       (LABEL_TAC "xy_in_axb") (LABEL_TAC "xy_in_ayb")) THENL
       [SUBGOAL_THEN
        `(p:A->real^2) y IN
          closure(inside(path_image gaxb UNION path_image gab))`
        (LABEL_TAC "y_in_closure") THENL
         [USE_THEN "xy_in_axb" (fun th ->
