        SUBGOAL_THEN
         `(p:A->real^2) y IN path_image gayb /\
          ~((p y) IN path_image gaxb) /\
          ~((p y) IN path_image gab)`
        STRIP_ASSUME_TAC THENL
         [USE_THEN "y_on_ayb_middle" MP_TAC THEN
          USE_THEN "axb_ayb_path" MP_TAC THEN
          USE_THEN "ayb_ab_path" MP_TAC THEN SET_TAC[];
          ALL_TAC] THEN
        MP_TAC(ISPECL
         [`gaxb:real^1->real^2`; `gayb:real^1->real^2`;
          `gab:real^1->real^2`; `(p:A->real^2) a`;
          `(p:A->real^2) b`; `(p:A->real^2) y`]
         CROSSCUT_OTHER_PATH_NOT_IN_CLOSURE) THEN
        ANTS_TAC THENL
         [ASM_SIMP_TAC[ARC_IMP_SIMPLE_PATH];
          DISCH_THEN(fun th ->
            USE_THEN "y_in_closure" (fun ith ->
              CONTR_TAC(MP (NOT_ELIM th) ith)))];
        SUBGOAL_THEN
        `(p:A->real^2) x IN
          closure(inside(path_image gayb UNION path_image gab))`
        (LABEL_TAC "x_in_closure") THENL
         [USE_THEN "xy_in_ayb" (fun th ->
            MATCH_MP_TAC(REWRITE_RULE[SUBSET]
             (MATCH_MP SUBSET_CLOSURE th))) THEN
          USE_THEN "x_closure" ACCEPT_TAC;
          ALL_TAC] THEN
        SUBGOAL_THEN
         `(p:A->real^2) x IN path_image gaxb /\
          ~((p x) IN path_image gayb) /\
          ~((p x) IN path_image gab)`
        STRIP_ASSUME_TAC THENL
         [USE_THEN "x_on_axb_middle" MP_TAC THEN
          USE_THEN "axb_ayb_path" MP_TAC THEN
          USE_THEN "ab_axb_path" MP_TAC THEN SET_TAC[];
          ALL_TAC] THEN
        MP_TAC(ISPECL
         [`gayb:real^1->real^2`; `gaxb:real^1->real^2`;
          `gab:real^1->real^2`; `(p:A->real^2) a`;
          `(p:A->real^2) b`; `(p:A->real^2) x`]
         CROSSCUT_OTHER_PATH_NOT_IN_CLOSURE) THEN
        ANTS_TAC THENL
         [ASM_SIMP_TAC[ARC_IMP_SIMPLE_PATH];
          DISCH_THEN(fun th ->
            USE_THEN "x_in_closure" (fun ith ->
              CONTR_TAC(MP (NOT_ELIM th) ith)))]];
      DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "xay_inside"
       (fun th -> MATCH_MP_TAC(REWRITE_RULE[SUBSET] th)) THEN
      USE_THEN "xay_image" (fun th ->
        USE_THEN "a_on_xay_middle"
         (ACCEPT_TAC o REWRITE_RULE[th]));
      REPEAT DISJ2_TAC THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "xby_inside"
       (fun th -> MATCH_MP_TAC(REWRITE_RULE[SUBSET] th)) THEN
