    DISJ1_TAC THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "axb_inside"
     (fun th -> MATCH_MP_TAC(REWRITE_RULE[SUBSET] th)) THEN
    USE_THEN "axb_image" (fun th ->
      USE_THEN "x_on_axb_middle"
