    DISJ2_TAC THEN DISJ1_TAC THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "ayb_inside"
     (fun th -> MATCH_MP_TAC(REWRITE_RULE[SUBSET] th)) THEN
    USE_THEN "ayb_image" (fun th ->
