let MAXIMAL_PLANAR_GRAPH_FACE_VERTICES_CARD_LE_3 = prove
 (`!V E p c k.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        (!G. E PSUBSET G /\
             G SUBSET complete_graph_edges V
             ==> ~planar_graph V G) /\
        k IN components
             ((:real^2) DIFF plane_graph_carrier V E p c)
        ==> CARD(plane_graph_face_vertices V E p c k) <= 3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding maximal component" THEN
  SUBGOAL_THEN
   `FINITE(plane_graph_face_vertices
      (V:A->bool) E (p:A->real^2) (c:(A->bool)->real^2->bool) k)`
  (LABEL_TAC "finite_face") THENL
   [MATCH_MP_TAC FINITE_PLANE_GRAPH_FACE_VERTICES THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[ARITH_RULE `n <= 3 <=> ~(4 <= n)`] THEN
  DISCH_THEN(LABEL_TAC "large_face") THEN
  MP_TAC(ISPECL
   [`4`; `plane_graph_face_vertices
      (V:A->bool) E (p:A->real^2)
      (c:(A->bool)->real^2->bool) k`]
   CHOOSE_SUBSET_STRONG) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC "@t. t_subset t_size"] THEN
  REMOVE_THEN "t_size" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE_CONV `t:A->bool HAS_SIZE 4`] THEN
  INTRO_TAC
   "@a b x y. xy_distinct bx_distinct by_distinct \
    ab_distinct ax_distinct ay_distinct t_eq" THEN
  USE_THEN "t_eq" SUBST_ALL_TAC THEN
  SUBGOAL_THEN
   `(a:A) IN plane_graph_face_vertices V E p c k /\
    (b:A) IN plane_graph_face_vertices V E p c k /\
    (x:A) IN plane_graph_face_vertices V E p c k /\
    (y:A) IN plane_graph_face_vertices V E p c k`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_face")
   (CONJUNCTS_THEN2 (LABEL_TAC "b_face")
    (CONJUNCTS_THEN2 (LABEL_TAC "x_face")
     (LABEL_TAC "y_face")))) THENL
   [USE_THEN "t_subset" MP_TAC THEN
    REWRITE_TAC[INSERT_SUBSET; SING_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((x:A) = b)` (LABEL_TAC "xb_distinct") THENL
   [ASM_REWRITE_TAC[EQ_SYM_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((y:A) = b)` (LABEL_TAC "yb_distinct") THENL
   [ASM_REWRITE_TAC[EQ_SYM_EQ];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `k:real^2->bool`]
   MAXIMAL_PLANAR_GRAPH_FACE_VERTICES_CLIQUE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(LABEL_TAC "clique")] THEN
  SUBGOAL_THEN
   `({a,b}:A->bool) IN E /\ {a,x} IN E /\ {x,b} IN E /\
    {a,y} IN E /\ {y,b} IN E /\ {x,y} IN E`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN
    USE_THEN "clique" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY
   (fun s ->
      USE_THEN s
       (ASSUME_TAC o CONJUNCT2 o
        REWRITE_RULE[plane_graph_face_vertices; IN_ELIM_THM]))
   ["a_face"; "b_face"; "x_face"; "y_face"] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `a:A`; `b:A`; `x:A`; `y:A`;
    `k:real^2->bool`]
   PLANE_GRAPH_EMBEDDING_K4_NOT_COFACIAL) THEN
  ASM_REWRITE_TAC[]);;

let embedding_vertex_obstacles = new_definition
 `embedding_vertex_obstacles
      (V:A->bool) (E:(A->bool)->bool)
      (p:A->real^2) (c:(A->bool)->real^2->bool) v =
        IMAGE p (V DELETE v) UNION
        UNIONS(IMAGE c {e | e IN E /\ ~(v IN e)})`;;

let COMPACT_EMBEDDING_VERTEX_OBSTACLES = prove
 (`!V E p c v.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c
        ==> compact(embedding_vertex_obstacles V E p c v)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[embedding_vertex_obstacles] THEN
  MATCH_MP_TAC COMPACT_UNION THEN CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_IMP_COMPACT THEN
    MATCH_MP_TAC FINITE_IMAGE THEN
    REWRITE_TAC[FINITE_DELETE] THEN
    ASM_MESON_TAC[finite_simple_graph];
    MATCH_MP_TAC COMPACT_UNIONS THEN CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_IMAGE THEN MATCH_MP_TAC FINITE_SUBSET THEN
      EXISTS_TAC `E:(A->bool)->bool` THEN
      CONJ_TAC THENL
       [ASM_MESON_TAC[finite_simple_graph];
        REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]];
      REWRITE_TAC[FORALL_IN_IMAGE; IN_ELIM_THM] THEN
      X_GEN_TAC `e:A->bool` THEN STRIP_TAC THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `e:A->bool`]
       PLANE_GRAPH_EMBEDDING_EDGE_COMPACT) THEN
      ASM_REWRITE_TAC[]]]);;

let EMBEDDING_VERTEX_NOT_IN_OBSTACLES = prove
 (`!V E p c v.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        v IN V
        ==> ~((p v) IN embedding_vertex_obstacles V E p c v)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN
   (CONJUNCTS_THEN2 (LABEL_TAC "graph")
    (CONJUNCTS_THEN2 (LABEL_TAC "embedding") (LABEL_TAC "vertex"))) THEN
  USE_THEN "embedding" MP_TAC THEN
  REWRITE_TAC[plane_graph_embedding] THEN
  INTRO_TAC "injective _ intersections _" THEN
  REWRITE_TAC[embedding_vertex_obstacles; IN_UNION; DE_MORGAN_THM] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[IN_IMAGE; IN_DELETE] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV] THEN ASM_MESON_TAC[];
    REWRITE_TAC[IN_UNIONS; EXISTS_IN_IMAGE; IN_ELIM_THM] THEN
    DISCH_THEN(X_CHOOSE_THEN `e:A->bool` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `((p:A->real^2) v) IN IMAGE p V` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`p:A->real^2`; `V:A->bool`; `v:A`] FUN_IN_IMAGE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REMOVE_THEN "intersections" (MP_TAC o SPEC `e:A->bool`) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "intersection") THEN
    SUBGOAL_THEN `((p:A->real^2) v) IN IMAGE p e` ASSUME_TAC THENL
     [USE_THEN "intersection" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[IN_INTER];
      ALL_TAC] THEN
    UNDISCH_TAC `((p:A->real^2) v) IN IMAGE p e` THEN
    REWRITE_TAC[IN_IMAGE] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A`
     (CONJUNCTS_THEN2 (LABEL_TAC "member") (LABEL_TAC "image"))) THEN
    USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    INTRO_TAC "_ _ edge_property" THEN
    REMOVE_THEN "edge_property" (MP_TAC o SPEC `e:A->bool`) THEN
    ASM_REWRITE_TAC[] THEN INTRO_TAC "subset _" THEN
    SUBGOAL_THEN `(u:A) IN V` ASSUME_TAC THENL
     [REMOVE_THEN "subset" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
      DISCH_THEN(MP_TAC o SPEC `u:A`) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `u:A = v` (LABEL_TAC "same") THENL
     [USE_THEN "injective" (fun th ->
       MATCH_MP_TAC(SPECL [`u:A`; `v:A`]
        (CONJUNCT2(REWRITE_RULE[INJ] th)))) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "same" SUBST_ALL_TAC THEN ASM_MESON_TAC[]]);;

let EMBEDDING_VERTEX_OBSTACLE_BALL = prove
 (`!V E p c v.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        v IN V
        ==> ?r. &0 < r /\
                ball(p v,r) INTER
                embedding_vertex_obstacles V E p c v = {}`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`embedding_vertex_obstacles
       (V:A->bool) E (p:A->real^2) c v`;
    `(p:A->real^2) v`]
   SEPARATE_POINT_CLOSED) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC COMPACT_IMP_CLOSED THEN
      MATCH_MP_TAC COMPACT_EMBEDDING_VERTEX_OBSTACLES THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC EMBEDDING_VERTEX_NOT_IN_OBSTACLES THEN
      ASM_REWRITE_TAC[]];
    DISCH_THEN(X_CHOOSE_THEN `r:real` STRIP_ASSUME_TAC)] THEN
  EXISTS_TAC `r:real` THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[EXTENSION; IN_INTER; NOT_IN_EMPTY; IN_BALL] THEN
  ASM_MESON_TAC[REAL_NOT_LT]);;

let EMBEDDING_VERTEX_OBSTACLE_BALLS = prove
 (`!V E p c.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c
        ==> ?r:A->real.
              !v. v IN V
                  ==> &0 < r v /\
                      ball(p v,r v) INTER
                      embedding_vertex_obstacles V E p c v = {}`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[GSYM SKOLEM_THM] THEN
  X_GEN_TAC `v:A` THEN ASM_CASES_TAC `(v:A) IN V` THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `v:A`]
     EMBEDDING_VERTEX_OBSTACLE_BALL) THEN
    ASM_REWRITE_TAC[];
    EXISTS_TAC `&1` THEN ASM_REWRITE_TAC[]]);;

let EMBEDDING_VERTEX_DISJOINT_BALLS = prove
 (`!V E p c.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c
        ==> ?r:A->real.
              (!v. v IN V
                   ==> &0 < r v /\
                       ball(p v,r v) INTER
                       embedding_vertex_obstacles V E p c v = {}) /\
              (!v w. v IN V /\ w IN V /\ ~(v = w)
                     ==> DISJOINT (cball(p v,r v)) (cball(p w,r w)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`]
   EMBEDDING_VERTEX_OBSTACLE_BALLS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `q:A->real` (LABEL_TAC "balls")) THEN
  EXISTS_TAC `\v:A. q v / &3` THEN CONJ_TAC THENL
   [X_GEN_TAC `v:A` THEN DISCH_TAC THEN
    USE_THEN "balls" (fun th ->
      MP_TAC(MATCH_MP (SPEC `v:A` th) (ASSUME `(v:A) IN V`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "positive")
     (LABEL_TAC "clear")) THEN
    CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      SUBGOAL_THEN
       `ball((p:A->real^2) v,q v / &3) SUBSET ball(p v,q v)`
      ASSUME_TAC THENL
       [REWRITE_TAC[SUBSET; IN_BALL] THEN ASM_REAL_ARITH_TAC;
        USE_THEN "clear" MP_TAC THEN ASM SET_TAC[]]];
    MAP_EVERY X_GEN_TAC [`v:A`; `w:A`] THEN STRIP_TAC THEN
    USE_THEN "balls" (fun th ->
      MP_TAC(MATCH_MP (SPEC `v:A` th) (ASSUME `(v:A) IN V`))) THEN
    USE_THEN "balls" (fun th ->
      MP_TAC(MATCH_MP (SPEC `w:A` th) (ASSUME `(w:A) IN V`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "wpositive")
     (LABEL_TAC "wclear")) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "vpositive")
     (LABEL_TAC "vclear")) THEN
    SUBGOAL_THEN
     `((p:A->real^2) w) IN
      embedding_vertex_obstacles V E p c v`
    ASSUME_TAC THENL
     [REWRITE_TAC[embedding_vertex_obstacles; IN_UNION] THEN
      DISJ1_TAC THEN MATCH_MP_TAC(ISPECL
       [`p:A->real^2`; `(V DELETE v):A->bool`; `w:A`] FUN_IN_IMAGE) THEN
      ASM_REWRITE_TAC[IN_DELETE];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `((p:A->real^2) v) IN
      embedding_vertex_obstacles V E p c w`
    ASSUME_TAC THENL
     [REWRITE_TAC[embedding_vertex_obstacles; IN_UNION] THEN
      DISJ1_TAC THEN MATCH_MP_TAC(ISPECL
       [`p:A->real^2`; `(V DELETE w):A->bool`; `v:A`] FUN_IN_IMAGE) THEN
      ASM_REWRITE_TAC[IN_DELETE];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((p:A->real^2) w IN ball(p v,q v))`
    ASSUME_TAC THENL
     [USE_THEN "vclear" MP_TAC THEN ASM SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((p:A->real^2) v IN ball(p w,q w))`
    ASSUME_TAC THENL
     [USE_THEN "wclear" MP_TAC THEN ASM SET_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY; IN_CBALL] THEN
    X_GEN_TAC `x:real^2` THEN STRIP_TAC THEN
    MP_TAC(ISPECL
     [`(p:A->real^2) v`; `x:real^2`; `(p:A->real^2) w`]
     DIST_TRIANGLE) THEN
    MP_TAC(ISPECL [`(p:A->real^2) w`; `x:real^2`] DIST_SYM) THEN
    MP_TAC(ISPECL
     [`(p:A->real^2) w`; `(p:A->real^2) v`] DIST_SYM) THEN
    RULE_ASSUM_TAC(REWRITE_RULE[IN_BALL; REAL_NOT_LT]) THEN
    ASM_REAL_ARITH_TAC]);;

let EMBEDDING_VERTEX_DISJOINT_CLOSED_BALLS = prove
 (`!V E p c.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c
        ==> ?r:A->real.
              (!v. v IN V
                   ==> &0 < r v /\
                       cball(p v,r v) INTER
                       embedding_vertex_obstacles V E p c v = {}) /\
              (!v w. v IN V /\ w IN V /\ ~(v = w)
                     ==> DISJOINT
                          (cball(p v,r v)) (cball(p w,r w)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`]
   EMBEDDING_VERTEX_DISJOINT_BALLS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@q. clear disjoint" THEN
  EXISTS_TAC `\v:A. q v / &2` THEN CONJ_TAC THENL
   [X_GEN_TAC `v:A` THEN DISCH_TAC THEN
    USE_THEN "clear" (fun th ->
      MP_TAC(MATCH_MP (SPEC `v:A` th) (ASSUME `(v:A) IN V`))) THEN
    INTRO_TAC "positive clear_v" THEN CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      SUBGOAL_THEN
       `cball((p:A->real^2) v,q v / &2) SUBSET ball(p v,q v)`
      (LABEL_TAC "subset") THENL
       [REWRITE_TAC[SUBSET; IN_CBALL; IN_BALL] THEN ASM_REAL_ARITH_TAC;
        USE_THEN "subset" MP_TAC THEN USE_THEN "clear_v" MP_TAC THEN
        SET_TAC[]]];
    MAP_EVERY X_GEN_TAC [`v:A`; `w:A`] THEN
    INTRO_TAC "v w distinct" THEN
    SUBGOAL_THEN
     `DISJOINT (cball((p:A->real^2) v,q v))
               (cball(p w,q w))`
    (LABEL_TAC "large_disjoint") THENL
     [USE_THEN "disjoint" (fun th ->
        MATCH_MP_TAC(SPECL [`v:A`; `w:A`] th)) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `cball((p:A->real^2) v,q v / &2) SUBSET cball(p v,q v)`
    (LABEL_TAC "v_subset") THENL
     [USE_THEN "clear" (fun th ->
        MP_TAC(MATCH_MP (SPEC `v:A` th) (ASSUME `(v:A) IN V`))) THEN
      INTRO_TAC "positive _" THEN
      REWRITE_TAC[SUBSET; IN_CBALL] THEN ASM_REAL_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `cball((p:A->real^2) w,q w / &2) SUBSET cball(p w,q w)`
    (LABEL_TAC "w_subset") THENL
     [USE_THEN "clear" (fun th ->
        MP_TAC(MATCH_MP (SPEC `w:A` th) (ASSUME `(w:A) IN V`))) THEN
      INTRO_TAC "positive _" THEN
      REWRITE_TAC[SUBSET; IN_CBALL] THEN ASM_REAL_ARITH_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    X_GEN_TAC `x:real^2` THEN INTRO_TAC "xv xw" THEN
    SUBGOAL_THEN
     `(x:real^2) IN
      cball((p:A->real^2) (v:A),(q:A->real) v)`
    (LABEL_TAC "xv_large") THENL
     [USE_THEN "v_subset" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
      DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN
      ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x:real^2) IN
      cball((p:A->real^2) (w:A),(q:A->real) w)`
    (LABEL_TAC "xw_large") THENL
     [USE_THEN "w_subset" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
      DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN
      ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "large_disjoint" MP_TAC THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN ASM_REWRITE_TAC[]]);;

let ARC_SUBPATH_TO_FRONTIER = prove
 (`!g:real^1->real^N s.
        arc g /\
        pathstart g IN interior s /\
        ~(pathfinish g IN s)
        ==> ?u. u IN interval[vec 0,vec 1] /\
                ~(u = vec 0) /\
                arc(subpath (vec 0) u g) /\
                pathfinish(subpath (vec 0) u g) IN frontier s /\
                (path_image(subpath (vec 0) u g) DELETE
                 pathfinish(subpath (vec 0) u g)) SUBSET interior s /\
                path_image(subpath (vec 0) u g) SUBSET path_image g`,
  REPEAT GEN_TAC THEN
  DISCH_THEN
   (CONJUNCTS_THEN2 (LABEL_TAC "arc")
    (CONJUNCTS_THEN2 (LABEL_TAC "start") (LABEL_TAC "finish"))) THEN
  MP_TAC(ISPECL [`g:real^1->real^N`; `s:real^N->bool`]
    SUBPATH_TO_FRONTIER) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "arc" ACCEPT_TAC;
      MATCH_MP_TAC(REWRITE_RULE[SUBSET] INTERIOR_SUBSET) THEN
      USE_THEN "start" ACCEPT_TAC;
      USE_THEN "finish" ACCEPT_TAC];
    DISCH_THEN(X_CHOOSE_THEN `u:real^1`
     (CONJUNCTS_THEN2 (LABEL_TAC "parameter")
      (CONJUNCTS_THEN2 (LABEL_TAC "boundary")
       (LABEL_TAC "inside"))))] THEN
  SUBGOAL_THEN `~(u:real^1 = vec 0)` (LABEL_TAC "nonzero") THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN
     `(g:real^1->real^N) (vec 0) IN interior(s:real^N->bool)`
    ASSUME_TAC THENL
     [USE_THEN "start" MP_TAC THEN REWRITE_TAC[pathstart];
      UNDISCH_TAC
       `pathfinish(subpath (vec 0) u (g:real^1->real^N)) IN
        frontier(s:real^N->bool)` THEN
      ASM_REWRITE_TAC[PATHFINISH_SUBPATH; frontier; IN_DIFF]];
    ALL_TAC] THEN
  EXISTS_TAC `u:real^1` THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC ARC_SUBPATH_ARC THEN
    ASM_REWRITE_TAC[ENDS_IN_UNIT_INTERVAL] THEN ASM_MESON_TAC[];
    MATCH_MP_TAC PATH_IMAGE_SUBPATH_SUBSET THEN
    ASM_REWRITE_TAC[ENDS_IN_UNIT_INTERVAL] THEN
    MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "arc" ACCEPT_TAC]);;

let POLYGONAL_ARC_SUBPATH_TO_FRONTIER = prove
 (`!g:real^1->real^N. !s:real^N->bool.
        polygonal_arc g /\
        pathstart g IN interior s /\
        ~(pathfinish g IN s)
        ==> ?h. polygonal_arc h /\
                path_image h SUBSET path_image g /\
                pathstart h = pathstart g /\
                pathfinish h IN frontier s /\
                (path_image h DELETE pathfinish h) SUBSET interior s`,
  REPEAT GEN_TAC THEN INTRO_TAC "polygonal start finish" THEN
  MP_TAC(ISPECL [`g:real^1->real^N`; `s:real^N->bool`]
    ARC_SUBPATH_TO_FRONTIER) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC POLYGONAL_ARC_IMP_ARC THEN
    USE_THEN "polygonal" ACCEPT_TAC;
    INTRO_TAC
     "@u. parameter nonzero subarc boundary inside image_subset"] THEN
  EXISTS_TAC `subpath (vec 0) u (g:real^1->real^N)` THEN
  ASM_REWRITE_TAC[PATHSTART_SUBPATH; pathstart] THEN
  MATCH_MP_TAC POLYGONAL_ARC_SUBPATH THEN
  ASM_REWRITE_TAC[ENDS_IN_UNIT_INTERVAL] THEN ASM_MESON_TAC[]);;

let ARC_MIDDLE_OUTSIDE_DISJOINT_CBALLS = prove
 (`!g:real^1->real^N a b r s.
        arc g /\
        pathstart g = a /\
        pathfinish g = b /\
        &0 < r /\
        &0 < s /\
        DISJOINT (cball(a,r)) (cball(b,s))
        ==> ?h. arc h /\
                path_image h SUBSET path_image g /\
                pathstart h IN sphere(a,r) /\
                pathfinish h IN sphere(b,s) /\
                (path_image h DELETE pathstart h) SUBSET
                ((:real^N) DIFF cball(a,r)) /\
                (path_image h DELETE pathfinish h) SUBSET
                ((:real^N) DIFF cball(b,s))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN
   (CONJUNCTS_THEN2 (LABEL_TAC "arc")
    (CONJUNCTS_THEN2 (LABEL_TAC "start")
     (CONJUNCTS_THEN2 (LABEL_TAC "finish")
      (CONJUNCTS_THEN2 (LABEL_TAC "rpositive")
       (CONJUNCTS_THEN2 (LABEL_TAC "spositive")
        (LABEL_TAC "disjoint")))))) THEN
  SUBGOAL_THEN
   `open((:real^N) DIFF cball(a,r))`
  (LABEL_TAC "tail_open") THENL
   [MATCH_MP_TAC OPEN_DIFF THEN REWRITE_TAC[OPEN_UNIV; CLOSED_CBALL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `open((:real^N) DIFF cball(b,s))`
  (LABEL_TAC "head_open") THENL
   [MATCH_MP_TAC OPEN_DIFF THEN REWRITE_TAC[OPEN_UNIV; CLOSED_CBALL];
    ALL_TAC] THEN
  SUBGOAL_THEN `(b:real^N) IN cball(b,s)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[CENTRE_IN_CBALL; REAL_LT_IMP_LE];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((b:real^N) IN cball(a,r))` ASSUME_TAC THENL
   [USE_THEN "disjoint" MP_TAC THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(b:real^N) IN interior((:real^N) DIFF cball(a,r))`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[INTERIOR_OPEN; IN_DIFF; IN_UNIV];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((a:real^N) IN ((:real^N) DIFF cball(a,r)))`
  ASSUME_TAC THENL
   [REWRITE_TAC[IN_DIFF; IN_UNIV; CENTRE_IN_CBALL] THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`reversepath(g:real^1->real^N)`;
    `(:real^N) DIFF cball(a,r)`]
   ARC_SUBPATH_TO_FRONTIER) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[ARC_REVERSEPATH; PATHSTART_REVERSEPATH;
                 PATHFINISH_REVERSEPATH];
    INTRO_TAC
     "@t. tail_parameter tail_nonzero tail_arc tail_boundary \
          tail_outside tail_subset"] THEN
  ABBREV_TAC
   `q:real^1->real^N =
      reversepath(subpath (vec 0) t (reversepath g))` THEN
  SUBGOAL_THEN `arc(q:real^1->real^N)` (LABEL_TAC "q_arc") THENL
   [EXPAND_TAC "q" THEN ASM_SIMP_TAC[ARC_REVERSEPATH];
    ALL_TAC] THEN
  SUBGOAL_THEN `pathfinish(q:real^1->real^N) = b`
  (LABEL_TAC "q_finish") THENL
   [EXPAND_TAC "q" THEN
    REWRITE_TAC[PATHFINISH_REVERSEPATH; PATHSTART_SUBPATH;
                reversepath; VECTOR_SUB_RZERO] THEN
    USE_THEN "finish" MP_TAC THEN REWRITE_TAC[pathfinish];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `pathstart(q:real^1->real^N) IN sphere(a,r)`
  (LABEL_TAC "q_start") THENL
   [EXPAND_TAC "q" THEN
    REWRITE_TAC[PATHSTART_REVERSEPATH] THEN
    USE_THEN "tail_boundary" MP_TAC THEN
    REWRITE_TAC[FRONTIER_COMPLEMENT; FRONTIER_CBALL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(path_image(q:real^1->real^N) DELETE pathstart q) SUBSET
    ((:real^N) DIFF cball(a,r))`
  (LABEL_TAC "q_outside") THENL
   [EXPAND_TAC "q" THEN
    REWRITE_TAC[PATH_IMAGE_REVERSEPATH; PATHSTART_REVERSEPATH] THEN
    UNDISCH_TAC
     `(path_image(subpath (vec 0) t (reversepath g)) DELETE
       pathfinish(subpath (vec 0) t (reversepath g))) SUBSET
      interior((:real^N) DIFF cball(a,r))` THEN
    ASM_SIMP_TAC[INTERIOR_OPEN];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `path_image(q:real^1->real^N) SUBSET path_image g`
  (LABEL_TAC "q_subset") THENL
   [EXPAND_TAC "q" THEN
    USE_THEN "tail_subset" MP_TAC THEN
    REWRITE_TAC[PATH_IMAGE_REVERSEPATH];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `pathstart(q:real^1->real^N) IN cball(a,r)`
  ASSUME_TAC THENL
   [USE_THEN "q_start" MP_TAC THEN
    REWRITE_TAC[IN_SPHERE; IN_CBALL] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(pathstart(q:real^1->real^N) IN cball(b,s))`
  ASSUME_TAC THENL
   [USE_THEN "disjoint" MP_TAC THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `pathstart(q:real^1->real^N) IN
    interior((:real^N) DIFF cball(b,s))`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[INTERIOR_OPEN; IN_DIFF; IN_UNIV];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(pathfinish(q:real^1->real^N) IN
      ((:real^N) DIFF cball(b,s)))`
  ASSUME_TAC THENL
   [ASM_REWRITE_TAC[IN_DIFF; IN_UNIV];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`q:real^1->real^N`; `(:real^N) DIFF cball(b,s)`]
   ARC_SUBPATH_TO_FRONTIER) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC
     "@u. middle_parameter middle_nonzero middle_arc head_boundary \
          head_outside middle_subset"] THEN
  EXISTS_TAC `subpath (vec 0) u (q:real^1->real^N)` THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "middle_arc" ACCEPT_TAC;
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `path_image(q:real^1->real^N)` THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[PATHSTART_SUBPATH] THEN
    USE_THEN "q_start" MP_TAC THEN REWRITE_TAC[pathstart];
    USE_THEN "head_boundary" MP_TAC THEN
    REWRITE_TAC[FRONTIER_COMPLEMENT; FRONTIER_CBALL];
    SUBGOAL_THEN
     `pathstart(subpath (vec 0) u q) = pathstart(q:real^1->real^N)`
    ASSUME_TAC THENL
     [REWRITE_TAC[PATHSTART_SUBPATH; pathstart];
      USE_THEN "middle_subset" MP_TAC THEN
      USE_THEN "q_outside" MP_TAC THEN ASM SET_TAC[]];
    UNDISCH_TAC
     `(path_image(subpath (vec 0) u q) DELETE
       pathfinish(subpath (vec 0) u q)) SUBSET
     interior((:real^N) DIFF cball(b,s))` THEN
    ASM_SIMP_TAC[INTERIOR_OPEN]]);;

let POLYGONAL_ARC_MIDDLE_OUTSIDE_DISJOINT_CBALLS = prove
 (`!g:real^1->real^N a b r s.
        polygonal_arc g /\
        pathstart g IN cball(a,r) /\
        pathfinish g IN cball(b,s) /\
        &0 < r /\
        &0 < s /\
        DISJOINT (cball(a,r)) (cball(b,s))
        ==> ?h. polygonal_arc h /\
                path_image h SUBSET path_image g /\
                pathstart h IN sphere(a,r) /\
                pathfinish h IN sphere(b,s) /\
                (path_image h DELETE pathstart h) SUBSET
                ((:real^N) DIFF cball(a,r)) /\
                (path_image h DELETE pathfinish h) SUBSET
                ((:real^N) DIFF cball(b,s))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "polygonal start_in finish_in rpositive spositive disjoint" THEN
  SUBGOAL_THEN
   `open((:real^N) DIFF cball(a,r))`
  (LABEL_TAC "tail_open") THENL
   [MATCH_MP_TAC OPEN_DIFF THEN REWRITE_TAC[OPEN_UNIV; CLOSED_CBALL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `open((:real^N) DIFF cball(b,s))`
  (LABEL_TAC "head_open") THENL
   [MATCH_MP_TAC OPEN_DIFF THEN REWRITE_TAC[OPEN_UNIV; CLOSED_CBALL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(pathfinish(g:real^1->real^N) IN cball(a,r))`
  (LABEL_TAC "finish_outside") THENL
   [USE_THEN "disjoint" MP_TAC THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `pathfinish(g:real^1->real^N) IN
    interior((:real^N) DIFF cball(a,r))`
  (LABEL_TAC "finish_in_exterior") THENL
   [ASM_SIMP_TAC[INTERIOR_OPEN; IN_DIFF; IN_UNIV];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(pathstart(g:real^1->real^N) IN
      ((:real^N) DIFF cball(a,r)))`
  (LABEL_TAC "start_not_exterior") THENL
   [ASM_REWRITE_TAC[IN_DIFF; IN_UNIV];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`reversepath(g:real^1->real^N)`;
    `(:real^N) DIFF cball(a,r)`]
   POLYGONAL_ARC_SUBPATH_TO_FRONTIER) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[POLYGONAL_ARC_REVERSEPATH; PATHSTART_REVERSEPATH;
                 PATHFINISH_REVERSEPATH];
    INTRO_TAC
     "@h. h_polygonal h_subset h_start h_boundary h_outside"] THEN
  ABBREV_TAC `q:real^1->real^N = reversepath h` THEN
  SUBGOAL_THEN `polygonal_arc(q:real^1->real^N)`
  (LABEL_TAC "q_polygonal") THENL
   [EXPAND_TAC "q" THEN MATCH_MP_TAC POLYGONAL_ARC_REVERSEPATH THEN
    USE_THEN "h_polygonal" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `pathfinish(q:real^1->real^N) = pathfinish g`
  (LABEL_TAC "q_finish") THENL
   [EXPAND_TAC "q" THEN
    ASM_REWRITE_TAC[PATHFINISH_REVERSEPATH; PATHSTART_REVERSEPATH];
    ALL_TAC] THEN
  SUBGOAL_THEN `pathstart(q:real^1->real^N) IN sphere(a,r)`
  (LABEL_TAC "q_start") THENL
   [EXPAND_TAC "q" THEN REWRITE_TAC[PATHSTART_REVERSEPATH] THEN
    USE_THEN "h_boundary" MP_TAC THEN
    REWRITE_TAC[FRONTIER_COMPLEMENT; FRONTIER_CBALL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(path_image(q:real^1->real^N) DELETE pathstart q) SUBSET
    ((:real^N) DIFF cball(a,r))`
  (LABEL_TAC "q_outside") THENL
   [EXPAND_TAC "q" THEN
    REWRITE_TAC[PATH_IMAGE_REVERSEPATH; PATHSTART_REVERSEPATH] THEN
    UNDISCH_TAC
     `(path_image(h:real^1->real^N) DELETE pathfinish h) SUBSET
      interior((:real^N) DIFF cball(a,r))` THEN
    ASM_SIMP_TAC[INTERIOR_OPEN];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `path_image(q:real^1->real^N) SUBSET path_image g`
  (LABEL_TAC "q_subset") THENL
   [EXPAND_TAC "q" THEN
    REWRITE_TAC[PATH_IMAGE_REVERSEPATH] THEN
    USE_THEN "h_subset" MP_TAC THEN
    REWRITE_TAC[PATH_IMAGE_REVERSEPATH];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `pathstart(q:real^1->real^N) IN cball(a,r)`
  (LABEL_TAC "q_start_in") THENL
   [USE_THEN "q_start" MP_TAC THEN
