   POLYGONAL_ARC_SUBPATH_TO_FRONTIER) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC
     "@k. k_polygonal k_subset k_start k_boundary k_outside"] THEN
  EXISTS_TAC `k:real^1->real^N` THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "k_polygonal" ACCEPT_TAC;
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `path_image(q:real^1->real^N)` THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    USE_THEN "k_boundary" MP_TAC THEN
    REWRITE_TAC[FRONTIER_COMPLEMENT; FRONTIER_CBALL];
    USE_THEN "k_subset" MP_TAC THEN USE_THEN "q_outside" MP_TAC THEN
    ASM SET_TAC[];
    UNDISCH_TAC
     `(path_image(k:real^1->real^N) DELETE pathfinish k) SUBSET
      interior((:real^N) DIFF cball(b,s))` THEN
    ASM_SIMP_TAC[INTERIOR_OPEN]]);;

let ARC_JOIN_LINEPATH_FROM_SPHERE = prove
 (`!h:real^1->real^N a r.
        arc h /\
        &0 < r /\
        pathstart h IN sphere(a,r) /\
        (path_image h DELETE pathstart h) SUBSET
        ((:real^N) DIFF cball(a,r))
        ==> arc(linepath(a,pathstart h) ++ h)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN
   (CONJUNCTS_THEN2 (LABEL_TAC "arc")
    (CONJUNCTS_THEN2 (LABEL_TAC "positive")
     (CONJUNCTS_THEN2 (LABEL_TAC "start")
      (LABEL_TAC "outside")))) THEN
  SUBGOAL_THEN `~((a:real^N) = pathstart h)` ASSUME_TAC THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "start" MP_TAC THEN
    REWRITE_TAC[IN_SPHERE; DIST_REFL] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `segment[a:real^N,pathstart h] SUBSET cball(a,r)`
  (LABEL_TAC "segment") THENL
   [MATCH_MP_TAC SEGMENT_SUBSET_CONVEX THEN
    REWRITE_TAC[CONVEX_CBALL; CENTRE_IN_CBALL] THEN
    CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      USE_THEN "start" MP_TAC THEN
      REWRITE_TAC[IN_SPHERE; IN_CBALL] THEN REAL_ARITH_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC ARC_JOIN THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[ARC_LINEPATH_EQ];
    USE_THEN "arc" ACCEPT_TAC;
    REWRITE_TAC[PATHFINISH_LINEPATH];
    REWRITE_TAC[PATH_IMAGE_LINEPATH; PATHSTART_LINEPATH;
                SUBSET; IN_INTER; IN_SING] THEN
    X_GEN_TAC `x:real^N` THEN STRIP_TAC THEN
    ASM_CASES_TAC `x:real^N = pathstart h` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(x:real^N) IN cball(a,r)` ASSUME_TAC THENL
     [USE_THEN "segment" (fun th ->
        MATCH_MP_TAC(REWRITE_RULE[SUBSET] th)) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x:real^N) IN ((:real^N) DIFF cball(a,r))`
    ASSUME_TAC THENL
     [USE_THEN "outside" (fun th ->
        MATCH_MP_TAC(REWRITE_RULE[SUBSET] th)) THEN
      ASM_REWRITE_TAC[IN_DELETE];
      UNDISCH_TAC `(x:real^N) IN ((:real^N) DIFF cball(a,r))` THEN
      ASM_REWRITE_TAC[IN_DIFF; IN_UNIV]]]);;

