    X_GEN_TAC `x:real^N` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(x:real^N) IN cball(a,r)` ASSUME_TAC THENL
     [USE_THEN "tail_segment" (fun th ->
        MATCH_MP_TAC(REWRITE_RULE[SUBSET] th)) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_TAC THEN
    UNDISCH_TAC `DISJOINT (cball(a:real^N,r)) (cball(b,s))` THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `x:real^N`) THEN ASM_REWRITE_TAC[];
