  (LABEL_TAC "q_image") THENL
   [EXPAND_TAC "q" THEN
    ASM_SIMP_TAC[PATH_IMAGE_JOIN; PATHFINISH_LINEPATH;
                 PATH_IMAGE_LINEPATH];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(path_image(q:real^1->real^N) DELETE pathfinish q) SUBSET
    ((:real^N) DIFF cball(b,s))`
  (LABEL_TAC "q_outside") THENL
   [REWRITE_TAC[SUBSET; IN_DELETE] THEN
    X_GEN_TAC `x:real^N` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `(x:real^N) IN segment[a,pathstart h] \/
      x IN path_image h`
    DISJ_CASES_TAC THENL
     [USE_THEN "q_image" (fun th ->
        UNDISCH_TAC `(x:real^N) IN path_image q` THEN
        ONCE_REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_UNION];
      USE_THEN "tail_clear" (fun th ->
        MATCH_MP_TAC(REWRITE_RULE[SUBSET] th)) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "head_outside" (fun th ->
        MATCH_MP_TAC(REWRITE_RULE[SUBSET] th)) THEN
      REWRITE_TAC[IN_DELETE] THEN CONJ_TAC THENL
       [ASM_REWRITE_TAC[];
        USE_THEN "q_finish" MP_TAC THEN ASM_MESON_TAC[]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `arc(q ++ linepath(pathfinish q,b):real^1->real^N)`
  MP_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`q:real^1->real^N`; `b:real^N`; `s:real`]
     ARC_JOIN_LINEPATH_TO_SPHERE) THEN
    ASM_REWRITE_TAC[];
    EXPAND_TAC "q" THEN ASM_REWRITE_TAC[]]);;

let POLYGONAL_ARC_RADIALIZE_BETWEEN_DISJOINT_CBALLS = prove
 (`!h:real^1->real^N a b r s.
        polygonal_arc h /\
        &0 < r /\
        &0 < s /\
        DISJOINT (cball(a,r)) (cball(b,s)) /\
        pathstart h IN sphere(a,r) /\
        pathfinish h IN sphere(b,s) /\
        (path_image h DELETE pathstart h) SUBSET
        ((:real^N) DIFF cball(a,r)) /\
        (path_image h DELETE pathfinish h) SUBSET
        ((:real^N) DIFF cball(b,s))
        ==> polygonal_arc
             ((linepath(a,pathstart h) ++ h) ++
              linepath(pathfinish h,b))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "polygonal rpositive spositive disjoint start finish \
             tail_outside head_outside" THEN
  SUBGOAL_THEN `arc(h:real^1->real^N)` (LABEL_TAC "arc") THENL
   [MATCH_MP_TAC POLYGONAL_ARC_IMP_ARC THEN
    USE_THEN "polygonal" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((a:real^N) = pathstart h)`
  (LABEL_TAC "tail_distinct") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN USE_THEN "start" MP_TAC THEN
    REWRITE_TAC[IN_SPHERE; DIST_REFL] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(pathfinish h = (b:real^N))`
  (LABEL_TAC "head_distinct") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN USE_THEN "finish" MP_TAC THEN
    REWRITE_TAC[IN_SPHERE; DIST_REFL] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  ABBREV_TAC `g:real^1->real^N = linepath(a,pathstart h) ++ h` THEN
  SUBGOAL_THEN `arc(g:real^1->real^N)` (LABEL_TAC "g_arc") THENL
   [EXPAND_TAC "g" THEN
    MATCH_MP_TAC(ISPECL
     [`h:real^1->real^N`; `a:real^N`; `r:real`]
     ARC_JOIN_LINEPATH_FROM_SPHERE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `polygonal_arc(g:real^1->real^N)`
  (LABEL_TAC "g_polygonal") THENL
   [MATCH_MP_TAC(ISPECL
     [`linepath(a:real^N,pathstart h)`; `h:real^1->real^N`;
      `g:real^1->real^N`]
     POLYGONAL_ARC_SUBSET_UNION) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC POLYGONAL_ARC_LINEPATH THEN ASM_REWRITE_TAC[];
      EXPAND_TAC "g" THEN
      ASM_SIMP_TAC[PATH_IMAGE_JOIN; PATHFINISH_LINEPATH; SUBSET_REFL]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `arc(g ++ linepath(pathfinish h,b):real^1->real^N)`
  (LABEL_TAC "full_arc") THENL
   [EXPAND_TAC "g" THEN
    MATCH_MP_TAC(ISPECL
     [`h:real^1->real^N`; `a:real^N`; `b:real^N`;
      `r:real`; `s:real`]
     ARC_RADIALIZE_BETWEEN_DISJOINT_CBALLS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`g:real^1->real^N`;
    `linepath(pathfinish(h:real^1->real^N),(b:real^N)):
       real^1->real^N`;
    `g ++ linepath(pathfinish h,b):real^1->real^N`]
   POLYGONAL_ARC_SUBSET_UNION) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC POLYGONAL_ARC_LINEPATH THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN `pathfinish(g:real^1->real^N) = pathfinish h`
    (LABEL_TAC "g_finish") THENL
     [EXPAND_TAC "g" THEN REWRITE_TAC[PATHFINISH_JOIN];
      ASM_SIMP_TAC[PATH_IMAGE_JOIN; PATHSTART_LINEPATH;
                   PATH_IMAGE_LINEPATH; SUBSET_REFL]]]);;

let RADIAL_SEGMENTS_INTER = prove
 (`!a x y:real^N. !r.
        x IN sphere(a,r) /\
        y IN sphere(a,r) /\
        ~(x = y)
        ==> segment[a,x] INTER segment[a,y] = {a}`,
  REPEAT GEN_TAC THEN INTRO_TAC "x_sphere y_sphere distinct" THEN
  GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [SEGMENT_SYM] THEN
  MATCH_MP_TAC INTER_SEGMENT THEN
  ASM_CASES_TAC `collinear{x:real^N,a,y}` THENL
   [DISJ1_TAC THEN REWRITE_TAC[GSYM BETWEEN_IN_SEGMENT] THEN
    USE_THEN "x_sphere" MP_TAC THEN USE_THEN "y_sphere" MP_TAC THEN
    UNDISCH_TAC `collinear{x:real^N,a,y}` THEN
    REWRITE_TAC[COLLINEAR_BETWEEN_CASES; IN_SPHERE; between] THEN
    REWRITE_TAC[DIST_SYM] THEN
    MP_TAC(ISPECL [`x:real^N`; `y:real^N`] DIST_POS_LT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "first")
     (DISJ_CASES_THEN2 (LABEL_TAC "middle") (LABEL_TAC "last"))) THEN
    REPEAT DISCH_TAC THEN ASM_REAL_ARITH_TAC;
    ASM_REWRITE_TAC[]]);;

let RADIAL_SEGMENT_SUBSET_CBALL = prove
 (`!a x:real^N. !r.
        &0 <= r /\ x IN sphere(a,r)
        ==> segment[a,x] SUBSET cball(a,r)`,
  REPEAT GEN_TAC THEN INTRO_TAC "nonnegative sphere" THEN
  MATCH_MP_TAC SEGMENT_SUBSET_CONVEX THEN
  REWRITE_TAC[CONVEX_CBALL; CENTRE_IN_CBALL] THEN
  ASM_REWRITE_TAC[] THEN USE_THEN "sphere" MP_TAC THEN
  REWRITE_TAC[IN_SPHERE; IN_CBALL] THEN REAL_ARITH_TAC);;

let RADIAL_SEGMENT_INTER_SPHERE = prove
 (`!a x:real^N. !r.
        x IN sphere(a,r)
        ==> segment[a,x] INTER sphere(a,r) = {x}`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "x_sphere") THEN
  REWRITE_TAC[EXTENSION; IN_INTER; IN_SING] THEN
  X_GEN_TAC `y:real^N` THEN EQ_TAC THENL
   [INTRO_TAC "segment y_sphere" THEN
    SUBGOAL_THEN `between (y:real^N) (a,x)`
    (LABEL_TAC "between") THENL
     [USE_THEN "segment" MP_TAC THEN
      REWRITE_TAC[BETWEEN_IN_SEGMENT];
      ALL_TAC] THEN
    USE_THEN "between" MP_TAC THEN
    USE_THEN "x_sphere" MP_TAC THEN USE_THEN "y_sphere" MP_TAC THEN
    REWRITE_TAC[between; IN_SPHERE] THEN
    REWRITE_TAC[DIST_SYM] THEN
    MP_TAC(ISPECL [`y:real^N`; `x:real^N`] DIST_POS_LE) THEN
    REWRITE_TAC[GSYM DIST_EQ_0] THEN NORM_ARITH_TAC;
    DISCH_THEN SUBST_ALL_TAC THEN
    ASM_REWRITE_TAC[ENDS_IN_SEGMENT]]);;

let PATH_IMAGE_INTER_CBALL_FROM_SPHERE = prove
 (`!h:real^1->real^N a r.
        pathstart h IN sphere(a,r) /\
        (path_image h DELETE pathstart h) SUBSET
        ((:real^N) DIFF cball(a,r))
        ==> path_image h INTER cball(a,r) = {pathstart h}`,
  REPEAT GEN_TAC THEN INTRO_TAC "start outside" THEN
  SUBGOAL_THEN `pathstart(h:real^1->real^N) IN cball(a,r)`
  (LABEL_TAC "start_in") THENL
   [USE_THEN "start" MP_TAC THEN
    REWRITE_TAC[IN_SPHERE; IN_CBALL] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "outside" MP_TAC THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_DIFF; IN_UNIV] THEN
  MP_TAC(ISPEC `h:real^1->real^N` PATHSTART_IN_PATH_IMAGE) THEN
  USE_THEN "start_in" MP_TAC THEN SET_TAC[]);;

let PATH_IMAGE_INTER_CBALL_TO_SPHERE = prove
 (`!h:real^1->real^N b r.
        pathfinish h IN sphere(b,r) /\
        (path_image h DELETE pathfinish h) SUBSET
        ((:real^N) DIFF cball(b,r))
        ==> path_image h INTER cball(b,r) = {pathfinish h}`,
  REPEAT GEN_TAC THEN INTRO_TAC "finish outside" THEN
  SUBGOAL_THEN `pathfinish(h:real^1->real^N) IN cball(b,r)`
  (LABEL_TAC "finish_in") THENL
   [USE_THEN "finish" MP_TAC THEN
    REWRITE_TAC[IN_SPHERE; IN_CBALL] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "outside" MP_TAC THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_DIFF; IN_UNIV] THEN
  MP_TAC(ISPEC `h:real^1->real^N` PATHFINISH_IN_PATH_IMAGE) THEN
  USE_THEN "finish_in" MP_TAC THEN SET_TAC[]);;

let PATH_IMAGE_RADIALIZE = prove
 (`!h:real^1->real^N a b.
        path_image
         ((linepath(a,pathstart h) ++ h) ++
          linepath(pathfinish h,b)) =
        segment[a,pathstart h] UNION path_image h UNION
        segment[pathfinish h,b]`,
  REPEAT GEN_TAC THEN
  SIMP_TAC[PATH_IMAGE_JOIN; PATHFINISH_LINEPATH; PATHFINISH_JOIN;
           PATHSTART_LINEPATH; PATH_IMAGE_LINEPATH; UNION_ASSOC]);;

let EMBEDDED_DART_MIDDLE_OUTSIDE_DISJOINT_CBALLS = prove
 (`!V E p c u v r s.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        (u,v) IN graph_darts E /\
        &0 < r /\
        &0 < s /\
        DISJOINT (cball(p u,r)) (cball(p v,s))
        ==> ?h:real^1->real^2.
              arc h /\
              path_image h SUBSET c {u,v} /\
              pathstart h IN sphere(p u,r) /\
              pathfinish h IN sphere(p v,s) /\
              (path_image h DELETE pathstart h) SUBSET
              ((:real^2) DIFF cball(p u,r)) /\
              (path_image h DELETE pathfinish h) SUBSET
              ((:real^2) DIFF cball(p v,s))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN
   (CONJUNCTS_THEN2 (LABEL_TAC "graph")
    (CONJUNCTS_THEN2 (LABEL_TAC "embedding")
     (CONJUNCTS_THEN2 (LABEL_TAC "dart")
      (CONJUNCTS_THEN2 (LABEL_TAC "rpositive")
       (CONJUNCTS_THEN2 (LABEL_TAC "spositive")
        (LABEL_TAC "disjoint")))))) THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `u:A`; `v:A`]
   PLANE_GRAPH_EMBEDDING_DART_PATH) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC "@g. edge_arc edge_image edge_start edge_finish"] THEN
  MP_TAC(ISPECL
   [`g:real^1->real^2`; `(p:A->real^2) u`; `(p:A->real^2) v`;
    `r:real`; `s:real`]
   ARC_MIDDLE_OUTSIDE_DISJOINT_CBALLS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC
     "@h. middle_arc middle_subset middle_start middle_finish \
          tail_outside head_outside"] THEN
  EXISTS_TAC `h:real^1->real^2` THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC SUBSET_TRANS THEN
  EXISTS_TAC `path_image(g:real^1->real^2)` THEN
  ASM_REWRITE_TAC[SUBSET_REFL]);;

let EMBEDDED_DART_RADIALIZED_ARC = prove
 (`!V E p c u v r s.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        (u,v) IN graph_darts E /\
        &0 < r /\
        &0 < s /\
        DISJOINT (cball(p u,r)) (cball(p v,s))
        ==> ?h:real^1->real^2.
              arc h /\
              path_image h SUBSET c {u,v} /\
              pathstart h IN sphere(p u,r) /\
              pathfinish h IN sphere(p v,s) /\
              (path_image h DELETE pathstart h) SUBSET
              ((:real^2) DIFF cball(p u,r)) /\
              (path_image h DELETE pathfinish h) SUBSET
              ((:real^2) DIFF cball(p v,s)) /\
              arc((linepath(p u,pathstart h) ++ h) ++
                  linepath(pathfinish h,p v)) /\
              pathstart((linepath(p u,pathstart h) ++ h) ++
                        linepath(pathfinish h,p v)) = p u /\
              pathfinish((linepath(p u,pathstart h) ++ h) ++
                         linepath(pathfinish h,p v)) = p v`,
  REPEAT GEN_TAC THEN
  DISCH_THEN
   (CONJUNCTS_THEN2 (LABEL_TAC "graph")
    (CONJUNCTS_THEN2 (LABEL_TAC "embedding")
     (CONJUNCTS_THEN2 (LABEL_TAC "dart")
      (CONJUNCTS_THEN2 (LABEL_TAC "rpositive")
       (CONJUNCTS_THEN2 (LABEL_TAC "spositive")
        (LABEL_TAC "disjoint")))))) THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `u:A`; `v:A`;
    `r:real`; `s:real`]
   EMBEDDED_DART_MIDDLE_OUTSIDE_DISJOINT_CBALLS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@h. middle_arc middle_subset middle_start middle_finish \
        tail_outside head_outside" THEN
  EXISTS_TAC `h:real^1->real^2` THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`h:real^1->real^2`; `(p:A->real^2) u`; `(p:A->real^2) v`;
      `r:real`; `s:real`]
     ARC_RADIALIZE_BETWEEN_DISJOINT_CBALLS) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[PATHSTART_JOIN; PATHSTART_LINEPATH];
    REWRITE_TAC[PATHFINISH_JOIN; PATHFINISH_LINEPATH]]);;

let PLANE_GRAPH_EMBEDDING_DISJOINT_RADIALIZED_DARTS = prove
 (`!V E p c.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c
        ==> ?r:A->real.
              (!v. v IN V
                   ==> &0 < r v /\
                       cball(p v,r v) INTER
                       embedding_vertex_obstacles V E p c v = {}) /\
              (!v w. v IN V /\ w IN V /\ ~(v = w)
                     ==> DISJOINT
                          (cball(p v,r v)) (cball(p w,r w))) /\
              (!u v. (u,v) IN graph_darts E
                     ==> ?h:real^1->real^2.
                           arc h /\
                           path_image h SUBSET c {u,v} /\
                           pathstart h IN sphere(p u,r u) /\
                           pathfinish h IN sphere(p v,r v) /\
                           (path_image h DELETE pathstart h) SUBSET
                           ((:real^2) DIFF cball(p u,r u)) /\
                           (path_image h DELETE pathfinish h) SUBSET
                           ((:real^2) DIFF cball(p v,r v)) /\
                           arc((linepath(p u,pathstart h) ++ h) ++
                               linepath(pathfinish h,p v)) /\
                           pathstart
                            ((linepath(p u,pathstart h) ++ h) ++
                             linepath(pathfinish h,p v)) = p u /\
                           pathfinish
                            ((linepath(p u,pathstart h) ++ h) ++
                             linepath(pathfinish h,p v)) = p v)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN
   (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "embedding")) THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`]
   EMBEDDING_VERTEX_DISJOINT_CLOSED_BALLS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@r. clear disjoint" THEN
  EXISTS_TAC `r:A->real` THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "clear" ACCEPT_TAC;
    USE_THEN "disjoint" ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`u:A`; `v:A`] THEN DISCH_TAC THEN
    SUBGOAL_THEN `(u:A) IN V /\ (v:A) IN V /\ ~(u = v)`
    STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `u:A`; `v:A`;
      `(r:A->real) u`; `(r:A->real) v`]
     EMBEDDED_DART_RADIALIZED_ARC) THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "clear" (fun th ->
        MP_TAC(MATCH_MP (SPEC `u:A` th) (ASSUME `(u:A) IN V`))) THEN
      MESON_TAC[];
      USE_THEN "clear" (fun th ->
        MP_TAC(MATCH_MP (SPEC `v:A` th) (ASSUME `(v:A) IN V`))) THEN
      MESON_TAC[];
      USE_THEN "disjoint" (fun th ->
        MATCH_MP_TAC(SPECL [`u:A`; `v:A`] th)) THEN
      ASM_REWRITE_TAC[]]]);;

let PATH_IMAGE_AVOIDS_CENTRE_FROM_SPHERE = prove
 (`!h:real^1->real^N a r.
        &0 < r /\
        pathstart h IN sphere(a,r) /\
        (path_image h DELETE pathstart h) SUBSET
        ((:real^N) DIFF cball(a,r))
        ==> ~(a IN path_image h)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "positive start outside" THEN DISCH_TAC THEN
  ASM_CASES_TAC `(a:real^N) = pathstart h` THENL
   [UNDISCH_TAC `(a:real^N) = pathstart h` THEN
    DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "start" MP_TAC THEN
    REWRITE_TAC[IN_SPHERE; DIST_REFL] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:real^N) IN ((:real^N) DIFF cball(a,r))`
  ASSUME_TAC THENL
   [USE_THEN "outside" (fun th ->
      MATCH_MP_TAC(REWRITE_RULE[SUBSET] th)) THEN
    ASM_REWRITE_TAC[IN_DELETE];
    UNDISCH_TAC `(a:real^N) IN ((:real^N) DIFF cball(a,r))` THEN
    REWRITE_TAC[IN_DIFF; IN_UNIV; CENTRE_IN_CBALL] THEN
    ASM_REAL_ARITH_TAC]);;

let PATH_IMAGE_AVOIDS_CENTRE_TO_SPHERE = prove
 (`!h:real^1->real^N b r.
        &0 < r /\
        pathfinish h IN sphere(b,r) /\
        (path_image h DELETE pathfinish h) SUBSET
        ((:real^N) DIFF cball(b,r))
        ==> ~(b IN path_image h)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "positive finish outside" THEN DISCH_TAC THEN
  ASM_CASES_TAC `(b:real^N) = pathfinish h` THENL
   [UNDISCH_TAC `(b:real^N) = pathfinish h` THEN
    DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "finish" MP_TAC THEN
    REWRITE_TAC[IN_SPHERE; DIST_REFL] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(b:real^N) IN ((:real^N) DIFF cball(b,r))`
  ASSUME_TAC THENL
   [USE_THEN "outside" (fun th ->
      MATCH_MP_TAC(REWRITE_RULE[SUBSET] th)) THEN
    ASM_REWRITE_TAC[IN_DELETE];
    UNDISCH_TAC `(b:real^N) IN ((:real^N) DIFF cball(b,r))` THEN
    REWRITE_TAC[IN_DIFF; IN_UNIV; CENTRE_IN_CBALL] THEN
    ASM_REAL_ARITH_TAC]);;

let EMBEDDED_DART_MIDDLE_AVOIDS_VERTICES = prove
 (`!V E p c u v r s h.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        (u,v) IN graph_darts E /\
        &0 < r /\
        &0 < s /\
        path_image h SUBSET c {u,v} /\
        pathstart h IN sphere(p u,r) /\
        pathfinish h IN sphere(p v,s) /\
        (path_image h DELETE pathstart h) SUBSET
        ((:real^2) DIFF cball(p u,r)) /\
        (path_image h DELETE pathfinish h) SUBSET
        ((:real^2) DIFF cball(p v,s))
        ==> DISJOINT (path_image h) (IMAGE p V)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding dart rpositive spositive middle_subset \
             middle_start middle_finish tail_outside head_outside" THEN
  SUBGOAL_THEN
   `(u:A) IN V /\ (v:A) IN V /\ ~(u = v)`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{u:A,v} IN E` ASSUME_TAC THENL
   [USE_THEN "dart" MP_TAC THEN REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) {u,v} INTER IMAGE p V =
    IMAGE p {u,v}`
  (LABEL_TAC "vertex_intersection") THENL
   [USE_THEN "embedding" MP_TAC THEN
    REWRITE_TAC[plane_graph_embedding] THEN
    INTRO_TAC "_ _ vertices _" THEN
    REMOVE_THEN "vertices" (MP_TAC o SPEC `{u:A,v}`) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((p:A->real^2) u IN path_image h)`
  (LABEL_TAC "not_u") THENL
   [MATCH_MP_TAC(ISPECL
     [`h:real^1->real^2`; `(p:A->real^2) u`; `r:real`]
     PATH_IMAGE_AVOIDS_CENTRE_FROM_SPHERE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((p:A->real^2) v IN path_image h)`
  (LABEL_TAC "not_v") THENL
   [MATCH_MP_TAC(ISPECL
     [`h:real^1->real^2`; `(p:A->real^2) v`; `s:real`]
     PATH_IMAGE_AVOIDS_CENTRE_TO_SPHERE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  X_GEN_TAC `x:real^2` THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `(x:real^2) IN (c:(A->bool)->real^2->bool) {u,v}`
  ASSUME_TAC THENL
   [USE_THEN "middle_subset" (fun th ->
      MATCH_MP_TAC(REWRITE_RULE[SUBSET] th)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:real^2) IN IMAGE (p:A->real^2) {u,v}`
  ASSUME_TAC THENL
   [USE_THEN "vertex_intersection" (fun th ->
      ONCE_REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[IN_INTER];
    UNDISCH_TAC `(x:real^2) IN IMAGE (p:A->real^2) {u,v}` THEN
    REWRITE_TAC[IMAGE_CLAUSES; IN_INSERT; NOT_IN_EMPTY] THEN
    ASM_MESON_TAC[]]);;

let EMBEDDED_MIDDLE_ARCS_DISJOINT = prove
 (`!V E p c e e' h h'.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e IN E /\ e' IN E /\ ~(e = e') /\
        path_image h SUBSET c e /\
        path_image h' SUBSET c e' /\
        DISJOINT (path_image h) (IMAGE p V) /\
        DISJOINT (path_image h') (IMAGE p V)
        ==> DISJOINT (path_image h) (path_image h')`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding edge edge' distinct h_subset h'_subset \
             h_vertices h'_vertices" THEN
  USE_THEN "embedding" MP_TAC THEN
  REWRITE_TAC[plane_graph_embedding] THEN
  INTRO_TAC "_ _ _ edge_intersections" THEN
  REMOVE_THEN "edge_intersections" (MP_TAC o SPECL
   [`e:A->bool`; `e':A->bool`]) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "intersection") THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  X_GEN_TAC `x:real^2` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(x:real^2) IN IMAGE (p:A->real^2) (e INTER e')`
  ASSUME_TAC THENL
   [USE_THEN "intersection" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[IN_INTER] THEN CONJ_TAC THENL
     [USE_THEN "h_subset" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
      DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN ASM_REWRITE_TAC[];
      USE_THEN "h'_subset" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
      DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:real^2) IN IMAGE (p:A->real^2) V`
  ASSUME_TAC THENL
   [UNDISCH_TAC `(x:real^2) IN IMAGE (p:A->real^2) (e INTER e')` THEN
    REWRITE_TAC[IN_IMAGE; IN_INTER] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    INTRO_TAC "_ _ edge_properties" THEN
    REMOVE_THEN "edge_properties" (MP_TAC o SPEC `e:A->bool`) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "edge_subset _" THEN
    USE_THEN "edge_subset" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
    DISCH_THEN(MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[];
    USE_THEN "h_vertices" MP_TAC THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN ASM_REWRITE_TAC[]]);;

let edge_polygonal_obstacles = new_definition
 `edge_polygonal_obstacles
      (V:A->bool) (p:A->real^2) (r:A->real) (e:A->bool) =
        IMAGE p V UNION
        UNIONS(IMAGE (\v. cball(p v,r v)) (V DIFF e))`;;

let CLOSED_EDGE_POLYGONAL_OBSTACLES = prove
 (`!V p r e.
        FINITE (V:A->bool)
        ==> closed(edge_polygonal_obstacles V (p:A->real^2) r e)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[edge_polygonal_obstacles] THEN
  MATCH_MP_TAC CLOSED_UNION THEN CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_IMP_CLOSED THEN
    MATCH_MP_TAC FINITE_IMAGE THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC CLOSED_UNIONS THEN CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_IMAGE THEN ASM_SIMP_TAC[FINITE_DIFF];
      REWRITE_TAC[FORALL_IN_IMAGE] THEN
      MESON_TAC[CLOSED_CBALL]]]);;

let EMBEDDING_EDGE_SUBSET_VERTEX_OBSTACLES = prove
 (`!V E p c v e.
        e IN E /\ ~(v IN e)
        ==> c e SUBSET
            embedding_vertex_obstacles
             (V:A->bool) E (p:A->real^2) c v`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[embedding_vertex_obstacles; SUBSET; IN_UNION;
              IN_UNIONS; EXISTS_IN_IMAGE; IN_ELIM_THM] THEN
  MESON_TAC[]);;

let RADIALIZED_MIDDLE_AVOIDS_EDGE_POLYGONAL_OBSTACLES = prove
 (`!V E p c r e h.
        e IN E /\
        path_image h SUBSET c e /\
        DISJOINT (path_image h) (IMAGE p V) /\
        (!v. v IN V
             ==> cball(p v,r v) INTER
                 embedding_vertex_obstacles V E p c v = {})
        ==> DISJOINT (path_image h)
             (edge_polygonal_obstacles
               (V:A->bool) (p:A->real^2) r e)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "edge image avoids_vertices clear" THEN
  REWRITE_TAC[edge_polygonal_obstacles; DISJOINT; IN_UNION;
              EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  X_GEN_TAC `x:real^2` THEN INTRO_TAC "xh obstacle" THEN
  REMOVE_THEN "obstacle"
   (DISJ_CASES_THEN2 (LABEL_TAC "vertex_obstacle")
    (LABEL_TAC "ball_obstacle")) THENL
   [USE_THEN "avoids_vertices" MP_TAC THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN ASM_REWRITE_TAC[];
    REMOVE_THEN "ball_obstacle" (fun th ->
      X_CHOOSE_THEN `v:A`
       (CONJUNCTS_THEN2
        (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
         (LABEL_TAC "v_not_edge"))
        (LABEL_TAC "xv"))
       (REWRITE_RULE[IN_UNIONS; EXISTS_IN_IMAGE; IN_DIFF] th)) THEN
    SUBGOAL_THEN
     `(x:real^2) IN (c:(A->bool)->real^2->bool) e`
    (LABEL_TAC "xe") THENL
     [USE_THEN "image" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
      DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x:real^2) IN
      embedding_vertex_obstacles
       (V:A->bool) E (p:A->real^2) c v`
    (LABEL_TAC "x_obstacle") THENL
     [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (MATCH_MP
        (ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
          `c:(A->bool)->real^2->bool`; `v:A`; `e:A->bool`]
         EMBEDDING_EDGE_SUBSET_VERTEX_OBSTACLES)
        (CONJ (ASSUME `(e:A->bool) IN E`)
              (ASSUME `~((v:A) IN e)`)))) THEN
      USE_THEN "xe" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "clear" (fun th ->
      MP_TAC(MATCH_MP (SPEC `v:A` th)
       (ASSUME `(v:A) IN V`))) THEN
    REWRITE_TAC[EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN ASM_REWRITE_TAC[]]);;

let FINITE_DISJOINT_COMPACT_OPEN_NEIGHBOURHOODS = prove
 (`!s:A->bool. !k:A->real^N->bool.
        FINITE s /\
        (!i. i IN s ==> compact(k i) /\ ~(k i = {})) /\
        (!i j. i IN s /\ j IN s /\ ~(i = j)
               ==> DISJOINT (k i) (k j))
        ==> ?u:A->real^N->bool.
              (!i. i IN s ==> open(u i) /\ k i SUBSET u i) /\
              (!i j. i IN s /\ j IN s /\ ~(i = j)
                     ==> DISJOINT (u i) (u j))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite compact family_disjoint" THEN
  SUBGOAL_THEN
   `!i j:A. i IN s /\ j IN s /\ ~(i = j)
            ==> ~((k:A->real^N->bool) i = k j)`
  (LABEL_TAC "images_distinct") THENL
   [MAP_EVERY X_GEN_TAC [`i:A`; `j:A`] THEN
    INTRO_TAC "i j distinct" THEN DISCH_THEN(LABEL_TAC "same_image") THEN
    USE_THEN "compact" (MP_TAC o SPEC `i:A`) THEN
    USE_THEN "i" (fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "_ nonempty" THEN
    USE_THEN "family_disjoint" (MP_TAC o SPECL [`i:A`; `j:A`]) THEN
    USE_THEN "i" (fun ith ->
      USE_THEN "j" (fun jth ->
        USE_THEN "distinct" (fun dth ->
          REWRITE_TAC[ith; jth; dth]))) THEN
    DISCH_THEN(LABEL_TAC "ij_disjoint") THEN
    USE_THEN "nonempty" MP_TAC THEN REWRITE_TAC[DISJOINT_EMPTY_REFL] THEN
    USE_THEN "same_image" (fun sth ->
      USE_THEN "ij_disjoint" (fun dth ->
        ACCEPT_TAC(REWRITE_RULE[SYM sth] dth)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `pairwise (separated_in euclidean)
      (IMAGE (k:A->real^N->bool) s)`
  (LABEL_TAC "separated") THENL
   [REWRITE_TAC[PAIRWISE_IMAGE; pairwise] THEN
    MAP_EVERY X_GEN_TAC [`i:A`; `j:A`] THEN
    INTRO_TAC "i j distinct" THEN DISCH_TAC THEN
    SUBGOAL_THEN `closed((k:A->real^N->bool) i)`
    (LABEL_TAC "i_closed") THENL
     [MATCH_MP_TAC COMPACT_IMP_CLOSED THEN
      USE_THEN "compact" (MP_TAC o SPEC `i:A`) THEN
      USE_THEN "i" (fun th -> REWRITE_TAC[th]) THEN
      INTRO_TAC "i_compact _" THEN USE_THEN "i_compact" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `closed((k:A->real^N->bool) j)`
    (LABEL_TAC "j_closed") THENL
     [MATCH_MP_TAC COMPACT_IMP_CLOSED THEN
      USE_THEN "compact" (MP_TAC o SPEC `j:A`) THEN
      USE_THEN "j" (fun th -> REWRITE_TAC[th]) THEN
      INTRO_TAC "j_compact _" THEN USE_THEN "j_compact" ACCEPT_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[separated_in; TOPSPACE_EUCLIDEAN; SUBSET_UNIV;
                EUCLIDEAN_CLOSURE_OF] THEN
    ASM_SIMP_TAC[CLOSURE_CLOSED] THEN
    SUBGOAL_THEN
     `(k:A->real^N->bool) i INTER k j = {}`
    (LABEL_TAC "intersection") THENL
     [USE_THEN "family_disjoint" (MP_TAC o SPECL [`i:A`; `j:A`]) THEN
      USE_THEN "i" (fun ith ->
        USE_THEN "j" (fun jth ->
          USE_THEN "distinct" (fun dth ->
            REWRITE_TAC[ith; jth; dth; DISJOINT])));
      ASM_REWRITE_TAC[INTER_COMM]];
    ALL_TAC] THEN
  MP_TAC(ISPEC `IMAGE (k:A->real^N->bool) s`
   (REWRITE_RULE[HEREDITARILY_NORMAL_SEPARATION_PAIRWISE]
    (MATCH_MP
     (ISPEC `euclidean:(real^N)topology`
       METRIZABLE_IMP_HEREDITARILY_NORMAL_SPACE)
     METRIZABLE_SPACE_EUCLIDEAN))) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_IMAGE THEN USE_THEN "finite" ACCEPT_TAC;
      REWRITE_TAC[TOPSPACE_EUCLIDEAN; SUBSET_UNIV];
      USE_THEN "separated" ACCEPT_TAC];
    DISCH_THEN(X_CHOOSE_THEN
     `f:(real^N->bool)->real^N->bool`
     (CONJUNCTS_THEN2 (LABEL_TAC "neighborhoods")
      (LABEL_TAC "apart")))] THEN
  EXISTS_TAC
   `\i:A. (f:(real^N->bool)->real^N->bool)
           ((k:A->real^N->bool) i)` THEN
  CONJ_TAC THENL
   [X_GEN_TAC `i:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `(k:A->real^N->bool) i IN IMAGE k s`
    (LABEL_TAC "image") THENL
      [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `i:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "neighborhoods" (fun nth ->
      USE_THEN "image" (fun ith ->
        LABEL_TAC "neighborhood"
         (MATCH_MP (SPEC `(k:A->real^N->bool) i` nth) ith))) THEN
    USE_THEN "neighborhood" MP_TAC THEN REWRITE_TAC[OPEN_IN];
    MAP_EVERY X_GEN_TAC [`i:A`; `j:A`] THEN
    INTRO_TAC "i j distinct" THEN
    SUBGOAL_THEN
     `(k:A->real^N->bool) i IN IMAGE k s`
    (LABEL_TAC "i_image") THENL
     [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `i:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(k:A->real^N->bool) j IN IMAGE k s`
    (LABEL_TAC "j_image") THENL
     [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `j:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `~((k:A->real^N->bool) i = k j)`
    (LABEL_TAC "different_images") THENL
     [USE_THEN "images_distinct" (MP_TAC o SPECL [`i:A`; `j:A`]) THEN
      USE_THEN "i" (fun ith ->
        USE_THEN "j" (fun jth ->
          USE_THEN "distinct" (fun dth ->
            REWRITE_TAC[ith; jth; dth])));
      ALL_TAC] THEN
    USE_THEN "apart" (MP_TAC o REWRITE_RULE[pairwise]) THEN
    DISCH_THEN(MP_TAC o SPECL
     [`(k:A->real^N->bool) i`; `(k:A->real^N->bool) j`]) THEN
    USE_THEN "i_image" (fun ith ->
      USE_THEN "j_image" (fun jth ->
        USE_THEN "different_images" (fun dth ->
          REWRITE_TAC[ith; jth; dth])))]);;

let FINITE_DISJOINT_ARCS_POLYGONALIZE = prove
 (`!s:A->bool. !h:A->real^1->real^N.
        !z:A->real^N->bool.
        FINITE s /\
        (!i. i IN s ==> closed(z i)) /\
        (!i. i IN s
             ==> arc(h i) /\ DISJOINT (path_image(h i)) (z i)) /\
        (!i j. i IN s /\ j IN s /\ ~(i = j)
               ==> DISJOINT (path_image(h i)) (path_image(h j)))
        ==> ?q:A->real^1->real^N.
              (!i. i IN s
                   ==> polygonal_arc(q i) /\
                       pathstart(q i) = pathstart(h i) /\
                       pathfinish(q i) = pathfinish(h i) /\
                       DISJOINT (path_image(q i)) (z i)) /\
              (!i j. i IN s /\ j IN s /\ ~(i = j)
                     ==> DISJOINT (path_image(q i)) (path_image(q j)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite closed arcs family_disjoint" THEN
  MP_TAC(ISPECL
   [`s:A->bool`;
    `\i:A. path_image((h:A->real^1->real^N) i)`]
   FINITE_DISJOINT_COMPACT_OPEN_NEIGHBOURHOODS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "finite" ACCEPT_TAC;
      X_GEN_TAC `i:A` THEN
      DISCH_THEN(LABEL_TAC "i") THEN
      USE_THEN "arcs" (MP_TAC o SPEC `i:A`) THEN
      USE_THEN "i" (fun th -> REWRITE_TAC[th]) THEN
      INTRO_TAC "arc _" THEN CONJ_TAC THENL
       [MATCH_MP_TAC COMPACT_PATH_IMAGE THEN
        MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "arc" ACCEPT_TAC;
        REWRITE_TAC[PATH_IMAGE_NONEMPTY]];
      REWRITE_TAC[] THEN USE_THEN "family_disjoint" ACCEPT_TAC];
    DISCH_THEN(X_CHOOSE_THEN `u:A->real^N->bool`
     (CONJUNCTS_THEN2 (LABEL_TAC "neighborhoods")
      (LABEL_TAC "neighborhoods_disjoint")))] THEN
  SUBGOAL_THEN
   `!i:A. i IN s
          ==> ?g:real^1->real^N.
                polygonal_arc g /\
                path_image g SUBSET (u i DIFF z i) /\
                pathstart g = pathstart(h i) /\
                pathfinish g = pathfinish(h i)`
  (LABEL_TAC "choices") THENL
   [X_GEN_TAC `i:A` THEN DISCH_THEN(LABEL_TAC "i") THEN
    USE_THEN "arcs" (MP_TAC o SPEC `i:A`) THEN
    USE_THEN "i" (fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "arc avoids" THEN
    USE_THEN "neighborhoods" (MP_TAC o SPEC `i:A`) THEN
    USE_THEN "i" (fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "open contains" THEN
    SUBGOAL_THEN
     `path_image((h:A->real^1->real^N) i) SUBSET (u i DIFF z i)`
    (LABEL_TAC "ambient_subset") THENL
     [USE_THEN "contains" MP_TAC THEN USE_THEN "avoids" MP_TAC THEN
      REWRITE_TAC[DISJOINT] THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `path_image((h:A->real^1->real^N) i) SUBSET
      connected_component (u i DIFF z i) (pathstart(h i))`
    (LABEL_TAC "component_subset") THENL
     [MATCH_MP_TAC CONNECTED_COMPONENT_MAXIMAL THEN
      REPEAT CONJ_TAC THENL
       [REWRITE_TAC[PATHSTART_IN_PATH_IMAGE];
        MATCH_MP_TAC CONNECTED_PATH_IMAGE THEN
        MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "arc" ACCEPT_TAC;
        USE_THEN "ambient_subset" ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`connected_component (u i DIFF z i)
        (pathstart((h:A->real^1->real^N) i))`;
      `pathstart((h:A->real^1->real^N) i)`;
      `pathfinish((h:A->real^1->real^N) i)`]
     POLYGONAL_ARC_IN_OPEN_CONNECTED) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC OPEN_CONNECTED_COMPONENT THEN
        MATCH_MP_TAC OPEN_DIFF THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "closed" (fun th ->
          MATCH_MP_TAC(SPEC `i:A` th)) THEN
        USE_THEN "i" ACCEPT_TAC;
        REWRITE_TAC[CONNECTED_CONNECTED_COMPONENT];
        USE_THEN "component_subset" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
        DISCH_THEN MATCH_MP_TAC THEN REWRITE_TAC[PATHSTART_IN_PATH_IMAGE];
        USE_THEN "component_subset" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
        DISCH_THEN MATCH_MP_TAC THEN REWRITE_TAC[PATHFINISH_IN_PATH_IMAGE];
        USE_THEN "arc" (MP_TAC o MATCH_MP ARC_DISTINCT_ENDS) THEN
        MESON_TAC[]];
      DISCH_THEN(X_CHOOSE_THEN `g:real^1->real^N`
       (CONJUNCTS_THEN2 (LABEL_TAC "polygonal")
        (CONJUNCTS_THEN2 (LABEL_TAC "g_component")
         (CONJUNCTS_THEN2 (LABEL_TAC "g_start")
          (LABEL_TAC "g_finish")))))] THEN
    EXISTS_TAC `g:real^1->real^N` THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC
     `connected_component (u i DIFF z i)
       (pathstart((h:A->real^1->real^N) i))` THEN
    ASM_REWRITE_TAC[CONNECTED_COMPONENT_SUBSET];
    ALL_TAC] THEN
  USE_THEN "choices"
   (MP_TAC o REWRITE_RULE[RIGHT_IMP_EXISTS_THM; SKOLEM_THM]) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:A->real^1->real^N`
  (LABEL_TAC "chosen")) THEN
  EXISTS_TAC `q:A->real^1->real^N` THEN CONJ_TAC THENL
   [X_GEN_TAC `i:A` THEN DISCH_TAC THEN
    USE_THEN "chosen" (fun th ->
      MP_TAC(MATCH_MP (SPEC `i:A` th) (ASSUME `(i:A) IN s`))) THEN
    INTRO_TAC "polygonal subset start finish" THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "subset" MP_TAC THEN SET_TAC[];
    MAP_EVERY X_GEN_TAC [`i:A`; `j:A`] THEN
    INTRO_TAC "i j distinct" THEN
    USE_THEN "chosen" (fun th ->
      MP_TAC(MATCH_MP (SPEC `i:A` th) (ASSUME `(i:A) IN s`))) THEN
    INTRO_TAC "_ i_subset _ _" THEN
    USE_THEN "chosen" (fun th ->
      MP_TAC(MATCH_MP (SPEC `j:A` th) (ASSUME `(j:A) IN s`))) THEN
    INTRO_TAC "_ j_subset _ _" THEN
    USE_THEN "neighborhoods_disjoint"
     (MP_TAC o SPECL [`i:A`; `j:A`]) THEN
    USE_THEN "i" (fun ith ->
      USE_THEN "j" (fun jth ->
        USE_THEN "distinct" (fun dth ->
          REWRITE_TAC[ith; jth; dth]))) THEN
    REWRITE_TAC[DISJOINT] THEN
    USE_THEN "i_subset" MP_TAC THEN USE_THEN "j_subset" MP_TAC THEN
    SET_TAC[]]);;

let PLANE_GRAPH_EMBEDDING_DISJOINT_RADIALIZED_EDGES = prove
 (`!V E p c.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c
        ==> ?r a b h.
              (!v. v IN V
                   ==> &0 < r v /\
                       cball(p v,r v) INTER
                       embedding_vertex_obstacles V E p c v = {}) /\
              (!v w. v IN V /\ w IN V /\ ~(v = w)
                     ==> DISJOINT
                          (cball(p v,r v)) (cball(p w,r w))) /\
              (!e. e IN E
                   ==> a e IN V /\
                       b e IN V /\
                       ~(a e = b e) /\
                       e = {a e,b e} /\
                       arc(h e) /\
                       path_image(h e) SUBSET c e /\
                       pathstart(h e) IN sphere(p(a e),r(a e)) /\
                       pathfinish(h e) IN sphere(p(b e),r(b e)) /\
                       (path_image(h e) DELETE pathstart(h e)) SUBSET
                       ((:real^2) DIFF cball(p(a e),r(a e))) /\
                       (path_image(h e) DELETE pathfinish(h e)) SUBSET
                       ((:real^2) DIFF cball(p(b e),r(b e))) /\
                       DISJOINT (path_image(h e)) (IMAGE p V) /\
                       arc((linepath(p(a e),pathstart(h e)) ++ h e) ++
                           linepath(pathfinish(h e),p(b e))) /\
                       pathstart
                        ((linepath(p(a e),pathstart(h e)) ++ h e) ++
                         linepath(pathfinish(h e),p(b e))) = p(a e) /\
                       pathfinish
                        ((linepath(p(a e),pathstart(h e)) ++ h e) ++
                         linepath(pathfinish(h e),p(b e))) = p(b e)) /\
              (!e e'. e IN E /\ e' IN E /\ ~(e = e')
                       ==> DISJOINT (path_image(h e))
                                    (path_image(h e')))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`]
   PLANE_GRAPH_EMBEDDING_DISJOINT_RADIALIZED_DARTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@r. clear disjoint dart_arcs" THEN
  SUBGOAL_THEN
   `!e:A->bool. e IN E
        ==> ?u v:A. ?h:real^1->real^2.
              u IN V /\
              v IN V /\
              ~(u = v) /\
              e = {u,v} /\
              arc h /\
              path_image h SUBSET c e /\
              pathstart h IN sphere(p u,r u) /\
              pathfinish h IN sphere(p v,r v) /\
              (path_image h DELETE pathstart h) SUBSET
              ((:real^2) DIFF cball(p u,r u)) /\
              (path_image h DELETE pathfinish h) SUBSET
              ((:real^2) DIFF cball(p v,r v)) /\
              DISJOINT (path_image h) (IMAGE p V) /\
              arc((linepath(p u,pathstart h) ++ h) ++
                  linepath(pathfinish h,p v)) /\
              pathstart((linepath(p u,pathstart h) ++ h) ++
                        linepath(pathfinish h,p v)) = p u /\
              pathfinish((linepath(p u,pathstart h) ++ h) ++
                         linepath(pathfinish h,p v)) = p v`
  (LABEL_TAC "edge_choices") THENL
   [X_GEN_TAC `e:A->bool` THEN DISCH_TAC THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`]
     FINITE_SIMPLE_GRAPH_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@u v. u_vertex v_vertex distinct edge_pair" THEN
    SUBGOAL_THEN `(u:A,v) IN graph_darts E`
    (LABEL_TAC "dart") THENL
     [REWRITE_TAC[IN_GRAPH_DARTS] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `&0 < (r:A->real) u`
    (LABEL_TAC "u_positive") THENL
     [USE_THEN "clear" (fun th ->
        MP_TAC(MATCH_MP (SPEC `u:A` th) (ASSUME `(u:A) IN V`))) THEN
      MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `&0 < (r:A->real) v`
    (LABEL_TAC "v_positive") THENL
     [USE_THEN "clear" (fun th ->
        MP_TAC(MATCH_MP (SPEC `v:A` th) (ASSUME `(v:A) IN V`))) THEN
      MESON_TAC[];
      ALL_TAC] THEN
    USE_THEN "dart_arcs" (fun th ->
      MP_TAC(MATCH_MP (SPECL [`u:A`; `v:A`] th)
       (ASSUME `(u:A,v) IN graph_darts E`))) THEN
    INTRO_TAC
     "@h. middle_arc middle_subset middle_start middle_finish \
          tail_outside head_outside radial_arc radial_start radial_finish" THEN
    SUBGOAL_THEN `DISJOINT (path_image h) (IMAGE (p:A->real^2) V)`
    (LABEL_TAC "avoids_vertices") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `u:A`; `v:A`;
        `(r:A->real) u`; `(r:A->real) v`; `h:real^1->real^2`]
       EMBEDDED_DART_MIDDLE_AVOIDS_VERTICES) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC
     [`u:A`; `v:A`; `h:real^1->real^2`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "edge_choices"
   (MP_TAC o REWRITE_RULE[RIGHT_IMP_EXISTS_THM; SKOLEM_THM]) THEN
  DISCH_THEN
   (X_CHOOSE_THEN `a:(A->bool)->A`
    (X_CHOOSE_THEN `b:(A->bool)->A`
     (X_CHOOSE_THEN `h:(A->bool)->real^1->real^2`
      (LABEL_TAC "chosen")))) THEN
  MAP_EVERY EXISTS_TAC
   [`r:A->real`; `a:(A->bool)->A`; `b:(A->bool)->A`;
    `h:(A->bool)->real^1->real^2`] THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`e:A->bool`; `e':A->bool`] THEN
  INTRO_TAC "edge edge' distinct" THEN
  USE_THEN "chosen" (fun th ->
    MP_TAC(MATCH_MP (SPEC `e:A->bool` th)
     (ASSUME `(e:A->bool) IN E`))) THEN
  INTRO_TAC "_ _ _ _ _ h_subset _ _ _ _ h_vertices _ _ _" THEN
  USE_THEN "chosen" (fun th ->
    MP_TAC(MATCH_MP (SPEC `e':A->bool` th)
     (ASSUME `(e':A->bool) IN E`))) THEN
  INTRO_TAC "_ _ _ _ _ h'_subset _ _ _ _ h'_vertices _ _ _" THEN
  MATCH_MP_TAC
   (ISPEC `(h:(A->bool)->real^1->real^2) e'`
    (ISPEC `(h:(A->bool)->real^1->real^2) e`
     (ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `e:A->bool`; `e':A->bool`]
       EMBEDDED_MIDDLE_ARCS_DISJOINT))) THEN
  ASM_REWRITE_TAC[]);;

let PLANE_GRAPH_EMBEDDING_DISJOINT_POLYGONAL_MIDDLES = prove
 (`!V E p c.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c
        ==> ?r a b q.
              (!v. v IN V
                   ==> &0 < r v /\
                       cball(p v,r v) INTER
                       embedding_vertex_obstacles V E p c v = {}) /\
              (!v w. v IN V /\ w IN V /\ ~(v = w)
                     ==> DISJOINT
                          (cball(p v,r v)) (cball(p w,r w))) /\
              (!e. e IN E
                   ==> a e IN V /\
                       b e IN V /\
                       ~(a e = b e) /\
                       e = {a e,b e} /\
                       polygonal_arc(q e) /\
                       pathstart(q e) IN sphere(p(a e),r(a e)) /\
                       pathfinish(q e) IN sphere(p(b e),r(b e)) /\
                       DISJOINT (path_image(q e))
                        (edge_polygonal_obstacles V p r e)) /\
              (!e e'. e IN E /\ e' IN E /\ ~(e = e')
                       ==> DISJOINT (path_image(q e))
                                    (path_image(q e')))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding" THEN
  USE_THEN "graph" MP_TAC THEN REWRITE_TAC[finite_simple_graph] THEN
  INTRO_TAC "vertices_finite edges_finite _" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`]
   PLANE_GRAPH_EMBEDDING_DISJOINT_RADIALIZED_EDGES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@r a b h. clear balls radialized h_disjoint" THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`;
    `h:(A->bool)->real^1->real^2`;
    `edge_polygonal_obstacles
      (V:A->bool) (p:A->real^2) (r:A->real)`]
   FINITE_DISJOINT_ARCS_POLYGONALIZE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "edges_finite" ACCEPT_TAC;
      X_GEN_TAC `e:A->bool` THEN DISCH_TAC THEN
      MATCH_MP_TAC CLOSED_EDGE_POLYGONAL_OBSTACLES THEN
      USE_THEN "vertices_finite" ACCEPT_TAC;
      X_GEN_TAC `e:A->bool` THEN DISCH_TAC THEN
      USE_THEN "radialized" (fun th ->
        MP_TAC(MATCH_MP (SPEC `e:A->bool` th)
         (ASSUME `(e:A->bool) IN E`))) THEN
      INTRO_TAC "_ _ _ _ arc image _ _ _ _ avoids _ _ _" THEN
      CONJ_TAC THENL
       [USE_THEN "arc" ACCEPT_TAC;
        MATCH_MP_TAC
         (ISPECL
          [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
           `c:(A->bool)->real^2->bool`; `r:A->real`;
           `e:A->bool`; `(h:(A->bool)->real^1->real^2) e`]
          RADIALIZED_MIDDLE_AVOIDS_EDGE_POLYGONAL_OBSTACLES) THEN
        ASM_REWRITE_TAC[] THEN
        X_GEN_TAC `v:A` THEN DISCH_TAC THEN
        USE_THEN "clear" (fun th ->
          MP_TAC(MATCH_MP (SPEC `v:A` th)
           (ASSUME `(v:A) IN V`))) THEN
        MESON_TAC[]];
      USE_THEN "h_disjoint" ACCEPT_TAC];
    DISCH_THEN(X_CHOOSE_THEN `q:(A->bool)->real^1->real^2`
     (CONJUNCTS_THEN2 (LABEL_TAC "polygonalized")
      (LABEL_TAC "q_disjoint")))] THEN
  MAP_EVERY EXISTS_TAC
   [`r:A->real`; `a:(A->bool)->A`; `b:(A->bool)->A`;
    `q:(A->bool)->real^1->real^2`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "clear" ACCEPT_TAC;
    USE_THEN "balls" ACCEPT_TAC;
    X_GEN_TAC `e:A->bool` THEN DISCH_TAC THEN
    USE_THEN "radialized" (fun th ->
      MP_TAC(MATCH_MP (SPEC `e:A->bool` th)
       (ASSUME `(e:A->bool) IN E`))) THEN
    INTRO_TAC "a_vertex b_vertex distinct pair _ _ start finish \
               _ _ _ _ _ _" THEN
    USE_THEN "polygonalized" (fun th ->
      MP_TAC(MATCH_MP (SPEC `e:A->bool` th)
       (ASSUME `(e:A->bool) IN E`))) THEN
    INTRO_TAC "polygonal q_start q_finish avoids" THEN
    ASM_REWRITE_TAC[] THEN USE_THEN "pair" ACCEPT_TAC;
    USE_THEN "q_disjoint" ACCEPT_TAC]);;

let PLANE_GRAPH_EMBEDDING_DISJOINT_TRIMMED_POLYGONAL_MIDDLES = prove
 (`!V E p c.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c
        ==> ?r a b k.
              (!v. v IN V
                   ==> &0 < r v /\
                       cball(p v,r v) INTER
                       embedding_vertex_obstacles V E p c v = {}) /\
              (!v w. v IN V /\ w IN V /\ ~(v = w)
                     ==> DISJOINT
                          (cball(p v,r v)) (cball(p w,r w))) /\
              (!e. e IN E
                   ==> a e IN V /\
                       b e IN V /\
                       ~(a e = b e) /\
                       e = {a e,b e} /\
                       polygonal_arc(k e) /\
                       pathstart(k e) IN sphere(p(a e),r(a e)) /\
                       pathfinish(k e) IN sphere(p(b e),r(b e)) /\
                       (path_image(k e) DELETE pathstart(k e)) SUBSET
                       ((:real^2) DIFF cball(p(a e),r(a e))) /\
                       (path_image(k e) DELETE pathfinish(k e)) SUBSET
                       ((:real^2) DIFF cball(p(b e),r(b e))) /\
                       DISJOINT (path_image(k e))
                        (edge_polygonal_obstacles V p r e)) /\
              (!e e'. e IN E /\ e' IN E /\ ~(e = e')
                       ==> DISJOINT (path_image(k e))
                                    (path_image(k e')))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph embedding" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`]
   PLANE_GRAPH_EMBEDDING_DISJOINT_POLYGONAL_MIDDLES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@r a b q. clear balls polygonalized q_disjoint" THEN
  SUBGOAL_THEN
   `!e:A->bool. e IN E
        ==> ?h:real^1->real^2.
              polygonal_arc h /\
              path_image h SUBSET path_image(q e) /\
              pathstart h IN sphere(p(a e),r(a e)) /\
              pathfinish h IN sphere(p(b e),r(b e)) /\
              (path_image h DELETE pathstart h) SUBSET
              ((:real^2) DIFF cball(p(a e),r(a e))) /\
              (path_image h DELETE pathfinish h) SUBSET
              ((:real^2) DIFF cball(p(b e),r(b e))) /\
              DISJOINT (path_image h)
               (edge_polygonal_obstacles V p r e)`
  (LABEL_TAC "choices") THENL
   [X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    USE_THEN "polygonalized" (fun th ->
      MP_TAC(MATCH_MP (SPEC `e:A->bool` th)
       (ASSUME `(e:A->bool) IN E`))) THEN
    INTRO_TAC
     "a_vertex b_vertex distinct pair polygonal start finish avoids" THEN
    SUBGOAL_THEN
     `&0 < (r:A->real)
            ((a:(A->bool)->A) (e:A->bool))`
    (LABEL_TAC "a_positive") THENL
     [USE_THEN "clear" (fun th ->
        MP_TAC(MATCH_MP (SPEC `(a:(A->bool)->A) e` th)
         (ASSUME `(a:(A->bool)->A) e IN V`))) THEN
      INTRO_TAC "positive _" THEN USE_THEN "positive" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `&0 < (r:A->real)
            ((b:(A->bool)->A) (e:A->bool))`
    (LABEL_TAC "b_positive") THENL
     [USE_THEN "clear" (fun th ->
        MP_TAC(MATCH_MP (SPEC `(b:(A->bool)->A) e` th)
         (ASSUME `(b:(A->bool)->A) e IN V`))) THEN
      INTRO_TAC "positive _" THEN USE_THEN "positive" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `pathstart((q:(A->bool)->real^1->real^2) e) IN
      cball((p:A->real^2) ((a:(A->bool)->A) e),
            r(a e))`
    (LABEL_TAC "start_in") THENL
     [USE_THEN "start" MP_TAC THEN
      REWRITE_TAC[IN_SPHERE; IN_CBALL] THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `pathfinish((q:(A->bool)->real^1->real^2) e) IN
      cball((p:A->real^2) ((b:(A->bool)->A) e),
            r(b e))`
    (LABEL_TAC "finish_in") THENL
     [USE_THEN "finish" MP_TAC THEN
      REWRITE_TAC[IN_SPHERE; IN_CBALL] THEN REAL_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `DISJOINT
       (cball((p:A->real^2) ((a:(A->bool)->A) e),r(a e)))
       (cball(p((b:(A->bool)->A) e),r(b e)))`
    (LABEL_TAC "endpoint_balls") THENL
     [USE_THEN "balls" (fun th ->
        MATCH_MP_TAC(SPECL
         [`(a:(A->bool)->A) e`; `(b:(A->bool)->A) e`] th)) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`(q:(A->bool)->real^1->real^2) e`;
      `(p:A->real^2) ((a:(A->bool)->A) e)`;
      `(p:A->real^2) ((b:(A->bool)->A) e)`;
      `(r:A->real) ((a:(A->bool)->A) e)`;
      `(r:A->real) ((b:(A->bool)->A) e)`]
     POLYGONAL_ARC_MIDDLE_OUTSIDE_DISJOINT_CBALLS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      INTRO_TAC
       "@h. h_polygonal h_subset h_start h_finish \
            tail_outside head_outside"] THEN
    EXISTS_TAC `h:real^1->real^2` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "h_subset" MP_TAC THEN USE_THEN "avoids" MP_TAC THEN
    REWRITE_TAC[DISJOINT] THEN SET_TAC[];
    ALL_TAC] THEN
  USE_THEN "choices"
   (MP_TAC o REWRITE_RULE[RIGHT_IMP_EXISTS_THM; SKOLEM_THM]) THEN
  DISCH_THEN(X_CHOOSE_THEN `k:(A->bool)->real^1->real^2`
   (LABEL_TAC "chosen")) THEN
  MAP_EVERY EXISTS_TAC
   [`r:A->real`; `a:(A->bool)->A`; `b:(A->bool)->A`;
    `k:(A->bool)->real^1->real^2`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "clear" ACCEPT_TAC;
    USE_THEN "balls" ACCEPT_TAC;
    X_GEN_TAC `e:A->bool` THEN DISCH_TAC THEN
    USE_THEN "polygonalized" (fun th ->
      MP_TAC(MATCH_MP (SPEC `e:A->bool` th)
       (ASSUME `(e:A->bool) IN E`))) THEN
    INTRO_TAC
     "a_vertex b_vertex distinct pair _ _ _ _" THEN
    USE_THEN "chosen" (fun th ->
      MP_TAC(MATCH_MP (SPEC `e:A->bool` th)
       (ASSUME `(e:A->bool) IN E`))) THEN
    INTRO_TAC
     "polygonal _ start finish tail_outside head_outside avoids" THEN
    ASM_REWRITE_TAC[] THEN USE_THEN "pair" ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`e:A->bool`; `e':A->bool`] THEN
    INTRO_TAC "edge edge' distinct" THEN
    USE_THEN "chosen" (fun th ->
      MP_TAC(MATCH_MP (SPEC `e:A->bool` th)
       (ASSUME `(e:A->bool) IN E`))) THEN
    INTRO_TAC "_ e_subset _ _ _ _ _" THEN
    USE_THEN "chosen" (fun th ->
      MP_TAC(MATCH_MP (SPEC `e':A->bool` th)
       (ASSUME `(e':A->bool) IN E`))) THEN
    INTRO_TAC "_ e'_subset _ _ _ _ _" THEN
    USE_THEN "q_disjoint" (MP_TAC o SPECL
     [`e:A->bool`; `e':A->bool`]) THEN
    USE_THEN "edge" (fun eth ->
      USE_THEN "edge'" (fun e'th ->
        USE_THEN "distinct" (fun dth ->
          REWRITE_TAC[eth; e'th; dth]))) THEN
    REWRITE_TAC[DISJOINT] THEN
    USE_THEN "e_subset" MP_TAC THEN USE_THEN "e'_subset" MP_TAC THEN
    SET_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Reconstructing a polygonal embedding from the disjoint trimmed middles.   *)
(* ------------------------------------------------------------------------- *)

let RADIAL_SEGMENT_DISJOINT_SET_OUTSIDE_CBALL = prove
 (`!a x:real^N. !r s.
        &0 <= r /\
        x IN sphere(a,r) /\
        DISJOINT s (cball(a,r))
        ==> DISJOINT (segment[a,x]) s`,
  REPEAT GEN_TAC THEN INTRO_TAC "nonnegative sphere disjoint" THEN
  SUBGOAL_THEN `segment[a:real^N,x] SUBSET cball(a,r)`
  (LABEL_TAC "segment") THENL
   [MATCH_MP_TAC RADIAL_SEGMENT_SUBSET_CBALL THEN ASM_REWRITE_TAC[];
    USE_THEN "disjoint" MP_TAC THEN USE_THEN "segment" MP_TAC THEN
    REWRITE_TAC[DISJOINT] THEN SET_TAC[]]);;

let RADIAL_SEGMENT_DISJOINT_SET_AT_OTHER_SPHERE_POINT = prove
 (`!a x y:real^N. !r s.
        x IN sphere(a,r) /\
        y IN sphere(a,r) /\
        ~(x = y) /\
        s INTER cball(a,r) = {y}
        ==> DISJOINT (segment[a,x]) s`,
  REPEAT GEN_TAC THEN INTRO_TAC "x_sphere y_sphere distinct meets_ball" THEN
  SUBGOAL_THEN `&0 <= r` (LABEL_TAC "nonnegative") THENL
   [USE_THEN "x_sphere" MP_TAC THEN
    REWRITE_TAC[IN_SPHERE] THEN
    MP_TAC(ISPECL [`a:real^N`; `x:real^N`] DIST_POS_LE) THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `segment[a:real^N,x] SUBSET cball(a,r)`
  (LABEL_TAC "segment") THENL
   [MATCH_MP_TAC RADIAL_SEGMENT_SUBSET_CBALL THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `segment[a:real^N,x] INTER sphere(a,r) = {x}`
  (LABEL_TAC "meets_sphere") THENL
   [MATCH_MP_TAC RADIAL_SEGMENT_INTER_SPHERE THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    X_GEN_TAC `z:real^N` THEN INTRO_TAC "z_segment z_set" THEN
    SUBGOAL_THEN `(z:real^N) IN cball(a,r)` (LABEL_TAC "z_ball") THENL
     [USE_THEN "segment" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "z_segment" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(z:real^N) = y` (LABEL_TAC "z_y") THENL
     [SUBGOAL_THEN `(z:real^N) IN {y}` MP_TAC THENL
       [USE_THEN "meets_ball" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
        ASM_REWRITE_TAC[IN_INTER];
        REWRITE_TAC[IN_SING]];
      ALL_TAC] THEN
    SUBGOAL_THEN `(y:real^N) IN segment[a,x]`
    (LABEL_TAC "y_segment") THENL
     [ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(y:real^N) IN segment[a,x] INTER sphere(a,r)`
    (LABEL_TAC "y_intersection") THENL
     [ASM_REWRITE_TAC[IN_INTER];
      ALL_TAC] THEN
    SUBGOAL_THEN `(y:real^N) IN {x}` MP_TAC THENL
     [USE_THEN "meets_sphere" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
      USE_THEN "y_intersection" ACCEPT_TAC;
      REWRITE_TAC[IN_SING] THEN
      ASM_REWRITE_TAC[]]]);;

let RADIAL_SEGMENTS_AT_GRAPH_VERTICES_INTER = prove
 (`!V p r v w x y.
        v IN (V:A->bool) /\
        w IN V /\
        &0 <= r v /\
        &0 <= r w /\
        x IN sphere((p:A->real^N) v,r v) /\
        y IN sphere(p w,r w) /\
        (v = w ==> ~(x = y)) /\
        (~(v = w)
         ==> DISJOINT (cball(p v,r v)) (cball(p w,r w)))
        ==> segment[p v,x] INTER segment[p w,y] =
            IMAGE p ({v} INTER {w})`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "v_vertex w_vertex v_nonnegative w_nonnegative \
             x_sphere y_sphere same different" THEN
  ASM_CASES_TAC `(v:A) = w` THENL
   [ASM_REWRITE_TAC[INTER_IDEMPOT; IMAGE_CLAUSES] THEN
    MATCH_MP_TAC RADIAL_SEGMENTS_INTER THEN ASM_MESON_TAC[];
    SUBGOAL_THEN
     `segment[(p:A->real^N) v,x] SUBSET cball(p v,r v)`
    (LABEL_TAC "first") THENL
     [MATCH_MP_TAC RADIAL_SEGMENT_SUBSET_CBALL THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `segment[(p:A->real^N) w,y] SUBSET cball(p w,r w)`
    (LABEL_TAC "second") THENL
     [MATCH_MP_TAC RADIAL_SEGMENT_SUBSET_CBALL THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `DISJOINT
       (cball((p:A->real^N) v,r v)) (cball(p w,r w))`
    (LABEL_TAC "balls") THENL
     [USE_THEN "different" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `{v:A} INTER {w} = {}` SUBST1_TAC THENL
     [ASM SET_TAC[];
      REWRITE_TAC[IMAGE_CLAUSES; EXTENSION; IN_INTER; NOT_IN_EMPTY]] THEN
    X_GEN_TAC `z:real^N` THEN
    INTRO_TAC "z_first z_second" THEN
    USE_THEN "first" (fun sth ->
      USE_THEN "z_first" (fun zth ->
        LABEL_TAC "z_first_ball"
         (MATCH_MP (REWRITE_RULE[SUBSET] sth) zth))) THEN
    USE_THEN "second" (fun sth ->
      USE_THEN "z_second" (fun zth ->
        LABEL_TAC "z_second_ball"
         (MATCH_MP (REWRITE_RULE[SUBSET] sth) zth))) THEN
    USE_THEN "balls" MP_TAC THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `z:real^N`) THEN ASM_REWRITE_TAC[]]);;

let radialized_edge = new_definition
 `radialized_edge
    (p:A->real^N) (a:(A->bool)->A) (b:(A->bool)->A)
    (k:(A->bool)->real^1->real^N) e =
      (linepath(p(a e),pathstart(k e)) ++ k e) ++
      linepath(pathfinish(k e),p(b e))`;;

let PATH_IMAGE_RADIALIZED_EDGE = prove
 (`!p a b k e.
        path_image(radialized_edge p a b k e) =
        segment[p(a e),pathstart(k e)] UNION path_image(k e) UNION
        segment[pathfinish(k e),p(b e)]`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[radialized_edge; PATH_IMAGE_RADIALIZE]);;

let EDGE_POLYGONAL_OBSTACLES_CONTAINS_VERTICES = prove
 (`!V p r e.
        IMAGE (p:A->real^2) V SUBSET
        edge_polygonal_obstacles V p r e`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[edge_polygonal_obstacles] THEN SET_TAC[]);;

let EDGE_POLYGONAL_OBSTACLES_CONTAINS_CBALL = prove
 (`!V p r e v.
        v IN (V:A->bool) /\ ~(v IN e)
        ==> cball((p:A->real^2) v,r v) SUBSET
            edge_polygonal_obstacles V p r e`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[edge_polygonal_obstacles; SUBSET; IN_UNION;
              IN_UNIONS; EXISTS_IN_IMAGE; IN_DIFF] THEN
  MESON_TAC[]);;

let RADIAL_SEGMENT_AT_GRAPH_VERTEX_INTER_VERTICES = prove
 (`!V p r v x.
        v IN (V:A->bool) /\
        &0 <= r v /\
        x IN sphere((p:A->real^N) v,r v) /\
        (!w. w IN V /\ ~(v = w)
             ==> &0 <= r w /\
                 DISJOINT (cball(p v,r v)) (cball(p w,r w)))
        ==> segment[p v,x] INTER IMAGE p V = {p v}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "v_vertex v_nonnegative sphere balls" THEN
  SUBGOAL_THEN
   `segment[(p:A->real^N) v,x] SUBSET cball(p v,r v)`
  (LABEL_TAC "segment") THENL
   [MATCH_MP_TAC RADIAL_SEGMENT_SUBSET_CBALL THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[EXTENSION; IN_INTER; IN_IMAGE; IN_SING] THEN
  X_GEN_TAC `z:real^N` THEN EQ_TAC THENL
   [DISCH_THEN
     (CONJUNCTS_THEN2 (LABEL_TAC "z_segment")
      (X_CHOOSE_THEN `w:A`
       (CONJUNCTS_THEN2 (LABEL_TAC "z_w")
        (LABEL_TAC "w_vertex")))) THEN
    ASM_CASES_TAC `(v:A) = w` THENL
     [ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `&0 <= (r:A->real) w`
      (LABEL_TAC "w_nonnegative") THENL
     [USE_THEN "balls" (fun th ->
        MP_TAC(MATCH_MP (SPEC `w:A` th)
         (CONJ (ASSUME `(w:A) IN V`)
               (ASSUME `~((v:A) = w)`)))) THEN
      MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `DISJOINT
       (cball((p:A->real^N) v,r v)) (cball(p w,r w))`
    (LABEL_TAC "disjoint") THENL
     [USE_THEN "balls" (fun th ->
        MP_TAC(MATCH_MP (SPEC `w:A` th)
         (CONJ (ASSUME `(w:A) IN V`)
               (ASSUME `~((v:A) = w)`)))) THEN
      MESON_TAC[];
      ALL_TAC] THEN
    USE_THEN "segment" (fun sth ->
      USE_THEN "z_segment" (fun zth ->
        LABEL_TAC "z_v_ball"
         (MATCH_MP
           (SPEC `z:real^N` (REWRITE_RULE[SUBSET] sth)) zth))) THEN
    SUBGOAL_THEN
     `(z:real^N) IN cball((p:A->real^N) w,(r:A->real) w)`
    (LABEL_TAC "z_w_ball") THENL
     [USE_THEN "z_w" SUBST1_TAC THEN
      ASM_REWRITE_TAC[IN_CBALL; DIST_REFL];
      USE_THEN "disjoint" MP_TAC THEN ASM SET_TAC[]];
    DISCH_THEN SUBST1_TAC THEN
    ASM_MESON_TAC[ENDS_IN_SEGMENT]]);;

let RADIALIZED_EDGE_INTER_VERTICES = prove
 (`!V (p:A->real^2) (r:A->real)
      (a:(A->bool)->A) (b:(A->bool)->A)
      (k:(A->bool)->real^1->real^2) (e:A->bool).
        a e IN (V:A->bool) /\
        b e IN V /\
        e = {a e,b e} /\
        (!v. v IN V ==> &0 <= r v) /\
        pathstart(k e) IN sphere((p:A->real^2)(a e),r(a e)) /\
        pathfinish(k e) IN sphere(p(b e),r(b e)) /\
        (!v w. v IN V /\ w IN V /\ ~(v = w)
               ==> DISJOINT (cball(p v,r v)) (cball(p w,r w))) /\
        DISJOINT (path_image(k e))
         (edge_polygonal_obstacles V p r e)
        ==> path_image(radialized_edge p a b k e) INTER IMAGE p V =
            IMAGE p e`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "a_vertex b_vertex pair nonnegative start finish balls avoids" THEN
  SUBGOAL_THEN
   `segment[(p:A->real^2)((a:(A->bool)->A)(e:A->bool)),
            pathstart((k:(A->bool)->real^1->real^2) e)] INTER
    IMAGE p V = {p(a e)}`
  (LABEL_TAC "tail") THENL
   [MATCH_MP_TAC
     (ISPECL
       [`V:A->bool`; `p:A->real^2`; `r:A->real`;
        `(a:(A->bool)->A) (e:A->bool)`;
        `pathstart((k:(A->bool)->real^1->real^2) e)`]
       RADIAL_SEGMENT_AT_GRAPH_VERTEX_INTER_VERTICES) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
  `segment[(p:A->real^2)((b:(A->bool)->A)(e:A->bool)),
            pathfinish((k:(A->bool)->real^1->real^2) e)] INTER
    IMAGE p V = {p(b e)}`
  (LABEL_TAC "head") THENL
   [MATCH_MP_TAC
     (ISPECL
       [`V:A->bool`; `p:A->real^2`; `r:A->real`;
        `(b:(A->bool)->A) (e:A->bool)`;
        `pathfinish((k:(A->bool)->real^1->real^2) e)`]
       RADIAL_SEGMENT_AT_GRAPH_VERTEX_INTER_VERTICES) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "pair"
   (MP_TAC o AP_TERM `\s:A->bool. IMAGE (p:A->real^2) s`) THEN
  REWRITE_TAC[IMAGE_CLAUSES] THEN
  DISCH_THEN(LABEL_TAC "edge_vertices") THEN
  SUBGOAL_THEN
   `segment[pathfinish((k:(A->bool)->real^1->real^2) (e:A->bool)),
            (p:A->real^2)((b:(A->bool)->A) e)] INTER
    IMAGE p V = {p(b e)}`
  (LABEL_TAC "reversed_head") THENL
   [ONCE_REWRITE_TAC[SEGMENT_SYM] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[PATH_IMAGE_RADIALIZED_EDGE] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `p:A->real^2`; `r:A->real`; `e:A->bool`]
   EDGE_POLYGONAL_OBSTACLES_CONTAINS_VERTICES) THEN
  USE_THEN "avoids" MP_TAC THEN
  USE_THEN "tail" MP_TAC THEN
  USE_THEN "reversed_head" MP_TAC THEN
  USE_THEN "edge_vertices" MP_TAC THEN
  REWRITE_TAC[DISJOINT] THEN SET_TAC[]);;

let RADIAL_SEGMENT_DISJOINT_EDGE_MIDDLE = prove
 (`!V (p:A->real^2) (r:A->real)
      (a:(A->bool)->A) (b:(A->bool)->A)
      (k:(A->bool)->real^1->real^2) (e:A->bool) v x.
        v IN V /\
        &0 <= r v /\
        x IN sphere(p v,r v) /\
        e = {a e,b e} /\
        pathstart(k e) IN sphere(p(a e),r(a e)) /\
        pathfinish(k e) IN sphere(p(b e),r(b e)) /\
        (path_image(k e) DELETE pathstart(k e)) SUBSET
        ((:real^2) DIFF cball(p(a e),r(a e))) /\
        (path_image(k e) DELETE pathfinish(k e)) SUBSET
        ((:real^2) DIFF cball(p(b e),r(b e))) /\
        DISJOINT (path_image(k e))
         (edge_polygonal_obstacles V p r e) /\
        (v = a e ==> ~(x = pathstart(k e))) /\
        (v = b e ==> ~(x = pathfinish(k e)))
        ==> DISJOINT (segment[p v,x]) (path_image(k e))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "v_vertex nonnegative x_sphere pair start finish \
             tail_outside head_outside avoids start_distinct \
             finish_distinct" THEN
  ASM_CASES_TAC
   `(v:A) = (a:(A->bool)->A) (e:A->bool)` THENL
   [MATCH_MP_TAC
     (ISPECL
       [`(p:A->real^2) v`; `x:real^2`;
        `pathstart((k:(A->bool)->real^1->real^2) e)`;
        `(r:A->real) v`;
       `path_image((k:(A->bool)->real^1->real^2) e)`]
       RADIAL_SEGMENT_DISJOINT_SET_AT_OTHER_SPHERE_POINT) THEN
    REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      ASM_MESON_TAC[];
      MATCH_MP_TAC PATH_IMAGE_INTER_CBALL_FROM_SPHERE THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ASM_CASES_TAC
   `(v:A) = (b:(A->bool)->A) (e:A->bool)` THENL
   [MATCH_MP_TAC
     (ISPECL
       [`(p:A->real^2) v`; `x:real^2`;
        `pathfinish((k:(A->bool)->real^1->real^2) e)`;
        `(r:A->real) v`;
       `path_image((k:(A->bool)->real^1->real^2) e)`]
       RADIAL_SEGMENT_DISJOINT_SET_AT_OTHER_SPHERE_POINT) THEN
    REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      ASM_MESON_TAC[];
      MATCH_MP_TAC PATH_IMAGE_INTER_CBALL_TO_SPHERE THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC
   (ISPECL
     [`(p:A->real^2) v`; `x:real^2`; `(r:A->real) v`;
      `path_image((k:(A->bool)->real^1->real^2) (e:A->bool))`]
     RADIAL_SEGMENT_DISJOINT_SET_OUTSIDE_CBALL) THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    MP_TAC(ISPECL
     [`V:A->bool`; `p:A->real^2`; `r:A->real`; `e:A->bool`; `v:A`]
     EDGE_POLYGONAL_OBSTACLES_CONTAINS_CBALL) THEN
    ANTS_TAC THENL
     [USE_THEN "pair" MP_TAC THEN ASM SET_TAC[];
      DISCH_THEN(LABEL_TAC "ball_subset")] THEN
    USE_THEN "avoids" MP_TAC THEN
    USE_THEN "ball_subset" MP_TAC THEN
    REWRITE_TAC[DISJOINT] THEN SET_TAC[]]);;

let UNION3_INTER_UNION3 = prove
 (`!s t u s' t' u':A->bool.
        (s UNION t UNION u) INTER (s' UNION t' UNION u') =
        (s INTER s') UNION (s INTER t') UNION (s INTER u') UNION
        (t INTER s') UNION (t INTER t') UNION (t INTER u') UNION
        (u INTER s') UNION (u INTER t') UNION (u INTER u')`,
  SET_TAC[]);;

let DISJOINT_SETS_POINTS_DISTINCT = prove
 (`!s t:A->bool. !x y.
        DISJOINT s t /\ x IN s /\ y IN t ==> ~(x = y)`,
  REWRITE_TAC[DISJOINT] THEN SET_TAC[]);;

let RADIALIZED_EDGES_INTER = prove
 (`!V E (p:A->real^2) (r:A->real)
      (a:(A->bool)->A) (b:(A->bool)->A)
      (k:(A->bool)->real^1->real^2) e e'.
        (!v. v IN V ==> &0 <= r v) /\
        (!v w. v IN V /\ w IN V /\ ~(v = w)
               ==> DISJOINT (cball(p v,r v)) (cball(p w,r w))) /\
        (!d. d IN E
             ==> a d IN V /\
                 b d IN V /\
                 d = {a d,b d} /\
                 pathstart(k d) IN sphere(p(a d),r(a d)) /\
                 pathfinish(k d) IN sphere(p(b d),r(b d)) /\
                 (path_image(k d) DELETE pathstart(k d)) SUBSET
                 ((:real^2) DIFF cball(p(a d),r(a d))) /\
                 (path_image(k d) DELETE pathfinish(k d)) SUBSET
                 ((:real^2) DIFF cball(p(b d),r(b d))) /\
                 DISJOINT (path_image(k d))
                  (edge_polygonal_obstacles V p r d)) /\
        (!d d'. d IN E /\ d' IN E /\ ~(d = d')
                 ==> DISJOINT (path_image(k d)) (path_image(k d'))) /\
        e IN E /\ e' IN E /\ ~(e = e')
        ==> path_image(radialized_edge p a b k e) INTER
            path_image(radialized_edge p a b k e') =
            IMAGE p (e INTER e')`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "nonnegative balls edge_data middle_disjoint e_edge e'_edge distinct" THEN
  USE_THEN "edge_data" (fun th ->
    MP_TAC(MATCH_MP (SPEC `e:A->bool` th)
     (ASSUME `(e:A->bool) IN E`))) THEN
  INTRO_TAC
   "e_a_vertex e_b_vertex e_pair e_start e_finish \
    e_tail_outside e_head_outside e_avoids" THEN
  USE_THEN "edge_data" (fun th ->
    MP_TAC(MATCH_MP (SPEC `e':A->bool` th)
     (ASSUME `(e':A->bool) IN E`))) THEN
  INTRO_TAC
   "e'_a_vertex e'_b_vertex e'_pair e'_start e'_finish \
    e'_tail_outside e'_head_outside e'_avoids" THEN
  SUBGOAL_THEN
   `DISJOINT
     (path_image((k:(A->bool)->real^1->real^2) (e:A->bool)))
     (path_image(k (e':A->bool)))`
  (LABEL_TAC "middles") THENL
   [USE_THEN "middle_disjoint" (fun th ->
      MATCH_MP_TAC(SPECL [`e:A->bool`; `e':A->bool`] th)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(pathstart((k:(A->bool)->real^1->real^2) (e:A->bool)) =
      pathstart(k (e':A->bool)))`
  (LABEL_TAC "start_start_distinct") THENL
   [MATCH_MP_TAC
     (ISPECL
       [`path_image((k:(A->bool)->real^1->real^2) (e:A->bool))`;
        `path_image((k:(A->bool)->real^1->real^2) (e':A->bool))`;
        `pathstart((k:(A->bool)->real^1->real^2) (e:A->bool))`;
        `pathstart((k:(A->bool)->real^1->real^2) (e':A->bool))`]
       DISJOINT_SETS_POINTS_DISTINCT) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "middles" ACCEPT_TAC;
      ACCEPT_TAC
       (ISPEC `(k:(A->bool)->real^1->real^2) (e:A->bool)`
        PATHSTART_IN_PATH_IMAGE);
      ACCEPT_TAC
       (ISPEC `(k:(A->bool)->real^1->real^2) (e':A->bool)`
        PATHSTART_IN_PATH_IMAGE)];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(pathstart((k:(A->bool)->real^1->real^2) (e:A->bool)) =
      pathfinish(k (e':A->bool)))`
  (LABEL_TAC "start_finish_distinct") THENL
   [MATCH_MP_TAC
     (ISPECL
       [`path_image((k:(A->bool)->real^1->real^2) (e:A->bool))`;
        `path_image((k:(A->bool)->real^1->real^2) (e':A->bool))`;
        `pathstart((k:(A->bool)->real^1->real^2) (e:A->bool))`;
        `pathfinish((k:(A->bool)->real^1->real^2) (e':A->bool))`]
       DISJOINT_SETS_POINTS_DISTINCT) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "middles" ACCEPT_TAC;
      ACCEPT_TAC
       (ISPEC `(k:(A->bool)->real^1->real^2) (e:A->bool)`
        PATHSTART_IN_PATH_IMAGE);
      ACCEPT_TAC
       (ISPEC `(k:(A->bool)->real^1->real^2) (e':A->bool)`
        PATHFINISH_IN_PATH_IMAGE)];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(pathfinish((k:(A->bool)->real^1->real^2) (e:A->bool)) =
      pathstart(k (e':A->bool)))`
  (LABEL_TAC "finish_start_distinct") THENL
   [MATCH_MP_TAC
     (ISPECL
       [`path_image((k:(A->bool)->real^1->real^2) (e:A->bool))`;
        `path_image((k:(A->bool)->real^1->real^2) (e':A->bool))`;
        `pathfinish((k:(A->bool)->real^1->real^2) (e:A->bool))`;
        `pathstart((k:(A->bool)->real^1->real^2) (e':A->bool))`]
       DISJOINT_SETS_POINTS_DISTINCT) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "middles" ACCEPT_TAC;
      ACCEPT_TAC
       (ISPEC `(k:(A->bool)->real^1->real^2) (e:A->bool)`
        PATHFINISH_IN_PATH_IMAGE);
      ACCEPT_TAC
       (ISPEC `(k:(A->bool)->real^1->real^2) (e':A->bool)`
        PATHSTART_IN_PATH_IMAGE)];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(pathfinish((k:(A->bool)->real^1->real^2) (e:A->bool)) =
      pathfinish(k (e':A->bool)))`
  (LABEL_TAC "finish_finish_distinct") THENL
   [MATCH_MP_TAC
     (ISPECL
       [`path_image((k:(A->bool)->real^1->real^2) (e:A->bool))`;
        `path_image((k:(A->bool)->real^1->real^2) (e':A->bool))`;
        `pathfinish((k:(A->bool)->real^1->real^2) (e:A->bool))`;
        `pathfinish((k:(A->bool)->real^1->real^2) (e':A->bool))`]
       DISJOINT_SETS_POINTS_DISTINCT) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "middles" ACCEPT_TAC;
      ACCEPT_TAC
       (ISPEC `(k:(A->bool)->real^1->real^2) (e:A->bool)`
        PATHFINISH_IN_PATH_IMAGE);
      ACCEPT_TAC
       (ISPEC `(k:(A->bool)->real^1->real^2) (e':A->bool)`
        PATHFINISH_IN_PATH_IMAGE)];
    ALL_TAC] THEN
  SUBGOAL_THEN
  `segment[(p:A->real^2)((a:(A->bool)->A) (e:A->bool)),
            pathstart((k:(A->bool)->real^1->real^2) e)] INTER
    segment[p(a e'),pathstart(k e')] =
    IMAGE p ({a e} INTER {a e'})`
  (LABEL_TAC "tail_tail") THENL
   [MATCH_MP_TAC
     (ISPECL
       [`V:A->bool`; `p:A->real^2`; `r:A->real`;
        `(a:(A->bool)->A) (e:A->bool)`;
        `(a:(A->bool)->A) (e':A->bool)`;
       `pathstart((k:(A->bool)->real^1->real^2) (e:A->bool))`;
        `pathstart((k:(A->bool)->real^1->real^2) (e':A->bool))`]
       RADIAL_SEGMENTS_AT_GRAPH_VERTICES_INTER) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "e_a_vertex" ACCEPT_TAC;
      USE_THEN "e'_a_vertex" ACCEPT_TAC;
      USE_THEN "nonnegative" (fun th ->
        MATCH_MP_TAC(SPEC `(a:(A->bool)->A) (e:A->bool)` th)) THEN
      USE_THEN "e_a_vertex" ACCEPT_TAC;
      USE_THEN "nonnegative" (fun th ->
        MATCH_MP_TAC(SPEC `(a:(A->bool)->A) (e':A->bool)` th)) THEN
