let RADIALIZED_EDGE_ENDPOINTS = prove
 (`!p:A->real^N. !a b k e.
        pathstart(radialized_edge p a b k e) = p(a e) /\
        pathfinish(radialized_edge p a b k e) = p(b e)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[radialized_edge; PATHSTART_JOIN; PATHFINISH_JOIN;
              PATHSTART_LINEPATH; PATHFINISH_LINEPATH]);;

let POLYGONAL_ARC_RADIALIZED_EDGE = prove
 (`!p:A->real^N. !r a b k e.
        polygonal_arc(k e) /\
        &0 < r(a e) /\
        &0 < r(b e) /\
        DISJOINT (cball(p(a e),r(a e))) (cball(p(b e),r(b e))) /\
        pathstart(k e) IN sphere(p(a e),r(a e)) /\
        pathfinish(k e) IN sphere(p(b e),r(b e)) /\
        (path_image(k e) DELETE pathstart(k e)) SUBSET
        ((:real^N) DIFF cball(p(a e),r(a e))) /\
        (path_image(k e) DELETE pathfinish(k e)) SUBSET
        ((:real^N) DIFF cball(p(b e),r(b e)))
        ==> polygonal_arc(radialized_edge p a b k e)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[radialized_edge] THEN
  MATCH_ACCEPT_TAC POLYGONAL_ARC_RADIALIZE_BETWEEN_DISJOINT_CBALLS);;

let PLANE_GRAPH_EMBEDDING_IMP_POLYGONAL_EMBEDDING = prove
 (`!V E (p:A->real^2) c.
        finite_simple_graph V E /\
        plane_graph_embedding V E p c
        ==> ?c'. polygonal_plane_graph_embedding V E p c'`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph embedding" THEN
  SUBGOAL_THEN `INJ (p:A->real^2) V UNIV`
  (LABEL_TAC "injective") THENL
   [USE_THEN "embedding"
     (fun th ->
       ACCEPT_TAC
        (CONJUNCT1(REWRITE_RULE[plane_graph_embedding] th)));
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`]
   PLANE_GRAPH_EMBEDDING_DISJOINT_TRIMMED_POLYGONAL_MIDDLES) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      USE_THEN "embedding" ACCEPT_TAC];
    INTRO_TAC "@r a b k. clear balls edge_data middle_disjoint"] THEN
  SUBGOAL_THEN
   `!v:A. v IN V ==> &0 <= (r:A->real) v`
  (LABEL_TAC "nonnegative") THENL
   [X_GEN_TAC `v:A` THEN DISCH_THEN(LABEL_TAC "v_vertex") THEN
    MATCH_MP_TAC REAL_LT_IMP_LE THEN
    USE_THEN "clear" (fun th ->
      MP_TAC(MATCH_MP (SPEC `v:A` th)
       (ASSUME `(v:A) IN V`))) THEN
    INTRO_TAC "positive _" THEN USE_THEN "positive" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!d:A->bool. d IN (E:(A->bool)->bool)
        ==> (a:(A->bool)->A) d IN (V:A->bool) /\
            (b:(A->bool)->A) d IN V /\
            d = {a d,b d} /\
            pathstart(k d) IN sphere(p(a d),r(a d)) /\
            pathfinish(k d) IN sphere(p(b d),r(b d)) /\
            (path_image(k d) DELETE pathstart(k d)) SUBSET
            ((:real^2) DIFF cball(p(a d),r(a d))) /\
            (path_image(k d) DELETE pathfinish(k d)) SUBSET
            ((:real^2) DIFF cball(p(b d),r(b d))) /\
            DISJOINT (path_image(k d))
             (edge_polygonal_obstacles V p r d)`
  (LABEL_TAC "edge_geometry") THENL
   [X_GEN_TAC `d:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    USE_THEN "edge_data" (fun th ->
