   `!d:A->bool. d IN (E:(A->bool)->bool)
        ==> path_image
             (radialized_edge (p:A->real^2) (a:(A->bool)->A)
               (b:(A->bool)->A) (k:(A->bool)->real^1->real^2) d)
            INTER IMAGE p (V:A->bool) =
            IMAGE p d`
  (LABEL_TAC "vertex_intersections") THENL
   [X_GEN_TAC `d:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    USE_THEN "edge_geometry" (fun th ->
      MP_TAC(MATCH_MP (SPEC `d:A->bool` th)
       (ASSUME `(d:A->bool) IN E`))) THEN
    INTRO_TAC "a_vertex b_vertex pair start finish \
               tail_outside head_outside avoids" THEN
    MATCH_MP_TAC
     (ISPECL
       [`V:A->bool`; `p:A->real^2`; `r:A->real`;
        `a:(A->bool)->A`; `b:(A->bool)->A`;
        `k:(A->bool)->real^1->real^2`; `d:A->bool`]
       RADIALIZED_EDGE_INTER_VERTICES) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "a_vertex" ACCEPT_TAC;
      USE_THEN "b_vertex" ACCEPT_TAC;
      USE_THEN "pair" ACCEPT_TAC;
      USE_THEN "nonnegative" ACCEPT_TAC;
      USE_THEN "start" ACCEPT_TAC;
      USE_THEN "finish" ACCEPT_TAC;
      USE_THEN "balls" ACCEPT_TAC;
      USE_THEN "avoids" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!d d':A->bool.
        d IN (E:(A->bool)->bool) /\ d' IN E /\ ~(d = d')
        ==> path_image
             (radialized_edge (p:A->real^2) (a:(A->bool)->A)
               (b:(A->bool)->A) (k:(A->bool)->real^1->real^2) d) INTER
            path_image(radialized_edge p a b k d') =
            IMAGE p (d INTER d')`
  (LABEL_TAC "edge_intersections") THENL
   [MAP_EVERY X_GEN_TAC [`d:A->bool`; `d':A->bool`] THEN
    INTRO_TAC "edge edge' distinct" THEN
    MATCH_MP_TAC
     (ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `r:A->real`; `a:(A->bool)->A`; `b:(A->bool)->A`;
        `k:(A->bool)->real^1->real^2`;
        `d:A->bool`; `d':A->bool`]
       RADIALIZED_EDGES_INTER) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "nonnegative" ACCEPT_TAC;
      USE_THEN "balls" ACCEPT_TAC;
      USE_THEN "edge_geometry" ACCEPT_TAC;
      USE_THEN "middle_disjoint" ACCEPT_TAC;
      USE_THEN "edge" ACCEPT_TAC;
      USE_THEN "edge'" ACCEPT_TAC;
      USE_THEN "distinct" ACCEPT_TAC];
    ALL_TAC] THEN
  EXISTS_TAC
   `\d:A->bool.
      path_image
       (radialized_edge (p:A->real^2) a b k d)` THEN
  REWRITE_TAC[polygonal_plane_graph_embedding] THEN CONJ_TAC THENL
   [REWRITE_TAC[plane_graph_embedding] THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "injective" ACCEPT_TAC;
      X_GEN_TAC `d:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
      EXISTS_TAC
       `radialized_edge (p:A->real^2) a b k (d:A->bool)` THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC POLYGONAL_ARC_IMP_ARC THEN
        USE_THEN "polygonal_edges" (fun th ->
          MATCH_MP_TAC(SPEC `d:A->bool` th)) THEN
        USE_THEN "edge" ACCEPT_TAC;
        REFL_TAC;
        USE_THEN "endpoint_images" (fun th ->
          MATCH_MP_TAC(SPEC `d:A->bool` th)) THEN
        USE_THEN "edge" ACCEPT_TAC];
      X_GEN_TAC `d:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
      BETA_TAC THEN
      USE_THEN "vertex_intersections" (fun th ->
        MATCH_MP_TAC(SPEC `d:A->bool` th)) THEN
      USE_THEN "edge" ACCEPT_TAC;
      MAP_EVERY X_GEN_TAC [`d:A->bool`; `d':A->bool`] THEN
      INTRO_TAC "edge edge' distinct" THEN BETA_TAC THEN
      USE_THEN "edge_intersections" (fun th ->
        MATCH_MP_TAC(SPECL [`d:A->bool`; `d':A->bool`] th)) THEN
      ASM_REWRITE_TAC[]];
    X_GEN_TAC `d:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    EXISTS_TAC
     `radialized_edge (p:A->real^2) a b k (d:A->bool)` THEN
    CONJ_TAC THENL
     [USE_THEN "polygonal_edges" (fun th ->
        MATCH_MP_TAC(SPEC `d:A->bool` th)) THEN
      USE_THEN "edge" ACCEPT_TAC;
      REFL_TAC]]);;

let PLANAR_GRAPH_IMP_POLYGONALLY_PLANAR = prove
 (`!V E.
        planar_graph (V:A->bool) E
        ==> polygonally_planar_graph V E`,
  REWRITE_TAC[planar_graph; polygonally_planar_graph] THEN
  MESON_TAC[PLANE_GRAPH_EMBEDDING_IMP_POLYGONAL_EMBEDDING]);;

let POLYGONALLY_PLANAR_IMP_PLANAR_GRAPH = prove
 (`!V E.
        polygonally_planar_graph (V:A->bool) E
        ==> planar_graph V E`,
  REWRITE_TAC[polygonally_planar_graph; planar_graph;
              polygonal_plane_graph_embedding] THEN
  MESON_TAC[]);;

let PLANAR_GRAPH_EQ_POLYGONALLY_PLANAR_GRAPH = prove
 (`!V E.
        planar_graph (V:A->bool) E <=>
        polygonally_planar_graph V E`,
  MESON_TAC[PLANAR_GRAPH_IMP_POLYGONALLY_PLANAR;
            POLYGONALLY_PLANAR_IMP_PLANAR_GRAPH]);;

let PLANAR_GRAPH_EQ_POLYGONAL = prove
 (`!V E.
        planar_graph (V:A->bool) E <=>
        finite_simple_graph V E /\
        ?p c. polygonal_plane_graph_embedding V E p c`,
  REWRITE_TAC[PLANAR_GRAPH_EQ_POLYGONALLY_PLANAR_GRAPH;
              polygonally_planar_graph]);;

let PLANE_GRAPH_EMBEDDING_INDUCED_SUBGRAPH = prove
 (`!V E p c W.
        plane_graph_embedding (V:A->bool) E p c /\ W SUBSET V
        ==> plane_graph_embedding W (induced_subgraph_edges E W) p c`,
  REPEAT GEN_TAC THEN INTRO_TAC "embedding subset" THEN
  USE_THEN "embedding" MP_TAC THEN
  REWRITE_TAC[plane_graph_embedding] THEN
  INTRO_TAC "injective paths vertices intersections" THEN
  REWRITE_TAC[plane_graph_embedding] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[INJ; IN_UNIV] THEN
    MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    INTRO_TAC "x_small y_small equal" THEN
    SUBGOAL_THEN `(x:A) IN V /\ (y:A) IN V`
    (CONJUNCTS_THEN2 (LABEL_TAC "x_big") (LABEL_TAC "y_big")) THENL
     [USE_THEN "subset" MP_TAC THEN REWRITE_TAC[SUBSET] THEN
      ASM_MESON_TAC[];
      ALL_TAC] THEN
    USE_THEN "injective" MP_TAC THEN REWRITE_TAC[INJ; IN_UNIV] THEN
    DISCH_THEN(MP_TAC o SPECL [`x:A`; `y:A`]) THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `e:A->bool` THEN
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    INTRO_TAC "edge edge_subset" THEN
    USE_THEN "paths" MATCH_MP_TAC THEN USE_THEN "edge" ACCEPT_TAC;
    X_GEN_TAC `e:A->bool` THEN
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    INTRO_TAC "edge edge_subset" THEN
    SUBGOAL_THEN
     `(c:(A->bool)->real^2->bool) e INTER IMAGE p V = IMAGE p e`
    (LABEL_TAC "old") THENL
     [USE_THEN "vertices" MATCH_MP_TAC THEN USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `IMAGE (p:A->real^2) W SUBSET IMAGE p V`
    (LABEL_TAC "small_vertices") THENL
     [MATCH_MP_TAC IMAGE_SUBSET THEN USE_THEN "subset" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `IMAGE (p:A->real^2) e SUBSET IMAGE p W`
    (LABEL_TAC "endpoints") THENL
     [MATCH_MP_TAC IMAGE_SUBSET THEN USE_THEN "edge_subset" ACCEPT_TAC;
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`(c:(A->bool)->real^2->bool) e`;
      `IMAGE (p:A->real^2) V`; `IMAGE (p:A->real^2) e`;
      `IMAGE (p:A->real^2) W`]
     INTER_SUBSET_CARRIER_EQ) THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`e:A->bool`; `e':A->bool`] THEN
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    INTRO_TAC "(edge edge_subset) (edge' edge'_subset) distinct" THEN
    USE_THEN "intersections" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

let MAXIMAL_PLANAR_GRAPH_EXTENSION = prove
 (`!V E.
        planar_graph (V:A->bool) E
        ==> ?E'. E SUBSET E' /\
                 planar_graph V E' /\
                 (!E''. E' PSUBSET E'' /\
                         E'' SUBSET complete_graph_edges V
                         ==> ~planar_graph V E'')`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "planar") THEN
  ABBREV_TAC
   `candidates = {E':(A->bool)->bool |
       E SUBSET E' /\ E' SUBSET complete_graph_edges V /\
       planar_graph V E'}` THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite_vertices") THENL
   [USE_THEN "planar" MP_TAC THEN
    REWRITE_TAC[planar_graph; FINITE_SIMPLE_GRAPH_EQ] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `E SUBSET complete_graph_edges (V:A->bool)`
  (LABEL_TAC "edges") THENL
   [USE_THEN "planar" MP_TAC THEN
    REWRITE_TAC[planar_graph; FINITE_SIMPLE_GRAPH_EQ] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(candidates:((A->bool)->bool)->bool)`
  (LABEL_TAC "finite_candidates") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `{E':(A->bool)->bool |
                 E' SUBSET complete_graph_edges V}` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_POWERSET THEN
      MATCH_MP_TAC FINITE_COMPLETE_GRAPH_EDGES THEN
      USE_THEN "finite_vertices" ACCEPT_TAC;
      EXPAND_TAC "candidates" THEN
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(candidates:((A->bool)->bool)->bool = {})`
  (LABEL_TAC "candidates_nonempty") THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN EXISTS_TAC `E:(A->bool)->bool` THEN
    EXPAND_TAC "candidates" THEN REWRITE_TAC[IN_ELIM_THM; SUBSET_REFL] THEN
    CONJ_TAC THENL
     [USE_THEN "edges" ACCEPT_TAC;
      USE_THEN "planar" ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPEC `candidates:((A->bool)->bool)->bool`
   FINITE_MAXIMAL_ELEMENT) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "finite_candidates" ACCEPT_TAC;
      USE_THEN "candidates_nonempty" ACCEPT_TAC];
    DISCH_THEN(X_CHOOSE_THEN `E':(A->bool)->bool`
     (CONJUNCTS_THEN2 (LABEL_TAC "candidate") (LABEL_TAC "maximal")))] THEN
  USE_THEN "candidate" MP_TAC THEN EXPAND_TAC "candidates" THEN
  REWRITE_TAC[IN_ELIM_THM] THEN
  INTRO_TAC "contains within extended_planar" THEN
  EXISTS_TAC `E':(A->bool)->bool` THEN CONJ_TAC THENL
   [USE_THEN "contains" ACCEPT_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "extended_planar" ACCEPT_TAC;
    ALL_TAC] THEN
  X_GEN_TAC `E'':(A->bool)->bool` THEN
  INTRO_TAC "proper allowed" THEN DISCH_THEN(LABEL_TAC "planar'") THEN
  USE_THEN "maximal" (MP_TAC o SPEC `E'':(A->bool)->bool`) THEN
  ANTS_TAC THENL
   [EXPAND_TAC "candidates" THEN REWRITE_TAC[IN_ELIM_THM] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `E':(A->bool)->bool` THEN
      CONJ_TAC THENL
       [USE_THEN "contains" ACCEPT_TAC;
        USE_THEN "proper" MP_TAC THEN REWRITE_TAC[PSUBSET] THEN MESON_TAC[]];
      CONJ_TAC THENL
       [USE_THEN "allowed" ACCEPT_TAC;
        USE_THEN "planar'" ACCEPT_TAC]];
    DISCH_THEN(LABEL_TAC "notproper") THEN
    USE_THEN "notproper" MP_TAC THEN USE_THEN "proper" MP_TAC THEN
    MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Straight-line embeddings.                                                 *)
(* ------------------------------------------------------------------------- *)

let straight_edge = new_definition
 `straight_edge (p:A->real^N) e = convex hull (IMAGE p e)`;;

let straight_line_embedding = new_definition
 `straight_line_embedding
      (V:A->bool) (E:(A->bool)->bool) (p:A->real^2) <=>
        INJ p V UNIV /\
        (!e. e IN E
             ==> straight_edge p e INTER IMAGE p V = IMAGE p e) /\
        (!e e'. e IN E /\ e' IN E /\ ~(e = e')
                 ==> straight_edge p e INTER straight_edge p e' =
                     IMAGE p (e INTER e'))`;;

let straight_line_planar_graph = new_definition
 `straight_line_planar_graph (V:A->bool) (E:(A->bool)->bool) <=>
        finite_simple_graph V E /\
        ?p. straight_line_embedding V E p`;;

let STRAIGHT_EDGE_PAIR = prove
 (`!p:A->real^N u v.
        straight_edge p {u,v} = segment[p u,p v]`,
  REWRITE_TAC[straight_edge; IMAGE_CLAUSES; SEGMENT_CONVEX_HULL]);;

let IMAGE_SUBSET_STRAIGHT_EDGE = prove
 (`!p:A->real^N e. IMAGE p e SUBSET straight_edge p e`,
  REWRITE_TAC[straight_edge; HULL_SUBSET]);;

let STRAIGHT_LINE_EMBEDDING_SUBSET_EDGES = prove
 (`!V E E' p.
        straight_line_embedding (V:A->bool) E p /\ E' SUBSET E
        ==> straight_line_embedding V E' p`,
  REWRITE_TAC[straight_line_embedding] THEN MESON_TAC[SUBSET]);;

let STRAIGHT_LINE_EMBEDDING_EQ_ON_VERTICES = prove
 (`!V E p q.
        finite_simple_graph (V:A->bool) E /\
        straight_line_embedding V E p /\
        (!x. x IN V ==> q x = p x)
        ==> straight_line_embedding V E (q:A->real^2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding agrees" THEN
  USE_THEN "embedding" MP_TAC THEN
  REWRITE_TAC[straight_line_embedding] THEN
  INTRO_TAC "injective vertices intersections" THEN
  SUBGOAL_THEN `IMAGE (q:A->real^2) V = IMAGE p V`
  (LABEL_TAC "vertex_image") THENL
   [MATCH_MP_TAC IMAGE_EQ THEN USE_THEN "agrees" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!e:A->bool. e IN E ==> e SUBSET V`
  (LABEL_TAC "edge_subset") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!e:A->bool. e IN E
                  ==> straight_edge (q:A->real^2) e =
                      straight_edge (p:A->real^2) e /\
                      IMAGE (q:A->real^2) e = IMAGE (p:A->real^2) e`
  (LABEL_TAC "edge_images") THENL
   [X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    SUBGOAL_THEN `(e:A->bool) SUBSET V` (LABEL_TAC "subset") THENL
     [USE_THEN "edge_subset" MATCH_MP_TAC THEN USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `!x:A. x IN e ==> (q:A->real^2) x = p x`
    (LABEL_TAC "on_edge") THENL
     [X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "in_edge") THEN
      USE_THEN "agrees" MATCH_MP_TAC THEN
      USE_THEN "subset" (fun sth ->
        USE_THEN "in_edge" (fun eth ->
          ACCEPT_TAC
           (MATCH_MP (SPEC `x:A` (REWRITE_RULE[SUBSET] sth)) eth)));
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[straight_edge] THEN AP_TERM_TAC THEN
      MATCH_MP_TAC IMAGE_EQ THEN USE_THEN "on_edge" ACCEPT_TAC;
      MATCH_MP_TAC IMAGE_EQ THEN USE_THEN "on_edge" ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[straight_line_embedding] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[INJ; IN_UNIV] THEN
    MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    INTRO_TAC "x_vertex y_vertex equal" THEN
    SUBGOAL_THEN
     `(q:A->real^2) x = p x /\ (q:A->real^2) y = p y`
    (CONJUNCTS_THEN2 (LABEL_TAC "x_image") (LABEL_TAC "y_image")) THENL
     [CONJ_TAC THEN USE_THEN "agrees" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV] THEN
    DISCH_THEN(MP_TAC o SPECL [`x:A`; `y:A`]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    USE_THEN "x_image" (fun xth ->
      USE_THEN "equal" (fun eth ->
        USE_THEN "y_image" (fun yth ->
          ACCEPT_TAC(TRANS (TRANS (SYM xth) eth) yth))));
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    SUBGOAL_THEN
     `straight_edge (q:A->real^2) e = straight_edge p e /\
      IMAGE q e = IMAGE p e`
    (CONJUNCTS_THEN2 (LABEL_TAC "edge_image")
      (LABEL_TAC "endpoint_image")) THENL
     [USE_THEN "edge_images" MATCH_MP_TAC THEN USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `straight_edge (p:A->real^2) e INTER IMAGE p V = IMAGE p e`
    (LABEL_TAC "old") THENL
     [USE_THEN "vertices" MATCH_MP_TAC THEN USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "vertex_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "edge_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "endpoint_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "old" ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`e:A->bool`; `e':A->bool`] THEN
    INTRO_TAC "edge edge' distinct" THEN
    SUBGOAL_THEN
     `straight_edge (q:A->real^2) e = straight_edge p e /\
      IMAGE q e = IMAGE p e`
    (CONJUNCTS_THEN2 (LABEL_TAC "edge_image")
      (LABEL_TAC "endpoint_image")) THENL
     [USE_THEN "edge_images" MATCH_MP_TAC THEN USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `straight_edge (q:A->real^2) e' = straight_edge p e' /\
      IMAGE q e' = IMAGE p e'`
    (CONJUNCTS_THEN2 (LABEL_TAC "edge'_image")
      (LABEL_TAC "endpoint'_image")) THENL
     [USE_THEN "edge_images" MATCH_MP_TAC THEN USE_THEN "edge'" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `IMAGE (q:A->real^2) (e INTER e') =
      IMAGE (p:A->real^2) (e INTER e')`
    (LABEL_TAC "common_image") THENL
     [MATCH_MP_TAC IMAGE_EQ THEN X_GEN_TAC `x:A` THEN
      REWRITE_TAC[IN_INTER] THEN INTRO_TAC "in_edge in_edge'" THEN
      SUBGOAL_THEN `(e:A->bool) SUBSET V` (LABEL_TAC "subset") THENL
       [USE_THEN "edge_subset" MATCH_MP_TAC THEN USE_THEN "edge" ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "agrees" MATCH_MP_TAC THEN
      USE_THEN "subset" (fun sth ->
        USE_THEN "in_edge" (fun eth ->
          ACCEPT_TAC
           (MATCH_MP (SPEC `x:A` (REWRITE_RULE[SUBSET] sth)) eth)));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `straight_edge (p:A->real^2) e INTER straight_edge p e' =
      IMAGE p (e INTER e')`
    (LABEL_TAC "old") THENL
     [USE_THEN "intersections" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "edge_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "edge'_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "common_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "old" ACCEPT_TAC]);;

let STRAIGHT_LINE_EMBEDDING_UNION = prove
 (`!V1 E1 V2 E2 p.
        straight_line_embedding (V1:A->bool) E1 p /\
        straight_line_embedding V2 E2 p /\
        INJ p (V1 UNION V2) UNIV /\
        (!e. e IN E1
             ==> straight_edge p e INTER IMAGE p V2 SUBSET IMAGE p e) /\
        (!e. e IN E2
             ==> straight_edge p e INTER IMAGE p V1 SUBSET IMAGE p e) /\
        (!e e'. e IN E1 /\ e' IN E2 /\ ~(e = e')
                ==> straight_edge p e INTER straight_edge p e' =
                    IMAGE p (e INTER e'))
        ==> straight_line_embedding (V1 UNION V2) (E1 UNION E2)
             (p:A->real^2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "embedding1 embedding2 injective vertices12 vertices21 cross" THEN
  USE_THEN "embedding1" MP_TAC THEN
  REWRITE_TAC[straight_line_embedding] THEN
  INTRO_TAC "injective1 vertices1 intersections1" THEN
  USE_THEN "embedding2" MP_TAC THEN
  REWRITE_TAC[straight_line_embedding] THEN
  INTRO_TAC "injective2 vertices2 intersections2" THEN
  REWRITE_TAC[straight_line_embedding] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "injective" ACCEPT_TAC;
    X_GEN_TAC `e:A->bool` THEN
    REWRITE_TAC[IN_UNION] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "edge1") (LABEL_TAC "edge2")) THENL
     [SUBGOAL_THEN
       `straight_edge (p:A->real^2) e INTER IMAGE p V1 = IMAGE p e`
      (LABEL_TAC "old") THENL
       [USE_THEN "vertices1" MATCH_MP_TAC THEN USE_THEN "edge1" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `straight_edge (p:A->real^2) e INTER IMAGE p V2 SUBSET IMAGE p e`
      (LABEL_TAC "other") THENL
       [USE_THEN "vertices12" MATCH_MP_TAC THEN USE_THEN "edge1" ACCEPT_TAC;
        ALL_TAC] THEN
      REWRITE_TAC[IMAGE_UNION] THEN
      MATCH_MP_TAC(SET_RULE
       `(s:real^2->bool) INTER a = i /\ s INTER b SUBSET i
        ==> s INTER (a UNION b) = i`) THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN
       `straight_edge (p:A->real^2) e INTER IMAGE p V2 = IMAGE p e`
      (LABEL_TAC "old") THENL
       [USE_THEN "vertices2" MATCH_MP_TAC THEN USE_THEN "edge2" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `straight_edge (p:A->real^2) e INTER IMAGE p V1 SUBSET IMAGE p e`
      (LABEL_TAC "other") THENL
       [USE_THEN "vertices21" MATCH_MP_TAC THEN USE_THEN "edge2" ACCEPT_TAC;
        ALL_TAC] THEN
      REWRITE_TAC[IMAGE_UNION] THEN
      MATCH_MP_TAC(SET_RULE
       `(s:real^2->bool) INTER b = i /\ s INTER a SUBSET i
        ==> s INTER (a UNION b) = i`) THEN
      ASM_REWRITE_TAC[]];
    MAP_EVERY X_GEN_TAC [`e:A->bool`; `e':A->bool`] THEN
    INTRO_TAC "edge edge' distinct" THEN
    USE_THEN "edge" MP_TAC THEN REWRITE_TAC[IN_UNION] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "edge1") (LABEL_TAC "edge2")) THENL
     [USE_THEN "edge'" MP_TAC THEN REWRITE_TAC[IN_UNION] THEN
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "edge1'")
       (LABEL_TAC "edge2'")) THENL
       [USE_THEN "intersections1" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        USE_THEN "cross" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
      USE_THEN "edge'" MP_TAC THEN REWRITE_TAC[IN_UNION] THEN
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "edge1'")
       (LABEL_TAC "edge2'")) THENL
       [ONCE_REWRITE_TAC[INTER_COMM] THEN
        USE_THEN "cross" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        USE_THEN "intersections2" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]]]);;

let STRAIGHT_LINE_EMBEDDING_INSERT_VERTEX_STAR = prove
 (`!V E p v N p'.
        finite_simple_graph (V:A->bool) E /\
        straight_line_embedding V E p /\
        ~(v IN V) /\ N SUBSET V /\
        (!u. u IN V ==> p' u = p u) /\
        ~((p':A->real^2) v IN IMAGE p V) /\
        (!e. e IN E ==> ~(p' v IN straight_edge p e)) /\
        (!u. u IN N
             ==> segment[p' v,p u] INTER IMAGE p V = {p u}) /\
        (!u e. u IN N /\ e IN E
               ==> segment[p' v,p u] INTER straight_edge p e =
                   IMAGE p ({u} INTER e)) /\
        (!u w. u IN N /\ w IN N /\ ~(u = w)
               ==> segment[p' v,p u] INTER segment[p' v,p w] = {p' v})
        ==> straight_line_embedding (v INSERT V)
             (IMAGE (\u:A. {v,u}) N UNION E) p'`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding fresh neighbors agrees new_vertex old_edges \
    new_vertices new_old new_new" THEN
  USE_THEN "embedding" MP_TAC THEN
  REWRITE_TAC[straight_line_embedding] THEN
  INTRO_TAC "old_injective old_vertices old_intersections" THEN
  SUBGOAL_THEN `IMAGE (p':A->real^2) V = IMAGE p V`
  (LABEL_TAC "old_image") THENL
   [MATCH_MP_TAC IMAGE_EQ THEN USE_THEN "agrees" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!e:A->bool. e IN E ==> e SUBSET V`
  (LABEL_TAC "edge_subset") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!e:A->bool. e IN E
                  ==> straight_edge (p':A->real^2) e =
                      straight_edge (p:A->real^2) e /\
                      IMAGE (p':A->real^2) e = IMAGE (p:A->real^2) e`
  (LABEL_TAC "old_edge_image") THENL
   [X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    SUBGOAL_THEN
     `!x:A. x IN e ==> (p':A->real^2) x = p x`
    (LABEL_TAC "on_edge") THENL
     [X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "in_edge") THEN
      USE_THEN "agrees" MATCH_MP_TAC THEN
      USE_THEN "edge_subset" (MP_TAC o SPEC `e:A->bool`) THEN
      REWRITE_TAC[SUBSET] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[straight_edge] THEN AP_TERM_TAC THEN
      MATCH_MP_TAC IMAGE_EQ THEN
      USE_THEN "on_edge" ACCEPT_TAC;
      MATCH_MP_TAC IMAGE_EQ THEN
      USE_THEN "on_edge" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u:A. u IN N
          ==> straight_edge (p':A->real^2) {v,u} INTER
              IMAGE p' (v INSERT V) = IMAGE p' {v,u}`
  (LABEL_TAC "new_edge_vertices") THENL
   [X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "neighbor") THEN
    SUBGOAL_THEN `(u:A) IN V` (LABEL_TAC "u_vertex") THENL
     [USE_THEN "neighbors" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "neighbor" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(p':A->real^2) u = p u` (LABEL_TAC "u_image") THENL
     [USE_THEN "agrees" MATCH_MP_TAC THEN USE_THEN "u_vertex" ACCEPT_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[STRAIGHT_EDGE_PAIR; IMAGE_CLAUSES] THEN
    USE_THEN "old_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "u_image" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(SET_RULE
     `(s:real^2->bool) INTER t = {r} /\ q IN s
      ==> s INTER (q INSERT t) = {q,r}`) THEN
    CONJ_TAC THENL
     [USE_THEN "new_vertices" (MATCH_MP_TAC o SPEC `u:A`) THEN
      USE_THEN "neighbor" ACCEPT_TAC;
      REWRITE_TAC[ENDS_IN_SEGMENT]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!e:A->bool. e IN E
          ==> straight_edge (p':A->real^2) e INTER
              IMAGE p' (v INSERT V) = IMAGE p' e`
  (LABEL_TAC "old_edge_vertices") THENL
   [X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    SUBGOAL_THEN
     `straight_edge (p':A->real^2) e = straight_edge p e /\
      IMAGE p' e = IMAGE p e`
    (CONJUNCTS_THEN2 (LABEL_TAC "edge_image") (LABEL_TAC "image")) THENL
     [USE_THEN "old_edge_image" MATCH_MP_TAC THEN
      USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `straight_edge (p:A->real^2) e INTER IMAGE p V = IMAGE p e`
    (LABEL_TAC "old") THENL
     [USE_THEN "old_vertices" MATCH_MP_TAC THEN USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((p':A->real^2) v IN
        straight_edge (p:A->real^2) (e:A->bool))`
    (LABEL_TAC "avoids") THENL
     [USE_THEN "old_edges" MATCH_MP_TAC THEN USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[IMAGE_CLAUSES] THEN
    USE_THEN "old_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "edge_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "image" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(SET_RULE
     `(s:real^2->bool) INTER t = i /\ ~(q IN s)
      ==> s INTER (q INSERT t) = i`) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u w:A.
        u IN N /\ w IN N /\ ~({v,u} = {v,w})
        ==> straight_edge (p':A->real^2) {v,u} INTER
            straight_edge p' {v,w} =
            IMAGE p' ({v,u} INTER {v,w})`
  (LABEL_TAC "new_edge_intersections") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN
    INTRO_TAC "u_neighbor w_neighbor edges_distinct" THEN
    SUBGOAL_THEN `(u:A) IN V /\ (w:A) IN V`
    (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex") (LABEL_TAC "w_vertex")) THENL
     [USE_THEN "neighbors" MP_TAC THEN
      REWRITE_TAC[SUBSET] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `~((u:A) = w)` (LABEL_TAC "distinct") THENL
     [DISCH_THEN SUBST_ALL_TAC THEN
      USE_THEN "edges_distinct" MP_TAC THEN REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(p':A->real^2) u = p u /\ p' w = p w`
    (CONJUNCTS_THEN2 (LABEL_TAC "u_image") (LABEL_TAC "w_image")) THENL
     [CONJ_TAC THEN USE_THEN "agrees" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `segment[(p':A->real^2) v,(p:A->real^2) u] INTER
      segment[p' v,p w] = {p' v}`
    (LABEL_TAC "intersection") THENL
     [USE_THEN "new_new" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[STRAIGHT_EDGE_PAIR] THEN
    USE_THEN "u_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "w_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "intersection" (fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN `({v:A,u} INTER {v,w}) = {v}` SUBST1_TAC THENL
     [ASM SET_TAC[];
      REWRITE_TAC[IMAGE_CLAUSES]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u:A e.
        u IN N /\ e IN E
        ==> straight_edge (p':A->real^2) {v,u} INTER straight_edge p' e =
            IMAGE p' ({v,u} INTER e)`
  (LABEL_TAC "new_old_intersections") THENL
   [X_GEN_TAC `u:A` THEN X_GEN_TAC `e:A->bool` THEN
    INTRO_TAC "neighbor edge" THEN
    SUBGOAL_THEN `(u:A) IN V` (LABEL_TAC "u_vertex") THENL
     [USE_THEN "neighbors" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "neighbor" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(p':A->real^2) u = p u` (LABEL_TAC "u_image") THENL
     [USE_THEN "agrees" MATCH_MP_TAC THEN USE_THEN "u_vertex" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `straight_edge (p':A->real^2) e = straight_edge p e /\
      IMAGE p' e = IMAGE p e`
    (CONJUNCTS_THEN2 (LABEL_TAC "edge_image") (LABEL_TAC "image")) THENL
     [USE_THEN "old_edge_image" MATCH_MP_TAC THEN
      USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `segment[(p':A->real^2) v,(p:A->real^2) u] INTER
      straight_edge p e = IMAGE p ({u} INTER e)`
    (LABEL_TAC "intersection") THENL
     [USE_THEN "new_old" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(e:A->bool) SUBSET V` (LABEL_TAC "subset") THENL
     [USE_THEN "edge_subset" MATCH_MP_TAC THEN USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((v:A) IN e)` (LABEL_TAC "v_not_edge") THENL
     [DISCH_THEN(LABEL_TAC "v_edge") THEN
      USE_THEN "fresh" (fun nth ->
        USE_THEN "subset" (fun sth ->
          USE_THEN "v_edge" (fun eth ->
            CONTR_TAC(MP (NOT_ELIM nth)
             (MATCH_MP (SPEC `v:A` (REWRITE_RULE[SUBSET] sth)) eth)))));
      ALL_TAC] THEN
    SUBGOAL_THEN `({v:A,u} INTER e) = {u} INTER e` SUBST1_TAC THENL
     [MATCH_MP_TAC(SET_RULE
       `~((v:A) IN e) ==> {v,u} INTER e = {u} INTER e`) THEN
      USE_THEN "v_not_edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `IMAGE (p':A->real^2) ({u} INTER e) = IMAGE p ({u} INTER e)`
    SUBST1_TAC THENL
     [MATCH_MP_TAC IMAGE_EQ THEN X_GEN_TAC `x:A` THEN
      REWRITE_TAC[IN_INTER; IN_SING] THEN
      DISCH_THEN(CONJUNCTS_THEN2 SUBST1_TAC (LABEL_TAC "u_edge")) THEN
      USE_THEN "u_image" ACCEPT_TAC;
      REWRITE_TAC[STRAIGHT_EDGE_PAIR] THEN
      USE_THEN "u_image" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "edge_image" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "intersection" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!e e':A->bool.
        e IN E /\ e' IN E /\ ~(e = e')
        ==> straight_edge (p':A->real^2) e INTER straight_edge p' e' =
            IMAGE p' (e INTER e')`
  (LABEL_TAC "old_edge_intersections") THENL
   [MAP_EVERY X_GEN_TAC [`e:A->bool`; `e':A->bool`] THEN
    INTRO_TAC "edge edge' distinct" THEN
    SUBGOAL_THEN
     `straight_edge (p':A->real^2) e = straight_edge p e /\
      IMAGE p' e = IMAGE p e`
    (CONJUNCTS_THEN2 (LABEL_TAC "edge_image") (LABEL_TAC "image")) THENL
     [USE_THEN "old_edge_image" MATCH_MP_TAC THEN
      USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `straight_edge (p':A->real^2) e' = straight_edge p e' /\
      IMAGE p' e' = IMAGE p e'`
    (CONJUNCTS_THEN2 (LABEL_TAC "edge'_image") (LABEL_TAC "image'")) THENL
     [USE_THEN "old_edge_image" MATCH_MP_TAC THEN
      USE_THEN "edge'" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `straight_edge (p:A->real^2) e INTER straight_edge p e' =
      IMAGE p (e INTER e')`
    (LABEL_TAC "intersection") THENL
     [USE_THEN "old_intersections" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(e:A->bool) SUBSET V` (LABEL_TAC "subset") THENL
     [USE_THEN "edge_subset" MATCH_MP_TAC THEN USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `IMAGE (p':A->real^2) (e INTER e') = IMAGE p (e INTER e')`
    SUBST1_TAC THENL
     [MATCH_MP_TAC IMAGE_EQ THEN X_GEN_TAC `x:A` THEN
      REWRITE_TAC[IN_INTER] THEN INTRO_TAC "in_edge in_edge'" THEN
      USE_THEN "agrees" MATCH_MP_TAC THEN
      USE_THEN "subset" (fun sth ->
        USE_THEN "in_edge" (fun eth ->
          ACCEPT_TAC
           (MATCH_MP (SPEC `x:A` (REWRITE_RULE[SUBSET] sth)) eth)));
      USE_THEN "edge_image" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "edge'_image" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "intersection" ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[straight_line_embedding] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[INJ; IN_UNIV; IN_INSERT] THEN
    MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    INTRO_TAC "x_vertex y_vertex equal" THEN
    ASM_CASES_TAC `(x:A) = v` THENL
     [ASM_CASES_TAC `(y:A) = v` THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(y:A) IN V` (LABEL_TAC "y_old") THENL
       [ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(p':A->real^2) y = p y` (LABEL_TAC "y_image") THENL
       [USE_THEN "agrees" MATCH_MP_TAC THEN USE_THEN "y_old" ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "new_vertex" MP_TAC THEN
      REWRITE_TAC[IN_IMAGE] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    ASM_CASES_TAC `(y:A) = v` THENL
     [SUBGOAL_THEN `(x:A) IN V` (LABEL_TAC "x_old") THENL
       [ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(p':A->real^2) x = p x` (LABEL_TAC "x_image") THENL
       [USE_THEN "agrees" MATCH_MP_TAC THEN USE_THEN "x_old" ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "new_vertex" MP_TAC THEN
      REWRITE_TAC[IN_IMAGE] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(x:A) IN V /\ (y:A) IN V`
    (CONJUNCTS_THEN2 (LABEL_TAC "x_old") (LABEL_TAC "y_old")) THENL
     [ASM_MESON_TAC[];
      ALL_TAC] THEN
    USE_THEN "old_injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV] THEN
    DISCH_THEN(MP_TAC o SPECL [`x:A`; `y:A`]) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    SUBGOAL_THEN `(p':A->real^2) x = p x` (LABEL_TAC "x_image") THENL
     [USE_THEN "agrees" MATCH_MP_TAC THEN USE_THEN "x_old" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(p':A->real^2) y = p y` (LABEL_TAC "y_image") THENL
     [USE_THEN "agrees" MATCH_MP_TAC THEN USE_THEN "y_old" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "x_image" (fun xth ->
      USE_THEN "equal" (fun eth ->
        USE_THEN "y_image" (fun yth ->
          ACCEPT_TAC(TRANS (TRANS (SYM xth) eth) yth))));
    X_GEN_TAC `e:A->bool` THEN
    REWRITE_TAC[IN_UNION] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "new") (LABEL_TAC "old")) THENL
     [USE_THEN "new" MP_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
      INTRO_TAC "@u. edge_eq neighbor" THEN
      USE_THEN "edge_eq" SUBST1_TAC THEN
      USE_THEN "new_edge_vertices" MATCH_MP_TAC THEN
      USE_THEN "neighbor" ACCEPT_TAC;
      USE_THEN "old_edge_vertices" MATCH_MP_TAC THEN
      USE_THEN "old" ACCEPT_TAC];
    MAP_EVERY X_GEN_TAC [`e:A->bool`; `e':A->bool`] THEN
    INTRO_TAC "edge edge' distinct" THEN
    USE_THEN "edge" MP_TAC THEN REWRITE_TAC[IN_UNION] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "new") (LABEL_TAC "old")) THENL
     [USE_THEN "new" MP_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
