      USE_THEN "edge_eq" SUBST_ALL_TAC THEN
      USE_THEN "edge'" MP_TAC THEN REWRITE_TAC[IN_UNION] THEN
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "new'") (LABEL_TAC "old'")) THENL
       [USE_THEN "new'" MP_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
