        USE_THEN "edge'_eq" SUBST_ALL_TAC THEN
        USE_THEN "new_edge_intersections" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
        USE_THEN "new_old_intersections" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[]];
      USE_THEN "edge'" MP_TAC THEN REWRITE_TAC[IN_UNION] THEN
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "new'") (LABEL_TAC "old'")) THENL
       [USE_THEN "new'" MP_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
        INTRO_TAC "@w. edge'_eq neighbor'" THEN
        USE_THEN "edge'_eq" SUBST_ALL_TAC THEN
        ONCE_REWRITE_TAC[INTER_COMM] THEN
        USE_THEN "new_old_intersections" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
        USE_THEN "old_edge_intersections" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[]]]]);;

let STRAIGHT_LINE_EMBEDDING_IMP_PLANE_GRAPH_EMBEDDING = prove
 (`!V E p.
        finite_simple_graph (V:A->bool) E /\
        straight_line_embedding V E p
        ==> plane_graph_embedding V E p (straight_edge p)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[straight_line_embedding; plane_graph_embedding] THEN
  DISCH_THEN
   (CONJUNCTS_THEN2 (LABEL_TAC "graph")
     (CONJUNCTS_THEN2 (LABEL_TAC "injective")
       (CONJUNCTS_THEN2 (LABEL_TAC "vertices") (LABEL_TAC "edges")))) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "injective" ACCEPT_TAC;
    X_GEN_TAC `e:A->bool` THEN DISCH_TAC THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`]
     FINITE_SIMPLE_GRAPH_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A`
     (X_CHOOSE_THEN `v:A` STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `linepath((p:A->real^2) u,p v)` THEN
    SUBGOAL_THEN `~((p:A->real^2) u = p v)` ASSUME_TAC THENL
     [USE_THEN "injective" MP_TAC THEN
      REWRITE_TAC[INJ; IN_UNIV] THEN ASM_MESON_TAC[];
      ASM_REWRITE_TAC[ARC_LINEPATH_EQ; PATH_IMAGE_LINEPATH;
                      PATHSTART_LINEPATH; PATHFINISH_LINEPATH;
                      STRAIGHT_EDGE_PAIR; IMAGE_CLAUSES]];
    USE_THEN "vertices" ACCEPT_TAC;
    USE_THEN "edges" ACCEPT_TAC]);;

let STRAIGHT_LINE_PLANAR_IMP_PLANAR_GRAPH = prove
 (`!V E.
        straight_line_planar_graph (V:A->bool) E
        ==> planar_graph V E`,
  REWRITE_TAC[straight_line_planar_graph; planar_graph] THEN
  MESON_TAC[STRAIGHT_LINE_EMBEDDING_IMP_PLANE_GRAPH_EMBEDDING]);;

let STRAIGHT_LINE_EMBEDDING_IMP_POLYGONAL_PLANE_GRAPH_EMBEDDING = prove
 (`!V E p.
        finite_simple_graph (V:A->bool) E /\
        straight_line_embedding V E p
        ==> polygonal_plane_graph_embedding V E p (straight_edge p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[polygonal_plane_graph_embedding] THEN CONJ_TAC THENL
   [MATCH_MP_TAC STRAIGHT_LINE_EMBEDDING_IMP_PLANE_GRAPH_EMBEDDING THEN
    ASM_REWRITE_TAC[];
    X_GEN_TAC `e:A->bool` THEN DISCH_TAC THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`]
     FINITE_SIMPLE_GRAPH_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A`
     (X_CHOOSE_THEN `v:A` STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `linepath((p:A->real^2) u,p v)` THEN
    SUBGOAL_THEN `~((p:A->real^2) u = p v)` ASSUME_TAC THENL
     [UNDISCH_TAC `straight_line_embedding
        (V:A->bool) (E:(A->bool)->bool) p` THEN
      REWRITE_TAC[straight_line_embedding; INJ; IN_UNIV] THEN
      ASM_MESON_TAC[];
      CONJ_TAC THENL
       [MATCH_MP_TAC POLYGONAL_ARC_LINEPATH THEN ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[PATH_IMAGE_LINEPATH; STRAIGHT_EDGE_PAIR]]]]);;

let STRAIGHT_LINE_PLANAR_IMP_POLYGONALLY_PLANAR = prove
 (`!V E.
        straight_line_planar_graph (V:A->bool) E
        ==> polygonally_planar_graph V E`,
  REWRITE_TAC[straight_line_planar_graph; polygonally_planar_graph] THEN
  MESON_TAC[
    STRAIGHT_LINE_EMBEDDING_IMP_POLYGONAL_PLANE_GRAPH_EMBEDDING]);;

(* ------------------------------------------------------------------------- *)
(* Numerically indexed simple cycles.                                        *)
(* ------------------------------------------------------------------------- *)

let cyclic_indices = new_definition
 `cyclic_indices n = {i:num | i < n}`;;

let cyclic_vertices = new_definition
 `cyclic_vertices (q:num->A) n = IMAGE q (cyclic_indices n)`;;

let cyclic_edges = new_definition
 `cyclic_edges (q:num->A) n =
        IMAGE (\i. {q i,q ((i + 1) MOD n)}) (cyclic_indices n)`;;

let simple_graph_cycle = new_definition
 `simple_graph_cycle (E:(A->bool)->bool) (q:num->A) n <=>
        3 <= n /\
        INJ q (cyclic_indices n) (:A) /\
        cyclic_edges q n SUBSET E`;;

let IN_CYCLIC_INDICES = prove
 (`!i n. i IN cyclic_indices n <=> i < n`,
  REWRITE_TAC[cyclic_indices; IN_ELIM_THM]);;

let FINITE_CYCLIC_INDICES = prove
 (`!n. FINITE(cyclic_indices n)`,
  REWRITE_TAC[cyclic_indices; FINITE_NUMSEG_LT]);;

let CARD_CYCLIC_INDICES = prove
 (`!n. CARD(cyclic_indices n) = n`,
  REWRITE_TAC[cyclic_indices; CARD_NUMSEG_LT]);;

let IN_CYCLIC_VERTICES = prove
 (`!q:num->A n x.
        x IN cyclic_vertices q n <=> ?i. i < n /\ x = q i`,
  REWRITE_TAC[cyclic_vertices; IN_IMAGE; IN_CYCLIC_INDICES] THEN
  MESON_TAC[]);;

let IN_CYCLIC_EDGES = prove
 (`!q:num->A n e.
        e IN cyclic_edges q n <=>
        ?i. i < n /\ e = {q i,q ((i + 1) MOD n)}`,
  REWRITE_TAC[cyclic_edges; IN_IMAGE; IN_CYCLIC_INDICES] THEN
  MESON_TAC[]);;

let FINITE_CYCLIC_VERTICES = prove
 (`!q:num->A n. FINITE(cyclic_vertices q n)`,
  REWRITE_TAC[cyclic_vertices] THEN
  MESON_TAC[FINITE_IMAGE; FINITE_CYCLIC_INDICES]);;

let FINITE_CYCLIC_EDGES = prove
 (`!q:num->A n. FINITE(cyclic_edges q n)`,
  REWRITE_TAC[cyclic_edges] THEN
  MESON_TAC[FINITE_IMAGE; FINITE_CYCLIC_INDICES]);;

let CYCLIC_SUCCESSOR_NE = prove
 (`!n i. 2 <= n /\ i < n ==> ~((i + 1) MOD n = i)`,
  REPEAT GEN_TAC THEN INTRO_TAC "large index" THEN
  MP_TAC(SPECL [`i + 1`; `n:num`] MOD_CASES) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN SUBST1_TAC] THEN
  COND_CASES_TAC THENL
   [ARITH_TAC;
    DISCH_THEN(LABEL_TAC "equal") THEN
    SUBGOAL_THEN `(i + 1) - n + n = i + 1`
    (LABEL_TAC "subadd") THENL
     [MATCH_MP_TAC SUB_ADD THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `i + n = i + 1` (LABEL_TAC "relation") THENL
     [USE_THEN "subadd" MP_TAC THEN
      USE_THEN "equal" (fun th -> REWRITE_TAC[th]);
      ALL_TAC] THEN
    USE_THEN "relation" MP_TAC THEN
    REWRITE_TAC[EQ_ADD_LCANCEL] THEN ASM_ARITH_TAC]);;

let CARD_CYCLIC_VERTICES = prove
 (`!q:num->A n.
        INJ q (cyclic_indices n) (:A)
        ==> CARD(cyclic_vertices q n) = n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "injective") THEN
  REWRITE_TAC[cyclic_vertices] THEN
  TRANS_TAC EQ_TRANS `CARD(cyclic_indices n)` THEN CONJ_TAC THENL
   [MATCH_MP_TAC CARD_IMAGE_INJ THEN CONJ_TAC THENL
     [USE_THEN "injective" MP_TAC THEN
      REWRITE_TAC[INJ; IN_UNIV] THEN MESON_TAC[];
      MATCH_ACCEPT_TAC FINITE_CYCLIC_INDICES];
    MATCH_ACCEPT_TAC CARD_CYCLIC_INDICES]);;

let CYCLIC_EDGE_SUBSET_VERTICES = prove
 (`!q:num->A n e.
        0 < n /\ e IN cyclic_edges q n
        ==> e SUBSET cyclic_vertices q n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_CYCLIC_EDGES] THEN
  INTRO_TAC "positive @i. index edge_eq" THEN
  USE_THEN "edge_eq" SUBST1_TAC THEN
  REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_CYCLIC_VERTICES] THEN
  CONJ_TAC THENL
   [EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[];
    EXISTS_TAC `(i + 1) MOD n` THEN
    ASM_REWRITE_TAC[MOD_LT_EQ_LT]]);;

let CYCLIC_EDGE_HAS_SIZE = prove
 (`!q:num->A n e.
        2 <= n /\
        INJ q (cyclic_indices n) (:A) /\
        e IN cyclic_edges q n
        ==> e HAS_SIZE 2`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_CYCLIC_EDGES] THEN
  INTRO_TAC "large injective @i. index edge_eq" THEN
  USE_THEN "edge_eq" SUBST1_TAC THEN
  SUBGOAL_THEN `(i + 1) MOD n < n`
  (LABEL_TAC "successor_index") THENL
   [ASM_REWRITE_TAC[MOD_LT_EQ_LT] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((i + 1) MOD n = i)`
  (LABEL_TAC "index_distinct") THENL
   [MATCH_MP_TAC CYCLIC_SUCCESSOR_NE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((q:num->A) i = q ((i + 1) MOD n))`
  (LABEL_TAC "distinct") THENL
   [DISCH_THEN(LABEL_TAC "same_image") THEN
    USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV] THEN
    REWRITE_TAC[NOT_FORALL_THM] THEN
    MAP_EVERY EXISTS_TAC [`i:num`; `(i + 1) MOD n`] THEN
    ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
    REWRITE_TAC[HAS_SIZE_CONV
     `({(q:num->A) i,q ((i + 1) MOD n)}:A->bool) HAS_SIZE 2`] THEN
    MAP_EVERY EXISTS_TAC
     [`(q:num->A) i`; `(q:num->A) ((i + 1) MOD n)`] THEN
    ASM_REWRITE_TAC[]]);;

let FINITE_SIMPLE_GRAPH_CYCLIC = prove
 (`!E q:num->A n.
        simple_graph_cycle E q n
        ==> finite_simple_graph (cyclic_vertices q n) (cyclic_edges q n)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective subset" THEN
  REWRITE_TAC[finite_simple_graph] THEN REPEAT CONJ_TAC THENL
   [MATCH_ACCEPT_TAC FINITE_CYCLIC_VERTICES;
    MATCH_ACCEPT_TAC FINITE_CYCLIC_EDGES;
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `e:A->bool`]
       CYCLIC_EDGE_SUBSET_VERTICES) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `e:A->bool`]
       CYCLIC_EDGE_HAS_SIZE) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]]);;

(* ------------------------------------------------------------------------- *)
(* Splitting an indexed cycle along a chord to its last vertex.              *)
(* ------------------------------------------------------------------------- *)

let cyclic_split_left = new_definition
 `cyclic_split_left (q:num->A) n j i =
        if i < j + 1 then q i else q (n - 1)`;;

let cyclic_split_right = new_definition
 `cyclic_split_right (q:num->A) j i = q (j + i)`;;

let CYCLIC_SPLIT_LEFT_INJ = prove
 (`!q:num->A n j.
        INJ q (cyclic_indices n) (:A) /\ j + 2 < n
        ==> INJ (cyclic_split_left q n j)
                (cyclic_indices (j + 2)) (:A)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
  INTRO_TAC "injective bound" THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `k:num`] THEN
  INTRO_TAC "i_index k_index equal" THEN
  ASM_CASES_TAC `i < j + 1` THEN
  ASM_CASES_TAC `k < j + 1` THENL
   [REMOVE_THEN "equal" MP_TAC THEN
    REWRITE_TAC[cyclic_split_left] THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(LABEL_TAC "images_equal") THEN
    USE_THEN "injective"
     (MATCH_MP_TAC o SPECL [`i:num`; `k:num`]) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    REMOVE_THEN "equal" MP_TAC THEN
    REWRITE_TAC[cyclic_split_left] THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(LABEL_TAC "images_equal") THEN
    SUBGOAL_THEN `n - 1 < n` (LABEL_TAC "last_index") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `i = n - 1` (LABEL_TAC "i_last") THENL
     [USE_THEN "injective"
       (MATCH_MP_TAC o SPECL [`i:num`; `n - 1`]) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ASM_ARITH_TAC];
    REMOVE_THEN "equal" MP_TAC THEN
    REWRITE_TAC[cyclic_split_left] THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(LABEL_TAC "images_equal") THEN
    SUBGOAL_THEN `n - 1 < n` (LABEL_TAC "last_index") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `k = n - 1` (LABEL_TAC "k_last") THENL
     [USE_THEN "injective"
       (MATCH_MP_TAC o SPECL [`k:num`; `n - 1`]) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ASM_ARITH_TAC];
    ASM_ARITH_TAC]);;

let CYCLIC_SPLIT_RIGHT_INJ = prove
 (`!q:num->A n j.
        INJ q (cyclic_indices n) (:A) /\ j < n
        ==> INJ (cyclic_split_right q j)
                (cyclic_indices (n - j)) (:A)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES;
              cyclic_split_right] THEN
  INTRO_TAC "injective j_index" THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `k:num`] THEN
  INTRO_TAC "i_index k_index equal" THEN
  SUBGOAL_THEN `j + i < n /\ j + k < n`
  (CONJUNCTS_THEN2 (LABEL_TAC "old_i") (LABEL_TAC "old_k")) THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `j + i = j + k` (LABEL_TAC "indices_equal") THENL
   [USE_THEN "injective"
     (MATCH_MP_TAC o SPECL [`j + i`; `j + k`]) THEN
    ASM_REWRITE_TAC[];
    USE_THEN "indices_equal" MP_TAC THEN
    REWRITE_TAC[EQ_ADD_LCANCEL]]);;

let CYCLIC_SPLIT_LEFT_EDGES = prove
 (`!q:num->A n j e.
        j + 2 < n /\
        e IN cyclic_edges (cyclic_split_left q n j) (j + 2)
        ==> e IN cyclic_edges q n \/ e = {q j,q (n - 1)}`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_CYCLIC_EDGES] THEN
  INTRO_TAC "bound @i. index edge_eq" THEN
  USE_THEN "edge_eq" SUBST1_TAC THEN
  ASM_CASES_TAC `i < j` THENL
   [DISJ1_TAC THEN EXISTS_TAC `i:num` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      SUBGOAL_THEN `(i + 1) MOD (j + 2) = i + 1`
      SUBST1_TAC THENL
       [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(i + 1) MOD n = i + 1`
      SUBST1_TAC THENL
       [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      ASM_SIMP_TAC[cyclic_split_left] THEN ASM_ARITH_TAC];
    ASM_CASES_TAC `(i:num) = j` THENL
     [DISJ2_TAC THEN
      SUBGOAL_THEN `(i + 1) MOD (j + 2) = j + 1`
      SUBST1_TAC THENL
       [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOD_LT THEN ARITH_TAC;
        ASM_REWRITE_TAC[cyclic_split_left] THEN ARITH_TAC];
      SUBGOAL_THEN `i = j + 1` SUBST_ALL_TAC THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `((j + 1) + 1) MOD (j + 2) = 0`
      (LABEL_TAC "left_wrap") THENL
       [SUBGOAL_THEN `(j + 1) + 1 = j + 2` SUBST1_TAC THENL
         [ARITH_TAC;
          REWRITE_TAC[MOD_REFL]];
        ALL_TAC] THEN
      SUBGOAL_THEN `(n - 1 + 1) MOD n = 0`
      (LABEL_TAC "old_wrap") THENL
       [SUBGOAL_THEN `n - 1 + 1 = n` SUBST1_TAC THENL
         [ASM_ARITH_TAC;
          REWRITE_TAC[MOD_REFL]];
        ALL_TAC] THEN
      DISJ1_TAC THEN EXISTS_TAC `n - 1` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        ASM_REWRITE_TAC[cyclic_split_left] THEN
        REWRITE_TAC[LT_REFL] THEN ASM_ARITH_TAC]]]);;

let CYCLIC_SPLIT_RIGHT_EDGES = prove
 (`!q:num->A n j e.
        j + 2 < n /\
        e IN cyclic_edges (cyclic_split_right q j) (n - j)
        ==> e IN cyclic_edges q n \/ e = {q j,q (n - 1)}`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_CYCLIC_EDGES] THEN
  INTRO_TAC "bound @i. index edge_eq" THEN
  USE_THEN "edge_eq" SUBST1_TAC THEN
  ASM_CASES_TAC `i + 1 < n - j` THENL
   [SUBGOAL_THEN `(i + 1) MOD (n - j) = i + 1`
    (LABEL_TAC "next") THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `((j + i) + 1) MOD n = (j + i) + 1`
    (LABEL_TAC "old_next") THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    DISJ1_TAC THEN EXISTS_TAC `j + i` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      ASM_REWRITE_TAC[cyclic_split_right; ADD_ASSOC]];
    SUBGOAL_THEN `i + 1 = n - j` (LABEL_TAC "at_end") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `j + i = n - 1` (LABEL_TAC "last") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(i + 1) MOD (n - j) = 0`
    (LABEL_TAC "wrap") THENL
     [USE_THEN "at_end" (fun th -> REWRITE_TAC[th; MOD_REFL]);
      ALL_TAC] THEN
    DISJ2_TAC THEN
    ASM_REWRITE_TAC[cyclic_split_right; ADD_CLAUSES] THEN
    SET_TAC[]]);;

let SIMPLE_GRAPH_CYCLE_SPLIT_LEFT = prove
 (`!E q:num->A n j.
        simple_graph_cycle E q n /\
        0 < j /\ j + 2 < n /\ {q j,q (n - 1)} IN E
        ==> simple_graph_cycle E (cyclic_split_left q n j) (j + 2)`,
  REPEAT GEN_TAC THEN INTRO_TAC "cycle j_positive bound chord" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective edges" THEN
  REWRITE_TAC[simple_graph_cycle] THEN REPEAT CONJ_TAC THENL
   [ASM_ARITH_TAC;
    MATCH_MP_TAC CYCLIC_SPLIT_LEFT_INJ THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[SUBSET] THEN X_GEN_TAC `e:A->bool` THEN
    DISCH_THEN(LABEL_TAC "split_edge") THEN
    MP_TAC(ISPECL
     [`q:num->A`; `n:num`; `j:num`; `e:A->bool`]
     CYCLIC_SPLIT_LEFT_EDGES) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(DISJ_CASES_THEN2
     (LABEL_TAC "old_edge") (LABEL_TAC "chord_edge")) THENL
     [USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "old_edge" ACCEPT_TAC;
      USE_THEN "chord_edge" SUBST1_TAC THEN
      USE_THEN "chord" ACCEPT_TAC]]);;

let SIMPLE_GRAPH_CYCLE_SPLIT_RIGHT = prove
 (`!E q:num->A n j.
        simple_graph_cycle E q n /\
        0 < j /\ j + 2 < n /\ {q j,q (n - 1)} IN E
        ==> simple_graph_cycle E (cyclic_split_right q j) (n - j)`,
  REPEAT GEN_TAC THEN INTRO_TAC "cycle j_positive bound chord" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective edges" THEN
  REWRITE_TAC[simple_graph_cycle] THEN REPEAT CONJ_TAC THENL
   [ASM_ARITH_TAC;
    MATCH_MP_TAC CYCLIC_SPLIT_RIGHT_INJ THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    REWRITE_TAC[SUBSET] THEN X_GEN_TAC `e:A->bool` THEN
    DISCH_THEN(LABEL_TAC "split_edge") THEN
    MP_TAC(ISPECL
     [`q:num->A`; `n:num`; `j:num`; `e:A->bool`]
     CYCLIC_SPLIT_RIGHT_EDGES) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(DISJ_CASES_THEN2
     (LABEL_TAC "old_edge") (LABEL_TAC "chord_edge")) THENL
     [USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "old_edge" ACCEPT_TAC;
      USE_THEN "chord_edge" SUBST1_TAC THEN
      USE_THEN "chord" ACCEPT_TAC]]);;

(* ------------------------------------------------------------------------- *)
(* Strictly convex indexed polygons and splitting along a chord.             *)
(* ------------------------------------------------------------------------- *)

let plane_orientation = new_definition
 `plane_orientation (a:real^2) (b:real^2) (c:real^2) =
        (b$1 - a$1) * (c$2 - a$2) -
        (b$2 - a$2) * (c$1 - a$1)`;;

let strictly_convex_cycle = new_definition
 `strictly_convex_cycle (z:num->real^2) n <=>
        !i j k. i < j /\ j < k /\ k < n
                 ==> &0 < plane_orientation (z i) (z j) (z k)`;;

let PLANE_ORIENTATION_DOT = prove
 (`!a b c:real^2.
        plane_orientation a b c =
        vector[a$2 - b$2;b$1 - a$1] dot (c - a)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_orientation; DOT_2; VECTOR_2; VECTOR_SUB_COMPONENT] THEN
  CONV_TAC REAL_RING);;

let PLANE_ORIENTATION_CYCLIC = prove
 (`!a b c:real^2.
        plane_orientation a b c = plane_orientation b c a`,
  REPEAT GEN_TAC THEN REWRITE_TAC[plane_orientation] THEN REAL_ARITH_TAC);;

let PLANE_ORIENTATION_SWAP = prove
 (`!a b c:real^2.
        plane_orientation a c b = --(plane_orientation a b c)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[plane_orientation] THEN REAL_ARITH_TAC);;

let PLANE_ORIENTATION_REFL = prove
 (`(!a b:real^2. plane_orientation a a b = &0) /\
   (!a b:real^2. plane_orientation a b a = &0) /\
   (!a b:real^2. plane_orientation a b b = &0)`,
  REPEAT CONJ_TAC THEN REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_orientation] THEN REAL_ARITH_TAC);;

let CONVEX_PLANE_ORIENTATION_GE = prove
 (`!a b:real^2. convex {x | &0 <= plane_orientation a b x}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[PLANE_ORIENTATION_DOT; DOT_RSUB; REAL_SUB_LE] THEN
  REWRITE_TAC[GSYM real_ge; CONVEX_HALFSPACE_GE]);;

let CONVEX_PLANE_ORIENTATION_LE = prove
 (`!a b:real^2. convex {x | plane_orientation a b x <= &0}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[PLANE_ORIENTATION_DOT; DOT_RSUB;
              REAL_ARITH `x - y <= &0 <=> x <= y`;
              CONVEX_HALFSPACE_LE]);;

let CONVEX_HULL_SUBSET_PLANE_ORIENTATION_GE = prove
 (`!s a b:real^2.
        (!x. x IN s ==> &0 <= plane_orientation a b x)
        ==> convex hull s SUBSET {x | &0 <= plane_orientation a b x}`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "side") THEN
  MATCH_MP_TAC HULL_MINIMAL THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
    USE_THEN "side" ACCEPT_TAC;
    MATCH_ACCEPT_TAC CONVEX_PLANE_ORIENTATION_GE]);;

let CONVEX_HULL_SUBSET_PLANE_ORIENTATION_LE = prove
 (`!s a b:real^2.
        (!x. x IN s ==> plane_orientation a b x <= &0)
        ==> convex hull s SUBSET {x | plane_orientation a b x <= &0}`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "side") THEN
  MATCH_MP_TAC HULL_MINIMAL THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
    USE_THEN "side" ACCEPT_TAC;
    MATCH_ACCEPT_TAC CONVEX_PLANE_ORIENTATION_LE]);;

let STRICTLY_CONVEX_CYCLE_SPLIT_LEFT = prove
 (`!z:num->real^2. !n j.
        strictly_convex_cycle z n /\ j + 2 < n
        ==> strictly_convex_cycle (cyclic_split_left z n j) (j + 2)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[strictly_convex_cycle] THEN
  INTRO_TAC "convex bound" THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `k:num`; `l:num`] THEN
  INTRO_TAC "ik kl l_index" THEN
  SUBGOAL_THEN `i < j + 1 /\ k < j + 1`
  (CONJUNCTS_THEN2 (LABEL_TAC "i_early") (LABEL_TAC "k_early")) THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[cyclic_split_left] THEN ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `l < j + 1` THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "convex" MATCH_MP_TAC THEN
    ASM_ARITH_TAC;
    ASM_REWRITE_TAC[] THEN USE_THEN "convex" MATCH_MP_TAC THEN
    ASM_ARITH_TAC]);;

let STRICTLY_CONVEX_CYCLE_SPLIT_RIGHT = prove
 (`!z:num->real^2. !n j.
        strictly_convex_cycle z n /\ j + 2 < n
        ==> strictly_convex_cycle (cyclic_split_right z j) (n - j)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[strictly_convex_cycle; cyclic_split_right] THEN
  INTRO_TAC "convex bound" THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `k:num`; `l:num`] THEN
  INTRO_TAC "ik kl l_index" THEN
  USE_THEN "convex" (MP_TAC o SPECL [`j + i`; `j + k`; `j + l`]) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    REWRITE_TAC[ADD_ASSOC]]);;

let DOT_VSUM_AFFINE = prove
 (`!s:A->bool. !u:A->real. !f:A->real^N. !a:real^N. !b.
        FINITE s /\ sum s u = &1
        ==> a dot (vsum s (\x. u x % f x)) - b =
            sum s (\x. u x * (a dot f x - b))`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite sum_one" THEN
  ASM_SIMP_TAC[REAL_SUB_LDISTRIB; SUM_SUB; DOT_RSUM; DOT_RMUL; SUM_RMUL] THEN
  ASM_REAL_ARITH_TAC);;

let IN_CONVEX_HULL_SUPPORTING_HYPERPLANE_GE = prove
 (`!s:real^N->bool. !a x:real^N. !b.
        FINITE s /\
        (!y. y IN s ==> b <= a dot y) /\
        x IN convex hull s /\ a dot x = b
        ==> x IN convex hull {y | y IN s /\ a dot y = b}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite supporting in_hull on_plane" THEN
  USE_THEN "in_hull" MP_TAC THEN
  REWRITE_TAC[CONVEX_HULL_FINITE; IN_ELIM_THM] THEN
  INTRO_TAC "@u. nonnegative sum_one combination" THEN
  SUBGOAL_THEN
   `sum s (\y:real^N. u y * (a dot y - b)) = &0`
  (LABEL_TAC "weighted_zero") THENL
   [MP_TAC(ISPECL
     [`s:real^N->bool`; `u:real^N->real`; `\y:real^N. y`;
      `a:real^N`; `b:real`] DOT_VSUM_AFFINE) THEN
    ASM_REWRITE_TAC[REAL_SUB_REFL] THEN BETA_TAC THEN
    DISCH_THEN(fun th -> ACCEPT_TAC(SYM th));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y:real^N. y IN s ==> &0 <= u y * (a dot y - b)`
  (LABEL_TAC "products_nonnegative") THENL
   [X_GEN_TAC `y:real^N` THEN DISCH_THEN(LABEL_TAC "in_set") THEN
    MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [USE_THEN "nonnegative" MATCH_MP_TAC THEN
      USE_THEN "in_set" ACCEPT_TAC;
      REWRITE_TAC[REAL_SUB_LE] THEN
      USE_THEN "supporting" MATCH_MP_TAC THEN
      USE_THEN "in_set" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y:real^N. y IN s ==> u y * (a dot y - b) = &0`
  (LABEL_TAC "products_zero") THENL
   [MATCH_MP_TAC(BETA_RULE(ISPECL
     [`\y:real^N. u y * (a dot y - b)`; `s:real^N->bool`]
     SUM_POS_EQ_0)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y:real^N. y IN s /\ ~(a dot y = b) ==> u y = &0`
  (LABEL_TAC "off_plane_zero") THENL
   [X_GEN_TAC `y:real^N` THEN INTRO_TAC "in_set off_plane" THEN
    USE_THEN "products_zero" (fun th ->
      MP_TAC(MATCH_MP (SPEC `y:real^N` th)
       (ASSUME `(y:real^N) IN s`))) THEN
    ASM_REWRITE_TAC[REAL_ENTIRE; REAL_SUB_0];
    ALL_TAC] THEN
  REWRITE_TAC[CONVEX_HULL_FINITE; IN_ELIM_THM] THEN
  EXISTS_TAC `u:real^N->real` THEN REPEAT CONJ_TAC THENL
   [X_GEN_TAC `y:real^N` THEN REWRITE_TAC[IN_ELIM_THM] THEN
    INTRO_TAC "in_set on_plane_here" THEN
    USE_THEN "nonnegative" MATCH_MP_TAC THEN
    USE_THEN "in_set" ACCEPT_TAC;
    SUBGOAL_THEN
     `sum s (u:real^N->real) =
      sum {y:real^N | y IN s /\ a dot y = b} u`
    (fun th -> ASM_REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC SUM_SUPERSET THEN CONJ_TAC THENL
     [SET_TAC[];
      X_GEN_TAC `y:real^N` THEN REWRITE_TAC[IN_ELIM_THM] THEN
      INTRO_TAC "in_set not_in_face" THEN
      SUBGOAL_THEN `~(a dot (y:real^N) = b)`
      (LABEL_TAC "off_plane_here") THENL
       [DISCH_THEN(LABEL_TAC "on_plane_here") THEN
        CONTR_TAC(MP
         (NOT_ELIM(ASSUME `~((y:real^N) IN s /\ a dot y = b)`))
         (CONJ (ASSUME `(y:real^N) IN s`)
               (ASSUME `a dot (y:real^N) = b`)));
        USE_THEN "off_plane_zero" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[]]];
    SUBGOAL_THEN
     `vsum s (\y:real^N. u y % y) =
      vsum {y:real^N | y IN s /\ a dot y = b} (\y. u y % y)`
    (fun th -> ASM_REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC VSUM_SUPERSET THEN CONJ_TAC THENL
     [SET_TAC[];
      X_GEN_TAC `y:real^N` THEN REWRITE_TAC[IN_ELIM_THM] THEN
      INTRO_TAC "in_set not_in_face" THEN
      SUBGOAL_THEN `~(a dot (y:real^N) = b)`
      (LABEL_TAC "off_plane_here") THENL
       [DISCH_THEN(LABEL_TAC "on_plane_here") THEN
        CONTR_TAC(MP
         (NOT_ELIM(ASSUME `~((y:real^N) IN s /\ a dot y = b)`))
         (CONJ (ASSUME `(y:real^N) IN s`)
               (ASSUME `a dot (y:real^N) = b`)));
        ALL_TAC] THEN
      SUBGOAL_THEN `(u:real^N->real) y = &0`
      (LABEL_TAC "coefficient_zero") THENL
       [USE_THEN "off_plane_zero" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[VECTOR_MUL_LZERO]]]]);;

let STRICTLY_CONVEX_CYCLE_SPLIT_LEFT_ORIENTATION = prove
 (`!z:num->real^2. !n j i.
        strictly_convex_cycle z n /\ j + 2 < n /\ i < j + 2
        ==> &0 <= plane_orientation (z j) (z (n - 1))
                    (cyclic_split_left z n j i) /\
            (plane_orientation (z j) (z (n - 1))
               (cyclic_split_left z n j i) = &0
             ==> cyclic_split_left z n j i = z j \/
                 cyclic_split_left z n j i = z (n - 1))`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex bound index" THEN
  SUBGOAL_THEN `i < j \/ (i:num) = j \/ i = j + 1` MP_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN
     (DISJ_CASES_THEN2 (LABEL_TAC "before")
      (DISJ_CASES_THEN2 (LABEL_TAC "first") (LABEL_TAC "last")))] THENL
   [SUBGOAL_THEN `i < j + 1` (LABEL_TAC "early") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `&0 < plane_orientation (z j) (z (n - 1)) (z i)`
    (LABEL_TAC "positive") THENL
     [USE_THEN "convex" MP_TAC THEN
      REWRITE_TAC[strictly_convex_cycle] THEN
      DISCH_THEN(MP_TAC o SPECL [`i:num`; `j:num`; `n - 1`]) THEN
      ANTS_TAC THENL
       [ASM_ARITH_TAC;
        DISCH_THEN(LABEL_TAC "old_positive")] THEN
      MP_TAC(ISPECL
       [`(z:num->real^2) i`; `(z:num->real^2) j`;
        `(z:num->real^2) (n - 1)`]
       PLANE_ORIENTATION_CYCLIC) THEN
      ASM_REAL_ARITH_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[cyclic_split_left] THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      DISCH_THEN(LABEL_TAC "zero") THEN ASM_REAL_ARITH_TAC];
    USE_THEN "first" SUBST_ALL_TAC THEN
    REWRITE_TAC[cyclic_split_left;
                ARITH_RULE `!j:num. j < j + 1`;
                PLANE_ORIENTATION_REFL; REAL_LE_REFL];
    USE_THEN "last" SUBST_ALL_TAC THEN
    REWRITE_TAC[cyclic_split_left; LT_REFL;
                PLANE_ORIENTATION_REFL; REAL_LE_REFL]]);;

let STRICTLY_CONVEX_CYCLE_SPLIT_RIGHT_ORIENTATION = prove
 (`!z:num->real^2. !n j i.
        strictly_convex_cycle z n /\ j + 2 < n /\ i < n - j
        ==> plane_orientation (z j) (z (n - 1))
              (cyclic_split_right z j i) <= &0 /\
            (plane_orientation (z j) (z (n - 1))
               (cyclic_split_right z j i) = &0
             ==> cyclic_split_right z j i = z j \/
                 cyclic_split_right z j i = z (n - 1))`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex bound index" THEN
  SUBGOAL_THEN
   `(i:num) = 0 \/ i + 1 = n - j \/ (0 < i /\ i + 1 < n - j)`
  MP_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN
     (DISJ_CASES_THEN2 (LABEL_TAC "first")
      (DISJ_CASES_THEN2 (LABEL_TAC "last")
       (CONJUNCTS_THEN2 (LABEL_TAC "positive_index")
        (LABEL_TAC "before_last"))))] THENL
   [USE_THEN "first" SUBST_ALL_TAC THEN
    REWRITE_TAC[cyclic_split_right; ADD_CLAUSES;
                PLANE_ORIENTATION_REFL; REAL_LE_REFL];
    SUBGOAL_THEN `j + i = n - 1` (LABEL_TAC "old_last") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[cyclic_split_right] THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[PLANE_ORIENTATION_REFL; REAL_LE_REFL];
    SUBGOAL_THEN
     `&0 < plane_orientation (z j) (z (j + i)) (z (n - 1))`
    (LABEL_TAC "old_positive") THENL
     [USE_THEN "convex" MP_TAC THEN
      REWRITE_TAC[strictly_convex_cycle] THEN
      DISCH_THEN(MP_TAC o SPECL [`j:num`; `j + i`; `n - 1`]) THEN
      ANTS_TAC THENL
       [ASM_ARITH_TAC;
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `plane_orientation (z j) (z (n - 1)) (z (j + i)) =
      --(plane_orientation (z j) (z (j + i)) (z (n - 1)))`
    (LABEL_TAC "reverse") THENL
     [MATCH_ACCEPT_TAC(ISPECL
       [`(z:num->real^2) j`; `(z:num->real^2) (j + i)`;
        `(z:num->real^2) (n - 1)`]
       PLANE_ORIENTATION_SWAP);
      ALL_TAC] THEN
    REWRITE_TAC[cyclic_split_right] THEN CONJ_TAC THENL
     [ASM_REAL_ARITH_TAC;
      DISCH_THEN(LABEL_TAC "zero") THEN ASM_REAL_ARITH_TAC]]);;

let STRICTLY_CONVEX_CYCLE_SPLIT_LEFT_SIDE = prove
 (`!z:num->real^2. !n j.
        strictly_convex_cycle z n /\ j + 2 < n
        ==> (!x. x IN cyclic_vertices (cyclic_split_left z n j) (j + 2)
                  ==> &0 <= plane_orientation (z j) (z (n - 1)) x) /\
            {x | x IN cyclic_vertices (cyclic_split_left z n j) (j + 2) /\
                 plane_orientation (z j) (z (n - 1)) x = &0}
            SUBSET {z j,z (n - 1)}`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex bound" THEN CONJ_TAC THENL
   [X_GEN_TAC `x:real^2` THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    INTRO_TAC "@i. index point" THEN
    USE_THEN "point" SUBST1_TAC THEN
    MP_TAC(ISPECL [`z:num->real^2`; `n:num`; `j:num`; `i:num`]
     STRICTLY_CONVEX_CYCLE_SPLIT_LEFT_ORIENTATION) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_INSERT; NOT_IN_EMPTY] THEN
    X_GEN_TAC `x:real^2` THEN INTRO_TAC "in_cycle zero" THEN
    USE_THEN "in_cycle" MP_TAC THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    INTRO_TAC "@i. index point" THEN
    USE_THEN "point" SUBST_ALL_TAC THEN
    MP_TAC(ISPECL [`z:num->real^2`; `n:num`; `j:num`; `i:num`]
     STRICTLY_CONVEX_CYCLE_SPLIT_LEFT_ORIENTATION) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]]);;

let STRICTLY_CONVEX_CYCLE_SPLIT_RIGHT_SIDE = prove
 (`!z:num->real^2. !n j.
        strictly_convex_cycle z n /\ j + 2 < n
        ==> (!x. x IN cyclic_vertices (cyclic_split_right z j) (n - j)
                  ==> plane_orientation (z j) (z (n - 1)) x <= &0) /\
            {x | x IN cyclic_vertices (cyclic_split_right z j) (n - j) /\
                 plane_orientation (z j) (z (n - 1)) x = &0}
            SUBSET {z j,z (n - 1)}`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex bound" THEN CONJ_TAC THENL
   [X_GEN_TAC `x:real^2` THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    INTRO_TAC "@i. index point" THEN
    USE_THEN "point" SUBST1_TAC THEN
    MP_TAC(ISPECL [`z:num->real^2`; `n:num`; `j:num`; `i:num`]
     STRICTLY_CONVEX_CYCLE_SPLIT_RIGHT_ORIENTATION) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_INSERT; NOT_IN_EMPTY] THEN
    X_GEN_TAC `x:real^2` THEN INTRO_TAC "in_cycle zero" THEN
    USE_THEN "in_cycle" MP_TAC THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    INTRO_TAC "@i. index point" THEN
    USE_THEN "point" SUBST_ALL_TAC THEN
    MP_TAC(ISPECL [`z:num->real^2`; `n:num`; `j:num`; `i:num`]
     STRICTLY_CONVEX_CYCLE_SPLIT_RIGHT_ORIENTATION) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]]);;

let CYCLIC_SPLIT_LEFT_CHORD_ENDPOINTS = prove
 (`!z:num->real^2. !n j.
        j + 2 < n
        ==> {z j,z (n - 1)} SUBSET
            cyclic_vertices (cyclic_split_left z n j) (j + 2)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "bound") THEN
  REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_CYCLIC_VERTICES] THEN
  CONJ_TAC THENL
   [EXISTS_TAC `j:num` THEN CONJ_TAC THENL
     [ARITH_TAC;
      REWRITE_TAC[cyclic_split_left] THEN
      REWRITE_TAC[ARITH_RULE `!j:num. j < j + 1`]];
    EXISTS_TAC `j + 1` THEN CONJ_TAC THENL
     [ARITH_TAC;
      REWRITE_TAC[cyclic_split_left; LT_REFL]]]);;

let CYCLIC_SPLIT_RIGHT_CHORD_ENDPOINTS = prove
 (`!z:num->real^2. !n j.
        j + 2 < n
        ==> {z j,z (n - 1)} SUBSET
            cyclic_vertices (cyclic_split_right z j) (n - j)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "bound") THEN
  REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_CYCLIC_VERTICES] THEN
  CONJ_TAC THENL
   [EXISTS_TAC `0` THEN
    REWRITE_TAC[cyclic_split_right; ADD_CLAUSES] THEN ASM_ARITH_TAC;
    EXISTS_TAC `n - j - 1` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[cyclic_split_right] THEN AP_TERM_TAC THEN
      ASM_ARITH_TAC]]);;

let STRICTLY_CONVEX_CYCLE_SPLIT_HULLS_INTER = prove
 (`!z:num->real^2. !n j.
        strictly_convex_cycle z n /\ j + 2 < n
        ==> convex hull
             (cyclic_vertices (cyclic_split_left z n j) (j + 2)) INTER
            convex hull
             (cyclic_vertices (cyclic_split_right z j) (n - j)) =
            segment[z j,z (n - 1)]`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex bound" THEN
  ABBREV_TAC
   `L = cyclic_vertices (cyclic_split_left (z:num->real^2) n j) (j + 2)` THEN
  ABBREV_TAC
   `R = cyclic_vertices (cyclic_split_right (z:num->real^2) j) (n - j)` THEN
  ABBREV_TAC
   `a:real^2 = vector[((z:num->real^2) j)$2 - (z (n - 1))$2;
                     (z (n - 1))$1 - (z j)$1]` THEN
  SUBGOAL_THEN
   `!y:real^2.
      plane_orientation ((z:num->real^2) j) (z (n - 1)) y =
      a dot y - a dot z j`
  (LABEL_TAC "orientation") THENL
   [X_GEN_TAC `y:real^2` THEN EXPAND_TAC "a" THEN
    REWRITE_TAC[PLANE_ORIENTATION_DOT; DOT_RSUB];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(!y:real^2. y IN L
         ==> &0 <= plane_orientation ((z:num->real^2) j) (z (n - 1)) y) /\
    {y | y IN L /\ plane_orientation (z j) (z (n - 1)) y = &0}
    SUBSET {z j,z (n - 1)}`
  (CONJUNCTS_THEN2 (LABEL_TAC "left_side") (LABEL_TAC "left_face")) THENL
   [EXPAND_TAC "L" THEN
    MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_SPLIT_LEFT_SIDE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(!y:real^2. y IN R
         ==> plane_orientation ((z:num->real^2) j) (z (n - 1)) y <= &0) /\
    {y | y IN R /\ plane_orientation (z j) (z (n - 1)) y = &0}
    SUBSET {z j,z (n - 1)}`
  (CONJUNCTS_THEN2 (LABEL_TAC "right_side") (LABEL_TAC "right_face")) THENL
   [EXPAND_TAC "R" THEN
    MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_SPLIT_RIGHT_SIDE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INTER] THEN X_GEN_TAC `x:real^2` THEN
    INTRO_TAC "in_left in_right" THEN
    SUBGOAL_THEN
     `&0 <= plane_orientation (z j) (z (n - 1)) x`
    (LABEL_TAC "x_left") THENL
     [USE_THEN "left_side" (fun sth ->
       ACCEPT_TAC(MATCH_MP
        (SPEC `x:real^2`
         (REWRITE_RULE[SUBSET; IN_ELIM_THM]
          (MATCH_MP
           (ISPECL [`L:real^2->bool`; `(z:num->real^2) j`;
                    `(z:num->real^2) (n - 1)`]
            CONVEX_HULL_SUBSET_PLANE_ORIENTATION_GE) sth)))
        (ASSUME `(x:real^2) IN convex hull L`)));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `plane_orientation (z j) (z (n - 1)) x <= &0`
    (LABEL_TAC "x_right") THENL
     [USE_THEN "right_side" (fun sth ->
       ACCEPT_TAC(MATCH_MP
        (SPEC `x:real^2`
         (REWRITE_RULE[SUBSET; IN_ELIM_THM]
          (MATCH_MP
           (ISPECL [`R:real^2->bool`; `(z:num->real^2) j`;
                    `(z:num->real^2) (n - 1)`]
            CONVEX_HULL_SUBSET_PLANE_ORIENTATION_LE) sth)))
        (ASSUME `(x:real^2) IN convex hull R`)));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `plane_orientation (z j) (z (n - 1)) x = &0`
    (LABEL_TAC "x_on_line") THENL
     [ASM_REAL_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `x IN convex hull
       {y:real^2 | y IN L /\ a dot y = a dot (z:num->real^2) j}`
    (LABEL_TAC "x_in_face_hull") THENL
     [MATCH_MP_TAC(ISPECL
       [`L:real^2->bool`; `a:real^2`; `x:real^2`; `a dot (z:num->real^2) j`]
       IN_CONVEX_HULL_SUPPORTING_HYPERPLANE_GE) THEN
      REPEAT CONJ_TAC THENL
       [EXPAND_TAC "L" THEN MATCH_ACCEPT_TAC FINITE_CYCLIC_VERTICES;
        X_GEN_TAC `y:real^2` THEN
        DISCH_THEN(LABEL_TAC "in_left_generator") THEN
        SUBGOAL_THEN
         `&0 <= plane_orientation (z j) (z (n - 1)) y`
        (LABEL_TAC "y_side") THENL
         [USE_THEN "left_side" (MATCH_MP_TAC o SPEC `y:real^2`) THEN
          USE_THEN "in_left_generator" ACCEPT_TAC;
          ALL_TAC] THEN
        USE_THEN "orientation" (MP_TAC o SPEC `y:real^2`) THEN
        ASM_REAL_ARITH_TAC;
        USE_THEN "in_left" ACCEPT_TAC;
        USE_THEN "orientation" (MP_TAC o SPEC `x:real^2`) THEN
        ASM_REAL_ARITH_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{y:real^2 | y IN L /\ a dot y = a dot (z:num->real^2) j}
      SUBSET {z j,z (n - 1)}`
    (LABEL_TAC "face_subset") THENL
     [REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
      X_GEN_TAC `y:real^2` THEN
      INTRO_TAC "in_left_generator on_line" THEN
      USE_THEN "left_face" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      REWRITE_TAC[IN_ELIM_THM] THEN CONJ_TAC THENL
       [USE_THEN "in_left_generator" ACCEPT_TAC;
        USE_THEN "orientation" (MP_TAC o SPEC `y:real^2`) THEN
        ASM_REAL_ARITH_TAC];
      ALL_TAC] THEN
    REWRITE_TAC[SEGMENT_CONVEX_HULL] THEN
    USE_THEN "face_subset" (fun th ->
      MATCH_MP_TAC(REWRITE_RULE[SUBSET] (MATCH_MP HULL_MONO th))) THEN
    USE_THEN "x_in_face_hull" ACCEPT_TAC;
    REWRITE_TAC[SEGMENT_CONVEX_HULL; SUBSET_INTER] THEN CONJ_TAC THENL
     [MATCH_MP_TAC HULL_MONO THEN EXPAND_TAC "L" THEN
      MATCH_MP_TAC CYCLIC_SPLIT_LEFT_CHORD_ENDPOINTS THEN
      USE_THEN "bound" ACCEPT_TAC;
      MATCH_MP_TAC HULL_MONO THEN EXPAND_TAC "R" THEN
      MATCH_MP_TAC CYCLIC_SPLIT_RIGHT_CHORD_ENDPOINTS THEN
      USE_THEN "bound" ACCEPT_TAC]]);;

(* ------------------------------------------------------------------------- *)
(* Gluing straight-line embeddings along a common boundary edge.             *)
(* ------------------------------------------------------------------------- *)

let STRAIGHT_EDGE_SUBSET_CONVEX_HULL = prove
 (`!p:A->real^N. !e V.
        e SUBSET V
        ==> straight_edge p e SUBSET convex hull (IMAGE p V)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[straight_edge] THEN MATCH_MP_TAC HULL_MONO THEN
  MATCH_MP_TAC IMAGE_SUBSET THEN ASM_REWRITE_TAC[]);;

let STRAIGHT_LINE_EMBEDDINGS_ALONG_EDGE_CROSS_INJ = prove
 (`!V1 E1 V2 E2 p u v x y.
        straight_line_embedding (V1:A->bool) E1 p /\
        straight_line_embedding V2 E2 p /\
        {u,v} SUBSET V1 /\ {u,v} SUBSET V2 /\
        {u,v} IN E1 /\ {u,v} IN E2 /\
        convex hull (IMAGE p V1) INTER convex hull (IMAGE p V2) =
        segment[p u,p v] /\
        x IN V1 /\ y IN V2 /\ p x = p y
        ==> x = y`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "embedding1 embedding2 chord_subset1 chord_subset2 \
             chord1 chord2 hulls x_vertex y_vertex equal" THEN
  MP_TAC(ASSUME
   `straight_line_embedding (V1:A->bool) E1 (p:A->real^2)`) THEN
  REWRITE_TAC[straight_line_embedding] THEN
  INTRO_TAC "injective1 vertices1 intersections1" THEN
  MP_TAC(ASSUME
   `straight_line_embedding (V2:A->bool) E2 (p:A->real^2)`) THEN
  REWRITE_TAC[straight_line_embedding] THEN
  INTRO_TAC "injective2 vertices2 intersections2" THEN
  SUBGOAL_THEN
   `(p:A->real^2) x IN segment[p u,p v]`
  (LABEL_TAC "in_chord") THENL
   [USE_THEN "hulls" (fun th -> REWRITE_TAC[GSYM th; IN_INTER]) THEN
    CONJ_TAC THEN
    MATCH_MP_TAC(REWRITE_RULE[SUBSET] HULL_SUBSET) THEN
    REWRITE_TAC[IN_IMAGE] THENL
     [EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:A->real^2) x IN IMAGE p {u,v}` MP_TAC THENL
   [USE_THEN "vertices1" (fun th ->
     MP_TAC(MATCH_MP (SPEC `{u,v}:A->bool` th)
      (ASSUME `({u,v}:A->bool) IN E1`))) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th; IN_INTER]) THEN
    CONJ_TAC THENL
     [REWRITE_TAC[STRAIGHT_EDGE_PAIR] THEN
      USE_THEN "in_chord" ACCEPT_TAC;
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `x:A` THEN
      CONJ_TAC THENL
       [REFL_TAC;
        USE_THEN "x_vertex" ACCEPT_TAC]];
    REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@w. image w_chord" THEN
    SUBGOAL_THEN `(w:A) IN V1 /\ (w:A) IN V2`
    (CONJUNCTS_THEN2 (LABEL_TAC "w_vertex1") (LABEL_TAC "w_vertex2")) THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
         (ASSUME `({u,v}:A->bool) SUBSET V1`)) THEN
        USE_THEN "w_chord" ACCEPT_TAC;
        MATCH_MP_TAC(REWRITE_RULE[SUBSET]
         (ASSUME `({u,v}:A->bool) SUBSET V2`)) THEN
        USE_THEN "w_chord" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(x:A) = w` (LABEL_TAC "x_w") THENL
     [USE_THEN "injective1" (fun ith ->
       USE_THEN "x_vertex" (fun xth ->
        USE_THEN "w_vertex1" (fun wth ->
         USE_THEN "image" (fun eth ->
          ACCEPT_TAC(MATCH_MP
           (SPECL [`x:A`; `w:A`] (REWRITE_RULE[INJ; IN_UNIV] ith))
           (CONJ xth (CONJ wth eth)))))));
      ALL_TAC] THEN
    SUBGOAL_THEN `(y:A) = w` (LABEL_TAC "y_w") THENL
     [USE_THEN "injective2" (fun ith ->
       USE_THEN "y_vertex" (fun yth ->
        USE_THEN "w_vertex2" (fun wth ->
         USE_THEN "equal" (fun eqth ->
          USE_THEN "image" (fun imth ->
           ACCEPT_TAC(MATCH_MP
            (SPECL [`y:A`; `w:A`] (REWRITE_RULE[INJ; IN_UNIV] ith))
            (CONJ yth (CONJ wth (TRANS (SYM eqth) imth)))))))));
      ALL_TAC] THEN
    USE_THEN "x_w" (fun xth ->
     USE_THEN "y_w" (fun yth -> ACCEPT_TAC(TRANS xth (SYM yth))))]);;

let INJ_UNION_STRAIGHT_LINE_EMBEDDINGS_ALONG_EDGE = prove
 (`!V1 E1 V2 E2 p u v.
        straight_line_embedding (V1:A->bool) E1 p /\
        straight_line_embedding V2 E2 p /\
        {u,v} SUBSET V1 /\ {u,v} SUBSET V2 /\
        {u,v} IN E1 /\ {u,v} IN E2 /\
        convex hull (IMAGE p V1) INTER convex hull (IMAGE p V2) =
        segment[p u,p v]
        ==> INJ (p:A->real^2) (V1 UNION V2) UNIV`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "embedding1 embedding2 chord_subset1 chord_subset2 \
             chord1 chord2 hulls" THEN
  MP_TAC(ASSUME
   `straight_line_embedding (V1:A->bool) E1 (p:A->real^2)`) THEN
  REWRITE_TAC[straight_line_embedding] THEN
  INTRO_TAC "injective1 vertices1 intersections1" THEN
  MP_TAC(ASSUME
   `straight_line_embedding (V2:A->bool) E2 (p:A->real^2)`) THEN
  REWRITE_TAC[straight_line_embedding] THEN
  INTRO_TAC "injective2 vertices2 intersections2" THEN
  REWRITE_TAC[INJ; IN_UNIV] THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
  REWRITE_TAC[IN_UNION] THEN INTRO_TAC "x_union y_union equal" THEN
  USE_THEN "x_union" MP_TAC THEN
  DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "x1") (LABEL_TAC "x2")) THENL
   [USE_THEN "y_union" MP_TAC THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "y1") (LABEL_TAC "y2")) THENL
     [USE_THEN "injective1" (fun ith ->
       ACCEPT_TAC(MATCH_MP
        (SPECL [`x:A`; `y:A`] (REWRITE_RULE[INJ; IN_UNIV] ith))
        (CONJ (ASSUME `(x:A) IN V1`)
         (CONJ (ASSUME `(y:A) IN V1`)
               (ASSUME `(p:A->real^2) x = p y`)))));
      MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`;
        `V2:A->bool`; `E2:(A->bool)->bool`; `p:A->real^2`;
        `u:A`; `v:A`; `x:A`; `y:A`]
       STRAIGHT_LINE_EMBEDDINGS_ALONG_EDGE_CROSS_INJ) THEN
      ASM_REWRITE_TAC[]];
    USE_THEN "y_union" MP_TAC THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "y1") (LABEL_TAC "y2")) THENL
     [ONCE_REWRITE_TAC[EQ_SYM_EQ] THEN
      MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`;
        `V2:A->bool`; `E2:(A->bool)->bool`; `p:A->real^2`;
        `u:A`; `v:A`; `y:A`; `x:A`]
       STRAIGHT_LINE_EMBEDDINGS_ALONG_EDGE_CROSS_INJ) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "injective2" (fun ith ->
       ACCEPT_TAC(MATCH_MP
        (SPECL [`x:A`; `y:A`] (REWRITE_RULE[INJ; IN_UNIV] ith))
        (CONJ (ASSUME `(x:A) IN V2`)
         (CONJ (ASSUME `(y:A) IN V2`)
               (ASSUME `(p:A->real^2) x = p y`)))))]]);;

let STRAIGHT_LINE_EMBEDDINGS_ALONG_EDGE_INTER_VERTICES = prove
 (`!V1 E1 V2 E2 p u v e.
        straight_line_embedding (V1:A->bool) E1 p /\
        straight_line_embedding V2 E2 p /\
        {u,v} SUBSET V1 /\ {u,v} IN E2 /\
        e IN E1 /\ e SUBSET V1 /\
        convex hull (IMAGE p V1) INTER convex hull (IMAGE p V2) =
        segment[p u,p v]
        ==> straight_edge p e INTER IMAGE p V2 SUBSET IMAGE p e`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "embedding1 embedding2 chord_subset1 chord2 edge edge_subset hulls" THEN
  MP_TAC(ASSUME
   `straight_line_embedding (V1:A->bool) E1 (p:A->real^2)`) THEN
  REWRITE_TAC[straight_line_embedding] THEN
  INTRO_TAC "injective1 vertices1 intersections1" THEN
  MP_TAC(ASSUME
   `straight_line_embedding (V2:A->bool) E2 (p:A->real^2)`) THEN
  REWRITE_TAC[straight_line_embedding] THEN
  INTRO_TAC "injective2 vertices2 intersections2" THEN
  REWRITE_TAC[SUBSET; IN_INTER] THEN X_GEN_TAC `x:real^2` THEN
  INTRO_TAC "in_edge in_vertices2" THEN
  SUBGOAL_THEN `x IN segment[(p:A->real^2) u,p v]`
  (LABEL_TAC "in_chord") THENL
   [USE_THEN "hulls" (fun th -> REWRITE_TAC[GSYM th; IN_INTER]) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (MATCH_MP STRAIGHT_EDGE_SUBSET_CONVEX_HULL
        (ASSUME `(e:A->bool) SUBSET V1`))) THEN
      USE_THEN "in_edge" ACCEPT_TAC;
      MATCH_MP_TAC(REWRITE_RULE[SUBSET] HULL_SUBSET) THEN
      USE_THEN "in_vertices2" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `x IN IMAGE (p:A->real^2) {u,v}`
  (LABEL_TAC "endpoint") THENL
   [USE_THEN "vertices2" (fun th ->
     MP_TAC(MATCH_MP (SPEC `({u,v}:A->bool)` th)
      (ASSUME `({u,v}:A->bool) IN E2`))) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th; IN_INTER]) THEN
    CONJ_TAC THENL
     [REWRITE_TAC[STRAIGHT_EDGE_PAIR] THEN
      USE_THEN "in_chord" ACCEPT_TAC;
      USE_THEN "in_vertices2" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `x IN IMAGE (p:A->real^2) V1`
  (LABEL_TAC "in_vertices1") THENL
   [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
     (MATCH_MP IMAGE_SUBSET
      (ASSUME `({u,v}:A->bool) SUBSET V1`))) THEN
    USE_THEN "endpoint" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "vertices1" (fun th ->
   MP_TAC(MATCH_MP (SPEC `e:A->bool` th) (ASSUME `(e:A->bool) IN E1`))) THEN
  DISCH_THEN(fun th -> REWRITE_TAC[GSYM th; IN_INTER]) THEN
  CONJ_TAC THENL
   [USE_THEN "in_edge" ACCEPT_TAC;
    USE_THEN "in_vertices1" ACCEPT_TAC]);;

let STRAIGHT_LINE_EMBEDDING_EDGE_CHORD_ENDPOINT = prove
 (`!V E p u v e x.
        straight_line_embedding (V:A->bool) E p /\
        {u,v} IN E /\ e IN E /\ ~(e = {u,v}) /\
        x IN straight_edge p e /\ x IN segment[p u,p v]
        ==> x IN IMAGE p {u,v}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "embedding chord edge distinct in_edge in_chord" THEN
  MP_TAC(ASSUME
   `straight_line_embedding (V:A->bool) E (p:A->real^2)`) THEN
  REWRITE_TAC[straight_line_embedding] THEN
  INTRO_TAC "injective vertices intersections" THEN
  SUBGOAL_THEN `x IN IMAGE (p:A->real^2) (e INTER {u,v})` MP_TAC THENL
   [USE_THEN "intersections" (fun th ->
     MP_TAC(MATCH_MP
      (SPECL [`e:A->bool`; `{u,v}:A->bool`] th)
      (CONJ (ASSUME `(e:A->bool) IN E`)
       (CONJ (ASSUME `({u,v}:A->bool) IN E`)
             (ASSUME `~((e:A->bool) = {u,v})`))))) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th; IN_INTER]) THEN
    CONJ_TAC THENL
     [USE_THEN "in_edge" ACCEPT_TAC;
      REWRITE_TAC[STRAIGHT_EDGE_PAIR] THEN
      USE_THEN "in_chord" ACCEPT_TAC];
    REWRITE_TAC[IN_IMAGE; IN_INTER] THEN
    INTRO_TAC "@a. image a_edge a_chord" THEN
    EXISTS_TAC `a:A` THEN CONJ_TAC THENL
     [USE_THEN "image" ACCEPT_TAC;
      USE_THEN "a_chord" ACCEPT_TAC]]);;

let STRAIGHT_LINE_EMBEDDINGS_ALONG_EDGE_INTER_EDGES = prove
 (`!V1 E1 V2 E2 p u v e d.
        straight_line_embedding (V1:A->bool) E1 p /\
        straight_line_embedding V2 E2 p /\
        INJ p (V1 UNION V2) UNIV /\
        {u,v} SUBSET V1 /\ {u,v} SUBSET V2 /\
        {u,v} IN E1 /\ {u,v} IN E2 /\
        e IN E1 /\ d IN E2 /\ ~(e = d) /\
        e SUBSET V1 /\ d SUBSET V2 /\
        convex hull (IMAGE p V1) INTER convex hull (IMAGE p V2) =
        segment[p u,p v]
        ==> straight_edge p e INTER straight_edge p d =
            IMAGE p (e INTER d)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "embedding1 embedding2 injective chord_subset1 chord_subset2 \
    chord1 chord2 edge1 edge2 distinct edge_subset1 edge_subset2 hulls" THEN
  MP_TAC(ASSUME
   `straight_line_embedding (V1:A->bool) E1 (p:A->real^2)`) THEN
  REWRITE_TAC[straight_line_embedding] THEN
  INTRO_TAC "injective1 vertices1 intersections1" THEN
  MP_TAC(ASSUME
   `straight_line_embedding (V2:A->bool) E2 (p:A->real^2)`) THEN
  REWRITE_TAC[straight_line_embedding] THEN
  INTRO_TAC "injective2 vertices2 intersections2" THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INTER] THEN X_GEN_TAC `x:real^2` THEN
    INTRO_TAC "in_edge1 in_edge2" THEN
    SUBGOAL_THEN `x IN segment[(p:A->real^2) u,p v]`
    (LABEL_TAC "in_chord") THENL
     [USE_THEN "hulls" (fun th -> REWRITE_TAC[GSYM th; IN_INTER]) THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
         (MATCH_MP STRAIGHT_EDGE_SUBSET_CONVEX_HULL
          (ASSUME `(e:A->bool) SUBSET V1`))) THEN
        USE_THEN "in_edge1" ACCEPT_TAC;
        MATCH_MP_TAC(REWRITE_RULE[SUBSET]
         (MATCH_MP STRAIGHT_EDGE_SUBSET_CONVEX_HULL
          (ASSUME `(d:A->bool) SUBSET V2`))) THEN
        USE_THEN "in_edge2" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `x IN IMAGE (p:A->real^2) {u,v}`
    (LABEL_TAC "endpoint") THENL
     [ASM_CASES_TAC `(e:A->bool) = {u,v}` THENL
       [SUBGOAL_THEN `(e:A->bool) = {u,v}`
        (LABEL_TAC "edge1_chord") THENL
         [ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        SUBGOAL_THEN `~((d:A->bool) = {u,v})`
        (LABEL_TAC "edge2_not_chord") THENL
         [DISCH_THEN(LABEL_TAC "edge2_chord") THEN
          USE_THEN "distinct" (fun nth ->
           USE_THEN "edge1_chord" (fun eth ->
            USE_THEN "edge2_chord" (fun dth ->
             CONTR_TAC(MP (NOT_ELIM nth) (TRANS eth (SYM dth))))));
          ALL_TAC] THEN
        MATCH_MP_TAC(ISPECL
         [`V2:A->bool`; `E2:(A->bool)->bool`; `p:A->real^2`;
          `u:A`; `v:A`; `d:A->bool`; `x:real^2`]
         STRAIGHT_LINE_EMBEDDING_EDGE_CHORD_ENDPOINT) THEN
        ASM_REWRITE_TAC[];
        MATCH_MP_TAC(ISPECL
         [`V1:A->bool`; `E1:(A->bool)->bool`; `p:A->real^2`;
          `u:A`; `v:A`; `e:A->bool`; `x:real^2`]
         STRAIGHT_LINE_EMBEDDING_EDGE_CHORD_ENDPOINT) THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `x IN IMAGE (p:A->real^2) V1 /\
                  x IN IMAGE p V2`
    (CONJUNCTS_THEN2 (LABEL_TAC "in_vertices1")
      (LABEL_TAC "in_vertices2")) THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
         (MATCH_MP IMAGE_SUBSET
          (ASSUME `({u,v}:A->bool) SUBSET V1`)));
        MATCH_MP_TAC(REWRITE_RULE[SUBSET]
         (MATCH_MP IMAGE_SUBSET
          (ASSUME `({u,v}:A->bool) SUBSET V2`)))] THEN
      USE_THEN "endpoint" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `x IN IMAGE (p:A->real^2) e /\
                  x IN IMAGE p d`
    (CONJUNCTS_THEN2 (LABEL_TAC "in_image1")
      (LABEL_TAC "in_image2")) THENL
     [CONJ_TAC THENL
       [USE_THEN "vertices1" (fun th ->
         MP_TAC(MATCH_MP (SPEC `e:A->bool` th)
          (ASSUME `(e:A->bool) IN E1`))) THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th; IN_INTER]) THEN
        CONJ_TAC THENL
         [USE_THEN "in_edge1" ACCEPT_TAC;
          USE_THEN "in_vertices1" ACCEPT_TAC];
        USE_THEN "vertices2" (fun th ->
         MP_TAC(MATCH_MP (SPEC `d:A->bool` th)
          (ASSUME `(d:A->bool) IN E2`))) THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th; IN_INTER]) THEN
        CONJ_TAC THENL
         [USE_THEN "in_edge2" ACCEPT_TAC;
          USE_THEN "in_vertices2" ACCEPT_TAC]];
      ALL_TAC] THEN
    SUBGOAL_THEN `(e:A->bool) SUBSET V1 UNION V2 /\
                  (d:A->bool) SUBSET V1 UNION V2`
    (CONJUNCTS_THEN2 (LABEL_TAC "edge_union1")
      (LABEL_TAC "edge_union2")) THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `V1:A->bool` THEN
        ASM_REWRITE_TAC[SUBSET_UNION];
        MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `V2:A->bool` THEN
        ASM_REWRITE_TAC[SUBSET_UNION]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `IMAGE (p:A->real^2) (e INTER d) = IMAGE p e INTER IMAGE p d`
    (fun th -> REWRITE_TAC[th; IN_INTER]) THENL
     [MATCH_MP_TAC(ISPECL
       [`p:A->real^2`; `V1 UNION V2:A->bool`; `e:A->bool`; `d:A->bool`]
       IMAGE_INTER_INJ_ON) THEN
      ASM_REWRITE_TAC[];
      CONJ_TAC THENL
       [USE_THEN "in_image1" ACCEPT_TAC;
        USE_THEN "in_image2" ACCEPT_TAC]];
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `IMAGE (p:A->real^2) e INTER IMAGE p d` THEN
    CONJ_TAC THENL
     [MATCH_ACCEPT_TAC IMAGE_INTER_SUBSET;
      MATCH_MP_TAC(SET_RULE
       `(a:real^2->bool) SUBSET s /\ b SUBSET t
        ==> a INTER b SUBSET s INTER t`) THEN
      CONJ_TAC THENL
       [MATCH_ACCEPT_TAC
         (ISPECL [`p:A->real^2`; `e:A->bool`]
          IMAGE_SUBSET_STRAIGHT_EDGE);
        MATCH_ACCEPT_TAC
         (ISPECL [`p:A->real^2`; `d:A->bool`]
          IMAGE_SUBSET_STRAIGHT_EDGE)]]]);;

let STRAIGHT_LINE_EMBEDDING_UNION_ALONG_EDGE = prove
 (`!V1 E1 V2 E2 p u v.
        finite_simple_graph (V1:A->bool) E1 /\
        finite_simple_graph V2 E2 /\
        straight_line_embedding V1 E1 p /\
        straight_line_embedding V2 E2 p /\
        {u,v} IN E1 /\ {u,v} IN E2 /\
        convex hull (IMAGE p V1) INTER convex hull (IMAGE p V2) =
        segment[p u,p v]
        ==> straight_line_embedding (V1 UNION V2) (E1 UNION E2)
             (p:A->real^2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 embedding1 embedding2 chord1 chord2 hulls" THEN
  MP_TAC(ASSUME `finite_simple_graph (V1:A->bool) E1`) THEN
  REWRITE_TAC[finite_simple_graph] THEN
  INTRO_TAC "finite_vertices1 finite_edges1 edge_data1" THEN
  MP_TAC(ASSUME `finite_simple_graph (V2:A->bool) E2`) THEN
  REWRITE_TAC[finite_simple_graph] THEN
  INTRO_TAC "finite_vertices2 finite_edges2 edge_data2" THEN
  SUBGOAL_THEN
   `(!e:A->bool. e IN E1 ==> e SUBSET V1) /\
    (!e:A->bool. e IN E2 ==> e SUBSET V2)`
  (CONJUNCTS_THEN2 (LABEL_TAC "edge_subset1")
    (LABEL_TAC "edge_subset2")) THENL
   [CONJ_TAC THENL
     [X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
      USE_THEN "edge_data1" (fun th ->
       USE_THEN "edge" (fun eth ->
        ACCEPT_TAC(CONJUNCT1(MATCH_MP (SPEC `e:A->bool` th) eth))));
      X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
      USE_THEN "edge_data2" (fun th ->
       USE_THEN "edge" (fun eth ->
        ACCEPT_TAC(CONJUNCT1(MATCH_MP (SPEC `e:A->bool` th) eth))))];
    ALL_TAC] THEN
  SUBGOAL_THEN `({u,v}:A->bool) SUBSET V1 /\ {u,v} SUBSET V2`
  (CONJUNCTS_THEN2 (LABEL_TAC "chord_subset1")
    (LABEL_TAC "chord_subset2")) THENL
   [CONJ_TAC THENL
     [USE_THEN "edge_subset1"
       (MATCH_MP_TAC o SPEC `({u,v}:A->bool)`) THEN
      USE_THEN "chord1" ACCEPT_TAC;
      USE_THEN "edge_subset2"
       (MATCH_MP_TAC o SPEC `({u,v}:A->bool)`) THEN
      USE_THEN "chord2" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (p:A->real^2) (V1 UNION V2) UNIV`
  (LABEL_TAC "injective") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`;
      `V2:A->bool`; `E2:(A->bool)->bool`; `p:A->real^2`;
      `u:A`; `v:A`]
     INJ_UNION_STRAIGHT_LINE_EMBEDDINGS_ALONG_EDGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC STRAIGHT_LINE_EMBEDDING_UNION THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "embedding1" ACCEPT_TAC;
    USE_THEN "embedding2" ACCEPT_TAC;
    USE_THEN "injective" ACCEPT_TAC;
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge1") THEN
    MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`;
      `V2:A->bool`; `E2:(A->bool)->bool`; `p:A->real^2`;
      `u:A`; `v:A`; `e:A->bool`]
     STRAIGHT_LINE_EMBEDDINGS_ALONG_EDGE_INTER_VERTICES) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "embedding1" ACCEPT_TAC;
      USE_THEN "embedding2" ACCEPT_TAC;
      USE_THEN "chord_subset1" ACCEPT_TAC;
      USE_THEN "chord2" ACCEPT_TAC;
      USE_THEN "edge1" ACCEPT_TAC;
      USE_THEN "edge_subset1" (MATCH_MP_TAC o SPEC `e:A->bool`) THEN
      USE_THEN "edge1" ACCEPT_TAC;
      USE_THEN "hulls" ACCEPT_TAC];
    X_GEN_TAC `d:A->bool` THEN DISCH_THEN(LABEL_TAC "edge2") THEN
    MATCH_MP_TAC(ISPECL
     [`V2:A->bool`; `E2:(A->bool)->bool`;
      `V1:A->bool`; `E1:(A->bool)->bool`; `p:A->real^2`;
      `u:A`; `v:A`; `d:A->bool`]
     STRAIGHT_LINE_EMBEDDINGS_ALONG_EDGE_INTER_VERTICES) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "embedding2" ACCEPT_TAC;
      USE_THEN "embedding1" ACCEPT_TAC;
      USE_THEN "chord_subset2" ACCEPT_TAC;
      USE_THEN "chord1" ACCEPT_TAC;
      USE_THEN "edge2" ACCEPT_TAC;
      USE_THEN "edge_subset2" (MATCH_MP_TAC o SPEC `d:A->bool`) THEN
      USE_THEN "edge2" ACCEPT_TAC;
      ONCE_REWRITE_TAC[INTER_COMM] THEN USE_THEN "hulls" ACCEPT_TAC];
    MAP_EVERY X_GEN_TAC [`e:A->bool`; `d:A->bool`] THEN
    INTRO_TAC "edge1 edge2 distinct" THEN
    MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`;
      `V2:A->bool`; `E2:(A->bool)->bool`; `p:A->real^2`;
      `u:A`; `v:A`; `e:A->bool`; `d:A->bool`]
     STRAIGHT_LINE_EMBEDDINGS_ALONG_EDGE_INTER_EDGES) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "embedding1" ACCEPT_TAC;
      USE_THEN "embedding2" ACCEPT_TAC;
      USE_THEN "injective" ACCEPT_TAC;
      USE_THEN "chord_subset1" ACCEPT_TAC;
      USE_THEN "chord_subset2" ACCEPT_TAC;
      USE_THEN "chord1" ACCEPT_TAC;
      USE_THEN "chord2" ACCEPT_TAC;
      USE_THEN "edge1" ACCEPT_TAC;
      USE_THEN "edge2" ACCEPT_TAC;
      USE_THEN "distinct" ACCEPT_TAC;
      USE_THEN "edge_subset1" (MATCH_MP_TAC o SPEC `e:A->bool`) THEN
      USE_THEN "edge1" ACCEPT_TAC;
      USE_THEN "edge_subset2" (MATCH_MP_TAC o SPEC `d:A->bool`) THEN
      USE_THEN "edge2" ACCEPT_TAC;
      USE_THEN "hulls" ACCEPT_TAC]]);;

let STRAIGHT_LINE_EMBEDDING_UNION_STRICTLY_CONVEX_CYCLE_SPLIT = prove
 (`!V1 E1 V2 E2 p u v z n j.
        finite_simple_graph (V1:A->bool) E1 /\
        finite_simple_graph V2 E2 /\
        straight_line_embedding V1 E1 p /\
        straight_line_embedding V2 E2 p /\
        {u,v} IN E1 /\ {u,v} IN E2 /\
        strictly_convex_cycle z n /\ j + 2 < n /\
        p u = z j /\ p v = z (n - 1) /\
        convex hull (IMAGE p V1) =
        convex hull
         (cyclic_vertices (cyclic_split_left z n j) (j + 2)) /\
        convex hull (IMAGE p V2) =
        convex hull
         (cyclic_vertices (cyclic_split_right z j) (n - j))
        ==> straight_line_embedding (V1 UNION V2) (E1 UNION E2)
             (p:A->real^2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph1 graph2 embedding1 embedding2 chord1 chord2 convex bound \
    first_endpoint last_endpoint left_hull right_hull" THEN
  MATCH_MP_TAC(ISPECL
   [`V1:A->bool`; `E1:(A->bool)->bool`;
    `V2:A->bool`; `E2:(A->bool)->bool`; `p:A->real^2`;
    `u:A`; `v:A`]
   STRAIGHT_LINE_EMBEDDING_UNION_ALONG_EDGE) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "graph1" ACCEPT_TAC;
    USE_THEN "graph2" ACCEPT_TAC;
    USE_THEN "embedding1" ACCEPT_TAC;
    USE_THEN "embedding2" ACCEPT_TAC;
    USE_THEN "chord1" ACCEPT_TAC;
    USE_THEN "chord2" ACCEPT_TAC;
    USE_THEN "left_hull" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "right_hull" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "first_endpoint" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "last_endpoint" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_SPLIT_HULLS_INTER THEN
    ASM_REWRITE_TAC[]]);;

let quadratic_bezier = new_definition
 `quadratic_bezier (a:real^2) b c t =
        (&1 - t) pow 2 % a +
        (&2 * (&1 - t) * t) % b +
        t pow 2 % c`;;

let QUADRATIC_BEZIER_0 = prove
 (`!a b c:real^2. quadratic_bezier a b c (&0) = a`,
  REWRITE_TAC[quadratic_bezier; REAL_SUB_RZERO; REAL_POW_2;
              REAL_MUL_RZERO; REAL_MUL_LID; VECTOR_MUL_LZERO;
              VECTOR_ADD_RID; VECTOR_MUL_LID]);;

let QUADRATIC_BEZIER_1 = prove
 (`!a b c:real^2. quadratic_bezier a b c (&1) = c`,
  REWRITE_TAC[quadratic_bezier; REAL_SUB_REFL; REAL_POW_2;
              REAL_MUL_LZERO; REAL_MUL_RZERO; REAL_MUL_LID;
              VECTOR_MUL_LZERO; VECTOR_ADD_LID; VECTOR_MUL_LID]);;

let PLANE_ORIENTATION_QUADRATIC_BEZIER_RIGHT = prove
 (`!x y a b c:real^2. !t.
        plane_orientation x y (quadratic_bezier a b c t) =
        (&1 - t) pow 2 * plane_orientation x y a +
        (&2 * (&1 - t) * t) * plane_orientation x y b +
        t pow 2 * plane_orientation x y c`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_orientation; quadratic_bezier;
              VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT] THEN
  CONV_TAC REAL_RING);;

let PLANE_ORIENTATION_QUADRATIC_BEZIER_PAIR = prove
 (`!x a b c:real^2. !s t.
        plane_orientation x (quadratic_bezier a b c s)
          (quadratic_bezier a b c t) =
        (t - s) *
        ((&2 * (&1 - s) * (&1 - t)) * plane_orientation x a b +
         (s + t - &2 * s * t) * plane_orientation x a c +
         (&2 * s * t) * plane_orientation x b c)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_orientation; quadratic_bezier;
              VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT] THEN
  CONV_TAC REAL_RING);;

let PLANE_ORIENTATION_QUADRATIC_BEZIER_TRIPLE = prove
 (`!a b c:real^2. !r s t.
        plane_orientation
          (quadratic_bezier a b c r)
          (quadratic_bezier a b c s)
          (quadratic_bezier a b c t) =
        &2 * (s - r) * (t - r) * (t - s) *
        plane_orientation a b c`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_orientation; quadratic_bezier;
              VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT] THEN
  CONV_TAC REAL_RING);;

let PLANE_ORIENTATION_QUADRATIC_BEZIER_RIGHT_POS = prove
 (`!x y a b c:real^2. !t.
        &0 < t /\ t < &1 /\
        &0 <= plane_orientation x y a /\
        &0 < plane_orientation x y b /\
        &0 <= plane_orientation x y c
        ==> &0 < plane_orientation x y (quadratic_bezier a b c t)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "tpos tbound oa ob oc" THEN
  REWRITE_TAC[PLANE_ORIENTATION_QUADRATIC_BEZIER_RIGHT] THEN
  SUBGOAL_THEN
   `&0 <= (&1 - t) pow 2 * plane_orientation x y (a:real^2)`
  (LABEL_TAC "first") THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN
    ASM_REWRITE_TAC[REAL_LE_POW_2];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&0 < (&2 * (&1 - t) * t) * plane_orientation x y (b:real^2)`
  (LABEL_TAC "middle") THENL
   [MATCH_MP_TAC REAL_LT_MUL THEN ASM_REWRITE_TAC[] THEN
    REPEAT(MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC) THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&0 <= t pow 2 * plane_orientation x y (c:real^2)`
  (LABEL_TAC "last") THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN
    ASM_REWRITE_TAC[REAL_LE_POW_2];
    ASM_REAL_ARITH_TAC]);;

let PLANE_ORIENTATION_QUADRATIC_BEZIER_PAIR_POS = prove
 (`!x a b c:real^2. !s t.
        &0 < s /\ s < t /\ t < &1 /\
        &0 <= plane_orientation x a b /\
        &0 <= plane_orientation x a c /\
        &0 <= plane_orientation x b c /\
        (&0 < plane_orientation x a b \/
         &0 < plane_orientation x a c \/
         &0 < plane_orientation x b c)
        ==> &0 < plane_orientation x (quadratic_bezier a b c s)
                    (quadratic_bezier a b c t)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "spos st tbound oab oac obc positive" THEN
  REWRITE_TAC[PLANE_ORIENTATION_QUADRATIC_BEZIER_PAIR] THEN
  SUBGOAL_THEN `&0 < t - s` (LABEL_TAC "difference") THENL
   [ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &2 * (&1 - s) * (&1 - t)`
  (LABEL_TAC "first_coefficient") THENL
   [REPEAT(MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC) THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < s + t - &2 * s * t`
  (LABEL_TAC "middle_coefficient") THENL
   [SUBGOAL_THEN
     `s + t - &2 * s * t = s * (&1 - t) + t * (&1 - s)`
    SUBST1_TAC THENL
     [CONV_TAC REAL_RING;
      MATCH_MP_TAC REAL_LT_ADD THEN CONJ_TAC THEN
      MATCH_MP_TAC REAL_LT_MUL THEN ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &2 * s * t`
  (LABEL_TAC "last_coefficient") THENL
   [REPEAT(MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC) THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&0 <= (&2 * (&1 - s) * (&1 - t)) *
           plane_orientation x (a:real^2) b`
  (LABEL_TAC "first") THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&0 <= (s + t - &2 * s * t) *
           plane_orientation x (a:real^2) c`
  (LABEL_TAC "middle") THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&0 <= (&2 * s * t) * plane_orientation x (b:real^2) c`
  (LABEL_TAC "last") THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&0 <
    (&2 * (&1 - s) * (&1 - t)) * plane_orientation x (a:real^2) b +
    (s + t - &2 * s * t) * plane_orientation x a c +
    (&2 * s * t) * plane_orientation x b c`
  (LABEL_TAC "sum") THENL
   [USE_THEN "positive"
     (DISJ_CASES_THEN2 (LABEL_TAC "oab_pos")
       (DISJ_CASES_THEN2 (LABEL_TAC "oac_pos") (LABEL_TAC "obc_pos"))) THENL
     [SUBGOAL_THEN
       `&0 < (&2 * (&1 - s) * (&1 - t)) *
             plane_orientation x (a:real^2) b`
      (LABEL_TAC "first_pos") THENL
       [MATCH_MP_TAC REAL_LT_MUL THEN ASM_REWRITE_TAC[];
        ASM_REAL_ARITH_TAC];
      SUBGOAL_THEN
       `&0 < (s + t - &2 * s * t) *
             plane_orientation x (a:real^2) c`
      (LABEL_TAC "middle_pos") THENL
       [MATCH_MP_TAC REAL_LT_MUL THEN ASM_REWRITE_TAC[];
        ASM_REAL_ARITH_TAC];
      SUBGOAL_THEN
       `&0 < (&2 * s * t) * plane_orientation x (b:real^2) c`
      (LABEL_TAC "last_pos") THENL
       [MATCH_MP_TAC REAL_LT_MUL THEN ASM_REWRITE_TAC[];
        ASM_REAL_ARITH_TAC]];
    MATCH_MP_TAC REAL_LT_MUL THEN ASM_REWRITE_TAC[]]);;

let PLANE_ORIENTATION_QUADRATIC_BEZIER_TRIPLE_POS = prove
 (`!a b c:real^2. !r s t.
        r < s /\ s < t /\ &0 < plane_orientation a b c
        ==> &0 < plane_orientation
                    (quadratic_bezier a b c r)
                    (quadratic_bezier a b c s)
                    (quadratic_bezier a b c t)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "rs st orientation" THEN
  REWRITE_TAC[PLANE_ORIENTATION_QUADRATIC_BEZIER_TRIPLE] THEN
  REPEAT(MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC) THEN
  ASM_REAL_ARITH_TAC);;

let STRICTLY_CONVEX_CYCLE_QUADRATIC_BEZIER_RIGHT = prove
 (`!z:num->real^2. !n i j t.
        strictly_convex_cycle z n /\
        3 <= n /\ i < j /\ j < n - 1 /\ &0 < t /\ t < &1
        ==> &0 < plane_orientation (z i) (z j)
                    (quadratic_bezier (z (n - 2)) (z (n - 1)) (z 0) t)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "convex nlarge ij jbound tpos tbound" THEN
  MATCH_MP_TAC PLANE_ORIENTATION_QUADRATIC_BEZIER_RIGHT_POS THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [ASM_CASES_TAC `j < n - 2` THENL
     [MATCH_MP_TAC REAL_LT_IMP_LE THEN
      USE_THEN "convex" MP_TAC THEN
      REWRITE_TAC[strictly_convex_cycle] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_ARITH_TAC;
      SUBGOAL_THEN `j = n - 2` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN REAL_ARITH_TAC]];
    USE_THEN "convex" MP_TAC THEN
    REWRITE_TAC[strictly_convex_cycle] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_ARITH_TAC;
    ASM_CASES_TAC `i = 0` THENL
     [ASM_REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LT_IMP_LE THEN
      SUBGOAL_THEN
       `plane_orientation (z i) (z j) (z 0) =
        plane_orientation (z 0) (z i) (z j)`
      SUBST1_TAC THENL
       [MESON_TAC[PLANE_ORIENTATION_CYCLIC];
        USE_THEN "convex" MP_TAC THEN
        REWRITE_TAC[strictly_convex_cycle] THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_ARITH_TAC]]]);;

let PLANE_ORIENTATION_CYCLIC2 = prove
 (`!a b c:real^2.
        plane_orientation a b c = plane_orientation c a b`,
  REPEAT GEN_TAC THEN
  TRANS_TAC EQ_TRANS `plane_orientation b c (a:real^2)` THEN
  CONJ_TAC THENL
   [MATCH_ACCEPT_TAC
     (SPECL [`a:real^2`; `b:real^2`; `c:real^2`]
       PLANE_ORIENTATION_CYCLIC);
    MATCH_ACCEPT_TAC
     (SPECL [`b:real^2`; `c:real^2`; `a:real^2`]
       PLANE_ORIENTATION_CYCLIC)]);;

let STRICTLY_CONVEX_CYCLE_QUADRATIC_BEZIER_ORIENTATIONS = prove
 (`!z:num->real^2. !n i.
        strictly_convex_cycle z n /\ 3 <= n /\ i < n - 1
        ==>
        (&0 <= plane_orientation (z i) (z (n - 2)) (z (n - 1)) /\
         &0 <= plane_orientation (z i) (z (n - 2)) (z 0) /\
         &0 <= plane_orientation (z i) (z (n - 1)) (z 0)) /\
        (&0 < plane_orientation (z i) (z (n - 2)) (z (n - 1)) \/
         &0 < plane_orientation (z i) (z (n - 2)) (z 0) \/
         &0 < plane_orientation (z i) (z (n - 1)) (z 0))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "convex nlarge ibound" THEN
  REPEAT CONJ_TAC THENL
   [ASM_CASES_TAC `i < n - 2` THENL
     [MATCH_MP_TAC REAL_LT_IMP_LE THEN
      USE_THEN "convex" (MATCH_MP_TAC o
        REWRITE_RULE[strictly_convex_cycle]) THEN
      ASM_ARITH_TAC;
      SUBGOAL_THEN `i = n - 2` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN REAL_ARITH_TAC]];
    ASM_CASES_TAC `i = 0` THENL
     [ASM_REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN REAL_ARITH_TAC;
      ASM_CASES_TAC `i = n - 2` THENL
       [ASM_REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN REAL_ARITH_TAC;
        MATCH_MP_TAC REAL_LT_IMP_LE THEN
        SUBGOAL_THEN
         `plane_orientation (z i) (z (n - 2)) (z 0) =
          plane_orientation (z 0) (z i) (z (n - 2))`
        SUBST1_TAC THENL
         [MATCH_ACCEPT_TAC
           (SPECL
             [`(z:num->real^2) i`;
              `(z:num->real^2) (n - 2)`;
              `(z:num->real^2) 0`]
             PLANE_ORIENTATION_CYCLIC2);
          USE_THEN "convex" (MATCH_MP_TAC o
            REWRITE_RULE[strictly_convex_cycle]) THEN
          ASM_ARITH_TAC]]];
    ASM_CASES_TAC `i = 0` THENL
     [ASM_REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LT_IMP_LE THEN
      SUBGOAL_THEN
       `plane_orientation (z i) (z (n - 1)) (z 0) =
        plane_orientation (z 0) (z i) (z (n - 1))`
      SUBST1_TAC THENL
       [MATCH_ACCEPT_TAC
         (SPECL
           [`(z:num->real^2) i`;
            `(z:num->real^2) (n - 1)`;
            `(z:num->real^2) 0`]
           PLANE_ORIENTATION_CYCLIC2);
        USE_THEN "convex" (MATCH_MP_TAC o
          REWRITE_RULE[strictly_convex_cycle]) THEN
        ASM_ARITH_TAC]];
    ASM_CASES_TAC `i < n - 2` THENL
     [DISJ1_TAC THEN
      USE_THEN "convex" (MATCH_MP_TAC o
        REWRITE_RULE[strictly_convex_cycle]) THEN
      ASM_ARITH_TAC;
      DISJ2_TAC THEN DISJ2_TAC THEN
      SUBGOAL_THEN
       `plane_orientation (z i) (z (n - 1)) (z 0) =
        plane_orientation (z 0) (z i) (z (n - 1))`
      SUBST1_TAC THENL
       [MATCH_ACCEPT_TAC
         (SPECL
           [`(z:num->real^2) i`;
            `(z:num->real^2) (n - 1)`;
            `(z:num->real^2) 0`]
           PLANE_ORIENTATION_CYCLIC2);
        USE_THEN "convex" (MATCH_MP_TAC o
          REWRITE_RULE[strictly_convex_cycle]) THEN
        ASM_ARITH_TAC]]]);;

let STRICTLY_CONVEX_CYCLE_QUADRATIC_BEZIER_PAIR = prove
 (`!z:num->real^2. !n i s t.
        strictly_convex_cycle z n /\
        3 <= n /\ i < n - 1 /\ &0 < s /\ s < t /\ t < &1
        ==> &0 < plane_orientation (z i)
                    (quadratic_bezier
                      (z (n - 2)) (z (n - 1)) (z 0) s)
                    (quadratic_bezier
                      (z (n - 2)) (z (n - 1)) (z 0) t)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "convex nlarge ibound spos st tbound" THEN
  MATCH_MP_TAC PLANE_ORIENTATION_QUADRATIC_BEZIER_PAIR_POS THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [ASM_CASES_TAC `i < n - 2` THENL
     [MATCH_MP_TAC REAL_LT_IMP_LE THEN
      USE_THEN "convex" (MATCH_MP_TAC o
        REWRITE_RULE[strictly_convex_cycle]) THEN
      ASM_ARITH_TAC;
      SUBGOAL_THEN `i = n - 2` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN REAL_ARITH_TAC]];
    ASM_CASES_TAC `i = 0` THENL
     [ASM_REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN REAL_ARITH_TAC;
      ASM_CASES_TAC `i = n - 2` THENL
       [ASM_REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN REAL_ARITH_TAC;
        MATCH_MP_TAC REAL_LT_IMP_LE THEN
        SUBGOAL_THEN
         `plane_orientation (z i) (z (n - 2)) (z 0) =
          plane_orientation (z 0) (z i) (z (n - 2))`
        SUBST1_TAC THENL
         [MATCH_ACCEPT_TAC
           (SPECL
             [`(z:num->real^2) i`;
              `(z:num->real^2) (n - 2)`;
              `(z:num->real^2) 0`]
             PLANE_ORIENTATION_CYCLIC2);
          USE_THEN "convex" (MATCH_MP_TAC o
            REWRITE_RULE[strictly_convex_cycle]) THEN
          ASM_ARITH_TAC]]];
    ASM_CASES_TAC `i = 0` THENL
     [ASM_REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LT_IMP_LE THEN
      SUBGOAL_THEN
       `plane_orientation (z i) (z (n - 1)) (z 0) =
        plane_orientation (z 0) (z i) (z (n - 1))`
      SUBST1_TAC THENL
       [MATCH_ACCEPT_TAC
         (SPECL
           [`(z:num->real^2) i`;
            `(z:num->real^2) (n - 1)`;
            `(z:num->real^2) 0`]
           PLANE_ORIENTATION_CYCLIC2);
        USE_THEN "convex" (MATCH_MP_TAC o
          REWRITE_RULE[strictly_convex_cycle]) THEN
        ASM_ARITH_TAC]];
    ASM_CASES_TAC `i < n - 2` THENL
     [DISJ1_TAC THEN
      USE_THEN "convex" (MATCH_MP_TAC o
        REWRITE_RULE[strictly_convex_cycle]) THEN
      ASM_ARITH_TAC;
      DISJ2_TAC THEN DISJ2_TAC THEN
      SUBGOAL_THEN
       `plane_orientation (z i) (z (n - 1)) (z 0) =
        plane_orientation (z 0) (z i) (z (n - 1))`
      SUBST1_TAC THENL
       [MATCH_ACCEPT_TAC
         (SPECL
           [`(z:num->real^2) i`;
            `(z:num->real^2) (n - 1)`;
            `(z:num->real^2) 0`]
           PLANE_ORIENTATION_CYCLIC2);
        USE_THEN "convex" (MATCH_MP_TAC o
          REWRITE_RULE[strictly_convex_cycle]) THEN
        ASM_ARITH_TAC]]]);;

let STRICTLY_CONVEX_CYCLE_QUADRATIC_BEZIER_TRIPLE = prove
 (`!z:num->real^2. !n r s t.
        strictly_convex_cycle z n /\ 3 <= n /\ r < s /\ s < t
        ==> &0 < plane_orientation
                    (quadratic_bezier
                      (z (n - 2)) (z (n - 1)) (z 0) r)
                    (quadratic_bezier
                      (z (n - 2)) (z (n - 1)) (z 0) s)
                    (quadratic_bezier
                      (z (n - 2)) (z (n - 1)) (z 0) t)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "convex nlarge rs st" THEN
  MATCH_MP_TAC PLANE_ORIENTATION_QUADRATIC_BEZIER_TRIPLE_POS THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `plane_orientation (z (n - 2)) (z (n - 1)) (z 0) =
    plane_orientation (z 0) (z (n - 2)) (z (n - 1))`
  SUBST1_TAC THENL
   [MATCH_ACCEPT_TAC
     (SPECL
       [`(z:num->real^2) (n - 2)`;
        `(z:num->real^2) (n - 1)`;
        `(z:num->real^2) 0`]
       PLANE_ORIENTATION_CYCLIC2);
    USE_THEN "convex" (MATCH_MP_TAC o
      REWRITE_RULE[strictly_convex_cycle]) THEN
    ASM_ARITH_TAC]);;

let bezier_refined_cycle = new_definition
 `bezier_refined_cycle (z:num->real^2) n tau i =
        if i < n - 1 then z i
        else quadratic_bezier
              (z (n - 2)) (z (n - 1)) (z 0)
              (tau (i - (n - 1)))`;;

let STRICTLY_CONVEX_CYCLE_BEZIER_REFINED = prove
 (`!z:num->real^2. !n tau k.
        strictly_convex_cycle z n /\
        3 <= n /\
        (!r. r < k ==> &0 < tau r /\ tau r < &1) /\
        (!r s. r < s /\ s < k ==> tau r < tau s)
        ==> strictly_convex_cycle
             (bezier_refined_cycle z n tau) (n - 1 + k)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "convex nlarge parameters increasing" THEN
  REWRITE_TAC[strictly_convex_cycle] THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `j:num`; `l:num`] THEN
  INTRO_TAC "ij jl lbound" THEN
  REWRITE_TAC[bezier_refined_cycle] THEN
  ASM_CASES_TAC `l < n - 1` THENL
   [SUBGOAL_THEN `i < n - 1 /\ j < n - 1`
    (CONJUNCTS_THEN2 (LABEL_TAC "iold") (LABEL_TAC "jold")) THENL
     [ASM_ARITH_TAC;
      ASM_REWRITE_TAC[] THEN
      USE_THEN "convex" (MATCH_MP_TAC o
        REWRITE_RULE[strictly_convex_cycle]) THEN
      ASM_ARITH_TAC];
    ALL_TAC] THEN
  ASM_CASES_TAC `j < n - 1` THENL
   [SUBGOAL_THEN `i < n - 1` (LABEL_TAC "iold") THENL
     [ASM_ARITH_TAC;
      ASM_REWRITE_TAC[]] THEN
    MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_QUADRATIC_BEZIER_RIGHT THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "parameters" MATCH_MP_TAC THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `i < n - 1` THENL
   [ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_QUADRATIC_BEZIER_PAIR THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "parameters" (MP_TAC o SPEC `j - (n - 1)`) THEN
      ANTS_TAC THENL
       [ASM_ARITH_TAC;
        MESON_TAC[]];
      USE_THEN "increasing" MATCH_MP_TAC THEN ASM_ARITH_TAC;
      USE_THEN "parameters" (MP_TAC o SPEC `l - (n - 1)`) THEN
      ANTS_TAC THENL
       [ASM_ARITH_TAC;
        MESON_TAC[]]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_QUADRATIC_BEZIER_TRIPLE THEN
  ASM_REWRITE_TAC[] THEN
  CONJ_TAC THEN
  USE_THEN "increasing" MATCH_MP_TAC THEN ASM_ARITH_TAC);;

let bezier_parameter = new_definition
 `bezier_parameter k r = &(r + 1) / &(k + 1)`;;

let BEZIER_PARAMETER_BOUNDS = prove
 (`!k r. r < k
          ==> &0 < bezier_parameter k r /\
              bezier_parameter k r < &1`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[bezier_parameter] THEN DISCH_TAC THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC REAL_LT_DIV THEN
    REWRITE_TAC[REAL_OF_NUM_LT] THEN ARITH_TAC;
    SUBGOAL_THEN `&0 < &(k + 1)` ASSUME_TAC THENL
     [REWRITE_TAC[REAL_OF_NUM_LT] THEN ARITH_TAC;
      ASM_SIMP_TAC[REAL_LT_LDIV_EQ; REAL_MUL_LID; REAL_OF_NUM_LT] THEN
      ASM_ARITH_TAC]]);;

let BEZIER_PARAMETER_MONO = prove
 (`!k r s. r < s
            ==> bezier_parameter k r < bezier_parameter k s`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[bezier_parameter] THEN DISCH_TAC THEN
  SUBGOAL_THEN `&0 < &(k + 1)` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_OF_NUM_LT] THEN ARITH_TAC;
    ASM_SIMP_TAC[REAL_LT_DIV2_EQ; REAL_OF_NUM_LT] THEN
    ASM_ARITH_TAC]);;

let BEZIER_PARAMETER_INJ = prove
 (`!k r s. bezier_parameter k r = bezier_parameter k s <=> r = s`,
  REPEAT GEN_TAC THEN EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "equal") THEN
    ASM_CASES_TAC `r:num = s` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `r < s \/ s < r` DISJ_CASES_TAC THENL
     [ASM_ARITH_TAC;
      MP_TAC(SPECL [`k:num`; `r:num`; `s:num`]
        BEZIER_PARAMETER_MONO) THEN
      ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      MP_TAC(SPECL [`k:num`; `s:num`; `r:num`]
        BEZIER_PARAMETER_MONO) THEN
      ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC];
    DISCH_THEN SUBST1_TAC THEN REFL_TAC]);;

let STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_UNIFORM = prove
 (`!z:num->real^2. !n k.
        strictly_convex_cycle z n /\ 3 <= n
        ==> strictly_convex_cycle
             (bezier_refined_cycle z n (bezier_parameter k))
             (n - 1 + k)`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex nlarge" THEN
  MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_BEZIER_REFINED THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_ACCEPT_TAC BEZIER_PARAMETER_BOUNDS;
    MESON_TAC[BEZIER_PARAMETER_MONO]]);;

let STRICTLY_CONVEX_CYCLE_LAST_TRIANGLE = prove
 (`!z:num->real^2. !n.
        strictly_convex_cycle z n /\ 3 <= n
        ==> &0 < plane_orientation
                    (z (n - 2)) (z (n - 1)) (z 0)`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex nlarge" THEN
  SUBGOAL_THEN
   `plane_orientation (z (n - 2)) (z (n - 1)) (z 0) =
    plane_orientation (z 0) (z (n - 2)) (z (n - 1))`
  SUBST1_TAC THENL
   [MATCH_ACCEPT_TAC
     (SPECL
       [`(z:num->real^2) (n - 2)`;
        `(z:num->real^2) (n - 1)`;
        `(z:num->real^2) 0`]
       PLANE_ORIENTATION_CYCLIC2);
    USE_THEN "convex" (MATCH_MP_TAC o
      REWRITE_RULE[strictly_convex_cycle]) THEN
    ASM_ARITH_TAC]);;

let bezier_arc_point = new_definition
 `bezier_arc_point (z:num->real^2) n k r =
        quadratic_bezier
          (z (n - 2)) (z (n - 1)) (z 0)
          (bezier_parameter k r)`;;

let BEZIER_REFINED_CYCLE_ARC_POINT = prove
 (`!z:num->real^2. !n k r.
        3 <= n
        ==> bezier_refined_cycle z n (bezier_parameter k) (n - 1 + r) =
            bezier_arc_point z n k r`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[bezier_refined_cycle; bezier_arc_point] THEN
  COND_CASES_TAC THENL
   [ASM_ARITH_TAC;
    SUBGOAL_THEN `(n - 1 + r) - (n - 1) = r` SUBST1_TAC THENL
     [ASM_ARITH_TAC;
      REFL_TAC]]);;

let PLANE_ORIENTATION_EQ_0_COLLINEAR = prove
 (`!a b c:real^2.
        plane_orientation a b c = &0 <=> collinear {a,b,c}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_orientation; COLLINEAR_3_2D] THEN REAL_ARITH_TAC);;

let IN_CONVEX_HULL_SUPPORTING_PLANE_ORIENTATION = prove
 (`!s:real^2->bool. !a b x:real^2.
        FINITE s /\
        (!y. y IN s ==> &0 <= plane_orientation a b y) /\
        x IN convex hull s /\
        plane_orientation a b x = &0
        ==> x IN convex hull
             {y | y IN s /\ plane_orientation a b y = &0}`,
  REWRITE_TAC[PLANE_ORIENTATION_DOT; DOT_RSUB;
              REAL_SUB_LE; REAL_SUB_0] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC IN_CONVEX_HULL_SUPPORTING_HYPERPLANE_GE THEN
  ASM_REWRITE_TAC[]);;

let SEGMENT_INTER_CONVEX_HULL_SUPPORTING_PLANE_ORIENTATION = prove
 (`!s:real^2->bool. !a b p:real^2.
        FINITE s /\
        a IN s /\
        (!x. x IN s ==> &0 <= plane_orientation a b x) /\
        {x | x IN s /\ plane_orientation a b x = &0} = {a} /\
        plane_orientation a b p < &0
        ==> segment[p,a] INTER convex hull s = {a}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite point side unique outside" THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INTER; IN_SING] THEN
    X_GEN_TAC `x:real^2` THEN INTRO_TAC "in_segment in_hull" THEN
    SUBGOAL_THEN `plane_orientation a b x <= &0`
    (LABEL_TAC "nonpositive") THENL
     [SUBGOAL_THEN
       `x IN {y:real^2 | plane_orientation a b y <= &0}`
      MP_TAC THENL
       [MATCH_MP_TAC(ISPECL
         [`{y:real^2 | plane_orientation a b y <= &0}`;
          `p:real^2`; `a:real^2`; `x:real^2`]
         CONVEX_CONTAINS) THEN
        ASM_REWRITE_TAC[IN_ELIM_THM; CONVEX_PLANE_ORIENTATION_LE;
                        PLANE_ORIENTATION_REFL] THEN
        ASM_REAL_ARITH_TAC;
        REWRITE_TAC[IN_ELIM_THM]];
      ALL_TAC] THEN
    SUBGOAL_THEN `&0 <= plane_orientation a b x`
    (LABEL_TAC "nonnegative") THENL
     [MP_TAC(MATCH_MP
       (REWRITE_RULE[SUBSET]
        (MATCH_MP CONVEX_HULL_SUBSET_PLANE_ORIENTATION_GE
         (ASSUME
          `!y:real^2. y IN s ==> &0 <= plane_orientation a b y`)))
       (ASSUME `(x:real^2) IN convex hull s`)) THEN
      REWRITE_TAC[IN_ELIM_THM];
      ALL_TAC] THEN
    SUBGOAL_THEN `plane_orientation a b x = &0`
    (LABEL_TAC "on_line") THENL
     [ASM_REAL_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `x IN convex hull
       {y:real^2 | y IN s /\ plane_orientation a b y = &0}`
    MP_TAC THENL
     [MATCH_MP_TAC IN_CONVEX_HULL_SUPPORTING_PLANE_ORIENTATION THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[CONVEX_HULL_SING; IN_SING]];
    REWRITE_TAC[SING_SUBSET; IN_INTER; ENDS_IN_SEGMENT] THEN
    MATCH_MP_TAC HULL_INC THEN USE_THEN "point" ACCEPT_TAC]);;

let quadratic_bezier_tangent = new_definition
 `quadratic_bezier_tangent (a:real^2) b c t =
        quadratic_bezier a b c t +
        ((&1 - t) % (b - a) + t % (c - b))`;;

let bezier_arc_tangent = new_definition
 `bezier_arc_tangent (z:num->real^2) n k r =
        quadratic_bezier_tangent
          (z (n - 2)) (z (n - 1)) (z 0)
          (bezier_parameter k r)`;;

let PLANE_ORIENTATION_QUADRATIC_BEZIER_TANGENT = prove
 (`!x a b c:real^2. !t.
        plane_orientation
          (quadratic_bezier a b c t)
          (quadratic_bezier_tangent a b c t) x =
        (&1 - t) pow 2 * plane_orientation x a b +
        (t * (&1 - t)) * plane_orientation x a c +
        t pow 2 * plane_orientation x b c`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_orientation; quadratic_bezier;
              quadratic_bezier_tangent; VECTOR_ADD_COMPONENT;
              VECTOR_SUB_COMPONENT; VECTOR_MUL_COMPONENT] THEN
  CONV_TAC REAL_RING);;

let PLANE_ORIENTATION_QUADRATIC_BEZIER_TANGENT_CURVE = prove
 (`!a b c:real^2. !s t.
        plane_orientation
          (quadratic_bezier a b c t)
          (quadratic_bezier_tangent a b c t)
          (quadratic_bezier a b c s) =
        (s - t) pow 2 * plane_orientation a b c`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_orientation; quadratic_bezier;
              quadratic_bezier_tangent; VECTOR_ADD_COMPONENT;
              VECTOR_SUB_COMPONENT; VECTOR_MUL_COMPONENT] THEN
  CONV_TAC REAL_RING);;

let PLANE_ORIENTATION_QUADRATIC_BEZIER_TANGENT_CONTROL = prove
 (`!a b c:real^2. !t.
        plane_orientation
          (quadratic_bezier a b c t)
          (quadratic_bezier_tangent a b c t) b =
        --(t * (&1 - t) * plane_orientation a b c)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_orientation; quadratic_bezier;
              quadratic_bezier_tangent; VECTOR_ADD_COMPONENT;
              VECTOR_SUB_COMPONENT; VECTOR_MUL_COMPONENT] THEN
  CONV_TAC REAL_RING);;

let PLANE_ORIENTATION_QUADRATIC_BEZIER_TANGENT_POS = prove
 (`!x a b c:real^2. !t.
        &0 < t /\ t < &1 /\
        &0 <= plane_orientation x a b /\
        &0 <= plane_orientation x a c /\
        &0 <= plane_orientation x b c /\
        (&0 < plane_orientation x a b \/
         &0 < plane_orientation x a c \/
         &0 < plane_orientation x b c)
        ==> &0 < plane_orientation
                    (quadratic_bezier a b c t)
                    (quadratic_bezier_tangent a b c t) x`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "tpos tbound oab oac obc positive" THEN
  REWRITE_TAC[PLANE_ORIENTATION_QUADRATIC_BEZIER_TANGENT] THEN
  SUBGOAL_THEN `&0 < (&1 - t) pow 2`
  (LABEL_TAC "first_coefficient") THENL
   [MATCH_MP_TAC REAL_POW_LT THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < t * (&1 - t)`
  (LABEL_TAC "middle_coefficient") THENL
   [MATCH_MP_TAC REAL_LT_MUL THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < t pow 2`
  (LABEL_TAC "last_coefficient") THENL
   [MATCH_MP_TAC REAL_POW_LT THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&0 <= (&1 - t) pow 2 * plane_orientation x (a:real^2) b`
  (LABEL_TAC "first") THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&0 <= (t * (&1 - t)) * plane_orientation x (a:real^2) c`
  (LABEL_TAC "middle") THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&0 <= t pow 2 * plane_orientation x (b:real^2) c`
  (LABEL_TAC "last") THENL
   [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "positive"
   (DISJ_CASES_THEN2 (LABEL_TAC "oab_pos")
     (DISJ_CASES_THEN2 (LABEL_TAC "oac_pos") (LABEL_TAC "obc_pos"))) THENL
   [SUBGOAL_THEN
     `&0 < (&1 - t) pow 2 * plane_orientation x (a:real^2) b`
    (LABEL_TAC "first_pos") THENL
     [MATCH_MP_TAC REAL_LT_MUL THEN ASM_REWRITE_TAC[];
      ASM_REAL_ARITH_TAC];
    SUBGOAL_THEN
     `&0 < (t * (&1 - t)) * plane_orientation x (a:real^2) c`
    (LABEL_TAC "middle_pos") THENL
     [MATCH_MP_TAC REAL_LT_MUL THEN ASM_REWRITE_TAC[];
      ASM_REAL_ARITH_TAC];
    SUBGOAL_THEN
     `&0 < t pow 2 * plane_orientation x (b:real^2) c`
    (LABEL_TAC "last_pos") THENL
     [MATCH_MP_TAC REAL_LT_MUL THEN ASM_REWRITE_TAC[];
      ASM_REAL_ARITH_TAC]]);;

(* The Bezier tangent leaves every retained polygon vertex on its left.      *)

let STRICTLY_CONVEX_CYCLE_QUADRATIC_BEZIER_TANGENT_AT_OLD_VERTEX = prove
 (`!z:num->real^2. !n i t.
        strictly_convex_cycle z n /\
        3 <= n /\ i < n - 1 /\ &0 < t /\ t < &1
        ==> &0 < plane_orientation
                    (quadratic_bezier
                      (z (n - 2)) (z (n - 1)) (z 0) t)
                    (quadratic_bezier_tangent
                      (z (n - 2)) (z (n - 1)) (z 0) t)
                    (z i)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "convex nlarge ibound tpos tbound" THEN
  MATCH_MP_TAC PLANE_ORIENTATION_QUADRATIC_BEZIER_TANGENT_POS THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL
   [`z:num->real^2`; `n:num`; `i:num`]
   STRICTLY_CONVEX_CYCLE_QUADRATIC_BEZIER_ORIENTATIONS) THEN
  ASM_REWRITE_TAC[] THEN MESON_TAC[]);;

let STRICTLY_CONVEX_CYCLE_BEZIER_ARC_TANGENT_AT_OLD_VERTEX = prove
 (`!z:num->real^2. !n k r i.
        strictly_convex_cycle z n /\
        3 <= n /\ r < k /\ i < n - 1
        ==> &0 < plane_orientation
                    (bezier_arc_point z n k r)
                    (bezier_arc_tangent z n k r)
                    (z i)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "convex nlarge rbound ibound" THEN
  REWRITE_TAC[bezier_arc_point; bezier_arc_tangent] THEN
  MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_QUADRATIC_BEZIER_TANGENT_AT_OLD_VERTEX THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`k:num`; `r:num`] BEZIER_PARAMETER_BOUNDS) THEN
  ASM_REWRITE_TAC[]);;

let PLANE_ORIENTATION_BEZIER_ARC_TANGENT_ARC = prove
 (`!z:num->real^2. !n k r s.
        plane_orientation
          (bezier_arc_point z n k r)
          (bezier_arc_tangent z n k r)
          (bezier_arc_point z n k s) =
        (bezier_parameter k s - bezier_parameter k r) pow 2 *
        plane_orientation (z (n - 2)) (z (n - 1)) (z 0)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[bezier_arc_point; bezier_arc_tangent;
              PLANE_ORIENTATION_QUADRATIC_BEZIER_TANGENT_CURVE]);;

let STRICTLY_CONVEX_CYCLE_BEZIER_ARC_TANGENT_CONTROL = prove
 (`!z:num->real^2. !n k r.
        strictly_convex_cycle z n /\ 3 <= n /\ r < k
        ==> plane_orientation
              (bezier_arc_point z n k r)
              (bezier_arc_tangent z n k r)
              (z (n - 1)) < &0`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex nlarge rbound" THEN
  SUBGOAL_THEN
   `&0 < plane_orientation
          (z (n - 2)) (z (n - 1)) ((z:num->real^2) 0)`
  (LABEL_TAC "triangle") THENL
   [MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_LAST_TRIANGLE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`k:num`; `r:num`] BEZIER_PARAMETER_BOUNDS) THEN
  ASM_REWRITE_TAC[] THEN INTRO_TAC "parameter_pos parameter_bound" THEN
  REWRITE_TAC[bezier_arc_point; bezier_arc_tangent;
              PLANE_ORIENTATION_QUADRATIC_BEZIER_TANGENT_CONTROL] THEN
  SUBGOAL_THEN
   `&0 < bezier_parameter k r * (&1 - bezier_parameter k r) *
         plane_orientation (z (n - 2)) (z (n - 1)) ((z:num->real^2) 0)`
  MP_TAC THENL
   [REPEAT(MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC) THEN
    ASM_REAL_ARITH_TAC;
    REAL_ARITH_TAC]);;

let BEZIER_ARC_POINT_IN_REFINED_CYCLE = prove
 (`!z:num->real^2. !n k r.
        3 <= n /\ r < k
        ==> bezier_arc_point z n k r IN
            cyclic_vertices
              (bezier_refined_cycle z n (bezier_parameter k))
              (n - 1 + k)`,
  REPEAT GEN_TAC THEN INTRO_TAC "nlarge rbound" THEN
  REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
  EXISTS_TAC `n - 1 + r` THEN CONJ_TAC THENL
   [ASM_ARITH_TAC;
    CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC BEZIER_REFINED_CYCLE_ARC_POINT THEN
    ASM_REWRITE_TAC[]]);;

let STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_TANGENT_SIDE = prove
 (`!z:num->real^2. !n k r x.
        strictly_convex_cycle z n /\
        3 <= n /\ r < k /\
        x IN cyclic_vertices
              (bezier_refined_cycle z n (bezier_parameter k))
              (n - 1 + k)
        ==> &0 <= plane_orientation
                    (bezier_arc_point z n k r)
                    (bezier_arc_tangent z n k r) x`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "convex nlarge rbound vertex" THEN
  USE_THEN "vertex" MP_TAC THEN
  REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
  INTRO_TAC "@i. ibound point" THEN
  USE_THEN "point" SUBST1_TAC THEN
  REWRITE_TAC[bezier_refined_cycle] THEN
  ASM_CASES_TAC `i < n - 1` THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC REAL_LT_IMP_LE THEN
    MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_BEZIER_ARC_TANGENT_AT_OLD_VERTEX THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[bezier_arc_point] THEN
    REWRITE_TAC[bezier_arc_tangent;
                PLANE_ORIENTATION_QUADRATIC_BEZIER_TANGENT_CURVE] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN
    REWRITE_TAC[REAL_LE_POW_2] THEN
    MATCH_MP_TAC REAL_LT_IMP_LE THEN
    MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_LAST_TRIANGLE THEN
    ASM_REWRITE_TAC[]]);;

let STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_TANGENT_EQ = prove
 (`!z:num->real^2. !n k r.
        strictly_convex_cycle z n /\ 3 <= n /\ r < k
        ==> {x |
              x IN cyclic_vertices
                    (bezier_refined_cycle z n (bezier_parameter k))
                    (n - 1 + k) /\
              plane_orientation
                (bezier_arc_point z n k r)
                (bezier_arc_tangent z n k r) x = &0} =
            {bezier_arc_point z n k r}`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex nlarge rbound" THEN
  REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_SING] THEN
  X_GEN_TAC `x:real^2` THEN EQ_TAC THENL
   [INTRO_TAC "vertex zero" THEN
    USE_THEN "vertex" MP_TAC THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    INTRO_TAC "@i. ibound point" THEN
    USE_THEN "point" SUBST_ALL_TAC THEN
    ASM_CASES_TAC `i < n - 1` THENL
     [SUBGOAL_THEN
       `bezier_refined_cycle z n (bezier_parameter k) i = z i`
      (LABEL_TAC "old_point") THENL
       [ASM_REWRITE_TAC[bezier_refined_cycle];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `plane_orientation
          (bezier_arc_point z n k r)
          (bezier_arc_tangent z n k r) (z i) = &0`
      (LABEL_TAC "old_zero") THENL
       [USE_THEN "old_point" (fun th ->
          USE_THEN "zero" (ACCEPT_TAC o REWRITE_RULE[th]));
        ALL_TAC] THEN
      USE_THEN "old_point" SUBST1_TAC THEN
      MP_TAC(ISPECL
       [`z:num->real^2`; `n:num`; `k:num`; `r:num`; `i:num`]
       STRICTLY_CONVEX_CYCLE_BEZIER_ARC_TANGENT_AT_OLD_VERTEX) THEN
      ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
      SUBGOAL_THEN
       `bezier_refined_cycle z n (bezier_parameter k) i =
        bezier_arc_point z n k (i - (n - 1))`
      (LABEL_TAC "arc_point") THENL
       [ASM_REWRITE_TAC[bezier_refined_cycle; bezier_arc_point];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `plane_orientation
          (bezier_arc_point z n k r)
          (bezier_arc_tangent z n k r)
          (bezier_arc_point z n k (i - (n - 1))) = &0`
      (LABEL_TAC "arc_zero") THENL
       [USE_THEN "arc_point" (fun th ->
          USE_THEN "zero" (ACCEPT_TAC o REWRITE_RULE[th]));
        ALL_TAC] THEN
      USE_THEN "arc_point" SUBST1_TAC THEN
      SUBGOAL_THEN
       `&0 < plane_orientation
              (z (n - 2)) (z (n - 1)) ((z:num->real^2) 0)`
      (LABEL_TAC "triangle") THENL
       [MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_LAST_TRIANGLE THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(bezier_parameter k (i - (n - 1)) -
         bezier_parameter k r) pow 2 *
        plane_orientation (z (n - 2)) (z (n - 1))
          ((z:num->real^2) 0) = &0`
      (LABEL_TAC "zero_product") THENL
       [USE_THEN "arc_zero" MP_TAC THEN
        REWRITE_TAC[PLANE_ORIENTATION_BEZIER_ARC_TANGENT_ARC];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `bezier_parameter k (i - (n - 1)) = bezier_parameter k r`
      (LABEL_TAC "equal_parameter") THENL
       [USE_THEN "zero_product" MP_TAC THEN
        ASM_SIMP_TAC[REAL_ENTIRE; REAL_LT_IMP_NZ; REAL_POW_EQ_0] THEN
        REAL_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `i - (n - 1) = r` (LABEL_TAC "equal_index") THENL
       [MP_TAC(SPECL [`k:num`; `i - (n - 1)`; `r:num`]
         BEZIER_PARAMETER_INJ) THEN
        ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[bezier_arc_point]]];
    DISCH_THEN SUBST1_TAC THEN CONJ_TAC THENL
     [MATCH_MP_TAC BEZIER_ARC_POINT_IN_REFINED_CYCLE THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[PLANE_ORIENTATION_REFL]]]);;

let STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_FAN_HULL = prove
 (`!z:num->real^2. !n k r.
        strictly_convex_cycle z n /\ 3 <= n /\ r < k
        ==> segment[z (n - 1),bezier_arc_point z n k r] INTER
            convex hull
             (cyclic_vertices
               (bezier_refined_cycle z n (bezier_parameter k))
               (n - 1 + k)) =
            {bezier_arc_point z n k r}`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex nlarge rbound" THEN
  MATCH_MP_TAC
   SEGMENT_INTER_CONVEX_HULL_SUPPORTING_PLANE_ORIENTATION THEN
  EXISTS_TAC `bezier_arc_tangent z n k r` THEN
  REPEAT CONJ_TAC THENL
   [ACCEPT_TAC(ISPECL
     [`bezier_refined_cycle
        (z:num->real^2) n (bezier_parameter k)`;
      `(n:num) - 1 + k`]
     FINITE_CYCLIC_VERTICES);
    MATCH_MP_TAC BEZIER_ARC_POINT_IN_REFINED_CYCLE THEN
    ASM_REWRITE_TAC[];
    X_GEN_TAC `x:real^2` THEN DISCH_THEN(LABEL_TAC "vertex") THEN
    MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_TANGENT_SIDE THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_TANGENT_EQ THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_BEZIER_ARC_TANGENT_CONTROL THEN
    ASM_REWRITE_TAC[]]);;

let STRAIGHT_LINE_EMBEDDING_RAY_INTER_EDGE = prove
 (`!V E p u e s.
        finite_simple_graph (V:A->bool) E /\
        straight_line_embedding V E p /\
        u IN V /\ e IN E /\
        s INTER convex hull (IMAGE p V) = {p u} /\ p u IN s
        ==> s INTER straight_edge p e = IMAGE p ({u} INTER e)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding vertex edge ray_hull endpoint" THEN
  USE_THEN "embedding" MP_TAC THEN
  REWRITE_TAC[straight_line_embedding] THEN
  INTRO_TAC "injective edge_vertices edge_intersections" THEN
  SUBGOAL_THEN `(e:A->bool) SUBSET V` (LABEL_TAC "edge_subset") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    INTRO_TAC "finite_vertices finite_edges edges" THEN
    USE_THEN "edges" (MP_TAC o SPEC `e:A->bool`) THEN
    ANTS_TAC THENL
     [USE_THEN "edge" ACCEPT_TAC;
      INTRO_TAC "subset size" THEN USE_THEN "subset" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `straight_edge (p:A->real^2) e SUBSET convex hull (IMAGE p V)`
  (LABEL_TAC "edge_hull") THENL
   [MATCH_MP_TAC STRAIGHT_EDGE_SUBSET_CONVEX_HULL THEN
    USE_THEN "edge_subset" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `s INTER straight_edge (p:A->real^2) e SUBSET {p u}`
  (LABEL_TAC "intersection_subset") THENL
   [USE_THEN "ray_hull" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC(SET_RULE
     `(e:real^2->bool) SUBSET h ==> s INTER e SUBSET s INTER h`) THEN
    USE_THEN "edge_hull" ACCEPT_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `(u:A) IN e` THENL
   [SUBGOAL_THEN `IMAGE (p:A->real^2) ({u} INTER e) = {p u}`
    SUBST1_TAC THENL
     [SUBGOAL_THEN `({u} INTER e:A->bool) = {u}` SUBST1_TAC THENL
       [MATCH_MP_TAC(SET_RULE `u:A IN e ==> {u} INTER e = {u}`) THEN
        ASM_REWRITE_TAC[];
        REWRITE_TAC[IMAGE_CLAUSES]];
      MATCH_MP_TAC(SET_RULE
       `(s:real^2->bool) INTER e SUBSET {a} /\ a IN s /\ a IN e
        ==> s INTER e = {a}`) THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(REWRITE_RULE[SUBSET] IMAGE_SUBSET_STRAIGHT_EDGE) THEN
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `u:A` THEN
      ASM_REWRITE_TAC[]];
    SUBGOAL_THEN
     `~((p:A->real^2) u IN straight_edge p e)`
    (LABEL_TAC "endpoint_not_edge") THENL
     [DISCH_THEN(LABEL_TAC "endpoint_edge") THEN
      SUBGOAL_THEN `(p:A->real^2) u IN IMAGE p e`
      (LABEL_TAC "endpoint_image") THENL
       [USE_THEN "edge_vertices" (fun th ->
         MP_TAC(MATCH_MP (SPEC `e:A->bool` th)
           (ASSUME `(e:A->bool) IN E`))) THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th; IN_INTER]) THEN
        CONJ_TAC THENL
         [USE_THEN "endpoint_edge" ACCEPT_TAC;
          REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `u:A` THEN
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      USE_THEN "endpoint_image" MP_TAC THEN
      REWRITE_TAC[IN_IMAGE] THEN
      INTRO_TAC "@y. y_edge y_image" THEN
      SUBGOAL_THEN `(y:A) IN V` (LABEL_TAC "y_vertex") THENL
       [USE_THEN "edge_subset" MP_TAC THEN
        REWRITE_TAC[SUBSET] THEN DISCH_THEN MATCH_MP_TAC THEN
        USE_THEN "y_image" ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "injective" MP_TAC THEN
      REWRITE_TAC[INJ; IN_UNIV] THEN
      DISCH_THEN(MP_TAC o SPECL [`y:A`; `u:A`]) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST_ALL_TAC THEN
      ACCEPT_TAC
       (MP (NOT_ELIM(ASSUME `~((u:A) IN e)`))
           (ASSUME `(u:A) IN e`));
      SUBGOAL_THEN `IMAGE (p:A->real^2) ({u} INTER e) = {}`
      SUBST1_TAC THENL
       [SUBGOAL_THEN `({u} INTER e:A->bool) = {}` SUBST1_TAC THENL
         [MATCH_MP_TAC(SET_RULE `~(u:A IN e) ==> {u} INTER e = {}`) THEN
          ASM_REWRITE_TAC[];
          REWRITE_TAC[IMAGE_CLAUSES]];
        MATCH_MP_TAC(SET_RULE
         `(s:real^2->bool) INTER t SUBSET {(p:A->real^2) u} /\
          ~(p u IN t)
          ==> s INTER t = {}`) THEN
        ASM_REWRITE_TAC[]]]]);;

let STRAIGHT_LINE_EMBEDDING_INSERT_VERTEX_STAR_OUTSIDE_HULL = prove
 (`!V E p v N p'.
        finite_simple_graph (V:A->bool) E /\
        straight_line_embedding V E p /\
        ~(v IN V) /\ N SUBSET V /\
        (!u. u IN V ==> p' u = p u) /\
        ~((p':A->real^2) v IN convex hull (IMAGE p V)) /\
        (!u. u IN N
             ==> segment[p' v,p u] INTER convex hull (IMAGE p V) = {p u}) /\
        (!u w. u IN N /\ w IN N /\ ~(u = w)
               ==> segment[p' v,p u] INTER segment[p' v,p w] = {p' v})
        ==> straight_line_embedding (v INSERT V)
             (IMAGE (\u:A. {v,u}) N UNION E) p'`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding fresh neighbors agrees outside ray_hull ray_pair" THEN
  SUBGOAL_THEN
   `IMAGE (p:A->real^2) V SUBSET convex hull (IMAGE p V)`
  (LABEL_TAC "image_hull") THENL
   [MATCH_ACCEPT_TAC HULL_SUBSET;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `v:A`; `N:A->bool`; `p':A->real^2`]
   STRAIGHT_LINE_EMBEDDING_INSERT_VERTEX_STAR) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    USE_THEN "embedding" ACCEPT_TAC;
    USE_THEN "fresh" ACCEPT_TAC;
    USE_THEN "neighbors" ACCEPT_TAC;
    USE_THEN "agrees" ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "in_image") THEN
    USE_THEN "outside" MP_TAC THEN
    USE_THEN "image_hull" MP_TAC THEN
    USE_THEN "in_image" MP_TAC THEN SET_TAC[];
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    SUBGOAL_THEN `(e:A->bool) SUBSET V` (LABEL_TAC "edge_subset") THENL
     [USE_THEN "graph" MP_TAC THEN REWRITE_TAC[finite_simple_graph] THEN
      INTRO_TAC "finite_vertices finite_edges edges" THEN
      USE_THEN "edges" (MP_TAC o SPEC `e:A->bool`) THEN
      ANTS_TAC THENL
       [USE_THEN "edge" ACCEPT_TAC;
        INTRO_TAC "subset size" THEN USE_THEN "subset" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `straight_edge (p:A->real^2) e SUBSET convex hull (IMAGE p V)`
    (LABEL_TAC "edge_hull") THENL
     [MATCH_MP_TAC STRAIGHT_EDGE_SUBSET_CONVEX_HULL THEN
      USE_THEN "edge_subset" ACCEPT_TAC;
      ALL_TAC] THEN
    DISCH_THEN(LABEL_TAC "in_edge") THEN
    USE_THEN "outside" MP_TAC THEN
    USE_THEN "edge_hull" MP_TAC THEN
    USE_THEN "in_edge" MP_TAC THEN SET_TAC[];
    X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "neighbor") THEN
    SUBGOAL_THEN
     `segment[(p':A->real^2) v,(p:A->real^2) u] INTER
      convex hull (IMAGE (p:A->real^2) V) = {(p:A->real^2) u}`
    (LABEL_TAC "ray_hull_u") THENL
     [USE_THEN "ray_hull" (fun th ->
       USE_THEN "neighbor" (fun nth ->
        ACCEPT_TAC(MATCH_MP (SPEC `u:A` th) nth)));
      ALL_TAC] THEN
    MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
     [USE_THEN "ray_hull_u" MP_TAC THEN
      USE_THEN "image_hull" MP_TAC THEN SET_TAC[];
      REWRITE_TAC[SUBSET; IN_SING; IN_INTER] THEN
      X_GEN_TAC `x:real^2` THEN DISCH_THEN SUBST1_TAC THEN
      CONJ_TAC THENL
       [REWRITE_TAC[ENDS_IN_SEGMENT];
        MATCH_MP_TAC FUN_IN_IMAGE THEN
        USE_THEN "neighbors" MP_TAC THEN
        USE_THEN "neighbor" MP_TAC THEN SET_TAC[]]];
    MAP_EVERY X_GEN_TAC [`u:A`; `e:A->bool`] THEN
    INTRO_TAC "neighbor edge" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `u:A`; `e:A->bool`;
       `segment[(p':A->real^2) v,(p:A->real^2) u]`]
     STRAIGHT_LINE_EMBEDDING_RAY_INTER_EDGE) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      USE_THEN "embedding" ACCEPT_TAC;
      USE_THEN "neighbors" MP_TAC THEN
      USE_THEN "neighbor" MP_TAC THEN SET_TAC[];
      USE_THEN "edge" ACCEPT_TAC;
      USE_THEN "ray_hull" (fun th ->
       USE_THEN "neighbor" (fun nth ->
        ACCEPT_TAC(MATCH_MP (SPEC `u:A` th) nth)));
      REWRITE_TAC[ENDS_IN_SEGMENT]];
    MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN
    INTRO_TAC "neighbor neighbor' distinct" THEN
    USE_THEN "ray_pair" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[]]);;

let SEGMENT_INTER_CONVEX_HULL_SUPPORTING_EDGE_ORIENTATION = prove
 (`!s:real^2->bool. !a b p e:real^2.
        FINITE s /\
        a IN s /\ b IN s /\ e IN {a,b} /\
        (!x. x IN s ==> &0 <= plane_orientation a b x) /\
        {x | x IN s /\ plane_orientation a b x = &0} = {a,b} /\
        plane_orientation a b p < &0
        ==> segment[p,e] INTER convex hull s = {e}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite a_vertex b_vertex endpoint side face outside" THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INTER; IN_SING] THEN
    X_GEN_TAC `x:real^2` THEN INTRO_TAC "in_segment in_hull" THEN
    SUBGOAL_THEN `plane_orientation a b x <= &0`
    (LABEL_TAC "nonpositive") THENL
     [SUBGOAL_THEN
      `x IN {y:real^2 | plane_orientation a b y <= &0}`
      MP_TAC THENL
       [MATCH_MP_TAC(ISPECL
         [`{y:real^2 | plane_orientation a b y <= &0}`;
          `p:real^2`; `e:real^2`; `x:real^2`]
         CONVEX_CONTAINS) THEN
        ASM_REWRITE_TAC[IN_ELIM_THM; CONVEX_PLANE_ORIENTATION_LE] THEN
        USE_THEN "endpoint" MP_TAC THEN
        REWRITE_TAC[IN_INSERT; IN_SING] THEN
        DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
        REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN ASM_REAL_ARITH_TAC;
        REWRITE_TAC[IN_ELIM_THM]];
      ALL_TAC] THEN
    SUBGOAL_THEN `&0 <= plane_orientation a b x`
    (LABEL_TAC "nonnegative") THENL
     [MP_TAC(MATCH_MP
       (REWRITE_RULE[SUBSET]
        (MATCH_MP CONVEX_HULL_SUBSET_PLANE_ORIENTATION_GE
         (ASSUME
          `!y:real^2. y IN s ==> &0 <= plane_orientation a b y`)))
       (ASSUME `(x:real^2) IN convex hull s`)) THEN
      REWRITE_TAC[IN_ELIM_THM];
      ALL_TAC] THEN
    SUBGOAL_THEN `plane_orientation a b x = &0`
    (LABEL_TAC "on_line") THENL
     [ASM_REAL_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `x IN convex hull
       {y:real^2 | y IN s /\ plane_orientation a b y = &0}`
    (LABEL_TAC "in_face_hull") THENL
     [MATCH_MP_TAC IN_CONVEX_HULL_SUPPORTING_PLANE_ORIENTATION THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x:real^2) IN segment[(a:real^2),(b:real^2)]`
    (LABEL_TAC "in_face") THENL
     [USE_THEN "in_face_hull" MP_TAC THEN
      USE_THEN "face" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[GSYM SEGMENT_CONVEX_HULL];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `segment[(p:real^2),(e:real^2)] INTER
      segment[(a:real^2),(b:real^2)] = {e}`
    (LABEL_TAC "segments") THENL
     [ASM_CASES_TAC `(e:real^2) = a` THENL
       [ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC
         (ISPECL [`p:real^2`; `a:real^2`; `b:real^2`]
           INTER_SEGMENT) THEN
        DISJ2_TAC THEN
        REWRITE_TAC[GSYM PLANE_ORIENTATION_EQ_0_COLLINEAR] THEN
        MP_TAC(SPECL [`p:real^2`; `a:real^2`; `b:real^2`]
          PLANE_ORIENTATION_CYCLIC) THEN
        ASM_REAL_ARITH_TAC;
        SUBGOAL_THEN `(e:real^2) = b` SUBST1_TAC THENL
         [USE_THEN "endpoint" MP_TAC THEN
          REWRITE_TAC[IN_INSERT; IN_SING] THEN ASM_MESON_TAC[];
          ALL_TAC] THEN
        ONCE_REWRITE_TAC[INTER_COMM] THEN
        GEN_REWRITE_TAC (LAND_CONV o RAND_CONV)
         [CONJUNCT1 SEGMENT_SYM] THEN
        MATCH_MP_TAC
         (ISPECL [`a:real^2`; `b:real^2`; `p:real^2`]
           INTER_SEGMENT) THEN
        DISJ2_TAC THEN
        REWRITE_TAC[GSYM PLANE_ORIENTATION_EQ_0_COLLINEAR] THEN
        ASM_REAL_ARITH_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x:real^2) IN
      segment[(p:real^2),(e:real^2)] INTER
      segment[(a:real^2),(b:real^2)]`
    MP_TAC THENL
     [ASM_REWRITE_TAC[IN_INTER];
      ASM_REWRITE_TAC[IN_SING]];
    REWRITE_TAC[SING_SUBSET; IN_INTER; ENDS_IN_SEGMENT] THEN
    MATCH_MP_TAC HULL_INC THEN
    ASM SET_TAC[]]);;

let SEGMENT_INTER_CONVEX_HULL_SUPPORTING_PLANE_ORIENTATION_LE = prove
 (`!s:real^2->bool. !a b p e:real^2.
        FINITE s /\
        e IN s /\
        (!x. x IN s ==> &0 <= plane_orientation a b x) /\
        {x | x IN s /\ plane_orientation a b x = &0} = {e} /\
        plane_orientation a b p <= &0 /\
        plane_orientation a b e <= &0
        ==> segment[p,e] INTER convex hull s = {e}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite endpoint side unique outside endpoint_side" THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INTER; IN_SING] THEN
    X_GEN_TAC `x:real^2` THEN INTRO_TAC "in_segment in_hull" THEN
    SUBGOAL_THEN `plane_orientation a b x <= &0`
    (LABEL_TAC "nonpositive") THENL
     [SUBGOAL_THEN
       `x IN {y:real^2 | plane_orientation a b y <= &0}`
      MP_TAC THENL
       [MATCH_MP_TAC(ISPECL
         [`{y:real^2 | plane_orientation a b y <= &0}`;
          `p:real^2`; `e:real^2`; `x:real^2`]
         CONVEX_CONTAINS) THEN
        ASM_REWRITE_TAC[IN_ELIM_THM; CONVEX_PLANE_ORIENTATION_LE] THEN
        ASM_REAL_ARITH_TAC;
        REWRITE_TAC[IN_ELIM_THM]];
      ALL_TAC] THEN
    SUBGOAL_THEN `&0 <= plane_orientation a b x`
    (LABEL_TAC "nonnegative") THENL
     [MP_TAC(MATCH_MP
       (REWRITE_RULE[SUBSET]
        (MATCH_MP CONVEX_HULL_SUBSET_PLANE_ORIENTATION_GE
         (ASSUME
          `!y:real^2. y IN s ==> &0 <= plane_orientation a b y`)))
       (ASSUME `(x:real^2) IN convex hull s`)) THEN
      REWRITE_TAC[IN_ELIM_THM];
      ALL_TAC] THEN
    SUBGOAL_THEN `plane_orientation a b x = &0`
    (LABEL_TAC "on_line") THENL
     [ASM_REAL_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `x IN convex hull
       {y:real^2 | y IN s /\ plane_orientation a b y = &0}`
    MP_TAC THENL
     [MATCH_MP_TAC IN_CONVEX_HULL_SUPPORTING_PLANE_ORIENTATION THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[CONVEX_HULL_SING; IN_SING]];
    REWRITE_TAC[SING_SUBSET; IN_INTER; ENDS_IN_SEGMENT] THEN
    MATCH_MP_TAC HULL_INC THEN USE_THEN "endpoint" ACCEPT_TAC]);;

let PLANE_ORIENTATION_QUADRATIC_BEZIER_FIRST_EDGE = prove
 (`!a b c:real^2. !t.
        plane_orientation a b (quadratic_bezier a b c t) =
        t pow 2 * plane_orientation a b c`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[PLANE_ORIENTATION_QUADRATIC_BEZIER_RIGHT;
              PLANE_ORIENTATION_REFL] THEN
  REAL_ARITH_TAC);;

let PLANE_ORIENTATION_QUADRATIC_BEZIER_LAST_EDGE = prove
 (`!a b c:real^2. !t.
        plane_orientation b c (quadratic_bezier a b c t) =
        (&1 - t) pow 2 * plane_orientation b c a`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[PLANE_ORIENTATION_QUADRATIC_BEZIER_RIGHT;
              PLANE_ORIENTATION_REFL] THEN
  REAL_ARITH_TAC);;

let STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_FIRST_ENDPOINT_SIDE = prove
 (`!z:num->real^2. !n k x.
        strictly_convex_cycle z n /\ 3 <= n /\ 0 < k /\
        x IN cyclic_vertices
              (bezier_refined_cycle z n (bezier_parameter k))
              (n - 1 + k)
        ==> &0 <= plane_orientation
                    (z (n - 2)) (z (n - 1)) x`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "convex nlarge kpositive vertex" THEN
  USE_THEN "vertex" MP_TAC THEN
  REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
  INTRO_TAC "@i. ibound point" THEN
  USE_THEN "point" SUBST1_TAC THEN
  REWRITE_TAC[bezier_refined_cycle] THEN
  ASM_CASES_TAC `i < n - 1` THEN ASM_REWRITE_TAC[] THENL
   [ASM_CASES_TAC `i = n - 2` THENL
     [ASM_REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LT_IMP_LE THEN
      SUBGOAL_THEN
       `plane_orientation (z (n - 2)) (z (n - 1)) (z i) =
        plane_orientation (z i) (z (n - 2)) (z (n - 1))`
      SUBST1_TAC THENL
       [MATCH_ACCEPT_TAC
         (SPECL
           [`(z:num->real^2) (n - 2)`;
            `(z:num->real^2) (n - 1)`;
            `(z:num->real^2) i`]
           PLANE_ORIENTATION_CYCLIC2);
        USE_THEN "convex"
         (MATCH_MP_TAC o REWRITE_RULE[strictly_convex_cycle]) THEN
        ASM_ARITH_TAC]];
    REWRITE_TAC[PLANE_ORIENTATION_QUADRATIC_BEZIER_FIRST_EDGE] THEN
    MATCH_MP_TAC REAL_LE_MUL THEN
    REWRITE_TAC[REAL_LE_POW_2] THEN
    MATCH_MP_TAC REAL_LT_IMP_LE THEN
    MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_LAST_TRIANGLE THEN
    ASM_REWRITE_TAC[]]);;

let STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_FIRST_ENDPOINT_EQ = prove
 (`!z:num->real^2. !n k.
        strictly_convex_cycle z n /\ 3 <= n /\ 0 < k
        ==> {x |
              x IN cyclic_vertices
                    (bezier_refined_cycle z n (bezier_parameter k))
                    (n - 1 + k) /\
              plane_orientation (z (n - 2)) (z (n - 1)) x = &0} =
            {z (n - 2)}`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex nlarge kpositive" THEN
  REWRITE_TAC[EXTENSION; IN_ELIM_THM; IN_SING] THEN
  X_GEN_TAC `x:real^2` THEN EQ_TAC THENL
   [INTRO_TAC "vertex zero" THEN
    USE_THEN "vertex" MP_TAC THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    INTRO_TAC "@i. ibound point" THEN
    USE_THEN "point" SUBST_ALL_TAC THEN
    ASM_CASES_TAC `i < n - 1` THENL
     [SUBGOAL_THEN
       `bezier_refined_cycle z n (bezier_parameter k) i = z i`
      (LABEL_TAC "old_point") THENL
       [ASM_REWRITE_TAC[bezier_refined_cycle];
        ALL_TAC] THEN
      ASM_CASES_TAC `i = n - 2` THENL
       [ASM_REWRITE_TAC[];
        SUBGOAL_THEN
        `&0 < plane_orientation
                (z (n - 2)) (z (n - 1))
                (bezier_refined_cycle z n (bezier_parameter k) i)`
        MP_TAC THENL
         [USE_THEN "old_point" (fun th -> REWRITE_TAC[th]) THEN
          SUBGOAL_THEN
           `plane_orientation (z (n - 2)) (z (n - 1)) (z i) =
            plane_orientation (z i) (z (n - 2)) (z (n - 1))`
          SUBST1_TAC THENL
           [MATCH_ACCEPT_TAC
             (SPECL
               [`(z:num->real^2) (n - 2)`;
                `(z:num->real^2) (n - 1)`;
                `(z:num->real^2) i`]
               PLANE_ORIENTATION_CYCLIC2);
            USE_THEN "convex"
             (MATCH_MP_TAC o REWRITE_RULE[strictly_convex_cycle]) THEN
            ASM_ARITH_TAC];
          USE_THEN "zero" MP_TAC THEN ASM_REAL_ARITH_TAC]];
      SUBGOAL_THEN `i - (n - 1) < k` (LABEL_TAC "sample") THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `&0 < bezier_parameter k (i - (n - 1))`
      (LABEL_TAC "parameter_positive") THENL
       [MP_TAC(SPECL [`k:num`; `i - (n - 1)`]
         BEZIER_PARAMETER_BOUNDS) THEN
        ASM_REWRITE_TAC[] THEN MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
      `&0 < plane_orientation
              (z (n - 2)) (z (n - 1))
              (bezier_refined_cycle z n (bezier_parameter k) i)`
      MP_TAC THENL
       [REWRITE_TAC[bezier_refined_cycle] THEN
        ASM_REWRITE_TAC[] THEN
        REWRITE_TAC[PLANE_ORIENTATION_QUADRATIC_BEZIER_FIRST_EDGE] THEN
        MATCH_MP_TAC REAL_LT_MUL THEN
        ASM_SIMP_TAC[REAL_POW_LT] THEN
        MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_LAST_TRIANGLE THEN
        ASM_REWRITE_TAC[];
        USE_THEN "zero" MP_TAC THEN ASM_REAL_ARITH_TAC]];
    DISCH_THEN SUBST1_TAC THEN CONJ_TAC THENL
     [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `n - 2` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[bezier_refined_cycle] THEN
        COND_CASES_TAC THEN ASM_ARITH_TAC];
      REWRITE_TAC[PLANE_ORIENTATION_REFL]]]);;

