             (SPECL
               [`(z:num->real^2) (n - 2)`;
                `(z:num->real^2) 0`;
                `(z:num->real^2) i`]
               PLANE_ORIENTATION_CYCLIC);
            USE_THEN "convex"
             (MATCH_MP_TAC o REWRITE_RULE[strictly_convex_cycle]) THEN
            ASM_ARITH_TAC];
          USE_THEN "point" (fun th ->
           USE_THEN "zero" (MP_TAC o REWRITE_RULE[th])) THEN
          ASM_REAL_ARITH_TAC]]];
    DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
    CONJ_TAC THENL
     [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `n - 2` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[bezier_refined_cycle] THEN
        COND_CASES_TAC THEN ASM_ARITH_TAC];
      REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN REAL_ARITH_TAC;
      REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `0` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[bezier_refined_cycle] THEN
        COND_CASES_TAC THEN ASM_ARITH_TAC];
      REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN REAL_ARITH_TAC]]);;

let STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_ZERO_ENDPOINT_FAN_HULL = prove
 (`!z:num->real^2. !n e.
        strictly_convex_cycle z n /\ 3 <= n /\
        e IN {z (n - 2),z 0}
        ==> segment[z (n - 1),e] INTER
            convex hull
             (cyclic_vertices
               (bezier_refined_cycle z n (bezier_parameter 0))
               (n - 1)) =
            {e}`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex nlarge endpoint" THEN
  MATCH_MP_TAC(ISPECL
   [`cyclic_vertices
      (bezier_refined_cycle
        (z:num->real^2) n (bezier_parameter 0))
      (n - 1)`;
    `(z:num->real^2) (n - 2)`;
    `(z:num->real^2) 0`;
    `(z:num->real^2) (n - 1)`;
    `e:real^2`]
   SEGMENT_INTER_CONVEX_HULL_SUPPORTING_EDGE_ORIENTATION) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_ACCEPT_TAC FINITE_CYCLIC_VERTICES;
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `n - 2` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[bezier_refined_cycle] THEN
      COND_CASES_TAC THEN ASM_ARITH_TAC];
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `0` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[bezier_refined_cycle] THEN
      COND_CASES_TAC THEN ASM_ARITH_TAC];
    USE_THEN "endpoint" ACCEPT_TAC;
    X_GEN_TAC `x:real^2` THEN DISCH_THEN(LABEL_TAC "vertex") THEN
    MATCH_MP_TAC(ISPECL
     [`z:num->real^2`; `n:num`; `x:real^2`]
     STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_ZERO_CHORD_SIDE) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_ZERO_CHORD_EQ THEN
    ASM_REWRITE_TAC[];
    MP_TAC(ISPECL [`z:num->real^2`; `n:num`]
      STRICTLY_CONVEX_CYCLE_LAST_TRIANGLE) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL
     [`(z:num->real^2) (n - 2)`;
      `(z:num->real^2) (n - 1)`;
      `(z:num->real^2) 0`]
     PLANE_ORIENTATION_SWAP) THEN
    ASM_REAL_ARITH_TAC]);;

let bezier_chain_parameter = new_definition
 `bezier_chain_parameter k r = &r / &(k + 1)`;;

let BEZIER_CHAIN_PARAMETER_BOUNDS = prove
 (`!k r. r <= k + 1
          ==> &0 <= bezier_chain_parameter k r /\
              bezier_chain_parameter k r <= &1`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[bezier_chain_parameter] THEN DISCH_TAC THEN
  SUBGOAL_THEN `&0 < &(k + 1)` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_OF_NUM_LT] THEN ARITH_TAC;
    CONJ_TAC THENL
     [MATCH_MP_TAC REAL_LE_DIV THEN
      CONJ_TAC THEN REWRITE_TAC[REAL_OF_NUM_LE] THEN ARITH_TAC;
      ASM_SIMP_TAC[REAL_LE_LDIV_EQ; REAL_MUL_LID; REAL_OF_NUM_LE]]]);;

let BEZIER_CHAIN_PARAMETER_MONO = prove
 (`!k r s. r < s
            ==> bezier_chain_parameter k r <
                bezier_chain_parameter k s`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[bezier_chain_parameter] THEN DISCH_TAC THEN
  SUBGOAL_THEN `&0 < &(k + 1)` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_OF_NUM_LT] THEN ARITH_TAC;
    ASM_SIMP_TAC[REAL_LT_DIV2_EQ; REAL_OF_NUM_LT]]);;

let bezier_chain_point = new_definition
 `bezier_chain_point (z:num->real^2) n k r =
        quadratic_bezier
          (z (n - 2)) (z (n - 1)) (z 0)
          (bezier_chain_parameter k r)`;;

let BEZIER_CHAIN_POINT_0 = prove
 (`!z:num->real^2. !n k.
        bezier_chain_point z n k 0 = z (n - 2)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[bezier_chain_point; bezier_chain_parameter;
              REAL_OF_NUM_EQ; real_div; REAL_MUL_LZERO;
              QUADRATIC_BEZIER_0]);;

let BEZIER_CHAIN_POINT_LAST = prove
 (`!z:num->real^2. !n k.
        bezier_chain_point z n k (k + 1) = z 0`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[bezier_chain_point; bezier_chain_parameter] THEN
  SUBGOAL_THEN `~(&(k + 1) = &0)` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_OF_NUM_EQ] THEN ARITH_TAC;
    ASM_SIMP_TAC[REAL_DIV_REFL; QUADRATIC_BEZIER_1]]);;

let BEZIER_CHAIN_POINT_INTERIOR = prove
 (`!z:num->real^2. !n k r.
        bezier_chain_point z n k (r + 1) =
        bezier_arc_point z n k r`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[bezier_chain_point; bezier_arc_point;
              bezier_chain_parameter; bezier_parameter]);;

let STRICTLY_CONVEX_CYCLE_BEZIER_CHAIN_CONTROL_PAIR = prove
 (`!z:num->real^2. !n k r s.
        strictly_convex_cycle z n /\ 3 <= n /\ r < s /\ s <= k + 1
        ==> plane_orientation (z (n - 1))
              (bezier_chain_point z n k r)
              (bezier_chain_point z n k s) < &0`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex nlarge rs sbound" THEN
  SUBGOAL_THEN
   `&0 < plane_orientation
          (z (n - 2)) (z (n - 1)) ((z:num->real^2) 0)`
  (LABEL_TAC "triangle") THENL
   [MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_LAST_TRIANGLE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_orientation (z (n - 1)) (z (n - 2)) ((z:num->real^2) 0) =
    --plane_orientation (z (n - 2)) (z (n - 1)) (z 0)`
  (LABEL_TAC "control_triangle") THENL
   [REWRITE_TAC[plane_orientation] THEN CONV_TAC REAL_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `r <= k + 1` (LABEL_TAC "rbound") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`k:num`; `r:num`] BEZIER_CHAIN_PARAMETER_BOUNDS) THEN
  MP_TAC(SPECL [`k:num`; `s:num`] BEZIER_CHAIN_PARAMETER_BOUNDS) THEN
  MP_TAC(SPECL [`k:num`; `r:num`; `s:num`]
    BEZIER_CHAIN_PARAMETER_MONO) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "parameter_order") THEN
  INTRO_TAC "snonnegative sbound_parameter" THEN
  INTRO_TAC "rnonnegative rbound_parameter" THEN
  SUBGOAL_THEN
   `&0 < bezier_chain_parameter k r +
         bezier_chain_parameter k s -
         &2 * bezier_chain_parameter k r *
              bezier_chain_parameter k s`
  (LABEL_TAC "coefficient") THENL
   [SUBGOAL_THEN
     `bezier_chain_parameter k r + bezier_chain_parameter k s -
      &2 * bezier_chain_parameter k r * bezier_chain_parameter k s =
      bezier_chain_parameter k r *
        (&1 - bezier_chain_parameter k s) +
      bezier_chain_parameter k s *
        (&1 - bezier_chain_parameter k r)`
    SUBST1_TAC THENL
     [CONV_TAC REAL_RING;
      MATCH_MP_TAC REAL_LET_ADD THEN CONJ_TAC THENL
       [MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC;
        MATCH_MP_TAC REAL_LT_MUL THEN ASM_REAL_ARITH_TAC]];
    ALL_TAC] THEN
  REWRITE_TAC[bezier_chain_point;
              PLANE_ORIENTATION_QUADRATIC_BEZIER_PAIR;
              PLANE_ORIENTATION_REFL] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `&0 < bezier_chain_parameter k s - bezier_chain_parameter k r`
  (LABEL_TAC "difference") THENL
   [ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[REAL_MUL_RZERO; REAL_ADD_LID; REAL_ADD_RID;
              REAL_MUL_RNEG; REAL_NEG_LT0] THEN
  REPEAT(MATCH_MP_TAC REAL_LT_MUL THEN CONJ_TAC) THEN
  ASM_REWRITE_TAC[]);;

let STRICTLY_CONVEX_CYCLE_BEZIER_CHAIN_FAN_INTER = prove
 (`!z:num->real^2. !n k r s.
        strictly_convex_cycle z n /\ 3 <= n /\
        r <= k + 1 /\ s <= k + 1 /\ ~(r = s)
        ==> segment[z (n - 1),bezier_chain_point z n k r] INTER
            segment[z (n - 1),bezier_chain_point z n k s] =
            {z (n - 1)}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "convex nlarge rbound sbound distinct" THEN
  GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [SEGMENT_SYM] THEN
  MATCH_MP_TAC INTER_SEGMENT THEN DISJ2_TAC THEN
  DISCH_THEN(LABEL_TAC "collinear") THEN
  ASM_CASES_TAC `r < s` THENL
   [SUBGOAL_THEN
     `plane_orientation (z (n - 1))
        (bezier_chain_point z n k r)
        (bezier_chain_point z n k s) = &0`
    (LABEL_TAC "zero") THENL
     [REWRITE_TAC[PLANE_ORIENTATION_EQ_0_COLLINEAR] THEN
      ONCE_REWRITE_TAC[SET_RULE
       `{a:real^2,b,c} = {b,a,c}`] THEN
      USE_THEN "collinear" ACCEPT_TAC;
      MP_TAC(ISPECL
       [`z:num->real^2`; `n:num`; `k:num`; `r:num`; `s:num`]
       STRICTLY_CONVEX_CYCLE_BEZIER_CHAIN_CONTROL_PAIR) THEN
      ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC];
    SUBGOAL_THEN `s < r` (LABEL_TAC "sr") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `plane_orientation (z (n - 1))
        (bezier_chain_point z n k s)
        (bezier_chain_point z n k r) = &0`
    (LABEL_TAC "zero") THENL
     [REWRITE_TAC[PLANE_ORIENTATION_EQ_0_COLLINEAR] THEN
      ONCE_REWRITE_TAC[SET_RULE
       `{a:real^2,b,c} = {c,a,b}`] THEN
      USE_THEN "collinear" ACCEPT_TAC;
      MP_TAC(ISPECL
       [`z:num->real^2`; `n:num`; `k:num`; `s:num`; `r:num`]
      STRICTLY_CONVEX_CYCLE_BEZIER_CHAIN_CONTROL_PAIR) THEN
      ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC]]);;

let STRICTLY_CONVEX_CYCLE_BEZIER_CHAIN_FAN_HULL = prove
 (`!z:num->real^2. !n k r.
        strictly_convex_cycle z n /\ 3 <= n /\ r <= k + 1
        ==> segment[z (n - 1),bezier_chain_point z n k r] INTER
            convex hull
             (cyclic_vertices
               (bezier_refined_cycle z n (bezier_parameter k))
               (n - 1 + k)) =
            {bezier_chain_point z n k r}`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex nlarge rbound" THEN
  ASM_CASES_TAC `k = 0` THENL
   [SUBGOAL_THEN `r = 0 \/ r = 1`
    (DISJ_CASES_THEN SUBST1_TAC) THENL
     [ASM_ARITH_TAC;
      MP_TAC(ISPECL
       [`z:num->real^2`; `n:num`; `(z:num->real^2) (n - 2)`]
       STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_ZERO_ENDPOINT_FAN_HULL) THEN
      ASM_REWRITE_TAC[BEZIER_CHAIN_POINT_0; IN_INSERT; ADD_CLAUSES];
      ASM_REWRITE_TAC[
       REWRITE_RULE[ADD_CLAUSES]
        (SPECL [`z:num->real^2`; `n:num`; `0`]
          BEZIER_CHAIN_POINT_LAST)] THEN
      MP_TAC(ISPECL
       [`z:num->real^2`; `n:num`; `(z:num->real^2) 0`]
       STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_ZERO_ENDPOINT_FAN_HULL) THEN
      ASM_REWRITE_TAC[IN_INSERT; IN_SING; ADD_CLAUSES]];
    ALL_TAC] THEN
  SUBGOAL_THEN `0 < k` (LABEL_TAC "kpositive") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `r = 0` THENL
   [MP_TAC(ISPECL [`z:num->real^2`; `n:num`; `k:num`]
      STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_FIRST_ENDPOINT_FAN_HULL) THEN
    ASM_REWRITE_TAC[BEZIER_CHAIN_POINT_0];
    ALL_TAC] THEN
  ASM_CASES_TAC `r = k + 1` THENL
   [MP_TAC(ISPECL [`z:num->real^2`; `n:num`; `k:num`]
      STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_LAST_ENDPOINT_FAN_HULL) THEN
    ASM_REWRITE_TAC[BEZIER_CHAIN_POINT_LAST];
    ALL_TAC] THEN
  SUBGOAL_THEN `0 < r /\ r - 1 < k`
  (CONJUNCTS_THEN2 (LABEL_TAC "rpositive") (LABEL_TAC "sample")) THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `r = (r - 1) + 1` (LABEL_TAC "index") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`z:num->real^2`; `n:num`; `k:num`; `r - 1`]
   STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_FAN_HULL) THEN
  ASM_REWRITE_TAC[GSYM BEZIER_CHAIN_POINT_INTERIOR] THEN
  DISCH_THEN(LABEL_TAC "interior_hull") THEN
  USE_THEN "index" (fun ith ->
   USE_THEN "interior_hull"
    (ACCEPT_TAC o SUBS [SYM ith])));;

let STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_CONTROL_OUTSIDE_HULL_GENERAL = prove
 (`!z:num->real^2. !n k.
        strictly_convex_cycle z n /\ 3 <= n
        ==> ~(z (n - 1) IN
              convex hull
               (cyclic_vertices
                 (bezier_refined_cycle z n (bezier_parameter k))
                 (n - 1 + k)))`,
  REPEAT GEN_TAC THEN INTRO_TAC "convex nlarge" THEN
  DISCH_THEN(LABEL_TAC "control_hull") THEN
  SUBGOAL_THEN
   `(z:num->real^2) (n - 1) IN
    segment[(z:num->real^2) (n - 1),bezier_chain_point z n k 0] INTER
    convex hull
     (cyclic_vertices
       (bezier_refined_cycle z n (bezier_parameter k))
       (n - 1 + k))`
  (LABEL_TAC "control_intersection") THENL
   [REWRITE_TAC[IN_INTER; ENDS_IN_SEGMENT] THEN
    USE_THEN "control_hull" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(z:num->real^2) (n - 1) = bezier_chain_point z n k 0`
  (LABEL_TAC "control_chain_endpoint") THENL
   [MP_TAC(ISPECL [`z:num->real^2`; `n:num`; `k:num`; `0`]
     STRICTLY_CONVEX_CYCLE_BEZIER_CHAIN_FAN_HULL) THEN
    ASM_REWRITE_TAC[ARITH_RULE `0 <= (k:num) + 1`] THEN
    DISCH_THEN(fun th ->
     USE_THEN "control_intersection" (MP_TAC o REWRITE_RULE[th])) THEN
    REWRITE_TAC[IN_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN `(z:num->real^2) (n - 1) = z (n - 2)`
  (LABEL_TAC "control_endpoint") THENL
   [USE_THEN "control_chain_endpoint" MP_TAC THEN
    REWRITE_TAC[BEZIER_CHAIN_POINT_0];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`z:num->real^2`; `n:num`]
    STRICTLY_CONVEX_CYCLE_LAST_TRIANGLE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "control_endpoint" (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[PLANE_ORIENTATION_REFL] THEN REAL_ARITH_TAC);;

let STRAIGHT_LINE_EMBEDDING_INSERT_VERTEX_BEZIER_CHAIN = prove
 (`!V E p v N p' z n k.
        finite_simple_graph (V:A->bool) E /\
        straight_line_embedding V E p /\
        ~(v IN V) /\ N SUBSET V /\
        (!u. u IN V ==> p' u = p u) /\
        (p':A->real^2) v = z (n - 1) /\
        strictly_convex_cycle z n /\ 3 <= n /\
        convex hull (IMAGE p V) =
        convex hull
         (cyclic_vertices
           (bezier_refined_cycle z n (bezier_parameter k))
           (n - 1 + k)) /\
        (!u. u IN N
             ==> ?r. r <= k + 1 /\ p u = bezier_chain_point z n k r)
        ==> straight_line_embedding (v INSERT V)
             (IMAGE (\u:A. {v,u}) N UNION E) p'`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding fresh neighbors agrees new_point convex nlarge \
    hull neighbor_points" THEN
  USE_THEN "embedding"
   (MP_TAC o REWRITE_RULE[straight_line_embedding]) THEN
  INTRO_TAC "injective edge_vertices edge_intersections" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `v:A`; `N:A->bool`; `p':A->real^2`]
   STRAIGHT_LINE_EMBEDDING_INSERT_VERTEX_STAR_OUTSIDE_HULL) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    USE_THEN "embedding" ACCEPT_TAC;
    USE_THEN "fresh" ACCEPT_TAC;
    USE_THEN "neighbors" ACCEPT_TAC;
    USE_THEN "agrees" ACCEPT_TAC;
    USE_THEN "new_point" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "hull" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC
     STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_CONTROL_OUTSIDE_HULL_GENERAL THEN
    ASM_REWRITE_TAC[];
    X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "neighbor") THEN
    USE_THEN "neighbor_points" (fun th ->
     USE_THEN "neighbor" (fun nth ->
      MP_TAC(MATCH_MP (SPEC `u:A` th) nth))) THEN
    INTRO_TAC "@r. rbound endpoint" THEN
    USE_THEN "new_point" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "endpoint" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "hull" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_BEZIER_CHAIN_FAN_HULL THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN
    INTRO_TAC "neighbor neighbor' distinct" THEN
    USE_THEN "neighbor_points" (fun th ->
     USE_THEN "neighbor" (fun nth ->
      MP_TAC(MATCH_MP (SPEC `u:A` th) nth))) THEN
    INTRO_TAC "@r. rbound endpoint" THEN
    USE_THEN "neighbor_points" (fun th ->
     USE_THEN "neighbor'" (fun nth ->
      MP_TAC(MATCH_MP (SPEC `w:A` th) nth))) THEN
    INTRO_TAC "@s. sbound endpoint'" THEN
    SUBGOAL_THEN `~((r:num) = (s:num))`
    (LABEL_TAC "indices_distinct") THENL
     [DISCH_THEN(LABEL_TAC "equal_indices") THEN
      SUBGOAL_THEN `(u:A) IN V` (LABEL_TAC "u_vertex") THENL
       [USE_THEN "neighbors" MP_TAC THEN
        USE_THEN "neighbor" MP_TAC THEN SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(w:A) IN V` (LABEL_TAC "w_vertex") THENL
       [USE_THEN "neighbors" MP_TAC THEN
        USE_THEN "neighbor'" MP_TAC THEN SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(p:A->real^2) u = (p:A->real^2) w`
      (LABEL_TAC "same_point") THENL
       [ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = w` (LABEL_TAC "same_vertex") THENL
       [USE_THEN "injective" MP_TAC THEN REWRITE_TAC[INJ; IN_UNIV] THEN
        DISCH_THEN(MP_TAC o SPECL [`u:A`; `w:A`]) THEN
        ASM_REWRITE_TAC[];
        ACCEPT_TAC
         (MP (NOT_ELIM(ASSUME `~((u:A) = w)`))
             (ASSUME `(u:A) = w`))];
      ALL_TAC] THEN
    USE_THEN "new_point" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "endpoint" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "endpoint'" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_BEZIER_CHAIN_FAN_INTER THEN
    ASM_REWRITE_TAC[]]);;

(* Replace the last boundary vertex by a chain, retaining the old prefix.    *)

let cyclic_delete_last = new_definition
 `cyclic_delete_last (q:num->A) w n i =
        if i < n - 1 then q i else w (i - (n - 2))`;;

let CYCLIC_DELETE_LAST_PREFIX = prove
 (`!q w n i.
        i < n - 1
        ==> cyclic_delete_last (q:num->A) w n i = q i`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[cyclic_delete_last] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

let CYCLIC_DELETE_LAST_CHAIN = prove
 (`!q w n r.
        3 <= n /\ 0 < r
        ==> cyclic_delete_last (q:num->A) w n (n - 2 + r) = w r`,
  REPEAT GEN_TAC THEN INTRO_TAC "nlarge rpositive" THEN
  REWRITE_TAC[cyclic_delete_last] THEN
  SUBGOAL_THEN `~(n - 2 + r < n - 1)` ASSUME_TAC THENL
   [ASM_ARITH_TAC;
    ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN ASM_ARITH_TAC]);;

let CYCLIC_DELETE_LAST_FIRST = prove
 (`!q w n.
        3 <= n
        ==> cyclic_delete_last (q:num->A) w n 0 = q 0`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN ASM_ARITH_TAC);;

let CYCLIC_DELETE_LAST_PENULTIMATE = prove
 (`!q w n.
        3 <= n
        ==> cyclic_delete_last (q:num->A) w n (n - 2) = q (n - 2)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN ASM_ARITH_TAC);;

let recursive_triangulated_disk_RULES,
    recursive_triangulated_disk_INDUCT,
    recursive_triangulated_disk_CASES = new_inductive_definition
 `(!q:num->A.
        INJ q (cyclic_indices 3) (:A)
        ==> recursive_triangulated_disk
             (cyclic_vertices q 3) (cyclic_edges q 3) q 3) /\
  (!V E q:num->A. !n k w.
        recursive_triangulated_disk
          V E (cyclic_delete_last q w n) (n - 1 + k) /\
        3 <= n /\
        INJ q (cyclic_indices n) (:A) /\
        ~(q (n - 1) IN V) /\
        cyclic_vertices w (k + 2) SUBSET V /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0
        ==> recursive_triangulated_disk
             (q (n - 1) INSERT V)
             (IMAGE (\u:A. {q (n - 1),u})
                    (cyclic_vertices w (k + 2)) UNION E)
             q n) /\
  (!V1 E1 V2 E2 q:num->A. !n j.
        recursive_triangulated_disk
          V1 E1 (cyclic_split_left q n j) (j + 2) /\
        recursive_triangulated_disk
          V2 E2 (cyclic_split_right q j) (n - j) /\
        0 < j /\ j + 2 < n /\
        INJ q (cyclic_indices n) (:A) /\
        V1 INTER V2 = {q j,q (n - 1)} /\
        {q j,q (n - 1)} IN E1 /\
        {q j,q (n - 1)} IN E2
        ==> recursive_triangulated_disk
             (V1 UNION V2) (E1 UNION E2) q n)`;;

let QUADRATIC_BEZIER_IN_CONVEX_HULL_3 = prove
 (`!a b c:real^2. !t.
        &0 <= t /\ t <= &1
        ==> quadratic_bezier a b c t IN convex hull {a,b,c}`,
  REPEAT GEN_TAC THEN INTRO_TAC "t_nonnegative t_bound" THEN
  REWRITE_TAC[CONVEX_HULL_3; IN_ELIM_THM; quadratic_bezier] THEN
  MAP_EVERY EXISTS_TAC
   [`(&1 - (t:real)) pow 2`;
    `&2 * (&1 - (t:real)) * t`;
    `(t:real) pow 2`] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_ACCEPT_TAC REAL_LE_POW_2;
    MATCH_MP_TAC REAL_LE_MUL THEN CONJ_TAC THENL
     [REAL_ARITH_TAC;
      MATCH_MP_TAC REAL_LE_MUL THEN ASM_REAL_ARITH_TAC];
    MATCH_ACCEPT_TAC REAL_LE_POW_2;
    CONV_TAC REAL_RING;
    REFL_TAC]);;

let CYCLIC_VERTICES_BEZIER_REFINED_SUBSET_CONVEX_HULL = prove
 (`!z:num->real^2. !n k.
        3 <= n
        ==> cyclic_vertices
             (bezier_refined_cycle z n (bezier_parameter k))
             (n - 1 + k)
            SUBSET convex hull (cyclic_vertices z n)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "nlarge") THEN
  REWRITE_TAC[SUBSET; IN_CYCLIC_VERTICES] THEN
  X_GEN_TAC `x:real^2` THEN
  INTRO_TAC "@i. index point" THEN
  USE_THEN "point" SUBST1_TAC THEN
  ASM_CASES_TAC `i < n - 1` THENL
   [REWRITE_TAC[bezier_refined_cycle] THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC HULL_INC THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `i:num` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[bezier_refined_cycle] THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `{(z:num->real^2) (n - 2),z (n - 1),z 0}
    SUBSET cyclic_vertices z n`
  (LABEL_TAC "triangle_subset") THENL
   [REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
    REPEAT CONJ_TAC THEN REWRITE_TAC[IN_CYCLIC_VERTICES] THENL
     [EXISTS_TAC `n - 2` THEN ASM_ARITH_TAC;
      EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC;
      EXISTS_TAC `0` THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC(REWRITE_RULE[SUBSET]
   (MATCH_MP
    (ISPECL
      [`convex:(real^2->bool)->bool`;
       `{(z:num->real^2) (n - 2),z (n - 1),z 0}`;
       `cyclic_vertices (z:num->real^2) n`]
      HULL_MONO)
    (ASSUME
     `{(z:num->real^2) (n - 2),z (n - 1),z 0}
      SUBSET cyclic_vertices z n`))) THEN
  MATCH_MP_TAC QUADRATIC_BEZIER_IN_CONVEX_HULL_3 THEN
  MP_TAC(SPECL [`k:num`; `i - (n - 1)`]
    BEZIER_PARAMETER_BOUNDS) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    ASM_REAL_ARITH_TAC]);;
let CYCLIC_INDICES_3 = prove
 (`cyclic_indices 3 = {0,1,2}`,
  REWRITE_TAC[cyclic_indices; EXTENSION; IN_ELIM_THM;
              IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let CYCLIC_VERTICES_3 = prove
 (`!q:num->A. cyclic_vertices q 3 = {q 0,q 1,q 2}`,
  GEN_TAC THEN
  REWRITE_TAC[cyclic_vertices; CYCLIC_INDICES_3; IMAGE_CLAUSES]);;

let CYCLIC_EDGES_3 = prove
 (`!q:num->A.
        cyclic_edges q 3 = {{q 0,q 1},{q 1,q 2},{q 2,q 0}}`,
  GEN_TAC THEN
  REWRITE_TAC[cyclic_edges; CYCLIC_INDICES_3; IMAGE_CLAUSES] THEN
  CONV_TAC NUM_REDUCE_CONV);;

let STRAIGHT_LINE_EMBEDDING_TRIANGLE = prove
 (`!u v w:A. !p:A->real^2.
        ~(u = v) /\ ~(v = w) /\ ~(w = u) /\
        ~collinear {p u,p v,p w}
        ==> straight_line_embedding
             {u,v,w} {{u,v},{v,w},{w,u}} p`,
  REPEAT GEN_TAC THEN INTRO_TAC "uv vw wu noncollinear" THEN
  SUBGOAL_THEN `~((p:A->real^2) u = p v)`
  (LABEL_TAC "puv") THENL
   [DISCH_THEN(fun th ->
      USE_THEN "noncollinear" MP_TAC THEN
      REWRITE_TAC[th; SET_RULE `{a,a,b} = {a,b}`; COLLINEAR_2]);
    ALL_TAC] THEN
  SUBGOAL_THEN `~((p:A->real^2) v = p w)`
  (LABEL_TAC "pvw") THENL
   [DISCH_THEN(fun th ->
      USE_THEN "noncollinear" MP_TAC THEN
      REWRITE_TAC[th; SET_RULE `{a,b,b} = {a,b}`; COLLINEAR_2]);
    ALL_TAC] THEN
  SUBGOAL_THEN `~((p:A->real^2) w = p u)`
  (LABEL_TAC "pwu") THENL
   [DISCH_THEN(fun th ->
      USE_THEN "noncollinear" MP_TAC THEN
      REWRITE_TAC[th; SET_RULE `{a,b,a} = {a,b}`; COLLINEAR_2]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `segment[(p:A->real^2) u,p v] INTER segment[p v,p w] = {p v}`
  (LABEL_TAC "uv_vw") THENL
   [MATCH_MP_TAC INTER_SEGMENT THEN
    DISJ2_TAC THEN USE_THEN "noncollinear" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `segment[(p:A->real^2) v,p w] INTER segment[p w,p u] = {p w}`
  (LABEL_TAC "vw_wu") THENL
   [MATCH_MP_TAC INTER_SEGMENT THEN DISJ2_TAC THEN
    ONCE_REWRITE_TAC[SET_RULE `{a,b,c} = {c,a,b}`] THEN
    USE_THEN "noncollinear" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `segment[(p:A->real^2) w,p u] INTER segment[p u,p v] = {p u}`
  (LABEL_TAC "wu_uv") THENL
   [MATCH_MP_TAC INTER_SEGMENT THEN DISJ2_TAC THEN
    ONCE_REWRITE_TAC[SET_RULE `{a,b,c} = {b,c,a}`] THEN
    USE_THEN "noncollinear" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `segment[(p:A->real^2) v,p w] INTER segment[p u,p v] = {p v}`
  (LABEL_TAC "vw_uv") THENL
   [ONCE_REWRITE_TAC[INTER_COMM] THEN USE_THEN "uv_vw" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `segment[(p:A->real^2) w,p u] INTER segment[p v,p w] = {p w}`
  (LABEL_TAC "wu_vw") THENL
   [ONCE_REWRITE_TAC[INTER_COMM] THEN USE_THEN "vw_wu" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `segment[(p:A->real^2) u,p v] INTER segment[p w,p u] = {p u}`
  (LABEL_TAC "uv_wu") THENL
   [ONCE_REWRITE_TAC[INTER_COMM] THEN USE_THEN "wu_uv" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `({u,v}:A->bool) INTER {v,w} = {v}`
  (LABEL_TAC "edge_uv_vw") THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `({v,w}:A->bool) INTER {w,u} = {w}`
  (LABEL_TAC "edge_vw_wu") THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `({w,u}:A->bool) INTER {u,v} = {u}`
  (LABEL_TAC "edge_wu_uv") THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `({v,w}:A->bool) INTER {u,v} = {v}`
  (LABEL_TAC "edge_vw_uv") THENL
   [ONCE_REWRITE_TAC[INTER_COMM] THEN USE_THEN "edge_uv_vw" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `({w,u}:A->bool) INTER {v,w} = {w}`
  (LABEL_TAC "edge_wu_vw") THENL
   [ONCE_REWRITE_TAC[INTER_COMM] THEN USE_THEN "edge_vw_wu" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `({u,v}:A->bool) INTER {w,u} = {u}`
  (LABEL_TAC "edge_uv_wu") THENL
   [ONCE_REWRITE_TAC[INTER_COMM] THEN USE_THEN "edge_wu_uv" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[straight_line_embedding] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[INJ; IN_UNIV; IN_INSERT; NOT_IN_EMPTY] THEN
    ASM_MESON_TAC[];
    X_GEN_TAC `e:A->bool` THEN
    REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST1_TAC) THEN
    REWRITE_TAC[STRAIGHT_EDGE_PAIR; IMAGE_CLAUSES] THEN
    ASM SET_TAC[ENDS_IN_SEGMENT];
    MAP_EVERY X_GEN_TAC [`e:A->bool`; `e':A->bool`] THEN
    INTRO_TAC "edge edge' distinct" THEN
    USE_THEN "edge" MP_TAC THEN
    REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    USE_THEN "edge'" MP_TAC THEN
    REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    ASM_REWRITE_TAC[STRAIGHT_EDGE_PAIR; IMAGE_CLAUSES] THEN
    ASM_MESON_TAC[]]);;

let PRESCRIBED_TRIANGLE_STRAIGHT_LINE_EMBEDDING = prove
 (`!q:num->A. !z:num->real^2.
        INJ q (cyclic_indices 3) (:A) /\
        strictly_convex_cycle z 3
        ==> ?p:A->real^2.
              straight_line_embedding
                (cyclic_vertices q 3) (cyclic_edges q 3) p /\
              (!i. i < 3 ==> p (q i) = z i) /\
              convex hull (IMAGE p (cyclic_vertices q 3)) =
              convex hull (cyclic_vertices z 3)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective convex" THEN
  SUBGOAL_THEN
   `~((q:num->A) 0 = q 1) /\
    ~(q 1 = q 2) /\
    ~(q 2 = q 0)`
  (CONJUNCTS_THEN2 (LABEL_TAC "q01")
    (CONJUNCTS_THEN2 (LABEL_TAC "q12") (LABEL_TAC "q20"))) THENL
   [USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; CYCLIC_INDICES_3;
                IN_INSERT; NOT_IN_EMPTY] THEN
    MESON_TAC[ARITH_RULE `~(0 = 1) /\ ~(1 = 2) /\ ~(2 = 0)`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `&0 < plane_orientation
           ((z:num->real^2) 0) (z 1) (z 2)`
  (LABEL_TAC "positive") THENL
   [USE_THEN "convex" MP_TAC THEN
    REWRITE_TAC[strictly_convex_cycle] THEN
    DISCH_THEN(MP_TAC o SPECL [`0`; `1`; `2`]) THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~collinear
      {(z:num->real^2) 0,z 1,z 2}`
  (LABEL_TAC "noncollinear") THENL
   [REWRITE_TAC[GSYM PLANE_ORIENTATION_EQ_0_COLLINEAR] THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  ABBREV_TAC
   `p:A->real^2 =
      \x. if x = q 0 then z 0
          else if x = q 1 then z 1
          else z 2` THEN
  SUBGOAL_THEN
   `(p:A->real^2) (q 0) = z 0 /\
    p (q 1) = z 1 /\
    p (q 2) = z 2`
  (CONJUNCTS_THEN2 (LABEL_TAC "p0")
    (CONJUNCTS_THEN2 (LABEL_TAC "p1") (LABEL_TAC "p2"))) THENL
   [EXPAND_TAC "p" THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `p:A->real^2` THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[CYCLIC_VERTICES_3; CYCLIC_EDGES_3] THEN
    MATCH_MP_TAC STRAIGHT_LINE_EMBEDDING_TRIANGLE THEN
    ASM_REWRITE_TAC[];
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    SUBGOAL_THEN `(i:num) = 0 \/ i = 1 \/ i = 2`
    MP_TAC THENL
     [ASM_ARITH_TAC;
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST1_TAC) THEN
      ASM_REWRITE_TAC[]];
    REWRITE_TAC[CYCLIC_VERTICES_3; IMAGE_CLAUSES] THEN
    ASM_REWRITE_TAC[]]);;
let RECURSIVE_TRIANGULATED_DISK_INVARIANTS = prove
 (`!V E q:num->A. !n.
        recursive_triangulated_disk V E q n
        ==> finite_simple_graph V E /\
            3 <= n /\
            INJ q (cyclic_indices n) (:A) /\
            cyclic_vertices q n SUBSET V`,
  MATCH_MP_TAC recursive_triangulated_disk_INDUCT THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `q:num->A` THEN
    DISCH_THEN(LABEL_TAC "injective") THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`cyclic_edges (q:num->A) 3`; `q:num->A`; `3`]
       FINITE_SIMPLE_GRAPH_CYCLIC) THEN
      REWRITE_TAC[simple_graph_cycle] THEN
      ASM_REWRITE_TAC[SUBSET_REFL] THEN ARITH_TAC;
      ARITH_TAC;
      USE_THEN "injective" ACCEPT_TAC;
      REWRITE_TAC[SUBSET_REFL]];
    MAP_EVERY X_GEN_TAC
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
      `n:num`; `k:num`; `w:num->A`] THEN
    INTRO_TAC
     "(graph old_large old_injective old_boundary) nlarge injective \
      fresh neighbors first last" THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INSERT_VERTEX_STAR THEN
      ASM_REWRITE_TAC[];
      USE_THEN "nlarge" ACCEPT_TAC;
      USE_THEN "injective" ACCEPT_TAC;
      REWRITE_TAC[SUBSET; IN_CYCLIC_VERTICES] THEN
      X_GEN_TAC `x:A` THEN INTRO_TAC "@i. index point" THEN
      USE_THEN "point" SUBST1_TAC THEN
      ASM_CASES_TAC `(i:num) = n - 1` THENL
       [ASM_REWRITE_TAC[IN_INSERT];
        REWRITE_TAC[IN_INSERT] THEN DISJ2_TAC THEN
        USE_THEN "old_boundary"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
        EXISTS_TAC `i:num` THEN CONJ_TAC THENL
         [ASM_ARITH_TAC;
          MATCH_MP_TAC EQ_SYM THEN
          MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN ASM_ARITH_TAC]]];
    MAP_EVERY X_GEN_TAC
     [`V1:A->bool`; `E1:(A->bool)->bool`;
      `V2:A->bool`; `E2:(A->bool)->bool`;
      `q:num->A`; `n:num`; `j:num`] THEN
    INTRO_TAC
     "(graph1 left_large left_injective left_boundary) \
      (graph2 right_large right_injective right_boundary) \
      jpositive bound injective overlap chord1 chord2" THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_UNION THEN ASM_REWRITE_TAC[];
      ASM_ARITH_TAC;
      USE_THEN "injective" ACCEPT_TAC;
      REWRITE_TAC[SUBSET; IN_CYCLIC_VERTICES] THEN
      X_GEN_TAC `x:A` THEN INTRO_TAC "@i. index point" THEN
      USE_THEN "point" SUBST1_TAC THEN
      ASM_CASES_TAC `(i:num) <= j` THENL
       [REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
        USE_THEN "left_boundary"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
        EXISTS_TAC `i:num` THEN CONJ_TAC THENL
         [ASM_ARITH_TAC;
          REWRITE_TAC[cyclic_split_left] THEN ASM_REWRITE_TAC[] THEN
          ASM_ARITH_TAC];
        REWRITE_TAC[IN_UNION] THEN DISJ2_TAC THEN
        USE_THEN "right_boundary"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
        EXISTS_TAC `i - j` THEN CONJ_TAC THENL
         [ASM_ARITH_TAC;
          REWRITE_TAC[cyclic_split_right] THEN AP_TERM_TAC THEN
          ASM_ARITH_TAC]]]]);;

(* Index and function-pasting helpers for the geometric induction.           *)

let CYCLIC_VERTICES_SPLIT_UNION = prove
 (`!q:num->A. !n j.
        j + 2 < n
        ==> cyclic_vertices (cyclic_split_left q n j) (j + 2) UNION
            cyclic_vertices (cyclic_split_right q j) (n - j) =
            cyclic_vertices q n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "bound") THEN
  REWRITE_TAC[EXTENSION; IN_UNION; IN_CYCLIC_VERTICES] THEN
  X_GEN_TAC `x:A` THEN EQ_TAC THENL
   [DISCH_THEN(DISJ_CASES_THEN2
     (X_CHOOSE_THEN `i:num`
       (CONJUNCTS_THEN2 (LABEL_TAC "index") (LABEL_TAC "point")))
     (X_CHOOSE_THEN `i:num`
       (CONJUNCTS_THEN2 (LABEL_TAC "index") (LABEL_TAC "point")))) THENL
     [USE_THEN "point" SUBST1_TAC THEN
      REWRITE_TAC[cyclic_split_left] THEN
      ASM_CASES_TAC `(i:num) < j + 1` THEN ASM_REWRITE_TAC[] THENL
       [EXISTS_TAC `i:num` THEN ASM_ARITH_TAC;
        EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC];
      USE_THEN "point" SUBST1_TAC THEN
      REWRITE_TAC[cyclic_split_right] THEN
      EXISTS_TAC `j + i` THEN ASM_ARITH_TAC];
    INTRO_TAC "@i. index point" THEN
    USE_THEN "point" SUBST1_TAC THEN
    ASM_CASES_TAC `(i:num) <= j` THENL
     [DISJ1_TAC THEN EXISTS_TAC `i:num` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[cyclic_split_left] THEN ASM_REWRITE_TAC[] THEN
        ASM_ARITH_TAC];
      DISJ2_TAC THEN EXISTS_TAC `i - j` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[cyclic_split_right] THEN AP_TERM_TAC THEN
        ASM_ARITH_TAC]]]);;

let PASTE_FUNCTIONS_ON_TWO_POINT_INTERSECTION = prove
 (`!V1 V2:A->bool. !p1 p2:A->B. !u v.
        V1 INTER V2 = {u,v} /\
        p1 u = p2 u /\ p1 v = p2 v
        ==> ?p:A->B.
              (!x. x IN V1 ==> p x = p1 x) /\
              (!x. x IN V2 ==> p x = p2 x)`,
  REPEAT GEN_TAC THEN INTRO_TAC "overlap agree_u agree_v" THEN
  EXISTS_TAC `\x:A. if x IN V1 then (p1:A->B) x else p2 x` THEN
  CONJ_TAC THENL
   [SIMP_TAC[];
    X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "in_second") THEN
    ASM_CASES_TAC `(x:A) IN V1` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(x:A) IN V1 INTER V2` (LABEL_TAC "in_overlap") THENL
     [ASM_REWRITE_TAC[IN_INTER];
      USE_THEN "in_overlap" MP_TAC THEN
      USE_THEN "overlap" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN
      DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
      ASM_REWRITE_TAC[]]]);;

let CYCLIC_DELETE_LAST_BEZIER_BOUNDARY = prove
 (`!p:A->real^2. !q w:num->A. !z:num->real^2. !n k.
        3 <= n /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0 /\
        (!i. i < n - 1 + k
             ==> p (cyclic_delete_last q w n i) =
                 bezier_refined_cycle z n (bezier_parameter k) i)
        ==> (!i. i < n - 1 ==> p (q i) = z i) /\
            (!u. u IN cyclic_vertices w (k + 2)
                 ==> ?r. r <= k + 1 /\
                         p u = bezier_chain_point z n k r)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "nlarge first last boundary" THEN CONJ_TAC THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    USE_THEN "boundary" (MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      ASM_SIMP_TAC[CYCLIC_DELETE_LAST_PREFIX; bezier_refined_cycle]];
    X_GEN_TAC `u:A` THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    INTRO_TAC "@r. index point" THEN
    USE_THEN "point" SUBST1_TAC THEN
    EXISTS_TAC `r:num` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    ASM_CASES_TAC `(r:num) = 0` THENL
     [ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `n - 2 < n - 1` (LABEL_TAC "penultimate") THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      USE_THEN "boundary" (MP_TAC o SPEC `n - 2`) THEN
      ANTS_TAC THENL
       [ASM_ARITH_TAC;
        ASM_SIMP_TAC[CYCLIC_DELETE_LAST_PENULTIMATE;
                     bezier_refined_cycle; BEZIER_CHAIN_POINT_0]];
      ALL_TAC] THEN
    ASM_CASES_TAC `(r:num) = k + 1` THENL
     [ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `0 < n - 1` (LABEL_TAC "first_index") THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      USE_THEN "boundary" (MP_TAC o SPEC `0`) THEN
      ANTS_TAC THENL
       [ASM_ARITH_TAC;
        ASM_SIMP_TAC[CYCLIC_DELETE_LAST_FIRST] THEN
        REWRITE_TAC[BEZIER_CHAIN_POINT_LAST] THEN
        ASM_SIMP_TAC[bezier_refined_cycle]];
      ALL_TAC] THEN
    SUBGOAL_THEN `(r:num) = (r - 1) + 1`
    (LABEL_TAC "successor") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `0 < (r:num)` (LABEL_TAC "positive") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~(n - 2 + r < n - 1)`
    (LABEL_TAC "on_chain") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "boundary" (MP_TAC o SPEC `n - 2 + r`) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      ASM_SIMP_TAC[CYCLIC_DELETE_LAST_CHAIN] THEN
      ASM_REWRITE_TAC[bezier_refined_cycle] THEN
      SUBGOAL_THEN `(n - 2 + r) - (n - 1) = r - 1`
      SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      REWRITE_TAC[GSYM bezier_arc_point] THEN
      DISCH_TAC THEN
      REWRITE_TAC[GSYM BEZIER_CHAIN_POINT_INTERIOR] THEN
      AP_TERM_TAC THEN ASM_ARITH_TAC]]);;
(* Convex-hull bookkeeping for the geometric induction.                      *)

let CONVEX_HULL_UNION_EQ = prove
 (`!s t u v:real^2->bool.
        convex hull s = convex hull u /\
        convex hull t = convex hull v
        ==> convex hull (s UNION t) = convex hull (u UNION v)`,
  ONCE_REWRITE_TAC[HULL_UNION] THEN SIMP_TAC[]);;

let CONVEX_HULL_INSERT_EQ = prove
 (`!a:real^2. !s t.
        convex hull s = convex hull t
        ==> convex hull (a INSERT s) = convex hull (a INSERT t)`,
  ONCE_REWRITE_TAC[HULL_INSERT] THEN SIMP_TAC[]);;

let CONVEX_HULL_INSERT_BEZIER_REFINED_CYCLE = prove
 (`!z:num->real^2. !n k.
        3 <= n
        ==> convex hull
             (z (n - 1) INSERT
              cyclic_vertices
               (bezier_refined_cycle z n (bezier_parameter k))
               (n - 1 + k)) =
            convex hull (cyclic_vertices z n)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "nlarge") THEN
  MATCH_MP_TAC CONVEX_HULLS_EQ THEN CONJ_TAC THENL
   [REWRITE_TAC[INSERT_SUBSET] THEN CONJ_TAC THENL
     [MATCH_MP_TAC HULL_INC THEN
      REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `(n:num) - 1` THEN ASM_ARITH_TAC;
      MATCH_MP_TAC CYCLIC_VERTICES_BEZIER_REFINED_SUBSET_CONVEX_HULL THEN
      ASM_REWRITE_TAC[]];
    REWRITE_TAC[SUBSET; IN_CYCLIC_VERTICES] THEN
    X_GEN_TAC `x:real^2` THEN INTRO_TAC "@i. index point" THEN
    USE_THEN "point" SUBST1_TAC THEN
    MATCH_MP_TAC HULL_INC THEN
    REWRITE_TAC[IN_INSERT] THEN
    ASM_CASES_TAC `(i:num) = n - 1` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(i:num) < n - 1` (LABEL_TAC "old_index") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    DISJ2_TAC THEN REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `i:num` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      ASM_SIMP_TAC[bezier_refined_cycle]]]);;

let FINITE_SIMPLE_GRAPH_EDGE_VERTICES = prove
 (`!V E. !u v:A.
        finite_simple_graph V E /\ {u,v} IN E
        ==> u IN V /\ v IN V`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge" THEN
  USE_THEN "graph" (MP_TAC o REWRITE_RULE[finite_simple_graph]) THEN
  INTRO_TAC "finite_vertices finite_edges edges" THEN
  USE_THEN "edges" (MP_TAC o SPEC `{u:A,v}`) THEN
  ANTS_TAC THENL
   [USE_THEN "edge" ACCEPT_TAC;
    INTRO_TAC "subset size" THEN
    USE_THEN "subset" MP_TAC THEN
    REWRITE_TAC[INSERT_SUBSET; SING_SUBSET]]);;

let RECURSIVE_TRIANGULATED_DISK_EMBEDDING_STRONG = prove
 (`!V E q:num->A. !n.
        recursive_triangulated_disk V E q n
        ==> finite_simple_graph V E /\
            cyclic_vertices q n SUBSET V /\
            (!z:num->real^2.
                strictly_convex_cycle z n
                ==> ?p:A->real^2.
                      straight_line_embedding V E p /\
                      (!i. i < n ==> p (q i) = z i) /\
                      convex hull (IMAGE p V) =
                      convex hull (cyclic_vertices z n))`,
  MATCH_MP_TAC recursive_triangulated_disk_INDUCT THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `q:num->A` THEN DISCH_THEN(LABEL_TAC "injective") THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`cyclic_edges (q:num->A) 3`; `q:num->A`; `3`]
       FINITE_SIMPLE_GRAPH_CYCLIC) THEN
      REWRITE_TAC[simple_graph_cycle] THEN
      ASM_REWRITE_TAC[SUBSET_REFL] THEN ARITH_TAC;
      REWRITE_TAC[SUBSET_REFL];
      X_GEN_TAC `z:num->real^2` THEN
      DISCH_THEN(LABEL_TAC "convex") THEN
      MATCH_MP_TAC PRESCRIBED_TRIANGLE_STRAIGHT_LINE_EMBEDDING THEN
      ASM_REWRITE_TAC[]];
    MAP_EVERY X_GEN_TAC
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
      `n:num`; `k:num`; `w:num->A`] THEN
    INTRO_TAC
     "(graph old_vertices induction) nlarge injective fresh neighbors \
      first last" THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INSERT_VERTEX_STAR THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[SUBSET; IN_CYCLIC_VERTICES] THEN
      X_GEN_TAC `x:A` THEN INTRO_TAC "@i. index point" THEN
      USE_THEN "point" SUBST1_TAC THEN
      ASM_CASES_TAC `(i:num) = n - 1` THENL
       [ASM_REWRITE_TAC[IN_INSERT];
        REWRITE_TAC[IN_INSERT] THEN DISJ2_TAC THEN
        USE_THEN "old_vertices"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
        EXISTS_TAC `i:num` THEN CONJ_TAC THENL
         [ASM_ARITH_TAC;
          MATCH_MP_TAC EQ_SYM THEN
          MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN ASM_ARITH_TAC]];
      X_GEN_TAC `z:num->real^2` THEN
      DISCH_THEN(LABEL_TAC "convex") THEN
      SUBGOAL_THEN
       `strictly_convex_cycle
         (bezier_refined_cycle z n (bezier_parameter k))
         (n - 1 + k)`
      (LABEL_TAC "refined_convex") THENL
       [MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_BEZIER_REFINED_UNIFORM THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "induction"
       (MP_TAC o SPEC
        `bezier_refined_cycle (z:num->real^2) n (bezier_parameter k)`) THEN
      ANTS_TAC THENL
       [USE_THEN "refined_convex" ACCEPT_TAC;
        INTRO_TAC "@p. embedding boundary hull"] THEN
      MP_TAC(ISPECL
       [`p:A->real^2`; `q:num->A`; `w:num->A`; `z:num->real^2`;
        `n:num`; `k:num`]
       CYCLIC_DELETE_LAST_BEZIER_BOUNDARY) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        INTRO_TAC "old_boundary neighbor_points"] THEN
      ABBREV_TAC
       `p':A->real^2 =
          \x. if x = q (n - 1) then z (n - 1) else p x` THEN
      SUBGOAL_THEN `!x:A. x IN V ==> (p':A->real^2) x = p x`
      (LABEL_TAC "agrees") THENL
       [X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "vertex") THEN
        SUBGOAL_THEN `~((x:A) = q (n - 1))`
        (LABEL_TAC "not_new") THENL
         [ASM_MESON_TAC[];
          EXPAND_TAC "p'" THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN `(p':A->real^2) (q (n - 1)) = z (n - 1)`
      (LABEL_TAC "new_point") THENL
       [EXPAND_TAC "p'" THEN REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `IMAGE (p':A->real^2) V = IMAGE p V`
      (LABEL_TAC "old_image") THENL
       [MATCH_MP_TAC IMAGE_EQ THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      EXISTS_TAC `p':A->real^2` THEN REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
          `(q:num->A) (n - 1)`;
          `cyclic_vertices (w:num->A) (k + 2)`;
          `p':A->real^2`; `z:num->real^2`; `n:num`; `k:num`]
         STRAIGHT_LINE_EMBEDDING_INSERT_VERTEX_BEZIER_CHAIN) THEN
        ASM_REWRITE_TAC[];
        X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
        ASM_CASES_TAC `(i:num) = n - 1` THENL
         [ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        SUBGOAL_THEN `(i:num) < n - 1`
        (LABEL_TAC "old_index") THENL
         [ASM_ARITH_TAC;
          ALL_TAC] THEN
        SUBGOAL_THEN `~((q:num->A) i = q (n - 1))`
        (LABEL_TAC "distinct_vertex") THENL
         [DISCH_THEN(LABEL_TAC "same_vertex") THEN
          USE_THEN "injective" MP_TAC THEN
          REWRITE_TAC[INJ; cyclic_indices; IN_ELIM_THM; IN_UNIV] THEN
          DISCH_THEN(MP_TAC o SPECL [`i:num`; `(n:num) - 1`]) THEN
          ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
          ALL_TAC] THEN
        EXPAND_TAC "p'" THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "old_boundary" (MATCH_MP_TAC o SPEC `i:num`) THEN
        USE_THEN "old_index" ACCEPT_TAC;
        REWRITE_TAC[IMAGE_CLAUSES] THEN ASM_REWRITE_TAC[] THEN
        TRANS_TAC EQ_TRANS
         `convex hull
           ((z:num->real^2) (n - 1) INSERT
            cyclic_vertices
             (bezier_refined_cycle z n (bezier_parameter k))
             (n - 1 + k))` THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC CONVEX_HULL_INSERT_EQ THEN
          USE_THEN "hull" ACCEPT_TAC;
          MATCH_MP_TAC CONVEX_HULL_INSERT_BEZIER_REFINED_CYCLE THEN
          USE_THEN "nlarge" ACCEPT_TAC]]];
    MAP_EVERY X_GEN_TAC
     [`V1:A->bool`; `E1:(A->bool)->bool`;
      `V2:A->bool`; `E2:(A->bool)->bool`;
      `q:num->A`; `n:num`; `j:num`] THEN
    INTRO_TAC
     "(graph1 left_vertices induction1) \
      (graph2 right_vertices induction2) \
      jpositive bound injective overlap chord1 chord2" THEN
    SUBGOAL_THEN
     `cyclic_vertices (cyclic_split_left q n j) (j + 2) UNION
      cyclic_vertices (cyclic_split_right q j) (n - j) =
      cyclic_vertices (q:num->A) n`
    (LABEL_TAC "cycle_union") THENL
     [MATCH_MP_TAC CYCLIC_VERTICES_SPLIT_UNION THEN
      USE_THEN "bound" ACCEPT_TAC;
      ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_UNION THEN ASM_REWRITE_TAC[];
      USE_THEN "cycle_union" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[UNION_SUBSET] THEN CONJ_TAC THENL
       [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `V1:A->bool` THEN
        ASM_REWRITE_TAC[] THEN SET_TAC[];
        MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `V2:A->bool` THEN
        ASM_REWRITE_TAC[] THEN SET_TAC[]];
      X_GEN_TAC `z:num->real^2` THEN
      DISCH_THEN(LABEL_TAC "convex") THEN
      SUBGOAL_THEN
       `cyclic_vertices (cyclic_split_left z n j) (j + 2) UNION
        cyclic_vertices (cyclic_split_right z j) (n - j) =
        cyclic_vertices (z:num->real^2) n`
      (LABEL_TAC "geometric_cycle_union") THENL
       [MATCH_MP_TAC CYCLIC_VERTICES_SPLIT_UNION THEN
        USE_THEN "bound" ACCEPT_TAC;
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`;
        `(q:num->A) j`; `(q:num->A) (n - 1)`]
       FINITE_SIMPLE_GRAPH_EDGE_VERTICES) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        INTRO_TAC "qj_vertex1 qlast_vertex1"] THEN
      MP_TAC(ISPECL
       [`V2:A->bool`; `E2:(A->bool)->bool`;
        `(q:num->A) j`; `(q:num->A) (n - 1)`]
       FINITE_SIMPLE_GRAPH_EDGE_VERTICES) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        INTRO_TAC "qj_vertex2 qlast_vertex2"] THEN
      SUBGOAL_THEN
       `strictly_convex_cycle (cyclic_split_left z n j) (j + 2)`
      (LABEL_TAC "left_convex") THENL
       [MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_SPLIT_LEFT THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `strictly_convex_cycle (cyclic_split_right z j) (n - j)`
      (LABEL_TAC "right_convex") THENL
       [MATCH_MP_TAC STRICTLY_CONVEX_CYCLE_SPLIT_RIGHT THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "induction1"
       (MP_TAC o SPEC `cyclic_split_left (z:num->real^2) n j`) THEN
      ANTS_TAC THENL
       [USE_THEN "left_convex" ACCEPT_TAC;
        INTRO_TAC "@p1. embedding1 boundary1 hull1"] THEN
      USE_THEN "induction2"
       (MP_TAC o SPEC `cyclic_split_right (z:num->real^2) j`) THEN
      ANTS_TAC THENL
       [USE_THEN "right_convex" ACCEPT_TAC;
        INTRO_TAC "@p2. embedding2 boundary2 hull2"] THEN
      SUBGOAL_THEN
       `(p1:A->real^2) ((q:num->A) j) = (z:num->real^2) j`
      (LABEL_TAC "p1_qj") THENL
       [USE_THEN "boundary1" (MP_TAC o SPEC `j:num`) THEN
        ANTS_TAC THENL
         [ASM_ARITH_TAC;
          REWRITE_TAC[cyclic_split_left;
                      ARITH_RULE `(j:num) < j + 1`]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(p1:A->real^2) ((q:num->A) (n - 1)) =
        (z:num->real^2) (n - 1)`
      (LABEL_TAC "p1_qlast") THENL
       [USE_THEN "boundary1" (MP_TAC o SPEC `(j:num) + 1`) THEN
        ANTS_TAC THENL
         [ASM_ARITH_TAC;
          REWRITE_TAC[cyclic_split_left; LT_REFL]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(p2:A->real^2) ((q:num->A) j) = (z:num->real^2) j`
      (LABEL_TAC "p2_qj") THENL
       [USE_THEN "boundary2" (MP_TAC o SPEC `0`) THEN
        ANTS_TAC THENL
         [ASM_ARITH_TAC;
          REWRITE_TAC[cyclic_split_right; ADD_CLAUSES]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(j:num) + ((n:num) - j - 1) = (n:num) - 1`
      (LABEL_TAC "last_index") THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(p2:A->real^2) ((q:num->A) (n - 1)) =
        (z:num->real^2) (n - 1)`
      (LABEL_TAC "p2_qlast") THENL
       [USE_THEN "boundary2"
         (MP_TAC o SPEC `(n:num) - (j:num) - 1`) THEN
        ANTS_TAC THENL
         [ASM_ARITH_TAC;
          ASM_REWRITE_TAC[cyclic_split_right]];
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`V1:A->bool`; `V2:A->bool`;
        `p1:A->real^2`; `p2:A->real^2`;
        `(q:num->A) j`; `(q:num->A) (n - 1)`]
       PASTE_FUNCTIONS_ON_TWO_POINT_INTERSECTION) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        INTRO_TAC "@p. agrees1 agrees2"] THEN
      SUBGOAL_THEN `IMAGE (p:A->real^2) V1 = IMAGE (p1:A->real^2) V1`
      (LABEL_TAC "image1") THENL
       [MATCH_MP_TAC IMAGE_EQ THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `IMAGE (p:A->real^2) V2 = IMAGE (p2:A->real^2) V2`
      (LABEL_TAC "image2") THENL
       [MATCH_MP_TAC IMAGE_EQ THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `straight_line_embedding V1 E1 (p:A->real^2)`
      (LABEL_TAC "p_embedding1") THENL
       [MATCH_MP_TAC(ISPECL
         [`V1:A->bool`; `E1:(A->bool)->bool`;
          `p1:A->real^2`; `p:A->real^2`]
         STRAIGHT_LINE_EMBEDDING_EQ_ON_VERTICES) THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "graph1" ACCEPT_TAC;
          USE_THEN "embedding1" ACCEPT_TAC;
          USE_THEN "agrees1" ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `straight_line_embedding V2 E2 (p:A->real^2)`
      (LABEL_TAC "p_embedding2") THENL
       [MATCH_MP_TAC(ISPECL
         [`V2:A->bool`; `E2:(A->bool)->bool`;
          `p2:A->real^2`; `p:A->real^2`]
         STRAIGHT_LINE_EMBEDDING_EQ_ON_VERTICES) THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "graph2" ACCEPT_TAC;
          USE_THEN "embedding2" ACCEPT_TAC;
          USE_THEN "agrees2" ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(p:A->real^2) ((q:num->A) j) = (z:num->real^2) j`
      (LABEL_TAC "p_qj") THENL
       [USE_THEN "agrees1" (MP_TAC o SPEC `(q:num->A) j`) THEN
        ANTS_TAC THENL
         [USE_THEN "qj_vertex1" ACCEPT_TAC;
          DISCH_THEN(LABEL_TAC "p_equals_p1") THEN
          TRANS_TAC EQ_TRANS `(p1:A->real^2) ((q:num->A) j)` THEN
          CONJ_TAC THENL
           [USE_THEN "p_equals_p1" ACCEPT_TAC;
            USE_THEN "p1_qj" ACCEPT_TAC]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(p:A->real^2) ((q:num->A) (n - 1)) =
        (z:num->real^2) (n - 1)`
      (LABEL_TAC "p_qlast") THENL
       [USE_THEN "agrees1"
         (MP_TAC o SPEC `(q:num->A) (n - 1)`) THEN
        ANTS_TAC THENL
         [USE_THEN "qlast_vertex1" ACCEPT_TAC;
          DISCH_THEN(LABEL_TAC "p_equals_p1") THEN
          TRANS_TAC EQ_TRANS `(p1:A->real^2) ((q:num->A) (n - 1))` THEN
          CONJ_TAC THENL
           [USE_THEN "p_equals_p1" ACCEPT_TAC;
            USE_THEN "p1_qlast" ACCEPT_TAC]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `convex hull (IMAGE (p:A->real^2) V1) =
        convex hull
         (cyclic_vertices (cyclic_split_left z n j) (j + 2))`
      (LABEL_TAC "p_hull1") THENL
       [USE_THEN "image1" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "hull1" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `convex hull (IMAGE (p:A->real^2) V2) =
        convex hull
         (cyclic_vertices (cyclic_split_right z j) (n - j))`
      (LABEL_TAC "p_hull2") THENL
       [USE_THEN "image2" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "hull2" ACCEPT_TAC;
        ALL_TAC] THEN
      EXISTS_TAC `p:A->real^2` THEN REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL
          [`V1:A->bool`; `E1:(A->bool)->bool`;
          `V2:A->bool`; `E2:(A->bool)->bool`;
          `p:A->real^2`; `(q:num->A) j`; `(q:num->A) (n - 1)`;
          `z:num->real^2`; `n:num`; `j:num`]
         STRAIGHT_LINE_EMBEDDING_UNION_STRICTLY_CONVEX_CYCLE_SPLIT) THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "graph1" ACCEPT_TAC;
          USE_THEN "graph2" ACCEPT_TAC;
          USE_THEN "p_embedding1" ACCEPT_TAC;
          USE_THEN "p_embedding2" ACCEPT_TAC;
          USE_THEN "chord1" ACCEPT_TAC;
          USE_THEN "chord2" ACCEPT_TAC;
          USE_THEN "convex" ACCEPT_TAC;
          USE_THEN "bound" ACCEPT_TAC;
          USE_THEN "p_qj" ACCEPT_TAC;
          USE_THEN "p_qlast" ACCEPT_TAC;
          USE_THEN "p_hull1" ACCEPT_TAC;
          USE_THEN "p_hull2" ACCEPT_TAC];
        X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
        ASM_CASES_TAC `(i:num) <= j` THENL
         [SUBGOAL_THEN `(i:num) < j + 1`
          (LABEL_TAC "left_index") THENL
           [ASM_ARITH_TAC;
            ALL_TAC] THEN
          SUBGOAL_THEN `(q:num->A) i IN V1`
          (LABEL_TAC "vertex1") THENL
           [USE_THEN "left_vertices"
             (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
            REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
            EXISTS_TAC `i:num` THEN CONJ_TAC THENL
             [ASM_ARITH_TAC;
              ASM_REWRITE_TAC[cyclic_split_left]];
            ALL_TAC] THEN
          USE_THEN "agrees1" (MP_TAC o SPEC `(q:num->A) i`) THEN
          ANTS_TAC THENL
           [USE_THEN "vertex1" ACCEPT_TAC;
            DISCH_THEN(LABEL_TAC "p_equals_p1")] THEN
          USE_THEN "boundary1" (MP_TAC o SPEC `i:num`) THEN
          ANTS_TAC THENL
           [ASM_ARITH_TAC;
            DISCH_THEN(LABEL_TAC "p1_boundary")] THEN
          TRANS_TAC EQ_TRANS `(p1:A->real^2) ((q:num->A) i)` THEN
          CONJ_TAC THENL
           [USE_THEN "p_equals_p1" ACCEPT_TAC;
            USE_THEN "left_index" (fun ith ->
             USE_THEN "p1_boundary"
              (ACCEPT_TAC o REWRITE_RULE[cyclic_split_left; ith]))];
          SUBGOAL_THEN `(j:num) + ((i:num) - j) = i`
          (LABEL_TAC "right_index") THENL
           [UNDISCH_TAC `~((i:num) <= j)` THEN ARITH_TAC;
            ALL_TAC] THEN
          SUBGOAL_THEN `(q:num->A) i IN V2`
          (LABEL_TAC "vertex2") THENL
           [USE_THEN "right_vertices"
             (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
            REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
            EXISTS_TAC `(i:num) - (j:num)` THEN CONJ_TAC THENL
             [ASM_ARITH_TAC;
              ASM_REWRITE_TAC[cyclic_split_right]];
            ALL_TAC] THEN
          USE_THEN "agrees2" (MP_TAC o SPEC `(q:num->A) i`) THEN
          ANTS_TAC THENL
           [USE_THEN "vertex2" ACCEPT_TAC;
            DISCH_THEN(LABEL_TAC "p_equals_p2")] THEN
          USE_THEN "boundary2"
           (MP_TAC o SPEC `(i:num) - (j:num)`) THEN
          ANTS_TAC THENL
           [ASM_ARITH_TAC;
            DISCH_THEN(LABEL_TAC "p2_boundary")] THEN
          TRANS_TAC EQ_TRANS `(p2:A->real^2) ((q:num->A) i)` THEN
          CONJ_TAC THENL
           [USE_THEN "p_equals_p2" ACCEPT_TAC;
            USE_THEN "right_index" (fun ith ->
             USE_THEN "p2_boundary"
              (ACCEPT_TAC o REWRITE_RULE[cyclic_split_right; ith]))]];
        REWRITE_TAC[IMAGE_UNION] THEN
        USE_THEN "image1" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "image2" (fun th -> REWRITE_TAC[th]) THEN
        TRANS_TAC EQ_TRANS
         `convex hull
           (cyclic_vertices
             (cyclic_split_left (z:num->real^2) n j) (j + 2) UNION
            cyclic_vertices
             (cyclic_split_right (z:num->real^2) j) (n - j))` THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC CONVEX_HULL_UNION_EQ THEN
          ASM_REWRITE_TAC[];
          USE_THEN "geometric_cycle_union"
           (fun th -> REWRITE_TAC[th])]]]]);;

let RECURSIVE_TRIANGULATED_DISK_STRAIGHT_LINE_EMBEDDING = prove
 (`!V E q:num->A. !n.
        recursive_triangulated_disk V E q n
        ==> !z:num->real^2.
              strictly_convex_cycle z n
              ==> ?p:A->real^2.
                    straight_line_embedding V E p /\
                    (!i. i < n ==> p (q i) = z i) /\
                    convex hull (IMAGE p V) =
                    convex hull (cyclic_vertices z n)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "recursive") THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`]
   RECURSIVE_TRIANGULATED_DISK_EMBEDDING_STRONG) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "graph vertices conclusion" THEN
  USE_THEN "conclusion" ACCEPT_TAC);;

let STRICTLY_CONVEX_CYCLE_3_EXISTS = prove
 (`?z:num->real^2. strictly_convex_cycle z 3`,
  EXISTS_TAC
   `\i. if i = 0 then vector[&0;&0]:real^2
        else if i = 1 then vector[&1;&0]
        else vector[&0;&1]` THEN
  REWRITE_TAC[strictly_convex_cycle] THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `j:num`; `k:num`] THEN
  DISCH_THEN(LABEL_TAC "indices") THEN
  SUBGOAL_THEN `(i:num) = 0 /\ j = 1 /\ k = 2`
  (CONJUNCTS_THEN2 SUBST1_TAC
    (CONJUNCTS_THEN2 SUBST1_TAC SUBST1_TAC)) THENL
   [ASM_ARITH_TAC;
    CONV_TAC NUM_REDUCE_CONV THEN
    SIMP_TAC[plane_orientation; VECTOR_2] THEN REAL_ARITH_TAC]);;

let RECURSIVE_TRIANGULATED_DISK_3_IMP_STRAIGHT_LINE_PLANAR = prove
 (`!V E q:num->A.
        recursive_triangulated_disk V E q 3
        ==> straight_line_planar_graph V E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "recursive") THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `3`]
   RECURSIVE_TRIANGULATED_DISK_EMBEDDING_STRONG) THEN
  ANTS_TAC THENL
   [USE_THEN "recursive" ACCEPT_TAC;
    INTRO_TAC "graph vertices conclusion"] THEN
  REWRITE_TAC[straight_line_planar_graph] THEN CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    MP_TAC STRICTLY_CONVEX_CYCLE_3_EXISTS THEN
    INTRO_TAC "@z. convex" THEN
    USE_THEN "conclusion" (MP_TAC o SPEC `z:num->real^2`) THEN
    ANTS_TAC THENL
     [USE_THEN "convex" ACCEPT_TAC;
      INTRO_TAC "@p. embedding boundary hull" THEN
      EXISTS_TAC `p:A->real^2` THEN
      USE_THEN "embedding" ACCEPT_TAC]]);;

let FARY_REDUCTION_TO_RECURSIVE_TRIANGULATIONS = prove
 (`!V E.
        planar_graph (V:A->bool) E /\
        (!E'. planar_graph V E' /\
              (!E''. E' PSUBSET E'' /\
                      E'' SUBSET complete_graph_edges V
                      ==> ~planar_graph V E'')
              ==> ?q:num->A.
                    recursive_triangulated_disk V E' q 3)
        ==> straight_line_planar_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "planar recursive_maximal" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "planar" MP_TAC THEN
    REWRITE_TAC[planar_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`]
   MAXIMAL_PLANAR_GRAPH_EXTENSION) THEN
  ANTS_TAC THENL
   [USE_THEN "planar" ACCEPT_TAC;
    INTRO_TAC "@E'. contains extended maximal"] THEN
  USE_THEN "recursive_maximal" (MP_TAC o SPEC `E':(A->bool)->bool`) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "extended" ACCEPT_TAC;
      USE_THEN "maximal" ACCEPT_TAC];
    INTRO_TAC "@q. recursive"] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E':(A->bool)->bool`; `q:num->A`]
   RECURSIVE_TRIANGULATED_DISK_3_IMP_STRAIGHT_LINE_PLANAR) THEN
  ANTS_TAC THENL
   [USE_THEN "recursive" ACCEPT_TAC;
    REWRITE_TAC[straight_line_planar_graph] THEN
    INTRO_TAC "extended_graph @p. extended_embedding"] THEN
  REWRITE_TAC[straight_line_planar_graph] THEN CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    EXISTS_TAC `p:A->real^2` THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E':(A->bool)->bool`;
      `E:(A->bool)->bool`; `p:A->real^2`]
     STRAIGHT_LINE_EMBEDDING_SUBSET_EDGES) THEN
    CONJ_TAC THENL
     [USE_THEN "extended_embedding" ACCEPT_TAC;
      USE_THEN "contains" ACCEPT_TAC]]);;
(* Small graphs, which do not have a triangular outer face.                  *)

let DISTINCT_STANDARD_PLANE_POINTS = prove
 (`~((vec 0:real^2) = vector[&1;&0])`,
  DISCH_THEN(MP_TAC o AP_TERM `\x:real^2. x$1`) THEN
  SIMP_TAC[VECTOR_2; VEC_COMPONENT; DIMINDEX_2] THEN REAL_ARITH_TAC);;

let TWO_STANDARD_PLANE_POINTS_HAS_SIZE = prove
 (`({vec 0:real^2,vector[&1;&0]}:real^2->bool) HAS_SIZE 2`,
  REWRITE_TAC[HAS_SIZE_CONV
   `({vec 0:real^2,vector[&1;&0]}:real^2->bool) HAS_SIZE 2`] THEN
  MAP_EVERY EXISTS_TAC [`vec 0:real^2`; `vector[&1;&0]:real^2`] THEN
  ASM_REWRITE_TAC[DISTINCT_STANDARD_PLANE_POINTS]);;

let FINITE_SIMPLE_GRAPH_CARD_LE_2_EMBEDDING = prove
 (`!V E p.
        finite_simple_graph (V:A->bool) E /\
        CARD V <= 2 /\
        INJ (p:A->real^2) V UNIV
        ==> straight_line_embedding V E p`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph small injective" THEN
  SUBGOAL_THEN `!e:A->bool. e IN E ==> e = (V:A->bool)`
  (LABEL_TAC "only_edge") THENL
   [X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    SUBGOAL_THEN `(e:A->bool) SUBSET V /\ e HAS_SIZE 2`
    (CONJUNCTS_THEN2 (LABEL_TAC "subset") (LABEL_TAC "size")) THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite") THENL
     [USE_THEN "graph" MP_TAC THEN REWRITE_TAC[finite_simple_graph] THEN
      MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `CARD(e:A->bool) <= CARD(V:A->bool)`
    (LABEL_TAC "card_subset") THENL
     [MATCH_MP_TAC CARD_SUBSET THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `CARD(V:A->bool) = 2` (LABEL_TAC "card") THENL
     [USE_THEN "size" MP_TAC THEN REWRITE_TAC[HAS_SIZE] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    MATCH_MP_TAC CARD_SUBSET_EQ THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "size" MP_TAC THEN REWRITE_TAC[HAS_SIZE] THEN MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[straight_line_embedding] THEN REPEAT CONJ_TAC THENL
   [USE_THEN "injective" ACCEPT_TAC;
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    SUBGOAL_THEN `(e:A->bool) = V` SUBST1_TAC THENL
     [USE_THEN "only_edge" MATCH_MP_TAC THEN USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[straight_edge] THEN
    MP_TAC(ISPECL
     [`convex:(real^2->bool)->bool`; `IMAGE (p:A->real^2) V`]
     HULL_SUBSET) THEN SET_TAC[];
    MAP_EVERY X_GEN_TAC [`e:A->bool`; `e':A->bool`] THEN
    INTRO_TAC "edge edge' distinct" THEN
    USE_THEN "only_edge" MP_TAC THEN ASM_MESON_TAC[]]);;

let FINITE_SIMPLE_GRAPH_CARD_LE_2_IMP_STRAIGHT_LINE_PLANAR = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E /\ CARD V <= 2
        ==> straight_line_planar_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph small" THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite") THENL
   [USE_THEN "graph" MP_TAC THEN REWRITE_TAC[finite_simple_graph] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC TWO_STANDARD_PLANE_POINTS_HAS_SIZE THEN REWRITE_TAC[HAS_SIZE] THEN
  INTRO_TAC "target_finite target_card" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `{vec 0:real^2,vector[&1;&0]}:real^2->bool`]
   CARD_LE_INJ) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC "@p. image injective"] THEN
  REWRITE_TAC[straight_line_planar_graph] THEN CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    EXISTS_TAC `p:A->real^2` THEN
    MATCH_MP_TAC FINITE_SIMPLE_GRAPH_CARD_LE_2_EMBEDDING THEN
    ASM_REWRITE_TAC[INJ; IN_UNIV]]);;

let PAIR_SET_SYM = prove
 (`!x y:A. {x,y} = {y,x}`,
  SET_TAC[]);;

let COMPLETE_GRAPH_EDGES_3 = prove
 (`!a b c:A.
        ~(a = b) /\ ~(b = c) /\ ~(c = a)
        ==> complete_graph_edges {a,b,c} = {{a,b},{b,c},{c,a}}`,
  REPEAT GEN_TAC THEN INTRO_TAC "ab bc ca" THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `e:A->bool` THEN EQ_TAC THENL
   [REWRITE_TAC[IN_COMPLETE_GRAPH_EDGES] THEN
    INTRO_TAC "subset size" THEN
    USE_THEN "size" MP_TAC THEN
    REWRITE_TAC[HAS_SIZE_CONV `(e:A->bool) HAS_SIZE 2`] THEN
    INTRO_TAC "@u v. distinct pair" THEN
    SUBGOAL_THEN `(u:A) = a \/ u = b \/ u = c` MP_TAC THENL
     [USE_THEN "subset"
       (MP_TAC o SPEC `u:A` o REWRITE_RULE[SUBSET]) THEN
      ASM_REWRITE_TAC[IN_INSERT; IN_SING];
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
      (SUBGOAL_THEN `(v:A) = a \/ v = b \/ v = c` MP_TAC THENL
        [USE_THEN "subset"
          (MP_TAC o SPEC `v:A` o REWRITE_RULE[SUBSET]) THEN
         ASM_REWRITE_TAC[IN_INSERT; IN_SING];
         DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
         USE_THEN "distinct" MP_TAC THEN
         ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY; PAIR_SET_SYM] THEN
         USE_THEN "distinct" MP_TAC THEN REWRITE_TAC[]])];
    DISCH_THEN(LABEL_TAC "target") THEN
    REWRITE_TAC[IN_COMPLETE_GRAPH_EDGES] THEN CONJ_TAC THENL
     [USE_THEN "target" MP_TAC THEN
      REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST1_TAC) THEN
      REWRITE_TAC[SUBSET; IN_INSERT; IN_SING] THEN
      REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[];
      USE_THEN "target" MP_TAC THEN
      REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST1_TAC) THENL
       [REWRITE_TAC[HAS_SIZE_CONV `({a:A,b}:A->bool) HAS_SIZE 2`] THEN
        MAP_EVERY EXISTS_TAC [`a:A`; `b:A`] THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[HAS_SIZE_CONV `({b:A,c}:A->bool) HAS_SIZE 2`] THEN
        MAP_EVERY EXISTS_TAC [`b:A`; `c:A`] THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[HAS_SIZE_CONV `({c:A,a}:A->bool) HAS_SIZE 2`] THEN
        MAP_EVERY EXISTS_TAC [`c:A`; `a:A`] THEN ASM_REWRITE_TAC[]]]]);;

let INJ_CYCLIC_INDICES_3 = prove
 (`!q:num->A.
        ~(q 0 = q 1) /\ ~(q 1 = q 2) /\ ~(q 2 = q 0)
        ==> INJ q (cyclic_indices 3) (:A)`,
  GEN_TAC THEN
  REWRITE_TAC[INJ; IN_UNIV; CYCLIC_INDICES_3;
              IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[]);;

let MAXIMAL_PLANAR_GRAPH_CARD_3_RECURSIVE = prove
 (`!V E.
        planar_graph (V:A->bool) E /\
        (!E'. E PSUBSET E' /\
               E' SUBSET complete_graph_edges V
               ==> ~planar_graph V E') /\
        CARD V = 3
        ==> ?q:num->A. recursive_triangulated_disk V E q 3`,
  REPEAT GEN_TAC THEN INTRO_TAC "planar maximal card" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "planar"
     (ACCEPT_TAC o CONJUNCT1 o
      REWRITE_RULE[planar_graph]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(V:A->bool) HAS_SIZE 3` MP_TAC THENL
   [REWRITE_TAC[HAS_SIZE] THEN CONJ_TAC THENL
     [USE_THEN "graph"
       (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[finite_simple_graph]);
      USE_THEN "card" ACCEPT_TAC];
    REWRITE_TAC[HAS_SIZE_CONV `(V:A->bool) HAS_SIZE 3`] THEN
    INTRO_TAC "@a b c. bc ab ac vertices"] THEN
  USE_THEN "vertices" SUBST_ALL_TAC THEN
  SUBGOAL_THEN `~((c:A) = a)` (LABEL_TAC "ca") THENL
   [ASM_MESON_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC
   `q:num->A = \i. if i = 0 then a else if i = 1 then b else c` THEN
  SUBGOAL_THEN `(q:num->A) 0 = a /\ q 1 = b /\ q 2 = c`
  (CONJUNCTS_THEN2 (LABEL_TAC "q0")
   (CONJUNCTS_THEN2 (LABEL_TAC "q1") (LABEL_TAC "q2"))) THENL
   [EXPAND_TAC "q" THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (q:num->A) (cyclic_indices 3) (:A)`
  (LABEL_TAC "injective") THENL
   [MATCH_MP_TAC INJ_CYCLIC_INDICES_3 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `complete_graph_edges ({a,b,c}:A->bool) =
    {{a,b},{b,c},{c,a}}`
  (LABEL_TAC "complete") THENL
   [MATCH_MP_TAC COMPLETE_GRAPH_EDGES_3 THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_edges (q:num->A) 3 = {{a,b},{b,c},{c,a}}`
  (LABEL_TAC "cycle_edges") THENL
   [REWRITE_TAC[CYCLIC_EDGES_3] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `E SUBSET cyclic_edges (q:num->A) 3`
  (LABEL_TAC "edge_subset") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `complete_graph_edges ({a,b,c}:A->bool)` THEN
    CONJ_TAC THENL
     [USE_THEN "graph"
       (ACCEPT_TAC o CONJUNCT2 o REWRITE_RULE[FINITE_SIMPLE_GRAPH_EQ]);
      USE_THEN "complete" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "cycle_edges" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[SUBSET_REFL]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `recursive_triangulated_disk
      (cyclic_vertices (q:num->A) 3) (cyclic_edges q 3) q 3`
  (LABEL_TAC "recursive_cycle") THENL
   [MATCH_MP_TAC(CONJUNCT1 recursive_triangulated_disk_RULES) THEN
    USE_THEN "injective" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `planar_graph
      (cyclic_vertices (q:num->A) 3) (cyclic_edges q 3)`
  (LABEL_TAC "cycle_planar") THENL
   [ASM_MESON_TAC[STRAIGHT_LINE_PLANAR_IMP_PLANAR_GRAPH;
                  RECURSIVE_TRIANGULATED_DISK_3_IMP_STRAIGHT_LINE_PLANAR];
    ALL_TAC] THEN
  SUBGOAL_THEN `cyclic_vertices (q:num->A) 3 = {a,b,c}`
  (LABEL_TAC "cycle_vertices") THENL
   [REWRITE_TAC[CYCLIC_VERTICES_3] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `E = cyclic_edges (q:num->A) 3`
  (LABEL_TAC "all_edges") THENL
   [ASM_CASES_TAC `E = cyclic_edges (q:num->A) 3` THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "maximal" (MP_TAC o SPEC `cyclic_edges (q:num->A) 3`) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [REWRITE_TAC[PSUBSET] THEN ASM_REWRITE_TAC[];
        USE_THEN "complete" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "cycle_edges" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[SUBSET_REFL]];
      USE_THEN "cycle_planar" MP_TAC THEN
      USE_THEN "cycle_vertices" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  EXISTS_TAC `q:num->A` THEN
  USE_THEN "recursive_cycle" (fun rth ->
    USE_THEN "cycle_vertices" (fun vth ->
      USE_THEN "all_edges" (fun eth ->
        ACCEPT_TAC(REWRITE_RULE[vth; (GSYM eth)] rth)))));;

let FARY_REDUCTION_TO_LARGE_RECURSIVE_TRIANGULATIONS = prove
 (`!V E.
        planar_graph (V:A->bool) E /\
        (!E'. planar_graph V E' /\
              (!E''. E' PSUBSET E'' /\
                      E'' SUBSET complete_graph_edges V
                      ==> ~planar_graph V E'') /\
              4 <= CARD V
              ==> ?q:num->A.
                    recursive_triangulated_disk V E' q 3)
        ==> straight_line_planar_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "planar recursive_maximal" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "planar" MP_TAC THEN
    REWRITE_TAC[planar_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `CARD(V:A->bool) <= 2` THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_CARD_LE_2_IMP_STRAIGHT_LINE_PLANAR THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC FARY_REDUCTION_TO_RECURSIVE_TRIANGULATIONS THEN
  CONJ_TAC THENL
   [USE_THEN "planar" ACCEPT_TAC;
    X_GEN_TAC `E':(A->bool)->bool` THEN
    INTRO_TAC "extended maximal" THEN
    ASM_CASES_TAC `CARD(V:A->bool) = 3` THENL
     [MATCH_MP_TAC MAXIMAL_PLANAR_GRAPH_CARD_3_RECURSIVE THEN
      ASM_REWRITE_TAC[];
      USE_THEN "recursive_maximal"
       (MP_TAC o SPEC `E':(A->bool)->bool`) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        DISCH_THEN ACCEPT_TAC]]]);;

(* Pure graph bookkeeping for the boundary-vertex deletion case.             *)

let GRAPH_NEIGHBORS_SUBSET_DELETE = prove
 (`!V E v:A.
        finite_simple_graph V E /\ v IN V
        ==> graph_neighbors E v SUBSET V DELETE v`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph vertex" THEN
  REWRITE_TAC[SUBSET; IN_DELETE] THEN X_GEN_TAC `u:A` THEN
  DISCH_THEN(LABEL_TAC "neighbor") THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `u:A`]
   FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
  ASM_REWRITE_TAC[] THEN MESON_TAC[]);;

let FINITE_SIMPLE_GRAPH_EDGE_THROUGH_VERTEX = prove
 (`!V E e v:A.
        finite_simple_graph V E /\ e IN E /\ v IN e
        ==> ?u. e = {v,u} /\ u IN graph_neighbors E v`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge contains" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`]
   FINITE_SIMPLE_GRAPH_EDGE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@a b. a_vertex b_vertex distinct pair" THEN
  ASM_CASES_TAC `(v:A) = a` THENL
   [EXISTS_TAC `b:A` THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
      SUBGOAL_THEN `({v,b}:A->bool) = e` SUBST1_TAC THENL
       [ASM_REWRITE_TAC[];
        USE_THEN "edge" ACCEPT_TAC]];
    SUBGOAL_THEN `(v:A) = b` (LABEL_TAC "v_eq_b") THENL
     [USE_THEN "pair" SUBST_ALL_TAC THEN
      ASM_MESON_TAC[IN_INSERT; IN_SING];
      EXISTS_TAC `a:A` THEN CONJ_TAC THENL
       [ASM_REWRITE_TAC[] THEN SET_TAC[];
        REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
        SUBGOAL_THEN `({v,a}:A->bool) = e` SUBST1_TAC THENL
         [ASM_REWRITE_TAC[] THEN SET_TAC[];
          USE_THEN "edge" ACCEPT_TAC]]]]);;

let FINITE_SIMPLE_GRAPH_DELETE_VERTEX_EDGES_SUBSET = prove
 (`!V E v:A.
        finite_simple_graph V E /\ v IN V
        ==> E SUBSET
            IMAGE (\u:A. {v,u}) (graph_neighbors E v) UNION
            induced_subgraph_edges E (V DELETE v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph vertex" THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `e:A->bool` THEN
  DISCH_THEN(LABEL_TAC "edge") THEN REWRITE_TAC[IN_UNION] THEN
  ASM_CASES_TAC `(v:A) IN e` THENL
   [DISJ1_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`; `v:A`]
     FINITE_SIMPLE_GRAPH_EDGE_THROUGH_VERTEX) THEN
    ASM_REWRITE_TAC[];
    DISJ2_TAC THEN REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    CONJ_TAC THENL
     [USE_THEN "edge" ACCEPT_TAC;
      REWRITE_TAC[SUBSET; IN_DELETE] THEN X_GEN_TAC `u:A` THEN
      DISCH_THEN(LABEL_TAC "u_edge") THEN CONJ_TAC THENL
       [USE_THEN "graph" MP_TAC THEN REWRITE_TAC[finite_simple_graph] THEN
        ASM_MESON_TAC[SUBSET];
        DISCH_THEN(LABEL_TAC "u_eq_v") THEN
        USE_THEN "u_eq_v" SUBST_ALL_TAC THEN ASM_MESON_TAC[]]]]);;

let DELETE_VERTEX_EDGES_SUBSET = prove
 (`!V E v:A.
        IMAGE (\u:A. {v,u}) (graph_neighbors E v) UNION
        induced_subgraph_edges E (V DELETE v) SUBSET E`,
  REPEAT GEN_TAC THEN REWRITE_TAC[SUBSET; IN_UNION] THEN
  X_GEN_TAC `e:A->bool` THEN
  DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "star")
    (LABEL_TAC "old")) THENL
   [USE_THEN "star" MP_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@u. edge_pair neighbor" THEN
    USE_THEN "edge_pair" SUBST1_TAC THEN
    USE_THEN "neighbor" MP_TAC THEN REWRITE_TAC[IN_GRAPH_NEIGHBORS];
    USE_THEN "old" MP_TAC THEN
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[]]);;

let FINITE_SIMPLE_GRAPH_DELETE_VERTEX_EDGES = prove
 (`!V E v:A.
        finite_simple_graph V E /\ v IN V
        ==> E = IMAGE (\u:A. {v,u}) (graph_neighbors E v) UNION
                induced_subgraph_edges E (V DELETE v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph vertex" THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_DELETE_VERTEX_EDGES_SUBSET THEN
    ASM_REWRITE_TAC[];
    MATCH_ACCEPT_TAC DELETE_VERTEX_EDGES_SUBSET]);;

let RECURSIVE_TRIANGULATED_DISK_DELETE_BOUNDARY_VERTEX = prove
 (`!V E q:num->A. !n k w.
        finite_simple_graph V E /\
        q (n - 1) IN V /\
        recursive_triangulated_disk
          (V DELETE (q (n - 1)))
          (induced_subgraph_edges E (V DELETE (q (n - 1))))
          (cyclic_delete_last q w n) (n - 1 + k) /\
        3 <= n /\
        INJ q (cyclic_indices n) (:A) /\
        graph_neighbors E (q (n - 1)) = cyclic_vertices w (k + 2) /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0
        ==> recursive_triangulated_disk V E q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph last_vertex recursive nlarge injective neighbors first last" THEN
  SUBGOAL_THEN
   `q (n - 1) INSERT (V DELETE (q (n - 1))) = (V:A->bool)`
  (LABEL_TAC "vertices") THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (\u:A. {q (n - 1),u}) (cyclic_vertices w (k + 2)) UNION
    induced_subgraph_edges E (V DELETE (q (n - 1))) = E`
  (LABEL_TAC "edges") THENL
   [USE_THEN "neighbors" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC EQ_SYM THEN
    MATCH_MP_TAC FINITE_SIMPLE_GRAPH_DELETE_VERTEX_EDGES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(V:A->bool) DELETE ((q:num->A) (n - 1))`;
    `induced_subgraph_edges (E:(A->bool)->bool)
       ((V:A->bool) DELETE ((q:num->A) (n - 1)))`;
    `q:num->A`; `n:num`; `k:num`; `w:num->A`]
   (CONJUNCT1(CONJUNCT2 recursive_triangulated_disk_RULES))) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[IN_DELETE] THEN
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC GRAPH_NEIGHBORS_SUBSET_DELETE THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;

(* Keep this dependency here and bracket its mixed real/complex priorities.  *)

prioritize_real();;
needs "Multivariate/cauchy.ml";;
prioritize_real();;

let radialized_edge_other_endpoint = new_definition
 `radialized_edge_other_endpoint
    (a:(A->bool)->A) (b:(A->bool)->A) v e =
      if v = a e then b e else a e`;;

let RADIALIZED_EDGE_INCIDENT_PAIR = prove
 (`!a:(A->bool)->A. !b v e.
        e = {a e,b e} /\ ~(a e = b e) /\ v IN e
        ==> e = {v,radialized_edge_other_endpoint a b v e} /\
            ~(radialized_edge_other_endpoint a b v e = v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "pair distinct incident" THEN
  ASM_CASES_TAC
   `(v:A) = (a:(A->bool)->A) (e:A->bool)` THENL
   [CONJ_TAC THENL
     [REMOVE_THEN "pair" (fun th ->
        TRANS_TAC EQ_TRANS `{(a:(A->bool)->A) e,b e}` THEN
        CONJ_TAC THENL
         [MATCH_ACCEPT_TAC th;
          ASM_REWRITE_TAC[radialized_edge_other_endpoint]]);
      REMOVE_THEN "pair" (fun _ -> ALL_TAC) THEN
      ASM_REWRITE_TAC[radialized_edge_other_endpoint; EQ_SYM_EQ]];
    SUBGOAL_THEN
     `(v:A) = (b:(A->bool)->A) (e:A->bool)`
     (LABEL_TAC "v_head") THENL
     [REMOVE_THEN "pair" (fun th ->
        REMOVE_THEN "incident" (fun ith ->
          MP_TAC(ONCE_REWRITE_RULE[th] ith))) THEN
      ASM_REWRITE_TAC[IN_INSERT; IN_SING];
      CONJ_TAC THENL
       [REMOVE_THEN "pair" (fun th ->
          TRANS_TAC EQ_TRANS `{(a:(A->bool)->A) e,b e}` THEN
          CONJ_TAC THENL
           [MATCH_ACCEPT_TAC th;
            ASM_REWRITE_TAC[radialized_edge_other_endpoint; INSERT_AC]]);
        REMOVE_THEN "pair" (fun _ -> ALL_TAC) THEN
        ASM_REWRITE_TAC[radialized_edge_other_endpoint]]]]);;

let GRAPH_NEIGHBORS_AS_INCIDENT_EDGE_IMAGE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !a b v.
        finite_simple_graph V E /\
        (!e. e IN E ==> e = {a e,b e} /\ ~(a e = b e))
        ==> graph_neighbors E v =
            IMAGE (radialized_edge_other_endpoint a b v)
              {e | e IN E /\ v IN e}`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge_data" THEN
  REWRITE_TAC[EXTENSION; IN_GRAPH_NEIGHBORS; IN_IMAGE; IN_ELIM_THM] THEN
  X_GEN_TAC `u:A` THEN EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "edge") THEN
    EXISTS_TAC `{v:A,u}` THEN REWRITE_TAC[] THEN
    SUBGOAL_THEN `~((v:A) = u)` (LABEL_TAC "distinct") THENL
     [SUBGOAL_THEN `(u:A) IN graph_neighbors E v`
      (LABEL_TAC "neighbor") THENL
       [REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
        USE_THEN "edge" ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "graph" (fun gth ->
        USE_THEN "neighbor" (fun nth ->
          ACCEPT_TAC(List.nth
           (CONJUNCTS
           (MATCH_MP
             (ISPECL
              [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `u:A`]
              FINITE_SIMPLE_GRAPH_NEIGHBOR)
             (CONJ gth nth))) 2)));
      ALL_TAC] THEN
    USE_THEN "edge_data" (fun th ->
      MP_TAC(MATCH_MP (SPEC `{v:A,u}` th)
       (ASSUME `({v:A,u}:A->bool) IN E`))) THEN
    INTRO_TAC "pair endpoints_distinct" THEN
    SUBGOAL_THEN `(v:A) IN {v,u}` (LABEL_TAC "incident") THENL
     [REWRITE_TAC[IN_INSERT];
      ALL_TAC] THEN
    USE_THEN "pair" (fun pth ->
      USE_THEN "endpoints_distinct" (fun dth ->
        USE_THEN "incident" (fun ith ->
          MP_TAC(MATCH_MP
           (ISPECL
            [`a:(A->bool)->A`; `b:(A->bool)->A`;
             `v:A`; `{v:A,u}`]
            RADIALIZED_EDGE_INCIDENT_PAIR)
           (CONJ pth (CONJ dth ith)))))) THEN
    INTRO_TAC "incident_pair other_distinct" THEN
    REMOVE_THEN "pair" (fun _ -> ALL_TAC) THEN
    REMOVE_THEN "incident_pair" (fun th ->
      MP_TAC(AP_TERM `\s:A->bool. u IN s` th)) THEN
    ASM_REWRITE_TAC[IN_INSERT; IN_SING; EQ_SYM_EQ];
    INTRO_TAC "@e. other edge incident" THEN
    USE_THEN "edge_data" (fun th ->
      MP_TAC(MATCH_MP (SPEC `e:A->bool` th)
       (ASSUME `(e:A->bool) IN E`))) THEN
    INTRO_TAC "pair distinct" THEN
    USE_THEN "pair" (fun pth ->
      USE_THEN "distinct" (fun dth ->
        USE_THEN "incident" (fun ith ->
          MP_TAC(MATCH_MP
           (ISPECL
            [`a:(A->bool)->A`; `b:(A->bool)->A`;
             `v:A`; `e:A->bool`]
            RADIALIZED_EDGE_INCIDENT_PAIR)
           (CONJ pth (CONJ dth ith)))))) THEN
    INTRO_TAC "incident_pair other_distinct" THEN
    USE_THEN "other" SUBST1_TAC THEN
    USE_THEN "incident_pair" (SUBST1_TAC o SYM) THEN
    USE_THEN "edge" ACCEPT_TAC]);;

let CONNECTED_SUBSET_OF_COMPONENT = prove
 (`!s k t:real^N->bool.
        k IN components s /\
        connected t /\
        t SUBSET s /\
        ~(t INTER k = {})
        ==> t SUBSET k`,
  REPEAT GEN_TAC THEN INTRO_TAC "component connected subset meets" THEN
  USE_THEN "component" MP_TAC THEN REWRITE_TAC[IN_COMPONENTS] THEN
  INTRO_TAC "@z. z_in component_eq" THEN
  SUBGOAL_THEN `?x:real^N. x IN t /\ x IN k`
  (X_CHOOSE_THEN `x:real^N`
   (CONJUNCTS_THEN2 (LABEL_TAC "x_in_t") (LABEL_TAC "x_in_k"))) THENL
   [USE_THEN "meets" MP_TAC THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `t SUBSET connected_component (s:real^N->bool) x`
  (LABEL_TAC "t_component") THENL
   [MATCH_MP_TAC(ISPECL
     [`s:real^N->bool`; `t:real^N->bool`; `x:real^N`]
     CONNECTED_COMPONENT_MAXIMAL) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_component (s:real^N->bool) x = k`
  (LABEL_TAC "same_component") THENL
   [USE_THEN "component_eq" SUBST1_TAC THEN
    MATCH_MP_TAC(ISPECL
     [`s:real^N->bool`; `z:real^N`; `x:real^N`]
     CONNECTED_COMPONENT_EQ) THEN
    USE_THEN "x_in_k" MP_TAC THEN
    USE_THEN "component_eq" (fun th -> REWRITE_TAC[th]);
    USE_THEN "same_component" (fun th ->
      USE_THEN "t_component" (ACCEPT_TAC o REWRITE_RULE[th]))]);;

let COMPONENT_FRONTIER_OF_CONNECTED_APPROACH = prove
 (`!s k t:real^N->bool. !x.
        k IN components ((:real^N) DIFF s) /\
        connected t /\
        t SUBSET ((:real^N) DIFF s) /\
        ~(t INTER k = {}) /\
        x IN s /\
        x IN closure t
        ==> x IN frontier k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "component connected subset meets x_in x_limit" THEN
  SUBGOAL_THEN `(t:real^N->bool) SUBSET k`
  (LABEL_TAC "t_in_component") THENL
   [MATCH_MP_TAC(ISPECL
     [`(:real^N) DIFF s`; `k:real^N->bool`; `t:real^N->bool`]
     CONNECTED_SUBSET_OF_COMPONENT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:real^N) IN closure k`
  (LABEL_TAC "x_closure") THENL
   [SUBGOAL_THEN
     `closure(t:real^N->bool) SUBSET closure k`
    (LABEL_TAC "closure_subset") THENL
     [MATCH_MP_TAC CLOSURE_MINIMAL THEN CONJ_TAC THENL
       [MATCH_MP_TAC SUBSET_TRANS THEN
        EXISTS_TAC `k:real^N->bool` THEN
        ASM_REWRITE_TAC[CLOSURE_SUBSET];
        REWRITE_TAC[CLOSED_CLOSURE]];
      USE_THEN "closure_subset"
       (MP_TAC o SPEC `x:real^N` o REWRITE_RULE[SUBSET]) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[frontier; IN_DIFF] THEN CONJ_TAC THENL
   [USE_THEN "x_closure" ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "x_interior") THEN
    SUBGOAL_THEN `(x:real^N) IN k` (LABEL_TAC "x_in_component") THENL
     [MP_TAC(ISPEC `k:real^N->bool` INTERIOR_SUBSET) THEN
      REWRITE_TAC[SUBSET] THEN
      DISCH_THEN(MP_TAC o SPEC `x:real^N`) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(k:real^N->bool) SUBSET (:real^N) DIFF s`
    (LABEL_TAC "component_subset") THENL
     [MATCH_MP_TAC IN_COMPONENTS_SUBSET THEN
      USE_THEN "component" ACCEPT_TAC;
      USE_THEN "component_subset"
       (MP_TAC o SPEC `x:real^N` o REWRITE_RULE[SUBSET]) THEN
      ASM_REWRITE_TAC[IN_DIFF; IN_UNIV]]]);;

let IN_UNIT_HORIZONTAL_SEGMENT = prove
 (`!x:real^2.
        x IN segment[vec 0,basis 1] <=>
        x$2 = &0 /\ &0 <= x$1 /\ x$1 <= &1`,
  GEN_TAC THEN REWRITE_TAC[IN_SEGMENT] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `u:real` STRIP_ASSUME_TAC) THEN
    ASM_REWRITE_TAC[] THEN
    SIMP_TAC[VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT; VEC_COMPONENT;
             BASIS_COMPONENT; DIMINDEX_2; ARITH] THEN
    ASM_REWRITE_TAC[REAL_MUL_RZERO; REAL_MUL_RID; REAL_ADD_LID;
                    REAL_ADD_RID];
    INTRO_TAC "x2 lower upper" THEN
    EXISTS_TAC `(x:real^2)$1` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[CART_EQ; FORALL_2; DIMINDEX_2] THEN
    ASM_SIMP_TAC[VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT; VEC_COMPONENT;
                 BASIS_COMPONENT; DIMINDEX_2; ARITH] THEN
    ASM_REWRITE_TAC[REAL_MUL_RZERO; REAL_MUL_RID; REAL_ADD_LID;
                    REAL_ADD_RID]]);;

let IN_OPEN_UNIT_HORIZONTAL_SEGMENT = prove
 (`!x:real^2.
        x IN segment(vec 0,basis 1) <=>
        x$2 = &0 /\ &0 < x$1 /\ x$1 < &1`,
  GEN_TAC THEN REWRITE_TAC[IN_SEGMENT] THEN
  SIMP_TAC[BASIS_NONZERO; DIMINDEX_GE_1; LE_REFL] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `u:real` STRIP_ASSUME_TAC) THEN
    ASM_REWRITE_TAC[] THEN
    SIMP_TAC[VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT; VEC_COMPONENT;
             BASIS_COMPONENT; DIMINDEX_2; ARITH] THEN
    ASM_REWRITE_TAC[REAL_MUL_RZERO; REAL_MUL_RID; REAL_ADD_LID;
                    REAL_ADD_RID];
    INTRO_TAC "x2 lower upper" THEN
    EXISTS_TAC `(x:real^2)$1` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[CART_EQ; FORALL_2; DIMINDEX_2] THEN
    ASM_SIMP_TAC[VECTOR_ADD_COMPONENT; VECTOR_MUL_COMPONENT; VEC_COMPONENT;
                 BASIS_COMPONENT; DIMINDEX_2; ARITH] THEN
    ASM_REWRITE_TAC[REAL_MUL_RZERO; REAL_MUL_RID; REAL_ADD_LID;
                    REAL_ADD_RID]]);;

let LOCAL_HALF_BALL_COMPONENT_FRONTIER = prove
 (`!s:real^N->bool. !k z a b e.
        k IN components ((:real^N) DIFF s) /\
        &0 < e /\
        ~(a = vec 0) /\
        ball(z,e) INTER {x | a dot x > b} SUBSET (:real^N) DIFF s /\
        ~(k INTER ball(z,e) INTER {x | a dot x > b} = {}) /\
        (!w. w IN ball(z,e) /\ a dot w = b ==> w IN s)
        ==> !w. w IN ball(z,e) /\ a dot w = b ==> w IN frontier k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "component e_positive normal halfball_subset meets flat_in" THEN
  X_GEN_TAC `w:real^N` THEN INTRO_TAC "w_ball w_flat" THEN
  MATCH_MP_TAC(ISPECL
   [`s:real^N->bool`; `k:real^N->bool`;
    `ball(z:real^N,e) INTER {x:real^N | a dot x > b}`;
    `w:real^N`]
   COMPONENT_FRONTIER_OF_CONNECTED_APPROACH) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "component" ACCEPT_TAC;
    MATCH_MP_TAC CONVEX_CONNECTED THEN
    MATCH_MP_TAC CONVEX_INTER THEN
    REWRITE_TAC[CONVEX_BALL; CONVEX_HALFSPACE_GT];
    USE_THEN "halfball_subset" ACCEPT_TAC;
    USE_THEN "meets" MP_TAC THEN SET_TAC[];
    USE_THEN "flat_in" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN
     `~(ball(z:real^N,e) INTER {x:real^N | a dot x > b} = {})`
    (LABEL_TAC "halfball_nonempty") THENL
     [USE_THEN "meets" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`ball(z:real^N,e)`; `{x:real^N | a dot x > b}`]
     CLOSURE_INTER_CONVEX_OPEN) THEN
    REWRITE_TAC[CONVEX_BALL; OPEN_BALL; CONVEX_HALFSPACE_GT;
                OPEN_HALFSPACE_GT] THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    ASM_SIMP_TAC[CLOSURE_BALL; CLOSURE_HALFSPACE_GT; IN_INTER;
                 IN_CBALL; IN_ELIM_THM] THEN
    USE_THEN "w_ball" MP_TAC THEN
    REWRITE_TAC[IN_BALL] THEN REAL_ARITH_TAC]);;

let UNIT_HORIZONTAL_SEGMENT_FRONTIER_LOCALLY = prove
 (`!r:real^2->bool. !k z.
        closed r /\
        r INTER segment[vec 0,basis 1] SUBSET {vec 0,basis 1} /\
        k IN components
          ((:real^2) DIFF (segment[vec 0,basis 1] UNION r)) /\
        z IN segment(vec 0,basis 1) /\
        z IN frontier k
        ==> ?e. &0 < e /\
                ball(z,e) INTER segment(vec 0,basis 1) SUBSET frontier k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "closed edge_inter component z_segment z_frontier" THEN
  SUBGOAL_THEN
   `(z:real^2)$2 = &0 /\ &0 < z$1 /\ z$1 < &1`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "z_segment" MP_TAC THEN
    REWRITE_TAC[IN_OPEN_UNIT_HORIZONTAL_SEGMENT];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((z:real^2) IN r)` (LABEL_TAC "z_not_r") THENL
   [MP_TAC(ISPECL [`vec 0:real^2`; `basis 1:real^2`]
      SEGMENT_OPEN_SUBSET_CLOSED) THEN
    MP_TAC(ISPECL [`vec 0:real^2`; `basis 1:real^2`]
      ENDS_NOT_IN_SEGMENT) THEN
    USE_THEN "edge_inter" MP_TAC THEN
    USE_THEN "z_segment" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `open((:real^2) DIFF r)` (LABEL_TAC "open_away") THENL
   [REWRITE_TAC[OPEN_CLOSED; COMPL_COMPL] THEN
    USE_THEN "closed" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "open_away" (MP_TAC o REWRITE_RULE[OPEN_CONTAINS_BALL]) THEN
  DISCH_THEN(MP_TAC o SPEC `z:real^2`) THEN
  ASM_REWRITE_TAC[IN_DIFF; IN_UNIV] THEN
  INTRO_TAC "@d. d_positive ball_away" THEN
  ABBREV_TAC
   `e = min d (min ((z:real^2)$1) (&1 - z$1))` THEN
  SUBGOAL_THEN `&0 < e` (LABEL_TAC "e_positive") THENL
   [EXPAND_TAC "e" THEN REWRITE_TAC[REAL_LT_MIN] THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `e <= d /\ e <= (z:real^2)$1 /\ e <= &1 - z$1`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "e" THEN REWRITE_TAC[real_min] THEN
    REPEAT COND_CASES_TAC THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:real^2. w IN ball(z,e) ==> &0 < w$1 /\ w$1 < &1`
  (LABEL_TAC "inside_strip") THENL
   [X_GEN_TAC `w:real^2` THEN REWRITE_TAC[IN_BALL; dist] THEN
    DISCH_THEN(LABEL_TAC "near") THEN
    MP_TAC(ISPECL [`z - w:real^2`; `1`] COMPONENT_LE_NORM) THEN
    REWRITE_TAC[VECTOR_SUB_COMPONENT; REAL_ABS_BOUNDS] THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `ball(z:real^2,e) SUBSET (:real^2) DIFF r`
  (LABEL_TAC "small_ball_away") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `ball(z:real^2,d)` THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[SUBSET; IN_BALL] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "z_frontier" (MP_TAC o REWRITE_RULE[FRONTIER_STRADDLE]) THEN
  DISCH_THEN(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2
   (X_CHOOSE_THEN `y:real^2`
    (CONJUNCTS_THEN2 (LABEL_TAC "y_in_k") (LABEL_TAC "y_near")))
   (K ALL_TAC)) THEN
  SUBGOAL_THEN `(y:real^2) IN ball(z,e)` (LABEL_TAC "y_ball") THENL
   [REWRITE_TAC[IN_BALL] THEN
    USE_THEN "y_near" MP_TAC THEN REWRITE_TAC[DIST_SYM];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(y:real^2) IN (:real^2) DIFF
     (segment[vec 0,basis 1] UNION r)`
  (LABEL_TAC "y_complement") THENL
   [USE_THEN "component" (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
    REWRITE_TAC[SUBSET] THEN
    DISCH_THEN MATCH_MP_TAC THEN USE_THEN "y_in_k" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((y:real^2) IN segment[vec 0,basis 1])`
  (LABEL_TAC "y_not_segment") THENL
   [USE_THEN "y_complement" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `&0 < (y:real^2)$1 /\ y$1 < &1`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "inside_strip" MATCH_MP_TAC THEN
    USE_THEN "y_ball" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((y:real^2)$2 = &0)` (LABEL_TAC "y_off_axis") THENL
   [DISCH_THEN(LABEL_TAC "y_on_axis") THEN
    USE_THEN "y_not_segment" MP_TAC THEN
    REWRITE_TAC[IN_UNIT_HORIZONTAL_SEGMENT] THEN
    ASM_REWRITE_TAC[] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:real^2. w IN ball(z,e) /\ w$2 = &0 ==> w IN frontier k`
  (LABEL_TAC "axis_frontier") THENL
   [SUBGOAL_THEN `&0 < (y:real^2)$2 \/ y$2 < &0`
    DISJ_CASES_TAC THENL
     [USE_THEN "y_off_axis" MP_TAC THEN REAL_ARITH_TAC;
      MP_TAC(ISPECL
       [`segment[vec 0:real^2,basis 1] UNION r`;
        `k:real^2->bool`; `z:real^2`; `basis 2:real^2`; `&0`; `e:real`]
       LOCAL_HALF_BALL_COMPONENT_FRONTIER) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [USE_THEN "component" ACCEPT_TAC;
          USE_THEN "e_positive" ACCEPT_TAC;
          SIMP_TAC[BASIS_NONZERO; DIMINDEX_2; ARITH];
          REWRITE_TAC[SUBSET; IN_INTER; IN_ELIM_THM; IN_DIFF; IN_UNIV;
                      IN_UNION; DE_MORGAN_THM] THEN
          SIMP_TAC[DOT_BASIS; DIMINDEX_2; ARITH] THEN
          X_GEN_TAC `w:real^2` THEN INTRO_TAC "w_ball w_above" THEN
          CONJ_TAC THENL
           [REWRITE_TAC[IN_UNIT_HORIZONTAL_SEGMENT] THEN
            ASM_REAL_ARITH_TAC;
            USE_THEN "small_ball_away"
             (MP_TAC o REWRITE_RULE[SUBSET]) THEN
            DISCH_THEN(MP_TAC o SPEC `w:real^2`) THEN
            ASM_REWRITE_TAC[IN_DIFF; IN_UNIV]];
          REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER; IN_ELIM_THM] THEN
          EXISTS_TAC `y:real^2` THEN ASM_REWRITE_TAC[] THEN
          ASM_SIMP_TAC[DOT_BASIS; DIMINDEX_2; ARITH] THEN
          ASM_REWRITE_TAC[real_gt];
          X_GEN_TAC `w:real^2` THEN
          SIMP_TAC[DOT_BASIS; DIMINDEX_2; ARITH] THEN
          INTRO_TAC "w_ball w_axis" THEN
          REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
          REWRITE_TAC[IN_UNIT_HORIZONTAL_SEGMENT] THEN
          SUBGOAL_THEN `&0 < (w:real^2)$1 /\ w$1 < &1`
          STRIP_ASSUME_TAC THENL
           [USE_THEN "inside_strip" MATCH_MP_TAC THEN
            USE_THEN "w_ball" ACCEPT_TAC;
            ASM_REAL_ARITH_TAC]];
        SIMP_TAC[DOT_BASIS; DIMINDEX_2; ARITH]];
      MP_TAC(ISPECL
       [`segment[vec 0:real^2,basis 1] UNION r`;
        `k:real^2->bool`; `z:real^2`; `--(basis 2:real^2)`;
        `&0`; `e:real`]
       LOCAL_HALF_BALL_COMPONENT_FRONTIER) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [USE_THEN "component" ACCEPT_TAC;
          USE_THEN "e_positive" ACCEPT_TAC;
          SIMP_TAC[VECTOR_NEG_EQ_0; BASIS_NONZERO; DIMINDEX_2; ARITH];
          REWRITE_TAC[SUBSET; IN_INTER; IN_ELIM_THM; IN_DIFF; IN_UNIV;
                      IN_UNION; DE_MORGAN_THM; DOT_LNEG] THEN
          SIMP_TAC[DOT_BASIS; DIMINDEX_2; ARITH] THEN
          X_GEN_TAC `w:real^2` THEN INTRO_TAC "w_ball w_below" THEN
          CONJ_TAC THENL
           [REWRITE_TAC[IN_UNIT_HORIZONTAL_SEGMENT] THEN
            ASM_REAL_ARITH_TAC;
            USE_THEN "small_ball_away"
             (MP_TAC o REWRITE_RULE[SUBSET]) THEN
            DISCH_THEN(MP_TAC o SPEC `w:real^2`) THEN
            ASM_REWRITE_TAC[IN_DIFF; IN_UNIV]];
          REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER; IN_ELIM_THM] THEN
          EXISTS_TAC `y:real^2` THEN ASM_REWRITE_TAC[DOT_LNEG] THEN
          SIMP_TAC[DOT_BASIS; DIMINDEX_2; ARITH] THEN ASM_REAL_ARITH_TAC;
          X_GEN_TAC `w:real^2` THEN
          SIMP_TAC[DOT_LNEG; DOT_BASIS; DIMINDEX_2; ARITH] THEN
          INTRO_TAC "w_ball w_axis" THEN
          REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
          REWRITE_TAC[IN_UNIT_HORIZONTAL_SEGMENT] THEN
          SUBGOAL_THEN `&0 < (w:real^2)$1 /\ w$1 < &1`
          STRIP_ASSUME_TAC THENL
           [USE_THEN "inside_strip" MATCH_MP_TAC THEN
            USE_THEN "w_ball" ACCEPT_TAC;
            ASM_REAL_ARITH_TAC]];
        SIMP_TAC[DOT_LNEG; DOT_BASIS; DIMINDEX_2; ARITH;
                 REAL_NEG_EQ_0]]];
    ALL_TAC] THEN
  EXISTS_TAC `e:real` THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[SUBSET; IN_INTER] THEN
  X_GEN_TAC `w:real^2` THEN INTRO_TAC "w_ball w_segment" THEN
  USE_THEN "axis_frontier" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "w_segment" MP_TAC THEN
  REWRITE_TAC[IN_OPEN_UNIT_HORIZONTAL_SEGMENT] THEN MESON_TAC[]);;

let UNIT_HORIZONTAL_SEGMENT_FRONTIER = prove
 (`!r:real^2->bool. !k x.
        closed r /\
        r INTER segment[vec 0,basis 1] SUBSET {vec 0,basis 1} /\
        k IN components
          ((:real^2) DIFF (segment[vec 0,basis 1] UNION r)) /\
        x IN segment(vec 0,basis 1) /\
        x IN frontier k
        ==> segment[vec 0,basis 1] SUBSET frontier k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "closed edge_inter component x_segment x_frontier" THEN
  SUBGOAL_THEN
   `open_in (subtopology euclidean
      (segment(vec 0:real^2,basis 1)))
      (segment(vec 0:real^2,basis 1) INTER frontier k)`
  (LABEL_TAC "relatively_open") THENL
   [REWRITE_TAC[OPEN_IN_CONTAINS_BALL] THEN CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_INTER] THEN MESON_TAC[];
      X_GEN_TAC `y:real^2` THEN REWRITE_TAC[IN_INTER] THEN
      INTRO_TAC "y_segment y_frontier" THEN
      MP_TAC(ISPECL [`r:real^2->bool`; `k:real^2->bool`; `y:real^2`]
        UNIT_HORIZONTAL_SEGMENT_FRONTIER_LOCALLY) THEN
      ASM_REWRITE_TAC[] THEN
      INTRO_TAC "@d. d_positive local_frontier" THEN
      EXISTS_TAC `d:real` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "local_frontier" MP_TAC THEN SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `closed_in (subtopology euclidean
      (segment(vec 0:real^2,basis 1)))
      (segment(vec 0:real^2,basis 1) INTER frontier k)`
  (LABEL_TAC "relatively_closed") THENL
   [MATCH_MP_TAC CLOSED_IN_CLOSED_INTER THEN
    MATCH_ACCEPT_TAC FRONTIER_CLOSED;
    ALL_TAC] THEN
  SUBGOAL_THEN `connected(segment(vec 0:real^2,basis 1))`
  (LABEL_TAC "connected_segment") THENL
   [MATCH_MP_TAC CONVEX_CONNECTED THEN REWRITE_TAC[CONVEX_SEGMENT];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `segment(vec 0:real^2,basis 1) INTER frontier k =
    segment(vec 0,basis 1)`
  (LABEL_TAC "open_segment_frontier") THENL
   [USE_THEN "connected_segment"
      (MP_TAC o REWRITE_RULE[CONNECTED_CLOPEN]) THEN
    DISCH_THEN(MP_TAC o SPEC
      `segment(vec 0:real^2,basis 1) INTER frontier k`) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
     [USE_THEN "x_segment" MP_TAC THEN
      USE_THEN "x_frontier" MP_TAC THEN ASM SET_TAC[];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `segment(vec 0:real^2,basis 1) SUBSET frontier k`
  (LABEL_TAC "open_segment_subset") THENL
   [USE_THEN "open_segment_frontier" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`segment(vec 0:real^2,basis 1)`; `frontier(k:real^2->bool)`]
   CLOSURE_MINIMAL) THEN
  ASM_REWRITE_TAC[FRONTIER_CLOSED] THEN
  SIMP_TAC[CLOSURE_SEGMENT; BASIS_NONZERO; DIMINDEX_GE_1; LE_REFL]);;

let ARC_COMPONENT_FRONTIER_PROPAGATION = prove
 (`!g:real^1->real^2. !r k x.
        arc g /\
        closed r /\
        path_image g INTER r SUBSET {pathstart g,pathfinish g} /\
        k IN components ((:real^2) DIFF (path_image g UNION r)) /\
        x IN path_image g DIFF {pathstart g,pathfinish g} /\
        x IN frontier k
        ==> path_image g SUBSET frontier k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "arc closed edge_inter component x_interior x_frontier" THEN
  SUBGOAL_THEN `arc(linepath(vec 0:real^2,basis 1))`
  (LABEL_TAC "line_arc") THENL
   [SIMP_TAC[ARC_LINEPATH_EQ; BASIS_NONZERO; DIMINDEX_GE_1; LE_REFL];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`g:real^1->real^2`; `linepath(vec 0:real^2,basis 1)`]
   HOMEOMORPHISM_ARC_IMAGES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@f f'. image_homeomorphism f_start f_finish f'_start f'_finish" THEN
  MP_TAC(ISPECL
   [`g:real^1->real^2`; `linepath(vec 0:real^2,basis 1)`;
    `f:real^2->real^2`; `f':real^2->real^2`]
   JORDAN_SCHOENFLIES) THEN
  ANTS_TAC THENL
   [ASM_MESON_TAC[ARC_IMP_SIMPLE_PATH];
    ALL_TAC] THEN
  INTRO_TAC
   "@q q'. global_homeomorphism q_agrees q'_agrees image_arc _ _" THEN
  SUBGOAL_THEN
   `IMAGE (q:real^2->real^2) (path_image g) =
    segment[vec 0,basis 1]`
  (LABEL_TAC "image_segment") THENL
   [USE_THEN "image_arc" MP_TAC THEN REWRITE_TAC[PATH_IMAGE_LINEPATH];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:real^2->real^2) (pathstart g) = vec 0`
  (LABEL_TAC "q_start") THENL
   [USE_THEN "q_agrees"
     (MP_TAC o SPEC `pathstart(g:real^1->real^2)`) THEN
    REWRITE_TAC[PATHSTART_IN_PATH_IMAGE] THEN
    DISCH_THEN SUBST1_TAC THEN
    USE_THEN "f_start" MP_TAC THEN REWRITE_TAC[PATHSTART_LINEPATH];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:real^2->real^2) (pathfinish g) = basis 1`
  (LABEL_TAC "q_finish") THENL
   [USE_THEN "q_agrees"
     (MP_TAC o SPEC `pathfinish(g:real^1->real^2)`) THEN
    REWRITE_TAC[PATHFINISH_IN_PATH_IMAGE] THEN
    DISCH_THEN SUBST1_TAC THEN
    USE_THEN "f_finish" MP_TAC THEN REWRITE_TAC[PATHFINISH_LINEPATH];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u v:real^2. (q:real^2->real^2) u = q v ==> u = v`
  (LABEL_TAC "q_injective") THENL
   [MAP_EVERY X_GEN_TAC [`u:real^2`; `v:real^2`] THEN
    DISCH_THEN(MP_TAC o AP_TERM `(q':real^2->real^2)`) THEN
    USE_THEN "global_homeomorphism" (fun th ->
      REWRITE_TAC[REWRITE_RULE[IN_UNIV]
       (CONJUNCT1(REWRITE_RULE[homeomorphism] th))]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (q:real^2->real^2) (:real^2) = (:real^2)`
  (LABEL_TAC "q_surjective") THENL
   [USE_THEN "global_homeomorphism"
     (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o
      REWRITE_RULE[homeomorphism]);
    ALL_TAC] THEN
  SUBGOAL_THEN `closed(IMAGE (q:real^2->real^2) r)`
  (LABEL_TAC "image_closed") THENL
   [MP_TAC(ISPECL
     [`q:real^2->real^2`; `q':real^2->real^2`;
      `(:real^2)`; `(:real^2)`; `r:real^2->bool`]
     HOMEOMORPHISM_IMP_CLOSED_MAP) THEN
    ASM_REWRITE_TAC[SUBTOPOLOGY_UNIV; GSYM CLOSED_IN];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (q:real^2->real^2) r INTER segment[vec 0,basis 1] =
    IMAGE q (r INTER path_image g)`
  (LABEL_TAC "image_intersection") THENL
   [USE_THEN "image_segment" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC IMAGE_INTER_INJ THEN
    USE_THEN "q_injective" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (q:real^2->real^2) r INTER segment[vec 0,basis 1]
    SUBSET {vec 0,basis 1}`
  (LABEL_TAC "edge_image_inter") THENL
   [USE_THEN "image_intersection" SUBST1_TAC THEN
    TRANS_TAC SUBSET_TRANS
     `IMAGE (q:real^2->real^2) {pathstart g,pathfinish g}` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC IMAGE_SUBSET THEN
      USE_THEN "edge_inter" MP_TAC THEN SET_TAC[];
      ASM_REWRITE_TAC[IMAGE_CLAUSES; SUBSET_REFL]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (q:real^2->real^2)
      ((:real^2) DIFF (path_image g UNION r)) =
    (:real^2) DIFF
      (segment[vec 0,basis 1] UNION IMAGE q r)`
  (LABEL_TAC "image_complement") THENL
   [TRANS_TAC EQ_TRANS
     `IMAGE (q:real^2->real^2) (:real^2) DIFF
      IMAGE q (path_image g UNION r)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC IMAGE_DIFF_INJ THEN
      MAP_EVERY X_GEN_TAC [`u:real^2`; `v:real^2`] THEN
      INTRO_TAC "u_univ v_union image_equal" THEN
      USE_THEN "q_injective" MATCH_MP_TAC THEN
      USE_THEN "image_equal" ACCEPT_TAC;
      ASM_REWRITE_TAC[IMAGE_UNION; PATH_IMAGE_LINEPATH]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `homeomorphism
      (((:real^2) DIFF (path_image g UNION r)),
       ((:real^2) DIFF
        (segment[vec 0,basis 1] UNION IMAGE q r)))
      ((q:real^2->real^2),q')`
  (LABEL_TAC "complement_homeomorphism") THENL
   [MATCH_MP_TAC HOMEOMORPHISM_OF_SUBSETS THEN
    MAP_EVERY EXISTS_TAC [`(:real^2)`; `(:real^2)`] THEN
    ASM_REWRITE_TAC[SUBSET_UNIV];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (q:real^2->real^2) k IN
    components ((:real^2) DIFF
      (segment[vec 0,basis 1] UNION IMAGE q r))`
  (LABEL_TAC "image_component") THENL
   [USE_THEN "complement_homeomorphism"
     (MP_TAC o MATCH_MP HOMEOMORPHISM_COMPONENTS) THEN
    DISCH_THEN SUBST1_TAC THEN MATCH_MP_TAC FUN_IN_IMAGE THEN
    USE_THEN "component" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (q:real^2->real^2) (frontier k) =
    frontier (IMAGE q k)`
  (LABEL_TAC "image_frontier") THENL
   [MP_TAC(ISPECL
     [`q:real^2->real^2`; `q':real^2->real^2`;
      `(:real^2)`; `(:real^2)`; `k:real^2->bool`]
     HOMEOMORPHISM_FRONTIER_OF) THEN
    ASM_REWRITE_TAC[SUBSET_UNIV; SUBTOPOLOGY_UNIV;
                    EUCLIDEAN_FRONTIER_OF];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:real^2->real^2) x IN segment[vec 0,basis 1]`
  (LABEL_TAC "qx_closed_segment") THENL
   [USE_THEN "image_segment" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC FUN_IN_IMAGE THEN
    USE_THEN "x_interior" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((q:real^2->real^2) x IN {vec 0,basis 1})`
  (LABEL_TAC "qx_not_endpoints") THENL
   [REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY; DE_MORGAN_THM] THEN
    CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "qx_start") THEN
      USE_THEN "q_injective"
       (MP_TAC o SPECL [`x:real^2`; `pathstart(g:real^1->real^2)`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        USE_THEN "x_interior" MP_TAC THEN SET_TAC[]];
      DISCH_THEN(LABEL_TAC "qx_finish") THEN
      USE_THEN "q_injective"
       (MP_TAC o SPECL [`x:real^2`; `pathfinish(g:real^1->real^2)`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        USE_THEN "x_interior" MP_TAC THEN SET_TAC[]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:real^2->real^2) x IN segment(vec 0,basis 1)`
  (LABEL_TAC "qx_open_segment") THENL
   [USE_THEN "qx_closed_segment" MP_TAC THEN
    REWRITE_TAC[SEGMENT_CLOSED_OPEN; IN_UNION] THEN
    USE_THEN "qx_not_endpoints" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:real^2->real^2) x IN frontier (IMAGE q k)`
  (LABEL_TAC "qx_frontier") THENL
   [USE_THEN "image_frontier" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC FUN_IN_IMAGE THEN USE_THEN "x_frontier" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `segment[vec 0,basis 1] SUBSET
    frontier (IMAGE (q:real^2->real^2) k)`
