   `open((:real^2) DIFF plane_graph_carrier (V:A->bool) E p c)`
  (LABEL_TAC "carrier_complement_open") THENL
   [MATCH_MP_TAC OPEN_DIFF THEN
    ASM_REWRITE_TAC[OPEN_UNIV];
    ALL_TAC] THEN
  SUBGOAL_THEN `open(k:real^2->bool)` (LABEL_TAC "k_open") THENL
   [MATCH_MP_TAC(ISPECL
     [`(:real^2) DIFF plane_graph_carrier (V:A->bool) E p c`;
