     OPEN_COMPONENTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(k:real^2->bool) SUBSET
    (:real^2) DIFF plane_graph_carrier (V:A->bool) E p c`
  (LABEL_TAC "k_subset") THENL
