    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `frontier k SUBSET (c:(A->bool)->real^2->bool) e`
  (LABEL_TAC "frontier_edge") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`; `k:real^2->bool`]
     PLANE_GRAPH_EMBEDDING_FACE_FRONTIER_SUBSET_EDGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(subtopology euclidean m) frontier_of (k:real^2->bool) = {}`
  (LABEL_TAC "relative_frontier_empty") THENL
   [MP_TAC(ISPECL
     [`euclidean:(real^2)topology`;
      `m:real^2->bool`; `k:real^2->bool`]
     FRONTIER_OF_SUBSET_SUBTOPOLOGY) THEN
    MP_TAC(ISPECL
     [`euclidean:(real^2)topology`;
      `k:real^2->bool`; `m:real^2->bool`]
     FRONTIER_OF_SUBTOPOLOGY_SUBSET) THEN
    REWRITE_TAC[EUCLIDEAN_FRONTIER_OF] THEN
    USE_THEN "frontier_edge" MP_TAC THEN
