let MAXIMAL_PLANAR_GRAPH_EDGES_NONEMPTY = prove
 (`!V E p c.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        (!G. E PSUBSET G /\
             G SUBSET complete_graph_edges V
             ==> ~planar_graph V G) /\
        2 <= CARD V
        ==> ~(E = {})`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding maximal vertices" THEN
  DISCH_THEN(LABEL_TAC "edges_empty") THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "vertices_finite") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?u v:A. u IN V /\ v IN V /\ ~(u = v)`
  (X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `v:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
      (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
        (LABEL_TAC "distinct"))))) THENL
   [ASM_CASES_TAC `?u v:A. u IN V /\ v IN V /\ ~(u = v)` THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `?a:A. V SUBSET {a}` MP_TAC THENL
     [USE_THEN "vertices_finite" MP_TAC THEN
      USE_THEN "vertices" MP_TAC THEN
      ASM SET_TAC[];
      REWRITE_TAC[GSYM CARD_LE_1] THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(IMAGE (p:A->real^2) V)`
  (LABEL_TAC "image_finite") THENL
   [MATCH_MP_TAC FINITE_IMAGE THEN
    USE_THEN "vertices_finite" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `interior(IMAGE (p:A->real^2) V) = {}`
  (LABEL_TAC "image_empty_interior") THENL
   [MATCH_MP_TAC EMPTY_INTERIOR_FINITE THEN
    USE_THEN "image_finite" ACCEPT_TAC;
    ALL_TAC] THEN
  ABBREV_TAC
   `s = (:real^2) DIFF plane_graph_carrier
      (V:A->bool) (E:(A->bool)->bool) (p:A->real^2)
      (c:(A->bool)->real^2->bool)` THEN
  SUBGOAL_THEN `connected(s:real^2->bool)` (LABEL_TAC "connected") THENL
   [EXPAND_TAC "s" THEN
    USE_THEN "edges_empty" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[plane_graph_carrier; IMAGE_CLAUSES; UNIONS_0;
                UNION_EMPTY] THEN
    MATCH_MP_TAC(ISPECL
     [`(:real^2):real^2->bool`; `IMAGE (p:A->real^2) V`]
     CONNECTED_OPEN_DIFF_COUNTABLE) THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[DIMINDEX_2] THEN ARITH_TAC;
      REWRITE_TAC[OPEN_UNIV];
      REWRITE_TAC[CONNECTED_UNIV];
      MATCH_MP_TAC FINITE_IMP_COUNTABLE THEN
      USE_THEN "image_finite" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((s:real^2->bool) = {})` (LABEL_TAC "nonempty") THENL
   [EXPAND_TAC "s" THEN
    USE_THEN "edges_empty" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[plane_graph_carrier; IMAGE_CLAUSES; UNIONS_0;
                UNION_EMPTY] THEN
    DISCH_THEN(LABEL_TAC "complement_empty") THEN
    SUBGOAL_THEN `IMAGE (p:A->real^2) V = (:real^2)`
    (LABEL_TAC "image_univ") THENL
     [USE_THEN "complement_empty" MP_TAC THEN SET_TAC[];
      USE_THEN "image_univ" SUBST_ALL_TAC THEN
      USE_THEN "image_empty_interior" MP_TAC THEN
      REWRITE_TAC[INTERIOR_UNIV; UNIV_NOT_EMPTY]];
    ALL_TAC] THEN
  SUBGOAL_THEN `components(s:real^2->bool) = {s}`
  (LABEL_TAC "single_component") THENL
   [REWRITE_TAC[COMPONENTS_EQ_SING] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `u:A`]
   PLANE_GRAPH_EMBEDDING_VERTEX_INCIDENT_COMPONENT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@ku. ku_component u_frontier" THEN
  SUBGOAL_THEN `(ku:real^2->bool) = s` (LABEL_TAC "ku_eq") THENL
   [USE_THEN "ku_component" MP_TAC THEN
    USE_THEN "single_component" (fun th -> REWRITE_TAC[th; IN_SING]);
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `v:A`]
   PLANE_GRAPH_EMBEDDING_VERTEX_INCIDENT_COMPONENT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@kv. kv_component v_frontier" THEN
  SUBGOAL_THEN `(kv:real^2->bool) = s` (LABEL_TAC "kv_eq") THENL
   [USE_THEN "kv_component" MP_TAC THEN
    USE_THEN "single_component" (fun th -> REWRITE_TAC[th; IN_SING]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(s:real^2->bool) IN components
     ((:real^2) DIFF plane_graph_carrier (V:A->bool) E p c)`
  (LABEL_TAC "face_component") THENL
   [ASM_REWRITE_TAC[IN_SING];
