   [USE_THEN "ku_eq" (fun th ->
      USE_THEN "u_frontier" (fun uth ->
        ACCEPT_TAC(REWRITE_RULE[th] uth)));
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:A->real^2) v IN frontier s`
  (LABEL_TAC "v_on_face") THENL
   [USE_THEN "kv_eq" (fun th ->
      USE_THEN "v_frontier" (fun vth ->
        ACCEPT_TAC(REWRITE_RULE[th] vth)));
    ALL_TAC] THEN
  SUBGOAL_THEN `({u,v}:A->bool) IN E` (LABEL_TAC "edge") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `s:real^2->bool`; `u:A`; `v:A`]
     MAXIMAL_PLANAR_GRAPH_COFACIAL_ADJACENT) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      USE_THEN "embedding" ACCEPT_TAC;
      USE_THEN "maximal" ACCEPT_TAC;
      USE_THEN "u_vertex" ACCEPT_TAC;
      USE_THEN "v_vertex" ACCEPT_TAC;
      USE_THEN "distinct" ACCEPT_TAC;
      USE_THEN "face_component" ACCEPT_TAC;
      USE_THEN "u_on_face" ACCEPT_TAC;
      USE_THEN "v_on_face" ACCEPT_TAC];
    USE_THEN "edge" MP_TAC THEN
    USE_THEN "edges_empty" (fun th -> REWRITE_TAC[th; NOT_IN_EMPTY])]);;

let PLANE_GRAPH_EMBEDDING_FACE_CONTAINS_EDGE_INTERIOR = prove
 (`!V E p c k.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        ~(E = {}) /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c)
