    USE_THEN "endpoints" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC NONEMPTY_SIMPLE_PATH_ENDLESS THEN
    ASM_SIMP_TAC[ARC_IMP_SIMPLE_PATH];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `closed(plane_graph_carrier (V:A->bool) E p c)`
  (LABEL_TAC "carrier_closed") THENL
   [MATCH_MP_TAC PLANE_GRAPH_CARRIER_CLOSED THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `open((:real^2) DIFF plane_graph_carrier (V:A->bool) E p c)`
  (LABEL_TAC "carrier_complement_open") THENL
   [MATCH_MP_TAC OPEN_DIFF THEN ASM_REWRITE_TAC[OPEN_UNIV];
