let PLANE_GRAPH_EMBEDDING_FACE_VERTICES_CARD_GE_2 = prove
 (`!V E p c k.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        ~(E = {}) /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c)
        ==> 2 <= CARD(plane_graph_face_vertices V E p c k)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding edges_nonempty component" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `k:real^2->bool`]
   PLANE_GRAPH_EMBEDDING_FACE_CONTAINS_EDGE_INTERIOR) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@d x. d_edge x_interior x_frontier" THEN
  SUBGOAL_THEN
   `IMAGE (p:A->real^2) d SUBSET (c:(A->bool)->real^2->bool) d`
  (LABEL_TAC "d_endpoints") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `d:A->bool`]
     PLANE_GRAPH_EMBEDDING_EDGE_ENDPOINTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) d SUBSET frontier k`
  (LABEL_TAC "d_frontier") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `d:A->bool`;
      `k:real^2->bool`; `x:real^2`]
     PLANE_GRAPH_EMBEDDING_EDGE_COMPONENT_FRONTIER) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(d:A->bool) SUBSET plane_graph_face_vertices V E p c k`
  (LABEL_TAC "d_subset") THENL
   [REWRITE_TAC[SUBSET; plane_graph_face_vertices; IN_ELIM_THM] THEN
    X_GEN_TAC `v:A` THEN DISCH_THEN(LABEL_TAC "v_edge") THEN
    CONJ_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN
      INTRO_TAC "_ _ edge_data" THEN
      USE_THEN "edge_data" (fun th ->
        USE_THEN "d_edge" (fun eth ->
          MP_TAC(MATCH_MP (SPEC `d:A->bool` th) eth))) THEN
      INTRO_TAC "d_vertex _" THEN
      USE_THEN "d_vertex"
       (MATCH_MP_TAC o SPEC `v:A` o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "v_edge" ACCEPT_TAC;
      USE_THEN "d_frontier"
       (MATCH_MP_TAC o SPEC `(p:A->real^2) v` o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "d_endpoints"
       (MATCH_MP_TAC o SPEC `(p:A->real^2) v` o REWRITE_RULE[SUBSET]) THEN
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `v:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  TRANS_TAC LE_TRANS `CARD(d:A->bool)` THEN CONJ_TAC THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    INTRO_TAC "_ _ edge_data" THEN
    USE_THEN "edge_data" (fun th ->
      USE_THEN "d_edge" (fun eth ->
        MP_TAC(MATCH_MP (SPEC `d:A->bool` th) eth))) THEN
    REWRITE_TAC[HAS_SIZE] THEN
    INTRO_TAC "_ _ d_card" THEN ASM_ARITH_TAC;
    MATCH_MP_TAC CARD_SUBSET THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC FINITE_PLANE_GRAPH_FACE_VERTICES THEN
    USE_THEN "graph" ACCEPT_TAC]);;

let MAXIMAL_PLANAR_GRAPH_FACE_VERTICES_CARD_EQ_3 = prove
 (`!V E p c k.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        (!G. E PSUBSET G /\
             G SUBSET complete_graph_edges V
             ==> ~planar_graph V G) /\
        3 <= CARD V /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        2 <= CARD(plane_graph_face_vertices V E p c k)
        ==> CARD(plane_graph_face_vertices V E p c k) = 3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding maximal vertices component lower" THEN
  SUBGOAL_THEN
   `FINITE(plane_graph_face_vertices
      (V:A->bool) E (p:A->real^2) c k)`
  (LABEL_TAC "face_finite") THENL
   [MATCH_MP_TAC FINITE_PLANE_GRAPH_FACE_VERTICES THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(plane_graph_face_vertices
      (V:A->bool) E (p:A->real^2) c k) <= 3`
  (LABEL_TAC "upper") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `k:real^2->bool`]
     MAXIMAL_PLANAR_GRAPH_FACE_VERTICES_CARD_LE_3) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC
   `CARD(plane_graph_face_vertices
      (V:A->bool) E (p:A->real^2) c k) = 3` THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `CARD(plane_graph_face_vertices
      (V:A->bool) E (p:A->real^2) c k) = 2`
  (LABEL_TAC "face_card") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_face_vertices (V:A->bool) E (p:A->real^2) c k
    HAS_SIZE 2`
  MP_TAC THENL
   [REWRITE_TAC[HAS_SIZE] THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[HAS_SIZE_CONV
     `plane_graph_face_vertices
       (V:A->bool) E (p:A->real^2) c k HAS_SIZE 2`] THEN
    INTRO_TAC "@u v. distinct face_eq"] THEN
  SUBGOAL_THEN `({u:A,v}:A->bool) IN E` (LABEL_TAC "edge") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `k:real^2->bool`]
     MAXIMAL_PLANAR_GRAPH_FACE_VERTICES_CLIQUE) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MATCH_MP_TAC o SPECL [`u:A`; `v:A`]) THEN
    USE_THEN "face_eq" (fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[IN_INSERT];
    ALL_TAC] THEN
  SUBGOAL_THEN `(V:A->bool) SUBSET {u,v}` (LABEL_TAC "vertex_subset") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `{u:A,v}`; `k:real^2->bool`]
     PLANE_GRAPH_EMBEDDING_FACE_VERTICES_SUBSET_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "face_eq" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[SUBSET_REFL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(V:A->bool) <=
    CARD(plane_graph_face_vertices V E (p:A->real^2) c k)`
  (LABEL_TAC "card_le") THENL
   [MATCH_MP_TAC CARD_SUBSET THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "face_eq" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "vertex_subset" ACCEPT_TAC;
    ASM_ARITH_TAC]);;

let MAXIMAL_PLANAR_GRAPH_EVERY_FACE_TRIANGULAR = prove
 (`!V E p c k.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        (!G. E PSUBSET G /\
             G SUBSET complete_graph_edges V
             ==> ~planar_graph V G) /\
        3 <= CARD V /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c)
        ==> CARD(plane_graph_face_vertices V E p c k) = 3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding maximal vertices component" THEN
  SUBGOAL_THEN `~((E:(A->bool)->bool) = {})`
  (LABEL_TAC "edges_nonempty") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`]
     MAXIMAL_PLANAR_GRAPH_EDGES_NONEMPTY) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `k:real^2->bool`]
   MAXIMAL_PLANAR_GRAPH_FACE_VERTICES_CARD_EQ_3) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `k:real^2->bool`]
   PLANE_GRAPH_EMBEDDING_FACE_VERTICES_CARD_GE_2) THEN
  ASM_REWRITE_TAC[]);;

let MAXIMAL_PLANAR_GRAPH_EVERY_FACE_TRIANGULAR_CYCLE = prove
 (`!V E p c k.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        (!G. E PSUBSET G /\
             G SUBSET complete_graph_edges V
             ==> ~planar_graph V G) /\
        3 <= CARD V /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c)
        ==> ?q:num->A.
              plane_graph_face_vertices V E p c k =
                cyclic_vertices q 3 /\
              simple_graph_cycle E q 3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding maximal vertices component" THEN
  SUBGOAL_THEN
   `CARD(plane_graph_face_vertices
      (V:A->bool) E (p:A->real^2) c k) = 3`
  (LABEL_TAC "face_card") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `k:real^2->bool`]
     MAXIMAL_PLANAR_GRAPH_EVERY_FACE_TRIANGULAR) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(plane_graph_face_vertices
      (V:A->bool) E (p:A->real^2) c k)`
  (LABEL_TAC "face_finite") THENL
   [MATCH_MP_TAC FINITE_PLANE_GRAPH_FACE_VERTICES THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_face_vertices (V:A->bool) E (p:A->real^2) c k
    HAS_SIZE 3`
  MP_TAC THENL
   [REWRITE_TAC[HAS_SIZE] THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[HAS_SIZE_CONV
     `plane_graph_face_vertices
       (V:A->bool) E (p:A->real^2) c k HAS_SIZE 3`] THEN
    INTRO_TAC "@a b d. bd ab ad face_eq"] THEN
  ABBREV_TAC
   `q:num->A = \i. if i = 0 then a else if i = 1 then b else d` THEN
  SUBGOAL_THEN `(q:num->A) 0 = a /\ q 1 = b /\ q 2 = d`
  (CONJUNCTS_THEN2 (LABEL_TAC "q0")
   (CONJUNCTS_THEN2 (LABEL_TAC "q1") (LABEL_TAC "q2"))) THENL
   [EXPAND_TAC "q" THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (q:num->A) (cyclic_indices 3) (:A)`
  (LABEL_TAC "injective") THENL
   [REWRITE_TAC[INJ; CYCLIC_INDICES_3;
                IN_INSERT; NOT_IN_EMPTY; IN_UNIV] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_face_vertices (V:A->bool) E (p:A->real^2) c k =
    cyclic_vertices (q:num->A) 3`
  (LABEL_TAC "face_cycle") THENL
   [REWRITE_TAC[CYCLIC_VERTICES_3] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `k:real^2->bool`]
   MAXIMAL_PLANAR_GRAPH_FACE_VERTICES_CLIQUE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "clique") THEN
  SUBGOAL_THEN `cyclic_edges (q:num->A) 3 SUBSET E`
  (LABEL_TAC "cycle_edges") THENL
   [REWRITE_TAC[CYCLIC_EDGES_3; INSERT_SUBSET; SING_SUBSET] THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
    USE_THEN "clique" MATCH_MP_TAC THEN
    USE_THEN "face_cycle" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[CYCLIC_VERTICES_3] THEN ASM_REWRITE_TAC[IN_INSERT];
    ALL_TAC] THEN
  EXISTS_TAC `q:num->A` THEN CONJ_TAC THENL
   [USE_THEN "face_eq" (fun eth ->
      USE_THEN "face_cycle" (fun cth ->
        ACCEPT_TAC(TRANS (SYM eth) cth)));
    REWRITE_TAC[simple_graph_cycle] THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC]);;

let INCIDENT_EDGES_EQUAL_OF_OTHER_ENDPOINT = prove
 (`!E:(A->bool)->bool. !a b v e1 e2.
        (!d. d IN E ==> d = {a d,b d} /\ ~(a d = b d)) /\
        e1 IN E /\ v IN e1 /\ e2 IN E /\ v IN e2 /\
        radialized_edge_other_endpoint a b v e1 =
        radialized_edge_other_endpoint a b v e2
        ==> e1 = e2`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "edge_data edge1 incident1 edge2 incident2 same_other" THEN
  USE_THEN "edge_data" (MP_TAC o SPEC `e1:A->bool`) THEN
  ANTS_TAC THENL
   [USE_THEN "edge1" ACCEPT_TAC;
    INTRO_TAC "pair1 distinct1"] THEN
  USE_THEN "edge_data" (MP_TAC o SPEC `e2:A->bool`) THEN
  ANTS_TAC THENL
   [USE_THEN "edge2" ACCEPT_TAC;
    INTRO_TAC "pair2 distinct2"] THEN
  SUBGOAL_THEN
   `e1 = {v,radialized_edge_other_endpoint a b v e1}:A->bool`
  (LABEL_TAC "pair1_at_v") THENL
   [USE_THEN "pair1" (fun pth ->
      USE_THEN "distinct1" (fun dth ->
       USE_THEN "incident1" (fun ith ->
        MP_TAC(MATCH_MP
         (ISPECL
          [`a:(A->bool)->A`; `b:(A->bool)->A`; `v:A`; `e1:A->bool`]
          RADIALIZED_EDGE_INCIDENT_PAIR)
         (CONJ pth (CONJ dth ith)))))) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `e2 = {v,radialized_edge_other_endpoint a b v e2}:A->bool`
  (LABEL_TAC "pair2_at_v") THENL
   [USE_THEN "pair2" (fun pth ->
      USE_THEN "distinct2" (fun dth ->
       USE_THEN "incident2" (fun ith ->
        MP_TAC(MATCH_MP
         (ISPECL
          [`a:(A->bool)->A`; `b:(A->bool)->A`; `v:A`; `e2:A->bool`]
          RADIALIZED_EDGE_INCIDENT_PAIR)
         (CONJ pth (CONJ dth ith)))))) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  TRANS_TAC EQ_TRANS
   `{v,radialized_edge_other_endpoint a b v e1}:A->bool` THEN
  CONJ_TAC THENL
   [USE_THEN "pair1_at_v" ACCEPT_TAC;
    TRANS_TAC EQ_TRANS
     `{v,radialized_edge_other_endpoint a b v e2}:A->bool` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(SET_RULE `(x:A) = y ==> {v,x} = {v,y}`) THEN
      USE_THEN "same_other" ACCEPT_TAC;
      USE_THEN "pair2_at_v" (ACCEPT_TAC o SYM)]]);;

let CYCLIC_VERTICES_OFFSET = prove
 (`!q:num->A. !n k.
        cyclic_vertices (\i. q((i + k) MOD n)) n =
        cyclic_vertices q n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cyclic_vertices] THEN
  TRANS_TAC EQ_TRANS
   `IMAGE (q:num->A)
      (IMAGE
        (\i. if i < n then (i + k) MOD n else i)
        (cyclic_indices n))` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[GSYM IMAGE_o; o_THM] THEN
    MATCH_MP_TAC IMAGE_EQ THEN
    SIMP_TAC[o_THM; IN_CYCLIC_INDICES];
    SUBGOAL_THEN
     `IMAGE
       (\i. if i < n then (i + k) MOD n else i)
       (cyclic_indices n) =
      cyclic_indices n`
    SUBST1_TAC THENL
     [MATCH_MP_TAC PERMUTES_IMAGE THEN
      REWRITE_TAC[cyclic_indices; PERMUTES_CYCLIC_N];
      REFL_TAC]]);;

let MOD_ADD_LEFT_REDUCE = prove
 (`!a b n. (a MOD n + b) MOD n = (a + b) MOD n`,
  CONV_TAC MOD_DOWN_CONV THEN REWRITE_TAC[]);;

let CYCLIC_OFFSET_SUCCESSOR = prove
 (`!n k i.
        (((i + 1) MOD n + k) MOD n) =
        ((((i + k) MOD n) + 1) MOD n)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[MOD_ADD_LEFT_REDUCE; ADD_AC]);;

let CYCLIC_EDGES_OFFSET = prove
 (`!q:num->A. !n k.
        cyclic_edges (\i. q((i + k) MOD n)) n =
        cyclic_edges q n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cyclic_edges] THEN
  TRANS_TAC EQ_TRANS
   `IMAGE (\i. {(q:num->A) i,q((i + 1) MOD n)})
      (IMAGE
        (\i. if i < n then (i + k) MOD n else i)
        (cyclic_indices n))` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[GSYM IMAGE_o; o_THM] THEN
    MATCH_MP_TAC IMAGE_EQ THEN
    REWRITE_TAC[o_THM; IN_CYCLIC_INDICES] THEN
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[CYCLIC_OFFSET_SUCCESSOR];
    SUBGOAL_THEN
     `IMAGE
       (\i. if i < n then (i + k) MOD n else i)
       (cyclic_indices n) =
      cyclic_indices n`
    SUBST1_TAC THENL
     [MATCH_MP_TAC PERMUTES_IMAGE THEN
      REWRITE_TAC[cyclic_indices; PERMUTES_CYCLIC_N];
      REFL_TAC]]);;

let INJ_CYCLIC_OFFSET = prove
 (`!q:num->A. !n k.
        INJ q (cyclic_indices n) (:A)
        ==> INJ (\i. q((i + k) MOD n)) (cyclic_indices n) (:A)`,
  REPEAT GEN_TAC THEN
  SIMP_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
  DISCH_THEN(LABEL_TAC "injective") THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
  INTRO_TAC "i_index j_index same" THEN
  SUBGOAL_THEN
   `(i + k) MOD n < n /\ (j + k) MOD n < n`
  (CONJUNCTS_THEN2 (LABEL_TAC "i_offset")
    (LABEL_TAC "j_offset")) THENL
   [CONJ_TAC THEN REWRITE_TAC[MOD_LT_EQ_LT] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((i + k) MOD n) = ((j + k) MOD n)`
  (LABEL_TAC "same_index") THENL
   [USE_THEN "injective"
     (MATCH_MP_TAC o SPECL [`(i + k) MOD n`; `(j + k) MOD n`]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP PERMUTES_INJECTIVE
   (SPECL [`n:num`; `k:num`] PERMUTES_CYCLIC_N)) THEN
  DISCH_THEN(MP_TAC o SPECL [`i:num`; `j:num`]) THEN
  ASM_REWRITE_TAC[]);;

let SIMPLE_GRAPH_CYCLE_OFFSET = prove
 (`!E:(A->bool)->bool. !q:num->A. !n k.
        simple_graph_cycle E q n
        ==> simple_graph_cycle E (\i. q((i + k) MOD n)) n`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective edges" THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "large" ACCEPT_TAC;
    MATCH_MP_TAC INJ_CYCLIC_OFFSET THEN
    USE_THEN "injective" ACCEPT_TAC;
    REWRITE_TAC[CYCLIC_EDGES_OFFSET] THEN
    USE_THEN "edges" ACCEPT_TAC]);;

let CYCLIC_EDGES_SUBSET_OF_CHAIN_AND_LAST = prove
 (`!E:(A->bool)->bool. !w:num->A. !n.
        2 <= n /\
        (!i. i + 1 < n ==> {w i,w(i + 1)} IN E) /\
        {w(n - 1),w 0} IN E
        ==> cyclic_edges w n SUBSET E`,
  REPEAT GEN_TAC THEN INTRO_TAC "large chain last" THEN
  REWRITE_TAC[SUBSET; IN_CYCLIC_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN
  INTRO_TAC "@i. index edge_eq" THEN
  USE_THEN "edge_eq" SUBST1_TAC THEN
  ASM_CASES_TAC `(i:num) + 1 < n` THENL
   [SUBGOAL_THEN `(i + 1) MOD n = i + 1`
    (LABEL_TAC "successor") THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[];
      USE_THEN "successor" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "chain" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
    SUBGOAL_THEN `(i:num) = n - 1` (LABEL_TAC "last_index") THENL
     [USE_THEN "index" MP_TAC THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(i + 1) MOD n = 0` (LABEL_TAC "successor") THENL
     [USE_THEN "last_index" SUBST1_TAC THEN
      SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[MOD_REFL]];
      ASM_REWRITE_TAC[]]]);;
(* Plane triangulated disks with one distinguished outer face.               *)

let plane_triangulated_disk = new_definition
 `plane_triangulated_disk
      (V:A->bool) (E:(A->bool)->bool)
      (p:A->real^2) (c:(A->bool)->real^2->bool)
      (q:num->A) n (outer:real^2->bool) <=>
        finite_simple_graph V E /\
        plane_graph_embedding V E p c /\
        3 <= n /\
        simple_graph_cycle E q n /\
        outer IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        plane_graph_face_vertices V E p c outer =
          cyclic_vertices q n /\
        (!k. k IN components
               ((:real^2) DIFF plane_graph_carrier V E p c) /\
             ~(k = outer)
             ==> ?r:num->A.
                   plane_graph_face_vertices V E p c k =
                     cyclic_vertices r 3 /\
                   simple_graph_cycle E r 3)`;;

let PLANE_TRIANGULATED_DISK_BOUNDARY_SUBSET = prove
 (`!V E p c q n outer.
        plane_triangulated_disk
          (V:A->bool) E p c q n outer
        ==> cyclic_vertices q n SUBSET V`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC "_ _ _ _ _ boundary _" THEN
  USE_THEN "boundary" (fun th -> REWRITE_TAC[GSYM th]) THEN
  MATCH_ACCEPT_TAC PLANE_GRAPH_FACE_VERTICES_SUBSET);;

let PLANE_TRIANGULATED_DISK_OUTER_FRONTIER_SUBSET_INDUCED_CARRIER =
 prove
 (`!V E p c q n outer.
        plane_triangulated_disk
          (V:A->bool) E p c q n outer
        ==> frontier outer SUBSET
            plane_graph_carrier
              (cyclic_vertices q n)
              (induced_subgraph_edges E (cyclic_vertices q n))
              p c`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC "graph embedding _ _ component boundary _" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `outer:real^2->bool`]
   PLANE_GRAPH_EMBEDDING_FACE_FRONTIER_SUBSET_INDUCED_CARRIER) THEN
  ASM_REWRITE_TAC[]);;

let MAXIMAL_PLANAR_GRAPH_PLANE_TRIANGULATED_DISK = prove
 (`!V E p c outer.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        (!G. E PSUBSET G /\
             G SUBSET complete_graph_edges V
             ==> ~planar_graph V G) /\
        3 <= CARD V /\
        outer IN components
          ((:real^2) DIFF plane_graph_carrier V E p c)
        ==> ?q:num->A.
              plane_triangulated_disk V E p c q 3 outer`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding maximal vertices component" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `outer:real^2->bool`]
   MAXIMAL_PLANAR_GRAPH_EVERY_FACE_TRIANGULAR_CYCLE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@q. boundary boundary_cycle" THEN
  EXISTS_TAC `q:num->A` THEN
  REWRITE_TAC[plane_triangulated_disk] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    USE_THEN "embedding" ACCEPT_TAC;
    ARITH_TAC;
    USE_THEN "boundary_cycle" ACCEPT_TAC;
    USE_THEN "component" ACCEPT_TAC;
    USE_THEN "boundary" ACCEPT_TAC;
    X_GEN_TAC `k:real^2->bool` THEN
    INTRO_TAC "k_component _" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `k:real^2->bool`]
     MAXIMAL_PLANAR_GRAPH_EVERY_FACE_TRIANGULAR_CYCLE) THEN
    ASM_REWRITE_TAC[]]);;
(* Induction from topological triangulated disks to the recursive grammar.   *)

let PLANE_TRIANGULATED_DISK_INVARIANTS = prove
 (`!V E p c q n outer.
        plane_triangulated_disk
          (V:A->bool) E p c q n outer
        ==> finite_simple_graph V E /\
            plane_graph_embedding V E p c /\
            3 <= n /\
            INJ q (cyclic_indices n) (:A) /\
            cyclic_edges q n SUBSET E /\
            cyclic_vertices q n SUBSET V /\
            outer IN components
              ((:real^2) DIFF plane_graph_carrier V E p c) /\
            plane_graph_face_vertices V E p c outer =
              cyclic_vertices q n`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_triangulated_disk; simple_graph_cycle] THEN
  INTRO_TAC
   "graph embedding large (_ injective boundary_edges) component \
    boundary _" THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    USE_THEN "embedding" ACCEPT_TAC;
    USE_THEN "large" ACCEPT_TAC;
    USE_THEN "injective" ACCEPT_TAC;
    USE_THEN "boundary_edges" ACCEPT_TAC;
    USE_THEN "boundary" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_ACCEPT_TAC PLANE_GRAPH_FACE_VERTICES_SUBSET;
    USE_THEN "component" ACCEPT_TAC;
    USE_THEN "boundary" ACCEPT_TAC]);;

let FINITE_SIMPLE_GRAPH_TRIANGULAR_CYCLE_RECURSIVE = prove
 (`!V E q:num->A.
        finite_simple_graph V E /\
        simple_graph_cycle E q 3 /\
        V = cyclic_vertices q 3
        ==> recursive_triangulated_disk V E q 3`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "graph (_ injective boundary_edges) vertices" THEN
  SUBGOAL_THEN
   `~((q:num->A) 0 = q 1) /\
    ~(q 1 = q 2) /\
    ~(q 2 = q 0)`
  (CONJUNCTS_THEN2 (LABEL_TAC "q01")
    (CONJUNCTS_THEN2 (LABEL_TAC "q12") (LABEL_TAC "q20"))) THENL
   [USE_THEN "injective" MP_TAC THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN
    REWRITE_TAC[INJ; IN_UNIV; CYCLIC_INDICES_3;
                IN_INSERT; NOT_IN_EMPTY] THEN
    MESON_TAC[ARITH_RULE
     `~((0:num) = 1) /\ ~(1 = 2) /\ ~(2 = 0)`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `complete_graph_edges (V:A->bool) = cyclic_edges q 3`
  (LABEL_TAC "complete") THENL
   [USE_THEN "vertices" SUBST1_TAC THEN
    REWRITE_TAC[CYCLIC_VERTICES_3; CYCLIC_EDGES_3] THEN
    MATCH_MP_TAC COMPLETE_GRAPH_EDGES_3 THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `E = cyclic_edges (q:num->A) 3`
  (LABEL_TAC "edges") THENL
   [MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
     [USE_THEN "complete" (fun th -> REWRITE_TAC[GSYM th]) THEN
      USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[FINITE_SIMPLE_GRAPH_EQ] THEN MESON_TAC[];
      USE_THEN "boundary_edges" ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPEC `q:num->A` (CONJUNCT1 recursive_triangulated_disk_RULES)) THEN
  ASM_REWRITE_TAC[]);;

let PLANE_TRIANGULATED_DISK_CARD_3_RECURSIVE = prove
 (`!V E p c q outer.
        plane_triangulated_disk
          (V:A->bool) E p c q 3 outer /\
        CARD V = 3
        ==> recursive_triangulated_disk V E q 3`,
  REPEAT GEN_TAC THEN INTRO_TAC "disk card" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `3`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph _ _ injective boundary_edges boundary _ _" THEN
  SUBGOAL_THEN `CARD(cyclic_vertices (q:num->A) 3) = 3`
  (LABEL_TAC "boundary_card") THENL
   [MATCH_MP_TAC CARD_CYCLIC_VERTICES THEN
    USE_THEN "injective" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `V = cyclic_vertices (q:num->A) 3`
  (LABEL_TAC "vertices") THENL
   [USE_THEN "graph"
      (ASSUME_TAC o CONJUNCT1 o REWRITE_RULE[FINITE_SIMPLE_GRAPH_EQ]) THEN
    MATCH_MP_TAC EQ_SYM THEN
    MATCH_MP_TAC CARD_SUBSET_EQ THEN
    ASM_REWRITE_TAC[FINITE_CYCLIC_VERTICES];
    ALL_TAC] THEN
  MATCH_MP_TAC FINITE_SIMPLE_GRAPH_TRIANGULAR_CYCLE_RECURSIVE THEN
  ASM_REWRITE_TAC[simple_graph_cycle] THEN ARITH_TAC);;

let TRIANGULAR_SIMPLE_GRAPH_CYCLE_CLIQUE = prove
 (`!E r:num->A. !u v.
        simple_graph_cycle E r 3 /\
        u IN cyclic_vertices r 3 /\
        v IN cyclic_vertices r 3 /\
        ~(u = v)
        ==> {u,v} IN E`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "(_ injective edges) u_vertex v_vertex distinct" THEN
  SUBGOAL_THEN
   `~((r:num->A) 0 = r 1) /\
    ~(r 1 = r 2) /\
    ~(r 2 = r 0)`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "injective" MP_TAC THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN
    REWRITE_TAC[INJ; IN_UNIV; CYCLIC_INDICES_3;
                IN_INSERT; NOT_IN_EMPTY] THEN
    MESON_TAC[ARITH_RULE
     `~((0:num) = 1) /\ ~(1 = 2) /\ ~(2 = 0)`];
    ALL_TAC] THEN
  USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
  SUBGOAL_THEN
   `complete_graph_edges (cyclic_vertices (r:num->A) 3) =
    cyclic_edges r 3`
  (fun th -> REWRITE_TAC[GSYM th]) THENL
   [REWRITE_TAC[CYCLIC_VERTICES_3; CYCLIC_EDGES_3] THEN
    MATCH_MP_TAC COMPLETE_GRAPH_EDGES_3 THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[IN_COMPLETE_GRAPH_EDGES] THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[INSERT_SUBSET; SING_SUBSET];
      REWRITE_TAC[HAS_SIZE_CONV `({u:A,v}:A->bool) HAS_SIZE 2`] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `v:A`] THEN ASM_REWRITE_TAC[]]]);;

let PLANE_TRIANGULATED_DISK_COMMON_FACE_ADJACENT_OR_BOUNDARY = prove
 (`!V E p c q n outer k u v.
        plane_triangulated_disk
          (V:A->bool) E p c q n outer /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        u IN plane_graph_face_vertices V E p c k /\
        v IN plane_graph_face_vertices V E p c k /\
        ~(u = v)
        ==> {u,v} IN E \/
            u IN cyclic_vertices q n /\
            v IN cyclic_vertices q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "disk component u_face v_face distinct" THEN
  ASM_CASES_TAC `(k:real^2->bool) = outer` THENL
   [DISJ2_TAC THEN
    USE_THEN "disk" MP_TAC THEN
    REWRITE_TAC[plane_triangulated_disk] THEN
    INTRO_TAC "_ _ _ _ _ boundary _" THEN
    USE_THEN "boundary" (fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_MESON_TAC[];
    DISJ1_TAC THEN
    USE_THEN "disk" MP_TAC THEN
    REWRITE_TAC[plane_triangulated_disk] THEN
    INTRO_TAC "_ _ _ _ _ _ inner_faces" THEN
    USE_THEN "inner_faces" (MP_TAC o SPEC `k:real^2->bool`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@r. face_vertices triangle" THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:num->A`; `u:A`; `v:A`]
     TRIANGULAR_SIMPLE_GRAPH_CYCLE_CLIQUE) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "triangle" ACCEPT_TAC;
      USE_THEN "face_vertices" (fun th -> REWRITE_TAC[GSYM th]) THEN
      USE_THEN "u_face" ACCEPT_TAC;
      USE_THEN "face_vertices" (fun th -> REWRITE_TAC[GSYM th]) THEN
      USE_THEN "v_face" ACCEPT_TAC;
      USE_THEN "distinct" ACCEPT_TAC]]);;

let BOUNDARY_NEIGHBOR_OF_LAST_WITHOUT_CHORD = prove
 (`!V E q:num->A. !n u.
        finite_simple_graph V E /\
        simple_graph_cycle E q n /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q (n - 1)} IN E)) /\
        u IN graph_neighbors E (q (n - 1)) /\
        u IN cyclic_vertices q n
        ==> u = q (n - 2) \/ u = q 0`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph cycle chordless neighbor boundary" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective boundary_edges" THEN
  USE_THEN "boundary" MP_TAC THEN
  REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
  INTRO_TAC "@i. index point" THEN
  USE_THEN "point" SUBST1_TAC THEN
  ASM_CASES_TAC `(i:num) = 0` THEN ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `(i:num) = n - 2` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `~((i:num) = n - 1)` (LABEL_TAC "not_last") THENL
   [DISCH_THEN(LABEL_TAC "last") THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
     `(q:num->A) (n - 1)`; `(q:num->A) i`]
     FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "neighbor" MP_TAC THEN
    USE_THEN "point" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "last" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN `0 < i /\ i + 2 < n`
  (CONJUNCTS_THEN2 (LABEL_TAC "positive") (LABEL_TAC "bound")) THENL
   [MATCH_MP_TAC(ARITH_RULE
     `3 <= n /\ i < n /\ ~(i = 0) /\
      ~(i = n - 2) /\ ~(i = n - 1)
      ==> 0 < i /\ i + 2 < n`) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "chordless" (MP_TAC o SPEC `i:num`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "no_chord") THEN
  SUBGOAL_THEN `{(q:num->A) i,q (n - 1)} IN E`
  (LABEL_TAC "edge") THENL
   [ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
    REWRITE_TAC[GSYM IN_GRAPH_NEIGHBORS] THEN
    USE_THEN "point" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "neighbor" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "no_chord" (fun nth ->
    USE_THEN "edge" (fun eth ->
      CONTR_TAC(MP (NOT_ELIM nth) eth))));;

let PLANE_GRAPH_CARRIER_MONO = prove
 (`!V V' E E' p c.
        (V':A->bool) SUBSET V /\ E' SUBSET E
        ==> plane_graph_carrier V' E' p c SUBSET
            plane_graph_carrier V E p c`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_graph_carrier; SUBSET; IN_UNION;
              IN_IMAGE; IN_UNIONS] THEN
  MESON_TAC[SUBSET]);;

let COMPLEMENT_COMPONENT_PERSISTS_WITH_FRONTIER = prove
 (`!s t k:real^N->bool.
        t SUBSET s /\
        k IN components ((:real^N) DIFF s) /\
        frontier k SUBSET t
        ==> k IN components ((:real^N) DIFF t)`,
  REPEAT GEN_TAC THEN INTRO_TAC "subset component frontier" THEN
  REWRITE_TAC[IN_COMPONENTS_MAXIMAL_ALT] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "component"
     (ACCEPT_TAC o MATCH_MP IN_COMPONENTS_NONEMPTY);
    USE_THEN "component" MP_TAC THEN
    DISCH_THEN(MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
    USE_THEN "subset" MP_TAC THEN SET_TAC[];
    USE_THEN "component"
     (ACCEPT_TAC o MATCH_MP IN_COMPONENTS_CONNECTED);
    X_GEN_TAC `u:real^N->bool` THEN
    INTRO_TAC "meets u_subset u_connected" THEN
    ASM_CASES_TAC `(u:real^N->bool) SUBSET k` THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_THEN `~((u:real^N->bool) SUBSET k)`
      (LABEL_TAC "not_subset") THEN
    MP_TAC(ISPECL [`u:real^N->bool`; `k:real^N->bool`]
      CONNECTED_INTER_FRONTIER) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "u_connected" ACCEPT_TAC;
        USE_THEN "meets" MP_TAC THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
        USE_THEN "not_subset" MP_TAC THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[]];
      DISCH_THEN(LABEL_TAC "meets_frontier") THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["meets_frontier"; "frontier"; "u_subset"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[]]]);;

let PLANE_GRAPH_FACE_COMPONENT_INDUCED_SUBGRAPH = prove
 (`!V E p c W k.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        W SUBSET V /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        plane_graph_face_vertices V E p c k SUBSET W
        ==> k IN components
          ((:real^2) DIFF
           plane_graph_carrier W (induced_subgraph_edges E W) p c)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding vertices component face_vertices" THEN
  MATCH_MP_TAC(ISPECL
   [`plane_graph_carrier (V:A->bool) E p c`;
    `plane_graph_carrier (W:A->bool)
      (induced_subgraph_edges E W) p c`;
    `k:real^2->bool`]
   COMPLEMENT_COMPONENT_PERSISTS_WITH_FRONTIER) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC PLANE_GRAPH_CARRIER_MONO THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[];
    USE_THEN "component" ACCEPT_TAC;
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC
     `plane_graph_carrier
       (plane_graph_face_vertices (V:A->bool) E p c k)
       (induced_subgraph_edges E
         (plane_graph_face_vertices V E p c k)) p c` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC
       PLANE_GRAPH_EMBEDDING_FACE_FRONTIER_SUBSET_INDUCED_CARRIER THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC PLANE_GRAPH_CARRIER_MONO THEN
      ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
      ASM_MESON_TAC[SUBSET]]]);;

let PLANE_GRAPH_FACE_VERTICES_RESTRICT = prove
 (`!V E p c W E' k.
        (W:A->bool) SUBSET V /\
        plane_graph_face_vertices V E p c k SUBSET W
        ==> plane_graph_face_vertices W E' p c k =
            plane_graph_face_vertices V E p c k`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_graph_face_vertices; SUBSET; EXTENSION; IN_ELIM_THM] THEN
  MESON_TAC[]);;

let PLANE_TRIANGULATED_DISK_NONINCIDENT_FACE_PERSISTS = prove
 (`!V E p c q n outer k v.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        ~(v IN plane_graph_face_vertices V E p c k)
        ==> k IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
            plane_graph_face_vertices
              (V DELETE v) (induced_subgraph_edges E (V DELETE v))
              p c k =
            plane_graph_face_vertices V E p c k`,
  REPEAT GEN_TAC THEN INTRO_TAC "disk component nonincident" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "graph embedding _ _ _ _ _ _" THEN
  SUBGOAL_THEN
   `plane_graph_face_vertices (V:A->bool) E p c k SUBSET V DELETE v`
  (LABEL_TAC "face_vertices") THENL
   [REWRITE_TAC[SUBSET; IN_DELETE] THEN X_GEN_TAC `u:A` THEN
    DISCH_THEN(LABEL_TAC "u_face") THEN CONJ_TAC THENL
     [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (ISPECL
        [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
         `c:(A->bool)->real^2->bool`; `k:real^2->bool`]
        PLANE_GRAPH_FACE_VERTICES_SUBSET)) THEN
      USE_THEN "u_face" ACCEPT_TAC;
      DISCH_THEN SUBST_ALL_TAC THEN
      USE_THEN "nonincident" (fun nth ->
        USE_THEN "u_face" (fun th ->
          CONTR_TAC(MP (NOT_ELIM nth) th)))];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `V DELETE (v:A)`;
      `k:real^2->bool`]
     PLANE_GRAPH_FACE_COMPONENT_INDUCED_SUBGRAPH) THEN
    ASM_REWRITE_TAC[DELETE_SUBSET];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `(V:A->bool) DELETE (v:A)`;
      `induced_subgraph_edges (E:(A->bool)->bool)
        ((V:A->bool) DELETE (v:A))`;
      `k:real^2->bool`]
     PLANE_GRAPH_FACE_VERTICES_RESTRICT) THEN
    ASM_REWRITE_TAC[DELETE_SUBSET]]);;

let PLANE_GRAPH_EMBEDDING_DELETE_VERTEX_POINT_OUTSIDE_CARRIER = prove
 (`!V E p c v.
        plane_graph_embedding (V:A->bool) E p c /\
        v IN V
        ==> ~((p:A->real^2) v IN
              plane_graph_carrier (V DELETE v)
                (induced_subgraph_edges E (V DELETE v)) p c)`,
  REPEAT GEN_TAC THEN INTRO_TAC "embedding vertex" THEN
  USE_THEN "embedding" MP_TAC THEN
  REWRITE_TAC[plane_graph_embedding] THEN
  INTRO_TAC "injective _ edge_vertices _" THEN
  REWRITE_TAC[plane_graph_carrier; UNIONS_IMAGE; IN_UNION;
              IN_IMAGE; IN_ELIM_THM] THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (X_CHOOSE_THEN `u:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "equal") (LABEL_TAC "u_delete")))
   (X_CHOOSE_THEN `e:A->bool`
    (CONJUNCTS_THEN2 (LABEL_TAC "edge") (LABEL_TAC "point")))) THENL
   [USE_THEN "u_delete" (MP_TAC o REWRITE_RULE[IN_DELETE]) THEN
    INTRO_TAC "u_vertex distinct" THEN
    USE_THEN "injective" (fun th ->
      MP_TAC(SPECL [`v:A`; `u:A`]
       (REWRITE_RULE[INJ; IN_UNIV] th))) THEN
    ASM_REWRITE_TAC[];
    USE_THEN "edge"
     (MP_TAC o REWRITE_RULE[IN_INDUCED_SUBGRAPH_EDGES]) THEN
    INTRO_TAC "old_edge edge_subset" THEN
    USE_THEN "edge_vertices" (MP_TAC o SPEC `e:A->bool`) THEN
    ANTS_TAC THENL [USE_THEN "old_edge" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(LABEL_TAC "edge_inter") THEN
    SUBGOAL_THEN `(p:A->real^2) v IN IMAGE p e`
    (LABEL_TAC "point_image") THENL
     [USE_THEN "edge_inter"
       (fun th -> REWRITE_TAC[GSYM th; IN_INTER]) THEN
      CONJ_TAC THENL
       [USE_THEN "point" ACCEPT_TAC;
        REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `v:A` THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    USE_THEN "point_image" MP_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@u. equal u_edge" THEN
    SUBGOAL_THEN `(u:A) IN V DELETE v` (LABEL_TAC "u_delete") THENL
     [USE_THEN "edge_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "u_edge" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "u_delete" (MP_TAC o REWRITE_RULE[IN_DELETE]) THEN
    INTRO_TAC "u_vertex distinct" THEN
    USE_THEN "injective" (fun th ->
      MP_TAC(SPECL [`v:A`; `u:A`]
       (REWRITE_RULE[INJ; IN_UNIV] th))) THEN
    ASM_REWRITE_TAC[]]);;

let COMPONENT_SUBSET_OF_SUPERSET_COMPONENT = prove
 (`!s t k:real^N->bool.
        s SUBSET t /\
        k IN components s
        ==> ?l. l IN components t /\ k SUBSET l`,
  REPEAT GEN_TAC THEN INTRO_TAC "subset component" THEN
  MATCH_MP_TAC(ISPECL
   [`t:real^N->bool`; `k:real^N->bool`]
   EXISTS_COMPONENT_SUPERSET) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `s:real^N->bool` THEN
    CONJ_TAC THENL
     [USE_THEN "component"
       (ACCEPT_TAC o MATCH_MP IN_COMPONENTS_SUBSET);
      USE_THEN "subset" ACCEPT_TAC];
    SUBGOAL_THEN `~((k:real^N->bool) = {})`
    (LABEL_TAC "nonempty") THENL
     [USE_THEN "component"
       (ACCEPT_TAC o MATCH_MP IN_COMPONENTS_NONEMPTY);
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["nonempty"; "subset"] THEN
      USE_THEN "component"
       (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[]];
    USE_THEN "component"
     (ACCEPT_TAC o MATCH_MP IN_COMPONENTS_CONNECTED)]);;

let PLANE_GRAPH_DELETE_VERTEX_COMPONENT_ADJOINS_POINT = prove
 (`!V E p c v k l.
        plane_graph_embedding (V:A->bool) E p c /\
        v IN V /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        v IN plane_graph_face_vertices V E p c k /\
        l IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        k SUBSET l
        ==> (p:A->real^2) v INSERT k SUBSET l`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "embedding vertex component v_face larger k_subset" THEN
  SUBGOAL_THEN `connected(k:real^2->bool)`
  (LABEL_TAC "connected") THENL
   [USE_THEN "component"
     (ACCEPT_TAC o MATCH_MP IN_COMPONENTS_CONNECTED);
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:A->real^2) v IN closure k`
  (LABEL_TAC "v_closure") THENL
   [USE_THEN "v_face" MP_TAC THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN
    REWRITE_TAC[plane_graph_face_vertices; IN_ELIM_THM;
                frontier; IN_DIFF] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_carrier ((V:A->bool) DELETE (v:A))
      (induced_subgraph_edges (E:(A->bool)->bool)
        ((V:A->bool) DELETE (v:A))) (p:A->real^2)
        (c:(A->bool)->real^2->bool) SUBSET
    plane_graph_carrier V E p c`
  (LABEL_TAC "carrier_subset") THENL
   [MATCH_MP_TAC PLANE_GRAPH_CARRIER_MONO THEN
    REWRITE_TAC[DELETE_SUBSET] THEN
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`(:real^2) DIFF
      plane_graph_carrier ((V:A->bool) DELETE (v:A))
       (induced_subgraph_edges (E:(A->bool)->bool)
         ((V:A->bool) DELETE (v:A))) (p:A->real^2)
         (c:(A->bool)->real^2->bool)`;
    `l:real^2->bool`; `(p:A->real^2) v INSERT (k:real^2->bool)`]
   CONNECTED_SUBSET_OF_COMPONENT) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "larger" ACCEPT_TAC;
    ASM_SIMP_TAC[CONNECTED_INSERT];
    REWRITE_TAC[INSERT_SUBSET; IN_DIFF; IN_UNIV] THEN CONJ_TAC THENL
     [MATCH_MP_TAC
       PLANE_GRAPH_EMBEDDING_DELETE_VERTEX_POINT_OUTSIDE_CARRIER THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC
       `(:real^2) DIFF
        plane_graph_carrier (V:A->bool) (E:(A->bool)->bool)
          (p:A->real^2) (c:(A->bool)->real^2->bool)` THEN
      CONJ_TAC THENL
       [USE_THEN "component"
         (ACCEPT_TAC o MATCH_MP IN_COMPONENTS_SUBSET);
        USE_THEN "carrier_subset" MP_TAC THEN SET_TAC[]]];
    SUBGOAL_THEN `~((k:real^2->bool) = {})`
    (LABEL_TAC "nonempty") THENL
     [USE_THEN "component"
       (ACCEPT_TAC o MATCH_MP IN_COMPONENTS_NONEMPTY);
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["nonempty"; "k_subset"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[]]]);;

let PLANE_TRIANGULATED_DISK_DELETE_VERTEX_OUTER_COMPONENT = prove
 (`!V E p c q n outer v.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        v IN cyclic_vertices q n
        ==> ?outer'.
              outer' IN components
               ((:real^2) DIFF
                plane_graph_carrier (V DELETE v)
                 (induced_subgraph_edges E (V DELETE v)) p c) /\
              outer SUBSET outer' /\
              (p:A->real^2) v IN outer'`,
  REPEAT GEN_TAC THEN INTRO_TAC "disk v_boundary" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "_ embedding _ _ _ boundary_subset component boundary" THEN
  SUBGOAL_THEN `(v:A) IN V` (LABEL_TAC "v_vertex") THENL
   [USE_THEN "boundary_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "v_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_carrier ((V:A->bool) DELETE (v:A))
      (induced_subgraph_edges (E:(A->bool)->bool)
       ((V:A->bool) DELETE (v:A))) (p:A->real^2)
       (c:(A->bool)->real^2->bool) SUBSET
    plane_graph_carrier V E p c`
  (LABEL_TAC "carrier_subset") THENL
   [MATCH_MP_TAC PLANE_GRAPH_CARRIER_MONO THEN
    REWRITE_TAC[DELETE_SUBSET] THEN
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((:real^2) DIFF plane_graph_carrier V E p c) SUBSET
    ((:real^2) DIFF
     plane_graph_carrier ((V:A->bool) DELETE (v:A))
      (induced_subgraph_edges (E:(A->bool)->bool)
       ((V:A->bool) DELETE (v:A))) p c)`
  (LABEL_TAC "complement_subset") THENL
   [USE_THEN "carrier_subset" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(:real^2) DIFF plane_graph_carrier (V:A->bool) E p c`;
    `(:real^2) DIFF
     plane_graph_carrier ((V:A->bool) DELETE (v:A))
      (induced_subgraph_edges (E:(A->bool)->bool)
       ((V:A->bool) DELETE (v:A))) p c`;
    `outer:real^2->bool`]
   COMPONENT_SUBSET_OF_SUPERSET_COMPONENT) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "complement_subset" ACCEPT_TAC;
      USE_THEN "component" ACCEPT_TAC];
    INTRO_TAC "@outer'. outer'_component outer_subset"] THEN
  SUBGOAL_THEN
   `v IN plane_graph_face_vertices (V:A->bool) E p c outer`
  (LABEL_TAC "v_face") THENL
   [USE_THEN "boundary" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "v_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:A->real^2) v INSERT outer SUBSET outer'`
  (LABEL_TAC "adjoined") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `v:A`;
      `outer:real^2->bool`; `outer':real^2->bool`]
     PLANE_GRAPH_DELETE_VERTEX_COMPONENT_ADJOINS_POINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `outer':real^2->bool` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "outer'_component" ACCEPT_TAC;
    USE_THEN "outer_subset" ACCEPT_TAC;
    USE_THEN "adjoined"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[INSERT_SUBSET])]);;

let PLANE_GRAPH_DELETE_VERTEX_INCIDENT_COMPONENTS_MERGE = prove
 (`!V E p c v k1 k2 l1 l2.
        plane_graph_embedding (V:A->bool) E p c /\
        v IN V /\
        k1 IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        v IN plane_graph_face_vertices V E p c k1 /\
        k2 IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        v IN plane_graph_face_vertices V E p c k2 /\
        l1 IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        k1 SUBSET l1 /\
        l2 IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        k2 SUBSET l2
        ==> l1 = l2`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "embedding vertex k1_component v_face1 k2_component v_face2 \
    l1_component k1_subset l2_component k2_subset" THEN
  SUBGOAL_THEN `(p:A->real^2) v INSERT k1 SUBSET l1`
  (LABEL_TAC "adjoined1") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `v:A`;
      `k1:real^2->bool`; `l1:real^2->bool`]
     PLANE_GRAPH_DELETE_VERTEX_COMPONENT_ADJOINS_POINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:A->real^2) v INSERT k2 SUBSET l2`
  (LABEL_TAC "adjoined2") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `v:A`;
      `k2:real^2->bool`; `l2:real^2->bool`]
     PLANE_GRAPH_DELETE_VERTEX_COMPONENT_ADJOINS_POINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(:real^2) DIFF
      plane_graph_carrier ((V:A->bool) DELETE (v:A))
       (induced_subgraph_edges (E:(A->bool)->bool)
         ((V:A->bool) DELETE (v:A)))
       (p:A->real^2) (c:(A->bool)->real^2->bool)`;
    `l1:real^2->bool`; `l2:real^2->bool`]
   COMPONENTS_EQ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MATCH_MP_TAC(snd(EQ_IMP_RULE th))) THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
  EXISTS_TAC `(p:A->real^2) v` THEN CONJ_TAC THENL
   [USE_THEN "adjoined1"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[INSERT_SUBSET]);
    USE_THEN "adjoined2"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[INSERT_SUBSET])]);;

let PLANE_GRAPH_DELETE_VERTEX_INCIDENT_COMPONENT_SUBSET = prove
 (`!V E p c v k0 l0 k.
        plane_graph_embedding (V:A->bool) E p c /\
        v IN V /\
        k0 IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        v IN plane_graph_face_vertices V E p c k0 /\
        l0 IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        k0 SUBSET l0 /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        v IN plane_graph_face_vertices V E p c k
        ==> k SUBSET l0`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "embedding vertex k0_component v_k0 l0_component k0_subset \
    k_component v_k" THEN
  SUBGOAL_THEN
   `plane_graph_carrier ((V:A->bool) DELETE (v:A))
      (induced_subgraph_edges (E:(A->bool)->bool)
       ((V:A->bool) DELETE (v:A))) (p:A->real^2)
       (c:(A->bool)->real^2->bool) SUBSET
    plane_graph_carrier V E p c`
  (LABEL_TAC "carrier_subset") THENL
   [MATCH_MP_TAC PLANE_GRAPH_CARRIER_MONO THEN
    REWRITE_TAC[DELETE_SUBSET] THEN
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(:real^2) DIFF plane_graph_carrier (V:A->bool) E p c`;
    `(:real^2) DIFF
     plane_graph_carrier ((V:A->bool) DELETE (v:A))
      (induced_subgraph_edges (E:(A->bool)->bool)
       ((V:A->bool) DELETE (v:A))) p c`;
    `k:real^2->bool`]
   COMPONENT_SUBSET_OF_SUPERSET_COMPONENT) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "carrier_subset" MP_TAC THEN SET_TAC[];
      USE_THEN "k_component" ACCEPT_TAC];
    INTRO_TAC "@l. l_component k_subset"] THEN
  SUBGOAL_THEN `(l0:real^2->bool) = l` SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `v:A`;
      `k0:real^2->bool`; `k:real^2->bool`;
      `l0:real^2->bool`; `l:real^2->bool`]
     PLANE_GRAPH_DELETE_VERTEX_INCIDENT_COMPONENTS_MERGE) THEN
    ASM_REWRITE_TAC[];
    USE_THEN "k_subset" ACCEPT_TAC]);;

let PLANE_GRAPH_DELETE_VERTEX_INCIDENT_FACE_VERTEX = prove
 (`!V E p c v k l u.
        l IN components
          ((:real^2) DIFF
           plane_graph_carrier ((V:A->bool) DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        k SUBSET l /\
        u IN plane_graph_face_vertices V E p c k /\
        ~(u = v)
        ==> u IN
            plane_graph_face_vertices (V DELETE v)
              (induced_subgraph_edges E (V DELETE v)) p c l`,
