  REWRITE_TAC[plane_graph_face_vertices; IN_ELIM_THM] THEN
  CONJ_TAC THENL
   [ASM_REWRITE_TAC[IN_DELETE];
    ALL_TAC] THEN
  REWRITE_TAC[frontier; IN_DIFF] THEN CONJ_TAC THENL
   [SUBGOAL_THEN `closure(k:real^2->bool) SUBSET closure l`
    (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THENL
     [MATCH_MP_TAC CLOSURE_MINIMAL THEN CONJ_TAC THENL
       [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `l:real^2->bool` THEN
        ASM_REWRITE_TAC[CLOSURE_SUBSET];
        REWRITE_TAC[CLOSED_CLOSURE]];
      USE_THEN "u_frontier" MP_TAC THEN
      REWRITE_TAC[frontier; IN_DIFF] THEN MESON_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "u_interior") THEN
  SUBGOAL_THEN `(p:A->real^2) u IN l` (LABEL_TAC "u_in_l") THENL
   [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
     (ISPEC `l:real^2->bool` INTERIOR_SUBSET)) THEN
    USE_THEN "u_interior" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:A->real^2) u IN
    plane_graph_carrier ((V:A->bool) DELETE (v:A))
      (induced_subgraph_edges (E:(A->bool)->bool)
       ((V:A->bool) DELETE (v:A))) p c`
  (LABEL_TAC "u_carrier") THENL
   [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
     (ISPECL
      [`(V:A->bool) DELETE (v:A)`;
       `induced_subgraph_edges (E:(A->bool)->bool)
        ((V:A->bool) DELETE (v:A))`;
       `p:A->real^2`; `c:(A->bool)->real^2->bool`]
      PLANE_GRAPH_CARRIER_VERTEX_SUBSET)) THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `u:A` THEN
    ASM_REWRITE_TAC[IN_DELETE];
    ALL_TAC] THEN
  USE_THEN "component" (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
  MAP_EVERY (fun name -> USE_THEN name MP_TAC) ["u_in_l"; "u_carrier"] THEN
  POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[]);;

let PLANE_TRIANGULATED_DISK_DELETE_VERTEX_INCIDENT_FACE_VERTICES = prove
 (`!V E p c q n outer v newouter k.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        v IN cyclic_vertices q n /\
        newouter IN components
          ((:real^2) DIFF
