  INTRO_TAC
   "disk v_boundary outer_component outer_subset k_component v_face" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "_ embedding _ _ _ boundary_subset old_outer boundary" THEN
  SUBGOAL_THEN `(v:A) IN V` (LABEL_TAC "v_vertex") THENL
   [USE_THEN "boundary_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "v_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `v IN plane_graph_face_vertices (V:A->bool) E p c outer`
  (LABEL_TAC "v_outer") THENL
   [USE_THEN "boundary" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "v_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(k:real^2->bool) SUBSET newouter`
  (LABEL_TAC "face_subset") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `v:A`;
      `outer:real^2->bool`; `newouter:real^2->bool`;
      `k:real^2->bool`]
     PLANE_GRAPH_DELETE_VERTEX_INCIDENT_COMPONENT_SUBSET) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET; IN_DELETE] THEN X_GEN_TAC `u:A` THEN
  INTRO_TAC "u_face distinct" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `v:A`;
    `k:real^2->bool`; `newouter:real^2->bool`; `u:A`]
   PLANE_GRAPH_DELETE_VERTEX_INCIDENT_FACE_VERTEX) THEN
  ASM_REWRITE_TAC[]);;

let PLANE_TRIANGULATED_DISK_DELETE_VERTEX_BOUNDARY_NEIGHBORS_SUBSET = prove
