let CLOSURE_INTER_UNIONS_COMPONENTS = prove
 (`!u l:real^N->bool.
        FINITE(components u)
        ==> closure(l INTER u) =
            UNIONS {closure(l INTER k) | k IN components u}`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "finite") THEN
  SUBGOAL_THEN
   `(l:real^N->bool) INTER u =
    UNIONS(IMAGE (\k:real^N->bool. l INTER k) (components u))`
  SUBST1_TAC THENL
   [MP_TAC(ISPEC `u:real^N->bool` UNIONS_COMPONENTS) THEN SET_TAC[];
    ALL_TAC] THEN
  ASM_SIMP_TAC[CLOSURE_UNIONS; FINITE_IMAGE] THEN
  AP_TERM_TAC THEN SET_TAC[]);;

let IN_UNIONS_CLOSURE_INTER = prove
 (`!f:(real^N->bool)->bool. !l x.
        x IN UNIONS {closure(l INTER k) | k IN f}
        ==> ?k. k IN f /\ x IN closure(l INTER k)`,
  REWRITE_TAC[IN_UNIONS; IN_ELIM_THM] THEN
  REPEAT STRIP_TAC THEN ASM_MESON_TAC[]);;

let COMPONENT_FRONTIER_OF_SUBSET_AWAY_FROM_DIFFERENCE = prove
 (`!s t l x:real^N.
        FINITE(components((:real^N) DIFF s)) /\
        t SUBSET s /\
        l IN components((:real^N) DIFF t) /\
        x IN frontier l /\
        x IN t /\
        ~(x IN closure(s DIFF t))
        ==> ?k. k IN components((:real^N) DIFF s) /\
                k SUBSET l /\
                x IN frontier k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite subset component x_frontier x_t x_away" THEN
  SUBGOAL_THEN `open((:real^N) DIFF closure(s DIFF t))`
  (LABEL_TAC "neighborhood_open") THENL
   [REWRITE_TAC[GSYM closed; CLOSED_CLOSURE];
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:real^N) IN (:real^N) DIFF closure(s DIFF t)`
  (LABEL_TAC "x_neighborhood") THENL
   [ASM_REWRITE_TAC[IN_DIFF; IN_UNIV];
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:real^N) IN closure l` (LABEL_TAC "x_closure") THENL
   [USE_THEN "x_frontier" MP_TAC THEN
    REWRITE_TAC[frontier; IN_DIFF] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(x:real^N) IN closure
     (((:real^N) DIFF closure(s DIFF t)) INTER l)`
  (LABEL_TAC "x_local_closure") THENL
   [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
     (MATCH_MP OPEN_INTER_CLOSURE_SUBSET
       (ASSUME `open((:real^N) DIFF closure(s DIFF t))`))) THEN
    REWRITE_TAC[IN_INTER] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((:real^N) DIFF closure(s DIFF t)) INTER l SUBSET
    l INTER ((:real^N) DIFF s)`
  (LABEL_TAC "local_subset") THENL
   [USE_THEN "component" (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
    MP_TAC(ISPEC `s DIFF t:real^N->bool` CLOSURE_SUBSET) THEN
    USE_THEN "subset" MP_TAC THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:real^N) IN closure(l INTER ((:real^N) DIFF s))`
  (LABEL_TAC "x_old_closure") THENL
   [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
     (MATCH_MP SUBSET_CLOSURE
       (ASSUME
        `((:real^N) DIFF closure(s DIFF t)) INTER l SUBSET
         l INTER ((:real^N) DIFF s)`))) THEN
    USE_THEN "x_local_closure" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?k:real^N->bool.
        k IN components((:real^N) DIFF s) /\
        x IN closure(l INTER k)` MP_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`components((:real^N) DIFF s)`; `l:real^N->bool`; `x:real^N`]
     IN_UNIONS_CLOSURE_INTER) THEN
    USE_THEN "x_old_closure" MP_TAC THEN
    ONCE_REWRITE_TAC[MATCH_MP
     (ISPECL [`(:real^N) DIFF s`; `l:real^N->bool`]
       CLOSURE_INTER_UNIONS_COMPONENTS)
     (ASSUME `FINITE(components((:real^N) DIFF s))`)] THEN
    REWRITE_TAC[];
    INTRO_TAC "@k. k_component x_inter_closure"] THEN
  SUBGOAL_THEN `~((l INTER k:real^N->bool) = {})`
  (LABEL_TAC "inter_nonempty") THENL
   [DISCH_THEN(fun th -> USE_THEN "x_inter_closure" MP_TAC THEN
      REWRITE_TAC[th; CLOSURE_EMPTY; NOT_IN_EMPTY]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(k:real^N->bool) SUBSET l` (LABEL_TAC "k_subset") THENL
   [MATCH_MP_TAC(ISPECL
     [`(:real^N) DIFF t`; `l:real^N->bool`; `k:real^N->bool`]
     CONNECTED_SUBSET_OF_COMPONENT) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "component" ACCEPT_TAC;
      USE_THEN "k_component"
       (ACCEPT_TAC o MATCH_MP IN_COMPONENTS_CONNECTED);
      USE_THEN "k_component" (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
      USE_THEN "subset" MP_TAC THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
      ONCE_REWRITE_TAC[INTER_COMM] THEN
      USE_THEN "inter_nonempty" ACCEPT_TAC];
    ALL_TAC] THEN
  EXISTS_TAC `k:real^N->bool` THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[frontier; IN_DIFF] THEN CONJ_TAC THENL
   [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
     (MATCH_MP SUBSET_CLOSURE
       (SET_RULE `(l INTER k:real^N->bool) SUBSET k`))) THEN
    USE_THEN "x_inter_closure" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "k_component" (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
  MP_TAC(ISPEC `k:real^N->bool` INTERIOR_SUBSET) THEN
  MAP_EVERY (fun name -> USE_THEN name MP_TAC) ["subset"; "x_t"] THEN
  POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[]);;

let FINITE_SIMPLE_GRAPH_EDGE_EQ_OF_MEMBERS = prove
 (`!V E e u v.
        finite_simple_graph (V:A->bool) E /\
        e IN E /\ u IN e /\ v IN e /\ ~(u = v)
        ==> e = {u,v}`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge u_edge v_edge distinct" THEN
  MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`]
   FINITE_SIMPLE_GRAPH_EDGE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@a b. _ _ ab_distinct edge_pair" THEN
  USE_THEN "edge_pair" SUBST_ALL_TAC THEN
  MAP_EVERY (fun name -> USE_THEN name MP_TAC)
   ["u_edge"; "v_edge"; "distinct"; "ab_distinct"] THEN
  POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[]);;

let PLANE_GRAPH_CARRIER_DELETE_VERTEX_SUBSET_OBSTACLES = prove
 (`!V E p c u v.
        finite_simple_graph (V:A->bool) E /\
        u IN V /\ v IN V /\ ~(u = v) /\
        ~(u IN graph_neighbors E v)
        ==> plane_graph_carrier V E p c DIFF
            plane_graph_carrier (V DELETE v)
              (induced_subgraph_edges E (V DELETE v)) p c
            SUBSET embedding_vertex_obstacles V E p c u`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph u_vertex v_vertex distinct nonneighbor" THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `x:real^2` THEN
  REWRITE_TAC[plane_graph_carrier; embedding_vertex_obstacles;
              UNIONS_IMAGE; IN_DIFF; IN_UNION; IN_IMAGE; IN_ELIM_THM] THEN
  INTRO_TAC "((@w. point w_vertex) | (@e. edge point)) outside" THENL
   [ASM_CASES_TAC `(w:A) = u` THENL
     [SUBGOAL_THEN
       `?z:A. (x:real^2) = (p:A->real^2) z /\ z IN V DELETE v`
      (LABEL_TAC "new_vertex") THENL
       [EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[IN_DELETE];
        MAP_EVERY (fun name -> USE_THEN name MP_TAC)
         ["outside"; "new_vertex"] THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[]];
      DISJ1_TAC THEN EXISTS_TAC `w:A` THEN
      ASM_REWRITE_TAC[IN_DELETE]];
    ASM_CASES_TAC `(u:A) IN e` THENL
     [SUBGOAL_THEN `~((v:A) IN e)` (LABEL_TAC "v_not_edge") THENL
       [DISCH_THEN(LABEL_TAC "v_edge") THEN
        SUBGOAL_THEN `(e:A->bool) = {u,v}` (LABEL_TAC "edge_pair") THENL
         [MATCH_MP_TAC(ISPECL
           [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`;
            `u:A`; `v:A`]
           FINITE_SIMPLE_GRAPH_EDGE_EQ_OF_MEMBERS) THEN
          ASM_REWRITE_TAC[];
          SUBGOAL_THEN `(u:A) IN graph_neighbors E v`
          (LABEL_TAC "neighbor") THENL
           [REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
            ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
            USE_THEN "edge_pair" (fun th -> REWRITE_TAC[GSYM th]) THEN
            USE_THEN "edge" ACCEPT_TAC;
            ASM_MESON_TAC[]]];
        ALL_TAC] THEN
      SUBGOAL_THEN `(e:A->bool) SUBSET V` (LABEL_TAC "edge_subset") THENL
       [USE_THEN "graph" MP_TAC THEN
        REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(e:A->bool) SUBSET V DELETE v`
      (LABEL_TAC "edge_delete") THENL
       [USE_THEN "edge_subset" MP_TAC THEN
        USE_THEN "v_not_edge" MP_TAC THEN SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(e:A->bool) IN induced_subgraph_edges E (V DELETE v)`
      (LABEL_TAC "new_edge") THENL
       [REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `?d:A->bool.
          d IN induced_subgraph_edges E (V DELETE v) /\
          (x:real^2) IN c d`
      (LABEL_TAC "new_point") THENL
       [EXISTS_TAC `e:A->bool` THEN ASM_REWRITE_TAC[];
        MAP_EVERY (fun name -> USE_THEN name MP_TAC)
         ["outside"; "new_point"] THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[]];
      DISJ2_TAC THEN EXISTS_TAC `e:A->bool` THEN
      ASM_REWRITE_TAC[]]]);;

let PLANE_GRAPH_DELETE_VERTEX_POINT_AWAY_FROM_REMOVED_CARRIER = prove
 (`!V E p c u v.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        u IN V /\ v IN V /\ ~(u = v) /\
        ~(u IN graph_neighbors E v)
        ==> ~((p:A->real^2) u IN
              closure
               (plane_graph_carrier V E p c DIFF
                plane_graph_carrier (V DELETE v)
                  (induced_subgraph_edges E (V DELETE v)) p c))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding u_vertex v_vertex distinct nonneighbor" THEN
  SUBGOAL_THEN
   `plane_graph_carrier (V:A->bool) E p c DIFF
    plane_graph_carrier (V DELETE v)
      (induced_subgraph_edges E (V DELETE v)) p c SUBSET
    embedding_vertex_obstacles V E p c u`
  (LABEL_TAC "removed_subset") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `u:A`; `v:A`]
     PLANE_GRAPH_CARRIER_DELETE_VERTEX_SUBSET_OBSTACLES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `closed(embedding_vertex_obstacles
      (V:A->bool) E (p:A->real^2) c u)`
  (LABEL_TAC "obstacles_closed") THENL
   [MATCH_MP_TAC COMPACT_IMP_CLOSED THEN
    MATCH_MP_TAC COMPACT_EMBEDDING_VERTEX_OBSTACLES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `closure
     (plane_graph_carrier (V:A->bool) E p c DIFF
      plane_graph_carrier (V DELETE v)
       (induced_subgraph_edges E (V DELETE v)) p c) SUBSET
    embedding_vertex_obstacles V E p c u`
  (LABEL_TAC "closure_subset") THENL
   [MATCH_MP_TAC CLOSURE_MINIMAL THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((p:A->real^2) u IN embedding_vertex_obstacles V E p c u)`
  (LABEL_TAC "point_outside") THENL
   [MATCH_MP_TAC EMBEDDING_VERTEX_NOT_IN_OBSTACLES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY (fun name -> USE_THEN name MP_TAC)
   ["closure_subset"; "point_outside"] THEN
  POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[]);;

let PLANE_GRAPH_DELETE_VERTEX_NEW_FACE_VERTEX_OLD_FACE = prove
 (`!V E p c v l u.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        v IN V /\
        l IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        u IN plane_graph_face_vertices (V DELETE v)
          (induced_subgraph_edges E (V DELETE v)) p c l /\
        ~(u IN graph_neighbors E v)
        ==> ?k. k IN components
                   ((:real^2) DIFF plane_graph_carrier V E p c) /\
                k SUBSET l /\
                u IN plane_graph_face_vertices V E p c k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding v_vertex component u_newface nonneighbor" THEN
  USE_THEN "u_newface" MP_TAC THEN
  REWRITE_TAC[plane_graph_face_vertices; IN_ELIM_THM] THEN
  INTRO_TAC "u_delete u_frontier" THEN
  USE_THEN "u_delete" MP_TAC THEN
  REWRITE_TAC[IN_DELETE] THEN INTRO_TAC "u_vertex distinct" THEN
  SUBGOAL_THEN
   `plane_graph_carrier ((V:A->bool) DELETE (v:A))
      (induced_subgraph_edges (E:(A->bool)->bool)
       ((V:A->bool) DELETE (v:A))) p c SUBSET
    plane_graph_carrier V E p c`
  (LABEL_TAC "carrier_subset") THENL
   [MATCH_MP_TAC PLANE_GRAPH_CARRIER_MONO THEN
    CONJ_TAC THENL
     [REWRITE_TAC[DELETE_SUBSET];
      REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(components
     ((:real^2) DIFF plane_graph_carrier (V:A->bool) E p c))`
  (LABEL_TAC "finite_faces") THENL
   [MATCH_MP_TAC FINITE_COMPLEMENT_COMPONENTS_PLANE_GRAPH_CARRIER THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:A->real^2) u IN
    plane_graph_carrier ((V:A->bool) DELETE (v:A))
      (induced_subgraph_edges (E:(A->bool)->bool)
       ((V:A->bool) DELETE (v:A))) p c`
  (LABEL_TAC "u_newcarrier") THENL
   [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
     (ISPECL
      [`(V:A->bool) DELETE (v:A)`;
       `induced_subgraph_edges (E:(A->bool)->bool)
        ((V:A->bool) DELETE (v:A))`;
       `p:A->real^2`; `c:(A->bool)->real^2->bool`]
      PLANE_GRAPH_CARRIER_VERTEX_SUBSET)) THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `u:A` THEN
    ASM_REWRITE_TAC[IN_DELETE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((p:A->real^2) u IN
      closure
       (plane_graph_carrier V E p c DIFF
        plane_graph_carrier (V DELETE v)
          (induced_subgraph_edges E (V DELETE v)) p c))`
  (LABEL_TAC "u_away") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `u:A`; `v:A`]
     PLANE_GRAPH_DELETE_VERTEX_POINT_AWAY_FROM_REMOVED_CARRIER) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?k:real^2->bool.
      k IN components
       ((:real^2) DIFF plane_graph_carrier (V:A->bool) E p c) /\
      k SUBSET l /\ (p:A->real^2) u IN frontier k` MP_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`plane_graph_carrier (V:A->bool) E p c`;
      `plane_graph_carrier ((V:A->bool) DELETE (v:A))
        (induced_subgraph_edges (E:(A->bool)->bool)
          ((V:A->bool) DELETE (v:A)))
        (p:A->real^2) (c:(A->bool)->real^2->bool)`;
      `l:real^2->bool`; `(p:A->real^2) u`]
     COMPONENT_FRONTIER_OF_SUBSET_AWAY_FROM_DIFFERENCE) THEN
    ASM_REWRITE_TAC[];
    INTRO_TAC "@k. k_component k_subset u_oldfrontier"] THEN
  EXISTS_TAC `k:real^2->bool` THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[plane_graph_face_vertices; IN_ELIM_THM] THEN
  ASM_REWRITE_TAC[]);;

let PLANE_TRIANGULATED_DISK_DELETE_VERTEX_FACE_VERTICES_SUBSET = prove
 (`!V E p c q n outer v newouter.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        v IN cyclic_vertices q n /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        outer SUBSET newouter
        ==> plane_graph_face_vertices (V DELETE v)
              (induced_subgraph_edges E (V DELETE v)) p c newouter
            SUBSET
            (cyclic_vertices q n DELETE v) UNION graph_neighbors E v`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "disk v_boundary outer_component outer_subset" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding _ _ _ boundary_subset old_outer boundary" THEN
  SUBGOAL_THEN `(v:A) IN V` (LABEL_TAC "v_vertex") THENL
   [USE_THEN "boundary_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "v_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `v IN plane_graph_face_vertices (V:A->bool) E p c outer`
  (LABEL_TAC "v_outer") THENL
   [USE_THEN "boundary" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "v_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:A->real^2) v INSERT outer SUBSET newouter`
  (LABEL_TAC "outer_adjoined") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `v:A`;
      `outer:real^2->bool`; `newouter:real^2->bool`]
     PLANE_GRAPH_DELETE_VERTEX_COMPONENT_ADJOINS_POINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:A->real^2) v IN newouter`
  (LABEL_TAC "v_newouter") THENL
   [USE_THEN "outer_adjoined"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[INSERT_SUBSET]);
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `u:A` THEN
  DISCH_THEN(LABEL_TAC "u_newface") THEN
  USE_THEN "u_newface" MP_TAC THEN
  REWRITE_TAC[plane_graph_face_vertices; IN_ELIM_THM] THEN
  INTRO_TAC "u_delete u_frontier" THEN
  USE_THEN "u_delete" MP_TAC THEN
  REWRITE_TAC[IN_DELETE] THEN INTRO_TAC "u_vertex distinct" THEN
  ASM_CASES_TAC `(u:A) IN graph_neighbors E v` THENL
   [REWRITE_TAC[IN_UNION] THEN DISJ2_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `v:A`;
    `newouter:real^2->bool`; `u:A`]
   PLANE_GRAPH_DELETE_VERTEX_NEW_FACE_VERTEX_OLD_FACE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@k. k_component k_subset u_oldface" THEN
  SUBGOAL_THEN
   `v IN plane_graph_face_vertices (V:A->bool) E p c k`
  (LABEL_TAC "v_oldface") THENL
   [ASM_CASES_TAC
     `v IN plane_graph_face_vertices (V:A->bool) E p c k` THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `k:real^2->bool`; `v:A`]
     PLANE_TRIANGULATED_DISK_NONINCIDENT_FACE_PERSISTS) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "k_newcomponent _" THEN
    SUBGOAL_THEN `~((k:real^2->bool) = {})`
    (LABEL_TAC "k_nonempty") THENL
     [USE_THEN "k_component"
       (ACCEPT_TAC o MATCH_MP IN_COMPONENTS_NONEMPTY);
      ALL_TAC] THEN
    SUBGOAL_THEN `(k:real^2->bool) = newouter`
    (LABEL_TAC "k_newouter") THENL
     [MP_TAC(ISPECL
       [`(:real^2) DIFF
         plane_graph_carrier ((V:A->bool) DELETE (v:A))
          (induced_subgraph_edges (E:(A->bool)->bool)
            ((V:A->bool) DELETE (v:A)))
          (p:A->real^2) (c:(A->bool)->real^2->bool)`;
        `k:real^2->bool`; `newouter:real^2->bool`]
       COMPONENTS_EQ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MATCH_MP_TAC(snd(EQ_IMP_RULE th))) THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["k_nonempty"; "k_subset"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(p:A->real^2) v IN plane_graph_carrier V E p c`
    (LABEL_TAC "v_oldcarrier") THENL
     [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (ISPECL
        [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
         `c:(A->bool)->real^2->bool`]
        PLANE_GRAPH_CARRIER_VERTEX_SUBSET)) THEN
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `v:A` THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "k_component" (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["v_newouter"; "k_newouter"; "v_oldcarrier"] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `k:real^2->bool`; `u:A`; `v:A`]
   PLANE_TRIANGULATED_DISK_COMMON_FACE_ADJACENT_OR_BOUNDARY) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "adjacent_or_boundary") THEN
  SUBGOAL_THEN `~({u:A,v} IN E)` (LABEL_TAC "not_edge") THENL
   [DISCH_THEN(LABEL_TAC "edge") THEN
    SUBGOAL_THEN `(u:A) IN graph_neighbors E v`
    (LABEL_TAC "neighbor") THENL
