    ALL_TAC] THEN
  MAP_EVERY (fun name -> USE_THEN name MP_TAC)
   ["adjacent_or_boundary"; "not_edge"; "distinct"; "v_boundary"] THEN
  POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[]);;

let PLANE_TRIANGULATED_DISK_DELETE_VERTEX_FACE_VERTICES = prove
 (`!V E p c q n outer v newouter.
