let FINITE_SIMPLE_GRAPH_EDGE_THROUGH_MEMBER = prove
 (`!V E e v:A.
        finite_simple_graph V E /\ e IN E /\ v IN e
        ==> ?u. v IN V /\ u IN V /\ ~(u = v) /\ e = {v,u}`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge v_edge" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`]
   FINITE_SIMPLE_GRAPH_EDGE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@a b. a_vertex b_vertex distinct edge_pair" THEN
  ASM_CASES_TAC `(v:A) = a` THENL
   [EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN `(v:A) = b` (LABEL_TAC "v_b") THENL
     [USE_THEN "v_edge" MP_TAC THEN
      USE_THEN "edge_pair" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN ASM_MESON_TAC[];
      EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[PAIR_SET_SYM]]]);;

let PLANE_GRAPH_EMBEDDING_EDGE_INTER_DELETE_VERTEX_CARRIER = prove
 (`!V E p c e v.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e IN E /\ v IN e
        ==> c e INTER
            plane_graph_carrier (V DELETE v)
              (induced_subgraph_edges E (V DELETE v)) p c =
            IMAGE p (e DELETE v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph embedding edge v_edge" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`; `v:A`]
   FINITE_SIMPLE_GRAPH_EDGE_THROUGH_MEMBER) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@u. v_vertex u_vertex distinct edge_pair" THEN
  SUBGOAL_THEN
   `induced_subgraph_edges (E:(A->bool)->bool)
      ((V:A->bool) DELETE (v:A)) SUBSET E DELETE e`
  (LABEL_TAC "edges_subset") THENL
   [REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES; IN_DELETE] THEN
    X_GEN_TAC `d:A->bool` THEN INTRO_TAC "d_edge d_subset" THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "d_subset"
     (MP_TAC o SPEC `v:A` o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_INSERT];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_carrier ((V:A->bool) DELETE (v:A))
      (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
      (p:A->real^2) (c:(A->bool)->real^2->bool) SUBSET
    plane_graph_carrier V (E DELETE e) p c`
  (LABEL_TAC "carrier_subset") THENL
   [MATCH_MP_TAC PLANE_GRAPH_CARRIER_MONO THEN
    ASM_REWRITE_TAC[DELETE_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) e INTER
    plane_graph_carrier (V:A->bool) (E DELETE e) (p:A->real^2) c =
    IMAGE p e`
  (LABEL_TAC "edge_remainder") THENL
   [MATCH_MP_TAC PLANE_GRAPH_EMBEDDING_EDGE_INTER_DELETE_CARRIER THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((p:A->real^2) v IN
      plane_graph_carrier ((V:A->bool) DELETE (v:A))
       (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
       (p:A->real^2) (c:(A->bool)->real^2->bool))`
  (LABEL_TAC "v_outside") THENL
   [MATCH_MP_TAC
     PLANE_GRAPH_EMBEDDING_DELETE_VERTEX_POINT_OUTSIDE_CARRIER THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:A->real^2) u IN
    plane_graph_carrier ((V:A->bool) DELETE (v:A))
      (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
      (p:A->real^2) (c:(A->bool)->real^2->bool)`
  (LABEL_TAC "u_newcarrier") THENL
   [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
     (ISPECL
      [`(V:A->bool) DELETE (v:A)`;
       `induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v)`;
       `p:A->real^2`; `c:(A->bool)->real^2->bool`]
      PLANE_GRAPH_CARRIER_VERTEX_SUBSET)) THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `u:A` THEN
    ASM_REWRITE_TAC[IN_DELETE];
    ALL_TAC] THEN
  SUBGOAL_THEN `(e:A->bool) DELETE (v:A) = {u:A}`
  (LABEL_TAC "remaining") THENL
   [USE_THEN "edge_pair" SUBST1_TAC THEN
