    USE_THEN "distinct" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "remaining" (fun th -> REWRITE_TAC[th; IMAGE_CLAUSES]) THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INTER; IN_SING] THEN
    X_GEN_TAC `x:real^2` THEN INTRO_TAC "x_edge x_newcarrier" THEN
    SUBGOAL_THEN `(x:real^2) IN IMAGE (p:A->real^2) (e:A->bool)`
    (LABEL_TAC "x_endpoint") THENL
     [USE_THEN "edge_remainder" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[IN_INTER] THEN CONJ_TAC THENL
       [USE_THEN "x_edge" ACCEPT_TAC;
        USE_THEN "carrier_subset"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "x_newcarrier" ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "x_endpoint" MP_TAC THEN
    USE_THEN "edge_pair" (fun th -> REWRITE_TAC[th; IMAGE_CLAUSES]) THEN
    REWRITE_TAC[IN_INSERT; IN_SING] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "x_v")
      (LABEL_TAC "x_u")) THENL
     [USE_THEN "x_v" SUBST_ALL_TAC THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["v_outside"; "x_newcarrier"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[];
      USE_THEN "x_u" ACCEPT_TAC];
    REWRITE_TAC[SING_SUBSET; IN_INTER] THEN CONJ_TAC THENL
     [SUBGOAL_THEN
       `(p:A->real^2) u IN (c:(A->bool)->real^2->bool) e INTER
