        REWRITE_TAC[IN_INTER] THEN
        INTRO_TAC "u_edge _" THEN USE_THEN "u_edge" ACCEPT_TAC];
      USE_THEN "u_newcarrier" ACCEPT_TAC]]);;

let PLANE_GRAPH_DELETE_VERTEX_INCIDENT_EDGE_REMAINDER_CONNECTED = prove
 (`!V E p c e v.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e IN E /\ v IN e
        ==> connected
             (c e DIFF
              plane_graph_carrier (V DELETE v)
               (induced_subgraph_edges E (V DELETE v)) p c)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph embedding edge v_edge" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`; `v:A`]
   FINITE_SIMPLE_GRAPH_EDGE_THROUGH_MEMBER) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@u. v_vertex u_vertex distinct edge_pair" THEN
  SUBGOAL_THEN `(e:A->bool) DELETE (v:A) = {u:A}`
  (LABEL_TAC "remaining") THENL
   [USE_THEN "edge_pair" SUBST1_TAC THEN
    MATCH_MP_TAC(SET_RULE `~(u = v) ==> {v,u} DELETE v = {u}`) THEN
    USE_THEN "distinct" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) e INTER
    plane_graph_carrier ((V:A->bool) DELETE (v:A))
      (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v)) p c =
    {(p:A->real^2) u}`
  (LABEL_TAC "edge_intersection") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`; `v:A`]
     PLANE_GRAPH_EMBEDDING_EDGE_INTER_DELETE_VERTEX_CARRIER) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "remaining" (fun th -> REWRITE_TAC[th; IMAGE_CLAUSES]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) e DIFF
    plane_graph_carrier ((V:A->bool) DELETE (v:A))
      (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v)) p c =
    c e DELETE (p u)`
  (LABEL_TAC "removed_edge") THENL
   [USE_THEN "edge_intersection" MP_TAC THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
    ALL_TAC] THEN
  USE_THEN "embedding" MP_TAC THEN
  REWRITE_TAC[plane_graph_embedding] THEN
  INTRO_TAC "_ edge_paths _ _" THEN
  REMOVE_THEN "edge_paths" (MP_TAC o SPEC `e:A->bool`) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@g. arc edge_image endpoints" THEN
  SUBGOAL_THEN `(p:A->real^2) u IN path_image g`
  (LABEL_TAC "u_path") THENL
   [SUBGOAL_THEN
     `(p:A->real^2) u IN {pathstart g,pathfinish g}`
    (LABEL_TAC "u_endpoint") THENL
     [USE_THEN "endpoints" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "edge_pair"
       (fun th -> REWRITE_TAC[th; IMAGE_CLAUSES;
                              IN_INSERT; IN_SING]);
      ALL_TAC] THEN
    USE_THEN "u_endpoint" MP_TAC THEN
    REWRITE_TAC[IN_INSERT; IN_SING] THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
    REWRITE_TAC[PATHSTART_IN_PATH_IMAGE; PATHFINISH_IN_PATH_IMAGE];
    ALL_TAC] THEN
  USE_THEN "removed_edge" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "edge_image" (fun th -> REWRITE_TAC[GSYM th]) THEN
  MATCH_MP_TAC(snd(EQ_IMP_RULE(MATCH_MP
   (ISPECL [`g:real^1->real^2`; `(p:A->real^2) u`]
     CONNECTED_ARC_IMAGE_DELETE)
   (CONJ (ASSUME `arc(g:real^1->real^2)`)
         (ASSUME `(p:A->real^2) u IN path_image g`))))) THEN
  USE_THEN "endpoints" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "edge_pair"
   (fun th -> REWRITE_TAC[th; IMAGE_CLAUSES; IN_INSERT; IN_SING]));;

let PLANE_GRAPH_EMBEDDING_EDGE_MEMBER_POINT = prove
 (`!V E p c e v.
        plane_graph_embedding (V:A->bool) E p c /\
        e IN E /\ v IN e
        ==> (p:A->real^2) v IN c e`,
  REPEAT GEN_TAC THEN INTRO_TAC "embedding edge v_edge" THEN
  USE_THEN "embedding" MP_TAC THEN
  REWRITE_TAC[plane_graph_embedding] THEN
  INTRO_TAC "_ edge_paths _ _" THEN
  REMOVE_THEN "edge_paths" (MP_TAC o SPEC `e:A->bool`) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@g. _ edge_image endpoints" THEN
  USE_THEN "edge_image" (fun th -> REWRITE_TAC[GSYM th]) THEN
  SUBGOAL_THEN
   `(p:A->real^2) v IN {pathstart g,pathfinish g}` MP_TAC THENL
   [USE_THEN "endpoints" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `v:A` THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[IN_INSERT; IN_SING] THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
    REWRITE_TAC[PATHSTART_IN_PATH_IMAGE; PATHFINISH_IN_PATH_IMAGE]]);;

let PLANE_GRAPH_DELETE_VERTEX_REMOVED_CARRIER_SUBSET_COMPONENT = prove
 (`!V E p c v l.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        v IN V /\
        l IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        (p:A->real^2) v IN l
        ==> plane_graph_carrier V E p c DIFF
            plane_graph_carrier (V DELETE v)
              (induced_subgraph_edges E (V DELETE v)) p c
            SUBSET l`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding v_vertex component v_component" THEN
  REWRITE_TAC[SUBSET; IN_DIFF] THEN X_GEN_TAC `x:real^2` THEN
  INTRO_TAC "x_oldcarrier x_outside" THEN
  USE_THEN "x_oldcarrier" MP_TAC THEN
  REWRITE_TAC[plane_graph_carrier; IN_UNION] THEN
  DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "x_vertex")
    (LABEL_TAC "x_edges")) THENL
   [USE_THEN "x_vertex" MP_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@w. x_w w_vertex" THEN
    ASM_CASES_TAC `(w:A) = v` THENL
     [USE_THEN "x_w" SUBST1_TAC THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN
       `(p:A->real^2) w IN
        plane_graph_carrier ((V:A->bool) DELETE (v:A))
          (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
          (p:A->real^2) (c:(A->bool)->real^2->bool)`
      (LABEL_TAC "w_newcarrier") THENL
       [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
         (ISPECL
          [`(V:A->bool) DELETE (v:A)`;
           `induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v)`;
           `p:A->real^2`; `c:(A->bool)->real^2->bool`]
          PLANE_GRAPH_CARRIER_VERTEX_SUBSET)) THEN
        REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `w:A` THEN
        ASM_REWRITE_TAC[IN_DELETE];
        SUBGOAL_THEN
         `(x:real^2) IN
          plane_graph_carrier ((V:A->bool) DELETE (v:A))
            (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
            (p:A->real^2) (c:(A->bool)->real^2->bool)`
        (LABEL_TAC "x_newcarrier") THENL
         [USE_THEN "x_w" SUBST1_TAC THEN
          USE_THEN "w_newcarrier" ACCEPT_TAC;
          ALL_TAC] THEN
        USE_THEN "x_outside" (fun nth ->
          USE_THEN "x_newcarrier" (fun th ->
            CONTR_TAC(MP (NOT_ELIM nth) th)))]];
    USE_THEN "x_edges" MP_TAC THEN
    REWRITE_TAC[UNIONS_IMAGE; IN_ELIM_THM] THEN
    INTRO_TAC "@e. e_edge x_edge" THEN
    ASM_CASES_TAC `(v:A) IN e` THENL
     [SUBGOAL_THEN
       `connected
        ((c:(A->bool)->real^2->bool) e DIFF
         plane_graph_carrier ((V:A->bool) DELETE (v:A))
          (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
          (p:A->real^2) (c:(A->bool)->real^2->bool))`
      (LABEL_TAC "removed_connected") THENL
       [MATCH_MP_TAC
         PLANE_GRAPH_DELETE_VERTEX_INCIDENT_EDGE_REMAINDER_CONNECTED THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(p:A->real^2) v IN
        (c:(A->bool)->real^2->bool) e DIFF
        plane_graph_carrier ((V:A->bool) DELETE (v:A))
          (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
          (p:A->real^2) (c:(A->bool)->real^2->bool)`
      (LABEL_TAC "v_removed_edge") THENL
       [REWRITE_TAC[IN_DIFF] THEN CONJ_TAC THENL
         [MATCH_MP_TAC(ISPECL
           [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
            `c:(A->bool)->real^2->bool`; `e:A->bool`; `v:A`]
           PLANE_GRAPH_EMBEDDING_EDGE_MEMBER_POINT) THEN
          ASM_REWRITE_TAC[];
          MATCH_MP_TAC
           PLANE_GRAPH_EMBEDDING_DELETE_VERTEX_POINT_OUTSIDE_CARRIER THEN
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(c:(A->bool)->real^2->bool) e DIFF
        plane_graph_carrier ((V:A->bool) DELETE (v:A))
          (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
          (p:A->real^2) (c:(A->bool)->real^2->bool) SUBSET l`
      (LABEL_TAC "removed_subset") THENL
       [MATCH_MP_TAC(ISPECL
         [`(:real^2) DIFF
           plane_graph_carrier ((V:A->bool) DELETE (v:A))
            (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
            (p:A->real^2) (c:(A->bool)->real^2->bool)`;
          `l:real^2->bool`;
          `(c:(A->bool)->real^2->bool) e DIFF
           plane_graph_carrier ((V:A->bool) DELETE (v:A))
            (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
            (p:A->real^2) (c:(A->bool)->real^2->bool)`]
         CONNECTED_SUBSET_OF_COMPONENT) THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "component" ACCEPT_TAC;
          USE_THEN "removed_connected" ACCEPT_TAC;
          REWRITE_TAC[SUBSET; IN_DIFF; IN_UNIV] THEN
          X_GEN_TAC `y:real^2` THEN
          INTRO_TAC "_ y_outside" THEN USE_THEN "y_outside" ACCEPT_TAC;
          REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
          EXISTS_TAC `(p:A->real^2) v` THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      USE_THEN "removed_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      ASM_REWRITE_TAC[IN_DIFF];
      SUBGOAL_THEN `(e:A->bool) SUBSET V`
      (LABEL_TAC "edge_subset") THENL
       [USE_THEN "graph" MP_TAC THEN
        REWRITE_TAC[finite_simple_graph] THEN
        INTRO_TAC "_ _ edges" THEN
        USE_THEN "edges" (fun th ->
          USE_THEN "e_edge" (fun eth ->
            MP_TAC(MATCH_MP (SPEC `e:A->bool` th) eth))) THEN
        INTRO_TAC "edge_subset _" THEN USE_THEN "edge_subset" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(e:A->bool) SUBSET V DELETE v`
      (LABEL_TAC "edge_delete") THENL
       [REWRITE_TAC[SUBSET; IN_DELETE] THEN X_GEN_TAC `y:A` THEN
        DISCH_THEN(LABEL_TAC "y_edge") THEN CONJ_TAC THENL
         [USE_THEN "edge_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          USE_THEN "y_edge" ACCEPT_TAC;
          DISCH_THEN(LABEL_TAC "y_v") THEN
          USE_THEN "y_v" SUBST_ALL_TAC THEN
          USE_THEN "y_edge" MP_TAC THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(e:A->bool) IN induced_subgraph_edges E (V DELETE v)`
      (LABEL_TAC "new_edge") THENL
       [REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(c:(A->bool)->real^2->bool) e SUBSET
        plane_graph_carrier ((V:A->bool) DELETE (v:A))
          (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
          (p:A->real^2) (c:(A->bool)->real^2->bool)`
      (LABEL_TAC "edge_carrier") THENL
       [MATCH_MP_TAC PLANE_GRAPH_CARRIER_EDGE_SUBSET THEN
        USE_THEN "new_edge" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(x:real^2) IN
        plane_graph_carrier ((V:A->bool) DELETE (v:A))
          (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
          (p:A->real^2) (c:(A->bool)->real^2->bool)`
      (LABEL_TAC "x_newcarrier") THENL
       [USE_THEN "edge_carrier" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "x_edge" ACCEPT_TAC;
        USE_THEN "x_outside" (fun nth ->
          USE_THEN "x_newcarrier" (fun th ->
            CONTR_TAC(MP (NOT_ELIM nth) th)))]]]);;

(* Every other complementary component survives restoring the vertex.       *)

let PLANE_GRAPH_DELETE_VERTEX_OTHER_COMPONENT_PERSISTS = prove
 (`!V E p c v newouter l.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        v IN V /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        (p:A->real^2) v IN newouter /\
        l IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        ~(l = newouter)
        ==> l IN components
             ((:real^2) DIFF plane_graph_carrier V E p c)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding v_vertex newouter_component v_newouter \
    component distinct" THEN
  ABBREV_TAC
   `oldcarrier = plane_graph_carrier (V:A->bool) E p c` THEN
  ABBREV_TAC
   `newcarrier = plane_graph_carrier ((V:A->bool) DELETE (v:A))
      (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v)) p c` THEN
  SUBGOAL_THEN `(newcarrier:real^2->bool) SUBSET oldcarrier`
  (LABEL_TAC "carrier_subset") THENL
   [EXPAND_TAC "newcarrier" THEN EXPAND_TAC "oldcarrier" THEN
    MATCH_MP_TAC PLANE_GRAPH_CARRIER_MONO THEN
    ASM_REWRITE_TAC[DELETE_SUBSET] THEN
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(oldcarrier:real^2->bool) DIFF newcarrier SUBSET newouter`
  (LABEL_TAC "removed_subset") THENL
   [EXPAND_TAC "oldcarrier" THEN EXPAND_TAC "newcarrier" THEN
    MATCH_MP_TAC
     PLANE_GRAPH_DELETE_VERTEX_REMOVED_CARRIER_SUBSET_COMPONENT THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(l:real^2->bool) INTER newouter = {}`
  (LABEL_TAC "components_disjoint") THENL
   [MP_TAC(ISPECL
     [`(:real^2) DIFF (newcarrier:real^2->bool)`;
      `l:real^2->bool`; `newouter:real^2->bool`]
     COMPONENTS_EQ) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(l:real^2->bool) SUBSET (:real^2) DIFF oldcarrier`
  (LABEL_TAC "l_old_complement") THENL
   [REWRITE_TAC[SUBSET; IN_DIFF; IN_UNIV] THEN
    X_GEN_TAC `x:real^2` THEN DISCH_THEN(LABEL_TAC "x_l") THEN
    SUBGOAL_THEN `~((x:real^2) IN newcarrier)`
    (LABEL_TAC "x_not_newcarrier") THENL
     [USE_THEN "component" (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
      REWRITE_TAC[SUBSET; IN_DIFF; IN_UNIV] THEN
      DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(LABEL_TAC "x_oldcarrier") THEN
    SUBGOAL_THEN `(x:real^2) IN oldcarrier DIFF newcarrier`
    (LABEL_TAC "x_removed") THENL
     [ASM_REWRITE_TAC[IN_DIFF];
      ALL_TAC] THEN
    SUBGOAL_THEN `(x:real^2) IN newouter`
    (LABEL_TAC "x_newouter") THENL
     [USE_THEN "removed_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "x_removed" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(x:real^2) IN l INTER newouter`
    (LABEL_TAC "x_intersection") THENL
     [ASM_REWRITE_TAC[IN_INTER];
      USE_THEN "components_disjoint" (fun th ->
        USE_THEN "x_intersection" MP_TAC THEN
        REWRITE_TAC[th; NOT_IN_EMPTY])];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`l:real^2->bool`;
    `(:real^2) DIFF (oldcarrier:real^2->bool)`;
    `(:real^2) DIFF (newcarrier:real^2->bool)`]
   COMPONENTS_INTERMEDIATE_SUBSET) THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "carrier_subset" MP_TAC THEN SET_TAC[]);;

let PLANE_TRIANGULATED_DISK_DELETE_VERTEX_OTHER_FACE_TRIANGULAR = prove
 (`!V E p c q n outer v newouter l.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        v IN cyclic_vertices q n /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        outer SUBSET newouter /\
        (p:A->real^2) v IN newouter /\
        l IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        ~(l = newouter)
        ==> ?r:num->A.
              plane_graph_face_vertices (V DELETE v)
                (induced_subgraph_edges E (V DELETE v)) p c l =
                cyclic_vertices r 3 /\
              simple_graph_cycle
                (induced_subgraph_edges E (V DELETE v)) r 3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk v_boundary newouter_component outer_subset v_newouter \
    component distinct" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding _ _ _ boundary_subset outer_component boundary" THEN
  SUBGOAL_THEN `(v:A) IN V` (LABEL_TAC "v_vertex") THENL
   [USE_THEN "boundary_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "v_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(l:real^2->bool) IN components
    ((:real^2) DIFF
     plane_graph_carrier (V:A->bool) (E:(A->bool)->bool)
       (p:A->real^2) (c:(A->bool)->real^2->bool))`
  (LABEL_TAC "old_component") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `v:A`;
      `newouter:real^2->bool`; `l:real^2->bool`]
     PLANE_GRAPH_DELETE_VERTEX_OTHER_COMPONENT_PERSISTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((l:real^2->bool) = {})`
  (LABEL_TAC "l_nonempty") THENL
   [USE_THEN "component" (ACCEPT_TAC o MATCH_MP IN_COMPONENTS_NONEMPTY);
    ALL_TAC] THEN
  SUBGOAL_THEN `(l:real^2->bool) INTER newouter = {}`
  (LABEL_TAC "components_disjoint") THENL
   [MP_TAC(ISPECL
     [`(:real^2) DIFF
       plane_graph_carrier ((V:A->bool) DELETE (v:A))
        (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
        (p:A->real^2) (c:(A->bool)->real^2->bool)`;
      `l:real^2->bool`; `newouter:real^2->bool`]
     COMPONENTS_EQ) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(v IN plane_graph_face_vertices (V:A->bool) E p c l)`
  (LABEL_TAC "v_not_face") THENL
   [DISCH_THEN(LABEL_TAC "v_face") THEN
    SUBGOAL_THEN
     `(l:real^2->bool) SUBSET newouter`
    (LABEL_TAC "l_subset_newouter") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `v:A`;
        `outer:real^2->bool`; `newouter:real^2->bool`;
        `l:real^2->bool`]
       PLANE_GRAPH_DELETE_VERTEX_INCIDENT_COMPONENT_SUBSET) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "boundary" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "v_boundary" ACCEPT_TAC;
      ALL_TAC] THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["l_nonempty"; "l_subset_newouter"; "components_disjoint"] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((l:real^2->bool) = outer)`
  (LABEL_TAC "not_outer") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "v_not_face" MP_TAC THEN
    USE_THEN "boundary" (fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "disk" MP_TAC THEN
  REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC "_ _ _ _ _ _ all_faces" THEN
  USE_THEN "all_faces" (fun th ->
    USE_THEN "old_component" (fun cth ->
      USE_THEN "not_outer" (fun nth ->
        MP_TAC(MATCH_MP (SPEC `l:real^2->bool` th)
          (CONJ cth nth))))) THEN
  INTRO_TAC "@r. old_face old_cycle" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `l:real^2->bool`; `v:A`]
   PLANE_TRIANGULATED_DISK_NONINCIDENT_FACE_PERSISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "face_restrict") THEN
  SUBGOAL_THEN
   `cyclic_vertices (r:num->A) 3 SUBSET V DELETE v`
  (LABEL_TAC "face_vertices_delete") THENL
   [SUBGOAL_THEN
    `plane_graph_face_vertices (V:A->bool) E p c l SUBSET V`
    (LABEL_TAC "face_vertices") THENL
     [ACCEPT_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `l:real^2->bool`]
       PLANE_GRAPH_FACE_VERTICES_SUBSET);
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["old_face"; "face_vertices"; "v_not_face"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `r:num->A` THEN CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    USE_THEN "old_cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN
    INTRO_TAC "large injective old_edges" THEN
    REWRITE_TAC[simple_graph_cycle] THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "cycle_edge") THEN
    CONJ_TAC THENL
     [USE_THEN "old_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "cycle_edge" ACCEPT_TAC;
      X_GEN_TAC `y:A` THEN DISCH_THEN(LABEL_TAC "y_edge") THEN
      USE_THEN "face_vertices_delete"
       (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (MATCH_MP
        (SPECL [`r:num->A`; `3`; `e:A->bool`]
         CYCLIC_EDGE_SUBSET_VERTICES)
        (CONJ (ARITH_RULE `0 < 3`)
              (ASSUME `(e:A->bool) IN cyclic_edges r 3`)))) THEN
      USE_THEN "y_edge" ACCEPT_TAC]]);;

let PLANE_TRIANGULATED_DISK_DELETE_VERTEX = prove
 (`!V E p c q n outer v newouter r m.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        v IN cyclic_vertices q n /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        outer SUBSET newouter /\
        (p:A->real^2) v IN newouter /\
        plane_graph_face_vertices (V DELETE v)
          (induced_subgraph_edges E (V DELETE v)) p c newouter =
          cyclic_vertices r m /\
        simple_graph_cycle
          (induced_subgraph_edges E (V DELETE v)) r m
        ==> plane_triangulated_disk
              (V DELETE v)
              (induced_subgraph_edges E (V DELETE v))
              p c r m newouter`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk v_boundary newouter_component outer_subset v_newouter \
    new_boundary new_cycle" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding _ _ _ _ _ _" THEN
  SUBGOAL_THEN `(v:A) IN V` (LABEL_TAC "v_vertex") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`]
     PLANE_TRIANGULATED_DISK_BOUNDARY_SUBSET) THEN
    ASM_REWRITE_TAC[SUBSET] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    USE_THEN "v_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `3 <= m` (LABEL_TAC "new_large") THENL
   [USE_THEN "new_cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[plane_triangulated_disk] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `(V:A->bool) DELETE (v:A)`]
     FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH) THEN
    ASM_REWRITE_TAC[DELETE_SUBSET];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `(V:A->bool) DELETE (v:A)`]
     PLANE_GRAPH_EMBEDDING_INDUCED_SUBGRAPH) THEN
    ASM_REWRITE_TAC[DELETE_SUBSET];
    USE_THEN "new_large" ACCEPT_TAC;
    USE_THEN "new_cycle" ACCEPT_TAC;
    USE_THEN "newouter_component" ACCEPT_TAC;
    USE_THEN "new_boundary" ACCEPT_TAC;
    X_GEN_TAC `l:real^2->bool` THEN
    INTRO_TAC "component distinct" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `v:A`; `newouter:real^2->bool`;
      `l:real^2->bool`]
     PLANE_TRIANGULATED_DISK_DELETE_VERTEX_OTHER_FACE_TRIANGULAR) THEN
    ASM_REWRITE_TAC[]]);;

let CYCLIC_VERTICES_CYCLIC_DELETE_LAST = prove
 (`!q w:num->A. !n k.
        3 <= n /\
        INJ q (cyclic_indices n) (:A) /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0
        ==> cyclic_vertices (cyclic_delete_last q w n) (n - 1 + k) =
            cyclic_vertices q n DELETE q (n - 1) UNION
            cyclic_vertices w (k + 2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "nlarge q_injective first last" THEN
  REWRITE_TAC[EXTENSION; IN_UNION; IN_DELETE; IN_CYCLIC_VERTICES] THEN
  X_GEN_TAC `x:A` THEN EQ_TAC THENL
   [INTRO_TAC "@i. index point" THEN
    USE_THEN "point" SUBST1_TAC THEN
    ASM_CASES_TAC `(i:num) < n - 1` THENL
     [DISJ1_TAC THEN CONJ_TAC THENL
        [EXISTS_TAC `i:num` THEN CONJ_TAC THENL
         [ASM_ARITH_TAC;
          MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN
          USE_THEN "index" MP_TAC THEN ASM_ARITH_TAC];
        DISCH_THEN(LABEL_TAC "equal_last") THEN
        MAP_EVERY (fun name -> USE_THEN name MP_TAC)
         ["nlarge"; "q_injective"; "equal_last"] THEN
        MP_TAC(MATCH_MP
         (SPECL [`q:num->A`; `w:num->A`; `n:num`; `i:num`]
          CYCLIC_DELETE_LAST_PREFIX)
         (ASSUME `(i:num) < n - 1`)) THEN
        MP_TAC(ASSUME `(i:num) < n - 1`) THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN
        REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
        MESON_TAC[ARITH_RULE
         `3 <= n /\ i < n - 1
          ==> i < n /\ n - 1 < n /\ ~(i = n - 1)`]];
      DISJ2_TAC THEN
      EXISTS_TAC `i - (n - 2)` THEN CONJ_TAC THENL
       [USE_THEN "index" MP_TAC THEN ASM_ARITH_TAC;
        REWRITE_TAC[cyclic_delete_last] THEN ASM_REWRITE_TAC[]]];
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "old")
      (LABEL_TAC "chain")) THENL
     [USE_THEN "old" MP_TAC THEN
      INTRO_TAC "(@i. old_index old_point) not_last" THEN
      SUBGOAL_THEN `(i:num) < n - 1` (LABEL_TAC "before_last") THENL
       [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
         ["old_index"; "old_point"; "not_last"] THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN
        MESON_TAC[ARITH_RULE
         `i < n /\ ~(i = n - 1) ==> i < n - 1`];
        ALL_TAC] THEN
      EXISTS_TAC `i:num` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        USE_THEN "old_point" (fun th -> REWRITE_TAC[th]) THEN
        CONV_TAC SYM_CONV THEN
        MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN
        USE_THEN "before_last" ACCEPT_TAC];
      USE_THEN "chain" MP_TAC THEN
      INTRO_TAC "@r. chain_index chain_point" THEN
      ASM_CASES_TAC `(r:num) = 0` THENL
       [EXISTS_TAC `n - 2` THEN CONJ_TAC THENL
         [ASM_ARITH_TAC;
          USE_THEN "chain_point" (fun th -> REWRITE_TAC[th]) THEN
          ASM_REWRITE_TAC[] THEN
          CONV_TAC SYM_CONV THEN
          MATCH_MP_TAC CYCLIC_DELETE_LAST_PENULTIMATE THEN
          USE_THEN "nlarge" ACCEPT_TAC];
        ALL_TAC] THEN
      ASM_CASES_TAC `(r:num) = k + 1` THENL
       [EXISTS_TAC `0` THEN CONJ_TAC THENL
         [ASM_ARITH_TAC;
          USE_THEN "chain_point" (fun th -> REWRITE_TAC[th]) THEN
          ASM_REWRITE_TAC[] THEN
          CONV_TAC SYM_CONV THEN
          MATCH_MP_TAC CYCLIC_DELETE_LAST_FIRST THEN
          USE_THEN "nlarge" ACCEPT_TAC];
        EXISTS_TAC `n - 2 + r` THEN CONJ_TAC THENL
         [ASM_ARITH_TAC;
          USE_THEN "chain_point" (fun th -> REWRITE_TAC[th]) THEN
          CONV_TAC SYM_CONV THEN
          MATCH_MP_TAC CYCLIC_DELETE_LAST_CHAIN THEN
          ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]]]]);;

let BOUNDARY_NEIGHBORS_OF_LAST_WITHOUT_CHORD = prove
 (`!V E q:num->A. !n.
        finite_simple_graph V E /\
        simple_graph_cycle E q n /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q (n - 1)} IN E))
        ==> graph_neighbors E (q (n - 1)) INTER cyclic_vertices q n =
            {q (n - 2),q 0}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph cycle chordless" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "nlarge injective boundary_edges" THEN
  SUBGOAL_THEN
   `(q:num->A) (n - 2) IN graph_neighbors E (q (n - 1))`
  (LABEL_TAC "previous_neighbor") THENL
   [REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
    USE_THEN "boundary_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `n - 2` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      SUBGOAL_THEN `(n - 2) + 1 = n - 1` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `(n - 1) MOD n = n - 1` SUBST1_TAC THENL
         [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
          SET_TAC[]]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:num->A) 0 IN graph_neighbors E (q (n - 1))`
  (LABEL_TAC "first_neighbor") THENL
   [REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
    USE_THEN "boundary_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `n - 1` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[MOD_REFL]]];
    ALL_TAC] THEN
  REWRITE_TAC[EXTENSION; IN_INTER; IN_INSERT; IN_SING] THEN
  X_GEN_TAC `u:A` THEN EQ_TAC THENL
   [INTRO_TAC "neighbor boundary" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`; `u:A`]
     BOUNDARY_NEIGHBOR_OF_LAST_WITHOUT_CHORD) THEN
    ASM_REWRITE_TAC[simple_graph_cycle];
    DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
    ASM_REWRITE_TAC[IN_CYCLIC_VERTICES] THENL
     [EXISTS_TAC `n - 2` THEN ASM_ARITH_TAC;
      EXISTS_TAC `0` THEN ASM_ARITH_TAC]]);;

let INJ_CYCLIC_DELETE_LAST = prove
 (`!q w:num->A. !n k.
        3 <= n /\
        INJ q (cyclic_indices n) (:A) /\
        INJ w (cyclic_indices (k + 2)) (:A) /\
        cyclic_vertices q n INTER cyclic_vertices w (k + 2) =
          {q (n - 2),q 0} /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0
        ==> INJ (cyclic_delete_last q w n)
              (cyclic_indices (n - 1 + k)) (:A)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "nlarge q_injective w_injective intersection first last" THEN
  SUBGOAL_THEN
   `!i r. i < n - 1 /\ 0 < r /\ r < k + 1
          ==> ~((q:num->A) i = w r)`
  (LABEL_TAC "separate") THENL
   [MAP_EVERY X_GEN_TAC [`i:num`; `r:num`] THEN
    INTRO_TAC "i_index r_positive r_index" THEN
    DISCH_THEN(LABEL_TAC "same") THEN
    SUBGOAL_THEN
     `(q:num->A) i IN
      cyclic_vertices q n INTER cyclic_vertices w (k + 2)`
    (LABEL_TAC "common") THENL
     [REWRITE_TAC[IN_INTER; IN_CYCLIC_VERTICES] THEN CONJ_TAC THENL
       [EXISTS_TAC `i:num` THEN ASM_ARITH_TAC;
        EXISTS_TAC `r:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
      ALL_TAC] THEN
    USE_THEN "common" MP_TAC THEN
    USE_THEN "intersection" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_INSERT; IN_SING] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "previous")
      (LABEL_TAC "next")) THENL
     [SUBGOAL_THEN `(w:num->A) r = w 0`
      (LABEL_TAC "same_w") THENL
       [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
         ["first"; "same"; "previous"] THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[];
        ALL_TAC] THEN
      MP_TAC(CONJUNCT2(REWRITE_RULE[INJ]
       (ASSUME `INJ (w:num->A) (cyclic_indices (k + 2)) (:A)`))) THEN
      DISCH_THEN(MP_TAC o SPECL [`r:num`; `0`]) THEN
      ANTS_TAC THENL
       [REWRITE_TAC[IN_CYCLIC_INDICES] THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        DISCH_THEN(LABEL_TAC "r_zero") THEN ASM_ARITH_TAC];
      SUBGOAL_THEN `(w:num->A) r = w (k + 1)`
      (LABEL_TAC "same_w") THENL
       [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
         ["last"; "same"; "next"] THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[];
        ALL_TAC] THEN
      MP_TAC(CONJUNCT2(REWRITE_RULE[INJ]
       (ASSUME `INJ (w:num->A) (cyclic_indices (k + 2)) (:A)`))) THEN
      DISCH_THEN(MP_TAC o SPECL [`r:num`; `k + 1`]) THEN
      ANTS_TAC THENL
       [REWRITE_TAC[IN_CYCLIC_INDICES] THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        DISCH_THEN(LABEL_TAC "r_last") THEN ASM_ARITH_TAC]];
    ALL_TAC] THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
  INTRO_TAC "i_index j_index same" THEN
  ASM_CASES_TAC `(i:num) < n - 1` THENL
   [SUBGOAL_THEN
     `cyclic_delete_last (q:num->A) w n i = q i`
    (LABEL_TAC "i_value") THENL
     [MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_CASES_TAC `(j:num) < n - 1` THENL
     [SUBGOAL_THEN
       `cyclic_delete_last (q:num->A) w n j = q j`
      (LABEL_TAC "j_value") THENL
       [MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(q:num->A) i = q j`
      (LABEL_TAC "same_q") THENL
       [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
         ["i_value"; "j_value"; "same"] THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[];
        ALL_TAC] THEN
      MP_TAC(CONJUNCT2(REWRITE_RULE[INJ]
       (ASSUME `INJ (q:num->A) (cyclic_indices n) (:A)`))) THEN
      DISCH_THEN(MP_TAC o SPECL [`i:num`; `j:num`]) THEN
      ANTS_TAC THENL
       [REWRITE_TAC[IN_CYCLIC_INDICES] THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        DISCH_THEN ACCEPT_TAC];
      SUBGOAL_THEN
       `0 < j - (n - 2) /\ j - (n - 2) < k + 1`
      (CONJUNCTS_THEN2 (LABEL_TAC "r_positive")
        (LABEL_TAC "r_index")) THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `cyclic_delete_last (q:num->A) w n j =
        w (j - (n - 2))`
      (LABEL_TAC "j_value") THENL
       [REWRITE_TAC[cyclic_delete_last] THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(q:num->A) i = w (j - (n - 2))`
      (LABEL_TAC "mixed_equal") THENL
       [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
         ["i_value"; "j_value"; "same"] THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[];
        ALL_TAC] THEN
      USE_THEN "separate" (fun th ->
        LABEL_TAC "different"
         (MATCH_MP (SPECL [`i:num`; `j - (n - 2)`] th)
          (CONJ (ASSUME `(i:num) < n - 1`)
           (CONJ (ASSUME `0 < j - (n - 2)`)
             (ASSUME `j - (n - 2) < k + 1`))))) THEN
      USE_THEN "different" (fun nth ->
        USE_THEN "mixed_equal" (fun eth ->
          CONTR_TAC(MP (NOT_ELIM nth) eth)))];
    SUBGOAL_THEN
     `0 < i - (n - 2) /\ i - (n - 2) < k + 1`
    (CONJUNCTS_THEN2 (LABEL_TAC "r_positive")
      (LABEL_TAC "r_index")) THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `cyclic_delete_last (q:num->A) w n i =
      w (i - (n - 2))`
    (LABEL_TAC "i_value") THENL
     [REWRITE_TAC[cyclic_delete_last] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_CASES_TAC `(j:num) < n - 1` THENL
     [SUBGOAL_THEN
       `cyclic_delete_last (q:num->A) w n j = q j`
      (LABEL_TAC "j_value") THENL
       [MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(q:num->A) j = w (i - (n - 2))`
      (LABEL_TAC "mixed_equal") THENL
       [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
         ["i_value"; "j_value"; "same"] THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[];
        ALL_TAC] THEN
      USE_THEN "separate" (fun th ->
        LABEL_TAC "different"
         (MATCH_MP (SPECL [`j:num`; `i - (n - 2)`] th)
          (CONJ (ASSUME `(j:num) < n - 1`)
           (CONJ (ASSUME `0 < i - (n - 2)`)
             (ASSUME `i - (n - 2) < k + 1`))))) THEN
      USE_THEN "different" (fun nth ->
        USE_THEN "mixed_equal" (fun eth ->
          CONTR_TAC(MP (NOT_ELIM nth) eth)));
      SUBGOAL_THEN
       `0 < j - (n - 2) /\ j - (n - 2) < k + 1`
      (CONJUNCTS_THEN2 (LABEL_TAC "s_positive")
        (LABEL_TAC "s_index")) THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `cyclic_delete_last (q:num->A) w n j =
        w (j - (n - 2))`
      (LABEL_TAC "j_value") THENL
       [REWRITE_TAC[cyclic_delete_last] THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `i = n - 2 + (i - (n - 2)) /\
        j = n - 2 + (j - (n - 2))`
      (CONJUNCTS_THEN2 (LABEL_TAC "i_recover")
        (LABEL_TAC "j_recover")) THENL
       [CONJ_TAC THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(w:num->A) (i - (n - 2)) = w (j - (n - 2))`
      (LABEL_TAC "same_w") THENL
       [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
         ["i_value"; "j_value"; "same"] THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[];
        ALL_TAC] THEN
      MP_TAC(CONJUNCT2(REWRITE_RULE[INJ]
       (ASSUME `INJ (w:num->A) (cyclic_indices (k + 2)) (:A)`))) THEN
      DISCH_THEN(MP_TAC o SPECL
       [`i - (n - 2)`; `j - (n - 2)`]) THEN
      ANTS_TAC THENL
       [REWRITE_TAC[IN_CYCLIC_INDICES] THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        DISCH_THEN(LABEL_TAC "same_index") THEN ASM_ARITH_TAC]]]);;

let SIMPLE_GRAPH_CYCLE_CYCLIC_DELETE_LAST = prove
 (`!E:(A->bool)->bool. !q w:num->A. !n k.
        simple_graph_cycle E q n /\
        3 <= n - 1 + k /\
        INJ w (cyclic_indices (k + 2)) (:A) /\
        cyclic_vertices q n INTER cyclic_vertices w (k + 2) =
          {q (n - 2),q 0} /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0 /\
        (!r. r + 1 < k + 2 ==> {w r,w(r + 1)} IN E)
        ==> simple_graph_cycle E (cyclic_delete_last q w n) (n - 1 + k)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "cycle newlarge w_injective intersection first last chain" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "nlarge q_injective boundary_edges" THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  REPEAT CONJ_TAC THENL
   [ASM_ARITH_TAC;
    MATCH_MP_TAC INJ_CYCLIC_DELETE_LAST THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC CYCLIC_EDGES_SUBSET_OF_CHAIN_AND_LAST THEN
    REPEAT CONJ_TAC THENL
     [ASM_ARITH_TAC;
      X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
      ASM_CASES_TAC `(i:num) + 1 < n - 1` THENL
       [SUBGOAL_THEN
         `cyclic_delete_last (q:num->A) w n i = q i /\
          cyclic_delete_last q w n (i + 1) = q (i + 1)`
        (CONJUNCTS_THEN2 (LABEL_TAC "i_value")
          (LABEL_TAC "next_value")) THENL
         [CONJ_TAC THEN MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN
          ASM_ARITH_TAC;
          ALL_TAC] THEN
        ASM_REWRITE_TAC[] THEN
        USE_THEN "boundary_edges"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        REWRITE_TAC[IN_CYCLIC_EDGES] THEN
        EXISTS_TAC `i:num` THEN CONJ_TAC THENL
         [ASM_ARITH_TAC;
          SUBGOAL_THEN `(i + 1) MOD n = i + 1` SUBST1_TAC THENL
           [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
            REFL_TAC]];
        ASM_CASES_TAC `(i:num) < n - 1` THENL
         [SUBGOAL_THEN `(i:num) = n - 2`
          (LABEL_TAC "seam") THENL
           [ASM_ARITH_TAC;
            ALL_TAC] THEN
          SUBGOAL_THEN
           `cyclic_delete_last (q:num->A) w n i = w 0 /\
            cyclic_delete_last q w n (i + 1) = w 1`
          (CONJUNCTS_THEN2 (LABEL_TAC "i_value")
            (LABEL_TAC "next_value")) THENL
           [CONJ_TAC THENL
             [USE_THEN "seam" SUBST1_TAC THEN
              ASM_SIMP_TAC[CYCLIC_DELETE_LAST_PENULTIMATE];
              USE_THEN "seam" SUBST1_TAC THEN
              ACCEPT_TAC(MATCH_MP
               (SPECL [`q:num->A`; `w:num->A`; `n:num`; `1`]
               CYCLIC_DELETE_LAST_CHAIN)
               (CONJ (ASSUME `3 <= n`) (ARITH_RULE `0 < 1`)))];
            USE_THEN "i_value" (fun th -> REWRITE_TAC[th]) THEN
            USE_THEN "next_value" (fun th -> REWRITE_TAC[th]) THEN
            SUBGOAL_THEN `0 + 1 < k + 2`
            (LABEL_TAC "first_bound") THENL
             [ASM_ARITH_TAC;
              USE_THEN "chain" (fun th ->
                ACCEPT_TAC(REWRITE_RULE[ADD_CLAUSES]
                 (MATCH_MP (SPEC `0` th)
                  (ASSUME `0 + 1 < k + 2`))))]];
          SUBGOAL_THEN
           `0 < i - (n - 2) /\
            i - (n - 2) + 1 < k + 2`
          (CONJUNCTS_THEN2 (LABEL_TAC "r_positive")
            (LABEL_TAC "r_bound")) THENL
           [ASM_ARITH_TAC;
            ALL_TAC] THEN
          SUBGOAL_THEN
           `cyclic_delete_last (q:num->A) w n i =
              w (i - (n - 2)) /\
            cyclic_delete_last q w n (i + 1) =
              w (i - (n - 2) + 1)`
          (CONJUNCTS_THEN2 (LABEL_TAC "i_value")
            (LABEL_TAC "next_value")) THENL
           [REWRITE_TAC[cyclic_delete_last] THEN
            ASM_REWRITE_TAC[] THEN
            AP_TERM_TAC THEN ASM_ARITH_TAC;
            ASM_REWRITE_TAC[] THEN
            USE_THEN "chain"
             (MATCH_MP_TAC o SPEC `i - (n - 2)`) THEN
            USE_THEN "r_bound" ACCEPT_TAC]]];
      SUBGOAL_THEN `(n - 1 + k) - 1 = n - 2 + k` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `cyclic_delete_last (q:num->A) w n (n - 2 + k) = w k`
      (LABEL_TAC "last_value") THENL
       [ASM_CASES_TAC `(k:num) = 0` THENL
         [ASM_SIMP_TAC[ADD_CLAUSES; CYCLIC_DELETE_LAST_PENULTIMATE];
          MATCH_MP_TAC CYCLIC_DELETE_LAST_CHAIN THEN
          CONJ_TAC THENL
           [USE_THEN "nlarge" ACCEPT_TAC;
            ASM_ARITH_TAC]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `cyclic_delete_last (q:num->A) w n 0 = w (k + 1)`
      (LABEL_TAC "first_value") THENL
       [ASM_SIMP_TAC[CYCLIC_DELETE_LAST_FIRST];
        ALL_TAC] THEN
      USE_THEN "last_value" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "first_value" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "chain" (MATCH_MP_TAC o SPEC `k:num`) THEN
      ASM_ARITH_TAC]]);;

let cyclic_reverse = new_definition
 `cyclic_reverse (q:num->A) n i = q(n - 1 - i)`;;

let CYCLIC_VERTICES_REVERSE = prove
 (`!q:num->A. !n.
        cyclic_vertices (cyclic_reverse q n) n = cyclic_vertices q n`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[EXTENSION; IN_CYCLIC_VERTICES; cyclic_reverse] THEN
  X_GEN_TAC `x:A` THEN EQ_TAC THEN
  INTRO_TAC "@i. index point" THENL
   [EXISTS_TAC `n - 1 - i` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      USE_THEN "point" ACCEPT_TAC];
    EXISTS_TAC `n - 1 - i` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      USE_THEN "point" (fun th -> REWRITE_TAC[th]) THEN
      AP_TERM_TAC THEN ASM_ARITH_TAC]]);;

let INJ_CYCLIC_REVERSE = prove
 (`!q:num->A. !n.
        INJ q (cyclic_indices n) (:A)
        ==> INJ (cyclic_reverse q n) (cyclic_indices n) (:A)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[INJ; IN_CYCLIC_INDICES; IN_UNIV; cyclic_reverse] THEN
  DISCH_THEN(LABEL_TAC "injective") THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
  INTRO_TAC "i_index j_index same" THEN
  SUBGOAL_THEN
   `n - 1 - i < n /\ n - 1 - j < n`
  (CONJUNCTS_THEN2 (LABEL_TAC "i_reverse")
    (LABEL_TAC "j_reverse")) THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "injective"
   (MP_TAC o SPECL [`n - 1 - i`; `n - 1 - j`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(LABEL_TAC "same_reverse") THEN ASM_ARITH_TAC]);;

let CYCLIC_REVERSE_ENDPOINTS = prove
 (`!q:num->A. !n.
        0 < n
        ==> cyclic_reverse q n 0 = q(n - 1) /\
            cyclic_reverse q n (n - 1) = q 0`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "positive") THEN
  REWRITE_TAC[cyclic_reverse] THEN
  CONJ_TAC THEN AP_TERM_TAC THEN ASM_ARITH_TAC);;

let CYCLIC_REVERSE_CHAIN = prove
 (`!E:(A->bool)->bool. !q:num->A. !n.
        (!i. i + 1 < n ==> {q i,q(i + 1)} IN E)
        ==> !i. i + 1 < n
                ==> {cyclic_reverse q n i,
                     cyclic_reverse q n (i + 1)} IN E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "chain") THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
  REWRITE_TAC[cyclic_reverse] THEN
  SUBGOAL_THEN
   `(n - 1 - (i + 1)) + 1 < n`
  (LABEL_TAC "reverse_index") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "chain"
   (MP_TAC o SPEC `n - 1 - (i + 1)`) THEN
  ANTS_TAC THENL
   [USE_THEN "reverse_index" ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "reverse_edge")] THEN
  SUBGOAL_THEN
   `(n - 1 - (i + 1)) + 1 = n - 1 - i`
  (LABEL_TAC "successor") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "successor" (fun th -> REWRITE_TAC[GSYM th]) THEN
  ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
  USE_THEN "reverse_edge" ACCEPT_TAC);;

let NEIGHBOR_PATH_FROM_REVERSED_CYCLIC_CHAIN = prove
 (`!E:(A->bool)->bool. !v a b z m.
        2 <= m /\
        graph_neighbors E v = cyclic_vertices z m /\
        INJ z (cyclic_indices m) (:A) /\
        z 0 = b /\
        z (m - 1) = a /\
        (!i. i + 1 < m ==> {z i,z(i + 1)} IN E)
        ==> ?k w:num->A.
              m = k + 2 /\
              graph_neighbors E v = cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = a /\
              w (k + 1) = b /\
              (!i. i + 1 < k + 2 ==> {w i,w(i + 1)} IN E)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "large neighbors injective first last chain" THEN
  MAP_EVERY EXISTS_TAC
   [`m - 2`; `cyclic_reverse (z:num->A) m`] THEN
  SUBGOAL_THEN `(m:num) - 2 + 2 = m`
  (LABEL_TAC "length") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `0 < (m:num)` (LABEL_TAC "positive") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "length" (ACCEPT_TAC o SYM);
    USE_THEN "length" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[CYCLIC_VERTICES_REVERSE] THEN
    USE_THEN "neighbors" ACCEPT_TAC;
    USE_THEN "length" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC INJ_CYCLIC_REVERSE THEN
    USE_THEN "injective" ACCEPT_TAC;
    MP_TAC(MATCH_MP
     (SPECL [`z:num->A`; `m:num`] CYCLIC_REVERSE_ENDPOINTS)
     (ASSUME `0 < (m:num)`)) THEN
    INTRO_TAC "reverse_first _" THEN
    USE_THEN "reverse_first" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "last" ACCEPT_TAC;
    SUBGOAL_THEN `(m:num) - 2 + 1 = m - 1`
    (LABEL_TAC "last_index") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "last_index" (fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(MATCH_MP
     (SPECL [`z:num->A`; `m:num`] CYCLIC_REVERSE_ENDPOINTS)
     (ASSUME `0 < (m:num)`)) THEN
    INTRO_TAC "_ reverse_last" THEN
    USE_THEN "reverse_last" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "first" ACCEPT_TAC;
    USE_THEN "length" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC CYCLIC_REVERSE_CHAIN THEN
    USE_THEN "chain" ACCEPT_TAC]);;

let SIMPLE_GRAPH_CYCLE_INDUCED_SUBGRAPH = prove
 (`!E:(A->bool)->bool. !q:num->A. !n W.
        simple_graph_cycle E q n /\
        cyclic_vertices q n SUBSET W
        ==> simple_graph_cycle (induced_subgraph_edges E W) q n`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "(large injective edges) vertices" THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "large" ACCEPT_TAC;
    USE_THEN "injective" ACCEPT_TAC;
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "cycle_edge") THEN
    CONJ_TAC THENL
     [USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "cycle_edge" ACCEPT_TAC;
      REWRITE_TAC[SUBSET] THEN
      X_GEN_TAC `y:A` THEN DISCH_THEN(LABEL_TAC "y_edge") THEN
      USE_THEN "vertices" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (MATCH_MP
        (SPECL [`q:num->A`; `n:num`; `e:A->bool`]
         CYCLIC_EDGE_SUBSET_VERTICES)
        (CONJ (MATCH_MP (ARITH_RULE `3 <= n ==> 0 < n`)
                (ASSUME `3 <= n`))
              (ASSUME `(e:A->bool) IN cyclic_edges q n`)))) THEN
      USE_THEN "y_edge" ACCEPT_TAC]]);;

let FINITE_SIMPLE_GRAPH_NEIGHBORS_SUBSET_DELETE = prove
 (`!V E x:A.
        finite_simple_graph V E
        ==> graph_neighbors E x SUBSET V DELETE x`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  REWRITE_TAC[SUBSET; IN_DELETE] THEN
  X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "neighbor") THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `x:A`; `u:A`]
   FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "_ u_vertex distinct" THEN
  CONJ_TAC THENL
   [USE_THEN "u_vertex" ACCEPT_TAC;
    DISCH_THEN(fun reverse ->
      USE_THEN "distinct" (fun distinct ->
        CONTR_TAC(MP (NOT_ELIM distinct) (SYM reverse))))]);;

let PLANE_TRIANGULATED_DISK_DELETE_LAST_WITH_NEIGHBOR_PATH = prove
 (`!V E p c q n outer k w.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q (n - 1)} IN E)) /\
        3 <= n - 1 + k /\
        graph_neighbors E (q (n - 1)) = cyclic_vertices w (k + 2) /\
        INJ w (cyclic_indices (k + 2)) (:A) /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0 /\
        (!r. r + 1 < k + 2 ==> {w r,w(r + 1)} IN E)
        ==> ?newouter.
              plane_triangulated_disk
                (V DELETE q (n - 1))
                (induced_subgraph_edges E (V DELETE q (n - 1)))
                p c (cyclic_delete_last q w n) (n - 1 + k) newouter`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk chordless newlarge neighbors w_injective first last chain" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN
   `simple_graph_cycle (E:(A->bool)->bool) q n`
  (LABEL_TAC "cycle") THENL
   [REWRITE_TAC[simple_graph_cycle] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:num->A) (n - 1) IN cyclic_vertices q n`
  (LABEL_TAC "last_boundary") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
  `cyclic_vertices (q:num->A) n INTER cyclic_vertices w (k + 2) =
    {q (n - 2),q 0}`
  (LABEL_TAC "intersection") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`]
     BOUNDARY_NEIGHBORS_OF_LAST_WITHOUT_CHORD) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle (E:(A->bool)->bool)
      (cyclic_delete_last (q:num->A) (w:num->A) n) (n - 1 + k)`
  (LABEL_TAC "old_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DELETE_LAST THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
  `cyclic_vertices (cyclic_delete_last (q:num->A) w n) (n - 1 + k) =
    cyclic_vertices q n DELETE q (n - 1) UNION graph_neighbors E (q (n - 1))`
  (LABEL_TAC "new_vertices") THENL
   [MP_TAC(ISPECL [`q:num->A`; `w:num->A`; `n:num`; `k:num`]
     CYCLIC_VERTICES_CYCLIC_DELETE_LAST) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_vertices (cyclic_delete_last (q:num->A) w n) (n - 1 + k)
    SUBSET V DELETE q (n - 1)`
  (LABEL_TAC "new_vertices_subset") THENL
   [USE_THEN "new_vertices" (fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
    `graph_neighbors E ((q:num->A) (n - 1))
      SUBSET V DELETE q (n - 1)`
    (LABEL_TAC "neighbors_subset") THENL
     [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_NEIGHBORS_SUBSET_DELETE THEN
      USE_THEN "graph" ACCEPT_TAC;
      USE_THEN "boundary_subset" MP_TAC THEN
      USE_THEN "neighbors_subset" MP_TAC THEN SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle
     (induced_subgraph_edges (E:(A->bool)->bool)
       ((V:A->bool) DELETE (q:num->A) (n - 1)))
     (cyclic_delete_last (q:num->A) (w:num->A) n) (n - 1 + k)`
  (LABEL_TAC "new_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_INDUCED_SUBGRAPH THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `(q:num->A) (n - 1)`]
   PLANE_TRIANGULATED_DISK_DELETE_VERTEX_OUTER_COMPONENT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@newouter. newouter_component outer_subset last_newouter" THEN
  SUBGOAL_THEN
   `plane_graph_face_vertices (V DELETE q (n - 1))
      (induced_subgraph_edges E (V DELETE q (n - 1)))
      p c newouter =
    cyclic_vertices (cyclic_delete_last (q:num->A) w n) (n - 1 + k)`
  (LABEL_TAC "new_boundary") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `(q:num->A) (n - 1)`;
      `newouter:real^2->bool`]
     PLANE_TRIANGULATED_DISK_DELETE_VERTEX_FACE_VERTICES) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "new_vertices" (fun th -> REWRITE_TAC[GSYM th]);
    ALL_TAC] THEN
  EXISTS_TAC `newouter:real^2->bool` THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `(q:num->A) (n - 1)`;
    `newouter:real^2->bool`;
    `cyclic_delete_last (q:num->A) (w:num->A) n`;
    `n - 1 + k`]
   PLANE_TRIANGULATED_DISK_DELETE_VERTEX) THEN
  ASM_REWRITE_TAC[]);;

let SIMPLE_GRAPH_CYCLE_CONSECUTIVE_EDGE = prove
 (`!E:(A->bool)->bool. !q:num->A. !n i.
        simple_graph_cycle E q n /\ i + 1 < n
        ==> {q i,q(i + 1)} IN E`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "(_ _ edges) bound" THEN
  USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
  REWRITE_TAC[IN_CYCLIC_EDGES] THEN
  EXISTS_TAC `i:num` THEN CONJ_TAC THENL
   [ASM_ARITH_TAC;
    ASM_SIMP_TAC[MOD_LT]]);;

let SIMPLE_GRAPH_CYCLE_CLOSING_EDGE = prove
 (`!E:(A->bool)->bool. !q:num->A. !n.
        simple_graph_cycle E q n
        ==> {q (n - 1),q 0} IN E`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large _ edges" THEN
  USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
  REWRITE_TAC[IN_CYCLIC_EDGES] THEN
  EXISTS_TAC `n - 1` THEN CONJ_TAC THENL
   [ASM_ARITH_TAC;
    SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[MOD_REFL]]]);;

let PLANE_GRAPH_EMBEDDING_CYCLE_CHAIN_PATHS = prove
 (`!V E p c q n.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        simple_graph_cycle E q n
        ==> ?g:num->real^1->real^2.
              !i. i + 1 < n
                  ==> arc(g i) /\
                      path_image(g i) = c {q i,q(i + 1)} /\
                      pathstart(g i) = p(q i) /\
                      pathfinish(g i) = p(q(i + 1))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph embedding cycle" THEN
  REWRITE_TAC[GSYM SKOLEM_THM] THEN X_GEN_TAC `i:num` THEN
  ASM_CASES_TAC `i + 1 < n` THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `(q:num->A) i`;
      `(q:num->A)(i + 1)`]
     PLANE_GRAPH_EMBEDDING_DART_PATH) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN
      MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `i:num`]
       SIMPLE_GRAPH_CYCLE_CONSECUTIVE_EDGE) THEN
      ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `g:real^1->real^2`
       (LABEL_TAC "path")) THEN
      EXISTS_TAC `g:real^1->real^2` THEN ASM_REWRITE_TAC[]];
    EXISTS_TAC `linepath(vec 0:real^2,vec 0)` THEN ASM_REWRITE_TAC[]]);;

let SIMPLE_GRAPH_CYCLE_CHAIN_EDGE_NE_CLOSING = prove
 (`!E:(A->bool)->bool. !q:num->A. !n i.
        simple_graph_cycle E q n /\ i + 1 < n
        ==> ~({q i,q(i + 1)} = {q(n - 1),q 0})`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "(large injective _) bound" THEN
  SUBGOAL_THEN
   `!j k. j < n /\ k < n /\ (q:num->A) j = q k ==> j = k`
  (LABEL_TAC "index_injective") THENL
   [USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_CYCLIC_INDICES; IN_UNIV] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((q:num->A) i = q(i + 1))`
  (LABEL_TAC "chain_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same") THEN
    SUBGOAL_THEN `i = i + 1` MP_TAC THENL
     [USE_THEN "index_injective" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((q:num->A) (n - 1) = q 0)`
  (LABEL_TAC "closing_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same") THEN
    SUBGOAL_THEN `n - 1 = 0` MP_TAC THENL
     [USE_THEN "index_injective" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ASM_ARITH_TAC];
    DISCH_THEN(LABEL_TAC "edge_equal") THEN
    SUBGOAL_THEN
     `((q:num->A) i = q(n - 1) /\ q(i + 1) = q 0) \/
      (q i = q 0 /\ q(i + 1) = q(n - 1))`
    MP_TAC THENL
     [ASM SET_TAC[];
      DISCH_THEN(DISJ_CASES_THEN STRIP_ASSUME_TAC) THENL
       [SUBGOAL_THEN `i = n - 1` MP_TAC THENL
         [USE_THEN "index_injective" MATCH_MP_TAC THEN
          ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
          ASM_ARITH_TAC];
        SUBGOAL_THEN `i = 0` (LABEL_TAC "i_zero") THENL
         [USE_THEN "index_injective" MATCH_MP_TAC THEN
          ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
          ALL_TAC] THEN
        SUBGOAL_THEN `i + 1 = n - 1` MP_TAC THENL
         [USE_THEN "index_injective" MATCH_MP_TAC THEN
          ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
          ASM_ARITH_TAC]]]]);;

let SIMPLE_GRAPH_CYCLE_CHAIN_EDGES_DISTINCT = prove
 (`!E:(A->bool)->bool. !q:num->A. !n i j.
        simple_graph_cycle E q n /\ i + 1 < n /\ j + 1 < n /\ ~(i = j)
        ==> ~({q i,q(i + 1)} = {q j,q(j + 1)})`,
  REPEAT GEN_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "(_ injective _) i_bound j_bound indices_distinct" THEN
  SUBGOAL_THEN
   `!h k. h < n /\ k < n /\ (q:num->A) h = q k ==> h = k`
  (LABEL_TAC "index_injective") THENL
   [USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_CYCLIC_INDICES; IN_UNIV] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((q:num->A) i = q(i + 1))`
  (LABEL_TAC "i_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same") THEN
    SUBGOAL_THEN `i = i + 1` MP_TAC THENL
     [USE_THEN "index_injective" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((q:num->A) j = q(j + 1))`
  (LABEL_TAC "j_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same") THEN
    SUBGOAL_THEN `j = j + 1` MP_TAC THENL
     [USE_THEN "index_injective" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ARITH_TAC];
    ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "edges_equal") THEN
  SUBGOAL_THEN
   `((q:num->A) i = q j /\ q(i + 1) = q(j + 1)) \/
    (q i = q(j + 1) /\ q(i + 1) = q j)`
  MP_TAC THENL
   [USE_THEN "edges_equal" MP_TAC THEN ASM SET_TAC[];
    DISCH_THEN(DISJ_CASES_THEN STRIP_ASSUME_TAC) THENL
     [USE_THEN "indices_distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "index_injective" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      SUBGOAL_THEN `i = j + 1 /\ i + 1 = j` MP_TAC THENL
       [CONJ_TAC THENL
         [USE_THEN "index_injective" MATCH_MP_TAC THEN
          ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
          USE_THEN "index_injective" MATCH_MP_TAC THEN
          ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
        ARITH_TAC]]]);;

let PLANE_GRAPH_EMBEDDING_EDGE_ENDPOINT_MEMBER = prove
 (`!V E p c e v.
        plane_graph_embedding (V:A->bool) E p c /\
        e IN E /\ v IN e
        ==> p v IN c e`,
  REPEAT GEN_TAC THEN INTRO_TAC "embedding edge endpoint" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `e:A->bool`]
   PLANE_GRAPH_EMBEDDING_EDGE_ENDPOINTS) THEN
  ASM_REWRITE_TAC[SUBSET; IN_IMAGE] THEN
  DISCH_THEN MATCH_MP_TAC THEN EXISTS_TAC `v:A` THEN
  ASM_REWRITE_TAC[]);;

let PLANE_GRAPH_EMBEDDING_CYCLE_PREFIX_INTER_NEXT = prove
 (`!V E p c q n h.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        simple_graph_cycle E q n /\
        h + 2 < n
        ==> UNIONS(IMAGE (\i. c {q i,q(i + 1)}) (0..h)) INTER
            c {q(h + 1),q(h + 2)} = {p(q(h + 1))}`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph embedding cycle bound" THEN
  SUBGOAL_THEN
   `!j k. j < n /\ k < n /\ (q:num->A) j = q k ==> j = k`
  (LABEL_TAC "index_injective") THENL
   [USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
    INTRO_TAC "(_ injective _)" THEN
    USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_CYCLIC_INDICES; IN_UNIV] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{(q:num->A) (h + 1),q((h + 1) + 1)} IN E`
  (fun th -> LABEL_TAC "next_edge"
    (REWRITE_RULE[ARITH_RULE `(h + 1) + 1 = h + 2`] th)) THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `h + 1`]
     SIMPLE_GRAPH_CYCLE_CONSECUTIVE_EDGE) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INTER; IN_SING] THEN
    X_GEN_TAC `x:real^2` THEN INTRO_TAC "prefix next" THEN
    USE_THEN "prefix" MP_TAC THEN
    REWRITE_TAC[IN_UNIONS; IN_IMAGE] THEN
    INTRO_TAC "@s. (@i. set_eq index) x_in" THEN
    USE_THEN "set_eq" SUBST_ALL_TAC THEN
    SUBGOAL_THEN `i + 1 < n` (LABEL_TAC "edge_bound") THENL
     [USE_THEN "index" MP_TAC THEN REWRITE_TAC[IN_NUMSEG] THEN
      ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `{(q:num->A) i,q(i + 1)} IN E`
    (LABEL_TAC "edge") THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `i:num`]
       SIMPLE_GRAPH_CYCLE_CONSECUTIVE_EDGE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~({(q:num->A) i,q(i + 1)} = {q(h + 1),q((h + 1) + 1)})`
    (fun th -> LABEL_TAC "edges_distinct"
      (REWRITE_RULE[ARITH_RULE `(h + 1) + 1 = h + 2`] th)) THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `i:num`; `h + 1`]
       SIMPLE_GRAPH_CYCLE_CHAIN_EDGES_DISTINCT) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "index" MP_TAC THEN REWRITE_TAC[IN_NUMSEG] THEN
      ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(c:(A->bool)->real^2->bool) {q i,q(i + 1)} INTER
      c {q(h + 1),q(h + 2)} =
      IMAGE p ({q i,q(i + 1)} INTER {q(h + 1),q(h + 2)})`
    (LABEL_TAC "edge_intersection") THENL
     [USE_THEN "embedding" MP_TAC THEN
      REWRITE_TAC[plane_graph_embedding] THEN
      INTRO_TAC "_ _ _ intersections" THEN
      USE_THEN "intersections" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x:real^2) IN IMAGE (p:A->real^2)
       ({q i,q(i + 1)} INTER {q(h + 1),q(h + 2)})`
    (LABEL_TAC "x_intersection") THENL
     [USE_THEN "edge_intersection" (fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[IN_INTER];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{(q:num->A) i,q(i + 1)} INTER {q(h + 1),q(h + 2)}
      SUBSET {q(h + 1)}`
    (LABEL_TAC "vertex_intersection") THENL
     [SUBGOAL_THEN `~((q:num->A) i = q(h + 1))`
      (LABEL_TAC "first_not_next_start") THENL
       [DISCH_THEN(LABEL_TAC "same") THEN
        SUBGOAL_THEN `i = h + 1` MP_TAC THENL
         [USE_THEN "index_injective" MATCH_MP_TAC THEN
          ASM_REWRITE_TAC[] THEN
          USE_THEN "index" MP_TAC THEN REWRITE_TAC[IN_NUMSEG] THEN
          ASM_ARITH_TAC;
          USE_THEN "index" MP_TAC THEN REWRITE_TAC[IN_NUMSEG] THEN
          ARITH_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `~((q:num->A) i = q(h + 2))`
      (LABEL_TAC "first_not_next_finish") THENL
       [DISCH_THEN(LABEL_TAC "same") THEN
        SUBGOAL_THEN `i = h + 2` MP_TAC THENL
         [USE_THEN "index_injective" MATCH_MP_TAC THEN
          ASM_REWRITE_TAC[] THEN
          USE_THEN "index" MP_TAC THEN REWRITE_TAC[IN_NUMSEG] THEN
          ASM_ARITH_TAC;
          USE_THEN "index" MP_TAC THEN REWRITE_TAC[IN_NUMSEG] THEN
          ARITH_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `~((q:num->A) (i + 1) = q(h + 2))`
      (LABEL_TAC "finish_not_next_finish") THENL
       [DISCH_THEN(LABEL_TAC "same") THEN
        SUBGOAL_THEN `i + 1 = h + 2` MP_TAC THENL
         [USE_THEN "index_injective" MATCH_MP_TAC THEN
          ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
          USE_THEN "index" MP_TAC THEN REWRITE_TAC[IN_NUMSEG] THEN
          ARITH_TAC];
        ALL_TAC] THEN
      ASM SET_TAC[];
      ALL_TAC] THEN
    USE_THEN "x_intersection" MP_TAC THEN
    REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@u. u_in x_eq" THEN
    USE_THEN "vertex_intersection"
     (MP_TAC o SPEC `u:A` o REWRITE_RULE[SUBSET]) THEN
    ASM_REWRITE_TAC[IN_SING] THEN DISCH_THEN SUBST_ALL_TAC THEN
    REFL_TAC;
    REWRITE_TAC[SING_SUBSET; IN_INTER] THEN CONJ_TAC THENL
     [REWRITE_TAC[IN_UNIONS] THEN
      EXISTS_TAC `(c:(A->bool)->real^2->bool) {q h,q(h + 1)}` THEN
      CONJ_TAC THENL
       [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `h:num` THEN
        REWRITE_TAC[IN_NUMSEG] THEN ARITH_TAC;
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
          `c:(A->bool)->real^2->bool`; `{(q:num->A) h,q(h + 1)}`;
          `(q:num->A) (h + 1)`]
         PLANE_GRAPH_EMBEDDING_EDGE_ENDPOINT_MEMBER) THEN
        ASM_REWRITE_TAC[IN_INSERT; IN_SING] THEN
        MATCH_MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `h:num`]
         SIMPLE_GRAPH_CYCLE_CONSECUTIVE_EDGE) THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`;
        `{(q:num->A) (h + 1),q(h + 2)}`; `(q:num->A) (h + 1)`]
       PLANE_GRAPH_EMBEDDING_EDGE_ENDPOINT_MEMBER) THEN
      ASM_REWRITE_TAC[IN_INSERT] THEN
      USE_THEN "next_edge" ACCEPT_TAC]]);;

let PLANE_GRAPH_EMBEDDING_CYCLE_PREFIX_ARC = prove
 (`!V E p c q n.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        simple_graph_cycle E q n
        ==> !h. h + 1 < n
                  ==> ?a:real^1->real^2.
                        arc a /\
                        path_image a =
                          UNIONS
                           (IMAGE (\i. c {q i,q(i + 1)}) (0..h)) /\
                        pathstart a = p(q 0) /\
                        pathfinish a = p(q(h + 1))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph embedding cycle" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`]
   PLANE_GRAPH_EMBEDDING_CYCLE_CHAIN_PATHS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@g. paths" THEN
  MATCH_MP_TAC num_INDUCTION THEN CONJ_TAC THENL
   [DISCH_THEN(LABEL_TAC "bound") THEN
    USE_THEN "paths" (MP_TAC o SPEC `0`) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      INTRO_TAC "arc image start finish"] THEN
    EXISTS_TAC `(g:num->real^1->real^2) 0` THEN
    ASM_REWRITE_TAC[NUMSEG_SING; IMAGE_CLAUSES; UNIONS_1; ADD_CLAUSES];
    X_GEN_TAC `h:num` THEN DISCH_THEN(LABEL_TAC "induction") THEN
    DISCH_THEN(LABEL_TAC "bound") THEN
    USE_THEN "induction" MP_TAC THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      INTRO_TAC "@a. a_arc a_image a_start a_finish"] THEN
    USE_THEN "paths" (MP_TAC o SPEC `SUC h`) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      INTRO_TAC "g_arc g_image g_start g_finish"] THEN
    SUBGOAL_THEN
     `path_image(a:real^1->real^2) INTER
      path_image((g:num->real^1->real^2) (SUC h)) =
      {(p:A->real^2) (q(h + 1))}`
    (LABEL_TAC "intersection") THENL
     [USE_THEN "a_image" SUBST1_TAC THEN
      USE_THEN "g_image" SUBST1_TAC THEN
      REWRITE_TAC[ARITH_RULE `SUC h = h + 1`;
                  ARITH_RULE `(h + 1) + 1 = h + 2`] THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`; `h:num`]
       PLANE_GRAPH_EMBEDDING_CYCLE_PREFIX_INTER_NEXT) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `pathfinish(a:real^1->real^2) =
      pathstart((g:num->real^1->real^2) (SUC h))`
    (LABEL_TAC "joined") THENL
     [ASM_REWRITE_TAC[ARITH_RULE `SUC h = h + 1`];
      ALL_TAC] THEN
    EXISTS_TAC
     `(a:real^1->real^2) ++ (g:num->real^1->real^2) (SUC h)` THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC ARC_JOIN THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "intersection" (fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[ARITH_RULE `SUC h = h + 1`; SUBSET_REFL];
      ASM_SIMP_TAC[PATH_IMAGE_JOIN; NUMSEG_CLAUSES; LE_0;
                   IMAGE_CLAUSES; UNIONS_INSERT;
                   ARITH_RULE `SUC h = h + 1`; UNION_ACI];
      ASM_REWRITE_TAC[PATHSTART_JOIN];
      ASM_REWRITE_TAC[PATHFINISH_JOIN]]]);;

let PLANE_GRAPH_EMBEDDING_CYCLE_CHAIN_ENDPOINTS = prove
 (`!V E p c q n.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        simple_graph_cycle E q n
        ==> p(q 0) IN
              UNIONS(IMAGE (\i. c {q i,q(i + 1)}) (0..n - 2)) /\
            p(q(n - 1)) IN
              UNIONS(IMAGE (\i. c {q i,q(i + 1)}) (0..n - 2))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph embedding cycle" THEN
  SUBGOAL_THEN `3 <= n` (LABEL_TAC "large") THENL
   [USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[IN_UNIONS] THEN
    EXISTS_TAC `(c:(A->bool)->real^2->bool)
      {(q:num->A) 0,q(0 + 1)}` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `0` THEN
      REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `{(q:num->A) 0,q(0 + 1)}`;
        `(q:num->A) 0`]
       PLANE_GRAPH_EMBEDDING_EDGE_ENDPOINT_MEMBER) THEN
      ASM_REWRITE_TAC[IN_INSERT] THEN
      MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `0`]
       SIMPLE_GRAPH_CYCLE_CONSECUTIVE_EDGE) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
    REWRITE_TAC[IN_UNIONS] THEN
    EXISTS_TAC `(c:(A->bool)->real^2->bool)
      {(q:num->A) (n - 2),q((n - 2) + 1)}` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `n - 2` THEN
      REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC;
      SUBGOAL_THEN `(n - 2) + 1 = n - 1` (LABEL_TAC "index_eq") THENL
       [ASM_ARITH_TAC;
        USE_THEN "index_eq" (fun th -> REWRITE_TAC[th]) THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
          `c:(A->bool)->real^2->bool`;
          `{(q:num->A) (n - 2),q(n - 1)}`; `(q:num->A) (n - 1)`]
         PLANE_GRAPH_EMBEDDING_EDGE_ENDPOINT_MEMBER) THEN
        ASM_REWRITE_TAC[IN_INSERT; IN_SING] THEN
        USE_THEN "index_eq" (fun th -> REWRITE_TAC[GSYM th]) THEN
        MATCH_MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `n - 2`]
         SIMPLE_GRAPH_CYCLE_CONSECUTIVE_EDGE) THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]]]);;

let PLANE_GRAPH_EMBEDDING_CYCLE_CHAIN_INTER_CLOSING_SUBSET = prove
 (`!V E p c q n.
        finite_simple_graph (V:A->bool) E /\
