    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~({(q:num->A) i,q(i + 1)} = {q(n - 1),q 0})`
  (LABEL_TAC "edges_distinct") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `i:num`]
     SIMPLE_GRAPH_CYCLE_CHAIN_EDGE_NE_CLOSING) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) {q i,q(i + 1)} INTER
    c {q(n - 1),q 0} =
    IMAGE p ({q i,q(i + 1)} INTER {q(n - 1),q 0})`
  (LABEL_TAC "edge_intersection") THENL
   [USE_THEN "embedding" MP_TAC THEN
    REWRITE_TAC[plane_graph_embedding] THEN
    INTRO_TAC "_ _ _ intersections" THEN
    USE_THEN "intersections" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(x:real^2) IN IMAGE (p:A->real^2)
      ({(q:num->A) i,q(i + 1)} INTER {q(n - 1),q 0})`
  (LABEL_TAC "x_intersection") THENL
   [USE_THEN "edge_intersection" (fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[IN_INTER];
    USE_THEN "x_intersection" MP_TAC THEN
    REWRITE_TAC[IN_IMAGE; IN_INTER] THEN MESON_TAC[]]);;

let PLANE_GRAPH_EMBEDDING_CYCLE_CHAIN_INTER_CLOSING = prove
 (`!V E p c q n.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        simple_graph_cycle E q n
        ==> UNIONS(IMAGE (\i. c {q i,q(i + 1)}) (0..n - 2)) INTER
            c {q(n - 1),q 0} =
            {p(q 0),p(q(n - 1))}`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph embedding cycle" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`]
   PLANE_GRAPH_EMBEDDING_CYCLE_CHAIN_INTER_CLOSING_SUBSET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "intersection_subset") THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`]
   PLANE_GRAPH_EMBEDDING_CYCLE_CHAIN_ENDPOINTS) THEN
  ASM_REWRITE_TAC[] THEN INTRO_TAC "first_chain last_chain" THEN
  SUBGOAL_THEN `{(q:num->A) (n - 1),q 0} IN E`
  (LABEL_TAC "closing_edge") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CLOSING_EDGE THEN
    USE_THEN "cycle" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `{(q:num->A) (n - 1),q 0}`]
   PLANE_GRAPH_EMBEDDING_EDGE_ENDPOINTS) THEN
  ASM_REWRITE_TAC[IMAGE_CLAUSES] THEN
  DISCH_THEN(LABEL_TAC "closing_endpoints") THEN
  USE_THEN "intersection_subset" MP_TAC THEN
  USE_THEN "first_chain" MP_TAC THEN USE_THEN "last_chain" MP_TAC THEN
  USE_THEN "closing_endpoints" MP_TAC THEN SET_TAC[]);;

let CYCLIC_EDGES_CHAIN_CLOSING = prove
 (`!q:num->A. !n.
        3 <= n
        ==> cyclic_edges q n =
            IMAGE (\i. {q i,q(i + 1)}) (0..n - 2) UNION
            {{q(n - 1),q 0}}`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "large") THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `e:A->bool` THEN
  REWRITE_TAC[IN_CYCLIC_EDGES; IN_UNION; IN_IMAGE; IN_SING] THEN
  EQ_TAC THENL
   [INTRO_TAC "@i. index edge" THEN
    ASM_CASES_TAC `i < n - 1` THENL
     [DISJ1_TAC THEN EXISTS_TAC `i:num` THEN CONJ_TAC THENL
       [USE_THEN "edge" SUBST1_TAC THEN
        SUBGOAL_THEN `i + 1 < n` (LABEL_TAC "successor") THENL
         [ASM_ARITH_TAC;
          ASM_SIMP_TAC[MOD_LT]];
        REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC];
      DISJ2_TAC THEN
      SUBGOAL_THEN `i = n - 1` (LABEL_TAC "last") THENL
       [ASM_ARITH_TAC;
        USE_THEN "edge" SUBST1_TAC THEN
        USE_THEN "last" SUBST1_TAC THEN
        SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
         [ASM_ARITH_TAC;
          REWRITE_TAC[MOD_REFL]]]];
    DISCH_THEN(DISJ_CASES_THEN2
     (X_CHOOSE_THEN `i:num`
      (CONJUNCTS_THEN2 (LABEL_TAC "edge") (LABEL_TAC "index")))
     (LABEL_TAC "closing")) THENL
     [EXISTS_TAC `i:num` THEN
      USE_THEN "edge" SUBST1_TAC THEN
      USE_THEN "index" MP_TAC THEN REWRITE_TAC[IN_NUMSEG] THEN
      DISCH_THEN(LABEL_TAC "bound") THEN
      SUBGOAL_THEN `(i + 1) MOD n = i + 1`
      (LABEL_TAC "successor") THENL
       [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
      USE_THEN "closing" SUBST1_TAC THEN
      EXISTS_TAC `n - 1` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
         [ASM_ARITH_TAC;
          REWRITE_TAC[MOD_REFL]]]]]);;

let PLANE_GRAPH_CYCLE_CARRIER_DECOMPOSITION = prove
 (`!c:(A->bool)->B->bool. !q:num->A. !n.
        3 <= n
        ==> UNIONS(IMAGE c (cyclic_edges q n)) =
            UNIONS(IMAGE (\i. c {q i,q(i + 1)}) (0..n - 2)) UNION
            c {q(n - 1),q 0}`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "large") THEN
  MP_TAC(ISPECL [`q:num->A`; `n:num`] CYCLIC_EDGES_CHAIN_CLOSING) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[IMAGE_UNION; UNIONS_UNION; IMAGE_CLAUSES; UNIONS_1] THEN
  ONCE_REWRITE_TAC[GSYM IMAGE_o] THEN REWRITE_TAC[o_DEF]);;

let PLANE_GRAPH_EMBEDDING_SIMPLE_CYCLE_JORDAN_EXACT = prove
 (`!V E p c q n.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        simple_graph_cycle E q n
        ==> ?j:real^1->real^2.
              simple_path j /\
              pathfinish j = pathstart j /\
              path_image j = UNIONS(IMAGE c (cyclic_edges q n))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph embedding cycle" THEN
  SUBGOAL_THEN `3 <= n` (LABEL_TAC "large") THENL
   [USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`]
   PLANE_GRAPH_EMBEDDING_CYCLE_PREFIX_ARC) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `n - 2`) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    INTRO_TAC "@a. a_arc a_image a_start a_finish"] THEN
  SUBGOAL_THEN `n - 2 + 1 = n - 1`
  (LABEL_TAC "last_index") THENL
   [ASM_ARITH_TAC;
    RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `n - 2 + 1 = n - 1`])] THEN
  SUBGOAL_THEN `{(q:num->A) (n - 1),q 0} IN E`
  (LABEL_TAC "closing_edge") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CLOSING_EDGE THEN
    USE_THEN "cycle" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `(q:num->A) (n - 1)`;
    `(q:num->A) 0`]
   PLANE_GRAPH_EMBEDDING_DART_PATH) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    INTRO_TAC "@b. b_arc b_image b_start b_finish"] THEN
  SUBGOAL_THEN
   `path_image(a:real^1->real^2) INTER path_image b =
    {(p:A->real^2) (q 0),p(q(n - 1))}`
  (LABEL_TAC "intersection") THENL
   [USE_THEN "a_image" SUBST1_TAC THEN
    USE_THEN "b_image" SUBST1_TAC THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`]
     PLANE_GRAPH_EMBEDDING_CYCLE_CHAIN_INTER_CLOSING) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `UNIONS(IMAGE (c:(A->bool)->real^2->bool) (cyclic_edges q n)) =
    UNIONS(IMAGE (\i. c {q i,q(i + 1)}) (0..n - 2)) UNION
    c {q(n - 1),q 0}`
  (LABEL_TAC "decomposition") THENL
   [MATCH_MP_TAC PLANE_GRAPH_CYCLE_CARRIER_DECOMPOSITION THEN
    USE_THEN "large" ACCEPT_TAC;
    ALL_TAC] THEN
  EXISTS_TAC `(a:real^1->real^2) ++ b` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC SIMPLE_PATH_JOIN_LOOP THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "intersection" (fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[INSERT_AC; SUBSET_REFL];
    ASM_REWRITE_TAC[PATHSTART_JOIN; PATHFINISH_JOIN];
    ASM_SIMP_TAC[PATH_IMAGE_JOIN] THEN
    ASM_REWRITE_TAC[]]);;

let EDGE_IMAGE_UNIONS_SUBSET_PLANE_GRAPH_CARRIER = prove
 (`!V E p c F.
        F SUBSET (E:(A->bool)->bool)
        ==> UNIONS(IMAGE (c:(A->bool)->real^2->bool) F) SUBSET
            plane_graph_carrier (V:A->bool) E p c`,
  REPEAT GEN_TAC THEN REWRITE_TAC[plane_graph_carrier] THEN SET_TAC[]);;

let PLANE_TRIANGULATED_DISK_OUTER_JORDAN_SIDE = prove
 (`!V E p c q n outer.
        plane_triangulated_disk (V:A->bool) E p c q n outer
        ==> ?j:real^1->real^2.
              simple_path j /\
              pathfinish j = pathstart j /\
              path_image j = UNIONS(IMAGE c (cyclic_edges q n)) /\
              (outer SUBSET inside(path_image j) \/
               outer SUBSET outside(path_image j))`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "disk") THEN
  USE_THEN "disk" MP_TAC THEN REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC "graph embedding large cycle outer_component boundary faces" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`]
   PLANE_GRAPH_EMBEDDING_SIMPLE_CYCLE_JORDAN_EXACT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@j. simple closed image" THEN
  EXISTS_TAC `j:real^1->real^2` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `path_image(j:real^1->real^2) SUBSET
    plane_graph_carrier (V:A->bool) E p c`
  (LABEL_TAC "cycle_carrier_subset") THENL
   [USE_THEN "image" SUBST1_TAC THEN
    MATCH_MP_TAC EDGE_IMAGE_UNIONS_SUBSET_PLANE_GRAPH_CARRIER THEN
    USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(:real^2) DIFF plane_graph_carrier (V:A->bool) E p c SUBSET
    (:real^2) DIFF path_image j`
  (LABEL_TAC "complement_subset") THENL
   [USE_THEN "cycle_carrier_subset" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(:real^2) DIFF plane_graph_carrier (V:A->bool) E p c`;
    `(:real^2) DIFF path_image(j:real^1->real^2)`;
    `outer:real^2->bool`]
   COMPONENT_SUBSET_OF_SUPERSET_COMPONENT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@side. side_component outer_subset" THEN
  MP_TAC(ISPEC `j:real^1->real^2` JORDAN_COMPONENTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "components") THEN
  USE_THEN "side_component" MP_TAC THEN
  USE_THEN "components" (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[IN_INSERT; IN_SING] THEN
  DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN ASM_REWRITE_TAC[]);;

let OPEN_CONNECTED_SUBSET_EQ_OF_FRONTIER_DISJOINT = prove
 (`!s t:real^N->bool.
        connected s /\
        ~(t = {}) /\
        open t /\
        t SUBSET s /\
        frontier t INTER s = {}
        ==> t = s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "connected nonempty open subset frontier" THEN
  SUBGOAL_THEN
   `open_in (subtopology euclidean s) (t:real^N->bool)`
  (LABEL_TAC "relative_open") THENL
   [SUBGOAL_THEN `(s:real^N->bool) INTER t = t`
    (LABEL_TAC "intersection") THENL
     [USE_THEN "subset" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    MP_TAC(MATCH_MP
     (ISPECL [`s:real^N->bool`; `t:real^N->bool`] OPEN_IN_OPEN_INTER)
     (ASSUME `open(t:real^N->bool)`)) THEN
    USE_THEN "intersection" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(subtopology euclidean s) frontier_of (t:real^N->bool) = {}`
  (LABEL_TAC "relative_frontier") THENL
   [MP_TAC(ISPECL
     [`euclidean:(real^N)topology`; `s:real^N->bool`; `t:real^N->bool`]
     FRONTIER_OF_SUBSET_SUBTOPOLOGY) THEN
    MP_TAC(ISPECL
     [`euclidean:(real^N)topology`; `t:real^N->bool`; `s:real^N->bool`]
     FRONTIER_OF_SUBTOPOLOGY_SUBSET) THEN
    REWRITE_TAC[EUCLIDEAN_FRONTIER_OF] THEN
    USE_THEN "frontier" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `closed_in (subtopology euclidean s) (t:real^N->bool)`
  (LABEL_TAC "relative_closed") THENL
   [MP_TAC(ISPECL
     [`subtopology euclidean (s:real^N->bool)`; `t:real^N->bool`]
     CLOPEN_IN_EQ_FRONTIER_OF) THEN
    ASM_REWRITE_TAC
     [TOPSPACE_SUBTOPOLOGY; TOPSPACE_EUCLIDEAN; INTER_UNIV];
    ALL_TAC] THEN
  MP_TAC(REWRITE_RULE[CONNECTED_CLOPEN]
   (ASSUME `connected(s:real^N->bool)`)) THEN
  DISCH_THEN(MP_TAC o SPEC `t:real^N->bool`) THEN ASM_REWRITE_TAC[]);;

let PLANE_GRAPH_EMBEDDING_CYCLE_VERTICES_SUBSET_CARRIER = prove
 (`!V E p c q n.
        plane_graph_embedding (V:A->bool) E p c /\
        simple_graph_cycle E q n
        ==> IMAGE p (cyclic_vertices q n) SUBSET
            UNIONS(IMAGE c (cyclic_edges q n))`,
  REPEAT GEN_TAC THEN INTRO_TAC "embedding cycle" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective cycle_edges" THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `x:real^2` THEN
  REWRITE_TAC[IN_IMAGE] THEN
  INTRO_TAC "@v. point boundary" THEN
  USE_THEN "point" SUBST1_TAC THEN
  USE_THEN "boundary" MP_TAC THEN
  REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
  INTRO_TAC "@i. index vertex" THEN
  USE_THEN "vertex" SUBST1_TAC THEN
  ABBREV_TAC
   `e:A->bool = {q i,q((i + 1) MOD n)}` THEN
  SUBGOAL_THEN `(e:A->bool) IN cyclic_edges q n`
  (LABEL_TAC "cycle_edge") THENL
   [EXPAND_TAC "e" THEN REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(e:A->bool) IN E` (LABEL_TAC "edge") THENL
   [USE_THEN "cycle_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "cycle_edge" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[IN_UNIONS] THEN
  EXISTS_TAC `(c:(A->bool)->real^2->bool) e` THEN CONJ_TAC THENL
   [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `e:A->bool` THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`; `(q:num->A) i`]
     PLANE_GRAPH_EMBEDDING_EDGE_ENDPOINT_MEMBER) THEN
    ASM_REWRITE_TAC[] THEN EXPAND_TAC "e" THEN REWRITE_TAC[IN_INSERT]]);;

let PLANE_GRAPH_EMBEDDING_CHORDLESS_CYCLE_INDUCED_CARRIER = prove
 (`!V E p c q n.
        plane_graph_embedding (V:A->bool) E p c /\
        simple_graph_cycle E q n /\
        induced_subgraph_edges E (cyclic_vertices q n) =
          cyclic_edges q n
        ==> plane_graph_carrier
              (cyclic_vertices q n)
              (induced_subgraph_edges E (cyclic_vertices q n)) p c =
            UNIONS(IMAGE c (cyclic_edges q n))`,
  REPEAT GEN_TAC THEN INTRO_TAC "embedding cycle chordless" THEN
  REWRITE_TAC[plane_graph_carrier] THEN
  USE_THEN "chordless" (fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(SET_RULE
   `s SUBSET t ==> s UNION t = t`) THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`]
   PLANE_GRAPH_EMBEDDING_CYCLE_VERTICES_SUBSET_CARRIER) THEN
  ASM_REWRITE_TAC[]);;

let PLANE_TRIANGULATED_DISK_OUTER_EQ_JORDAN_SIDE = prove
 (`!V E p c q n outer.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        induced_subgraph_edges E (cyclic_vertices q n) =
          cyclic_edges q n
        ==> ?j:real^1->real^2.
              simple_path j /\
              pathfinish j = pathstart j /\
              path_image j = UNIONS(IMAGE c (cyclic_edges q n)) /\
              (outer = inside(path_image j) \/
               outer = outside(path_image j))`,
  REPEAT GEN_TAC THEN INTRO_TAC "disk chordless" THEN
  USE_THEN "disk" MP_TAC THEN REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC
   "graph embedding large cycle outer_component boundary faces" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_OUTER_JORDAN_SIDE) THEN
  ASM_REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC "@j. simple closed image outer_side" THEN
  SUBGOAL_THEN
   `frontier(outer:real^2->bool) SUBSET path_image j`
  (LABEL_TAC "outer_frontier") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`]
     PLANE_TRIANGULATED_DISK_OUTER_FRONTIER_SUBSET_INDUCED_CARRIER) THEN
    ASM_REWRITE_TAC[plane_triangulated_disk] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`]
     PLANE_GRAPH_EMBEDDING_CHORDLESS_CYCLE_INDUCED_CARRIER) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["image"; "chordless"] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((outer:real^2->bool) = {})`
  (LABEL_TAC "outer_nonempty") THENL
   [MATCH_MP_TAC(ISPECL
     [`(:real^2) DIFF plane_graph_carrier
       (V:A->bool) (E:(A->bool)->bool) (p:A->real^2)
       (c:(A->bool)->real^2->bool)`;
      `outer:real^2->bool`]
     IN_COMPONENTS_NONEMPTY) THEN
    USE_THEN "outer_component" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `open(outer:real^2->bool)` (LABEL_TAC "outer_open") THENL
   [MATCH_MP_TAC(ISPECL
     [`(:real^2) DIFF plane_graph_carrier
       (V:A->bool) (E:(A->bool)->bool) (p:A->real^2)
       (c:(A->bool)->real^2->bool)`;
      `outer:real^2->bool`]
     OPEN_COMPONENTS) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC OPEN_DIFF THEN REWRITE_TAC[OPEN_UNIV] THEN
    MATCH_MP_TAC PLANE_GRAPH_CARRIER_CLOSED THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPEC `j:real^1->real^2` JORDAN_INSIDE_OUTSIDE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "inside_nonempty inside_open inside_connected outside_nonempty \
    outside_open outside_connected inside_bounded outside_unbounded \
    sides_disjoint sides_union inside_frontier outside_frontier" THEN
  EXISTS_TAC `j:real^1->real^2` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "outer_side" MP_TAC THEN
  USE_THEN "image" (fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "outer_inside")
    (LABEL_TAC "outer_outside")) THENL
   [DISJ1_TAC THEN
    MATCH_MP_TAC OPEN_CONNECTED_SUBSET_EQ_OF_FRONTIER_DISJOINT THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "inside_connected" ACCEPT_TAC;
      USE_THEN "outer_nonempty" ACCEPT_TAC;
      USE_THEN "outer_open" ACCEPT_TAC;
      USE_THEN "outer_inside" ACCEPT_TAC;
      MP_TAC(ISPEC
       `UNIONS(IMAGE (c:(A->bool)->real^2->bool) (cyclic_edges q n))`
       INSIDE_NO_OVERLAP) THEN
      USE_THEN "outer_frontier" MP_TAC THEN
      USE_THEN "image" MP_TAC THEN SET_TAC[]];
    DISJ2_TAC THEN
    MATCH_MP_TAC OPEN_CONNECTED_SUBSET_EQ_OF_FRONTIER_DISJOINT THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "outside_connected" ACCEPT_TAC;
      USE_THEN "outer_nonempty" ACCEPT_TAC;
      USE_THEN "outer_open" ACCEPT_TAC;
      USE_THEN "outer_outside" ACCEPT_TAC;
      MP_TAC(ISPEC
       `UNIONS(IMAGE (c:(A->bool)->real^2->bool) (cyclic_edges q n))`
       OUTSIDE_NO_OVERLAP) THEN
      USE_THEN "outer_frontier" MP_TAC THEN
      USE_THEN "image" MP_TAC THEN SET_TAC[]]]);;

let SIMPLE_GRAPH_CYCLE_NO_CHORDS_EQ_INDUCED_EDGES = prove
 (`!V E q:num->A. !n.
        finite_simple_graph V E /\
        simple_graph_cycle E q n /\
        (!i j. i < n /\ j < n /\ {q i,q j} IN E
               ==> {q i,q j} IN cyclic_edges q n)
        ==> induced_subgraph_edges E (cyclic_vertices q n) =
            cyclic_edges q n`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph cycle no_chords" THEN
  USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective boundary_edges" THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN INTRO_TAC "edge boundary_subset" THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`]
     FINITE_SIMPLE_GRAPH_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@u v. u_vertex v_vertex distinct pair" THEN
    SUBGOAL_THEN
     `(u:A) IN cyclic_vertices q n /\
      (v:A) IN cyclic_vertices q n`
    (CONJUNCTS_THEN2 (LABEL_TAC "u_boundary")
      (LABEL_TAC "v_boundary")) THENL
     [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["boundary_subset"; "pair"] THEN SET_TAC[];
      ALL_TAC] THEN
    USE_THEN "u_boundary" MP_TAC THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    INTRO_TAC "@i. i_index u_point" THEN
    USE_THEN "v_boundary" MP_TAC THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    INTRO_TAC "@j. j_index v_point" THEN
    USE_THEN "pair" SUBST1_TAC THEN
    USE_THEN "no_chords" (MP_TAC o SPECL [`i:num`; `j:num`]) THEN
    ASM_MESON_TAC[];
    REWRITE_TAC[SUBSET] THEN
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "cycle_edge") THEN
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    CONJ_TAC THENL
     [USE_THEN "boundary_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "cycle_edge" ACCEPT_TAC;
      MATCH_MP_TAC CYCLIC_EDGE_SUBSET_VERTICES THEN
      CONJ_TAC THENL
       [ASM_ARITH_TAC;
        USE_THEN "cycle_edge" ACCEPT_TAC]]]);;

let SIMPLE_GRAPH_CYCLE_3_INDUCED_EDGES = prove
 (`!V E r:num->A.
        finite_simple_graph V E /\
        simple_graph_cycle E r 3
        ==> induced_subgraph_edges E (cyclic_vertices r 3) =
            cyclic_edges r 3`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph cycle" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:num->A`; `3`]
   SIMPLE_GRAPH_CYCLE_NO_CHORDS_EQ_INDUCED_EDGES) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
  INTRO_TAC "i_bound j_bound edge" THEN
  SUBGOAL_THEN `~((r:num->A) i = r j)` (LABEL_TAC "distinct") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `{(r:num->A) i,r j}:A->bool`]
     FINITE_SIMPLE_GRAPH_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@u v. u_vertex v_vertex uv_distinct pair" THEN
    DISCH_THEN(LABEL_TAC "same") THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["same"; "uv_distinct"; "pair"] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((i:num) = 0 \/ i = 1 \/ i = 2) /\
    ((j:num) = 0 \/ j = 1 \/ j = 2)`
  (LABEL_TAC "cases") THENL
   [ASM_ARITH_TAC;
    USE_THEN "cases"
     (CONJUNCTS_THEN2
      (REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC)
      (REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
    ASM_REWRITE_TAC
     [CYCLIC_EDGES_3; IN_INSERT; IN_SING; PAIR_SET_SYM] THEN
    ASM_MESON_TAC[]]);;

let OPEN_JORDAN_COMPLEMENT_COMPONENT_EQ_SIDE = prove
 (`!j:real^1->real^2. !k.
        simple_path j /\
        pathfinish j = pathstart j /\
        connected k /\
        ~(k = {}) /\
        open k /\
        k SUBSET (:real^2) DIFF path_image j /\
        frontier k SUBSET path_image j
        ==> frontier k = path_image j /\
            (k = inside(path_image j) \/
             k = outside(path_image j))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "simple closed k_connected k_nonempty k_open k_subset \
    frontier_subset" THEN
  MP_TAC(ISPEC `j:real^1->real^2` JORDAN_INSIDE_OUTSIDE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "inside_nonempty inside_open inside_connected outside_nonempty \
    outside_open outside_connected inside_bounded outside_unbounded \
    sides_disjoint sides_union inside_frontier outside_frontier" THEN
  SUBGOAL_THEN
   `(k:real^2->bool) = inside(path_image j) \/
    k = outside(path_image j)`
  (LABEL_TAC "side") THENL
   [MP_TAC(ISPECL
     [`path_image(j:real^1->real^2)`; `k:real^2->bool`]
     CONNECTED_SUBSET_INSIDE_OR_OUTSIDE) THEN
    ASM_SIMP_TAC[CLOSED_PATH_IMAGE; SIMPLE_PATH_IMP_PATH] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "inside_subset")
      (LABEL_TAC "outside_subset")) THENL
     [DISJ1_TAC THEN
      MATCH_MP_TAC(ISPECL
       [`inside(path_image(j:real^1->real^2))`; `k:real^2->bool`]
       OPEN_CONNECTED_SUBSET_EQ_OF_FRONTIER_DISJOINT) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "frontier_subset" MP_TAC THEN
      MP_TAC(ISPEC `path_image(j:real^1->real^2)` INSIDE_NO_OVERLAP) THEN
      SET_TAC[];
      DISJ2_TAC THEN
      MATCH_MP_TAC(ISPECL
       [`outside(path_image(j:real^1->real^2))`; `k:real^2->bool`]
       OPEN_CONNECTED_SUBSET_EQ_OF_FRONTIER_DISJOINT) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "frontier_subset" MP_TAC THEN
      MP_TAC(ISPEC `path_image(j:real^1->real^2)` OUTSIDE_NO_OVERLAP) THEN
      SET_TAC[]];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "side" (DISJ_CASES_THEN SUBST1_TAC) THEN
    ASM_REWRITE_TAC[];
    USE_THEN "side" ACCEPT_TAC]);;

let PLANE_GRAPH_EMBEDDING_TRIANGULAR_FACE_JORDAN_SIDE = prove
 (`!V E p c k r.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        plane_graph_face_vertices V E p c k = cyclic_vertices r 3 /\
        simple_graph_cycle E r 3
        ==> ?j:real^1->real^2.
              simple_path j /\
              pathfinish j = pathstart j /\
              path_image j = UNIONS(IMAGE c (cyclic_edges r 3)) /\
              frontier k = path_image j /\
              (k = inside(path_image j) \/
               k = outside(path_image j))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding component face_vertices cycle" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `r:num->A`; `3`]
   PLANE_GRAPH_EMBEDDING_SIMPLE_CYCLE_JORDAN_EXACT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@j. simple closed image" THEN
  SUBGOAL_THEN
   `induced_subgraph_edges E (cyclic_vertices (r:num->A) 3) =
    cyclic_edges r 3`
  (LABEL_TAC "induced") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:num->A`]
     SIMPLE_GRAPH_CYCLE_3_INDUCED_EDGES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_carrier
      (cyclic_vertices (r:num->A) 3) (cyclic_edges r 3) p c =
    path_image j`
  (LABEL_TAC "cycle_carrier") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `r:num->A`; `3`]
     PLANE_GRAPH_EMBEDDING_CHORDLESS_CYCLE_INDUCED_CARRIER) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "image" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN `frontier(k:real^2->bool) SUBSET path_image j`
  (LABEL_TAC "frontier_subset") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `k:real^2->bool`]
     PLANE_GRAPH_EMBEDDING_FACE_FRONTIER_SUBSET_INDUCED_CARRIER) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "face_vertices" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "cycle_carrier" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `path_image(j:real^1->real^2) SUBSET
    plane_graph_carrier (V:A->bool) E p c`
  (LABEL_TAC "cycle_subset") THENL
   [USE_THEN "image" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC EDGE_IMAGE_UNIONS_SUBSET_PLANE_GRAPH_CARRIER THEN
    USE_THEN "cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(k:real^2->bool) SUBSET (:real^2) DIFF path_image j`
  (LABEL_TAC "k_subset") THENL
   [MP_TAC(MATCH_MP IN_COMPONENTS_SUBSET
     (ASSUME
      `(k:real^2->bool) IN components
       ((:real^2) DIFF plane_graph_carrier
         (V:A->bool) E (p:A->real^2) c)`)) THEN
    USE_THEN "cycle_subset" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `connected(k:real^2->bool)`
  (LABEL_TAC "k_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`(:real^2) DIFF plane_graph_carrier
       (V:A->bool) E (p:A->real^2) c`; `k:real^2->bool`]
     IN_COMPONENTS_CONNECTED) THEN
    USE_THEN "component" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((k:real^2->bool) = {})`
  (LABEL_TAC "k_nonempty") THENL
   [MATCH_MP_TAC(ISPECL
     [`(:real^2) DIFF plane_graph_carrier
       (V:A->bool) E (p:A->real^2) c`; `k:real^2->bool`]
     IN_COMPONENTS_NONEMPTY) THEN
    USE_THEN "component" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `open(k:real^2->bool)` (LABEL_TAC "k_open") THENL
   [MATCH_MP_TAC(ISPECL
     [`(:real^2) DIFF plane_graph_carrier
       (V:A->bool) E (p:A->real^2) c`; `k:real^2->bool`]
     OPEN_COMPONENTS) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC OPEN_DIFF THEN CONJ_TAC THENL
       [REWRITE_TAC[OPEN_UNIV];
        MATCH_MP_TAC PLANE_GRAPH_CARRIER_CLOSED THEN ASM_REWRITE_TAC[]];
      USE_THEN "component" ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`j:real^1->real^2`; `k:real^2->bool`]
   OPEN_JORDAN_COMPLEMENT_COMPONENT_EQ_SIDE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "frontier side" THEN
  EXISTS_TAC `j:real^1->real^2` THEN ASM_REWRITE_TAC[]);;

let CLOSED_EMPTY_INTERIOR_JORDAN_SIDE_DENSE = prove
 (`!C:real^2->bool. !j:real^1->real^2. !s x.
        closed C /\
        interior C = {} /\
        simple_path j /\
        pathfinish j = pathstart j /\
        (s = inside(path_image j) \/ s = outside(path_image j)) /\
        x IN path_image j
        ==> x IN closure(s DIFF C)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "closed empty simple loop side x_curve" THEN
  MP_TAC(ISPEC `j:real^1->real^2` JORDAN_INSIDE_OUTSIDE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "inside_nonempty inside_open inside_connected outside_nonempty \
    outside_open outside_connected inside_bounded outside_unbounded \
    sides_disjoint sides_union inside_frontier outside_frontier" THEN
  SUBGOAL_THEN
   `open(s:real^2->bool) /\ frontier s = path_image j`
  (CONJUNCTS_THEN2
    (LABEL_TAC "side_open") (LABEL_TAC "side_frontier")) THENL
   [USE_THEN "side" (DISJ_CASES_THEN SUBST1_TAC) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `closure((s:real^2->bool) DIFF C) = closure s`
  (LABEL_TAC "side_closure") THENL
   [ONCE_REWRITE_TAC
     [SET_RULE
       `(s:real^2->bool) DIFF C =
        s INTER ((:real^2) DIFF C)`] THEN
    MATCH_MP_TAC CLOSURE_OPEN_INTER_SUPERSET THEN
    CONJ_TAC THENL
     [USE_THEN "side_open" ACCEPT_TAC;
      REWRITE_TAC[CLOSURE_COMPLEMENT] THEN
      USE_THEN "empty" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[DIFF_EMPTY; SUBSET_UNIV]];
    ALL_TAC] THEN
  USE_THEN "side_closure" (fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN `x IN frontier(s:real^2->bool)` MP_TAC THENL
   [USE_THEN "side_frontier" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "x_curve" ACCEPT_TAC;
    REWRITE_TAC[frontier; IN_DIFF] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC))]);;

let CLOSED_EMPTY_INTERIOR_JORDAN_SIDE_INCIDENT_COMPONENT = prove
 (`!C:real^2->bool. !j:real^1->real^2. !s x.
        closed C /\
        interior C = {} /\
        FINITE(components((:real^2) DIFF C)) /\
        simple_path j /\
        pathfinish j = pathstart j /\
        (s = inside(path_image j) \/ s = outside(path_image j)) /\
        path_image j SUBSET C /\
        x IN path_image j
        ==> ?k. k IN components((:real^2) DIFF C) /\
                k SUBSET s /\
                x IN frontier k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "closed empty finite simple loop side curve_subset x_curve" THEN
  SUBGOAL_THEN
   `x IN closure((s:real^2->bool) DIFF C)`
  (LABEL_TAC "x_dense") THENL
   [MATCH_MP_TAC(ISPECL
     [`C:real^2->bool`; `j:real^1->real^2`;
      `s:real^2->bool`; `x:real^2`]
     CLOSED_EMPTY_INTERIOR_JORDAN_SIDE_DENSE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `closure((s:real^2->bool) DIFF C) =
    UNIONS
     {closure(s INTER k) |
      k IN components((:real^2) DIFF C)}`
  (LABEL_TAC "closure_components") THENL
   [ONCE_REWRITE_TAC
     [SET_RULE
       `(s:real^2->bool) DIFF C =
        s INTER ((:real^2) DIFF C)`] THEN
    REWRITE_TAC[INTER_UNIV] THEN
    MATCH_MP_TAC CLOSURE_INTER_UNIONS_COMPONENTS THEN
    USE_THEN "finite" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?k:real^2->bool.
        k IN components((:real^2) DIFF C) /\
        x IN closure(s INTER k)` MP_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`components((:real^2) DIFF C)`;
      `s:real^2->bool`; `x:real^2`]
     IN_UNIONS_CLOSURE_INTER) THEN
    USE_THEN "closure_components" (fun th ->
      USE_THEN "x_dense" (ACCEPT_TAC o REWRITE_RULE[th]));
    INTRO_TAC "@k. component x_inter_closure"] THEN
  SUBGOAL_THEN
   `~((s:real^2->bool) INTER k = {})`
  (LABEL_TAC "inter_nonempty") THENL
   [DISCH_THEN(fun th ->
      USE_THEN "x_inter_closure" MP_TAC THEN
      REWRITE_TAC[th; CLOSURE_EMPTY; NOT_IN_EMPTY]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(k:real^2->bool) SUBSET (:real^2) DIFF path_image j`
  (LABEL_TAC "k_curve_complement") THENL
   [USE_THEN "component" (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
    USE_THEN "curve_subset" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(k:real^2->bool) SUBSET inside(path_image j) \/
    k SUBSET outside(path_image j)`
  (LABEL_TAC "k_side") THENL
   [MATCH_MP_TAC(ISPECL
     [`path_image(j:real^1->real^2)`; `k:real^2->bool`]
     CONNECTED_SUBSET_INSIDE_OR_OUTSIDE) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC CLOSED_PATH_IMAGE THEN
      ASM_MESON_TAC[SIMPLE_PATH_IMP_PATH];
      MATCH_MP_TAC(ISPECL
       [`(:real^2) DIFF C`; `k:real^2->bool`]
       IN_COMPONENTS_CONNECTED) THEN
      USE_THEN "component" ACCEPT_TAC;
      USE_THEN "k_curve_complement" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(k:real^2->bool) SUBSET s`
  (LABEL_TAC "k_subset") THENL
   [MP_TAC(ISPEC
     `path_image(j:real^1->real^2)` INSIDE_INTER_OUTSIDE) THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["side"; "k_side"; "inter_nonempty"] THEN
    SET_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `k:real^2->bool` THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "component" ACCEPT_TAC;
    USE_THEN "k_subset" ACCEPT_TAC;
    REWRITE_TAC[frontier; IN_DIFF] THEN CONJ_TAC THENL
     [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (MATCH_MP SUBSET_CLOSURE
        (SET_RULE `((s:real^2->bool) INTER k) SUBSET k`))) THEN
      USE_THEN "x_inter_closure" ACCEPT_TAC;
      USE_THEN "component" (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
      MP_TAC(ISPEC `k:real^2->bool` INTERIOR_SUBSET) THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["curve_subset"; "x_curve"] THEN
      SET_TAC[]]]);;

let PLANE_GRAPH_EMBEDDING_JORDAN_SIDE_INCIDENT_COMPONENT = prove
 (`!V E p c j s x.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        simple_path (j:real^1->real^2) /\
        pathfinish j = pathstart j /\
        (s = inside(path_image j) \/ s = outside(path_image j)) /\
        path_image j SUBSET plane_graph_carrier V E p c /\
        x IN path_image j
        ==> ?k. k IN components
                     ((:real^2) DIFF plane_graph_carrier V E p c) /\
                k SUBSET s /\
                x IN frontier k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding simple loop side curve_subset x_curve" THEN
  MATCH_MP_TAC(ISPECL
   [`plane_graph_carrier
      (V:A->bool) E (p:A->real^2)
      (c:(A->bool)->real^2->bool)`;
    `j:real^1->real^2`; `s:real^2->bool`; `x:real^2`]
   CLOSED_EMPTY_INTERIOR_JORDAN_SIDE_INCIDENT_COMPONENT) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC PLANE_GRAPH_CARRIER_CLOSED THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC PLANE_GRAPH_CARRIER_EMPTY_INTERIOR THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC FINITE_COMPLEMENT_COMPONENTS_PLANE_GRAPH_CARRIER THEN
    ASM_REWRITE_TAC[];
    USE_THEN "simple" ACCEPT_TAC;
    USE_THEN "loop" ACCEPT_TAC;
    USE_THEN "side" ACCEPT_TAC;
    USE_THEN "curve_subset" ACCEPT_TAC;
    USE_THEN "x_curve" ACCEPT_TAC]);;

let PLANE_GRAPH_EMBEDDING_TRIANGULAR_FACE_OPPOSITE_EDGE = prove
 (`!V E p c k r e.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        plane_graph_face_vertices V E p c k =
          cyclic_vertices r 3 /\
        simple_graph_cycle E r 3 /\
        e IN cyclic_edges r 3
        ==> ?j:real^1->real^2. ?l:real^2->bool.
              simple_path j /\
              pathfinish j = pathstart j /\
              path_image j =
                UNIONS(IMAGE c (cyclic_edges r 3)) /\
              frontier k = path_image j /\
              l IN components
                ((:real^2) DIFF plane_graph_carrier V E p c) /\
              ~(l = k) /\
              e SUBSET plane_graph_face_vertices V E p c l /\
              c e SUBSET frontier l /\
              ((k = inside(path_image j) /\
                l SUBSET outside(path_image j)) \/
               (k = outside(path_image j) /\
                l SUBSET inside(path_image j)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding component face_vertices cycle cycle_edge" THEN
  SUBGOAL_THEN `cyclic_edges (r:num->A) 3 SUBSET E`
  (LABEL_TAC "cycle_edges") THENL
   [USE_THEN "cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN MESON_TAC[];
    ALL_TAC] THEN
