          USE_THEN "l_subset"
           (ACCEPT_TAC o REWRITE_RULE[th]))]]]);;

let PLANE_TRIANGULATED_DISK_TRIANGULAR_FACE_OPPOSITE_EDGE = prove
 (`!V E p c q n outer k r e.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        plane_graph_face_vertices V E p c k =
          cyclic_vertices r 3 /\
        simple_graph_cycle E r 3 /\
        e IN cyclic_edges r 3
        ==> ?l. l IN components
                     ((:real^2) DIFF plane_graph_carrier V E p c) /\
                ~(l = k) /\
                e SUBSET plane_graph_face_vertices V E p c l /\
                c e SUBSET frontier l /\
                (l = outer \/
                 ?t:num->A.
                   plane_graph_face_vertices V E p c l =
                     cyclic_vertices t 3 /\
                   simple_graph_cycle E t 3)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "disk component face_vertices cycle cycle_edge" THEN
  USE_THEN "disk" MP_TAC THEN
  REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC "graph embedding _ _ _ _ triangular" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `k:real^2->bool`;
    `r:num->A`; `e:A->bool`]
   PLANE_GRAPH_EMBEDDING_TRIANGULAR_FACE_OPPOSITE_EDGE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@j l. simple loop image frontier l_component distinct \
    edge_face edge_frontier opposite" THEN
  EXISTS_TAC `l:real^2->bool` THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "l_component" ACCEPT_TAC;
    USE_THEN "distinct" ACCEPT_TAC;
    USE_THEN "edge_face" ACCEPT_TAC;
    USE_THEN "edge_frontier" ACCEPT_TAC;
    ASM_CASES_TAC `(l:real^2->bool) = outer` THENL
     [ASM_REWRITE_TAC[];
      DISJ2_TAC THEN
      USE_THEN "triangular"
       (MATCH_MP_TAC o SPEC `l:real^2->bool`) THEN
      ASM_REWRITE_TAC[]]]);;

let PAIR_SET_EQ_DISTINCT = prove
 (`!v u a b:A.
        ~(v = u) /\ {v,u} = {a,b}
        ==> (v = a /\ u = b) \/ (v = b /\ u = a)`,
  SET_TAC[]);;

let UNIT_HORIZONTAL_SEGMENT_AT_MOST_TWO_INCIDENT_COMPONENTS = prove
 (`!r:real^2->bool. !k1 k2 k3 z.
        closed r /\
        r INTER segment[vec 0,basis 1] SUBSET {vec 0,basis 1} /\
        k1 IN components
          ((:real^2) DIFF (segment[vec 0,basis 1] UNION r)) /\
        k2 IN components
          ((:real^2) DIFF (segment[vec 0,basis 1] UNION r)) /\
        k3 IN components
          ((:real^2) DIFF (segment[vec 0,basis 1] UNION r)) /\
        z IN segment(vec 0,basis 1) /\
        z IN frontier k1 /\
        z IN frontier k2 /\
        z IN frontier k3
        ==> k1 = k2 \/ k1 = k3 \/ k2 = k3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "closed edge_inter k1_component k2_component k3_component \
    z_segment z_frontier1 z_frontier2 z_frontier3" THEN
  SUBGOAL_THEN
   `(z:real^2)$2 = &0 /\ &0 < z$1 /\ z$1 < &1`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "z_segment" MP_TAC THEN
    REWRITE_TAC[IN_OPEN_UNIT_HORIZONTAL_SEGMENT];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((z:real^2) IN r)` (LABEL_TAC "z_not_r") THENL
   [MP_TAC(ISPECL [`vec 0:real^2`; `basis 1:real^2`]
      SEGMENT_OPEN_SUBSET_CLOSED) THEN
    MP_TAC(ISPECL [`vec 0:real^2`; `basis 1:real^2`]
      ENDS_NOT_IN_SEGMENT) THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["edge_inter"; "z_segment"] THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `open((:real^2) DIFF r)` (LABEL_TAC "open_away") THENL
   [REWRITE_TAC[OPEN_CLOSED; COMPL_COMPL] THEN
    USE_THEN "closed" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "open_away" (MP_TAC o REWRITE_RULE[OPEN_CONTAINS_BALL]) THEN
  DISCH_THEN(MP_TAC o SPEC `z:real^2`) THEN
  ASM_REWRITE_TAC[IN_DIFF; IN_UNIV] THEN
  INTRO_TAC "@d. d_positive ball_away" THEN
  ABBREV_TAC
   `e = min d (min ((z:real^2)$1) (&1 - z$1))` THEN
  SUBGOAL_THEN `&0 < e` (LABEL_TAC "e_positive") THENL
   [EXPAND_TAC "e" THEN REWRITE_TAC[REAL_LT_MIN] THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `e <= d /\ e <= (z:real^2)$1 /\ e <= &1 - z$1`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "e" THEN REWRITE_TAC[real_min] THEN
    REPEAT COND_CASES_TAC THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:real^2. w IN ball(z,e) ==> &0 < w$1 /\ w$1 < &1`
  (LABEL_TAC "inside_strip") THENL
   [X_GEN_TAC `w:real^2` THEN REWRITE_TAC[IN_BALL; dist] THEN
    DISCH_THEN(LABEL_TAC "near") THEN
    MP_TAC(ISPECL [`z - w:real^2`; `1`] COMPONENT_LE_NORM) THEN
    REWRITE_TAC[VECTOR_SUB_COMPONENT; REAL_ABS_BOUNDS] THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `ball(z:real^2,e) SUBSET (:real^2) DIFF r`
  (LABEL_TAC "small_ball_away") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `ball(z:real^2,d)` THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[SUBSET; IN_BALL] THEN ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  ABBREV_TAC
   `upper:real^2->bool =
      ball(z,e) INTER {w:real^2 | &0 < w$2}` THEN
  ABBREV_TAC
   `lower:real^2->bool =
      ball(z,e) INTER {w:real^2 | w$2 < &0}` THEN
  SUBGOAL_THEN
   `(upper:real^2->bool) SUBSET
      (:real^2) DIFF (segment[vec 0,basis 1] UNION r) /\
    (lower:real^2->bool) SUBSET
      (:real^2) DIFF (segment[vec 0,basis 1] UNION r)`
  (CONJUNCTS_THEN2 (LABEL_TAC "upper_subset")
    (LABEL_TAC "lower_subset")) THENL
   [EXPAND_TAC "upper" THEN EXPAND_TAC "lower" THEN
    REWRITE_TAC[SUBSET; IN_INTER; IN_ELIM_THM; IN_DIFF; IN_UNION;
                IN_UNIV; DE_MORGAN_THM] THEN
    CONJ_TAC THEN X_GEN_TAC `w:real^2` THEN
    INTRO_TAC "w_ball w_side" THEN CONJ_TAC THENL
     [REWRITE_TAC[IN_UNIT_HORIZONTAL_SEGMENT] THEN
      ASM_REAL_ARITH_TAC;
      USE_THEN "small_ball_away"
       (MP_TAC o SPEC `w:real^2` o REWRITE_RULE[SUBSET]) THEN
      ASM_REWRITE_TAC[IN_DIFF; IN_UNIV];
      REWRITE_TAC[IN_UNIT_HORIZONTAL_SEGMENT] THEN
      ASM_REAL_ARITH_TAC;
      USE_THEN "small_ball_away"
       (MP_TAC o SPEC `w:real^2` o REWRITE_RULE[SUBSET]) THEN
      ASM_REWRITE_TAC[IN_DIFF; IN_UNIV]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected(upper:real^2->bool) /\ connected(lower:real^2->bool)`
  (CONJUNCTS_THEN2 (LABEL_TAC "upper_connected")
    (LABEL_TAC "lower_connected")) THENL
   [EXPAND_TAC "upper" THEN EXPAND_TAC "lower" THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC CONVEX_CONNECTED THEN
      MATCH_MP_TAC CONVEX_INTER THEN REWRITE_TAC[CONVEX_BALL] THEN
      MATCH_ACCEPT_TAC(REWRITE_RULE[real_gt]
       (ISPECL [`&0`; `2`] CONVEX_HALFSPACE_COMPONENT_GT));
      MATCH_MP_TAC CONVEX_CONNECTED THEN
      MATCH_MP_TAC CONVEX_INTER THEN
      REWRITE_TAC[CONVEX_BALL; CONVEX_HALFSPACE_COMPONENT_LT]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!k:real^2->bool.
        k IN components
          ((:real^2) DIFF (segment[vec 0,basis 1] UNION r)) /\
        z IN frontier k
        ==> (?y. y IN upper /\ upper SUBSET k) \/
            (?y. y IN lower /\ lower SUBSET k)`
  (LABEL_TAC "side") THENL
   [X_GEN_TAC `k:real^2->bool` THEN
    INTRO_TAC "component z_frontier" THEN
    USE_THEN "z_frontier"
     (MP_TAC o REWRITE_RULE[FRONTIER_STRADDLE]) THEN
    DISCH_THEN(MP_TAC o SPEC `e:real`) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(CONJUNCTS_THEN2
     (X_CHOOSE_THEN `y:real^2`
      (CONJUNCTS_THEN2 (LABEL_TAC "y_in_k")
       (LABEL_TAC "y_near")))
     (K ALL_TAC)) THEN
    SUBGOAL_THEN `(y:real^2) IN ball(z,e)`
    (LABEL_TAC "y_ball") THENL
     [REWRITE_TAC[IN_BALL] THEN
      USE_THEN "y_near" MP_TAC THEN REWRITE_TAC[DIST_SYM];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(y:real^2) IN
      (:real^2) DIFF (segment[vec 0,basis 1] UNION r)`
    (LABEL_TAC "y_complement") THENL
     [USE_THEN "component"
       (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
      REWRITE_TAC[SUBSET] THEN
      DISCH_THEN MATCH_MP_TAC THEN
      USE_THEN "y_in_k" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((y:real^2)$2 = &0)`
    (LABEL_TAC "y_off_axis") THENL
     [DISCH_THEN(LABEL_TAC "y_axis") THEN
      SUBGOAL_THEN
       `(y:real^2) IN segment[vec 0,basis 1]`
      (LABEL_TAC "y_segment") THENL
       [REWRITE_TAC[IN_UNIT_HORIZONTAL_SEGMENT] THEN
        USE_THEN "inside_strip" (fun th ->
          USE_THEN "y_ball"
           (MP_TAC o MATCH_MP (SPEC `y:real^2` th))) THEN
        ASM_REAL_ARITH_TAC;
        ALL_TAC] THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["y_complement"; "y_segment"] THEN
      SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `&0 < (y:real^2)$2 \/ y$2 < &0`
    DISJ_CASES_TAC THENL
     [MP_TAC(SPECL [`&0`; `(y:real^2)$2`] REAL_LT_TOTAL) THEN
      ASM_REWRITE_TAC[];
      DISJ1_TAC THEN EXISTS_TAC `y:real^2` THEN CONJ_TAC THENL
       [EXPAND_TAC "upper" THEN ASM_REWRITE_TAC[IN_INTER; IN_ELIM_THM];
        MATCH_MP_TAC(ISPECL
         [`(:real^2) DIFF
            (segment[vec 0,basis 1] UNION r)`;
          `k:real^2->bool`; `upper:real^2->bool`]
         CONNECTED_SUBSET_OF_COMPONENT) THEN
        ASM_REWRITE_TAC[] THEN
        REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
        EXISTS_TAC `y:real^2` THEN ASM_REWRITE_TAC[] THEN
        EXPAND_TAC "upper" THEN ASM_REWRITE_TAC[IN_INTER; IN_ELIM_THM]];
      DISJ2_TAC THEN EXISTS_TAC `y:real^2` THEN CONJ_TAC THENL
       [EXPAND_TAC "lower" THEN ASM_REWRITE_TAC[IN_INTER; IN_ELIM_THM];
        MATCH_MP_TAC(ISPECL
         [`(:real^2) DIFF
            (segment[vec 0,basis 1] UNION r)`;
          `k:real^2->bool`; `lower:real^2->bool`]
         CONNECTED_SUBSET_OF_COMPONENT) THEN
        ASM_REWRITE_TAC[] THEN
        REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
        EXISTS_TAC `y:real^2` THEN ASM_REWRITE_TAC[] THEN
        EXPAND_TAC "lower" THEN
        ASM_REWRITE_TAC[IN_INTER; IN_ELIM_THM]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!k l h:real^2->bool.
        k IN components
          ((:real^2) DIFF (segment[vec 0,basis 1] UNION r)) /\
        l IN components
          ((:real^2) DIFF (segment[vec 0,basis 1] UNION r)) /\
        h SUBSET k /\ h SUBSET l /\ ~(h = {})
        ==> k = l`
  (LABEL_TAC "same_side") THENL
   [REPEAT GEN_TAC THEN
    INTRO_TAC "k_component l_component h_k h_l h_nonempty" THEN
    MP_TAC(ISPECL
     [`(:real^2) DIFF (segment[vec 0,basis 1] UNION r)`;
      `k:real^2->bool`; `l:real^2->bool`]
     COMPONENTS_EQ) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> MATCH_MP_TAC(snd(EQ_IMP_RULE th))) THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["h_k"; "h_l"; "h_nonempty"] THEN
    SET_TAC[];
    ALL_TAC] THEN
  USE_THEN "side" (fun th ->
    USE_THEN "k1_component" (fun kth ->
      USE_THEN "z_frontier1" (fun zth ->
        MP_TAC(MATCH_MP (SPEC `k1:real^2->bool` th)
