          (CONJ kth zth))))) THEN
  DISCH_THEN
   (DISJ_CASES_THEN2 (LABEL_TAC "k2_upper")
    (LABEL_TAC "k2_lower")) THEN
  USE_THEN "side" (fun th ->
    USE_THEN "k3_component" (fun kth ->
      USE_THEN "z_frontier3" (fun zth ->
        MP_TAC(MATCH_MP (SPEC `k3:real^2->bool` th)
          (CONJ kth zth))))) THEN
  DISCH_THEN
   (DISJ_CASES_THEN2 (LABEL_TAC "k3_upper")
    (LABEL_TAC "k3_lower")) THEN
  USE_THEN "same_side" (fun same_side ->
    FIRST
     [DISJ1_TAC THEN
      MATCH_MP_TAC(SPECL
       [`k1:real^2->bool`; `k2:real^2->bool`; `upper:real^2->bool`]
       same_side) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["k1_upper"; "k2_upper"] THEN SET_TAC[];
      DISJ1_TAC THEN
      MATCH_MP_TAC(SPECL
       [`k1:real^2->bool`; `k2:real^2->bool`; `lower:real^2->bool`]
       same_side) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["k1_lower"; "k2_lower"] THEN SET_TAC[];
      DISJ2_TAC THEN DISJ1_TAC THEN
      MATCH_MP_TAC(SPECL
       [`k1:real^2->bool`; `k3:real^2->bool`; `upper:real^2->bool`]
       same_side) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["k1_upper"; "k3_upper"] THEN SET_TAC[];
      DISJ2_TAC THEN DISJ1_TAC THEN
      MATCH_MP_TAC(SPECL
       [`k1:real^2->bool`; `k3:real^2->bool`; `lower:real^2->bool`]
       same_side) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["k1_lower"; "k3_lower"] THEN SET_TAC[];
      DISJ2_TAC THEN DISJ2_TAC THEN
      MATCH_MP_TAC(SPECL
       [`k2:real^2->bool`; `k3:real^2->bool`; `upper:real^2->bool`]
       same_side) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["k2_upper"; "k3_upper"] THEN SET_TAC[];
      DISJ2_TAC THEN DISJ2_TAC THEN
      MATCH_MP_TAC(SPECL
       [`k2:real^2->bool`; `k3:real^2->bool`; `lower:real^2->bool`]
       same_side) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["k2_lower"; "k3_lower"] THEN SET_TAC[]]));;

let ARC_AT_MOST_TWO_INCIDENT_COMPONENTS = prove
 (`!g:real^1->real^2. !r k1 k2 k3 x.
        arc g /\
        closed r /\
        path_image g INTER r SUBSET {pathstart g,pathfinish g} /\
        k1 IN components ((:real^2) DIFF (path_image g UNION r)) /\
        k2 IN components ((:real^2) DIFF (path_image g UNION r)) /\
        k3 IN components ((:real^2) DIFF (path_image g UNION r)) /\
        x IN path_image g DIFF {pathstart g,pathfinish g} /\
        x IN frontier k1 /\
        x IN frontier k2 /\
        x IN frontier k3
        ==> k1 = k2 \/ k1 = k3 \/ k2 = k3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "arc closed edge_inter k1_component k2_component k3_component \
    x_interior x_frontier1 x_frontier2 x_frontier3" THEN
  SUBGOAL_THEN `arc(linepath(vec 0:real^2,basis 1))`
  (LABEL_TAC "line_arc") THENL
   [SIMP_TAC[ARC_LINEPATH_EQ; BASIS_NONZERO; DIMINDEX_GE_1; LE_REFL];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`g:real^1->real^2`; `linepath(vec 0:real^2,basis 1)`]
   HOMEOMORPHISM_ARC_IMAGES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@f f'. image_homeomorphism f_start f_finish f'_start f'_finish" THEN
  MP_TAC(ISPECL
   [`g:real^1->real^2`; `linepath(vec 0:real^2,basis 1)`;
    `f:real^2->real^2`; `f':real^2->real^2`]
   JORDAN_SCHOENFLIES) THEN
  ANTS_TAC THENL
   [ASM_MESON_TAC[ARC_IMP_SIMPLE_PATH];
    ALL_TAC] THEN
  INTRO_TAC
   "@q q'. global_homeomorphism q_agrees q'_agrees image_arc _ _" THEN
  SUBGOAL_THEN
   `IMAGE (q:real^2->real^2) (path_image g) =
    segment[vec 0,basis 1]`
  (LABEL_TAC "image_segment") THENL
   [USE_THEN "image_arc" MP_TAC THEN REWRITE_TAC[PATH_IMAGE_LINEPATH];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:real^2->real^2) (pathstart g) = vec 0`
  (LABEL_TAC "q_start") THENL
   [USE_THEN "q_agrees"
     (MP_TAC o SPEC `pathstart(g:real^1->real^2)`) THEN
    REWRITE_TAC[PATHSTART_IN_PATH_IMAGE] THEN
    DISCH_THEN SUBST1_TAC THEN
    USE_THEN "f_start" MP_TAC THEN REWRITE_TAC[PATHSTART_LINEPATH];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:real^2->real^2) (pathfinish g) = basis 1`
  (LABEL_TAC "q_finish") THENL
   [USE_THEN "q_agrees"
     (MP_TAC o SPEC `pathfinish(g:real^1->real^2)`) THEN
    REWRITE_TAC[PATHFINISH_IN_PATH_IMAGE] THEN
    DISCH_THEN SUBST1_TAC THEN
    USE_THEN "f_finish" MP_TAC THEN REWRITE_TAC[PATHFINISH_LINEPATH];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u v:real^2. (q:real^2->real^2) u = q v ==> u = v`
  (LABEL_TAC "q_injective") THENL
   [MAP_EVERY X_GEN_TAC [`u:real^2`; `v:real^2`] THEN
    DISCH_THEN(MP_TAC o AP_TERM `(q':real^2->real^2)`) THEN
    USE_THEN "global_homeomorphism" (fun th ->
      REWRITE_TAC[REWRITE_RULE[IN_UNIV]
       (CONJUNCT1(REWRITE_RULE[homeomorphism] th))]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (q:real^2->real^2) (:real^2) = (:real^2)`
  (LABEL_TAC "q_surjective") THENL
   [USE_THEN "global_homeomorphism"
     (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o
      REWRITE_RULE[homeomorphism]);
    ALL_TAC] THEN
  SUBGOAL_THEN `closed(IMAGE (q:real^2->real^2) r)`
  (LABEL_TAC "image_closed") THENL
   [MP_TAC(ISPECL
     [`q:real^2->real^2`; `q':real^2->real^2`;
      `(:real^2)`; `(:real^2)`; `r:real^2->bool`]
     HOMEOMORPHISM_IMP_CLOSED_MAP) THEN
    ASM_REWRITE_TAC[SUBTOPOLOGY_UNIV; GSYM CLOSED_IN];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (q:real^2->real^2) r INTER segment[vec 0,basis 1] =
    IMAGE q (r INTER path_image g)`
  (LABEL_TAC "image_intersection") THENL
   [USE_THEN "image_segment" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC IMAGE_INTER_INJ THEN
    USE_THEN "q_injective" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (q:real^2->real^2) r INTER segment[vec 0,basis 1]
    SUBSET {vec 0,basis 1}`
  (LABEL_TAC "edge_image_inter") THENL
   [USE_THEN "image_intersection" SUBST1_TAC THEN
    TRANS_TAC SUBSET_TRANS
     `IMAGE (q:real^2->real^2) {pathstart g,pathfinish g}` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC IMAGE_SUBSET THEN
      USE_THEN "edge_inter" MP_TAC THEN SET_TAC[];
      ASM_REWRITE_TAC[IMAGE_CLAUSES; SUBSET_REFL]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (q:real^2->real^2)
      ((:real^2) DIFF (path_image g UNION r)) =
    (:real^2) DIFF
      (segment[vec 0,basis 1] UNION IMAGE q r)`
  (LABEL_TAC "image_complement") THENL
   [TRANS_TAC EQ_TRANS
     `IMAGE (q:real^2->real^2) (:real^2) DIFF
      IMAGE q (path_image g UNION r)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC IMAGE_DIFF_INJ THEN
      MAP_EVERY X_GEN_TAC [`u:real^2`; `v:real^2`] THEN
      INTRO_TAC "u_univ v_union image_equal" THEN
      USE_THEN "q_injective" MATCH_MP_TAC THEN
      USE_THEN "image_equal" ACCEPT_TAC;
      ASM_REWRITE_TAC[IMAGE_UNION; PATH_IMAGE_LINEPATH]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `homeomorphism
      (((:real^2) DIFF (path_image g UNION r)),
       ((:real^2) DIFF
        (segment[vec 0,basis 1] UNION IMAGE q r)))
      ((q:real^2->real^2),q')`
  (LABEL_TAC "complement_homeomorphism") THENL
   [MATCH_MP_TAC HOMEOMORPHISM_OF_SUBSETS THEN
    MAP_EVERY EXISTS_TAC [`(:real^2)`; `(:real^2)`] THEN
    ASM_REWRITE_TAC[SUBSET_UNIV];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!k:real^2->bool.
        k IN components
          ((:real^2) DIFF (path_image g UNION r))
        ==> IMAGE q k IN components
              ((:real^2) DIFF
               (segment[vec 0,basis 1] UNION IMAGE q r))`
  (LABEL_TAC "image_component") THENL
   [X_GEN_TAC `k:real^2->bool` THEN
    DISCH_THEN(LABEL_TAC "component") THEN
    USE_THEN "complement_homeomorphism"
     (MP_TAC o MATCH_MP HOMEOMORPHISM_COMPONENTS) THEN
    DISCH_THEN SUBST1_TAC THEN MATCH_MP_TAC FUN_IN_IMAGE THEN
    USE_THEN "component" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!k:real^2->bool.
        IMAGE (q:real^2->real^2) (frontier k) =
        frontier (IMAGE q k)`
  (LABEL_TAC "image_frontier") THENL
   [X_GEN_TAC `k:real^2->bool` THEN
    MP_TAC(ISPECL
     [`q:real^2->real^2`; `q':real^2->real^2`;
      `(:real^2)`; `(:real^2)`; `k:real^2->bool`]
     HOMEOMORPHISM_FRONTIER_OF) THEN
    ASM_REWRITE_TAC[SUBSET_UNIV; SUBTOPOLOGY_UNIV;
                    EUCLIDEAN_FRONTIER_OF];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:real^2->real^2) x IN segment[vec 0,basis 1]`
  (LABEL_TAC "qx_closed_segment") THENL
   [USE_THEN "image_segment" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC FUN_IN_IMAGE THEN
    USE_THEN "x_interior" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((q:real^2->real^2) x IN {vec 0,basis 1})`
  (LABEL_TAC "qx_not_endpoints") THENL
   [REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY; DE_MORGAN_THM] THEN
    CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "qx_start") THEN
      USE_THEN "q_injective"
       (MP_TAC o SPECL [`x:real^2`; `pathstart(g:real^1->real^2)`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        USE_THEN "x_interior" MP_TAC THEN SET_TAC[]];
      DISCH_THEN(LABEL_TAC "qx_finish") THEN
      USE_THEN "q_injective"
       (MP_TAC o SPECL [`x:real^2`; `pathfinish(g:real^1->real^2)`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        USE_THEN "x_interior" MP_TAC THEN SET_TAC[]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:real^2->real^2) x IN segment(vec 0,basis 1)`
  (LABEL_TAC "qx_open_segment") THENL
   [USE_THEN "qx_closed_segment" MP_TAC THEN
    REWRITE_TAC[SEGMENT_CLOSED_OPEN; IN_UNION] THEN
    USE_THEN "qx_not_endpoints" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!k:real^2->bool.
        x IN frontier k
        ==> (q:real^2->real^2) x IN frontier (IMAGE q k)`
  (LABEL_TAC "qx_frontier") THENL
   [X_GEN_TAC `k:real^2->bool` THEN
    DISCH_THEN(LABEL_TAC "x_frontier") THEN
    USE_THEN "image_frontier"
     (MP_TAC o SPEC `k:real^2->bool`) THEN
    DISCH_THEN(fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC FUN_IN_IMAGE THEN
    USE_THEN "x_frontier" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!s t:real^2->bool.
        IMAGE (q:real^2->real^2) s = IMAGE q t ==> s = t`
  (LABEL_TAC "image_injective") THENL
   [REPEAT GEN_TAC THEN
    USE_THEN "q_injective" MP_TAC THEN
    REWRITE_TAC[EXTENSION; IN_IMAGE] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`IMAGE (q:real^2->real^2) r`;
    `IMAGE (q:real^2->real^2) k1`;
    `IMAGE (q:real^2->real^2) k2`;
    `IMAGE (q:real^2->real^2) k3`;
    `(q:real^2->real^2) x`]
   UNIT_HORIZONTAL_SEGMENT_AT_MOST_TWO_INCIDENT_COMPONENTS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "image_closed" ACCEPT_TAC;
      USE_THEN "edge_image_inter" ACCEPT_TAC;
      USE_THEN "image_component" MATCH_MP_TAC THEN
      USE_THEN "k1_component" ACCEPT_TAC;
      USE_THEN "image_component" MATCH_MP_TAC THEN
      USE_THEN "k2_component" ACCEPT_TAC;
      USE_THEN "image_component" MATCH_MP_TAC THEN
      USE_THEN "k3_component" ACCEPT_TAC;
      USE_THEN "qx_open_segment" ACCEPT_TAC;
      USE_THEN "qx_frontier" MATCH_MP_TAC THEN
      USE_THEN "x_frontier1" ACCEPT_TAC;
      USE_THEN "qx_frontier" MATCH_MP_TAC THEN
      USE_THEN "x_frontier2" ACCEPT_TAC;
      USE_THEN "qx_frontier" MATCH_MP_TAC THEN
      USE_THEN "x_frontier3" ACCEPT_TAC];
    DISCH_THEN(LABEL_TAC "image_equality") THEN
    USE_THEN "image_equality"
     (DISJ_CASES_THEN2 (LABEL_TAC "image12")
      (DISJ_CASES_THEN2 (LABEL_TAC "image13")
       (LABEL_TAC "image23"))) THENL
     [DISJ1_TAC THEN
      USE_THEN "image_injective" MATCH_MP_TAC THEN
      USE_THEN "image12" ACCEPT_TAC;
      DISJ2_TAC THEN DISJ1_TAC THEN
      USE_THEN "image_injective" MATCH_MP_TAC THEN
      USE_THEN "image13" ACCEPT_TAC;
      DISJ2_TAC THEN DISJ2_TAC THEN
      USE_THEN "image_injective" MATCH_MP_TAC THEN
      USE_THEN "image23" ACCEPT_TAC]]);;

let PLANE_GRAPH_EMBEDDING_EDGE_AT_MOST_TWO_INCIDENT_COMPONENTS =
  prove
 (`!V E p c e k1 k2 k3 x.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e IN E /\
        k1 IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        k2 IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        k3 IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        x IN c e DIFF IMAGE p e /\
        x IN frontier k1 /\
        x IN frontier k2 /\
        x IN frontier k3
        ==> k1 = k2 \/ k1 = k3 \/ k2 = k3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding edge k1_component k2_component k3_component \
    x_interior x_frontier1 x_frontier2 x_frontier3" THEN
  USE_THEN "embedding" MP_TAC THEN
  REWRITE_TAC[plane_graph_embedding] THEN
  INTRO_TAC "_ edge_paths _ _" THEN
  REMOVE_THEN "edge_paths" (MP_TAC o SPEC `e:A->bool`) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@g. arc edge_image endpoints" THEN
  SUBGOAL_THEN
   `closed(plane_graph_carrier
      (V:A->bool) (E DELETE e) (p:A->real^2)
      (c:(A->bool)->real^2->bool))`
  (LABEL_TAC "remainder_closed") THENL
   [MATCH_MP_TAC COMPACT_IMP_CLOSED THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `E DELETE (e:A->bool)`]
     PLANE_GRAPH_CARRIER_COMPACT) THEN
    ASM_REWRITE_TAC[DELETE_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_carrier (V:A->bool) E p c =
    c e UNION plane_graph_carrier V (E DELETE e) p c`
  (LABEL_TAC "carrier_decomposition") THENL
   [MATCH_MP_TAC PLANE_GRAPH_CARRIER_DELETE_EDGE THEN
    USE_THEN "edge" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) e INTER
    plane_graph_carrier V (E DELETE e) p c = IMAGE p e`
  (LABEL_TAC "edge_remainder") THENL
   [MATCH_MP_TAC PLANE_GRAPH_EMBEDDING_EDGE_INTER_DELETE_CARRIER THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "edge_image" (SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC(ISPECL
   [`g:real^1->real^2`;
    `plane_graph_carrier
      (V:A->bool) (E DELETE e) (p:A->real^2)
      (c:(A->bool)->real^2->bool)`;
    `k1:real^2->bool`; `k2:real^2->bool`; `k3:real^2->bool`;
    `x:real^2`]
   ARC_AT_MOST_TWO_INCIDENT_COMPONENTS) THEN
  ASM_REWRITE_TAC[SUBSET_REFL] THEN
  USE_THEN "carrier_decomposition"
   (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
  ASM_REWRITE_TAC[]);;

let PLANE_GRAPH_EMBEDDING_EDGE_INTERIOR_NONEMPTY = prove
 (`!V E p c e.
        plane_graph_embedding (V:A->bool) E p c /\
        e IN E
        ==> ~((c:(A->bool)->real^2->bool) e DIFF
              IMAGE (p:A->real^2) e = {})`,
  REPEAT GEN_TAC THEN INTRO_TAC "embedding edge" THEN
  USE_THEN "embedding" MP_TAC THEN
  REWRITE_TAC[plane_graph_embedding] THEN
  INTRO_TAC "_ edge_paths _ _" THEN
  USE_THEN "edge_paths" (fun th ->
    USE_THEN "edge" (fun eth ->
      MP_TAC(MATCH_MP (SPEC `e:A->bool` th) eth))) THEN
  INTRO_TAC "@g. arc edge_image endpoints" THEN
  USE_THEN "edge_image" (fun th -> REWRITE_TAC[GSYM th]) THEN
  USE_THEN "endpoints" (fun th -> REWRITE_TAC[GSYM th]) THEN
  MATCH_MP_TAC NONEMPTY_SIMPLE_PATH_ENDLESS THEN
  ASM_SIMP_TAC[ARC_IMP_SIMPLE_PATH]);;

let PLANE_GRAPH_EMBEDDING_EDGE_AT_MOST_TWO_INCIDENT_FACES = prove
 (`!V E p c e k1 k2 k3.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e IN E /\
        k1 IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        k2 IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        k3 IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        c e SUBSET frontier k1 /\
        c e SUBSET frontier k2 /\
        c e SUBSET frontier k3
        ==> k1 = k2 \/ k1 = k3 \/ k2 = k3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding edge k1_component k2_component k3_component \
    k1_frontier k2_frontier k3_frontier" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `e:A->bool`]
   PLANE_GRAPH_EMBEDDING_EDGE_INTERIOR_NONEMPTY) THEN
  ASM_REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
  INTRO_TAC "@x. x_interior" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `e:A->bool`;
    `k1:real^2->bool`; `k2:real^2->bool`; `k3:real^2->bool`;
    `x:real^2`]
   PLANE_GRAPH_EMBEDDING_EDGE_AT_MOST_TWO_INCIDENT_COMPONENTS) THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "k1_frontier" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "x_interior" MP_TAC THEN SET_TAC[];
    USE_THEN "k2_frontier" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "x_interior" MP_TAC THEN SET_TAC[];
    USE_THEN "k3_frontier" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "x_interior" MP_TAC THEN SET_TAC[]]);;

let PLANE_GRAPH_EMBEDDING_OTHER_INCIDENT_FACE_UNIQUE = prove
 (`!V E p c e k l1 l2.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e IN E /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        l1 IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        l2 IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        c e SUBSET frontier k /\
        c e SUBSET frontier l1 /\
        c e SUBSET frontier l2 /\
        ~(l1 = k) /\
        ~(l2 = k)
        ==> l1 = l2`,
  REPEAT GEN_TAC THEN INTRO_TAC
   "graph embedding edge k_component l1_component l2_component \
    k_frontier l1_frontier l2_frontier l1_distinct l2_distinct" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `e:A->bool`;
    `k:real^2->bool`; `l1:real^2->bool`; `l2:real^2->bool`]
   PLANE_GRAPH_EMBEDDING_EDGE_AT_MOST_TWO_INCIDENT_FACES) THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

let CONNECTED_FINITE_CLOSED_COVER_CROSSING = prove
 (`!s:real^N->bool. !f g:(real^N->bool)->bool.
        FINITE f /\
        connected s /\
        s SUBSET UNIONS f /\
        (!t. t IN f
             ==> closed_in (subtopology euclidean s) t) /\
        g SUBSET f /\
        ~(UNIONS g = {}) /\
        ~(UNIONS(f DIFF g) = {})
        ==> ?u v. u IN g /\
                  v IN f DIFF g /\
                  ~(u INTER v = {})`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite connected cover closed subfamily left_nonempty right_nonempty" THEN
  ASM_CASES_TAC
   `?u v:real^N->bool.
        u IN g /\ v IN f DIFF g /\ ~(u INTER v = {})` THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  POP_ASSUM MP_TAC THEN DISCH_THEN(LABEL_TAC "no_crossing") THEN
  SUBGOAL_THEN
   `?e1 e2:real^N->bool.
        closed_in (subtopology euclidean s) e1 /\
        closed_in (subtopology euclidean s) e2 /\
        s SUBSET e1 UNION e2 /\
        e1 INTER e2 = {} /\
        ~(e1 = {}) /\
        ~(e2 = {})`
  (LABEL_TAC "separation") THENL
   [MAP_EVERY EXISTS_TAC
     [`UNIONS(g:(real^N->bool)->bool)`;
      `UNIONS(f DIFF g):(real^N->bool)`] THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC CLOSED_IN_UNIONS THEN CONJ_TAC THENL
       [MATCH_MP_TAC FINITE_SUBSET THEN
        EXISTS_TAC `f:(real^N->bool)->bool` THEN ASM_REWRITE_TAC[];
        X_GEN_TAC `t:real^N->bool` THEN
        DISCH_THEN(LABEL_TAC "t_sub") THEN
        USE_THEN "closed" MATCH_MP_TAC THEN
        USE_THEN "subfamily" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "t_sub" ACCEPT_TAC];
      MATCH_MP_TAC CLOSED_IN_UNIONS THEN CONJ_TAC THENL
       [MATCH_MP_TAC FINITE_SUBSET THEN
        EXISTS_TAC `f:(real^N->bool)->bool` THEN
        ASM_REWRITE_TAC[] THEN
        REWRITE_TAC[SUBSET; IN_DIFF] THEN
        X_GEN_TAC `t:real^N->bool` THEN
        DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC));
        X_GEN_TAC `t:real^N->bool` THEN
        REWRITE_TAC[IN_DIFF] THEN INTRO_TAC "t_f _" THEN
        USE_THEN "closed" MATCH_MP_TAC THEN
        USE_THEN "t_f" ACCEPT_TAC];
      REWRITE_TAC[SUBSET; IN_UNION; IN_UNIONS] THEN
      X_GEN_TAC `x:real^N` THEN DISCH_THEN(LABEL_TAC "x_s") THEN
      USE_THEN "cover"
       (MP_TAC o SPEC `x:real^N` o REWRITE_RULE[SUBSET]) THEN
      ASM_REWRITE_TAC[IN_UNIONS] THEN
      INTRO_TAC "@t. t_f x_t" THEN
      ASM_CASES_TAC `(t:real^N->bool) IN g` THENL
       [DISJ1_TAC THEN EXISTS_TAC `t:real^N->bool` THEN
        ASM_REWRITE_TAC[];
        DISJ2_TAC THEN EXISTS_TAC `t:real^N->bool` THEN
        ASM_REWRITE_TAC[IN_DIFF]];
      REWRITE_TAC[EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
      X_GEN_TAC `x:real^N` THEN
      DISCH_THEN(CONJUNCTS_THEN2
       (LABEL_TAC "x_left") (LABEL_TAC "x_right")) THEN
      USE_THEN "x_left" (MP_TAC o REWRITE_RULE[IN_UNIONS]) THEN
      DISCH_THEN(X_CHOOSE_THEN `u:real^N->bool`
       (CONJUNCTS_THEN2 (LABEL_TAC "u_g") (LABEL_TAC "x_u"))) THEN
      USE_THEN "x_right" (MP_TAC o REWRITE_RULE[IN_UNIONS]) THEN
      DISCH_THEN(X_CHOOSE_THEN `v:real^N->bool`
       (CONJUNCTS_THEN2 (LABEL_TAC "v_rest") (LABEL_TAC "x_v"))) THEN
      SUBGOAL_THEN
       `?u v:real^N->bool.
          u IN g /\ v IN f DIFF g /\ ~(u INTER v = {})`
      (LABEL_TAC "crossing") THENL
       [MAP_EVERY EXISTS_TAC
         [`u:real^N->bool`; `v:real^N->bool`] THEN
        ASM_REWRITE_TAC[] THEN
        REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
        EXISTS_TAC `x:real^N` THEN ASM_REWRITE_TAC[];
        MAP_EVERY (fun name -> USE_THEN name MP_TAC)
         ["no_crossing"; "crossing"] THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[]];
      USE_THEN "left_nonempty" ACCEPT_TAC;
      USE_THEN "right_nonempty" ACCEPT_TAC];
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["connected"; "separation"] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN
    REWRITE_TAC[CONNECTED_CLOSED_IN] THEN MESON_TAC[]]);;

let CONNECTED_COMPLEMENT_COMPONENT_DELETE_2 = prove
 (`!C l:real^2->bool. !a.
        closed C /\
        l IN components((:real^2) DIFF C)
        ==> connected(l DELETE a)`,
  REPEAT GEN_TAC THEN INTRO_TAC "closed component" THEN
  SUBGOAL_THEN `open((:real^2) DIFF C)`
  (LABEL_TAC "complement_open") THENL
   [REWRITE_TAC[OPEN_CLOSED; COMPL_COMPL] THEN
    USE_THEN "closed" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `open(l:real^2->bool)`
  (LABEL_TAC "component_open") THENL
   [MATCH_MP_TAC(ISPECL
     [`(:real^2) DIFF C`; `l:real^2->bool`] OPEN_COMPONENTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `connected(l:real^2->bool)`
  (LABEL_TAC "component_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`(:real^2) DIFF C`; `l:real^2->bool`]
     IN_COMPONENTS_CONNECTED) THEN
    USE_THEN "component" ACCEPT_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC CONNECTED_OPEN_DELETE THEN
  ASM_REWRITE_TAC[DIMINDEX_2; LE_REFL]);;

let PLANE_GRAPH_CARRIER_DELETE_VERTEX_POINT_ON_INCIDENT_EDGE = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !p:A->real^2. !c:(A->bool)->real^2->bool. !v:A. !x:real^2.
        finite_simple_graph V E /\
        (x:real^2) IN
          (plane_graph_carrier (V:A->bool) (E:(A->bool)->bool)
             (p:A->real^2) (c:(A->bool)->real^2->bool) DIFF
           plane_graph_carrier ((V:A->bool) DELETE (v:A))
             (induced_subgraph_edges (E:(A->bool)->bool)
               ((V:A->bool) DELETE (v:A)))
             (p:A->real^2) (c:(A->bool)->real^2->bool)) /\
        ~((x:real^2) = (p:A->real^2) (v:A))
        ==> ?e:A->bool.
              e IN (E:(A->bool)->bool) /\
              (v:A) IN e /\
              (x:real^2) IN
                (c:(A->bool)->real^2->bool) e DIFF
                IMAGE (p:A->real^2) e`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph x_removed x_not_v" THEN
  USE_THEN "x_removed" MP_TAC THEN
  REWRITE_TAC[IN_DIFF] THEN INTRO_TAC "x_old x_not_new" THEN
  USE_THEN "x_old" MP_TAC THEN
  REWRITE_TAC[plane_graph_carrier; IN_UNION; IN_IMAGE;
              UNIONS_IMAGE; IN_ELIM_THM] THEN
  DISCH_THEN
   (DISJ_CASES_THEN2
    (X_CHOOSE_THEN `w:A`
     (CONJUNCTS_THEN2 (LABEL_TAC "x_w") (LABEL_TAC "w_vertex")))
    (X_CHOOSE_THEN `e:A->bool`
     (CONJUNCTS_THEN2 (LABEL_TAC "e_edge") (LABEL_TAC "x_edge")))) THENL
   [ASM_CASES_TAC `(w:A) = v` THENL
     [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["x_not_v"; "x_w"] THEN
      ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x:real^2) IN IMAGE (p:A->real^2) (V DELETE v)`
    (LABEL_TAC "x_new_vertex") THENL
     [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `w:A` THEN
      ASM_REWRITE_TAC[IN_DELETE];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x:real^2) IN
      plane_graph_carrier ((V:A->bool) DELETE (v:A))
        (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
        (p:A->real^2) (c:(A->bool)->real^2->bool)`
    (LABEL_TAC "x_new_carrier") THENL
     [REWRITE_TAC[plane_graph_carrier; IN_UNION] THEN DISJ1_TAC THEN
      USE_THEN "x_new_vertex" ACCEPT_TAC;
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["x_not_new"; "x_new_carrier"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(e:A->bool) SUBSET V`
  (LABEL_TAC "edge_subset") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    INTRO_TAC "_ _ edges" THEN
    USE_THEN "edges" (fun th ->
      USE_THEN "e_edge" (fun eth ->
        MP_TAC(MATCH_MP (SPEC `e:A->bool` th) eth))) THEN
    INTRO_TAC "subset _" THEN USE_THEN "subset" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(v:A) IN e` (LABEL_TAC "v_edge") THENL
   [ASM_CASES_TAC `(v:A) IN e` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(e:A->bool) SUBSET V DELETE v`
    (LABEL_TAC "edge_delete") THENL
     [REWRITE_TAC[SUBSET; IN_DELETE] THEN X_GEN_TAC `u:A` THEN
      DISCH_THEN(LABEL_TAC "u_edge") THEN CONJ_TAC THENL
       [USE_THEN "edge_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "u_edge" ACCEPT_TAC;
        ASM_MESON_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(e:A->bool) IN induced_subgraph_edges E (V DELETE v)`
    (LABEL_TAC "new_edge") THENL
     [REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x:real^2) IN
      plane_graph_carrier ((V:A->bool) DELETE (v:A))
        (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
        (p:A->real^2) (c:(A->bool)->real^2->bool)`
    (LABEL_TAC "x_new_carrier") THENL
     [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (MATCH_MP
        (SPECL
         [`(V:A->bool) DELETE (v:A)`;
          `induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v)`;
          `p:A->real^2`; `c:(A->bool)->real^2->bool`; `e:A->bool`]
         PLANE_GRAPH_CARRIER_EDGE_SUBSET)
        (ASSUME
         `(e:A->bool) IN
          induced_subgraph_edges E (V DELETE v)`))) THEN
      USE_THEN "x_edge" ACCEPT_TAC;
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["x_not_new"; "x_new_carrier"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((x:real^2) IN IMAGE (p:A->real^2) e)`
  (LABEL_TAC "x_not_endpoint") THENL
   [REWRITE_TAC[IN_IMAGE] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A`
     (CONJUNCTS_THEN2 (LABEL_TAC "x_u") (LABEL_TAC "u_edge"))) THEN
    SUBGOAL_THEN `(u:A) IN V` (LABEL_TAC "u_vertex") THENL
     [USE_THEN "edge_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "u_edge" ACCEPT_TAC;
      ALL_TAC] THEN
    ASM_CASES_TAC `(u:A) = v` THENL
     [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["x_not_v"; "x_u"] THEN
      ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x:real^2) IN IMAGE (p:A->real^2) (V DELETE v)`
    (LABEL_TAC "x_new_vertex") THENL
     [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `u:A` THEN
      ASM_REWRITE_TAC[IN_DELETE] THEN
      USE_THEN "x_u" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x:real^2) IN
      plane_graph_carrier ((V:A->bool) DELETE (v:A))
        (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
        (p:A->real^2) (c:(A->bool)->real^2->bool)`
    (LABEL_TAC "x_new_carrier") THENL
     [REWRITE_TAC[plane_graph_carrier; IN_UNION] THEN DISJ1_TAC THEN
      USE_THEN "x_new_vertex" ACCEPT_TAC;
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["x_not_new"; "x_new_carrier"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `e:A->bool` THEN
  CONJ_TAC THENL
   [USE_THEN "e_edge" ACCEPT_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "v_edge" ACCEPT_TAC;
    CONJ_TAC THENL
     [USE_THEN "x_edge" ACCEPT_TAC;
      USE_THEN "x_not_endpoint" MP_TAC THEN REWRITE_TAC[IN_IMAGE]]]);;

let PLANE_TRIANGULATED_DISK_DELETE_VERTEX_INCIDENT_FACE_CLOSURE_COVER =
  prove
 (`!V E p c q n outer v newouter.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        v IN cyclic_vertices q n /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        (p:A->real^2) v IN newouter
        ==> newouter DELETE p v SUBSET
            UNIONS
             {closure k |
              k IN components
               ((:real^2) DIFF plane_graph_carrier V E p c) /\
              v IN plane_graph_face_vertices V E p c k}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk v_boundary newouter_component v_newouter" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding _ _ _ boundary_subset old_outer boundary" THEN
  SUBGOAL_THEN `(v:A) IN V` (LABEL_TAC "v_vertex") THENL
   [USE_THEN "boundary_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "v_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:A->real^2) v IN plane_graph_carrier V E p c`
  (LABEL_TAC "v_oldcarrier") THENL
   [REWRITE_TAC[plane_graph_carrier; IN_UNION] THEN DISJ1_TAC THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `v:A` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET; IN_DELETE] THEN X_GEN_TAC `x:real^2` THEN
  INTRO_TAC "x_newouter x_not_v" THEN
  SUBGOAL_THEN
   `~((x:real^2) IN
      plane_graph_carrier ((V:A->bool) DELETE (v:A))
        (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
        (p:A->real^2) (c:(A->bool)->real^2->bool))`
  (LABEL_TAC "x_not_newcarrier") THENL
   [USE_THEN "newouter_component"
     (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
    REWRITE_TAC[SUBSET; IN_DIFF; IN_UNIV] THEN
    DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[UNIONS_GSPEC; IN_ELIM_THM] THEN
  ASM_CASES_TAC
   `(x:real^2) IN plane_graph_carrier
      (V:A->bool) (E:(A->bool)->bool)
      (p:A->real^2) (c:(A->bool)->real^2->bool)` THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `v:A`; `x:real^2`]
     PLANE_GRAPH_CARRIER_DELETE_VERTEX_POINT_ON_INCIDENT_EDGE) THEN
    ASM_REWRITE_TAC[IN_DIFF] THEN
    INTRO_TAC "@e. e_edge v_edge x_middle" THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `x:real^2`]
     PLANE_GRAPH_CARRIER_POINT_INCIDENT_COMPONENT) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@k. k_component x_frontier" THEN
    SUBGOAL_THEN
     `(c:(A->bool)->real^2->bool) e SUBSET frontier k`
    (LABEL_TAC "edge_frontier") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `e:A->bool`;
        `k:real^2->bool`; `x:real^2`]
       PLANE_GRAPH_EMBEDDING_EDGE_COMPONENT_FRONTIER) THEN
      ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[IN_DIFF] THEN USE_THEN "x_middle" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `v IN plane_graph_face_vertices (V:A->bool) E p c k`
    (LABEL_TAC "v_face") THENL
     [REWRITE_TAC[plane_graph_face_vertices; IN_ELIM_THM] THEN
      CONJ_TAC THENL
       [USE_THEN "v_vertex" ACCEPT_TAC;
        USE_THEN "edge_frontier"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
          `c:(A->bool)->real^2->bool`; `e:A->bool`; `v:A`]
         PLANE_GRAPH_EMBEDDING_EDGE_MEMBER_POINT) THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    EXISTS_TAC `k:real^2->bool` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "x_frontier" MP_TAC THEN
    REWRITE_TAC[frontier; IN_DIFF] THEN MESON_TAC[];
    SUBGOAL_THEN
     `(x:real^2) IN
      UNIONS
       (components
        ((:real^2) DIFF
         plane_graph_carrier (V:A->bool) E p c))`
    (LABEL_TAC "x_components") THENL
     [REWRITE_TAC[GSYM UNIONS_COMPONENTS; IN_DIFF; IN_UNIV] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "x_components" MP_TAC THEN
    REWRITE_TAC[IN_UNIONS] THEN
    INTRO_TAC "@k. k_component x_k" THEN
    SUBGOAL_THEN
     `v IN plane_graph_face_vertices (V:A->bool) E p c k`
    (LABEL_TAC "v_face") THENL
     [ASM_CASES_TAC
       `v IN plane_graph_face_vertices (V:A->bool) E p c k` THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
        `outer:real^2->bool`; `k:real^2->bool`; `v:A`]
       PLANE_TRIANGULATED_DISK_NONINCIDENT_FACE_PERSISTS) THEN
      ASM_REWRITE_TAC[] THEN
      INTRO_TAC "k_newcomponent _" THEN
      SUBGOAL_THEN `(k:real^2->bool) = newouter`
      (LABEL_TAC "k_newouter") THENL
       [MP_TAC(ISPECL
         [`(:real^2) DIFF
           plane_graph_carrier ((V:A->bool) DELETE (v:A))
            (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
            (p:A->real^2) (c:(A->bool)->real^2->bool)`;
          `k:real^2->bool`; `newouter:real^2->bool`]
         COMPONENTS_EQ) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MATCH_MP_TAC(snd(EQ_IMP_RULE th))) THEN
        REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_INTER] THEN
        EXISTS_TAC `x:real^2` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "k_component" (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["v_newouter"; "v_oldcarrier"; "k_newouter"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
      ALL_TAC] THEN
    EXISTS_TAC `k:real^2->bool` THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(REWRITE_RULE[SUBSET]
      (ISPEC `k:real^2->bool` CLOSURE_SUBSET)) THEN
    USE_THEN "x_k" ACCEPT_TAC]);;

let DISTINCT_COMPONENT_CLOSURES_INTER_SUBSET_FRONTIERS = prove
 (`!s k l:real^N->bool.
        k IN components s /\
        l IN components s /\
        ~(k = l)
        ==> closure k INTER closure l SUBSET
            frontier k INTER frontier l`,
  REPEAT GEN_TAC THEN INTRO_TAC "k_component l_component distinct" THEN
  SUBGOAL_THEN `(k:real^N->bool) INTER l = {}`
  (LABEL_TAC "disjoint") THENL
   [MP_TAC(ISPECL
     [`s:real^N->bool`; `k:real^N->bool`; `l:real^N->bool`]
     COMPONENTS_NONOVERLAP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MATCH_MP_TAC(snd(EQ_IMP_RULE th))) THEN
    USE_THEN "distinct" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET; IN_INTER; frontier; IN_DIFF] THEN
  X_GEN_TAC `x:real^N` THEN
  INTRO_TAC "x_closure_k x_closure_l" THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "x_closure_k" ACCEPT_TAC;
    SUBGOAL_THEN
     `interior(k:real^N->bool) INTER closure l = {}`
    (LABEL_TAC "interior_k_disjoint") THENL
     [MP_TAC(ISPECL
       [`interior(k:real^N->bool)`; `l:real^N->bool`]
       OPEN_INTER_CLOSURE_EQ_EMPTY) THEN
      REWRITE_TAC[OPEN_INTERIOR] THEN
      DISCH_THEN(fun th -> MATCH_MP_TAC(snd(EQ_IMP_RULE th))) THEN
      MP_TAC(ISPEC `k:real^N->bool` INTERIOR_SUBSET) THEN
      USE_THEN "disjoint" MP_TAC THEN SET_TAC[];
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["interior_k_disjoint"; "x_closure_l"] THEN
      SET_TAC[]];
    USE_THEN "x_closure_l" ACCEPT_TAC;
    SUBGOAL_THEN
     `interior(l:real^N->bool) INTER closure k = {}`
    (LABEL_TAC "interior_l_disjoint") THENL
     [MP_TAC(ISPECL
       [`interior(l:real^N->bool)`; `k:real^N->bool`]
       OPEN_INTER_CLOSURE_EQ_EMPTY) THEN
      REWRITE_TAC[OPEN_INTERIOR] THEN
      DISCH_THEN(fun th -> MATCH_MP_TAC(snd(EQ_IMP_RULE th))) THEN
