let PLANE_TRIANGULATED_DISK_INCIDENT_FACE_PATCH_INTERSECTION_EDGE =
  prove
 (`!V E p c q n outer v newouter k l x.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        v IN cyclic_vertices q n /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        (p:A->real^2) v IN newouter /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        l IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        ~(k = l) /\
        x IN (newouter DELETE p v) INTER closure k INTER closure l
        ==> ?e:A->bool.
              e IN E /\
              v IN e /\
              c e SUBSET frontier k /\
              c e SUBSET frontier l`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk v_boundary newouter_component v_newouter \
    k_component l_component distinct x_inter" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "graph embedding _ _ _ _ _ _" THEN
  SUBGOAL_THEN
   `(x:real^2) IN newouter /\
    ~((x:real^2) = (p:A->real^2) v) /\
    (x:real^2) IN closure k /\
    (x:real^2) IN closure l`
  (CONJUNCTS_THEN2 (LABEL_TAC "x_newouter")
   (CONJUNCTS_THEN2 (LABEL_TAC "x_not_v")
    (CONJUNCTS_THEN2
     (LABEL_TAC "x_closure_k") (LABEL_TAC "x_closure_l")))) THENL
   [USE_THEN "x_inter" MP_TAC THEN
    REWRITE_TAC[IN_INTER; IN_DELETE] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(x:real^2) IN frontier k /\ x IN frontier l`
  (CONJUNCTS_THEN2
    (LABEL_TAC "x_frontier_k") (LABEL_TAC "x_frontier_l")) THENL
   [MP_TAC(ISPECL
     [`(:real^2) DIFF
       plane_graph_carrier (V:A->bool) E p c`;
      `k:real^2->bool`; `l:real^2->bool`]
     DISTINCT_COMPONENT_CLOSURES_INTER_SUBSET_FRONTIERS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[SUBSET] THEN
    DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN
    ASM_REWRITE_TAC[IN_INTER];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(x:real^2) IN plane_graph_carrier (V:A->bool) E p c`
  (LABEL_TAC "x_oldcarrier") THENL
   [SUBGOAL_THEN
     `frontier(k:real^2->bool) SUBSET
      plane_graph_carrier (V:A->bool) E p c`
    (LABEL_TAC "frontier_subset") THENL
     [MATCH_MP_TAC FRONTIER_OF_COMPONENTS_CLOSED_COMPLEMENT THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC PLANE_GRAPH_CARRIER_CLOSED THEN
      ASM_REWRITE_TAC[];
      USE_THEN "frontier_subset"
       (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "x_frontier_k" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((x:real^2) IN
      plane_graph_carrier ((V:A->bool) DELETE (v:A))
        (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
        (p:A->real^2) (c:(A->bool)->real^2->bool))`
  (LABEL_TAC "x_not_newcarrier") THENL
   [USE_THEN "newouter_component"
     (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
    REWRITE_TAC[SUBSET; IN_DIFF; IN_UNIV] THEN
    DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `v:A`; `x:real^2`]
   PLANE_GRAPH_CARRIER_DELETE_VERTEX_POINT_ON_INCIDENT_EDGE) THEN
  ASM_REWRITE_TAC[IN_DIFF] THEN
  INTRO_TAC "@e. e_edge v_edge x_middle" THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) e SUBSET frontier k`
  (LABEL_TAC "edge_frontier_k") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`;
      `k:real^2->bool`; `x:real^2`]
     PLANE_GRAPH_EMBEDDING_EDGE_COMPONENT_FRONTIER) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[IN_DIFF] THEN USE_THEN "x_middle" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) e SUBSET frontier l`
  (LABEL_TAC "edge_frontier_l") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`;
      `l:real^2->bool`; `x:real^2`]
     PLANE_GRAPH_EMBEDDING_EDGE_COMPONENT_FRONTIER) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[IN_DIFF] THEN USE_THEN "x_middle" ACCEPT_TAC;
    ALL_TAC] THEN
  EXISTS_TAC `e:A->bool` THEN ASM_REWRITE_TAC[]);;

let PLANE_TRIANGULATED_DISK_DELETE_VERTEX_INCIDENT_FACE_SUBSET =
  prove
 (`!V E p c q n outer v newouter k.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        v IN cyclic_vertices q n /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        outer SUBSET newouter /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        v IN plane_graph_face_vertices V E p c k
        ==> k SUBSET newouter DELETE (p:A->real^2) v`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk v_boundary newouter_component outer_subset \
    k_component v_face" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding _ _ _ boundary_subset outer_component boundary" THEN
  SUBGOAL_THEN `(v:A) IN V` (LABEL_TAC "v_vertex") THENL
   [USE_THEN "boundary_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "v_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `v IN plane_graph_face_vertices (V:A->bool) E p c outer`
  (LABEL_TAC "v_outer") THENL
   [USE_THEN "boundary" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "v_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(k:real^2->bool) SUBSET newouter`
  (LABEL_TAC "k_subset") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `v:A`;
      `outer:real^2->bool`; `newouter:real^2->bool`;
      `k:real^2->bool`]
     PLANE_GRAPH_DELETE_VERTEX_INCIDENT_COMPONENT_SUBSET) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:A->real^2) v IN plane_graph_carrier V E p c`
  (LABEL_TAC "v_carrier") THENL
   [REWRITE_TAC[plane_graph_carrier; IN_UNION] THEN DISJ1_TAC THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `v:A` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "k_component" (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
  MAP_EVERY (fun name -> USE_THEN name MP_TAC)
   ["k_subset"; "v_carrier"] THEN
  POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[]);;
let plane_graph_incident_faces = new_definition
 `plane_graph_incident_faces
    (V:A->bool) (E:(A->bool)->bool)
    (p:A->real^2) (c:(A->bool)->real^2->bool) (v:A) =
  {k | k IN components
         ((:real^2) DIFF plane_graph_carrier V E p c) /\
       v IN plane_graph_face_vertices V E p c k}`;;

let PLANE_TRIANGULATED_DISK_INCIDENT_FACES_CROSS_PARTITION = prove
 (`!V E p c q n outer v newouter.
   !g:(real^2->bool)->bool.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        v IN cyclic_vertices q n /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        outer SUBSET newouter /\
        (p:A->real^2) v IN newouter /\
        g SUBSET plane_graph_incident_faces V E p c v /\
        ~(g = {}) /\
        ~(plane_graph_incident_faces V E p c v DIFF g = {})
        ==> ?k l e.
              k IN g /\
              l IN plane_graph_incident_faces V E p c v DIFF g /\
              e IN E /\
              v IN e /\
              c e SUBSET frontier k /\
              c e SUBSET frontier l`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk v_boundary newouter_component outer_subset v_newouter \
    g_subset g_nonempty rest_nonempty" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "graph embedding _ _ _ _ _ _" THEN
  ABBREV_TAC
   `s = newouter DELETE (p:A->real^2) v` THEN
  SUBGOAL_THEN
   `FINITE(plane_graph_incident_faces
      (V:A->bool) E p c v)`
  (LABEL_TAC "faces_finite") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC
     `components
       ((:real^2) DIFF
        plane_graph_carrier (V:A->bool) E p c)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_COMPLEMENT_COMPONENTS_PLANE_GRAPH_CARRIER THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[plane_graph_incident_faces; SUBSET; IN_ELIM_THM] THEN
      MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(g:(real^2->bool)->bool)`
  (LABEL_TAC "g_finite") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC
     `plane_graph_incident_faces
       (V:A->bool) E p c v` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(plane_graph_incident_faces
      (V:A->bool) E p c v DIFF g)`
  (LABEL_TAC "rest_finite") THENL
   [MATCH_MP_TAC FINITE_DIFF THEN
    USE_THEN "faces_finite" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!k:real^2->bool.
      k IN plane_graph_incident_faces
       (V:A->bool) E p c v
      ==> ~(k = {}) /\ k SUBSET s`
  (LABEL_TAC "face_data") THENL
   [X_GEN_TAC `k:real^2->bool` THEN
    REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
    INTRO_TAC "k_component v_face" THEN
    CONJ_TAC THENL
     [USE_THEN "k_component"
       (ACCEPT_TAC o MATCH_MP IN_COMPONENTS_NONEMPTY);
      EXPAND_TAC "s" THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
        `outer:real^2->bool`; `v:A`; `newouter:real^2->bool`;
        `k:real^2->bool`]
       PLANE_TRIANGULATED_DISK_DELETE_VERTEX_INCIDENT_FACE_SUBSET) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `connected(s:real^2->bool)`
  (LABEL_TAC "s_connected") THENL
   [EXPAND_TAC "s" THEN
    MATCH_MP_TAC(ISPECL
     [`plane_graph_carrier ((V:A->bool) DELETE (v:A))
        (induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v))
        (p:A->real^2) (c:(A->bool)->real^2->bool)`;
      `newouter:real^2->bool`; `(p:A->real^2) v`]
     CONNECTED_COMPLEMENT_COMPONENT_DELETE_2) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC PLANE_GRAPH_CARRIER_CLOSED THEN
