    REWRITE_TAC[IN_INTER; UNIONS_GSPEC; IN_ELIM_THM] THEN
    MESON_TAC[];
    INTRO_TAC "@l. l_rest x_closure_l"] THEN
  SUBGOAL_THEN
   `(x:real^2) IN s`
  (LABEL_TAC "x_s") THENL
   [USE_THEN "x_a" MP_TAC THEN
    EXPAND_TAC "a" THEN REWRITE_TAC[IN_INTER] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `k IN plane_graph_incident_faces
     (V:A->bool) E p c v`
  (LABEL_TAC "k_face") THENL
   [USE_THEN "g_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "k_g" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `l IN plane_graph_incident_faces
     (V:A->bool) E p c v`
  (LABEL_TAC "l_face") THENL
