   [USE_THEN "l_rest" MP_TAC THEN
    REWRITE_TAC[IN_DIFF] THEN INTRO_TAC "_ l_not_g" THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["k_g"; "l_not_g"] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "k_face" MP_TAC THEN
  REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
  INTRO_TAC "k_component v_k" THEN
  USE_THEN "l_face" MP_TAC THEN
  REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
  INTRO_TAC "l_component v_l" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `v:A`; `newouter:real^2->bool`;
    `k:real^2->bool`; `l:real^2->bool`; `x:real^2`]
   PLANE_TRIANGULATED_DISK_INCIDENT_FACE_PATCH_INTERSECTION_EDGE) THEN
