  ASM_REWRITE_TAC[] THEN
  USE_THEN "l_rest" MP_TAC THEN
  REWRITE_TAC[plane_graph_incident_faces]);;
let PLANE_GRAPH_EMBEDDING_FRONTIER_EDGE_SUBSET_FACE_VERTICES = prove
 (`!V E p c e k.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e IN E /\
        c e SUBSET frontier k
        ==> e SUBSET plane_graph_face_vertices V E p c k`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph embedding edge edge_frontier" THEN
  SUBGOAL_THEN `(e:A->bool) SUBSET V`
  (LABEL_TAC "edge_vertices") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    INTRO_TAC "_ _ edge_data" THEN
    USE_THEN "edge_data" (fun th ->
      USE_THEN "edge" (fun eth ->
        MP_TAC(MATCH_MP (SPEC `e:A->bool` th) eth))) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET; plane_graph_face_vertices; IN_ELIM_THM] THEN
  X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "u_edge") THEN
  CONJ_TAC THENL
   [USE_THEN "edge_vertices"
     (MATCH_MP_TAC o SPEC `u:A` o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "u_edge" ACCEPT_TAC;
    USE_THEN "edge_frontier"
     (MATCH_MP_TAC o SPEC `(p:A->real^2) u` o REWRITE_RULE[SUBSET]) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`; `u:A`]
     PLANE_GRAPH_EMBEDDING_EDGE_MEMBER_POINT) THEN
    ASM_REWRITE_TAC[]]);;

let PLANE_GRAPH_EMBEDDING_TRIANGULAR_FACE_FRONTIER_EDGE = prove
 (`!V E p c k r e.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        plane_graph_face_vertices V E p c k = cyclic_vertices r 3 /\
        simple_graph_cycle E r 3 /\
        e IN E /\
        c e SUBSET frontier k
        ==> e IN cyclic_edges r 3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding face_vertices cycle edge edge_frontier" THEN
  SUBGOAL_THEN
   `(e:A->bool) SUBSET cyclic_vertices r 3`
  (LABEL_TAC "edge_subset") THENL
   [USE_THEN "face_vertices" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`; `k:real^2->bool`]
     PLANE_GRAPH_EMBEDDING_FRONTIER_EDGE_SUBSET_FACE_VERTICES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(e:A->bool) IN
    induced_subgraph_edges E (cyclic_vertices r 3)`
  (LABEL_TAC "induced_edge") THENL
   [REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:num->A`]
   SIMPLE_GRAPH_CYCLE_3_INDUCED_EDGES) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> USE_THEN "induced_edge"
    (ACCEPT_TAC o REWRITE_RULE[th])));;

let TRIANGLE_CYCLIC_EDGE_AT_0 = prove
 (`!r:num->A. !e.
        ~((r 0:A) = r 1) /\
        ~(r 2 = r 0) /\
        e IN cyclic_edges r 3 /\
        r 0 IN e
        ==> e = {r 0,r 1} \/ e = {r 2,r 0}`,
  REWRITE_TAC[CYCLIC_EDGES_3; IN_INSERT; IN_SING] THEN SET_TAC[]);;

let TRIANGLE_CYCLIC_EDGE_AT_1 = prove
 (`!r:num->A. !e.
        ~((r 0:A) = r 1) /\
        ~(r 1 = r 2) /\
        e IN cyclic_edges r 3 /\
        r 1 IN e
        ==> e = {r 0,r 1} \/ e = {r 1,r 2}`,
  REWRITE_TAC[CYCLIC_EDGES_3; IN_INSERT; IN_SING] THEN SET_TAC[]);;

let TRIANGLE_CYCLIC_EDGE_AT_2 = prove
 (`!r:num->A. !e.
        ~((r 2:A) = r 0) /\
        ~(r 1 = r 2) /\
        e IN cyclic_edges r 3 /\
        r 2 IN e
        ==> e = {r 1,r 2} \/ e = {r 2,r 0}`,
  REWRITE_TAC[CYCLIC_EDGES_3; IN_INSERT; IN_SING] THEN SET_TAC[]);;

let PLANE_TRIANGULATED_DISK_OUTER_FRONTIER_EDGE_AT_LAST = prove
 (`!V E p c q n outer e.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q (n - 1)} IN E)) /\
        e IN E /\
        q (n - 1) IN e /\
        c e SUBSET frontier outer
        ==> e = {q (n - 1),q (n - 2)} \/
            e = {q (n - 1),q 0}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "disk chordless edge last_edge edge_frontier" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN `simple_graph_cycle (E:(A->bool)->bool) q n`
  (LABEL_TAC "cycle") THENL
   [REWRITE_TAC[simple_graph_cycle] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(e:A->bool) SUBSET cyclic_vertices q n`
  (LABEL_TAC "edge_subset") THENL
   [USE_THEN "boundary" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`;
      `outer:real^2->bool`]
     PLANE_GRAPH_EMBEDDING_FRONTIER_EDGE_SUBSET_FACE_VERTICES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`;
    `(q:num->A) (n - 1)`]
   FINITE_SIMPLE_GRAPH_EDGE_THROUGH_MEMBER) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@u. last_vertex u_vertex distinct edge_pair" THEN
  SUBGOAL_THEN
   `(u:A) IN graph_neighbors E (q(n - 1))`
  (LABEL_TAC "u_neighbor") THENL
   [REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
    USE_THEN "edge_pair" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "edge" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(u:A) IN cyclic_vertices q n`
  (LABEL_TAC "u_boundary") THENL
   [USE_THEN "edge_subset"
     (MATCH_MP_TAC o SPEC `u:A` o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "edge_pair" (fun th ->
      REWRITE_TAC[th; IN_INSERT; IN_SING]);
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
    `n:num`; `u:A`]
   BOUNDARY_NEIGHBOR_OF_LAST_WITHOUT_CHORD) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  USE_THEN "edge_pair" (fun th -> REWRITE_TAC[th]));;

let plane_graph_face_adjacent_at = new_definition
 `plane_graph_face_adjacent_at
    (E:(A->bool)->bool) (c:(A->bool)->real^2->bool)
    (v:A) (k:real^2->bool) (l:real^2->bool) <=>
  ~(k = l) /\
  ?e:A->bool.
    e IN E /\
    v IN e /\
    c e SUBSET frontier k /\
    c e SUBSET frontier l`;;

let PLANE_TRIANGULATED_DISK_INCIDENT_FACE_ADJACENCY_DEGREE_2 =
  prove
 (`!V E p c q n outer k l1 l2 l3.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q (n - 1)} IN E)) /\
        k IN plane_graph_incident_faces V E p c (q(n - 1)) /\
        l1 IN plane_graph_incident_faces V E p c (q(n - 1)) /\
        l2 IN plane_graph_incident_faces V E p c (q(n - 1)) /\
        l3 IN plane_graph_incident_faces V E p c (q(n - 1)) /\
        plane_graph_face_adjacent_at E c (q(n - 1)) k l1 /\
        plane_graph_face_adjacent_at E c (q(n - 1)) k l2 /\
        plane_graph_face_adjacent_at E c (q(n - 1)) k l3
        ==> l1 = l2 \/ l1 = l3 \/ l2 = l3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk chordless k_face l1_face l2_face l3_face \
    adjacent1 adjacent2 adjacent3" THEN
  USE_THEN "disk" MP_TAC THEN
