  REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
  INTRO_TAC "l1_component v_l1" THEN
  USE_THEN "l2_face" MP_TAC THEN
  REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
  INTRO_TAC "l2_component v_l2" THEN
  USE_THEN "l3_face" MP_TAC THEN
  REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
  INTRO_TAC "l3_component v_l3" THEN
  USE_THEN "adjacent1" MP_TAC THEN
  REWRITE_TAC[plane_graph_face_adjacent_at] THEN
  INTRO_TAC "k_l1 @e1. e1_edge v_e1 e1_k e1_l1" THEN
