  REWRITE_TAC[plane_graph_face_adjacent_at] THEN
  INTRO_TAC "k_l3 @e3. e3_edge v_e3 e3_k e3_l3" THEN
  SUBGOAL_THEN
   `!e:A->bool. !l m:real^2->bool.
      e IN E /\
      l IN components
       ((:real^2) DIFF plane_graph_carrier V E p c) /\
      m IN components
       ((:real^2) DIFF plane_graph_carrier V E p c) /\
      c e SUBSET frontier k /\
      c e SUBSET frontier l /\
      c e SUBSET frontier m /\
      ~(k = l) /\
