          USE_THEN "e1_edge" ACCEPT_TAC;
          USE_THEN "v_e1" ACCEPT_TAC;
          USE_THEN "k_outer" (fun th ->
            USE_THEN "e1_k" (ACCEPT_TAC o REWRITE_RULE[th]))];
        DISCH_THEN(LABEL_TAC "e1_choice")] THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
