      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [USE_THEN "r20" ACCEPT_TAC;
          USE_THEN "r12" ACCEPT_TAC;
          USE_THEN "e2_triangle" ACCEPT_TAC;
