let FINITE_PLANE_GRAPH_INCIDENT_FACES = prove
 (`!V E p c v.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c
        ==> FINITE(plane_graph_incident_faces V E p c v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph embedding" THEN
  MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC
   `components
     ((:real^2) DIFF
      plane_graph_carrier (V:A->bool) E p c)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_COMPLEMENT_COMPONENTS_PLANE_GRAPH_CARRIER THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[plane_graph_incident_faces; SUBSET; IN_ELIM_THM] THEN
    MESON_TAC[]]);;

let PLANE_GRAPH_FACE_ADJACENT_AT_SYM = prove
 (`!E c v k l.
        plane_graph_face_adjacent_at
          (E:(A->bool)->bool) c v k l <=>
        plane_graph_face_adjacent_at E c v l k`,
  REWRITE_TAC[plane_graph_face_adjacent_at] THEN MESON_TAC[]);;

let PLANE_GRAPH_FACE_ADJACENT_AT_IRREFL = prove
 (`!E c v k.
        ~plane_graph_face_adjacent_at
          (E:(A->bool)->bool) c v k k`,
  REWRITE_TAC[plane_graph_face_adjacent_at]);;

let PLANE_TRIANGULATED_DISK_OUTER_INCIDENT_FACE = prove
 (`!V E p c q n outer v.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        v IN cyclic_vertices q n
        ==> outer IN plane_graph_incident_faces V E p c v`,
  REPEAT GEN_TAC THEN INTRO_TAC "disk v_boundary" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "_ _ _ _ _ _ outer_component boundary" THEN
  REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
  CONJ_TAC THENL
   [USE_THEN "outer_component" ACCEPT_TAC;
    USE_THEN "boundary" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "v_boundary" ACCEPT_TAC]);;

let PLANE_TRIANGULATED_DISK_INCIDENT_FACE_ADJACENCY_CONNECTED =
  prove
 (`!V E p c q n outer v newouter.
   !g:(real^2->bool)->bool.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        v IN cyclic_vertices q n /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE v)
             (induced_subgraph_edges E (V DELETE v)) p c) /\
        outer SUBSET newouter /\
        (p:A->real^2) v IN newouter /\
        g SUBSET plane_graph_incident_faces V E p c v /\
        ~(g = {}) /\
        ~(plane_graph_incident_faces V E p c v DIFF g = {})
        ==> ?k l.
              k IN g /\
              l IN plane_graph_incident_faces V E p c v DIFF g /\
              plane_graph_face_adjacent_at E c v k l`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk v_boundary newouter_component outer_subset v_newouter \
    g_subset g_nonempty rest_nonempty" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `v:A`; `newouter:real^2->bool`;
    `g:(real^2->bool)->bool`]
   PLANE_TRIANGULATED_DISK_INCIDENT_FACES_CROSS_PARTITION) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "disk" ACCEPT_TAC;
      USE_THEN "v_boundary" ACCEPT_TAC;
      USE_THEN "newouter_component" ACCEPT_TAC;
      USE_THEN "outer_subset" ACCEPT_TAC;
      USE_THEN "v_newouter" ACCEPT_TAC;
      USE_THEN "g_subset" ACCEPT_TAC;
      USE_THEN "g_nonempty" ACCEPT_TAC;
      USE_THEN "rest_nonempty" ACCEPT_TAC];
    INTRO_TAC "@k l e. k_g l_rest e_edge v_edge e_k e_l"] THEN
  MAP_EVERY EXISTS_TAC [`k:real^2->bool`; `l:real^2->bool`] THEN
  CONJ_TAC THENL
   [USE_THEN "k_g" ACCEPT_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "l_rest" ACCEPT_TAC;
    REWRITE_TAC[plane_graph_face_adjacent_at] THEN
    CONJ_TAC THENL
     [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["k_g"; "l_rest"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN
      REWRITE_TAC[IN_DIFF] THEN MESON_TAC[];
      EXISTS_TAC `e:A->bool` THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "e_edge" ACCEPT_TAC;
        USE_THEN "v_edge" ACCEPT_TAC;
        USE_THEN "e_k" ACCEPT_TAC;
        USE_THEN "e_l" ACCEPT_TAC]]]);;
let finite_relation_path = new_definition
 `finite_relation_path
    (R:A->A->bool) (s:A->bool) (f:num->A) n <=>
  (!i. i < n ==> f i IN s) /\
  (!i j. i < n /\ j < n /\ f i = f j ==> i = j) /\
  (!i. i + 1 < n ==> R (f i) (f(i + 1)))`;;

let FINITE_RELATION_PATH_APPEND = prove
 (`!R:A->A->bool. !s f n y.
        finite_relation_path R s f n /\
        0 < n /\
        y IN s /\
        ~(?i. i < n /\ f i = y) /\
        R (f(n - 1)) y
        ==> finite_relation_path R s
             (\i. if i < n then f i else y) (n + 1)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[finite_relation_path] THEN
  INTRO_TAC
   "(vertices injective chain) positive y_vertex y_new last_edge" THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "i_bound") THEN
    COND_CASES_TAC THEN ASM_MESON_TAC[];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
    INTRO_TAC "i_bound j_bound equal" THEN
    REMOVE_THEN "equal" MP_TAC THEN
    REPEAT COND_CASES_TAC THEN
    DISCH_THEN(LABEL_TAC "equal") THENL
     [USE_THEN "injective" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      USE_THEN "y_new" MP_TAC THEN
      REWRITE_TAC[NOT_EXISTS_THM] THEN ASM_MESON_TAC[];
      USE_THEN "y_new" MP_TAC THEN
      REWRITE_TAC[NOT_EXISTS_THM] THEN ASM_MESON_TAC[];
      ASM_ARITH_TAC];
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "step_bound") THEN
    USE_THEN "step_bound" (fun th ->
      LABEL_TAC "i_old"
       (MATCH_MP
         (ARITH_RULE `i + 1 < (n:num) + 1 ==> i < n`) th)) THEN
    USE_THEN "i_old" (fun th -> REWRITE_TAC[th]) THEN
    COND_CASES_TAC THENL
     [USE_THEN "chain" (MP_TAC o SPEC `i:num`) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        DISCH_THEN ACCEPT_TAC];
      FIRST_X_ASSUM(LABEL_TAC "last_step") THEN
      USE_THEN "positive" (fun pth ->
        USE_THEN "i_old" (fun ith ->
          USE_THEN "last_step" (fun lth ->
            MP_TAC(MATCH_MP
             (ARITH_RULE
              `0 < (n:num) /\ i < n /\ ~(i + 1 < n)
               ==> i = n - 1`)
             (CONJ pth (CONJ ith lth)))))) THEN
      DISCH_THEN SUBST1_TAC THEN
      USE_THEN "last_edge" MP_TAC THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[]]]);;

let FINITE_RELATION_PATH_PREPEND = prove
 (`!R:A->A->bool. !s f n y.
        finite_relation_path R s f n /\
        0 < n /\
        y IN s /\
        ~(?i. i < n /\ f i = y) /\
        R y (f 0)
        ==> finite_relation_path R s
             (\i. if i = 0 then y else f(i - 1)) (n + 1)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[finite_relation_path] THEN
  INTRO_TAC
   "(vertices injective chain) positive y_vertex y_new first_edge" THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "i_bound") THEN
    COND_CASES_TAC THEN ASM_MESON_TAC[ARITH_RULE
     `i < n + 1 /\ ~(i = 0) ==> i - 1 < n`];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
    INTRO_TAC "i_bound j_bound equal" THEN
    REMOVE_THEN "equal" MP_TAC THEN
    REPEAT COND_CASES_TAC THEN
    DISCH_THEN(LABEL_TAC "equal") THENL
     [ASM_REWRITE_TAC[];
      USE_THEN "y_new" MP_TAC THEN
      REWRITE_TAC[NOT_EXISTS_THM] THEN ASM_MESON_TAC[ARITH_RULE
       `j < n + 1 /\ ~(j = 0) ==> j - 1 < n`];
      USE_THEN "y_new" MP_TAC THEN
      REWRITE_TAC[NOT_EXISTS_THM] THEN ASM_MESON_TAC[ARITH_RULE
       `i < n + 1 /\ ~(i = 0) ==> i - 1 < n`];
      SUBGOAL_THEN `i - 1 = j - 1` MP_TAC THENL
       [USE_THEN "injective" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        ASM_ARITH_TAC]];
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "step_bound") THEN
    SUBGOAL_THEN `~(i + 1 = 0)`
    (fun th -> REWRITE_TAC[th]) THENL
     [ARITH_TAC;
      ALL_TAC] THEN
    COND_CASES_TAC THENL
     [ASM_REWRITE_TAC[ARITH_RULE `0 + 1 = 1`;
                      ARITH_RULE `1 - 1 = 0`];
      SUBGOAL_THEN `(i - 1) + 1 = i`
      (LABEL_TAC "pred_suc") THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      REWRITE_TAC[ARITH_RULE `(i + 1) - 1 = i`] THEN
      USE_THEN "chain" (MP_TAC o SPEC `i - 1`) THEN
      ANTS_TAC THENL
       [ASM_ARITH_TAC;
        DISCH_THEN(fun th ->
         USE_THEN "pred_suc" (fun eq -> ACCEPT_TAC(REWRITE_RULE[eq] th)))]]]);;

let FINITE_RELATION_PATH_LENGTH_LE = prove
 (`!R:A->A->bool. !s f n.
        FINITE s /\ finite_relation_path R s f n
        ==> n <= CARD s`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[finite_relation_path] THEN
  INTRO_TAC "finite (vertices injective chain)" THEN
  SUBGOAL_THEN
   `IMAGE (f:num->A) (cyclic_indices n) SUBSET s`
  (LABEL_TAC "image_subset") THENL
   [REWRITE_TAC[SUBSET; IN_IMAGE; IN_CYCLIC_INDICES] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(IMAGE (f:num->A) (cyclic_indices n)) = n`
  (LABEL_TAC "image_card") THENL
   [TRANS_TAC EQ_TRANS `CARD(cyclic_indices n)` THEN CONJ_TAC THENL
     [MATCH_MP_TAC CARD_IMAGE_INJ THEN
      CONJ_TAC THENL
       [REWRITE_TAC[IN_CYCLIC_INDICES] THEN
        USE_THEN "injective" ACCEPT_TAC;
        REWRITE_TAC[FINITE_CYCLIC_INDICES]];
      REWRITE_TAC[CARD_CYCLIC_INDICES]];
    ALL_TAC] THEN
  USE_THEN "image_card" (fun th -> REWRITE_TAC[GSYM th]) THEN
  MP_TAC(ISPECL
   [`IMAGE (f:num->A) (cyclic_indices n)`; `s:A->bool`]
   CARD_SUBSET) THEN
  ASM_REWRITE_TAC[]);;

let FINITE_CONNECTED_DEGREE_2_RELATION_SPANNING_PATH = prove
 (`!s:A->bool. !R:A->A->bool.
        FINITE s /\
        ~(s = {}) /\
        (!x y. x IN s /\ y IN s /\ R x y ==> R y x) /\
        (!t. t SUBSET s /\ ~(t = {}) /\ ~(s DIFF t = {})
             ==> ?x y. x IN t /\ y IN s DIFF t /\ R x y) /\
        (!x y1 y2 y3.
             x IN s /\ y1 IN s /\ y2 IN s /\ y3 IN s /\
             R x y1 /\ R x y2 /\ R x y3
             ==> y1 = y2 \/ y1 = y3 \/ y2 = y3)
        ==> ?n f.
              0 < n /\
              finite_relation_path R s f n /\
              IMAGE f (cyclic_indices n) = s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite nonempty symmetric cut_connected degree2" THEN
  USE_THEN "nonempty" MP_TAC THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (LABEL_TAC "a_vertex")) THEN
  SUBGOAL_THEN
   `finite_relation_path (R:A->A->bool) s (\i. a) 1`
  (LABEL_TAC "singleton_path") THENL
   [REWRITE_TAC[finite_relation_path] THEN REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      REPEAT STRIP_TAC THEN ASM_ARITH_TAC;
      ARITH_TAC];
    ALL_TAC] THEN
  MP_TAC(fst(EQ_IMP_RULE
   (ISPEC `\m. ?f:num->A. finite_relation_path R s f m`
     num_MAX))) THEN
  MATCH_MP_TAC(TAUT
   `p /\ (q ==> r) ==> (p ==> q) ==> r`) THEN
  CONJ_TAC THENL
   [CONJ_TAC THENL
     [EXISTS_TAC `1` THEN BETA_TAC THEN
      EXISTS_TAC `\i:num. a:A` THEN
      USE_THEN "singleton_path" ACCEPT_TAC;
      EXISTS_TAC `CARD(s:A->bool)` THEN
      X_GEN_TAC `m:num` THEN BETA_TAC THEN
      DISCH_THEN(X_CHOOSE_THEN `h:num->A`
       (LABEL_TAC "bounded_path")) THEN
      MP_TAC(ISPECL
       [`R:A->A->bool`; `s:A->bool`; `h:num->A`; `m:num`]
       FINITE_RELATION_PATH_LENGTH_LE) THEN
      ASM_REWRITE_TAC[]];
    DISCH_THEN(X_CHOOSE_THEN `n:num` MP_TAC) THEN
    BETA_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2
     (X_CHOOSE_THEN `f:num->A` (LABEL_TAC "path"))
     (LABEL_TAC "maximal"))] THEN
  SUBGOAL_THEN `0 < n` (LABEL_TAC "positive") THENL
   [USE_THEN "maximal" (MP_TAC o SPEC `1`) THEN
    ANTS_TAC THENL
     [EXISTS_TAC `\i:num. a:A` THEN
      USE_THEN "singleton_path" ACCEPT_TAC;
      DISCH_THEN MP_TAC THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(?h:num->A. finite_relation_path R s h (n + 1))`
  (LABEL_TAC "unextendable") THENL
   [REWRITE_TAC[NOT_EXISTS_THM] THEN
    X_GEN_TAC `h:num->A` THEN
    DISCH_THEN(LABEL_TAC "longer_path") THEN
    USE_THEN "maximal" (MP_TAC o SPEC `n + 1`) THEN
    ANTS_TAC THENL
     [EXISTS_TAC `h:num->A` THEN
      USE_THEN "longer_path" ACCEPT_TAC;
      DISCH_THEN MP_TAC THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN ARITH_TAC];
    ALL_TAC] THEN
  ABBREV_TAC
   `t = IMAGE (f:num->A) (cyclic_indices n)` THEN
  SUBGOAL_THEN `(t:A->bool) SUBSET s`
  (LABEL_TAC "t_subset") THENL
   [EXPAND_TAC "t" THEN
    REWRITE_TAC[SUBSET; IN_IMAGE; IN_CYCLIC_INDICES] THEN
    USE_THEN "path" MP_TAC THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN
    REWRITE_TAC[finite_relation_path] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((t:A->bool) = {})`
  (LABEL_TAC "t_nonempty") THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `(f:num->A) 0` THEN
    EXPAND_TAC "t" THEN REWRITE_TAC[IN_IMAGE] THEN
    EXISTS_TAC `0` THEN ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
    ALL_TAC] THEN
  ASM_CASES_TAC `(t:A->bool) = s` THENL
   [EXISTS_TAC `n:num` THEN EXISTS_TAC `f:num->A` THEN
    ASM_REWRITE_TAC[] THEN EXPAND_TAC "t" THEN ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "t_ne_s")] THEN
