    POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
    ALL_TAC] THEN
  USE_THEN "cut_connected" (MP_TAC o SPEC `t:A->bool`) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC "@x y. x_t y_rest xy"] THEN
  USE_THEN "x_t" MP_TAC THEN EXPAND_TAC "t" THEN
  REWRITE_TAC[IN_IMAGE; IN_CYCLIC_INDICES] THEN
  INTRO_TAC "@j. x_eq j_bound" THEN
  USE_THEN "x_eq" (fun th ->
    USE_THEN "xy"
     (LABEL_TAC "jy" o REWRITE_RULE[th])) THEN
  USE_THEN "y_rest" MP_TAC THEN
  REWRITE_TAC[IN_DIFF] THEN
  INTRO_TAC "y_vertex y_not_t" THEN
  SUBGOAL_THEN `~(?i. i < n /\ (f:num->A) i = y)`
  (LABEL_TAC "y_new") THENL
   [USE_THEN "y_not_t" MP_TAC THEN EXPAND_TAC "t" THEN
    REWRITE_TAC[IN_IMAGE; IN_CYCLIC_INDICES] THEN MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "path" MP_TAC THEN
  REWRITE_TAC[finite_relation_path] THEN
  DISCH_THEN(CONJUNCTS_THEN2
   (LABEL_TAC "vertices")
   (CONJUNCTS_THEN2
    (LABEL_TAC "injective") (LABEL_TAC "chain"))) THEN
  DISJ_CASES_THEN2 (LABEL_TAC "j_zero") (LABEL_TAC "j_nonzero")
   (SPEC `j = 0` EXCLUDED_MIDDLE) THENL
   [REMOVE_THEN "j_zero" SUBST_VAR_TAC THEN
    SUBGOAL_THEN `(f:num->A) 0 IN s`
    (LABEL_TAC "first_vertex") THENL
     [USE_THEN "vertices" (MP_TAC o SPEC `0`) THEN
      DISCH_THEN(fun th ->
        USE_THEN "positive" (ACCEPT_TAC o MATCH_MP th));
