    USE_THEN "symmetric" (fun sth ->
      USE_THEN "first_vertex" (fun fvth ->
        USE_THEN "y_vertex" (fun yth ->
          USE_THEN "jy" (fun rth ->
            MP_TAC
             (MATCH_MP
              (SPECL [`(f:num->A) 0`; `y:A`] sth)
              (CONJ fvth (CONJ yth rth))))))) THEN
    DISCH_THEN(LABEL_TAC "first_edge") THEN
    MP_TAC(ISPECL
     [`R:A->A->bool`; `s:A->bool`; `f:num->A`; `n:num`; `y:A`]
     FINITE_RELATION_PATH_PREPEND) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "path" ACCEPT_TAC;
        USE_THEN "positive" ACCEPT_TAC;
        USE_THEN "y_vertex" ACCEPT_TAC;
        USE_THEN "y_new" ACCEPT_TAC;
        USE_THEN "first_edge" ACCEPT_TAC];
      ALL_TAC] THEN
    DISCH_THEN(LABEL_TAC "extended") THEN
    USE_THEN "unextendable" (fun uth ->
      USE_THEN "extended" (fun eth ->
        CONTR_TAC(MP (NOT_ELIM uth)
         (EXISTS
          (`?h:num->A. finite_relation_path R s h (n + 1)`,
           `\i. if i = 0 then y else (f:num->A)(i - 1)`)
          eth))));
    ALL_TAC] THEN
  ASM_CASES_TAC `j + 1 = n` THENL
   [SUBGOAL_THEN `j = n - 1` (LABEL_TAC "j_last") THENL
     [MATCH_MP_TAC(ARITH_RULE
       `j < (n:num) /\ j + 1 = n ==> j = n - 1`) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`R:A->A->bool`; `s:A->bool`; `f:num->A`; `n:num`; `y:A`]
     FINITE_RELATION_PATH_APPEND) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "j_last" (fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(LABEL_TAC "extended") THEN
    USE_THEN "unextendable" MP_TAC THEN
    REWRITE_TAC[NOT_EXISTS_THM] THEN
    DISCH_THEN(MP_TAC o SPEC
     `\i. if i < n then (f:num->A) i else y`) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `0 < j /\ j + 1 < n`
  (CONJUNCTS_THEN2
   (LABEL_TAC "j_positive") (LABEL_TAC "j_next")) THENL
   [MATCH_MP_TAC(ARITH_RULE
     `~(j = 0) /\ j < (n:num) /\ ~(j + 1 = n)
      ==> 0 < j /\ j + 1 < n`) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(j - 1) + 1 = j`
  (LABEL_TAC "pred_suc") THENL
   [MATCH_MP_TAC(ARITH_RULE
     `0 < (j:num) ==> (j - 1) + 1 = j`) THEN
    USE_THEN "j_positive" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "chain" (fun cth ->
    USE_THEN "pred_suc" (fun pth ->
      USE_THEN "j_bound" (fun jth ->
        USE_THEN "vertices" (fun vth ->
          USE_THEN "symmetric" (fun sth ->
            let predecessor_bound =
              EQ_MP
               (SYM(BETA_RULE(AP_TERM `\k:num. k < n` pth))) jth in
            let previous_forward =
              EQ_MP
               (BETA_RULE
                (AP_TERM
                 `\z:A. (R:A->A->bool) ((f:num->A)(j - 1)) z`
                 (AP_TERM `f:num->A` pth)))
               (MATCH_MP (SPEC `j - 1` cth) predecessor_bound) in
            let previous_index_bound =
              MATCH_MP
               (ARITH_RULE `j < (n:num) ==> j - 1 < n`) jth in
            let previous_vertex =
              MATCH_MP (SPEC `j - 1` vth) previous_index_bound in
            let center_vertex = MATCH_MP (SPEC `j:num` vth) jth in
            LABEL_TAC "previous_edge"
             (MATCH_MP
              (SPECL
               [`(f:num->A)(j - 1)`; `(f:num->A) j`] sth)
              (CONJ previous_vertex
               (CONJ center_vertex previous_forward)))))))) THEN
  USE_THEN "chain" (fun cth ->
    USE_THEN "j_next" (fun jth ->
      LABEL_TAC "next_edge" (MATCH_MP (SPEC `j:num` cth) jth))) THEN
  USE_THEN "degree2" (MP_TAC o SPECL
   [`(f:num->A) j`; `y:A`; `(f:num->A)(j - 1)`;
    `(f:num->A)(j + 1)`]) THEN
