   [REPEAT CONJ_TAC THENL
     [USE_THEN "vertices" MATCH_MP_TAC THEN
      USE_THEN "j_bound" ACCEPT_TAC;
      USE_THEN "y_vertex" ACCEPT_TAC;
      USE_THEN "vertices" MATCH_MP_TAC THEN ASM_ARITH_TAC;
      USE_THEN "vertices" MATCH_MP_TAC THEN
      USE_THEN "j_next" ACCEPT_TAC;
      USE_THEN "jy" ACCEPT_TAC;
      USE_THEN "previous_edge" ACCEPT_TAC;
      USE_THEN "next_edge" ACCEPT_TAC];
    DISCH_THEN(DISJ_CASES_THEN2
     (LABEL_TAC "y_previous")
     (DISJ_CASES_THEN2
      (LABEL_TAC "y_next") (LABEL_TAC "neighbors_equal")))] THENL
   [USE_THEN "y_new" (fun nth ->
      USE_THEN "j_bound" (fun jth ->
        USE_THEN "y_previous" (fun eth ->
          let bth = MATCH_MP
           (ARITH_RULE `j < (n:num) ==> j - 1 < n`) jth in
          let witness = EXISTS
           (`?i. i < n /\ (f:num->A) i = y`, `j - 1`)
           (CONJ bth (SYM eth)) in
          CONTR_TAC(MP (NOT_ELIM nth) witness))));
    USE_THEN "y_new" (fun nth ->
      USE_THEN "j_next" (fun jth ->
        USE_THEN "y_next" (fun eth ->
          let witness = EXISTS
           (`?i. i < n /\ (f:num->A) i = y`, `j + 1`)
           (CONJ jth (SYM eth)) in
          CONTR_TAC(MP (NOT_ELIM nth) witness))));
    USE_THEN "injective" (fun ith ->
      USE_THEN "j_bound" (fun jth ->
        USE_THEN "j_next" (fun jnth ->
          USE_THEN "j_positive" (fun jpth ->
            USE_THEN "neighbors_equal" (fun eth ->
              let previous_bound = MATCH_MP
               (ARITH_RULE `j < (n:num) ==> j - 1 < n`) jth in
              let indices_equal = MATCH_MP
               (SPECL [`j - 1`; `j + 1`] ith)
               (CONJ previous_bound (CONJ jnth eth)) in
              let indices_distinct = MATCH_MP
               (ARITH_RULE
                `0 < (j:num) ==> ~(j - 1 = j + 1)`) jpth in
              CONTR_TAC(MP (NOT_ELIM indices_distinct)
               indices_equal))))))]);;
let PLANE_TRIANGULATED_DISK_INCIDENT_FACE_ADJACENCY_SPANNING_PATH =
  prove
 (`!V E p c q n outer newouter.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q (n - 1)} IN E)) /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE q(n - 1))
             (induced_subgraph_edges E (V DELETE q(n - 1))) p c) /\
        outer SUBSET newouter /\
        (p:A->real^2) (q(n - 1)) IN newouter
        ==> ?m h.
              0 < m /\
              finite_relation_path
                (plane_graph_face_adjacent_at E c (q(n - 1)))
                (plane_graph_incident_faces V E p c (q(n - 1)))
                h m /\
              IMAGE h (cyclic_indices m) =
                plane_graph_incident_faces V E p c (q(n - 1))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk chordless newouter_component outer_subset last_newouter" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  MATCH_MP_TAC(ISPECL
   [`plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1))`;
    `plane_graph_face_adjacent_at
      (E:(A->bool)->bool) c (q(n - 1))`]
   FINITE_CONNECTED_DEGREE_2_RELATION_SPANNING_PATH) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_PLANE_GRAPH_INCIDENT_FACES THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `outer:real^2->bool` THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `(q:num->A)(n - 1)`]
     PLANE_TRIANGULATED_DISK_OUTER_INCIDENT_FACE) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC;
    MAP_EVERY X_GEN_TAC
     [`k:real^2->bool`; `l:real^2->bool`] THEN
    INTRO_TAC "k_face l_face adjacent" THEN
    USE_THEN "adjacent" MP_TAC THEN
    REWRITE_TAC[PLANE_GRAPH_FACE_ADJACENT_AT_SYM];
    X_GEN_TAC `t:(real^2->bool)->bool` THEN
    INTRO_TAC "t_subset t_nonempty rest_nonempty" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `(q:num->A)(n - 1)`;
      `newouter:real^2->bool`; `t:(real^2->bool)->bool`]
     PLANE_TRIANGULATED_DISK_INCIDENT_FACE_ADJACENCY_CONNECTED) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC;
    MAP_EVERY X_GEN_TAC
     [`k:real^2->bool`; `l1:real^2->bool`;
      `l2:real^2->bool`; `l3:real^2->bool`] THEN
    INTRO_TAC
     "k_face l1_face l2_face l3_face adjacent1 adjacent2 adjacent3" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `k:real^2->bool`;
      `l1:real^2->bool`; `l2:real^2->bool`; `l3:real^2->bool`]
     PLANE_TRIANGULATED_DISK_INCIDENT_FACE_ADJACENCY_DEGREE_2) THEN
    ASM_REWRITE_TAC[]]);;
let PLANE_TRIANGULATED_DISK_INCIDENT_FACE_ADJACENCY_SPANNING_PATH_OUTER =
  prove
 (`!V E p c q n outer newouter.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q (n - 1)} IN E)) /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE q(n - 1))
             (induced_subgraph_edges E (V DELETE q(n - 1))) p c) /\
        outer SUBSET newouter /\
        (p:A->real^2) (q(n - 1)) IN newouter
        ==> ?m h r.
              0 < m /\
              finite_relation_path
                (plane_graph_face_adjacent_at E c (q(n - 1)))
                (plane_graph_incident_faces V E p c (q(n - 1)))
                h m /\
              IMAGE h (cyclic_indices m) =
                plane_graph_incident_faces V E p c (q(n - 1)) /\
              r < m /\
              h r = outer`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk chordless newouter_component outer_subset last_newouter" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `newouter:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INCIDENT_FACE_ADJACENCY_SPANNING_PATH) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@m h. positive path coverage" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "_ _ nlarge _ _ _ _ _" THEN
  SUBGOAL_THEN
   `outer IN plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1))`
  (LABEL_TAC "outer_face") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `(q:num->A)(n - 1)`]
     PLANE_TRIANGULATED_DISK_OUTER_INCIDENT_FACE) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "outer_face" MP_TAC THEN
  USE_THEN "coverage" (fun th -> REWRITE_TAC[GSYM th]) THEN
  REWRITE_TAC[IN_IMAGE; IN_CYCLIC_INDICES] THEN
  INTRO_TAC "@r. point bound" THEN
  MAP_EVERY EXISTS_TAC [`m:num`; `h:num->real^2->bool`; `r:num`] THEN
  ASM_REWRITE_TAC[]);;
let FINITE_RELATION_PATH_CYCLIC_OFFSET = prove
 (`!R:A->A->bool. !s f n r.
        finite_relation_path R s f n /\
        R (f(n - 1)) (f 0) /\
        r < n
        ==> finite_relation_path R s
             (\i. f((i + r) MOD n)) n /\
            IMAGE (\i. f((i + r) MOD n)) (cyclic_indices n) =
              IMAGE f (cyclic_indices n) /\
            f((0 + r) MOD n) = f r`,
  REPEAT GEN_TAC THEN INTRO_TAC "path closing r_index" THEN
  SUBGOAL_THEN `0 < (n:num)` (LABEL_TAC "positive") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "path" MP_TAC THEN
  REWRITE_TAC[finite_relation_path] THEN
  INTRO_TAC "vertices injective chain" THEN
  SUBGOAL_THEN `INJ (f:num->A) (cyclic_indices n) (:A)`
  (LABEL_TAC "f_injective") THENL
   [REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    USE_THEN "injective" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `INJ (\i. (f:num->A)((i + r) MOD n))
        (cyclic_indices n) (:A)`
  (LABEL_TAC "offset_injective") THENL
   [MATCH_MP_TAC INJ_CYCLIC_OFFSET THEN
    USE_THEN "f_injective" ACCEPT_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[finite_relation_path] THEN
    REPEAT CONJ_TAC THENL
     [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "i_index") THEN
      BETA_TAC THEN
      USE_THEN "vertices" MATCH_MP_TAC THEN
      REWRITE_TAC[MOD_LT_EQ_LT] THEN ASM_ARITH_TAC;
      USE_THEN "offset_injective" MP_TAC THEN
      REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES];
      X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "next_index") THEN
      BETA_TAC THEN
      SUBGOAL_THEN `(i + 1) MOD n = i + 1`
      (LABEL_TAC "next_mod") THENL
       [MATCH_MP_TAC MOD_LT THEN
        USE_THEN "next_index" ACCEPT_TAC;
        ALL_TAC] THEN
      MP_TAC(SPECL [`n:num`; `r:num`; `i:num`]
       CYCLIC_OFFSET_SUCCESSOR) THEN
      USE_THEN "next_mod" (fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(LABEL_TAC "successor_offset") THEN
      USE_THEN "successor_offset" (fun th -> REWRITE_TAC[th]) THEN
      SUBGOAL_THEN `(i + r) MOD n < n`
      (LABEL_TAC "offset_index") THENL
       [REWRITE_TAC[MOD_LT_EQ_LT] THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      ASM_CASES_TAC `((i + r) MOD n) + 1 < n` THENL
       [SUBGOAL_THEN
         `(((i + r) MOD n) + 1) MOD n =
          ((i + r) MOD n) + 1`
        (fun th -> REWRITE_TAC[th]) THENL
         [MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[];
          USE_THEN "chain" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
        SUBGOAL_THEN `(i + r) MOD n = n - 1`
        (LABEL_TAC "last_offset") THENL
         [ASM_ARITH_TAC;
          USE_THEN "last_offset" (fun th -> REWRITE_TAC[th]) THEN
          SUBGOAL_THEN `(n - 1) + 1 = n`
          (fun th -> REWRITE_TAC[th; MOD_REFL]) THENL
           [ASM_ARITH_TAC;
            USE_THEN "closing" ACCEPT_TAC]]]];
    CONJ_TAC THENL
     [MP_TAC(SPECL [`f:num->A`; `n:num`; `r:num`]
       CYCLIC_VERTICES_OFFSET) THEN
      REWRITE_TAC[cyclic_vertices];
      ASM_SIMP_TAC[MOD_LT; ADD_CLAUSES]]]);;
let FINITE_RELATION_PATH_ENDPOINTS_RELATED = prove
 (`!R:A->A->bool. !s f n.
        3 <= n /\
        finite_relation_path R s f n /\
        IMAGE f (cyclic_indices n) = s /\
        (!x. x IN s ==> ~R x x) /\
        (!x y. x IN s /\ y IN s /\ R x y ==> R y x) /\
        (!x. x IN s
             ==> ?y z.
                   y IN s /\ z IN s /\ ~(y = z) /\ R x y /\ R x z) /\
        (!x y1 y2 y3.
             x IN s /\ y1 IN s /\ y2 IN s /\ y3 IN s /\
             R x y1 /\ R x y2 /\ R x y3
             ==> y1 = y2 \/ y1 = y3 \/ y2 = y3)
        ==> R (f(n - 1)) (f 0)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "large path coverage irreflexive symmetric degree_at_least_2 \
    degree_at_most_2" THEN
  USE_THEN "path" MP_TAC THEN
  REWRITE_TAC[finite_relation_path] THEN
  INTRO_TAC "vertices injective relation_chain" THEN
  SUBGOAL_THEN
   `(f:num->A) 0 IN s /\ f 1 IN s /\ f(n - 1) IN s`
  (CONJUNCTS_THEN2 (LABEL_TAC "first_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "second_vertex")
    (LABEL_TAC "last_vertex"))) THENL
   [REPEAT CONJ_TAC THEN
    USE_THEN "vertices" MATCH_MP_TAC THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(R:A->A->bool) ((f:num->A) 0) (f 1)`
  (LABEL_TAC "first_edge") THENL
   [USE_THEN "relation_chain" (MP_TAC o SPEC `0`) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[ADD_CLAUSES]];
    ALL_TAC] THEN
  USE_THEN "degree_at_least_2" (MP_TAC o SPEC `(f:num->A) 0`) THEN
  ANTS_TAC THENL
   [USE_THEN "first_vertex" ACCEPT_TAC;
    INTRO_TAC
     "@y z. y_vertex z_vertex y_z y_edge z_edge"] THEN
  USE_THEN "degree_at_most_2"
   (MP_TAC o SPECL
     [`(f:num->A) 0`; `y:A`; `z:A`; `(f:num->A) 1`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(LABEL_TAC "one_is_second")] THEN
  SUBGOAL_THEN
   `?u:A.
      u IN s /\
      ~(u = (f:num->A) 0) /\
      ~(u = f 1) /\
      (R:A->A->bool) (f 0) u`
  MP_TAC THENL
   [USE_THEN "irreflexive" (MP_TAC o SPEC `(f:num->A) 0`) THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["first_vertex"; "y_vertex"; "z_vertex"; "y_z";
      "y_edge"; "z_edge"; "one_is_second"] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[];
    INTRO_TAC "@u. u_vertex u_not_first u_not_second u_edge"] THEN
  USE_THEN "u_vertex" MP_TAC THEN
  USE_THEN "coverage" (fun th -> REWRITE_TAC[GSYM th]) THEN
  REWRITE_TAC[IN_IMAGE; IN_CYCLIC_INDICES] THEN
  INTRO_TAC "@j. u_point j_index" THEN
  SUBGOAL_THEN `(j:num) = n - 1`
  (LABEL_TAC "j_last") THENL
   [ASM_CASES_TAC `(j:num) = n - 1` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `1 < (j:num) /\ j + 1 < n`
    (CONJUNCTS_THEN2 (LABEL_TAC "j_after_second")
     (LABEL_TAC "j_before_last")) THENL
     [SUBGOAL_THEN `~((j:num) = 0) /\ ~(j = 1)`
      STRIP_ASSUME_TAC THENL
       [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
         ["u_not_first"; "u_not_second"; "u_point"] THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[];
        ASM_ARITH_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(f:num->A) (j - 1) IN s /\ f(j + 1) IN s`
    (CONJUNCTS_THEN2 (LABEL_TAC "previous_vertex")
     (LABEL_TAC "next_vertex")) THENL
     [CONJ_TAC THEN USE_THEN "vertices" MATCH_MP_TAC THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(R:A->A->bool) ((f:num->A) j) (f(j - 1)) /\
      R (f j) (f(j + 1))`
    (CONJUNCTS_THEN2 (LABEL_TAC "previous_edge")
     (LABEL_TAC "next_edge")) THENL
     [CONJ_TAC THENL
       [USE_THEN "symmetric"
         (MP_TAC o SPECL [`(f:num->A)(j - 1)`; `(f:num->A) j`]) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THENL
           [USE_THEN "previous_vertex" ACCEPT_TAC;
            USE_THEN "u_point" (fun th ->
              USE_THEN "u_vertex" (ACCEPT_TAC o REWRITE_RULE[th]));
            SUBGOAL_THEN `(j - 1) + 1 = j`
            (LABEL_TAC "previous_successor") THENL
             [ASM_ARITH_TAC;
              USE_THEN "relation_chain" (MP_TAC o SPEC `j - 1`) THEN
              ANTS_TAC THENL
               [ASM_ARITH_TAC;
                ASM_REWRITE_TAC[]]]];
          DISCH_THEN ACCEPT_TAC];
        USE_THEN "relation_chain" MATCH_MP_TAC THEN
        USE_THEN "j_before_last" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((f:num->A) 0 = f(j - 1)) /\
      ~(f 0 = f(j + 1)) /\
      ~(f(j - 1) = f(j + 1))`
    (CONJUNCTS_THEN2 (LABEL_TAC "first_not_previous")
     (CONJUNCTS_THEN2 (LABEL_TAC "first_not_next")
      (LABEL_TAC "previous_not_next"))) THENL
     [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["injective"; "large"; "j_index";
        "j_after_second"; "j_before_last"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN
      MESON_TAC[ARITH_RULE
       `3 <= n /\ j < n /\ 1 < j /\ j + 1 < n
        ==> 0 < n /\ j - 1 < n /\ j + 1 < n /\
            ~(0 = j - 1) /\ ~(0 = j + 1) /\
            ~(j - 1 = j + 1)`];
      ALL_TAC] THEN
    USE_THEN "degree_at_most_2"
     (MP_TAC o SPECL
       [`(f:num->A) j`; `(f:num->A) 0`;
        `(f:num->A)(j - 1)`; `(f:num->A)(j + 1)`]) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "u_point" (fun th ->
         USE_THEN "u_vertex" (ACCEPT_TAC o REWRITE_RULE[th]));
        USE_THEN "first_vertex" ACCEPT_TAC;
        USE_THEN "previous_vertex" ACCEPT_TAC;
        USE_THEN "next_vertex" ACCEPT_TAC;
        USE_THEN "symmetric"
         (MP_TAC o SPECL [`(f:num->A) 0`; `u:A`]) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[];
          DISCH_THEN(LABEL_TAC "u_reverse")] THEN
        USE_THEN "u_point" (fun th ->
          USE_THEN "u_reverse" (ACCEPT_TAC o REWRITE_RULE[th]));
        USE_THEN "previous_edge" ACCEPT_TAC;
        USE_THEN "next_edge" ACCEPT_TAC];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  USE_THEN "symmetric"
   (MATCH_MP_TAC o SPECL [`(f:num->A) 0`; `(f:num->A)(n - 1)`]) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "first_vertex" ACCEPT_TAC;
    USE_THEN "last_vertex" ACCEPT_TAC;
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["u_edge"; "u_point"; "j_last"] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[]]);;
let SIMPLE_GRAPH_CYCLE_3_TWO_EDGES_AT_VERTEX = prove
 (`!E:(A->bool)->bool. !r:num->A. !v.
        simple_graph_cycle E r 3 /\
        v IN cyclic_vertices r 3
        ==> ?u w.
              ~(u = v) /\
              ~(w = v) /\
              ~(u = w) /\
              {v,u} IN cyclic_edges r 3 /\
              {v,w} IN cyclic_edges r 3`,
  REPEAT GEN_TAC THEN INTRO_TAC "cycle v_vertex" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "_ injective _" THEN
  SUBGOAL_THEN
   `~((r:num->A) 0 = r 1) /\
    ~(r 1 = r 2) /\
    ~(r 2 = r 0)`
  (LABEL_TAC "distinct") THENL
   [USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC
     [INJ; IN_UNIV; CYCLIC_INDICES_3;
      IN_INSERT; NOT_IN_EMPTY] THEN
    MESON_TAC[ARITH_RULE
     `~((0:num) = 1) /\ ~(1 = 2) /\ ~(2 = 0)`];
    ALL_TAC] THEN
  USE_THEN "v_vertex" MP_TAC THEN
  REWRITE_TAC[CYCLIC_VERTICES_3; IN_INSERT; IN_SING] THEN
  DISCH_THEN
   (DISJ_CASES_THEN2 SUBST1_TAC
    (DISJ_CASES_THEN2 SUBST1_TAC SUBST1_TAC)) THENL
   [MAP_EVERY EXISTS_TAC [`(r:num->A) 1`; `(r:num->A) 2`];
    MAP_EVERY EXISTS_TAC [`(r:num->A) 0`; `(r:num->A) 2`];
    MAP_EVERY EXISTS_TAC [`(r:num->A) 0`; `(r:num->A) 1`]] THEN
  USE_THEN "distinct" MP_TAC THEN
  POP_ASSUM_LIST(K ALL_TAC) THEN
  REWRITE_TAC[CYCLIC_EDGES_3; IN_INSERT; IN_SING] THEN
  SET_TAC[]);;

let PLANE_GRAPH_EMBEDDING_TRIANGULAR_FACE_EDGE_FRONTIER = prove
 (`!V E p c k r e.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        plane_graph_face_vertices V E p c k =
          cyclic_vertices r 3 /\
        simple_graph_cycle E r 3 /\
        e IN cyclic_edges r 3
        ==> c e SUBSET frontier k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding component face_vertices cycle cycle_edge" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `k:real^2->bool`; `r:num->A`]
   PLANE_GRAPH_EMBEDDING_TRIANGULAR_FACE_JORDAN_SIDE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@j. simple loop image face_frontier face_side" THEN
  USE_THEN "face_frontier" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "image" (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `x:real^2` THEN
  DISCH_THEN(LABEL_TAC "x_edge") THEN
  REWRITE_TAC[IN_UNIONS] THEN
  EXISTS_TAC `(c:(A->bool)->real^2->bool) e` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `e:A->bool` THEN
    ASM_REWRITE_TAC[];
    USE_THEN "x_edge" ACCEPT_TAC]);;

let PLANE_TRIANGULATED_DISK_INTERNAL_FACE_TWO_EDGE_ADJACENCIES =
  prove
 (`!V E p c q n outer k v.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        k IN plane_graph_incident_faces V E p c v /\
        ~(k = outer)
        ==> ?e1 e2 l1 l2.
              ~(e1 = e2) /\
              e1 IN E /\ e2 IN E /\
              v IN e1 /\ v IN e2 /\
              c e1 SUBSET frontier k /\
              c e1 SUBSET frontier l1 /\
              c e2 SUBSET frontier k /\
              c e2 SUBSET frontier l2 /\
              l1 IN components
                ((:real^2) DIFF plane_graph_carrier V E p c) /\
              v IN plane_graph_face_vertices V E p c l1 /\
              l2 IN components
                ((:real^2) DIFF plane_graph_carrier V E p c) /\
              v IN plane_graph_face_vertices V E p c l2 /\
              plane_graph_face_adjacent_at E c v k l1 /\
              plane_graph_face_adjacent_at E c v k l2`,
  REPEAT GEN_TAC THEN INTRO_TAC "disk k_incident k_not_outer" THEN
  USE_THEN "disk" MP_TAC THEN
  REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC
   "graph embedding nlarge boundary_cycle outer_component boundary \
    all_faces" THEN
  USE_THEN "k_incident" MP_TAC THEN
  REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
  INTRO_TAC "k_component v_k" THEN
  USE_THEN "all_faces" (MP_TAC o SPEC `k:real^2->bool`) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC "@r. face_vertices triangle_cycle"] THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `r:num->A`; `v:A`]
   SIMPLE_GRAPH_CYCLE_3_TWO_EDGES_AT_VERTEX) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    USE_THEN "face_vertices" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "v_k" ACCEPT_TAC;
    INTRO_TAC "@u w. u_v w_v u_w vu vw"] THEN
  ABBREV_TAC `(e1:A->bool) = {v,u}` THEN
  ABBREV_TAC `(e2:A->bool) = {v,w}` THEN
  SUBGOAL_THEN `~((e1:A->bool) = e2)`
  (LABEL_TAC "edges_distinct") THENL
   [EXPAND_TAC "e1" THEN EXPAND_TAC "e2" THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["u_v"; "w_v"; "u_w"] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(e1:A->bool) IN cyclic_edges r 3`
  (LABEL_TAC "e1_cycle") THENL
   [EXPAND_TAC "e1" THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(e2:A->bool) IN cyclic_edges r 3`
  (LABEL_TAC "e2_cycle") THENL
   [EXPAND_TAC "e2" THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(e1:A->bool) IN E /\ e2 IN E`
  (CONJUNCTS_THEN2 (LABEL_TAC "e1_edge") (LABEL_TAC "e2_edge")) THENL
   [USE_THEN "triangle_cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN
    INTRO_TAC "_ _ triangle_edges" THEN
    CONJ_TAC THEN USE_THEN "triangle_edges"
     (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v:A) IN e1 /\ v IN e2`
  (CONJUNCTS_THEN2 (LABEL_TAC "v_e1") (LABEL_TAC "v_e2")) THENL
   [EXPAND_TAC "e1" THEN EXPAND_TAC "e2" THEN
    REWRITE_TAC[IN_INSERT];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) e1 SUBSET frontier k /\
    c e2 SUBSET frontier k`
  (CONJUNCTS_THEN2 (LABEL_TAC "e1_k") (LABEL_TAC "e2_k")) THENL
   [CONJ_TAC THEN MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `k:real^2->bool`; `r:num->A`]
     PLANE_GRAPH_EMBEDDING_TRIANGULAR_FACE_EDGE_FRONTIER) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `k:real^2->bool`; `r:num->A`; `e1:A->bool`]
   PLANE_TRIANGULATED_DISK_TRIANGULAR_FACE_OPPOSITE_EDGE) THEN
  ASM_REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC
   "@l1. l1_component l1_distinct e1_face e1_l1 l1_shape" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `k:real^2->bool`; `r:num->A`; `e2:A->bool`]
   PLANE_TRIANGULATED_DISK_TRIANGULAR_FACE_OPPOSITE_EDGE) THEN
  ASM_REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC
   "@l2. l2_component l2_distinct e2_face e2_l2 l2_shape" THEN
  MAP_EVERY EXISTS_TAC
   [`e1:A->bool`; `e2:A->bool`;
    `l1:real^2->bool`; `l2:real^2->bool`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "edges_distinct" ACCEPT_TAC;
    USE_THEN "e1_edge" ACCEPT_TAC;
    USE_THEN "e2_edge" ACCEPT_TAC;
    USE_THEN "v_e1" ACCEPT_TAC;
    USE_THEN "v_e2" ACCEPT_TAC;
    USE_THEN "e1_k" ACCEPT_TAC;
    USE_THEN "e1_l1" ACCEPT_TAC;
    USE_THEN "e2_k" ACCEPT_TAC;
    USE_THEN "e2_l2" ACCEPT_TAC;
    USE_THEN "l1_component" ACCEPT_TAC;
    USE_THEN "e1_face" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "v_e1" ACCEPT_TAC;
    USE_THEN "l2_component" ACCEPT_TAC;
    USE_THEN "e2_face" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "v_e2" ACCEPT_TAC;
    REWRITE_TAC[plane_graph_face_adjacent_at] THEN
    CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "l1_distinct" (fun dth ->
        USE_THEN "same" (fun sth ->
          CONTR_TAC(MP (NOT_ELIM dth) (SYM sth))));
      EXISTS_TAC `e1:A->bool` THEN ASM_REWRITE_TAC[]];
    REWRITE_TAC[plane_graph_face_adjacent_at] THEN
    CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "l2_distinct" (fun dth ->
        USE_THEN "same" (fun sth ->
          CONTR_TAC(MP (NOT_ELIM dth) (SYM sth))));
      EXISTS_TAC `e2:A->bool` THEN ASM_REWRITE_TAC[]]]);;
let TWO_CHOICES_COVER = prove
 (`!a b x y z:A.
        (x = a \/ x = b) /\
        (y = a \/ y = b) /\
        (z = a \/ z = b) /\
        ~(x = y)
        ==> z = x \/ z = y`,
  MESON_TAC[]);;

let TRIANGLE_INCIDENT_EDGE_CHOICE = prove
 (`!E:(A->bool)->bool. !r:num->A. !v e1 e2 d.
        simple_graph_cycle E r 3 /\
        v IN cyclic_vertices r 3 /\
        e1 IN cyclic_edges r 3 /\
        e2 IN cyclic_edges r 3 /\
        d IN cyclic_edges r 3 /\
        v IN e1 /\ v IN e2 /\ v IN d /\
        ~(e1 = e2)
        ==> d = e1 \/ d = e2`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "cycle v_vertex e1_cycle e2_cycle d_cycle \
    v_e1 v_e2 v_d e1_e2" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "_ injective _" THEN
  SUBGOAL_THEN
   `~((r:num->A) 0 = r 1) /\
    ~(r 1 = r 2) /\
    ~(r 2 = r 0)`
  (CONJUNCTS_THEN2 (LABEL_TAC "r01")
   (CONJUNCTS_THEN2 (LABEL_TAC "r12") (LABEL_TAC "r20"))) THENL
   [USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC
     [INJ; IN_UNIV; CYCLIC_INDICES_3;
      IN_INSERT; NOT_IN_EMPTY] THEN
    MESON_TAC[ARITH_RULE
     `~((0:num) = 1) /\ ~(1 = 2) /\ ~(2 = 0)`];
    ALL_TAC] THEN
  USE_THEN "v_vertex" MP_TAC THEN
  REWRITE_TAC[CYCLIC_VERTICES_3; IN_INSERT; IN_SING] THEN
  DISCH_THEN
   (DISJ_CASES_THEN2 (LABEL_TAC "v0")
    (DISJ_CASES_THEN2 (LABEL_TAC "v1") (LABEL_TAC "v2"))) THENL
   [MP_TAC(ISPECL [`r:num->A`; `e1:A->bool`]
      TRIANGLE_CYCLIC_EDGE_AT_0) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "e1_choice") THEN
    MP_TAC(ISPECL [`r:num->A`; `e2:A->bool`]
      TRIANGLE_CYCLIC_EDGE_AT_0) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "e2_choice") THEN
    MP_TAC(ISPECL [`r:num->A`; `d:A->bool`]
      TRIANGLE_CYCLIC_EDGE_AT_0) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "d_choice") THEN
    MATCH_MP_TAC(ISPECL
     [`{(r:num->A) 0,r 1}:A->bool`; `{r 2,r 0}:A->bool`;
     `e1:A->bool`; `e2:A->bool`; `d:A->bool`]
     TWO_CHOICES_COVER) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC TRIANGLE_CYCLIC_EDGE_AT_0 THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "v0" (fun th ->
        USE_THEN "v_e1" (ACCEPT_TAC o REWRITE_RULE[th]));
      MATCH_MP_TAC TRIANGLE_CYCLIC_EDGE_AT_0 THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "v0" (fun th ->
        USE_THEN "v_e2" (ACCEPT_TAC o REWRITE_RULE[th]));
      MATCH_MP_TAC TRIANGLE_CYCLIC_EDGE_AT_0 THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "v0" (fun th ->
        USE_THEN "v_d" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "e1_e2" ACCEPT_TAC];
    MP_TAC(ISPECL [`r:num->A`; `e1:A->bool`]
      TRIANGLE_CYCLIC_EDGE_AT_1) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "e1_choice") THEN
    MP_TAC(ISPECL [`r:num->A`; `e2:A->bool`]
      TRIANGLE_CYCLIC_EDGE_AT_1) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "e2_choice") THEN
    MP_TAC(ISPECL [`r:num->A`; `d:A->bool`]
      TRIANGLE_CYCLIC_EDGE_AT_1) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "d_choice") THEN
    MATCH_MP_TAC(ISPECL
     [`{(r:num->A) 0,r 1}:A->bool`; `{r 1,r 2}:A->bool`;
     `e1:A->bool`; `e2:A->bool`; `d:A->bool`]
     TWO_CHOICES_COVER) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC TRIANGLE_CYCLIC_EDGE_AT_1 THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "v1" (fun th ->
        USE_THEN "v_e1" (ACCEPT_TAC o REWRITE_RULE[th]));
      MATCH_MP_TAC TRIANGLE_CYCLIC_EDGE_AT_1 THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "v1" (fun th ->
        USE_THEN "v_e2" (ACCEPT_TAC o REWRITE_RULE[th]));
      MATCH_MP_TAC TRIANGLE_CYCLIC_EDGE_AT_1 THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "v1" (fun th ->
        USE_THEN "v_d" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "e1_e2" ACCEPT_TAC];
    MP_TAC(ISPECL [`r:num->A`; `e1:A->bool`]
      TRIANGLE_CYCLIC_EDGE_AT_2) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "e1_choice") THEN
    MP_TAC(ISPECL [`r:num->A`; `e2:A->bool`]
      TRIANGLE_CYCLIC_EDGE_AT_2) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "e2_choice") THEN
    MP_TAC(ISPECL [`r:num->A`; `d:A->bool`]
      TRIANGLE_CYCLIC_EDGE_AT_2) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "d_choice") THEN
    MATCH_MP_TAC(ISPECL
     [`{(r:num->A) 1,r 2}:A->bool`; `{r 2,r 0}:A->bool`;
     `e1:A->bool`; `e2:A->bool`; `d:A->bool`]
     TWO_CHOICES_COVER) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC TRIANGLE_CYCLIC_EDGE_AT_2 THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "v2" (fun th ->
        USE_THEN "v_e1" (ACCEPT_TAC o REWRITE_RULE[th]));
      MATCH_MP_TAC TRIANGLE_CYCLIC_EDGE_AT_2 THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "v2" (fun th ->
        USE_THEN "v_e2" (ACCEPT_TAC o REWRITE_RULE[th]));
      MATCH_MP_TAC TRIANGLE_CYCLIC_EDGE_AT_2 THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "v2" (fun th ->
        USE_THEN "v_d" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "e1_e2" ACCEPT_TAC]]);;

let PLANE_TRIANGULATED_DISK_INCIDENT_FACE_FRONTIER_EDGE_CHOICE =
  prove
 (`!V E p c q n outer k e1 e2 d.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        k IN plane_graph_incident_faces V E p c (q(n - 1)) /\
        ~(e1 = e2) /\
        e1 IN E /\ e2 IN E /\ d IN E /\
        q(n - 1) IN e1 /\ q(n - 1) IN e2 /\ q(n - 1) IN d /\
        c e1 SUBSET frontier k /\
        c e2 SUBSET frontier k /\
        c d SUBSET frontier k
        ==> d = e1 \/ d = e2`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk chordless k_incident e1_e2 e1_edge e2_edge d_edge \
    v_e1 v_e2 v_d e1_k e2_k d_k" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  USE_THEN "k_incident" MP_TAC THEN
  REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
  INTRO_TAC "k_component v_k" THEN
  ASM_CASES_TAC `(k:real^2->bool) = outer` THENL
   [FIRST_X_ASSUM(LABEL_TAC "k_outer") THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `e1:A->bool`]
     PLANE_TRIANGULATED_DISK_OUTER_FRONTIER_EDGE_AT_LAST) THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `e2:A->bool`]
     PLANE_TRIANGULATED_DISK_OUTER_FRONTIER_EDGE_AT_LAST) THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `d:A->bool`]
     PLANE_TRIANGULATED_DISK_OUTER_FRONTIER_EDGE_AT_LAST) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["e1_e2"; "k_outer"; "e1_k"; "e2_k"; "d_k"] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "k_not_outer")] THEN
  USE_THEN "disk" MP_TAC THEN
  REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC "_ _ _ _ _ _ all_faces" THEN
  USE_THEN "all_faces" (MP_TAC o SPEC `k:real^2->bool`) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC "@r. face_vertices triangle_cycle"] THEN
  SUBGOAL_THEN
   `(e1:A->bool) IN cyclic_edges r 3 /\
    e2 IN cyclic_edges r 3 /\
    d IN cyclic_edges r 3`
  (CONJUNCTS_THEN2 (LABEL_TAC "e1_cycle")
   (CONJUNCTS_THEN2 (LABEL_TAC "e2_cycle") (LABEL_TAC "d_cycle"))) THENL
   [REPEAT CONJ_TAC THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `k:real^2->bool`; `r:num->A`]
     PLANE_GRAPH_EMBEDDING_TRIANGULAR_FACE_FRONTIER_EDGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `r:num->A`; `(q:num->A)(n - 1)`;
    `e1:A->bool`; `e2:A->bool`; `d:A->bool`]
   TRIANGLE_INCIDENT_EDGE_CHOICE) THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "face_vertices" (fun th -> REWRITE_TAC[GSYM th]) THEN
  USE_THEN "v_k" ACCEPT_TAC);;
let PLANE_TRIANGULATED_DISK_INCIDENT_FACE_SHARED_TWO_EDGES_NEIGHBORS =
  prove
 (`!V E p c q n outer k l e1 e2.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        k IN plane_graph_incident_faces V E p c (q(n - 1)) /\
        l IN plane_graph_incident_faces V E p c (q(n - 1)) /\
        ~(k = l) /\
        ~(e1 = e2) /\
        e1 IN E /\ e2 IN E /\
        q(n - 1) IN e1 /\ q(n - 1) IN e2 /\
        c e1 SUBSET frontier k /\
        c e2 SUBSET frontier k /\
        c e1 SUBSET frontier l /\
        c e2 SUBSET frontier l
        ==> (!m. m IN plane_graph_incident_faces
                       V E p c (q(n - 1)) /\
                  plane_graph_face_adjacent_at E c (q(n - 1)) k m
                  ==> m = l) /\
            (!m. m IN plane_graph_incident_faces
                       V E p c (q(n - 1)) /\
                  plane_graph_face_adjacent_at E c (q(n - 1)) l m
                  ==> m = k)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk chordless k_face l_face k_l e1_e2 e1_edge e2_edge \
