let PLANE_TRIANGULATED_DISK_INCIDENT_FACE_SHARED_TWO_EDGES_EXHAUST =
  prove
 (`!V E p c q n outer newouter k l e1 e2.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE q(n - 1))
             (induced_subgraph_edges E (V DELETE q(n - 1))) p c) /\
        outer SUBSET newouter /\
        (p:A->real^2) (q(n - 1)) IN newouter /\
        k IN plane_graph_incident_faces V E p c (q(n - 1)) /\
        l IN plane_graph_incident_faces V E p c (q(n - 1)) /\
        ~(k = l) /\
        ~(e1 = e2) /\
        e1 IN E /\ e2 IN E /\
        q(n - 1) IN e1 /\ q(n - 1) IN e2 /\
        c e1 SUBSET frontier k /\
        c e2 SUBSET frontier k /\
        c e1 SUBSET frontier l /\
        c e2 SUBSET frontier l
        ==> plane_graph_incident_faces V E p c (q(n - 1))
            SUBSET {k,l}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk chordless newouter_component outer_subset last_newouter \
    k_face l_face k_l e1_e2 e1_edge e2_edge v_e1 v_e2 \
    e1_k e2_k e1_l e2_l" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `k:real^2->bool`; `l:real^2->bool`;
    `e1:A->bool`; `e2:A->bool`]
   PLANE_TRIANGULATED_DISK_INCIDENT_FACE_SHARED_TWO_EDGES_NEIGHBORS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "unique_k unique_l" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "_ _ nlarge _ _ _ _ _" THEN
  SUBGOAL_THEN
   `(q:num->A)(n - 1) IN cyclic_vertices q n`
  (LABEL_TAC "last_boundary") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET] THEN
  X_GEN_TAC `m:real^2->bool` THEN
  DISCH_THEN(LABEL_TAC "m_face") THEN
  ASM_CASES_TAC
   `(m:real^2->bool) IN {k,l}` THEN ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(LABEL_TAC "m_not_pair") THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `(q:num->A)(n - 1)`;
    `newouter:real^2->bool`; `{k,l}:(real^2->bool)->bool`]
   PLANE_TRIANGULATED_DISK_INCIDENT_FACE_ADJACENCY_CONNECTED) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "disk" ACCEPT_TAC;
      USE_THEN "last_boundary" ACCEPT_TAC;
      USE_THEN "newouter_component" ACCEPT_TAC;
      USE_THEN "outer_subset" ACCEPT_TAC;
      USE_THEN "last_newouter" ACCEPT_TAC;
      REWRITE_TAC[SUBSET; IN_INSERT; IN_SING] THEN
      ASM_MESON_TAC[];
      SET_TAC[];
      REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
      EXISTS_TAC `m:real^2->bool` THEN
      ASM_REWRITE_TAC[IN_DIFF]];
    INTRO_TAC "@a b. a_pair b_rest adjacent"] THEN
  USE_THEN "b_rest" MP_TAC THEN
  REWRITE_TAC[IN_DIFF] THEN
  INTRO_TAC "b_face b_not_pair" THEN
  USE_THEN "a_pair" MP_TAC THEN
  REWRITE_TAC[IN_INSERT; IN_SING] THEN
  DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
   [USE_THEN "unique_k" (MP_TAC o SPEC `b:real^2->bool`) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(LABEL_TAC "b_l") THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["b_l"; "b_not_pair"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN MESON_TAC[]];
    USE_THEN "unique_l" (MP_TAC o SPEC `b:real^2->bool`) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(LABEL_TAC "b_k") THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["b_k"; "b_not_pair"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN MESON_TAC[]]]);;
let CYCLIC_SECOND_SUCCESSOR_NE = prove
 (`!n i. 3 <= n /\ i < n
          ==> ~((i + 2) MOD n = i)`,
  REPEAT GEN_TAC THEN INTRO_TAC "large index" THEN
  MP_TAC(SPECL [`i + 2`; `n:num`] MOD_CASES) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN SUBST1_TAC] THEN
  COND_CASES_TAC THENL
   [ARITH_TAC;
    DISCH_THEN(LABEL_TAC "equal") THEN
    SUBGOAL_THEN `(i + 2) - n + n = i + 2`
    (LABEL_TAC "subadd") THENL
     [MATCH_MP_TAC SUB_ADD THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `i + n = i + 2`
    (LABEL_TAC "relation") THENL
     [USE_THEN "subadd" MP_TAC THEN
      USE_THEN "equal" (fun th -> REWRITE_TAC[th]);
      ALL_TAC] THEN
    USE_THEN "relation" MP_TAC THEN
    REWRITE_TAC[EQ_ADD_LCANCEL] THEN ASM_ARITH_TAC]);;

let CYCLIC_SUCCESSOR_NO_TWO_CYCLE = prove
 (`!n i j.
        3 <= n /\
        i < n /\ j < n /\
        j = (i + 1) MOD n /\
        i = (j + 1) MOD n
        ==> F`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "large i_index j_index j_successor i_successor" THEN
  SUBGOAL_THEN `1 MOD n = 1` (LABEL_TAC "one_mod") THENL
   [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(((i + 1) MOD n) + 1) MOD n = (i + 2) MOD n`
  (LABEL_TAC "two_steps") THENL
   [MP_TAC(SPECL [`i + 1`; `1`; `n:num`] MOD_ADD_MOD) THEN
    USE_THEN "one_mod" (fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(fun th ->
      ACCEPT_TAC(REWRITE_RULE[ARITH_RULE `(i + 1) + 1 = i + 2`] th));
    ALL_TAC] THEN
  SUBGOAL_THEN `(i + 2) MOD n = i`
  (LABEL_TAC "returns") THENL
   [TRANS_TAC EQ_TRANS `(((i + 1) MOD n) + 1) MOD n` THEN
    CONJ_TAC THENL
     [USE_THEN "two_steps" (ACCEPT_TAC o SYM);
      USE_THEN "j_successor" (SUBST1_TAC o SYM) THEN
      USE_THEN "i_successor" (ACCEPT_TAC o SYM)];
    ALL_TAC] THEN
  MP_TAC(SPECL [`n:num`; `i:num`] CYCLIC_SECOND_SUCCESSOR_NE) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "large" ACCEPT_TAC;
      USE_THEN "i_index" ACCEPT_TAC];
    DISCH_THEN(LABEL_TAC "no_return")] THEN
  USE_THEN "no_return" (fun nth ->
    USE_THEN "returns" (fun rth ->
      CONTR_TAC(MP (NOT_ELIM nth) rth))));;

let PLANE_GRAPH_EMBEDDING_EDGE_INCIDENT_FACE_CHOICE = prove
 (`!V E p c e k l m.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e IN E /\
        k IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        l IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        m IN components
          ((:real^2) DIFF plane_graph_carrier V E p c) /\
        c e SUBSET frontier k /\
        c e SUBSET frontier l /\
        c e SUBSET frontier m /\
        ~(k = l)
        ==> m = k \/ m = l`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding edge k_component l_component m_component \
    e_k e_l e_m k_l" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `e:A->bool`;
    `k:real^2->bool`; `l:real^2->bool`; `m:real^2->bool`]
   PLANE_GRAPH_EMBEDDING_EDGE_AT_MOST_TWO_INCIDENT_FACES) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY (fun name -> USE_THEN name MP_TAC) ["k_l"] THEN
  POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[]);;

let PLANE_GRAPH_EMBEDDING_EDGE_INCIDENT_COMPONENT_FRONTIER = prove
 (`!V E p c e.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e IN E
        ==> ?k. k IN components
                    ((:real^2) DIFF plane_graph_carrier V E p c) /\
                c e SUBSET frontier k`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph embedding edge" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `e:A->bool`]
   PLANE_GRAPH_EMBEDDING_EDGE_INTERIOR_NONEMPTY) THEN
  ASM_REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
  INTRO_TAC "@x. x_middle" THEN
  SUBGOAL_THEN
   `(x:real^2) IN plane_graph_carrier (V:A->bool) E p c`
  (LABEL_TAC "x_carrier") THENL
   [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
     (MATCH_MP
       (ISPECL
        [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
         `c:(A->bool)->real^2->bool`; `e:A->bool`]
        PLANE_GRAPH_CARRIER_EDGE_SUBSET)
       (ASSUME `(e:A->bool) IN E`))) THEN
    USE_THEN "x_middle" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `x:real^2`]
   PLANE_GRAPH_CARRIER_POINT_INCIDENT_COMPONENT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@k. k_component x_frontier" THEN
  EXISTS_TAC `k:real^2->bool` THEN
  CONJ_TAC THENL
   [USE_THEN "k_component" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`;
      `k:real^2->bool`; `x:real^2`]
     PLANE_GRAPH_EMBEDDING_EDGE_COMPONENT_FRONTIER) THEN
    ASM_REWRITE_TAC[]]);;

let CYCLIC_INDEX_HAS_PREDECESSOR = prove
 (`!m i.
        2 <= m /\ i < m
        ==> ?j. j < m /\
                i = (j + 1) MOD m /\
                ~(j = i)`,
  REPEAT GEN_TAC THEN INTRO_TAC "large index" THEN
  ASM_CASES_TAC `(i:num) = 0` THENL
   [EXISTS_TAC `m - 1` THEN
    REPEAT CONJ_TAC THENL
     [ASM_ARITH_TAC;
      SUBGOAL_THEN `(m - 1) + 1 = m`
      (fun th -> ASM_REWRITE_TAC[th; MOD_REFL]) THEN
      ASM_ARITH_TAC;
      ASM_ARITH_TAC];
    EXISTS_TAC `i - 1` THEN
    REPEAT CONJ_TAC THENL
     [ASM_ARITH_TAC;
      SUBGOAL_THEN `(i - 1) + 1 = i`
      (fun th -> REWRITE_TAC[th]) THENL
       [ASM_ARITH_TAC;
        CONV_TAC SYM_CONV THEN MATCH_MP_TAC MOD_LT THEN
        USE_THEN "index" ACCEPT_TAC];
      ASM_ARITH_TAC]]);;

let PLANE_GRAPH_FACE_ADJACENT_CYCLE_EDGES_INJ = prove
 (`!V E p c v h m d.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        3 <= m /\
        finite_relation_path
          (plane_graph_face_adjacent_at E c v)
          (plane_graph_incident_faces V E p c v) h m /\
        (!i. i < m
             ==> d i IN E /\
                 v IN d i /\
                 c(d i) SUBSET frontier(h i) /\
                 c(d i) SUBSET frontier(h((i + 1) MOD m)))
        ==> INJ d (cyclic_indices m) (:(A->bool))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding large path edge_cycle" THEN
  USE_THEN "path" MP_TAC THEN
  REWRITE_TAC[finite_relation_path] THEN
  INTRO_TAC "vertices h_injective chain" THEN
  SUBGOAL_THEN
   `!r. r < m
        ==> (h:num->real^2->bool) r IN
            components
              ((:real^2) DIFF
               plane_graph_carrier (V:A->bool) E p c)`
  (LABEL_TAC "face_component") THENL
   [X_GEN_TAC `r:num` THEN DISCH_THEN(LABEL_TAC "r_index") THEN
    USE_THEN "vertices" (MP_TAC o SPEC `r:num`) THEN
    ANTS_TAC THENL
     [USE_THEN "r_index" ACCEPT_TAC;
      REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
      MESON_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
  INTRO_TAC "i_index j_index same_edge" THEN
  ABBREV_TAC `(si:num) = (i + 1) MOD m` THEN
  POP_ASSUM(LABEL_TAC "si_def") THEN
  ABBREV_TAC `(sj:num) = (j + 1) MOD m` THEN
  POP_ASSUM(LABEL_TAC "sj_def") THEN
  SUBGOAL_THEN `(si:num) < m /\ (sj:num) < m`
  (CONJUNCTS_THEN2 (LABEL_TAC "si_index")
   (LABEL_TAC "sj_index")) THENL
   [EXPAND_TAC "si" THEN EXPAND_TAC "sj" THEN
    REWRITE_TAC[MOD_LT_EQ_LT] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((si:num) = i) /\ ~((sj:num) = j)`
  (CONJUNCTS_THEN2 (LABEL_TAC "si_not_i")
   (LABEL_TAC "sj_not_j")) THENL
   [CONJ_TAC THENL
     [EXPAND_TAC "si" THEN
      MATCH_MP_TAC CYCLIC_SUCCESSOR_NE THEN ASM_ARITH_TAC;
      EXPAND_TAC "sj" THEN
      MATCH_MP_TAC CYCLIC_SUCCESSOR_NE THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(h:num->real^2->bool) i IN
      components
       ((:real^2) DIFF plane_graph_carrier (V:A->bool) E p c) /\
    h si IN
      components
       ((:real^2) DIFF plane_graph_carrier V E p c) /\
    h j IN
      components
       ((:real^2) DIFF plane_graph_carrier V E p c) /\
    h sj IN
      components
       ((:real^2) DIFF plane_graph_carrier V E p c)`
  (CONJUNCTS_THEN2 (LABEL_TAC "hi_component")
   (CONJUNCTS_THEN2 (LABEL_TAC "hsi_component")
    (CONJUNCTS_THEN2 (LABEL_TAC "hj_component")
     (LABEL_TAC "hsj_component")))) THENL
   [REPEAT CONJ_TAC THEN USE_THEN "face_component" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((h:num->real^2->bool) i = h si)`
  (LABEL_TAC "faces_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same_face") THEN
    SUBGOAL_THEN `(i:num) = si`
    (LABEL_TAC "same_index") THENL
     [USE_THEN "h_injective" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      USE_THEN "si_not_i" MP_TAC THEN
      USE_THEN "same_index" MP_TAC THEN MESON_TAC[]];
    ALL_TAC] THEN
  USE_THEN "edge_cycle" (MP_TAC o SPEC `i:num`) THEN
  ANTS_TAC THENL
   [USE_THEN "i_index" ACCEPT_TAC;
    INTRO_TAC "di_edge v_di di_hi di_hsi"] THEN
  USE_THEN "edge_cycle" (MP_TAC o SPEC `j:num`) THEN
  ANTS_TAC THENL
   [USE_THEN "j_index" ACCEPT_TAC;
    INTRO_TAC "dj_edge v_dj dj_hj dj_hsj"] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) ((d:num->A->bool) (i:num))
      SUBSET frontier((h:num->real^2->bool) (j:num)) /\
    c(d i) SUBSET frontier(h(sj:num))`
  (CONJUNCTS_THEN2 (LABEL_TAC "di_hj")
   (LABEL_TAC "di_hsj")) THENL
   [CONJ_TAC THENL
     [USE_THEN "same_edge" (fun th ->
        USE_THEN "dj_hj"
         (MATCH_ACCEPT_TAC o REWRITE_RULE[GSYM th]));
      EXPAND_TAC "sj" THEN
      USE_THEN "same_edge" (fun th ->
        USE_THEN "dj_hsj"
         (MATCH_ACCEPT_TAC o REWRITE_RULE[GSYM th]))];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(h:num->real^2->bool) j = h i \/ h j = h si`
  (LABEL_TAC "hj_choice") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `(d:num->A->bool) i`;
      `(h:num->real^2->bool) i`; `(h:num->real^2->bool) si`;
      `(h:num->real^2->bool) j`]
     PLANE_GRAPH_EMBEDDING_EDGE_INCIDENT_FACE_CHOICE) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      USE_THEN "embedding" ACCEPT_TAC;
      USE_THEN "di_edge" ACCEPT_TAC;
      USE_THEN "hi_component" ACCEPT_TAC;
      USE_THEN "hsi_component" ACCEPT_TAC;
      USE_THEN "hj_component" ACCEPT_TAC;
      USE_THEN "di_hi" ACCEPT_TAC;
      EXPAND_TAC "si" THEN USE_THEN "di_hsi" MATCH_ACCEPT_TAC;
      USE_THEN "di_hj" ACCEPT_TAC;
      USE_THEN "faces_distinct" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(h:num->real^2->bool) sj = h i \/ h sj = h si`
  (LABEL_TAC "hsj_choice") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `(d:num->A->bool) i`;
      `(h:num->real^2->bool) i`; `(h:num->real^2->bool) si`;
      `(h:num->real^2->bool) sj`]
     PLANE_GRAPH_EMBEDDING_EDGE_INCIDENT_FACE_CHOICE) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      USE_THEN "embedding" ACCEPT_TAC;
      USE_THEN "di_edge" ACCEPT_TAC;
      USE_THEN "hi_component" ACCEPT_TAC;
      USE_THEN "hsi_component" ACCEPT_TAC;
      USE_THEN "hsj_component" ACCEPT_TAC;
      USE_THEN "di_hi" ACCEPT_TAC;
      EXPAND_TAC "si" THEN USE_THEN "di_hsi" MATCH_ACCEPT_TAC;
      USE_THEN "di_hsj" ACCEPT_TAC;
      USE_THEN "faces_distinct" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(j:num) = i \/ j = si`
  (LABEL_TAC "j_choice") THENL
   [USE_THEN "hj_choice"
     (DISJ_CASES_THEN2 (LABEL_TAC "hj_hi") (LABEL_TAC "hj_hsi")) THENL
     [DISJ1_TAC THEN USE_THEN "h_injective" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      DISJ2_TAC THEN USE_THEN "h_injective" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(sj:num) = i \/ sj = si`
  (LABEL_TAC "sj_choice") THENL
   [USE_THEN "hsj_choice"
     (DISJ_CASES_THEN2 (LABEL_TAC "hsj_hi")
      (LABEL_TAC "hsj_hsi")) THENL
     [DISJ1_TAC THEN USE_THEN "h_injective" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      DISJ2_TAC THEN USE_THEN "h_injective" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  USE_THEN "j_choice"
   (DISJ_CASES_THEN2 (LABEL_TAC "j_i") (LABEL_TAC "j_si")) THENL
   [USE_THEN "j_i" (ACCEPT_TAC o SYM);
    ALL_TAC] THEN
  USE_THEN "sj_choice"
   (DISJ_CASES_THEN2 (LABEL_TAC "sj_i") (LABEL_TAC "sj_si")) THENL
   [SUBGOAL_THEN `F` CONTR_TAC THEN
    MATCH_MP_TAC(SPECL [`m:num`; `i:num`; `j:num`]
      CYCLIC_SUCCESSOR_NO_TWO_CYCLE) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "large" ACCEPT_TAC;
      USE_THEN "i_index" ACCEPT_TAC;
      USE_THEN "j_index" ACCEPT_TAC;
      USE_THEN "si_def" (fun th ->
        USE_THEN "j_si" (ACCEPT_TAC o REWRITE_RULE[GSYM th]));
      USE_THEN "sj_def" (fun th ->
        USE_THEN "sj_i"
         (ACCEPT_TAC o SYM o REWRITE_RULE[GSYM th]))];
    SUBGOAL_THEN `(sj:num) = j`
    (LABEL_TAC "sj_j") THENL
     [TRANS_TAC EQ_TRANS `si:num` THEN
      CONJ_TAC THENL
       [USE_THEN "sj_si" ACCEPT_TAC;
        USE_THEN "j_si" (ACCEPT_TAC o SYM)];
      ALL_TAC] THEN
    USE_THEN "sj_not_j" (fun nth ->
      USE_THEN "sj_j" (fun sth ->
        CONTR_TAC(MP (NOT_ELIM nth) sth)))]);;

let PLANE_TRIANGULATED_DISK_INCIDENT_FACE_CYCLE_EDGES_ENUMERATE =
  prove
 (`!V E p c q n outer h m d.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        3 <= m /\
        finite_relation_path
          (plane_graph_face_adjacent_at E c (q(n - 1)))
          (plane_graph_incident_faces V E p c (q(n - 1))) h m /\
        IMAGE h (cyclic_indices m) =
          plane_graph_incident_faces V E p c (q(n - 1)) /\
        (!i. i < m
             ==> d i IN E /\
                 q(n - 1) IN d i /\
                 c(d i) SUBSET frontier(h i) /\
                 c(d i) SUBSET frontier(h((i + 1) MOD m)))
        ==> {e:A->bool | e IN E /\ q(n - 1) IN e} =
            IMAGE d (cyclic_indices m)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk chordless large path coverage edge_cycle" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN
   `INJ (d:num->A->bool) (cyclic_indices m) (:(A->bool))`
  (LABEL_TAC "d_injective") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `(q:num->A)(n - 1)`;
      `h:num->real^2->bool`; `m:num`; `d:num->A->bool`]
     PLANE_GRAPH_FACE_ADJACENT_CYCLE_EDGES_INJ) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "path" MP_TAC THEN
  REWRITE_TAC[finite_relation_path] THEN
  INTRO_TAC "face_vertices h_injective chain" THEN
  REWRITE_TAC[EXTENSION] THEN
  X_GEN_TAC `e:A->bool` THEN
  REWRITE_TAC[IN_ELIM_THM; IN_IMAGE; IN_CYCLIC_INDICES] THEN
  EQ_TAC THENL
   [INTRO_TAC "edge incident" THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`]
     PLANE_GRAPH_EMBEDDING_EDGE_INCIDENT_COMPONENT_FRONTIER) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@k. k_component e_k" THEN
    SUBGOAL_THEN
     `(e:A->bool) SUBSET
      plane_graph_face_vertices V E p c (k:real^2->bool)`
    (LABEL_TAC "e_face") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `e:A->bool`;
        `k:real^2->bool`]
       PLANE_GRAPH_EMBEDDING_FRONTIER_EDGE_SUBSET_FACE_VERTICES) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(k:real^2->bool) IN
      plane_graph_incident_faces
       (V:A->bool) (E:(A->bool)->bool) (p:A->real^2)
       (c:(A->bool)->real^2->bool) ((q:num->A)(n - 1))`
    (LABEL_TAC "k_face") THENL
     [REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
      CONJ_TAC THENL
       [USE_THEN "k_component" MATCH_ACCEPT_TAC;
        USE_THEN "e_face"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "incident" MATCH_ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "k_face" MP_TAC THEN
    USE_THEN "coverage" (fun th -> REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[IN_IMAGE; IN_CYCLIC_INDICES] THEN
    INTRO_TAC "@i. k_point i_index" THEN
    USE_THEN "k_point" SUBST_ALL_TAC THEN
    MP_TAC(SPECL [`m:num`; `i:num`] CYCLIC_INDEX_HAS_PREDECESSOR) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      INTRO_TAC "@j. j_index predecessor j_i"] THEN
    SUBGOAL_THEN
     `(h:num->real^2->bool) i IN
      plane_graph_incident_faces
       (V:A->bool) (E:(A->bool)->bool) (p:A->real^2)
       (c:(A->bool)->real^2->bool) ((q:num->A)(n - 1))`
    (LABEL_TAC "hi_face") THENL
     [USE_THEN "face_vertices" MATCH_MP_TAC THEN
      USE_THEN "i_index" MATCH_ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "edge_cycle" (MP_TAC o SPEC `j:num`) THEN
    ANTS_TAC THENL
     [USE_THEN "j_index" MATCH_ACCEPT_TAC;
      INTRO_TAC "dj_edge v_dj dj_hj dj_hnext"] THEN
    USE_THEN "edge_cycle" (MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL
     [USE_THEN "i_index" MATCH_ACCEPT_TAC;
      INTRO_TAC "di_edge v_di di_hi di_hnext"] THEN
    SUBGOAL_THEN
     `(c:(A->bool)->real^2->bool) ((d:num->A->bool) (j:num))
      SUBSET frontier((h:num->real^2->bool) (i:num))`
    (LABEL_TAC "dj_hi") THENL
     [USE_THEN "predecessor" (fun th ->
        USE_THEN "dj_hnext"
         (MATCH_ACCEPT_TAC o REWRITE_RULE[GSYM th]));
      ALL_TAC] THEN
    SUBGOAL_THEN `~((d:num->A->bool) j = d i)`
    (LABEL_TAC "dj_di") THENL
     [DISCH_THEN(LABEL_TAC "same_edge") THEN
      SUBGOAL_THEN `(j:num) = i`
      (LABEL_TAC "same_index") THENL
       [MP_TAC(CONJUNCT2(REWRITE_RULE[INJ]
         (ASSUME
          `INJ (d:num->A->bool)
               (cyclic_indices m) (:(A->bool))`))) THEN
        DISCH_THEN MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
        USE_THEN "j_i" (fun nth ->
          USE_THEN "same_index" (fun sth ->
            CONTR_TAC(MP (NOT_ELIM nth) sth)))];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `(h:num->real^2->bool) i`;
      `(d:num->A->bool) j`; `(d:num->A->bool) i`; `e:A->bool`]
     PLANE_TRIANGULATED_DISK_INCIDENT_FACE_FRONTIER_EDGE_CHOICE) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "disk" MATCH_ACCEPT_TAC;
        USE_THEN "chordless" MATCH_ACCEPT_TAC;
        USE_THEN "hi_face" MATCH_ACCEPT_TAC;
        USE_THEN "dj_di" MATCH_ACCEPT_TAC;
        USE_THEN "dj_edge" MATCH_ACCEPT_TAC;
        USE_THEN "di_edge" MATCH_ACCEPT_TAC;
        USE_THEN "edge" MATCH_ACCEPT_TAC;
        USE_THEN "v_dj" MATCH_ACCEPT_TAC;
        USE_THEN "v_di" MATCH_ACCEPT_TAC;
        USE_THEN "incident" MATCH_ACCEPT_TAC;
        USE_THEN "dj_hi" MATCH_ACCEPT_TAC;
        USE_THEN "di_hi" MATCH_ACCEPT_TAC;
        USE_THEN "e_k" MATCH_ACCEPT_TAC];
      DISCH_THEN
       (DISJ_CASES_THEN2 (LABEL_TAC "e_dj") (LABEL_TAC "e_di"))] THENL
     [EXISTS_TAC `j:num` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[]];
    INTRO_TAC "@i. point i_index" THEN
    USE_THEN "point" SUBST_ALL_TAC THEN
    USE_THEN "edge_cycle" (MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL
     [USE_THEN "i_index" MATCH_ACCEPT_TAC;
      INTRO_TAC "di_edge v_di di_hi di_hnext"] THEN
    CONJ_TAC THENL
     [USE_THEN "di_edge" MATCH_ACCEPT_TAC;
      USE_THEN "v_di" MATCH_ACCEPT_TAC]]);;
let PLANE_TRIANGULATED_DISK_OUTER_EDGE_OPPOSITE_FACE_FRONTIER = prove
 (`!V E p c q n outer e.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        e IN cyclic_edges q n /\
        c e SUBSET frontier outer
        ==> ?l.
              l IN components
                ((:real^2) DIFF plane_graph_carrier V E p c) /\
              ~(l = outer) /\
              c e SUBSET frontier outer /\
              c e SUBSET frontier l /\
              e SUBSET plane_graph_face_vertices V E p c l`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "disk cycle_edge edge_outer" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective cycle_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN `(e:A->bool) IN E` (LABEL_TAC "edge") THENL
   [USE_THEN "cycle_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "cycle_edge" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_OUTER_JORDAN_SIDE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@j. simple loop image outer_side" THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) e SUBSET path_image j`
  (LABEL_TAC "edge_curve") THENL
   [USE_THEN "image" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[SUBSET; IN_UNIONS] THEN
    X_GEN_TAC `x:real^2` THEN DISCH_THEN(LABEL_TAC "x_edge") THEN
    EXISTS_TAC `(c:(A->bool)->real^2->bool) e` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `e:A->bool` THEN
      ASM_REWRITE_TAC[];
      USE_THEN "x_edge" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `path_image(j:real^1->real^2) SUBSET
    plane_graph_carrier (V:A->bool) E p c`
  (LABEL_TAC "curve_subset") THENL
   [USE_THEN "image" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC EDGE_IMAGE_UNIONS_SUBSET_PLANE_GRAPH_CARRIER THEN
    USE_THEN "cycle_edges" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPEC `j:real^1->real^2` JORDAN_INSIDE_OUTSIDE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "inside_nonempty inside_open inside_connected outside_nonempty \
    outside_open outside_connected inside_bounded outside_unbounded \
    sides_disjoint sides_union inside_frontier outside_frontier" THEN
  SUBGOAL_THEN
   `?s:real^2->bool.
      (s = inside(path_image j) \/ s = outside(path_image j)) /\
      DISJOINT outer s`
  MP_TAC THENL
   [USE_THEN "outer_side"
     (DISJ_CASES_THEN2
      (LABEL_TAC "outer_inside") (LABEL_TAC "outer_outside")) THENL
     [EXISTS_TAC `outside(path_image(j:real^1->real^2))` THEN
      CONJ_TAC THENL
       [DISJ2_TAC THEN REFL_TAC;
        MATCH_MP_TAC(SET_RULE
         `outer SUBSET inside(path_image(j:real^1->real^2)) /\
          inside(path_image j) INTER outside(path_image j) = {}
          ==> DISJOINT outer (outside(path_image j))`) THEN
        ASM_REWRITE_TAC[]];
      EXISTS_TAC `inside(path_image(j:real^1->real^2))` THEN
      CONJ_TAC THENL
       [DISJ1_TAC THEN REFL_TAC;
        MATCH_MP_TAC(SET_RULE
         `outer SUBSET outside(path_image(j:real^1->real^2)) /\
          inside(path_image j) INTER outside(path_image j) = {}
          ==> DISJOINT outer (inside(path_image j))`) THEN
        ASM_REWRITE_TAC[]]];
    INTRO_TAC "@s. s_side outer_s_disjoint"] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `e:A->bool`]
   PLANE_GRAPH_EMBEDDING_EDGE_INTERIOR_NONEMPTY) THEN
  ASM_REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
  INTRO_TAC "@x. x_middle" THEN
  SUBGOAL_THEN `(x:real^2) IN path_image j`
  (LABEL_TAC "x_curve") THENL
   [USE_THEN "edge_curve"
     (MATCH_MP_TAC o SPEC `x:real^2` o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "x_middle" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `j:real^1->real^2`;
    `s:real^2->bool`; `x:real^2`]
   PLANE_GRAPH_EMBEDDING_JORDAN_SIDE_INCIDENT_COMPONENT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC "@l. l_component l_subset x_frontier"] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) e SUBSET frontier l`
  (LABEL_TAC "edge_l") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`;
      `l:real^2->bool`; `x:real^2`]
     PLANE_GRAPH_EMBEDDING_EDGE_COMPONENT_FRONTIER) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((l:real^2->bool) = outer)`
  (LABEL_TAC "distinct") THENL
   [SUBGOAL_THEN `~((l:real^2->bool) = {})`
    (LABEL_TAC "l_nonempty") THENL
     [MATCH_MP_TAC(ISPECL
       [`(:real^2) DIFF
         plane_graph_carrier (V:A->bool) E p c`;
        `l:real^2->bool`]
       IN_COMPONENTS_NONEMPTY) THEN
      USE_THEN "l_component" ACCEPT_TAC;
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["l_nonempty"; "l_subset"; "outer_s_disjoint"] THEN
      SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(e:A->bool) SUBSET plane_graph_face_vertices V E p c l`
  (LABEL_TAC "edge_face") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`;
      `l:real^2->bool`]
     PLANE_GRAPH_EMBEDDING_FRONTIER_EDGE_SUBSET_FACE_VERTICES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `l:real^2->bool` THEN
  ASM_REWRITE_TAC[]);;

let PLANE_TRIANGULATED_DISK_OUTER_FACE_TWO_EDGE_ADJACENCIES_FRONTIER =
  prove
 (`!V E p c q n outer.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        c {q(n - 1),q(n - 2)} SUBSET frontier outer /\
        c {q(n - 1),q 0} SUBSET frontier outer
        ==> ?l1 l2.
              l1 IN plane_graph_incident_faces
                V E p c (q(n - 1)) /\
              l2 IN plane_graph_incident_faces
                V E p c (q(n - 1)) /\
              plane_graph_face_adjacent_at E c (q(n - 1)) outer l1 /\
              plane_graph_face_adjacent_at E c (q(n - 1)) outer l2 /\
              c {q(n - 1),q(n - 2)} SUBSET frontier outer /\
              c {q(n - 1),q 0} SUBSET frontier outer /\
              c {q(n - 1),q(n - 2)} SUBSET frontier l1 /\
              c {q(n - 1),q 0} SUBSET frontier l2`,
  REPEAT GEN_TAC THEN INTRO_TAC "disk left_outer right_outer" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective cycle_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN
   `{(q:num->A)(n - 1),q(n - 2)} IN cyclic_edges q n`
  (LABEL_TAC "left_cycle_edge") THENL
   [REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `n - 2` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      SUBGOAL_THEN `(n - 2) + 1 = n - 1`
      SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `(n - 1) MOD n = n - 1`
        SUBST1_TAC THENL
         [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
          MATCH_ACCEPT_TAC PAIR_SET_SYM]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{(q:num->A)(n - 1),q 0} IN cyclic_edges q n`
  (LABEL_TAC "right_cycle_edge") THENL
   [REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `n - 1` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      SUBGOAL_THEN `(n - 1) + 1 = n`
      SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[MOD_REFL]]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `{(q:num->A)(n - 1),q(n - 2)}`]
   PLANE_TRIANGULATED_DISK_OUTER_EDGE_OPPOSITE_FACE_FRONTIER) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@l1. l1_component l1_distinct left_l1 left_face" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `{(q:num->A)(n - 1),q 0}`]
   PLANE_TRIANGULATED_DISK_OUTER_EDGE_OPPOSITE_FACE_FRONTIER) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@l2. l2_component l2_distinct right_l2 right_face" THEN
  SUBGOAL_THEN
   `l1 IN plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1))`
  (LABEL_TAC "l1_incident") THENL
   [REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
    CONJ_TAC THENL
     [USE_THEN "l1_component" ACCEPT_TAC;
      USE_THEN "left_face" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      REWRITE_TAC[IN_INSERT]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `l2 IN plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1))`
  (LABEL_TAC "l2_incident") THENL
   [REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
    CONJ_TAC THENL
     [USE_THEN "l2_component" ACCEPT_TAC;
      USE_THEN "right_face" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      REWRITE_TAC[IN_INSERT]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_face_adjacent_at
      (E:(A->bool)->bool) c (q(n - 1)) outer l1`
  (LABEL_TAC "l1_adjacent") THENL
   [REWRITE_TAC[plane_graph_face_adjacent_at] THEN CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "l1_distinct" (fun dth ->
       USE_THEN "same" (fun sth ->
        CONTR_TAC(MP (NOT_ELIM dth) (SYM sth))));
      EXISTS_TAC `{(q:num->A)(n - 1),q(n - 2)}` THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "cycle_edges"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "left_cycle_edge" ACCEPT_TAC;
        REWRITE_TAC[IN_INSERT];
        USE_THEN "left_outer" ACCEPT_TAC;
        USE_THEN "left_l1" ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_face_adjacent_at
      (E:(A->bool)->bool) c (q(n - 1)) outer l2`
  (LABEL_TAC "l2_adjacent") THENL
   [REWRITE_TAC[plane_graph_face_adjacent_at] THEN CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "l2_distinct" (fun dth ->
       USE_THEN "same" (fun sth ->
        CONTR_TAC(MP (NOT_ELIM dth) (SYM sth))));
      EXISTS_TAC `{(q:num->A)(n - 1),q 0}` THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "cycle_edges"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "right_cycle_edge" ACCEPT_TAC;
        REWRITE_TAC[IN_INSERT];
        USE_THEN "right_outer" ACCEPT_TAC;
        USE_THEN "right_l2" ACCEPT_TAC]];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`l1:real^2->bool`; `l2:real^2->bool`] THEN
  ASM_REWRITE_TAC[]);;
let CARD_SUBSET_PAIR_LE_2 = prove
 (`!s:A->bool. !k l.
        s SUBSET {k,l}
        ==> CARD s <= 2`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "subset") THEN
  MP_TAC(ISPECL [`s:A->bool`; `{k,l}:A->bool`] CARD_SUBSET) THEN
  ASM_REWRITE_TAC[FINITE_INSERT; FINITE_EMPTY] THEN
  SIMP_TAC[CARD_CLAUSES; FINITE_INSERT; FINITE_EMPTY] THEN
  ARITH_TAC);;

let PLANE_TRIANGULATED_DISK_INCIDENT_FACE_OPPOSITES_DISTINCT = prove
 (`!V E p c q n outer newouter k l1 l2 e1 e2.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE q(n - 1))
             (induced_subgraph_edges E (V DELETE q(n - 1))) p c) /\
        outer SUBSET newouter /\
        (p:A->real^2) (q(n - 1)) IN newouter /\
        3 <= CARD(plane_graph_incident_faces
                    V E p c (q(n - 1))) /\
        k IN plane_graph_incident_faces V E p c (q(n - 1)) /\
        l1 IN plane_graph_incident_faces V E p c (q(n - 1)) /\
        l2 IN plane_graph_incident_faces V E p c (q(n - 1)) /\
        plane_graph_face_adjacent_at E c (q(n - 1)) k l1 /\
        ~(e1 = e2) /\
        e1 IN E /\ e2 IN E /\
        q(n - 1) IN e1 /\ q(n - 1) IN e2 /\
        c e1 SUBSET frontier k /\
        c e2 SUBSET frontier k /\
        c e1 SUBSET frontier l1 /\
        c e2 SUBSET frontier l2
        ==> ~(l1 = l2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk chordless newouter_component outer_subset last_newouter \
    card_large k_face l1_face l2_face k_l1 e1_e2 e1_edge e2_edge \
    v_e1 v_e2 e1_k e2_k e1_l1 e2_l2" THEN
  DISCH_THEN(LABEL_TAC "l1_l2") THEN
  SUBGOAL_THEN `~((k:real^2->bool) = l1)`
  (LABEL_TAC "k_not_l1") THENL
   [USE_THEN "k_l1" MP_TAC THEN
    REWRITE_TAC[plane_graph_face_adjacent_at] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `newouter:real^2->bool`;
    `k:real^2->bool`; `l1:real^2->bool`;
    `e1:A->bool`; `e2:A->bool`]
   PLANE_TRIANGULATED_DISK_INCIDENT_FACE_SHARED_TWO_EDGES_EXHAUST) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "disk" ACCEPT_TAC;
      USE_THEN "chordless" ACCEPT_TAC;
      USE_THEN "newouter_component" ACCEPT_TAC;
      USE_THEN "outer_subset" ACCEPT_TAC;
      USE_THEN "last_newouter" ACCEPT_TAC;
      USE_THEN "k_face" ACCEPT_TAC;
      USE_THEN "l1_face" ACCEPT_TAC;
      USE_THEN "k_not_l1" ACCEPT_TAC;
      USE_THEN "e1_e2" ACCEPT_TAC;
      USE_THEN "e1_edge" ACCEPT_TAC;
      USE_THEN "e2_edge" ACCEPT_TAC;
      USE_THEN "v_e1" ACCEPT_TAC;
      USE_THEN "v_e2" ACCEPT_TAC;
      USE_THEN "e1_k" ACCEPT_TAC;
      USE_THEN "e2_k" ACCEPT_TAC;
      USE_THEN "e1_l1" ACCEPT_TAC;
      USE_THEN "l1_l2" (fun th ->
        USE_THEN "e2_l2" (ACCEPT_TAC o REWRITE_RULE[GSYM th]))];
    DISCH_THEN(LABEL_TAC "faces_subset")] THEN
  MP_TAC(ISPECL
   [`plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1))`;
    `k:real^2->bool`; `l1:real^2->bool`]
   CARD_SUBSET_PAIR_LE_2) THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let PLANE_TRIANGULATED_DISK_INCIDENT_FACE_DEGREE_AT_LEAST_2 =
  prove
 (`!V E p c q n outer newouter k.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        c {q(n - 1),q(n - 2)} SUBSET frontier outer /\
        c {q(n - 1),q 0} SUBSET frontier outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE q(n - 1))
             (induced_subgraph_edges E (V DELETE q(n - 1))) p c) /\
        outer SUBSET newouter /\
        (p:A->real^2) (q(n - 1)) IN newouter /\
        3 <= CARD(plane_graph_incident_faces
                    V E p c (q(n - 1))) /\
        k IN plane_graph_incident_faces V E p c (q(n - 1))
        ==> ?l1 l2.
              l1 IN plane_graph_incident_faces
                V E p c (q(n - 1)) /\
              l2 IN plane_graph_incident_faces
                V E p c (q(n - 1)) /\
              ~(l1 = l2) /\
              plane_graph_face_adjacent_at E c (q(n - 1)) k l1 /\
              plane_graph_face_adjacent_at E c (q(n - 1)) k l2`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk left_outer right_outer chordless newouter_component \
    outer_subset last_newouter card_large k_face" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  ASM_CASES_TAC `(k:real^2->bool) = outer` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`]
     PLANE_TRIANGULATED_DISK_OUTER_FACE_TWO_EDGE_ADJACENCIES_FRONTIER) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      INTRO_TAC
       "@l1 l2. l1_face l2_face outer_l1 outer_l2 \
        left_outer_result right_outer_result left_l1 right_l2"] THEN
    ABBREV_TAC `(e1:A->bool) = {q(n - 1),q(n - 2)}` THEN
    ABBREV_TAC `(e2:A->bool) = {q(n - 1),q 0}` THEN
    SUBGOAL_THEN
     `!i j. i < n /\ j < n /\ ~(i = j)
            ==> ~((q:num->A) i = q j)`
    (LABEL_TAC "q_distinct") THENL
     [MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
      INTRO_TAC "i_index j_index i_j" THEN
      DISCH_THEN(LABEL_TAC "same") THEN
      MP_TAC(CONJUNCT2(REWRITE_RULE[INJ]
       (ASSUME `INJ (q:num->A) (cyclic_indices n) (:A)`))) THEN
      DISCH_THEN(MP_TAC o SPECL [`i:num`; `j:num`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((q:num->A)(n - 1) = q(n - 2)) /\
      ~(q(n - 1) = q 0) /\
      ~(q(n - 2) = q 0)`
    (CONJUNCTS_THEN2 (LABEL_TAC "last_previous")
     (CONJUNCTS_THEN2 (LABEL_TAC "last_first")
      (LABEL_TAC "previous_first"))) THENL
     [REPEAT CONJ_TAC THEN USE_THEN "q_distinct" MATCH_MP_TAC THEN
      ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((e1:A->bool) = e2)`
    (LABEL_TAC "e1_e2") THENL
     [EXPAND_TAC "e1" THEN EXPAND_TAC "e2" THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["last_previous"; "last_first"; "previous_first"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(e1:A->bool) IN cyclic_edges q n /\
      (e2:A->bool) IN cyclic_edges q n`
    (CONJUNCTS_THEN2 (LABEL_TAC "e1_cycle")
     (LABEL_TAC "e2_cycle")) THENL
     [EXPAND_TAC "e1" THEN EXPAND_TAC "e2" THEN CONJ_TAC THENL
       [REWRITE_TAC[IN_CYCLIC_EDGES] THEN
        EXISTS_TAC `n - 2` THEN CONJ_TAC THENL
         [ASM_ARITH_TAC;
          SUBGOAL_THEN `(n - 2) + 1 = n - 1`
          SUBST1_TAC THENL
           [ASM_ARITH_TAC;
            SUBGOAL_THEN `(n - 1) MOD n = n - 1`
            SUBST1_TAC THENL
             [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
              MATCH_ACCEPT_TAC PAIR_SET_SYM]]];
        REWRITE_TAC[IN_CYCLIC_EDGES] THEN
        EXISTS_TAC `n - 1` THEN CONJ_TAC THENL
         [ASM_ARITH_TAC;
          SUBGOAL_THEN `(n - 1) + 1 = n`
          SUBST1_TAC THENL
           [ASM_ARITH_TAC;
            REWRITE_TAC[MOD_REFL]]]];
      ALL_TAC] THEN
    SUBGOAL_THEN `(e1:A->bool) IN E /\ e2 IN E`
    (CONJUNCTS_THEN2 (LABEL_TAC "e1_edge")
     (LABEL_TAC "e2_edge")) THENL
     [CONJ_TAC THEN USE_THEN "boundary_edges"
       (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(q:num->A)(n - 1) IN e1 /\
      (q:num->A)(n - 1) IN e2`
    (CONJUNCTS_THEN2 (LABEL_TAC "v_e1")
     (LABEL_TAC "v_e2")) THENL
     [EXPAND_TAC "e1" THEN EXPAND_TAC "e2" THEN
      REWRITE_TAC[IN_INSERT];
      ALL_TAC] THEN
    SUBGOAL_THEN `~((l1:real^2->bool) = l2)`
    (LABEL_TAC "l1_l2") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
        `outer:real^2->bool`; `newouter:real^2->bool`;
        `outer:real^2->bool`; `l1:real^2->bool`;
        `l2:real^2->bool`; `e1:A->bool`; `e2:A->bool`]
       PLANE_TRIANGULATED_DISK_INCIDENT_FACE_OPPOSITES_DISTINCT) THEN
      ASM_REWRITE_TAC[] THEN
      EXPAND_TAC "e1" THEN EXPAND_TAC "e2" THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`l1:real^2->bool`; `l2:real^2->bool`] THEN
