     [REWRITE_TAC[IN_CYCLIC_INDICES] THEN
      USE_THEN "injective" ACCEPT_TAC;
      REWRITE_TAC[FINITE_CYCLIC_INDICES]];
    REWRITE_TAC[CARD_CYCLIC_INDICES]]);;

