let FINITE_RELATION_PATH_CYCLIC_CHAIN = prove
 (`!R:A->A->bool. !s f n.
        0 < n /\
        finite_relation_path R s f n /\
        R (f(n - 1)) (f 0)
        ==> !i. i < n ==> R (f i) (f((i + 1) MOD n))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "positive path closing" THEN
  USE_THEN "path" MP_TAC THEN
  REWRITE_TAC[finite_relation_path] THEN
  INTRO_TAC "vertices injective chain" THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "i_index") THEN
  ASM_CASES_TAC `i + 1 < n` THENL
   [SUBGOAL_THEN `(i + 1) MOD n = i + 1`
    (fun th -> REWRITE_TAC[th]) THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[];
      USE_THEN "chain" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
    SUBGOAL_THEN `(i:num) = n - 1` SUBST1_TAC THENL
     [ASM_ARITH_TAC;
      SUBGOAL_THEN `(n - 1) + 1 = n`
      (fun th -> REWRITE_TAC[th; MOD_REFL]) THENL
       [ASM_ARITH_TAC;
        USE_THEN "closing" ACCEPT_TAC]]]);;

let PLANE_GRAPH_FACE_ADJACENT_CYCLE_EDGE_SELECTION = prove
 (`!E:(A->bool)->bool. !c v s h m.
        0 < m /\
        finite_relation_path
          (plane_graph_face_adjacent_at E c v) s h m /\
        plane_graph_face_adjacent_at E c v (h(m - 1)) (h 0)
        ==> ?d:num->A->bool.
              !i. i < m
                  ==> d i IN E /\
                      v IN d i /\
                      c(d i) SUBSET frontier(h i) /\
                      c(d i) SUBSET frontier(h((i + 1) MOD m))`,
  REPEAT GEN_TAC THEN INTRO_TAC "positive path closing" THEN
  SUBGOAL_THEN
   `!i. i < m
        ==> plane_graph_face_adjacent_at
              (E:(A->bool)->bool) c v
              (h i) (h((i + 1) MOD m))`
  (LABEL_TAC "cyclic_chain") THENL
   [MATCH_MP_TAC(ISPECL
     [`plane_graph_face_adjacent_at
        (E:(A->bool)->bool) c v`;
      `s:(real^2->bool)->bool`; `h:num->real^2->bool`; `m:num`]
     FINITE_RELATION_PATH_CYCLIC_CHAIN) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC
   `\i. @e:A->bool.
          e IN E /\
          v IN e /\
          (c:(A->bool)->real^2->bool) e SUBSET
            frontier((h:num->real^2->bool) i) /\
          c e SUBSET frontier(h((i + 1) MOD m))` THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "i_index") THEN
  BETA_TAC THEN
  USE_THEN "cyclic_chain" (fun th ->
    MP_TAC(MATCH_MP (SPEC `i:num` th)
      (ASSUME `(i:num) < m`))) THEN
  REWRITE_TAC[plane_graph_face_adjacent_at] THEN
  INTRO_TAC "faces_distinct @e. edge incident left right" THEN
  MATCH_MP_TAC(BETA_RULE(ISPECL
   [`\d:A->bool.
        d IN E /\
        v IN d /\
        (c:(A->bool)->real^2->bool) d SUBSET
          frontier((h:num->real^2->bool) i) /\
        c d SUBSET frontier(h((i + 1) MOD m))`;
    `e:A->bool`]
   SELECT_AX)) THEN
  BETA_TAC THEN ASM_REWRITE_TAC[]);;

