let FINITE_RELATION_PATH_REVERSE = prove
 (`!R:A->A->bool. !s f n.
        (!x y. x IN s /\ y IN s /\ R x y ==> R y x) /\
        finite_relation_path R s f n
        ==> finite_relation_path R s (cyclic_reverse f n) n`,
  REPEAT GEN_TAC THEN INTRO_TAC "symmetric path" THEN
  USE_THEN "path" MP_TAC THEN
  REWRITE_TAC[finite_relation_path; cyclic_reverse] THEN
  INTRO_TAC "vertices injective chain" THEN
  REWRITE_TAC[finite_relation_path; cyclic_reverse] THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "i_index") THEN
    BETA_TAC THEN USE_THEN "vertices" MATCH_MP_TAC THEN
    ASM_ARITH_TAC;
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
    INTRO_TAC "i_index j_index same" THEN BETA_TAC THEN
    SUBGOAL_THEN
     `(n - 1 - i:num) = n - 1 - j`
    (LABEL_TAC "reverse_indices") THENL
     [USE_THEN "injective" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ASM_ARITH_TAC];
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "next_index") THEN
    BETA_TAC THEN
    USE_THEN "symmetric"
     (MATCH_MP_TAC o SPECL
       [`(f:num->A) (n - 1 - (i + 1))`;
        `(f:num->A) (n - 1 - i)`]) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "vertices" MATCH_MP_TAC THEN
      ASM_ARITH_TAC;
      USE_THEN "vertices" MATCH_MP_TAC THEN
      ASM_ARITH_TAC;
      USE_THEN "chain"
       (MP_TAC o SPEC `n - 1 - (i + 1)`) THEN
      ANTS_TAC THENL
       [ASM_ARITH_TAC;
        DISCH_THEN(LABEL_TAC "reverse_edge") THEN
        SUBGOAL_THEN
         `(n - 1 - (i + 1)) + 1 = n - 1 - i`
        (fun th ->
          USE_THEN "reverse_edge"
           (ACCEPT_TAC o REWRITE_RULE[th])) THEN
        ASM_ARITH_TAC]]]);;

let FINITE_RELATION_PATH_ENDPOINTS_RELATED_AT_FIRST = prove
 (`!R:A->A->bool. !s f n.
        3 <= n /\
        finite_relation_path R s f n /\
        IMAGE f (cyclic_indices n) = s /\
        (!x. x IN s ==> ~R x x) /\
        (!x y. x IN s /\ y IN s /\ R x y ==> R y x) /\
        (?y z.
             y IN s /\ z IN s /\ ~(y = z) /\
             R (f 0) y /\ R (f 0) z) /\
        (!x y1 y2 y3.
             x IN s /\ y1 IN s /\ y2 IN s /\ y3 IN s /\
             R x y1 /\ R x y2 /\ R x y3
             ==> y1 = y2 \/ y1 = y3 \/ y2 = y3)
        ==> R (f(n - 1)) (f 0)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "large path coverage irreflexive symmetric first_degree \
    degree_at_most_2" THEN
  USE_THEN "path" MP_TAC THEN
  REWRITE_TAC[finite_relation_path] THEN
  INTRO_TAC "vertices injective relation_chain" THEN
  SUBGOAL_THEN
   `(f:num->A) 0 IN s /\ f 1 IN s /\ f(n - 1) IN s`
  (CONJUNCTS_THEN2 (LABEL_TAC "first_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "second_vertex")
    (LABEL_TAC "last_vertex"))) THENL
   [REPEAT CONJ_TAC THEN
    USE_THEN "vertices" MATCH_MP_TAC THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(R:A->A->bool) ((f:num->A) 0) (f 1)`
  (LABEL_TAC "first_edge") THENL
   [USE_THEN "relation_chain" (MP_TAC o SPEC `0`) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[ADD_CLAUSES]];
    ALL_TAC] THEN
  USE_THEN "first_degree" MP_TAC THEN
  INTRO_TAC
   "@y z. y_vertex z_vertex y_z y_edge z_edge" THEN
  USE_THEN "degree_at_most_2"
   (MP_TAC o SPECL
     [`(f:num->A) 0`; `y:A`; `z:A`; `(f:num->A) 1`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(LABEL_TAC "one_is_second")] THEN
  SUBGOAL_THEN
   `?u:A.
      u IN s /\
      ~(u = (f:num->A) 0) /\
      ~(u = f 1) /\
      (R:A->A->bool) (f 0) u`
  MP_TAC THENL
   [USE_THEN "irreflexive" (MP_TAC o SPEC `(f:num->A) 0`) THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["first_vertex"; "y_vertex"; "z_vertex"; "y_z";
      "y_edge"; "z_edge"; "one_is_second"] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[];
    INTRO_TAC "@u. u_vertex u_not_first u_not_second u_edge"] THEN
  USE_THEN "u_vertex" MP_TAC THEN
  USE_THEN "coverage" (fun th -> REWRITE_TAC[GSYM th]) THEN
  REWRITE_TAC[IN_IMAGE; IN_CYCLIC_INDICES] THEN
  INTRO_TAC "@j. u_point j_index" THEN
  SUBGOAL_THEN `(j:num) = n - 1`
  (LABEL_TAC "j_last") THENL
   [ASM_CASES_TAC `(j:num) = n - 1` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `1 < (j:num) /\ j + 1 < n`
    (CONJUNCTS_THEN2 (LABEL_TAC "j_after_second")
     (LABEL_TAC "j_before_last")) THENL
     [SUBGOAL_THEN `~((j:num) = 0) /\ ~(j = 1)`
      STRIP_ASSUME_TAC THENL
       [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
         ["u_not_first"; "u_not_second"; "u_point"] THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[];
        ASM_ARITH_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(f:num->A) (j - 1) IN s /\ f(j + 1) IN s`
    (CONJUNCTS_THEN2 (LABEL_TAC "previous_vertex")
     (LABEL_TAC "next_vertex")) THENL
     [CONJ_TAC THEN USE_THEN "vertices" MATCH_MP_TAC THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(R:A->A->bool) ((f:num->A) j) (f(j - 1)) /\
      R (f j) (f(j + 1))`
    (CONJUNCTS_THEN2 (LABEL_TAC "previous_edge")
     (LABEL_TAC "next_edge")) THENL
     [CONJ_TAC THENL
       [USE_THEN "symmetric"
         (MP_TAC o SPECL [`(f:num->A)(j - 1)`; `(f:num->A) j`]) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THENL
           [USE_THEN "previous_vertex" ACCEPT_TAC;
            USE_THEN "u_point" (fun th ->
              USE_THEN "u_vertex" (ACCEPT_TAC o REWRITE_RULE[th]));
            SUBGOAL_THEN `(j - 1) + 1 = j`
            (LABEL_TAC "previous_successor") THENL
             [ASM_ARITH_TAC;
              USE_THEN "relation_chain" (MP_TAC o SPEC `j - 1`) THEN
              ANTS_TAC THENL
               [ASM_ARITH_TAC;
                ASM_REWRITE_TAC[]]]];
          DISCH_THEN ACCEPT_TAC];
        USE_THEN "relation_chain" MATCH_MP_TAC THEN
        USE_THEN "j_before_last" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((f:num->A) 0 = f(j - 1)) /\
      ~(f 0 = f(j + 1)) /\
      ~(f(j - 1) = f(j + 1))`
    (CONJUNCTS_THEN2 (LABEL_TAC "first_not_previous")
     (CONJUNCTS_THEN2 (LABEL_TAC "first_not_next")
      (LABEL_TAC "previous_not_next"))) THENL
     [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["injective"; "large"; "j_index";
        "j_after_second"; "j_before_last"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN
      MESON_TAC[ARITH_RULE
       `3 <= n /\ j < n /\ 1 < j /\ j + 1 < n
        ==> 0 < n /\ j - 1 < n /\ j + 1 < n /\
            ~(0 = j - 1) /\ ~(0 = j + 1) /\
            ~(j - 1 = j + 1)`];
      ALL_TAC] THEN
    USE_THEN "degree_at_most_2"
     (MP_TAC o SPECL
       [`(f:num->A) j`; `(f:num->A) 0`;
        `(f:num->A)(j - 1)`; `(f:num->A)(j + 1)`]) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "u_point" (fun th ->
         USE_THEN "u_vertex" (ACCEPT_TAC o REWRITE_RULE[th]));
        USE_THEN "first_vertex" ACCEPT_TAC;
        USE_THEN "previous_vertex" ACCEPT_TAC;
        USE_THEN "next_vertex" ACCEPT_TAC;
        USE_THEN "symmetric"
         (MP_TAC o SPECL [`(f:num->A) 0`; `u:A`]) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[];
          DISCH_THEN(LABEL_TAC "u_reverse")] THEN
        USE_THEN "u_point" (fun th ->
          USE_THEN "u_reverse" (ACCEPT_TAC o REWRITE_RULE[th]));
        USE_THEN "previous_edge" ACCEPT_TAC;
        USE_THEN "next_edge" ACCEPT_TAC];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  USE_THEN "symmetric"
   (MATCH_MP_TAC o SPECL [`(f:num->A) 0`; `(f:num->A)(n - 1)`]) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "first_vertex" ACCEPT_TAC;
    USE_THEN "last_vertex" ACCEPT_TAC;
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["u_edge"; "u_point"; "j_last"] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[]]);;

let FINITE_RELATION_PATH_ENDPOINTS_RELATED_AT_EITHER = prove
 (`!R:A->A->bool. !s f n.
        3 <= n /\
        finite_relation_path R s f n /\
        IMAGE f (cyclic_indices n) = s /\
        (!x. x IN s ==> ~R x x) /\
        (!x y. x IN s /\ y IN s /\ R x y ==> R y x) /\
        ((?y z.
             y IN s /\ z IN s /\ ~(y = z) /\
             R (f 0) y /\ R (f 0) z) \/
         (?y z.
             y IN s /\ z IN s /\ ~(y = z) /\
             R (f(n - 1)) y /\ R (f(n - 1)) z)) /\
        (!x y1 y2 y3.
             x IN s /\ y1 IN s /\ y2 IN s /\ y3 IN s /\
             R x y1 /\ R x y2 /\ R x y3
             ==> y1 = y2 \/ y1 = y3 \/ y2 = y3)
        ==> R (f(n - 1)) (f 0)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "large path coverage irreflexive symmetric endpoint_degree \
    degree_at_most_2" THEN
  USE_THEN "endpoint_degree"
   (DISJ_CASES_THEN2
    (LABEL_TAC "first_degree") (LABEL_TAC "last_degree")) THENL
   [MATCH_MP_TAC(ISPECL
     [`R:A->A->bool`; `s:A->bool`; `f:num->A`; `n:num`]
     FINITE_RELATION_PATH_ENDPOINTS_RELATED_AT_FIRST) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_relation_path (R:A->A->bool) s
      (cyclic_reverse (f:num->A) n) n`
  (LABEL_TAC "reverse_path") THENL
   [MATCH_MP_TAC FINITE_RELATION_PATH_REVERSE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (cyclic_reverse (f:num->A) n) (cyclic_indices n) = s`
  (LABEL_TAC "reverse_coverage") THENL
   [TRANS_TAC EQ_TRANS
     `IMAGE (f:num->A) (cyclic_indices n)` THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`f:num->A`; `n:num`]
       CYCLIC_VERTICES_REVERSE) THEN
      REWRITE_TAC[cyclic_vertices];
      USE_THEN "coverage" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?y z:A.
      y IN s /\ z IN s /\ ~(y = z) /\
      R (cyclic_reverse (f:num->A) n 0) y /\
      R (cyclic_reverse f n 0) z`
  (LABEL_TAC "reverse_first_degree") THENL
   [USE_THEN "last_degree" MP_TAC THEN
    REWRITE_TAC[cyclic_reverse; SUB_0];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(R:A->A->bool)
     (cyclic_reverse (f:num->A) n (n - 1))
     (cyclic_reverse f n 0)`
  (LABEL_TAC "reverse_closing") THENL
   [MATCH_MP_TAC(ISPECL
     [`R:A->A->bool`; `s:A->bool`;
      `cyclic_reverse (f:num->A) n`; `n:num`]
     FINITE_RELATION_PATH_ENDPOINTS_RELATED_AT_FIRST) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(f:num->A) 0 IN s /\ f(n - 1) IN s`
  (CONJUNCTS_THEN2
    (LABEL_TAC "first_vertex") (LABEL_TAC "last_vertex")) THENL
   [USE_THEN "path" MP_TAC THEN
    REWRITE_TAC[finite_relation_path] THEN
    INTRO_TAC "vertices _ _" THEN
    CONJ_TAC THEN USE_THEN "vertices" MATCH_MP_TAC THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "symmetric"
   (MATCH_MP_TAC o SPECL
     [`(f:num->A) 0`; `(f:num->A)(n - 1)`]) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "first_vertex" ACCEPT_TAC;
    USE_THEN "last_vertex" ACCEPT_TAC;
    USE_THEN "reverse_closing" MP_TAC THEN
    REWRITE_TAC[cyclic_reverse; SUB_0; SUB_REFL]]);;

let PLANE_TRIANGULATED_DISK_INTERNAL_INCIDENT_FACE_DEGREE_AT_LEAST_2 =
  prove
 (`!V E p c q n outer newouter k.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE q(n - 1))
             (induced_subgraph_edges E (V DELETE q(n - 1))) p c) /\
        outer SUBSET newouter /\
        (p:A->real^2) (q(n - 1)) IN newouter /\
        3 <= CARD(plane_graph_incident_faces
                    V E p c (q(n - 1))) /\
        k IN plane_graph_incident_faces V E p c (q(n - 1)) /\
        ~(k = outer)
        ==> ?l1 l2.
              l1 IN plane_graph_incident_faces
                V E p c (q(n - 1)) /\
              l2 IN plane_graph_incident_faces
                V E p c (q(n - 1)) /\
              ~(l1 = l2) /\
              plane_graph_face_adjacent_at E c (q(n - 1)) k l1 /\
              plane_graph_face_adjacent_at E c (q(n - 1)) k l2`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk chordless newouter_component outer_subset last_newouter \
    card_large k_face k_not_outer" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `k:real^2->bool`;
    `(q:num->A)(n - 1)`]
   PLANE_TRIANGULATED_DISK_INTERNAL_FACE_TWO_EDGE_ADJACENCIES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@e1 e2 l1 l2. e1_e2 e1_edge e2_edge v_e1 v_e2 \
    e1_k e1_l1 e2_k e2_l2 l1_component v_l1 \
    l2_component v_l2 k_l1 k_l2" THEN
  SUBGOAL_THEN
   `(l1:real^2->bool) IN
      plane_graph_incident_faces
        (V:A->bool) (E:(A->bool)->bool) (p:A->real^2)
        (c:(A->bool)->real^2->bool) ((q:num->A)(n - 1)) /\
    (l2:real^2->bool) IN
      plane_graph_incident_faces V E p c (q(n - 1))`
  (CONJUNCTS_THEN2 (LABEL_TAC "l1_face")
   (LABEL_TAC "l2_face")) THENL
   [CONJ_TAC THEN
    REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((l1:real^2->bool) = l2)`
  (LABEL_TAC "l1_l2") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `newouter:real^2->bool`;
      `k:real^2->bool`; `l1:real^2->bool`;
      `l2:real^2->bool`; `e1:A->bool`; `e2:A->bool`]
     PLANE_TRIANGULATED_DISK_INCIDENT_FACE_OPPOSITES_DISTINCT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`l1:real^2->bool`; `l2:real^2->bool`] THEN
  ASM_REWRITE_TAC[]);;

let
 PLANE_TRIANGULATED_DISK_INCIDENT_FACE_PATH_ENDPOINTS_ADJACENT_CHORDLESS =
  prove
 (`!V E p c q n outer newouter m h.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE q(n - 1))
             (induced_subgraph_edges E (V DELETE q(n - 1))) p c) /\
        outer SUBSET newouter /\
        (p:A->real^2) (q(n - 1)) IN newouter /\
        3 <= m /\
        finite_relation_path
          (plane_graph_face_adjacent_at E c (q(n - 1)))
          (plane_graph_incident_faces V E p c (q(n - 1)))
          h m /\
        IMAGE h (cyclic_indices m) =
          plane_graph_incident_faces V E p c (q(n - 1))
        ==> plane_graph_face_adjacent_at E c (q(n - 1))
              (h(m - 1)) (h 0)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk chordless newouter_component outer_subset last_newouter \
    mlarge path coverage" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN
   `FINITE(plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1)))`
  (LABEL_TAC "finite_faces") THENL
   [MATCH_MP_TAC FINITE_PLANE_GRAPH_INCIDENT_FACES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `m <= CARD(plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1)))`
  (LABEL_TAC "path_length") THENL
   [MATCH_MP_TAC(ISPECL
     [`plane_graph_face_adjacent_at
        (E:(A->bool)->bool) c (q(n - 1))`;
      `plane_graph_incident_faces
        (V:A->bool) E p c (q(n - 1))`;
      `h:num->real^2->bool`; `m:num`]
     FINITE_RELATION_PATH_LENGTH_LE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `3 <= CARD(plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1)))`
  (LABEL_TAC "faces_large") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(h:num->real^2->bool) 0 IN
      plane_graph_incident_faces (V:A->bool) E p c (q(n - 1)) /\
    h(m - 1) IN
      plane_graph_incident_faces V E p c (q(n - 1)) /\
    ~(h 0 = h(m - 1))`
  (CONJUNCTS_THEN2 (LABEL_TAC "first_face")
   (CONJUNCTS_THEN2
    (LABEL_TAC "last_face") (LABEL_TAC "endpoints_distinct"))) THENL
   [USE_THEN "path" MP_TAC THEN
    REWRITE_TAC[finite_relation_path] THEN
    INTRO_TAC "vertices injective chain" THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "vertices" MATCH_MP_TAC THEN ASM_ARITH_TAC;
      USE_THEN "vertices" MATCH_MP_TAC THEN ASM_ARITH_TAC;
      DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "injective"
       (MP_TAC o SPECL [`0`; `(m:num) - 1`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [ASM_ARITH_TAC;
          ASM_ARITH_TAC;
          USE_THEN "same" ACCEPT_TAC];
        ASM_ARITH_TAC]];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`plane_graph_face_adjacent_at
      (E:(A->bool)->bool) c (q(n - 1))`;
    `plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1))`;
    `h:num->real^2->bool`; `m:num`]
   FINITE_RELATION_PATH_ENDPOINTS_RELATED_AT_EITHER) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "mlarge" ACCEPT_TAC;
    USE_THEN "path" ACCEPT_TAC;
    USE_THEN "coverage" ACCEPT_TAC;
    X_GEN_TAC `k:real^2->bool` THEN
    DISCH_THEN(LABEL_TAC "k_face") THEN
    MATCH_ACCEPT_TAC
     (ISPECL
       [`E:(A->bool)->bool`; `c:(A->bool)->real^2->bool`;
        `(q:num->A)(n - 1)`; `k:real^2->bool`]
       PLANE_GRAPH_FACE_ADJACENT_AT_IRREFL);
    MAP_EVERY X_GEN_TAC
     [`k:real^2->bool`; `l:real^2->bool`] THEN
    INTRO_TAC "k_face l_face adjacent" THEN
    USE_THEN "adjacent" MP_TAC THEN
    REWRITE_TAC[PLANE_GRAPH_FACE_ADJACENT_AT_SYM];
    SUBGOAL_THEN
     `~((h:num->real^2->bool) 0 = outer) \/
      ~(h(m - 1) = outer)`
    (DISJ_CASES_THEN2
      (LABEL_TAC "first_not_outer") (LABEL_TAC "last_not_outer")) THENL
     [USE_THEN "endpoints_distinct" MP_TAC THEN MESON_TAC[];
      DISJ1_TAC THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
        `outer:real^2->bool`; `newouter:real^2->bool`;
        `(h:num->real^2->bool) 0`]
       PLANE_TRIANGULATED_DISK_INTERNAL_INCIDENT_FACE_DEGREE_AT_LEAST_2) THEN
      ASM_REWRITE_TAC[];
      DISJ2_TAC THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
        `outer:real^2->bool`; `newouter:real^2->bool`;
        `(h:num->real^2->bool)(m - 1)`]
       PLANE_TRIANGULATED_DISK_INTERNAL_INCIDENT_FACE_DEGREE_AT_LEAST_2) THEN
      ASM_REWRITE_TAC[]];
    MAP_EVERY X_GEN_TAC
     [`k:real^2->bool`; `l1:real^2->bool`;
      `l2:real^2->bool`; `l3:real^2->bool`] THEN
    INTRO_TAC
     "k_face l1_face l2_face l3_face adjacent1 adjacent2 adjacent3" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `k:real^2->bool`;
      `l1:real^2->bool`; `l2:real^2->bool`; `l3:real^2->bool`]
     PLANE_TRIANGULATED_DISK_INCIDENT_FACE_ADJACENCY_DEGREE_2) THEN
    ASM_REWRITE_TAC[]]);;

let CARD_TRIPLE_EQ_3 = prove
 (`!a b c:A.
        ~(a = b) /\ ~(a = c) /\ ~(b = c)
        ==> CARD {a,b,c} = 3`,
  REPEAT STRIP_TAC THEN
  SIMP_TAC[CARD_CLAUSES; FINITE_INSERT; FINITE_EMPTY] THEN
  ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC);;

let PLANE_TRIANGULATED_DISK_INCIDENT_EDGE_OUTER_FRONTIER_SMALL =
  prove
 (`!V E p c q n outer e.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        e IN E /\
        q(n - 1) IN e /\
        CARD(plane_graph_incident_faces V E p c (q(n - 1))) < 3
        ==> c e SUBSET frontier outer`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "disk edge last_edge faces_small" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN
   `FINITE(plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1)))`
  (LABEL_TAC "finite_faces") THENL
   [MATCH_MP_TAC FINITE_PLANE_GRAPH_INCIDENT_FACES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(outer:real^2->bool) IN
    plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1))`
  (LABEL_TAC "outer_face") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `(q:num->A)(n - 1)`]
     PLANE_TRIANGULATED_DISK_OUTER_INCIDENT_FACE) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `e:A->bool`]
   PLANE_GRAPH_EMBEDDING_EDGE_INCIDENT_COMPONENT_FRONTIER) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@k. k_component e_k" THEN
  SUBGOAL_THEN
   `(e:A->bool) SUBSET
    plane_graph_face_vertices V E p c k`
  (LABEL_TAC "e_face_k") THENL
   [MATCH_MP_TAC
     PLANE_GRAPH_EMBEDDING_FRONTIER_EDGE_SUBSET_FACE_VERTICES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(k:real^2->bool) IN
    plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1))`
  (LABEL_TAC "k_face") THENL
   [REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
    CONJ_TAC THENL
     [USE_THEN "k_component" ACCEPT_TAC;
      USE_THEN "e_face_k" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "last_edge" ACCEPT_TAC];
    ALL_TAC] THEN
  ASM_CASES_TAC `(k:real^2->bool) = outer` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    USE_THEN "e_k" ACCEPT_TAC;
    FIRST_X_ASSUM(LABEL_TAC "k_not_outer")] THEN
  USE_THEN "disk" MP_TAC THEN
  REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC "_ _ _ _ _ _ triangular" THEN
  USE_THEN "triangular" (MP_TAC o SPEC `k:real^2->bool`) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  INTRO_TAC "@r. k_vertices r_cycle" THEN
  SUBGOAL_THEN `(e:A->bool) IN cyclic_edges r 3`
  (LABEL_TAC "e_cycle") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `k:real^2->bool`;
      `r:num->A`; `e:A->bool`]
     PLANE_GRAPH_EMBEDDING_TRIANGULAR_FACE_FRONTIER_EDGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `k:real^2->bool`;
    `r:num->A`; `e:A->bool`]
   PLANE_TRIANGULATED_DISK_TRIANGULAR_FACE_OPPOSITE_EDGE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@l. l_component l_not_k e_face_l e_l l_face_data" THEN
  SUBGOAL_THEN
   `(l:real^2->bool) IN
    plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1))`
  (LABEL_TAC "l_face") THENL
   [REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
    CONJ_TAC THENL
     [USE_THEN "l_component" ACCEPT_TAC;
      USE_THEN "e_face_l" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "last_edge" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(l:real^2->bool) = outer`
  (LABEL_TAC "l_outer") THENL
   [ASM_CASES_TAC `(l:real^2->bool) = outer` THENL
     [ASM_REWRITE_TAC[];
      FIRST_X_ASSUM(LABEL_TAC "l_not_outer")] THEN
    SUBGOAL_THEN
     `{outer,k,l} SUBSET
      plane_graph_incident_faces
        (V:A->bool) E p c (q(n - 1))`
    (LABEL_TAC "three_faces") THENL
     [REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `CARD {outer,k,l:real^2->bool} = 3`
    (LABEL_TAC "three_card") THENL
     [MATCH_MP_TAC CARD_TRIPLE_EQ_3 THEN
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["k_not_outer"; "l_not_outer"; "l_not_k"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
      ALL_TAC] THEN
    USE_THEN "three_faces" (fun sth ->
      USE_THEN "finite_faces" (fun fth ->
        MP_TAC(MATCH_MP
         (ISPECL
          [`{outer,k,l}:(real^2->bool)->bool`;
           `plane_graph_incident_faces
             (V:A->bool) E p c (q(n - 1))`]
          CARD_SUBSET)
         (CONJ sth fth)))) THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["three_card"; "faces_small"] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "l_outer" (fun th ->
    USE_THEN "e_l" (ACCEPT_TAC o REWRITE_RULE[th])));;

let
 PLANE_TRIANGULATED_DISK_INCIDENT_FACE_SPANNING_CYCLE_OUTER_CHORDLESS =
  prove
 (`!V E p c q n outer newouter.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        newouter IN components
          ((:real^2) DIFF
           plane_graph_carrier (V DELETE q(n - 1))
             (induced_subgraph_edges E (V DELETE q(n - 1))) p c) /\
        outer SUBSET newouter /\
        (p:A->real^2) (q(n - 1)) IN newouter /\
        3 <= CARD(plane_graph_incident_faces
                    V E p c (q(n - 1)))
        ==> ?m h.
              3 <= m /\
              finite_relation_path
                (plane_graph_face_adjacent_at E c (q(n - 1)))
                (plane_graph_incident_faces V E p c (q(n - 1)))
                h m /\
              IMAGE h (cyclic_indices m) =
                plane_graph_incident_faces V E p c (q(n - 1)) /\
              h 0 = outer /\
              plane_graph_face_adjacent_at E c (q(n - 1))
                (h(m - 1)) (h 0)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk chordless newouter_component outer_subset last_newouter \
    faces_large" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `newouter:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INCIDENT_FACE_ADJACENCY_SPANNING_PATH_OUTER) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@m f r. positive path coverage r_index outer_point" THEN
  SUBGOAL_THEN
   `CARD(plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1))) = m`
  (LABEL_TAC "faces_card") THENL
   [MATCH_MP_TAC(ISPECL
     [`plane_graph_face_adjacent_at
        (E:(A->bool)->bool) c (q(n - 1))`;
      `plane_graph_incident_faces
        (V:A->bool) E p c (q(n - 1))`;
      `f:num->real^2->bool`; `m:num`]
     FINITE_RELATION_PATH_COVERAGE_CARD) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `3 <= m` (LABEL_TAC "mlarge") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_face_adjacent_at
      (E:(A->bool)->bool) c (q(n - 1)) (f(m - 1)) (f 0)`
  (LABEL_TAC "closing") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `newouter:real^2->bool`;
      `m:num`; `f:num->real^2->bool`]
     PLANE_TRIANGULATED_DISK_INCIDENT_FACE_PATH_ENDPOINTS_ADJACENT_CHORDLESS)
    THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`plane_graph_face_adjacent_at
      (E:(A->bool)->bool) c (q(n - 1))`;
    `plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1))`;
    `f:num->real^2->bool`; `m:num`; `r:num`]
   FINITE_RELATION_PATH_CYCLIC_OFFSET) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "rotated_path rotated_coverage rotated_first" THEN
  ABBREV_TAC
   `(h:num->real^2->bool) = \i. f((i + r) MOD m)` THEN
  SUBGOAL_THEN `(h:num->real^2->bool) 0 = outer`
  (LABEL_TAC "h_outer") THENL
   [EXPAND_TAC "h" THEN BETA_TAC THEN
    TRANS_TAC EQ_TRANS `(f:num->real^2->bool) r` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_face_adjacent_at
      (E:(A->bool)->bool) c (q(n - 1)) (h(m - 1)) (h 0)`
  (LABEL_TAC "h_closing") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `newouter:real^2->bool`;
      `m:num`; `h:num->real^2->bool`]
     PLANE_TRIANGULATED_DISK_INCIDENT_FACE_PATH_ENDPOINTS_ADJACENT_CHORDLESS)
    THEN
    ASM_REWRITE_TAC[] THEN
    EXPAND_TAC "h" THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`m:num`; `h:num->real^2->bool`] THEN
  ASM_REWRITE_TAC[] THEN
  EXPAND_TAC "h" THEN ASM_REWRITE_TAC[]);;

let PLANE_TRIANGULATED_DISK_CHORDLESS_OUTER_FRONTIER_EDGES_AT_LAST =
  prove
 (`!V E p c q n outer.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E))
        ==> c {q(n - 1),q(n - 2)} SUBSET frontier outer /\
            c {q(n - 1),q 0} SUBSET frontier outer`,
  REPEAT GEN_TAC THEN INTRO_TAC "disk chordless" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN
   `{(q:num->A)(n - 1),q(n - 2)} IN cyclic_edges q n /\
    {(q:num->A)(n - 1),q 0} IN cyclic_edges q n`
  (CONJUNCTS_THEN2
   (LABEL_TAC "left_cycle_edge") (LABEL_TAC "right_cycle_edge")) THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[IN_CYCLIC_EDGES] THEN
      EXISTS_TAC `n - 2` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `(n:num) - 2 + 1 = n - 1`
        SUBST1_TAC THENL
         [ASM_ARITH_TAC;
          SUBGOAL_THEN `(n - 1) MOD n = n - 1`
          SUBST1_TAC THENL
           [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
            MATCH_ACCEPT_TAC PAIR_SET_SYM]]];
      REWRITE_TAC[IN_CYCLIC_EDGES] THEN
      EXISTS_TAC `n - 1` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `(n:num) - 1 + 1 = n`
        SUBST1_TAC THENL
         [ASM_ARITH_TAC;
          REWRITE_TAC[MOD_REFL]]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{(q:num->A)(n - 1),q(n - 2)} IN E /\
    {(q:num->A)(n - 1),q 0} IN E`
  (CONJUNCTS_THEN2
   (LABEL_TAC "left_edge") (LABEL_TAC "right_edge")) THENL
   [CONJ_TAC THEN USE_THEN "boundary_edges"
     (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC
   `CARD(plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1))) < 3` THENL
   [FIRST_X_ASSUM(LABEL_TAC "faces_small") THEN
    CONJ_TAC THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`]
     PLANE_TRIANGULATED_DISK_INCIDENT_EDGE_OUTER_FRONTIER_SMALL) THEN
    ASM_REWRITE_TAC[IN_INSERT];
    FIRST_X_ASSUM(LABEL_TAC "faces_not_small")] THEN
  SUBGOAL_THEN
   `3 <= CARD(plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1)))`
  (LABEL_TAC "faces_large") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:num->A)(n - 1) IN cyclic_vertices q n`
  (LABEL_TAC "last_boundary") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `(q:num->A)(n - 1)`]
   PLANE_TRIANGULATED_DISK_DELETE_VERTEX_OUTER_COMPONENT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@newouter. newouter_component outer_subset last_newouter" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `newouter:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INCIDENT_FACE_SPANNING_CYCLE_OUTER_CHORDLESS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@m h. mlarge path coverage h_outer closing" THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `c:(A->bool)->real^2->bool`;
    `(q:num->A)(n - 1)`;
    `plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1))`;
    `h:num->real^2->bool`; `m:num`]
   PLANE_GRAPH_FACE_ADJACENT_CYCLE_EDGE_SELECTION) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    INTRO_TAC "@d. edge_cycle"] THEN
  SUBGOAL_THEN
   `INJ (d:num->A->bool) (cyclic_indices m) (:(A->bool))`
  (LABEL_TAC "d_injective") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `(q:num->A)(n - 1)`;
      `h:num->real^2->bool`; `m:num`; `d:num->A->bool`]
     PLANE_GRAPH_FACE_ADJACENT_CYCLE_EDGES_INJ) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "edge_cycle" (MP_TAC o SPEC `0`) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    INTRO_TAC "d0_edge v_d0 d0_left d0_right"] THEN
  USE_THEN "edge_cycle" (MP_TAC o SPEC `m - 1`) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    INTRO_TAC
     "dlast_edge v_dlast dlast_left dlast_right"] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) (d 0) SUBSET frontier outer`
  (LABEL_TAC "d0_outer") THENL
   [USE_THEN "h_outer" (fun th ->
      USE_THEN "d0_left" (ACCEPT_TAC o REWRITE_RULE[th]));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) (d(m - 1))
    SUBSET frontier outer`
  (LABEL_TAC "dlast_outer") THENL
   [SUBGOAL_THEN `((m:num) - 1 + 1) MOD m = 0`
    (LABEL_TAC "wrap") THENL
     [SUBGOAL_THEN `(m:num) - 1 + 1 = m`
      (fun th -> REWRITE_TAC[th; MOD_REFL]) THEN
      ASM_ARITH_TAC;
      USE_THEN "wrap" (fun th ->
       USE_THEN "h_outer" (fun hth ->
        USE_THEN "dlast_right"
         (ACCEPT_TAC o REWRITE_RULE[th; hth])))];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((d:num->A->bool) 0 = d(m - 1))`
  (LABEL_TAC "selected_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same_edge") THEN
    USE_THEN "d_injective"
     (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
    DISCH_THEN(MP_TAC o SPECL [`0`; `m - 1`]) THEN
    ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `(d:num->A->bool) 0`]
   PLANE_TRIANGULATED_DISK_OUTER_FRONTIER_EDGE_AT_LAST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "d0_choice") THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `(d:num->A->bool) (m - 1)`]
   PLANE_TRIANGULATED_DISK_OUTER_FRONTIER_EDGE_AT_LAST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "dlast_choice") THEN
  USE_THEN "d0_choice"
   (DISJ_CASES_THEN2
    (LABEL_TAC "d0_is_left") (LABEL_TAC "d0_is_right")) THENL
   [USE_THEN "dlast_choice"
     (DISJ_CASES_THEN2
      (LABEL_TAC "dlast_is_left") (LABEL_TAC "dlast_is_right")) THENL
     [SUBGOAL_THEN `F` CONTR_TAC THEN
      USE_THEN "selected_distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
      TRANS_TAC EQ_TRANS
       `{(q:num->A)(n - 1),q(n - 2)}` THEN
      ASM_REWRITE_TAC[];
      CONJ_TAC THENL
       [USE_THEN "d0_is_left" (fun th ->
          USE_THEN "d0_outer" (ACCEPT_TAC o REWRITE_RULE[th]));
        USE_THEN "dlast_is_right" (fun th ->
          USE_THEN "dlast_outer" (ACCEPT_TAC o REWRITE_RULE[th]))]];
    USE_THEN "dlast_choice"
     (DISJ_CASES_THEN2
      (LABEL_TAC "dlast_is_left") (LABEL_TAC "dlast_is_right")) THENL
     [CONJ_TAC THENL
       [USE_THEN "dlast_is_left" (fun th ->
          USE_THEN "dlast_outer" (ACCEPT_TAC o REWRITE_RULE[th]));
        USE_THEN "d0_is_right" (fun th ->
          USE_THEN "d0_outer" (ACCEPT_TAC o REWRITE_RULE[th]))];
      SUBGOAL_THEN `F` CONTR_TAC THEN
      USE_THEN "selected_distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
      TRANS_TAC EQ_TRANS
       `{(q:num->A)(n - 1),q 0}` THEN
      ASM_REWRITE_TAC[]]]);;
let FINITE_SIMPLE_GRAPH_ENDPOINT_FUNCTIONS = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> ?a b:(A->bool)->A.
              !e. e IN E ==> e = {a e,b e} /\ ~(a e = b e)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  SUBGOAL_THEN
   `!e:A->bool. e IN E
        ==> ?u v:A. e = {u,v} /\ ~(u = v)`
  (LABEL_TAC "choices") THENL
   [X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`]
     FINITE_SIMPLE_GRAPH_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@u v. u_vertex v_vertex distinct pair" THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `v:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "choices"
   (MP_TAC o REWRITE_RULE[RIGHT_IMP_EXISTS_THM; SKOLEM_THM]) THEN
  INTRO_TAC "@a b. chosen" THEN
  MAP_EVERY EXISTS_TAC
   [`a:(A->bool)->A`; `b:(A->bool)->A`] THEN
  USE_THEN "chosen" ACCEPT_TAC);;

let RADIALIZED_EDGE_OTHER_ENDPOINT_PAIR = prove
 (`!a b:(A->bool)->A. !v u e.
        e = {v,u} /\
        ~(v = u) /\
        e = {a e,b e} /\
        ~(a e = b e)
        ==> radialized_edge_other_endpoint a b v e = u`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "pair distinct endpoint_pair endpoint_distinct" THEN
  SUBGOAL_THEN
   `{(a:(A->bool)->A) e,b e} = {v,u}`
  (LABEL_TAC "pairs_equal") THENL
   [USE_THEN "endpoint_pair" (fun eth ->
      USE_THEN "pair"
       (MATCH_ACCEPT_TAC o TRANS (SYM eth)));
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(a:(A->bool)->A) e`; `(b:(A->bool)->A) e`; `v:A`; `u:A`]
   PAIR_SET_EQ_DISTINCT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "orientations") THEN
  REWRITE_TAC[radialized_edge_other_endpoint] THEN
  COND_CASES_TAC THENL
   [USE_THEN "orientations" MP_TAC THEN ASM_MESON_TAC[];
    USE_THEN "orientations" MP_TAC THEN ASM_MESON_TAC[]]);;

let CYCLIC_INCIDENT_EDGES_NEIGHBOR_ENUMERATION = prove
 (`!V E a b v d m.
        finite_simple_graph (V:A->bool) E /\
        (!e. e IN E ==> e = {a e,b e} /\ ~(a e = b e)) /\
        (!i. i < m ==> d i IN E /\ v IN d i) /\
        {e | e IN E /\ v IN e} = IMAGE d (cyclic_indices m) /\
        INJ d (cyclic_indices m) (:(A->bool))
        ==> graph_neighbors E v =
              cyclic_vertices
               (\i. radialized_edge_other_endpoint a b v (d i)) m /\
            INJ
             (\i. radialized_edge_other_endpoint a b v (d i))
             (cyclic_indices m) (:A)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph edge_data selected enumeration d_injective" THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `a:(A->bool)->A`; `b:(A->bool)->A`; `v:A`]
     GRAPH_NEIGHBORS_AS_INCIDENT_EDGE_IMAGE) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "enumeration" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[cyclic_vertices; GSYM IMAGE_o; o_DEF];
    REWRITE_TAC[INJ; IN_CYCLIC_INDICES; IN_UNIV] THEN
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
    INTRO_TAC "i_index j_index same_other" THEN
    USE_THEN "selected" (MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL
     [USE_THEN "i_index" ACCEPT_TAC;
      INTRO_TAC "di_edge v_di"] THEN
    USE_THEN "selected" (MP_TAC o SPEC `j:num`) THEN
    ANTS_TAC THENL
     [USE_THEN "j_index" ACCEPT_TAC;
      INTRO_TAC "dj_edge v_dj"] THEN
    USE_THEN "d_injective"
     (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
    DISCH_THEN MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `a:(A->bool)->A`; `b:(A->bool)->A`;
      `v:A`; `(d:num->A->bool) i`; `(d:num->A->bool) j`]
     INCIDENT_EDGES_EQUAL_OF_OTHER_ENDPOINT) THEN
    ASM_REWRITE_TAC[]]);;

let SIMPLE_GRAPH_CYCLE_3_DISTINCT_VERTICES_EDGE = prove
 (`!E:(A->bool)->bool. !r:num->A. !u w.
        simple_graph_cycle E r 3 /\
        u IN cyclic_vertices r 3 /\
        w IN cyclic_vertices r 3 /\
        ~(u = w)
        ==> {u,w} IN E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "cycle u_vertex w_vertex distinct" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective edges" THEN
  USE_THEN "u_vertex" MP_TAC THEN
  REWRITE_TAC[CYCLIC_VERTICES_3; IN_INSERT; IN_SING] THEN
  DISCH_THEN
   (DISJ_CASES_THEN2 SUBST_ALL_TAC
    (DISJ_CASES_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC)) THEN
  USE_THEN "w_vertex" MP_TAC THEN
  REWRITE_TAC[CYCLIC_VERTICES_3; IN_INSERT; IN_SING] THEN
  DISCH_THEN
   (DISJ_CASES_THEN2 SUBST_ALL_TAC
    (DISJ_CASES_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC)) THEN
  USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
  ASM_REWRITE_TAC
   [CYCLIC_EDGES_3; IN_INSERT; IN_SING; PAIR_SET_SYM] THEN
  ASM_MESON_TAC[]);;

let
 PLANE_TRIANGULATED_DISK_INTERNAL_FACE_INCIDENT_EDGE_ENDPOINTS_ADJACENT =
  prove
 (`!V E p c q n outer a b k v e e'.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        (!d. d IN E ==> d = {a d,b d} /\ ~(a d = b d)) /\
        k IN plane_graph_incident_faces V E p c v /\
        ~(k = outer) /\
        ~(e = e') /\
        e IN E /\ e' IN E /\
        v IN e /\ v IN e' /\
        c e SUBSET frontier k /\
        c e' SUBSET frontier k
        ==> {radialized_edge_other_endpoint a b v e,
             radialized_edge_other_endpoint a b v e'} IN E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk edge_data face not_outer edges_distinct edge edge' \
    v_e v_e' e_frontier e'_frontier" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "graph embedding nlarge q_injective boundary_edges \
             boundary_subset outer_component boundary" THEN
  USE_THEN "face" MP_TAC THEN
  REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
  INTRO_TAC "component v_face" THEN
  USE_THEN "disk" MP_TAC THEN
  REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC
   "_ _ _ _ _ _ triangular" THEN
  USE_THEN "triangular" (MP_TAC o SPEC `k:real^2->bool`) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC "@r. face_vertices triangle"] THEN
  USE_THEN "edge_data" (MP_TAC o SPEC `e:A->bool`) THEN
  ANTS_TAC THENL
   [USE_THEN "edge" ACCEPT_TAC;
    INTRO_TAC "endpoint_pair endpoint_distinct"] THEN
  USE_THEN "edge_data" (MP_TAC o SPEC `e':A->bool`) THEN
  ANTS_TAC THENL
   [USE_THEN "edge'" ACCEPT_TAC;
    INTRO_TAC "endpoint_pair' endpoint_distinct'"] THEN
  MP_TAC(ISPECL
   [`a:(A->bool)->A`; `b:(A->bool)->A`; `v:A`; `e:A->bool`]
   RADIALIZED_EDGE_INCIDENT_PAIR) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "endpoint_pair" MATCH_ACCEPT_TAC;
      USE_THEN "endpoint_distinct" MATCH_ACCEPT_TAC;
      USE_THEN "v_e" MATCH_ACCEPT_TAC];
    INTRO_TAC "e_pair u_distinct"] THEN
  MP_TAC(ISPECL
   [`a:(A->bool)->A`; `b:(A->bool)->A`; `v:A`; `e':A->bool`]
   RADIALIZED_EDGE_INCIDENT_PAIR) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "endpoint_pair'" MATCH_ACCEPT_TAC;
      USE_THEN "endpoint_distinct'" MATCH_ACCEPT_TAC;
      USE_THEN "v_e'" MATCH_ACCEPT_TAC];
    INTRO_TAC "e'_pair w_distinct"] THEN
  SUBGOAL_THEN
   `~(radialized_edge_other_endpoint
        (a:(A->bool)->A) b v e =
      radialized_edge_other_endpoint a b v e')`
  (LABEL_TAC "other_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same_other") THEN
    USE_THEN "edges_distinct" (fun th -> MATCH_MP_TAC(NOT_ELIM th)) THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `a:(A->bool)->A`; `b:(A->bool)->A`;
      `v:A`; `e:A->bool`; `e':A->bool`]
     INCIDENT_EDGES_EQUAL_OF_OTHER_ENDPOINT) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "edge_data" MATCH_ACCEPT_TAC;
      USE_THEN "edge" MATCH_ACCEPT_TAC;
      USE_THEN "v_e" MATCH_ACCEPT_TAC;
      USE_THEN "edge'" MATCH_ACCEPT_TAC;
      USE_THEN "v_e'" MATCH_ACCEPT_TAC;
      USE_THEN "same_other" MATCH_ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(e:A->bool) SUBSET plane_graph_face_vertices V E p c k`
  (LABEL_TAC "e_face") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`;
      `k:real^2->bool`]
     PLANE_GRAPH_EMBEDDING_FRONTIER_EDGE_SUBSET_FACE_VERTICES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(e':A->bool) SUBSET plane_graph_face_vertices V E p c k`
  (LABEL_TAC "e'_face") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e':A->bool`;
      `k:real^2->bool`]
     PLANE_GRAPH_EMBEDDING_FRONTIER_EDGE_SUBSET_FACE_VERTICES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `r:num->A`;
    `radialized_edge_other_endpoint
      (a:(A->bool)->A) b v e`;
    `radialized_edge_other_endpoint
      (a:(A->bool)->A) b v e'`]
   SIMPLE_GRAPH_CYCLE_3_DISTINCT_VERTICES_EDGE) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "triangle" ACCEPT_TAC;
    USE_THEN "face_vertices" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "e_face" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    MATCH_MP_TAC(SET_RULE
     `(s:A->bool) = {v,u} ==> u IN s`) THEN
    USE_THEN "e_pair" MATCH_ACCEPT_TAC;
    USE_THEN "face_vertices" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "e'_face" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    MATCH_MP_TAC(SET_RULE
     `(s:A->bool) = {v,u} ==> u IN s`) THEN
    USE_THEN "e'_pair" MATCH_ACCEPT_TAC;
    USE_THEN "other_distinct" ACCEPT_TAC]);;

let CYCLIC_CHAIN_ENDPOINT_PAIR_TO_NEIGHBOR_PATH = prove
 (`!E:(A->bool)->bool. !v z m a b.
        2 <= m /\
        graph_neighbors E v = cyclic_vertices z m /\
        INJ z (cyclic_indices m) (:A) /\
        {z 0,z(m - 1)} = {a,b} /\
        ~(a = b) /\
        (!i. i + 1 < m ==> {z i,z(i + 1)} IN E)
        ==> ?k w:num->A.
              m = k + 2 /\
              graph_neighbors E v = cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = a /\
              w (k + 1) = b /\
              (!i. i + 1 < k + 2 ==> {w i,w(i + 1)} IN E)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "large neighbors injective endpoints ab_distinct chain" THEN
  SUBGOAL_THEN `~((z:num->A) 0 = z(m - 1))`
  (LABEL_TAC "z_endpoints_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same") THEN
    USE_THEN "injective"
     (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
    DISCH_THEN(MP_TAC o SPECL [`0`; `m - 1`]) THEN
    ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(z:num->A) 0`; `(z:num->A) (m - 1)`; `a:A`; `b:A`]
   PAIR_SET_EQ_DISTINCT) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "z_endpoints_distinct" ACCEPT_TAC;
      USE_THEN "endpoints" ACCEPT_TAC];
    DISCH_THEN
     (DISJ_CASES_THEN2
      (CONJUNCTS_THEN2 (LABEL_TAC "first") (LABEL_TAC "last"))
      (CONJUNCTS_THEN2 (LABEL_TAC "first") (LABEL_TAC "last")))] THENL
   [MAP_EVERY EXISTS_TAC [`m - 2`; `z:num->A`] THEN
    SUBGOAL_THEN `(m:num) - 2 + 2 = m`
    (LABEL_TAC "length") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(m:num) - 2 + 1 = m - 1`
    (LABEL_TAC "last_index") THENL
     [ASM_ARITH_TAC;
      ASM_REWRITE_TAC[]];
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `v:A`; `a:A`; `b:A`;
      `z:num->A`; `m:num`]
     NEIGHBOR_PATH_FROM_REVERSED_CYCLIC_CHAIN) THEN
    ASM_REWRITE_TAC[]]);;

let PLANE_TRIANGULATED_DISK_INCIDENT_FACE_CYCLE_OUTER_EDGE_PAIR =
  prove
 (`!V E p c q n outer h m d.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        c {q(n - 1),q(n - 2)} SUBSET frontier outer /\
        c {q(n - 1),q 0} SUBSET frontier outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        3 <= m /\
        finite_relation_path
          (plane_graph_face_adjacent_at E c (q(n - 1)))
          (plane_graph_incident_faces V E p c (q(n - 1))) h m /\
        h 0 = outer /\
        (!i. i < m
             ==> d i IN E /\
                 q(n - 1) IN d i /\
                 c(d i) SUBSET frontier(h i) /\
                 c(d i) SUBSET frontier(h((i + 1) MOD m)))
        ==> {d 0,d(m - 1)} =
            {{q(n - 1),q(n - 2)},{q(n - 1),q 0}}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk left_boundary right_boundary chordless large path \
    h_outer edge_cycle" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN
   `INJ (d:num->A->bool) (cyclic_indices m) (:(A->bool))`
  (LABEL_TAC "d_injective") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `(q:num->A)(n - 1)`;
      `h:num->real^2->bool`; `m:num`; `d:num->A->bool`]
     PLANE_GRAPH_FACE_ADJACENT_CYCLE_EDGES_INJ) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "edge_cycle" (MP_TAC o SPEC `0`) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    INTRO_TAC "d0_edge v_d0 d0_outer d0_next"] THEN
  USE_THEN "edge_cycle" (MP_TAC o SPEC `m - 1`) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    INTRO_TAC
     "dlast_edge v_dlast dlast_previous dlast_next"] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) (d 0) SUBSET frontier outer`
  (LABEL_TAC "d0_outer_face") THENL
   [USE_THEN "h_outer" (fun th ->
      USE_THEN "d0_outer"
       (MATCH_ACCEPT_TAC o REWRITE_RULE[th]));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) (d(m - 1))
    SUBSET frontier outer`
  (LABEL_TAC "dlast_outer_face") THENL
   [SUBGOAL_THEN `((m:num) - 1 + 1) MOD m = 0`
    (LABEL_TAC "wrap") THENL
     [SUBGOAL_THEN `(m:num) - 1 + 1 = m`
      (fun th -> REWRITE_TAC[th; MOD_REFL]) THEN
      ASM_ARITH_TAC;
      USE_THEN "wrap" (fun th ->
       USE_THEN "h_outer" (fun hth ->
        USE_THEN "dlast_next"
         (MATCH_ACCEPT_TAC o REWRITE_RULE[th; hth])))];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((d:num->A->bool) 0 = d(m - 1))`
  (LABEL_TAC "selected_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same_edge") THEN
    USE_THEN "d_injective"
     (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
    DISCH_THEN(MP_TAC o SPECL [`0`; `m - 1`]) THEN
    ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(outer:real^2->bool) IN
    plane_graph_incident_faces
     (V:A->bool) (E:(A->bool)->bool) (p:A->real^2)
     (c:(A->bool)->real^2->bool) ((q:num->A)(n - 1))`
  (LABEL_TAC "outer_face") THENL
   [REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
    CONJ_TAC THENL
     [USE_THEN "outer_component" ACCEPT_TAC;
      USE_THEN "boundary" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{(q:num->A)(n - 1),q(n - 2)} IN cyclic_edges q n`
  (LABEL_TAC "left_cycle_edge") THENL
   [REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `n - 2` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      SUBGOAL_THEN `(n:num) - 2 + 1 = n - 1`
      SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `(n - 1) MOD n = n - 1`
        SUBST1_TAC THENL
         [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
          MATCH_ACCEPT_TAC PAIR_SET_SYM]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{(q:num->A)(n - 1),q 0} IN cyclic_edges q n`
