    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((q:num->A)(n - 1) = q(n - 2)) /\
    ~(q(n - 1) = q 0) /\
    ~(q(n - 2) = q 0)`
  (LABEL_TAC "boundary_distinct") THENL
   [USE_THEN "q_injective"
     (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
    REWRITE_TAC[IN_CYCLIC_INDICES; IN_UNIV] THEN
    DISCH_THEN(LABEL_TAC "injective") THEN
    REPEAT CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "injective" (MP_TAC o SPECL
       [`n - 1`; `n - 2`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [ASM_ARITH_TAC;
          ASM_ARITH_TAC;
          USE_THEN "same" ACCEPT_TAC];
        ASM_ARITH_TAC];
      DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "injective" (MP_TAC o SPECL
       [`n - 1`; `0`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [ASM_ARITH_TAC;
          ASM_ARITH_TAC;
          USE_THEN "same" ACCEPT_TAC];
        ASM_ARITH_TAC];
      DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "injective" (MP_TAC o SPECL
       [`n - 2`; `0`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [ASM_ARITH_TAC;
          ASM_ARITH_TAC;
          USE_THEN "same" ACCEPT_TAC];
        ASM_ARITH_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~({(q:num->A)(n - 1),q(n - 2)} =
