  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `outer:real^2->bool`;
    `{(q:num->A)(n - 1),q(n - 2)}`;
    `{(q:num->A)(n - 1),q 0}`; `(d:num->A->bool) 0`]
   PLANE_TRIANGULATED_DISK_INCIDENT_FACE_FRONTIER_EDGE_CHOICE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "disk" ACCEPT_TAC;
      USE_THEN "chordless" ACCEPT_TAC;
      USE_THEN "outer_face" ACCEPT_TAC;
      USE_THEN "boundary_edges_distinct" ACCEPT_TAC;
      USE_THEN "left_edge" ACCEPT_TAC;
      USE_THEN "right_edge" ACCEPT_TAC;
      USE_THEN "d0_edge" ACCEPT_TAC;
      REWRITE_TAC[IN_INSERT];
      REWRITE_TAC[IN_INSERT];
      USE_THEN "v_d0" ACCEPT_TAC;
      USE_THEN "left_outer" ACCEPT_TAC;
      USE_THEN "right_outer" ACCEPT_TAC;
      USE_THEN "d0_outer_face" ACCEPT_TAC];
    DISCH_THEN(LABEL_TAC "d0_choice")] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `outer:real^2->bool`;
    `{(q:num->A)(n - 1),q(n - 2)}`;
    `{(q:num->A)(n - 1),q 0}`; `(d:num->A->bool) (m - 1)`]
   PLANE_TRIANGULATED_DISK_INCIDENT_FACE_FRONTIER_EDGE_CHOICE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "disk" ACCEPT_TAC;
      USE_THEN "chordless" ACCEPT_TAC;
      USE_THEN "outer_face" ACCEPT_TAC;
      USE_THEN "boundary_edges_distinct" ACCEPT_TAC;
      USE_THEN "left_edge" ACCEPT_TAC;
      USE_THEN "right_edge" ACCEPT_TAC;
      USE_THEN "dlast_edge" ACCEPT_TAC;
      REWRITE_TAC[IN_INSERT];
      REWRITE_TAC[IN_INSERT];
      USE_THEN "v_dlast" ACCEPT_TAC;
      USE_THEN "left_outer" ACCEPT_TAC;
      USE_THEN "right_outer" ACCEPT_TAC;
      USE_THEN "dlast_outer_face" ACCEPT_TAC];
    DISCH_THEN(LABEL_TAC "dlast_choice")] THEN
  USE_THEN "d0_choice"
   (DISJ_CASES_THEN2
    (LABEL_TAC "d0_left") (LABEL_TAC "d0_right")) THENL
   [USE_THEN "dlast_choice"
     (DISJ_CASES_THEN2
      (LABEL_TAC "dlast_left") (LABEL_TAC "dlast_right")) THENL
     [SUBGOAL_THEN `F` CONTR_TAC THEN
      USE_THEN "selected_distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
      TRANS_TAC EQ_TRANS
       `{(q:num->A)(n - 1),q(n - 2)}` THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[PAIR_SET_SYM]];
    USE_THEN "dlast_choice"
     (DISJ_CASES_THEN2
      (LABEL_TAC "dlast_left") (LABEL_TAC "dlast_right")) THENL
     [ASM_REWRITE_TAC[PAIR_SET_SYM];
      SUBGOAL_THEN `F` CONTR_TAC THEN
      USE_THEN "selected_distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
      TRANS_TAC EQ_TRANS
       `{(q:num->A)(n - 1),q 0}` THEN
      ASM_REWRITE_TAC[]]]);;

let PLANE_TRIANGULATED_DISK_INCIDENT_FACE_CYCLE_NEIGHBOR_PATH =
  prove
 (`!V E p c q n outer h m d.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        c {q(n - 1),q(n - 2)} SUBSET frontier outer /\
        c {q(n - 1),q 0} SUBSET frontier outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        3 <= m /\
        finite_relation_path
          (plane_graph_face_adjacent_at E c (q(n - 1)))
          (plane_graph_incident_faces V E p c (q(n - 1))) h m /\
        IMAGE h (cyclic_indices m) =
          plane_graph_incident_faces V E p c (q(n - 1)) /\
        h 0 = outer /\
        (!i. i < m
             ==> d i IN E /\
                 q(n - 1) IN d i /\
                 c(d i) SUBSET frontier(h i) /\
                 c(d i) SUBSET frontier(h((i + 1) MOD m)))
        ==> ?k w:num->A.
              m = k + 2 /\
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = q(n - 2) /\
              w(k + 1) = q 0 /\
              (!i. i + 1 < k + 2
                   ==> {w i,w(i + 1)} IN E)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk left_boundary right_boundary chordless large path coverage \
    h_outer edge_cycle" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`]
   FINITE_SIMPLE_GRAPH_ENDPOINT_FUNCTIONS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@a b. edge_data" THEN
  SUBGOAL_THEN
   `INJ (d:num->A->bool) (cyclic_indices m) (:(A->bool))`
  (LABEL_TAC "d_injective") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `(q:num->A)(n - 1)`;
      `h:num->real^2->bool`; `m:num`; `d:num->A->bool`]
     PLANE_GRAPH_FACE_ADJACENT_CYCLE_EDGES_INJ) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{e:A->bool | e IN E /\ q(n - 1) IN e} =
    IMAGE d (cyclic_indices m)`
  (LABEL_TAC "edge_enumeration") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `h:num->real^2->bool`;
      `m:num`; `d:num->A->bool`]
     PLANE_TRIANGULATED_DISK_INCIDENT_FACE_CYCLE_EDGES_ENUMERATE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC
   `z:num->A =
      \i. radialized_edge_other_endpoint
            (a:(A->bool)->A) (b:(A->bool)->A)
            ((q:num->A)(n - 1)) ((d:num->A->bool) i)` THEN
  SUBGOAL_THEN
   `graph_neighbors E ((q:num->A)(n - 1)) =
      cyclic_vertices z m /\
    INJ (z:num->A) (cyclic_indices m) (:A)`
  (CONJUNCTS_THEN2
   (LABEL_TAC "neighbors") (LABEL_TAC "z_injective")) THENL
   [EXPAND_TAC "z" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `a:(A->bool)->A`; `b:(A->bool)->A`;
      `(q:num->A)(n - 1)`; `d:num->A->bool`; `m:num`]
     CYCLIC_INCIDENT_EDGES_NEIGHBOR_ENUMERATION) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      USE_THEN "edge_data" ACCEPT_TAC;
      X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "i_index") THEN
      USE_THEN "edge_cycle" (MP_TAC o SPEC `i:num`) THEN
      ANTS_TAC THENL
       [USE_THEN "i_index" ACCEPT_TAC;
        INTRO_TAC "di_edge v_di di_left di_right"] THEN
      ASM_REWRITE_TAC[];
      USE_THEN "edge_enumeration" ACCEPT_TAC;
      USE_THEN "d_injective" ACCEPT_TAC];
    ALL_TAC] THEN
  USE_THEN "path" MP_TAC THEN
  REWRITE_TAC[finite_relation_path] THEN
  INTRO_TAC "face_vertices h_injective face_chain" THEN
  SUBGOAL_THEN
   `!i. i + 1 < m ==> {(z:num->A) i,z(i + 1)} IN E`
  (LABEL_TAC "neighbor_chain") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "next_index") THEN
    SUBGOAL_THEN `(i:num) < m` (LABEL_TAC "i_index") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "edge_cycle" (MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL
     [USE_THEN "i_index" ACCEPT_TAC;
      INTRO_TAC "di_edge v_di di_left di_right"] THEN
    USE_THEN "edge_cycle" (MP_TAC o SPEC `i + 1`) THEN
    ANTS_TAC THENL
     [USE_THEN "next_index" ACCEPT_TAC;
      INTRO_TAC "dnext_edge v_dnext dnext_left dnext_right"] THEN
    SUBGOAL_THEN `(i + 1) MOD m = i + 1`
    (LABEL_TAC "no_wrap") THENL
     [MATCH_MP_TAC MOD_LT THEN
      USE_THEN "next_index" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(c:(A->bool)->real^2->bool) (d i)
      SUBSET frontier(h(i + 1))`
    (LABEL_TAC "di_face") THENL
     [USE_THEN "no_wrap" (fun th ->
       USE_THEN "di_right"
        (MATCH_ACCEPT_TAC o REWRITE_RULE[th]));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(h:num->real^2->bool) (i + 1) IN
      plane_graph_incident_faces
       (V:A->bool) (E:(A->bool)->bool) (p:A->real^2)
       (c:(A->bool)->real^2->bool) ((q:num->A)(n - 1))`
    (LABEL_TAC "next_face") THENL
     [USE_THEN "face_vertices" MATCH_MP_TAC THEN
      USE_THEN "next_index" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((h:num->real^2->bool) (i + 1) = outer)`
    (LABEL_TAC "next_not_outer") THENL
     [DISCH_THEN(LABEL_TAC "next_outer") THEN
      USE_THEN "h_injective"
       (MP_TAC o SPECL [`i + 1`; `0`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [USE_THEN "next_index" ACCEPT_TAC;
          ASM_ARITH_TAC;
          TRANS_TAC EQ_TRANS `outer:real^2->bool` THEN
          CONJ_TAC THENL
           [USE_THEN "next_outer" ACCEPT_TAC;
            USE_THEN "h_outer" (ACCEPT_TAC o SYM)]];
        ASM_ARITH_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `~((d:num->A->bool) i = d(i + 1))`
    (LABEL_TAC "edges_distinct") THENL
     [DISCH_THEN(LABEL_TAC "same_edge") THEN
      USE_THEN "d_injective"
       (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
      DISCH_THEN(MP_TAC o SPECL [`i:num`; `i + 1`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
        ASM_ARITH_TAC];
      ALL_TAC] THEN
    EXPAND_TAC "z" THEN BETA_TAC THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `a:(A->bool)->A`;
      `b:(A->bool)->A`; `(h:num->real^2->bool) (i + 1)`;
      `(q:num->A)(n - 1)`; `(d:num->A->bool) i`;
      `(d:num->A->bool) (i + 1)`]
     PLANE_TRIANGULATED_DISK_INTERNAL_FACE_INCIDENT_EDGE_ENDPOINTS_ADJACENT)
    THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "disk" ACCEPT_TAC;
      USE_THEN "edge_data" ACCEPT_TAC;
      USE_THEN "next_face" ACCEPT_TAC;
      USE_THEN "next_not_outer" ACCEPT_TAC;
      USE_THEN "edges_distinct" ACCEPT_TAC;
      USE_THEN "di_edge" ACCEPT_TAC;
      USE_THEN "dnext_edge" ACCEPT_TAC;
      USE_THEN "v_di" ACCEPT_TAC;
      USE_THEN "v_dnext" ACCEPT_TAC;
      USE_THEN "di_face" ACCEPT_TAC;
      USE_THEN "dnext_left" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((d:num->A->bool) 0 = d(m - 1))`
  (LABEL_TAC "selected_endpoints_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same_edge") THEN
    USE_THEN "d_injective"
     (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
    DISCH_THEN(MP_TAC o SPECL [`0`; `m - 1`]) THEN
    ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{(d:num->A->bool) 0,d(m - 1)} =
    {{(q:num->A)(n - 1),q(n - 2)},{q(n - 1),q 0}}`
  (LABEL_TAC "outer_edge_pair") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `h:num->real^2->bool`;
      `m:num`; `d:num->A->bool`]
     PLANE_TRIANGULATED_DISK_INCIDENT_FACE_CYCLE_OUTER_EDGE_PAIR) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((q:num->A)(n - 1) = q(n - 2)) /\
    ~(q(n - 1) = q 0) /\
    ~(q(n - 2) = q 0)`
  (CONJUNCTS_THEN2 (LABEL_TAC "last_penult")
   (CONJUNCTS_THEN2
    (LABEL_TAC "last_first") (LABEL_TAC "penult_first"))) THENL
   [USE_THEN "q_injective"
     (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
    REWRITE_TAC[IN_CYCLIC_INDICES; IN_UNIV] THEN
    DISCH_THEN(LABEL_TAC "injective") THEN
    REPEAT CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "injective" (MP_TAC o SPECL
       [`n - 1`; `n - 2`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [ASM_ARITH_TAC; ASM_ARITH_TAC;
          USE_THEN "same" ACCEPT_TAC];
        ASM_ARITH_TAC];
      DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "injective" (MP_TAC o SPECL
       [`n - 1`; `0`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [ASM_ARITH_TAC; ASM_ARITH_TAC;
          USE_THEN "same" ACCEPT_TAC];
        ASM_ARITH_TAC];
      DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "injective" (MP_TAC o SPECL
       [`n - 2`; `0`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [ASM_ARITH_TAC; ASM_ARITH_TAC;
          USE_THEN "same" ACCEPT_TAC];
        ASM_ARITH_TAC]];
    ALL_TAC] THEN
  USE_THEN "edge_cycle" (MP_TAC o SPEC `0`) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    INTRO_TAC "d0_edge v_d0 d0_left d0_right"] THEN
  USE_THEN "edge_cycle" (MP_TAC o SPEC `m - 1`) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    INTRO_TAC "dlast_edge v_dlast dlast_left dlast_right"] THEN
  USE_THEN "edge_data" (MP_TAC o SPEC `(d:num->A->bool) 0`) THEN
  ANTS_TAC THENL
   [USE_THEN "d0_edge" ACCEPT_TAC;
    INTRO_TAC "d0_endpoints d0_endpoint_distinct"] THEN
  USE_THEN "edge_data"
   (MP_TAC o SPEC `(d:num->A->bool) (m - 1)`) THEN
  ANTS_TAC THENL
   [USE_THEN "dlast_edge" ACCEPT_TAC;
    INTRO_TAC "dlast_endpoints dlast_endpoint_distinct"] THEN
  SUBGOAL_THEN
   `{(z:num->A) 0,z(m - 1)} = {q(n - 2),q 0}`
  (LABEL_TAC "neighbor_endpoint_pair") THENL
   [MP_TAC(ISPECL
     [`(d:num->A->bool) 0`; `(d:num->A->bool) (m - 1)`;
      `{(q:num->A)(n - 1),q(n - 2)}`;
      `{(q:num->A)(n - 1),q 0}`]
     PAIR_SET_EQ_DISTINCT) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "selected_endpoints_distinct" ACCEPT_TAC;
        USE_THEN "outer_edge_pair" ACCEPT_TAC];
      DISCH_THEN
       (DISJ_CASES_THEN2
        (CONJUNCTS_THEN2
         (LABEL_TAC "d0_fixed") (LABEL_TAC "dlast_fixed"))
        (CONJUNCTS_THEN2
         (LABEL_TAC "d0_fixed") (LABEL_TAC "dlast_fixed")))] THENL
     [SUBGOAL_THEN
       `radialized_edge_other_endpoint
          (a:(A->bool)->A) b (q(n - 1)) (d 0) = q(n - 2)`
      (LABEL_TAC "z0") THENL
       [MATCH_MP_TAC RADIALIZED_EDGE_OTHER_ENDPOINT_PAIR THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "d0_fixed" ACCEPT_TAC;
          USE_THEN "last_penult" ACCEPT_TAC;
          USE_THEN "d0_endpoints" ACCEPT_TAC;
          USE_THEN "d0_endpoint_distinct" ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `radialized_edge_other_endpoint
          (a:(A->bool)->A) b (q(n - 1)) (d(m - 1)) = q 0`
      (LABEL_TAC "zlast") THENL
       [MATCH_MP_TAC RADIALIZED_EDGE_OTHER_ENDPOINT_PAIR THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "dlast_fixed" ACCEPT_TAC;
          USE_THEN "last_first" ACCEPT_TAC;
          USE_THEN "dlast_endpoints" ACCEPT_TAC;
          USE_THEN "dlast_endpoint_distinct" ACCEPT_TAC];
        EXPAND_TAC "z" THEN BETA_TAC THEN
        USE_THEN "z0" (fun zth ->
         USE_THEN "zlast" (fun lth ->
          REWRITE_TAC[zth; lth]))];
      SUBGOAL_THEN
       `radialized_edge_other_endpoint
          (a:(A->bool)->A) b (q(n - 1)) (d 0) = q 0`
      (LABEL_TAC "z0") THENL
       [MATCH_MP_TAC RADIALIZED_EDGE_OTHER_ENDPOINT_PAIR THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "d0_fixed" ACCEPT_TAC;
          USE_THEN "last_first" ACCEPT_TAC;
          USE_THEN "d0_endpoints" ACCEPT_TAC;
          USE_THEN "d0_endpoint_distinct" ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `radialized_edge_other_endpoint
          (a:(A->bool)->A) b (q(n - 1)) (d(m - 1)) = q(n - 2)`
      (LABEL_TAC "zlast") THENL
       [MATCH_MP_TAC RADIALIZED_EDGE_OTHER_ENDPOINT_PAIR THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "dlast_fixed" ACCEPT_TAC;
          USE_THEN "last_penult" ACCEPT_TAC;
          USE_THEN "dlast_endpoints" ACCEPT_TAC;
          USE_THEN "dlast_endpoint_distinct" ACCEPT_TAC];
        EXPAND_TAC "z" THEN BETA_TAC THEN
        USE_THEN "z0" (fun zth ->
         USE_THEN "zlast" (fun lth ->
          REWRITE_TAC[zth; lth; PAIR_SET_SYM]))]];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `(q:num->A)(n - 1)`;
    `z:num->A`; `m:num`; `(q:num->A)(n - 2)`; `(q:num->A) 0`]
   CYCLIC_CHAIN_ENDPOINT_PAIR_TO_NEIGHBOR_PATH) THEN
  REPEAT CONJ_TAC THENL
   [ASM_ARITH_TAC;
    USE_THEN "neighbors" ACCEPT_TAC;
    USE_THEN "z_injective" ACCEPT_TAC;
