    USE_THEN "neighbor_chain" ACCEPT_TAC]);;

let PLANE_TRIANGULATED_DISK_DELETE_LAST_LARGE_INCIDENT_FACE_CYCLE =
  prove
 (`!V E p c q n outer.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        c {q(n - 1),q(n - 2)} SUBSET frontier outer /\
        c {q(n - 1),q 0} SUBSET frontier outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        3 <= CARD(plane_graph_incident_faces
                    V E p c (q(n - 1)))
        ==> ?k w newouter.
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = q(n - 2) /\
              w(k + 1) = q 0 /\
              plane_triangulated_disk
                (V DELETE q(n - 1))
                (induced_subgraph_edges E (V DELETE q(n - 1)))
                p c (cyclic_delete_last q w n)
                (n - 1 + k) newouter`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "disk left_boundary right_boundary chordless faces_large" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN
   `(q:num->A)(n - 1) IN cyclic_vertices q n`
  (LABEL_TAC "last_boundary") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `(q:num->A)(n - 1)`]
   PLANE_TRIANGULATED_DISK_DELETE_VERTEX_OUTER_COMPONENT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@patchouter. patch_component outer_subset last_patch" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `patchouter:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INCIDENT_FACE_EDGE_CYCLE_OUTER) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@m h d. mlarge path coverage h_outer closing edge_cycle" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `h:num->real^2->bool`;
    `m:num`; `d:num->A->bool`]
   PLANE_TRIANGULATED_DISK_INCIDENT_FACE_CYCLE_NEIGHBOR_PATH) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@k w. length neighbors w_injective first last chain" THEN
  SUBGOAL_THEN `3 <= (n:num) - 1 + k`
  (LABEL_TAC "newlarge") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `k:num`; `w:num->A`]
   PLANE_TRIANGULATED_DISK_DELETE_LAST_WITH_NEIGHBOR_PATH) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "disk" ACCEPT_TAC;
      USE_THEN "chordless" ACCEPT_TAC;
      USE_THEN "newlarge" ACCEPT_TAC;
      USE_THEN "neighbors" ACCEPT_TAC;
      USE_THEN "w_injective" ACCEPT_TAC;
      USE_THEN "first" ACCEPT_TAC;
      USE_THEN "last" ACCEPT_TAC;
      USE_THEN "chain" ACCEPT_TAC];
    INTRO_TAC "@newouter. newdisk"] THEN
  MAP_EVERY EXISTS_TAC
   [`k:num`; `w:num->A`; `newouter:real^2->bool`] THEN
  ASM_REWRITE_TAC[]);;

let CYCLIC_INDICES_2 = prove
 (`cyclic_indices 2 = {0,1}`,
  REWRITE_TAC[cyclic_indices; EXTENSION; IN_ELIM_THM;
              IN_INSERT; IN_SING] THEN
  ARITH_TAC);;

let CYCLIC_VERTICES_2 = prove
 (`!q:num->A. cyclic_vertices q 2 = {q 0,q 1}`,
  GEN_TAC THEN
  REWRITE_TAC[cyclic_vertices; CYCLIC_INDICES_2; IMAGE_CLAUSES]);;

let PLANE_TRIANGULATED_DISK_TWO_INCIDENT_FACES_DATA =
  prove
 (`!V E p c q n outer.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        c {q(n - 1),q(n - 2)} SUBSET frontier outer /\
        c {q(n - 1),q 0} SUBSET frontier outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        CARD(plane_graph_incident_faces
               V E p c (q(n - 1))) = 2
        ==> {e:A->bool | e IN E /\ q(n - 1) IN e} =
              {{q(n - 1),q(n - 2)},{q(n - 1),q 0}} /\
            {q(n - 2),q 0} IN E /\
            ?l. l IN plane_graph_incident_faces
                       V E p c (q(n - 1)) /\
                ~(l = outer) /\
                c {q(n - 1),q(n - 2)} SUBSET frontier l /\
                c {q(n - 1),q 0} SUBSET frontier l`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "disk left_boundary right_boundary chordless face_card" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN
   `(q:num->A)(n - 1) IN cyclic_vertices q n`
  (LABEL_TAC "last_boundary") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(outer:real^2->bool) IN
    plane_graph_incident_faces
     (V:A->bool) E p c ((q:num->A)(n - 1))`
  (LABEL_TAC "outer_face") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `(q:num->A)(n - 1)`]
     PLANE_TRIANGULATED_DISK_OUTER_INCIDENT_FACE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_OUTER_FACE_TWO_EDGE_ADJACENCIES_FRONTIER) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC
     "@l1 l2. l1_face l2_face outer_l1 outer_l2 \
      left_outer right_outer left_l1 right_l2"] THEN
  SUBGOAL_THEN `~((outer:real^2->bool) = l1)`
  (LABEL_TAC "outer_l1_distinct") THENL
   [USE_THEN "outer_l1" MP_TAC THEN
    REWRITE_TAC[plane_graph_face_adjacent_at] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1)))`
  (LABEL_TAC "faces_finite") THENL
   [MATCH_MP_TAC FINITE_PLANE_GRAPH_INCIDENT_FACES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_incident_faces
      (V:A->bool) E p c (q(n - 1)) = {outer,l1}`
  (LABEL_TAC "faces_pair") THENL
   [MATCH_MP_TAC EQ_SYM THEN
    MATCH_MP_TAC CARD_SUBSET_EQ THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "faces_finite" ACCEPT_TAC;
      REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
      ASM_REWRITE_TAC[];
      USE_THEN "face_card" (fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC
       [CARD_CLAUSES; FINITE_INSERT; FINITE_EMPTY;
        IN_INSERT; NOT_IN_EMPTY] THEN
      ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(l2:real^2->bool) = l1`
  (LABEL_TAC "l2_l1") THENL
   [SUBGOAL_THEN `~((l2:real^2->bool) = outer)`
    (LABEL_TAC "l2_not_outer") THENL
     [USE_THEN "outer_l2" MP_TAC THEN
      REWRITE_TAC[plane_graph_face_adjacent_at] THEN MESON_TAC[];
      USE_THEN "l2_face" MP_TAC THEN
      USE_THEN "faces_pair" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) {q(n - 1),q 0}
    SUBSET frontier l1`
  (LABEL_TAC "right_l1") THENL
   [USE_THEN "l2_l1" (fun th ->
      USE_THEN "right_l2"
       (MATCH_ACCEPT_TAC o REWRITE_RULE[th]));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{(q:num->A)(n - 1),q(n - 2)} IN cyclic_edges q n`
  (LABEL_TAC "left_cycle_edge") THENL
   [REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `n - 2` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      SUBGOAL_THEN `(n:num) - 2 + 1 = n - 1`
      SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `(n - 1) MOD n = n - 1`
        SUBST1_TAC THENL
         [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
          MATCH_ACCEPT_TAC PAIR_SET_SYM]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{(q:num->A)(n - 1),q 0} IN cyclic_edges q n`
  (LABEL_TAC "right_cycle_edge") THENL
   [REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `n - 1` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      SUBGOAL_THEN `(n:num) - 1 + 1 = n`
      SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[MOD_REFL]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{(q:num->A)(n - 1),q(n - 2)} IN E /\
    {(q:num->A)(n - 1),q 0} IN E`
  (CONJUNCTS_THEN2
   (LABEL_TAC "left_edge") (LABEL_TAC "right_edge")) THENL
   [CONJ_TAC THEN USE_THEN "boundary_edges"
     (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((q:num->A)(n - 1) = q(n - 2)) /\
    ~(q(n - 1) = q 0) /\
    ~(q(n - 2) = q 0)`
  (LABEL_TAC "boundary_distinct") THENL
   [USE_THEN "q_injective"
     (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
    REWRITE_TAC[IN_CYCLIC_INDICES; IN_UNIV] THEN
    DISCH_THEN(LABEL_TAC "injective") THEN
    REPEAT CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "injective" (MP_TAC o SPECL
       [`n - 1`; `n - 2`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [ASM_ARITH_TAC; ASM_ARITH_TAC;
          USE_THEN "same" ACCEPT_TAC];
        ASM_ARITH_TAC];
      DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "injective" (MP_TAC o SPECL
       [`n - 1`; `0`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [ASM_ARITH_TAC; ASM_ARITH_TAC;
          USE_THEN "same" ACCEPT_TAC];
        ASM_ARITH_TAC];
      DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "injective" (MP_TAC o SPECL
       [`n - 2`; `0`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [ASM_ARITH_TAC; ASM_ARITH_TAC;
          USE_THEN "same" ACCEPT_TAC];
        ASM_ARITH_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~({(q:num->A)(n - 1),q(n - 2)} =
      {q(n - 1),q 0})`
  (LABEL_TAC "boundary_edges_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same_edges") THEN
    MP_TAC(ISPECL
     [`(q:num->A)(n - 1)`; `(q:num->A)(n - 2)`;
      `(q:num->A)(n - 1)`; `(q:num->A) 0`]
     PAIR_SET_EQ_DISTINCT) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "boundary_distinct" MP_TAC THEN MESON_TAC[];
        USE_THEN "same_edges" ACCEPT_TAC];
      USE_THEN "boundary_distinct" MP_TAC THEN MESON_TAC[]];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (ISPECL [`V:A->bool`; `E:(A->bool)->bool`]
    FINITE_SIMPLE_GRAPH_ENDPOINT_FUNCTIONS)
   (ASSUME `finite_simple_graph (V:A->bool) E`)) THEN
  INTRO_TAC "@a b. edge_data" THEN
  USE_THEN "edge_data"
   (MP_TAC o SPEC `{(q:num->A)(n - 1),q(n - 2)}`) THEN
  ANTS_TAC THENL
   [USE_THEN "left_edge" ACCEPT_TAC;
    INTRO_TAC "left_endpoint_pair left_endpoint_distinct"] THEN
  USE_THEN "edge_data"
   (MP_TAC o SPEC `{(q:num->A)(n - 1),q 0}`) THEN
  ANTS_TAC THENL
   [USE_THEN "right_edge" ACCEPT_TAC;
    INTRO_TAC "right_endpoint_pair right_endpoint_distinct"] THEN
  SUBGOAL_THEN
   `radialized_edge_other_endpoint
      (a:(A->bool)->A) b (q(n - 1)) {q(n - 1),q(n - 2)} =
    q(n - 2)`
  (LABEL_TAC "left_other") THENL
   [MATCH_MP_TAC RADIALIZED_EDGE_OTHER_ENDPOINT_PAIR THEN
    REPEAT CONJ_TAC THENL
     [REFL_TAC;
      USE_THEN "boundary_distinct" MP_TAC THEN MESON_TAC[];
      USE_THEN "left_endpoint_pair" ACCEPT_TAC;
      USE_THEN "left_endpoint_distinct" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `radialized_edge_other_endpoint
      (a:(A->bool)->A) b (q(n - 1)) {q(n - 1),q 0} = q 0`
  (LABEL_TAC "right_other") THENL
   [MATCH_MP_TAC RADIALIZED_EDGE_OTHER_ENDPOINT_PAIR THEN
    REPEAT CONJ_TAC THENL
     [REFL_TAC;
      USE_THEN "boundary_distinct" MP_TAC THEN MESON_TAC[];
      USE_THEN "right_endpoint_pair" ACCEPT_TAC;
      USE_THEN "right_endpoint_distinct" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `{(q:num->A)(n - 2),q 0} IN E`
  (LABEL_TAC "neighbor_edge") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `a:(A->bool)->A`;
      `b:(A->bool)->A`; `l1:real^2->bool`;
      `(q:num->A)(n - 1)`;
      `{(q:num->A)(n - 1),q(n - 2)}`;
      `{(q:num->A)(n - 1),q 0}`]
     PLANE_TRIANGULATED_DISK_INTERNAL_FACE_INCIDENT_EDGE_ENDPOINTS_ADJACENT)
    THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "disk" ACCEPT_TAC;
        USE_THEN "edge_data" ACCEPT_TAC;
        USE_THEN "l1_face" ACCEPT_TAC;
        USE_THEN "outer_l1_distinct" MP_TAC THEN MESON_TAC[];
        USE_THEN "boundary_edges_distinct" ACCEPT_TAC;
        USE_THEN "left_edge" ACCEPT_TAC;
        USE_THEN "right_edge" ACCEPT_TAC;
        REWRITE_TAC[IN_INSERT];
        REWRITE_TAC[IN_INSERT];
        USE_THEN "left_l1" ACCEPT_TAC;
        USE_THEN "right_l1" ACCEPT_TAC];
      USE_THEN "left_other" (fun lth ->
       USE_THEN "right_other" (fun rth ->
        DISCH_THEN(ACCEPT_TAC o REWRITE_RULE[lth;rth])))];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [ONCE_REWRITE_TAC[EXTENSION] THEN
    REWRITE_TAC[IN_ELIM_THM; IN_INSERT; IN_SING] THEN
    X_GEN_TAC `e:A->bool` THEN EQ_TAC THENL
     [INTRO_TAC "edge incident" THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `e:A->bool`]
       PLANE_GRAPH_EMBEDDING_EDGE_INCIDENT_COMPONENT_FRONTIER) THEN
      ASM_REWRITE_TAC[] THEN
      INTRO_TAC "@k. k_component e_k" THEN
      SUBGOAL_THEN
       `(e:A->bool) SUBSET
        plane_graph_face_vertices V E p c (k:real^2->bool)`
      (LABEL_TAC "e_face") THENL
       [MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
          `c:(A->bool)->real^2->bool`; `e:A->bool`;
          `k:real^2->bool`]
         PLANE_GRAPH_EMBEDDING_FRONTIER_EDGE_SUBSET_FACE_VERTICES) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(k:real^2->bool) IN
        plane_graph_incident_faces
         (V:A->bool) E p c ((q:num->A)(n - 1))`
      (LABEL_TAC "k_face") THENL
       [REWRITE_TAC[plane_graph_incident_faces; IN_ELIM_THM] THEN
        CONJ_TAC THENL
         [USE_THEN "k_component" ACCEPT_TAC;
          USE_THEN "e_face"
           (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          USE_THEN "incident" ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(k:real^2->bool) = outer \/ k = l1`
      (LABEL_TAC "k_choice") THENL
       [USE_THEN "k_face" MP_TAC THEN
        USE_THEN "faces_pair" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[IN_INSERT; IN_SING];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(c:(A->bool)->real^2->bool) {q(n - 1),q(n - 2)}
          SUBSET frontier k /\
        c {q(n - 1),q 0} SUBSET frontier k`
      (CONJUNCTS_THEN2
       (LABEL_TAC "left_k") (LABEL_TAC "right_k")) THENL
       [CONJ_TAC THENL
         [USE_THEN "k_choice"
           (DISJ_CASES_THEN SUBST1_TAC) THEN
          ASM_REWRITE_TAC[];
          USE_THEN "k_choice"
           (DISJ_CASES_THEN SUBST1_TAC) THEN
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
        `outer:real^2->bool`; `k:real^2->bool`;
        `{(q:num->A)(n - 1),q(n - 2)}`;
        `{(q:num->A)(n - 1),q 0}`; `e:A->bool`]
       PLANE_TRIANGULATED_DISK_INCIDENT_FACE_FRONTIER_EDGE_CHOICE) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [USE_THEN "disk" ACCEPT_TAC;
          USE_THEN "chordless" ACCEPT_TAC;
          USE_THEN "k_face" ACCEPT_TAC;
          USE_THEN "boundary_edges_distinct" ACCEPT_TAC;
          USE_THEN "left_edge" ACCEPT_TAC;
          USE_THEN "right_edge" ACCEPT_TAC;
          USE_THEN "edge" ACCEPT_TAC;
          REWRITE_TAC[IN_INSERT];
          REWRITE_TAC[IN_INSERT];
          USE_THEN "incident" ACCEPT_TAC;
          USE_THEN "left_k" ACCEPT_TAC;
          USE_THEN "right_k" ACCEPT_TAC;
          USE_THEN "e_k" ACCEPT_TAC];
        DISCH_THEN
         (DISJ_CASES_THEN
           (fun th -> REWRITE_TAC[th; IN_INSERT; IN_SING]))];
      DISCH_THEN
       (DISJ_CASES_THEN
         (fun th -> ASM_REWRITE_TAC[th; IN_INSERT; IN_SING]))];
    USE_THEN "neighbor_edge" ACCEPT_TAC;
    EXISTS_TAC `l1:real^2->bool` THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "l1_face" ACCEPT_TAC;
      USE_THEN "outer_l1_distinct" MP_TAC THEN MESON_TAC[];
      USE_THEN "left_l1" ACCEPT_TAC;
      USE_THEN "right_l1" ACCEPT_TAC]]);;

let FINITE_SIMPLE_GRAPH_TWO_INCIDENT_EDGES_NEIGHBORS = prove
 (`!V E v a b.
        finite_simple_graph (V:A->bool) E /\
        {e:A->bool | e IN E /\ v IN e} = {{v,a},{v,b}}
        ==> graph_neighbors E v = {a,b}`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph incident_edges" THEN
  SUBGOAL_THEN
   `{(v:A),a} IN E /\ {(v:A),b} IN E`
  (CONJUNCTS_THEN2 (LABEL_TAC "edge_a") (LABEL_TAC "edge_b")) THENL
   [CONJ_TAC THENL
     [SUBGOAL_THEN
       `({(v:A),a}:A->bool) IN {e | e IN E /\ v IN e}`
      MP_TAC THENL
       [USE_THEN "incident_edges" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[IN_INSERT];
        REWRITE_TAC[IN_ELIM_THM] THEN MESON_TAC[]];
      SUBGOAL_THEN
       `({(v:A),b}:A->bool) IN {e | e IN E /\ v IN e}`
      MP_TAC THENL
       [USE_THEN "incident_edges" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[IN_INSERT];
        REWRITE_TAC[IN_ELIM_THM] THEN MESON_TAC[]]];
    ALL_TAC] THEN
  ONCE_REWRITE_TAC[EXTENSION] THEN
  X_GEN_TAC `u:A` THEN
  REWRITE_TAC[IN_GRAPH_NEIGHBORS; IN_INSERT; IN_SING] THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "edge") THEN
    SUBGOAL_THEN `~((v:A) = u)` (LABEL_TAC "distinct") THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `u:A`]
       FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
      ASM_REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `({(v:A),u}:A->bool) = {v,a} \/ {v,u} = {v,b}`
    (LABEL_TAC "choice") THENL
     [SUBGOAL_THEN
       `({(v:A),u}:A->bool) IN {e | e IN E /\ v IN e}`
      MP_TAC THENL
       [REWRITE_TAC[IN_ELIM_THM; IN_INSERT] THEN
        USE_THEN "edge" ACCEPT_TAC;
        USE_THEN "incident_edges" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[IN_INSERT; IN_SING]];
      ALL_TAC] THEN
    USE_THEN "choice"
     (DISJ_CASES_THEN (LABEL_TAC "pair")) THENL
     [MP_TAC(ISPECL [`v:A`; `u:A`; `v:A`; `a:A`]
       PAIR_SET_EQ_DISTINCT) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[];
      MP_TAC(ISPECL [`v:A`; `u:A`; `v:A`; `b:A`]
       PAIR_SET_EQ_DISTINCT) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[]];
    DISCH_THEN(DISJ_CASES_THEN (fun th -> ASM_REWRITE_TAC[th]))]);;

let TWO_VERTEX_NEIGHBOR_PATH = prove
 (`!E:(A->bool)->bool. !a b.
        ~(a = b) /\ {a,b} IN E
        ==> ?w:num->A.
              cyclic_vertices w 2 = {a,b} /\
              INJ w (cyclic_indices 2) (:A) /\
              w 0 = a /\
              w 1 = b /\
              (!r. r + 1 < 2 ==> {w r,w(r + 1)} IN E)`,
  REPEAT GEN_TAC THEN INTRO_TAC "distinct edge" THEN
  EXISTS_TAC `\i:num. if i = 0 then (a:A) else b` THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[CYCLIC_VERTICES_2] THEN BETA_TAC THEN
    REWRITE_TAC[ARITH_RULE `~((1:num) = 0)`];
    REWRITE_TAC
     [INJ; CYCLIC_INDICES_2; IN_INSERT; NOT_IN_EMPTY; IN_UNIV] THEN
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN BETA_TAC THEN
    INTRO_TAC "i_index j_index same" THEN
    ASM_CASES_TAC `(i:num) = 0` THEN
    ASM_CASES_TAC `(j:num) = 0` THEN
    USE_THEN "same" MP_TAC THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    BETA_TAC THEN REWRITE_TAC[];
    BETA_TAC THEN REWRITE_TAC[ARITH_RULE `~((1:num) = 0)`];
    X_GEN_TAC `r:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    SUBGOAL_THEN `(r:num) = 0` SUBST1_TAC THENL
     [ASM_ARITH_TAC;
      BETA_TAC THEN
      ASM_REWRITE_TAC
       [ADD_CLAUSES; ARITH_RULE `~((1:num) = 0)`]]]);;

let PLANE_TRIANGULATED_DISK_DELETE_LAST_TWO_INCIDENT_FACES = prove
 (`!V E p c q n outer.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        c {q(n - 1),q(n - 2)} SUBSET frontier outer /\
        c {q(n - 1),q 0} SUBSET frontier outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        CARD(plane_graph_incident_faces
               V E p c (q(n - 1))) = 2 /\
        4 <= n
        ==> ?w newouter.
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w 2 /\
              INJ w (cyclic_indices 2) (:A) /\
              w 0 = q(n - 2) /\
              w 1 = q 0 /\
              plane_triangulated_disk
                (V DELETE q(n - 1))
                (induced_subgraph_edges E (V DELETE q(n - 1)))
                p c (cyclic_delete_last q w n) (n - 1) newouter`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk left_boundary right_boundary chordless face_card nlarge" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding _ q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_TWO_INCIDENT_FACES_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "incident_edges neighbor_edge _" THEN
  SUBGOAL_THEN
   `graph_neighbors E ((q:num->A)(n - 1)) = {q(n - 2),q 0}`
  (LABEL_TAC "neighbors") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `(q:num->A)(n - 1)`;
      `(q:num->A)(n - 2)`; `(q:num->A) 0`]
     FINITE_SIMPLE_GRAPH_TWO_INCIDENT_EDGES_NEIGHBORS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((q:num->A)(n - 2) = q 0)`
  (LABEL_TAC "endpoints_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same") THEN
    USE_THEN "q_injective"
     (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
    REWRITE_TAC[IN_CYCLIC_INDICES; IN_UNIV] THEN
    DISCH_THEN(MP_TAC o SPECL [`n - 2`; `0`]) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [ASM_ARITH_TAC;
        ASM_ARITH_TAC;
        USE_THEN "same" ACCEPT_TAC];
      ASM_ARITH_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `(q:num->A)(n - 2)`; `(q:num->A) 0`]
   TWO_VERTEX_NEIGHBOR_PATH) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@w. vertices w_injective first last chain" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `0`; `w:num->A`]
   PLANE_TRIANGULATED_DISK_DELETE_LAST_WITH_NEIGHBOR_PATH) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "disk" ACCEPT_TAC;
      USE_THEN "chordless" ACCEPT_TAC;
      ASM_ARITH_TAC;
      ASM_REWRITE_TAC[ADD_CLAUSES];
      ASM_REWRITE_TAC[ADD_CLAUSES];
      ASM_REWRITE_TAC[ADD_CLAUSES];
      ASM_REWRITE_TAC[ADD_CLAUSES];
      ASM_REWRITE_TAC[ADD_CLAUSES]];
    INTRO_TAC "@newouter. newdisk"] THEN
  MAP_EVERY EXISTS_TAC
   [`w:num->A`; `newouter:real^2->bool`] THEN
  ASM_REWRITE_TAC[ADD_CLAUSES] THEN
  USE_THEN "newdisk"
   (ACCEPT_TAC o REWRITE_RULE[ADD_CLAUSES]));;

let PLANE_GRAPH_EMBEDDING_VERTEX_ON_EDGE = prove
 (`!V E p c u e.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        u IN V /\
        e IN E /\
        p u IN c e
        ==> u IN e`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding u_vertex edge point" THEN
  USE_THEN "embedding" MP_TAC THEN
  REWRITE_TAC[plane_graph_embedding] THEN
