  ANTS_TAC THENL
   [USE_THEN "edge" ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "edge_intersection")] THEN
  SUBGOAL_THEN
   `(p:A->real^2) u IN
    (c:(A->bool)->real^2->bool) (e:A->bool) INTER IMAGE p V`
  (LABEL_TAC "point_intersection") THENL
   [REWRITE_TAC[IN_INTER] THEN CONJ_TAC THENL
     [USE_THEN "point" ACCEPT_TAC;
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `u:A` THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:A->real^2) u IN IMAGE p (e:A->bool)`
  (LABEL_TAC "point_endpoint") THENL
   [USE_THEN "edge_intersection" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "point_intersection" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "point_endpoint" MP_TAC THEN
  REWRITE_TAC[IN_IMAGE] THEN
  INTRO_TAC "@v. same v_edge" THEN
  SUBGOAL_THEN `(v:A) IN V` (LABEL_TAC "v_vertex") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    INTRO_TAC "_ _ edges" THEN
    USE_THEN "edges" (MP_TAC o SPEC `e:A->bool`) THEN
    ANTS_TAC THENL
     [USE_THEN "edge" ACCEPT_TAC;
      INTRO_TAC "edge_subset _"] THEN
    USE_THEN "edge_subset"
     (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "v_edge" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "p_injective"
   (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
  DISCH_THEN(MP_TAC o SPECL [`u:A`; `v:A`]) THEN
  ASM_REWRITE_TAC[IN_UNIV] THEN
  DISCH_THEN SUBST1_TAC THEN
  USE_THEN "v_edge" ACCEPT_TAC);;

let PLANE_TRIANGULATED_DISK_TRIANGULAR_BOUNDARY_TWO_FACES_VERTICES =
  prove
 (`!V E p c q outer.
        plane_triangulated_disk (V:A->bool) E p c q 3 outer /\
        c {q 2,q 1} SUBSET frontier outer /\
        c {q 2,q 0} SUBSET frontier outer /\
