   `!j. 0 < j /\ j + 2 < 3
        ==> ~({(q:num->A) j,q 2} IN E)`
  (LABEL_TAC "chordless") THENL
   [ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `3`;
    `outer:real^2->bool`]
