  (CONJUNCTS_THEN2
   (LABEL_TAC "left_face") (LABEL_TAC "right_face")) THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `{(q:num->A) 2,q 1}`;
        `l:real^2->bool`]
       PLANE_GRAPH_EMBEDDING_FRONTIER_EDGE_SUBSET_FACE_VERTICES) THEN
