let PLANE_TRIANGULATED_DISK_DELETE_LAST_CHORDLESS = prove
 (`!V E p c q n outer.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        c {q(n - 1),q(n - 2)} SUBSET frontier outer /\
        c {q(n - 1),q 0} SUBSET frontier outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        3 < CARD V
        ==> ?k w newouter.
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = q(n - 2) /\
              w(k + 1) = q 0 /\
              plane_triangulated_disk
                (V DELETE q(n - 1))
                (induced_subgraph_edges E (V DELETE q(n - 1)))
                p c (cyclic_delete_last q w n)
                (n - 1 + k) newouter`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk left_boundary right_boundary chordless vertices_large" THEN
  SUBGOAL_THEN
   `2 <= CARD(plane_graph_incident_faces
      (V:A->bool) E p c ((q:num->A)(n - 1)))`
  (LABEL_TAC "faces_lower") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
     `outer:real^2->bool`]
     PLANE_TRIANGULATED_DISK_LAST_INCIDENT_FACES_CARD_AT_LEAST_2) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC
   `CARD(plane_graph_incident_faces
      (V:A->bool) E p c ((q:num->A)(n - 1))) = 2` THENL
   [FIRST_X_ASSUM(LABEL_TAC "face_card") THEN
    SUBGOAL_THEN `4 <= (n:num)` (LABEL_TAC "nlarge") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
        `outer:real^2->bool`]
       PLANE_TRIANGULATED_DISK_TWO_FACES_BOUNDARY_LENGTH) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`]
     PLANE_TRIANGULATED_DISK_DELETE_LAST_TWO_INCIDENT_FACES) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC
     "@w newouter. neighbors w_injective first last newdisk" THEN
    MAP_EVERY EXISTS_TAC
     [`0`; `w:num->A`; `newouter:real^2->bool`] THEN
