    SUBGOAL_THEN
     `3 <= CARD(plane_graph_incident_faces
        (V:A->bool) E p c ((q:num->A)(n - 1)))`
    (LABEL_TAC "faces_large") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`]
     PLANE_TRIANGULATED_DISK_DELETE_LAST_LARGE_INCIDENT_FACE_CYCLE) THEN
    ASM_REWRITE_TAC[]]);;
let PLANE_GRAPH_EMBEDDING_EDGE_INTER_CYCLE_CARRIER = prove
 (`!V E p c q n e.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        simple_graph_cycle E q n /\
        e IN E /\
        ~(e IN cyclic_edges q n)
        ==> c e INTER UNIONS(IMAGE c (cyclic_edges q n)) =
            IMAGE p (e INTER cyclic_vertices q n)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding cycle edge not_cycle" THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INTER] THEN
    X_GEN_TAC `x:real^2` THEN INTRO_TAC "x_edge x_cycle" THEN
    USE_THEN "x_cycle" MP_TAC THEN
    REWRITE_TAC[IN_UNIONS; IN_IMAGE] THEN
    INTRO_TAC "@s. (@d. set_eq d_cycle) x_d" THEN
    USE_THEN "set_eq" SUBST_ALL_TAC THEN
    SUBGOAL_THEN `(d:A->bool) IN E` (LABEL_TAC "d_edge") THENL
     [USE_THEN "cycle" MP_TAC THEN
      REWRITE_TAC[simple_graph_cycle] THEN
      INTRO_TAC "_ _ cycle_edges" THEN
      USE_THEN "cycle_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "d_cycle" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((e:A->bool) = d)` (LABEL_TAC "distinct") THENL
     [DISCH_THEN SUBST_ALL_TAC THEN
      USE_THEN "not_cycle" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "d_cycle" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(c:(A->bool)->real^2->bool) e INTER c d =
      IMAGE p (e INTER d)`
    (LABEL_TAC "edge_intersection") THENL
     [USE_THEN "embedding" MP_TAC THEN
      REWRITE_TAC[plane_graph_embedding] THEN
      INTRO_TAC "_ _ _ intersections" THEN
      USE_THEN "intersections" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(x:real^2) IN IMAGE (p:A->real^2) (e INTER d)`
    (LABEL_TAC "x_image") THENL
     [USE_THEN "edge_intersection" (fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[IN_INTER];
      ALL_TAC] THEN
    USE_THEN "x_image" MP_TAC THEN
    REWRITE_TAC[IN_IMAGE; IN_INTER] THEN
    INTRO_TAC "@u. x_eq u_e u_d" THEN
    REWRITE_TAC[IN_IMAGE; IN_INTER] THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(REWRITE_RULE[SUBSET]
     (MATCH_MP
      (SPECL [`q:num->A`; `n:num`; `d:A->bool`]
       CYCLIC_EDGE_SUBSET_VERTICES)
      (CONJ
       (MATCH_MP (ARITH_RULE `3 <= n ==> 0 < n`)
        (CONJUNCT1(REWRITE_RULE[simple_graph_cycle]
         (ASSUME `simple_graph_cycle (E:(A->bool)->bool) q n`))))
       (ASSUME `(d:A->bool) IN cyclic_edges q n`)))) THEN
    USE_THEN "u_d" ACCEPT_TAC;
    REWRITE_TAC[SUBSET] THEN X_GEN_TAC `x:real^2` THEN
    REWRITE_TAC[IN_IMAGE; IN_INTER] THEN
    INTRO_TAC "@u. x_eq u_edge u_boundary" THEN
    USE_THEN "x_eq" SUBST1_TAC THEN REWRITE_TAC[IN_INTER] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `e:A->bool`; `u:A`]
       PLANE_GRAPH_EMBEDDING_EDGE_ENDPOINT_MEMBER) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "u_boundary" MP_TAC THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    INTRO_TAC "@i. i_index u_eq" THEN
    USE_THEN "u_eq" SUBST1_TAC THEN
    ABBREV_TAC `d:A->bool = {q i,q((i + 1) MOD n)}` THEN
    SUBGOAL_THEN `(d:A->bool) IN cyclic_edges q n`
    (LABEL_TAC "d_cycle") THENL
     [EXPAND_TAC "d" THEN REWRITE_TAC[IN_CYCLIC_EDGES] THEN
      EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(d:A->bool) IN E` (LABEL_TAC "d_edge") THENL
     [USE_THEN "cycle" MP_TAC THEN
      REWRITE_TAC[simple_graph_cycle] THEN
      INTRO_TAC "_ _ cycle_edges" THEN
      USE_THEN "cycle_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "d_cycle" ACCEPT_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[IN_UNIONS] THEN
    EXISTS_TAC `(c:(A->bool)->real^2->bool) d` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `d:A->bool` THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `d:A->bool`; `(q:num->A) i`]
       PLANE_GRAPH_EMBEDDING_EDGE_ENDPOINT_MEMBER) THEN
      ASM_REWRITE_TAC[] THEN
      EXPAND_TAC "d" THEN REWRITE_TAC[IN_INSERT]]]);;

