let CYCLIC_CHORD_TO_LAST_NOT_EDGE = prove
 (`!q:num->A. !n j.
        INJ q (cyclic_indices n) (:A) /\
        0 < j /\ j + 2 < n
        ==> ~({q j,q(n - 1)} IN cyclic_edges q n)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "injective jpositive bound" THEN
  REWRITE_TAC[IN_CYCLIC_EDGES] THEN
  INTRO_TAC "@i. i_index edge_eq" THEN
  SUBGOAL_THEN `~((q:num->A) j = q(n - 1))`
  (LABEL_TAC "endpoints_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same") THEN
    USE_THEN "injective" (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
    DISCH_THEN(MP_TAC o SPECL [`j:num`; `n - 1`]) THEN
    ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((q:num->A) i = q j /\
     q((i + 1) MOD n) = q(n - 1)) \/
    (q i = q(n - 1) /\ q((i + 1) MOD n) = q j)`
  (DISJ_CASES_THEN STRIP_ASSUME_TAC) THENL
   [USE_THEN "edge_eq" MP_TAC THEN
    USE_THEN "endpoints_distinct" MP_TAC THEN SET_TAC[];
    SUBGOAL_THEN `(i:num) = j` (LABEL_TAC "i_eq") THENL
     [USE_THEN "injective"
       (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
      DISCH_THEN(MP_TAC o SPECL [`i:num`; `j:num`]) THEN
      ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "i_eq" SUBST_ALL_TAC THEN
    SUBGOAL_THEN `(j + 1) MOD n = j + 1`
    (LABEL_TAC "mod_eq") THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      RULE_ASSUM_TAC
       (REWRITE_RULE[ASSUME `(j + 1) MOD n = j + 1`])] THEN
    USE_THEN "injective"
     (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
    DISCH_THEN(MP_TAC o SPECL [`j + 1`; `n - 1`]) THEN
    ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
    SUBGOAL_THEN `(i:num) = n - 1` (LABEL_TAC "i_eq") THENL
     [USE_THEN "injective"
       (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
      DISCH_THEN(MP_TAC o SPECL [`i:num`; `n - 1`]) THEN
      ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "i_eq" SUBST_ALL_TAC THEN
    SUBGOAL_THEN `(n - 1) + 1 = n` (LABEL_TAC "last_suc") THENL
     [ASM_ARITH_TAC;
      RULE_ASSUM_TAC
       (REWRITE_RULE[ASSUME `(n - 1) + 1 = n`; MOD_REFL])] THEN
    USE_THEN "injective"
     (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
    DISCH_THEN(MP_TAC o SPECL [`0`; `j:num`]) THEN
    ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC]);;

let PLANE_GRAPH_EMBEDDING_CHORD_INTER_CYCLE_CARRIER = prove
 (`!V E p c q n j.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        simple_graph_cycle E q n /\
        0 < j /\ j + 2 < n /\
        {q j,q(n - 1)} IN E
        ==> c {q j,q(n - 1)} INTER
            UNIONS(IMAGE c (cyclic_edges q n)) =
            {p(q j),p(q(n - 1))}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding cycle jpositive bound chord" THEN
  SUBGOAL_THEN `INJ (q:num->A) (cyclic_indices n) (:A)`
  (LABEL_TAC "injective") THENL
   [USE_THEN "cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~({(q:num->A) j,q(n - 1)} IN cyclic_edges q n)`
  (LABEL_TAC "not_cycle") THENL
   [MATCH_MP_TAC CYCLIC_CHORD_TO_LAST_NOT_EDGE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `{(q:num->A) j,q(n - 1)}:A->bool`]
   PLANE_GRAPH_EMBEDDING_EDGE_INTER_CYCLE_CARRIER) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "intersection") THEN
  SUBGOAL_THEN
   `({(q:num->A) j,q(n - 1)}:A->bool) INTER
    cyclic_vertices q n = {q j,q(n - 1)}`
  (LABEL_TAC "boundary_endpoints") THENL
   [MATCH_MP_TAC(SET_RULE `s SUBSET t ==> s INTER t = s`) THEN
    REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_CYCLIC_VERTICES] THEN
    CONJ_TAC THENL
     [EXISTS_TAC `j:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      EXISTS_TAC `n - 1` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  USE_THEN "intersection" (fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[IMAGE_CLAUSES]);;
let cyclic_split_left_oriented = new_definition
 `cyclic_split_left_oriented (q:num->A) n j i =
    if i <= j then q(j - i) else q(n - 1)`;;
let CYCLIC_SPLIT_LEFT_ORIENTED_INJ = prove
 (`!q:num->A. !n j.
        INJ q (cyclic_indices n) (:A) /\ j + 2 < n
        ==> INJ (cyclic_split_left_oriented q n j)
                (cyclic_indices (j + 2)) (:A)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[INJ; IN_CYCLIC_INDICES; IN_UNIV;
              cyclic_split_left_oriented] THEN
  INTRO_TAC "injective bound" THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `k:num`] THEN
  INTRO_TAC "i_index k_index same" THEN
  ASM_CASES_TAC `(i:num) <= j` THEN
  ASM_CASES_TAC `(k:num) <= j` THEN ASM_REWRITE_TAC[] THENL
   [SUBGOAL_THEN `(q:num->A)(j - i) = q(j - k)`
    (LABEL_TAC "images_eq") THENL
     [USE_THEN "same" MP_TAC THEN
      REWRITE_TAC[ASSUME `(i:num) <= j`; ASSUME `(k:num) <= j`];
      ALL_TAC] THEN
    USE_THEN "injective"
     (MP_TAC o SPECL [`j - i:num`; `j - k:num`]) THEN
    DISCH_THEN(LABEL_TAC "injective_case") THEN
    SUBGOAL_THEN
     `j - i < n /\ j - k < n /\
      (q:num->A)(j - i) = q(j - k)`
    (LABEL_TAC "injective_arguments") THENL
     [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "injective_case" (fun th ->
     MP_TAC(MP th (ASSUME
      `j - i < n /\ j - k < n /\
       (q:num->A)(j - i) = q(j - k)`))) THEN
    DISCH_THEN(LABEL_TAC "reverse_eq") THEN ASM_ARITH_TAC;
    SUBGOAL_THEN `(q:num->A)(j - i) = q(n - 1)`
    (LABEL_TAC "images_eq") THENL
     [USE_THEN "same" MP_TAC THEN
      REWRITE_TAC
       [ASSUME `(i:num) <= j`; ASSUME `~((k:num) <= j)`];
      ALL_TAC] THEN
    USE_THEN "injective"
     (MP_TAC o SPECL [`j - i:num`; `n - 1:num`]) THEN
    DISCH_THEN(LABEL_TAC "injective_case") THEN
    SUBGOAL_THEN
     `j - i < n /\ n - 1 < n /\
      (q:num->A)(j - i) = q(n - 1)`
    (LABEL_TAC "injective_arguments") THENL
     [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "injective_case" (fun th ->
     MP_TAC(MP th (ASSUME
      `j - i < n /\ n - 1 < n /\
       (q:num->A)(j - i) = q(n - 1)`))) THEN
    DISCH_THEN(LABEL_TAC "index_eq") THEN ASM_ARITH_TAC;
    SUBGOAL_THEN `(q:num->A)(n - 1) = q(j - k)`
    (LABEL_TAC "images_eq") THENL
     [USE_THEN "same" MP_TAC THEN
      REWRITE_TAC
       [ASSUME `~((i:num) <= j)`; ASSUME `(k:num) <= j`];
      ALL_TAC] THEN
    USE_THEN "injective"
     (MP_TAC o SPECL [`n - 1:num`; `j - k:num`]) THEN
    DISCH_THEN(LABEL_TAC "injective_case") THEN
    SUBGOAL_THEN
     `n - 1 < n /\ j - k < n /\
      (q:num->A)(n - 1) = q(j - k)`
    (LABEL_TAC "injective_arguments") THENL
     [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "injective_case" (fun th ->
     MP_TAC(MP th (ASSUME
      `n - 1 < n /\ j - k < n /\
       (q:num->A)(n - 1) = q(j - k)`))) THEN
    DISCH_THEN(LABEL_TAC "index_eq") THEN ASM_ARITH_TAC;
    ASM_ARITH_TAC]);;

let SIMPLE_GRAPH_CYCLE_SPLIT_LEFT_ORIENTED = prove
 (`!E:(A->bool)->bool. !q:num->A. !n j.
        simple_graph_cycle E q n /\
        0 < j /\ j + 2 < n /\ {q j,q(n - 1)} IN E
        ==> simple_graph_cycle E
              (cyclic_split_left_oriented q n j) (j + 2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "cycle jpositive bound chord" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective cycle_edges" THEN
  REWRITE_TAC[simple_graph_cycle] THEN REPEAT CONJ_TAC THENL
   [ASM_ARITH_TAC;
    MATCH_MP_TAC CYCLIC_SPLIT_LEFT_ORIENTED_INJ THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET; IN_CYCLIC_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN
  INTRO_TAC "@i. i_index edge_eq" THEN
  USE_THEN "edge_eq" SUBST1_TAC THEN
  ASM_CASES_TAC `(i:num) < j` THENL
   [SUBGOAL_THEN `(i + 1) MOD (j + 2) = i + 1`
    (LABEL_TAC "next") THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[cyclic_split_left_oriented] THEN
    REWRITE_TAC[ASSUME `(i:num) < j`] THEN
    SUBGOAL_THEN `(i:num) <= j /\ i + 1 <= j`
    STRIP_ASSUME_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
    SUBGOAL_THEN `j - (i + 1) + 1 = j - i`
    (LABEL_TAC "successor") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "successor" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `j - (i + 1)`]
     SIMPLE_GRAPH_CYCLE_CONSECUTIVE_EDGE) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `(i:num) = j` THENL
   [SUBGOAL_THEN `(i + 1) MOD (j + 2) = j + 1`
    (LABEL_TAC "next") THENL
     [SUBST1_TAC(ASSUME `(i:num) = j`) THEN
      MATCH_MP_TAC MOD_LT THEN ARITH_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[cyclic_split_left_oriented] THEN
    REWRITE_TAC[ASSUME `(i:num) = j`] THEN
    SUBGOAL_THEN `j - j = 0` SUBST1_TAC THENL
     [ARITH_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[LE_REFL; ARITH_RULE `~((j:num) + 1 <= j)`] THEN
    SUBGOAL_THEN
     `{(q:num->A) 0,q(n - 1)} = {q(n - 1),q 0}`
    SUBST1_TAC THENL
     [SET_TAC[];
      MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CLOSING_EDGE THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(i:num) = j + 1` (LABEL_TAC "last") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(i + 1) MOD (j + 2) = 0`
  (LABEL_TAC "wrap") THENL
   [REWRITE_TAC[MOD_EQ_0] THEN EXISTS_TAC `1` THEN
    REWRITE_TAC[MULT_CLAUSES] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "last" (fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[cyclic_split_left_oriented] THEN
  SUBGOAL_THEN `((j + 1) + 1) MOD (j + 2) = 0`
  (LABEL_TAC "wrap_at_last") THENL
   [REWRITE_TAC[MOD_EQ_0] THEN EXISTS_TAC `1` THEN
    REWRITE_TAC[MULT_CLAUSES] THEN ARITH_TAC;
    ALL_TAC] THEN
  ASM_REWRITE_TAC
   [LE_0; SUB_0; ARITH_RULE `~((j:num) + 1 <= j)`] THEN
  SUBGOAL_THEN
   `{(q:num->A)(n - 1),q j} = {q j,q(n - 1)}`
  SUBST1_TAC THENL
   [SET_TAC[];
    ASM_REWRITE_TAC[]]);;
let cyclic_split_left_boundary_edges = new_definition
 `cyclic_split_left_boundary_edges (q:num->A) n j =
    IMAGE
      (\i. {cyclic_split_left_oriented q n j i,
             cyclic_split_left_oriented q n j (i + 1)})
      (0..j)`;;

let cyclic_split_right_boundary_edges = new_definition
 `cyclic_split_right_boundary_edges (q:num->A) n j =
    IMAGE
      (\i. {cyclic_split_right q j i,
             cyclic_split_right q j (i + 1)})
      (0..n - j - 2)`;;
let IN_CYCLIC_SPLIT_LEFT_BOUNDARY_EDGES = prove
 (`!q:num->A. !n j e.
        0 < j
        ==> (e IN cyclic_split_left_boundary_edges q n j <=>
             e = {q(n - 1),q 0} \/
             ?k. k < j /\ e = {q k,q(k + 1)})`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "jpositive") THEN
  REWRITE_TAC
   [cyclic_split_left_boundary_edges; IN_IMAGE; IN_NUMSEG] THEN
  EQ_TAC THENL
   [INTRO_TAC "@i. edge i_nonnegative i_bound" THEN
    ASM_CASES_TAC `(i:num) = j` THENL
     [DISJ1_TAC THEN USE_THEN "edge" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[cyclic_split_left_oriented] THEN
      ASM_REWRITE_TAC[LE_REFL; ARITH_RULE `~((j:num) + 1 <= j)`;
                      SUB_REFL] THEN
      SET_TAC[];
      DISJ2_TAC THEN EXISTS_TAC `j - (i + 1)` THEN
      CONJ_TAC THENL
       [ASM_ARITH_TAC;
        USE_THEN "edge" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[cyclic_split_left_oriented] THEN
        SUBGOAL_THEN `(i:num) <= j /\ i + 1 <= j`
        STRIP_ASSUME_TAC THENL
         [ASM_ARITH_TAC;
          ALL_TAC] THEN
        ASM_REWRITE_TAC[] THEN
        SUBGOAL_THEN `j - (i + 1) + 1 = j - i`
        (LABEL_TAC "successor") THENL
         [ASM_ARITH_TAC;
          ALL_TAC] THEN
        USE_THEN "successor" (fun th -> REWRITE_TAC[th]) THEN
        SET_TAC[]]];
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "closing")
     (X_CHOOSE_THEN `k:num`
      (CONJUNCTS_THEN2 (LABEL_TAC "k_bound")
       (LABEL_TAC "old_edge")))) THENL
     [EXISTS_TAC `j:num` THEN REPEAT CONJ_TAC THENL
       [USE_THEN "closing" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[cyclic_split_left_oriented; LE_REFL;
                    ARITH_RULE `~((j:num) + 1 <= j)`; SUB_REFL] THEN
        MATCH_ACCEPT_TAC PAIR_SET_SYM;
        ARITH_TAC;
        ARITH_TAC];
      EXISTS_TAC `j - (k + 1)` THEN REPEAT CONJ_TAC THENL
       [USE_THEN "old_edge" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[cyclic_split_left_oriented] THEN
        SUBGOAL_THEN
         `j - (k + 1) <= j /\ j - (k + 1) + 1 <= j`
        STRIP_ASSUME_TAC THENL
         [ASM_ARITH_TAC;
          ALL_TAC] THEN
        ASM_REWRITE_TAC[] THEN
        SUBGOAL_THEN
         `j - (j - (k + 1)) = k + 1 /\
          j - (j - (k + 1) + 1) = k`
        STRIP_ASSUME_TAC THENL
         [ASM_ARITH_TAC;
          ALL_TAC] THEN
        ASM_REWRITE_TAC[] THEN MATCH_ACCEPT_TAC PAIR_SET_SYM;
        ARITH_TAC;
        ASM_ARITH_TAC]]]);;

let IN_CYCLIC_SPLIT_RIGHT_BOUNDARY_EDGES = prove
 (`!q:num->A. !n j e.
        j + 2 < n
        ==> (e IN cyclic_split_right_boundary_edges q n j <=>
             ?k. j <= k /\ k + 1 < n /\
                 e = {q k,q(k + 1)})`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "bound") THEN
  REWRITE_TAC
   [cyclic_split_right_boundary_edges; IN_IMAGE; IN_NUMSEG] THEN
  EQ_TAC THENL
   [INTRO_TAC "@i. edge i_nonnegative i_bound" THEN
    EXISTS_TAC `(j + i):num` THEN REPEAT CONJ_TAC THENL
     [ARITH_TAC;
      ASM_ARITH_TAC;
      USE_THEN "edge" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[cyclic_split_right; ADD_ASSOC]];
    INTRO_TAC "@k. j_le k_bound edge" THEN
    EXISTS_TAC `(k - j):num` THEN REPEAT CONJ_TAC THENL
      [USE_THEN "edge" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[cyclic_split_right] THEN
      SUBGOAL_THEN
       `j + (k - j) = k /\ j + (k - j + 1) = k + 1`
      STRIP_ASSUME_TAC THENL
       [ASM_ARITH_TAC;
        ASM_REWRITE_TAC[]];
      ARITH_TAC;
      ASM_ARITH_TAC]]);;

let CYCLIC_SPLIT_BOUNDARY_EDGES_UNION = prove
 (`!q:num->A. !n j.
        0 < j /\ j + 2 < n
        ==> cyclic_split_left_boundary_edges q n j UNION
            cyclic_split_right_boundary_edges q n j =
            cyclic_edges q n`,
  REPEAT GEN_TAC THEN INTRO_TAC "jpositive bound" THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `e:A->bool` THEN
  ASM_SIMP_TAC
   [IN_UNION; IN_CYCLIC_SPLIT_LEFT_BOUNDARY_EDGES;
    IN_CYCLIC_SPLIT_RIGHT_BOUNDARY_EDGES; IN_CYCLIC_EDGES] THEN
  EQ_TAC THENL
   [DISCH_THEN(DISJ_CASES_THEN2
     (DISJ_CASES_THEN2 (LABEL_TAC "closing")
      (X_CHOOSE_THEN `k:num`
       (CONJUNCTS_THEN2 (LABEL_TAC "k_bound")
        (LABEL_TAC "edge"))))
     (X_CHOOSE_THEN `k:num`
      (CONJUNCTS_THEN2 (LABEL_TAC "j_le")
       (CONJUNCTS_THEN2 (LABEL_TAC "k_bound")
        (LABEL_TAC "edge"))))) THENL
     [EXISTS_TAC `n - 1` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        USE_THEN "closing" (fun th -> REWRITE_TAC[th]) THEN
        SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
         [ASM_ARITH_TAC;
          REWRITE_TAC[MOD_REFL]]];
      EXISTS_TAC `k:num` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `(k + 1) MOD n = k + 1`
        (LABEL_TAC "next") THENL
         [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
          ASM_REWRITE_TAC[]]];
      EXISTS_TAC `k:num` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `(k + 1) MOD n = k + 1`
        (LABEL_TAC "next") THENL
         [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
          ASM_REWRITE_TAC[]]]];
    INTRO_TAC "@i. i_bound edge" THEN
    ASM_CASES_TAC `(i:num) = n - 1` THENL
     [DISJ1_TAC THEN DISJ1_TAC THEN
      USE_THEN "edge" (fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[MOD_REFL]];
      SUBGOAL_THEN `i + 1 < n` (LABEL_TAC "successor") THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(i + 1) MOD n = i + 1`
      (LABEL_TAC "next") THENL
       [MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      ASM_CASES_TAC `(i:num) < j` THENL
       [DISJ1_TAC THEN DISJ2_TAC THEN EXISTS_TAC `i:num` THEN
        ASM_REWRITE_TAC[];
        DISJ2_TAC THEN EXISTS_TAC `i:num` THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]]]);;

let CYCLIC_SPLIT_BOUNDARY_EDGES_DISJOINT = prove
 (`!E:(A->bool)->bool. !q:num->A. !n j.
        simple_graph_cycle E q n /\ 0 < j /\ j + 2 < n
        ==> cyclic_split_left_boundary_edges q n j INTER
            cyclic_split_right_boundary_edges q n j = {}`,
  REPEAT GEN_TAC THEN INTRO_TAC "cycle jpositive bound" THEN
  REWRITE_TAC[EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  X_GEN_TAC `e:A->bool` THEN
  ASM_SIMP_TAC
   [IN_CYCLIC_SPLIT_LEFT_BOUNDARY_EDGES;
    IN_CYCLIC_SPLIT_RIGHT_BOUNDARY_EDGES] THEN
  DISCH_THEN(CONJUNCTS_THEN2
   (DISJ_CASES_THEN2 (LABEL_TAC "closing")
    (X_CHOOSE_THEN `k:num`
     (CONJUNCTS_THEN2 (LABEL_TAC "k_bound")
      (LABEL_TAC "left_edge"))))
   (X_CHOOSE_THEN `l:num`
    (CONJUNCTS_THEN2 (LABEL_TAC "j_le_l")
     (CONJUNCTS_THEN2 (LABEL_TAC "l_bound")
      (LABEL_TAC "right_edge"))))) THENL
   [SUBGOAL_THEN
     `~({(q:num->A) l,q(l + 1)} = {q(n - 1),q 0})`
    (LABEL_TAC "distinct") THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `l:num`]
       SIMPLE_GRAPH_CYCLE_CHAIN_EDGE_NE_CLOSING) THEN
      ASM_REWRITE_TAC[];
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["closing"; "right_edge"; "distinct"] THEN SET_TAC[]];
    SUBGOAL_THEN
     `~({(q:num->A) k,q(k + 1)} = {q l,q(l + 1)})`
    (LABEL_TAC "distinct") THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `k:num`; `l:num`]
       SIMPLE_GRAPH_CYCLE_CHAIN_EDGES_DISTINCT) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["left_edge"; "right_edge"; "distinct"] THEN SET_TAC[]]]);;

let UNIONS_CYCLIC_SPLIT_LEFT_BOUNDARY_EDGES = prove
 (`!q:num->A. !n j.
        0 < j
        ==> UNIONS(cyclic_split_left_boundary_edges q n j) =
            IMAGE q (0..j) UNION {q(n - 1)}`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "jpositive") THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `x:A` THEN EQ_TAC THENL
   [REWRITE_TAC[IN_UNIONS] THEN
    INTRO_TAC "@e. e_left x_e" THEN
    REMOVE_THEN "e_left" MP_TAC THEN
    ASM_SIMP_TAC[IN_CYCLIC_SPLIT_LEFT_BOUNDARY_EDGES] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "closing")
     (X_CHOOSE_THEN `k:num`
      (CONJUNCTS_THEN2 (LABEL_TAC "k_bound")
       (LABEL_TAC "edge")))) THENL
     [USE_THEN "closing" SUBST_ALL_TAC THEN
      USE_THEN "x_e" MP_TAC THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "x_last")
       (LABEL_TAC "x_zero")) THENL
       [REWRITE_TAC[IN_UNION; IN_SING] THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
        REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `0` THEN
        ASM_REWRITE_TAC[IN_NUMSEG] THEN ARITH_TAC];
      USE_THEN "edge" SUBST_ALL_TAC THEN
      USE_THEN "x_e" MP_TAC THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "x_first")
       (LABEL_TAC "x_second")) THEN
      REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
      REWRITE_TAC[IN_IMAGE] THENL
       [EXISTS_TAC `k:num` THEN
        ASM_REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC;
        EXISTS_TAC `k + 1` THEN
        ASM_REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC]];
    REWRITE_TAC[IN_UNION; IN_IMAGE; IN_NUMSEG; IN_SING] THEN
    DISCH_THEN(DISJ_CASES_THEN2
     (X_CHOOSE_THEN `i:num`
      (CONJUNCTS_THEN2 (LABEL_TAC "x_eq")
       (CONJUNCTS_THEN2 (LABEL_TAC "i_nonnegative")
        (LABEL_TAC "i_bound"))))
     (LABEL_TAC "x_last")) THENL
     [ASM_CASES_TAC `(i:num) < j` THENL
       [REWRITE_TAC[IN_UNIONS] THEN
        EXISTS_TAC `{(q:num->A) i,q(i + 1)}` THEN CONJ_TAC THENL
         [ASM_SIMP_TAC[IN_CYCLIC_SPLIT_LEFT_BOUNDARY_EDGES] THEN
          DISJ2_TAC THEN EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[];
          ASM_REWRITE_TAC[IN_INSERT]];
        SUBGOAL_THEN `(i:num) = j` SUBST_ALL_TAC THENL
         [ASM_ARITH_TAC;
          REWRITE_TAC[IN_UNIONS] THEN
          EXISTS_TAC `{(q:num->A) (j - 1),q((j - 1) + 1)}` THEN
          CONJ_TAC THENL
           [ASM_SIMP_TAC[IN_CYCLIC_SPLIT_LEFT_BOUNDARY_EDGES] THEN
            DISJ2_TAC THEN EXISTS_TAC `j - 1` THEN
            ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
            SUBGOAL_THEN `(j - 1) + 1 = j` SUBST1_TAC THENL
             [ASM_ARITH_TAC;
              ASM_REWRITE_TAC[IN_INSERT; IN_SING]]]]];
      USE_THEN "x_last" SUBST1_TAC THEN REWRITE_TAC[IN_UNIONS] THEN
      EXISTS_TAC `{(q:num->A)(n - 1),q 0}` THEN CONJ_TAC THENL
       [ASM_SIMP_TAC[IN_CYCLIC_SPLIT_LEFT_BOUNDARY_EDGES];
        REWRITE_TAC[IN_INSERT]]]]);;

let UNIONS_CYCLIC_SPLIT_RIGHT_BOUNDARY_EDGES = prove
 (`!q:num->A. !n j.
        j + 2 < n
        ==> UNIONS(cyclic_split_right_boundary_edges q n j) =
            IMAGE q (j..n - 1)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "bound") THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `x:A` THEN EQ_TAC THENL
   [REWRITE_TAC[IN_UNIONS] THEN
    INTRO_TAC "@e. e_right x_e" THEN
    REMOVE_THEN "e_right" MP_TAC THEN
    ASM_SIMP_TAC[IN_CYCLIC_SPLIT_RIGHT_BOUNDARY_EDGES] THEN
    INTRO_TAC "@k. j_le k_bound edge" THEN
    USE_THEN "edge" SUBST_ALL_TAC THEN
    USE_THEN "x_e" MP_TAC THEN
    REWRITE_TAC[IN_INSERT; IN_SING] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "x_first")
     (LABEL_TAC "x_second")) THEN
    REWRITE_TAC[IN_IMAGE] THENL
     [EXISTS_TAC `k:num` THEN
      ASM_REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC;
      EXISTS_TAC `k + 1` THEN
      ASM_REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC];
    REWRITE_TAC[IN_IMAGE; IN_NUMSEG] THEN
    INTRO_TAC "@i. x_eq j_le i_bound" THEN
    ASM_CASES_TAC `i + 1 < n` THENL
     [REWRITE_TAC[IN_UNIONS] THEN
      EXISTS_TAC `{(q:num->A) i,q(i + 1)}` THEN CONJ_TAC THENL
       [ASM_SIMP_TAC[IN_CYCLIC_SPLIT_RIGHT_BOUNDARY_EDGES] THEN
        EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[IN_INSERT]];
      SUBGOAL_THEN `(i:num) = n - 1` SUBST_ALL_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[IN_UNIONS] THEN
        EXISTS_TAC `{(q:num->A) (n - 2),q((n - 2) + 1)}` THEN
        CONJ_TAC THENL
         [ASM_SIMP_TAC[IN_CYCLIC_SPLIT_RIGHT_BOUNDARY_EDGES] THEN
          EXISTS_TAC `n - 2` THEN REPEAT CONJ_TAC THEN
          ASM_ARITH_TAC;
          SUBGOAL_THEN `(n - 2) + 1 = n - 1` SUBST1_TAC THENL
           [ASM_ARITH_TAC;
            ASM_REWRITE_TAC[IN_INSERT; IN_SING]]]]]]);;

let UNIONS_CYCLIC_SPLIT_BOUNDARY_EDGES_INTER = prove
 (`!E:(A->bool)->bool. !q:num->A. !n j.
        simple_graph_cycle E q n /\ 0 < j /\ j + 2 < n
        ==> UNIONS(cyclic_split_left_boundary_edges q n j) INTER
            UNIONS(cyclic_split_right_boundary_edges q n j) =
            {q j,q(n - 1)}`,
  REPEAT GEN_TAC THEN INTRO_TAC "cycle jpositive bound" THEN
  SUBGOAL_THEN
   `!i k. i < n /\ k < n /\ (q:num->A) i = q k ==> i = k`
  (LABEL_TAC "index_injective") THENL
   [USE_THEN "cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN
    INTRO_TAC "_ injective _" THEN
    USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_CYCLIC_INDICES; IN_UNIV] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`q:num->A`; `n:num`; `j:num`]
   UNIONS_CYCLIC_SPLIT_LEFT_BOUNDARY_EDGES) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "left_vertices") THEN
  MP_TAC(SPECL [`q:num->A`; `n:num`; `j:num`]
   UNIONS_CYCLIC_SPLIT_RIGHT_BOUNDARY_EDGES) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "right_vertices") THEN
  USE_THEN "left_vertices" SUBST1_TAC THEN
  USE_THEN "right_vertices" SUBST1_TAC THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INTER; IN_UNION; IN_IMAGE; IN_NUMSEG;
                IN_INSERT; IN_SING] THEN
    X_GEN_TAC `x:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2
     (DISJ_CASES_THEN2
      (X_CHOOSE_THEN `i:num`
       (CONJUNCTS_THEN2 (LABEL_TAC "x_i")
        (CONJUNCTS_THEN2 (LABEL_TAC "i_nonnegative")
         (LABEL_TAC "i_bound"))))
      (LABEL_TAC "x_last"))
     (X_CHOOSE_THEN `k:num`
      (CONJUNCTS_THEN2 (LABEL_TAC "x_k")
       (CONJUNCTS_THEN2 (LABEL_TAC "j_le_k")
        (LABEL_TAC "k_bound"))))) THENL
     [SUBGOAL_THEN `(i:num) = k` (LABEL_TAC "indices_equal") THENL
       [USE_THEN "index_injective" MATCH_MP_TAC THEN
        REPEAT CONJ_TAC THENL
         [ASM_ARITH_TAC;
          ASM_ARITH_TAC;
          ASM_MESON_TAC[]];
        SUBGOAL_THEN `(i:num) = j` SUBST_ALL_TAC THENL
         [ASM_ARITH_TAC;
          ASM_REWRITE_TAC[]]];
      ASM_REWRITE_TAC[]];
    REWRITE_TAC[SUBSET; IN_INSERT; IN_SING] THEN
    X_GEN_TAC `x:A` THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
    REWRITE_TAC[IN_INTER] THEN CONJ_TAC THENL
     [REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `j:num` THEN
      REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC;
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `j:num` THEN
      REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC;
      REWRITE_TAC[IN_UNION; IN_SING];
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `n - 1` THEN
      REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC]]);;
let PLANE_GRAPH_EMBEDDING_CHORD_BOUNDARY_ARCS = prove
 (`!V E p c q n j.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        simple_graph_cycle E q n /\
        0 < j /\ j + 2 < n /\ {q j,q(n - 1)} IN E
        ==> ?a b:real^1->real^2.
              arc a /\
              pathstart a = p(q j) /\
              pathfinish a = p(q(n - 1)) /\
              path_image a =
                UNIONS(IMAGE c
                 (cyclic_split_left_boundary_edges q n j)) /\
              arc b /\
              pathstart b = p(q j) /\
              pathfinish b = p(q(n - 1)) /\
              path_image b =
                UNIONS(IMAGE c
                 (cyclic_split_right_boundary_edges q n j)) /\
              path_image a INTER path_image b =
                {p(q j),p(q(n - 1))} /\
              path_image a UNION path_image b =
                UNIONS(IMAGE c (cyclic_edges q n))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding cycle jpositive bound chord" THEN
  SUBGOAL_THEN
   `simple_graph_cycle E
     (cyclic_split_left_oriented (q:num->A) n j) (j + 2)`
  (LABEL_TAC "left_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_SPLIT_LEFT_ORIENTED THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle E (cyclic_split_right (q:num->A) j) (n - j)`
  (LABEL_TAC "right_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_SPLIT_RIGHT THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`;
    `cyclic_split_left_oriented (q:num->A) n j`; `j + 2`]
   PLANE_GRAPH_EMBEDDING_CYCLE_PREFIX_ARC) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `j:num`) THEN
  ANTS_TAC THENL
   [ARITH_TAC;
    INTRO_TAC "@a. a_arc a_image a_start a_finish"] THEN
  SUBGOAL_THEN
   `path_image(a:real^1->real^2) =
    UNIONS(IMAGE (c:(A->bool)->real^2->bool)
     (cyclic_split_left_boundary_edges (q:num->A) n j))`
  (LABEL_TAC "left_image") THENL
   [USE_THEN "a_image" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[cyclic_split_left_boundary_edges] THEN
    ONCE_REWRITE_TAC[GSYM IMAGE_o] THEN REWRITE_TAC[o_DEF];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `pathstart(a:real^1->real^2) = (p:A->real^2)((q:num->A) j)`
  (LABEL_TAC "left_start") THENL
   [ASM_REWRITE_TAC[cyclic_split_left_oriented; LE_0; SUB_0];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `pathfinish(a:real^1->real^2) =
    (p:A->real^2)((q:num->A)(n - 1))`
  (LABEL_TAC "left_finish") THENL
   [ASM_REWRITE_TAC[cyclic_split_left_oriented;
                    ARITH_RULE `~((j:num) + 1 <= j)`];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`;
    `cyclic_split_right (q:num->A) j`; `(n:num) - j`]
   PLANE_GRAPH_EMBEDDING_CYCLE_PREFIX_ARC) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `(n:num) - j - 2`) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    INTRO_TAC "@b. b_arc b_image b_start b_finish"] THEN
  SUBGOAL_THEN
   `path_image(b:real^1->real^2) =
    UNIONS(IMAGE (c:(A->bool)->real^2->bool)
     (cyclic_split_right_boundary_edges (q:num->A) n j))`
  (LABEL_TAC "right_image") THENL
   [USE_THEN "b_image" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[cyclic_split_right_boundary_edges] THEN
    ONCE_REWRITE_TAC[GSYM IMAGE_o] THEN REWRITE_TAC[o_DEF];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `pathstart(b:real^1->real^2) = (p:A->real^2)((q:num->A) j)`
  (LABEL_TAC "right_start") THENL
   [ASM_REWRITE_TAC[cyclic_split_right; ADD_CLAUSES];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `pathfinish(b:real^1->real^2) =
    (p:A->real^2)((q:num->A)(n - 1))`
  (LABEL_TAC "right_finish") THENL
   [SUBGOAL_THEN `j + ((n:num) - j - 2 + 1) = n - 1`
    (LABEL_TAC "last_index") THENL
     [ASM_ARITH_TAC;
      ASM_REWRITE_TAC[cyclic_split_right]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_split_left_boundary_edges (q:num->A) n j UNION
    cyclic_split_right_boundary_edges q n j = cyclic_edges q n`
  (LABEL_TAC "edge_union") THENL
   [MATCH_MP_TAC CYCLIC_SPLIT_BOUNDARY_EDGES_UNION THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_split_left_boundary_edges (q:num->A) n j INTER
    cyclic_split_right_boundary_edges q n j = {}`
  (LABEL_TAC "edge_disjoint") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `j:num`]
     CYCLIC_SPLIT_BOUNDARY_EDGES_DISJOINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_split_left_boundary_edges (q:num->A) n j SUBSET E /\
    cyclic_split_right_boundary_edges q n j SUBSET E`
  (CONJUNCTS_THEN2 (LABEL_TAC "left_edges")
                    (LABEL_TAC "right_edges")) THENL
   [SUBGOAL_THEN `cyclic_edges (q:num->A) n SUBSET E`
    (LABEL_TAC "cycle_edges") THENL
     [USE_THEN "cycle" MP_TAC THEN
      REWRITE_TAC[simple_graph_cycle] THEN MESON_TAC[];
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["edge_union"; "cycle_edges"] THEN SET_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`;
    `cyclic_split_left_boundary_edges (q:num->A) n j`;
    `cyclic_split_right_boundary_edges (q:num->A) n j`]
   PLANE_GRAPH_EMBEDDING_EDGE_UNIONS_INTER) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "carrier_inter") THEN
  SUBGOAL_THEN
   `UNIONS(cyclic_split_left_boundary_edges (q:num->A) n j) INTER
    UNIONS(cyclic_split_right_boundary_edges q n j) =
    {q j,q(n - 1)}`
  (LABEL_TAC "endpoint_inter") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `j:num`]
     UNIONS_CYCLIC_SPLIT_BOUNDARY_EDGES_INTER) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `UNIONS(IMAGE c
     (cyclic_split_left_boundary_edges (q:num->A) n j)) INTER
    UNIONS(IMAGE c
     (cyclic_split_right_boundary_edges q n j)) =
    {(p:A->real^2)(q j),p(q(n - 1))}`
  (LABEL_TAC "arc_inter") THENL
   [USE_THEN "carrier_inter" (fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[IMAGE_CLAUSES];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `UNIONS(IMAGE (c:(A->bool)->real^2->bool)
     (cyclic_split_left_boundary_edges (q:num->A) n j)) UNION
    UNIONS(IMAGE c
     (cyclic_split_right_boundary_edges q n j)) =
    UNIONS(IMAGE c (cyclic_edges q n))`
  (LABEL_TAC "carrier_union") THENL
   [USE_THEN "edge_union" (fun th -> REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[IMAGE_UNION; UNIONS_UNION];
    ALL_TAC] THEN
  MAP_EVERY (fun name -> REMOVE_THEN name (K ALL_TAC))
   ["a_image"; "a_start"; "a_finish";
    "b_image"; "b_start"; "b_finish"] THEN
  MAP_EVERY EXISTS_TAC
   [`a:real^1->real^2`; `b:real^1->real^2`] THEN
  ASM_REWRITE_TAC[IMAGE_CLAUSES]);;
let UNBOUNDED_CONNECTED_FRONTIER_AVOIDS_JORDAN_INSIDE = prove
 (`!g:real^1->real^2. !k x.
        simple_path g /\ pathfinish g = pathstart g /\
        connected k /\ ~bounded k /\
        k SUBSET (:real^2) DIFF path_image g /\
        x IN frontier k
        ==> ~(x IN inside(path_image g))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "simple closed connected unbounded subset x_frontier" THEN
  MP_TAC(ISPEC `g:real^1->real^2` JORDAN_INSIDE_OUTSIDE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "inside_nonempty inside_open inside_connected outside_nonempty \
    outside_open outside_connected inside_bounded outside_unbounded \
    sides_disjoint sides_union inside_frontier outside_frontier" THEN
  DISCH_THEN(LABEL_TAC "x_inside") THEN
  SUBGOAL_THEN
   `inside(path_image g) IN
    components((:real^2) DIFF path_image g)`
  (LABEL_TAC "inside_component") THENL
   [MP_TAC(ISPEC `g:real^1->real^2` JORDAN_COMPONENTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th; IN_INSERT]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(inside(path_image g) INTER (k:real^2->bool) = {})`
  (LABEL_TAC "meets_inside") THENL
   [MP_TAC(ISPECL
     [`inside(path_image g):real^2->bool`; `k:real^2->bool`]
     OPEN_INTER_CLOSURE_EQ_EMPTY) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "closure_equiv") THEN
    SUBGOAL_THEN `(x:real^2) IN closure k`
    (LABEL_TAC "x_closure") THENL
     [USE_THEN "x_frontier" MP_TAC THEN
      REWRITE_TAC[frontier; IN_DIFF] THEN MESON_TAC[];
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["x_inside"; "x_closure"; "closure_equiv"] THEN SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(k:real^2->bool) SUBSET inside(path_image g)`
  (LABEL_TAC "k_inside") THENL
   [MATCH_MP_TAC(ISPECL
     [`(:real^2) DIFF path_image(g:real^1->real^2)`;
      `k:real^2->bool`; `inside(path_image g):real^2->bool`]
     COMPONENTS_MAXIMAL) THEN
    ASM_REWRITE_TAC[];
    ASM_MESON_TAC[BOUNDED_SUBSET]]);;

let UNBOUNDED_CONNECTED_FRONTIER_AVOIDS_TWO_ARC_INSIDE = prove
 (`!a b:real^1->real^2. !u v k x.
        arc a /\ pathstart a = u /\ pathfinish a = v /\
        arc b /\ pathstart b = u /\ pathfinish b = v /\
        path_image a INTER path_image b = {u,v} /\
        connected k /\ ~bounded k /\
        k SUBSET (:real^2) DIFF
          (path_image a UNION path_image b) /\
        x IN frontier k
        ==> ~(x IN inside(path_image a UNION path_image b))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "a_arc a_start a_finish b_arc b_start b_finish intersection \
    connected unbounded subset x_frontier" THEN
  MP_TAC(ISPECL
   [`(a:real^1->real^2) ++ reversepath(b:real^1->real^2)`;
    `k:real^2->bool`; `x:real^2`]
   UNBOUNDED_CONNECTED_FRONTIER_AVOIDS_JORDAN_INSIDE) THEN
  ASM_SIMP_TAC
   [PATHSTART_JOIN; PATHFINISH_JOIN; PATHSTART_REVERSEPATH;
    PATHFINISH_REVERSEPATH; SIMPLE_PATH_JOIN_LOOP_EQ;
    ARC_REVERSEPATH_EQ; PATH_IMAGE_JOIN; PATH_IMAGE_REVERSEPATH;
    SUBSET_REFL]);;

let PLANE_TRIANGULATED_DISK_CHORD_INTER_INSIDE = prove
 (`!V E p c q n outer j.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        ~bounded outer /\
        0 < j /\ j + 2 < n /\ {q j,q(n - 1)} IN E
        ==> ~(c {q j,q(n - 1)} INTER
              inside(UNIONS(IMAGE c (cyclic_edges q n))) = {})`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "disk outer_unbounded jpositive bound chord" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding large q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN `simple_graph_cycle (E:(A->bool)->bool) q n`
  (LABEL_TAC "cycle") THENL
   [REWRITE_TAC[simple_graph_cycle] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i k. i < n /\ k < n /\
          (p:A->real^2)((q:num->A) i) = p(q k)
          ==> i = k`
  (LABEL_TAC "point_index_injective") THENL
   [MAP_EVERY X_GEN_TAC [`i:num`; `k:num`] THEN
    INTRO_TAC "i_bound k_bound points_equal" THEN
    SUBGOAL_THEN
     `(q:num->A) i IN V /\ (q:num->A) k IN V`
    (CONJUNCTS_THEN2 (LABEL_TAC "qi_vertex")
                     (LABEL_TAC "qk_vertex")) THENL
     [CONJ_TAC THEN
      USE_THEN "boundary_subset"
       (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      REWRITE_TAC[IN_CYCLIC_VERTICES] THENL
