let PLANE_GRAPH_EMBEDDING_CHORD_EXPLICIT_THETA = prove
 (`!V E p c q n j.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        simple_graph_cycle E q n /\
        0 < j /\ j + 2 < n /\
        {q j,q(n - 1)} IN E
        ==> ?a b d:real^1->real^2.
              ~(p(q j) = p(q(n - 1))) /\
              arc a /\
              pathstart a = p(q j) /\
              pathfinish a = p(q(n - 1)) /\
              path_image a =
                UNIONS
                 (IMAGE c (cyclic_split_left_boundary_edges q n j)) /\
              arc b /\
              pathstart b = p(q j) /\
              pathfinish b = p(q(n - 1)) /\
              path_image b =
                UNIONS
                 (IMAGE c (cyclic_split_right_boundary_edges q n j)) /\
              arc d /\
              pathstart d = p(q j) /\
              pathfinish d = p(q(n - 1)) /\
              path_image d = c {q j,q(n - 1)} /\
              path_image a INTER path_image b =
                {p(q j),p(q(n - 1))} /\
              path_image a INTER path_image d =
                {p(q j),p(q(n - 1))} /\
              path_image b INTER path_image d =
                {p(q j),p(q(n - 1))} /\
              path_image a UNION path_image b =
                UNIONS(IMAGE c (cyclic_edges q n))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding cycle jpositive bound chord" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`; `j:num`]
   PLANE_GRAPH_EMBEDDING_CHORD_BOUNDARY_ARCS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:real^1->real^2`
   (X_CHOOSE_THEN `b:real^1->real^2` MP_TAC)) THEN
  INTRO_TAC
   "a_arc a_start a_finish a_image b_arc b_start b_finish b_image \
    ab_inter boundary_union" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `(q:num->A) j`;
    `(q:num->A)(n - 1)`]
   PLANE_GRAPH_EMBEDDING_DART_PATH) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    INTRO_TAC "@d. d_arc d_image d_start d_finish"] THEN
  SUBGOAL_THEN `~((p:A->real^2)(q j) = p(q(n - 1)))`
  (LABEL_TAC "points_distinct") THENL
   [MP_TAC(MATCH_MP ARC_DISTINCT_ENDS
     (ASSUME `arc(d:real^1->real^2)`)) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`; `j:num`]
   PLANE_GRAPH_EMBEDDING_CHORD_INTER_CYCLE_CARRIER) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "chord_boundary_inter") THEN
  SUBGOAL_THEN
   `path_image(d:real^1->real^2) INTER
    (path_image a UNION path_image b) =
    {(p:A->real^2)(q j),p(q(n - 1))}`
  (LABEL_TAC "d_boundary_inter") THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `path_image(a:real^1->real^2) INTER path_image d =
