let PLANE_TRIANGULATED_DISK_CHORD_EXPLICIT_SPLIT = prove
 (`!V E p c q n outer j.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        ~bounded outer /\
        0 < j /\ j + 2 < n /\ {q j,q(n - 1)} IN E
        ==> ?a b d:real^1->real^2.
              arc a /\
              pathstart a = p(q j) /\
              pathfinish a = p(q(n - 1)) /\
              path_image a =
                UNIONS
                 (IMAGE c (cyclic_split_left_boundary_edges q n j)) /\
              arc b /\
              pathstart b = p(q j) /\
              pathfinish b = p(q(n - 1)) /\
              path_image b =
                UNIONS
                 (IMAGE c (cyclic_split_right_boundary_edges q n j)) /\
              arc d /\
              pathstart d = p(q j) /\
              pathfinish d = p(q(n - 1)) /\
              path_image d = c {q j,q(n - 1)} /\
              path_image a INTER path_image b =
                {p(q j),p(q(n - 1))} /\
              path_image a INTER path_image d =
                {p(q j),p(q(n - 1))} /\
              path_image b INTER path_image d =
                {p(q j),p(q(n - 1))} /\
              path_image a UNION path_image b =
                UNIONS(IMAGE c (cyclic_edges q n)) /\
              inside(path_image a UNION path_image d) INTER
              inside(path_image b UNION path_image d) = {} /\
              inside(path_image a UNION path_image d) UNION
              inside(path_image b UNION path_image d) UNION
              path_image d DIFF {p(q j),p(q(n - 1))} =
                inside(UNIONS(IMAGE c (cyclic_edges q n)))`,
