  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:real^1->real^2`
   (X_CHOOSE_THEN `b:real^1->real^2`
    (X_CHOOSE_THEN `d:real^1->real^2` MP_TAC))) THEN
  INTRO_TAC
   "points_distinct a_arc a_start a_finish a_image \
    b_arc b_start b_finish b_image d_arc d_start d_finish d_image \
    ab_inter ad_inter bd_inter boundary_union" THEN
  SUBGOAL_THEN
   `~(path_image(d:real^1->real^2) INTER
      inside(path_image a UNION path_image b) = {})`
  (LABEL_TAC "crosses") THENL
   [USE_THEN "d_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "boundary_union" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `j:num`]
     PLANE_TRIANGULATED_DISK_CHORD_INTER_INSIDE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`a:real^1->real^2`; `b:real^1->real^2`;
    `d:real^1->real^2`;
    `(p:A->real^2)((q:num->A)(j:num))`;
    `(p:A->real^2)((q:num->A)(n - 1))`]
   SPLIT_INSIDE_SIMPLE_CLOSED_CURVE) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[ARC_IMP_SIMPLE_PATH];
    INTRO_TAC "sides_disjoint sides_union"] THEN
  MAP_EVERY EXISTS_TAC
   [`a:real^1->real^2`; `b:real^1->real^2`;
    `d:real^1->real^2`] THEN
  ASM_REWRITE_TAC[]);;
let CYCLIC_EDGES_CHAIN_AND_CLOSING = prove
 (`!r:num->A. !m.
        0 < m
        ==> cyclic_edges r (m + 1) =
            {r m,r 0} INSERT
            IMAGE (\i. {r i,r(i + 1)}) (0..m - 1)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "positive") THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `e:A->bool` THEN
  REWRITE_TAC[IN_CYCLIC_EDGES; IN_INSERT; IN_IMAGE; IN_NUMSEG] THEN
  EQ_TAC THENL
   [INTRO_TAC "@i. i_bound edge" THEN
    ASM_CASES_TAC `(i:num) < m` THENL
     [DISJ2_TAC THEN EXISTS_TAC `i:num` THEN
      SUBGOAL_THEN `(i + 1) MOD (m + 1) = i + 1`
      (LABEL_TAC "next") THENL
       [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
      DISJ1_TAC THEN
      SUBGOAL_THEN `(i:num) = m` SUBST_ALL_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `(m + 1) MOD (m + 1) = 0`
        SUBST1_TAC THENL
         [REWRITE_TAC[MOD_REFL];
          ASM_REWRITE_TAC[MOD_REFL]]]];
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "closing")
     (X_CHOOSE_THEN `i:num`
      (CONJUNCTS_THEN2 (LABEL_TAC "edge")
       (CONJUNCTS_THEN2 (LABEL_TAC "nonnegative")
                        (LABEL_TAC "i_bound"))))) THENL
     [EXISTS_TAC `m:num` THEN CONJ_TAC THENL
       [ARITH_TAC;
        SUBGOAL_THEN `(m + 1) MOD (m + 1) = 0`
        SUBST1_TAC THENL
         [REWRITE_TAC[MOD_REFL];
          ASM_REWRITE_TAC[MOD_REFL]]];
      EXISTS_TAC `i:num` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `(i + 1) MOD (m + 1) = i + 1`
        SUBST1_TAC THENL
         [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
          ASM_REWRITE_TAC[]]]]]);;

let CYCLIC_EDGES_SPLIT_LEFT_ORIENTED = prove
 (`!q:num->A. !n j.
        0 < j /\ j + 2 < n
        ==> cyclic_edges (cyclic_split_left_oriented q n j) (j + 2) =
            {q j,q(n - 1)} INSERT
            cyclic_split_left_boundary_edges q n j`,
  REPEAT GEN_TAC THEN INTRO_TAC "jpositive bound" THEN
  MP_TAC(ISPECL
   [`cyclic_split_left_oriented (q:num->A) n j`; `j + 1`]
  CYCLIC_EDGES_CHAIN_AND_CLOSING) THEN
  ANTS_TAC THENL
   [ARITH_TAC;
    DISCH_THEN(LABEL_TAC "edges")] THEN
  USE_THEN "edges" MP_TAC THEN
  REWRITE_TAC[ARITH_RULE `(j + 1) + 1 = j + 2`;
              ARITH_RULE `(j + 1) - 1 = j`;
              cyclic_split_left_boundary_edges] THEN
  REWRITE_TAC[cyclic_split_left_oriented; LE_REFL; LE_0;
              ARITH_RULE `~((j:num) + 1 <= j)`; SUB_REFL; SUB_0] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN
   `{(q:num->A)(n - 1),q j} = {q j,q(n - 1)}`
  SUBST1_TAC THENL
   [SET_TAC[];
    REFL_TAC]);;

let CYCLIC_EDGES_SPLIT_RIGHT_EXPLICIT = prove
 (`!q:num->A. !n j.
        j + 2 < n
        ==> cyclic_edges (cyclic_split_right q j) (n - j) =
            {q j,q(n - 1)} INSERT
            cyclic_split_right_boundary_edges q n j`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "bound") THEN
  MP_TAC(ISPECL
   [`cyclic_split_right (q:num->A) j`; `n - j - 1`]
   CYCLIC_EDGES_CHAIN_AND_CLOSING) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(LABEL_TAC "edges")] THEN
  SUBGOAL_THEN `(n - j - 1) + 1 = n - j`
  (LABEL_TAC "length") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(n - j - 1) - 1 = n - j - 2`
  (LABEL_TAC "last_chain") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `j + (n - j - 1) = n - 1`
  (LABEL_TAC "last") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "edges" MP_TAC THEN
  USE_THEN "length" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "last_chain" (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[cyclic_split_right_boundary_edges;
              cyclic_split_right; ADD_CLAUSES; ADD_ASSOC] THEN
  USE_THEN "last" (fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN
   `{(q:num->A)(n - 1),q j} = {q j,q(n - 1)}`
  SUBST1_TAC THENL
   [SET_TAC[];
    REFL_TAC]);;

let CYCLIC_VERTICES_SPLIT_LEFT_ORIENTED = prove
 (`!q:num->A. !n j.
        j + 2 < n
        ==> cyclic_vertices (cyclic_split_left_oriented q n j) (j + 2) =
            cyclic_vertices (cyclic_split_left q n j) (j + 2)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "bound") THEN
  REWRITE_TAC[EXTENSION; IN_CYCLIC_VERTICES] THEN
  X_GEN_TAC `x:A` THEN EQ_TAC THENL
   [INTRO_TAC "@i. i_bound point" THEN
    ASM_CASES_TAC `(i:num) <= j` THENL
     [EXISTS_TAC `j - i:num` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        USE_THEN "point" (fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[cyclic_split_left_oriented; cyclic_split_left] THEN
        SUBGOAL_THEN `j - i < j + 1` ASSUME_TAC THENL
         [ASM_ARITH_TAC;
          ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN ASM_ARITH_TAC]];
      SUBGOAL_THEN `(i:num) = j + 1` SUBST_ALL_TAC THENL
       [ASM_ARITH_TAC;
        EXISTS_TAC `j + 1` THEN
        ASM_REWRITE_TAC[cyclic_split_left_oriented; cyclic_split_left;
                        ARITH_RULE `~((j:num) + 1 <= j)`;
                        ARITH_RULE `~((j:num) + 1 < j + 1)`]]];
    INTRO_TAC "@i. i_bound point" THEN
    ASM_CASES_TAC `(i:num) < j + 1` THENL
     [EXISTS_TAC `j - i:num` THEN CONJ_TAC THENL
       [ASM_ARITH_TAC;
        USE_THEN "point" (fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[cyclic_split_left_oriented; cyclic_split_left] THEN
        SUBGOAL_THEN `(j - i:num) <= j` ASSUME_TAC THENL
         [ARITH_TAC;
          ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN ASM_ARITH_TAC]];
      SUBGOAL_THEN `(i:num) = j + 1` SUBST_ALL_TAC THENL
       [ASM_ARITH_TAC;
        EXISTS_TAC `j + 1` THEN
        ASM_REWRITE_TAC[cyclic_split_left_oriented; cyclic_split_left;
                        ARITH_RULE `~((j:num) + 1 <= j)`;
                        ARITH_RULE `~((j:num) + 1 < j + 1)`]]]]);;

let PLANE_GRAPH_EMBEDDING_CHORD_EXPLICIT_CYCLE_CARRIERS = prove
 (`!c q n j a b d.
        0 < j /\ j + 2 < n /\
        path_image(a:real^1->real^2) =
          UNIONS(IMAGE (c:(A->bool)->real^2->bool)
            (cyclic_split_left_boundary_edges q n j)) /\
        path_image(b:real^1->real^2) =
          UNIONS(IMAGE c (cyclic_split_right_boundary_edges q n j)) /\
        path_image(d:real^1->real^2) = c {q j,q(n - 1)}
        ==> path_image a UNION path_image d =
            UNIONS
             (IMAGE c
              (cyclic_edges
                (cyclic_split_left_oriented q n j) (j + 2))) /\
            path_image b UNION path_image d =
            UNIONS
             (IMAGE c
              (cyclic_edges (cyclic_split_right q j) (n - j)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "jpositive bound a_image b_image d_image" THEN
  MP_TAC(ISPECL [`q:num->A`; `n:num`; `j:num`]
   CYCLIC_EDGES_SPLIT_LEFT_ORIENTED) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "left_edges") THEN
  MP_TAC(ISPECL [`q:num->A`; `n:num`; `j:num`]
   CYCLIC_EDGES_SPLIT_RIGHT_EXPLICIT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "right_edges") THEN
  ASM_REWRITE_TAC[IMAGE_CLAUSES; UNIONS_INSERT] THEN SET_TAC[]);;
let THETA_SPLIT_CLOSED_SIDES = prove
 (`!a b d:real^1->real^2. !u v.
        ~(u = v) /\
        arc a /\ pathstart a = u /\ pathfinish a = v /\
        arc b /\ pathstart b = u /\ pathfinish b = v /\
        arc d /\ pathstart d = u /\ pathfinish d = v /\
        path_image a INTER path_image b = {u,v} /\
        path_image a INTER path_image d = {u,v} /\
        path_image b INTER path_image d = {u,v} /\
        ~(path_image d INTER
          inside(path_image a UNION path_image b) = {})
        ==> closure(inside(path_image a UNION path_image d)) INTER
            closure(inside(path_image b UNION path_image d)) =
            path_image d /\
            closure(inside(path_image a UNION path_image d)) UNION
            closure(inside(path_image b UNION path_image d)) =
            closure(inside(path_image a UNION path_image b))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "distinct a_arc a_start a_finish b_arc b_start b_finish \
    d_arc d_start d_finish ab_inter ad_inter bd_inter crosses" THEN
  MP_TAC(ISPECL
   [`a:real^1->real^2`; `b:real^1->real^2`;
    `d:real^1->real^2`; `u:real^2`; `v:real^2`]
   SPLIT_INSIDE_SIMPLE_CLOSED_CURVE) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[ARC_IMP_SIMPLE_PATH];
    INTRO_TAC "sides_disjoint sides_union"] THEN
  SUBGOAL_THEN
   `frontier(inside(path_image a UNION path_image d)) =
    path_image(a:real^1->real^2) UNION path_image d`
  (LABEL_TAC "left_frontier") THENL
   [MP_TAC(ISPEC
     `(a:real^1->real^2) ++ reversepath(d:real^1->real^2)`
     JORDAN_INSIDE_OUTSIDE) THEN
    ASM_SIMP_TAC
     [PATHSTART_JOIN; PATHFINISH_JOIN; PATHSTART_REVERSEPATH;
      PATHFINISH_REVERSEPATH; SIMPLE_PATH_JOIN_LOOP_EQ;
      ARC_REVERSEPATH_EQ; PATH_IMAGE_JOIN; PATH_IMAGE_REVERSEPATH;
      SUBSET_REFL] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `frontier(inside(path_image b UNION path_image d)) =
    path_image(b:real^1->real^2) UNION path_image d`
  (LABEL_TAC "right_frontier") THENL
   [MP_TAC(ISPEC
     `(b:real^1->real^2) ++ reversepath(d:real^1->real^2)`
     JORDAN_INSIDE_OUTSIDE) THEN
    ASM_SIMP_TAC
     [PATHSTART_JOIN; PATHFINISH_JOIN; PATHSTART_REVERSEPATH;
      PATHFINISH_REVERSEPATH; SIMPLE_PATH_JOIN_LOOP_EQ;
      ARC_REVERSEPATH_EQ; PATH_IMAGE_JOIN; PATH_IMAGE_REVERSEPATH;
      SUBSET_REFL] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `frontier(inside(path_image a UNION path_image b)) =
    path_image(a:real^1->real^2) UNION path_image b`
  (LABEL_TAC "outer_frontier") THENL
   [MP_TAC(ISPEC
     `(a:real^1->real^2) ++ reversepath(b:real^1->real^2)`
     JORDAN_INSIDE_OUTSIDE) THEN
    ASM_SIMP_TAC
     [PATHSTART_JOIN; PATHFINISH_JOIN; PATHSTART_REVERSEPATH;
      PATHFINISH_REVERSEPATH; SIMPLE_PATH_JOIN_LOOP_EQ;
      ARC_REVERSEPATH_EQ; PATH_IMAGE_JOIN; PATH_IMAGE_REVERSEPATH;
      SUBSET_REFL] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPEC
   `path_image(a:real^1->real^2) UNION path_image d`
   INSIDE_NO_OVERLAP) THEN
  MP_TAC(ISPEC
   `path_image(b:real^1->real^2) UNION path_image d`
   INSIDE_NO_OVERLAP) THEN
  MP_TAC(ISPEC
   `path_image(a:real^1->real^2) UNION path_image b`
   INSIDE_NO_OVERLAP) THEN
  ASM_REWRITE_TAC[CLOSURE_UNION_FRONTIER] THEN
  REPEAT STRIP_TAC THEN ASM SET_TAC[]);;

let plane_graph_closed_side_vertices = new_definition
 `plane_graph_closed_side_vertices
    (V:A->bool) (p:A->real^2) (s:real^2->bool) =
      {v | v IN V /\ p v IN closure(inside s)}`;;

let PLANE_GRAPH_CLOSED_SIDE_VERTICES_INTER = prove
 (`!V E p c e l r d.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e IN E /\
        path_image(d:real^1->real^2) = c e /\
        closure(inside(l:real^2->bool)) INTER closure(inside r) =
          path_image d
        ==> plane_graph_closed_side_vertices V p l INTER
            plane_graph_closed_side_vertices V p r = e`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding edge d_image closed_inter" THEN
  SUBGOAL_THEN `(e:A->bool) SUBSET V` (LABEL_TAC "edge_subset") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    INTRO_TAC "_ _ edge_data" THEN
    USE_THEN "edge_data" (MP_TAC o SPEC `e:A->bool`) THEN
    ANTS_TAC THENL
     [USE_THEN "edge" ACCEPT_TAC;
      DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC))];
    ALL_TAC] THEN
  USE_THEN "embedding" MP_TAC THEN
  REWRITE_TAC[plane_graph_embedding] THEN
  INTRO_TAC "p_injective _ edge_vertices _" THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) e INTER IMAGE p V = IMAGE p e`
  (LABEL_TAC "edge_vertex_inter") THENL
   [USE_THEN "edge_vertices" MATCH_MP_TAC THEN
    USE_THEN "edge" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[EXTENSION; IN_INTER; plane_graph_closed_side_vertices;
              IN_ELIM_THM] THEN
  X_GEN_TAC `x:A` THEN EQ_TAC THENL
   [INTRO_TAC "(x_vertex x_left) (_ x_right)" THEN
    SUBGOAL_THEN `(p:A->real^2) x IN path_image d`
    (LABEL_TAC "x_d") THENL
     [USE_THEN "closed_inter" (fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[IN_INTER];
      ALL_TAC] THEN
    SUBGOAL_THEN `(p:A->real^2) x IN IMAGE p e`
    (LABEL_TAC "x_edge_image") THENL
     [USE_THEN "edge_vertex_inter" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[IN_INTER] THEN CONJ_TAC THENL
       [USE_THEN "d_image" (fun th -> REWRITE_TAC[GSYM th]) THEN
        USE_THEN "x_d" ACCEPT_TAC;
        REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `x:A` THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    USE_THEN "x_edge_image" MP_TAC THEN
    REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@y. point y_edge" THEN
    SUBGOAL_THEN `(y:A) IN V` (LABEL_TAC "y_vertex") THENL
     [USE_THEN "edge_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "y_edge" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "p_injective" MP_TAC THEN REWRITE_TAC[INJ; IN_UNIV] THEN
    DISCH_THEN(MP_TAC o SPECL [`x:A`; `y:A`]) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN SUBST1_TAC THEN USE_THEN "y_edge" ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "x_edge") THEN
    SUBGOAL_THEN `(x:A) IN V` (LABEL_TAC "x_vertex") THENL
     [USE_THEN "edge_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "x_edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(p:A->real^2) x IN path_image d`
    (LABEL_TAC "x_d") THENL
     [USE_THEN "d_image" (fun th -> REWRITE_TAC[th]) THEN
      SUBGOAL_THEN
       `(p:A->real^2) x IN
        (c:(A->bool)->real^2->bool) (e:A->bool) INTER IMAGE p V`
      MP_TAC THENL
       [USE_THEN "edge_vertex_inter" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `x:A` THEN
        ASM_REWRITE_TAC[];
        REWRITE_TAC[IN_INTER] THEN
        DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC))];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(p:A->real^2) x IN
      closure(inside l) INTER closure(inside r)`
    (LABEL_TAC "x_closed") THENL
     [USE_THEN "closed_inter" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "x_d" ACCEPT_TAC;
      USE_THEN "x_closed" MP_TAC THEN
      REWRITE_TAC[IN_INTER] THEN ASM_REWRITE_TAC[]]]);;

let PLANE_GRAPH_CLOSED_SIDE_VERTICES_UNION = prove
 (`!V p l r.
        IMAGE (p:A->real^2) V SUBSET
          closure(inside(l:real^2->bool)) UNION closure(inside r)
        ==> plane_graph_closed_side_vertices V p l UNION
            plane_graph_closed_side_vertices V p r = V`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[SUBSET; EXTENSION; IN_IMAGE; IN_UNION;
              plane_graph_closed_side_vertices; IN_ELIM_THM] THEN
  MESON_TAC[]);;

let PLANE_GRAPH_THETA_CLOSED_SIDE_VERTICES = prove
 (`!V E p c e a b d u v.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e IN E /\
        ~(u = v) /\
        arc a /\ pathstart a = u /\ pathfinish a = v /\
        arc b /\ pathstart b = u /\ pathfinish b = v /\
        arc d /\ pathstart d = u /\ pathfinish d = v /\
        path_image a INTER path_image b = {u,v} /\
        path_image a INTER path_image d = {u,v} /\
        path_image b INTER path_image d = {u,v} /\
        path_image d = c e /\
        ~(path_image d INTER
          inside(path_image a UNION path_image b) = {})
        ==> closure(inside(path_image a UNION path_image d)) INTER
            closure(inside(path_image b UNION path_image d)) =
            path_image d /\
            closure(inside(path_image a UNION path_image d)) UNION
            closure(inside(path_image b UNION path_image d)) =
            closure(inside(path_image a UNION path_image b)) /\
            plane_graph_closed_side_vertices
              V p (path_image a UNION path_image d) INTER
            plane_graph_closed_side_vertices
              V p (path_image b UNION path_image d) = e`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding edge distinct \
    a_arc a_start a_finish b_arc b_start b_finish \
    d_arc d_start d_finish ab_inter ad_inter bd_inter d_image crosses" THEN
  MP_TAC(ISPECL
   [`a:real^1->real^2`; `b:real^1->real^2`;
    `d:real^1->real^2`; `u:real^2`; `v:real^2`]
   THETA_SPLIT_CLOSED_SIDES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "closed_inter closed_union" THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "closed_inter" ACCEPT_TAC;
    USE_THEN "closed_union" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`;
      `path_image(a:real^1->real^2) UNION
       (c:(A->bool)->real^2->bool) (e:A->bool)`;
      `path_image(b:real^1->real^2) UNION c e`;
      `d:real^1->real^2`]
     PLANE_GRAPH_CLOSED_SIDE_VERTICES_INTER) THEN
    ASM_REWRITE_TAC[]]);;
let PLANE_TRIANGULATED_DISK_OFFSET = prove
 (`!V E p c q n outer k.
        plane_triangulated_disk (V:A->bool) E p c q n outer
        ==> plane_triangulated_disk
             V E p c (\i. q((i + k) MOD n)) n outer`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC "graph embedding large cycle component boundary faces" THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    USE_THEN "embedding" ACCEPT_TAC;
    USE_THEN "large" ACCEPT_TAC;
    MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_OFFSET THEN
    USE_THEN "cycle" ACCEPT_TAC;
    USE_THEN "component" ACCEPT_TAC;
    REWRITE_TAC[CYCLIC_VERTICES_OFFSET] THEN
    USE_THEN "boundary" ACCEPT_TAC;
    USE_THEN "faces" ACCEPT_TAC]);;

let CYCLIC_OFFSET_PAIR_TO_LAST = prove
 (`!q:num->A. !n i k.
        3 <= n /\ i < k /\ k < n /\
        ~({q i,q k} IN cyclic_edges q n)
        ==> let j = i + n - k - 1 in
            0 < j /\ j + 2 < n /\
            (j + (k + 1)) MOD n = i /\
            ((n - 1) + (k + 1)) MOD n = k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "large ordered k_index not_edge" THEN
  LET_TAC THEN
  SUBGOAL_THEN `~(k = i + 1)` (LABEL_TAC "not_successor") THENL
   [DISCH_THEN(LABEL_TAC "successor") THEN
    USE_THEN "not_edge" (MATCH_MP_TAC o NOT_ELIM) THEN
    REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `i:num` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      USE_THEN "successor" SUBST1_TAC THEN
      SUBGOAL_THEN `(i + 1) MOD n = i + 1` SUBST1_TAC THENL
       [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
        REFL_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(i = 0 /\ k = n - 1)` (LABEL_TAC "not_wrap") THENL
   [INTRO_TAC "i_zero k_last" THEN
    USE_THEN "not_edge" (MATCH_MP_TAC o NOT_ELIM) THEN
    REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `n - 1` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      SUBGOAL_THEN `(n - 1 + 1) MOD n = 0` SUBST1_TAC THENL
       [SUBGOAL_THEN `n - 1 + 1 = n` SUBST1_TAC THENL
         [ASM_ARITH_TAC;
          REWRITE_TAC[MOD_REFL]];
        ASM_REWRITE_TAC[PAIR_SET_SYM]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `0 < i + n - k - 1 /\ (i + n - k - 1) + 2 < n`
  (CONJUNCTS_THEN2 (LABEL_TAC "j_positive") (LABEL_TAC "j_bound")) THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((i + n - k - 1) + (k + 1)) MOD n = i`
  (LABEL_TAC "j_offset") THENL
   [SUBGOAL_THEN `(i + n - k - 1) + (k + 1) = n + i`
    SUBST1_TAC THENL
     [ASM_ARITH_TAC;
      MP_TAC(SPECL [`1`; `n:num`; `i:num`]
       (List.nth (CONJUNCTS MOD_MULT_ADD) 1)) THEN
      REWRITE_TAC[MULT_CLAUSES] THEN
      DISCH_THEN SUBST1_TAC THEN MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `((n - 1) + (k + 1)) MOD n = k`
  (LABEL_TAC "last_offset") THENL
   [SUBGOAL_THEN `(n - 1) + (k + 1) = n + k`
    SUBST1_TAC THENL
     [ASM_ARITH_TAC;
      MP_TAC(SPECL [`1`; `n:num`; `k:num`]
       (List.nth (CONJUNCTS MOD_MULT_ADD) 1)) THEN
      REWRITE_TAC[MULT_CLAUSES] THEN
      DISCH_THEN SUBST1_TAC THEN MATCH_MP_TAC MOD_LT THEN
      USE_THEN "k_index" ACCEPT_TAC];
    ALL_TAC] THEN
  EXPAND_TAC "j" THEN
  ASM_REWRITE_TAC[]);;

let PLANE_TRIANGULATED_DISK_INDEXED_BOUNDARY_CHORD_INTER_INSIDE = prove
 (`!V E p c q n outer i k.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        ~bounded outer /\
        i < k /\ k < n /\
        {q i,q k} IN E /\
        ~({q i,q k} IN cyclic_edges q n)
        ==> ~(c {q i,q k} INTER
              inside(UNIONS(IMAGE c (cyclic_edges q n))) = {})`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk outer_unbounded ordered k_index chord not_cycle" THEN
  SUBGOAL_THEN `3 <= n` (LABEL_TAC "large") THENL
   [USE_THEN "disk" MP_TAC THEN
    REWRITE_TAC[plane_triangulated_disk] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (ISPECL [`q:num->A`; `n:num`; `i:num`; `k:num`]
     CYCLIC_OFFSET_PAIR_TO_LAST)
   (CONJ (ASSUME `3 <= n`)
     (CONJ (ASSUME `(i:num) < k`)
      (CONJ (ASSUME `(k:num) < n`)
            (ASSUME
             `~({(q:num->A) i,q k} IN cyclic_edges q n)`))))) THEN
  CONV_TAC(LAND_CONV(ONCE_DEPTH_CONV let_CONV)) THEN
  INTRO_TAC "j_positive j_bound j_index last_index" THEN
  SUBGOAL_THEN
   `plane_triangulated_disk
      (V:A->bool) E p c
      (\h. q((h + (k + 1)) MOD n)) n outer`
  (LABEL_TAC "offset_disk") THENL
   [ACCEPT_TAC(MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
       `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
       `outer:real^2->bool`; `k + 1`]
      PLANE_TRIANGULATED_DISK_OFFSET)
     (ASSUME
      `plane_triangulated_disk
        (V:A->bool) E p c q n outer`));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{(q:num->A) (((i + n - k - 1) + (k + 1)) MOD n),
     q ((n - 1 + (k + 1)) MOD n)} = {q i,q k}`
  (LABEL_TAC "rotated_edge") THENL
   [REWRITE_TAC
     [ASSUME
       `((i + n - k - 1) + (k + 1)) MOD n = i`;
      ASSUME
       `((n - 1) + (k + 1)) MOD n = k`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_edges (\h. (q:num->A)((h + (k + 1)) MOD n)) n =
    cyclic_edges q n`
  (LABEL_TAC "offset_edges") THENL
   [ACCEPT_TAC(SPECL [`q:num->A`; `n:num`; `k + 1`]
     CYCLIC_EDGES_OFFSET);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_triangulated_disk
      (V:A->bool) E p c
      (\h. q((h + (k + 1)) MOD n)) n outer /\
    ~bounded outer /\
    0 < i + n - k - 1 /\
    (i + n - k - 1) + 2 < n /\
    {(\h. q((h + (k + 1)) MOD n)) (i + n - k - 1),
     (\h. q((h + (k + 1)) MOD n)) (n - 1)} IN E`
  (LABEL_TAC "rotated_conditions") THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "offset_disk" ACCEPT_TAC;
      USE_THEN "outer_unbounded" ACCEPT_TAC;
      USE_THEN "j_positive" ACCEPT_TAC;
      USE_THEN "j_bound" ACCEPT_TAC;
      BETA_TAC THEN
      USE_THEN "rotated_edge" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "chord" ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
     `c:(A->bool)->real^2->bool`;
     `(\h. q((h + (k + 1)) MOD n)):num->A`; `n:num`;
     `outer:real^2->bool`; `i + n - k - 1`]
    PLANE_TRIANGULATED_DISK_CHORD_INTER_INSIDE)
   (ASSUME
    `plane_triangulated_disk
       (V:A->bool) E p c
       (\h. q((h + (k + 1)) MOD n)) n outer /\
     ~bounded outer /\
     0 < i + n - k - 1 /\
     (i + n - k - 1) + 2 < n /\
     {(\h. q((h + (k + 1)) MOD n)) (i + n - k - 1),
      (\h. q((h + (k + 1)) MOD n)) (n - 1)} IN E`)) THEN
  USE_THEN "offset_edges" (fun th -> REWRITE_TAC[th]) THEN
  BETA_TAC THEN
  USE_THEN "rotated_edge" (fun th -> REWRITE_TAC[th]));;

let PLANE_TRIANGULATED_DISK_BOUNDARY_CHORD_INTER_INSIDE = prove
 (`!V E p c q n outer e.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        ~bounded outer /\
        e IN E /\
        e SUBSET cyclic_vertices q n /\
        ~(e IN cyclic_edges q n)
        ==> ~(c e INTER
              inside(UNIONS(IMAGE c (cyclic_edges q n))) = {})`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "disk outer_unbounded edge boundary not_cycle" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding large q_injective boundary_edges boundary_subset \
    outer_component boundary_face" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`]
   FINITE_SIMPLE_GRAPH_EDGE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@u v. u_vertex v_vertex distinct pair" THEN
  SUBGOAL_THEN
   `(u:A) IN cyclic_vertices q n /\ (v:A) IN cyclic_vertices q n`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_boundary")
                    (LABEL_TAC "v_boundary")) THENL
   [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["boundary"; "pair"] THEN SET_TAC[];
    ALL_TAC] THEN
  USE_THEN "u_boundary" MP_TAC THEN
  REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
  INTRO_TAC "@i. i_index u_eq" THEN
  USE_THEN "v_boundary" MP_TAC THEN
  REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
  INTRO_TAC "@k. k_index v_eq" THEN
  SUBGOAL_THEN `~((i:num) = k)` (LABEL_TAC "indices_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same_index") THEN
    SUBGOAL_THEN `(u:A) = v` (LABEL_TAC "same_endpoint") THENL
     [ACCEPT_TAC(TRANS
       (ASSUME `(u:A) = (q:num->A) i`)
       (TRANS
        (AP_TERM `(q:num->A)` (ASSUME `(i:num) = k`))
        (SYM(ASSUME `(v:A) = (q:num->A) k`))));
      CONTR_TAC(MP
       (NOT_ELIM(ASSUME `~((u:A) = v)`))
       (ASSUME `(u:A) = v`))];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (ARITH_RULE `~((i:num) = k) ==> i < k \/ k < i`)
   (ASSUME `~((i:num) = k)`)) THEN
  DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "forward_order")
                             (LABEL_TAC "reverse_order")) THENL
   [SUBGOAL_THEN `(e:A->bool) = {(q:num->A) i,q k}`
    (LABEL_TAC "edge_pair") THENL
     [TRANS_TAC EQ_TRANS `{u:A,v}` THEN CONJ_TAC THENL
       [USE_THEN "pair" ACCEPT_TAC;
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `{(q:num->A) i,q k} = e`
    (LABEL_TAC "edge_pair_sym") THENL
     [ACCEPT_TAC(SYM
       (ASSUME `(e:A->bool) = {(q:num->A) i,q k}`));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `plane_triangulated_disk (V:A->bool) E p c q n outer /\
      ~bounded outer /\ i < k /\ k < n /\
      {q i,q k} IN E /\
      ~({q i,q k} IN cyclic_edges q n)`
    (LABEL_TAC "indexed_conditions") THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "disk" ACCEPT_TAC;
        USE_THEN "outer_unbounded" ACCEPT_TAC;
        USE_THEN "forward_order" ACCEPT_TAC;
        USE_THEN "k_index" ACCEPT_TAC;
        REWRITE_TAC[ASSUME `{(q:num->A) i,q k} = e`] THEN
        USE_THEN "edge" ACCEPT_TAC;
        REWRITE_TAC[ASSUME `{(q:num->A) i,q k} = e`] THEN
        USE_THEN "not_cycle" ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
       `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
       `outer:real^2->bool`; `i:num`; `k:num`]
      PLANE_TRIANGULATED_DISK_INDEXED_BOUNDARY_CHORD_INTER_INSIDE)
     (ASSUME
      `plane_triangulated_disk (V:A->bool) E p c q n outer /\
       ~bounded outer /\ i < k /\ k < n /\
       {q i,q k} IN E /\
       ~({q i,q k} IN cyclic_edges q n)`)) THEN
    REWRITE_TAC[ASSUME `{(q:num->A) i,q k} = e`];
    SUBGOAL_THEN `(e:A->bool) = {(q:num->A) k,q i}`
    (LABEL_TAC "edge_pair") THENL
     [TRANS_TAC EQ_TRANS `{u:A,v}` THEN CONJ_TAC THENL
       [USE_THEN "pair" ACCEPT_TAC;
        ASM_REWRITE_TAC[PAIR_SET_SYM]];
      ALL_TAC] THEN
    SUBGOAL_THEN `{(q:num->A) k,q i} = e`
    (LABEL_TAC "edge_pair_sym") THENL
     [ACCEPT_TAC(SYM
       (ASSUME `(e:A->bool) = {(q:num->A) k,q i}`));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `plane_triangulated_disk (V:A->bool) E p c q n outer /\
      ~bounded outer /\ k < i /\ i < n /\
      {q k,q i} IN E /\
      ~({q k,q i} IN cyclic_edges q n)`
    (LABEL_TAC "indexed_conditions") THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "disk" ACCEPT_TAC;
        USE_THEN "outer_unbounded" ACCEPT_TAC;
        USE_THEN "reverse_order" ACCEPT_TAC;
        USE_THEN "i_index" ACCEPT_TAC;
        REWRITE_TAC[ASSUME `{(q:num->A) k,q i} = e`] THEN
        USE_THEN "edge" ACCEPT_TAC;
        REWRITE_TAC[ASSUME `{(q:num->A) k,q i} = e`] THEN
        USE_THEN "not_cycle" ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
       `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
       `outer:real^2->bool`; `k:num`; `i:num`]
      PLANE_TRIANGULATED_DISK_INDEXED_BOUNDARY_CHORD_INTER_INSIDE)
     (ASSUME
      `plane_triangulated_disk (V:A->bool) E p c q n outer /\
       ~bounded outer /\ k < i /\ i < n /\
       {q k,q i} IN E /\
       ~({q k,q i} IN cyclic_edges q n)`)) THEN
    REWRITE_TAC[ASSUME `{(q:num->A) k,q i} = e`]]);;

let PLANE_TRIANGULATED_DISK_CARRIER_SUBSET_CLOSED_INSIDE = prove
 (`!V E p c q n outer.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        ~bounded outer
        ==> plane_graph_carrier V E p c SUBSET
            closure(inside(UNIONS(IMAGE c (cyclic_edges q n))))`,
  REPEAT GEN_TAC THEN INTRO_TAC "disk outer_unbounded" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding large q_injective boundary_edges boundary_subset \
    outer_component boundary_face" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_OUTER_JORDAN_SIDE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "jordan_exists") THEN
  SUBGOAL_THEN
   `!j:real^1->real^2.
      simple_path j /\
      pathfinish j = pathstart j /\
      path_image j = UNIONS(IMAGE c (cyclic_edges (q:num->A) n)) /\
      ((outer:real^2->bool) SUBSET inside(path_image j) \/
       outer SUBSET outside(path_image j))
      ==> plane_graph_carrier
           (V:A->bool) (E:(A->bool)->bool) (p:A->real^2)
           (c:(A->bool)->real^2->bool) SUBSET
          closure(inside(UNIONS(IMAGE c (cyclic_edges q n))))`
  (LABEL_TAC "all_jordan_curves") THENL
   [X_GEN_TAC `j:real^1->real^2` THEN
    INTRO_TAC "simple closed image outer_side" THEN
  MP_TAC(ISPEC `j:real^1->real^2` JORDAN_INSIDE_OUTSIDE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "inside_nonempty inside_open inside_connected outside_nonempty \
    outside_open outside_connected inside_bounded outside_unbounded \
    sides_disjoint sides_union inside_frontier outside_frontier" THEN
  SUBGOAL_THEN
   `outer SUBSET outside(path_image(j:real^1->real^2))`
  (LABEL_TAC "outer_outside") THENL
   [USE_THEN "outer_side"
     (DISJ_CASES_THEN2 (LABEL_TAC "outer_inside")
                       (LABEL_TAC "outer_outside")) THENL
     [SUBGOAL_THEN `bounded(outer:real^2->bool)`
      (LABEL_TAC "outer_bounded") THENL
       [MATCH_MP_TAC BOUNDED_SUBSET THEN
        EXISTS_TAC `inside(path_image(j:real^1->real^2))` THEN
        ASM_REWRITE_TAC[];
        USE_THEN "outer_unbounded" (fun uth ->
         USE_THEN "outer_bounded" (fun bth ->
          CONTR_TAC(MP (NOT_ELIM uth) bth)))];
      USE_THEN "outer_outside" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `connected(outer:real^2->bool)`
  (LABEL_TAC "outer_connected") THENL
   [USE_THEN "outer_component"
     (ACCEPT_TAC o MATCH_MP IN_COMPONENTS_CONNECTED);
    ALL_TAC] THEN
  SUBGOAL_THEN `~((outer:real^2->bool) = {})`
  (LABEL_TAC "outer_nonempty") THENL
   [MATCH_MP_TAC(ISPECL
     [`(:real^2) DIFF plane_graph_carrier
        (V:A->bool) (E:(A->bool)->bool) (p:A->real^2)
        (c:(A->bool)->real^2->bool)`;
      `outer:real^2->bool`]
     IN_COMPONENTS_NONEMPTY) THEN
    USE_THEN "outer_component" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `open(outer:real^2->bool)`
  (LABEL_TAC "outer_open") THENL
   [MATCH_MP_TAC(ISPECL
     [`(:real^2) DIFF plane_graph_carrier
        (V:A->bool) (E:(A->bool)->bool) (p:A->real^2)
        (c:(A->bool)->real^2->bool)`;
      `outer:real^2->bool`]
     OPEN_COMPONENTS) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC OPEN_DIFF THEN REWRITE_TAC[OPEN_UNIV] THEN
    MATCH_MP_TAC PLANE_GRAPH_CARRIER_CLOSED THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(outer:real^2->bool) SUBSET
    (:real^2) DIFF
      plane_graph_carrier
       (V:A->bool) (E:(A->bool)->bool) (p:A->real^2)
       (c:(A->bool)->real^2->bool)`
  (LABEL_TAC "outer_complement") THENL
   [MATCH_MP_TAC IN_COMPONENTS_SUBSET THEN
    USE_THEN "outer_component" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
  `closure(inside(path_image(j:real^1->real^2))) =
    inside(path_image j) UNION path_image j`
  (LABEL_TAC "closed_inside") THENL
   [USE_THEN "image" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[CLOSURE_UNION_FRONTIER] THEN
    USE_THEN "inside_frontier" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `x:real^2` THEN
  DISCH_THEN(LABEL_TAC "x_carrier") THEN
  USE_THEN "image" (fun th -> REWRITE_TAC[GSYM th]) THEN
  ASM_CASES_TAC
   `(x:real^2) IN closure(inside(path_image(j:real^1->real^2)))` THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(LABEL_TAC "x_closed_inside") THEN
  SUBGOAL_THEN `(x:real^2) IN outside(path_image j)`
  (LABEL_TAC "x_outside") THENL
   [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["closed_inside"; "x_closed_inside"] THEN
    MP_TAC(ISPEC `path_image(j:real^1->real^2)`
     INSIDE_UNION_OUTSIDE) THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(frontier(outer:real^2->bool) INTER outside(path_image j) = {})`
  (LABEL_TAC "frontier_meets_outside") THENL
   [DISCH_THEN(LABEL_TAC "frontier_avoids_outside") THEN
    SUBGOAL_THEN
     `(outer:real^2->bool) = outside(path_image j)`
    (LABEL_TAC "outer_eq_outside") THENL
     [MATCH_MP_TAC OPEN_CONNECTED_SUBSET_EQ_OF_FRONTIER_DISJOINT THEN
      ASM_REWRITE_TAC[];
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["x_carrier"; "x_outside"; "outer_complement";
        "outer_eq_outside"] THEN SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `frontier(outer:real^2->bool) INTER
    outside(path_image(j:real^1->real^2)) = {}`
  (LABEL_TAC "frontier_avoids_outside") THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    X_GEN_TAC `z:real^2` THEN
    INTRO_TAC "z_frontier z_outside" THEN
  SUBGOAL_THEN
   `(z:real^2) IN
    plane_graph_carrier
      (cyclic_vertices (q:num->A) n)
      (induced_subgraph_edges
        (E:(A->bool)->bool) (cyclic_vertices q n))
      (p:A->real^2) (c:(A->bool)->real^2->bool)`
  (LABEL_TAC "z_induced_carrier") THENL
   [USE_THEN "disk" (fun th -> MP_TAC(MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
       `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
       `outer:real^2->bool`]
      PLANE_TRIANGULATED_DISK_OUTER_FRONTIER_SUBSET_INDUCED_CARRIER)
     th)) THEN
    DISCH_THEN(MP_TAC o SPEC `z:real^2` o REWRITE_RULE[SUBSET]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (p:A->real^2) (cyclic_vertices q n) SUBSET path_image j`
  (LABEL_TAC "boundary_vertex_points") THENL
   [USE_THEN "image" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`]
