    REWRITE_TAC[EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `z:real^2`) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((z:real^2) IN IMAGE (p:A->real^2) (cyclic_vertices q n))`
  (LABEL_TAC "z_not_vertex") THENL
   [DISCH_THEN(LABEL_TAC "z_vertex") THEN
    USE_THEN "z_not_path" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "boundary_vertex_points"
     (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "z_vertex" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?e:A->bool.
      e IN induced_subgraph_edges
       (E:(A->bool)->bool) (cyclic_vertices (q:num->A) n) /\
      (z:real^2) IN (c:(A->bool)->real^2->bool) e`
  (LABEL_TAC "edge_exists") THENL
   [USE_THEN "z_induced_carrier"
