    USE_THEN "z_not_vertex" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(?e:A->bool.
       e IN induced_subgraph_edges
        (E:(A->bool)->bool) (cyclic_vertices (q:num->A) n) /\
       (z:real^2) IN (c:(A->bool)->real^2->bool) e)`
  (LABEL_TAC "no_edge") THENL
   [REWRITE_TAC[NOT_EXISTS_THM] THEN
    X_GEN_TAC `e:A->bool` THEN
    INTRO_TAC "e_induced z_edge" THEN
  USE_THEN "e_induced" MP_TAC THEN
  REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
  INTRO_TAC "edge edge_boundary" THEN
  SUBGOAL_THEN
   `IMAGE (p:A->real^2) e SUBSET path_image j`
  (LABEL_TAC "edge_endpoints_boundary") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `IMAGE (p:A->real^2) (cyclic_vertices q n)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC IMAGE_SUBSET THEN
      USE_THEN "edge_boundary" ACCEPT_TAC;
      USE_THEN "boundary_vertex_points" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(z:real^2) IN c e DIFF IMAGE (p:A->real^2) e`
  (LABEL_TAC "z_edge_interior") THENL
   [REWRITE_TAC[IN_DIFF] THEN
    CONJ_TAC THENL
     [USE_THEN "z_edge" ACCEPT_TAC;
      DISCH_THEN(LABEL_TAC "z_endpoint") THEN
      USE_THEN "z_not_path" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "edge_endpoints_boundary"
       (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "z_endpoint" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) e SUBSET frontier outer`
  (LABEL_TAC "edge_frontier") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e:A->bool`;
      `outer:real^2->bool`; `z:real^2`]
     PLANE_GRAPH_EMBEDDING_EDGE_COMPONENT_FRONTIER) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((e:A->bool) IN cyclic_edges q n)`
  (LABEL_TAC "not_cycle_edge") THENL
   [DISCH_THEN(LABEL_TAC "cycle_edge") THEN
    SUBGOAL_THEN `(c:(A->bool)->real^2->bool) e SUBSET path_image j`
    (LABEL_TAC "cycle_edge_subset") THENL
     [USE_THEN "image" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[SUBSET; IN_UNIONS] THEN
      X_GEN_TAC `w:real^2` THEN DISCH_THEN(LABEL_TAC "w_edge") THEN
      EXISTS_TAC `(c:(A->bool)->real^2->bool) e` THEN
      CONJ_TAC THENL
       [REWRITE_TAC[IN_IMAGE] THEN
        EXISTS_TAC `e:A->bool` THEN ASM_REWRITE_TAC[];
        USE_THEN "w_edge" ACCEPT_TAC];
      SUBGOAL_THEN `(z:real^2) IN path_image j`
      (LABEL_TAC "z_on_cycle") THENL
       [USE_THEN "cycle_edge_subset"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "z_edge" ACCEPT_TAC;
        USE_THEN "z_not_path" (MATCH_MP_TAC o NOT_ELIM) THEN
        USE_THEN "z_on_cycle" ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_triangulated_disk
      (V:A->bool) (E:(A->bool)->bool) (p:A->real^2)
      (c:(A->bool)->real^2->bool) (q:num->A) n outer /\
    ~bounded(outer:real^2->bool) /\
    (e:A->bool) IN E /\
    e SUBSET cyclic_vertices q n /\
    ~(e IN cyclic_edges q n)`
  (LABEL_TAC "chord_hypotheses") THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "chord_hypotheses" (fun th -> MP_TAC(MATCH_MP
   (ISPECL
    [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
     `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
     `outer:real^2->bool`; `e:A->bool`]
    PLANE_TRIANGULATED_DISK_BOUNDARY_CHORD_INTER_INSIDE)
   th)) THEN
  DISCH_THEN(LABEL_TAC "chord_nonempty") THEN
  SUBGOAL_THEN
   `(outer:real^2->bool) SUBSET
    (:real^2) DIFF path_image(j:real^1->real^2)`
  (LABEL_TAC "outer_path_complement") THENL
   [REWRITE_TAC[SUBSET; IN_DIFF; IN_UNIV] THEN
    X_GEN_TAC `u:real^2` THEN
    DISCH_THEN(LABEL_TAC "u_outer") THEN
    SUBGOAL_THEN
     `(u:real^2) IN outside(path_image(j:real^1->real^2))`
    (LABEL_TAC "u_outside") THENL
     [USE_THEN "outer_outside" (fun th ->
       USE_THEN "u_outer" (fun uth ->
        ACCEPT_TAC(MATCH_MP
         (SPEC `u:real^2` (REWRITE_RULE[SUBSET] th)) uth)));
      DISCH_THEN(LABEL_TAC "u_path") THEN
      MP_TAC(ISPEC `path_image(j:real^1->real^2)`
       OUTSIDE_NO_OVERLAP) THEN
      REWRITE_TAC[EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
      DISCH_THEN(MP_TAC o SPEC `u:real^2`) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) e INTER
    inside(path_image(j:real^1->real^2)) = {}`
  (LABEL_TAC "chord_empty") THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    X_GEN_TAC `y:real^2` THEN
    INTRO_TAC "y_edge y_inside" THEN
    SUBGOAL_THEN `(y:real^2) IN frontier outer`
    (LABEL_TAC "y_frontier") THENL
     [USE_THEN "edge_frontier" (fun th ->
       USE_THEN "y_edge" (fun yth ->
        ACCEPT_TAC(MATCH_MP
         (SPEC `y:real^2` (REWRITE_RULE[SUBSET] th)) yth)));
      USE_THEN "y_inside" MP_TAC THEN
      REWRITE_TAC[GSYM NOT_DEF] THEN
      MATCH_MP_TAC(ISPECL
       [`j:real^1->real^2`; `outer:real^2->bool`; `y:real^2`]
       UNBOUNDED_CONNECTED_FRONTIER_AVOIDS_JORDAN_INSIDE) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  USE_THEN "chord_nonempty" (MATCH_MP_TAC o NOT_ELIM) THEN
  USE_THEN "image" (fun th -> REWRITE_TAC[GSYM th]) THEN
  USE_THEN "chord_empty" ACCEPT_TAC;
  ALL_TAC] THEN
  USE_THEN "no_edge" (MATCH_MP_TAC o NOT_ELIM) THEN
  USE_THEN "edge_exists" ACCEPT_TAC;
  ALL_TAC] THEN
  USE_THEN "frontier_meets_outside" (MATCH_MP_TAC o NOT_ELIM) THEN
  USE_THEN "frontier_avoids_outside" ACCEPT_TAC;
  ALL_TAC] THEN
  USE_THEN "all_jordan_curves"
   (MATCH_MP_TAC o REWRITE_RULE[GSYM LEFT_IMP_EXISTS_THM]) THEN
  USE_THEN "jordan_exists" ACCEPT_TAC);;
let CONNECTED_CLOSED_COVER_MEETS_INTER = prove
 (`!s l r:real^N->bool.
        connected s /\ closed l /\ closed r /\
        s SUBSET l UNION r /\
        ~(s INTER (l DIFF r) = {}) /\
        ~(s INTER (r DIFF l) = {})
        ==> ~(s INTER (l INTER r) = {})`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "connected l_closed r_closed cover meets_left meets_right" THEN
  DISCH_THEN(LABEL_TAC "avoids_inter") THEN
  SUBGOAL_THEN
   `closure((s:real^N->bool) INTER l) SUBSET l`
  (LABEL_TAC "left_closure") THENL
   [MATCH_MP_TAC CLOSURE_MINIMAL THEN
    ASM_REWRITE_TAC[INTER_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `closure((s:real^N->bool) INTER r) SUBSET r`
  (LABEL_TAC "right_closure") THENL
   [MATCH_MP_TAC CLOSURE_MINIMAL THEN
    ASM_REWRITE_TAC[INTER_SUBSET];
    ALL_TAC] THEN
  USE_THEN "connected" MP_TAC THEN
  REWRITE_TAC[CONNECTED_SEPARATION] THEN
  MAP_EVERY EXISTS_TAC
   [`(s:real^N->bool) INTER l`; `(s:real^N->bool) INTER r`] THEN
  MAP_EVERY (fun name -> USE_THEN name MP_TAC)
   ["cover"; "meets_left"; "meets_right"; "avoids_inter";
    "left_closure"; "right_closure"] THEN
  SET_TAC[]);;

let PLANE_GRAPH_EMBEDDING_CLOSED_SIDE_EDGE = prove
 (`!V E p c e0 l r.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e0 IN E /\
        plane_graph_closed_side_vertices V p l UNION
          plane_graph_closed_side_vertices V p r = V /\
        plane_graph_closed_side_vertices V p l INTER
          plane_graph_closed_side_vertices V p r = e0 /\
        closure(inside(l:real^2->bool)) INTER closure(inside r) = c e0 /\
        (!e. e IN E
             ==> c e SUBSET
                 closure(inside l) UNION closure(inside r))
        ==> !e. e IN E
                ==> e SUBSET plane_graph_closed_side_vertices V p l \/
                    e SUBSET plane_graph_closed_side_vertices V p r`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding separator vertices overlap closed_inter \
    carrier_cover" THEN
  X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
  SUBGOAL_THEN `(e:A->bool) SUBSET V /\ e HAS_SIZE 2`
  (CONJUNCTS_THEN2 (LABEL_TAC "edge_subset")
                    (LABEL_TAC "edge_size")) THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    INTRO_TAC "_ _ edge_data" THEN
    USE_THEN "edge_data" MATCH_MP_TAC THEN USE_THEN "edge" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "edge_size" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE_CONV `(e:A->bool) HAS_SIZE 2`] THEN
  INTRO_TAC "@x y. distinct edge_eq" THEN
  USE_THEN "edge_eq" SUBST_ALL_TAC THEN
  ASM_CASES_TAC
   `({x:A,y}:A->bool) SUBSET
    plane_graph_closed_side_vertices V p l` THEN
  ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC
   `({x:A,y}:A->bool) SUBSET
    plane_graph_closed_side_vertices V p r` THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `(x:A) IN plane_graph_closed_side_vertices V p l \/
    x IN plane_graph_closed_side_vertices V p r`
  (LABEL_TAC "x_side") THENL
   [REWRITE_TAC[GSYM IN_UNION] THEN
    USE_THEN "vertices" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "edge_subset"
     (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_INSERT];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(y:A) IN plane_graph_closed_side_vertices V p l \/
    y IN plane_graph_closed_side_vertices V p r`
  (LABEL_TAC "y_side") THENL
   [REWRITE_TAC[GSYM IN_UNION] THEN
    USE_THEN "vertices" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "edge_subset"
     (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_INSERT; IN_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((x:A) IN plane_graph_closed_side_vertices V p l /\
     ~(x IN plane_graph_closed_side_vertices V p r) /\
     y IN plane_graph_closed_side_vertices V p r /\
     ~(y IN plane_graph_closed_side_vertices V p l)) \/
    ((y:A) IN plane_graph_closed_side_vertices V p l /\
     ~(y IN plane_graph_closed_side_vertices V p r) /\
     x IN plane_graph_closed_side_vertices V p r /\
     ~(x IN plane_graph_closed_side_vertices V p l))`
  (LABEL_TAC "orientation") THENL
   [MAP_EVERY MP_TAC
     [ASSUME
       `~(({x:A,y}:A->bool) SUBSET
          plane_graph_closed_side_vertices V p l)`;
      ASSUME
       `~(({x:A,y}:A->bool) SUBSET
          plane_graph_closed_side_vertices V p r)`;
      ASSUME
       `(x:A) IN plane_graph_closed_side_vertices V p l \/
        x IN plane_graph_closed_side_vertices V p r`;
      ASSUME
       `(y:A) IN plane_graph_closed_side_vertices V p l \/
        y IN plane_graph_closed_side_vertices V p r`] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN
    REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN ITAUT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (p:A->real^2) {x,y} SUBSET
    (c:(A->bool)->real^2->bool) {x,y}`
  (LABEL_TAC "endpoints") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `{x:A,y}`]
     PLANE_GRAPH_EMBEDDING_EDGE_ENDPOINTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((c:(A->bool)->real^2->bool) {x,y} INTER
      (closure(inside l) DIFF closure(inside r)) = {}) /\
    ~(c {x,y} INTER
      (closure(inside r) DIFF closure(inside l)) = {})`
  (CONJUNCTS_THEN2 (LABEL_TAC "edge_meets_left")
                    (LABEL_TAC "edge_meets_right")) THENL
   [USE_THEN "orientation"
     (DISJ_CASES_THEN2 (LABEL_TAC "left_orientation")
                       (LABEL_TAC "right_orientation")) THENL
     [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["left_orientation"; "endpoints"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN
      REWRITE_TAC[plane_graph_closed_side_vertices; IN_ELIM_THM;
                  IMAGE_CLAUSES] THEN SET_TAC[];
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["right_orientation"; "endpoints"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN
      REWRITE_TAC[plane_graph_closed_side_vertices; IN_ELIM_THM;
                  IMAGE_CLAUSES] THEN SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected((c:(A->bool)->real^2->bool) {x,y})`
  (LABEL_TAC "edge_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `{x:A,y}`]
     PLANE_GRAPH_EMBEDDING_EDGE_CONNECTED) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((c:(A->bool)->real^2->bool) {x,y} INTER
      (closure(inside l) INTER closure(inside r)) = {})`
  (LABEL_TAC "edge_meets_separator") THENL
   [MATCH_MP_TAC CONNECTED_CLOSED_COVER_MEETS_INTER THEN
    ASM_REWRITE_TAC[CLOSED_CLOSURE] THEN
    USE_THEN "carrier_cover"
     (MATCH_MP_TAC o SPEC `{x:A,y}`) THEN
    USE_THEN "edge" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(({x:A,y}:A->bool) = e0)`
  (LABEL_TAC "edges_distinct") THENL
   [DISCH_THEN(LABEL_TAC "edge_is_separator") THEN
    SUBGOAL_THEN
     `({x:A,y}:A->bool) SUBSET
      plane_graph_closed_side_vertices V p l`
    (LABEL_TAC "left_subset") THENL
     [USE_THEN "edge_is_separator" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "overlap" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[INTER_SUBSET];
      CONTR_TAC(MP
       (NOT_ELIM
        (ASSUME
         `~(({x:A,y}:A->bool) SUBSET
            plane_graph_closed_side_vertices V p l)`))
       (ASSUME
        `({x:A,y}:A->bool) SUBSET
         plane_graph_closed_side_vertices V p l`))];
    ALL_TAC] THEN
  SUBGOAL_THEN `({x:A,y}:A->bool) INTER e0 = {}`
  (LABEL_TAC "endpoint_inter") THENL
   [USE_THEN "orientation"
     (DISJ_CASES_THEN2 (LABEL_TAC "left_orientation")
                       (LABEL_TAC "right_orientation")) THENL
     [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["left_orientation"; "overlap"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
      MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["right_orientation"; "overlap"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) {x,y} INTER c e0 =
    IMAGE p ({x,y} INTER e0)`
  (LABEL_TAC "edge_inter") THENL
   [USE_THEN "embedding" MP_TAC THEN
    REWRITE_TAC[plane_graph_embedding] THEN
    INTRO_TAC "_ _ _ intersections" THEN
    USE_THEN "intersections" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY (fun name -> USE_THEN name MP_TAC)
   ["edge_meets_separator"; "closed_inter";
    "edge_inter"; "endpoint_inter"] THEN
  REWRITE_TAC[IMAGE_CLAUSES] THEN SET_TAC[]);;

let INDUCED_SUBGRAPH_EDGES_UNION = prove
 (`!E:(A->bool)->bool. !W1 W2.
        (!e. e IN E ==> e SUBSET W1 \/ e SUBSET W2)
        ==> induced_subgraph_edges E W1 UNION
            induced_subgraph_edges E W2 = E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "edge_side") THEN
  REWRITE_TAC[EXTENSION; IN_UNION; IN_INDUCED_SUBGRAPH_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN EQ_TAC THENL
   [DISCH_THEN(DISJ_CASES_THEN STRIP_ASSUME_TAC) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(LABEL_TAC "edge") THEN
    USE_THEN "edge_side" (MP_TAC o SPEC `e:A->bool`) THEN
    ANTS_TAC THENL
     [USE_THEN "edge" ACCEPT_TAC;
      DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THEN
      ASM_REWRITE_TAC[]]]);;

let PLANE_GRAPH_EMBEDDING_CLOSED_SIDE_EDGE_PARTITION = prove
 (`!V E p c e0 l r.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e0 IN E /\
        plane_graph_closed_side_vertices V p l UNION
          plane_graph_closed_side_vertices V p r = V /\
        plane_graph_closed_side_vertices V p l INTER
          plane_graph_closed_side_vertices V p r = e0 /\
        closure(inside(l:real^2->bool)) INTER closure(inside r) = c e0 /\
        (!e. e IN E
             ==> c e SUBSET
                 closure(inside l) UNION closure(inside r))
        ==> induced_subgraph_edges E
              (plane_graph_closed_side_vertices V p l) UNION
            induced_subgraph_edges E
              (plane_graph_closed_side_vertices V p r) = E /\
            e0 IN induced_subgraph_edges E
              (plane_graph_closed_side_vertices V p l) /\
            e0 IN induced_subgraph_edges E
              (plane_graph_closed_side_vertices V p r)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding separator vertices overlap closed_inter \
    carrier_cover" THEN
  SUBGOAL_THEN
   `!e:A->bool.
        e IN E
        ==> e SUBSET plane_graph_closed_side_vertices V p l \/
            e SUBSET plane_graph_closed_side_vertices V p r`
  (LABEL_TAC "edge_side") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e0:A->bool`;
      `l:real^2->bool`; `r:real^2->bool`]
     PLANE_GRAPH_EMBEDDING_CLOSED_SIDE_EDGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC INDUCED_SUBGRAPH_EDGES_UNION THEN
    USE_THEN "edge_side" ACCEPT_TAC;
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN CONJ_TAC THENL
     [USE_THEN "separator" ACCEPT_TAC;
      USE_THEN "overlap" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[INTER_SUBSET]];
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN CONJ_TAC THENL
     [USE_THEN "separator" ACCEPT_TAC;
      USE_THEN "overlap" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[INTER_SUBSET]]]);;

let PLANE_GRAPH_EMBEDDING_CLOSED_SIDE_INDUCED_EDGE_CARRIER = prove
 (`!V E p c e0 l r.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e0 IN E /\
        plane_graph_closed_side_vertices V p l INTER
          plane_graph_closed_side_vertices V p r = e0 /\
        closure(inside(l:real^2->bool)) INTER closure(inside r) = c e0 /\
        (!e. e IN E
             ==> c e SUBSET
                 closure(inside l) UNION closure(inside r))
        ==> !e. e IN induced_subgraph_edges E
                     (plane_graph_closed_side_vertices V p l)
                ==> c e SUBSET closure(inside l)`,
