    ALL_TAC] THEN
  FIRST_X_ASSUM(LABEL_TAC "edges_distinct") THEN
  SUBGOAL_THEN `(e:A->bool) HAS_SIZE 2` (LABEL_TAC "edge_size") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    INTRO_TAC "_ _ edge_data" THEN
    USE_THEN "edge_data" (MP_TAC o SPEC `e:A->bool`) THEN
    ANTS_TAC THENL
     [USE_THEN "edge" ACCEPT_TAC;
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC)];
    ALL_TAC] THEN
  USE_THEN "edge_size" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE_CONV `(e:A->bool) HAS_SIZE 2`] THEN
  INTRO_TAC "@u v. distinct edge_eq" THEN
  USE_THEN "edge_eq" SUBST_ALL_TAC THEN
  SUBGOAL_THEN `~(({u:A,v}:A->bool) SUBSET e0)`
  (LABEL_TAC "not_separator_subset") THENL
   [DISCH_THEN(LABEL_TAC "separator_subset") THEN
    USE_THEN "edges_distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `{u:A,v}`; `e0:A->bool`]
     FINITE_SIMPLE_GRAPH_EDGE_SUBSET_EQ) THEN
    ASM_REWRITE_TAC[];
