    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "embedding" MP_TAC THEN
  REWRITE_TAC[plane_graph_embedding] THEN
  INTRO_TAC "p_injective edge_paths _ edge_intersections" THEN
  SUBGOAL_THEN `~((p:A->real^2) b = p a)`
  (LABEL_TAC "points_distinct") THENL
   [USE_THEN "p_injective" MP_TAC THEN
