      USE_THEN "point" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "y_is_a" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((c:(A->bool)->real^2->bool) {u,v} DELETE (p:A->real^2) a) INTER
      (closure(inside l) DIFF closure(inside r)) = {})`
  (LABEL_TAC "punctured_meets_left") THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `(p:A->real^2) b` THEN
    USE_THEN "edge_image" (fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[IN_INTER; IN_DELETE];
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `x:real^2` THEN
