let PLANE_GRAPH_EMBEDDING_CLOSED_SIDE_INDUCED_CARRIER = prove
 (`!V E p c e0 l r.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        e0 IN E /\
        plane_graph_closed_side_vertices V p l INTER
          plane_graph_closed_side_vertices V p r = e0 /\
        closure(inside(l:real^2->bool)) INTER closure(inside r) = c e0 /\
        (!e. e IN E
             ==> c e SUBSET
                 closure(inside l) UNION closure(inside r))
        ==> plane_graph_carrier
              (plane_graph_closed_side_vertices V p l)
              (induced_subgraph_edges E
                (plane_graph_closed_side_vertices V p l)) p c
            SUBSET closure(inside l)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding separator overlap closed_inter carrier_cover" THEN
  REWRITE_TAC[plane_graph_carrier; UNION_SUBSET] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; FORALL_IN_IMAGE;
                plane_graph_closed_side_vertices; IN_ELIM_THM] THEN
    MESON_TAC[];
    REWRITE_TAC[UNIONS_SUBSET; FORALL_IN_IMAGE] THEN
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e0:A->bool`;
      `l:real^2->bool`; `r:real^2->bool`]
     PLANE_GRAPH_EMBEDDING_CLOSED_SIDE_INDUCED_EDGE_CARRIER) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `e:A->bool`) THEN
    ASM_REWRITE_TAC[]]);;

let PLANE_GRAPH_EMBEDDING_CLOSED_SIDE_INDUCED_CARRIERS = prove
 (`!V E p c e0 l r.
        finite_simple_graph (V:A->bool) E /\
