   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e0:A->bool`;
      `l:real^2->bool`; `r:real^2->bool`]
     PLANE_GRAPH_EMBEDDING_CLOSED_SIDE_INDUCED_CARRIER) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `e0:A->bool`;
      `r:real^2->bool`; `l:real^2->bool`]
     PLANE_GRAPH_EMBEDDING_CLOSED_SIDE_INDUCED_CARRIER) THEN
    ASM_REWRITE_TAC[INTER_COMM; UNION_COMM]]);;
let ARC_PAIR_BOUNDARY_SUBSET_CLOSURE_INSIDE = prove
 (`!a d:real^1->real^2. !u v.
        ~(u = v) /\
        arc a /\ pathstart a = u /\ pathfinish a = v /\
        arc d /\ pathstart d = u /\ pathfinish d = v /\
        path_image a INTER path_image d = {u,v}
        ==> path_image a UNION path_image d SUBSET
            closure(inside(path_image a UNION path_image d))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "distinct a_arc a_start a_finish d_arc d_start d_finish inter" THEN
  SUBGOAL_THEN
   `frontier(inside(path_image(a:real^1->real^2) UNION path_image d)) =
    path_image a UNION path_image d`
  (LABEL_TAC "frontier") THENL
   [MP_TAC(ISPEC
     `(a:real^1->real^2) ++ reversepath(d:real^1->real^2)`
     JORDAN_INSIDE_OUTSIDE) THEN
    ASM_SIMP_TAC
     [PATHSTART_JOIN; PATHFINISH_JOIN; PATHSTART_REVERSEPATH;
      PATHFINISH_REVERSEPATH; SIMPLE_PATH_JOIN_LOOP_EQ;
      ARC_REVERSEPATH_EQ; PATH_IMAGE_JOIN; PATH_IMAGE_REVERSEPATH;
      SUBSET_REFL] THEN
    MESON_TAC[];
    REWRITE_TAC[CLOSURE_UNION_FRONTIER] THEN
    USE_THEN "frontier" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[SUBSET_UNION]]);;

let JORDAN_OUTSIDE_COMPONENT_OF_INTERMEDIATE_CARRIER = prove
 (`!j:real^1->real^2. !carrier.
        simple_path j /\ pathfinish j = pathstart j /\
        path_image j SUBSET carrier /\
        carrier SUBSET closure(inside(path_image j))
        ==> outside(path_image j) IN
            components((:real^2) DIFF carrier)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "simple closed boundary carrier" THEN
  MP_TAC(ISPEC `j:real^1->real^2` JORDAN_INSIDE_OUTSIDE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "inside_nonempty inside_open inside_connected outside_nonempty \
    outside_open outside_connected inside_bounded outside_unbounded \
    sides_disjoint sides_union inside_frontier outside_frontier" THEN
  SUBGOAL_THEN
   `closure(inside(path_image(j:real^1->real^2))) =
    inside(path_image j) UNION path_image j`
  (LABEL_TAC "closed_inside") THENL
   [REWRITE_TAC[CLOSURE_UNION_FRONTIER] THEN
    USE_THEN "inside_frontier" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`outside(path_image(j:real^1->real^2))`;
    `(:real^2) DIFF carrier`;
    `(:real^2) DIFF path_image j`]
   COMPONENTS_INTERMEDIATE_SUBSET) THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[OUTSIDE_IN_COMPONENTS] THEN ASM_REWRITE_TAC[];
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["carrier"; "closed_inside"; "sides_disjoint"] THEN
    MP_TAC(ISPEC `path_image(j:real^1->real^2)` OUTSIDE_NO_OVERLAP) THEN
    SET_TAC[];
    USE_THEN "boundary" MP_TAC THEN SET_TAC[]]);;

let ARC_PAIR_OUTSIDE_COMPONENT_OF_INTERMEDIATE_CARRIER = prove
 (`!a d:real^1->real^2. !u v carrier.
        ~(u = v) /\
        arc a /\ pathstart a = u /\ pathfinish a = v /\
        arc d /\ pathstart d = u /\ pathfinish d = v /\
        path_image a INTER path_image d = {u,v} /\
        path_image a UNION path_image d SUBSET carrier /\
        carrier SUBSET closure(inside(path_image a UNION path_image d))
        ==> outside(path_image a UNION path_image d) IN
            components((:real^2) DIFF carrier)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "distinct a_arc a_start a_finish d_arc d_start d_finish \
    inter boundary carrier" THEN
  MP_TAC(ISPECL
   [`(a:real^1->real^2) ++ reversepath(d:real^1->real^2)`;
    `carrier:real^2->bool`]
   JORDAN_OUTSIDE_COMPONENT_OF_INTERMEDIATE_CARRIER) THEN
  ASM_SIMP_TAC
   [PATHSTART_JOIN; PATHFINISH_JOIN; PATHSTART_REVERSEPATH;
    PATHFINISH_REVERSEPATH; SIMPLE_PATH_JOIN_LOOP_EQ;
    ARC_REVERSEPATH_EQ; PATH_IMAGE_JOIN; PATH_IMAGE_REVERSEPATH;
    SUBSET_REFL]);;

let FINITE_SIMPLE_GRAPH_CYCLE_VERTICES_SUBSET = prove
 (`!V E q n.
        finite_simple_graph (V:A->bool) E /\ simple_graph_cycle E q n
        ==> cyclic_vertices q n SUBSET V`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph cycle" THEN
  USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large _ cycle_edges" THEN
  REWRITE_TAC[SUBSET; IN_CYCLIC_VERTICES] THEN
  X_GEN_TAC `x:A` THEN INTRO_TAC "@i. i_index x_eq" THEN
  USE_THEN "x_eq" SUBST1_TAC THEN
  ABBREV_TAC `e:A->bool = {q i,q((i + 1) MOD n)}` THEN
  SUBGOAL_THEN `(e:A->bool) IN cyclic_edges q n`
  (LABEL_TAC "cycle_edge") THENL
   [EXPAND_TAC "e" THEN REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(e:A->bool) IN E` (LABEL_TAC "edge") THENL
   [USE_THEN "cycle_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "cycle_edge" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(e:A->bool) SUBSET V` (LABEL_TAC "edge_subset") THENL
   [USE_THEN "graph" MP_TAC THEN REWRITE_TAC[finite_simple_graph] THEN
    ASM_MESON_TAC[];
    USE_THEN "edge_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    EXPAND_TAC "e" THEN REWRITE_TAC[IN_INSERT]]);;

let SIMPLE_GRAPH_CYCLE_CARRIER_SUBSET_INDUCED_CARRIER = prove
 (`!E:(A->bool)->bool. !q n W p c.
        simple_graph_cycle E q n /\ cyclic_vertices q n SUBSET W
        ==> UNIONS(IMAGE (c:(A->bool)->real^2->bool) (cyclic_edges q n))
            SUBSET plane_graph_carrier
              W (induced_subgraph_edges E W) (p:A->real^2) c`,
  REPEAT GEN_TAC THEN INTRO_TAC "cycle vertices" THEN
  SUBGOAL_THEN `3 <= n /\ cyclic_edges (q:num->A) n SUBSET E`
  (CONJUNCTS_THEN2 (LABEL_TAC "large") (LABEL_TAC "cycle_edges")) THENL
   [USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[UNIONS_SUBSET; FORALL_IN_IMAGE] THEN
  X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "cycle_edge") THEN
  MATCH_MP_TAC(ISPECL
   [`W:A->bool`; `induced_subgraph_edges E (W:A->bool)`;
    `p:A->real^2`; `c:(A->bool)->real^2->bool`; `e:A->bool`]
   PLANE_GRAPH_CARRIER_EDGE_SUBSET) THEN
  REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN CONJ_TAC THENL
   [USE_THEN "cycle_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "cycle_edge" ACCEPT_TAC;
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `cyclic_vertices (q:num->A) n` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC CYCLIC_EDGE_SUBSET_VERTICES THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      USE_THEN "vertices" ACCEPT_TAC]]);;

let PLANE_GRAPH_EMBEDDING_CYCLE_VERTICES_SUBSET_CLOSED_SIDE = prove
 (`!V E p c q n s.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        simple_graph_cycle E q n /\
        UNIONS(IMAGE c (cyclic_edges q n)) = s /\
        s SUBSET closure(inside(s:real^2->bool))
        ==> cyclic_vertices q n SUBSET
            plane_graph_closed_side_vertices V p s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding cycle carrier boundary" THEN
  SUBGOAL_THEN `cyclic_vertices (q:num->A) n SUBSET V`
  (LABEL_TAC "vertices") THENL
   [ACCEPT_TAC(MATCH_MP
     (ISPECL [`V:A->bool`; `E:(A->bool)->bool`;
              `q:num->A`; `n:num`]
       FINITE_SIMPLE_GRAPH_CYCLE_VERTICES_SUBSET)
     (CONJ (ASSUME `finite_simple_graph (V:A->bool) E`)
           (ASSUME `simple_graph_cycle (E:(A->bool)->bool) q n`)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (p:A->real^2) (cyclic_vertices q n) SUBSET s`
  (LABEL_TAC "points") THENL
   [USE_THEN "carrier" (fun th -> REWRITE_TAC[GSYM th]) THEN
    ACCEPT_TAC(MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
       `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`]
      PLANE_GRAPH_EMBEDDING_CYCLE_VERTICES_SUBSET_CARRIER)
     (CONJ (ASSUME `plane_graph_embedding (V:A->bool) E p c`)
           (ASSUME `simple_graph_cycle (E:(A->bool)->bool) q n`)));
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET; plane_graph_closed_side_vertices; IN_ELIM_THM] THEN
  X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "x_cycle") THEN
  CONJ_TAC THENL
   [USE_THEN "vertices" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "x_cycle" ACCEPT_TAC;
    USE_THEN "boundary" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "points" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `x:A` THEN
    ASM_REWRITE_TAC[]]);;

let PLANE_GRAPH_EMBEDDING_CYCLE_CARRIER_SUBSET_CLOSED_SIDE_INDUCED_CARRIER =
 prove
 (`!V E p c q n s.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        simple_graph_cycle E q n /\
        UNIONS(IMAGE c (cyclic_edges q n)) = s /\
        s SUBSET closure(inside(s:real^2->bool))
        ==> s SUBSET
            plane_graph_carrier
              (plane_graph_closed_side_vertices V p s)
              (induced_subgraph_edges E
                (plane_graph_closed_side_vertices V p s)) p c`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding cycle carrier boundary" THEN
  SUBGOAL_THEN
   `cyclic_vertices (q:num->A) n SUBSET
    plane_graph_closed_side_vertices V p s`
  (LABEL_TAC "vertices") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `s:real^2->bool`]
     PLANE_GRAPH_EMBEDDING_CYCLE_VERTICES_SUBSET_CLOSED_SIDE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "carrier" (fun th -> REWRITE_TAC[GSYM th]) THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `q:num->A`; `n:num`;
    `plane_graph_closed_side_vertices (V:A->bool) (p:A->real^2)
      (s:real^2->bool)`;
    `p:A->real^2`; `c:(A->bool)->real^2->bool`]
   SIMPLE_GRAPH_CYCLE_CARRIER_SUBSET_INDUCED_CARRIER) THEN
  ASM_REWRITE_TAC[]);;
let PLANE_GRAPH_EMBEDDING_CHORD_EXPLICIT_SIDE_BOUNDARIES = prove
 (`!V E p c q n j a b d.
        finite_simple_graph (V:A->bool) E /\
        plane_graph_embedding V E p c /\
        simple_graph_cycle E q n /\
        0 < j /\ j + 2 < n /\ {q j,q(n - 1)} IN E /\
        arc a /\ pathstart a = p(q j) /\
          pathfinish a = p(q(n - 1)) /\
        path_image a =
          UNIONS(IMAGE c (cyclic_split_left_boundary_edges q n j)) /\
        arc b /\ pathstart b = p(q j) /\
          pathfinish b = p(q(n - 1)) /\
        path_image b =
          UNIONS(IMAGE c (cyclic_split_right_boundary_edges q n j)) /\
        arc d /\ pathstart d = p(q j) /\
          pathfinish d = p(q(n - 1)) /\
        path_image d = c {q j,q(n - 1)} /\
        path_image a INTER path_image d =
          {p(q j),p(q(n - 1))} /\
        path_image b INTER path_image d =
          {p(q j),p(q(n - 1))}
        ==> path_image a UNION path_image d SUBSET
            plane_graph_carrier
              (plane_graph_closed_side_vertices
                V p (path_image a UNION path_image d))
              (induced_subgraph_edges E
                (plane_graph_closed_side_vertices
                  V p (path_image a UNION path_image d))) p c /\
            path_image b UNION path_image d SUBSET
            plane_graph_carrier
              (plane_graph_closed_side_vertices
                V p (path_image b UNION path_image d))
              (induced_subgraph_edges E
                (plane_graph_closed_side_vertices
                  V p (path_image b UNION path_image d))) p c`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph embedding cycle jpositive bound chord \
    a_arc a_start a_finish a_image \
    b_arc b_start b_finish b_image \
    d_arc d_start d_finish d_image ad_inter bd_inter" THEN
  SUBGOAL_THEN `~((p:A->real^2)(q j) = p(q(n - 1)))`
  (LABEL_TAC "distinct") THENL
   [MP_TAC(MATCH_MP ARC_DISTINCT_ENDS
     (ASSUME `arc(d:real^1->real^2)`)) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle E
     (cyclic_split_left_oriented (q:num->A) n j) (j + 2)`
  (LABEL_TAC "left_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_SPLIT_LEFT_ORIENTED THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle E (cyclic_split_right (q:num->A) j) (n - j)`
  (LABEL_TAC "right_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_SPLIT_RIGHT THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
  `path_image(a:real^1->real^2) UNION path_image d SUBSET
    closure(inside(path_image a UNION path_image d))`
  (LABEL_TAC "left_closed") THENL
   [MATCH_MP_TAC(ISPECL
     [`a:real^1->real^2`; `d:real^1->real^2`;
      `(p:A->real^2)((q:num->A) j)`; `(p:A->real^2)(q(n - 1))`]
     ARC_PAIR_BOUNDARY_SUBSET_CLOSURE_INSIDE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
  `path_image(b:real^1->real^2) UNION path_image d SUBSET
    closure(inside(path_image b UNION path_image d))`
  (LABEL_TAC "right_closed") THENL
   [MATCH_MP_TAC(ISPECL
     [`b:real^1->real^2`; `d:real^1->real^2`;
      `(p:A->real^2)((q:num->A) j)`; `(p:A->real^2)(q(n - 1))`]
     ARC_PAIR_BOUNDARY_SUBSET_CLOSURE_INSIDE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`; `j:num`;
    `a:real^1->real^2`; `b:real^1->real^2`; `d:real^1->real^2`]
   PLANE_GRAPH_EMBEDDING_CHORD_EXPLICIT_CYCLE_CARRIERS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "left_carrier right_carrier" THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`;
      `cyclic_split_left_oriented (q:num->A) n j`; `j + 2`;
      `path_image(a:real^1->real^2) UNION
       path_image(d:real^1->real^2)`]
     PLANE_GRAPH_EMBEDDING_CYCLE_CARRIER_SUBSET_CLOSED_SIDE_INDUCED_CARRIER)
    THEN
    ASM_REWRITE_TAC[];
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`;
      `cyclic_split_right (q:num->A) j`; `(n:num) - j`;
      `path_image(b:real^1->real^2) UNION
       path_image(d:real^1->real^2)`]
     PLANE_GRAPH_EMBEDDING_CYCLE_CARRIER_SUBSET_CLOSED_SIDE_INDUCED_CARRIER)
    THEN
    ASM_REWRITE_TAC[]]);;

let PLANE_TRIANGULATED_DISK_CHORD_EXPLICIT_SIDE_COMPONENTS = prove
 (`!V E p c q n outer j a b d.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        ~bounded outer /\
        0 < j /\ j + 2 < n /\ {q j,q(n - 1)} IN E /\
        arc a /\ pathstart a = p(q j) /\
          pathfinish a = p(q(n - 1)) /\
        path_image a =
          UNIONS(IMAGE c (cyclic_split_left_boundary_edges q n j)) /\
        arc b /\ pathstart b = p(q j) /\
          pathfinish b = p(q(n - 1)) /\
        path_image b =
          UNIONS(IMAGE c (cyclic_split_right_boundary_edges q n j)) /\
        arc d /\ pathstart d = p(q j) /\
          pathfinish d = p(q(n - 1)) /\
        path_image d = c {q j,q(n - 1)} /\
        path_image a INTER path_image b =
          {p(q j),p(q(n - 1))} /\
        path_image a INTER path_image d =
          {p(q j),p(q(n - 1))} /\
        path_image b INTER path_image d =
          {p(q j),p(q(n - 1))} /\
        path_image a UNION path_image b =
          UNIONS(IMAGE c (cyclic_edges q n))
        ==> path_image a UNION path_image d SUBSET
            plane_graph_carrier
              (plane_graph_closed_side_vertices
                (V:A->bool) p (path_image a UNION path_image d))
              (induced_subgraph_edges E
                (plane_graph_closed_side_vertices
                  (V:A->bool) p (path_image a UNION path_image d))) p c /\
            plane_graph_carrier
              (plane_graph_closed_side_vertices
                (V:A->bool) p (path_image a UNION path_image d))
              (induced_subgraph_edges E
                (plane_graph_closed_side_vertices
                  (V:A->bool) p (path_image a UNION path_image d))) p c
            SUBSET closure
              (inside(path_image a UNION path_image d)) /\
            outside(path_image a UNION path_image d) IN
            components
              ((:real^2) DIFF
               plane_graph_carrier
                (plane_graph_closed_side_vertices
                  (V:A->bool) p (path_image a UNION path_image d))
                (induced_subgraph_edges E
                  (plane_graph_closed_side_vertices
                    (V:A->bool) p (path_image a UNION path_image d))) p c) /\
            path_image b UNION path_image d SUBSET
            plane_graph_carrier
              (plane_graph_closed_side_vertices
                (V:A->bool) p (path_image b UNION path_image d))
              (induced_subgraph_edges E
                (plane_graph_closed_side_vertices
                  (V:A->bool) p (path_image b UNION path_image d))) p c /\
            plane_graph_carrier
              (plane_graph_closed_side_vertices
                (V:A->bool) p (path_image b UNION path_image d))
              (induced_subgraph_edges E
                (plane_graph_closed_side_vertices
                  (V:A->bool) p (path_image b UNION path_image d))) p c
            SUBSET closure
              (inside(path_image b UNION path_image d)) /\
            outside(path_image b UNION path_image d) IN
            components
              ((:real^2) DIFF
               plane_graph_carrier
                (plane_graph_closed_side_vertices
                  (V:A->bool) p (path_image b UNION path_image d))
                (induced_subgraph_edges E
                  (plane_graph_closed_side_vertices
                    (V:A->bool) p (path_image b UNION path_image d))) p c)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk outer_unbounded jpositive bound chord \
    a_arc a_start a_finish a_image \
    b_arc b_start b_finish b_image \
    d_arc d_start d_finish d_image \
    ab_inter ad_inter bd_inter boundary_union" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding large q_injective boundary_edges boundary_subset \
    outer_component boundary_face" THEN
  SUBGOAL_THEN `simple_graph_cycle (E:(A->bool)->bool) q n`
  (LABEL_TAC "cycle") THENL
   [REWRITE_TAC[simple_graph_cycle] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((p:A->real^2)(q j) = p(q(n - 1)))`
  (LABEL_TAC "distinct") THENL
   [MP_TAC(MATCH_MP ARC_DISTINCT_ENDS
     (ASSUME `arc(d:real^1->real^2)`)) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(path_image(d:real^1->real^2) INTER
      inside(path_image a UNION path_image b) = {})`
  (LABEL_TAC "crosses") THENL
   [USE_THEN "d_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "boundary_union" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `j:num`]
     PLANE_TRIANGULATED_DISK_CHORD_INTER_INSIDE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `{q j,q(n - 1)}:A->bool`;
    `a:real^1->real^2`; `b:real^1->real^2`; `d:real^1->real^2`;
    `(p:A->real^2)((q:num->A) j)`; `(p:A->real^2)(q(n - 1))`]
   PLANE_GRAPH_THETA_CLOSED_SIDE_VERTICES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "closed_inter closed_union overlap" THEN
  SUBGOAL_THEN
   `plane_graph_carrier (V:A->bool) E p c SUBSET
    closure(inside(UNIONS(IMAGE c (cyclic_edges q n))))`
  (LABEL_TAC "full_carrier") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`]
     PLANE_TRIANGULATED_DISK_CARRIER_SUBSET_CLOSED_INSIDE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!e:A->bool.
      e IN E
      ==> (c:(A->bool)->real^2->bool) e SUBSET
          closure(inside(path_image a UNION path_image d)) UNION
          closure(inside(path_image b UNION path_image d))`
  (LABEL_TAC "carrier_cover") THENL
   [X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
