    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `plane_graph_carrier (V:A->bool) E p c` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC PLANE_GRAPH_CARRIER_EDGE_SUBSET THEN
      USE_THEN "edge" ACCEPT_TAC;
      MAP_EVERY (fun name -> USE_THEN name (fun th -> REWRITE_TAC[th]))
       ["a_image"; "b_image"; "d_image"] THEN
