    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `{q j,q(n - 1)}:A->bool`;
    `path_image(a:real^1->real^2) UNION path_image d`;
    `path_image(b:real^1->real^2) UNION path_image d`]
   PLANE_GRAPH_EMBEDDING_CLOSED_SIDE_INDUCED_CARRIERS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "left_carrier right_carrier" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`; `j:num`;
    `a:real^1->real^2`; `b:real^1->real^2`; `d:real^1->real^2`]
   PLANE_GRAPH_EMBEDDING_CHORD_EXPLICIT_SIDE_BOUNDARIES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "left_boundary right_boundary" THEN
  SUBGOAL_THEN
   `outside(path_image(a:real^1->real^2) UNION path_image d) IN
    components
     ((:real^2) DIFF
      plane_graph_carrier
       (plane_graph_closed_side_vertices
         (V:A->bool) p (path_image a UNION path_image d))
       (induced_subgraph_edges E
         (plane_graph_closed_side_vertices
           (V:A->bool) p (path_image a UNION path_image d))) p c)`
  (LABEL_TAC "left_component") THENL
   [USE_THEN "d_start" (fun start_th ->
      USE_THEN "d_finish" (fun finish_th ->
