let PLANE_GRAPH_EMBEDDING_CYCLE_CARRIER_VERTEX_SET = prove
 (`!V E p c q n W.
        plane_graph_embedding (V:A->bool) E p c /\
        simple_graph_cycle E q n /\
        (W:A->bool) SUBSET V /\
        cyclic_vertices q n SUBSET W
        ==> {v | v IN W /\
