let ARC_PAIR_OUTSIDE_FACE_VERTICES_CYCLE = prove
 (`!V E p c W E' q n a d u v.
        plane_graph_embedding (V:A->bool) E p c /\
        simple_graph_cycle E q n /\
        (W:A->bool) SUBSET V /\
        cyclic_vertices q n SUBSET W /\
        ~(u = v) /\
        arc a /\ pathstart a = u /\ pathfinish a = v /\
        arc d /\ pathstart d = u /\ pathfinish d = v /\
        path_image a INTER path_image d = {u,v} /\
        path_image a UNION path_image d =
          UNIONS(IMAGE c (cyclic_edges q n))
        ==> plane_graph_face_vertices
              W E' p c (outside(path_image a UNION path_image d)) =
            cyclic_vertices q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "embedding cycle W_subset cycle_subset distinct \
    a_arc a_start a_finish d_arc d_start d_finish inter carrier" THEN
  SUBGOAL_THEN
   `frontier(outside(path_image(a:real^1->real^2) UNION path_image d)) =
    path_image a UNION path_image d`
  (LABEL_TAC "frontier") THENL
   [MP_TAC(ISPEC
     `(a:real^1->real^2) ++ reversepath(d:real^1->real^2)`
     JORDAN_INSIDE_OUTSIDE) THEN
    ASM_SIMP_TAC
     [PATHSTART_JOIN; PATHFINISH_JOIN; PATHSTART_REVERSEPATH;
      PATHFINISH_REVERSEPATH; SIMPLE_PATH_JOIN_LOOP_EQ;
      ARC_REVERSEPATH_EQ; PATH_IMAGE_JOIN; PATH_IMAGE_REVERSEPATH;
      SUBSET_REFL] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[plane_graph_face_vertices] THEN
  USE_THEN "frontier" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "carrier" (fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`; `W:A->bool`]
   PLANE_GRAPH_EMBEDDING_CYCLE_CARRIER_VERTEX_SET) THEN
  ASM_REWRITE_TAC[]);;

