   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`;
      `cyclic_split_right (q:num->A) j`; `(n:num) - j`;
      `path_image(b:real^1->real^2) UNION path_image d`]
     PLANE_GRAPH_EMBEDDING_CYCLE_VERTICES_SUBSET_CLOSED_SIDE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_face_vertices
      (plane_graph_closed_side_vertices
        (V:A->bool) p (path_image a UNION path_image d))
      (induced_subgraph_edges (E:(A->bool)->bool)
        (plane_graph_closed_side_vertices
          (V:A->bool) p (path_image a UNION path_image d)))
      p c (outside(path_image a UNION path_image d)) =
    cyclic_vertices
      (cyclic_split_left_oriented (q:num->A) n j) (j + 2)`
  (LABEL_TAC "left_face") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`;
      `plane_graph_closed_side_vertices
        (V:A->bool) p (path_image a UNION path_image d)`;
      `induced_subgraph_edges E
        (plane_graph_closed_side_vertices
          (V:A->bool) p (path_image a UNION path_image d))`;
      `cyclic_split_left_oriented (q:num->A) n j`; `j + 2`;
      `a:real^1->real^2`; `d:real^1->real^2`;
      `(p:A->real^2)((q:num->A) j)`; `(p:A->real^2)(q(n - 1))`]
     ARC_PAIR_OUTSIDE_FACE_VERTICES_CYCLE) THEN
    REPEAT CONJ_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_face_vertices
      (plane_graph_closed_side_vertices
        (V:A->bool) p (path_image b UNION path_image d))
      (induced_subgraph_edges (E:(A->bool)->bool)
        (plane_graph_closed_side_vertices
          (V:A->bool) p (path_image b UNION path_image d)))
      p c (outside(path_image b UNION path_image d)) =
    cyclic_vertices (cyclic_split_right (q:num->A) j) (n - j)`
  (LABEL_TAC "right_face") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`;
      `plane_graph_closed_side_vertices
        (V:A->bool) p (path_image b UNION path_image d)`;
      `induced_subgraph_edges E
        (plane_graph_closed_side_vertices
          (V:A->bool) p (path_image b UNION path_image d))`;
      `cyclic_split_right (q:num->A) j`; `(n:num) - j`;
      `b:real^1->real^2`; `d:real^1->real^2`;
      `(p:A->real^2)((q:num->A) j)`; `(p:A->real^2)(q(n - 1))`]
     ARC_PAIR_OUTSIDE_FACE_VERTICES_CYCLE) THEN
    REPEAT CONJ_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "left_face" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(ISPECL [`q:num->A`; `n:num`; `j:num`]
     CYCLIC_VERTICES_SPLIT_LEFT_ORIENTED) THEN
    ASM_REWRITE_TAC[];
    USE_THEN "right_face" ACCEPT_TAC]);;

let PLANE_GRAPH_CARRIER_UNION = prove
 (`!V1 V2 V E1 E2 E p c.
        (V1:A->bool) UNION V2 = V /\
        (E1:(A->bool)->bool) UNION E2 = E
        ==> plane_graph_carrier V1 E1 p c UNION
            plane_graph_carrier V2 E2 p c =
            plane_graph_carrier V E p c`,
  REPEAT GEN_TAC THEN INTRO_TAC "vertices edges" THEN
  USE_THEN "vertices" (fun th -> REWRITE_TAC[GSYM th]) THEN
  USE_THEN "edges" (fun th -> REWRITE_TAC[GSYM th]) THEN
  REWRITE_TAC[plane_graph_carrier; IMAGE_UNION; UNIONS_UNION] THEN
  SET_TAC[]);;

let NONOUTSIDE_COMPONENT_SUBSET_INSIDE = prove
 (`!s C k:real^N->bool.
        closed s /\
        s SUBSET C /\
        outside s IN components((:real^N) DIFF C) /\
        k IN components((:real^N) DIFF C) /\
        ~(k = outside s)
        ==> k SUBSET inside s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "closed boundary outside_component component distinct" THEN
  SUBGOAL_THEN `connected(k:real^N->bool)`
  (LABEL_TAC "connected") THENL
   [USE_THEN "component"
     (ACCEPT_TAC o MATCH_MP IN_COMPONENTS_CONNECTED);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(k:real^N->bool) SUBSET (:real^N) DIFF s`
  (LABEL_TAC "complement") THENL
   [USE_THEN "component" (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
    USE_THEN "boundary" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`s:real^N->bool`; `k:real^N->bool`]
   CONNECTED_SUBSET_INSIDE_OR_OUTSIDE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "inside")
    (LABEL_TAC "outside")) THENL
   [USE_THEN "inside" ACCEPT_TAC;
    SUBGOAL_THEN
     `~((k:real^N->bool) INTER outside s = {})`
    (LABEL_TAC "meets") THENL
     [USE_THEN "component" (MP_TAC o MATCH_MP IN_COMPONENTS_NONEMPTY) THEN
      USE_THEN "outside" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(k:real^N->bool) = outside s`
    (LABEL_TAC "equal") THENL
     [MP_TAC(MATCH_MP
       (ISPECL
        [`(:real^N) DIFF C`; `k:real^N->bool`;
         `outside(s:real^N->bool)`]
        COMPONENTS_EQ)
       (CONJ
        (ASSUME
         `(k:real^N->bool) IN components((:real^N) DIFF C)`)
        (ASSUME
         `outside(s:real^N->bool) IN
          components((:real^N) DIFF C)`))) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "distinct" (fun nth ->
       USE_THEN "equal" (fun eth ->
        CONTR_TAC(MP (NOT_ELIM nth) eth)))]]);;

let COMPONENT_OF_CARRIER_UNION_INSIDE = prove
 (`!C C1 C2 s t d k:real^N->bool.
        C1 UNION C2 = C /\
        C2 SUBSET closure(inside t) /\
        closure(inside s) INTER closure(inside t) = d /\
        d SUBSET s /\
        k IN components((:real^N) DIFF C1) /\
        k SUBSET inside s
        ==> k IN components((:real^N) DIFF C)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "carrier_union other_side closed_inter separator component inside" THEN
  SUBGOAL_THEN `(C1:real^N->bool) SUBSET C`
  (LABEL_TAC "carrier_subset") THENL
   [USE_THEN "carrier_union" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(k:real^N->bool) SUBSET (:real^N) DIFF C`
  (LABEL_TAC "full_complement") THENL
   [USE_THEN "component" (MP_TAC o MATCH_MP IN_COMPONENTS_SUBSET) THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["inside"; "carrier_union"; "other_side";
      "closed_inter"; "separator"] THEN
    MP_TAC(ISPEC `inside(s:real^N->bool)` CLOSURE_SUBSET) THEN
    MP_TAC(ISPEC `s:real^N->bool` INSIDE_NO_OVERLAP) THEN
    SET_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`k:real^N->bool`; `(:real^N) DIFF C`;
    `(:real^N) DIFF C1`]
   COMPONENTS_INTERMEDIATE_SUBSET) THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "carrier_subset" MP_TAC THEN SET_TAC[]);;

let PLANE_GRAPH_FACE_VERTICES_SUBSET_CLOSED_SIDE = prove
 (`!V E p c k s.
        (k:real^2->bool) SUBSET inside s
        ==> plane_graph_face_vertices (V:A->bool) E p c k SUBSET
            plane_graph_closed_side_vertices V p s`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "inside") THEN
  SUBGOAL_THEN
   `closure(k:real^2->bool) SUBSET closure(inside s)`
  (LABEL_TAC "closure") THENL
   [MATCH_MP_TAC CLOSURE_MINIMAL THEN
    ASM_REWRITE_TAC[CLOSED_CLOSURE] THEN
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `inside(s:real^2->bool)` THEN
    ASM_REWRITE_TAC[CLOSURE_SUBSET];
    ALL_TAC] THEN
  REWRITE_TAC
   [plane_graph_face_vertices; plane_graph_closed_side_vertices;
    SUBSET; IN_ELIM_THM] THEN
  X_GEN_TAC `v:A` THEN INTRO_TAC "vertex frontier" THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "closure" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
  USE_THEN "frontier" MP_TAC THEN
  REWRITE_TAC[frontier; IN_DIFF] THEN MESON_TAC[]);;

let PLANE_TRIANGULATED_DISK_INDUCED_CLOSED_SIDE = prove
 (`!V E p c q n outer W q' m s W2 E2 t d.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        ~bounded outer /\
        (W:A->bool) SUBSET V /\
        W = plane_graph_closed_side_vertices V p s /\
        3 <= m /\
        simple_graph_cycle E q' m /\
        cyclic_vertices q' m SUBSET W /\
        s SUBSET
          plane_graph_carrier W (induced_subgraph_edges E W) p c /\
        outside s IN components
          ((:real^2) DIFF
           plane_graph_carrier W (induced_subgraph_edges E W) p c) /\
        plane_graph_face_vertices
          W (induced_subgraph_edges E W) p c (outside s) =
          cyclic_vertices q' m /\
        plane_graph_carrier W (induced_subgraph_edges E W) p c UNION
          plane_graph_carrier W2 E2 p c =
          plane_graph_carrier V E p c /\
        plane_graph_carrier W2 E2 p c SUBSET closure(inside t) /\
        closure(inside s) INTER closure(inside t) = d /\
        d SUBSET s /\
        closed s /\
        bounded s
        ==> plane_triangulated_disk
              W (induced_subgraph_edges E W) p c q' m (outside s)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk outer_unbounded W_subset W_closed large cycle cycle_vertices \
    boundary_carrier outer_component outer_face carrier_union \
    other_side closed_inter separator closed bounded" THEN
  USE_THEN "disk" MP_TAC THEN
  REWRITE_TAC[plane_triangulated_disk] THEN
  INTRO_TAC
   "graph embedding _ _ original_component original_face triangular" THEN
  SUBGOAL_THEN
   `simple_graph_cycle
      (induced_subgraph_edges (E:(A->bool)->bool) (W:A->bool))
      (q':num->A) m`
  (LABEL_TAC "induced_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_INDUCED_SUBGRAPH THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[plane_triangulated_disk] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `W:A->bool`]
     FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `W:A->bool`]
     PLANE_GRAPH_EMBEDDING_INDUCED_SUBGRAPH) THEN
    ASM_REWRITE_TAC[];
    USE_THEN "large" ACCEPT_TAC;
    USE_THEN "induced_cycle" ACCEPT_TAC;
    USE_THEN "outer_component" ACCEPT_TAC;
    USE_THEN "outer_face" ACCEPT_TAC;
    X_GEN_TAC `k:real^2->bool` THEN
    INTRO_TAC "component distinct" THEN
    SUBGOAL_THEN `(k:real^2->bool) SUBSET inside s`
    (LABEL_TAC "inside") THENL
     [MATCH_MP_TAC(ISPECL
       [`s:real^2->bool`;
        `plane_graph_carrier (W:A->bool)
          (induced_subgraph_edges (E:(A->bool)->bool) W)
          (p:A->real^2) (c:(A->bool)->real^2->bool)`;
        `k:real^2->bool`]
       NONOUTSIDE_COMPONENT_SUBSET_INSIDE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(k:real^2->bool) IN components
       ((:real^2) DIFF plane_graph_carrier (V:A->bool) E p c)`
    (LABEL_TAC "original_component") THENL
     [MATCH_MP_TAC(ISPECL
       [`plane_graph_carrier (V:A->bool) E p c`;
        `plane_graph_carrier (W:A->bool)
          (induced_subgraph_edges (E:(A->bool)->bool) W) p c`;
        `plane_graph_carrier (W2:A->bool) (E2:(A->bool)->bool) p c`;
        `s:real^2->bool`; `t:real^2->bool`; `d:real^2->bool`;
        `k:real^2->bool`]
       COMPONENT_OF_CARRIER_UNION_INSIDE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `bounded(k:real^2->bool)` (LABEL_TAC "k_bounded") THENL
     [MATCH_MP_TAC BOUNDED_SUBSET THEN
      EXISTS_TAC `inside(s:real^2->bool)` THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC BOUNDED_INSIDE THEN
      USE_THEN "bounded" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((k:real^2->bool) = outer)`
    (LABEL_TAC "not_original_outer") THENL
     [DISCH_THEN SUBST_ALL_TAC THEN
      USE_THEN "outer_unbounded" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "k_bounded" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "triangular" (MP_TAC o SPEC `k:real^2->bool`) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      INTRO_TAC "@r. old_face old_cycle"] THEN
    SUBGOAL_THEN
     `plane_graph_face_vertices (V:A->bool) E p c k SUBSET W`
    (LABEL_TAC "old_vertices") THENL
     [USE_THEN "W_closed" (fun th -> REWRITE_TAC[th]) THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `k:real^2->bool`;
        `s:real^2->bool`]
       PLANE_GRAPH_FACE_VERTICES_SUBSET_CLOSED_SIDE) THEN
      USE_THEN "inside" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `plane_graph_face_vertices
        (W:A->bool) (induced_subgraph_edges E W) p c k =
      plane_graph_face_vertices V E p c k`
    (LABEL_TAC "restricted_face") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `W:A->bool`;
        `induced_subgraph_edges (E:(A->bool)->bool) (W:A->bool)`;
        `k:real^2->bool`]
       PLANE_GRAPH_FACE_VERTICES_RESTRICT) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    EXISTS_TAC `r:num->A` THEN CONJ_TAC THENL
     [USE_THEN "restricted_face" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "old_face" ACCEPT_TAC;
      MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_INDUCED_SUBGRAPH THEN
      CONJ_TAC THENL
       [USE_THEN "old_cycle" ACCEPT_TAC;
        USE_THEN "old_face" (fun th -> REWRITE_TAC[GSYM th]) THEN
        USE_THEN "old_vertices" ACCEPT_TAC]]]);;

let PLANE_TRIANGULATED_DISK_CHORD_EXPLICIT_SIDE_DISKS = prove
 (`!V E p c q n outer j a b d.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        ~bounded outer /\
        0 < j /\ j + 2 < n /\ {q j,q(n - 1)} IN E /\
        arc a /\ pathstart a = p(q j) /\
          pathfinish a = p(q(n - 1)) /\
        path_image a =
          UNIONS(IMAGE c (cyclic_split_left_boundary_edges q n j)) /\
        arc b /\ pathstart b = p(q j) /\
          pathfinish b = p(q(n - 1)) /\
        path_image b =
          UNIONS(IMAGE c (cyclic_split_right_boundary_edges q n j)) /\
        arc d /\ pathstart d = p(q j) /\
          pathfinish d = p(q(n - 1)) /\
        path_image d = c {q j,q(n - 1)} /\
        path_image a INTER path_image b =
          {p(q j),p(q(n - 1))} /\
        path_image a INTER path_image d =
          {p(q j),p(q(n - 1))} /\
        path_image b INTER path_image d =
          {p(q j),p(q(n - 1))} /\
        path_image a UNION path_image b =
          UNIONS(IMAGE c (cyclic_edges q n))
        ==> plane_triangulated_disk
              (plane_graph_closed_side_vertices
                V p (path_image a UNION path_image d))
              (induced_subgraph_edges E
                (plane_graph_closed_side_vertices
                  V p (path_image a UNION path_image d)))
              p c (cyclic_split_left q n j) (j + 2)
              (outside(path_image a UNION path_image d)) /\
            plane_triangulated_disk
              (plane_graph_closed_side_vertices
                V p (path_image b UNION path_image d))
              (induced_subgraph_edges E
                (plane_graph_closed_side_vertices
                  V p (path_image b UNION path_image d)))
              p c (cyclic_split_right q j) (n - j)
              (outside(path_image b UNION path_image d))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(fun th ->
    LABEL_TAC "conditions" th THEN MP_TAC th) THEN
  INTRO_TAC
   "disk outer_unbounded jpositive bound chord \
    a_arc a_start a_finish a_image \
    b_arc b_start b_finish b_image \
    d_arc d_start d_finish d_image \
    ab_inter ad_inter bd_inter boundary_union" THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
     `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
     `outer:real^2->bool`]
    PLANE_TRIANGULATED_DISK_INVARIANTS)
   (ASSUME
    `plane_triangulated_disk
      (V:A->bool) E p c q n outer`)) THEN
  INTRO_TAC
   "graph embedding large q_injective boundary_edges boundary_subset \
    outer_component boundary_face" THEN
  SUBGOAL_THEN `simple_graph_cycle (E:(A->bool)->bool) q n`
  (LABEL_TAC "cycle") THENL
   [REWRITE_TAC[simple_graph_cycle] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((p:A->real^2)(q j) = p(q(n - 1)))`
  (LABEL_TAC "distinct") THENL
   [MP_TAC(MATCH_MP ARC_DISTINCT_ENDS
     (ASSUME `arc(d:real^1->real^2)`)) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(path_image(d:real^1->real^2) INTER
      inside(path_image a UNION path_image b) = {})`
  (LABEL_TAC "crosses") THENL
   [USE_THEN "d_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "boundary_union" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `j:num`]
     PLANE_TRIANGULATED_DISK_CHORD_INTER_INSIDE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
     `c:(A->bool)->real^2->bool`; `{q j,q(n - 1)}:A->bool`;
     `a:real^1->real^2`; `b:real^1->real^2`;
     `d:real^1->real^2`;
     `(p:A->real^2)((q:num->A) j)`;
     `(p:A->real^2)(q(n - 1))`]
    PLANE_GRAPH_THETA_CLOSED_SIDE_VERTICES)
   (end_itlist CONJ
    [ASSUME `finite_simple_graph (V:A->bool) E`;
     ASSUME `plane_graph_embedding (V:A->bool) E p c`;
     ASSUME `{(q:num->A) j,q(n - 1)} IN E`;
     ASSUME `~((p:A->real^2)(q j) = p(q(n - 1)))`;
     ASSUME `arc(a:real^1->real^2)`;
     ASSUME
      `pathstart(a:real^1->real^2) =
       (p:A->real^2)((q:num->A) j)`;
     ASSUME
      `pathfinish(a:real^1->real^2) =
       (p:A->real^2)((q:num->A)(n - 1))`;
     ASSUME `arc(b:real^1->real^2)`;
     ASSUME
      `pathstart(b:real^1->real^2) =
       (p:A->real^2)((q:num->A) j)`;
     ASSUME
      `pathfinish(b:real^1->real^2) =
       (p:A->real^2)((q:num->A)(n - 1))`;
     ASSUME `arc(d:real^1->real^2)`;
     ASSUME
      `pathstart(d:real^1->real^2) =
       (p:A->real^2)((q:num->A) j)`;
     ASSUME
      `pathfinish(d:real^1->real^2) =
       (p:A->real^2)((q:num->A)(n - 1))`;
     ASSUME
      `path_image(a:real^1->real^2) INTER path_image b =
       {(p:A->real^2)((q:num->A) j),p(q(n - 1))}`;
     ASSUME
      `path_image(a:real^1->real^2) INTER path_image d =
       {(p:A->real^2)((q:num->A) j),p(q(n - 1))}`;
     ASSUME
      `path_image(b:real^1->real^2) INTER path_image d =
       {(p:A->real^2)((q:num->A) j),p(q(n - 1))}`;
     ASSUME
      `path_image(d:real^1->real^2) =
       (c:(A->bool)->real^2->bool) {q j,q(n - 1)}`;
     ASSUME
      `~(path_image(d:real^1->real^2) INTER
         inside(path_image a UNION path_image b) = {})`])) THEN
  INTRO_TAC "closed_inter closed_union overlap" THEN
  USE_THEN "conditions" (fun th ->
   MP_TAC(MATCH_MP
    (ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `j:num`;
      `a:real^1->real^2`; `b:real^1->real^2`;
      `d:real^1->real^2`]
     PLANE_TRIANGULATED_DISK_CHORD_EXPLICIT_SIDE_COMPONENTS)
    th)) THEN
  INTRO_TAC
   "left_boundary left_carrier left_component \
    right_boundary right_carrier right_component" THEN
  USE_THEN "conditions" (fun th ->
   MP_TAC(MATCH_MP
    (ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `j:num`;
      `a:real^1->real^2`; `b:real^1->real^2`;
      `d:real^1->real^2`]
     PLANE_TRIANGULATED_DISK_CHORD_EXPLICIT_SIDE_PARTITIONS)
    th)) THEN
  INTRO_TAC
   "vertices overlap_vertices edges chord_left chord_right" THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
     `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
     `outer:real^2->bool`; `j:num`;
     `a:real^1->real^2`; `b:real^1->real^2`;
     `d:real^1->real^2`]
    PLANE_TRIANGULATED_DISK_CHORD_EXPLICIT_SIDE_OUTER_FACE_VERTICES)
   (end_itlist CONJ
    [ASSUME
      `plane_triangulated_disk
        (V:A->bool) E p c q n outer`;
     ASSUME `~bounded(outer:real^2->bool)`;
     ASSUME `0 < j`;
     ASSUME `j + 2 < n`;
     ASSUME `{(q:num->A) j,q(n - 1)} IN E`;
     ASSUME `arc(a:real^1->real^2)`;
     ASSUME
      `pathstart(a:real^1->real^2) =
       (p:A->real^2)((q:num->A) j)`;
     ASSUME
      `pathfinish(a:real^1->real^2) =
       (p:A->real^2)((q:num->A)(n - 1))`;
     ASSUME
      `path_image(a:real^1->real^2) =
       UNIONS(IMAGE (c:(A->bool)->real^2->bool)
        (cyclic_split_left_boundary_edges (q:num->A) n j))`;
     ASSUME `arc(b:real^1->real^2)`;
     ASSUME
      `pathstart(b:real^1->real^2) =
       (p:A->real^2)((q:num->A) j)`;
     ASSUME
      `pathfinish(b:real^1->real^2) =
       (p:A->real^2)((q:num->A)(n - 1))`;
     ASSUME
      `path_image(b:real^1->real^2) =
       UNIONS(IMAGE (c:(A->bool)->real^2->bool)
        (cyclic_split_right_boundary_edges (q:num->A) n j))`;
     ASSUME `arc(d:real^1->real^2)`;
     ASSUME
      `pathstart(d:real^1->real^2) =
       (p:A->real^2)((q:num->A) j)`;
     ASSUME
      `pathfinish(d:real^1->real^2) =
       (p:A->real^2)((q:num->A)(n - 1))`;
     ASSUME
      `path_image(d:real^1->real^2) =
       (c:(A->bool)->real^2->bool) {q j,q(n - 1)}`;
     ASSUME
      `path_image(a:real^1->real^2) INTER path_image d =
       {(p:A->real^2)((q:num->A) j),p(q(n - 1))}`;
     ASSUME
      `path_image(b:real^1->real^2) INTER path_image d =
       {(p:A->real^2)((q:num->A) j),p(q(n - 1))}`])) THEN
  INTRO_TAC "left_face right_face" THEN
  SUBGOAL_THEN
   `plane_graph_carrier
      (plane_graph_closed_side_vertices
        (V:A->bool) p (path_image a UNION path_image d))
      (induced_subgraph_edges E
        (plane_graph_closed_side_vertices
          V p (path_image a UNION path_image d))) p c UNION
    plane_graph_carrier
      (plane_graph_closed_side_vertices
        V p (path_image b UNION path_image d))
      (induced_subgraph_edges E
        (plane_graph_closed_side_vertices
          V p (path_image b UNION path_image d))) p c =
    plane_graph_carrier V E p c`
  (LABEL_TAC "carrier_union") THENL
   [MATCH_MP_TAC PLANE_GRAPH_CARRIER_UNION THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_closed_side_vertices
      V p (path_image a UNION path_image d) SUBSET (V:A->bool)`
  (LABEL_TAC "left_subset") THENL
   [REWRITE_TAC[plane_graph_closed_side_vertices; SUBSET; IN_ELIM_THM] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_closed_side_vertices
      V p (path_image b UNION path_image d) SUBSET (V:A->bool)`
  (LABEL_TAC "right_subset") THENL
   [REWRITE_TAC[plane_graph_closed_side_vertices; SUBSET; IN_ELIM_THM] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle E
      (cyclic_split_left (q:num->A) n j) (j + 2)`
  (LABEL_TAC "left_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_SPLIT_LEFT THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle E
      (cyclic_split_right (q:num->A) j) (n - j)`
  (LABEL_TAC "right_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_SPLIT_RIGHT THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_vertices (cyclic_split_left (q:num->A) n j) (j + 2)
    SUBSET
    plane_graph_closed_side_vertices
      V p (path_image a UNION path_image d)`
  (LABEL_TAC "left_vertices") THENL
   [USE_THEN "left_face" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_ACCEPT_TAC PLANE_GRAPH_FACE_VERTICES_SUBSET;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_vertices (cyclic_split_right (q:num->A) j) (n - j)
    SUBSET
    plane_graph_closed_side_vertices
      V p (path_image b UNION path_image d)`
  (LABEL_TAC "right_vertices") THENL
   [USE_THEN "right_face" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_ACCEPT_TAC PLANE_GRAPH_FACE_VERTICES_SUBSET;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `closed(path_image(a:real^1->real^2) UNION path_image d)`
  (LABEL_TAC "left_closed") THENL
   [MATCH_MP_TAC CLOSED_UNION THEN CONJ_TAC THENL
     [MATCH_MP_TAC CLOSED_PATH_IMAGE THEN
      MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "a_arc" ACCEPT_TAC;
      MATCH_MP_TAC CLOSED_PATH_IMAGE THEN
      MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "d_arc" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `closed(path_image(b:real^1->real^2) UNION path_image d)`
  (LABEL_TAC "right_closed") THENL
   [MATCH_MP_TAC CLOSED_UNION THEN CONJ_TAC THENL
     [MATCH_MP_TAC CLOSED_PATH_IMAGE THEN
      MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "b_arc" ACCEPT_TAC;
      MATCH_MP_TAC CLOSED_PATH_IMAGE THEN
      MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "d_arc" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `bounded(path_image(a:real^1->real^2) UNION path_image d)`
  (LABEL_TAC "left_bounded") THENL
   [REWRITE_TAC[BOUNDED_UNION] THEN CONJ_TAC THENL
     [MATCH_MP_TAC BOUNDED_PATH_IMAGE THEN
      MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "a_arc" ACCEPT_TAC;
      MATCH_MP_TAC BOUNDED_PATH_IMAGE THEN
      MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "d_arc" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `bounded(path_image(b:real^1->real^2) UNION path_image d)`
  (LABEL_TAC "right_bounded") THENL
   [REWRITE_TAC[BOUNDED_UNION] THEN CONJ_TAC THENL
     [MATCH_MP_TAC BOUNDED_PATH_IMAGE THEN
      MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "b_arc" ACCEPT_TAC;
      MATCH_MP_TAC BOUNDED_PATH_IMAGE THEN
      MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "d_arc" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `path_image(d:real^1->real^2) SUBSET
    path_image a UNION path_image d`
  (LABEL_TAC "d_left") THENL
   [SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `path_image(d:real^1->real^2) SUBSET
    path_image b UNION path_image d`
  (LABEL_TAC "d_right") THENL
   [SET_TAC[];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`;
      `plane_graph_closed_side_vertices
        (V:A->bool) p (path_image a UNION path_image d)`;
      `cyclic_split_left (q:num->A) n j`; `j + 2`;
      `path_image(a:real^1->real^2) UNION path_image d`;
      `plane_graph_closed_side_vertices
        (V:A->bool) p (path_image b UNION path_image d)`;
      `induced_subgraph_edges E
        (plane_graph_closed_side_vertices
          (V:A->bool) p (path_image b UNION path_image d))`;
      `path_image(b:real^1->real^2) UNION path_image d`;
     `path_image(d:real^1->real^2)`]
     PLANE_TRIANGULATED_DISK_INDUCED_CLOSED_SIDE) THEN
    REPEAT CONJ_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_ARITH_TAC;
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`;
      `plane_graph_closed_side_vertices
        (V:A->bool) p (path_image b UNION path_image d)`;
      `cyclic_split_right (q:num->A) j`; `(n:num) - j`;
      `path_image(b:real^1->real^2) UNION path_image d`;
      `plane_graph_closed_side_vertices
        (V:A->bool) p (path_image a UNION path_image d)`;
      `induced_subgraph_edges E
        (plane_graph_closed_side_vertices
          (V:A->bool) p (path_image a UNION path_image d))`;
      `path_image(a:real^1->real^2) UNION path_image d`;
     `path_image(d:real^1->real^2)`]
     PLANE_TRIANGULATED_DISK_INDUCED_CLOSED_SIDE) THEN
    REPEAT CONJ_TAC THEN
    ASM_REWRITE_TAC[INTER_COMM; UNION_COMM] THEN
    ASM_ARITH_TAC]);;
(* Induction restricted to the geometrically distinguished unbounded face.   *)

let PLANE_TRIANGULATED_DISK_DELETE_LAST_OUTER_SUBSET = prove
 (`!V E p c q n outer k w oldouter.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        graph_neighbors E (q(n - 1)) = cyclic_vertices w (k + 2) /\
        w 0 = q(n - 2) /\
        w(k + 1) = q 0 /\
        plane_triangulated_disk
          (V DELETE q(n - 1))
          (induced_subgraph_edges E (V DELETE q(n - 1)))
          p c (cyclic_delete_last q w n) (n - 1 + k) oldouter
        ==> ?newouter.
              outer SUBSET newouter /\
              plane_triangulated_disk
                (V DELETE q(n - 1))
                (induced_subgraph_edges E (V DELETE q(n - 1)))
                p c (cyclic_delete_last q w n) (n - 1 + k) newouter`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "disk neighbors first last olddisk" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN
   `(q:num->A)(n - 1) IN cyclic_vertices q n`
  (LABEL_TAC "last_boundary") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `(q:num->A)(n - 1)`]
   PLANE_TRIANGULATED_DISK_DELETE_VERTEX_OUTER_COMPONENT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@newouter. newouter_component outer_subset last_newouter" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `(q:num->A)(n - 1)`;
    `newouter:real^2->bool`]
   PLANE_TRIANGULATED_DISK_DELETE_VERTEX_FACE_VERTICES) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "face_vertices") THEN
  SUBGOAL_THEN
   `plane_graph_face_vertices (V DELETE q(n - 1))
      (induced_subgraph_edges E (V DELETE q(n - 1)))
      p c newouter =
    cyclic_vertices (cyclic_delete_last (q:num->A) w n) (n - 1 + k)`
  (LABEL_TAC "new_boundary") THENL
   [USE_THEN "face_vertices" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC EQ_SYM THEN
    MATCH_MP_TAC CYCLIC_VERTICES_CYCLIC_DELETE_LAST THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP PLANE_TRIANGULATED_DISK_INVARIANTS
   (ASSUME
    `plane_triangulated_disk
      ((V:A->bool) DELETE (q:num->A)(n - 1))
      (induced_subgraph_edges (E:(A->bool)->bool)
        (V DELETE q(n - 1)))
      (p:A->real^2) (c:(A->bool)->real^2->bool)
      (cyclic_delete_last q w n) (n - 1 + k)
      (oldouter:real^2->bool)`)) THEN
  INTRO_TAC
   "_ _ newlarge new_injective new_boundary_edges _ _ _" THEN
  SUBGOAL_THEN
   `simple_graph_cycle
      (induced_subgraph_edges (E:(A->bool)->bool)
        ((V:A->bool) DELETE (q:num->A)(n - 1)))
      (cyclic_delete_last (q:num->A) (w:num->A) n) (n - 1 + k)`
  (LABEL_TAC "new_cycle") THENL
   [REWRITE_TAC[simple_graph_cycle] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `newouter:real^2->bool` THEN CONJ_TAC THENL
   [USE_THEN "outer_subset" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `(q:num->A)(n - 1)`;
      `newouter:real^2->bool`;
      `cyclic_delete_last (q:num->A) (w:num->A) n`;
      `n - 1 + k`]
     PLANE_TRIANGULATED_DISK_DELETE_VERTEX) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "disk" ACCEPT_TAC;
      USE_THEN "last_boundary" ACCEPT_TAC;
      USE_THEN "newouter_component" ACCEPT_TAC;
      USE_THEN "outer_subset" ACCEPT_TAC;
      USE_THEN "last_newouter" ACCEPT_TAC;
      USE_THEN "new_boundary" ACCEPT_TAC;
      USE_THEN "new_cycle" ACCEPT_TAC]]);;

let PLANE_TRIANGULATED_DISK_CHORD_SPLIT_UNBOUNDED_RECURSIVE_STEP =
  prove
 (`!V E p c q n outer j V1 E1 outer1 V2 E2 outer2.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        0 < j /\ j + 2 < n /\
        plane_triangulated_disk
          V1 E1 p c (cyclic_split_left q n j) (j + 2) outer1 /\
        ~bounded outer1 /\
        plane_triangulated_disk
          V2 E2 p c (cyclic_split_right q j) (n - j) outer2 /\
        ~bounded outer2 /\
        V1 UNION V2 = V /\
        E1 UNION E2 = E /\
        V1 INTER V2 = {q j,q(n - 1)} /\
        {q j,q(n - 1)} IN E1 /\
        {q j,q(n - 1)} IN E2 /\
        (!V' E' q' m newouter.
             CARD(V':A->bool) < CARD V /\
             ~bounded newouter /\
             plane_triangulated_disk V' E' p c q' m newouter
             ==> recursive_triangulated_disk V' E' q' m)
        ==> recursive_triangulated_disk V E q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk jpositive bound left_disk left_unbounded \
    right_disk right_unbounded vertices edges overlap \
    chord_left chord_right induction" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  MP_TAC(ISPECL
   [`V1:A->bool`; `E1:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`;
    `cyclic_split_left (q:num->A) n j`; `j + 2`;
    `outer1:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "left_graph left_embedding left_large left_injective \
    left_boundary_edges left_boundary_subset left_outer_component \
    left_boundary" THEN
  USE_THEN "right_disk"
   (MP_TAC o MATCH_MP PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  INTRO_TAC
   "right_graph right_embedding right_large right_injective \
    right_boundary_edges right_boundary_subset right_outer_component \
    right_boundary" THEN
  SUBGOAL_THEN `(q:num->A) 0 IN V1`
  (LABEL_TAC "q0_left") THENL
   [USE_THEN "left_boundary_subset"
     (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `0` THEN
    ASM_REWRITE_TAC[cyclic_split_left] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((q:num->A) 0 IN V2)`
  (LABEL_TAC "q0_not_right") THENL
   [DISCH_THEN(LABEL_TAC "q0_right") THEN
    SUBGOAL_THEN `(q:num->A) 0 IN {q j,q(n - 1)}`
    (LABEL_TAC "q0_overlap") THENL
     [USE_THEN "overlap" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[IN_INTER] THEN ASM_REWRITE_TAC[];
      USE_THEN "q0_overlap" MP_TAC THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN
      DISCH_THEN(DISJ_CASES_THEN2
       (LABEL_TAC "q0_qj") (LABEL_TAC "q0_qlast")) THENL
       [USE_THEN "q_injective"
         (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
        DISCH_THEN(MP_TAC o SPECL [`0`; `j:num`]) THEN
        ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
        USE_THEN "q_injective"
         (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
        DISCH_THEN(MP_TAC o SPECL [`0`; `n - 1`]) THEN
        ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:num->A) (j + 1) IN V2`
  (LABEL_TAC "qnext_right") THENL
   [USE_THEN "right_boundary_subset"
     (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `1` THEN
    ASM_REWRITE_TAC[cyclic_split_right] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((q:num->A) (j + 1) IN V1)`
  (LABEL_TAC "qnext_not_left") THENL
   [DISCH_THEN(LABEL_TAC "qnext_left") THEN
    SUBGOAL_THEN `(q:num->A) (j + 1) IN {q j,q(n - 1)}`
    (LABEL_TAC "qnext_overlap") THENL
     [USE_THEN "overlap" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[IN_INTER] THEN ASM_REWRITE_TAC[];
      USE_THEN "qnext_overlap" MP_TAC THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN
      DISCH_THEN(DISJ_CASES_THEN2
       (LABEL_TAC "qnext_qj") (LABEL_TAC "qnext_qlast")) THENL
       [USE_THEN "q_injective"
         (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
        DISCH_THEN(MP_TAC o SPECL [`j + 1`; `j:num`]) THEN
        ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
        USE_THEN "q_injective"
         (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
        DISCH_THEN(MP_TAC o SPECL [`j + 1`; `n - 1`]) THEN
        ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(V1:A->bool) < CARD(V:A->bool)`
  (LABEL_TAC "left_smaller") THENL
   [MATCH_MP_TAC CARD_PSUBSET THEN
    CONJ_TAC THENL
     [REWRITE_TAC[PSUBSET] THEN CONJ_TAC THENL
       [USE_THEN "vertices" (fun th -> REWRITE_TAC[GSYM th]) THEN
        REWRITE_TAC[SUBSET_UNION];
        DISCH_THEN(LABEL_TAC "left_all") THEN
        USE_THEN "qnext_not_left" (MATCH_MP_TAC o NOT_ELIM) THEN
        USE_THEN "left_all" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "vertices" (fun th -> REWRITE_TAC[GSYM th]) THEN
        REWRITE_TAC[IN_UNION] THEN DISJ2_TAC THEN
        USE_THEN "qnext_right" ACCEPT_TAC];
      USE_THEN "graph"
       (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[finite_simple_graph])];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(V2:A->bool) < CARD(V:A->bool)`
  (LABEL_TAC "right_smaller") THENL
   [MATCH_MP_TAC CARD_PSUBSET THEN
    CONJ_TAC THENL
     [REWRITE_TAC[PSUBSET] THEN CONJ_TAC THENL
       [USE_THEN "vertices" (fun th -> REWRITE_TAC[GSYM th]) THEN
        REWRITE_TAC[SUBSET_UNION];
        DISCH_THEN(LABEL_TAC "right_all") THEN
        USE_THEN "q0_not_right" (MATCH_MP_TAC o NOT_ELIM) THEN
        USE_THEN "right_all" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "vertices" (fun th -> REWRITE_TAC[GSYM th]) THEN
        REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
        USE_THEN "q0_left" ACCEPT_TAC];
      USE_THEN "graph"
       (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[finite_simple_graph])];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `recursive_triangulated_disk
      (V1:A->bool) E1 (cyclic_split_left q n j) (j + 2)`
  (LABEL_TAC "left_recursive") THENL
   [USE_THEN "induction" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `outer1:real^2->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `recursive_triangulated_disk
      (V2:A->bool) E2 (cyclic_split_right q j) (n - j)`
  (LABEL_TAC "right_recursive") THENL
   [USE_THEN "induction" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `outer2:real^2->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V1:A->bool`; `E1:(A->bool)->bool`;
    `V2:A->bool`; `E2:(A->bool)->bool`;
    `q:num->A`; `n:num`; `j:num`]
   (CONJUNCT2(CONJUNCT2 recursive_triangulated_disk_RULES))) THEN
  ASM_REWRITE_TAC[]);;

let PLANE_TRIANGULATED_DISK_CHORD_UNBOUNDED_RECURSIVE_STEP = prove
 (`!V E p c q n outer j.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        ~bounded outer /\
        0 < j /\ j + 2 < n /\ {q j,q(n - 1)} IN E /\
        (!V' E' q' m newouter.
             CARD(V':A->bool) < CARD V /\
             ~bounded newouter /\
             plane_triangulated_disk V' E' p c q' m newouter
             ==> recursive_triangulated_disk V' E' q' m)
        ==> recursive_triangulated_disk V E q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk outer_unbounded jpositive bound chord induction" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `j:num`]
   PLANE_TRIANGULATED_DISK_CHORD_EXPLICIT_SPLIT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@a b d. a_arc a_start a_finish a_image \
    b_arc b_start b_finish b_image \
    d_arc d_start d_finish d_image \
    ab_inter ad_inter bd_inter boundary_union \
    sides_disjoint sides_union" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `j:num`;
    `a:real^1->real^2`; `b:real^1->real^2`;
    `d:real^1->real^2`]
   PLANE_TRIANGULATED_DISK_CHORD_EXPLICIT_SIDE_DISKS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "left_disk right_disk" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `j:num`;
    `a:real^1->real^2`; `b:real^1->real^2`;
    `d:real^1->real^2`]
   PLANE_TRIANGULATED_DISK_CHORD_EXPLICIT_SIDE_PARTITIONS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "vertices overlap edges chord_left chord_right" THEN
  SUBGOAL_THEN
   `~bounded(outside(path_image(a:real^1->real^2) UNION path_image d))`
  (LABEL_TAC "left_unbounded") THENL
   [MATCH_MP_TAC UNBOUNDED_OUTSIDE THEN
    REWRITE_TAC[BOUNDED_UNION] THEN CONJ_TAC THENL
     [MATCH_MP_TAC BOUNDED_PATH_IMAGE THEN
      MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "a_arc" ACCEPT_TAC;
      MATCH_MP_TAC BOUNDED_PATH_IMAGE THEN
      MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "d_arc" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~bounded(outside(path_image(b:real^1->real^2) UNION path_image d))`
  (LABEL_TAC "right_unbounded") THENL
   [MATCH_MP_TAC UNBOUNDED_OUTSIDE THEN
    REWRITE_TAC[BOUNDED_UNION] THEN CONJ_TAC THENL
     [MATCH_MP_TAC BOUNDED_PATH_IMAGE THEN
      MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "b_arc" ACCEPT_TAC;
      MATCH_MP_TAC BOUNDED_PATH_IMAGE THEN
      MATCH_MP_TAC ARC_IMP_PATH THEN USE_THEN "d_arc" ACCEPT_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `j:num`;
    `plane_graph_closed_side_vertices
      (V:A->bool) p (path_image a UNION path_image d)`;
    `induced_subgraph_edges E
      (plane_graph_closed_side_vertices
        (V:A->bool) p (path_image a UNION path_image d))`;
    `outside(path_image(a:real^1->real^2) UNION path_image d)`;
    `plane_graph_closed_side_vertices
      (V:A->bool) p (path_image b UNION path_image d)`;
    `induced_subgraph_edges E
      (plane_graph_closed_side_vertices
        (V:A->bool) p (path_image b UNION path_image d))`;
    `outside(path_image(b:real^1->real^2) UNION path_image d)`]
   PLANE_TRIANGULATED_DISK_CHORD_SPLIT_UNBOUNDED_RECURSIVE_STEP) THEN
  ASM_REWRITE_TAC[]);;

let PLANE_TRIANGULATED_DISK_CHORDLESS_UNBOUNDED_RECURSIVE_STEP =
  prove
 (`!V E p c q n outer.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        ~bounded outer /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        3 < CARD V /\
        (!V' E' q' m newouter.
             CARD(V':A->bool) < CARD V /\
             ~bounded newouter /\
             plane_triangulated_disk V' E' p c q' m newouter
             ==> recursive_triangulated_disk V' E' q' m)
        ==> recursive_triangulated_disk V E q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "disk outer_unbounded chordless vertices_large induction" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN `(q:num->A)(n - 1) IN V`
  (LABEL_TAC "last_vertex") THENL
   [USE_THEN "boundary_subset"
     (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_CHORDLESS_OUTER_FRONTIER_EDGES_AT_LAST) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "left_boundary right_boundary" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_DELETE_LAST_CHORDLESS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@k w oldouter. neighbors w_injective first last olddisk" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`; `k:num`; `w:num->A`;
    `oldouter:real^2->bool`]
   PLANE_TRIANGULATED_DISK_DELETE_LAST_OUTER_SUBSET) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@newouter. outer_subset newdisk" THEN
  SUBGOAL_THEN
   `CARD((V:A->bool) DELETE q(n - 1)) < CARD V`
  (LABEL_TAC "smaller") THENL
   [SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite") THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`(q:num->A)(n - 1)`; `V:A->bool`]
     CARD_DELETE) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~bounded(newouter:real^2->bool)`
  (LABEL_TAC "newouter_unbounded") THENL
   [DISCH_THEN(LABEL_TAC "newouter_bounded") THEN
    USE_THEN "outer_unbounded" (MATCH_MP_TAC o NOT_ELIM) THEN
    MATCH_MP_TAC BOUNDED_SUBSET THEN
    EXISTS_TAC `newouter:real^2->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `recursive_triangulated_disk
      ((V:A->bool) DELETE q(n - 1))
      (induced_subgraph_edges E (V DELETE q(n - 1)))
      (cyclic_delete_last q w n) (n - 1 + k)`
  (LABEL_TAC "recursive") THENL
   [USE_THEN "induction"
     (MATCH_MP_TAC o SPECL
      [`(V:A->bool) DELETE (q:num->A)(n - 1)`;
       `induced_subgraph_edges (E:(A->bool)->bool)
         (V DELETE q(n - 1))`;
       `cyclic_delete_last (q:num->A) (w:num->A) n`;
       `n - 1 + k`; `newouter:real^2->bool`]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
    `n:num`; `k:num`; `w:num->A`]
   RECURSIVE_TRIANGULATED_DISK_DELETE_BOUNDARY_VERTEX) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    USE_THEN "last_vertex" ACCEPT_TAC;
    USE_THEN "recursive" ACCEPT_TAC;
    USE_THEN "nlarge" ACCEPT_TAC;
    USE_THEN "q_injective" ACCEPT_TAC;
    USE_THEN "neighbors" ACCEPT_TAC;
    USE_THEN "first" ACCEPT_TAC;
    USE_THEN "last" ACCEPT_TAC]);;

let PLANE_TRIANGULATED_DISK_UNBOUNDED_RECURSIVE_STEP_GUARDED =
  prove
 (`!V E p c q n outer.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        ~bounded outer /\
        3 < CARD V /\
        (!V' E' q' m newouter.
             CARD(V':A->bool) < CARD V /\
             ~bounded newouter /\
             plane_triangulated_disk V' E' p c q' m newouter
             ==> recursive_triangulated_disk V' E' q' m)
        ==> recursive_triangulated_disk V E q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "disk outer_unbounded vertices_large induction" THEN
  ASM_CASES_TAC
   `?j:num. 0 < j /\ j + 2 < n /\
            {(q:num->A) j,q(n - 1)} IN E` THENL
   [FIRST_X_ASSUM
     (X_CHOOSE_THEN `j:num`
      (fun th -> MP_TAC th THEN INTRO_TAC "jpositive bound chord")) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`; `j:num`]
     PLANE_TRIANGULATED_DISK_CHORD_UNBOUNDED_RECURSIVE_STEP) THEN
    ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "no_chord") THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`]
     PLANE_TRIANGULATED_DISK_CHORDLESS_UNBOUNDED_RECURSIVE_STEP) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `j:num` THEN INTRO_TAC "jpositive bound" THEN
    DISCH_THEN(LABEL_TAC "chord") THEN
    USE_THEN "no_chord" (MATCH_MP_TAC o NOT_ELIM) THEN
    EXISTS_TAC `j:num` THEN ASM_REWRITE_TAC[]]);;

let PLANE_TRIANGULATED_DISK_UNBOUNDED_RECURSIVE = prove
 (`!V E p c q n outer.
        plane_triangulated_disk (V:A->bool) E p c q n outer /\
        ~bounded outer
        ==> recursive_triangulated_disk V E q n`,
  GEN_TAC THEN WF_INDUCT_TAC `CARD(V:A->bool)` THEN
  POP_ASSUM(LABEL_TAC "induction") THEN
  REPEAT GEN_TAC THEN INTRO_TAC "disk outer_unbounded" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "graph embedding nlarge q_injective boundary_edges boundary_subset \
    outer_component boundary" THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite") THENL
   [USE_THEN "graph"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[finite_simple_graph]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(n:num) <= CARD(V:A->bool)`
  (LABEL_TAC "boundary_card") THENL
   [SUBGOAL_THEN
     `CARD(cyclic_vertices (q:num->A) n) <= CARD(V:A->bool)`
    MP_TAC THENL
     [MATCH_MP_TAC CARD_SUBSET THEN ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[CARD_CYCLIC_VERTICES]];
    ALL_TAC] THEN
  ASM_CASES_TAC `3 < CARD(V:A->bool)` THENL
   [FIRST_X_ASSUM(LABEL_TAC "vertices_large") THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `q:num->A`; `n:num`;
      `outer:real^2->bool`]
     PLANE_TRIANGULATED_DISK_UNBOUNDED_RECURSIVE_STEP_GUARDED) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC
     [`V':A->bool`; `E':(A->bool)->bool`; `q':num->A`;
      `m:num`; `newouter:real^2->bool`] THEN
    INTRO_TAC "smaller newouter_unbounded newdisk" THEN
    USE_THEN "induction" (MP_TAC o SPEC `V':A->bool`) THEN
    ANTS_TAC THENL
     [USE_THEN "smaller" ACCEPT_TAC;
      DISCH_THEN(fun ith ->
       MATCH_MP_TAC(SPECL
        [`E':(A->bool)->bool`; `p:A->real^2`;
         `c:(A->bool)->real^2->bool`; `q':num->A`; `m:num`;
         `newouter:real^2->bool`] ith)) THEN
      ASM_REWRITE_TAC[]];
    FIRST_X_ASSUM(LABEL_TAC "vertices_small") THEN
    SUBGOAL_THEN `(n:num) = 3 /\ CARD(V:A->bool) = 3`
    (CONJUNCTS_THEN2 (LABEL_TAC "n_three") (LABEL_TAC "card_three"))
    THENL
     [ASM_ARITH_TAC;
      USE_THEN "n_three" SUBST_ALL_TAC THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `c:(A->bool)->real^2->bool`; `q:num->A`;
        `outer:real^2->bool`]
       PLANE_TRIANGULATED_DISK_CARD_3_RECURSIVE) THEN
      ASM_REWRITE_TAC[]]]);;
(* The maximal-triangulation bridge and Fary's theorem.                      *)

let MAXIMAL_PLANAR_GRAPH_LARGE_RECURSIVE = prove
 (`!V E.
        planar_graph (V:A->bool) E /\
        (!G. E PSUBSET G /\
             G SUBSET complete_graph_edges V
             ==> ~planar_graph V G) /\
        4 <= CARD V
        ==> ?q:num->A. recursive_triangulated_disk V E q 3`,
  REPEAT GEN_TAC THEN INTRO_TAC "planar maximal vertices_large" THEN
  USE_THEN "planar" MP_TAC THEN
  REWRITE_TAC[planar_graph] THEN
  INTRO_TAC "graph @p c. embedding" THEN
  SUBGOAL_THEN
   `bounded(plane_graph_carrier
      (V:A->bool) E (p:A->real^2) (c:(A->bool)->real^2->bool))`
  (LABEL_TAC "carrier_bounded") THENL
   [MATCH_MP_TAC COMPACT_IMP_BOUNDED THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `E:(A->bool)->bool`]
     PLANE_GRAPH_CARRIER_COMPACT) THEN
    ASM_REWRITE_TAC[SUBSET_REFL];
    ALL_TAC] THEN
  MP_TAC(ISPEC
   `(:real^2) DIFF
    plane_graph_carrier
      (V:A->bool) E (p:A->real^2) (c:(A->bool)->real^2->bool)`
   COBOUNDED_UNBOUNDED_COMPONENTS) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[SET_RULE
     `(:real^2) DIFF ((:real^2) DIFF s) = s`] THEN
    USE_THEN "carrier_bounded" ACCEPT_TAC;
    INTRO_TAC "@outer. outer_component outer_unbounded"] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `outer:real^2->bool`]
   MAXIMAL_PLANAR_GRAPH_PLANE_TRIANGULATED_DISK) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      USE_THEN "embedding" ACCEPT_TAC;
      USE_THEN "maximal" ACCEPT_TAC;
      ASM_ARITH_TAC;
      USE_THEN "outer_component" ACCEPT_TAC];
    INTRO_TAC "@q. disk"] THEN
  EXISTS_TAC `q:num->A` THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `c:(A->bool)->real^2->bool`; `q:num->A`; `3`;
    `outer:real^2->bool`]
   PLANE_TRIANGULATED_DISK_UNBOUNDED_RECURSIVE) THEN
  ASM_REWRITE_TAC[]);;

let FARY = prove
 (`!V E.
        planar_graph (V:A->bool) E
        ==> straight_line_planar_graph V E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "planar") THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`]
   FARY_REDUCTION_TO_LARGE_RECURSIVE_TRIANGULATIONS) THEN
  CONJ_TAC THENL
   [USE_THEN "planar" ACCEPT_TAC;
    X_GEN_TAC `E':(A->bool)->bool` THEN
    INTRO_TAC "extended maximal vertices_large" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E':(A->bool)->bool`]
     MAXIMAL_PLANAR_GRAPH_LARGE_RECURSIVE) THEN
    ASM_REWRITE_TAC[]]);;

let PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR_GRAPH = prove
 (`!V E.
        planar_graph (V:A->bool) E <=>
        straight_line_planar_graph V E`,
  MESON_TAC[FARY; STRAIGHT_LINE_PLANAR_IMP_PLANAR_GRAPH]);;

let PLANAR_GRAPH_EQ_STRAIGHT_LINE = prove
 (`!V E.
        planar_graph (V:A->bool) E <=>
        finite_simple_graph V E /\
        ?p. straight_line_embedding V E p`,
  REWRITE_TAC[PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR_GRAPH;
              straight_line_planar_graph]);;

(* ========================================================================= *)
(* Recursive and Euler-rotation characterizations of planarity.              *)
(* ========================================================================= *)

(* ------------------------------------------------------------------------- *)
(* Recursive triangulation certificates.                                     *)
(*                                                                           *)
(* Apart from the unavoidable small cases, a graph is recursively planar     *)
(* when it is a spanning subgraph of a recursively triangulated disk whose   *)
(* distinguished boundary is a triangle.                                     *)
(* ------------------------------------------------------------------------- *)

let recursive_planar_graph = new_definition
 `recursive_planar_graph (V:A->bool) (E:(A->bool)->bool) <=>
        finite_simple_graph V E /\
        (CARD V <= 2 \/
         ?E' q:num->A.
              E SUBSET E' /\
              recursive_triangulated_disk V E' q 3)`;;

let RECURSIVE_PLANAR_GRAPH_IMP_STRAIGHT_LINE_PLANAR = prove
 (`!V E.
        recursive_planar_graph (V:A->bool) E
        ==> straight_line_planar_graph V E`,
  REPEAT GEN_TAC THEN REWRITE_TAC[recursive_planar_graph] THEN
  INTRO_TAC "graph certificate" THEN
  USE_THEN "certificate"
   (DISJ_CASES_THEN2 (LABEL_TAC "small") (LABEL_TAC "extension")) THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_CARD_LE_2_IMP_STRAIGHT_LINE_PLANAR THEN
    ASM_REWRITE_TAC[];
    USE_THEN "extension"
     (X_CHOOSE_THEN `E':(A->bool)->bool`
      (X_CHOOSE_THEN `q:num->A`
       (CONJUNCTS_THEN2 (LABEL_TAC "subset") (LABEL_TAC "recursive")))) THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E':(A->bool)->bool`; `q:num->A`]
     RECURSIVE_TRIANGULATED_DISK_3_IMP_STRAIGHT_LINE_PLANAR) THEN
    ASM_REWRITE_TAC[straight_line_planar_graph] THEN
    INTRO_TAC "extended_graph @p. embedding" THEN
    EXISTS_TAC `p:A->real^2` THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E':(A->bool)->bool`; `E:(A->bool)->bool`;
      `p:A->real^2`]
     STRAIGHT_LINE_EMBEDDING_SUBSET_EDGES) THEN
    ASM_REWRITE_TAC[]]);;

let PLANAR_GRAPH_IMP_RECURSIVE_PLANAR_GRAPH = prove
 (`!V E.
        planar_graph (V:A->bool) E
        ==> recursive_planar_graph V E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "planar") THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "planar"
     (ACCEPT_TAC o CONJUNCT1 o
      REWRITE_RULE[planar_graph]);
    ALL_TAC] THEN
  REWRITE_TAC[recursive_planar_graph] THEN
  CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `CARD(V:A->bool) <= 2` THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`]
    MAXIMAL_PLANAR_GRAPH_EXTENSION) THEN
  ANTS_TAC THENL
   [USE_THEN "planar" ACCEPT_TAC;
    INTRO_TAC "@E'. subset extended maximal"] THEN
  EXISTS_TAC `E':(A->bool)->bool` THEN
  USE_THEN "subset" (fun th -> REWRITE_TAC[th]) THEN
  ASM_CASES_TAC `CARD(V:A->bool) = 3` THENL
   [MP_TAC(ISPECL [`V:A->bool`; `E':(A->bool)->bool`]
      MAXIMAL_PLANAR_GRAPH_CARD_3_RECURSIVE) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(ISPECL [`V:A->bool`; `E':(A->bool)->bool`]
      MAXIMAL_PLANAR_GRAPH_LARGE_RECURSIVE) THEN
    ASM_REWRITE_TAC[] THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      DISCH_THEN ACCEPT_TAC]]);;

let RECURSIVE_PLANAR_GRAPH_EQ_PLANAR_GRAPH = prove
 (`!V E.
        recursive_planar_graph (V:A->bool) E <=>
        planar_graph V E`,
  REPEAT GEN_TAC THEN EQ_TAC THENL
   [MESON_TAC[RECURSIVE_PLANAR_GRAPH_IMP_STRAIGHT_LINE_PLANAR;
              STRAIGHT_LINE_PLANAR_IMP_PLANAR_GRAPH];
    MATCH_ACCEPT_TAC PLANAR_GRAPH_IMP_RECURSIVE_PLANAR_GRAPH]);;

let PLANAR_GRAPH_EQ_RECURSIVE_PLANAR_GRAPH = prove
 (`!V E.
        planar_graph (V:A->bool) E <=>
        recursive_planar_graph V E`,
  MESON_TAC[RECURSIVE_PLANAR_GRAPH_EQ_PLANAR_GRAPH]);;

let PLANAR_GRAPH_EQ_RECURSIVE_TRIANGULATION = prove
 (`!V E.
        planar_graph (V:A->bool) E <=>
        finite_simple_graph V E /\
        (CARD V <= 2 \/
         ?E' q:num->A.
              E SUBSET E' /\
              recursive_triangulated_disk V E' q 3)`,
  REWRITE_TAC[PLANAR_GRAPH_EQ_RECURSIVE_PLANAR_GRAPH;
              recursive_planar_graph]);;

let RECURSIVE_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR = prove
 (`!V E.
        recursive_planar_graph (V:A->bool) E <=>
        straight_line_planar_graph V E`,
  REPEAT GEN_TAC THEN EQ_TAC THENL
   [MATCH_ACCEPT_TAC RECURSIVE_PLANAR_GRAPH_IMP_STRAIGHT_LINE_PLANAR;
    MESON_TAC[STRAIGHT_LINE_PLANAR_IMP_PLANAR_GRAPH;
              PLANAR_GRAPH_IMP_RECURSIVE_PLANAR_GRAPH]]);;

(* ------------------------------------------------------------------------- *)
(* Rotation systems and their face orbits for finite simple graphs.          *)
(*                                                                           *)
(* The combinatorial map machinery is kept independent of geometric          *)
(* embeddings.                                                               *)
(* ------------------------------------------------------------------------- *)

let reverse_dart = new_definition
 `reverse_dart (d:A#A) = (SND d,FST d)`;;

let REVERSE_DART_PAIR = prove
 (`!u v:A. reverse_dart(u,v) = (v,u)`,
  REWRITE_TAC[reverse_dart; FST; SND]);;

let REVERSE_DART_INVOLUTION = prove
 (`!d:A#A. reverse_dart(reverse_dart d) = d`,
  REWRITE_TAC[FORALL_PAIR_THM; REVERSE_DART_PAIR]);;

let DART_EDGE_REVERSE = prove
 (`!d:A#A. dart_edge(reverse_dart d) = dart_edge d`,
  REWRITE_TAC[FORALL_PAIR_THM; DART_EDGE_PAIR; REVERSE_DART_PAIR] THEN
  SET_TAC[]);;

let GRAPH_DARTS_REVERSE = prove
 (`!E d:A#A.
        reverse_dart d IN graph_darts E <=> d IN graph_darts E`,
  REWRITE_TAC[graph_darts; IN_ELIM_THM; DART_EDGE_REVERSE]);;

let GRAPH_DARTS_SUBSET_CROSS = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> graph_darts E SUBSET V CROSS V`,
  REWRITE_TAC[SUBSET; FORALL_PAIR_THM; IN_CROSS] THEN
  MESON_TAC[FINITE_SIMPLE_GRAPH_DART]);;

let FINITE_GRAPH_DARTS = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> FINITE(graph_darts E)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC `(V:A->bool) CROSS V` THEN
  CONJ_TAC THENL
   [ASM_MESON_TAC[FINITE_CROSS; finite_simple_graph];
    MATCH_MP_TAC GRAPH_DARTS_SUBSET_CROSS THEN ASM_REWRITE_TAC[]]);;

let REVERSE_DART_NO_FIXEDPOINT = prove
 (`!V E d:A#A.
        finite_simple_graph V E /\ d IN graph_darts E
        ==> ~(reverse_dart d = d)`,
  REWRITE_TAC[FORALL_PAIR_THM; REVERSE_DART_PAIR; PAIR_EQ] THEN
  MESON_TAC[FINITE_SIMPLE_GRAPH_DART]);;

let GRAPH_NEIGHBORS_SYM = prove
 (`!E u v:A.
        v IN graph_neighbors E u <=> u IN graph_neighbors E v`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
  SUBGOAL_THEN `{u:A,v} = {v,u}` SUBST1_TAC THENL
   [SET_TAC[];
    REFL_TAC]);;

let FINITE_GRAPH_NEIGHBORS = prove
 (`!V E u.
        finite_simple_graph (V:A->bool) E
        ==> FINITE(graph_neighbors E u)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC `V:A->bool` THEN
  CONJ_TAC THENL
   [ASM_MESON_TAC[finite_simple_graph];
    REWRITE_TAC[SUBSET] THEN X_GEN_TAC `v:A` THEN DISCH_TAC THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Local rotations and the induced permutation of directed edge-sides.       *)
(* ------------------------------------------------------------------------- *)

let graph_reverse_dart = new_definition
 `graph_reverse_dart (E:(A->bool)->bool) (d:A#A) =
        if d IN graph_darts E then reverse_dart d else d`;;

let outgoing_darts = new_definition
 `outgoing_darts (E:(A->bool)->bool) u =
        {d | d IN graph_darts E /\ FST d = u}`;;

let graph_rotation = new_definition
 `graph_rotation (E:(A->bool)->bool) (r:(A#A)->A#A) <=>
        r permutes graph_darts E /\
        (!d. d IN graph_darts E ==> FST(r d) = FST d) /\
        (!d d'. d IN graph_darts E /\ d' IN graph_darts E /\
                 FST d = FST d'
                 ==> ?n. ITER n r d = d')`;;

let graph_face_successor = new_definition
 `graph_face_successor
      (E:(A->bool)->bool) (r:(A#A)->A#A) =
        r o graph_reverse_dart E`;;

let graph_face = new_definition
 `graph_face (E:(A->bool)->bool) (r:(A#A)->A#A) d =
        {d' | ?n. ITER n (graph_face_successor E r) d = d'}`;;

let FST_REVERSE_DART = prove
 (`!d:A#A. FST(reverse_dart d) = SND d`,
  REWRITE_TAC[FORALL_PAIR_THM; REVERSE_DART_PAIR; FST; SND]);;

let SND_REVERSE_DART = prove
 (`!d:A#A. SND(reverse_dart d) = FST d`,
  REWRITE_TAC[FORALL_PAIR_THM; REVERSE_DART_PAIR; FST; SND]);;

let GRAPH_REVERSE_DART_IN = prove
 (`!E d:A#A.
        d IN graph_darts E
        ==> graph_reverse_dart E d = reverse_dart d`,
  SIMP_TAC[graph_reverse_dart]);;

let GRAPH_REVERSE_DART_OUT = prove
 (`!E d:A#A.
        ~(d IN graph_darts E)
        ==> graph_reverse_dart E d = d`,
  SIMP_TAC[graph_reverse_dart]);;

let GRAPH_REVERSE_DART_INVOLUTION = prove
 (`!E d:A#A.
        graph_reverse_dart E (graph_reverse_dart E d) = d`,
  REPEAT GEN_TAC THEN ASM_CASES_TAC `(d:A#A) IN graph_darts E` THENL
   [SUBGOAL_THEN `reverse_dart(d:A#A) IN graph_darts E` ASSUME_TAC THENL
     [ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE];
      ASM_SIMP_TAC[GRAPH_REVERSE_DART_IN; REVERSE_DART_INVOLUTION]];
    ASM_SIMP_TAC[graph_reverse_dart]]);;

let GRAPH_REVERSE_DART_PERMUTES = prove
 (`!E:(A->bool)->bool.
        graph_reverse_dart E permutes graph_darts E`,
  GEN_TAC THEN MATCH_MP_TAC PERMUTES_INVOLUTION THEN
  REWRITE_TAC[GRAPH_REVERSE_DART_INVOLUTION] THEN
  SIMP_TAC[GRAPH_REVERSE_DART_OUT]);;

let GRAPH_REVERSE_DART_NO_FIXEDPOINT = prove
 (`!V E d:A#A.
        finite_simple_graph V E /\ d IN graph_darts E
        ==> ~(graph_reverse_dart E d = d)`,
  REPEAT STRIP_TAC THEN
  ASM_MESON_TAC[GRAPH_REVERSE_DART_IN; REVERSE_DART_NO_FIXEDPOINT]);;

let IN_OUTGOING_DARTS = prove
 (`!E u d:A#A.
        d IN outgoing_darts E u <=>
        d IN graph_darts E /\ FST d = u`,
  REWRITE_TAC[outgoing_darts; IN_ELIM_THM]);;

let IN_OUTGOING_DARTS_PAIR = prove
 (`!E u v:A.
        (u,v) IN outgoing_darts E u <=> {u,v} IN E`,
  REWRITE_TAC[IN_OUTGOING_DARTS; IN_GRAPH_DARTS; FST]);;

let OUTGOING_DARTS_SUBSET = prove
 (`!E u:A. outgoing_darts E u SUBSET graph_darts E`,
  REWRITE_TAC[SUBSET; IN_OUTGOING_DARTS] THEN MESON_TAC[]);;

let FINITE_OUTGOING_DARTS = prove
 (`!V E u:A.
        finite_simple_graph V E ==> FINITE(outgoing_darts E u)`,
  MESON_TAC[FINITE_GRAPH_DARTS; FINITE_SUBSET; OUTGOING_DARTS_SUBSET]);;

let GRAPH_ROTATION_PERMUTES = prove
 (`!E r:(A#A)->A#A.
        graph_rotation E r ==> r permutes graph_darts E`,
  REWRITE_TAC[graph_rotation] THEN MESON_TAC[]);;

let GRAPH_ROTATION_IN = prove
 (`!E r d:A#A.
        graph_rotation E r /\ d IN graph_darts E
        ==> r d IN graph_darts E`,
  MESON_TAC[GRAPH_ROTATION_PERMUTES; PERMUTES_IN_IMAGE]);;

let GRAPH_ROTATION_TAIL = prove
 (`!E r d:A#A.
        graph_rotation E r /\ d IN graph_darts E
        ==> FST(r d) = FST d`,
  REWRITE_TAC[graph_rotation] THEN MESON_TAC[]);;

let GRAPH_ROTATION_ITER = prove
 (`!E r d:A#A.
        graph_rotation E r /\ d IN graph_darts E
        ==> !n. ITER n r d IN graph_darts E /\
                FST(ITER n r d) = FST d`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN INDUCT_TAC THENL
   [ASM_REWRITE_TAC[ITER];
    REWRITE_TAC[ITER] THEN
    SUBGOAL_THEN
     `ITER n (r:(A#A)->A#A) d IN graph_darts E /\
      FST(ITER n r d) = FST d`
    STRIP_ASSUME_TAC THENL
     [ASM_REWRITE_TAC[];
      CONJ_TAC THENL
       [MATCH_MP_TAC GRAPH_ROTATION_IN THEN ASM_REWRITE_TAC[];
        MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `ITER n r d:A#A`]
         GRAPH_ROTATION_TAIL) THEN
        ASM_REWRITE_TAC[]]]]);;

let GRAPH_ROTATION_ORBIT = prove
 (`!E r d d':A#A.
        graph_rotation E r /\
        d IN graph_darts E /\ d' IN graph_darts E
        ==> ((?n. ITER n r d = d') <=> FST d' = FST d)`,
  REPEAT STRIP_TAC THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `n:num` (SUBST1_TAC o SYM)) THEN
    MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_ROTATION_ITER) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `n:num`) THEN SIMP_TAC[];
    DISCH_TAC THEN UNDISCH_TAC
     `graph_rotation (E:(A->bool)->bool) (r:(A#A)->A#A)` THEN
    REWRITE_TAC[graph_rotation] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
     (CONJUNCTS_THEN2 (K ALL_TAC)
      (MP_TAC o SPECL [`d:A#A`; `d':A#A`]))) THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_FACE_SUCCESSOR_IN = prove
 (`!E r d:A#A.
        d IN graph_darts E
        ==> graph_face_successor E r d = r(reverse_dart d)`,
  SIMP_TAC[graph_face_successor; o_THM; GRAPH_REVERSE_DART_IN]);;

let GRAPH_FACE_SUCCESSOR_PERMUTES = prove
 (`!E r:(A#A)->A#A.
        graph_rotation E r
        ==> graph_face_successor E r permutes graph_darts E`,
  REWRITE_TAC[graph_face_successor] THEN
  MESON_TAC[GRAPH_ROTATION_PERMUTES; GRAPH_REVERSE_DART_PERMUTES;
            PERMUTES_COMPOSE]);;

let GRAPH_FACE_SUCCESSOR_DART = prove
 (`!E r d:A#A.
        graph_rotation E r /\ d IN graph_darts E
        ==> graph_face_successor E r d IN graph_darts E`,
  MESON_TAC[GRAPH_FACE_SUCCESSOR_PERMUTES; PERMUTES_IN_IMAGE]);;

let GRAPH_FACE_SUCCESSOR_TAIL = prove
 (`!E r d:A#A.
        graph_rotation E r /\ d IN graph_darts E
        ==> FST(graph_face_successor E r d) = SND d`,
  REPEAT STRIP_TAC THEN ASM_SIMP_TAC[GRAPH_FACE_SUCCESSOR_IN] THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `reverse_dart(d:A#A)`]
   GRAPH_ROTATION_TAIL) THEN
  ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE; FST_REVERSE_DART]);;

let IN_GRAPH_FACE = prove
 (`!E r d d':A#A.
        d' IN graph_face E r d <=>
        ?n. ITER n (graph_face_successor E r) d = d'`,
  REWRITE_TAC[graph_face; IN_ELIM_THM]);;

let GRAPH_FACE_REFL = prove
 (`!E r d:A#A. d IN graph_face E r d`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_GRAPH_FACE] THEN EXISTS_TAC `0` THEN
  REWRITE_TAC[ITER]);;

let GRAPH_FACE_SUCCESSOR_IN_FACE = prove
 (`!E r d:A#A.
        graph_face_successor E r d IN graph_face E r d`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_GRAPH_FACE] THEN EXISTS_TAC `1` THEN
  REWRITE_TAC[ITER_1]);;

let GRAPH_FACE_SUBSET_DARTS = prove
 (`!E r d:A#A.
        graph_rotation E r /\ d IN graph_darts E
        ==> graph_face E r d SUBSET graph_darts E`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SUBSET; IN_GRAPH_FACE] THEN
  X_GEN_TAC `d':A#A` THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` (SUBST1_TAC o SYM)) THEN
  SPEC_TAC(`n:num`,`n:num`) THEN INDUCT_TAC THENL
   [ASM_REWRITE_TAC[ITER];
    REWRITE_TAC[ITER] THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_DART THEN ASM_REWRITE_TAC[]]);;

let FINITE_GRAPH_FACE = prove
 (`!V E r d:A#A.
        finite_simple_graph V E /\ graph_rotation E r /\
        d IN graph_darts E
        ==> FINITE(graph_face E r d)`,
  MESON_TAC[FINITE_GRAPH_DARTS; FINITE_SUBSET; GRAPH_FACE_SUBSET_DARTS]);;

(* ------------------------------------------------------------------------- *)
(* Orbit partitions of finite permutations.                                  *)
(* ------------------------------------------------------------------------- *)

let PERMUTES_ITER = prove
 (`!f:A->A s n. f permutes s ==> ITER n f permutes s`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SPEC_TAC(`n:num`,`n:num`) THEN INDUCT_TAC THENL
   [REWRITE_TAC[CONJUNCT1 ITER_POINTLESS; PERMUTES_I];
    REWRITE_TAC[CONJUNCT2 ITER_POINTLESS] THEN
    MATCH_MP_TAC PERMUTES_COMPOSE THEN ASM_REWRITE_TAC[]]);;

let FINITE_PERMUTES_PERIODIC = prove
 (`!f:A->A s x.
        FINITE s /\ f permutes s /\ x IN s
        ==> ?d. 0 < d /\ ITER d f x = x`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutes point" THEN
  SUBGOAL_THEN
   `FINITE {((=) (ITER n (f:A->A) x)):A->bool | n IN (:num)}`
  (LABEL_TAC "finite_orbit") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `IMAGE (\y:A. (=) y) s` THEN CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_IMAGE THEN USE_THEN "finite" ACCEPT_TAC;
      REWRITE_TAC[SUBSET; IN_IMAGE; IN_UNIV; IN_ELIM_THM] THEN
      X_GEN_TAC `q:A->bool` THEN
      DISCH_THEN(X_CHOOSE_THEN `n:num` SUBST1_TAC) THEN
      EXISTS_TAC `ITER n (f:A->A) x` THEN CONJ_TAC THENL
       [REFL_TAC;
        MP_TAC(ISPECL
         [`ITER n (f:A->A):A->A`; `s:A->bool`; `x:A`]
         PERMUTES_IN_IMAGE) THEN
        ANTS_TAC THENL
         [MATCH_MP_TAC PERMUTES_ITER THEN
          USE_THEN "permutes" ACCEPT_TAC;
          ASM_REWRITE_TAC[]]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?d. 0 < d /\ !n. ITER n (f:A->A) x = x <=> d divides n`
  MP_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`(=):A->A->bool`; `f:A->A`; `x:A`]
     ORDER_EXISTENCE_FINITE) THEN
    CONJ_TAC THENL
     [USE_THEN "finite_orbit" ACCEPT_TAC;
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REFL_TAC;
      ALL_TAC] THEN
    CONJ_TAC THENL
     [MESON_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [MESON_TAC[];
      MATCH_MP_TAC PERMUTES_INJECTIVE THEN
      EXISTS_TAC `s:A->bool` THEN USE_THEN "permutes" ACCEPT_TAC];
    DISCH_THEN(X_CHOOSE_THEN `d:num` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `d:num` THEN ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `d:num`) THEN
    REWRITE_TAC[DIVIDES_REFL]]);;

let permutation_orbit = new_definition
 `permutation_orbit (f:A->A) x = {y | ?n. ITER n f x = y}`;;

let permutation_orbits = new_definition
 `permutation_orbits (f:A->A) s =
        IMAGE (permutation_orbit f) s`;;

let IN_PERMUTATION_ORBIT = prove
 (`!f:A->A. !x y.
        y IN permutation_orbit f x <=> ?n. ITER n f x = y`,
  REWRITE_TAC[permutation_orbit; IN_ELIM_THM]);;

let PERMUTATION_ORBIT_REFL = prove
 (`!f:A->A. !x. x IN permutation_orbit f x`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
  EXISTS_TAC `0` THEN REWRITE_TAC[ITER]);;

let PERMUTATION_ORBIT_TRANS = prove
 (`!f:A->A. !x y z.
        y IN permutation_orbit f x /\
        z IN permutation_orbit f y
        ==> z IN permutation_orbit f x`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
  INTRO_TAC "first second" THEN
  USE_THEN "first"
   (X_CHOOSE_THEN `m:num` (LABEL_TAC "first_step")) THEN
  USE_THEN "second"
   (X_CHOOSE_THEN `n:num` (LABEL_TAC "second_step")) THEN
  EXISTS_TAC `n + m:num` THEN
  REWRITE_TAC[GSYM ITER_ADD] THEN ASM_REWRITE_TAC[]);;

let PERMUTATION_ORBIT_SUBSET = prove
 (`!f:A->A. !s x.
        f permutes s /\ x IN s
        ==> permutation_orbit f x SUBSET s`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation member" THEN
  REWRITE_TAC[SUBSET; IN_PERMUTATION_ORBIT] THEN
  X_GEN_TAC `y:A` THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` (SUBST1_TAC o SYM)) THEN
  MP_TAC(ISPECL [`ITER n (f:A->A):A->A`; `s:A->bool`; `x:A`]
    PERMUTES_IN_IMAGE) THEN
  ANTS_TAC THENL
   [MATCH_MP_TAC PERMUTES_ITER THEN
    USE_THEN "permutation" ACCEPT_TAC;
    ASM_REWRITE_TAC[]]);;

let FINITE_PERMUTATION_ORBIT = prove
 (`!f:A->A. !s x.
        FINITE s /\ f permutes s /\ x IN s
        ==> FINITE(permutation_orbit f x)`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutation member" THEN
  MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC `s:A->bool` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC PERMUTATION_ORBIT_SUBSET THEN ASM_REWRITE_TAC[]);;

let PERMUTATION_ORBIT_SYM = prove
 (`!f:A->A. !s x y.
        FINITE s /\
        f permutes s /\
        x IN s /\
        y IN permutation_orbit f x
        ==> x IN permutation_orbit f y`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutation member orbit" THEN
  USE_THEN "orbit" MP_TAC THEN
  REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THEN
  MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`]
    FINITE_PERMUTES_PERIODIC) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `k:num`
     (CONJUNCTS_THEN2 (LABEL_TAC "positive") (LABEL_TAC "return")))] THEN
  REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
  EXISTS_TAC `k * (n + 1) - n` THEN
  USE_THEN "step" (SUBST1_TAC o SYM) THEN
  REWRITE_TAC[ITER_ADD] THEN
  SUBGOAL_THEN `(k * (n + 1) - n) + n = k * (n + 1)`
  SUBST1_TAC THENL
   [MATCH_MP_TAC SUB_ADD THEN
    MP_TAC(ISPECL [`1`; `k:num`; `n:num`; `n + 1`] LE_MULT2) THEN
    ANTS_TAC THENL
     [USE_THEN "positive" MP_TAC THEN ARITH_TAC;
      REWRITE_TAC[MULT_CLAUSES]];
    ONCE_REWRITE_TAC[MULT_SYM] THEN
    REWRITE_TAC[GSYM ITER_MUL] THEN
    MATCH_MP_TAC ITER_FIXPOINT THEN
    USE_THEN "return" ACCEPT_TAC]);;

let PERMUTATION_ORBIT_IMAGE = prove
 (`!f:A->A. !s x.
        FINITE s /\
        f permutes s /\
        x IN s
        ==> IMAGE f (permutation_orbit f x) =
            permutation_orbit f x`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutation member" THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; FORALL_IN_IMAGE] THEN
    X_GEN_TAC `y:A` THEN
    REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
    DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THEN
    EXISTS_TAC `SUC n` THEN REWRITE_TAC[ITER] THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[SUBSET] THEN X_GEN_TAC `y:A` THEN
    DISCH_THEN(LABEL_TAC "y_orbit") THEN
    MP_TAC(SPEC `y:A`
     (MATCH_MP
       (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_SURJECTIVE)
       (ASSUME `(f:A->A) permutes s`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` (LABEL_TAC "preimage")) THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `z:A` THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(y:A) IN s` (LABEL_TAC "y_member") THENL
     [MATCH_MP_TAC
       (REWRITE_RULE[SUBSET]
        (MATCH_MP
          (ISPECL [`f:A->A`; `s:A->bool`; `x:A`]
            PERMUTATION_ORBIT_SUBSET)
          (CONJ (ASSUME `(f:A->A) permutes s`)
                (ASSUME `(x:A) IN s`)))) THEN
      USE_THEN "y_orbit" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(z:A) IN s` (LABEL_TAC "z_member") THENL
     [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `z:A`]
       PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(y:A) IN permutation_orbit (f:A->A) z`
    (LABEL_TAC "y_from_z") THENL
     [REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
      EXISTS_TAC `SUC 0` THEN REWRITE_TAC[ITER] THEN
      USE_THEN "preimage" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(z:A) IN permutation_orbit (f:A->A) y`
    (LABEL_TAC "z_from_y") THENL
     [MATCH_MP_TAC(ISPECL
       [`f:A->A`; `s:A->bool`; `z:A`; `y:A`]
       PERMUTATION_ORBIT_SYM) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`f:A->A`; `x:A`; `y:A`; `z:A`]
      PERMUTATION_ORBIT_TRANS) THEN
    ASM_REWRITE_TAC[]]);;

let PERMUTATION_ORBIT_EQ = prove
 (`!f:A->A. !s x y.
        FINITE s /\ f permutes s /\ x IN s
        ==> (permutation_orbit f y = permutation_orbit f x <=>
             y IN permutation_orbit f x)`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutation member" THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "same") THEN
    USE_THEN "same" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL;
    DISCH_THEN(LABEL_TAC "orbit") THEN
    SUBGOAL_THEN `x IN permutation_orbit (f:A->A) y`
    (LABEL_TAC "reverse") THENL
     [MATCH_MP_TAC(ISPECL
       [`f:A->A`; `s:A->bool`; `x:A`; `y:A`]
       PERMUTATION_ORBIT_SYM) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `z:A` THEN EQ_TAC THENL
     [DISCH_THEN(LABEL_TAC "z_orbit") THEN
      MATCH_MP_TAC(ISPECL [`f:A->A`; `x:A`; `y:A`; `z:A`]
       PERMUTATION_ORBIT_TRANS) THEN
      ASM_REWRITE_TAC[];
      DISCH_THEN(LABEL_TAC "z_orbit") THEN
      MATCH_MP_TAC(ISPECL [`f:A->A`; `y:A`; `x:A`; `z:A`]
       PERMUTATION_ORBIT_TRANS) THEN
      ASM_REWRITE_TAC[]]]);;

let IN_PERMUTATION_ORBITS = prove
 (`!f:A->A. !s c.
        c IN permutation_orbits f s <=>
        ?x. x IN s /\ c = permutation_orbit f x`,
  REWRITE_TAC[permutation_orbits; IN_IMAGE] THEN MESON_TAC[]);;

let FINITE_PERMUTATION_ORBITS = prove
 (`!f:A->A. !s.
        FINITE s ==> FINITE(permutation_orbits f s)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[permutation_orbits] THEN
  MATCH_MP_TAC FINITE_IMAGE THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The face orbits form a finite partition of the dart set.                  *)
(* ------------------------------------------------------------------------- *)

let GRAPH_FACE_AS_PERMUTATION_ORBIT = prove
 (`!E r d:A#A.
        graph_face E r d =
        permutation_orbit (graph_face_successor E r) d`,
  REWRITE_TAC[graph_face; permutation_orbit]);;

let GRAPH_FACE_SYM = prove
 (`!V E r d d':A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        d IN graph_darts E /\
        d' IN graph_face E r d
        ==> d IN graph_face E r d'`,
  REWRITE_TAC[GRAPH_FACE_AS_PERMUTATION_ORBIT] THEN
  MESON_TAC[PERMUTATION_ORBIT_SYM; FINITE_GRAPH_DARTS;
            GRAPH_FACE_SUCCESSOR_PERMUTES]);;

let GRAPH_FACE_TRANS = prove
 (`!E r d d' d'':A#A.
        d' IN graph_face E r d /\ d'' IN graph_face E r d'
        ==> d'' IN graph_face E r d`,
  REWRITE_TAC[GRAPH_FACE_AS_PERMUTATION_ORBIT] THEN
  MESON_TAC[PERMUTATION_ORBIT_TRANS]);;

let GRAPH_FACE_EQ = prove
 (`!V E r d d':A#A.
        finite_simple_graph V E /\ graph_rotation E r /\
        d IN graph_darts E
        ==> (graph_face E r d' = graph_face E r d <=>
             d' IN graph_face E r d)`,
  REWRITE_TAC[GRAPH_FACE_AS_PERMUTATION_ORBIT] THEN
  MESON_TAC[PERMUTATION_ORBIT_EQ; FINITE_GRAPH_DARTS;
            GRAPH_FACE_SUCCESSOR_PERMUTES]);;

let DISTINCT_GRAPH_FACES_DISJOINT = prove
 (`!V E r d d':A#A.
        finite_simple_graph V E /\ graph_rotation E r /\
        d IN graph_darts E /\ d' IN graph_darts E /\
        ~(graph_face E r d = graph_face E r d')
        ==> DISJOINT (graph_face E r d) (graph_face E r d')`,
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  MESON_TAC[GRAPH_FACE_EQ]);;

let graph_faces = new_definition
 `graph_faces (E:(A->bool)->bool) (r:(A#A)->A#A) =
        IMAGE (graph_face E r) (graph_darts E)`;;

let IN_GRAPH_FACES = prove
 (`!E r f:(A#A)->bool.
        f IN graph_faces E r <=>
        ?d. d IN graph_darts E /\ f = graph_face E r d`,
  REWRITE_TAC[graph_faces; IN_IMAGE] THEN MESON_TAC[]);;

let GRAPH_FACES_AS_PERMUTATION_ORBITS = prove
 (`!E r:(A#A)->A#A.
        graph_faces E r =
        permutation_orbits (graph_face_successor E r) (graph_darts E)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_faces; permutation_orbits] THEN
  SUBGOAL_THEN
   `(graph_face E r:(A#A)->(A#A)->bool) =
    permutation_orbit (graph_face_successor E r)`
  SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; GRAPH_FACE_AS_PERMUTATION_ORBIT];
    REFL_TAC]);;

let FINITE_GRAPH_FACES = prove
 (`!V E r:(A#A)->A#A.
        finite_simple_graph V E ==> FINITE(graph_faces E r)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[graph_faces] THEN
  MATCH_MP_TAC FINITE_IMAGE THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
  ASM_REWRITE_TAC[]);;

let UNIONS_GRAPH_FACES = prove
 (`!E r:(A#A)->A#A.
        graph_rotation E r
        ==> UNIONS(graph_faces E r) = graph_darts E`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[EXTENSION; IN_UNIONS; IN_GRAPH_FACES] THEN
  ASM_MESON_TAC[GRAPH_FACE_REFL; GRAPH_FACE_SUBSET_DARTS; SUBSET]);;

let PAIRWISE_DISJOINT_GRAPH_FACES = prove
 (`!V E r:(A#A)->A#A.
        finite_simple_graph V E /\ graph_rotation E r
        ==> pairwise DISJOINT (graph_faces E r)`,
  REWRITE_TAC[pairwise; IN_GRAPH_FACES] THEN
  MESON_TAC[DISTINCT_GRAPH_FACES_DISJOINT]);;

(* ------------------------------------------------------------------------- *)
(* Euler data of finite graph rotation systems.                              *)
(* ------------------------------------------------------------------------- *)

(* ------------------------------------------------------------------------- *)
(* Reachability and connected components.                                    *)
(* ------------------------------------------------------------------------- *)

let graph_reachable = new_definition
 `graph_reachable (E:(A->bool)->bool) u v <=>
        RTC (\x y. {x,y} IN E) u v`;;

let connected_graph = new_definition
 `connected_graph (V:A->bool) (E:(A->bool)->bool) <=>
        !u v. u IN V /\ v IN V ==> graph_reachable E u v`;;

let graph_component = new_definition
 `graph_component (E:(A->bool)->bool) u =
        {v | graph_reachable E u v}`;;

let GRAPH_REACHABLE_REFL = prove
 (`!E u:A. graph_reachable E u u`,
  REWRITE_TAC[graph_reachable; RTC_REFL]);;

let GRAPH_EDGE_IMP_REACHABLE = prove
 (`!E u v:A. {u,v} IN E ==> graph_reachable E u v`,
  REWRITE_TAC[graph_reachable] THEN MESON_TAC[RTC_INC]);;

let GRAPH_REACHABLE_TRANS = prove
 (`!E u v w:A.
        graph_reachable E u v /\ graph_reachable E v w
        ==> graph_reachable E u w`,
  REWRITE_TAC[graph_reachable] THEN MESON_TAC[RTC_TRANS]);;

let GRAPH_REACHABLE_SYM = prove
 (`!E u v:A. graph_reachable E u v ==> graph_reachable E v u`,
  REPEAT GEN_TAC THEN REWRITE_TAC[graph_reachable] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC
   (SPECL [`u:A`; `v:A`]
    (MATCH_MP (REWRITE_RULE[]
      (ISPEC `\x y:A. {x,y} IN E` RTC_SYM))
     (prove
       (`!x y:A. {x,y} IN E ==> {y,x} IN E`,
        MESON_TAC[SET_RULE `{x:A,y} = {y,x}`])))) THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_REACHABLE_VERTEX = prove
 (`!V E u v:A.
        finite_simple_graph V E /\ u IN V /\ graph_reachable E u v
        ==> v IN V`,
  REPEAT GEN_TAC THEN REWRITE_TAC[graph_reachable] THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!x y:A. RTC (\x y. {x,y} IN E) x y
             ==> (x IN V ==> y IN V)`
  (fun th ->
    MP_TAC(SPECL [`u:A`; `v:A`] th) THEN ASM_REWRITE_TAC[]) THEN
  MATCH_MP_TAC RTC_INDUCT THEN REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN REWRITE_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `x:A`; `y:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
    REWRITE_TAC[];
    MESON_TAC[]]);;

let GRAPH_REACHABLE_VERTICES = prove
 (`!V E u v:A.
        finite_simple_graph V E /\ graph_reachable E u v
        ==> (u IN V <=> v IN V)`,
  REPEAT STRIP_TAC THEN EQ_TAC THEN DISCH_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     GRAPH_REACHABLE_VERTEX) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `u:A`]
     GRAPH_REACHABLE_VERTEX) THEN
    ASM_MESON_TAC[GRAPH_REACHABLE_SYM]]);;

let GRAPH_REACHABLE_NONTRIVIAL_VERTICES = prove
 (`!V E u v:A.
        finite_simple_graph V E /\
        graph_reachable E u v /\ ~(u = v)
        ==> u IN V /\ v IN V`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(u:A) IN V` ASSUME_TAC THENL
   [UNDISCH_TAC `graph_reachable (E:(A->bool)->bool) u v` THEN
    REWRITE_TAC[graph_reachable] THEN
    ONCE_REWRITE_TAC[RTC_CASES_R] THEN REWRITE_TAC[] THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `w:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
    CONJ_TAC THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     GRAPH_REACHABLE_VERTEX) THEN
    ASM_REWRITE_TAC[]]);;

let IN_GRAPH_COMPONENT = prove
 (`!E u v:A.
        v IN graph_component E u <=> graph_reachable E u v`,
  REWRITE_TAC[graph_component; IN_ELIM_THM]);;

let GRAPH_COMPONENT_REFL = prove
 (`!E u:A. u IN graph_component E u`,
  REWRITE_TAC[IN_GRAPH_COMPONENT; GRAPH_REACHABLE_REFL]);;

let GRAPH_COMPONENT_CLOSED = prove
 (`!E u v w:A.
        v IN graph_component E u /\ {v,w} IN E
        ==> w IN graph_component E u`,
  REWRITE_TAC[IN_GRAPH_COMPONENT] THEN
  MESON_TAC[GRAPH_EDGE_IMP_REACHABLE; GRAPH_REACHABLE_TRANS]);;

let GRAPH_COMPONENT_EQ = prove
 (`!E u v:A.
        graph_component E u = graph_component E v <=>
        graph_reachable E u v`,
  REWRITE_TAC[EXTENSION; IN_GRAPH_COMPONENT] THEN
  MESON_TAC[GRAPH_REACHABLE_REFL; GRAPH_REACHABLE_SYM;
            GRAPH_REACHABLE_TRANS]);;

let GRAPH_COMPONENT_SUBSET = prove
 (`!V E u:A.
        finite_simple_graph V E /\ u IN V
        ==> graph_component E u SUBSET V`,
  REWRITE_TAC[SUBSET; IN_GRAPH_COMPONENT] THEN
  MESON_TAC[GRAPH_REACHABLE_VERTICES]);;

let FINITE_GRAPH_COMPONENT = prove
 (`!V E u:A.
        finite_simple_graph V E ==> FINITE(graph_component E u)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC `u INSERT (V:A->bool)` THEN
  CONJ_TAC THENL
   [ASM_MESON_TAC[FINITE_INSERT; finite_simple_graph];
    REWRITE_TAC[SUBSET; IN_GRAPH_COMPONENT; IN_INSERT] THEN
    ASM_MESON_TAC[GRAPH_REACHABLE_NONTRIVIAL_VERTICES]]);;

let CONNECTED_GRAPH_COMPONENT = prove
 (`!V E u:A.
        u IN V
        ==> (connected_graph V E <=> V SUBSET graph_component E u)`,
  REWRITE_TAC[connected_graph; SUBSET; IN_GRAPH_COMPONENT] THEN
  MESON_TAC[GRAPH_REACHABLE_SYM; GRAPH_REACHABLE_TRANS]);;

(* ------------------------------------------------------------------------- *)
(* Cardinality bookkeeping for darts and face orbits.                        *)
(* ------------------------------------------------------------------------- *)

let edge_darts = new_definition
 `edge_darts (e:A->bool) = {d | dart_edge d = e}`;;

let EDGE_DARTS_PAIR = prove
 (`!u v:A.
        ~(u = v)
        ==> edge_darts {u,v} = {(u,v),(v,u)}`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[EXTENSION; FORALL_PAIR_THM; edge_darts; IN_ELIM_THM;
              DART_EDGE_PAIR; IN_INSERT; NOT_IN_EMPTY; PAIR_EQ] THEN
  ASM SET_TAC[]);;

let EDGE_DARTS_HAS_SIZE_2 = prove
 (`!e:A->bool. e HAS_SIZE 2 ==> edge_darts e HAS_SIZE 2`,
  GEN_TAC THEN
  REWRITE_TAC[HAS_SIZE_CONV `(e:A->bool) HAS_SIZE 2`] THEN
  INTRO_TAC "@u v. distinct pair" THEN
  ASM_REWRITE_TAC[EDGE_DARTS_PAIR] THEN
  MAP_EVERY EXISTS_TAC
   [`((u:A),(v:A))`; `((v:A),(u:A))`] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[PAIR_EQ] THEN ASM_MESON_TAC[];
    MATCH_MP_TAC EDGE_DARTS_PAIR THEN ASM_REWRITE_TAC[]]);;

let GRAPH_DARTS_UNIONS_EDGE_DARTS = prove
 (`!E:(A->bool)->bool.
        graph_darts E = UNIONS {edge_darts e | e IN E}`,
  GEN_TAC THEN MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; graph_darts; IN_ELIM_THM] THEN
    X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    REWRITE_TAC[IN_UNIONS] THEN
    EXISTS_TAC `edge_darts (dart_edge(d:A#A))` THEN CONJ_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN
      EXISTS_TAC `dart_edge(d:A#A)` THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[edge_darts; IN_ELIM_THM]];
    REWRITE_TAC[SUBSET; IN_UNIONS; graph_darts; IN_ELIM_THM] THEN
    X_GEN_TAC `d:A#A` THEN
    INTRO_TAC "@t. (@e. edge t_rep) d_in" THEN
    USE_THEN "t_rep" SUBST_ALL_TAC THEN
    USE_THEN "d_in" MP_TAC THEN
    REWRITE_TAC[edge_darts; IN_ELIM_THM] THEN ASM_MESON_TAC[]]);;

let DISTINCT_EDGE_DARTS_DISJOINT = prove
 (`!e e':A->bool.
        ~(e = e') ==> DISJOINT (edge_darts e) (edge_darts e')`,
  REPEAT GEN_TAC THEN REWRITE_TAC[DISJOINT; edge_darts] THEN SET_TAC[]);;

let CARD_GRAPH_DARTS = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> CARD(graph_darts E) = 2 * CARD E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  SUBGOAL_THEN `FINITE(E:(A->bool)->bool)` (LABEL_TAC "finite_edges") THENL
   [USE_THEN "graph"
     (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o
      REWRITE_RULE[finite_simple_graph]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `E HAS_SIZE CARD(E:(A->bool)->bool)`
  (LABEL_TAC "edge_size") THENL
   [ASM_REWRITE_TAC[HAS_SIZE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!e:A->bool. e IN E ==> edge_darts e HAS_SIZE 2`
  (LABEL_TAC "dart_fibres") THENL
   [X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    MATCH_MP_TAC EDGE_DARTS_HAS_SIZE_2 THEN
    USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `edge_darts:(A->bool)->(A#A)->bool`;
    `CARD(E:(A->bool)->bool)`; `2`] HAS_SIZE_UNIONS) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
   [MAP_EVERY X_GEN_TAC [`e:A->bool`; `e':A->bool`] THEN
    INTRO_TAC "edge edge' distinct" THEN
    MATCH_MP_TAC DISTINCT_EDGE_DARTS_DISJOINT THEN
    USE_THEN "distinct" ACCEPT_TAC;
    DISCH_THEN(MP_TAC) THEN
    REWRITE_TAC[GSYM GRAPH_DARTS_UNIONS_EDGE_DARTS; HAS_SIZE] THEN
    ARITH_TAC]);;

let CARD_GRAPH_DARTS_AS_FACE_SUM = prove
 (`!V E r:(A#A)->A#A.
        finite_simple_graph V E /\ graph_rotation E r
        ==> CARD(graph_darts E) = nsum (graph_faces E r) CARD`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation" THEN
  MP_TAC(ISPEC `graph_faces (E:(A->bool)->bool) (r:(A#A)->A#A)`
    CARD_UNIONS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
       FINITE_GRAPH_FACES) THEN
      USE_THEN "graph" ACCEPT_TAC;
      X_GEN_TAC `f:(A#A)->bool` THEN
      REWRITE_TAC[IN_GRAPH_FACES] THEN
      INTRO_TAC "@d. dart face" THEN
      USE_THEN "face" SUBST1_TAC THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
       FINITE_GRAPH_FACE) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
       PAIRWISE_DISJOINT_GRAPH_FACES) THEN
      ASM_REWRITE_TAC[pairwise; DISJOINT]];
    ASM_SIMP_TAC[UNIONS_GRAPH_FACES]]);;

let FACE_SUM_EQ_TWICE_EDGES = prove
 (`!V E r:(A#A)->A#A.
        finite_simple_graph V E /\ graph_rotation E r
        ==> nsum (graph_faces E r) CARD = 2 * CARD E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
   CARD_GRAPH_DARTS_AS_FACE_SUM) THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`] CARD_GRAPH_DARTS) THEN
  ASM_REWRITE_TAC[] THEN ARITH_TAC);;

(* A singleton component has one formal face despite having no darts.        *)

let graph_map_faces = new_definition
 `graph_map_faces (V:A->bool) (E:(A->bool)->bool) r =
        if E = {} /\ ~(V = {}) then
          {{}:(A#A)->bool}
        else graph_faces E r`;;

let graph_euler_formula = new_definition
 `graph_euler_formula (V:A->bool) (E:(A->bool)->bool) r <=>
        CARD V + CARD(graph_map_faces V E r) = CARD E + 2`;;

(* ------------------------------------------------------------------------- *)
(* Euler-planar rotations are stated componentwise.                          *)
(* ------------------------------------------------------------------------- *)

let graph_component_edges = new_definition
 `graph_component_edges (E:(A->bool)->bool) u =
        {e | e IN E /\ e SUBSET graph_component E u}`;;

let IN_GRAPH_COMPONENT_EDGES = prove
 (`!E e u:A.
        e IN graph_component_edges E u <=>
        e IN E /\ e SUBSET graph_component E u`,
  REWRITE_TAC[graph_component_edges; IN_ELIM_THM]);;

let GRAPH_COMPONENT_EDGES_SUBSET = prove
 (`!E u:A. graph_component_edges E u SUBSET E`,
  REWRITE_TAC[SUBSET; IN_GRAPH_COMPONENT_EDGES] THEN MESON_TAC[]);;

let FINITE_SIMPLE_GRAPH_COMPONENT = prove
 (`!V E u:A.
        finite_simple_graph V E /\ u IN V
        ==> finite_simple_graph
             (graph_component E u) (graph_component_edges E u)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph vertex" THEN
  REWRITE_TAC[finite_simple_graph] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
     FINITE_GRAPH_COMPONENT) THEN
    USE_THEN "graph" ACCEPT_TAC;
    MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `E:(A->bool)->bool` THEN CONJ_TAC THENL
     [USE_THEN "graph"
       (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o
        REWRITE_RULE[finite_simple_graph]);
      MATCH_ACCEPT_TAC GRAPH_COMPONENT_EDGES_SUBSET];
    X_GEN_TAC `e:A->bool` THEN
    REWRITE_TAC[IN_GRAPH_COMPONENT_EDGES] THEN
    INTRO_TAC "edge subset" THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[]]);;

let GRAPH_COMPONENT_EDGES_CONNECTED = prove
 (`!V E u:A.
        finite_simple_graph V E /\ u IN V
        ==> connected_graph
             (graph_component E u) (graph_component_edges E u)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph vertex" THEN
  REWRITE_TAC[connected_graph] THEN
  MAP_EVERY X_GEN_TAC [`v:A`; `w:A`] THEN
  INTRO_TAC "v_component w_component" THEN
  SUBGOAL_THEN
   `!x y:A.
        graph_reachable E x y /\
        x IN graph_component E u
        ==> graph_reachable (graph_component_edges E u) x y`
  (LABEL_TAC "restrict_path") THENL
   [REWRITE_TAC[graph_reachable] THEN
    SUBGOAL_THEN
     `!x y:A.
          RTC (\x y. {x,y} IN E) x y
          ==> (x IN graph_component E u
               ==> y IN graph_component E u /\
                   RTC
                    (\x y. {x,y} IN graph_component_edges E u) x y)`
    (LABEL_TAC "induction") THENL
     [MATCH_MP_TAC RTC_INDUCT THEN REPEAT CONJ_TAC THENL
       [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
        REWRITE_TAC[] THEN
        DISCH_THEN(LABEL_TAC "edge") THEN
        DISCH_THEN(LABEL_TAC "x_component") THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC GRAPH_COMPONENT_CLOSED THEN
          EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[];
          MATCH_MP_TAC RTC_INC THEN REWRITE_TAC[] THEN
          REWRITE_TAC[IN_GRAPH_COMPONENT_EDGES] THEN
          CONJ_TAC THENL
           [USE_THEN "edge" ACCEPT_TAC;
            REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
            CONJ_TAC THENL
             [USE_THEN "x_component" ACCEPT_TAC;
              MATCH_MP_TAC GRAPH_COMPONENT_CLOSED THEN
              EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[]]]];
        REWRITE_TAC[RTC_REFL];
        MESON_TAC[RTC_TRANS]];
      USE_THEN "induction" MP_TAC THEN MESON_TAC[]];
    USE_THEN "restrict_path" MP_TAC THEN
    USE_THEN "v_component" MP_TAC THEN
    USE_THEN "w_component" MP_TAC THEN
    REWRITE_TAC[IN_GRAPH_COMPONENT] THEN
    MESON_TAC[GRAPH_REACHABLE_REFL;
              GRAPH_REACHABLE_SYM; GRAPH_REACHABLE_TRANS]]);;

let CONNECTED_GRAPH_COMPONENT_EDGES = prove
 (`!V E u:A.
        finite_simple_graph V E /\ connected_graph V E /\ u IN V
        ==> graph_component E u = V /\
            graph_component_edges E u = E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected vertex" THEN
  SUBGOAL_THEN `graph_component E (u:A) = V`
  (LABEL_TAC "component") THENL
   [MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_COMPONENT_SUBSET THEN ASM_REWRITE_TAC[];
      MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
       CONNECTED_GRAPH_COMPONENT) THEN
      ASM_REWRITE_TAC[]];
    ASM_REWRITE_TAC[]] THEN
  REWRITE_TAC[EXTENSION; IN_GRAPH_COMPONENT_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN EQ_TAC THENL
   [MESON_TAC[];
    DISCH_THEN(LABEL_TAC "edge") THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[]]);;

let euler_planar_rotation = new_definition
 `euler_planar_rotation (V:A->bool) (E:(A->bool)->bool) r <=>
        finite_simple_graph V E /\
        graph_rotation E r /\
        graph_euler_formula V E r`;;

let euler_planar_graph = new_definition
 `euler_planar_graph (V:A->bool) (E:(A->bool)->bool) <=>
        finite_simple_graph V E /\
        (!u. u IN V
             ==> ?r:(A#A)->A#A.
                   euler_planar_rotation
                     (graph_component E u)
                     (graph_component_edges E u) r)`;;

let EULER_PLANAR_ROTATION_CONNECTED = prove
 (`!V E r u:A.
        euler_planar_rotation V E r /\
        connected_graph V E /\ u IN V
        ==> graph_rotation E r /\ graph_euler_formula V E r`,
  REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[]);;

let EULER_PLANAR_GRAPH_FINITE_SIMPLE = prove
 (`!V E.
        euler_planar_graph (V:A->bool) E
        ==> finite_simple_graph V E`,
  REWRITE_TAC[euler_planar_graph] THEN MESON_TAC[]);;

let EULER_PLANAR_GRAPH_CONNECTED = prove
 (`!V E u:A.
        euler_planar_graph V E /\
        connected_graph V E /\ u IN V
        ==> ?r:(A#A)->A#A. euler_planar_rotation V E r`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler connected vertex" THEN
  USE_THEN "euler" MP_TAC THEN REWRITE_TAC[euler_planar_graph] THEN
  INTRO_TAC "graph components" THEN
  USE_THEN "components" (MP_TAC o SPEC `u:A`) THEN
  ANTS_TAC THENL
   [USE_THEN "vertex" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:(A#A)->A#A`
    (LABEL_TAC "component_rotation")) THEN
  MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
    CONNECTED_GRAPH_COMPONENT_EDGES) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  INTRO_TAC "component component_edges" THEN
  EXISTS_TAC `r:(A#A)->A#A` THEN
  USE_THEN "component" (fun vth ->
    USE_THEN "component_edges" (fun eth ->
      USE_THEN "component_rotation"
       (ACCEPT_TAC o REWRITE_RULE[vth; eth]))));;

(* ------------------------------------------------------------------------- *)
(* Cardinal bounds from recursive triangulation certificates.                *)
(* ------------------------------------------------------------------------- *)

let CARD_UNION_ADD_INTER_FINITE = prove
 (`!s t:A->bool.
        FINITE s /\ FINITE t
        ==> CARD(s UNION t) + CARD(s INTER t) = CARD s + CARD t`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`s:A->bool`; `t:A->bool`] CARD_UNION_GEN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC SUB_ADD THEN
  MATCH_MP_TAC LE_TRANS THEN EXISTS_TAC `CARD(s:A->bool)` THEN
  ASM_SIMP_TAC[CARD_SUBSET; INTER_SUBSET; LE_ADD]);;

let RECURSIVE_TRIANGULATED_DISK_EDGE_BOUND = prove
 (`!V E q:num->A. !n.
        recursive_triangulated_disk V E q n
        ==> CARD E + n + 3 <= 3 * CARD V`,
  SUBGOAL_THEN
   `!V E q:num->A. !n.
        recursive_triangulated_disk V E q n
        ==> finite_simple_graph V E /\
            CARD E + n + 3 <= 3 * CARD V`
  MP_TAC THENL
   [MATCH_MP_TAC recursive_triangulated_disk_INDUCT THEN
    REPEAT CONJ_TAC THENL
     [X_GEN_TAC `q:num->A` THEN DISCH_THEN(LABEL_TAC "injective") THEN
      SUBGOAL_THEN
       `finite_simple_graph
          (cyclic_vertices (q:num->A) 3) (cyclic_edges q 3)`
      (LABEL_TAC "graph") THENL
       [MATCH_MP_TAC(ISPECL
         [`cyclic_edges (q:num->A) 3`; `q:num->A`; `3`]
         FINITE_SIMPLE_GRAPH_CYCLIC) THEN
        REWRITE_TAC[simple_graph_cycle; SUBSET_REFL] THEN
        ASM_REWRITE_TAC[] THEN ARITH_TAC;
        ALL_TAC] THEN
      CONJ_TAC THENL
       [USE_THEN "graph" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `CARD(cyclic_vertices (q:num->A) 3) = 3`
      (LABEL_TAC "vertices") THENL
       [MATCH_MP_TAC CARD_CYCLIC_VERTICES THEN
        USE_THEN "injective" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `CARD(cyclic_edges (q:num->A) 3) <= 3`
      (LABEL_TAC "edges") THENL
       [REWRITE_TAC[cyclic_edges] THEN
        TRANS_TAC LE_TRANS `CARD(cyclic_indices 3)` THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC CARD_IMAGE_LE THEN
          MATCH_ACCEPT_TAC FINITE_CYCLIC_INDICES;
          REWRITE_TAC[CARD_CYCLIC_INDICES] THEN ARITH_TAC];
        ASM_ARITH_TAC];
      MAP_EVERY X_GEN_TAC
       [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
        `n:num`; `k:num`; `w:num->A`] THEN
      INTRO_TAC
       "(graph old_bound) nlarge injective fresh neighbors first last" THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INSERT_VERTEX_STAR THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `FINITE(V:A->bool) /\ FINITE(E:(A->bool)->bool)`
      (CONJUNCTS_THEN2 (LABEL_TAC "finite_vertices")
        (LABEL_TAC "finite_edges")) THENL
       [USE_THEN "graph" MP_TAC THEN
        REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `CARD(q (n - 1) INSERT (V:A->bool)) = CARD V + 1`
      (LABEL_TAC "new_vertices") THENL
       [ASM_SIMP_TAC[CARD_CLAUSES] THEN ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `CARD(IMAGE (\u:A. {q (n - 1),u})
                   (cyclic_vertices w (k + 2)) UNION E)
        <= CARD E + (k + 2)`
      (LABEL_TAC "new_edges") THENL
       [TRANS_TAC LE_TRANS
         `CARD(IMAGE (\u:A. {q (n - 1),u})
                     (cyclic_vertices w (k + 2))) +
          CARD(E:(A->bool)->bool)` THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC CARD_UNION_LE THEN CONJ_TAC THENL
           [MATCH_MP_TAC FINITE_IMAGE THEN
            MATCH_ACCEPT_TAC FINITE_CYCLIC_VERTICES;
            USE_THEN "finite_edges" ACCEPT_TAC];
          MATCH_MP_TAC(ARITH_RULE
           `a <= k + 2 ==> a + e <= e + k + 2`) THEN
          TRANS_TAC LE_TRANS `CARD(cyclic_vertices (w:num->A) (k + 2))` THEN
          CONJ_TAC THENL
           [MATCH_MP_TAC CARD_IMAGE_LE THEN
            MATCH_ACCEPT_TAC FINITE_CYCLIC_VERTICES;
            REWRITE_TAC[cyclic_vertices] THEN
            TRANS_TAC LE_TRANS `CARD(cyclic_indices (k + 2))` THEN
            CONJ_TAC THENL
             [MATCH_MP_TAC CARD_IMAGE_LE THEN
              MATCH_ACCEPT_TAC FINITE_CYCLIC_INDICES;
              REWRITE_TAC[CARD_CYCLIC_INDICES] THEN ARITH_TAC]]];
        ASM_ARITH_TAC];
      MAP_EVERY X_GEN_TAC
       [`V1:A->bool`; `E1:(A->bool)->bool`;
        `V2:A->bool`; `E2:(A->bool)->bool`;
        `q:num->A`; `n:num`; `j:num`] THEN
      INTRO_TAC
       "(graph1 bound1) (graph2 bound2) \
        jpositive split_bound injective overlap chord1 chord2" THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_UNION THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `FINITE(V1:A->bool) /\ FINITE(E1:(A->bool)->bool) /\
        FINITE(V2:A->bool) /\ FINITE(E2:(A->bool)->bool)`
      (CONJUNCTS_THEN2 (LABEL_TAC "finite_v1")
       (CONJUNCTS_THEN2 (LABEL_TAC "finite_e1")
        (CONJUNCTS_THEN2 (LABEL_TAC "finite_v2")
         (LABEL_TAC "finite_e2")))) THENL
       [MAP_EVERY (fun name -> USE_THEN name MP_TAC) ["graph1"; "graph2"] THEN
        REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `~((q:num->A) j = q (n - 1))`
      (LABEL_TAC "chord_distinct") THENL
       [USE_THEN "injective" MP_TAC THEN
        REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
        ASM_MESON_TAC[ARITH_RULE
         `j + 2 < n ==> j < n /\ n - 1 < n /\ ~(j = n - 1)`];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `CARD({(q:num->A) j,q (n - 1)}:A->bool) = 2`
      (LABEL_TAC "chord_card") THENL
       [ASM_SIMP_TAC[CARD_CLAUSES; FINITE_INSERT; FINITE_SING;
                     CARD_SING; IN_SING] THEN
        ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `CARD(V1 UNION V2:A->bool) + 2 = CARD V1 + CARD V2`
      (LABEL_TAC "new_vertices") THENL
       [MP_TAC(ISPECL [`V1:A->bool`; `V2:A->bool`]
          CARD_UNION_ADD_INTER_FINITE) THEN
        ASM_REWRITE_TAC[] THEN
        USE_THEN "overlap" (fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `CARD(E1 UNION E2:(A->bool)->bool) + 1 <= CARD E1 + CARD E2`
      (LABEL_TAC "new_edges") THENL
       [SUBGOAL_THEN
         `E1 UNION E2 =
          E1 UNION (E2 DELETE ({q j,q (n - 1)}:A->bool))`
        SUBST1_TAC THENL
         [ASM SET_TAC[];
          ALL_TAC] THEN
        MP_TAC(ISPECL
         [`E1:(A->bool)->bool`;
          `E2 DELETE ({q j,q (n - 1)}:A->bool)`]
         CARD_UNION_LE) THEN
        ASM_SIMP_TAC[FINITE_DELETE; CARD_DELETE] THEN
        DISCH_THEN(LABEL_TAC "union_bound") THEN
        SUBGOAL_THEN `~(E2:(A->bool)->bool = {})`
        (LABEL_TAC "edges2_nonempty") THENL
         [USE_THEN "chord2" MP_TAC THEN SET_TAC[];
          ALL_TAC] THEN
        SUBGOAL_THEN `0 < CARD(E2:(A->bool)->bool)`
        (LABEL_TAC "edges2_positive") THENL
         [MP_TAC(ISPEC `E2:(A->bool)->bool` CARD_EQ_0) THEN
          ASM_REWRITE_TAC[] THEN ARITH_TAC;
          ASM_ARITH_TAC];
        ASM_ARITH_TAC]];
    MESON_TAC[]]);;

let RECURSIVE_TRIANGULATED_DISK_3_EDGE_BOUND = prove
 (`!V E q:num->A.
        recursive_triangulated_disk V E q 3
        ==> CARD E + 6 <= 3 * CARD V`,
  MESON_TAC[RECURSIVE_TRIANGULATED_DISK_EDGE_BOUND;
            ARITH_RULE `e + 3 + 3 = e + 6`]);;

let RECURSIVE_PLANAR_GRAPH_EDGE_BOUND = prove
 (`!V E.
        recursive_planar_graph (V:A->bool) E /\ 3 <= CARD V
        ==> CARD E + 6 <= 3 * CARD V`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[recursive_planar_graph] THEN
  INTRO_TAC "(graph certificate) vertices" THEN
  USE_THEN "certificate"
   (DISJ_CASES_THEN2 (LABEL_TAC "small") (LABEL_TAC "extension")) THENL
   [ASM_ARITH_TAC;
    USE_THEN "extension"
     (X_CHOOSE_THEN `E':(A->bool)->bool`
      (X_CHOOSE_THEN `q:num->A`
       (CONJUNCTS_THEN2 (LABEL_TAC "subset") (LABEL_TAC "recursive")))) THEN
    SUBGOAL_THEN `FINITE(E':(A->bool)->bool)`
    (LABEL_TAC "finite_extended") THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E':(A->bool)->bool`; `q:num->A`; `3`]
       RECURSIVE_TRIANGULATED_DISK_INVARIANTS) THEN
      ASM_REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD(E:(A->bool)->bool) <= CARD(E':(A->bool)->bool)`
    (LABEL_TAC "edge_card") THENL
     [MATCH_MP_TAC CARD_SUBSET THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E':(A->bool)->bool`; `q:num->A`]
     RECURSIVE_TRIANGULATED_DISK_3_EDGE_BOUND) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]);;

let PLANAR_GRAPH_EDGE_BOUND = prove
 (`!V E.
        planar_graph (V:A->bool) E /\ 3 <= CARD V
        ==> CARD E + 6 <= 3 * CARD V`,
  MESON_TAC[RECURSIVE_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
            RECURSIVE_PLANAR_GRAPH_EDGE_BOUND]);;

let STRAIGHT_LINE_PLANAR_GRAPH_EDGE_BOUND = prove
 (`!V E.
        straight_line_planar_graph (V:A->bool) E /\ 3 <= CARD V
        ==> CARD E + 6 <= 3 * CARD V`,
  MESON_TAC[RECURSIVE_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR;
            RECURSIVE_PLANAR_GRAPH_EDGE_BOUND]);;

(* ------------------------------------------------------------------------- *)
(* Disjoint unions of permutations.                                          *)
(* ------------------------------------------------------------------------- *)

let disjoint_permutation_union = new_definition
 `disjoint_permutation_union
    (f:A->A) (s:A->bool) (g:A->A) x =
        if x IN s then f x else g x`;;

let DISJOINT_PERMUTATION_UNION_PERMUTES = prove
 (`!f g:A->A. !s t.
        FINITE s /\
        FINITE t /\
        f permutes s /\
        g permutes t /\
        DISJOINT s t
        ==> disjoint_permutation_union f s g
            permutes (s UNION t)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite_s finite_t f_permutation g_permutation disjoint" THEN
  MP_TAC(ISPECL
   [`s UNION t:A->bool`;
    `disjoint_permutation_union (f:A->A) s (g:A->A)`]
   PERMUTES_FINITE_INJECTIVE) THEN
  ASM_REWRITE_TAC[FINITE_UNION] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `x:A` THEN
    REWRITE_TAC[disjoint_permutation_union] THEN
    DISCH_THEN(LABEL_TAC "outside") THEN
    SUBGOAL_THEN `~((x:A) IN s) /\ ~(x IN t)`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "outside" MP_TAC THEN SET_TAC[];
      ASM_REWRITE_TAC[] THEN
      USE_THEN "g_permutation"
       (MATCH_MP_TAC o CONJUNCT1 o REWRITE_RULE[permutes]) THEN
      ASM_REWRITE_TAC[]];
    X_GEN_TAC `x:A` THEN REWRITE_TAC[IN_UNION] THEN
    DISCH_THEN(DISJ_CASES_THEN2
      (LABEL_TAC "x_s") (LABEL_TAC "x_t")) THENL
     [REWRITE_TAC[disjoint_permutation_union] THEN
      ASM_REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
      MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`]
        PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[disjoint_permutation_union] THEN
      ASM_CASES_TAC `(x:A) IN s` THENL
       [USE_THEN "disjoint" MP_TAC THEN
        REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
        DISCH_THEN(MP_TAC o SPEC `x:A`) THEN ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[IN_UNION] THEN DISJ2_TAC THEN
        MP_TAC(ISPECL [`g:A->A`; `t:A->bool`; `x:A`]
          PERMUTES_IN_IMAGE) THEN
        ASM_REWRITE_TAC[]]];
    MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    REWRITE_TAC[IN_UNION] THEN
    INTRO_TAC "x_union y_union equal" THEN
    ASM_CASES_TAC `(x:A) IN s` THEN
    ASM_CASES_TAC `(y:A) IN s` THENL
     [MATCH_MP_TAC
       (fst(EQ_IMP_RULE
        (SPECL [`x:A`; `y:A`]
         (MATCH_MP
          (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
          (ASSUME `(f:A->A) permutes s`))))) THEN
      REMOVE_THEN "equal"
       (fun th -> MP_TAC(REWRITE_RULE[disjoint_permutation_union] th)) THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN `(y:A) IN t` (LABEL_TAC "y_t") THENL
       [USE_THEN "y_union" MP_TAC THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(f:A->A) x IN s /\ (g:A->A) y IN t`
      (CONJUNCTS_THEN2 (LABEL_TAC "fx_s") (LABEL_TAC "gy_t")) THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`]
            PERMUTES_IN_IMAGE) THEN ASM_REWRITE_TAC[];
          MP_TAC(ISPECL [`g:A->A`; `t:A->bool`; `y:A`]
            PERMUTES_IN_IMAGE) THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN `(f:A->A) x = (g:A->A) y`
      (LABEL_TAC "images_equal") THENL
       [REMOVE_THEN "equal"
         (fun th -> MP_TAC(REWRITE_RULE[disjoint_permutation_union] th)) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(f:A->A) x IN t` (LABEL_TAC "fx_t") THENL
       [USE_THEN "images_equal" (fun th ->
         USE_THEN "gy_t" (ACCEPT_TAC o REWRITE_RULE[GSYM th]));
        ALL_TAC] THEN
      USE_THEN "disjoint" MP_TAC THEN
      REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
      DISCH_THEN(MP_TAC o SPEC `(f:A->A) x`) THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN `(x:A) IN t` (LABEL_TAC "x_t") THENL
       [USE_THEN "x_union" MP_TAC THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(g:A->A) x IN t /\ (f:A->A) y IN s`
      (CONJUNCTS_THEN2 (LABEL_TAC "gx_t") (LABEL_TAC "fy_s")) THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL [`g:A->A`; `t:A->bool`; `x:A`]
            PERMUTES_IN_IMAGE) THEN ASM_REWRITE_TAC[];
          MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `y:A`]
            PERMUTES_IN_IMAGE) THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN `(g:A->A) x = (f:A->A) y`
      (LABEL_TAC "images_equal") THENL
       [REMOVE_THEN "equal"
         (fun th -> MP_TAC(REWRITE_RULE[disjoint_permutation_union] th)) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(f:A->A) y IN t` (LABEL_TAC "fy_t") THENL
       [USE_THEN "images_equal" (fun th ->
         USE_THEN "gx_t" (ACCEPT_TAC o REWRITE_RULE[th]));
        ALL_TAC] THEN
      USE_THEN "disjoint" MP_TAC THEN
      REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
      DISCH_THEN(MP_TAC o SPEC `(f:A->A) y`) THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN `(x:A) IN t /\ (y:A) IN t`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[];
        ALL_TAC] THEN
      MATCH_MP_TAC
       (fst(EQ_IMP_RULE
        (SPECL [`x:A`; `y:A`]
         (MATCH_MP
          (ISPECL [`g:A->A`; `t:A->bool`] PERMUTES_INJECTIVE)
          (ASSUME `(g:A->A) permutes t`))))) THEN
      REMOVE_THEN "equal"
       (fun th -> MP_TAC(REWRITE_RULE[disjoint_permutation_union] th)) THEN
      ASM_REWRITE_TAC[]]]);;

let DISJOINT_PERMUTATION_UNION_PRESERVES_KEY = prove
 (`!f g:A->A. !s t. !k:A->B.
        (!x. x IN s ==> k(f x) = k x) /\
        (!x. x IN t ==> k(g x) = k x)
        ==> !x.
              x IN s UNION t
              ==> k(disjoint_permutation_union f s g x) = k x`,
  REPEAT GEN_TAC THEN INTRO_TAC "f_preserves g_preserves" THEN
  X_GEN_TAC `x:A` THEN REWRITE_TAC[IN_UNION] THEN
  DISCH_THEN(DISJ_CASES_THEN2
    (LABEL_TAC "x_s") (LABEL_TAC "x_t")) THENL
   [ASM_REWRITE_TAC[disjoint_permutation_union] THEN
    USE_THEN "f_preserves" (MATCH_MP_TAC o SPEC `x:A`) THEN
    USE_THEN "x_s" ACCEPT_TAC;
    ASM_CASES_TAC `(x:A) IN s` THEN
    ASM_REWRITE_TAC[disjoint_permutation_union] THENL
     [USE_THEN "f_preserves" (MATCH_MP_TAC o SPEC `x:A`) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "g_preserves" (MATCH_MP_TAC o SPEC `x:A`) THEN
      USE_THEN "x_t" ACCEPT_TAC]]);;

let DISJOINT_PERMUTATION_UNION_ITER_LEFT = prove
 (`!f g:A->A. !s x.
        f permutes s /\
        x IN s
        ==> !n.
              ITER n (disjoint_permutation_union f s g) x =
              ITER n f x /\
              ITER n f x IN s`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation member" THEN
  INDUCT_TAC THENL
   [ASM_REWRITE_TAC[ITER];
    FIRST_X_ASSUM
     (CONJUNCTS_THEN2 (LABEL_TAC "same")
      (LABEL_TAC "iter_member")) THEN
    REWRITE_TAC[ITER] THEN
    USE_THEN "same" SUBST1_TAC THEN
    ASM_REWRITE_TAC[disjoint_permutation_union] THEN
    MP_TAC(ISPECL
     [`f:A->A`; `s:A->bool`; `ITER n (f:A->A) x`]
     PERMUTES_IN_IMAGE) THEN
    ASM_REWRITE_TAC[]]);;

let DISJOINT_PERMUTATION_UNION_ITER_RIGHT = prove
 (`!f g:A->A. !s t x.
        g permutes t /\
        DISJOINT s t /\
        x IN t
        ==> !n.
              ITER n (disjoint_permutation_union f s g) x =
              ITER n g x /\
              ITER n g x IN t`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation disjoint member" THEN
  INDUCT_TAC THENL
   [ASM_REWRITE_TAC[ITER];
    FIRST_X_ASSUM
     (CONJUNCTS_THEN2 (LABEL_TAC "same")
      (LABEL_TAC "iter_member")) THEN
    SUBGOAL_THEN `~(ITER n (g:A->A) x IN s)`
    (LABEL_TAC "not_left") THENL
     [USE_THEN "disjoint" MP_TAC THEN
      REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
      DISCH_THEN(MP_TAC o SPEC `ITER n (g:A->A) x`) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[ITER] THEN
    USE_THEN "same" SUBST1_TAC THEN
    ASM_REWRITE_TAC[disjoint_permutation_union] THEN
    MP_TAC(ISPECL
     [`g:A->A`; `t:A->bool`; `ITER n (g:A->A) x`]
     PERMUTES_IN_IMAGE) THEN
    ASM_REWRITE_TAC[]]);;

let DISJOINT_PERMUTATION_UNION_ORBIT_LEFT = prove
 (`!f g:A->A. !s x.
        f permutes s /\
        x IN s /\
        (!y. y IN s ==> ?n. ITER n f x = y)
        ==> permutation_orbit
             (disjoint_permutation_union f s g) x = s`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation member transitive" THEN
  REWRITE_TAC[EXTENSION; IN_PERMUTATION_ORBIT] THEN
  X_GEN_TAC `y:A` THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THEN
    MP_TAC(SPEC `n:num`
     (MATCH_MP
      (ISPECL [`f:A->A`; `g:A->A`; `s:A->bool`; `x:A`]
       DISJOINT_PERMUTATION_UNION_ITER_LEFT)
      (CONJ (ASSUME `(f:A->A) permutes s`)
            (ASSUME `(x:A) IN s`)))) THEN
    ASM_MESON_TAC[];
    DISCH_THEN(LABEL_TAC "y_member") THEN
    SUBGOAL_THEN `?n. ITER n (f:A->A) x = y`
    (X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THENL
     [USE_THEN "transitive" MATCH_MP_TAC THEN
      USE_THEN "y_member" ACCEPT_TAC;
      EXISTS_TAC `n:num` THEN
      MP_TAC(SPEC `n:num`
       (MATCH_MP
        (ISPECL [`f:A->A`; `g:A->A`; `s:A->bool`; `x:A`]
         DISJOINT_PERMUTATION_UNION_ITER_LEFT)
        (CONJ (ASSUME `(f:A->A) permutes s`)
              (ASSUME `(x:A) IN s`)))) THEN
      ASM_MESON_TAC[]]]);;

let DISJOINT_PERMUTATION_UNION_ORBIT_RIGHT = prove
 (`!f g:A->A. !s t x.
        g permutes t /\
        DISJOINT s t /\
        x IN t /\
        (!y. y IN t ==> ?n. ITER n g x = y)
        ==> permutation_orbit
             (disjoint_permutation_union f s g) x = t`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "permutation disjoint member transitive" THEN
  REWRITE_TAC[EXTENSION; IN_PERMUTATION_ORBIT] THEN
  X_GEN_TAC `y:A` THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THEN
    MP_TAC(SPEC `n:num`
     (MATCH_MP
      (ISPECL
       [`f:A->A`; `g:A->A`; `s:A->bool`; `t:A->bool`; `x:A`]
       DISJOINT_PERMUTATION_UNION_ITER_RIGHT)
      (end_itlist CONJ
       [ASSUME `(g:A->A) permutes t`;
        ASSUME `DISJOINT (s:A->bool) t`;
        ASSUME `(x:A) IN t`]))) THEN
    ASM_MESON_TAC[];
    DISCH_THEN(LABEL_TAC "y_member") THEN
    SUBGOAL_THEN `?n. ITER n (g:A->A) x = y`
    (X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THENL
     [USE_THEN "transitive" MATCH_MP_TAC THEN
      USE_THEN "y_member" ACCEPT_TAC;
      EXISTS_TAC `n:num` THEN
      MP_TAC(SPEC `n:num`
       (MATCH_MP
        (ISPECL
         [`f:A->A`; `g:A->A`; `s:A->bool`; `t:A->bool`; `x:A`]
         DISJOINT_PERMUTATION_UNION_ITER_RIGHT)
        (end_itlist CONJ
         [ASSUME `(g:A->A) permutes t`;
          ASSUME `DISJOINT (s:A->bool) t`;
          ASSUME `(x:A) IN t`]))) THEN
      ASM_MESON_TAC[]]]);;

let PERMUTATION_ORBITS_DISJOINT_UNION_TRANSITIVE = prove
 (`!f g:A->A. !s t a b.
        f permutes s /\
        g permutes t /\
        DISJOINT s t /\
        a IN s /\
        b IN t /\
        (!x y. x IN s /\ y IN s ==> ?n. ITER n f x = y) /\
        (!x y. x IN t /\ y IN t ==> ?n. ITER n g x = y)
        ==> permutation_orbits
             (disjoint_permutation_union f s g) (s UNION t) =
            {s,t}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "f_permutation g_permutation disjoint a_member b_member
    f_transitive g_transitive" THEN
  SUBGOAL_THEN
   `permutation_orbit
     (disjoint_permutation_union (f:A->A) s g) a = s`
  (LABEL_TAC "left_orbit") THENL
   [MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_ORBIT_LEFT THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `y:A` THEN DISCH_THEN(LABEL_TAC "y_member") THEN
    USE_THEN "f_transitive"
     (MATCH_MP_TAC o SPECL [`a:A`; `y:A`]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit
     (disjoint_permutation_union (f:A->A) s g) b = t`
  (LABEL_TAC "right_orbit") THENL
   [MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_ORBIT_RIGHT THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `y:A` THEN DISCH_THEN(LABEL_TAC "y_member") THEN
    USE_THEN "g_transitive"
     (MATCH_MP_TAC o SPECL [`b:A`; `y:A`]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_PERMUTATION_ORBITS;
                IN_INSERT; IN_SING] THEN
    X_GEN_TAC `c:A->bool` THEN
    INTRO_TAC "@x. x_union orbit" THEN
    USE_THEN "x_union"
     (DISJ_CASES_THEN2 (LABEL_TAC "x_left")
       (LABEL_TAC "x_right") o REWRITE_RULE[IN_UNION]) THENL
     [DISJ1_TAC THEN
      USE_THEN "orbit" SUBST1_TAC THEN
      MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_ORBIT_LEFT THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `y:A` THEN DISCH_THEN(LABEL_TAC "y_member") THEN
      USE_THEN "f_transitive"
       (MATCH_MP_TAC o SPECL [`x:A`; `y:A`]) THEN
      ASM_REWRITE_TAC[];
      DISJ2_TAC THEN
      USE_THEN "orbit" SUBST1_TAC THEN
      MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_ORBIT_RIGHT THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `y:A` THEN DISCH_THEN(LABEL_TAC "y_member") THEN
      USE_THEN "g_transitive"
       (MATCH_MP_TAC o SPECL [`x:A`; `y:A`]) THEN
      ASM_REWRITE_TAC[]];
    REWRITE_TAC[SUBSET; IN_PERMUTATION_ORBITS;
                IN_INSERT; IN_SING] THEN
    X_GEN_TAC `c:A->bool` THEN
    DISCH_THEN(DISJ_CASES_THEN2
      (LABEL_TAC "left") (LABEL_TAC "right")) THENL
     [EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[IN_UNION];
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[IN_UNION]]]);;

(* ------------------------------------------------------------------------- *)
(* Restricting an invariant permutation to a subset.                         *)
(* ------------------------------------------------------------------------- *)

let restricted_permutation = new_definition
 `restricted_permutation (f:A->A) (s:A->bool) x =
        if x IN s then f x else x`;;

let RESTRICTED_PERMUTATION_PERMUTES = prove
 (`!f:A->A. !u s.
        FINITE s /\
        s SUBSET u /\
        f permutes u /\
        IMAGE f s = s
        ==> restricted_permutation f s permutes s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite subset permutation invariant" THEN
  SUBGOAL_THEN
   `restricted_permutation (f:A->A) s =
    \x. if x IN s then f x else x`
  SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; restricted_permutation];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`u:A->bool`; `s:A->bool`; `f:A->A`]
   RESTRICT_PERMUTES_SUBSET) THEN
  ASM_REWRITE_TAC[]);;

let RESTRICTED_PERMUTATION_ITER = prove
 (`!f:A->A. !s x.
        x IN s /\
        IMAGE f s = s
        ==> !n. ITER n (restricted_permutation f s) x = ITER n f x /\
                ITER n f x IN s`,
  REPEAT GEN_TAC THEN INTRO_TAC "member invariant" THEN
  INDUCT_TAC THENL
   [ASM_REWRITE_TAC[ITER];
    FIRST_X_ASSUM
     (CONJUNCTS_THEN2 (LABEL_TAC "same")
      (LABEL_TAC "iter_member")) THEN
    REWRITE_TAC[ITER] THEN
    USE_THEN "same" SUBST1_TAC THEN
    ASM_REWRITE_TAC[restricted_permutation] THEN
    USE_THEN "invariant" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[IN_IMAGE] THEN
    EXISTS_TAC `ITER n (f:A->A) x` THEN
    ASM_REWRITE_TAC[]]);;

let RESTRICTED_PERMUTATION_TRANSITIVE = prove
 (`!f:A->A. !s.
        IMAGE f s = s /\
        (!x y. x IN s /\ y IN s ==> ?n. ITER n f x = y)
        ==> !x y.
              x IN s /\ y IN s
              ==> ?n. ITER n (restricted_permutation f s) x = y`,
  REPEAT GEN_TAC THEN INTRO_TAC "invariant transitive" THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
  INTRO_TAC "x_member y_member" THEN
  SUBGOAL_THEN `?n. ITER n (f:A->A) x = y`
  (X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THENL
   [USE_THEN "transitive"
     (MATCH_MP_TAC o SPECL [`x:A`; `y:A`]) THEN
    ASM_REWRITE_TAC[];
    EXISTS_TAC `n:num` THEN
    MP_TAC(SPEC `n:num`
     (MATCH_MP
      (ISPECL [`f:A->A`; `s:A->bool`; `x:A`]
       RESTRICTED_PERMUTATION_ITER)
      (CONJ (ASSUME `(x:A) IN s`)
            (ASSUME `IMAGE (f:A->A) s = s`)))) THEN
    ASM_MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Orbit counts under a two-point permutation surgery.                       *)
(* ------------------------------------------------------------------------- *)

let PERMUTATION_ORBIT_EQ_IF_AGREE = prove
 (`!f g:A->A. !x.
        (!z. z IN permutation_orbit f x ==> g z = f z)
        ==> permutation_orbit g x = permutation_orbit f x`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "agree") THEN
  SUBGOAL_THEN
   `!n. ITER n (g:A->A) x = ITER n f x`
  (LABEL_TAC "iter") THENL
   [INDUCT_TAC THEN ASM_REWRITE_TAC[ITER] THEN
    USE_THEN "agree" MATCH_MP_TAC THEN
    REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
    EXISTS_TAC `n:num` THEN REFL_TAC;
    REWRITE_TAC[EXTENSION; IN_PERMUTATION_ORBIT] THEN
    ASM_MESON_TAC[]]);;

let PERMUTATION_ORBITS_TWO_POINT_SURGERY_LE = prove
 (`!f g:A->A. !s x y.
        FINITE s /\
        f permutes s /\
        g permutes (s DELETE x DELETE y) /\
        x IN s /\
        y IN s /\
        ~(x = y) /\
        ~(f x = x) /\
        (!z. z IN s DELETE x DELETE y /\
             ~(f z = x) /\ ~(f z = y)
             ==> g z = f z)
        ==> CARD(permutation_orbits f s) <=
            CARD(permutation_orbits g (s DELETE x DELETE y)) + 1`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite old_permutation new_permutation x y distinct nonfixed agree" THEN
  ABBREV_TAC
   `ox:A->bool = permutation_orbit (f:A->A) (x:A)` THEN
  ABBREV_TAC
   `oy:A->bool = permutation_orbit (f:A->A) (y:A)` THEN
  ABBREV_TAC
   `old:(A->bool)->bool =
      permutation_orbits (f:A->A) (s:A->bool)` THEN
  ABBREV_TAC
   `new:(A->bool)->bool =
      permutation_orbits (g:A->A)
       ((s:A->bool) DELETE (x:A) DELETE (y:A))` THEN
  ABBREV_TAC
   `unaffected:(A->bool)->bool = old DELETE ox DELETE oy` THEN
  SUBGOAL_THEN `FINITE(old:(A->bool)->bool)`
  (LABEL_TAC "finite_old") THENL
   [EXPAND_TAC "old" THEN
    MATCH_MP_TAC FINITE_PERMUTATION_ORBITS THEN
    USE_THEN "finite" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(new:(A->bool)->bool)`
  (LABEL_TAC "finite_new") THENL
   [EXPAND_TAC "new" THEN
    MATCH_MP_TAC FINITE_PERMUTATION_ORBITS THEN
    ASM_REWRITE_TAC[FINITE_DELETE];
    ALL_TAC] THEN
  SUBGOAL_THEN `(ox:A->bool) IN old`
  (LABEL_TAC "ox_old") THENL
   [EXPAND_TAC "old" THEN REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
    EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[] THEN
    EXPAND_TAC "ox" THEN REFL_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(oy:A->bool) IN old`
  (LABEL_TAC "oy_old") THENL
   [EXPAND_TAC "old" THEN REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
    EXPAND_TAC "oy" THEN REFL_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(unaffected:(A->bool)->bool) SUBSET new`
  (LABEL_TAC "unaffected_subset") THENL
   [REWRITE_TAC[SUBSET] THEN X_GEN_TAC `c:A->bool` THEN
    EXPAND_TAC "unaffected" THEN REWRITE_TAC[IN_DELETE] THEN
    INTRO_TAC "(c_old c_not_ox) c_not_oy" THEN
    USE_THEN "c_old" MP_TAC THEN EXPAND_TAC "old" THEN
    REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A`
     (CONJUNCTS_THEN2 (LABEL_TAC "a_member") (LABEL_TAC "c_orbit"))) THEN
    SUBGOAL_THEN `~(a:A = x) /\ ~(a = y)`
    (CONJUNCTS_THEN2 (LABEL_TAC "a_not_x") (LABEL_TAC "a_not_y")) THENL
     [ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!z:A. z IN permutation_orbit f a ==> (g:A->A) z = f z`
    (LABEL_TAC "orbit_agreement") THENL
     [X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_orbit") THEN
      SUBGOAL_THEN `(z:A) IN s` (LABEL_TAC "z_member") THENL
       [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`]
          PERMUTATION_ORBIT_SUBSET) THEN
        ASM_REWRITE_TAC[SUBSET] THEN
        DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(f:A->A) z IN permutation_orbit f a`
      (LABEL_TAC "fz_orbit") THENL
       [USE_THEN "z_orbit" MP_TAC THEN
        REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
        DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "z_step")) THEN
        REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
        EXISTS_TAC `SUC n` THEN REWRITE_TAC[ITER] THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `permutation_orbit (f:A->A) z = permutation_orbit f a`
      (LABEL_TAC "z_same_orbit") THENL
       [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `z:A`]
          PERMUTATION_ORBIT_EQ) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `permutation_orbit (f:A->A) (f z) = permutation_orbit f a`
      (LABEL_TAC "fz_same_orbit") THENL
       [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `(f:A->A) z`]
          PERMUTATION_ORBIT_EQ) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `~(z:A = x) /\ ~(z = y) /\
        ~((f:A->A) z = x) /\ ~(f z = y)`
      STRIP_ASSUME_TAC THENL
       [EXPAND_TAC "ox" THEN EXPAND_TAC "oy" THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      USE_THEN "agree" (MATCH_MP_TAC o SPEC `z:A`) THEN
      ASM_REWRITE_TAC[IN_DELETE];
      ALL_TAC] THEN
    EXPAND_TAC "new" THEN REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
    EXISTS_TAC `a:A` THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[IN_DELETE];
      USE_THEN "c_orbit" SUBST1_TAC THEN
      CONV_TAC SYM_CONV THEN
      MATCH_MP_TAC PERMUTATION_ORBIT_EQ_IF_AGREE THEN
      USE_THEN "orbit_agreement" ACCEPT_TAC];
    ALL_TAC] THEN
  ASM_CASES_TAC `(ox:A->bool) = oy` THENL
   [FIRST_X_ASSUM(LABEL_TAC "same_orbit") THEN
    SUBGOAL_THEN
     `old:(A->bool)->bool = ox INSERT unaffected`
    (LABEL_TAC "old_decomposition") THENL
     [EXPAND_TAC "unaffected" THEN
      USE_THEN "same_orbit" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[DELETE_DELETE] THEN CONV_TAC SYM_CONV THEN
      MATCH_MP_TAC INSERT_DELETE THEN
      USE_THEN "ox_old" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((ox:A->bool) IN unaffected)`
    (LABEL_TAC "ox_not_unaffected") THENL
     [EXPAND_TAC "unaffected" THEN REWRITE_TAC[IN_DELETE];
      ALL_TAC] THEN
    SUBGOAL_THEN `FINITE(unaffected:(A->bool)->bool)`
    (LABEL_TAC "finite_unaffected") THENL
     [EXPAND_TAC "unaffected" THEN ASM_REWRITE_TAC[FINITE_DELETE];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD(unaffected:(A->bool)->bool) <=
      CARD(new:(A->bool)->bool)`
    (LABEL_TAC "unaffected_card") THENL
     [USE_THEN "unaffected_subset" (fun subset_th ->
       USE_THEN "finite_new" (fun finite_th ->
        MATCH_ACCEPT_TAC(MATCH_MP (SPEC_ALL CARD_SUBSET)
         (CONJ subset_th finite_th))));
      USE_THEN "old_decomposition" SUBST1_TAC THEN
      ASM_SIMP_TAC[CARD_CLAUSES; ARITH_RULE `n + 1 = SUC n`;
                   ARITH_RULE `SUC m <= SUC n <=> m <= n`]];
    FIRST_X_ASSUM(LABEL_TAC "different_orbits") THEN
    SUBGOAL_THEN
     `old:(A->bool)->bool = ox INSERT oy INSERT unaffected`
    (LABEL_TAC "old_decomposition") THENL
      [EXPAND_TAC "unaffected" THEN
      CONV_TAC SYM_CONV THEN
      TRANS_TAC EQ_TRANS
       `ox INSERT (old DELETE ox):(A->bool)->bool` THEN
      CONJ_TAC THENL
       [AP_TERM_TAC THEN MATCH_MP_TAC INSERT_DELETE THEN
        ASM_REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[];
        MATCH_MP_TAC INSERT_DELETE THEN
        USE_THEN "ox_old" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((ox:A->bool) IN unaffected) /\
      ~((oy:A->bool) IN unaffected) /\
      ~(ox = oy)`
    (CONJUNCTS_THEN2 (LABEL_TAC "ox_not_unaffected")
      (CONJUNCTS_THEN2 (LABEL_TAC "oy_not_unaffected")
       (LABEL_TAC "orbits_distinct"))) THENL
     [EXPAND_TAC "unaffected" THEN
      ASM_REWRITE_TAC[IN_DELETE];
      ALL_TAC] THEN
    SUBGOAL_THEN `FINITE(unaffected:(A->bool)->bool)`
    (LABEL_TAC "finite_unaffected") THENL
     [EXPAND_TAC "unaffected" THEN ASM_REWRITE_TAC[FINITE_DELETE];
      ALL_TAC] THEN
    SUBGOAL_THEN `(f:A->A) x IN s DELETE x DELETE y`
    (LABEL_TAC "fx_survives") THENL
     [SUBGOAL_THEN `(f:A->A) x IN s` (LABEL_TAC "fx_member") THENL
       [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`]
          PERMUTES_IN_IMAGE) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `~((f:A->A) x = y)` (LABEL_TAC "fx_not_y") THENL
       [DISCH_THEN(LABEL_TAC "fx_y") THEN
        SUBGOAL_THEN
         `(y:A) IN permutation_orbit f x`
        (LABEL_TAC "y_orbit") THENL
         [REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
          EXISTS_TAC `1` THEN ASM_REWRITE_TAC[ITER_1];
          ALL_TAC] THEN
        SUBGOAL_THEN
         `permutation_orbit (f:A->A) y = permutation_orbit f x`
        (LABEL_TAC "same_old_orbit") THENL
         [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`; `y:A`]
            PERMUTATION_ORBIT_EQ) THEN
          ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        USE_THEN "different_orbits" MP_TAC THEN
        EXPAND_TAC "ox" THEN EXPAND_TAC "oy" THEN
        USE_THEN "same_old_orbit" MP_TAC THEN MESON_TAC[];
        ASM_REWRITE_TAC[IN_DELETE]];
      ALL_TAC] THEN
    ABBREV_TAC
     `q:A->bool =
        permutation_orbit (g:A->A) ((f:A->A) (x:A))` THEN
    SUBGOAL_THEN `(q:A->bool) IN new`
    (LABEL_TAC "q_new") THENL
     [EXPAND_TAC "new" THEN REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
      EXISTS_TAC `(f:A->A) x` THEN ASM_REWRITE_TAC[] THEN
      EXPAND_TAC "q" THEN REFL_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((q:A->bool) IN unaffected)`
    (LABEL_TAC "q_not_unaffected") THENL
     [DISCH_THEN(LABEL_TAC "q_unaffected") THEN
      USE_THEN "q_unaffected" MP_TAC THEN
      EXPAND_TAC "unaffected" THEN REWRITE_TAC[IN_DELETE] THEN
      INTRO_TAC "(q_old q_not_ox) q_not_oy" THEN
      USE_THEN "q_old" MP_TAC THEN EXPAND_TAC "old" THEN
      REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
      DISCH_THEN(X_CHOOSE_THEN `a:A`
       (CONJUNCTS_THEN2 (LABEL_TAC "a_member") (LABEL_TAC "q_old_orbit"))) THEN
      SUBGOAL_THEN `(f:A->A) x IN permutation_orbit f a`
      (LABEL_TAC "fx_old_orbit") THENL
       [USE_THEN "q_old_orbit" (SUBST1_TAC o SYM) THEN
        EXPAND_TAC "q" THEN
        ACCEPT_TAC(ISPECL
         [`g:A->A`; `(f:A->A) x`] PERMUTATION_ORBIT_REFL);
        ALL_TAC] THEN
      SUBGOAL_THEN
       `permutation_orbit (f:A->A) (f x) = permutation_orbit f a`
      (LABEL_TAC "fx_same_a") THENL
       [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `(f:A->A) x`]
          PERMUTATION_ORBIT_EQ) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `permutation_orbit (f:A->A) (f x) = ox`
      (LABEL_TAC "fx_same_x") THENL
       [SUBGOAL_THEN
         `(f:A->A) x IN permutation_orbit f x`
        (LABEL_TAC "fx_orbit_x") THENL
         [REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
          EXISTS_TAC `1` THEN REWRITE_TAC[ITER_1];
          ALL_TAC] THEN
        EXPAND_TAC "ox" THEN
        MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`; `(f:A->A) x`]
          PERMUTATION_ORBIT_EQ) THEN
        ASM_REWRITE_TAC[];
        USE_THEN "q_not_ox" MP_TAC THEN
        USE_THEN "q_old_orbit" MP_TAC THEN
        USE_THEN "fx_same_a" MP_TAC THEN
        USE_THEN "fx_same_x" MP_TAC THEN MESON_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `q INSERT unaffected SUBSET (new:(A->bool)->bool)`
    (LABEL_TAC "extended_subset") THENL
     [REWRITE_TAC[SUBSET; IN_INSERT] THEN X_GEN_TAC `c:A->bool` THEN
      DISCH_THEN(DISJ_CASES_THEN2 SUBST1_TAC (LABEL_TAC "c_unaffected")) THENL
       [USE_THEN "q_new" ACCEPT_TAC;
        USE_THEN "unaffected_subset" MP_TAC THEN
        REWRITE_TAC[SUBSET] THEN
        DISCH_THEN(MP_TAC o SPEC `c:A->bool`) THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD(q INSERT unaffected:(A->bool)->bool) <=
      CARD(new:(A->bool)->bool)`
    (LABEL_TAC "extended_card") THENL
     [USE_THEN "extended_subset" (fun subset_th ->
       USE_THEN "finite_new" (fun finite_th ->
        MATCH_ACCEPT_TAC(MATCH_MP (SPEC_ALL CARD_SUBSET)
         (CONJ subset_th finite_th))));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((ox:A->bool) IN oy INSERT unaffected)`
    (LABEL_TAC "ox_not_inner") THENL
     [ASM_REWRITE_TAC[IN_INSERT];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `FINITE(oy INSERT unaffected:(A->bool)->bool)`
    (LABEL_TAC "finite_inner") THENL
     [ASM_REWRITE_TAC[FINITE_INSERT];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `SUC(CARD(unaffected:(A->bool)->bool)) <=
      CARD(new:(A->bool)->bool)`
    (LABEL_TAC "normalized_extended_card") THENL
     [USE_THEN "finite_unaffected" (fun finite_th ->
       USE_THEN "q_not_unaffected" (fun notin_th ->
        USE_THEN "extended_card" (fun card_th ->
         MATCH_ACCEPT_TAC
          (SIMP_RULE[CARD_CLAUSES; finite_th; notin_th] card_th))));
      ALL_TAC] THEN
    USE_THEN "old_decomposition" SUBST1_TAC THEN
    ASM_SIMP_TAC[CARD_CLAUSES; ARITH_RULE `n + 1 = SUC n`;
                 ARITH_RULE `SUC m <= SUC n <=> m <= n`]]);;

(* ------------------------------------------------------------------------- *)
(* Orbit counts under composition with a transposition.                      *)
(* ------------------------------------------------------------------------- *)

let PERMUTATION_SWAP_PERMUTES = prove
 (`!f:A->A. !s a b.
        f permutes s /\ a IN s /\ b IN s
        ==> (swap(a,b) o f) permutes s`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation a b" THEN
  MATCH_MP_TAC PERMUTES_COMPOSE THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC PERMUTES_SWAP THEN ASM_REWRITE_TAC[]);;

let FINITE_PERMUTES_LEAST_PERIOD = prove
 (`!f:A->A. !s x.
        FINITE s /\ f permutes s /\ x IN s
        ==> ?d. 0 < d /\
                ITER d f x = x /\
                (!n. 0 < n /\ n < d ==> ~(ITER n f x = x))`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutation member" THEN
  SUBGOAL_THEN
   `?n. 0 < n /\ ITER n (f:A->A) x = x`
  (LABEL_TAC "period") THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`]
      FINITE_PERMUTES_PERIODIC) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPEC
   `\n:num. 0 < n /\ ITER n (f:A->A) x = x` num_WOP) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:num`
   (CONJUNCTS_THEN2
    (CONJUNCTS_THEN2 (LABEL_TAC "positive") (LABEL_TAC "return"))
    (LABEL_TAC "least"))) THEN
  EXISTS_TAC `d:num` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `n:num` THEN INTRO_TAC "positive_n less" THEN
  DISCH_THEN(LABEL_TAC "early_return") THEN
  USE_THEN "least" (fun least_th ->
   USE_THEN "less" (fun less_th ->
    USE_THEN "positive_n" (fun positive_th ->
     USE_THEN "early_return" (fun return_th ->
      ACCEPT_TAC
       (MP (NOT_ELIM(MP (SPEC `n:num` least_th) less_th))
           (CONJ positive_th return_th)))))));;

let PERMUTATION_SWAP_MERGES_DISTINCT_ORBITS = prove
 (`!f:A->A. !s a b.
        FINITE s /\
        f permutes s /\
        a IN s /\
        b IN s /\
        ~(permutation_orbit f a = permutation_orbit f b)
        ==> b IN permutation_orbit (swap(a,b) o f) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite permutation a b different_orbits" THEN
  ABBREV_TAC `g:A->A = swap((a:A),(b:A)) o (f:A->A)` THEN
  SUBGOAL_THEN `~((b:A) IN permutation_orbit f a)`
  (LABEL_TAC "b_not_old_orbit") THENL
   [DISCH_THEN(LABEL_TAC "b_old_orbit") THEN
    MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `b:A`]
      PERMUTATION_ORBIT_EQ) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "different_orbits" MP_TAC THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`]
    FINITE_PERMUTES_LEAST_PERIOD) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:num`
   (CONJUNCTS_THEN2 (LABEL_TAC "positive")
    (CONJUNCTS_THEN2 (LABEL_TAC "return") (LABEL_TAC "least")))) THEN
  SUBGOAL_THEN
   `!k. k < d ==> ITER k (g:A->A) a = ITER k f a`
  (LABEL_TAC "same_before_return") THENL
   [INDUCT_TAC THENL
     [REWRITE_TAC[ITER];
      FIRST_X_ASSUM(LABEL_TAC "induction") THEN
      REWRITE_TAC[ITER] THEN DISCH_THEN(LABEL_TAC "less") THEN
      SUBGOAL_THEN `(k:num) < (d:num)`
      (LABEL_TAC "previous_less") THENL
       [USE_THEN "less" MP_TAC THEN ARITH_TAC;
        ALL_TAC] THEN
      USE_THEN "previous_less" (fun less_th ->
       USE_THEN "induction" (fun induction_th ->
        MP_TAC(MATCH_MP induction_th less_th))) THEN
      DISCH_THEN SUBST1_TAC THEN
      SUBGOAL_THEN
       `~(ITER (SUC k) (f:A->A) a = a)`
      (LABEL_TAC "not_return") THENL
       [USE_THEN "least" (MATCH_MP_TAC o SPEC `SUC k`) THEN
        CONJ_TAC THENL
         [ARITH_TAC;
          USE_THEN "less" ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `~(ITER (SUC k) (f:A->A) a = b)`
      (LABEL_TAC "not_b") THENL
       [DISCH_THEN(LABEL_TAC "hits_b") THEN
        USE_THEN "b_not_old_orbit" (MATCH_MP_TAC o NOT_ELIM) THEN
        REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
        EXISTS_TAC `SUC k` THEN
        USE_THEN "hits_b" ACCEPT_TAC;
        ALL_TAC] THEN
      EXPAND_TAC "g" THEN REWRITE_TAC[o_THM] THEN
      MATCH_MP_TAC SWAP_OTHER THEN
      CONJ_TAC THENL
       [USE_THEN "not_return"
         (ACCEPT_TAC o REWRITE_RULE[ITER]);
        USE_THEN "not_b"
         (ACCEPT_TAC o REWRITE_RULE[ITER])]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?j:num. d = SUC j`
  (X_CHOOSE_THEN `j:num` (LABEL_TAC "d_suc")) THENL
   [EXISTS_TAC `d - 1` THEN
    USE_THEN "positive" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
  EXISTS_TAC `SUC j` THEN REWRITE_TAC[ITER] THEN
  SUBGOAL_THEN `(j:num) < (d:num)` (LABEL_TAC "j_less") THENL
   [USE_THEN "d_suc" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `ITER j (g:A->A) a = ITER j (f:A->A) a`
  SUBST1_TAC THENL
   [USE_THEN "same_before_return" (fun same_th ->
     USE_THEN "j_less" (fun less_th ->
      ACCEPT_TAC(MATCH_MP (SPEC `j:num` same_th) less_th)));
    ALL_TAC] THEN
  EXPAND_TAC "g" THEN REWRITE_TAC[o_THM] THEN
  SUBGOAL_THEN `(f:A->A) (ITER j f a) = a`
  SUBST1_TAC THENL
   [USE_THEN "return" MP_TAC THEN
    USE_THEN "d_suc" (fun th -> REWRITE_TAC[th; ITER]) THEN
    DISCH_THEN ACCEPT_TAC;
    REWRITE_TAC[SWAP_LEFT]]);;

let PERMUTATION_ORBIT_SUCCESSOR = prove
 (`!f:A->A. !x y.
        y IN permutation_orbit f x
        ==> f y IN permutation_orbit f x`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THEN
  EXISTS_TAC `SUC n` THEN REWRITE_TAC[ITER] THEN
  ASM_REWRITE_TAC[]);;

let PERMUTATION_SWAP_AFFECTED_ORBIT_HITS = prove
 (`!f:A->A. !s a b z.
        FINITE s /\
        f permutes s /\
        a IN s /\
        b IN s /\
        z IN s /\
        (z IN permutation_orbit f a \/
         z IN permutation_orbit f b)
        ==> a IN permutation_orbit (swap(a,b) o f) z \/
            b IN permutation_orbit (swap(a,b) o f) z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite permutation a b z affected" THEN
  ABBREV_TAC `g:A->A = swap((a:A),(b:A)) o (f:A->A)` THEN
  MATCH_MP_TAC(TAUT `(~p /\ ~q ==> F) ==> p \/ q`) THEN
  INTRO_TAC "not_a not_b" THEN
  SUBGOAL_THEN
   `!w:A. w IN permutation_orbit g z ==> (f:A->A) w = g w`
  (LABEL_TAC "orbit_agreement") THENL
   [X_GEN_TAC `w:A` THEN DISCH_THEN(LABEL_TAC "w_orbit") THEN
    SUBGOAL_THEN
     `~((f:A->A) w = a) /\ ~(f w = b)`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [DISCH_THEN(LABEL_TAC "fw_a") THEN
        USE_THEN "not_b" (MATCH_MP_TAC o NOT_ELIM) THEN
        SUBGOAL_THEN `(g:A->A) w = b` (SUBST1_TAC o SYM) THENL
         [EXPAND_TAC "g" THEN ASM_REWRITE_TAC[o_THM; SWAP_LEFT];
          MATCH_MP_TAC(ISPECL [`g:A->A`; `z:A`; `w:A`]
           PERMUTATION_ORBIT_SUCCESSOR) THEN
          USE_THEN "w_orbit" ACCEPT_TAC];
        DISCH_THEN(LABEL_TAC "fw_b") THEN
        USE_THEN "not_a" (MATCH_MP_TAC o NOT_ELIM) THEN
        SUBGOAL_THEN `(g:A->A) w = a` (SUBST1_TAC o SYM) THENL
         [EXPAND_TAC "g" THEN ASM_REWRITE_TAC[o_THM; SWAP_RIGHT];
          MATCH_MP_TAC(ISPECL [`g:A->A`; `z:A`; `w:A`]
           PERMUTATION_ORBIT_SUCCESSOR) THEN
          USE_THEN "w_orbit" ACCEPT_TAC]];
      ALL_TAC] THEN
    EXPAND_TAC "g" THEN REWRITE_TAC[o_THM] THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC SWAP_OTHER THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit (f:A->A) z = permutation_orbit g z`
  (LABEL_TAC "same_orbit") THENL
   [USE_THEN "orbit_agreement" (fun agreement_th ->
     ACCEPT_TAC(MATCH_MP
      (ISPECL [`g:A->A`; `f:A->A`; `z:A`]
       PERMUTATION_ORBIT_EQ_IF_AGREE)
      agreement_th));
    ALL_TAC] THEN
  USE_THEN "affected"
   (DISJ_CASES_THEN2 (LABEL_TAC "from_a") (LABEL_TAC "from_b")) THENL
   [SUBGOAL_THEN
     `permutation_orbit (f:A->A) z = permutation_orbit f a`
    (LABEL_TAC "old_same_a") THENL
     [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `z:A`]
       PERMUTATION_ORBIT_EQ) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "not_a" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "same_orbit" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "old_same_a" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL;
    SUBGOAL_THEN
     `permutation_orbit (f:A->A) z = permutation_orbit f b`
    (LABEL_TAC "old_same_b") THENL
     [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `b:A`; `z:A`]
       PERMUTATION_ORBIT_EQ) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "not_b" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "same_orbit" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "old_same_b" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL]);;

let PERMUTATION_SWAP_UNAFFECTED_ORBIT = prove
 (`!f:A->A. !s a b z.
        FINITE s /\
        f permutes s /\
        a IN s /\
        b IN s /\
        z IN s /\
        ~(z IN permutation_orbit f a) /\
        ~(z IN permutation_orbit f b)
        ==> permutation_orbit (swap(a,b) o f) z =
            permutation_orbit f z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite permutation a b z not_a not_b" THEN
  MATCH_MP_TAC PERMUTATION_ORBIT_EQ_IF_AGREE THEN
  X_GEN_TAC `w:A` THEN DISCH_THEN(LABEL_TAC "w_orbit") THEN
  SUBGOAL_THEN
   `(f:A->A) w IN permutation_orbit f z`
  (LABEL_TAC "fw_orbit") THENL
   [MATCH_MP_TAC(ISPECL [`f:A->A`; `z:A`; `w:A`]
      PERMUTATION_ORBIT_SUCCESSOR) THEN
    USE_THEN "w_orbit" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((f:A->A) w = a) /\ ~(f w = b)`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "fw_a") THEN
      USE_THEN "not_a" (MATCH_MP_TAC o NOT_ELIM) THEN
      MATCH_MP_TAC(ISPECL
       [`f:A->A`; `s:A->bool`; `z:A`; `a:A`]
       PERMUTATION_ORBIT_SYM) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "fw_a" (fun eq_th ->
       USE_THEN "fw_orbit"
        (ACCEPT_TAC o REWRITE_RULE[eq_th]));
      DISCH_THEN(LABEL_TAC "fw_b") THEN
      USE_THEN "not_b" (MATCH_MP_TAC o NOT_ELIM) THEN
      MATCH_MP_TAC(ISPECL
       [`f:A->A`; `s:A->bool`; `z:A`; `b:A`]
       PERMUTATION_ORBIT_SYM) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "fw_b" (fun eq_th ->
       USE_THEN "fw_orbit"
        (ACCEPT_TAC o REWRITE_RULE[eq_th]))];
    REWRITE_TAC[o_THM] THEN MATCH_MP_TAC SWAP_OTHER THEN
    ASM_REWRITE_TAC[]]);;

let PERMUTATION_ORBITS_SWAP_SUBSET = prove
 (`!f:A->A. !s a b.
        FINITE s /\
        f permutes s /\
        a IN s /\
        b IN s
        ==> permutation_orbits (swap(a,b) o f) s SUBSET
            permutation_orbit (swap(a,b) o f) a INSERT
            permutation_orbit (swap(a,b) o f) b INSERT
            (permutation_orbits f s DELETE permutation_orbit f a
                                      DELETE permutation_orbit f b)`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutation a b" THEN
  SUBGOAL_THEN `(swap((a:A),(b:A)) o (f:A->A)) permutes s`
  (LABEL_TAC "new_permutation") THENL
   [MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET; IN_PERMUTATION_ORBITS] THEN
  X_GEN_TAC `c:A->bool` THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "z_member") (LABEL_TAC "c_orbit"))) THEN
  ASM_CASES_TAC
   `(z:A) IN permutation_orbit f a \/
    z IN permutation_orbit f b` THENL
   [FIRST_X_ASSUM(LABEL_TAC "affected") THEN
    MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `b:A`; `z:A`]
      PERMUTATION_SWAP_AFFECTED_ORBIT_HITS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(DISJ_CASES_THEN2
     (LABEL_TAC "hits_a") (LABEL_TAC "hits_b")) THENL
     [USE_THEN "c_orbit" SUBST1_TAC THEN
      REWRITE_TAC[IN_INSERT] THEN DISJ1_TAC THEN
      CONV_TAC SYM_CONV THEN
      MP_TAC(ISPECL
       [`swap((a:A),(b:A)) o (f:A->A)`;
        `s:A->bool`; `z:A`; `a:A`]
       PERMUTATION_ORBIT_EQ) THEN ASM_REWRITE_TAC[];
      USE_THEN "c_orbit" SUBST1_TAC THEN
      REWRITE_TAC[IN_INSERT] THEN DISJ2_TAC THEN DISJ1_TAC THEN
      CONV_TAC SYM_CONV THEN
      MP_TAC(ISPECL
       [`swap((a:A),(b:A)) o (f:A->A)`;
        `s:A->bool`; `z:A`; `b:A`]
       PERMUTATION_ORBIT_EQ) THEN ASM_REWRITE_TAC[]];
    FIRST_X_ASSUM(LABEL_TAC "unaffected") THEN
    SUBGOAL_THEN
     `permutation_orbit (swap((a:A),(b:A)) o f) z =
      permutation_orbit f z`
    (LABEL_TAC "same_orbit") THENL
     [MATCH_MP_TAC(ISPECL
       [`f:A->A`; `s:A->bool`; `a:A`; `b:A`; `z:A`]
       PERMUTATION_SWAP_UNAFFECTED_ORBIT) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "unaffected" (fun unaffected_th ->
       ACCEPT_TAC(MATCH_MP (TAUT `~(p \/ q) ==> ~p /\ ~q`)
        unaffected_th));
      ALL_TAC] THEN
    REWRITE_TAC[IN_INSERT] THEN
    DISJ2_TAC THEN DISJ2_TAC THEN
    REWRITE_TAC[IN_DELETE] THEN
    USE_THEN "c_orbit" SUBST1_TAC THEN
    USE_THEN "same_orbit" SUBST1_TAC THEN
    CONJ_TAC THENL
     [CONJ_TAC THENL
       [REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
        EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
        DISCH_THEN(LABEL_TAC "same_a") THEN
        USE_THEN "unaffected" (MATCH_MP_TAC o NOT_ELIM) THEN
        DISJ1_TAC THEN
        MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `z:A`]
          PERMUTATION_ORBIT_EQ) THEN ASM_REWRITE_TAC[]];
      DISCH_THEN(LABEL_TAC "same_b") THEN
      USE_THEN "unaffected" (MATCH_MP_TAC o NOT_ELIM) THEN
      DISJ2_TAC THEN
      MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `b:A`; `z:A`]
        PERMUTATION_ORBIT_EQ) THEN ASM_REWRITE_TAC[]]]);;

let FINITE_CARD_INSERT_LE_ONE = prove
 (`!x:A. !s.
        FINITE s ==> CARD(x INSERT s) <= CARD s + 1`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "finite") THEN
  ASM_CASES_TAC `(x:A) IN s` THEN
  ASM_SIMP_TAC[CARD_CLAUSES] THEN ARITH_TAC);;

let PERMUTATION_ORBITS_SWAP_LE = prove
 (`!f:A->A. !s a b.
        FINITE s /\
        f permutes s /\
        a IN s /\
        b IN s
        ==> CARD(permutation_orbits (swap(a,b) o f) s) <=
            CARD(permutation_orbits f s) + 1`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutation a b" THEN
  ABBREV_TAC
   `old:(A->bool)->bool =
      permutation_orbits (f:A->A) (s:A->bool)` THEN
  ABBREV_TAC
   `new:(A->bool)->bool =
      permutation_orbits (swap((a:A),(b:A)) o (f:A->A)) s` THEN
  ABBREV_TAC
   `oa:A->bool = permutation_orbit (f:A->A) (a:A)` THEN
  ABBREV_TAC
   `ob:A->bool = permutation_orbit (f:A->A) (b:A)` THEN
  ABBREV_TAC
   `ga:A->bool =
      permutation_orbit (swap((a:A),(b:A)) o (f:A->A)) a` THEN
  ABBREV_TAC
   `gb:A->bool =
      permutation_orbit (swap((a:A),(b:A)) o (f:A->A)) b` THEN
  ABBREV_TAC
   `unaffected:(A->bool)->bool = old DELETE oa DELETE ob` THEN
  ABBREV_TAC
   `cover:(A->bool)->bool = ga INSERT gb INSERT unaffected` THEN
  SUBGOAL_THEN `FINITE(old:(A->bool)->bool)`
  (LABEL_TAC "finite_old") THENL
   [EXPAND_TAC "old" THEN MATCH_MP_TAC FINITE_PERMUTATION_ORBITS THEN
    USE_THEN "finite" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(new:(A->bool)->bool)`
  (LABEL_TAC "finite_new") THENL
   [EXPAND_TAC "new" THEN MATCH_MP_TAC FINITE_PERMUTATION_ORBITS THEN
    USE_THEN "finite" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(unaffected:(A->bool)->bool)`
  (LABEL_TAC "finite_unaffected") THENL
   [EXPAND_TAC "unaffected" THEN ASM_REWRITE_TAC[FINITE_DELETE];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(cover:(A->bool)->bool)`
  (LABEL_TAC "finite_cover") THENL
   [EXPAND_TAC "cover" THEN ASM_REWRITE_TAC[FINITE_INSERT];
    ALL_TAC] THEN
  SUBGOAL_THEN `(oa:A->bool) IN old`
  (LABEL_TAC "oa_old") THENL
   [EXPAND_TAC "oa" THEN EXPAND_TAC "old" THEN
    REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(ob:A->bool) IN old`
  (LABEL_TAC "ob_old") THENL
   [EXPAND_TAC "ob" THEN EXPAND_TAC "old" THEN
    REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(new:(A->bool)->bool) SUBSET cover`
  (LABEL_TAC "new_subset") THENL
   [EXPAND_TAC "new" THEN EXPAND_TAC "cover" THEN
    EXPAND_TAC "ga" THEN EXPAND_TAC "gb" THEN
    EXPAND_TAC "unaffected" THEN EXPAND_TAC "oa" THEN
    EXPAND_TAC "ob" THEN EXPAND_TAC "old" THEN
    MATCH_MP_TAC PERMUTATION_ORBITS_SWAP_SUBSET THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(new:(A->bool)->bool) <= CARD(cover:(A->bool)->bool)`
  (LABEL_TAC "new_card") THENL
   [USE_THEN "new_subset" (fun subset_th ->
     USE_THEN "finite_cover" (fun finite_th ->
      MATCH_ACCEPT_TAC(MATCH_MP (SPEC_ALL CARD_SUBSET)
       (CONJ subset_th finite_th))));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(cover:(A->bool)->bool) <=
    CARD(unaffected:(A->bool)->bool) + 2`
  (LABEL_TAC "cover_card") THENL
   [EXPAND_TAC "cover" THEN
    TRANS_TAC LE_TRANS
     `CARD(gb INSERT unaffected:(A->bool)->bool) + 1` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_CARD_INSERT_LE_ONE THEN
      ASM_REWRITE_TAC[FINITE_INSERT];
      MP_TAC(ISPECL
       [`gb:A->bool`; `unaffected:(A->bool)->bool`]
       FINITE_CARD_INSERT_LE_ONE) THEN
      ASM_REWRITE_TAC[] THEN ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(new:(A->bool)->bool) <=
    CARD(unaffected:(A->bool)->bool) + 2`
  (LABEL_TAC "new_unaffected_card") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `(oa:A->bool) = ob` THENL
   [FIRST_X_ASSUM(LABEL_TAC "same_orbit") THEN
    SUBGOAL_THEN
     `old:(A->bool)->bool = oa INSERT unaffected`
    (LABEL_TAC "old_decomposition") THENL
     [EXPAND_TAC "unaffected" THEN
      USE_THEN "same_orbit" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[DELETE_DELETE] THEN CONV_TAC SYM_CONV THEN
      MATCH_MP_TAC INSERT_DELETE THEN
      USE_THEN "oa_old" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((oa:A->bool) IN unaffected)`
    (LABEL_TAC "oa_not_unaffected") THENL
     [EXPAND_TAC "unaffected" THEN REWRITE_TAC[IN_DELETE];
      ALL_TAC] THEN
    USE_THEN "old_decomposition" SUBST1_TAC THEN
    ASM_SIMP_TAC[CARD_CLAUSES] THEN ASM_ARITH_TAC;
    FIRST_X_ASSUM(LABEL_TAC "different_orbits") THEN
    SUBGOAL_THEN
     `old:(A->bool)->bool = oa INSERT ob INSERT unaffected`
    (LABEL_TAC "old_decomposition") THENL
     [EXPAND_TAC "unaffected" THEN CONV_TAC SYM_CONV THEN
      TRANS_TAC EQ_TRANS
       `oa INSERT (old DELETE oa):(A->bool)->bool` THEN
      CONJ_TAC THENL
       [AP_TERM_TAC THEN MATCH_MP_TAC INSERT_DELETE THEN
        ASM_REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[];
        MATCH_MP_TAC INSERT_DELETE THEN
        USE_THEN "oa_old" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((oa:A->bool) IN ob INSERT unaffected) /\
      ~((ob:A->bool) IN unaffected)`
    (CONJUNCTS_THEN2
      (LABEL_TAC "oa_not_inner") (LABEL_TAC "ob_not_unaffected")) THENL
     [EXPAND_TAC "unaffected" THEN
      ASM_REWRITE_TAC[IN_INSERT; IN_DELETE];
      ALL_TAC] THEN
    USE_THEN "old_decomposition" SUBST1_TAC THEN
    ASM_SIMP_TAC[CARD_CLAUSES; FINITE_INSERT] THEN ASM_ARITH_TAC]);;

let PERMUTATION_SWAP_MERGED_ORBITS = prove
 (`!f:A->A. !s a b.
        FINITE s /\
        f permutes s /\
        a IN s /\
        b IN s /\
        ~(permutation_orbit f a = permutation_orbit f b)
        ==> permutation_orbit (swap(a,b) o f) b =
            permutation_orbit (swap(a,b) o f) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite permutation a b different_orbits" THEN
  SUBGOAL_THEN
   `(swap((a:A),(b:A)) o (f:A->A)) permutes s`
  (LABEL_TAC "new_permutation") THENL
   [MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(b:A) IN permutation_orbit (swap(a,b) o f) a`
  (LABEL_TAC "merged") THENL
   [MATCH_MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `b:A`]
      PERMUTATION_SWAP_MERGES_DISTINCT_ORBITS) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(ISPECL
     [`swap((a:A),(b:A)) o (f:A->A)`;
      `s:A->bool`; `a:A`; `b:A`]
     PERMUTATION_ORBIT_EQ) THEN
    ASM_REWRITE_TAC[]]);;

let PERMUTATION_ORBITS_SWAP_DISTINCT = prove
 (`!f:A->A. !s a b.
        FINITE s /\
        f permutes s /\
        a IN s /\
        b IN s /\
        ~(permutation_orbit f a = permutation_orbit f b)
        ==> CARD(permutation_orbits f s) =
            CARD(permutation_orbits (swap(a,b) o f) s) + 1`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite permutation a b different_orbits" THEN
  ABBREV_TAC
   `old:(A->bool)->bool =
      permutation_orbits (f:A->A) (s:A->bool)` THEN
  ABBREV_TAC
   `new:(A->bool)->bool =
      permutation_orbits (swap((a:A),(b:A)) o (f:A->A)) s` THEN
  ABBREV_TAC
   `oa:A->bool = permutation_orbit (f:A->A) (a:A)` THEN
  ABBREV_TAC
   `ob:A->bool = permutation_orbit (f:A->A) (b:A)` THEN
  ABBREV_TAC
   `ga:A->bool =
      permutation_orbit (swap((a:A),(b:A)) o (f:A->A)) a` THEN
  ABBREV_TAC
   `unaffected:(A->bool)->bool = old DELETE oa DELETE ob` THEN
  SUBGOAL_THEN `FINITE(old:(A->bool)->bool)`
  (LABEL_TAC "finite_old") THENL
   [EXPAND_TAC "old" THEN MATCH_MP_TAC FINITE_PERMUTATION_ORBITS THEN
    USE_THEN "finite" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(unaffected:(A->bool)->bool)`
  (LABEL_TAC "finite_unaffected") THENL
   [EXPAND_TAC "unaffected" THEN ASM_REWRITE_TAC[FINITE_DELETE];
    ALL_TAC] THEN
  SUBGOAL_THEN `(oa:A->bool) IN old`
  (LABEL_TAC "oa_old") THENL
   [EXPAND_TAC "oa" THEN EXPAND_TAC "old" THEN
    REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(ob:A->bool) IN old`
  (LABEL_TAC "ob_old") THENL
   [EXPAND_TAC "ob" THEN EXPAND_TAC "old" THEN
    REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit (swap((a:A),(b:A)) o f) b = ga`
  (LABEL_TAC "merged_orbits") THENL
   [EXPAND_TAC "ga" THEN
    MATCH_MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `b:A`]
      PERMUTATION_SWAP_MERGED_ORBITS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(new:(A->bool)->bool) SUBSET ga INSERT unaffected`
  (LABEL_TAC "new_subset") THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `b:A`]
      PERMUTATION_ORBITS_SWAP_SUBSET) THEN
    ASM_REWRITE_TAC[] THEN
    EXPAND_TAC "new" THEN EXPAND_TAC "ga" THEN
    EXPAND_TAC "unaffected" THEN EXPAND_TAC "oa" THEN
    EXPAND_TAC "ob" THEN EXPAND_TAC "old" THEN
    ASM_REWRITE_TAC[INSERT_INSERT];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(ga INSERT unaffected:(A->bool)->bool)`
  (LABEL_TAC "finite_affected_cover") THENL
   [ASM_REWRITE_TAC[FINITE_INSERT];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(new:(A->bool)->bool) <=
    CARD(ga INSERT unaffected:(A->bool)->bool)`
  (LABEL_TAC "new_card") THENL
   [USE_THEN "new_subset" (fun subset_th ->
     USE_THEN "finite_affected_cover" (fun finite_th ->
      MATCH_ACCEPT_TAC(MATCH_MP (SPEC_ALL CARD_SUBSET)
       (CONJ subset_th finite_th))));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(new:(A->bool)->bool) <=
    CARD(unaffected:(A->bool)->bool) + 1`
  (LABEL_TAC "new_unaffected_card") THENL
   [MP_TAC(ISPECL
     [`ga:A->bool`; `unaffected:(A->bool)->bool`]
     FINITE_CARD_INSERT_LE_ONE) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `old:(A->bool)->bool = oa INSERT ob INSERT unaffected`
  (LABEL_TAC "old_decomposition") THENL
   [EXPAND_TAC "unaffected" THEN CONV_TAC SYM_CONV THEN
    TRANS_TAC EQ_TRANS
     `oa INSERT (old DELETE oa):(A->bool)->bool` THEN
    CONJ_TAC THENL
     [AP_TERM_TAC THEN MATCH_MP_TAC INSERT_DELETE THEN
      ASM_REWRITE_TAC[IN_DELETE] THEN
      EXPAND_TAC "oa" THEN EXPAND_TAC "ob" THEN
      USE_THEN "different_orbits" ACCEPT_TAC;
      MATCH_MP_TAC INSERT_DELETE THEN
      USE_THEN "oa_old" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((oa:A->bool) IN ob INSERT unaffected) /\
    ~((ob:A->bool) IN unaffected)`
  (CONJUNCTS_THEN2
    (LABEL_TAC "oa_not_inner") (LABEL_TAC "ob_not_unaffected")) THENL
   [EXPAND_TAC "unaffected" THEN
    ASM_REWRITE_TAC[IN_INSERT; IN_DELETE] THEN
    EXPAND_TAC "oa" THEN EXPAND_TAC "ob" THEN
    USE_THEN "different_orbits" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(new:(A->bool)->bool) + 1 <= CARD(old:(A->bool)->bool)`
  (LABEL_TAC "strict_bound") THENL
   [USE_THEN "old_decomposition" SUBST1_TAC THEN
    ASM_SIMP_TAC[CARD_CLAUSES; FINITE_INSERT] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(old:(A->bool)->bool) <= CARD(new:(A->bool)->bool) + 1`
  (LABEL_TAC "reverse_bound") THENL
   [MP_TAC(ISPECL
     [`swap((a:A),(b:A)) o (f:A->A)`;
      `s:A->bool`; `a:A`; `b:A`]
     PERMUTATION_ORBITS_SWAP_LE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN
      ASM_REWRITE_TAC[];
      EXPAND_TAC "old" THEN EXPAND_TAC "new" THEN
      REWRITE_TAC[o_ASSOC; SWAP_IDEMPOTENT; I_O_ID]];
    ASM_ARITH_TAC]);;

let PERMUTATION_SWAP_SPLITS_SAME_ORBIT = prove
 (`!f:A->A. !s a b.
        FINITE s /\
        f permutes s /\
        a IN s /\
        b IN s /\
        ~(a = b) /\
        permutation_orbit f a = permutation_orbit f b
        ==> ~(permutation_orbit (swap(a,b) o f) a =
              permutation_orbit (swap(a,b) o f) b)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite permutation a_member b_member distinct same_old_orbit" THEN
  SUBGOAL_THEN `(b:A) IN permutation_orbit f a`
  (LABEL_TAC "b_old_orbit") THENL
   [USE_THEN "same_old_orbit" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?n. 0 < n /\ ITER n (f:A->A) a = b`
  (LABEL_TAC "positive_hit") THENL
   [USE_THEN "b_old_orbit" MP_TAC THEN
    REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
    DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "hit")) THEN
    SUBGOAL_THEN `~(n = 0)` (LABEL_TAC "nonzero") THENL
     [DISCH_THEN SUBST_ALL_TAC THEN
      USE_THEN "distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "hit" (ACCEPT_TAC o REWRITE_RULE[ITER]);
      ALL_TAC] THEN
    EXISTS_TAC `n:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPEC
   `\n:num. 0 < n /\ ITER n (f:A->A) a = b` num_WOP) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `k:num`
   (CONJUNCTS_THEN2
    (CONJUNCTS_THEN2 (LABEL_TAC "k_positive") (LABEL_TAC "k_hit"))
    (LABEL_TAC "k_least"))) THEN
  ABBREV_TAC `g:A->A = swap((a:A),(b:A)) o (f:A->A)` THEN
  ABBREV_TAC
   `t:A->bool =
      {z | ?j:num. j < k /\ z = ITER j (f:A->A) a}` THEN
  SUBGOAL_THEN `(a:A) IN t` (LABEL_TAC "a_path") THENL
   [EXPAND_TAC "t" THEN REWRITE_TAC[IN_ELIM_THM] THEN
    EXISTS_TAC `0` THEN ASM_REWRITE_TAC[ITER];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((b:A) IN t)` (LABEL_TAC "b_not_path") THENL
   [EXPAND_TAC "t" THEN REWRITE_TAC[IN_ELIM_THM] THEN
    DISCH_THEN(X_CHOOSE_THEN `j:num`
     (CONJUNCTS_THEN2 (LABEL_TAC "j_less") (LABEL_TAC "j_hit"))) THEN
    SUBGOAL_THEN `0 < j` (LABEL_TAC "j_positive") THENL
     [ASM_CASES_TAC `j = 0` THENL
       [FIRST_X_ASSUM SUBST_ALL_TAC THEN
        USE_THEN "j_hit" (fun hit_th ->
         USE_THEN "distinct" (fun distinct_th ->
          CONTR_TAC
           (MP (NOT_ELIM distinct_th)
               (SYM(REWRITE_RULE[ITER] hit_th)))));
        ASM_ARITH_TAC];
      ALL_TAC] THEN
    USE_THEN "k_least" (fun least_th ->
     USE_THEN "j_less" (fun less_th ->
      USE_THEN "j_positive" (fun positive_th ->
       USE_THEN "j_hit" (fun hit_th ->
        CONTR_TAC
         (MP (NOT_ELIM(MP (SPEC `j:num` least_th) less_th))
             (CONJ positive_th (SYM hit_th)))))));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!m:num. 0 < m /\ m < k ==> ~(ITER m (f:A->A) a = a)`
  (LABEL_TAC "no_early_return") THENL
   [X_GEN_TAC `m:num` THEN INTRO_TAC "m_positive m_less" THEN
    DISCH_THEN(LABEL_TAC "m_return") THEN
    SUBGOAL_THEN `0 < k - m /\ k - m < k`
    (CONJUNCTS_THEN2 (LABEL_TAC "remainder_positive")
      (LABEL_TAC "remainder_less")) THENL
     [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["m_positive"; "m_less"] THEN
      ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `ITER (k - m) (f:A->A) a = b`
    (LABEL_TAC "remainder_hit") THENL
     [TRANS_TAC EQ_TRANS
       `ITER (k - m) (f:A->A) (ITER m f a)` THEN
      CONJ_TAC THENL
       [USE_THEN "m_return" (fun th -> REWRITE_TAC[th]);
        REWRITE_TAC[ITER_ADD] THEN
        SUBGOAL_THEN `((k:num) - m) + m = k`
        (fun th -> REWRITE_TAC[th]) THENL
         [MATCH_MP_TAC(SPECL [`k:num`; `m:num`] SUB_ADD) THEN
          USE_THEN "m_less" MP_TAC THEN ARITH_TAC;
          USE_THEN "k_hit" ACCEPT_TAC]];
      ALL_TAC] THEN
    CONTR_TAC
     (MP
      (NOT_ELIM
       (MP
        (SPEC `(k:num) - m`
         (ASSUME
          `!j:num.
               j < k ==> ~(0 < j /\ ITER j (f:A->A) a = b)`))
        (ASSUME `(k:num) - m < k`)))
      (CONJ
       (ASSUME `0 < (k:num) - m`)
       (ASSUME `ITER ((k:num) - m) (f:A->A) a = b`)));
    ALL_TAC] THEN
  SUBGOAL_THEN `!z:A. z IN t ==> (g:A->A) z IN t`
  (LABEL_TAC "path_invariant") THENL
   [X_GEN_TAC `z:A` THEN EXPAND_TAC "t" THEN
    REWRITE_TAC[IN_ELIM_THM] THEN
    DISCH_THEN(X_CHOOSE_THEN `j:num`
     (CONJUNCTS_THEN2 (LABEL_TAC "j_less") (LABEL_TAC "z_path"))) THEN
    USE_THEN "z_path" SUBST1_TAC THEN
    EXPAND_TAC "g" THEN REWRITE_TAC[o_THM; GSYM ITER] THEN
    ASM_CASES_TAC `SUC j = k` THENL
     [EXISTS_TAC `0` THEN ASM_REWRITE_TAC[ITER; SWAP_RIGHT] THEN
      REWRITE_TAC[GSYM ITER] THEN ASM_REWRITE_TAC[SWAP_RIGHT];
      ALL_TAC] THEN
    SUBGOAL_THEN `SUC j < k` (LABEL_TAC "next_less") THENL
     [MP_TAC(ASSUME `(j:num) < k`) THEN
      MP_TAC(ASSUME `~(SUC(j:num) = k)`) THEN
      ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~(ITER (SUC j) (f:A->A) a = a)`
    (LABEL_TAC "next_not_a") THENL
     [USE_THEN "no_early_return" (fun no_return_th ->
       USE_THEN "next_less" (fun less_th ->
        ACCEPT_TAC
         (MP (SPEC `SUC j` no_return_th)
             (CONJ (ARITH_RULE `0 < SUC(j:num)`) less_th))));
      ALL_TAC] THEN
    SUBGOAL_THEN `~(ITER (SUC j) (f:A->A) a = b)`
    (LABEL_TAC "next_not_b") THENL
     [USE_THEN "k_least" (fun least_th ->
       USE_THEN "next_less" (fun less_th ->
        LABEL_TAC "not_both" (MP (SPEC `SUC j` least_th) less_th))) THEN
      DISCH_THEN(LABEL_TAC "next_hit") THEN
      USE_THEN "not_both" (fun not_th ->
       USE_THEN "next_hit" (fun hit_th ->
        CONTR_TAC
         (MP (NOT_ELIM not_th)
             (CONJ (ARITH_RULE `0 < SUC(j:num)`) hit_th))));
      ALL_TAC] THEN
    EXISTS_TAC `SUC j` THEN CONJ_TAC THENL
     [USE_THEN "next_less" ACCEPT_TAC;
      MATCH_MP_TAC SWAP_OTHER THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `!n:num. ITER n (g:A->A) a IN t`
  (LABEL_TAC "iterates_in_path") THENL
   [INDUCT_TAC THENL
     [REWRITE_TAC[ITER] THEN USE_THEN "a_path" ACCEPT_TAC;
      REWRITE_TAC[ITER] THEN
      USE_THEN "path_invariant" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((b:A) IN permutation_orbit g a)`
  (LABEL_TAC "b_not_new_orbit") THENL
   [REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
    DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "b_hit")) THEN
    USE_THEN "b_not_path" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "b_hit" (SUBST1_TAC o SYM) THEN
    USE_THEN "iterates_in_path" (ACCEPT_TAC o SPEC `n:num`);
    ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "same_new_orbit") THEN
  USE_THEN "b_not_new_orbit" (MATCH_MP_TAC o NOT_ELIM) THEN
  USE_THEN "same_new_orbit" (fun th -> REWRITE_TAC[th]) THEN
  MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL);;

let PERMUTATION_ORBITS_SWAP_SAME = prove
 (`!f:A->A. !s a b.
        FINITE s /\
        f permutes s /\
        a IN s /\
        b IN s /\
        ~(a = b) /\
        permutation_orbit f a = permutation_orbit f b
        ==> CARD
             (permutation_orbits (swap(a,b) o f) s) =
            CARD(permutation_orbits f s) + 1`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite permutation a_member b_member distinct same_old_orbit" THEN
  SUBGOAL_THEN `(swap((a:A),(b:A)) o (f:A->A)) permutes s`
  (LABEL_TAC "new_permutation") THENL
   [MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(permutation_orbit (swap((a:A),(b:A)) o f) a =
      permutation_orbit (swap(a,b) o f) b)`
  (LABEL_TAC "split") THENL
   [MATCH_MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `b:A`]
     PERMUTATION_SWAP_SPLITS_SAME_ORBIT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`swap((a:A),(b:A)) o (f:A->A)`; `s:A->bool`; `a:A`; `b:A`]
   PERMUTATION_ORBITS_SWAP_DISTINCT) THEN
  ASM_REWRITE_TAC[o_ASSOC; SWAP_IDEMPOTENT; I_O_ID]);;

(* ------------------------------------------------------------------------- *)
(* Inserting a fresh element into one orbit of a finite permutation.         *)
(* ------------------------------------------------------------------------- *)

let ITER_AGREES_ON = prove
 (`!f g:A->A. !s x.
        x IN s /\
        (!y. y IN s ==> f y IN s /\ g y = f y)
        ==> !n. ITER n g x = ITER n f x /\ ITER n f x IN s`,
  REPEAT GEN_TAC THEN INTRO_TAC "member agrees" THEN
  INDUCT_TAC THENL
   [ASM_REWRITE_TAC[ITER];
    FIRST_X_ASSUM
     (CONJUNCTS_THEN2 (LABEL_TAC "same")
      (LABEL_TAC "iter_member")) THEN
    REWRITE_TAC[ITER] THEN
    USE_THEN "same" SUBST1_TAC THEN
    USE_THEN "agrees"
     (MP_TAC o SPEC `ITER n (f:A->A) x`) THEN
    ANTS_TAC THENL
     [USE_THEN "iter_member" ACCEPT_TAC;
      INTRO_TAC "next_member same_step" THEN
      ASM_REWRITE_TAC[]]]);;

let PERMUTATION_ORBIT_FIXED = prove
 (`!f:A->A. !x.
        f x = x
        ==> permutation_orbit f x = {x}`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "fixed") THEN
  REWRITE_TAC[EXTENSION; IN_PERMUTATION_ORBIT; IN_SING] THEN
  X_GEN_TAC `y:A` THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `n:num` (SUBST1_TAC o SYM)) THEN
    MATCH_MP_TAC ITER_FIXPOINT THEN
    USE_THEN "fixed" ACCEPT_TAC;
    DISCH_THEN SUBST1_TAC THEN
    EXISTS_TAC `0` THEN REWRITE_TAC[ITER]]);;

let PERMUTATION_ORBITS_INSERT_FIXED = prove
 (`!f:A->A. !s x.
        f x = x
        ==> permutation_orbits f (x INSERT s) =
            {x} INSERT permutation_orbits f s`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "fixed") THEN
  REWRITE_TAC[permutation_orbits; IMAGE_CLAUSES] THEN
  USE_THEN "fixed" (fun fixed_th ->
    REWRITE_TAC[MATCH_MP
      (ISPECL [`f:A->A`; `x:A`] PERMUTATION_ORBIT_FIXED)
      fixed_th]));;

let CARD_PERMUTATION_ORBITS_INSERT_FIXED = prove
 (`!f:A->A. !s x.
        FINITE s /\
        f permutes s /\
        ~(x IN s)
        ==> CARD(permutation_orbits f (x INSERT s)) =
            CARD(permutation_orbits f s) + 1`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutation fresh" THEN
  SUBGOAL_THEN `(f:A->A) x = x` (LABEL_TAC "fixed") THENL
   [USE_THEN "permutation"
     (MATCH_MP_TAC o CONJUNCT1 o REWRITE_RULE[permutes]) THEN
    USE_THEN "fresh" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(({x}:A->bool) IN permutation_orbits (f:A->A) s)`
  (LABEL_TAC "new_orbit") THENL
   [REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A`
     (CONJUNCTS_THEN2 (LABEL_TAC "y_member")
      (LABEL_TAC "orbit"))) THEN
    SUBGOAL_THEN `permutation_orbit (f:A->A) y SUBSET s`
    (LABEL_TAC "orbit_subset") THENL
     [MATCH_MP_TAC PERMUTATION_ORBIT_SUBSET THEN
      ASM_REWRITE_TAC[];
      USE_THEN "fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "orbit_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "orbit" (fun th -> REWRITE_TAC[GSYM th; IN_SING])];
    ALL_TAC] THEN
  USE_THEN "fixed" (fun fixed_th ->
    REWRITE_TAC[MATCH_MP
      (ISPECL [`f:A->A`; `s:A->bool`; `x:A`]
       PERMUTATION_ORBITS_INSERT_FIXED)
      fixed_th]) THEN
  ASM_SIMP_TAC[CARD_CLAUSES; FINITE_PERMUTATION_ORBITS] THEN
  ARITH_TAC);;

let permutation_insert = new_definition
 `permutation_insert (f:A->A) x a = swap(x,f a) o f`;;

let PERMUTATION_INSERT_PERMUTES = prove
 (`!f:A->A. !s x a.
        f permutes s /\
        a IN s /\
        ~(x IN s)
        ==> permutation_insert f x a permutes (x INSERT s)`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation anchor fresh" THEN
  REWRITE_TAC[permutation_insert] THEN
  MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC PERMUTES_SUBSET THEN
    EXISTS_TAC `s:A->bool` THEN
    ASM_REWRITE_TAC[] THEN SET_TAC[];
    REWRITE_TAC[IN_INSERT];
    REWRITE_TAC[IN_INSERT] THEN DISJ2_TAC THEN
    MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`]
      PERMUTES_IN_IMAGE) THEN
    ASM_REWRITE_TAC[]]);;

let PERMUTATION_INSERT_ORBIT_COUNT = prove
 (`!f:A->A. !s x a.
        FINITE s /\
        f permutes s /\
        a IN s /\
        ~(x IN s)
        ==> CARD
             (permutation_orbits
               (permutation_insert f x a) (x INSERT s)) =
            CARD(permutation_orbits f s)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite permutation anchor fresh" THEN
  SUBGOAL_THEN `(f:A->A) x = x` (LABEL_TAC "fixed") THENL
   [USE_THEN "permutation"
     (MATCH_MP_TAC o CONJUNCT1 o REWRITE_RULE[permutes]) THEN
    USE_THEN "fresh" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(f:A->A) permutes (x INSERT s)`
  (LABEL_TAC "extended_permutation") THENL
   [MATCH_MP_TAC PERMUTES_SUBSET THEN
    EXISTS_TAC `s:A->bool` THEN ASM_REWRITE_TAC[] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(f:A->A) a IN s`
  (LABEL_TAC "image_anchor") THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`]
      PERMUTES_IN_IMAGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(permutation_orbit (f:A->A) x =
      permutation_orbit f (f a))`
  (LABEL_TAC "distinct_orbits") THENL
   [USE_THEN "fixed" (fun fixed_th ->
      REWRITE_TAC[MATCH_MP
       (ISPECL [`f:A->A`; `x:A`] PERMUTATION_ORBIT_FIXED)
       fixed_th]) THEN
    DISCH_THEN(LABEL_TAC "same_orbit") THEN
    SUBGOAL_THEN
     `(x:A) IN permutation_orbit (f:A->A) (f a)`
    (LABEL_TAC "x_orbit") THENL
     [USE_THEN "same_orbit" (fun th -> REWRITE_TAC[GSYM th; IN_SING]);
      ALL_TAC] THEN
    SUBGOAL_THEN `permutation_orbit (f:A->A) (f a) SUBSET s`
    (LABEL_TAC "orbit_subset") THENL
     [MATCH_MP_TAC PERMUTATION_ORBIT_SUBSET THEN
      ASM_REWRITE_TAC[];
      USE_THEN "fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "orbit_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "x_orbit" ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`f:A->A`; `x INSERT s:A->bool`; `x:A`; `(f:A->A) a`]
   PERMUTATION_ORBITS_SWAP_DISTINCT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[FINITE_INSERT; IN_INSERT];
    REWRITE_TAC[GSYM permutation_insert] THEN
    DISCH_THEN(LABEL_TAC "merge_count") THEN
    MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`]
      CARD_PERMUTATION_ORBITS_INSERT_FIXED) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]);;

let FINITE_PERMUTATION_ONE_ORBIT_TRANSITIVE = prove
 (`!f:A->A. !s.
        FINITE s /\
        f permutes s /\
        CARD(permutation_orbits f s) = 1
        ==> !y z. y IN s /\ z IN s ==> ?n. ITER n f y = z`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutation one_orbit_count" THEN
  MAP_EVERY X_GEN_TAC [`y:A`; `z:A`] THEN
  INTRO_TAC "y_member z_member" THEN
  SUBGOAL_THEN
   `(permutation_orbits (f:A->A) s) HAS_SIZE 1`
  (LABEL_TAC "one_orbit") THENL
   [REWRITE_TAC[HAS_SIZE] THEN CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_PERMUTATION_ORBITS THEN
      USE_THEN "finite" ACCEPT_TAC;
      USE_THEN "one_orbit_count" ACCEPT_TAC];
    ALL_TAC] THEN
  USE_THEN "one_orbit" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE_CONV
   `(permutation_orbits (f:A->A) s) HAS_SIZE 1`] THEN
  INTRO_TAC "@c. all_orbits" THEN
  SUBGOAL_THEN
   `permutation_orbit (f:A->A) y = c /\
    permutation_orbit f z = c`
  (CONJUNCTS_THEN2 (LABEL_TAC "y_orbit")
    (LABEL_TAC "z_orbit")) THENL
   [CONJ_TAC THENL
     [SUBGOAL_THEN
       `permutation_orbit (f:A->A) y IN permutation_orbits f s`
      (LABEL_TAC "y_in") THENL
       [REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
        EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[];
        USE_THEN "y_in" MP_TAC THEN
        USE_THEN "all_orbits" (fun th -> REWRITE_TAC[th; IN_SING])];
      SUBGOAL_THEN
       `permutation_orbit (f:A->A) z IN permutation_orbits f s`
      (LABEL_TAC "z_in") THENL
       [REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
        EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
        USE_THEN "z_in" MP_TAC THEN
        USE_THEN "all_orbits" (fun th -> REWRITE_TAC[th; IN_SING])]];
    ALL_TAC] THEN
  REWRITE_TAC[GSYM IN_PERMUTATION_ORBIT] THEN
  MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `y:A`; `z:A`]
    PERMUTATION_ORBIT_EQ) THEN
  ASM_REWRITE_TAC[]);;

let PERMUTATION_INSERT_TRANSITIVE = prove
 (`!f:A->A. !s x a.
        FINITE s /\
        f permutes s /\
        a IN s /\
        ~(x IN s) /\
        (!y z. y IN s /\ z IN s ==> ?n. ITER n f y = z)
        ==> !y z.
              y IN x INSERT s /\ z IN x INSERT s
              ==> ?n. ITER n (permutation_insert f x a) y = z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite permutation anchor fresh transitive" THEN
  MATCH_MP_TAC FINITE_PERMUTATION_ONE_ORBIT_TRANSITIVE THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[FINITE_INSERT];
    MATCH_MP_TAC PERMUTATION_INSERT_PERMUTES THEN
    ASM_REWRITE_TAC[];
    TRANS_TAC EQ_TRANS
     `CARD(permutation_orbits (f:A->A) s)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC PERMUTATION_INSERT_ORBIT_COUNT THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN
       `permutation_orbits (f:A->A) s =
        {permutation_orbit f a}`
      SUBST1_TAC THENL
       [MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
         [REWRITE_TAC[SUBSET; IN_PERMUTATION_ORBITS; IN_SING] THEN
          X_GEN_TAC `c:A->bool` THEN
          INTRO_TAC "@y. y_member orbit" THEN
          USE_THEN "orbit" SUBST1_TAC THEN
          MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `y:A`]
            PERMUTATION_ORBIT_EQ) THEN
          ASM_REWRITE_TAC[] THEN
          DISCH_THEN(fun th ->
            MATCH_MP_TAC (snd(EQ_IMP_RULE th))) THEN
          REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
          USE_THEN "transitive"
           (MATCH_MP_TAC o SPECL [`a:A`; `y:A`]) THEN
          ASM_REWRITE_TAC[];
          REWRITE_TAC[SUBSET; IN_PERMUTATION_ORBITS; IN_SING] THEN
          X_GEN_TAC `c:A->bool` THEN DISCH_THEN SUBST1_TAC THEN
          EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[]];
        REWRITE_TAC[CARD_SING]]]]);;

let PERMUTATION_INSERT_TRANSITIVE_RESTRICTED = prove
 (`!f:A->A. !s t x a.
        FINITE s /\
        f permutes s /\
        t SUBSET s /\
        IMAGE f t = t /\
        a IN t /\
        ~(x IN s) /\
        (!y z. y IN t /\ z IN t ==> ?n. ITER n f y = z)
        ==> !y z.
              y IN x INSERT t /\ z IN x INSERT t
              ==> ?n. ITER n (permutation_insert f x a) y = z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite permutation subset invariant anchor fresh transitive" THEN
  ABBREV_TAC `p:A->A = \y. if y IN t then (f:A->A) y else y` THEN
  SUBGOAL_THEN `FINITE(t:A->bool)` (LABEL_TAC "finite_restriction") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `s:A->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:A->A) permutes t`
  (LABEL_TAC "restricted_permutation") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC(ISPECL
     [`s:A->bool`; `t:A->bool`; `f:A->A`]
     RESTRICT_PERMUTES_SUBSET) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "finite_restriction" ACCEPT_TAC;
      USE_THEN "subset" ACCEPT_TAC;
      USE_THEN "permutation" ACCEPT_TAC;
      USE_THEN "invariant" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y z:A.
        y IN t /\ z IN t
        ==> ?n. ITER n (p:A->A) y = z`
  (LABEL_TAC "restricted_transitive") THENL
   [MAP_EVERY X_GEN_TAC [`y:A`; `z:A`] THEN
    INTRO_TAC "y_member z_member" THEN
    SUBGOAL_THEN `?n. ITER n (f:A->A) y = z`
    (X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THENL
     [USE_THEN "transitive"
       (MATCH_MP_TAC o SPECL [`y:A`; `z:A`]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    EXISTS_TAC `n:num` THEN
    MP_TAC(ISPECL
     [`f:A->A`; `p:A->A`; `t:A->bool`; `y:A`] ITER_AGREES_ON) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "y_member" ACCEPT_TAC;
        X_GEN_TAC `w:A` THEN DISCH_THEN(LABEL_TAC "w_member") THEN
        CONJ_TAC THENL
         [USE_THEN "invariant"
           (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
          REWRITE_TAC[IN_IMAGE] THEN
          EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[];
          EXPAND_TAC "p" THEN ASM_REWRITE_TAC[]]];
      DISCH_THEN(MP_TAC o SPEC `n:num`) THEN
      USE_THEN "step" (fun th -> REWRITE_TAC[th]) THEN
      MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_insert (p:A->A) x a permutes (x INSERT t)`
  (LABEL_TAC "restricted_inserted_permutation") THENL
   [MATCH_MP_TAC PERMUTATION_INSERT_PERMUTES THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "fresh" MP_TAC THEN
    USE_THEN "subset" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y z:A.
        y IN x INSERT t /\ z IN x INSERT t
        ==> ?n. ITER n (permutation_insert (p:A->A) x a) y = z`
  (LABEL_TAC "restricted_inserted_transitive") THENL
   [MATCH_MP_TAC PERMUTATION_INSERT_TRANSITIVE THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "fresh" MP_TAC THEN
    USE_THEN "subset" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A.
        w IN x INSERT t
        ==> permutation_insert (p:A->A) x a w IN x INSERT t /\
            permutation_insert (f:A->A) x a w =
            permutation_insert p x a w`
  (LABEL_TAC "insertions_agree") THENL
   [X_GEN_TAC `w:A` THEN DISCH_THEN(LABEL_TAC "w_member") THEN
    CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`permutation_insert (p:A->A) x a`;
        `x INSERT t:A->bool`; `w:A`] PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(p:A->A) a = f a` (LABEL_TAC "anchor_agrees") THENL
     [EXPAND_TAC "p" THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[permutation_insert; o_THM] THEN
    USE_THEN "anchor_agrees" (fun th -> REWRITE_TAC[th]) THEN
    AP_TERM_TAC THEN
    USE_THEN "w_member"
     (DISJ_CASES_THEN2 (LABEL_TAC "new_point")
       (LABEL_TAC "old_point") o REWRITE_RULE[IN_INSERT]) THENL
     [USE_THEN "new_point" SUBST1_TAC THEN
      SUBGOAL_THEN `~((x:A) IN t)` (LABEL_TAC "fresh_restriction") THENL
       [USE_THEN "fresh" MP_TAC THEN
        USE_THEN "subset" MP_TAC THEN SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(f:A->A) x = x` (LABEL_TAC "f_fixed") THENL
       [USE_THEN "permutation"
         (MATCH_MP_TAC o CONJUNCT1 o REWRITE_RULE[permutes]) THEN
        USE_THEN "fresh" ACCEPT_TAC;
        EXPAND_TAC "p" THEN ASM_REWRITE_TAC[]];
      EXPAND_TAC "p" THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`y:A`; `z:A`] THEN
  INTRO_TAC "y_member z_member" THEN
  SUBGOAL_THEN
   `?n. ITER n (permutation_insert (p:A->A) x a) y = z`
  (X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THENL
   [USE_THEN "restricted_inserted_transitive"
     (MATCH_MP_TAC o SPECL [`y:A`; `z:A`]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `n:num` THEN
  MP_TAC(ISPECL
   [`permutation_insert (p:A->A) x a`;
    `permutation_insert (f:A->A) x a`;
    `x INSERT t:A->bool`; `y:A`] ITER_AGREES_ON) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `n:num`) THEN
  USE_THEN "step" (fun th -> REWRITE_TAC[th]) THEN
  MESON_TAC[]);;

let PERMUTATION_INSERT_ORBIT_TRANSITIVE = prove
 (`!f:A->A. !s c x a.
        FINITE s /\
        f permutes s /\
        c IN s /\
        a IN permutation_orbit f c /\
        ~(x IN s)
        ==> !y z.
              y IN x INSERT permutation_orbit f c /\
              z IN x INSERT permutation_orbit f c
              ==> ?n. ITER n (permutation_insert f x a) y = z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite permutation base anchor fresh" THEN
  MATCH_MP_TAC(ISPECL
   [`f:A->A`; `s:A->bool`; `permutation_orbit (f:A->A) c`;
    `x:A`; `a:A`]
   PERMUTATION_INSERT_TRANSITIVE_RESTRICTED) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "finite" ACCEPT_TAC;
    USE_THEN "permutation" ACCEPT_TAC;
    MATCH_MP_TAC PERMUTATION_ORBIT_SUBSET THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`f:A->A`; `s:A->bool`; `c:A`]
     PERMUTATION_ORBIT_IMAGE) THEN
    ASM_REWRITE_TAC[];
    USE_THEN "anchor" ACCEPT_TAC;
    USE_THEN "fresh" ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`y:A`; `z:A`] THEN
    INTRO_TAC "y_orbit z_orbit" THEN
    REWRITE_TAC[GSYM IN_PERMUTATION_ORBIT] THEN
    SUBGOAL_THEN
     `permutation_orbit (f:A->A) y = permutation_orbit f c`
    (LABEL_TAC "same_orbit") THENL
     [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `c:A`; `y:A`]
       PERMUTATION_ORBIT_EQ) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "same_orbit" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "z_orbit" ACCEPT_TAC]]);;

let PERMUTATION_INSERT_PRESERVES_KEY = prove
 (`!f:A->A. !s x a. !P:A->B.
        f permutes s /\
        a IN s /\
        ~(x IN s) /\
        P x = P a /\
        (!y. y IN s ==> P(f y) = P y)
        ==> !y.
              y IN x INSERT s
              ==> P(permutation_insert f x a y) = P y`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "permutation anchor fresh same_key invariant" THEN
  SUBGOAL_THEN `(f:A->A) x = x` (LABEL_TAC "fixed") THENL
   [USE_THEN "permutation"
     (MATCH_MP_TAC o CONJUNCT1 o REWRITE_RULE[permutes]) THEN
    USE_THEN "fresh" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(f:A->A) a IN s` (LABEL_TAC "image_anchor") THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`]
      PERMUTES_IN_IMAGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  X_GEN_TAC `y:A` THEN
  REWRITE_TAC[IN_INSERT] THEN
  DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "new_point")
    (LABEL_TAC "old_point")) THENL
   [USE_THEN "new_point" SUBST1_TAC THEN
    REWRITE_TAC[permutation_insert; o_THM] THEN
    ASM_REWRITE_TAC[SWAP_LEFT] THEN
    TRANS_TAC EQ_TRANS `(P:A->B) a` THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "invariant" MATCH_MP_TAC THEN
    USE_THEN "anchor" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(f:A->A) y IN s` (LABEL_TAC "image_old") THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `y:A`]
      PERMUTES_IN_IMAGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(y:A) = a` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    REWRITE_TAC[permutation_insert; o_THM; SWAP_RIGHT] THEN
    USE_THEN "same_key" ACCEPT_TAC;
    FIRST_X_ASSUM(LABEL_TAC "not_anchor")] THEN
  SUBGOAL_THEN `~((f:A->A) y = x)` (LABEL_TAC "not_new") THENL
   [DISCH_THEN(LABEL_TAC "same_new") THEN
    USE_THEN "fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "same_new" (fun th ->
      USE_THEN "image_old" (ACCEPT_TAC o REWRITE_RULE[th]));
    ALL_TAC] THEN
  SUBGOAL_THEN `~((f:A->A) y = f a)`
  (LABEL_TAC "not_anchor_image") THENL
   [DISCH_THEN(LABEL_TAC "same_image") THEN
    USE_THEN "not_anchor" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "permutation" (fun permutation_th ->
      MP_TAC(MATCH_MP
       (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
       permutation_th)) THEN
    DISCH_THEN(MP_TAC o SPECL [`y:A`; `a:A`]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[permutation_insert; o_THM] THEN
  SUBGOAL_THEN
   `swap((x:A),(f:A->A) a) (f y) = f y`
  SUBST1_TAC THENL
   [MATCH_MP_TAC SWAP_OTHER THEN ASM_REWRITE_TAC[];
    USE_THEN "invariant" MATCH_MP_TAC THEN
    USE_THEN "old_point" ACCEPT_TAC]);;

let PERMUTATION_INSERT_PRESERVES_KEY_TRANSITIVE = prove
 (`!f:A->A. !s x a. !P:A->B.
        FINITE s /\
        f permutes s /\
        a IN s /\
        ~(x IN s) /\
        P x = P a /\
        (!y. y IN s ==> P(f y) = P y) /\
        (!y z. y IN s /\ z IN s /\ P y = P z
               ==> ?n. ITER n f y = z)
        ==> permutation_insert f x a permutes (x INSERT s) /\
            (!y. y IN x INSERT s
                 ==> P(permutation_insert f x a y) = P y) /\
            (!y z. y IN x INSERT s /\ z IN x INSERT s /\
                   P y = P z
                   ==> ?n. ITER n (permutation_insert f x a) y = z)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite permutation anchor fresh same_key invariant transitive" THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC PERMUTATION_INSERT_PERMUTES THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC PERMUTATION_INSERT_PRESERVES_KEY THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`y:A`; `z:A`] THEN
  INTRO_TAC "y_member z_member equal_key" THEN
  ASM_CASES_TAC `(P:A->B) y = P a` THENL
   [FIRST_X_ASSUM(LABEL_TAC "affected_key") THEN
    SUBGOAL_THEN `(P:A->B) z = P a`
    (LABEL_TAC "z_affected_key") THENL
     [TRANS_TAC EQ_TRANS `(P:A->B) y` THEN
      CONJ_TAC THENL
       [USE_THEN "equal_key" (ACCEPT_TAC o SYM);
        USE_THEN "affected_key" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(y:A) IN x INSERT permutation_orbit (f:A->A) a /\
      (z:A) IN x INSERT permutation_orbit f a`
    (CONJUNCTS_THEN2 (LABEL_TAC "y_affected")
      (LABEL_TAC "z_affected")) THENL
     [CONJ_TAC THENL
       [REWRITE_TAC[IN_INSERT] THEN
        ASM_CASES_TAC `(y:A) = x` THENL
         [ASM_REWRITE_TAC[];
          SUBGOAL_THEN `(y:A) IN s` (LABEL_TAC "y_old") THENL
           [USE_THEN "y_member" MP_TAC THEN
            REWRITE_TAC[IN_INSERT] THEN ASM_REWRITE_TAC[];
            ALL_TAC] THEN
          DISJ2_TAC THEN REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
          USE_THEN "transitive"
           (MATCH_MP_TAC o SPECL [`a:A`; `y:A`]) THEN
          ASM_REWRITE_TAC[]];
        REWRITE_TAC[IN_INSERT] THEN
        ASM_CASES_TAC `(z:A) = x` THENL
         [ASM_REWRITE_TAC[];
          SUBGOAL_THEN `(z:A) IN s` (LABEL_TAC "z_old") THENL
           [USE_THEN "z_member" MP_TAC THEN
            REWRITE_TAC[IN_INSERT] THEN ASM_REWRITE_TAC[];
            ALL_TAC] THEN
          DISJ2_TAC THEN REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
          USE_THEN "transitive"
           (MATCH_MP_TAC o SPECL [`a:A`; `z:A`]) THEN
          ASM_REWRITE_TAC[]]];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`f:A->A`; `s:A->bool`; `a:A`; `x:A`; `a:A`]
     PERMUTATION_INSERT_ORBIT_TRANSITIVE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[PERMUTATION_ORBIT_REFL];
      DISCH_THEN(MP_TAC o SPECL [`y:A`; `z:A`]) THEN
      ASM_REWRITE_TAC[]];
    FIRST_X_ASSUM(LABEL_TAC "unaffected_key")] THEN
  SUBGOAL_THEN `(y:A) IN s /\ (z:A) IN s`
  (CONJUNCTS_THEN2 (LABEL_TAC "y_old") (LABEL_TAC "z_old")) THENL
   [USE_THEN "y_member" MP_TAC THEN
    USE_THEN "z_member" MP_TAC THEN
    REWRITE_TAC[IN_INSERT] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?n. ITER n (f:A->A) y = z`
  (X_CHOOSE_THEN `n:num` (LABEL_TAC "old_step")) THENL
   [USE_THEN "transitive"
     (MATCH_MP_TAC o SPECL [`y:A`; `z:A`]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `n:num` THEN
  MP_TAC(ISPECL
   [`f:A->A`; `permutation_insert (f:A->A) x a`;
    `{w:A | w IN s /\ (P:A->B) w = P y}`; `y:A`]
   ITER_AGREES_ON) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    X_GEN_TAC `w:A` THEN
    REWRITE_TAC[IN_ELIM_THM] THEN
    INTRO_TAC "w_member w_key" THEN
    SUBGOAL_THEN `(f:A->A) w IN s`
    (LABEL_TAC "image_member") THENL
     [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `w:A`]
       PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN
      CONJ_TAC THENL
       [USE_THEN "image_member" ACCEPT_TAC;
        TRANS_TAC EQ_TRANS `(P:A->B) w` THEN
        CONJ_TAC THENL
         [USE_THEN "invariant" MATCH_MP_TAC THEN
          USE_THEN "w_member" ACCEPT_TAC;
          USE_THEN "w_key" ACCEPT_TAC]];
      ALL_TAC] THEN
    REWRITE_TAC[permutation_insert; o_THM] THEN
    MATCH_MP_TAC SWAP_OTHER THEN
    CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "new_image") THEN
      USE_THEN "fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "new_image" (fun th ->
       USE_THEN "image_member" (ACCEPT_TAC o REWRITE_RULE[th]));
      ALL_TAC] THEN
    DISCH_THEN(LABEL_TAC "anchor_image") THEN
    SUBGOAL_THEN `(w:A) = a` (LABEL_TAC "anchor_point") THENL
     [MP_TAC(SPECL [`w:A`; `a:A`]
       (MATCH_MP
        (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
        (ASSUME `(f:A->A) permutes s`))) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "unaffected_key" (MATCH_MP_TAC o NOT_ELIM) THEN
    TRANS_TAC EQ_TRANS `(P:A->B) w` THEN
    CONJ_TAC THENL
     [USE_THEN "w_key" (ACCEPT_TAC o SYM);
      USE_THEN "anchor_point" (fun th -> REWRITE_TAC[th])];
    DISCH_THEN(MP_TAC o SPEC `n:num`) THEN
    USE_THEN "old_step" (fun th -> REWRITE_TAC[th]) THEN
    MESON_TAC[]]);;

let PERMUTES_COMMUTES_SWAP_OUTSIDE = prove
 (`!f:A->A. !s x y.
        f permutes s /\
        ~(x IN s) /\
        ~(y IN s)
        ==> f o swap(x,y) = swap(x,y) o f`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation x_out y_out" THEN
  SUBGOAL_THEN `(f:A->A) x = x /\ f y = y`
  (CONJUNCTS_THEN2 (LABEL_TAC "fix_x") (LABEL_TAC "fix_y")) THENL
   [CONJ_TAC THEN
    USE_THEN "permutation"
     (MATCH_MP_TAC o CONJUNCT1 o REWRITE_RULE[permutes]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `z:A` THEN
  ASM_CASES_TAC `(z:A) = x` THENL
   [FIRST_X_ASSUM SUBST1_TAC THEN
    ASM_REWRITE_TAC[o_THM; SWAP_LEFT; SWAP_RIGHT];
    FIRST_X_ASSUM(LABEL_TAC "z_not_x")] THEN
  ASM_CASES_TAC `(z:A) = y` THENL
   [FIRST_X_ASSUM SUBST1_TAC THEN
    ASM_REWRITE_TAC[o_THM; SWAP_LEFT; SWAP_RIGHT];
    FIRST_X_ASSUM(LABEL_TAC "z_not_y")] THEN
  SUBGOAL_THEN `~((f:A->A) z = x) /\ ~(f z = y)`
  (CONJUNCTS_THEN2 (LABEL_TAC "fz_not_x")
    (LABEL_TAC "fz_not_y")) THENL
   [CONJ_TAC THEN DISCH_THEN(LABEL_TAC "image") THENL
     [USE_THEN "z_not_x" (MATCH_MP_TAC o NOT_ELIM) THEN
      MP_TAC(SPECL [`z:A`; `x:A`]
       (MATCH_MP
        (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
        (ASSUME `(f:A->A) permutes s`))) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "z_not_y" (MATCH_MP_TAC o NOT_ELIM) THEN
      MP_TAC(SPECL [`z:A`; `y:A`]
       (MATCH_MP
        (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
        (ASSUME `(f:A->A) permutes s`))) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[o_THM] THEN
  SUBGOAL_THEN `swap((x:A),y) z = z` SUBST1_TAC THENL
   [MATCH_MP_TAC SWAP_OTHER THEN ASM_REWRITE_TAC[];
    CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC SWAP_OTHER THEN ASM_REWRITE_TAC[]]);;

let PERMUTATION_INSERT_TWO_ORBIT_COUNT = prove
 (`!f:A->A. !s x y a.
        FINITE s /\
        f permutes s /\
        a IN s /\
        ~(x IN s) /\
        ~(y IN x INSERT s)
        ==> CARD
             (permutation_orbits
               (permutation_insert
                 (permutation_insert f x a) y x)
               (y INSERT x INSERT s)) =
            CARD(permutation_orbits f s)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite permutation anchor x_fresh y_fresh" THEN
  TRANS_TAC EQ_TRANS
   `CARD
     (permutation_orbits
       (permutation_insert (f:A->A) x a)
       (x INSERT s))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC PERMUTATION_INSERT_ORBIT_COUNT THEN
    ASM_REWRITE_TAC[FINITE_INSERT; IN_INSERT] THEN
    MATCH_MP_TAC PERMUTATION_INSERT_PERMUTES THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC PERMUTATION_INSERT_ORBIT_COUNT THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Existence of rotations on finite graphs.                                  *)
(* ------------------------------------------------------------------------- *)

let FINITE_CYCLIC_PERMUTATION = prove
 (`!s:A->bool.
        FINITE s
        ==> ?f:A->A.
              f permutes s /\
              !x y. x IN s /\ y IN s
                    ==> ?n. ITER n f x = y`,
  X_GEN_TAC `s:A->bool` THEN DISCH_THEN(LABEL_TAC "finite") THEN
  ASM_CASES_TAC `s:A->bool = {}` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    EXISTS_TAC `I:A->A` THEN
    REWRITE_TAC[PERMUTES_I; NOT_IN_EMPTY];
    FIRST_X_ASSUM(LABEL_TAC "nonempty")] THEN
  SUBGOAL_THEN `?a:A. a IN s`
  (X_CHOOSE_THEN `a:A` (LABEL_TAC "member")) THENL
   [USE_THEN "nonempty" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?n. ?f:A->A.
          f permutes s /\
          CARD(permutation_orbits f s) = n`
  (fun existence_th ->
    MP_TAC
     (MATCH_MP
      (fst
       (EQ_IMP_RULE
        (CONV_RULE
         (ONCE_DEPTH_CONV BETA_CONV)
         (SPEC
          `\n. ?f:A->A.
                 f permutes s /\
                 CARD(permutation_orbits f s) = n`
          num_WOP))))
      existence_th)) THENL
   [EXISTS_TAC `CARD(permutation_orbits (I:A->A) s)` THEN
    EXISTS_TAC `I:A->A` THEN
    REWRITE_TAC[PERMUTES_I];
    DISCH_THEN(X_CHOOSE_THEN `n:num`
     (CONJUNCTS_THEN2
      (X_CHOOSE_THEN `f:A->A`
       (CONJUNCTS_THEN2 (LABEL_TAC "permutation")
        (LABEL_TAC "count")))
      (LABEL_TAC "minimal")))] THEN
  SUBGOAL_THEN `~(n = 0)` (LABEL_TAC "positive") THENL
   [DISCH_THEN(LABEL_TAC "zero") THEN
    SUBGOAL_THEN
     `permutation_orbits (f:A->A) s = {}`
    (LABEL_TAC "no_orbits") THENL
     [MP_TAC(ISPEC `permutation_orbits (f:A->A) s` CARD_EQ_0) THEN
      ASM_SIMP_TAC[FINITE_PERMUTATION_ORBITS];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `permutation_orbit (f:A->A) a IN
      permutation_orbits f s`
    (LABEL_TAC "has_orbit") THENL
     [REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
      EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[];
      USE_THEN "has_orbit" MP_TAC THEN
      USE_THEN "no_orbits" (fun th -> REWRITE_TAC[th; NOT_IN_EMPTY])];
    ALL_TAC] THEN
  SUBGOAL_THEN `n = 1` (LABEL_TAC "one_orbit_count") THENL
   [MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "not_one") THEN
    SUBGOAL_THEN `1 < n` (LABEL_TAC "at_least_two") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `?b:A.
          b IN s /\
          ~(permutation_orbit (f:A->A) a =
            permutation_orbit f b)`
    (X_CHOOSE_THEN `b:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "b_member")
        (LABEL_TAC "different_orbits"))) THENL
     [MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
      DISCH_THEN(LABEL_TAC "no_second_orbit") THEN
      SUBGOAL_THEN
       `!x:A.
          x IN s
          ==> permutation_orbit (f:A->A) a =
              permutation_orbit f x`
      (LABEL_TAC "all_same") THENL
       [X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "x_member") THEN
        MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
        DISCH_THEN(LABEL_TAC "different") THEN
        USE_THEN "no_second_orbit" (MATCH_MP_TAC o NOT_ELIM) THEN
        EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `permutation_orbits (f:A->A) s =
        {permutation_orbit f a}`
      (LABEL_TAC "singleton_orbits") THENL
       [REWRITE_TAC[EXTENSION; IN_PERMUTATION_ORBITS; IN_SING] THEN
        X_GEN_TAC `c:A->bool` THEN EQ_TAC THENL
         [DISCH_THEN(X_CHOOSE_THEN `x:A`
           (CONJUNCTS_THEN2 (LABEL_TAC "x_member")
            (LABEL_TAC "representation"))) THEN
          SUBGOAL_THEN
           `permutation_orbit (f:A->A) a =
            permutation_orbit f x`
          (LABEL_TAC "same_orbit") THENL
           [USE_THEN "all_same" MATCH_MP_TAC THEN
            USE_THEN "x_member" ACCEPT_TAC;
            USE_THEN "same_orbit" (fun th -> REWRITE_TAC[th]) THEN
            USE_THEN "representation" ACCEPT_TAC];
          DISCH_THEN(LABEL_TAC "representation") THEN
          EXISTS_TAC `a:A` THEN
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      USE_THEN "count" MP_TAC THEN
      USE_THEN "singleton_orbits"
       (fun th -> REWRITE_TAC[th; CARD_SING]) THEN
      ASM_ARITH_TAC;
      ALL_TAC] THEN
    ABBREV_TAC `g:A->A = swap(a,b) o (f:A->A)` THEN
    SUBGOAL_THEN `(g:A->A) permutes s`
    (LABEL_TAC "new_permutation") THENL
     [EXPAND_TAC "g" THEN
      MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD(permutation_orbits (f:A->A) s) =
      CARD(permutation_orbits (g:A->A) s) + 1`
    (LABEL_TAC "merged") THENL
     [EXPAND_TAC "g" THEN
      MATCH_MP_TAC(ISPECL
       [`f:A->A`; `s:A->bool`; `a:A`; `b:A`]
       PERMUTATION_ORBITS_SWAP_DISTINCT) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD(permutation_orbits (g:A->A) s) < n`
    (LABEL_TAC "smaller") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~(?h:A->A.
           h permutes s /\
           CARD(permutation_orbits h s) =
           CARD(permutation_orbits (g:A->A) s))`
    (LABEL_TAC "minimality") THENL
     [USE_THEN "minimal" MATCH_MP_TAC THEN
      USE_THEN "smaller" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "minimality" (MATCH_MP_TAC o NOT_ELIM) THEN
    EXISTS_TAC `g:A->A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `f:A->A` THEN
  CONJ_TAC THENL
   [USE_THEN "permutation" ACCEPT_TAC;
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
  INTRO_TAC "x_member y_member" THEN
  SUBGOAL_THEN
   `(permutation_orbits (f:A->A) s) HAS_SIZE 1`
  (LABEL_TAC "one_orbit") THENL
   [REWRITE_TAC[HAS_SIZE] THEN CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_PERMUTATION_ORBITS THEN
      USE_THEN "finite" ACCEPT_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  USE_THEN "one_orbit" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE_CONV
   `(permutation_orbits (f:A->A) s) HAS_SIZE 1`] THEN
  INTRO_TAC "@c. all_orbits" THEN
  SUBGOAL_THEN
   `permutation_orbit (f:A->A) x = c /\
    permutation_orbit f y = c`
  (CONJUNCTS_THEN2 (LABEL_TAC "x_orbit")
    (LABEL_TAC "y_orbit")) THENL
   [CONJ_TAC THENL
     [SUBGOAL_THEN
       `permutation_orbit (f:A->A) x IN
        permutation_orbits f s`
      (LABEL_TAC "x_in") THENL
       [REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
        EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[];
        USE_THEN "x_in" MP_TAC THEN
        USE_THEN "all_orbits"
         (fun th -> REWRITE_TAC[th; IN_SING])];
      SUBGOAL_THEN
       `permutation_orbit (f:A->A) y IN
        permutation_orbits f s`
      (LABEL_TAC "y_in") THENL
       [REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
        EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[];
        USE_THEN "y_in" MP_TAC THEN
        USE_THEN "all_orbits"
         (fun th -> REWRITE_TAC[th; IN_SING])]];
    ALL_TAC] THEN
  REWRITE_TAC[GSYM IN_PERMUTATION_ORBIT] THEN
  MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`; `y:A`]
    PERMUTATION_ORBIT_EQ) THEN
  ASM_REWRITE_TAC[]);;

let FINITE_SIMPLE_GRAPH_HAS_ROTATION = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> ?r:(A#A)->A#A. graph_rotation E r`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  SUBGOAL_THEN
   `!u:A.
        ?p:(A#A)->A#A.
          p permutes outgoing_darts E u /\
          !x y. x IN outgoing_darts E u /\
                y IN outgoing_darts E u
                ==> ?n. ITER n p x = y`
  MP_TAC THENL
   [X_GEN_TAC `u:A` THEN
    MATCH_MP_TAC FINITE_CYCLIC_PERMUTATION THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
     FINITE_OUTGOING_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    REWRITE_TAC[SKOLEM_THM] THEN
    DISCH_THEN(X_CHOOSE_THEN `p:A->(A#A)->A#A`
     (LABEL_TAC "local"))] THEN
  ABBREV_TAC
   `r:(A#A)->A#A = \d. (p:A->(A#A)->A#A) (FST d) d` THEN
  EXISTS_TAC `r:(A#A)->A#A` THEN
  REWRITE_TAC[graph_rotation] THEN REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL
     [`graph_darts (E:(A->bool)->bool)`; `r:(A#A)->A#A`]
      PERMUTES_FINITE_INJECTIVE) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      USE_THEN "graph" ACCEPT_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    REPEAT CONJ_TAC THENL
     [X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "not_dart") THEN
      EXPAND_TAC "r" THEN REWRITE_TAC[] THEN
      USE_THEN "local" (MP_TAC o SPEC `FST(d:A#A)`) THEN
      INTRO_TAC "permutation transitive" THEN
      USE_THEN "permutation"
       (MATCH_MP_TAC o CONJUNCT1 o REWRITE_RULE[permutes]) THEN
      USE_THEN "not_dart" MP_TAC THEN
      REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[];
      X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "dart") THEN
      SUBGOAL_THEN `(d:A#A) IN outgoing_darts E (FST d)`
      (LABEL_TAC "outgoing") THENL
       [ASM_REWRITE_TAC[IN_OUTGOING_DARTS];
        ALL_TAC] THEN
      USE_THEN "local" (MP_TAC o SPEC `FST(d:A#A)`) THEN
      INTRO_TAC "permutation transitive" THEN
      MP_TAC(ISPECL
       [`p (FST(d:A#A)):(A#A)->A#A`;
        `outgoing_darts E (FST(d:A#A))`; `d:A#A`]
       PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[] THEN
      EXPAND_TAC "r" THEN REWRITE_TAC[IN_OUTGOING_DARTS] THEN
      MESON_TAC[];
      MAP_EVERY X_GEN_TAC [`d:A#A`; `d':A#A`] THEN
      INTRO_TAC "dart dart' same_image" THEN
      SUBGOAL_THEN
       `(d:A#A) IN outgoing_darts E (FST d) /\
        (d':A#A) IN outgoing_darts E (FST d')`
      (CONJUNCTS_THEN2 (LABEL_TAC "outgoing")
        (LABEL_TAC "outgoing'")) THENL
       [ASM_REWRITE_TAC[IN_OUTGOING_DARTS];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(p:A->(A#A)->A#A) (FST d) d IN
        outgoing_darts E (FST d) /\
        p (FST d') d' IN outgoing_darts E (FST d')`
      (CONJUNCTS_THEN2 (LABEL_TAC "image")
        (LABEL_TAC "image'")) THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL
           [`p (FST(d:A#A)):(A#A)->A#A`;
            `outgoing_darts E (FST(d:A#A))`; `d:A#A`]
           PERMUTES_IN_IMAGE) THEN
          USE_THEN "local" (MP_TAC o SPEC `FST(d:A#A)`) THEN
          ASM_MESON_TAC[];
          MP_TAC(ISPECL
           [`p (FST(d':A#A)):(A#A)->A#A`;
            `outgoing_darts E (FST(d':A#A))`; `d':A#A`]
           PERMUTES_IN_IMAGE) THEN
          USE_THEN "local" (MP_TAC o SPEC `FST(d':A#A)`) THEN
          ASM_MESON_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN `FST(d:A#A) = FST(d':A#A)`
      (LABEL_TAC "same_tail") THENL
       [USE_THEN "same_image" MP_TAC THEN
        EXPAND_TAC "r" THEN
        USE_THEN "image" MP_TAC THEN USE_THEN "image'" MP_TAC THEN
        REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[];
        ALL_TAC] THEN
      USE_THEN "local" (MP_TAC o SPEC `FST(d':A#A)`) THEN
      INTRO_TAC "permutation transitive" THEN
      SUBGOAL_THEN
       `(p:A->(A#A)->A#A) (FST d') d =
        p (FST d') d'`
      (LABEL_TAC "same_local_image") THENL
       [USE_THEN "same_image" MP_TAC THEN
        EXPAND_TAC "r" THEN
        USE_THEN "same_tail" (fun th -> REWRITE_TAC[th]);
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`p (FST(d':A#A)):(A#A)->A#A`;
        `outgoing_darts E (FST(d':A#A))`]
       PERMUTES_INJECTIVE) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o SPECL [`d:A#A`; `d':A#A`]) THEN
      ASM_REWRITE_TAC[]];
    X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "dart") THEN
    SUBGOAL_THEN `(d:A#A) IN outgoing_darts E (FST d)`
    (LABEL_TAC "outgoing") THENL
     [ASM_REWRITE_TAC[IN_OUTGOING_DARTS];
      ALL_TAC] THEN
    USE_THEN "local" (MP_TAC o SPEC `FST(d:A#A)`) THEN
    INTRO_TAC "permutation transitive" THEN
    MP_TAC(ISPECL
     [`p (FST(d:A#A)):(A#A)->A#A`;
      `outgoing_darts E (FST(d:A#A))`; `d:A#A`]
     PERMUTES_IN_IMAGE) THEN
    ASM_REWRITE_TAC[] THEN
    EXPAND_TAC "r" THEN REWRITE_TAC[IN_OUTGOING_DARTS] THEN
    MESON_TAC[];
    MAP_EVERY X_GEN_TAC [`d:A#A`; `d':A#A`] THEN
    INTRO_TAC "dart dart' same_tail" THEN
    SUBGOAL_THEN
     `(d:A#A) IN outgoing_darts E (FST d) /\
      (d':A#A) IN outgoing_darts E (FST d)`
    (CONJUNCTS_THEN2 (LABEL_TAC "outgoing")
      (LABEL_TAC "outgoing'")) THENL
     [ASM_REWRITE_TAC[IN_OUTGOING_DARTS];
      ALL_TAC] THEN
    USE_THEN "local" (MP_TAC o SPEC `FST(d:A#A)`) THEN
    INTRO_TAC "permutation transitive" THEN
    USE_THEN "transitive" (MP_TAC o SPECL [`d:A#A`; `d':A#A`]) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "outgoing" ACCEPT_TAC;
        USE_THEN "outgoing'" ACCEPT_TAC];
      DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "local_step"))] THEN
    EXISTS_TAC `n:num` THEN
    MP_TAC(ISPECL
     [`p (FST(d:A#A)):(A#A)->A#A`; `r:(A#A)->A#A`;
      `outgoing_darts E (FST(d:A#A))`; `d:A#A`]
     ITER_AGREES_ON) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "outgoing" ACCEPT_TAC;
        X_GEN_TAC `z:A#A` THEN DISCH_THEN(LABEL_TAC "z_outgoing") THEN
        CONJ_TAC THENL
         [MP_TAC(ISPECL
           [`p (FST(d:A#A)):(A#A)->A#A`;
            `outgoing_darts E (FST(d:A#A))`; `z:A#A`]
           PERMUTES_IN_IMAGE) THEN
          ASM_REWRITE_TAC[];
          EXPAND_TAC "r" THEN
          USE_THEN "z_outgoing" MP_TAC THEN
          REWRITE_TAC[IN_OUTGOING_DARTS] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[th])]];
      DISCH_THEN(MP_TAC o SPEC `n:num`) THEN
      INTRO_TAC "same_iteration iter_member" THEN
      USE_THEN "same_iteration" (fun same_th ->
       USE_THEN "local_step" (fun step_th ->
        ACCEPT_TAC(TRANS same_th step_th)))]]);;

(* ------------------------------------------------------------------------- *)
(* Ordered spanning trees of finite connected simple graphs.                 *)
(*                                                                           *)
(* The reverse list order records a rooted tree construction: each head      *)
(* introduces one new vertex and joins it to a vertex already represented by *)
(* the tail.                                                                 *)
(* ------------------------------------------------------------------------- *)

let rooted_edge_vertices = new_recursive_definition list_RECURSION
 `(rooted_edge_vertices (u:A) [] = {u}) /\
  (rooted_edge_vertices u (CONS (d:A#A) es) =
        FST d INSERT rooted_edge_vertices u es)`;;

let rooted_edge_list = new_recursive_definition list_RECURSION
 `(rooted_edge_list (E:(A->bool)->bool) u [] <=> T) /\
  (rooted_edge_list E u (CONS (d:A#A) es) <=>
        rooted_edge_list E u es /\
        ~(FST d IN rooted_edge_vertices u es) /\
        SND d IN rooted_edge_vertices u es /\
        {FST d,SND d} IN E)`;;

let rooted_edge_set = new_recursive_definition list_RECURSION
 `(rooted_edge_set ([]:(A#A)list) = {}) /\
  (rooted_edge_set (CONS (d:A#A) es) =
        {FST d,SND d} INSERT rooted_edge_set es)`;;

let ROOT_IN_ROOTED_EDGE_VERTICES = prove
 (`!u:A. !es. u IN rooted_edge_vertices u es`,
  GEN_TAC THEN LIST_INDUCT_TAC THEN
  ASM_REWRITE_TAC[rooted_edge_vertices; IN_INSERT]);;

let FINITE_ROOTED_EDGE_VERTICES = prove
 (`!u:A. !es. FINITE(rooted_edge_vertices u es)`,
  GEN_TAC THEN LIST_INDUCT_TAC THEN
  ASM_REWRITE_TAC[rooted_edge_vertices; FINITE_INSERT; FINITE_SING]);;

let FINITE_ROOTED_EDGE_SET = prove
 (`!es:(A#A)list. FINITE(rooted_edge_set es)`,
  LIST_INDUCT_TAC THEN
  ASM_REWRITE_TAC[rooted_edge_set; FINITE_EMPTY; FINITE_INSERT]);;

let ROOTED_EDGE_LIST_TAIL = prove
 (`!E u d:A#A. !es.
        rooted_edge_list E u (CONS d es)
        ==> rooted_edge_list E u es`,
  REWRITE_TAC[rooted_edge_list] THEN MESON_TAC[]);;

let ROOTED_EDGE_LIST_VERTICES_SUBSET = prove
 (`!V E u:A. !es.
        finite_simple_graph V E /\
        u IN V /\
        rooted_edge_list E u es
        ==> rooted_edge_vertices u es SUBSET V`,
  REPEAT GEN_TAC THEN
  SPEC_TAC(`es:(A#A)list`,`es:(A#A)list`) THEN
  LIST_INDUCT_TAC THENL
   [REWRITE_TAC[rooted_edge_vertices; SING_SUBSET] THEN MESON_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "induction") THEN
    MP_TAC(ISPEC `h:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    REWRITE_TAC[rooted_edge_list; rooted_edge_vertices] THEN
    INTRO_TAC "graph root tail new old edge" THEN
    REWRITE_TAC[INSERT_SUBSET] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `x:A`; `y:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
      USE_THEN "induction" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]]]);;

let ROOTED_EDGE_LIST_CARD_VERTICES = prove
 (`!E u:A. !es.
        rooted_edge_list E u es
        ==> CARD(rooted_edge_vertices u es) = LENGTH es + 1`,
  REPEAT GEN_TAC THEN
  SPEC_TAC(`es:(A#A)list`,`es:(A#A)list`) THEN
  LIST_INDUCT_TAC THENL
   [REWRITE_TAC[rooted_edge_list; rooted_edge_vertices;
                CARD_SING; LENGTH] THEN ARITH_TAC;
    FIRST_X_ASSUM(LABEL_TAC "induction") THEN
    MP_TAC(ISPEC `h:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    REWRITE_TAC[rooted_edge_list; rooted_edge_vertices; LENGTH] THEN
    INTRO_TAC "tail new old edge" THEN
    ASM_SIMP_TAC[CARD_CLAUSES; FINITE_ROOTED_EDGE_VERTICES] THEN
    ARITH_TAC]);;

let ROOTED_EDGE_SET_SUBSET = prove
 (`!E u:A. !es.
        rooted_edge_list E u es
        ==> rooted_edge_set es SUBSET E`,
  REPEAT GEN_TAC THEN
  SPEC_TAC(`es:(A#A)list`,`es:(A#A)list`) THEN
  LIST_INDUCT_TAC THENL
   [REWRITE_TAC[rooted_edge_list; rooted_edge_set; EMPTY_SUBSET];
    FIRST_X_ASSUM(LABEL_TAC "induction") THEN
    MP_TAC(ISPEC `h:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    REWRITE_TAC[rooted_edge_list; rooted_edge_set; INSERT_SUBSET] THEN
    INTRO_TAC "tail new old edge" THEN CONJ_TAC THENL
     [USE_THEN "edge" ACCEPT_TAC;
      USE_THEN "induction" MATCH_MP_TAC THEN
      USE_THEN "tail" ACCEPT_TAC]]);;

let ROOTED_EDGE_SET_ENDPOINTS = prove
 (`!E u:A. !es e.
        rooted_edge_list E u es /\
        e IN rooted_edge_set es
        ==> e SUBSET rooted_edge_vertices u es`,
  REPEAT GEN_TAC THEN
  SPEC_TAC(`es:(A#A)list`,`es:(A#A)list`) THEN
  LIST_INDUCT_TAC THENL
   [REWRITE_TAC[rooted_edge_set; NOT_IN_EMPTY];
    FIRST_X_ASSUM(LABEL_TAC "induction") THEN
    MP_TAC(ISPEC `h:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    DISCH_THEN(CONJUNCTS_THEN2
     (LABEL_TAC "ordered") (LABEL_TAC "edge_member")) THEN
    USE_THEN "ordered" MP_TAC THEN
    REWRITE_TAC[rooted_edge_list] THEN
    INTRO_TAC "tail new old edge" THEN
    USE_THEN "edge_member" MP_TAC THEN
    REWRITE_TAC[rooted_edge_set; IN_INSERT] THEN
    DISCH_THEN(LABEL_TAC "edge_member") THEN
    REWRITE_TAC[rooted_edge_vertices] THEN
    USE_THEN "edge_member"
     (DISJ_CASES_THEN2 (LABEL_TAC "head_edge") (LABEL_TAC "tail_edge")) THENL
     [USE_THEN "head_edge" SUBST1_TAC THEN
      REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_INSERT] THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `rooted_edge_vertices (u:A) t` THEN CONJ_TAC THENL
       [USE_THEN "induction" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        SET_TAC[]]]]);;

let ROOTED_EDGE_LIST_NEW_EDGE = prove
 (`!E u x y:A. !es.
        rooted_edge_list E u (CONS (x,y) es)
        ==> ~({x,y} IN rooted_edge_set es)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[rooted_edge_list; FST; SND] THEN
  INTRO_TAC "tail new old edge" THEN
  DISCH_THEN(LABEL_TAC "old_edge") THEN
  SUBGOAL_THEN
   `{x:A,y} SUBSET rooted_edge_vertices u es`
  (LABEL_TAC "old_endpoints") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `u:A`; `es:(A#A)list`; `{x:A,y}`]
     ROOTED_EDGE_SET_ENDPOINTS) THEN
    ASM_REWRITE_TAC[];
    USE_THEN "new" MP_TAC THEN
    USE_THEN "old_endpoints" MP_TAC THEN SET_TAC[]]);;

let ROOTED_EDGE_LIST_CARD_EDGES = prove
 (`!E u:A. !es.
        rooted_edge_list E u es
        ==> CARD(rooted_edge_set es) = LENGTH es`,
  REPEAT GEN_TAC THEN
  SPEC_TAC(`es:(A#A)list`,`es:(A#A)list`) THEN
  LIST_INDUCT_TAC THENL
   [REWRITE_TAC[rooted_edge_list; rooted_edge_set;
                CARD_CLAUSES; LENGTH];
    FIRST_X_ASSUM(LABEL_TAC "induction") THEN
    MP_TAC(ISPEC `h:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    REWRITE_TAC[rooted_edge_list; rooted_edge_set; LENGTH] THEN
    INTRO_TAC "tail new old edge" THEN
    SUBGOAL_THEN
     `~({x:A,y} IN rooted_edge_set t)`
    (LABEL_TAC "new_edge") THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `u:A`; `x:A`; `y:A`; `t:(A#A)list`]
       ROOTED_EDGE_LIST_NEW_EDGE) THEN
      ASM_REWRITE_TAC[rooted_edge_list; FST; SND];
      ALL_TAC] THEN
    ASM_SIMP_TAC[CARD_CLAUSES; FINITE_ROOTED_EDGE_SET] THEN
    USE_THEN "induction" (fun induction_th ->
     MP_TAC(MATCH_MP induction_th
      (ASSUME `rooted_edge_list (E:(A->bool)->bool) u t`))) THEN
    ARITH_TAC]);;

let GRAPH_REACHABLE_CLOSED = prove
 (`!E W u v:A.
        (!x y. x IN W /\ {x,y} IN E ==> y IN W) /\
        graph_reachable E u v /\
        u IN W
        ==> v IN W`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "closed")
   (CONJUNCTS_THEN2 (LABEL_TAC "reachable") (LABEL_TAC "member"))) THEN
  SUBGOAL_THEN
   `RTC (\x y:A. {x,y} IN E) u v`
  (LABEL_TAC "rtc") THENL
   [USE_THEN "reachable"
     (ACCEPT_TAC o REWRITE_RULE[graph_reachable]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x y:A. RTC (\x y. {x,y} IN E) x y
             ==> (x IN W ==> y IN W)`
  (fun induction_th ->
    MP_TAC(SPECL [`u:A`; `v:A`] induction_th) THEN
    ASM_REWRITE_TAC[]) THEN
  MATCH_MP_TAC RTC_INDUCT THEN REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "edge") THEN
    DISCH_THEN(LABEL_TAC "x_member") THEN
    USE_THEN "closed" (MATCH_MP_TAC o SPECL [`x:A`; `y:A`]) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[];
    MESON_TAC[]]);;

let CONNECTED_GRAPH_CROSSING_EDGE = prove
 (`!V E W u:A.
        finite_simple_graph V E /\
        connected_graph V E /\
        W SUBSET V /\
        u IN W /\
        ~(W = V)
        ==> ?x y. x IN V DIFF W /\ y IN W /\ {x,y} IN E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected subset root proper" THEN
  SUBGOAL_THEN `?v:A. v IN V /\ ~(v IN W)`
  (X_CHOOSE_THEN `v:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex") (LABEL_TAC "v_outside"))) THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `graph_reachable E (u:A) v`
  (LABEL_TAC "reachable") THENL
   [USE_THEN "connected" MP_TAC THEN
    REWRITE_TAC[connected_graph] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    USE_THEN "subset" MP_TAC THEN REWRITE_TAC[SUBSET] THEN
    DISCH_THEN(MP_TAC o SPEC `u:A`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
  DISCH_THEN(LABEL_TAC "no_crossing") THEN
  SUBGOAL_THEN
   `!x y:A. x IN W /\ {x,y} IN E ==> y IN W`
  (LABEL_TAC "closed") THENL
   [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    INTRO_TAC "x_inside edge" THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "y_outside") THEN
    USE_THEN "no_crossing" (MATCH_MP_TAC o NOT_ELIM) THEN
    MAP_EVERY EXISTS_TAC [`y:A`; `x:A`] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(y:A) IN V` (LABEL_TAC "y_vertex") THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `x:A`; `y:A`]
      FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
      ASM_REWRITE_TAC[IN_DIFF] THEN
      SUBGOAL_THEN `{y:A,x} = {x,y}` SUBST1_TAC THENL
       [SET_TAC[];
        USE_THEN "edge" ACCEPT_TAC]];
    ALL_TAC] THEN
  USE_THEN "v_outside" (MATCH_MP_TAC o NOT_ELIM) THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `W:A->bool`; `u:A`; `v:A`]
   GRAPH_REACHABLE_CLOSED) THEN
  ASM_REWRITE_TAC[]);;

let CONNECTED_GRAPH_ROOTED_EDGE_LIST = prove
 (`!V E u:A.
        finite_simple_graph V E /\
        connected_graph V E /\
        u IN V
        ==> ?es:(A#A)list.
              rooted_edge_list E u es /\
              rooted_edge_vertices u es = V`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected root" THEN
  SUBGOAL_THEN
   `!n. !es:(A#A)list.
        rooted_edge_list E u es /\
        rooted_edge_vertices u es SUBSET V /\
        CARD(V DIFF rooted_edge_vertices u es) = n
        ==> ?es':(A#A)list.
              rooted_edge_list E u es' /\
              rooted_edge_vertices u es' = V`
  (LABEL_TAC "extension") THENL
   [MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN
    DISCH_THEN(LABEL_TAC "induction") THEN
    X_GEN_TAC `es:(A#A)list` THEN
    INTRO_TAC "ordered subset remaining" THEN
    ASM_CASES_TAC `rooted_edge_vertices (u:A) es = V` THENL
     [EXISTS_TAC `es:(A#A)list` THEN ASM_REWRITE_TAC[];
      FIRST_X_ASSUM(LABEL_TAC "proper")] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `rooted_edge_vertices (u:A) es`; `u:A`]
     CONNECTED_GRAPH_CROSSING_EDGE) THEN
    ASM_REWRITE_TAC[ROOT_IN_ROOTED_EDGE_VERTICES] THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "x_new")
       (CONJUNCTS_THEN2 (LABEL_TAC "y_old") (LABEL_TAC "edge"))))) THEN
    SUBGOAL_THEN
     `rooted_edge_list E u
       (CONS ((x:A),(y:A)) es)`
    (LABEL_TAC "extended_order") THENL
     [ASM_REWRITE_TAC[rooted_edge_list; FST; SND] THEN
      USE_THEN "x_new" MP_TAC THEN REWRITE_TAC[IN_DIFF] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `rooted_edge_vertices u (CONS ((x:A),(y:A)) es) SUBSET V`
    (LABEL_TAC "extended_subset") THENL
     [REWRITE_TAC[rooted_edge_vertices; FST; INSERT_SUBSET] THEN
      USE_THEN "x_new" MP_TAC THEN REWRITE_TAC[IN_DIFF] THEN
      ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `V DIFF rooted_edge_vertices u (CONS ((x:A),(y:A)) es) =
      (V DIFF rooted_edge_vertices u es) DELETE x`
    (LABEL_TAC "remaining_delete") THENL
     [REWRITE_TAC[rooted_edge_vertices; FST] THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~(V DIFF rooted_edge_vertices (u:A) es = {})`
    (LABEL_TAC "remaining_nonempty") THENL
     [USE_THEN "x_new" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `FINITE(V DIFF rooted_edge_vertices (u:A) es)`
    (LABEL_TAC "finite_remaining") THENL
     [MATCH_MP_TAC FINITE_DIFF THEN
      USE_THEN "graph"
       (ACCEPT_TAC o CONJUNCT1 o
        REWRITE_RULE[finite_simple_graph]);
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD(V DIFF rooted_edge_vertices u
       (CONS ((x:A),(y:A)) es)) < n`
    (LABEL_TAC "decreases") THENL
     [USE_THEN "remaining_delete" SUBST1_TAC THEN
      SUBGOAL_THEN
       `~(CARD(V DIFF rooted_edge_vertices (u:A) es) = 0)`
      (LABEL_TAC "remaining_positive") THENL
       [ASM_SIMP_TAC[CARD_EQ_0];
        MP_TAC(ISPECL
         [`x:A`; `V DIFF rooted_edge_vertices (u:A) es`]
         CARD_DELETE) THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
      ALL_TAC] THEN
    USE_THEN "induction" (fun induction_th ->
     USE_THEN "decreases" (fun decreases_th ->
      MATCH_MP_TAC
       (SPEC `CONS ((x:A),(y:A)) es`
        (MATCH_MP
         (SPEC
          `CARD(V DIFF rooted_edge_vertices u
            (CONS ((x:A),(y:A)) es))`
          induction_th)
         decreases_th)))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "extension" (MATCH_MP_TAC o SPECL
   [`CARD(V DIFF rooted_edge_vertices (u:A) [])`;
    `[]:(A#A)list`]) THEN
  ASM_REWRITE_TAC[rooted_edge_list; rooted_edge_vertices;
                  SING_SUBSET]);;

(* ------------------------------------------------------------------------- *)
(* Edge reversals as ordered transpositions of graph-rotation orbits.        *)
(* ------------------------------------------------------------------------- *)

let GRAPH_REVERSE_DART_SUBSET_PERMUTES = prove
 (`!T E:(A->bool)->bool.
        T SUBSET E
        ==> graph_reverse_dart T permutes graph_darts E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "subset") THEN
  MATCH_MP_TAC PERMUTES_INVOLUTION THEN
  REWRITE_TAC[GRAPH_REVERSE_DART_INVOLUTION] THEN
  X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "not_dart") THEN
  MATCH_MP_TAC GRAPH_REVERSE_DART_OUT THEN
  USE_THEN "not_dart" MP_TAC THEN
  USE_THEN "subset" MP_TAC THEN
  REWRITE_TAC[graph_darts; SUBSET; IN_ELIM_THM] THEN MESON_TAC[]);;

let GRAPH_REVERSE_DART_INSERT_EDGE = prove
 (`!t:(A->bool)->bool. !u v:A.
        ~(u = v) /\
        ~({u,v} IN t)
        ==> graph_reverse_dart ({u,v} INSERT t) =
            swap((u,v),(v,u)) o graph_reverse_dart t`,
  REPEAT GEN_TAC THEN INTRO_TAC "distinct new_edge" THEN
  REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `d:A#A` THEN
  ASM_CASES_TAC `dart_edge(d:A#A) = {u,v}` THENL
   [FIRST_X_ASSUM(LABEL_TAC "edge_eq") THEN
    SUBGOAL_THEN `(d:A#A) IN edge_darts {u,v}`
    (LABEL_TAC "edge_dart") THENL
     [REWRITE_TAC[edge_darts; IN_ELIM_THM] THEN
      USE_THEN "edge_eq" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(d:A#A) = (u,v) \/ d = (v,u)`
    (DISJ_CASES_THEN2 SUBST1_TAC SUBST1_TAC) THENL
     [USE_THEN "edge_dart" MP_TAC THEN
      USE_THEN "distinct" (fun distinct_th ->
       REWRITE_TAC
        [MATCH_MP (ISPECL [`u:A`; `v:A`] EDGE_DARTS_PAIR) distinct_th;
         IN_INSERT; NOT_IN_EMPTY]);
      ASM_REWRITE_TAC[graph_reverse_dart; o_THM; IN_GRAPH_DARTS;
                      REVERSE_DART_PAIR; SWAP_LEFT; IN_INSERT];
      SUBGOAL_THEN `{v:A,u} = {u,v}` (LABEL_TAC "edge_symmetry") THENL
       [SET_TAC[];
        ASM_REWRITE_TAC[graph_reverse_dart; o_THM; IN_GRAPH_DARTS;
                        REVERSE_DART_PAIR; SWAP_RIGHT; IN_INSERT]]];
    FIRST_X_ASSUM(LABEL_TAC "different_edge") THEN
    SUBGOAL_THEN
     `graph_reverse_dart ({u:A,v} INSERT t) d =
      graph_reverse_dart t d`
    (LABEL_TAC "same_reversal") THENL
     [REWRITE_TAC[graph_reverse_dart; graph_darts; IN_ELIM_THM;
                  IN_INSERT] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "same_reversal" SUBST1_TAC THEN
    REWRITE_TAC[o_THM] THEN CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC SWAP_OTHER THEN CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "forward") THEN
      USE_THEN "different_edge" (MATCH_MP_TAC o NOT_ELIM) THEN
      SUBGOAL_THEN
       `dart_edge(graph_reverse_dart t (d:A#A)) = dart_edge d`
      MP_TAC THENL
       [REWRITE_TAC[graph_reverse_dart] THEN COND_CASES_TAC THEN
        ASM_REWRITE_TAC[DART_EDGE_REVERSE];
        ASM_REWRITE_TAC[DART_EDGE_PAIR] THEN
        DISCH_THEN(LABEL_TAC "forward_edge") THEN
        USE_THEN "different_edge" (MATCH_MP_TAC o NOT_ELIM) THEN
        USE_THEN "forward_edge" (ACCEPT_TAC o SYM)];
      DISCH_THEN(LABEL_TAC "reverse") THEN
      USE_THEN "different_edge" (MATCH_MP_TAC o NOT_ELIM) THEN
      SUBGOAL_THEN
       `dart_edge(graph_reverse_dart t (d:A#A)) = dart_edge d`
      MP_TAC THENL
       [REWRITE_TAC[graph_reverse_dart] THEN COND_CASES_TAC THEN
        ASM_REWRITE_TAC[DART_EDGE_REVERSE];
        ASM_REWRITE_TAC[DART_EDGE_PAIR] THEN
        DISCH_THEN(LABEL_TAC "reverse_edge") THEN
        USE_THEN "different_edge" (MATCH_MP_TAC o NOT_ELIM) THEN
        TRANS_TAC EQ_TRANS `{v:A,u}` THEN CONJ_TAC THENL
         [USE_THEN "reverse_edge" (ACCEPT_TAC o SYM);
          ACCEPT_TAC(SET_RULE `{v:A,u} = {u,v}`)]]]]);;

let rooted_edge_reversal = new_recursive_definition list_RECURSION
 `(rooted_edge_reversal ([]:(A#A)list) = I) /\
  (rooted_edge_reversal (CONS (d:A#A) es) =
        swap((FST d,SND d),(SND d,FST d)) o
        rooted_edge_reversal es)`;;

let ROOTED_EDGE_REVERSAL_EQ_GRAPH_REVERSE_DART = prove
 (`!V E u:A. !es.
        finite_simple_graph V E /\
        rooted_edge_list E u es
        ==> rooted_edge_reversal es =
            graph_reverse_dart (rooted_edge_set es)`,
  REPEAT GEN_TAC THEN
  SPEC_TAC(`es:(A#A)list`,`es:(A#A)list`) THEN
  LIST_INDUCT_TAC THENL
   [REWRITE_TAC[rooted_edge_reversal; rooted_edge_set;
                FUN_EQ_THM; I_THM; graph_reverse_dart;
                graph_darts; IN_ELIM_THM; NOT_IN_EMPTY];
    FIRST_X_ASSUM(LABEL_TAC "induction") THEN
    MP_TAC(ISPEC `h:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    REWRITE_TAC[rooted_edge_list; rooted_edge_reversal;
                rooted_edge_set; FST; SND] THEN
    INTRO_TAC "graph tail new old edge" THEN
    SUBGOAL_THEN `~(x:A = y)` (LABEL_TAC "distinct") THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `x:A`; `y:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~({x:A,y} IN rooted_edge_set t)`
    (LABEL_TAC "new_edge") THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `u:A`; `x:A`; `y:A`; `t:(A#A)list`]
       ROOTED_EDGE_LIST_NEW_EDGE) THEN
      ASM_REWRITE_TAC[rooted_edge_list; FST; SND];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`rooted_edge_set (t:(A#A)list)`; `x:A`; `y:A`]
     GRAPH_REVERSE_DART_INSERT_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(LABEL_TAC "insert_reversal") THEN
    USE_THEN "insert_reversal" (fun th -> REWRITE_TAC[th]) THEN
    AP_TERM_TAC THEN
    USE_THEN "induction" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_REVERSE_DART_PRESERVES_VERTEX_SET = prove
 (`!t:(A->bool)->bool. !W d:A#A.
        (!e. e IN t ==> e SUBSET W)
        ==> (FST(graph_reverse_dart t d) IN W <=>
             FST d IN W)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "edges") THEN
  MP_TAC(ISPEC `d:A#A` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:A`
   (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
  REWRITE_TAC[graph_reverse_dart; IN_GRAPH_DARTS] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[REVERSE_DART_PAIR; FST] THEN
  SUBGOAL_THEN `{x:A,y} SUBSET W`
  (LABEL_TAC "endpoints") THENL
   [USE_THEN "edges" (MATCH_MP_TAC o SPEC `{x:A,y}`) THEN
    ASM_REWRITE_TAC[];
    USE_THEN "endpoints" MP_TAC THEN
    REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
    INTRO_TAC "x y" THEN ASM_REWRITE_TAC[]]);;

let ROOTED_EDGE_REVERSAL_PRESERVES_VERTICES = prove
 (`!V E u:A. !es d:A#A.
        finite_simple_graph V E /\
        rooted_edge_list E u es
        ==> (FST(rooted_edge_reversal es d) IN
             rooted_edge_vertices u es <=>
             FST d IN rooted_edge_vertices u es)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph ordered" THEN
  SUBGOAL_THEN
   `rooted_edge_reversal (es:(A#A)list) =
    graph_reverse_dart (rooted_edge_set es)`
  SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `es:(A#A)list`]
     ROOTED_EDGE_REVERSAL_EQ_GRAPH_REVERSE_DART) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC GRAPH_REVERSE_DART_PRESERVES_VERTEX_SET THEN
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `u:A`; `es:(A#A)list`; `e:A->bool`]
     ROOTED_EDGE_SET_ENDPOINTS) THEN
    ASM_REWRITE_TAC[]]);;

let ROOTED_EDGE_ROTATION_PRESERVES_VERTICES = prove
 (`!V E r:(A#A)->A#A. !u:A. !es d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        rooted_edge_list E u es /\
        d IN graph_darts E
        ==> (FST((rooted_edge_reversal es o r) d) IN
             rooted_edge_vertices u es <=>
             FST d IN rooted_edge_vertices u es)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation ordered dart" THEN
  REWRITE_TAC[o_THM] THEN
  SUBGOAL_THEN
   `(FST(rooted_edge_reversal es ((r:(A#A)->A#A) d)) IN
     rooted_edge_vertices u es <=>
     FST(r d) IN rooted_edge_vertices u es)`
  (LABEL_TAC "reversal") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`;
      `es:(A#A)list`; `(r:(A#A)->A#A) d`]
     ROOTED_EDGE_REVERSAL_PRESERVES_VERTICES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FST((r:(A#A)->A#A) d) = FST d`
  (LABEL_TAC "tail") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_ROTATION_TAIL) THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;

let PERMUTATION_ORBITS_DISTINCT_BY_INVARIANT = prove
 (`!f:A->A. !s P a b.
        FINITE s /\
        f permutes s /\
        a IN s /\
        b IN s /\
        (!z. z IN s ==> (P(f z) <=> P z)) /\
        ~(P a <=> P b)
        ==> ~(permutation_orbit f a = permutation_orbit f b)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite permutation a b invariant separated" THEN
  DISCH_THEN(LABEL_TAC "same_orbit") THEN
  SUBGOAL_THEN
   `(b:A) IN permutation_orbit f a`
  (LABEL_TAC "b_orbit") THENL
   [USE_THEN "same_orbit" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL;
    ALL_TAC] THEN
  USE_THEN "b_orbit" MP_TAC THEN
  REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THEN
  SUBGOAL_THEN
   `!m. ITER m (f:A->A) a IN s /\
        (P(ITER m f a) <=> P a)`
  (LABEL_TAC "iteration") THENL
   [INDUCT_TAC THEN ASM_REWRITE_TAC[ITER] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`f:A->A`; `s:A->bool`; `ITER m (f:A->A) a`]
      PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN
       `(P(f(ITER m (f:A->A) a)) <=>
         P(ITER m f a))`
      (LABEL_TAC "preserved") THENL
       [USE_THEN "invariant"
         (MATCH_MP_TAC o SPEC `ITER m (f:A->A) a`) THEN
        ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[]]];
     ALL_TAC] THEN
  SUBGOAL_THEN `((P:A->bool) (b:A) <=> P (a:A))`
  (LABEL_TAC "same_value") THENL
   [USE_THEN "iteration" (fun iteration_th ->
     USE_THEN "step" (fun step_th ->
      ACCEPT_TAC
       (SUBS [step_th]
        (CONJUNCT2(SPEC `n:num` iteration_th)))));
    ALL_TAC] THEN
  USE_THEN "same_value" (fun same_th ->
   USE_THEN "separated" (fun separated_th ->
    ACCEPT_TAC(MP (NOT_ELIM separated_th) (SYM same_th)))));;

let ROOTED_EDGE_REVERSAL_ROTATION_PERMUTES = prove
 (`!V E r:(A#A)->A#A. !u:A. !es.
        finite_simple_graph V E /\
        graph_rotation E r /\
        rooted_edge_list E u es
        ==> (rooted_edge_reversal es o r) permutes graph_darts E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation ordered" THEN
  SUBGOAL_THEN
   `rooted_edge_reversal (es:(A#A)list) =
    graph_reverse_dart (rooted_edge_set es)`
  SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `es:(A#A)list`]
     ROOTED_EDGE_REVERSAL_EQ_GRAPH_REVERSE_DART) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC PERMUTES_COMPOSE THEN CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC GRAPH_REVERSE_DART_SUBSET_PERMUTES THEN
      MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `u:A`; `es:(A#A)list`]
       ROOTED_EDGE_SET_SUBSET) THEN
      ASM_REWRITE_TAC[]]]);;

let ROOTED_EDGE_NEXT_DART_ORBITS_DISTINCT = prove
 (`!V E r:(A#A)->A#A. !u x y:A. !es.
        finite_simple_graph V E /\
        graph_rotation E r /\
        rooted_edge_list E u (CONS (x,y) es)
        ==> ~(permutation_orbit (rooted_edge_reversal es o r) (x,y) =
              permutation_orbit (rooted_edge_reversal es o r) (y,x))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation ordered" THEN
  SUBGOAL_THEN `rooted_edge_list E (u:A) es`
  (LABEL_TAC "tail") THENL
   [USE_THEN "ordered" MP_TAC THEN
    REWRITE_TAC[rooted_edge_list; FST; SND] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((x:A) IN rooted_edge_vertices u es) /\
    y IN rooted_edge_vertices u es /\
    {x,y} IN E`
  (CONJUNCTS_THEN2 (LABEL_TAC "new")
   (CONJUNCTS_THEN2 (LABEL_TAC "old") (LABEL_TAC "edge"))) THENL
   [USE_THEN "ordered" MP_TAC THEN
    REWRITE_TAC[rooted_edge_list; FST; SND] THEN MESON_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`rooted_edge_reversal (es:(A#A)list) o (r:(A#A)->A#A)`;
    `graph_darts (E:(A->bool)->bool)`;
    `\d:A#A. FST d IN rooted_edge_vertices (u:A) es`;
    `(x:A,y:A)`; `(y:A,x:A)`]
   PERMUTATION_ORBITS_DISTINCT_BY_INVARIANT) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `es:(A#A)list`]
     ROOTED_EDGE_REVERSAL_ROTATION_PERMUTES) THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    REWRITE_TAC[IN_GRAPH_DARTS] THEN
    ONCE_REWRITE_TAC[SET_RULE `{y:A,x} = {x,y}`] THEN
    USE_THEN "edge" ACCEPT_TAC;
    X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "dart") THEN
    REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `es:(A#A)list`; `d:A#A`]
     ROOTED_EDGE_ROTATION_PRESERVES_VERTICES) THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[FST]]);;

let ROOTED_EDGE_REVERSAL_ORBIT_COUNT = prove
 (`!V E r:(A#A)->A#A. !u:A. !es.
        finite_simple_graph V E /\
        graph_rotation E r /\
        rooted_edge_list E u es
        ==> CARD(permutation_orbits r (graph_darts E)) =
            CARD(permutation_orbits
              (rooted_edge_reversal es o r) (graph_darts E)) +
            LENGTH es`,
  REPEAT GEN_TAC THEN
  SPEC_TAC(`es:(A#A)list`,`es:(A#A)list`) THEN
  LIST_INDUCT_TAC THENL
   [REWRITE_TAC[rooted_edge_list; rooted_edge_reversal;
                I_O_ID; LENGTH; ADD_CLAUSES];
    POP_ASSUM MP_TAC THEN
    DISCH_THEN(LABEL_TAC "induction") THEN
    MP_TAC(ISPEC `h:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    INTRO_TAC "graph rotation ordered" THEN
    SUBGOAL_THEN `rooted_edge_list E (u:A) t`
    (LABEL_TAC "tail") THENL
     [USE_THEN "ordered" MP_TAC THEN
      REWRITE_TAC[rooted_edge_list; FST; SND] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `{x:A,y} IN E`
    (LABEL_TAC "edge") THENL
     [USE_THEN "ordered" MP_TAC THEN
      REWRITE_TAC[rooted_edge_list; FST; SND] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD(permutation_orbits (r:(A#A)->A#A)
       (graph_darts (E:(A->bool)->bool))) =
      CARD(permutation_orbits
       (rooted_edge_reversal (t:(A#A)list) o r)
       (graph_darts E)) +
      LENGTH(t:(A#A)list)`
    (LABEL_TAC "previous_count") THENL
     [REMOVE_THEN "induction" (fun induction_th ->
       USE_THEN "graph" (fun graph_th ->
        USE_THEN "rotation" (fun rotation_th ->
         USE_THEN "tail" (fun tail_th ->
          ACCEPT_TAC(MATCH_MP induction_th
           (CONJ graph_th (CONJ rotation_th tail_th)))))));
      ALL_TAC] THEN
    REMOVE_THEN "induction" (K ALL_TAC) THEN
    SUBGOAL_THEN
     `(rooted_edge_reversal t o (r:(A#A)->A#A))
      permutes graph_darts E`
    (LABEL_TAC "permutation") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `u:A`; `t:(A#A)list`]
       ROOTED_EDGE_REVERSAL_ROTATION_PERMUTES) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~(permutation_orbit
         (rooted_edge_reversal t o (r:(A#A)->A#A)) (x,y) =
        permutation_orbit
         (rooted_edge_reversal t o r) (y,x))`
    (LABEL_TAC "different_orbits") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `u:A`; `x:A`; `y:A`; `t:(A#A)list`]
       ROOTED_EDGE_NEXT_DART_ORBITS_DISTINCT) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD(permutation_orbits
       (rooted_edge_reversal t o (r:(A#A)->A#A))
       (graph_darts E)) =
      CARD(permutation_orbits
       (swap((x:A,y),(y,x)) o
        (rooted_edge_reversal t o r))
       (graph_darts E)) + 1`
    (LABEL_TAC "merged_count") THENL
     [MATCH_MP_TAC(ISPECL
       [`rooted_edge_reversal t o (r:(A#A)->A#A)`;
        `graph_darts (E:(A->bool)->bool)`;
        `(x:A,y:A)`; `(y:A,x:A)`]
       PERMUTATION_ORBITS_SWAP_DISTINCT) THEN
      ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
        USE_THEN "graph" ACCEPT_TAC;
        ASM_REWRITE_TAC[IN_GRAPH_DARTS];
        REWRITE_TAC[IN_GRAPH_DARTS] THEN
        ONCE_REWRITE_TAC[SET_RULE `{y:A,x} = {x,y}`] THEN
        USE_THEN "edge" ACCEPT_TAC];
      ALL_TAC] THEN
    REWRITE_TAC[rooted_edge_reversal; FST; SND; LENGTH;
                GSYM o_ASSOC] THEN
    ASM_ARITH_TAC]);;

let GRAPH_REVERSE_ROTATION_PERMUTES = prove
 (`!E r:(A#A)->A#A. !t.
        graph_rotation E r /\
        t SUBSET E
        ==> (graph_reverse_dart t o r) permutes graph_darts E`,
  REPEAT GEN_TAC THEN INTRO_TAC "rotation subset" THEN
  MATCH_MP_TAC PERMUTES_COMPOSE THEN CONJ_TAC THENL
   [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    MATCH_MP_TAC GRAPH_REVERSE_DART_SUBSET_PERMUTES THEN
    USE_THEN "subset" ACCEPT_TAC]);;

let GRAPH_REVERSE_DART_UNION_ORBIT_BOUND = prove
 (`!V E r:(A#A)->A#A. !t.
        finite_simple_graph V E /\
        graph_rotation E r /\
        t SUBSET E
        ==> !q. FINITE q /\
                q SUBSET E /\
                DISJOINT q t
                ==> CARD(permutation_orbits
                     (graph_reverse_dart (q UNION t) o r)
                     (graph_darts E)) <=
                    CARD(permutation_orbits
                     (graph_reverse_dart t o r)
                     (graph_darts E)) +
                    CARD q`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation t_subset" THEN
  REWRITE_TAC[IMP_CONJ] THEN
  MATCH_MP_TAC FINITE_INDUCT_STRONG THEN CONJ_TAC THENL
   [REWRITE_TAC[EMPTY_SUBSET; DISJOINT_EMPTY; UNION_EMPTY;
                CARD_CLAUSES; ADD_CLAUSES; LE_REFL];
    MAP_EVERY X_GEN_TAC [`e:A->bool`; `q:(A->bool)->bool`] THEN
    INTRO_TAC "induction new finite_q" THEN
    DISCH_THEN(LABEL_TAC "extended_subset") THEN
    DISCH_THEN(LABEL_TAC "disjoint") THEN
    SUBGOAL_THEN
     `(e:A->bool) IN E /\ q SUBSET E`
    (CONJUNCTS_THEN2 (LABEL_TAC "edge") (LABEL_TAC "q_subset")) THENL
     [USE_THEN "extended_subset" MP_TAC THEN
      REWRITE_TAC[INSERT_SUBSET];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((e:A->bool) IN t) /\ DISJOINT q t`
    (CONJUNCTS_THEN2
      (LABEL_TAC "not_in_t") (LABEL_TAC "tail_disjoint")) THENL
     [USE_THEN "disjoint" MP_TAC THEN
      REWRITE_TAC[DISJOINT; INTER; EXTENSION; IN_ELIM_THM;
                  IN_INSERT; NOT_IN_EMPTY] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD(permutation_orbits
       (graph_reverse_dart (q UNION t) o
        (r:(A#A)->A#A)) (graph_darts E)) <=
      CARD(permutation_orbits
       (graph_reverse_dart t o r) (graph_darts E)) +
      CARD q`
    (LABEL_TAC "previous_bound") THENL
     [REMOVE_THEN "induction" (fun induction_th ->
       USE_THEN "q_subset" (fun subset_th ->
        USE_THEN "tail_disjoint" (fun disjoint_th ->
         ACCEPT_TAC(MP (MP induction_th subset_th) disjoint_th))));
      ALL_TAC] THEN
    REMOVE_THEN "induction" (K ALL_TAC) THEN
    SUBGOAL_THEN `(e:A->bool) HAS_SIZE 2`
    (LABEL_TAC "edge_size") THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    USE_THEN "edge_size" MP_TAC THEN
    REWRITE_TAC[HAS_SIZE_CONV `(e:A->bool) HAS_SIZE 2`] THEN
    INTRO_TAC "@u v. distinct edge_pair" THEN
    USE_THEN "edge_pair" SUBST_ALL_TAC THEN
    SUBGOAL_THEN
     `~({u:A,v} IN q UNION t)`
    (LABEL_TAC "new_union") THENL
     [REWRITE_TAC[IN_UNION] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_reverse_dart
       (({u:A,v} INSERT q) UNION t) o (r:(A#A)->A#A) =
      swap((u,v),(v,u)) o
       (graph_reverse_dart (q UNION t) o r)`
    (LABEL_TAC "insert_reversal") THENL
     [ASM_REWRITE_TAC[INSERT_UNION; o_ASSOC] THEN
      AP_THM_TAC THEN AP_TERM_TAC THEN
      MATCH_MP_TAC(ISPECL
       [`q UNION t:(A->bool)->bool`; `u:A`; `v:A`]
       GRAPH_REVERSE_DART_INSERT_EDGE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(graph_reverse_dart (q UNION t) o (r:(A#A)->A#A))
      permutes graph_darts E`
    (LABEL_TAC "permutation") THENL
     [MATCH_MP_TAC GRAPH_REVERSE_ROTATION_PERMUTES THEN
      ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD(permutation_orbits
       (graph_reverse_dart
         (({u:A,v} INSERT q) UNION t) o
        (r:(A#A)->A#A)) (graph_darts E)) <=
      CARD(permutation_orbits
       (graph_reverse_dart (q UNION t) o r)
       (graph_darts E)) + 1`
    (LABEL_TAC "one_more") THENL
     [USE_THEN "insert_reversal" SUBST1_TAC THEN
      MATCH_MP_TAC(ISPECL
       [`graph_reverse_dart (q UNION t) o (r:(A#A)->A#A)`;
        `graph_darts (E:(A->bool)->bool)`;
        `(u:A,v:A)`; `(v:A,u:A)`]
       PERMUTATION_ORBITS_SWAP_LE) THEN
      ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
        USE_THEN "graph" ACCEPT_TAC;
        ASM_REWRITE_TAC[IN_GRAPH_DARTS];
        REWRITE_TAC[IN_GRAPH_DARTS] THEN
        ONCE_REWRITE_TAC[SET_RULE `{v:A,u} = {u,v}`] THEN
        USE_THEN "edge" ACCEPT_TAC];
      ALL_TAC] THEN
    REMOVE_THEN "insert_reversal" (K ALL_TAC) THEN
    ASM_SIMP_TAC[CARD_CLAUSES] THEN
    ASM_ARITH_TAC]);;

let GRAPH_REVERSE_DART_EXTENSION_ORBIT_BOUND = prove
 (`!V E r:(A#A)->A#A. !t.
        finite_simple_graph V E /\
        graph_rotation E r /\
        t SUBSET E
        ==> CARD(permutation_orbits
             (graph_reverse_dart E o r) (graph_darts E)) <=
            CARD(permutation_orbits
             (graph_reverse_dart t o r) (graph_darts E)) +
            CARD(E DIFF t)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation subset" THEN
  SUBGOAL_THEN `FINITE(E DIFF t:(A->bool)->bool)`
  (LABEL_TAC "finite_difference") THENL
   [MATCH_MP_TAC FINITE_DIFF THEN
    USE_THEN "graph"
     (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o
      REWRITE_RULE[finite_simple_graph]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(E DIFF t:(A->bool)->bool) SUBSET E /\
    DISJOINT (E DIFF t) t`
  (CONJUNCTS_THEN2
    (LABEL_TAC "difference_subset") (LABEL_TAC "disjoint")) THENL
   [REWRITE_TAC[SUBSET; DISJOINT] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E DIFF t) UNION t = (E:(A->bool)->bool)`
  (LABEL_TAC "decomposition") THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!q. FINITE(q:(A->bool)->bool) /\
        q SUBSET E /\ DISJOINT q t
        ==> CARD(permutation_orbits
             (graph_reverse_dart (q UNION t) o r)
             (graph_darts E)) <=
            CARD(permutation_orbits
             (graph_reverse_dart t o r) (graph_darts E)) +
            CARD q`
  (LABEL_TAC "union_bound") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `t:(A->bool)->bool`]
     GRAPH_REVERSE_DART_UNION_ORBIT_BOUND) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REMOVE_THEN "union_bound"
   (MP_TAC o SPEC `E DIFF t:(A->bool)->bool`) THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "decomposition" (fun th -> REWRITE_TAC[th]));;

let FINITE_SIMPLE_GRAPH_DART_FST = prove
 (`!V E d:A#A.
        finite_simple_graph V E /\
        d IN graph_darts E
        ==> FST d IN V`,
  MESON_TAC[FINITE_SIMPLE_GRAPH_DART; PAIR]);;

let CONNECTED_GRAPH_VERTEX_HAS_OUTGOING_DART = prove
 (`!V E v:A.
        finite_simple_graph V E /\
        connected_graph V E /\
        ~(E = {}) /\
        v IN V
        ==> ?d:A#A. d IN outgoing_darts E v`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected nonempty vertex" THEN
  SUBGOAL_THEN `?e:A->bool. e IN E`
  (X_CHOOSE_THEN `e:A->bool` (LABEL_TAC "edge")) THENL
   [USE_THEN "nonempty" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(e:A->bool) HAS_SIZE 2`
  (LABEL_TAC "edge_size") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
     (CONJUNCTS_THEN2 (K ALL_TAC)
      (MP_TAC o SPEC `e:A->bool`))) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(e:A->bool) SUBSET V`
  (LABEL_TAC "edge_subset") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
     (CONJUNCTS_THEN2 (K ALL_TAC)
      (MP_TAC o SPEC `e:A->bool`))) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "edge_size" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE_CONV `(e:A->bool) HAS_SIZE 2`] THEN
  INTRO_TAC "@x y. distinct edge_pair" THEN
  USE_THEN "edge_pair" SUBST_ALL_TAC THEN
  SUBGOAL_THEN `(x:A) IN V /\ (y:A) IN V`
  (CONJUNCTS_THEN2 (LABEL_TAC "x_vertex") (LABEL_TAC "y_vertex")) THENL
   [USE_THEN "edge_subset" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `graph_reachable E (v:A) x`
  (LABEL_TAC "reachable") THENL
   [USE_THEN "connected" MP_TAC THEN
    REWRITE_TAC[connected_graph] THEN
    DISCH_THEN(MP_TAC o SPECL [`v:A`; `x:A`]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(v:A) = x` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    EXISTS_TAC `(x:A,y:A)` THEN
    ASM_REWRITE_TAC[IN_OUTGOING_DARTS; IN_GRAPH_DARTS; FST];
    FIRST_X_ASSUM(LABEL_TAC "different")] THEN
  USE_THEN "reachable" MP_TAC THEN
  REWRITE_TAC[graph_reachable] THEN
  ONCE_REWRITE_TAC[RTC_CASES_R] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "first_edge") (K ALL_TAC))) THEN
  EXISTS_TAC `(v:A,w:A)` THEN
  ASM_REWRITE_TAC[IN_OUTGOING_DARTS; IN_GRAPH_DARTS; FST]);;

let GRAPH_ROTATION_ORBIT_OUTGOING_DARTS = prove
 (`!E r d:A#A.
        graph_rotation E r /\
        d IN graph_darts E
        ==> permutation_orbit r d = outgoing_darts E (FST d)`,
  REPEAT GEN_TAC THEN INTRO_TAC "rotation dart" THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `d':A#A` THEN
  REWRITE_TAC[IN_PERMUTATION_ORBIT; IN_OUTGOING_DARTS] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `n:num` (SUBST1_TAC o SYM)) THEN
    MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_ROTATION_ITER) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `n:num`) THEN SIMP_TAC[];
    INTRO_TAC "dart' same_tail" THEN
    MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `d:A#A`; `d':A#A`]
     GRAPH_ROTATION_ORBIT) THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_ROTATION_ORBITS_AS_OUTGOING_DARTS = prove
 (`!V E r:(A#A)->A#A.
        finite_simple_graph V E /\
        connected_graph V E /\
        graph_rotation E r /\
        ~(E = {})
        ==> permutation_orbits r (graph_darts E) =
            IMAGE (outgoing_darts E) V`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected rotation nonempty" THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `c:(A#A)->bool` THEN
  REWRITE_TAC[IN_PERMUTATION_ORBITS; IN_IMAGE] THEN EQ_TAC THENL
   [INTRO_TAC "@d. dart representation" THEN
    EXISTS_TAC `FST(d:A#A)` THEN CONJ_TAC THENL
     [USE_THEN "representation" SUBST1_TAC THEN
      MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
       GRAPH_ROTATION_ORBIT_OUTGOING_DARTS) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `d:A#A`]
       FINITE_SIMPLE_GRAPH_DART_FST) THEN
      ASM_REWRITE_TAC[]];
    INTRO_TAC "@v. representation vertex" THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `v:A`]
     CONNECTED_GRAPH_VERTEX_HAS_OUTGOING_DART) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:A#A` (LABEL_TAC "outgoing")) THEN
    EXISTS_TAC `d:A#A` THEN
    CONJ_TAC THENL
     [USE_THEN "outgoing" MP_TAC THEN
      REWRITE_TAC[IN_OUTGOING_DARTS] THEN
      INTRO_TAC "dart same_tail" THEN
      USE_THEN "dart" ACCEPT_TAC;
      USE_THEN "representation" SUBST1_TAC THEN
      USE_THEN "outgoing" MP_TAC THEN
      REWRITE_TAC[IN_OUTGOING_DARTS] THEN
      INTRO_TAC "dart same_tail" THEN
      USE_THEN "same_tail" (SUBST1_TAC o SYM) THEN
      CONV_TAC SYM_CONV THEN
      MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
       GRAPH_ROTATION_ORBIT_OUTGOING_DARTS) THEN
      ASM_REWRITE_TAC[]]]);;

let CONNECTED_GRAPH_OUTGOING_DARTS_INJECTIVE = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E /\
        connected_graph V E /\
        ~(E = {})
        ==> !u v.
              u IN V /\ v IN V /\
              outgoing_darts E u = outgoing_darts E v
              ==> u = v`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected nonempty" THEN
  MAP_EVERY X_GEN_TAC [`u:A`; `v:A`] THEN
  INTRO_TAC "u_vertex v_vertex same" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
   CONNECTED_GRAPH_VERTEX_HAS_OUTGOING_DART) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:A#A` (LABEL_TAC "outgoing_u")) THEN
  REMOVE_THEN "same" (fun same_th ->
   REMOVE_THEN "outgoing_u" (fun outgoing_u_th ->
    MP_TAC outgoing_u_th THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN
    INTRO_TAC "u_dart u_tail" THEN
    SUBGOAL_THEN `(d:A#A) IN outgoing_darts E v`
    (LABEL_TAC "outgoing_v") THENL
     [ACCEPT_TAC(REWRITE_RULE[same_th] outgoing_u_th);
      USE_THEN "outgoing_v" MP_TAC THEN
      REWRITE_TAC[IN_OUTGOING_DARTS] THEN
      INTRO_TAC "v_dart v_tail" THEN
      USE_THEN "u_tail" (fun u_tail_th ->
       USE_THEN "v_tail" (fun v_tail_th ->
        ACCEPT_TAC(TRANS (SYM u_tail_th) v_tail_th))) ])));;

let GRAPH_ROTATION_ORBIT_COUNT = prove
 (`!V E r:(A#A)->A#A.
        finite_simple_graph V E /\
        connected_graph V E /\
        graph_rotation E r /\
        ~(E = {})
        ==> CARD(permutation_orbits r (graph_darts E)) = CARD V`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected rotation nonempty" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
   GRAPH_ROTATION_ORBITS_AS_OUTGOING_DARTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC CARD_IMAGE_INJ THEN CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `v:A`] THEN
    INTRO_TAC "u_vertex v_vertex same" THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`]
     CONNECTED_GRAPH_OUTGOING_DARTS_INJECTIVE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(MP_TAC o SPECL [`u:A`; `v:A`]) THEN
      ASM_REWRITE_TAC[]];
    USE_THEN "graph"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[finite_simple_graph])]);;

let FINITE_SIMPLE_GRAPH_NONEMPTY_EDGE_HAS_VERTEX = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E /\
        ~(E = {})
        ==> ?u. u IN V`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph nonempty" THEN
  SUBGOAL_THEN `?e:A->bool. e IN E`
  (X_CHOOSE_THEN `e:A->bool` (LABEL_TAC "edge")) THENL
   [USE_THEN "nonempty" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(e:A->bool) HAS_SIZE 2`
  (LABEL_TAC "edge_size") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
     (CONJUNCTS_THEN2 (K ALL_TAC)
      (MP_TAC o SPEC `e:A->bool`))) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(e:A->bool) SUBSET V`
  (LABEL_TAC "edge_subset") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
     (CONJUNCTS_THEN2 (K ALL_TAC)
      (MP_TAC o SPEC `e:A->bool`))) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "edge_size" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE_CONV `(e:A->bool) HAS_SIZE 2`] THEN
  INTRO_TAC "@u v. distinct edge_pair" THEN
  EXISTS_TAC `u:A` THEN
  USE_THEN "edge_pair" SUBST_ALL_TAC THEN
  USE_THEN "edge_subset" MP_TAC THEN SET_TAC[]);;

let CONNECTED_GRAPH_REVERSE_ROTATION_EULER_BOUND = prove
 (`!V E r:(A#A)->A#A.
        finite_simple_graph V E /\
        connected_graph V E /\
        graph_rotation E r /\
        ~(E = {})
        ==> CARD V +
            CARD(permutation_orbits
              (graph_reverse_dart E o r) (graph_darts E))
            <= CARD E + 2`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected rotation nonempty" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`]
   FINITE_SIMPLE_GRAPH_NONEMPTY_EDGE_HAS_VERTEX) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:A` (LABEL_TAC "root")) THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
   CONNECTED_GRAPH_ROOTED_EDGE_LIST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `es:(A#A)list`
   (CONJUNCTS_THEN2 (LABEL_TAC "ordered") (LABEL_TAC "spanning"))) THEN
  SUBGOAL_THEN `FINITE(E:(A->bool)->bool)`
  (LABEL_TAC "finite_edges") THENL
   [USE_THEN "graph"
     (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o
      REWRITE_RULE[finite_simple_graph]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `rooted_edge_set (es:(A#A)list) SUBSET E`
  (LABEL_TAC "tree_subset") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `u:A`; `es:(A#A)list`]
     ROOTED_EDGE_SET_SUBSET) THEN
    USE_THEN "ordered" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(V:A->bool) = LENGTH(es:(A#A)list) + 1`
  (LABEL_TAC "vertex_count") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `u:A`; `es:(A#A)list`]
     ROOTED_EDGE_LIST_CARD_VERTICES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(rooted_edge_set (es:(A#A)list)) =
    LENGTH(es:(A#A)list)`
  (LABEL_TAC "tree_count") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `u:A`; `es:(A#A)list`]
     ROOTED_EDGE_LIST_CARD_EDGES) THEN
    USE_THEN "ordered" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(rooted_edge_set (es:(A#A)list)) <=
    CARD(E:(A->bool)->bool)`
  (LABEL_TAC "tree_le_edges") THENL
   [MATCH_MP_TAC CARD_SUBSET THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD((E:(A->bool)->bool) DIFF
         rooted_edge_set (es:(A#A)list)) =
    CARD(E:(A->bool)->bool) -
    CARD(rooted_edge_set (es:(A#A)list))`
  (LABEL_TAC "difference_count") THENL
   [MATCH_MP_TAC CARD_DIFF THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `rooted_edge_reversal (es:(A#A)list) =
    graph_reverse_dart (rooted_edge_set (es:(A#A)list))`
  (LABEL_TAC "tree_reversal") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`;
      `es:(A#A)list`]
     ROOTED_EDGE_REVERSAL_EQ_GRAPH_REVERSE_DART) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(permutation_orbits (r:(A#A)->A#A) (graph_darts E)) =
    CARD(V:A->bool)`
  (LABEL_TAC "rotation_count") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
     GRAPH_ROTATION_ORBIT_COUNT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(permutation_orbits (r:(A#A)->A#A) (graph_darts E)) =
    CARD(permutation_orbits
      (graph_reverse_dart (rooted_edge_set (es:(A#A)list)) o r)
      (graph_darts E)) +
    LENGTH(es:(A#A)list)`
  (LABEL_TAC "tree_orbit_count") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `es:(A#A)list`]
     ROOTED_EDGE_REVERSAL_ORBIT_COUNT) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "tree_reversal" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(permutation_orbits
      (graph_reverse_dart E o (r:(A#A)->A#A))
      (graph_darts E)) <=
    CARD(permutation_orbits
      (graph_reverse_dart (rooted_edge_set (es:(A#A)list)) o r)
      (graph_darts E)) +
    CARD((E:(A->bool)->bool) DIFF
         rooted_edge_set (es:(A#A)list))`
  (LABEL_TAC "extension_bound") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `rooted_edge_set (es:(A#A)list)`]
     GRAPH_REVERSE_DART_EXTENSION_ORBIT_BOUND) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_ARITH_TAC);;

let INVOLUTION_ITER_SWAP_COMPOSITION = prove
 (`!p q:A->A.
        (!x. q(q x) = x)
        ==> !n x.
              q(ITER n (p o q) x) =
              ITER n (q o p) (q x)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "involution") THEN
  INDUCT_TAC THEN X_GEN_TAC `x:A` THEN
  ASM_REWRITE_TAC[ITER; o_THM]);;

let INVOLUTION_IMAGE_PERMUTATION_ORBIT = prove
 (`!p q:A->A.
        (!z. q(q z) = z)
        ==> !x.
              IMAGE q (permutation_orbit (p o q) x) =
              permutation_orbit (q o p) (q x)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "involution") THEN
  X_GEN_TAC `x:A` THEN REWRITE_TAC[EXTENSION] THEN
  X_GEN_TAC `y:A` THEN
  REWRITE_TAC[IN_IMAGE; IN_PERMUTATION_ORBIT] THEN EQ_TAC THENL
   [INTRO_TAC "@z. image (@n. step)" THEN
    EXISTS_TAC `n:num` THEN
    SUBGOAL_THEN
    `q(ITER n ((p:A->A) o q) x) =
      ITER n (q o p) (q x)`
    (LABEL_TAC "conjugate") THENL
     [USE_THEN "involution" (fun involution_th ->
       ACCEPT_TAC(SPECL [`n:num`; `x:A`]
        (MATCH_MP
         (SPECL [`p:A->A`; `q:A->A`]
          INVOLUTION_ITER_SWAP_COMPOSITION)
         involution_th)));
      REMOVE_THEN "conjugate" (fun conjugate_th ->
       USE_THEN "step" (fun step_th ->
        USE_THEN "image" (fun image_th ->
         ACCEPT_TAC
          (TRANS (SYM conjugate_th)
           (TRANS (AP_TERM `q:A->A` step_th) (SYM image_th))))))];
    DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THEN
    EXISTS_TAC `ITER n ((p:A->A) o q) x` THEN CONJ_TAC THENL
     [SUBGOAL_THEN
       `q(ITER n ((p:A->A) o q) x) =
        ITER n (q o p) (q x)`
      (LABEL_TAC "conjugate") THENL
       [USE_THEN "involution" (fun involution_th ->
         ACCEPT_TAC(SPECL [`n:num`; `x:A`]
          (MATCH_MP
           (SPECL [`p:A->A`; `q:A->A`]
            INVOLUTION_ITER_SWAP_COMPOSITION)
           involution_th)));
        REMOVE_THEN "conjugate" (fun conjugate_th ->
         USE_THEN "step" (fun step_th ->
          ACCEPT_TAC(SYM(TRANS conjugate_th step_th))))];
      EXISTS_TAC `n:num` THEN REFL_TAC]]);;

let INVOLUTION_IMAGE_PERMUTATION_ORBITS = prove
 (`!p q:A->A. !s:A->bool.
        q permutes (s:A->bool) /\
        (!z. q(q z) = z)
        ==> IMAGE (IMAGE q)
             (permutation_orbits (p o q) (s:A->bool)) =
            permutation_orbits (q o p) (s:A->bool)`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation involution" THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `c:A->bool` THEN EQ_TAC THENL
   [REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@a. image source" THEN
    USE_THEN "source" MP_TAC THEN
    REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
    INTRO_TAC "@x. member representation" THEN
    REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
    EXISTS_TAC `(q:A->A) (x:A)` THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`q:A->A`; `s:A->bool`; `x:A`]
       PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "image" SUBST1_TAC THEN
      USE_THEN "representation" SUBST1_TAC THEN
      USE_THEN "involution" (fun involution_th ->
       ACCEPT_TAC(SPEC `x:A`
        (MATCH_MP
         (SPECL [`p:A->A`; `q:A->A`]
          INVOLUTION_IMAGE_PERMUTATION_ORBIT)
         involution_th)))];
    REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
    INTRO_TAC "@y. member representation" THEN
    REWRITE_TAC[IN_IMAGE] THEN
    EXISTS_TAC
     `permutation_orbit ((p:A->A) o q) ((q:A->A) (y:A))` THEN
    CONJ_TAC THENL
     [USE_THEN "representation" SUBST1_TAC THEN
      CONV_TAC SYM_CONV THEN
      USE_THEN "involution" (fun involution_th ->
       MP_TAC(SPEC `(q:A->A) (y:A)`
        (MATCH_MP
         (SPECL [`p:A->A`; `q:A->A`]
          INVOLUTION_IMAGE_PERMUTATION_ORBIT)
         involution_th))) THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
      EXISTS_TAC `(q:A->A) (y:A)` THEN CONJ_TAC THENL
       [MP_TAC(ISPECL [`q:A->A`; `s:A->bool`; `y:A`]
         PERMUTES_IN_IMAGE) THEN
        ASM_REWRITE_TAC[];
        REFL_TAC]]]);;

let INVOLUTION_IMAGE_INJECTIVE = prove
 (`!q:A->A.
        (!z. q(q z) = z)
        ==> !s t:A->bool.
              IMAGE q (s:A->bool) = IMAGE q (t:A->bool)
              ==> s = t`,
  GEN_TAC THEN DISCH_THEN(LABEL_TAC "involution") THEN
  SUBGOAL_THEN
   `!x y:A. (q:A->A) x = q y ==> x = y`
  (LABEL_TAC "injective") THENL
   [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    DISCH_THEN(LABEL_TAC "same") THEN
    USE_THEN "involution" (fun involution_th ->
     USE_THEN "same" (fun same_th ->
      ACCEPT_TAC
       (TRANS (SYM(SPEC `x:A` involution_th))
        (TRANS (AP_TERM `q:A->A` same_th)
         (SPEC `y:A` involution_th)))));
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`s:A->bool`; `t:A->bool`] THEN
  DISCH_THEN(LABEL_TAC "same_image") THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `z:A` THEN EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "member") THEN
    SUBGOAL_THEN `(q:A->A) (z:A) IN IMAGE q t`
    (LABEL_TAC "image_member") THENL
     [USE_THEN "same_image" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[IN_IMAGE] THEN
      EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "image_member" MP_TAC THEN
    REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@w. image member_t" THEN
    SUBGOAL_THEN `(z:A) = w` SUBST1_TAC THENL
     [USE_THEN "injective" (MATCH_MP_TAC o SPECL [`z:A`; `w:A`]) THEN
      USE_THEN "image" ACCEPT_TAC;
      USE_THEN "member_t" ACCEPT_TAC];
    DISCH_THEN(LABEL_TAC "member") THEN
    SUBGOAL_THEN `(q:A->A) (z:A) IN IMAGE q s`
    (LABEL_TAC "image_member") THENL
     [USE_THEN "same_image" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_IMAGE] THEN
      EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "image_member" MP_TAC THEN
    REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@w. image member_s" THEN
    SUBGOAL_THEN `(z:A) = w` SUBST1_TAC THENL
     [USE_THEN "injective" (MATCH_MP_TAC o SPECL [`z:A`; `w:A`]) THEN
      USE_THEN "image" ACCEPT_TAC;
      USE_THEN "member_s" ACCEPT_TAC]]);;

let CARD_PERMUTATION_ORBITS_SWAP_COMPOSITION = prove
 (`!p q:A->A. !s:A->bool.
        FINITE(s:A->bool) /\
        q permutes (s:A->bool) /\
        (!z. q(q z) = z)
        ==> CARD(permutation_orbits (p o q) (s:A->bool)) =
            CARD(permutation_orbits (q o p) (s:A->bool))`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutation involution" THEN
  SUBGOAL_THEN
   `IMAGE (IMAGE (q:A->A))
      (permutation_orbits ((p:A->A) o q) s) =
    permutation_orbits (q o p) s`
  (LABEL_TAC "orbit_image") THENL
   [MATCH_MP_TAC(ISPECL
     [`p:A->A`; `q:A->A`; `s:A->bool`]
     INVOLUTION_IMAGE_PERMUTATION_ORBITS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "orbit_image" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
  CONV_TAC SYM_CONV THEN MATCH_MP_TAC CARD_IMAGE_INJ THEN
  CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`a:A->bool`; `b:A->bool`] THEN
    INTRO_TAC "a_orbit b_orbit same_image" THEN
    USE_THEN "involution" (fun involution_th ->
     MATCH_MP_TAC(SPECL [`a:A->bool`; `b:A->bool`]
      (MATCH_MP
       (SPEC `q:A->A` INVOLUTION_IMAGE_INJECTIVE)
       involution_th))) THEN
    USE_THEN "same_image" ACCEPT_TAC;
    MATCH_MP_TAC FINITE_PERMUTATION_ORBITS THEN
    USE_THEN "finite" ACCEPT_TAC]);;

let GRAPH_FACE_REVERSE_ROTATION_ORBIT_COUNT = prove
 (`!V E r:(A#A)->A#A.
        finite_simple_graph V E /\
        graph_rotation E r
        ==> CARD(permutation_orbits
             (graph_face_successor E r) (graph_darts E)) =
