  REWRITE_TAC[graph_face_successor] THEN
  MATCH_MP_TAC(ISPECL
   [`r:(A#A)->A#A`; `graph_reverse_dart (E:(A->bool)->bool)`;
    `graph_darts E:A#A->bool`]
   CARD_PERMUTATION_ORBITS_SWAP_COMPOSITION) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    MATCH_ACCEPT_TAC GRAPH_REVERSE_DART_PERMUTES;
    MATCH_ACCEPT_TAC GRAPH_REVERSE_DART_INVOLUTION]);;

let GRAPH_REACHABLE_EMPTY = prove
 (`!u v:A.
        graph_reachable ({}:(A->bool)->bool) u v <=> u = v`,
  REPEAT GEN_TAC THEN REWRITE_TAC[graph_reachable] THEN
  ONCE_REWRITE_TAC[RTC_CASES_R] THEN
  REWRITE_TAC[NOT_IN_EMPTY]);;

let CONNECTED_GRAPH_MAP_FACES_EULER_BOUND = prove
 (`!V E r:(A#A)->A#A.
        finite_simple_graph V E /\
        connected_graph V E /\
        graph_rotation E r
        ==> CARD V + CARD(graph_map_faces V E r) <= CARD E + 2`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected rotation" THEN
  ASM_CASES_TAC `E:(A->bool)->bool = {}` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    ASM_CASES_TAC `V:A->bool = {}` THENL
     [FIRST_X_ASSUM SUBST_ALL_TAC THEN
      SUBGOAL_THEN
       `graph_darts ({}:(A->bool)->bool) = ({}:(A#A)->bool)`
      (LABEL_TAC "no_darts") THENL
       [REWRITE_TAC[graph_darts; EXTENSION; IN_ELIM_THM;
                    NOT_IN_EMPTY];
        ASM_REWRITE_TAC[graph_map_faces; graph_faces;
                        IMAGE_CLAUSES; CARD_CLAUSES] THEN ARITH_TAC];
      FIRST_X_ASSUM(LABEL_TAC "vertices_nonempty")] THEN
    SUBGOAL_THEN `?u:A. u IN V`
    (X_CHOOSE_THEN `u:A` (LABEL_TAC "vertex")) THENL
     [USE_THEN "vertices_nonempty" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(V:A->bool) = {u}`
    (LABEL_TAC "singleton_vertices") THENL
     [REWRITE_TAC[EXTENSION; IN_SING] THEN X_GEN_TAC `v:A` THEN
      EQ_TAC THENL
       [DISCH_THEN(LABEL_TAC "v_vertex") THEN
        USE_THEN "connected" MP_TAC THEN
        REWRITE_TAC[connected_graph] THEN
        DISCH_THEN(MP_TAC o SPECL [`v:A`; `u:A`]) THEN
        ASM_REWRITE_TAC[GRAPH_REACHABLE_EMPTY];
        DISCH_THEN SUBST1_TAC THEN
        USE_THEN "vertex" ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "singleton_vertices" SUBST1_TAC THEN
    REWRITE_TAC[graph_map_faces; CARD_SING; NOT_INSERT_EMPTY;
                CARD_CLAUSES] THEN ARITH_TAC;
    FIRST_X_ASSUM(LABEL_TAC "edges_nonempty")] THEN
  SUBGOAL_THEN
   `CARD(permutation_orbits
      (graph_face_successor (E:(A->bool)->bool) r)
      (graph_darts E)) =
    CARD(permutation_orbits
      (graph_reverse_dart E o (r:(A#A)->A#A))
      (graph_darts E))`
  (LABEL_TAC "face_conjugacy") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
     GRAPH_FACE_REVERSE_ROTATION_ORBIT_COUNT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(V:A->bool) +
    CARD(permutation_orbits
      (graph_reverse_dart E o (r:(A#A)->A#A))
      (graph_darts E)) <=
    CARD(E:(A->bool)->bool) + 2`
  (LABEL_TAC "reverse_bound") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
     CONNECTED_GRAPH_REVERSE_ROTATION_EULER_BOUND) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[graph_map_faces] THEN
  ASM_REWRITE_TAC[GRAPH_FACES_AS_PERMUTATION_ORBITS] THEN
  ASM_ARITH_TAC);;

let GRAPH_EULER_FORMULA_EQ_SATURATES_BOUND = prove
 (`!V E r:(A#A)->A#A.
        finite_simple_graph V E /\
        connected_graph V E /\
        graph_rotation E r
        ==> (graph_euler_formula V E r <=>
             CARD E + 2 <= CARD V + CARD(graph_map_faces V E r))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected rotation" THEN
  SUBGOAL_THEN
   `CARD(V:A->bool) + CARD(graph_map_faces V E r) <=
    CARD(E:(A->bool)->bool) + 2`
  (LABEL_TAC "bound") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
     CONNECTED_GRAPH_MAP_FACES_EULER_BOUND) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[graph_euler_formula] THEN ASM_ARITH_TAC]);;

let EULER_PLANAR_ROTATION_MAXIMIZES_FACES = prove
 (`!V E r r':(A#A)->A#A.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        graph_rotation E r'
        ==> CARD(graph_map_faces V E r') <=
            CARD(graph_map_faces V E r)`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler connected rotation'" THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation; graph_euler_formula] THEN
  INTRO_TAC "graph rotation formula" THEN
  SUBGOAL_THEN
   `CARD(V:A->bool) + CARD(graph_map_faces V E r') <=
    CARD(E:(A->bool)->bool) + 2`
  (LABEL_TAC "bound") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r':(A#A)->A#A`]
     CONNECTED_GRAPH_MAP_FACES_EULER_BOUND) THEN
    ASM_REWRITE_TAC[];
    ASM_ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* Inserting edges into graph rotations.                                     *)
(* ------------------------------------------------------------------------- *)

let GRAPH_DARTS_INSERT_EDGE = prove
 (`!E u v:A.
        graph_darts ({u,v} INSERT E) =
        (u,v) INSERT (v,u) INSERT graph_darts E`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[EXTENSION; FORALL_PAIR_THM; graph_darts; IN_ELIM_THM;
              IN_INSERT; DART_EDGE_PAIR; PAIR_EQ] THEN
  SET_TAC[]);;

let OUTGOING_DARTS_INSERT_EDGE_LEFT = prove
 (`!E u v:A.
        ~(u = v)
        ==> outgoing_darts ({u,v} INSERT E) u =
            (u,v) INSERT outgoing_darts E u`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "distinct") THEN
  REWRITE_TAC[EXTENSION; FORALL_PAIR_THM; IN_OUTGOING_DARTS;
              IN_GRAPH_DARTS; IN_INSERT; DART_EDGE_PAIR; FST;
              PAIR_EQ] THEN
  ASM SET_TAC[]);;

let OUTGOING_DARTS_INSERT_EDGE_RIGHT = prove
 (`!E u v:A.
        ~(u = v)
        ==> outgoing_darts ({u,v} INSERT E) v =
            (v,u) INSERT outgoing_darts E v`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "distinct") THEN
  SUBGOAL_THEN `{u:A,v} = {v,u}` (LABEL_TAC "edge_symmetry") THENL
   [SET_TAC[];
    USE_THEN "edge_symmetry" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC OUTGOING_DARTS_INSERT_EDGE_LEFT THEN
    ASM_MESON_TAC[]]);;

let OUTGOING_DARTS_FRESH_VERTEX = prove
 (`!V E v:A.
        finite_simple_graph V E /\
        ~(v IN V)
        ==> outgoing_darts E v = {}`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph fresh" THEN
  REWRITE_TAC[EXTENSION; NOT_IN_EMPTY] THEN
  X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "outgoing") THEN
  USE_THEN "outgoing" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "dart tail" THEN
  USE_THEN "fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
  USE_THEN "tail" (SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `d:A#A`]
   FINITE_SIMPLE_GRAPH_DART_FST) THEN
  ASM_REWRITE_TAC[]);;

let FINITE_SIMPLE_GRAPH_INSERT_PENDANT = prove
 (`!V E u v:A.
        finite_simple_graph V E /\
        u IN V /\
        ~(v IN V)
        ==> finite_simple_graph
             (v INSERT V) ({u,v} INSERT E)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph vertex fresh" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `{u:A}`]
   FINITE_SIMPLE_GRAPH_INSERT_VERTEX_STAR) THEN
  ASM_REWRITE_TAC[SING_SUBSET; IMAGE_CLAUSES;
                  SET_RULE `{v:A,u} = {u,v}`;
                  SET_RULE `{{u:A,v}} UNION E = {u,v} INSERT E`]);;

let GRAPH_ROTATION_IMAGE_OUTGOING_DARTS = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !u:A.
        graph_rotation E r
        ==> IMAGE r (outgoing_darts E u) = outgoing_darts E u`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "rotation") THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; FORALL_IN_IMAGE] THEN
    X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "outgoing") THEN
    USE_THEN "outgoing" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN
    INTRO_TAC "dart tail" THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_ROTATION_IN THEN ASM_REWRITE_TAC[];
      TRANS_TAC EQ_TRANS `FST(d:A#A)` THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
         GRAPH_ROTATION_TAIL) THEN
        ASM_REWRITE_TAC[];
        USE_THEN "tail" ACCEPT_TAC]];
    REWRITE_TAC[SUBSET] THEN X_GEN_TAC `d:A#A` THEN
    DISCH_THEN(LABEL_TAC "outgoing") THEN
    USE_THEN "outgoing" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN
    INTRO_TAC "dart tail" THEN
    SUBGOAL_THEN
     `IMAGE (r:(A#A)->A#A) (graph_darts E) = graph_darts E`
    (LABEL_TAC "image_darts") THENL
     [MATCH_MP_TAC(ISPECL
       [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`]
       PERMUTES_IMAGE) THEN
      MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
      USE_THEN "rotation" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `?e:A#A. e IN graph_darts E /\ (r:(A#A)->A#A) e = d`
    (X_CHOOSE_THEN `e:A#A`
     (CONJUNCTS_THEN2 (LABEL_TAC "e_dart")
      (LABEL_TAC "image"))) THENL
     [USE_THEN "image_darts" (fun image_th ->
        MP_TAC(AP_TERM
         `\s:(A#A)->bool. (d:A#A) IN s`
         image_th)) THEN
      REWRITE_TAC[IN_IMAGE] THEN
      ASM_MESON_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `e:A#A` THEN
    CONJ_TAC THENL
     [USE_THEN "image" (ACCEPT_TAC o SYM);
      REWRITE_TAC[IN_OUTGOING_DARTS] THEN
      ASM_REWRITE_TAC[] THEN
      TRANS_TAC EQ_TRANS `FST((r:(A#A)->A#A) e)` THEN
      CONJ_TAC THENL
       [CONV_TAC SYM_CONV THEN
        MATCH_MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `e:A#A`]
         GRAPH_ROTATION_TAIL) THEN
        ASM_REWRITE_TAC[];
        USE_THEN "image" SUBST1_TAC THEN
        USE_THEN "tail" ACCEPT_TAC]]]);;

let GRAPH_ROTATION_INSERT_EDGE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v:A. !a b:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        ~(u = v) /\
        ~({u,v} IN E) /\
        a IN outgoing_darts E u /\
        b IN outgoing_darts E v
        ==> graph_rotation
             ({u,v} INSERT E)
             (permutation_insert
               (permutation_insert r (u,v) a)
               (v,u) b)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation distinct new_edge a_anchor b_anchor" THEN
  USE_THEN "a_anchor" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "a_dart a_tail" THEN
  USE_THEN "b_anchor" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "b_dart b_tail" THEN
  SUBGOAL_THEN
   `~(((u:A),(v:A)) IN graph_darts E) /\
    ~(((v:A),(u:A)) IN graph_darts E)`
  (CONJUNCTS_THEN2 (LABEL_TAC "forward_fresh")
    (LABEL_TAC "reverse_fresh")) THENL
   [ASM_REWRITE_TAC[IN_GRAPH_DARTS;
                    SET_RULE `{v:A,u} = {u,v}`];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((v:A,u:A) = (u,v))`
  (LABEL_TAC "darts_distinct") THENL
   [REWRITE_TAC[PAIR_EQ] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(graph_darts (E:(A->bool)->bool))`
  (LABEL_TAC "finite_darts") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "rotation" MP_TAC THEN
  REWRITE_TAC[graph_rotation] THEN
  INTRO_TAC
   "old_permutation old_tail old_transitive" THEN
  SUBGOAL_THEN
   `permutation_insert (r:(A#A)->A#A) (u,v) a
      permutes ((u,v) INSERT graph_darts E) /\
    (!d. d IN (u,v) INSERT graph_darts E
         ==> FST(permutation_insert r (u,v) a d) = FST d) /\
    (!d d'. d IN (u,v) INSERT graph_darts E /\
             d' IN (u,v) INSERT graph_darts E /\
             FST d = FST d'
             ==> ?n. ITER n (permutation_insert r (u,v) a) d = d')`
  (CONJUNCTS_THEN2 (LABEL_TAC "first_permutation")
    (CONJUNCTS_THEN2 (LABEL_TAC "first_tail")
      (LABEL_TAC "first_transitive"))) THENL
   [MATCH_MP_TAC(ISPECL
     [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`;
      `(u:A,v:A)`; `a:A#A`; `FST:A#A->A`]
     PERMUTATION_INSERT_PRESERVES_KEY_TRANSITIVE) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "finite_darts" ACCEPT_TAC;
      USE_THEN "old_permutation" ACCEPT_TAC;
      USE_THEN "a_dart" ACCEPT_TAC;
      USE_THEN "forward_fresh" ACCEPT_TAC;
      ASM_REWRITE_TAC[FST];
      USE_THEN "old_tail" ACCEPT_TAC;
      USE_THEN "old_transitive" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_insert
      (permutation_insert (r:(A#A)->A#A) (u,v) a)
      (v,u) b
      permutes ((v,u) INSERT (u,v) INSERT graph_darts E) /\
    (!d. d IN (v,u) INSERT (u,v) INSERT graph_darts E
         ==> FST
              (permutation_insert
                (permutation_insert r (u,v) a)
                (v,u) b d) =
             FST d) /\
    (!d d'. d IN (v,u) INSERT (u,v) INSERT graph_darts E /\
             d' IN (v,u) INSERT (u,v) INSERT graph_darts E /\
             FST d = FST d'
             ==> ?n.
                   ITER n
                    (permutation_insert
                      (permutation_insert r (u,v) a)
                      (v,u) b) d =
                   d')`
  (CONJUNCTS_THEN2 (LABEL_TAC "second_permutation")
    (CONJUNCTS_THEN2 (LABEL_TAC "second_tail")
      (LABEL_TAC "second_transitive"))) THENL
   [MATCH_MP_TAC(ISPECL
     [`permutation_insert (r:(A#A)->A#A) (u,v) a`;
      `(u:A,v:A) INSERT graph_darts E`;
      `(v:A,u:A)`; `b:A#A`; `FST:A#A->A`]
     PERMUTATION_INSERT_PRESERVES_KEY_TRANSITIVE) THEN
    REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[FINITE_INSERT];
      USE_THEN "first_permutation" ACCEPT_TAC;
      REWRITE_TAC[IN_INSERT] THEN
      DISJ2_TAC THEN USE_THEN "b_dart" ACCEPT_TAC;
      REWRITE_TAC[IN_INSERT] THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[FST];
      USE_THEN "first_tail" ACCEPT_TAC;
      USE_THEN "first_transitive" ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[graph_rotation; GRAPH_DARTS_INSERT_EDGE] THEN
  SUBGOAL_THEN
   `((u:A,v:A) INSERT (v,u) INSERT graph_darts E) =
    (v,u) INSERT (u,v) INSERT graph_darts E`
  SUBST1_TAC THENL
   [SET_TAC[];
    ASM_REWRITE_TAC[]]);;

let GRAPH_FACE_SUCCESSOR_INSERT_EDGE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v:A. !a b:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        ~(u = v) /\
        ~({u,v} IN E) /\
        a IN outgoing_darts E u /\
        b IN outgoing_darts E v
        ==> graph_face_successor
             ({u,v} INSERT E)
             (permutation_insert
               (permutation_insert r (u,v) a)
               (v,u) b) =
            swap(r b,r a) o
            permutation_insert
             (permutation_insert
               (graph_face_successor E r)
               (u,v) (reverse_dart a))
             (v,u) (reverse_dart b)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation distinct new_edge a_anchor b_anchor" THEN
  USE_THEN "a_anchor" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "a_dart a_tail" THEN
  USE_THEN "b_anchor" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "b_dart b_tail" THEN
  SUBGOAL_THEN `~((a:A#A) = b)` (LABEL_TAC "anchors_distinct") THENL
   [DISCH_THEN(LABEL_TAC "anchors_equal") THEN
    USE_THEN "distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
    TRANS_TAC EQ_TRANS `FST(a:A#A)` THEN
    CONJ_TAC THENL
     [USE_THEN "a_tail" (ACCEPT_TAC o SYM);
      USE_THEN "anchors_equal" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "b_tail" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((u:A),(v:A)) IN graph_darts E) /\
    ~(((v:A),(u:A)) IN graph_darts E)`
  (CONJUNCTS_THEN2 (LABEL_TAC "forward_fresh")
    (LABEL_TAC "reverse_fresh")) THENL
   [ASM_REWRITE_TAC[IN_GRAPH_DARTS;
                    SET_RULE `{v:A,u} = {u,v}`];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A,v:A) = (v,u))`
  (LABEL_TAC "darts_distinct") THENL
   [REWRITE_TAC[PAIR_EQ] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:(A#A)->A#A) permutes graph_darts E`
  (LABEL_TAC "rotation_permutation") THENL
   [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) a IN graph_darts E /\
    r b IN graph_darts E`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_image_dart")
    (LABEL_TAC "b_image_dart")) THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`; `a:A#A`]
       PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL
       [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`; `b:A#A`]
       PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((r:(A#A)->A#A) b = r a)`
  (LABEL_TAC "images_distinct") THENL
   [MP_TAC(SPECL [`b:A#A`; `a:A#A`]
     (MATCH_MP
      (ISPECL
       [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`]
       PERMUTES_INJECTIVE)
      (ASSUME
       `(r:(A#A)->A#A) permutes graph_darts E`))) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((r:(A#A)->A#A) a = (v,u)) /\
    ~(r b = (u,v)) /\
    ~(r b = (v,u))`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_image_not_reverse")
    (CONJUNCTS_THEN2 (LABEL_TAC "b_image_not_forward")
      (LABEL_TAC "b_image_not_reverse"))) THENL
   [REPEAT CONJ_TAC THEN DISCH_THEN(LABEL_TAC "equal") THENL
     [USE_THEN "reverse_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "a_image_dart" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "forward_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "b_image_dart" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "reverse_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "b_image_dart" (ACCEPT_TAC o REWRITE_RULE[th]))];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(a:A#A) IN graph_darts E /\
    reverse_dart(b:A#A) IN graph_darts E`
  (CONJUNCTS_THEN2 (LABEL_TAC "reverse_a_dart")
    (LABEL_TAC "reverse_b_dart")) THENL
   [ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (reverse_dart(a:A#A)) = r a /\
    graph_face_successor E r (reverse_dart(b:A#A)) = r b`
  (CONJUNCTS_THEN2 (LABEL_TAC "face_a_image")
    (LABEL_TAC "face_b_image")) THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `reverse_dart(a:A#A)`]
       GRAPH_FACE_SUCCESSOR_IN) THEN
      ASM_REWRITE_TAC[REVERSE_DART_INVOLUTION];
      MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `reverse_dart(b:A#A)`]
       GRAPH_FACE_SUCCESSOR_IN) THEN
      ASM_REWRITE_TAC[REVERSE_DART_INVOLUTION]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) o swap((u,v),(v,u)) =
    swap((u,v),(v,u)) o r`
  (LABEL_TAC "rotation_commutes") THENL
   [MATCH_MP_TAC(ISPECL
     [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`;
      `(u:A,v:A)`; `(v:A,u:A)`]
     PERMUTES_COMMUTES_SWAP_OUTSIDE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `swap((u:A,v:A),(r:(A#A)->A#A) a) o
      swap((u,v),(v,u)) =
    swap((v,u),r a) o swap((u,v),r a)`
  (LABEL_TAC "first_swap") THENL
   [GEN_REWRITE_TAC (RAND_CONV o LAND_CONV) [SWAP_SYM] THEN
    MATCH_MP_TAC(ISPECL
     [`(u:A,v:A)`; `(r:(A#A)->A#A) a`; `(v:A,u:A)`]
     SWAP_COMMON) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `swap((v:A,u:A),(r:(A#A)->A#A) b) o
      swap((v,u),r a) =
    swap(r b,r a) o swap((v,u),r b)`
  (LABEL_TAC "second_swap") THENL
   [MATCH_MP_TAC(ISPECL
     [`(v:A,u:A)`; `(r:(A#A)->A#A) b`; `(r:(A#A)->A#A) a`]
     SWAP_COMMON) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(swap((v:A,u:A),(r:(A#A)->A#A) b) o
      swap((u,v),r a)) o
     (r o
      (swap((u,v),(v,u)) o graph_reverse_dart E)) =
    swap(r b,r a) o
     (swap((v,u),r b) o
      (swap((u,v),r a) o
       (r o graph_reverse_dart E)))`
  (LABEL_TAC "algebra") THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM] THEN X_GEN_TAC `d:A#A` THEN
    SUBGOAL_THEN
     `(r:(A#A)->A#A)
       (swap((u,v),(v,u)) (graph_reverse_dart E d)) =
      swap((u,v),(v,u)) (r(graph_reverse_dart E d))`
    SUBST1_TAC THENL
     [USE_THEN "rotation_commutes" (fun th ->
       MP_TAC(AP_THM th `graph_reverse_dart E (d:A#A)`)) THEN
      REWRITE_TAC[o_THM];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `swap((u:A,v:A),(r:(A#A)->A#A) a)
       (swap((u,v),(v,u)) (r(graph_reverse_dart E d))) =
      swap((v,u),r a)
       (swap((u,v),r a) (r(graph_reverse_dart E d)))`
    SUBST1_TAC THENL
     [USE_THEN "first_swap" (fun th ->
       MP_TAC(AP_THM th
        `(r:(A#A)->A#A) (graph_reverse_dart E d)`)) THEN
      REWRITE_TAC[o_THM];
      USE_THEN "second_swap" (fun th ->
       MP_TAC(AP_THM th
        `swap((u:A,v:A),r a)
          ((r:(A#A)->A#A) (graph_reverse_dart E d))`)) THEN
      REWRITE_TAC[o_THM]];
    ALL_TAC] THEN
  REWRITE_TAC[graph_face_successor; permutation_insert; o_THM;
              REVERSE_DART_INVOLUTION] THEN
  USE_THEN "face_a_image"
   (fun th ->
     REWRITE_TAC[REWRITE_RULE[graph_face_successor; o_THM] th]) THEN
  USE_THEN "face_b_image"
   (fun th ->
     REWRITE_TAC[REWRITE_RULE[graph_face_successor; o_THM] th]) THEN
  ASM_SIMP_TAC[SWAP_OTHER] THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `u:A`; `v:A`]
   GRAPH_REVERSE_DART_INSERT_EDGE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[o_ASSOC] THEN
  USE_THEN "algebra"
   (ACCEPT_TAC o REWRITE_RULE[o_ASSOC]));;

let CARD_GRAPH_FACES_INSERT_EDGE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v:A. !a b:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        ~(u = v) /\
        ~({u,v} IN E) /\
        a IN outgoing_darts E u /\
        b IN outgoing_darts E v /\
        reverse_dart b IN graph_face E r (reverse_dart a)
        ==> CARD
             (graph_faces
               ({u,v} INSERT E)
               (permutation_insert
                 (permutation_insert r (u,v) a)
                 (v,u) b)) =
            CARD(graph_faces E r) + 1`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph rotation distinct new_edge a_anchor b_anchor cofacial" THEN
  USE_THEN "a_anchor" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "a_dart a_tail" THEN
  USE_THEN "b_anchor" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "b_dart b_tail" THEN
  SUBGOAL_THEN `~((a:A#A) = b)` (LABEL_TAC "anchors_distinct") THENL
   [DISCH_THEN(LABEL_TAC "anchors_equal") THEN
    USE_THEN "distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
    TRANS_TAC EQ_TRANS `FST(a:A#A)` THEN
    CONJ_TAC THENL
     [USE_THEN "a_tail" (ACCEPT_TAC o SYM);
      USE_THEN "anchors_equal" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "b_tail" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((u:A),(v:A)) IN graph_darts E) /\
    ~(((v:A),(u:A)) IN graph_darts E) /\
    ~((u:A,v:A) = (v,u))`
  (CONJUNCTS_THEN2 (LABEL_TAC "forward_fresh")
    (CONJUNCTS_THEN2 (LABEL_TAC "reverse_fresh")
      (LABEL_TAC "darts_distinct"))) THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[IN_GRAPH_DARTS];
      ASM_REWRITE_TAC[IN_GRAPH_DARTS;
                      SET_RULE `{v:A,u} = {u,v}`];
      REWRITE_TAC[PAIR_EQ] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(graph_darts (E:(A->bool)->bool))`
  (LABEL_TAC "finite_darts") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  ABBREV_TAC
   `g:(A#A)->A#A = graph_face_successor E r` THEN
  ABBREV_TAC
   `g1:(A#A)->A#A =
      permutation_insert g (u,v) (reverse_dart a)` THEN
  ABBREV_TAC
   `g2:(A#A)->A#A =
      permutation_insert g1 (v,u) (reverse_dart b)` THEN
  SUBGOAL_THEN `(g:(A#A)->A#A) permutes graph_darts E`
  (LABEL_TAC "face_permutation") THENL
   [EXPAND_TAC "g" THEN MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(a:A#A) IN graph_darts E /\
    reverse_dart(b:A#A) IN graph_darts E`
  (CONJUNCTS_THEN2 (LABEL_TAC "reverse_a_dart")
    (LABEL_TAC "reverse_b_dart")) THENL
   [ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(b:A#A) IN
    permutation_orbit (g:(A#A)->A#A) (reverse_dart a)`
  (LABEL_TAC "same_old_face") THENL
   [EXPAND_TAC "g" THEN
    USE_THEN "cofacial" MP_TAC THEN
    REWRITE_TAC[GRAPH_FACE_AS_PERMUTATION_ORBIT];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(g:(A#A)->A#A) (reverse_dart a) = r a /\
    g (reverse_dart b) = r b`
  (CONJUNCTS_THEN2 (LABEL_TAC "face_a_image")
    (LABEL_TAC "face_b_image")) THENL
   [EXPAND_TAC "g" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `reverse_dart(a:A#A)`]
       GRAPH_FACE_SUCCESSOR_IN) THEN
      ASM_REWRITE_TAC[REVERSE_DART_INVOLUTION];
      MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `reverse_dart(b:A#A)`]
       GRAPH_FACE_SUCCESSOR_IN) THEN
      ASM_REWRITE_TAC[REVERSE_DART_INVOLUTION]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) a IN graph_darts E /\
    r b IN graph_darts E /\
    ~(r b = r a)`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_image_dart")
    (CONJUNCTS_THEN2 (LABEL_TAC "b_image_dart")
      (LABEL_TAC "images_distinct"))) THENL
   [SUBGOAL_THEN `(r:(A#A)->A#A) permutes graph_darts E`
    (LABEL_TAC "rotation_permutation") THENL
     [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
      USE_THEN "rotation" ACCEPT_TAC;
      ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`; `a:A#A`]
       PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL
       [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`; `b:A#A`]
       PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`b:A#A`; `a:A#A`]
       (MATCH_MP
        (ISPECL
         [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`]
         PERMUTES_INJECTIVE)
        (ASSUME
         `(r:(A#A)->A#A) permutes graph_darts E`))) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(g1:(A#A)->A#A) permutes
      ((u,v) INSERT graph_darts E)`
  (LABEL_TAC "first_permutation") THENL
   [EXPAND_TAC "g1" THEN MATCH_MP_TAC PERMUTATION_INSERT_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(g2:(A#A)->A#A) permutes
      ((v,u) INSERT (u,v) INSERT graph_darts E)`
  (LABEL_TAC "second_permutation") THENL
   [EXPAND_TAC "g2" THEN MATCH_MP_TAC PERMUTATION_INSERT_PERMUTES THEN
    ASM_REWRITE_TAC[IN_INSERT];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD
     (permutation_orbits
       (g2:(A#A)->A#A)
       ((v,u) INSERT (u,v) INSERT graph_darts E)) =
    CARD(permutation_orbits g (graph_darts E))`
  (LABEL_TAC "insertions_preserve_count") THENL
   [TRANS_TAC EQ_TRANS
     `CARD
       (permutation_orbits
         (g1:(A#A)->A#A)
         ((u,v) INSERT graph_darts E))` THEN
    CONJ_TAC THENL
     [EXPAND_TAC "g2" THEN
      MATCH_MP_TAC PERMUTATION_INSERT_ORBIT_COUNT THEN
      ASM_REWRITE_TAC[FINITE_INSERT; IN_INSERT];
      EXPAND_TAC "g1" THEN
      MATCH_MP_TAC PERMUTATION_INSERT_ORBIT_COUNT THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) a IN
       permutation_orbit g (reverse_dart a) /\
    r b IN permutation_orbit g (reverse_dart a)`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_image_old_orbit")
    (LABEL_TAC "b_image_old_orbit")) THENL
   [CONJ_TAC THENL
     [USE_THEN "face_a_image" (SUBST1_TAC o SYM) THEN
      MATCH_MP_TAC PERMUTATION_ORBIT_SUCCESSOR THEN
      MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL;
      USE_THEN "face_b_image" (SUBST1_TAC o SYM) THEN
      MATCH_MP_TAC PERMUTATION_ORBIT_SUCCESSOR THEN
      USE_THEN "same_old_face" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!p q:A#A.
        p IN (u,v) INSERT
             permutation_orbit g (reverse_dart a) /\
        q IN (u,v) INSERT
             permutation_orbit g (reverse_dart a)
        ==> ?n. ITER n (g1:(A#A)->A#A) p = q`
  (LABEL_TAC "first_orbit_transitive") THENL
   [EXPAND_TAC "g1" THEN
    MATCH_MP_TAC(ISPECL
     [`g:(A#A)->A#A`; `graph_darts E:A#A->bool`;
      `reverse_dart(a:A#A)`; `(u:A,v:A)`;
      `reverse_dart(a:A#A)`]
     PERMUTATION_INSERT_ORBIT_TRANSITIVE) THEN
    ASM_REWRITE_TAC[PERMUTATION_ORBIT_REFL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(b:A#A) IN
      permutation_orbit (g1:(A#A)->A#A) (r a) /\
    r b IN permutation_orbit g1 (r a)`
  (CONJUNCTS_THEN2 (LABEL_TAC "b_anchor_first_orbit")
    (LABEL_TAC "b_image_first_orbit")) THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
      USE_THEN "first_orbit_transitive"
       (MATCH_MP_TAC o SPECL
         [`(r:(A#A)->A#A) a`;
          `reverse_dart(b:A#A)`]) THEN
      ASM_REWRITE_TAC[IN_INSERT];
      REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
      USE_THEN "first_orbit_transitive"
       (MATCH_MP_TAC o SPECL
         [`(r:(A#A)->A#A) a`;
          `(r:(A#A)->A#A) b`]) THEN
      ASM_REWRITE_TAC[IN_INSERT]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!p q:A#A.
        p IN (v,u) INSERT
             permutation_orbit g1
              ((r:(A#A)->A#A) (a:A#A)) /\
        q IN (v,u) INSERT
             permutation_orbit g1
              ((r:(A#A)->A#A) (a:A#A))
        ==> ?n. ITER n (g2:(A#A)->A#A) p = q`
  (LABEL_TAC "second_orbit_transitive") THENL
   [EXPAND_TAC "g2" THEN
    MATCH_MP_TAC(ISPECL
     [`g1:(A#A)->A#A`;
      `(u:A,v:A) INSERT graph_darts E`;
      `(r:(A#A)->A#A) (a:A#A)`; `(v:A,u:A)`;
      `reverse_dart(b:A#A)`]
     PERMUTATION_INSERT_ORBIT_TRANSITIVE) THEN
    REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[FINITE_INSERT];
      USE_THEN "first_permutation" ACCEPT_TAC;
      REWRITE_TAC[IN_INSERT] THEN ASM_REWRITE_TAC[];
      USE_THEN "b_anchor_first_orbit" ACCEPT_TAC;
      REWRITE_TAC[IN_INSERT] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) (b:A#A) IN
    permutation_orbit
     (g2:(A#A)->A#A) ((r:(A#A)->A#A) (a:A#A))`
  (LABEL_TAC "same_second_orbit") THENL
   [REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
    USE_THEN "second_orbit_transitive"
     (MATCH_MP_TAC o SPECL
       [`(r:(A#A)->A#A) (a:A#A)`;
        `(r:(A#A)->A#A) (b:A#A)`]) THEN
    ASM_REWRITE_TAC[IN_INSERT; PERMUTATION_ORBIT_REFL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit
      (g2:(A#A)->A#A) ((r:(A#A)->A#A) (b:A#A)) =
    permutation_orbit
      g2 ((r:(A#A)->A#A) (a:A#A))`
  (LABEL_TAC "same_orbit") THENL
   [MP_TAC(ISPECL
      [`g2:(A#A)->A#A`;
      `(v:A,u:A) INSERT (u,v) INSERT graph_darts E`;
      `(r:(A#A)->A#A) (a:A#A)`;
      `(r:(A#A)->A#A) (b:A#A)`]
     PERMUTATION_ORBIT_EQ) THEN
    ASM_REWRITE_TAC[FINITE_INSERT; IN_INSERT];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD
     (permutation_orbits
       (swap((r:(A#A)->A#A) (b:A#A),
             (r:(A#A)->A#A) (a:A#A)) o g2)
       ((v,u) INSERT (u,v) INSERT graph_darts E)) =
    CARD(permutation_orbits g (graph_darts E)) + 1`
  (LABEL_TAC "split_count") THENL
   [TRANS_TAC EQ_TRANS
     `CARD
       (permutation_orbits
         (g2:(A#A)->A#A)
         ((v,u) INSERT (u,v) INSERT graph_darts E)) + 1` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`g2:(A#A)->A#A`;
        `(v:A,u:A) INSERT (u,v) INSERT graph_darts E`;
        `(r:(A#A)->A#A) (b:A#A)`;
        `(r:(A#A)->A#A) (a:A#A)`]
       PERMUTATION_ORBITS_SWAP_SAME) THEN
      ASM_REWRITE_TAC[FINITE_INSERT; IN_INSERT];
      USE_THEN "insertions_preserve_count"
       (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  REWRITE_TAC[GRAPH_FACES_AS_PERMUTATION_ORBITS;
              GRAPH_DARTS_INSERT_EDGE] THEN
  SUBGOAL_THEN
   `((u:A,v:A) INSERT (v,u) INSERT graph_darts E) =
    (v,u) INSERT (u,v) INSERT graph_darts E`
  SUBST1_TAC THENL
   [SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor
      ({u:A,v} INSERT E)
      (permutation_insert
        (permutation_insert (r:(A#A)->A#A) (u,v) a)
        (v,u) b) =
    swap(r b,r a) o (g2:(A#A)->A#A)`
  SUBST1_TAC THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`; `a:A#A`; `b:A#A`]
     GRAPH_FACE_SUCCESSOR_INSERT_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(LABEL_TAC "successor") THEN
    EXPAND_TAC "g2" THEN EXPAND_TAC "g1" THEN EXPAND_TAC "g" THEN
    USE_THEN "successor" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor (E:(A->bool)->bool) (r:(A#A)->A#A) = g`
  SUBST1_TAC THENL
   [EXPAND_TAC "g" THEN REFL_TAC;
    USE_THEN "split_count" ACCEPT_TAC]);;

let GRAPH_EULER_FORMULA_INSERT_EDGE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v:A. !a b:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        graph_euler_formula V E r /\
        ~(u = v) /\
        ~({u,v} IN E) /\
        a IN outgoing_darts E u /\
        b IN outgoing_darts E v /\
        reverse_dart b IN graph_face E r (reverse_dart a)
        ==> graph_euler_formula
             V ({u,v} INSERT E)
             (permutation_insert
               (permutation_insert r (u,v) a)
               (v,u) b)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph rotation euler distinct new_edge a_anchor b_anchor cofacial" THEN
  SUBGOAL_THEN `FINITE(E:(A->bool)->bool)`
  (LABEL_TAC "finite_edges") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(E:(A->bool)->bool = {})`
  (LABEL_TAC "edges_nonempty") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "a_anchor" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS; graph_darts;
                IN_ELIM_THM; NOT_IN_EMPTY];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD
     (graph_faces
       ({u:A,v} INSERT E)
       (permutation_insert
         (permutation_insert r (u,v) a)
         (v,u) b)) =
    CARD(graph_faces E r) + 1`
  (LABEL_TAC "face_count") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`; `a:A#A`; `b:A#A`]
     CARD_GRAPH_FACES_INSERT_EDGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
  ASM_REWRITE_TAC[NOT_INSERT_EMPTY] THEN
  ASM_SIMP_TAC[CARD_CLAUSES] THEN
  ARITH_TAC);;

let EULER_PLANAR_ROTATION_INSERT_EDGE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v:A. !a b:A#A.
        euler_planar_rotation V E r /\
        u IN V /\
        v IN V /\
        ~(u = v) /\
        ~({u,v} IN E) /\
        a IN outgoing_darts E u /\
        b IN outgoing_darts E v /\
        reverse_dart b IN graph_face E r (reverse_dart a)
        ==> euler_planar_rotation
             V ({u,v} INSERT E)
             (permutation_insert
               (permutation_insert r (u,v) a)
               (v,u) b)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler_rotation u_vertex v_vertex distinct new_edge
    a_anchor b_anchor cofacial" THEN
  USE_THEN "euler_rotation" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph rotation euler" THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INSERT_EDGE THEN
    ASM_REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
    REWRITE_TAC[HAS_SIZE_CONV `{u:A,v} HAS_SIZE 2`] THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `v:A`] THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`; `a:A#A`; `b:A#A`]
     GRAPH_ROTATION_INSERT_EDGE) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`; `a:A#A`; `b:A#A`]
     GRAPH_EULER_FORMULA_INSERT_EDGE) THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_ROTATION_INSERT_PENDANT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
  !u v:A. !a:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        u IN V /\
        ~(v IN V) /\
        a IN outgoing_darts E u
        ==> graph_rotation
             ({u,v} INSERT E)
             (permutation_insert r (u,v) a)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation u_vertex v_fresh anchor" THEN
  SUBGOAL_THEN `~(u:A = v)` (LABEL_TAC "distinct") THENL
   [DISCH_THEN(LABEL_TAC "equal") THEN
    USE_THEN "v_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "equal" (fun th ->
      USE_THEN "u_vertex" (ACCEPT_TAC o REWRITE_RULE[th]));
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:A#A) IN graph_darts E /\ FST a = u`
  (CONJUNCTS_THEN2 (LABEL_TAC "anchor_dart")
    (LABEL_TAC "anchor_tail")) THENL
   [USE_THEN "anchor" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((u:A),(v:A)) IN graph_darts E) /\
    ~(((v:A),(u:A)) IN graph_darts E)`
  (CONJUNCTS_THEN2 (LABEL_TAC "new_forward")
    (LABEL_TAC "new_reverse")) THENL
   [CONJ_TAC THEN DISCH_THEN(LABEL_TAC "old_dart") THEN
    USE_THEN "v_fresh" (MATCH_MP_TAC o NOT_ELIM) THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `u:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(graph_darts (E:(A->bool)->bool))`
  (LABEL_TAC "finite_darts") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_insert (r:(A#A)->A#A) (u,v) a
    permutes ((u,v) INSERT graph_darts E)`
  (LABEL_TAC "inserted_permutation") THENL
   [MATCH_MP_TAC PERMUTATION_INSERT_PERMUTES THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[graph_rotation] THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[GRAPH_DARTS_INSERT_EDGE] THEN
    MATCH_MP_TAC PERMUTES_SUBSET THEN
    EXISTS_TAC `(u:A,v) INSERT graph_darts E` THEN
    ASM_REWRITE_TAC[] THEN SET_TAC[];
    X_GEN_TAC `d:A#A` THEN
    REWRITE_TAC[GRAPH_DARTS_INSERT_EDGE; IN_INSERT] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "forward")
      (DISJ_CASES_THEN2 (LABEL_TAC "reverse")
     (LABEL_TAC "old"))) THENL
     [USE_THEN "forward" SUBST1_TAC THEN
      MP_TAC(ISPECL
       [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`;
        `(u:A,v:A)`; `a:A#A`; `FST:A#A->A`]
       PERMUTATION_INSERT_PRESERVES_KEY) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
          USE_THEN "rotation" ACCEPT_TAC;
          USE_THEN "anchor_dart" ACCEPT_TAC;
          USE_THEN "new_forward" ACCEPT_TAC;
          ASM_REWRITE_TAC[FST];
          X_GEN_TAC `e:A#A` THEN DISCH_THEN(LABEL_TAC "e_dart") THEN
          MATCH_MP_TAC(ISPECL
           [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `e:A#A`]
           GRAPH_ROTATION_TAIL) THEN
          ASM_REWRITE_TAC[]];
        DISCH_THEN(MP_TAC o SPEC `(u:A,v:A)`) THEN
        REWRITE_TAC[IN_INSERT]];
      USE_THEN "reverse" SUBST1_TAC THEN
      SUBGOAL_THEN
       `permutation_insert (r:(A#A)->A#A) (u,v) a (v,u) = (v,u)`
      SUBST1_TAC THENL
       [USE_THEN "inserted_permutation"
         (MATCH_MP_TAC o CONJUNCT1 o REWRITE_RULE[permutes]) THEN
        ASM_REWRITE_TAC[IN_INSERT; PAIR_EQ];
        REWRITE_TAC[]];
      MP_TAC(ISPECL
       [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`;
        `(u:A,v:A)`; `a:A#A`; `FST:A#A->A`]
       PERMUTATION_INSERT_PRESERVES_KEY) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
          USE_THEN "rotation" ACCEPT_TAC;
          USE_THEN "anchor_dart" ACCEPT_TAC;
          USE_THEN "new_forward" ACCEPT_TAC;
          ASM_REWRITE_TAC[FST];
          X_GEN_TAC `e:A#A` THEN DISCH_THEN(LABEL_TAC "e_dart") THEN
          MATCH_MP_TAC(ISPECL
           [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `e:A#A`]
           GRAPH_ROTATION_TAIL) THEN
          ASM_REWRITE_TAC[]];
        DISCH_THEN(MP_TAC o SPEC `d:A#A`) THEN
        ASM_REWRITE_TAC[IN_INSERT]]];
    MAP_EVERY X_GEN_TAC [`d:A#A`; `d':A#A`] THEN
    REWRITE_TAC[GRAPH_DARTS_INSERT_EDGE] THEN
    INTRO_TAC "d_dart d'_dart same_tail" THEN
    ASM_CASES_TAC `FST(d:A#A) = u` THENL
     [UNDISCH_TAC `FST(d:A#A) = u` THEN
      DISCH_THEN(LABEL_TAC "tail_u") THEN
      SUBGOAL_THEN
       `(d:A#A) IN (u,v) INSERT outgoing_darts E u /\
        (d':A#A) IN (u,v) INSERT outgoing_darts E u`
      (CONJUNCTS_THEN2 (LABEL_TAC "d_local")
        (LABEL_TAC "d'_local")) THENL
       [MP_TAC(ISPECL [`E:(A->bool)->bool`; `u:A`; `v:A`]
          OUTGOING_DARTS_INSERT_EDGE_LEFT) THEN
        ASM_REWRITE_TAC[EXTENSION] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        REWRITE_TAC[IN_OUTGOING_DARTS] THEN
        ASM_REWRITE_TAC[GRAPH_DARTS_INSERT_EDGE] THEN
        ASM_MESON_TAC[FST];
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`;
        `outgoing_darts E u:(A#A)->bool`; `(u:A,v:A)`; `a:A#A`]
       PERMUTATION_INSERT_TRANSITIVE_RESTRICTED) THEN
      ANTS_TAC THENL
       [CONJ_TAC THENL
         [USE_THEN "finite_darts" ACCEPT_TAC; ALL_TAC] THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
          USE_THEN "rotation" ACCEPT_TAC;
          ALL_TAC] THEN
        CONJ_TAC THENL
         [MATCH_ACCEPT_TAC OUTGOING_DARTS_SUBSET; ALL_TAC] THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC GRAPH_ROTATION_IMAGE_OUTGOING_DARTS THEN
          USE_THEN "rotation" ACCEPT_TAC;
          ALL_TAC] THEN
        CONJ_TAC THENL
         [USE_THEN "anchor" ACCEPT_TAC; ALL_TAC] THEN
        CONJ_TAC THENL
         [USE_THEN "new_forward" ACCEPT_TAC; ALL_TAC] THEN
        MAP_EVERY X_GEN_TAC [`e:A#A`; `e':A#A`] THEN
        INTRO_TAC "e_outgoing e'_outgoing" THEN
        USE_THEN "rotation" MP_TAC THEN
        REWRITE_TAC[graph_rotation] THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
         (CONJUNCTS_THEN2 (K ALL_TAC)
          (MP_TAC o SPECL [`e:A#A`; `e':A#A`]))) THEN
        ASM_MESON_TAC[IN_OUTGOING_DARTS];
        DISCH_THEN(MP_TAC o SPECL [`d:A#A`; `d':A#A`]) THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    UNDISCH_TAC `~(FST(d:A#A) = u)` THEN
    DISCH_THEN(LABEL_TAC "tail_not_u") THEN
    ASM_CASES_TAC `FST(d:A#A) = v` THENL
     [UNDISCH_TAC `FST(d:A#A) = v` THEN
      DISCH_THEN(LABEL_TAC "tail_v") THEN
      SUBGOAL_THEN
       `outgoing_darts ({u:A,v} INSERT E) v = {(v,u)}`
      (LABEL_TAC "new_outgoing_v") THENL
       [MP_TAC(ISPECL [`E:(A->bool)->bool`; `u:A`; `v:A`]
          OUTGOING_DARTS_INSERT_EDGE_RIGHT) THEN
        ASM_REWRITE_TAC[] THEN
        DISCH_THEN SUBST1_TAC THEN
        MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `v:A`]
          OUTGOING_DARTS_FRESH_VERTEX) THEN
        ASM_REWRITE_TAC[] THEN
        DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(d:A#A) IN outgoing_darts ({u,v} INSERT E) v /\
        (d':A#A) IN outgoing_darts ({u,v} INSERT E) v`
      (CONJUNCTS_THEN2 (LABEL_TAC "d_outgoing")
        (LABEL_TAC "d'_outgoing")) THENL
       [CONJ_TAC THENL
         [REWRITE_TAC[IN_OUTGOING_DARTS; GRAPH_DARTS_INSERT_EDGE] THEN
          CONJ_TAC THENL
           [USE_THEN "d_dart" ACCEPT_TAC;
            USE_THEN "tail_v" ACCEPT_TAC];
          REWRITE_TAC[IN_OUTGOING_DARTS; GRAPH_DARTS_INSERT_EDGE] THEN
          CONJ_TAC THENL
           [USE_THEN "d'_dart" ACCEPT_TAC;
            TRANS_TAC EQ_TRANS `FST(d:A#A)` THEN
            CONJ_TAC THENL
             [USE_THEN "same_tail" (ACCEPT_TAC o SYM);
              USE_THEN "tail_v" ACCEPT_TAC]]];
        ALL_TAC] THEN
      SUBGOAL_THEN `(d:A#A) = (v,u) /\ d' = (v,u)`
      (CONJUNCTS_THEN2 SUBST1_TAC SUBST1_TAC) THENL
       [CONJ_TAC THENL
         [USE_THEN "d_outgoing" (fun outgoing_th ->
            USE_THEN "new_outgoing_v" (fun set_th ->
             ACCEPT_TAC(REWRITE_RULE[set_th; IN_SING] outgoing_th)));
          USE_THEN "d'_outgoing" (fun outgoing_th ->
            USE_THEN "new_outgoing_v" (fun set_th ->
             ACCEPT_TAC(REWRITE_RULE[set_th; IN_SING] outgoing_th)))];
        EXISTS_TAC `0` THEN REWRITE_TAC[ITER]];
      ALL_TAC] THEN
    UNDISCH_TAC `~(FST(d:A#A) = v)` THEN
    DISCH_THEN(LABEL_TAC "tail_not_v") THEN
    SUBGOAL_THEN
     `(d:A#A) IN graph_darts E /\ d' IN graph_darts E`
    (CONJUNCTS_THEN2 (LABEL_TAC "d_old")
      (LABEL_TAC "d'_old")) THENL
     [SUBGOAL_THEN
       `~(FST(d':A#A) = u) /\ ~(FST d' = v)`
      (CONJUNCTS_THEN2 (LABEL_TAC "d'_not_u")
        (LABEL_TAC "d'_not_v")) THENL
       [CONJ_TAC THEN DISCH_THEN(LABEL_TAC "d'_tail") THENL
         [USE_THEN "tail_not_u" (MATCH_MP_TAC o NOT_ELIM);
          USE_THEN "tail_not_v" (MATCH_MP_TAC o NOT_ELIM)] THEN
        TRANS_TAC EQ_TRANS `FST(d':A#A)` THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      CONJ_TAC THENL
       [USE_THEN "d_dart" MP_TAC THEN
        REWRITE_TAC[IN_INSERT] THEN
        DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "forward")
          (DISJ_CASES_THEN2 (LABEL_TAC "reverse")
            (LABEL_TAC "old"))) THENL
         [USE_THEN "tail_not_u" (fun not_th ->
            USE_THEN "forward" (fun dart_th ->
             CONTR_TAC(MP (NOT_ELIM not_th)
              (REWRITE_RULE[FST]
               (AP_TERM `FST:A#A->A` dart_th)))));
          USE_THEN "tail_not_v" (fun not_th ->
            USE_THEN "reverse" (fun dart_th ->
             CONTR_TAC(MP (NOT_ELIM not_th)
              (REWRITE_RULE[FST]
               (AP_TERM `FST:A#A->A` dart_th)))));
          USE_THEN "old" ACCEPT_TAC];
        USE_THEN "d'_dart" MP_TAC THEN
        REWRITE_TAC[IN_INSERT] THEN
        DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "forward")
          (DISJ_CASES_THEN2 (LABEL_TAC "reverse")
            (LABEL_TAC "old"))) THENL
         [USE_THEN "d'_not_u" (fun not_th ->
            USE_THEN "forward" (fun dart_th ->
             CONTR_TAC(MP (NOT_ELIM not_th)
              (REWRITE_RULE[FST]
               (AP_TERM `FST:A#A->A` dart_th)))));
          USE_THEN "d'_not_v" (fun not_th ->
            USE_THEN "reverse" (fun dart_th ->
             CONTR_TAC(MP (NOT_ELIM not_th)
              (REWRITE_RULE[FST]
               (AP_TERM `FST:A#A->A` dart_th)))));
          USE_THEN "old" ACCEPT_TAC]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `?n. ITER n (r:(A#A)->A#A) d = d'`
    (X_CHOOSE_THEN `n:num` (LABEL_TAC "old_step")) THENL
     [USE_THEN "rotation" MP_TAC THEN
      REWRITE_TAC[graph_rotation] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
       (CONJUNCTS_THEN2 (K ALL_TAC)
        (MP_TAC o SPECL [`d:A#A`; `d':A#A`]))) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    EXISTS_TAC `n:num` THEN
    MP_TAC(ISPECL
     [`r:(A#A)->A#A`;
      `permutation_insert (r:(A#A)->A#A) (u,v) a`;
      `outgoing_darts E (FST(d:A#A)):(A#A)->bool`; `d:A#A`]
     ITER_AGREES_ON) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [REWRITE_TAC[IN_OUTGOING_DARTS] THEN
        USE_THEN "d_old" ACCEPT_TAC;
       X_GEN_TAC `e:A#A` THEN DISCH_THEN(LABEL_TAC "e_outgoing") THEN
        USE_THEN "e_outgoing" MP_TAC THEN
        REWRITE_TAC[IN_OUTGOING_DARTS] THEN
        INTRO_TAC "e_dart e_tail" THEN
        SUBGOAL_THEN `(r:(A#A)->A#A) e IN graph_darts E`
        (LABEL_TAC "re_dart") THENL
         [MATCH_MP_TAC(ISPECL
           [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `e:A#A`]
           GRAPH_ROTATION_IN) THEN
          ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        USE_THEN "rotation" (fun rotation_th ->
          USE_THEN "e_dart" (fun dart_th ->
           USE_THEN "e_tail" (fun tail_th ->
            LABEL_TAC "re_tail"
             (TRANS
              (MATCH_MP
               (ISPECL
                [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `e:A#A`]
                GRAPH_ROTATION_TAIL)
               (CONJ rotation_th dart_th))
              tail_th)))) THEN
        CONJ_TAC THENL
         [REWRITE_TAC[IN_OUTGOING_DARTS] THEN
          CONJ_TAC THENL
           [USE_THEN "re_dart" ACCEPT_TAC;
            USE_THEN "re_tail" ACCEPT_TAC];
          REWRITE_TAC[permutation_insert; o_THM] THEN
          USE_THEN "rotation" (fun rotation_th ->
           USE_THEN "anchor_dart" (fun dart_th ->
            USE_THEN "anchor_tail" (fun tail_th ->
             LABEL_TAC "rotated_anchor_tail"
              (TRANS
               (MATCH_MP
                (ISPECL
                 [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `a:A#A`]
                 GRAPH_ROTATION_TAIL)
                (CONJ rotation_th dart_th))
               tail_th)))) THEN
          SUBGOAL_THEN
           `~((r:(A#A)->A#A) e = (u,v))`
          (LABEL_TAC "not_new_image") THENL
           [DISCH_THEN(LABEL_TAC "new_image") THEN
            USE_THEN "tail_not_u" (fun not_th ->
             USE_THEN "re_tail" (fun tail_th ->
              USE_THEN "new_image" (fun image_th ->
               CONTR_TAC(MP (NOT_ELIM not_th)
                (TRANS (SYM tail_th)
                 (REWRITE_RULE[FST]
                  (AP_TERM `FST:A#A->A` image_th)))))));
            ALL_TAC] THEN
          SUBGOAL_THEN
           `~((r:(A#A)->A#A) e = r a)`
          (LABEL_TAC "not_anchor_image") THENL
           [DISCH_THEN(LABEL_TAC "anchor_image") THEN
            USE_THEN "tail_not_u" (fun not_th ->
             USE_THEN "re_tail" (fun re_tail_th ->
              USE_THEN "anchor_image" (fun image_th ->
               USE_THEN "rotated_anchor_tail" (fun anchor_tail_th ->
                CONTR_TAC(MP (NOT_ELIM not_th)
                 (TRANS (SYM re_tail_th)
                  (TRANS
                   (AP_TERM `FST:A#A->A` image_th)
                   anchor_tail_th)))))));
            ALL_TAC] THEN
          USE_THEN "not_new_image" (fun new_th ->
           USE_THEN "not_anchor_image" (fun anchor_th ->
            ACCEPT_TAC(MATCH_MP
             (ISPECL
              [`(u:A,v:A)`; `(r:(A#A)->A#A) a`;
               `(r:(A#A)->A#A) e`]
              SWAP_OTHER)
             (CONJ new_th anchor_th))))]];
      DISCH_THEN(MP_TAC o SPEC `n:num`) THEN
      USE_THEN "old_step" (fun th -> REWRITE_TAC[th]) THEN
      MESON_TAC[]]]);;

let GRAPH_FACE_SUCCESSOR_INSERT_PENDANT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v:A. !a:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        u IN V /\
        ~(v IN V) /\
        a IN outgoing_darts E u
        ==> graph_face_successor
             ({u,v} INSERT E)
             (permutation_insert r (u,v) a) =
            permutation_insert
             (permutation_insert
               (graph_face_successor E r)
               (u,v) (reverse_dart a))
             (v,u) (u,v)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation u_vertex v_fresh anchor" THEN
  SUBGOAL_THEN `~(u:A = v)` (LABEL_TAC "distinct") THENL
   [DISCH_THEN(LABEL_TAC "equal") THEN
    USE_THEN "v_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "equal" (fun th ->
      USE_THEN "u_vertex" (ACCEPT_TAC o REWRITE_RULE[th]));
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:A#A) IN graph_darts E`
  (LABEL_TAC "anchor_dart") THENL
   [USE_THEN "anchor" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((u:A),(v:A)) IN graph_darts E) /\
    ~(((v:A),(u:A)) IN graph_darts E)`
  (CONJUNCTS_THEN2 (LABEL_TAC "new_forward")
    (LABEL_TAC "new_reverse")) THENL
   [CONJ_TAC THEN DISCH_THEN(LABEL_TAC "old_dart") THEN
    USE_THEN "v_fresh" (MATCH_MP_TAC o NOT_ELIM) THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `u:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~({u:A,v} IN E)` (LABEL_TAC "new_edge") THENL
   [DISCH_THEN(LABEL_TAC "edge") THEN
    ASM_MESON_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN `reverse_dart(a:A#A) IN graph_darts E`
  (LABEL_TAC "reverse_anchor") THENL
   [ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (reverse_dart(a:A#A)) = r a`
  (LABEL_TAC "old_anchor_image") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `reverse_dart(a:A#A)`]
     GRAPH_FACE_SUCCESSOR_IN) THEN
    ASM_REWRITE_TAC[REVERSE_DART_INVOLUTION];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(graph_face_successor
      (E:(A->bool)->bool) (r:(A#A)->A#A)) permutes graph_darts E`
  (LABEL_TAC "face_permutation") THENL
   [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r ((u:A),(v:A)) = (u,v)`
  (LABEL_TAC "face_fixes_forward") THENL
   [USE_THEN "face_permutation"
     (MATCH_MP_TAC o CONJUNCT1 o REWRITE_RULE[permutes]) THEN
    USE_THEN "new_forward" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) permutes graph_darts E`
  (LABEL_TAC "rotation_permutation") THENL
   [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) o swap((u,v),(v,u)) =
    swap((u,v),(v,u)) o r`
  (LABEL_TAC "rotation_commutes") THENL
   [MATCH_MP_TAC(ISPECL
     [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`;
      `(u:A,v:A)`; `(v:A,u:A)`]
     PERMUTES_COMMUTES_SWAP_OUTSIDE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:(A#A)->A#A) a IN graph_darts E`
  (LABEL_TAC "image_anchor") THENL
   [MATCH_MP_TAC GRAPH_ROTATION_IN THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((r:(A#A)->A#A) a = (v,u))`
  (LABEL_TAC "image_not_reverse") THENL
   [DISCH_THEN(LABEL_TAC "equal") THEN
    USE_THEN "new_reverse" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "equal" (fun th ->
      USE_THEN "image_anchor" (ACCEPT_TAC o REWRITE_RULE[th]));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `swap((u:A,v:A),(r:(A#A)->A#A) a) o
      swap((u,v),(v,u)) =
    swap((v,u),r a) o swap((u,v),r a)`
  (LABEL_TAC "swap_triangle") THENL
   [GEN_REWRITE_TAC (RAND_CONV o LAND_CONV) [SWAP_SYM] THEN
    MATCH_MP_TAC(ISPECL
     [`(u:A,v:A)`; `(r:(A#A)->A#A) a`; `(v:A,u:A)`]
     SWAP_COMMON) THEN
    ASM_REWRITE_TAC[PAIR_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(swap((u:A,v:A),(r:(A#A)->A#A) a) o r) o
      (swap((u,v),(v,u)) o graph_reverse_dart E) =
    swap((v,u),r a) o
      (swap((u,v),r a) o
       (r o graph_reverse_dart E))`
  (LABEL_TAC "algebra") THENL
   [REWRITE_TAC[FUN_EQ_THM; o_THM] THEN X_GEN_TAC `d:A#A` THEN
    SUBGOAL_THEN
     `(r:(A#A)->A#A)
       (swap((u,v),(v,u)) (graph_reverse_dart E d)) =
      swap((u,v),(v,u)) (r(graph_reverse_dart E d))`
    SUBST1_TAC THENL
     [USE_THEN "rotation_commutes" (fun th ->
       MP_TAC(AP_THM th `graph_reverse_dart E (d:A#A)`)) THEN
      REWRITE_TAC[o_THM];
      USE_THEN "swap_triangle" (fun th ->
       MP_TAC(AP_THM th
        `((r:(A#A)->A#A) o graph_reverse_dart E) d`)) THEN
      REWRITE_TAC[o_THM]];
    ALL_TAC] THEN
  REWRITE_TAC[permutation_insert] THEN
  USE_THEN "old_anchor_image" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "face_fixes_forward"
   (fun th -> REWRITE_TAC[o_THM; th; SWAP_LEFT]) THEN
  REWRITE_TAC[graph_face_successor] THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `u:A`; `v:A`]
   GRAPH_REVERSE_DART_INSERT_EDGE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "algebra" ACCEPT_TAC);;

let CARD_GRAPH_FACES_INSERT_PENDANT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v:A. !a:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        u IN V /\
        ~(v IN V) /\
        a IN outgoing_darts E u
        ==> CARD
             (graph_faces
               ({u,v} INSERT E)
               (permutation_insert r (u,v) a)) =
            CARD(graph_faces E r)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation u_vertex v_fresh anchor" THEN
  REWRITE_TAC[GRAPH_FACES_AS_PERMUTATION_ORBITS;
              GRAPH_DARTS_INSERT_EDGE] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `a:A#A`]
   GRAPH_FACE_SUCCESSOR_INSERT_PENDANT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN
   `((u:A,v:A) INSERT (v,u) INSERT graph_darts E) =
    (v,u) INSERT (u,v) INSERT graph_darts E`
  SUBST1_TAC THENL
   [SET_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC PERMUTATION_INSERT_TWO_ORBIT_COUNT THEN
  REPEAT CONJ_TAC THENL
   [ASM_MESON_TAC[FINITE_GRAPH_DARTS];
    ASM_MESON_TAC[GRAPH_FACE_SUCCESSOR_PERMUTES];
    ASM_MESON_TAC[IN_OUTGOING_DARTS; GRAPH_DARTS_REVERSE];
    ASM_MESON_TAC[FINITE_SIMPLE_GRAPH_DART];
    REWRITE_TAC[IN_INSERT; PAIR_EQ] THEN
    ASM_MESON_TAC[FINITE_SIMPLE_GRAPH_DART]]);;

let GRAPH_EULER_FORMULA_INSERT_PENDANT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v:A. !a:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        graph_euler_formula V E r /\
        u IN V /\
        ~(v IN V) /\
        a IN outgoing_darts E u
        ==> graph_euler_formula
             (v INSERT V)
             ({u,v} INSERT E)
             (permutation_insert r (u,v) a)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation euler u_vertex v_fresh anchor" THEN
  SUBGOAL_THEN
   `FINITE(V:A->bool) /\ FINITE(E:(A->bool)->bool)`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_vertices")
    (LABEL_TAC "finite_edges")) THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(E:(A->bool)->bool = {})`
  (LABEL_TAC "edges_nonempty") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "anchor" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS; graph_darts;
                IN_ELIM_THM; NOT_IN_EMPTY];
    ALL_TAC] THEN
  SUBGOAL_THEN `~({u:A,v} IN E)` (LABEL_TAC "new_edge") THENL
   [DISCH_THEN(LABEL_TAC "old_edge") THEN
    USE_THEN "v_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `u:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS;
                    SET_RULE `{v:A,u} = {u,v}`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD
     (graph_faces
       ({u:A,v} INSERT E)
       (permutation_insert r (u,v) a)) =
    CARD(graph_faces E r)`
  (LABEL_TAC "face_count") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`; `a:A#A`]
     CARD_GRAPH_FACES_INSERT_PENDANT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
  ASM_REWRITE_TAC[NOT_INSERT_EMPTY] THEN
  ASM_SIMP_TAC[CARD_CLAUSES] THEN
  ARITH_TAC);;

let EULER_PLANAR_ROTATION_INSERT_PENDANT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v:A. !a:A#A.
        euler_planar_rotation V E r /\
        u IN V /\
        ~(v IN V) /\
        a IN outgoing_darts E u
        ==> euler_planar_rotation
             (v INSERT V)
             ({u,v} INSERT E)
             (permutation_insert r (u,v) a)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "euler_rotation u_vertex v_fresh anchor" THEN
  USE_THEN "euler_rotation" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph rotation euler" THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INSERT_PENDANT;
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`; `a:A#A`]
     GRAPH_ROTATION_INSERT_PENDANT);
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`; `a:A#A`]
     GRAPH_EULER_FORMULA_INSERT_PENDANT)] THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Base Euler-planar rotations.                                              *)
(* ------------------------------------------------------------------------- *)

let GRAPH_DARTS_SINGLE_EDGE = prove
 (`!u v:A.
        ~(u = v)
        ==> graph_darts {{u,v}} = {(u,v),(v,u)}`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "distinct") THEN
  TRANS_TAC EQ_TRANS `edge_darts {u:A,v}` THEN CONJ_TAC THENL
   [REWRITE_TAC[graph_darts; edge_darts; EXTENSION;
                IN_ELIM_THM; IN_SING];
    MATCH_MP_TAC EDGE_DARTS_PAIR THEN
    USE_THEN "distinct" ACCEPT_TAC]);;

let FINITE_SIMPLE_GRAPH_SINGLE_EDGE = prove
 (`!u v:A.
        ~(u = v)
        ==> finite_simple_graph {u,v} {{u,v}}`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "distinct") THEN
  MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INSERT_EDGE THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[finite_simple_graph; FINITE_INSERT; FINITE_EMPTY;
                NOT_IN_EMPTY];
    SET_TAC[];
    REWRITE_TAC[HAS_SIZE_CONV `({u:A,v}:A->bool) HAS_SIZE 2`] THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `v:A`] THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_ROTATION_SINGLE_EDGE = prove
 (`!u v:A.
        ~(u = v)
        ==> graph_rotation {{u,v}} (I:(A#A)->A#A)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "distinct") THEN
  REWRITE_TAC[graph_rotation] THEN REPEAT CONJ_TAC THENL
   [MATCH_ACCEPT_TAC PERMUTES_I;
    REWRITE_TAC[I_THM];
    MAP_EVERY X_GEN_TAC [`d:A#A`; `d':A#A`] THEN
    INTRO_TAC "d_dart d'_dart same_tail" THEN
    SUBGOAL_THEN `(d:A#A) = d'` SUBST1_TAC THENL
     [USE_THEN "d_dart" MP_TAC THEN USE_THEN "d'_dart" MP_TAC THEN
      REWRITE_TAC[MATCH_MP GRAPH_DARTS_SINGLE_EDGE
       (ASSUME `~(u:A = v)`); IN_INSERT; IN_SING] THEN
      ASM_MESON_TAC[FST];
      EXISTS_TAC `0` THEN REWRITE_TAC[ITER]]]);;

let GRAPH_FACE_SUCCESSOR_SINGLE_EDGE = prove
 (`!u v:A.
        ~(u = v)
        ==> graph_face_successor {{u,v}} (I:(A#A)->A#A) (u,v) =
            (v,u) /\
            graph_face_successor {{u,v}} I (v,u) = (u,v)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "distinct") THEN
  ASM_SIMP_TAC[graph_face_successor; o_THM; graph_reverse_dart;
               GRAPH_DARTS_SINGLE_EDGE; IN_INSERT; IN_SING;
               REVERSE_DART_PAIR; I_THM]);;

let GRAPH_FACE_SINGLE_EDGE = prove
 (`!u v:A. !d:A#A.
        ~(u = v) /\ d IN graph_darts {{u,v}}
        ==> graph_face {{u,v}} (I:(A#A)->A#A) d =
            graph_darts {{u,v}}`,
  MAP_EVERY X_GEN_TAC [`u:A`; `v:A`; `d:A#A`] THEN
  INTRO_TAC "distinct d_dart" THEN
  SUBGOAL_THEN `(d:A#A) = (u,v) \/ d = (v,u)`
  (DISJ_CASES_THEN SUBST_ALL_TAC) THENL
   [USE_THEN "d_dart" MP_TAC THEN
    USE_THEN "distinct" (fun distinct_th ->
      REWRITE_TAC
       [MATCH_MP
         (ISPECL [`u:A`; `v:A`] GRAPH_DARTS_SINGLE_EDGE)
         distinct_th;
        IN_INSERT; IN_SING]);
    ALL_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [MATCH_MP_TAC GRAPH_FACE_SUBSET_DARTS THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_ROTATION_SINGLE_EDGE THEN
      USE_THEN "distinct" ACCEPT_TAC;
      USE_THEN "d_dart" ACCEPT_TAC];
    REWRITE_TAC[SUBSET] THEN X_GEN_TAC `z:A#A` THEN
    USE_THEN "distinct" (fun distinct_th ->
      REWRITE_TAC
       [MATCH_MP
         (ISPECL [`u:A`; `v:A`] GRAPH_DARTS_SINGLE_EDGE)
         distinct_th;
        IN_INSERT; IN_SING]) THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
    REWRITE_TAC[IN_GRAPH_FACE] THENL
     [EXISTS_TAC `0` THEN REWRITE_TAC[ITER];
      EXISTS_TAC `1` THEN
      REWRITE_TAC[ITER_1] THEN
      USE_THEN "distinct" (fun distinct_th ->
       ACCEPT_TAC
        (CONJUNCT1
         (MATCH_MP
          (ISPECL [`u:A`; `v:A`]
           GRAPH_FACE_SUCCESSOR_SINGLE_EDGE)
          distinct_th)))];
    MATCH_MP_TAC GRAPH_FACE_SUBSET_DARTS THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_ROTATION_SINGLE_EDGE THEN
      USE_THEN "distinct" ACCEPT_TAC;
      USE_THEN "d_dart" ACCEPT_TAC];
    REWRITE_TAC[SUBSET] THEN X_GEN_TAC `z:A#A` THEN
    USE_THEN "distinct" (fun distinct_th ->
      REWRITE_TAC
       [MATCH_MP
         (ISPECL [`u:A`; `v:A`] GRAPH_DARTS_SINGLE_EDGE)
         distinct_th;
        IN_INSERT; IN_SING]) THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
    REWRITE_TAC[IN_GRAPH_FACE] THENL
     [EXISTS_TAC `1` THEN
      REWRITE_TAC[ITER_1] THEN
      USE_THEN "distinct" (fun distinct_th ->
       ACCEPT_TAC
        (CONJUNCT2
         (MATCH_MP
          (ISPECL [`u:A`; `v:A`]
           GRAPH_FACE_SUCCESSOR_SINGLE_EDGE)
          distinct_th)));
      EXISTS_TAC `0` THEN REWRITE_TAC[ITER]]]);;

let GRAPH_FACES_SINGLE_EDGE = prove
  (`!u v:A.
        ~(u = v)
        ==> graph_faces {{u,v}} (I:(A#A)->A#A) =
            {graph_darts {{u,v}}}`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "distinct") THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET] THEN X_GEN_TAC `f:(A#A)->bool` THEN
    REWRITE_TAC[IN_GRAPH_FACES; IN_SING] THEN
    INTRO_TAC "@d. d_dart face" THEN
    USE_THEN "face" SUBST1_TAC THEN
    MATCH_MP_TAC GRAPH_FACE_SINGLE_EDGE THEN
    CONJ_TAC THENL
     [USE_THEN "distinct" ACCEPT_TAC;
      USE_THEN "d_dart" ACCEPT_TAC];
    REWRITE_TAC[SUBSET] THEN X_GEN_TAC `f:(A#A)->bool` THEN
    REWRITE_TAC[IN_SING; IN_GRAPH_FACES] THEN
    DISCH_THEN SUBST1_TAC THEN EXISTS_TAC `(u:A,v:A)` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR; IN_SING];
      MATCH_MP_TAC EQ_SYM THEN MATCH_MP_TAC GRAPH_FACE_SINGLE_EDGE THEN
      CONJ_TAC THENL
       [USE_THEN "distinct" ACCEPT_TAC;
        REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR; IN_SING]]]]);;

let GRAPH_EULER_FORMULA_SINGLE_EDGE = prove
  (`!u v:A.
        ~(u = v)
        ==> graph_euler_formula {u,v} {{u,v}}
             (I:(A#A)->A#A)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "distinct") THEN
  REWRITE_TAC[graph_euler_formula; graph_map_faces;
              NOT_INSERT_EMPTY] THEN
  USE_THEN "distinct" (fun distinct_th ->
    REWRITE_TAC
     [MATCH_MP
       (ISPECL [`u:A`; `v:A`] GRAPH_FACES_SINGLE_EDGE)
       distinct_th]) THEN
  ASM_SIMP_TAC[NOT_INSERT_EMPTY; CARD_CLAUSES;
               FINITE_INSERT; FINITE_EMPTY; NOT_IN_EMPTY; IN_SING] THEN
  ARITH_TAC);;

let EULER_PLANAR_ROTATION_SINGLE_EDGE = prove
 (`!u v:A.
        ~(u = v)
        ==> euler_planar_rotation {u,v} {{u,v}}
             (I:(A#A)->A#A)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "distinct") THEN
  REWRITE_TAC[euler_planar_rotation] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_SINGLE_EDGE;
    MATCH_MP_TAC GRAPH_ROTATION_SINGLE_EDGE;
    MATCH_MP_TAC GRAPH_EULER_FORMULA_SINGLE_EDGE] THEN
  USE_THEN "distinct" ACCEPT_TAC);;

let GRAPH_ROTATION_CARD_FACES_ONE_COFACIAL = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A. !d d':A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        CARD(graph_faces E r) = 1 /\
        d IN graph_darts E /\
        d' IN graph_darts E
        ==> d' IN graph_face E r d`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation one_face d_dart d'_dart" THEN
  SUBGOAL_THEN
   `(graph_faces
      (E:(A->bool)->bool) (r:(A#A)->A#A)) HAS_SIZE 1`
  MP_TAC THENL
   [REWRITE_TAC[HAS_SIZE] THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
     FINITE_GRAPH_FACES) THEN
    USE_THEN "graph" ACCEPT_TAC;
    REWRITE_TAC
     [HAS_SIZE_CONV
       `(graph_faces
          (E:(A->bool)->bool) (r:(A#A)->A#A)) HAS_SIZE 1`] THEN
    INTRO_TAC "@f. all_faces"] THEN
  SUBGOAL_THEN `graph_face E r (d:A#A) = f`
  (LABEL_TAC "d_face") THENL
   [USE_THEN "all_faces" (fun th -> REWRITE_TAC[GSYM IN_SING; GSYM th]) THEN
    REWRITE_TAC[IN_GRAPH_FACES] THEN EXISTS_TAC `d:A#A` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `graph_face E r (d':A#A) = f`
  (LABEL_TAC "d'_face") THENL
   [USE_THEN "all_faces" (fun th -> REWRITE_TAC[GSYM IN_SING; GSYM th]) THEN
    REWRITE_TAC[IN_GRAPH_FACES] THEN EXISTS_TAC `d':A#A` THEN
    ASM_REWRITE_TAC[];
    USE_THEN "d_face" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "d'_face" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_ACCEPT_TAC GRAPH_FACE_REFL]);;

let triangle_rotation = new_definition
 `triangle_rotation (a:A) b c =
    permutation_insert
     (permutation_insert
       (permutation_insert (I:(A#A)->A#A) (b,c) (b,a))
       (c,a) (c,b))
     (a,c) (a,b)`;;

let EULER_PLANAR_TRIANGLE_ROTATION = prove
 (`!a b c:A.
        ~(a = b) /\ ~(b = c) /\ ~(c = a)
        ==> euler_planar_rotation
             {a,b,c} {{a,b},{b,c},{c,a}}
             (triangle_rotation a b c)`,
  REPEAT GEN_TAC THEN INTRO_TAC "ab bc ca" THEN
  ABBREV_TAC
   `r1:(A#A)->A#A =
      permutation_insert (I:(A#A)->A#A) (b,c) (b,a)` THEN
  SUBGOAL_THEN
   `euler_planar_rotation
      (c INSERT {a,b}:A->bool)
      ({b,c} INSERT {{a,b}}:(A->bool)->bool)
      (r1:(A#A)->A#A)`
  (LABEL_TAC "path") THENL
   [EXPAND_TAC "r1" THEN
    MATCH_MP_TAC(ISPECL
     [`{a,b}:A->bool`; `{{a,b}}:(A->bool)->bool`;
      `I:(A#A)->A#A`; `b:A`; `c:A`; `(b:A,a:A)`]
     EULER_PLANAR_ROTATION_INSERT_PENDANT) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC EULER_PLANAR_ROTATION_SINGLE_EDGE THEN
      USE_THEN "ab" ACCEPT_TAC;
      SET_TAC[];
      USE_THEN "bc" MP_TAC THEN USE_THEN "ca" MP_TAC THEN SET_TAC[];
      REWRITE_TAC[IN_OUTGOING_DARTS_PAIR; IN_SING] THEN SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD
     (graph_faces
       ({b,c} INSERT {{a,b}}:(A->bool)->bool)
       (r1:(A#A)->A#A)) = 1`
  (LABEL_TAC "one_face") THENL
   [TRANS_TAC EQ_TRANS `CARD(graph_faces {{a,b}} (I:(A#A)->A#A))` THEN
    CONJ_TAC THENL
     [EXPAND_TAC "r1" THEN
      MATCH_MP_TAC(ISPECL
       [`{a,b}:A->bool`; `{{a,b}}:(A->bool)->bool`;
        `I:(A#A)->A#A`; `b:A`; `c:A`; `(b:A,a:A)`]
       CARD_GRAPH_FACES_INSERT_PENDANT) THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_SINGLE_EDGE THEN
        USE_THEN "ab" ACCEPT_TAC;
        MATCH_MP_TAC GRAPH_ROTATION_SINGLE_EDGE THEN
       USE_THEN "ab" ACCEPT_TAC;
        SET_TAC[];
        USE_THEN "bc" MP_TAC THEN USE_THEN "ca" MP_TAC THEN SET_TAC[];
        REWRITE_TAC[IN_OUTGOING_DARTS_PAIR; IN_SING] THEN SET_TAC[]];
      ASM_SIMP_TAC[GRAPH_FACES_SINGLE_EDGE; CARD_SING]];
    ALL_TAC] THEN
  USE_THEN "path"
   (MP_TAC o REWRITE_RULE[euler_planar_rotation]) THEN
  INTRO_TAC "path_graph path_rotation path_formula" THEN
  SUBGOAL_THEN
   `reverse_dart(a:A,b:A) IN
    graph_face
      ({b,c} INSERT {{a,b}}:(A->bool)->bool)
      (r1:(A#A)->A#A)
      (reverse_dart(c:A,b:A))`
  (LABEL_TAC "cofacial") THENL
   [MATCH_MP_TAC(ISPECL
     [`c INSERT {a,b}:A->bool`;
      `{b,c} INSERT {{a,b}}:(A->bool)->bool`;
     `r1:(A#A)->A#A`; `reverse_dart(c,b):A#A`;
      `reverse_dart(a,b):A#A`]
     GRAPH_ROTATION_CARD_FACES_ONE_COFACIAL) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "path_graph" ACCEPT_TAC;
      USE_THEN "path_rotation" ACCEPT_TAC;
      USE_THEN "one_face" ACCEPT_TAC;
      REWRITE_TAC[REVERSE_DART_PAIR; IN_GRAPH_DARTS;
                  DART_EDGE_PAIR; IN_INSERT];
      REWRITE_TAC[REVERSE_DART_PAIR; IN_GRAPH_DARTS;
                  DART_EDGE_PAIR; IN_INSERT; IN_SING] THEN
      SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `euler_planar_rotation
      (c INSERT {a,b}:A->bool)
      ({c,a} INSERT ({b,c} INSERT {{a,b}}):(A->bool)->bool)
      (permutation_insert
        (permutation_insert (r1:(A#A)->A#A) (c,a) (c,b))
        (a,c) (a,b))`
  (LABEL_TAC "triangle") THENL
   [MATCH_MP_TAC(ISPECL
     [`c INSERT {a,b}:A->bool`;
      `{b,c} INSERT {{a,b}}:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `c:A`; `a:A`;
      `(c:A,b:A)`; `(a:A,b:A)`]
    EULER_PLANAR_ROTATION_INSERT_EDGE) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "path" ACCEPT_TAC;
      REWRITE_TAC[IN_INSERT];
      REWRITE_TAC[IN_INSERT; IN_SING];
      USE_THEN "ca" ACCEPT_TAC;
      REWRITE_TAC[IN_INSERT; IN_SING] THEN
      MATCH_MP_TAC(TAUT `~p /\ ~q ==> ~(p \/ q)`) THEN
      CONJ_TAC THEN DISCH_THEN(LABEL_TAC "edge_equal") THENL
       [MP_TAC(ISPECL [`c:A`; `a:A`; `b:A`; `c:A`]
         PAIR_SET_EQ_DISTINCT) THEN
        ANTS_TAC THENL
         [CONJ_TAC THENL
           [USE_THEN "ca" ACCEPT_TAC;
            USE_THEN "edge_equal" ACCEPT_TAC];
          DISCH_THEN(DISJ_CASES_THEN2
           (CONJUNCTS_THEN2 (LABEL_TAC "cb") (K ALL_TAC))
           (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "ab_equal"))) THENL
           [USE_THEN "bc" (MATCH_MP_TAC o NOT_ELIM) THEN
            USE_THEN "cb" (ACCEPT_TAC o SYM);
            USE_THEN "ab" (MATCH_MP_TAC o NOT_ELIM) THEN
            USE_THEN "ab_equal" ACCEPT_TAC]];
        MP_TAC(ISPECL [`c:A`; `a:A`; `a:A`; `b:A`]
         PAIR_SET_EQ_DISTINCT) THEN
        ANTS_TAC THENL
         [CONJ_TAC THENL
           [USE_THEN "ca" ACCEPT_TAC;
            USE_THEN "edge_equal" ACCEPT_TAC];
          DISCH_THEN(DISJ_CASES_THEN2
           (CONJUNCTS_THEN2 (LABEL_TAC "ca_equal") (K ALL_TAC))
           (CONJUNCTS_THEN2 (LABEL_TAC "cb") (K ALL_TAC))) THENL
           [USE_THEN "ca" (MATCH_MP_TAC o NOT_ELIM) THEN
            USE_THEN "ca_equal" ACCEPT_TAC;
            USE_THEN "bc" (MATCH_MP_TAC o NOT_ELIM) THEN
            USE_THEN "cb" (ACCEPT_TAC o SYM)]]];
      REWRITE_TAC[IN_OUTGOING_DARTS_PAIR; IN_INSERT;
                  SET_RULE `{c:A,b} = {b,c}`];
      REWRITE_TAC[IN_OUTGOING_DARTS_PAIR; IN_INSERT; IN_SING];
      USE_THEN "cofacial" ACCEPT_TAC];
    USE_THEN "triangle" MP_TAC THEN
    EXPAND_TAC "r1" THEN
    REWRITE_TAC[triangle_rotation;
                SET_RULE `c INSERT {a:A,b} = {a,b,c}`;
                SET_RULE
                 `{c:A,a} INSERT ({b,c} INSERT {{a,b}}) =
                  {{a,b},{b,c},{c,a}}`]]);;

let EULER_PLANAR_TRIANGLE_ROTATION_EXISTS = prove
 (`!a b c:A.
        ~(a = b) /\ ~(b = c) /\ ~(c = a)
        ==> ?r:(A#A)->A#A.
              euler_planar_rotation
                {a,b,c} {{a,b},{b,c},{c,a}} r`,
  MESON_TAC[EULER_PLANAR_TRIANGLE_ROTATION]);;

(* ------------------------------------------------------------------------- *)
(* Directed boundary faces of Euler-planar rotations.                        *)
(* ------------------------------------------------------------------------- *)

let cyclic_darts = new_definition
 `cyclic_darts (q:num->A) n =
    IMAGE
     (\i. (q i,q ((i + 1) MOD n)))
     (cyclic_indices n)`;;

let IN_CYCLIC_DARTS = prove
 (`!q:num->A. !n d.
        d IN cyclic_darts q n <=>
        ?i. i < n /\ d = (q i,q ((i + 1) MOD n))`,
  REWRITE_TAC[cyclic_darts; IN_IMAGE; IN_CYCLIC_INDICES] THEN
  MESON_TAC[]);;

let FINITE_CYCLIC_DARTS = prove
 (`!q:num->A. !n. FINITE(cyclic_darts q n)`,
  REWRITE_TAC[cyclic_darts] THEN
  MESON_TAC[FINITE_IMAGE; FINITE_CYCLIC_INDICES]);;

let CYCLIC_DARTS_SUBSET_GRAPH_DARTS = prove
 (`!E q:num->A. !n.
        cyclic_edges q n SUBSET E
        ==> cyclic_darts q n SUBSET graph_darts E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "edges") THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `d:A#A` THEN
  REWRITE_TAC[IN_CYCLIC_DARTS] THEN
  DISCH_THEN(X_CHOOSE_THEN `i:num` STRIP_ASSUME_TAC) THEN
  ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN
  USE_THEN "edges" (fun th ->
    MATCH_MP_TAC
     (SPEC `{(q:num->A) i,q ((i + 1) MOD n)}`
       (REWRITE_RULE[SUBSET] th))) THEN
  REWRITE_TAC[IN_CYCLIC_EDGES] THEN
  EXISTS_TAC `i:num` THEN
  ASM_REWRITE_TAC[]);;

let CYCLIC_DARTS_3 = prove
 (`!q:num->A.
        cyclic_darts q 3 =
        {(q 0,q 1),(q 1,q 2),(q 2,q 0)}`,
  GEN_TAC THEN
  REWRITE_TAC[cyclic_darts; CYCLIC_INDICES_3; IMAGE_CLAUSES] THEN
  CONV_TAC NUM_REDUCE_CONV);;

let TRIANGLE_ROTATION_VALUES = prove
 (`!a b c:A.
        ~(a = b) /\ ~(b = c) /\ ~(c = a)
        ==> triangle_rotation a b c (a,b) = (a,c) /\
            triangle_rotation a b c (a,c) = (a,b) /\
            triangle_rotation a b c (b,a) = (b,c) /\
            triangle_rotation a b c (b,c) = (b,a) /\
            triangle_rotation a b c (c,a) = (c,b) /\
            triangle_rotation a b c (c,b) = (c,a)`,
  REPEAT GEN_TAC THEN INTRO_TAC "ab bc ca" THEN
  REPEAT CONJ_TAC THEN
  REWRITE_TAC[triangle_rotation; permutation_insert; o_THM; I_THM] THEN
  ASM_SIMP_TAC[SWAP_LEFT; SWAP_RIGHT; SWAP_OTHER; PAIR_EQ]);;

let GRAPH_FACE_SUCCESSOR_TRIANGLE_OUTER = prove
 (`!a b c:A.
        ~(a = b) /\ ~(b = c) /\ ~(c = a)
        ==> graph_face_successor
             {{a,b},{b,c},{c,a}}
             (triangle_rotation a b c) (a,b) = (b,c) /\
            graph_face_successor
             {{a,b},{b,c},{c,a}}
             (triangle_rotation a b c) (b,c) = (c,a) /\
            graph_face_successor
             {{a,b},{b,c},{c,a}}
             (triangle_rotation a b c) (c,a) = (a,b)`,
  REPEAT GEN_TAC THEN INTRO_TAC "ab bc ca" THEN
  MP_TAC(ISPECL [`a:A`; `b:A`; `c:A`]
    TRIANGLE_ROTATION_VALUES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "rab rac rba rbc rca rcb" THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL
     [`{{a,b},{b,c},{c,a}}:(A->bool)->bool`;
      `triangle_rotation a b c:(A#A)->A#A`; `(a:A,b:A)`]
     GRAPH_FACE_SUCCESSOR_IN);
    MP_TAC(ISPECL
     [`{{a,b},{b,c},{c,a}}:(A->bool)->bool`;
      `triangle_rotation a b c:(A#A)->A#A`; `(b:A,c:A)`]
     GRAPH_FACE_SUCCESSOR_IN);
    MP_TAC(ISPECL
     [`{{a,b},{b,c},{c,a}}:(A->bool)->bool`;
      `triangle_rotation a b c:(A#A)->A#A`; `(c:A,a:A)`]
     GRAPH_FACE_SUCCESSOR_IN)] THEN
  REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR; IN_INSERT;
              REVERSE_DART_PAIR] THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_FACE_TRIANGLE_OUTER = prove
  (`!a b c:A.
        ~(a = b) /\ ~(b = c) /\ ~(c = a)
        ==> graph_face
             {{a,b},{b,c},{c,a}}
             (triangle_rotation a b c) (a,b) =
            {(a,b),(b,c),(c,a)}`,
  REPEAT GEN_TAC THEN INTRO_TAC "ab bc ca" THEN
  SUBGOAL_THEN
   `graph_face_successor
      {{a,b},{b,c},{c,a}}
      (triangle_rotation a b c) (a:A,b:A) = (b,c) /\
    graph_face_successor
      {{a,b},{b,c},{c,a}}
      (triangle_rotation a b c) (b,c) = (c,a) /\
    graph_face_successor
      {{a,b},{b,c},{c,a}}
      (triangle_rotation a b c) (c,a) = (a,b)`
  (CONJUNCTS_THEN2 (LABEL_TAC "gab")
    (CONJUNCTS_THEN2 (LABEL_TAC "gbc") (LABEL_TAC "gca"))) THENL
   [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_TRIANGLE_OUTER THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_GRAPH_FACE] THEN
    X_GEN_TAC `d:A#A` THEN
    DISCH_THEN(X_CHOOSE_THEN `n:num` (SUBST1_TAC o SYM)) THEN
    SPEC_TAC(`n:num`,`n:num`) THEN INDUCT_TAC THENL
     [REWRITE_TAC[ITER; IN_INSERT];
      REWRITE_TAC[ITER] THEN
      FIRST_X_ASSUM MP_TAC THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST1_TAC) THEN
      ASM_REWRITE_TAC[IN_INSERT; IN_SING]];
    REWRITE_TAC[SUBSET; IN_INSERT; IN_SING] THEN
    X_GEN_TAC `d:A#A` THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST1_TAC) THEN
    REWRITE_TAC[IN_GRAPH_FACE] THENL
     [EXISTS_TAC `0` THEN REWRITE_TAC[ITER];
      EXISTS_TAC `1` THEN REWRITE_TAC[ITER_1] THEN
      USE_THEN "gab" ACCEPT_TAC;
      EXISTS_TAC `SUC(SUC 0)` THEN
      REWRITE_TAC[ITER] THEN ASM_REWRITE_TAC[]]]);;

let boundary_euler_rotation = new_definition
 `boundary_euler_rotation
    (V:A->bool) (E:(A->bool)->bool) (q:num->A) n r <=>
    euler_planar_rotation V E r /\
    graph_face E r (q 0,q 1) = cyclic_darts q n`;;

let BOUNDARY_EULER_TRIANGLE_ROTATION = prove
 (`!q:num->A.
        INJ q (cyclic_indices 3) (:A)
        ==> boundary_euler_rotation
             (cyclic_vertices q 3)
             (cyclic_edges q 3) q 3
             (triangle_rotation (q 0) (q 1) (q 2))`,
  GEN_TAC THEN DISCH_THEN(LABEL_TAC "injective") THEN
  SUBGOAL_THEN
   `~((q:num->A) 0 = q 1) /\
    ~(q 1 = q 2) /\
    ~(q 2 = q 0)`
  (CONJUNCTS_THEN2 (LABEL_TAC "q01")
    (CONJUNCTS_THEN2 (LABEL_TAC "q12") (LABEL_TAC "q20"))) THENL
   [USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; CYCLIC_INDICES_3;
                IN_INSERT; NOT_IN_EMPTY] THEN
    MESON_TAC[ARITH_RULE `~(0 = 1) /\ ~(1 = 2) /\ ~(2 = 0)`];
    ALL_TAC] THEN
  REWRITE_TAC[boundary_euler_rotation; CYCLIC_VERTICES_3;
              CYCLIC_EDGES_3; CYCLIC_DARTS_3] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC EULER_PLANAR_TRIANGLE_ROTATION THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC GRAPH_FACE_TRIANGLE_OUTER THEN
    ASM_REWRITE_TAC[]]);;

let BOUNDARY_EULER_TRIANGLE_ROTATION_EXISTS = prove
 (`!q:num->A.
        INJ q (cyclic_indices 3) (:A)
        ==> ?r:(A#A)->A#A.
              boundary_euler_rotation
               (cyclic_vertices q 3)
               (cyclic_edges q 3) q 3 r`,
  MESON_TAC[BOUNDARY_EULER_TRIANGLE_ROTATION]);;

(* ------------------------------------------------------------------------- *)
(* Local successor characterizations of directed boundary faces.             *)
(* ------------------------------------------------------------------------- *)

let cyclic_dart = new_definition
 `cyclic_dart (q:num->A) n i = (q i,q ((i + 1) MOD n))`;;

let cyclic_face_successors = new_definition
 `cyclic_face_successors
    (E:(A->bool)->bool) (r:(A#A)->A#A) (q:num->A) n <=>
    !i. i < n
        ==> graph_face_successor E r (cyclic_dart q n i) =
            cyclic_dart q n ((i + 1) MOD n)`;;

let IN_CYCLIC_DARTS_CYCLIC_DART = prove
 (`!q:num->A. !n d.
        d IN cyclic_darts q n <=>
        ?i. i < n /\ d = cyclic_dart q n i`,
  REWRITE_TAC[IN_CYCLIC_DARTS; cyclic_dart]);;

let CYCLIC_DART_DISTINCT = prove
 (`!q:num->A. !n i j.
        INJ q (cyclic_indices n) (:A) /\
        i < n /\ j < n /\ ~(i = j)
        ==> ~(cyclic_dart q n i = cyclic_dart q n j)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "injective i_index j_index distinct" THEN
  DISCH_THEN(MP_TAC o AP_TERM `FST:A#A->A`) THEN
  REWRITE_TAC[cyclic_dart; FST] THEN
  DISCH_THEN(LABEL_TAC "same_vertex") THEN
  USE_THEN "distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
  USE_THEN "injective" MP_TAC THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
  DISCH_THEN(MATCH_MP_TAC o SPECL [`i:num`; `j:num`]) THEN
  ASM_REWRITE_TAC[]);;

let SIMPLE_GRAPH_CYCLE_CYCLIC_DART = prove
  (`!E:(A->bool)->bool. !q:num->A. !n i.
        simple_graph_cycle E q n /\
        i < n
        ==> cyclic_dart q n i IN graph_darts E`,
  REPEAT GEN_TAC THEN INTRO_TAC "cycle index" THEN
  REWRITE_TAC[cyclic_dart; IN_GRAPH_DARTS; DART_EDGE_PAIR] THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective edges" THEN
  USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
  REWRITE_TAC[IN_CYCLIC_EDGES] THEN
  EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[]);;

let CYCLIC_FACE_SUCCESSORS_ITER = prove
 (`!E r q:num->A. !n.
        2 <= n /\ cyclic_face_successors E r q n
        ==> !m.
              ITER m (graph_face_successor E r) (q 0,q 1) =
              cyclic_dart q n (m MOD n)`,
  REPEAT GEN_TAC THEN INTRO_TAC "large successors" THEN
  INDUCT_TAC THENL
   [SUBGOAL_THEN `0 MOD n = 0` (LABEL_TAC "mod0") THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `1 MOD n = 1` (LABEL_TAC "mod1") THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[ITER; cyclic_dart; ADD_CLAUSES];
    REWRITE_TAC[ITER] THEN
    FIRST_X_ASSUM(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "successors" MP_TAC THEN
    REWRITE_TAC[cyclic_face_successors] THEN
    DISCH_THEN(MP_TAC o SPEC `m MOD n`) THEN
    ANTS_TAC THENL
     [ASM_SIMP_TAC[MOD_LT] THEN ASM_ARITH_TAC;
      REWRITE_TAC[MOD_ADD_LEFT_REDUCE; ADD1]]]);;

let CYCLIC_FACE_SUCCESSORS_IMP_GRAPH_FACE = prove
 (`!E r q:num->A. !n.
        2 <= n /\ cyclic_face_successors E r q n
        ==> graph_face E r (q 0,q 1) = cyclic_darts q n`,
  REPEAT GEN_TAC THEN INTRO_TAC "large successors" THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_GRAPH_FACE] THEN
    X_GEN_TAC `d:A#A` THEN
    DISCH_THEN(X_CHOOSE_THEN `m:num` (SUBST1_TAC o SYM)) THEN
    REWRITE_TAC[IN_CYCLIC_DARTS_CYCLIC_DART] THEN
    EXISTS_TAC `m MOD n` THEN CONJ_TAC THENL
     [ASM_SIMP_TAC[MOD_LT] THEN ASM_ARITH_TAC;
      MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `q:num->A`; `n:num`] CYCLIC_FACE_SUCCESSORS_ITER) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o SPEC `m:num`) THEN REWRITE_TAC[]];
    REWRITE_TAC[SUBSET; IN_CYCLIC_DARTS_CYCLIC_DART;
                IN_GRAPH_FACE] THEN
    X_GEN_TAC `d:A#A` THEN
    INTRO_TAC "@i. index dart" THEN
    USE_THEN "dart" SUBST1_TAC THEN
    EXISTS_TAC `i:num` THEN
    MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `q:num->A`; `n:num`] CYCLIC_FACE_SUCCESSORS_ITER) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `i:num`) THEN
    ASM_SIMP_TAC[MOD_LT]]);;

let GRAPH_FACE_IMP_CYCLIC_FACE_SUCCESSORS = prove
 (`!E r q:num->A. !n.
        2 <= n /\
        INJ q (cyclic_indices n) (:A) /\
        cyclic_edges q n SUBSET E /\
        graph_rotation E r /\
        graph_face E r (q 0,q 1) = cyclic_darts q n
        ==> cyclic_face_successors E r q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "large injective edges rotation face" THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
  ABBREV_TAC `j = (i + 1) MOD n` THEN
  SUBGOAL_THEN `(j:num) < n` (LABEL_TAC "next_index") THENL
   [EXPAND_TAC "j" THEN ASM_SIMP_TAC[MOD_LT] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n i IN cyclic_darts q n`
  (LABEL_TAC "boundary_dart") THENL
   [REWRITE_TAC[IN_CYCLIC_DARTS_CYCLIC_DART] THEN
    EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n i IN graph_darts E`
  (LABEL_TAC "graph_dart") THENL
   [USE_THEN "edges" (fun edges_th ->
      MP_TAC(MATCH_MP
       (ISPECL [`E:(A->bool)->bool`; `q:num->A`; `n:num`]
        CYCLIC_DARTS_SUBSET_GRAPH_DARTS)
       edges_th)) THEN
    REWRITE_TAC[SUBSET] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    USE_THEN "boundary_dart" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (cyclic_dart (q:num->A) n i) IN
    graph_face E r (q 0,q 1)`
  (LABEL_TAC "successor_in_face") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `(q 0,q 1):A#A`; `cyclic_dart q n i:A#A`;
      `graph_face_successor E r (cyclic_dart q n i):A#A`]
     GRAPH_FACE_TRANS) THEN
    CONJ_TAC THENL
     [USE_THEN "face" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "boundary_dart" ACCEPT_TAC;
      MATCH_ACCEPT_TAC GRAPH_FACE_SUCCESSOR_IN_FACE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (cyclic_dart (q:num->A) n i) IN
    cyclic_darts q n`
  MP_TAC THENL
   [USE_THEN "face" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "successor_in_face" ACCEPT_TAC;
    REWRITE_TAC[IN_CYCLIC_DARTS_CYCLIC_DART] THEN
    INTRO_TAC "@k. k_index successor"] THEN
  SUBGOAL_THEN `(k:num) = j` (LABEL_TAC "same_index") THENL
   [USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    DISCH_THEN(MATCH_MP_TAC o SPECL [`k:num`; `j:num`]) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(AP_TERM `FST:A#A->A`
     (ASSUME
       `graph_face_successor E r (cyclic_dart (q:num->A) n i) =
        cyclic_dart q n k`)) THEN
    REWRITE_TAC[cyclic_dart; FST] THEN
    MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `cyclic_dart (q:num->A) n i`]
     GRAPH_FACE_SUCCESSOR_TAIL) THEN
    ASM_REWRITE_TAC[cyclic_dart; SND] THEN
    EXPAND_TAC "j" THEN MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "same_index" SUBST_ALL_TAC THEN
  USE_THEN "successor" ACCEPT_TAC);;

let BOUNDARY_EULER_ROTATION_IMP_CYCLIC_FACE_SUCCESSORS = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n r.
        2 <= n /\
        INJ q (cyclic_indices n) (:A) /\
        cyclic_edges q n SUBSET E /\
        boundary_euler_rotation V E q n r
        ==> cyclic_face_successors E r q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "large injective edges boundary" THEN
  MATCH_MP_TAC GRAPH_FACE_IMP_CYCLIC_FACE_SUCCESSORS THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "boundary" MP_TAC THEN
  REWRITE_TAC[boundary_euler_rotation; euler_planar_rotation] THEN
  MESON_TAC[]);;

let BOUNDARY_EULER_ROTATION_OF_CYCLIC_FACE_SUCCESSORS = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n r.
        2 <= n /\
        euler_planar_rotation V E r /\
        cyclic_face_successors E r q n
        ==> boundary_euler_rotation V E q n r`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "large euler successors" THEN
  REWRITE_TAC[boundary_euler_rotation] THEN
  CONJ_TAC THENL
   [USE_THEN "euler" ACCEPT_TAC;
    MATCH_MP_TAC CYCLIC_FACE_SUCCESSORS_IMP_GRAPH_FACE THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Directed-face effects of inserting an edge into a graph rotation.         *)
(* ------------------------------------------------------------------------- *)

let GRAPH_FACE_SUCCESSOR_INSERT_EDGE_VALUES = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v:A. !a b:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        ~(u = v) /\
        ~({u,v} IN E) /\
        a IN outgoing_darts E u /\
        b IN outgoing_darts E v
        ==> let r' =
              permutation_insert
               (permutation_insert r (u,v) a)
               (v,u) b in
            graph_face_successor
             ({u,v} INSERT E) r' (reverse_dart a) = (u,v) /\
            graph_face_successor
             ({u,v} INSERT E) r' (u,v) = r b /\
            graph_face_successor
             ({u,v} INSERT E) r' (reverse_dart b) = (v,u) /\
            graph_face_successor
             ({u,v} INSERT E) r' (v,u) = r a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation distinct new_edge a_anchor b_anchor" THEN
  LET_TAC THEN
  USE_THEN "a_anchor" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "a_dart a_tail" THEN
  USE_THEN "b_anchor" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "b_dart b_tail" THEN
  SUBGOAL_THEN `~((a:A#A) = b)` (LABEL_TAC "anchors_distinct") THENL
   [DISCH_THEN(LABEL_TAC "equal") THEN
    USE_THEN "distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((u:A),(v:A)) IN graph_darts E) /\
    ~(((v:A),(u:A)) IN graph_darts E)`
  (CONJUNCTS_THEN2 (LABEL_TAC "forward_fresh")
    (LABEL_TAC "reverse_fresh")) THENL
   [ASM_REWRITE_TAC[IN_GRAPH_DARTS;
                    SET_RULE `{v:A,u} = {u,v}`];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A,v:A) = (v,u))`
  (LABEL_TAC "new_darts_distinct") THENL
   [REWRITE_TAC[PAIR_EQ] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) a IN graph_darts E /\
    r b IN graph_darts E`
  (CONJUNCTS_THEN2 (LABEL_TAC "ra_dart")
    (LABEL_TAC "rb_dart")) THENL
   [CONJ_TAC THEN MATCH_MP_TAC GRAPH_ROTATION_IN THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((r:(A#A)->A#A) a = r b)`
  (LABEL_TAC "images_distinct") THENL
   [MP_TAC(SPECL [`a:A#A`; `b:A#A`]
     (MATCH_MP
      (ISPECL
       [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`]
       PERMUTES_INJECTIVE)
      (MATCH_MP
       (ISPECL
        [`E:(A->bool)->bool`; `r:(A#A)->A#A`]
        GRAPH_ROTATION_PERMUTES)
       (ASSUME `graph_rotation E (r:(A#A)->A#A)`)))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (reverse_dart(a:A#A)) = r a /\
    graph_face_successor E r (reverse_dart(b:A#A)) = r b`
  (CONJUNCTS_THEN2 (LABEL_TAC "ga") (LABEL_TAC "gb")) THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `reverse_dart(a:A#A)`] GRAPH_FACE_SUCCESSOR_IN);
      MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `reverse_dart(b:A#A)`] GRAPH_FACE_SUCCESSOR_IN)] THEN
    ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE; REVERSE_DART_INVOLUTION];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (u:A,v:A) = (u,v) /\
    graph_face_successor E r (v:A,u:A) = (v,u)`
  (CONJUNCTS_THEN2 (LABEL_TAC "gx") (LABEL_TAC "gy")) THENL
   [CONJ_TAC THEN
    MATCH_MP_TAC(CONJUNCT1(REWRITE_RULE[permutes]
     (MATCH_MP
      (ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`]
       GRAPH_FACE_SUCCESSOR_PERMUTES)
      (ASSUME `graph_rotation E (r:(A#A)->A#A)`)))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((r:(A#A)->A#A) a = (u,v)) /\
    ~(r a = (v,u)) /\
    ~(r b = (u,v)) /\
    ~(r b = (v,u))`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN DISCH_THEN(LABEL_TAC "equal") THENL
     [USE_THEN "forward_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "ra_dart" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "reverse_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "ra_dart" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "forward_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "rb_dart" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "reverse_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "rb_dart" (ACCEPT_TAC o REWRITE_RULE[th]))];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `a:A#A`; `b:A#A`]
   GRAPH_FACE_SUCCESSOR_INSERT_EDGE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "successor") THEN
  REPEAT CONJ_TAC THEN
  USE_THEN "successor" (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[permutation_insert; o_THM] THEN
  ASM_SIMP_TAC[SWAP_LEFT; SWAP_RIGHT; SWAP_OTHER]);;

let GRAPH_FACE_SUCCESSOR_INSERT_PENDANT_VALUES = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v:A. !a:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        u IN V /\
        ~(v IN V) /\
        a IN outgoing_darts E u
        ==> let r' = permutation_insert r (u,v) a in
            graph_face_successor
             ({u,v} INSERT E) r' (reverse_dart a) = (u,v) /\
            graph_face_successor
             ({u,v} INSERT E) r' (u,v) = (v,u) /\
            graph_face_successor
             ({u,v} INSERT E) r' (v,u) = r a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation u_vertex v_fresh anchor" THEN
  LET_TAC THEN
  SUBGOAL_THEN `~(u:A = v)` (LABEL_TAC "distinct") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "anchor" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "anchor_dart anchor_tail" THEN
  SUBGOAL_THEN
   `~(((u:A),(v:A)) IN graph_darts E) /\
    ~(((v:A),(u:A)) IN graph_darts E)`
  (CONJUNCTS_THEN2 (LABEL_TAC "forward_fresh")
    (LABEL_TAC "reverse_fresh")) THENL
   [CONJ_TAC THEN DISCH_THEN(LABEL_TAC "old_dart") THEN
    USE_THEN "v_fresh" (MATCH_MP_TAC o NOT_ELIM) THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `u:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A,v:A) = (v,u))`
  (LABEL_TAC "new_darts_distinct") THENL
   [REWRITE_TAC[PAIR_EQ] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:(A#A)->A#A) a IN graph_darts E`
  (LABEL_TAC "ra_dart") THENL
   [MATCH_MP_TAC GRAPH_ROTATION_IN THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((r:(A#A)->A#A) a = (u,v)) /\
    ~(r a = (v,u))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN DISCH_THEN(LABEL_TAC "equal") THENL
     [USE_THEN "forward_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "ra_dart" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "reverse_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "ra_dart" (ACCEPT_TAC o REWRITE_RULE[th]))];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (reverse_dart(a:A#A)) = r a`
  (LABEL_TAC "ga") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `reverse_dart(a:A#A)`] GRAPH_FACE_SUCCESSOR_IN) THEN
    ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE; REVERSE_DART_INVOLUTION];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (u:A,v:A) = (u,v) /\
    graph_face_successor E r (v:A,u:A) = (v,u)`
  (CONJUNCTS_THEN2 (LABEL_TAC "gx") (LABEL_TAC "gy")) THENL
   [CONJ_TAC THEN
    MATCH_MP_TAC(CONJUNCT1(REWRITE_RULE[permutes]
     (MATCH_MP
      (ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`]
       GRAPH_FACE_SUCCESSOR_PERMUTES)
      (ASSUME `graph_rotation E (r:(A#A)->A#A)`)))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `a:A#A`]
   GRAPH_FACE_SUCCESSOR_INSERT_PENDANT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "successor") THEN
  REPEAT CONJ_TAC THEN
  USE_THEN "successor" (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[permutation_insert; o_THM] THEN
  ASM_SIMP_TAC[SWAP_LEFT; SWAP_RIGHT; SWAP_OTHER]);;

(* Inserting an edge leaves unaffected old face successors unchanged.        *)

let GRAPH_FACE_SUCCESSOR_INSERT_EDGE_UNCHANGED = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v:A. !a b d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        ~(u = v) /\
        ~({u,v} IN E) /\
        a IN outgoing_darts E u /\
        b IN outgoing_darts E v /\
        d IN graph_darts E /\
        ~(d = reverse_dart a) /\
        ~(d = reverse_dart b)
        ==> graph_face_successor
             ({u,v} INSERT E)
             (permutation_insert
               (permutation_insert r (u,v) a)
               (v,u) b) d =
            graph_face_successor E r d`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph rotation distinct new_edge a_anchor b_anchor
    d_dart not_a not_b" THEN
  USE_THEN "a_anchor" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "a_dart a_tail" THEN
  USE_THEN "b_anchor" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "b_dart b_tail" THEN
  SUBGOAL_THEN `~((a:A#A) = b)` (LABEL_TAC "anchors_distinct") THENL
   [DISCH_THEN(LABEL_TAC "equal") THEN
    USE_THEN "distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((r:(A#A)->A#A) a = r b)`
  (LABEL_TAC "images_distinct") THENL
   [MP_TAC(SPECL [`a:A#A`; `b:A#A`]
     (MATCH_MP
      (ISPECL
       [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`]
       PERMUTES_INJECTIVE)
      (MATCH_MP
       (ISPECL
        [`E:(A->bool)->bool`; `r:(A#A)->A#A`]
        GRAPH_ROTATION_PERMUTES)
       (ASSUME `graph_rotation E (r:(A#A)->A#A)`)))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((u:A),(v:A)) IN graph_darts E) /\
    ~(((v:A),(u:A)) IN graph_darts E)`
  (CONJUNCTS_THEN2 (LABEL_TAC "forward_fresh")
    (LABEL_TAC "reverse_fresh")) THENL
   [ASM_REWRITE_TAC[IN_GRAPH_DARTS;
                    SET_RULE `{v:A,u} = {u,v}`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(a:A#A) IN graph_darts E /\
    reverse_dart(b:A#A) IN graph_darts E`
  (CONJUNCTS_THEN2 (LABEL_TAC "reverse_a_dart")
    (LABEL_TAC "reverse_b_dart")) THENL
   [ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(graph_face_successor
      (E:(A->bool)->bool) (r:(A#A)->A#A)) permutes graph_darts E`
  (LABEL_TAC "face_permutation") THENL
   [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (d:A#A) IN graph_darts E`
  (LABEL_TAC "gd_dart") THENL
   [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_DART THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (reverse_dart(a:A#A)) = r a /\
    graph_face_successor E r (reverse_dart(b:A#A)) = r b`
  (CONJUNCTS_THEN2 (LABEL_TAC "ga") (LABEL_TAC "gb")) THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `reverse_dart(a:A#A)`] GRAPH_FACE_SUCCESSOR_IN);
      MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `reverse_dart(b:A#A)`] GRAPH_FACE_SUCCESSOR_IN)] THEN
    ASM_REWRITE_TAC[REVERSE_DART_INVOLUTION];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (u:A,v:A) = (u,v)`
  (LABEL_TAC "gx") THENL
   [MATCH_MP_TAC(CONJUNCT1(REWRITE_RULE[permutes]
     (ASSUME
      `(graph_face_successor
         (E:(A->bool)->bool) (r:(A#A)->A#A))
       permutes graph_darts E`))) THEN
    USE_THEN "forward_fresh" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(graph_face_successor E r (d:A#A) = r a) /\
    ~(graph_face_successor E r d = r b)`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN DISCH_THEN(LABEL_TAC "equal") THENL
     [USE_THEN "not_a" (MATCH_MP_TAC o NOT_ELIM) THEN
      MP_TAC(SPECL [`d:A#A`; `reverse_dart(a:A#A)`]
       (MATCH_MP
        (ISPECL
         [`graph_face_successor E r:(A#A)->A#A`;
          `graph_darts E:A#A->bool`] PERMUTES_INJECTIVE)
        (ASSUME
         `(graph_face_successor
            (E:(A->bool)->bool) (r:(A#A)->A#A))
          permutes graph_darts E`))) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "not_b" (MATCH_MP_TAC o NOT_ELIM) THEN
      MP_TAC(SPECL [`d:A#A`; `reverse_dart(b:A#A)`]
       (MATCH_MP
        (ISPECL
         [`graph_face_successor E r:(A#A)->A#A`;
          `graph_darts E:A#A->bool`] PERMUTES_INJECTIVE)
        (ASSUME
         `(graph_face_successor
            (E:(A->bool)->bool) (r:(A#A)->A#A))
          permutes graph_darts E`))) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(graph_face_successor E r (d:A#A) = (u,v)) /\
    ~(graph_face_successor E r d = (v,u)) /\
    ~((r:(A#A)->A#A) a = (u,v)) /\
    ~(r a = (v,u)) /\
    ~(r b = (u,v)) /\
    ~(r b = (v,u))`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN DISCH_THEN(LABEL_TAC "equal") THENL
     [USE_THEN "forward_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "gd_dart" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "reverse_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "gd_dart" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "forward_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       MP_TAC(ISPECL
        [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `a:A#A`]
        GRAPH_ROTATION_IN) THEN ASM_REWRITE_TAC[th]);
      USE_THEN "reverse_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       MP_TAC(ISPECL
        [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `a:A#A`]
        GRAPH_ROTATION_IN) THEN ASM_REWRITE_TAC[th]);
      USE_THEN "forward_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       MP_TAC(ISPECL
        [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `b:A#A`]
        GRAPH_ROTATION_IN) THEN ASM_REWRITE_TAC[th]);
      USE_THEN "reverse_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       MP_TAC(ISPECL
        [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `b:A#A`]
        GRAPH_ROTATION_IN) THEN ASM_REWRITE_TAC[th])];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `a:A#A`; `b:A#A`]
   GRAPH_FACE_SUCCESSOR_INSERT_EDGE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[permutation_insert; o_THM] THEN
  ASM_SIMP_TAC[SWAP_OTHER]);;

(* The corresponding fact for inserting a pendant edge.                     *)

let GRAPH_FACE_SUCCESSOR_INSERT_PENDANT_UNCHANGED = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v:A. !a d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
