        a IN outgoing_darts E u /\
        d IN graph_darts E /\
        ~(d = reverse_dart a)
        ==> graph_face_successor
             ({u,v} INSERT E)
             (permutation_insert r (u,v) a) d =
            graph_face_successor E r d`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation u_vertex v_fresh anchor d_dart not_a" THEN
  SUBGOAL_THEN `~(u:A = v)` (LABEL_TAC "distinct") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "anchor" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "anchor_dart anchor_tail" THEN
  SUBGOAL_THEN
   `~(((u:A),(v:A)) IN graph_darts E) /\
    ~(((v:A),(u:A)) IN graph_darts E)`
  (CONJUNCTS_THEN2 (LABEL_TAC "forward_fresh")
    (LABEL_TAC "reverse_fresh")) THENL
   [CONJ_TAC THEN DISCH_THEN(LABEL_TAC "old_dart") THEN
    USE_THEN "v_fresh" (MATCH_MP_TAC o NOT_ELIM) THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN ASM_REWRITE_TAC[];
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `u:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(graph_face_successor
      (E:(A->bool)->bool) (r:(A#A)->A#A)) permutes graph_darts E`
  (LABEL_TAC "face_permutation") THENL
   [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(a:A#A) IN graph_darts E /\
    graph_face_successor E r (d:A#A) IN graph_darts E /\
    (r:(A#A)->A#A) a IN graph_darts E`
  (CONJUNCTS_THEN2 (LABEL_TAC "reverse_a_dart")
    (CONJUNCTS_THEN2 (LABEL_TAC "gd_dart") (LABEL_TAC "ra_dart"))) THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE];
      MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_DART THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC GRAPH_ROTATION_IN THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (reverse_dart(a:A#A)) = r a`
  (LABEL_TAC "ga") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `reverse_dart(a:A#A)`] GRAPH_FACE_SUCCESSOR_IN) THEN
    ASM_REWRITE_TAC[REVERSE_DART_INVOLUTION];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (u:A,v:A) = (u,v)`
  (LABEL_TAC "gx") THENL
   [MATCH_MP_TAC(CONJUNCT1(REWRITE_RULE[permutes]
     (ASSUME
      `(graph_face_successor
         (E:(A->bool)->bool) (r:(A#A)->A#A))
       permutes graph_darts E`))) THEN
    USE_THEN "forward_fresh" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(graph_face_successor E r (d:A#A) = r a)`
  (LABEL_TAC "not_ra") THENL
   [DISCH_THEN(LABEL_TAC "equal") THEN
    USE_THEN "not_a" (MATCH_MP_TAC o NOT_ELIM) THEN
    MP_TAC(SPECL [`d:A#A`; `reverse_dart(a:A#A)`]
     (MATCH_MP
      (ISPECL
       [`graph_face_successor E r:(A#A)->A#A`;
        `graph_darts E:A#A->bool`] PERMUTES_INJECTIVE)
      (ASSUME
       `(graph_face_successor
          (E:(A->bool)->bool) (r:(A#A)->A#A))
        permutes graph_darts E`))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(graph_face_successor E r (d:A#A) = (u,v)) /\
    ~(graph_face_successor E r d = (v,u)) /\
    ~((r:(A#A)->A#A) a = (u,v)) /\
    ~(r a = (v,u))`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN DISCH_THEN(LABEL_TAC "equal") THENL
     [USE_THEN "forward_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "gd_dart" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "reverse_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "gd_dart" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "forward_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "ra_dart" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "reverse_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "equal" (fun th ->
       USE_THEN "ra_dart" (ACCEPT_TAC o REWRITE_RULE[th]))];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `a:A#A`]
   GRAPH_FACE_SUCCESSOR_INSERT_PENDANT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[permutation_insert; o_THM] THEN
  ASM_SIMP_TAC[SWAP_LEFT; SWAP_OTHER]);;

(* ------------------------------------------------------------------------- *)
(* Definitions and elementary lemmas for adding a fan from a fresh vertex.   *)
(* ------------------------------------------------------------------------- *)

let fan_edges = new_recursive_definition num_RECURSION
 `(fan_edges (x:A) (w:num->A) (E:(A->bool)->bool) 0 =
      {x,w 0} INSERT E) /\
  (fan_edges x w E (SUC t) =
      {x,w (SUC t)} INSERT fan_edges x w E t)`;;

let fan_rotation = new_recursive_definition num_RECURSION
 `(fan_rotation (x:A) (w:num->A) (p:A#A)
                (r:(A#A)->A#A) 0 =
      permutation_insert r (w 0,x) (reverse_dart p)) /\
  (fan_rotation x w p r (SUC t) =
      permutation_insert
       (permutation_insert
         (fan_rotation x w p r t)
       (x,w (SUC t)) (x,w 0))
       (w (SUC t),x) (w (SUC t),w t))`;;

let FAN_EDGE_IN = prove
 (`!x:A. !w:num->A. !E h i.
        i <= h ==> {x,w i} IN fan_edges x w E h`,
  REPEAT GEN_TAC THEN SPEC_TAC(`h:num`,`h:num`) THEN
  INDUCT_TAC THENL
   [REWRITE_TAC[LE; fan_edges; IN_INSERT] THEN MESON_TAC[];
    DISCH_THEN(DISJ_CASES_THEN2 SUBST1_TAC
      (LABEL_TAC "earlier") o REWRITE_RULE[LE]) THENL
     [REWRITE_TAC[fan_edges; IN_INSERT];
      REWRITE_TAC[fan_edges; IN_INSERT] THEN DISJ2_TAC THEN
      FIRST_X_ASSUM MATCH_MP_TAC THEN
      USE_THEN "earlier" ACCEPT_TAC]]);;

let FAN_EDGES_EXPLICIT = prove
 (`!x:A. !w:num->A. !E h.
        fan_edges x w E h =
        IMAGE (\i. {x,w i}) (0..h) UNION E`,
  REPEAT GEN_TAC THEN SPEC_TAC(`h:num`,`h:num`) THEN INDUCT_TAC THENL
   [REWRITE_TAC[fan_edges; NUMSEG_SING; IMAGE_CLAUSES; UNION_EMPTY] THEN
    SET_TAC[];
    REWRITE_TAC[fan_edges; NUMSEG_CLAUSES; IMAGE_CLAUSES;
                ARITH_RULE `0 <= SUC h`] THEN
    ASM SET_TAC[]]);;

let FAN_EDGES_MONO = prove
 (`!x:A. !w:num->A. !E t.
        E SUBSET fan_edges x w E t`,
  REWRITE_TAC[FAN_EDGES_EXPLICIT] THEN SET_TAC[]);;

let FAN_EDGES_CYCLIC_VERTICES = prove
  (`!x:A. !w:num->A. !E h.
        fan_edges x w E h =
        IMAGE (\u. {x,u}) (cyclic_vertices w (h + 1)) UNION E`,
  REPEAT GEN_TAC THEN REWRITE_TAC[FAN_EDGES_EXPLICIT;
    cyclic_vertices; cyclic_indices; NUMSEG_LT; GSYM IMAGE_o; o_DEF;
    ARITH_RULE `~(h + 1 = 0)`] THEN
  SUBGOAL_THEN `(h + 1) - 1 = h` SUBST1_TAC THENL
   [ARITH_TAC;
    REFL_TAC]);;

let FAN_EDGE_FRESH = prove
 (`!V:A->bool. !E:(A->bool)->bool. !x w h t.
        finite_simple_graph V E /\
        ~(x IN V) /\
        INJ w (cyclic_indices (h + 1)) (:A) /\
        (!i. i <= h ==> w i IN V) /\
        t < h
        ==> ~({x,w (SUC t)} IN fan_edges x w E t)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph x_fresh injective vertices bound" THEN
  REWRITE_TAC[FAN_EDGES_EXPLICIT; IN_UNION; IN_IMAGE] THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (X_CHOOSE_THEN `i:num`
    (CONJUNCTS_THEN2 (LABEL_TAC "edge_equal")
     (LABEL_TAC "index")))
   (LABEL_TAC "old_edge")) THENL
   [SUBGOAL_THEN
     `(w:num->A) i IN V /\ w (SUC t) IN V`
    (CONJUNCTS_THEN2 (LABEL_TAC "wi_vertex")
      (LABEL_TAC "ws_vertex")) THENL
     [CONJ_TAC THEN USE_THEN "vertices" MATCH_MP_TAC THEN
      USE_THEN "index" MP_TAC THEN
      REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((x:A) = w i) /\ ~(x = w (SUC t))`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(w:num->A) i = w (SUC t)`
    (LABEL_TAC "same_vertex") THENL
     [USE_THEN "edge_equal" MP_TAC THEN ASM SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(i:num) = SUC t` (LABEL_TAC "same_index") THENL
     [USE_THEN "injective" MP_TAC THEN
      REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
      DISCH_THEN(MATCH_MP_TAC o SPECL [`i:num`; `SUC t`]) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "index" MP_TAC THEN
      REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC;
      USE_THEN "index" MP_TAC THEN
      REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC];
    USE_THEN "x_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `x:A`; `(w:num->A) (SUC t)`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS]]);;

let GRAPH_DART_NE_FRESH_VERTEX = prove
 (`!V:A->bool. !E:(A->bool)->bool. !x d u.
        finite_simple_graph V E /\
        ~(x IN V) /\
        d IN graph_darts E
        ==> ~(d = (x,u)) /\ ~(d = (u,x))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph fresh dart" THEN
  CONJ_TAC THEN DISCH_THEN(LABEL_TAC "equal") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `x:A`; `u:A`]
     FINITE_SIMPLE_GRAPH_DART);
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `x:A`]
     FINITE_SIMPLE_GRAPH_DART)] THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "equal" (fun th ->
    USE_THEN "dart" (ACCEPT_TAC o REWRITE_RULE[th])));;

let FAN_PATH_DART_DISTINCT = prove
 (`!w:num->A. !h i j.
        INJ w (cyclic_indices (h + 1)) (:A) /\
        i < h /\ j < h /\ ~(i = j)
        ==> ~((w i,w (SUC i)) = (w j,w (SUC j)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "injective i_index j_index distinct" THEN
  DISCH_THEN(MP_TAC o AP_TERM `FST:A#A->A`) THEN
  REWRITE_TAC[FST] THEN DISCH_THEN(LABEL_TAC "same_vertex") THEN
  USE_THEN "distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
  USE_THEN "injective" MP_TAC THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
  DISCH_THEN(MATCH_MP_TAC o SPECL [`i:num`; `j:num`]) THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let fan_source_dart = new_recursive_definition num_RECURSION
 `(fan_source_dart (p:A#A) (w:num->A) 0 = p) /\
  (fan_source_dart p w (SUC t) = (w t,w (SUC t)))`;;

(* ------------------------------------------------------------------------- *)
(* Euler-planar rotation surgery for adding a fan from a fresh vertex.       *)
(*                                                                           *)
(* Starting from a boundary path w(0),...,w(h), this repeatedly inserts the  *)
(* edges from a fresh vertex x.  The invariant records the resulting face    *)
(* successor chain as well as the old darts whose successors are unchanged.  *)
(* ------------------------------------------------------------------------- *)

let FAN_GRAPH_DARTS_MONO = prove
 (`!x:A. !w:num->A. !E t.
        graph_darts E SUBSET graph_darts (fan_edges x w E t)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[SUBSET; FORALL_PAIR_THM; IN_GRAPH_DARTS] THEN
  MESON_TAC[FAN_EDGES_MONO; SUBSET]);;

let fan_rotation_invariant = new_definition
 `fan_rotation_invariant
    (V:A->bool) (E:(A->bool)->bool) (r:(A#A)->A#A)
    (x:A) (w:num->A) (p:A#A) h t <=>
        euler_planar_rotation
         (x INSERT V) (fan_edges x w E t) (fan_rotation x w p r t) /\
        graph_face_successor
         (fan_edges x w E t) (fan_rotation x w p r t) p = (w 0,x) /\
        graph_face_successor
         (fan_edges x w E t) (fan_rotation x w p r t) (w 0,x) =
        (x,w t) /\
        graph_face_successor
         (fan_edges x w E t) (fan_rotation x w p r t) (x,w t) =
        graph_face_successor E r (fan_source_dart p w t) /\
        (!i. t <= i /\ i < h
             ==> graph_face_successor
                  (fan_edges x w E t) (fan_rotation x w p r t)
                  (w i,w (SUC i)) =
                 graph_face_successor E r (w i,w (SUC i))) /\
        (!d. d IN graph_darts E /\
             ~(d = p) /\
             (!i. i < h ==> ~(d = (w i,w (SUC i))))
             ==> graph_face_successor
                  (fan_edges x w E t) (fan_rotation x w p r t) d =
                 graph_face_successor E r d)`;;

let fan_rotation_induction_statement = new_definition
 `fan_rotation_induction_statement
    (V:A->bool) (E:(A->bool)->bool) (r:(A#A)->A#A)
    (x:A) (w:num->A) (p:A#A) h t <=>
        euler_planar_rotation V E r /\
        ~(x IN V) /\
        INJ w (cyclic_indices (h + 1)) (:A) /\
        (!i. i <= h ==> w i IN V) /\
        p IN graph_darts E /\
        SND p = w 0 /\
        (!i. i < h ==> (w i,w (SUC i)) IN graph_darts E) /\
        (!i. i < h ==> ~(p = (w i,w (SUC i)))) /\
        (!i. i < h
             ==> graph_face_successor E r (fan_source_dart p w i) =
                 (w i,w (SUC i)))
        ==> t <= h
        ==> fan_rotation_invariant V E r x w p h t`;;

let EXPAND_FAN_ROTATION_INVARIANT_TAC ((_,w) as g) =
  let eth0 = SPEC_ALL fan_rotation_invariant in
  let l,_ = dest_iff(concl eth0) in
  let eth = INSTANTIATE (term_match [] l w) eth0 in
  CONV_TAC (fun tm ->
    if aconv tm w then eth
    else failwith "EXPAND_FAN_ROTATION_INVARIANT_TAC") g;;
let FAN_ROTATION_INVARIANT_RULE th =
  let eth0 = SPEC_ALL fan_rotation_invariant in
  let l,_ = dest_iff(concl eth0) in
  EQ_MP (INSTANTIATE (term_match [] l (concl th)) eth0) th;;

let EXPAND_FAN_ROTATION_STATEMENT_TAC ((_,w) as g) =
  let eth0 = SPEC_ALL fan_rotation_induction_statement in
  let l,_ = dest_iff(concl eth0) in
  let eth = INSTANTIATE (term_match [] l w) eth0 in
  CONV_TAC (fun tm ->
    if aconv tm w then eth
    else failwith "EXPAND_FAN_ROTATION_STATEMENT_TAC") g;;

let FAN_ROTATION_STATEMENT_RULE th =
  let eth0 = SPEC_ALL fan_rotation_induction_statement in
  let l,_ = dest_iff(concl eth0) in
  EQ_MP (INSTANTIATE (term_match [] l (concl th)) eth0) th;;

let EULER_PLANAR_ROTATION_FAN_BASE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !p:A#A. !h.
        fan_rotation_induction_statement
         (V:A->bool) (E:(A->bool)->bool) (r:(A#A)->A#A)
         (x:A) (w:num->A) (p:A#A) h 0`,
  REPEAT GEN_TAC THEN
  EXPAND_FAN_ROTATION_STATEMENT_TAC THEN
  INTRO_TAC
     "euler fresh injective vertices p_dart p_head
      path_darts p_distinct chain" THEN
    USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN
    INTRO_TAC "graph rotation euler_formula" THEN
    SUBGOAL_THEN `(w:num->A) 0 IN V`
    (LABEL_TAC "base_vertex") THENL
     [USE_THEN "vertices" MATCH_MP_TAC THEN ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `reverse_dart(p:A#A) IN outgoing_darts E (w 0)`
    (LABEL_TAC "base_anchor") THENL
     [REWRITE_TAC[IN_OUTGOING_DARTS] THEN
      ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE; FST_REVERSE_DART];
      ALL_TAC] THEN
    REWRITE_TAC[LE_0] THEN
    EXPAND_FAN_ROTATION_INVARIANT_TAC THEN
    SUBGOAL_THEN
     `euler_planar_rotation
       ((x:A) INSERT (V:A->bool))
       (fan_edges x w (E:(A->bool)->bool) 0)
       (fan_rotation x w p (r:(A#A)->A#A) 0)`
    (LABEL_TAC "new_euler") THENL
     [REWRITE_TAC[fan_edges; fan_rotation] THEN
      ONCE_REWRITE_TAC[SET_RULE `{x:A,w 0} = {w 0,x}`] THEN
      MATCH_MP_TAC EULER_PLANAR_ROTATION_INSERT_PENDANT THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "euler" ACCEPT_TAC;
        USE_THEN "base_vertex" ACCEPT_TAC;
        USE_THEN "fresh" ACCEPT_TAC;
        USE_THEN "base_anchor" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_face_successor
       (fan_edges (x:A) (w:num->A) (E:(A->bool)->bool) 0)
       (fan_rotation x w p (r:(A#A)->A#A) 0) (p:A#A) = (w 0,x) /\
      graph_face_successor
       (fan_edges x w E 0) (fan_rotation x w p r 0) (w 0,x) =
       (x,w 0) /\
      graph_face_successor
       (fan_edges x w E 0) (fan_rotation x w p r 0) (x,w 0) =
       r(reverse_dart p)`
    (CONJUNCTS_THEN2 (LABEL_TAC "new_p")
      (CONJUNCTS_THEN2 (LABEL_TAC "new_first")
        (LABEL_TAC "new_last"))) THENL
     [REWRITE_TAC[fan_edges; fan_rotation] THEN
      ONCE_REWRITE_TAC[SET_RULE `{x:A,w 0} = {w 0,x}`] THEN
      MATCH_MP_TAC(REWRITE_RULE
       [LET_DEF; LET_END_DEF; REVERSE_DART_INVOLUTION]
       (ISPECL
        [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
         `(w:num->A) 0`; `x:A`; `reverse_dart(p:A#A)`]
        GRAPH_FACE_SUCCESSOR_INSERT_PENDANT_VALUES)) THEN
      ASM_REWRITE_TAC[REVERSE_DART_INVOLUTION];
      ALL_TAC] THEN
    USE_THEN "p_dart" (fun th ->
      LABEL_TAC "old_p_value"
       (MATCH_MP
        (ISPECL
         [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `p:A#A`]
         GRAPH_FACE_SUCCESSOR_IN)
        th)) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "new_euler" ACCEPT_TAC;
      USE_THEN "new_p" ACCEPT_TAC;
      USE_THEN "new_first" ACCEPT_TAC;
      REWRITE_TAC[fan_source_dart] THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `i:num` THEN INTRO_TAC "nonnegative index" THEN
      REWRITE_TAC[fan_edges; fan_rotation] THEN
      ONCE_REWRITE_TAC[SET_RULE `{x:A,w 0} = {w 0,x}`] THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `(w:num->A) 0`; `x:A`; `reverse_dart(p:A#A)`;
        `((w:num->A) i,w (SUC i)):A#A`]
       GRAPH_FACE_SUCCESSOR_INSERT_PENDANT_UNCHANGED) THEN
      ASM_REWRITE_TAC[REVERSE_DART_INVOLUTION] THEN ASM_MESON_TAC[];
      X_GEN_TAC `d:A#A` THEN INTRO_TAC "d_dart not_p avoids" THEN
      REWRITE_TAC[fan_edges; fan_rotation] THEN
      ONCE_REWRITE_TAC[SET_RULE `{x:A,w 0} = {w 0,x}`] THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `(w:num->A) 0`; `x:A`; `reverse_dart(p:A#A)`; `d:A#A`]
       GRAPH_FACE_SUCCESSOR_INSERT_PENDANT_UNCHANGED) THEN
      ASM_REWRITE_TAC[REVERSE_DART_INVOLUTION]]);;

let EULER_PLANAR_ROTATION_FAN_STEP = prove
 (`!t. !V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !p:A#A. !h.
        fan_rotation_induction_statement
         (V:A->bool) (E:(A->bool)->bool) (r:(A#A)->A#A)
         (x:A) (w:num->A) (p:A#A) h t
        ==> fan_rotation_induction_statement
             (V:A->bool) (E:(A->bool)->bool) (r:(A#A)->A#A)
             (x:A) (w:num->A) (p:A#A) h (SUC t)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(LABEL_TAC "induction") THEN
  EXPAND_FAN_ROTATION_STATEMENT_TAC THEN
  INTRO_TAC
     "euler fresh injective vertices p_dart p_head
      path_darts p_distinct chain" THEN
    USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN
    INTRO_TAC "graph rotation euler_formula" THEN
    DISCH_THEN(LABEL_TAC "step_bound") THEN
    EXPAND_FAN_ROTATION_INVARIANT_TAC THEN
    USE_THEN "induction"
     (MP_TAC o FAN_ROTATION_STATEMENT_RULE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      ANTS_TAC THENL
       [ASM_ARITH_TAC;
        DISCH_THEN(MP_TAC o FAN_ROTATION_INVARIANT_RULE) THEN
        INTRO_TAC
         "old_euler old_p old_first old_last
          old_future old_unchanged"]] THEN
    SUBGOAL_THEN `(t:num) < h` (LABEL_TAC "t_index") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "old_euler"
     (MP_TAC o REWRITE_RULE[euler_planar_rotation]) THEN
    INTRO_TAC "current_graph current_rotation current_formula" THEN
    SUBGOAL_THEN `(w:num->A) (SUC t) IN V`
    (LABEL_TAC "next_vertex") THENL
     [USE_THEN "vertices" MATCH_MP_TAC THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((x:A) = w (SUC t))`
    (LABEL_TAC "distinct") THENL
     [ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~({x:A,w (SUC t)} IN fan_edges x w E t)`
    (LABEL_TAC "new_edge") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `x:A`;
        `w:num->A`; `h:num`; `t:num`] FAN_EDGE_FRESH) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x:A,w 0) IN outgoing_darts (fan_edges x w E t) x`
    (LABEL_TAC "x_anchor") THENL
     [REWRITE_TAC[IN_OUTGOING_DARTS_PAIR] THEN
      MATCH_MP_TAC FAN_EDGE_IN THEN ARITH_TAC;
      ALL_TAC] THEN
    (fun (asl,_ as g) ->
      let path =
        MATCH_MP (SPEC `t:num` (assoc "path_darts" asl))
                 (assoc "t_index" asl) in
      let edge = REWRITE_RULE[IN_GRAPH_DARTS] path in
      let mono =
        REWRITE_RULE[SUBSET]
         (ISPECL
           [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `t:num`]
           FAN_EDGES_MONO) in
      let fan_edge = MATCH_MP mono edge in
      let reverse_edge =
        REWRITE_RULE
         [SET_RULE `{w t:A,w (SUC t)} = {w (SUC t),w t}`]
         fan_edge in
      let outgoing =
        EQ_MP
         (SYM(ISPECL
           [`fan_edges (x:A) (w:num->A) (E:(A->bool)->bool) t`;
            `(w:num->A) (SUC t)`; `(w:num->A) t`]
           IN_OUTGOING_DARTS_PAIR))
         reverse_edge in
      LABEL_TAC "w_anchor" outgoing g) THEN
    (fun (asl,_ as g) ->
      let path =
        MATCH_MP (SPEC `t:num` (assoc "path_darts" asl))
                 (assoc "t_index" asl) in
      let mono =
        REWRITE_RULE[SUBSET]
         (ISPECL
           [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `t:num`]
           FAN_GRAPH_DARTS_MONO) in
      LABEL_TAC "path_current" (MATCH_MP mono path) g) THEN
    (fun (asl,_ as g) ->
      let successor =
        `graph_face_successor
          (fan_edges (x:A) (w:num->A) (E:(A->bool)->bool) t)
          (fan_rotation x w (p:A#A) (r:(A#A)->A#A) t)` in
      let chain_t =
        MATCH_MP (SPEC `t:num` (assoc "chain" asl))
                 (assoc "t_index" asl) in
      let face_steps =
        TRANS (AP_TERM successor (assoc "old_first" asl))
         (TRANS (assoc "old_last" asl) chain_t) in
      let iter_prop =
        `ITER (SUC(SUC 0))
          (graph_face_successor
            (fan_edges (x:A) (w:num->A) (E:(A->bool)->bool) t)
            (fan_rotation x w (p:A#A) (r:(A#A)->A#A) t))
          (w 0,x) = (w t,w (SUC t))` in
      let iter_eq =
        EQ_MP (SYM(REWRITE_CONV[ITER] iter_prop)) face_steps in
      let face_exists =
        EXISTS
         (`?n. ITER n
            (graph_face_successor
              (fan_edges (x:A) (w:num->A) (E:(A->bool)->bool) t)
              (fan_rotation x w (p:A#A) (r:(A#A)->A#A) t))
            (w 0,x) = (w t,w (SUC t))`,
          `SUC(SUC 0)`)
         iter_eq in
      let cofacial =
        EQ_MP
         (SYM(ISPECL
           [`fan_edges x w E t:(A->bool)->bool`;
            `fan_rotation x w p r t:(A#A)->A#A`;
            `(w 0,x):A#A`; `(w t,w (SUC t)):A#A`]
           IN_GRAPH_FACE))
         face_exists in
      let next_in =
        MATCH_MP
         (SET_RULE `(y:A) IN V ==> y IN x INSERT V`)
         (assoc "next_vertex" asl) in
      let inserted =
        MATCH_MP
         (REWRITE_RULE[REVERSE_DART_PAIR]
           (ISPECL
             [`x INSERT V:A->bool`;
              `fan_edges x w E t:(A->bool)->bool`;
              `fan_rotation x w p r t:(A#A)->A#A`;
              `x:A`; `(w:num->A) (SUC t)`;
              `(x,w 0):A#A`; `(w (SUC t),w t):A#A`]
             EULER_PLANAR_ROTATION_INSERT_EDGE))
         (end_itlist CONJ
           [assoc "old_euler" asl;
            SET_RULE `(x:A) IN x INSERT V`;
            next_in;
            assoc "distinct" asl;
            assoc "new_edge" asl;
            assoc "x_anchor" asl;
            assoc "w_anchor" asl;
            cofacial]) in
      let new_euler =
        REWRITE_RULE
         [GSYM(CONJUNCT2 fan_edges); GSYM(CONJUNCT2 fan_rotation)]
         inserted in
      LABEL_TAC "new_euler" new_euler g) THEN
    (fun (asl,_ as g) ->
      let values =
        MATCH_MP
         (ISPECL
           [`x INSERT V:A->bool`;
            `fan_edges x w E t:(A->bool)->bool`;
            `fan_rotation x w p r t:(A#A)->A#A`;
            `x:A`; `(w:num->A) (SUC t)`;
            `(x,w 0):A#A`; `(w (SUC t),w t):A#A`]
           GRAPH_FACE_SUCCESSOR_INSERT_EDGE_VALUES)
         (end_itlist CONJ
           (map (fun s -> assoc s asl)
             ["current_graph"; "current_rotation"; "distinct";
              "new_edge"; "x_anchor"; "w_anchor"])) in
      let values' =
        REWRITE_RULE
         [LET_DEF; LET_END_DEF; REVERSE_DART_PAIR;
          GSYM(CONJUNCT2 fan_edges); GSYM(CONJUNCT2 fan_rotation)]
         values in
      let first = CONJUNCT1 values'
      and last = CONJUNCT1(CONJUNCT2 values') in
      (LABEL_TAC "new_first" first THEN
       LABEL_TAC "new_last_raw" last) g) THEN
    (fun (asl,_ as g) ->
      let old_path_value =
        REWRITE_RULE[REVERSE_DART_PAIR]
         (MATCH_MP
           (ISPECL
             [`fan_edges x w E t:(A->bool)->bool`;
              `fan_rotation x w p r t:(A#A)->A#A`;
              `(w t,w (SUC t)):A#A`]
             GRAPH_FACE_SUCCESSOR_IN)
           (assoc "path_current" asl)) in
      LABEL_TAC "old_path_value" old_path_value g) THEN
    (fun (asl,_ as g) ->
      let d = `d:A#A` in
      let condition =
        `(d:A#A) IN graph_darts
          (fan_edges (x:A) (w:num->A) (E:(A->bool)->bool) t) /\
         ~(d = (w 0,x)) /\
         ~(d = (w t,w (SUC t)))` in
      let condition_th = ASSUME condition in
      let d_dart = CONJUNCT1 condition_th
      and not_x = CONJUNCT1(CONJUNCT2 condition_th)
      and not_path = CONJUNCT2(CONJUNCT2 condition_th) in
      let unchanged =
        MATCH_MP
         (REWRITE_RULE[REVERSE_DART_PAIR]
           (ISPECL
             [`x INSERT V:A->bool`;
              `fan_edges x w E t:(A->bool)->bool`;
              `fan_rotation x w p r t:(A#A)->A#A`;
              `x:A`; `(w:num->A) (SUC t)`;
              `(x,w 0):A#A`; `(w (SUC t),w t):A#A`; d]
             GRAPH_FACE_SUCCESSOR_INSERT_EDGE_UNCHANGED))
         (end_itlist CONJ
           ((map (fun s -> assoc s asl)
              ["current_graph"; "current_rotation"; "distinct";
               "new_edge"; "x_anchor"; "w_anchor"]) @
            [d_dart; not_x; not_path])) in
      let unchanged' =
        REWRITE_RULE
         [GSYM(CONJUNCT2 fan_edges); GSYM(CONJUNCT2 fan_rotation)]
         unchanged in
      LABEL_TAC "step_unchanged"
       (GEN d (DISCH condition unchanged')) g) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "new_euler" ACCEPT_TAC;
      USE_THEN "step_unchanged" (MP_TAC o SPEC `p:A#A`) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
          (ISPECL
            [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `t:num`]
            FAN_GRAPH_DARTS_MONO)) THEN
          USE_THEN "p_dart" ACCEPT_TAC;
          (fun (asl,_ as g) ->
            let fresh_pair =
              MATCH_MP
               (ISPECL
                 [`V:A->bool`; `E:(A->bool)->bool`; `x:A`;
                  `p:A#A`; `(w:num->A) 0`]
                 GRAPH_DART_NE_FRESH_VERTEX)
               (CONJ (assoc "graph" asl)
                (CONJ (assoc "fresh" asl) (assoc "p_dart" asl))) in
            ACCEPT_TAC (CONJUNCT2 fresh_pair) g);
          USE_THEN "p_distinct" MATCH_MP_TAC THEN
          USE_THEN "t_index" ACCEPT_TAC];
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "old_p" ACCEPT_TAC];
      USE_THEN "new_first" ACCEPT_TAC;
      REWRITE_TAC[fan_source_dart] THEN
      (fun (asl,_ as g) ->
        let future_t =
          MATCH_MP (SPEC `t:num` (assoc "old_future" asl))
           (CONJ (SPEC `t:num` LE_REFL) (assoc "t_index" asl)) in
        ACCEPT_TAC
         (TRANS (assoc "new_last_raw" asl)
          (TRANS (SYM(assoc "old_path_value" asl)) future_t)) g);
      X_GEN_TAC `i:num` THEN INTRO_TAC "after index" THEN
      USE_THEN "step_unchanged" (MP_TAC o SPEC
       `((w:num->A) i,w (SUC i)):A#A`) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
           (ISPECL
            [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `t:num`]
            FAN_GRAPH_DARTS_MONO)) THEN
          USE_THEN "path_darts" MATCH_MP_TAC THEN
          USE_THEN "index" ACCEPT_TAC;
          (fun (asl,_ as g) ->
            let dart =
              MATCH_MP (SPEC `i:num` (assoc "path_darts" asl))
                       (assoc "index" asl) in
            let fresh_pair =
              MATCH_MP
               (ISPECL
                 [`V:A->bool`; `E:(A->bool)->bool`; `x:A`;
                  `((w:num->A) i,w (SUC i)):A#A`; `(w:num->A) 0`]
                 GRAPH_DART_NE_FRESH_VERTEX)
               (CONJ (assoc "graph" asl)
                (CONJ (assoc "fresh" asl) dart)) in
            ACCEPT_TAC (CONJUNCT2 fresh_pair) g);
          MATCH_MP_TAC(ISPECL
           [`w:num->A`; `h:num`; `i:num`; `t:num`]
           FAN_PATH_DART_DISTINCT) THEN
          ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "old_future" MATCH_MP_TAC THEN ASM_ARITH_TAC];
      X_GEN_TAC `d:A#A` THEN
      INTRO_TAC "d_dart not_p avoids" THEN
      USE_THEN "step_unchanged" (MP_TAC o SPEC `d:A#A`) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
           (ISPECL
            [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `t:num`]
            FAN_GRAPH_DARTS_MONO)) THEN
          USE_THEN "d_dart" ACCEPT_TAC;
          (fun (asl,_ as g) ->
            let fresh_pair =
              MATCH_MP
               (ISPECL
                 [`V:A->bool`; `E:(A->bool)->bool`; `x:A`;
                  `d:A#A`; `(w:num->A) 0`]
                 GRAPH_DART_NE_FRESH_VERTEX)
               (CONJ (assoc "graph" asl)
                (CONJ (assoc "fresh" asl) (assoc "d_dart" asl))) in
            ACCEPT_TAC (CONJUNCT2 fresh_pair) g);
          USE_THEN "avoids" MATCH_MP_TAC THEN
          USE_THEN "t_index" ACCEPT_TAC];
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        (fun (asl,_ as g) ->
          let th =
            MATCH_MP (SPEC `d:A#A` (assoc "old_unchanged" asl))
             (CONJ (assoc "d_dart" asl)
              (CONJ (assoc "not_p" asl) (assoc "avoids" asl))) in
          ACCEPT_TAC th g)]]);;

let EULER_PLANAR_ROTATION_FAN_INDEX = prove
 (`!t. !V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !p:A#A. !h.
        fan_rotation_induction_statement
         (V:A->bool) (E:(A->bool)->bool) (r:(A#A)->A#A)
         (x:A) (w:num->A) (p:A#A) h t`,
  INDUCT_TAC THEN REPEAT GEN_TAC THENL
   [MATCH_ACCEPT_TAC EULER_PLANAR_ROTATION_FAN_BASE;
    MATCH_MP_TAC EULER_PLANAR_ROTATION_FAN_STEP THEN
    FIRST_X_ASSUM MATCH_ACCEPT_TAC]);;

let EULER_PLANAR_ROTATION_FAN = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !p:A#A. !h.
        euler_planar_rotation V E r /\
        ~(x IN V) /\
        INJ w (cyclic_indices (h + 1)) (:A) /\
        (!i. i <= h ==> w i IN V) /\
        p IN graph_darts E /\
        SND p = w 0 /\
        (!i. i < h ==> (w i,w (SUC i)) IN graph_darts E) /\
        (!i. i < h ==> ~(p = (w i,w (SUC i)))) /\
        (!i. i < h
             ==> graph_face_successor E r (fan_source_dart p w i) =
                 (w i,w (SUC i)))
        ==> fan_rotation_invariant V E r x w p h h`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "assumptions") THEN
  MP_TAC(ISPECL
   [`h:num`; `V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `x:A`; `w:num->A`; `p:A#A`; `h:num`]
   EULER_PLANAR_ROTATION_FAN_INDEX) THEN
  REWRITE_TAC[fan_rotation_induction_statement] THEN
  ASM_REWRITE_TAC[LE_REFL]);;

(* ------------------------------------------------------------------------- *)
(* Boundary-preserving fan insertion for a cyclic disk.                      *)
(*                                                                           *)
(* The generic fan theorem is specialized to the boundary obtained by        *)
(* deleting the last vertex of q.  The old cyclic face is first converted    *)
(* to local successor equations.  Fan insertion changes the final three      *)
(* successors and leaves the earlier cyclic prefix unchanged; these local    *)
(* equations are then reassembled into the new boundary face q.              *)
(* ------------------------------------------------------------------------- *)

let CYCLIC_DELETE_LAST_FAN_PATH = prove
 (`!q w:num->A. !n k r.
        3 <= n /\
        r <= k /\
        w 0 = q (n - 2)
        ==> cyclic_delete_last q w n (n - 2 + r) = w r`,
  REPEAT GEN_TAC THEN INTRO_TAC "nlarge index first" THEN
  ASM_CASES_TAC `(r:num) = 0` THENL
   [ASM_REWRITE_TAC[ADD_CLAUSES] THEN
    MATCH_MP_TAC CYCLIC_DELETE_LAST_PENULTIMATE THEN
    USE_THEN "nlarge" ACCEPT_TAC;
    MATCH_MP_TAC CYCLIC_DELETE_LAST_CHAIN THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]);;

let CYCLIC_DELETE_LAST_FAN_LAST = prove
 (`!q w:num->A. !n k.
        3 <= n /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0
        ==> cyclic_dart (cyclic_delete_last q w n)
             (n - 1 + k) (n - 2 + k) =
            (w k,w (k + 1))`,
  REPEAT GEN_TAC THEN INTRO_TAC "nlarge first last" THEN
  REWRITE_TAC[cyclic_dart] THEN
  REWRITE_TAC[PAIR_EQ] THEN CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`q:num->A`; `w:num->A`; `n:num`; `k:num`; `k:num`]
     CYCLIC_DELETE_LAST_FAN_PATH) THEN
    ASM_REWRITE_TAC[LE_REFL];
    SUBGOAL_THEN `(n - 2 + k) + 1 = n - 1 + k`
    (fun th -> REWRITE_TAC[th; MOD_REFL]) THENL
     [ASM_ARITH_TAC;
      TRANS_TAC EQ_TRANS `(q:num->A) 0` THEN CONJ_TAC THENL
       [MATCH_MP_TAC CYCLIC_DELETE_LAST_FIRST THEN
        USE_THEN "nlarge" ACCEPT_TAC;
        USE_THEN "last" (ACCEPT_TAC o SYM)]]]);;

let CYCLIC_DELETE_LAST_FAN_PREFIX_DART = prove
 (`!q w:num->A. !n k i.
        3 <= n /\
        i < n - 2
        ==> cyclic_dart (cyclic_delete_last q w n)
             (n - 1 + k) i = (q i,q (i + 1))`,
  REPEAT GEN_TAC THEN INTRO_TAC "nlarge index" THEN
  REWRITE_TAC[cyclic_dart; PAIR_EQ] THEN CONJ_TAC THENL
   [MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN ASM_ARITH_TAC;
    SUBGOAL_THEN `(i + 1) MOD (n - 1 + k) = i + 1`
    SUBST1_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN ASM_ARITH_TAC]]);;

let CYCLIC_DELETE_LAST_FAN_PATH_DART = prove
 (`!q w:num->A. !n k r.
        3 <= n /\
        r <= k /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0
        ==> cyclic_dart (cyclic_delete_last q w n)
             (n - 1 + k) (n - 2 + r) =
            (w r,w (r + 1))`,
  REPEAT GEN_TAC THEN INTRO_TAC "nlarge index first last" THEN
  ASM_CASES_TAC `(r:num) = k` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_LAST THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[cyclic_dart; PAIR_EQ] THEN CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`q:num->A`; `w:num->A`; `n:num`; `k:num`; `r:num`]
       CYCLIC_DELETE_LAST_FAN_PATH) THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN
       `((n - 2 + r) + 1) MOD (n - 1 + k) = n - 2 + (r + 1)`
      SUBST1_TAC THENL
       [TRANS_TAC EQ_TRANS `((n - 2 + r) + 1)` THEN CONJ_TAC THENL
         [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
          ASM_ARITH_TAC];
        MATCH_MP_TAC(ISPECL
         [`q:num->A`; `w:num->A`; `n:num`; `k:num`; `r + 1`]
         CYCLIC_DELETE_LAST_FAN_PATH) THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]]]);;

let CYCLIC_DELETE_LAST_FAN_P_DART = prove
 (`!q w:num->A. !n k.
        3 <= n
        ==> cyclic_dart (cyclic_delete_last q w n)
             (n - 1 + k) (n - 3) =
            (q (n - 3),q (n - 2))`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "nlarge") THEN
  MP_TAC(ISPECL
   [`q:num->A`; `w:num->A`; `n:num`; `k:num`; `n - 3`]
   CYCLIC_DELETE_LAST_FAN_PREFIX_DART) THEN
  ASM_REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[PAIR_EQ] THEN
    AP_TERM_TAC THEN ASM_ARITH_TAC]);;

let CYCLIC_DELETE_LAST_FAN_AFTER_LAST = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !q w:num->A. !n k.
        3 <= n /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0 /\
        cyclic_face_successors
         E r (cyclic_delete_last q w n) (n - 1 + k)
        ==> graph_face_successor E r (w k,w (k + 1)) =
            (q 0,q 1)`,
  REPEAT GEN_TAC THEN INTRO_TAC "nlarge first last successors" THEN
  USE_THEN "successors" MP_TAC THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  DISCH_THEN(MP_TAC o SPEC `n - 2 + k`) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(LABEL_TAC "successor")] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_delete_last (q:num->A) w n)
      (n - 1 + k) (n - 2 + k) = (w k,w (k + 1))`
  (LABEL_TAC "last_dart") THENL
   [MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_LAST THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_delete_last (q:num->A) w n)
      (n - 1 + k) 0 = (q 0,q 1)`
  (LABEL_TAC "first_dart") THENL
   [MATCH_MP_TAC(REWRITE_RULE[ADD_CLAUSES]
     (ISPECL
       [`q:num->A`; `w:num->A`; `n:num`; `k:num`; `0`]
       CYCLIC_DELETE_LAST_FAN_PREFIX_DART)) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    SUBGOAL_THEN
     `((n - 2 + k) + 1) MOD (n - 1 + k) = 0`
    (LABEL_TAC "wrap") THENL
     [SUBGOAL_THEN `(n - 2 + k) + 1 = n - 1 + k`
      SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[MOD_REFL]];
      (fun (asl,_ as g) ->
        let result =
          SUBS [assoc "last_dart" asl; assoc "wrap" asl]
            (assoc "successor" asl) in
        ACCEPT_TAC (TRANS result (assoc "first_dart" asl)) g)]]);;

let CYCLIC_DELETE_LAST_FAN_CHAIN_ZERO = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !q w:num->A. !n k.
        3 <= n /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0 /\
        cyclic_face_successors
         E r (cyclic_delete_last q w n) (n - 1 + k)
        ==> graph_face_successor E r
             (q (n - 3),q (n - 2)) = (w 0,w 1)`,
  REPEAT GEN_TAC THEN INTRO_TAC "nlarge first last successors" THEN
  USE_THEN "successors" MP_TAC THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  DISCH_THEN(MP_TAC o SPEC `n - 3`) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(LABEL_TAC "successor")] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_delete_last (q:num->A) w n)
      (n - 1 + k) (n - 3) = (q (n - 3),q (n - 2))`
  (LABEL_TAC "p_dart") THENL
   [MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_P_DART THEN
    USE_THEN "nlarge" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((n - 3) + 1) MOD (n - 1 + k) = n - 2`
  (LABEL_TAC "next_index") THENL
   [TRANS_TAC EQ_TRANS `((n - 3) + 1)` THEN CONJ_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_delete_last (q:num->A) w n)
      (n - 1 + k) (n - 2) = (w 0,w 1)`
  (LABEL_TAC "first_path") THENL
   [MATCH_MP_TAC(REWRITE_RULE[ADD_CLAUSES]
     (ISPECL
       [`q:num->A`; `w:num->A`; `n:num`; `k:num`; `0`]
       CYCLIC_DELETE_LAST_FAN_PATH_DART)) THEN
    ASM_REWRITE_TAC[LE_0];
    (fun (asl,_ as g) ->
      let result =
        SUBS [assoc "p_dart" asl; assoc "next_index" asl]
          (assoc "successor" asl) in
      ACCEPT_TAC (TRANS result (assoc "first_path" asl)) g)]);;

let CYCLIC_DELETE_LAST_FAN_CHAIN_SUC = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !q w:num->A. !n k j.
        3 <= n /\
        j < k /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0 /\
        cyclic_face_successors
         E r (cyclic_delete_last q w n) (n - 1 + k)
        ==> graph_face_successor E r (w j,w (SUC j)) =
            (w (SUC j),w (SUC(SUC j)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "nlarge index first last successors" THEN
  USE_THEN "successors" MP_TAC THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  DISCH_THEN(MP_TAC o SPEC `n - 2 + j`) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(LABEL_TAC "successor")] THEN
  SUBGOAL_THEN
  `cyclic_dart (cyclic_delete_last (q:num->A) w n)
      (n - 1 + k) (n - 2 + j) = (w j,w (SUC j))`
  (LABEL_TAC "source_dart") THENL
   [REWRITE_TAC[ADD1] THEN
    MATCH_MP_TAC(ISPECL
     [`q:num->A`; `w:num->A`; `n:num`; `k:num`; `j:num`]
     CYCLIC_DELETE_LAST_FAN_PATH_DART) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((n - 2 + j) + 1) MOD (n - 1 + k) = n - 2 + SUC j`
  (LABEL_TAC "next_index") THENL
   [TRANS_TAC EQ_TRANS `((n - 2 + j) + 1)` THEN CONJ_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
  `cyclic_dart (cyclic_delete_last (q:num->A) w n)
      (n - 1 + k) (n - 2 + SUC j) =
    (w (SUC j),w (SUC(SUC j)))`
  (LABEL_TAC "target_dart") THENL
   [REWRITE_TAC[ADD1] THEN
    MATCH_MP_TAC(ISPECL
     [`q:num->A`; `w:num->A`; `n:num`; `k:num`; `j + 1`]
     CYCLIC_DELETE_LAST_FAN_PATH_DART) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    (fun (asl,_ as g) ->
      let result =
        SUBS [assoc "source_dart" asl; assoc "next_index" asl]
          (assoc "successor" asl) in
      ACCEPT_TAC (TRANS result (assoc "target_dart" asl)) g)]);;

let CYCLIC_DELETE_LAST_FAN_CHAIN = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !q w:num->A. !n k.
        3 <= n /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0 /\
        cyclic_face_successors
         E r (cyclic_delete_last q w n) (n - 1 + k)
        ==> !i. i < k + 1
                ==> graph_face_successor E r
                     (fan_source_dart
                       (q (n - 3),q (n - 2)) w i) =
                    (w i,w (SUC i))`,
  REPEAT GEN_TAC THEN INTRO_TAC "nlarge first last successors" THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
  ASM_CASES_TAC `(i:num) = 0` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    REWRITE_TAC[fan_source_dart] THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `q:num->A`; `w:num->A`; `n:num`; `k:num`]
     CYCLIC_DELETE_LAST_FAN_CHAIN_ZERO) THEN
    ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "positive") THEN
    MP_TAC(SPEC `i:num` num_CASES) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `j:num` SUBST_ALL_TAC) THEN
    REWRITE_TAC[fan_source_dart] THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `q:num->A`; `w:num->A`; `n:num`; `k:num`; `j:num`]
     CYCLIC_DELETE_LAST_FAN_CHAIN_SUC) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]);;

let CYCLIC_DART_NOWRAP = prove
 (`!q:num->A. !n i.
