  SUBGOAL_THEN `(i + 1) MOD (n - 1 + k) = i + 1`
  (LABEL_TAC "next_index") THENL
   [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_delete_last (q:num->A) w n)
