          (assoc "successor" asl) in
      ACCEPT_TAC (TRANS result (assoc "target_dart" asl)) g)]);;

let BOUNDARY_EULER_ROTATION_CYCLIC_FAN_INVARIANT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q w:num->A. !n k.
   !r:(A#A)->A#A. !x:A.
        simple_graph_cycle E (cyclic_delete_last q w n) (n - 1 + k) /\
        boundary_euler_rotation
         V E (cyclic_delete_last q w n) (n - 1 + k) r /\
        3 <= n /\
        ~(x IN V) /\
        INJ w (cyclic_indices (k + 2)) (:A) /\
        cyclic_vertices w (k + 2) SUBSET V /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0
        ==> fan_rotation_invariant
             V E r x w (q (n - 3),q (n - 2)) (k + 1) (k + 1)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "cycle boundary nlarge fresh injective vertices first last" THEN
  USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "oldlarge oldinjective oldedges" THEN
  SUBGOAL_THEN
   `cyclic_face_successors E r (cyclic_delete_last (q:num->A) w n)
      (n - 1 + k)`
  (LABEL_TAC "successors") THENL
   [MATCH_MP_TAC BOUNDARY_EULER_ROTATION_IMP_CYCLIC_FACE_SUCCESSORS THEN
    ASM_MESON_TAC[simple_graph_cycle; ARITH_RULE `3 <= m ==> 2 <= m`];
    ALL_TAC] THEN
  MATCH_MP_TAC EULER_PLANAR_ROTATION_FAN THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation] THEN MESON_TAC[];
    USE_THEN "fresh" ACCEPT_TAC;
    ASM_REWRITE_TAC[ARITH_RULE `(k + 1) + 1 = k + 2`];
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    USE_THEN "vertices" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    SUBGOAL_THEN
     `cyclic_dart (cyclic_delete_last (q:num->A) w n)
        (n - 1 + k) (n - 3) = (q (n - 3),q (n - 2))`
    (LABEL_TAC "p_dart") THENL
     [MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_P_DART THEN
      USE_THEN "nlarge" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "p_dart" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DART THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    REWRITE_TAC[SND] THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    REWRITE_TAC[ADD1] THEN
    SUBGOAL_THEN
     `cyclic_dart (cyclic_delete_last (q:num->A) w n)
        (n - 1 + k) (n - 2 + i) = (w i,w (i + 1))`
    (LABEL_TAC "path_dart") THENL
     [MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_PATH_DART THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "path_dart" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DART THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    REWRITE_TAC[ADD1] THEN
    SUBGOAL_THEN
     `cyclic_dart (cyclic_delete_last (q:num->A) w n)
        (n - 1 + k) (n - 3) = (q (n - 3),q (n - 2))`
    (LABEL_TAC "p_dart") THENL
     [MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_P_DART THEN
      USE_THEN "nlarge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `cyclic_dart (cyclic_delete_last (q:num->A) w n)
        (n - 1 + k) (n - 2 + i) = (w i,w (i + 1))`
    (LABEL_TAC "path_dart") THENL
     [MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_PATH_DART THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "p_dart" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "path_dart" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC CYCLIC_DART_DISTINCT THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `q:num->A`; `w:num->A`; `n:num`; `k:num`]
     CYCLIC_DELETE_LAST_FAN_CHAIN) THEN
    ASM_REWRITE_TAC[]]);;

let FAN_ROTATION_CYCLIC_PREFIX_SUCCESSOR = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q w:num->A. !n k.
   !r:(A#A)->A#A. !i.
        simple_graph_cycle E (cyclic_delete_last q w n) (n - 1 + k) /\
        cyclic_face_successors
         E r (cyclic_delete_last q w n) (n - 1 + k) /\
        3 <= n /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0 /\
        fan_rotation_invariant
         V E r (q (n - 1)) w (q (n - 3),q (n - 2))
         (k + 1) (k + 1) /\
        i < n - 3
        ==> graph_face_successor
             (fan_edges (q (n - 1)) w E (k + 1))
             (fan_rotation (q (n - 1)) w
               (q (n - 3),q (n - 2)) r (k + 1))
             (q i,q (i + 1)) = (q (i + 1),q (i + 2))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "cycle successors nlarge first last invariant index" THEN
  USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "oldlarge oldinjective oldedges" THEN
  USE_THEN "invariant" MP_TAC THEN
  REWRITE_TAC[fan_rotation_invariant] THEN
  INTRO_TAC "euler new_p new_first new_last future unchanged" THEN
  USE_THEN "unchanged" (MP_TAC o SPEC `(q i,q (i + 1)):A#A`) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [SUBGOAL_THEN
       `cyclic_dart (cyclic_delete_last (q:num->A) w n)
          (n - 1 + k) i = (q i,q (i + 1))`
      (LABEL_TAC "old_source") THENL
       [MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_PREFIX_DART THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      USE_THEN "old_source" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DART THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      SUBGOAL_THEN
       `cyclic_dart (cyclic_delete_last (q:num->A) w n)
          (n - 1 + k) i = (q i,q (i + 1))`
      (LABEL_TAC "old_source") THENL
       [MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_PREFIX_DART THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `cyclic_dart (cyclic_delete_last (q:num->A) w n)
          (n - 1 + k) (n - 3) =
        (q (n - 3),q (n - 2))`
      (LABEL_TAC "old_p") THENL
       [MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_P_DART THEN
        USE_THEN "nlarge" ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "old_source" (fun th -> REWRITE_TAC[GSYM th]) THEN
      USE_THEN "old_p" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC CYCLIC_DART_DISTINCT THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      X_GEN_TAC `j:num` THEN DISCH_THEN(LABEL_TAC "path_index") THEN
      SUBGOAL_THEN
       `cyclic_dart (cyclic_delete_last (q:num->A) w n)
          (n - 1 + k) i = (q i,q (i + 1))`
      (LABEL_TAC "old_source") THENL
       [MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_PREFIX_DART THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `cyclic_dart (cyclic_delete_last (q:num->A) w n)
          (n - 1 + k) (n - 2 + j) =
        (w j,w (SUC j))`
      (LABEL_TAC "old_path") THENL
       [REWRITE_TAC[ADD1] THEN
        MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_PATH_DART THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      USE_THEN "old_source" (fun th -> REWRITE_TAC[GSYM th]) THEN
      USE_THEN "old_path" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC CYCLIC_DART_DISTINCT THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `q:num->A`; `w:num->A`; `n:num`; `k:num`; `i:num`]
     CYCLIC_DELETE_LAST_FAN_PREFIX_SUCCESSOR) THEN
    ASM_REWRITE_TAC[]]);;

let FAN_ROTATION_CYCLIC_PREDECESSOR_SUCCESSOR = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q w:num->A. !n k.
   !r:(A#A)->A#A.
        w 0 = q (n - 2) /\
