  INTRO_TAC "successors nlarge first last invariant" THEN
  USE_THEN "invariant" MP_TAC THEN REWRITE_TAC[fan_rotation_invariant] THEN
  INTRO_TAC "euler new_p new_first new_last future unchanged" THEN
  SUBGOAL_THEN
   `graph_face_successor E r (w k,w (k + 1)) =
    ((q:num->A) 0,q 1)`
  (LABEL_TAC "old_after_last") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
