let CYCLIC_DART_PENULTIMATE = prove
 (`!q:num->A. !n.
        2 <= n
        ==> cyclic_dart q n (n - 2) = (q (n - 2),q (n - 1))`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "nlarge") THEN
  SUBGOAL_THEN `(n - 2) + 1 = n - 1` (LABEL_TAC "index") THENL
   [ASM_ARITH_TAC;
    MP_TAC(ISPECL [`q:num->A`; `n:num`; `n - 2`]
      CYCLIC_DART_NOWRAP) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      DISCH_THEN(fun th ->
        USE_THEN "index" (fun ith ->
          ACCEPT_TAC(REWRITE_RULE[ith] th)))]]);;

let CYCLIC_DART_ZERO = prove
 (`!q:num->A. !n.
        2 <= n
        ==> cyclic_dart q n 0 = (q 0,q 1)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "nlarge") THEN
  MP_TAC(ISPECL [`q:num->A`; `n:num`; `0`]
    CYCLIC_DART_NOWRAP) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    CONV_TAC NUM_REDUCE_CONV]);;

let CYCLIC_FACE_SUCCESSORS_OF_PREFIX_AND_LAST = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !q:num->A. !n.
        3 <= n /\
        (!i. i < n - 3
             ==> graph_face_successor E r (q i,q (i + 1)) =
                 (q (i + 1),q (i + 2))) /\
        graph_face_successor E r (q (n - 3),q (n - 2)) =
          (q (n - 2),q (n - 1)) /\
        graph_face_successor E r (q (n - 2),q (n - 1)) =
          (q (n - 1),q 0) /\
        graph_face_successor E r (q (n - 1),q 0) = (q 0,q 1)
        ==> cyclic_face_successors E r q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "nlarge prefix predecessor penultimate last" THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
  ASM_CASES_TAC `i < n - 3` THENL
   [FIRST_X_ASSUM(LABEL_TAC "early") THEN
    SUBGOAL_THEN
     `cyclic_dart (q:num->A) n i = (q i,q (i + 1))`
    (LABEL_TAC "source_dart") THENL
     [MATCH_MP_TAC CYCLIC_DART_NOWRAP THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(i + 1) MOD n = i + 1`
    (LABEL_TAC "next_index") THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `cyclic_dart (q:num->A) n (i + 1) =
      (q (i + 1),q (i + 2))`
    (LABEL_TAC "target_dart") THENL
     [MP_TAC(ISPECL [`q:num->A`; `n:num`; `i + 1`]
       CYCLIC_DART_NOWRAP) THEN
      ANTS_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[ARITH_RULE `(i + 1) + 1 = i + 2`]];
      ALL_TAC] THEN
    USE_THEN "source_dart" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "next_index" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "target_dart" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "prefix" MATCH_MP_TAC THEN
    USE_THEN "early" ACCEPT_TAC;
    ASM_CASES_TAC `(i:num) = n - 3` THENL
     [FIRST_X_ASSUM SUBST_ALL_TAC THEN
      SUBGOAL_THEN `((n - 3) + 1) MOD n = n - 2`
      (LABEL_TAC "next_index") THENL
       [TRANS_TAC EQ_TRANS `((n - 3) + 1)` THEN CONJ_TAC THENL
         [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
          ASM_ARITH_TAC];
        ALL_TAC] THEN
      USE_THEN "next_index" (fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(ISPECL [`q:num->A`; `n:num`] CYCLIC_DART_THIRD_LAST) THEN
      ANTS_TAC THENL
       [USE_THEN "nlarge" ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      USE_THEN "predecessor" (fun th -> REWRITE_TAC[th]) THEN
      MATCH_MP_TAC EQ_SYM THEN
      MATCH_MP_TAC CYCLIC_DART_PENULTIMATE THEN ASM_ARITH_TAC;
      ASM_CASES_TAC `(i:num) = n - 2` THENL
       [FIRST_X_ASSUM SUBST_ALL_TAC THEN
        SUBGOAL_THEN `((n - 2) + 1) MOD n = n - 1`
        (LABEL_TAC "next_index") THENL
         [TRANS_TAC EQ_TRANS `((n - 2) + 1)` THEN CONJ_TAC THENL
           [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
            ASM_ARITH_TAC];
          ALL_TAC] THEN
        USE_THEN "next_index" (fun th -> REWRITE_TAC[th]) THEN
        MP_TAC(ISPECL [`q:num->A`; `n:num`]
          CYCLIC_DART_PENULTIMATE) THEN
        ANTS_TAC THENL
         [ASM_ARITH_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        USE_THEN "penultimate" (fun th -> REWRITE_TAC[th]) THEN
        MATCH_MP_TAC EQ_SYM THEN
        MATCH_MP_TAC CYCLIC_DART_LAST THEN ASM_ARITH_TAC;
        SUBGOAL_THEN `(i:num) = n - 1` SUBST_ALL_TAC THENL
         [ASM_ARITH_TAC;
          SUBGOAL_THEN `((n - 1) + 1) MOD n = 0`
          (LABEL_TAC "next_index") THENL
           [SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
             [ASM_ARITH_TAC;
              REWRITE_TAC[MOD_REFL]];
            ALL_TAC] THEN
          USE_THEN "next_index" (fun th -> REWRITE_TAC[th]) THEN
          MP_TAC(ISPECL [`q:num->A`; `n:num`] CYCLIC_DART_LAST) THEN
          ANTS_TAC THENL
           [ASM_ARITH_TAC;
            DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
          USE_THEN "last" (fun th -> REWRITE_TAC[th]) THEN
          MATCH_MP_TAC EQ_SYM THEN
          MATCH_MP_TAC CYCLIC_DART_ZERO THEN ASM_ARITH_TAC]]]]);;

let FAN_ROTATION_CYCLIC_FACE_SUCCESSORS = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q w:num->A. !n k.
   !r:(A#A)->A#A.
        simple_graph_cycle E (cyclic_delete_last q w n) (n - 1 + k) /\
        cyclic_face_successors
         E r (cyclic_delete_last q w n) (n - 1 + k) /\
        3 <= n /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0 /\
        fan_rotation_invariant
         V E r (q (n - 1)) w (q (n - 3),q (n - 2))
         (k + 1) (k + 1)
        ==> cyclic_face_successors
             (fan_edges (q (n - 1)) w E (k + 1))
             (fan_rotation (q (n - 1)) w
               (q (n - 3),q (n - 2)) r (k + 1))
             q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "cycle successors nlarge first last invariant" THEN
  MATCH_MP_TAC CYCLIC_FACE_SUCCESSORS_OF_PREFIX_AND_LAST THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "nlarge" ACCEPT_TAC;
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `w:num->A`;
      `n:num`; `k:num`; `r:(A#A)->A#A`; `i:num`]
     FAN_ROTATION_CYCLIC_PREFIX_SUCCESSOR) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `w:num->A`;
      `n:num`; `k:num`; `r:(A#A)->A#A`]
     FAN_ROTATION_CYCLIC_PREDECESSOR_SUCCESSOR) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `w:num->A`;
      `n:num`; `k:num`; `r:(A#A)->A#A`]
     FAN_ROTATION_CYCLIC_PENULTIMATE_SUCCESSOR) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `w:num->A`;
      `n:num`; `k:num`; `r:(A#A)->A#A`]
     FAN_ROTATION_CYCLIC_LAST_SUCCESSOR) THEN
    ASM_REWRITE_TAC[]]);;

let BOUNDARY_EULER_ROTATION_OF_CYCLIC_FAN_INVARIANT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q w:num->A. !n k.
   !r:(A#A)->A#A.
        simple_graph_cycle E (cyclic_delete_last q w n) (n - 1 + k) /\
        cyclic_face_successors
         E r (cyclic_delete_last q w n) (n - 1 + k) /\
        3 <= n /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0 /\
        fan_rotation_invariant
         V E r (q (n - 1)) w (q (n - 3),q (n - 2))
         (k + 1) (k + 1)
        ==> boundary_euler_rotation
             (q (n - 1) INSERT V)
             (fan_edges (q (n - 1)) w E (k + 1)) q n
             (fan_rotation (q (n - 1)) w
               (q (n - 3),q (n - 2)) r (k + 1))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "cycle successors nlarge first last invariant" THEN
  (fun (asl,_ as g) ->
    let euler =
      CONJUNCT1
       (REWRITE_RULE[fan_rotation_invariant]
         (assoc "invariant" asl)) in
    LABEL_TAC "euler" euler g) THEN
  (fun (asl,_ as g) ->
    let successors = MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `w:num->A`;
       `n:num`; `k:num`; `r:(A#A)->A#A`]
      FAN_ROTATION_CYCLIC_FACE_SUCCESSORS)
     (end_itlist CONJ
      [assoc "cycle" asl; assoc "successors" asl;
       assoc "nlarge" asl; assoc "first" asl; assoc "last" asl;
       assoc "invariant" asl]) in
    LABEL_TAC "new_successors" successors g) THEN
  (fun (asl,_ as g) ->
    let n2 = MATCH_MP (ARITH_RULE `3 <= n ==> 2 <= n`)
                       (assoc "nlarge" asl) in
    let result = MATCH_MP
      (ISPECL
       [`(q:num->A) (n - 1) INSERT V`;
        `fan_edges ((q:num->A) (n - 1)) w E (k + 1)`;
        `q:num->A`; `n:num`;
        `fan_rotation ((q:num->A) (n - 1)) w
          (q (n - 3),q (n - 2)) r (k + 1)`]
       BOUNDARY_EULER_ROTATION_OF_CYCLIC_FACE_SUCCESSORS)
      (CONJ n2
       (CONJ (assoc "euler" asl) (assoc "new_successors" asl))) in
    ACCEPT_TAC result g));;

let BOUNDARY_EULER_ROTATION_CYCLIC_FAN = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q w:num->A. !n k.
   !r:(A#A)->A#A.
        simple_graph_cycle E (cyclic_delete_last q w n) (n - 1 + k) /\
        boundary_euler_rotation
         V E (cyclic_delete_last q w n) (n - 1 + k) r /\
        3 <= n /\
        ~(q (n - 1) IN V) /\
        INJ w (cyclic_indices (k + 2)) (:A) /\
        cyclic_vertices w (k + 2) SUBSET V /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0
        ==> boundary_euler_rotation
             (q (n - 1) INSERT V)
             (IMAGE (\u:A. {q (n - 1),u})
               (cyclic_vertices w (k + 2)) UNION E)
             q n
             (fan_rotation (q (n - 1)) w
               (q (n - 3),q (n - 2)) r (k + 1))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "cycle boundary nlarge fresh injective vertices first last" THEN
  USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "oldlarge oldinjective oldedges" THEN
  (fun (asl,_ as g) ->
    let oldn2 = MATCH_MP (ARITH_RULE `3 <= m ==> 2 <= m`)
                          (assoc "oldlarge" asl) in
    let successors = MATCH_MP
      (ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `cyclic_delete_last (q:num->A) w n`; `n - 1 + k`;
        `r:(A#A)->A#A`]
       BOUNDARY_EULER_ROTATION_IMP_CYCLIC_FACE_SUCCESSORS)
      (CONJ oldn2
       (CONJ (assoc "oldinjective" asl)
        (CONJ (assoc "oldedges" asl) (assoc "boundary" asl)))) in
    LABEL_TAC "successors" successors g) THEN
  (fun (asl,_ as g) ->
    let invariant = MATCH_MP
      (ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `w:num->A`;
        `n:num`; `k:num`; `r:(A#A)->A#A`; `(q:num->A) (n - 1)`]
       BOUNDARY_EULER_ROTATION_CYCLIC_FAN_INVARIANT)
      (end_itlist CONJ
       [assoc "cycle" asl; assoc "boundary" asl; assoc "nlarge" asl;
        assoc "fresh" asl; assoc "injective" asl; assoc "vertices" asl;
        assoc "first" asl; assoc "last" asl]) in
    LABEL_TAC "invariant" invariant g) THEN
  (fun (asl,_ as g) ->
    let boundary = MATCH_MP
      (ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `w:num->A`;
        `n:num`; `k:num`; `r:(A#A)->A#A`]
       BOUNDARY_EULER_ROTATION_OF_CYCLIC_FAN_INVARIANT)
      (end_itlist CONJ
       [assoc "cycle" asl; assoc "successors" asl; assoc "nlarge" asl;
        assoc "first" asl; assoc "last" asl; assoc "invariant" asl]) in
    ACCEPT_TAC
     (REWRITE_RULE
      [FAN_EDGES_CYCLIC_VERTICES;
       ARITH_RULE `(k + 1) + 1 = k + 2`] boundary) g));;

(* ------------------------------------------------------------------------- *)
(* Deleting edges from finite graph rotation systems.                        *)
(* ------------------------------------------------------------------------- *)

(* Deleting x from a permutation splices its predecessor directly to f x.    *)

let permutation_delete = new_definition
 `permutation_delete (f:A->A) x = swap(x,f x) o f`;;

let PERMUTATION_DELETE_APPLY = prove
 (`!f:A->A. !x y.
        permutation_delete f x y =
        if f y = x then f x
        else if f y = f x then x
        else f y`,
  REWRITE_TAC[permutation_delete; o_THM; swap]);;

let PERMUTATION_DELETE_FIX = prove
 (`!f:A->A. !x. permutation_delete f x x = x`,
  REWRITE_TAC[permutation_delete; o_THM; SWAP_RIGHT]);;

let PERMUTATION_DELETE_PERMUTES = prove
 (`!f:A->A. !s x.
        f permutes s /\ x IN s
        ==> permutation_delete f x permutes (s DELETE x)`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation member" THEN
  REWRITE_TAC[permutation_delete] THEN
  MATCH_MP_TAC PERMUTES_INSERT_LEMMA THEN
  ASM_SIMP_TAC[INSERT_DELETE]);;

let PERMUTATION_DELETE_APPLY_IN = prove
 (`!f:A->A. !s x y.
        f permutes s /\ x IN s /\ y IN s /\ ~(y = x)
        ==> permutation_delete f x y =
            if f y = x then f x else f y`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation x y distinct" THEN
  REWRITE_TAC[PERMUTATION_DELETE_APPLY] THEN
  SUBGOAL_THEN `~((f:A->A) y = f x)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPECL [`y:A`; `x:A`]) THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;

let PERMUTATION_DELETE_PRESERVES_KEY = prove
 (`!f:A->A. !s x k:A->B.
        f permutes s /\
        x IN s /\
        (!y. y IN s ==> k(f y) = k y)
        ==> !y. y IN s DELETE x
                ==> k(permutation_delete f x y) = k y`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation x preserves" THEN
  X_GEN_TAC `y:A` THEN REWRITE_TAC[IN_DELETE] THEN
  INTRO_TAC "member distinct" THEN
  MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`; `y:A`]
    PERMUTATION_DELETE_APPLY_IN) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[] THENL
   [TRANS_TAC EQ_TRANS `(k:A->B) x` THEN CONJ_TAC THENL
     [USE_THEN "preserves" (MATCH_MP_TAC o SPEC `x:A`) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "preserves" (fun th ->
       MP_TAC(MATCH_MP (SPEC `y:A` th) (ASSUME `(y:A) IN s`))) THEN
      ASM_REWRITE_TAC[]];
    USE_THEN "preserves" (fun th ->
     MATCH_ACCEPT_TAC(MATCH_MP (SPEC `y:A` th)
      (ASSUME `(y:A) IN s`)))]);;

let permutation_delete_two = new_definition
 `permutation_delete_two (f:A->A) x y =
        permutation_delete (permutation_delete f x) y`;;

let PERMUTATION_DELETE_TWO_PERMUTES = prove
 (`!f:A->A. !s x y.
        f permutes s /\ x IN s /\ y IN s /\ ~(x = y)
        ==> permutation_delete_two f x y
            permutes (s DELETE x DELETE y)`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation x y distinct" THEN
  REWRITE_TAC[permutation_delete_two] THEN
  MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN CONJ_TAC THENL
   [MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[]]);;

let PERMUTATION_DELETE_TWO_PRESERVES_KEY = prove
 (`!f:A->A. !s x y k:A->B.
        f permutes s /\
        x IN s /\
        y IN s /\
        ~(x = y) /\
        (!z. z IN s ==> k(f z) = k z)
        ==> !z. z IN s DELETE x DELETE y
                ==> k(permutation_delete_two f x y z) = k z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "permutation x y distinct preserves" THEN
  SUBGOAL_THEN
   `permutation_delete (f:A->A) x permutes (s DELETE x)`
  (LABEL_TAC "first_permutation") THENL
   [MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN s DELETE x
          ==> (k:A->B) (permutation_delete f x z) = k z`
  (LABEL_TAC "first_preserves") THENL
   [MATCH_MP_TAC PERMUTATION_DELETE_PRESERVES_KEY THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[permutation_delete_two] THEN
  MATCH_MP_TAC PERMUTATION_DELETE_PRESERVES_KEY THEN
  ASM_REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[]);;

(* Deletion preserves a cyclic action on each fibre of an invariant key.     *)

let PERMUTATION_ITER_PRESERVES_KEY = prove
 (`!f:A->A. !s k:A->B a.
        f permutes s /\
        a IN s /\
        (!z. z IN s ==> k(f z) = k z)
        ==> !n. ITER n f a IN s /\ k(ITER n f a) = k a`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation member preserves" THEN
  INDUCT_TAC THEN ASM_REWRITE_TAC[ITER] THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `ITER n (f:A->A) a`]
      PERMUTES_IN_IMAGE) THEN
    ASM_REWRITE_TAC[];
    TRANS_TAC EQ_TRANS `(k:A->B) (ITER n (f:A->A) a)` THEN
    CONJ_TAC THENL
     [USE_THEN "preserves"
       (MATCH_MP_TAC o SPEC `ITER n (f:A->A) a`) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]]]);;

let PERMUTATION_DELETE_ITER_OFF_KEY = prove
 (`!f:A->A. !s x k:A->B a.
        f permutes s /\
        x IN s /\
        a IN s /\
        (!z. z IN s ==> k(f z) = k z) /\
        ~(k x = k a)
        ==> !n. ITER n (permutation_delete f x) a = ITER n f a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "permutation x a preserves different_key" THEN
  SUBGOAL_THEN
   `!n. ITER n (f:A->A) a IN s /\ (k:A->B) (ITER n f a) = k a`
  (LABEL_TAC "old_iter") THENL
   [MATCH_MP_TAC PERMUTATION_ITER_PRESERVES_KEY THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  INDUCT_TAC THEN ASM_REWRITE_TAC[ITER] THEN
  MP_TAC(SPEC `n:num` (ASSUME
   `!n. ITER n (f:A->A) a IN s /\
        (k:A->B) (ITER n f a) = k a`)) THEN
  INTRO_TAC "iter_member iter_key" THEN
  SUBGOAL_THEN `~(ITER n (f:A->A) a = x)`
  (LABEL_TAC "iter_distinct") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((f:A->A) (ITER n f a) = x)`
  (LABEL_TAC "not_enter") THENL
   [DISCH_THEN(LABEL_TAC "enters") THEN
    SUBGOAL_THEN
     `(k:A->B) (f(ITER n f a)) = k(ITER n f a)`
    (LABEL_TAC "step_key") THENL
     [USE_THEN "preserves"
       (MATCH_MP_TAC o SPEC `ITER n (f:A->A) a`) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`f:A->A`; `s:A->bool`; `x:A`; `ITER n (f:A->A) a`]
   PERMUTATION_DELETE_APPLY_IN) THEN
  ASM_REWRITE_TAC[]);;

let PERMUTATION_DELETE_TRANSITIVE_KEY = prove
 (`!f:A->A. !s x k:A->B.
        f permutes s /\
        x IN s /\
        (!z. z IN s ==> k(f z) = k z) /\
        (!a b. a IN s /\ b IN s /\ k a = k b
               ==> ?n. ITER n f a = b)
        ==> !a b. a IN s DELETE x /\
                  b IN s DELETE x /\
                  k a = k b
                  ==> ?n. ITER n (permutation_delete f x) a = b`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation x preserves transitive" THEN
  MAP_EVERY X_GEN_TAC [`a:A`; `b:A`] THEN
  INTRO_TAC "a b same_key" THEN
  USE_THEN "a" MP_TAC THEN REWRITE_TAC[IN_DELETE] THEN
  INTRO_TAC "a_member a_distinct" THEN
  USE_THEN "b" MP_TAC THEN REWRITE_TAC[IN_DELETE] THEN
  INTRO_TAC "b_member b_distinct" THEN
  ABBREV_TAC `p:A->A = permutation_delete f x` THEN
  SUBGOAL_THEN `(p:A->A) permutes (s DELETE x)`
  (LABEL_TAC "deleted_permutation") THENL
   [EXPAND_TAC "p" THEN MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN s DELETE x ==> (k:A->B) (p z) = k z`
  (LABEL_TAC "deleted_preserves") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC PERMUTATION_DELETE_PRESERVES_KEY THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!m. ITER m (p:A->A) a IN s DELETE x /\
        (k:A->B) (ITER m p a) = k a`
  (LABEL_TAC "deleted_iter") THENL
   [MATCH_MP_TAC PERMUTATION_ITER_PRESERVES_KEY THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(k:A->B) x = k a` THENL
   [ALL_TAC;
    SUBGOAL_THEN
     `!n. ITER n (p:A->A) a = ITER n f a`
    (LABEL_TAC "same_iter") THENL
     [EXPAND_TAC "p" THEN
      MATCH_MP_TAC(ISPECL
       [`f:A->A`; `s:A->bool`; `x:A`; `k:A->B`; `a:A`]
       PERMUTATION_DELETE_ITER_OFF_KEY) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `?n. ITER n (f:A->A) a = b`
    (X_CHOOSE_THEN `n:num` (LABEL_TAC "old_step")) THENL
     [USE_THEN "transitive" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      EXISTS_TAC `n:num` THEN ASM_REWRITE_TAC[]]] THEN
  SUBGOAL_THEN
   `?z:A. (?m. ITER m (p:A->A) a = z) /\ (f:A->A) z = x`
  (X_CHOOSE_THEN `z:A`
    (CONJUNCTS_THEN2
      (X_CHOOSE_THEN `m:num` (LABEL_TAC "z_step"))
      (LABEL_TAC "z_enters"))) THENL
   [MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "no_entry") THEN
    SUBGOAL_THEN
     `!n. ?m. ITER m (p:A->A) a = ITER n f a`
    (LABEL_TAC "old_iter_in_deleted") THENL
     [INDUCT_TAC THENL
       [EXISTS_TAC `0` THEN REWRITE_TAC[ITER];
        FIRST_X_ASSUM(X_CHOOSE_THEN `m:num`
          (LABEL_TAC "old_iter_step")) THEN
        SUBGOAL_THEN
         `ITER n (f:A->A) a IN s /\ ~(ITER n f a = x)`
        (CONJUNCTS_THEN2 (LABEL_TAC "iter_member")
          (LABEL_TAC "iter_distinct")) THENL
         [USE_THEN "old_iter_step" (SUBST1_TAC o SYM) THEN
          MP_TAC(CONJUNCT1(SPEC `m:num` (ASSUME
           `!m. ITER m (p:A->A) a IN s DELETE x /\
                (k:A->B) (ITER m p a) = k a`))) THEN
          REWRITE_TAC[IN_DELETE];
          ALL_TAC] THEN
        SUBGOAL_THEN `~((f:A->A) (ITER n f a) = x)`
        (LABEL_TAC "not_enter") THENL
         [DISCH_THEN(LABEL_TAC "enters") THEN
          SUBGOAL_THEN
           `?z:A. (?j. ITER j (p:A->A) a = z) /\
                  (f:A->A) z = x`
          MP_TAC THENL
           [EXISTS_TAC `ITER n (f:A->A) a` THEN
            CONJ_TAC THENL
             [EXISTS_TAC `m:num` THEN ASM_REWRITE_TAC[];
              USE_THEN "enters" ACCEPT_TAC];
            ASM_REWRITE_TAC[]];
          ALL_TAC] THEN
        EXISTS_TAC `SUC m` THEN REWRITE_TAC[ITER] THEN
        EXPAND_TAC "p" THEN
        MP_TAC(ISPECL
         [`f:A->A`; `s:A->bool`; `x:A`; `ITER n (f:A->A) a`]
         PERMUTATION_DELETE_APPLY_IN) THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `?n. ITER n (f:A->A) a = x`
    (X_CHOOSE_THEN `n:num` (LABEL_TAC "old_reaches_x")) THENL
     [USE_THEN "transitive" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REMOVE_THEN "old_iter_in_deleted"
     (MP_TAC o SPEC `n:num`) THEN
    DISCH_THEN(X_CHOOSE_THEN `m:num` (LABEL_TAC "deleted_reaches_x")) THEN
    SUBGOAL_THEN `ITER m (p:A->A) a = x`
    (LABEL_TAC "deleted_reaches_x_direct") THENL
     [TRANS_TAC EQ_TRANS `ITER n (f:A->A) a` THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(CONJUNCT1(SPEC `m:num` (ASSUME
     `!m. ITER m (p:A->A) a IN s DELETE x /\
          (k:A->B) (ITER m p a) = k a`))) THEN
    REWRITE_TAC[IN_DELETE] THEN
    USE_THEN "deleted_reaches_x_direct" SUBST1_TAC THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?j. ITER j (p:A->A) a = (f:A->A) x`
  (X_CHOOSE_THEN `j:num` (LABEL_TAC "after_deleted")) THENL
   [EXISTS_TAC `SUC m` THEN REWRITE_TAC[ITER] THEN
    SUBGOAL_THEN `(z:A) IN s /\ ~(z = x)`
     (CONJUNCTS_THEN2 (LABEL_TAC "z_member")
      (LABEL_TAC "z_distinct")) THENL
     [USE_THEN "z_step" (SUBST1_TAC o SYM) THEN
      MP_TAC(CONJUNCT1(SPEC `m:num` (ASSUME
       `!m. ITER m (p:A->A) a IN s DELETE x /\
            (k:A->B) (ITER m p a) = k a`))) THEN
      REWRITE_TAC[IN_DELETE];
      ALL_TAC] THEN
    EXPAND_TAC "p" THEN
    MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`; `z:A`]
      PERMUTATION_DELETE_APPLY_IN) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!n. ITER n (f:A->A) a = x \/
        ?m. ITER m (p:A->A) a = ITER n f a`
  (LABEL_TAC "old_iter_covered") THENL
   [INDUCT_TAC THENL
     [DISJ2_TAC THEN EXISTS_TAC `0` THEN REWRITE_TAC[ITER];
      MP_TAC(ASSUME
       `ITER n (f:A->A) a = x \/
        ?m. ITER m (p:A->A) a = ITER n f a`) THEN
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "at_x")
       (X_CHOOSE_THEN `h:num` (LABEL_TAC "covered_step"))) THEN
      REWRITE_TAC[ITER] THENL
       [DISJ2_TAC THEN EXISTS_TAC `j:num` THEN ASM_REWRITE_TAC[];
        ASM_CASES_TAC `(f:A->A) (ITER n f a) = x` THENL
         [ASM_REWRITE_TAC[];
          DISJ2_TAC THEN EXISTS_TAC `SUC h` THEN
          REWRITE_TAC[ITER] THEN
          SUBGOAL_THEN
           `ITER n (f:A->A) a IN s /\ ~(ITER n f a = x)`
          (CONJUNCTS_THEN2 (LABEL_TAC "iter_member")
            (LABEL_TAC "iter_distinct")) THENL
           [USE_THEN "covered_step" (SUBST1_TAC o SYM) THEN
            MP_TAC(CONJUNCT1(SPEC `h:num` (ASSUME
             `!m. ITER m (p:A->A) a IN s DELETE x /\
                  (k:A->B) (ITER m p a) = k a`))) THEN
            REWRITE_TAC[IN_DELETE];
            ALL_TAC] THEN
          EXPAND_TAC "p" THEN
          MP_TAC(ISPECL
           [`f:A->A`; `s:A->bool`; `x:A`; `ITER n (f:A->A) a`]
           PERMUTATION_DELETE_APPLY_IN) THEN
          ASM_REWRITE_TAC[]]]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?n. ITER n (f:A->A) a = b`
  (X_CHOOSE_THEN `n:num` (LABEL_TAC "old_step")) THENL
   [USE_THEN "transitive" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[];
    REMOVE_THEN "old_iter_covered" (MP_TAC o SPEC `n:num`) THEN
    ASM_REWRITE_TAC[]]);;

let PERMUTATION_DELETE_TWO_TRANSITIVE_KEY = prove
 (`!f:A->A. !s x y k:A->B.
        f permutes s /\
        x IN s /\
        y IN s /\
        ~(x = y) /\
        (!z. z IN s ==> k(f z) = k z) /\
        (!a b. a IN s /\ b IN s /\ k a = k b
               ==> ?n. ITER n f a = b)
        ==> !a b. a IN s DELETE x DELETE y /\
                  b IN s DELETE x DELETE y /\
                  k a = k b
                  ==> ?n. ITER n (permutation_delete_two f x y) a = b`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "permutation x y distinct preserves transitive" THEN
  SUBGOAL_THEN
   `permutation_delete (f:A->A) x permutes (s DELETE x)`
  (LABEL_TAC "first_permutation") THENL
   [MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN s DELETE x
          ==> (k:A->B) (permutation_delete f x z) = k z`
  (LABEL_TAC "first_preserves") THENL
   [MATCH_MP_TAC PERMUTATION_DELETE_PRESERVES_KEY THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b:A. a IN s DELETE x /\ b IN s DELETE x /\
             (k:A->B) a = k b
             ==> ?n. ITER n (permutation_delete f x) a = b`
  (LABEL_TAC "first_transitive") THENL
   [MATCH_MP_TAC PERMUTATION_DELETE_TRANSITIVE_KEY THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[permutation_delete_two] THEN
  MATCH_MP_TAC PERMUTATION_DELETE_TRANSITIVE_KEY THEN
  ASM_REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The two deleted darts of an undirected edge.                              *)
(* ------------------------------------------------------------------------- *)

let GRAPH_DARTS_DELETE_EDGE = prove
 (`!E u v:A.
        graph_darts (E DELETE {u,v}) =
        graph_darts E DELETE (u,v) DELETE (v,u)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[EXTENSION; FORALL_PAIR_THM; graph_darts; IN_ELIM_THM;
              IN_DELETE; DART_EDGE_PAIR; PAIR_EQ] THEN
  SET_TAC[]);;

let graph_delete_rotation = new_definition
 `graph_delete_rotation (r:(A#A)->A#A) u v =
        permutation_delete_two r (u,v) (v,u)`;;

let GRAPH_DELETE_ROTATION_PERMUTES = prove
 (`!V E r u v:A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E
        ==> graph_delete_rotation r u v
            permutes graph_darts (E DELETE {u,v})`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation edge" THEN
  REWRITE_TAC[graph_delete_rotation; GRAPH_DARTS_DELETE_EDGE] THEN
  MATCH_MP_TAC PERMUTATION_DELETE_TWO_PERMUTES THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ASM_REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR];
    REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR] THEN
    SUBGOAL_THEN `{v:A,u} = {u,v}` SUBST1_TAC THENL
     [SET_TAC[];
      ASM_REWRITE_TAC[]];
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR; PAIR_EQ] THEN
    MESON_TAC[]]);;

let GRAPH_DELETE_ROTATION_TAIL = prove
 (`!V E r u v:A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E
        ==> !d. d IN graph_darts (E DELETE {u,v})
                ==> FST(graph_delete_rotation r u v d) = FST d`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation edge" THEN
  SUBGOAL_THEN
   `!d:A#A. d IN graph_darts E ==> FST((r:(A#A)->A#A) d) = FST d`
  (LABEL_TAC "tail") THENL
   [ASM_MESON_TAC[GRAPH_ROTATION_TAIL];
    ALL_TAC] THEN
  REWRITE_TAC[graph_delete_rotation; GRAPH_DARTS_DELETE_EDGE] THEN
  MATCH_MP_TAC PERMUTATION_DELETE_TWO_PRESERVES_KEY THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ASM_REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR];
    REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR] THEN
    SUBGOAL_THEN `{v:A,u} = {u,v}` SUBST1_TAC THENL
     [SET_TAC[];
      ASM_REWRITE_TAC[]];
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR; PAIR_EQ] THEN
    MESON_TAC[];
    USE_THEN "tail" ACCEPT_TAC]);;

let GRAPH_DELETE_ROTATION = prove
 (`!V E r u v:A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E
        ==> graph_rotation (E DELETE {u,v})
             (graph_delete_rotation r u v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation edge" THEN
  REWRITE_TAC[graph_rotation] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`] GRAPH_DELETE_ROTATION_PERMUTES) THEN
    ASM_REWRITE_TAC[];
    X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "dart") THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`] GRAPH_DELETE_ROTATION_TAIL) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `d:A#A`) THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`d:A#A`; `d':A#A`] THEN
    INTRO_TAC "dart dart' same_tail" THEN
    MP_TAC(ISPECL
     [`r:(A#A)->A#A`; `graph_darts E:(A#A)->bool`;
      `((u:A),(v:A))`; `((v:A),(u:A))`; `FST:(A#A)->A`]
     PERMUTATION_DELETE_TWO_TRANSITIVE_KEY) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
        USE_THEN "rotation" ACCEPT_TAC;
        ASM_REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR];
        REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR] THEN
        SUBGOAL_THEN `{v:A,u} = {u,v}` SUBST1_TAC THENL
         [SET_TAC[];
          ASM_REWRITE_TAC[]];
        MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
         FINITE_SIMPLE_GRAPH_DART) THEN
        ASM_REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR; PAIR_EQ] THEN
        MESON_TAC[];
        X_GEN_TAC `z:A#A` THEN DISCH_THEN(LABEL_TAC "z_dart") THEN
        MATCH_MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `z:A#A`]
         GRAPH_ROTATION_TAIL) THEN
        ASM_REWRITE_TAC[];
        MAP_EVERY X_GEN_TAC [`a:A#A`; `b:A#A`] THEN
        INTRO_TAC "a_dart b_dart same_tail" THEN
        MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `a:A#A`; `b:A#A`]
         GRAPH_ROTATION_ORBIT) THEN
        ASM_REWRITE_TAC[]];
      DISCH_THEN(MP_TAC o SPECL [`d:A#A`; `d':A#A`]) THEN
      REWRITE_TAC[GSYM graph_delete_rotation;
                  GSYM GRAPH_DARTS_DELETE_EDGE] THEN
      ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* Splicing two cyclic permutations at one common point.                     *)
(* ------------------------------------------------------------------------- *)

let permutation_cycle_splice = new_definition
 `permutation_cycle_splice (f:A->A) (s:A->bool) (g:A->A) x =
        swap(x,g x) o
        disjoint_permutation_union f s (permutation_delete g x)`;;

let PERMUTATION_CYCLE_SPLICE_PERMUTES = prove
 (`!f g:A->A. !s t x.
        FINITE s /\
        FINITE t /\
        f permutes s /\
        g permutes t /\
        s INTER t = {x} /\
        x IN s /\
        x IN t /\
        ~(g x = x)
        ==> permutation_cycle_splice f s g x
            permutes (s UNION t)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite_s finite_t f_permutation g_permutation overlap
    x_s x_t nonfixed" THEN
  ABBREV_TAC `t' = (t:A->bool) DELETE x` THEN
  SUBGOAL_THEN `FINITE(t':A->bool)` (LABEL_TAC "finite_t'") THENL
   [EXPAND_TAC "t'" THEN ASM_REWRITE_TAC[FINITE_DELETE];
    ALL_TAC] THEN
  SUBGOAL_THEN `DISJOINT (s:A->bool) t'`
  (LABEL_TAC "disjoint") THENL
   [USE_THEN "overlap" MP_TAC THEN
    EXPAND_TAC "t'" THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_DELETE;
                IN_SING; NOT_IN_EMPTY] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_delete (g:A->A) x permutes t'`
  (LABEL_TAC "deleted_permutation") THENL
   [EXPAND_TAC "t'" THEN
    MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `disjoint_permutation_union (f:A->A) s (permutation_delete g x)
    permutes (s UNION t')`
  (LABEL_TAC "union_permutation") THENL
   [MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(g:A->A) x IN t'`
  (LABEL_TAC "gx_t'") THENL
   [EXPAND_TAC "t'" THEN REWRITE_TAC[IN_DELETE] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`g:A->A`; `t:A->bool`; `x:A`]
      PERMUTES_IN_IMAGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `s UNION t' = (s UNION t:A->bool)`
  (LABEL_TAC "union") THENL
   [EXPAND_TAC "t'" THEN ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(swap(x,(g:A->A) x) o
     disjoint_permutation_union f s (permutation_delete g x))
    permutes (s UNION t')`
  (LABEL_TAC "spliced_permutation") THENL
   [MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN
    ASM_REWRITE_TAC[IN_UNION];
    ALL_TAC] THEN
  REWRITE_TAC[permutation_cycle_splice] THEN
  (fun (asl,_ as goal) ->
    ACCEPT_TAC
     (REWRITE_RULE
       [assoc "union" asl]
       (assoc "spliced_permutation" asl))
     goal));;

let PERMUTATION_DELETE_TRANSITIVE = prove
 (`!g:A->A. !t x.
        g permutes t /\
        x IN t /\
        (!a b. a IN t /\ b IN t ==> ?n. ITER n g a = b)
        ==> !a b.
              a IN t DELETE x /\
              b IN t DELETE x
              ==> ?n. ITER n (permutation_delete g x) a = b`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation member transitive" THEN
  MP_TAC(ISPECL
   [`g:A->A`; `t:A->bool`; `x:A`; `\z:A. T`]
   PERMUTATION_DELETE_TRANSITIVE_KEY) THEN
  ASM_REWRITE_TAC[]);;

let PERMUTATION_CYCLE_SPLICE_TRANSITIVE = prove
 (`!f g:A->A. !s t x.
        FINITE s /\
        FINITE t /\
        f permutes s /\
        g permutes t /\
        s INTER t = {x} /\
        x IN s /\
        x IN t /\
        ~(g x = x) /\
        (!a b. a IN s /\ b IN s ==> ?n. ITER n f a = b) /\
        (!a b. a IN t /\ b IN t ==> ?n. ITER n g a = b)
        ==> !a b.
              a IN s UNION t /\
              b IN s UNION t
              ==> ?n. ITER n (permutation_cycle_splice f s g x) a = b`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite_s finite_t f_permutation g_permutation overlap
    x_s x_t nonfixed f_transitive g_transitive" THEN
  ABBREV_TAC `t' = (t:A->bool) DELETE x` THEN
  ABBREV_TAC
   `p:A->A =
      disjoint_permutation_union (f:A->A) s (permutation_delete g x)` THEN
  SUBGOAL_THEN
   `(p:A->A) =
    disjoint_permutation_union f s (permutation_delete g x)`
  (LABEL_TAC "p_definition") THENL
   [EXPAND_TAC "p" THEN REFL_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(t':A->bool)` (LABEL_TAC "finite_t'") THENL
   [EXPAND_TAC "t'" THEN ASM_REWRITE_TAC[FINITE_DELETE];
    ALL_TAC] THEN
  SUBGOAL_THEN `DISJOINT (s:A->bool) t'`
  (LABEL_TAC "disjoint") THENL
   [USE_THEN "overlap" MP_TAC THEN
    EXPAND_TAC "t'" THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_DELETE;
                IN_SING; NOT_IN_EMPTY] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_delete (g:A->A) x permutes t'`
  (LABEL_TAC "deleted_permutation") THENL
   [EXPAND_TAC "t'" THEN
    MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b:A.
        a IN t' /\ b IN t'
        ==> ?n. ITER n (permutation_delete g x) a = b`
  (LABEL_TAC "deleted_transitive") THENL
   [EXPAND_TAC "t'" THEN
    MATCH_MP_TAC PERMUTATION_DELETE_TRANSITIVE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(g:A->A) x IN t'`
  (LABEL_TAC "gx_t'") THENL
   [EXPAND_TAC "t'" THEN REWRITE_TAC[IN_DELETE] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`g:A->A`; `t:A->bool`; `x:A`]
      PERMUTES_IN_IMAGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbits (p:A->A) (s UNION t') = {s,t'}`
  (LABEL_TAC "two_orbits") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC(ISPECL
     [`f:A->A`; `permutation_delete (g:A->A) x`;
      `s:A->bool`; `t':A->bool`; `x:A`; `(g:A->A) x`]
     PERMUTATION_ORBITS_DISJOINT_UNION_TRANSITIVE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((s:A->bool) = t')` (LABEL_TAC "different_sets") THENL
   [DISCH_THEN(LABEL_TAC "equal_sets") THEN
    SUBGOAL_THEN `(x:A) IN t'` (LABEL_TAC "x_t'") THENL
     [USE_THEN "equal_sets" (fun th -> REWRITE_TAC[GSYM th]) THEN
      USE_THEN "x_s" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "disjoint" MP_TAC THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `x:A`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(permutation_orbits (p:A->A) (s UNION t')) = 2`
  (LABEL_TAC "two_count") THENL
   [USE_THEN "two_orbits" (fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[CARD_CLAUSES; FINITE_INSERT; FINITE_EMPTY;
                 NOT_IN_EMPTY; IN_SING] THEN
    ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:A->A) permutes (s UNION t')`
  (LABEL_TAC "union_permutation") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit (p:A->A) x = s /\
    permutation_orbit p (g x) = t'`
  (CONJUNCTS_THEN2 (LABEL_TAC "x_orbit") (LABEL_TAC "gx_orbit")) THENL
   [CONJ_TAC THENL
     [EXPAND_TAC "p" THEN
      MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_ORBIT_LEFT THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `y:A` THEN DISCH_THEN(LABEL_TAC "y_s") THEN
      USE_THEN "f_transitive"
       (MATCH_MP_TAC o SPECL [`x:A`; `y:A`]) THEN
      ASM_REWRITE_TAC[];
      EXPAND_TAC "p" THEN
      MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_ORBIT_RIGHT THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `y:A` THEN DISCH_THEN(LABEL_TAC "y_t'") THEN
      USE_THEN "deleted_transitive"
       (MATCH_MP_TAC o SPECL [`(g:A->A) x`; `y:A`]) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD
     (permutation_orbits
       (swap(x,(g:A->A) x) o p) (s UNION t')) = 1`
  (LABEL_TAC "one_count") THENL
   [SUBGOAL_THEN
     `CARD(permutation_orbits (p:A->A) (s UNION t')) =
      CARD
       (permutation_orbits
         (swap(x,(g:A->A) x) o p) (s UNION t')) + 1`
    (LABEL_TAC "merged_count") THENL
     [MATCH_MP_TAC(ISPECL
       [`p:A->A`; `s UNION t':A->bool`; `x:A`; `(g:A->A) x`]
       PERMUTATION_ORBITS_SWAP_DISTINCT) THEN
      ASM_REWRITE_TAC[FINITE_UNION; IN_UNION];
      REMOVE_THEN "merged_count" MP_TAC THEN
      REMOVE_THEN "two_count" MP_TAC THEN
      ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(swap(x,(g:A->A) x) o p) permutes (s UNION t')`
  (LABEL_TAC "spliced_permutation") THENL
   [MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN
    ASM_REWRITE_TAC[IN_UNION];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b:A.
        a IN s UNION t' /\ b IN s UNION t'
        ==> ?n. ITER n (swap(x,g x) o p) a = b`
  (LABEL_TAC "spliced_transitive") THENL
   [MATCH_MP_TAC FINITE_PERMUTATION_ONE_ORBIT_TRANSITIVE THEN
    ASM_REWRITE_TAC[FINITE_UNION];
    ALL_TAC] THEN
  SUBGOAL_THEN `s UNION t' = (s UNION t:A->bool)`
  (LABEL_TAC "union") THENL
   [EXPAND_TAC "t'" THEN ASM SET_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[permutation_cycle_splice] THEN
  (fun (asl,_ as goal) ->
    ACCEPT_TAC
     (REWRITE_RULE
       [assoc "p_definition" asl; assoc "union" asl]
       (assoc "spliced_transitive" asl))
     goal));;

let SWAP_PRESERVES_KEY = prove
 (`!k:A->B. !a b z.
        k a = k b
        ==> k(swap(a,b) z) = k z`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  ASM_CASES_TAC `(z:A) = a` THENL
   [ASM_REWRITE_TAC[SWAP_LEFT];
    ASM_CASES_TAC `(z:A) = b` THENL
     [ASM_REWRITE_TAC[SWAP_RIGHT];
      ASM_SIMP_TAC[SWAP_OTHER]]]);;

let PERMUTATION_CYCLE_SPLICE_PRESERVES_KEY = prove
 (`!f g:A->A. !s t x. !k:A->B.
        FINITE s /\
        FINITE t /\
        f permutes s /\
        g permutes t /\
        s INTER t = {x} /\
        x IN s /\
        x IN t /\
        ~(g x = x) /\
        (!z. z IN s ==> k(f z) = k z) /\
        (!z. z IN t ==> k(g z) = k z)
        ==> !z.
              z IN s UNION t
              ==> k(permutation_cycle_splice f s g x z) = k z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite_s finite_t f_permutation g_permutation overlap
    x_s x_t nonfixed f_preserves g_preserves" THEN
  ABBREV_TAC `t' = (t:A->bool) DELETE x` THEN
  ABBREV_TAC
   `p:A->A =
      disjoint_permutation_union (f:A->A) s (permutation_delete g x)` THEN
  SUBGOAL_THEN
   `(p:A->A) =
    disjoint_permutation_union f s (permutation_delete g x)`
  (LABEL_TAC "p_definition") THENL
   [EXPAND_TAC "p" THEN REFL_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(t':A->bool)` (LABEL_TAC "finite_t'") THENL
   [EXPAND_TAC "t'" THEN ASM_REWRITE_TAC[FINITE_DELETE];
    ALL_TAC] THEN
  SUBGOAL_THEN `DISJOINT (s:A->bool) t'`
  (LABEL_TAC "disjoint") THENL
   [USE_THEN "overlap" MP_TAC THEN
    EXPAND_TAC "t'" THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_DELETE;
                IN_SING; NOT_IN_EMPTY] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_delete (g:A->A) x permutes t'`
  (LABEL_TAC "deleted_permutation") THENL
   [EXPAND_TAC "t'" THEN
    MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN t'
           ==> (k:A->B) (permutation_delete g x z) = k z`
  (LABEL_TAC "deleted_preserves") THENL
   [EXPAND_TAC "t'" THEN
    MATCH_MP_TAC PERMUTATION_DELETE_PRESERVES_KEY THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:A->A) permutes (s UNION t')`
  (LABEL_TAC "union_permutation") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN s UNION t' ==> (k:A->B) (p z) = k z`
  (LABEL_TAC "union_preserves") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_PRESERVES_KEY THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(g:A->A) x IN t'`
  (LABEL_TAC "gx_t'") THENL
   [EXPAND_TAC "t'" THEN REWRITE_TAC[IN_DELETE] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`g:A->A`; `t:A->bool`; `x:A`]
      PERMUTES_IN_IMAGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(k:A->B) (g x) = k x`
  (LABEL_TAC "splice_key") THENL
   [USE_THEN "g_preserves" (MATCH_MP_TAC o SPEC `x:A`) THEN
    USE_THEN "x_t" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `s UNION t' = (s UNION t:A->bool)`
  (LABEL_TAC "union") THENL
   [EXPAND_TAC "t'" THEN ASM SET_TAC[];
    ALL_TAC] THEN
  X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_union") THEN
  SUBGOAL_THEN `(z:A) IN s UNION t'` (LABEL_TAC "z_old_union") THENL
   [USE_THEN "union" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "z_union" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:A->A) z IN s UNION t'`
  (LABEL_TAC "pz_union") THENL
   [(fun (asl,_ as goal) ->
      let image_equivalence =
        MATCH_MP
         (ISPECL [`p:A->A`; `s UNION t':A->bool`; `z:A`]
           PERMUTES_IN_IMAGE)
         (assoc "union_permutation" asl) in
      ACCEPT_TAC
       (EQ_MP
         (SYM image_equivalence)
         (assoc "z_old_union" asl))
       goal);
    ALL_TAC] THEN
  SUBGOAL_THEN `(k:A->B) (p z) = k z`
  (LABEL_TAC "pz_key") THENL
   [USE_THEN "union_preserves" (MATCH_MP_TAC o SPEC `z:A`) THEN
    USE_THEN "z_old_union" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[permutation_cycle_splice; o_THM] THEN
  (fun (asl,_ as goal) ->
    let swap_key =
      MATCH_MP
       (ISPECL
         [`k:A->B`; `x:A`; `(g:A->A) x`; `(p:A->A) z`]
         SWAP_PRESERVES_KEY)
       (SYM(assoc "splice_key" asl)) in
    ACCEPT_TAC
     (REWRITE_RULE
       [assoc "p_definition" asl]
       (TRANS swap_key (assoc "pz_key" asl)))
     goal));;

(* ------------------------------------------------------------------------- *)
(* Orbit counts for deletion and disjoint union of finite permutations.      *)
(* ------------------------------------------------------------------------- *)

let PERMUTATION_DELETE_ORBIT_COUNT = prove
 (`!f:A->A. !s x.
        FINITE s /\
        f permutes s /\
        x IN s /\
        ~(f x = x)
        ==> CARD
             (permutation_orbits
               (permutation_delete f x) (s DELETE x)) =
            CARD(permutation_orbits f s)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite permutation member nonfixed" THEN
  ABBREV_TAC `a:A = inverse (f:A->A) x` THEN
  SUBGOAL_THEN `(f:A->A) a = x` (LABEL_TAC "predecessor") THENL
   [EXPAND_TAC "a" THEN
    MP_TAC(MATCH_MP
     (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INVERSES)
     (ASSUME `(f:A->A) permutes s`)) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:A) IN s` (LABEL_TAC "predecessor_member") THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`]
      PERMUTES_IN_IMAGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((a:A) = x)` (LABEL_TAC "predecessor_distinct") THENL
   [ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_delete (f:A->A) x a = f x`
  (LABEL_TAC "deleted_predecessor") THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`; `a:A`]
      PERMUTATION_DELETE_APPLY_IN) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_insert (permutation_delete (f:A->A) x) x a = f`
  (LABEL_TAC "reconstruct") THENL
   [REWRITE_TAC[permutation_insert] THEN
    USE_THEN "deleted_predecessor" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[permutation_delete] THEN
    ONCE_REWRITE_TAC[o_ASSOC] THEN
    REWRITE_TAC[SWAP_IDEMPOTENT; I_O_ID];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `x INSERT ((s:A->bool) DELETE x) = s`
  (LABEL_TAC "restore_set") THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`permutation_delete (f:A->A) x`; `(s:A->bool) DELETE x`;
    `x:A`; `a:A`]
   PERMUTATION_INSERT_ORBIT_COUNT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[FINITE_DELETE];
      MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[IN_DELETE];
      REWRITE_TAC[IN_DELETE]];
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(ACCEPT_TAC o SYM)]);;

let PERMUTATION_DELETE_TWO_ORBIT_COUNT = prove
 (`!f:A->A. !s x y.
        FINITE s /\
        f permutes s /\
        x IN s /\
        y IN s /\
        ~(x = y) /\
        ~(f x = x) /\
        ~(permutation_delete f x y = y)
        ==> CARD
             (permutation_orbits
               (permutation_delete_two f x y)
               (s DELETE x DELETE y)) =
            CARD(permutation_orbits f s)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite permutation x_member y_member distinct
    x_nonfixed y_nonfixed" THEN
  SUBGOAL_THEN
   `permutation_delete (f:A->A) x permutes (s DELETE x)`
  (LABEL_TAC "deleted_permutation") THENL
   [MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(y:A) IN s DELETE x`
  (LABEL_TAC "y_survives") THENL
   [ASM_REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`permutation_delete (f:A->A) x`;
    `(s:A->bool) DELETE x`; `y:A`]
   PERMUTATION_DELETE_ORBIT_COUNT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[FINITE_DELETE];
    DISCH_THEN(LABEL_TAC "second_deletion")] THEN
  MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`]
    PERMUTATION_DELETE_ORBIT_COUNT) THEN
  ASM_REWRITE_TAC[permutation_delete_two] THEN
  DISCH_THEN(LABEL_TAC "first_deletion") THEN
  ASM_REWRITE_TAC[]);;

let PERMUTATION_ORBITS_EQ_ON = prove
 (`!f g:A->A. !s.
        f permutes s /\
        (!x. x IN s ==> g x = f x)
        ==> permutation_orbits g s = permutation_orbits f s`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation agree" THEN
  SUBGOAL_THEN
   `!x:A. x IN s
           ==> permutation_orbit g x = permutation_orbit f x`
  (LABEL_TAC "same_orbit") THENL
   [X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "x_member") THEN
    MATCH_MP_TAC PERMUTATION_ORBIT_EQ_IF_AGREE THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_orbit") THEN
    USE_THEN "agree" (MATCH_MP_TAC o SPEC `z:A`) THEN
    MATCH_MP_TAC
     (REWRITE_RULE[SUBSET]
       (MATCH_MP
         (ISPECL [`f:A->A`; `s:A->bool`; `x:A`]
          PERMUTATION_ORBIT_SUBSET)
         (CONJ (ASSUME `(f:A->A) permutes s`)
               (ASSUME `(x:A) IN s`)))) THEN
    USE_THEN "z_orbit" ACCEPT_TAC;
    REWRITE_TAC[permutation_orbits; EXTENSION; IN_IMAGE] THEN
    ASM_MESON_TAC[]]);;

let PERMUTATION_ORBIT_DISJOINT_UNION_LEFT = prove
 (`!f g:A->A. !s x.
        f permutes s /\
        x IN s
        ==> permutation_orbit
             (disjoint_permutation_union f s g) x =
            permutation_orbit f x`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation member" THEN
  REWRITE_TAC[EXTENSION; IN_PERMUTATION_ORBIT] THEN
  X_GEN_TAC `y:A` THEN EQ_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THEN
  EXISTS_TAC `n:num` THEN
  MP_TAC(SPEC `n:num`
   (MATCH_MP
    (ISPECL [`f:A->A`; `g:A->A`; `s:A->bool`; `x:A`]
     DISJOINT_PERMUTATION_UNION_ITER_LEFT)
    (CONJ (ASSUME `(f:A->A) permutes s`)
          (ASSUME `(x:A) IN s`)))) THEN
  ASM_REWRITE_TAC[] THEN MESON_TAC[]);;

let PERMUTATION_ORBIT_DISJOINT_UNION_RIGHT = prove
 (`!f g:A->A. !s t x.
        g permutes t /\
        DISJOINT s t /\
        x IN t
        ==> permutation_orbit
             (disjoint_permutation_union f s g) x =
            permutation_orbit g x`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation disjoint member" THEN
  REWRITE_TAC[EXTENSION; IN_PERMUTATION_ORBIT] THEN
  X_GEN_TAC `y:A` THEN EQ_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THEN
  EXISTS_TAC `n:num` THEN
  MP_TAC(SPEC `n:num`
   (MATCH_MP
    (ISPECL
     [`f:A->A`; `g:A->A`; `s:A->bool`; `t:A->bool`; `x:A`]
     DISJOINT_PERMUTATION_UNION_ITER_RIGHT)
    (end_itlist CONJ
     [ASSUME `(g:A->A) permutes t`;
      ASSUME `DISJOINT (s:A->bool) t`;
      ASSUME `(x:A) IN t`]))) THEN
  ASM_REWRITE_TAC[] THEN MESON_TAC[]);;

let PERMUTATION_ORBITS_DISJOINT_UNION = prove
 (`!f g:A->A. !s t.
        f permutes s /\
        g permutes t /\
        DISJOINT s t
        ==> permutation_orbits
             (disjoint_permutation_union f s g) (s UNION t) =
            permutation_orbits f s UNION permutation_orbits g t`,
  REPEAT GEN_TAC THEN INTRO_TAC "f_permutation g_permutation disjoint" THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THEN
  REWRITE_TAC[SUBSET; IN_PERMUTATION_ORBITS; IN_UNION] THEN
  X_GEN_TAC `c:A->bool` THENL
   [INTRO_TAC "@x. x_union orbit" THEN
    USE_THEN "x_union"
     (DISJ_CASES_THEN2 (LABEL_TAC "x_left") (LABEL_TAC "x_right")) THENL
     [DISJ1_TAC THEN EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC EQ_TRANS THEN
      EXISTS_TAC
       `permutation_orbit
         (disjoint_permutation_union (f:A->A) s g) x` THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC PERMUTATION_ORBIT_DISJOINT_UNION_LEFT THEN
      ASM_REWRITE_TAC[];
      DISJ2_TAC THEN EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC EQ_TRANS THEN
      EXISTS_TAC
       `permutation_orbit
         (disjoint_permutation_union (f:A->A) s g) x` THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(ISPECL
       [`f:A->A`; `g:A->A`; `s:A->bool`; `t:A->bool`; `x:A`]
       PERMUTATION_ORBIT_DISJOINT_UNION_RIGHT) THEN
      ASM_REWRITE_TAC[]];
    DISCH_THEN(DISJ_CASES_THEN2
      (X_CHOOSE_THEN `x:A`
       (CONJUNCTS_THEN2 (LABEL_TAC "x_left") (LABEL_TAC "orbit")))
      (X_CHOOSE_THEN `x:A`
       (CONJUNCTS_THEN2 (LABEL_TAC "x_right") (LABEL_TAC "orbit")))) THENL
     [EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[IN_UNION] THEN
      USE_THEN "orbit" SUBST1_TAC THEN
      CONV_TAC SYM_CONV THEN
      MATCH_MP_TAC PERMUTATION_ORBIT_DISJOINT_UNION_LEFT THEN
      ASM_REWRITE_TAC[];
      EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[IN_UNION] THEN
      USE_THEN "orbit" SUBST1_TAC THEN
      CONV_TAC SYM_CONV THEN
      MATCH_MP_TAC(ISPECL
       [`f:A->A`; `g:A->A`; `s:A->bool`; `t:A->bool`; `x:A`]
       PERMUTATION_ORBIT_DISJOINT_UNION_RIGHT) THEN
      ASM_REWRITE_TAC[]]]);;

let DISJOINT_PERMUTATION_ORBITS = prove
 (`!f g:A->A. !s t.
        f permutes s /\
        g permutes t /\
        DISJOINT s t
        ==> DISJOINT (permutation_orbits f s) (permutation_orbits g t)`,
  REPEAT GEN_TAC THEN INTRO_TAC "f_permutation g_permutation disjoint" THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  X_GEN_TAC `c:A->bool` THEN
  REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (X_CHOOSE_THEN `x:A`
     (CONJUNCTS_THEN2 (LABEL_TAC "x_member") (LABEL_TAC "left_orbit")))
    (X_CHOOSE_THEN `y:A`
     (CONJUNCTS_THEN2 (LABEL_TAC "y_member") (LABEL_TAC "right_orbit")))) THEN
  SUBGOAL_THEN `(x:A) IN permutation_orbit g y`
  (LABEL_TAC "x_right_orbit") THENL
   [USE_THEN "right_orbit" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "left_orbit" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL;
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:A) IN t` (LABEL_TAC "x_right") THENL
   [MATCH_MP_TAC
     (REWRITE_RULE[SUBSET]
      (MATCH_MP
       (ISPECL [`g:A->A`; `t:A->bool`; `y:A`]
        PERMUTATION_ORBIT_SUBSET)
       (CONJ (ASSUME `(g:A->A) permutes t`)
             (ASSUME `(y:A) IN t`)))) THEN
    USE_THEN "x_right_orbit" ACCEPT_TAC;
    USE_THEN "disjoint" MP_TAC THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `x:A`) THEN ASM_REWRITE_TAC[]]);;

let PERMUTATION_ORBIT_DISJOINT_UNION_DISTINCT = prove
 (`!f g:A->A. !s t a b.
        f permutes s /\
        g permutes t /\
        DISJOINT s t /\
        a IN s /\
        b IN t
        ==> ~(permutation_orbit
               (disjoint_permutation_union f s g) a =
              permutation_orbit
               (disjoint_permutation_union f s g) b)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "f_permutation g_permutation disjoint a_member b_member" THEN
  SUBGOAL_THEN
   `permutation_orbit
     (disjoint_permutation_union (f:A->A) s g) a =
    permutation_orbit f a`
  (LABEL_TAC "left_orbit") THENL
   [MATCH_MP_TAC PERMUTATION_ORBIT_DISJOINT_UNION_LEFT THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit
     (disjoint_permutation_union (f:A->A) s g) b =
    permutation_orbit g b`
  (LABEL_TAC "right_orbit") THENL
   [MATCH_MP_TAC(ISPECL
     [`f:A->A`; `g:A->A`; `s:A->bool`; `t:A->bool`; `b:A`]
     PERMUTATION_ORBIT_DISJOINT_UNION_RIGHT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "same") THEN
  SUBGOAL_THEN `(a:A) IN permutation_orbit g b`
  (LABEL_TAC "a_right_orbit") THENL
   [USE_THEN "right_orbit" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "same" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL;
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:A) IN t` (LABEL_TAC "a_right") THENL
   [MATCH_MP_TAC
     (REWRITE_RULE[SUBSET]
      (MATCH_MP
       (ISPECL [`g:A->A`; `t:A->bool`; `b:A`]
        PERMUTATION_ORBIT_SUBSET)
       (CONJ (ASSUME `(g:A->A) permutes t`)
             (ASSUME `(b:A) IN t`)))) THEN
    USE_THEN "a_right_orbit" ACCEPT_TAC;
    USE_THEN "disjoint" MP_TAC THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `a:A`) THEN ASM_REWRITE_TAC[]]);;

let CARD_PERMUTATION_ORBITS_DISJOINT_UNION = prove
 (`!f g:A->A. !s t.
        FINITE s /\
        FINITE t /\
        f permutes s /\
        g permutes t /\
        DISJOINT s t
        ==> CARD
             (permutation_orbits
               (disjoint_permutation_union f s g) (s UNION t)) =
            CARD(permutation_orbits f s) +
            CARD(permutation_orbits g t)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite_s finite_t f_permutation g_permutation disjoint" THEN
  SUBGOAL_THEN
   `permutation_orbits
      (disjoint_permutation_union (f:A->A) s g) (s UNION t) =
    permutation_orbits f s UNION permutation_orbits g t`
  SUBST1_TAC THENL
   [MATCH_MP_TAC PERMUTATION_ORBITS_DISJOINT_UNION THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC CARD_UNION THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_PERMUTATION_ORBITS THEN
      USE_THEN "finite_s" ACCEPT_TAC;
      MATCH_MP_TAC FINITE_PERMUTATION_ORBITS THEN
      USE_THEN "finite_t" ACCEPT_TAC;
      MP_TAC(MATCH_MP
       (ISPECL [`f:A->A`; `g:A->A`; `s:A->bool`; `t:A->bool`]
        DISJOINT_PERMUTATION_ORBITS)
       (end_itlist CONJ
        [ASSUME `(f:A->A) permutes s`;
         ASSUME `(g:A->A) permutes t`;
         ASSUME `DISJOINT (s:A->bool) t`])) THEN
      REWRITE_TAC[DISJOINT]]]);;

(* ------------------------------------------------------------------------- *)
(* Gluing Euler rotations along a common boundary edge.                      *)
(* ------------------------------------------------------------------------- *)

let GRAPH_DARTS_UNION = prove
 (`!E1 E2:(A->bool)->bool.
        graph_darts (E1 UNION E2) =
        graph_darts E1 UNION graph_darts E2`,
  REWRITE_TAC[graph_darts; EXTENSION; IN_ELIM_THM; IN_UNION]);;

let GRAPH_DARTS_INTER = prove
 (`!E1 E2:(A->bool)->bool.
        graph_darts (E1 INTER E2) =
        graph_darts E1 INTER graph_darts E2`,
  REWRITE_TAC[graph_darts; EXTENSION; IN_ELIM_THM; IN_INTER]);;

let OUTGOING_DARTS_UNION = prove
 (`!E1 E2:(A->bool)->bool. !u:A.
        outgoing_darts (E1 UNION E2) u =
        outgoing_darts E1 u UNION outgoing_darts E2 u`,
  REWRITE_TAC[EXTENSION; IN_OUTGOING_DARTS; GRAPH_DARTS_UNION;
              IN_UNION] THEN
  MESON_TAC[]);;

let OUTGOING_DARTS_EMPTY_OUTSIDE_VERTICES = prove
 (`!V E u:A.
        finite_simple_graph V E /\
        ~(u IN V)
        ==> outgoing_darts E u = {}`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph outside" THEN
  REWRITE_TAC[EXTENSION; NOT_IN_EMPTY; IN_OUTGOING_DARTS] THEN
  X_GEN_TAC `d:A#A` THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (LABEL_TAC "dart") (LABEL_TAC "tail")) THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `d:A#A`]
   FINITE_SIMPLE_GRAPH_DART_FST) THEN
  ASM_REWRITE_TAC[]);;

let OUTGOING_DARTS_TAIL_UNIQUE = prove
 (`!E:(A->bool)->bool. !u v:A. !d:A#A.
        d IN outgoing_darts E u /\
        d IN outgoing_darts E v
        ==> u = v`,
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[]);;

let RESTRICTED_PERMUTATION_IMAGE = prove
 (`!f:A->A. !s.
        IMAGE (restricted_permutation f s) s = IMAGE f s`,
  REWRITE_TAC[EXTENSION; IN_IMAGE; restricted_permutation] THEN
  MESON_TAC[]);;

let GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES = prove
  (`!V E r u:A.
        finite_simple_graph V E /\
        graph_rotation E r
        ==> restricted_permutation r (outgoing_darts E u)
            permutes outgoing_darts E u`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation" THEN
  MATCH_MP_TAC(ISPECL
   [`r:(A#A)->A#A`; `graph_darts E:A#A->bool`;
    `outgoing_darts E u:A#A->bool`]
  RESTRICTED_PERMUTATION_PERMUTES) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
     FINITE_OUTGOING_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    MATCH_ACCEPT_TAC(ISPECL
     [`E:(A->bool)->bool`; `u:A`] OUTGOING_DARTS_SUBSET);
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`]
     GRAPH_ROTATION_PERMUTES) THEN
    USE_THEN "rotation" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `u:A`]
     GRAPH_ROTATION_IMAGE_OUTGOING_DARTS) THEN
    USE_THEN "rotation" ACCEPT_TAC]);;

let GRAPH_ROTATION_RESTRICTED_OUTGOING_TRANSITIVE = prove
 (`!E r u:A.
        graph_rotation E r
        ==> !d d':A#A.
              d IN outgoing_darts E u /\
              d' IN outgoing_darts E u
              ==> ?n.
                    ITER n
                     (restricted_permutation r (outgoing_darts E u)) d =
                    d'`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "rotation") THEN
  MATCH_MP_TAC RESTRICTED_PERMUTATION_TRANSITIVE THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC GRAPH_ROTATION_IMAGE_OUTGOING_DARTS THEN
    USE_THEN "rotation" ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`d:A#A`; `d':A#A`] THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN
    INTRO_TAC "(dart tail) dart' tail'" THEN
    USE_THEN "rotation" MP_TAC THEN
    REWRITE_TAC[graph_rotation] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 (K ALL_TAC)
       (MP_TAC o SPECL [`d:A#A`; `d':A#A`]))) THEN
    ASM_REWRITE_TAC[]]);;

let RESTRICTED_PERMUTATION_OUTGOING_IMAGE = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !u:A. !d:A#A.
        restricted_permutation r (outgoing_darts E u)
          permutes outgoing_darts E u /\
        d IN outgoing_darts E u
        ==> r d IN outgoing_darts E u`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation outgoing" THEN
  MP_TAC(ISPECL
   [`restricted_permutation
      (r:(A#A)->A#A) (outgoing_darts E u)`;
    `outgoing_darts E u:A#A->bool`; `d:A#A`]
   PERMUTES_IN_IMAGE) THEN
  ASM_REWRITE_TAC[restricted_permutation]);;

let GRAPH_ROTATION_OF_RESTRICTED_OUTGOING = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A.
        FINITE(graph_darts E) /\
        (!d. ~(d IN graph_darts E) ==> r d = d) /\
        (!u. restricted_permutation r (outgoing_darts E u)
             permutes outgoing_darts E u) /\
        (!u d d'.
             d IN outgoing_darts E u /\
             d' IN outgoing_darts E u
             ==> ?n.
                   ITER n
                    (restricted_permutation r (outgoing_darts E u)) d =
                   d')
        ==> graph_rotation E r`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite outside local_permutation local_transitive" THEN
  REWRITE_TAC[graph_rotation] THEN REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL
     [`graph_darts E:A#A->bool`; `r:(A#A)->A#A`]
     PERMUTES_FINITE_INJECTIVE) THEN
    USE_THEN "finite" (fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REPEAT CONJ_TAC THENL
     [X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "not_dart") THEN
      USE_THEN "outside" (MATCH_MP_TAC o SPEC `d:A#A`) THEN
      USE_THEN "not_dart" ACCEPT_TAC;
      X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "dart") THEN
      SUBGOAL_THEN
       `(d:A#A) IN outgoing_darts E (FST d)`
      (LABEL_TAC "outgoing") THENL
       [ASM_REWRITE_TAC[IN_OUTGOING_DARTS];
        ALL_TAC] THEN
      (fun (asl,_ as goal) ->
        let local =
          SPEC `FST(d:A#A)` (assoc "local_permutation" asl) in
        let image_equivalence =
          MATCH_MP
           (ISPECL
            [`restricted_permutation
               (r:(A#A)->A#A) (outgoing_darts E (FST d))`;
             `outgoing_darts E (FST(d:A#A))`; `d:A#A`]
            PERMUTES_IN_IMAGE)
           local in
        let image =
          EQ_MP (SYM image_equivalence) (assoc "outgoing" asl) in
        let image' =
          REWRITE_RULE
           [restricted_permutation; assoc "outgoing" asl] image in
        let subset =
          REWRITE_RULE[SUBSET]
           (ISPECL
            [`E:(A->bool)->bool`; `FST(d:A#A)`]
            OUTGOING_DARTS_SUBSET) in
        ACCEPT_TAC
         (MATCH_MP (SPEC `(r:(A#A)->A#A) d` subset) image')
         goal);
      MAP_EVERY X_GEN_TAC [`d:A#A`; `d':A#A`] THEN
      INTRO_TAC "dart dart' images" THEN
      SUBGOAL_THEN
       `(d:A#A) IN outgoing_darts E (FST d) /\
        (d':A#A) IN outgoing_darts E (FST d')`
      (CONJUNCTS_THEN2 (LABEL_TAC "outgoing")
        (LABEL_TAC "outgoing'")) THENL
       [ASM_REWRITE_TAC[IN_OUTGOING_DARTS];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(r:(A#A)->A#A) d IN outgoing_darts E (FST d) /\
        r d' IN outgoing_darts E (FST d')`
      (CONJUNCTS_THEN2 (LABEL_TAC "image_outgoing")
        (LABEL_TAC "image_outgoing'")) THENL
        [CONJ_TAC THENL
         [MATCH_MP_TAC(ISPECL
           [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
            `FST(d:A#A)`; `d:A#A`]
           RESTRICTED_PERMUTATION_OUTGOING_IMAGE) THEN
          ASM_REWRITE_TAC[];
          MATCH_MP_TAC(ISPECL
           [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
            `FST(d':A#A)`; `d':A#A`]
           RESTRICTED_PERMUTATION_OUTGOING_IMAGE) THEN
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN `FST(d:A#A) = FST(d':A#A)`
      (LABEL_TAC "same_tail") THENL
       [(fun (asl,_ as goal) ->
          let image_outgoing' =
            REWRITE_RULE
             [GSYM(assoc "images" asl)]
             (assoc "image_outgoing'" asl) in
          MATCH_ACCEPT_TAC
           (MATCH_MP
            (ISPECL
             [`E:(A->bool)->bool`; `FST(d:A#A)`; `FST(d':A#A)`;
              `(r:(A#A)->A#A) d`]
             OUTGOING_DARTS_TAIL_UNIQUE)
            (CONJ (assoc "image_outgoing" asl) image_outgoing'))
           goal);
        ALL_TAC] THEN
      MP_TAC(MATCH_MP
       (ISPECL
        [`restricted_permutation
           (r:(A#A)->A#A) (outgoing_darts E (FST d))`;
         `outgoing_darts E (FST(d:A#A))`]
        PERMUTES_INJECTIVE)
       (SPEC `FST(d:A#A)` (ASSUME
         `!u:A.
            restricted_permutation r (outgoing_darts E u)
            permutes outgoing_darts E u`))) THEN
      DISCH_THEN(MP_TAC o SPECL [`d:A#A`; `d':A#A`]) THEN
      ASM_REWRITE_TAC[restricted_permutation]];
    X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "dart") THEN
    SUBGOAL_THEN
     `(d:A#A) IN outgoing_darts E (FST d)`
    (LABEL_TAC "outgoing") THENL
     [ASM_REWRITE_TAC[IN_OUTGOING_DARTS];
      ALL_TAC] THEN
    MP_TAC(MATCH_MP
     (ISPECL
      [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
       `FST(d:A#A)`; `d:A#A`]
      RESTRICTED_PERMUTATION_OUTGOING_IMAGE)
     (CONJ
      (SPEC `FST(d:A#A)` (ASSUME
        `!u:A.
           restricted_permutation r (outgoing_darts E u)
           permutes outgoing_darts E u`))
      (ASSUME
        `(d:A#A) IN outgoing_darts E (FST d)`))) THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[];
    MAP_EVERY X_GEN_TAC [`d:A#A`; `d':A#A`] THEN
    INTRO_TAC "dart dart' same_tail" THEN
    SUBGOAL_THEN
     `(d:A#A) IN outgoing_darts E (FST d) /\
      (d':A#A) IN outgoing_darts E (FST d)`
    (CONJUNCTS_THEN2 (LABEL_TAC "outgoing")
      (LABEL_TAC "outgoing'")) THENL
     [ASM_REWRITE_TAC[IN_OUTGOING_DARTS];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `?n.
        ITER n
         (restricted_permutation
           (r:(A#A)->A#A) (outgoing_darts E (FST d))) d =
        d'`
    (X_CHOOSE_THEN `n:num` (LABEL_TAC "local_step")) THENL
     [USE_THEN "local_transitive"
       (MATCH_MP_TAC o SPECL [`FST(d:A#A)`; `d:A#A`; `d':A#A`]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `IMAGE (r:(A#A)->A#A) (outgoing_darts E (FST(d:A#A))) =
      outgoing_darts E (FST(d:A#A))`
    (LABEL_TAC "image") THENL
     [MP_TAC(MATCH_MP PERMUTES_IMAGE
       (SPEC `FST(d:A#A)` (ASSUME
         `!u:A.
            restricted_permutation r (outgoing_darts E u)
            permutes outgoing_darts E u`))) THEN
      REWRITE_TAC[RESTRICTED_PERMUTATION_IMAGE];
      ALL_TAC] THEN
    EXISTS_TAC `n:num` THEN
    (fun (asl,_ as goal) ->
      let iter =
        CONJUNCT1
         (SPEC `n:num`
          (MATCH_MP
           (ISPECL
            [`r:(A#A)->A#A`;
             `outgoing_darts E (FST(d:A#A))`; `d:A#A`]
            RESTRICTED_PERMUTATION_ITER)
           (CONJ (assoc "outgoing" asl) (assoc "image" asl)))) in
      ACCEPT_TAC
       (TRANS (SYM iter) (assoc "local_step" asl))
       goal)]);;

let FINITE_SIMPLE_GRAPH_SHARED_EDGE_INTERSECTION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u v:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2
        ==> E1 INTER E2 = {{u,v}}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 vertex_overlap chord1 chord2" THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INTER; IN_SING] THEN
    X_GEN_TAC `e:A->bool` THEN INTRO_TAC "edge1 edge2" THEN
    MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`; `e:A->bool`]
    FINITE_SIMPLE_GRAPH_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@a b. a_vertex1 b_vertex1 distinct edge" THEN
    SUBGOAL_THEN `(a:A,b) IN graph_darts E2`
    (LABEL_TAC "dart2") THENL
     [REWRITE_TAC[IN_GRAPH_DARTS] THEN
      USE_THEN "edge" (fun th -> REWRITE_TAC[GSYM th]) THEN
      USE_THEN "edge2" ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V2:A->bool`; `E2:(A->bool)->bool`; `a:A`; `b:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "a_vertex2 b_vertex2" THEN
    SUBGOAL_THEN `(a:A) IN {u,v} /\ (b:A) IN {u,v}`
    (CONJUNCTS_THEN2 (LABEL_TAC "a_shared")
      (LABEL_TAC "b_shared")) THENL
     [USE_THEN "vertex_overlap" (fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[IN_INTER];
      ALL_TAC] THEN
    USE_THEN "edge" SUBST1_TAC THEN ASM SET_TAC[];
    REWRITE_TAC[SUBSET; IN_SING; IN_INTER] THEN
    X_GEN_TAC `e:A->bool` THEN
    DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]]);;

let FINITE_SIMPLE_GRAPH_SHARED_DARTS = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u v:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2
        ==> graph_darts E1 INTER graph_darts E2 =
            {(u,v),(v,u)}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 vertex_overlap chord1 chord2" THEN
  SUBGOAL_THEN `~((u:A) = v)` (LABEL_TAC "distinct") THENL
   [MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[GSYM GRAPH_DARTS_INTER] THEN
  MP_TAC(ISPECL
   [`V1:A->bool`; `V2:A->bool`;
    `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
   FINITE_SIMPLE_GRAPH_SHARED_EDGE_INTERSECTION) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC GRAPH_DARTS_SINGLE_EDGE THEN
  USE_THEN "distinct" ACCEPT_TAC);;

let FINITE_SIMPLE_GRAPH_SHARED_OUTGOING_LEFT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u v:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2
        ==> outgoing_darts E1 u INTER outgoing_darts E2 u =
            {(u,v)}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 vertex_overlap chord1 chord2" THEN
  SUBGOAL_THEN `~((u:A) = v)` (LABEL_TAC "distinct") THENL
   [MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V1:A->bool`; `V2:A->bool`;
    `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
   FINITE_SIMPLE_GRAPH_SHARED_DARTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "dart_overlap") THEN
  REWRITE_TAC[EXTENSION; IN_INTER; IN_OUTGOING_DARTS; IN_SING] THEN
  X_GEN_TAC `d:A#A` THEN EQ_TAC THENL
   [INTRO_TAC "(dart1 tail1) dart2 tail2" THEN
    SUBGOAL_THEN
     `(d:A#A) IN graph_darts E1 INTER graph_darts E2`
    (LABEL_TAC "shared") THENL
     [ASM_REWRITE_TAC[IN_INTER];
      ALL_TAC] THEN
    USE_THEN "shared" MP_TAC THEN
    USE_THEN "dart_overlap"
     (fun th -> REWRITE_TAC[th; IN_INSERT; IN_SING]) THEN
    DISCH_THEN(DISJ_CASES_THEN2
      (LABEL_TAC "forward") (LABEL_TAC "reverse")) THENL
     [USE_THEN "forward" ACCEPT_TAC;
      USE_THEN "reverse" SUBST_ALL_TAC THEN
      USE_THEN "tail1" MP_TAC THEN
      REWRITE_TAC[FST] THEN DISCH_THEN(LABEL_TAC "equal") THEN
      USE_THEN "distinct" (fun nth ->
        USE_THEN "equal" (fun eth ->
          CONTR_TAC(MP (NOT_ELIM nth) (SYM eth))))];
    DISCH_THEN SUBST1_TAC THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS; FST]]);;

let FINITE_SIMPLE_GRAPH_SHARED_OUTGOING_RIGHT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u v:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2
        ==> outgoing_darts E1 v INTER outgoing_darts E2 v =
            {(v,u)}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 vertex_overlap chord1 chord2" THEN
  SUBGOAL_THEN `~((u:A) = v)` (LABEL_TAC "distinct") THENL
   [MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V1:A->bool`; `V2:A->bool`;
    `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
   FINITE_SIMPLE_GRAPH_SHARED_DARTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "dart_overlap") THEN
  REWRITE_TAC[EXTENSION; IN_INTER; IN_OUTGOING_DARTS; IN_SING] THEN
  X_GEN_TAC `d:A#A` THEN EQ_TAC THENL
   [INTRO_TAC "(dart1 tail1) dart2 tail2" THEN
    SUBGOAL_THEN
     `(d:A#A) IN graph_darts E1 INTER graph_darts E2`
    (LABEL_TAC "shared") THENL
     [ASM_REWRITE_TAC[IN_INTER];
      ALL_TAC] THEN
    USE_THEN "shared" MP_TAC THEN
    USE_THEN "dart_overlap"
     (fun th -> REWRITE_TAC[th; IN_INSERT; IN_SING]) THEN
    DISCH_THEN(DISJ_CASES_THEN2
      (LABEL_TAC "reverse") (LABEL_TAC "forward")) THENL
     [USE_THEN "reverse" SUBST_ALL_TAC THEN
      USE_THEN "tail1" MP_TAC THEN
      REWRITE_TAC[FST] THEN DISCH_THEN(LABEL_TAC "equal") THEN
      USE_THEN "distinct" (fun nth ->
        USE_THEN "equal" (fun eth ->
          CONTR_TAC(MP (NOT_ELIM nth) eth)));
      USE_THEN "forward" ACCEPT_TAC];
    DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[IN_GRAPH_DARTS; FST] THEN
    ONCE_REWRITE_TAC[SET_RULE `{v:A,u} = {u,v}`] THEN
    ASM_REWRITE_TAC[]]);;

let FINITE_SIMPLE_GRAPH_SHARED_EDGE_DISTINCT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u v:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2
        ==> ~(u = v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph1 graph2 overlap chord1 chord2" THEN
  MP_TAC(ISPECL
   [`V1:A->bool`; `E1:(A->bool)->bool`; `u:A`; `v:A`]
   FINITE_SIMPLE_GRAPH_DART) THEN
  ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[]);;

let graph_split_local_rotation = new_definition
 `graph_split_local_rotation
    (V1:A->bool) (E1:(A->bool)->bool) (E2:(A->bool)->bool)
    (r1:(A#A)->A#A) (r2:(A#A)->A#A) u v x =
      if x = u then
        permutation_cycle_splice
          (restricted_permutation r1 (outgoing_darts E1 u))
          (outgoing_darts E1 u)
          (restricted_permutation r2 (outgoing_darts E2 u))
          (u,v)
      else if x = v then
        permutation_cycle_splice
          (restricted_permutation r2 (outgoing_darts E2 v))
          (outgoing_darts E2 v)
          (restricted_permutation r1 (outgoing_darts E1 v))
          (v,u)
      else if x IN V1 then
        restricted_permutation r1 (outgoing_darts E1 x)
      else
        restricted_permutation r2 (outgoing_darts E2 x)`;;

let graph_split_rotation = new_definition
 `graph_split_rotation
    (V1:A->bool) (E1:(A->bool)->bool) (E2:(A->bool)->bool)
    (r1:(A#A)->A#A) (r2:(A#A)->A#A) u v d =
      if d IN graph_darts (E1 UNION E2) then
        graph_split_local_rotation V1 E1 E2 r1 r2 u v (FST d) d
      else d`;;

let GRAPH_SPLIT_LOCAL_ROTATION_PERMUTES = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u v:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2 /\
        ~(restricted_permutation r2 (outgoing_darts E2 u) (u,v) =
          (u,v)) /\
        ~(restricted_permutation r1 (outgoing_darts E1 v) (v,u) =
          (v,u))
        ==> !x:A.
              graph_split_local_rotation V1 E1 E2 r1 r2 u v x
              permutes outgoing_darts (E1 UNION E2) x`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph1 graph2 rotation1 rotation2 overlap chord1 chord2
    u_nonfixed v_nonfixed" THEN
  (fun (asl,_ as goal) ->
    LABEL_TAC "distinct"
     (MATCH_MP
      (ISPECL
       [`V1:A->bool`; `V2:A->bool`;
        `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_SHARED_EDGE_DISTINCT)
     (end_itlist CONJ
       (map (fun name -> assoc name asl)
        ["graph1"; "graph2"; "overlap"; "chord1"; "chord2"])))
     goal) THEN
  X_GEN_TAC `x:A` THEN
  REWRITE_TAC[graph_split_local_rotation; OUTGOING_DARTS_UNION] THEN
  ASM_CASES_TAC `(x:A) = u` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN ASM_REWRITE_TAC[] THEN
    (fun (asl,_ as goal) ->
      let finite1 =
        MATCH_MP
         (ISPECL [`V1:A->bool`; `E1:(A->bool)->bool`; `u:A`]
          FINITE_OUTGOING_DARTS)
         (assoc "graph1" asl)
      and finite2 =
        MATCH_MP
         (ISPECL [`V2:A->bool`; `E2:(A->bool)->bool`; `u:A`]
          FINITE_OUTGOING_DARTS)
         (assoc "graph2" asl)
      and permutation1 =
        MATCH_MP
         (ISPECL
          [`V1:A->bool`; `E1:(A->bool)->bool`;
           `r1:(A#A)->A#A`; `u:A`]
          GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES)
         (CONJ (assoc "graph1" asl) (assoc "rotation1" asl))
      and permutation2 =
        MATCH_MP
         (ISPECL
          [`V2:A->bool`; `E2:(A->bool)->bool`;
           `r2:(A#A)->A#A`; `u:A`]
          GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES)
         (CONJ (assoc "graph2" asl) (assoc "rotation2" asl))
      and shared =
        MATCH_MP
         (ISPECL
          [`V1:A->bool`; `V2:A->bool`;
           `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
           `u:A`; `v:A`]
          FINITE_SIMPLE_GRAPH_SHARED_OUTGOING_LEFT)
         (end_itlist CONJ
          (map (fun name -> assoc name asl)
           ["graph1"; "graph2"; "overlap"; "chord1"; "chord2"]))
      and member1 =
        REWRITE_RULE[GSYM IN_OUTGOING_DARTS_PAIR]
         (assoc "chord1" asl)
      and member2 =
         REWRITE_RULE[GSYM IN_OUTGOING_DARTS_PAIR]
         (assoc "chord2" asl) in
      let rule =
        ISPECL
         [`restricted_permutation
            (r1:(A#A)->A#A) (outgoing_darts E1 u)`;
          `restricted_permutation
            (r2:(A#A)->A#A) (outgoing_darts E2 u)`;
          `outgoing_darts E1 u:A#A->bool`;
          `outgoing_darts E2 u:A#A->bool`; `(u:A,v:A)`]
         PERMUTATION_CYCLE_SPLICE_PERMUTES
      and assumptions =
        end_itlist CONJ
         [finite1; finite2; permutation1; permutation2; shared;
          member1; member2; assoc "u_nonfixed" asl] in
      MATCH_ACCEPT_TAC
       (MATCH_MP rule assumptions)
       goal);
    ALL_TAC] THEN
  ASM_CASES_TAC `(x:A) = v` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN ASM_REWRITE_TAC[] THEN
    (fun (asl,_ as goal) ->
      let finite2 =
        MATCH_MP
         (ISPECL [`V2:A->bool`; `E2:(A->bool)->bool`; `v:A`]
          FINITE_OUTGOING_DARTS)
         (assoc "graph2" asl)
      and finite1 =
        MATCH_MP
         (ISPECL [`V1:A->bool`; `E1:(A->bool)->bool`; `v:A`]
          FINITE_OUTGOING_DARTS)
         (assoc "graph1" asl)
      and permutation2 =
        MATCH_MP
         (ISPECL
          [`V2:A->bool`; `E2:(A->bool)->bool`;
           `r2:(A#A)->A#A`; `v:A`]
          GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES)
         (CONJ (assoc "graph2" asl) (assoc "rotation2" asl))
      and permutation1 =
        MATCH_MP
         (ISPECL
          [`V1:A->bool`; `E1:(A->bool)->bool`;
           `r1:(A#A)->A#A`; `v:A`]
          GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES)
         (CONJ (assoc "graph1" asl) (assoc "rotation1" asl))
      and shared =
        ONCE_REWRITE_RULE[INTER_COMM]
         (MATCH_MP
          (ISPECL
           [`V1:A->bool`; `V2:A->bool`;
            `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
            `u:A`; `v:A`]
           FINITE_SIMPLE_GRAPH_SHARED_OUTGOING_RIGHT)
          (end_itlist CONJ
           (map (fun name -> assoc name asl)
            ["graph1"; "graph2"; "overlap"; "chord1"; "chord2"])))
      in
      let member2 =
        EQ_MP
         (SYM(REWRITE_CONV
          [IN_OUTGOING_DARTS_PAIR;
           SET_RULE `{v:A,u} = {u,v}`]
          `((v:A),(u:A)) IN outgoing_darts E2 v`))
         (assoc "chord2" asl)
      and member1 =
        EQ_MP
         (SYM(REWRITE_CONV
          [IN_OUTGOING_DARTS_PAIR;
           SET_RULE `{v:A,u} = {u,v}`]
          `((v:A),(u:A)) IN outgoing_darts E1 v`))
         (assoc "chord1" asl) in
      let rule =
        ISPECL
         [`restricted_permutation
            (r2:(A#A)->A#A) (outgoing_darts E2 v)`;
          `restricted_permutation
            (r1:(A#A)->A#A) (outgoing_darts E1 v)`;
          `outgoing_darts E2 v:A#A->bool`;
          `outgoing_darts E1 v:A#A->bool`; `(v:A,u:A)`]
         PERMUTATION_CYCLE_SPLICE_PERMUTES
      and assumptions =
        end_itlist CONJ
         [finite2; finite1; permutation2; permutation1; shared;
          member2; member1; assoc "v_nonfixed" asl] in
      MATCH_ACCEPT_TAC
       (ONCE_REWRITE_RULE[UNION_COMM]
        (MATCH_MP rule assumptions))
       goal);
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN ASM_CASES_TAC `(x:A) IN V1` THENL
   [SUBGOAL_THEN `~((x:A) IN V2)` (LABEL_TAC "outside2") THENL
     [USE_THEN "overlap" MP_TAC THEN ASM SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `outgoing_darts E2 (x:A) = {}`
    (LABEL_TAC "empty2") THENL
     [MATCH_MP_TAC(ISPECL
       [`V2:A->bool`; `E2:(A->bool)->bool`; `x:A`]
       OUTGOING_DARTS_EMPTY_OUTSIDE_VERTICES) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[UNION_EMPTY] THEN
      MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`;
        `r1:(A#A)->A#A`; `x:A`]
       GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES) THEN
      ASM_REWRITE_TAC[]];
    SUBGOAL_THEN `outgoing_darts E1 (x:A) = {}`
    (LABEL_TAC "empty1") THENL
     [MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`; `x:A`]
       OUTGOING_DARTS_EMPTY_OUTSIDE_VERTICES) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC
       [SET_RULE `{} UNION (s:(A#A)->bool) = s`] THEN
      MATCH_MP_TAC(ISPECL
       [`V2:A->bool`; `E2:(A->bool)->bool`;
        `r2:(A#A)->A#A`; `x:A`]
       GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES) THEN
      ASM_REWRITE_TAC[]]]);;

let GRAPH_SPLIT_LOCAL_ROTATION_TRANSITIVE = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u v:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2 /\
        ~(restricted_permutation r2 (outgoing_darts E2 u) (u,v) =
          (u,v)) /\
        ~(restricted_permutation r1 (outgoing_darts E1 v) (v,u) =
          (v,u))
        ==> !x d d':A#A.
              d IN outgoing_darts (E1 UNION E2) x /\
              d' IN outgoing_darts (E1 UNION E2) x
              ==> ?n.
                    ITER n
                     (graph_split_local_rotation
                       V1 E1 E2 r1 r2 u v x) d =
                    d'`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph1 graph2 rotation1 rotation2 overlap chord1 chord2
    u_nonfixed v_nonfixed" THEN
  (fun (asl,_ as goal) ->
    LABEL_TAC "distinct"
     (MATCH_MP
      (ISPECL
       [`V1:A->bool`; `V2:A->bool`;
        `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_SHARED_EDGE_DISTINCT)
      (end_itlist CONJ
       (map (fun name -> assoc name asl)
        ["graph1"; "graph2"; "overlap"; "chord1"; "chord2"])))
     goal) THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `d:A#A`; `d':A#A`] THEN
  REWRITE_TAC[graph_split_local_rotation; OUTGOING_DARTS_UNION] THEN
  ASM_CASES_TAC `(x:A) = u` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN ASM_REWRITE_TAC[] THEN
    (fun (asl,_ as goal) ->
      let finite1 =
        MATCH_MP
         (ISPECL [`V1:A->bool`; `E1:(A->bool)->bool`; `u:A`]
          FINITE_OUTGOING_DARTS)
         (assoc "graph1" asl)
      and finite2 =
        MATCH_MP
         (ISPECL [`V2:A->bool`; `E2:(A->bool)->bool`; `u:A`]
          FINITE_OUTGOING_DARTS)
         (assoc "graph2" asl)
      and permutation1 =
        MATCH_MP
         (ISPECL
          [`V1:A->bool`; `E1:(A->bool)->bool`;
           `r1:(A#A)->A#A`; `u:A`]
          GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES)
         (CONJ (assoc "graph1" asl) (assoc "rotation1" asl))
      and permutation2 =
        MATCH_MP
         (ISPECL
          [`V2:A->bool`; `E2:(A->bool)->bool`;
           `r2:(A#A)->A#A`; `u:A`]
          GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES)
         (CONJ (assoc "graph2" asl) (assoc "rotation2" asl))
      and shared =
        MATCH_MP
         (ISPECL
          [`V1:A->bool`; `V2:A->bool`;
           `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
           `u:A`; `v:A`]
          FINITE_SIMPLE_GRAPH_SHARED_OUTGOING_LEFT)
         (end_itlist CONJ
          (map (fun name -> assoc name asl)
           ["graph1"; "graph2"; "overlap"; "chord1"; "chord2"]))
      and member1 =
        REWRITE_RULE[GSYM IN_OUTGOING_DARTS_PAIR]
         (assoc "chord1" asl)
      and member2 =
        REWRITE_RULE[GSYM IN_OUTGOING_DARTS_PAIR]
         (assoc "chord2" asl)
      and transitive1 =
        MATCH_MP
         (ISPECL
          [`E1:(A->bool)->bool`; `r1:(A#A)->A#A`; `u:A`]
          GRAPH_ROTATION_RESTRICTED_OUTGOING_TRANSITIVE)
         (assoc "rotation1" asl)
      and transitive2 =
        MATCH_MP
         (ISPECL
          [`E2:(A->bool)->bool`; `r2:(A#A)->A#A`; `u:A`]
          GRAPH_ROTATION_RESTRICTED_OUTGOING_TRANSITIVE)
         (assoc "rotation2" asl) in
      let result =
        MATCH_MP
        (ISPECL
         [`restricted_permutation
            (r1:(A#A)->A#A) (outgoing_darts E1 u)`;
          `restricted_permutation
            (r2:(A#A)->A#A) (outgoing_darts E2 u)`;
          `outgoing_darts E1 u:A#A->bool`;
          `outgoing_darts E2 u:A#A->bool`; `(u:A,v:A)`]
         PERMUTATION_CYCLE_SPLICE_TRANSITIVE)
        (end_itlist CONJ
         [finite1; finite2; permutation1; permutation2; shared;
          member1; member2; assoc "u_nonfixed" asl;
          transitive1; transitive2]) in
      MATCH_ACCEPT_TAC
       (SPECL [`d:A#A`; `d':A#A`] result)
       goal);
    ALL_TAC] THEN
  ASM_CASES_TAC `(x:A) = v` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN ASM_REWRITE_TAC[] THEN
    (fun (asl,_ as goal) ->
      let finite2 =
        MATCH_MP
         (ISPECL [`V2:A->bool`; `E2:(A->bool)->bool`; `v:A`]
          FINITE_OUTGOING_DARTS)
         (assoc "graph2" asl)
      and finite1 =
        MATCH_MP
         (ISPECL [`V1:A->bool`; `E1:(A->bool)->bool`; `v:A`]
          FINITE_OUTGOING_DARTS)
         (assoc "graph1" asl)
      and permutation2 =
        MATCH_MP
         (ISPECL
          [`V2:A->bool`; `E2:(A->bool)->bool`;
           `r2:(A#A)->A#A`; `v:A`]
          GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES)
         (CONJ (assoc "graph2" asl) (assoc "rotation2" asl))
      and permutation1 =
        MATCH_MP
         (ISPECL
          [`V1:A->bool`; `E1:(A->bool)->bool`;
           `r1:(A#A)->A#A`; `v:A`]
          GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES)
         (CONJ (assoc "graph1" asl) (assoc "rotation1" asl))
      and shared =
        ONCE_REWRITE_RULE[INTER_COMM]
         (MATCH_MP
          (ISPECL
           [`V1:A->bool`; `V2:A->bool`;
            `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
            `u:A`; `v:A`]
           FINITE_SIMPLE_GRAPH_SHARED_OUTGOING_RIGHT)
          (end_itlist CONJ
           (map (fun name -> assoc name asl)
            ["graph1"; "graph2"; "overlap"; "chord1"; "chord2"])))
      and transitive2 =
        MATCH_MP
         (ISPECL
          [`E2:(A->bool)->bool`; `r2:(A#A)->A#A`; `v:A`]
          GRAPH_ROTATION_RESTRICTED_OUTGOING_TRANSITIVE)
         (assoc "rotation2" asl)
      and transitive1 =
        MATCH_MP
         (ISPECL
          [`E1:(A->bool)->bool`; `r1:(A#A)->A#A`; `v:A`]
          GRAPH_ROTATION_RESTRICTED_OUTGOING_TRANSITIVE)
         (assoc "rotation1" asl) in
      let member2 =
        EQ_MP
         (SYM(REWRITE_CONV
          [IN_OUTGOING_DARTS_PAIR;
           SET_RULE `{v:A,u} = {u,v}`]
          `((v:A),(u:A)) IN outgoing_darts E2 v`))
         (assoc "chord2" asl)
      and member1 =
        EQ_MP
         (SYM(REWRITE_CONV
          [IN_OUTGOING_DARTS_PAIR;
           SET_RULE `{v:A,u} = {u,v}`]
          `((v:A),(u:A)) IN outgoing_darts E1 v`))
         (assoc "chord1" asl) in
      let result =
        ONCE_REWRITE_RULE[UNION_COMM]
         (MATCH_MP
         (ISPECL
          [`restricted_permutation
             (r2:(A#A)->A#A) (outgoing_darts E2 v)`;
           `restricted_permutation
             (r1:(A#A)->A#A) (outgoing_darts E1 v)`;
           `outgoing_darts E2 v:A#A->bool`;
           `outgoing_darts E1 v:A#A->bool`; `(v:A,u:A)`]
          PERMUTATION_CYCLE_SPLICE_TRANSITIVE)
         (end_itlist CONJ
          [finite2; finite1; permutation2; permutation1; shared;
           member2; member1; assoc "v_nonfixed" asl;
           transitive2; transitive1])) in
      MATCH_ACCEPT_TAC
       (SPECL [`d:A#A`; `d':A#A`] result)
       goal);
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN ASM_CASES_TAC `(x:A) IN V1` THENL
   [SUBGOAL_THEN `~((x:A) IN V2)` (LABEL_TAC "outside2") THENL
     [USE_THEN "overlap" MP_TAC THEN ASM SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `outgoing_darts E2 (x:A) = {}`
    (LABEL_TAC "empty2") THENL
     [MATCH_MP_TAC(ISPECL
       [`V2:A->bool`; `E2:(A->bool)->bool`; `x:A`]
       OUTGOING_DARTS_EMPTY_OUTSIDE_VERTICES) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[UNION_EMPTY] THEN
      (fun (asl,_ as goal) ->
        let transitive =
          MATCH_MP
           (ISPECL
            [`E1:(A->bool)->bool`; `r1:(A#A)->A#A`; `x:A`]
            GRAPH_ROTATION_RESTRICTED_OUTGOING_TRANSITIVE)
           (assoc "rotation1" asl) in
        MATCH_ACCEPT_TAC
         (SPECL [`d:A#A`; `d':A#A`] transitive)
         goal)];
    SUBGOAL_THEN `outgoing_darts E1 (x:A) = {}`
    (LABEL_TAC "empty1") THENL
     [MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`; `x:A`]
       OUTGOING_DARTS_EMPTY_OUTSIDE_VERTICES) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC
       [SET_RULE `{} UNION (s:(A#A)->bool) = s`] THEN
      (fun (asl,_ as goal) ->
        let transitive =
          MATCH_MP
           (ISPECL
            [`E2:(A->bool)->bool`; `r2:(A#A)->A#A`; `x:A`]
            GRAPH_ROTATION_RESTRICTED_OUTGOING_TRANSITIVE)
           (assoc "rotation2" asl) in
        MATCH_ACCEPT_TAC
         (SPECL [`d:A#A`; `d':A#A`] transitive)
         goal)]]);;

let RESTRICTED_GRAPH_SPLIT_ROTATION = prove
 (`!V1:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u v x:A.
        graph_split_local_rotation V1 E1 E2 r1 r2 u v x
          permutes outgoing_darts (E1 UNION E2) x
        ==> restricted_permutation
             (graph_split_rotation V1 E1 E2 r1 r2 u v)
             (outgoing_darts (E1 UNION E2) x) =
            graph_split_local_rotation V1 E1 E2 r1 r2 u v x`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "permutation") THEN
  REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `d:A#A` THEN
  REWRITE_TAC[restricted_permutation] THEN
  ASM_CASES_TAC `(d:A#A) IN outgoing_darts (E1 UNION E2) x` THENL
   [FIRST_X_ASSUM MP_TAC THEN REWRITE_TAC[IN_OUTGOING_DARTS] THEN
    INTRO_TAC "dart tail" THEN
    ASM_REWRITE_TAC[graph_split_rotation];
    ASM_REWRITE_TAC[] THEN
    USE_THEN "permutation" MP_TAC THEN
    REWRITE_TAC[permutes] THEN
    DISCH_THEN(CONJUNCTS_THEN2
      (MP_TAC o SPEC `d:A#A`) (K ALL_TAC)) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(ACCEPT_TAC o SYM)]);;

let GRAPH_SPLIT_ROTATION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u v:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2 /\
        ~(restricted_permutation r2 (outgoing_darts E2 u) (u,v) =
          (u,v)) /\
        ~(restricted_permutation r1 (outgoing_darts E1 v) (v,u) =
          (v,u))
        ==> graph_rotation
             (E1 UNION E2)
             (graph_split_rotation V1 E1 E2 r1 r2 u v)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph1 graph2 rotation1 rotation2 overlap chord1 chord2
    u_nonfixed v_nonfixed" THEN
  SUBGOAL_THEN
   `!x:A.
      graph_split_local_rotation V1 E1 E2 r1 r2 u v x
        permutes outgoing_darts (E1 UNION E2) x`
  (LABEL_TAC "local_permutation") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`; `u:A`; `v:A`]
     GRAPH_SPLIT_LOCAL_ROTATION_PERMUTES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x d d':A#A.
      d IN outgoing_darts (E1 UNION E2) x /\
      d' IN outgoing_darts (E1 UNION E2) x
      ==> ?n.
            ITER n
             (graph_split_local_rotation
               V1 E1 E2 r1 r2 u v x) d =
            d'`
  (LABEL_TAC "local_transitive") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`; `u:A`; `v:A`]
     GRAPH_SPLIT_LOCAL_ROTATION_TRANSITIVE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`E1 UNION E2:(A->bool)->bool`;
    `graph_split_rotation
      (V1:A->bool) E1 E2 r1 r2 u v:(A#A)->A#A`]
   GRAPH_ROTATION_OF_RESTRICTED_OUTGOING) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V1 UNION V2:A->bool`; `E1 UNION E2:(A->bool)->bool`]
     FINITE_GRAPH_DARTS) THEN
    MATCH_MP_TAC FINITE_SIMPLE_GRAPH_UNION THEN ASM_REWRITE_TAC[];
    SIMP_TAC[graph_split_rotation];
    X_GEN_TAC `x:A` THEN
    MP_TAC(MATCH_MP
     (ISPECL
      [`V1:A->bool`; `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
       `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
       `u:A`; `v:A`; `x:A`]
      RESTRICTED_GRAPH_SPLIT_ROTATION)
     (SPEC `x:A` (ASSUME
       `!x:A.
          graph_split_local_rotation V1 E1 E2 r1 r2 u v x
            permutes outgoing_darts (E1 UNION E2) x`))) THEN
    DISCH_THEN SUBST1_TAC THEN
    USE_THEN "local_permutation" (ACCEPT_TAC o SPEC `x:A`);
    MAP_EVERY X_GEN_TAC [`x:A`; `d:A#A`; `d':A#A`] THEN
    DISCH_THEN(LABEL_TAC "members") THEN
    MP_TAC(MATCH_MP
     (ISPECL
      [`V1:A->bool`; `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
       `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
       `u:A`; `v:A`; `x:A`]
      RESTRICTED_GRAPH_SPLIT_ROTATION)
     (SPEC `x:A` (ASSUME
       `!x:A.
          graph_split_local_rotation V1 E1 E2 r1 r2 u v x
            permutes outgoing_darts (E1 UNION E2) x`))) THEN
    DISCH_THEN SUBST1_TAC THEN
    USE_THEN "local_transitive"
     (MATCH_MP_TAC o SPECL [`x:A`; `d:A#A`; `d':A#A`]) THEN
    USE_THEN "members" ACCEPT_TAC]);;

let CYCLIC_FACE_SUCCESSOR_NOT_REVERSE = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !q:num->A. !n i.
        3 <= n /\
        INJ q (cyclic_indices n) (:A) /\
        cyclic_face_successors E r q n /\
        i < n
        ==> ~(graph_face_successor E r (cyclic_dart q n i) =
              reverse_dart(cyclic_dart q n i))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "large injective successors index" THEN
  ABBREV_TAC `j = (i + 1) MOD n` THEN
  SUBGOAL_THEN `(j:num) < n` (LABEL_TAC "next_index") THENL
   [EXPAND_TAC "j" THEN ASM_SIMP_TAC[MOD_LT] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (cyclic_dart (q:num->A) n i) =
    cyclic_dart q n j`
  (LABEL_TAC "successor") THENL
   [USE_THEN "successors" MP_TAC THEN
    REWRITE_TAC[cyclic_face_successors] THEN
    DISCH_THEN(MP_TAC o SPEC `i:num`) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "reverse") THEN
  SUBGOAL_THEN
   `(q:num->A) ((j + 1) MOD n) = q i`
  (LABEL_TAC "same_vertex") THENL
   [USE_THEN "successor" (fun sth ->
      USE_THEN "reverse" (fun rth ->
       MP_TAC(AP_TERM `SND:A#A->A` (TRANS (SYM sth) rth)))) THEN
    REWRITE_TAC[cyclic_dart; SND; SND_REVERSE_DART; FST];
    ALL_TAC] THEN
  SUBGOAL_THEN `((j + 1) MOD n) = i`
  (LABEL_TAC "returns") THENL
   [USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    DISCH_THEN(MATCH_MP_TAC o SPECL [`(j + 1) MOD n`; `i:num`]) THEN
    ASM_REWRITE_TAC[] THEN
    ASM_SIMP_TAC[MOD_LT] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`n:num`; `i:num`; `j:num`]
    CYCLIC_SUCCESSOR_NO_TWO_CYCLE) THEN
  ASM_REWRITE_TAC[] THEN EXPAND_TAC "j" THEN REFL_TAC);;

let BOUNDARY_EULER_ROTATION_REVERSE_DART_NONFIXED = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n r i.
        3 <= n /\
        INJ q (cyclic_indices n) (:A) /\
        cyclic_edges q n SUBSET E /\
        boundary_euler_rotation V E q n r /\
        i < n
        ==> ~(restricted_permutation
               r (outgoing_darts E (SND(cyclic_dart q n i)))
               (reverse_dart(cyclic_dart q n i)) =
              reverse_dart(cyclic_dart q n i))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "large injective edges boundary index" THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n i IN graph_darts E`
  (LABEL_TAC "dart") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DART THEN
    ASM_REWRITE_TAC[simple_graph_cycle];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(cyclic_dart (q:num->A) n i) IN
    outgoing_darts E (SND(cyclic_dart q n i))`
  (LABEL_TAC "reverse_outgoing") THENL
   [REWRITE_TAC[IN_OUTGOING_DARTS] THEN
    ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE; FST_REVERSE_DART];
    ALL_TAC] THEN
  SUBGOAL_THEN `cyclic_face_successors E r (q:num->A) n`
  (LABEL_TAC "successors") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `r:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_IMP_CYCLIC_FACE_SUCCESSORS) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(graph_face_successor E r (cyclic_dart (q:num->A) n i) =
      reverse_dart(cyclic_dart q n i))`
  (LABEL_TAC "not_reverse") THENL
   [MATCH_MP_TAC CYCLIC_FACE_SUCCESSOR_NOT_REVERSE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "fixed") THEN
  (fun (asl,_ as goal) ->
    LABEL_TAC "rotation_fixed"
     (REWRITE_RULE
       [restricted_permutation; assoc "reverse_outgoing" asl]
       (assoc "fixed" asl))
     goal) THEN
  USE_THEN "not_reverse" (MATCH_MP_TAC o NOT_ELIM) THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `cyclic_dart (q:num->A) n i`]
   GRAPH_FACE_SUCCESSOR_IN) THEN
  ASM_REWRITE_TAC[]);;

let graph_split_face_permutation = new_definition
 `graph_split_face_permutation
    (E1:(A->bool)->bool) (E2:(A->bool)->bool)
    (r1:(A#A)->A#A) (r2:(A#A)->A#A) (u:A) (v:A) =
    swap(graph_face_successor E1 r1 (u,v),
         graph_face_successor E2 r2 (v,u)) o
    disjoint_permutation_union
      (permutation_delete
        (graph_face_successor E1 r1) (u,v))
      (graph_darts E1 DELETE (u,v))
      (permutation_delete
        (graph_face_successor E2 r2) (v,u))`;;

let GRAPH_SPLIT_DART_PARTITION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u v:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2
        ==> DISJOINT
             (graph_darts E1 DELETE (u,v))
             (graph_darts E2 DELETE (v,u)) /\
            (graph_darts E1 DELETE (u,v)) UNION
            (graph_darts E2 DELETE (v,u)) =
            graph_darts (E1 UNION E2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 overlap chord1 chord2" THEN
  SUBGOAL_THEN
   `graph_darts E1 INTER graph_darts E2 =
    {((u:A),(v:A)),((v:A),(u:A))}`
  (LABEL_TAC "shared") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_SHARED_DARTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) = v)` (LABEL_TAC "distinct") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_SHARED_EDGE_DISTINCT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((u:A),(v:A)) IN graph_darts E1 /\
    (v,u) IN graph_darts E1 /\
    (u,v) IN graph_darts E2 /\
    (v,u) IN graph_darts E2`
  STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[IN_GRAPH_DARTS;
                    SET_RULE `{v:A,u} = {u,v}`];
    CONJ_TAC THENL
     [REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_DELETE;
                  NOT_IN_EMPTY] THEN
      X_GEN_TAC `d:A#A` THEN
      DISCH_THEN(CONJUNCTS_THEN2
       (CONJUNCTS_THEN2 (LABEL_TAC "dart1") (LABEL_TAC "not_forward"))
       (CONJUNCTS_THEN2 (LABEL_TAC "dart2") (LABEL_TAC "not_reverse"))) THEN
      SUBGOAL_THEN
       `(d:A#A) IN graph_darts E1 INTER graph_darts E2`
      (LABEL_TAC "dart_shared") THENL
       [ASM_REWRITE_TAC[IN_INTER];
        USE_THEN "dart_shared" MP_TAC THEN
        USE_THEN "shared" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[IN_INSERT; IN_SING] THEN
        DISCH_THEN(DISJ_CASES_THEN2
         (fun th ->
           USE_THEN "not_forward" (fun nth ->
             CONTR_TAC(MP (NOT_ELIM nth) th)))
         (fun th ->
           USE_THEN "not_reverse" (fun nth ->
             CONTR_TAC(MP (NOT_ELIM nth) th))))];
      REWRITE_TAC[GRAPH_DARTS_UNION; EXTENSION; IN_UNION; IN_DELETE] THEN
      X_GEN_TAC `d:A#A` THEN EQ_TAC THENL
       [MESON_TAC[];
        DISCH_THEN(DISJ_CASES_THEN2
          (LABEL_TAC "dart1") (LABEL_TAC "dart2")) THENL
         [ASM_CASES_TAC `(d:A#A) = (u,v)` THENL
           [DISJ2_TAC THEN ASM_REWRITE_TAC[PAIR_EQ];
            DISJ1_TAC THEN ASM_REWRITE_TAC[]];
          ASM_CASES_TAC `(d:A#A) = (v,u)` THENL
           [DISJ1_TAC THEN ASM_REWRITE_TAC[PAIR_EQ];
            DISJ2_TAC THEN ASM_REWRITE_TAC[]]]]]]);;

let GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT = prove
 (`!V E r d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        d IN graph_darts E
        ==> ~(graph_face_successor E r d = d)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation dart" THEN
  DISCH_THEN(LABEL_TAC "fixed") THEN
  SUBGOAL_THEN `FST(d:A#A) = SND d` (LABEL_TAC "loop") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_FACE_SUCCESSOR_TAIL) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `FST(d:A#A)`; `SND(d:A#A)`]
   FINITE_SIMPLE_GRAPH_DART) THEN
  ASM_REWRITE_TAC[PAIR]);;

let GRAPH_SPLIT_FACE_PERMUTATION_PERMUTES = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u v:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2
        ==> graph_split_face_permutation E1 E2 r1 r2 u v
            permutes graph_darts (E1 UNION E2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 rotation1 rotation2 overlap chord1 chord2" THEN
  ABBREV_TAC `x:A#A = (u:A,v:A)` THEN
  ABBREV_TAC `y:A#A = (v:A,u:A)` THEN
  ABBREV_TAC
   `f1:(A#A)->A#A =
      graph_face_successor (E1:(A->bool)->bool) (r1:(A#A)->A#A)` THEN
  ABBREV_TAC
   `f2:(A#A)->A#A =
      graph_face_successor (E2:(A->bool)->bool) (r2:(A#A)->A#A)` THEN
  ABBREV_TAC `S1:(A#A)->bool = graph_darts E1 DELETE x` THEN
  ABBREV_TAC `S2:(A#A)->bool = graph_darts E2 DELETE y` THEN
  SUBGOAL_THEN
   `DISJOINT (S1:(A#A)->bool) S2 /\
    S1 UNION S2 = graph_darts (E1 UNION E2)`
  (CONJUNCTS_THEN2 (LABEL_TAC "disjoint") (LABEL_TAC "union")) THENL
   [MAP_EVERY EXPAND_TAC ["S1"; "S2"; "x"; "y"] THEN
    MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
     GRAPH_SPLIT_DART_PARTITION) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(f1:(A#A)->A#A) permutes graph_darts E1 /\
    (f2:(A#A)->A#A) permutes graph_darts E2`
  (CONJUNCTS_THEN2 (LABEL_TAC "face1_permutation")
    (LABEL_TAC "face2_permutation")) THENL
   [EXPAND_TAC "f1" THEN EXPAND_TAC "f2" THEN CONJ_TAC THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(x:A#A) IN graph_darts E1 /\ (y:A#A) IN graph_darts E2`
  (CONJUNCTS_THEN2 (LABEL_TAC "x_dart") (LABEL_TAC "y_dart")) THENL
   [MAP_EVERY EXPAND_TAC ["x"; "y"] THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS;
                    SET_RULE `{v:A,u} = {u,v}`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((f1:(A#A)->A#A) x = x) /\
    ~((f2:(A#A)->A#A) y = y)`
  (CONJUNCTS_THEN2 (LABEL_TAC "x_nonfixed")
    (LABEL_TAC "y_nonfixed")) THENL
   [EXPAND_TAC "f1" THEN EXPAND_TAC "f2" THEN CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`; `r1:(A#A)->A#A`;
        `x:A#A`] GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
       [`V2:A->bool`; `E2:(A->bool)->bool`; `r2:(A#A)->A#A`;
        `y:A#A`] GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_delete (f1:(A#A)->A#A) x permutes S1 /\
    permutation_delete (f2:(A#A)->A#A) y permutes S2`
  (CONJUNCTS_THEN2 (LABEL_TAC "deleted1_permutation")
    (LABEL_TAC "deleted2_permutation")) THENL
   [CONJ_TAC THENL
     [EXPAND_TAC "S1" THEN
      MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN ASM_REWRITE_TAC[];
      EXPAND_TAC "S2" THEN
      MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(f1:(A#A)->A#A) x IN S1 /\
    (f2:(A#A)->A#A) y IN S2`
  (CONJUNCTS_THEN2 (LABEL_TAC "f1x_member")
    (LABEL_TAC "f2y_member")) THENL
   [CONJ_TAC THENL
     [EXPAND_TAC "S1" THEN REWRITE_TAC[IN_DELETE] THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`f1:(A#A)->A#A`; `graph_darts E1:A#A->bool`;
                     `x:A#A`] PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[];
      EXPAND_TAC "S2" THEN REWRITE_TAC[IN_DELETE] THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`f2:(A#A)->A#A`; `graph_darts E2:A#A->bool`;
                     `y:A#A`] PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[graph_split_face_permutation] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "union" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_PERMUTES THEN
    MAP_EVERY EXPAND_TAC ["S1"; "S2"] THEN
    ASM_REWRITE_TAC[FINITE_DELETE] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
       [`V2:A->bool`; `E2:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      ASM_REWRITE_TAC[]];
    USE_THEN "union" (fun th -> REWRITE_TAC[GSYM th; IN_UNION]) THEN
    DISJ1_TAC THEN USE_THEN "f1x_member" ACCEPT_TAC;
    USE_THEN "union" (fun th -> REWRITE_TAC[GSYM th; IN_UNION]) THEN
    DISJ2_TAC THEN USE_THEN "f2y_member" ACCEPT_TAC]);;

let CARD_GRAPH_SPLIT_FACE_PERMUTATION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u v:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2
        ==> CARD(graph_faces E1 r1) + CARD(graph_faces E2 r2) =
            CARD
             (permutation_orbits
               (graph_split_face_permutation E1 E2 r1 r2 u v)
               (graph_darts (E1 UNION E2))) + 1`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 rotation1 rotation2 overlap chord1 chord2" THEN
  ABBREV_TAC `x:A#A = (u:A,v:A)` THEN
  ABBREV_TAC `y:A#A = (v:A,u:A)` THEN
  ABBREV_TAC
   `f1:(A#A)->A#A =
      graph_face_successor (E1:(A->bool)->bool) (r1:(A#A)->A#A)` THEN
  ABBREV_TAC
   `f2:(A#A)->A#A =
      graph_face_successor (E2:(A->bool)->bool) (r2:(A#A)->A#A)` THEN
  ABBREV_TAC `S1:(A#A)->bool = graph_darts E1 DELETE x` THEN
  ABBREV_TAC `S2:(A#A)->bool = graph_darts E2 DELETE y` THEN
  ABBREV_TAC
   `g1:(A#A)->A#A = permutation_delete (f1:(A#A)->A#A) x` THEN
  ABBREV_TAC
   `g2:(A#A)->A#A = permutation_delete (f2:(A#A)->A#A) y` THEN
  ABBREV_TAC
   `p:(A#A)->A#A =
      disjoint_permutation_union (g1:(A#A)->A#A) S1 g2` THEN
  SUBGOAL_THEN
   `DISJOINT (S1:(A#A)->bool) S2 /\
    S1 UNION S2 = graph_darts (E1 UNION E2)`
  (CONJUNCTS_THEN2 (LABEL_TAC "disjoint") (LABEL_TAC "union")) THENL
   [MAP_EVERY EXPAND_TAC ["S1"; "S2"; "x"; "y"] THEN
    MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
     GRAPH_SPLIT_DART_PARTITION) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(graph_darts E1:A#A->bool) /\
    FINITE(graph_darts E2:A#A->bool)`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_darts1")
    (LABEL_TAC "finite_darts2")) THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
       [`V2:A->bool`; `E2:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(S1:(A#A)->bool) /\ FINITE(S2:(A#A)->bool)`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_s1") (LABEL_TAC "finite_s2")) THENL
   [MAP_EVERY EXPAND_TAC ["S1"; "S2"] THEN
    ASM_REWRITE_TAC[FINITE_DELETE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(f1:(A#A)->A#A) permutes graph_darts E1 /\
    (f2:(A#A)->A#A) permutes graph_darts E2`
  (CONJUNCTS_THEN2 (LABEL_TAC "face1_permutation")
    (LABEL_TAC "face2_permutation")) THENL
   [EXPAND_TAC "f1" THEN EXPAND_TAC "f2" THEN CONJ_TAC THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(x:A#A) IN graph_darts E1 /\ (y:A#A) IN graph_darts E2`
  (CONJUNCTS_THEN2 (LABEL_TAC "x_dart") (LABEL_TAC "y_dart")) THENL
   [MAP_EVERY EXPAND_TAC ["x"; "y"] THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS;
                    SET_RULE `{v:A,u} = {u,v}`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((f1:(A#A)->A#A) x = x) /\
    ~((f2:(A#A)->A#A) y = y)`
  (CONJUNCTS_THEN2 (LABEL_TAC "x_nonfixed")
    (LABEL_TAC "y_nonfixed")) THENL
   [EXPAND_TAC "f1" THEN EXPAND_TAC "f2" THEN CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`; `r1:(A#A)->A#A`;
        `x:A#A`] GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
       [`V2:A->bool`; `E2:(A->bool)->bool`; `r2:(A#A)->A#A`;
        `y:A#A`] GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(g1:(A#A)->A#A) permutes S1 /\ (g2:(A#A)->A#A) permutes S2`
  (CONJUNCTS_THEN2 (LABEL_TAC "g1_permutation")
    (LABEL_TAC "g2_permutation")) THENL
   [MAP_EVERY EXPAND_TAC ["g1"; "g2"; "S1"; "S2"] THEN CONJ_TAC THEN
    MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(f1:(A#A)->A#A) x IN S1 /\
    (f2:(A#A)->A#A) y IN S2`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_member") (LABEL_TAC "b_member")) THENL
   [CONJ_TAC THENL
     [EXPAND_TAC "S1" THEN REWRITE_TAC[IN_DELETE] THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`f1:(A#A)->A#A`; `graph_darts E1:A#A->bool`;
                     `x:A#A`] PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[];
      EXPAND_TAC "S2" THEN REWRITE_TAC[IN_DELETE] THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`f2:(A#A)->A#A`; `graph_darts E2:A#A->bool`;
                     `y:A#A`] PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:(A#A)->A#A) permutes (S1 UNION S2)`
  (LABEL_TAC "p_permutation") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(permutation_orbit (p:(A#A)->A#A)
       ((f1:(A#A)->A#A) x) =
      permutation_orbit p ((f2:(A#A)->A#A) y))`
  (LABEL_TAC "different_orbits") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC(ISPECL
     [`g1:(A#A)->A#A`; `g2:(A#A)->A#A`;
      `S1:(A#A)->bool`; `S2:(A#A)->bool`;
      `(f1:(A#A)->A#A) x`; `(f2:(A#A)->A#A) y`]
     PERMUTATION_ORBIT_DISJOINT_UNION_DISTINCT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(permutation_orbits (p:(A#A)->A#A) (S1 UNION S2)) =
    CARD
     (permutation_orbits
       (swap((f1:(A#A)->A#A) x,(f2:(A#A)->A#A) y) o p)
       (S1 UNION S2)) + 1`
  (LABEL_TAC "merged") THENL
   [MATCH_MP_TAC PERMUTATION_ORBITS_SWAP_DISTINCT THEN
    ASM_REWRITE_TAC[FINITE_UNION; IN_UNION];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(permutation_orbits (p:(A#A)->A#A) (S1 UNION S2)) =
    CARD(permutation_orbits g1 S1) +
    CARD(permutation_orbits g2 S2)`
  (LABEL_TAC "sum") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC CARD_PERMUTATION_ORBITS_DISJOINT_UNION THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(permutation_orbits (g1:(A#A)->A#A) S1) =
      CARD
       (permutation_orbits
         (f1:(A#A)->A#A)
         (graph_darts (E1:(A->bool)->bool))) /\
    CARD(permutation_orbits (g2:(A#A)->A#A) S2) =
      CARD
       (permutation_orbits
         (f2:(A#A)->A#A)
         (graph_darts (E2:(A->bool)->bool)))`
  (CONJUNCTS_THEN2 (LABEL_TAC "delete1_count")
    (LABEL_TAC "delete2_count")) THENL
   [CONJ_TAC THENL
     [MAP_EVERY EXPAND_TAC ["g1"; "S1"] THEN
      MATCH_MP_TAC PERMUTATION_DELETE_ORBIT_COUNT THEN ASM_REWRITE_TAC[];
      MAP_EVERY EXPAND_TAC ["g2"; "S2"] THEN
      MATCH_MP_TAC PERMUTATION_DELETE_ORBIT_COUNT THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  USE_THEN "sum" MP_TAC THEN USE_THEN "merged" MP_TAC THEN
  USE_THEN "union" (fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXPAND_TAC ["p"; "g1"; "g2"; "S1"; "S2";
                       "f1"; "f2"; "x"; "y"] THEN
  REWRITE_TAC[graph_split_face_permutation;
              GRAPH_FACES_AS_PERMUTATION_ORBITS] THEN
  ASM_REWRITE_TAC[] THEN ARITH_TAC);;

let SWAP_PERMUTATION_DELETE_CANCEL = prove
 (`!f:A->A. !x z.
        swap(x,f x) (permutation_delete f x z) = f z`,
  REWRITE_TAC[permutation_delete; o_THM; swap] THEN MESON_TAC[]);;

let SWAP_PERMUTATION_DELETE_SPLICE = prove
 (`!f g:A->A. !x y z.
        ~(f z = f x) /\
        ~(f z = g y)
        ==> swap(f x,g y) (permutation_delete f x z) =
            swap(x,g y) (f z)`,
  REWRITE_TAC[permutation_delete; o_THM; swap] THEN MESON_TAC[]);;

let GRAPH_SPLIT_LOCAL_ROTATION_LEFT_AT_LEFT = prove
 (`!V1 E1 E2 r1 r2 u v d:A#A.
        {u,v} IN E2 /\
        d IN outgoing_darts E1 u
        ==> graph_split_local_rotation V1 E1 E2 r1 r2 u v u d =
            swap((u,v),r2(u,v)) (r1 d)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_REWRITE_TAC
   [graph_split_local_rotation; permutation_cycle_splice; o_THM;
    disjoint_permutation_union; restricted_permutation;
    IN_OUTGOING_DARTS_PAIR]);;

let GRAPH_SPLIT_LOCAL_ROTATION_RIGHT_AT_RIGHT = prove
 (`!V1 E1 E2 r1 r2 u v d:A#A.
        ~(u = v) /\
        {u,v} IN E1 /\
        d IN outgoing_darts E2 v
        ==> graph_split_local_rotation V1 E1 E2 r1 r2 u v v d =
            swap((v,u),r1(v,u)) (r2 d)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_REWRITE_TAC
   [graph_split_local_rotation; permutation_cycle_splice; o_THM;
    disjoint_permutation_union; restricted_permutation;
    IN_OUTGOING_DARTS_PAIR; SET_RULE `{v:A,u} = {u,v}`]);;

let GRAPH_SPLIT_LOCAL_ROTATION_LEFT_AT_RIGHT = prove
 (`!V1 E1 E2 r1 r2 u v d:A#A.
        ~(u = v) /\
        {u,v} IN E1 /\
        d IN outgoing_darts E1 v /\
        ~(d IN outgoing_darts E2 v)
        ==> graph_split_local_rotation V1 E1 E2 r1 r2 u v v d =
            r1 d`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_REWRITE_TAC
   [graph_split_local_rotation; permutation_cycle_splice; o_THM;
    disjoint_permutation_union] THEN
  REWRITE_TAC[SWAP_PERMUTATION_DELETE_CANCEL] THEN
  ASM_REWRITE_TAC[restricted_permutation]);;

let GRAPH_SPLIT_LOCAL_ROTATION_RIGHT_AT_LEFT = prove
 (`!V1 E1 E2 r1 r2 u v d:A#A.
        {u,v} IN E2 /\
        d IN outgoing_darts E2 u /\
        ~(d IN outgoing_darts E1 u)
        ==> graph_split_local_rotation V1 E1 E2 r1 r2 u v u d =
            r2 d`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_REWRITE_TAC
   [graph_split_local_rotation; permutation_cycle_splice; o_THM;
    disjoint_permutation_union] THEN
  REWRITE_TAC[SWAP_PERMUTATION_DELETE_CANCEL] THEN
  ASM_REWRITE_TAC[restricted_permutation]);;

let GRAPH_SPLIT_LOCAL_ROTATION_LEFT_AWAY = prove
 (`!V1 E1 E2 r1 r2 u v w d:A#A.
        ~(w = u) /\
        ~(w = v) /\
        w IN V1 /\
        d IN outgoing_darts E1 w
        ==> graph_split_local_rotation V1 E1 E2 r1 r2 u v w d =
            r1 d`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_REWRITE_TAC
   [graph_split_local_rotation; restricted_permutation]);;

let GRAPH_SPLIT_LOCAL_ROTATION_RIGHT_AWAY = prove
 (`!V1 E1 E2 r1 r2 u v w d:A#A.
        ~(w = u) /\
        ~(w = v) /\
        ~(w IN V1) /\
        d IN outgoing_darts E2 w
        ==> graph_split_local_rotation V1 E1 E2 r1 r2 u v w d =
            r2 d`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_REWRITE_TAC
   [graph_split_local_rotation; restricted_permutation]);;

let GRAPH_SPLIT_FACE_PERMUTATION_LEFT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u v:A. !d:A#A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2 /\
        ~(restricted_permutation r2 (outgoing_darts E2 u) (u,v) =
          (u,v)) /\
        d IN graph_darts E1 DELETE (u,v)
        ==> graph_split_face_permutation E1 E2 r1 r2 u v d =
            if SND d = u then
              swap((u,v),graph_face_successor E2 r2 (v,u))
                (graph_face_successor E1 r1 d)
            else graph_face_successor E1 r1 d`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph1 graph2 rotation1 rotation2 overlap chord1 chord2
    cross_nonfixed d_left" THEN
  ABBREV_TAC `x:A#A = (u:A,v:A)` THEN
  ABBREV_TAC `y:A#A = (v:A,u:A)` THEN
  ABBREV_TAC
   `f1:(A#A)->A#A =
      graph_face_successor (E1:(A->bool)->bool) (r1:(A#A)->A#A)` THEN
  ABBREV_TAC
   `f2:(A#A)->A#A =
      graph_face_successor (E2:(A->bool)->bool) (r2:(A#A)->A#A)` THEN
  ABBREV_TAC `S1:(A#A)->bool = graph_darts E1 DELETE x` THEN
  ABBREV_TAC `S2:(A#A)->bool = graph_darts E2 DELETE y` THEN
  SUBGOAL_THEN
   `DISJOINT (S1:(A#A)->bool) S2`
  (LABEL_TAC "disjoint") THENL
   [MAP_EVERY EXPAND_TAC ["S1"; "S2"; "x"; "y"] THEN
    MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
     `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
     GRAPH_SPLIT_DART_PARTITION) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(f1:(A#A)->A#A) permutes graph_darts E1 /\
    (f2:(A#A)->A#A) permutes graph_darts E2`
  (CONJUNCTS_THEN2 (LABEL_TAC "face1_permutation")
    (LABEL_TAC "face2_permutation")) THENL
   [MAP_EVERY EXPAND_TAC ["f1"; "f2"] THEN
    CONJ_TAC THEN MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(x:A#A) IN graph_darts E1 /\
    (y:A#A) IN graph_darts E2`
  (CONJUNCTS_THEN2 (LABEL_TAC "x_dart") (LABEL_TAC "y_dart")) THENL
   [MAP_EVERY EXPAND_TAC ["x"; "y"] THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS;
                    SET_RULE `{v:A,u} = {u,v}`];
    ALL_TAC] THEN
  SUBGOAL_THEN `(d:A#A) IN S1`
  (LABEL_TAC "d_s1") THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "d_s1" MP_TAC THEN
  EXPAND_TAC "S1" THEN REWRITE_TAC[IN_DELETE] THEN
  INTRO_TAC "d_dart d_not_x" THEN
  SUBGOAL_THEN `(f2:(A#A)->A#A) y IN S2`
  (LABEL_TAC "b_s2") THENL
   [EXPAND_TAC "S2" THEN REWRITE_TAC[IN_DELETE] THEN
    SUBGOAL_THEN `~((f2:(A#A)->A#A) y = y)`
    (LABEL_TAC "b_not_y") THENL
     [EXPAND_TAC "f2" THEN
      MATCH_ACCEPT_TAC
       (MATCH_MP
         (ISPECL
           [`V2:A->bool`; `E2:(A->bool)->bool`; `r2:(A#A)->A#A`;
            `y:A#A`]
           GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT)
         (CONJ
           (ASSUME `finite_simple_graph (V2:A->bool) E2`)
           (CONJ
             (ASSUME `graph_rotation E2 (r2:(A#A)->A#A)`)
             (ASSUME `(y:A#A) IN graph_darts E2`))));
      MP_TAC(ISPECL
       [`f2:(A#A)->A#A`; `graph_darts E2:A#A->bool`; `y:A#A`]
       PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((f2:(A#A)->A#A) y = x)`
  (LABEL_TAC "b_not_x") THENL
   [SUBGOAL_THEN
     `restricted_permutation r2 (outgoing_darts E2 u) (u,v) =
      (r2:(A#A)->A#A) (u,v)`
     (LABEL_TAC "restricted_is_r2") THENL
     [REWRITE_TAC[restricted_permutation] THEN
      ASM_REWRITE_TAC[IN_OUTGOING_DARTS_PAIR];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((r2:(A#A)->A#A) (u,v) = (u,v))`
     (LABEL_TAC "r2_nonfixed") THENL
     [ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(f2:(A#A)->A#A) y =
      (r2:(A#A)->A#A) (x:A#A)`
     (LABEL_TAC "right_successor") THENL
     [MAP_EVERY EXPAND_TAC ["f2"; "x"; "y"] THEN
      ASM_SIMP_TAC
       [GRAPH_FACE_SUCCESSOR_IN; IN_GRAPH_DARTS;
        REVERSE_DART_PAIR; SET_RULE `{v:A,u} = {u,v}`];
      USE_THEN "right_successor" (fun th -> REWRITE_TAC[th]) THEN
      EXPAND_TAC "x" THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FST((f1:(A#A)->A#A) d) = SND d`
  (LABEL_TAC "tail_d") THENL
   [EXPAND_TAC "f1" THEN
    MATCH_MP_TAC
     (ISPECL
       [`E1:(A->bool)->bool`; `r1:(A#A)->A#A`; `d:A#A`]
       GRAPH_FACE_SUCCESSOR_TAIL) THEN
    CONJ_TAC THENL
     [USE_THEN "rotation1" ACCEPT_TAC;
      USE_THEN "d_dart" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FST((f1:(A#A)->A#A) x) = SND x`
  (LABEL_TAC "tail_x") THENL
   [EXPAND_TAC "f1" THEN
    MATCH_MP_TAC
     (ISPECL
       [`E1:(A->bool)->bool`; `r1:(A#A)->A#A`; `x:A#A`]
       GRAPH_FACE_SUCCESSOR_TAIL) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FST((f2:(A#A)->A#A) y) = SND y`
  (LABEL_TAC "tail_y") THENL
   [EXPAND_TAC "f2" THEN
    MATCH_MP_TAC
     (ISPECL
       [`E2:(A->bool)->bool`; `r2:(A#A)->A#A`; `y:A#A`]
       GRAPH_FACE_SUCCESSOR_TAIL) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC
   [graph_split_face_permutation; o_THM;
    disjoint_permutation_union] THEN
  ASM_CASES_TAC `SND(d:A#A) = u` THENL
   [ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC SWAP_PERMUTATION_DELETE_SPLICE THEN
    CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "same_image") THEN
      MP_TAC(MATCH_MP
      (ISPECL
        [`f1:(A#A)->A#A`; `graph_darts E1:A#A->bool`]
        PERMUTES_INJECTIVE)
       (ASSUME `(f1:(A#A)->A#A) permutes graph_darts E1`)) THEN
      DISCH_THEN(MP_TAC o SPECL [`d:A#A`; `x:A#A`]) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "d_eq_x") THEN
      USE_THEN "d_not_x" (fun th ->
        CONTR_TAC(MP (NOT_ELIM th) (ASSUME `(d:A#A) = x`)));
      ASM_CASES_TAC `(f1:(A#A)->A#A) d = x` THENL
       [DISCH_THEN(LABEL_TAC "image_eq_b") THEN
        USE_THEN "b_not_x" (fun th ->
          CONTR_TAC(MP (NOT_ELIM th)
            (TRANS
              (SYM(ASSUME `(f1:(A#A)->A#A) d =
                           (f2:(A#A)->A#A) y`))
              (ASSUME `(f1:(A#A)->A#A) d = x`))));
        SUBGOAL_THEN `(f1:(A#A)->A#A) d IN S1`
        (LABEL_TAC "image_s1") THENL
         [EXPAND_TAC "S1" THEN REWRITE_TAC[IN_DELETE] THEN
          MP_TAC(ISPECL
           [`f1:(A#A)->A#A`; `graph_darts E1:A#A->bool`; `d:A#A`]
           PERMUTES_IN_IMAGE) THEN
          ASM_REWRITE_TAC[IN_DELETE];
          SUBGOAL_THEN
           `~((f1:(A#A)->A#A) d IN S2)`
          (LABEL_TAC "image_not_s2") THENL
           [USE_THEN "disjoint" MP_TAC THEN
            REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
            DISCH_THEN(MP_TAC o SPEC `(f1:(A#A)->A#A) d`) THEN
            ASM_REWRITE_TAC[];
            DISCH_THEN(LABEL_TAC "image_eq_b") THEN
            SUBGOAL_THEN `(f1:(A#A)->A#A) d IN S2`
            (LABEL_TAC "image_s2") THENL
             [USE_THEN "image_eq_b" (fun th -> REWRITE_TAC[th]) THEN
              USE_THEN "b_s2" ACCEPT_TAC;
            USE_THEN "image_not_s2" (fun th ->
              CONTR_TAC(MP (NOT_ELIM th)
                (ASSUME `(f1:(A#A)->A#A) d IN S2`)))]]]]];
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `~((f1:(A#A)->A#A) d = x)`
    (LABEL_TAC "image_not_x") THENL
     [DISCH_THEN(MP_TAC o AP_TERM `FST:A#A->A`) THEN
      EXPAND_TAC "x" THEN ASM_REWRITE_TAC[FST];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((f1:(A#A)->A#A) d = (f1:(A#A)->A#A) x)`
    (LABEL_TAC "image_not_a") THENL
     [DISCH_THEN(LABEL_TAC "same_image") THEN
      MP_TAC(MATCH_MP
       (ISPECL
        [`f1:(A#A)->A#A`; `graph_darts E1:A#A->bool`]
        PERMUTES_INJECTIVE)
       (ASSUME `(f1:(A#A)->A#A) permutes graph_darts E1`)) THEN
      DISCH_THEN(MP_TAC o SPECL [`d:A#A`; `x:A#A`]) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "d_eq_x") THEN
      USE_THEN "d_not_x" (fun th ->
        CONTR_TAC(MP (NOT_ELIM th) (ASSUME `(d:A#A) = x`)));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((f1:(A#A)->A#A) d = (f2:(A#A)->A#A) y)`
    (LABEL_TAC "image_not_b") THENL
     [DISCH_THEN(MP_TAC o AP_TERM `FST:A#A->A`) THEN
      ASM_REWRITE_TAC[] THEN
      EXPAND_TAC "y" THEN ASM_REWRITE_TAC[SND];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`f1:(A#A)->A#A`; `graph_darts E1:A#A->bool`;
      `x:A#A`; `d:A#A`] PERMUTATION_DELETE_APPLY_IN) THEN
    ASM_REWRITE_TAC[IN_DELETE] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC SWAP_OTHER THEN ASM_REWRITE_TAC[]]);;

let GRAPH_SPLIT_FACE_PERMUTATION_SWAP_RIGHT = prove
 (`!E1 E2:(A->bool)->bool. !r1 r2:(A#A)->A#A.
   !u v:A. !d:A#A.
        DISJOINT
          (graph_darts E1 DELETE (u,v))
          (graph_darts E2 DELETE (v,u)) /\
        d IN graph_darts E2 DELETE (v,u)
        ==> graph_split_face_permutation E1 E2 r1 r2 u v d =
            graph_split_face_permutation E2 E1 r2 r1 v u d`,
  REPEAT GEN_TAC THEN INTRO_TAC "disjoint right" THEN
  SUBGOAL_THEN
   `~((d:A#A) IN graph_darts E1 DELETE (u,v))`
  (LABEL_TAC "not_left") THENL
   [USE_THEN "disjoint" MP_TAC THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `d:A#A`) THEN ASM_REWRITE_TAC[];
    REWRITE_TAC
     [graph_split_face_permutation; o_THM;
      disjoint_permutation_union] THEN
    ASM_REWRITE_TAC[SWAP_SYM]]);;

let GRAPH_SPLIT_FACE_PERMUTATION_RIGHT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u v:A. !d:A#A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2 /\
        ~(restricted_permutation r1 (outgoing_darts E1 v) (v,u) =
          (v,u)) /\
        d IN graph_darts E2 DELETE (v,u)
        ==> graph_split_face_permutation E1 E2 r1 r2 u v d =
            if SND d = v then
              swap((v,u),graph_face_successor E1 r1 (u,v))
                (graph_face_successor E2 r2 d)
            else graph_face_successor E2 r2 d`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph1 graph2 rotation1 rotation2 overlap chord1 chord2
    cross_nonfixed d_right" THEN
  SUBGOAL_THEN
   `DISJOINT
      (graph_darts E1 DELETE ((u:A),(v:A)))
      (graph_darts E2 DELETE (v,u))`
  (LABEL_TAC "disjoint") THENL
   [MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
     GRAPH_SPLIT_DART_PARTITION) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(V2:A->bool) INTER V1 = {v,u}`
  (LABEL_TAC "reverse_overlap") THENL
   [USE_THEN "overlap" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  TRANS_TAC EQ_TRANS
   `graph_split_face_permutation
      (E2:(A->bool)->bool) E1 r2 r1 v u d` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC GRAPH_SPLIT_FACE_PERMUTATION_SWAP_RIGHT THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V2:A->bool`; `V1:A->bool`;
      `E2:(A->bool)->bool`; `E1:(A->bool)->bool`;
      `r2:(A#A)->A#A`; `r1:(A#A)->A#A`;
      `v:A`; `u:A`; `d:A#A`]
     GRAPH_SPLIT_FACE_PERMUTATION_LEFT) THEN
    ASM_REWRITE_TAC[SET_RULE `{v:A,u} = {u,v}`]]);;

let GRAPH_SPLIT_REVERSE_LEFT_NOT_RIGHT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !u v:A. !d:A#A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2 /\
        d IN graph_darts E1 DELETE (u,v) /\
        SND d = v
        ==> ~(reverse_dart d IN outgoing_darts E2 v)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 overlap chord1 chord2 d_left head" THEN
  USE_THEN "d_left" MP_TAC THEN REWRITE_TAC[IN_DELETE] THEN
  INTRO_TAC "d_dart d_not_chord" THEN
  SUBGOAL_THEN
   `outgoing_darts E1 (v:A) INTER outgoing_darts E2 v = {(v,u)}`
  (LABEL_TAC "shared") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_SHARED_OUTGOING_RIGHT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(d:A#A) IN outgoing_darts E1 v`
  (LABEL_TAC "reverse_left") THENL
   [REWRITE_TAC[IN_OUTGOING_DARTS; GRAPH_DARTS_REVERSE;
                FST_REVERSE_DART] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(LABEL_TAC "reverse_right")] THEN
  SUBGOAL_THEN
   `reverse_dart(d:A#A) IN
    outgoing_darts E1 v INTER outgoing_darts E2 v`
  (LABEL_TAC "reverse_shared") THENL
   [ASM_REWRITE_TAC[IN_INTER];
    ALL_TAC] THEN
  SUBGOAL_THEN `reverse_dart(d:A#A) = (v,u)`
  (LABEL_TAC "reverse_chord") THENL
   [USE_THEN "reverse_shared" MP_TAC THEN
    USE_THEN "shared" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN `(d:A#A) = (u,v)`
  (LABEL_TAC "d_chord") THENL
   [MP_TAC(AP_TERM `reverse_dart:A#A->A#A`
     (ASSUME `reverse_dart(d:A#A) = (v,u)`)) THEN
    REWRITE_TAC[REVERSE_DART_INVOLUTION; REVERSE_DART_PAIR];
    USE_THEN "d_not_chord" (fun th ->
      CONTR_TAC(MP (NOT_ELIM th) (ASSUME `(d:A#A) = (u,v)`)))]);;

