let GRAPH_FACE_SUCCESSOR_SPLIT_LEFT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u v:A. !d:A#A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2 /\
        d IN graph_darts E1 DELETE (u,v)
        ==> graph_face_successor
             (E1 UNION E2)
             (graph_split_rotation V1 E1 E2 r1 r2 u v) d =
            if SND d = u then
              swap((u,v),graph_face_successor E2 r2 (v,u))
                (graph_face_successor E1 r1 d)
            else graph_face_successor E1 r1 d`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 overlap chord1 chord2 d_left" THEN
  USE_THEN "d_left" MP_TAC THEN REWRITE_TAC[IN_DELETE] THEN
  INTRO_TAC "d_dart d_not_chord" THEN
  SUBGOAL_THEN `~((u:A) = v)` (LABEL_TAC "distinct") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_SHARED_EDGE_DISTINCT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(d:A#A) IN outgoing_darts E1 (SND d)`
  (LABEL_TAC "reverse_left") THENL
   [REWRITE_TAC[IN_OUTGOING_DARTS; GRAPH_DARTS_REVERSE;
                FST_REVERSE_DART] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(SND(d:A#A)) IN V1`
  (LABEL_TAC "head_vertex") THENL
   [MP_TAC(MATCH_MP
     (ISPECL
      [`V1:A->bool`; `E1:(A->bool)->bool`]
     GRAPH_DARTS_SUBSET_CROSS)
    (ASSUME `finite_simple_graph (V1:A->bool) E1`)) THEN
    REWRITE_TAC[SUBSET] THEN
    DISCH_THEN(MP_TAC o SPEC `(FST(d:A#A),SND d)`) THEN
    ASM_REWRITE_TAC[PAIR; IN_CROSS] THEN
    DISCH_THEN(CONJUNCTS_THEN2
      (LABEL_TAC "tail_vertex") ACCEPT_TAC);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor
      (E1 UNION E2:(A->bool)->bool)
      (graph_split_rotation (V1:A->bool) E1 E2 r1 r2 u v) (d:A#A) =
    graph_split_local_rotation (V1:A->bool) E1 E2 r1 r2 u v
      (SND(d:A#A)) (reverse_dart d)`
  (LABEL_TAC "union_successor") THENL
   [ASM_SIMP_TAC
     [GRAPH_FACE_SUCCESSOR_IN; graph_split_rotation;
      GRAPH_DARTS_UNION; IN_UNION;
      GRAPH_DARTS_REVERSE; FST_REVERSE_DART];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E1 r1 (d:A#A) = r1(reverse_dart d)`
  (LABEL_TAC "left_successor") THENL
   [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_IN THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E2 r2 ((v:A),(u:A)) = r2(u,v)`
  (LABEL_TAC "cross_successor") THENL
   [MP_TAC(ISPECL
     [`E2:(A->bool)->bool`; `r2:(A#A)->A#A`; `(v:A,u:A)`]
     GRAPH_FACE_SUCCESSOR_IN) THEN
    ASM_REWRITE_TAC
     [IN_GRAPH_DARTS; REVERSE_DART_PAIR;
      SET_RULE `{v:A,u} = {u,v}`];
    ALL_TAC] THEN
  USE_THEN "union_successor" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "left_successor" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "cross_successor" (fun th -> REWRITE_TAC[th]) THEN
  ASM_CASES_TAC `SND(d:A#A) = u` THENL
   [ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `reverse_dart(d:A#A) IN outgoing_darts E1 u`
    (LABEL_TAC "reverse_left_at_u") THENL
     [USE_THEN "reverse_left" (fun th ->
        ACCEPT_TAC(SUBS [ASSUME `SND(d:A#A) = u`] th));
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
      `u:A`; `v:A`; `reverse_dart(d:A#A)`]
     GRAPH_SPLIT_LOCAL_ROTATION_LEFT_AT_LEFT) THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[] THEN
    ASM_CASES_TAC `SND(d:A#A) = v` THENL
     [SUBGOAL_THEN
       `~(reverse_dart(d:A#A) IN outgoing_darts E2 v)`
      (LABEL_TAC "not_right") THENL
       [MATCH_MP_TAC(ISPECL
         [`V1:A->bool`; `V2:A->bool`;
          `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
          `u:A`; `v:A`; `d:A#A`]
         GRAPH_SPLIT_REVERSE_LEFT_NOT_RIGHT) THEN
        ASM_REWRITE_TAC[IN_DELETE];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `reverse_dart(d:A#A) IN outgoing_darts E1 v`
      (LABEL_TAC "reverse_left_at_v") THENL
       [USE_THEN "reverse_left" (fun th ->
          ACCEPT_TAC(SUBS [ASSUME `SND(d:A#A) = v`] th));
        ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
        `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
       `u:A`; `v:A`; `reverse_dart(d:A#A)`]
       GRAPH_SPLIT_LOCAL_ROTATION_LEFT_AT_RIGHT) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
        `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
        `u:A`; `v:A`; `SND(d:A#A)`; `reverse_dart(d:A#A)`]
       GRAPH_SPLIT_LOCAL_ROTATION_LEFT_AWAY) THEN
      ASM_REWRITE_TAC[]]]);;

let GRAPH_FACE_SUCCESSOR_SPLIT_RIGHT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u v:A. !d:A#A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2 /\
        d IN graph_darts E2 DELETE (v,u)
        ==> graph_face_successor
             (E1 UNION E2)
             (graph_split_rotation V1 E1 E2 r1 r2 u v) d =
            if SND d = v then
              swap((v,u),graph_face_successor E1 r1 (u,v))
                (graph_face_successor E2 r2 d)
            else graph_face_successor E2 r2 d`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 overlap chord1 chord2 d_right" THEN
  USE_THEN "d_right" MP_TAC THEN REWRITE_TAC[IN_DELETE] THEN
  INTRO_TAC "d_dart d_not_chord" THEN
  SUBGOAL_THEN `~((u:A) = v)` (LABEL_TAC "distinct") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_SHARED_EDGE_DISTINCT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(d:A#A) IN outgoing_darts E2 (SND d)`
  (LABEL_TAC "reverse_right") THENL
   [REWRITE_TAC[IN_OUTGOING_DARTS; GRAPH_DARTS_REVERSE;
                FST_REVERSE_DART] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(SND(d:A#A)) IN V2`
  (LABEL_TAC "head_vertex") THENL
   [MP_TAC(MATCH_MP
     (ISPECL
      [`V2:A->bool`; `E2:(A->bool)->bool`]
     GRAPH_DARTS_SUBSET_CROSS)
    (ASSUME `finite_simple_graph (V2:A->bool) E2`)) THEN
    REWRITE_TAC[SUBSET] THEN
    DISCH_THEN(MP_TAC o SPEC `(FST(d:A#A),SND d)`) THEN
    ASM_REWRITE_TAC[PAIR; IN_CROSS] THEN
    DISCH_THEN(CONJUNCTS_THEN2
      (LABEL_TAC "tail_vertex") ACCEPT_TAC);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor
      (E1 UNION E2:(A->bool)->bool)
      (graph_split_rotation (V1:A->bool) E1 E2 r1 r2 u v) (d:A#A) =
    graph_split_local_rotation (V1:A->bool) E1 E2 r1 r2 u v
      (SND(d:A#A)) (reverse_dart d)`
  (LABEL_TAC "union_successor") THENL
   [ASM_SIMP_TAC
     [GRAPH_FACE_SUCCESSOR_IN; graph_split_rotation;
      GRAPH_DARTS_UNION; IN_UNION;
      GRAPH_DARTS_REVERSE; FST_REVERSE_DART];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E2 r2 (d:A#A) = r2(reverse_dart d)`
  (LABEL_TAC "right_successor") THENL
   [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_IN THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E1 r1 ((u:A),(v:A)) = r1(v,u)`
  (LABEL_TAC "cross_successor") THENL
   [MP_TAC(ISPECL
     [`E1:(A->bool)->bool`; `r1:(A#A)->A#A`; `(u:A,v:A)`]
     GRAPH_FACE_SUCCESSOR_IN) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS; REVERSE_DART_PAIR];
    ALL_TAC] THEN
  USE_THEN "union_successor" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "right_successor" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "cross_successor" (fun th -> REWRITE_TAC[th]) THEN
  ASM_CASES_TAC `SND(d:A#A) = v` THENL
   [ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `reverse_dart(d:A#A) IN outgoing_darts E2 v`
    (LABEL_TAC "reverse_right_at_v") THENL
     [USE_THEN "reverse_right" (fun th ->
        ACCEPT_TAC(SUBS [ASSUME `SND(d:A#A) = v`] th));
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
      `u:A`; `v:A`; `reverse_dart(d:A#A)`]
     GRAPH_SPLIT_LOCAL_ROTATION_RIGHT_AT_RIGHT) THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[] THEN
    ASM_CASES_TAC `SND(d:A#A) = u` THENL
     [SUBGOAL_THEN
       `~(reverse_dart(d:A#A) IN outgoing_darts E1 u)`
      (LABEL_TAC "not_left") THENL
       [MATCH_MP_TAC(ISPECL
         [`V1:A->bool`; `V2:A->bool`;
          `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
          `u:A`; `v:A`; `d:A#A`]
         GRAPH_SPLIT_REVERSE_RIGHT_NOT_LEFT) THEN
        ASM_REWRITE_TAC[IN_DELETE];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `reverse_dart(d:A#A) IN outgoing_darts E2 u`
      (LABEL_TAC "reverse_right_at_u") THENL
       [USE_THEN "reverse_right" (fun th ->
          ACCEPT_TAC(SUBS [ASSUME `SND(d:A#A) = u`] th));
        ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
        `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
       `u:A`; `v:A`; `reverse_dart(d:A#A)`]
       GRAPH_SPLIT_LOCAL_ROTATION_RIGHT_AT_LEFT) THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN `~(SND(d:A#A) IN V1)`
      (LABEL_TAC "head_not_left") THENL
       [DISCH_THEN(LABEL_TAC "head_left") THEN
        SUBGOAL_THEN `SND(d:A#A) IN V1 INTER V2` MP_TAC THENL
         [ASM_REWRITE_TAC[IN_INTER];
          USE_THEN "overlap" (fun th -> REWRITE_TAC[th]) THEN
          ASM_REWRITE_TAC[IN_INSERT; IN_SING]];
        ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
        `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
        `u:A`; `v:A`; `SND(d:A#A)`; `reverse_dart(d:A#A)`]
       GRAPH_SPLIT_LOCAL_ROTATION_RIGHT_AWAY) THEN
      ASM_REWRITE_TAC[]]]);;

let GRAPH_FACE_SUCCESSOR_SPLIT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u v:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2 /\
        ~(restricted_permutation r2 (outgoing_darts E2 u) (u,v) =
          (u,v)) /\
        ~(restricted_permutation r1 (outgoing_darts E1 v) (v,u) =
          (v,u))
        ==> graph_face_successor
             (E1 UNION E2)
             (graph_split_rotation V1 E1 E2 r1 r2 u v) =
            graph_split_face_permutation E1 E2 r1 r2 u v`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph1 graph2 rotation1 rotation2 overlap chord1 chord2
    u_nonfixed v_nonfixed" THEN
  SUBGOAL_THEN
   `DISJOINT
      (graph_darts E1 DELETE ((u:A),(v:A)))
      (graph_darts E2 DELETE (v,u)) /\
    (graph_darts E1 DELETE (u,v)) UNION
    (graph_darts E2 DELETE (v,u)) =
      graph_darts (E1 UNION E2)`
  (CONJUNCTS_THEN2 (LABEL_TAC "disjoint") (LABEL_TAC "union")) THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
     GRAPH_SPLIT_DART_PARTITION) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_rotation
      (E1 UNION E2:(A->bool)->bool)
      (graph_split_rotation (V1:A->bool) E1 E2 r1 r2 u v)`
  (LABEL_TAC "split_rotation") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`; `u:A`; `v:A`]
     GRAPH_SPLIT_ROTATION) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor
      (E1 UNION E2:(A->bool)->bool)
      (graph_split_rotation (V1:A->bool) E1 E2 r1 r2 u v)
      permutes graph_darts (E1 UNION E2:(A->bool)->bool)`
  (LABEL_TAC "concrete_permutation") THENL
   [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(graph_split_face_permutation
       (E1:(A->bool)->bool) E2 r1 r2 u v:(A#A)->A#A)
      permutes graph_darts (E1 UNION E2:(A->bool)->bool)`
  (LABEL_TAC "abstract_permutation") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`; `u:A`; `v:A`]
     GRAPH_SPLIT_FACE_PERMUTATION_PERMUTES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `d:A#A` THEN
  ASM_CASES_TAC `(d:A#A) IN graph_darts (E1 UNION E2)` THENL
   [SUBGOAL_THEN
     `(d:A#A) IN graph_darts E1 DELETE (u,v) \/
      (d:A#A) IN graph_darts E2 DELETE (v,u)`
    (DISJ_CASES_THEN2 (LABEL_TAC "d_left") (LABEL_TAC "d_right"))
    THENL
     [USE_THEN "union" (fun th ->
        MP_TAC(REWRITE_RULE[GSYM th]
          (ASSUME `(d:A#A) IN graph_darts (E1 UNION E2)`))) THEN
      REWRITE_TAC[IN_UNION];
      MP_TAC(ISPECL
       [`V1:A->bool`; `V2:A->bool`;
        `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
        `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
        `u:A`; `v:A`; `d:A#A`]
       GRAPH_FACE_SUCCESSOR_SPLIT_LEFT) THEN
      MP_TAC(ISPECL
       [`V1:A->bool`; `V2:A->bool`;
        `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
        `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
        `u:A`; `v:A`; `d:A#A`]
       GRAPH_SPLIT_FACE_PERMUTATION_LEFT) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[];
      MP_TAC(ISPECL
       [`V1:A->bool`; `V2:A->bool`;
        `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
        `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
        `u:A`; `v:A`; `d:A#A`]
       GRAPH_FACE_SUCCESSOR_SPLIT_RIGHT) THEN
      MP_TAC(ISPECL
       [`V1:A->bool`; `V2:A->bool`;
        `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
        `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
        `u:A`; `v:A`; `d:A#A`]
       GRAPH_SPLIT_FACE_PERMUTATION_RIGHT) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[]];
    SUBGOAL_THEN
     `graph_face_successor
        (E1 UNION E2:(A->bool)->bool)
        (graph_split_rotation (V1:A->bool) E1 E2 r1 r2 u v)
        (d:A#A) = d`
    (LABEL_TAC "concrete_fixed") THENL
     [MP_TAC(SPEC `d:A#A`
       (CONJUNCT1(REWRITE_RULE[permutes]
         (ASSUME
          `graph_face_successor
             (E1 UNION E2:(A->bool)->bool)
             (graph_split_rotation (V1:A->bool) E1 E2 r1 r2 u v)
             permutes graph_darts (E1 UNION E2:(A->bool)->bool)`)))) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(graph_split_face_permutation
        (E1:(A->bool)->bool) E2 r1 r2 u v:(A#A)->A#A) (d:A#A) = d`
    (LABEL_TAC "abstract_fixed") THENL
     [MP_TAC(SPEC `d:A#A`
      (CONJUNCT1(REWRITE_RULE[permutes]
         (ASSUME
          `(graph_split_face_permutation
             (E1:(A->bool)->bool) E2 r1 r2 u v:(A#A)->A#A)
             permutes graph_darts (E1 UNION E2:(A->bool)->bool)`)))) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]]]);;

let CARD_GRAPH_FACES_SPLIT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u v:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2 /\
        ~(restricted_permutation r2 (outgoing_darts E2 u) (u,v) =
          (u,v)) /\
        ~(restricted_permutation r1 (outgoing_darts E1 v) (v,u) =
          (v,u))
        ==> CARD(graph_faces E1 r1) + CARD(graph_faces E2 r2) =
            CARD
             (graph_faces
               (E1 UNION E2)
               (graph_split_rotation V1 E1 E2 r1 r2 u v)) + 1`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph1 graph2 rotation1 rotation2 overlap chord1 chord2
    u_nonfixed v_nonfixed" THEN
  SUBGOAL_THEN
   `graph_face_successor
      (E1 UNION E2:(A->bool)->bool)
      (graph_split_rotation (V1:A->bool) E1 E2 r1 r2 u v) =
    graph_split_face_permutation
      (E1:(A->bool)->bool) E2 r1 r2 u v`
  (LABEL_TAC "successor") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`; `u:A`; `v:A`]
     GRAPH_FACE_SUCCESSOR_SPLIT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V1:A->bool`; `V2:A->bool`;
    `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
    `r1:(A#A)->A#A`; `r2:(A#A)->A#A`; `u:A`; `v:A`]
   CARD_GRAPH_SPLIT_FACE_PERMUTATION) THEN
  ASM_REWRITE_TAC[GRAPH_FACES_AS_PERMUTATION_ORBITS]);;

let EULER_PLANAR_ROTATION_SPLIT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u v:A.
        euler_planar_rotation V1 E1 r1 /\
        euler_planar_rotation V2 E2 r2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2 /\
        ~(restricted_permutation r2 (outgoing_darts E2 u) (u,v) =
          (u,v)) /\
        ~(restricted_permutation r1 (outgoing_darts E1 v) (v,u) =
          (v,u))
        ==> euler_planar_rotation
             (V1 UNION V2)
             (E1 UNION E2)
             (graph_split_rotation V1 E1 E2 r1 r2 u v)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler1 euler2 overlap chord1 chord2 u_nonfixed v_nonfixed" THEN
  USE_THEN "euler1" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph1 rotation1 formula1" THEN
  USE_THEN "euler2" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph2 rotation2 formula2" THEN
  SUBGOAL_THEN `~((u:A) = v)` (LABEL_TAC "distinct") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_SHARED_EDGE_DISTINCT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(E1:(A->bool)->bool = {})`
  (LABEL_TAC "edges1_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "edges1_empty") THEN
    USE_THEN "chord1" (fun th ->
      MP_TAC(SUBS [ASSUME `E1:(A->bool)->bool = {}`] th)) THEN
    REWRITE_TAC[NOT_IN_EMPTY];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(E2:(A->bool)->bool = {})`
  (LABEL_TAC "edges2_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "edges2_empty") THEN
    USE_THEN "chord2" (fun th ->
      MP_TAC(SUBS [ASSUME `E2:(A->bool)->bool = {}`] th)) THEN
    REWRITE_TAC[NOT_IN_EMPTY];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(E1 UNION E2:(A->bool)->bool = {})`
  (LABEL_TAC "union_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "union_empty") THEN
    SUBGOAL_THEN `{u:A,v} IN E1 UNION E2`
    (LABEL_TAC "chord_union") THENL
     [REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
      USE_THEN "chord1" ACCEPT_TAC;
      USE_THEN "chord_union" (fun th ->
        MP_TAC(SUBS
         [ASSUME `E1 UNION E2:(A->bool)->bool = {}`] th)) THEN
      REWRITE_TAC[NOT_IN_EMPTY]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(V1:A->bool) /\ FINITE(E1:(A->bool)->bool) /\
    FINITE(V2:A->bool) /\ FINITE(E2:(A->bool)->bool)`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_v1")
   (CONJUNCTS_THEN2 (LABEL_TAC "finite_e1")
    (CONJUNCTS_THEN2 (LABEL_TAC "finite_v2")
     (LABEL_TAC "finite_e2")))) THENL
   [MAP_EVERY (fun name -> USE_THEN name MP_TAC) ["graph1"; "graph2"] THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD({u:A,v}) = 2`
  (LABEL_TAC "shared_vertices_card") THENL
   [ASM_SIMP_TAC
     [CARD_CLAUSES; FINITE_INSERT; FINITE_SING; CARD_SING; IN_SING] THEN
    ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(V1 INTER V2:A->bool) = 2`
  (LABEL_TAC "vertex_intersection_card") THENL
   [USE_THEN "overlap" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "shared_vertices_card" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(E1:(A->bool)->bool) INTER E2 = {{u,v}}`
  (LABEL_TAC "edge_intersection") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_SHARED_EDGE_INTERSECTION) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD((E1:(A->bool)->bool) INTER E2) = 1`
  (LABEL_TAC "edge_intersection_card") THENL
   [USE_THEN "edge_intersection" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[CARD_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(V1 INTER V2:A->bool) <= CARD V1`
  (LABEL_TAC "vertex_intersection_bound") THENL
   [MATCH_MP_TAC CARD_SUBSET THEN
    ASM_REWRITE_TAC[INTER_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD((E1:(A->bool)->bool) INTER E2) <= CARD E1`
  (LABEL_TAC "edge_intersection_bound") THENL
   [MATCH_MP_TAC CARD_SUBSET THEN
    ASM_REWRITE_TAC[INTER_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(V1 UNION V2:A->bool) + 2 = CARD V1 + CARD V2`
  (LABEL_TAC "vertex_union_card") THENL
   [MP_TAC(ISPECL [`V1:A->bool`; `V2:A->bool`] CARD_UNION_GEN) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "vertex_union_raw") THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(E1 UNION E2:(A->bool)->bool) + 1 = CARD E1 + CARD E2`
  (LABEL_TAC "edge_union_card") THENL
   [MP_TAC(ISPECL
     [`E1:(A->bool)->bool`; `E2:(A->bool)->bool`] CARD_UNION_GEN) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "edge_union_raw") THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(V1:A->bool) +
    CARD(graph_faces (E1:(A->bool)->bool) (r1:(A#A)->A#A)) =
    CARD(E1:(A->bool)->bool) + 2`
  (LABEL_TAC "euler_faces1") THENL
   [USE_THEN "formula1" MP_TAC THEN
    REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(V2:A->bool) +
    CARD(graph_faces (E2:(A->bool)->bool) (r2:(A#A)->A#A)) =
    CARD(E2:(A->bool)->bool) + 2`
  (LABEL_TAC "euler_faces2") THENL
   [USE_THEN "formula2" MP_TAC THEN
    REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(graph_faces (E1:(A->bool)->bool) (r1:(A#A)->A#A)) +
    CARD(graph_faces (E2:(A->bool)->bool) (r2:(A#A)->A#A)) =
    CARD
     (graph_faces
       (E1 UNION E2:(A->bool)->bool)
       (graph_split_rotation
         (V1:A->bool) E1 E2 r1 r2 u v)) + 1`
  (LABEL_TAC "faces_card") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`; `u:A`; `v:A`]
     CARD_GRAPH_FACES_SPLIT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[euler_planar_rotation] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_UNION THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`; `u:A`; `v:A`]
     GRAPH_SPLIT_ROTATION) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* The outer boundary survives gluing: the two copies of the chord disappear *)
(* from their boundary walks and the remaining walks splice together.        *)
(* ------------------------------------------------------------------------- *)

let CYCLIC_INDEX_IMAGES_EQ = prove
 (`!q:num->A. !n i k.
        INJ q (cyclic_indices n) (:A) /\ i < n /\ k < n
        ==> (q i = q k <=> i = k)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN MESON_TAC[]);;

let CYCLIC_DART_SPLIT_LEFT_PREFIX = prove
 (`!q:num->A. !n j i.
        j + 2 < n /\ i < j
        ==> cyclic_dart (cyclic_split_left q n j) (j + 2) i =
            cyclic_dart q n i`,
  REPEAT GEN_TAC THEN INTRO_TAC "bound index" THEN
  REWRITE_TAC[cyclic_dart] THEN
  SUBGOAL_THEN `(i + 1) MOD (j + 2) = i + 1`
  (LABEL_TAC "left_next") THENL
   [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(i + 1) MOD n = i + 1`
  (LABEL_TAC "whole_next") THENL
   [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
    ASM_REWRITE_TAC[cyclic_split_left] THEN ASM_ARITH_TAC]);;

let CYCLIC_DART_SPLIT_LEFT_CHORD = prove
 (`!q:num->A. !n j.
        j + 2 < n
        ==> cyclic_dart (cyclic_split_left q n j) (j + 2) j =
            (q j,q (n - 1))`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "bound") THEN
  REWRITE_TAC[cyclic_dart] THEN
  SUBGOAL_THEN `(j + 1) MOD (j + 2) = j + 1`
  (LABEL_TAC "next") THENL
   [MATCH_MP_TAC MOD_LT THEN ARITH_TAC;
    ASM_REWRITE_TAC[cyclic_split_left; LT_REFL] THEN ARITH_TAC]);;

let CYCLIC_DART_SPLIT_LEFT_LAST = prove
 (`!q:num->A. !n j.
        j + 2 < n
        ==> cyclic_dart (cyclic_split_left q n j) (j + 2) (j + 1) =
            cyclic_dart q n (n - 1)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "bound") THEN
  REWRITE_TAC[cyclic_dart] THEN
  SUBGOAL_THEN `((j + 1) + 1) MOD (j + 2) = 0`
  (LABEL_TAC "left_wrap") THENL
   [SUBGOAL_THEN `(j + 1) + 1 = j + 2` SUBST1_TAC THENL
     [ARITH_TAC;
      REWRITE_TAC[MOD_REFL]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(n - 1 + 1) MOD n = 0`
  (LABEL_TAC "whole_wrap") THENL
   [SUBGOAL_THEN `n - 1 + 1 = n` SUBST1_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[MOD_REFL]];
    ASM_REWRITE_TAC[cyclic_split_left; LT_REFL] THEN ARITH_TAC]);;

let CYCLIC_DART_SPLIT_RIGHT_PREFIX = prove
 (`!q:num->A. !n j k.
        j + 2 < n /\ k < n - j - 1
        ==> cyclic_dart (cyclic_split_right q j) (n - j) k =
            cyclic_dart q n (j + k)`,
  REPEAT GEN_TAC THEN INTRO_TAC "bound index" THEN
  REWRITE_TAC[cyclic_dart] THEN
  SUBGOAL_THEN `(k + 1) MOD (n - j) = k + 1`
  (LABEL_TAC "right_next") THENL
   [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `((j + k) + 1) MOD n = (j + k) + 1`
  (LABEL_TAC "whole_next") THENL
   [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
    ASM_REWRITE_TAC[cyclic_split_right; ADD_ASSOC]]);;

let CYCLIC_DART_SPLIT_RIGHT_CHORD = prove
 (`!q:num->A. !n j.
        j + 2 < n
        ==> cyclic_dart (cyclic_split_right q j) (n - j)
             (n - j - 1) =
            (q (n - 1),q j)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "bound") THEN
  REWRITE_TAC[cyclic_dart] THEN
  SUBGOAL_THEN `(n - j - 1 + 1) MOD (n - j) = 0`
  (LABEL_TAC "wrap") THENL
   [SUBGOAL_THEN `n - j - 1 + 1 = n - j` SUBST1_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[MOD_REFL]];
    ASM_REWRITE_TAC[cyclic_split_right; ADD_CLAUSES; PAIR_EQ] THEN
    AP_TERM_TAC THEN ASM_ARITH_TAC]);;

let CYCLIC_DART_SPLIT_RIGHT_FIRST = prove
 (`!q:num->A. !n j.
        j + 2 < n
        ==> cyclic_dart (cyclic_split_right q j) (n - j) 0 =
            cyclic_dart q n j`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "bound") THEN
  MP_TAC(ISPECL [`q:num->A`; `n:num`; `j:num`; `0`]
    CYCLIC_DART_SPLIT_RIGHT_PREFIX) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    REWRITE_TAC[ADD_CLAUSES]]);;

let CYCLIC_SPLIT_LEFT_AFTER_CHORD = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !q:num->A. !n j.
        j + 2 < n /\
        cyclic_face_successors E r (cyclic_split_left q n j) (j + 2)
        ==> graph_face_successor E r (q j,q (n - 1)) =
            cyclic_dart q n (n - 1)`,
  REPEAT GEN_TAC THEN INTRO_TAC "bound successors" THEN
  USE_THEN "successors" MP_TAC THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  DISCH_THEN(MP_TAC o SPEC `j:num`) THEN
  ANTS_TAC THENL
   [ARITH_TAC;
    DISCH_THEN(LABEL_TAC "successor")] THEN
  SUBGOAL_THEN `(j + 1) MOD (j + 2) = j + 1`
  (LABEL_TAC "next") THENL
   [MATCH_MP_TAC MOD_LT THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_split_left (q:num->A) n j) (j + 2) j =
    (q j,q (n - 1))`
  (LABEL_TAC "chord") THENL
   [MATCH_MP_TAC CYCLIC_DART_SPLIT_LEFT_CHORD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_split_left (q:num->A) n j) (j + 2) (j + 1) =
    cyclic_dart q n (n - 1)`
  (LABEL_TAC "last") THENL
   [MATCH_MP_TAC CYCLIC_DART_SPLIT_LEFT_LAST THEN
    ASM_REWRITE_TAC[];
    ASM_MESON_TAC[]]);;

let CYCLIC_SPLIT_RIGHT_AFTER_CHORD = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !q:num->A. !n j.
        j + 2 < n /\
        cyclic_face_successors E r (cyclic_split_right q j) (n - j)
        ==> graph_face_successor E r (q (n - 1),q j) =
            cyclic_dart q n j`,
  REPEAT GEN_TAC THEN INTRO_TAC "bound successors" THEN
  USE_THEN "successors" MP_TAC THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  DISCH_THEN(MP_TAC o SPEC `n - j - 1`) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(LABEL_TAC "successor")] THEN
  SUBGOAL_THEN `((n - j - 1) + 1) MOD (n - j) = 0`
  (LABEL_TAC "wrap") THENL
   [SUBGOAL_THEN `(n - j - 1) + 1 = n - j` SUBST1_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[MOD_REFL]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_split_right (q:num->A) j) (n - j)
      (n - j - 1) = (q (n - 1),q j)`
  (LABEL_TAC "chord") THENL
   [MATCH_MP_TAC CYCLIC_DART_SPLIT_RIGHT_CHORD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_split_right (q:num->A) j) (n - j) 0 =
    cyclic_dart q n j`
  (LABEL_TAC "first") THENL
   [MATCH_MP_TAC CYCLIC_DART_SPLIT_RIGHT_FIRST THEN
    ASM_REWRITE_TAC[];
    ASM_MESON_TAC[]]);;

let GRAPH_FACE_SUCCESSOR_SPLIT_LEFT_BOUNDARY = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !q:num->A. !n j i.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        simple_graph_cycle
          E1 (cyclic_split_left q n j) (j + 2) /\
        cyclic_face_successors
          E1 r1 (cyclic_split_left q n j) (j + 2) /\
        cyclic_face_successors
          E2 r2 (cyclic_split_right q j) (n - j) /\
        j + 2 < n /\
        INJ q (cyclic_indices n) (:A) /\
        V1 INTER V2 = {q j,q (n - 1)} /\
        {q j,q (n - 1)} IN E1 /\
        {q j,q (n - 1)} IN E2 /\
        i < j
        ==> graph_face_successor
             (E1 UNION E2)
             (graph_split_rotation V1 E1 E2 r1 r2
               (q j) (q (n - 1)))
             (cyclic_dart q n i) =
            cyclic_dart q n (i + 1)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph1 graph2 cycle1 successors1 successors2 bound injective overlap
    chord1 chord2 index" THEN
  USE_THEN "cycle1" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "left_large left_injective left_edges" THEN
  SUBGOAL_THEN
   `graph_face_successor E2 r2
      ((q:num->A) (n - 1),q j) = cyclic_dart q n j`
  (LABEL_TAC "right_after_chord") THENL
   [MATCH_MP_TAC CYCLIC_SPLIT_RIGHT_AFTER_CHORD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n i =
    cyclic_dart (cyclic_split_left q n j) (j + 2) i`
  (LABEL_TAC "left_source") THENL
   [MATCH_MP_TAC EQ_SYM THEN
    MATCH_MP_TAC CYCLIC_DART_SPLIT_LEFT_PREFIX THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_split_left (q:num->A) n j) (j + 2) j =
    (q j,q (n - 1))`
  (LABEL_TAC "left_chord") THENL
   [MATCH_MP_TAC CYCLIC_DART_SPLIT_LEFT_CHORD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(cyclic_dart (cyclic_split_left (q:num->A) n j) (j + 2) i =
      cyclic_dart (cyclic_split_left q n j) (j + 2) j)`
  (LABEL_TAC "left_distinct") THENL
   [MATCH_MP_TAC CYCLIC_DART_DISTINCT THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n i IN
    graph_darts E1 DELETE (q j,q (n - 1))`
  (LABEL_TAC "left_dart") THENL
   [REWRITE_TAC[IN_DELETE] THEN CONJ_TAC THENL
     [USE_THEN "left_source" (fun th -> REWRITE_TAC[th]) THEN
      MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DART THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor
      (E1 UNION E2:(A->bool)->bool)
      (graph_split_rotation (V1:A->bool) E1 E2 r1 r2
        (q j) (q (n - 1)))
      (cyclic_dart q n i) =
    if SND(cyclic_dart q n i) = q j then
      swap((q j,q (n - 1)),
           graph_face_successor E2 r2 (q (n - 1),q j))
        (graph_face_successor E1 r1 (cyclic_dart q n i))
    else graph_face_successor E1 r1 (cyclic_dart q n i)`
  (LABEL_TAC "split_successor") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
      `(q:num->A) j`; `q (n - 1):A`; `cyclic_dart q n i:A#A`]
    GRAPH_FACE_SUCCESSOR_SPLIT_LEFT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E1 r1 (cyclic_dart (q:num->A) n i) =
    cyclic_dart (cyclic_split_left q n j) (j + 2)
      ((i + 1) MOD (j + 2))`
  (LABEL_TAC "left_successor") THENL
   [USE_THEN "left_source" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "successors1" MP_TAC THEN
    REWRITE_TAC[cyclic_face_successors] THEN
    DISCH_THEN(MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n i = (q i,q (i + 1))`
  (LABEL_TAC "source_pair") THENL
   [MATCH_MP_TAC CYCLIC_DART_NOWRAP THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `i + 1 = j` THENL
   [SUBGOAL_THEN
     `SND(cyclic_dart (q:num->A) n i) = q j`
    (LABEL_TAC "whole_head") THENL
     [USE_THEN "source_pair" (fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[SND];
      ALL_TAC] THEN
    SUBGOAL_THEN `(i + 1) MOD (j + 2) = i + 1`
    (LABEL_TAC "left_next") THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "split_successor" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "whole_head" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "left_successor" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "left_next" (fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[SWAP_LEFT];
    SUBGOAL_THEN
     `~((q:num->A) (i + 1) = q j)`
    (LABEL_TAC "head_distinct") THENL
     [MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `i + 1`; `j:num`]
       CYCLIC_INDEX_IMAGES_EQ) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~(SND(cyclic_dart (q:num->A) n i) = q j)`
    (LABEL_TAC "whole_head") THENL
     [USE_THEN "source_pair" (fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[SND];
      ALL_TAC] THEN
    SUBGOAL_THEN `(i + 1) MOD (j + 2) = i + 1`
    (LABEL_TAC "left_next") THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `cyclic_dart (cyclic_split_left (q:num->A) n j) (j + 2)
        (i + 1) = cyclic_dart q n (i + 1)`
    (LABEL_TAC "left_target") THENL
     [MATCH_MP_TAC CYCLIC_DART_SPLIT_LEFT_PREFIX THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "split_successor" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "whole_head" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "left_successor" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "left_next" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "left_target" ACCEPT_TAC]);;

let GRAPH_FACE_SUCCESSOR_SPLIT_RIGHT_BOUNDARY = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !q:num->A. !n j i.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        simple_graph_cycle
          E2 (cyclic_split_right q j) (n - j) /\
        cyclic_face_successors
          E1 r1 (cyclic_split_left q n j) (j + 2) /\
        cyclic_face_successors
          E2 r2 (cyclic_split_right q j) (n - j) /\
        j + 2 < n /\
        INJ q (cyclic_indices n) (:A) /\
        V1 INTER V2 = {q j,q (n - 1)} /\
        {q j,q (n - 1)} IN E1 /\
        {q j,q (n - 1)} IN E2 /\
        j <= i /\ i < n - 1
        ==> graph_face_successor
             (E1 UNION E2)
             (graph_split_rotation V1 E1 E2 r1 r2
               (q j) (q (n - 1)))
             (cyclic_dart q n i) =
            cyclic_dart q n (i + 1)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph1 graph2 cycle2 successors1 successors2 bound injective overlap
    chord1 chord2 index_lower index_upper" THEN
  USE_THEN "cycle2" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "right_large right_injective right_edges" THEN
  SUBGOAL_THEN
   `graph_face_successor E1 r1
      ((q:num->A) j,q (n - 1)) = cyclic_dart q n (n - 1)`
  (LABEL_TAC "left_after_chord") THENL
   [MATCH_MP_TAC CYCLIC_SPLIT_LEFT_AFTER_CHORD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `j + ((i:num) - j) = i`
  (LABEL_TAC "source_index") THENL
   [MATCH_MP_TAC
    (ARITH_RULE `j <= (i:num) ==> j + (i - j) = i`) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_split_right (q:num->A) j) (n - j) (i - j) =
    cyclic_dart q n i`
  (LABEL_TAC "right_source_forward") THENL
   [MP_TAC(ISPECL
     [`q:num->A`; `n:num`; `j:num`; `(i:num) - j`]
     CYCLIC_DART_SPLIT_RIGHT_PREFIX) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n i =
    cyclic_dart (cyclic_split_right q j) (n - j) (i - j)`
  (LABEL_TAC "right_source") THENL
   [MATCH_MP_TAC EQ_SYM THEN
    USE_THEN "right_source_forward" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_split_right (q:num->A) j) (n - j)
      (n - j - 1) = (q (n - 1),q j)`
  (LABEL_TAC "right_chord") THENL
   [MATCH_MP_TAC CYCLIC_DART_SPLIT_RIGHT_CHORD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(cyclic_dart (cyclic_split_right (q:num->A) j) (n - j)
        (i - j) =
      cyclic_dart (cyclic_split_right q j) (n - j)
        (n - j - 1))`
  (LABEL_TAC "right_distinct") THENL
   [MATCH_MP_TAC CYCLIC_DART_DISTINCT THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n i IN
    graph_darts E2 DELETE (q (n - 1),q j)`
  (LABEL_TAC "right_dart") THENL
   [REWRITE_TAC[IN_DELETE] THEN CONJ_TAC THENL
     [USE_THEN "right_source" (fun th -> REWRITE_TAC[th]) THEN
      MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DART THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor
      (E1 UNION E2:(A->bool)->bool)
      (graph_split_rotation (V1:A->bool) E1 E2 r1 r2
        (q j) (q (n - 1)))
      (cyclic_dart q n i) =
    if SND(cyclic_dart q n i) = q (n - 1) then
      swap((q (n - 1),q j),
           graph_face_successor E1 r1 (q j,q (n - 1)))
        (graph_face_successor E2 r2 (cyclic_dart q n i))
    else graph_face_successor E2 r2 (cyclic_dart q n i)`
  (LABEL_TAC "split_successor") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
      `(q:num->A) j`; `q (n - 1):A`; `cyclic_dart q n i:A#A`]
    GRAPH_FACE_SUCCESSOR_SPLIT_RIGHT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E2 r2 (cyclic_dart (q:num->A) n i) =
    cyclic_dart (cyclic_split_right q j) (n - j)
      (((i - j) + 1) MOD (n - j))`
  (LABEL_TAC "right_successor") THENL
   [USE_THEN "right_source" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "successors2" MP_TAC THEN
    REWRITE_TAC[cyclic_face_successors] THEN
    DISCH_THEN(MP_TAC o SPEC `(i:num) - j`) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n i = (q i,q (i + 1))`
  (LABEL_TAC "source_pair") THENL
   [MATCH_MP_TAC CYCLIC_DART_NOWRAP THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `i + 1 = n - 1` THENL
   [SUBGOAL_THEN
     `SND(cyclic_dart (q:num->A) n i) = q (n - 1)`
    (LABEL_TAC "whole_head") THENL
     [USE_THEN "source_pair" (fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[SND];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `((i - j) + 1) MOD (n - j) = (i - j) + 1`
    (LABEL_TAC "right_next") THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(i - j) + 1 = n - j - 1`
    (LABEL_TAC "right_last") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "split_successor" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "whole_head" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "right_successor" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "right_next" (fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[SWAP_LEFT];
    SUBGOAL_THEN
     `~((q:num->A) (i + 1) = q (n - 1))`
    (LABEL_TAC "head_distinct") THENL
     [MP_TAC(ISPECL
      [`q:num->A`; `n:num`; `(i:num) + 1`; `(n:num) - 1`]
       CYCLIC_INDEX_IMAGES_EQ) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~(SND(cyclic_dart (q:num->A) n i) = q (n - 1))`
    (LABEL_TAC "whole_head") THENL
     [USE_THEN "source_pair" (fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[SND];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `((i - j) + 1) MOD (n - j) = (i - j) + 1`
    (LABEL_TAC "right_next") THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `j + ((i - j) + 1) = i + 1`
    (LABEL_TAC "target_index") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `cyclic_dart (cyclic_split_right (q:num->A) j) (n - j)
        ((i - j) + 1) = cyclic_dart q n (i + 1)`
    (LABEL_TAC "right_target") THENL
     [MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `j:num`; `((i:num) - j) + 1`]
       CYCLIC_DART_SPLIT_RIGHT_PREFIX) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    USE_THEN "split_successor" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "whole_head" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "right_successor" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "right_next" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "right_target" ACCEPT_TAC]);;

let GRAPH_FACE_SUCCESSOR_SPLIT_LAST_BOUNDARY = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !q:num->A. !n j.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        simple_graph_cycle
          E1 (cyclic_split_left q n j) (j + 2) /\
        cyclic_face_successors
          E1 r1 (cyclic_split_left q n j) (j + 2) /\
        0 < j /\ j + 2 < n /\
        INJ q (cyclic_indices n) (:A) /\
        V1 INTER V2 = {q j,q (n - 1)} /\
        {q j,q (n - 1)} IN E1 /\
        {q j,q (n - 1)} IN E2
        ==> graph_face_successor
             (E1 UNION E2)
             (graph_split_rotation V1 E1 E2 r1 r2
               (q j) (q (n - 1)))
             (cyclic_dart q n (n - 1)) =
            cyclic_dart q n 0`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph1 graph2 cycle1 successors1 jpositive bound injective overlap
    chord1 chord2" THEN
  USE_THEN "cycle1" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "left_large left_injective left_edges" THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_split_left (q:num->A) n j) (j + 2) (j + 1) =
    cyclic_dart q n (n - 1)`
  (LABEL_TAC "left_source_forward") THENL
   [MATCH_MP_TAC CYCLIC_DART_SPLIT_LEFT_LAST THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n (n - 1) =
    cyclic_dart (cyclic_split_left q n j) (j + 2) (j + 1)`
  (LABEL_TAC "left_source") THENL
   [MATCH_MP_TAC EQ_SYM THEN
    USE_THEN "left_source_forward" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_split_left (q:num->A) n j) (j + 2) j =
    (q j,q (n - 1))`
  (LABEL_TAC "left_chord") THENL
   [MATCH_MP_TAC CYCLIC_DART_SPLIT_LEFT_CHORD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(cyclic_dart (cyclic_split_left (q:num->A) n j) (j + 2) (j + 1) =
      cyclic_dart (cyclic_split_left q n j) (j + 2) j)`
  (LABEL_TAC "left_distinct") THENL
   [MATCH_MP_TAC CYCLIC_DART_DISTINCT THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n (n - 1) IN
    graph_darts E1 DELETE (q j,q (n - 1))`
  (LABEL_TAC "left_dart") THENL
   [REWRITE_TAC[IN_DELETE] THEN CONJ_TAC THENL
     [USE_THEN "left_source" (fun th -> REWRITE_TAC[th]) THEN
      MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DART THEN
      ASM_REWRITE_TAC[] THEN ARITH_TAC;
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor
      (E1 UNION E2:(A->bool)->bool)
      (graph_split_rotation (V1:A->bool) E1 E2 r1 r2
        (q j) (q (n - 1)))
      (cyclic_dart q n (n - 1)) =
    if SND(cyclic_dart q n (n - 1)) = q j then
      swap((q j,q (n - 1)),
           graph_face_successor E2 r2 (q (n - 1),q j))
        (graph_face_successor E1 r1 (cyclic_dart q n (n - 1)))
    else graph_face_successor E1 r1 (cyclic_dart q n (n - 1))`
  (LABEL_TAC "split_successor") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
      `(q:num->A) j`; `q (n - 1):A`;
      `cyclic_dart q n (n - 1):A#A`]
     GRAPH_FACE_SUCCESSOR_SPLIT_LEFT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E1 r1 (cyclic_dart (q:num->A) n (n - 1)) =
    cyclic_dart (cyclic_split_left q n j) (j + 2)
      (((j + 1) + 1) MOD (j + 2))`
  (LABEL_TAC "left_successor") THENL
   [USE_THEN "left_source" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "successors1" MP_TAC THEN
    REWRITE_TAC[cyclic_face_successors] THEN
    DISCH_THEN(MP_TAC o SPEC `(j:num) + 1`) THEN
    ANTS_TAC THENL
     [ARITH_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `((j + 1) + 1) MOD (j + 2) = 0`
  (LABEL_TAC "left_wrap") THENL
   [SUBGOAL_THEN `(j + 1) + 1 = j + 2` SUBST1_TAC THENL
     [ARITH_TAC;
      REWRITE_TAC[MOD_REFL]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_split_left (q:num->A) n j) (j + 2) 0 =
    cyclic_dart q n 0`
  (LABEL_TAC "left_target") THENL
   [MATCH_MP_TAC CYCLIC_DART_SPLIT_LEFT_PREFIX THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n (n - 1) = (q (n - 1),q 0)`
  (LABEL_TAC "source_pair") THENL
   [MATCH_MP_TAC CYCLIC_DART_LAST THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((q:num->A) 0 = q j)`
  (LABEL_TAC "head_distinct") THENL
   [DISCH_THEN(LABEL_TAC "head_equal") THEN
    USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    DISCH_THEN(MP_TAC o SPECL [`0`; `j:num`]) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(SND(cyclic_dart (q:num->A) n (n - 1)) = q j)`
  (LABEL_TAC "whole_head") THENL
   [USE_THEN "source_pair" (fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[SND];
    ALL_TAC] THEN
  USE_THEN "split_successor" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "whole_head" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "left_successor" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "left_wrap" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "left_target" ACCEPT_TAC);;

let CYCLIC_SPLIT_LEFT_WHOLE_NEXT = prove
 (`!i j n:num.
        i < j /\ j + 2 < n
        ==> (i + 1) MOD n = i + 1`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC);;

let CYCLIC_SPLIT_RIGHT_WHOLE_NEXT = prove
 (`!i n:num.
        i < n - 1
        ==> (i + 1) MOD n = i + 1`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC);;

let CYCLIC_INDEX_LAST_CASE = prove
 (`!i n:num.
        i < n /\ ~(i < n - 1)
        ==> i = n - 1`,
  ARITH_TAC);;

let CYCLIC_FACE_SUCCESSORS_SPLIT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !q:num->A. !n j.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        simple_graph_cycle
          E1 (cyclic_split_left q n j) (j + 2) /\
        simple_graph_cycle
          E2 (cyclic_split_right q j) (n - j) /\
        cyclic_face_successors
          E1 r1 (cyclic_split_left q n j) (j + 2) /\
        cyclic_face_successors
          E2 r2 (cyclic_split_right q j) (n - j) /\
        0 < j /\ j + 2 < n /\
        INJ q (cyclic_indices n) (:A) /\
        V1 INTER V2 = {q j,q (n - 1)} /\
        {q j,q (n - 1)} IN E1 /\
        {q j,q (n - 1)} IN E2
        ==> cyclic_face_successors
             (E1 UNION E2)
             (graph_split_rotation V1 E1 E2 r1 r2
               (q j) (q (n - 1)))
             q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph1 graph2 cycle1 cycle2 successors1 successors2 jpositive bound
    injective overlap chord1 chord2" THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
  ASM_CASES_TAC `(i:num) < j` THENL
   [FIRST_X_ASSUM(LABEL_TAC "left_index") THEN
    SUBGOAL_THEN `((i:num) + 1) MOD n = i + 1`
    SUBST1_TAC THENL
     [(fun (asl,_ as g) ->
        let result = MATCH_MP
          (SPECL [`i:num`; `j:num`; `n:num`]
            CYCLIC_SPLIT_LEFT_WHOLE_NEXT)
          (CONJ (assoc "left_index" asl) (assoc "bound" asl)) in
        ACCEPT_TAC result g);
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
      `q:num->A`; `n:num`; `j:num`; `i:num`]
     GRAPH_FACE_SUCCESSOR_SPLIT_LEFT_BOUNDARY) THEN
    ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "not_left") THEN
    ASM_CASES_TAC `(i:num) < n - 1` THENL
     [FIRST_X_ASSUM(LABEL_TAC "right_upper") THEN
      SUBGOAL_THEN `((i:num) + 1) MOD n = i + 1`
      SUBST1_TAC THENL
       [MATCH_MP_TAC CYCLIC_SPLIT_RIGHT_WHOLE_NEXT THEN
        USE_THEN "right_upper" ACCEPT_TAC;
        ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `V2:A->bool`;
        `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
        `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
        `q:num->A`; `n:num`; `j:num`; `i:num`]
       GRAPH_FACE_SUCCESSOR_SPLIT_RIGHT_BOUNDARY) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      FIRST_X_ASSUM(LABEL_TAC "not_before_last") THEN
      SUBGOAL_THEN `(i:num) = n - 1` SUBST_ALL_TAC THENL
       [(fun (asl,_ as g) ->
          let result = MATCH_MP
            (SPECL [`i:num`; `n:num`] CYCLIC_INDEX_LAST_CASE)
            (CONJ
              (assoc "index" asl)
              (assoc "not_before_last" asl)) in
          ACCEPT_TAC result g);
        ALL_TAC] THEN
      SUBGOAL_THEN `(((n:num) - 1) + 1) MOD n = 0`
      SUBST1_TAC THENL
       [SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
         [ASM_ARITH_TAC;
          REWRITE_TAC[MOD_REFL]];
        ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `V2:A->bool`;
        `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
        `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
        `q:num->A`; `n:num`; `j:num`]
       GRAPH_FACE_SUCCESSOR_SPLIT_LAST_BOUNDARY) THEN
      ASM_REWRITE_TAC[]]]);;

let BOUNDARY_EULER_ROTATION_SPLIT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !q:num->A. !n j.
        simple_graph_cycle
          E1 (cyclic_split_left q n j) (j + 2) /\
        simple_graph_cycle
          E2 (cyclic_split_right q j) (n - j) /\
        boundary_euler_rotation
          V1 E1 (cyclic_split_left q n j) (j + 2) r1 /\
        boundary_euler_rotation
          V2 E2 (cyclic_split_right q j) (n - j) r2 /\
        0 < j /\ j + 2 < n /\
        INJ q (cyclic_indices n) (:A) /\
        V1 INTER V2 = {q j,q (n - 1)} /\
        {q j,q (n - 1)} IN E1 /\
        {q j,q (n - 1)} IN E2
        ==> boundary_euler_rotation
             (V1 UNION V2) (E1 UNION E2) q n
             (graph_split_rotation V1 E1 E2 r1 r2
               (q j) (q (n - 1)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "cycle1 cycle2 boundary1 boundary2 jpositive bound injective overlap
    chord1 chord2" THEN
  USE_THEN "cycle1" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "left_large left_injective left_edges" THEN
  USE_THEN "cycle2" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "right_large right_injective right_edges" THEN
  USE_THEN "boundary1" MP_TAC THEN
  REWRITE_TAC[boundary_euler_rotation] THEN
  INTRO_TAC "euler1 outer1" THEN
  USE_THEN "boundary2" MP_TAC THEN
  REWRITE_TAC[boundary_euler_rotation] THEN
  INTRO_TAC "euler2 outer2" THEN
  USE_THEN "euler1" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph1 rotation1 formula1" THEN
  USE_THEN "euler2" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph2 rotation2 formula2" THEN
  SUBGOAL_THEN
   `cyclic_face_successors
      E1 r1 (cyclic_split_left (q:num->A) n j) (j + 2)`
  (LABEL_TAC "successors1") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`;
      `cyclic_split_left (q:num->A) n j`; `(j:num) + 2`;
      `r1:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_IMP_CYCLIC_FACE_SUCCESSORS) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_face_successors
      E2 r2 (cyclic_split_right (q:num->A) j) (n - j)`
  (LABEL_TAC "successors2") THENL
   [MATCH_MP_TAC(ISPECL
     [`V2:A->bool`; `E2:(A->bool)->bool`;
      `cyclic_split_right (q:num->A) j`; `(n:num) - j`;
      `r2:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_IMP_CYCLIC_FACE_SUCCESSORS) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_split_left (q:num->A) n j) (j + 2) j =
    (q j,q (n - 1))`
  (LABEL_TAC "left_chord_dart") THENL
   [MATCH_MP_TAC CYCLIC_DART_SPLIT_LEFT_CHORD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (cyclic_split_right (q:num->A) j) (n - j)
      (n - j - 1) = (q (n - 1),q j)`
  (LABEL_TAC "right_chord_dart") THENL
   [MATCH_MP_TAC CYCLIC_DART_SPLIT_RIGHT_CHORD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(restricted_permutation (r2:(A#A)->A#A)
       (outgoing_darts (E2:(A->bool)->bool) ((q:num->A) j))
       (q j,q (n - 1)) = (q j,q (n - 1)))`
  (LABEL_TAC "left_nonfixed") THENL
   [MP_TAC(ISPECL
     [`V2:A->bool`; `E2:(A->bool)->bool`;
      `cyclic_split_right (q:num->A) j`; `(n:num) - j`;
      `r2:(A#A)->A#A`; `(n:num) - j - 1`]
     BOUNDARY_EULER_ROTATION_REVERSE_DART_NONFIXED) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ASM_REWRITE_TAC[REVERSE_DART_PAIR; SND]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(restricted_permutation (r1:(A#A)->A#A)
       (outgoing_darts (E1:(A->bool)->bool) ((q:num->A) (n - 1)))
       (q (n - 1),q j) = (q (n - 1),q j))`
  (LABEL_TAC "right_nonfixed") THENL
   [MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`;
      `cyclic_split_left (q:num->A) n j`; `(j:num) + 2`;
      `r1:(A#A)->A#A`; `j:num`]
     BOUNDARY_EULER_ROTATION_REVERSE_DART_NONFIXED) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ARITH_TAC;
      ASM_REWRITE_TAC[REVERSE_DART_PAIR; SND]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `euler_planar_rotation
      (V1 UNION V2:A->bool) (E1 UNION E2)
      (graph_split_rotation V1 E1 E2 r1 r2
        (q j) (q (n - 1)))`
  (LABEL_TAC "euler") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
      `(q:num->A) j`; `q (n - 1):A`]
     EULER_PLANAR_ROTATION_SPLIT) THEN
    ASM_REWRITE_TAC[euler_planar_rotation];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_face_successors
      (E1 UNION E2:(A->bool)->bool)
      (graph_split_rotation (V1:A->bool) E1 E2 r1 r2
        (q j) (q (n - 1))) q n`
  (LABEL_TAC "successors") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
      `q:num->A`; `n:num`; `j:num`]
     CYCLIC_FACE_SUCCESSORS_SPLIT) THEN
    ASM_REWRITE_TAC[simple_graph_cycle];
    ALL_TAC] THEN
  REWRITE_TAC[GSYM euler_planar_rotation] THEN
  REWRITE_TAC[GSYM boundary_euler_rotation] THEN
  MATCH_MP_TAC(ISPECL
   [`V1 UNION V2:A->bool`; `E1 UNION E2:(A->bool)->bool`;
    `q:num->A`; `n:num`;
    `graph_split_rotation (V1:A->bool) E1 E2 r1 r2
      (q j) (q (n - 1)):(A#A)->A#A`]
   BOUNDARY_EULER_ROTATION_OF_CYCLIC_FACE_SUCCESSORS) THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* Euler rotations for recursively triangulated disks.                       *)
(* ------------------------------------------------------------------------- *)

let cyclic_delete_last_chain_index = new_definition
 `cyclic_delete_last_chain_index n k r =
    if r = 0 then n - 2
    else if r = k + 1 then 0
    else n - 2 + r`;;

let CYCLIC_DELETE_LAST_CHAIN_INDEX_BOUND = prove
 (`!n k r.
        3 <= n /\ r < k + 2
        ==> cyclic_delete_last_chain_index n k r < n - 1 + k`,
  REPEAT GEN_TAC THEN INTRO_TAC "nlarge index" THEN
  REWRITE_TAC[cyclic_delete_last_chain_index] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[] THENL
   [ASM_ARITH_TAC;
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]);;

let CYCLIC_DELETE_LAST_CHAIN_INDEX_VALUE = prove
 (`!q w:num->A. !n k r.
        3 <= n /\ r < k + 2 /\
        w 0 = q (n - 2) /\ w (k + 1) = q 0
        ==> cyclic_delete_last q w n
             (cyclic_delete_last_chain_index n k r) = w r`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "nlarge index first last" THEN
  REWRITE_TAC[cyclic_delete_last_chain_index] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[] THENL
   [MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN ASM_ARITH_TAC;
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THENL
     [MATCH_MP_TAC CYCLIC_DELETE_LAST_FIRST THEN
      USE_THEN "nlarge" ACCEPT_TAC;
      MATCH_MP_TAC CYCLIC_DELETE_LAST_CHAIN THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]]);;

let CYCLIC_DELETE_LAST_CHAIN_INDEX_INJ = prove
 (`!n k.
        3 <= n
        ==> INJ (cyclic_delete_last_chain_index n k)
                (cyclic_indices (k + 2)) (:num)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "nlarge") THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES;
              cyclic_delete_last_chain_index] THEN
  MAP_EVERY X_GEN_TAC [`r:num`; `s:num`] THEN
  INTRO_TAC "r_index s_index equal" THEN
  REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]) THEN ASM_ARITH_TAC);;

let INJ_CYCLIC_DELETE_LAST_IMP_INJ_CHAIN = prove
 (`!q w:num->A. !n k.
        3 <= n /\
        INJ (cyclic_delete_last q w n)
            (cyclic_indices (n - 1 + k)) (:A) /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0
        ==> INJ w (cyclic_indices (k + 2)) (:A)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "nlarge old_injective first last" THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
  MAP_EVERY X_GEN_TAC [`r:num`; `s:num`] THEN
  INTRO_TAC "r_index s_index equal" THEN
  SUBGOAL_THEN
   `cyclic_delete_last_chain_index n k r < n - 1 + k /\
    cyclic_delete_last_chain_index n k s < n - 1 + k`
  (CONJUNCTS_THEN2 (LABEL_TAC "old_r_index")
    (LABEL_TAC "old_s_index")) THENL
   [CONJ_TAC THEN MATCH_MP_TAC CYCLIC_DELETE_LAST_CHAIN_INDEX_BOUND THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_delete_last (q:num->A) (w:num->A) n
      (cyclic_delete_last_chain_index n k r) = w r /\
    cyclic_delete_last q w n
      (cyclic_delete_last_chain_index n k s) = w s`
  (CONJUNCTS_THEN2 (LABEL_TAC "old_r_value")
    (LABEL_TAC "old_s_value")) THENL
   [CONJ_TAC THEN
    MATCH_MP_TAC CYCLIC_DELETE_LAST_CHAIN_INDEX_VALUE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_delete_last_chain_index n k r =
    cyclic_delete_last_chain_index n k s`
  (LABEL_TAC "old_indices_equal") THENL
   [USE_THEN "old_injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    DISCH_THEN(MATCH_MP_TAC o SPECL
     [`cyclic_delete_last_chain_index n k r`;
      `cyclic_delete_last_chain_index n k s`]) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
      ["old_r_value"; "old_s_value"; "equal"] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`n:num`; `k:num`]
    CYCLIC_DELETE_LAST_CHAIN_INDEX_INJ) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

let SIMPLE_GRAPH_CYCLE_INSERT_LAST_VERTEX = prove
 (`!E:(A->bool)->bool. !q w:num->A. !n k.
        simple_graph_cycle
          E (cyclic_delete_last q w n) (n - 1 + k) /\
        3 <= n /\
        INJ q (cyclic_indices n) (:A) /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0
        ==> simple_graph_cycle
             (IMAGE (\u:A. {q (n - 1),u})
               (cyclic_vertices w (k + 2)) UNION E)
             q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "old_cycle nlarge injective first last" THEN
  USE_THEN "old_cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "old_large old_injective old_edges" THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "nlarge" ACCEPT_TAC;
    USE_THEN "injective" ACCEPT_TAC;
    REWRITE_TAC[SUBSET; IN_CYCLIC_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN
    INTRO_TAC "@i. index edge" THEN
    USE_THEN "edge" SUBST1_TAC THEN
    ASM_CASES_TAC `(i:num) < n - 2` THENL
     [SUBGOAL_THEN `(i + 1) MOD n = i + 1`
      (LABEL_TAC "new_next") THENL
       [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(i + 1) MOD (n - 1 + k) = i + 1`
      (LABEL_TAC "old_next") THENL
       [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `cyclic_delete_last (q:num->A) w n i = q i /\
        cyclic_delete_last q w n (i + 1) = q (i + 1)`
      (CONJUNCTS_THEN2 (LABEL_TAC "old_i_value")
        (LABEL_TAC "old_next_value")) THENL
       [CONJ_TAC THEN MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN
        ASM_ARITH_TAC;
        ALL_TAC] THEN
      REWRITE_TAC[IN_UNION] THEN DISJ2_TAC THEN
      USE_THEN "old_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      REWRITE_TAC[IN_CYCLIC_EDGES] THEN
      EXISTS_TAC `i:num` THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ASM_CASES_TAC `(i:num) = n - 2` THENL
       [FIRST_X_ASSUM SUBST_ALL_TAC THEN
        SUBGOAL_THEN `((n - 2) + 1) MOD n = n - 1`
        (LABEL_TAC "next") THENL
         [TRANS_TAC EQ_TRANS `(n - 2) + 1` THEN CONJ_TAC THENL
           [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
            ASM_ARITH_TAC];
          ALL_TAC] THEN
        ASM_REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
        REWRITE_TAC[IN_IMAGE] THEN
        EXISTS_TAC `(w:num->A) 0` THEN
        CONJ_TAC THENL
         [ASM_REWRITE_TAC[] THEN SET_TAC[];
          REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
          EXISTS_TAC `0` THEN ARITH_TAC];
        SUBGOAL_THEN `(i:num) = n - 1` SUBST_ALL_TAC THENL
         [ASM_ARITH_TAC;
          ALL_TAC] THEN
        SUBGOAL_THEN `((n - 1) + 1) MOD n = 0`
        (LABEL_TAC "wrap") THENL
         [SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
           [ASM_ARITH_TAC;
            REWRITE_TAC[MOD_REFL]];
          ALL_TAC] THEN
        ASM_REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
        REWRITE_TAC[IN_IMAGE] THEN
        EXISTS_TAC `(w:num->A) (k + 1)` THEN
        CONJ_TAC THENL
         [ASM_REWRITE_TAC[];
          REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
          EXISTS_TAC `k + 1` THEN ARITH_TAC]]]]);;

let SIMPLE_GRAPH_CYCLE_UNION_SPLIT = prove
 (`!E1 E2:(A->bool)->bool. !q:num->A. !n j.
        simple_graph_cycle
          E1 (cyclic_split_left q n j) (j + 2) /\
        simple_graph_cycle
          E2 (cyclic_split_right q j) (n - j) /\
        0 < j /\ j + 2 < n /\
        INJ q (cyclic_indices n) (:A)
        ==> simple_graph_cycle (E1 UNION E2) q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "cycle1 cycle2 jpositive bound injective" THEN
  USE_THEN "cycle1" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "left_large left_injective left_edges" THEN
  USE_THEN "cycle2" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "right_large right_injective right_edges" THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  REPEAT CONJ_TAC THENL
   [ASM_ARITH_TAC;
    USE_THEN "injective" ACCEPT_TAC;
    REWRITE_TAC[SUBSET; IN_CYCLIC_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN
    INTRO_TAC "@i. index edge" THEN
    USE_THEN "edge" SUBST1_TAC THEN
    ASM_CASES_TAC `(i:num) < j` THENL
     [FIRST_X_ASSUM(LABEL_TAC "left_index") THEN
      SUBGOAL_THEN
       `{cyclic_split_left (q:num->A) n j i,
         cyclic_split_left q n j ((i + 1) MOD (j + 2))} =
        {q i,q ((i + 1) MOD n)}`
      (LABEL_TAC "left_edge") THENL
       [MP_TAC(ISPECL
         [`q:num->A`; `n:num`; `j:num`; `i:num`]
         CYCLIC_DART_SPLIT_LEFT_PREFIX) THEN
        ASM_REWRITE_TAC[] THEN
        DISCH_THEN(MP_TAC o
          AP_TERM `dart_edge:A#A->A->bool`) THEN
        REWRITE_TAC[cyclic_dart; DART_EDGE_PAIR];
        ALL_TAC] THEN
      REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
      USE_THEN "left_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      REWRITE_TAC[IN_CYCLIC_EDGES] THEN
      EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(ARITH_RULE `i < j ==> i < j + 2`) THEN
      USE_THEN "left_index" ACCEPT_TAC;
      FIRST_X_ASSUM(LABEL_TAC "not_left") THEN
      ASM_CASES_TAC `(i:num) < n - 1` THENL
       [FIRST_X_ASSUM(LABEL_TAC "right_upper") THEN
        SUBGOAL_THEN `j + ((i:num) - j) = i`
        (LABEL_TAC "source_index") THENL
         [MATCH_MP_TAC
           (ARITH_RULE `~((i:num) < j) ==> j + (i - j) = i`) THEN
          USE_THEN "not_left" ACCEPT_TAC;
          ALL_TAC] THEN
        SUBGOAL_THEN
         `{cyclic_split_right (q:num->A) j (i - j),
           cyclic_split_right q j (((i - j) + 1) MOD (n - j))} =
          {q i,q ((i + 1) MOD n)}`
        (LABEL_TAC "right_edge") THENL
         [MP_TAC(ISPECL
           [`q:num->A`; `n:num`; `j:num`; `(i:num) - j`]
           CYCLIC_DART_SPLIT_RIGHT_PREFIX) THEN
          ANTS_TAC THENL
           [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
            ASM_REWRITE_TAC[] THEN
            DISCH_THEN(MP_TAC o
              AP_TERM `dart_edge:A#A->A->bool`) THEN
            REWRITE_TAC[cyclic_dart; DART_EDGE_PAIR]];
          ALL_TAC] THEN
        REWRITE_TAC[IN_UNION] THEN DISJ2_TAC THEN
        USE_THEN "right_edges"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        REWRITE_TAC[IN_CYCLIC_EDGES] THEN
        EXISTS_TAC `(i:num) - j` THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        SUBGOAL_THEN `(i:num) = n - 1` SUBST_ALL_TAC THENL
         [ASM_ARITH_TAC;
          ALL_TAC] THEN
        SUBGOAL_THEN
         `{cyclic_split_left (q:num->A) n j (j + 1),
           cyclic_split_left q n j (((j + 1) + 1) MOD (j + 2))} =
          {q (n - 1),q (((n - 1) + 1) MOD n)}`
        (LABEL_TAC "last_edge") THENL
         [MP_TAC(ISPECL [`q:num->A`; `n:num`; `j:num`]
           CYCLIC_DART_SPLIT_LEFT_LAST) THEN
          ASM_REWRITE_TAC[] THEN
          DISCH_THEN(MP_TAC o
            AP_TERM `dart_edge:A#A->A->bool`) THEN
          REWRITE_TAC[cyclic_dart; DART_EDGE_PAIR];
          ALL_TAC] THEN
        REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
        USE_THEN "left_edges"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        REWRITE_TAC[IN_CYCLIC_EDGES] THEN
        EXISTS_TAC `(j:num) + 1` THEN
        ASM_REWRITE_TAC[] THEN ARITH_TAC]]]);;

let RECURSIVE_TRIANGULATED_DISK_BOUNDARY_EULER_ROTATION = prove
 (`!V E q:num->A. !n.
        recursive_triangulated_disk V E q n
        ==> simple_graph_cycle E q n /\
            ?r:(A#A)->A#A.
              boundary_euler_rotation V E q n r`,
  MATCH_MP_TAC recursive_triangulated_disk_INDUCT THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `q:num->A` THEN
    DISCH_THEN(LABEL_TAC "injective") THEN
    CONJ_TAC THENL
     [REWRITE_TAC[simple_graph_cycle; SUBSET_REFL] THEN
      ASM_REWRITE_TAC[] THEN ARITH_TAC;
      MATCH_MP_TAC BOUNDARY_EULER_TRIANGLE_ROTATION_EXISTS THEN
      USE_THEN "injective" ACCEPT_TAC];
    MAP_EVERY X_GEN_TAC
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
      `n:num`; `k:num`; `w:num->A`] THEN
    INTRO_TAC
     "(old_cycle @r. old_boundary) nlarge injective fresh neighbors
      first last" THEN
    USE_THEN "old_cycle"
     (MP_TAC o REWRITE_RULE[simple_graph_cycle]) THEN
    INTRO_TAC "old_large old_injective old_edges" THEN
    SUBGOAL_THEN
     `INJ (w:num->A) (cyclic_indices (k + 2)) (:A)`
    (LABEL_TAC "neighbor_injective") THENL
     [MATCH_MP_TAC(ISPECL
       [`q:num->A`; `w:num->A`; `n:num`; `k:num`]
       INJ_CYCLIC_DELETE_LAST_IMP_INJ_CHAIN) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_INSERT_LAST_VERTEX THEN
      ASM_REWRITE_TAC[simple_graph_cycle];
      EXISTS_TAC
       `fan_rotation ((q:num->A) (n - 1)) w
          (q (n - 3),q (n - 2)) r (k + 1)` THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `q:num->A`; `w:num->A`; `n:num`; `k:num`;
        `r:(A#A)->A#A`]
       BOUNDARY_EULER_ROTATION_CYCLIC_FAN) THEN
      ASM_REWRITE_TAC[simple_graph_cycle]];
    MAP_EVERY X_GEN_TAC
     [`V1:A->bool`; `E1:(A->bool)->bool`;
      `V2:A->bool`; `E2:(A->bool)->bool`;
      `q:num->A`; `n:num`; `j:num`] THEN
    INTRO_TAC
     "(cycle1 @r1. boundary1) (cycle2 @r2. boundary2)
      jpositive bound injective overlap chord1 chord2" THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
        `q:num->A`; `n:num`; `j:num`]
       SIMPLE_GRAPH_CYCLE_UNION_SPLIT) THEN
      ASM_REWRITE_TAC[];
      EXISTS_TAC
       `graph_split_rotation (V1:A->bool) E1 E2 r1 r2
          (q j) (q (n - 1))` THEN
      MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `V2:A->bool`;
        `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
        `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
        `q:num->A`; `n:num`; `j:num`]
       BOUNDARY_EULER_ROTATION_SPLIT) THEN
      ASM_REWRITE_TAC[]]]);;

let RECURSIVE_TRIANGULATED_DISK_BOUNDARY_EULER_ROTATION_EXISTS = prove
 (`!V E q:num->A. !n.
        recursive_triangulated_disk V E q n
        ==> ?r:(A#A)->A#A.
              boundary_euler_rotation V E q n r`,
  MESON_TAC[RECURSIVE_TRIANGULATED_DISK_BOUNDARY_EULER_ROTATION]);;

(* ------------------------------------------------------------------------- *)
(* Cardinal bookkeeping and cyclic rerooting for recursive disks.            *)
(* ------------------------------------------------------------------------- *)

let FINITE_SIMPLE_GRAPH_INSERT_STAR_CARD = prove
 (`!V:A->bool. !E:(A->bool)->bool. !v N.
        finite_simple_graph V E /\
        ~(v IN V) /\
        N SUBSET V
        ==> CARD(v INSERT V) = CARD V + 1 /\
            CARD(IMAGE (\u:A. {v,u}) N UNION E) = CARD N + CARD E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph fresh neighbors" THEN
  SUBGOAL_THEN `FINITE(V:A->bool) /\ FINITE(E:(A->bool)->bool)`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_vertices")
    (LABEL_TAC "finite_edges")) THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(N:A->bool)` (LABEL_TAC "finite_neighbors") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(IMAGE (\u:A. {v,u}) N) = CARD(N:A->bool)`
  (LABEL_TAC "star_card") THENL
   [MATCH_MP_TAC CARD_IMAGE_INJ THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN
    INTRO_TAC "u_neighbor w_neighbor same_edge" THEN
    SUBGOAL_THEN `(u:A) IN V /\ (w:A) IN V`
    (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex") (LABEL_TAC "w_vertex")) THENL
     [CONJ_TAC THEN USE_THEN "neighbors"
       (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(SET_RULE
       `u IN V /\ w IN V /\ ~(v IN V) /\ {v,u} = {v,w}
        ==> u = w`) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (\u:A. {v,u}) N INTER E = ({}:(A->bool)->bool)`
  (LABEL_TAC "disjoint") THENL
   [REWRITE_TAC[EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    X_GEN_TAC `e:A->bool` THEN
    INTRO_TAC "star edge" THEN
    USE_THEN "star" MP_TAC THEN
    REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@u. edge_pair u_neighbor" THEN
    USE_THEN "edge_pair" SUBST_ALL_TAC THEN
    SUBGOAL_THEN `({v:A,u}:A->bool) SUBSET V`
    (LABEL_TAC "edge_vertices") THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
      USE_THEN "fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "edge_vertices"
       (MP_TAC o SPEC `v:A` o REWRITE_RULE[SUBSET]) THEN
      REWRITE_TAC[IN_INSERT]];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [ASM_SIMP_TAC[CARD_CLAUSES] THEN ARITH_TAC;
    MP_TAC(ISPECL
     [`IMAGE (\u:A. {v,u}) N`; `E:(A->bool)->bool`]
     CARD_UNION) THEN
    ASM_SIMP_TAC[FINITE_IMAGE] THEN
    USE_THEN "star_card" (fun th -> REWRITE_TAC[th])]);;

let FINITE_SIMPLE_GRAPH_SPLIT_CARD = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u v.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2
        ==> CARD(V1 UNION V2) + 2 = CARD V1 + CARD V2 /\
            CARD(E1 UNION E2) + 1 = CARD E1 + CARD E2`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 overlap chord1 chord2" THEN
  SUBGOAL_THEN
   `FINITE(V1:A->bool) /\ FINITE(E1:(A->bool)->bool) /\
    FINITE(V2:A->bool) /\ FINITE(E2:(A->bool)->bool)`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_v1")
   (CONJUNCTS_THEN2 (LABEL_TAC "finite_e1")
    (CONJUNCTS_THEN2 (LABEL_TAC "finite_v2")
     (LABEL_TAC "finite_e2")))) THENL
   [MAP_EVERY (fun name -> USE_THEN name MP_TAC) ["graph1"; "graph2"] THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) = v)` (LABEL_TAC "distinct") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_SHARED_EDGE_DISTINCT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(V1 INTER V2:A->bool) = 2`
  (LABEL_TAC "vertex_inter_card") THENL
   [USE_THEN "overlap" (fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[CARD_CLAUSES; FINITE_INSERT; FINITE_SING;
                 CARD_SING; IN_SING] THEN
    ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `E1 INTER E2 = {{u:A,v}}`
  (LABEL_TAC "edge_inter") THENL
   [MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_INTER; IN_SING] THEN
      X_GEN_TAC `e:A->bool` THEN INTRO_TAC "edge1 edge2" THEN
      MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`; `e:A->bool`]
       FINITE_SIMPLE_GRAPH_EDGE) THEN
      ASM_REWRITE_TAC[] THEN
      INTRO_TAC "@a b. a1 b1 ab edge_pair" THEN
      MP_TAC(ISPECL
       [`V2:A->bool`; `E2:(A->bool)->bool`; `e:A->bool`]
       FINITE_SIMPLE_GRAPH_EDGE) THEN
      ASM_REWRITE_TAC[] THEN
      INTRO_TAC "@c d. c2 d2 cd edge_pair2" THEN
      USE_THEN "edge_pair" SUBST1_TAC THEN
      MATCH_MP_TAC(SET_RULE
       `V1 INTER V2 = {u,v} /\
        a IN V1 /\ b IN V1 /\ c IN V2 /\ d IN V2 /\
        {a,b} = {c,d} /\ ~(a = b)
        ==> {a,b} = {u,v}`) THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[SUBSET; IN_SING; IN_INTER] THEN
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(E1 INTER E2:(A->bool)->bool) = 1`
  (LABEL_TAC "edge_inter_card") THENL
   [USE_THEN "edge_inter" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[CARD_SING];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`V1:A->bool`; `V2:A->bool`]
   CARD_UNION_ADD_INTER_FINITE) THEN
  MP_TAC(ISPECL [`E1:(A->bool)->bool`; `E2:(A->bool)->bool`]
   CARD_UNION_ADD_INTER_FINITE) THEN
  ASM_REWRITE_TAC[] THEN ARITH_TAC);;

let RECURSIVE_TRIANGULATED_DISK_EDGE_COUNT = prove
 (`!V E q:num->A. !n.
        recursive_triangulated_disk V E q n
        ==> CARD E + n + 3 = 3 * CARD V`,
  SUBGOAL_THEN
   `!V E q:num->A. !n.
        recursive_triangulated_disk V E q n
        ==> finite_simple_graph V E /\
            INJ q (cyclic_indices n) (:A) /\
            CARD E + n + 3 = 3 * CARD V`
  MP_TAC THENL
   [MATCH_MP_TAC
     (BETA_RULE(SPEC
       `\(V:A->bool) (E:(A->bool)->bool) (q:num->A) n.
          finite_simple_graph V E /\
          INJ q (cyclic_indices n) (:A) /\
          CARD E + n + 3 = 3 * CARD V`
       recursive_triangulated_disk_INDUCT)) THEN
    REPEAT CONJ_TAC THENL
     [X_GEN_TAC `q:num->A` THEN DISCH_THEN(LABEL_TAC "injective") THEN
      SUBGOAL_THEN
       `~((q:num->A) 0 = q 1) /\
        ~(q 1 = q 2) /\
        ~(q 2 = q 0)`
      (CONJUNCTS_THEN2 (LABEL_TAC "q01")
       (CONJUNCTS_THEN2 (LABEL_TAC "q12") (LABEL_TAC "q20"))) THENL
       [REPEAT CONJ_TAC THENL
         [DISCH_THEN(LABEL_TAC "same") THEN
          USE_THEN "injective"
           (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
          DISCH_THEN(MP_TAC o SPECL [`0`; `1`]) THEN
          ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ARITH_TAC;
          DISCH_THEN(LABEL_TAC "same") THEN
          USE_THEN "injective"
           (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
          DISCH_THEN(MP_TAC o SPECL [`1`; `2`]) THEN
          ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ARITH_TAC;
          DISCH_THEN(LABEL_TAC "same") THEN
          USE_THEN "injective"
           (MP_TAC o CONJUNCT2 o REWRITE_RULE[INJ]) THEN
          DISCH_THEN(MP_TAC o SPECL [`2`; `0`]) THEN
          ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ARITH_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `CARD(cyclic_vertices (q:num->A) 3) = 3`
      (LABEL_TAC "vertices") THENL
       [MATCH_MP_TAC CARD_CYCLIC_VERTICES THEN
        USE_THEN "injective" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `CARD(cyclic_edges (q:num->A) 3) = 3`
      (LABEL_TAC "edges") THENL
       [SUBGOAL_THEN `(cyclic_edges (q:num->A) 3) HAS_SIZE 3`
        MP_TAC THENL
         [REWRITE_TAC[CYCLIC_EDGES_3] THEN
          REWRITE_TAC[HAS_SIZE_CONV
           `({{q 0,q 1},{q 1,q 2},{q 2,q 0}}:(A->bool)->bool)
             HAS_SIZE 3`] THEN
          MAP_EVERY EXISTS_TAC
           [`{(q:num->A) 0,q 1}`;
            `{(q:num->A) 1,q 2}`;
            `{(q:num->A) 2,q 0}`] THEN
          ASM SET_TAC[];
          REWRITE_TAC[HAS_SIZE] THEN MESON_TAC[]];
        ALL_TAC] THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL
         [`cyclic_edges (q:num->A) 3`; `q:num->A`; `3`]
         FINITE_SIMPLE_GRAPH_CYCLIC) THEN
        REWRITE_TAC[simple_graph_cycle; SUBSET_REFL] THEN
        ASM_REWRITE_TAC[] THEN ARITH_TAC;
        USE_THEN "injective" ACCEPT_TAC;
        ASM_ARITH_TAC];
      MAP_EVERY X_GEN_TAC
      [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
        `n:num`; `k:num`; `w:num->A`] THEN
      INTRO_TAC
       "(graph old_injective old_count) nlarge injective fresh \
        neighbors first last" THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INSERT_VERTEX_STAR THEN
        ASM_REWRITE_TAC[];
        USE_THEN "injective" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `INJ (w:num->A) (cyclic_indices (k + 2)) (:A)`
      (LABEL_TAC "w_injective") THENL
       [MATCH_MP_TAC(ISPECL
         [`q:num->A`; `w:num->A`; `n:num`; `k:num`]
         INJ_CYCLIC_DELETE_LAST_IMP_INJ_CHAIN) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `CARD(cyclic_vertices (w:num->A) (k + 2)) = k + 2`
      (LABEL_TAC "neighbors_card") THENL
       [MATCH_MP_TAC CARD_CYCLIC_VERTICES THEN
        USE_THEN "w_injective" ACCEPT_TAC;
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `(q:num->A)(n - 1)`;
        `cyclic_vertices (w:num->A) (k + 2)`]
       FINITE_SIMPLE_GRAPH_INSERT_STAR_CARD) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "neighbors_card" (fun th -> REWRITE_TAC[th]) THEN
      INTRO_TAC "vertices_card edges_card" THEN
      ASM_ARITH_TAC;
      MAP_EVERY X_GEN_TAC
       [`V1:A->bool`; `E1:(A->bool)->bool`;
        `V2:A->bool`; `E2:(A->bool)->bool`;
        `q:num->A`; `n:num`; `j:num`] THEN
      INTRO_TAC
       "(graph1 left_injective count1) \
        (graph2 right_injective count2) \
        jpositive bound injective overlap chord1 chord2" THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_UNION THEN ASM_REWRITE_TAC[];
        USE_THEN "injective" ACCEPT_TAC;
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`V1:A->bool`; `V2:A->bool`;
        `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
        `(q:num->A) j`; `(q:num->A)(n - 1)`]
       FINITE_SIMPLE_GRAPH_SPLIT_CARD) THEN
      ASM_REWRITE_TAC[] THEN
      INTRO_TAC "vertices_card edges_card" THEN
      ASM_ARITH_TAC];
    MESON_TAC[]]);;

let CYCLIC_VERTICES_CONG = prove
 (`!q p:num->A. !n.
        (!i. i < n ==> p i = q i)
        ==> cyclic_vertices p n = cyclic_vertices q n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "agree") THEN
  REWRITE_TAC[cyclic_vertices] THEN
  MATCH_MP_TAC IMAGE_EQ THEN
  X_GEN_TAC `i:num` THEN
  REWRITE_TAC[IN_CYCLIC_INDICES] THEN
  DISCH_THEN(LABEL_TAC "index") THEN
  USE_THEN "agree" MATCH_MP_TAC THEN
  USE_THEN "index" ACCEPT_TAC);;

let CYCLIC_EDGES_CONG = prove
 (`!q p:num->A. !n.
        (!i. i < n ==> p i = q i)
        ==> cyclic_edges p n = cyclic_edges q n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "agree") THEN
  REWRITE_TAC[cyclic_edges] THEN
  MATCH_MP_TAC IMAGE_EQ THEN
  X_GEN_TAC `i:num` THEN
  REWRITE_TAC[IN_CYCLIC_INDICES] THEN
  DISCH_THEN(LABEL_TAC "index") THEN
  SUBGOAL_THEN `0 < n` (LABEL_TAC "positive") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:num->A) i = (q:num->A) i`
  (LABEL_TAC "first") THENL
   [USE_THEN "agree" MATCH_MP_TAC THEN
    USE_THEN "index" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:num->A) ((i + 1) MOD n) = (q:num->A) ((i + 1) MOD n)`
  (LABEL_TAC "second") THENL
   [USE_THEN "agree" MATCH_MP_TAC THEN
    REWRITE_TAC[MOD_LT_EQ_LT] THEN
    USE_THEN "positive" ACCEPT_TAC;
    ASM_REWRITE_TAC[]]);;

let INJ_CYCLIC_INDICES_CONG = prove
 (`!q p:num->A. !n.
        INJ q (cyclic_indices n) (:A) /\
        (!i. i < n ==> p i = q i)
        ==> INJ p (cyclic_indices n) (:A)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective agree" THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
  INTRO_TAC "i_index j_index same" THEN
  USE_THEN "injective" MP_TAC THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
  DISCH_THEN(MATCH_MP_TAC o SPECL [`i:num`; `j:num`]) THEN
  ASM_MESON_TAC[]);;

let RECURSIVE_TRIANGULATED_DISK_CONG = prove
 (`!V E q:num->A. !n p:num->A.
        recursive_triangulated_disk V E q n /\
        (!i. i < n ==> p i = q i)
        ==> recursive_triangulated_disk V E p n`,
  SUBGOAL_THEN
   `!V E q:num->A. !n.
        recursive_triangulated_disk V E q n
        ==> !p:num->A.
              (!i. i < n ==> p i = q i)
              ==> recursive_triangulated_disk V E p n`
  MP_TAC THENL
   [MATCH_MP_TAC
     (BETA_RULE(SPEC
       `\(V:A->bool) (E:(A->bool)->bool) (q:num->A) n.
          !p:num->A.
            (!i. i < n ==> p i = q i)
            ==> recursive_triangulated_disk V E p n`
       recursive_triangulated_disk_INDUCT)) THEN
    REPEAT CONJ_TAC THENL
     [X_GEN_TAC `q:num->A` THEN DISCH_THEN(LABEL_TAC "injective") THEN
      X_GEN_TAC `p:num->A` THEN DISCH_THEN(LABEL_TAC "agree") THEN
      SUBGOAL_THEN `INJ (p:num->A) (cyclic_indices 3) (:A)`
      (LABEL_TAC "p_injective") THENL
       [MATCH_MP_TAC INJ_CYCLIC_INDICES_CONG THEN
        EXISTS_TAC `q:num->A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPEC `p:num->A`
       (CONJUNCT1 recursive_triangulated_disk_RULES)) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "agree" (fun th ->
       REWRITE_TAC
        [MATCH_MP CYCLIC_VERTICES_CONG th;
         MATCH_MP CYCLIC_EDGES_CONG th]);
      MAP_EVERY X_GEN_TAC
       [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
        `n:num`; `k:num`; `w:num->A`] THEN
      INTRO_TAC
       "induction nlarge injective fresh neighbors first last" THEN
      X_GEN_TAC `p:num->A` THEN DISCH_THEN(LABEL_TAC "agree") THEN
      SUBGOAL_THEN
       `INJ (p:num->A) (cyclic_indices n) (:A)`
      (LABEL_TAC "p_injective") THENL
       [MATCH_MP_TAC INJ_CYCLIC_INDICES_CONG THEN
        EXISTS_TAC `q:num->A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!i. i < n - 1 + k
            ==> cyclic_delete_last (p:num->A) w n i =
                cyclic_delete_last q w n i`
      (LABEL_TAC "child_agree") THENL
       [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
        REWRITE_TAC[cyclic_delete_last] THEN
        COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "agree" MATCH_MP_TAC THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `recursive_triangulated_disk
          V E (cyclic_delete_last (p:num->A) w n) (n - 1 + k)`
      (LABEL_TAC "p_child") THENL
       [USE_THEN "induction" MATCH_MP_TAC THEN
        USE_THEN "child_agree" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(p:num->A) 0 = q 0 /\
        p(n - 2) = q(n - 2) /\
        p(n - 1) = q(n - 1)`
      (CONJUNCTS_THEN2 (LABEL_TAC "first_value")
       (CONJUNCTS_THEN2 (LABEL_TAC "penultimate_value")
        (LABEL_TAC "last_value"))) THENL
       [REPEAT CONJ_TAC THEN USE_THEN "agree" MATCH_MP_TAC THEN
        ASM_ARITH_TAC;
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:num->A`;
        `n:num`; `k:num`; `w:num->A`]
       (CONJUNCT1(CONJUNCT2 recursive_triangulated_disk_RULES))) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        DISCH_THEN(LABEL_TAC "p_recursive")] THEN
      USE_THEN "p_recursive" (fun th ->
       USE_THEN "last_value" (fun eq -> ACCEPT_TAC(REWRITE_RULE[eq] th)));
      MAP_EVERY X_GEN_TAC
       [`V1:A->bool`; `E1:(A->bool)->bool`;
        `V2:A->bool`; `E2:(A->bool)->bool`;
        `q:num->A`; `n:num`; `j:num`] THEN
      INTRO_TAC
       "induction1 induction2 jpositive bound injective \
        overlap chord1 chord2" THEN
      X_GEN_TAC `p:num->A` THEN DISCH_THEN(LABEL_TAC "agree") THEN
      SUBGOAL_THEN
       `INJ (p:num->A) (cyclic_indices n) (:A)`
      (LABEL_TAC "p_injective") THENL
       [MATCH_MP_TAC INJ_CYCLIC_INDICES_CONG THEN
        EXISTS_TAC `q:num->A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!i. i < j + 2
            ==> cyclic_split_left (p:num->A) n j i =
                cyclic_split_left q n j i`
      (LABEL_TAC "left_agree") THENL
       [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
        REWRITE_TAC[cyclic_split_left] THEN
        COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "agree" MATCH_MP_TAC THEN
        ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!i. i < n - j
            ==> cyclic_split_right (p:num->A) j i =
                cyclic_split_right q j i`
      (LABEL_TAC "right_agree") THENL
       [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
        REWRITE_TAC[cyclic_split_right] THEN
        USE_THEN "agree" MATCH_MP_TAC THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `recursive_triangulated_disk
          (V1:A->bool) E1 (cyclic_split_left p n j) (j + 2)`
      (LABEL_TAC "p_left") THENL
       [USE_THEN "induction1" MATCH_MP_TAC THEN
        USE_THEN "left_agree" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `recursive_triangulated_disk
          (V2:A->bool) E2 (cyclic_split_right p j) (n - j)`
      (LABEL_TAC "p_right") THENL
       [USE_THEN "induction2" MATCH_MP_TAC THEN
        USE_THEN "right_agree" ACCEPT_TAC;
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`;
        `V2:A->bool`; `E2:(A->bool)->bool`;
        `p:num->A`; `n:num`; `j:num`]
       (CONJUNCT2(CONJUNCT2 recursive_triangulated_disk_RULES))) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        SUBGOAL_THEN
         `(p:num->A) j = (q:num->A) j /\
          p(n - 1) = q(n - 1)`
        (CONJUNCTS_THEN2 (LABEL_TAC "chord_left")
          (LABEL_TAC "chord_right")) THENL
         [CONJ_TAC THEN USE_THEN "agree" MATCH_MP_TAC THEN
          ASM_ARITH_TAC;
          ASM_REWRITE_TAC[]];
        DISCH_THEN ACCEPT_TAC]];
    MESON_TAC[]]);;

let RECURSIVE_TRIANGULATED_DISK_CAP = prove
 (`!V E q:num->A. !n x:A.
        recursive_triangulated_disk V E q n /\
        ~(x IN V)
        ==> recursive_triangulated_disk
             (x INSERT V)
             (IMAGE (\u:A. {x,u}) (cyclic_vertices q n) UNION E)
             (\i. if i = 0 then q 0 else if i = 1 then q 1 else x)
             3`,
  REPEAT GEN_TAC THEN INTRO_TAC "recursive fresh" THEN
  MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`;
                 `q:num->A`; `n:num`]
    RECURSIVE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "graph nlarge injective boundary" THEN
  SUBGOAL_THEN `(q:num->A) 0 IN V /\ q 1 IN V`
  (CONJUNCTS_THEN2 (LABEL_TAC "q0_vertex")
    (LABEL_TAC "q1_vertex")) THENL
   [CONJ_TAC THEN USE_THEN "boundary"
     (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THENL
     [EXISTS_TAC `0`;
      EXISTS_TAC `1`] THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((q:num->A) 0 = q 1)`
  (LABEL_TAC "q01") THENL
   [USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    DISCH_THEN(MP_TAC o SPECL [`0`; `1`]) THEN
    ASM_MESON_TAC[ARITH_RULE
     `3 <= n ==> 0 < n /\ 1 < n /\ ~(0 = 1)`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((x:A) = q 0) /\ ~(x = q 1)`
  (CONJUNCTS_THEN2 (LABEL_TAC "xq0") (LABEL_TAC "xq1")) THENL
   [ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `INJ (\i. if i = 0 then (q:num->A) 0
             else if i = 1 then q 1 else x)
        (cyclic_indices 3) (:A)`
  (LABEL_TAC "cap_injective") THENL
   [REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
    INTRO_TAC "i_index j_index same" THEN
    (SUBGOAL_THEN `i = 0 \/ i = 1 \/ i = 2`
     MP_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC]) THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    (SUBGOAL_THEN `j = 0 \/ j = 1 \/ j = 2`
     MP_TAC THENL
     [ASM_ARITH_TAC;
      ALL_TAC]) THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    USE_THEN "same" MP_TAC THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `recursive_triangulated_disk
      (V:A->bool) E
      (cyclic_delete_last
        (\i. if i = 0 then q 0 else if i = 1 then q 1 else x)
        (\i. q((i + 1) MOD n)) 3)
      n`
  (LABEL_TAC "child") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `cyclic_delete_last
        (\i. if i = 0 then q 0 else if i = 1 then q 1 else (x:A))
        (\i. (q:num->A)((i + 1) MOD n)) 3`]
     RECURSIVE_TRIANGULATED_DISK_CONG) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    REWRITE_TAC[cyclic_delete_last] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_CASES_TAC `i < 2` THEN ASM_REWRITE_TAC[] THENL
     [ASM_CASES_TAC `i = 0` THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `i = 1` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[]];
      SUBGOAL_THEN `i - 1 + 1 = i` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        ASM_SIMP_TAC[MOD_LT]]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `\i. if i = 0 then (q:num->A) 0
          else if i = 1 then q 1 else x`;
    `3`; `n - 2`; `\i. (q:num->A)((i + 1) MOD n)`]
   (CONJUNCT1(CONJUNCT2 recursive_triangulated_disk_RULES))) THEN
  (ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [SUBGOAL_THEN `3 - 1 + (n - 2) = n` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        USE_THEN "child" ACCEPT_TAC];
      ARITH_TAC;
      USE_THEN "cap_injective" ACCEPT_TAC;
      SIMP_TAC[ARITH_RULE `3 - 1 = 2`;
               ARITH_RULE `~(2 = 0)`;
               ARITH_RULE `~(2 = 1)`] THEN
      USE_THEN "fresh" ACCEPT_TAC;
      SUBGOAL_THEN `n - 2 + 2 = n` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        ASM_REWRITE_TAC[CYCLIC_VERTICES_OFFSET]];
      (SUBGOAL_THEN `1 < n` (LABEL_TAC "one_bound") THENL
        [ASM_ARITH_TAC;
         ALL_TAC]) THEN
      ASM_SIMP_TAC[MOD_LT;
                   ARITH_RULE `0 + 1 = 1`;
                   ARITH_RULE `3 - 2 = 1`;
                   ARITH_RULE `~(1 = 0)`];
      (SUBGOAL_THEN `(n - 2 + 1) + 1 = n`
       (LABEL_TAC "wrap") THENL
       [ASM_ARITH_TAC;
        ALL_TAC]) THEN
      USE_THEN "wrap" (fun th -> REWRITE_TAC[th; MOD_REFL]) THEN
      SIMP_TAC[]];
    DISCH_THEN MP_TAC]) THEN
  (SUBGOAL_THEN `n - 2 + 2 = n` SUBST1_TAC THENL
   [ASM_ARITH_TAC;
    REWRITE_TAC[CYCLIC_VERTICES_OFFSET] THEN
    SIMP_TAC[ARITH_RULE `3 - 1 = 2`;
             ARITH_RULE `~(2 = 0)`;
             ARITH_RULE `~(2 = 1)`]]));;

(* ------------------------------------------------------------------------- *)
(* Injective relabelling of recursive triangulated disks.                    *)
(* ------------------------------------------------------------------------- *)

let CYCLIC_VERTICES_IMAGE = prove
 (`!f:A->B. !q:num->A. !n.
        cyclic_vertices (f o q) n = IMAGE f (cyclic_vertices q n)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[cyclic_vertices; IMAGE_o]);;

let CYCLIC_EDGES_IMAGE = prove
 (`!f:A->B. !q:num->A. !n.
        cyclic_edges (f o q) n =
        IMAGE (IMAGE f) (cyclic_edges q n)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[cyclic_edges; IMAGE_o; o_DEF] THEN
  ONCE_REWRITE_TAC[GSYM IMAGE_o] THEN
  MATCH_MP_TAC IMAGE_EQ THEN
  X_GEN_TAC `i:num` THEN DISCH_TAC THEN
  REWRITE_TAC[o_DEF; IMAGE_CLAUSES]);;

let CYCLIC_DELETE_LAST_IMAGE = prove
 (`!f:A->B. !q w:num->A. !n.
        f o cyclic_delete_last q w n =
        cyclic_delete_last (f o q) (f o w) n`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[FUN_EQ_THM; o_DEF; cyclic_delete_last] THEN
  GEN_TAC THEN COND_CASES_TAC THEN REWRITE_TAC[]);;

let CYCLIC_SPLIT_LEFT_IMAGE = prove
 (`!f:A->B. !q:num->A. !n j.
        f o cyclic_split_left q n j =
        cyclic_split_left (f o q) n j`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[FUN_EQ_THM; o_DEF; cyclic_split_left] THEN
  GEN_TAC THEN COND_CASES_TAC THEN REWRITE_TAC[]);;

let CYCLIC_SPLIT_RIGHT_IMAGE = prove
 (`!f:A->B. !q:num->A. !j.
        f o cyclic_split_right q j =
        cyclic_split_right (f o q) j`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[FUN_EQ_THM; o_DEF; cyclic_split_right]);;

let RECURSIVE_TRIANGULATED_DISK_DELETE_LAST_IMAGE = prove
 (`!f:A->B. !V E q w n m.
        recursive_triangulated_disk
          V E (f o cyclic_delete_last q w n) m
        ==> recursive_triangulated_disk
             V E (cyclic_delete_last (f o q) (f o w) n) m`,
  REPEAT GEN_TAC THEN REWRITE_TAC[CYCLIC_DELETE_LAST_IMAGE]);;

let CYCLIC_VERTICES_IMAGE_SUBSET = prove
 (`!f:A->B. !q n V.
        cyclic_vertices q n SUBSET V
        ==> cyclic_vertices (f o q) n SUBSET IMAGE f V`,
  REPEAT GEN_TAC THEN REWRITE_TAC[CYCLIC_VERTICES_IMAGE] THEN
  MATCH_ACCEPT_TAC IMAGE_SUBSET);;

let IMAGE_STAR_IMAGE = prove
 (`!f:A->B. !x N.
        IMAGE (IMAGE f) (IMAGE (\u:A. {x,u}) N) =
        IMAGE (\u:B. {f x,u}) (IMAGE f N)`,
  REPEAT GEN_TAC THEN
  ONCE_REWRITE_TAC[GSYM IMAGE_o] THEN
  ONCE_REWRITE_TAC[GSYM IMAGE_o] THEN
  MATCH_MP_TAC IMAGE_EQ THEN
  REWRITE_TAC[o_DEF; IMAGE_CLAUSES]);;

let PAIR_EDGE_IMAGE_IN = prove
 (`!f:A->B. !a b E.
        {a,b} IN E
        ==> {f a,f b} IN IMAGE (IMAGE f) E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "edge") THEN
  REWRITE_TAC[IN_IMAGE] THEN
  EXISTS_TAC `{a:A,b}` THEN
  ASM_REWRITE_TAC[IMAGE_CLAUSES]);;

let INJ_ON_SUBSET = prove
 (`!f:A->B. !s t.
        INJ f t (:B) /\ s SUBSET t
        ==> INJ f s (:B)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[INJ; SUBSET; IN_UNIV] THEN MESON_TAC[]);;

let INJ_ON_COMPOSE = prove
 (`!f:A->B. !g:C->A. !s t.
        INJ f t (:B) /\
        INJ g s (:A) /\
        IMAGE g s SUBSET t
        ==> INJ (f o g) s (:B)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[INJ; SUBSET; FORALL_IN_IMAGE; IN_UNIV; o_DEF] THEN
  MESON_TAC[]);;

let RECURSIVE_TRIANGULATED_DISK_INSERT_BOUNDARY_SUBSET = prove
 (`!V E q:num->A. !n k w.
        recursive_triangulated_disk
          V E (cyclic_delete_last q w n) (n - 1 + k) /\
        3 <= n
        ==> IMAGE q (cyclic_indices n) SUBSET q (n - 1) INSERT V`,
  REPEAT GEN_TAC THEN INTRO_TAC "recursive nlarge" THEN
  REWRITE_TAC[SUBSET; FORALL_IN_IMAGE;
              IN_CYCLIC_INDICES; IN_INSERT] THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
  ASM_CASES_TAC `(i:num) = n - 1` THEN ASM_REWRITE_TAC[] THEN
  DISJ2_TAC THEN
  MP_TAC(MATCH_MP RECURSIVE_TRIANGULATED_DISK_INVARIANTS
   (ASSUME
    `recursive_triangulated_disk
      (V:A->bool) E (cyclic_delete_last q w n) (n - 1 + k)`)) THEN
  INTRO_TAC "_ _ _ boundary" THEN
  USE_THEN "boundary"
   (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
  REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
  EXISTS_TAC `i:num` THEN CONJ_TAC THENL
   [ASM_ARITH_TAC;
    MATCH_MP_TAC EQ_SYM THEN
    MATCH_MP_TAC CYCLIC_DELETE_LAST_PREFIX THEN ASM_ARITH_TAC]);;

let RECURSIVE_TRIANGULATED_DISK_INSERT_IMAGE_INJ = prove
 (`!f:A->B. !V E q:num->A. !n k w.
        recursive_triangulated_disk
          V E (cyclic_delete_last q w n) (n - 1 + k) /\
        3 <= n /\
        INJ q (cyclic_indices n) (:A) /\
        INJ f (q (n - 1) INSERT V) (:B)
        ==> INJ (f o q) (cyclic_indices n) (:B)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "recursive nlarge q_injective f_injective" THEN
  MATCH_MP_TAC INJ_ON_COMPOSE THEN
  EXISTS_TAC `(q:num->A) (n - 1) INSERT V` THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "f_injective" ACCEPT_TAC;
    USE_THEN "q_injective" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
      `n:num`; `k:num`; `w:num->A`]
     RECURSIVE_TRIANGULATED_DISK_INSERT_BOUNDARY_SUBSET) THEN
    CONJ_TAC THENL
     [USE_THEN "recursive" ACCEPT_TAC;
      USE_THEN "nlarge" ACCEPT_TAC]]);;

let COMPOSE_IMAGE_FRESH_INJ_ON = prove
 (`!f:A->B. !q:num->A. !i V.
        INJ f (q i INSERT V) (:B) /\
        ~(q i IN V)
        ==> ~((f o q) i IN IMAGE f V)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[o_THM; INJ; IN_UNIV; IN_IMAGE; IN_INSERT] THEN
  MESON_TAC[]);;

let COMPOSE_APPLY_EQ = prove
 (`!f:A->B. !q w:num->A. !i:num. !j:num.
        w i = q j
        ==> (f o w) i = (f o q) j`,
  REPEAT GEN_TAC THEN REWRITE_TAC[o_THM] THEN
  DISCH_THEN SUBST1_TAC THEN REFL_TAC);;

let RECURSIVE_TRIANGULATED_DISK_IMAGE_INSERT = prove
 (`!f:A->B. !q w:num->A. !V E n k.
        recursive_triangulated_disk
          ((f o q) (n - 1) INSERT IMAGE f V)
          (IMAGE (\u:B. {(f o q) (n - 1),u})
                 (cyclic_vertices (f o w) (k + 2)) UNION
           IMAGE (IMAGE f) E)
          (f o q) n
        ==> recursive_triangulated_disk
             (IMAGE f (q (n - 1) INSERT V))
             (IMAGE (IMAGE f)
                (IMAGE (\u:A. {q (n - 1),u})
                       (cyclic_vertices w (k + 2)) UNION E))
             (f o q) n`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[IMAGE_CLAUSES; IMAGE_UNION; IMAGE_STAR_IMAGE;
              o_THM; CYCLIC_VERTICES_IMAGE]);;

let RECURSIVE_TRIANGULATED_DISK_IMAGE_INSERT_RULE = prove
 (`!f:A->B. !q w:num->A. !V E n k.
        recursive_triangulated_disk
          (IMAGE f V) (IMAGE (IMAGE f) E)
          (cyclic_delete_last (f o q) (f o w) n) (n - 1 + k) /\
        3 <= n /\
        INJ (f o q) (cyclic_indices n) (:B) /\
        ~((f o q) (n - 1) IN IMAGE f V) /\
        cyclic_vertices (f o w) (k + 2) SUBSET IMAGE f V /\
        (f o w) 0 = (f o q) (n - 2) /\
        (f o w) (k + 1) = (f o q) 0
        ==> recursive_triangulated_disk
             (IMAGE f (q (n - 1) INSERT V))
             (IMAGE (IMAGE f)
                (IMAGE (\u:A. {q (n - 1),u})
                       (cyclic_vertices w (k + 2)) UNION E))
             (f o q) n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "child nlarge injective fresh neighbors first last" THEN
  MATCH_MP_TAC(ISPECL
   [`f:A->B`; `q:num->A`; `w:num->A`;
    `V:A->bool`; `E:(A->bool)->bool`; `n:num`; `k:num`]
   RECURSIVE_TRIANGULATED_DISK_IMAGE_INSERT) THEN
  MATCH_MP_TAC(ISPECL
   [`IMAGE (f:A->B) V`;
    `IMAGE (IMAGE (f:A->B)) (E:(A->bool)->bool)`;
    `(f:A->B) o (q:num->A)`; `n:num`; `k:num`;
    `(f:A->B) o (w:num->A)`]
   (CONJUNCT1(CONJUNCT2 recursive_triangulated_disk_RULES))) THEN
  ASM_REWRITE_TAC[]);;

let RECURSIVE_TRIANGULATED_DISK_IMAGE_UNION = prove
 (`!f:A->B. !V1 E1 V2 E2 q n.
        recursive_triangulated_disk
          (IMAGE f V1 UNION IMAGE f V2)
          (IMAGE (IMAGE f) E1 UNION IMAGE (IMAGE f) E2)
          q n
        ==> recursive_triangulated_disk
             (IMAGE f (V1 UNION V2))
             (IMAGE (IMAGE f) (E1 UNION E2))
             q n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IMAGE_UNION]);;

let RECURSIVE_TRIANGULATED_DISK_IMAGE_SPLIT_RULE = prove
 (`!f:A->B. !V1 E1 V2 E2 q:num->A. !n j.
        recursive_triangulated_disk
          (IMAGE f V1) (IMAGE (IMAGE f) E1)
          (cyclic_split_left (f o q) n j) (j + 2) /\
        recursive_triangulated_disk
          (IMAGE f V2) (IMAGE (IMAGE f) E2)
          (cyclic_split_right (f o q) j) (n - j) /\
        0 < j /\ j + 2 < n /\
        INJ (f o q) (cyclic_indices n) (:B) /\
        IMAGE f V1 INTER IMAGE f V2 =
          {f(q j),f(q(n - 1))} /\
        {q j,q(n - 1)} IN E1 /\
        {q j,q(n - 1)} IN E2
        ==> recursive_triangulated_disk
             (IMAGE f (V1 UNION V2))
             (IMAGE (IMAGE f) (E1 UNION E2))
             (f o q) n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "left right jpositive bound injective overlap chord1 chord2" THEN
  MATCH_MP_TAC(ISPECL
   [`f:A->B`; `V1:A->bool`; `E1:(A->bool)->bool`;
    `V2:A->bool`; `E2:(A->bool)->bool`;
    `(f:A->B) o (q:num->A)`; `n:num`]
   RECURSIVE_TRIANGULATED_DISK_IMAGE_UNION) THEN
  MATCH_MP_TAC(ISPECL
   [`IMAGE (f:A->B) V1`;
    `IMAGE (IMAGE (f:A->B)) (E1:(A->bool)->bool)`;
    `IMAGE (f:A->B) V2`;
    `IMAGE (IMAGE (f:A->B)) (E2:(A->bool)->bool)`;
    `(f:A->B) o (q:num->A)`; `n:num`; `j:num`]
   (CONJUNCT2(CONJUNCT2 recursive_triangulated_disk_RULES))) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "left" ACCEPT_TAC;
    USE_THEN "right" ACCEPT_TAC;
    USE_THEN "jpositive" ACCEPT_TAC;
    USE_THEN "bound" ACCEPT_TAC;
    USE_THEN "injective" ACCEPT_TAC;
    REWRITE_TAC[o_THM] THEN USE_THEN "overlap" ACCEPT_TAC;
    REWRITE_TAC[o_THM] THEN MATCH_MP_TAC PAIR_EDGE_IMAGE_IN THEN
    USE_THEN "chord1" ACCEPT_TAC;
    REWRITE_TAC[o_THM] THEN MATCH_MP_TAC PAIR_EDGE_IMAGE_IN THEN
    USE_THEN "chord2" ACCEPT_TAC]);;

let RECURSIVE_TRIANGULATED_DISK_IMAGE = prove
 (`!V E q:num->A. !n f:A->B.
        recursive_triangulated_disk V E q n /\
        INJ f V (:B)
        ==> recursive_triangulated_disk
             (IMAGE f V) (IMAGE (IMAGE f) E) (f o q) n`,
  SUBGOAL_THEN
   `!V E q:num->A. !n.
        recursive_triangulated_disk V E q n
        ==> recursive_triangulated_disk V E q n /\
            !f:A->B.
              INJ f V (:B)
              ==> recursive_triangulated_disk
                   (IMAGE f V) (IMAGE (IMAGE f) E) (f o q) n`
  MP_TAC THENL
   [MATCH_MP_TAC
     (BETA_RULE(SPEC
       `\(V:A->bool) (E:(A->bool)->bool) (q:num->A) n.
          recursive_triangulated_disk V E q n /\
          !f:A->B.
            INJ f V (:B)
            ==> recursive_triangulated_disk
                 (IMAGE f V) (IMAGE (IMAGE f) E) (f o q) n`
    recursive_triangulated_disk_INDUCT)) THEN
    REPEAT CONJ_TAC THENL
     [X_GEN_TAC `q:num->A` THEN DISCH_THEN(LABEL_TAC "injective") THEN
      SUBGOAL_THEN
       `recursive_triangulated_disk
         (cyclic_vertices (q:num->A) 3) (cyclic_edges q 3) q 3`
      (LABEL_TAC "recursive") THENL
       [MATCH_MP_TAC(CONJUNCT1 recursive_triangulated_disk_RULES) THEN
        USE_THEN "injective" ACCEPT_TAC;
        ALL_TAC] THEN
      CONJ_TAC THENL
       [USE_THEN "recursive" ACCEPT_TAC;
        ALL_TAC] THEN
      X_GEN_TAC `f:A->B` THEN DISCH_THEN(LABEL_TAC "f_injective") THEN
      MP_TAC(ISPEC `(f:A->B) o (q:num->A)`
       (CONJUNCT1 recursive_triangulated_disk_RULES)) THEN
      ANTS_TAC THENL
       [MATCH_MP_TAC INJ_ON_COMPOSE THEN
        EXISTS_TAC `cyclic_vertices (q:num->A) 3` THEN
        ASM_REWRITE_TAC[cyclic_vertices; SUBSET_REFL];
        REWRITE_TAC[CYCLIC_VERTICES_IMAGE; CYCLIC_EDGES_IMAGE]];
      MAP_EVERY X_GEN_TAC
       [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
        `n:num`; `k:num`; `w:num->A`] THEN
      INTRO_TAC
       "(child_recursive induction) nlarge injective fresh \
        neighbors first last" THEN
      SUBGOAL_THEN
       `recursive_triangulated_disk
         ((q:num->A) (n - 1) INSERT V)
         (IMAGE (\u:A. {q (n - 1),u})
                (cyclic_vertices w (k + 2)) UNION E)
         q n`
      (LABEL_TAC "recursive") THENL
       [MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
          `n:num`; `k:num`; `w:num->A`]
         (CONJUNCT1(CONJUNCT2 recursive_triangulated_disk_RULES))) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      CONJ_TAC THENL
       [USE_THEN "recursive" ACCEPT_TAC;
        ALL_TAC] THEN
      X_GEN_TAC `f:A->B` THEN DISCH_THEN(LABEL_TAC "f_injective") THEN
      SUBGOAL_THEN `INJ (f:A->B) V (:B)`
      (LABEL_TAC "f_child_injective") THENL
       [MATCH_MP_TAC INJ_ON_SUBSET THEN
        EXISTS_TAC `(q:num->A)(n - 1) INSERT V` THEN
        ASM_REWRITE_TAC[] THEN SET_TAC[];
        ALL_TAC] THEN
      USE_THEN "induction" (MP_TAC o SPEC `f:A->B`) THEN
      ANTS_TAC THENL
       [USE_THEN "f_child_injective" ACCEPT_TAC;
        DISCH_THEN(LABEL_TAC "mapped_child_raw")] THEN
      SUBGOAL_THEN
       `recursive_triangulated_disk
         (IMAGE (f:A->B) V) (IMAGE (IMAGE f) E)
         (cyclic_delete_last (f o q) (f o w) n) (n - 1 + k)`
      (LABEL_TAC "mapped_child") THENL
       [MATCH_MP_TAC RECURSIVE_TRIANGULATED_DISK_DELETE_LAST_IMAGE THEN
        USE_THEN "mapped_child_raw" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `INJ ((f:A->B) o (q:num->A)) (cyclic_indices n) (:B)`
      (LABEL_TAC "mapped_injective") THENL
       [MATCH_MP_TAC(ISPECL
         [`f:A->B`; `V:A->bool`; `E:(A->bool)->bool`;
          `q:num->A`; `n:num`; `k:num`; `w:num->A`]
         RECURSIVE_TRIANGULATED_DISK_INSERT_IMAGE_INJ) THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "child_recursive" ACCEPT_TAC;
          USE_THEN "nlarge" ACCEPT_TAC;
          USE_THEN "injective" ACCEPT_TAC;
         USE_THEN "f_injective" ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN
      `~(((f:A->B) o (q:num->A)) (n - 1) IN IMAGE f V)`
      (LABEL_TAC "mapped_fresh") THENL
       [MATCH_MP_TAC(ISPECL
         [`f:A->B`; `q:num->A`; `n - 1`; `V:A->bool`]
         COMPOSE_IMAGE_FRESH_INJ_ON) THEN
        CONJ_TAC THENL
         [USE_THEN "f_injective" ACCEPT_TAC;
          USE_THEN "fresh" ACCEPT_TAC];
        ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
       [`f:A->B`; `q:num->A`; `w:num->A`;
       `V:A->bool`; `E:(A->bool)->bool`; `n:num`; `k:num`]
       RECURSIVE_TRIANGULATED_DISK_IMAGE_INSERT_RULE) THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "mapped_child" ACCEPT_TAC;
        USE_THEN "nlarge" ACCEPT_TAC;
        USE_THEN "mapped_injective" ACCEPT_TAC;
        USE_THEN "mapped_fresh" ACCEPT_TAC;
        MATCH_MP_TAC CYCLIC_VERTICES_IMAGE_SUBSET THEN
        USE_THEN "neighbors" ACCEPT_TAC;
        MATCH_MP_TAC COMPOSE_APPLY_EQ THEN
        USE_THEN "first" ACCEPT_TAC;
        MATCH_MP_TAC COMPOSE_APPLY_EQ THEN
        USE_THEN "last" ACCEPT_TAC];
      MAP_EVERY X_GEN_TAC
       [`V1:A->bool`; `E1:(A->bool)->bool`;
        `V2:A->bool`; `E2:(A->bool)->bool`;
        `q:num->A`; `n:num`; `j:num`] THEN
      INTRO_TAC
       "(child_recursive1 induction1) \
        (child_recursive2 induction2) \
        jpositive bound injective overlap chord1 chord2" THEN
      SUBGOAL_THEN
       `recursive_triangulated_disk
         (V1 UNION V2:A->bool) (E1 UNION E2) q n`
      (LABEL_TAC "recursive") THENL
       [MATCH_MP_TAC(ISPECL
         [`V1:A->bool`; `E1:(A->bool)->bool`;
          `V2:A->bool`; `E2:(A->bool)->bool`;
          `q:num->A`; `n:num`; `j:num`]
         (CONJUNCT2(CONJUNCT2 recursive_triangulated_disk_RULES))) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      CONJ_TAC THENL
       [USE_THEN "recursive" ACCEPT_TAC;
        ALL_TAC] THEN
      X_GEN_TAC `f:A->B` THEN DISCH_THEN(LABEL_TAC "f_injective") THEN
      SUBGOAL_THEN
       `INJ (f:A->B) V1 (:B) /\ INJ f V2 (:B)`
      (CONJUNCTS_THEN2 (LABEL_TAC "f_injective1")
        (LABEL_TAC "f_injective2")) THENL
       [CONJ_TAC THEN MATCH_MP_TAC INJ_ON_SUBSET THEN
        EXISTS_TAC `V1 UNION V2:A->bool` THEN
        ASM_REWRITE_TAC[] THEN SET_TAC[];
        ALL_TAC] THEN
      USE_THEN "induction1" (MP_TAC o SPEC `f:A->B`) THEN
      ANTS_TAC THENL
       [USE_THEN "f_injective1" ACCEPT_TAC;
        REWRITE_TAC[CYCLIC_SPLIT_LEFT_IMAGE]] THEN
      DISCH_THEN(LABEL_TAC "mapped1") THEN
      USE_THEN "induction2" (MP_TAC o SPEC `f:A->B`) THEN
      ANTS_TAC THENL
       [USE_THEN "f_injective2" ACCEPT_TAC;
        REWRITE_TAC[CYCLIC_SPLIT_RIGHT_IMAGE]] THEN
      DISCH_THEN(LABEL_TAC "mapped2") THEN
      SUBGOAL_THEN
       `INJ ((f:A->B) o (q:num->A)) (cyclic_indices n) (:B)`
      (LABEL_TAC "mapped_injective") THENL
       [MATCH_MP_TAC INJ_ON_COMPOSE THEN
        EXISTS_TAC `V1 UNION V2:A->bool` THEN
        ASM_REWRITE_TAC[] THEN
        USE_THEN "recursive"
         (MP_TAC o MATCH_MP RECURSIVE_TRIANGULATED_DISK_INVARIANTS) THEN
        INTRO_TAC "_ _ _ boundary" THEN
        USE_THEN "boundary"
         (ACCEPT_TAC o REWRITE_RULE[cyclic_vertices]);
        ALL_TAC] THEN
      SUBGOAL_THEN
       `IMAGE (f:A->B) V1 INTER IMAGE f V2 =
        {f((q:num->A) j),f(q(n - 1))}`
      (LABEL_TAC "mapped_overlap") THENL
       [MP_TAC(ISPECL
         [`f:A->B`; `V1 UNION V2:A->bool`; `V1:A->bool`; `V2:A->bool`]
         IMAGE_INTER_INJ_ON) THEN
        ASM_REWRITE_TAC[] THEN
        ANTS_TAC THENL
         [SET_TAC[];
          DISCH_THEN(LABEL_TAC "image_inter")] THEN
        MATCH_MP_TAC EQ_SYM THEN
        USE_THEN "image_inter" MP_TAC THEN
        USE_THEN "overlap"
         (fun th -> REWRITE_TAC[th; IMAGE_CLAUSES]);
        ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
       [`f:A->B`; `V1:A->bool`; `E1:(A->bool)->bool`;
        `V2:A->bool`; `E2:(A->bool)->bool`;
        `q:num->A`; `n:num`; `j:num`]
       RECURSIVE_TRIANGULATED_DISK_IMAGE_SPLIT_RULE) THEN
      ASM_REWRITE_TAC[]];
    MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Cyclic rerooting of recursive triangulated disks.                         *)
(* ------------------------------------------------------------------------- *)

let STRAIGHT_LINE_GRAPH_CARRIER_SUBSET_CONVEX_HULL = prove
 (`!V E p:A->real^2.
        finite_simple_graph V E /\
        straight_line_embedding V E p
        ==> plane_graph_carrier V E p (straight_edge p)
            SUBSET convex hull (IMAGE p V)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph embedding" THEN
  REWRITE_TAC[plane_graph_carrier; UNION_SUBSET] THEN
  CONJ_TAC THENL
   [MATCH_ACCEPT_TAC HULL_SUBSET;
    REWRITE_TAC[UNIONS_SUBSET; FORALL_IN_IMAGE] THEN
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    MATCH_MP_TAC STRAIGHT_EDGE_SUBSET_CONVEX_HULL THEN
    USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[]]);;

let STRAIGHT_LINE_EMBEDDING_SUPPORTING_UNBOUNDED_FACE = prove
 (`!V E p:A->real^2. !u a:real^2. !b.
        finite_simple_graph V E /\
        straight_line_embedding V E p /\
        u IN V /\
        ~(a = vec 0) /\
        a dot p u = b /\
        (!x. x IN convex hull (IMAGE p V) ==> a dot x <= b)
        ==> ?outer.
              outer IN components
               ((:real^2) DIFF
                plane_graph_carrier V E p (straight_edge p)) /\
              ~bounded outer /\
              u IN plane_graph_face_vertices
                    V E p (straight_edge p) outer`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph embedding vertex normal support support_hull" THEN
  ABBREV_TAC `h = {x:real^2 | a dot x > b}` THEN
  SUBGOAL_THEN `connected(h:real^2->bool)` (LABEL_TAC "connected") THENL
   [MATCH_MP_TAC CONVEX_CONNECTED THEN
    EXPAND_TAC "h" THEN MATCH_ACCEPT_TAC CONVEX_HALFSPACE_GT;
    ALL_TAC] THEN
  SUBGOAL_THEN `~bounded(h:real^2->bool)` (LABEL_TAC "unbounded") THENL
   [EXPAND_TAC "h" THEN
    REWRITE_TAC[BOUNDED_HALFSPACE_GT] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(h:real^2->bool = {})` (LABEL_TAC "nonempty") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "unbounded" MP_TAC THEN REWRITE_TAC[BOUNDED_EMPTY];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `h SUBSET
    (:real^2) DIFF plane_graph_carrier
      (V:A->bool) E p (straight_edge p)`
  (LABEL_TAC "outside") THENL
   [REWRITE_TAC[SUBSET; IN_DIFF; IN_UNIV] THEN
    X_GEN_TAC `x:real^2` THEN DISCH_THEN(LABEL_TAC "x_halfspace") THEN
    DISCH_THEN(LABEL_TAC "x_carrier") THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`]
     STRAIGHT_LINE_GRAPH_CARRIER_SUBSET_CONVEX_HULL) THEN
    ASM_REWRITE_TAC[SUBSET] THEN
    DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(LABEL_TAC "x_hull") THEN
    SUBGOAL_THEN `a dot (x:real^2) <= b`
    (LABEL_TAC "x_support") THENL
     [USE_THEN "support_hull" MATCH_MP_TAC THEN
      USE_THEN "x_hull" ACCEPT_TAC;
      USE_THEN "x_halfspace" MP_TAC THEN
      EXPAND_TAC "h" THEN REWRITE_TAC[IN_ELIM_THM] THEN
      ASM_REAL_ARITH_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(:real^2) DIFF
      plane_graph_carrier (V:A->bool) E p (straight_edge p)`;
    `h:real^2->bool`]
   EXISTS_COMPONENT_SUPERSET) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    DISCH_THEN(LABEL_TAC "complement_empty") THEN
    USE_THEN "outside" MP_TAC THEN
    USE_THEN "nonempty" MP_TAC THEN
    ASM SET_TAC[];
    INTRO_TAC "@outer. component halfspace_subset"] THEN
  SUBGOAL_THEN `~bounded(outer:real^2->bool)`
  (LABEL_TAC "outer_unbounded") THENL
   [DISCH_THEN(LABEL_TAC "outer_bounded") THEN
    USE_THEN "unbounded" (MATCH_MP_TAC o NOT_ELIM) THEN
    MATCH_MP_TAC BOUNDED_SUBSET THEN
    EXISTS_TAC `outer:real^2->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:A->real^2) u IN closure(h:real^2->bool)`
  (LABEL_TAC "vertex_closure_halfspace") THENL
   [EXPAND_TAC "h" THEN
    ASM_SIMP_TAC[CLOSURE_HALFSPACE_GT; IN_ELIM_THM] THEN
    REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:A->real^2) u IN closure(outer:real^2->bool)`
  (LABEL_TAC "vertex_closure_outer") THENL
   [MATCH_MP_TAC(REWRITE_RULE[SUBSET] (MATCH_MP SUBSET_CLOSURE
      (ASSUME `(h:real^2->bool) SUBSET outer`))) THEN
    USE_THEN "vertex_closure_halfspace" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:A->real^2) u IN
    plane_graph_carrier V E p (straight_edge p)`
  (LABEL_TAC "vertex_carrier") THENL
   [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
      (ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
        `straight_edge (p:A->real^2)`]
       PLANE_GRAPH_CARRIER_VERTEX_SUBSET)) THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `u:A` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((p:A->real^2) u IN outer)`
  (LABEL_TAC "vertex_not_outer") THENL
   [MP_TAC(MATCH_MP IN_COMPONENTS_SUBSET
     (ASSUME
       `(outer:real^2->bool) IN components
        ((:real^2) DIFF
         plane_graph_carrier (V:A->bool) E p (straight_edge p))`)) THEN
    REWRITE_TAC[SUBSET; IN_DIFF; IN_UNIV] THEN
    DISCH_THEN(MP_TAC o SPEC `(p:A->real^2) u`) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `outer:real^2->bool` THEN
  ASM_REWRITE_TAC[plane_graph_face_vertices; IN_ELIM_THM] THEN
  REWRITE_TAC[frontier; IN_DIFF] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "vertex_interior") THEN
  USE_THEN "vertex_not_outer" (MATCH_MP_TAC o NOT_ELIM) THEN
  MATCH_MP_TAC(REWRITE_RULE[SUBSET] INTERIOR_SUBSET) THEN
  USE_THEN "vertex_interior" ACCEPT_TAC);;

let FINITE_SIMPLE_GRAPH_INSERT_STAR_NEIGHBORS = prove
 (`!V E x:A. !N.
        finite_simple_graph V E /\
        ~(x IN V) /\
        N SUBSET V
        ==> graph_neighbors
             (IMAGE (\u:A. {x,u}) N UNION E) x = N`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph fresh neighbors" THEN
  REWRITE_TAC[EXTENSION; IN_GRAPH_NEIGHBORS; IN_UNION] THEN
  X_GEN_TAC `u:A` THEN EQ_TAC THENL
   [DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "star")
      (LABEL_TAC "old")) THENL
     [USE_THEN "star" MP_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
      INTRO_TAC "@v. edge_pair v_neighbor" THEN
      SUBGOAL_THEN `(v:A) IN V` (LABEL_TAC "v_vertex") THENL
       [USE_THEN "neighbors" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "v_neighbor" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = v` SUBST1_TAC THENL
       [MATCH_MP_TAC(SET_RULE
         `~(x IN V) /\ v IN V /\ {x,u} = {x,v} ==> u = v`) THEN
        ASM_REWRITE_TAC[];
        USE_THEN "v_neighbor" ACCEPT_TAC];
      SUBGOAL_THEN `({x:A,u}:A->bool) SUBSET V`
      (LABEL_TAC "edge_vertices") THENL
       [USE_THEN "graph" MP_TAC THEN
        REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
        MAP_EVERY (fun name -> USE_THEN name MP_TAC)
         ["fresh"; "edge_vertices"] THEN
        REWRITE_TAC[SUBSET] THEN SET_TAC[]]];
    DISCH_THEN(LABEL_TAC "neighbor") THEN DISJ1_TAC THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `u:A` THEN
    ASM_REWRITE_TAC[]]);;

let FINITE_SIMPLE_GRAPH_INSERT_STAR_DELETE = prove
 (`!V E x:A. !N.
        finite_simple_graph V E /\
        ~(x IN V) /\
        N SUBSET V
        ==> induced_subgraph_edges
             (IMAGE (\u:A. {x,u}) N UNION E)
             ((x INSERT V) DELETE x) = E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph fresh neighbors" THEN
  SUBGOAL_THEN `((x:A) INSERT V) DELETE x = V` SUBST1_TAC THENL
   [REWRITE_TAC[DELETE_INSERT] THEN
    MATCH_MP_TAC(fst(EQ_IMP_RULE
      (SPECL [`x:A`; `V:A->bool`] DELETE_NON_ELEMENT))) THEN
    USE_THEN "fresh" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[EXTENSION; IN_INDUCED_SUBGRAPH_EDGES; IN_UNION] THEN
  X_GEN_TAC `e:A->bool` THEN EQ_TAC THENL
   [INTRO_TAC "edge edge_vertices" THEN
    USE_THEN "edge"
     (DISJ_CASES_THEN2 (LABEL_TAC "star") (LABEL_TAC "old")) THENL
     [USE_THEN "star" MP_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
      INTRO_TAC "@u. edge_pair u_neighbor" THEN
      USE_THEN "edge_pair" SUBST_ALL_TAC THEN
      USE_THEN "edge_vertices"
       (MP_TAC o SPEC `x:A` o REWRITE_RULE[SUBSET]) THEN
      REWRITE_TAC[IN_INSERT] THEN DISCH_THEN(LABEL_TAC "x_vertex") THEN
      CONTR_TAC
       (MP (NOT_ELIM(ASSUME `~((x:A) IN V)`))
           (ASSUME `(x:A) IN V`));
      USE_THEN "old" ACCEPT_TAC];
    DISCH_THEN(LABEL_TAC "old") THEN CONJ_TAC THENL
     [DISJ2_TAC THEN USE_THEN "old" ACCEPT_TAC;
      USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN
      INTRO_TAC "_ _ edge_data" THEN
      USE_THEN "edge_data" (MP_TAC o SPEC `e:A->bool`) THEN
      ANTS_TAC THENL
       [USE_THEN "old" ACCEPT_TAC;
        INTRO_TAC "subset size" THEN
        USE_THEN "subset" ACCEPT_TAC]]]);;

let TRIANGULAR_CYCLE_DELETE_VERTEX_NEIGHBORS = prove
 (`!E:(A->bool)->bool. !r:num->A. !x.
        simple_graph_cycle E r 3 /\
        x IN cyclic_vertices r 3
        ==> cyclic_vertices r 3 DELETE x SUBSET graph_neighbors E x`,
  REPEAT GEN_TAC THEN INTRO_TAC "cycle x_cycle" THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_GRAPH_NEIGHBORS] THEN
  X_GEN_TAC `u:A` THEN INTRO_TAC "u_cycle distinct" THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `r:num->A`; `x:A`; `u:A`]
   TRIANGULAR_SIMPLE_GRAPH_CYCLE_CLIQUE) THEN
  ASM_REWRITE_TAC[EQ_SYM_EQ]);;

let RECURSIVE_TRIANGULATED_DISK_3_MAXIMAL_PLANAR_GRAPH = prove
 (`!V E q:num->A.
        recursive_triangulated_disk V E q 3
        ==> planar_graph V E /\
            (!G. E PSUBSET G /\
                 G SUBSET complete_graph_edges V
                 ==> ~planar_graph V G)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "recursive") THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E /\
                INJ q (cyclic_indices 3) (:A) /\
                cyclic_vertices q 3 SUBSET V`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph")
   (CONJUNCTS_THEN2 (LABEL_TAC "injective")
    (LABEL_TAC "boundary"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `3`]
     RECURSIVE_TRIANGULATED_DISK_INVARIANTS) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `3 <= CARD(V:A->bool)` (LABEL_TAC "vertices") THENL
   [MP_TAC(ISPECL [`cyclic_vertices (q:num->A) 3`; `V:A->bool`]
      CARD_SUBSET) THEN
    ASM_REWRITE_TAC[] THEN
    ANTS_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
      ASM_SIMP_TAC[CARD_CYCLIC_VERTICES]];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(E:(A->bool)->bool) + 6 = 3 * CARD(V:A->bool)`
  (LABEL_TAC "edge_count") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `3`]
     RECURSIVE_TRIANGULATED_DISK_EDGE_COUNT) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `planar_graph (V:A->bool) E`
  (LABEL_TAC "topological") THENL
   [MATCH_MP_TAC STRAIGHT_LINE_PLANAR_IMP_PLANAR_GRAPH THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`]
     RECURSIVE_TRIANGULATED_DISK_3_IMP_STRAIGHT_LINE_PLANAR) THEN
    USE_THEN "recursive" ACCEPT_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "topological" ACCEPT_TAC;
    X_GEN_TAC `G:(A->bool)->bool` THEN
    INTRO_TAC "proper allowed" THEN
    DISCH_THEN(LABEL_TAC "G_topological") THEN
    SUBGOAL_THEN `FINITE(G:(A->bool)->bool)` (LABEL_TAC "finite_G") THENL
     [USE_THEN "G_topological" MP_TAC THEN
      REWRITE_TAC[planar_graph; finite_simple_graph] THEN
      MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD(E:(A->bool)->bool) < CARD(G:(A->bool)->bool)`
    (LABEL_TAC "strict_card") THENL
     [MATCH_MP_TAC CARD_PSUBSET THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`V:A->bool`; `G:(A->bool)->bool`]
      PLANAR_GRAPH_EDGE_BOUND) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]);;

let STANDARD_TRIANGLE_STRICTLY_CONVEX = prove
 (`strictly_convex_cycle
    (\i. if i = 0 then vector[&0;&0]:real^2
         else if i = 1 then vector[&1;&0]
         else vector[&0;&1]) 3`,
  REWRITE_TAC[strictly_convex_cycle] THEN
