   [ASM_ARITH_TAC;
    CONV_TAC NUM_REDUCE_CONV THEN
    SIMP_TAC[plane_orientation; VECTOR_2] THEN REAL_ARITH_TAC]);;

let STANDARD_TRIANGLE_SUPPORT = prove
 (`!x:real^2.
        x IN convex hull
         (cyclic_vertices
           (\i. if i = 0 then vector[&0;&0]:real^2
                else if i = 1 then vector[&1;&0]
                else vector[&0;&1]) 3)
        ==> (basis 2:real^2) dot x <= &1`,
  GEN_TAC THEN
  REWRITE_TAC[CYCLIC_VERTICES_3] THEN
