  SUBGOAL_THEN
   `convex hull
      {vector[&0;&0]:real^2,vector[&1;&0],vector[&0;&1]}
    SUBSET {x:real^2 | (basis 2:real^2) dot x <= &1}`
  (LABEL_TAC "support") THENL
   [MATCH_MP_TAC HULL_MINIMAL THEN CONJ_TAC THENL
     [REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_ELIM_THM] THEN
      SIMP_TAC[DOT_BASIS; VECTOR_2; DIMINDEX_2; ARITH] THEN
      REAL_ARITH_TAC;
      MATCH_ACCEPT_TAC CONVEX_HALFSPACE_LE];
    USE_THEN "support" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
    DISCH_THEN(MP_TAC o SPEC `x:real^2`) THEN
    ASM_REWRITE_TAC[IN_ELIM_THM]]);;

let RECURSIVE_TRIANGULATED_DISK_3_EXPOSED_PLANE_DISK = prove
 (`!V E q:num->A.
        recursive_triangulated_disk V E q 3
        ==> ?p:A->real^2. ?outer r.
              plane_triangulated_disk
                V E p (straight_edge p) r 3 outer /\
              ~bounded outer /\
              q 2 IN cyclic_vertices r 3`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "recursive") THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    INJ q (cyclic_indices 3) (:A) /\
    cyclic_vertices q 3 SUBSET V`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph")
   (CONJUNCTS_THEN2 (LABEL_TAC "injective")
    (LABEL_TAC "boundary"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `3`]
     RECURSIVE_TRIANGULATED_DISK_INVARIANTS) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:num->A) 2 IN V` (LABEL_TAC "q2_vertex") THENL
   [USE_THEN "boundary" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `2` THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `3 <= CARD(V:A->bool)` (LABEL_TAC "vertices") THENL
   [MP_TAC(ISPECL [`cyclic_vertices (q:num->A) 3`; `V:A->bool`]
      CARD_SUBSET) THEN
    ASM_REWRITE_TAC[] THEN
    ANTS_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
      ASM_SIMP_TAC[CARD_CYCLIC_VERTICES]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `3`]
   RECURSIVE_TRIANGULATED_DISK_STRAIGHT_LINE_EMBEDDING) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC
   `\i. if i = 0 then vector[&0;&0]:real^2
        else if i = 1 then vector[&1;&0]
        else vector[&0;&1]`) THEN
  ANTS_TAC THENL
   [MATCH_ACCEPT_TAC STANDARD_TRIANGLE_STRICTLY_CONVEX;
    INTRO_TAC "@p. embedding prescribed hull"] THEN
  SUBGOAL_THEN
  `(p:A->real^2) ((q:num->A) 2) = vector[&0;&1]`
  (LABEL_TAC "q2_point") THENL
   [USE_THEN "prescribed" (MP_TAC o SPEC `2`) THEN
    REWRITE_TAC[ARITH_RULE `2 < 3`; ARITH_RULE `~(2 = 0)`;
                ARITH_RULE `~(2 = 1)`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x:real^2.
      x IN convex hull (IMAGE (p:A->real^2) V)
      ==> (basis 2:real^2) dot x <= &1`
  (LABEL_TAC "support") THENL
   [X_GEN_TAC `x:real^2` THEN DISCH_THEN(LABEL_TAC "x_hull") THEN
    MATCH_MP_TAC STANDARD_TRIANGLE_SUPPORT THEN
    USE_THEN "hull" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "x_hull" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((basis 2:real^2) = vec 0)`
  (LABEL_TAC "normal") THENL
   [MATCH_MP_TAC BASIS_NONZERO THEN
    REWRITE_TAC[DIMINDEX_2] THEN ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `(q:num->A) 2`; `basis 2:real^2`; `&1`]
  STRAIGHT_LINE_EMBEDDING_SUPPORTING_UNBOUNDED_FACE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`vector[&0;&1]:real^2`; `2`] DOT_BASIS) THEN
    REWRITE_TAC[DIMINDEX_2; VECTOR_2] THEN ARITH_TAC;
    INTRO_TAC "@outer. outer_component outer_unbounded q2_face"] THEN
  SUBGOAL_THEN
   `plane_graph_embedding
      (V:A->bool) E p (straight_edge (p:A->real^2))`
  (LABEL_TAC "plane_embedding") THENL
   [MATCH_MP_TAC STRAIGHT_LINE_EMBEDDING_IMP_PLANE_GRAPH_EMBEDDING THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`]
   RECURSIVE_TRIANGULATED_DISK_3_MAXIMAL_PLANAR_GRAPH) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "topological maximal" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
    `straight_edge (p:A->real^2)`; `outer:real^2->bool`]
   MAXIMAL_PLANAR_GRAPH_PLANE_TRIANGULATED_DISK) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC "@r. disk"] THEN
  SUBGOAL_THEN `(q:num->A) 2 IN cyclic_vertices (r:num->A) 3`
  (LABEL_TAC "q2_boundary") THENL
   [USE_THEN "disk" MP_TAC THEN
    REWRITE_TAC[plane_triangulated_disk] THEN
    INTRO_TAC "_ _ _ _ _ face _" THEN
    USE_THEN "face" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "q2_face" ACCEPT_TAC;
    MAP_EVERY EXISTS_TAC
     [`p:A->real^2`; `outer:real^2->bool`; `r:num->A`] THEN
    ASM_REWRITE_TAC[]]);;

let RECURSIVE_TRIANGULATED_DISK_BOUNDARY_EDGES = prove
 (`!V E q:num->A. !n.
        recursive_triangulated_disk V E q n
        ==> cyclic_edges q n SUBSET E`,
  MATCH_MP_TAC recursive_triangulated_disk_INDUCT THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[SUBSET_REFL];
    REPEAT GEN_TAC THEN
    INTRO_TAC "child nlarge injective fresh neighbors first last" THEN
    REWRITE_TAC[SUBSET; IN_CYCLIC_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN INTRO_TAC "@i. i_index edge" THEN
    USE_THEN "edge" SUBST1_TAC THEN REWRITE_TAC[IN_UNION] THEN
    ASM_CASES_TAC `(i:num) < n - 2` THENL
     [DISJ2_TAC THEN
      USE_THEN "child" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      REWRITE_TAC[IN_CYCLIC_EDGES] THEN EXISTS_TAC `i:num` THEN
      CONJ_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN
         `i + 1 < n /\ i + 1 < n - 1 + k /\ i + 1 < n - 1`
        STRIP_ASSUME_TAC THENL
         [ASM_ARITH_TAC;
          ASM_SIMP_TAC[MOD_LT; CYCLIC_DELETE_LAST_PREFIX]] THEN
        SUBGOAL_THEN `i < n - 1`
         (fun th -> REWRITE_TAC[MATCH_MP CYCLIC_DELETE_LAST_PREFIX th]) THEN
        ASM_ARITH_TAC];
      SUBGOAL_THEN `(i:num) = n - 2 \/ i = n - 1` MP_TAC THENL
       [ASM_ARITH_TAC;
        DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
         [DISJ1_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
          EXISTS_TAC `(w:num->A) 0` THEN CONJ_TAC THENL
           [SUBGOAL_THEN `n - 2 + 1 = n - 1` SUBST1_TAC THENL
             [ASM_ARITH_TAC;
              SUBGOAL_THEN `n - 1 < n` ASSUME_TAC THENL
               [ASM_ARITH_TAC;
                ASM_SIMP_TAC[MOD_LT; PAIR_SET_SYM]]];
            REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
            EXISTS_TAC `0` THEN ARITH_TAC];
          DISJ1_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
          EXISTS_TAC `(w:num->A) (k + 1)` THEN CONJ_TAC THENL
           [SUBGOAL_THEN `n - 1 + 1 = n` SUBST1_TAC THENL
             [ASM_ARITH_TAC;
              ASM_REWRITE_TAC[MOD_REFL]];
            REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
            EXISTS_TAC `k + 1` THEN ARITH_TAC]]]];
    REPEAT GEN_TAC THEN
    INTRO_TAC
     "left right jpositive bound injective overlap chord1 chord2" THEN
    REWRITE_TAC[SUBSET; IN_CYCLIC_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN INTRO_TAC "@i. i_index edge" THEN
    USE_THEN "edge" SUBST1_TAC THEN REWRITE_TAC[IN_UNION] THEN
    ASM_CASES_TAC `(i:num) < j` THENL
     [DISJ1_TAC THEN
      USE_THEN "left" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      REWRITE_TAC[IN_CYCLIC_EDGES] THEN EXISTS_TAC `i:num` THEN
      CONJ_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN
         `i + 1 < n /\ i + 1 < j + 2 /\
          i < j + 1 /\ i + 1 < j + 1`
        STRIP_ASSUME_TAC THENL
         [ASM_ARITH_TAC;
          ASM_SIMP_TAC[MOD_LT; cyclic_split_left]]];
      ASM_CASES_TAC `(i:num) < n - 1` THENL
       [DISJ2_TAC THEN
        USE_THEN "right" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        REWRITE_TAC[IN_CYCLIC_EDGES] THEN
        EXISTS_TAC `(i:num) - j` THEN CONJ_TAC THENL
         [ASM_ARITH_TAC;
          SUBGOAL_THEN
           `i + 1 < n /\ i - j + 1 < n - j /\
            j + (i - j) = i /\ j + (i - j + 1) = i + 1`
          STRIP_ASSUME_TAC THENL
           [ASM_ARITH_TAC;
            ASM_SIMP_TAC[MOD_LT; cyclic_split_right]]];
        SUBGOAL_THEN `(i:num) = n - 1` SUBST_ALL_TAC THENL
         [ASM_ARITH_TAC;
          DISJ1_TAC THEN
          USE_THEN "left" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          REWRITE_TAC[IN_CYCLIC_EDGES] THEN
          EXISTS_TAC `j + 1` THEN CONJ_TAC THENL
           [ARITH_TAC;
            SUBGOAL_THEN
             `n - 1 + 1 = n /\ (j + 1) + 1 = j + 2`
            STRIP_ASSUME_TAC THENL
             [ASM_ARITH_TAC;
              ASM_REWRITE_TAC[MOD_REFL; cyclic_split_left] THEN
              ASM_ARITH_TAC]]]]]]);;

let RECURSIVE_TRIANGULATED_DISK_BOUNDARY_CYCLE = prove
 (`!V E q:num->A. !n.
        recursive_triangulated_disk V E q n
        ==> simple_graph_cycle E q n`,
  REWRITE_TAC[simple_graph_cycle] THEN
  MESON_TAC[RECURSIVE_TRIANGULATED_DISK_INVARIANTS;
            RECURSIVE_TRIANGULATED_DISK_BOUNDARY_EDGES]);;

let PAIR_FALSE_INJ = prove
 (`!s:A->bool. INJ (\x:A. (x,F)) s (:(A#bool))`,
  REWRITE_TAC[INJ; IN_UNIV; PAIR_EQ] THEN MESON_TAC[]);;

let PAIR_TRUE_NOT_IN_FALSE_IMAGE = prove
 (`!x:A. !s:A->bool. ~((x,T) IN IMAGE (\y:A. (y,F)) s)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_IMAGE; PAIR_EQ] THEN MESON_TAC[]);;

let IMAGE_FST_PAIR_FALSE = prove
 (`!s:A->bool.
        IMAGE (FST:A#bool->A) (IMAGE (\x:A. (x,F)) s) = s`,
  GEN_TAC THEN REWRITE_TAC[GSYM IMAGE_o; o_DEF; IMAGE_ID]);;

let IMAGE_IMAGE_FST_PAIR_FALSE = prove
 (`!s:(A->bool)->bool.
        IMAGE (IMAGE (FST:A#bool->A))
          (IMAGE (IMAGE (\x:A. (x,F))) s) = s`,
  GEN_TAC THEN
  REWRITE_TAC[GSYM IMAGE_o; o_DEF; IMAGE_FST_PAIR_FALSE; IMAGE_ID]);;

let FST_INJ_ON_PAIR_FALSE_IMAGE = prove
 (`!s:A->bool.
        INJ (FST:A#bool->A) (IMAGE (\x:A. (x,F)) s) (:A)`,
  GEN_TAC THEN REWRITE_TAC[INJ; IN_UNIV] THEN
  MAP_EVERY X_GEN_TAC [`u:A#bool`; `v:A#bool`] THEN
  INTRO_TAC "u_image v_image same" THEN
  REMOVE_THEN "u_image" MP_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
  INTRO_TAC "@a. u_pair a_member" THEN
  REMOVE_THEN "v_image" MP_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
  INTRO_TAC "@b. v_pair b_member" THEN
  ASM_REWRITE_TAC[PAIR_EQ] THEN
  TRANS_TAC EQ_TRANS `FST(u:A#bool)` THEN CONJ_TAC THENL
   [MP_TAC(AP_TERM `(\z:A#bool. FST z)`
     (ASSUME `(u:A#bool) = ((a:A),F)`)) THEN
    REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o SYM);
    TRANS_TAC EQ_TRANS `FST(v:A#bool)` THEN CONJ_TAC THENL
     [USE_THEN "same" ACCEPT_TAC;
      MP_TAC(AP_TERM `(\z:A#bool. FST z)`
       (ASSUME `(v:A#bool) = ((b:A),F)`)) THEN
      REWRITE_TAC[]]]);;

let RECURSIVE_TRIANGULATED_DISK_OFFSET_FRESH = prove
 (`!V E q:num->A. !n k x:A.
        recursive_triangulated_disk V E q n /\
        ~(x IN V)
        ==> recursive_triangulated_disk
             V E (\i. q((i + k) MOD n)) n`,
  REPEAT GEN_TAC THEN INTRO_TAC "recursive fresh" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`]
   RECURSIVE_TRIANGULATED_DISK_INVARIANTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "graph nlarge injective boundary" THEN
  SUBGOAL_THEN
   `recursive_triangulated_disk
      (x INSERT V)
      (IMAGE (\u:A. {x,u}) (cyclic_vertices q n) UNION E)
      (\i. if i = 0 then q 0 else if i = 1 then q 1 else x) 3`
  (LABEL_TAC "cap_recursive") THENL
   [MATCH_MP_TAC RECURSIVE_TRIANGULATED_DISK_CAP THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`x INSERT (V:A->bool)`;
    `IMAGE (\u:A. {x,u}) (cyclic_vertices q n) UNION
     (E:(A->bool)->bool)`;
    `(\i. if i = 0 then q 0 else if i = 1 then q 1 else x):num->A`]
   RECURSIVE_TRIANGULATED_DISK_3_EXPOSED_PLANE_DISK) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[ARITH_RULE `~(2 = 0)`; ARITH_RULE `~(2 = 1)`] THEN
  INTRO_TAC "@p outer r. cap_disk outer_unbounded apex_boundary" THEN
  MP_TAC(ISPECL
   [`x INSERT (V:A->bool)`;
    `IMAGE (\u:A. {x,u}) (cyclic_vertices q n) UNION
     (E:(A->bool)->bool)`;
    `p:A->real^2`; `straight_edge (p:A->real^2)`;
    `r:num->A`; `3`; `outer:real^2->bool`; `x:A`]
   PLANE_TRIANGULATED_DISK_DELETE_VERTEX_OUTER_COMPONENT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@newouter. newouter_component outer_subset apex_newouter" THEN
  SUBGOAL_THEN `((x:A) INSERT V) DELETE x = V`
  (LABEL_TAC "delete_vertices") THENL
   [USE_THEN "fresh" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `induced_subgraph_edges
      (IMAGE (\u:A. {x,u}) (cyclic_vertices q n) UNION E)
      ((x INSERT V) DELETE x) = E`
  (LABEL_TAC "delete_edges") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `x:A`;
      `cyclic_vertices (q:num->A) n`]
     FINITE_SIMPLE_GRAPH_INSERT_STAR_DELETE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_neighbors
      (IMAGE (\u:A. {x,u}) (cyclic_vertices q n) UNION E) x =
    cyclic_vertices q n`
  (LABEL_TAC "apex_neighbors") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `x:A`;
      `cyclic_vertices (q:num->A) n`]
     FINITE_SIMPLE_GRAPH_INSERT_STAR_NEIGHBORS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle
      (IMAGE (\u:A. {x,u}) (cyclic_vertices q n) UNION E)
      (r:num->A) 3`
  (LABEL_TAC "cap_cycle") THENL
   [MP_TAC(MATCH_MP PLANE_TRIANGULATED_DISK_INVARIANTS
     (ASSUME
       `plane_triangulated_disk
          (x INSERT (V:A->bool))
          (IMAGE (\u:A. {x,u}) (cyclic_vertices q n) UNION E)
          (p:A->real^2) (straight_edge p) (r:num->A) 3
          (outer:real^2->bool)`)) THEN
    INTRO_TAC "_ _ rlarge rinjective redges _ _ _" THEN
    ASM_REWRITE_TAC[simple_graph_cycle];
    ALL_TAC] THEN
  SUBGOAL_THEN
  `cyclic_vertices (r:num->A) 3 DELETE x
    SUBSET cyclic_vertices q n`
  (LABEL_TAC "remaining_subset") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC
     `graph_neighbors
       (IMAGE (\u:A. {x,u}) (cyclic_vertices q n) UNION E) x` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`IMAGE (\u:A. {x,u}) (cyclic_vertices q n) UNION
         (E:(A->bool)->bool)`;
        `r:num->A`; `x:A`]
       TRIANGULAR_CYCLE_DELETE_VERTEX_NEIGHBORS) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[SUBSET_REFL]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`x INSERT (V:A->bool)`;
    `IMAGE (\u:A. {x,u}) (cyclic_vertices q n) UNION
     (E:(A->bool)->bool)`;
    `p:A->real^2`; `straight_edge (p:A->real^2)`;
    `r:num->A`; `3`; `outer:real^2->bool`; `x:A`;
    `newouter:real^2->bool`]
   PLANE_TRIANGULATED_DISK_DELETE_VERTEX_FACE_VERTICES) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "face_vertices") THEN
  SUBGOAL_THEN
   `plane_graph_face_vertices
      (V:A->bool) E p (straight_edge p) newouter =
    cyclic_vertices q n`
  (LABEL_TAC "new_boundary") THENL
   [USE_THEN "face_vertices" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "remaining_subset" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  REMOVE_THEN "face_vertices" (fun _ -> ALL_TAC) THEN
  SUBGOAL_THEN `~bounded(newouter:real^2->bool)`
  (LABEL_TAC "newouter_unbounded") THENL
   [DISCH_THEN(LABEL_TAC "newouter_bounded") THEN
    USE_THEN "outer_unbounded" (MATCH_MP_TAC o NOT_ELIM) THEN
    MATCH_MP_TAC BOUNDED_SUBSET THEN
    EXISTS_TAC `newouter:real^2->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `simple_graph_cycle (E:(A->bool)->bool) q n`
  (LABEL_TAC "boundary_cycle") THENL
   [ACCEPT_TAC(MATCH_MP
     (ISPECL [`V:A->bool`; `E:(A->bool)->bool`;
              `q:num->A`; `n:num`]
       RECURSIVE_TRIANGULATED_DISK_BOUNDARY_CYCLE)
     (ASSUME `recursive_triangulated_disk (V:A->bool) E q n`));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_triangulated_disk
      (V:A->bool) E p (straight_edge p) q n newouter`
  (LABEL_TAC "disk") THENL
   [MP_TAC(ISPECL
     [`x INSERT (V:A->bool)`;
      `IMAGE (\u:A. {x,u}) (cyclic_vertices q n) UNION
       (E:(A->bool)->bool)`;
      `p:A->real^2`; `straight_edge (p:A->real^2)`;
      `r:num->A`; `3`; `outer:real^2->bool`; `x:A`;
      `newouter:real^2->bool`; `q:num->A`; `n:num`]
     PLANE_TRIANGULATED_DISK_DELETE_VERTEX) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `p:A->real^2`; `straight_edge (p:A->real^2)`;
    `(\i. q((i + k) MOD n)):num->A`; `n:num`;
    `newouter:real^2->bool`]
   PLANE_TRIANGULATED_DISK_UNBOUNDED_RECURSIVE) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `p:A->real^2`; `straight_edge (p:A->real^2)`;
      `q:num->A`; `n:num`; `newouter:real^2->bool`; `k:num`]
     PLANE_TRIANGULATED_DISK_OFFSET) THEN
    USE_THEN "disk" ACCEPT_TAC;
    USE_THEN "newouter_unbounded" ACCEPT_TAC]);;

let RECURSIVE_TRIANGULATED_DISK_OFFSET = prove
 (`!V E q:num->A. !n k.
        recursive_triangulated_disk V E q n
        ==> recursive_triangulated_disk
             V E (\i. q((i + k) MOD n)) n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "recursive") THEN
  SUBGOAL_THEN
   `recursive_triangulated_disk
      (IMAGE (\a:A. (a,F)) V)
      (IMAGE (IMAGE (\a:A. (a,F))) E)
      ((\a:A. (a,F)) o q) n`
  (LABEL_TAC "lifted") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `(\a:A. (a,F)):A->A#bool`]
     RECURSIVE_TRIANGULATED_DISK_IMAGE) THEN
    ASM_REWRITE_TAC[PAIR_FALSE_INJ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `recursive_triangulated_disk
      (IMAGE (\a:A. (a,F)) V)
      (IMAGE (IMAGE (\a:A. (a,F))) E)
      (\i. (((\a:A. (a,F)) o q) ((i + k) MOD n))) n`
  (LABEL_TAC "lifted_offset") THENL
   [MATCH_MP_TAC(ISPECL
     [`IMAGE (\a:A. (a,F)) (V:A->bool)`;
      `IMAGE (IMAGE (\a:A. (a,F))) (E:(A->bool)->bool)`;
      `((\a:A. (a,F)) o q):num->A#bool`; `n:num`; `k:num`;
      `((q:num->A) 0,T)`]
     RECURSIVE_TRIANGULATED_DISK_OFFSET_FRESH) THEN
    ASM_REWRITE_TAC[PAIR_TRUE_NOT_IN_FALSE_IMAGE];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`IMAGE (\a:A. (a,F)) (V:A->bool)`;
    `IMAGE (IMAGE (\a:A. (a,F))) (E:(A->bool)->bool)`;
    `(\i. (((\a:A. (a,F)) o q) ((i + k) MOD n))):num->A#bool`;
    `n:num`; `(FST:A#bool->A)`]
   RECURSIVE_TRIANGULATED_DISK_IMAGE) THEN
  ASM_REWRITE_TAC[FST_INJ_ON_PAIR_FALSE_IMAGE;
                  IMAGE_FST_PAIR_FALSE;
                  IMAGE_IMAGE_FST_PAIR_FALSE; o_THM] THEN
  DISCH_THEN(LABEL_TAC "projected") THEN
  SUBGOAL_THEN
   `(FST:A#bool->A) o (\i. ((q:num->A) ((i + k) MOD n),F)) =
    (\i. q((i + k) MOD n))`
   (fun th -> USE_THEN "projected"
     (ACCEPT_TAC o REWRITE_RULE[th])) THEN
  REWRITE_TAC[FUN_EQ_THM; o_THM]);;

(* ------------------------------------------------------------------------- *)
(* Face-orbit surgery under deletion of an edge.                             *)
(* ------------------------------------------------------------------------- *)

(* Deleting points in different invariant fibres performs two independent
   splices in the permutation. *)

let PERMUTATION_DELETE_TWO_APPLY_IN_DIFFERENT_KEYS = prove
 (`!f:A->A. !s x y k:A->B z.
        f permutes s /\
        x IN s /\
        y IN s /\
        z IN s DELETE x DELETE y /\
        (!w. w IN s ==> k(f w) = k w) /\
        ~(k x = k y)
        ==> permutation_delete_two f x y z =
            if f z = x then f x
            else if f z = y then f y
            else f z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "permutation x y z preserves different_keys" THEN
  USE_THEN "z" MP_TAC THEN REWRITE_TAC[IN_DELETE] THEN
  DISCH_THEN(CONJUNCTS_THEN2
   (CONJUNCTS_THEN2 (LABEL_TAC "z_member") (LABEL_TAC "z_not_x"))
   (LABEL_TAC "z_not_y")) THEN
  SUBGOAL_THEN `~(x:A = y)` (LABEL_TAC "x_not_y") THENL
   [ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((f:A->A) x = y)` (LABEL_TAC "fx_not_y") THENL
   [DISCH_THEN(LABEL_TAC "fx_y") THEN
    MP_TAC(SPEC `x:A` (ASSUME
     `!w:A. w IN s ==> (k:A->B) (f w) = k w`)) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((f:A->A) y = x)` (LABEL_TAC "fy_not_x") THENL
   [DISCH_THEN(LABEL_TAC "fy_x") THEN
    MP_TAC(SPEC `y:A` (ASSUME
     `!w:A. w IN s ==> (k:A->B) (f w) = k w`)) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_delete (f:A->A) x permutes (s DELETE x)`
  (LABEL_TAC "first_permutation") THENL
   [MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `permutation_delete (f:A->A) x y = f y`
  (LABEL_TAC "first_y") THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`; `y:A`]
      PERMUTATION_DELETE_APPLY_IN) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_delete (f:A->A) x z =
    if f z = x then f x else f z`
  (LABEL_TAC "first_z") THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`; `z:A`]
      PERMUTATION_DELETE_APPLY_IN) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[permutation_delete_two] THEN
  MP_TAC(ISPECL
   [`permutation_delete (f:A->A) x`; `(s:A->bool) DELETE x`;
    `y:A`; `z:A`] PERMUTATION_DELETE_APPLY_IN) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[];
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_CASES_TAC `(f:A->A) z = x` THEN ASM_REWRITE_TAC[]]);;

let FINITE_SIMPLE_GRAPH_EDGE_DARTS = prove
 (`!V E u v:A.
        finite_simple_graph V E /\ {u,v} IN E
        ==> ~(u = v) /\
            (u,v) IN graph_darts E /\
            (v,u) IN graph_darts E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge" THEN
  SUBGOAL_THEN `(u:A,v) IN graph_darts E`
  (LABEL_TAC "forward") THENL
   [ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v:A,u) IN graph_darts E`
  (LABEL_TAC "reverse") THENL
   [REWRITE_TAC[IN_GRAPH_DARTS] THEN
    SUBGOAL_THEN `{v:A,u} = {u,v}` SUBST1_TAC THENL
     [SET_TAC[];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
   FINITE_SIMPLE_GRAPH_DART) THEN
  ASM_REWRITE_TAC[] THEN MESON_TAC[]);;

let GRAPH_FACE_SUCCESSOR_DELETE_EDGE = prove
 (`!V E r u v d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E /\
        d IN graph_darts (E DELETE {u,v})
        ==> graph_face_successor
              (E DELETE {u,v}) (graph_delete_rotation r u v) d =
            if graph_face_successor E r d = (u,v) then
              graph_face_successor E r (v,u)
            else if graph_face_successor E r d = (v,u) then
              graph_face_successor E r (u,v)
            else graph_face_successor E r d`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation edge dart" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
   FINITE_SIMPLE_GRAPH_EDGE_DARTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "u_not_v forward reverse" THEN
  SUBGOAL_THEN `(d:A#A) IN graph_darts E`
  (LABEL_TAC "old_dart") THENL
   [USE_THEN "dart" MP_TAC THEN
    REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE; IN_DELETE] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(d:A#A) IN
    graph_darts E DELETE (u,v) DELETE (v,u)`
  (LABEL_TAC "reverse_survives") THENL
   [REWRITE_TAC[GSYM GRAPH_DARTS_DELETE_EDGE] THEN
    ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor
      ((E:(A->bool)->bool) DELETE {u,v})
      (graph_delete_rotation (r:(A#A)->A#A) u v) (d:A#A) =
    graph_delete_rotation r u v (reverse_dart d)`
  (LABEL_TAC "new_successor") THENL
   [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_IN THEN
    USE_THEN "dart" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (d:A#A) = r(reverse_dart d)`
  (LABEL_TAC "old_successor") THENL
   [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_IN THEN
    USE_THEN "old_dart" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r ((v:A),(u:A)) = r(u,v)`
  (LABEL_TAC "successor_reverse") THENL
   [ASM_SIMP_TAC[GRAPH_FACE_SUCCESSOR_IN; REVERSE_DART_PAIR];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r ((u:A),(v:A)) = r(v,u)`
  (LABEL_TAC "successor_forward") THENL
   [ASM_SIMP_TAC[GRAPH_FACE_SUCCESSOR_IN; REVERSE_DART_PAIR];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_delete_rotation (r:(A#A)->A#A) (u:A) (v:A)
      (reverse_dart(d:A#A)) =
    if r(reverse_dart d) = ((u:A),(v:A)) then r(u,v)
    else if r(reverse_dart d) = ((v:A),(u:A)) then r(v,u)
    else r(reverse_dart d)`
  (LABEL_TAC "splice") THENL
   [REWRITE_TAC[graph_delete_rotation] THEN
    MATCH_MP_TAC(ISPECL
     [`r:(A#A)->A#A`; `graph_darts E:(A#A)->bool`;
      `((u:A),(v:A))`; `((v:A),(u:A))`;
      `FST:(A#A)->A`; `reverse_dart(d:A#A)`]
     PERMUTATION_DELETE_TWO_APPLY_IN_DIFFERENT_KEYS) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
      USE_THEN "rotation" ACCEPT_TAC;
      USE_THEN "forward" ACCEPT_TAC;
      USE_THEN "reverse" ACCEPT_TAC;
      USE_THEN "reverse_survives" ACCEPT_TAC;
      X_GEN_TAC `w:A#A` THEN DISCH_THEN(LABEL_TAC "w_dart") THEN
      MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `w:A#A`]
       GRAPH_ROTATION_TAIL) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[FST]];
    ALL_TAC] THEN
  USE_THEN "new_successor" SUBST1_TAC THEN
  USE_THEN "splice" SUBST1_TAC THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_FACE_SUCCESSOR_DELETE_EDGE_UNCHANGED = prove
 (`!V E r u v d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E /\
        d IN graph_darts (E DELETE {u,v}) /\
        ~(graph_face_successor E r d = (u,v)) /\
        ~(graph_face_successor E r d = (v,u))
        ==> graph_face_successor
              (E DELETE {u,v}) (graph_delete_rotation r u v) d =
            graph_face_successor E r d`,
  REPEAT GEN_TAC THEN INTRO_TAC
   "graph rotation edge dart not_forward not_reverse" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `d:A#A`] GRAPH_FACE_SUCCESSOR_DELETE_EDGE) THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_FACE_SUCCESSOR_DELETE_EDGE_FORWARD_SPLICE = prove
 (`!V E r u v d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E /\
        d IN graph_darts (E DELETE {u,v}) /\
        graph_face_successor E r d = (u,v)
        ==> graph_face_successor
              (E DELETE {u,v}) (graph_delete_rotation r u v) d =
            graph_face_successor E r (v,u)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation edge dart successor" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `d:A#A`] GRAPH_FACE_SUCCESSOR_DELETE_EDGE) THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_FACE_SUCCESSOR_DELETE_EDGE_REVERSE_SPLICE = prove
 (`!V E r u v d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E /\
        d IN graph_darts (E DELETE {u,v}) /\
        graph_face_successor E r d = (v,u)
        ==> graph_face_successor
              (E DELETE {u,v}) (graph_delete_rotation r u v) d =
            graph_face_successor E r (u,v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation edge dart successor" THEN
  SUBGOAL_THEN `~(u:A = v)` (LABEL_TAC "distinct") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_EDGE_DARTS) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `d:A#A`] GRAPH_FACE_SUCCESSOR_DELETE_EDGE) THEN
  ASM_REWRITE_TAC[PAIR_EQ] THEN ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The face-count bound under deletion of an edge.                           *)
(* ------------------------------------------------------------------------- *)

let CARD_GRAPH_FACES_DELETE_EDGE_BOUND = prove
 (`!V E r u v:A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E
        ==> CARD(graph_faces E r) <=
            CARD
             (graph_faces
               (E DELETE {u,v}) (graph_delete_rotation r u v)) + 1`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation edge" THEN
  ABBREV_TAC
   `f:(A#A)->A#A =
      graph_face_successor (E:(A->bool)->bool) (r:(A#A)->A#A)` THEN
  ABBREV_TAC
   `g:(A#A)->A#A =
      graph_face_successor
       (E DELETE {u,v})
       (graph_delete_rotation (r:(A#A)->A#A) (u:A) (v:A))` THEN
  SUBGOAL_THEN
   `~(u:A = v) /\
    ((u:A),(v:A)) IN graph_darts E /\
    ((v:A),(u:A)) IN graph_darts E`
  (CONJUNCTS_THEN2 (LABEL_TAC "distinct")
    (CONJUNCTS_THEN2 (LABEL_TAC "forward") (LABEL_TAC "reverse"))) THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_EDGE_DARTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(graph_darts (E:(A->bool)->bool))`
  (LABEL_TAC "finite_darts") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(f:(A#A)->A#A) permutes graph_darts E`
  (LABEL_TAC "old_permutation") THENL
   [EXPAND_TAC "f" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(g:(A#A)->A#A) permutes
    (graph_darts E DELETE (u,v) DELETE (v,u))`
  (LABEL_TAC "new_permutation") THENL
   [REWRITE_TAC[GSYM GRAPH_DARTS_DELETE_EDGE] THEN
    EXPAND_TAC "g" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`] GRAPH_DELETE_ROTATION) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((f:(A#A)->A#A) (u,v) = (u,v))`
  (LABEL_TAC "nonfixed") THENL
   [EXPAND_TAC "f" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `((u:A),(v:A))`] GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A#A.
        z IN graph_darts E DELETE (u,v) DELETE (v,u) /\
        ~((f:(A#A)->A#A) z = (u,v)) /\
        ~(f z = (v,u))
        ==> (g:(A#A)->A#A) z = f z`
  (LABEL_TAC "agree") THENL
   [X_GEN_TAC `z:A#A` THEN
    INTRO_TAC "z not_forward not_reverse" THEN
    EXPAND_TAC "f" THEN EXPAND_TAC "g" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`; `z:A#A`]
     GRAPH_FACE_SUCCESSOR_DELETE_EDGE_UNCHANGED) THEN
    ASM_REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`f:(A#A)->A#A`; `g:(A#A)->A#A`;
    `graph_darts E:(A#A)->bool`; `((u:A),(v:A))`; `((v:A),(u:A))`]
   PERMUTATION_ORBITS_TWO_POINT_SURGERY_LE) THEN
  ASM_REWRITE_TAC[PAIR_EQ] THEN
  EXPAND_TAC "f" THEN EXPAND_TAC "g" THEN
  REWRITE_TAC[GSYM GRAPH_DARTS_DELETE_EDGE;
              GSYM GRAPH_FACES_AS_PERMUTATION_ORBITS]);;

let CARD_GRAPH_FACES_DELETE_CONSECUTIVE_EDGE = prove
 (`!V E r u v:A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E /\
        graph_face_successor E r (u,v) = (v,u) /\
        ~(graph_face_successor E r (v,u) = (u,v))
        ==> CARD
             (graph_faces
               (E DELETE {u,v}) (graph_delete_rotation r u v)) =
            CARD(graph_faces E r)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation edge forward_successor not_two_cycle" THEN
  ABBREV_TAC
   `f:(A#A)->A#A =
      graph_face_successor (E:(A->bool)->bool) (r:(A#A)->A#A)` THEN
  ABBREV_TAC
   `g:(A#A)->A#A =
      graph_face_successor
       (E DELETE {u,v})
       (graph_delete_rotation (r:(A#A)->A#A) u v)` THEN
  ABBREV_TAC
   `h:(A#A)->A#A =
      permutation_delete_two f (u,v) (v,u)` THEN
  ABBREV_TAC `s:(A#A)->bool = graph_darts E` THEN
  SUBGOAL_THEN
   `~(u:A = v) /\
    ((u:A),(v:A)) IN s /\
    ((v:A),(u:A)) IN s`
  (CONJUNCTS_THEN2 (LABEL_TAC "distinct")
    (CONJUNCTS_THEN2 (LABEL_TAC "forward") (LABEL_TAC "reverse"))) THENL
   [EXPAND_TAC "s" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_EDGE_DARTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(s:(A#A)->bool)`
  (LABEL_TAC "finite_darts") THENL
   [EXPAND_TAC "s" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(f:(A#A)->A#A) permutes s`
  (LABEL_TAC "face_permutation") THENL
   [EXPAND_TAC "f" THEN EXPAND_TAC "s" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((f:(A#A)->A#A) (u,v) = (u,v))`
  (LABEL_TAC "forward_nonfixed") THENL
   [EXPAND_TAC "f" THEN ASM_REWRITE_TAC[PAIR_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((f:(A#A)->A#A) (v,u) = (v,u))`
  (LABEL_TAC "reverse_nonfixed") THENL
   [EXPAND_TAC "f" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `(v:A,u:A)`] GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS;
                    SET_RULE `{v:A,u} = {u,v}`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_delete (f:(A#A)->A#A) (u,v) (v,u) = f(v,u)`
  (LABEL_TAC "deleted_reverse") THENL
   [MP_TAC(ISPECL
     [`f:(A#A)->A#A`; `s:(A#A)->bool`;
      `(u:A,v:A)`; `(v:A,u:A)`]
     PERMUTATION_DELETE_APPLY_IN) THEN
    ASM_REWRITE_TAC[PAIR_EQ] THEN
    EXPAND_TAC "f" THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(permutation_delete (f:(A#A)->A#A) (u,v) (v,u) =
      (v,u))`
  (LABEL_TAC "deleted_reverse_nonfixed") THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD
     (permutation_orbits (h:(A#A)->A#A)
       ((s:(A#A)->bool) DELETE (u:A,v:A) DELETE (v:A,u:A))) =
    CARD(permutation_orbits (f:(A#A)->A#A) s)`
  (LABEL_TAC "exact_surgery") THENL
   [EXPAND_TAC "h" THEN
    MATCH_MP_TAC(ISPECL
     [`f:(A#A)->A#A`; `s:(A#A)->bool`;
      `(u:A,v:A)`; `(v:A,u:A)`]
     PERMUTATION_DELETE_TWO_ORBIT_COUNT) THEN
    ASM_REWRITE_TAC[PAIR_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A#A.
      z IN s DELETE (u,v) DELETE (v,u)
      ==> (g:(A#A)->A#A) z = h z`
  (LABEL_TAC "agree") THENL
   [X_GEN_TAC `z:A#A` THEN
    REWRITE_TAC[IN_DELETE] THEN
    INTRO_TAC "(z_member z_not_forward) z_not_reverse" THEN
    SUBGOAL_THEN `~((f:(A#A)->A#A) z = (v,u))`
    (LABEL_TAC "not_reverse_image") THENL
     [DISCH_THEN(LABEL_TAC "reverse_image") THEN
      MP_TAC(MATCH_MP
       (ISPECL [`f:(A#A)->A#A`; `s:(A#A)->bool`]
        PERMUTES_INJECTIVE)
       (ASSUME `(f:(A#A)->A#A) permutes s`)) THEN
      DISCH_THEN(MP_TAC o SPECL [`z:A#A`; `(u:A,v:A)`]) THEN
      EXPAND_TAC "f" THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(g:(A#A)->A#A) z =
      if f z = (u,v) then f(v,u) else f z`
    (LABEL_TAC "new_value") THENL
     [EXPAND_TAC "g" THEN EXPAND_TAC "f" THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `u:A`; `v:A`; `z:A#A`]
       GRAPH_FACE_SUCCESSOR_DELETE_EDGE) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE; IN_DELETE];
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    ABBREV_TAC
     `p:(A#A)->A#A =
        permutation_delete (f:(A#A)->A#A) (u,v)` THEN
    SUBGOAL_THEN
     `(p:(A#A)->A#A) z =
      if f z = (u,v) then f(u,v) else f z`
    (LABEL_TAC "first_value") THENL
     [EXPAND_TAC "p" THEN
      MP_TAC(ISPECL
       [`f:(A#A)->A#A`; `s:(A#A)->bool`;
        `(u:A,v:A)`; `z:A#A`]
       PERMUTATION_DELETE_APPLY_IN) THEN
      ASM_REWRITE_TAC[IN_DELETE];
      ALL_TAC] THEN
    SUBGOAL_THEN `(p:(A#A)->A#A) (v,u) = f(v,u)`
    (LABEL_TAC "reverse_value") THENL
     [EXPAND_TAC "p" THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(p:(A#A)->A#A) permutes (s DELETE (u,v))`
    (LABEL_TAC "first_permutation") THENL
     [EXPAND_TAC "p" THEN
      MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(h:(A#A)->A#A) z =
      if p z = (v,u) then p(v,u) else p z`
    (LABEL_TAC "second_value") THENL
     [EXPAND_TAC "h" THEN
      REWRITE_TAC[permutation_delete_two] THEN
      MP_TAC(ISPECL
       [`p:(A#A)->A#A`; `(s:(A#A)->bool) DELETE (u,v)`;
        `(v:A,u:A)`; `z:A#A`]
       PERMUTATION_DELETE_APPLY_IN) THEN
      ASM_REWRITE_TAC[IN_DELETE; PAIR_EQ];
      ALL_TAC] THEN
    USE_THEN "new_value" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "second_value" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "first_value" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "reverse_value" (fun th -> REWRITE_TAC[th]) THEN
    EXPAND_TAC "f" THEN
    ASM_CASES_TAC
     `graph_face_successor E r z = ((u:A),(v:A))` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbits (g:(A#A)->A#A)
      ((s:(A#A)->bool) DELETE (u:A,v:A) DELETE (v:A,u:A)) =
    permutation_orbits (h:(A#A)->A#A)
      (s DELETE (u,v) DELETE (v,u))`
  (LABEL_TAC "same_orbits") THENL
   [MATCH_MP_TAC(ISPECL
     [`h:(A#A)->A#A`; `g:(A#A)->A#A`;
      `(s:(A#A)->bool) DELETE (u,v) DELETE (v,u)`]
     PERMUTATION_ORBITS_EQ_ON) THEN
    CONJ_TAC THENL
     [EXPAND_TAC "h" THEN
      MATCH_MP_TAC PERMUTATION_DELETE_TWO_PERMUTES THEN
      ASM_REWRITE_TAC[PAIR_EQ];
      USE_THEN "agree" ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[GRAPH_FACES_AS_PERMUTATION_ORBITS;
              GRAPH_DARTS_DELETE_EDGE] THEN
  EXPAND_TAC "g" THEN EXPAND_TAC "f" THEN EXPAND_TAC "s" THEN
  USE_THEN "same_orbits" (fun th -> REWRITE_TAC[th]) THEN
  ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Euler-planar rotations under deletion of a nonseparating edge.            *)
(* ------------------------------------------------------------------------- *)

let FINITE_SIMPLE_GRAPH_DELETE_EDGE = prove
 (`!V E e.
        finite_simple_graph (V:A->bool) E
        ==> finite_simple_graph V (E DELETE e)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[finite_simple_graph] THEN
  INTRO_TAC "finite_vertices finite_edges edge_property" THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "finite_vertices" ACCEPT_TAC;
    ASM_REWRITE_TAC[FINITE_DELETE];
    X_GEN_TAC `d:A->bool` THEN REWRITE_TAC[IN_DELETE] THEN
    INTRO_TAC "d_edge d_distinct" THEN
    USE_THEN "edge_property" (MATCH_MP_TAC o SPEC `d:A->bool`) THEN
    USE_THEN "d_edge" ACCEPT_TAC]);;

let GRAPH_REACHABLE_MONO = prove
  (`!E E' u v:A.
        E SUBSET E' /\ graph_reachable E u v
        ==> graph_reachable E' u v`,
  REPEAT GEN_TAC THEN INTRO_TAC "subset reachable" THEN
  USE_THEN "reachable" MP_TAC THEN
  REWRITE_TAC[graph_reachable] THEN
  DISCH_THEN(LABEL_TAC "rtc") THEN
  REWRITE_TAC[graph_reachable] THEN
  MP_TAC(ISPECL
   [`\x y:A. {x,y} IN E`; `\x y:A. {x,y} IN E'`]
   RTC_MONO) THEN
  ANTS_TAC THENL
   [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    DISCH_THEN(LABEL_TAC "edge") THEN
    USE_THEN "subset" MP_TAC THEN
    USE_THEN "edge" MP_TAC THEN SET_TAC[];
    DISCH_THEN(MP_TAC o SPECL [`u:A`; `v:A`]) THEN
    ASM_REWRITE_TAC[]]);;

let CONNECTED_GRAPH_MONO = prove
 (`!V E E'.
        connected_graph (V:A->bool) E /\ E SUBSET E'
        ==> connected_graph V E'`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected subset" THEN
  REWRITE_TAC[connected_graph] THEN
  MAP_EVERY X_GEN_TAC [`u:A`; `v:A`] THEN
  INTRO_TAC "u_vertex v_vertex" THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `E':(A->bool)->bool`; `u:A`; `v:A`]
   GRAPH_REACHABLE_MONO) THEN
  CONJ_TAC THENL
   [USE_THEN "subset" ACCEPT_TAC;
    USE_THEN "connected" MP_TAC THEN
    REWRITE_TAC[connected_graph] THEN
    DISCH_THEN(MP_TAC o SPECL [`u:A`; `v:A`]) THEN
    ASM_REWRITE_TAC[]]);;

(* Face surgery loses at most one face.  Together with the old Euler
   equality and the universal connected Euler bound, this forces the
   deleted rotation to satisfy Euler's formula as well. *)

let EULER_PLANAR_ROTATION_DELETE_EDGE_CONNECTED = prove
 (`!V E r u v:A.
        euler_planar_rotation V E r /\
        {u,v} IN E /\
        connected_graph V (E DELETE {u,v})
        ==> euler_planar_rotation
             V (E DELETE {u,v}) (graph_delete_rotation r u v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler edge connected" THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph rotation formula" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) (E DELETE {u,v})`
  (LABEL_TAC "deleted_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_DELETE_EDGE THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_rotation
     (E DELETE {u,v})
     (graph_delete_rotation (r:(A#A)->A#A) u v)`
  (LABEL_TAC "deleted_rotation") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`] GRAPH_DELETE_ROTATION) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `u IN V /\ v IN V /\ ~(u:A = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
    (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex") (LABEL_TAC "distinct"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((E DELETE {u,v}):(A->bool)->bool) = {})`
  (LABEL_TAC "deleted_edges_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "deleted_edges_empty") THEN
    SUBGOAL_THEN
     `graph_reachable
       ((E DELETE {u,v}):(A->bool)->bool) (u:A) (v:A)`
    (LABEL_TAC "reachable") THENL
     [USE_THEN "connected" MP_TAC THEN
      REWRITE_TAC[connected_graph] THEN
      DISCH_THEN(MP_TAC o SPECL [`u:A`; `v:A`]) THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN `(u:A) = v` (LABEL_TAC "equal") THENL
       [USE_THEN "deleted_edges_empty" (fun empty_th ->
         USE_THEN "reachable" (MP_TAC o REWRITE_RULE[empty_th])) THEN
        REWRITE_TAC[GRAPH_REACHABLE_EMPTY];
        USE_THEN "equal" SUBST_ALL_TAC THEN
        USE_THEN "distinct" MP_TAC THEN REWRITE_TAC[]]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(E:(A->bool)->bool = {})`
  (LABEL_TAC "edges_nonempty") THENL
   [USE_THEN "edge" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(E:(A->bool)->bool)`
  (LABEL_TAC "finite_edges") THENL
   [USE_THEN "graph"
     (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o
      REWRITE_RULE[finite_simple_graph]);
    ALL_TAC] THEN
  SUBGOAL_THEN `0 < CARD(E:(A->bool)->bool)`
  (LABEL_TAC "edges_positive") THENL
   [SUBGOAL_THEN `~(CARD(E:(A->bool)->bool) = 0)` MP_TAC THENL
     [ASM_SIMP_TAC[CARD_EQ_0];
      ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD((E DELETE {u,v}):(A->bool)->bool) = CARD E - 1`
  (LABEL_TAC "deleted_edge_count") THENL
   [MP_TAC(ISPECL
     [`{u:A,v}:A->bool`; `E:(A->bool)->bool`] CARD_DELETE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(graph_faces (E:(A->bool)->bool) r) <=
    CARD
     (graph_faces
       (E DELETE {u,v})
       (graph_delete_rotation (r:(A#A)->A#A) u v)) + 1`
  (LABEL_TAC "face_bound") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`] CARD_GRAPH_FACES_DELETE_EDGE_BOUND) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD((E DELETE {u,v}):(A->bool)->bool) + 2 <=
    CARD(V:A->bool) +
    CARD
     (graph_map_faces
       V (E DELETE {u,v})
       (graph_delete_rotation (r:(A#A)->A#A) u v))`
  (LABEL_TAC "saturates") THENL
   [USE_THEN "formula" MP_TAC THEN
    USE_THEN "face_bound" MP_TAC THEN
    REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `(E DELETE {u,v}):(A->bool)->bool`;
    `graph_delete_rotation (r:(A#A)->A#A) u v`]
   GRAPH_EULER_FORMULA_EQ_SATURATES_BOUND) THEN
  ASM_REWRITE_TAC[]);;

(* A connected target subgraph can be reached by deleting all surplus edges:
   every intermediate graph still contains the target and hence stays
   connected. *)

let EULER_PLANAR_ROTATION_SUBSET_CONNECTED = prove
 (`!V E E' r:(A#A)->A#A.
        E SUBSET E' /\
        connected_graph V E /\
        euler_planar_rotation V E' r
        ==> ?r':(A#A)->A#A. euler_planar_rotation V E r'`,
  REPEAT GEN_TAC THEN INTRO_TAC "subset connected euler" THEN
  SUBGOAL_THEN `FINITE(E':(A->bool)->bool)`
  (LABEL_TAC "finite_supergraph") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation; finite_simple_graph] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!D:(A->bool)->bool.
        FINITE D
        ==> DISJOINT D E
        ==> !s:(A#A)->A#A.
              euler_planar_rotation V (E UNION D) s
              ==> ?s':(A#A)->A#A. euler_planar_rotation V E s'`
  (LABEL_TAC "delete_surplus") THENL
   [MATCH_MP_TAC FINITE_INDUCT_STRONG THEN CONJ_TAC THENL
     [REWRITE_TAC[DISJOINT_EMPTY; UNION_EMPTY] THEN
      X_GEN_TAC `s:(A#A)->A#A` THEN
      DISCH_THEN(LABEL_TAC "base_euler") THEN
      EXISTS_TAC `s:(A#A)->A#A` THEN
      ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC
       [`e:A->bool`; `D:(A->bool)->bool`] THEN
      INTRO_TAC "induction fresh finite_D" THEN
      DISCH_THEN(LABEL_TAC "disjoint") THEN
      X_GEN_TAC `s:(A#A)->A#A` THEN
      DISCH_THEN(LABEL_TAC "extended_euler") THEN
      SUBGOAL_THEN
       `~((e:A->bool) IN E) /\ DISJOINT D E`
      (CONJUNCTS_THEN2 (LABEL_TAC "not_in_base")
        (LABEL_TAC "tail_disjoint")) THENL
       [USE_THEN "disjoint" MP_TAC THEN
        REWRITE_TAC[DISJOINT] THEN SET_TAC[];
        ALL_TAC] THEN
      USE_THEN "extended_euler"
       (MP_TAC o REWRITE_RULE[euler_planar_rotation]) THEN
      INTRO_TAC "extended_graph extended_rotation extended_formula" THEN
      SUBGOAL_THEN
       `(e:A->bool) IN E UNION (e INSERT D)`
      (LABEL_TAC "surplus_edge") THENL
       [SET_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E UNION (e INSERT D):(A->bool)->bool`;
        `e:A->bool`] FINITE_SIMPLE_GRAPH_EDGE) THEN
      ASM_REWRITE_TAC[] THEN
      INTRO_TAC
       "@u v. u_vertex v_vertex distinct edge_pair" THEN
      USE_THEN "edge_pair" SUBST_ALL_TAC THEN
      SUBGOAL_THEN
       `(E UNION ({u:A,v} INSERT D)) DELETE {u,v} = E UNION D`
      (LABEL_TAC "delete_edge") THENL
       [USE_THEN "not_in_base" MP_TAC THEN
        USE_THEN "fresh" MP_TAC THEN SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `connected_graph (V:A->bool) (E UNION D)`
      (LABEL_TAC "intermediate_connected") THENL
       [MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
        `E UNION D:(A->bool)->bool`] CONNECTED_GRAPH_MONO) THEN
        CONJ_TAC THENL
         [ASM_REWRITE_TAC[];
          SET_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `euler_planar_rotation
         (V:A->bool) (E UNION D)
         (graph_delete_rotation (s:(A#A)->A#A) u v)`
      (LABEL_TAC "deleted_euler") THENL
       [USE_THEN "delete_edge" (SUBST1_TAC o SYM) THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E UNION ({u:A,v} INSERT D):(A->bool)->bool`;
          `s:(A#A)->A#A`; `u:A`; `v:A`]
         EULER_PLANAR_ROTATION_DELETE_EDGE_CONNECTED) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      REMOVE_THEN "induction" (fun induction_th ->
       USE_THEN "tail_disjoint" (fun disjoint_th ->
        MP_TAC(MP induction_th disjoint_th))) THEN
      DISCH_THEN
       (MP_TAC o
        SPEC `graph_delete_rotation (s:(A#A)->A#A) u v`) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE((E' DIFF E):(A->bool)->bool)`
  (LABEL_TAC "finite_surplus") THENL
   [MATCH_MP_TAC FINITE_DIFF THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `DISJOINT
     ((E' DIFF E):(A->bool)->bool) (E:(A->bool)->bool)`
  (LABEL_TAC "surplus_disjoint") THENL
   [REWRITE_TAC[DISJOINT] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `E UNION (E' DIFF E) = (E':(A->bool)->bool)`
  (LABEL_TAC "recover_supergraph") THENL
   [USE_THEN "subset" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  REMOVE_THEN "delete_surplus" (fun deletion_th ->
   USE_THEN "finite_surplus" (fun finite_th ->
    USE_THEN "surplus_disjoint" (fun disjoint_th ->
     MP_TAC
      (MP
       (MP
        (SPEC `(E' DIFF E):(A->bool)->bool` deletion_th)
        finite_th)
       disjoint_th)))) THEN
  DISCH_THEN(MP_TAC o SPEC `r:(A#A)->A#A`) THEN
  USE_THEN "recover_supergraph" (fun th -> ASM_REWRITE_TAC[th]));;

(* ------------------------------------------------------------------------- *)
(* Euler-planar rotations under deletion of a pendant vertex.                *)
(*                                                                           *)
(* Deleting the pendant edge removes two consecutive darts from one face,    *)
(* so the face count is unchanged.  One vertex and one edge disappear, and   *)
(* Euler's formula is therefore preserved.                                   *)
(* ------------------------------------------------------------------------- *)

let DELETE_SINGLETON_UNION = prove
 (`!E F a:A. ~(a IN F) /\ E = {a} UNION F ==> E DELETE a = F`,
  REPEAT GEN_TAC THEN INTRO_TAC "not_member decomposition" THEN
  USE_THEN "decomposition" SUBST1_TAC THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_SING] THEN
  X_GEN_TAC `x:A` THEN
  ASM_CASES_TAC `(x:A) = a` THEN ASM_REWRITE_TAC[]);;

let FINITE_SIMPLE_GRAPH_EDGE_DELETE_NONEMPTY_PAIR_PROPER = prove
 (`!V E u v:A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(E DELETE {u,v} = {})
        ==> ~({u,v} = V)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge remainder" THEN
  DISCH_THEN(LABEL_TAC "all_vertices") THEN
  SUBGOAL_THEN `?e:A->bool. e IN E DELETE {u,v}`
  (X_CHOOSE_THEN `e:A->bool` (LABEL_TAC "other_edge")) THENL
   [USE_THEN "remainder" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`]
   FINITE_SIMPLE_GRAPH_EDGE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "other_edge" MP_TAC THEN SET_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `a:A`
     (X_CHOOSE_THEN `b:A` (LABEL_TAC "edge_data")))] THEN
  USE_THEN "edge_data" MP_TAC THEN
  USE_THEN "other_edge" MP_TAC THEN
  USE_THEN "all_vertices" MP_TAC THEN
  REWRITE_TAC[IN_DELETE] THEN
  SET_TAC[]);;

let OUTGOING_DARTS_EQ_SINGLETON_NEIGHBOR = prove
 (`!E u v:A.
        graph_neighbors E v = {u}
        ==> outgoing_darts E v = {(v,u)}`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "neighbors") THEN
  REWRITE_TAC[EXTENSION; FORALL_PAIR_THM; IN_OUTGOING_DARTS;
              IN_GRAPH_DARTS; FST; IN_SING; PAIR_EQ] THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
  ASM_CASES_TAC `(x:A) = v` THEN ASM_REWRITE_TAC[] THEN
  ONCE_REWRITE_TAC[GSYM IN_GRAPH_NEIGHBORS] THEN
  ASM_REWRITE_TAC[IN_SING]);;

let CONNECTED_GRAPH_PENDANT_OTHER_DART = prove
 (`!V E u v:A.
        finite_simple_graph V E /\
        connected_graph V E /\
        graph_neighbors E v = {u} /\
        ~(E DELETE {u,v} = {})
        ==> ?w. (u,w) IN graph_darts E /\ ~(w = v)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph connected neighbors remainder" THEN
  SUBGOAL_THEN `({u:A,v}:A->bool) IN E` (LABEL_TAC "edge") THENL
   [ONCE_REWRITE_TAC[SET_RULE `{u:A,v} = {v,u}`] THEN
    REWRITE_TAC[GSYM IN_GRAPH_NEIGHBORS] THEN
    ASM_REWRITE_TAC[IN_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN `u IN V /\ v IN V /\ ~(u:A = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
    (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex") (LABEL_TAC "distinct"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?x y:A.
        x IN V DIFF {u,v} /\
        y IN {u,v} /\
        {x,y} IN E`
  (X_CHOOSE_THEN `x:A`
   (X_CHOOSE_THEN `y:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "outside")
     (CONJUNCTS_THEN2 (LABEL_TAC "y_pair")
      (LABEL_TAC "crossing"))))) THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `{u:A,v}`; `u:A`]
     CONNECTED_GRAPH_CROSSING_EDGE) THEN
    ASM_REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_INSERT] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_EDGE_DELETE_NONEMPTY_PAIR_PROPER) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(y:A) = u` (LABEL_TAC "y_is_u") THENL
   [ASM_CASES_TAC `(y:A) = u` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(y:A) = v` (LABEL_TAC "y_is_v") THENL
     [USE_THEN "y_pair" MP_TAC THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(x:A) IN graph_neighbors E v`
    (LABEL_TAC "x_neighbor") THENL
     [REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
      USE_THEN "y_is_v" SUBST_ALL_TAC THEN
      ONCE_REWRITE_TAC[SET_RULE `{v:A,x} = {x,v}`] THEN
      USE_THEN "crossing" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(x:A) = u` (LABEL_TAC "x_is_u") THENL
     [USE_THEN "x_neighbor" MP_TAC THEN
      USE_THEN "neighbors" (fun th -> REWRITE_TAC[th; IN_SING]);
      ALL_TAC] THEN
    USE_THEN "outside" MP_TAC THEN
    REWRITE_TAC[IN_DIFF; IN_INSERT; IN_SING] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `x:A` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[IN_GRAPH_DARTS] THEN
    USE_THEN "y_is_u" SUBST_ALL_TAC THEN
    ONCE_REWRITE_TAC[SET_RULE `{u:A,x} = {x,u}`] THEN
    USE_THEN "crossing" ACCEPT_TAC;
    USE_THEN "outside" MP_TAC THEN
    REWRITE_TAC[IN_DIFF; IN_INSERT; IN_SING] THEN
    MESON_TAC[]]);;

let GRAPH_FACE_SUCCESSOR_PAIR = prove
 (`!E r u v:A.
        (v,u) IN graph_darts E
        ==> graph_face_successor E r (v,u) = r(u,v)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "dart") THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `(v:A,u:A)`]
   GRAPH_FACE_SUCCESSOR_IN) THEN
  ASM_REWRITE_TAC[REVERSE_DART_PAIR]);;

let GRAPH_FACE_SUCCESSOR_PENDANT = prove
 (`!V E r u v:A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        connected_graph V E /\
        graph_neighbors E v = {u} /\
        ~(E DELETE {u,v} = {})
        ==> graph_face_successor E r (u,v) = (v,u) /\
            ~(graph_face_successor E r (v,u) = (u,v))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation connected neighbors remainder" THEN
  SUBGOAL_THEN `({u:A,v}:A->bool) IN E` (LABEL_TAC "edge") THENL
   [ONCE_REWRITE_TAC[SET_RULE `{u:A,v} = {v,u}`] THEN
    REWRITE_TAC[GSYM IN_GRAPH_NEIGHBORS] THEN
    ASM_REWRITE_TAC[IN_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((u:A),(v:A)) IN graph_darts E /\
    ((v:A),(u:A)) IN graph_darts E`
  (CONJUNCTS_THEN2 (LABEL_TAC "forward_dart")
    (LABEL_TAC "reverse_dart")) THENL
   [ASM_REWRITE_TAC[IN_GRAPH_DARTS;
                    SET_RULE `{v:A,u} = {u,v}`];
    ALL_TAC] THEN
  SUBGOAL_THEN `outgoing_darts E (v:A) = {(v,u)}`
  (LABEL_TAC "pendant_darts") THENL
   [MATCH_MP_TAC OUTGOING_DARTS_EQ_SINGLETON_NEIGHBOR THEN
    USE_THEN "neighbors" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) (v,u) IN outgoing_darts E v`
  (LABEL_TAC "rotated_reverse") THENL
   [REWRITE_TAC[IN_OUTGOING_DARTS] THEN CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_ROTATION_IN THEN ASM_REWRITE_TAC[];
      MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `(v:A,u:A)`]
       GRAPH_ROTATION_TAIL) THEN
      ASM_REWRITE_TAC[FST]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:(A#A)->A#A) (v,u) = (v,u)`
  (LABEL_TAC "reverse_fixed") THENL
   [USE_THEN "rotated_reverse" MP_TAC THEN
    USE_THEN "pendant_darts" (fun th -> REWRITE_TAC[th; IN_SING]);
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `v:A`; `u:A`]
     GRAPH_FACE_SUCCESSOR_PAIR) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "two_cycle") THEN
  SUBGOAL_THEN `(r:(A#A)->A#A) (u,v) = (u,v)`
  (LABEL_TAC "forward_fixed") THENL
   [TRANS_TAC EQ_TRANS
     `graph_face_successor E (r:(A#A)->A#A) (v,u)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC EQ_SYM THEN
      MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `u:A`; `v:A`]
       GRAPH_FACE_SUCCESSOR_PAIR) THEN
      USE_THEN "reverse_dart" ACCEPT_TAC;
      USE_THEN "two_cycle" ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
   CONNECTED_GRAPH_PENDANT_OTHER_DART) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "other_dart")
    (LABEL_TAC "other_head"))) THEN
  SUBGOAL_THEN
   `?n. ITER n (r:(A#A)->A#A) (u,v) = (u,w)`
  (X_CHOOSE_THEN `n:num` (LABEL_TAC "orbit")) THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `(u:A,v:A)`; `(u:A,w:A)`]
     GRAPH_ROTATION_ORBIT) THEN
    ASM_REWRITE_TAC[FST];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `ITER n (r:(A#A)->A#A) (u,v) = (u,v)`
  (LABEL_TAC "fixed_iter") THENL
   [MATCH_MP_TAC ITER_FIXPOINT THEN
    USE_THEN "forward_fixed" ACCEPT_TAC;
    ALL_TAC] THEN
  REMOVE_THEN "fixed_iter" (fun fixed_th ->
   REMOVE_THEN "orbit" (fun orbit_th ->
    MP_TAC(TRANS (SYM fixed_th) orbit_th))) THEN
  REWRITE_TAC[PAIR_EQ] THEN ASM_REWRITE_TAC[]);;

let FINITE_SIMPLE_GRAPH_PENDANT_DELETE_EDGE = prove
 (`!V E u v:A.
        finite_simple_graph V E /\
        v IN V /\
        graph_neighbors E v = {u}
        ==> E DELETE {u,v} =
            induced_subgraph_edges E (V DELETE v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph v_vertex neighbors" THEN
  SUBGOAL_THEN `({u:A,v}:A->bool) IN E` (LABEL_TAC "edge") THENL
   [ONCE_REWRITE_TAC[SET_RULE `{u:A,v} = {v,u}`] THEN
    REWRITE_TAC[GSYM IN_GRAPH_NEIGHBORS] THEN
    ASM_REWRITE_TAC[IN_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(u:A = v)` (LABEL_TAC "distinct") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `v:A`]
   FINITE_SIMPLE_GRAPH_DELETE_VERTEX_EDGES) THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[IMAGE_CLAUSES] THEN
  DISCH_THEN(fun th ->
   LABEL_TAC "decomposition"
    (ONCE_REWRITE_RULE[SET_RULE `{v:A,u} = {u,v}`] th)) THEN
  SUBGOAL_THEN
   `~(({u:A,v}:A->bool) IN
      induced_subgraph_edges E (V DELETE v))`
  (LABEL_TAC "edge_not_old") THENL
   [REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES; SUBSET; IN_DELETE] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "subset")) THEN
    USE_THEN "subset" (MP_TAC o SPEC `v:A`) THEN
    REWRITE_TAC[IN_INSERT; IN_SING] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  REMOVE_THEN "edge_not_old" (fun not_th ->
   REMOVE_THEN "decomposition" (fun decomposition_th ->
    ACCEPT_TAC(MATCH_MP
     (ISPECL
      [`E:(A->bool)->bool`;
       `induced_subgraph_edges E (V DELETE v):(A->bool)->bool`;
       `{u:A,v}:A->bool`]
      DELETE_SINGLETON_UNION)
     (CONJ not_th decomposition_th)))));;

let FINITE_SIMPLE_GRAPH_PENDANT_REMAINDER = prove
 (`!V E u v:A.
        finite_simple_graph V E /\
        v IN V /\
        E DELETE {u,v} = induced_subgraph_edges E (V DELETE v)
        ==> finite_simple_graph (V DELETE v) (E DELETE {u,v})`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph vertex edges" THEN
  USE_THEN "edges" SUBST1_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `V DELETE (v:A)`]
   FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH) THEN
  ASM_REWRITE_TAC[DELETE_SUBSET]);;

let GRAPH_EULER_FORMULA_DELETE_PENDANT_COUNTS = prove
 (`!V E r s u v:A.
        FINITE V /\
        FINITE E /\
        v IN V /\
        {u,v} IN E /\
        ~(E DELETE {u,v} = {}) /\
        graph_euler_formula V E r /\
        CARD(graph_faces (E DELETE {u,v}) s) = CARD(graph_faces E r)
        ==> graph_euler_formula (V DELETE v) (E DELETE {u,v}) s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite_vertices finite_edges vertex edge remainder formula face_count" THEN
  SUBGOAL_THEN `CARD(V DELETE (v:A)) = CARD V - 1`
  (LABEL_TAC "vertex_count") THENL
   [MP_TAC(ISPECL [`v:A`; `V:A->bool`] CARD_DELETE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD((E DELETE {u:A,v}):(A->bool)->bool) = CARD E - 1`
  (LABEL_TAC "edge_count") THENL
   [MP_TAC(ISPECL [`{u:A,v}:A->bool`; `E:(A->bool)->bool`]
     CARD_DELETE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(V:A->bool = {}) /\ ~(E:(A->bool)->bool = {})`
  (CONJUNCTS_THEN2 (LABEL_TAC "vertices_nonempty")
    (LABEL_TAC "edges_nonempty")) THENL
   [CONJ_TAC THENL
     [USE_THEN "vertex" MP_TAC THEN SET_TAC[];
      USE_THEN "edge" MP_TAC THEN SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `0 < CARD(V:A->bool) /\ 0 < CARD(E:(A->bool)->bool)`
  (CONJUNCTS_THEN2 (LABEL_TAC "vertices_positive")
    (LABEL_TAC "edges_positive")) THENL
   [CONJ_TAC THENL
     [SUBGOAL_THEN `~(CARD(V:A->bool) = 0)` MP_TAC THENL
       [ASM_SIMP_TAC[CARD_EQ_0];
        ARITH_TAC];
      SUBGOAL_THEN `~(CARD(E:(A->bool)->bool) = 0)` MP_TAC THENL
       [ASM_SIMP_TAC[CARD_EQ_0];
        ARITH_TAC]];
    ALL_TAC] THEN
  REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "formula" MP_TAC THEN
  REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
  ASM_REWRITE_TAC[] THEN
  ASM_ARITH_TAC);;

let EULER_PLANAR_ROTATION_DELETE_PENDANT = prove
 (`!V E r u v:A.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        graph_neighbors E v = {u} /\
        ~(E DELETE {u,v} = {})
        ==> euler_planar_rotation
             (V DELETE v)
             (E DELETE {u,v})
             (graph_delete_rotation r u v)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "euler connected neighbors remainder" THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph rotation formula" THEN
  SUBGOAL_THEN `({u:A,v}:A->bool) IN E` (LABEL_TAC "edge") THENL
   [ONCE_REWRITE_TAC[SET_RULE `{u:A,v} = {v,u}`] THEN
    REWRITE_TAC[GSYM IN_GRAPH_NEIGHBORS] THEN
    ASM_REWRITE_TAC[IN_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN `u IN V /\ v IN V /\ ~(u:A = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
    (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex") (LABEL_TAC "distinct"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `E DELETE {u:A,v} = induced_subgraph_edges E (V DELETE v)`
  (LABEL_TAC "deleted_edges") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_PENDANT_DELETE_EDGE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E r (u:A,v:A) = (v,u) /\
    ~(graph_face_successor E r (v,u) = (u,v))`
  (CONJUNCTS_THEN2 (LABEL_TAC "forward_successor")
    (LABEL_TAC "not_two_cycle")) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`]
     GRAPH_FACE_SUCCESSOR_PENDANT) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD
     (graph_faces
       (E DELETE {u:A,v})
       (graph_delete_rotation (r:(A#A)->A#A) u v)) =
    CARD(graph_faces E r)`
  (LABEL_TAC "face_count") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`]
     CARD_GRAPH_FACES_DELETE_CONSECUTIVE_EDGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(V:A->bool) /\ FINITE(E:(A->bool)->bool)`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_vertices")
    (LABEL_TAC "finite_edges")) THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_PENDANT_REMAINDER THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`]
     GRAPH_DELETE_ROTATION) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `graph_delete_rotation (r:(A#A)->A#A) u v`;
      `u:A`; `v:A`]
     GRAPH_EULER_FORMULA_DELETE_PENDANT_COUNTS) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "finite_vertices" ACCEPT_TAC;
        USE_THEN "finite_edges" ACCEPT_TAC;
        USE_THEN "v_vertex" ACCEPT_TAC;
        USE_THEN "edge" ACCEPT_TAC;
        USE_THEN "remainder" ACCEPT_TAC;
        USE_THEN "formula" ACCEPT_TAC;
        USE_THEN "face_count" ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC]]);;

let EULER_PLANAR_ROTATION_DELETE_PENDANT_INDUCED = prove
 (`!V E r u v:A.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        graph_neighbors E v = {u} /\
        ~(E DELETE {u,v} = {})
        ==> euler_planar_rotation
             (V DELETE v)
             (induced_subgraph_edges E (V DELETE v))
             (graph_delete_rotation r u v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler connected neighbors remainder" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\ v IN V`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "vertex")) THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN
    INTRO_TAC "graph rotation formula" THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `({u:A,v}:A->bool) IN E` (LABEL_TAC "edge") THENL
     [ONCE_REWRITE_TAC[SET_RULE `{u:A,v} = {v,u}`] THEN
      REWRITE_TAC[GSYM IN_GRAPH_NEIGHBORS] THEN
      ASM_REWRITE_TAC[IN_SING];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `E DELETE {u:A,v} = induced_subgraph_edges E (V DELETE v)`
  (LABEL_TAC "deleted_edges") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_PENDANT_DELETE_EDGE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "deleted_edges" (SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC EULER_PLANAR_ROTATION_DELETE_PENDANT THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Heredity of Euler-planar rotations for connected subgraphs.               *)
(*                                                                           *)
(* A rooted edge list relative to a nonempty base set W builds the remaining *)
(* vertices one at a time.  In reverse order, every added vertex is pendant. *)
(* This lets us first delete surplus edges and then delete all vertices      *)
(* outside a prescribed connected subgraph.                                  *)
(* ------------------------------------------------------------------------- *)

let relative_rooted_edge_vertices =
  new_recursive_definition list_RECURSION
   `(relative_rooted_edge_vertices (W:A->bool) [] = W) /\
    (relative_rooted_edge_vertices W (CONS (d:A#A) es) =
        FST d INSERT relative_rooted_edge_vertices W es)`;;

let relative_rooted_edge_list =
  new_recursive_definition list_RECURSION
   `(relative_rooted_edge_list (E:(A->bool)->bool) W [] <=> T) /\
    (relative_rooted_edge_list E W (CONS (d:A#A) es) <=>
        relative_rooted_edge_list E W es /\
        ~(FST d IN relative_rooted_edge_vertices W es) /\
        SND d IN relative_rooted_edge_vertices W es /\
        {FST d,SND d} IN E)`;;

let BASE_SUBSET_RELATIVE_ROOTED_EDGE_VERTICES = prove
 (`!W:A->bool. !es. W SUBSET relative_rooted_edge_vertices W es`,
  GEN_TAC THEN LIST_INDUCT_TAC THEN
  ASM_REWRITE_TAC[relative_rooted_edge_vertices; SUBSET_REFL] THEN
  MATCH_MP_TAC SUBSET_TRANS THEN
  EXISTS_TAC `relative_rooted_edge_vertices (W:A->bool) t` THEN
  CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    SET_TAC[]]);;

let FINITE_RELATIVE_ROOTED_EDGE_VERTICES = prove
 (`!W:A->bool. !es.
        FINITE W ==> FINITE(relative_rooted_edge_vertices W es)`,
  GEN_TAC THEN LIST_INDUCT_TAC THEN
  ASM_REWRITE_TAC[relative_rooted_edge_vertices; FINITE_INSERT]);;

let RELATIVE_ROOTED_EDGE_LIST_TAIL = prove
 (`!E W d:A#A. !es.
        relative_rooted_edge_list E W (CONS d es)
        ==> relative_rooted_edge_list E W es`,
  REWRITE_TAC[relative_rooted_edge_list] THEN MESON_TAC[]);;

let RELATIVE_ROOTED_EDGE_LIST_VERTICES_SUBSET = prove
 (`!V E W:A->bool. !es.
        finite_simple_graph V E /\
        W SUBSET V /\
        relative_rooted_edge_list E W es
        ==> relative_rooted_edge_vertices W es SUBSET V`,
  REPEAT GEN_TAC THEN
  SPEC_TAC(`es:(A#A)list`,`es:(A#A)list`) THEN
  LIST_INDUCT_TAC THENL
   [REWRITE_TAC[relative_rooted_edge_vertices;
                relative_rooted_edge_list] THEN MESON_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "induction") THEN
    MP_TAC(ISPEC `h:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    REWRITE_TAC[relative_rooted_edge_list;
                relative_rooted_edge_vertices; FST; SND] THEN
    INTRO_TAC "graph base tail new old edge" THEN
    REWRITE_TAC[INSERT_SUBSET] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `x:A`; `y:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
      USE_THEN "induction" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]]);;

let RELATIVE_ROOTED_EDGE_SET_SUBSET = prove
 (`!E W:A->bool. !es.
        relative_rooted_edge_list E W es
        ==> rooted_edge_set es SUBSET E`,
  REPEAT GEN_TAC THEN
  SPEC_TAC(`es:(A#A)list`,`es:(A#A)list`) THEN
  LIST_INDUCT_TAC THENL
   [REWRITE_TAC[relative_rooted_edge_list; rooted_edge_set; EMPTY_SUBSET];
    FIRST_X_ASSUM(LABEL_TAC "induction") THEN
    MP_TAC(ISPEC `h:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    REWRITE_TAC[relative_rooted_edge_list; rooted_edge_set;
                FST; SND; INSERT_SUBSET] THEN
    INTRO_TAC "tail new old edge" THEN CONJ_TAC THENL
     [USE_THEN "edge" ACCEPT_TAC;
      USE_THEN "induction" MATCH_MP_TAC THEN
      USE_THEN "tail" ACCEPT_TAC]]);;

let RELATIVE_ROOTED_EDGE_SET_ENDPOINTS = prove
 (`!E W:A->bool. !es e.
        relative_rooted_edge_list E W es /\
        e IN rooted_edge_set es
        ==> e SUBSET relative_rooted_edge_vertices W es`,
  REPEAT GEN_TAC THEN
  SPEC_TAC(`es:(A#A)list`,`es:(A#A)list`) THEN
  LIST_INDUCT_TAC THENL
   [REWRITE_TAC[rooted_edge_set; NOT_IN_EMPTY];
    FIRST_X_ASSUM(LABEL_TAC "induction") THEN
    MP_TAC(ISPEC `h:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    DISCH_THEN(CONJUNCTS_THEN2
     (LABEL_TAC "ordered") (LABEL_TAC "edge_member")) THEN
    USE_THEN "ordered" MP_TAC THEN
    REWRITE_TAC[relative_rooted_edge_list; FST; SND] THEN
    INTRO_TAC "tail new old edge" THEN
    USE_THEN "edge_member" MP_TAC THEN
    REWRITE_TAC[rooted_edge_set; IN_INSERT] THEN
    DISCH_THEN(DISJ_CASES_THEN2
      (LABEL_TAC "head_edge") (LABEL_TAC "tail_edge")) THENL
     [USE_THEN "head_edge" SUBST1_TAC THEN
      REWRITE_TAC[relative_rooted_edge_vertices;
                  INSERT_SUBSET; SING_SUBSET; IN_INSERT] THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `relative_rooted_edge_vertices (W:A->bool) t` THEN
      CONJ_TAC THENL
       [USE_THEN "induction" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[relative_rooted_edge_vertices] THEN SET_TAC[]]]]);;

let RELATIVE_ROOTED_EDGE_LIST_NEW_EDGE = prove
 (`!E W x y:A. !es.
        relative_rooted_edge_list E W (CONS (x,y) es)
        ==> ~({x,y} IN rooted_edge_set es)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[relative_rooted_edge_list; FST; SND] THEN
  INTRO_TAC "tail new old edge" THEN
  DISCH_THEN(LABEL_TAC "old_edge") THEN
  SUBGOAL_THEN
   `{x:A,y} SUBSET relative_rooted_edge_vertices W es`
  (LABEL_TAC "old_endpoints") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `W:A->bool`; `es:(A#A)list`; `{x:A,y}`]
     RELATIVE_ROOTED_EDGE_SET_ENDPOINTS) THEN
    ASM_REWRITE_TAC[];
    USE_THEN "new" MP_TAC THEN
    USE_THEN "old_endpoints" MP_TAC THEN SET_TAC[]]);;

let CONNECTED_GRAPH_RELATIVE_ROOTED_EDGE_LIST = prove
 (`!V E W u:A.
        finite_simple_graph V E /\
        connected_graph V E /\
        W SUBSET V /\
        u IN W
        ==> ?es:(A#A)list.
              relative_rooted_edge_list E W es /\
              relative_rooted_edge_vertices W es = V`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected base root" THEN
  SUBGOAL_THEN
   `!n. !es:(A#A)list.
        relative_rooted_edge_list E W es /\
        relative_rooted_edge_vertices W es SUBSET V /\
        CARD(V DIFF relative_rooted_edge_vertices W es) = n
        ==> ?es':(A#A)list.
              relative_rooted_edge_list E W es' /\
              relative_rooted_edge_vertices W es' = V`
  (LABEL_TAC "extension") THENL
   [MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN
    DISCH_THEN(LABEL_TAC "induction") THEN
    X_GEN_TAC `es:(A#A)list` THEN
    INTRO_TAC "ordered subset remaining" THEN
    ASM_CASES_TAC `relative_rooted_edge_vertices (W:A->bool) es = V` THENL
     [EXISTS_TAC `es:(A#A)list` THEN ASM_REWRITE_TAC[];
      FIRST_X_ASSUM(LABEL_TAC "proper")] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `relative_rooted_edge_vertices (W:A->bool) es`; `u:A`]
     CONNECTED_GRAPH_CROSSING_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `(u:A) IN relative_rooted_edge_vertices W es`
    (LABEL_TAC "root_represented") THENL
     [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (ISPECL [`W:A->bool`; `es:(A#A)list`]
        BASE_SUBSET_RELATIVE_ROOTED_EDGE_VERTICES)) THEN
      USE_THEN "root" ACCEPT_TAC;
      ASM_REWRITE_TAC[]] THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "x_new")
       (CONJUNCTS_THEN2 (LABEL_TAC "y_old") (LABEL_TAC "edge"))))) THEN
    SUBGOAL_THEN
     `relative_rooted_edge_list E W (CONS ((x:A),(y:A)) es)`
    (LABEL_TAC "extended_order") THENL
     [ASM_REWRITE_TAC[relative_rooted_edge_list; FST; SND] THEN
      USE_THEN "x_new" MP_TAC THEN REWRITE_TAC[IN_DIFF] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `relative_rooted_edge_vertices W (CONS ((x:A),(y:A)) es) SUBSET V`
    (LABEL_TAC "extended_subset") THENL
     [REWRITE_TAC[relative_rooted_edge_vertices; FST; INSERT_SUBSET] THEN
      USE_THEN "x_new" MP_TAC THEN REWRITE_TAC[IN_DIFF] THEN
      ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `V DIFF
        relative_rooted_edge_vertices W (CONS ((x:A),(y:A)) es) =
      (V DIFF relative_rooted_edge_vertices W es) DELETE x`
    (LABEL_TAC "remaining_delete") THENL
     [REWRITE_TAC[relative_rooted_edge_vertices; FST] THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `FINITE(V DIFF relative_rooted_edge_vertices (W:A->bool) es)`
    (LABEL_TAC "finite_remaining") THENL
     [MATCH_MP_TAC FINITE_DIFF THEN
      USE_THEN "graph"
       (ACCEPT_TAC o CONJUNCT1 o
        REWRITE_RULE[finite_simple_graph]);
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD(V DIFF
       relative_rooted_edge_vertices W (CONS ((x:A),(y:A)) es)) < n`
    (LABEL_TAC "decreases") THENL
     [USE_THEN "remaining_delete" SUBST1_TAC THEN
      MP_TAC(ISPECL
       [`x:A`; `V DIFF relative_rooted_edge_vertices (W:A->bool) es`]
       CARD_DELETE) THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN
       `~(CARD(V DIFF relative_rooted_edge_vertices (W:A->bool) es) = 0)`
      MP_TAC THENL
       [ASM_SIMP_TAC[CARD_EQ_0] THEN
        USE_THEN "x_new" MP_TAC THEN SET_TAC[];
        ASM_ARITH_TAC];
      ALL_TAC] THEN
    USE_THEN "induction" (fun induction_th ->
     USE_THEN "decreases" (fun decreases_th ->
      MATCH_MP_TAC
       (SPEC `CONS ((x:A),(y:A)) es`
        (MATCH_MP
         (SPEC
          `CARD(V DIFF
            relative_rooted_edge_vertices W
             (CONS ((x:A),(y:A)) es))`
          induction_th)
         decreases_th)))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "extension" (MATCH_MP_TAC o SPECL
   [`CARD(V DIFF relative_rooted_edge_vertices (W:A->bool) [])`;
    `[]:(A#A)list`]) THEN
  ASM_REWRITE_TAC[relative_rooted_edge_list;
                  relative_rooted_edge_vertices]);;

let CONNECTED_GRAPH_INSERT_EDGE_VERTEX = prove
 (`!V E x y:A.
        connected_graph V E /\ y IN V
        ==> connected_graph (x INSERT V) ({x,y} INSERT E)`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected y_vertex" THEN
  REWRITE_TAC[connected_graph] THEN
  MAP_EVERY X_GEN_TAC [`a:A`; `b:A`] THEN
  INTRO_TAC "a_vertex b_vertex" THEN
  ASM_CASES_TAC `(a:A) = x` THEN
  ASM_CASES_TAC `(b:A) = x` THENL
   [ASM_REWRITE_TAC[GRAPH_REACHABLE_REFL];
    UNDISCH_TAC `(a:A) = x` THEN DISCH_THEN SUBST_ALL_TAC THEN
    SUBGOAL_THEN `(b:A) IN V` (LABEL_TAC "b_old") THENL
     [USE_THEN "b_vertex" MP_TAC THEN
      REWRITE_TAC[IN_INSERT] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN
    EXISTS_TAC `y:A` THEN CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN REWRITE_TAC[IN_INSERT];
      MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `({x:A,y} INSERT E):(A->bool)->bool`;
        `y:A`; `b:A`]
       GRAPH_REACHABLE_MONO) THEN
      CONJ_TAC THENL
       [SET_TAC[];
        USE_THEN "connected" MP_TAC THEN
        REWRITE_TAC[connected_graph] THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]];
    UNDISCH_TAC `(b:A) = x` THEN DISCH_THEN SUBST_ALL_TAC THEN
    MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
    SUBGOAL_THEN `(a:A) IN V` (LABEL_TAC "a_old") THENL
     [USE_THEN "a_vertex" MP_TAC THEN
      REWRITE_TAC[IN_INSERT] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN
    EXISTS_TAC `y:A` THEN CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN REWRITE_TAC[IN_INSERT];
      MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `({x:A,y} INSERT E):(A->bool)->bool`;
        `y:A`; `a:A`]
       GRAPH_REACHABLE_MONO) THEN
      CONJ_TAC THENL
       [SET_TAC[];
        USE_THEN "connected" MP_TAC THEN
        REWRITE_TAC[connected_graph] THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]];
    SUBGOAL_THEN `(a:A) IN V /\ (b:A) IN V`
    (CONJUNCTS_THEN2 (LABEL_TAC "a_old") (LABEL_TAC "b_old")) THENL
     [USE_THEN "a_vertex" MP_TAC THEN
      USE_THEN "b_vertex" MP_TAC THEN
      REWRITE_TAC[IN_INSERT] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `({x:A,y} INSERT E):(A->bool)->bool`;
      `a:A`; `b:A`]
     GRAPH_REACHABLE_MONO) THEN
    CONJ_TAC THENL
     [SET_TAC[];
      USE_THEN "connected" MP_TAC THEN
      REWRITE_TAC[connected_graph] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]]);;

let CONNECTED_GRAPH_RELATIVE_ROOTED_EDGE_SET = prove
 (`!E:(A->bool)->bool. !B:(A->bool)->bool. !W:A->bool. !es.
        connected_graph W B /\
        relative_rooted_edge_list E W es
        ==> connected_graph
             (relative_rooted_edge_vertices W es)
             (B UNION rooted_edge_set es)`,
  REPEAT GEN_TAC THEN
  SPEC_TAC(`es:(A#A)list`,`es:(A#A)list`) THEN
  LIST_INDUCT_TAC THENL
   [REWRITE_TAC[relative_rooted_edge_list;
                relative_rooted_edge_vertices; rooted_edge_set;
                UNION_EMPTY] THEN MESON_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "induction") THEN
    MP_TAC(ISPEC `h:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    REWRITE_TAC[relative_rooted_edge_list;
                relative_rooted_edge_vertices;
                rooted_edge_set; FST; SND] THEN
    INTRO_TAC "connected tail new old edge" THEN
    ONCE_REWRITE_TAC
     [SET_RULE
       `B UNION ({x:A,y} INSERT R) = {x,y} INSERT (B UNION R)`] THEN
    MATCH_MP_TAC CONNECTED_GRAPH_INSERT_EDGE_VERTEX THEN
    CONJ_TAC THENL
     [USE_THEN "induction" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      USE_THEN "old" ACCEPT_TAC]]);;

let RELATIVE_ROOTED_EDGE_SET_WITH_BASE_SUBSET = prove
 (`!E:(A->bool)->bool. !B:(A->bool)->bool.
   !W:A->bool. !es:(A#A)list.
        relative_rooted_edge_list E W es /\
        B SUBSET induced_subgraph_edges E W
        ==> B UNION rooted_edge_set es SUBSET E`,
  REPEAT GEN_TAC THEN INTRO_TAC "ordered base_edges" THEN
  REWRITE_TAC[UNION_SUBSET] THEN CONJ_TAC THENL
   [USE_THEN "base_edges" MP_TAC THEN
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[];
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `W:A->bool`; `es:(A#A)list`]
     RELATIVE_ROOTED_EDGE_SET_SUBSET) THEN
    ASM_REWRITE_TAC[]]);;

let FINITE_SIMPLE_GRAPH_EDGE_SUBSET = prove
 (`!V E B.
        finite_simple_graph (V:A->bool) E /\ B SUBSET E
        ==> finite_simple_graph V B`,
  REWRITE_TAC[finite_simple_graph] THEN
  MESON_TAC[FINITE_SUBSET; SUBSET]);;

let RELATIVE_ROOTED_EDGE_LIST_NEW_EDGE_NOT_IN_BASE = prove
 (`!E:(A->bool)->bool. !B:(A->bool)->bool.
   !W:A->bool. !x y:A. !es.
        relative_rooted_edge_list E W (CONS (x,y) es) /\
        B SUBSET induced_subgraph_edges E W
        ==> ~({x,y} IN B)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[relative_rooted_edge_list; FST; SND] THEN
  INTRO_TAC "(tail new old edge) base_edges" THEN
  DISCH_THEN(LABEL_TAC "base_edge") THEN
  SUBGOAL_THEN `{x:A,y} SUBSET W` (LABEL_TAC "base_endpoints") THENL
   [USE_THEN "base_edges" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
    DISCH_THEN(MP_TAC o SPEC `{x:A,y}`) THEN
    ASM_REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:A) IN relative_rooted_edge_vertices W es`
  (LABEL_TAC "x_old") THENL
   [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
     (ISPECL [`W:A->bool`; `es:(A#A)list`]
      BASE_SUBSET_RELATIVE_ROOTED_EDGE_VERTICES)) THEN
    USE_THEN "base_endpoints" MP_TAC THEN SET_TAC[];
    ASM_MESON_TAC[]]);;

let RELATIVE_ROOTED_EDGE_LIST_HEAD_REMAINDER = prove
 (`!E:(A->bool)->bool. !B:(A->bool)->bool.
   !W:A->bool. !x y:A. !es.
        relative_rooted_edge_list E W (CONS (x,y) es) /\
        B SUBSET induced_subgraph_edges E W
        ==> (B UNION rooted_edge_set (CONS (x,y) es)) DELETE {x,y} =
            B UNION rooted_edge_set es`,
  REPEAT GEN_TAC THEN INTRO_TAC "ordered base_edges" THEN
  SUBGOAL_THEN
   `~({x:A,y} IN B UNION rooted_edge_set es)`
  (LABEL_TAC "new_edge") THENL
   [REWRITE_TAC[IN_UNION] THEN
    MATCH_MP_TAC(TAUT `~p /\ ~q ==> ~(p \/ q)`) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
        `x:A`; `y:A`; `es:(A#A)list`]
       RELATIVE_ROOTED_EDGE_LIST_NEW_EDGE_NOT_IN_BASE) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `W:A->bool`; `x:A`; `y:A`;
        `es:(A#A)list`]
       RELATIVE_ROOTED_EDGE_LIST_NEW_EDGE) THEN
      USE_THEN "ordered" ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[rooted_edge_set] THEN
  MATCH_MP_TAC(ISPECL
   [`B UNION ({x:A,y} INSERT rooted_edge_set es):(A->bool)->bool`;
    `B UNION rooted_edge_set es:(A->bool)->bool`;
    `{x:A,y}:A->bool`]
   DELETE_SINGLETON_UNION) THEN
  ASM_REWRITE_TAC[] THEN SET_TAC[]);;

let RELATIVE_ROOTED_EDGE_LIST_HEAD_NEIGHBORS = prove
 (`!E:(A->bool)->bool. !B:(A->bool)->bool.
   !W:A->bool. !x y:A. !es.
        relative_rooted_edge_list E W (CONS (x,y) es) /\
        B SUBSET induced_subgraph_edges E W
        ==> graph_neighbors
             (B UNION rooted_edge_set (CONS (x,y) es)) x = {y}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[relative_rooted_edge_list; FST; SND] THEN
  INTRO_TAC "(tail new old edge) base_edges" THEN
  SUBGOAL_THEN `~(x:A = y)` (LABEL_TAC "distinct") THENL
   [ASM_MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `z:A` THEN
  REWRITE_TAC[IN_GRAPH_NEIGHBORS; IN_SING; rooted_edge_set;
              IN_UNION; IN_INSERT] THEN
  EQ_TAC THENL
   [DISCH_THEN(DISJ_CASES_THEN2
     (LABEL_TAC "base_edge")
     (DISJ_CASES_THEN2 (LABEL_TAC "head_edge")
       (LABEL_TAC "tail_edge"))) THENL
     [SUBGOAL_THEN `{x:A,z} SUBSET W` (LABEL_TAC "base_endpoints") THENL
       [USE_THEN "base_edges" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
        DISCH_THEN(MP_TAC o SPEC `{x:A,z}`) THEN
        ASM_REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(x:A) IN relative_rooted_edge_vertices W es`
      (LABEL_TAC "x_old") THENL
       [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
         (ISPECL [`W:A->bool`; `es:(A#A)list`]
          BASE_SUBSET_RELATIVE_ROOTED_EDGE_VERTICES)) THEN
        USE_THEN "base_endpoints" MP_TAC THEN SET_TAC[];
        ASM_MESON_TAC[]];
      MATCH_MP_TAC
       (SET_RULE
        `~(x:A = y) /\ {x,z} = {x,y} ==> z = y`) THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN
       `{x:A,z} SUBSET relative_rooted_edge_vertices W es`
      (LABEL_TAC "tail_endpoints") THENL
       [MATCH_MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `W:A->bool`; `es:(A#A)list`; `{x:A,z}`]
         RELATIVE_ROOTED_EDGE_SET_ENDPOINTS) THEN
        ASM_REWRITE_TAC[];
        USE_THEN "tail_endpoints" MP_TAC THEN
        USE_THEN "new" MP_TAC THEN SET_TAC[]]];
    DISCH_THEN SUBST1_TAC THEN
    DISJ2_TAC THEN DISJ1_TAC THEN REFL_TAC]);;

let EULER_PLANAR_ROTATION_SINGLETON_I = prove
 (`!u:A. euler_planar_rotation {u} {} (I:(A#A)->A#A)`,
  GEN_TAC THEN
  REWRITE_TAC[euler_planar_rotation; finite_simple_graph; graph_rotation;
              graph_euler_formula; graph_map_faces; graph_darts;
              graph_faces] THEN
  REWRITE_TAC[SET_RULE `{d:A#A | dart_edge d IN {}} = {}`] THEN
  SIMP_TAC[PERMUTES_EMPTY; NOT_INSERT_EMPTY; CARD_SING;
           FINITE_INSERT; FINITE_EMPTY; NOT_IN_EMPTY; CARD_CLAUSES] THEN
  ARITH_TAC);;

let CONNECTED_GRAPH_EMPTY_EDGES_SINGLETON = prove
 (`!W u:A.
        connected_graph W {} /\ u IN W
        ==> W = {u}`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected root" THEN
  REWRITE_TAC[EXTENSION; IN_SING] THEN X_GEN_TAC `v:A` THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "vertex") THEN
    USE_THEN "connected" MP_TAC THEN
    REWRITE_TAC[connected_graph] THEN
    DISCH_THEN(MP_TAC o SPECL [`u:A`; `v:A`]) THEN
    ASM_REWRITE_TAC[GRAPH_REACHABLE_EMPTY] THEN MESON_TAC[];
    DISCH_THEN SUBST1_TAC THEN USE_THEN "root" ACCEPT_TAC]);;

let EULER_PLANAR_ROTATION_CONNECTED_EMPTY = prove
 (`!W:A->bool.
        ~(W = {}) /\ connected_graph W {}
        ==> ?r:(A#A)->A#A. euler_planar_rotation W {} r`,
  GEN_TAC THEN INTRO_TAC "nonempty connected" THEN
  SUBGOAL_THEN `?u:A. u IN W`
  (X_CHOOSE_THEN `u:A` (LABEL_TAC "root")) THENL
   [USE_THEN "nonempty" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`W:A->bool`; `u:A`]
   CONNECTED_GRAPH_EMPTY_EDGES_SINGLETON) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN SUBST1_TAC THEN
  EXISTS_TAC `I:(A#A)->A#A` THEN
  MATCH_ACCEPT_TAC EULER_PLANAR_ROTATION_SINGLETON_I);;

let EULER_PLANAR_ROTATION_RELATIVE_ROOTED_RESTRICT = prove
 (`!E:(A->bool)->bool. !B:(A->bool)->bool. !W:A->bool.
   !es:(A#A)list. !r:(A#A)->A#A.
        finite_simple_graph W B /\
        connected_graph W B /\
        ~(B = {}) /\
        B SUBSET induced_subgraph_edges E W /\
        relative_rooted_edge_list E W es /\
        euler_planar_rotation
          (relative_rooted_edge_vertices W es)
          (B UNION rooted_edge_set es) r
        ==> ?s:(A#A)->A#A. euler_planar_rotation W B s`,
  REPEAT GEN_TAC THEN
  SPEC_TAC(`r:(A#A)->A#A`,`r:(A#A)->A#A`) THEN
  SPEC_TAC(`es:(A#A)list`,`es:(A#A)list`) THEN
  LIST_INDUCT_TAC THENL
   [REWRITE_TAC[relative_rooted_edge_list;
                relative_rooted_edge_vertices;
                rooted_edge_set; UNION_EMPTY] THEN
    MESON_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "induction") THEN
    MP_TAC(ISPEC `h:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    X_GEN_TAC `r:(A#A)->A#A` THEN
    INTRO_TAC
     "base_graph base_connected base_nonempty base_edges ordered euler" THEN
    SUBGOAL_THEN
     `relative_rooted_edge_list E W (t:(A#A)list) /\
      ~(x IN relative_rooted_edge_vertices W t) /\
      y IN relative_rooted_edge_vertices W t /\
      {x:A,y} IN E`
    (CONJUNCTS_THEN2 (LABEL_TAC "tail_ordered")
     (CONJUNCTS_THEN2 (LABEL_TAC "new")
      (CONJUNCTS_THEN2 (LABEL_TAC "old") (LABEL_TAC "edge")))) THENL
     [USE_THEN "ordered" MP_TAC THEN
      REWRITE_TAC[relative_rooted_edge_list; FST; SND];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `connected_graph
       (relative_rooted_edge_vertices W (CONS ((x:A),(y:A)) t))
       (B UNION rooted_edge_set (CONS (x,y) t))`
    (LABEL_TAC "current_connected") THENL
     [MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
        `CONS ((x:A),(y:A)) t`]
       CONNECTED_GRAPH_RELATIVE_ROOTED_EDGE_SET) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_neighbors
       (B UNION rooted_edge_set (CONS ((x:A),(y:A)) t)) x = {y}`
    (LABEL_TAC "neighbors") THENL
     [MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
        `x:A`; `y:A`; `t:(A#A)list`]
       RELATIVE_ROOTED_EDGE_LIST_HEAD_NEIGHBORS) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(B UNION rooted_edge_set (CONS ((x:A),(y:A)) t)) DELETE {y,x} =
      B UNION rooted_edge_set t`
    (LABEL_TAC "remainder") THENL
     [ONCE_REWRITE_TAC[SET_RULE `{y:A,x} = {x,y}`] THEN
      MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
        `x:A`; `y:A`; `t:(A#A)list`]
       RELATIVE_ROOTED_EDGE_LIST_HEAD_REMAINDER) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~(B UNION rooted_edge_set (t:(A#A)list) = {})`
    (LABEL_TAC "remainder_nonempty") THENL
     [USE_THEN "base_nonempty" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`relative_rooted_edge_vertices W (CONS ((x:A),(y:A)) t)`;
      `B UNION rooted_edge_set (CONS ((x:A),(y:A)) t)`;
      `r:(A#A)->A#A`; `y:A`; `x:A`]
     EULER_PLANAR_ROTATION_DELETE_PENDANT) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(LABEL_TAC "deleted_euler")] THEN
    SUBGOAL_THEN
     `(relative_rooted_edge_vertices W (CONS ((x:A),(y:A)) t))
       DELETE x =
      relative_rooted_edge_vertices W t`
    (LABEL_TAC "deleted_vertices") THENL
     [REWRITE_TAC[relative_rooted_edge_vertices; FST] THEN
      USE_THEN "new" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `euler_planar_rotation
       (relative_rooted_edge_vertices W t)
       (B UNION rooted_edge_set t)
       (graph_delete_rotation (r:(A#A)->A#A) y x)`
    (LABEL_TAC "tail_euler") THENL
     [USE_THEN "deleted_vertices" (SUBST1_TAC o SYM) THEN
      USE_THEN "remainder" (SUBST1_TAC o SYM) THEN
      USE_THEN "deleted_euler" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "induction"
     (MP_TAC o SPEC `graph_delete_rotation (r:(A#A)->A#A) y x`) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "base_graph" ACCEPT_TAC;
        USE_THEN "base_connected" ACCEPT_TAC;
        USE_THEN "base_nonempty" ACCEPT_TAC;
        USE_THEN "base_edges" ACCEPT_TAC;
        USE_THEN "tail_ordered" ACCEPT_TAC;
        USE_THEN "tail_euler" ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC]]);;

let EULER_PLANAR_ROTATION_CONNECTED_SUBGRAPH = prove
 (`!V E r W B.
        euler_planar_rotation (V:A->bool) E r /\
        connected_graph V E /\
        W SUBSET V /\
        ~(W = {}) /\
        B SUBSET induced_subgraph_edges E W /\
        connected_graph W B
        ==> ?s:(A#A)->A#A. euler_planar_rotation W B s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "euler connected subset nonempty edge_subset target_connected" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(B:(A->bool)->bool) = {}` THENL
   [FIRST_X_ASSUM(LABEL_TAC "target_empty") THEN
    USE_THEN "target_empty" SUBST_ALL_TAC THEN
    MATCH_MP_TAC EULER_PLANAR_ROTATION_CONNECTED_EMPTY THEN
    ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "target_nonempty") THEN
    SUBGOAL_THEN `?u:A. u IN W`
    (X_CHOOSE_THEN `w:A` (LABEL_TAC "root")) THENL
     [USE_THEN "nonempty" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `W:A->bool`; `w:A`]
     CONNECTED_GRAPH_RELATIVE_ROOTED_EDGE_LIST) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `es:(A#A)list`
     (CONJUNCTS_THEN2 (LABEL_TAC "ordered")
      (LABEL_TAC "vertices"))) THEN
    SUBGOAL_THEN
     `B UNION rooted_edge_set es SUBSET (E:(A->bool)->bool)`
    (LABEL_TAC "intermediate_subset") THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
        `es:(A#A)list`]
       RELATIVE_ROOTED_EDGE_SET_WITH_BASE_SUBSET) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `connected_graph
       (V:A->bool) (B UNION rooted_edge_set es)`
    (LABEL_TAC "intermediate_connected") THENL
     [USE_THEN "vertices" (SUBST1_TAC o SYM) THEN
      MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
        `es:(A#A)list`]
       CONNECTED_GRAPH_RELATIVE_ROOTED_EDGE_SET) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `B UNION rooted_edge_set es:(A->bool)->bool`;
      `E:(A->bool)->bool`; `r:(A#A)->A#A`]
     EULER_PLANAR_ROTATION_SUBSET_CONNECTED) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "intermediate_subset" ACCEPT_TAC;
        USE_THEN "intermediate_connected" ACCEPT_TAC;
        USE_THEN "euler" ACCEPT_TAC];
      DISCH_THEN(X_CHOOSE_THEN `s:(A#A)->A#A`
       (LABEL_TAC "intermediate_euler"))] THEN
    SUBGOAL_THEN `finite_simple_graph (W:A->bool) B`
    (LABEL_TAC "target_graph") THENL
     [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_EDGE_SUBSET THEN
      EXISTS_TAC `induced_subgraph_edges E (W:A->bool)` THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `W:A->bool`]
       FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
      `es:(A#A)list`; `s:(A#A)->A#A`]
     EULER_PLANAR_ROTATION_RELATIVE_ROOTED_RESTRICT) THEN
    ASM_REWRITE_TAC[]]);;

let INDUCED_SUBGRAPH_EDGES_SUBSET = prove
 (`!E:(A->bool)->bool. !W:A->bool.
        induced_subgraph_edges E W SUBSET E`,
  REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[]);;

let GRAPH_COMPONENT_MONO = prove
 (`!E E' u:A.
        E SUBSET E'
        ==> graph_component E u SUBSET graph_component E' u`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "subset") THEN
  REWRITE_TAC[SUBSET; IN_GRAPH_COMPONENT] THEN
  X_GEN_TAC `v:A` THEN DISCH_THEN(LABEL_TAC "reachable") THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `E':(A->bool)->bool`; `u:A`; `v:A`]
   GRAPH_REACHABLE_MONO) THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_COMPONENT_EDGES_MONO_INDUCED = prove
 (`!E E' u:A.
        E SUBSET E'
        ==> graph_component_edges E u SUBSET
            induced_subgraph_edges
              (graph_component_edges E' u) (graph_component E u)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "edge_subset") THEN
  SUBGOAL_THEN
   `graph_component E (u:A) SUBSET graph_component E' u`
  (LABEL_TAC "component_subset") THENL
   [MATCH_MP_TAC GRAPH_COMPONENT_MONO THEN
    USE_THEN "edge_subset" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES;
              IN_GRAPH_COMPONENT_EDGES] THEN
  ASM_MESON_TAC[SUBSET]);;

let EULER_PLANAR_GRAPH_SUBGRAPH = prove
 (`!V E W B.
        euler_planar_graph (V:A->bool) E /\
        W SUBSET V /\
        B SUBSET induced_subgraph_edges E W
        ==> euler_planar_graph W B`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler subset edge_subset" THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_graph] THEN
  INTRO_TAC "source_graph source_components" THEN
  SUBGOAL_THEN `finite_simple_graph (W:A->bool) B`
  (LABEL_TAC "target_graph") THENL
   [MATCH_MP_TAC(ISPECL
     [`W:A->bool`; `induced_subgraph_edges E W:(A->bool)->bool`;
      `B:(A->bool)->bool`]
     FINITE_SIMPLE_GRAPH_EDGE_SUBSET) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `W:A->bool`]
       FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "edge_subset" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `B SUBSET (E:(A->bool)->bool)`
  (LABEL_TAC "ambient_edge_subset") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `induced_subgraph_edges E (W:A->bool)` THEN
    CONJ_TAC THENL
     [USE_THEN "edge_subset" ACCEPT_TAC;
      MATCH_ACCEPT_TAC INDUCED_SUBGRAPH_EDGES_SUBSET];
    ALL_TAC] THEN
  REWRITE_TAC[euler_planar_graph] THEN
  CONJ_TAC THENL
   [USE_THEN "target_graph" ACCEPT_TAC;
    ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "target_vertex") THEN
  SUBGOAL_THEN `(u:A) IN V` (LABEL_TAC "source_vertex") THENL
   [USE_THEN "subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "target_vertex" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "source_components" (MP_TAC o SPEC `u:A`) THEN
  ANTS_TAC THENL
   [USE_THEN "source_vertex" ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `r:(A#A)->A#A`
     (LABEL_TAC "source_rotation"))] THEN
  SUBGOAL_THEN
   `connected_graph
     (graph_component E (u:A)) (graph_component_edges E u)`
  (LABEL_TAC "source_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
     GRAPH_COMPONENT_EDGES_CONNECTED) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph
     (graph_component B (u:A)) (graph_component_edges B u)`
  (LABEL_TAC "target_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`W:A->bool`; `B:(A->bool)->bool`; `u:A`]
     GRAPH_COMPONENT_EDGES_CONNECTED) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_component B (u:A) SUBSET graph_component E u`
  (LABEL_TAC "component_subset") THENL
   [MATCH_MP_TAC GRAPH_COMPONENT_MONO THEN
    USE_THEN "ambient_edge_subset" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(graph_component B (u:A) = {})`
  (LABEL_TAC "component_nonempty") THENL
   [MP_TAC(ISPECL [`B:(A->bool)->bool`; `u:A`]
     GRAPH_COMPONENT_REFL) THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_component_edges B (u:A) SUBSET
    induced_subgraph_edges
      (graph_component_edges E u) (graph_component B u)`
  (LABEL_TAC "component_edges") THENL
   [MATCH_MP_TAC GRAPH_COMPONENT_EDGES_MONO_INDUCED THEN
    USE_THEN "ambient_edge_subset" ACCEPT_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`graph_component E (u:A)`;
    `graph_component_edges E u:(A->bool)->bool`;
    `r:(A#A)->A#A`;
    `graph_component B u:A->bool`;
    `graph_component_edges B u:(A->bool)->bool`]
   EULER_PLANAR_ROTATION_CONNECTED_SUBGRAPH) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "source_rotation" ACCEPT_TAC;
    USE_THEN "source_connected" ACCEPT_TAC;
    USE_THEN "component_subset" ACCEPT_TAC;
    USE_THEN "component_nonempty" ACCEPT_TAC;
    USE_THEN "component_edges" ACCEPT_TAC;
    USE_THEN "target_connected" ACCEPT_TAC]);;

let EULER_PLANAR_GRAPH_INDUCED_SUBGRAPH = prove
 (`!V E W.
        euler_planar_graph (V:A->bool) E /\ W SUBSET V
        ==> euler_planar_graph W (induced_subgraph_edges E W)`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler subset" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `W:A->bool`;
    `induced_subgraph_edges E W:(A->bool)->bool`]
   EULER_PLANAR_GRAPH_SUBGRAPH) THEN
  ASM_REWRITE_TAC[SUBSET_REFL]);;

let FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH_SELF = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> induced_subgraph_edges E V = E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  REWRITE_TAC[EXTENSION; IN_INDUCED_SUBGRAPH_EDGES] THEN
  USE_THEN "graph" MP_TAC THEN
  REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[]);;

let EULER_PLANAR_GRAPH_SUBSET_EDGES = prove
 (`!V E B.
        euler_planar_graph (V:A->bool) E /\ B SUBSET E
        ==> euler_planar_graph V B`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler edge_subset" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC EULER_PLANAR_GRAPH_FINITE_SIMPLE THEN
    USE_THEN "euler" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `B SUBSET induced_subgraph_edges E (V:A->bool)`
  (LABEL_TAC "induced_edge_subset") THENL
   [MP_TAC(MATCH_MP
     (ISPECL [`V:A->bool`; `E:(A->bool)->bool`]
      FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH_SELF)
     (ASSUME `finite_simple_graph (V:A->bool) E`)) THEN
    DISCH_THEN(fun th -> ONCE_REWRITE_TAC[th]) THEN
    USE_THEN "edge_subset" ACCEPT_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `V:A->bool`;
    `B:(A->bool)->bool`]
   EULER_PLANAR_GRAPH_SUBGRAPH) THEN
  ASM_REWRITE_TAC[SUBSET_REFL]);;

(* ------------------------------------------------------------------------- *)
(* Maximal extensions of Euler-planar rotations.                             *)
(* ------------------------------------------------------------------------- *)

let MAXIMAL_EULER_PLANAR_ROTATION_EXTENSION = prove
 (`!V E r:(A#A)->A#A.
        euler_planar_rotation V E r
        ==> ?E' r'.
              E SUBSET E' /\
              euler_planar_rotation V E' r' /\
              (!E'' s:(A#A)->A#A.
                   E' PSUBSET E'' /\
                   E'' SUBSET complete_graph_edges V
                   ==> ~euler_planar_rotation V E'' s)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "euler") THEN
  ABBREV_TAC
   `candidates = {E':(A->bool)->bool |
       E SUBSET E' /\
       E' SUBSET complete_graph_edges V /\
       ?r':(A#A)->A#A. euler_planar_rotation V E' r'}` THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite_vertices") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation; FINITE_SIMPLE_GRAPH_EQ] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `E SUBSET complete_graph_edges (V:A->bool)`
  (LABEL_TAC "edges") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation; FINITE_SIMPLE_GRAPH_EQ] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(candidates:((A->bool)->bool)->bool)`
  (LABEL_TAC "finite_candidates") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `{E':(A->bool)->bool |
                 E' SUBSET complete_graph_edges V}` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_POWERSET THEN
      MATCH_MP_TAC FINITE_COMPLETE_GRAPH_EDGES THEN
      USE_THEN "finite_vertices" ACCEPT_TAC;
      EXPAND_TAC "candidates" THEN
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(candidates:((A->bool)->bool)->bool = {})`
  (LABEL_TAC "candidates_nonempty") THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `E:(A->bool)->bool` THEN
    EXPAND_TAC "candidates" THEN
    REWRITE_TAC[IN_ELIM_THM; SUBSET_REFL] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPEC `candidates:((A->bool)->bool)->bool`
    FINITE_MAXIMAL_ELEMENT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `E':(A->bool)->bool`
     (CONJUNCTS_THEN2 (LABEL_TAC "candidate")
      (LABEL_TAC "maximal")))] THEN
  USE_THEN "candidate" MP_TAC THEN EXPAND_TAC "candidates" THEN
  REWRITE_TAC[IN_ELIM_THM] THEN
  INTRO_TAC "contains within (@r'. extended_euler)" THEN
  MAP_EVERY EXISTS_TAC
   [`E':(A->bool)->bool`; `r':(A#A)->A#A`] THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC
   [`E'':(A->bool)->bool`; `s:(A#A)->A#A`] THEN
  INTRO_TAC "proper allowed" THEN
  DISCH_THEN(LABEL_TAC "larger_euler") THEN
  USE_THEN "maximal" (MP_TAC o SPEC `E'':(A->bool)->bool`) THEN
  ANTS_TAC THENL
   [EXPAND_TAC "candidates" THEN REWRITE_TAC[IN_ELIM_THM] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `E':(A->bool)->bool` THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "proper" MP_TAC THEN REWRITE_TAC[PSUBSET] THEN
      MESON_TAC[];
      ASM_MESON_TAC[]];
    ASM_MESON_TAC[]]);;

let MAXIMAL_EULER_PLANAR_ROTATION_COFACIAL_DART_HEADS_ADJACENT = prove
 (`!V E r:(A#A)->A#A. !d d':A#A.
        euler_planar_rotation V E r /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\
             E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s) /\
        d IN graph_darts E /\
        d' IN graph_face E r d /\
        ~(SND d = SND d')
        ==> {SND d,SND d'} IN E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "euler maximal d_dart cofacial distinct" THEN
  ASM_CASES_TAC `({SND(d:A#A),SND(d':A#A)}:A->bool) IN E` THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "euler"
     (ACCEPT_TAC o CONJUNCT1 o
      REWRITE_RULE[euler_planar_rotation]);
    ALL_TAC] THEN
  SUBGOAL_THEN `graph_rotation E (r:(A#A)->A#A)`
  (LABEL_TAC "rotation") THENL
   [USE_THEN "euler"
     (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o
      REWRITE_RULE[euler_planar_rotation]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(d':A#A) IN graph_darts E`
  (LABEL_TAC "d'_dart") THENL
   [MATCH_MP_TAC
     (REWRITE_RULE[SUBSET]
       (MATCH_MP
         (ISPECL
           [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
           GRAPH_FACE_SUBSET_DARTS)
         (CONJ (ASSUME `graph_rotation E (r:(A#A)->A#A)`)
               (ASSUME `(d:A#A) IN graph_darts E`)))) THEN
    USE_THEN "cofacial" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `SND(d:A#A) IN V /\ SND(d':A#A) IN V`
  (CONJUNCTS_THEN2 (LABEL_TAC "d_head")
    (LABEL_TAC "d'_head")) THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `FST(d:A#A)`; `SND(d:A#A)`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[PAIR] THEN MESON_TAC[];
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `FST(d':A#A)`; `SND(d':A#A)`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[PAIR] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(d:A#A) IN outgoing_darts E (SND d) /\
    reverse_dart(d':A#A) IN outgoing_darts E (SND d')`
  (CONJUNCTS_THEN2 (LABEL_TAC "d_anchor")
    (LABEL_TAC "d'_anchor")) THENL
   [CONJ_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS; GRAPH_DARTS_REVERSE;
                FST_REVERSE_DART] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC
   `r' =
      permutation_insert
       (permutation_insert (r:(A#A)->A#A)
         (SND(d:A#A),SND(d':A#A)) (reverse_dart d))
       (SND(d':A#A),SND(d:A#A)) (reverse_dart d')` THEN
  SUBGOAL_THEN
   `euler_planar_rotation
      (V:A->bool)
      ({SND(d:A#A),SND(d':A#A)} INSERT E) r'`
  (LABEL_TAC "extended_euler") THENL
   [EXPAND_TAC "r'" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `SND(d:A#A)`; `SND(d':A#A)`;
      `reverse_dart(d:A#A)`; `reverse_dart(d':A#A)`]
     EULER_PLANAR_ROTATION_INSERT_EDGE) THEN
    ASM_REWRITE_TAC[REVERSE_DART_INVOLUTION];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `E PSUBSET ({SND(d:A#A),SND(d':A#A)} INSERT E)`
  (LABEL_TAC "proper") THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `({SND(d:A#A),SND(d':A#A)} INSERT E)
    SUBSET complete_graph_edges V`
  (LABEL_TAC "allowed") THENL
   [USE_THEN "extended_euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation; FINITE_SIMPLE_GRAPH_EQ] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "maximal"
   (MP_TAC o SPECL
     [`{SND(d:A#A),SND(d':A#A)} INSERT E`;
      `r':(A#A)->A#A`]) THEN
  ASM_MESON_TAC[]);;

let MAXIMAL_EULER_PLANAR_ROTATION_EXTENSION_CONNECTED = prove
 (`!V E r:(A#A)->A#A.
        euler_planar_rotation V E r /\
        connected_graph V E
        ==> ?E' r'.
              E SUBSET E' /\
              connected_graph V E' /\
              euler_planar_rotation V E' r' /\
              (!E'' s:(A#A)->A#A.
                   E' PSUBSET E'' /\
                   E'' SUBSET complete_graph_edges V
                   ==> ~euler_planar_rotation V E'' s)`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler connected" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
   MAXIMAL_EULER_PLANAR_ROTATION_EXTENSION) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@E' r'. subset extended maximal" THEN
  MAP_EVERY EXISTS_TAC
   [`E':(A->bool)->bool`; `r':(A#A)->A#A`] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `E':(A->bool)->bool`]
   CONNECTED_GRAPH_MONO) THEN
  ASM_REWRITE_TAC[]);;

let graph_rotation_face_vertices = new_definition
 `graph_rotation_face_vertices
    (E:(A->bool)->bool) (r:(A#A)->A#A) d =
      IMAGE SND (graph_face E r d)`;;

let FINITE_GRAPH_ROTATION_FACE_VERTICES = prove
 (`!V E r d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        d IN graph_darts E
        ==> FINITE(graph_rotation_face_vertices E r d)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation dart" THEN
  REWRITE_TAC[graph_rotation_face_vertices] THEN
  MATCH_MP_TAC FINITE_IMAGE THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `r:(A#A)->A#A`; `d:A#A`]
   FINITE_GRAPH_FACE) THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_ROTATION_FACE_VERTICES_SUBSET = prove
 (`!V E r d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        d IN graph_darts E
        ==> graph_rotation_face_vertices E r d SUBSET V`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation dart" THEN
  REWRITE_TAC[graph_rotation_face_vertices; SUBSET; IN_IMAGE] THEN
  X_GEN_TAC `u:A` THEN
  INTRO_TAC "@a. head face" THEN
  USE_THEN "head" SUBST1_TAC THEN
  SUBGOAL_THEN `(a:A#A) IN graph_darts E`
  (LABEL_TAC "a_dart") THENL
   [MATCH_MP_TAC
     (REWRITE_RULE[SUBSET]
       (MATCH_MP
         (ISPECL
           [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
           GRAPH_FACE_SUBSET_DARTS)
         (CONJ (ASSUME `graph_rotation E (r:(A#A)->A#A)`)
               (ASSUME `(d:A#A) IN graph_darts E`)))) THEN
    USE_THEN "face" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `FST(a:A#A)`; `SND(a:A#A)`]
   FINITE_SIMPLE_GRAPH_DART) THEN
  ASM_REWRITE_TAC[PAIR] THEN MESON_TAC[]);;

let MAXIMAL_EULER_PLANAR_ROTATION_FACE_VERTICES_CLIQUE = prove
 (`!V E r d:A#A.
        euler_planar_rotation V E r /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\
             E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s) /\
        d IN graph_darts E
        ==> !u v.
              u IN graph_rotation_face_vertices E r d /\
              v IN graph_rotation_face_vertices E r d /\
              ~(u = v)
              ==> {u,v} IN E`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler maximal dart" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "euler"
     (ACCEPT_TAC o CONJUNCT1 o
      REWRITE_RULE[euler_planar_rotation]);
    ALL_TAC] THEN
  SUBGOAL_THEN `graph_rotation E (r:(A#A)->A#A)`
  (LABEL_TAC "rotation") THENL
   [USE_THEN "euler"
     (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o
      REWRITE_RULE[euler_planar_rotation]);
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`u:A`; `v:A`] THEN
  REWRITE_TAC[graph_rotation_face_vertices; IN_IMAGE] THEN
  INTRO_TAC
   "(@a. a_head a_face) (@b. b_head b_face) distinct" THEN
  SUBGOAL_THEN `(a:A#A) IN graph_darts E`
  (LABEL_TAC "a_dart") THENL
   [MATCH_MP_TAC
     (REWRITE_RULE[SUBSET]
       (MATCH_MP
         (ISPECL
           [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
           GRAPH_FACE_SUBSET_DARTS)
         (CONJ (ASSUME `graph_rotation E (r:(A#A)->A#A)`)
               (ASSUME `(d:A#A) IN graph_darts E`)))) THEN
    USE_THEN "a_face" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face E r (a:A#A) = graph_face E r d`
  (LABEL_TAC "same_face") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `d:A#A`; `a:A#A`] GRAPH_FACE_EQ) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(b:A#A) IN graph_face E r a`
  (LABEL_TAC "cofacial") THENL
   [USE_THEN "same_face" (fun th ->
      USE_THEN "b_face" (ACCEPT_TAC o REWRITE_RULE[GSYM th]));
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `a:A#A`; `b:A#A`]
   MAXIMAL_EULER_PLANAR_ROTATION_COFACIAL_DART_HEADS_ADJACENT) THEN
  ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Topological planarity implies componentwise Euler planarity.              *)
(* ------------------------------------------------------------------------- *)

let FINITE_SIMPLE_GRAPH_SINGLETON_EDGES_EMPTY = prove
 (`!E:(A->bool)->bool. !u:A.
        finite_simple_graph {u} E
        ==> E = {}`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  REWRITE_TAC[EXTENSION; NOT_IN_EMPTY] THEN
  X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
  MP_TAC(ISPECL
   [`{u:A}:A->bool`; `E:(A->bool)->bool`; `e:A->bool`]
   FINITE_SIMPLE_GRAPH_EDGE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@a b. a_vertex b_vertex distinct edge_pair" THEN
  ASM_MESON_TAC[IN_SING]);;

let CONNECTED_FINITE_SIMPLE_GRAPH_PAIR_EDGE = prove
 (`!E:(A->bool)->bool. !u v:A.
        finite_simple_graph {u,v} E /\
        connected_graph {u,v} E /\
        ~(u = v)
        ==> E = {{u,v}}`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected distinct" THEN
  SUBGOAL_THEN `E SUBSET {{u:A,v}}` (LABEL_TAC "subset") THENL
   [REWRITE_TAC[SUBSET; IN_SING] THEN
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    MP_TAC(ISPECL
     [`{u:A,v}:A->bool`; `E:(A->bool)->bool`; `e:A->bool`]
     FINITE_SIMPLE_GRAPH_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@a b. a_vertex b_vertex ab edge_pair" THEN
    USE_THEN "a_vertex" MP_TAC THEN
    USE_THEN "b_vertex" MP_TAC THEN
    REWRITE_TAC[IN_INSERT; IN_SING] THEN ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `({u:A,v}:A->bool) IN E` (LABEL_TAC "edge") THENL
   [ASM_CASES_TAC `({u:A,v}:A->bool) IN E` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `E = ({}:(A->bool)->bool)` (LABEL_TAC "empty") THENL
     [USE_THEN "subset" MP_TAC THEN ASM SET_TAC[];
      ALL_TAC] THEN
    USE_THEN "connected" (MP_TAC o REWRITE_RULE[connected_graph]) THEN
    DISCH_THEN(MP_TAC o SPECL [`u:A`; `v:A`]) THEN
    ASM_REWRITE_TAC[GRAPH_REACHABLE_EMPTY; IN_INSERT; IN_SING];
    ASM SET_TAC[]]);;

let CONNECTED_SMALL_EULER_ROTATION = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E /\
        connected_graph V E /\
        ~(V = {}) /\
        CARD V <= 2
        ==> ?r:(A#A)->A#A. euler_planar_rotation V E r`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected nonempty small" THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite") THENL
   [USE_THEN "graph"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[finite_simple_graph]);
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(V:A->bool) = 1 \/ CARD V = 2`
  (LABEL_TAC "card_cases") THENL
   [SUBGOAL_THEN `~(CARD(V:A->bool) = 0)` MP_TAC THENL
     [ASM_SIMP_TAC[CARD_EQ_0];
      ASM_ARITH_TAC];
    ALL_TAC] THEN
  USE_THEN "card_cases"
   (DISJ_CASES_THEN2 (LABEL_TAC "card_one") (LABEL_TAC "card_two")) THENL
   [SUBGOAL_THEN `(V:A->bool) HAS_SIZE 1` MP_TAC THENL
     [ASM_REWRITE_TAC[HAS_SIZE];
      REWRITE_TAC[HAS_SIZE_CONV `(V:A->bool) HAS_SIZE 1`] THEN
      INTRO_TAC "@u. vertices"] THEN
    SUBGOAL_THEN `E = ({}:(A->bool)->bool)` (LABEL_TAC "edges") THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `u:A`]
       FINITE_SIMPLE_GRAPH_SINGLETON_EDGES_EMPTY) THEN
      USE_THEN "vertices" (SUBST1_TAC o SYM) THEN
      USE_THEN "graph" ACCEPT_TAC;
      EXISTS_TAC `I:(A#A)->A#A` THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_ACCEPT_TAC EULER_PLANAR_ROTATION_SINGLETON_I];
    SUBGOAL_THEN `(V:A->bool) HAS_SIZE 2` MP_TAC THENL
     [ASM_REWRITE_TAC[HAS_SIZE];
      REWRITE_TAC[HAS_SIZE_CONV `(V:A->bool) HAS_SIZE 2`] THEN
      INTRO_TAC "@u v. distinct vertices"] THEN
    SUBGOAL_THEN `E = {{u:A,v}}` (LABEL_TAC "edges") THENL
     [MATCH_MP_TAC CONNECTED_FINITE_SIMPLE_GRAPH_PAIR_EDGE THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "vertices" (SUBST1_TAC o SYM) THEN
        USE_THEN "graph" ACCEPT_TAC;
        USE_THEN "vertices" (SUBST1_TAC o SYM) THEN
        USE_THEN "connected" ACCEPT_TAC;
        USE_THEN "distinct" ACCEPT_TAC];
      EXISTS_TAC `I:(A#A)->A#A` THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC EULER_PLANAR_ROTATION_SINGLE_EDGE THEN
      USE_THEN "distinct" ACCEPT_TAC]]);;

let FINITE_SIMPLE_GRAPH_SUBSET_EDGES = prove
 (`!V E E'.
        finite_simple_graph (V:A->bool) E /\ E' SUBSET E
        ==> finite_simple_graph V E'`,
  REWRITE_TAC[finite_simple_graph] THEN
  MESON_TAC[FINITE_SUBSET; SUBSET]);;

let PLANE_GRAPH_EMBEDDING_SUBSET_EDGES = prove
 (`!V E E' p c.
        plane_graph_embedding (V:A->bool) E p c /\ E' SUBSET E
        ==> plane_graph_embedding V E' p c`,
  REWRITE_TAC[plane_graph_embedding] THEN MESON_TAC[SUBSET]);;

let PLANAR_GRAPH_SUBSET_EDGES = prove
 (`!V E E'.
        planar_graph (V:A->bool) E /\ E' SUBSET E
        ==> planar_graph V E'`,
  REWRITE_TAC[planar_graph] THEN
  MESON_TAC[FINITE_SIMPLE_GRAPH_SUBSET_EDGES;
            PLANE_GRAPH_EMBEDDING_SUBSET_EDGES]);;

let PLANAR_GRAPH_INDUCED_SUBGRAPH = prove
 (`!V E W.
        planar_graph (V:A->bool) E /\ W SUBSET V
        ==> planar_graph W (induced_subgraph_edges E W)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[planar_graph] THEN
  INTRO_TAC "(graph @p c. embedding) subset" THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `W:A->bool`]
     FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH) THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY EXISTS_TAC
     [`p:A->real^2`; `c:(A->bool)->real^2->bool`] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A->real^2`;
      `c:(A->bool)->real^2->bool`; `W:A->bool`]
     PLANE_GRAPH_EMBEDDING_INDUCED_SUBGRAPH) THEN
    ASM_REWRITE_TAC[]]);;

let PLANAR_GRAPH_SUBGRAPH = prove
 (`!V E W F.
        planar_graph (V:A->bool) E /\
        W SUBSET V /\
        F SUBSET induced_subgraph_edges E W
        ==> planar_graph W F`,
  MESON_TAC[PLANAR_GRAPH_INDUCED_SUBGRAPH;
            PLANAR_GRAPH_SUBSET_EDGES]);;

let PLANAR_GRAPH_IMP_EULER_PLANAR_GRAPH = prove
 (`!V E.
        planar_graph (V:A->bool) E
        ==> euler_planar_graph V E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "planar") THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "planar"
     (ACCEPT_TAC o CONJUNCT1 o
      REWRITE_RULE[planar_graph]);
    ALL_TAC] THEN
  REWRITE_TAC[euler_planar_graph] THEN
  CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "vertex") THEN
  SUBGOAL_THEN `graph_component E (u:A) SUBSET V`
  (LABEL_TAC "component_subset") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
     GRAPH_COMPONENT_SUBSET) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph
      (graph_component E (u:A)) (graph_component_edges E u)`
  (LABEL_TAC "component_graph") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
     FINITE_SIMPLE_GRAPH_COMPONENT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph
      (graph_component E (u:A)) (graph_component_edges E u)`
  (LABEL_TAC "component_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
     GRAPH_COMPONENT_EDGES_CONNECTED) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(graph_component E (u:A) = {})`
  (LABEL_TAC "component_nonempty") THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `u:A` THEN MATCH_ACCEPT_TAC GRAPH_COMPONENT_REFL;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `planar_graph
      (graph_component E (u:A)) (graph_component_edges E u)`
  (LABEL_TAC "component_planar") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `graph_component E (u:A)`]
     PLANAR_GRAPH_INDUCED_SUBGRAPH) THEN
    ASM_REWRITE_TAC[induced_subgraph_edges; graph_component_edges];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`graph_component E (u:A)`;
    `graph_component_edges E u:(A->bool)->bool`]
   PLANAR_GRAPH_IMP_RECURSIVE_PLANAR_GRAPH) THEN
  ASM_REWRITE_TAC[recursive_planar_graph] THEN
  DISCH_THEN(LABEL_TAC "certificate") THEN
  USE_THEN "certificate"
   (DISJ_CASES_THEN2 (LABEL_TAC "small")
     (X_CHOOSE_THEN `E':(A->bool)->bool`
      (X_CHOOSE_THEN `q:num->A`
       (CONJUNCTS_THEN2 (LABEL_TAC "edge_subset")
        (LABEL_TAC "recursive"))))) THENL
   [MATCH_MP_TAC CONNECTED_SMALL_EULER_ROTATION THEN
    ASM_REWRITE_TAC[];
    MP_TAC(ISPECL
     [`graph_component E (u:A)`;
      `E':(A->bool)->bool`; `q:num->A`; `3`]
     RECURSIVE_TRIANGULATED_DISK_BOUNDARY_EULER_ROTATION) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "extended_cycle @r. boundary" THEN
    MATCH_MP_TAC(ISPECL
     [`graph_component E (u:A)`;
      `graph_component_edges E u:(A->bool)->bool`;
      `E':(A->bool)->bool`; `r:(A#A)->A#A`]
     EULER_PLANAR_ROTATION_SUBSET_CONNECTED) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation] THEN MESON_TAC[]]);;

(* ========================================================================= *)
(* Subdivisions, Euler bounds, and planar obstructions.                      *)
(* ========================================================================= *)

(* ------------------------------------------------------------------------- *)
(* Edge subdivisions and topological subgraphs.                              *)
(*                                                                           *)
(* A one-edge subdivision replaces {u,v} by {u,w} and {w,v}, where w is a    *)
(* fresh vertex.  The inductive closure gives a combinatorial certificate    *)
(* that one graph is a subdivision of another.  The main geometric result    *)
(* suppresses a subdivision vertex in an arc embedding; consequently, any    *)
(* topological subgraph of a planar graph is itself planar.                  *)
(* ------------------------------------------------------------------------- *)

let PAIR_HAS_SIZE_2 = prove
 (`!u v:A. ({u,v}:A->bool) HAS_SIZE 2 <=> ~(u = v)`,
  REPEAT GEN_TAC THEN ASM_CASES_TAC `u:A = v` THEN
  ASM_REWRITE_TAC[] THEN
  ASM_SIMP_TAC[HAS_SIZE; FINITE_INSERT; FINITE_EMPTY;
               CARD_CLAUSES; IN_SING; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let graph_edge_subdivision = new_definition
 `graph_edge_subdivision
    (V:A->bool) (E:(A->bool)->bool) V' E' <=>
      ?u v w.
        {u,v} IN E /\
        ~(w IN V) /\
        V' = w INSERT V /\
        E' = {{u,w},{w,v}} UNION (E DELETE {u,v})`;;

let FINITE_SIMPLE_GRAPH_EDGE_SUBDIVISION = prove
 (`!V E V' E'.
        finite_simple_graph (V:A->bool) E /\
        graph_edge_subdivision V E V' E'
        ==> finite_simple_graph V' E'`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph subdivision" THEN
  USE_THEN "subdivision" MP_TAC THEN
  REWRITE_TAC[graph_edge_subdivision] THEN
  INTRO_TAC "@u v w. edge fresh vertices edges" THEN
  SUBGOAL_THEN
   `{u:A,v} SUBSET V /\ ({u:A,v}:A->bool) HAS_SIZE 2`
  (CONJUNCTS_THEN2 (LABEL_TAC "edge_subset") (LABEL_TAC "edge_size")) THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(u:A = v)` (LABEL_TAC "uv") THENL
   [USE_THEN "edge_size" MP_TAC THEN
    REWRITE_TAC[PAIR_HAS_SIZE_2];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(u:A = w) /\ ~(w:A = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "uw") (LABEL_TAC "wv")) THENL
   [USE_THEN "edge_subset" MP_TAC THEN
    USE_THEN "fresh" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  USE_THEN "graph" MP_TAC THEN
  REWRITE_TAC[finite_simple_graph] THEN
  INTRO_TAC "finite_vertices finite_edges old_edge" THEN
  SUBGOAL_THEN `(u:A) IN V /\ (v:A) IN V`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex") (LABEL_TAC "v_vertex")) THENL
   [USE_THEN "edge_subset" MP_TAC THEN
    REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN MESON_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[finite_simple_graph] THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[FINITE_INSERT];
    ASM_REWRITE_TAC[FINITE_UNION; FINITE_INSERT; FINITE_EMPTY;
                    FINITE_DELETE];
    REWRITE_TAC[FORALL_IN_UNION; FORALL_IN_INSERT; NOT_IN_EMPTY] THEN
    CONJ_TAC THENL
     [CONJ_TAC THENL
       [CONJ_TAC THENL
         [ASM_REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_INSERT];
          ASM_REWRITE_TAC[PAIR_HAS_SIZE_2]];
        CONJ_TAC THENL
         [ASM_REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_INSERT];
          ASM_REWRITE_TAC[PAIR_HAS_SIZE_2]]];
      X_GEN_TAC `d:A->bool` THEN INTRO_TAC "old" THEN
      SUBGOAL_THEN `d SUBSET V /\ (d:A->bool) HAS_SIZE 2`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "old_edge" (MP_TAC o SPEC `d:A->bool`) THEN
        FIRST_X_ASSUM(MP_TAC) THEN
        REWRITE_TAC[IN_DELETE] THEN MESON_TAC[];
        CONJ_TAC THENL
         [MATCH_MP_TAC SUBSET_TRANS THEN
          EXISTS_TAC `V:A->bool` THEN
          ASM_REWRITE_TAC[] THEN
          REWRITE_TAC[SUBSET; IN_INSERT] THEN MESON_TAC[];
          ASM_REWRITE_TAC[]]]]]);;

let EDGE_SUBDIVISION_INDUCED_SUBGRAPH = prove
 (`!V E u v w.
        finite_simple_graph (V:A->bool) E /\
        {u,v} IN E /\
        ~(w IN V)
        ==> induced_subgraph_edges
             ({{u,w},{w,v}} UNION (E DELETE {u,v})) V =
            E DELETE {u,v}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[finite_simple_graph] THEN
  INTRO_TAC "(_ _ old_edge) edge fresh" THEN
  REWRITE_TAC[EXTENSION; IN_INDUCED_SUBGRAPH_EDGES] THEN
  X_GEN_TAC `d:A->bool` THEN
  REWRITE_TAC[IN_UNION; IN_DELETE] THEN
  EQ_TAC THENL
   [INTRO_TAC "((new | old not_replaced)) subset" THENL
     [USE_THEN "new" MP_TAC THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN
      DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
      USE_THEN "subset" MP_TAC THEN
      REWRITE_TAC[SUBSET; IN_INSERT; IN_SING] THEN
      ASM_MESON_TAC[];
      ASM_REWRITE_TAC[]];
    INTRO_TAC "old not_replaced" THEN
    CONJ_TAC THENL
     [DISJ2_TAC THEN ASM_REWRITE_TAC[];
      USE_THEN "old_edge" (fun th ->
       USE_THEN "old" (fun eth ->
        ACCEPT_TAC(CONJUNCT1(MATCH_MP (SPEC `d:A->bool` th) eth))))]]);;

let PLANAR_GRAPH_EDGE_SUBDIVISION_IMP = prove
 (`!V E V' E'.
        finite_simple_graph (V:A->bool) E /\
        graph_edge_subdivision V E V' E' /\
        planar_graph V' E'
        ==> planar_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph subdivision planar" THEN
  USE_THEN "subdivision" MP_TAC THEN
  REWRITE_TAC[graph_edge_subdivision] THEN
  INTRO_TAC "@u v w. edge fresh vertices edges" THEN
  USE_THEN "vertices" SUBST_ALL_TAC THEN
  USE_THEN "edges" SUBST_ALL_TAC THEN
  SUBGOAL_THEN
   `{u:A,v} SUBSET V /\ ({u:A,v}:A->bool) HAS_SIZE 2`
  (CONJUNCTS_THEN2 (LABEL_TAC "edge_subset") (LABEL_TAC "edge_size")) THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(u:A = v)` (LABEL_TAC "uv") THENL
   [USE_THEN "edge_size" MP_TAC THEN
    REWRITE_TAC[PAIR_HAS_SIZE_2];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(u:A = w) /\ ~(w:A = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "uw") (LABEL_TAC "wv")) THENL
   [USE_THEN "edge_subset" MP_TAC THEN
    USE_THEN "fresh" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  USE_THEN "planar" MP_TAC THEN
  REWRITE_TAC[planar_graph] THEN
  INTRO_TAC "subdivided_graph @p c. embedding" THEN
  MP_TAC(ISPECL
   [`w INSERT V:A->bool`;
    `{{u:A,w},{w:A,v}} UNION
       (E DELETE {u:A,v}):(A->bool)->bool`;
    `p:A->real^2`; `c:(A->bool)->real^2->bool`;
    `u:A`; `w:A`; `v:A`]
   PLANE_GRAPH_EMBEDDING_TWO_EDGE_ARC) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[IN_UNION; IN_INSERT; IN_SING];
    INTRO_TAC "@g. arc path_image pathstart pathfinish"] THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) (E DELETE {u,v})`
  (LABEL_TAC "old_graph") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `E DELETE {u:A,v}`]
     FINITE_SIMPLE_GRAPH_SUBSET_EDGES) THEN
    CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      REWRITE_TAC[SUBSET; IN_DELETE] THEN
      REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `plane_graph_embedding
      (V:A->bool) (E DELETE {u,v}) (p:A->real^2) c`
  (LABEL_TAC "old_embedding") THENL
   [MP_TAC(ISPECL
     [`w INSERT V:A->bool`;
      `{{u:A,w},{w:A,v}} UNION
         (E DELETE {u:A,v}):(A->bool)->bool`;
      `p:A->real^2`; `c:(A->bool)->real^2->bool`; `V:A->bool`]
     PLANE_GRAPH_EMBEDDING_INDUCED_SUBGRAPH) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "embedding" ACCEPT_TAC;
        REWRITE_TAC[SUBSET; IN_INSERT] THEN
        X_GEN_TAC `x:A` THEN DISCH_TAC THEN DISJ2_TAC THEN
        ASM_REWRITE_TAC[]];
      ASM_SIMP_TAC[EDGE_SUBDIVISION_INDUCED_SUBGRAPH]];
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (p:A->real^2) (w INSERT V) UNIV`
  (LABEL_TAC "injective") THENL
   [USE_THEN "embedding" (fun th ->
     ACCEPT_TAC(CONJUNCT1(REWRITE_RULE[plane_graph_embedding] th)));
    ALL_TAC] THEN
  SUBGOAL_THEN `~((p:A->real^2) w IN IMAGE p V)`
  (LABEL_TAC "new_point") THENL
   [REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@x. x_vertex point" THEN
    USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV] THEN
    DISCH_THEN(MP_TAC o SPECL [`w:A`; `x:A`]) THEN
    ASM_REWRITE_TAC[IN_INSERT] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) {u,w} INTER
       IMAGE p (w INSERT V) = IMAGE p {u,w}`
  (LABEL_TAC "uw_vertices") THENL
   [USE_THEN "embedding" MP_TAC THEN
    REWRITE_TAC[plane_graph_embedding] THEN
    INTRO_TAC "_ _ edge_vertices _" THEN
    USE_THEN "edge_vertices" MATCH_MP_TAC THEN
    REWRITE_TAC[IN_UNION; IN_INSERT; IN_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:(A->bool)->real^2->bool) {w,v} INTER
       IMAGE p (w INSERT V) = IMAGE p {w,v}`
  (LABEL_TAC "wv_vertices") THENL
   [USE_THEN "embedding" MP_TAC THEN
    REWRITE_TAC[plane_graph_embedding] THEN
    INTRO_TAC "_ _ edge_vertices _" THEN
    USE_THEN "edge_vertices" MATCH_MP_TAC THEN
    REWRITE_TAC[IN_UNION; IN_INSERT; IN_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (p:A->real^2) {u,v} SUBSET IMAGE p V`
  (LABEL_TAC "old_endpoint_images") THENL
   [MATCH_MP_TAC IMAGE_SUBSET THEN
    USE_THEN "edge_subset" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `path_image(g:real^1->real^2) INTER IMAGE p V =
    IMAGE (p:A->real^2) {u,v}`
  (LABEL_TAC "old_vertices") THENL
   [USE_THEN "path_image" MP_TAC THEN
    USE_THEN "uw_vertices" MP_TAC THEN
    USE_THEN "wv_vertices" MP_TAC THEN
    USE_THEN "new_point" MP_TAC THEN
    USE_THEN "old_endpoint_images" MP_TAC THEN
    REWRITE_TAC[IMAGE_CLAUSES] THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E DELETE {u:A,v}`;
    `p:A->real^2`; `c:(A->bool)->real^2->bool`;
    `{u:A,v}`; `g:real^1->real^2`]
   PLANAR_GRAPH_INSERT_EDGE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "old_graph" ACCEPT_TAC;
      USE_THEN "old_embedding" ACCEPT_TAC;
      USE_THEN "edge_subset" ACCEPT_TAC;
      USE_THEN "edge_size" ACCEPT_TAC;
      SET_TAC[];
      USE_THEN "arc" ACCEPT_TAC;
      ASM_REWRITE_TAC[IMAGE_CLAUSES];
      USE_THEN "old_vertices" ACCEPT_TAC;
      X_GEN_TAC `d:A->bool` THEN
      REWRITE_TAC[IN_DELETE] THEN
      INTRO_TAC "d_old not_replaced" THEN
      SUBGOAL_THEN `(d:A->bool) SUBSET V` (LABEL_TAC "d_subset") THENL
       [USE_THEN "graph" MP_TAC THEN
        REWRITE_TAC[finite_simple_graph] THEN
        INTRO_TAC "_ _ edge_data" THEN
        USE_THEN "edge_data" (fun th ->
         USE_THEN "d_old" (fun eth ->
          ACCEPT_TAC
           (CONJUNCT1(MATCH_MP (SPEC `d:A->bool` th) eth))));
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(c:(A->bool)->real^2->bool) {u,w} INTER c d =
        IMAGE p ({u,w} INTER d)`
      (LABEL_TAC "uw_inter") THENL
       [MATCH_MP_TAC(ISPECL
         [`w INSERT V:A->bool`;
          `{{u:A,w},{w:A,v}} UNION
             (E DELETE {u:A,v}):(A->bool)->bool`;
          `p:A->real^2`; `c:(A->bool)->real^2->bool`;
          `{u:A,w}`; `d:A->bool`]
         PLANE_GRAPH_EMBEDDING_EDGE_INTER) THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "embedding" ACCEPT_TAC;
          REWRITE_TAC[IN_UNION; IN_INSERT; IN_SING];
          REWRITE_TAC[IN_UNION; IN_DELETE] THEN DISJ2_TAC THEN
          ASM_REWRITE_TAC[];
          INTRO_TAC "same" THEN
          USE_THEN "same" MP_TAC THEN
          USE_THEN "d_subset" MP_TAC THEN
          USE_THEN "fresh" MP_TAC THEN SET_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(c:(A->bool)->real^2->bool) {w,v} INTER c d =
        IMAGE p ({w,v} INTER d)`
      (LABEL_TAC "wv_inter") THENL
       [MATCH_MP_TAC(ISPECL
         [`w INSERT V:A->bool`;
          `{{u:A,w},{w:A,v}} UNION
             (E DELETE {u:A,v}):(A->bool)->bool`;
          `p:A->real^2`; `c:(A->bool)->real^2->bool`;
          `{w:A,v}`; `d:A->bool`]
         PLANE_GRAPH_EMBEDDING_EDGE_INTER) THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "embedding" ACCEPT_TAC;
          REWRITE_TAC[IN_UNION; IN_INSERT; IN_SING];
          REWRITE_TAC[IN_UNION; IN_DELETE] THEN DISJ2_TAC THEN
          ASM_REWRITE_TAC[];
          INTRO_TAC "same" THEN
          USE_THEN "same" MP_TAC THEN
          USE_THEN "d_subset" MP_TAC THEN
          USE_THEN "fresh" MP_TAC THEN SET_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `({u:A,w} INTER d) UNION ({w:A,v} INTER d) =
        {u:A,v} INTER d`
      (LABEL_TAC "edge_intersections") THENL
       [USE_THEN "d_subset" MP_TAC THEN
        USE_THEN "fresh" MP_TAC THEN SET_TAC[];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[SET_RULE
       `((s:real^2->bool) UNION t) INTER d =
        (s INTER d) UNION (t INTER d)`;
       GSYM IMAGE_UNION]];
    DISCH_THEN(LABEL_TAC "restored") THEN
    SUBGOAL_THEN
     `({u:A,v} INSERT (E DELETE {u,v})) = E`
    (LABEL_TAC "restore_edges") THENL
     [USE_THEN "edge" MP_TAC THEN SET_TAC[];
      CONJ_TAC THENL
       [USE_THEN "graph" ACCEPT_TAC;
        USE_THEN "restored" (fun th ->
         USE_THEN "restore_edges" (fun eth ->
          ACCEPT_TAC
           (CONJUNCT2
             (REWRITE_RULE[eth; planar_graph] th))))]]]);;

let graph_subdivision_RULES,
    graph_subdivision_INDUCT,
    graph_subdivision_CASES = new_inductive_definition
 `(!V E.
        finite_simple_graph (V:A->bool) E
        ==> graph_subdivision V E V E) /\
  (!V E V' E' V'' E''.
        graph_subdivision (V:A->bool) E V' E' /\
        graph_edge_subdivision V' E' V'' E''
        ==> graph_subdivision V E V'' E'')`;;

let GRAPH_SUBDIVISION_FINITE_SIMPLE = prove
 (`!V E V' E'.
        graph_subdivision (V:A->bool) E V' E'
        ==> finite_simple_graph V E /\ finite_simple_graph V' E'`,
  MATCH_MP_TAC graph_subdivision_INDUCT THEN
  CONJ_TAC THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN ASM_REWRITE_TAC[];
    REPEAT GEN_TAC THEN
    INTRO_TAC "(source target) edge_step" THEN
    CONJ_TAC THENL
     [USE_THEN "source" ACCEPT_TAC;
      MATCH_MP_TAC(ISPECL
       [`V':A->bool`; `E':(A->bool)->bool`;
        `V'':A->bool`; `E'':(A->bool)->bool`]
       FINITE_SIMPLE_GRAPH_EDGE_SUBDIVISION) THEN
      ASM_REWRITE_TAC[]]]);;

let PLANAR_GRAPH_SUBDIVISION_IMP = prove
 (`!V E V' E'.
        graph_subdivision (V:A->bool) E V' E' /\
        planar_graph V' E'
        ==> planar_graph V E`,
  SUBGOAL_THEN
   `!V E V' E'.
        graph_subdivision (V:A->bool) E V' E'
        ==> finite_simple_graph V' E' /\
            (planar_graph V' E'
             ==> planar_graph V E)`
  MP_TAC THENL
   [MATCH_MP_TAC graph_subdivision_INDUCT THEN
    CONJ_TAC THENL
     [REPEAT GEN_TAC THEN INTRO_TAC "graph" THEN
      CONJ_TAC THENL
       [USE_THEN "graph" ACCEPT_TAC;
        DISCH_TAC THEN FIRST_ASSUM ACCEPT_TAC];
      REPEAT GEN_TAC THEN
      INTRO_TAC
       "(intermediate_graph reflection) edge_step" THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL
         [`V':A->bool`; `E':(A->bool)->bool`;
          `V'':A->bool`; `E'':(A->bool)->bool`]
         FINITE_SIMPLE_GRAPH_EDGE_SUBDIVISION) THEN
        ASM_REWRITE_TAC[];
        INTRO_TAC "final_planar" THEN
        USE_THEN "reflection" MATCH_MP_TAC THEN
        MATCH_MP_TAC(ISPECL
         [`V':A->bool`; `E':(A->bool)->bool`;
          `V'':A->bool`; `E'':(A->bool)->bool`]
         PLANAR_GRAPH_EDGE_SUBDIVISION_IMP) THEN
        ASM_REWRITE_TAC[]]];
    DISCH_THEN(LABEL_TAC "induction") THEN
    REPEAT GEN_TAC THEN INTRO_TAC "subdivision planar" THEN
    USE_THEN "induction" (fun ith ->
     USE_THEN "subdivision" (fun sth ->
      USE_THEN "planar" (fun pth ->
       ACCEPT_TAC
        (MATCH_MP
          (CONJUNCT2
            (MATCH_MP
              (SPECL [`V:A->bool`; `E:(A->bool)->bool`;
                      `V':A->bool`; `E':(A->bool)->bool`] ith)
              sth))
          pth))))]);;

let graph_topological_subgraph = new_definition
 `graph_topological_subgraph
    (W:A->bool) (D:(A->bool)->bool) V E <=>
      ?W' F'.
        graph_subdivision W D W' F' /\
        W' SUBSET V /\
        F' SUBSET induced_subgraph_edges E W'`;;

let PLANAR_GRAPH_TOPOLOGICAL_SUBGRAPH = prove
 (`!V E W D.
        planar_graph (V:A->bool) E /\
        graph_topological_subgraph W D V E
        ==> planar_graph W D`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_topological_subgraph] THEN
  INTRO_TAC "planar (@W' F'. subdivision vertices edges)" THEN
  MATCH_MP_TAC(ISPECL
   [`W:A->bool`; `D:(A->bool)->bool`;
    `W':A->bool`; `F':(A->bool)->bool`]
   PLANAR_GRAPH_SUBDIVISION_IMP) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `W':A->bool`; `F':(A->bool)->bool`]
   PLANAR_GRAPH_SUBGRAPH) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Complete-graph cardinalities and elementary planar obstructions.          *)
(* ------------------------------------------------------------------------- *)

let CARD_COMPLETE_GRAPH_EDGES = prove
 (`!V:A->bool.
        FINITE V
        ==> CARD(complete_graph_edges V) = binom(CARD V,2)`,
  GEN_TAC THEN DISCH_THEN(LABEL_TAC "finite") THEN
  REWRITE_TAC[complete_graph_edges] THEN
  MATCH_MP_TAC CARD_RESTRICTED_POWERSET THEN
  USE_THEN "finite" ACCEPT_TAC);;

let complete_bipartite_edges = new_definition
 `complete_bipartite_edges (X:A->bool) (Y:A->bool) =
        IMAGE (\p:A#A. {FST p,SND p}) (X CROSS Y)`;;

let IN_COMPLETE_BIPARTITE_EDGES = prove
 (`!X Y e:A->bool.
        e IN complete_bipartite_edges X Y <=>
        ?x y. x IN X /\ y IN Y /\ e = {x,y}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[complete_bipartite_edges; IN_IMAGE; EXISTS_PAIR_THM;
              IN_CROSS; FST; SND] THEN MESON_TAC[]);;

let FINITE_SIMPLE_COMPLETE_BIPARTITE_GRAPH = prove
 (`!X Y:A->bool.
        FINITE X /\ FINITE Y /\ DISJOINT X Y
        ==> finite_simple_graph
             (X UNION Y) (complete_bipartite_edges X Y)`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite_X finite_Y disjoint" THEN
  REWRITE_TAC[FINITE_SIMPLE_GRAPH_EQ] THEN CONJ_TAC THENL
   [ASM_REWRITE_TAC[FINITE_UNION];
    REWRITE_TAC[SUBSET; IN_COMPLETE_BIPARTITE_EDGES;
                IN_COMPLETE_GRAPH_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN
     INTRO_TAC "@x y. x_member y_member edge" THEN
    USE_THEN "edge" SUBST1_TAC THEN CONJ_TAC THENL
     [REWRITE_TAC[IN_INSERT; IN_SING; IN_UNION] THEN
      ASM_MESON_TAC[];
      SUBGOAL_THEN `~(x:A = y)` (LABEL_TAC "distinct") THENL
       [DISCH_THEN SUBST_ALL_TAC THEN
        USE_THEN "disjoint" MP_TAC THEN
        REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
        DISCH_THEN(MP_TAC o SPEC `y:A`) THEN ASM_REWRITE_TAC[];
        REWRITE_TAC
         [HAS_SIZE_CONV `({x:A,y}:A->bool) HAS_SIZE 2`] THEN
        MAP_EVERY EXISTS_TAC [`x:A`; `y:A`] THEN
        ASM_REWRITE_TAC[]]]]);;

let CARD_COMPLETE_BIPARTITE_EDGES = prove
 (`!X Y:A->bool.
        FINITE X /\ FINITE Y /\ DISJOINT X Y
        ==> CARD(complete_bipartite_edges X Y) = CARD X * CARD Y`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite_X finite_Y disjoint" THEN
  REWRITE_TAC[complete_bipartite_edges] THEN
  TRANS_TAC EQ_TRANS `CARD((X:A->bool) CROSS (Y:A->bool))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC CARD_IMAGE_INJ THEN
    CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`p:A#A`; `p':A#A`] THEN
      INTRO_TAC "p_member p'_member same_edge" THEN
      MP_TAC(ISPEC `p:A#A` PAIR_SURJECTIVE) THEN
      DISCH_THEN(X_CHOOSE_THEN `x:A`
       (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
      MP_TAC(ISPEC `p':A#A` PAIR_SURJECTIVE) THEN
      DISCH_THEN(X_CHOOSE_THEN `x':A`
       (X_CHOOSE_THEN `y':A` SUBST_ALL_TAC)) THEN
      USE_THEN "p_member" MP_TAC THEN
      USE_THEN "p'_member" MP_TAC THEN
      USE_THEN "same_edge" MP_TAC THEN
      USE_THEN "disjoint" MP_TAC THEN
      REWRITE_TAC[IN_CROSS; FST; SND; PAIR_EQ; DISJOINT] THEN
      SET_TAC[];
      MATCH_MP_TAC FINITE_CROSS THEN ASM_REWRITE_TAC[]];
    MATCH_MP_TAC CARD_CROSS THEN ASM_REWRITE_TAC[]]);;

let COMPLETE_BIPARTITE_GRAPH_CONNECTED = prove
 (`!X Y:A->bool.
        ~(X = {}) /\ ~(Y = {})
        ==> connected_graph
             (X UNION Y) (complete_bipartite_edges X Y)`,
  REPEAT GEN_TAC THEN INTRO_TAC "X_nonempty Y_nonempty" THEN
  SUBGOAL_THEN `?x:A. x IN X`
  (X_CHOOSE_THEN `x0:A` (LABEL_TAC "x0")) THENL
   [USE_THEN "X_nonempty" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?y:A. y IN Y`
  (X_CHOOSE_THEN `y0:A` (LABEL_TAC "y0")) THENL
   [USE_THEN "Y_nonempty" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x y:A.
        x IN X /\ y IN Y
        ==> graph_reachable (complete_bipartite_edges X Y) x y /\
            graph_reachable (complete_bipartite_edges X Y) y x`
  (LABEL_TAC "cross_reachable") THENL
   [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    INTRO_TAC "x_member y_member" THEN CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
      REWRITE_TAC[IN_COMPLETE_BIPARTITE_EDGES] THEN
      MAP_EVERY EXISTS_TAC [`x:A`; `y:A`] THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
      MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
      REWRITE_TAC[IN_COMPLETE_BIPARTITE_EDGES] THEN
      MAP_EVERY EXISTS_TAC [`x:A`; `y:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[connected_graph] THEN
  MAP_EVERY X_GEN_TAC [`u:A`; `v:A`] THEN
  REWRITE_TAC[IN_UNION] THEN
  DISCH_THEN(CONJUNCTS_THEN2
   (DISJ_CASES_THEN2 (LABEL_TAC "u_X") (LABEL_TAC "u_Y"))
   (DISJ_CASES_THEN2 (LABEL_TAC "v_X") (LABEL_TAC "v_Y"))) THEN
  ASM_MESON_TAC[GRAPH_REACHABLE_TRANS]);;

let HAS_SIZE_3_OTHER = prove
 (`!S u:A.
        S HAS_SIZE 3 /\ u IN S
        ==> ?v. v IN S /\ ~(v = u)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[HAS_SIZE_CONV `S:A->bool HAS_SIZE 3`] THEN
  SET_TAC[]);;

let COMPLETE_BIPARTITE_DART = prove
 (`!X Y u v:A.
        (u,v) IN graph_darts (complete_bipartite_edges X Y) <=>
        (u IN X /\ v IN Y) \/ (u IN Y /\ v IN X)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_GRAPH_DARTS] THEN EQ_TAC THENL
   [REWRITE_TAC[IN_COMPLETE_BIPARTITE_EDGES] THEN
    INTRO_TAC "@x y. x_member y_member edge" THEN
    MP_TAC(MATCH_MP
     (SET_RULE
      `{u:A,v} = {x,y}
       ==> (u = x /\ v = y) \/ (u = y /\ v = x)`)
     (ASSUME `{u:A,v} = {x,y}`)) THEN
    ASM_MESON_TAC[];
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "forward")
     (LABEL_TAC "reverse")) THEN
    REWRITE_TAC[IN_COMPLETE_BIPARTITE_EDGES] THENL
     [MAP_EVERY EXISTS_TAC [`u:A`; `v:A`] THEN ASM_REWRITE_TAC[];
      MAP_EVERY EXISTS_TAC [`v:A`; `u:A`] THEN ASM_REWRITE_TAC[] THEN
      SET_TAC[]]]);;

let GRAPH_FACE_SUCCESSOR_SQUARE_FIXED = prove
 (`!E r d:A#A.
        graph_rotation E r /\
        d IN graph_darts E /\
        ITER 2 (graph_face_successor E r) d = d
        ==> outgoing_darts E (SND d) = {reverse_dart d}`,
  REPEAT GEN_TAC THEN INTRO_TAC "rotation dart square" THEN
  ABBREV_TAC `d1 = graph_face_successor E (r:(A#A)->A#A) d` THEN
  SUBGOAL_THEN `(d1:A#A) IN graph_darts E`
  (LABEL_TAC "d1_dart") THENL
   [EXPAND_TAC "d1" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_DART THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A) d1 = d`
  (LABEL_TAC "return") THENL
   [ONCE_REWRITE_TAC
     [GSYM(ASSUME
       `graph_face_successor E (r:(A#A)->A#A) d = d1`)] THEN
    USE_THEN "square" MP_TAC THEN
    REWRITE_TAC[num_CONV `2`; num_CONV `1`; ITER];
    ALL_TAC] THEN
  SUBGOAL_THEN `FST(d1:A#A) = SND(d:A#A)`
  (LABEL_TAC "d1_tail") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_FACE_SUCCESSOR_TAIL) THEN
    ASM_REWRITE_TAC
     [ASSUME `graph_face_successor E (r:(A#A)->A#A) d = d1`];
    ALL_TAC] THEN
  SUBGOAL_THEN `SND(d1:A#A) = FST(d:A#A)`
  (LABEL_TAC "d1_head") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d1:A#A`]
     GRAPH_FACE_SUCCESSOR_TAIL) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(d1:A#A) = reverse_dart(d:A#A)`
  (LABEL_TAC "d1_reverse") THENL
   [MP_TAC(ISPEC `d:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A`
     (X_CHOOSE_THEN `v:A` SUBST_ALL_TAC)) THEN
    MP_TAC(ISPEC `d1:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    USE_THEN "d1_tail" MP_TAC THEN
    USE_THEN "d1_head" MP_TAC THEN
    REWRITE_TAC[FST; SND; REVERSE_DART_PAIR; PAIR_EQ] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `r(reverse_dart(d:A#A)) = reverse_dart d`
  (LABEL_TAC "rotation_fixed") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_FACE_SUCCESSOR_IN) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[EXTENSION; IN_OUTGOING_DARTS; IN_SING] THEN
