let COMPLETE_BIPARTITE_FACE_SUCCESSOR_NO_FIXEDPOINT = prove
 (`!X Y r u v:A.
        DISJOINT X Y /\
        graph_rotation (complete_bipartite_edges X Y) r /\
        (u,v) IN graph_darts (complete_bipartite_edges X Y)
        ==> ~(graph_face_successor
               (complete_bipartite_edges X Y) r (u,v) = (u,v))`,
  REPEAT GEN_TAC THEN INTRO_TAC "disjoint rotation dart" THEN
  DISCH_THEN(LABEL_TAC "fixed") THEN
  SUBGOAL_THEN `(u:A) = v` (LABEL_TAC "equal") THENL
   [MP_TAC(ISPECL
     [`complete_bipartite_edges (X:A->bool) Y`; `r:(A#A)->A#A`;
      `(u:A,v:A)`]
     GRAPH_FACE_SUCCESSOR_TAIL) THEN
    ASM_REWRITE_TAC[FST; SND];
    ALL_TAC] THEN
  USE_THEN "equal" SUBST_ALL_TAC THEN
  USE_THEN "dart" MP_TAC THEN
  REWRITE_TAC[COMPLETE_BIPARTITE_DART] THEN
  DISCH_THEN(DISJ_CASES_THEN
   (CONJUNCTS_THEN2 (LABEL_TAC "in_X") (LABEL_TAC "in_Y"))) THEN
  MP_TAC(MATCH_MP
   (SET_RULE
    `DISJOINT (X:A->bool) Y
     ==> ~((v:A) IN X /\ v IN Y)`)
   (ASSUME `DISJOINT (X:A->bool) Y`)) THEN
  ASM_REWRITE_TAC[]);;

let COMPLETE_BIPARTITE_FACE_SUCCESSOR_SQUARE_NO_FIXEDPOINT = prove
 (`!X Y r u v:A.
        X HAS_SIZE 3 /\
        Y HAS_SIZE 3 /\
        graph_rotation (complete_bipartite_edges X Y) r /\
        (u,v) IN graph_darts (complete_bipartite_edges X Y)
        ==> ~(ITER 2
              (graph_face_successor (complete_bipartite_edges X Y) r)
              (u,v) = (u,v))`,
  REPEAT GEN_TAC THEN INTRO_TAC "X_size Y_size rotation dart" THEN
  DISCH_THEN(LABEL_TAC "square") THEN
  SUBGOAL_THEN
   `outgoing_darts (complete_bipartite_edges X Y) (v:A) =
    {((v:A),(u:A))}`
  (LABEL_TAC "singleton") THENL
   [MP_TAC(ISPECL
     [`complete_bipartite_edges (X:A->bool) Y`; `r:(A#A)->A#A`;
      `(u:A,v:A)`]
     GRAPH_FACE_SUCCESSOR_SQUARE_FIXED) THEN
    ASM_REWRITE_TAC[SND; REVERSE_DART_PAIR];
    ALL_TAC] THEN
  USE_THEN "dart" MP_TAC THEN
  REWRITE_TAC[COMPLETE_BIPARTITE_DART] THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (CONJUNCTS_THEN2 (LABEL_TAC "u_X") (LABEL_TAC "v_Y"))
   (CONJUNCTS_THEN2 (LABEL_TAC "u_Y") (LABEL_TAC "v_X"))) THENL
   [SUBGOAL_THEN `?w:A. w IN X /\ ~(w = u)`
    (X_CHOOSE_THEN `w:A`
     (CONJUNCTS_THEN2 (LABEL_TAC "w_X")
      (LABEL_TAC "w_distinct"))) THENL
     [MATCH_MP_TAC HAS_SIZE_3_OTHER THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `((v:A),(w:A)) IN
      outgoing_darts
       (complete_bipartite_edges (X:A->bool) (Y:A->bool)) v`
    (LABEL_TAC "candidate") THENL
     [REWRITE_TAC
       [IN_OUTGOING_DARTS; FST; COMPLETE_BIPARTITE_DART] THEN
      ASM_REWRITE_TAC[];
      USE_THEN "candidate" MP_TAC THEN
      USE_THEN "singleton"
       (fun th -> REWRITE_TAC[th; IN_SING; PAIR_EQ]) THEN
      ASM_REWRITE_TAC[]];
    SUBGOAL_THEN `?w:A. w IN Y /\ ~(w = u)`
    (X_CHOOSE_THEN `w:A`
     (CONJUNCTS_THEN2 (LABEL_TAC "w_Y")
      (LABEL_TAC "w_distinct"))) THENL
     [MATCH_MP_TAC HAS_SIZE_3_OTHER THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `((v:A),(w:A)) IN
      outgoing_darts
       (complete_bipartite_edges (X:A->bool) (Y:A->bool)) v`
    (LABEL_TAC "candidate") THENL
     [REWRITE_TAC
       [IN_OUTGOING_DARTS; FST; COMPLETE_BIPARTITE_DART] THEN
      ASM_REWRITE_TAC[];
      USE_THEN "candidate" MP_TAC THEN
      USE_THEN "singleton"
       (fun th -> REWRITE_TAC[th; IN_SING; PAIR_EQ]) THEN
      ASM_REWRITE_TAC[]]]);;

