let COMPLETE_BIPARTITE_FACE_SUCCESSOR_SWITCHES_PARTS = prove
 (`!X Y r d:A#A.
        graph_rotation (complete_bipartite_edges X Y) r /\
        d IN graph_darts (complete_bipartite_edges X Y)
        ==> (FST d IN X /\
             FST(graph_face_successor
                  (complete_bipartite_edges X Y) r d) IN Y) \/
            (FST d IN Y /\
             FST(graph_face_successor
                  (complete_bipartite_edges X Y) r d) IN X)`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MAP_EVERY X_GEN_TAC
   [`X:A->bool`; `Y:A->bool`; `r:(A#A)->A#A`; `u:A`; `v:A`] THEN
  INTRO_TAC "rotation dart" THEN
  SUBGOAL_THEN
   `FST(graph_face_successor
        (complete_bipartite_edges (X:A->bool) Y)
        (r:(A#A)->A#A) (u:A,v:A)) = v`
  (LABEL_TAC "next_tail") THENL
   [MP_TAC(ISPECL
     [`complete_bipartite_edges (X:A->bool) Y`; `r:(A#A)->A#A`;
      `(u:A,v:A)`]
     GRAPH_FACE_SUCCESSOR_TAIL) THEN
    ASM_REWRITE_TAC[SND];
    ALL_TAC] THEN
  USE_THEN "dart" MP_TAC THEN
  REWRITE_TAC[COMPLETE_BIPARTITE_DART] THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (CONJUNCTS_THEN2 (LABEL_TAC "u_X") (LABEL_TAC "v_Y"))
   (CONJUNCTS_THEN2 (LABEL_TAC "u_Y") (LABEL_TAC "v_X"))) THENL
   [DISJ1_TAC THEN ASM_REWRITE_TAC[FST];
    DISJ2_TAC THEN ASM_REWRITE_TAC[FST]]);;

let COMPLETE_BIPARTITE_FACE_SUCCESSOR_CUBE_NO_FIXEDPOINT = prove
 (`!X Y r d:A#A.
        DISJOINT X Y /\
        graph_rotation (complete_bipartite_edges X Y) r /\
        d IN graph_darts (complete_bipartite_edges X Y)
        ==> ~(ITER 3
