  SUBGOAL_THEN
   `(d1:A#A) IN graph_darts (complete_bipartite_edges X Y)`
  (LABEL_TAC "d1_dart") THENL
   [EXPAND_TAC "d1" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_DART THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(d2:A#A) IN graph_darts (complete_bipartite_edges X Y)`
  (LABEL_TAC "d2_dart") THENL
   [EXPAND_TAC "d2" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_DART THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor
     (complete_bipartite_edges X Y) (r:(A#A)->A#A) d2 = d`
  (LABEL_TAC "return") THENL
   [ONCE_REWRITE_TAC
     [GSYM(ASSUME
       `graph_face_successor
         (complete_bipartite_edges (X:A->bool) Y)
         (r:(A#A)->A#A) d1 = d2`)] THEN
    ONCE_REWRITE_TAC
     [GSYM(ASSUME
       `graph_face_successor
         (complete_bipartite_edges (X:A->bool) Y)
         (r:(A#A)->A#A) d = d1`)] THEN
    USE_THEN "cube" MP_TAC THEN
    REWRITE_TAC
     [num_CONV `3`; num_CONV `2`; num_CONV `1`; ITER];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(FST(d:A#A) IN X /\ FST(d1:A#A) IN Y) \/
    (FST d IN Y /\ FST d1 IN X)`
  (LABEL_TAC "switch0") THENL
   [MP_TAC(ISPECL
     [`X:A->bool`; `Y:A->bool`; `r:(A#A)->A#A`; `d:A#A`]
     COMPLETE_BIPARTITE_FACE_SUCCESSOR_SWITCHES_PARTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(FST(d1:A#A) IN X /\ FST(d2:A#A) IN Y) \/
    (FST d1 IN Y /\ FST d2 IN X)`
  (LABEL_TAC "switch1") THENL
   [MP_TAC(ISPECL
     [`X:A->bool`; `Y:A->bool`; `r:(A#A)->A#A`; `d1:A#A`]
     COMPLETE_BIPARTITE_FACE_SUCCESSOR_SWITCHES_PARTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(FST(d2:A#A) IN X /\ FST(d:A#A) IN Y) \/
    (FST d2 IN Y /\ FST d IN X)`
  (LABEL_TAC "switch2") THENL
   [MP_TAC(ISPECL
     [`X:A->bool`; `Y:A->bool`; `r:(A#A)->A#A`; `d2:A#A`]
     COMPLETE_BIPARTITE_FACE_SUCCESSOR_SWITCHES_PARTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!z:A. ~(z IN X /\ z IN Y)`
  (LABEL_TAC "apart") THENL
   [MATCH_MP_TAC
     (SET_RULE
      `DISJOINT (X:A->bool) Y ==> !z. ~(z IN X /\ z IN Y)`) THEN
    USE_THEN "disjoint" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "switch0" MP_TAC THEN
  USE_THEN "switch1" MP_TAC THEN
  USE_THEN "switch2" MP_TAC THEN
  USE_THEN "apart" MP_TAC THEN
  POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[]);;

