          (complete_bipartite_edges (X:A->bool) (Y:A->bool))
          (r:(A#A)->A#A)) <=
    nsum (graph_faces (complete_bipartite_edges X Y) r) CARD`
  (LABEL_TAC "face_sum_lower") THENL
   [SUBGOAL_THEN
     `nsum
       (graph_faces
         (complete_bipartite_edges (X:A->bool) (Y:A->bool))
         (r:(A#A)->A#A))
       (\f:(A#A)->bool. 4) =
      CARD(graph_faces (complete_bipartite_edges X Y) r) * 4`
    (LABEL_TAC "constant_sum") THENL
     [MATCH_MP_TAC NSUM_CONST THEN
      USE_THEN "finite_faces" ACCEPT_TAC;
      ALL_TAC] THEN
    ONCE_REWRITE_TAC[MULT_SYM] THEN
    USE_THEN "constant_sum" (SUBST1_TAC o SYM) THEN
    USE_THEN "sum_lower" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(complete_bipartite_edges (X:A->bool) (Y:A->bool)) = 9`
  (LABEL_TAC "nine_edges") THENL
   [MP_TAC(ISPECL
     [`X:A->bool`; `Y:A->bool`] CARD_COMPLETE_BIPARTITE_EDGES) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(X:A->bool) UNION (Y:A->bool)`;
    `complete_bipartite_edges (X:A->bool) Y`;
    `r:(A#A)->A#A`]
   FACE_SUM_EQ_TWICE_EDGES) THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let COMPLETE_BIPARTITE_3_3_NOT_EULER_PLANAR_ROTATION = prove
 (`!X Y r:(A#A)->A#A.
        X HAS_SIZE 3 /\ Y HAS_SIZE 3 /\ DISJOINT X Y
        ==> ~euler_planar_rotation
              (X UNION Y) (complete_bipartite_edges X Y) r`,
  REPEAT GEN_TAC THEN INTRO_TAC "X_size Y_size disjoint" THEN
  DISCH_THEN(LABEL_TAC "euler") THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph rotation formula" THEN
  SUBGOAL_THEN `FINITE(X:A->bool) /\ CARD(X:A->bool) = 3`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_X")
   (LABEL_TAC "card_X")) THENL
   [USE_THEN "X_size" MP_TAC THEN REWRITE_TAC[HAS_SIZE];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(Y:A->bool) /\ CARD(Y:A->bool) = 3`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_Y")
   (LABEL_TAC "card_Y")) THENL
   [USE_THEN "Y_size" MP_TAC THEN REWRITE_TAC[HAS_SIZE];
    ALL_TAC] THEN
  SUBGOAL_THEN `(X:A->bool) INTER (Y:A->bool) = {}`
  (LABEL_TAC "intersection") THENL
   [USE_THEN "disjoint" MP_TAC THEN REWRITE_TAC[DISJOINT];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD((X:A->bool) UNION (Y:A->bool)) = 6`
  (LABEL_TAC "six_vertices") THENL
   [MP_TAC(ISPECL [`X:A->bool`; `Y:A->bool`] CARD_UNION) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(complete_bipartite_edges (X:A->bool) (Y:A->bool)) = 9`
  (LABEL_TAC "nine_edges") THENL
   [MP_TAC(ISPECL
     [`X:A->bool`; `Y:A->bool`] CARD_COMPLETE_BIPARTITE_EDGES) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(complete_bipartite_edges (X:A->bool) (Y:A->bool) = {})`
  (LABEL_TAC "edges_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "empty") THEN
    USE_THEN "empty" (fun th ->
      USE_THEN "nine_edges"
       (MP_TAC o REWRITE_RULE[th; CARD_CLAUSES])) THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD
     (graph_faces
       (complete_bipartite_edges (X:A->bool) (Y:A->bool))
       (r:(A#A)->A#A)) <= 4`
  (LABEL_TAC "few_faces") THENL
   [MATCH_MP_TAC COMPLETE_BIPARTITE_GRAPH_FACE_COUNT_LE_4 THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "formula" MP_TAC THEN
  REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let COMPLETE_BIPARTITE_3_3_NOT_EULER_PLANAR = prove
 (`!X Y:A->bool.
        X HAS_SIZE 3 /\ Y HAS_SIZE 3 /\ DISJOINT X Y
