   [USE_THEN "X_size" MP_TAC THEN REWRITE_TAC[HAS_SIZE];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(Y:A->bool) /\ CARD(Y:A->bool) = 3`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_Y")
   (LABEL_TAC "card_Y")) THENL
   [USE_THEN "Y_size" MP_TAC THEN REWRITE_TAC[HAS_SIZE];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((X:A->bool) = {})`
  (LABEL_TAC "X_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "empty") THEN
    USE_THEN "empty" (fun th ->
      USE_THEN "card_X"
       (MP_TAC o REWRITE_RULE[th; CARD_CLAUSES])) THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((Y:A->bool) = {})`
  (LABEL_TAC "Y_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "empty") THEN
    USE_THEN "empty" (fun th ->
      USE_THEN "card_Y"
       (MP_TAC o REWRITE_RULE[th; CARD_CLAUSES])) THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph
     ((X:A->bool) UNION (Y:A->bool))
     (complete_bipartite_edges (X:A->bool) (Y:A->bool))`
  (LABEL_TAC "connected") THENL
   [MATCH_MP_TAC COMPLETE_BIPARTITE_GRAPH_CONNECTED THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?u:A. u IN X`
  (X_CHOOSE_THEN `u:A` (LABEL_TAC "u_X")) THENL
   [USE_THEN "X_nonempty" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?r:(A#A)->A#A.
        euler_planar_rotation
         ((X:A->bool) UNION (Y:A->bool))
         (complete_bipartite_edges (X:A->bool) (Y:A->bool)) r`
