    ASM_REWRITE_TAC[IN_UNION];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`X:A->bool`; `Y:A->bool`; `r:(A#A)->A#A`]
   COMPLETE_BIPARTITE_3_3_NOT_EULER_PLANAR_ROTATION) THEN
  ASM_REWRITE_TAC[]);;

