    ASM_REWRITE_TAC[]]);;

let COMPLETE_GRAPH_DART = prove
 (`!V u v:A.
        (u,v) IN graph_darts (complete_graph_edges V) <=>
        u IN V /\ v IN V /\ ~(u = v)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[IN_GRAPH_DARTS; IN_COMPLETE_GRAPH_EDGES;
              INSERT_SUBSET; SING_SUBSET;
              HAS_SIZE] THEN
  SIMP_TAC[CARD_CLAUSES; FINITE_INSERT; FINITE_EMPTY;
           IN_INSERT; IN_SING; NOT_IN_EMPTY] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
  CONV_TAC NUM_REDUCE_CONV);;

let HAS_SIZE_5_OTHER_TWO = prove
 (`!S u v:A.
        S HAS_SIZE 5 /\ u IN S /\ v IN S /\ ~(u = v)
        ==> ?w. w IN S /\ ~(w = u) /\ ~(w = v)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "size u_member v_member distinct" THEN
  MP_TAC(SPEC
   `?w:A. w IN S /\ ~(w = u) /\ ~(w = v)`
   EXCLUDED_MIDDLE) THEN
  DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "other")
    (LABEL_TAC "no_other")) THENL
   [USE_THEN "other" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(S:A->bool) SUBSET {u,v}`
  (LABEL_TAC "subset") THENL
   [REWRITE_TAC[SUBSET; IN_INSERT; IN_SING] THEN
    X_GEN_TAC `w:A` THEN DISCH_THEN(LABEL_TAC "w_member") THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["no_other"; "w_member"] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(S:A->bool) /\ CARD(S:A->bool) = 5`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "size" MP_TAC THEN REWRITE_TAC[HAS_SIZE];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`S:A->bool`; `{u:A,v}:A->bool`] CARD_SUBSET) THEN
  ASM_REWRITE_TAC[FINITE_INSERT; FINITE_EMPTY] THEN
  MP_TAC(ISPECL [`u:A`; `v:A`] CARD_LE_2) THEN
  ARITH_TAC);;

let COMPLETE_GRAPH_FACE_SUCCESSOR_SQUARE_NO_FIXEDPOINT = prove
 (`!V r u v:A.
        V HAS_SIZE 5 /\
        graph_rotation (complete_graph_edges V) r /\
        (u,v) IN graph_darts (complete_graph_edges V)
        ==> ~(ITER 2
              (graph_face_successor (complete_graph_edges V) r)
              (u,v) = (u,v))`,
  REPEAT GEN_TAC THEN INTRO_TAC "size rotation dart" THEN
  DISCH_THEN(LABEL_TAC "square") THEN
  SUBGOAL_THEN
   `outgoing_darts (complete_graph_edges (V:A->bool)) (v:A) =
    {((v:A),(u:A))}`
  (LABEL_TAC "singleton") THENL
   [MP_TAC(ISPECL
     [`complete_graph_edges (V:A->bool)`; `r:(A#A)->A#A`;
      `(u:A,v:A)`]
     GRAPH_FACE_SUCCESSOR_SQUARE_FIXED) THEN
    ASM_REWRITE_TAC[SND; REVERSE_DART_PAIR];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(u:A) IN V /\ (v:A) IN V /\ ~(u = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
    (LABEL_TAC "distinct"))) THENL
   [USE_THEN "dart" MP_TAC THEN
    REWRITE_TAC[COMPLETE_GRAPH_DART];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?w:A. w IN V /\ ~(w = u) /\ ~(w = v)`
  (X_CHOOSE_THEN `w:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "w_vertex")
    (CONJUNCTS_THEN2 (LABEL_TAC "w_not_u")
     (LABEL_TAC "w_not_v")))) THENL
   [MATCH_MP_TAC HAS_SIZE_5_OTHER_TWO THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((v:A),(w:A)) IN
    outgoing_darts (complete_graph_edges (V:A->bool)) v`
  (LABEL_TAC "candidate") THENL
   [REWRITE_TAC[IN_OUTGOING_DARTS; FST; COMPLETE_GRAPH_DART] THEN
    ASM_REWRITE_TAC[];
    USE_THEN "candidate" MP_TAC THEN
    USE_THEN "singleton"
     (fun th -> REWRITE_TAC[th; IN_SING; PAIR_EQ]) THEN
    ASM_REWRITE_TAC[]]);;

let COMPLETE_GRAPH_FACE_SUCCESSOR_SQUARE_NO_FIXEDPOINT_DART = prove
