  SUBGOAL_THEN `~((d1:A#A) = d)` (LABEL_TAC "d1_d") THENL
   [EXPAND_TAC "d1" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `complete_graph_edges (V:A->bool)`;
      `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((d2:A#A) = d)` (LABEL_TAC "d2_d") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `r:(A#A)->A#A`; `d:A#A`]
     COMPLETE_GRAPH_FACE_SUCCESSOR_SQUARE_NO_FIXEDPOINT_DART) THEN
    ASM_REWRITE_TAC[num_CONV `2`; num_CONV `1`; ITER];
