  SUBGOAL_THEN `~((d2:A#A) = d1)` (LABEL_TAC "d2_d1") THENL
   [EXPAND_TAC "d2" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `complete_graph_edges (V:A->bool)`;
      `r:(A#A)->A#A`; `d1:A#A`]
     GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD {d2:A#A,d1,d} = 3`
