   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `complete_graph_edges (V:A->bool)`;
      `r:(A#A)->A#A`; `d:A#A`]
     FINITE_GRAPH_FACE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`{d2:A#A,d1,d}`;
    `graph_face (complete_graph_edges (V:A->bool))
                (r:(A#A)->A#A) (d:A#A)`]
   CARD_SUBSET) THEN
  ASM_REWRITE_TAC[]);;

