  SUBGOAL_THEN
   `CARD(complete_graph_edges (V:A->bool)) = 10`
  (LABEL_TAC "ten_edges") THENL
   [MP_TAC(ISPEC `V:A->bool` CARD_COMPLETE_GRAPH_EDGES) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[BINOM] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `complete_graph_edges (V:A->bool)`;
    `r:(A#A)->A#A`]
   FACE_SUM_EQ_TWICE_EDGES) THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let COMPLETE_GRAPH_5_NOT_EULER_PLANAR_ROTATION = prove
 (`!V r:(A#A)->A#A.
        V HAS_SIZE 5
        ==> ~euler_planar_rotation V (complete_graph_edges V) r`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "size") THEN
  DISCH_THEN(LABEL_TAC "euler") THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph rotation formula" THEN
  SUBGOAL_THEN `FINITE(V:A->bool) /\ CARD(V:A->bool) = 5`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_vertices")
   (LABEL_TAC "five_vertices")) THENL
   [USE_THEN "size" MP_TAC THEN REWRITE_TAC[HAS_SIZE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(complete_graph_edges (V:A->bool)) = 10`
  (LABEL_TAC "ten_edges") THENL
   [MP_TAC(ISPEC `V:A->bool` CARD_COMPLETE_GRAPH_EDGES) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[BINOM] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(complete_graph_edges (V:A->bool) = {})`
  (LABEL_TAC "edges_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "empty") THEN
    USE_THEN "empty" (fun th ->
      USE_THEN "ten_edges"
       (MP_TAC o REWRITE_RULE[th; CARD_CLAUSES])) THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD
     (graph_faces
       (complete_graph_edges (V:A->bool))
       (r:(A#A)->A#A)) <= 6`
  (LABEL_TAC "few_faces") THENL
   [MATCH_MP_TAC COMPLETE_GRAPH_5_FACE_COUNT_LE_6 THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "formula" MP_TAC THEN
  REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let COMPLETE_GRAPH_5_NOT_EULER_PLANAR = prove
 (`!V:A->bool.
        V HAS_SIZE 5
        ==> ~euler_planar_graph V (complete_graph_edges V)`,
  GEN_TAC THEN DISCH_THEN(LABEL_TAC "size") THEN
  DISCH_THEN(LABEL_TAC "euler") THEN
  SUBGOAL_THEN `FINITE(V:A->bool) /\ CARD(V:A->bool) = 5`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_vertices")
   (LABEL_TAC "five_vertices")) THENL
   [USE_THEN "size" MP_TAC THEN REWRITE_TAC[HAS_SIZE];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((V:A->bool) = {})`
  (LABEL_TAC "vertices_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "empty") THEN
    USE_THEN "empty" (fun th ->
      USE_THEN "five_vertices"
       (MP_TAC o REWRITE_RULE[th; CARD_CLAUSES])) THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `?u:A. u IN V`
  (X_CHOOSE_THEN `u:A` (LABEL_TAC "vertex")) THENL
   [USE_THEN "vertices_nonempty" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?r:(A#A)->A#A.
        euler_planar_rotation V (complete_graph_edges V) r`
  (X_CHOOSE_THEN `r:(A#A)->A#A` (LABEL_TAC "rotation")) THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `complete_graph_edges (V:A->bool)`; `u:A`]
     EULER_PLANAR_GRAPH_CONNECTED) THEN
    ASM_REWRITE_TAC[COMPLETE_GRAPH_CONNECTED];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `r:(A#A)->A#A`]
   COMPLETE_GRAPH_5_NOT_EULER_PLANAR_ROTATION) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The connected simple-graph edge bound from an Euler-planar rotation.      *)
(* ------------------------------------------------------------------------- *)

let RTC_STAYS_IN_SINGLE_EDGE_ENDPOINTS = prove
 (`!E:(A->bool)->bool. !u v:A.
        outgoing_darts E u = {(u,v)} /\
        outgoing_darts E v = {(v,u)}
        ==> !x y:A.
              RTC (\x y. {x,y} IN E) x y
              ==> (x IN {u,v} ==> y IN {u,v})`,
  REPEAT GEN_TAC THEN INTRO_TAC "outgoing_u outgoing_v" THEN
  MATCH_MP_TAC RTC_INDUCT THEN REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    DISCH_THEN(LABEL_TAC "edge") THEN
    REWRITE_TAC[IN_INSERT; IN_SING] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "x_u")
      (LABEL_TAC "x_v")) THENL
     [SUBGOAL_THEN `(x:A,y:A) IN outgoing_darts E u`
      (LABEL_TAC "outgoing") THENL
       [REWRITE_TAC[IN_OUTGOING_DARTS; IN_GRAPH_DARTS; FST] THEN
        CONJ_TAC THENL
         [USE_THEN "edge" (ACCEPT_TAC o BETA_RULE);
          USE_THEN "x_u" ACCEPT_TAC];
        USE_THEN "outgoing" MP_TAC THEN
        USE_THEN "outgoing_u"
         (fun th -> REWRITE_TAC[th; IN_SING; PAIR_EQ]) THEN
        ASM_REWRITE_TAC[IN_INSERT; IN_SING] THEN MESON_TAC[]];
      SUBGOAL_THEN `(x:A,y:A) IN outgoing_darts E v`
      (LABEL_TAC "outgoing") THENL
       [REWRITE_TAC[IN_OUTGOING_DARTS; IN_GRAPH_DARTS; FST] THEN
        CONJ_TAC THENL
         [USE_THEN "edge" (ACCEPT_TAC o BETA_RULE);
          USE_THEN "x_v" ACCEPT_TAC];
        USE_THEN "outgoing" MP_TAC THEN
        USE_THEN "outgoing_v"
         (fun th -> REWRITE_TAC[th; IN_SING; PAIR_EQ]) THEN
        ASM_REWRITE_TAC[IN_INSERT; IN_SING] THEN MESON_TAC[]]];
    REWRITE_TAC[];
    MESON_TAC[]]);;

let GRAPH_FACE_SUCCESSOR_SQUARE_NO_FIXEDPOINT_CONNECTED = prove
 (`!V E r u v:A.
        finite_simple_graph V E /\
        connected_graph V E /\
        graph_rotation E r /\
        3 <= CARD V /\
        (u,v) IN graph_darts E
        ==> ~(ITER 2 (graph_face_successor E r) (u,v) = (u,v))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph connected rotation vertices_large dart" THEN
  DISCH_THEN(LABEL_TAC "square") THEN
  ABBREV_TAC
   `d1 = graph_face_successor E (r:(A#A)->A#A) (u:A,v:A)` THEN
  SUBGOAL_THEN `(d1:A#A) IN graph_darts E`
  (LABEL_TAC "d1_dart") THENL
   [EXPAND_TAC "d1" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_DART THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A) d1 = (u:A,v:A)`
  (LABEL_TAC "return") THENL
   [USE_THEN "square" MP_TAC THEN
    EXPAND_TAC "d1" THEN
    REWRITE_TAC[num_CONV `2`; num_CONV `1`; ITER];
    ALL_TAC] THEN
  SUBGOAL_THEN `FST(d1:A#A) = v` (LABEL_TAC "d1_tail") THENL
   [EXPAND_TAC "d1" THEN
    MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `(u:A,v:A)`]
     GRAPH_FACE_SUCCESSOR_TAIL) THEN
    ASM_REWRITE_TAC[FST; SND] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `SND(d1:A#A) = u` (LABEL_TAC "d1_head") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d1:A#A`]
     GRAPH_FACE_SUCCESSOR_TAIL) THEN
    ASM_REWRITE_TAC[FST; SND] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(d1:A#A) = (v:A,u:A)` (LABEL_TAC "d1_reverse") THENL
   [MP_TAC(ISPEC `d1:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A`
     (X_CHOOSE_THEN `b:A` SUBST_ALL_TAC)) THEN
    ASM_MESON_TAC[FST; SND; PAIR_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `outgoing_darts E (v:A) = {(v:A,u:A)}`
  (LABEL_TAC "outgoing_v") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `(u:A,v:A)`]
     GRAPH_FACE_SUCCESSOR_SQUARE_FIXED) THEN
    ASM_REWRITE_TAC[SND; REVERSE_DART_PAIR];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `ITER 2 (graph_face_successor E (r:(A#A)->A#A)) d1 = d1`
  (LABEL_TAC "d1_square") THENL
   [REWRITE_TAC[num_CONV `2`; num_CONV `1`; ITER] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `outgoing_darts E (u:A) = {(u:A,v:A)}`
  (LABEL_TAC "outgoing_u") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d1:A#A`]
     GRAPH_FACE_SUCCESSOR_SQUARE_FIXED) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "d1_reverse" SUBST1_TAC THEN
    REWRITE_TAC[SND; REVERSE_DART_PAIR];
    ALL_TAC] THEN
  SUBGOAL_THEN `u IN V /\ v IN V /\ ~(u:A = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
    (LABEL_TAC "distinct"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(V:A->bool) SUBSET {u,v}` (LABEL_TAC "vertices_subset") THENL
   [REWRITE_TAC[SUBSET] THEN X_GEN_TAC `w:A` THEN
    DISCH_THEN(LABEL_TAC "w_vertex") THEN
    MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `u:A`; `v:A`]
     RTC_STAYS_IN_SINGLE_EDGE_ENDPOINTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPECL [`u:A`; `w:A`]) THEN
    ANTS_TAC THENL
     [USE_THEN "connected" MP_TAC THEN
      REWRITE_TAC[connected_graph] THEN
      DISCH_THEN(MP_TAC o SPECL [`u:A`; `w:A`]) THEN
      ASM_REWRITE_TAC[graph_reachable];
      REWRITE_TAC[IN_INSERT]];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(V:A->bool) <= CARD({u:A,v}:A->bool)`
  (LABEL_TAC "card_subset") THENL
   [MATCH_MP_TAC CARD_SUBSET THEN
    ASM_REWRITE_TAC[FINITE_INSERT; FINITE_EMPTY];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`u:A`; `v:A`] CARD_LE_2) THEN
  ASM_ARITH_TAC);;

let GRAPH_FACE_SUCCESSOR_SQUARE_NO_FIXEDPOINT_CONNECTED_DART = prove
 (`!V E r d:A#A.
        finite_simple_graph V E /\
        connected_graph V E /\
        graph_rotation E r /\
        3 <= CARD V /\
        d IN graph_darts E
        ==> ~(ITER 2 (graph_face_successor E r) d = d)`,
  REWRITE_TAC[FORALL_PAIR_THM] THEN
  MATCH_ACCEPT_TAC GRAPH_FACE_SUCCESSOR_SQUARE_NO_FIXEDPOINT_CONNECTED);;

let CONNECTED_SIMPLE_GRAPH_FACE_CARD_AT_LEAST_3 = prove
 (`!V E r d:A#A.
        finite_simple_graph V E /\
        connected_graph V E /\
        graph_rotation E r /\
        3 <= CARD V /\
        d IN graph_darts E
        ==> 3 <= CARD(graph_face E r d)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph connected rotation vertices_large dart" THEN
  ABBREV_TAC `d1 = graph_face_successor E (r:(A#A)->A#A) d` THEN
  ABBREV_TAC `d2 = graph_face_successor E (r:(A#A)->A#A) d1` THEN
  SUBGOAL_THEN `(d1:A#A) IN graph_darts E`
  (LABEL_TAC "d1_dart") THENL
   [EXPAND_TAC "d1" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_DART THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(d2:A#A) IN graph_darts E`
  (LABEL_TAC "d2_dart") THENL
   [EXPAND_TAC "d2" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_DART THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((d1:A#A) = d)` (LABEL_TAC "d1_d") THENL
   [EXPAND_TAC "d1" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((d2:A#A) = d)` (LABEL_TAC "d2_d") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_FACE_SUCCESSOR_SQUARE_NO_FIXEDPOINT_CONNECTED_DART) THEN
    ASM_REWRITE_TAC[num_CONV `2`; num_CONV `1`; ITER];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((d2:A#A) = d1)` (LABEL_TAC "d2_d1") THENL
   [EXPAND_TAC "d2" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `r:(A#A)->A#A`; `d1:A#A`]
     GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD {d2:A#A,d1,d} = 3`
  (LABEL_TAC "three") THENL
   [MATCH_MP_TAC CARD_TRIPLE_EQ_3 THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{d2:A#A,d1,d} SUBSET graph_face E r d`
  (LABEL_TAC "subset") THENL
   [REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_GRAPH_FACE] THEN
    CONJ_TAC THENL
     [EXISTS_TAC `2` THEN
      ASM_REWRITE_TAC[num_CONV `2`; num_CONV `1`; ITER];
      CONJ_TAC THENL
       [EXISTS_TAC `1` THEN ASM_REWRITE_TAC[ITER_1];
        EXISTS_TAC `0` THEN REWRITE_TAC[ITER]]];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(graph_face E (r:(A#A)->A#A) d)`
  (LABEL_TAC "finite_face") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `r:(A#A)->A#A`; `d:A#A`]
     FINITE_GRAPH_FACE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`{d2:A#A,d1,d}`;
    `graph_face (E:(A->bool)->bool) (r:(A#A)->A#A) d`]
   CARD_SUBSET) THEN
  ASM_REWRITE_TAC[]);;

let CONNECTED_SIMPLE_GRAPH_FACE_SUM_LOWER_BOUND = prove
 (`!V E r:(A#A)->A#A.
        finite_simple_graph V E /\
        connected_graph V E /\
        graph_rotation E r /\
        3 <= CARD V
        ==> 3 * CARD(graph_faces E r) <= 2 * CARD E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph connected rotation vertices_large" THEN
  SUBGOAL_THEN `FINITE(graph_faces E (r:(A#A)->A#A))`
  (LABEL_TAC "finite_faces") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
     FINITE_GRAPH_FACES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!f:(A#A)->bool.
        f IN graph_faces E r
        ==> 3 <= CARD f`
  (LABEL_TAC "large_faces") THENL
   [X_GEN_TAC `f:(A#A)->bool` THEN
    REWRITE_TAC[IN_GRAPH_FACES] THEN
    INTRO_TAC "@d. dart face" THEN
    USE_THEN "face" SUBST1_TAC THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `r:(A#A)->A#A`; `d:A#A`]
     CONNECTED_SIMPLE_GRAPH_FACE_CARD_AT_LEAST_3) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `nsum (graph_faces E r) (\f:(A#A)->bool. 3) <=
    nsum (graph_faces E r) CARD`
  (LABEL_TAC "sum_lower") THENL
   [MATCH_MP_TAC NSUM_LE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `3 * CARD(graph_faces E (r:(A#A)->A#A)) <=
    nsum (graph_faces E r) CARD`
  (LABEL_TAC "face_sum_lower") THENL
   [SUBGOAL_THEN
     `nsum (graph_faces E r) (\f:(A#A)->bool. 3) =
      CARD(graph_faces E r) * 3`
    (LABEL_TAC "constant_sum") THENL
     [MATCH_MP_TAC NSUM_CONST THEN
      USE_THEN "finite_faces" ACCEPT_TAC;
      ALL_TAC] THEN
    ONCE_REWRITE_TAC[MULT_SYM] THEN
    USE_THEN "constant_sum" (SUBST1_TAC o SYM) THEN
    USE_THEN "sum_lower" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
   FACE_SUM_EQ_TWICE_EDGES) THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let EULER_PLANAR_ROTATION_CONNECTED_EDGE_BOUND = prove
 (`!V E r:(A#A)->A#A.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        3 <= CARD V
        ==> CARD E + 6 <= 3 * CARD V`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler connected vertices_large" THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph rotation formula" THEN
  SUBGOAL_THEN `~(V:A->bool = {})` (LABEL_TAC "vertices_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "vertices_empty") THEN
    USE_THEN "vertices_empty" (fun empty_th ->
      USE_THEN "vertices_large"
       (MP_TAC o REWRITE_RULE[empty_th; CARD_CLAUSES])) THEN
    ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(E:(A->bool)->bool = {})`
  (LABEL_TAC "edges_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "edges_empty") THEN
    USE_THEN "formula" MP_TAC THEN
    REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
    ASM_REWRITE_TAC[CARD_SING; CARD_CLAUSES] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `3 * CARD(graph_faces E (r:(A#A)->A#A)) <= 2 * CARD E`
  (LABEL_TAC "face_bound") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
     CONNECTED_SIMPLE_GRAPH_FACE_SUM_LOWER_BOUND) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "formula" MP_TAC THEN
  REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let EULER_PLANAR_GRAPH_CONNECTED_EDGE_BOUND = prove
 (`!V E.
        euler_planar_graph (V:A->bool) E /\
        connected_graph V E /\
        3 <= CARD V
        ==> CARD E + 6 <= 3 * CARD V`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler connected vertices_large" THEN
  SUBGOAL_THEN `~(V:A->bool = {})` (LABEL_TAC "vertices_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "vertices_empty") THEN
    USE_THEN "vertices_empty" (fun empty_th ->
      USE_THEN "vertices_large"
       (MP_TAC o REWRITE_RULE[empty_th; CARD_CLAUSES])) THEN
    ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?u:A. u IN V`
  (X_CHOOSE_THEN `u:A` (LABEL_TAC "vertex")) THENL
   [USE_THEN "vertices_nonempty" MP_TAC THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
   EULER_PLANAR_GRAPH_CONNECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:(A#A)->A#A` (LABEL_TAC "rotation")) THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
   EULER_PLANAR_ROTATION_CONNECTED_EDGE_BOUND) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Combinatorial descent for maximal Euler-planar rotations.                 *)
(* ------------------------------------------------------------------------- *)

let PAIRWISE_ADJACENT_COMPLETE_GRAPH_EDGES_SUBSET = prove
 (`!W:A->bool. !E:(A->bool)->bool.
        (!u v. u IN W /\ v IN W /\ ~(u = v) ==> {u,v} IN E)
        ==> complete_graph_edges W SUBSET E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "adjacent") THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `e:A->bool` THEN
  REWRITE_TAC[IN_COMPLETE_GRAPH_EDGES] THEN
  INTRO_TAC "endpoints size" THEN
  USE_THEN "size" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE_CONV `(e:A->bool) HAS_SIZE 2`] THEN
  INTRO_TAC "@u v. distinct pair" THEN
  USE_THEN "pair" SUBST1_TAC THEN
  USE_THEN "adjacent" MATCH_MP_TAC THEN
  USE_THEN "endpoints" MP_TAC THEN
  ASM SET_TAC[]);;

let COMPLETE_GRAPH_EDGES_SUBSET_INDUCED = prove
 (`!W:A->bool. !E:(A->bool)->bool.
        complete_graph_edges W SUBSET E
        ==> complete_graph_edges W SUBSET induced_subgraph_edges E W`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES;
              IN_COMPLETE_GRAPH_EDGES] THEN
  MESON_TAC[]);;

let GRAPH_FACE_SUCCESSOR_IMAGE = prove
 (`!V E r d:A#A.
        finite_simple_graph (V:A->bool) E /\
        graph_rotation E r /\
        d IN graph_darts E
        ==> IMAGE (graph_face_successor E r) (graph_face E r d) =
            graph_face E r d`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation dart" THEN
  MP_TAC(ISPECL
   [`graph_face_successor (E:(A->bool)->bool) (r:(A#A)->A#A)`;
    `graph_darts E:A#A->bool`; `d:A#A`]
   PERMUTATION_ORBIT_IMAGE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      USE_THEN "graph" ACCEPT_TAC;
      MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
      USE_THEN "rotation" ACCEPT_TAC;
      USE_THEN "dart" ACCEPT_TAC];
    REWRITE_TAC[GSYM GRAPH_FACE_AS_PERMUTATION_ORBIT]]);;

let GRAPH_ROTATION_FACE_TAILS_EQ_VERTICES = prove
 (`!V E r d:A#A.
        finite_simple_graph (V:A->bool) E /\
