        d IN graph_darts E
        ==> IMAGE FST (graph_face E r d) =
            graph_rotation_face_vertices E r d`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation dart" THEN
  SUBGOAL_THEN
   `IMAGE (graph_face_successor E (r:(A#A)->A#A))
      (graph_face E r d) = graph_face E r d`
  (LABEL_TAC "face_image") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_FACE_SUCCESSOR_IMAGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[graph_rotation_face_vertices] THEN
  TRANS_TAC EQ_TRANS
   `IMAGE FST
     (IMAGE (graph_face_successor E (r:(A#A)->A#A))
       (graph_face E r d))` THEN
  CONJ_TAC THENL
   [AP_TERM_TAC THEN USE_THEN "face_image" (ACCEPT_TAC o SYM);
    REWRITE_TAC[GSYM IMAGE_o] THEN
    MATCH_MP_TAC IMAGE_EQ THEN
    X_GEN_TAC `a:A#A` THEN DISCH_THEN(LABEL_TAC "face") THEN
    REWRITE_TAC[o_THM] THEN
    SUBGOAL_THEN `(a:A#A) IN graph_darts E` (LABEL_TAC "a_dart") THENL
     [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (MATCH_MP
        (ISPECL [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
         GRAPH_FACE_SUBSET_DARTS)
        (CONJ (ASSUME `graph_rotation E (r:(A#A)->A#A)`)
              (ASSUME `(d:A#A) IN graph_darts E`)))) THEN
      USE_THEN "face" ACCEPT_TAC;
      MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_TAIL THEN
      ASM_REWRITE_TAC[]]]);;

let MAXIMAL_EULER_PLANAR_ROTATION_FACE_VERTICES_CARD_LE_4 = prove
 (`!V E r d:A#A.
        euler_planar_rotation (V:A->bool) E r /\
        connected_graph V E /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\
             E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s) /\
        d IN graph_darts E
        ==> CARD(graph_rotation_face_vertices E r d) <= 4`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "euler connected maximal dart" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `graph_rotation E (r:(A#A)->A#A)`
  (LABEL_TAC "rotation") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(graph_rotation_face_vertices E (r:(A#A)->A#A) d)`
  (LABEL_TAC "finite_face_vertices") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     FINITE_GRAPH_ROTATION_FACE_VERTICES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_rotation_face_vertices E (r:(A#A)->A#A) d SUBSET V`
  (LABEL_TAC "face_vertices_subset") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_ROTATION_FACE_VERTICES_SUBSET) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u v.
      u IN graph_rotation_face_vertices E (r:(A#A)->A#A) d /\
      v IN graph_rotation_face_vertices E r d /\
      ~(u = v)
      ==> {u,v} IN E`
  (LABEL_TAC "face_clique") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     MAXIMAL_EULER_PLANAR_ROTATION_FACE_VERTICES_CLIQUE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC
   `CARD(graph_rotation_face_vertices E (r:(A#A)->A#A) d) <= 4` THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(LABEL_TAC "too_many") THEN
  MP_TAC(SPEC `5`
   (MATCH_MP
    (ISPEC `graph_rotation_face_vertices
              E (r:(A#A)->A#A) d` CHOOSE_SUBSET)
    (ASSUME
     `FINITE(graph_rotation_face_vertices
       E (r:(A#A)->A#A) d)`))) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    INTRO_TAC "@W. W_face size"] THEN
  SUBGOAL_THEN `(W:A->bool) SUBSET V`
  (LABEL_TAC "W_vertices") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `graph_rotation_face_vertices E (r:(A#A)->A#A) d` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `complete_graph_edges (W:A->bool) SUBSET E`
  (LABEL_TAC "complete_edges") THENL
   [MATCH_MP_TAC PAIRWISE_ADJACENT_COMPLETE_GRAPH_EDGES_SUBSET THEN
    MAP_EVERY X_GEN_TAC [`u:A`; `v:A`] THEN
    INTRO_TAC "u_W v_W distinct" THEN
    USE_THEN "face_clique" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
    USE_THEN "W_face" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `complete_graph_edges W SUBSET
    induced_subgraph_edges E (W:A->bool)`
  (LABEL_TAC "induced_complete") THENL
   [MATCH_MP_TAC(ISPECL
     [`W:A->bool`; `E:(A->bool)->bool`]
     COMPLETE_GRAPH_EDGES_SUBSET_INDUCED) THEN
    USE_THEN "complete_edges" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((W:A->bool) = {})`
  (LABEL_TAC "W_nonempty") THENL
   [USE_THEN "size" MP_TAC THEN
    REWRITE_TAC[HAS_SIZE] THEN
    INTRO_TAC "W_finite W_card" THEN
    DISCH_THEN(LABEL_TAC "W_empty") THEN
    USE_THEN "W_empty" (fun empty_th ->
      USE_THEN "W_card"
       (MP_TAC o REWRITE_RULE[empty_th; CARD_CLAUSES])) THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `W:A->bool`; `complete_graph_edges W:(A->bool)->bool`]
   EULER_PLANAR_ROTATION_CONNECTED_SUBGRAPH) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "euler" ACCEPT_TAC;
      USE_THEN "connected" ACCEPT_TAC;
      USE_THEN "W_vertices" ACCEPT_TAC;
      USE_THEN "W_nonempty" ACCEPT_TAC;
      USE_THEN "induced_complete" ACCEPT_TAC;
      MATCH_ACCEPT_TAC COMPLETE_GRAPH_CONNECTED];
    DISCH_THEN(X_CHOOSE_THEN `s:(A#A)->A#A`
     (LABEL_TAC "complete_euler"))] THEN
  MP_TAC(ISPECL [`W:A->bool`; `s:(A#A)->A#A`]
   COMPLETE_GRAPH_5_NOT_EULER_PLANAR_ROTATION) THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_FACE_SUBSET_COMPLETE_FACE_DARTS = prove
 (`!V E r d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        d IN graph_darts E
        ==> graph_face E r d SUBSET
            graph_darts
              (complete_graph_edges
                (graph_rotation_face_vertices E r d))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation dart" THEN
  REWRITE_TAC[SUBSET; FORALL_PAIR_THM; COMPLETE_GRAPH_DART] THEN
  MAP_EVERY X_GEN_TAC [`u:A`; `v:A`] THEN
  DISCH_THEN(LABEL_TAC "face") THEN
  SUBGOAL_THEN `(u:A,v) IN graph_darts E`
  (LABEL_TAC "edge_dart") THENL
   [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
     (MATCH_MP
      (ISPECL [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `(d:A#A)`]
       GRAPH_FACE_SUBSET_DARTS)
      (CONJ (ASSUME `graph_rotation E (r:(A#A)->A#A)`)
            (ASSUME `(d:A#A) IN graph_darts E`)))) THEN
    USE_THEN "face" ACCEPT_TAC;
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_ROTATION_FACE_TAILS_EQ_VERTICES) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th; IN_IMAGE]) THEN
    EXISTS_TAC `(u:A,v:A)` THEN ASM_REWRITE_TAC[FST];
    REWRITE_TAC[graph_rotation_face_vertices; IN_IMAGE] THEN
    EXISTS_TAC `(u:A,v:A)` THEN ASM_REWRITE_TAC[SND];
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]]);;

let CARD_COMPLETE_GRAPH_DARTS_LE_2 = prove
 (`!W:A->bool.
        FINITE W /\ CARD W <= 2
        ==> CARD(graph_darts (complete_graph_edges W)) <= 2`,
  GEN_TAC THEN INTRO_TAC "finite small" THEN
  SUBGOAL_THEN
   `finite_simple_graph
      (W:A->bool) (complete_graph_edges W)`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_COMPLETE_GRAPH THEN
    USE_THEN "finite" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`W:A->bool`; `complete_graph_edges W:(A->bool)->bool`]
   CARD_GRAPH_DARTS) THEN
  ANTS_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "darts")] THEN
  MP_TAC(ISPEC `W:A->bool` CARD_COMPLETE_GRAPH_EDGES) THEN
  ANTS_TAC THENL
   [USE_THEN "finite" ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "edges")] THEN
  USE_THEN "darts" SUBST1_TAC THEN
  USE_THEN "edges" SUBST1_TAC THEN
  SUBGOAL_THEN
   `CARD(W:A->bool) = 0 \/
    CARD W = 1 \/
    CARD W = 2`
  MP_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST1_TAC) THEN
    REWRITE_TAC[BINOM] THEN CONV_TAC NUM_REDUCE_CONV]);;

