let PERMUTATION_DELETE_TWO_PRESERVES_OLD_ORBIT = prove
 (`!f:A->A. !s x y a b.
        FINITE s /\
        f permutes s /\
        x IN s /\
        y IN s /\
        ~(x = y) /\
        a IN s DELETE x DELETE y /\
        b IN s DELETE x DELETE y /\
        b IN permutation_orbit f a
        ==> b IN
            permutation_orbit (permutation_delete_two f x y) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite permutation x_member y_member distinct a_member b_member \
    b_orbit" THEN
  SUBGOAL_THEN
   `!z:A. z IN s
          ==> permutation_orbit f (f z) = permutation_orbit f z`
  (LABEL_TAC "orbit_invariant") THENL
   [X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_member") THEN
    MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `z:A`; `(f:A->A) z`]
     PERMUTATION_ORBIT_EQ) THEN
    ASM_REWRITE_TAC[] THEN
    MESON_TAC[PERMUTATION_ORBIT_SUCCESSOR;
              PERMUTATION_ORBIT_REFL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!c d:A.
        c IN s /\
        d IN s /\
        permutation_orbit f c = permutation_orbit f d
        ==> ?n. ITER n f c = d`
  (LABEL_TAC "orbit_transitive") THENL
   [MAP_EVERY X_GEN_TAC [`c:A`; `e:A`] THEN
    INTRO_TAC "c_member e_member same_orbit" THEN
    REWRITE_TAC[GSYM IN_PERMUTATION_ORBIT] THEN
    USE_THEN "same_orbit" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL;
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:A) IN s /\ (b:A) IN s`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_in_s") (LABEL_TAC "b_in_s")) THENL
   [CONJ_TAC THENL
     [USE_THEN "a_member" MP_TAC;
      USE_THEN "b_member" MP_TAC] THEN
    REWRITE_TAC[IN_DELETE] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit f (a:A) = permutation_orbit f b`
  (LABEL_TAC "same_old_orbit") THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `b:A`]
     PERMUTATION_ORBIT_EQ) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(ACCEPT_TAC o SYM);
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`f:A->A`; `s:A->bool`; `x:A`; `y:A`;
    `\z:A. permutation_orbit f z`]
   PERMUTATION_DELETE_TWO_TRANSITIVE_KEY) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(MP_TAC o SPECL [`a:A`; `b:A`]) THEN
    ASM_REWRITE_TAC[GSYM IN_PERMUTATION_ORBIT]]);;

let PERMUTATION_SWAP_COALESCES_DISTINCT_ORBITS = prove
 (`!f:A->A. !s x y a b.
        FINITE s /\
        f permutes s /\
        x IN s /\
        y IN s /\
        a IN s /\
        b IN s /\
        ~(permutation_orbit f x = permutation_orbit f y) /\
        (a IN permutation_orbit f x \/
         a IN permutation_orbit f y) /\
        (b IN permutation_orbit f x \/
         b IN permutation_orbit f y)
        ==> b IN permutation_orbit (swap(x,y) o f) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite permutation x_member y_member a_member b_member \
    distinct_orbits a_affected b_affected" THEN
  ABBREV_TAC `g:A->A = swap((x:A),(y:A)) o (f:A->A)` THEN
  SUBGOAL_THEN `(g:A->A) permutes s`
  (LABEL_TAC "new_permutation") THENL
   [EXPAND_TAC "g" THEN
    MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit (g:A->A) y = permutation_orbit g x`
  (LABEL_TAC "merged_anchors") THENL
   [EXPAND_TAC "g" THEN
    MATCH_MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`; `y:A`]
     PERMUTATION_SWAP_MERGED_ORBITS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A.
        z IN s /\
        (z IN permutation_orbit f x \/
         z IN permutation_orbit f y)
        ==> permutation_orbit g z = permutation_orbit g x`
  (LABEL_TAC "affected_orbit") THENL
   [X_GEN_TAC `z:A` THEN INTRO_TAC "z_member z_affected" THEN
    MP_TAC(ISPECL
     [`f:A->A`; `s:A->bool`; `x:A`; `y:A`; `z:A`]
     PERMUTATION_SWAP_AFFECTED_ORBIT_HITS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(DISJ_CASES_THEN2
      (LABEL_TAC "hits_x") (LABEL_TAC "hits_y")) THENL
     [MP_TAC(ISPECL [`g:A->A`; `s:A->bool`; `z:A`; `x:A`]
       PERMUTATION_ORBIT_EQ) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[];
      MP_TAC(ISPECL [`g:A->A`; `s:A->bool`; `z:A`; `y:A`]
       PERMUTATION_ORBIT_EQ) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit (g:A->A) a = permutation_orbit g x`
  (LABEL_TAC "a_merged") THENL
   [USE_THEN "affected_orbit" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit (g:A->A) b = permutation_orbit g x`
  (LABEL_TAC "b_merged") THENL
   [USE_THEN "affected_orbit" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "a_merged" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "b_merged" (fun th -> REWRITE_TAC[GSYM th]) THEN
  MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL);;

let PERMUTATION_DELETE_TWO_AFTER_SWAP = prove
 (`!f:A->A. !s x y z.
        f permutes s /\
        x IN s /\
        y IN s /\
        ~(x = y) /\
        ~(f x = x) /\
        ~(f y = y) /\
        z IN s DELETE x DELETE y
        ==> permutation_delete_two (swap(x,y) o f) x y z =
            if f z = x then f y
            else if f z = y then f x
            else f z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "permutation x_member y_member distinct x_nonfixed y_nonfixed \
    z_member" THEN
  SUBGOAL_THEN `(z:A) IN s /\ ~(z = x) /\ ~(z = y)`
  (CONJUNCTS_THEN2 (LABEL_TAC "z_in_s")
    (CONJUNCTS_THEN2 (LABEL_TAC "z_not_x") (LABEL_TAC "z_not_y"))) THENL
   [USE_THEN "z_member" MP_TAC THEN
    REWRITE_TAC[IN_DELETE] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_delete (swap((x:A),(y:A)) o (f:A->A)) x z =
    if (swap(x,y) o f) z = x then (swap(x,y) o f) x
    else (swap(x,y) o f) z`
  (LABEL_TAC "p_z") THENL
   [MATCH_MP_TAC(ISPECL
     [`swap((x:A),(y:A)) o (f:A->A)`;
      `s:A->bool`; `x:A`; `z:A`]
     PERMUTATION_DELETE_APPLY_IN) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_delete (swap((x:A),(y:A)) o (f:A->A)) x y =
    if (swap(x,y) o f) y = x then (swap(x,y) o f) x
    else (swap(x,y) o f) y`
  (LABEL_TAC "p_y") THENL
   [MATCH_MP_TAC(ISPECL
     [`swap((x:A),(y:A)) o (f:A->A)`;
      `s:A->bool`; `x:A`; `y:A`]
     PERMUTATION_DELETE_APPLY_IN) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_delete
      (permutation_delete (swap((x:A),(y:A)) o (f:A->A)) x) y z =
    if permutation_delete (swap(x,y) o f) x z = y then
      permutation_delete (swap(x,y) o f) x y
    else permutation_delete (swap(x,y) o f) x z`
  (LABEL_TAC "outer") THENL
   [MATCH_MP_TAC(ISPECL
     [`permutation_delete
        (swap((x:A),(y:A)) o (f:A->A)) x`;
      `s DELETE (x:A)`; `y:A`; `z:A`]
     PERMUTATION_DELETE_APPLY_IN) THEN
    ASM_REWRITE_TAC[IN_DELETE] THEN
    MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN CONJ_TAC THENL
     [MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN ASM_REWRITE_TAC[];
      USE_THEN "x_member" ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[permutation_delete_two] THEN
  USE_THEN "outer" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "p_z" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "p_y" (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[o_THM] THEN
  ASM_CASES_TAC `(f:A->A) z = x` THENL
   [FIRST_X_ASSUM(LABEL_TAC "fz_x") THEN
    SUBGOAL_THEN `~((f:A->A) y = x)` (LABEL_TAC "fy_not_x") THENL
     [DISCH_THEN(LABEL_TAC "fy_x") THEN
      MP_TAC(MATCH_MP
       (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
       (ASSUME `(f:A->A) permutes s`)) THEN
      DISCH_THEN(MP_TAC o SPECL [`y:A`; `z:A`]) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[swap];
    ASM_CASES_TAC `(f:A->A) z = y` THENL
     [FIRST_X_ASSUM(LABEL_TAC "fz_y") THEN
      SUBGOAL_THEN `~((f:A->A) x = y)` (LABEL_TAC "fx_not_y") THENL
       [DISCH_THEN(LABEL_TAC "fx_y") THEN
        MP_TAC(MATCH_MP
         (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
         (ASSUME `(f:A->A) permutes s`)) THEN
        DISCH_THEN(MP_TAC o SPECL [`x:A`; `z:A`]) THEN
        ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[swap];
      ASM_REWRITE_TAC[swap]]]);;

let GRAPH_FACE_SUCCESSOR_DELETE_EDGE_AS_CROSS_DELETE = prove
 (`!V E r u v d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E /\
        d IN graph_darts (E DELETE {u,v})
        ==> graph_face_successor
              (E DELETE {u,v}) (graph_delete_rotation r u v) d =
            permutation_delete_two
              (swap((u,v),(v,u)) o graph_face_successor E r)
              (u,v) (v,u) d`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation edge dart" THEN
  SUBGOAL_THEN
   `~(u:A = v) /\
    ((u:A),(v:A)) IN graph_darts E /\
    ((v:A),(u:A)) IN graph_darts E`
  (CONJUNCTS_THEN2 (LABEL_TAC "distinct")
    (CONJUNCTS_THEN2 (LABEL_TAC "forward") (LABEL_TAC "reverse"))) THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_EDGE_DARTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(graph_face_successor E (r:(A#A)->A#A))
    permutes graph_darts E`
  (LABEL_TAC "face_permutation") THENL
   [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(graph_face_successor E (r:(A#A)->A#A) (u,v) = (u,v))`
  (LABEL_TAC "forward_nonfixed") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `(u:A,v:A)`]
     GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(graph_face_successor E (r:(A#A)->A#A) (v,u) = (v,u))`
  (LABEL_TAC "reverse_nonfixed") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `(v:A,u:A)`]
     GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_delete_two
      (swap((u:A,v:A),(v:A,u:A)) o graph_face_successor E r)
      (u,v) (v,u) d =
    if graph_face_successor E r d = (u,v) then
      graph_face_successor E r (v,u)
    else if graph_face_successor E r d = (v,u) then
      graph_face_successor E r (u,v)
    else graph_face_successor E r d`
  (LABEL_TAC "cross_delete") THENL
   [MATCH_MP_TAC(ISPECL
     [`graph_face_successor E (r:(A#A)->A#A)`;
      `graph_darts E:A#A->bool`;
      `(u:A,v:A)`; `(v:A,u:A)`; `d:A#A`]
     PERMUTATION_DELETE_TWO_AFTER_SWAP) THEN
    ASM_REWRITE_TAC[PAIR_EQ; GSYM GRAPH_DARTS_DELETE_EDGE];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `d:A#A`]
   GRAPH_FACE_SUCCESSOR_DELETE_EDGE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "deleted_successor") THEN
  USE_THEN "deleted_successor" SUBST1_TAC THEN
  USE_THEN "cross_delete" (ACCEPT_TAC o SYM));;

let GRAPH_FACE_DELETE_EDGE_MERGES_DISTINCT_FACES = prove
 (`!V E r u v a b:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E /\
        a IN graph_darts (E DELETE {u,v}) /\
        b IN graph_darts (E DELETE {u,v}) /\
        ~(graph_face E r (u,v) = graph_face E r (v,u)) /\
        (a IN graph_face E r (u,v) \/
         a IN graph_face E r (v,u)) /\
        (b IN graph_face E r (u,v) \/
         b IN graph_face E r (v,u))
        ==> b IN
            graph_face
              (E DELETE {u,v})
              (graph_delete_rotation r u v) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph rotation edge a_dart b_dart distinct_faces \
    a_affected b_affected" THEN
  SUBGOAL_THEN
   `~(u:A = v) /\
    ((u:A),(v:A)) IN graph_darts E /\
    ((v:A),(u:A)) IN graph_darts E`
  (CONJUNCTS_THEN2 (LABEL_TAC "distinct")
    (CONJUNCTS_THEN2 (LABEL_TAC "forward") (LABEL_TAC "reverse"))) THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_EDGE_DARTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(graph_darts (E:(A->bool)->bool))`
  (LABEL_TAC "finite_darts") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  ABBREV_TAC
   `f:(A#A)->A#A =
      graph_face_successor (E:(A->bool)->bool) (r:(A#A)->A#A)` THEN
  ABBREV_TAC
   `h:(A#A)->A#A =
      swap(((u:A),(v:A)),((v:A),(u:A))) o (f:(A#A)->A#A)` THEN
  ABBREV_TAC
   `k:(A#A)->A#A =
      permutation_delete_two
        (h:(A#A)->A#A) ((u:A),(v:A)) ((v:A),(u:A))` THEN
  SUBGOAL_THEN `(f:(A#A)->A#A) permutes graph_darts E`
  (LABEL_TAC "f_permutation") THENL
   [EXPAND_TAC "f" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(h:(A#A)->A#A) permutes graph_darts E`
  (LABEL_TAC "h_permutation") THENL
   [EXPAND_TAC "h" THEN
    MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(k:(A#A)->A#A) permutes
    (graph_darts E DELETE (u,v) DELETE (v,u))`
  (LABEL_TAC "k_permutation") THENL
   [EXPAND_TAC "k" THEN
    MATCH_MP_TAC PERMUTATION_DELETE_TWO_PERMUTES THEN
    ASM_REWRITE_TAC[PAIR_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(a:A#A) IN graph_darts E /\ (b:A#A) IN graph_darts E`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_old_dart")
    (LABEL_TAC "b_old_dart")) THENL
   [CONJ_TAC THENL
     [USE_THEN "a_dart" MP_TAC;
      USE_THEN "b_dart" MP_TAC] THEN
    REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE; IN_DELETE] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(b:A#A) IN permutation_orbit h a`
  (LABEL_TAC "merged_orbit") THENL
   [EXPAND_TAC "h" THEN
    MATCH_MP_TAC(ISPECL
     [`f:(A#A)->A#A`; `graph_darts E:A#A->bool`;
      `(u:A,v:A)`; `(v:A,u:A)`; `a:A#A`; `b:A#A`]
     PERMUTATION_SWAP_COALESCES_DISTINCT_ORBITS) THEN
    ASM_REWRITE_TAC[] THEN
    EXPAND_TAC "f" THEN
    ASM_REWRITE_TAC[GSYM GRAPH_FACE_AS_PERMUTATION_ORBIT];
    ALL_TAC] THEN
  SUBGOAL_THEN `(b:A#A) IN permutation_orbit k a`
  (LABEL_TAC "deleted_orbit") THENL
   [EXPAND_TAC "k" THEN
    MATCH_MP_TAC(ISPECL
     [`h:(A#A)->A#A`; `graph_darts E:A#A->bool`;
      `(u:A,v:A)`; `(v:A,u:A)`; `a:A#A`; `b:A#A`]
     PERMUTATION_DELETE_TWO_PRESERVES_OLD_ORBIT) THEN
    ASM_REWRITE_TAC[PAIR_EQ; GSYM GRAPH_DARTS_DELETE_EDGE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit
      (graph_face_successor
        (E DELETE {u,v})
        (graph_delete_rotation (r:(A#A)->A#A) u v)) a =
    permutation_orbit (k:(A#A)->A#A) a`
  (LABEL_TAC "new_orbit") THENL
   [MATCH_MP_TAC PERMUTATION_ORBIT_EQ_IF_AGREE THEN
    X_GEN_TAC `z:A#A` THEN DISCH_THEN(LABEL_TAC "z_orbit") THEN
    SUBGOAL_THEN
     `(z:A#A) IN graph_darts E DELETE (u,v) DELETE (v,u)`
    (LABEL_TAC "z_dart") THENL
     [MP_TAC(ISPECL
       [`k:(A#A)->A#A`;
        `(graph_darts E DELETE (u,v) DELETE (v,u)):A#A->bool`;
        `a:A#A`]
       PERMUTATION_ORBIT_SUBSET) THEN
      ASM_REWRITE_TAC[GSYM GRAPH_DARTS_DELETE_EDGE; SUBSET] THEN
      DISCH_THEN(MP_TAC o SPEC `z:A#A`) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    EXPAND_TAC "k" THEN EXPAND_TAC "h" THEN EXPAND_TAC "f" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`; `z:A#A`]
     GRAPH_FACE_SUCCESSOR_DELETE_EDGE_AS_CROSS_DELETE) THEN
    ASM_REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE];
    ALL_TAC] THEN
  REWRITE_TAC[GRAPH_FACE_AS_PERMUTATION_ORBIT] THEN
  USE_THEN "new_orbit" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "deleted_orbit" ACCEPT_TAC);;

let PERMUTATION_DELETE_FIXED_ORBIT_COUNT = prove
 (`!f:A->A. !s x.
        FINITE s /\
        f permutes s /\
        x IN s /\
        f x = x
        ==> CARD(permutation_orbits f s) =
            CARD
              (permutation_orbits
                (permutation_delete f x) (s DELETE x)) + 1`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutation member fixed" THEN
  SUBGOAL_THEN
   `permutation_delete (f:A->A) x permutes (s DELETE x)`
  (LABEL_TAC "deleted_permutation") THENL
   [MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN s DELETE x
          ==> permutation_delete f x z = f z`
  (LABEL_TAC "agree") THENL
   [X_GEN_TAC `z:A` THEN REWRITE_TAC[IN_DELETE] THEN
    INTRO_TAC "z_member z_distinct" THEN
    MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`; `z:A`]
     PERMUTATION_DELETE_APPLY_IN) THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `~((f:A->A) z = x)` (LABEL_TAC "not_enter") THENL
     [DISCH_THEN(LABEL_TAC "enters") THEN
      MP_TAC(MATCH_MP
       (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
       (ASSUME `(f:A->A) permutes s`)) THEN
      DISCH_THEN(MP_TAC o SPECL [`z:A`; `x:A`]) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbits (f:A->A) ((s:A->bool) DELETE (x:A)) =
    permutation_orbits
      (permutation_delete f x) ((s:A->bool) DELETE x)`
  (LABEL_TAC "same_surviving_orbits") THENL
   [MATCH_MP_TAC(ISPECL
     [`permutation_delete (f:A->A) x`; `f:A->A`;
      `(s DELETE x):A->bool`]
     PERMUTATION_ORBITS_EQ_ON) THEN
    CONJ_TAC THENL
     [USE_THEN "deleted_permutation" ACCEPT_TAC;
      X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_member") THEN
      CONV_TAC SYM_CONV THEN
      USE_THEN "agree" (MATCH_MP_TAC o SPEC `z:A`) THEN
      USE_THEN "z_member" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `x INSERT ((s:A->bool) DELETE x) = s`
  (LABEL_TAC "restore_set") THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `permutation_orbit (f:A->A) x = {x}`
  (LABEL_TAC "fixed_orbit") THENL
   [MATCH_MP_TAC PERMUTATION_ORBIT_FIXED THEN
    USE_THEN "fixed" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbits (f:A->A) (s:A->bool) =
    ({x:A}:A->bool) INSERT
      permutation_orbits
        (permutation_delete f x) ((s:A->bool) DELETE x)`
  (LABEL_TAC "orbit_decomposition") THENL
   [ASM_MESON_TAC[PERMUTATION_ORBITS_INSERT_FIXED];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(({x:A}:A->bool) IN
      permutation_orbits (permutation_delete f x) (s DELETE x))`
  (LABEL_TAC "fixed_orbit_fresh") THENL
   [REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
    INTRO_TAC "@z. z_member orbit" THEN
    SUBGOAL_THEN
     `(z:A) IN permutation_orbit (permutation_delete f x) z`
    (LABEL_TAC "z_refl") THENL
     [MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL;
      USE_THEN "orbit" (fun th ->
       USE_THEN "z_refl" (MP_TAC o REWRITE_RULE[GSYM th])) THEN
      USE_THEN "z_member" MP_TAC THEN
      REWRITE_TAC[IN_SING; IN_DELETE] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE
      (permutation_orbits
        (permutation_delete (f:A->A) x) (s DELETE x))`
  (LABEL_TAC "finite_surviving_orbits") THENL
   [MATCH_MP_TAC FINITE_PERMUTATION_ORBITS THEN
    ASM_REWRITE_TAC[FINITE_DELETE];
    ALL_TAC] THEN
  USE_THEN "orbit_decomposition" SUBST1_TAC THEN
  ASM_SIMP_TAC[CARD_CLAUSES] THEN ARITH_TAC);;

let EULER_PLANAR_ROTATION_DELETE_EDGE_FACE_COUNT = prove
 (`!V E r u v:A.
        euler_planar_rotation V E r /\
        {u,v} IN E /\
        connected_graph V (E DELETE {u,v})
        ==> CARD(graph_faces E r) =
            CARD
              (graph_faces
                (E DELETE {u,v}) (graph_delete_rotation r u v)) + 1`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler edge connected" THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph rotation formula" THEN
  SUBGOAL_THEN
   `euler_planar_rotation
      (V:A->bool) (E DELETE {u,v})
      (graph_delete_rotation (r:(A#A)->A#A) u v)`
  (LABEL_TAC "deleted_euler") THENL
   [MATCH_MP_TAC EULER_PLANAR_ROTATION_DELETE_EDGE_CONNECTED THEN
    ASM_REWRITE_TAC[euler_planar_rotation];
    ALL_TAC] THEN
  USE_THEN "deleted_euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "deleted_graph deleted_rotation deleted_formula" THEN
  SUBGOAL_THEN `~(u:A = v)` (LABEL_TAC "distinct") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_EDGE_DARTS) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((E DELETE {u,v}):(A->bool)->bool) = {})`
  (LABEL_TAC "deleted_edges_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "deleted_edges_empty") THEN
    SUBGOAL_THEN
     `graph_reachable
       ((E DELETE {u,v}):(A->bool)->bool) (u:A) (v:A)`
    (LABEL_TAC "reachable") THENL
     [USE_THEN "connected" MP_TAC THEN
      REWRITE_TAC[connected_graph] THEN
      DISCH_THEN(MP_TAC o SPECL [`u:A`; `v:A`]) THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
      USE_THEN "deleted_edges_empty" (fun th ->
       USE_THEN "reachable" (MP_TAC o REWRITE_RULE[th])) THEN
      ASM_REWRITE_TAC[GRAPH_REACHABLE_EMPTY]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(E:(A->bool)->bool = {})`
  (LABEL_TAC "edges_nonempty") THENL
   [USE_THEN "edge" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(E:(A->bool)->bool)`
  (LABEL_TAC "finite_edges") THENL
   [USE_THEN "graph"
     (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o
      REWRITE_RULE[finite_simple_graph]);
    ALL_TAC] THEN
  SUBGOAL_THEN `0 < CARD(E:(A->bool)->bool)`
  (LABEL_TAC "edges_positive") THENL
   [SUBGOAL_THEN `~(CARD(E:(A->bool)->bool) = 0)` MP_TAC THENL
     [ASM_SIMP_TAC[CARD_EQ_0];
      ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD((E DELETE {u,v}):(A->bool)->bool) = CARD E - 1`
  (LABEL_TAC "deleted_edge_count") THENL
   [MP_TAC(ISPECL
     [`{u:A,v}:A->bool`; `E:(A->bool)->bool`] CARD_DELETE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "formula" MP_TAC THEN
  USE_THEN "deleted_formula" MP_TAC THEN
  REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let PERMUTATION_ORBIT_TWO_CYCLE_SUBSET = prove
 (`!f:A->A. !x y.
        f x = y /\ f y = x
        ==> permutation_orbit f x SUBSET {x,y}`,
  REPEAT GEN_TAC THEN INTRO_TAC "forward reverse" THEN
  REWRITE_TAC[SUBSET; IN_PERMUTATION_ORBIT] THEN
  X_GEN_TAC `z:A` THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` (SUBST1_TAC o SYM)) THEN
  SPEC_TAC(`n:num`,`n:num`) THEN
  INDUCT_TAC THENL
   [REWRITE_TAC[ITER; IN_INSERT];
    REWRITE_TAC[ITER] THEN
    FIRST_X_ASSUM MP_TAC THEN
    REWRITE_TAC[IN_INSERT; IN_SING] THEN
    ASM_MESON_TAC[]]);;

let EULER_PLANAR_ROTATION_NONSEPARATING_EDGE_DISTINCT_FACES = prove
 (`!V E r u v:A.
        euler_planar_rotation V E r /\
        {u,v} IN E /\
        connected_graph V (E DELETE {u,v}) /\
        3 <= CARD V
        ==> ~(graph_face E r (u,v) = graph_face E r (v,u))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "euler edge deleted_connected vertices_large" THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph rotation formula" THEN
  ABBREV_TAC `x:A#A = (u:A,v:A)` THEN
  ABBREV_TAC `y:A#A = (v:A,u:A)` THEN
  ABBREV_TAC `s:(A#A)->bool = graph_darts E` THEN
  ABBREV_TAC
   `f:(A#A)->A#A =
      graph_face_successor (E:(A->bool)->bool) (r:(A#A)->A#A)` THEN
  ABBREV_TAC `h:(A#A)->A#A = swap(x,y) o f` THEN
  ABBREV_TAC `p:(A#A)->A#A = permutation_delete h x` THEN
  ABBREV_TAC `q:(A#A)->A#A = permutation_delete p y` THEN
  ABBREV_TAC
   `g:(A#A)->A#A =
      graph_face_successor
       (E DELETE {u,v})
       (graph_delete_rotation (r:(A#A)->A#A) u v)` THEN
  SUBGOAL_THEN
   `~(x:A#A = y) /\ (x:A#A) IN s /\ (y:A#A) IN s`
  (CONJUNCTS_THEN2 (LABEL_TAC "distinct")
    (CONJUNCTS_THEN2 (LABEL_TAC "x_member") (LABEL_TAC "y_member"))) THENL
   [MAP_EVERY EXPAND_TAC ["x"; "y"; "s"] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_EDGE_DARTS) THEN
    ASM_REWRITE_TAC[PAIR_EQ] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(s:(A#A)->bool)` (LABEL_TAC "finite_darts") THENL
   [EXPAND_TAC "s" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(f:(A#A)->A#A) permutes s`
  (LABEL_TAC "f_permutation") THENL
   [EXPAND_TAC "f" THEN EXPAND_TAC "s" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(h:(A#A)->A#A) permutes s`
  (LABEL_TAC "h_permutation") THENL
   [EXPAND_TAC "h" THEN
    MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:(A#A)->A#A) permutes (s DELETE x)`
  (LABEL_TAC "p_permutation") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:(A#A)->A#A) permutes (s DELETE x DELETE y)`
  (LABEL_TAC "q_permutation") THENL
   [EXPAND_TAC "q" THEN
    MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN
    ASM_REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(y:A#A) IN s DELETE x`
  (LABEL_TAC "y_survives") THENL
   [ASM_REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "same_face") THEN
  SUBGOAL_THEN
   `permutation_orbit (f:(A#A)->A#A) x =
    permutation_orbit f y`
  (LABEL_TAC "same_old_orbit") THENL
   [EXPAND_TAC "f" THEN
    USE_THEN "same_face" MP_TAC THEN
    REWRITE_TAC[GRAPH_FACE_AS_PERMUTATION_ORBIT];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(permutation_orbits (h:(A#A)->A#A) s) =
    CARD(permutation_orbits f s) + 1`
  (LABEL_TAC "swap_count") THENL
   [EXPAND_TAC "h" THEN
    MATCH_MP_TAC(ISPECL
     [`f:(A#A)->A#A`; `s:(A#A)->bool`; `x:A#A`; `y:A#A`]
     PERMUTATION_ORBITS_SWAP_SAME) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbits (g:(A#A)->A#A) (s DELETE x DELETE y) =
    permutation_orbits q (s DELETE x DELETE y)`
  (LABEL_TAC "same_new_orbits") THENL
   [MATCH_MP_TAC(ISPECL
     [`q:(A#A)->A#A`; `g:(A#A)->A#A`;
      `(s:(A#A)->bool) DELETE x DELETE y`]
     PERMUTATION_ORBITS_EQ_ON) THEN
    CONJ_TAC THENL
     [USE_THEN "q_permutation" ACCEPT_TAC;
      X_GEN_TAC `z:A#A` THEN DISCH_THEN(LABEL_TAC "z_member") THEN
      MAP_EVERY EXPAND_TAC ["g"; "q"; "p"; "h"; "f"] THEN
      REWRITE_TAC[GSYM permutation_delete_two] THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `u:A`; `v:A`; `z:A#A`]
       GRAPH_FACE_SUCCESSOR_DELETE_EDGE_AS_CROSS_DELETE) THEN
      ASM_REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(permutation_orbits (f:(A#A)->A#A) s) =
    CARD(permutation_orbits (q:(A#A)->A#A) (s DELETE x DELETE y)) + 1`
  (LABEL_TAC "face_count") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`]
     EULER_PLANAR_ROTATION_DELETE_EDGE_FACE_COUNT) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[GRAPH_FACES_AS_PERMUTATION_ORBITS] THEN
    MAP_EVERY EXPAND_TAC ["f"; "g"; "s"; "x"; "y"] THEN
    REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE] THEN
    USE_THEN "same_new_orbits" (fun th -> REWRITE_TAC[th]) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(h:(A#A)->A#A) x = x` THENL
   [FIRST_X_ASSUM(LABEL_TAC "x_fixed") THEN
    SUBGOAL_THEN
     `CARD(permutation_orbits (h:(A#A)->A#A) s) =
      CARD(permutation_orbits (p:(A#A)->A#A) (s DELETE x)) + 1`
    (LABEL_TAC "first_count") THENL
     [EXPAND_TAC "p" THEN
      MATCH_MP_TAC(ISPECL
       [`h:(A#A)->A#A`; `s:(A#A)->bool`; `x:A#A`]
       PERMUTATION_DELETE_FIXED_ORBIT_COUNT) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_CASES_TAC `(p:(A#A)->A#A) y = y` THENL
     [FIRST_X_ASSUM(LABEL_TAC "y_fixed") THEN
      SUBGOAL_THEN
       `CARD(permutation_orbits (p:(A#A)->A#A) (s DELETE x)) =
        CARD(permutation_orbits (q:(A#A)->A#A)
          (s DELETE x DELETE y)) + 1`
      (LABEL_TAC "second_count") THENL
       [EXPAND_TAC "q" THEN
        MATCH_MP_TAC(ISPECL
         [`p:(A#A)->A#A`; `(s:(A#A)->bool) DELETE x`; `y:A#A`]
         PERMUTATION_DELETE_FIXED_ORBIT_COUNT) THEN
        ASM_REWRITE_TAC[FINITE_DELETE];
        ALL_TAC] THEN
      SUBGOAL_THEN `~((h:(A#A)->A#A) y = x)`
      (LABEL_TAC "y_not_to_x") THENL
       [MP_TAC(MATCH_MP
         (ISPECL [`h:(A#A)->A#A`; `s:(A#A)->bool`]
          PERMUTES_INJECTIVE)
         (ASSUME `(h:(A#A)->A#A) permutes s`)) THEN
        DISCH_THEN(MP_TAC o SPECL [`y:A#A`; `x:A#A`]) THEN
        ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(p:(A#A)->A#A) y = h y`
      (LABEL_TAC "p_y") THENL
       [EXPAND_TAC "p" THEN
        MP_TAC(ISPECL
         [`h:(A#A)->A#A`; `s:(A#A)->bool`; `x:A#A`; `y:A#A`]
         PERMUTATION_DELETE_APPLY_IN) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(h:(A#A)->A#A) y = y`
      (LABEL_TAC "h_y_fixed") THENL
       [ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(f:(A#A)->A#A) x = y`
      (LABEL_TAC "f_x") THENL
       [USE_THEN "x_fixed" MP_TAC THEN
        EXPAND_TAC "h" THEN
        REWRITE_TAC[o_THM; swap] THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(f:(A#A)->A#A) y = x`
      (LABEL_TAC "f_y") THENL
       [USE_THEN "h_y_fixed" MP_TAC THEN
        EXPAND_TAC "h" THEN
        REWRITE_TAC[o_THM; swap] THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `permutation_orbit (f:(A#A)->A#A) x SUBSET {x,y}`
      (LABEL_TAC "two_cycle") THENL
       [MATCH_MP_TAC PERMUTATION_ORBIT_TWO_CYCLE_SUBSET THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `connected_graph (V:A->bool) E`
      (LABEL_TAC "connected") THENL
       [MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `(E DELETE {u,v}):(A->bool)->bool`;
          `E:(A->bool)->bool`] CONNECTED_GRAPH_MONO) THEN
        ASM_REWRITE_TAC[] THEN SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `3 <= CARD(graph_face E (r:(A#A)->A#A) x)`
      (LABEL_TAC "face_large") THENL
       [MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `x:A#A`]
         CONNECTED_SIMPLE_GRAPH_FACE_CARD_AT_LEAST_3) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `graph_face E (r:(A#A)->A#A) x SUBSET {x,y}`
      (LABEL_TAC "face_subset") THENL
       [REWRITE_TAC[GRAPH_FACE_AS_PERMUTATION_ORBIT] THEN
        ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `CARD(graph_face E (r:(A#A)->A#A) x) <= CARD {x:A#A,y}`
      (LABEL_TAC "card_upper") THENL
       [MATCH_MP_TAC CARD_SUBSET THEN CONJ_TAC THENL
         [USE_THEN "face_subset" ACCEPT_TAC;
          REWRITE_TAC[FINITE_INSERT; FINITE_EMPTY]];
        ALL_TAC] THEN
      SUBGOAL_THEN `CARD {x:A#A,y} = 2` (LABEL_TAC "pair_card") THENL
       [ASM_SIMP_TAC
         [CARD_CLAUSES; FINITE_INSERT; FINITE_EMPTY; IN_SING;
          NOT_IN_EMPTY] THEN
        ARITH_TAC;
        ASM_ARITH_TAC];
      FIRST_X_ASSUM(LABEL_TAC "y_nonfixed") THEN
      SUBGOAL_THEN
       `CARD(permutation_orbits (q:(A#A)->A#A)
          (s DELETE x DELETE y)) =
        CARD(permutation_orbits (p:(A#A)->A#A) (s DELETE x))`
      (LABEL_TAC "second_count") THENL
       [EXPAND_TAC "q" THEN
        MATCH_MP_TAC(ISPECL
         [`p:(A#A)->A#A`; `(s:(A#A)->bool) DELETE x`; `y:A#A`]
         PERMUTATION_DELETE_ORBIT_COUNT) THEN
        ASM_REWRITE_TAC[FINITE_DELETE];
        ALL_TAC] THEN
      ASM_ARITH_TAC];
    FIRST_X_ASSUM(LABEL_TAC "x_nonfixed") THEN
    SUBGOAL_THEN
     `CARD(permutation_orbits (p:(A#A)->A#A) (s DELETE x)) =
      CARD(permutation_orbits (h:(A#A)->A#A) s)`
    (LABEL_TAC "first_count") THENL
     [EXPAND_TAC "p" THEN
      MATCH_MP_TAC(ISPECL
       [`h:(A#A)->A#A`; `s:(A#A)->bool`; `x:A#A`]
       PERMUTATION_DELETE_ORBIT_COUNT) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_CASES_TAC `(p:(A#A)->A#A) y = y` THENL
     [FIRST_X_ASSUM(LABEL_TAC "y_fixed") THEN
      SUBGOAL_THEN
       `CARD(permutation_orbits (p:(A#A)->A#A) (s DELETE x)) =
        CARD(permutation_orbits (q:(A#A)->A#A)
          (s DELETE x DELETE y)) + 1`
      (LABEL_TAC "second_count") THENL
       [EXPAND_TAC "q" THEN
        MATCH_MP_TAC(ISPECL
         [`p:(A#A)->A#A`; `(s:(A#A)->bool) DELETE x`; `y:A#A`]
         PERMUTATION_DELETE_FIXED_ORBIT_COUNT) THEN
        ASM_REWRITE_TAC[FINITE_DELETE];
        ALL_TAC] THEN
      ASM_ARITH_TAC;
      FIRST_X_ASSUM(LABEL_TAC "y_nonfixed") THEN
      SUBGOAL_THEN
       `CARD(permutation_orbits (q:(A#A)->A#A)
          (s DELETE x DELETE y)) =
        CARD(permutation_orbits (p:(A#A)->A#A) (s DELETE x))`
      (LABEL_TAC "second_count") THENL
       [EXPAND_TAC "q" THEN
        MATCH_MP_TAC(ISPECL
         [`p:(A#A)->A#A`; `(s:(A#A)->bool) DELETE x`; `y:A#A`]
         PERMUTATION_DELETE_ORBIT_COUNT) THEN
        ASM_REWRITE_TAC[FINITE_DELETE];
        ALL_TAC] THEN
      ASM_ARITH_TAC]]);;

let GRAPH_FACE_DELETE_EDGE_PRESERVES_COFACIAL = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
        !u v:A. !a b:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E /\
        a IN graph_darts (E DELETE {u,v}) /\
        b IN graph_darts (E DELETE {u,v}) /\
        ~(graph_face E r (u,v) = graph_face E r (v,u)) /\
        b IN graph_face E r a
        ==> b IN
            graph_face
              (E DELETE {u,v}) (graph_delete_rotation r u v) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph rotation edge a_survives b_survives distinct_faces cofacial" THEN
  SUBGOAL_THEN `(a:A#A) IN graph_darts E`
  (LABEL_TAC "a_dart") THENL
   [USE_THEN "a_survives" MP_TAC THEN
    REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE; IN_DELETE] THEN MESON_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC
   `(a:A#A) IN graph_face E r (u,v) \/
    a IN graph_face E r (v,u)` THENL
   [FIRST_X_ASSUM(LABEL_TAC "affected") THEN
    SUBGOAL_THEN
     `(b:A#A) IN graph_face E r (u,v) \/
      b IN graph_face E r (v,u)`
    (LABEL_TAC "b_affected") THENL
     [USE_THEN "affected" MP_TAC THEN
      USE_THEN "cofacial" MP_TAC THEN
      MESON_TAC[GRAPH_FACE_TRANS];
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `u:A`; `v:A`; `a:A#A`; `b:A#A`]
       GRAPH_FACE_DELETE_EDGE_MERGES_DISTINCT_FACES) THEN
      ASM_REWRITE_TAC[]];
    FIRST_X_ASSUM(LABEL_TAC "unaffected") THEN
    SUBGOAL_THEN
     `!z:A#A.
        z IN graph_face
             (E:(A->bool)->bool) (r:(A#A)->A#A) (a:A#A)
        ==> graph_face_successor
              (E DELETE {(u:A),(v:A)})
              (graph_delete_rotation r u v) z =
            graph_face_successor E r z`
    (LABEL_TAC "successor_agrees") THENL
     [X_GEN_TAC `z:A#A` THEN DISCH_THEN(LABEL_TAC "z_face") THEN
      SUBGOAL_THEN `(z:A#A) IN graph_darts E`
      (LABEL_TAC "z_dart") THENL
       [MATCH_MP_TAC
         (REWRITE_RULE[SUBSET]
          (MATCH_MP
           (ISPECL
            [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `a:A#A`]
            GRAPH_FACE_SUBSET_DARTS)
           (CONJ (ASSUME `graph_rotation E (r:(A#A)->A#A)`)
                 (ASSUME `(a:A#A) IN graph_darts E`)))) THEN
        USE_THEN "z_face" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(graph_face_successor E (r:(A#A)->A#A) z) IN
        graph_face E r a`
      (LABEL_TAC "next_face") THENL
       [USE_THEN "z_face" MP_TAC THEN
        REWRITE_TAC[IN_GRAPH_FACE] THEN
        DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "z_step")) THEN
        REWRITE_TAC[IN_GRAPH_FACE] THEN
        EXISTS_TAC `SUC n` THEN
        REWRITE_TAC[ITER] THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `~((z:A#A) = (u,v)) /\ ~(z = (v,u))`
      (CONJUNCTS_THEN2 (LABEL_TAC "z_not_forward")
        (LABEL_TAC "z_not_reverse")) THENL
       [CONJ_TAC THEN DISCH_THEN(LABEL_TAC "z_incident") THEN
        USE_THEN "unaffected" (MATCH_MP_TAC o NOT_ELIM) THENL
         [DISJ1_TAC;
          DISJ2_TAC] THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
          `a:A#A`; `z:A#A`] GRAPH_FACE_SYM) THEN
        ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `~(graph_face_successor
            (E:(A->bool)->bool) (r:(A#A)->A#A) (z:A#A) =
           ((u:A),(v:A))) /\
        ~(graph_face_successor E r z = ((v:A),(u:A)))`
      (CONJUNCTS_THEN2 (LABEL_TAC "next_not_forward")
        (LABEL_TAC "next_not_reverse")) THENL
       [CONJ_TAC THENL
         [DISCH_THEN(LABEL_TAC "next_forward") THEN
          USE_THEN "unaffected" (MATCH_MP_TAC o NOT_ELIM) THEN
          DISJ1_TAC THEN
          MATCH_MP_TAC(ISPECL
           [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
            `a:A#A`; `(u:A,v:A)`] GRAPH_FACE_SYM) THEN
          REPEAT CONJ_TAC THENL
           [USE_THEN "graph" ACCEPT_TAC;
            USE_THEN "rotation" ACCEPT_TAC;
            USE_THEN "a_dart" ACCEPT_TAC;
            USE_THEN "next_face" MP_TAC THEN
            USE_THEN "next_forward" (fun th -> REWRITE_TAC[th])];
          DISCH_THEN(LABEL_TAC "next_reverse") THEN
          USE_THEN "unaffected" (MATCH_MP_TAC o NOT_ELIM) THEN
          DISJ2_TAC THEN
          MATCH_MP_TAC(ISPECL
           [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
            `a:A#A`; `(v:A,u:A)`] GRAPH_FACE_SYM) THEN
          REPEAT CONJ_TAC THENL
           [USE_THEN "graph" ACCEPT_TAC;
            USE_THEN "rotation" ACCEPT_TAC;
            USE_THEN "a_dart" ACCEPT_TAC;
            USE_THEN "next_face" MP_TAC THEN
            USE_THEN "next_reverse" (fun th -> REWRITE_TAC[th])]];
        ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `u:A`; `v:A`; `z:A#A`]
       GRAPH_FACE_SUCCESSOR_DELETE_EDGE_UNCHANGED) THEN
      ASM_REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE; IN_DELETE];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_face
        ((E:(A->bool)->bool) DELETE {(u:A),(v:A)})
        (graph_delete_rotation (r:(A#A)->A#A) u v) (a:A#A) =
      graph_face E r a`
    (LABEL_TAC "same_face") THENL
     [REWRITE_TAC[GRAPH_FACE_AS_PERMUTATION_ORBIT] THEN
      MATCH_MP_TAC PERMUTATION_ORBIT_EQ_IF_AGREE THEN
      X_GEN_TAC `z:A#A` THEN
      REWRITE_TAC[GSYM GRAPH_FACE_AS_PERMUTATION_ORBIT] THEN
      USE_THEN "successor_agrees" (ACCEPT_TAC o SPEC `z:A#A`);
      USE_THEN "same_face" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "cofacial" ACCEPT_TAC]]);;

let EULER_PLANAR_ROTATION_NONSEPARATING_EDGE_PRESERVES_COFACIAL = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
        !u v:A. !a b:A#A.
        euler_planar_rotation V E r /\
        {u,v} IN E /\
        connected_graph V (E DELETE {u,v}) /\
        3 <= CARD V /\
        a IN graph_darts (E DELETE {u,v}) /\
        b IN graph_darts (E DELETE {u,v}) /\
        b IN graph_face E r a
        ==> b IN
            graph_face
              (E DELETE {u,v}) (graph_delete_rotation r u v) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler edge connected vertices_large a_survives b_survives cofacial" THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph rotation formula" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `a:A#A`; `b:A#A`]
   GRAPH_FACE_DELETE_EDGE_PRESERVES_COFACIAL) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`]
   EULER_PLANAR_ROTATION_NONSEPARATING_EDGE_DISTINCT_FACES) THEN
  ASM_REWRITE_TAC[euler_planar_rotation]);;

let PERMUTATION_DELETE_TWO_AFTER_CONSECUTIVE_SWAP = prove
 (`!f:A->A. !s x y z.
        f permutes s /\
        x IN s /\
        y IN s /\
        ~(x = y) /\
        f x = y /\
        z IN s DELETE x DELETE y
        ==> permutation_delete_two (swap(x,y) o f) x y z =
            permutation_delete_two f x y z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "permutation x_member y_member distinct consecutive z_member" THEN
  SUBGOAL_THEN `(z:A) IN s /\ ~(z = x) /\ ~(z = y)`
  (CONJUNCTS_THEN2 (LABEL_TAC "z_in_s")
    (CONJUNCTS_THEN2 (LABEL_TAC "z_not_x") (LABEL_TAC "z_not_y"))) THENL
   [USE_THEN "z_member" MP_TAC THEN REWRITE_TAC[IN_DELETE] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((f:A->A) z = y)` (LABEL_TAC "fz_not_y") THENL
   [DISCH_THEN(LABEL_TAC "fz_y") THEN
    MP_TAC(MATCH_MP
     (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
     (ASSUME `(f:A->A) permutes s`)) THEN
    DISCH_THEN(MP_TAC o SPECL [`z:A`; `x:A`]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`f:A->A`; `s:A->bool`; `x:A`; `y:A`; `z:A`]
   PERMUTATION_DELETE_TWO_AFTER_SWAP) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    DISCH_THEN(LABEL_TAC "y_fixed") THEN
    MP_TAC(MATCH_MP
     (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
     (ASSUME `(f:A->A) permutes s`)) THEN
    DISCH_THEN(MP_TAC o SPECL [`x:A`; `y:A`]) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]] THEN
  REWRITE_TAC[permutation_delete_two] THEN
  ABBREV_TAC `p:A->A = permutation_delete (f:A->A) x` THEN
  SUBGOAL_THEN `(p:A->A) permutes (s DELETE x)`
  (LABEL_TAC "p_permutation") THENL
   [EXPAND_TAC "p" THEN MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:A->A) z = if f z = x then f x else f z`
  (LABEL_TAC "p_z") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`; `z:A`]
     PERMUTATION_DELETE_APPLY_IN) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:A->A) y = if f y = x then f x else f y`
  (LABEL_TAC "p_y") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`; `y:A`]
     PERMUTATION_DELETE_APPLY_IN) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`p:A->A`; `s DELETE (x:A)`; `y:A`; `z:A`]
   PERMUTATION_DELETE_APPLY_IN) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[IN_DELETE];
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "p_z" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "p_y" (fun th -> REWRITE_TAC[th]) THEN
    ASM_CASES_TAC `(f:A->A) z = x` THENL
     [SUBGOAL_THEN `~((f:A->A) y = x)` (LABEL_TAC "fy_not_x") THENL
       [DISCH_THEN(LABEL_TAC "fy_x") THEN
        MP_TAC(MATCH_MP
         (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
         (ASSUME `(f:A->A) permutes s`)) THEN
        DISCH_THEN(MP_TAC o SPECL [`z:A`; `y:A`]) THEN
        ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[]];
      ASM_REWRITE_TAC[]]]);;

let GRAPH_FACE_SUCCESSOR_DELETE_CONSECUTIVE_EDGE_AS_DELETE_TWO = prove
 (`!V E r u v d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E /\
        graph_face_successor E r (u,v) = (v,u) /\
        d IN graph_darts (E DELETE {u,v})
        ==> graph_face_successor
              (E DELETE {u,v}) (graph_delete_rotation r u v) d =
            permutation_delete_two
              (graph_face_successor E r) (u,v) (v,u) d`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation edge consecutive dart" THEN
  TRANS_TAC EQ_TRANS
   `permutation_delete_two
      (swap(((u:A),(v:A)),((v:A),(u:A))) o
       graph_face_successor E (r:(A#A)->A#A))
      (u,v) (v,u) d` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`; `d:A#A`]
     GRAPH_FACE_SUCCESSOR_DELETE_EDGE_AS_CROSS_DELETE) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`graph_face_successor E (r:(A#A)->A#A)`;
      `graph_darts E:A#A->bool`; `(u:A,v:A)`; `(v:A,u:A)`;
      `d:A#A`]
     PERMUTATION_DELETE_TWO_AFTER_CONSECUTIVE_SWAP) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
      USE_THEN "rotation" ACCEPT_TAC;
      ASM_REWRITE_TAC[IN_GRAPH_DARTS];
      ASM_REWRITE_TAC[IN_GRAPH_DARTS; SET_RULE `{v:A,u} = {u,v}`];
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_EDGE_DARTS) THEN
      ASM_REWRITE_TAC[PAIR_EQ] THEN MESON_TAC[];
      USE_THEN "consecutive" ACCEPT_TAC;
      USE_THEN "dart" MP_TAC THEN
      REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE]]]);;

let GRAPH_FACE_DELETE_CONSECUTIVE_EDGE_PRESERVES_COFACIAL = prove
 (`!V E r u v a b:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E /\
        graph_face_successor E r (u,v) = (v,u) /\
        a IN graph_darts (E DELETE {u,v}) /\
        b IN graph_darts (E DELETE {u,v}) /\
        b IN graph_face E r a
        ==> b IN
            graph_face
              (E DELETE {u,v}) (graph_delete_rotation r u v) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph rotation edge consecutive a_survives b_survives cofacial" THEN
  ABBREV_TAC
   `p:(A#A)->A#A =
      permutation_delete_two
       (graph_face_successor E (r:(A#A)->A#A)) (u,v) (v,u)` THEN
  SUBGOAL_THEN
   `(p:(A#A)->A#A) permutes graph_darts (E DELETE {u,v})`
  (LABEL_TAC "deleted_permutation") THENL
   [EXPAND_TAC "p" THEN REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE] THEN
    MATCH_MP_TAC PERMUTATION_DELETE_TWO_PERMUTES THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
      USE_THEN "rotation" ACCEPT_TAC;
      ASM_REWRITE_TAC[IN_GRAPH_DARTS];
      ASM_REWRITE_TAC[IN_GRAPH_DARTS; SET_RULE `{v:A,u} = {u,v}`];
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_EDGE_DARTS) THEN
      ASM_REWRITE_TAC[PAIR_EQ] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `b IN permutation_orbit (p:(A#A)->A#A) a`
  (LABEL_TAC "deleted_cofacial") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC(ISPECL
     [`graph_face_successor E (r:(A#A)->A#A)`;
      `graph_darts E:A#A->bool`; `(u:A,v:A)`; `(v:A,u:A)`;
      `a:A#A`; `b:A#A`]
     PERMUTATION_DELETE_TWO_PRESERVES_OLD_ORBIT) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      USE_THEN "graph" ACCEPT_TAC;
      MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
      USE_THEN "rotation" ACCEPT_TAC;
      ASM_REWRITE_TAC[IN_GRAPH_DARTS];
      ASM_REWRITE_TAC[IN_GRAPH_DARTS; SET_RULE `{v:A,u} = {u,v}`];
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_EDGE_DARTS) THEN
      ASM_REWRITE_TAC[PAIR_EQ] THEN MESON_TAC[];
      USE_THEN "a_survives" MP_TAC THEN
      REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE];
      USE_THEN "b_survives" MP_TAC THEN
      REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE];
      USE_THEN "cofacial" MP_TAC THEN
      REWRITE_TAC[GRAPH_FACE_AS_PERMUTATION_ORBIT]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face
      ((E:(A->bool)->bool) DELETE {u,v})
      (graph_delete_rotation (r:(A#A)->A#A) u v) a =
    permutation_orbit (p:(A#A)->A#A) a`
  (LABEL_TAC "same_face") THENL
   [REWRITE_TAC[GRAPH_FACE_AS_PERMUTATION_ORBIT] THEN
    MATCH_MP_TAC PERMUTATION_ORBIT_EQ_IF_AGREE THEN
    X_GEN_TAC `z:A#A` THEN DISCH_THEN(LABEL_TAC "z_orbit") THEN
    SUBGOAL_THEN `z IN graph_darts ((E:(A->bool)->bool) DELETE {u,v})`
    (LABEL_TAC "z_survives") THENL
     [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (MATCH_MP
        (ISPECL
         [`p:(A#A)->A#A`;
          `graph_darts ((E:(A->bool)->bool) DELETE {u,v})`;
          `a:A#A`] PERMUTATION_ORBIT_SUBSET)
        (CONJ
         (ASSUME
          `(p:(A#A)->A#A) permutes
           graph_darts ((E:(A->bool)->bool) DELETE {u,v})`)
         (ASSUME
          `(a:A#A) IN graph_darts
           ((E:(A->bool)->bool) DELETE {u,v})`)))) THEN
      USE_THEN "z_orbit" ACCEPT_TAC;
      EXPAND_TAC "p" THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `u:A`; `v:A`; `z:A#A`]
       GRAPH_FACE_SUCCESSOR_DELETE_CONSECUTIVE_EDGE_AS_DELETE_TWO) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  USE_THEN "same_face" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "deleted_cofacial" ACCEPT_TAC);;

let EULER_PLANAR_ROTATION_DELETE_PENDANT_PRESERVES_COFACIAL = prove
 (`!V E r u v:A. !a b:A#A.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        graph_neighbors E v = {u} /\
        ~(E DELETE {u,v} = {}) /\
        a IN graph_darts (E DELETE {u,v}) /\
        b IN graph_darts (E DELETE {u,v}) /\
        b IN graph_face E r a
        ==> b IN
            graph_face
              (E DELETE {u,v}) (graph_delete_rotation r u v) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected neighbors remainder a_survives b_survives cofacial" THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph rotation formula" THEN
  SUBGOAL_THEN `({u:A,v}:A->bool) IN E` (LABEL_TAC "edge") THENL
   [ONCE_REWRITE_TAC[SET_RULE `{u:A,v} = {v,u}`] THEN
    REWRITE_TAC[GSYM IN_GRAPH_NEIGHBORS] THEN
    ASM_REWRITE_TAC[IN_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A) (u,v) = (v,u)`
  (LABEL_TAC "consecutive") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`] GRAPH_FACE_SUCCESSOR_PENDANT) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `a:A#A`; `b:A#A`]
   GRAPH_FACE_DELETE_CONSECUTIVE_EDGE_PRESERVES_COFACIAL) THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_DARTS_MONO = prove
 (`!E E':(A->bool)->bool.
        E SUBSET E' ==> graph_darts E SUBSET graph_darts E'`,
  REWRITE_TAC[graph_darts; SUBSET; IN_ELIM_THM] THEN MESON_TAC[]);;

let EULER_PLANAR_ROTATION_SUBSET_CONNECTED_PRESERVES_COFACIAL = prove
 (`!V E E' r:(A#A)->A#A. !a b:A#A.
        E SUBSET E' /\
        connected_graph V E /\
        3 <= CARD V /\
        a IN graph_darts E /\
        b IN graph_darts E /\
        euler_planar_rotation V E' r /\
        b IN graph_face E' r a
        ==> ?r':(A#A)->A#A.
              euler_planar_rotation V E r' /\
              b IN graph_face E r' a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "subset connected vertices_large a_base b_base euler cofacial" THEN
  SUBGOAL_THEN `FINITE(E':(A->bool)->bool)`
  (LABEL_TAC "finite_supergraph") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation; finite_simple_graph] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!D:(A->bool)->bool.
        FINITE D
        ==> DISJOINT D E
        ==> !s:(A#A)->A#A.
              euler_planar_rotation V (E UNION D) s /\
              b IN graph_face (E UNION D) s a
              ==> ?s':(A#A)->A#A.
                    euler_planar_rotation V E s' /\
                    b IN graph_face E s' a`
  (LABEL_TAC "delete_surplus") THENL
   [MATCH_MP_TAC FINITE_INDUCT_STRONG THEN CONJ_TAC THENL
     [REWRITE_TAC[DISJOINT_EMPTY; UNION_EMPTY] THEN
      X_GEN_TAC `s:(A#A)->A#A` THEN
      INTRO_TAC "base_euler base_cofacial" THEN
      EXISTS_TAC `s:(A#A)->A#A` THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC
       [`e:A->bool`; `D:(A->bool)->bool`] THEN
      INTRO_TAC "induction fresh finite_D" THEN
      DISCH_THEN(LABEL_TAC "disjoint") THEN
      X_GEN_TAC `s:(A#A)->A#A` THEN
      INTRO_TAC "extended_euler extended_cofacial" THEN
      SUBGOAL_THEN
       `~((e:A->bool) IN E) /\ DISJOINT D E`
      (CONJUNCTS_THEN2 (LABEL_TAC "not_in_base")
        (LABEL_TAC "tail_disjoint")) THENL
       [USE_THEN "disjoint" MP_TAC THEN
        REWRITE_TAC[DISJOINT] THEN SET_TAC[];
        ALL_TAC] THEN
      USE_THEN "extended_euler"
       (MP_TAC o REWRITE_RULE[euler_planar_rotation]) THEN
      INTRO_TAC "extended_graph extended_rotation extended_formula" THEN
      SUBGOAL_THEN
       `(e:A->bool) IN E UNION (e INSERT D)`
      (LABEL_TAC "surplus_edge") THENL
       [SET_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E UNION (e INSERT D):(A->bool)->bool`;
        `e:A->bool`] FINITE_SIMPLE_GRAPH_EDGE) THEN
      ASM_REWRITE_TAC[] THEN
      INTRO_TAC
       "@u v. u_vertex v_vertex distinct edge_pair" THEN
      USE_THEN "edge_pair" SUBST_ALL_TAC THEN
      SUBGOAL_THEN
       `(E UNION ({u:A,v} INSERT D)) DELETE {u,v} = E UNION D`
      (LABEL_TAC "delete_edge") THENL
       [USE_THEN "not_in_base" MP_TAC THEN
        USE_THEN "fresh" MP_TAC THEN SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `connected_graph (V:A->bool) (E UNION D)`
      (LABEL_TAC "intermediate_connected") THENL
       [MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
          `E UNION D:(A->bool)->bool`] CONNECTED_GRAPH_MONO) THEN
        CONJ_TAC THENL
         [USE_THEN "connected" ACCEPT_TAC;
          SET_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(a:A#A) IN graph_darts (E UNION D) /\
        (b:A#A) IN graph_darts (E UNION D)`
      (CONJUNCTS_THEN2 (LABEL_TAC "a_survives")
        (LABEL_TAC "b_survives")) THENL
       [CONJ_TAC THEN
        MATCH_MP_TAC(REWRITE_RULE[SUBSET]
         (MATCH_MP
          (ISPECL
           [`E:(A->bool)->bool`; `E UNION D:(A->bool)->bool`]
           GRAPH_DARTS_MONO)
          (SET_RULE `(E:(A->bool)->bool) SUBSET E UNION D`))) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `euler_planar_rotation
         (V:A->bool) (E UNION D)
         (graph_delete_rotation (s:(A#A)->A#A) u v)`
      (LABEL_TAC "deleted_euler") THENL
       [USE_THEN "delete_edge" (SUBST1_TAC o SYM) THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E UNION ({u:A,v} INSERT D):(A->bool)->bool`;
          `s:(A#A)->A#A`; `u:A`; `v:A`]
         EULER_PLANAR_ROTATION_DELETE_EDGE_CONNECTED) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `b IN graph_face
         (E UNION D)
         (graph_delete_rotation (s:(A#A)->A#A) u v) a`
      (LABEL_TAC "deleted_cofacial") THENL
       [USE_THEN "delete_edge" (SUBST1_TAC o SYM) THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E UNION ({u:A,v} INSERT D):(A->bool)->bool`;
          `s:(A#A)->A#A`; `u:A`; `v:A`; `a:A#A`; `b:A#A`]
         EULER_PLANAR_ROTATION_NONSEPARATING_EDGE_PRESERVES_COFACIAL) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      REMOVE_THEN "induction" (fun induction_th ->
       USE_THEN "tail_disjoint" (fun disjoint_th ->
        MP_TAC(MP induction_th disjoint_th))) THEN
      DISCH_THEN
       (MP_TAC o
        SPEC `graph_delete_rotation (s:(A#A)->A#A) u v`) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE((E' DIFF E):(A->bool)->bool)`
  (LABEL_TAC "finite_surplus") THENL
   [MATCH_MP_TAC FINITE_DIFF THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `DISJOINT ((E' DIFF E):(A->bool)->bool) (E:(A->bool)->bool)`
  (LABEL_TAC "surplus_disjoint") THENL
   [REWRITE_TAC[DISJOINT] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `E UNION (E' DIFF E) = (E':(A->bool)->bool)`
  (LABEL_TAC "recover_supergraph") THENL
   [USE_THEN "subset" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  REMOVE_THEN "delete_surplus" (fun deletion_th ->
   USE_THEN "finite_surplus" (fun finite_th ->
    USE_THEN "surplus_disjoint" (fun disjoint_th ->
     MP_TAC
      (MP
       (MP
        (SPEC `(E' DIFF E):(A->bool)->bool` deletion_th)
        finite_th)
       disjoint_th)))) THEN
  DISCH_THEN(MP_TAC o SPEC `r:(A#A)->A#A`) THEN
  ASM_REWRITE_TAC[]);;

let EULER_PLANAR_ROTATION_RELATIVE_ROOTED_RESTRICT_PRESERVES_COFACIAL =
 prove
 (`!E:(A->bool)->bool. !B:(A->bool)->bool. !W:A->bool.
   !es:(A#A)list. !r:(A#A)->A#A. !a b:A#A.
        finite_simple_graph W B /\
        connected_graph W B /\
        ~(B = {}) /\
        B SUBSET induced_subgraph_edges E W /\
        relative_rooted_edge_list E W es /\
        a IN graph_darts B /\
        b IN graph_darts B /\
        euler_planar_rotation
          (relative_rooted_edge_vertices W es)
          (B UNION rooted_edge_set es) r /\
        b IN graph_face (B UNION rooted_edge_set es) r a
        ==> ?s:(A#A)->A#A.
              euler_planar_rotation W B s /\
              b IN graph_face B s a`,
  REPEAT GEN_TAC THEN
  SPEC_TAC(`r:(A#A)->A#A`,`r:(A#A)->A#A`) THEN
  SPEC_TAC(`es:(A#A)list`,`es:(A#A)list`) THEN
  LIST_INDUCT_TAC THENL
   [REWRITE_TAC[relative_rooted_edge_list;
                relative_rooted_edge_vertices;
                rooted_edge_set; UNION_EMPTY] THEN
    MESON_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "induction") THEN
    MP_TAC(ISPEC `h:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    X_GEN_TAC `r:(A#A)->A#A` THEN
    INTRO_TAC
     "base_graph base_connected base_nonempty base_edges ordered \
      a_base b_base euler cofacial" THEN
    SUBGOAL_THEN
     `relative_rooted_edge_list E W (t:(A#A)list) /\
      ~(x IN relative_rooted_edge_vertices W t) /\
      y IN relative_rooted_edge_vertices W t /\
      {x:A,y} IN E`
    (CONJUNCTS_THEN2 (LABEL_TAC "tail_ordered")
     (CONJUNCTS_THEN2 (LABEL_TAC "new")
      (CONJUNCTS_THEN2 (LABEL_TAC "old") (LABEL_TAC "edge")))) THENL
     [USE_THEN "ordered" MP_TAC THEN
      REWRITE_TAC[relative_rooted_edge_list; FST; SND];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `connected_graph
       (relative_rooted_edge_vertices W (CONS ((x:A),(y:A)) t))
       (B UNION rooted_edge_set (CONS (x,y) t))`
    (LABEL_TAC "current_connected") THENL
     [MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
        `CONS ((x:A),(y:A)) t`]
       CONNECTED_GRAPH_RELATIVE_ROOTED_EDGE_SET) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_neighbors
       (B UNION rooted_edge_set (CONS ((x:A),(y:A)) t)) x = {y}`
    (LABEL_TAC "neighbors") THENL
     [MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
        `x:A`; `y:A`; `t:(A#A)list`]
       RELATIVE_ROOTED_EDGE_LIST_HEAD_NEIGHBORS) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(B UNION rooted_edge_set (CONS ((x:A),(y:A)) t)) DELETE {y,x} =
      B UNION rooted_edge_set t`
    (LABEL_TAC "remainder") THENL
     [ONCE_REWRITE_TAC[SET_RULE `{y:A,x} = {x,y}`] THEN
      MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
        `x:A`; `y:A`; `t:(A#A)list`]
       RELATIVE_ROOTED_EDGE_LIST_HEAD_REMAINDER) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~(B UNION rooted_edge_set (t:(A#A)list) = {})`
    (LABEL_TAC "remainder_nonempty") THENL
     [USE_THEN "base_nonempty" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(a:A#A) IN graph_darts (B UNION rooted_edge_set t) /\
      (b:A#A) IN graph_darts (B UNION rooted_edge_set t)`
    (CONJUNCTS_THEN2 (LABEL_TAC "a_survives")
      (LABEL_TAC "b_survives")) THENL
     [CONJ_TAC THEN
      MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (MATCH_MP
        (ISPECL
         [`B:(A->bool)->bool`;
          `B UNION rooted_edge_set (t:(A#A)list):(A->bool)->bool`]
         GRAPH_DARTS_MONO)
        (SET_RULE
         `(B:(A->bool)->bool) SUBSET B UNION rooted_edge_set t`))) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`relative_rooted_edge_vertices W (CONS ((x:A),(y:A)) t)`;
      `B UNION rooted_edge_set (CONS ((x:A),(y:A)) t)`;
      `r:(A#A)->A#A`; `y:A`; `x:A`]
     EULER_PLANAR_ROTATION_DELETE_PENDANT) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(LABEL_TAC "deleted_euler")] THEN
    MP_TAC(ISPECL
     [`relative_rooted_edge_vertices W (CONS ((x:A),(y:A)) t)`;
      `B UNION rooted_edge_set (CONS ((x:A),(y:A)) t)`;
      `r:(A#A)->A#A`; `y:A`; `x:A`; `a:A#A`; `b:A#A`]
     EULER_PLANAR_ROTATION_DELETE_PENDANT_PRESERVES_COFACIAL) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      USE_THEN "remainder" (fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[];
      DISCH_THEN(LABEL_TAC "deleted_cofacial")] THEN
    SUBGOAL_THEN
     `(relative_rooted_edge_vertices W (CONS ((x:A),(y:A)) t))
       DELETE x =
      relative_rooted_edge_vertices W t`
    (LABEL_TAC "deleted_vertices") THENL
     [REWRITE_TAC[relative_rooted_edge_vertices; FST] THEN
      USE_THEN "new" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `euler_planar_rotation
       (relative_rooted_edge_vertices W t)
       (B UNION rooted_edge_set t)
       (graph_delete_rotation (r:(A#A)->A#A) y x)`
    (LABEL_TAC "tail_euler") THENL
     [USE_THEN "deleted_vertices" (SUBST1_TAC o SYM) THEN
      USE_THEN "remainder" (SUBST1_TAC o SYM) THEN
      USE_THEN "deleted_euler" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `b IN graph_face
       (B UNION rooted_edge_set t)
       (graph_delete_rotation (r:(A#A)->A#A) y x) a`
    (LABEL_TAC "tail_cofacial") THENL
     [USE_THEN "remainder" (SUBST1_TAC o SYM) THEN
      USE_THEN "deleted_cofacial" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "induction"
     (MP_TAC o SPEC `graph_delete_rotation (r:(A#A)->A#A) y x`) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN ACCEPT_TAC]]);;

let EULER_PLANAR_ROTATION_CONNECTED_SUBGRAPH_PRESERVES_COFACIAL = prove
 (`!V E r W B a b.
        euler_planar_rotation (V:A->bool) E r /\
        connected_graph V E /\
        W SUBSET V /\
        ~(W = {}) /\
        3 <= CARD V /\
        B SUBSET induced_subgraph_edges E W /\
        connected_graph W B /\
        a IN graph_darts B /\
        b IN graph_darts B /\
        b IN graph_face E r a
        ==> ?s:(A#A)->A#A.
              euler_planar_rotation W B s /\
              b IN graph_face B s a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected subset nonempty vertices_large edge_subset \
    target_connected a_base b_base cofacial" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(B:(A->bool)->bool = {})`
  (LABEL_TAC "target_nonempty") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "a_base" MP_TAC THEN
    REWRITE_TAC[graph_darts; NOT_IN_EMPTY; IN_ELIM_THM];
    ALL_TAC] THEN
  SUBGOAL_THEN `?u:A. u IN W`
  (X_CHOOSE_THEN `w:A` (LABEL_TAC "root")) THENL
   [USE_THEN "nonempty" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `W:A->bool`; `w:A`]
   CONNECTED_GRAPH_RELATIVE_ROOTED_EDGE_LIST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `es:(A#A)list`
   (CONJUNCTS_THEN2 (LABEL_TAC "ordered")
    (LABEL_TAC "vertices"))) THEN
  SUBGOAL_THEN
   `B UNION rooted_edge_set es SUBSET (E:(A->bool)->bool)`
  (LABEL_TAC "intermediate_subset") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
      `es:(A#A)list`]
     RELATIVE_ROOTED_EDGE_SET_WITH_BASE_SUBSET) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph (V:A->bool) (B UNION rooted_edge_set es)`
  (LABEL_TAC "intermediate_connected") THENL
   [USE_THEN "vertices" (SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
      `es:(A#A)list`]
     CONNECTED_GRAPH_RELATIVE_ROOTED_EDGE_SET) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(a:A#A) IN graph_darts (B UNION rooted_edge_set es) /\
    (b:A#A) IN graph_darts (B UNION rooted_edge_set es)`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_intermediate")
    (LABEL_TAC "b_intermediate")) THENL
   [CONJ_TAC THEN
    MATCH_MP_TAC(REWRITE_RULE[SUBSET]
     (MATCH_MP
      (ISPECL
       [`B:(A->bool)->bool`;
        `B UNION rooted_edge_set (es:(A#A)list):(A->bool)->bool`]
       GRAPH_DARTS_MONO)
      (SET_RULE
       `(B:(A->bool)->bool) SUBSET B UNION rooted_edge_set es`))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `B UNION rooted_edge_set es:(A->bool)->bool`;
    `E:(A->bool)->bool`; `r:(A#A)->A#A`; `a:A#A`; `b:A#A`]
   EULER_PLANAR_ROTATION_SUBSET_CONNECTED_PRESERVES_COFACIAL) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `s:(A#A)->A#A`
     (CONJUNCTS_THEN2 (LABEL_TAC "intermediate_euler")
      (LABEL_TAC "intermediate_cofacial")))] THEN
  SUBGOAL_THEN `finite_simple_graph (W:A->bool) B`
  (LABEL_TAC "target_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_EDGE_SUBSET THEN
    EXISTS_TAC `induced_subgraph_edges E (W:A->bool)` THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `W:A->bool`]
     FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
    `es:(A#A)list`; `s:(A#A)->A#A`; `a:A#A`; `b:A#A`]
   EULER_PLANAR_ROTATION_RELATIVE_ROOTED_RESTRICT_PRESERVES_COFACIAL) THEN
  ASM_REWRITE_TAC[]);;

let EULER_PLANAR_ROTATION_NONSEPARATING_EDGE_PRESERVES_COFACIAL_SET =
 prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
        !u v:A. !a:A#A. !C:(A#A)->bool.
        euler_planar_rotation V E r /\
        {u,v} IN E /\
        connected_graph V (E DELETE {u,v}) /\
        3 <= CARD V /\
        a IN graph_darts (E DELETE {u,v}) /\
        C SUBSET graph_darts (E DELETE {u,v}) /\
        C SUBSET graph_face E r a
        ==> C SUBSET
            graph_face
              (E DELETE {u,v}) (graph_delete_rotation r u v) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler edge connected vertices_large a_survives C_survives cofacial" THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `b:A#A` THEN
  DISCH_THEN(LABEL_TAC "b_C") THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `a:A#A`; `b:A#A`]
   EULER_PLANAR_ROTATION_NONSEPARATING_EDGE_PRESERVES_COFACIAL) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [USE_THEN "C_survives" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]);
    USE_THEN "cofacial" (MATCH_MP_TAC o REWRITE_RULE[SUBSET])] THEN
  USE_THEN "b_C" ACCEPT_TAC);;

let EULER_PLANAR_ROTATION_DELETE_PENDANT_PRESERVES_COFACIAL_SET = prove
 (`!V E r u v:A. !a:A#A. !C:(A#A)->bool.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        graph_neighbors E v = {u} /\
        ~(E DELETE {u,v} = {}) /\
        a IN graph_darts (E DELETE {u,v}) /\
        C SUBSET graph_darts (E DELETE {u,v}) /\
        C SUBSET graph_face E r a
        ==> C SUBSET
            graph_face
              (E DELETE {u,v}) (graph_delete_rotation r u v) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected neighbors remainder a_survives C_survives cofacial" THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `b:A#A` THEN
  DISCH_THEN(LABEL_TAC "b_C") THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `a:A#A`; `b:A#A`]
   EULER_PLANAR_ROTATION_DELETE_PENDANT_PRESERVES_COFACIAL) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [USE_THEN "C_survives" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]);
    USE_THEN "cofacial" (MATCH_MP_TAC o REWRITE_RULE[SUBSET])] THEN
  USE_THEN "b_C" ACCEPT_TAC);;

let EULER_PLANAR_ROTATION_SUBSET_CONNECTED_PRESERVES_COFACIAL_SET = prove
 (`!V:A->bool. !E E':(A->bool)->bool. !r:(A#A)->A#A.
   !a:A#A. !C:(A#A)->bool.
        E SUBSET E' /\ connected_graph V E /\ 3 <= CARD V /\
        a IN graph_darts E /\ C SUBSET graph_darts E /\
        euler_planar_rotation V E' r /\ C SUBSET graph_face E' r a
        ==> ?r':(A#A)->A#A.
              euler_planar_rotation V E r' /\
              C SUBSET graph_face E r' a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "subset connected vertices_large a_base C_base euler cofacial" THEN
  SUBGOAL_THEN `FINITE(E':(A->bool)->bool)`
  (LABEL_TAC "finite_supergraph") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation; finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!D:(A->bool)->bool.
        FINITE D ==> DISJOINT D E ==> !s:(A#A)->A#A.
        euler_planar_rotation V (E UNION D) s /\
        C SUBSET graph_face (E UNION D) s a
        ==> ?s':(A#A)->A#A.
              euler_planar_rotation V E s' /\
              C SUBSET graph_face E s' a`
  (LABEL_TAC "delete_surplus") THENL
   [MATCH_MP_TAC FINITE_INDUCT_STRONG THEN CONJ_TAC THENL
     [REWRITE_TAC[DISJOINT_EMPTY; UNION_EMPTY] THEN
      X_GEN_TAC `s:(A#A)->A#A` THEN
      INTRO_TAC "base_euler base_cofacial" THEN
      EXISTS_TAC `s:(A#A)->A#A` THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`e:A->bool`; `D:(A->bool)->bool`] THEN
      INTRO_TAC "induction fresh finite_D" THEN
      DISCH_THEN(LABEL_TAC "disjoint") THEN
      X_GEN_TAC `s:(A#A)->A#A` THEN
      INTRO_TAC "extended_euler extended_cofacial" THEN
      SUBGOAL_THEN `~((e:A->bool) IN E) /\ DISJOINT D E`
      (CONJUNCTS_THEN2 (LABEL_TAC "not_in_base")
        (LABEL_TAC "tail_disjoint")) THENL
       [USE_THEN "disjoint" MP_TAC THEN
        REWRITE_TAC[DISJOINT] THEN SET_TAC[];
        ALL_TAC] THEN
      USE_THEN "extended_euler"
       (MP_TAC o REWRITE_RULE[euler_planar_rotation]) THEN
      INTRO_TAC "extended_graph extended_rotation extended_formula" THEN
      SUBGOAL_THEN `(e:A->bool) IN E UNION (e INSERT D)`
      (LABEL_TAC "surplus_edge") THENL [SET_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E UNION (e INSERT D):(A->bool)->bool`;
        `e:A->bool`] FINITE_SIMPLE_GRAPH_EDGE) THEN
      ASM_REWRITE_TAC[] THEN
      INTRO_TAC "@u v. u_vertex v_vertex distinct edge_pair" THEN
      USE_THEN "edge_pair" SUBST_ALL_TAC THEN
      SUBGOAL_THEN
       `(E UNION ({u:A,v} INSERT D)) DELETE {u,v} = E UNION D`
      (LABEL_TAC "delete_edge") THENL
       [USE_THEN "not_in_base" MP_TAC THEN
        USE_THEN "fresh" MP_TAC THEN SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `connected_graph (V:A->bool) (E UNION D)`
      (LABEL_TAC "intermediate_connected") THENL
       [MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
          `E UNION D:(A->bool)->bool`] CONNECTED_GRAPH_MONO) THEN
        CONJ_TAC THENL [USE_THEN "connected" ACCEPT_TAC; SET_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN `(a:A#A) IN graph_darts (E UNION D)`
      (LABEL_TAC "a_survives") THENL
       [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
         (MATCH_MP
          (ISPECL [`E:(A->bool)->bool`; `E UNION D:(A->bool)->bool`]
           GRAPH_DARTS_MONO)
          (SET_RULE `(E:(A->bool)->bool) SUBSET E UNION D`))) THEN
        USE_THEN "a_base" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(C:(A#A)->bool) SUBSET
        graph_darts ((E:(A->bool)->bool) UNION D)`
      (LABEL_TAC "C_survives") THENL
       [MATCH_MP_TAC SUBSET_TRANS THEN
        EXISTS_TAC `graph_darts (E:(A->bool)->bool)` THEN
        ASM_REWRITE_TAC[GRAPH_DARTS_MONO] THEN
        MATCH_MP_TAC GRAPH_DARTS_MONO THEN SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `euler_planar_rotation (V:A->bool) (E UNION D)
         (graph_delete_rotation (s:(A#A)->A#A) u v)`
      (LABEL_TAC "deleted_euler") THENL
       [USE_THEN "delete_edge" (SUBST1_TAC o SYM) THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E UNION ({u:A,v} INSERT D):(A->bool)->bool`;
          `s:(A#A)->A#A`; `u:A`; `v:A`]
         EULER_PLANAR_ROTATION_DELETE_EDGE_CONNECTED) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(C:(A#A)->bool) SUBSET graph_face
         (E UNION D) (graph_delete_rotation (s:(A#A)->A#A) u v) a`
      (LABEL_TAC "deleted_cofacial") THENL
       [USE_THEN "delete_edge" (SUBST1_TAC o SYM) THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E UNION ({u:A,v} INSERT D):(A->bool)->bool`;
          `s:(A#A)->A#A`; `u:A`; `v:A`; `a:A#A`; `C:(A#A)->bool`]
         EULER_PLANAR_ROTATION_NONSEPARATING_EDGE_PRESERVES_COFACIAL_SET) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      REMOVE_THEN "induction" (fun induction_th ->
       USE_THEN "tail_disjoint" (fun disjoint_th ->
        MP_TAC(MP induction_th disjoint_th))) THEN
      DISCH_THEN
       (MP_TAC o SPEC `graph_delete_rotation (s:(A#A)->A#A) u v`) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE((E' DIFF E):(A->bool)->bool)`
  (LABEL_TAC "finite_surplus") THENL
   [MATCH_MP_TAC FINITE_DIFF THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `DISJOINT ((E' DIFF E):(A->bool)->bool) (E:(A->bool)->bool)`
  (LABEL_TAC "surplus_disjoint") THENL
   [REWRITE_TAC[DISJOINT] THEN SET_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `E UNION (E' DIFF E) = (E':(A->bool)->bool)`
  (LABEL_TAC "recover_supergraph") THENL
   [USE_THEN "subset" MP_TAC THEN SET_TAC[]; ALL_TAC] THEN
  REMOVE_THEN "delete_surplus" (fun deletion_th ->
   USE_THEN "finite_surplus" (fun finite_th ->
    USE_THEN "surplus_disjoint" (fun disjoint_th ->
     MP_TAC(MP (MP
      (SPEC `(E' DIFF E):(A->bool)->bool` deletion_th)
      finite_th) disjoint_th)))) THEN
  DISCH_THEN(MP_TAC o SPEC `r:(A#A)->A#A`) THEN
  ASM_REWRITE_TAC[]);;

let EULER_PLANAR_ROTATION_RELATIVE_ROOTED_RESTRICT_PRESERVES_COFACIAL_SET =
 prove
 (`!E:(A->bool)->bool. !B:(A->bool)->bool. !W:A->bool.
   !es:(A#A)list. !r:(A#A)->A#A. !a:A#A. !C:(A#A)->bool.
        finite_simple_graph W B /\ connected_graph W B /\ ~(B = {}) /\
        B SUBSET induced_subgraph_edges E W /\
        relative_rooted_edge_list E W es /\
        a IN graph_darts B /\ C SUBSET graph_darts B /\
        euler_planar_rotation
          (relative_rooted_edge_vertices W es)
          (B UNION rooted_edge_set es) r /\
        C SUBSET graph_face (B UNION rooted_edge_set es) r a
        ==> ?s:(A#A)->A#A.
              euler_planar_rotation W B s /\
              C SUBSET graph_face B s a`,
  REPEAT GEN_TAC THEN
  SPEC_TAC(`r:(A#A)->A#A`,`r:(A#A)->A#A`) THEN
  SPEC_TAC(`es:(A#A)list`,`es:(A#A)list`) THEN
  LIST_INDUCT_TAC THENL
   [REWRITE_TAC[relative_rooted_edge_list;
                relative_rooted_edge_vertices;
                rooted_edge_set; UNION_EMPTY] THEN MESON_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "induction") THEN
    MP_TAC(ISPEC `h:A#A` PAIR_SURJECTIVE) THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A`
     (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
    X_GEN_TAC `r:(A#A)->A#A` THEN
    INTRO_TAC
     "base_graph base_connected base_nonempty base_edges ordered \
      a_base C_base euler cofacial" THEN
    SUBGOAL_THEN
     `relative_rooted_edge_list E W (t:(A#A)list) /\
      ~(x IN relative_rooted_edge_vertices W t) /\
      y IN relative_rooted_edge_vertices W t /\ {x:A,y} IN E`
    (CONJUNCTS_THEN2 (LABEL_TAC "tail_ordered")
     (CONJUNCTS_THEN2 (LABEL_TAC "new")
      (CONJUNCTS_THEN2 (LABEL_TAC "old") (LABEL_TAC "edge")))) THENL
     [USE_THEN "ordered" MP_TAC THEN
      REWRITE_TAC[relative_rooted_edge_list; FST; SND];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `connected_graph
       (relative_rooted_edge_vertices W (CONS ((x:A),(y:A)) t))
       (B UNION rooted_edge_set (CONS (x,y) t))`
    (LABEL_TAC "current_connected") THENL
     [MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
        `CONS ((x:A),(y:A)) t`]
       CONNECTED_GRAPH_RELATIVE_ROOTED_EDGE_SET) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_neighbors
       (B UNION rooted_edge_set (CONS ((x:A),(y:A)) t)) x = {y}`
    (LABEL_TAC "neighbors") THENL
     [MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
        `x:A`; `y:A`; `t:(A#A)list`]
       RELATIVE_ROOTED_EDGE_LIST_HEAD_NEIGHBORS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(B UNION rooted_edge_set (CONS ((x:A),(y:A)) t)) DELETE {y,x} =
      B UNION rooted_edge_set t`
    (LABEL_TAC "remainder") THENL
     [ONCE_REWRITE_TAC[SET_RULE `{y:A,x} = {x,y}`] THEN
      MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
        `x:A`; `y:A`; `t:(A#A)list`]
       RELATIVE_ROOTED_EDGE_LIST_HEAD_REMAINDER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `~(B UNION rooted_edge_set (t:(A#A)list) = {})`
    (LABEL_TAC "remainder_nonempty") THENL
     [USE_THEN "base_nonempty" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(a:A#A) IN graph_darts (B UNION rooted_edge_set t)`
    (LABEL_TAC "a_survives") THENL
     [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (MATCH_MP
        (ISPECL
         [`B:(A->bool)->bool`;
          `B UNION rooted_edge_set (t:(A#A)list):(A->bool)->bool`]
         GRAPH_DARTS_MONO)
        (SET_RULE
         `(B:(A->bool)->bool) SUBSET B UNION rooted_edge_set t`))) THEN
      USE_THEN "a_base" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(C:(A#A)->bool) SUBSET
      graph_darts (B UNION rooted_edge_set (t:(A#A)list))`
    (LABEL_TAC "C_survives") THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `graph_darts (B:(A->bool)->bool)` THEN
      CONJ_TAC THENL
       [USE_THEN "C_base" ACCEPT_TAC;
        MATCH_MP_TAC GRAPH_DARTS_MONO THEN SET_TAC[]];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`relative_rooted_edge_vertices W (CONS ((x:A),(y:A)) t)`;
      `B UNION rooted_edge_set (CONS ((x:A),(y:A)) t)`;
      `r:(A#A)->A#A`; `y:A`; `x:A`]
     EULER_PLANAR_ROTATION_DELETE_PENDANT) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(LABEL_TAC "deleted_euler")] THEN
    MP_TAC(ISPECL
     [`relative_rooted_edge_vertices W (CONS ((x:A),(y:A)) t)`;
      `B UNION rooted_edge_set (CONS ((x:A),(y:A)) t)`;
      `r:(A#A)->A#A`; `y:A`; `x:A`; `a:A#A`; `C:(A#A)->bool`]
     EULER_PLANAR_ROTATION_DELETE_PENDANT_PRESERVES_COFACIAL_SET) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      USE_THEN "remainder" (fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[];
      DISCH_THEN(LABEL_TAC "deleted_cofacial")] THEN
    SUBGOAL_THEN
     `(relative_rooted_edge_vertices W (CONS ((x:A),(y:A)) t))
       DELETE x = relative_rooted_edge_vertices W t`
    (LABEL_TAC "deleted_vertices") THENL
     [REWRITE_TAC[relative_rooted_edge_vertices; FST] THEN
      USE_THEN "new" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `euler_planar_rotation
       (relative_rooted_edge_vertices W t)
       (B UNION rooted_edge_set t)
       (graph_delete_rotation (r:(A#A)->A#A) y x)`
    (LABEL_TAC "tail_euler") THENL
     [USE_THEN "deleted_vertices" (SUBST1_TAC o SYM) THEN
      USE_THEN "remainder" (SUBST1_TAC o SYM) THEN
      USE_THEN "deleted_euler" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(C:(A#A)->bool) SUBSET graph_face
       (B UNION rooted_edge_set t)
       (graph_delete_rotation (r:(A#A)->A#A) y x) a`
    (LABEL_TAC "tail_cofacial") THENL
     [USE_THEN "remainder" (SUBST1_TAC o SYM) THEN
      USE_THEN "deleted_cofacial" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "induction"
     (MP_TAC o SPEC `graph_delete_rotation (r:(A#A)->A#A) y x`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let EULER_PLANAR_ROTATION_CONNECTED_SUBGRAPH_PRESERVES_COFACIAL_SET =
 prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !W:A->bool. !B:(A->bool)->bool. !a:A#A. !C:(A#A)->bool.
        euler_planar_rotation V E r /\ connected_graph V E /\
        W SUBSET V /\ ~(W = {}) /\ 3 <= CARD V /\
        B SUBSET induced_subgraph_edges E W /\ connected_graph W B /\
        a IN graph_darts B /\ C SUBSET graph_darts B /\
        C SUBSET graph_face E r a
        ==> ?s:(A#A)->A#A.
              euler_planar_rotation W B s /\
              C SUBSET graph_face B s a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected subset nonempty vertices_large edge_subset \
    target_connected a_base C_base cofacial" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(B:(A->bool)->bool = {})`
  (LABEL_TAC "target_nonempty") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "a_base" MP_TAC THEN
    REWRITE_TAC[graph_darts; NOT_IN_EMPTY; IN_ELIM_THM];
    ALL_TAC] THEN
  SUBGOAL_THEN `?u:A. u IN W`
  (X_CHOOSE_THEN `w:A` (LABEL_TAC "root")) THENL
   [USE_THEN "nonempty" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `W:A->bool`; `w:A`]
   CONNECTED_GRAPH_RELATIVE_ROOTED_EDGE_LIST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `es:(A#A)list`
   (CONJUNCTS_THEN2 (LABEL_TAC "ordered") (LABEL_TAC "vertices"))) THEN
  SUBGOAL_THEN
   `B UNION rooted_edge_set es SUBSET (E:(A->bool)->bool)`
  (LABEL_TAC "intermediate_subset") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
      `es:(A#A)list`] RELATIVE_ROOTED_EDGE_SET_WITH_BASE_SUBSET) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph (V:A->bool) (B UNION rooted_edge_set es)`
  (LABEL_TAC "intermediate_connected") THENL
   [USE_THEN "vertices" (SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
      `es:(A#A)list`] CONNECTED_GRAPH_RELATIVE_ROOTED_EDGE_SET) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:A#A) IN graph_darts (B UNION rooted_edge_set es)`
  (LABEL_TAC "a_intermediate") THENL
   [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
     (MATCH_MP
      (ISPECL
       [`B:(A->bool)->bool`;
        `B UNION rooted_edge_set (es:(A#A)list):(A->bool)->bool`]
       GRAPH_DARTS_MONO)
      (SET_RULE `(B:(A->bool)->bool) SUBSET B UNION rooted_edge_set es`))) THEN
    USE_THEN "a_base" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(C:(A#A)->bool) SUBSET
    graph_darts (B UNION rooted_edge_set (es:(A#A)list))`
  (LABEL_TAC "C_intermediate") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `graph_darts (B:(A->bool)->bool)` THEN
    CONJ_TAC THENL
     [USE_THEN "C_base" ACCEPT_TAC;
      MATCH_MP_TAC GRAPH_DARTS_MONO THEN SET_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `B UNION rooted_edge_set es:(A->bool)->bool`;
    `E:(A->bool)->bool`; `r:(A#A)->A#A`; `a:A#A`; `C:(A#A)->bool`]
   EULER_PLANAR_ROTATION_SUBSET_CONNECTED_PRESERVES_COFACIAL_SET) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `s:(A#A)->A#A`
     (CONJUNCTS_THEN2 (LABEL_TAC "intermediate_euler")
      (LABEL_TAC "intermediate_cofacial")))] THEN
  SUBGOAL_THEN `finite_simple_graph (W:A->bool) B`
  (LABEL_TAC "target_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_EDGE_SUBSET THEN
    EXISTS_TAC `induced_subgraph_edges E (W:A->bool)` THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `W:A->bool`]
     FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `B:(A->bool)->bool`; `W:A->bool`;
    `es:(A#A)list`; `s:(A#A)->A#A`; `a:A#A`; `C:(A#A)->bool`]
   EULER_PLANAR_ROTATION_RELATIVE_ROOTED_RESTRICT_PRESERVES_COFACIAL_SET) THEN
  ASM_REWRITE_TAC[]);;

let EULER_PLANAR_COMPLETE_GRAPH_4_FACE_COUNT = prove
 (`!W:A->bool. !r:(A#A)->A#A.
        W HAS_SIZE 4 /\
        euler_planar_rotation W (complete_graph_edges W) r
        ==> CARD(graph_faces (complete_graph_edges W) r) = 4`,
  REPEAT GEN_TAC THEN INTRO_TAC "size euler" THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph rotation formula" THEN
  SUBGOAL_THEN `FINITE(W:A->bool) /\ CARD(W:A->bool) = 4`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_vertices")
   (LABEL_TAC "four_vertices")) THENL
   [USE_THEN "size" MP_TAC THEN REWRITE_TAC[HAS_SIZE];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(complete_graph_edges (W:A->bool)) = 6`
  (LABEL_TAC "six_edges") THENL
   [MP_TAC(ISPEC `W:A->bool` CARD_COMPLETE_GRAPH_EDGES) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[BINOM] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(complete_graph_edges (W:A->bool) = {})`
  (LABEL_TAC "edges_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "empty") THEN
    USE_THEN "empty" (fun th ->
      USE_THEN "six_edges"
       (MP_TAC o REWRITE_RULE[th; CARD_CLAUSES])) THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  USE_THEN "formula" MP_TAC THEN
  REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let COMPLETE_GRAPH_4_FACE_SUM = prove
 (`!W:A->bool. !r:(A#A)->A#A.
        W HAS_SIZE 4 /\
        graph_rotation (complete_graph_edges W) r
        ==> nsum (graph_faces (complete_graph_edges W) r) CARD = 12`,
  REPEAT GEN_TAC THEN INTRO_TAC "size rotation" THEN
  SUBGOAL_THEN `FINITE(W:A->bool) /\ CARD(W:A->bool) = 4`
