   [USE_THEN "size" MP_TAC THEN REWRITE_TAC[HAS_SIZE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph (W:A->bool) (complete_graph_edges W)`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_COMPLETE_GRAPH THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(complete_graph_edges (W:A->bool)) = 6`
  (LABEL_TAC "six_edges") THENL
   [MP_TAC(ISPEC `W:A->bool` CARD_COMPLETE_GRAPH_EDGES) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[BINOM] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`W:A->bool`; `complete_graph_edges (W:A->bool)`;
    `r:(A#A)->A#A`] FACE_SUM_EQ_TWICE_EDGES) THEN
  ASM_REWRITE_TAC[] THEN ARITH_TAC);;

let NSUM_CARD_4_MINIMUM_3_EQ = prove
 (`!s:A->bool. !f:A->num. !x:A.
        FINITE s /\ CARD s = 4 /\ x IN s /\
        (!y. y IN s ==> 3 <= f y) /\ nsum s f = 12
        ==> f x = 3`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite size x lower total" THEN
  SUBGOAL_THEN `FINITE((s:A->bool) DELETE x)`
  (LABEL_TAC "finite_delete") THENL
   [REWRITE_TAC[FINITE_DELETE] THEN USE_THEN "finite" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD((s:A->bool) DELETE x) = 3`
  (LABEL_TAC "size_delete") THENL
   [MP_TAC(ISPECL [`x:A`; `s:A->bool`] CARD_DELETE) THEN
    ANTS_TAC THENL [USE_THEN "finite" ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "x" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "size" (fun th -> REWRITE_TAC[th]) THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `nsum ((s:A->bool) DELETE x) (\y:A. 3) <=
    nsum (s DELETE x) (f:A->num)`
  (LABEL_TAC "delete_lower") THENL
   [MATCH_MP_TAC NSUM_LE THEN CONJ_TAC THENL
     [USE_THEN "finite_delete" ACCEPT_TAC;
      ALL_TAC] THEN
    X_GEN_TAC `y:A` THEN REWRITE_TAC[IN_DELETE] THEN
    INTRO_TAC "y_member distinct" THEN
    USE_THEN "lower" (MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL
     [USE_THEN "y_member" ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `nsum ((s:A->bool) DELETE x) (\y:A. 3) = 9`
  (LABEL_TAC "constant_sum") THENL
   [MP_TAC(ISPECL [`3`; `(s:A->bool) DELETE x`] NSUM_CONST) THEN
    ANTS_TAC THENL [USE_THEN "finite_delete" ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "size_delete" (fun th -> REWRITE_TAC[th]) THEN
    ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `9 <= nsum ((s:A->bool) DELETE x) (f:A->num)`
  (LABEL_TAC "nine") THENL
   [USE_THEN "constant_sum" (fun th ->
      USE_THEN "delete_lower" (MP_TAC o REWRITE_RULE[th])) THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`f:A->num`; `s:A->bool`; `x:A`] NSUM_DELETE) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "finite" ACCEPT_TAC;
      USE_THEN "x" ACCEPT_TAC];
    DISCH_THEN(LABEL_TAC "split")] THEN
  USE_THEN "lower" (MP_TAC o SPEC `x:A`) THEN
  ANTS_TAC THENL [USE_THEN "x" ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "split" MP_TAC THEN
  USE_THEN "total" MP_TAC THEN
  USE_THEN "nine" MP_TAC THEN ARITH_TAC);;

