let PERMUTES_ITER_EQUAL_IMP_PERIOD = prove
 (`!f:A->A s x i j.
        f permutes s /\ i <= j /\ ITER i f x = ITER j f x
        ==> ITER (j - i) f x = x`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutes ordered equal" THEN
  SUBGOAL_THEN `((j:num) - i) + i = j` (LABEL_TAC "subadd") THENL
   [MATCH_MP_TAC SUB_ADD THEN USE_THEN "ordered" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `j = i + ((j:num) - i)`
  (LABEL_TAC "decomposition") THENL
   [USE_THEN "subadd" (fun th ->
      MATCH_ACCEPT_TAC(GEN_REWRITE_RULE RAND_CONV [ADD_SYM] (SYM th)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `ITER j (f:A->A) x = ITER i f (ITER (j - i) f x)`
  (LABEL_TAC "expand") THENL
   [ONCE_REWRITE_TAC[ITER_ADD] THEN
    USE_THEN "decomposition" (fun th ->
      MATCH_ACCEPT_TAC(BETA_RULE
       (AP_TERM `\n:num. ITER n (f:A->A) x` th)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `ITER i (f:A->A) x = ITER i f (ITER (j - i) f x)`
  (LABEL_TAC "same_image") THENL
   [USE_THEN "equal" (fun eth ->
      USE_THEN "expand" (fun xth -> ACCEPT_TAC(TRANS eth xth)));
    ALL_TAC] THEN
  SUBGOAL_THEN `ITER i (f:A->A) permutes s`
  (LABEL_TAC "iter_permutes") THENL
   [MATCH_MP_TAC PERMUTES_ITER THEN USE_THEN "permutes" ACCEPT_TAC;
    ALL_TAC] THEN
  ONCE_REWRITE_TAC[EQ_SYM_EQ] THEN
  MP_TAC(MATCH_MP
   (ISPECL [`ITER i (f:A->A):A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
   (ASSUME `ITER i (f:A->A) permutes s`)) THEN
  DISCH_THEN(MP_TAC o SPECL [`x:A`; `ITER (j - i) (f:A->A) x`]) THEN
  DISCH_THEN(fun th -> MATCH_MP_TAC(fst(EQ_IMP_RULE th))) THEN
  USE_THEN "same_image" ACCEPT_TAC);;

let ITER_MOD_PERIODIC_POINT = prove
 (`!f:A->A x d n.
        0 < d /\ ITER d f x = x
        ==> ITER n f x = ITER (n MOD d) f x`,
  REPEAT GEN_TAC THEN INTRO_TAC "positive return" THEN
  SUBGOAL_THEN `!k:num. ITER (k * d) (f:A->A) x = x`
  (LABEL_TAC "multiple_return") THENL
   [INDUCT_TAC THENL
     [REWRITE_TAC[MULT_CLAUSES; ITER];
      REWRITE_TAC[MULT_CLAUSES] THEN
      ONCE_REWRITE_TAC[GSYM ITER_ADD] THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `n = n MOD d + (n DIV d) * d`
  (LABEL_TAC "division") THENL
   [MP_TAC(SPECL [`n:num`; `d:num`] DIVISION) THEN
    ANTS_TAC THENL
     [USE_THEN "positive" MP_TAC THEN ARITH_TAC;
      ARITH_TAC];
    ALL_TAC] THEN
  TRANS_TAC EQ_TRANS `ITER (n MOD d + (n DIV d) * d) (f:A->A) x` THEN
  CONJ_TAC THENL
   [USE_THEN "division" (fun th ->
      MATCH_ACCEPT_TAC(BETA_RULE
       (AP_TERM `\m:num. ITER m (f:A->A) x` th)));
    TRANS_TAC EQ_TRANS
     `ITER (n MOD d) (f:A->A)
       (ITER ((n DIV d) * d) f x)` THEN
    CONJ_TAC THENL
     [MATCH_ACCEPT_TAC(SYM(ISPECL
       [`f:A->A`; `n MOD d`; `(n DIV d) * d`; `x:A`] ITER_ADD));
      USE_THEN "multiple_return" (fun th -> REWRITE_TAC[th])]]);;

let FINITE_TRANSITIVE_PERMUTATION_CYCLE = prove
 (`!f:A->A s x.
        FINITE s /\
        f permutes s /\
        x IN s /\
        (!y. y IN s ==> ?n. ITER n f x = y)
        ==> IMAGE (\i. ITER i f x) (cyclic_indices (CARD s)) = s /\
            INJ (\i. ITER i f x) (cyclic_indices (CARD s)) (:A) /\
            ITER (CARD s) f x = x`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutes x transitive" THEN
  SUBGOAL_THEN `!n:num. ITER n (f:A->A) x IN s`
  (LABEL_TAC "iter_in") THENL
   [X_GEN_TAC `n:num` THEN
    MP_TAC(ISPECL [`ITER n (f:A->A):A->A`; `s:A->bool`; `x:A`]
      PERMUTES_IN_IMAGE) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC PERMUTES_ITER THEN USE_THEN "permutes" ACCEPT_TAC;
      DISCH_THEN(MP_TAC o snd o EQ_IMP_RULE) THEN
      DISCH_THEN MATCH_MP_TAC THEN USE_THEN "x" ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`(=):A->A->bool`; `f:A->A`; `x:A`]
    ORDER_EXISTENCE_ITER) THEN
  ANTS_TAC THENL
   [MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `d:num` (LABEL_TAC "periods"))] THEN
  SUBGOAL_THEN `0 < d` (LABEL_TAC "positive") THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`]
      FINITE_PERMUTES_PERIODIC) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "finite" ACCEPT_TAC;
        USE_THEN "permutes" ACCEPT_TAC;
        USE_THEN "x" ACCEPT_TAC];
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `k:num`
     (CONJUNCTS_THEN2 (LABEL_TAC "kpositive")
      (LABEL_TAC "kreturn"))) THEN
    SUBGOAL_THEN `d divides k` (LABEL_TAC "kdivides") THENL
     [USE_THEN "periods" (fun th ->
        MATCH_MP_TAC(fst(EQ_IMP_RULE(SPEC `k:num` th)))) THEN
      USE_THEN "kreturn" ACCEPT_TAC;
      ALL_TAC] THEN
    MATCH_MP_TAC(ARITH_RULE `~((d:num) = 0) ==> 0 < d`) THEN
    DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "kdivides" MP_TAC THEN
    REWRITE_TAC[NUMBER_RULE `0 divides n <=> n = 0`] THEN
    USE_THEN "kpositive" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `ITER d (f:A->A) x = x` (LABEL_TAC "dreturn") THENL
   [USE_THEN "periods" (fun th ->
      MATCH_MP_TAC(snd(EQ_IMP_RULE(SPEC `d:num` th)))) THEN
    MATCH_ACCEPT_TAC DIVIDES_REFL;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!n:num. ITER n (f:A->A) x = ITER (n MOD d) f x`
  (LABEL_TAC "iter_mod") THENL
   [X_GEN_TAC `n:num` THEN
    MATCH_MP_TAC(ISPECL [`f:A->A`; `x:A`; `d:num`; `n:num`]
      ITER_MOD_PERIODIC_POINT) THEN
    CONJ_TAC THENL
     [USE_THEN "positive" ACCEPT_TAC;
      USE_THEN "dreturn" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (\i. ITER i (f:A->A) x) (cyclic_indices d) = s`
  (LABEL_TAC "orbit_image") THENL
   [MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; FORALL_IN_IMAGE] THEN
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      USE_THEN "iter_in" (MATCH_ACCEPT_TAC o SPEC `i:num`);
      REWRITE_TAC[SUBSET] THEN X_GEN_TAC `y:A` THEN
      DISCH_THEN(LABEL_TAC "y_member") THEN
      USE_THEN "transitive" (MP_TAC o SPEC `y:A`) THEN
      ANTS_TAC THENL [USE_THEN "y_member" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "reach")) THEN
      REWRITE_TAC[IN_IMAGE; IN_CYCLIC_INDICES] THEN
      EXISTS_TAC `n MOD d` THEN CONJ_TAC THENL
       [USE_THEN "iter_mod" (MP_TAC o SPEC `n:num`) THEN
        USE_THEN "reach" MP_TAC THEN MESON_TAC[];
        REWRITE_TAC[MOD_LT_EQ_LT] THEN USE_THEN "positive" ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `INJ (\i. ITER i (f:A->A) x) (cyclic_indices d) (:A)`
  (LABEL_TAC "orbit_inj") THENL
   [REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    MATCH_MP_TAC WLOG_LE THEN CONJ_TAC THENL
     [MESON_TAC[];
      ALL_TAC] THEN
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
    DISCH_THEN(LABEL_TAC "ordered") THEN
    INTRO_TAC "ibound jbound equal" THEN
    SUBGOAL_THEN `ITER (j - i) (f:A->A) x = x`
    (LABEL_TAC "difference_return") THENL
     [MATCH_MP_TAC(ISPECL
       [`f:A->A`; `s:A->bool`; `x:A`; `i:num`; `j:num`]
       PERMUTES_ITER_EQUAL_IMP_PERIOD) THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "permutes" ACCEPT_TAC;
        USE_THEN "ordered" ACCEPT_TAC;
        USE_THEN "equal" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `d divides (j - i)`
    (LABEL_TAC "difference_divides") THENL
     [USE_THEN "periods" (fun th ->
        MATCH_MP_TAC(fst(EQ_IMP_RULE(SPEC `j - i:num` th)))) THEN
      USE_THEN "difference_return" ACCEPT_TAC;
      ALL_TAC] THEN
    MATCH_MP_TAC(ARITH_RULE
     `i <= j /\ j < d /\ (d <= j - i \/ j - i = 0) ==> i = j`) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "ordered" ACCEPT_TAC;
      USE_THEN "jbound" ACCEPT_TAC;
      USE_THEN "difference_divides"
       (MATCH_ACCEPT_TAC o MATCH_MP DIVIDES_LE)];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(s:A->bool) = d` (LABEL_TAC "card_eq") THENL
   [USE_THEN "orbit_image" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MP_TAC(ISPECL [`\i:num. ITER i (f:A->A) x`; `d:num`]
      CARD_CYCLIC_VERTICES) THEN
    REWRITE_TAC[cyclic_vertices] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    USE_THEN "orbit_inj" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "card_eq" (fun th -> REWRITE_TAC[th]) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "orbit_image" ACCEPT_TAC;
    USE_THEN "orbit_inj" ACCEPT_TAC;
    USE_THEN "dreturn" ACCEPT_TAC]);;

let OUTGOING_DART_HEADS = prove
 (`!E:(A->bool)->bool. !u:A.
        IMAGE SND (outgoing_darts E u) = graph_neighbors E u`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[EXTENSION; IN_IMAGE; EXISTS_PAIR_THM;
              IN_OUTGOING_DARTS; IN_GRAPH_DARTS;
              IN_GRAPH_NEIGHBORS; FST; SND] THEN
  MESON_TAC[]);;

let CARD_OUTGOING_DARTS = prove
 (`!V E u:A.
        finite_simple_graph V E
        ==> CARD(outgoing_darts E u) = CARD(graph_neighbors E u)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  REWRITE_TAC[GSYM OUTGOING_DART_HEADS] THEN
  MATCH_MP_TAC EQ_SYM THEN MATCH_MP_TAC CARD_IMAGE_INJ THEN
  CONJ_TAC THENL
   [REWRITE_TAC[FORALL_PAIR_THM; IN_OUTGOING_DARTS;
                PAIR_EQ; FST; SND] THEN MESON_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
     FINITE_OUTGOING_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC]);;

let GRAPH_OUTGOING_DART_NEIGHBOR_CARD_POS = prove
 (`!V E u d:A#A.
        finite_simple_graph (V:A->bool) E /\
        d IN outgoing_darts E u
        ==> 0 < CARD(graph_neighbors E u)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph dart" THEN
  SUBGOAL_THEN `FINITE(graph_neighbors (E:(A->bool)->bool) (u:A))`
  (LABEL_TAC "finite") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
     FINITE_GRAPH_NEIGHBORS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(SND(d:A#A)) IN graph_neighbors E u`
  (LABEL_TAC "neighbor") THENL
   [REWRITE_TAC[GSYM OUTGOING_DART_HEADS; IN_IMAGE] THEN
    EXISTS_TAC `d:A#A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(graph_neighbors (E:(A->bool)->bool) (u:A) = {})`
  (LABEL_TAC "nonempty") THENL
   [USE_THEN "neighbor" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(CARD(graph_neighbors (E:(A->bool)->bool) (u:A)) = 0)`
  MP_TAC THENL
   [ASM_SIMP_TAC[CARD_EQ_0];
    ARITH_TAC]);;

let GRAPH_ROTATION_NEIGHBOR_ENUMERATION = prove
 (`!V E r u d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        d IN outgoing_darts E u
        ==> ?w:num->A.
              graph_neighbors E u =
                cyclic_vertices w (CARD(graph_neighbors E u)) /\
              INJ w (cyclic_indices (CARD(graph_neighbors E u))) (:A) /\
              (!i. i IN cyclic_indices (CARD(graph_neighbors E u))
                   ==> ITER i
                        (restricted_permutation r (outgoing_darts E u)) d =
                       (u,w i)) /\
              ITER (CARD(graph_neighbors E u))
                (restricted_permutation r (outgoing_darts E u)) d = d`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation dart" THEN
  ABBREV_TAC
   `f:(A#A)->A#A =
      restricted_permutation r (outgoing_darts E u)` THEN
  MP_TAC(ISPECL
   [`f:(A#A)->A#A`; `outgoing_darts E u:A#A->bool`; `d:A#A`]
   FINITE_TRANSITIVE_PERMUTATION_CYCLE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
       FINITE_OUTGOING_DARTS) THEN
      USE_THEN "graph" ACCEPT_TAC;
      EXPAND_TAC "f" THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `u:A`]
       GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES) THEN
      CONJ_TAC THENL
       [USE_THEN "graph" ACCEPT_TAC;
        USE_THEN "rotation" ACCEPT_TAC];
      USE_THEN "dart" ACCEPT_TAC;
      X_GEN_TAC `d':A#A` THEN DISCH_THEN(LABEL_TAC "d'_outgoing") THEN
      MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `u:A`]
       GRAPH_ROTATION_RESTRICTED_OUTGOING_TRANSITIVE) THEN
      ANTS_TAC THENL
       [USE_THEN "rotation" ACCEPT_TAC;
        ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPECL [`d:A#A`; `d':A#A`]) THEN
      EXPAND_TAC "f" THEN
      ANTS_TAC THENL
       [CONJ_TAC THENL
         [USE_THEN "dart" ACCEPT_TAC;
          USE_THEN "d'_outgoing" ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC]];
    INTRO_TAC "orbit_image orbit_inj return"] THEN
  SUBGOAL_THEN
   `(f:(A#A)->A#A) permutes outgoing_darts E u`
  (LABEL_TAC "f_permutes") THENL
   [EXPAND_TAC "f" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `u:A`]
     GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES) THEN
    CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      USE_THEN "rotation" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i:num. ITER i (f:(A#A)->A#A) d IN outgoing_darts E u`
  (LABEL_TAC "iter_outgoing") THENL
   [X_GEN_TAC `i:num` THEN
    MP_TAC(ISPECL
     [`ITER i (f:(A#A)->A#A):(A#A)->A#A`;
      `outgoing_darts E u:A#A->bool`; `d:A#A`]
     PERMUTES_IN_IMAGE) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC PERMUTES_ITER THEN USE_THEN "f_permutes" ACCEPT_TAC;
      DISCH_THEN(MP_TAC o snd o EQ_IMP_RULE) THEN
      DISCH_THEN MATCH_MP_TAC THEN USE_THEN "dart" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(outgoing_darts (E:(A->bool)->bool) (u:A)) =
    CARD(graph_neighbors E u)`
  (LABEL_TAC "card_eq") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
     CARD_OUTGOING_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  ABBREV_TAC `w:num->A = \i. SND(ITER i (f:(A#A)->A#A) d)` THEN
  EXISTS_TAC `w:num->A` THEN REPEAT CONJ_TAC THENL
   [TRANS_TAC EQ_TRANS
     `IMAGE (SND:A#A->A)
       (outgoing_darts (E:(A->bool)->bool) (u:A))` THEN
    CONJ_TAC THENL
     [MATCH_ACCEPT_TAC(SYM(ISPECL
       [`E:(A->bool)->bool`; `u:A`] OUTGOING_DART_HEADS));
      ALL_TAC] THEN
    EXPAND_TAC "w" THEN REWRITE_TAC[cyclic_vertices] THEN
    SUBGOAL_THEN
     `IMAGE (\i. ITER i (f:(A#A)->A#A) d)
       (cyclic_indices
         (CARD(graph_neighbors (E:(A->bool)->bool) (u:A)))) =
      outgoing_darts E u`
    (LABEL_TAC "neighbor_orbit_image") THENL
     [USE_THEN "card_eq" (fun cth ->
        USE_THEN "orbit_image" (fun oth ->
          MATCH_ACCEPT_TAC(REWRITE_RULE[cth] oth)));
      ALL_TAC] THEN
    USE_THEN "neighbor_orbit_image" (fun th ->
      ONCE_REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[GSYM IMAGE_o; o_DEF];
    SUBGOAL_THEN
     `INJ (\i. ITER i (f:(A#A)->A#A) d)
       (cyclic_indices
         (CARD(graph_neighbors (E:(A->bool)->bool) (u:A))))
       (:A#A)`
    (LABEL_TAC "neighbor_orbit_inj") THENL
     [USE_THEN "card_eq" (fun cth ->
        USE_THEN "orbit_inj" (fun ith ->
          MATCH_ACCEPT_TAC(REWRITE_RULE[cth] ith)));
      ALL_TAC] THEN
    EXPAND_TAC "w" THEN REWRITE_TAC[INJ; IN_UNIV] THEN
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
    INTRO_TAC "i_index j_index heads_equal" THEN
    SUBGOAL_THEN
     `ITER i (f:(A#A)->A#A) d = ITER j f d`
    (LABEL_TAC "darts_equal") THENL
     [USE_THEN "iter_outgoing" (MP_TAC o SPEC `i:num`) THEN
      USE_THEN "iter_outgoing" (MP_TAC o SPEC `j:num`) THEN
      REWRITE_TAC[IN_OUTGOING_DARTS] THEN
      USE_THEN "heads_equal" MP_TAC THEN MESON_TAC[PAIR];
      ALL_TAC] THEN
    USE_THEN "neighbor_orbit_inj" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV] THEN
    DISCH_THEN(MP_TAC o SPECL [`i:num`; `j:num`]) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "i_index" ACCEPT_TAC;
        USE_THEN "j_index" ACCEPT_TAC;
        USE_THEN "darts_equal" ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    EXPAND_TAC "w" THEN BETA_TAC THEN
    USE_THEN "iter_outgoing" (MP_TAC o SPEC `i:num`) THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[PAIR];
    USE_THEN "card_eq" (fun cth ->
      USE_THEN "return" (MATCH_ACCEPT_TAC o REWRITE_RULE[cth]))]);;

let GRAPH_ROTATION_NEIGHBOR_ENUMERATION_PHASED = prove
 (`!V E r u d:A#A.
        finite_simple_graph (V:A->bool) E /\
        graph_rotation E r /\
        d IN outgoing_darts E u
        ==> ?w:num->A.
              graph_neighbors E u =
                cyclic_vertices w (CARD(graph_neighbors E u)) /\
              INJ w (cyclic_indices (CARD(graph_neighbors E u))) (:A) /\
              w 0 = SND d /\
              (2 <= CARD(graph_neighbors E u) ==> w 1 = SND(r d)) /\
              (!i. i IN cyclic_indices (CARD(graph_neighbors E u))
                   ==> ITER i
                        (restricted_permutation r (outgoing_darts E u)) d =
                       (u,w i)) /\
              ITER (CARD(graph_neighbors E u))
                (restricted_permutation r (outgoing_darts E u)) d = d`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation dart" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `d:A#A`]
   GRAPH_ROTATION_NEIGHBOR_ENUMERATION) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@w. neighbors injective iter return" THEN
  SUBGOAL_THEN `0 < CARD(graph_neighbors (E:(A->bool)->bool) (u:A))`
  (LABEL_TAC "positive") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `d:A#A`]
     GRAPH_OUTGOING_DART_NEIGHBOR_CARD_POS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `w:num->A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "neighbors" ACCEPT_TAC;
    USE_THEN "injective" ACCEPT_TAC;
    USE_THEN "iter" (MP_TAC o SPEC `0`) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[IN_CYCLIC_INDICES] THEN
      USE_THEN "positive" ACCEPT_TAC;
      DISCH_THEN(MP_TAC o AP_TERM `SND:A#A->A`) THEN
      REWRITE_TAC[ITER; SND] THEN DISCH_THEN(ACCEPT_TAC o SYM)];
    DISCH_THEN(LABEL_TAC "large") THEN
    USE_THEN "iter" (MP_TAC o SPEC `1`) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
      DISCH_THEN(MP_TAC o AP_TERM `SND:A#A->A`) THEN
      REWRITE_TAC[ITER_1; restricted_permutation] THEN
      USE_THEN "dart" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[SND] THEN DISCH_THEN(ACCEPT_TAC o SYM)];
    USE_THEN "iter" ACCEPT_TAC;
    USE_THEN "return" ACCEPT_TAC]);;

let GRAPH_ROTATION_SUCCESSIVE_HEADS_COFACIAL = prove
 (`!V E r u v w:A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        (u,v) IN outgoing_darts E u /\
        r(u,v) = (u,w)
        ==> v IN graph_rotation_face_vertices E r (v,u) /\
            w IN graph_rotation_face_vertices E r (v,u)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation outgoing step" THEN
  SUBGOAL_THEN `((v:A),u) IN graph_darts E`
  (LABEL_TAC "reverse_dart") THENL
   [MP_TAC(ISPECL [`E:(A->bool)->bool`; `((u:A),v):A#A`]
     GRAPH_DARTS_REVERSE) THEN
    REWRITE_TAC[REVERSE_DART_PAIR] THEN
    DISCH_THEN(MP_TAC o snd o EQ_IMP_RULE) THEN
    DISCH_THEN MATCH_MP_TAC THEN
    USE_THEN "outgoing" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A) (v,u) = (u,w)`
  (LABEL_TAC "face_step") THENL
   [TRANS_TAC EQ_TRANS `(r:(A#A)->A#A) ((u:A),v)` THEN
    CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((v:A),u):A#A`]
       GRAPH_FACE_SUCCESSOR_IN) THEN
      ANTS_TAC THENL
       [USE_THEN "reverse_dart" ACCEPT_TAC;
        REWRITE_TAC[REVERSE_DART_PAIR]];
      USE_THEN "step" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(u:A,w) IN graph_face E r (v,u)`
  (LABEL_TAC "next_in_face") THENL
   [USE_THEN "face_step" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    MATCH_ACCEPT_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((v:A),u):A#A`]
     GRAPH_FACE_SUCCESSOR_IN_FACE);
    ALL_TAC] THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN
     `IMAGE (FST:A#A->A) (graph_face E r ((v:A),u)) =
      graph_rotation_face_vertices E r (v,u)`
    (LABEL_TAC "face_tails") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `((v:A),u):A#A`]
       GRAPH_ROTATION_FACE_TAILS_EQ_VERTICES) THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "graph" ACCEPT_TAC;
        USE_THEN "rotation" ACCEPT_TAC;
        USE_THEN "reverse_dart" ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "face_tails" (fun th -> REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `((v:A),u):A#A` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[FST];
      MATCH_ACCEPT_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((v:A),u):A#A`]
       GRAPH_FACE_REFL)];
    REWRITE_TAC[graph_rotation_face_vertices; IN_IMAGE] THEN
    EXISTS_TAC `((u:A),w):A#A` THEN CONJ_TAC THENL
     [REWRITE_TAC[SND];
      USE_THEN "next_in_face" ACCEPT_TAC]]);;

let MAXIMAL_EULER_PLANAR_ROTATION_NEIGHBOR_CYCLE = prove
 (`!V E r u d:A#A.
        euler_planar_rotation V E r /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\
             E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s) /\
        d IN outgoing_darts E u
        ==> ?w:num->A.
              graph_neighbors E u =
                cyclic_vertices w (CARD(graph_neighbors E u)) /\
              INJ w (cyclic_indices (CARD(graph_neighbors E u))) (:A) /\
              w 0 = SND d /\
              (2 <= CARD(graph_neighbors E u)
               ==> w 1 = SND(r d) /\
                   cyclic_edges w (CARD(graph_neighbors E u)) SUBSET E)`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler maximal dart" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "euler"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[euler_planar_rotation]);
    ALL_TAC] THEN
  SUBGOAL_THEN `graph_rotation E (r:(A#A)->A#A)`
  (LABEL_TAC "rotation") THENL
   [USE_THEN "euler"
     (ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o
      REWRITE_RULE[euler_planar_rotation]);
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `d:A#A`]
   GRAPH_ROTATION_NEIGHBOR_ENUMERATION_PHASED) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      USE_THEN "rotation" ACCEPT_TAC;
      USE_THEN "dart" ACCEPT_TAC];
    INTRO_TAC "@w. neighbors injective start next iter return"] THEN
  EXISTS_TAC `w:num->A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "neighbors" ACCEPT_TAC;
    USE_THEN "injective" ACCEPT_TAC;
    USE_THEN "start" ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "large") THEN
    CONJ_TAC THENL
     [USE_THEN "next" MATCH_MP_TAC THEN
      USE_THEN "large" ACCEPT_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[SUBSET; IN_CYCLIC_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN
    INTRO_TAC "@i. index edge_eq" THEN
    USE_THEN "edge_eq" SUBST1_TAC THEN
    ABBREV_TAC
     `j:num =
        (i + 1) MOD
        CARD(graph_neighbors (E:(A->bool)->bool) (u:A))` THEN
    SUBGOAL_THEN
     `j IN cyclic_indices
       (CARD(graph_neighbors (E:(A->bool)->bool) (u:A)))`
    (LABEL_TAC "j_index") THENL
     [EXPAND_TAC "j" THEN
      REWRITE_TAC[IN_CYCLIC_INDICES; MOD_LT_EQ_LT] THEN
      USE_THEN "large" MP_TAC THEN ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `ITER i
       (restricted_permutation (r:(A#A)->A#A)
         (outgoing_darts (E:(A->bool)->bool) (u:A))) d =
      (u,(w:num->A) i)`
    (LABEL_TAC "current") THENL
     [USE_THEN "iter" (MP_TAC o SPEC `i:num`) THEN
      ANTS_TAC THENL
       [REWRITE_TAC[IN_CYCLIC_INDICES] THEN USE_THEN "index" ACCEPT_TAC;
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `ITER j
       (restricted_permutation (r:(A#A)->A#A)
         (outgoing_darts (E:(A->bool)->bool) (u:A))) d =
      (u,(w:num->A) j)`
    (LABEL_TAC "next") THENL
     [USE_THEN "iter" (MP_TAC o SPEC `j:num`) THEN
      ANTS_TAC THENL
       [USE_THEN "j_index" ACCEPT_TAC;
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `restricted_permutation (r:(A#A)->A#A)
        (outgoing_darts (E:(A->bool)->bool) (u:A))
      permutes outgoing_darts E u`
    (LABEL_TAC "local_permutation") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `u:A`]
       GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES) THEN
      CONJ_TAC THENL
       [USE_THEN "graph" ACCEPT_TAC;
        USE_THEN "rotation" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(u,(w:num->A) i) IN outgoing_darts E u`
    (LABEL_TAC "current_outgoing") THENL
     [USE_THEN "current" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MP_TAC(ISPECL
       [`ITER i
          (restricted_permutation (r:(A#A)->A#A)
            (outgoing_darts E u))`;
        `outgoing_darts (E:(A->bool)->bool) (u:A)`; `d:A#A`]
       PERMUTES_IN_IMAGE) THEN
      ANTS_TAC THENL
       [MATCH_MP_TAC PERMUTES_ITER THEN
        USE_THEN "local_permutation" ACCEPT_TAC;
        DISCH_THEN(MP_TAC o snd o EQ_IMP_RULE) THEN
        DISCH_THEN MATCH_MP_TAC THEN USE_THEN "dart" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `ITER (i + 1)
       (restricted_permutation (r:(A#A)->A#A)
         (outgoing_darts E u)) d =
      ITER j
       (restricted_permutation r (outgoing_darts E u)) d`
    (LABEL_TAC "step_mod") THENL
     [EXPAND_TAC "j" THEN
      MATCH_MP_TAC(ISPECL
       [`restricted_permutation (r:(A#A)->A#A)
          (outgoing_darts E u)`;
        `d:A#A`; `CARD(graph_neighbors (E:(A->bool)->bool) (u:A))`;
        `i + 1:num`]
       ITER_MOD_PERIODIC_POINT) THEN
      CONJ_TAC THENL
       [USE_THEN "large" MP_TAC THEN ARITH_TAC;
        USE_THEN "return" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `restricted_permutation (r:(A#A)->A#A) (outgoing_darts E u)
        (u,(w:num->A) i) = (u,w j)`
    (LABEL_TAC "local_step") THENL
     [TRANS_TAC EQ_TRANS
       `ITER (i + 1)
         (restricted_permutation (r:(A#A)->A#A)
           (outgoing_darts E u)) d` THEN
      CONJ_TAC THENL
       [USE_THEN "current" (fun th ->
          REWRITE_TAC[GSYM ADD1; ITER; th]);
        USE_THEN "step_mod" (fun sth ->
          USE_THEN "next" (fun nth -> ACCEPT_TAC(TRANS sth nth)))];
      ALL_TAC] THEN
    SUBGOAL_THEN `(r:(A#A)->A#A) (u,(w:num->A) i) = (u,w j)`
    (LABEL_TAC "rotation_step") THENL
     [USE_THEN "local_step" MP_TAC THEN
      REWRITE_TAC[restricted_permutation] THEN
      USE_THEN "current_outgoing" (fun th -> REWRITE_TAC[th]);
      ALL_TAC] THEN
    SUBGOAL_THEN `~((j:num) = i)` (LABEL_TAC "distinct_indices") THENL
     [EXPAND_TAC "j" THEN
      MATCH_MP_TAC(ISPECL
       [`CARD(graph_neighbors (E:(A->bool)->bool) (u:A))`; `i:num`]
       CYCLIC_SUCCESSOR_NE) THEN
      CONJ_TAC THENL
       [USE_THEN "large" ACCEPT_TAC;
        USE_THEN "index" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `~((w:num->A) i = w j)` (LABEL_TAC "distinct") THENL
     [DISCH_THEN(LABEL_TAC "same_vertex") THEN
      USE_THEN "injective" MP_TAC THEN
      REWRITE_TAC[INJ; IN_UNIV] THEN
      DISCH_THEN(MP_TAC o SPECL [`i:num`; `j:num`]) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [REWRITE_TAC[IN_CYCLIC_INDICES] THEN
          USE_THEN "index" ACCEPT_TAC;
          USE_THEN "j_index" ACCEPT_TAC;
          USE_THEN "same_vertex" ACCEPT_TAC];
        DISCH_THEN(LABEL_TAC "same_index") THEN
        USE_THEN "distinct_indices" MP_TAC THEN
        USE_THEN "same_index" MP_TAC THEN MESON_TAC[]];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `(w:num->A) i`; `(w:num->A) j`]
     GRAPH_ROTATION_SUCCESSIVE_HEADS_COFACIAL) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "graph" ACCEPT_TAC;
        USE_THEN "rotation" ACCEPT_TAC;
        USE_THEN "current_outgoing" ACCEPT_TAC;
        USE_THEN "rotation_step" ACCEPT_TAC];
      INTRO_TAC "current_face_vertex next_face_vertex"] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `(((w:num->A) i,(u:A)):A#A)`]
     MAXIMAL_EULER_PLANAR_ROTATION_FACE_VERTICES_CLIQUE) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "euler" ACCEPT_TAC;
        USE_THEN "maximal" ACCEPT_TAC;
        USE_THEN "current_outgoing" MP_TAC THEN
        REWRITE_TAC[IN_OUTGOING_DARTS] THEN
        DISCH_THEN(LABEL_TAC "current_dart") THEN
        MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `((u:A),(w:num->A) i):A#A`]
         GRAPH_DARTS_REVERSE) THEN
        ASM_REWRITE_TAC[REVERSE_DART_PAIR]];
      DISCH_THEN(MP_TAC o SPECL [`(w:num->A) i`; `(w:num->A) j`])] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "current_face_vertex" ACCEPT_TAC;
      USE_THEN "next_face_vertex" ACCEPT_TAC;
      USE_THEN "distinct" ACCEPT_TAC]]);;

let MAXIMAL_EULER_PLANAR_ROTATION_NONEMPTY_NEIGHBOR_CYCLE = prove
 (`!V E r u:A.
        euler_planar_rotation V E r /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\
             E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s) /\
        ~(graph_neighbors E u = {})
        ==> ?w:num->A.
              graph_neighbors E u =
                cyclic_vertices w (CARD(graph_neighbors E u)) /\
              INJ w (cyclic_indices (CARD(graph_neighbors E u))) (:A) /\
              (2 <= CARD(graph_neighbors E u)
               ==> cyclic_edges w (CARD(graph_neighbors E u)) SUBSET E)`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler maximal nonempty" THEN
  SUBGOAL_THEN `?v:A. v IN graph_neighbors E u`
  (X_CHOOSE_THEN `v:A` (LABEL_TAC "neighbor")) THENL
   [USE_THEN "nonempty" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `((u:A),v):A#A`]
   MAXIMAL_EULER_PLANAR_ROTATION_NEIGHBOR_CYCLE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[IN_OUTGOING_DARTS; IN_GRAPH_DARTS; FST] THEN
    USE_THEN "neighbor" MP_TAC THEN REWRITE_TAC[IN_GRAPH_NEIGHBORS];
    INTRO_TAC "@w. neighbors injective start cycle"] THEN
  EXISTS_TAC `w:num->A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "neighbors" ACCEPT_TAC;
    USE_THEN "injective" ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "large") THEN
    USE_THEN "cycle" MP_TAC THEN
    ANTS_TAC THENL
     [USE_THEN "large" ACCEPT_TAC;
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC)]]);;

let BOUNDARY_EULER_ROTATION_LAST_ROTATION_STEP = prove
 (`!V E q n r.
        simple_graph_cycle (E:(A->bool)->bool) (q:num->A) n /\
        boundary_euler_rotation V E q n r
        ==> r(q(n - 1),q(n - 2)) = (q(n - 1),q 0)`,
  REPEAT GEN_TAC THEN INTRO_TAC "cycle boundary" THEN
  USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "nlarge injective edges" THEN
  SUBGOAL_THEN
   `cyclic_face_successors (E:(A->bool)->bool) r (q:num->A) n`
  (LABEL_TAC "successors") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `r:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_IMP_CYCLIC_FACE_SUCCESSORS) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(n - 2) + 1 = n - 1` (LABEL_TAC "penult") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(n - 1) + 1 = n` (LABEL_TAC "last") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(n - 1) MOD n = n - 1`
  (LABEL_TAC "penult_mod") THENL
   [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `n MOD n = 0` (LABEL_TAC "last_mod") THENL
   [REWRITE_TAC[MOD_REFL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n (n - 2) IN graph_darts E`
  (LABEL_TAC "dart") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DART THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "successors" MP_TAC THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  DISCH_THEN(MP_TAC o SPEC `n - 2:num`) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    ASM_REWRITE_TAC[cyclic_dart; GRAPH_FACE_SUCCESSOR_IN;
                    REVERSE_DART_PAIR]] THEN
  DISCH_THEN(LABEL_TAC "face_step") THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
     `cyclic_dart (q:num->A) n (n - 2)`]
    GRAPH_FACE_SUCCESSOR_IN)
   (ASSUME
    `cyclic_dart (q:num->A) n (n - 2) IN graph_darts E`)) THEN
  ASM_REWRITE_TAC[cyclic_dart; REVERSE_DART_PAIR] THEN
  USE_THEN "face_step" MP_TAC THEN MESON_TAC[]);;

let SIMPLE_GRAPH_CYCLE_LAST_BOUNDARY_DATA = prove
 (`!E q n.
        simple_graph_cycle (E:(A->bool)->bool) (q:num->A) n
        ==> 3 <= n /\
            ~(q(n - 2) = q 0) /\
            (q(n - 1),q(n - 2)) IN outgoing_darts E (q(n - 1)) /\
            q 0 IN graph_neighbors E (q(n - 1))`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "cycle") THEN
  SUBGOAL_THEN `3 <= n` (LABEL_TAC "nlarge") THENL
   [USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "nlarge" ACCEPT_TAC;
    USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
    INTRO_TAC "_ injective _" THEN
    DISCH_THEN(LABEL_TAC "same") THEN
    USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    DISCH_THEN(MP_TAC o SPECL [`n - 2:num`; `0`]) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    REWRITE_TAC[IN_OUTGOING_DARTS_PAIR] THEN
    ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
    SUBGOAL_THEN `(n - 2) + 1 = n - 1`
    (LABEL_TAC "penult") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `n - 2:num`]
     SIMPLE_GRAPH_CYCLE_CONSECUTIVE_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_ARITH_TAC;
    REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
    MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CLOSING_EDGE THEN
    USE_THEN "cycle" ACCEPT_TAC]);;

let FINITE_GRAPH_TWO_DISTINCT_NEIGHBORS_CARD = prove
 (`!V E u a b:A.
        finite_simple_graph V E /\
        a IN graph_neighbors E u /\
        b IN graph_neighbors E u /\
        ~(a = b)
        ==> 2 <= CARD(graph_neighbors E u)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph a_neighbor b_neighbor distinct" THEN
  SUBGOAL_THEN `FINITE(graph_neighbors (E:(A->bool)->bool) (u:A))`
  (LABEL_TAC "finite") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
     FINITE_GRAPH_NEIGHBORS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `{a:A,b} SUBSET graph_neighbors E u`
  (LABEL_TAC "pair_subset") THENL
   [REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`{a:A,b}`; `graph_neighbors (E:(A->bool)->bool) (u:A)`]
   CARD_SUBSET) THEN
  ASM_REWRITE_TAC[] THEN
  ASM_SIMP_TAC[CARD_CLAUSES; FINITE_INSERT; FINITE_SING;
               CARD_SING; IN_SING] THEN
  ARITH_TAC);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_LAST_NEIGHBOR_CYCLE = prove
 (`!V E r q n.
        boundary_euler_rotation (V:A->bool) E (q:num->A) n r /\
        simple_graph_cycle E q n /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\
             E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s)
        ==> ?k w.
              CARD(graph_neighbors E (q(n - 1))) = k + 2 /\
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = q(n - 2) /\
              w(k + 1) = q 0 /\
              cyclic_edges w (k + 2) SUBSET E`,
  REPEAT GEN_TAC THEN INTRO_TAC "boundary cycle maximal" THEN
  SUBGOAL_THEN `euler_planar_rotation (V:A->bool) E r`
  (LABEL_TAC "euler") THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `q:num->A`; `n:num`]
   SIMPLE_GRAPH_CYCLE_LAST_BOUNDARY_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "nlarge endpoints_distinct start_dart right_neighbor" THEN
  SUBGOAL_THEN
   `(q:num->A)(n - 2) IN graph_neighbors E (q(n - 1))`
  (LABEL_TAC "left_neighbor") THENL
   [USE_THEN "start_dart" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS_PAIR; IN_GRAPH_NEIGHBORS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `2 <= CARD(graph_neighbors (E:(A->bool)->bool) (q(n - 1)))`
  (LABEL_TAC "degree_large") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `(q:num->A)(n - 1)`;
      `(q:num->A)(n - 2)`; `(q:num->A) 0`]
     FINITE_GRAPH_TWO_DISTINCT_NEIGHBORS_CARD) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) (q(n - 1),q(n - 2)) = (q(n - 1),q 0)`
  (LABEL_TAC "rotation_step") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `r:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_LAST_ROTATION_STEP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `(q:num->A)(n - 1)`; `((q(n - 1),q(n - 2)):A#A)`]
   MAXIMAL_EULER_PLANAR_ROTATION_NEIGHBOR_CYCLE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC "@z. neighbors injective first phased"] THEN
  ABBREV_TAC
   `m = CARD(graph_neighbors
          (E:(A->bool)->bool) ((q:num->A)(n - 1)))` THEN
  POP_ASSUM(LABEL_TAC "m_definition") THEN
  SUBGOAL_THEN `(z:num->A) 0 = q(n - 2)` (LABEL_TAC "z_first") THENL
   [USE_THEN "first" MP_TAC THEN REWRITE_TAC[SND];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(z:num->A) 1 = q 0 /\ cyclic_edges z m SUBSET E`
  (CONJUNCTS_THEN2 (LABEL_TAC "z_second") (LABEL_TAC "z_edges")) THENL
   [MP_TAC(MATCH_MP
     (ASSUME
      `2 <= m
       ==> (z:num->A) 1 =
           SND((r:(A#A)->A#A) (q(n - 1),q(n - 2))) /\
           cyclic_edges z m SUBSET E`)
     (ASSUME `2 <= m`)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `h:num->A = \i. (z:num->A) ((i + 1) MOD m)` THEN
  POP_ASSUM(LABEL_TAC "h_definition") THEN
  SUBGOAL_THEN
   `graph_neighbors (E:(A->bool)->bool) (q(n - 1)) =
    cyclic_vertices h m`
  (LABEL_TAC "h_neighbors") THENL
   [USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[CYCLIC_VERTICES_OFFSET];
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (h:num->A) (cyclic_indices m) (:A)`
  (LABEL_TAC "h_injective") THENL
   [USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC INJ_CYCLIC_OFFSET THEN
    USE_THEN "injective" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `cyclic_edges (h:num->A) m SUBSET E`
  (LABEL_TAC "h_edges") THENL
   [USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[CYCLIC_EDGES_OFFSET] THEN
    USE_THEN "z_edges" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(h:num->A) 0 = q 0` (LABEL_TAC "h_first") THENL
   [USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    BETA_TAC THEN
    SUBGOAL_THEN `(0 + 1) MOD m = 1` SUBST1_TAC THENL
     [REWRITE_TAC[ADD_CLAUSES] THEN MATCH_MP_TAC MOD_LT THEN
      USE_THEN "degree_large" MP_TAC THEN ARITH_TAC;
      USE_THEN "z_second" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(h:num->A) (m - 1) = q(n - 2)`
  (LABEL_TAC "h_last") THENL
   [USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    BETA_TAC THEN
    SUBGOAL_THEN `(m - 1) + 1 = m` SUBST1_TAC THENL
     [USE_THEN "degree_large" MP_TAC THEN ARITH_TAC;
      REWRITE_TAC[MOD_REFL] THEN USE_THEN "z_first" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i + 1 < m ==> {(h:num->A) i,h(i + 1)} IN E`
  (LABEL_TAC "h_chain") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "within") THEN
    USE_THEN "h_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_EDGES] THEN EXISTS_TAC `i:num` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[IN_CYCLIC_INDICES] THEN
      USE_THEN "within" MP_TAC THEN ARITH_TAC;
      SUBGOAL_THEN `(i + 1) MOD m = i + 1` SUBST1_TAC THENL
       [MATCH_MP_TAC MOD_LT THEN USE_THEN "within" ACCEPT_TAC;
        REFL_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{(h:num->A) 0,h(m - 1)} = {q(n - 2),q 0}`
  (LABEL_TAC "h_endpoints") THENL
   [ASM_REWRITE_TAC[PAIR_SET_SYM];
    ALL_TAC] THEN
  SUBGOAL_THEN `{q(n - 2),q 0} IN (E:(A->bool)->bool)`
  (LABEL_TAC "endpoint_edge") THENL
   [USE_THEN "z_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_EDGES] THEN EXISTS_TAC `0` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[IN_CYCLIC_INDICES] THEN
      USE_THEN "degree_large" MP_TAC THEN ARITH_TAC;
      SUBGOAL_THEN `(0 + 1) MOD m = 1` SUBST1_TAC THENL
       [REWRITE_TAC[ADD_CLAUSES] THEN MATCH_MP_TAC MOD_LT THEN
        USE_THEN "degree_large" MP_TAC THEN ARITH_TAC;
        ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `(q:num->A)(n - 1)`;
    `h:num->A`; `m:num`; `(q:num->A)(n - 2)`; `(q:num->A) 0`]
   CYCLIC_CHAIN_ENDPOINT_PAIR_TO_NEIGHBOR_PATH) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "degree_large" ACCEPT_TAC;
      USE_THEN "h_neighbors" ACCEPT_TAC;
      USE_THEN "h_injective" ACCEPT_TAC;
      USE_THEN "h_endpoints" ACCEPT_TAC;
      USE_THEN "endpoints_distinct" ACCEPT_TAC;
      USE_THEN "h_chain" ACCEPT_TAC];
    INTRO_TAC
     "@k w. length w_neighbors w_injective w_first w_last w_chain"] THEN
  MAP_EVERY EXISTS_TAC [`k:num`; `w:num->A`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "length" ACCEPT_TAC;
    USE_THEN "w_neighbors" ACCEPT_TAC;
    USE_THEN "w_injective" ACCEPT_TAC;
    USE_THEN "w_first" ACCEPT_TAC;
    USE_THEN "w_last" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `w:num->A`; `k + 2:num`]
     CYCLIC_EDGES_SUBSET_OF_CHAIN_AND_LAST) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "length" (fun th -> REWRITE_TAC[GSYM th]) THEN
      USE_THEN "degree_large" ACCEPT_TAC;
      USE_THEN "w_chain" ACCEPT_TAC;
      ASM_REWRITE_TAC[ARITH_RULE `(k + 2) - 1 = k + 1`;
                      PAIR_SET_SYM]]]);;

let CYCLIC_GRAPH_CONNECTED = prove
 (`!w:num->A. !m.
        0 < m
        ==> connected_graph (cyclic_vertices w m) (cyclic_edges w m)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "positive") THEN
  SUBGOAL_THEN
   `!i. i < m
        ==> graph_reachable (cyclic_edges (w:num->A) m) (w 0) (w i)`
  (LABEL_TAC "reachable") THENL
   [INDUCT_TAC THENL
     [DISCH_TAC THEN MATCH_ACCEPT_TAC GRAPH_REACHABLE_REFL;
      DISCH_THEN(LABEL_TAC "index") THEN
      MATCH_MP_TAC(ISPECL
       [`cyclic_edges (w:num->A) m`; `(w:num->A) 0`; `(w:num->A) i`;
        `(w:num->A) (SUC i)`]
       GRAPH_REACHABLE_TRANS) THEN
      CONJ_TAC THENL
       [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC;
        REWRITE_TAC[graph_reachable] THEN
        MATCH_MP_TAC(CONJUNCT1(SPEC
         `(\(x:A) (y:A). {x,y} IN cyclic_edges (w:num->A) m)`
         RTC_RULES)) THEN
        REWRITE_TAC[IN_CYCLIC_EDGES] THEN EXISTS_TAC `i:num` THEN
        CONJ_TAC THENL
         [REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
          SUBGOAL_THEN `(i + 1) MOD m = i + 1` SUBST1_TAC THENL
           [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
            REWRITE_TAC[ADD1]]]]];
    ALL_TAC] THEN
  REWRITE_TAC[connected_graph] THEN
  MAP_EVERY X_GEN_TAC [`u:A`; `v:A`] THEN
  REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
  INTRO_TAC "(@i. i_index u_value) (@j. j_index v_value)" THEN
  USE_THEN "u_value" SUBST1_TAC THEN
  USE_THEN "v_value" SUBST1_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`cyclic_edges (w:num->A) m`; `(w:num->A) i`; `(w:num->A) 0`;
    `(w:num->A) j`]
   GRAPH_REACHABLE_TRANS) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
    USE_THEN "reachable" MATCH_MP_TAC THEN
    USE_THEN "i_index" ACCEPT_TAC;
    USE_THEN "reachable" MATCH_MP_TAC THEN
    USE_THEN "j_index" ACCEPT_TAC]);;

let CONNECTED_GRAPH_DELETE_VERTEX_OF_CONNECTED_NEIGHBORS = prove
 (`!V E v a:A.
        finite_simple_graph V E /\
        connected_graph V E /\
        v IN V /\
        a IN graph_neighbors E v /\
        (!u. u IN graph_neighbors E v
             ==> graph_reachable
                  (induced_subgraph_edges E (V DELETE v)) a u)
        ==> connected_graph (V DELETE v)
             (induced_subgraph_edges E (V DELETE v))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph connected vertex root_neighbor neighbors_reachable" THEN
  ABBREV_TAC `W:A->bool = V DELETE v` THEN
  POP_ASSUM(LABEL_TAC "W_definition") THEN
  ABBREV_TAC `B:(A->bool)->bool = induced_subgraph_edges E W` THEN
  POP_ASSUM(LABEL_TAC "B_definition") THEN
  SUBGOAL_THEN `finite_simple_graph (W:A->bool) B`
  (LABEL_TAC "deleted_graph") THENL
   [USE_THEN "B_definition" (SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `W:A->bool`]
     FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "W_definition"
     (fun th -> REWRITE_TAC[GSYM th; DELETE_SUBSET]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:A) IN W` (LABEL_TAC "root") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `a:A`]
     FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "W_definition"
     (fun th -> REWRITE_TAC[GSYM th; IN_DELETE]) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x:A. x IN W ==> graph_reachable B x a`
  (LABEL_TAC "reaches_root") THENL
   [X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "x_vertex") THEN
    ABBREV_TAC `C:A->bool = graph_component B x` THEN
    POP_ASSUM(LABEL_TAC "C_definition") THEN
    SUBGOAL_THEN `(C:A->bool) SUBSET W` (LABEL_TAC "C_subset") THENL
     [USE_THEN "C_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC(ISPECL
       [`W:A->bool`; `B:(A->bool)->bool`; `x:A`]
       GRAPH_COMPONENT_SUBSET) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(x:A) IN C` (LABEL_TAC "x_in_C") THENL
     [USE_THEN "C_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_ACCEPT_TAC GRAPH_COMPONENT_REFL;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((C:A->bool) = V)` (LABEL_TAC "C_proper") THENL
     [DISCH_THEN(LABEL_TAC "C_all") THEN
      USE_THEN "C_subset" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
      DISCH_THEN(MP_TAC o SPEC `v:A`) THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "W_definition"
       (fun th -> REWRITE_TAC[GSYM th; IN_DELETE]);
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `C:A->bool`; `x:A`]
     CONNECTED_GRAPH_CROSSING_EDGE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `W:A->bool` THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "W_definition"
       (fun th -> REWRITE_TAC[GSYM th; DELETE_SUBSET]);
      INTRO_TAC "@p y. p_outside y_in_C crossing"] THEN
    SUBGOAL_THEN `(p:A) = v` (LABEL_TAC "p_is_v") THENL
     [ASM_CASES_TAC `(p:A) = v` THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(p:A) IN W` (LABEL_TAC "p_in_W") THENL
       [USE_THEN "p_outside" MP_TAC THEN REWRITE_TAC[IN_DIFF] THEN
        USE_THEN "W_definition"
         (fun th -> REWRITE_TAC[GSYM th; IN_DELETE]) THEN
        ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `({p:A,y}:A->bool) IN B`
      (LABEL_TAC "deleted_edge") THENL
       [USE_THEN "B_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
        REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
        CONJ_TAC THENL
         [USE_THEN "crossing" ACCEPT_TAC;
          REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
          CONJ_TAC THENL
           [USE_THEN "p_in_W" ACCEPT_TAC;
            USE_THEN "C_subset"
             (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
            USE_THEN "y_in_C" ACCEPT_TAC]];
        ALL_TAC] THEN
      SUBGOAL_THEN `(p:A) IN C` (LABEL_TAC "p_in_C") THENL
       [USE_THEN "C_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
        MATCH_MP_TAC(ISPECL
         [`B:(A->bool)->bool`; `x:A`; `y:A`; `p:A`]
         GRAPH_COMPONENT_CLOSED) THEN
        CONJ_TAC THENL
         [USE_THEN "C_definition" (fun th -> REWRITE_TAC[th]) THEN
          USE_THEN "y_in_C" ACCEPT_TAC;
          ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
          USE_THEN "deleted_edge" ACCEPT_TAC];
        USE_THEN "p_outside" MP_TAC THEN REWRITE_TAC[IN_DIFF] THEN
        ASM_MESON_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `(y:A) IN graph_neighbors E v`
    (LABEL_TAC "y_neighbor") THENL
     [REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
      USE_THEN "p_is_v" (SUBST1_TAC o SYM) THEN
      USE_THEN "crossing" ACCEPT_TAC;
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`B:(A->bool)->bool`; `x:A`; `y:A`; `a:A`]
     GRAPH_REACHABLE_TRANS) THEN
    CONJ_TAC THENL
     [REWRITE_TAC[GSYM IN_GRAPH_COMPONENT] THEN
      USE_THEN "C_definition" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "y_in_C" ACCEPT_TAC;
      MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
      USE_THEN "neighbors_reachable" MATCH_MP_TAC THEN
      USE_THEN "y_neighbor" ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[connected_graph] THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
  INTRO_TAC "x_vertex y_vertex" THEN
  MATCH_MP_TAC(ISPECL
   [`B:(A->bool)->bool`; `x:A`; `a:A`; `y:A`]
   GRAPH_REACHABLE_TRANS) THEN
  CONJ_TAC THENL
   [USE_THEN "reaches_root" MATCH_MP_TAC THEN
    USE_THEN "x_vertex" ACCEPT_TAC;
    MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
    USE_THEN "reaches_root" MATCH_MP_TAC THEN
    USE_THEN "y_vertex" ACCEPT_TAC]);;

let CONNECTED_GRAPH_DELETE_VERTEX_OF_CYCLIC_NEIGHBORS = prove
 (`!V E v w m.
        finite_simple_graph (V:A->bool) E /\
        connected_graph V E /\
        v IN V /\
        graph_neighbors E v = cyclic_vertices (w:num->A) m /\
        0 < m /\
        cyclic_edges w m SUBSET E
        ==> connected_graph (V DELETE v)
             (induced_subgraph_edges E (V DELETE v))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph connected vertex neighbors positive cycle_edges" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `(w:num->A) 0`]
   CONNECTED_GRAPH_DELETE_VERTEX_OF_CONNECTED_NEIGHBORS) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    USE_THEN "connected" ACCEPT_TAC;
    USE_THEN "vertex" ACCEPT_TAC;
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN EXISTS_TAC `0` THEN
    REWRITE_TAC[IN_CYCLIC_INDICES] THEN
    USE_THEN "positive" ACCEPT_TAC;
    X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "u_neighbor") THEN
    SUBGOAL_THEN `u IN cyclic_vertices (w:num->A) m`
    (LABEL_TAC "u_cycle") THENL
     [USE_THEN "neighbors" (fun th -> REWRITE_TAC[GSYM th]) THEN
      USE_THEN "u_neighbor" ACCEPT_TAC;
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`cyclic_edges (w:num->A) m`;
      `induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v)`;
      `(w:num->A) 0`; `u:A`]
     GRAPH_REACHABLE_MONO) THEN
    CONJ_TAC THENL
     [REWRITE_TAC[SUBSET] THEN X_GEN_TAC `e:A->bool` THEN
      DISCH_THEN(LABEL_TAC "cycle_edge") THEN
      REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
      CONJ_TAC THENL
       [USE_THEN "cycle_edges"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "cycle_edge" ACCEPT_TAC;
        MATCH_MP_TAC SUBSET_TRANS THEN
        EXISTS_TAC `cyclic_vertices (w:num->A) m` THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC CYCLIC_EDGE_SUBSET_VERTICES THEN
          ASM_REWRITE_TAC[];
          USE_THEN "neighbors" (fun th -> REWRITE_TAC[GSYM th]) THEN
          MATCH_MP_TAC GRAPH_NEIGHBORS_SUBSET_DELETE THEN
          ASM_REWRITE_TAC[]]];
      MP_TAC(ISPECL [`w:num->A`; `m:num`] CYCLIC_GRAPH_CONNECTED) THEN
      ASM_REWRITE_TAC[connected_graph] THEN
      DISCH_THEN(MP_TAC o SPECL [`(w:num->A) 0`; `u:A`]) THEN
      ANTS_TAC THENL
       [CONJ_TAC THENL
         [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN EXISTS_TAC `0` THEN
          REWRITE_TAC[IN_CYCLIC_INDICES] THEN
          USE_THEN "positive" ACCEPT_TAC;
          USE_THEN "u_cycle" ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC]]]);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_DELETE_LAST = prove
 (`!V E r q n.
        boundary_euler_rotation (V:A->bool) E (q:num->A) n r /\
        simple_graph_cycle E q n /\
        connected_graph V E /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\
             E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s)
        ==> ?k w s.
              CARD(graph_neighbors E (q(n - 1))) = k + 2 /\
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = q(n - 2) /\
              w(k + 1) = q 0 /\
              cyclic_edges w (k + 2) SUBSET E /\
              euler_planar_rotation
               (V DELETE q(n - 1))
               (induced_subgraph_edges E (V DELETE q(n - 1))) s`,
  REPEAT GEN_TAC THEN INTRO_TAC "boundary cycle connected maximal" THEN
  SUBGOAL_THEN `euler_planar_rotation (V:A->bool) E r`
  (LABEL_TAC "euler") THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `q:num->A`; `n:num`]
   MAXIMAL_BOUNDARY_EULER_ROTATION_LAST_NEIGHBOR_CYCLE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@k w. length neighbors injective first last cycle_edges" THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `q:num->A`; `n:num`]
   SIMPLE_GRAPH_CYCLE_LAST_BOUNDARY_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "_ endpoints_distinct _ right_neighbor" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `(q:num->A)(n - 1)`;
    `(q:num->A) 0`]
   FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "last_vertex zero_vertex last_zero_distinct" THEN
  SUBGOAL_THEN
   `connected_graph (V DELETE (q:num->A)(n - 1))
      (induced_subgraph_edges E (V DELETE q(n - 1)))`
  (LABEL_TAC "deleted_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `(q:num->A)(n - 1)`;
      `w:num->A`; `k + 2:num`]
     CONNECTED_GRAPH_DELETE_VERTEX_OF_CYCLIC_NEIGHBORS) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      USE_THEN "connected" ACCEPT_TAC;
      USE_THEN "last_vertex" ACCEPT_TAC;
      USE_THEN "neighbors" ACCEPT_TAC;
      ARITH_TAC;
      USE_THEN "cycle_edges" ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `V DELETE (q:num->A)(n - 1)`;
    `induced_subgraph_edges E (V DELETE (q:num->A)(n - 1))`]
   EULER_PLANAR_ROTATION_CONNECTED_SUBGRAPH) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "euler" ACCEPT_TAC;
      USE_THEN "connected" ACCEPT_TAC;
      REWRITE_TAC[DELETE_SUBSET];
      ASM SET_TAC[];
      REWRITE_TAC[SUBSET_REFL];
      USE_THEN "deleted_connected" ACCEPT_TAC];
    DISCH_THEN(X_CHOOSE_THEN `s:(A#A)->A#A`
     (LABEL_TAC "deleted_euler"))] THEN
  MAP_EVERY EXISTS_TAC [`k:num`; `w:num->A`; `s:(A#A)->A#A`] THEN
  ASM_REWRITE_TAC[]);;

let SIMPLE_GRAPH_CYCLE_DELETE_LAST_INDUCED = prove
 (`!V E q:num->A. !n k w.
        finite_simple_graph V E /\
        simple_graph_cycle E q n /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q (n - 1)} IN E)) /\
        3 <= n - 1 + k /\
        graph_neighbors E (q (n - 1)) = cyclic_vertices w (k + 2) /\
        INJ w (cyclic_indices (k + 2)) (:A) /\
        w 0 = q (n - 2) /\
        w (k + 1) = q 0 /\
        cyclic_edges w (k + 2) SUBSET E
        ==> simple_graph_cycle
             (induced_subgraph_edges E (V DELETE q (n - 1)))
             (cyclic_delete_last q w n) (n - 1 + k)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph cycle chordless newlarge neighbors w_injective first last \
    w_edges" THEN
  SUBGOAL_THEN
   `!r. r + 1 < k + 2 ==> {(w:num->A) r,w(r + 1)} IN E`
  (LABEL_TAC "chain") THENL
   [X_GEN_TAC `r:num` THEN DISCH_THEN(LABEL_TAC "bound") THEN
    USE_THEN "w_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_EDGES] THEN EXISTS_TAC `r:num` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
      SUBGOAL_THEN `(r + 1) MOD (k + 2) = r + 1` SUBST1_TAC THENL
       [MATCH_MP_TAC MOD_LT THEN USE_THEN "bound" ACCEPT_TAC;
        REFL_TAC]];
    ALL_TAC] THEN
  USE_THEN "cycle" (MP_TAC o REWRITE_RULE[simple_graph_cycle]) THEN
  INTRO_TAC "nlarge q_injective boundary_edges" THEN
  SUBGOAL_THEN
   `cyclic_vertices (q:num->A) n INTER cyclic_vertices w (k + 2) =
    {q (n - 2),q 0}`
  (LABEL_TAC "intersection") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`]
     BOUNDARY_NEIGHBORS_OF_LAST_WITHOUT_CHORD) THEN
    ASM_REWRITE_TAC[simple_graph_cycle] THEN
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle (E:(A->bool)->bool)
      (cyclic_delete_last (q:num->A) (w:num->A) n) (n - 1 + k)`
  (LABEL_TAC "new_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DELETE_LAST THEN
    ASM_REWRITE_TAC[simple_graph_cycle];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_vertices (cyclic_delete_last (q:num->A) w n) (n - 1 + k) =
    cyclic_vertices q n DELETE q (n - 1) UNION
    graph_neighbors E (q (n - 1))`
  (LABEL_TAC "new_vertices") THENL
   [MP_TAC(ISPECL [`q:num->A`; `w:num->A`; `n:num`; `k:num`]
     CYCLIC_VERTICES_CYCLIC_DELETE_LAST) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `cyclic_delete_last (q:num->A) w n`;
    `n - 1 + k:num`; `V DELETE (q:num->A)(n - 1)`]
   SIMPLE_GRAPH_CYCLE_INDUCED_SUBGRAPH) THEN
  CONJ_TAC THENL
   [USE_THEN "new_cycle" ACCEPT_TAC;
    USE_THEN "new_vertices" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[UNION_SUBSET] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`]
       FINITE_SIMPLE_GRAPH_CYCLE_VERTICES_SUBSET) THEN
      ASM_REWRITE_TAC[simple_graph_cycle] THEN SET_TAC[];
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `(q:num->A)(n - 1)`]
       FINITE_SIMPLE_GRAPH_NEIGHBORS_SUBSET_DELETE) THEN
      USE_THEN "graph" ACCEPT_TAC]]);;

let MAXIMAL_EULER_PLANAR_ROTATION_FACE_VERTICES_CARD_EQ_3 = prove
 (`!V E r d:A#A.
        euler_planar_rotation (V:A->bool) E r /\
        connected_graph V E /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\
             E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s) /\
        3 <= CARD V /\
        d IN graph_darts E
        ==> CARD(graph_rotation_face_vertices E r d) = 3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "euler connected maximal vertices_large dart" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
   MAXIMAL_EULER_PLANAR_ROTATION_FACE_VERTICES_CARD_LE_3) THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
   CONNECTED_SIMPLE_GRAPH_FACE_VERTICES_CARD_AT_LEAST_3) THEN
  ASM_REWRITE_TAC[] THEN ARITH_TAC);;

let GRAPH_ROTATION_FIXED_DART_AT_TAIL = prove
 (`!E r d d':A#A.
        graph_rotation E r /\
        d IN graph_darts E /\
        d' IN graph_darts E /\
        FST d' = FST d /\
        r d = d
        ==> d' = d`,
  REPEAT GEN_TAC THEN INTRO_TAC "rotation dart dart' tail fixed" THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`; `d':A#A`]
   GRAPH_ROTATION_ORBIT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "orbit")) THEN
  USE_THEN "orbit" (SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC ITER_FIXPOINT THEN USE_THEN "fixed" ACCEPT_TAC);;

let MAXIMAL_EULER_PLANAR_ROTATION_SUCCESSIVE_NEIGHBOR_FACE = prove
 (`!V E r u v w:A.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\ E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s) /\
        3 <= CARD V /\
        (u,v) IN outgoing_darts E u /\
        r(u,v) = (u,w) /\
        ~(v = w) /\
        {v,w} IN E
        ==> graph_face_successor E r (u,w) = (w,v)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected maximal vertices_large outgoing step distinct edge" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `((u:A),v) IN graph_darts E` (LABEL_TAC "uv_dart") THENL
   [USE_THEN "outgoing" MP_TAC THEN REWRITE_TAC[IN_OUTGOING_DARTS] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `((v:A),u) IN graph_darts E` (LABEL_TAC "vu_dart") THENL
   [MP_TAC(ISPECL [`E:(A->bool)->bool`; `((u:A),v):A#A`]
     GRAPH_DARTS_REVERSE) THEN
    ASM_REWRITE_TAC[REVERSE_DART_PAIR];
    ALL_TAC] THEN
  SUBGOAL_THEN `((u:A),w) IN graph_darts E` (LABEL_TAC "uw_dart") THENL
   [USE_THEN "step" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC GRAPH_ROTATION_IN THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `((w:A),u) IN graph_darts E` (LABEL_TAC "wu_dart") THENL
   [MP_TAC(ISPECL [`E:(A->bool)->bool`; `((u:A),w):A#A`]
     GRAPH_DARTS_REVERSE) THEN
    ASM_REWRITE_TAC[REVERSE_DART_PAIR];
    ALL_TAC] THEN
  SUBGOAL_THEN `((w:A),v) IN graph_darts E` (LABEL_TAC "wv_dart") THENL
   [REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR] THEN
    ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
    USE_THEN "edge" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) = v) /\ ~((u:A) = w)`
  (CONJUNCTS_THEN2 (LABEL_TAC "uv_distinct") (LABEL_TAC "uw_distinct")) THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[];
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `w:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A) (v,u) = (u,w)`
  (LABEL_TAC "first_step") THENL
   [TRANS_TAC EQ_TRANS `(r:(A#A)->A#A) (u,v)` THEN
    CONJ_TAC THENL
     [MP_TAC(MATCH_MP
       (ISPECL
        [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((v:A),u):A#A`]
        GRAPH_FACE_SUCCESSOR_IN)
       (ASSUME `((v:A),u) IN graph_darts E`)) THEN
      REWRITE_TAC[REVERSE_DART_PAIR] THEN DISCH_THEN ACCEPT_TAC;
      USE_THEN "step" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(u:A,w) IN graph_face E r (v,u)`
  (LABEL_TAC "first_in_face") THENL
   [USE_THEN "first_step" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_ACCEPT_TAC GRAPH_FACE_SUCCESSOR_IN_FACE;
    ALL_TAC] THEN
  ABBREV_TAC
   `facev:A->bool =
      graph_rotation_face_vertices E (r:(A#A)->A#A) (v,u)` THEN
  POP_ASSUM(LABEL_TAC "facev_definition") THEN
  SUBGOAL_THEN `(u:A) IN facev /\ v IN facev /\ w IN facev`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_face")
    (CONJUNCTS_THEN2 (LABEL_TAC "v_face") (LABEL_TAC "w_face"))) THENL
   [CONJ_TAC THENL
     [USE_THEN "facev_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[graph_rotation_face_vertices; IN_IMAGE] THEN
      EXISTS_TAC `((v:A),u):A#A` THEN
      REWRITE_TAC[SND] THEN MATCH_ACCEPT_TAC GRAPH_FACE_REFL;
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `u:A`; `v:A`; `w:A`]
       GRAPH_ROTATION_SUCCESSIVE_HEADS_COFACIAL) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "facev_definition" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  SUBGOAL_THEN `(facev:A->bool) HAS_SIZE 3`
  (LABEL_TAC "facev_size") THENL
   [REWRITE_TAC[HAS_SIZE] THEN CONJ_TAC THENL
     [USE_THEN "facev_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `((v:A),u):A#A`]
       FINITE_GRAPH_ROTATION_FACE_VERTICES) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "facev_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `((v:A),u):A#A`]
       MAXIMAL_EULER_PLANAR_ROTATION_FACE_VERTICES_CARD_EQ_3) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `({u:A,v,w}:A->bool) HAS_SIZE 3`
  (LABEL_TAC "triple_size") THENL
   [REWRITE_TAC[HAS_SIZE_CONV `({u:A,v,w}:A->bool) HAS_SIZE 3`] THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `v:A`; `w:A`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(facev:A->bool) = {u,v,w}`
  (LABEL_TAC "facev_eq") THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC CARD_SUBSET_EQ THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "facev_size"
       (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[HAS_SIZE]);
      REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN ASM_REWRITE_TAC[];
      USE_THEN "triple_size" (fun triple_th ->
       USE_THEN "facev_size" (fun face_th ->
        ACCEPT_TAC(TRANS
         (CONJUNCT2(REWRITE_RULE[HAS_SIZE] triple_th))
         (SYM(CONJUNCT2(REWRITE_RULE[HAS_SIZE] face_th))))))];
    ALL_TAC] THEN
  ABBREV_TAC
   `d2:A#A = graph_face_successor E (r:(A#A)->A#A) (u,w)` THEN
  POP_ASSUM(LABEL_TAC "d2_definition") THEN
  SUBGOAL_THEN `(d2:A#A) IN graph_darts E` (LABEL_TAC "d2_dart") THENL
   [USE_THEN "d2_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_DART THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(d2:A#A) IN graph_face E r (v,u)`
  (LABEL_TAC "d2_face") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((v:A),u):A#A`;
      `((u:A),w):A#A`; `d2:A#A`]
     GRAPH_FACE_TRANS) THEN
    CONJ_TAC THENL
     [USE_THEN "first_in_face" ACCEPT_TAC;
      USE_THEN "d2_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_ACCEPT_TAC GRAPH_FACE_SUCCESSOR_IN_FACE];
    ALL_TAC] THEN
  SUBGOAL_THEN `FST(d2:A#A) = w` (LABEL_TAC "d2_tail") THENL
   [USE_THEN "d2_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((u:A),w):A#A`]
     GRAPH_FACE_SUCCESSOR_TAIL) THEN
    ASM_REWRITE_TAC[SND];
    ALL_TAC] THEN
  SUBGOAL_THEN `SND(d2:A#A) IN facev` (LABEL_TAC "d2_head_face") THENL
   [USE_THEN "facev_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[graph_rotation_face_vertices; IN_IMAGE] THEN
    EXISTS_TAC `d2:A#A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(SND(d2:A#A) = w)` (LABEL_TAC "head_not_w") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `FST(d2:A#A)`; `SND(d2:A#A)`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[PAIR] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(SND(d2:A#A) = u)` (LABEL_TAC "head_not_u") THENL
   [DISCH_THEN(LABEL_TAC "head_u") THEN
    SUBGOAL_THEN `(d2:A#A) = (w,u)` (LABEL_TAC "d2_pair") THENL
     [USE_THEN "d2_tail" (fun tail_th ->
       USE_THEN "head_u" (fun head_th ->
        let pair_th = MATCH_MP
          (snd(EQ_IMP_RULE
            (ISPECL
             [`FST(d2:A#A)`; `SND(d2:A#A)`; `w:A`; `u:A`]
             PAIR_EQ)))
          (CONJ tail_th head_th) in
        ACCEPT_TAC(TRANS (SYM(ISPEC `d2:A#A` PAIR)) pair_th)));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(d2:A#A) = (r:(A#A)->A#A) (w,u)`
    (LABEL_TAC "d2_rotation") THENL
     [USE_THEN "d2_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MP_TAC(MATCH_MP
       (ISPECL
        [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((u:A),w):A#A`]
        GRAPH_FACE_SUCCESSOR_IN)
       (ASSUME `((u:A),w) IN graph_darts E`)) THEN
      REWRITE_TAC[REVERSE_DART_PAIR] THEN DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(r:(A#A)->A#A) (w,u) = (w,u)`
    (LABEL_TAC "wu_fixed") THENL
     [USE_THEN "d2_rotation" (fun rotation_th ->
       USE_THEN "d2_pair" (fun pair_th ->
        ACCEPT_TAC(TRANS (SYM rotation_th) pair_th)));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `FST(((w:A),v):A#A) = FST(((w:A),u):A#A)`
    (LABEL_TAC "same_tail") THENL
     [REWRITE_TAC[FST];
      ALL_TAC] THEN
    MP_TAC(MATCH_MP
     (ISPECL
      [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
       `((w:A),u):A#A`; `((w:A),v):A#A`]
      GRAPH_ROTATION_FIXED_DART_AT_TAIL)
     (end_itlist CONJ
       [ASSUME `graph_rotation E (r:(A#A)->A#A)`;
        ASSUME `((w:A),u) IN graph_darts E`;
        ASSUME `((w:A),v) IN graph_darts E`;
        ASSUME `FST(((w:A),v):A#A) = FST(((w:A),u):A#A)`;
        ASSUME `(r:(A#A)->A#A) (w,u) = (w,u)`])) THEN
    DISCH_THEN(LABEL_TAC "same_dart") THEN
    USE_THEN "same_dart" MP_TAC THEN REWRITE_TAC[PAIR_EQ] THEN
    DISCH_THEN(LABEL_TAC "vu_same") THEN
    USE_THEN "uv_distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "vu_same" (ACCEPT_TAC o SYM);
    ALL_TAC] THEN
  SUBGOAL_THEN `SND(d2:A#A) = v` (LABEL_TAC "d2_head") THENL
   [USE_THEN "d2_head_face" MP_TAC THEN
    USE_THEN "facev_eq"
     (fun th -> REWRITE_TAC[th; IN_INSERT; IN_SING]) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(d2:A#A) = (w,v)` (LABEL_TAC "d2_result") THENL
   [USE_THEN "d2_tail" (fun tail_th ->
     USE_THEN "d2_head" (fun head_th ->
      let pair_th = MATCH_MP
        (snd(EQ_IMP_RULE
          (ISPECL
           [`FST(d2:A#A)`; `SND(d2:A#A)`; `w:A`; `v:A`]
           PAIR_EQ)))
        (CONJ tail_th head_th) in
      ACCEPT_TAC(TRANS (SYM(ISPEC `d2:A#A` PAIR)) pair_th)));
    ASM_MESON_TAC[]]);;

let GRAPH_ROTATION_NEIGHBOR_ENUMERATION_STEPS = prove
 (`!V E r u d:A#A.
        finite_simple_graph (V:A->bool) E /\
        graph_rotation E r /\
        d IN outgoing_darts E u
        ==> ?w:num->A.
              graph_neighbors E u =
                cyclic_vertices w (CARD(graph_neighbors E u)) /\
              INJ w (cyclic_indices (CARD(graph_neighbors E u))) (:A) /\
              w 0 = SND d /\
              (!i. i < CARD(graph_neighbors E u)
                   ==> (u,w i) IN outgoing_darts E u /\
                       r(u,w i) =
                       (u,w((i + 1) MOD
                           CARD(graph_neighbors E u))))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation dart" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `d:A#A`]
   GRAPH_ROTATION_NEIGHBOR_ENUMERATION_PHASED) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@w. neighbors injective start next iter return" THEN
  EXISTS_TAC `w:num->A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "neighbors" ACCEPT_TAC;
    USE_THEN "injective" ACCEPT_TAC;
    USE_THEN "start" ACCEPT_TAC;
    ALL_TAC] THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
  ABBREV_TAC
   `j = (i + 1) MOD
        CARD(graph_neighbors (E:(A->bool)->bool) (u:A))` THEN
  SUBGOAL_THEN
   `0 < CARD(graph_neighbors (E:(A->bool)->bool) (u:A))`
  (LABEL_TAC "positive") THENL
   [USE_THEN "index" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `j IN cyclic_indices
      (CARD(graph_neighbors (E:(A->bool)->bool) (u:A)))`
  (LABEL_TAC "j_index") THENL
   [EXPAND_TAC "j" THEN
    REWRITE_TAC[IN_CYCLIC_INDICES; MOD_LT_EQ_LT] THEN
    USE_THEN "positive" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `ITER i
      (restricted_permutation (r:(A#A)->A#A)
        (outgoing_darts (E:(A->bool)->bool) (u:A))) d =
    (u,(w:num->A) i)`
  (LABEL_TAC "current") THENL
   [USE_THEN "iter" (MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[IN_CYCLIC_INDICES] THEN
      USE_THEN "index" ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `ITER j
      (restricted_permutation (r:(A#A)->A#A)
        (outgoing_darts (E:(A->bool)->bool) (u:A))) d =
    (u,(w:num->A) j)`
  (LABEL_TAC "next_value") THENL
   [USE_THEN "iter" (MP_TAC o SPEC `j:num`) THEN
    ANTS_TAC THENL
     [USE_THEN "j_index" ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `restricted_permutation (r:(A#A)->A#A)
      (outgoing_darts (E:(A->bool)->bool) (u:A))
    permutes outgoing_darts E u`
  (LABEL_TAC "local_permutation") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `u:A`]
     GRAPH_ROTATION_RESTRICTED_OUTGOING_PERMUTES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(u,(w:num->A) i) IN outgoing_darts E u`
  (LABEL_TAC "current_outgoing") THENL
   [USE_THEN "current" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MP_TAC(ISPECL
     [`ITER i
        (restricted_permutation (r:(A#A)->A#A)
          (outgoing_darts E u))`;
      `outgoing_darts (E:(A->bool)->bool) (u:A)`; `d:A#A`]
     PERMUTES_IN_IMAGE) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC PERMUTES_ITER THEN
      USE_THEN "local_permutation" ACCEPT_TAC;
      DISCH_THEN(MP_TAC o snd o EQ_IMP_RULE) THEN
      DISCH_THEN MATCH_MP_TAC THEN USE_THEN "dart" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `ITER (i + 1)
      (restricted_permutation (r:(A#A)->A#A)
        (outgoing_darts E u)) d =
    ITER j
      (restricted_permutation r (outgoing_darts E u)) d`
  (LABEL_TAC "step_mod") THENL
   [EXPAND_TAC "j" THEN
    MATCH_MP_TAC(ISPECL
     [`restricted_permutation (r:(A#A)->A#A)
        (outgoing_darts E u)`;
      `d:A#A`; `CARD(graph_neighbors (E:(A->bool)->bool) (u:A))`;
      `i + 1:num`]
     ITER_MOD_PERIODIC_POINT) THEN
    CONJ_TAC THENL
     [USE_THEN "positive" ACCEPT_TAC;
      USE_THEN "return" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `restricted_permutation (r:(A#A)->A#A) (outgoing_darts E u)
      (u,(w:num->A) i) = (u,w j)`
  (LABEL_TAC "local_step") THENL
   [TRANS_TAC EQ_TRANS
     `ITER (i + 1)
       (restricted_permutation (r:(A#A)->A#A)
         (outgoing_darts E u)) d` THEN
    CONJ_TAC THENL
     [USE_THEN "current" (fun th ->
        REWRITE_TAC[GSYM ADD1; ITER; th]);
      USE_THEN "step_mod" (fun step_th ->
       USE_THEN "next_value"
        (fun next_th -> ACCEPT_TAC(TRANS step_th next_th)))];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "current_outgoing" ACCEPT_TAC;
    USE_THEN "local_step" MP_TAC THEN
    REWRITE_TAC[restricted_permutation] THEN
    USE_THEN "current_outgoing" (fun th -> REWRITE_TAC[th]) THEN
    EXPAND_TAC "j"]);;

let MAXIMAL_EULER_PLANAR_ROTATION_SUCCESSIVE_NEIGHBORS_EDGE = prove
 (`!V E r u v w:A.
        euler_planar_rotation V E r /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\ E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s) /\
        (u,v) IN outgoing_darts E u /\
        r(u,v) = (u,w) /\
        ~(v = w)
        ==> {v,w} IN E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "euler maximal outgoing step distinct" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `((u:A),v) IN graph_darts E`
  (LABEL_TAC "forward_dart") THENL
   [USE_THEN "outgoing" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `((v:A),u) IN graph_darts E`
  (LABEL_TAC "reverse_dart") THENL
   [MP_TAC(ISPECL [`E:(A->bool)->bool`; `((u:A),v):A#A`]
     GRAPH_DARTS_REVERSE) THEN
    ASM_REWRITE_TAC[REVERSE_DART_PAIR];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `w:A`]
   GRAPH_ROTATION_SUCCESSIVE_HEADS_COFACIAL) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "v_face w_face" THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
     `((v:A),u):A#A`]
    MAXIMAL_EULER_PLANAR_ROTATION_FACE_VERTICES_CLIQUE)
   (end_itlist CONJ
    [ASSUME `euler_planar_rotation (V:A->bool) E r`;
     ASSUME
      `!E' s:(A#A)->A#A.
         E PSUBSET E' /\ E' SUBSET complete_graph_edges V
         ==> ~euler_planar_rotation V E' s`;
     ASSUME `((v:A),u) IN graph_darts E`])) THEN
  DISCH_THEN(MP_TAC o ISPECL [`v:A`; `w:A`]) THEN
  ASM_REWRITE_TAC[]);;

let MAXIMAL_EULER_PLANAR_ROTATION_ORIENTED_NEIGHBOR_CYCLE = prove
 (`!V E r u d:A#A.
        euler_planar_rotation V E r /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\
             E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s) /\
        d IN outgoing_darts E u
        ==> ?w:num->A.
              graph_neighbors E u =
                cyclic_vertices w (CARD(graph_neighbors E u)) /\
              INJ w (cyclic_indices (CARD(graph_neighbors E u))) (:A) /\
              w 0 = SND d /\
              (2 <= CARD(graph_neighbors E u)
               ==> cyclic_edges w (CARD(graph_neighbors E u)) SUBSET E) /\
              (!i. i < CARD(graph_neighbors E u)
                   ==> (u,w i) IN outgoing_darts E u /\
                       r(u,w i) =
                       (u,w((i + 1) MOD
                           CARD(graph_neighbors E u))))`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler maximal dart" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `d:A#A`]
   GRAPH_ROTATION_NEIGHBOR_ENUMERATION_STEPS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@w. neighbors injective start steps" THEN
  EXISTS_TAC `w:num->A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "neighbors" ACCEPT_TAC;
    USE_THEN "injective" ACCEPT_TAC;
    USE_THEN "start" ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "large") THEN
    REWRITE_TAC[SUBSET; IN_CYCLIC_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN
    INTRO_TAC "@i. index edge" THEN
    USE_THEN "edge" SUBST1_TAC THEN
    SUBGOAL_THEN
     `(u,(w:num->A) i) IN outgoing_darts E u /\
      (r:(A#A)->A#A) (u,w i) =
      (u,w((i + 1) MOD
           CARD(graph_neighbors (E:(A->bool)->bool) (u:A))))`
    (CONJUNCTS_THEN2 (LABEL_TAC "outgoing") (LABEL_TAC "step")) THENL
     [USE_THEN "steps" (MP_TAC o SPEC `i:num`) THEN
      ANTS_TAC THENL
       [USE_THEN "index" ACCEPT_TAC;
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(i + 1) MOD
        CARD(graph_neighbors (E:(A->bool)->bool) (u:A)) <
      CARD(graph_neighbors (E:(A->bool)->bool) (u:A))`
    (LABEL_TAC "j_index") THENL
     [REWRITE_TAC[MOD_LT_EQ_LT] THEN
      USE_THEN "index" MP_TAC THEN ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((w:num->A) i =
        w((i + 1) MOD
          CARD(graph_neighbors (E:(A->bool)->bool) (u:A))))`
    (LABEL_TAC "distinct") THENL
     [DISCH_THEN(LABEL_TAC "same") THEN
      SUBGOAL_THEN
       `(i:num) =
        (i + 1) MOD
          CARD(graph_neighbors (E:(A->bool)->bool) (u:A))`
      (LABEL_TAC "same_index") THENL
       [USE_THEN "injective" MP_TAC THEN
        REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
        DISCH_THEN(MATCH_MP_TAC o SPECL
         [`i:num`;
          `(i + 1) MOD CARD(graph_neighbors
            (E:(A->bool)->bool) (u:A))`]) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`CARD(graph_neighbors (E:(A->bool)->bool) (u:A))`; `i:num`]
       CYCLIC_SUCCESSOR_NE) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        DISCH_THEN(LABEL_TAC "successor_ne")] THEN
      USE_THEN "successor_ne" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "same_index" (ACCEPT_TAC o SYM);
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `(w:num->A) i`;
      `(w:num->A)
       ((i + 1) MOD
        CARD(graph_neighbors (E:(A->bool)->bool) (u:A)))`]
     MAXIMAL_EULER_PLANAR_ROTATION_SUCCESSIVE_NEIGHBORS_EDGE) THEN
    ASM_REWRITE_TAC[];
    USE_THEN "steps" ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* Orient the neighbor cycle at the final boundary vertex.                   *)
(* ------------------------------------------------------------------------- *)

let CYCLIC_EDGES_REVERSE_SUBSET = prove
 (`!E:(A->bool)->bool. !q:num->A. !n.
        2 <= n /\
        cyclic_edges q n SUBSET E
        ==> cyclic_edges (cyclic_reverse q n) n SUBSET E`,
  REPEAT GEN_TAC THEN INTRO_TAC "large edges" THEN
  MATCH_MP_TAC CYCLIC_EDGES_SUBSET_OF_CHAIN_AND_LAST THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "large" ACCEPT_TAC;
    MATCH_MP_TAC CYCLIC_REVERSE_CHAIN THEN
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `i:num` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
      SUBGOAL_THEN `(i + 1) MOD n = i + 1` SUBST1_TAC THENL
       [MATCH_MP_TAC MOD_LT THEN USE_THEN "index" ACCEPT_TAC;
        REFL_TAC]];
    MP_TAC(SPECL [`q:num->A`; `n:num`] CYCLIC_REVERSE_ENDPOINTS) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      INTRO_TAC "first last"] THEN
    USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `n - 1:num` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
      SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        ASM_REWRITE_TAC[MOD_REFL; PAIR_SET_SYM]]]]);;

let CYCLIC_REVERSE_OFFSET_ROTATION_STEPS = prove
 (`!r:(A#A)->A#A. !u:A. !z:num->A. !m.
        2 <= m /\
        (!j. j < m
             ==> r(u,z j) = (u,z((j + 1) MOD m)))
        ==> !i. i + 1 < m
                ==> r
                     (u,cyclic_reverse
                         (\j. z((j + 1) MOD m)) m (i + 1)) =
                    (u,cyclic_reverse
                        (\j. z((j + 1) MOD m)) m i)`,
  REPEAT GEN_TAC THEN INTRO_TAC "large steps" THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
  REWRITE_TAC[cyclic_reverse] THEN BETA_TAC THEN
  SUBGOAL_THEN
   `m - 1 - (i + 1) + 1 = m - 1 - i`
  (LABEL_TAC "source_index") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `m - 1 - i < m` (LABEL_TAC "within") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "steps" (MP_TAC o SPEC `m - 1 - i:num`) THEN
  ASM_SIMP_TAC[MOD_LT]);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_LAST_ORIENTED_NEIGHBOR_PATH = prove
 (`!V E r q n.
        boundary_euler_rotation (V:A->bool) E (q:num->A) n r /\
        simple_graph_cycle E q n /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\
             E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s)
        ==> ?k w.
              CARD(graph_neighbors E (q(n - 1))) = k + 2 /\
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = q(n - 2) /\
              w(k + 1) = q 0 /\
              cyclic_edges w (k + 2) SUBSET E /\
              (!i. i + 1 < k + 2
                   ==> r(q(n - 1),w(i + 1)) =
                       (q(n - 1),w i))`,
  REPEAT GEN_TAC THEN INTRO_TAC "boundary cycle maximal" THEN
  SUBGOAL_THEN `euler_planar_rotation (V:A->bool) E r`
  (LABEL_TAC "euler") THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `q:num->A`; `n:num`]
   SIMPLE_GRAPH_CYCLE_LAST_BOUNDARY_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "nlarge endpoints_distinct start_dart right_neighbor" THEN
  SUBGOAL_THEN
   `(q:num->A)(n - 2) IN graph_neighbors E (q(n - 1))`
  (LABEL_TAC "left_neighbor") THENL
   [USE_THEN "start_dart" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS_PAIR; IN_GRAPH_NEIGHBORS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `2 <= CARD(graph_neighbors (E:(A->bool)->bool) (q(n - 1)))`
  (LABEL_TAC "degree_large") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `(q:num->A)(n - 1)`;
      `(q:num->A)(n - 2)`; `(q:num->A) 0`]
     FINITE_GRAPH_TWO_DISTINCT_NEIGHBORS_CARD) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) (q(n - 1),q(n - 2)) = (q(n - 1),q 0)`
  (LABEL_TAC "boundary_step") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `r:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_LAST_ROTATION_STEP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `(q:num->A)(n - 1)`; `((q(n - 1),q(n - 2)):A#A)`]
   MAXIMAL_EULER_PLANAR_ROTATION_ORIENTED_NEIGHBOR_CYCLE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC "@z. neighbors injective first cycle_edges steps"] THEN
  ABBREV_TAC
   `m = CARD(graph_neighbors
          (E:(A->bool)->bool) ((q:num->A)(n - 1)))` THEN
  POP_ASSUM(LABEL_TAC "m_definition") THEN
  SUBGOAL_THEN `2 <= m` (LABEL_TAC "large") THENL
   [USE_THEN "m_definition" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "degree_large" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_neighbors (E:(A->bool)->bool) (q(n - 1)) =
    cyclic_vertices (z:num->A) m`
  (LABEL_TAC "z_neighbors") THENL
   [USE_THEN "m_definition" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "neighbors" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (z:num->A) (cyclic_indices m) (:A)`
  (LABEL_TAC "z_injective") THENL
   [USE_THEN "m_definition" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "injective" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(z:num->A) 0 = q(n - 2)` (LABEL_TAC "z_first") THENL
   [USE_THEN "first" MP_TAC THEN REWRITE_TAC[SND];
    ALL_TAC] THEN
  SUBGOAL_THEN `cyclic_edges (z:num->A) m SUBSET E`
  (LABEL_TAC "z_edges") THENL
   [USE_THEN "m_definition" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "cycle_edges" MATCH_MP_TAC THEN
    USE_THEN "degree_large" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i < m
        ==> (q(n - 1),(z:num->A) i) IN outgoing_darts E (q(n - 1)) /\
            (r:(A#A)->A#A) (q(n - 1),z i) =
            (q(n - 1),z((i + 1) MOD m))`
  (LABEL_TAC "z_data") THENL
   [USE_THEN "m_definition" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "steps" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(z:num->A) 1 = q 0` (LABEL_TAC "z_second") THENL
   [USE_THEN "z_data" (MP_TAC o SPEC `0`) THEN
    ANTS_TAC THENL
     [USE_THEN "large" MP_TAC THEN ARITH_TAC;
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
       (LABEL_TAC "first_step"))] THEN
    SUBGOAL_THEN `(0 + 1) MOD m = 1` (LABEL_TAC "one_mod") THENL
     [REWRITE_TAC[ADD_CLAUSES] THEN MATCH_MP_TAC MOD_LT THEN
      USE_THEN "large" MP_TAC THEN ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "first_step" (fun step_th ->
     USE_THEN "z_first" (fun first_th ->
      USE_THEN "boundary_step" (fun boundary_th ->
       USE_THEN "one_mod" (fun mod_th ->
        ACCEPT_TAC(SYM(REWRITE_RULE
         [first_th; boundary_th; mod_th; PAIR_EQ] step_th))))));
    ALL_TAC] THEN
  ABBREV_TAC `h:num->A = \i. (z:num->A) ((i + 1) MOD m)` THEN
  POP_ASSUM(LABEL_TAC "h_definition") THEN
  ABBREV_TAC `w:num->A = cyclic_reverse (h:num->A) m` THEN
  POP_ASSUM(LABEL_TAC "w_definition") THEN
  SUBGOAL_THEN
   `graph_neighbors (E:(A->bool)->bool) (q(n - 1)) =
    cyclic_vertices (w:num->A) m`
  (LABEL_TAC "w_neighbors") THENL
   [USE_THEN "w_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[CYCLIC_VERTICES_REVERSE] THEN
    USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[CYCLIC_VERTICES_OFFSET] THEN
    USE_THEN "z_neighbors" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (w:num->A) (cyclic_indices m) (:A)`
  (LABEL_TAC "w_injective") THENL
   [USE_THEN "w_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC INJ_CYCLIC_REVERSE THEN
    USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC INJ_CYCLIC_OFFSET THEN
    USE_THEN "z_injective" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `cyclic_edges (w:num->A) m SUBSET E`
  (LABEL_TAC "w_edges") THENL
   [USE_THEN "w_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC CYCLIC_EDGES_REVERSE_SUBSET THEN
    CONJ_TAC THENL
     [USE_THEN "large" ACCEPT_TAC;
      USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[CYCLIC_EDGES_OFFSET] THEN
      USE_THEN "z_edges" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w:num->A) 0 = q(n - 2) /\ w(m - 1) = q 0`
  (CONJUNCTS_THEN2 (LABEL_TAC "w_first") (LABEL_TAC "w_last")) THENL
   [MP_TAC(SPECL [`h:num->A`; `m:num`] CYCLIC_REVERSE_ENDPOINTS) THEN
    ANTS_TAC THENL
     [USE_THEN "large" MP_TAC THEN ARITH_TAC;
      INTRO_TAC "reverse_first reverse_last"] THEN
    SUBGOAL_THEN `(h:num->A) 0 = q 0` (LABEL_TAC "h_first") THENL
     [USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      BETA_TAC THEN
      SUBGOAL_THEN `(0 + 1) MOD m = 1` SUBST1_TAC THENL
       [REWRITE_TAC[ADD_CLAUSES] THEN MATCH_MP_TAC MOD_LT THEN
        USE_THEN "large" MP_TAC THEN ARITH_TAC;
        USE_THEN "z_second" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(h:num->A) (m - 1) = q(n - 2)`
    (LABEL_TAC "h_last") THENL
     [USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      BETA_TAC THEN
      SUBGOAL_THEN `(m - 1) + 1 = m` SUBST1_TAC THENL
       [USE_THEN "large" MP_TAC THEN ARITH_TAC;
        REWRITE_TAC[MOD_REFL] THEN USE_THEN "z_first" ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "w_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i + 1 < m
        ==> (r:(A#A)->A#A) (q(n - 1),w(i + 1)) =
            (q(n - 1),w i)`
  (LABEL_TAC "w_steps") THENL
   [USE_THEN "w_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC CYCLIC_REVERSE_OFFSET_ROTATION_STEPS THEN
    CONJ_TAC THENL
     [USE_THEN "large" ACCEPT_TAC;
      X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
      USE_THEN "z_data" (MP_TAC o SPEC `i:num`) THEN
      ANTS_TAC THENL
       [USE_THEN "index" ACCEPT_TAC;
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC)]];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`m - 2`; `w:num->A`] THEN
  SUBGOAL_THEN `(m:num) - 2 + 2 = m` (LABEL_TAC "length") THENL
   [USE_THEN "large" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(m:num) - 2 + 1 = m - 1`
  (LABEL_TAC "last_index") THENL
   [USE_THEN "large" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "m_definition" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "length" (ACCEPT_TAC o SYM);
    USE_THEN "length" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "w_neighbors" ACCEPT_TAC;
    USE_THEN "length" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "w_injective" ACCEPT_TAC;
    USE_THEN "w_first" ACCEPT_TAC;
    USE_THEN "last_index" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "w_last" ACCEPT_TAC;
    USE_THEN "length" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "w_edges" ACCEPT_TAC;
    USE_THEN "length" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "w_steps" ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* The consecutive neighbor sectors are triangular faces.                    *)
(* ------------------------------------------------------------------------- *)

let MAXIMAL_EULER_PLANAR_ROTATION_SUCCESSIVE_NEIGHBOR_FACE_NEXT = prove
 (`!V E r u v w:A.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\ E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s) /\
        3 <= CARD V /\
        (u,v) IN outgoing_darts E u /\
        r(u,v) = (u,w) /\
        ~(v = w) /\
        {v,w} IN E
        ==> graph_face_successor E r (w,v) = (v,u)`,
