    MP_TAC(MATCH_MP
     (ISPECL
      [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
       `((v:A),w):A#A`; `((v:A),u):A#A`]
      GRAPH_ROTATION_FIXED_DART_AT_TAIL)
     (end_itlist CONJ
       [ASSUME `graph_rotation E (r:(A#A)->A#A)`;
        ASSUME `((v:A),w) IN graph_darts E`;
        ASSUME `((v:A),u) IN graph_darts E`;
        ASSUME `FST(((v:A),u):A#A) = FST(((v:A),w):A#A)`;
