let MAXIMAL_BOUNDARY_EULER_ROTATION_LAST_NEIGHBOR_FACES = prove
 (`!V E r q n.
        boundary_euler_rotation (V:A->bool) E (q:num->A) n r /\
        simple_graph_cycle E q n /\
        connected_graph V E /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\
             E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s) /\
        3 <= CARD V
        ==> ?k w.
              CARD(graph_neighbors E (q(n - 1))) = k + 2 /\
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = q(n - 2) /\
              w(k + 1) = q 0 /\
              cyclic_edges w (k + 2) SUBSET E /\
              (!i. i + 1 < k + 2
                   ==> r(q(n - 1),w(i + 1)) =
                       (q(n - 1),w i) /\
                       graph_face_successor E r
                        (q(n - 1),w i) = (w i,w(i + 1)) /\
                       graph_face_successor E r
                        (w i,w(i + 1)) = (w(i + 1),q(n - 1)) /\
                       graph_face_successor E r
                        (w(i + 1),q(n - 1)) =
                        (q(n - 1),w i))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "boundary cycle connected maximal vertices_large" THEN
  SUBGOAL_THEN `euler_planar_rotation (V:A->bool) E r`
  (LABEL_TAC "euler") THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `q:num->A`; `n:num`]
   MAXIMAL_BOUNDARY_EULER_ROTATION_LAST_ORIENTED_NEIGHBOR_PATH) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@k w. length neighbors injective first last cycle_edges path_steps" THEN
  MAP_EVERY EXISTS_TAC [`k:num`; `w:num->A`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "length" ACCEPT_TAC;
    USE_THEN "neighbors" ACCEPT_TAC;
    USE_THEN "injective" ACCEPT_TAC;
    USE_THEN "first" ACCEPT_TAC;
    USE_THEN "last" ACCEPT_TAC;
    USE_THEN "cycle_edges" ACCEPT_TAC;
    ALL_TAC] THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
  SUBGOAL_THEN
   `i < k + 2 /\ i + 1 < k + 2`
  (CONJUNCTS_THEN2 (LABEL_TAC "current_index")
    (LABEL_TAC "next_index")) THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w:num->A)(i + 1) IN
    graph_neighbors E ((q:num->A)(n - 1))`
  (LABEL_TAC "next_neighbor") THENL
   [USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `i + 1:num` THEN ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((q:num->A)(n - 1),w(i + 1)) IN
    outgoing_darts E (q(n - 1))`
  (LABEL_TAC "outgoing") THENL
   [REWRITE_TAC[IN_OUTGOING_DARTS_PAIR] THEN
    USE_THEN "next_neighbor" MP_TAC THEN
    REWRITE_TAC[IN_GRAPH_NEIGHBORS];
    ALL_TAC] THEN
  SUBGOAL_THEN `{(w:num->A) i,w(i + 1)} IN E`
  (LABEL_TAC "edge") THENL
   [USE_THEN "cycle_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_EDGES] THEN EXISTS_TAC `i:num` THEN
    CONJ_TAC THENL
     [ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
      SUBGOAL_THEN `(i + 1) MOD (k + 2) = i + 1`
      SUBST1_TAC THENL
       [MATCH_MP_TAC MOD_LT THEN USE_THEN "next_index" ACCEPT_TAC;
        REFL_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((w:num->A)(i + 1) = w i)`
  (LABEL_TAC "distinct") THENL
   [DISCH_THEN(LABEL_TAC "same") THEN
    USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    DISCH_THEN(MP_TAC o SPECL [`i + 1:num`; `i:num`]) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) (q(n - 1),w(i + 1)) =
    (q(n - 1),w i)`
  (LABEL_TAC "rotation_step") THENL
   [USE_THEN "path_steps" MATCH_MP_TAC THEN
    USE_THEN "index" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A)
      (q(n - 1),w i) = (w i,w(i + 1))`
  (LABEL_TAC "face_first") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `(q:num->A)(n - 1)`; `(w:num->A)(i + 1)`; `(w:num->A)i`]
     MAXIMAL_EULER_PLANAR_ROTATION_SUCCESSIVE_NEIGHBOR_FACE) THEN
    ASM_REWRITE_TAC[PAIR_SET_SYM];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A)
      (w i,w(i + 1)) = (w(i + 1),q(n - 1))`
  (LABEL_TAC "face_second") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `(q:num->A)(n - 1)`; `(w:num->A)(i + 1)`; `(w:num->A)i`]
     MAXIMAL_EULER_PLANAR_ROTATION_SUCCESSIVE_NEIGHBOR_FACE_NEXT) THEN
    ASM_REWRITE_TAC[PAIR_SET_SYM];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((w:num->A)(i + 1),(q:num->A)(n - 1)) IN graph_darts E`
  (LABEL_TAC "reverse_dart") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`;
      `((q:num->A)(n - 1),(w:num->A)(i + 1)):A#A`]
     GRAPH_DARTS_REVERSE) THEN
    USE_THEN "outgoing" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS; REVERSE_DART_PAIR] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A)
      (w(i + 1),q(n - 1)) = (q(n - 1),w i)`
  (LABEL_TAC "face_third") THENL
   [MP_TAC(MATCH_MP
     (ISPECL
      [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
       `((w:num->A)(i + 1),(q:num->A)(n - 1)):A#A`]
      GRAPH_FACE_SUCCESSOR_IN)
     (ASSUME
       `((w:num->A)(i + 1),(q:num->A)(n - 1)) IN graph_darts E`)) THEN
    ASM_REWRITE_TAC[REVERSE_DART_PAIR];
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Delete the triangular fan while preserving its outside face.              *)
(* ------------------------------------------------------------------------- *)

let GRAPH_REACHABLE_DELETE_EDGE = prove
  (`!E:(A->bool)->bool. !u v x y:A.
        ~(u = v) /\
        graph_reachable (E DELETE {u,v}) u v /\
        graph_reachable E x y
        ==> graph_reachable (E DELETE {u,v}) x y`,
  REPEAT GEN_TAC THEN INTRO_TAC "distinct alternate reachable" THEN
  SUBGOAL_THEN
   `!a b:A.
        graph_reachable E a b
        ==> graph_reachable (E DELETE {u,v}) a b`
  (LABEL_TAC "induction") THENL
   [REWRITE_TAC[graph_reachable] THEN
    MATCH_MP_TAC RTC_INDUCT THEN REPEAT CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`a:A`; `b:A`] THEN
      DISCH_THEN(LABEL_TAC "edge") THEN
      ASM_CASES_TAC `({a:A,b}:A->bool) = {u,v}` THENL
       [SUBGOAL_THEN
         `((a:A) = u /\ b = v) \/ (a = v /\ b = u)`
        MP_TAC THENL
         [ASM SET_TAC[];
          DISCH_THEN(DISJ_CASES_THEN STRIP_ASSUME_TAC) THENL
           [ASM_REWRITE_TAC[] THEN
            USE_THEN "alternate"
             (ACCEPT_TAC o REWRITE_RULE[graph_reachable]);
            ASM_REWRITE_TAC[] THEN
            ACCEPT_TAC(REWRITE_RULE[graph_reachable]
             (MATCH_MP GRAPH_REACHABLE_SYM
              (ASSUME
               `graph_reachable
                 ((E:(A->bool)->bool) DELETE {u,v}) u v`)))]];
        MATCH_MP_TAC RTC_INC THEN
        REWRITE_TAC[IN_DELETE] THEN CONJ_TAC THENL
         [USE_THEN "edge" (ACCEPT_TAC o REWRITE_RULE[]);
          USE_THEN "edge" MP_TAC THEN ASM_REWRITE_TAC[]]];
      X_GEN_TAC `a:A` THEN REWRITE_TAC[RTC_REFL];
      MESON_TAC[RTC_TRANS]];
    USE_THEN "induction" MATCH_MP_TAC THEN
    USE_THEN "reachable" ACCEPT_TAC]);;

let CONNECTED_GRAPH_DELETE_EDGE_OF_ALTERNATE_PATH = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
        connected_graph V E /\
        ~(u = v) /\
        graph_reachable (E DELETE {u,v}) u v
        ==> connected_graph V (E DELETE {u,v})`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected distinct alternate" THEN
  REWRITE_TAC[connected_graph] THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
  INTRO_TAC "x_vertex y_vertex" THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `u:A`; `v:A`; `x:A`; `y:A`]
   GRAPH_REACHABLE_DELETE_EDGE) THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "connected" MP_TAC THEN
  REWRITE_TAC[connected_graph] THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

let CONNECTED_GRAPH_DELETE_TRIANGLE_EDGE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w:A.
        connected_graph V E /\
        ~(u = v) /\
        {u,w} IN E DELETE {u,v} /\
        {w,v} IN E DELETE {u,v}
        ==> connected_graph V (E DELETE {u,v})`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "connected distinct first_edge second_edge" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
   CONNECTED_GRAPH_DELETE_EDGE_OF_ALTERNATE_PATH) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
   [`E DELETE {u:A,v}`; `u:A`; `w:A`; `v:A`]
   GRAPH_REACHABLE_TRANS) THEN
  CONJ_TAC THEN MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
  ASM_REWRITE_TAC[PAIR_SET_SYM]);;

let fan_delete_edges = new_recursive_definition num_RECURSION
 `(fan_delete_edges (x:A) (w:num->A)
                    (E:(A->bool)->bool) 0 = E) /\
  (fan_delete_edges x w E (SUC t) =
      fan_delete_edges x w E t DELETE {x,w t})`;;

let fan_delete_rotation = new_recursive_definition num_RECURSION
 `(fan_delete_rotation (x:A) (w:num->A)
                       (r:(A#A)->A#A) 0 = r) /\
  (fan_delete_rotation x w r (SUC t) =
      graph_delete_rotation
       (fan_delete_rotation x w r t) x (w t))`;;

let FAN_DELETE_EDGES_SUBSET = prove
  (`!x:A. !w:num->A. !E t.
        fan_delete_edges x w E t SUBSET E`,
  REPEAT GEN_TAC THEN SPEC_TAC(`t:num`,`t:num`) THEN
  INDUCT_TAC THENL
   [REWRITE_TAC[fan_delete_edges; SUBSET_REFL];
    REWRITE_TAC[fan_delete_edges] THEN
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `fan_delete_edges (x:A) (w:num->A) E t` THEN
    ASM_REWRITE_TAC[DELETE_SUBSET]]);;

let FAN_DELETE_EDGE_REMOVED = prove
  (`!x:A. !w:num->A. !E t i.
        i < t
        ==> ~({x,w i} IN fan_delete_edges x w E t)`,
  REPEAT GEN_TAC THEN SPEC_TAC(`i:num`,`i:num`) THEN
  SPEC_TAC(`t:num`,`t:num`) THEN
  INDUCT_TAC THENL
   [GEN_TAC THEN ARITH_TAC;
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    ASM_CASES_TAC `(i:num) = t` THENL
     [ASM_REWRITE_TAC[fan_delete_edges; IN_DELETE];
      SUBGOAL_THEN `(i:num) < t` (LABEL_TAC "earlier") THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `i:num`) THEN
      ASM_REWRITE_TAC[fan_delete_edges; IN_DELETE] THEN
      MESON_TAC[]]]);;

let FAN_DELETE_EDGE_REMAINS = prove
 (`!x:A. !w:num->A. !E m t i.
        INJ w (cyclic_indices m) (:A) /\
        (!j. j < m ==> ~(w j = x)) /\
        (!j. j < m ==> {x,w j} IN E) /\
        t <= i /\ i < m
        ==> {x,w i} IN fan_delete_edges x w E t`,
  REPEAT GEN_TAC THEN SPEC_TAC(`i:num`,`i:num`) THEN
  SPEC_TAC(`t:num`,`t:num`) THEN INDUCT_TAC THENL
   [X_GEN_TAC `i:num` THEN
    INTRO_TAC "injective avoids spokes lower index" THEN
    REWRITE_TAC[fan_delete_edges] THEN
    USE_THEN "spokes" (fun spokes_th ->
     USE_THEN "index" (fun index_th ->
      ACCEPT_TAC(MATCH_MP (SPEC `i:num` spokes_th) index_th)));
    POP_ASSUM(LABEL_TAC "induction") THEN
    X_GEN_TAC `i:num` THEN
    INTRO_TAC "injective avoids spokes lower index" THEN
    REWRITE_TAC[fan_delete_edges; IN_DELETE] THEN
    CONJ_TAC THENL
     [SUBGOAL_THEN `(t:num) <= i` (LABEL_TAC "old_lower") THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `INJ (w:num->A) (cyclic_indices m) (:A) /\
        (!j. j < m ==> ~(w j = x)) /\
        (!j. j < m ==> {x,w j} IN E) /\
        t <= i /\ i < m`
      (LABEL_TAC "old_data") THENL
       [ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "induction" (fun induction_th ->
       USE_THEN "old_data" (fun data_th ->
        ACCEPT_TAC(MATCH_MP (SPEC `i:num` induction_th) data_th)));
      DISCH_THEN(LABEL_TAC "same_edge") THEN
      SUBGOAL_THEN `(w:num->A) i = w t` (LABEL_TAC "same_vertex") THENL
       [SUBGOAL_THEN `(w:num->A) i IN {x,w t}`
        (LABEL_TAC "member") THENL
         [USE_THEN "same_edge" (fun th -> REWRITE_TAC[GSYM th]) THEN
          REWRITE_TAC[IN_INSERT; IN_SING];
          ALL_TAC] THEN
        USE_THEN "member" MP_TAC THEN
        REWRITE_TAC[IN_INSERT; IN_SING] THEN
        DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "wi_x")
          (LABEL_TAC "wi_wt")) THENL
         [USE_THEN "avoids" (MP_TAC o SPEC `i:num`) THEN
          ANTS_TAC THENL
           [USE_THEN "index" ACCEPT_TAC;
            DISCH_THEN(LABEL_TAC "not_wi_x")] THEN
          USE_THEN "not_wi_x" (fun not_th ->
           USE_THEN "wi_x" (fun eq_th ->
            CONTR_TAC(MP (NOT_ELIM not_th) eq_th)));
          USE_THEN "wi_wt" ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `(i:num) = t` (LABEL_TAC "same_index") THENL
       [USE_THEN "injective" MP_TAC THEN
        REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
        DISCH_THEN(MATCH_MP_TAC o SPECL [`i:num`; `t:num`]) THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "index" ACCEPT_TAC;
          ASM_ARITH_TAC;
          USE_THEN "same_vertex" ACCEPT_TAC];
        ASM_ARITH_TAC]]]);;

let FAN_DELETE_NONINCIDENT_EDGE_REMAINS = prove
 (`!x:A. !w:num->A. !E t e.
        e IN E /\
        ~(x IN e)
        ==> e IN fan_delete_edges x w E t`,
  REPEAT GEN_TAC THEN INTRO_TAC "edge avoids" THEN
  SPEC_TAC(`t:num`,`t:num`) THEN INDUCT_TAC THENL
   [ASM_REWRITE_TAC[fan_delete_edges];
    POP_ASSUM(LABEL_TAC "induction") THEN
    REWRITE_TAC[fan_delete_edges; IN_DELETE] THEN
    CONJ_TAC THENL
     [USE_THEN "induction" ACCEPT_TAC;
      USE_THEN "avoids" MP_TAC THEN SET_TAC[]]]);;

let EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !m t.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E) /\
        t < m
        ==> euler_planar_rotation
             V (fan_delete_edges x w E t)
             (fan_delete_rotation x w r t) /\
            connected_graph V (fan_delete_edges x w E t)`,
  REPEAT GEN_TAC THEN SPEC_TAC(`t:num`,`t:num`) THEN
  INDUCT_TAC THENL
   [INTRO_TAC
     "euler connected injective avoids spokes chain positive" THEN
    ASM_REWRITE_TAC[fan_delete_edges; fan_delete_rotation];
    POP_ASSUM(LABEL_TAC "induction") THEN
    INTRO_TAC
     "euler connected injective avoids spokes chain suc_bound" THEN
    SUBGOAL_THEN `(t:num) < m` (LABEL_TAC "bound") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "induction" MP_TAC THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      INTRO_TAC "old_euler old_connected"] THEN
    SUBGOAL_THEN
     `{x:A,w t} IN fan_delete_edges x w E t`
    (LABEL_TAC "deleted_edge") THENL
     [MATCH_MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
        `t:num`; `t:num`]
       FAN_DELETE_EDGE_REMAINS) THEN
      ASM_REWRITE_TAC[LE_REFL];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{x:A,w(t + 1)} IN fan_delete_edges x w E (SUC t)`
    (LABEL_TAC "next_spoke") THENL
     [MATCH_MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
        `SUC t`; `t + 1:num`]
       FAN_DELETE_EDGE_REMAINS) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{w(t + 1),w t:A} IN fan_delete_edges x w E (SUC t)`
    (LABEL_TAC "chain_edge") THENL
     [MATCH_MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `SUC t`;
        `{w(t + 1),w t:A}:A->bool`]
       FAN_DELETE_NONINCIDENT_EDGE_REMAINS) THEN
      CONJ_TAC THENL
       [ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
        USE_THEN "chain" MATCH_MP_TAC THEN ASM_ARITH_TAC;
        REWRITE_TAC[IN_INSERT; IN_SING] THEN
        DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "x_next")
          (LABEL_TAC "x_current")) THENL
         [USE_THEN "avoids" (MP_TAC o SPEC `t + 1:num`) THEN
          ANTS_TAC THENL
           [ASM_ARITH_TAC;
            DISCH_THEN(LABEL_TAC "next_not_x")] THEN
          USE_THEN "next_not_x" (fun not_th ->
           USE_THEN "x_next" (fun eq_th ->
            CONTR_TAC(MP (NOT_ELIM not_th) (SYM eq_th))));
          USE_THEN "avoids" (MP_TAC o SPEC `t:num`) THEN
          ANTS_TAC THENL
           [ASM_ARITH_TAC;
            DISCH_THEN(LABEL_TAC "current_not_x")] THEN
          USE_THEN "current_not_x" (fun not_th ->
           USE_THEN "x_current" (fun eq_th ->
            CONTR_TAC(MP (NOT_ELIM not_th) (SYM eq_th))))]];
      ALL_TAC] THEN
    SUBGOAL_THEN `~((x:A) = (w:num->A) (t:num))`
    (LABEL_TAC "distinct") THENL
     [ONCE_REWRITE_TAC[EQ_SYM_EQ] THEN
      USE_THEN "avoids" (MP_TAC o SPEC `t:num`) THEN
      ANTS_TAC THENL
       [USE_THEN "bound" ACCEPT_TAC;
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
    `connected_graph (V:A->bool) (fan_delete_edges x w E (SUC t))`
    (LABEL_TAC "new_connected") THENL
     [REWRITE_TAC[fan_delete_edges] THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`;
        `fan_delete_edges
          (x:A) (w:num->A) (E:(A->bool)->bool) t`;
        `x:A`; `(w:num->A)t`; `(w:num->A)(t + 1)`]
       CONNECTED_GRAPH_DELETE_TRIANGLE_EDGE) THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "old_connected" ACCEPT_TAC;
        USE_THEN "distinct" ACCEPT_TAC;
        USE_THEN "next_spoke"
         (ACCEPT_TAC o REWRITE_RULE[fan_delete_edges]);
        USE_THEN "chain_edge"
         (ACCEPT_TAC o REWRITE_RULE[fan_delete_edges])];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `euler_planar_rotation
       (V:A->bool) (fan_delete_edges x w E (SUC t))
       (fan_delete_rotation x w r (SUC t))`
    (LABEL_TAC "new_euler") THENL
     [REWRITE_TAC[fan_delete_edges; fan_delete_rotation] THEN
      MATCH_MP_TAC EULER_PLANAR_ROTATION_DELETE_EDGE_CONNECTED THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "old_euler" ACCEPT_TAC;
        USE_THEN "deleted_edge" ACCEPT_TAC;
        USE_THEN "new_connected" MP_TAC THEN
        REWRITE_TAC[fan_delete_edges] THEN DISCH_THEN ACCEPT_TAC];
      USE_THEN "new_euler" (fun euler_th ->
       USE_THEN "new_connected" (fun connected_th ->
        ACCEPT_TAC(CONJ euler_th connected_th)))]]);;

let FAN_DELETE_SPOKE_DARTS_REMAIN = prove
 (`!x:A. !w:num->A. !E m t i.
        INJ w (cyclic_indices m) (:A) /\
        (!j. j < m ==> ~(w j = x)) /\
        (!j. j < m ==> {x,w j} IN E) /\
        t <= i /\ i < m
        ==> (x,w i) IN graph_darts (fan_delete_edges x w E t) /\
            (w i,x) IN graph_darts (fan_delete_edges x w E t)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective avoids spokes lower index" THEN
  SUBGOAL_THEN
   `{x:A,w i} IN fan_delete_edges x w E t`
  (LABEL_TAC "edge") THENL
   [MATCH_MP_TAC(ISPECL
     [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
      `t:num`; `i:num`]
     FAN_DELETE_EDGE_REMAINS) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR] THEN CONJ_TAC THENL
     [USE_THEN "edge" ACCEPT_TAC;
      ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
      USE_THEN "edge" ACCEPT_TAC]]);;

let FAN_DELETE_NONINCIDENT_DART_REMAINS = prove
 (`!x a b:A. !w:num->A. !E t.
        (a,b) IN graph_darts E /\
        ~(a = x) /\ ~(b = x)
        ==> (a,b) IN graph_darts (fan_delete_edges x w E t)`,
  REPEAT GEN_TAC THEN INTRO_TAC "dart a_avoids b_avoids" THEN
  REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR] THEN
  MATCH_MP_TAC FAN_DELETE_NONINCIDENT_EDGE_REMAINS THEN
  CONJ_TAC THENL
   [USE_THEN "dart" (ACCEPT_TAC o REWRITE_RULE
     [IN_GRAPH_DARTS; DART_EDGE_PAIR]);
    ASM SET_TAC[]]);;

let EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX_GRAPH_DATA = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !m t.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E) /\
        t < m
        ==> finite_simple_graph V (fan_delete_edges x w E t) /\
            graph_rotation
             (fan_delete_edges x w E t)
             (fan_delete_rotation x w r t)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "data") THEN
  MP_TAC(MATCH_MP
   EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX
   (ASSUME
    `euler_planar_rotation (V:A->bool) E r /\
     connected_graph V E /\
     INJ w (cyclic_indices m) (:A) /\
     (!i. i < m ==> ~(w i = x)) /\
     (!i. i < m ==> {x,w i} IN E) /\
     (!i. i + 1 < m ==> {w i,w(i + 1)} IN E) /\
     t < m`)) THEN
  REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[]);;

let FAN_DELETE_FACE_SUCCESSOR_NONINCIDENT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x a b c d:A. !w:num->A. !m t.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E) /\
        (a,b) IN graph_darts E /\
        graph_face_successor E r (a,b) = (c,d) /\
        ~(a = x) /\ ~(b = x) /\ ~(c = x) /\ ~(d = x) /\
        t < m
        ==> graph_face_successor
             (fan_delete_edges x w E t)
             (fan_delete_rotation x w r t) (a,b) = (c,d)`,
  REPEAT GEN_TAC THEN SPEC_TAC(`t:num`,`t:num`) THEN
  INDUCT_TAC THENL
   [INTRO_TAC
     "euler connected injective avoids spokes chain dart successor \
      a_avoids b_avoids c_avoids d_avoids bound" THEN
    ASM_REWRITE_TAC[fan_delete_edges; fan_delete_rotation];
    POP_ASSUM(LABEL_TAC "induction") THEN
    INTRO_TAC
     "euler connected injective avoids spokes chain dart successor \
      a_avoids b_avoids c_avoids d_avoids suc_bound" THEN
    SUBGOAL_THEN `(t:num) < m` (LABEL_TAC "bound") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_face_successor
       (fan_delete_edges x w E t)
       (fan_delete_rotation x w r t) ((a:A),b) = ((c:A),d)`
    (LABEL_TAC "old_successor") THENL
     [USE_THEN "induction" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `finite_simple_graph
        (V:A->bool) (fan_delete_edges x w E t) /\
      graph_rotation
        (fan_delete_edges x w E t)
        (fan_delete_rotation x w r t)`
    (CONJUNCTS_THEN2 (LABEL_TAC "old_graph")
      (LABEL_TAC "old_rotation")) THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `x:A`; `w:num->A`; `m:num`; `t:num`]
       EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX_GRAPH_DATA) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{x:A,w t} IN fan_delete_edges x w E t`
    (LABEL_TAC "deleted_edge") THENL
     [MATCH_MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
        `t:num`; `t:num`]
       FAN_DELETE_EDGE_REMAINS) THEN
      ASM_REWRITE_TAC[LE_REFL];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `((a:A),b) IN graph_darts
       (fan_delete_edges x w E (SUC t))`
    (LABEL_TAC "new_dart") THENL
     [MATCH_MP_TAC FAN_DELETE_NONINCIDENT_DART_REMAINS THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[fan_delete_edges; fan_delete_rotation] THEN
    USE_THEN "old_successor" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`;
      `fan_delete_edges
        (x:A) (w:num->A) (E:(A->bool)->bool) t`;
      `fan_delete_rotation
        (x:A) (w:num->A) (r:(A#A)->A#A) t`;
      `x:A`; `(w:num->A)t`; `((a:A),b):A#A`]
     GRAPH_FACE_SUCCESSOR_DELETE_EDGE_UNCHANGED) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[PAIR_EQ] THEN REPEAT CONJ_TAC THENL
     [USE_THEN "new_dart"
       (ACCEPT_TAC o REWRITE_RULE[fan_delete_edges]);
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "c_is_x") (K ALL_TAC)) THEN
      USE_THEN "c_avoids" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "c_is_x" ACCEPT_TAC;
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "d_is_x")) THEN
      USE_THEN "d_avoids" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "d_is_x" ACCEPT_TAC]]);;

let GRAPH_FACE_SUCCESSOR_DELETE_EDGE_UNCHANGED_VALUE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v a b c d:A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E /\
        (a,b) IN graph_darts (E DELETE {u,v}) /\
        graph_face_successor E r (a,b) = (c,d) /\
        ~(c = u /\ d = v) /\
        ~(c = v /\ d = u)
        ==> graph_face_successor
             (E DELETE {u,v}) (graph_delete_rotation r u v) (a,b) =
            (c,d)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph rotation edge dart successor not_forward not_reverse" THEN
  USE_THEN "successor" (fun th -> REWRITE_TAC[GSYM th]) THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `((a:A),b):A#A`]
   GRAPH_FACE_SUCCESSOR_DELETE_EDGE_UNCHANGED) THEN
  ASM_REWRITE_TAC[PAIR_EQ]);;

let GRAPH_FACE_SUCCESSOR_DELETE_EDGE_FORWARD_SPLICE_VALUE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v a b c d:A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E /\
        (a,b) IN graph_darts (E DELETE {u,v}) /\
        graph_face_successor E r (a,b) = (u,v) /\
        graph_face_successor E r (v,u) = (c,d)
        ==> graph_face_successor
             (E DELETE {u,v}) (graph_delete_rotation r u v) (a,b) =
            (c,d)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation edge dart successor splice" THEN
  USE_THEN "splice" (fun th -> REWRITE_TAC[GSYM th]) THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `((a:A),b):A#A`]
   GRAPH_FACE_SUCCESSOR_DELETE_EDGE_FORWARD_SPLICE) THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_FACE_SUCCESSOR_DELETE_EDGE_REVERSE_SPLICE_VALUE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v a b c d:A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        {u,v} IN E /\
        (a,b) IN graph_darts (E DELETE {u,v}) /\
        graph_face_successor E r (a,b) = (v,u) /\
        graph_face_successor E r (u,v) = (c,d)
        ==> graph_face_successor
             (E DELETE {u,v}) (graph_delete_rotation r u v) (a,b) =
            (c,d)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation edge dart successor splice" THEN
  USE_THEN "splice" (fun th -> REWRITE_TAC[GSYM th]) THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `v:A`; `((a:A),b):A#A`]
     GRAPH_FACE_SUCCESSOR_DELETE_EDGE_REVERSE_SPLICE) THEN
  ASM_REWRITE_TAC[]);;

let INJ_CYCLIC_INDICES_NE = prove
 (`!w:num->A. !m i j.
        INJ w (cyclic_indices m) (:A) /\
        i < m /\ j < m /\ ~(i = j)
        ==> ~(w i = w j)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective i_index j_index distinct" THEN
  DISCH_THEN(LABEL_TAC "same") THEN
  USE_THEN "distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
  USE_THEN "injective" MP_TAC THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
  DISCH_THEN(MP_TAC o SPECL [`i:num`; `j:num`]) THEN
  ASM_REWRITE_TAC[]);;

let FAN_DELETE_CHAIN_DART_REMAINS = prove
 (`!x:A. !w:num->A. !E m t i.
        (!j. j < m ==> ~(w j = x)) /\
        (!j. j + 1 < m ==> {w j,w(j + 1)} IN E) /\
        i + 1 < m
        ==> (w i,w(i + 1)) IN
            graph_darts (fan_delete_edges x w E t)`,
  REPEAT GEN_TAC THEN INTRO_TAC "avoids chain index" THEN
  MATCH_MP_TAC FAN_DELETE_NONINCIDENT_DART_REMAINS THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR] THEN
    USE_THEN "chain" MATCH_MP_TAC THEN
    USE_THEN "index" ACCEPT_TAC;
    USE_THEN "avoids" (MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      DISCH_THEN ACCEPT_TAC];
    USE_THEN "avoids" (MP_TAC o SPEC `i + 1:num`) THEN
    ANTS_TAC THENL
     [USE_THEN "index" ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC]]);;

let FAN_DELETE_UNDELETED_TRIANGLE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !m t j.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E) /\
        (!i. i + 1 < m
             ==> graph_face_successor E r (x,w i) =
                   (w i,w(i + 1)) /\
                 graph_face_successor E r (w i,w(i + 1)) =
                   (w(i + 1),x) /\
                 graph_face_successor E r (w(i + 1),x) =
                   (x,w i)) /\
        t <= j /\ j + 1 < m
        ==> graph_face_successor
             (fan_delete_edges x w E t)
             (fan_delete_rotation x w r t) (x,w j) =
              (w j,w(j + 1)) /\
            graph_face_successor
             (fan_delete_edges x w E t)
             (fan_delete_rotation x w r t) (w j,w(j + 1)) =
              (w(j + 1),x) /\
            graph_face_successor
             (fan_delete_edges x w E t)
             (fan_delete_rotation x w r t) (w(j + 1),x) =
              (x,w j)`,
  REPEAT GEN_TAC THEN SPEC_TAC(`t:num`,`t:num`) THEN
  INDUCT_TAC THENL
   [INTRO_TAC
     "euler connected injective avoids spokes chain triangles lower index" THEN
    REWRITE_TAC[fan_delete_edges; fan_delete_rotation] THEN
    USE_THEN "triangles" MATCH_MP_TAC THEN
    USE_THEN "index" ACCEPT_TAC;
    POP_ASSUM(LABEL_TAC "induction") THEN
    INTRO_TAC
     "euler connected injective avoids spokes chain triangles lower index" THEN
    SUBGOAL_THEN `(t:num) < j` (LABEL_TAC "strict_lower") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(t:num) < m` (LABEL_TAC "bound") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_face_successor
       (fan_delete_edges x w E t)
       (fan_delete_rotation x w r t) ((x:A),w j) =
        (w j,w(j + 1)) /\
      graph_face_successor
       (fan_delete_edges x w E t)
       (fan_delete_rotation x w r t) ((w:num->A) j,w(j + 1)) =
        (w(j + 1),x) /\
      graph_face_successor
       (fan_delete_edges x w E t)
       (fan_delete_rotation x w r t) ((w:num->A) (j + 1),x) =
        (x,w j)`
    (CONJUNCTS_THEN2 (LABEL_TAC "old_first")
      (CONJUNCTS_THEN2 (LABEL_TAC "old_second")
        (LABEL_TAC "old_third"))) THENL
     [USE_THEN "induction" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `finite_simple_graph
        (V:A->bool) (fan_delete_edges x w E t) /\
      graph_rotation
        (fan_delete_edges x w E t)
        (fan_delete_rotation x w r t)`
    (CONJUNCTS_THEN2 (LABEL_TAC "old_graph")
      (LABEL_TAC "old_rotation")) THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `x:A`; `w:num->A`; `m:num`; `t:num`]
       EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX_GRAPH_DATA) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{x:A,w t} IN fan_delete_edges x w E t`
    (LABEL_TAC "deleted_edge") THENL
     [MATCH_MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
        `t:num`; `t:num`]
       FAN_DELETE_EDGE_REMAINS) THEN
      ASM_REWRITE_TAC[LE_REFL];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x:A,w j) IN graph_darts (fan_delete_edges x w E (SUC t)) /\
      (w j,x) IN graph_darts (fan_delete_edges x w E (SUC t))`
    (CONJUNCTS_THEN2 (LABEL_TAC "new_forward")
      (LABEL_TAC "new_reverse")) THENL
     [MATCH_MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
       `SUC t`; `j:num`]
       FAN_DELETE_SPOKE_DARTS_REMAIN) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x:A,w(j + 1)) IN
        graph_darts (fan_delete_edges x w E (SUC t)) /\
      (w(j + 1),x) IN
        graph_darts (fan_delete_edges x w E (SUC t))`
    (CONJUNCTS_THEN2 (LABEL_TAC "new_next_forward")
      (LABEL_TAC "new_next_reverse")) THENL
     [MATCH_MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
        `SUC t`; `j + 1:num`]
       FAN_DELETE_SPOKE_DARTS_REMAIN) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(w j,w(j + 1):A) IN
       graph_darts (fan_delete_edges x w E (SUC t))`
    (LABEL_TAC "new_chain") THENL
     [MATCH_MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
        `SUC t`; `j:num`]
       FAN_DELETE_CHAIN_DART_REMAINS) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `~((w:num->A) j = w t)`
    (LABEL_TAC "current_distinct") THENL
     [MATCH_MP_TAC(ISPECL
       [`w:num->A`; `m:num`; `j:num`; `t:num`]
       INJ_CYCLIC_INDICES_NE) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((w:num->A) (j + 1) = w t)`
    (LABEL_TAC "next_distinct") THENL
     [MATCH_MP_TAC(ISPECL
       [`w:num->A`; `m:num`; `j + 1:num`; `t:num`]
       INJ_CYCLIC_INDICES_NE) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((w:num->A) j = x)`
    (LABEL_TAC "current_avoids") THENL
     [USE_THEN "avoids" MATCH_MP_TAC THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((w:num->A) (j + 1) = x)`
    (LABEL_TAC "next_avoids") THENL
     [USE_THEN "avoids" MATCH_MP_TAC THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_face_successor
       (fan_delete_edges x w E (SUC t))
       (fan_delete_rotation x w r (SUC t)) ((x:A),w j) =
        (w j,w(j + 1))`
    (LABEL_TAC "new_first") THENL
     [REWRITE_TAC[fan_delete_edges; fan_delete_rotation] THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`;
        `fan_delete_edges
          (x:A) (w:num->A) (E:(A->bool)->bool) t`;
        `fan_delete_rotation
          (x:A) (w:num->A) (r:(A#A)->A#A) t`;
        `x:A`; `(w:num->A)t`; `x:A`; `(w:num->A)j`;
        `(w:num->A)j`; `(w:num->A)(j + 1)`]
       GRAPH_FACE_SUCCESSOR_DELETE_EDGE_UNCHANGED_VALUE) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "new_forward"
       (ACCEPT_TAC o REWRITE_RULE[fan_delete_edges]);
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_face_successor
       (fan_delete_edges x w E (SUC t))
       (fan_delete_rotation x w r (SUC t))
       ((w:num->A) j,w(j + 1)) =
        (w(j + 1),x)`
    (LABEL_TAC "new_second") THENL
     [REWRITE_TAC[fan_delete_edges; fan_delete_rotation] THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`;
        `fan_delete_edges
          (x:A) (w:num->A) (E:(A->bool)->bool) t`;
        `fan_delete_rotation
          (x:A) (w:num->A) (r:(A#A)->A#A) t`;
        `x:A`; `(w:num->A)t`; `(w:num->A)j`;
        `(w:num->A)(j + 1)`; `(w:num->A)(j + 1)`; `x:A`]
       GRAPH_FACE_SUCCESSOR_DELETE_EDGE_UNCHANGED_VALUE) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "new_chain"
       (ACCEPT_TAC o REWRITE_RULE[fan_delete_edges]);
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_face_successor
       (fan_delete_edges x w E (SUC t))
       (fan_delete_rotation x w r (SUC t))
       ((w:num->A) (j + 1),x) =
        (x,w j)`
    (LABEL_TAC "new_third") THENL
     [REWRITE_TAC[fan_delete_edges; fan_delete_rotation] THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`;
        `fan_delete_edges
          (x:A) (w:num->A) (E:(A->bool)->bool) t`;
        `fan_delete_rotation
          (x:A) (w:num->A) (r:(A#A)->A#A) t`;
        `x:A`; `(w:num->A)t`; `(w:num->A)(j + 1)`;
        `x:A`; `x:A`; `(w:num->A)j`]
       GRAPH_FACE_SUCCESSOR_DELETE_EDGE_UNCHANGED_VALUE) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "new_next_reverse"
       (ACCEPT_TAC o REWRITE_RULE[fan_delete_edges]);
      ASM_REWRITE_TAC[]]]);;

let FAN_DELETE_FACE_SUCCESSOR_NONINCIDENT_FROM = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x a b c d:A. !w:num->A. !m s t.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E) /\
        (a,b) IN graph_darts E /\
        graph_face_successor
         (fan_delete_edges x w E s)
         (fan_delete_rotation x w r s) (a,b) = (c,d) /\
        ~(a = x) /\ ~(b = x) /\ ~(c = x) /\ ~(d = x) /\
        s <= t /\ t < m
        ==> graph_face_successor
             (fan_delete_edges x w E t)
             (fan_delete_rotation x w r t) (a,b) = (c,d)`,
  REPEAT GEN_TAC THEN SPEC_TAC(`s:num`,`s:num`) THEN
  SPEC_TAC(`t:num`,`t:num`) THEN INDUCT_TAC THENL
   [X_GEN_TAC `s:num` THEN
    INTRO_TAC
     "euler connected injective avoids spokes chain dart at_stage \
      a_avoids b_avoids c_avoids d_avoids lower bound" THEN
    SUBGOAL_THEN `(s:num) = 0` SUBST_ALL_TAC THENL
     [ASM_ARITH_TAC;
      USE_THEN "at_stage" ACCEPT_TAC];
    POP_ASSUM(LABEL_TAC "induction") THEN X_GEN_TAC `s:num` THEN
    INTRO_TAC
     "euler connected injective avoids spokes chain dart at_stage \
      a_avoids b_avoids c_avoids d_avoids lower suc_bound" THEN
    ASM_CASES_TAC `(s:num) = SUC t` THENL
     [FIRST_X_ASSUM SUBST_ALL_TAC THEN
      USE_THEN "at_stage" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(s:num) <= t` (LABEL_TAC "old_lower") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(t:num) < m` (LABEL_TAC "old_bound") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_face_successor
       (fan_delete_edges x w E t)
       (fan_delete_rotation x w r t) ((a:A),b) = (c,d)`
    (LABEL_TAC "old_successor") THENL
     [USE_THEN "induction" (MATCH_MP_TAC o SPEC `s:num`) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `finite_simple_graph
        (V:A->bool) (fan_delete_edges x w E t) /\
      graph_rotation
        (fan_delete_edges x w E t)
        (fan_delete_rotation x w r t)`
    (CONJUNCTS_THEN2 (LABEL_TAC "old_graph")
      (LABEL_TAC "old_rotation")) THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `x:A`; `w:num->A`; `m:num`; `t:num`]
       EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX_GRAPH_DATA) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{x:A,w t} IN fan_delete_edges x w E t`
    (LABEL_TAC "deleted_edge") THENL
     [MATCH_MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
        `t:num`; `t:num`]
       FAN_DELETE_EDGE_REMAINS) THEN
      ASM_REWRITE_TAC[LE_REFL];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(a:A,b) IN graph_darts (fan_delete_edges x w E (SUC t))`
    (LABEL_TAC "new_dart") THENL
     [MATCH_MP_TAC FAN_DELETE_NONINCIDENT_DART_REMAINS THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[fan_delete_edges; fan_delete_rotation] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`;
      `fan_delete_edges
        (x:A) (w:num->A) (E:(A->bool)->bool) t`;
      `fan_delete_rotation
        (x:A) (w:num->A) (r:(A#A)->A#A) t`;
      `x:A`; `(w:num->A)t`; `a:A`; `b:A`; `c:A`; `d:A`]
     GRAPH_FACE_SUCCESSOR_DELETE_EDGE_UNCHANGED_VALUE) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "new_dart"
     (ACCEPT_TAC o REWRITE_RULE[fan_delete_edges])]);;

let FAN_DELETE_TAIL_SUCCESSOR = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !m t.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E) /\
        (!i. i + 1 < m
             ==> graph_face_successor E r (x,w i) =
                   (w i,w(i + 1)) /\
                 graph_face_successor E r (w i,w(i + 1)) =
                   (w(i + 1),x) /\
                 graph_face_successor E r (w(i + 1),x) =
                   (x,w i)) /\
        0 < t /\ t < m
        ==> graph_face_successor
             (fan_delete_edges x w E t)
             (fan_delete_rotation x w r t)
             (w(t - 1),w t) = (w t,x)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
  "euler connected injective avoids spokes chain triangles positive bound" THEN
  SUBGOAL_THEN `?j. (t:num) = SUC j`
  (X_CHOOSE_THEN `j:num` SUBST_ALL_TAC) THENL
   [MP_TAC(SPEC `t:num` num_CASES) THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "zero")
      (X_CHOOSE_THEN `j:num` (LABEL_TAC "successor"))) THENL
     [USE_THEN "positive" MP_TAC THEN
      USE_THEN "zero" (fun th -> REWRITE_TAC[th]) THEN ARITH_TAC;
      EXISTS_TAC `j:num` THEN USE_THEN "successor" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor
     (fan_delete_edges x w E j)
     (fan_delete_rotation x w r j)
     ((w:num->A) j,w(j + 1)) = (w(j + 1),x)`
  (LABEL_TAC "old_successor") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `x:A`; `w:num->A`; `m:num`; `j:num`; `j:num`]
     FAN_DELETE_UNDELETED_TRIANGLE) THEN
    ASM_REWRITE_TAC[LE_REFL] THEN ANTS_TAC THENL
     [ASM_ARITH_TAC;
      MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph
      (V:A->bool) (fan_delete_edges x w E j) /\
    graph_rotation
      (fan_delete_edges x w E j)
      (fan_delete_rotation x w r j)`
  (CONJUNCTS_THEN2 (LABEL_TAC "old_graph")
    (LABEL_TAC "old_rotation")) THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `x:A`; `w:num->A`; `m:num`; `j:num`]
     EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX_GRAPH_DATA) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{x:A,w j} IN fan_delete_edges x w E j`
  (LABEL_TAC "deleted_edge") THENL
   [MATCH_MP_TAC(ISPECL
     [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
      `j:num`; `j:num`]
     FAN_DELETE_EDGE_REMAINS) THEN
    ASM_REWRITE_TAC[LE_REFL] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((w:num->A) j,w(j + 1)) IN
    graph_darts (fan_delete_edges x w E (SUC j))`
  (LABEL_TAC "new_dart") THENL
   [MATCH_MP_TAC(ISPECL
     [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
      `SUC j`; `j:num`]
     FAN_DELETE_CHAIN_DART_REMAINS) THEN
