let FAN_DELETE_CHAIN_SUCCESSOR = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !m t i.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
        (!j. j < m ==> ~(w j = x)) /\
        (!j. j < m ==> {x,w j} IN E) /\
        (!j. j + 1 < m ==> {w j,w(j + 1)} IN E) /\
        (!j. j + 1 < m
             ==> graph_face_successor E r (x,w j) =
                   (w j,w(j + 1)) /\
                 graph_face_successor E r (w j,w(j + 1)) =
                   (w(j + 1),x) /\
                 graph_face_successor E r (w(j + 1),x) =
                   (x,w j)) /\
        i + 1 < t /\ t < m
        ==> graph_face_successor
             (fan_delete_edges x w E t)
             (fan_delete_rotation x w r t)
             (w i,w(i + 1)) = (w(i + 1),w(i + 2))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected injective avoids spokes chain triangles index bound" THEN
  SUBGOAL_THEN
   `((w:num->A) i,w(i + 1)) IN graph_darts E`
  (LABEL_TAC "dart") THENL
   [REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR] THEN
    USE_THEN "chain" MATCH_MP_TAC THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor
     (fan_delete_edges x w E (i + 2))
     (fan_delete_rotation x w r (i + 2))
     ((w:num->A) i,w(i + 1)) = (w(i + 1),w(i + 2))`
  (LABEL_TAC "at_splice") THENL
   [MATCH_MP_TAC(REWRITE_RULE
     [ADD1; ARITH_RULE `(i + 1) + 1 = i + 2`]
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
       `x:A`; `w:num->A`; `m:num`; `i:num`]
      FAN_DELETE_CHAIN_SUCCESSOR_AT_SPLICE)) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
