  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `x:A`; `(w:num->A)i`; `(w:num->A)(i + 1)`;
    `(w:num->A)(i + 1)`; `(w:num->A)(i + 2)`;
    `w:num->A`; `m:num`; `i + 2:num`; `t:num`]
   FAN_DELETE_FACE_SUCCESSOR_NONINCIDENT_FROM) THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [USE_THEN "avoids" MATCH_MP_TAC THEN ASM_ARITH_TAC;
    USE_THEN "avoids" MATCH_MP_TAC THEN ASM_ARITH_TAC;
    USE_THEN "avoids" MATCH_MP_TAC THEN ASM_ARITH_TAC;
    USE_THEN "avoids" MATCH_MP_TAC THEN ASM_ARITH_TAC;
    ASM_ARITH_TAC]);;

let FAN_DELETE_PREDECESSOR_SUCCESSOR_AT_FIRST = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x p:A. !w:num->A. !m.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E) /\
        (!i. i + 1 < m
             ==> graph_face_successor E r (x,w i) =
                   (w i,w(i + 1)) /\
                 graph_face_successor E r (w i,w(i + 1)) =
                   (w(i + 1),x) /\
                 graph_face_successor E r (w(i + 1),x) =
                   (x,w i)) /\
        (p,w 0) IN graph_darts E /\
        graph_face_successor E r (p,w 0) = (w 0,x) /\
        ~(p = x) /\
        2 <= m
        ==> graph_face_successor
             (fan_delete_edges x w E 1)
             (fan_delete_rotation x w r 1)
             (p,w 0) = (w 0,w 1)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected injective avoids spokes chain triangles dart \
    old_predecessor p_avoids bound" THEN
