    ALL_TAC] THEN
  SUBGOAL_THEN `{x:A,w 0} IN E` (LABEL_TAC "deleted_edge") THENL
   [USE_THEN "spokes" MATCH_MP_TAC THEN
    USE_THEN "bound" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A)
      ((x:A),w 0) = (w 0,w 1)`
  (LABEL_TAC "old_forward") THENL
