       (CONJUNCTS_THEN2 (LABEL_TAC "second") (LABEL_TAC "third"))) THEN
      USE_THEN "first" (ACCEPT_TAC o REWRITE_RULE[ADD_CLAUSES])];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((p:A),w 0) IN graph_darts (fan_delete_edges x w E 1)`
  (LABEL_TAC "new_dart") THENL
   [MATCH_MP_TAC FAN_DELETE_NONINCIDENT_DART_REMAINS THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "avoids" MATCH_MP_TAC THEN
    USE_THEN "bound" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[ARITH_RULE `1 = SUC 0`;
              fan_delete_edges; fan_delete_rotation] THEN
  REWRITE_TAC[ADD1; ADD_CLAUSES] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `x:A`; `(w:num->A)0`; `p:A`; `(w:num->A)0`;
