let FAN_DELETE_SPOKE_SUCCESSOR_REMAINS = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x c d:A. !w:num->A. !m j t.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E) /\
        graph_face_successor E r (x,w j) = (c,d) /\
        ~(c = x) /\ ~(d = x) /\
        t <= j /\ j < m
        ==> graph_face_successor
             (fan_delete_edges x w E t)
             (fan_delete_rotation x w r t)
             (x,w j) = (c,d)`,
  REPEAT GEN_TAC THEN SPEC_TAC(`t:num`,`t:num`) THEN
  INDUCT_TAC THENL
   [INTRO_TAC
     "euler connected injective avoids spokes chain successor \
      c_avoids d_avoids lower index" THEN
    ASM_REWRITE_TAC[fan_delete_edges; fan_delete_rotation];
    POP_ASSUM(LABEL_TAC "induction") THEN
    INTRO_TAC
     "euler connected injective avoids spokes chain successor \
      c_avoids d_avoids lower index" THEN
    SUBGOAL_THEN `(t:num) <= j` (LABEL_TAC "old_lower") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(t:num) < m` (LABEL_TAC "old_bound") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_face_successor
       (fan_delete_edges x w E t)
       (fan_delete_rotation x w r t)
       ((x:A),w j) = (c,d)`
    (LABEL_TAC "old_successor") THENL
     [USE_THEN "induction" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `finite_simple_graph
        (V:A->bool) (fan_delete_edges x w E t) /\
      graph_rotation
        (fan_delete_edges x w E t)
        (fan_delete_rotation x w r t)`
    (CONJUNCTS_THEN2 (LABEL_TAC "old_graph")
      (LABEL_TAC "old_rotation")) THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `x:A`; `w:num->A`; `m:num`; `t:num`]
       EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX_GRAPH_DATA) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{x:A,w t} IN fan_delete_edges x w E t`
    (LABEL_TAC "deleted_edge") THENL
     [MATCH_MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
        `t:num`; `t:num`]
       FAN_DELETE_EDGE_REMAINS) THEN
      ASM_REWRITE_TAC[LE_REFL];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `((x:A),w j) IN
      graph_darts (fan_delete_edges x w E (SUC t))`
    (LABEL_TAC "new_dart") THENL
     [MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
        `SUC t`; `j:num`]
       FAN_DELETE_SPOKE_DARTS_REMAIN) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "forward")
          (LABEL_TAC "reverse")) THEN
        USE_THEN "forward" ACCEPT_TAC];
      ALL_TAC] THEN
    REWRITE_TAC[fan_delete_edges; fan_delete_rotation] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`;
      `fan_delete_edges
        (x:A) (w:num->A) (E:(A->bool)->bool) t`;
      `fan_delete_rotation
        (x:A) (w:num->A) (r:(A#A)->A#A) t`;
      `x:A`; `(w:num->A)t`; `x:A`; `(w:num->A)j`; `c:A`; `d:A`]
     GRAPH_FACE_SUCCESSOR_DELETE_EDGE_UNCHANGED_VALUE) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "new_dart"
     (ACCEPT_TAC o REWRITE_RULE[fan_delete_edges])]);;

let FAN_DELETE_GRAPH_NEIGHBORS_LAST = prove
 (`!E:(A->bool)->bool. !x:A. !w:num->A. !m.
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        graph_neighbors E x = cyclic_vertices w m /\
        1 <= m
        ==> graph_neighbors (fan_delete_edges x w E (m - 1)) x =
            {w(m - 1)}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "injective avoids spokes neighbors positive" THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `y:A` THEN
  REWRITE_TAC[IN_SING] THEN EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "current_neighbor") THEN
    SUBGOAL_THEN `(y:A) IN graph_neighbors E x`
    (LABEL_TAC "old_neighbor") THENL
     [REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
      MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (ISPECL [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m - 1`]
        FAN_DELETE_EDGES_SUBSET)) THEN
      USE_THEN "current_neighbor" MP_TAC THEN
      REWRITE_TAC[IN_GRAPH_NEIGHBORS];
      ALL_TAC] THEN
    USE_THEN "old_neighbor" MP_TAC THEN
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    DISCH_THEN(X_CHOOSE_THEN `i:num`
     (CONJUNCTS_THEN2 (LABEL_TAC "index") (LABEL_TAC "value"))) THEN
    ASM_CASES_TAC `(i:num) < m - 1` THENL
     [FIRST_X_ASSUM(LABEL_TAC "deleted_index") THEN
      MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m - 1`; `i:num`]
       FAN_DELETE_EDGE_REMOVED) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(LABEL_TAC "removed") THEN
      USE_THEN "current_neighbor" MP_TAC THEN
      REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
      USE_THEN "value" (fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(LABEL_TAC "still_present") THEN
      USE_THEN "removed" (fun removed_th ->
       USE_THEN "still_present" (fun present_th ->
        CONTR_TAC(MP (NOT_ELIM removed_th) present_th)));
      SUBGOAL_THEN `(i:num) = m - 1` (LABEL_TAC "last_index") THENL
       [ASM_ARITH_TAC;
        USE_THEN "value" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "last_index" (fun th -> REWRITE_TAC[th])]];
    DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
    MATCH_MP_TAC(ISPECL
     [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
      `m - 1`; `m - 1`]
     FAN_DELETE_EDGE_REMAINS) THEN
    ASM_REWRITE_TAC[LE_REFL] THEN ASM_ARITH_TAC]);;

let FAN_DELETE_PENDANT_REMAINDER_NONEMPTY = prove
  (`!E:(A->bool)->bool. !x:A. !w:num->A. !m.
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E) /\
        2 <= m
        ==> ~(fan_delete_edges x w E (m - 1)
               DELETE {w(m - 1),x} = {})`,
  REPEAT GEN_TAC THEN INTRO_TAC "avoids chain bound" THEN
  SUBGOAL_THEN
   `{(w:num->A)(m - 2),w(m - 1)} IN E`
  (LABEL_TAC "chain_edge") THENL
   [SUBGOAL_THEN `(m - 2) + 1 = m - 1`
    (LABEL_TAC "next_index") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "next_index" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "chain" MATCH_MP_TAC THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((w:num->A)(m - 2) = x) /\ ~(w(m - 1) = x)`
  (CONJUNCTS_THEN2 (LABEL_TAC "first_avoids")
    (LABEL_TAC "last_avoids")) THENL
   [CONJ_TAC THEN USE_THEN "avoids" MATCH_MP_TAC THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{(w:num->A)(m - 2),w(m - 1)} IN
    fan_delete_edges x w E (m - 1)`
  (LABEL_TAC "chain_remains") THENL
   [MATCH_MP_TAC FAN_DELETE_NONINCIDENT_EDGE_REMAINS THEN
    ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~({(w:num->A)(m - 2),w(m - 1)} = {w(m - 1),x})`
  (LABEL_TAC "different_edge") THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
  EXISTS_TAC `{(w:num->A)(m - 2),w(m - 1)}:A->bool` THEN
  ASM_REWRITE_TAC[IN_DELETE]);;

let EULER_PLANAR_ROTATION_FAN_DELETE_LAST = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !m.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E) /\
        graph_neighbors E x = cyclic_vertices w m /\
        2 <= m
        ==> euler_planar_rotation
             (V DELETE x)
             (fan_delete_edges x w E (m - 1)
               DELETE {w(m - 1),x})
             (graph_delete_rotation
               (fan_delete_rotation x w r (m - 1))
               (w(m - 1)) x)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected injective avoids spokes chain neighbors bound" THEN
  SUBGOAL_THEN
   `euler_planar_rotation
      (V:A->bool) (fan_delete_edges x w E (m - 1))
      (fan_delete_rotation x w r (m - 1)) /\
    connected_graph V (fan_delete_edges x w E (m - 1))`
  (CONJUNCTS_THEN2 (LABEL_TAC "prefix_euler")
    (LABEL_TAC "prefix_connected")) THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `x:A`; `w:num->A`; `m:num`; `m - 1`]
     EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_neighbors (fan_delete_edges x w E (m - 1)) x =
    {(w:num->A)(m - 1)}`
  (LABEL_TAC "last_neighbor") THENL
   [MATCH_MP_TAC FAN_DELETE_GRAPH_NEIGHBORS_LAST THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(fan_delete_edges x w E (m - 1)
       DELETE {(w:num->A)(m - 1),x} = {})`
  (LABEL_TAC "remainder") THENL
   [MATCH_MP_TAC FAN_DELETE_PENDANT_REMAINDER_NONEMPTY THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `fan_delete_edges
      (x:A) (w:num->A) (E:(A->bool)->bool) (m - 1)`;
    `fan_delete_rotation
      (x:A) (w:num->A) (r:(A#A)->A#A) (m - 1)`;
    `(w:num->A)(m - 1)`; `x:A`]
   EULER_PLANAR_ROTATION_DELETE_PENDANT) THEN
  ASM_REWRITE_TAC[]);;

let FAN_DELETE_LAST_NONINCIDENT_SUCCESSOR = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x a b c d:A. !w:num->A. !m.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E) /\
        (a,b) IN graph_darts (fan_delete_edges x w E (m - 1)) /\
        graph_face_successor
         (fan_delete_edges x w E (m - 1))
         (fan_delete_rotation x w r (m - 1)) (a,b) = (c,d) /\
        ~(a = x) /\ ~(b = x) /\ ~(c = x) /\ ~(d = x) /\
        2 <= m
        ==> graph_face_successor
             (fan_delete_edges x w E (m - 1)
               DELETE {w(m - 1),x})
             (graph_delete_rotation
               (fan_delete_rotation x w r (m - 1))
               (w(m - 1)) x)
             (a,b) = (c,d)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected injective avoids spokes chain dart successor \
    a_avoids b_avoids c_avoids d_avoids bound" THEN
  SUBGOAL_THEN
   `finite_simple_graph
      (V:A->bool) (fan_delete_edges x w E (m - 1)) /\
    graph_rotation
      (fan_delete_edges x w E (m - 1))
      (fan_delete_rotation x w r (m - 1))`
  (CONJUNCTS_THEN2 (LABEL_TAC "old_graph")
    (LABEL_TAC "old_rotation")) THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `x:A`; `w:num->A`; `m:num`; `m - 1`]
     EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX_GRAPH_DATA) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{(w:num->A)(m - 1),x} IN fan_delete_edges x w E (m - 1)`
  (LABEL_TAC "deleted_edge") THENL
   [ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
    MATCH_MP_TAC(ISPECL
     [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
      `m - 1`; `m - 1`]
     FAN_DELETE_EDGE_REMAINS) THEN
    ASM_REWRITE_TAC[LE_REFL] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(a:A,b) IN graph_darts
    (fan_delete_edges x w E (m - 1) DELETE {w(m - 1),x})`
  (LABEL_TAC "new_dart") THENL
   [REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE; IN_DELETE; PAIR_EQ] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`;
    `fan_delete_edges
      (x:A) (w:num->A) (E:(A->bool)->bool) (m - 1)`;
    `fan_delete_rotation
      (x:A) (w:num->A) (r:(A#A)->A#A) (m - 1)`;
    `(w:num->A)(m - 1)`; `x:A`; `a:A`; `b:A`; `c:A`; `d:A`]
   GRAPH_FACE_SUCCESSOR_DELETE_EDGE_UNCHANGED_VALUE) THEN
  ASM_REWRITE_TAC[]);;

let FAN_DELETE_PENDANT_TAIL_SUCCESSOR = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x c d:A. !w:num->A. !m.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E) /\
        (!i. i + 1 < m
             ==> graph_face_successor E r (x,w i) =
                   (w i,w(i + 1)) /\
                 graph_face_successor E r (w i,w(i + 1)) =
                   (w(i + 1),x) /\
                 graph_face_successor E r (w(i + 1),x) =
                   (x,w i)) /\
        graph_face_successor E r (x,w(m - 1)) = (c,d) /\
        ~(c = x) /\ ~(d = x) /\
        2 <= m
        ==> graph_face_successor
             (fan_delete_edges x w E (m - 1)
               DELETE {w(m - 1),x})
             (graph_delete_rotation
               (fan_delete_rotation x w r (m - 1))
               (w(m - 1)) x)
             (w(m - 2),w(m - 1)) = (c,d)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected injective avoids spokes chain triangles \
    last_successor c_avoids d_avoids bound" THEN
  SUBGOAL_THEN
   `graph_face_successor
     (fan_delete_edges x w E (m - 1))
     (fan_delete_rotation x w r (m - 1))
     ((w:num->A)(m - 2),w(m - 1)) = (w(m - 1),x)`
  (LABEL_TAC "old_tail") THENL
   [MATCH_MP_TAC(REWRITE_RULE[ARITH_RULE `(m - 1) - 1 = m - 2`]
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
       `x:A`; `w:num->A`; `m:num`; `m - 1`]
      FAN_DELETE_TAIL_SUCCESSOR)) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor
     (fan_delete_edges x w E (m - 1))
     (fan_delete_rotation x w r (m - 1))
     ((x:A),w(m - 1)) = (c,d)`
  (LABEL_TAC "old_reverse") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `x:A`; `c:A`; `d:A`; `w:num->A`; `m:num`;
      `m - 1`; `m - 1`]
     FAN_DELETE_SPOKE_SUCCESSOR_REMAINS) THEN
    ASM_REWRITE_TAC[LE_REFL] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph
      (V:A->bool) (fan_delete_edges x w E (m - 1)) /\
    graph_rotation
      (fan_delete_edges x w E (m - 1))
      (fan_delete_rotation x w r (m - 1))`
  (CONJUNCTS_THEN2 (LABEL_TAC "old_graph")
    (LABEL_TAC "old_rotation")) THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `x:A`; `w:num->A`; `m:num`; `m - 1`]
     EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX_GRAPH_DATA) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{(w:num->A)(m - 1),x} IN fan_delete_edges x w E (m - 1)`
  (LABEL_TAC "deleted_edge") THENL
   [ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
    MATCH_MP_TAC(ISPECL
     [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
      `m - 1`; `m - 1`]
     FAN_DELETE_EDGE_REMAINS) THEN
    ASM_REWRITE_TAC[LE_REFL] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((w:num->A)(m - 2),w(m - 1)) IN graph_darts
    (fan_delete_edges x w E (m - 1) DELETE {w(m - 1),x})`
  (LABEL_TAC "new_dart") THENL
   [REWRITE_TAC[GRAPH_DARTS_DELETE_EDGE; IN_DELETE; PAIR_EQ] THEN
    SUBGOAL_THEN
     `((w:num->A)(m - 2),w(m - 1)) IN
      graph_darts (fan_delete_edges x w E (m - 1))`
    (LABEL_TAC "old_dart") THENL
     [SUBGOAL_THEN `(m - 2) + 1 = m - 1`
      (LABEL_TAC "next_index") THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `m:num`;
        `m - 1`; `m - 2`]
       FAN_DELETE_CHAIN_DART_REMAINS) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        DISCH_THEN(fun th ->
         USE_THEN "next_index" (fun ith ->
          ACCEPT_TAC(REWRITE_RULE[ith] th)))];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((w:num->A)(m - 2) = x) /\ ~(w(m - 1) = x)`
    (CONJUNCTS_THEN2 (LABEL_TAC "first_avoids")
      (LABEL_TAC "last_avoids")) THENL
     [CONJ_TAC THEN USE_THEN "avoids" MATCH_MP_TAC THEN ASM_ARITH_TAC;
     ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`;
    `fan_delete_edges
      (x:A) (w:num->A) (E:(A->bool)->bool) (m - 1)`;
    `fan_delete_rotation
      (x:A) (w:num->A) (r:(A#A)->A#A) (m - 1)`;
    `(w:num->A)(m - 1)`; `x:A`; `(w:num->A)(m - 2)`;
    `(w:num->A)(m - 1)`; `c:A`; `d:A`]
   GRAPH_FACE_SUCCESSOR_DELETE_EDGE_FORWARD_SPLICE_VALUE) THEN
  ASM_REWRITE_TAC[]);;

let CYCLIC_DELETE_LAST_FACE_SUCCESSORS_OF_LOCAL = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !q w:num->A. !n k.
        3 <= n /\
        w 0 = q(n - 2) /\
        w(k + 1) = q 0 /\
        (!i. i < n - 3
             ==> graph_face_successor E r (q i,q(i + 1)) =
                 (q(i + 1),q(i + 2))) /\
        graph_face_successor E r (q(n - 3),q(n - 2)) =
          (w 0,w 1) /\
        (!i. i < k
             ==> graph_face_successor E r (w i,w(i + 1)) =
                 (w(i + 1),w(i + 2))) /\
        graph_face_successor E r (w k,w(k + 1)) = (q 0,q 1)
        ==> cyclic_face_successors
             E r (cyclic_delete_last q w n) (n - 1 + k)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "nlarge first last prefix predecessor chain final" THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
  ASM_CASES_TAC `(i:num) < n - 3` THENL
   [FIRST_X_ASSUM(LABEL_TAC "early") THEN
    SUBGOAL_THEN
     `cyclic_dart (cyclic_delete_last (q:num->A) w n)
       (n - 1 + k) i = (q i,q(i + 1))`
    (LABEL_TAC "source_dart") THENL
     [MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_PREFIX_DART THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(i + 1) MOD (n - 1 + k) = i + 1`
    (LABEL_TAC "next_index") THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `cyclic_dart (cyclic_delete_last (q:num->A) w n)
       (n - 1 + k) (i + 1) = (q(i + 1),q(i + 2))`
    (LABEL_TAC "target_dart") THENL
     [MP_TAC(ISPECL
       [`q:num->A`; `w:num->A`; `n:num`; `k:num`; `i + 1`]
       CYCLIC_DELETE_LAST_FAN_PREFIX_DART) THEN
      ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[ARITH_RULE `(i + 1) + 1 = i + 2`]];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "prefix" MATCH_MP_TAC THEN USE_THEN "early" ACCEPT_TAC;
    ASM_CASES_TAC `(i:num) = n - 3` THENL
     [FIRST_X_ASSUM SUBST_ALL_TAC THEN
      SUBGOAL_THEN
       `cyclic_dart (cyclic_delete_last (q:num->A) w n)
         (n - 1 + k) (n - 3) = (q(n - 3),q(n - 2))`
      (LABEL_TAC "source_dart") THENL
       [MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_P_DART THEN
        USE_THEN "nlarge" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `((n - 3) + 1) MOD (n - 1 + k) = n - 2`
      (LABEL_TAC "next_index") THENL
       [TRANS_TAC EQ_TRANS `((n - 3) + 1)` THEN CONJ_TAC THENL
         [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
          ASM_ARITH_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `cyclic_dart (cyclic_delete_last (q:num->A) w n)
         (n - 1 + k) (n - 2) = (w 0,w 1)`
      (LABEL_TAC "target_dart") THENL
       [MATCH_MP_TAC(REWRITE_RULE[ADD_CLAUSES]
         (ISPECL
          [`q:num->A`; `w:num->A`; `n:num`; `k:num`; `0`]
          CYCLIC_DELETE_LAST_FAN_PATH_DART)) THEN
        ASM_REWRITE_TAC[LE_0];
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    ABBREV_TAC `j:num = i - (n - 2)` THEN
    POP_ASSUM(LABEL_TAC "j_definition") THEN
    SUBGOAL_THEN `i = n - 2 + j` (LABEL_TAC "i_index") THENL
     [USE_THEN "j_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(j:num) <= k` (LABEL_TAC "j_bound") THENL
     [USE_THEN "i_index" SUBST_ALL_TAC THEN
      USE_THEN "index" MP_TAC THEN
      USE_THEN "nlarge" MP_TAC THEN ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `cyclic_dart (cyclic_delete_last (q:num->A) w n)
       (n - 1 + k) i = (w j,w(j + 1))`
    (LABEL_TAC "source_dart") THENL
     [USE_THEN "i_index" (fun th -> REWRITE_TAC[th]) THEN
      MATCH_MP_TAC CYCLIC_DELETE_LAST_FAN_PATH_DART THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_CASES_TAC `(j:num) < k` THENL
     [FIRST_X_ASSUM(LABEL_TAC "before_last") THEN
      SUBGOAL_THEN
       `(i + 1) MOD (n - 1 + k) = n - 2 + (j + 1)`
      (LABEL_TAC "next_index") THENL
       [TRANS_TAC EQ_TRANS `(i + 1)` THEN CONJ_TAC THENL
         [MATCH_MP_TAC MOD_LT THEN
          USE_THEN "i_index" SUBST_ALL_TAC THEN
          USE_THEN "before_last" MP_TAC THEN
          USE_THEN "nlarge" MP_TAC THEN ARITH_TAC;
          USE_THEN "i_index" (fun th -> REWRITE_TAC[th]) THEN
          ARITH_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `cyclic_dart (cyclic_delete_last (q:num->A) w n)
         (n - 1 + k) (n - 2 + (j + 1)) =
        (w(j + 1),w(j + 2))`
      (LABEL_TAC "target_dart") THENL
       [MP_TAC(ISPECL
         [`q:num->A`; `w:num->A`; `n:num`; `k:num`; `j + 1`]
         CYCLIC_DELETE_LAST_FAN_PATH_DART) THEN
        ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
         [USE_THEN "before_last" MP_TAC THEN ARITH_TAC;
          REWRITE_TAC[ARITH_RULE `(j + 1) + 1 = j + 2`]];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "chain" MATCH_MP_TAC THEN
      USE_THEN "before_last" ACCEPT_TAC;
      FIRST_X_ASSUM(LABEL_TAC "not_before_last") THEN
      SUBGOAL_THEN `(j:num) = k` (LABEL_TAC "j_last") THENL
       [USE_THEN "j_bound" MP_TAC THEN
        USE_THEN "not_before_last" MP_TAC THEN ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(i:num) + 1 = n - 1 + k`
      (LABEL_TAC "after_last") THENL
       [USE_THEN "i_index" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "j_last" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "nlarge" MP_TAC THEN ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(i + 1) MOD (n - 1 + k) = 0`
      (LABEL_TAC "next_index") THENL
       [USE_THEN "after_last" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[MOD_REFL];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `cyclic_dart (cyclic_delete_last (q:num->A) w n)
         (n - 1 + k) 0 = (q 0,q 1)`
      (LABEL_TAC "target_dart") THENL
       [MATCH_MP_TAC(REWRITE_RULE[ADD_CLAUSES]
         (ISPECL
          [`q:num->A`; `w:num->A`; `n:num`; `k:num`; `0`]
          CYCLIC_DELETE_LAST_FAN_PREFIX_DART)) THEN
        ASM_REWRITE_TAC[] THEN
        USE_THEN "nlarge" MP_TAC THEN ARITH_TAC;
        ALL_TAC] THEN
      USE_THEN "j_last" SUBST_ALL_TAC THEN
      USE_THEN "source_dart" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "next_index" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "target_dart" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "final" ACCEPT_TAC]]);;

let CYCLIC_FACE_SUCCESSORS_PREFIX = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !q:num->A. !n i.
        cyclic_face_successors E r q n /\
        i + 2 < n
        ==> graph_face_successor E r (q i,q(i + 1)) =
            (q(i + 1),q(i + 2))`,
  REPEAT GEN_TAC THEN INTRO_TAC "successors index" THEN
  USE_THEN "successors" MP_TAC THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  DISCH_THEN(MP_TAC o SPEC `i:num`) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(LABEL_TAC "successor")] THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n i = (q i,q(i + 1))`
  (LABEL_TAC "source_dart") THENL
   [MATCH_MP_TAC CYCLIC_DART_NOWRAP THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(i + 1) MOD n = i + 1`
  (LABEL_TAC "next_index") THENL
   [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (q:num->A) n (i + 1) =
    (q(i + 1),q(i + 2))`
  (LABEL_TAC "target_dart") THENL
   [MP_TAC(ISPECL [`q:num->A`; `n:num`; `i + 1`]
     CYCLIC_DART_NOWRAP) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[ARITH_RULE `(i + 1) + 1 = i + 2`]];
    ALL_TAC] THEN
  (fun (asl,_ as g) ->
    let partial =
      SUBS [assoc "source_dart" asl; assoc "next_index" asl]
       (assoc "successor" asl) in
    ACCEPT_TAC (TRANS partial (assoc "target_dart" asl)) g));;

let FAN_DELETE_PENDANT_NONINCIDENT_SUCCESSOR = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x a b c d:A. !w:num->A. !m.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E) /\
        (a,b) IN graph_darts E /\
        graph_face_successor E r (a,b) = (c,d) /\
        ~(a = x) /\ ~(b = x) /\ ~(c = x) /\ ~(d = x) /\
        2 <= m
        ==> graph_face_successor
             (fan_delete_edges x w E (m - 1)
               DELETE {w(m - 1),x})
             (graph_delete_rotation
               (fan_delete_rotation x w r (m - 1))
               (w(m - 1)) x)
             (a,b) = (c,d)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected injective avoids spokes chain dart successor \
    a_avoids b_avoids c_avoids d_avoids bound" THEN
  SUBGOAL_THEN
   `graph_face_successor
     (fan_delete_edges x w E (m - 1))
     (fan_delete_rotation x w r (m - 1))
     ((a:A),b) = (c,d)`
  (LABEL_TAC "prefix_successor") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `x:A`; `a:A`; `b:A`; `c:A`; `d:A`; `w:num->A`; `m:num`;
      `m - 1`]
     FAN_DELETE_FACE_SUCCESSOR_NONINCIDENT) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(a:A,b) IN graph_darts (fan_delete_edges x w E (m - 1))`
  (LABEL_TAC "prefix_dart") THENL
   [MATCH_MP_TAC FAN_DELETE_NONINCIDENT_DART_REMAINS THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `x:A`; `a:A`; `b:A`; `c:A`; `d:A`; `w:num->A`; `m:num`]
   FAN_DELETE_LAST_NONINCIDENT_SUCCESSOR) THEN
  ASM_REWRITE_TAC[]);;

let FAN_DELETE_PENDANT_PREDECESSOR_SUCCESSOR = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x p:A. !w:num->A. !m.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
