        (!i. i + 1 < m
             ==> graph_face_successor E r (x,w i) =
                   (w i,w(i + 1)) /\
                 graph_face_successor E r (w i,w(i + 1)) =
                   (w(i + 1),x) /\
                 graph_face_successor E r (w(i + 1),x) =
                   (x,w i)) /\
        (p,w 0) IN graph_darts E /\
        graph_face_successor E r (p,w 0) = (w 0,x) /\
        ~(p = x) /\
        2 <= m
        ==> graph_face_successor
             (fan_delete_edges x w E (m - 1)
               DELETE {w(m - 1),x})
             (graph_delete_rotation
               (fan_delete_rotation x w r (m - 1))
               (w(m - 1)) x)
             (p,w 0) = (w 0,w 1)`,
