   `((p:A),w 0) IN graph_darts (fan_delete_edges x w E (m - 1))`
  (LABEL_TAC "prefix_dart") THENL
   [MATCH_MP_TAC FAN_DELETE_NONINCIDENT_DART_REMAINS THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "avoids" MATCH_MP_TAC THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `x:A`; `p:A`; `(w:num->A)0`; `(w:num->A)0`; `(w:num->A)1`;
    `w:num->A`; `m:num`]
   FAN_DELETE_LAST_NONINCIDENT_SUCCESSOR) THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [USE_THEN "avoids" MATCH_MP_TAC THEN ASM_ARITH_TAC;
    USE_THEN "avoids" MATCH_MP_TAC THEN ASM_ARITH_TAC;
    USE_THEN "avoids" MATCH_MP_TAC THEN ASM_ARITH_TAC]);;

let FAN_DELETE_PENDANT_CHAIN_SUCCESSOR = prove
