let CYCLIC_FACE_SUCCESSORS_THIRD_LAST = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !q:num->A. !n.
        cyclic_face_successors E r q n /\
        3 <= n
        ==> graph_face_successor E r (q(n - 3),q(n - 2)) =
