let FAN_DELETE_LAST_CYCLIC_FACE_SUCCESSORS = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !q w:num->A. !n k.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        simple_graph_cycle E q n /\
        cyclic_face_successors E r q n /\
        INJ w (cyclic_indices (k + 2)) (:A) /\
        (!i. i < k + 2 ==> ~(w i = q(n - 1))) /\
        (!i. i < k + 2 ==> {q(n - 1),w i} IN E) /\
        (!i. i + 1 < k + 2 ==> {w i,w(i + 1)} IN E) /\
        (!i. i + 1 < k + 2
             ==> graph_face_successor E r (q(n - 1),w i) =
                   (w i,w(i + 1)) /\
                 graph_face_successor E r (w i,w(i + 1)) =
                   (w(i + 1),q(n - 1)) /\
                 graph_face_successor E r (w(i + 1),q(n - 1)) =
                   (q(n - 1),w i)) /\
        w 0 = q(n - 2) /\
        w(k + 1) = q 0 /\
        3 <= n
        ==> cyclic_face_successors
             (fan_delete_edges (q(n - 1)) w E (k + 1)
               DELETE {w(k + 1),q(n - 1)})
             (graph_delete_rotation
               (fan_delete_rotation (q(n - 1)) w r (k + 1))
               (w(k + 1)) (q(n - 1)))
             (cyclic_delete_last q w n) (n - 1 + k)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected cycle old_successors injective avoids spokes chain \
    triangles first last nlarge" THEN
  USE_THEN "cycle" (MP_TAC o REWRITE_RULE[simple_graph_cycle]) THEN
  INTRO_TAC "cycle_large q_injective boundary_edges" THEN
  SUBGOAL_THEN
   `!i. i < n - 1 ==> ~((q:num->A)i = q(n - 1))`
  (LABEL_TAC "q_avoids") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    MATCH_MP_TAC(ISPECL
     [`q:num->A`; `n:num`; `i:num`; `n - 1`]
     INJ_CYCLIC_INDICES_NE) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "index" MP_TAC THEN
    USE_THEN "nlarge" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  ABBREV_TAC
   `E':(A->bool)->bool =
      fan_delete_edges ((q:num->A)(n - 1)) w E (k + 1)
       DELETE {w(k + 1),q(n - 1)}` THEN
  POP_ASSUM(LABEL_TAC "E'_definition") THEN
  ABBREV_TAC
   `r':(A#A)->A#A =
      graph_delete_rotation
       (fan_delete_rotation ((q:num->A)(n - 1)) w r (k + 1))
       (w(k + 1)) (q(n - 1))` THEN
  POP_ASSUM(LABEL_TAC "r'_definition") THEN
  SUBGOAL_THEN
   `!i. i < n - 3
        ==> graph_face_successor E' r'
             ((q:num->A)i,q(i + 1)) =
            (q(i + 1),q(i + 2))`
  (LABEL_TAC "new_prefix") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    SUBGOAL_THEN
     `graph_face_successor E (r:(A#A)->A#A)
       ((q:num->A)i,q(i + 1)) = (q(i + 1),q(i + 2))`
    (LABEL_TAC "old_prefix") THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `q:num->A`; `n:num`; `i:num`]
       CYCLIC_FACE_SUCCESSORS_PREFIX) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "index" MP_TAC THEN
      USE_THEN "nlarge" MP_TAC THEN ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `((q:num->A)i,q(i + 1)) IN graph_darts E`
    (LABEL_TAC "dart") THENL
     [SUBGOAL_THEN
       `cyclic_dart (q:num->A) n i = (q i,q(i + 1))`
      (LABEL_TAC "source_dart") THENL
       [MATCH_MP_TAC CYCLIC_DART_NOWRAP THEN
        USE_THEN "index" MP_TAC THEN
        USE_THEN "nlarge" MP_TAC THEN ARITH_TAC;
        ALL_TAC] THEN
      USE_THEN "source_dart" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DART THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "index" MP_TAC THEN
      USE_THEN "nlarge" MP_TAC THEN ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "E'_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "r'_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC(REWRITE_RULE[ARITH_RULE `(k + 2) - 1 = k + 1`]
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
       `(q:num->A)(n - 1)`; `(q:num->A)i`; `(q:num->A)(i + 1)`;
       `(q:num->A)(i + 1)`; `(q:num->A)(i + 2)`;
