      FAN_DELETE_PENDANT_NONINCIDENT_SUCCESSOR)) THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [USE_THEN "q_avoids" MATCH_MP_TAC THEN
      USE_THEN "index" MP_TAC THEN USE_THEN "nlarge" MP_TAC THEN ARITH_TAC;
      USE_THEN "q_avoids" MATCH_MP_TAC THEN
      USE_THEN "index" MP_TAC THEN USE_THEN "nlarge" MP_TAC THEN ARITH_TAC;
      USE_THEN "q_avoids" MATCH_MP_TAC THEN
