      ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E' r'
      ((q:num->A)(n - 3),q(n - 2)) = (w 0,w 1)`
  (LABEL_TAC "new_predecessor") THENL
   [SUBGOAL_THEN
     `graph_face_successor E (r:(A#A)->A#A)
