   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    USE_THEN "E'_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "r'_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC(REWRITE_RULE[ARITH_RULE `(k + 2) - 1 = k + 1`]
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
       `(q:num->A)(n - 1)`; `w:num->A`; `k + 2`; `i:num`]
      FAN_DELETE_PENDANT_CHAIN_SUCCESSOR)) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "index" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E' r'
      ((w:num->A)k,w(k + 1)) = (q 0,q 1)`
  (LABEL_TAC "new_final") THENL
   [SUBGOAL_THEN
     `graph_face_successor E (r:(A#A)->A#A)
       ((q:num->A)(n - 1),q 0) = (q 0,q 1)`
    (LABEL_TAC "old_final") THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `q:num->A`; `n:num`]
       CYCLIC_FACE_SUCCESSORS_LAST) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "E'_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "r'_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC(REWRITE_RULE
     [ARITH_RULE `(k + 2) - 1 = k + 1`;
      ARITH_RULE `(k + 2) - 2 = k`]
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
       `(q:num->A)(n - 1)`; `(q:num->A)0`; `(q:num->A)1`;
      `w:num->A`; `k + 2`]
      FAN_DELETE_PENDANT_TAIL_SUCCESSOR)) THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [USE_THEN "q_avoids" MATCH_MP_TAC THEN
      USE_THEN "nlarge" MP_TAC THEN ARITH_TAC;
      USE_THEN "q_avoids" MATCH_MP_TAC THEN
      USE_THEN "nlarge" MP_TAC THEN ARITH_TAC;
      ARITH_TAC];
    ALL_TAC] THEN
  USE_THEN "E'_definition" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "r'_definition" (fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC CYCLIC_DELETE_LAST_FACE_SUCCESSORS_OF_LOCAL THEN
  ASM_REWRITE_TAC[]);;

let FAN_DELETE_INDUCED_SUBGRAPH_EDGES = prove
 (`!V:A->bool. !E:(A->bool)->bool. !x:A. !w:num->A. !t.
        induced_subgraph_edges (fan_delete_edges x w E t) (V DELETE x) =
        induced_subgraph_edges E (V DELETE x)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[EXTENSION; IN_INDUCED_SUBGRAPH_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN EQ_TAC THENL
   [INTRO_TAC "current subset" THEN CONJ_TAC THENL
     [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (ISPECL [`x:A`; `w:num->A`; `E:(A->bool)->bool`; `t:num`]
        FAN_DELETE_EDGES_SUBSET)) THEN
      USE_THEN "current" ACCEPT_TAC;
      USE_THEN "subset" ACCEPT_TAC];
    INTRO_TAC "old subset" THEN CONJ_TAC THENL
     [MATCH_MP_TAC FAN_DELETE_NONINCIDENT_EDGE_REMAINS THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "subset" MP_TAC THEN SET_TAC[];
      USE_THEN "subset" ACCEPT_TAC]]);;

let FAN_DELETE_LAST_EDGES = prove
 (`!V:A->bool. !E:(A->bool)->bool. !x:A. !w:num->A. !m.
        finite_simple_graph V E /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        graph_neighbors E x = cyclic_vertices w m /\
        1 <= m
        ==> fan_delete_edges x w E (m - 1)
              DELETE {w(m - 1),x} =
            induced_subgraph_edges E (V DELETE x)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph injective avoids spokes neighbors positive" THEN
  SUBGOAL_THEN
   `finite_simple_graph
     (V:A->bool) (fan_delete_edges x w E (m - 1))`
  (LABEL_TAC "prefix_graph") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `fan_delete_edges x w E (m - 1):(A->bool)->bool`]
     FINITE_SIMPLE_GRAPH_SUBSET_EDGES) THEN
    ASM_REWRITE_TAC[FAN_DELETE_EDGES_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{x:A,w(m - 1)} IN fan_delete_edges x w E (m - 1)`
  (LABEL_TAC "last_edge") THENL
   [MATCH_MP_TAC(ISPECL
     [`x:A`; `w:num->A`; `E:(A->bool)->bool`;
      `m:num`; `m - 1`; `m - 1`]
     FAN_DELETE_EDGE_REMAINS) THEN
    ASM_REWRITE_TAC[LE_REFL] THEN
    USE_THEN "positive" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:A) IN V` (LABEL_TAC "x_vertex") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `fan_delete_edges
        (x:A) (w:num->A) (E:(A->bool)->bool) (m - 1)`;
      `x:A`; `(w:num->A)(m - 1)`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_neighbors (fan_delete_edges x w E (m - 1)) x =
    {(w:num->A)(m - 1)}`
  (LABEL_TAC "last_neighbor") THENL
   [MATCH_MP_TAC FAN_DELETE_GRAPH_NEIGHBORS_LAST THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`;
    `fan_delete_edges
      (x:A) (w:num->A) (E:(A->bool)->bool) (m - 1)`;
    `(w:num->A)(m - 1)`; `x:A`]
   FINITE_SIMPLE_GRAPH_PENDANT_DELETE_EDGE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun pendant_th ->
   ACCEPT_TAC(TRANS pendant_th
    (ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `x:A`;
      `w:num->A`; `m - 1`]
     FAN_DELETE_INDUCED_SUBGRAPH_EDGES))));;

let BOUNDARY_EULER_ROTATION_FAN_DELETE_LAST = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !q w:num->A. !n k.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        simple_graph_cycle E q n /\
        cyclic_face_successors E r q n /\
        INJ w (cyclic_indices (k + 2)) (:A) /\
        (!i. i < k + 2 ==> ~(w i = q(n - 1))) /\
        (!i. i < k + 2 ==> {q(n - 1),w i} IN E) /\
        (!i. i + 1 < k + 2 ==> {w i,w(i + 1)} IN E) /\
        (!i. i + 1 < k + 2
             ==> graph_face_successor E r (q(n - 1),w i) =
                   (w i,w(i + 1)) /\
                 graph_face_successor E r (w i,w(i + 1)) =
                   (w(i + 1),q(n - 1)) /\
                 graph_face_successor E r (w(i + 1),q(n - 1)) =
                   (q(n - 1),w i)) /\
        graph_neighbors E (q(n - 1)) =
          cyclic_vertices w (k + 2) /\
        w 0 = q(n - 2) /\
        w(k + 1) = q 0 /\
        3 <= n
        ==> boundary_euler_rotation
             (V DELETE q(n - 1))
             (induced_subgraph_edges E (V DELETE q(n - 1)))
             (cyclic_delete_last q w n) (n - 1 + k)
             (graph_delete_rotation
               (fan_delete_rotation (q(n - 1)) w r (k + 1))
               (w(k + 1)) (q(n - 1)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected cycle old_successors injective avoids spokes chain \
    triangles neighbors first last nlarge" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `euler_planar_rotation
     (V DELETE (q:num->A)(n - 1))
     (fan_delete_edges (q(n - 1)) w E (k + 1)
       DELETE {w(k + 1),q(n - 1)})
     (graph_delete_rotation
       (fan_delete_rotation (q(n - 1)) w r (k + 1))
       (w(k + 1)) (q(n - 1)))`
  (LABEL_TAC "new_euler") THENL
   [MATCH_MP_TAC(REWRITE_RULE[ARITH_RULE `(k + 2) - 1 = k + 1`]
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
       `(q:num->A)(n - 1)`; `w:num->A`; `k + 2`]
      EULER_PLANAR_ROTATION_FAN_DELETE_LAST)) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_face_successors
     (fan_delete_edges (q(n - 1)) w E (k + 1)
       DELETE {w(k + 1),q(n - 1)})
     (graph_delete_rotation
       (fan_delete_rotation (q(n - 1)) w r (k + 1))
       (w(k + 1)) (q(n - 1)))
     (cyclic_delete_last (q:num->A) w n) (n - 1 + k)`
  (LABEL_TAC "new_successors") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `q:num->A`; `w:num->A`; `n:num`; `k:num`]
     FAN_DELETE_LAST_CYCLIC_FACE_SUCCESSORS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `fan_delete_edges (q(n - 1)) w E (k + 1)
      DELETE {w(k + 1),q(n - 1)} =
    induced_subgraph_edges E (V DELETE (q:num->A)(n - 1))`
  (LABEL_TAC "new_edges") THENL
   [MATCH_MP_TAC(REWRITE_RULE[ARITH_RULE `(k + 2) - 1 = k + 1`]
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`;
       `(q:num->A)(n - 1)`; `w:num->A`; `k + 2`]
      FAN_DELETE_LAST_EDGES)) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "new_edges" (fun th -> REWRITE_TAC[GSYM th]) THEN
  MATCH_MP_TAC BOUNDARY_EULER_ROTATION_OF_CYCLIC_FACE_SUCCESSORS THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "nlarge" MP_TAC THEN ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* Package fan deletion as the maximal boundary descent step.                *)
(* ------------------------------------------------------------------------- *)

let MAXIMAL_BOUNDARY_EULER_ROTATION_DELETE_LAST_BOUNDARY = prove
 (`!V E r q n.
        boundary_euler_rotation (V:A->bool) E (q:num->A) n r /\
        simple_graph_cycle E q n /\
        connected_graph V E /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\
             E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s) /\
        3 <= CARD V
        ==> ?k w s.
              CARD(graph_neighbors E (q(n - 1))) = k + 2 /\
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = q(n - 2) /\
              w(k + 1) = q 0 /\
              cyclic_edges w (k + 2) SUBSET E /\
              boundary_euler_rotation
               (V DELETE q(n - 1))
               (induced_subgraph_edges E (V DELETE q(n - 1)))
               (cyclic_delete_last q w n) (n - 1 + k) s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "boundary cycle connected maximal vertices_large" THEN
  SUBGOAL_THEN `euler_planar_rotation (V:A->bool) E r`
  (LABEL_TAC "euler") THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "cycle" (MP_TAC o REWRITE_RULE[simple_graph_cycle]) THEN
  INTRO_TAC "nlarge q_injective boundary_edges" THEN
  SUBGOAL_THEN `cyclic_face_successors E (r:(A#A)->A#A) q n`
  (LABEL_TAC "old_successors") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `q:num->A`; `n:num`; `r:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_IMP_CYCLIC_FACE_SUCCESSORS) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "nlarge" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `q:num->A`; `n:num`]
   MAXIMAL_BOUNDARY_EULER_ROTATION_LAST_NEIGHBOR_FACES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@k w. length neighbors injective first last cycle_edges fan_faces" THEN
  SUBGOAL_THEN
   `!i. i < k + 2 ==> ~((w:num->A)i = q(n - 1))`
  (LABEL_TAC "avoids") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    SUBGOAL_THEN
     `(w:num->A)i IN graph_neighbors E ((q:num->A)(n - 1))`
    (LABEL_TAC "neighbor") THENL
     [USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `i:num` THEN
      ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
      ALL_TAC] THEN
    (fun (asl,_ as g) ->
      let data = MATCH_MP
       (ISPECL
        [`V:A->bool`; `E:(A->bool)->bool`;
         `(q:num->A)(n - 1)`; `(w:num->A)i`]
       FINITE_SIMPLE_GRAPH_NEIGHBOR)
       (CONJ (assoc "graph" asl) (assoc "neighbor" asl)) in
      ACCEPT_TAC
       (GEN_REWRITE_RULE RAND_CONV [EQ_SYM_EQ]
         (CONJUNCT2(CONJUNCT2 data))) g);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i < k + 2 ==> {(q:num->A)(n - 1),w i} IN E`
  (LABEL_TAC "spokes") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    REWRITE_TAC[GSYM IN_GRAPH_NEIGHBORS] THEN
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `i:num` THEN
      ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i + 1 < k + 2 ==> {(w:num->A)i,w(i + 1)} IN E`
  (LABEL_TAC "chain") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    USE_THEN "cycle_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `i:num` THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN
      USE_THEN "index" MP_TAC THEN ARITH_TAC;
      SUBGOAL_THEN `(i + 1) MOD (k + 2) = i + 1`
      SUBST1_TAC THENL
       [MATCH_MP_TAC MOD_LT THEN USE_THEN "index" ACCEPT_TAC;
        REFL_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i + 1 < k + 2
        ==> graph_face_successor
             (E:(A->bool)->bool) (r:(A#A)->A#A) (q(n - 1),w i) =
              (w i,w(i + 1)) /\
            graph_face_successor E r (w i,w(i + 1)) =
              (w(i + 1),q(n - 1)) /\
            graph_face_successor E r (w(i + 1),q(n - 1)) =
              (q(n - 1),w i)`
  (LABEL_TAC "triangles") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    (fun (asl,_ as g) ->
      let faces = MATCH_MP
       (SPEC `i:num` (assoc "fan_faces" asl))
       (assoc "index" asl) in
      ACCEPT_TAC (CONJUNCT2 faces) g);
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`k:num`; `w:num->A`;
    `graph_delete_rotation
      (fan_delete_rotation ((q:num->A)(n - 1)) w r (k + 1))
      (w(k + 1)) (q(n - 1)):(A#A)->A#A`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "length" ACCEPT_TAC;
    USE_THEN "neighbors" ACCEPT_TAC;
    USE_THEN "injective" ACCEPT_TAC;
    USE_THEN "first" ACCEPT_TAC;
    USE_THEN "last" ACCEPT_TAC;
    USE_THEN "cycle_edges" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `q:num->A`; `w:num->A`; `n:num`; `k:num`]
     BOUNDARY_EULER_ROTATION_FAN_DELETE_LAST) THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Maximal Euler rotations relative to a distinguished boundary face.        *)
(* ------------------------------------------------------------------------- *)

let maximal_boundary_euler_rotation = new_definition
 `maximal_boundary_euler_rotation
    (V:A->bool) (E:(A->bool)->bool) (q:num->A) n r <=>
    boundary_euler_rotation V E q n r /\
    (!E' s:(A#A)->A#A.
         E PSUBSET E' /\
         E' SUBSET complete_graph_edges V
         ==> ~boundary_euler_rotation V E' q n s)`;;

let MAXIMAL_EULER_PLANAR_BOUNDARY_ROTATION = prove
 (`!V E r q n.
        boundary_euler_rotation (V:A->bool) E (q:num->A) n r /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\
             E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s)
        ==> maximal_boundary_euler_rotation V E q n r`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[maximal_boundary_euler_rotation] THEN
  MESON_TAC[boundary_euler_rotation]);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_IMP_BOUNDARY = prove
 (`!V E q n r.
        maximal_boundary_euler_rotation (V:A->bool) E (q:num->A) n r
        ==> boundary_euler_rotation V E q n r`,
  REWRITE_TAC[maximal_boundary_euler_rotation] THEN MESON_TAC[]);;

let BOUNDARY_EULER_ROTATION_MAXIMAL_EXTENSION = prove
 (`!V E q n r.
        boundary_euler_rotation (V:A->bool) E (q:num->A) n r
        ==> ?E' r'.
              E SUBSET E' /\
              maximal_boundary_euler_rotation V E' q n r'`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "boundary") THEN
  ABBREV_TAC
   `candidates = {E':(A->bool)->bool |
       E SUBSET E' /\
       E' SUBSET complete_graph_edges V /\
       ?r':(A#A)->A#A.
          boundary_euler_rotation V E' q n r'}` THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite_vertices") THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation; euler_planar_rotation;
                FINITE_SIMPLE_GRAPH_EQ] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `E SUBSET complete_graph_edges (V:A->bool)`
  (LABEL_TAC "edges") THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation; euler_planar_rotation;
                FINITE_SIMPLE_GRAPH_EQ] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(candidates:((A->bool)->bool)->bool)`
  (LABEL_TAC "finite_candidates") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `{E':(A->bool)->bool |
                 E' SUBSET complete_graph_edges V}` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_POWERSET THEN
      MATCH_MP_TAC FINITE_COMPLETE_GRAPH_EDGES THEN
      USE_THEN "finite_vertices" ACCEPT_TAC;
      EXPAND_TAC "candidates" THEN
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(candidates:((A->bool)->bool)->bool = {})`
  (LABEL_TAC "candidates_nonempty") THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `E:(A->bool)->bool` THEN
    EXPAND_TAC "candidates" THEN
    REWRITE_TAC[IN_ELIM_THM; SUBSET_REFL] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPEC `candidates:((A->bool)->bool)->bool`
    FINITE_MAXIMAL_ELEMENT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `E':(A->bool)->bool`
   (CONJUNCTS_THEN2 (LABEL_TAC "candidate")
    (LABEL_TAC "maximal"))) THEN
  USE_THEN "candidate" MP_TAC THEN
  EXPAND_TAC "candidates" THEN REWRITE_TAC[IN_ELIM_THM] THEN
  INTRO_TAC "contains within (@r'. extended_boundary)" THEN
  MAP_EVERY EXISTS_TAC
   [`E':(A->bool)->bool`; `r':(A#A)->A#A`] THEN
  ASM_REWRITE_TAC[maximal_boundary_euler_rotation] THEN
  MAP_EVERY X_GEN_TAC
   [`E'':(A->bool)->bool`; `s:(A#A)->A#A`] THEN
  INTRO_TAC "proper allowed" THEN
  DISCH_THEN(LABEL_TAC "larger_boundary") THEN
  USE_THEN "maximal" (MP_TAC o SPEC `E'':(A->bool)->bool`) THEN
  ANTS_TAC THENL
   [EXPAND_TAC "candidates" THEN REWRITE_TAC[IN_ELIM_THM] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `E':(A->bool)->bool` THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "proper" MP_TAC THEN
      REWRITE_TAC[PSUBSET] THEN MESON_TAC[];
      ASM_MESON_TAC[]];
    ASM_MESON_TAC[]]);;

let SIMPLE_GRAPH_CYCLE_MONO = prove
 (`!E E':(A->bool)->bool. !q:num->A. !n.
        simple_graph_cycle E q n /\
        E SUBSET E'
        ==> simple_graph_cycle E' q n`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  MESON_TAC[SUBSET_TRANS]);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_FAN_REMAINDER = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q w:num->A. !n k.
   !r s:(A#A)->A#A.
        maximal_boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        graph_neighbors E (q(n - 1)) =
          cyclic_vertices w (k + 2) /\
        INJ w (cyclic_indices (k + 2)) (:A) /\
        w 0 = q(n - 2) /\
        w(k + 1) = q 0 /\
        3 <= n /\
        simple_graph_cycle
          (induced_subgraph_edges E (V DELETE q(n - 1)))
          (cyclic_delete_last q w n) (n - 1 + k) /\
        boundary_euler_rotation
          (V DELETE q(n - 1))
          (induced_subgraph_edges E (V DELETE q(n - 1)))
          (cyclic_delete_last q w n) (n - 1 + k) s
        ==> maximal_boundary_euler_rotation
             (V DELETE q(n - 1))
             (induced_subgraph_edges E (V DELETE q(n - 1)))
             (cyclic_delete_last q w n) (n - 1 + k) s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "maximal cycle neighbors injective first last nlarge
    new_cycle new_boundary" THEN
  SUBGOAL_THEN
   `boundary_euler_rotation (V:A->bool) E (q:num->A) n r`
  (LABEL_TAC "boundary") THENL
   [USE_THEN "maximal" MP_TAC THEN
    REWRITE_TAC[maximal_boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation; euler_planar_rotation] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:num->A)(n - 1) IN V`
  (LABEL_TAC "last_vertex") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`]
     FINITE_SIMPLE_GRAPH_CYCLE_VERTICES_SUBSET) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `n - 1:num` THEN
    ASM_REWRITE_TAC[IN_CYCLIC_INDICES] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_vertices (w:num->A) (k + 2) SUBSET
    V DELETE q(n - 1)`
  (LABEL_TAC "neighbor_vertices") THENL
   [USE_THEN "neighbors" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC GRAPH_NEIGHBORS_SUBSET_DELETE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:num->A)(n - 1) INSERT (V DELETE q(n - 1)) = V`
  (LABEL_TAC "vertices") THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `E =
    IMAGE (\u:A. {q(n - 1),u})
      (cyclic_vertices w (k + 2)) UNION
    induced_subgraph_edges E (V DELETE q(n - 1))`
  (LABEL_TAC "edges") THENL
   [USE_THEN "neighbors" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC FINITE_SIMPLE_GRAPH_DELETE_VERTEX_EDGES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[maximal_boundary_euler_rotation] THEN
  CONJ_TAC THENL
   [USE_THEN "new_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC
   [`E':(A->bool)->bool`; `t:(A#A)->A#A`] THEN
  INTRO_TAC "proper allowed" THEN
  DISCH_THEN(LABEL_TAC "larger_boundary") THEN
  SUBGOAL_THEN
   `simple_graph_cycle E'
     (cyclic_delete_last (q:num->A) w n) (n - 1 + k)`
  (LABEL_TAC "larger_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_MONO THEN
    EXISTS_TAC
     `induced_subgraph_edges (E:(A->bool)->bool)
       (V DELETE (q:num->A)(n - 1))` THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "proper"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[PSUBSET]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `boundary_euler_rotation
     ((q:num->A)(n - 1) INSERT (V DELETE q(n - 1)))
     (IMAGE (\u:A. {q(n - 1),u})
       (cyclic_vertices w (k + 2)) UNION E')
     q n
     (fan_rotation (q(n - 1)) w
       (q(n - 3),q(n - 2)) t (k + 1))`
  (LABEL_TAC "larger_fan") THENL
   [MATCH_MP_TAC(ISPECL
     [`V DELETE (q:num->A)(n - 1)`;
      `E':(A->bool)->bool`; `q:num->A`; `w:num->A`;
      `n:num`; `k:num`; `t:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_CYCLIC_FAN) THEN
    ASM_REWRITE_TAC[IN_DELETE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `E PSUBSET
    (IMAGE (\u:A. {q(n - 1),u})
      (cyclic_vertices w (k + 2)) UNION E')`
  (LABEL_TAC "larger_proper") THENL
   [USE_THEN "proper" MP_TAC THEN
    REWRITE_TAC[PSUBSET_ALT] THEN
    INTRO_TAC "old_subset @e. e_large e_new" THEN
    SUBGOAL_THEN
     `(e:A->bool) SUBSET V DELETE q(n - 1)`
    (LABEL_TAC "e_vertices") THENL
     [USE_THEN "allowed" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
      DISCH_THEN(MP_TAC o SPEC `e:A->bool`) THEN
      ASM_REWRITE_TAC[IN_COMPLETE_GRAPH_EDGES] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((e:A->bool) IN
        IMAGE (\u:A. {q(n - 1),u})
          (cyclic_vertices w (k + 2)))`
    (LABEL_TAC "e_not_star") THENL
     [DISCH_THEN(LABEL_TAC "star") THEN
      USE_THEN "star" MP_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
      INTRO_TAC "@u. u_cycle edge_pair" THEN
      USE_THEN "e_vertices" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
      DISCH_THEN(MP_TAC o SPEC `(q:num->A)(n - 1)`) THEN
      ASM_REWRITE_TAC[IN_DELETE; IN_INSERT];
      ALL_TAC] THEN
    USE_THEN "edges" SUBST1_TAC THEN
    REWRITE_TAC[PSUBSET_ALT] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[UNION_SUBSET] THEN CONJ_TAC THENL
       [MATCH_ACCEPT_TAC (CONJUNCT1 SUBSET_UNION);
        MATCH_MP_TAC SUBSET_TRANS THEN
        EXISTS_TAC `E':(A->bool)->bool` THEN
        ASM_REWRITE_TAC[] THEN
        MATCH_ACCEPT_TAC (CONJUNCT2 SUBSET_UNION)];
      EXISTS_TAC `e:A->bool` THEN ASM_REWRITE_TAC[IN_UNION]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(IMAGE (\u:A. {q(n - 1),u})
      (cyclic_vertices w (k + 2)) UNION E')
    SUBSET complete_graph_edges V`
  (LABEL_TAC "larger_allowed") THENL
   [USE_THEN "larger_fan" MP_TAC THEN
    USE_THEN "vertices" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[boundary_euler_rotation; euler_planar_rotation;
                FINITE_SIMPLE_GRAPH_EQ] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "maximal" MP_TAC THEN
  REWRITE_TAC[maximal_boundary_euler_rotation] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "old_maximal")) THEN
  SUBGOAL_THEN
   `~boundary_euler_rotation
      V
      (IMAGE (\u:A. {q(n - 1),u})
        (cyclic_vertices w (k + 2)) UNION E')
      q n
      (fan_rotation (q(n - 1)) w
        (q(n - 3),q(n - 2)) t (k + 1))`
  (LABEL_TAC "forbidden") THENL
   [USE_THEN "old_maximal" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "forbidden" (MATCH_MP_TAC o NOT_ELIM) THEN
  USE_THEN "vertices" (fun vertices_th ->
    USE_THEN "larger_fan"
     (ACCEPT_TAC o REWRITE_RULE[vertices_th])));;

let MAXIMAL_BOUNDARY_EULER_ROTATION_DELETE_LAST_CHORDLESS = prove
 (`!V E r q n.
        boundary_euler_rotation (V:A->bool) E (q:num->A) n r /\
        simple_graph_cycle E q n /\
        connected_graph V E /\
        (!E' s:(A#A)->A#A.
             E PSUBSET E' /\
             E' SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V E' s) /\
        3 <= CARD V /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        (4 <= n \/ 3 <= CARD(graph_neighbors E (q(n - 1))))
        ==> ?k w s.
              CARD(graph_neighbors E (q(n - 1))) = k + 2 /\
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = q(n - 2) /\
              w(k + 1) = q 0 /\
              cyclic_edges w (k + 2) SUBSET E /\
              simple_graph_cycle
               (induced_subgraph_edges E (V DELETE q(n - 1)))
               (cyclic_delete_last q w n) (n - 1 + k) /\
              maximal_boundary_euler_rotation
               (V DELETE q(n - 1))
               (induced_subgraph_edges E (V DELETE q(n - 1)))
               (cyclic_delete_last q w n) (n - 1 + k) s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "boundary cycle connected maximal vertices_large chordless \
    replacement_large" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation; euler_planar_rotation] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `q:num->A`; `n:num`]
   MAXIMAL_BOUNDARY_EULER_ROTATION_DELETE_LAST_BOUNDARY) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
  "@k w s. length neighbors injective first last cycle_edges new_boundary" THEN
  SUBGOAL_THEN `3 <= n` (LABEL_TAC "oldlarge") THENL
   [USE_THEN "cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `3 <= n - 1 + k` (LABEL_TAC "newlarge") THENL
   [USE_THEN "replacement_large" DISJ_CASES_TAC THENL
     [ASM_ARITH_TAC;
      USE_THEN "length" MP_TAC THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle
     (induced_subgraph_edges E (V DELETE q(n - 1)))
     (cyclic_delete_last (q:num->A) w n) (n - 1 + k)`
  (LABEL_TAC "new_cycle") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
      `n:num`; `k:num`; `w:num->A`]
     SIMPLE_GRAPH_CYCLE_DELETE_LAST_INDUCED) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `maximal_boundary_euler_rotation (V:A->bool) E q n r`
  (LABEL_TAC "boundary_maximal") THENL
   [MATCH_MP_TAC MAXIMAL_EULER_PLANAR_BOUNDARY_ROTATION THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `maximal_boundary_euler_rotation
     (V DELETE q(n - 1))
     (induced_subgraph_edges E (V DELETE q(n - 1)))
     (cyclic_delete_last (q:num->A) w n) (n - 1 + k) s`
  (LABEL_TAC "new_maximal") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `q:num->A`; `w:num->A`; `n:num`; `k:num`;
      `r:(A#A)->A#A`; `s:(A#A)->A#A`]
     MAXIMAL_BOUNDARY_EULER_ROTATION_FAN_REMAINDER) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`k:num`; `w:num->A`; `s:(A#A)->A#A`] THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Internal-face triangulation and fan descent under boundary maximality.    *)
(*                                                                           *)
(* Relative maximality does not force an edge across the distinguished outer *)
(* face.  The last boundary vertex therefore has an ordered neighbor path,   *)
(* rather than the closed neighbor cycle from absolute maximality.           *)
(* Internal sectors of that path are triangular.  Deleting the resulting fan *)
(* preserves the boundary Euler rotation, connectivity, and relative         *)
(* maximality; the chordless wrapper also preserves a simple boundary cycle. *)
(* ------------------------------------------------------------------------- *)

(* Boundary-preserving insertion into a face away from the outer boundary.   *)

let BOUNDARY_EULER_ROTATION_INSERT_EDGE_AWAY_FROM_BOUNDARY = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A. !d d':A#A.
        boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        d IN graph_darts E /\
        d' IN graph_face E r d /\
        ~(d IN cyclic_darts q n) /\
        ~(d' IN cyclic_darts q n) /\
        ~(SND d = SND d') /\
        ~({SND d,SND d'} IN E)
        ==> boundary_euler_rotation
             V ({SND d,SND d'} INSERT E)
             q n
             (permutation_insert
               (permutation_insert r
                 (SND d,SND d') (reverse_dart d))
               (SND d',SND d) (reverse_dart d'))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "boundary cycle dart cofacial d_internal d'_internal distinct new_edge" THEN
  SUBGOAL_THEN
   `euler_planar_rotation (V:A->bool) E (r:(A#A)->A#A)`
  (LABEL_TAC "euler") THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(d':A#A) IN graph_darts E`
  (LABEL_TAC "d'_dart") THENL
   [MATCH_MP_TAC
     (REWRITE_RULE[SUBSET]
       (MATCH_MP
         (ISPECL
           [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
           GRAPH_FACE_SUBSET_DARTS)
         (CONJ (ASSUME `graph_rotation E (r:(A#A)->A#A)`)
               (ASSUME `(d:A#A) IN graph_darts E`)))) THEN
    USE_THEN "cofacial" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `SND(d:A#A) IN V /\ SND(d':A#A) IN V`
  (CONJUNCTS_THEN2 (LABEL_TAC "d_head")
    (LABEL_TAC "d'_head")) THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `FST(d:A#A)`; `SND(d:A#A)`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[PAIR] THEN MESON_TAC[];
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `FST(d':A#A)`; `SND(d':A#A)`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[PAIR] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(d:A#A) IN outgoing_darts E (SND d) /\
    reverse_dart(d':A#A) IN outgoing_darts E (SND d')`
  (CONJUNCTS_THEN2 (LABEL_TAC "d_anchor")
    (LABEL_TAC "d'_anchor")) THENL
   [CONJ_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS; GRAPH_DARTS_REVERSE;
                FST_REVERSE_DART] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC
   `r' =
      permutation_insert
       (permutation_insert (r:(A#A)->A#A)
         (SND(d:A#A),SND(d':A#A)) (reverse_dart d))
       (SND(d':A#A),SND(d:A#A)) (reverse_dart d')` THEN
  SUBGOAL_THEN
   `euler_planar_rotation
      (V:A->bool)
      ({SND(d:A#A),SND(d':A#A)} INSERT E) r'`
  (LABEL_TAC "extended_euler") THENL
   [EXPAND_TAC "r'" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `SND(d:A#A)`; `SND(d':A#A)`;
      `reverse_dart(d:A#A)`; `reverse_dart(d':A#A)`]
     EULER_PLANAR_ROTATION_INSERT_EDGE) THEN
    ASM_REWRITE_TAC[REVERSE_DART_INVOLUTION];
    ALL_TAC] THEN
  SUBGOAL_THEN `cyclic_face_successors E r (q:num->A) n`
  (LABEL_TAC "old_successors") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `r:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_IMP_CYCLIC_FACE_SUCCESSORS) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN
    MESON_TAC[ARITH_RULE `3 <= n ==> 2 <= n`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_face_successors
      ({SND(d:A#A),SND(d':A#A)} INSERT E) r' q n`
  (LABEL_TAC "new_successors") THENL
   [REWRITE_TAC[cyclic_face_successors] THEN
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    SUBGOAL_THEN
     `cyclic_dart (q:num->A) n i IN graph_darts E`
    (LABEL_TAC "boundary_dart") THENL
     [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DART THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~(cyclic_dart (q:num->A) n i = d) /\
      ~(cyclic_dart q n i = d')`
    (CONJUNCTS_THEN2 (LABEL_TAC "not_d") (LABEL_TAC "not_d'")) THENL
     [CONJ_TAC THEN DISCH_THEN(LABEL_TAC "same") THENL
       [USE_THEN "d_internal" (MATCH_MP_TAC o NOT_ELIM) THEN
        USE_THEN "same" (SUBST1_TAC o SYM) THEN
        REWRITE_TAC[IN_CYCLIC_DARTS_CYCLIC_DART] THEN
        EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[];
        USE_THEN "d'_internal" (MATCH_MP_TAC o NOT_ELIM) THEN
        USE_THEN "same" (SUBST1_TAC o SYM) THEN
        REWRITE_TAC[IN_CYCLIC_DARTS_CYCLIC_DART] THEN
        EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    EXPAND_TAC "r'" THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `SND(d:A#A)`; `SND(d':A#A)`;
      `reverse_dart(d:A#A)`; `reverse_dart(d':A#A)`;
      `cyclic_dart (q:num->A) n i`]
     GRAPH_FACE_SUCCESSOR_INSERT_EDGE_UNCHANGED) THEN
    ASM_REWRITE_TAC[REVERSE_DART_INVOLUTION] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "old_successors" MP_TAC THEN
    REWRITE_TAC[cyclic_face_successors] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    USE_THEN "index" ACCEPT_TAC;
    ALL_TAC] THEN
  EXPAND_TAC "r'" THEN
  MATCH_MP_TAC BOUNDARY_EULER_ROTATION_OF_CYCLIC_FACE_SUCCESSORS THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  MESON_TAC[ARITH_RULE `3 <= n ==> 2 <= n`]);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_INTERNAL_COFACIAL_HEADS_ADJACENT =
  prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A. !d d':A#A.
        maximal_boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        d IN graph_darts E /\
        d' IN graph_face E r d /\
        DISJOINT (graph_face E r d) (cyclic_darts q n) /\
        ~(SND d = SND d')
        ==> {SND d,SND d'} IN E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "maximal cycle dart cofacial internal distinct" THEN
  ASM_CASES_TAC `({SND(d:A#A),SND(d':A#A)}:A->bool) IN E` THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(LABEL_TAC "new_edge") THEN
  SUBGOAL_THEN
   `boundary_euler_rotation
      (V:A->bool) E (q:num->A) n (r:(A#A)->A#A)`
  (LABEL_TAC "boundary") THENL
   [USE_THEN "maximal" MP_TAC THEN
    REWRITE_TAC[maximal_boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((d:A#A) IN cyclic_darts q n) /\
    ~((d':A#A) IN cyclic_darts q n)`
  (CONJUNCTS_THEN2 (LABEL_TAC "d_internal")
    (LABEL_TAC "d'_internal")) THENL
   [USE_THEN "internal" MP_TAC THEN
    REWRITE_TAC[DISJOINT] THEN
    USE_THEN "cofacial" MP_TAC THEN
    SET_TAC[GRAPH_FACE_REFL];
    ALL_TAC] THEN
  ABBREV_TAC
   `r' =
      permutation_insert
       (permutation_insert (r:(A#A)->A#A)
         (SND(d:A#A),SND(d':A#A)) (reverse_dart d))
