let MAXIMAL_BOUNDARY_EULER_ROTATION_INTERNAL_FACE_VERTICES_CLIQUE =
  prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A. !d:A#A.
        maximal_boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        d IN graph_darts E /\
        DISJOINT (graph_face E r d) (cyclic_darts q n)
        ==> !u v.
              u IN graph_rotation_face_vertices E r d /\
              v IN graph_rotation_face_vertices E r d /\
              ~(u = v)
              ==> {u,v} IN E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "maximal cycle dart internal" THEN
  SUBGOAL_THEN
   `boundary_euler_rotation
      (V:A->bool) E (q:num->A) n (r:(A#A)->A#A)`
  (LABEL_TAC "boundary") THENL
   [USE_THEN "maximal" MP_TAC THEN
    REWRITE_TAC[maximal_boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation; euler_planar_rotation] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`u:A`; `v:A`] THEN
  REWRITE_TAC[graph_rotation_face_vertices; IN_IMAGE] THEN
  INTRO_TAC
   "(@a. a_head a_face) (@b. b_head b_face) distinct" THEN
  SUBGOAL_THEN `(a:A#A) IN graph_darts E`
  (LABEL_TAC "a_dart") THENL
   [MATCH_MP_TAC
     (REWRITE_RULE[SUBSET]
       (MATCH_MP
         (ISPECL
           [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
           GRAPH_FACE_SUBSET_DARTS)
         (CONJ (ASSUME `graph_rotation E (r:(A#A)->A#A)`)
               (ASSUME `(d:A#A) IN graph_darts E`)))) THEN
    USE_THEN "a_face" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face E (r:(A#A)->A#A) (a:A#A) = graph_face E r d`
  (LABEL_TAC "same_face") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `d:A#A`; `a:A#A`] GRAPH_FACE_EQ) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(b:A#A) IN graph_face E r a`
  (LABEL_TAC "cofacial") THENL
   [USE_THEN "same_face" (fun th ->
      USE_THEN "b_face" (ACCEPT_TAC o REWRITE_RULE[GSYM th]));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `DISJOINT (graph_face E (r:(A#A)->A#A) (a:A#A))
             (cyclic_darts (q:num->A) n)`
  (LABEL_TAC "a_internal") THENL
   [USE_THEN "same_face" (fun th ->
      USE_THEN "internal" (ACCEPT_TAC o REWRITE_RULE[GSYM th]));
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
    `r:(A#A)->A#A`; `a:A#A`; `b:A#A`]
   MAXIMAL_BOUNDARY_EULER_ROTATION_INTERNAL_COFACIAL_HEADS_ADJACENT) THEN
  ASM_MESON_TAC[]);;

