   !r:(A#A)->A#A. !d:A#A.
        maximal_boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        connected_graph V E /\
        3 <= CARD V /\
        d IN graph_darts E /\
        DISJOINT (graph_face E r d) (cyclic_darts q n)
        ==> CARD(graph_rotation_face_vertices E r d) = 3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "maximal cycle connected vertices_large dart internal" THEN
  SUBGOAL_THEN
   `boundary_euler_rotation
      (V:A->bool) E (q:num->A) n (r:(A#A)->A#A)`
  (LABEL_TAC "boundary") THENL
   [USE_THEN "maximal" MP_TAC THEN
    REWRITE_TAC[maximal_boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation; euler_planar_rotation] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
    `r:(A#A)->A#A`; `d:A#A`]
   MAXIMAL_BOUNDARY_EULER_ROTATION_INTERNAL_FACE_VERTICES_CARD_LE_3) THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
   CONNECTED_SIMPLE_GRAPH_FACE_VERTICES_CARD_AT_LEAST_3) THEN
  ASM_REWRITE_TAC[] THEN ARITH_TAC);;

let CYCLIC_DART_ENTERING_LAST = prove
 (`!E:(A->bool)->bool. !q:num->A. !n. !v:A.
        simple_graph_cycle E q n /\
        (v,q(n - 1)) IN cyclic_darts q n
        ==> v = q(n - 2)`,
  REPEAT GEN_TAC THEN INTRO_TAC "cycle boundary_dart" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "nlarge injective edges" THEN
  USE_THEN "boundary_dart" MP_TAC THEN
  REWRITE_TAC[IN_CYCLIC_DARTS] THEN
  INTRO_TAC "@i. index dart" THEN
  SUBGOAL_THEN
   `(v:A) = (q:num->A) i /\
    q((i + 1) MOD n) = q(n - 1)`
  (CONJUNCTS_THEN2 (LABEL_TAC "tail") (LABEL_TAC "head")) THENL
   [USE_THEN "dart" MP_TAC THEN
    REWRITE_TAC[PAIR_EQ] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(i + 1) MOD n = n - 1`
  (LABEL_TAC "next_last") THENL
   [USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    DISCH_THEN(MATCH_MP_TAC o SPECL
     [`(i + 1) MOD n`; `n - 1`]) THEN
    ASM_REWRITE_TAC[] THEN
    ASM_SIMP_TAC[MOD_LT] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(i:num) = n - 2` (LABEL_TAC "previous") THENL
   [ASM_CASES_TAC `(i:num) + 1 < n` THENL
     [SUBGOAL_THEN `(i + 1) MOD n = i + 1`
      (LABEL_TAC "next_mod") THENL
       [MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[];
        ASM_ARITH_TAC];
      SUBGOAL_THEN `(i:num) = n - 1` (LABEL_TAC "i_last") THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `(i + 1) MOD n = 0`
        (LABEL_TAC "wrap") THENL
         [USE_THEN "i_last" (fun th -> REWRITE_TAC[th]) THEN
          SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
           [ASM_ARITH_TAC;
            REWRITE_TAC[MOD_REFL]];
          ASM_ARITH_TAC]]];
    ASM_REWRITE_TAC[]]);;

let BOUNDARY_EULER_ROTATION_NONBOUNDARY_FACE_DISJOINT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A. !d:A#A.
        boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        d IN graph_darts E /\
        ~(d IN cyclic_darts q n)
        ==> DISJOINT (graph_face E r d) (cyclic_darts q n)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "boundary cycle dart nonboundary" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation; euler_planar_rotation] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(q 0,q 1):A#A IN graph_darts E`
  (LABEL_TAC "boundary_anchor") THENL
   [SUBGOAL_THEN
     `cyclic_dart (q:num->A) n 0 = (q 0,q 1)`
    (LABEL_TAC "first_dart") THENL
     [REWRITE_TAC[cyclic_dart; PAIR_EQ; ADD_CLAUSES] THEN
      AP_TERM_TAC THEN MATCH_MP_TAC MOD_LT THEN
      USE_THEN "cycle" MP_TAC THEN
      REWRITE_TAC[simple_graph_cycle] THEN ARITH_TAC;
      MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `0`]
       SIMPLE_GRAPH_CYCLE_CYCLIC_DART) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        USE_THEN "cycle" MP_TAC THEN
        REWRITE_TAC[simple_graph_cycle] THEN ARITH_TAC;
        USE_THEN "first_dart" (fun th -> REWRITE_TAC[th])]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face E (r:(A#A)->A#A) (q 0,q 1) = cyclic_darts q n`
  (LABEL_TAC "boundary_face") THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(graph_face E (r:(A#A)->A#A) d =
      graph_face E r (q 0,q 1))`
  (LABEL_TAC "distinct_faces") THENL
   [DISCH_THEN(LABEL_TAC "same_face") THEN
    USE_THEN "nonboundary" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "boundary_face" (fun boundary_th ->
      USE_THEN "same_face" (fun same_th ->
       REWRITE_TAC[GSYM boundary_th; GSYM same_th])) THEN
    MATCH_ACCEPT_TAC GRAPH_FACE_REFL;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `d:A#A`; `(q 0,q 1):A#A`]
   DISTINCT_GRAPH_FACES_DISJOINT) THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "boundary_face" (fun th -> REWRITE_TAC[th]));;

let BOUNDARY_EULER_ROTATION_LAST_ORIENTED_NEIGHBOR_ENUMERATION =
  prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A.
        boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n
        ==> ?k w.
              CARD(graph_neighbors E (q(n - 1))) = k + 2 /\
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = q(n - 2) /\
              w(k + 1) = q 0 /\
              (!i. i + 1 < k + 2
                   ==> r(q(n - 1),w(i + 1)) =
                       (q(n - 1),w i))`,
  REPEAT GEN_TAC THEN INTRO_TAC "boundary cycle" THEN
  SUBGOAL_THEN `euler_planar_rotation (V:A->bool) E r`
  (LABEL_TAC "euler") THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `q:num->A`; `n:num`]
   SIMPLE_GRAPH_CYCLE_LAST_BOUNDARY_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "nlarge endpoints_distinct start_dart right_neighbor" THEN
  SUBGOAL_THEN
   `(q:num->A)(n - 2) IN graph_neighbors E (q(n - 1))`
  (LABEL_TAC "left_neighbor") THENL
   [USE_THEN "start_dart" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS_PAIR; IN_GRAPH_NEIGHBORS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `2 <= CARD(graph_neighbors (E:(A->bool)->bool) (q(n - 1)))`
  (LABEL_TAC "degree_large") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `(q:num->A)(n - 1)`;
      `(q:num->A)(n - 2)`; `(q:num->A) 0`]
     FINITE_GRAPH_TWO_DISTINCT_NEIGHBORS_CARD) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) (q(n - 1),q(n - 2)) = (q(n - 1),q 0)`
  (LABEL_TAC "boundary_step") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `r:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_LAST_ROTATION_STEP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `(q:num->A)(n - 1)`; `((q(n - 1),q(n - 2)):A#A)`]
   GRAPH_ROTATION_NEIGHBOR_ENUMERATION_STEPS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@z. neighbors injective first steps" THEN
  ABBREV_TAC
   `m = CARD(graph_neighbors
          (E:(A->bool)->bool) ((q:num->A)(n - 1)))` THEN
  POP_ASSUM(LABEL_TAC "m_definition") THEN
  SUBGOAL_THEN `2 <= m` (LABEL_TAC "large") THENL
   [USE_THEN "m_definition" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "degree_large" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_neighbors (E:(A->bool)->bool) (q(n - 1)) =
    cyclic_vertices (z:num->A) m`
  (LABEL_TAC "z_neighbors") THENL
   [USE_THEN "m_definition" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "neighbors" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (z:num->A) (cyclic_indices m) (:A)`
  (LABEL_TAC "z_injective") THENL
   [USE_THEN "m_definition" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "injective" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(z:num->A) 0 = q(n - 2)` (LABEL_TAC "z_first") THENL
   [USE_THEN "first" MP_TAC THEN REWRITE_TAC[SND];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i < m
        ==> (q(n - 1),(z:num->A) i) IN outgoing_darts E (q(n - 1)) /\
            (r:(A#A)->A#A) (q(n - 1),z i) =
            (q(n - 1),z((i + 1) MOD m))`
  (LABEL_TAC "z_data") THENL
   [USE_THEN "m_definition" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "steps" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(z:num->A) 1 = q 0` (LABEL_TAC "z_second") THENL
   [USE_THEN "z_data" (MP_TAC o SPEC `0`) THEN
    ANTS_TAC THENL
     [USE_THEN "large" MP_TAC THEN ARITH_TAC;
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
       (LABEL_TAC "first_step"))] THEN
    SUBGOAL_THEN `(0 + 1) MOD m = 1` (LABEL_TAC "one_mod") THENL
     [REWRITE_TAC[ADD_CLAUSES] THEN MATCH_MP_TAC MOD_LT THEN
      USE_THEN "large" MP_TAC THEN ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "first_step" (fun step_th ->
     USE_THEN "z_first" (fun first_th ->
      USE_THEN "boundary_step" (fun boundary_th ->
       USE_THEN "one_mod" (fun mod_th ->
        ACCEPT_TAC(SYM(REWRITE_RULE
         [first_th; boundary_th; mod_th; PAIR_EQ] step_th))))));
    ALL_TAC] THEN
  ABBREV_TAC `h:num->A = \i. (z:num->A) ((i + 1) MOD m)` THEN
  POP_ASSUM(LABEL_TAC "h_definition") THEN
  ABBREV_TAC `w:num->A = cyclic_reverse (h:num->A) m` THEN
  POP_ASSUM(LABEL_TAC "w_definition") THEN
  SUBGOAL_THEN
   `graph_neighbors (E:(A->bool)->bool) (q(n - 1)) =
    cyclic_vertices (w:num->A) m`
  (LABEL_TAC "w_neighbors") THENL
   [USE_THEN "w_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[CYCLIC_VERTICES_REVERSE] THEN
    USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[CYCLIC_VERTICES_OFFSET] THEN
    USE_THEN "z_neighbors" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (w:num->A) (cyclic_indices m) (:A)`
  (LABEL_TAC "w_injective") THENL
   [USE_THEN "w_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC INJ_CYCLIC_REVERSE THEN
    USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC INJ_CYCLIC_OFFSET THEN
    USE_THEN "z_injective" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w:num->A) 0 = q(n - 2) /\ w(m - 1) = q 0`
  (CONJUNCTS_THEN2 (LABEL_TAC "w_first") (LABEL_TAC "w_last")) THENL
   [MP_TAC(SPECL [`h:num->A`; `m:num`] CYCLIC_REVERSE_ENDPOINTS) THEN
    ANTS_TAC THENL
     [USE_THEN "large" MP_TAC THEN ARITH_TAC;
      INTRO_TAC "reverse_first reverse_last"] THEN
    SUBGOAL_THEN `(h:num->A) 0 = q 0` (LABEL_TAC "h_first") THENL
     [USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      BETA_TAC THEN
      SUBGOAL_THEN `(0 + 1) MOD m = 1` SUBST1_TAC THENL
       [REWRITE_TAC[ADD_CLAUSES] THEN MATCH_MP_TAC MOD_LT THEN
        USE_THEN "large" MP_TAC THEN ARITH_TAC;
        USE_THEN "z_second" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(h:num->A) (m - 1) = q(n - 2)`
    (LABEL_TAC "h_last") THENL
     [USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      BETA_TAC THEN
      SUBGOAL_THEN `(m - 1) + 1 = m` SUBST1_TAC THENL
       [USE_THEN "large" MP_TAC THEN ARITH_TAC;
        REWRITE_TAC[MOD_REFL] THEN USE_THEN "z_first" ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "w_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i + 1 < m
        ==> (r:(A#A)->A#A) (q(n - 1),w(i + 1)) =
            (q(n - 1),w i)`
  (LABEL_TAC "w_steps") THENL
   [USE_THEN "w_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "h_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC CYCLIC_REVERSE_OFFSET_ROTATION_STEPS THEN
    CONJ_TAC THENL
     [USE_THEN "large" ACCEPT_TAC;
      X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
      USE_THEN "z_data" (MP_TAC o SPEC `i:num`) THEN
      ANTS_TAC THENL
       [USE_THEN "index" ACCEPT_TAC;
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC)]];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`m - 2`; `w:num->A`] THEN
  SUBGOAL_THEN `(m:num) - 2 + 2 = m` (LABEL_TAC "length") THENL
   [USE_THEN "large" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(m:num) - 2 + 1 = m - 1`
  (LABEL_TAC "last_index") THENL
   [USE_THEN "large" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "m_definition" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "length" (ACCEPT_TAC o SYM);
    USE_THEN "length" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "w_neighbors" ACCEPT_TAC;
    USE_THEN "length" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "w_injective" ACCEPT_TAC;
    USE_THEN "w_first" ACCEPT_TAC;
    USE_THEN "last_index" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "w_last" ACCEPT_TAC;
    USE_THEN "length" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "w_steps" ACCEPT_TAC]);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_LAST_NEIGHBOR_CHAIN = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A.
        maximal_boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n
        ==> ?k w.
              CARD(graph_neighbors E (q(n - 1))) = k + 2 /\
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = q(n - 2) /\
              w(k + 1) = q 0 /\
              (!i. i + 1 < k + 2
                   ==> r(q(n - 1),w(i + 1)) =
                       (q(n - 1),w i)) /\
              (!i. i + 1 < k + 2
                   ==> {w i,w(i + 1)} IN E)`,
  REPEAT GEN_TAC THEN INTRO_TAC "maximal cycle" THEN
  SUBGOAL_THEN
   `boundary_euler_rotation
      (V:A->bool) E (q:num->A) n (r:(A#A)->A#A)`
  (LABEL_TAC "boundary") THENL
   [USE_THEN "maximal" MP_TAC THEN
    REWRITE_TAC[maximal_boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation; euler_planar_rotation] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
    `r:(A#A)->A#A`]
   BOUNDARY_EULER_ROTATION_LAST_ORIENTED_NEIGHBOR_ENUMERATION) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@k w. length neighbors injective first last steps" THEN
  MAP_EVERY EXISTS_TAC [`k:num`; `w:num->A`] THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
  SUBGOAL_THEN
   `(w:num->A)(i + 1) IN graph_neighbors E (q(n - 1))`
  (LABEL_TAC "neighbor") THENL
   [USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `i + 1` THEN
    ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((w:num->A)(i + 1),q(n - 1)) IN graph_darts E`
