   [REWRITE_TAC[IN_GRAPH_DARTS] THEN
    ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
    USE_THEN "neighbor" MP_TAC THEN
    REWRITE_TAC[IN_GRAPH_NEIGHBORS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((w:num->A)(i + 1),q(n - 1)) IN cyclic_darts q n)`
  (LABEL_TAC "nonboundary") THENL
   [DISCH_THEN(LABEL_TAC "boundary_dart") THEN
    SUBGOAL_THEN `(w:num->A)(i + 1) = q(n - 2)`
    (LABEL_TAC "entering_last") THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `q:num->A`; `n:num`;
        `(w:num->A)(i + 1)`]
       CYCLIC_DART_ENTERING_LAST) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(w:num->A)(i + 1) = w 0`
    (LABEL_TAC "same_vertex") THENL
     [ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    DISCH_THEN(MP_TAC o SPECL [`i + 1`; `0`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "index" MP_TAC THEN ARITH_TAC;
      DISCH_THEN(LABEL_TAC "same_index") THEN
      USE_THEN "same_index" MP_TAC THEN ARITH_TAC];
