  SUBGOAL_THEN
   `DISJOINT
      (graph_face E (r:(A#A)->A#A) (w(i + 1),q(n - 1)))
      (cyclic_darts q n)`
  (LABEL_TAC "internal") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `r:(A#A)->A#A`; `((w:num->A)(i + 1),q(n - 1)):A#A`]
     BOUNDARY_EULER_ROTATION_NONBOUNDARY_FACE_DISJOINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w:num->A)(i + 1) IN
      graph_rotation_face_vertices E r (w(i + 1),q(n - 1)) /\
    w i IN graph_rotation_face_vertices E r (w(i + 1),q(n - 1))`
  (CONJUNCTS_THEN2 (LABEL_TAC "next_in_face")
    (LABEL_TAC "current_in_face")) THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `(q:num->A)(n - 1)`; `(w:num->A)(i + 1)`;
      `(w:num->A)i`]
     GRAPH_ROTATION_SUCCESSIVE_HEADS_COFACIAL) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      USE_THEN "rotation" ACCEPT_TAC;
      REWRITE_TAC[IN_OUTGOING_DARTS_PAIR] THEN
      USE_THEN "neighbor" MP_TAC THEN
      REWRITE_TAC[IN_GRAPH_NEIGHBORS];
      USE_THEN "steps" (MATCH_MP_TAC o SPEC `i:num`) THEN
      USE_THEN "index" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((w:num->A)(i + 1) = w i)`
  (LABEL_TAC "distinct") THENL
   [DISCH_THEN(LABEL_TAC "same_vertex") THEN
    USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    DISCH_THEN(MP_TAC o SPECL [`i + 1`; `i:num`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "index" MP_TAC THEN ARITH_TAC;
      DISCH_THEN(LABEL_TAC "same_index") THEN
      USE_THEN "same_index" MP_TAC THEN ARITH_TAC];
    ALL_TAC] THEN
  ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
    `r:(A#A)->A#A`; `((w:num->A)(i + 1),q(n - 1)):A#A`]
   MAXIMAL_BOUNDARY_EULER_ROTATION_INTERNAL_FACE_VERTICES_CLIQUE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL
   [`(w:num->A)(i + 1)`; `(w:num->A)i`]) THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_ROTATION_SUCCESSIVE_NEIGHBOR_FACE_OF_TRIANGULAR_FACE = prove
 (`!V E r u v w:A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        (u,v) IN outgoing_darts E u /\
        r(u,v) = (u,w) /\
        ~(v = w) /\
        {v,w} IN E /\
        CARD(graph_rotation_face_vertices E r (v,u)) = 3
        ==> graph_face_successor E r (u,w) = (w,v)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph rotation outgoing step distinct edge triangular" THEN
  SUBGOAL_THEN `((u:A),v) IN graph_darts E` (LABEL_TAC "uv_dart") THENL
   [USE_THEN "outgoing" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `((v:A),u) IN graph_darts E` (LABEL_TAC "vu_dart") THENL
   [MP_TAC(ISPECL [`E:(A->bool)->bool`; `((u:A),v):A#A`]
     GRAPH_DARTS_REVERSE) THEN
    ASM_REWRITE_TAC[REVERSE_DART_PAIR];
    ALL_TAC] THEN
  SUBGOAL_THEN `((u:A),w) IN graph_darts E` (LABEL_TAC "uw_dart") THENL
   [USE_THEN "step" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC GRAPH_ROTATION_IN THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `((w:A),u) IN graph_darts E` (LABEL_TAC "wu_dart") THENL
   [MP_TAC(ISPECL [`E:(A->bool)->bool`; `((u:A),w):A#A`]
     GRAPH_DARTS_REVERSE) THEN
    ASM_REWRITE_TAC[REVERSE_DART_PAIR];
    ALL_TAC] THEN
  SUBGOAL_THEN `((w:A),v) IN graph_darts E` (LABEL_TAC "wv_dart") THENL
   [REWRITE_TAC[IN_GRAPH_DARTS] THEN
    ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
    USE_THEN "edge" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) = v) /\ ~((u:A) = w)`
  (CONJUNCTS_THEN2 (LABEL_TAC "uv_distinct")
    (LABEL_TAC "uw_distinct")) THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[];
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `w:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A) (v,u) = (u,w)`
  (LABEL_TAC "first_step") THENL
   [TRANS_TAC EQ_TRANS `(r:(A#A)->A#A) (u,v)` THEN
    CONJ_TAC THENL
     [MP_TAC(MATCH_MP
       (ISPECL
        [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((v:A),u):A#A`]
        GRAPH_FACE_SUCCESSOR_IN)
       (ASSUME `((v:A),u) IN graph_darts E`)) THEN
      REWRITE_TAC[REVERSE_DART_PAIR] THEN DISCH_THEN ACCEPT_TAC;
      USE_THEN "step" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(u:A,w) IN graph_face E r (v,u)`
  (LABEL_TAC "first_in_face") THENL
   [USE_THEN "first_step" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_ACCEPT_TAC GRAPH_FACE_SUCCESSOR_IN_FACE;
    ALL_TAC] THEN
  ABBREV_TAC
   `facev:A->bool =
      graph_rotation_face_vertices E (r:(A#A)->A#A) (v,u)` THEN
  POP_ASSUM(LABEL_TAC "facev_definition") THEN
  SUBGOAL_THEN `(u:A) IN facev /\ v IN facev /\ w IN facev`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_face")
    (CONJUNCTS_THEN2 (LABEL_TAC "v_face") (LABEL_TAC "w_face"))) THENL
   [CONJ_TAC THENL
     [USE_THEN "facev_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[graph_rotation_face_vertices; IN_IMAGE] THEN
      EXISTS_TAC `((v:A),u):A#A` THEN
      REWRITE_TAC[SND] THEN MATCH_ACCEPT_TAC GRAPH_FACE_REFL;
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `u:A`; `v:A`; `w:A`]
       GRAPH_ROTATION_SUCCESSIVE_HEADS_COFACIAL) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "facev_definition" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  SUBGOAL_THEN `(facev:A->bool) HAS_SIZE 3`
  (LABEL_TAC "facev_size") THENL
   [REWRITE_TAC[HAS_SIZE] THEN CONJ_TAC THENL
     [USE_THEN "facev_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
       `((v:A),u):A#A`]
       FINITE_GRAPH_ROTATION_FACE_VERTICES) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "triangular" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `({u:A,v,w}:A->bool) HAS_SIZE 3`
  (LABEL_TAC "triple_size") THENL
   [REWRITE_TAC[HAS_SIZE_CONV `({u:A,v,w}:A->bool) HAS_SIZE 3`] THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `v:A`; `w:A`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(facev:A->bool) = {u,v,w}`
  (LABEL_TAC "facev_eq") THENL
   [CONV_TAC SYM_CONV THEN MATCH_MP_TAC CARD_SUBSET_EQ THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "facev_size"
       (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[HAS_SIZE]);
      REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN ASM_REWRITE_TAC[];
      USE_THEN "triple_size" (fun triple_th ->
       USE_THEN "facev_size" (fun face_th ->
        ACCEPT_TAC(TRANS
         (CONJUNCT2(REWRITE_RULE[HAS_SIZE] triple_th))
         (SYM(CONJUNCT2(REWRITE_RULE[HAS_SIZE] face_th))))))];
    ALL_TAC] THEN
  ABBREV_TAC
   `d2:A#A = graph_face_successor E (r:(A#A)->A#A) (u,w)` THEN
  POP_ASSUM(LABEL_TAC "d2_definition") THEN
  SUBGOAL_THEN `(d2:A#A) IN graph_darts E` (LABEL_TAC "d2_dart") THENL
   [USE_THEN "d2_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_DART THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(d2:A#A) IN graph_face E r (v,u)`
  (LABEL_TAC "d2_face") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((v:A),u):A#A`;
      `((u:A),w):A#A`; `d2:A#A`]
     GRAPH_FACE_TRANS) THEN
    CONJ_TAC THENL
     [USE_THEN "first_in_face" ACCEPT_TAC;
      USE_THEN "d2_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_ACCEPT_TAC GRAPH_FACE_SUCCESSOR_IN_FACE];
    ALL_TAC] THEN
  SUBGOAL_THEN `FST(d2:A#A) = w` (LABEL_TAC "d2_tail") THENL
   [USE_THEN "d2_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((u:A),w):A#A`]
     GRAPH_FACE_SUCCESSOR_TAIL) THEN
    ASM_REWRITE_TAC[SND];
    ALL_TAC] THEN
  SUBGOAL_THEN `SND(d2:A#A) IN facev` (LABEL_TAC "d2_head_face") THENL
   [USE_THEN "facev_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[graph_rotation_face_vertices; IN_IMAGE] THEN
    EXISTS_TAC `d2:A#A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(SND(d2:A#A) = w)` (LABEL_TAC "head_not_w") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `FST(d2:A#A)`; `SND(d2:A#A)`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[PAIR] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(SND(d2:A#A) = u)` (LABEL_TAC "head_not_u") THENL
   [DISCH_THEN(LABEL_TAC "head_u") THEN
    SUBGOAL_THEN `(d2:A#A) = (w,u)` (LABEL_TAC "d2_pair") THENL
     [USE_THEN "d2_tail" (fun tail_th ->
       USE_THEN "head_u" (fun head_th ->
        let pair_th = MATCH_MP
          (snd(EQ_IMP_RULE
            (ISPECL
             [`FST(d2:A#A)`; `SND(d2:A#A)`; `w:A`; `u:A`]
             PAIR_EQ)))
          (CONJ tail_th head_th) in
        ACCEPT_TAC(TRANS (SYM(ISPEC `d2:A#A` PAIR)) pair_th)));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(d2:A#A) = (r:(A#A)->A#A) (w,u)`
    (LABEL_TAC "d2_rotation") THENL
     [USE_THEN "d2_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MP_TAC(MATCH_MP
       (ISPECL
        [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((u:A),w):A#A`]
        GRAPH_FACE_SUCCESSOR_IN)
       (ASSUME `((u:A),w) IN graph_darts E`)) THEN
      REWRITE_TAC[REVERSE_DART_PAIR] THEN DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(r:(A#A)->A#A) (w,u) = (w,u)`
    (LABEL_TAC "wu_fixed") THENL
     [USE_THEN "d2_rotation" (fun rotation_th ->
       USE_THEN "d2_pair" (fun pair_th ->
        ACCEPT_TAC(TRANS (SYM rotation_th) pair_th)));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `FST(((w:A),v):A#A) = FST(((w:A),u):A#A)`
    (LABEL_TAC "same_tail") THENL
     [REWRITE_TAC[FST];
      ALL_TAC] THEN
    MP_TAC(MATCH_MP
     (ISPECL
      [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
       `((w:A),u):A#A`; `((w:A),v):A#A`]
      GRAPH_ROTATION_FIXED_DART_AT_TAIL)
     (end_itlist CONJ
       [ASSUME `graph_rotation E (r:(A#A)->A#A)`;
        ASSUME `((w:A),u) IN graph_darts E`;
        ASSUME `((w:A),v) IN graph_darts E`;
        ASSUME `FST(((w:A),v):A#A) = FST(((w:A),u):A#A)`;
        ASSUME `(r:(A#A)->A#A) (w,u) = (w,u)`])) THEN
    DISCH_THEN(LABEL_TAC "same_dart") THEN
    USE_THEN "same_dart" MP_TAC THEN REWRITE_TAC[PAIR_EQ] THEN
    DISCH_THEN(LABEL_TAC "vu_same") THEN
    USE_THEN "uv_distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "vu_same" (ACCEPT_TAC o SYM);
    ALL_TAC] THEN
  SUBGOAL_THEN `SND(d2:A#A) = v` (LABEL_TAC "d2_head") THENL
   [USE_THEN "d2_head_face" MP_TAC THEN
    USE_THEN "facev_eq"
     (fun th -> REWRITE_TAC[th; IN_INSERT; IN_SING]) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "d2_tail" (fun tail_th ->
   USE_THEN "d2_head" (fun head_th ->
    let pair_th = MATCH_MP
      (snd(EQ_IMP_RULE
        (ISPECL
         [`FST(d2:A#A)`; `SND(d2:A#A)`; `w:A`; `v:A`]
         PAIR_EQ)))
      (CONJ tail_th head_th) in
    ACCEPT_TAC(TRANS (SYM(ISPEC `d2:A#A` PAIR)) pair_th))));;

let GRAPH_ROTATION_SUCCESSIVE_NEIGHBOR_TRIANGULAR_FACE = prove
 (`!V E r u v w:A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        (u,v) IN outgoing_darts E u /\
        r(u,v) = (u,w) /\
        ~(v = w) /\
        {v,w} IN E /\
        CARD(graph_rotation_face_vertices E r (v,u)) = 3
        ==> graph_face_successor E r (v,u) = (u,w) /\
            graph_face_successor E r (u,w) = (w,v) /\
            graph_face_successor E r (w,v) = (v,u)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph rotation outgoing step distinct edge triangular" THEN
  SUBGOAL_THEN `((u:A),v) IN graph_darts E` (LABEL_TAC "uv_dart") THENL
   [USE_THEN "outgoing" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `((v:A),u) IN graph_darts E` (LABEL_TAC "vu_dart") THENL
   [MP_TAC(ISPECL [`E:(A->bool)->bool`; `((u:A),v):A#A`]
     GRAPH_DARTS_REVERSE) THEN
    ASM_REWRITE_TAC[REVERSE_DART_PAIR];
    ALL_TAC] THEN
  SUBGOAL_THEN `((u:A),w) IN graph_darts E` (LABEL_TAC "uw_dart") THENL
   [USE_THEN "step" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC GRAPH_ROTATION_IN THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `((w:A),u) IN graph_darts E` (LABEL_TAC "wu_dart") THENL
   [MP_TAC(ISPECL [`E:(A->bool)->bool`; `((u:A),w):A#A`]
     GRAPH_DARTS_REVERSE) THEN
    ASM_REWRITE_TAC[REVERSE_DART_PAIR];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A) (v,u) = (u,w)`
  (LABEL_TAC "first_step") THENL
   [TRANS_TAC EQ_TRANS `(r:(A#A)->A#A) (u,v)` THEN
    CONJ_TAC THENL
     [MP_TAC(MATCH_MP
       (ISPECL
        [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((v:A),u):A#A`]
        GRAPH_FACE_SUCCESSOR_IN)
       (ASSUME `((v:A),u) IN graph_darts E`)) THEN
      REWRITE_TAC[REVERSE_DART_PAIR] THEN DISCH_THEN ACCEPT_TAC;
      USE_THEN "step" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A) (u,w) = (w,v)`
  (LABEL_TAC "second_step") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `u:A`; `v:A`; `w:A`]
     GRAPH_ROTATION_SUCCESSIVE_NEIGHBOR_FACE_OF_TRIANGULAR_FACE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(u:A,w) IN graph_face E r (v,u)`
  (LABEL_TAC "second_in_face") THENL
   [USE_THEN "first_step" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_ACCEPT_TAC GRAPH_FACE_SUCCESSOR_IN_FACE;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face E (r:(A#A)->A#A) (u,w) =
    graph_face E r (v,u)`
  (LABEL_TAC "same_face") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `((v:A),u):A#A`; `((u:A),w):A#A`]
     GRAPH_FACE_EQ) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(graph_rotation_face_vertices
      E (r:(A#A)->A#A) (u,w)) = 3`
  (LABEL_TAC "second_triangular") THENL
   [USE_THEN "same_face"
     (fun th -> REWRITE_TAC[graph_rotation_face_vertices; th]) THEN
    USE_THEN "triangular" MP_TAC THEN
    REWRITE_TAC[graph_rotation_face_vertices];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) (w,u) = (w,v)`
  (LABEL_TAC "second_rotation_step") THENL
   [MP_TAC(MATCH_MP
     (ISPECL
      [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((u:A),w):A#A`]
      GRAPH_FACE_SUCCESSOR_IN)
     (ASSUME `((u:A),w) IN graph_darts E`)) THEN
    REWRITE_TAC[REVERSE_DART_PAIR] THEN
    USE_THEN "second_step" MP_TAC THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `((w:A),u) IN outgoing_darts E w`
  (LABEL_TAC "second_outgoing") THENL
   [USE_THEN "wu_dart" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) = v)` (LABEL_TAC "uv_distinct") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{u:A,v} IN E` (LABEL_TAC "uv_edge") THENL
   [USE_THEN "outgoing" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS_PAIR];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "first_step" ACCEPT_TAC;
    USE_THEN "second_step" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `w:A`; `u:A`; `v:A`]
     GRAPH_ROTATION_SUCCESSIVE_NEIGHBOR_FACE_OF_TRIANGULAR_FACE) THEN
    ASM_REWRITE_TAC[]]);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_LAST_INTERNAL_NEIGHBOR_FACES =
  prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A.
        maximal_boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        connected_graph V E /\
        3 <= CARD V
        ==> ?k w.
              CARD(graph_neighbors E (q(n - 1))) = k + 2 /\
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = q(n - 2) /\
              w(k + 1) = q 0 /\
              (!i. i + 1 < k + 2
                   ==> {w i,w(i + 1)} IN E /\
                       r(q(n - 1),w(i + 1)) =
                        (q(n - 1),w i) /\
                       graph_face_successor E r
                        (q(n - 1),w i) = (w i,w(i + 1)) /\
                       graph_face_successor E r
                        (w i,w(i + 1)) = (w(i + 1),q(n - 1)) /\
                       graph_face_successor E r
                        (w(i + 1),q(n - 1)) =
                        (q(n - 1),w i))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "maximal cycle connected vertices_large" THEN
  SUBGOAL_THEN
   `boundary_euler_rotation
      (V:A->bool) E (q:num->A) n (r:(A#A)->A#A)`
  (LABEL_TAC "boundary") THENL
   [USE_THEN "maximal" MP_TAC THEN
    REWRITE_TAC[maximal_boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation; euler_planar_rotation] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
    `r:(A#A)->A#A`]
   MAXIMAL_BOUNDARY_EULER_ROTATION_LAST_NEIGHBOR_CHAIN) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@k w. length neighbors injective first last steps chain" THEN
  MAP_EVERY EXISTS_TAC [`k:num`; `w:num->A`] THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
  SUBGOAL_THEN `{(w:num->A)i,w(i + 1)} IN E`
  (LABEL_TAC "chain_edge") THENL
   [USE_THEN "chain" (MATCH_MP_TAC o SPEC `i:num`) THEN
    USE_THEN "index" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) (q(n - 1),w(i + 1)) =
    (q(n - 1),w i)`
  (LABEL_TAC "rotation_step") THENL
   [USE_THEN "steps" (MATCH_MP_TAC o SPEC `i:num`) THEN
    USE_THEN "index" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w:num->A)(i + 1) IN graph_neighbors E (q(n - 1))`
  (LABEL_TAC "neighbor") THENL
   [USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `i + 1` THEN
    ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((q:num->A)(n - 1),w(i + 1)) IN
    outgoing_darts E (q(n - 1))`
  (LABEL_TAC "outgoing") THENL
   [REWRITE_TAC[IN_OUTGOING_DARTS_PAIR] THEN
    USE_THEN "neighbor" MP_TAC THEN
    REWRITE_TAC[IN_GRAPH_NEIGHBORS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((w:num->A)(i + 1),q(n - 1)) IN graph_darts E`
  (LABEL_TAC "reverse_dart") THENL
   [REWRITE_TAC[IN_GRAPH_DARTS] THEN
    ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
    USE_THEN "neighbor" MP_TAC THEN
    REWRITE_TAC[IN_GRAPH_NEIGHBORS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((w:num->A)(i + 1),q(n - 1)) IN cyclic_darts q n)`
  (LABEL_TAC "nonboundary") THENL
   [DISCH_THEN(LABEL_TAC "boundary_dart") THEN
    SUBGOAL_THEN `(w:num->A)(i + 1) = q(n - 2)`
    (LABEL_TAC "entering_last") THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `q:num->A`; `n:num`;
        `(w:num->A)(i + 1)`]
       CYCLIC_DART_ENTERING_LAST) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(w:num->A)(i + 1) = w 0`
    (LABEL_TAC "same_vertex") THENL
     [ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    DISCH_THEN(MP_TAC o SPECL [`i + 1`; `0`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "index" MP_TAC THEN ARITH_TAC;
      DISCH_THEN(LABEL_TAC "same_index") THEN
      USE_THEN "same_index" MP_TAC THEN ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `DISJOINT
      (graph_face E (r:(A#A)->A#A) (w(i + 1),q(n - 1)))
      (cyclic_darts q n)`
  (LABEL_TAC "internal") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `r:(A#A)->A#A`; `((w:num->A)(i + 1),q(n - 1)):A#A`]
     BOUNDARY_EULER_ROTATION_NONBOUNDARY_FACE_DISJOINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(graph_rotation_face_vertices E (r:(A#A)->A#A)
      (w(i + 1),q(n - 1))) = 3`
  (LABEL_TAC "triangular") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `r:(A#A)->A#A`; `((w:num->A)(i + 1),q(n - 1)):A#A`]
     MAXIMAL_BOUNDARY_EULER_ROTATION_INTERNAL_FACE_VERTICES_CARD_EQ_3) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((w:num->A)(i + 1) = w i)`
  (LABEL_TAC "distinct") THENL
   [DISCH_THEN(LABEL_TAC "same_vertex") THEN
    USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    DISCH_THEN(MP_TAC o SPECL [`i + 1`; `i:num`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "index" MP_TAC THEN ARITH_TAC;
      DISCH_THEN(LABEL_TAC "same_index") THEN
      USE_THEN "same_index" MP_TAC THEN ARITH_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `(q:num->A)(n - 1)`; `(w:num->A)(i + 1)`; `(w:num->A)i`]
   GRAPH_ROTATION_SUCCESSIVE_NEIGHBOR_TRIANGULAR_FACE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      USE_THEN "rotation" ACCEPT_TAC;
      USE_THEN "outgoing" ACCEPT_TAC;
      USE_THEN "rotation_step" ACCEPT_TAC;
      USE_THEN "distinct" ACCEPT_TAC;
      ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
      USE_THEN "chain_edge" ACCEPT_TAC;
      USE_THEN "triangular" ACCEPT_TAC];
    INTRO_TAC "reverse_successor center_successor chain_successor"] THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_REACHABLE_CHAIN_FROM_FIRST = prove
 (`!E:(A->bool)->bool. !w:num->A. !m.
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E)
        ==> !i. i < m ==> graph_reachable E (w 0) (w i)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "chain") THEN
  INDUCT_TAC THENL
   [DISCH_TAC THEN MATCH_ACCEPT_TAC GRAPH_REACHABLE_REFL;
    DISCH_THEN(LABEL_TAC "index") THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `(w:num->A) 0`; `(w:num->A) i`;
      `(w:num->A) (SUC i)`]
     GRAPH_REACHABLE_TRANS) THEN
    CONJ_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC;
      REWRITE_TAC[graph_reachable] THEN
      MATCH_MP_TAC(CONJUNCT1(SPEC
       `(\(x:A) (y:A). {x,y} IN E)` RTC_RULES)) THEN
      BETA_TAC THEN ASM_MESON_TAC[ADD1]]]);;

let CONNECTED_GRAPH_DELETE_VERTEX_OF_NEIGHBOR_CHAIN = prove
 (`!V E v w m.
        finite_simple_graph (V:A->bool) E /\
        connected_graph V E /\
        v IN V /\
        graph_neighbors E v = cyclic_vertices (w:num->A) m /\
        0 < m /\
        (!i. i + 1 < m ==> {w i,w(i + 1)} IN E)
        ==> connected_graph (V DELETE v)
             (induced_subgraph_edges E (V DELETE v))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph connected vertex neighbors positive chain" THEN
  ABBREV_TAC `B:(A->bool)->bool =
    induced_subgraph_edges E (V DELETE v)` THEN
  POP_ASSUM(LABEL_TAC "B_definition") THEN
  SUBGOAL_THEN
   `graph_neighbors (E:(A->bool)->bool) v SUBSET V DELETE v`
  (LABEL_TAC "neighbors_subset") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_NEIGHBORS_SUBSET_DELETE THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i + 1 < m ==> {(w:num->A)i,w(i + 1)} IN B`
  (LABEL_TAC "deleted_chain") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    USE_THEN "B_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    CONJ_TAC THENL
     [USE_THEN "chain" (MATCH_MP_TAC o SPEC `i:num`) THEN
      USE_THEN "index" ACCEPT_TAC;
      REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
      CONJ_TAC THENL
       [USE_THEN "neighbors_subset"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
        EXISTS_TAC `i:num` THEN ASM_ARITH_TAC;
        USE_THEN "neighbors_subset"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
        EXISTS_TAC `i + 1` THEN ASM_ARITH_TAC]];
    ALL_TAC] THEN
  USE_THEN "B_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `(w:num->A) 0`]
   CONNECTED_GRAPH_DELETE_VERTEX_OF_CONNECTED_NEIGHBORS) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    USE_THEN "connected" ACCEPT_TAC;
    USE_THEN "vertex" ACCEPT_TAC;
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `0` THEN ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
    X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "u_neighbor") THEN
    USE_THEN "neighbors" (fun th ->
      USE_THEN "u_neighbor" (MP_TAC o REWRITE_RULE[th])) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    INTRO_TAC "@i. index value" THEN
    USE_THEN "value" SUBST1_TAC THEN
    USE_THEN "B_definition" (fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL
     [`B:(A->bool)->bool`; `w:num->A`; `m:num`]
     GRAPH_REACHABLE_CHAIN_FROM_FIRST) THEN
    ANTS_TAC THENL
     [USE_THEN "deleted_chain" ACCEPT_TAC;
      DISCH_THEN(MATCH_MP_TAC o SPEC `i:num`) THEN
      USE_THEN "index" ACCEPT_TAC]]);;

let SIMPLE_GRAPH_CYCLE_DELETE_LAST_INDUCED_OF_CHAIN = prove
 (`!V E q:num->A. !n k w.
        finite_simple_graph V E /\
        simple_graph_cycle E q n /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        3 <= n - 1 + k /\
        graph_neighbors E (q(n - 1)) = cyclic_vertices w (k + 2) /\
        INJ w (cyclic_indices (k + 2)) (:A) /\
        w 0 = q(n - 2) /\
        w(k + 1) = q 0 /\
        (!i. i + 1 < k + 2 ==> {w i,w(i + 1)} IN E)
        ==> simple_graph_cycle
             (induced_subgraph_edges E (V DELETE q(n - 1)))
             (cyclic_delete_last q w n) (n - 1 + k)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph cycle chordless newlarge neighbors injective first last chain" THEN
  USE_THEN "cycle" (MP_TAC o REWRITE_RULE[simple_graph_cycle]) THEN
  INTRO_TAC "nlarge q_injective boundary_edges" THEN
  SUBGOAL_THEN
   `cyclic_vertices (q:num->A) n INTER cyclic_vertices w (k + 2) =
    {q(n - 2),q 0}`
  (LABEL_TAC "intersection") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`]
     BOUNDARY_NEIGHBORS_OF_LAST_WITHOUT_CHORD) THEN
    ASM_REWRITE_TAC[simple_graph_cycle] THEN
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle (E:(A->bool)->bool)
      (cyclic_delete_last (q:num->A) (w:num->A) n) (n - 1 + k)`
  (LABEL_TAC "new_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DELETE_LAST THEN
    ASM_REWRITE_TAC[simple_graph_cycle];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_vertices (cyclic_delete_last (q:num->A) w n) (n - 1 + k) =
    cyclic_vertices q n DELETE q(n - 1) UNION
    graph_neighbors E (q(n - 1))`
  (LABEL_TAC "new_vertices") THENL
   [MP_TAC(ISPECL [`q:num->A`; `w:num->A`; `n:num`; `k:num`]
     CYCLIC_VERTICES_CYCLIC_DELETE_LAST) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `cyclic_delete_last (q:num->A) w n`;
    `n - 1 + k:num`; `V DELETE (q:num->A)(n - 1)`]
   SIMPLE_GRAPH_CYCLE_INDUCED_SUBGRAPH) THEN
  CONJ_TAC THENL
   [USE_THEN "new_cycle" ACCEPT_TAC;
    USE_THEN "new_vertices" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[UNION_SUBSET] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`]
       FINITE_SIMPLE_GRAPH_CYCLE_VERTICES_SUBSET) THEN
      ASM_REWRITE_TAC[simple_graph_cycle] THEN SET_TAC[];
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `(q:num->A)(n - 1)`]
      FINITE_SIMPLE_GRAPH_NEIGHBORS_SUBSET_DELETE) THEN
      USE_THEN "graph" ACCEPT_TAC]]);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_DELETE_LAST_BOUNDARY_INTERNAL =
  prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A.
        maximal_boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        connected_graph V E /\
        3 <= CARD V
        ==> ?k w s.
              CARD(graph_neighbors E (q(n - 1))) = k + 2 /\
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = q(n - 2) /\
              w(k + 1) = q 0 /\
              (!i. i + 1 < k + 2
                   ==> {w i,w(i + 1)} IN E) /\
              connected_graph
               (V DELETE q(n - 1))
               (induced_subgraph_edges E (V DELETE q(n - 1))) /\
              boundary_euler_rotation
               (V DELETE q(n - 1))
               (induced_subgraph_edges E (V DELETE q(n - 1)))
               (cyclic_delete_last q w n) (n - 1 + k) s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "maximal cycle connected vertices_large" THEN
  SUBGOAL_THEN
   `boundary_euler_rotation
      (V:A->bool) E (q:num->A) n (r:(A#A)->A#A)`
  (LABEL_TAC "boundary") THENL
   [USE_THEN "maximal" MP_TAC THEN
    REWRITE_TAC[maximal_boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `euler_planar_rotation
      (V:A->bool) E (r:(A#A)->A#A)`
  (LABEL_TAC "euler") THENL
   [USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "cycle" (MP_TAC o REWRITE_RULE[simple_graph_cycle]) THEN
  INTRO_TAC "nlarge q_injective boundary_edges" THEN
  SUBGOAL_THEN `cyclic_face_successors E (r:(A#A)->A#A) q n`
  (LABEL_TAC "old_successors") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `r:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_IMP_CYCLIC_FACE_SUCCESSORS) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "nlarge" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
    `r:(A#A)->A#A`]
   MAXIMAL_BOUNDARY_EULER_ROTATION_LAST_INTERNAL_NEIGHBOR_FACES) THEN
  ASM_REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC
   "@k w. length neighbors injective first last fan_faces" THEN
  SUBGOAL_THEN
   `!i. i + 1 < k + 2 ==> {(w:num->A)i,w(i + 1)} IN E`
  (LABEL_TAC "chain") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    USE_THEN "fan_faces" (MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL
     [USE_THEN "index" ACCEPT_TAC;
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i < k + 2 ==> ~((w:num->A)i = q(n - 1))`
  (LABEL_TAC "avoids") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    SUBGOAL_THEN
     `(w:num->A)i IN graph_neighbors E ((q:num->A)(n - 1))`
    (LABEL_TAC "neighbor") THENL
     [USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `i:num` THEN
      ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `(q:num->A)(n - 1)`; `(w:num->A)i`]
     FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i < k + 2 ==> {(q:num->A)(n - 1),w i} IN E`
  (LABEL_TAC "spokes") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    REWRITE_TAC[GSYM IN_GRAPH_NEIGHBORS] THEN
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `i:num` THEN
    ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i + 1 < k + 2
        ==> graph_face_successor E (r:(A#A)->A#A)
             (q(n - 1),w i) = (w i,w(i + 1)) /\
            graph_face_successor E r (w i,w(i + 1)) =
             (w(i + 1),q(n - 1)) /\
            graph_face_successor E r (w(i + 1),q(n - 1)) =
             (q(n - 1),w i)`
  (LABEL_TAC "triangles") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    USE_THEN "fan_faces" (MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL
     [USE_THEN "index" ACCEPT_TAC;
      DISCH_THEN(ACCEPT_TAC o CONJUNCT2 o CONJUNCT2)];
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:num->A)(n - 1) IN V`
  (LABEL_TAC "last_vertex") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`]
     FINITE_SIMPLE_GRAPH_CYCLE_VERTICES_SUBSET) THEN
    ASM_REWRITE_TAC[simple_graph_cycle; SUBSET] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph
      (V DELETE (q:num->A)(n - 1))
      (induced_subgraph_edges E (V DELETE q(n - 1)))`
  (LABEL_TAC "deleted_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `(q:num->A)(n - 1)`;
      `w:num->A`; `k + 2:num`]
     CONNECTED_GRAPH_DELETE_VERTEX_OF_NEIGHBOR_CHAIN) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  ABBREV_TAC
   `s:(A#A)->A#A =
      graph_delete_rotation
       (fan_delete_rotation ((q:num->A)(n - 1)) w r (k + 1))
       (w(k + 1)) (q(n - 1))` THEN
  POP_ASSUM(LABEL_TAC "s_definition") THEN
  SUBGOAL_THEN
   `boundary_euler_rotation
      (V DELETE (q:num->A)(n - 1))
      (induced_subgraph_edges E (V DELETE q(n - 1)))
      (cyclic_delete_last q w n) (n - 1 + k) s`
  (LABEL_TAC "new_boundary") THENL
   [USE_THEN "s_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `q:num->A`; `w:num->A`; `n:num`; `k:num`]
     BOUNDARY_EULER_ROTATION_FAN_DELETE_LAST) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`k:num`; `w:num->A`; `s:(A#A)->A#A`] THEN
  ASM_REWRITE_TAC[]);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_DELETE_LAST_CHORDLESS_INTERNAL =
  prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A.
        maximal_boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        connected_graph V E /\
        3 <= CARD V /\
        (!j. 0 < j /\ j + 2 < n
             ==> ~({q j,q(n - 1)} IN E)) /\
        (4 <= n \/ 3 <= CARD(graph_neighbors E (q(n - 1))))
        ==> ?k w s.
              CARD(graph_neighbors E (q(n - 1))) = k + 2 /\
              graph_neighbors E (q(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = q(n - 2) /\
              w(k + 1) = q 0 /\
              (!i. i + 1 < k + 2
                   ==> {w i,w(i + 1)} IN E) /\
              simple_graph_cycle
               (induced_subgraph_edges E (V DELETE q(n - 1)))
               (cyclic_delete_last q w n) (n - 1 + k) /\
              connected_graph
               (V DELETE q(n - 1))
               (induced_subgraph_edges E (V DELETE q(n - 1))) /\
              maximal_boundary_euler_rotation
               (V DELETE q(n - 1))
               (induced_subgraph_edges E (V DELETE q(n - 1)))
               (cyclic_delete_last q w n) (n - 1 + k) s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "maximal cycle connected vertices_large chordless replacement_large" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "maximal" MP_TAC THEN
    REWRITE_TAC[maximal_boundary_euler_rotation;
                boundary_euler_rotation; euler_planar_rotation] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
    `r:(A#A)->A#A`]
   MAXIMAL_BOUNDARY_EULER_ROTATION_DELETE_LAST_BOUNDARY_INTERNAL) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@k w s. length neighbors injective first last chain
            new_connected new_boundary" THEN
  SUBGOAL_THEN `3 <= n` (LABEL_TAC "oldlarge") THENL
   [USE_THEN "cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `3 <= n - 1 + k` (LABEL_TAC "newlarge") THENL
   [USE_THEN "replacement_large" DISJ_CASES_TAC THENL
     [ASM_ARITH_TAC;
      USE_THEN "length" MP_TAC THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle
      (induced_subgraph_edges E (V DELETE (q:num->A)(n - 1)))
      (cyclic_delete_last q w n) (n - 1 + k)`
  (LABEL_TAC "new_cycle") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
      `n:num`; `k:num`; `w:num->A`]
     SIMPLE_GRAPH_CYCLE_DELETE_LAST_INDUCED_OF_CHAIN) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `maximal_boundary_euler_rotation
      (V DELETE (q:num->A)(n - 1))
      (induced_subgraph_edges E (V DELETE q(n - 1)))
      (cyclic_delete_last q w n) (n - 1 + k) s`
  (LABEL_TAC "new_maximal") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `q:num->A`; `w:num->A`; `n:num`; `k:num`;
      `r:(A#A)->A#A`; `s:(A#A)->A#A`]
     MAXIMAL_BOUNDARY_EULER_ROTATION_FAN_REMAINDER) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`k:num`; `w:num->A`; `s:(A#A)->A#A`] THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Replacing an edge by a finite injective path.                             *)
(* ------------------------------------------------------------------------- *)

let indexed_path_vertices = new_definition
 `indexed_path_vertices (q:num->A) n = IMAGE q (0..n)`;;

let indexed_path_edges = new_definition
 `indexed_path_edges (q:num->A) n =
    IMAGE (\i. {q i,q(i + 1)}) (cyclic_indices n)`;;

let INDEXED_PATH_VERTICES_0 = prove
 (`!q:num->A. indexed_path_vertices q 0 = {q 0}`,
  REWRITE_TAC[indexed_path_vertices; NUMSEG_SING; IMAGE_CLAUSES]);;

let INDEXED_PATH_VERTICES_SUC = prove
 (`!q:num->A. !n.
        indexed_path_vertices q (SUC n) =
        q(SUC n) INSERT indexed_path_vertices q n`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[indexed_path_vertices; NUMSEG_CLAUSES; LE_0;
              IMAGE_CLAUSES]);;

let INDEXED_PATH_EDGES_0 = prove
 (`!q:num->A. indexed_path_edges q 0 = {}`,
  REWRITE_TAC[indexed_path_edges; cyclic_indices;
              NUMSEG_CLAUSES_LT; IMAGE_CLAUSES]);;

let INDEXED_PATH_EDGES_SUC = prove
 (`!q:num->A. !n.
        indexed_path_edges q (SUC n) =
        {q n,q(SUC n)} INSERT indexed_path_edges q n`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[indexed_path_edges; cyclic_indices;
              NUMSEG_CLAUSES_LT; IMAGE_CLAUSES; ADD1]);;

let IN_INDEXED_PATH_VERTICES = prove
 (`!q:num->A. !n x.
        x IN indexed_path_vertices q n <=>
        ?i. i <= n /\ x = q i`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[indexed_path_vertices; IN_IMAGE; IN_NUMSEG] THEN
  MESON_TAC[LE_0]);;

let IN_INDEXED_PATH_EDGES = prove
 (`!q:num->A. !n e.
        e IN indexed_path_edges q n <=>
        ?i. i < n /\ e = {q i,q(i + 1)}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[indexed_path_edges; IN_IMAGE; IN_CYCLIC_INDICES] THEN
  MESON_TAC[]);;

let GRAPH_SUBDIVISION_TRANS = prove
 (`!V E V' E' V'' E''.
        graph_subdivision (V:A->bool) E V' E' /\
        graph_subdivision V' E' V'' E''
        ==> graph_subdivision V E V'' E''`,
  SUBGOAL_THEN
   `!V' E' V'' E''.
        graph_subdivision (V':A->bool) E' V'' E''
        ==> !V E.
              graph_subdivision V E V' E'
              ==> graph_subdivision V E V'' E''`
  MP_TAC THENL
   [MATCH_MP_TAC graph_subdivision_INDUCT THEN
    CONJ_TAC THENL
     [REPEAT GEN_TAC THEN DISCH_TAC THEN
      REPEAT GEN_TAC THEN DISCH_THEN ACCEPT_TAC;
      REPEAT GEN_TAC THEN
      INTRO_TAC "(reflection edge_step)" THEN
      REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "prefix") THEN
      MATCH_MP_TAC(CONJUNCT2 graph_subdivision_RULES) THEN
      MAP_EVERY EXISTS_TAC
       [`V':A->bool`; `E':(A->bool)->bool`] THEN
      CONJ_TAC THENL
       [USE_THEN "reflection" MATCH_MP_TAC THEN
        USE_THEN "prefix" ACCEPT_TAC;
        USE_THEN "edge_step" ACCEPT_TAC]];
    DISCH_THEN(LABEL_TAC "transitivity") THEN
    REPEAT GEN_TAC THEN INTRO_TAC "first second" THEN
    USE_THEN "transitivity" MP_TAC THEN
    ASM_MESON_TAC[]]);;

let GRAPH_SUBDIVISION_REPLACE_EDGE_BY_INDEXED_PATH = prove
 (`!n V E. !q:num->A.
        finite_simple_graph (V:A->bool) E /\
        {q 0,q(SUC n)} IN E /\
        INJ q (0..SUC n) (:A) /\
        (!i. 0 < i /\ i < SUC n ==> ~(q i IN V))
        ==> graph_subdivision V E
             (V UNION indexed_path_vertices q (SUC n))
             ((E DELETE {q 0,q(SUC n)}) UNION
              indexed_path_edges q (SUC n))`,
  INDUCT_TAC THENL
   [REPEAT GEN_TAC THEN INTRO_TAC "graph edge injective fresh" THEN
    SUBGOAL_THEN `{(q:num->A) 0,q(SUC 0)} SUBSET V`
    (LABEL_TAC "endpoints") THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN
      INTRO_TAC "_ _ edge_properties" THEN
      USE_THEN "edge_properties" (fun eth ->
       USE_THEN "edge" (fun th ->
        MP_TAC(MATCH_MP
         (SPEC `{(q:num->A) 0,q(SUC 0)}` eth) th))) THEN
      DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT1 th));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(V:A->bool) UNION indexed_path_vertices q (SUC 0) = V`
    (LABEL_TAC "vertices") THENL
     [REWRITE_TAC[INDEXED_PATH_VERTICES_SUC;
                  INDEXED_PATH_VERTICES_0] THEN
      USE_THEN "endpoints"
       (ACCEPT_TAC o MATCH_MP
        (SET_RULE `{a:A,b} SUBSET V
                   ==> V UNION (b INSERT {a}) = V`));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `((E:(A->bool)->bool) DELETE {q 0,q(SUC 0)}) UNION
      indexed_path_edges q (SUC 0) = E`
    (LABEL_TAC "edges") THENL
     [REWRITE_TAC[INDEXED_PATH_EDGES_SUC;
                  INDEXED_PATH_EDGES_0] THEN
      USE_THEN "edge"
       (ACCEPT_TAC o MATCH_MP
        (SET_RULE `a:A IN s
                   ==> (s DELETE a) UNION (a INSERT {}) = s`));
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(CONJUNCT1 graph_subdivision_RULES) THEN
      USE_THEN "graph" ACCEPT_TAC];
    REPEAT GEN_TAC THEN
    INTRO_TAC "graph edge injective fresh" THEN
    SUBGOAL_THEN
     `!e:A->bool. e IN E ==> e SUBSET V`
    (LABEL_TAC "old_edge_vertices") THENL
     [X_GEN_TAC `e:A->bool` THEN
      DISCH_THEN(LABEL_TAC "old_edge") THEN
      USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN
      INTRO_TAC "_ _ edge_properties" THEN
      USE_THEN "edge_properties" (fun eth ->
       USE_THEN "old_edge" (fun th ->
        MP_TAC(MATCH_MP (SPEC `e:A->bool` eth) th))) THEN
      DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT1 th));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{(q:num->A) 0,q(SUC(SUC n))} SUBSET V`
    (LABEL_TAC "endpoints") THENL
     [USE_THEN "old_edge_vertices" MATCH_MP_TAC THEN
      USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((q:num->A)(SUC n) IN V)`
    (LABEL_TAC "penultimate_fresh") THENL
     [USE_THEN "fresh" MATCH_MP_TAC THEN ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((q:num->A) 0 = q(SUC(SUC n)))`
    (LABEL_TAC "endpoints_distinct") THENL
     [USE_THEN "injective" MP_TAC THEN
      REWRITE_TAC[INJ; IN_UNIV] THEN
      DISCH_THEN(LABEL_TAC "injective") THEN
      DISCH_THEN(LABEL_TAC "same") THEN
      SUBGOAL_THEN `0 = SUC(SUC n)` MP_TAC THENL
       [USE_THEN "injective" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[IN_NUMSEG; LE_0; LE_REFL];
        ARITH_TAC];
      ALL_TAC] THEN
    ABBREV_TAC `V1:A->bool = q(SUC n) INSERT V` THEN
    ABBREV_TAC
     `E1:(A->bool)->bool =
        {{q 0,q(SUC n)},{q(SUC n),q(SUC(SUC n))}} UNION
        (E DELETE {q 0,q(SUC(SUC n))})` THEN
    SUBGOAL_THEN
     `graph_edge_subdivision
       (V:A->bool) E (V1:A->bool) (E1:(A->bool)->bool)`
    (LABEL_TAC "edge_step") THENL
     [MAP_EVERY EXPAND_TAC ["V1"; "E1"] THEN
      REWRITE_TAC[graph_edge_subdivision] THEN
      MAP_EVERY EXISTS_TAC
       [`(q:num->A) 0`; `(q:num->A)(SUC(SUC n))`;
        `(q:num->A)(SUC n)`] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_subdivision
       (V:A->bool) E (V1:A->bool) (E1:(A->bool)->bool)`
    (LABEL_TAC "first_subdivision") THENL
     [MATCH_MP_TAC(CONJUNCT2 graph_subdivision_RULES) THEN
      MAP_EVERY EXISTS_TAC
       [`V:A->bool`; `E:(A->bool)->bool`] THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC(CONJUNCT1 graph_subdivision_RULES) THEN
        USE_THEN "graph" ACCEPT_TAC;
       USE_THEN "edge_step" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `finite_simple_graph (V1:A->bool) (E1:(A->bool)->bool)`
    (LABEL_TAC "intermediate_graph") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `V1:A->bool`; `E1:(A->bool)->bool`]
       FINITE_SIMPLE_GRAPH_EDGE_SUBDIVISION) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{(q:num->A) 0,q(SUC n)} IN E1`
    (LABEL_TAC "first_edge") THENL
     [EXPAND_TAC "E1" THEN
      REWRITE_TAC[IN_UNION; IN_INSERT];
      ALL_TAC] THEN
    SUBGOAL_THEN `INJ (q:num->A) (0..SUC n) (:A)`
    (LABEL_TAC "prefix_injective") THENL
     [USE_THEN "injective" MP_TAC THEN
      REWRITE_TAC[INJ; IN_UNIV] THEN
      INTRO_TAC "injective" THEN
      MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
      INTRO_TAC "i_bound j_bound equal" THEN
      USE_THEN "injective" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY
       (fun name -> USE_THEN name MP_TAC)
       ["i_bound"; "j_bound"] THEN
      REWRITE_TAC[IN_NUMSEG] THEN ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!i. 0 < i /\ i < SUC n ==> ~((q:num->A) i IN V1)`
    (LABEL_TAC "prefix_fresh") THENL
     [X_GEN_TAC `i:num` THEN INTRO_TAC "positive bound" THEN
      EXPAND_TAC "V1" THEN
      REWRITE_TAC[IN_INSERT; DE_MORGAN_THM] THEN
      CONJ_TAC THENL
       [DISCH_THEN(LABEL_TAC "equal") THEN
        USE_THEN "injective" MP_TAC THEN
        REWRITE_TAC[INJ; IN_UNIV] THEN
        DISCH_THEN(LABEL_TAC "injective") THEN
        SUBGOAL_THEN `i = SUC n` MP_TAC THENL
         [USE_THEN "injective" MATCH_MP_TAC THEN
          ASM_REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC;
          ASM_ARITH_TAC];
        USE_THEN "fresh" MATCH_MP_TAC THEN ASM_ARITH_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_subdivision
       (V1:A->bool) E1
       (V1 UNION indexed_path_vertices q (SUC n))
       ((E1 DELETE {q 0,q(SUC n)}) UNION
        indexed_path_edges q (SUC n))`
    (LABEL_TAC "prefix_subdivision") THENL
     [MATCH_MP_TAC(SPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`; `q:num->A`]
       (ASSUME
        `!V E. !q:num->A.
          finite_simple_graph (V:A->bool) E /\
          {q 0,q(SUC n)} IN E /\
          INJ q (0..SUC n) (:A) /\
          (!i. 0 < i /\ i < SUC n ==> ~(q i IN V))
          ==> graph_subdivision V E
               (V UNION indexed_path_vertices q (SUC n))
               ((E DELETE {q 0,q(SUC n)}) UNION
                indexed_path_edges q (SUC n))`)) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~({(q:num->A) 0,q(SUC n)} IN E)`
    (LABEL_TAC "new_edge_fresh") THENL
     [DISCH_THEN(LABEL_TAC "old_edge") THEN
      USE_THEN "old_edge_vertices" (fun th ->
       USE_THEN "old_edge" (fun eth ->
        MP_TAC(MATCH_MP
         (SPEC `{(q:num->A) 0,q(SUC n)}` th) eth))) THEN
      REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~({(q:num->A) 0,q(SUC n)} =
        {q(SUC n),q(SUC(SUC n))})`
    (LABEL_TAC "new_edges_distinct") THENL
     [MATCH_MP_TAC(SET_RULE
       `~(a:A = c) ==> ~({a,b} = {b,c})`) THEN
      USE_THEN "endpoints_distinct" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(V1:A->bool) UNION indexed_path_vertices q (SUC n) =
      V UNION indexed_path_vertices q (SUC(SUC n))`
    (LABEL_TAC "vertices") THENL
     [EXPAND_TAC "V1" THEN
      REWRITE_TAC[INDEXED_PATH_VERTICES_SUC] THEN
      MATCH_MP_TAC(SET_RULE
       `last:A IN V /\ penultimate IN P
        ==> (penultimate INSERT V) UNION P =
            V UNION (last INSERT P)`) THEN
      CONJ_TAC THENL
       [USE_THEN "endpoints"
         (ACCEPT_TAC o MATCH_MP
          (SET_RULE `{first:A,last} SUBSET V ==> last IN V`));
        REWRITE_TAC[IN_INSERT]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `((E1:(A->bool)->bool) DELETE {q 0,q(SUC n)}) UNION
        indexed_path_edges q (SUC n) =
      (E DELETE {q 0,q(SUC(SUC n))}) UNION
        indexed_path_edges q (SUC(SUC n))`
    (LABEL_TAC "edges") THENL
     [EXPAND_TAC "E1" THEN
      REWRITE_TAC[INDEXED_PATH_EDGES_SUC] THEN
      MATCH_MP_TAC(SET_RULE
       `~(a:A IN E) /\ ~(a = b)
        ==> ((({a,b} UNION (E DELETE c)) DELETE a) UNION P =
             (E DELETE c) UNION (b INSERT P))`) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "vertices" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "edges" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC GRAPH_SUBDIVISION_TRANS THEN
    MAP_EVERY EXISTS_TAC
     [`V1:A->bool`; `E1:(A->bool)->bool`] THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_SUBDIVISION_EXTEND_EDGE_BY_INDEXED_PATH = prove
 (`!V E V' E' n. !q:num->A.
        graph_subdivision (V:A->bool) E V' E' /\
        {q 0,q(SUC n)} IN E' /\
        INJ q (0..SUC n) (:A) /\
        (!i. 0 < i /\ i < SUC n ==> ~(q i IN V'))
        ==> graph_subdivision V E
             (V' UNION indexed_path_vertices q (SUC n))
             ((E' DELETE {q 0,q(SUC n)}) UNION
              indexed_path_edges q (SUC n))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "subdivision edge injective fresh" THEN
  SUBGOAL_THEN `finite_simple_graph (V':A->bool) E'`
  (LABEL_TAC "target_graph") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `V':A->bool`; `E':(A->bool)->bool`]
     GRAPH_SUBDIVISION_FINITE_SIMPLE) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC GRAPH_SUBDIVISION_TRANS THEN
  MAP_EVERY EXISTS_TAC
   [`V':A->bool`; `E':(A->bool)->bool`] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC GRAPH_SUBDIVISION_REPLACE_EDGE_BY_INDEXED_PATH THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_SUBDIVISION_REPLACE_EDGE_BY_INDEXED_PATH_LENGTH = prove
 (`!l V E. !q:num->A.
        0 < l /\
        finite_simple_graph (V:A->bool) E /\
        {q 0,q l} IN E /\
        INJ q (0..l) (:A) /\
        (!i. 0 < i /\ i < l ==> ~(q i IN V))
        ==> graph_subdivision V E
             (V UNION indexed_path_vertices q l)
             ((E DELETE {q 0,q l}) UNION indexed_path_edges q l)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "positive graph edge injective fresh" THEN
  SUBGOAL_THEN `SUC(l - 1) = l` (LABEL_TAC "length") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "length" (fun th ->
   MATCH_MP_TAC(REWRITE_RULE[th]
    (SPECL
     [`l - 1`; `V:A->bool`; `E:(A->bool)->bool`; `q:num->A`]
     GRAPH_SUBDIVISION_REPLACE_EDGE_BY_INDEXED_PATH))) THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_SUBDIVISION_EXTEND_EDGE_BY_INDEXED_PATH_LENGTH = prove
 (`!V E V' E' l. !q:num->A.
        0 < l /\
        graph_subdivision (V:A->bool) E V' E' /\
        {q 0,q l} IN E' /\
        INJ q (0..l) (:A) /\
        (!i. 0 < i /\ i < l ==> ~(q i IN V'))
        ==> graph_subdivision V E
             (V' UNION indexed_path_vertices q l)
             ((E' DELETE {q 0,q l}) UNION
              indexed_path_edges q l)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "positive subdivision edge injective fresh" THEN
  SUBGOAL_THEN `SUC(l - 1) = l` (LABEL_TAC "length") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "length" (fun th ->
   MATCH_MP_TAC(REWRITE_RULE[th]
    (SPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `V':A->bool`; `E':(A->bool)->bool`;
      `l - 1`; `q:num->A`]
     GRAPH_SUBDIVISION_EXTEND_EDGE_BY_INDEXED_PATH))) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* A K4 subdivision assembled from four paths between its branch vertices.   *)
(* ------------------------------------------------------------------------- *)

let four_path_vertices = new_definition
 `four_path_vertices (a:A) b c d
    (p0:num->A) l0 (p1:num->A) l1
    (p2:num->A) l2 (p3:num->A) l3 =
    ((({a,b,c,d} UNION indexed_path_vertices p0 l0) UNION
       indexed_path_vertices p1 l1) UNION
       indexed_path_vertices p2 l2) UNION
       indexed_path_vertices p3 l3`;;

let four_path_edges = new_definition
 `four_path_edges (a:A) b c d
    (p0:num->A) l0 (p1:num->A) l1
    (p2:num->A) l2 (p3:num->A) l3 =
    (((((((complete_graph_edges {a,b,c,d} DELETE {a,b}) UNION
          indexed_path_edges p0 l0) DELETE {b,c}) UNION
          indexed_path_edges p1 l1) DELETE {c,d}) UNION
          indexed_path_edges p2 l2) DELETE {d,a}) UNION
          indexed_path_edges p3 l3`;;

let FOUR_DISTINCT_GRAPH_FACTS = prove
 (`!a b c d:A.
        ~(a = b) /\ ~(a = c) /\ ~(a = d) /\
        ~(b = c) /\ ~(b = d) /\ ~(c = d)
        ==> finite_simple_graph
             {a,b,c,d} (complete_graph_edges {a,b,c,d}) /\
            {a,b} IN complete_graph_edges {a,b,c,d} /\
            {b,c} IN complete_graph_edges {a,b,c,d} /\
            {c,d} IN complete_graph_edges {a,b,c,d} /\
            {d,a} IN complete_graph_edges {a,b,c,d} /\
            ~({b,c} = {a,b}) /\
            ~({c,d} = {a,b}) /\ ~({c,d} = {b,c}) /\
            ~({d,a} = {a,b}) /\ ~({d,a} = {b,c}) /\
            ~({d,a} = {c,d})`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "ab ac ad bc bd cd" THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SIMPLE_COMPLETE_GRAPH THEN
    SIMP_TAC[FINITE_INSERT; FINITE_EMPTY];
    REWRITE_TAC[IN_COMPLETE_GRAPH_EDGES; PAIR_HAS_SIZE_2] THEN
    ASM SET_TAC[]]);;

let GRAPH_SUBDIVISION_K4_FROM_FOUR_PATHS = prove
 (`!a b c d:A. !l0 l1 l2 l3.
   !p0 p1 p2 p3:num->A.
        (~(a = b) /\ ~(a = c) /\ ~(a = d) /\
         ~(b = c) /\ ~(b = d) /\ ~(c = d)) /\
        (0 < l0 /\ 0 < l1 /\ 0 < l2 /\ 0 < l3) /\
        (p0 0 = a /\ p0 l0 = b /\
         p1 0 = b /\ p1 l1 = c /\
         p2 0 = c /\ p2 l2 = d /\
         p3 0 = d /\ p3 l3 = a) /\
        (INJ p0 (0..l0) (:A) /\
         INJ p1 (0..l1) (:A) /\
         INJ p2 (0..l2) (:A) /\
         INJ p3 (0..l3) (:A)) /\
        (!i. 0 < i /\ i < l0 ==> ~(p0 i IN {a,b,c,d})) /\
        (!i. 0 < i /\ i < l1
             ==> ~(p1 i IN
                   {a,b,c,d} UNION indexed_path_vertices p0 l0)) /\
        (!i. 0 < i /\ i < l2
             ==> ~(p2 i IN
                   ({a,b,c,d} UNION indexed_path_vertices p0 l0) UNION
                   indexed_path_vertices p1 l1)) /\
        (!i. 0 < i /\ i < l3
             ==> ~(p3 i IN
                   (({a,b,c,d} UNION indexed_path_vertices p0 l0) UNION
                    indexed_path_vertices p1 l1) UNION
                   indexed_path_vertices p2 l2))
        ==> graph_subdivision
             {a,b,c,d} (complete_graph_edges {a,b,c,d})
             (four_path_vertices a b c d
               p0 l0 p1 l1 p2 l2 p3 l3)
             (four_path_edges a b c d
               p0 l0 p1 l1 p2 l2 p3 l3)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "(ab ac ad bc bd cd) (l0_positive l1_positive l2_positive l3_positive) \
    (p0_first p0_last p1_first p1_last p2_first p2_last p3_first p3_last) \
    (p0_injective p1_injective p2_injective p3_injective) \
    p0_fresh p1_fresh p2_fresh p3_fresh" THEN
  MP_TAC(SPECL [`a:A`; `b:A`; `c:A`; `d:A`]
   FOUR_DISTINCT_GRAPH_FACTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "base_graph edge_ab edge_bc edge_cd edge_da \
    bc_ab cd_ab cd_bc da_ab da_bc da_cd" THEN
  ABBREV_TAC
   `V0:A->bool =
      {a,b,c,d} UNION indexed_path_vertices (p0:num->A) l0` THEN
  ABBREV_TAC
   `E0:(A->bool)->bool =
      (complete_graph_edges {a,b,c,d} DELETE {a,b}) UNION
      indexed_path_edges (p0:num->A) l0` THEN
  SUBGOAL_THEN
   `graph_subdivision
     {a,b,c,d} (complete_graph_edges {a,b,c,d})
     (V0:A->bool) (E0:(A->bool)->bool)`
  (LABEL_TAC "subdivision0") THENL
   [MAP_EVERY EXPAND_TAC ["V0"; "E0"] THEN
    MATCH_MP_TAC(REWRITE_RULE
     [ASSUME `(p0:num->A) 0 = a`;
      ASSUME `(p0:num->A) l0 = b`]
     (SPECL
      [`l0:num`; `{a:A,b,c,d}`;
       `complete_graph_edges {a:A,b,c,d}`;
       `p0:num->A`]
      GRAPH_SUBDIVISION_REPLACE_EDGE_BY_INDEXED_PATH_LENGTH)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{b:A,c} IN E0` (LABEL_TAC "edge1") THENL
   [EXPAND_TAC "E0" THEN
    REWRITE_TAC[IN_UNION; IN_DELETE] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC
   `V1:A->bool = V0 UNION indexed_path_vertices (p1:num->A) l1` THEN
  ABBREV_TAC
   `E1:(A->bool)->bool =
      (E0 DELETE {b,c}) UNION indexed_path_edges (p1:num->A) l1` THEN
  SUBGOAL_THEN
   `graph_subdivision
     {a,b,c,d} (complete_graph_edges {a,b,c,d})
     (V1:A->bool) (E1:(A->bool)->bool)`
  (LABEL_TAC "subdivision1") THENL
   [MAP_EVERY EXPAND_TAC ["V1"; "E1"] THEN
    MATCH_MP_TAC(REWRITE_RULE
     [ASSUME `(p1:num->A) 0 = b`;
      ASSUME `(p1:num->A) l1 = c`]
     (SPECL
      [`{a:A,b,c,d}`; `complete_graph_edges {a:A,b,c,d}`;
       `V0:A->bool`; `E0:(A->bool)->bool`;
       `l1:num`; `p1:num->A`]
      GRAPH_SUBDIVISION_EXTEND_EDGE_BY_INDEXED_PATH_LENGTH)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{c:A,d} IN E1` (LABEL_TAC "edge2") THENL
   [MAP_EVERY EXPAND_TAC ["E1"; "E0"] THEN
    REWRITE_TAC[IN_UNION; IN_DELETE] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC
   `V2:A->bool = V1 UNION indexed_path_vertices (p2:num->A) l2` THEN
  ABBREV_TAC
   `E2:(A->bool)->bool =
      (E1 DELETE {c,d}) UNION indexed_path_edges (p2:num->A) l2` THEN
  SUBGOAL_THEN
   `graph_subdivision
     {a,b,c,d} (complete_graph_edges {a,b,c,d})
     (V2:A->bool) (E2:(A->bool)->bool)`
  (LABEL_TAC "subdivision2") THENL
   [MAP_EVERY EXPAND_TAC ["V2"; "E2"] THEN
    MATCH_MP_TAC(REWRITE_RULE
     [ASSUME `(p2:num->A) 0 = c`;
      ASSUME `(p2:num->A) l2 = d`]
     (SPECL
      [`{a:A,b,c,d}`; `complete_graph_edges {a:A,b,c,d}`;
       `V1:A->bool`; `E1:(A->bool)->bool`;
       `l2:num`; `p2:num->A`]
      GRAPH_SUBDIVISION_EXTEND_EDGE_BY_INDEXED_PATH_LENGTH)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{d:A,a} IN E2` (LABEL_TAC "edge3") THENL
   [MAP_EVERY EXPAND_TAC ["E2"; "E1"; "E0"] THEN
    REWRITE_TAC[IN_UNION; IN_DELETE] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXPAND_TAC
   ["V2"; "E2"; "V1"; "E1"; "V0"; "E0"] THEN
  REWRITE_TAC[four_path_vertices; four_path_edges] THEN
  MATCH_MP_TAC(REWRITE_RULE
   [ASSUME `(p3:num->A) 0 = d`;
    ASSUME `(p3:num->A) l3 = a`]
   (SPECL
    [`{a:A,b,c,d}`; `complete_graph_edges {a:A,b,c,d}`;
     `(({a,b,c,d} UNION indexed_path_vertices (p0:num->A) l0) UNION
       indexed_path_vertices (p1:num->A) l1) UNION
       indexed_path_vertices (p2:num->A) l2`;
     `(((((complete_graph_edges {a,b,c,d} DELETE {a,b}) UNION
          indexed_path_edges (p0:num->A) l0) DELETE {b,c}) UNION
          indexed_path_edges (p1:num->A) l1) DELETE {c,d}) UNION
          indexed_path_edges (p2:num->A) l2`;
     `l3:num`; `p3:num->A`]
    GRAPH_SUBDIVISION_EXTEND_EDGE_BY_INDEXED_PATH_LENGTH)) THEN
  ASM_REWRITE_TAC[]);;

let INDEXED_PATH_EDGE_ON_BRANCH_VERTICES = prove
 (`!W:A->bool. !p:num->A. !l a b e.
        0 < l /\
        p 0 = a /\
        p l = b /\
        (!i. 0 < i /\ i < l ==> ~(p i IN W)) /\
        e IN indexed_path_edges p l /\
        e SUBSET W
        ==> e = {a,b}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "positive first last fresh edge edge_vertices" THEN
  USE_THEN "edge" MP_TAC THEN
  REWRITE_TAC[IN_INDEXED_PATH_EDGES] THEN
  INTRO_TAC "@i. index edge_value" THEN
  SUBGOAL_THEN `(p:num->A) i IN W /\ p(i + 1) IN W`
  (CONJUNCTS_THEN2 (LABEL_TAC "left_vertex")
   (LABEL_TAC "right_vertex")) THENL
   [USE_THEN "edge_vertices" MP_TAC THEN
    USE_THEN "edge_value" SUBST1_TAC THEN
    REWRITE_TAC[INSERT_SUBSET; SING_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN `i = 0` (LABEL_TAC "left_index") THENL
   [ASM_CASES_TAC `i = 0` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `~((p:num->A) i IN W)` MP_TAC THENL
     [USE_THEN "fresh" MATCH_MP_TAC THEN ASM_ARITH_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `i + 1 = l` (LABEL_TAC "right_index") THENL
   [ASM_CASES_TAC `i + 1 = l` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `~((p:num->A) (i + 1) IN W)` MP_TAC THENL
     [USE_THEN "fresh" MATCH_MP_TAC THEN ASM_ARITH_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let INDEXED_PATH_AVOIDS_OTHER_BRANCH_EDGE = prove
 (`!W:A->bool. !p:num->A. !l a b e.
        0 < l /\
        p 0 = a /\
        p l = b /\
        (!i. 0 < i /\ i < l ==> ~(p i IN W)) /\
        e SUBSET W /\
        ~(e = {a,b})
        ==> ~(e IN indexed_path_edges p l)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "positive first last fresh edge_vertices different" THEN
  DISCH_THEN(LABEL_TAC "edge") THEN
  SUBGOAL_THEN `(e:A->bool) = {a,b}` MP_TAC THENL
   [MATCH_MP_TAC INDEXED_PATH_EDGE_ON_BRANCH_VERTICES THEN
    MAP_EVERY EXISTS_TAC [`W:A->bool`; `p:num->A`; `l:num`] THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;

let SET_SUBSET_DELETE_UNION = prove
 (`!S T U:A->bool. !x.
        ~(x IN S) /\ S SUBSET T
        ==> S SUBSET (T DELETE x) UNION U`,
  SET_TAC[]);;

let FOUR_PATH_EDGES_CONTAIN_PATHS = prove
 (`!a b c d:A. !l0 l1 l2 l3.
   !p0 p1 p2 p3:num->A.
        (~(a = b) /\ ~(a = c) /\ ~(a = d) /\
         ~(b = c) /\ ~(b = d) /\ ~(c = d)) /\
        (0 < l0 /\ 0 < l1 /\ 0 < l2 /\ 0 < l3) /\
        (p0 0 = a /\ p0 l0 = b /\
         p1 0 = b /\ p1 l1 = c /\
         p2 0 = c /\ p2 l2 = d /\
         p3 0 = d /\ p3 l3 = a) /\
        (!i. 0 < i /\ i < l0 ==> ~(p0 i IN {a,b,c,d})) /\
        (!i. 0 < i /\ i < l1 ==> ~(p1 i IN {a,b,c,d})) /\
        (!i. 0 < i /\ i < l2 ==> ~(p2 i IN {a,b,c,d})) /\
        (!i. 0 < i /\ i < l3 ==> ~(p3 i IN {a,b,c,d}))
        ==> indexed_path_edges p0 l0 UNION
            indexed_path_edges p1 l1 UNION
            indexed_path_edges p2 l2 UNION
            indexed_path_edges p3 l3
            SUBSET
            four_path_edges a b c d
              p0 l0 p1 l1 p2 l2 p3 l3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "(ab ac ad bc bd cd) (l0_positive l1_positive l2_positive l3_positive) \
    (p0_first p0_last p1_first p1_last p2_first p2_last p3_first p3_last) \
    p0_fresh p1_fresh p2_fresh p3_fresh" THEN
  MP_TAC(SPECL [`a:A`; `b:A`; `c:A`; `d:A`]
   FOUR_DISTINCT_GRAPH_FACTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "_ _ _ _ _ bc_ab cd_ab cd_bc da_ab da_bc da_cd" THEN
  SUBGOAL_THEN
   `~({b:A,c} IN indexed_path_edges (p0:num->A) l0) /\
    ~({c:A,d} IN indexed_path_edges p0 l0) /\
    ~({d:A,a} IN indexed_path_edges p0 l0)`
  (CONJUNCTS_THEN2 (LABEL_TAC "p0_avoids_bc")
   (CONJUNCTS_THEN2 (LABEL_TAC "p0_avoids_cd")
    (LABEL_TAC "p0_avoids_da"))) THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`{a:A,b,c,d}`; `p0:num->A`; `l0:num`;
        `a:A`; `b:A`; `{b:A,c}`]
       INDEXED_PATH_AVOIDS_OTHER_BRANCH_EDGE) THEN
      ASM_REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_INSERT];
      MATCH_MP_TAC(ISPECL
       [`{a:A,b,c,d}`; `p0:num->A`; `l0:num`;
        `a:A`; `b:A`; `{c:A,d}`]
       INDEXED_PATH_AVOIDS_OTHER_BRANCH_EDGE) THEN
      ASM_REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_INSERT];
      MATCH_MP_TAC(ISPECL
       [`{a:A,b,c,d}`; `p0:num->A`; `l0:num`;
        `a:A`; `b:A`; `{d:A,a}`]
       INDEXED_PATH_AVOIDS_OTHER_BRANCH_EDGE) THEN
      ASM_REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_INSERT]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~({c:A,d} IN indexed_path_edges (p1:num->A) l1) /\
    ~({d:A,a} IN indexed_path_edges p1 l1)`
  (CONJUNCTS_THEN2 (LABEL_TAC "p1_avoids_cd")
   (LABEL_TAC "p1_avoids_da")) THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`{a:A,b,c,d}`; `p1:num->A`; `l1:num`;
        `b:A`; `c:A`; `{c:A,d}`]
       INDEXED_PATH_AVOIDS_OTHER_BRANCH_EDGE) THEN
      ASM_REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_INSERT];
      MATCH_MP_TAC(ISPECL
       [`{a:A,b,c,d}`; `p1:num->A`; `l1:num`;
        `b:A`; `c:A`; `{d:A,a}`]
       INDEXED_PATH_AVOIDS_OTHER_BRANCH_EDGE) THEN
      ASM_REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_INSERT]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~({d:A,a} IN indexed_path_edges (p2:num->A) l2)`
  (LABEL_TAC "p2_avoids_da") THENL
   [MATCH_MP_TAC(ISPECL
     [`{a:A,b,c,d}`; `p2:num->A`; `l2:num`;
      `c:A`; `d:A`; `{d:A,a}`]
     INDEXED_PATH_AVOIDS_OTHER_BRANCH_EDGE) THEN
    ASM_REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_INSERT];
      ALL_TAC] THEN
  REWRITE_TAC[four_path_edges] THEN
  REWRITE_TAC[UNION_SUBSET] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC SET_SUBSET_DELETE_UNION THEN
    CONJ_TAC THENL
     [USE_THEN "p0_avoids_da" ACCEPT_TAC;
      MATCH_MP_TAC SET_SUBSET_DELETE_UNION THEN
      CONJ_TAC THENL
       [USE_THEN "p0_avoids_cd" ACCEPT_TAC;
        MATCH_MP_TAC SET_SUBSET_DELETE_UNION THEN
        ASM_REWRITE_TAC[] THEN
        MATCH_ACCEPT_TAC (CONJUNCT2 SUBSET_UNION)]];
    MATCH_MP_TAC SET_SUBSET_DELETE_UNION THEN
    CONJ_TAC THENL
     [USE_THEN "p1_avoids_da" ACCEPT_TAC;
      MATCH_MP_TAC SET_SUBSET_DELETE_UNION THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_ACCEPT_TAC (CONJUNCT2 SUBSET_UNION)];
    MATCH_MP_TAC SET_SUBSET_DELETE_UNION THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_ACCEPT_TAC (CONJUNCT2 SUBSET_UNION);
    MATCH_ACCEPT_TAC (CONJUNCT2 SUBSET_UNION)]);;

(* ------------------------------------------------------------------------- *)
(* Four alternating vertices on a simple cycle yield a K4 subdivision.       *)
(* ------------------------------------------------------------------------- *)

let cyclic_offset_path = new_definition
 `cyclic_offset_path (q:num->A) a i = q(a + i)`;;

let cyclic_closing_path = new_definition
 `cyclic_closing_path (q:num->A) k n i =
    if i < n - k then q(k + i) else q 0`;;

let cyclic_k4_vertices = new_definition
 `cyclic_k4_vertices (q:num->A) n i j k =
    four_path_vertices
      (q 0) (q i) (q j) (q k)
      q i
      (cyclic_offset_path q i) (j - i)
      (cyclic_offset_path q j) (k - j)
      (cyclic_closing_path q k n) (n - k)`;;

let cyclic_k4_edges = new_definition
 `cyclic_k4_edges (q:num->A) n i j k =
    four_path_edges
      (q 0) (q i) (q j) (q k)
      q i
      (cyclic_offset_path q i) (j - i)
      (cyclic_offset_path q j) (k - j)
      (cyclic_closing_path q k n) (n - k)`;;

let CYCLIC_INJECTIVE_INDEX_EQ = prove
 (`!q:num->A. !n x y.
        INJ q (cyclic_indices n) (:A) /\
        x < n /\ y < n
        ==> (q x = q y <=> x = y)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective x_index y_index" THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "equal") THEN
    USE_THEN "injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV] THEN
    DISCH_THEN(MATCH_MP_TAC o SPECL [`x:num`; `y:num`]) THEN
    ASM_REWRITE_TAC[IN_CYCLIC_INDICES];
    DISCH_THEN SUBST1_TAC THEN REFL_TAC]);;

let CYCLIC_INJECTIVE_INDEX = prove
 (`!q:num->A. !n x y.
        INJ q (cyclic_indices n) (:A) /\
        x < n /\ y < n /\ q x = q y
        ==> x = y`,
  MESON_TAC[CYCLIC_INJECTIVE_INDEX_EQ]);;

let CYCLIC_INJECTIVE_NE = prove
 (`!q:num->A. !n x y.
        INJ q (cyclic_indices n) (:A) /\
        x < n /\ y < n /\ ~(x = y)
        ==> ~(q x = q y)`,
  MESON_TAC[CYCLIC_INJECTIVE_INDEX]);;

let NUM_OFFSET_BOUND = prove
 (`!a x l n:num.
        a + l < n /\ x <= l
        ==> a + x < n`,
  REPEAT GEN_TAC THEN INTRO_TAC "last bound" THEN
  MATCH_MP_TAC LET_TRANS THEN
  EXISTS_TAC `a + l:num` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC LE_ADD2 THEN
    CONJ_TAC THENL
     [REWRITE_TAC[LE_REFL];
      USE_THEN "bound" ACCEPT_TAC];
    USE_THEN "last" ACCEPT_TAC]);;

let CYCLIC_OFFSET_PATH_INJ = prove
 (`!q:num->A. !n a l.
        INJ q (cyclic_indices n) (:A) /\
        a + l < n
        ==> INJ (cyclic_offset_path q a) (0..l) (:A)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective last_index" THEN
  REWRITE_TAC[INJ; IN_UNIV] THEN
  MAP_EVERY X_GEN_TAC [`x:num`; `y:num`] THEN
  REWRITE_TAC[IN_NUMSEG] THEN
  INTRO_TAC "(_ x_bound) (_ y_bound) equal" THEN
  SUBGOAL_THEN
   `(q:num->A) (a + x) = q(a + y)`
  (LABEL_TAC "q_equal") THENL
   [USE_THEN "equal" MP_TAC THEN
    REWRITE_TAC[cyclic_offset_path];
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:num) + x < n /\ a + y < n`
  (CONJUNCTS_THEN2 (LABEL_TAC "x_index")
   (LABEL_TAC "y_index")) THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC NUM_OFFSET_BOUND THEN
      EXISTS_TAC `l:num` THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC NUM_OFFSET_BOUND THEN
      EXISTS_TAC `l:num` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:num) + x = a + y`
  (LABEL_TAC "index_equal") THENL
   [MATCH_MP_TAC CYCLIC_INJECTIVE_INDEX THEN
    MAP_EVERY EXISTS_TAC [`q:num->A`; `n:num`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "index_equal" MP_TAC THEN
  REWRITE_TAC[EQ_ADD_LCANCEL]);;

let CYCLIC_CLOSING_PATH_VALUES = prove
 (`!q:num->A. !n k.
        0 < k /\ k < n
        ==> cyclic_closing_path q k n 0 = q k /\
            cyclic_closing_path q k n (n - k) = q 0`,
  REPEAT GEN_TAC THEN INTRO_TAC "positive index" THEN
  REWRITE_TAC[cyclic_closing_path] THEN
  ASM_SIMP_TAC[ARITH_RULE `k < n ==> 0 < n - k`;
               LT_REFL; ADD_CLAUSES]);;

let NUM_CLOSING_INTERIOR_BOUND = prove
 (`!k n x:num.
        k + (n - k) = n /\ x < n - k
        ==> k + x < n`,
  REPEAT GEN_TAC THEN INTRO_TAC "split bound" THEN
  USE_THEN "split" (SUBST1_TAC o SYM) THEN
  REWRITE_TAC[LT_ADD_LCANCEL] THEN
  USE_THEN "bound" ACCEPT_TAC);;

let CYCLIC_CLOSING_PATH_INJ = prove
 (`!q:num->A. !n k.
        0 < k /\ k < n /\
        INJ q (cyclic_indices n) (:A)
        ==> INJ (cyclic_closing_path q k n) (0..n - k) (:A)`,
  REPEAT GEN_TAC THEN INTRO_TAC "k_positive k_index injective" THEN
  REWRITE_TAC[INJ; IN_UNIV] THEN
  MAP_EVERY X_GEN_TAC [`x:num`; `y:num`] THEN
  REWRITE_TAC[IN_NUMSEG] THEN
  INTRO_TAC "(_ x_bound) (_ y_bound) equal" THEN
  SUBGOAL_THEN `((n:num) - k) + k = n`
  (LABEL_TAC "split") THENL
   [MATCH_MP_TAC SUB_ADD THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(k:num) + (n - k) = n`
  (LABEL_TAC "split_left") THENL
   [USE_THEN "split"
     (ACCEPT_TAC o ONCE_REWRITE_RULE[ADD_SYM]);
    ALL_TAC] THEN
  ASM_CASES_TAC `(x:num) < n - k` THEN
  ASM_CASES_TAC `(y:num) < n - k` THENL
   [SUBGOAL_THEN
    `(q:num->A) (k + x) = q(k + y)`
    (LABEL_TAC "q_equal") THENL
     [USE_THEN "equal"
       (ACCEPT_TAC o REWRITE_RULE
        [cyclic_closing_path;
         ASSUME `(x:num) < n - k`;
         ASSUME `(y:num) < n - k`]);
      ALL_TAC] THEN
    SUBGOAL_THEN `(k:num) + x < n /\ k + y < n`
    (CONJUNCTS_THEN2 (LABEL_TAC "x_index")
     (LABEL_TAC "y_index")) THENL
     [CONJ_TAC THEN
      MATCH_MP_TAC NUM_CLOSING_INTERIOR_BOUND THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(k:num) + x = k + y` MP_TAC THENL
     [MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(k:num) + x`; `(k:num) + y`]
       CYCLIC_INJECTIVE_INDEX) THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[EQ_ADD_LCANCEL]];
    SUBGOAL_THEN `(y:num) = n - k` (LABEL_TAC "y_last") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(q:num->A) (k + x) = q 0`
    (LABEL_TAC "q_equal") THENL
     [USE_THEN "equal"
       (ACCEPT_TAC o REWRITE_RULE
        [cyclic_closing_path;
         ASSUME `(x:num) < n - k`;
         ASSUME `~((y:num) < n - k)`]);
      ALL_TAC] THEN
    SUBGOAL_THEN `(k:num) + x < n` (LABEL_TAC "x_index") THENL
     [MATCH_MP_TAC NUM_CLOSING_INTERIOR_BOUND THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(k:num) + x = 0` MP_TAC THENL
     [MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(k:num) + x`; `0`]
       CYCLIC_INJECTIVE_INDEX) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ASM_ARITH_TAC];
    SUBGOAL_THEN `(x:num) = n - k` (LABEL_TAC "x_last") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(q:num->A) 0 = q(k + y)`
    (LABEL_TAC "q_equal") THENL
     [USE_THEN "equal"
       (ACCEPT_TAC o REWRITE_RULE
        [cyclic_closing_path;
         ASSUME `~((x:num) < n - k)`;
         ASSUME `(y:num) < n - k`]);
      ALL_TAC] THEN
    SUBGOAL_THEN `(k:num) + y < n` (LABEL_TAC "y_index") THENL
     [MATCH_MP_TAC NUM_CLOSING_INTERIOR_BOUND THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `0 = (k:num) + y` MP_TAC THENL
     [MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `0`; `(k:num) + y`]
       CYCLIC_INJECTIVE_INDEX) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ASM_ARITH_TAC];
    ASM_ARITH_TAC]);;

let CYCLIC_PREFIX_PATH_INJ = prove
 (`!q:num->A. !n l.
        INJ q (cyclic_indices n) (:A) /\
        l < n
        ==> INJ q (0..l) (:A)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective last_index" THEN
  REWRITE_TAC[INJ; IN_UNIV] THEN
  MAP_EVERY X_GEN_TAC [`x:num`; `y:num`] THEN
  REWRITE_TAC[IN_NUMSEG] THEN
  INTRO_TAC "(_ x_bound) (_ y_bound) equal" THEN
  MATCH_MP_TAC CYCLIC_INJECTIVE_INDEX THEN
  MAP_EVERY EXISTS_TAC [`q:num->A`; `n:num`] THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let CYCLIC_VERTEX_NOT_IN_FOUR = prove
 (`!q:num->A. !n h a b c d.
        INJ q (cyclic_indices n) (:A) /\
        h < n /\ a < n /\ b < n /\ c < n /\ d < n /\
        ~(h = a) /\ ~(h = b) /\ ~(h = c) /\ ~(h = d)
        ==> ~(q h IN {q a,q b,q c,q d})`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[IN_INSERT; IN_SING] THEN
  MESON_TAC[CYCLIC_INJECTIVE_INDEX]);;

let CYCLIC_VERTEX_NOT_IN_PREFIX_PATH = prove
 (`!q:num->A. !n h l.
        INJ q (cyclic_indices n) (:A) /\
        h < n /\ l < h
        ==> ~(q h IN indexed_path_vertices q l)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective h_index earlier" THEN
  REWRITE_TAC[IN_INDEXED_PATH_VERTICES] THEN
  INTRO_TAC "@u. u_bound value" THEN
  SUBGOAL_THEN `(u:num) < n /\ ~(h = u)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_index")
   (LABEL_TAC "different")) THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  ASM_MESON_TAC[CYCLIC_INJECTIVE_INDEX]);;

let CYCLIC_VERTEX_NOT_IN_OFFSET_PATH = prove
 (`!q:num->A. !n h a l.
        INJ q (cyclic_indices n) (:A) /\
        h < n /\ a + l < h
        ==> ~(q h IN
              indexed_path_vertices (cyclic_offset_path q a) l)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective h_index earlier" THEN
  REWRITE_TAC[IN_INDEXED_PATH_VERTICES; cyclic_offset_path] THEN
  INTRO_TAC "@u. u_bound value" THEN
  SUBGOAL_THEN `(a:num) + u < h`
  (LABEL_TAC "u_before_h") THENL
   [MATCH_MP_TAC NUM_OFFSET_BOUND THEN
    EXISTS_TAC `l:num` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:num) + u < n /\ ~(h = a + u)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_index")
   (LABEL_TAC "different")) THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  ASM_MESON_TAC[CYCLIC_INJECTIVE_INDEX]);;

let NUM_ADD_SUB_RIGHT = prove
 (`!a b:num. a <= b ==> a + (b - a) = b`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "order") THEN
  MP_TAC(SPECL [`b:num`; `a:num`] SUB_ADD) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[ADD_SYM]);;

let CYCLIC_FOUR_PATH_DATA = prove
 (`!q:num->A. !n i j k.
        0 < i /\ i < j /\ j < k /\ k < n /\
        INJ q (cyclic_indices n) (:A)
        ==> (~(q 0 = q i) /\ ~(q 0 = q j) /\ ~(q 0 = q k) /\
             ~(q i = q j) /\ ~(q i = q k) /\ ~(q j = q k)) /\
            (0 < i /\ 0 < j - i /\ 0 < k - j /\ 0 < n - k) /\
            (q 0 = q 0 /\ q i = q i /\
             cyclic_offset_path q i 0 = q i /\
             cyclic_offset_path q i (j - i) = q j /\
             cyclic_offset_path q j 0 = q j /\
             cyclic_offset_path q j (k - j) = q k /\
             cyclic_closing_path q k n 0 = q k /\
             cyclic_closing_path q k n (n - k) = q 0) /\
            (INJ q (0..i) (:A) /\
             INJ (cyclic_offset_path q i) (0..j - i) (:A) /\
             INJ (cyclic_offset_path q j) (0..k - j) (:A) /\
             INJ (cyclic_closing_path q k n) (0..n - k) (:A)) /\
            (!t. 0 < t /\ t < i
                 ==> ~(q t IN {q 0,q i,q j,q k})) /\
            (!t. 0 < t /\ t < j - i
                 ==> ~(cyclic_offset_path q i t IN
                       {q 0,q i,q j,q k} UNION
                       indexed_path_vertices q i)) /\
            (!t. 0 < t /\ t < k - j
                 ==> ~(cyclic_offset_path q j t IN
                       ({q 0,q i,q j,q k} UNION
                        indexed_path_vertices q i) UNION
                       indexed_path_vertices
                        (cyclic_offset_path q i) (j - i))) /\
            (!t. 0 < t /\ t < n - k
                 ==> ~(cyclic_closing_path q k n t IN
                       (({q 0,q i,q j,q k} UNION
                         indexed_path_vertices q i) UNION
                        indexed_path_vertices
                         (cyclic_offset_path q i) (j - i)) UNION
                       indexed_path_vertices
                        (cyclic_offset_path q j) (k - j)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "i_positive ij jk kn injective" THEN
  SUBGOAL_THEN `(i:num) + (j - i) = j`
  (LABEL_TAC "ij_split") THENL
   [MATCH_MP_TAC NUM_ADD_SUB_RIGHT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(j:num) + (k - j) = k`
  (LABEL_TAC "jk_split") THENL
   [MATCH_MP_TAC NUM_ADD_SUB_RIGHT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(k:num) + (n - k) = n`
  (LABEL_TAC "kn_split") THENL
   [MATCH_MP_TAC NUM_ADD_SUB_RIGHT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((q:num->A) 0 = q i) /\ ~(q 0 = q j) /\ ~(q 0 = q k) /\
    ~(q i = q j) /\ ~(q i = q k) /\ ~(q j = q k)`
  (LABEL_TAC "distinct") THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC CYCLIC_INJECTIVE_NE THEN
      EXISTS_TAC `n:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC CYCLIC_INJECTIVE_NE THEN
      EXISTS_TAC `n:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC CYCLIC_INJECTIVE_NE THEN
      EXISTS_TAC `n:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC CYCLIC_INJECTIVE_NE THEN
      EXISTS_TAC `n:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC CYCLIC_INJECTIVE_NE THEN
      EXISTS_TAC `n:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC CYCLIC_INJECTIVE_NE THEN
      EXISTS_TAC `n:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `0 < i /\ 0 < j - i /\ 0 < k - j /\ 0 < n - k`
  (LABEL_TAC "lengths") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `0 < (k:num)` (LABEL_TAC "k_positive") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(i:num) < n /\ (j:num) < n`
  (CONJUNCTS_THEN2 (LABEL_TAC "i_index")
   (LABEL_TAC "j_index")) THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(i:num) + (j - i) < n`
  (LABEL_TAC "p1_last_index") THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(j:num) + (k - j) < n`
  (LABEL_TAC "p2_last_index") THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_closing_path (q:num->A) k n 0 = q k /\
    cyclic_closing_path q k n (n - k) = q 0`
  (CONJUNCTS_THEN2 (LABEL_TAC "closing_first")
   (LABEL_TAC "closing_last")) THENL
   [USE_THEN "k_positive" (fun kth ->
     USE_THEN "kn" (fun knth ->
      ACCEPT_TAC(MATCH_MP
       (SPECL [`q:num->A`; `n:num`; `k:num`]
        CYCLIC_CLOSING_PATH_VALUES)
       (CONJ kth knth))));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:num->A) 0 = q 0 /\ q i = q i /\
    cyclic_offset_path q i 0 = q i /\
    cyclic_offset_path q i (j - i) = q j /\
    cyclic_offset_path q j 0 = q j /\
    cyclic_offset_path q j (k - j) = q k /\
    cyclic_closing_path q k n 0 = q k /\
    cyclic_closing_path q k n (n - k) = q 0`
  (LABEL_TAC "endpoints") THENL
   [ASM_REWRITE_TAC[cyclic_offset_path; ADD_CLAUSES];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `INJ (q:num->A) (0..i) (:A) /\
    INJ (cyclic_offset_path q i) (0..j - i) (:A) /\
    INJ (cyclic_offset_path q j) (0..k - j) (:A) /\
    INJ (cyclic_closing_path q k n) (0..n - k) (:A)`
  (LABEL_TAC "path_injective") THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "injective" (fun ith ->
       USE_THEN "i_index" (fun index_th ->
        ACCEPT_TAC(MATCH_MP
         (SPECL [`q:num->A`; `n:num`; `i:num`]
          CYCLIC_PREFIX_PATH_INJ)
         (CONJ ith index_th))));
      USE_THEN "injective" (fun ith ->
       USE_THEN "p1_last_index" (fun index_th ->
        ACCEPT_TAC(MATCH_MP
         (SPECL
          [`q:num->A`; `n:num`; `i:num`; `j - i:num`]
          CYCLIC_OFFSET_PATH_INJ)
         (CONJ ith index_th))));
      USE_THEN "injective" (fun ith ->
       USE_THEN "p2_last_index" (fun index_th ->
        ACCEPT_TAC(MATCH_MP
         (SPECL
          [`q:num->A`; `n:num`; `j:num`; `k - j:num`]
          CYCLIC_OFFSET_PATH_INJ)
         (CONJ ith index_th))));
      USE_THEN "k_positive" (fun kpth ->
       USE_THEN "kn" (fun kth ->
        USE_THEN "injective" (fun ith ->
         ACCEPT_TAC(MATCH_MP
          (SPECL [`q:num->A`; `n:num`; `k:num`]
           CYCLIC_CLOSING_PATH_INJ)
          (CONJ kpth (CONJ kth ith))))))];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t. 0 < t /\ t < i
        ==> ~((q:num->A) t IN {q 0,q i,q j,q k})`
  (LABEL_TAC "fresh0") THENL
   [X_GEN_TAC `t:num` THEN INTRO_TAC "positive bound" THEN
    MATCH_MP_TAC(ISPECL
     [`q:num->A`; `n:num`; `t:num`;
      `0`; `i:num`; `j:num`; `k:num`]
     CYCLIC_VERTEX_NOT_IN_FOUR) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t. 0 < t /\ t < j - i
        ==> ~(cyclic_offset_path (q:num->A) i t IN
              {q 0,q i,q j,q k} UNION
              indexed_path_vertices q i)`
  (LABEL_TAC "fresh1") THENL
   [X_GEN_TAC `t:num` THEN INTRO_TAC "positive bound" THEN
    SUBGOAL_THEN `(i:num) + t < j`
    (LABEL_TAC "index_before_j") THENL
     [MATCH_MP_TAC NUM_CLOSING_INTERIOR_BOUND THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[cyclic_offset_path; IN_UNION; DE_MORGAN_THM] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(i:num) + t`;
        `0`; `i:num`; `j:num`; `k:num`]
       CYCLIC_VERTEX_NOT_IN_FOUR) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(i:num) + t`; `i:num`]
       CYCLIC_VERTEX_NOT_IN_PREFIX_PATH) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t. 0 < t /\ t < k - j
        ==> ~(cyclic_offset_path (q:num->A) j t IN
              ({q 0,q i,q j,q k} UNION
               indexed_path_vertices q i) UNION
              indexed_path_vertices
               (cyclic_offset_path q i) (j - i))`
  (LABEL_TAC "fresh2") THENL
   [X_GEN_TAC `t:num` THEN INTRO_TAC "positive bound" THEN
    SUBGOAL_THEN `(j:num) + t < k`
    (LABEL_TAC "index_before_k") THENL
     [MATCH_MP_TAC NUM_CLOSING_INTERIOR_BOUND THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[cyclic_offset_path; IN_UNION; DE_MORGAN_THM] THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(j:num) + t`;
        `0`; `i:num`; `j:num`; `k:num`]
       CYCLIC_VERTEX_NOT_IN_FOUR) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(j:num) + t`; `i:num`]
       CYCLIC_VERTEX_NOT_IN_PREFIX_PATH) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(j:num) + t`;
        `i:num`; `j - i:num`]
       CYCLIC_VERTEX_NOT_IN_OFFSET_PATH) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t. 0 < t /\ t < n - k
        ==> ~(cyclic_closing_path (q:num->A) k n t IN
              (({q 0,q i,q j,q k} UNION
                indexed_path_vertices q i) UNION
               indexed_path_vertices
                (cyclic_offset_path q i) (j - i)) UNION
              indexed_path_vertices
               (cyclic_offset_path q j) (k - j))`
  (LABEL_TAC "fresh3") THENL
   [X_GEN_TAC `t:num` THEN INTRO_TAC "positive bound" THEN
    SUBGOAL_THEN `(k:num) + t < n`
    (LABEL_TAC "index_before_n") THENL
     [MATCH_MP_TAC NUM_CLOSING_INTERIOR_BOUND THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[cyclic_closing_path] THEN
    REWRITE_TAC[IN_UNION; DE_MORGAN_THM] THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(k:num) + t`;
        `0`; `i:num`; `j:num`; `k:num`]
       CYCLIC_VERTEX_NOT_IN_FOUR) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(k:num) + t`; `i:num`]
       CYCLIC_VERTEX_NOT_IN_PREFIX_PATH) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(k:num) + t`;
        `i:num`; `j - i:num`]
       CYCLIC_VERTEX_NOT_IN_OFFSET_PATH) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(k:num) + t`;
        `j:num`; `k - j:num`]
       CYCLIC_VERTEX_NOT_IN_OFFSET_PATH) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let CYCLIC_K4_SUBDIVISION_RAW = prove
 (`!q:num->A. !n i j k.
        0 < i /\ i < j /\ j < k /\ k < n /\
        INJ q (cyclic_indices n) (:A)
        ==> graph_subdivision
             {q 0,q i,q j,q k}
             (complete_graph_edges {q 0,q i,q j,q k})
             (cyclic_k4_vertices q n i j k)
             (cyclic_k4_edges q n i j k)`,
  REPEAT GEN_TAC THEN INTRO_TAC "i_positive ij jk kn injective" THEN
  REWRITE_TAC[cyclic_k4_vertices; cyclic_k4_edges] THEN
  MATCH_MP_TAC GRAPH_SUBDIVISION_K4_FROM_FOUR_PATHS THEN
  MATCH_MP_TAC CYCLIC_FOUR_PATH_DATA THEN
  ASM_REWRITE_TAC[]);;

let INDEXED_PREFIX_VERTICES_SUBSET_CYCLIC = prove
 (`!q:num->A. !l n.
        l < n
        ==> indexed_path_vertices q l SUBSET cyclic_vertices q n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "last_index") THEN
  REWRITE_TAC[SUBSET; IN_INDEXED_PATH_VERTICES;
              IN_CYCLIC_VERTICES] THEN
  X_GEN_TAC `x:A` THEN
  INTRO_TAC "@t. t_bound value" THEN
  EXISTS_TAC `t:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let INDEXED_OFFSET_VERTICES_SUBSET_CYCLIC = prove
 (`!q:num->A. !a l n.
        a + l < n
        ==> indexed_path_vertices (cyclic_offset_path q a) l
            SUBSET cyclic_vertices q n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "last_index") THEN
  REWRITE_TAC[SUBSET; IN_INDEXED_PATH_VERTICES;
              IN_CYCLIC_VERTICES; cyclic_offset_path] THEN
  X_GEN_TAC `x:A` THEN
  INTRO_TAC "@t. t_bound value" THEN
  EXISTS_TAC `a + t:num` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC NUM_OFFSET_BOUND THEN
  EXISTS_TAC `l:num` THEN ASM_REWRITE_TAC[]);;

let INDEXED_CLOSING_VERTICES_SUBSET_CYCLIC = prove
 (`!q:num->A. !k n.
        k < n
        ==> indexed_path_vertices (cyclic_closing_path q k n) (n - k)
            SUBSET cyclic_vertices q n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "k_index") THEN
  REWRITE_TAC[SUBSET; IN_INDEXED_PATH_VERTICES] THEN
  X_GEN_TAC `x:A` THEN
  INTRO_TAC "@t. t_bound value" THEN
  ASM_CASES_TAC `(t:num) < n - k` THENL
   [USE_THEN "value" SUBST1_TAC THEN
    REWRITE_TAC[cyclic_closing_path; IN_CYCLIC_VERTICES] THEN
    ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `k + t:num` THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(k:num) + (n - k) = n`
    (LABEL_TAC "split") THENL
     [MATCH_MP_TAC NUM_ADD_SUB_RIGHT THEN ASM_ARITH_TAC;
      MATCH_MP_TAC NUM_CLOSING_INTERIOR_BOUND THEN
      ASM_REWRITE_TAC[]];
    SUBGOAL_THEN `(t:num) = n - k` (LABEL_TAC "last") THENL
     [ASM_ARITH_TAC;
      USE_THEN "value" SUBST1_TAC THEN
      ASM_REWRITE_TAC[cyclic_closing_path; IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `0` THEN ASM_ARITH_TAC]]);;

let CYCLIC_K4_VERTICES_EQ = prove
 (`!q:num->A. !n i j k.
        0 < i /\ i < j /\ j < k /\ k < n
        ==> cyclic_k4_vertices q n i j k = cyclic_vertices q n`,
  REPEAT GEN_TAC THEN INTRO_TAC "i_positive ij jk kn" THEN
  SUBGOAL_THEN `(i:num) + (j - i) = j`
  (LABEL_TAC "ij_split") THENL
   [MATCH_MP_TAC NUM_ADD_SUB_RIGHT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(j:num) + (k - j) = k`
  (LABEL_TAC "jk_split") THENL
   [MATCH_MP_TAC NUM_ADD_SUB_RIGHT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(k:num) + (n - k) = n`
  (LABEL_TAC "kn_split") THENL
   [MATCH_MP_TAC NUM_ADD_SUB_RIGHT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[cyclic_k4_vertices; four_path_vertices;
                UNION_SUBSET] THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[INSERT_SUBSET; SING_SUBSET;
                  IN_CYCLIC_VERTICES] THEN
      REPEAT CONJ_TAC THENL
       [EXISTS_TAC `0` THEN ASM_ARITH_TAC;
        EXISTS_TAC `i:num` THEN ASM_ARITH_TAC;
        EXISTS_TAC `j:num` THEN ASM_ARITH_TAC;
        EXISTS_TAC `k:num` THEN ASM_ARITH_TAC];
      MATCH_MP_TAC INDEXED_PREFIX_VERTICES_SUBSET_CYCLIC THEN
      ASM_ARITH_TAC;
      MATCH_MP_TAC INDEXED_OFFSET_VERTICES_SUBSET_CYCLIC THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC INDEXED_OFFSET_VERTICES_SUBSET_CYCLIC THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC INDEXED_CLOSING_VERTICES_SUBSET_CYCLIC THEN
      ASM_REWRITE_TAC[]];
    REWRITE_TAC[SUBSET; IN_CYCLIC_VERTICES] THEN
    X_GEN_TAC `x:A` THEN
    INTRO_TAC "@h. h_index value" THEN
    USE_THEN "value" SUBST1_TAC THEN
    REWRITE_TAC[cyclic_k4_vertices; four_path_vertices] THEN
    ASM_CASES_TAC `(h:num) <= i` THENL
     [SUBGOAL_THEN
       `(q:num->A) h IN indexed_path_vertices q i`
      (LABEL_TAC "path_member") THENL
       [REWRITE_TAC[IN_INDEXED_PATH_VERTICES] THEN
        EXISTS_TAC `h:num` THEN ASM_REWRITE_TAC[];
        USE_THEN "path_member" MP_TAC THEN SET_TAC[]];
      ALL_TAC] THEN
    ASM_CASES_TAC `(h:num) <= j` THENL
     [SUBGOAL_THEN
       `(q:num->A) h IN
        indexed_path_vertices (cyclic_offset_path q i) (j - i)`
      (LABEL_TAC "path_member") THENL
       [REWRITE_TAC[IN_INDEXED_PATH_VERTICES;
                    cyclic_offset_path] THEN
        EXISTS_TAC `h - i:num` THEN
        CONJ_TAC THENL
         [ASM_ARITH_TAC;
          AP_TERM_TAC THEN ASM_ARITH_TAC];
        USE_THEN "path_member" MP_TAC THEN SET_TAC[]];
      ALL_TAC] THEN
    ASM_CASES_TAC `(h:num) <= k` THENL
     [SUBGOAL_THEN
       `(q:num->A) h IN
        indexed_path_vertices (cyclic_offset_path q j) (k - j)`
      (LABEL_TAC "path_member") THENL
       [REWRITE_TAC[IN_INDEXED_PATH_VERTICES;
                    cyclic_offset_path] THEN
        EXISTS_TAC `h - j:num` THEN
        CONJ_TAC THENL
         [ASM_ARITH_TAC;
          AP_TERM_TAC THEN ASM_ARITH_TAC];
        USE_THEN "path_member" MP_TAC THEN SET_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(q:num->A) h IN
      indexed_path_vertices (cyclic_closing_path q k n) (n - k)`
    (LABEL_TAC "path_member") THENL
     [REWRITE_TAC[IN_INDEXED_PATH_VERTICES] THEN
      EXISTS_TAC `h - k:num` THEN
      CONJ_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[cyclic_closing_path] THEN
        SUBGOAL_THEN `(h:num) - k < n - k`
        (LABEL_TAC "interior") THENL
         [ASM_ARITH_TAC;
          ASM_REWRITE_TAC[] THEN
          AP_TERM_TAC THEN ASM_ARITH_TAC]];
      USE_THEN "path_member" MP_TAC THEN SET_TAC[]]]);;

let CYCLIC_EDGES_SUBSET_FOUR_INDEXED_PATHS = prove
 (`!q:num->A. !n i j k.
        0 < i /\ i < j /\ j < k /\ k < n
        ==> cyclic_edges q n SUBSET
            indexed_path_edges q i UNION
            indexed_path_edges (cyclic_offset_path q i) (j - i) UNION
            indexed_path_edges (cyclic_offset_path q j) (k - j) UNION
            indexed_path_edges (cyclic_closing_path q k n) (n - k)`,
  REPEAT GEN_TAC THEN INTRO_TAC "i_positive ij jk kn" THEN
  MATCH_MP_TAC CYCLIC_EDGES_SUBSET_OF_CHAIN_AND_LAST THEN
  CONJ_TAC THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [X_GEN_TAC `h:num` THEN DISCH_THEN(LABEL_TAC "successor_index") THEN
    ASM_CASES_TAC `(h:num) < i` THENL
     [SUBGOAL_THEN
       `{(q:num->A) h,q(h + 1)} IN indexed_path_edges q i`
      (LABEL_TAC "path_edge") THENL
       [REWRITE_TAC[IN_INDEXED_PATH_EDGES] THEN
        EXISTS_TAC `h:num` THEN ASM_REWRITE_TAC[];
        USE_THEN "path_edge" MP_TAC THEN SET_TAC[]];
      ALL_TAC] THEN
    ASM_CASES_TAC `(h:num) < j` THENL
     [SUBGOAL_THEN
       `{(q:num->A) h,q(h + 1)} IN
        indexed_path_edges (cyclic_offset_path q i) (j - i)`
      (LABEL_TAC "path_edge") THENL
       [REWRITE_TAC[IN_INDEXED_PATH_EDGES] THEN
        EXISTS_TAC `h - i:num` THEN
        CONJ_TAC THENL
         [ASM_ARITH_TAC;
          SUBGOAL_THEN `(i:num) + (h - i) = h`
          (LABEL_TAC "left_index") THENL
           [ASM_ARITH_TAC;
            ALL_TAC] THEN
          SUBGOAL_THEN `(i:num) + (h - i + 1) = h + 1`
          (LABEL_TAC "right_index") THENL
           [ASM_ARITH_TAC;
            ASM_REWRITE_TAC[cyclic_offset_path]]];
        USE_THEN "path_edge" MP_TAC THEN SET_TAC[]];
      ALL_TAC] THEN
    ASM_CASES_TAC `(h:num) < k` THENL
     [SUBGOAL_THEN
       `{(q:num->A) h,q(h + 1)} IN
        indexed_path_edges (cyclic_offset_path q j) (k - j)`
      (LABEL_TAC "path_edge") THENL
       [REWRITE_TAC[IN_INDEXED_PATH_EDGES] THEN
        EXISTS_TAC `h - j:num` THEN
        CONJ_TAC THENL
         [ASM_ARITH_TAC;
          SUBGOAL_THEN `(j:num) + (h - j) = h`
          (LABEL_TAC "left_index") THENL
           [ASM_ARITH_TAC;
            ALL_TAC] THEN
          SUBGOAL_THEN `(j:num) + (h - j + 1) = h + 1`
          (LABEL_TAC "right_index") THENL
           [ASM_ARITH_TAC;
            ASM_REWRITE_TAC[cyclic_offset_path]]];
        USE_THEN "path_edge" MP_TAC THEN SET_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{(q:num->A) h,q(h + 1)} IN
      indexed_path_edges (cyclic_closing_path q k n) (n - k)`
    (LABEL_TAC "path_edge") THENL
     [REWRITE_TAC[IN_INDEXED_PATH_EDGES] THEN
      EXISTS_TAC `h - k:num` THEN
      CONJ_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `(h:num) - k < n - k /\
                      h - k + 1 < n - k`
        (CONJUNCTS_THEN2 (LABEL_TAC "left_interior")
         (LABEL_TAC "right_interior")) THENL
         [ASM_ARITH_TAC;
          SUBGOAL_THEN `(k:num) + (h - k) = h`
          (LABEL_TAC "left_index") THENL
           [ASM_ARITH_TAC;
            ALL_TAC] THEN
          SUBGOAL_THEN `(k:num) + (h - k + 1) = h + 1`
          (LABEL_TAC "right_index") THENL
           [ASM_ARITH_TAC;
            ASM_REWRITE_TAC[cyclic_closing_path]]]];
      USE_THEN "path_edge" MP_TAC THEN SET_TAC[]];
    SUBGOAL_THEN
     `{(q:num->A) (n - 1),q 0} IN
      indexed_path_edges (cyclic_closing_path q k n) (n - k)`
    (LABEL_TAC "path_edge") THENL
     [REWRITE_TAC[IN_INDEXED_PATH_EDGES] THEN
      EXISTS_TAC `n - k - 1:num` THEN
      CONJ_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `(n:num) - k - 1 < n - k`
        (LABEL_TAC "left_interior") THENL
         [ASM_ARITH_TAC;
          ALL_TAC] THEN
        SUBGOAL_THEN `~((n:num) - k - 1 + 1 < n - k)`
        (LABEL_TAC "right_endpoint") THENL
         [ASM_ARITH_TAC;
          ALL_TAC] THEN
        SUBGOAL_THEN `(k:num) + (n - k - 1) = n - 1`
        (LABEL_TAC "left_index") THENL
         [ASM_ARITH_TAC;
          ASM_REWRITE_TAC[cyclic_closing_path]]];
      USE_THEN "path_edge" MP_TAC THEN SET_TAC[]]]);;

let FOUR_INDEXED_PATHS_SUBSET_CYCLIC_K4_EDGES = prove
 (`!q:num->A. !n i j k.
        0 < i /\ i < j /\ j < k /\ k < n /\
        INJ q (cyclic_indices n) (:A)
        ==> indexed_path_edges q i UNION
            indexed_path_edges (cyclic_offset_path q i) (j - i) UNION
            indexed_path_edges (cyclic_offset_path q j) (k - j) UNION
            indexed_path_edges (cyclic_closing_path q k n) (n - k)
            SUBSET cyclic_k4_edges q n i j k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "i_positive ij jk kn injective" THEN
  REWRITE_TAC[cyclic_k4_edges] THEN
  MATCH_MP_TAC FOUR_PATH_EDGES_CONTAIN_PATHS THEN
  MP_TAC(ISPECL [`q:num->A`; `n:num`; `i:num`; `j:num`; `k:num`]
    CYCLIC_FOUR_PATH_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  MESON_TAC[IN_UNION]);;

let CYCLIC_EDGES_SUBSET_CYCLIC_K4_EDGES = prove
 (`!q:num->A. !n i j k.
        0 < i /\ i < j /\ j < k /\ k < n /\
        INJ q (cyclic_indices n) (:A)
        ==> cyclic_edges q n SUBSET cyclic_k4_edges q n i j k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "i_positive ij jk kn injective" THEN
  TRANS_TAC SUBSET_TRANS
   `indexed_path_edges (q:num->A) i UNION
    indexed_path_edges (cyclic_offset_path q i) (j - i) UNION
    indexed_path_edges (cyclic_offset_path q j) (k - j) UNION
    indexed_path_edges (cyclic_closing_path q k n) (n - k)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC CYCLIC_EDGES_SUBSET_FOUR_INDEXED_PATHS;
    MATCH_MP_TAC FOUR_INDEXED_PATHS_SUBSET_CYCLIC_K4_EDGES] THEN
  ASM_REWRITE_TAC[]);;

let CYCLIC_K4_SUBDIVISION = prove
 (`!q:num->A. !n i j k.
        0 < i /\ i < j /\ j < k /\ k < n /\
        INJ q (cyclic_indices n) (:A)
        ==> graph_subdivision
             {q 0,q i,q j,q k}
             (complete_graph_edges {q 0,q i,q j,q k})
             (cyclic_vertices q n)
             (cyclic_k4_edges q n i j k) /\
            cyclic_edges q n SUBSET cyclic_k4_edges q n i j k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "i_positive ij jk kn injective" THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN
     `cyclic_k4_vertices (q:num->A) n i j k = cyclic_vertices q n`
    (LABEL_TAC "vertices") THENL
     [MATCH_MP_TAC CYCLIC_K4_VERTICES_EQ THEN ASM_REWRITE_TAC[];
      MP_TAC(ISPECL [`q:num->A`; `n:num`; `i:num`; `j:num`; `k:num`]
        CYCLIC_K4_SUBDIVISION_RAW) THEN
      ASM_REWRITE_TAC[]];
    MATCH_MP_TAC CYCLIC_EDGES_SUBSET_CYCLIC_K4_EDGES THEN
    ASM_REWRITE_TAC[]]);;

let INDEXED_PREFIX_EDGES_SUBSET_CYCLIC = prove
 (`!q:num->A. !l n.
        l < n
        ==> indexed_path_edges q l SUBSET cyclic_edges q n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "last_index") THEN
  REWRITE_TAC[SUBSET; IN_INDEXED_PATH_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN
  INTRO_TAC "@h. h_index edge_value" THEN
  USE_THEN "edge_value" SUBST1_TAC THEN
  REWRITE_TAC[IN_CYCLIC_EDGES] THEN
  EXISTS_TAC `h:num` THEN
  CONJ_TAC THENL
   [ASM_ARITH_TAC;
    SUBGOAL_THEN `(h:num) + 1 < n` (LABEL_TAC "successor_index") THENL
     [ASM_ARITH_TAC;
      ASM_SIMP_TAC[MOD_LT]]]);;

let INDEXED_OFFSET_EDGES_SUBSET_CYCLIC = prove
 (`!q:num->A. !a l n.
        a + l < n
        ==> indexed_path_edges (cyclic_offset_path q a) l
            SUBSET cyclic_edges q n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "last_index") THEN
  REWRITE_TAC[SUBSET; IN_INDEXED_PATH_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN
  INTRO_TAC "@h. h_index edge_value" THEN
  USE_THEN "edge_value" SUBST1_TAC THEN
  REWRITE_TAC[IN_CYCLIC_EDGES] THEN
  EXISTS_TAC `a + h:num` THEN
  SUBGOAL_THEN `(a:num) + h + 1 < n`
  (LABEL_TAC "successor_index") THENL
   [ASM_ARITH_TAC;
    CONJ_TAC THENL
     [ASM_ARITH_TAC;
      SUBGOAL_THEN `((a:num) + h + 1) MOD n = a + h + 1`
      (LABEL_TAC "successor") THENL
       [MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[cyclic_offset_path; GSYM ADD_ASSOC] THEN
        USE_THEN "successor" (fun th -> REWRITE_TAC[th])]]]);;

let INDEXED_CLOSING_EDGES_SUBSET_CYCLIC = prove
 (`!q:num->A. !k n.
        k < n
        ==> indexed_path_edges (cyclic_closing_path q k n) (n - k)
            SUBSET cyclic_edges q n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "k_index") THEN
  REWRITE_TAC[SUBSET; IN_INDEXED_PATH_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN
  INTRO_TAC "@h. h_index edge_value" THEN
  USE_THEN "edge_value" SUBST1_TAC THEN
  ASM_CASES_TAC `(h:num) + 1 < n - k` THENL
   [REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `k + h:num` THEN
    SUBGOAL_THEN `(k:num) + h + 1 < n`
    (LABEL_TAC "successor_index") THENL
     [ASM_ARITH_TAC;
      CONJ_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN `((k:num) + h + 1) MOD n = k + h + 1`
        (LABEL_TAC "successor") THENL
         [MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[];
          ASM_REWRITE_TAC[cyclic_closing_path; GSYM ADD_ASSOC] THEN
          USE_THEN "successor" (fun th -> REWRITE_TAC[th])]]];
    SUBGOAL_THEN `(h:num) + 1 = n - k`
    (LABEL_TAC "last_offset") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(k:num) + h = n - 1`
    (LABEL_TAC "last_index") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `n - 1:num` THEN
    CONJ_TAC THENL
     [ASM_ARITH_TAC;
      SUBGOAL_THEN `(n:num) - 1 + 1 = n`
      (LABEL_TAC "successor") THENL
       [ASM_ARITH_TAC;
        ASM_REWRITE_TAC[MOD_REFL; cyclic_closing_path]]]]);;

let COMPLETE_GRAPH_EDGES_FOUR_SUBSET = prove
 (`!a b c d:A.
        complete_graph_edges {a,b,c,d} SUBSET
        {{a,b},{a,c},{a,d},{b,c},{b,d},{c,d}}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[SUBSET; IN_COMPLETE_GRAPH_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN INTRO_TAC "endpoints size" THEN
  USE_THEN "size" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE_CONV `(e:A->bool) HAS_SIZE 2`] THEN
  INTRO_TAC "@u v. distinct edge_value" THEN
  SUBGOAL_THEN `({u:A,v}:A->bool) SUBSET {a,b,c,d}`
  MP_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INSERT; IN_SING] THEN
    X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "x_pair") THEN
    USE_THEN "endpoints" (MP_TAC o SPEC `x:A`) THEN
    ANTS_TAC THENL
     [USE_THEN "edge_value" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN
      USE_THEN "x_pair" ACCEPT_TAC;
      REWRITE_TAC[IN_INSERT; IN_SING]];
    ALL_TAC] THEN
  REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_INSERT; IN_SING] THEN
  INTRO_TAC "u_cases v_cases" THEN
  USE_THEN "edge_value" SUBST1_TAC THEN
  USE_THEN "u_cases" MP_TAC THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  USE_THEN "v_cases" MP_TAC THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  ASM_REWRITE_TAC[IN_INSERT; IN_SING; PAIR_SET_SYM] THEN
  ASM_MESON_TAC[]);;

let CYCLIC_K4_EDGES_SUBSET_CHORDS_UNION_CYCLIC = prove
 (`!q:num->A. !n i j k.
        0 < i /\ i < j /\ j < k /\ k < n
        ==> cyclic_k4_edges q n i j k SUBSET
            {{q 0,q j},{q i,q k}} UNION cyclic_edges q n`,
  REPEAT GEN_TAC THEN INTRO_TAC "i_positive ij jk kn" THEN
  SUBGOAL_THEN
   `indexed_path_edges (q:num->A) i SUBSET cyclic_edges q n`
  (LABEL_TAC "path0") THENL
   [MATCH_MP_TAC INDEXED_PREFIX_EDGES_SUBSET_CYCLIC THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `indexed_path_edges (cyclic_offset_path (q:num->A) i) (j - i)
    SUBSET cyclic_edges q n`
  (LABEL_TAC "path1") THENL
   [MATCH_MP_TAC INDEXED_OFFSET_EDGES_SUBSET_CYCLIC THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `indexed_path_edges (cyclic_offset_path (q:num->A) j) (k - j)
    SUBSET cyclic_edges q n`
  (LABEL_TAC "path2") THENL
   [MATCH_MP_TAC INDEXED_OFFSET_EDGES_SUBSET_CYCLIC THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `indexed_path_edges (cyclic_closing_path (q:num->A) k n) (n - k)
    SUBSET cyclic_edges q n`
  (LABEL_TAC "path3") THENL
   [MATCH_MP_TAC INDEXED_CLOSING_EDGES_SUBSET_CYCLIC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(q:num->A) 0`; `(q:num->A) i`; `(q:num->A) j`; `(q:num->A) k`]
   COMPLETE_GRAPH_EDGES_FOUR_SUBSET) THEN
  DISCH_THEN(LABEL_TAC "complete_edges") THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `e:A->bool` THEN
  REWRITE_TAC[cyclic_k4_edges; four_path_edges;
              IN_UNION; IN_DELETE; IN_INSERT; IN_SING] THEN
  DISCH_THEN(LABEL_TAC "edge") THEN
  USE_THEN "complete_edges"
   (MP_TAC o SPEC `e:A->bool` o REWRITE_RULE[SUBSET]) THEN
  USE_THEN "path0"
   (MP_TAC o SPEC `e:A->bool` o REWRITE_RULE[SUBSET]) THEN
  USE_THEN "path1"
   (MP_TAC o SPEC `e:A->bool` o REWRITE_RULE[SUBSET]) THEN
  USE_THEN "path2"
   (MP_TAC o SPEC `e:A->bool` o REWRITE_RULE[SUBSET]) THEN
  USE_THEN "path3"
   (MP_TAC o SPEC `e:A->bool` o REWRITE_RULE[SUBSET]) THEN
  REWRITE_TAC[IN_INSERT; IN_SING] THEN
  ASM_MESON_TAC[PAIR_SET_SYM]);;

let IMAGE_FST_CYCLIC_DARTS = prove
 (`!q:num->A. !n.
        IMAGE FST (cyclic_darts q n) = cyclic_vertices q n`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[cyclic_darts; cyclic_vertices; GSYM IMAGE_o] THEN
  MATCH_MP_TAC IMAGE_EQ THEN
  REWRITE_TAC[o_THM; FST]);;

(* Euler rotations under suppression of a degree-two subdivision vertex.     *)

let subdivision_tail_swap = new_definition
 `subdivision_tail_swap (u:A) v w =
    swap((u,v),(u,w)) o swap((v,u),(v,w))`;;

let SUBDIVISION_VERTICES_DISTINCT = prove
 (`!V:A->bool. !u v w.
        {u,v} SUBSET V /\ ({u,v}:A->bool) HAS_SIZE 2 /\ ~(w IN V)
        ==> ~(u = v) /\ ~(u = w) /\ ~(v = w)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[INSERT_SUBSET; SING_SUBSET;
              PAIR_HAS_SIZE_2] THEN
  SET_TAC[]);;

let SUBDIVISION_DARTS_DISTINCT = prove
 (`!u v w:A.
        ~(u = v) /\ ~(u = w) /\ ~(v = w)
        ==> ~((u,v) = (u,w)) /\
            ~((u,v) = (v,u)) /\
            ~((u,v) = (v,w)) /\
            ~((u,w) = (v,u)) /\
            ~((u,w) = (v,w)) /\
            ~((v,u) = (v,w))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[PAIR_EQ] THEN MESON_TAC[]);;

let SUBDIVISION_TAIL_SWAP_INVOLUTION = prove
 (`!u v w:A.
        ~(u = v) /\ ~(u = w) /\ ~(v = w)
        ==> subdivision_tail_swap u v w o
            subdivision_tail_swap u v w = I`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "distinct") THEN
  MP_TAC(ISPECL [`u:A`; `v:A`; `w:A`]
    SUBDIVISION_DARTS_DISTINCT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "uv_uw uv_vu uv_vw uw_vu uw_vw vu_vw" THEN
  REWRITE_TAC[subdivision_tail_swap; FUN_EQ_THM; o_THM; I_THM] THEN
  X_GEN_TAC `d:A#A` THEN
  MAP_EVERY ASM_CASES_TAC
   [`d:A#A = (u,v)`; `d:A#A = (u,w)`;
    `d:A#A = (v,u)`; `d:A#A = (v,w)`] THEN
  ASM_REWRITE_TAC[swap]);;

let SUBDIVISION_TAIL_SWAP_INVOLUTION_APPLY = prove
 (`!u v w:A.
        ~(u = v) /\ ~(u = w) /\ ~(v = w)
        ==> !d. subdivision_tail_swap u v w
                 (subdivision_tail_swap u v w d) = d`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "distinct") THEN
  MP_TAC(ISPECL [`u:A`; `v:A`; `w:A`]
    SUBDIVISION_TAIL_SWAP_INVOLUTION) THEN
  ASM_REWRITE_TAC[FUN_EQ_THM; o_THM; I_THM]);;

let SUBDIVISION_TAIL_SWAP_VALUES = prove
 (`!u v w:A.
        ~(u = v) /\ ~(u = w) /\ ~(v = w)
        ==> subdivision_tail_swap u v w (u,v) = (u,w) /\
            subdivision_tail_swap u v w (u,w) = (u,v) /\
            subdivision_tail_swap u v w (v,u) = (v,w) /\
            subdivision_tail_swap u v w (v,w) = (v,u)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "distinct") THEN
  MP_TAC(ISPECL [`u:A`; `v:A`; `w:A`]
    SUBDIVISION_DARTS_DISTINCT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "uv_uw uv_vu uv_vw uw_vu uw_vw vu_vw" THEN
  REWRITE_TAC[subdivision_tail_swap; o_THM] THEN
  ASM_SIMP_TAC[SWAP_LEFT; SWAP_RIGHT; SWAP_OTHER]);;

let SUBDIVISION_TAIL_SWAP_OTHER = prove
 (`!u v w:A. !d:A#A.
        ~(d = (u,v)) /\ ~(d = (u,w)) /\
        ~(d = (v,u)) /\ ~(d = (v,w))
        ==> subdivision_tail_swap u v w d = d`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[subdivision_tail_swap; o_THM] THEN
  INTRO_TAC "not_uv not_uw not_vu not_vw" THEN
  ASM_SIMP_TAC[SWAP_OTHER]);;

let IN_IMAGE_INVOLUTION = prove
 (`!f:A->A. (!x. f(f x) = x)
             ==> !s y. y IN IMAGE f s <=> f y IN s`,
  REWRITE_TAC[IN_IMAGE] THEN MESON_TAC[]);;

let FINITE_SIMPLE_GRAPH_FRESH_NO_EDGE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !w.
        finite_simple_graph V E /\ ~(w IN V)
        ==> !x. ~({w,x} IN E)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[finite_simple_graph] THEN
  INTRO_TAC "((finite_vertices finite_edges edge_data) fresh)" THEN
  X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "edge") THEN
  SUBGOAL_THEN `{w:A,x} SUBSET V` (LABEL_TAC "subset") THENL
   [USE_THEN "edge_data" (fun th ->
      ACCEPT_TAC(CONJUNCT1(MATCH_MP
       (SPEC `{w:A,x}` th)
       (ASSUME `{w:A,x} IN E`))));
    ALL_TAC] THEN
  USE_THEN "subset" MP_TAC THEN
  REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
  ASM_REWRITE_TAC[]);;

let SUBDIVISION_PAIR_SET_EQ = prove
 (`!x y a b:A.
        ~(a = b)
        ==> ({x,y} = {a,b} <=>
             (x = a /\ y = b) \/ (x = b /\ y = a))`,
  SET_TAC[]);;

let IMAGE_SWAP_REPLACE = prove
 (`!s:A->bool. !a b.
        a IN s /\ ~(b IN s)
        ==> IMAGE (swap(a,b)) s = b INSERT (s DELETE a)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[EXTENSION; IN_IMAGE; IN_INSERT; IN_DELETE; swap] THEN
  MESON_TAC[]);;

let SUBDIVISION_TAIL_SWAP_IMAGE = prove
 (`!S:(A#A)->bool. !u v w:A.
        ~(u = v) /\ ~(u = w) /\ ~(v = w) /\
        (u,v) IN S /\ (v,u) IN S /\
        ~((u,w) IN S) /\ ~((v,w) IN S)
        ==> IMAGE (subdivision_tail_swap u v w) S =
            (u,w) INSERT (v,w) INSERT
              (S DELETE (u,v) DELETE (v,u))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "uv uw vw uv_in vu_in uw_out vw_out" THEN
  REWRITE_TAC[subdivision_tail_swap; IMAGE_o] THEN
  MP_TAC(ISPECL
   [`S:(A#A)->bool`; `(v:A,u:A)`; `(v:A,w:A)`]
   IMAGE_SWAP_REPLACE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL
   [`(v:A,w:A) INSERT (S DELETE (v,u))`;
    `(u:A,v:A)`; `(u:A,w:A)`]
   IMAGE_SWAP_REPLACE) THEN
  ASM_REWRITE_TAC[IN_INSERT; IN_DELETE; PAIR_EQ] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_SIMP_TAC[DELETE_INSERT; PAIR_EQ] THEN SET_TAC[]);;

let DOUBLE_DELETE_INSERTS = prove
 (`!S:A->bool. !b d e f.
        ~(b = e) /\ ~(b = f) /\ ~(d = e) /\ ~(d = f) /\
        ~(e = f) /\ ~(e IN S) /\ ~(f IN S)
        ==> (b INSERT e INSERT f INSERT d INSERT S)
              DELETE e DELETE f =
            b INSERT d INSERT S`,
  SET_TAC[]);;

let DOUBLE_DELETE_SUBSET = prove
 (`!S:A->bool. !a b.
        S DELETE a DELETE b SUBSET S`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[SUBSET; IN_DELETE] THEN MESON_TAC[]);;

let GRAPH_DARTS_SUBDIVISION_TAIL_SWAP = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V)
        ==> IMAGE (subdivision_tail_swap u v w) (graph_darts E) =
            graph_darts
              ({{u,w},{w,v}} UNION (E DELETE {u,v}))
            DELETE (w,u) DELETE (w,v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh" THEN
  SUBGOAL_THEN
   `{u:A,v} SUBSET V /\ ({u:A,v}:A->bool) HAS_SIZE 2`
  (CONJUNCTS_THEN2 (LABEL_TAC "endpoints")
    (LABEL_TAC "edge_size")) THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`
  (LABEL_TAC "distinct") THENL
   [MATCH_MP_TAC(ISPECL [`V:A->bool`; `u:A`; `v:A`; `w:A`]
     SUBDIVISION_VERTICES_DISTINCT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x:A. ~({w,x} IN E) /\ ~({x,w} IN E)`
  (LABEL_TAC "fresh_edges") THENL
   [X_GEN_TAC `x:A` THEN
    SUBGOAL_THEN `~({w:A,x} IN E)` (LABEL_TAC "forward") THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `w:A`]
       FINITE_SIMPLE_GRAPH_FRESH_NO_EDGE) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `x:A`) THEN
      REWRITE_TAC[];
      ASM_REWRITE_TAC[SET_RULE `{x:A,w} = {w,x}`]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((u:A),v) IN graph_darts E /\
    ((v:A),u) IN graph_darts E`
  (CONJUNCTS_THEN2 (LABEL_TAC "uv_dart")
    (LABEL_TAC "vu_dart")) THENL
   [ASM_REWRITE_TAC[IN_GRAPH_DARTS;
                    SET_RULE `{v:A,u} = {u,v}`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((u:A),w) IN graph_darts E)`
  (LABEL_TAC "uw_fresh") THENL
   [REWRITE_TAC[IN_GRAPH_DARTS] THEN
    USE_THEN "fresh_edges" (fun th ->
     ACCEPT_TAC
      (REWRITE_RULE[SET_RULE `{w:A,u} = {u,w}`]
        (CONJUNCT1(SPEC `u:A` th))));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((v:A),w) IN graph_darts E)`
  (LABEL_TAC "vw_fresh") THENL
   [REWRITE_TAC[IN_GRAPH_DARTS] THEN
    USE_THEN "fresh_edges" (fun th ->
     ACCEPT_TAC
      (REWRITE_RULE[SET_RULE `{w:A,v} = {v,w}`]
        (CONJUNCT1(SPEC `v:A` th))));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((w:A),u) IN graph_darts E)`
  (LABEL_TAC "wu_fresh") THENL
   [REWRITE_TAC[IN_GRAPH_DARTS] THEN
    USE_THEN "fresh_edges" (fun th ->
     ACCEPT_TAC(CONJUNCT1(SPEC `u:A` th)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(((w:A),v) IN graph_darts E)`
  (LABEL_TAC "wv_fresh") THENL
   [REWRITE_TAC[IN_GRAPH_DARTS] THEN
    USE_THEN "fresh_edges" (fun th ->
     ACCEPT_TAC(CONJUNCT1(SPEC `v:A` th)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (subdivision_tail_swap (u:A) v w) (graph_darts E) =
    (u,w) INSERT (v,w) INSERT
      (graph_darts E DELETE (u,v) DELETE (v,u))`
  (LABEL_TAC "image") THENL
   [MATCH_MP_TAC(ISPECL
     [`graph_darts (E:(A->bool)->bool)`; `u:A`; `v:A`; `w:A`]
     SUBDIVISION_TAIL_SWAP_IMAGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{{u:A,w},{w,v}} UNION (E DELETE {u,v}) =
    {u,w} INSERT ({w,v} INSERT (E DELETE {u,v}))`
  (LABEL_TAC "subdivision_edges") THENL
   [SET_TAC[];
    ALL_TAC] THEN
  USE_THEN "image" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "subdivision_edges" (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[GRAPH_DARTS_INSERT_EDGE; GRAPH_DARTS_DELETE_EDGE] THEN
  USE_THEN "distinct" STRIP_ASSUME_TAC THEN
  CONV_TAC SYM_CONV THEN
  MATCH_MP_TAC(ISPECL
   [`graph_darts (E:(A->bool)->bool) DELETE (u,v) DELETE (v,u)`;
    `(u:A,w:A)`; `(v:A,w:A)`; `(w:A,u:A)`; `(w:A,v:A)`]
   DOUBLE_DELETE_INSERTS) THEN
  ASM_REWRITE_TAC[PAIR_EQ; IN_DELETE]);;

let OUTGOING_DARTS_SUBDIVISION_VERTEX = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V)
        ==> outgoing_darts
              ({{u,w},{w,v}} UNION (E DELETE {u,v})) w =
            {(w,u),(w,v)}`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh" THEN
  SUBGOAL_THEN
   `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`
  STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN
     `{u:A,v} SUBSET V /\ ({u:A,v}:A->bool) HAS_SIZE 2`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC(ISPECL [`V:A->bool`; `u:A`; `v:A`; `w:A`]
       SUBDIVISION_VERTICES_DISTINCT) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `!x:A. ~({w,x} IN E)`
  (LABEL_TAC "fresh_edges") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `w:A`]
     FINITE_SIMPLE_GRAPH_FRESH_NO_EDGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[EXTENSION; FORALL_PAIR_THM;
              IN_OUTGOING_DARTS; IN_GRAPH_DARTS; FST;
              IN_INSERT; IN_SING; IN_UNION; IN_DELETE;
              DART_EDGE_PAIR; PAIR_EQ] THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
  ASM_CASES_TAC `x:A = w` THEN ASM_REWRITE_TAC[] THEN
  ASM_SIMP_TAC[SUBDIVISION_PAIR_SET_EQ] THEN
  USE_THEN "fresh_edges" (MP_TAC o SPEC `y:A`) THEN
  SET_TAC[]);;

let GRAPH_ROTATION_SUBDIVISION_RETAINED_DARTS_INVARIANT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
   !r:(A#A)->A#A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        graph_rotation
          ({{u,w},{w,v}} UNION (E DELETE {u,v})) r
        ==> IMAGE r
              (graph_darts
                ({{u,w},{w,v}} UNION (E DELETE {u,v}))
               DELETE (w,u) DELETE (w,v)) =
            graph_darts
              ({{u,w},{w,v}} UNION (E DELETE {u,v}))
             DELETE (w,u) DELETE (w,v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh rotation" THEN
  ABBREV_TAC
   `D:(A#A)->bool =
      graph_darts ({{u,w},{w,v}} UNION (E DELETE {u,v}))` THEN
  ABBREV_TAC `O:(A#A)->bool = outgoing_darts
    ({{u,w},{w,v}} UNION (E DELETE {u,v})) w` THEN
  SUBGOAL_THEN `O = {(w:A,u:A),(w:A,v:A)}`
  (LABEL_TAC "outgoing") THENL
   [EXPAND_TAC "O" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`]
     OUTGOING_DARTS_SUBDIVISION_VERTEX) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `D DELETE (w:A,u:A) DELETE (w:A,v:A) = D DIFF O`
  (LABEL_TAC "retained") THENL
   [USE_THEN "outgoing" SUBST1_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (r:(A#A)->A#A) D = D`
  (LABEL_TAC "all_invariant") THENL
   [EXPAND_TAC "D" THEN
    USE_THEN "rotation" (fun th ->
     ACCEPT_TAC(MATCH_MP PERMUTES_IMAGE
      (MATCH_MP GRAPH_ROTATION_PERMUTES th)));
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (r:(A#A)->A#A) O = O`
  (LABEL_TAC "outgoing_invariant") THENL
   [EXPAND_TAC "O" THEN
    USE_THEN "rotation" (fun th ->
     ACCEPT_TAC(MATCH_MP
      (ISPECL
       [`{{u:A,w},{w:A,v}} UNION
          (E DELETE {u:A,v}):(A->bool)->bool`;
        `r:(A#A)->A#A`; `w:A`]
       GRAPH_ROTATION_IMAGE_OUTGOING_DARTS)
      th));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x y:A#A. (r:(A#A)->A#A) x = r y ==> x = y`
  (LABEL_TAC "injective") THENL
   [EXPAND_TAC "D" THEN
    USE_THEN "rotation" (fun th ->
     MP_TAC(MATCH_MP PERMUTES_INJECTIVE
      (MATCH_MP GRAPH_ROTATION_PERMUTES th))) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "retained" (fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN
   `IMAGE (r:(A#A)->A#A) (D DIFF O) =
    IMAGE r D DIFF IMAGE r O`
  SUBST1_TAC THENL
   [MATCH_MP_TAC IMAGE_DIFF_INJ THEN ASM_MESON_TAC[];
    ASM_REWRITE_TAC[]]);;

let FST_SWAP_SAME = prove
 (`!a b c:A. !d:A#A.
        FST(swap((a,b),(a,c)) d) = FST d`,
  REPEAT GEN_TAC THEN
  ASM_CASES_TAC `d:A#A = (a,b)` THEN ASM_REWRITE_TAC[swap; FST] THEN
  ASM_CASES_TAC `d:A#A = (a,c)` THEN ASM_REWRITE_TAC[swap; FST]);;

let SUBDIVISION_TAIL_SWAP_FST = prove
 (`!u v w:A. !d:A#A.
        FST(subdivision_tail_swap u v w d) = FST d`,
  REWRITE_TAC[subdivision_tail_swap; o_THM; FST_SWAP_SAME]);;

let ITER_CONJUGATE_INVOLUTION = prove
 (`!p q:A->A.
        (!x. q(q x) = x)
        ==> !n x.
              ITER n (q o p o q) x =
              q(ITER n p (q x))`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "involution") THEN
  INDUCT_TAC THEN X_GEN_TAC `x:A` THEN
  ASM_REWRITE_TAC[ITER; o_THM]);;

let INVOLUTION_CONJUGATE_REACHABLE = prove
 (`!p q:A->A. !x y.
        (!z. q(q z) = z) /\
        (?n. ITER n p (q x) = q y)
        ==> ?n. ITER n (q o p o q) x = y`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "involution (@n. step)" THEN
  EXISTS_TAC `n:num` THEN
  MP_TAC(SPECL [`n:num`; `x:A`]
   (MATCH_MP
    (ISPECL [`p:A->A`; `q:A->A`]
     ITER_CONJUGATE_INVOLUTION)
    (ASSUME `!z:A. (q:A->A) (q z) = z`))) THEN
  ASM_REWRITE_TAC[]);;

let RESTRICTED_PERMUTATION_TRANSITIVE_ON = prove
 (`!f:A->A. !s P.
        IMAGE f s = s /\
        (!x y. x IN s /\ y IN s /\ P x y
               ==> ?n. ITER n f x = y)
        ==> !x y.
              x IN s /\ y IN s /\ P x y
              ==> ?n. ITER n (restricted_permutation f s) x = y`,
  REPEAT GEN_TAC THEN INTRO_TAC "invariant transitive" THEN
  REPEAT GEN_TAC THEN INTRO_TAC "x_member y_member related" THEN
  SUBGOAL_THEN `?n. ITER n (f:A->A) x = y`
  (X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THENL
   [USE_THEN "transitive"
     (MATCH_MP_TAC o SPECL [`x:A`; `y:A`]) THEN
    ASM_REWRITE_TAC[];
    EXISTS_TAC `n:num` THEN
    MP_TAC(SPEC `n:num`
     (MATCH_MP
      (ISPECL [`f:A->A`; `s:A->bool`; `x:A`]
       RESTRICTED_PERMUTATION_ITER)
      (CONJ (ASSUME `(x:A) IN s`)
            (ASSUME `IMAGE (f:A->A) s = s`)))) THEN
    ASM_MESON_TAC[]]);;

let GRAPH_ROTATION_RESTRICTED_TRANSITIVE = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !R:(A#A)->bool.
        graph_rotation E r /\
        R SUBSET graph_darts E /\
        IMAGE r R = R
        ==> !x y.
              x IN R /\ y IN R /\ FST x = FST y
              ==> ?n. ITER n (restricted_permutation r R) x = y`,
  REPEAT GEN_TAC THEN INTRO_TAC "rotation subset invariant" THEN
  MATCH_MP_TAC RESTRICTED_PERMUTATION_TRANSITIVE_ON THEN
  CONJ_TAC THENL
   [USE_THEN "invariant" ACCEPT_TAC;
    ALL_TAC] THEN
  X_GEN_TAC `x:A#A` THEN X_GEN_TAC `y:A#A` THEN
  INTRO_TAC "x_member y_member same_tail" THEN
  USE_THEN "rotation" (fun th ->
   MATCH_MP_TAC(CONJUNCT2(CONJUNCT2
    (REWRITE_RULE[graph_rotation] th)))) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC
     (REWRITE_RULE[SUBSET]
      (ASSUME `(R:(A#A)->bool) SUBSET graph_darts E`)) THEN
    USE_THEN "x_member" ACCEPT_TAC;
    MATCH_MP_TAC
     (REWRITE_RULE[SUBSET]
      (ASSUME `(R:(A#A)->bool) SUBSET graph_darts E`)) THEN
    USE_THEN "y_member" ACCEPT_TAC;
    USE_THEN "same_tail" ACCEPT_TAC]);;

let GRAPH_ROTATION_RESTRICTED_TAIL = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !R:(A#A)->bool.
        graph_rotation E r /\
        R SUBSET graph_darts E
        ==> !d. d IN R
                ==> FST(restricted_permutation r R d) = FST d`,
  REPEAT GEN_TAC THEN INTRO_TAC "rotation subset" THEN
  X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "d_member") THEN
  REWRITE_TAC[restricted_permutation] THEN
  USE_THEN "d_member" (fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN `(d:A#A) IN graph_darts E`
  (LABEL_TAC "d_dart") THENL
   [MATCH_MP_TAC
     (REWRITE_RULE[SUBSET]
      (ASSUME `(R:(A#A)->bool) SUBSET graph_darts E`)) THEN
    USE_THEN "d_member" ACCEPT_TAC;
    USE_THEN "rotation" (fun rth ->
     USE_THEN "d_dart" (fun dth ->
      ACCEPT_TAC(MATCH_MP
       (SPECL
        [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
        GRAPH_ROTATION_TAIL)
       (CONJ rth dth))))]);;

let CONJUGATE_FST_PRESERVES = prove
 (`!q:(A#A)->A#A. !p D R.
        (!d. FST(q d) = FST d) /\
        (!d. d IN D ==> q d IN R) /\
        (!d. d IN R ==> FST(p d) = FST d)
        ==> !d. d IN D ==> FST((q o p o q) d) = FST d`,
  REPEAT GEN_TAC THEN INTRO_TAC "q_fst forward p_fst" THEN
  X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "d_member") THEN
  REWRITE_TAC[o_THM] THEN
  TRANS_TAC EQ_TRANS
   `FST((p:(A#A)->A#A) ((q:(A#A)->A#A) d))` THEN
  CONJ_TAC THENL
   [USE_THEN "q_fst" (fun th ->
     ACCEPT_TAC(SPEC
      `(p:(A#A)->A#A) ((q:(A#A)->A#A) d)` th));
    TRANS_TAC EQ_TRANS `FST((q:(A#A)->A#A) d)` THEN
    CONJ_TAC THENL
     [USE_THEN "p_fst" MATCH_MP_TAC THEN
      USE_THEN "forward" MATCH_MP_TAC THEN
      USE_THEN "d_member" ACCEPT_TAC;
      USE_THEN "q_fst" (fun th ->
       ACCEPT_TAC(SPEC `d:A#A` th))]]);;

let INVOLUTION_CONJUGATE_FST_TRANSITIVE = prove
 (`!q:(A#A)->A#A. !p D R.
        (!x. q(q x) = x) /\
        (!x. FST(q x) = FST x) /\
        (!x. x IN D ==> q x IN R) /\
        (!x y. x IN R /\ y IN R /\ FST x = FST y
               ==> ?n. ITER n p x = y)
        ==> !x y.
              x IN D /\ y IN D /\ FST x = FST y
              ==> ?n. ITER n (q o p o q) x = y`,
  REPEAT GEN_TAC THEN INTRO_TAC "involution fst forward transitive" THEN
  REPEAT GEN_TAC THEN INTRO_TAC "x_member y_member same_tail" THEN
  MATCH_MP_TAC INVOLUTION_CONJUGATE_REACHABLE THEN
  CONJ_TAC THENL
   [USE_THEN "involution" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "transitive" MATCH_MP_TAC THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "forward" MATCH_MP_TAC THEN
    USE_THEN "x_member" ACCEPT_TAC;
    USE_THEN "forward" MATCH_MP_TAC THEN
    USE_THEN "y_member" ACCEPT_TAC;
    USE_THEN "fst" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "same_tail" ACCEPT_TAC]);;

let graph_suppress_subdivision_rotation = new_definition
 `graph_suppress_subdivision_rotation
    (E:(A->bool)->bool) u v w (r:(A#A)->A#A) =
      subdivision_tail_swap u v w o
      restricted_permutation r
        (graph_darts
          ({{u,w},{w,v}} UNION (E DELETE {u,v}))
         DELETE (w,u) DELETE (w,v)) o
      subdivision_tail_swap u v w`;;

let GRAPH_ROTATION_SUPPRESS_SETUP_TAC =
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh rotation" THEN
  REWRITE_TAC[graph_suppress_subdivision_rotation] THEN
  ABBREV_TAC `D:(A#A)->bool = graph_darts E` THEN
  ABBREV_TAC
   `D':(A#A)->bool =
      graph_darts ({{u,w},{w,v}} UNION (E DELETE {u,v}))` THEN
  ABBREV_TAC
   `R:(A#A)->bool = D' DELETE (w,u) DELETE (w,v)` THEN
  ABBREV_TAC `q:(A#A)->A#A = subdivision_tail_swap u v w` THEN
  ABBREV_TAC `p:(A#A)->A#A = restricted_permutation r R` THEN
  SUBGOAL_THEN
   `R = D' DELETE (w:A,u:A) DELETE (w:A,v:A)`
  (LABEL_TAC "retained_definition") THENL
   [EXPAND_TAC "R" THEN REFL_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(R:(A#A)->bool) SUBSET D'`
  (LABEL_TAC "retained_subset") THENL
   [USE_THEN "retained_definition" (fun th -> REWRITE_TAC[th]) THEN
    ACCEPT_TAC(ISPECL
     [`D':(A#A)->bool`; `(w:A,u:A)`; `(w:A,v:A)`]
     DOUBLE_DELETE_SUBSET);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`
  (LABEL_TAC "distinct") THENL
   [SUBGOAL_THEN
     `{u:A,v} SUBSET V /\ ({u:A,v}:A->bool) HAS_SIZE 2`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC(ISPECL [`V:A->bool`; `u:A`; `v:A`; `w:A`]
       SUBDIVISION_VERTICES_DISTINCT) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `!d:A#A. (q:(A#A)->A#A) (q d) = d`
  (LABEL_TAC "involution") THENL
   [EXPAND_TAC "q" THEN
    MATCH_MP_TAC(ISPECL [`u:A`; `v:A`; `w:A`]
     SUBDIVISION_TAIL_SWAP_INVOLUTION_APPLY) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!d:A#A. FST((q:(A#A)->A#A) d) = FST d`
  (LABEL_TAC "q_fst") THENL
   [EXPAND_TAC "q" THEN
    REWRITE_TAC[SUBDIVISION_TAIL_SWAP_FST];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (q:(A#A)->A#A) D = R`
  (LABEL_TAC "image") THENL
   [EXPAND_TAC "q" THEN EXPAND_TAC "D" THEN
    USE_THEN "retained_definition" (fun th -> REWRITE_TAC[th]) THEN
    EXPAND_TAC "D'" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`]
     GRAPH_DARTS_SUBDIVISION_TAIL_SWAP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(D:(A#A)->bool)` (LABEL_TAC "finite_darts") THENL
   [EXPAND_TAC "D" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(R:(A#A)->bool)` (LABEL_TAC "finite_retained") THENL
   [USE_THEN "image" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC FINITE_IMAGE THEN
    USE_THEN "finite_darts" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (r:(A#A)->A#A) R = R`
  (LABEL_TAC "retained_invariant") THENL
   [USE_THEN "retained_definition" (fun th -> REWRITE_TAC[th]) THEN
    EXPAND_TAC "D'" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`]
     GRAPH_ROTATION_SUBDIVISION_RETAINED_DARTS_INVARIANT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC];;

let GRAPH_ROTATION_SUPPRESS_TRANSPORT_TAC =
  SUBGOAL_THEN `(p:(A#A)->A#A) permutes R`
  (LABEL_TAC "restricted_permutation") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC(ISPECL
     [`r:(A#A)->A#A`; `D':(A#A)->bool`; `R:(A#A)->bool`]
     RESTRICTED_PERMUTATION_PERMUTES) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "finite_retained" ACCEPT_TAC;
      USE_THEN "retained_subset" ACCEPT_TAC;
      EXPAND_TAC "D'" THEN
      MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
      USE_THEN "rotation" ACCEPT_TAC;
      USE_THEN "retained_invariant" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!d:A#A. d IN R
              ==> FST((p:(A#A)->A#A) d) = FST d`
  (LABEL_TAC "p_fst") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC(ISPECL
     [`{{u:A,w},{w,v}} UNION
       (E DELETE {u,v}):(A->bool)->bool`;
      `r:(A#A)->A#A`; `R:(A#A)->bool`]
     GRAPH_ROTATION_RESTRICTED_TAIL) THEN
    CONJ_TAC THENL
     [USE_THEN "rotation" ACCEPT_TAC;
      USE_THEN "retained_subset" MP_TAC THEN
      EXPAND_TAC "D'" THEN SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x y:A#A.
        x IN R /\ y IN R /\ FST x = FST y
        ==> ?n. ITER n (p:(A#A)->A#A) x = y`
  (LABEL_TAC "p_transitive") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC(ISPECL
     [`{{u:A,w},{w,v}} UNION
       (E DELETE {u,v}):(A->bool)->bool`;
      `r:(A#A)->A#A`; `R:(A#A)->bool`]
     GRAPH_ROTATION_RESTRICTED_TRANSITIVE) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "rotation" ACCEPT_TAC;
      USE_THEN "retained_subset" MP_TAC THEN
      EXPAND_TAC "D'" THEN SIMP_TAC[];
      USE_THEN "retained_invariant" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!d:A#A. d IN D ==> (q:(A#A)->A#A) d IN R`
  (LABEL_TAC "forward") THENL
   [X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "d_member") THEN
    USE_THEN "image" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[IN_IMAGE] THEN
    EXISTS_TAC `d:A#A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!d:A#A. d IN R ==> (q:(A#A)->A#A) d IN D`
  (LABEL_TAC "backward") THENL
   [X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "d_member") THEN
    SUBGOAL_THEN `d IN IMAGE (q:(A#A)->A#A) D`
    (LABEL_TAC "image_member") THENL
     [USE_THEN "image" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "d_member" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "image_member" MP_TAC THEN
    REWRITE_TAC[IN_IMAGE] THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A#A`
     (CONJUNCTS_THEN2 (LABEL_TAC "representation")
      (LABEL_TAC "x_member"))) THEN
    USE_THEN "representation" SUBST1_TAC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!d:A#A. d IN D
              ==> FST((q o p o q:(A#A)->A#A) d) = FST d`
  (LABEL_TAC "suppressed_tail") THENL
   [MATCH_MP_TAC(ISPECL
     [`q:(A#A)->A#A`; `p:(A#A)->A#A`;
      `D:(A#A)->bool`; `R:(A#A)->bool`]
     CONJUGATE_FST_PRESERVES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(q o p o q:(A#A)->A#A) permutes D`
  (LABEL_TAC "suppressed_permutation") THENL
   [MP_TAC(ISPECL
     [`q:(A#A)->A#A`; `q:(A#A)->A#A`;
      `p:(A#A)->A#A`; `D:(A#A)->bool`; `R:(A#A)->bool`]
     PERMUTES_TRANSFER_BIJECTIONS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x y:A#A.
        x IN D /\ y IN D /\ FST x = FST y
        ==> ?n. ITER n (q o p o q) x = y`
  (LABEL_TAC "suppressed_transitive") THENL
   [MATCH_MP_TAC(ISPECL
     [`q:(A#A)->A#A`; `p:(A#A)->A#A`;
      `D:(A#A)->bool`; `R:(A#A)->bool`]
     INVOLUTION_CONJUGATE_FST_TRANSITIVE) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "involution" ACCEPT_TAC;
      USE_THEN "q_fst" ACCEPT_TAC;
      USE_THEN "forward" ACCEPT_TAC;
      USE_THEN "p_transitive" ACCEPT_TAC];
    ALL_TAC];;

let GRAPH_ROTATION_SUPPRESS_PERMUTATION_TAC =
  USE_THEN "suppressed_permutation" MP_TAC THEN
  EXPAND_TAC "D" THEN SIMP_TAC[];;

let GRAPH_ROTATION_SUPPRESS_TAIL_TAC =
  USE_THEN "suppressed_tail" MP_TAC THEN
  EXPAND_TAC "D" THEN SIMP_TAC[];;

let GRAPH_ROTATION_SUPPRESS_TRANSITIVE_TAC =
  USE_THEN "suppressed_transitive" MP_TAC THEN
  EXPAND_TAC "D" THEN SIMP_TAC[];;

let GRAPH_ROTATION_SUPPRESS_FINISH_TAC =
  REWRITE_TAC[graph_rotation] THEN
  CONJ_TAC THENL
   [GRAPH_ROTATION_SUPPRESS_PERMUTATION_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [GRAPH_ROTATION_SUPPRESS_TAIL_TAC;
    GRAPH_ROTATION_SUPPRESS_TRANSITIVE_TAC];;

let GRAPH_ROTATION_SUPPRESS_SUBDIVISION = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
   !r:(A#A)->A#A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        graph_rotation
          ({{u,w},{w,v}} UNION (E DELETE {u,v})) r
        ==> graph_rotation E
             (graph_suppress_subdivision_rotation E u v w r)`,
  GRAPH_ROTATION_SUPPRESS_SETUP_TAC THEN
  GRAPH_ROTATION_SUPPRESS_TRANSPORT_TAC THEN
  GRAPH_ROTATION_SUPPRESS_FINISH_TAC);;

let INVOLUTION_IMAGE_CONJUGATE_PERMUTATION_ORBIT = prove
 (`!p q:A->A.
        (!z. q(q z) = z)
        ==> !x. IMAGE q (permutation_orbit p x) =
                permutation_orbit (q o p o q) (q x)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "involution") THEN
  X_GEN_TAC `x:A` THEN
  REWRITE_TAC[EXTENSION; IN_IMAGE; IN_PERMUTATION_ORBIT] THEN
  X_GEN_TAC `y:A` THEN EQ_TAC THENL
   [INTRO_TAC "@z. image (@n. step)" THEN
    EXISTS_TAC `n:num` THEN
    MP_TAC(SPECL [`n:num`; `(q:A->A) x`]
     (MATCH_MP
      (ISPECL [`p:A->A`; `q:A->A`]
       ITER_CONJUGATE_INVOLUTION)
      (ASSUME `!z:A. (q:A->A) (q z) = z`))) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THEN
    EXISTS_TAC `ITER n (p:A->A) x` THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`n:num`; `(q:A->A) x`]
       (MATCH_MP
        (ISPECL [`p:A->A`; `q:A->A`]
         ITER_CONJUGATE_INVOLUTION)
        (ASSUME `!z:A. (q:A->A) (q z) = z`))) THEN
      ASM_REWRITE_TAC[];
      EXISTS_TAC `n:num` THEN REFL_TAC]]);;

let INVOLUTION_IMAGE_CONJUGATE_PERMUTATION_ORBITS = prove
 (`!p q:A->A. !s t.
        (!z. q(q z) = z) /\ IMAGE q s = t
        ==> IMAGE (IMAGE q) (permutation_orbits p s) =
            permutation_orbits (q o p o q) t`,
  REPEAT GEN_TAC THEN INTRO_TAC "involution sets" THEN
  USE_THEN "sets" (SUBST1_TAC o SYM) THEN
  REWRITE_TAC[permutation_orbits; GSYM IMAGE_o] THEN
  MATCH_MP_TAC(ISPECL
   [`IMAGE (q:A->A) o permutation_orbit (p:A->A)`;
    `permutation_orbit ((q:A->A) o p o q) o q`;
    `s:A->bool`] IMAGE_EQ) THEN
  X_GEN_TAC `x:A` THEN DISCH_TAC THEN REWRITE_TAC[o_THM] THEN
  USE_THEN "involution" (fun th ->
   MATCH_ACCEPT_TAC(SPEC `x:A`
    (MATCH_MP
     (ISPECL [`p:A->A`; `q:A->A`]
      INVOLUTION_IMAGE_CONJUGATE_PERMUTATION_ORBIT)
     th))));;

let CARD_INVOLUTION_CONJUGATE_PERMUTATION_ORBITS = prove
 (`!p q:A->A. !s t.
        FINITE s /\
        (!z. q(q z) = z) /\
        IMAGE q s = t
        ==> CARD(permutation_orbits p s) =
            CARD(permutation_orbits (q o p o q) t)`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite involution sets" THEN
  SUBGOAL_THEN
   `IMAGE (IMAGE (q:A->A)) (permutation_orbits (p:A->A) s) =
    permutation_orbits (q o p o q) t`
  (LABEL_TAC "orbit_image") THENL
   [MATCH_MP_TAC(ISPECL
     [`p:A->A`; `q:A->A`; `s:A->bool`; `t:A->bool`]
     INVOLUTION_IMAGE_CONJUGATE_PERMUTATION_ORBITS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "orbit_image" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
  CONV_TAC SYM_CONV THEN MATCH_MP_TAC CARD_IMAGE_INJ THEN
  CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`a:A->bool`; `b:A->bool`] THEN
    INTRO_TAC "a_orbit b_orbit same_image" THEN
    USE_THEN "involution" (fun th ->
     MATCH_MP_TAC(SPECL [`a:A->bool`; `b:A->bool`]
      (MATCH_MP
       (SPEC `q:A->A` INVOLUTION_IMAGE_INJECTIVE)
       th))) THEN
    USE_THEN "same_image" ACCEPT_TAC;
    MATCH_MP_TAC FINITE_PERMUTATION_ORBITS THEN
    USE_THEN "finite" ACCEPT_TAC]);;

let TWO_POINT_TRANSITIVE_VALUES = prove
 (`!f:A->A. !x y.
        ~(x = y) /\
        f x IN {x,y} /\ f y IN {x,y} /\
        (?n. ITER n f x = y) /\ (?n. ITER n f y = x)
        ==> f x = y /\ f y = x`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[ITER_FIXPOINT]);;

let GRAPH_ROTATION_SUBDIVISION_VERTEX_VALUES = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
   !r:(A#A)->A#A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        graph_rotation
          ({{u,w},{w,v}} UNION (E DELETE {u,v})) r
        ==> r(w,u) = (w,v) /\ r(w,v) = (w,u)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh rotation" THEN
  ABBREV_TAC
   `S:(A->bool)->bool =
      {{u,w},{w,v}} UNION (E DELETE {u,v})` THEN
  SUBGOAL_THEN
   `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`
  (LABEL_TAC "distinct") THENL
   [SUBGOAL_THEN
     `{u:A,v} SUBSET V /\ ({u:A,v}:A->bool) HAS_SIZE 2`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC(ISPECL [`V:A->bool`; `u:A`; `v:A`; `w:A`]
       SUBDIVISION_VERTICES_DISTINCT) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `outgoing_darts S w = {((w:A),(u:A)),(w:A,v:A)}`
  (LABEL_TAC "outgoing") THENL
   [EXPAND_TAC "S" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`]
     OUTGOING_DARTS_SUBDIVISION_VERTEX) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w:A,u) IN outgoing_darts S w /\
    (w:A,v) IN outgoing_darts S w`
  (CONJUNCTS_THEN2 (LABEL_TAC "wu_outgoing")
    (LABEL_TAC "wv_outgoing")) THENL
   [USE_THEN "outgoing" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w:A,u) IN graph_darts S /\ (w:A,v) IN graph_darts S`
  (CONJUNCTS_THEN2 (LABEL_TAC "wu_dart") (LABEL_TAC "wv_dart")) THENL
   [ASM_MESON_TAC[IN_OUTGOING_DARTS];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`r:(A#A)->A#A`; `(w:A,u:A)`; `(w:A,v:A)`]
   TWO_POINT_TRANSITIVE_VALUES) THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[PAIR_EQ];
    USE_THEN "outgoing" (fun th -> REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN
    ASM_MESON_TAC[GRAPH_ROTATION_IN; GRAPH_ROTATION_TAIL; FST];
    USE_THEN "outgoing" (fun th -> REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN
    ASM_MESON_TAC[GRAPH_ROTATION_IN; GRAPH_ROTATION_TAIL; FST];
    MP_TAC(ISPECL
     [`S:(A->bool)->bool`; `r:(A#A)->A#A`;
      `(w:A,u:A)`; `(w:A,v:A)`]
     GRAPH_ROTATION_ORBIT) THEN
    ASM_REWRITE_TAC[FST];
    MP_TAC(ISPECL
     [`S:(A->bool)->bool`; `r:(A#A)->A#A`;
      `(w:A,v:A)`; `(w:A,u:A)`]
     GRAPH_ROTATION_ORBIT) THEN
    ASM_REWRITE_TAC[FST]]);;

let GRAPH_FACE_SUCCESSOR_SUBDIVISION_VALUES = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
   !r:(A#A)->A#A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        graph_rotation
          ({{u,w},{w,v}} UNION (E DELETE {u,v})) r
        ==> graph_face_successor
             ({{u,w},{w,v}} UNION (E DELETE {u,v})) r (u,w) =
            (w,v) /\
            graph_face_successor
             ({{u,w},{w,v}} UNION (E DELETE {u,v})) r (v,w) =
            (w,u) /\
            graph_face_successor
             ({{u,w},{w,v}} UNION (E DELETE {u,v})) r (w,u) =
            r(u,w) /\
            graph_face_successor
             ({{u,w},{w,v}} UNION (E DELETE {u,v})) r (w,v) =
            r(v,w)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh rotation" THEN
  ABBREV_TAC
   `S:(A->bool)->bool =
      {{u,w},{w,v}} UNION (E DELETE {u,v})` THEN
  SUBGOAL_THEN
   `(u:A,w) IN graph_darts S /\ (w:A,u) IN graph_darts S /\
    (v:A,w) IN graph_darts S /\ (w:A,v) IN graph_darts S`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "S" THEN
    REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR;
                IN_UNION; IN_INSERT; IN_SING] THEN
    SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`]
   GRAPH_ROTATION_SUBDIVISION_VERTEX_VALUES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "wu_value wv_value" THEN
  EXPAND_TAC "S" THEN
  ASM_SIMP_TAC[GRAPH_FACE_SUCCESSOR_IN; REVERSE_DART_PAIR]);;

let PERMUTATION_DELETE_TWO_KNOWN_PREDECESSORS = prove
 (`!f:A->A. !s x y a b.
        f permutes s /\
        x IN s /\ y IN s /\ ~(x = y) /\
        a IN s DELETE x DELETE y /\
        b IN s DELETE x DELETE y /\
        f a = y /\ f b = x
        ==> !z. z IN s DELETE x DELETE y
                ==> permutation_delete_two f x y z =
                    if z = a then f y
                    else if z = b then f x
                    else f z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "permutation x_member y_member distinct
    a_member b_member fa fb" THEN
  SUBGOAL_THEN
   `permutation_delete (f:A->A) x permutes (s DELETE x)`
  (LABEL_TAC "deleted_permutation") THENL
   [MATCH_MP_TAC PERMUTATION_DELETE_PERMUTES THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((f:A->A) y = x)` (LABEL_TAC "fy_not_x") THENL
   [MP_TAC(MATCH_MP
     (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
     (ASSUME `(f:A->A) permutes s`)) THEN
    USE_THEN "b_member" MP_TAC THEN
    REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((f:A->A) x = y)` (LABEL_TAC "fx_not_y") THENL
   [MP_TAC(MATCH_MP
     (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
     (ASSUME `(f:A->A) permutes s`)) THEN
    USE_THEN "a_member" MP_TAC THEN
    REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_delete (f:A->A) x y = f y`
  (LABEL_TAC "deleted_y") THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`; `y:A`]
     PERMUTATION_DELETE_APPLY_IN) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN s DELETE x DELETE y
           ==> permutation_delete (f:A->A) x z =
               if f z = x then f x else f z`
  (LABEL_TAC "deleted_value") THENL
   [X_GEN_TAC `z:A` THEN REWRITE_TAC[IN_DELETE] THEN
    INTRO_TAC "(z_member z_not_x) z_not_y" THEN
    MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `x:A`; `z:A`]
     PERMUTATION_DELETE_APPLY_IN) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_member") THEN
  REWRITE_TAC[permutation_delete_two] THEN
  MP_TAC(ISPECL
   [`permutation_delete (f:A->A) x`; `(s:A->bool) DELETE x`;
    `y:A`; `z:A`]
   PERMUTATION_DELETE_APPLY_IN) THEN
  ANTS_TAC THENL
   [USE_THEN "z_member" MP_TAC THEN
    REWRITE_TAC[IN_DELETE] THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
    DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
  USE_THEN "deleted_value" (fun th ->
   REWRITE_TAC[MATCH_MP (SPEC `z:A` th)
    (ASSUME `(z:A) IN s DELETE x DELETE y`)]) THEN
  USE_THEN "deleted_y" (fun th -> REWRITE_TAC[th]) THEN
  ASM_CASES_TAC `z:A = a` THENL
   [ASM_REWRITE_TAC[];
    ASM_CASES_TAC `z:A = b` THENL
     [ASM_REWRITE_TAC[];
      SUBGOAL_THEN
       `~((f:A->A) z = x) /\ ~(f z = y)`
      STRIP_ASSUME_TAC THENL
       [MP_TAC(MATCH_MP
         (ISPECL [`f:A->A`; `s:A->bool`] PERMUTES_INJECTIVE)
         (ASSUME `(f:A->A) permutes s`)) THEN
        USE_THEN "z_member" MP_TAC THEN
        USE_THEN "a_member" MP_TAC THEN
        USE_THEN "b_member" MP_TAC THEN
        REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[];
        ASM_REWRITE_TAC[]]]]);;

let GRAPH_FACE_SUCCESSOR_SUPPRESS_CONJUGATE_FORMULA = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
   !r:(A#A)->A#A. !z:A#A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        z IN graph_darts
              ({{u,w},{w,v}} UNION (E DELETE {u,v}))
             DELETE (w,u) DELETE (w,v)
        ==> (subdivision_tail_swap u v w o
             graph_face_successor E
              (graph_suppress_subdivision_rotation E u v w r) o
             subdivision_tail_swap u v w) z =
            restricted_permutation r
             (graph_darts
               ({{u,w},{w,v}} UNION (E DELETE {u,v}))
              DELETE (w,u) DELETE (w,v))
             (subdivision_tail_swap u v w
               (reverse_dart(subdivision_tail_swap u v w z)))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh retained" THEN
  ABBREV_TAC `q:(A#A)->A#A = subdivision_tail_swap u v w` THEN
  ABBREV_TAC `D:(A#A)->bool = graph_darts E` THEN
  ABBREV_TAC
   `R:(A#A)->bool =
      graph_darts ({{u,w},{w,v}} UNION (E DELETE {u,v}))
      DELETE (w,u) DELETE (w,v)` THEN
  SUBGOAL_THEN
   `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`
  (LABEL_TAC "distinct") THENL
   [SUBGOAL_THEN
     `{u:A,v} SUBSET V /\ ({u:A,v}:A->bool) HAS_SIZE 2`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC(ISPECL [`V:A->bool`; `u:A`; `v:A`; `w:A`]
       SUBDIVISION_VERTICES_DISTINCT) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `!d:A#A. (q:(A#A)->A#A) (q d) = d`
  (LABEL_TAC "involution") THENL
   [EXPAND_TAC "q" THEN
    MATCH_MP_TAC(ISPECL [`u:A`; `v:A`; `w:A`]
     SUBDIVISION_TAIL_SWAP_INVOLUTION_APPLY) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `IMAGE (q:(A#A)->A#A) D = R`
  (LABEL_TAC "image") THENL
   [EXPAND_TAC "q" THEN EXPAND_TAC "D" THEN EXPAND_TAC "R" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`]
     GRAPH_DARTS_SUBDIVISION_TAIL_SWAP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:(A#A)->A#A) z IN D`
  (LABEL_TAC "qz_dart") THENL
   [MP_TAC(SPECL [`D:(A#A)->bool`; `z:A#A`]
     (MATCH_MP
      (ISPEC `q:(A#A)->A#A` IN_IMAGE_INVOLUTION)
      (ASSUME `!d:A#A. (q:(A#A)->A#A) (q d) = d`))) THEN
    USE_THEN "image" (fun th -> REWRITE_TAC[th]) THEN
    EXPAND_TAC "R" THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  EXPAND_TAC "q" THEN EXPAND_TAC "D" THEN EXPAND_TAC "R" THEN
  ASM_SIMP_TAC[graph_face_successor;
               graph_suppress_subdivision_rotation; o_THM;
               GRAPH_REVERSE_DART_IN]);;

let GRAPH_DARTS_SUBDIVISION_NO_OLD_EDGE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
        finite_simple_graph V E /\ {u,v} IN E /\ ~(w IN V)
        ==> ~((u,v) IN graph_darts
                ({{u,w},{w,v}} UNION (E DELETE {u,v}))) /\
            ~((v,u) IN graph_darts
                ({{u,w},{w,v}} UNION (E DELETE {u,v})))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh" THEN
  SUBGOAL_THEN
   `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`
  STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN
     `{u:A,v} SUBSET V /\ ({u:A,v}:A->bool) HAS_SIZE 2`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC(ISPECL [`V:A->bool`; `u:A`; `v:A`; `w:A`]
       SUBDIVISION_VERTICES_DISTINCT) THEN
      ASM_REWRITE_TAC[]];
    REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR;
                IN_UNION; IN_INSERT; IN_SING; IN_DELETE] THEN
    ASM SET_TAC[]]);;

let GRAPH_DARTS_SUBDIVISION_RETAINED_ENDPOINTS = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
        finite_simple_graph V E /\ {u,v} IN E /\ ~(w IN V)
        ==> (u,w) IN
             graph_darts ({{u,w},{w,v}} UNION (E DELETE {u,v}))
             DELETE (w,u) DELETE (w,v) /\
            (v,w) IN
             graph_darts ({{u,w},{w,v}} UNION (E DELETE {u,v}))
             DELETE (w,u) DELETE (w,v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh" THEN
  SUBGOAL_THEN
   `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`
  (LABEL_TAC "distinct") THENL
   [SUBGOAL_THEN
     `{u:A,v} SUBSET V /\ ({u:A,v}:A->bool) HAS_SIZE 2`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC(ISPECL [`V:A->bool`; `u:A`; `v:A`; `w:A`]
       SUBDIVISION_VERTICES_DISTINCT) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (subdivision_tail_swap (u:A) v w)
      (graph_darts (E:(A->bool)->bool)) =
    graph_darts ({{u:A,w},{w,v}} UNION (E DELETE {u,v}))
    DELETE (w,u) DELETE (w,v)`
  (LABEL_TAC "image") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`]
     GRAPH_DARTS_SUBDIVISION_TAIL_SWAP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (ISPECL [`u:A`; `v:A`; `w:A`]
    SUBDIVISION_TAIL_SWAP_VALUES)
   (ASSUME `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`)) THEN
  INTRO_TAC "quv quw qvu qvw" THEN
  CONJ_TAC THENL
   [USE_THEN "image" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `(u:A,v:A)` THEN
    CONJ_TAC THENL
     [USE_THEN "quv" (ACCEPT_TAC o SYM);
      REWRITE_TAC[IN_GRAPH_DARTS] THEN USE_THEN "edge" ACCEPT_TAC];
    USE_THEN "image" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `(v:A,u:A)` THEN
    CONJ_TAC THENL
     [USE_THEN "qvu" (ACCEPT_TAC o SYM);
      REWRITE_TAC[IN_GRAPH_DARTS] THEN
      SUBGOAL_THEN `{v:A,u} = {u,v}` SUBST1_TAC THENL
       [SET_TAC[];
        USE_THEN "edge" ACCEPT_TAC]]]);;

let REVERSE_DART_AVOIDS_SUBDIVISION_PAIRS = prove
 (`!u v w:A. !z:A#A.
        ~(z = (v,u)) /\ ~(z = (w,u)) /\
        ~(z = (u,v)) /\ ~(z = (w,v))
        ==> ~(reverse_dart z = (u,v)) /\
            ~(reverse_dart z = (u,w)) /\
            ~(reverse_dart z = (v,u)) /\
            ~(reverse_dart z = (v,w))`,
  REWRITE_TAC[FORALL_PAIR_THM; REVERSE_DART_PAIR; PAIR_EQ] THEN
  MESON_TAC[]);;

let SUBDIVISION_TAIL_SWAP_REVERSE_RETAINED = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w z:A#A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        z IN graph_darts
              ({{u,w},{w,v}} UNION (E DELETE {u,v}))
             DELETE (w,u) DELETE (w,v)
        ==> subdivision_tail_swap u v w
             (reverse_dart(subdivision_tail_swap u v w z)) =
            if z = (u,w) then (v,w)
            else if z = (v,w) then (u,w)
            else reverse_dart z`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh retained" THEN
  SUBGOAL_THEN
   `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`
  (LABEL_TAC "distinct") THENL
   [SUBGOAL_THEN
     `{u:A,v} SUBSET V /\ ({u:A,v}:A->bool) HAS_SIZE 2`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC(ISPECL [`V:A->bool`; `u:A`; `v:A`; `w:A`]
       SUBDIVISION_VERTICES_DISTINCT) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((u:A,v) IN graph_darts
       ({{u,w},{w,v}} UNION (E DELETE {u,v}))) /\
    ~((v:A,u) IN graph_darts
       ({{u,w},{w,v}} UNION (E DELETE {u,v})))`
  (CONJUNCTS_THEN2 (LABEL_TAC "not_uv") (LABEL_TAC "not_vu")) THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`; `w:A`]
     GRAPH_DARTS_SUBDIVISION_NO_OLD_EDGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "retained" MP_TAC THEN REWRITE_TAC[IN_DELETE] THEN
  INTRO_TAC "(z_dart not_wu) not_wv" THEN
  MP_TAC(MATCH_MP
   (ISPECL [`u:A`; `v:A`; `w:A`]
    SUBDIVISION_TAIL_SWAP_VALUES)
   (ASSUME `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`)) THEN
  INTRO_TAC "quv quw qvu qvw" THEN
  ASM_CASES_TAC `z:A#A = (u,w)` THENL
   [ASM_REWRITE_TAC[REVERSE_DART_PAIR];
    ALL_TAC] THEN
  ASM_CASES_TAC `z:A#A = (v,w)` THENL
   [ASM_REWRITE_TAC[REVERSE_DART_PAIR];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(z:A#A = (u,v)) /\ ~(z = (u,w)) /\
    ~(z = (v,u)) /\ ~(z = (v,w))`
  (LABEL_TAC "z_other") THENL
   [ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `subdivision_tail_swap u v w (z:A#A) = z`
  (LABEL_TAC "qz") THENL
   [MATCH_MP_TAC SUBDIVISION_TAIL_SWAP_OTHER THEN
    USE_THEN "z_other" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `subdivision_tail_swap u v w (reverse_dart(z:A#A)) =
    reverse_dart z`
  (LABEL_TAC "qreverse") THENL
   [MATCH_MP_TAC SUBDIVISION_TAIL_SWAP_OTHER THEN
    MATCH_MP_TAC REVERSE_DART_AVOIDS_SUBDIVISION_PAIRS THEN
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;

let GRAPH_FACE_SUCCESSOR_SUPPRESS_CONJUGATE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
   !r:(A#A)->A#A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V)
        ==> !z:A#A.
             z IN graph_darts
                   ({{u,w},{w,v}} UNION (E DELETE {u,v}))
                  DELETE (w,u) DELETE (w,v)
             ==> (subdivision_tail_swap u v w o
                  graph_face_successor E
                   (graph_suppress_subdivision_rotation E u v w r) o
                  subdivision_tail_swap u v w) z =
                 if z = (u,w) then r(v,w)
                 else if z = (v,w) then r(u,w)
                 else graph_face_successor
                       ({{u,w},{w,v}} UNION (E DELETE {u,v})) r z`,
