   `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`
  (LABEL_TAC "distinct") THENL
   [SUBGOAL_THEN
     `{u:A,v} SUBSET V /\ ({u:A,v}:A->bool) HAS_SIZE 2`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC(ISPECL [`V:A->bool`; `u:A`; `v:A`; `w:A`]
       SUBDIVISION_VERTICES_DISTINCT) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (subdivision_tail_swap (u:A) v w)
      (graph_darts (E:(A->bool)->bool)) =
    graph_darts ({{u:A,w},{w,v}} UNION (E DELETE {u,v}))
    DELETE (w,u) DELETE (w,v)`
  (LABEL_TAC "image") THENL
   [MP_TAC(ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`;
       `u:A`; `v:A`; `w:A`]
      GRAPH_DARTS_SUBDIVISION_TAIL_SWAP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
  (ISPECL [`u:A`; `v:A`; `w:A`]
    SUBDIVISION_TAIL_SWAP_VALUES)
   (ASSUME `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`)) THEN
  INTRO_TAC "quv quw qvu qvw" THEN
  SUBGOAL_THEN
   `(u:A,w) IN
      graph_darts ({{u,w},{w,v}} UNION (E DELETE {u,v}))
      DELETE (w,u) DELETE (w,v) /\
    (v:A,w) IN
      graph_darts ({{u,w},{w,v}} UNION (E DELETE {u,v}))
      DELETE (w,u) DELETE (w,v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "uw_retained")
    (LABEL_TAC "vw_retained")) THENL
   [CONJ_TAC THENL
     [USE_THEN "image" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `(u:A,v:A)` THEN
      CONJ_TAC THENL
       [USE_THEN "quv" (ACCEPT_TAC o SYM);
        REWRITE_TAC[IN_GRAPH_DARTS] THEN USE_THEN "edge" ACCEPT_TAC];
      USE_THEN "image" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `(v:A,u:A)` THEN
      CONJ_TAC THENL
       [USE_THEN "qvu" (ACCEPT_TAC o SYM);
        REWRITE_TAC[IN_GRAPH_DARTS] THEN
        SUBGOAL_THEN `{v:A,u} = {u,v}` SUBST1_TAC THENL
         [SET_TAC[];
          USE_THEN "edge" ACCEPT_TAC]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(z:A#A) IN
    graph_darts ({{u,w},{w,v}} UNION (E DELETE {u,v}))`
  (LABEL_TAC "z_dart") THENL
   [USE_THEN "retained" MP_TAC THEN
    REWRITE_TAC[IN_DELETE] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(subdivision_tail_swap (u:A) v w o
     graph_face_successor (E:(A->bool)->bool)
      (graph_suppress_subdivision_rotation E u v w
       (r:(A#A)->A#A)) o
     subdivision_tail_swap u v w) z =
    restricted_permutation (r:(A#A)->A#A)
     (graph_darts ({{u:A,w},{w,v}} UNION (E DELETE {u,v}))
      DELETE (w,u) DELETE (w,v))
     (subdivision_tail_swap u v w
      (reverse_dart(subdivision_tail_swap u v w z)))`
  (LABEL_TAC "formula") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`; `z:A#A`]
     GRAPH_FACE_SUCCESSOR_SUPPRESS_CONJUGATE_FORMULA) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `subdivision_tail_swap (u:A) v w
     (reverse_dart(subdivision_tail_swap u v w z)) =
    if z = (u,w) then (v,w)
    else if z = (v,w) then (u,w)
    else reverse_dart z`
  (LABEL_TAC "swapped_reverse") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`; `z:A#A`]
     SUBDIVISION_TAIL_SWAP_REVERSE_RETAINED) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "formula" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "swapped_reverse" (fun th -> REWRITE_TAC[th]) THEN
  ASM_CASES_TAC `z:A#A = (u,w)` THENL
   [ASM_REWRITE_TAC[restricted_permutation];
    ALL_TAC] THEN
  ASM_CASES_TAC `z:A#A = (v,w)` THENL
   [ASM_REWRITE_TAC[restricted_permutation];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(reverse_dart(z:A#A) = (w,u)) /\
    ~(reverse_dart z = (w,v))`
  (CONJUNCTS_THEN2 (LABEL_TAC "reverse_not_wu")
    (LABEL_TAC "reverse_not_wv")) THENL
   [CONJ_TAC THEN DISCH_THEN(fun th ->
     MP_TAC(AP_TERM `reverse_dart:A#A->A#A` th)) THEN
    ASM_REWRITE_TAC[REVERSE_DART_INVOLUTION; REVERSE_DART_PAIR];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(z:A#A) IN
    graph_darts ({{u,w},{w,v}} UNION (E DELETE {u,v}))
    DELETE (w,u) DELETE (w,v)`
  (LABEL_TAC "reverse_retained") THENL
   [REWRITE_TAC[IN_DELETE] THEN
    ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE];
    ASM_SIMP_TAC[restricted_permutation; GRAPH_FACE_SUCCESSOR_IN]]);;

let GRAPH_FACE_SUCCESSOR_SUPPRESS_DELETE_TWO = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
   !r:(A#A)->A#A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        graph_rotation
          ({{u,w},{w,v}} UNION (E DELETE {u,v})) r
        ==> !z:A#A.
             z IN graph_darts
                   ({{u,w},{w,v}} UNION (E DELETE {u,v}))
                  DELETE (w,u) DELETE (w,v)
             ==> permutation_delete_two
                  (graph_face_successor
                    ({{u,w},{w,v}} UNION (E DELETE {u,v})) r)
                  (w,u) (w,v) z =
                 (subdivision_tail_swap u v w o
                  graph_face_successor E
                   (graph_suppress_subdivision_rotation E u v w r) o
                  subdivision_tail_swap u v w) z`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh rotation" THEN
  X_GEN_TAC `z:A#A` THEN DISCH_THEN(LABEL_TAC "retained") THEN
  ABBREV_TAC
   `S:(A->bool)->bool =
      {{u,w},{w,v}} UNION (E DELETE {u,v})` THEN
  ABBREV_TAC
   `f:(A#A)->A#A = graph_face_successor S r` THEN
  SUBGOAL_THEN
   `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`
  (LABEL_TAC "distinct") THENL
   [SUBGOAL_THEN
     `{u:A,v} SUBSET V /\ ({u:A,v}:A->bool) HAS_SIZE 2`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC(ISPECL [`V:A->bool`; `u:A`; `v:A`; `w:A`]
       SUBDIVISION_VERTICES_DISTINCT) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w:A,u) IN graph_darts S /\ (w:A,v) IN graph_darts S`
  (CONJUNCTS_THEN2 (LABEL_TAC "wu_dart") (LABEL_TAC "wv_dart")) THENL
   [EXPAND_TAC "S" THEN
    REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR;
                IN_UNION; IN_INSERT; IN_SING] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(u:A,w) IN graph_darts S DELETE (w,u) DELETE (w,v) /\
    (v:A,w) IN graph_darts S DELETE (w,u) DELETE (w,v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "uw_retained")
    (LABEL_TAC "vw_retained")) THENL
   [EXPAND_TAC "S" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`]
     GRAPH_DARTS_SUBDIVISION_RETAINED_ENDPOINTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(f:(A#A)->A#A) permutes graph_darts S`
  (LABEL_TAC "face_permutation") THENL
   [EXPAND_TAC "f" THEN MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(f:(A#A)->A#A) (u,w) = (w,v) /\
    f(v,w) = (w,u) /\ f(w,u) = r(u,w) /\ f(w,v) = r(v,w)`
  (CONJUNCTS_THEN2 (LABEL_TAC "fuw")
   (CONJUNCTS_THEN2 (LABEL_TAC "fvw")
    (CONJUNCTS_THEN2 (LABEL_TAC "fwu") (LABEL_TAC "fwv")))) THENL
   [EXPAND_TAC "f" THEN EXPAND_TAC "S" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`]
     GRAPH_FACE_SUCCESSOR_SUBDIVISION_VALUES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!d:A#A.
      d IN graph_darts S DELETE (w,u) DELETE (w,v)
      ==> permutation_delete_two (f:(A#A)->A#A) (w,u) (w,v) d =
          if d = (u,w) then f(w,v)
          else if d = (v,w) then f(w,u)
          else f d`
  (LABEL_TAC "deletion") THENL
   [MATCH_MP_TAC(ISPECL
     [`f:(A#A)->A#A`; `graph_darts S:(A#A)->bool`;
      `(w:A,u:A)`; `(w:A,v:A)`; `(u:A,w:A)`; `(v:A,w:A)`]
     PERMUTATION_DELETE_TWO_KNOWN_PREDECESSORS) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "face_permutation" ACCEPT_TAC;
      USE_THEN "wu_dart" ACCEPT_TAC;
      USE_THEN "wv_dart" ACCEPT_TAC;
      ASM_REWRITE_TAC[PAIR_EQ];
      USE_THEN "uw_retained" ACCEPT_TAC;
      USE_THEN "vw_retained" ACCEPT_TAC;
      USE_THEN "fuw" ACCEPT_TAC;
      USE_THEN "fvw" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_delete_two
      (graph_face_successor S (r:(A#A)->A#A)) (w,u) (w,v) z =
    permutation_delete_two (f:(A#A)->A#A) (w,u) (w,v) z`
  (LABEL_TAC "expand_f") THENL
   [EXPAND_TAC "f" THEN REFL_TAC;
    ALL_TAC] THEN
  USE_THEN "expand_f" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "deletion" (fun th ->
   REWRITE_TAC[MATCH_MP (SPEC `z:A#A` th)
    (ASSUME
     `(z:A#A) IN graph_darts S DELETE (w,u) DELETE (w,v)`)]) THEN
  USE_THEN "fwv" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "fwu" (fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPEC `z:A#A`
   (MATCH_MP
    (ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`]
     GRAPH_FACE_SUCCESSOR_SUPPRESS_CONJUGATE)
    (end_itlist CONJ
     [ASSUME `finite_simple_graph (V:A->bool) E`;
      ASSUME `{u:A,v} IN E`; ASSUME `~((w:A) IN V)`]))) THEN
  EXPAND_TAC "f" THEN EXPAND_TAC "S" THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o SYM));;

let FINITE_SIMPLE_GRAPH_SUBDIVIDED_EDGE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
        finite_simple_graph V E /\ {u,v} IN E /\ ~(w IN V)
        ==> finite_simple_graph
             (w INSERT V)
             ({{u,w},{w,v}} UNION (E DELETE {u,v}))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `w INSERT V:A->bool`;
    `{{u:A,w},{w:A,v}} UNION
      (E DELETE {u:A,v}):(A->bool)->bool`]
   FINITE_SIMPLE_GRAPH_EDGE_SUBDIVISION) THEN
  CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    REWRITE_TAC[graph_edge_subdivision] THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `v:A`; `w:A`] THEN
    ASM_REWRITE_TAC[]]);;

let CARD_SUBDIVISION_TAIL_SWAP_PERMUTATION_ORBITS = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
   !p:(A#A)->A#A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V)
        ==> CARD(permutation_orbits p (graph_darts E)) =
            CARD
             (permutation_orbits
              (subdivision_tail_swap u v w o p o
               subdivision_tail_swap u v w)
              (graph_darts
                ({{u,w},{w,v}} UNION (E DELETE {u,v})) DELETE
               (w,u) DELETE (w,v)))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh" THEN
  MATCH_MP_TAC(ISPECL
   [`p:(A#A)->A#A`; `subdivision_tail_swap (u:A) (v:A) (w:A)`;
    `graph_darts (E:(A->bool)->bool)`;
    `graph_darts
      ({{u:A,w},{w:A,v}} UNION (E DELETE {u:A,v})) DELETE
     (w:A,u:A) DELETE (w:A,v:A)`]
   CARD_INVOLUTION_CONJUGATE_PERMUTATION_ORBITS) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`u:A`; `v:A`; `w:A`]
     SUBDIVISION_TAIL_SWAP_INVOLUTION_APPLY) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `u:A`; `v:A`; `w:A`]
     SUBDIVISION_VERTICES_DISTINCT) THEN
    USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`]
     GRAPH_DARTS_SUBDIVISION_TAIL_SWAP) THEN
    ASM_REWRITE_TAC[]]);;

let CARD_GRAPH_FACES_SUPPRESS_SUBDIVISION = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
   !r:(A#A)->A#A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        graph_rotation
          ({{u,w},{w,v}} UNION (E DELETE {u,v})) r
        ==> CARD
             (graph_faces E
              (graph_suppress_subdivision_rotation E u v w r)) =
            CARD
             (graph_faces
              ({{u,w},{w,v}} UNION (E DELETE {u,v})) r)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh rotation" THEN
  ABBREV_TAC
   `S:(A->bool)->bool =
      {{u,w},{w,v}} UNION (E DELETE {u,v})` THEN
  ABBREV_TAC `D:(A#A)->bool = graph_darts E` THEN
  ABBREV_TAC `sdarts:(A#A)->bool = graph_darts S` THEN
  ABBREV_TAC
   `R:(A#A)->bool = sdarts DELETE (w,u) DELETE (w,v)` THEN
  ABBREV_TAC `q:(A#A)->A#A = subdivision_tail_swap u v w` THEN
  ABBREV_TAC
   `f:(A#A)->A#A = graph_face_successor S r` THEN
  ABBREV_TAC
   `g:(A#A)->A#A = graph_face_successor E
      (graph_suppress_subdivision_rotation E u v w r)` THEN
  ABBREV_TAC
   `h:(A#A)->A#A = permutation_delete_two f (w,u) (w,v)` THEN
  SUBGOAL_THEN
   `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`
  (LABEL_TAC "distinct") THENL
   [SUBGOAL_THEN
     `{u:A,v} SUBSET V /\ ({u:A,v}:A->bool) HAS_SIZE 2`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC(ISPECL [`V:A->bool`; `u:A`; `v:A`; `w:A`]
       SUBDIVISION_VERTICES_DISTINCT) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (w INSERT V:A->bool) S`
  (LABEL_TAC "subdivided_graph") THENL
   [EXPAND_TAC "S" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`]
     FINITE_SIMPLE_GRAPH_SUBDIVIDED_EDGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(D:(A#A)->bool)`
  (LABEL_TAC "finite_darts") THENL
   [EXPAND_TAC "D" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(sdarts:(A#A)->bool)`
  (LABEL_TAC "finite_subdivided_darts") THENL
   [EXPAND_TAC "sdarts" THEN
    MATCH_MP_TAC(ISPECL
     [`w INSERT V:A->bool`; `S:(A->bool)->bool`]
     FINITE_GRAPH_DARTS) THEN
    USE_THEN "subdivided_graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w:A,u:A) IN (sdarts:(A#A)->bool) /\
    (w:A,v:A) IN sdarts`
  (CONJUNCTS_THEN2 (LABEL_TAC "wu_dart") (LABEL_TAC "wv_dart")) THENL
   [EXPAND_TAC "sdarts" THEN EXPAND_TAC "S" THEN
    REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR;
                IN_UNION] THEN
    CONJ_TAC THEN DISJ1_TAC THENL
     [REWRITE_TAC[IN_INSERT] THEN DISJ1_TAC THEN
      MATCH_ACCEPT_TAC(SET_RULE `{w:A,u} = {u,w}`);
      REWRITE_TAC[IN_INSERT; IN_SING]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(f:(A#A)->A#A) permutes sdarts`
  (LABEL_TAC "face_permutation") THENL
   [EXPAND_TAC "f" THEN EXPAND_TAC "sdarts" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((f:(A#A)->A#A) (w,u) = (w,u)) /\
    ~(f(w,v) = (w,v))`
  (CONJUNCTS_THEN2 (LABEL_TAC "wu_nonfixed")
    (LABEL_TAC "wv_nonfixed")) THENL
   [CONJ_TAC THENL
     [EXPAND_TAC "f" THEN EXPAND_TAC "sdarts" THEN EXPAND_TAC "S" THEN
      MATCH_MP_TAC(ISPECL
       [`w INSERT V:A->bool`;
        `{{u:A,w},{w:A,v}} UNION
          (E DELETE {u:A,v}):(A->bool)->bool`;
        `r:(A#A)->A#A`; `(w:A,u:A)`]
       GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT) THEN
      ASM_REWRITE_TAC[];
      EXPAND_TAC "f" THEN EXPAND_TAC "sdarts" THEN EXPAND_TAC "S" THEN
      MATCH_MP_TAC(ISPECL
       [`w INSERT V:A->bool`;
        `{{u:A,w},{w:A,v}} UNION
          (E DELETE {u:A,v}):(A->bool)->bool`;
        `r:(A#A)->A#A`; `(w:A,v:A)`]
       GRAPH_FACE_SUCCESSOR_NO_FIXEDPOINT) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ASM_CASES_TAC
   `(f:(A#A)->A#A) (w:A,v:A) = (w:A,u:A)` THENL
   [POP_ASSUM(LABEL_TAC "same") THEN
    MP_TAC(ISPECL
     [`S:(A->bool)->bool`; `r:(A#A)->A#A`; `(w:A,v:A)`]
     GRAPH_FACE_SUCCESSOR_TAIL) THEN
    ASM_REWRITE_TAC[FST; SND];
    POP_ASSUM(LABEL_TAC "fwv_not_wu")] THEN
  SUBGOAL_THEN
   `permutation_delete (f:(A#A)->A#A)
      (w:A,u:A) (w:A,v:A) = f(w:A,v:A)`
  (LABEL_TAC "deleted_wv") THENL
   [MP_TAC(ISPECL
     [`f:(A#A)->A#A`; `sdarts:(A#A)->bool`;
      `(w:A,u:A)`; `(w:A,v:A)`]
     PERMUTATION_DELETE_APPLY_IN) THEN
    ASM_REWRITE_TAC[PAIR_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(permutation_delete (f:(A#A)->A#A)
       (w:A,u:A) (w:A,v:A) = (w:A,v:A))`
  (LABEL_TAC "deleted_wv_nonfixed") THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(h:(A#A)->A#A) permutes R`
  (LABEL_TAC "deleted_permutation") THENL
   [EXPAND_TAC "h" THEN EXPAND_TAC "R" THEN
    MATCH_MP_TAC PERMUTATION_DELETE_TWO_PERMUTES THEN
    ASM_REWRITE_TAC[PAIR_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(permutation_orbits (h:(A#A)->A#A) R) =
    CARD(permutation_orbits (f:(A#A)->A#A) sdarts)`
  (LABEL_TAC "deletion_count") THENL
   [EXPAND_TAC "h" THEN EXPAND_TAC "R" THEN
    MATCH_MP_TAC PERMUTATION_DELETE_TWO_ORBIT_COUNT THEN
    ASM_REWRITE_TAC[PAIR_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[GRAPH_FACES_AS_PERMUTATION_ORBITS] THEN
  TRANS_TAC EQ_TRANS
   `CARD(permutation_orbits (q o g o q:(A#A)->A#A) R)` THEN
  CONJ_TAC THENL
   [EXPAND_TAC "q" THEN EXPAND_TAC "g" THEN EXPAND_TAC "R" THEN
    EXPAND_TAC "sdarts" THEN EXPAND_TAC "S" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`;
      `graph_face_successor (E:(A->bool)->bool)
       (graph_suppress_subdivision_rotation E u v w
        (r:(A#A)->A#A))`]
     CARD_SUBDIVISION_TAIL_SWAP_PERMUTATION_ORBITS) THEN
    ASM_REWRITE_TAC[];
    TRANS_TAC EQ_TRANS
     `CARD(permutation_orbits (h:(A#A)->A#A) R)` THEN
    CONJ_TAC THENL
     [AP_TERM_TAC THEN
      MATCH_MP_TAC(ISPECL
       [`h:(A#A)->A#A`; `q o g o q:(A#A)->A#A`;
        `R:(A#A)->bool`] PERMUTATION_ORBITS_EQ_ON) THEN
      CONJ_TAC THENL
       [USE_THEN "deleted_permutation" ACCEPT_TAC;
        X_GEN_TAC `x:A#A` THEN
        DISCH_THEN(LABEL_TAC "x_retained") THEN
        EXPAND_TAC "h" THEN EXPAND_TAC "q" THEN EXPAND_TAC "g" THEN
        EXPAND_TAC "f" THEN EXPAND_TAC "R" THEN
        EXPAND_TAC "sdarts" THEN EXPAND_TAC "S" THEN
        MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
          `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`]
         GRAPH_FACE_SUCCESSOR_SUPPRESS_DELETE_TWO) THEN
        ASM_REWRITE_TAC[] THEN
        DISCH_THEN(MP_TAC o SPEC `x:A#A`) THEN
        ASM_REWRITE_TAC[] THEN
        DISCH_THEN(ACCEPT_TAC o SYM)];
      USE_THEN "deletion_count" MP_TAC THEN
      EXPAND_TAC "f" THEN EXPAND_TAC "sdarts" THEN
      REWRITE_TAC[]]]);;

let SUBDIVISION_NEW_EDGES_DISJOINT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
        finite_simple_graph V E /\
        ~(w IN V)
        ==> {{u,w},{w,v}} INTER E = {}`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph fresh" THEN
  MATCH_MP_TAC(SET_RULE
   `~((a:A->bool) IN e) /\ ~(b IN e)
    ==> {a,b} INTER e = {}`) THEN
  CONJ_TAC THENL
   [DISCH_THEN(LABEL_TAC "uw_old") THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `w:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    DISCH_THEN(LABEL_TAC "wv_old") THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `w:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS]]);;

let CARD_SUBDIVIDED_EDGE_SET = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V)
        ==> CARD
             ({{u,w},{w,v}} UNION (E DELETE {u,v})) =
            CARD E + 1`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh" THEN
  SUBGOAL_THEN
   `FINITE(E:(A->bool)->bool)`
  (LABEL_TAC "finite_edges") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`
  (LABEL_TAC "distinct") THENL
   [SUBGOAL_THEN
     `{u:A,v} SUBSET V /\ ({u:A,v}:A->bool) HAS_SIZE 2`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `u:A`; `v:A`; `w:A`]
       SUBDIVISION_VERTICES_DISTINCT) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(({u:A,w}:A->bool) = {w,v})`
  (LABEL_TAC "new_edges_distinct") THENL
   [USE_THEN "distinct" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `({{u:A,w},{w:A,v}}:(A->bool)->bool) HAS_SIZE 2`
  (LABEL_TAC "new_edges_size") THENL
   [REWRITE_TAC[PAIR_HAS_SIZE_2] THEN
    USE_THEN "new_edges_distinct" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`{{u:A,w},{w:A,v}}:(A->bool)->bool`;
    `(E:(A->bool)->bool) DELETE ({u:A,v}:A->bool)`]
   CARD_UNION) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "new_edges_size"
       (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[HAS_SIZE]);
      CONJ_TAC THENL
       [ASM_REWRITE_TAC[FINITE_DELETE];
        MATCH_MP_TAC(SET_RULE
         `(a:A->bool) INTER e = {}
          ==> a INTER (e DELETE c) = {}`) THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
          `u:A`; `v:A`; `w:A`]
         SUBDIVISION_NEW_EDGES_DISJOINT) THEN
        ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`{u:A,v}:A->bool`; `E:(A->bool)->bool`] CARD_DELETE) THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "new_edges_size" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE] THEN
  ASM_REWRITE_TAC[FINITE_DELETE] THEN
  SUBGOAL_THEN `~(CARD(E:(A->bool)->bool) = 0)` MP_TAC THENL
   [ASM_MESON_TAC[CARD_EQ_0; NOT_IN_EMPTY];
    ASM_ARITH_TAC]);;

let EULER_PLANAR_ROTATION_SUPPRESS_SUBDIVISION = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
   !r:(A#A)->A#A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        euler_planar_rotation
          (w INSERT V)
          ({{u,w},{w,v}} UNION (E DELETE {u,v})) r
        ==> euler_planar_rotation
             V E
             (graph_suppress_subdivision_rotation E u v w r)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge fresh euler" THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "subdivided_graph rotation formula" THEN
  SUBGOAL_THEN `FINITE(V:A->bool)`
  (LABEL_TAC "finite_vertices") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(w INSERT V:A->bool) = CARD V + 1`
  (LABEL_TAC "vertex_count") THENL
   [ASM_SIMP_TAC[CARD_CLAUSES] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD
     ({{u:A,w},{w:A,v}} UNION (E DELETE {u:A,v})) =
    CARD E + 1`
  (LABEL_TAC "edge_count") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`]
     CARD_SUBDIVIDED_EDGE_SET) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD
     (graph_faces (E:(A->bool)->bool)
      (graph_suppress_subdivision_rotation E
       (u:A) (v:A) (w:A) (r:(A#A)->A#A))) =
    CARD
     (graph_faces
      ({{u:A,w},{w:A,v}} UNION (E DELETE {u:A,v}))
      (r:(A#A)->A#A))`
  (LABEL_TAC "face_count") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`]
     CARD_GRAPH_FACES_SUPPRESS_SUBDIVISION) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(E:(A->bool)->bool = {})`
  (LABEL_TAC "edges_nonempty") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "edge" MP_TAC THEN REWRITE_TAC[NOT_IN_EMPTY];
    ALL_TAC] THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`]
     GRAPH_ROTATION_SUPPRESS_SUBDIVISION) THEN
    ASM_REWRITE_TAC[];
    USE_THEN "formula" MP_TAC THEN
    REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
    ASM_REWRITE_TAC
     [SET_RULE `~({a:A->bool,b} UNION e = {})`] THEN
    ASM_ARITH_TAC]);;

let EULER_PLANAR_ROTATION_SUBDIVISION_IMP = prove
 (`!V E V' E'. !r:(A#A)->A#A.
        graph_subdivision (V:A->bool) E V' E' /\
        euler_planar_rotation V' E' r
        ==> ?s:(A#A)->A#A. euler_planar_rotation V E s`,
  SUBGOAL_THEN
   `!V E V' E'.
        graph_subdivision (V:A->bool) E V' E'
        ==> finite_simple_graph V' E' /\
            (!r:(A#A)->A#A.
                euler_planar_rotation V' E' r
                ==> ?s:(A#A)->A#A.
                      euler_planar_rotation V E s)`
  MP_TAC THENL
   [MATCH_MP_TAC graph_subdivision_INDUCT THEN
    CONJ_TAC THENL
     [REPEAT GEN_TAC THEN INTRO_TAC "graph" THEN
      CONJ_TAC THENL
       [USE_THEN "graph" ACCEPT_TAC;
        X_GEN_TAC `r:(A#A)->A#A` THEN
        DISCH_THEN(LABEL_TAC "euler") THEN
        EXISTS_TAC `r:(A#A)->A#A` THEN
        USE_THEN "euler" ACCEPT_TAC];
      REPEAT GEN_TAC THEN
      INTRO_TAC "(intermediate_graph reflection) edge_step" THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL
         [`V':A->bool`; `E':(A->bool)->bool`;
          `V'':A->bool`; `E'':(A->bool)->bool`]
         FINITE_SIMPLE_GRAPH_EDGE_SUBDIVISION) THEN
        ASM_REWRITE_TAC[];
        X_GEN_TAC `r:(A#A)->A#A` THEN
        DISCH_THEN(LABEL_TAC "final_euler") THEN
        USE_THEN "edge_step" MP_TAC THEN
        REWRITE_TAC[graph_edge_subdivision] THEN
        INTRO_TAC "@u v w. edge fresh vertices edges" THEN
        USE_THEN "vertices" SUBST_ALL_TAC THEN
        USE_THEN "edges" SUBST_ALL_TAC THEN
        USE_THEN "reflection"
         (MATCH_MP_TAC o SPEC
           `graph_suppress_subdivision_rotation
             (E':(A->bool)->bool) (u:A) (v:A) (w:A)
             (r:(A#A)->A#A)`) THEN
        MATCH_MP_TAC(ISPECL
         [`V':A->bool`; `E':(A->bool)->bool`;
          `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`]
         EULER_PLANAR_ROTATION_SUPPRESS_SUBDIVISION) THEN
        ASM_REWRITE_TAC[]]];
    DISCH_THEN(LABEL_TAC "induction") THEN
    REPEAT GEN_TAC THEN
    INTRO_TAC "subdivision euler" THEN
    USE_THEN "induction" (fun ith ->
     USE_THEN "subdivision" (fun sth ->
      USE_THEN "euler" (fun eth ->
       ACCEPT_TAC
        (MATCH_MP
          (SPEC `r:(A#A)->A#A`
           (CONJUNCT2
            (MATCH_MP
             (SPECL
              [`V:A->bool`; `E:(A->bool)->bool`;
               `V':A->bool`; `E':(A->bool)->bool`] ith)
             sth)))
          eth))))]);;

let GRAPH_SUPPRESS_SUBDIVISION_PRESERVES_COFACIAL_DARTS = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
   !r:(A#A)->A#A. !a b:A#A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        graph_rotation
          ({{u,w},{w,v}} UNION (E DELETE {u,v})) r /\
        a IN graph_darts E /\
        b IN graph_darts E /\
        subdivision_tail_swap u v w b IN
          graph_face
           ({{u,w},{w,v}} UNION (E DELETE {u,v})) r
           (subdivision_tail_swap u v w a)
        ==> b IN
            graph_face E
             (graph_suppress_subdivision_rotation E u v w r) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph edge fresh rotation a_dart b_dart cofacial" THEN
  ABBREV_TAC
   `S:(A->bool)->bool =
      {{u,w},{w,v}} UNION (E DELETE {u,v})` THEN
  ABBREV_TAC `sdarts:(A#A)->bool = graph_darts S` THEN
  ABBREV_TAC
   `R:(A#A)->bool = sdarts DELETE (w,u) DELETE (w,v)` THEN
  ABBREV_TAC `q:(A#A)->A#A = subdivision_tail_swap u v w` THEN
  ABBREV_TAC `f:(A#A)->A#A = graph_face_successor S r` THEN
  ABBREV_TAC
   `g:(A#A)->A#A = graph_face_successor E
      (graph_suppress_subdivision_rotation E u v w r)` THEN
  ABBREV_TAC
   `h:(A#A)->A#A = permutation_delete_two f (w,u) (w,v)` THEN
  SUBGOAL_THEN
   `~(u:A = v) /\ ~(u = w) /\ ~(v = w)`
  (LABEL_TAC "distinct") THENL
   [MATCH_MP_TAC(ISPECL [`V:A->bool`; `u:A`; `v:A`; `w:A`]
     SUBDIVISION_VERTICES_DISTINCT) THEN
    USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (w INSERT V:A->bool) S`
  (LABEL_TAC "subdivided_graph") THENL
   [EXPAND_TAC "S" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`]
     FINITE_SIMPLE_GRAPH_SUBDIVIDED_EDGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(sdarts:(A#A)->bool)`
  (LABEL_TAC "finite_subdivided_darts") THENL
   [EXPAND_TAC "sdarts" THEN
    MATCH_MP_TAC(ISPECL
     [`w INSERT V:A->bool`; `S:(A->bool)->bool`]
     FINITE_GRAPH_DARTS) THEN
    USE_THEN "subdivided_graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w:A,u:A) IN sdarts /\ (w:A,v:A) IN sdarts`
  (CONJUNCTS_THEN2 (LABEL_TAC "wu_dart") (LABEL_TAC "wv_dart")) THENL
   [EXPAND_TAC "sdarts" THEN EXPAND_TAC "S" THEN
    REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR;
                IN_UNION; IN_INSERT; IN_SING] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(f:(A#A)->A#A) permutes sdarts`
  (LABEL_TAC "face_permutation") THENL
   [EXPAND_TAC "f" THEN EXPAND_TAC "sdarts" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(h:(A#A)->A#A) permutes R`
  (LABEL_TAC "deleted_permutation") THENL
   [EXPAND_TAC "h" THEN EXPAND_TAC "R" THEN
    MATCH_MP_TAC PERMUTATION_DELETE_TWO_PERMUTES THEN
    ASM_REWRITE_TAC[PAIR_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN `!z:A#A. (q:(A#A)->A#A)(q z) = z`
  (LABEL_TAC "involution") THENL
   [EXPAND_TAC "q" THEN
    MATCH_MP_TAC(ISPECL [`u:A`; `v:A`; `w:A`]
     SUBDIVISION_TAIL_SWAP_INVOLUTION_APPLY) THEN
    USE_THEN "distinct" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (q:(A#A)->A#A) (graph_darts E) = R`
  (LABEL_TAC "dart_image") THENL
   [EXPAND_TAC "q" THEN EXPAND_TAC "R" THEN
    EXPAND_TAC "sdarts" THEN EXPAND_TAC "S" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`]
     GRAPH_DARTS_SUBDIVISION_TAIL_SWAP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:(A#A)->A#A) a IN R /\ q b IN R`
  (CONJUNCTS_THEN2 (LABEL_TAC "qa_retained")
    (LABEL_TAC "qb_retained")) THENL
   [USE_THEN "dart_image" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    REWRITE_TAC[IN_IMAGE] THEN CONJ_TAC THENL
     [EXISTS_TAC `a:A#A` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `b:A#A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:(A#A)->A#A) b IN permutation_orbit f (q a)`
  (LABEL_TAC "old_orbit") THENL
   [USE_THEN "cofacial" MP_TAC THEN
    REWRITE_TAC[GRAPH_FACE_AS_PERMUTATION_ORBIT] THEN
    MAP_EVERY EXPAND_TAC ["q"; "f"; "S"] THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:(A#A)->A#A) b IN permutation_orbit h (q a)`
  (LABEL_TAC "deleted_orbit") THENL
   [EXPAND_TAC "h" THEN
    MATCH_MP_TAC(ISPECL
     [`f:(A#A)->A#A`; `sdarts:(A#A)->bool`;
      `(w:A,u:A)`; `(w:A,v:A)`;
      `(q:(A#A)->A#A) a`; `(q:(A#A)->A#A) b`]
     PERMUTATION_DELETE_TWO_PRESERVES_OLD_ORBIT) THEN
    ASM_REWRITE_TAC[PAIR_EQ] THEN
    CONJ_TAC THENL
     [USE_THEN "qa_retained" MP_TAC;
      USE_THEN "qb_retained" MP_TAC] THEN
    EXPAND_TAC "R" THEN SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit (q o g o q:(A#A)->A#A) (q a) =
    permutation_orbit h (q a)`
  (LABEL_TAC "same_deleted_orbit") THENL
   [MATCH_MP_TAC PERMUTATION_ORBIT_EQ_IF_AGREE THEN
    X_GEN_TAC `z:A#A` THEN DISCH_THEN(LABEL_TAC "z_orbit") THEN
    SUBGOAL_THEN `(z:A#A) IN R` (LABEL_TAC "z_retained") THENL
     [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (MATCH_MP
        (ISPECL
         [`h:(A#A)->A#A`; `R:(A#A)->bool`;
          `(q:(A#A)->A#A) a`]
         PERMUTATION_ORBIT_SUBSET)
        (CONJ
         (ASSUME `(h:(A#A)->A#A) permutes R`)
         (ASSUME `((q:(A#A)->A#A) a) IN R`)))) THEN
      USE_THEN "z_orbit" ACCEPT_TAC;
      ALL_TAC] THEN
    MAP_EVERY EXPAND_TAC ["h"; "f"; "q"; "g"; "R";
                          "sdarts"; "S"] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`]
     GRAPH_FACE_SUCCESSOR_SUPPRESS_DELETE_TWO) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `z:A#A`) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o SYM);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (q:(A#A)->A#A) (permutation_orbit g a) =
    permutation_orbit (q o g o q) (q a)`
  (LABEL_TAC "orbit_image") THENL
   [USE_THEN "involution" (fun ith ->
     MATCH_ACCEPT_TAC
      (SPEC `a:A#A`
       (MATCH_MP
        (ISPECL
         [`g:(A#A)->A#A`; `q:(A#A)->A#A`]
         INVOLUTION_IMAGE_CONJUGATE_PERMUTATION_ORBIT)
        ith)));
    ALL_TAC] THEN
  REWRITE_TAC[GRAPH_FACE_AS_PERMUTATION_ORBIT] THEN
  EXPAND_TAC "g" THEN
  SUBGOAL_THEN
   `(q:(A#A)->A#A) b IN IMAGE q (permutation_orbit g a)`
  MP_TAC THENL
   [USE_THEN "orbit_image" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "same_deleted_orbit" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "deleted_orbit" ACCEPT_TAC;
    REWRITE_TAC[IN_IMAGE] THEN
    DISCH_THEN(X_CHOOSE_THEN `c:A#A`
     (CONJUNCTS_THEN2 (LABEL_TAC "same_image")
       (LABEL_TAC "c_orbit"))) THEN
    SUBGOAL_THEN `(c:A#A) = b` SUBST_ALL_TAC THENL
     [USE_THEN "same_image" MP_TAC THEN
      USE_THEN "involution" (fun th ->
       MP_TAC(SPEC `c:A#A` th) THEN MP_TAC(SPEC `b:A#A` th)) THEN
      MESON_TAC[];
      USE_THEN "c_orbit" MP_TAC THEN EXPAND_TAC "g" THEN
      SIMP_TAC[]]]);;

let GRAPH_SUPPRESS_SUBDIVISION_PRESERVES_COFACIAL_SET = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
   !r:(A#A)->A#A. !a:A#A. !C:(A#A)->bool.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        graph_rotation
          ({{u,w},{w,v}} UNION (E DELETE {u,v})) r /\
        a IN graph_darts E /\
        C SUBSET graph_darts E /\
        IMAGE (subdivision_tail_swap u v w) C SUBSET
          graph_face
           ({{u,w},{w,v}} UNION (E DELETE {u,v})) r
           (subdivision_tail_swap u v w a)
        ==> C SUBSET
            graph_face E
             (graph_suppress_subdivision_rotation E u v w r) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph edge fresh rotation a_dart C_darts cofacial" THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `b:A#A` THEN
  DISCH_THEN(LABEL_TAC "b_member") THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`;
    `a:A#A`; `b:A#A`]
   GRAPH_SUPPRESS_SUBDIVISION_PRESERVES_COFACIAL_DARTS) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [USE_THEN "C_darts" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "b_member" ACCEPT_TAC;
    USE_THEN "cofacial" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `b:A#A` THEN
    ASM_REWRITE_TAC[]]);;

let EULER_PLANAR_ROTATION_SUPPRESS_SUBDIVISION_PRESERVES_COFACIAL_SET =
 prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
   !r:(A#A)->A#A. !a:A#A. !C:(A#A)->bool.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        euler_planar_rotation
          (w INSERT V)
          ({{u,w},{w,v}} UNION (E DELETE {u,v})) r /\
        a IN graph_darts E /\
        C SUBSET graph_darts E /\
        IMAGE (subdivision_tail_swap u v w) C SUBSET
          graph_face
           ({{u,w},{w,v}} UNION (E DELETE {u,v})) r
           (subdivision_tail_swap u v w a)
        ==> euler_planar_rotation V E
             (graph_suppress_subdivision_rotation E u v w r) /\
            C SUBSET
             graph_face E
              (graph_suppress_subdivision_rotation E u v w r) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph edge fresh euler a_dart C_darts cofacial" THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`]
     EULER_PLANAR_ROTATION_SUPPRESS_SUBDIVISION) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`;
      `a:A#A`; `C:(A#A)->bool`]
     GRAPH_SUPPRESS_SUBDIVISION_PRESERVES_COFACIAL_SET) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[]]);;

let GRAPH_FACE_TAILS_EQ_VERTICES = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A. !d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        d IN graph_darts E
        ==> IMAGE FST (graph_face E r d) =
            graph_rotation_face_vertices E r d`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph rotation dart" THEN
  SUBGOAL_THEN
   `graph_face E (r:(A#A)->A#A) d SUBSET graph_darts E`
  (LABEL_TAC "face_darts") THENL
   [MATCH_MP_TAC GRAPH_FACE_SUBSET_DARTS THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (graph_face_successor E (r:(A#A)->A#A))
      (graph_face E r d) = graph_face E r d`
  (LABEL_TAC "successor_image") THENL
   [REWRITE_TAC[GRAPH_FACE_AS_PERMUTATION_ORBIT] THEN
    MATCH_MP_TAC(ISPECL
     [`graph_face_successor E (r:(A#A)->A#A)`;
      `graph_darts E:A#A->bool`; `d:A#A`]
     PERMUTATION_ORBIT_IMAGE) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      USE_THEN "graph" ACCEPT_TAC;
      MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
      USE_THEN "rotation" ACCEPT_TAC;
      USE_THEN "dart" ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[graph_rotation_face_vertices] THEN
  USE_THEN "successor_image" (fun th ->
   GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [GSYM th]) THEN
  REWRITE_TAC[GSYM IMAGE_o] THEN
  MATCH_MP_TAC IMAGE_EQ THEN X_GEN_TAC `e:A#A` THEN
  DISCH_THEN(LABEL_TAC "e_face") THEN REWRITE_TAC[o_THM] THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `e:A#A`]
   GRAPH_FACE_SUCCESSOR_TAIL) THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "face_darts" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
  USE_THEN "e_face" ACCEPT_TAC);;

let EULER_PLANAR_ROTATION_SUPPRESS_SUBDIVISION_PRESERVES_FACE_VERTICES =
 prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v w.
   !r:(A#A)->A#A. !d:A#A. !W:A->bool.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        euler_planar_rotation
          (w INSERT V)
          ({{u,w},{w,v}} UNION (E DELETE {u,v})) r /\
        d IN graph_darts
          ({{u,w},{w,v}} UNION (E DELETE {u,v})) /\
        W SUBSET V /\
        ~(W = {}) /\
        W SUBSET
          graph_rotation_face_vertices
           ({{u,w},{w,v}} UNION (E DELETE {u,v})) r d
        ==> ?a:A#A.
              euler_planar_rotation V E
               (graph_suppress_subdivision_rotation E u v w r) /\
              a IN graph_darts E /\
              W SUBSET
               graph_rotation_face_vertices E
                (graph_suppress_subdivision_rotation E u v w r) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph edge fresh euler d_dart W_vertices W_nonempty marked" THEN
  ABBREV_TAC
   `S:(A->bool)->bool =
      {{u,w},{w,v}} UNION (E DELETE {u,v})` THEN
  ABBREV_TAC `q:(A#A)->A#A = subdivision_tail_swap u v w` THEN
  ABBREV_TAC
   `C:(A#A)->bool =
      {c:A#A |
        c IN graph_darts (E:(A->bool)->bool) /\
        (q:(A#A)->A#A) c IN
        graph_face (S:(A->bool)->bool) (r:(A#A)->A#A) (d:A#A)}` THEN
  SUBGOAL_THEN `finite_simple_graph (w INSERT V:A->bool) S`
  (LABEL_TAC "subdivided_graph") THENL
   [EXPAND_TAC "S" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`]
     FINITE_SIMPLE_GRAPH_SUBDIVIDED_EDGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `graph_rotation S (r:(A#A)->A#A)`
  (LABEL_TAC "rotation") THENL
   [USE_THEN "euler" MP_TAC THEN EXPAND_TAC "S" THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face S (r:(A#A)->A#A) d SUBSET graph_darts S`
  (LABEL_TAC "face_darts") THENL
   [MATCH_MP_TAC GRAPH_FACE_SUBSET_DARTS THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "d_dart" MP_TAC THEN EXPAND_TAC "S" THEN SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (q:(A#A)->A#A) (graph_darts E) =
    graph_darts S DELETE (w,u) DELETE (w,v)`
  (LABEL_TAC "dart_image") THENL
   [EXPAND_TAC "q" THEN EXPAND_TAC "S" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`]
     GRAPH_DARTS_SUBDIVISION_TAIL_SWAP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(C:(A#A)->bool) SUBSET graph_darts E`
  (LABEL_TAC "C_darts") THENL
   [EXPAND_TAC "C" THEN REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
    X_GEN_TAC `c:A#A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (q:(A#A)->A#A) C SUBSET graph_face S r d`
  (LABEL_TAC "C_cofacial") THENL
   [EXPAND_TAC "C" THEN
    REWRITE_TAC[SUBSET; FORALL_IN_IMAGE; IN_ELIM_THM] THEN
    X_GEN_TAC `c:A#A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(W:A->bool) SUBSET
    IMAGE (FST:A#A->A) (C:(A#A)->bool)`
  (LABEL_TAC "W_tails") THENL
   [REWRITE_TAC[SUBSET] THEN X_GEN_TAC `x:A` THEN
    DISCH_THEN(LABEL_TAC "x_marked") THEN
    SUBGOAL_THEN
     `(x:A) IN graph_rotation_face_vertices S r d`
    (LABEL_TAC "x_face_vertex") THENL
     [USE_THEN "marked" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "x_marked" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(x:A) IN V` (LABEL_TAC "x_vertex") THENL
     [USE_THEN "W_vertices" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "x_marked" ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`w INSERT V:A->bool`; `S:(A->bool)->bool`;
      `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_FACE_TAILS_EQ_VERTICES) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th ->
     USE_THEN "x_face_vertex" (MP_TAC o REWRITE_RULE[GSYM th])) THEN
    REWRITE_TAC[IN_IMAGE] THEN
    DISCH_THEN(X_CHOOSE_THEN `e:A#A`
     (CONJUNCTS_THEN2 (LABEL_TAC "e_tail") (LABEL_TAC "e_face"))) THEN
    SUBGOAL_THEN `(e:A#A) IN graph_darts S`
    (LABEL_TAC "e_dart") THENL
     [USE_THEN "face_darts" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "e_face" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(e:A#A) IN graph_darts S DELETE (w,u) DELETE (w,v)`
    (LABEL_TAC "e_retained") THENL
     [REWRITE_TAC[IN_DELETE] THEN ASM_REWRITE_TAC[] THEN
      CONJ_TAC THEN DISCH_THEN SUBST_ALL_TAC THEN
      ASM_MESON_TAC[FST];
      ALL_TAC] THEN
    MP_TAC(ASSUME
     `(e:A#A) IN
      graph_darts S DELETE (w,u) DELETE (w,v)`) THEN
    REWRITE_TAC
     [GSYM
       (ASSUME
        `IMAGE (q:(A#A)->A#A) (graph_darts E) =
         graph_darts S DELETE (w,u) DELETE (w,v)`);
      IN_IMAGE] THEN
    DISCH_THEN(X_CHOOSE_THEN `c:A#A`
     (CONJUNCTS_THEN2 (LABEL_TAC "c_image") (LABEL_TAC "c_dart"))) THEN
    REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `c:A#A` THEN
    CONJ_TAC THENL
     [TRANS_TAC EQ_TRANS `FST(e:A#A)` THEN
      CONJ_TAC THENL
       [ACCEPT_TAC(ASSUME `(x:A) = FST(e:A#A)`);
        MP_TAC
         (AP_TERM `FST:A#A->A`
          (ASSUME `(e:A#A) = (q:(A#A)->A#A) c`)) THEN
        EXPAND_TAC "q" THEN
        REWRITE_TAC[SUBDIVISION_TAIL_SWAP_FST]];
      EXPAND_TAC "C" THEN REWRITE_TAC[IN_ELIM_THM] THEN
      CONJ_TAC THENL
       [ACCEPT_TAC(ASSUME `(c:A#A) IN graph_darts E`);
        ACCEPT_TAC
         (EQ_MP
          (BETA_RULE
           (AP_TERM
            `\z:A#A.
               z IN graph_face
                     (S:(A->bool)->bool)
                     (r:(A#A)->A#A) (d:A#A)`
            (ASSUME `(e:A#A) = (q:(A#A)->A#A) c`)))
          (ASSUME `(e:A#A) IN graph_face S r d`))]];
    ALL_TAC] THEN
  MP_TAC(ASSUME `~((W:A->bool) = {})`) THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
  DISCH_THEN(X_CHOOSE_THEN `x0:A` (LABEL_TAC "x0_member")) THEN
  MP_TAC
   (MATCH_MP
    (SPEC `x0:A`
     (REWRITE_RULE[SUBSET]
      (ASSUME
       `(W:A->bool) SUBSET
        IMAGE (FST:A#A->A) (C:(A#A)->bool)`)))
    (ASSUME `(x0:A) IN W`)) THEN
  REWRITE_TAC[IN_IMAGE] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A#A`
   (CONJUNCTS_THEN2 (LABEL_TAC "x0_tail") (LABEL_TAC "a_member"))) THEN
  USE_THEN "a_member" MP_TAC THEN EXPAND_TAC "C" THEN
  REWRITE_TAC[IN_ELIM_THM] THEN
  INTRO_TAC "a_dart qa_face" THEN
  MP_TAC(ISPECL
   [`w INSERT V:A->bool`; `S:(A->bool)->bool`;
    `r:(A#A)->A#A`; `d:A#A`; `(q:(A#A)->A#A) a`]
   GRAPH_FACE_EQ) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "same_face") THEN
  MP_TAC
   (REWRITE_RULE
    [GSYM
     (ASSUME
      `graph_face (S:(A->bool)->bool) (r:(A#A)->A#A)
        ((q:(A#A)->A#A) a) =
       graph_face S r (d:A#A)`)]
    (ASSUME
     `IMAGE (q:(A#A)->A#A) (C:(A#A)->bool) SUBSET
      graph_face S r d`)) THEN
  DISCH_THEN(LABEL_TAC "anchored_cofacial") THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`;
    `a:A#A`; `C:(A#A)->bool`]
   EULER_PLANAR_ROTATION_SUPPRESS_SUBDIVISION_PRESERVES_COFACIAL_SET) THEN
  ANTS_TAC THENL
   [MAP_EVERY EXPAND_TAC ["q"; "S"] THEN ASM_REWRITE_TAC[];
    INTRO_TAC "suppressed_euler suppressed_cofacial"] THEN
  EXISTS_TAC `a:A#A` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "suppressed_euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "suppressed_graph suppressed_rotation suppressed_formula" THEN
  MATCH_MP_TAC SUBSET_TRANS THEN
  EXISTS_TAC
   `IMAGE (FST:A#A->A) (C:(A#A)->bool)` THEN
  CONJ_TAC THENL
   [USE_THEN "W_tails" ACCEPT_TAC;
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC
     `IMAGE (FST:A#A->A)
       (graph_face E
        (graph_suppress_subdivision_rotation E u v w r) a)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC IMAGE_SUBSET THEN
      USE_THEN "suppressed_cofacial" ACCEPT_TAC;
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
       `graph_suppress_subdivision_rotation E u v w r:
          (A#A)->A#A`;
        `a:A#A`] GRAPH_FACE_TAILS_EQ_VERTICES) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th; SUBSET_REFL])]]);;

let EULER_PLANAR_ROTATION_SUBDIVISION_PRESERVES_FACE_VERTICES = prove
 (`!V E V' E'. !r:(A#A)->A#A. !d:A#A. !W:A->bool.
        graph_subdivision (V:A->bool) E V' E' /\
        euler_planar_rotation V' E' r /\
        d IN graph_darts E' /\
        W SUBSET V /\
        ~(W = {}) /\
        W SUBSET graph_rotation_face_vertices E' r d
        ==> ?s:(A#A)->A#A. ?a:A#A.
              euler_planar_rotation V E s /\
              a IN graph_darts E /\
              W SUBSET graph_rotation_face_vertices E s a`,
  SUBGOAL_THEN
   `!V E V' E'.
        graph_subdivision (V:A->bool) E V' E'
        ==> V SUBSET V' /\
            finite_simple_graph V' E' /\
            (!r:(A#A)->A#A. !d:A#A. !W:A->bool.
                euler_planar_rotation V' E' r /\
                d IN graph_darts E' /\
                W SUBSET V /\
                ~(W = {}) /\
                W SUBSET graph_rotation_face_vertices E' r d
                ==> ?s:(A#A)->A#A. ?a:A#A.
                      euler_planar_rotation V E s /\
                      a IN graph_darts E /\
                      W SUBSET graph_rotation_face_vertices E s a)`
  MP_TAC THENL
   [MATCH_MP_TAC graph_subdivision_INDUCT THEN
    CONJ_TAC THENL
     [REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
      REPEAT CONJ_TAC THENL
       [REWRITE_TAC[SUBSET_REFL];
        USE_THEN "graph" ACCEPT_TAC;
        REPEAT GEN_TAC THEN
        INTRO_TAC "euler dart W_vertices W_nonempty marked" THEN
        EXISTS_TAC `r:(A#A)->A#A` THEN
        EXISTS_TAC `d:A#A` THEN
        ASM_REWRITE_TAC[]];
      REPEAT GEN_TAC THEN
      INTRO_TAC
       "(source_subset intermediate_graph reflection) edge_step" THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "edge_step" MP_TAC THEN
        REWRITE_TAC[graph_edge_subdivision] THEN
        USE_THEN "source_subset" MP_TAC THEN SET_TAC[];
        MATCH_MP_TAC(ISPECL
         [`V':A->bool`; `E':(A->bool)->bool`;
          `V'':A->bool`; `E'':(A->bool)->bool`]
         FINITE_SIMPLE_GRAPH_EDGE_SUBDIVISION) THEN
        ASM_REWRITE_TAC[];
        REPEAT GEN_TAC THEN
        INTRO_TAC "final_euler final_dart W_vertices W_nonempty marked" THEN
        USE_THEN "edge_step" MP_TAC THEN
        REWRITE_TAC[graph_edge_subdivision] THEN
        INTRO_TAC "@u v w. edge fresh vertices edges" THEN
        USE_THEN "vertices" SUBST_ALL_TAC THEN
        USE_THEN "edges" SUBST_ALL_TAC THEN
        SUBGOAL_THEN `(W:A->bool) SUBSET V'`
        (LABEL_TAC "W_intermediate") THENL
         [MATCH_MP_TAC SUBSET_TRANS THEN
          EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        MP_TAC(ISPECL
         [`V':A->bool`; `E':(A->bool)->bool`;
          `u:A`; `v:A`; `w:A`; `r:(A#A)->A#A`;
          `d:A#A`; `W:A->bool`]
         EULER_PLANAR_ROTATION_SUPPRESS_SUBDIVISION_PRESERVES_FACE_VERTICES)
        THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[];
          INTRO_TAC
           "@a. intermediate_euler intermediate_dart \
            intermediate_marked"] THEN
        USE_THEN "reflection"
         (MATCH_MP_TAC o SPECL
           [`graph_suppress_subdivision_rotation
              (E':(A->bool)->bool) (u:A) (v:A) (w:A)
              (r:(A#A)->A#A)`;
            `a:A#A`; `W:A->bool`]) THEN
        ASM_REWRITE_TAC[]]];
    DISCH_THEN(LABEL_TAC "induction") THEN
    REPEAT GEN_TAC THEN
    INTRO_TAC "subdivision euler dart W_vertices W_nonempty marked" THEN
    USE_THEN "induction" (fun ith ->
     USE_THEN "subdivision" (fun sth ->
      MP_TAC
       (MATCH_MP
        (SPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
          `V':A->bool`; `E':(A->bool)->bool`] ith)
        sth))) THEN
    INTRO_TAC "_ _ reflection" THEN
    USE_THEN "reflection"
     (MATCH_MP_TAC o SPECL
       [`r:(A#A)->A#A`; `d:A#A`; `W:A->bool`]) THEN
    ASM_REWRITE_TAC[]]);;

let EULER_PLANAR_ROTATION_K4_SUBDIVISION_NOT_COFACIAL = prove
 (`!W V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A. !d:A#A.
        W HAS_SIZE 4 /\
        graph_subdivision W (complete_graph_edges W) V E /\
        euler_planar_rotation V E r /\
        d IN graph_darts E
        ==> ~(W SUBSET graph_rotation_face_vertices E r d)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "size subdivision euler dart" THEN
  DISCH_THEN(LABEL_TAC "cofacial") THEN
  SUBGOAL_THEN `~((W:A->bool) = {})` (LABEL_TAC "nonempty") THENL
   [USE_THEN "size" MP_TAC THEN
    REWRITE_TAC[HAS_SIZE] THEN
    INTRO_TAC "_ card" THEN
    DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "card" MP_TAC THEN
    REWRITE_TAC[CARD_CLAUSES] THEN ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`W:A->bool`; `complete_graph_edges W:(A->bool)->bool`;
    `V:A->bool`; `E:(A->bool)->bool`;
    `r:(A#A)->A#A`; `d:A#A`; `W:A->bool`]
   EULER_PLANAR_ROTATION_SUBDIVISION_PRESERVES_FACE_VERTICES) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[SUBSET_REFL];
    INTRO_TAC "@s a. base_euler base_dart base_cofacial"] THEN
  SUBGOAL_THEN
   `CARD(graph_rotation_face_vertices
          (complete_graph_edges (W:A->bool)) s a) <= 3`
  (LABEL_TAC "face_small") THENL
   [MATCH_MP_TAC(ISPECL
     [`W:A->bool`; `s:(A#A)->A#A`; `a:A#A`]
     EULER_PLANAR_COMPLETE_GRAPH_4_FACE_VERTICES_CARD_LE_3) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph (W:A->bool) (complete_graph_edges W) /\
    graph_rotation (complete_graph_edges W) (s:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "base_graph")
   (LABEL_TAC "base_rotation")) THENL
   [USE_THEN "base_euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(graph_rotation_face_vertices
      (complete_graph_edges (W:A->bool)) (s:(A#A)->A#A) a)`
  (LABEL_TAC "finite_face") THENL
   [MATCH_MP_TAC(ISPECL
     [`W:A->bool`; `complete_graph_edges W:(A->bool)->bool`;
      `s:(A#A)->A#A`; `a:A#A`]
     FINITE_GRAPH_ROTATION_FACE_VERTICES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(W:A->bool) <=
    CARD(graph_rotation_face_vertices
      (complete_graph_edges W) (s:(A#A)->A#A) a)`
  (LABEL_TAC "four_le_face") THENL
   [MATCH_MP_TAC CARD_SUBSET THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "size" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE] THEN
  USE_THEN "four_le_face" MP_TAC THEN
  USE_THEN "face_small" MP_TAC THEN ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* Alternating chords and chordless ears on an Euler-planar boundary.        *)
(* ------------------------------------------------------------------------- *)

let BOUNDARY_EULER_ROTATION_NO_ALTERNATING_CHORDS = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A. !i j k.
        boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        connected_graph V E /\
        3 <= CARD V /\
        0 < i /\ i < j /\ j < k /\ k < n
        ==> ~({q 0,q j} IN E /\ {q i,q k} IN E)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "boundary cycle connected vertices_large i_positive ij jk kn" THEN
  INTRO_TAC "chord0 chord1" THEN
  USE_THEN "boundary" MP_TAC THEN
  REWRITE_TAC[boundary_euler_rotation] THEN
  INTRO_TAC "euler boundary_face" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "nlarge injective cycle_edges" THEN
  MP_TAC(ISPECL
   [`q:num->A`; `n:num`; `i:num`; `j:num`; `k:num`]
   CYCLIC_K4_SUBDIVISION) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "subdivision cycle_in_subdivision" THEN
