let CYCLIC_DARTS_OFFSET = prove
 (`!q:num->A. !n k.
        cyclic_darts (\i. q((i + k) MOD n)) n = cyclic_darts q n`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cyclic_darts] THEN
  TRANS_TAC EQ_TRANS
   `IMAGE (\i. ((q:num->A) i,q((i + 1) MOD n)))
      (IMAGE
        (\i. if i < n then (i + k) MOD n else i)
        (cyclic_indices n))` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[GSYM IMAGE_o; o_THM] THEN
    MATCH_MP_TAC IMAGE_EQ THEN
    REWRITE_TAC[o_THM; IN_CYCLIC_INDICES] THEN
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[CYCLIC_OFFSET_SUCCESSOR];
    SUBGOAL_THEN
     `IMAGE
       (\i. if i < n then (i + k) MOD n else i)
       (cyclic_indices n) =
      cyclic_indices n`
    SUBST1_TAC THENL
     [MATCH_MP_TAC PERMUTES_IMAGE THEN
      REWRITE_TAC[cyclic_indices; PERMUTES_CYCLIC_N];
      REFL_TAC]]);;

let BOUNDARY_EULER_ROTATION_OFFSET = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A. !k.
        boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n
        ==> boundary_euler_rotation
             V E (\i. q((i + k) MOD n)) n r`,
  REPEAT GEN_TAC THEN INTRO_TAC "boundary cycle" THEN
  USE_THEN "boundary" MP_TAC THEN
  REWRITE_TAC[boundary_euler_rotation] THEN
  INTRO_TAC "euler boundary_face" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective cycle_edges" THEN
  SUBGOAL_THEN `1 MOD n = 1` (LABEL_TAC "one_mod") THENL
   [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((q:num->A) 0,q 1) IN graph_darts E`
  (LABEL_TAC "base_dart") THENL
   [REWRITE_TAC[IN_GRAPH_DARTS] THEN
    USE_THEN "cycle_edges"
     (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_EDGES] THEN
    EXISTS_TAC `0` THEN
    CONJ_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[ADD_CLAUSES] THEN
      USE_THEN "one_mod" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((\i. (q:num->A) ((i + k) MOD n)) 0,
     (\i. q((i + k) MOD n)) 1) IN
    graph_face E r (q 0,q 1)`
  (LABEL_TAC "offset_in_face") THENL
   [SUBGOAL_THEN
     `cyclic_darts (\i. (q:num->A) ((i + k) MOD n)) n =
      cyclic_darts q n`
    (LABEL_TAC "offset_darts") THENL
     [MATCH_ACCEPT_TAC
       (SPECL [`q:num->A`; `n:num`; `k:num`] CYCLIC_DARTS_OFFSET);
      ALL_TAC] THEN
    SUBGOAL_THEN
     `((\i. (q:num->A) ((i + k) MOD n)) 0,
       (\i. q((i + k) MOD n)) 1) IN
      cyclic_darts (\i. q((i + k) MOD n)) n`
    (LABEL_TAC "offset_dart") THENL
     [REWRITE_TAC[IN_CYCLIC_DARTS] THEN
      EXISTS_TAC `0` THEN
      CONJ_TAC THENL
       [ASM_ARITH_TAC;
        BETA_TAC THEN REWRITE_TAC[ADD_CLAUSES] THEN
        USE_THEN "one_mod" (fun th -> REWRITE_TAC[th])];
      ALL_TAC] THEN
    USE_THEN "boundary_face" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "offset_darts" (fun th ->
     USE_THEN "offset_dart" (ACCEPT_TAC o REWRITE_RULE[th]));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face E (r:(A#A)->A#A)
      ((\i. (q:num->A) ((i + k) MOD n)) 0,
       (\i. q((i + k) MOD n)) 1) =
    graph_face E r (q 0,q 1)`
  (LABEL_TAC "same_face") THENL
   [SUBGOAL_THEN
     `(graph_face E (r:(A#A)->A#A)
        ((\i. (q:num->A) ((i + k) MOD n)) 0,
         (\i. q((i + k) MOD n)) 1) =
       graph_face E r (q 0,q 1) <=>
       ((\i. (q:num->A) ((i + k) MOD n)) 0,
        (\i. q((i + k) MOD n)) 1) IN
       graph_face E r (q 0,q 1))`
    (LABEL_TAC "face_eq_iff") THENL
     [USE_THEN "graph" (fun gth ->
       USE_THEN "rotation" (fun rth ->
        USE_THEN "base_dart" (fun dth ->
         ACCEPT_TAC
          (MATCH_MP
           (ISPECL
            [`V:A->bool`; `E:(A->bool)->bool`;
             `r:(A#A)->A#A`; `((q:num->A) 0,q 1)`;
             `(((\i. (q:num->A) ((i + k) MOD n)) 0),
               ((\i. q((i + k) MOD n)) 1))`]
            GRAPH_FACE_EQ)
           (CONJ gth (CONJ rth dth))))));
      ALL_TAC] THEN
    USE_THEN "face_eq_iff"
     (MATCH_MP_TAC o snd o EQ_IMP_RULE) THEN
    USE_THEN "offset_in_face" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[boundary_euler_rotation] THEN
  CONJ_TAC THENL
   [USE_THEN "euler" ACCEPT_TAC;
    BETA_TAC THEN
    USE_THEN "same_face" (fun th -> REWRITE_TAC[BETA_RULE th]) THEN
    USE_THEN "boundary_face" (fun th -> REWRITE_TAC[th]) THEN
    CONV_TAC SYM_CONV THEN
    MATCH_ACCEPT_TAC
     (SPECL [`q:num->A`; `n:num`; `k:num`] CYCLIC_DARTS_OFFSET)]);;

let BOUNDARY_EULER_ROTATION_CHORDLESS_LAST_OFFSET = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A.
        boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        connected_graph V E /\
        3 <= CARD V
        ==> ?w:num->A.
              boundary_euler_rotation V E w n r /\
              simple_graph_cycle E w n /\
              (!j. 0 < j /\ j + 2 < n
                   ==> ~({w j,w(n - 1)} IN E)) /\
              cyclic_darts w n = cyclic_darts q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "boundary cycle connected vertices_large" THEN
  USE_THEN "cycle" (MP_TAC o REWRITE_RULE[simple_graph_cycle]) THEN
  INTRO_TAC "nlarge injective cycle_edges" THEN
  ASM_CASES_TAC
   `?l. ?w:num->A.
          boundary_euler_rotation V E w n r /\
          simple_graph_cycle E w n /\
          cyclic_darts w n = cyclic_darts q n /\
          1 < l /\ l + 1 < n /\ {w 0,w l} IN E` THENL
   [FIRST_X_ASSUM(LABEL_TAC "some_chord");
    FIRST_X_ASSUM(LABEL_TAC "no_chord") THEN
    EXISTS_TAC `q:num->A` THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "boundary" ACCEPT_TAC;
      USE_THEN "cycle" ACCEPT_TAC;
      X_GEN_TAC `j:num` THEN INTRO_TAC "j_positive j_before_last" THEN
      DISCH_THEN(LABEL_TAC "edge") THEN
      USE_THEN "no_chord" (MATCH_MP_TAC o NOT_ELIM) THEN
      EXISTS_TAC `n - 1 - j:num` THEN
      ABBREV_TAC
       `w:num->A = \h. (q:num->A) ((h + j) MOD n)` THEN
      EXISTS_TAC `w:num->A` THEN
      SUBGOAL_THEN
       `boundary_euler_rotation V E (w:num->A) n r`
      (LABEL_TAC "w_boundary") THENL
       [EXPAND_TAC "w" THEN
        MATCH_MP_TAC BOUNDARY_EULER_ROTATION_OFFSET THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `simple_graph_cycle E (w:num->A) n`
      (LABEL_TAC "w_cycle") THENL
       [EXPAND_TAC "w" THEN
        MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_OFFSET THEN
        USE_THEN "cycle" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `cyclic_darts (w:num->A) n = cyclic_darts q n`
      (LABEL_TAC "w_darts") THENL
       [EXPAND_TAC "w" THEN
        MATCH_ACCEPT_TAC
         (SPECL [`q:num->A`; `n:num`; `j:num`] CYCLIC_DARTS_OFFSET);
        ALL_TAC] THEN
      SUBGOAL_THEN `(w:num->A) 0 = (q:num->A) j`
      (LABEL_TAC "w_first") THENL
       [EXPAND_TAC "w" THEN
        BETA_TAC THEN AP_TERM_TAC THEN
        REWRITE_TAC[ADD_CLAUSES] THEN
        MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(w:num->A) (n - 1 - j) = q(n - 1)`
      (LABEL_TAC "w_last") THENL
       [EXPAND_TAC "w" THEN
        SUBGOAL_THEN `(n:num) - 1 - j + j = n - 1`
        (LABEL_TAC "index") THENL
         [ASM_ARITH_TAC;
          ALL_TAC] THEN
        BETA_TAC THEN AP_TERM_TAC THEN
        USE_THEN "index" (fun th -> REWRITE_TAC[th]) THEN
        MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      REFL_TAC]] THEN
  USE_THEN "some_chord" (fun sth ->
   MP_TAC
    (MATCH_MP
      (fst(EQ_IMP_RULE
        (BETA_RULE(ISPEC
          `\l:num.
             ?w:num->A.
               boundary_euler_rotation V E w n r /\
               simple_graph_cycle E w n /\
               cyclic_darts w n = cyclic_darts q n /\
               1 < l /\ l + 1 < n /\ {w 0,w l} IN E`
          num_WOP))))
      sth)) THEN
  INTRO_TAC
   "@l. (@w. w_boundary w_cycle w_darts l_large l_before_n chord) \
    minimal" THEN
  SUBGOAL_THEN
   `!t. 2 < t /\ t < n ==> ~({(w:num->A) 1,w t} IN E)`
  (LABEL_TAC "next_chordless") THENL
   [X_GEN_TAC `t:num` THEN INTRO_TAC "t_large t_index" THEN
    DISCH_THEN(LABEL_TAC "edge") THEN
    ASM_CASES_TAC `(t:num) <= l` THENL
     [USE_THEN "minimal" (MP_TAC o SPEC `t - 1:num`) THEN
      ANTS_TAC THENL
       [ASM_ARITH_TAC;
        DISCH_THEN(MATCH_MP_TAC o NOT_ELIM)] THEN
      ABBREV_TAC
       `u:num->A = \h. (w:num->A) ((h + 1) MOD n)` THEN
      EXISTS_TAC `u:num->A` THEN
      SUBGOAL_THEN
       `boundary_euler_rotation V E (u:num->A) n r`
      (LABEL_TAC "u_boundary") THENL
       [EXPAND_TAC "u" THEN
        MATCH_MP_TAC BOUNDARY_EULER_ROTATION_OFFSET THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `simple_graph_cycle E (u:num->A) n`
      (LABEL_TAC "u_cycle") THENL
       [EXPAND_TAC "u" THEN
        MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_OFFSET THEN
        USE_THEN "w_cycle" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `cyclic_darts (u:num->A) n = cyclic_darts q n`
      (LABEL_TAC "u_darts") THENL
       [TRANS_TAC EQ_TRANS `cyclic_darts (w:num->A) n` THEN
        CONJ_TAC THENL
         [EXPAND_TAC "u" THEN
          MATCH_ACCEPT_TAC
           (SPECL [`w:num->A`; `n:num`; `1`] CYCLIC_DARTS_OFFSET);
          USE_THEN "w_darts" ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `(u:num->A) 0 = w 1`
      (LABEL_TAC "u_first") THENL
       [EXPAND_TAC "u" THEN
        BETA_TAC THEN AP_TERM_TAC THEN
        REWRITE_TAC[ADD_CLAUSES] THEN
        MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(u:num->A) (t - 1) = w t`
      (LABEL_TAC "u_last") THENL
       [EXPAND_TAC "u" THEN
        SUBGOAL_THEN `(t:num) - 1 + 1 = t`
        (LABEL_TAC "index") THENL
         [ASM_ARITH_TAC;
          ALL_TAC] THEN
        BETA_TAC THEN AP_TERM_TAC THEN
        USE_THEN "index" (fun th -> REWRITE_TAC[th]) THEN
        MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `w:num->A`; `n:num`;
        `r:(A#A)->A#A`; `1`; `l:num`; `t:num`]
       BOUNDARY_EULER_ROTATION_NO_ALTERNATING_CHORDS) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [USE_THEN "w_boundary" ACCEPT_TAC;
          USE_THEN "w_cycle" ACCEPT_TAC;
          USE_THEN "connected" ACCEPT_TAC;
          USE_THEN "vertices_large" ACCEPT_TAC;
          ASM_ARITH_TAC;
          ASM_ARITH_TAC;
          ASM_ARITH_TAC;
          USE_THEN "t_index" ACCEPT_TAC];
          DISCH_THEN(LABEL_TAC "no_alternating") THEN
          USE_THEN "no_alternating" MP_TAC THEN
          USE_THEN "chord" MP_TAC THEN
          USE_THEN "edge" MP_TAC THEN
          ITAUT_TAC]];
    ALL_TAC] THEN
  ABBREV_TAC `z:num->A = \h. (w:num->A) ((h + 2) MOD n)` THEN
  SUBGOAL_THEN `boundary_euler_rotation V E (z:num->A) n r`
  (LABEL_TAC "z_boundary") THENL
   [EXPAND_TAC "z" THEN
    MATCH_MP_TAC BOUNDARY_EULER_ROTATION_OFFSET THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `simple_graph_cycle E (z:num->A) n`
  (LABEL_TAC "z_cycle") THENL
   [EXPAND_TAC "z" THEN
    MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_OFFSET THEN
    USE_THEN "w_cycle" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `2 MOD n = 2` (LABEL_TAC "two_mod") THENL
   [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `((n:num) - 1 + 2) MOD n = 1`
  (LABEL_TAC "last_offset") THENL
   [SUBGOAL_THEN `(n:num) - 1 + 2 = n + 1`
    (LABEL_TAC "split") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "split" (fun th -> REWRITE_TAC[th]) THEN
    TRANS_TAC EQ_TRANS `1 MOD n` THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`1`; `n:num`; `1`] (CONJUNCT1 MOD_MULT_ADD)) THEN
      REWRITE_TAC[MULT_CLAUSES];
      MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(z:num->A) (n - 1) = w 1`
  (LABEL_TAC "z_last") THENL
   [EXPAND_TAC "z" THEN BETA_TAC THEN
    USE_THEN "last_offset" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  EXISTS_TAC `z:num->A` THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "z_boundary" ACCEPT_TAC;
    USE_THEN "z_cycle" ACCEPT_TAC;
    X_GEN_TAC `j:num` THEN INTRO_TAC "j_positive j_before_last" THEN
    SUBGOAL_THEN `(z:num->A) j = w(j + 2)`
    (LABEL_TAC "z_value") THENL
     [EXPAND_TAC "z" THEN
      BETA_TAC THEN AP_TERM_TAC THEN
      MATCH_MP_TAC MOD_LT THEN
      USE_THEN "j_before_last" ACCEPT_TAC;
      ALL_TAC] THEN
    DISCH_THEN(LABEL_TAC "edge") THEN
    USE_THEN "next_chordless" (MP_TAC o SPEC `j + 2:num`) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      DISCH_THEN(LABEL_TAC "forbidden") THEN
      SUBGOAL_THEN `{(w:num->A) (j + 2),w 1} IN E`
      (LABEL_TAC "reversed_edge") THENL
       [USE_THEN "edge" MP_TAC THEN
        USE_THEN "z_value" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "z_last" (fun th -> REWRITE_TAC[th]);
        ALL_TAC] THEN
      SUBGOAL_THEN `{(w:num->A) 1,w(j + 2)} IN E`
      (LABEL_TAC "oriented_edge") THENL
       [USE_THEN "reversed_edge" (fun eth ->
         ACCEPT_TAC
          (REWRITE_RULE
            [SYM(SPECL [`(w:num->A) 1`; `(w:num->A) (j + 2)`]
              PAIR_SET_SYM)]
            eth));
        ALL_TAC] THEN
      USE_THEN "forbidden" (fun nth ->
       USE_THEN "oriented_edge" (fun eth ->
        ACCEPT_TAC(MP (NOT_ELIM nth) eth)))];
    TRANS_TAC EQ_TRANS `cyclic_darts (w:num->A) n` THEN
    CONJ_TAC THENL
     [EXPAND_TAC "z" THEN
      MATCH_ACCEPT_TAC
       (SPECL [`w:num->A`; `n:num`; `2`] CYCLIC_DARTS_OFFSET);
      USE_THEN "w_darts" ACCEPT_TAC]]);;

(* ------------------------------------------------------------------------- *)
(* Recursive certificates from maximal Euler-planar boundary rotations.      *)
(* ------------------------------------------------------------------------- *)

let BOUNDARY_EULER_ROTATION_CYCLIC_DARTS_EQ = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q p:num->A. !n.
   !r:(A#A)->A#A.
        boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        simple_graph_cycle E p n /\
        cyclic_darts p n = cyclic_darts q n
        ==> boundary_euler_rotation V E p n r`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "boundary q_cycle p_cycle darts" THEN
  USE_THEN "boundary" MP_TAC THEN
  REWRITE_TAC[boundary_euler_rotation] THEN
  INTRO_TAC "euler q_face" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `3 <= n` (LABEL_TAC "large") THENL
   [USE_THEN "q_cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `((q:num->A) 0,q 1) IN graph_darts E`
  (LABEL_TAC "q_dart") THENL
   [SUBGOAL_THEN
    `cyclic_dart (q:num->A) n 0 = (q 0,q 1)`
    (LABEL_TAC "q_cyclic_dart") THENL
     [REWRITE_TAC[cyclic_dart; ADD_CLAUSES; PAIR_EQ] THEN
      AP_TERM_TAC THEN MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
      MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `q:num->A`; `n:num`; `0`]
       SIMPLE_GRAPH_CYCLE_CYCLIC_DART) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
       USE_THEN "q_cyclic_dart" (fun th -> REWRITE_TAC[th])]];
    ALL_TAC] THEN
  SUBGOAL_THEN `((p:num->A) 0,p 1) IN cyclic_darts p n`
  (LABEL_TAC "p_boundary_dart") THENL
   [REWRITE_TAC[IN_CYCLIC_DARTS] THEN
    EXISTS_TAC `0` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[ADD_CLAUSES; PAIR_EQ] THEN
      AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
      MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face E (r:(A#A)->A#A) ((p:num->A) 0,p 1) =
    graph_face E r (q 0,q 1)`
  (LABEL_TAC "same_face") THENL
   [MATCH_MP_TAC
     (snd(EQ_IMP_RULE
       (MATCH_MP
        (ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
          `((q:num->A) 0,q 1):A#A`; `((p:num->A) 0,p 1):A#A`]
         GRAPH_FACE_EQ)
        (CONJ
         (ASSUME `finite_simple_graph (V:A->bool) E`)
         (CONJ
          (ASSUME `graph_rotation E (r:(A#A)->A#A)`)
          (ASSUME `((q:num->A) 0,q 1) IN graph_darts E`)))))) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "q_face" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "darts" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "p_boundary_dart" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[boundary_euler_rotation] THEN
  CONJ_TAC THENL
   [USE_THEN "euler" ACCEPT_TAC;
    USE_THEN "same_face" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "q_face" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "darts" (fun th -> REWRITE_TAC[th])]);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_OFFSET = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A. !k.
        maximal_boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n
        ==> maximal_boundary_euler_rotation
             V E (\i. q((i + k) MOD n)) n r`,
  REPEAT GEN_TAC THEN INTRO_TAC "maximal cycle" THEN
  SUBGOAL_THEN
   `boundary_euler_rotation
     V E (\i. (q:num->A)((i + k) MOD n)) n r`
  (LABEL_TAC "offset_boundary") THENL
   [MATCH_MP_TAC BOUNDARY_EULER_ROTATION_OFFSET THEN
    USE_THEN "maximal" MP_TAC THEN
    REWRITE_TAC[maximal_boundary_euler_rotation] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle E (\i. (q:num->A)((i + k) MOD n)) n`
  (LABEL_TAC "offset_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_OFFSET THEN
    USE_THEN "cycle" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_darts (\i. (q:num->A)((i + k) MOD n)) n =
    cyclic_darts q n`
  (LABEL_TAC "offset_darts") THENL
   [MATCH_ACCEPT_TAC
     (SPECL [`q:num->A`; `n:num`; `k:num`] CYCLIC_DARTS_OFFSET);
    ALL_TAC] THEN
  REWRITE_TAC[maximal_boundary_euler_rotation] THEN
  CONJ_TAC THENL
   [USE_THEN "offset_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC
   [`E':(A->bool)->bool`; `s:(A#A)->A#A`] THEN
  INTRO_TAC "proper allowed" THEN
  DISCH_THEN(LABEL_TAC "larger_offset_boundary") THEN
  SUBGOAL_THEN `simple_graph_cycle E' (q:num->A) n`
  (LABEL_TAC "larger_q_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_MONO THEN
    EXISTS_TAC `E:(A->bool)->bool` THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "proper"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[PSUBSET]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle E' (\i. (q:num->A)((i + k) MOD n)) n`
  (LABEL_TAC "larger_offset_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_MONO THEN
    EXISTS_TAC `E:(A->bool)->bool` THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "proper"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[PSUBSET]);
    ALL_TAC] THEN
  SUBGOAL_THEN `boundary_euler_rotation V E' (q:num->A) n s`
  (LABEL_TAC "larger_q_boundary") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E':(A->bool)->bool`;
      `(\i. (q:num->A)((i + k) MOD n)):num->A`;
      `q:num->A`; `n:num`; `s:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_CYCLIC_DARTS_EQ) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "offset_darts" (ACCEPT_TAC o SYM);
    ALL_TAC] THEN
  USE_THEN "maximal" MP_TAC THEN
  REWRITE_TAC[maximal_boundary_euler_rotation] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
   (LABEL_TAC "old_maximal")) THEN
  REMOVE_THEN "old_maximal" (fun th ->
   MP_TAC(MATCH_MP
    (SPECL [`E':(A->bool)->bool`; `s:(A#A)->A#A`] th)
    (CONJ
     (ASSUME `E PSUBSET (E':(A->bool)->bool)`)
     (ASSUME
      `(E':(A->bool)->bool) SUBSET complete_graph_edges (V:A->bool)`)))) THEN
  ASM_REWRITE_TAC[]);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_CYCLIC_DARTS_EQ = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q p:num->A. !n.
   !r:(A#A)->A#A.
        maximal_boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        boundary_euler_rotation V E p n r /\
        simple_graph_cycle E p n /\
        cyclic_darts p n = cyclic_darts q n
        ==> maximal_boundary_euler_rotation V E p n r`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "maximal q_cycle p_boundary p_cycle darts" THEN
  REWRITE_TAC[maximal_boundary_euler_rotation] THEN
  CONJ_TAC THENL
   [USE_THEN "p_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC
   [`E':(A->bool)->bool`; `s:(A#A)->A#A`] THEN
  INTRO_TAC "proper allowed" THEN
  DISCH_THEN(LABEL_TAC "larger_p_boundary") THEN
  SUBGOAL_THEN `simple_graph_cycle E' (q:num->A) n`
  (LABEL_TAC "larger_q_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_MONO THEN
    EXISTS_TAC `E:(A->bool)->bool` THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "proper"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[PSUBSET]);
    ALL_TAC] THEN
  SUBGOAL_THEN `simple_graph_cycle E' (p:num->A) n`
  (LABEL_TAC "larger_p_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_MONO THEN
    EXISTS_TAC `E:(A->bool)->bool` THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "proper"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[PSUBSET]);
    ALL_TAC] THEN
  SUBGOAL_THEN `boundary_euler_rotation V E' (q:num->A) n s`
  (LABEL_TAC "larger_q_boundary") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E':(A->bool)->bool`; `p:num->A`;
      `q:num->A`; `n:num`; `s:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_CYCLIC_DARTS_EQ) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "darts" (ACCEPT_TAC o SYM);
    ALL_TAC] THEN
  USE_THEN "maximal" MP_TAC THEN
  REWRITE_TAC[maximal_boundary_euler_rotation] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
   (LABEL_TAC "old_maximal")) THEN
  REMOVE_THEN "old_maximal" (fun th ->
   MP_TAC(MATCH_MP
    (SPECL [`E':(A->bool)->bool`; `s:(A#A)->A#A`] th)
    (CONJ
     (ASSUME `E PSUBSET (E':(A->bool)->bool)`)
     (ASSUME
      `(E':(A->bool)->bool) SUBSET complete_graph_edges (V:A->bool)`)))) THEN
  ASM_REWRITE_TAC[]);;

let CONNECTED_GRAPH_CYCLE_EXTERNAL_NEIGHBOR = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
        finite_simple_graph V E /\
        connected_graph V E /\
        simple_graph_cycle E q n /\
        cyclic_vertices q n PSUBSET V
        ==> ?i x.
              i < n /\
              x IN V DIFF cyclic_vertices q n /\
              {q i,x} IN E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph connected cycle proper" THEN
  SUBGOAL_THEN `cyclic_vertices (q:num->A) n SUBSET V`
  (LABEL_TAC "cycle_subset") THENL
   [ACCEPT_TAC(MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`]
      FINITE_SIMPLE_GRAPH_CYCLE_VERTICES_SUBSET)
     (CONJ
      (ASSUME `finite_simple_graph (V:A->bool) E`)
      (ASSUME `simple_graph_cycle E (q:num->A) n`)));
    ALL_TAC] THEN
  SUBGOAL_THEN `3 <= n` (LABEL_TAC "large") THENL
   [USE_THEN "cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:num->A) 0 IN cyclic_vertices q n`
  (LABEL_TAC "root") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `0` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(cyclic_vertices (q:num->A) n = V)`
  (LABEL_TAC "cycle_not_all") THENL
   [USE_THEN "proper" MP_TAC THEN
    REWRITE_TAC[PSUBSET] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`V:A->bool`; `E:(A->bool)->bool`;
     `cyclic_vertices (q:num->A) n`; `(q:num->A) 0`]
    CONNECTED_GRAPH_CROSSING_EDGE)
   (end_itlist CONJ
    [ASSUME `finite_simple_graph (V:A->bool) E`;
     ASSUME `connected_graph (V:A->bool) E`;
     ASSUME `cyclic_vertices (q:num->A) n SUBSET V`;
     ASSUME `(q:num->A) 0 IN cyclic_vertices q n`;
     ASSUME `~(cyclic_vertices (q:num->A) n = V)`])) THEN
  INTRO_TAC "@x y. x_external y_cycle edge" THEN
  USE_THEN "y_cycle" MP_TAC THEN
  REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
  INTRO_TAC "@i. index y_value" THEN
  MAP_EVERY EXISTS_TAC [`i:num`; `x:A`] THEN
  ASM_REWRITE_TAC[] THEN
  REMOVE_THEN "y_value" (fun yth ->
   REMOVE_THEN "edge" (fun eth ->
    ACCEPT_TAC
     (REWRITE_RULE[yth] (ONCE_REWRITE_RULE[PAIR_SET_SYM] eth)))));;

let CONNECTED_GRAPH_TRIANGLE_HIGH_DEGREE_VERTEX = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A.
        finite_simple_graph V E /\
        connected_graph V E /\
        simple_graph_cycle E q 3 /\
        3 < CARD V
        ==> ?i. i < 3 /\ 3 <= CARD(graph_neighbors E (q i))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph connected cycle vertices_large" THEN
  SUBGOAL_THEN `cyclic_vertices (q:num->A) 3 SUBSET V`
  (LABEL_TAC "cycle_subset") THENL
   [ACCEPT_TAC(MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `3`]
      FINITE_SIMPLE_GRAPH_CYCLE_VERTICES_SUBSET)
     (CONJ
      (ASSUME `finite_simple_graph (V:A->bool) E`)
      (ASSUME `simple_graph_cycle E (q:num->A) 3`)));
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(cyclic_vertices (q:num->A) 3) = 3`
  (LABEL_TAC "cycle_card") THENL
   [MATCH_MP_TAC CARD_CYCLIC_VERTICES THEN
    USE_THEN "cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(cyclic_vertices (q:num->A) 3 = V)`
  (LABEL_TAC "cycle_not_all") THENL
   [DISCH_THEN(LABEL_TAC "all_vertices") THEN
    REMOVE_THEN "all_vertices" (fun th ->
     MP_TAC(AP_TERM `CARD:(A->bool)->num` th)) THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `cyclic_vertices (q:num->A) 3 PSUBSET V`
  (LABEL_TAC "proper") THENL
   [REWRITE_TAC[PSUBSET] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `3`]
   CONNECTED_GRAPH_CYCLE_EXTERNAL_NEIGHBOR) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@i x. index x_external edge" THEN
  SUBGOAL_THEN
   `(q:num->A) i IN cyclic_vertices q 3`
  (LABEL_TAC "qi_cycle") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_vertices (q:num->A) 3 DELETE q i
    SUBSET graph_neighbors E (q i)`
  (LABEL_TAC "other_neighbors") THENL
   [REWRITE_TAC[SUBSET; IN_DELETE] THEN
    X_GEN_TAC `u:A` THEN INTRO_TAC "u_cycle u_distinct" THEN
    REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `q:num->A`; `(q:num->A) i`; `u:A`]
     TRIANGULAR_SIMPLE_GRAPH_CYCLE_CLIQUE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(x:A) IN graph_neighbors E ((q:num->A) i)`
  (LABEL_TAC "x_neighbor") THENL
   [REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
    USE_THEN "edge" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `x INSERT (cyclic_vertices (q:num->A) 3 DELETE q i)
    SUBSET graph_neighbors E (q i)`
  (LABEL_TAC "three_subset") THENL
   [REWRITE_TAC[INSERT_SUBSET] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(cyclic_vertices (q:num->A) 3 DELETE q i) = 2`
  (LABEL_TAC "other_card") THENL
   [ASM_SIMP_TAC[CARD_DELETE; FINITE_CYCLIC_VERTICES] THEN
    ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((x:A) IN cyclic_vertices (q:num->A) 3 DELETE q i)`
  (LABEL_TAC "x_new") THENL
   [USE_THEN "x_external" MP_TAC THEN
    REWRITE_TAC[IN_DIFF; IN_DELETE] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(x INSERT (cyclic_vertices (q:num->A) 3 DELETE q i)) = 3`
  (LABEL_TAC "three_card") THENL
   [ASM_SIMP_TAC[CARD_CLAUSES; FINITE_DELETE;
                 FINITE_CYCLIC_VERTICES] THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL
   [`x INSERT (cyclic_vertices (q:num->A) 3 DELETE q i):A->bool`;
    `graph_neighbors (E:(A->bool)->bool) ((q:num->A) i)`]
   CARD_SUBSET) THEN
  ASM_REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [ACCEPT_TAC(MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `(q:num->A) i`]
      FINITE_GRAPH_NEIGHBORS)
     (ASSUME `finite_simple_graph (V:A->bool) E`));
    DISCH_THEN ACCEPT_TAC]);;

let TRIANGLE_OFFSET_LAST = prove
 (`!i:num. i < 3 ==> (2 + (i + 1)) MOD 3 = i`,
