   [ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  ASM_CASES_TAC `(i:num) = 1` THENL
   [ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `(i:num) = 2` SUBST1_TAC THENL
   [ASM_ARITH_TAC;
    CONV_TAC NUM_REDUCE_CONV]);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_TRIANGLE_HIGH_DEGREE_LAST = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A.
  !r:(A#A)->A#A.
        maximal_boundary_euler_rotation V E q 3 r /\
        simple_graph_cycle E q 3 /\
        connected_graph V E /\
        3 < CARD V
        ==> ?p:num->A.
              maximal_boundary_euler_rotation V E p 3 r /\
              simple_graph_cycle E p 3 /\
              cyclic_darts p 3 = cyclic_darts q 3 /\
              3 <= CARD(graph_neighbors E (p 2))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "maximal cycle connected vertices_large" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "maximal" MP_TAC THEN
    REWRITE_TAC[maximal_boundary_euler_rotation;
                boundary_euler_rotation; euler_planar_rotation] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`]
   CONNECTED_GRAPH_TRIANGLE_HIGH_DEGREE_VERTEX) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@i. index degree" THEN
  ABBREV_TAC
   `p:num->A = \h. (q:num->A)((h + (i + 1)) MOD 3)` THEN
  SUBGOAL_THEN
   `maximal_boundary_euler_rotation V E (p:num->A) 3 r`
  (LABEL_TAC "p_maximal") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC MAXIMAL_BOUNDARY_EULER_ROTATION_OFFSET THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `simple_graph_cycle E (p:num->A) 3`
  (LABEL_TAC "p_cycle") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_OFFSET THEN
    USE_THEN "cycle" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `cyclic_darts (p:num->A) 3 = cyclic_darts q 3`
  (LABEL_TAC "p_darts") THENL
   [EXPAND_TAC "p" THEN
    MATCH_ACCEPT_TAC CYCLIC_DARTS_OFFSET;
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:num->A) 2 = (q:num->A) (i:num)`
  (LABEL_TAC "p_last") THENL
   [EXPAND_TAC "p" THEN BETA_TAC THEN AP_TERM_TAC THEN
    MATCH_MP_TAC TRIANGLE_OFFSET_LAST THEN
    USE_THEN "index" ACCEPT_TAC;
    ALL_TAC] THEN
  EXISTS_TAC `p:num->A` THEN
  ASM_REWRITE_TAC[]);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_DELETE_EAR = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A.
        maximal_boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        connected_graph V E /\
        3 < CARD V
        ==> ?p:num->A. ?k:num. ?w:num->A. ?s:(A#A)->A#A.
              maximal_boundary_euler_rotation V E p n r /\
              simple_graph_cycle E p n /\
              cyclic_darts p n = cyclic_darts q n /\
              (!j. 0 < j /\ j + 2 < n
                   ==> ~({p j,p(n - 1)} IN E)) /\
              CARD(graph_neighbors E (p(n - 1))) = k + 2 /\
              graph_neighbors E (p(n - 1)) =
                cyclic_vertices w (k + 2) /\
              INJ w (cyclic_indices (k + 2)) (:A) /\
              w 0 = p(n - 2) /\
              w(k + 1) = p 0 /\
              (!i. i + 1 < k + 2
                   ==> {w i,w(i + 1)} IN E) /\
              simple_graph_cycle
               (induced_subgraph_edges E (V DELETE p(n - 1)))
               (cyclic_delete_last p w n) (n - 1 + k) /\
              connected_graph
               (V DELETE p(n - 1))
               (induced_subgraph_edges E (V DELETE p(n - 1))) /\
              maximal_boundary_euler_rotation
               (V DELETE p(n - 1))
               (induced_subgraph_edges E (V DELETE p(n - 1)))
               (cyclic_delete_last p w n) (n - 1 + k) s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "maximal cycle connected vertices_large" THEN
  SUBGOAL_THEN `3 <= n` (LABEL_TAC "nlarge") THENL
   [USE_THEN "cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `3 <= CARD(V:A->bool)`
  (LABEL_TAC "card_large") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `(n:num) = 3` THENL
   [FIRST_X_ASSUM(LABEL_TAC "n_three") THEN
    USE_THEN "n_three" SUBST_ALL_TAC THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
      `r:(A#A)->A#A`]
     MAXIMAL_BOUNDARY_EULER_ROTATION_TRIANGLE_HIGH_DEGREE_LAST) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      INTRO_TAC "@p. p_maximal p_cycle p_darts p_degree"] THEN
    SUBGOAL_THEN
     `!j. 0 < j /\ j + 2 < 3
          ==> ~({(p:num->A) j,p(3 - 1)} IN E)`
    (LABEL_TAC "p_chordless") THENL
     [X_GEN_TAC `j:num` THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:num->A`;
      `3`; `r:(A#A)->A#A`]
     MAXIMAL_BOUNDARY_EULER_ROTATION_DELETE_LAST_CHORDLESS_INTERNAL) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      INTRO_TAC
       "@k w s. length neighbors injective first last chain \
        new_cycle new_connected new_maximal"] THEN
    MAP_EVERY EXISTS_TAC
     [`p:num->A`; `k:num`; `w:num->A`; `s:(A#A)->A#A`] THEN
    ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "n_not_three") THEN
    SUBGOAL_THEN `4 <= n` (LABEL_TAC "n_four") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `boundary_euler_rotation V E (q:num->A) n r`
    (LABEL_TAC "boundary") THENL
     [MATCH_MP_TAC MAXIMAL_BOUNDARY_EULER_ROTATION_IMP_BOUNDARY THEN
      USE_THEN "maximal" ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
      `n:num`; `r:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_CHORDLESS_LAST_OFFSET) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@p. p_boundary p_cycle p_chordless p_darts" THEN
    SUBGOAL_THEN
     `maximal_boundary_euler_rotation V E (p:num->A) n r`
    (LABEL_TAC "p_maximal") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
        `p:num->A`; `n:num`; `r:(A#A)->A#A`]
       MAXIMAL_BOUNDARY_EULER_ROTATION_CYCLIC_DARTS_EQ) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:num->A`;
      `n:num`; `r:(A#A)->A#A`]
     MAXIMAL_BOUNDARY_EULER_ROTATION_DELETE_LAST_CHORDLESS_INTERNAL) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN DISJ1_TAC THEN
      USE_THEN "n_four" ACCEPT_TAC;
      INTRO_TAC
       "@k w s. length neighbors injective first last chain \
        new_cycle new_connected new_maximal"] THEN
    MAP_EVERY EXISTS_TAC
     [`p:num->A`; `k:num`; `w:num->A`; `s:(A#A)->A#A`] THEN
    ASM_REWRITE_TAC[]]);;

let SIMPLE_GRAPH_CYCLE_CYCLIC_DARTS_EQ_OFFSET = prove
 (`!E:(A->bool)->bool. !q p:num->A. !n.
        simple_graph_cycle E q n /\
        simple_graph_cycle E p n /\
        cyclic_darts p n = cyclic_darts q n
        ==> ?k. k < n /\
                !i. i < n ==> q i = p((i + k) MOD n)`,
  REPEAT GEN_TAC THEN INTRO_TAC "q_cycle p_cycle darts" THEN
  SUBGOAL_THEN `3 <= n` (LABEL_TAC "large") THENL
   [USE_THEN "q_cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (q:num->A) (cyclic_indices n) (:A)`
  (LABEL_TAC "q_injective") THENL
   [USE_THEN "q_cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (p:num->A) (cyclic_indices n) (:A)`
  (LABEL_TAC "p_injective") THENL
   [USE_THEN "p_cycle" MP_TAC THEN
    REWRITE_TAC[simple_graph_cycle] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `((q:num->A) 0,q 1) IN cyclic_darts p n`
  (LABEL_TAC "first_dart") THENL
   [USE_THEN "darts" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_CYCLIC_DARTS] THEN
    EXISTS_TAC `0` THEN CONJ_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[ADD_CLAUSES; PAIR_EQ] THEN
      AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
      MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  USE_THEN "first_dart" MP_TAC THEN
  REWRITE_TAC[IN_CYCLIC_DARTS; PAIR_EQ] THEN
  INTRO_TAC "@k. k_index q0 q1" THEN
  EXISTS_TAC `k:num` THEN ASM_REWRITE_TAC[] THEN
  INDUCT_TAC THENL
   [DISCH_THEN(LABEL_TAC "positive") THEN
    REWRITE_TAC[ADD_CLAUSES] THEN
    USE_THEN "q0" (fun th -> REWRITE_TAC[th]) THEN
    AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC MOD_LT THEN USE_THEN "k_index" ACCEPT_TAC;
    FIRST_X_ASSUM(LABEL_TAC "induction") THEN
    DISCH_THEN(LABEL_TAC "successor_index") THEN
    SUBGOAL_THEN `(i:num) < n` (LABEL_TAC "index") THENL
     [USE_THEN "successor_index" MP_TAC THEN ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `q i = (p:num->A)((i + k) MOD n)`
    (LABEL_TAC "ih") THENL
     [USE_THEN "induction" MATCH_MP_TAC THEN
      USE_THEN "index" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `((q:num->A) i,q(SUC i)) IN cyclic_darts p n`
    (LABEL_TAC "next_dart") THENL
     [USE_THEN "darts" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_CYCLIC_DARTS] THEN
      EXISTS_TAC `i:num` THEN CONJ_TAC THENL
       [USE_THEN "index" ACCEPT_TAC;
        REWRITE_TAC[PAIR_EQ] THEN AP_TERM_TAC THEN
        REWRITE_TAC[ADD1] THEN CONV_TAC SYM_CONV THEN
        MATCH_MP_TAC MOD_LT THEN
        USE_THEN "successor_index" MP_TAC THEN REWRITE_TAC[ADD1]];
      ALL_TAC] THEN
    USE_THEN "next_dart" MP_TAC THEN
    REWRITE_TAC[IN_CYCLIC_DARTS; PAIR_EQ] THEN
    INTRO_TAC "@h. h_index same_first next_value" THEN
    SUBGOAL_THEN `h = (i + k) MOD n` (LABEL_TAC "same_index") THENL
     [MATCH_MP_TAC
       (SPECL [`h:num`; `(i + k) MOD n`]
        (CONJUNCT2
         (REWRITE_RULE[INJ]
          (ASSUME `INJ (p:num->A) (cyclic_indices n) (:A)`)))) THEN
      REWRITE_TAC[IN_CYCLIC_INDICES] THEN
      CONJ_TAC THENL
       [USE_THEN "h_index" ACCEPT_TAC;
        ALL_TAC] THEN
      CONJ_TAC THENL
       [REWRITE_TAC[MOD_LT_EQ_LT] THEN ASM_ARITH_TAC;
        ACCEPT_TAC
         (TRANS
          (SYM(ASSUME `(q:num->A) i = (p:num->A) h`))
          (ASSUME
           `(q:num->A) i = (p:num->A) ((i + k) MOD n)`))];
      ALL_TAC] THEN
    USE_THEN "next_value" (fun th -> REWRITE_TAC[th]) THEN
    AP_TERM_TAC THEN
    USE_THEN "same_index" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[ADD1; MOD_ADD_LEFT_REDUCE; ADD_AC]]);;

let MAXIMAL_BOUNDARY_EULER_ROTATION_RECURSIVE_TRIANGULATED_DISK = prove
 (`!V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
   !r:(A#A)->A#A.
        maximal_boundary_euler_rotation V E q n r /\
        simple_graph_cycle E q n /\
        connected_graph V E
        ==> recursive_triangulated_disk V E q n`,
  SUBGOAL_THEN
   `!c. !V:A->bool. !E:(A->bool)->bool. !q:num->A. !n.
    !r:(A#A)->A#A.
         CARD V = c /\
         maximal_boundary_euler_rotation V E q n r /\
         simple_graph_cycle E q n /\
         connected_graph V E
         ==> recursive_triangulated_disk V E q n`
  (LABEL_TAC "card_induction") THENL
   [MATCH_MP_TAC num_WF THEN X_GEN_TAC `c:num` THEN
    DISCH_THEN(LABEL_TAC "induction") THEN
    REPEAT GEN_TAC THEN
    INTRO_TAC "card maximal cycle connected" THEN
    SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
    (LABEL_TAC "graph") THENL
     [USE_THEN "maximal" MP_TAC THEN
      REWRITE_TAC[maximal_boundary_euler_rotation;
                  boundary_euler_rotation; euler_planar_rotation] THEN
      MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `3 <= n` (LABEL_TAC "nlarge") THENL
     [USE_THEN "cycle" MP_TAC THEN
      REWRITE_TAC[simple_graph_cycle] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `INJ (q:num->A) (cyclic_indices n) (:A)`
    (LABEL_TAC "injective") THENL
     [USE_THEN "cycle" MP_TAC THEN
      REWRITE_TAC[simple_graph_cycle] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `cyclic_vertices (q:num->A) n SUBSET V`
    (LABEL_TAC "boundary_subset") THENL
     [USE_THEN "graph" (fun gth ->
       USE_THEN "cycle" (fun cth ->
        ACCEPT_TAC(MATCH_MP FINITE_SIMPLE_GRAPH_CYCLE_VERTICES_SUBSET
         (CONJ gth cth))));
      ALL_TAC] THEN
    SUBGOAL_THEN `CARD(cyclic_vertices (q:num->A) n) = n`
    (LABEL_TAC "boundary_card") THENL
     [USE_THEN "injective" (fun th ->
       ACCEPT_TAC(MATCH_MP CARD_CYCLIC_VERTICES th));
      ALL_TAC] THEN
    SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite_vertices") THENL
     [USE_THEN "graph"
       (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[finite_simple_graph]);
      ALL_TAC] THEN
    SUBGOAL_THEN `n <= CARD(V:A->bool)` (LABEL_TAC "n_le_card") THENL
     [USE_THEN "boundary_subset" (fun sth ->
       USE_THEN "finite_vertices" (fun fth ->
        MP_TAC(MATCH_MP CARD_SUBSET (CONJ sth fth)))) THEN
      USE_THEN "boundary_card" (fun th -> REWRITE_TAC[th]);
      ALL_TAC] THEN
    ASM_CASES_TAC `CARD(V:A->bool) <= 3` THENL
     [FIRST_X_ASSUM(LABEL_TAC "small") THEN
      SUBGOAL_THEN `(n:num) = 3` (LABEL_TAC "n_three") THENL
       [MAP_EVERY (fun s -> USE_THEN s MP_TAC)
         ["nlarge"; "n_le_card"; "small"] THEN ARITH_TAC;
        ALL_TAC] THEN
      USE_THEN "n_three" SUBST_ALL_TAC THEN
      SUBGOAL_THEN `CARD(V:A->bool) = 3`
      (LABEL_TAC "three_vertices") THENL
       [MAP_EVERY (fun s -> USE_THEN s MP_TAC)
         ["n_le_card"; "small"] THEN ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `V = cyclic_vertices (q:num->A) 3`
      (LABEL_TAC "all_vertices") THENL
       [USE_THEN "finite_vertices" (fun fth ->
        USE_THEN "boundary_subset" (fun sth ->
        USE_THEN "boundary_card" (fun bth ->
        USE_THEN "three_vertices" (fun vth ->
         ACCEPT_TAC
          (SYM(MATCH_MP CARD_SUBSET_EQ
           (CONJ fth (CONJ sth (TRANS bth (SYM vth))))))))));
        ALL_TAC] THEN
      MATCH_MP_TAC FINITE_SIMPLE_GRAPH_TRIANGULAR_CYCLE_RECURSIVE THEN
      ASM_REWRITE_TAC[];
      FIRST_X_ASSUM(LABEL_TAC "large_vertices") THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
        `r:(A#A)->A#A`]
       MAXIMAL_BOUNDARY_EULER_ROTATION_DELETE_EAR) THEN
      ASM_REWRITE_TAC[] THEN
      ANTS_TAC THENL
       [MAP_EVERY (fun s -> USE_THEN s MP_TAC)
         ["card"; "large_vertices"] THEN ARITH_TAC;
        ALL_TAC] THEN
      INTRO_TAC
       "@p k w s. p_maximal p_cycle p_darts p_chordless \
        neighbor_card neighbors w_injective first last chain \
        new_cycle new_connected new_maximal" THEN
      SUBGOAL_THEN `cyclic_vertices (p:num->A) n SUBSET V`
      (LABEL_TAC "p_boundary_subset") THENL
       [USE_THEN "graph" (fun gth ->
         USE_THEN "p_cycle" (fun cth ->
          ACCEPT_TAC(MATCH_MP FINITE_SIMPLE_GRAPH_CYCLE_VERTICES_SUBSET
           (CONJ gth cth))));
        ALL_TAC] THEN
      SUBGOAL_THEN `(p:num->A) (n - 1) IN V`
      (LABEL_TAC "last_vertex") THENL
       [USE_THEN "p_boundary_subset"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
        EXISTS_TAC `n - 1` THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `INJ (p:num->A) (cyclic_indices n) (:A)`
      (LABEL_TAC "p_injective") THENL
       [USE_THEN "p_cycle" MP_TAC THEN
        REWRITE_TAC[simple_graph_cycle] THEN MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `CARD(V DELETE (p:num->A)(n - 1)) < c`
      (LABEL_TAC "decreases") THENL
       [MP_TAC(ISPECL
         [`(p:num->A)(n - 1)`; `V:A->bool`] CARD_DELETE) THEN
        ASM_REWRITE_TAC[] THEN
        MAP_EVERY (fun s -> USE_THEN s MP_TAC)
         ["card"; "large_vertices"] THEN ARITH_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
