         (cyclic_delete_last p w n) (n - 1 + k)`
      (LABEL_TAC "child_recursive") THENL
       [USE_THEN "induction" (fun induction_th ->
         USE_THEN "decreases" (fun decreases_th ->
          MATCH_MP_TAC
           (SPECL
            [`V DELETE (p:num->A)(n - 1)`;
             `induced_subgraph_edges (E:(A->bool)->bool)
               (V DELETE p(n - 1))`;
             `cyclic_delete_last (p:num->A) w n`; `n - 1 + k`;
             `s:(A#A)->A#A`]
            (MATCH_MP
             (SPEC `CARD(V DELETE (p:num->A)(n - 1))` induction_th)
             decreases_th)))) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `recursive_triangulated_disk V E (p:num->A) n`
      (LABEL_TAC "p_recursive") THENL
       [MATCH_MP_TAC RECURSIVE_TRIANGULATED_DISK_DELETE_BOUNDARY_VERTEX THEN
        ASM_REWRITE_TAC[] THEN
        MAP_EVERY EXISTS_TAC [`k:num`; `w:num->A`] THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `q:num->A`; `p:num->A`; `n:num`]
       SIMPLE_GRAPH_CYCLE_CYCLIC_DARTS_EQ_OFFSET) THEN
      ASM_REWRITE_TAC[] THEN
      INTRO_TAC "@h. h_index agree" THEN
      SUBGOAL_THEN
       `recursive_triangulated_disk
         V E (\i. (p:num->A)((i + h) MOD n)) n`
      (LABEL_TAC "offset_recursive") THENL
       [MATCH_MP_TAC RECURSIVE_TRIANGULATED_DISK_OFFSET THEN
        USE_THEN "p_recursive" ACCEPT_TAC;
        ALL_TAC] THEN
      MATCH_MP_TAC RECURSIVE_TRIANGULATED_DISK_CONG THEN
      EXISTS_TAC `(\i. (p:num->A)((i + h) MOD n)):num->A` THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REPEAT GEN_TAC THEN INTRO_TAC "maximal cycle connected" THEN
  USE_THEN "card_induction"
   (MATCH_MP_TAC o SPECL
    [`CARD(V:A->bool)`; `V:A->bool`; `E:(A->bool)->bool`;
     `q:num->A`; `n:num`; `r:(A#A)->A#A`]) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* A maximal connected Euler rotation has an oriented triangular face.       *)
(* ------------------------------------------------------------------------- *)

let CONNECTED_GRAPH_TWO_DISTINCT_NEIGHBORS = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        finite_simple_graph V E /\
        connected_graph V E /\
        3 <= CARD V
        ==> ?u v w.
              v IN graph_neighbors E u /\
              w IN graph_neighbors E u /\
              ~(v = w)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected card" THEN
  SUBGOAL_THEN `~(V:A->bool = {})` (LABEL_TAC "nonempty") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "card" MP_TAC THEN
    REWRITE_TAC[CONJUNCT1 CARD_CLAUSES] THEN ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "nonempty" MP_TAC THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
  INTRO_TAC "@a. a_vertex" THEN
  SUBGOAL_THEN `{a:A} SUBSET V` (LABEL_TAC "a_subset") THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~({a:A} = V)` (LABEL_TAC "a_proper") THENL
   [DISCH_THEN(LABEL_TAC "all_a") THEN
    USE_THEN "card" MP_TAC THEN
    REMOVE_THEN "all_a"
     (fun th -> REWRITE_TAC[GSYM th; CARD_SING]) THEN
    ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `{a:A}`; `a:A`]
    CONNECTED_GRAPH_CROSSING_EDGE)
   (end_itlist CONJ
    [ASSUME `finite_simple_graph (V:A->bool) E`;
     ASSUME `connected_graph (V:A->bool) E`;
     ASSUME `{a:A} SUBSET V`;
     SET_RULE `(a:A) IN {a}`;
     ASSUME `~({a:A} = V)`])) THEN
  INTRO_TAC "@b y. b_outside y_singleton ba_edge" THEN
  SUBGOAL_THEN `(y:A) = a` SUBST_ALL_TAC THENL
   [USE_THEN "y_singleton" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(b:A) IN V /\ ~(b = a)`
   (CONJUNCTS_THEN2
    (LABEL_TAC "b_vertex") (LABEL_TAC "ba_distinct")) THENL
   [USE_THEN "b_outside" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{a:A,b} SUBSET V` (LABEL_TAC "ab_subset") THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~({a:A,b} = V)` (LABEL_TAC "ab_proper") THENL
   [DISCH_THEN(LABEL_TAC "all_ab") THEN
    USE_THEN "card" MP_TAC THEN
    REMOVE_THEN "all_ab" (fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_SIMP_TAC
     [CARD_CLAUSES; FINITE_SING; CARD_SING; IN_SING] THEN
    ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `{a:A,b}`; `a:A`]
    CONNECTED_GRAPH_CROSSING_EDGE)
   (end_itlist CONJ
    [ASSUME `finite_simple_graph (V:A->bool) E`;
     ASSUME `connected_graph (V:A->bool) E`;
     ASSUME `{a:A,b} SUBSET V`;
     SET_RULE `(a:A) IN {a,b}`;
     ASSUME `~({a:A,b} = V)`])) THEN
  INTRO_TAC "@c z. c_outside z_pair cz_edge" THEN
  USE_THEN "z_pair" MP_TAC THEN
  REWRITE_TAC[IN_INSERT; IN_SING] THEN
  DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
   [MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `c:A`] THEN
    REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
    CONJ_TAC THENL
     [ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
      USE_THEN "ba_edge" ACCEPT_TAC;
      CONJ_TAC THENL
       [ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
        USE_THEN "cz_edge" ACCEPT_TAC;
        USE_THEN "c_outside" MP_TAC THEN SET_TAC[]]];
    MAP_EVERY EXISTS_TAC [`b:A`; `a:A`; `c:A`] THEN
    REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
    CONJ_TAC THENL
     [USE_THEN "ba_edge" ACCEPT_TAC;
      CONJ_TAC THENL
       [ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
        USE_THEN "cz_edge" ACCEPT_TAC;
        USE_THEN "c_outside" MP_TAC THEN SET_TAC[]]]]);;

let MAXIMAL_EULER_PLANAR_ROTATION_TRIANGULAR_BOUNDARY = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        (!G s:(A#A)->A#A.
             E PSUBSET G /\
             G SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V G s) /\
        3 <= CARD V
        ==> ?q:num->A.
              maximal_boundary_euler_rotation V E q 3 r /\
              simple_graph_cycle E q 3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "euler connected maximal vertices_large" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
   (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`]
    CONNECTED_GRAPH_TWO_DISTINCT_NEIGHBORS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@u v t. v_neighbor t_neighbor vt_distinct" THEN
  SUBGOAL_THEN `(u:A,v) IN outgoing_darts E u`
   (LABEL_TAC "outgoing") THENL
   [REWRITE_TAC[IN_OUTGOING_DARTS_PAIR; GSYM IN_GRAPH_NEIGHBORS] THEN
    USE_THEN "v_neighbor" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `2 <= CARD(graph_neighbors (E:(A->bool)->bool) (u:A))`
   (LABEL_TAC "degree") THENL
   [ACCEPT_TAC(MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`; `t:A`]
      FINITE_GRAPH_TWO_DISTINCT_NEIGHBORS_CARD)
     (end_itlist CONJ
      [ASSUME `finite_simple_graph (V:A->bool) E`;
       ASSUME `(v:A) IN graph_neighbors E u`;
       ASSUME `(t:A) IN graph_neighbors E u`;
       ASSUME `~((v:A) = t)`]));
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `u:A`; `((u:A),v):A#A`]
   MAXIMAL_EULER_PLANAR_ROTATION_NEIGHBOR_CYCLE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC "@w. _ w_injective w_first w_rest"] THEN
  USE_THEN "w_rest" (fun rest_th ->
   USE_THEN "degree" (fun degree_th ->
    MP_TAC(MATCH_MP rest_th degree_th))) THEN
  INTRO_TAC "w_second w_edges" THEN
  SUBGOAL_THEN `(w:num->A) 0 = v` (LABEL_TAC "w0") THENL
   [USE_THEN "w_first" MP_TAC THEN REWRITE_TAC[SND];
    ALL_TAC] THEN
  SUBGOAL_THEN `((u:A),v) IN graph_darts E`
   (LABEL_TAC "uv_dart") THENL
   [USE_THEN "outgoing" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) (u,v) = (u,(w:num->A) 1)`
   (LABEL_TAC "step") THENL
   [GEN_REWRITE_TAC LAND_CONV [GSYM PAIR] THEN
    REWRITE_TAC[PAIR_EQ] THEN CONJ_TAC THENL
     [MP_TAC(MATCH_MP
       (ISPECL
        [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((u:A),v):A#A`]
        GRAPH_ROTATION_TAIL)
       (CONJ
        (ASSUME `graph_rotation E (r:(A#A)->A#A)`)
        (ASSUME `((u:A),v) IN graph_darts E`))) THEN
      REWRITE_TAC[FST];
      USE_THEN "w_second" (ACCEPT_TAC o SYM)];
    ALL_TAC] THEN
  SUBGOAL_THEN `((u:A),(w:num->A) 1) IN graph_darts E`
   (LABEL_TAC "uz_dart") THENL
   [USE_THEN "step" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((u:A),v):A#A`]
     GRAPH_ROTATION_IN) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{u:A,v} IN E` (LABEL_TAC "uv_edge") THENL
   [USE_THEN "v_neighbor" MP_TAC THEN REWRITE_TAC[IN_GRAPH_NEIGHBORS];
    ALL_TAC] THEN
  SUBGOAL_THEN `{u:A,(w:num->A) 1} IN E`
   (LABEL_TAC "uz_edge") THENL
   [USE_THEN "uz_dart" MP_TAC THEN
    REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `1 MOD CARD(graph_neighbors (E:(A->bool)->bool) (u:A)) = 1`
   (LABEL_TAC "one_mod_degree") THENL
   [MATCH_MP_TAC MOD_LT THEN USE_THEN "degree" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `{v:A,(w:num->A) 1} IN E`
   (LABEL_TAC "vz_edge") THENL
   [USE_THEN "w_edges" (fun th ->
      MP_TAC(SPEC `{v:A,(w:num->A) 1}` (REWRITE_RULE[SUBSET] th))) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[IN_CYCLIC_EDGES] THEN
      EXISTS_TAC `0` THEN CONJ_TAC THENL
       [USE_THEN "degree" MP_TAC THEN ARITH_TAC;
        REWRITE_TAC[ADD_CLAUSES] THEN
        USE_THEN "one_mod_degree" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "w0" (fun th -> REWRITE_TAC[th])];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) = v)` (LABEL_TAC "uv_distinct") THENL
   [MP_TAC(MATCH_MP
     (ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
      FINITE_SIMPLE_GRAPH_DART)
     (CONJ
      (ASSUME `finite_simple_graph (V:A->bool) E`)
      (ASSUME `((u:A),v) IN graph_darts E`))) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) = (w:num->A) 1)`
   (LABEL_TAC "uz_distinct") THENL
   [MP_TAC(MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `(w:num->A) 1`]
      FINITE_SIMPLE_GRAPH_DART)
     (CONJ
      (ASSUME `finite_simple_graph (V:A->bool) E`)
      (ASSUME `((u:A),(w:num->A) 1) IN graph_darts E`))) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((v:A) = (w:num->A) 1)`
   (LABEL_TAC "vz_distinct") THENL
   [DISCH_THEN(LABEL_TAC "same") THEN
    USE_THEN "w_injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_CYCLIC_INDICES; IN_UNIV] THEN
    DISCH_THEN(MP_TAC o SPECL [`0`; `1`]) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "degree" MP_TAC THEN ARITH_TAC;
        USE_THEN "degree" MP_TAC THEN ARITH_TAC;
        ACCEPT_TAC(TRANS
         (ASSUME `(w:num->A) 0 = v`)
         (ASSUME `(v:A) = w 1`))];
      ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A) (u,(w:num->A) 1) =
    (w 1,v)`
   (LABEL_TAC "first_successor") THENL
   [ACCEPT_TAC(MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
       `u:A`; `v:A`; `(w:num->A) 1`]
      MAXIMAL_EULER_PLANAR_ROTATION_SUCCESSIVE_NEIGHBOR_FACE)
     (end_itlist CONJ
      [ASSUME `euler_planar_rotation (V:A->bool) E r`;
       ASSUME `connected_graph (V:A->bool) E`;
       ASSUME
        `!G s:(A#A)->A#A.
             E PSUBSET G /\ G SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V G s`;
       ASSUME `3 <= CARD(V:A->bool)`;
       ASSUME `((u:A),v) IN outgoing_darts E u`;
       ASSUME `(r:(A#A)->A#A)(u,v) = (u,(w:num->A) 1)`;
       ASSUME `~((v:A) = w 1)`;
       ASSUME `{v:A,w 1} IN E`]));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A) ((w:num->A) 1,v) =
    (v,u)`
   (LABEL_TAC "second_successor") THENL
   [ACCEPT_TAC(MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
       `u:A`; `v:A`; `(w:num->A) 1`]
      MAXIMAL_EULER_PLANAR_ROTATION_SUCCESSIVE_NEIGHBOR_FACE_NEXT)
     (end_itlist CONJ
      [ASSUME `euler_planar_rotation (V:A->bool) E r`;
       ASSUME `connected_graph (V:A->bool) E`;
       ASSUME
        `!G s:(A#A)->A#A.
             E PSUBSET G /\ G SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V G s`;
       ASSUME `3 <= CARD(V:A->bool)`;
       ASSUME `((u:A),v) IN outgoing_darts E u`;
       ASSUME `(r:(A#A)->A#A)(u,v) = (u,(w:num->A) 1)`;
       ASSUME `~((v:A) = w 1)`;
       ASSUME `{v:A,w 1} IN E`]));
    ALL_TAC] THEN
  SUBGOAL_THEN `((v:A),u) IN graph_darts E`
   (LABEL_TAC "vu_dart") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `((u:A),v):A#A`]
     GRAPH_DARTS_REVERSE) THEN
    REWRITE_TAC[REVERSE_DART_PAIR] THEN
    DISCH_THEN(fun th ->
      ACCEPT_TAC(MATCH_MP (snd(EQ_IMP_RULE th))
       (ASSUME `((u:A),v) IN graph_darts E`)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor E (r:(A#A)->A#A) (v,u) =
    (u,(w:num->A) 1)`
   (LABEL_TAC "third_successor") THENL
   [ACCEPT_TAC(TRANS
     (MATCH_MP
      (ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `u:A`; `v:A`]
       GRAPH_FACE_SUCCESSOR_PAIR)
      (ASSUME `((v:A),u) IN graph_darts E`))
     (ASSUME `(r:(A#A)->A#A)(u,v) = (u,(w:num->A) 1)`));
    ALL_TAC] THEN
  ABBREV_TAC
   `q:num->A =
      \i. if i = 0 then u else if i = 1 then (w:num->A) 1 else v` THEN
  SUBGOAL_THEN
   `(q:num->A) 0 = u /\ q 1 = (w:num->A) 1 /\ q 2 = v`
   (CONJUNCTS_THEN2 (LABEL_TAC "q0")
    (CONJUNCTS_THEN2 (LABEL_TAC "q1") (LABEL_TAC "q2"))) THENL
   [EXPAND_TAC "q" THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (q:num->A) (cyclic_indices 3) (:A)`
   (LABEL_TAC "q_injective") THENL
   [MATCH_MP_TAC INJ_CYCLIC_INDICES_3 THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "q0" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "q1" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "uz_distinct" ACCEPT_TAC;
      USE_THEN "q1" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "q2" (fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(fun th ->
       USE_THEN "vz_distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
       ACCEPT_TAC(SYM th));
      USE_THEN "q2" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "q0" (fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(fun th ->
       USE_THEN "uv_distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
       ACCEPT_TAC(SYM th))];
    ALL_TAC] THEN
  SUBGOAL_THEN `cyclic_edges (q:num->A) 3 SUBSET E`
   (LABEL_TAC "q_edges") THENL
   [REWRITE_TAC[CYCLIC_EDGES_3; INSERT_SUBSET; SING_SUBSET] THEN
    USE_THEN "q0" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "q1" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "q2" (fun th -> REWRITE_TAC[th]) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "uz_edge" ACCEPT_TAC;
      ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
      USE_THEN "vz_edge" ACCEPT_TAC;
      ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
      USE_THEN "uv_edge" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `simple_graph_cycle E (q:num->A) 3`
   (LABEL_TAC "q_cycle") THENL
   [REWRITE_TAC[simple_graph_cycle] THEN
    REPEAT CONJ_TAC THENL
     [ARITH_TAC;
      USE_THEN "q_injective" ACCEPT_TAC;
      USE_THEN "q_edges" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_face_successors E (r:(A#A)->A#A) (q:num->A) 3`
   (LABEL_TAC "q_successors") THENL
   [REWRITE_TAC[cyclic_face_successors] THEN
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    MP_TAC(MATCH_MP
     (ARITH_RULE `i < 3 ==> i = 0 \/ i = 1 \/ i = 2`)
     (ASSUME `(i:num) < 3`)) THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST1_TAC) THENL
     [REWRITE_TAC[cyclic_dart] THEN CONV_TAC NUM_REDUCE_CONV THEN
      USE_THEN "q0" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "q1" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "q2" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "first_successor" ACCEPT_TAC;
      REWRITE_TAC[cyclic_dart] THEN CONV_TAC NUM_REDUCE_CONV THEN
      USE_THEN "q0" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "q1" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "q2" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "second_successor" ACCEPT_TAC;
      REWRITE_TAC[cyclic_dart] THEN CONV_TAC NUM_REDUCE_CONV THEN
      USE_THEN "q0" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "q1" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "q2" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "third_successor" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `boundary_euler_rotation (V:A->bool) E (q:num->A) 3 r`
   (LABEL_TAC "q_boundary") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `3`;
      `r:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_OF_CYCLIC_FACE_SUCCESSORS) THEN
    REPEAT CONJ_TAC THENL
     [ARITH_TAC;
      USE_THEN "euler" ACCEPT_TAC;
      USE_THEN "q_successors" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `maximal_boundary_euler_rotation (V:A->bool) E (q:num->A) 3 r`
   (LABEL_TAC "q_maximal") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `q:num->A`; `3`]
     MAXIMAL_EULER_PLANAR_BOUNDARY_ROTATION) THEN
    CONJ_TAC THENL
     [USE_THEN "q_boundary" ACCEPT_TAC;
      USE_THEN "maximal" ACCEPT_TAC];
    ALL_TAC] THEN
  EXISTS_TAC `q:num->A` THEN
  CONJ_TAC THENL
   [USE_THEN "q_maximal" ACCEPT_TAC;
    USE_THEN "q_cycle" ACCEPT_TAC]);;

let CONNECTED_MAXIMAL_EULER_PLANAR_ROTATION_RECURSIVE_DISK = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        (!G s:(A#A)->A#A.
             E PSUBSET G /\
             G SUBSET complete_graph_edges V
             ==> ~euler_planar_rotation V G s) /\
        3 <= CARD V
        ==> ?q:num->A. recursive_triangulated_disk V E q 3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "euler connected maximal vertices_large" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
   MAXIMAL_EULER_PLANAR_ROTATION_TRIANGULAR_BOUNDARY) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "euler" ACCEPT_TAC;
      USE_THEN "connected" ACCEPT_TAC;
      USE_THEN "maximal" ACCEPT_TAC;
      USE_THEN "vertices_large" ACCEPT_TAC];
    INTRO_TAC "@q. q_maximal q_cycle"] THEN
  EXISTS_TAC `q:num->A` THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `3`;
    `r:(A#A)->A#A`]
   MAXIMAL_BOUNDARY_EULER_ROTATION_RECURSIVE_TRIANGULATED_DISK) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "q_maximal" ACCEPT_TAC;
    USE_THEN "q_cycle" ACCEPT_TAC;
    USE_THEN "connected" ACCEPT_TAC]);;

let CONNECTED_EULER_PLANAR_GRAPH_IMP_RECURSIVE_PLANAR_GRAPH = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        euler_planar_graph V E /\ connected_graph V E
        ==> recursive_planar_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler connected" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
   (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC EULER_PLANAR_GRAPH_FINITE_SIMPLE THEN
    USE_THEN "euler" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[recursive_planar_graph] THEN
  CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `CARD(V:A->bool) <= 2` THENL
   [ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "large")] THEN
  DISJ2_TAC THEN
  SUBGOAL_THEN `3 <= CARD(V:A->bool)` (LABEL_TAC "card") THENL
   [USE_THEN "large" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(V:A->bool = {})` (LABEL_TAC "nonempty") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "card" MP_TAC THEN
    REWRITE_TAC[CONJUNCT1 CARD_CLAUSES] THEN ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "nonempty" MP_TAC THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
  INTRO_TAC "@u. vertex" THEN
  MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
   EULER_PLANAR_GRAPH_CONNECTED) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "euler" ACCEPT_TAC;
      USE_THEN "connected" ACCEPT_TAC;
      USE_THEN "vertex" ACCEPT_TAC];
    INTRO_TAC "@r. rotation"] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`]
   MAXIMAL_EULER_PLANAR_ROTATION_EXTENSION_CONNECTED) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "rotation" ACCEPT_TAC;
      USE_THEN "connected" ACCEPT_TAC];
    INTRO_TAC "@G s. subset extended_connected extended maximal"] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `G:(A->bool)->bool`; `s:(A#A)->A#A`]
   CONNECTED_MAXIMAL_EULER_PLANAR_ROTATION_RECURSIVE_DISK) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "extended" ACCEPT_TAC;
      USE_THEN "extended_connected" ACCEPT_TAC;
      USE_THEN "maximal" ACCEPT_TAC;
      USE_THEN "card" ACCEPT_TAC];
    INTRO_TAC "@q. recursive"] THEN
  MAP_EVERY EXISTS_TAC [`G:(A->bool)->bool`; `q:num->A`] THEN
  CONJ_TAC THENL
   [USE_THEN "subset" ACCEPT_TAC;
    USE_THEN "recursive" ACCEPT_TAC]);;

let FINITE_SIMPLE_GRAPH_DISJOINT_DARTS = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        DISJOINT V1 V2
        ==> DISJOINT (graph_darts E1) (graph_darts E2)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph1 graph2 vertices_disjoint" THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  X_GEN_TAC `d:A#A` THEN INTRO_TAC "dart1 dart2" THEN
  SUBGOAL_THEN `(FST(d:A#A)) IN V1` (LABEL_TAC "tail1") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`; `d:A#A`]
     FINITE_SIMPLE_GRAPH_DART_FST) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(FST(d:A#A)) IN V2` (LABEL_TAC "tail2") THENL
   [MATCH_MP_TAC(ISPECL
     [`V2:A->bool`; `E2:(A->bool)->bool`; `d:A#A`]
     FINITE_SIMPLE_GRAPH_DART_FST) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "vertices_disjoint" MP_TAC THEN ASM SET_TAC[]);;

let GRAPH_ROTATION_DISJOINT_UNION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        DISJOINT V1 V2
        ==> graph_rotation (E1 UNION E2)
             (disjoint_permutation_union r1 (graph_darts E1) r2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 rotation1 rotation2 vertices_disjoint" THEN
  SUBGOAL_THEN
   `DISJOINT (graph_darts E1:A#A->bool) (graph_darts E2)`
   (LABEL_TAC "darts_disjoint") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`]
     FINITE_SIMPLE_GRAPH_DISJOINT_DARTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[graph_rotation; GRAPH_DARTS_UNION] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_PERMUTES THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
       [`V2:A->bool`; `E2:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN ASM_REWRITE_TAC[];
      USE_THEN "darts_disjoint" ACCEPT_TAC];
    MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_PRESERVES_KEY THEN
    CONJ_TAC THENL
     [X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "dart1") THEN
      MATCH_MP_TAC(ISPECL
       [`E1:(A->bool)->bool`; `r1:(A#A)->A#A`; `d:A#A`]
       GRAPH_ROTATION_TAIL) THEN
      ASM_REWRITE_TAC[];
      X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "dart2") THEN
      MATCH_MP_TAC(ISPECL
       [`E2:(A->bool)->bool`; `r2:(A#A)->A#A`; `d:A#A`]
       GRAPH_ROTATION_TAIL) THEN
      ASM_REWRITE_TAC[]];
    MAP_EVERY X_GEN_TAC [`d:A#A`; `d2:A#A`] THEN
    INTRO_TAC "d_union d2_union same_tail" THEN
    USE_THEN "d_union"
     (DISJ_CASES_THEN2 (LABEL_TAC "d_left") (LABEL_TAC "d_right") o
      REWRITE_RULE[IN_UNION]) THEN
    USE_THEN "d2_union"
     (DISJ_CASES_THEN2 (LABEL_TAC "d2_left") (LABEL_TAC "d2_right") o
      REWRITE_RULE[IN_UNION]) THENL
     [SUBGOAL_THEN `?n. ITER n (r1:(A#A)->A#A) d = d2`
       (X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THENL
       [MP_TAC(ISPECL
         [`E1:(A->bool)->bool`; `r1:(A#A)->A#A`; `d:A#A`; `d2:A#A`]
         GRAPH_ROTATION_ORBIT) THEN
        ASM_MESON_TAC[];
        EXISTS_TAC `n:num` THEN
        MP_TAC(SPEC `n:num`
         (MATCH_MP
          (ISPECL
           [`r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
            `graph_darts E1:A#A->bool`; `d:A#A`]
           DISJOINT_PERMUTATION_UNION_ITER_LEFT)
          (CONJ
           (MATCH_MP GRAPH_ROTATION_PERMUTES
            (ASSUME `graph_rotation E1 (r1:(A#A)->A#A)`))
           (ASSUME `(d:A#A) IN graph_darts E1`)))) THEN
        ASM_REWRITE_TAC[]];
      SUBGOAL_THEN `(FST(d:A#A)) IN V1` (LABEL_TAC "tail_left") THENL
       [MATCH_MP_TAC(ISPECL
         [`V1:A->bool`; `E1:(A->bool)->bool`; `d:A#A`]
         FINITE_SIMPLE_GRAPH_DART_FST) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(FST(d2:A#A)) IN V2` (LABEL_TAC "tail_right") THENL
       [MATCH_MP_TAC(ISPECL
         [`V2:A->bool`; `E2:(A->bool)->bool`; `d2:A#A`]
         FINITE_SIMPLE_GRAPH_DART_FST) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "vertices_disjoint" MP_TAC THEN ASM SET_TAC[];
      SUBGOAL_THEN `(FST(d:A#A)) IN V2` (LABEL_TAC "tail_right") THENL
       [MATCH_MP_TAC(ISPECL
         [`V2:A->bool`; `E2:(A->bool)->bool`; `d:A#A`]
         FINITE_SIMPLE_GRAPH_DART_FST) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(FST(d2:A#A)) IN V1` (LABEL_TAC "tail_left") THENL
       [MATCH_MP_TAC(ISPECL
         [`V1:A->bool`; `E1:(A->bool)->bool`; `d2:A#A`]
         FINITE_SIMPLE_GRAPH_DART_FST) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "vertices_disjoint" MP_TAC THEN ASM SET_TAC[];
      SUBGOAL_THEN `?n. ITER n (r2:(A#A)->A#A) d = d2`
       (X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THENL
       [MP_TAC(ISPECL
         [`E2:(A->bool)->bool`; `r2:(A#A)->A#A`; `d:A#A`; `d2:A#A`]
         GRAPH_ROTATION_ORBIT) THEN
        ASM_MESON_TAC[];
        EXISTS_TAC `n:num` THEN
        MP_TAC(SPEC `n:num`
         (MATCH_MP
          (ISPECL
           [`r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
            `graph_darts E1:A#A->bool`; `graph_darts E2:A#A->bool`;
            `d:A#A`]
           DISJOINT_PERMUTATION_UNION_ITER_RIGHT)
          (end_itlist CONJ
           [MATCH_MP GRAPH_ROTATION_PERMUTES
             (ASSUME `graph_rotation E2 (r2:(A#A)->A#A)`);
            ASSUME
             `DISJOINT (graph_darts E1:A#A->bool) (graph_darts E2)`;
            ASSUME `(d:A#A) IN graph_darts E2`]))) THEN
        ASM_REWRITE_TAC[]]]]);;

let GRAPH_FACE_SUCCESSOR_DISJOINT_UNION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        DISJOINT V1 V2
        ==> !d:A#A.
              d IN graph_darts (E1 UNION E2)
              ==> graph_face_successor
                   (E1 UNION E2)
                   (disjoint_permutation_union
                     r1 (graph_darts E1) r2) d =
                  disjoint_permutation_union
                   (graph_face_successor E1 r1) (graph_darts E1)
                   (graph_face_successor E2 r2) d`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 rotation1 rotation2 vertices_disjoint" THEN
  SUBGOAL_THEN
   `DISJOINT (graph_darts E1:A#A->bool) (graph_darts E2)`
   (LABEL_TAC "darts_disjoint") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`]
     FINITE_SIMPLE_GRAPH_DISJOINT_DARTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  X_GEN_TAC `d:A#A` THEN
  REWRITE_TAC[GRAPH_DARTS_UNION; IN_UNION] THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (LABEL_TAC "d_left") (LABEL_TAC "d_right")) THENL
   [ASM_SIMP_TAC
     [GRAPH_FACE_SUCCESSOR_IN; GRAPH_DARTS_UNION; IN_UNION;
      disjoint_permutation_union; GRAPH_DARTS_REVERSE];
    SUBGOAL_THEN `~((d:A#A) IN graph_darts E1)`
     (LABEL_TAC "not_left") THENL
     [USE_THEN "darts_disjoint" MP_TAC THEN ASM SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `~(reverse_dart(d:A#A) IN graph_darts E1)`
     (LABEL_TAC "reverse_not_left") THENL
     [ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE];
      ALL_TAC] THEN
    ASM_SIMP_TAC
     [GRAPH_FACE_SUCCESSOR_IN; GRAPH_DARTS_UNION; IN_UNION;
      disjoint_permutation_union; GRAPH_DARTS_REVERSE]]);;

let CARD_GRAPH_FACES_DISJOINT_UNION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        DISJOINT V1 V2
        ==> CARD
             (graph_faces (E1 UNION E2)
               (disjoint_permutation_union r1 (graph_darts E1) r2)) =
            CARD(graph_faces E1 r1) + CARD(graph_faces E2 r2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 rotation1 rotation2 vertices_disjoint" THEN
  SUBGOAL_THEN
   `FINITE(graph_darts E1:A#A->bool) /\
    FINITE(graph_darts E2:A#A->bool)`
   (CONJUNCTS_THEN2 (LABEL_TAC "finite_darts1")
     (LABEL_TAC "finite_darts2")) THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
       [`V2:A->bool`; `E2:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `DISJOINT (graph_darts E1:A#A->bool) (graph_darts E2)`
   (LABEL_TAC "darts_disjoint") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`]
     FINITE_SIMPLE_GRAPH_DISJOINT_DARTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(graph_face_successor E1 r1:(A#A)->A#A) permutes graph_darts E1 /\
    (graph_face_successor E2 r2:(A#A)->A#A) permutes graph_darts E2`
   (CONJUNCTS_THEN2 (LABEL_TAC "face_permutation1")
     (LABEL_TAC "face_permutation2")) THENL
   [CONJ_TAC THEN MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbits
     (graph_face_successor
       (E1 UNION E2)
       (disjoint_permutation_union
         (r1:(A#A)->A#A) (graph_darts E1) r2))
     (graph_darts E1 UNION graph_darts E2) =
    permutation_orbits
     (disjoint_permutation_union
       (graph_face_successor E1 r1) (graph_darts E1)
       (graph_face_successor E2 r2))
     (graph_darts E1 UNION graph_darts E2)`
   (LABEL_TAC "same_orbits") THENL
   [MATCH_MP_TAC PERMUTATION_ORBITS_EQ_ON THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_PERMUTES THEN
      ASM_REWRITE_TAC[];
      X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "dart") THEN
      MP_TAC(ISPECL
       [`V1:A->bool`; `V2:A->bool`;
        `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
        `r1:(A#A)->A#A`; `r2:(A#A)->A#A`]
       GRAPH_FACE_SUCCESSOR_DISJOINT_UNION) THEN
      ASM_REWRITE_TAC[GRAPH_DARTS_UNION] THEN
      DISCH_THEN(MP_TAC o SPEC `d:A#A`) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[GRAPH_FACES_AS_PERMUTATION_ORBITS; GRAPH_DARTS_UNION] THEN
  USE_THEN "same_orbits" (fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC CARD_PERMUTATION_ORBITS_DISJOINT_UNION THEN
  ASM_REWRITE_TAC[]);;

let PERMUTATION_ORBIT_MEMBERSHIP_INVARIANT = prove
 (`!f:A->A. !s a z.
        FINITE s /\ f permutes s /\ a IN s /\ z IN s
        ==> (f z IN permutation_orbit f a <=>
             z IN permutation_orbit f a)`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutation anchor member" THEN
  SUBGOAL_THEN `(f:A->A) z IN s` (LABEL_TAC "image") THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `z:A`]
     PERMUTES_IN_IMAGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit (f:A->A) (f z) = permutation_orbit f z`
   (LABEL_TAC "successor_orbit") THENL
   [MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `z:A`; `(f:A->A) z`]
     PERMUTATION_ORBIT_EQ) THEN
    ASM_REWRITE_TAC[] THEN
    MESON_TAC[PERMUTATION_ORBIT_SUCCESSOR; PERMUTATION_ORBIT_REFL];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `(f:A->A) z`]
   PERMUTATION_ORBIT_EQ) THEN
  MP_TAC(ISPECL [`f:A->A`; `s:A->bool`; `a:A`; `z:A`]
   PERMUTATION_ORBIT_EQ) THEN
  ASM_REWRITE_TAC[] THEN MESON_TAC[]);;

let CARD_GRAPH_FACES_INSERT_EDGE_DISTINCT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !u v:A. !a b:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        ~(u = v) /\
        ~({u,v} IN E) /\
        a IN outgoing_darts E u /\
        b IN outgoing_darts E v /\
        ~(reverse_dart b IN graph_face E r (reverse_dart a))
        ==> CARD(graph_faces E r) =
            CARD
             (graph_faces
               ({u,v} INSERT E)
               (permutation_insert
                 (permutation_insert r (u,v) a)
                 (v,u) b)) + 1`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph rotation distinct new_edge a_anchor b_anchor separate_faces" THEN
  USE_THEN "a_anchor" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "a_dart a_tail" THEN
  USE_THEN "b_anchor" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "b_dart b_tail" THEN
  SUBGOAL_THEN
   `~(((u:A),(v:A)) IN graph_darts E) /\
    ~(((v:A),(u:A)) IN graph_darts E) /\
    ~((u:A,v:A) = (v,u))`
   (CONJUNCTS_THEN2 (LABEL_TAC "forward_fresh")
     (CONJUNCTS_THEN2 (LABEL_TAC "reverse_fresh")
      (LABEL_TAC "darts_distinct"))) THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[IN_GRAPH_DARTS];
      ASM_REWRITE_TAC[IN_GRAPH_DARTS;
                      SET_RULE `{v:A,u} = {u,v}`];
      REWRITE_TAC[PAIR_EQ] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(graph_darts (E:(A->bool)->bool))`
   (LABEL_TAC "finite_darts") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  ABBREV_TAC `g:(A#A)->A#A = graph_face_successor E r` THEN
  ABBREV_TAC
   `g1:(A#A)->A#A =
      permutation_insert g (u,v) (reverse_dart a)` THEN
  ABBREV_TAC
   `g2:(A#A)->A#A =
      permutation_insert g1 (v,u) (reverse_dart b)` THEN
  SUBGOAL_THEN `(g:(A#A)->A#A) permutes graph_darts E`
   (LABEL_TAC "face_permutation") THENL
   [EXPAND_TAC "g" THEN MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `reverse_dart(a:A#A) IN graph_darts E /\
    reverse_dart(b:A#A) IN graph_darts E`
   (CONJUNCTS_THEN2 (LABEL_TAC "reverse_a_dart")
     (LABEL_TAC "reverse_b_dart")) THENL
   [ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(permutation_orbit (g:(A#A)->A#A) (reverse_dart b) =
      permutation_orbit g (reverse_dart a))`
