let FINITE_SIMPLE_GRAPH_DISJOINT_EDGES = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        DISJOINT V1 V2
        ==> DISJOINT E1 E2`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph1 graph2 vertices_disjoint" THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  X_GEN_TAC `e:A->bool` THEN INTRO_TAC "edge1 edge2" THEN
  MP_TAC(ISPECL
   [`V1:A->bool`; `E1:(A->bool)->bool`; `e:A->bool`]
   FINITE_SIMPLE_GRAPH_EDGE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@u v. u_vertex1 v_vertex1 distinct edge_pair" THEN
  SUBGOAL_THEN `(u:A) IN V2` (LABEL_TAC "u_vertex2") THENL
   [USE_THEN "graph2" MP_TAC THEN REWRITE_TAC[finite_simple_graph] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
     (CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `e:A->bool`))) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "edge_pair" (fun th ->
      REWRITE_TAC[th; SUBSET; IN_INSERT]);
    ALL_TAC] THEN
  USE_THEN "vertices_disjoint" MP_TAC THEN ASM SET_TAC[]);;

let EULER_PLANAR_ROTATION_BRIDGE_DISJOINT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u v:A. !a b:A#A.
        euler_planar_rotation V1 E1 r1 /\
        euler_planar_rotation V2 E2 r2 /\
        DISJOINT V1 V2 /\
        u IN V1 /\ v IN V2 /\
        a IN outgoing_darts E1 u /\
        b IN outgoing_darts E2 v
        ==> euler_planar_rotation
             (V1 UNION V2)
             ({u,v} INSERT (E1 UNION E2))
             (permutation_insert
               (permutation_insert
                 (disjoint_permutation_union
                   r1 (graph_darts E1) r2)
                 (u,v) a)
               (v,u) b)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler1 euler2 vertices_disjoint u_vertex v_vertex a_anchor b_anchor" THEN
  USE_THEN "euler1" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph1 rotation1 formula1" THEN
  USE_THEN "euler2" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph2 rotation2 formula2" THEN
  ABBREV_TAC
   `r:(A#A)->A#A =
      disjoint_permutation_union
       (r1:(A#A)->A#A) (graph_darts E1) r2` THEN
  SUBGOAL_THEN
   `finite_simple_graph (V1 UNION V2:A->bool) (E1 UNION E2)`
   (LABEL_TAC "union_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_UNION THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_rotation (E1 UNION E2) (r:(A#A)->A#A)`
   (LABEL_TAC "union_rotation") THENL
   [EXPAND_TAC "r" THEN
    MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`]
     GRAPH_ROTATION_DISJOINT_UNION) THEN
