       [`graph_face_successor E1 r1:(A#A)->A#A`;
        `graph_darts E1:A#A->bool`; `d:A#A`]
       PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(d:A#A) IN graph_darts E2`
       (LABEL_TAC "d_right") THENL
       [USE_THEN "d_union" MP_TAC THEN
        REWRITE_TAC[GRAPH_DARTS_UNION; IN_UNION] THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
