    DISCH_THEN(LABEL_TAC "same_face") THEN
    USE_THEN "different_union_faces" (MATCH_MP_TAC o NOT_ELIM) THEN
    MP_TAC(ISPECL
     [`graph_face_successor (E1 UNION E2) (r:(A#A)->A#A)`;
      `graph_darts (E1 UNION E2):A#A->bool`;
      `reverse_dart(a:A#A)`; `reverse_dart(b:A#A)`]
     PERMUTATION_ORBIT_EQ) THEN
    ASM_REWRITE_TAC[GRAPH_DARTS_UNION; IN_UNION];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(E1:(A->bool)->bool = {}) /\
                ~(E2:(A->bool)->bool = {})`
   (CONJUNCTS_THEN2 (LABEL_TAC "edges1_nonempty")
     (LABEL_TAC "edges2_nonempty")) THENL
   [CONJ_TAC THENL
