      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`]
     CARD_GRAPH_FACES_DISJOINT_UNION) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(graph_faces (E1 UNION E2) (r:(A#A)->A#A)) =
