   [MATCH_MP_TAC(ISPECL
     [`V1 UNION V2:A->bool`; `E1 UNION E2:(A->bool)->bool`;
      `r:(A#A)->A#A`; `u:A`; `v:A`; `a:A#A`; `b:A#A`]
     CARD_GRAPH_FACES_INSERT_EDGE_DISTINCT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INSERT_EDGE THEN
