      SIMP_TAC[ASSUME `~(E2:(A->bool)->bool = {})`];
      ALL_TAC] THEN
    REWRITE_TAC[graph_euler_formula; graph_map_faces; NOT_INSERT_EMPTY] THEN
    USE_THEN "vertex_count" MP_TAC THEN
    USE_THEN "edge_count" MP_TAC THEN
    USE_THEN "inserted_edge_count" MP_TAC THEN
    USE_THEN "union_face_count" MP_TAC THEN
    USE_THEN "bridge_face_count" MP_TAC THEN
    USE_THEN "euler_count1" MP_TAC THEN
    USE_THEN "euler_count2" MP_TAC THEN
    ARITH_TAC]);;

let EULER_PLANAR_ROTATION_BRIDGE_CONNECTED = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A.
        euler_planar_rotation V1 E1 r1 /\
        connected_graph V1 E1 /\
        ~(V1 = {}) /\
        euler_planar_rotation V2 E2 r2 /\
        connected_graph V2 E2 /\
        ~(V2 = {}) /\
        DISJOINT V1 V2
        ==> ?u v:A. ?s:(A#A)->A#A.
              u IN V1 /\ v IN V2 /\
              euler_planar_rotation
               (V1 UNION V2)
               ({u,v} INSERT (E1 UNION E2)) s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler1 connected1 vertices1_nonempty euler2 connected2
    vertices2_nonempty vertices_disjoint" THEN
  SUBGOAL_THEN `finite_simple_graph (V1:A->bool) E1 /\
                finite_simple_graph (V2:A->bool) E2`
   (CONJUNCTS_THEN2 (LABEL_TAC "graph1") (LABEL_TAC "graph2")) THENL
   [USE_THEN "euler1" MP_TAC THEN USE_THEN "euler2" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?u:A. u IN V1`
   (X_CHOOSE_THEN `u:A` (LABEL_TAC "u_vertex")) THENL
   [USE_THEN "vertices1_nonempty" MP_TAC THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY];
    ALL_TAC] THEN
  SUBGOAL_THEN `?v:A. v IN V2`
   (X_CHOOSE_THEN `v:A` (LABEL_TAC "v_vertex")) THENL
   [USE_THEN "vertices2_nonempty" MP_TAC THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`u:A`; `v:A`] THEN
  ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `E1:(A->bool)->bool = {}` THEN
  ASM_CASES_TAC `E2:(A->bool)->bool = {}` THENL
   [SUBGOAL_THEN `(V1:A->bool) = {u}` (LABEL_TAC "vertices1") THENL
     [MATCH_MP_TAC(ISPECL [`V1:A->bool`; `u:A`]
       CONNECTED_GRAPH_EMPTY_EDGES_SINGLETON) THEN
      CONJ_TAC THENL
       [USE_THEN "connected1"
         (ACCEPT_TAC o REWRITE_RULE
          [ASSUME `E1:(A->bool)->bool = {}`]);
        USE_THEN "u_vertex" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(V2:A->bool) = {v}` (LABEL_TAC "vertices2") THENL
     [MATCH_MP_TAC(ISPECL [`V2:A->bool`; `v:A`]
       CONNECTED_GRAPH_EMPTY_EDGES_SINGLETON) THEN
      CONJ_TAC THENL
       [USE_THEN "connected2"
         (ACCEPT_TAC o REWRITE_RULE
          [ASSUME `E2:(A->bool)->bool = {}`]);
        USE_THEN "v_vertex" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `~((u:A) = v)` (LABEL_TAC "distinct") THENL
     [USE_THEN "vertices_disjoint" MP_TAC THEN
      USE_THEN "vertices1" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "vertices2" (fun th -> REWRITE_TAC[th]) THEN
      SET_TAC[];
      ALL_TAC] THEN
    EXISTS_TAC `I:(A#A)->A#A` THEN
    USE_THEN "vertices1" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "vertices2" (fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[UNION_EMPTY;
                    SET_RULE `{u:A} UNION {v} = {u,v}`] THEN
    MATCH_MP_TAC EULER_PLANAR_ROTATION_SINGLE_EDGE THEN
    USE_THEN "distinct" ACCEPT_TAC;
    SUBGOAL_THEN `(V1:A->bool) = {u}` (LABEL_TAC "vertices1") THENL
     [MATCH_MP_TAC(ISPECL [`V1:A->bool`; `u:A`]
       CONNECTED_GRAPH_EMPTY_EDGES_SINGLETON) THEN
      CONJ_TAC THENL
       [USE_THEN "connected1"
         (ACCEPT_TAC o REWRITE_RULE
          [ASSUME `E1:(A->bool)->bool = {}`]);
        USE_THEN "u_vertex" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `~((u:A) IN V2)` (LABEL_TAC "u_fresh") THENL
     [USE_THEN "vertices_disjoint" MP_TAC THEN ASM SET_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V2:A->bool`; `E2:(A->bool)->bool`; `v:A`]
     CONNECTED_GRAPH_VERTEX_HAS_OUTGOING_DART) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A#A` (LABEL_TAC "b_anchor")) THEN
    ABBREV_TAC
     `s:(A#A)->A#A =
        permutation_insert (r2:(A#A)->A#A) (v,u) b` THEN
    SUBGOAL_THEN
     `euler_planar_rotation
       (u INSERT V2) ({v:A,u} INSERT E2) (s:(A#A)->A#A)`
     (LABEL_TAC "pendant") THENL
     [EXPAND_TAC "s" THEN
      MATCH_MP_TAC(ISPECL
       [`V2:A->bool`; `E2:(A->bool)->bool`; `r2:(A#A)->A#A`;
        `v:A`; `u:A`; `b:A#A`]
       EULER_PLANAR_ROTATION_INSERT_PENDANT) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    EXISTS_TAC `s:(A#A)->A#A` THEN
    USE_THEN "vertices1" (fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[UNION_EMPTY;
                    SET_RULE `{u:A} UNION V = u INSERT V`] THEN
    ONCE_REWRITE_TAC[SET_RULE `{u:A,v} = {v,u}`] THEN
    USE_THEN "pendant" ACCEPT_TAC;
    SUBGOAL_THEN `(V2:A->bool) = {v}` (LABEL_TAC "vertices2") THENL
     [MATCH_MP_TAC(ISPECL [`V2:A->bool`; `v:A`]
       CONNECTED_GRAPH_EMPTY_EDGES_SINGLETON) THEN
      CONJ_TAC THENL
       [USE_THEN "connected2"
         (ACCEPT_TAC o REWRITE_RULE
          [ASSUME `E2:(A->bool)->bool = {}`]);
        USE_THEN "v_vertex" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `~((v:A) IN V1)` (LABEL_TAC "v_fresh") THENL
     [USE_THEN "vertices_disjoint" MP_TAC THEN ASM SET_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`; `u:A`]
     CONNECTED_GRAPH_VERTEX_HAS_OUTGOING_DART) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A#A` (LABEL_TAC "a_anchor")) THEN
    ABBREV_TAC
     `s:(A#A)->A#A =
        permutation_insert (r1:(A#A)->A#A) (u,v) a` THEN
    SUBGOAL_THEN
     `euler_planar_rotation
       (v INSERT V1) ({u:A,v} INSERT E1) (s:(A#A)->A#A)`
     (LABEL_TAC "pendant") THENL
     [EXPAND_TAC "s" THEN
      MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`; `r1:(A#A)->A#A`;
        `u:A`; `v:A`; `a:A#A`]
       EULER_PLANAR_ROTATION_INSERT_PENDANT) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    EXISTS_TAC `s:(A#A)->A#A` THEN
    REWRITE_TAC[UNION_EMPTY] THEN
    USE_THEN "vertices2" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[SET_RULE `V UNION {v:A} = v INSERT V`] THEN
    USE_THEN "pendant" ACCEPT_TAC;
    MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`; `u:A`]
     CONNECTED_GRAPH_VERTEX_HAS_OUTGOING_DART) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A#A` (LABEL_TAC "a_anchor")) THEN
    MP_TAC(ISPECL
     [`V2:A->bool`; `E2:(A->bool)->bool`; `v:A`]
     CONNECTED_GRAPH_VERTEX_HAS_OUTGOING_DART) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A#A` (LABEL_TAC "b_anchor")) THEN
    EXISTS_TAC
     `permutation_insert
       (permutation_insert
        (disjoint_permutation_union
         (r1:(A#A)->A#A) (graph_darts E1) r2)
        (u,v) a)
       (v,u) b` THEN
    MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
      `u:A`; `v:A`; `a:A#A`; `b:A#A`]
     EULER_PLANAR_ROTATION_BRIDGE_DISJOINT) THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_REACHABLE_CLOSED_SET = prove
 (`!E W u v:A.
        u IN W /\
        (!x y. x IN W /\ {x,y} IN E ==> y IN W) /\
        graph_reachable E u v
        ==> v IN W`,
  REPEAT GEN_TAC THEN INTRO_TAC "u_member closed reachable" THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `W:A->bool`; `u:A`; `v:A`]
   GRAPH_REACHABLE_CLOSED) THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_COMPONENTS_DISJOINT = prove
 (`!E u v:A.
        ~graph_reachable E u v
        ==> DISJOINT (graph_component E u) (graph_component E v)`,
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY;
              IN_GRAPH_COMPONENT] THEN
  MESON_TAC[GRAPH_REACHABLE_SYM; GRAPH_REACHABLE_TRANS]);;

let GRAPH_COMPONENT_INSERT_BRIDGE = prove
 (`!E u v:A.
        ~graph_reachable E u v
        ==> graph_component ({u,v} INSERT E) u =
            graph_component E u UNION graph_component E v`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "separate") THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET] THEN
    X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "x_component") THEN
    MATCH_MP_TAC(ISPECL
     [`({u:A,v} INSERT E):(A->bool)->bool`;
      `graph_component E u UNION graph_component E v:A->bool`;
      `u:A`; `x:A`]
     GRAPH_REACHABLE_CLOSED_SET) THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[IN_UNION; GRAPH_COMPONENT_REFL];
      MAP_EVERY X_GEN_TAC [`a:A`; `b:A`] THEN
      REWRITE_TAC[IN_UNION; IN_INSERT] THEN
      INTRO_TAC "a_member edge" THEN
      USE_THEN "edge" DISJ_CASES_TAC THENL
       [SUBGOAL_THEN `(b:A) = u \/ b = v` DISJ_CASES_TAC THENL
         [MATCH_MP_TAC
           (SET_RULE `{a:A,b} = {u,v} ==> b = u \/ b = v`) THEN
          ASM_REWRITE_TAC[];
          ASM_REWRITE_TAC[GRAPH_COMPONENT_REFL];
          ASM_REWRITE_TAC[GRAPH_COMPONENT_REFL]];
        USE_THEN "a_member" DISJ_CASES_TAC THENL
         [DISJ1_TAC THEN MATCH_MP_TAC GRAPH_COMPONENT_CLOSED THEN
          EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[];
          DISJ2_TAC THEN MATCH_MP_TAC GRAPH_COMPONENT_CLOSED THEN
          EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[]]];
      USE_THEN "x_component" MP_TAC THEN
      REWRITE_TAC[IN_GRAPH_COMPONENT]];
    REWRITE_TAC[SUBSET; IN_UNION; IN_GRAPH_COMPONENT] THEN
    X_GEN_TAC `x:A` THEN DISCH_THEN DISJ_CASES_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `({u:A,v} INSERT E):(A->bool)->bool`;
        `u:A`; `x:A`]
       GRAPH_REACHABLE_MONO) THEN
      CONJ_TAC THENL
       [MATCH_ACCEPT_TAC
         (SET_RULE
          `(E:(A->bool)->bool) SUBSET (e:A->bool) INSERT E`);
        ASM_REWRITE_TAC[]];
      MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN
      EXISTS_TAC `v:A` THEN CONJ_TAC THENL
       [MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
        REWRITE_TAC[IN_INSERT];
        MATCH_MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `({u:A,v} INSERT E):(A->bool)->bool`;
          `v:A`; `x:A`]
         GRAPH_REACHABLE_MONO) THEN
        CONJ_TAC THENL
         [MATCH_ACCEPT_TAC
           (SET_RULE
            `(E:(A->bool)->bool) SUBSET (e:A->bool) INSERT E`);
          ASM_REWRITE_TAC[]]]]]);;

let GRAPH_COMPONENT_INSERT_BRIDGE_MERGED = prove
 (`!E u v x:A.
        ~graph_reachable E u v /\
        x IN graph_component E u UNION graph_component E v
        ==> graph_component ({u,v} INSERT E) x =
            graph_component E u UNION graph_component E v`,
  REPEAT GEN_TAC THEN INTRO_TAC "separate x_merged" THEN
  SUBGOAL_THEN
   `graph_component ({u:A,v} INSERT E) u =
    graph_component E u UNION graph_component E v`
  (LABEL_TAC "merged") THENL
   [MATCH_MP_TAC GRAPH_COMPONENT_INSERT_BRIDGE THEN
    USE_THEN "separate" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "merged"
   (fun th -> REWRITE_TAC[GSYM th; GRAPH_COMPONENT_EQ]) THEN
  MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
  REWRITE_TAC[GSYM IN_GRAPH_COMPONENT] THEN
  USE_THEN "merged" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "x_merged" ACCEPT_TAC);;

let GRAPH_COMPONENT_INSERT_BRIDGE_OUTSIDE_CLOSED = prove
 (`!E u v x a b:A.
        ~graph_reachable E u v /\
        ~(x IN graph_component E u UNION graph_component E v) /\
        a IN graph_component E x /\
        {a,b} IN {u,v} INSERT E
        ==> b IN graph_component E x`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "separate x_outside a_member edge" THEN
  USE_THEN "edge" MP_TAC THEN REWRITE_TAC[IN_INSERT] THEN
  DISCH_THEN DISJ_CASES_TAC THENL
   [SUBGOAL_THEN `(a:A) = u \/ a = v` DISJ_CASES_TAC THENL
     [MATCH_MP_TAC
       (SET_RULE `{a:A,b} = {u,v} ==> a = u \/ a = v`) THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN `x IN graph_component E (u:A)`
      (LABEL_TAC "x_u") THENL
       [REWRITE_TAC[IN_GRAPH_COMPONENT] THEN
        MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
        USE_THEN "a_member" MP_TAC THEN
        REWRITE_TAC[IN_GRAPH_COMPONENT] THEN ASM_REWRITE_TAC[];
        USE_THEN "x_outside" MP_TAC THEN
        REWRITE_TAC[IN_UNION] THEN ASM_REWRITE_TAC[]];
      SUBGOAL_THEN `x IN graph_component E (v:A)`
      (LABEL_TAC "x_v") THENL
       [REWRITE_TAC[IN_GRAPH_COMPONENT] THEN
        MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
        USE_THEN "a_member" MP_TAC THEN
        REWRITE_TAC[IN_GRAPH_COMPONENT] THEN ASM_REWRITE_TAC[];
        USE_THEN "x_outside" MP_TAC THEN
        REWRITE_TAC[IN_UNION] THEN ASM_REWRITE_TAC[]]];
    MATCH_MP_TAC GRAPH_COMPONENT_CLOSED THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[]]);;

let GRAPH_COMPONENT_INSERT_BRIDGE_OUTSIDE = prove
 (`!E u v x:A.
        ~graph_reachable E u v /\
        ~(x IN graph_component E u UNION graph_component E v)
        ==> graph_component ({u,v} INSERT E) x =
            graph_component E x`,
  REPEAT GEN_TAC THEN INTRO_TAC "separate x_outside" THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET] THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_component") THEN
    MATCH_MP_TAC(ISPECL
     [`({u:A,v} INSERT E):(A->bool)->bool`;
      `graph_component E x:A->bool`; `x:A`; `z:A`]
     GRAPH_REACHABLE_CLOSED_SET) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_ACCEPT_TAC GRAPH_COMPONENT_REFL;
      MAP_EVERY X_GEN_TAC [`a:A`; `b:A`] THEN
      INTRO_TAC "a_member edge" THEN
      MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `u:A`; `v:A`; `x:A`; `a:A`; `b:A`]
       GRAPH_COMPONENT_INSERT_BRIDGE_OUTSIDE_CLOSED) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "z_component" MP_TAC THEN
      REWRITE_TAC[IN_GRAPH_COMPONENT]];
    REWRITE_TAC[SUBSET; IN_GRAPH_COMPONENT] THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "reachable") THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `({u:A,v} INSERT E):(A->bool)->bool`;
      `x:A`; `z:A`]
     GRAPH_REACHABLE_MONO) THEN
    CONJ_TAC THENL
     [MATCH_ACCEPT_TAC
       (SET_RULE
        `(E:(A->bool)->bool) SUBSET (e:A->bool) INSERT E`);
      USE_THEN "reachable" ACCEPT_TAC]]);;

let FINITE_SIMPLE_GRAPH_EDGE_COMPONENT = prove
 (`!V E e x:A.
        finite_simple_graph V E /\ e IN E /\ x IN e
        ==> e SUBSET graph_component E x`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge x_member" THEN
  SUBGOAL_THEN `(e:A->bool) HAS_SIZE 2` (LABEL_TAC "edge_size") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "edge_size" (MP_TAC o CONV_RULE HAS_SIZE_CONV) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A`
   (X_CHOOSE_THEN `b:A`
    (CONJUNCTS_THEN2
      (LABEL_TAC "distinct") (LABEL_TAC "edge_pair")))) THEN
  USE_THEN "edge_pair"
   (fun th -> REWRITE_TAC
     [th; SUBSET; IN_GRAPH_COMPONENT; IN_INSERT; IN_SING;
      NOT_IN_EMPTY]) THEN
  X_GEN_TAC `y:A` THEN DISCH_THEN(LABEL_TAC "y_endpoint") THEN
  SUBGOAL_THEN `(x:A) = a \/ x = b` (LABEL_TAC "x_endpoint") THENL
   [USE_THEN "x_member" MP_TAC THEN
    USE_THEN "edge_pair"
     (fun th -> REWRITE_TAC
       [th; IN_INSERT; IN_SING; NOT_IN_EMPTY]);
    SUBGOAL_THEN `{a:A,b} IN E` (LABEL_TAC "pair_edge") THENL
     [USE_THEN "edge_pair"
       (fun th -> USE_THEN "edge" (ACCEPT_TAC o REWRITE_RULE[th]));
      USE_THEN "x_endpoint" DISJ_CASES_TAC THEN
      USE_THEN "y_endpoint" DISJ_CASES_TAC THEN
      ASM_REWRITE_TAC[GRAPH_REACHABLE_REFL] THEN
      MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
      ASM_REWRITE_TAC[SET_RULE `{b:A,a} = {a,b}`]]]);;

let FINITE_SIMPLE_GRAPH_EDGE_SUBSET_COMPONENT_UNION = prove
 (`!V E e u v:A.
        finite_simple_graph V E /\
        e IN E /\
        e SUBSET (graph_component E u UNION graph_component E v)
        ==> e SUBSET graph_component E u \/
            e SUBSET graph_component E v`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge edge_subset" THEN
  SUBGOAL_THEN `(e:A->bool) HAS_SIZE 2` (LABEL_TAC "edge_size") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "edge_size" (MP_TAC o CONV_RULE HAS_SIZE_CONV) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A`
   (X_CHOOSE_THEN `b:A`
    (CONJUNCTS_THEN2
      (LABEL_TAC "distinct") (LABEL_TAC "edge_pair")))) THEN
  SUBGOAL_THEN `(a:A) IN e` (LABEL_TAC "a_edge") THENL
   [USE_THEN "edge_pair"
     (fun th -> REWRITE_TAC[th; IN_INSERT]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(a:A) IN graph_component E u \/ a IN graph_component E v`
  (DISJ_CASES_THEN2 (LABEL_TAC "a_u") (LABEL_TAC "a_v")) THENL
   [USE_THEN "edge_subset"
     (MP_TAC o SPEC `a:A` o REWRITE_RULE[SUBSET]) THEN
    ASM_REWRITE_TAC[IN_UNION];
    DISJ1_TAC THEN
    SUBGOAL_THEN
     `graph_component E (a:A) = graph_component E u`
    (LABEL_TAC "same_component") THENL
     [REWRITE_TAC[GRAPH_COMPONENT_EQ] THEN
      MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
      USE_THEN "a_u"
       (ACCEPT_TAC o REWRITE_RULE[IN_GRAPH_COMPONENT]);
      USE_THEN "same_component"
       (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`; `a:A`]
       FINITE_SIMPLE_GRAPH_EDGE_COMPONENT) THEN
      ASM_REWRITE_TAC[]];
    DISJ2_TAC THEN
    SUBGOAL_THEN
     `graph_component E (a:A) = graph_component E v`
    (LABEL_TAC "same_component") THENL
     [REWRITE_TAC[GRAPH_COMPONENT_EQ] THEN
      MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
      USE_THEN "a_v"
       (ACCEPT_TAC o REWRITE_RULE[IN_GRAPH_COMPONENT]);
      USE_THEN "same_component"
       (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`; `a:A`]
       FINITE_SIMPLE_GRAPH_EDGE_COMPONENT) THEN
      ASM_REWRITE_TAC[]]]);;

let GRAPH_COMPONENT_EDGES_EQ = prove
 (`!E u v:A.
        graph_reachable E u v
        ==> graph_component_edges E u = graph_component_edges E v`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "reachable") THEN
  SUBGOAL_THEN
   `graph_component E (u:A) = graph_component E v`
  (LABEL_TAC "component") THENL
   [REWRITE_TAC[GRAPH_COMPONENT_EQ] THEN
    USE_THEN "reachable" ACCEPT_TAC;
    REWRITE_TAC[EXTENSION; IN_GRAPH_COMPONENT_EDGES] THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_COMPONENT_EDGES_INSERT_BRIDGE_MERGED = prove
 (`!V E u v x:A.
        finite_simple_graph V E /\
        ~graph_reachable E u v /\
        x IN graph_component E u UNION graph_component E v
        ==> graph_component_edges ({u,v} INSERT E) x =
            {u,v} INSERT
            (graph_component_edges E u UNION graph_component_edges E v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph separate x_merged" THEN
  SUBGOAL_THEN
   `graph_component ({u:A,v} INSERT E) x =
    graph_component E u UNION graph_component E v`
  (LABEL_TAC "merged") THENL
   [MATCH_MP_TAC GRAPH_COMPONENT_INSERT_BRIDGE_MERGED THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `e:A->bool` THEN
    USE_THEN "merged"
     (fun th -> REWRITE_TAC
       [IN_GRAPH_COMPONENT_EDGES; IN_INSERT; IN_UNION; th]) THEN
    EQ_TAC THENL
     [INTRO_TAC "edge subset" THEN
      USE_THEN "edge"
       (DISJ_CASES_THEN2
         (LABEL_TAC "bridge") (LABEL_TAC "old_edge")) THENL
       [DISJ1_TAC THEN USE_THEN "bridge" ACCEPT_TAC;
        SUBGOAL_THEN
         `(e:A->bool) SUBSET graph_component E u \/
          e SUBSET graph_component E v`
        (DISJ_CASES_THEN2
          (LABEL_TAC "u_side") (LABEL_TAC "v_side")) THENL
         [MATCH_MP_TAC(ISPECL
           [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`;
            `u:A`; `v:A`]
           FINITE_SIMPLE_GRAPH_EDGE_SUBSET_COMPONENT_UNION) THEN
          ASM_REWRITE_TAC[];
          DISJ2_TAC THEN DISJ1_TAC THEN ASM_REWRITE_TAC[];
          DISJ2_TAC THEN DISJ2_TAC THEN ASM_REWRITE_TAC[]]];
      DISCH_THEN(DISJ_CASES_THEN2
       (LABEL_TAC "bridge")
       (DISJ_CASES_THEN2
         (LABEL_TAC "u_side") (LABEL_TAC "v_side"))) THENL
       [CONJ_TAC THENL
         [DISJ1_TAC THEN USE_THEN "bridge" ACCEPT_TAC;
          USE_THEN "bridge" SUBST1_TAC THEN
          REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_UNION;
                      GRAPH_COMPONENT_REFL]];
        CONJ_TAC THENL
         [DISJ2_TAC THEN
          USE_THEN "u_side" (ACCEPT_TAC o CONJUNCT1);
          MATCH_MP_TAC SUBSET_TRANS THEN
          EXISTS_TAC `graph_component E (u:A)` THEN
          CONJ_TAC THENL
           [USE_THEN "u_side" (ACCEPT_TAC o CONJUNCT2);
            MATCH_ACCEPT_TAC
             (SET_RULE `(s:A->bool) SUBSET s UNION t`)]];
        CONJ_TAC THENL
         [DISJ2_TAC THEN
          USE_THEN "v_side" (ACCEPT_TAC o CONJUNCT1);
          MATCH_MP_TAC SUBSET_TRANS THEN
          EXISTS_TAC `graph_component E (v:A)` THEN
          CONJ_TAC THENL
           [USE_THEN "v_side" (ACCEPT_TAC o CONJUNCT2);
            MATCH_ACCEPT_TAC
             (SET_RULE `(t:A->bool) SUBSET s UNION t`)]]]]]);;

let GRAPH_COMPONENT_EDGES_INSERT_BRIDGE_OUTSIDE = prove
 (`!E u v x:A.
        ~graph_reachable E u v /\
        ~(x IN graph_component E u UNION graph_component E v)
        ==> graph_component_edges ({u,v} INSERT E) x =
            graph_component_edges E x`,
  REPEAT GEN_TAC THEN INTRO_TAC "separate x_outside" THEN
  SUBGOAL_THEN
   `graph_component ({u:A,v} INSERT E) x = graph_component E x`
  (LABEL_TAC "component") THENL
   [MATCH_MP_TAC GRAPH_COMPONENT_INSERT_BRIDGE_OUTSIDE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~({u:A,v} SUBSET graph_component E x)`
  (LABEL_TAC "bridge_outside") THENL
   [REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
    DISCH_THEN(CONJUNCTS_THEN2
     (LABEL_TAC "u_component") (LABEL_TAC "v_component")) THEN
    SUBGOAL_THEN `x IN graph_component E (u:A)`
    (LABEL_TAC "x_u") THENL
     [REWRITE_TAC[IN_GRAPH_COMPONENT] THEN
      MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
      USE_THEN "u_component"
       (ACCEPT_TAC o REWRITE_RULE[IN_GRAPH_COMPONENT]);
      USE_THEN "x_outside" MP_TAC THEN
      REWRITE_TAC[IN_UNION] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `e:A->bool` THEN
  USE_THEN "component"
   (fun th -> REWRITE_TAC[IN_GRAPH_COMPONENT_EDGES; IN_INSERT; th]) THEN
  EQ_TAC THENL
   [INTRO_TAC "edge subset" THEN
    USE_THEN "edge"
     (DISJ_CASES_THEN2
       (LABEL_TAC "bridge") (LABEL_TAC "old_edge")) THENL
     [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["bridge_outside"; "subset"; "bridge"] THEN
      SET_TAC[];
      ASM_REWRITE_TAC[]];
    INTRO_TAC "edge subset" THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Passing recursive planar certificates across connected components.        *)
(* ------------------------------------------------------------------------- *)

let EULER_PLANAR_GRAPH_BRIDGE_COMPONENTS = prove
 (`!V E p q:A.
        euler_planar_graph V E /\
        p IN V /\
        q IN V /\
        ~graph_reachable E p q
        ==> ?u v:A.
              u IN graph_component E p /\
              v IN graph_component E q /\
              euler_planar_graph V ({u,v} INSERT E)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "euler p_vertex q_vertex separate" THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_graph] THEN
  INTRO_TAC "graph rotations" THEN
  SUBGOAL_THEN
   `?rp:(A#A)->A#A.
      euler_planar_rotation
       (graph_component E (p:A)) (graph_component_edges E p) rp`
  (X_CHOOSE_THEN `rp:(A#A)->A#A` (LABEL_TAC "p_rotation")) THENL
   [USE_THEN "rotations" (MATCH_MP_TAC o SPEC `p:A`) THEN
    USE_THEN "p_vertex" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?rq:(A#A)->A#A.
      euler_planar_rotation
       (graph_component E (q:A)) (graph_component_edges E q) rq`
  (X_CHOOSE_THEN `rq:(A#A)->A#A` (LABEL_TAC "q_rotation")) THENL
   [USE_THEN "rotations" (MATCH_MP_TAC o SPEC `q:A`) THEN
    USE_THEN "q_vertex" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph
     (graph_component E (p:A)) (graph_component_edges E p)`
  (LABEL_TAC "p_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A`]
     GRAPH_COMPONENT_EDGES_CONNECTED) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph
     (graph_component E (q:A)) (graph_component_edges E q)`
  (LABEL_TAC "q_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:A`]
     GRAPH_COMPONENT_EDGES_CONNECTED) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(graph_component E (p:A) = {})`
  (LABEL_TAC "p_nonempty") THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `p:A` THEN REWRITE_TAC[GRAPH_COMPONENT_REFL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(graph_component E (q:A) = {})`
  (LABEL_TAC "q_nonempty") THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `q:A` THEN REWRITE_TAC[GRAPH_COMPONENT_REFL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `DISJOINT (graph_component E (p:A)) (graph_component E q)`
  (LABEL_TAC "components_disjoint") THENL
   [MATCH_MP_TAC GRAPH_COMPONENTS_DISJOINT THEN
    USE_THEN "separate" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?u v:A. ?s:(A#A)->A#A.
      u IN graph_component E p /\
      v IN graph_component E q /\
      euler_planar_rotation
       (graph_component E p UNION graph_component E q)
       ({u,v} INSERT
        (graph_component_edges E p UNION graph_component_edges E q)) s`
  (X_CHOOSE_THEN `u:A`
   (X_CHOOSE_THEN `v:A`
    (X_CHOOSE_THEN `s:(A#A)->A#A`
     (CONJUNCTS_THEN2
       (LABEL_TAC "u_component")
       (CONJUNCTS_THEN2
         (LABEL_TAC "v_component")
         (LABEL_TAC "merged_rotation")))))) THENL
   [MATCH_MP_TAC(ISPECL
     [`graph_component E (p:A)`; `graph_component E (q:A)`;
      `graph_component_edges E p:(A->bool)->bool`;
      `graph_component_edges E q:(A->bool)->bool`;
      `rp:(A#A)->A#A`; `rq:(A#A)->A#A`]
     EULER_PLANAR_ROTATION_BRIDGE_CONNECTED) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `graph_reachable E (p:A) u`
  (LABEL_TAC "p_u") THENL
   [USE_THEN "u_component"
     (ACCEPT_TAC o REWRITE_RULE[IN_GRAPH_COMPONENT]);
    ALL_TAC] THEN
  SUBGOAL_THEN `graph_reachable E (q:A) v`
  (LABEL_TAC "q_v") THENL
   [USE_THEN "v_component"
     (ACCEPT_TAC o REWRITE_RULE[IN_GRAPH_COMPONENT]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_component E (u:A) = graph_component E p`
  (LABEL_TAC "u_component_eq") THENL
   [REWRITE_TAC[GRAPH_COMPONENT_EQ] THEN
    MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
    USE_THEN "p_u" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_component E (v:A) = graph_component E q`
  (LABEL_TAC "v_component_eq") THENL
   [REWRITE_TAC[GRAPH_COMPONENT_EQ] THEN
    MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
    USE_THEN "q_v" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_component_edges E (u:A) = graph_component_edges E p`
  (LABEL_TAC "u_edges_eq") THENL
   [MATCH_MP_TAC GRAPH_COMPONENT_EDGES_EQ THEN
    MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
    USE_THEN "p_u" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_component_edges E (v:A) = graph_component_edges E q`
  (LABEL_TAC "v_edges_eq") THENL
   [MATCH_MP_TAC GRAPH_COMPONENT_EDGES_EQ THEN
    MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
    USE_THEN "q_v" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_component E (p:A) SUBSET V`
  (LABEL_TAC "p_component_subset") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:A`]
     GRAPH_COMPONENT_SUBSET) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_component E (q:A) SUBSET V`
  (LABEL_TAC "q_component_subset") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:A`]
     GRAPH_COMPONENT_SUBSET) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(u:A) IN V` (LABEL_TAC "u_vertex") THENL
   [USE_THEN "p_component_subset"
     (MP_TAC o SPEC `u:A` o REWRITE_RULE[SUBSET]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v:A) IN V` (LABEL_TAC "v_vertex") THENL
   [USE_THEN "q_component_subset"
     (MP_TAC o SPEC `v:A` o REWRITE_RULE[SUBSET]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~graph_reachable E (u:A) v`
  (LABEL_TAC "bridge_separate") THENL
   [DISCH_THEN(LABEL_TAC "u_v") THEN
    USE_THEN "separate" MP_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN
    EXISTS_TAC `u:A` THEN CONJ_TAC THENL
     [USE_THEN "p_u" ACCEPT_TAC;
      MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN
      EXISTS_TAC `v:A` THEN CONJ_TAC THENL
       [USE_THEN "u_v" ACCEPT_TAC;
        MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
        USE_THEN "q_v" ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) = v)` (LABEL_TAC "distinct") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "bridge_separate" MP_TAC THEN
    REWRITE_TAC[GRAPH_REACHABLE_REFL];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) ({u,v} INSERT E)`
  (LABEL_TAC "inserted_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INSERT_EDGE THEN
    ASM_REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; PAIR_HAS_SIZE_2];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`u:A`; `v:A`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "u_component" ACCEPT_TAC;
    USE_THEN "v_component" ACCEPT_TAC;
    USE_THEN "inserted_graph" ACCEPT_TAC;
    X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "x_vertex") THEN
    ASM_CASES_TAC
     `(x:A) IN
      graph_component (E:(A->bool)->bool) (p:A) UNION
      graph_component E q` THENL
     [POP_ASSUM(LABEL_TAC "x_merged_base") THEN
      SUBGOAL_THEN
       `(x:A) IN graph_component E u UNION graph_component E v`
      (LABEL_TAC "x_merged") THENL
       [USE_THEN "u_component_eq" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "v_component_eq" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "x_merged_base" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `graph_component ({u:A,v} INSERT E) x =
        graph_component E p UNION graph_component E q`
      (LABEL_TAC "merged_component") THENL
       [USE_THEN "u_component_eq"
         (fun th -> REWRITE_TAC[GSYM th]) THEN
        USE_THEN "v_component_eq"
         (fun th -> REWRITE_TAC[GSYM th]) THEN
        MATCH_MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `u:A`; `v:A`; `x:A`]
         GRAPH_COMPONENT_INSERT_BRIDGE_MERGED) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `graph_component_edges ({u:A,v} INSERT E) x =
        {u,v} INSERT
        (graph_component_edges E p UNION graph_component_edges E q)`
      (LABEL_TAC "merged_edges") THENL
       [USE_THEN "u_edges_eq"
         (fun th -> REWRITE_TAC[GSYM th]) THEN
        USE_THEN "v_edges_eq"
         (fun th -> REWRITE_TAC[GSYM th]) THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
          `u:A`; `v:A`; `x:A`]
         GRAPH_COMPONENT_EDGES_INSERT_BRIDGE_MERGED) THEN
        ASM_REWRITE_TAC[];
        EXISTS_TAC `s:(A#A)->A#A` THEN
        USE_THEN "merged_component" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "merged_edges" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "merged_rotation" ACCEPT_TAC];
      POP_ASSUM(LABEL_TAC "x_outside_base") THEN
      SUBGOAL_THEN
       `~((x:A) IN graph_component E u UNION graph_component E v)`
      (LABEL_TAC "x_outside") THENL
       [USE_THEN "u_component_eq" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "v_component_eq" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "x_outside_base" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `?rx:(A#A)->A#A.
          euler_planar_rotation
           (graph_component E (x:A)) (graph_component_edges E x) rx`
      (X_CHOOSE_THEN `rx:(A#A)->A#A` (LABEL_TAC "old_rotation"))
      THENL
       [USE_THEN "rotations" (MATCH_MP_TAC o SPEC `x:A`) THEN
        USE_THEN "x_vertex" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `graph_component ({u:A,v} INSERT E) x = graph_component E x`
      (LABEL_TAC "outside_component") THENL
       [MATCH_MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `u:A`; `v:A`; `x:A`]
         GRAPH_COMPONENT_INSERT_BRIDGE_OUTSIDE) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `graph_component_edges ({u:A,v} INSERT E) x =
        graph_component_edges E x`
      (LABEL_TAC "outside_edges") THENL
       [MATCH_MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `u:A`; `v:A`; `x:A`]
         GRAPH_COMPONENT_EDGES_INSERT_BRIDGE_OUTSIDE) THEN
        ASM_REWRITE_TAC[];
        EXISTS_TAC `rx:(A#A)->A#A` THEN
        USE_THEN "outside_component" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "outside_edges" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "old_rotation" ACCEPT_TAC]]]);;

(* ------------------------------------------------------------------------- *)
(* Extension to maximal Euler-planar graphs.                                 *)
(* ------------------------------------------------------------------------- *)

let MAXIMAL_EULER_PLANAR_GRAPH_EXTENSION = prove
 (`!V E.
        euler_planar_graph (V:A->bool) E
        ==> ?E'.
              E SUBSET E' /\
              euler_planar_graph V E' /\
              (!E''.
                   E' PSUBSET E'' /\
                   E'' SUBSET complete_graph_edges V
                   ==> ~euler_planar_graph V E'')`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "euler") THEN
  ABBREV_TAC
   `candidates = {E':(A->bool)->bool |
       E SUBSET E' /\
       E' SUBSET complete_graph_edges V /\
       euler_planar_graph V E'}` THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC EULER_PLANAR_GRAPH_FINITE_SIMPLE THEN
    USE_THEN "euler" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite_vertices") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `E SUBSET complete_graph_edges (V:A->bool)`
  (LABEL_TAC "edges") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[FINITE_SIMPLE_GRAPH_EQ] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(candidates:((A->bool)->bool)->bool)`
  (LABEL_TAC "finite_candidates") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC
     `{E':(A->bool)->bool | E' SUBSET complete_graph_edges V}` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_POWERSET THEN
      MATCH_MP_TAC FINITE_COMPLETE_GRAPH_EDGES THEN
      USE_THEN "finite_vertices" ACCEPT_TAC;
      EXPAND_TAC "candidates" THEN
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(candidates:((A->bool)->bool)->bool = {})`
  (LABEL_TAC "candidates_nonempty") THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `E:(A->bool)->bool` THEN
    EXPAND_TAC "candidates" THEN
    REWRITE_TAC[IN_ELIM_THM; SUBSET_REFL] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPEC
   `candidates:((A->bool)->bool)->bool`
   FINITE_MAXIMAL_ELEMENT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `E':(A->bool)->bool`
     (CONJUNCTS_THEN2
       (LABEL_TAC "candidate") (LABEL_TAC "maximal")))] THEN
  USE_THEN "candidate" MP_TAC THEN
  EXPAND_TAC "candidates" THEN REWRITE_TAC[IN_ELIM_THM] THEN
  INTRO_TAC "contains within extended_euler" THEN
  EXISTS_TAC `E':(A->bool)->bool` THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `E'':(A->bool)->bool` THEN
  INTRO_TAC "proper allowed" THEN
  DISCH_THEN(LABEL_TAC "larger_euler") THEN
  USE_THEN "maximal" (MP_TAC o SPEC `E'':(A->bool)->bool`) THEN
  ANTS_TAC THENL
   [EXPAND_TAC "candidates" THEN REWRITE_TAC[IN_ELIM_THM] THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `E':(A->bool)->bool` THEN
      CONJ_TAC THENL
       [USE_THEN "contains" ACCEPT_TAC;
        USE_THEN "proper" MP_TAC THEN
        REWRITE_TAC[PSUBSET] THEN MESON_TAC[]];
      USE_THEN "allowed" ACCEPT_TAC;
      USE_THEN "larger_euler" ACCEPT_TAC];
    USE_THEN "proper" MP_TAC THEN
    REWRITE_TAC[PSUBSET] THEN MESON_TAC[]]);;

let MAXIMAL_EULER_PLANAR_GRAPH_EXTENSION_CONNECTED = prove
 (`!V E.
        euler_planar_graph (V:A->bool) E
        ==> ?E'.
              E SUBSET E' /\
              connected_graph V E' /\
              euler_planar_graph V E' /\
              (!E''.
                   E' PSUBSET E'' /\
                   E'' SUBSET complete_graph_edges V
                   ==> ~euler_planar_graph V E'')`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "euler") THEN
  MP_TAC(MATCH_MP
   (ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`]
     MAXIMAL_EULER_PLANAR_GRAPH_EXTENSION)
   (ASSUME `euler_planar_graph (V:A->bool) E`)) THEN
  INTRO_TAC "@E'. subset extended maximal" THEN
  SUBGOAL_THEN
   `connected_graph (V:A->bool) E'`
  (LABEL_TAC "connected") THENL
   [ASM_CASES_TAC `connected_graph (V:A->bool) E'` THEN
    ASM_REWRITE_TAC[] THEN
    POP_ASSUM(LABEL_TAC "not_connected") THEN
    USE_THEN "not_connected"
     (MP_TAC o
      REWRITE_RULE[connected_graph; NOT_FORALL_THM; NOT_IMP]) THEN
    INTRO_TAC "@p q. (p_vertex q_vertex) separate" THEN
    MP_TAC(MATCH_MP
     (ISPECL
       [`V:A->bool`; `E':(A->bool)->bool`; `p:A`; `q:A`]
       EULER_PLANAR_GRAPH_BRIDGE_COMPONENTS)
     (CONJ
       (ASSUME `euler_planar_graph (V:A->bool) E'`)
       (CONJ
         (ASSUME `(p:A) IN V`)
         (CONJ
           (ASSUME `(q:A) IN V`)
           (ASSUME `~graph_reachable
                     (E':(A->bool)->bool) p q`))))) THEN
    INTRO_TAC "@u v. u_component v_component larger_euler" THEN
    SUBGOAL_THEN
     `graph_reachable (E':(A->bool)->bool) p u`
    (LABEL_TAC "p_u") THENL
     [USE_THEN "u_component"
       (ACCEPT_TAC o REWRITE_RULE[IN_GRAPH_COMPONENT]);
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_reachable (E':(A->bool)->bool) q v`
    (LABEL_TAC "q_v") THENL
     [USE_THEN "v_component"
       (ACCEPT_TAC o REWRITE_RULE[IN_GRAPH_COMPONENT]);
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~graph_reachable (E':(A->bool)->bool) u v`
    (LABEL_TAC "bridge_separate") THENL
     [DISCH_THEN(LABEL_TAC "u_v") THEN
      USE_THEN "separate" MP_TAC THEN REWRITE_TAC[] THEN
      MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN
      EXISTS_TAC `u:A` THEN CONJ_TAC THENL
       [USE_THEN "p_u" ACCEPT_TAC;
        MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN
        EXISTS_TAC `v:A` THEN CONJ_TAC THENL
         [USE_THEN "u_v" ACCEPT_TAC;
          MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
          USE_THEN "q_v" ACCEPT_TAC]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~({u:A,v} IN E')`
    (LABEL_TAC "new_edge") THENL
     [DISCH_THEN(LABEL_TAC "edge") THEN
      USE_THEN "bridge_separate" MP_TAC THEN REWRITE_TAC[] THEN
      MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
      USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `E' PSUBSET ({u:A,v} INSERT E')`
    (LABEL_TAC "proper") THENL
     [USE_THEN "new_edge" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `({u:A,v} INSERT E') SUBSET complete_graph_edges V`
    (LABEL_TAC "allowed") THENL
     [MP_TAC(MATCH_MP
       (ISPECL
         [`V:A->bool`; `({u:A,v} INSERT E'):(A->bool)->bool`]
         EULER_PLANAR_GRAPH_FINITE_SIMPLE)
       (ASSUME
         `euler_planar_graph
           (V:A->bool) ({u:A,v} INSERT E')`)) THEN
      REWRITE_TAC[FINITE_SIMPLE_GRAPH_EQ] THEN MESON_TAC[];
      ALL_TAC] THEN
    USE_THEN "maximal"
     (MP_TAC o SPEC `({u:A,v} INSERT E')`) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `E':(A->bool)->bool` THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Equivalence of Euler, recursive, topological and straight-line planarity. *)
(* ------------------------------------------------------------------------- *)

let RECURSIVE_PLANAR_GRAPH_SUBSET_EDGES = prove
 (`!V E G.
        finite_simple_graph (V:A->bool) E /\
        E SUBSET G /\
        recursive_planar_graph V G
        ==> recursive_planar_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph subset recursive" THEN
  USE_THEN "recursive" MP_TAC THEN
  REWRITE_TAC[recursive_planar_graph] THEN
  INTRO_TAC "supergraph certificate" THEN
  REWRITE_TAC[recursive_planar_graph] THEN
  CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    USE_THEN "certificate"
     (DISJ_CASES_THEN2
       (LABEL_TAC "small") (LABEL_TAC "extension")) THENL
     [DISJ1_TAC THEN USE_THEN "small" ACCEPT_TAC;
      DISJ2_TAC THEN
      USE_THEN "extension" MP_TAC THEN
      INTRO_TAC "@H q. super_subset triangulated" THEN
      MAP_EVERY EXISTS_TAC [`H:(A->bool)->bool`; `q:num->A`] THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC SUBSET_TRANS THEN
        EXISTS_TAC `G:(A->bool)->bool` THEN
        ASM_REWRITE_TAC[];
        USE_THEN "triangulated" ACCEPT_TAC]]]);;

let EULER_PLANAR_GRAPH_IMP_RECURSIVE_PLANAR_GRAPH = prove
 (`!V E.
        euler_planar_graph (V:A->bool) E
        ==> recursive_planar_graph V E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "euler") THEN
  MP_TAC(MATCH_MP
   (ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`]
     MAXIMAL_EULER_PLANAR_GRAPH_EXTENSION_CONNECTED)
   (ASSUME `euler_planar_graph (V:A->bool) E`)) THEN
  INTRO_TAC "@G. subset connected extended maximal" THEN
  SUBGOAL_THEN
   `recursive_planar_graph (V:A->bool) G`
  (LABEL_TAC "recursive_supergraph") THENL
   [MATCH_MP_TAC
     CONNECTED_EULER_PLANAR_GRAPH_IMP_RECURSIVE_PLANAR_GRAPH THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `G:(A->bool)->bool`]
   RECURSIVE_PLANAR_GRAPH_SUBSET_EDGES) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC EULER_PLANAR_GRAPH_FINITE_SIMPLE THEN
  USE_THEN "euler" ACCEPT_TAC);;

let EULER_PLANAR_GRAPH_EQ_RECURSIVE_PLANAR_GRAPH = prove
 (`!V E.
        euler_planar_graph (V:A->bool) E <=>
        recursive_planar_graph V E`,
  MESON_TAC
   [EULER_PLANAR_GRAPH_IMP_RECURSIVE_PLANAR_GRAPH;
    RECURSIVE_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
    PLANAR_GRAPH_IMP_EULER_PLANAR_GRAPH]);;

let EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH = prove
 (`!V E.
        euler_planar_graph (V:A->bool) E <=>
        planar_graph V E`,
  MESON_TAC
   [EULER_PLANAR_GRAPH_IMP_RECURSIVE_PLANAR_GRAPH;
    RECURSIVE_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
    PLANAR_GRAPH_IMP_EULER_PLANAR_GRAPH]);;

let PLANAR_GRAPH_EQ_EULER_PLANAR_GRAPH = prove
 (`!V E.
        planar_graph (V:A->bool) E <=>
        euler_planar_graph V E`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH]);;

let PLANAR_GRAPH_EQ_EULER_ROTATIONS = prove
 (`!V E.
        planar_graph (V:A->bool) E <=>
        finite_simple_graph V E /\
        (!u. u IN V
             ==> ?r:(A#A)->A#A.
                   euler_planar_rotation
                     (graph_component E u)
                     (graph_component_edges E u) r)`,
  REWRITE_TAC[PLANAR_GRAPH_EQ_EULER_PLANAR_GRAPH;
              euler_planar_graph]);;

let EULER_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR = prove
 (`!V E.
        euler_planar_graph (V:A->bool) E <=>
        straight_line_planar_graph V E`,
  MESON_TAC
   [EULER_PLANAR_GRAPH_IMP_RECURSIVE_PLANAR_GRAPH;
    RECURSIVE_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR;
    RECURSIVE_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
    PLANAR_GRAPH_IMP_EULER_PLANAR_GRAPH]);;

(* ------------------------------------------------------------------------- *)
(* Topological nonplanarity consequences of Euler obstructions.              *)
(* ------------------------------------------------------------------------- *)

let NON_EULER_PLANAR_IMP_NON_PLANAR_GRAPH = prove
 (`!V E.
        ~euler_planar_graph (V:A->bool) E
        ==> ~planar_graph V E`,
  MESON_TAC[PLANAR_GRAPH_IMP_EULER_PLANAR_GRAPH]);;

let COMPLETE_BIPARTITE_3_3_NOT_PLANAR = prove
 (`!X Y:A->bool.
        X HAS_SIZE 3 /\ Y HAS_SIZE 3 /\ DISJOINT X Y
        ==> ~planar_graph
             (X UNION Y) (complete_bipartite_edges X Y)`,
  MESON_TAC[COMPLETE_BIPARTITE_3_3_NOT_EULER_PLANAR;
            NON_EULER_PLANAR_IMP_NON_PLANAR_GRAPH]);;

let COMPLETE_GRAPH_5_SUBGRAPH_OBSTRUCTS_PLANARITY = prove
 (`!V E W:A->bool.
        W HAS_SIZE 5 /\
        W SUBSET V /\
        complete_graph_edges W SUBSET E
        ==> ~planar_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "size vertices edges" THEN
  DISCH_THEN(LABEL_TAC "planar") THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `W:A->bool`;
    `complete_graph_edges W:(A->bool)->bool`]
   PLANAR_GRAPH_SUBGRAPH) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "complete_edge") THEN
    CONJ_TAC THENL
     [USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "complete_edge" ACCEPT_TAC;
      USE_THEN "complete_edge"
       (ACCEPT_TAC o REWRITE_RULE[SUBSET] o CONJUNCT1 o
        REWRITE_RULE[IN_COMPLETE_GRAPH_EDGES])];
    DISCH_THEN(LABEL_TAC "subgraph_planar") THEN
    MP_TAC(ISPEC `W:A->bool`
      COMPLETE_GRAPH_5_NOT_PLANAR) THEN
    ASM_REWRITE_TAC[]]);;

let COMPLETE_BIPARTITE_3_3_SUBGRAPH_OBSTRUCTS_PLANARITY = prove
 (`!V E X Y:A->bool.
        X HAS_SIZE 3 /\
        Y HAS_SIZE 3 /\
        DISJOINT X Y /\
        X UNION Y SUBSET V /\
        complete_bipartite_edges X Y SUBSET E
        ==> ~planar_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "xsize ysize disjoint vertices edges" THEN
  DISCH_THEN(LABEL_TAC "planar") THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `X UNION Y:A->bool`;
    `complete_bipartite_edges X Y:(A->bool)->bool`]
   PLANAR_GRAPH_SUBGRAPH) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "bipartite_edge") THEN
    CONJ_TAC THENL
     [USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "bipartite_edge" ACCEPT_TAC;
      USE_THEN "bipartite_edge" MP_TAC THEN
      REWRITE_TAC[IN_COMPLETE_BIPARTITE_EDGES] THEN SET_TAC[]];
    DISCH_THEN(LABEL_TAC "subgraph_planar") THEN
    MP_TAC(ISPECL [`X:A->bool`; `Y:A->bool`]
      COMPLETE_BIPARTITE_3_3_NOT_PLANAR) THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Kuratowski-style necessary conditions from subdivision certificates.      *)
(* ------------------------------------------------------------------------- *)

let GRAPH_SUBGRAPH_IMP_TOPOLOGICAL_SUBGRAPH = prove
 (`!V E W D.
        finite_simple_graph (W:A->bool) D /\
        W SUBSET V /\
        D SUBSET induced_subgraph_edges E W
        ==> graph_topological_subgraph W D V E`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_topological_subgraph] THEN
  INTRO_TAC "graph vertices edges" THEN
  MAP_EVERY EXISTS_TAC
   [`W:A->bool`; `D:(A->bool)->bool`] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(CONJUNCT1 graph_subdivision_RULES) THEN
  USE_THEN "graph" ACCEPT_TAC);;

let COMPLETE_GRAPH_5_TOPOLOGICAL_SUBGRAPH_OBSTRUCTS_PLANARITY = prove
 (`!V E W:A->bool.
        W HAS_SIZE 5 /\
        graph_topological_subgraph
          W (complete_graph_edges W) V E
        ==> ~planar_graph V E`,
  MESON_TAC[PLANAR_GRAPH_TOPOLOGICAL_SUBGRAPH;
            COMPLETE_GRAPH_5_NOT_PLANAR]);;

let COMPLETE_BIPARTITE_3_3_TOPOLOGICAL_SUBGRAPH_OBSTRUCTS_PLANARITY = prove
 (`!V E X Y:A->bool.
        X HAS_SIZE 3 /\
        Y HAS_SIZE 3 /\
        DISJOINT X Y /\
        graph_topological_subgraph
          (X UNION Y) (complete_bipartite_edges X Y) V E
        ==> ~planar_graph V E`,
  MESON_TAC[PLANAR_GRAPH_TOPOLOGICAL_SUBGRAPH;
            COMPLETE_BIPARTITE_3_3_NOT_PLANAR]);;

(* ------------------------------------------------------------------------- *)
(* Euler-planarity consequences of the characterization theorem.             *)
(* ------------------------------------------------------------------------- *)

let EULER_PLANAR_GRAPH_EDGE_BOUND = prove
 (`!V E.
        euler_planar_graph (V:A->bool) E /\
        3 <= CARD V
        ==> CARD E + 6 <= 3 * CARD V`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_RECURSIVE_PLANAR_GRAPH;
            RECURSIVE_PLANAR_GRAPH_EDGE_BOUND]);;

let COMPLETE_GRAPH_5_TOPOLOGICAL_SUBGRAPH_OBSTRUCTS_EULER_PLANARITY = prove
 (`!V E W:A->bool.
        W HAS_SIZE 5 /\
        graph_topological_subgraph
          W (complete_graph_edges W) V E
        ==> ~euler_planar_graph V E`,
  MESON_TAC[COMPLETE_GRAPH_5_TOPOLOGICAL_SUBGRAPH_OBSTRUCTS_PLANARITY;
            EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH]);;

let COMPLETE_BIPARTITE_3_3_TOPOLOGICAL_SUBGRAPH_OBSTRUCTS_EULER_PLANARITY =
  prove
   (`!V E X Y:A->bool.
          X HAS_SIZE 3 /\
          Y HAS_SIZE 3 /\
          DISJOINT X Y /\
          graph_topological_subgraph
            (X UNION Y) (complete_bipartite_edges X Y) V E
          ==> ~euler_planar_graph V E`,
    MESON_TAC
     [COMPLETE_BIPARTITE_3_3_TOPOLOGICAL_SUBGRAPH_OBSTRUCTS_PLANARITY;
      EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH]);;

(* ========================================================================= *)
(* Kuratowski's characterization by subdivisions.                            *)
(* ========================================================================= *)

(* ------------------------------------------------------------------------- *)
(* Vertex connectivity and simplicial edge contraction.                      *)
(*                                                                           *)
(* Connectivity is expressed by deletion of fewer than k vertices.           *)
(* ------------------------------------------------------------------------- *)

let vertex_k_connected_graph = new_definition
 `vertex_k_connected_graph k (V:A->bool) (E:(A->bool)->bool) <=>
        finite_simple_graph V E /\
        k < CARD V /\
        !S. S SUBSET V /\ CARD S < k
            ==> connected_graph
                 (V DIFF S) (induced_subgraph_edges E (V DIFF S))`;;

let graph_vertex_separator = new_definition
 `graph_vertex_separator
    (V:A->bool) (E:(A->bool)->bool) (S:A->bool) <=>
        S SUBSET V /\
        ~connected_graph
          (V DIFF S) (induced_subgraph_edges E (V DIFF S))`;;

let VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE = prove
 (`!k V E.
        vertex_k_connected_graph k (V:A->bool) E
        ==> finite_simple_graph V E`,
  SIMP_TAC[vertex_k_connected_graph]);;

let VERTEX_K_CONNECTED_GRAPH_CARD = prove
 (`!k V E.
        vertex_k_connected_graph k (V:A->bool) E
        ==> k < CARD V`,
  SIMP_TAC[vertex_k_connected_graph]);;

let VERTEX_K_CONNECTED_GRAPH_DELETE_LT = prove
 (`!k V E S.
        vertex_k_connected_graph k (V:A->bool) E /\
        S SUBSET V /\
        CARD S < k
        ==> connected_graph
             (V DIFF S) (induced_subgraph_edges E (V DIFF S))`,
  SIMP_TAC[vertex_k_connected_graph]);;

let VERTEX_K_CONNECTED_GRAPH_EQ_NO_SMALL_SEPARATOR = prove
 (`!k V E.
        vertex_k_connected_graph k (V:A->bool) E <=>
        finite_simple_graph V E /\
        k < CARD V /\
        !S. S SUBSET V /\ CARD S < k
            ==> ~graph_vertex_separator V E S`,
  REWRITE_TAC[vertex_k_connected_graph; graph_vertex_separator] THEN
  MESON_TAC[]);;

let VERTEX_K_CONNECTED_GRAPH_MONO = prove
 (`!k l V E.
        vertex_k_connected_graph k (V:A->bool) E /\
        l <= k
        ==> vertex_k_connected_graph l V E`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[vertex_k_connected_graph] THEN
  INTRO_TAC "(graph k_card deletion) bound" THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_ARITH_TAC;
    X_GEN_TAC `S:A->bool` THEN INTRO_TAC "subset size" THEN
    USE_THEN "deletion" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]);;

let VERTEX_K_CONNECTED_GRAPH_CONNECTED = prove
 (`!k V E.
        vertex_k_connected_graph k (V:A->bool) E /\
        0 < k
        ==> connected_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected positive" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `k:num` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`k:num`; `V:A->bool`; `E:(A->bool)->bool`; `{}:A->bool`]
   VERTEX_K_CONNECTED_GRAPH_DELETE_LT) THEN
  ASM_REWRITE_TAC[EMPTY_SUBSET; CARD_CLAUSES; DIFF_EMPTY] THEN
  DISCH_THEN(fun th ->
    ACCEPT_TAC
     (REWRITE_RULE
       [MATCH_MP FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH_SELF
         (ASSUME `finite_simple_graph (V:A->bool) E`)] th)));;

let VERTEX_2_CONNECTED_GRAPH_DELETE_VERTEX = prove
 (`!V E v:A.
        vertex_k_connected_graph 2 V E /\
        v IN V
        ==> connected_graph
             (V DELETE v)
             (induced_subgraph_edges E (V DELETE v))`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected vertex" THEN
  MP_TAC(ISPECL
   [`2`; `V:A->bool`; `E:(A->bool)->bool`; `{v:A}`]
   VERTEX_K_CONNECTED_GRAPH_DELETE_LT) THEN
  ASM_REWRITE_TAC[SING_SUBSET; CARD_SING; SET_RULE
   `(V:A->bool) DIFF {v} = V DELETE v`] THEN
  ARITH_TAC);;

let VERTEX_3_CONNECTED_GRAPH_DELETE_PAIR = prove
 (`!V E u v:A.
        vertex_k_connected_graph 3 V E /\
        u IN V /\ v IN V /\ ~(u = v)
        ==> connected_graph
             (V DIFF {u,v})
             (induced_subgraph_edges E (V DIFF {u,v}))`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected u_vertex v_vertex distinct" THEN
  MP_TAC(ISPECL
   [`3`; `V:A->bool`; `E:(A->bool)->bool`; `{u:A,v}`]
   VERTEX_K_CONNECTED_GRAPH_DELETE_LT) THEN
  ASM_REWRITE_TAC[INSERT_SUBSET; EMPTY_SUBSET] THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[CARD_CLAUSES; FINITE_SING; CARD_SING; IN_SING] THEN
    ARITH_TAC;
    DISCH_THEN ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* Simplicial contraction: u is identified with v.                           *)
(*                                                                           *)
(* The edge {u,v} becomes a loop and is suppressed. Common neighbours of u   *)
(* and v create duplicate edges, which disappear automatically because edge  *)
(* collections are sets.                                                     *)
(* ------------------------------------------------------------------------- *)

let graph_contract_vertex = new_definition
 `graph_contract_vertex (u:A) v x = if x = u then v else x`;;

let graph_contract_edges = new_definition
 `graph_contract_edges
    (V:A->bool) (E:(A->bool)->bool) u v =
      induced_subgraph_edges E (V DELETE u) UNION
      IMAGE (\w:A. {v,w}) (graph_neighbors E u DELETE v)`;;

let GRAPH_CONTRACT_VERTEX_LEFT = prove
 (`!u v:A. graph_contract_vertex u v u = v`,
  REWRITE_TAC[graph_contract_vertex]);;

let GRAPH_CONTRACT_VERTEX_AWAY = prove
 (`!u v x:A.
        ~(x = u) ==> graph_contract_vertex u v x = x`,
  SIMP_TAC[graph_contract_vertex]);;

let IMAGE_GRAPH_CONTRACT_VERTEX = prove
 (`!V u v:A.
        u IN V /\ v IN V /\ ~(u = v)
        ==> IMAGE (graph_contract_vertex u v) V = V DELETE u`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[EXTENSION; IN_IMAGE; IN_DELETE; graph_contract_vertex] THEN
  SET_TAC[]);;

let IN_GRAPH_CONTRACT_EDGES = prove
 (`!V E u v e:A->bool.
        e IN graph_contract_edges V E u v <=>
        (e IN E /\ e SUBSET V DELETE u) \/
        ?w. w IN graph_neighbors E u /\ ~(w = v) /\ e = {v,w}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_contract_edges; IN_UNION;
              IN_INDUCED_SUBGRAPH_EDGES; IN_IMAGE; IN_DELETE] THEN
  MESON_TAC[]);;

let GRAPH_CONTRACT_EDGES_OLD_SUBSET = prove
 (`!V E u v:A.
        induced_subgraph_edges E (V DELETE u) SUBSET
        graph_contract_edges V E u v`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_contract_edges; SUBSET_UNION]);;

let FINITE_SIMPLE_GRAPH_CONTRACT = prove
 (`!V E u v:A.
        finite_simple_graph V E /\
        u IN V /\ v IN V /\ ~(u = v)
        ==> finite_simple_graph
             (V DELETE u) (graph_contract_edges V E u v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph u_vertex v_vertex distinct" THEN
  REWRITE_TAC[FINITE_SIMPLE_GRAPH_EQ] THEN CONJ_TAC THENL
   [REWRITE_TAC[FINITE_DELETE] THEN
    USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    REWRITE_TAC[graph_contract_edges; UNION_SUBSET] THEN CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES;
                  IN_COMPLETE_GRAPH_EDGES] THEN
      X_GEN_TAC `e:A->bool` THEN INTRO_TAC "edge subset" THEN
      CONJ_TAC THENL
       [USE_THEN "subset" ACCEPT_TAC;
        USE_THEN "graph" MP_TAC THEN
        REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[]];
      REWRITE_TAC[SUBSET; IN_IMAGE; IN_COMPLETE_GRAPH_EDGES] THEN
      X_GEN_TAC `e:A->bool` THEN
      INTRO_TAC "@w. edge_value neighbor" THEN
      USE_THEN "edge_value" SUBST1_TAC THEN
      USE_THEN "neighbor" MP_TAC THEN REWRITE_TAC[IN_DELETE] THEN
      INTRO_TAC "u_neighbor not_v" THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `w:A`]
       FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
      ASM_REWRITE_TAC[] THEN
      INTRO_TAC "w_vertex not_u" THEN CONJ_TAC THENL
       [ASM SET_TAC[];
        REWRITE_TAC[PAIR_HAS_SIZE_2] THEN ASM_MESON_TAC[]]]]);;

let GRAPH_CONTRACT_EDGE_HOMOMORPHISM = prove
 (`!V E u v x y:A.
        finite_simple_graph V E /\
        u IN V /\ v IN V /\ ~(u = v) /\
        {x,y} IN E
        ==> graph_contract_vertex u v x =
            graph_contract_vertex u v y \/
            {graph_contract_vertex u v x,
             graph_contract_vertex u v y}
            IN graph_contract_edges V E u v`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph u_vertex v_vertex distinct edge" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `x:A`; `y:A`]
   FINITE_SIMPLE_GRAPH_DART) THEN
  ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN
  INTRO_TAC "x_vertex y_vertex xy_distinct" THEN
  ASM_CASES_TAC `(x:A) = u` THENL
   [SUBGOAL_THEN `~((y:A) = u)` (LABEL_TAC "y_not_u") THENL
     [ASM_MESON_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[graph_contract_vertex] THEN
    ASM_CASES_TAC `(y:A) = v` THENL
     [ASM_REWRITE_TAC[];
      DISJ2_TAC THEN REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN
      DISJ2_TAC THEN EXISTS_TAC `y:A` THEN
      ASM_REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN ASM_MESON_TAC[]];
    ASM_CASES_TAC `(y:A) = u` THENL
     [ASM_REWRITE_TAC[graph_contract_vertex] THEN
      ASM_CASES_TAC `(x:A) = v` THENL
       [ASM_REWRITE_TAC[];
        DISJ2_TAC THEN REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN
        DISJ2_TAC THEN EXISTS_TAC `x:A` THEN
        ASM_REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
        ASM_MESON_TAC[SET_RULE `{u:A,x} = {x,u}`]];
      ASM_REWRITE_TAC[graph_contract_vertex] THEN
      REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN
      DISJ1_TAC THEN ASM_REWRITE_TAC[] THEN
      ASM SET_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* Reachability is preserved by graph homomorphisms that may collapse edges. *)
(* ------------------------------------------------------------------------- *)

let GRAPH_REACHABLE_HOMOMORPHISM = prove
 (`!E:(A->bool)->bool. !D:(B->bool)->bool. !f:A->B. !x y.
        (!a b. {a,b} IN E ==> f a = f b \/ {f a,f b} IN D) /\
        graph_reachable E x y
        ==> graph_reachable D (f x) (f y)`,
  REPEAT GEN_TAC THEN INTRO_TAC "homomorphism reachable" THEN
  USE_THEN "reachable" (MP_TAC o REWRITE_RULE[graph_reachable]) THEN
  SPEC_TAC(`y:A`,`y:A`) THEN SPEC_TAC(`x:A`,`x:A`) THEN
  MATCH_MP_TAC RTC_INDUCT THEN REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`a:A`; `b:A`] THEN
    DISCH_THEN(LABEL_TAC "edge") THEN
    USE_THEN "homomorphism" (fun h ->
     USE_THEN "edge" (fun eth ->
      MP_TAC(MATCH_MP (SPECL [`a:A`; `b:A`] h)
                      (REWRITE_RULE[] eth)))) THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "same")
      (LABEL_TAC "mapped_edge")) THENL
     [ASM_REWRITE_TAC[GRAPH_REACHABLE_REFL];
      MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
      USE_THEN "mapped_edge" ACCEPT_TAC];
    X_GEN_TAC `a:A` THEN MATCH_ACCEPT_TAC GRAPH_REACHABLE_REFL;
    MAP_EVERY X_GEN_TAC [`a:A`; `b:A`; `c:A`] THEN
    MATCH_ACCEPT_TAC GRAPH_REACHABLE_TRANS]);;

let CONNECTED_GRAPH_CONTRACT = prove
 (`!V E u v:A.
        finite_simple_graph V E /\
        connected_graph V E /\
        u IN V /\ v IN V /\ ~(u = v)
        ==> connected_graph
             (V DELETE u) (graph_contract_edges V E u v)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph connected u_vertex v_vertex distinct" THEN
  REWRITE_TAC[connected_graph] THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
  INTRO_TAC "x_vertex y_vertex" THEN
  SUBGOAL_THEN `graph_reachable (E:(A->bool)->bool) x y`
  (LABEL_TAC "reachable") THENL
   [USE_THEN "connected" MP_TAC THEN REWRITE_TAC[connected_graph] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["x_vertex"; "y_vertex"] THEN
    REWRITE_TAC[IN_DELETE] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`E:(A->bool)->bool`;
    `graph_contract_edges (V:A->bool) E u v`;
    `graph_contract_vertex (u:A) v`; `x:A`; `y:A`]
   GRAPH_REACHABLE_HOMOMORPHISM) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`a:A`; `b:A`] THEN
      DISCH_THEN(LABEL_TAC "edge") THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
        `a:A`; `b:A`]
       GRAPH_CONTRACT_EDGE_HOMOMORPHISM) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "reachable" ACCEPT_TAC];
    MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["x_vertex"; "y_vertex"] THEN
    SIMP_TAC[graph_contract_vertex; IN_DELETE]]);;

(* ------------------------------------------------------------------------- *)
(* Vertex deletion and connectivity under simplicial contraction.            *)
(* ------------------------------------------------------------------------- *)

let INDUCED_GRAPH_CONTRACT_EDGES_DELETE_MERGED = prove
 (`!V E u v S:A->bool.
        v IN S
        ==> induced_subgraph_edges (graph_contract_edges V E u v)
              ((V DELETE u) DIFF S) =
            induced_subgraph_edges E ((V DELETE u) DIFF S)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "deleted") THEN
  REWRITE_TAC[EXTENSION; IN_INDUCED_SUBGRAPH_EDGES;
              IN_GRAPH_CONTRACT_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN ASM SET_TAC[]);;

let INDUCED_GRAPH_CONTRACT_EDGES_AWAY = prove
 (`!V E u v S:A->bool.
        finite_simple_graph V E /\
        u IN V /\ v IN V /\ ~(u = v) /\
        S SUBSET V DELETE u /\ ~(v IN S)
        ==> induced_subgraph_edges (graph_contract_edges V E u v)
              ((V DELETE u) DIFF S) =
            graph_contract_edges (V DIFF S)
              (induced_subgraph_edges E (V DIFF S)) u v`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph u_vertex v_vertex distinct subset v_not_deleted" THEN
  SUBGOAL_THEN
   `!w:A. w IN graph_neighbors E u ==> w IN V /\ ~(w = u)`
  (LABEL_TAC "neighbor_data") THENL
   [ASM_MESON_TAC[FINITE_SIMPLE_GRAPH_NEIGHBOR];
    ALL_TAC] THEN
  REWRITE_TAC[EXTENSION; IN_INDUCED_SUBGRAPH_EDGES;
              IN_GRAPH_CONTRACT_EDGES; IN_GRAPH_NEIGHBORS] THEN
  X_GEN_TAC `e:A->bool` THEN EQ_TAC THENL
   [INTRO_TAC "contract target" THEN
    USE_THEN "contract"
     (DISJ_CASES_THEN2 (LABEL_TAC "old") (LABEL_TAC "new")) THENL
     [DISJ1_TAC THEN ASM SET_TAC[];
      USE_THEN "new" MP_TAC THEN
      INTRO_TAC "@w. edge not_v edge_value" THEN
      SUBGOAL_THEN `(w:A) IN V /\ ~(w = u)`
      (LABEL_TAC "w_data") THENL
       [USE_THEN "neighbor_data" MATCH_MP_TAC THEN
        REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
        USE_THEN "edge" ACCEPT_TAC;
        ALL_TAC] THEN
      DISJ2_TAC THEN EXISTS_TAC `w:A` THEN ASM SET_TAC[]];
    DISCH_THEN
     (DISJ_CASES_THEN2 (LABEL_TAC "old") (LABEL_TAC "new")) THENL
     [CONJ_TAC THENL
       [DISJ1_TAC THEN ASM SET_TAC[];
        ASM SET_TAC[]];
      USE_THEN "new" MP_TAC THEN
      INTRO_TAC "@w. (edge edge_vertices) not_v edge_value" THEN
      SUBGOAL_THEN `(w:A) IN V /\ ~(w = u)`
      (LABEL_TAC "w_data") THENL
       [USE_THEN "neighbor_data" MATCH_MP_TAC THEN
        REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
        USE_THEN "edge" ACCEPT_TAC;
        ALL_TAC] THEN
      CONJ_TAC THENL
       [DISJ2_TAC THEN EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[];
        ASM SET_TAC[]]]]);;

let VERTEX_K_CONNECTED_GRAPH_CONTRACT = prove
 (`!k V E u v:A.
        vertex_k_connected_graph k V E /\
        u IN V /\ v IN V /\ ~(u = v) /\ 0 < k
        ==> vertex_k_connected_graph (k - 1)
             (V DELETE u) (graph_contract_edges V E u v)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "connected u_vertex v_vertex distinct positive" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `k:num` THEN USE_THEN "connected" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite_vertices") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `k < CARD(V:A->bool)` (LABEL_TAC "card") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_CARD THEN
    EXISTS_TAC `E:(A->bool)->bool` THEN
    USE_THEN "connected" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[vertex_k_connected_graph] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_CONTRACT THEN ASM_REWRITE_TAC[];
    ASM_SIMP_TAC[CARD_DELETE] THEN ASM_ARITH_TAC;
    X_GEN_TAC `S:A->bool` THEN INTRO_TAC "subset size" THEN
    SUBGOAL_THEN `FINITE(S:A->bool)` (LABEL_TAC "finite_deleted") THENL
     [MATCH_MP_TAC FINITE_SUBSET THEN EXISTS_TAC `V:A->bool` THEN
      ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
      ALL_TAC] THEN
    ASM_CASES_TAC `(v:A) IN S` THENL
     [REWRITE_TAC
       [MATCH_MP
         (ISPECL
           [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`; `S:A->bool`]
           INDUCED_GRAPH_CONTRACT_EDGES_DELETE_MERGED)
         (ASSUME `(v:A) IN S`)] THEN
      MP_TAC(ISPECL
       [`k:num`; `V:A->bool`; `E:(A->bool)->bool`;
        `u INSERT S:A->bool`]
       VERTEX_K_CONNECTED_GRAPH_DELETE_LT) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [USE_THEN "connected" ACCEPT_TAC;
          ASM SET_TAC[];
          ASM_SIMP_TAC[CARD_CLAUSES] THEN ASM_ARITH_TAC];
        DISCH_THEN(fun th ->
         ACCEPT_TAC
          (REWRITE_RULE
            [SET_RULE
              `V DIFF (u INSERT S:A->bool) =
               (V DELETE u) DIFF S`] th))];
      SUBGOAL_THEN
       `induced_subgraph_edges
          (graph_contract_edges (V:A->bool) (E:(A->bool)->bool)
             (u:A) (v:A))
          (((V:A->bool) DELETE u) DIFF (S:A->bool)) =
        graph_contract_edges ((V:A->bool) DIFF S)
          (induced_subgraph_edges (E:(A->bool)->bool)
             ((V:A->bool) DIFF S))
          (u:A) (v:A)`
      (LABEL_TAC "contract_edges") THENL
       [MATCH_MP_TAC INDUCED_GRAPH_CONTRACT_EDGES_AWAY THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`(V:A->bool) DIFF S`;
        `induced_subgraph_edges (E:(A->bool)->bool)
           ((V:A->bool) DIFF S)`;
        `u:A`; `v:A`]
       CONNECTED_GRAPH_CONTRACT) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THENL
         [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH THEN
          EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[] THEN SET_TAC[];
          MATCH_MP_TAC(ISPECL
           [`k:num`; `V:A->bool`; `E:(A->bool)->bool`; `S:A->bool`]
           VERTEX_K_CONNECTED_GRAPH_DELETE_LT) THEN
          REPEAT CONJ_TAC THENL
           [USE_THEN "connected" ACCEPT_TAC;
            ASM SET_TAC[];
            MATCH_MP_TAC LT_TRANS THEN EXISTS_TAC `k - 1` THEN
            ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
          ASM SET_TAC[];
          ASM SET_TAC[];
          USE_THEN "distinct" ACCEPT_TAC];
        DISCH_THEN(fun th ->
         ACCEPT_TAC
          (REWRITE_RULE
            [SET_RULE
              `((V:A->bool) DIFF S) DELETE u =
               (V DELETE u) DIFF S`;
             GSYM
              (ASSUME
                `induced_subgraph_edges
                   (graph_contract_edges
                     (V:A->bool) (E:(A->bool)->bool) u v)
                   ((V DELETE u) DIFF S) =
                 graph_contract_edges (V DIFF S)
                   (induced_subgraph_edges E (V DIFF S)) u v`)] th))]]]);;

let VERTEX_3_CONNECTED_GRAPH_CONTRACT_2_CONNECTED = prove
 (`!V E u v:A.
        vertex_k_connected_graph 3 V E /\
        u IN V /\ v IN V /\ ~(u = v)
        ==> vertex_k_connected_graph 2 (V DELETE u)
             (graph_contract_edges V E u v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected u_vertex v_vertex distinct" THEN
  MP_TAC(ISPECL
   [`3`; `V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
   VERTEX_K_CONNECTED_GRAPH_CONTRACT) THEN
  ASM_REWRITE_TAC[] THEN ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* Separators created by simplicial contraction.                             *)
(* ------------------------------------------------------------------------- *)

let VERTEX_3_CONNECTED_GRAPH_CONTRACT_SMALL_SEPARATOR = prove
 (`!V E u v S:A->bool.
        vertex_k_connected_graph 3 V E /\
        u IN V /\ v IN V /\ ~(u = v) /\
        graph_vertex_separator (V DELETE u)
          (graph_contract_edges V E u v) S /\
        CARD S < 3
        ==> v IN S`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "connected u_vertex v_vertex distinct separator small" THEN
  USE_THEN "separator" MP_TAC THEN
  REWRITE_TAC[graph_vertex_separator] THEN
  INTRO_TAC "subset not_connected" THEN
  ASM_CASES_TAC `(v:A) IN S` THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `3` THEN USE_THEN "connected" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `induced_subgraph_edges
      (graph_contract_edges (V:A->bool) (E:(A->bool)->bool) u v)
      ((V DELETE u) DIFF S) =
    graph_contract_edges (V DIFF S)
      (induced_subgraph_edges E (V DIFF S)) u v`
  (LABEL_TAC "contract_edges") THENL
   [MATCH_MP_TAC INDUCED_GRAPH_CONTRACT_EDGES_AWAY THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(V:A->bool) DIFF S`;
    `induced_subgraph_edges (E:(A->bool)->bool) ((V:A->bool) DIFF S)`;
    `u:A`; `v:A`]
   CONNECTED_GRAPH_CONTRACT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH THEN
      EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[] THEN SET_TAC[];
      MATCH_MP_TAC(ISPECL
       [`3`; `V:A->bool`; `E:(A->bool)->bool`; `S:A->bool`]
       VERTEX_K_CONNECTED_GRAPH_DELETE_LT) THEN
      ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
      ASM SET_TAC[];
      ASM SET_TAC[];
      USE_THEN "distinct" ACCEPT_TAC];
    DISCH_THEN(fun th ->
      let cth =
        REWRITE_RULE
         [SET_RULE
           `((V:A->bool) DIFF S) DELETE u = (V DELETE u) DIFF S`;
          GSYM
           (ASSUME
             `induced_subgraph_edges
                (graph_contract_edges
                  (V:A->bool) (E:(A->bool)->bool) u v)
                ((V DELETE u) DIFF S) =
              graph_contract_edges (V DIFF S)
                (induced_subgraph_edges E (V DIFF S)) u v`)] th in
      CONTR_TAC
       (MP
         (NOT_ELIM
           (ASSUME
             `~connected_graph ((V:A->bool) DELETE u DIFF S)
                (induced_subgraph_edges
                  (graph_contract_edges V (E:(A->bool)->bool) u v)
                  (V DELETE u DIFF S))`))
         cth))]);;

(* ------------------------------------------------------------------------- *)
(* Components arising from adjacent three-vertex separators.                 *)
(* ------------------------------------------------------------------------- *)

let graph_adjacent_separator_component = new_definition
 `graph_adjacent_separator_component
    (V:A->bool) (E:(A->bool)->bool) (C:A->bool) <=>
      ?u v w x.
        {u,v} IN E /\
        ~(u = v) /\ ~(u = w) /\ ~(v = w) /\
        graph_vertex_separator V E {u,v,w} /\
        x IN V DIFF {u,v,w} /\
        C = graph_component
             (induced_subgraph_edges E (V DIFF {u,v,w})) x`;;

(* ------------------------------------------------------------------------- *)
(* Thomassen's contractible-edge theorem for 3-connected graphs.             *)
(* ------------------------------------------------------------------------- *)

(* ------------------------------------------------------------------------- *)
(* A failed contraction yields a three-vertex separator containing the two   *)
(* endpoints of the contracted edge.                                         *)
(* ------------------------------------------------------------------------- *)

let VERTEX_3_CONNECTED_GRAPH_FAILED_CONTRACTION_SEPARATOR = prove
 (`!V E u v:A.
        vertex_k_connected_graph 3 V E /\
        5 <= CARD V /\
        {u,v} IN E /\
        ~vertex_k_connected_graph 3
          (V DELETE u) (graph_contract_edges V E u v)
        ==> ?w.
              w IN V /\ ~(w = u) /\ ~(w = v) /\
              graph_vertex_separator V E {u,v,w}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "connected large edge contraction_fails" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `3` THEN USE_THEN "connected" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(u:A) IN V /\ (v:A) IN V /\ ~(u = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
    (LABEL_TAC "distinct"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite_vertices") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph
      ((V:A->bool) DELETE u) (graph_contract_edges V E u v)`
  (LABEL_TAC "contract_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_CONTRACT THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `3 < CARD((V:A->bool) DELETE u)`
  (LABEL_TAC "contract_card") THENL
   [ASM_SIMP_TAC[CARD_DELETE] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?S:A->bool.
      S SUBSET V DELETE u /\ CARD S < 3 /\
      ~connected_graph
        ((V DELETE u) DIFF S)
        (induced_subgraph_edges (graph_contract_edges V E u v)
          ((V DELETE u) DIFF S))`
  (X_CHOOSE_THEN `S:A->bool`
   (CONJUNCTS_THEN2 (LABEL_TAC "separator_subset")
    (CONJUNCTS_THEN2 (LABEL_TAC "separator_small")
      (LABEL_TAC "separator_disconnect")))) THENL
   [USE_THEN "contraction_fails" MP_TAC THEN
    REWRITE_TAC[vertex_k_connected_graph] THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_vertex_separator
      ((V:A->bool) DELETE u) (graph_contract_edges V E u v) S`
  (LABEL_TAC "separator") THENL
   [ASM_REWRITE_TAC[graph_vertex_separator];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v:A) IN S` (LABEL_TAC "merged_in_separator") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`; `S:A->bool`]
     VERTEX_3_CONNECTED_GRAPH_CONTRACT_SMALL_SEPARATOR) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `vertex_k_connected_graph 2
      ((V:A->bool) DELETE u) (graph_contract_edges V E u v)`
  (LABEL_TAC "contract_2_connected") THENL
   [MATCH_MP_TAC VERTEX_3_CONNECTED_GRAPH_CONTRACT_2_CONNECTED THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(CARD(S:A->bool) < 2)`
  (LABEL_TAC "separator_not_small") THENL
   [DISCH_THEN(LABEL_TAC "too_small") THEN
    USE_THEN "separator_disconnect" (MATCH_MP_TAC o NOT_ELIM) THEN
    MATCH_MP_TAC(ISPECL
     [`2`; `(V:A->bool) DELETE u`;
      `graph_contract_edges V E u v:(A->bool)->bool`; `S:A->bool`]
     VERTEX_K_CONNECTED_GRAPH_DELETE_LT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(S:A->bool) = 2`
  (LABEL_TAC "separator_card") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?w:A. ~(w = v) /\ S = {v,w}`
  (X_CHOOSE_THEN `w:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "w_not_v")
    (LABEL_TAC "separator_pair"))) THENL
   [SUBGOAL_THEN `(S:A->bool) HAS_SIZE 2` MP_TAC THENL
     [ASM_REWRITE_TAC[HAS_SIZE] THEN
      MATCH_MP_TAC FINITE_SUBSET THEN
      EXISTS_TAC `(V:A->bool) DELETE u` THEN
      ASM_REWRITE_TAC[FINITE_DELETE];
      REWRITE_TAC[HAS_SIZE_CONV `(S:A->bool) HAS_SIZE 2`] THEN
      DISCH_THEN(X_CHOOSE_THEN `a:A`
       (X_CHOOSE_THEN `b:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "ab_distinct")
         (LABEL_TAC "S_pair")))) THEN
      USE_THEN "merged_in_separator" MP_TAC THEN
      USE_THEN "S_pair" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN
      DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
       [EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[];
        EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
        ASM SET_TAC[]]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(w:A) IN V /\ ~(w = u)`
  (CONJUNCTS_THEN2 (LABEL_TAC "w_vertex") (LABEL_TAC "w_not_u")) THENL
   [USE_THEN "separator_subset" MP_TAC THEN
    USE_THEN "separator_pair" (fun th -> REWRITE_TAC[th]) THEN
    SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `graph_vertex_separator
      (V:A->bool) E {u,v,w}`
  (LABEL_TAC "original_separator") THENL
   [REWRITE_TAC[graph_vertex_separator] THEN CONJ_TAC THENL
     [ASM SET_TAC[];
      USE_THEN "separator_disconnect" MP_TAC THEN
      REWRITE_TAC
       [MATCH_MP
         (ISPECL
          [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`; `S:A->bool`]
          INDUCED_GRAPH_CONTRACT_EDGES_DELETE_MERGED)
         (ASSUME `(v:A) IN S`)] THEN
      REMOVE_THEN "separator_pair" SUBST1_TAC THEN
      REWRITE_TAC[SET_RULE
       `((V:A->bool) DELETE u) DIFF {v,w} = V DIFF {u,v,w}`]];
    ALL_TAC] THEN
  EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Components of a vertex-deleted graph.                                     *)
(* ------------------------------------------------------------------------- *)

let GRAPH_VERTEX_SEPARATOR_COMPONENT_WITNESSES = prove
 (`!V E S:A->bool.
        graph_vertex_separator V E S
        ==> ?x y.
              x IN V DIFF S /\ y IN V DIFF S /\
              ~(y IN graph_component
                (induced_subgraph_edges E (V DIFF S)) x)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_vertex_separator; connected_graph;
              IN_GRAPH_COMPONENT] THEN
  MESON_TAC[]);;

let GRAPH_DELETED_COMPONENT_SUBSET = prove
 (`!V E S x:A.
        finite_simple_graph V E /\ x IN V DIFF S
        ==> graph_component
             (induced_subgraph_edges E (V DIFF S)) x
            SUBSET V DIFF S`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph x_vertex" THEN
  MATCH_MP_TAC GRAPH_COMPONENT_SUBSET THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH THEN
  EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[] THEN SET_TAC[]);;

let FINITE_GRAPH_DELETED_COMPONENT = prove
 (`!V E S x:A.
        finite_simple_graph V E
        ==> FINITE
             (graph_component
               (induced_subgraph_edges E (V DIFF S)) x)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  MATCH_MP_TAC(ISPECL
   [`(V:A->bool) DIFF S`;
    `induced_subgraph_edges (E:(A->bool)->bool) (V DIFF S)`; `x:A`]
   FINITE_GRAPH_COMPONENT) THEN
  MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH THEN
  EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[] THEN SET_TAC[]);;

(* Every member of a minimal three-vertex separator has a neighbor in every
   component left by its deletion. *)

let VERTEX_3_CONNECTED_GRAPH_SEPARATOR_COMPONENT_NEIGHBOR = prove
 (`!V E a b c x:A.
        vertex_k_connected_graph 3 V E /\
        ~(a = b) /\ ~(a = c) /\ ~(b = c) /\
        graph_vertex_separator V E {a,b,c} /\
        x IN V DIFF {a,b,c}
        ==> ?y.
              y IN graph_component
                (induced_subgraph_edges E (V DIFF {a,b,c})) x /\
              {c,y} IN E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "connected ab_distinct ac_distinct bc_distinct separator x_vertex" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `3` THEN USE_THEN "connected" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `{a:A,b,c} SUBSET V` (LABEL_TAC "separator_subset") THENL
   [USE_THEN "separator" MP_TAC THEN
    REWRITE_TAC[graph_vertex_separator] THEN MESON_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC
   `C:A->bool =
      graph_component
       (induced_subgraph_edges E (V DIFF {a,b,c})) x` THEN
  SUBGOAL_THEN `(C:A->bool) SUBSET V DIFF {a,b,c}`
  (LABEL_TAC "component_subset") THENL
   [EXPAND_TAC "C" THEN
    MATCH_MP_TAC GRAPH_DELETED_COMPONENT_SUBSET THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph
      ((V:A->bool) DIFF {a,b})
      (induced_subgraph_edges E (V DIFF {a,b}))`
  (LABEL_TAC "pair_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH THEN
    EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `connected_graph
      ((V:A->bool) DIFF {a,b})
      (induced_subgraph_edges E (V DIFF {a,b}))`
  (LABEL_TAC "pair_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`3`; `V:A->bool`; `E:(A->bool)->bool`; `{a:A,b}`]
     VERTEX_K_CONNECTED_GRAPH_DELETE_LT) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "connected" ACCEPT_TAC;
      USE_THEN "separator_subset" MP_TAC THEN SET_TAC[];
      ASM_SIMP_TAC
       [CARD_CLAUSES; FINITE_SING; CARD_SING; IN_SING] THEN
      ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(C:A->bool) SUBSET V DIFF {a,b}`
  (LABEL_TAC "component_pair_subset") THENL
   [USE_THEN "component_subset" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:A) IN C` (LABEL_TAC "x_component") THENL
   [EXPAND_TAC "C" THEN MATCH_ACCEPT_TAC GRAPH_COMPONENT_REFL;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((C:A->bool) = V DIFF {a,b})`
  (LABEL_TAC "component_proper") THENL
   [DISCH_THEN(LABEL_TAC "component_all") THEN
    SUBGOAL_THEN `(c:A) IN C` (LABEL_TAC "c_component") THENL
     [USE_THEN "component_all" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "separator_subset" MP_TAC THEN ASM SET_TAC[];
      USE_THEN "component_subset" MP_TAC THEN
      USE_THEN "c_component" MP_TAC THEN SET_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(V:A->bool) DIFF {a,b}`;
    `induced_subgraph_edges (E:(A->bool)->bool) (V DIFF {a,b})`;
    `C:A->bool`; `x:A`] CONNECTED_GRAPH_CROSSING_EDGE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@p y. p_outside y_component crossing_edge" THEN
  SUBGOAL_THEN
   `(p:A) = c`
  (LABEL_TAC "p_eq_c") THENL
   [MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "p_not_c") THEN
    SUBGOAL_THEN
     `{y:A,p} IN induced_subgraph_edges E (V DIFF {a,b,c})`
    (LABEL_TAC "component_edge") THENL
     [USE_THEN "crossing_edge" MP_TAC THEN
      REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
      INTRO_TAC "original_edge edge_pair_subset" THEN
      REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
      CONJ_TAC THENL
       [SUBGOAL_THEN `{y:A,p} = {p,y}` SUBST1_TAC THENL
         [SET_TAC[];
          USE_THEN "original_edge" ACCEPT_TAC];
        USE_THEN "component_subset" MP_TAC THEN
        USE_THEN "y_component" MP_TAC THEN
        USE_THEN "p_outside" MP_TAC THEN ASM SET_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `(p:A) IN C` (LABEL_TAC "p_component") THENL
     [EXPAND_TAC "C" THEN
      MATCH_MP_TAC GRAPH_COMPONENT_CLOSED THEN
      EXISTS_TAC `y:A` THEN
      ASM_REWRITE_TAC[];
      USE_THEN "p_outside" MP_TAC THEN
      USE_THEN "p_component" MP_TAC THEN SET_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "crossing_edge" MP_TAC THEN
  REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN ASM SET_TAC[]);;

let GRAPH_VERTEX_SEPARATOR_COMPONENT_PROPER = prove
 (`!V E S x:A.
        graph_vertex_separator V E S /\ x IN V DIFF S
        ==> ?y.
              y IN V DIFF S /\
              ~(y IN graph_component
                (induced_subgraph_edges E (V DIFF S)) x)`,
  REPEAT GEN_TAC THEN INTRO_TAC "separator x_vertex" THEN
  MP_TAC(ISPECL
   [`(V:A->bool) DIFF S`;
    `induced_subgraph_edges (E:(A->bool)->bool) (V DIFF S)`; `x:A`]
   CONNECTED_GRAPH_COMPONENT) THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "separator" MP_TAC THEN
  REWRITE_TAC[graph_vertex_separator] THEN SET_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Adjacent three-separators and a component of the deleted graph.           *)
(* ------------------------------------------------------------------------- *)

let GRAPH_ADJACENT_SEPARATOR_COMPONENT_DATA = prove
 (`!V E C:A->bool.
        graph_adjacent_separator_component V E C
        ==> ?u v w x.
              {u,v} IN E /\
              ~(u = v) /\ ~(u = w) /\ ~(v = w) /\
              graph_vertex_separator V E {u,v,w} /\
              x IN V DIFF {u,v,w} /\
              C = graph_component
                   (induced_subgraph_edges E (V DIFF {u,v,w})) x`,
  REWRITE_TAC[graph_adjacent_separator_component]);;

let FINITE_SIMPLE_GRAPH_ADJACENT_SEPARATOR_COMPONENT = prove
 (`!V E C:A->bool.
        finite_simple_graph V E /\
        graph_adjacent_separator_component V E C
        ==> FINITE C /\ C SUBSET V`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph component" THEN
  USE_THEN "component" MP_TAC THEN
  REWRITE_TAC[graph_adjacent_separator_component] THEN
  INTRO_TAC "@u v w x. edge uv_distinct uw_distinct vw_distinct \
             separator x_vertex C_eq" THEN
  USE_THEN "C_eq" SUBST1_TAC THEN CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_GRAPH_DELETED_COMPONENT THEN
    USE_THEN "graph" ACCEPT_TAC;
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `(V:A->bool) DIFF {u,v,w}` THEN CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_DELETED_COMPONENT_SUBSET THEN
      ASM_REWRITE_TAC[];
      SET_TAC[]]]);;

let VERTEX_K_CONNECTED_GRAPH_HAS_EDGE = prove
 (`!k V E.
        vertex_k_connected_graph k (V:A->bool) E /\ 0 < k
        ==> ?u v. {u,v} IN E`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected positive" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `k:num` THEN USE_THEN "connected" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `connected_graph (V:A->bool) E`
  (LABEL_TAC "graph_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`k:num`; `V:A->bool`; `E:(A->bool)->bool`]
     VERTEX_K_CONNECTED_GRAPH_CONNECTED) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((V:A->bool) = {})` (LABEL_TAC "nonempty") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    MP_TAC(ISPECL [`k:num`; `{}:A->bool`; `E:(A->bool)->bool`]
     VERTEX_K_CONNECTED_GRAPH_CARD) THEN
    ASM_REWRITE_TAC[CARD_CLAUSES] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "nonempty" MP_TAC THEN
  REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
  INTRO_TAC "@a. a_vertex" THEN
  SUBGOAL_THEN `~({a:A} = V)` (LABEL_TAC "singleton_proper") THENL
   [DISCH_THEN(LABEL_TAC "V_singleton") THEN
    MP_TAC(ISPECL [`k:num`; `V:A->bool`; `E:(A->bool)->bool`]
     VERTEX_K_CONNECTED_GRAPH_CARD) THEN
    ASM_REWRITE_TAC[] THEN
    REMOVE_THEN "V_singleton" (fun th -> REWRITE_TAC[GSYM th; CARD_SING]) THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `{a:A}`; `a:A`]
   CONNECTED_GRAPH_CROSSING_EDGE) THEN
  ASM_REWRITE_TAC[SING_SUBSET; IN_SING] THEN
  INTRO_TAC "@u v. u_outside v_singleton edge" THEN
  SUBGOAL_THEN `(v:A) = a` SUBST_ALL_TAC THENL
   [USE_THEN "v_singleton" MP_TAC THEN SET_TAC[];
    MAP_EVERY EXISTS_TAC [`u:A`; `a:A`] THEN
    USE_THEN "edge" ACCEPT_TAC]);;

let VERTEX_3_CONNECTED_GRAPH_HAS_ADJACENT_SEPARATOR_COMPONENT = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        vertex_k_connected_graph 3 V E /\
        5 <= CARD V /\
        (!u v:A.
           {u,v} IN E
           ==> ~vertex_k_connected_graph 3
                (V DELETE u) (graph_contract_edges V E u v))
        ==> ?C. graph_adjacent_separator_component V E C`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected large all_fail" THEN
  MP_TAC(ISPECL [`3`; `V:A->bool`; `E:(A->bool)->bool`]
   VERTEX_K_CONNECTED_GRAPH_HAS_EDGE) THEN
  ASM_REWRITE_TAC[ARITH_RULE `0 < 3`] THEN
  INTRO_TAC "@u v. edge" THEN
  MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
   VERTEX_3_CONNECTED_GRAPH_FAILED_CONTRACTION_SEPARATOR) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    USE_THEN "all_fail" MATCH_MP_TAC THEN
    USE_THEN "edge" ACCEPT_TAC;
    INTRO_TAC "@w. w_vertex w_not_u w_not_v separator"] THEN
  MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `{u:A,v,w}`]
   GRAPH_VERTEX_SEPARATOR_COMPONENT_WITNESSES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@x y. x_vertex y_vertex separate" THEN
  EXISTS_TAC
   `graph_component
     (induced_subgraph_edges E (V DIFF {u:A,v,w})) x` THEN
  REWRITE_TAC[graph_adjacent_separator_component] THEN
  MAP_EVERY EXISTS_TAC [`u:A`; `v:A`; `w:A`; `x:A`] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `3` THEN USE_THEN "connected" ACCEPT_TAC;
    MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[]]);;

let FINITE_SIMPLE_GRAPH_MAXIMAL_ADJACENT_SEPARATOR_COMPONENT = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        finite_simple_graph V E /\
        (?C. graph_adjacent_separator_component V E C)
        ==> ?C.
              graph_adjacent_separator_component V E C /\
              !D. graph_adjacent_separator_component V E D
                  ==> CARD D <= CARD C`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph exists_component" THEN
  MP_TAC(fst(EQ_IMP_RULE(SPEC
   `\n:num. ?C:A->bool.
      graph_adjacent_separator_component V E C /\ CARD C = n`
   num_MAX))) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "exists_component" MP_TAC THEN
      DISCH_THEN(X_CHOOSE_THEN `C:A->bool`
       (LABEL_TAC "component")) THEN
      EXISTS_TAC `CARD(C:A->bool)` THEN
      BETA_TAC THEN
      EXISTS_TAC `C:A->bool` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `CARD(V:A->bool)` THEN
      BETA_TAC THEN
      X_GEN_TAC `n:num` THEN
      INTRO_TAC "@C. component C_card" THEN
      USE_THEN "C_card" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC CARD_SUBSET THEN
      CONJ_TAC THENL
       [MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `C:A->bool`]
         FINITE_SIMPLE_GRAPH_ADJACENT_SEPARATOR_COMPONENT) THEN
        ASM_REWRITE_TAC[] THEN MESON_TAC[];
        USE_THEN "graph" MP_TAC THEN
        REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[]]];
    BETA_TAC THEN
    INTRO_TAC "@n. (@C. component C_card) maximal"] THEN
  EXISTS_TAC `C:A->bool` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `D:A->bool` THEN DISCH_THEN(LABEL_TAC "D_component") THEN
  USE_THEN "maximal" (MP_TAC o SPEC `CARD(D:A->bool)`) THEN
  ANTS_TAC THENL
   [BETA_TAC THEN EXISTS_TAC `D:A->bool` THEN ASM_REWRITE_TAC[];
    USE_THEN "C_card" (fun th -> REWRITE_TAC[GSYM th])]);;

(* ------------------------------------------------------------------------- *)
(* Enlarging a deleted component by the adjacent separator pair.             *)
(* ------------------------------------------------------------------------- *)

let GRAPH_COMPONENT_ADD_ADJACENT_PAIR_CONNECTED = prove
 (`!V E S x C u v z:A.
        finite_simple_graph V E /\
        x IN V DIFF S /\
        C = graph_component
             (induced_subgraph_edges E (V DIFF S)) x /\
        {u,v} IN E /\
        z IN C /\ {u,z} IN E
        ==> connected_graph
             (C UNION {u,v})
             (induced_subgraph_edges E (C UNION {u,v}))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph x_vertex C_eq uv_edge z_component uz_edge" THEN
  ABBREV_TAC `D:(A->bool)->bool =
    induced_subgraph_edges E (V DIFF S)` THEN
  ABBREV_TAC `W:A->bool = C UNION {u,v}` THEN
  ABBREV_TAC `B:(A->bool)->bool = induced_subgraph_edges E W` THEN
  SUBGOAL_THEN `finite_simple_graph
      ((V:A->bool) DIFF S) D`
  (LABEL_TAC "deleted_graph") THENL
   [EXPAND_TAC "D" THEN
    MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH THEN
    EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `connected_graph
      (C:A->bool) (graph_component_edges D x)`
  (LABEL_TAC "component_connected") THENL
   [USE_THEN "C_eq" (fun th -> REWRITE_TAC[th]) THEN
    ACCEPT_TAC(MATCH_MP
     (ISPECL [`(V:A->bool) DIFF S`; `D:(A->bool)->bool`; `x:A`]
       GRAPH_COMPONENT_EDGES_CONNECTED)
     (CONJ
       (ASSUME `finite_simple_graph ((V:A->bool) DIFF S) D`)
       (ASSUME `(x:A) IN V DIFF S`)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_component_edges D (x:A) SUBSET B`
  (LABEL_TAC "component_edges_subset") THENL
   [EXPAND_TAC "D" THEN EXPAND_TAC "B" THEN EXPAND_TAC "W" THEN
    USE_THEN "C_eq" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[SUBSET; IN_GRAPH_COMPONENT_EDGES;
                IN_INDUCED_SUBGRAPH_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN
    INTRO_TAC "(edge deleted_subset) component_edge_subset" THEN
    CONJ_TAC THENL
     [USE_THEN "edge" ACCEPT_TAC;
      X_GEN_TAC `q:A` THEN DISCH_THEN(LABEL_TAC "q_edge") THEN
      REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
      EXPAND_TAC "D" THEN
      USE_THEN "component_edge_subset" (MATCH_MP_TAC o SPEC `q:A`) THEN
      USE_THEN "q_edge" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `{u:A,v} IN B` (LABEL_TAC "uv_target_edge") THENL
   [EXPAND_TAC "B" THEN EXPAND_TAC "W" THEN
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    ACCEPT_TAC(CONJ
     (ASSUME `{u:A,v} IN E`)
     (SET_RULE `{u:A,v} SUBSET C UNION {u,v}`));
    ALL_TAC] THEN
  SUBGOAL_THEN `{u:A,z} IN B` (LABEL_TAC "uz_target_edge") THENL
   [EXPAND_TAC "B" THEN EXPAND_TAC "W" THEN
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    ACCEPT_TAC(CONJ
     (ASSUME `{u:A,z} IN E`)
     (MATCH_MP
      (SET_RULE `(z:A) IN C ==> {u,z} SUBSET C UNION {u,v}`)
      (ASSUME `(z:A) IN C`)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN C ==> graph_reachable B u a`
  (LABEL_TAC "reachable_from_u") THENL
   [X_GEN_TAC `a:A` THEN DISCH_THEN(LABEL_TAC "a_component") THEN
    SUBGOAL_THEN
     `graph_reachable (graph_component_edges D x) (z:A) a`
    (LABEL_TAC "component_reachable") THENL
     [USE_THEN "component_connected" MP_TAC THEN
      REWRITE_TAC[connected_graph] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN
    EXISTS_TAC `z:A` THEN CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
      USE_THEN "uz_target_edge" ACCEPT_TAC;
      ACCEPT_TAC(MATCH_MP
       (ISPECL
        [`graph_component_edges D (x:A)`;
         `B:(A->bool)->bool`; `z:A`; `a:A`]
        GRAPH_REACHABLE_MONO)
       (CONJ
        (ASSUME `graph_component_edges D (x:A) SUBSET B`)
        (ASSUME
         `graph_reachable (graph_component_edges D x) (z:A) a`)))];
    ALL_TAC] THEN
  EXPAND_TAC "W" THEN
  REWRITE_TAC[connected_graph] THEN
  MAP_EVERY X_GEN_TAC [`a:A`; `b:A`] THEN
  INTRO_TAC "a_vertex b_vertex" THEN
  SUBGOAL_THEN
   `graph_reachable
      B u (a:A)`
  (LABEL_TAC "u_to_a") THENL
   [USE_THEN "a_vertex" MP_TAC THEN
    REWRITE_TAC[IN_UNION; IN_INSERT; IN_SING] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "a_component")
      (DISJ_CASES_THEN2 (LABEL_TAC "a_eq_u")
                        (LABEL_TAC "a_eq_v"))) THENL
     [USE_THEN "reachable_from_u" MATCH_MP_TAC THEN
      USE_THEN "a_component" ACCEPT_TAC;
      USE_THEN "a_eq_u" SUBST_ALL_TAC THEN
      MATCH_ACCEPT_TAC GRAPH_REACHABLE_REFL;
      USE_THEN "a_eq_v" SUBST_ALL_TAC THEN
      MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
      USE_THEN "uv_target_edge" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_reachable
      B u (b:A)`
  (LABEL_TAC "u_to_b") THENL
   [USE_THEN "b_vertex" MP_TAC THEN
    REWRITE_TAC[IN_UNION; IN_INSERT; IN_SING] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "b_component")
      (DISJ_CASES_THEN2 (LABEL_TAC "b_eq_u")
                        (LABEL_TAC "b_eq_v"))) THENL
     [USE_THEN "reachable_from_u" MATCH_MP_TAC THEN
      USE_THEN "b_component" ACCEPT_TAC;
      USE_THEN "b_eq_u" SUBST_ALL_TAC THEN
      MATCH_ACCEPT_TAC GRAPH_REACHABLE_REFL;
      USE_THEN "b_eq_v" SUBST_ALL_TAC THEN
      MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
      USE_THEN "uv_target_edge" ACCEPT_TAC];
    MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN EXISTS_TAC `u:A` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
      USE_THEN "u_to_a" ACCEPT_TAC;
      USE_THEN "u_to_b" ACCEPT_TAC]]);;

let CARD_COMPONENT_ADD_PAIR_DELETE_GT = prove
 (`!C:A->bool. !u v y:A.
        FINITE C /\
        ~(u IN C) /\ ~(v IN C) /\ ~(u = v) /\
        y IN C UNION {u,v}
        ==> CARD C < CARD((C UNION {u,v}) DELETE y)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite u_outside v_outside distinct y_member" THEN
  SUBGOAL_THEN `C UNION {u:A,v} = u INSERT (v INSERT C)`
  (LABEL_TAC "union_eq") THENL
   [SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) IN v INSERT C)` (LABEL_TAC "u_outside_inner") THENL
   [ASM_REWRITE_TAC[IN_INSERT];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(C UNION {u:A,v}) = CARD C + 2`
  (LABEL_TAC "union_card") THENL
   [USE_THEN "union_eq" (fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[FINITE_INSERT; CARD_CLAUSES] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD((C UNION {u:A,v}) DELETE y) =
    CARD(C UNION {u,v}) - 1`
  (LABEL_TAC "delete_card") THENL
   [MP_TAC(ISPECL [`y:A`; `C UNION {u:A,v}`] CARD_DELETE) THEN
    ASM_REWRITE_TAC[FINITE_UNION; FINITE_INSERT; FINITE_EMPTY];
    ASM_ARITH_TAC]);;

let CARD_COMPONENT_ADD_PAIR_DELETE_GT_GEN = prove
 (`!C:A->bool. !u v y:A.
        FINITE C /\
        ~(u IN C) /\ ~(v IN C) /\ ~(u = v)
        ==> CARD C < CARD((C UNION {u,v}) DELETE y)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "finite u_outside v_outside distinct" THEN
  ASM_CASES_TAC `(y:A) IN C UNION {u,v}` THENL
   [MATCH_MP_TAC CARD_COMPONENT_ADD_PAIR_DELETE_GT THEN
    ASM_REWRITE_TAC[];
    SUBGOAL_THEN `(C UNION {u:A,v}) DELETE y = C UNION {u,v}`
    SUBST1_TAC THENL
     [ASM SET_TAC[];
      MATCH_MP_TAC CARD_PSUBSET THEN
      CONJ_TAC THENL
       [REWRITE_TAC[PSUBSET] THEN ASM SET_TAC[];
        ASM_REWRITE_TAC[FINITE_UNION; FINITE_INSERT; FINITE_EMPTY]]]]);;

let CONNECTED_SUBSET_GRAPH_COMPONENT = prove
 (`!V E W S r:A.
        connected_graph W (induced_subgraph_edges E W) /\
        W SUBSET V DIFF S /\
        r IN W
        ==> W SUBSET
            graph_component
             (induced_subgraph_edges E (V DIFF S)) r`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected subset root" THEN
  REWRITE_TAC[SUBSET; IN_GRAPH_COMPONENT] THEN
  X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_vertex") THEN
  MATCH_MP_TAC(ISPECL
   [`induced_subgraph_edges (E:(A->bool)->bool) W`;
    `induced_subgraph_edges E ((V:A->bool) DIFF S)`;
    `r:A`; `z:A`] GRAPH_REACHABLE_MONO) THEN
  CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
    USE_THEN "subset" MP_TAC THEN SET_TAC[];
    USE_THEN "connected" MP_TAC THEN
    REWRITE_TAC[connected_graph] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* The enlarged component cannot acquire a cutpoint.  Otherwise a component
   not containing the surviving endpoint of {u,v} attaches to the original
   graph only through that cutpoint and the third separator vertex w. *)

let VERTEX_3_CONNECTED_GRAPH_COMPONENT_ADD_PAIR_DELETE_CONNECTED = prove
 (`!V E u v w x C y:A.
        vertex_k_connected_graph 3 V E /\
        ~(u = v) /\ ~(u = w) /\ ~(v = w) /\
        graph_vertex_separator V E {u,v,w} /\
        x IN V DIFF {u,v,w} /\
        C = graph_component
             (induced_subgraph_edges E (V DIFF {u,v,w})) x /\
        {u,v} IN E /\
        y IN C UNION {u,v}
        ==> connected_graph
             ((C UNION {u,v}) DELETE y)
             (induced_subgraph_edges E ((C UNION {u,v}) DELETE y))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "connected uv_distinct uw_distinct vw_distinct separator \
             x_vertex C_eq uv_edge y_member" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `3` THEN USE_THEN "connected" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `{u:A,v,w} SUBSET V` (LABEL_TAC "separator_subset") THENL
   [USE_THEN "separator" MP_TAC THEN
    REWRITE_TAC[graph_vertex_separator] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(C:A->bool) SUBSET V DIFF {u,v,w}`
  (LABEL_TAC "C_subset") THENL
   [USE_THEN "C_eq" SUBST1_TAC THEN
    MATCH_MP_TAC GRAPH_DELETED_COMPONENT_SUBSET THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `W:A->bool = C UNION {u,v}` THEN
  ABBREV_TAC `Q:A->bool = W DELETE y` THEN
  ABBREV_TAC `B:(A->bool)->bool = induced_subgraph_edges E Q` THEN
  SUBGOAL_THEN `?a:A. a IN {u,v} /\ ~(a = y)`
  (X_CHOOSE_THEN `a:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "a_endpoint") (LABEL_TAC "a_not_y"))) THENL
   [ASM_CASES_TAC `(u:A) = y` THENL
     [EXISTS_TAC `v:A` THEN ASM SET_TAC[];
      EXISTS_TAC `u:A` THEN ASM SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:A) IN Q` (LABEL_TAC "a_vertex") THENL
   [EXPAND_TAC "Q" THEN EXPAND_TAC "W" THEN ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `Q SUBSET (V:A->bool)` (LABEL_TAC "Q_subset") THENL
   [EXPAND_TAC "Q" THEN EXPAND_TAC "W" THEN
    USE_THEN "C_subset" MP_TAC THEN
    USE_THEN "separator_subset" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (Q:A->bool) B`
  (LABEL_TAC "Q_graph") THENL
   [EXPAND_TAC "B" THEN
    MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH THEN
    EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
  DISCH_THEN(LABEL_TAC "Q_disconnected") THEN
  SUBGOAL_THEN
   `?z:A. z IN Q /\
      ~(z IN graph_component B a)`
  (X_CHOOSE_THEN `z:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "z_vertex")
    (LABEL_TAC "z_not_a_component"))) THENL
   [MP_TAC(ISPECL [`Q:A->bool`; `B:(A->bool)->bool`; `a:A`]
     CONNECTED_GRAPH_COMPONENT) THEN
    ASM_REWRITE_TAC[] THEN SET_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `K:A->bool = graph_component B z` THEN
  SUBGOAL_THEN `(K:A->bool) SUBSET Q` (LABEL_TAC "K_subset") THENL
   [EXPAND_TAC "K" THEN
    MATCH_MP_TAC GRAPH_COMPONENT_SUBSET THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN K` (LABEL_TAC "z_component") THENL
   [EXPAND_TAC "K" THEN MATCH_ACCEPT_TAC GRAPH_COMPONENT_REFL;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((a:A) IN K)` (LABEL_TAC "a_not_component") THENL
   [EXPAND_TAC "K" THEN
    USE_THEN "z_not_a_component" MP_TAC THEN
    REWRITE_TAC[IN_GRAPH_COMPONENT] THEN
    MESON_TAC[GRAPH_REACHABLE_SYM];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t:A. t IN {u,v} /\ t IN Q ==> ~(t IN K)`
  (LABEL_TAC "endpoints_outside_K") THENL
   [X_GEN_TAC `t:A` THEN INTRO_TAC "t_endpoint t_vertex" THEN
    SUBGOAL_THEN `graph_reachable B (a:A) t`
    (LABEL_TAC "a_to_t") THENL
     [ASM_CASES_TAC `(a:A) = t` THENL
       [ASM_REWRITE_TAC[GRAPH_REACHABLE_REFL];
        MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
        EXPAND_TAC "B" THEN
         REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
         CONJ_TAC THENL
         [SUBGOAL_THEN `{a:A,t} = {u,v}` SUBST1_TAC THENL
           [ACCEPT_TAC(MATCH_MP
             (SET_RULE
              `(a:A) IN {u,v} /\ t IN {u,v} /\ ~(a = t)
               ==> {a,t} = {u,v}`)
             (CONJ
              (ASSUME `(a:A) IN {u,v}`)
              (CONJ
               (ASSUME `(t:A) IN {u,v}`)
               (ASSUME `~((a:A) = t)`))));
            USE_THEN "uv_edge" ACCEPT_TAC];
          REWRITE_TAC[INSERT_SUBSET; EMPTY_SUBSET] THEN
          CONJ_TAC THENL
           [USE_THEN "a_vertex" ACCEPT_TAC;
            USE_THEN "t_vertex" ACCEPT_TAC]]];
      DISCH_THEN(LABEL_TAC "t_component") THEN
      USE_THEN "a_not_component" (MATCH_MP_TAC o NOT_ELIM) THEN
      EXPAND_TAC "K" THEN REWRITE_TAC[IN_GRAPH_COMPONENT] THEN
      MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN EXISTS_TAC `t:A` THEN
      CONJ_TAC THENL
       [USE_THEN "t_component" (fun th ->
         ACCEPT_TAC(REWRITE_RULE
          [GSYM(ASSUME `graph_component B (z:A) = K`);
           IN_GRAPH_COMPONENT] th));
        MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
        USE_THEN "a_to_t" ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!r s:A.
      r IN K /\
      {r,s} IN induced_subgraph_edges E (V DIFF {y,w})
      ==> s IN K`
  (LABEL_TAC "K_closed") THENL
   [MAP_EVERY X_GEN_TAC [`r:A`; `s:A`] THEN
    INTRO_TAC "r_component edge" THEN
    SUBGOAL_THEN `(r:A) IN Q` (LABEL_TAC "r_vertex") THENL
     [USE_THEN "K_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "r_component" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((r:A) IN {u,v})` (LABEL_TAC "r_not_endpoint") THENL
     [DISCH_THEN(LABEL_TAC "r_endpoint") THEN
      USE_THEN "endpoints_outside_K" (fun th ->
       let nth =
         MATCH_MP
          (SPEC `r:A` th)
          (CONJ
           (ASSUME `(r:A) IN {u,v}`)
           (ASSUME `(r:A) IN Q`)) in
       ACCEPT_TAC(MP (NOT_ELIM nth) (ASSUME `(r:A) IN K`)));
      ALL_TAC] THEN
    SUBGOAL_THEN `(r:A) IN C` (LABEL_TAC "r_C") THENL
     [USE_THEN "r_vertex" MP_TAC THEN
      REWRITE_TAC
       [GSYM(ASSUME `(W:A->bool) DELETE y = Q`);
        GSYM(ASSUME `(C:A->bool) UNION {u,v} = W`);
        IN_DELETE; IN_UNION] THEN
      MESON_TAC[ASSUME `~((r:A) IN {u,v})`];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(s:A) IN W /\ ~(s = y)`
    (CONJUNCTS_THEN2 (LABEL_TAC "s_W") (LABEL_TAC "s_not_y")) THENL
     [USE_THEN "edge" MP_TAC THEN
      REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
      INTRO_TAC "original_edge edge_subset" THEN
      CONJ_TAC THENL
       [ASM_CASES_TAC `(s:A) IN {u,v}` THENL
         [EXPAND_TAC "W" THEN ASM SET_TAC[];
          SUBGOAL_THEN
           `{r:A,s} IN
             induced_subgraph_edges E (V DIFF {u,v,w})`
          (LABEL_TAC "old_component_edge") THENL
           [REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
            CONJ_TAC THENL
             [USE_THEN "original_edge" ACCEPT_TAC;
              USE_THEN "C_subset" MP_TAC THEN
              USE_THEN "r_C" MP_TAC THEN
              USE_THEN "edge_subset" MP_TAC THEN ASM SET_TAC[]];
            EXPAND_TAC "W" THEN REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
            USE_THEN "C_eq" (fun eqth ->
             REWRITE_TAC[eqth] THEN
             MATCH_MP_TAC GRAPH_COMPONENT_CLOSED THEN
             EXISTS_TAC `r:A` THEN CONJ_TAC THENL
              [USE_THEN "r_C"
                (ACCEPT_TAC o REWRITE_RULE[eqth]);
               USE_THEN "old_component_edge" ACCEPT_TAC])]];
        USE_THEN "edge_subset" MP_TAC THEN SET_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `(s:A) IN Q` (LABEL_TAC "s_vertex") THENL
     [EXPAND_TAC "Q" THEN ASM_REWRITE_TAC[IN_DELETE];
      ALL_TAC] THEN
    EXPAND_TAC "K" THEN MATCH_MP_TAC GRAPH_COMPONENT_CLOSED THEN
    EXISTS_TAC `r:A` THEN CONJ_TAC THENL
     [USE_THEN "r_component" (fun th ->
       ACCEPT_TAC(REWRITE_RULE
        [GSYM(ASSUME `graph_component B (z:A) = K`)] th));
      ALL_TAC] THEN
    EXPAND_TAC "B" THEN REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    CONJ_TAC THENL
     [USE_THEN "edge" (fun th ->
       ACCEPT_TAC(CONJUNCT1
        (REWRITE_RULE[IN_INDUCED_SUBGRAPH_EDGES] th)));
      REWRITE_TAC[INSERT_SUBSET; EMPTY_SUBSET] THEN
      CONJ_TAC THENL
       [USE_THEN "r_vertex" ACCEPT_TAC;
        USE_THEN "s_vertex" ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `connected_graph
      ((V:A->bool) DIFF {y,w})
      (induced_subgraph_edges E (V DIFF {y,w}))`
  (LABEL_TAC "two_delete_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`3`; `V:A->bool`; `E:(A->bool)->bool`; `{y:A,w}`]
     VERTEX_K_CONNECTED_GRAPH_DELETE_LT) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "connected" ACCEPT_TAC;
      ACCEPT_TAC(MATCH_MP
       (SET_RULE
        `C SUBSET V DIFF {u:A,v,w} /\
         {u,v,w} SUBSET V /\
         y IN C UNION {u,v}
         ==> {y,w} SUBSET V`)
       (CONJ
        (ASSUME `(C:A->bool) SUBSET V DIFF {u,v,w}`)
        (CONJ
         (ASSUME `{u:A,v,w} SUBSET V`)
         (REWRITE_RULE
          [GSYM(ASSUME `(C:A->bool) UNION {u,v} = W`)]
          (ASSUME `(y:A) IN W`)))));
      ASM_CASES_TAC `(y:A) = w` THEN
      ASM_REWRITE_TAC[SET_RULE `{y:A,y} = {y}`; CARD_SING] THEN
      ASM_SIMP_TAC
       [CARD_CLAUSES; FINITE_SING; CARD_SING; IN_SING] THEN
      ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN V DIFF {y,w}`
  (LABEL_TAC "z_two_delete") THENL
   [(let zq = ASSUME `(z:A) IN Q` in
    let zdata =
      REWRITE_RULE
       [GSYM(ASSUME `(W:A->bool) DELETE y = Q`);
        GSYM(ASSUME `(C:A->bool) UNION {u,v} = W`);
        IN_DELETE] zq in
    let zv =
      MATCH_MP
       (SPEC `z:A`
        (REWRITE_RULE[SUBSET]
         (ASSUME `(Q:A->bool) SUBSET V`)))
       zq in
    ACCEPT_TAC(MATCH_MP
     (SET_RULE
      `C SUBSET V DIFF {u:A,v,w} /\
       ~(u = w) /\ ~(v = w) /\
       z IN C UNION {u,v} /\ ~(z = y) /\ z IN V
       ==> z IN V DIFF {y,w}`)
     (CONJ
      (ASSUME `(C:A->bool) SUBSET V DIFF {u,v,w}`)
      (CONJ
       (ASSUME `~((u:A) = w)`)
       (CONJ
        (ASSUME `~((v:A) = w)`)
         (CONJ
          (CONJUNCT1 zdata)
         (CONJ (CONJUNCT2 zdata) zv)))))));
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:A) IN V DIFF {y,w}`
  (LABEL_TAC "a_two_delete") THENL
   [ACCEPT_TAC(MATCH_MP
     (SET_RULE
      `(a:A) IN {u,v} /\ ~(a = y) /\
       {u,v,w} SUBSET V /\ ~(u = w) /\ ~(v = w)
       ==> a IN V DIFF {y,w}`)
     (CONJ
      (ASSUME `(a:A) IN {u,v}`)
      (CONJ
       (ASSUME `~((a:A) = y)`)
       (CONJ
        (ASSUME `{u:A,v,w} SUBSET V`)
        (CONJ
         (ASSUME `~((u:A) = w)`)
         (ASSUME `~((v:A) = w)`))))));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_reachable
      (induced_subgraph_edges E (V DIFF {y,w})) (z:A) a`
  (LABEL_TAC "z_to_a") THENL
   [USE_THEN "two_delete_connected" MP_TAC THEN
    REWRITE_TAC[connected_graph] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "a_not_component" (MATCH_MP_TAC o NOT_ELIM) THEN
  MATCH_MP_TAC(ISPECL
   [`induced_subgraph_edges (E:(A->bool)->bool) (V DIFF {y,w})`;
    `K:A->bool`; `z:A`; `a:A`] GRAPH_REACHABLE_CLOSED) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Thomassen's contractible-edge theorem.                                    *)
(* ------------------------------------------------------------------------- *)

let VERTEX_3_CONNECTED_GRAPH_CONTRACTIBLE_EDGE = prove
 (`!V E.
        vertex_k_connected_graph 3 (V:A->bool) E /\
        5 <= CARD V
        ==> ?u v.
              {u,v} IN E /\
              vertex_k_connected_graph 3
                (V DELETE u) (graph_contract_edges V E u v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected large" THEN
  MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
  DISCH_THEN(LABEL_TAC "no_contractible") THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `3` THEN USE_THEN "connected" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b:A.
      {a,b} IN E
      ==> ~vertex_k_connected_graph 3
            (V DELETE a) (graph_contract_edges V E a b)`
  (LABEL_TAC "all_fail") THENL
   [MAP_EVERY X_GEN_TAC [`a:A`; `b:A`] THEN
    DISCH_THEN(LABEL_TAC "edge") THEN
    DISCH_THEN(LABEL_TAC "contractible") THEN
    USE_THEN "no_contractible" (MATCH_MP_TAC o NOT_ELIM) THEN
    MAP_EVERY EXISTS_TAC [`a:A`; `b:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?C:A->bool. graph_adjacent_separator_component V E C`
  (X_CHOOSE_THEN `C:A->bool` (LABEL_TAC "C_component")) THENL
   [MATCH_MP_TAC
     VERTEX_3_CONNECTED_GRAPH_HAS_ADJACENT_SEPARATOR_COMPONENT THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (ISPECL [`V:A->bool`; `E:(A->bool)->bool`]
    FINITE_SIMPLE_GRAPH_MAXIMAL_ADJACENT_SEPARATOR_COMPONENT)
   (CONJ
    (ASSUME `finite_simple_graph (V:A->bool) E`)
    (EXISTS
     (`?D:A->bool. graph_adjacent_separator_component V E D`,
     `C:A->bool`)
     (ASSUME `graph_adjacent_separator_component V E (C:A->bool)`)))) THEN
  INTRO_TAC "@H. H_component maximal" THEN
  USE_THEN "H_component" MP_TAC THEN
  REWRITE_TAC[graph_adjacent_separator_component] THEN
  INTRO_TAC
   "@u v w x. uv_edge uv_distinct uw_distinct vw_distinct \
    separator x_vertex H_eq" THEN
  SUBGOAL_THEN `FINITE(H:A->bool)` (LABEL_TAC "H_finite") THENL
   [USE_THEN "H_eq" (fun eqth ->
     ACCEPT_TAC(REWRITE_RULE[GSYM eqth]
      (MATCH_MP
       (ISPECL
        [`V:A->bool`; `E:(A->bool)->bool`; `{u:A,v,w}`; `x:A`]
        FINITE_GRAPH_DELETED_COMPONENT)
       (ASSUME `finite_simple_graph (V:A->bool) E`))));
    ALL_TAC] THEN
  SUBGOAL_THEN `(H:A->bool) SUBSET V DIFF {u,v,w}`
  (LABEL_TAC "H_subset") THENL
   [USE_THEN "H_eq" (fun eqth ->
     ACCEPT_TAC(REWRITE_RULE[GSYM eqth]
      (MATCH_MP
       (ISPECL
        [`V:A->bool`; `E:(A->bool)->bool`; `{u:A,v,w}`; `x:A`]
        GRAPH_DELETED_COMPONENT_SUBSET)
       (CONJ
        (ASSUME `finite_simple_graph (V:A->bool) E`)
        (ASSUME `(x:A) IN V DIFF {u,v,w}`)))));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?z:A. z IN V DIFF {u,v,w} /\ ~(z IN H)`
  (X_CHOOSE_THEN `z:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "z_vertex")
    (LABEL_TAC "z_outside_H"))) THENL
   [USE_THEN "H_eq" (fun eqth ->
     ACCEPT_TAC(REWRITE_RULE[GSYM eqth]
      (MATCH_MP
       (ISPECL
        [`V:A->bool`; `E:(A->bool)->bool`; `{u:A,v,w}`; `x:A`]
        GRAPH_VERTEX_SEPARATOR_COMPONENT_PROPER)
       (CONJ
        (ASSUME `graph_vertex_separator (V:A->bool) E {u,v,w}`)
        (ASSUME `(x:A) IN V DIFF {u,v,w}`)))));
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`; `w:A`; `z:A`]
   VERTEX_3_CONNECTED_GRAPH_SEPARATOR_COMPONENT_NEIGHBOR) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@p. p_other_component wp_edge" THEN
  SUBGOAL_THEN
   `(p:A) IN V DIFF {u,v,w}`
  (LABEL_TAC "p_vertex") THENL
   [ACCEPT_TAC(MATCH_MP
     (SPEC `p:A`
      (REWRITE_RULE[SUBSET]
       (MATCH_MP
        (ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `{u:A,v,w}`; `z:A`]
         GRAPH_DELETED_COMPONENT_SUBSET)
        (CONJ
         (ASSUME `finite_simple_graph (V:A->bool) E`)
         (ASSUME `(z:A) IN V DIFF {u,v,w}`)))))
     (ASSUME
      `(p:A) IN
      graph_component
        (induced_subgraph_edges E (V DIFF {u,v,w})) z`));
    ALL_TAC] THEN
  SUBGOAL_THEN `~((p:A) IN H)` (LABEL_TAC "p_outside_H") THENL
   [DISCH_THEN(LABEL_TAC "p_H") THEN
    USE_THEN "z_outside_H" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "H_eq" (fun eqth ->
     REWRITE_TAC[eqth; IN_GRAPH_COMPONENT] THEN
     MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN EXISTS_TAC `p:A` THEN
     CONJ_TAC THENL
      [USE_THEN "p_H"
        (ACCEPT_TAC o REWRITE_RULE[eqth; IN_GRAPH_COMPONENT]);
       MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
       USE_THEN "p_other_component"
        (ACCEPT_TAC o REWRITE_RULE[IN_GRAPH_COMPONENT])]);
    ALL_TAC] THEN
  MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `w:A`; `p:A`]
   VERTEX_3_CONNECTED_GRAPH_FAILED_CONTRACTION_SEPARATOR) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    USE_THEN "all_fail" MATCH_MP_TAC THEN
    USE_THEN "wp_edge" ACCEPT_TAC;
    INTRO_TAC "@y. y_vertex y_not_w y_not_p new_separator"] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `w:A`; `u:A`; `x:A`]
   VERTEX_3_CONNECTED_GRAPH_SEPARATOR_COMPONENT_NEIGHBOR) THEN
  ASM_REWRITE_TAC[SET_RULE `{v:A,w,u} = {u,v,w}`] THEN
  INTRO_TAC "@h. h_H uh_edge" THEN
  SUBGOAL_THEN
   `connected_graph
      (H UNION {u:A,v})
      (induced_subgraph_edges E (H UNION {u,v}))`
  (LABEL_TAC "expanded_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `{u:A,v,w}`; `x:A`;
      `H:A->bool`; `u:A`; `v:A`; `h:A`]
     GRAPH_COMPONENT_ADD_ADJACENT_PAIR_CONNECTED) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `W:A->bool = H UNION {u,v}` THEN
  ABBREV_TAC `R:A->bool = W DELETE y` THEN
  SUBGOAL_THEN `connected_graph
      (R:A->bool) (induced_subgraph_edges E R)`
  (LABEL_TAC "R_connected") THENL
   [ASM_CASES_TAC `(y:A) IN W` THENL
     [EXPAND_TAC "R" THEN EXPAND_TAC "W" THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `u:A`; `v:A`; `w:A`; `x:A`; `H:A->bool`; `y:A`]
       VERTEX_3_CONNECTED_GRAPH_COMPONENT_ADD_PAIR_DELETE_CONNECTED) THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN `(R:A->bool) = W` (LABEL_TAC "R_eq_W") THENL
       [EXPAND_TAC "R" THEN ASM SET_TAC[];
        ALL_TAC] THEN
      USE_THEN "R_eq_W" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "expanded_connected" (fun th ->
       ACCEPT_TAC(REWRITE_RULE
        [ASSUME `(H:A->bool) UNION {u,v} = W`] th))];
    ALL_TAC] THEN
  SUBGOAL_THEN `(u:A) IN V /\ (v:A) IN V`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex") (LABEL_TAC "v_vertex")) THENL
   [USE_THEN "graph" (MP_TAC o REWRITE_RULE[finite_simple_graph]) THEN
    INTRO_TAC "finite_vertices finite_edges edges" THEN
    USE_THEN "edges" (MP_TAC o SPEC `{u:A,v}`) THEN
    ANTS_TAC THENL
     [USE_THEN "uv_edge" ACCEPT_TAC;
      INTRO_TAC "uv_subset uv_size" THEN
      USE_THEN "uv_subset" MP_TAC THEN
      REWRITE_TAC[INSERT_SUBSET; SING_SUBSET]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?r:A. r IN {u,v} /\ ~(r = y)`
  (X_CHOOSE_THEN `r:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "r_endpoint") (LABEL_TAC "r_not_y"))) THENL
   [ASM_CASES_TAC `(u:A) = y` THENL
     [EXISTS_TAC `v:A` THEN ASM SET_TAC[];
      EXISTS_TAC `u:A` THEN ASM SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN R` (LABEL_TAC "r_vertex") THENL
   [EXPAND_TAC "R" THEN EXPAND_TAC "W" THEN ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(R:A->bool) SUBSET V DIFF {w,p,y}`
  (LABEL_TAC "R_subset") THENL
   [EXPAND_TAC "R" THEN EXPAND_TAC "W" THEN
    REWRITE_TAC
     [SUBSET; IN_DIFF; IN_DELETE; IN_UNION; IN_INSERT; IN_SING] THEN
    X_GEN_TAC `q:A` THEN
    INTRO_TAC "(q_H | q_eq_u | q_eq_v) q_not_y" THENL
     [SUBGOAL_THEN `(q:A) IN V DIFF {u,v,w}`
      (LABEL_TAC "q_old") THENL
       [USE_THEN "H_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "q_H" ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "q_old" MP_TAC THEN
      REWRITE_TAC[IN_DIFF; IN_INSERT; IN_SING] THEN
      INTRO_TAC "q_vertex q_not_separator" THEN
      CONJ_TAC THENL
       [USE_THEN "q_vertex" ACCEPT_TAC;
        REWRITE_TAC[TAUT
         `~(a \/ b \/ c) <=> ~a /\ ~b /\ ~c`] THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "q_not_separator" MP_TAC THEN MESON_TAC[];
          DISCH_THEN SUBST_ALL_TAC THEN
          USE_THEN "p_outside_H" (MATCH_MP_TAC o NOT_ELIM) THEN
          USE_THEN "q_H" ACCEPT_TAC;
          USE_THEN "q_not_y" ACCEPT_TAC]];
      USE_THEN "q_eq_u" SUBST_ALL_TAC THEN
      CONJ_TAC THENL
       [USE_THEN "u_vertex" ACCEPT_TAC;
        REWRITE_TAC[TAUT
         `~(a \/ b \/ c) <=> ~a /\ ~b /\ ~c`] THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "uw_distinct" ACCEPT_TAC;
          USE_THEN "p_vertex" MP_TAC THEN
          REWRITE_TAC[IN_DIFF; IN_INSERT; IN_SING] THEN MESON_TAC[];
          USE_THEN "q_not_y" ACCEPT_TAC]];
      USE_THEN "q_eq_v" SUBST_ALL_TAC THEN
      CONJ_TAC THENL
       [USE_THEN "v_vertex" ACCEPT_TAC;
        REWRITE_TAC[TAUT
         `~(a \/ b \/ c) <=> ~a /\ ~b /\ ~c`] THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "vw_distinct" ACCEPT_TAC;
          USE_THEN "p_vertex" MP_TAC THEN
          REWRITE_TAC[IN_DIFF; IN_INSERT; IN_SING] THEN MESON_TAC[];
          USE_THEN "q_not_y" ACCEPT_TAC]]];
    ALL_TAC] THEN
  ABBREV_TAC
   `N:A->bool =
      graph_component
       (induced_subgraph_edges E (V DIFF {w,p,y})) r` THEN
  SUBGOAL_THEN `(R:A->bool) SUBSET N` (LABEL_TAC "R_in_N") THENL
   [EXPAND_TAC "N" THEN
    MATCH_MP_TAC CONNECTED_SUBSET_GRAPH_COMPONENT THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `graph_adjacent_separator_component
      (V:A->bool) E N`
  (LABEL_TAC "N_component") THENL
   [REWRITE_TAC[graph_adjacent_separator_component] THEN
    MAP_EVERY EXISTS_TAC [`w:A`; `p:A`; `y:A`; `r:A`] THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "wp_edge" ACCEPT_TAC;
      USE_THEN "p_vertex" MP_TAC THEN SET_TAC[];
      ASM_MESON_TAC[];
      ASM_MESON_TAC[];
      USE_THEN "new_separator" ACCEPT_TAC;
      USE_THEN "R_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "r_vertex" ACCEPT_TAC;
      EXPAND_TAC "N" THEN REFL_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(N:A->bool) <= CARD(H:A->bool)`
  (LABEL_TAC "N_at_most_H") THENL
   [USE_THEN "maximal" MATCH_MP_TAC THEN
    USE_THEN "N_component" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(N:A->bool)` (LABEL_TAC "N_finite") THENL
   [EXPAND_TAC "N" THEN
    MATCH_MP_TAC FINITE_GRAPH_DELETED_COMPONENT THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(R:A->bool) <= CARD(N:A->bool)`
  (LABEL_TAC "R_at_most_N") THENL
   [MATCH_MP_TAC CARD_SUBSET THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(H:A->bool) < CARD(R:A->bool)`
  (LABEL_TAC "H_less_R") THENL
   [EXPAND_TAC "R" THEN EXPAND_TAC "W" THEN
    MATCH_MP_TAC CARD_COMPONENT_ADD_PAIR_DELETE_GT_GEN THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "H_subset" MP_TAC THEN ASM SET_TAC[];
    ASM_ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* Vertex and degree structure of graph subdivisions.                        *)
(* ------------------------------------------------------------------------- *)

let PAIR_SET_EQ_LEFT = prove
 (`!a b c:A. ({a,b} = {a,c} <=> b = c)`,
  SET_TAC[]);;

let PAIR_SET_EQ_CROSS = prove
 (`!a b c:A. ({a,b} = {c,a} <=> b = c)`,
  SET_TAC[]);;

let PAIR_SET_EQ = prove
 (`!a b c d:A.
        ({a,b} = {c,d} <=>
         (a = c /\ b = d) \/ (a = d /\ b = c))`,
  SET_TAC[]);;

let CARD_INSERT_NOTIN = prove
 (`!x:A. !s.
        FINITE s /\ ~(x IN s)
        ==> CARD(x INSERT s) = SUC(CARD s)`,
  SIMP_TAC[CARD_CLAUSES]);;

let CARD_DELETE_IN = prove
 (`!x:A. !s.
        FINITE s /\ x IN s
        ==> CARD(s DELETE x) = CARD s - 1`,
  SIMP_TAC[CARD_DELETE]);;

let GRAPH_EDGE_SUBDIVISION_SOURCE_SUBSET = prove
 (`!V E V' E'.
        graph_edge_subdivision (V:A->bool) E V' E'
        ==> V SUBSET V'`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_edge_subdivision] THEN SET_TAC[]);;

let GRAPH_EDGE_SUBDIVISION_NEW_VERTEX_NEIGHBORS = prove
 (`!V E V' E' u v w:A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        V' = w INSERT V /\
        E' = {{u,w},{w,v}} UNION (E DELETE {u,v})
        ==> graph_neighbors E' w = {u,v}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph edge fresh vertices edges" THEN
  USE_THEN "edges" SUBST1_TAC THEN
  REWRITE_TAC[EXTENSION] THEN
  X_GEN_TAC `x:A` THEN
  REWRITE_TAC[IN_GRAPH_NEIGHBORS; IN_UNION; IN_INSERT;
              IN_SING; IN_DELETE] THEN
  SUBGOAL_THEN `~({w:A,x} IN E)` (LABEL_TAC "not_old") THENL
   [DISCH_THEN(LABEL_TAC "old_edge") THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `w:A`; `x:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
    ASM_REWRITE_TAC[PAIR_SET_EQ_LEFT; PAIR_SET_EQ_CROSS]]);;

let GRAPH_EDGE_SUBDIVISION_OLD_VERTEX_NEIGHBORS = prove
 (`!V E V' E' u v w x:A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        ~(w IN V) /\
        x IN V /\
        V' = w INSERT V /\
        E' = {{u,w},{w,v}} UNION (E DELETE {u,v})
        ==> graph_neighbors E' x =
            if x = u then
              w INSERT (graph_neighbors E x DELETE v)
            else if x = v then
              w INSERT (graph_neighbors E x DELETE u)
            else graph_neighbors E x`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph edge fresh x_vertex vertices edges" THEN
  USE_THEN "edges" SUBST1_TAC THEN
  REWRITE_TAC[EXTENSION] THEN
  X_GEN_TAC `y:A` THEN
  REWRITE_TAC[IN_GRAPH_NEIGHBORS; IN_UNION; IN_INSERT;
              IN_SING; IN_DELETE] THEN
  SUBGOAL_THEN `(u:A) IN V /\ (v:A) IN V /\ ~(u = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
    (LABEL_TAC "uv_distinct"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(w:A = u) /\ ~(w = v) /\ ~(w = x)`
  (CONJUNCTS_THEN2 (LABEL_TAC "w_not_u")
   (CONJUNCTS_THEN2 (LABEL_TAC "w_not_v")
    (LABEL_TAC "w_not_x"))) THENL
   [USE_THEN "fresh" MP_TAC THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(x:A) = u` THENL
   [ASM_REWRITE_TAC[PAIR_SET_EQ] THEN
    REWRITE_TAC[IN_INSERT; IN_DELETE; IN_GRAPH_NEIGHBORS];
    ASM_CASES_TAC `(x:A) = v` THENL
     [ASM_REWRITE_TAC[PAIR_SET_EQ] THEN
      REWRITE_TAC[IN_INSERT; IN_DELETE; IN_GRAPH_NEIGHBORS];
      ASM_REWRITE_TAC[PAIR_SET_EQ] THEN
      REWRITE_TAC[IN_GRAPH_NEIGHBORS]]]);;

let GRAPH_EDGE_SUBDIVISION_OLD_VERTEX_DEGREE = prove
 (`!V E V' E' x:A.
        finite_simple_graph V E /\
        graph_edge_subdivision V E V' E' /\
        x IN V
        ==> CARD(graph_neighbors E' x) =
            CARD(graph_neighbors E x)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph subdivision x_vertex" THEN
  USE_THEN "subdivision" MP_TAC THEN
  REWRITE_TAC[graph_edge_subdivision] THEN
  INTRO_TAC "@u v w. edge fresh vertices edges" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `V':A->bool`; `E':(A->bool)->bool`;
    `u:A`; `v:A`; `w:A`; `x:A`]
   GRAPH_EDGE_SUBDIVISION_OLD_VERTEX_NEIGHBORS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "neighbors") THEN
  SUBGOAL_THEN `FINITE(graph_neighbors (E:(A->bool)->bool) x)`
  (LABEL_TAC "finite_neighbors") THENL
   [MATCH_MP_TAC FINITE_GRAPH_NEIGHBORS THEN
    EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(u:A) IN V /\ (v:A) IN V /\ ~(u = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
    (LABEL_TAC "uv_distinct"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  ASM_CASES_TAC `(x:A) = u` THENL
   [POP_ASSUM SUBST_ALL_TAC THEN
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(v:A) IN graph_neighbors E u`
    (LABEL_TAC "removed_neighbor") THENL
     [ASM_REWRITE_TAC[IN_GRAPH_NEIGHBORS];
      SUBGOAL_THEN `1 <= CARD(graph_neighbors E (u:A))`
      (LABEL_TAC "degree_positive") THENL
       [MP_TAC(ISPECL
         [`{v:A}`; `graph_neighbors E (u:A)`]
         CARD_SUBSET) THEN
        ASM_REWRITE_TAC[SING_SUBSET; CARD_SING];
        SUBGOAL_THEN `~((w:A) IN graph_neighbors E u DELETE v)`
        (LABEL_TAC "fresh_neighbor") THENL
         [REWRITE_TAC[IN_DELETE] THEN
          INTRO_TAC "w_neighbor _" THEN
          USE_THEN "fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
          ACCEPT_TAC(CONJUNCT1(CONJUNCT2(MATCH_MP
           (ISPECL
            [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `w:A`]
            FINITE_SIMPLE_GRAPH_NEIGHBOR)
           (CONJ
            (ASSUME `finite_simple_graph (V:A->bool) E`)
            (ASSUME `(w:A) IN graph_neighbors E u`)))));
          SUBGOAL_THEN `FINITE(graph_neighbors E (u:A) DELETE v)`
          (LABEL_TAC "finite_remainder") THENL
           [ASM_REWRITE_TAC[FINITE_DELETE];
            ALL_TAC] THEN
          SUBGOAL_THEN
           `CARD(w INSERT (graph_neighbors E (u:A) DELETE v)) =
            SUC(CARD(graph_neighbors E u DELETE v))`
          (LABEL_TAC "insert_card") THENL
           [ACCEPT_TAC(MATCH_MP
             (ISPECL
              [`w:A`; `graph_neighbors E (u:A) DELETE v`]
              CARD_INSERT_NOTIN)
             (CONJ
              (ASSUME `FINITE(graph_neighbors E (u:A) DELETE v)`)
              (ASSUME
               `~((w:A) IN graph_neighbors E u DELETE v)`)));
            ALL_TAC] THEN
          SUBGOAL_THEN
           `CARD(graph_neighbors E (u:A) DELETE v) =
            CARD(graph_neighbors E u) - 1`
          (LABEL_TAC "delete_card") THENL
           [ACCEPT_TAC(MATCH_MP
             (ISPECL
              [`v:A`; `graph_neighbors E (u:A)`]
              CARD_DELETE_IN)
            (CONJ
              (ASSUME `FINITE(graph_neighbors E (u:A))`)
              (ASSUME `(v:A) IN graph_neighbors E u`)));
            ASM_REWRITE_TAC[] THEN
            ASM_ARITH_TAC]]]];
    ASM_CASES_TAC `(x:A) = v` THENL
     [POP_ASSUM SUBST_ALL_TAC THEN
      USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(u:A) IN graph_neighbors E v`
      (LABEL_TAC "removed_neighbor") THENL
       [REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
        SUBGOAL_THEN `{v:A,u} = {u,v}` SUBST1_TAC THENL
         [REWRITE_TAC[PAIR_SET_EQ];
          USE_THEN "edge" ACCEPT_TAC];
        SUBGOAL_THEN `1 <= CARD(graph_neighbors E (v:A))`
        (LABEL_TAC "degree_positive") THENL
         [MP_TAC(ISPECL
           [`{u:A}`; `graph_neighbors E (v:A)`]
           CARD_SUBSET) THEN
          ASM_REWRITE_TAC[SING_SUBSET; CARD_SING];
          SUBGOAL_THEN `~((w:A) IN graph_neighbors E v DELETE u)`
          (LABEL_TAC "fresh_neighbor") THENL
           [REWRITE_TAC[IN_DELETE] THEN
            INTRO_TAC "w_neighbor _" THEN
            USE_THEN "fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
            ACCEPT_TAC(CONJUNCT1(CONJUNCT2(MATCH_MP
             (ISPECL
              [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `w:A`]
              FINITE_SIMPLE_GRAPH_NEIGHBOR)
             (CONJ
              (ASSUME `finite_simple_graph (V:A->bool) E`)
              (ASSUME `(w:A) IN graph_neighbors E v`)))));
            SUBGOAL_THEN `FINITE(graph_neighbors E (v:A) DELETE u)`
            (LABEL_TAC "finite_remainder") THENL
             [ASM_REWRITE_TAC[FINITE_DELETE];
              ALL_TAC] THEN
            SUBGOAL_THEN
             `CARD(w INSERT (graph_neighbors E (v:A) DELETE u)) =
              SUC(CARD(graph_neighbors E v DELETE u))`
            (LABEL_TAC "insert_card") THENL
             [ACCEPT_TAC(MATCH_MP
               (ISPECL
                [`w:A`; `graph_neighbors E (v:A) DELETE u`]
                CARD_INSERT_NOTIN)
               (CONJ
                (ASSUME `FINITE(graph_neighbors E (v:A) DELETE u)`)
                (ASSUME
                 `~((w:A) IN graph_neighbors E v DELETE u)`)));
              ALL_TAC] THEN
            SUBGOAL_THEN
             `CARD(graph_neighbors E (v:A) DELETE u) =
              CARD(graph_neighbors E v) - 1`
            (LABEL_TAC "delete_card") THENL
             [ACCEPT_TAC(MATCH_MP
               (ISPECL
                [`u:A`; `graph_neighbors E (v:A)`]
                CARD_DELETE_IN)
               (CONJ
                (ASSUME `FINITE(graph_neighbors E (v:A))`)
              (ASSUME `(u:A) IN graph_neighbors E v`)));
              ASM_REWRITE_TAC[] THEN
              ASM_ARITH_TAC]]]];
      USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[]]]);;

let GRAPH_EDGE_SUBDIVISION_NEW_VERTEX_DEGREE = prove
 (`!V E V' E' x:A.
        finite_simple_graph V E /\
        graph_edge_subdivision V E V' E' /\
        x IN V' DIFF V
        ==> CARD(graph_neighbors E' x) = 2`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph subdivision new_vertex" THEN
  USE_THEN "subdivision" MP_TAC THEN
  REWRITE_TAC[graph_edge_subdivision] THEN
  INTRO_TAC "@u v w. edge fresh vertices edges" THEN
  SUBGOAL_THEN `(x:A) = w` SUBST_ALL_TAC THENL
   [USE_THEN "new_vertex" MP_TAC THEN ASM SET_TAC[];
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `V':A->bool`; `E':(A->bool)->bool`;
      `u:A`; `v:A`; `w:A`]
     GRAPH_EDGE_SUBDIVISION_NEW_VERTEX_NEIGHBORS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN
    MESON_TAC[HAS_SIZE; PAIR_HAS_SIZE_2]]);;

let GRAPH_SUBDIVISION_VERTEX_STRUCTURE = prove
 (`!V E V' E'.
        graph_subdivision (V:A->bool) E V' E'
        ==> finite_simple_graph V' E' /\
            V SUBSET V' /\
            (!x. x IN V
                 ==> CARD(graph_neighbors E' x) =
                     CARD(graph_neighbors E x)) /\
            (!x. x IN V' DIFF V
                 ==> CARD(graph_neighbors E' x) = 2)`,
  MATCH_MP_TAC graph_subdivision_INDUCT THEN
  CONJ_TAC THENL
   [REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
    ASM_REWRITE_TAC[SUBSET_REFL; DIFF_EQ_EMPTY; NOT_IN_EMPTY];
    REPEAT GEN_TAC THEN
    INTRO_TAC
     "(intermediate_graph source_subset source_degree new_degree)
      edge_step" THEN
    SUBGOAL_THEN `finite_simple_graph (V'':A->bool) E''`
    (LABEL_TAC "target_graph") THENL
     [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_EDGE_SUBDIVISION THEN
      EXISTS_TAC `V':A->bool` THEN
      EXISTS_TAC `E':(A->bool)->bool` THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(V':A->bool) SUBSET V''`
    (LABEL_TAC "step_subset") THENL
     [MATCH_MP_TAC(ISPECL
       [`V':A->bool`; `E':(A->bool)->bool`;
        `V'':A->bool`; `E'':(A->bool)->bool`]
       GRAPH_EDGE_SUBDIVISION_SOURCE_SUBSET) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "target_graph" ACCEPT_TAC;
      MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `V':A->bool` THEN
      ASM_REWRITE_TAC[];
      X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "x_source") THEN
      TRANS_TAC EQ_TRANS `CARD(graph_neighbors E' (x:A))` THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL
         [`V':A->bool`; `E':(A->bool)->bool`;
          `V'':A->bool`; `E'':(A->bool)->bool`; `x:A`]
         GRAPH_EDGE_SUBDIVISION_OLD_VERTEX_DEGREE) THEN
        ASM_REWRITE_TAC[] THEN
        USE_THEN "source_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "x_source" ACCEPT_TAC;
        USE_THEN "source_degree" MATCH_MP_TAC THEN
        USE_THEN "x_source" ACCEPT_TAC];
      X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "x_new") THEN
      SUBGOAL_THEN `(x:A) IN V'' /\ ~(x IN V)`
      (CONJUNCTS_THEN2
       (LABEL_TAC "x_target") (LABEL_TAC "x_not_source")) THENL
       [USE_THEN "x_new" MP_TAC THEN REWRITE_TAC[IN_DIFF];
        ALL_TAC] THEN
      ASM_CASES_TAC `(x:A) IN V'` THENL
       [TRANS_TAC EQ_TRANS `CARD(graph_neighbors E' (x:A))` THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC(ISPECL
           [`V':A->bool`; `E':(A->bool)->bool`;
            `V'':A->bool`; `E'':(A->bool)->bool`; `x:A`]
           GRAPH_EDGE_SUBDIVISION_OLD_VERTEX_DEGREE) THEN
          ASM_REWRITE_TAC[];
          USE_THEN "new_degree" MATCH_MP_TAC THEN
          ASM_REWRITE_TAC[IN_DIFF]];
        MATCH_MP_TAC(ISPECL
         [`V':A->bool`; `E':(A->bool)->bool`;
          `V'':A->bool`; `E'':(A->bool)->bool`; `x:A`]
         GRAPH_EDGE_SUBDIVISION_NEW_VERTEX_DEGREE) THEN
        ASM_REWRITE_TAC[] THEN
        ASM_REWRITE_TAC[IN_DIFF]]]]);;

let GRAPH_SUBDIVISION_VERTEX_DEGREES = prove
 (`!V E V' E'.
        graph_subdivision (V:A->bool) E V' E'
        ==> V SUBSET V' /\
            (!x. x IN V
                 ==> CARD(graph_neighbors E' x) =
                     CARD(graph_neighbors E x)) /\
            (!x. x IN V' DIFF V
                 ==> CARD(graph_neighbors E' x) = 2)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "subdivision") THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`V:A->bool`; `E:(A->bool)->bool`;
     `V':A->bool`; `E':(A->bool)->bool`]
    GRAPH_SUBDIVISION_VERTEX_STRUCTURE)
   (ASSUME `graph_subdivision (V:A->bool) E V' E'`)) THEN
  INTRO_TAC "(target_graph source_subset source_degree new_degree)" THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_SUBDIVISION_SOURCE_SUBSET = prove
 (`!V E V' E'.
        graph_subdivision (V:A->bool) E V' E'
        ==> V SUBSET V'`,
  MESON_TAC[GRAPH_SUBDIVISION_VERTEX_DEGREES]);;

let GRAPH_SUBDIVISION_SOURCE_VERTEX_DEGREE = prove
 (`!V E V' E' x:A.
        graph_subdivision V E V' E' /\
        x IN V
        ==> CARD(graph_neighbors E' x) =
            CARD(graph_neighbors E x)`,
  MESON_TAC[GRAPH_SUBDIVISION_VERTEX_DEGREES]);;

let GRAPH_SUBDIVISION_INTERNAL_VERTEX_DEGREE = prove
 (`!V E V' E' x:A.
        graph_subdivision V E V' E' /\
        x IN V' DIFF V
        ==> CARD(graph_neighbors E' x) = 2`,
  MESON_TAC[GRAPH_SUBDIVISION_VERTEX_DEGREES]);;

let GRAPH_SUBDIVISION_NONSOURCE_VERTEX_DEGREE_LE_2 = prove
 (`!V E V' E' x:A.
        graph_subdivision V E V' E' /\
        ~(x IN V)
        ==> CARD(graph_neighbors E' x) <= 2`,
  REPEAT GEN_TAC THEN INTRO_TAC "subdivision not_source" THEN
  SUBGOAL_THEN `finite_simple_graph (V':A->bool) E'`
  (LABEL_TAC "target_graph") THENL
   [MP_TAC(MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`;
       `V':A->bool`; `E':(A->bool)->bool`]
      GRAPH_SUBDIVISION_FINITE_SIMPLE)
     (ASSUME
      `graph_subdivision
        (V:A->bool) (E:(A->bool)->bool)
        (V':A->bool) (E':(A->bool)->bool)`)) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(x:A) IN V'` THENL
   [SUBGOAL_THEN `CARD(graph_neighbors E' (x:A)) = 2`
    SUBST1_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `V':A->bool`; `E':(A->bool)->bool`; `x:A`]
       GRAPH_SUBDIVISION_INTERNAL_VERTEX_DEGREE) THEN
      ASM_REWRITE_TAC[IN_DIFF];
      ARITH_TAC];
    SUBGOAL_THEN `graph_neighbors (E':(A->bool)->bool) x = {}`
    SUBST1_TAC THENL
     [REWRITE_TAC[EXTENSION; NOT_IN_EMPTY] THEN
      X_GEN_TAC `y:A` THEN
      REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
      DISCH_THEN(LABEL_TAC "edge") THEN
      MP_TAC(ISPECL
       [`V':A->bool`; `E':(A->bool)->bool`; `x:A`; `y:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS];
      REWRITE_TAC[CARD_CLAUSES] THEN ARITH_TAC]]);;

let GRAPH_NEIGHBORS_COMPLETE_GRAPH = prove
 (`!V:A->bool. !v.
        graph_neighbors (complete_graph_edges V) v =
        if v IN V then V DELETE v else {}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[EXTENSION; IN_GRAPH_NEIGHBORS;
              IN_COMPLETE_GRAPH_EDGES; PAIR_HAS_SIZE_2] THEN
  SET_TAC[]);;

let COMPLETE_GRAPH_VERTEX_DEGREE = prove
 (`!V:A->bool. !v n.
        V HAS_SIZE SUC n /\ v IN V
        ==> CARD(graph_neighbors (complete_graph_edges V) v) = n`,
  REPEAT GEN_TAC THEN INTRO_TAC "size vertex" THEN
  ASM_REWRITE_TAC[GRAPH_NEIGHBORS_COMPLETE_GRAPH] THEN
  USE_THEN "size" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE] THEN
  INTRO_TAC "finite card" THEN
  ASM_SIMP_TAC[CARD_DELETE] THEN
  ARITH_TAC);;

let COMPLETE_GRAPH_5_SUBDIVISION_SOURCE_VERTEX_DEGREE = prove
 (`!V:A->bool. !V':A->bool. !E':(A->bool)->bool. !v.
        V HAS_SIZE 5 /\
        graph_subdivision V (complete_graph_edges V) V' E' /\
        v IN V
        ==> CARD(graph_neighbors E' v) = 4`,
  REPEAT GEN_TAC THEN INTRO_TAC "size subdivision vertex" THEN
  TRANS_TAC EQ_TRANS
   `CARD(graph_neighbors (complete_graph_edges (V:A->bool)) v)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `complete_graph_edges (V:A->bool)`;
      `V':A->bool`; `E':(A->bool)->bool`; `v:A`]
     GRAPH_SUBDIVISION_SOURCE_VERTEX_DEGREE) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(ISPECL
     [`V:A->bool`; `v:A`; `4`]
     COMPLETE_GRAPH_VERTEX_DEGREE) THEN
    DISCH_THEN MATCH_MP_TAC THEN
    CONJ_TAC THENL
     [CONV_TAC NUM_REDUCE_CONV THEN USE_THEN "size" ACCEPT_TAC;
      USE_THEN "vertex" ACCEPT_TAC]]);;

let GRAPH_NEIGHBORS_COMPLETE_BIPARTITE = prove
 (`!X Y:A->bool. !v.
        DISJOINT X Y
        ==> graph_neighbors (complete_bipartite_edges X Y) v =
            if v IN X then Y else if v IN Y then X else {}`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "disjoint") THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `w:A` THEN
  REWRITE_TAC[IN_GRAPH_NEIGHBORS; IN_COMPLETE_BIPARTITE_EDGES;
              PAIR_SET_EQ] THEN
  USE_THEN "disjoint" MP_TAC THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  SET_TAC[]);;

let COMPLETE_BIPARTITE_3_3_SUBDIVISION_VERTEX_DEGREE_LE_3 = prove
 (`!X Y:A->bool. !V:A->bool. !E:(A->bool)->bool. !v:A.
        X HAS_SIZE 3 /\
        Y HAS_SIZE 3 /\
        DISJOINT X Y /\
        graph_subdivision
          (X UNION Y) (complete_bipartite_edges X Y) V E
        ==> CARD(graph_neighbors E v) <= 3`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "X_size Y_size disjoint subdivision" THEN
  ASM_CASES_TAC `(v:A) IN X UNION Y` THENL
   [SUBGOAL_THEN
     `CARD(graph_neighbors E (v:A)) =
      CARD(graph_neighbors
       (complete_bipartite_edges (X:A->bool) Y) v)`
    (LABEL_TAC "degree") THENL
     [MATCH_MP_TAC(ISPECL
       [`X UNION Y:A->bool`;
        `complete_bipartite_edges (X:A->bool) Y`;
        `V:A->bool`; `E:(A->bool)->bool`; `v:A`]
       GRAPH_SUBDIVISION_SOURCE_VERTEX_DEGREE) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "degree" (fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(ISPECL [`X:A->bool`; `Y:A->bool`; `v:A`]
       GRAPH_NEIGHBORS_COMPLETE_BIPARTITE) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
      USE_THEN "X_size" MP_TAC THEN
      USE_THEN "Y_size" MP_TAC THEN
      REWRITE_TAC[HAS_SIZE] THEN
      ASM_CASES_TAC `(v:A) IN X` THEN
      ASM_CASES_TAC `(v:A) IN Y` THEN
      ASM_REWRITE_TAC[CARD_CLAUSES] THEN ARITH_TAC];
    MP_TAC(ISPECL
     [`X UNION Y:A->bool`;
      `complete_bipartite_edges (X:A->bool) Y`;
      `V:A->bool`; `E:(A->bool)->bool`; `v:A`]
     GRAPH_SUBDIVISION_NONSOURCE_VERTEX_DEGREE_LE_2) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* Transitivity and injective transport of graph subdivisions.               *)
(* ------------------------------------------------------------------------- *)

let GRAPH_SUBDIVISION_STEP = prove
 (`!V V' V'':A->bool.
   !E E' E'':(A->bool)->bool.
        graph_subdivision V E V' E' /\
        graph_edge_subdivision V' E' V'' E''
        ==> graph_subdivision V E V'' E''`,
  MESON_TAC[graph_subdivision_RULES]);;

let GRAPH_SUBDIVISION_SUBGRAPH = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !V':A->bool. !E':(A->bool)->bool.
        graph_subdivision V E V' E'
        ==> !W:A->bool. !D:(A->bool)->bool.
              finite_simple_graph W D /\
              W SUBSET V /\
              D SUBSET induced_subgraph_edges E W
              ==> ?W':A->bool. ?D':(A->bool)->bool.
                    graph_subdivision W D W' D' /\
                    W' SUBSET V' /\
                    D' SUBSET induced_subgraph_edges E' W'`,
  MATCH_MP_TAC graph_subdivision_INDUCT THEN
  CONJ_TAC THENL
   [REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "ambient_graph") THEN
    REPEAT GEN_TAC THEN
    INTRO_TAC "graph vertices edges" THEN
    MAP_EVERY EXISTS_TAC
     [`W:A->bool`; `D:(A->bool)->bool`] THEN
    ASM_REWRITE_TAC[SUBSET_REFL] THEN
    MATCH_MP_TAC(CONJUNCT1 graph_subdivision_RULES) THEN
    USE_THEN "graph" ACCEPT_TAC;
    REPEAT GEN_TAC THEN
    INTRO_TAC "induction edge_step" THEN
    REPEAT GEN_TAC THEN
    INTRO_TAC "graph source_vertices source_edges" THEN
    USE_THEN "induction" (MP_TAC o SPECL
     [`W:A->bool`; `D:(A->bool)->bool`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      INTRO_TAC "@P f. subdivision vertices edges"] THEN
    USE_THEN "edge_step"
     (MP_TAC o REWRITE_RULE[graph_edge_subdivision]) THEN
    INTRO_TAC "@a b w. ambient_edge fresh target_vertices target_edges" THEN
    SUBGOAL_THEN `~((w:A) IN P)` (LABEL_TAC "retained_fresh") THENL
     [DISCH_THEN(LABEL_TAC "w_retained") THEN
      USE_THEN "fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "vertices" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "w_retained" ACCEPT_TAC;
      ALL_TAC] THEN
    ASM_CASES_TAC `({a:A,b}:A->bool) IN f` THENL
     [ABBREV_TAC
       `Q:A->bool = w INSERT P` THEN
      ABBREV_TAC
       `G:(A->bool)->bool =
          {{a:A,w},{w,b}} UNION (f DELETE {a,b})` THEN
      SUBGOAL_THEN
       `graph_edge_subdivision
          (P:A->bool) f (Q:A->bool) (G:(A->bool)->bool)`
      (LABEL_TAC "retained_step") THENL
       [REWRITE_TAC[graph_edge_subdivision] THEN
        MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `w:A`] THEN
        ASM_REWRITE_TAC[] THEN
        EXPAND_TAC "Q" THEN EXPAND_TAC "G" THEN
        REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `{a:A,b} SUBSET P`
      (LABEL_TAC "edge_vertices") THENL
       [USE_THEN "edges" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
        DISCH_THEN(MP_TAC o SPEC `{a:A,b}`) THEN
        ASM_REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[];
        ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC
       [`Q:A->bool`; `G:(A->bool)->bool`] THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC(CONJUNCT2 graph_subdivision_RULES) THEN
        MAP_EVERY EXISTS_TAC
         [`P:A->bool`; `f:(A->bool)->bool`] THEN
        ASM_REWRITE_TAC[];
        EXPAND_TAC "Q" THEN
        USE_THEN "target_vertices" SUBST1_TAC THEN
        REWRITE_TAC[INSERT_SUBSET; IN_INSERT] THEN
        MATCH_MP_TAC SUBSET_TRANS THEN
        EXISTS_TAC `V':A->bool` THEN
        ASM_REWRITE_TAC[] THEN
        MATCH_ACCEPT_TAC(SET_RULE
         `(V':A->bool) SUBSET w INSERT V'`);
        EXPAND_TAC "Q" THEN EXPAND_TAC "G" THEN
        USE_THEN "target_edges" SUBST1_TAC THEN
        REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES;
                    IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_DELETE] THEN
        X_GEN_TAC `d:A->bool` THEN
        DISCH_THEN(DISJ_CASES_THEN2
         (DISJ_CASES_THEN2 SUBST1_TAC SUBST1_TAC)
         (LABEL_TAC "old_edge")) THENL
         [CONJ_TAC THENL
           [REWRITE_TAC[IN_UNION; IN_INSERT];
            USE_THEN "edge_vertices" MP_TAC THEN
            REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
            INTRO_TAC "a_vertex b_vertex" THEN
            X_GEN_TAC `x:A` THEN
            REWRITE_TAC[IN_INSERT; IN_SING] THEN
            DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
            ASM_REWRITE_TAC[IN_INSERT]];
          CONJ_TAC THENL
           [REWRITE_TAC[IN_UNION; IN_INSERT];
            USE_THEN "edge_vertices" MP_TAC THEN
            REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
            INTRO_TAC "a_vertex b_vertex" THEN
            X_GEN_TAC `x:A` THEN
            REWRITE_TAC[IN_INSERT; IN_SING] THEN
            DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
            ASM_REWRITE_TAC[IN_INSERT]];
          SUBGOAL_THEN
           `(d:A->bool) IN induced_subgraph_edges E' P`
          (LABEL_TAC "old_induced") THENL
           [USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
            ACCEPT_TAC(CONJUNCT1
             (ASSUME `(d:A->bool) IN f /\ ~(d = {a,b})`));
            USE_THEN "old_induced" MP_TAC THEN
            REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
            INTRO_TAC "old_ambient old_vertices" THEN
            CONJ_TAC THENL
             [REWRITE_TAC[IN_UNION; IN_DELETE] THEN
              DISJ2_TAC THEN ASM_REWRITE_TAC[];
              X_GEN_TAC `x:A` THEN
              DISCH_THEN(LABEL_TAC "old_vertex") THEN
              DISJ2_TAC THEN
              USE_THEN "old_vertices"
               (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
              USE_THEN "old_vertex" ACCEPT_TAC]]]];
      MAP_EVERY EXISTS_TAC
       [`P:A->bool`; `f:(A->bool)->bool`] THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "subdivision" ACCEPT_TAC;
        USE_THEN "target_vertices" SUBST1_TAC THEN
        MATCH_MP_TAC SUBSET_TRANS THEN
        EXISTS_TAC `V':A->bool` THEN
        ASM_REWRITE_TAC[] THEN
        MATCH_ACCEPT_TAC(SET_RULE
         `(V':A->bool) SUBSET w INSERT V'`);
        USE_THEN "target_edges" SUBST1_TAC THEN
        REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
        X_GEN_TAC `d:A->bool` THEN DISCH_THEN(LABEL_TAC "retained") THEN
        SUBGOAL_THEN
         `(d:A->bool) IN induced_subgraph_edges E' P`
        (LABEL_TAC "old_induced") THENL
         [USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          USE_THEN "retained" ACCEPT_TAC;
          USE_THEN "old_induced" MP_TAC THEN
          REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES;
                      IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_DELETE] THEN
          INTRO_TAC "old_ambient old_vertices" THEN
          SUBGOAL_THEN `~((d:A->bool) = {a,b})`
          (LABEL_TAC "not_removed") THENL
           [DISCH_THEN SUBST_ALL_TAC THEN
            FIRST_X_ASSUM(MATCH_MP_TAC o NOT_ELIM) THEN
            USE_THEN "retained" ACCEPT_TAC;
            CONJ_TAC THENL
             [DISJ2_TAC THEN ASM_REWRITE_TAC[];
              USE_THEN "old_vertices"
               (ACCEPT_TAC o REWRITE_RULE[SUBSET])]]]]]]);;

let IMAGE_SET_INJECTIVE = prove
 (`!f:A->B.
        (!x y. f x = f y ==> x = y)
        ==> !s t. IMAGE f s = IMAGE f t ==> s = t`,
  GEN_TAC THEN DISCH_THEN(LABEL_TAC "injective") THEN
  REPEAT GEN_TAC THEN
  REWRITE_TAC[EXTENSION; IN_IMAGE] THEN
  DISCH_THEN(LABEL_TAC "same_image") THEN
  X_GEN_TAC `x:A` THEN
  USE_THEN "same_image" (MP_TAC o SPEC `(f:A->B) x`) THEN
  USE_THEN "injective" MP_TAC THEN MESON_TAC[]);;

let FINITE_SIMPLE_GRAPH_IMAGE = prove
 (`!f:A->B V E.
        (!x y. f x = f y ==> x = y) /\
        finite_simple_graph V E
        ==> finite_simple_graph
             (IMAGE f V) (IMAGE (IMAGE f) E)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective graph" THEN
  USE_THEN "graph" MP_TAC THEN
  REWRITE_TAC[finite_simple_graph] THEN
  INTRO_TAC "finite_vertices finite_edges edge" THEN
  REWRITE_TAC[finite_simple_graph] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_IMAGE THEN
    USE_THEN "finite_vertices" ACCEPT_TAC;
    MATCH_MP_TAC FINITE_IMAGE THEN
    USE_THEN "finite_edges" ACCEPT_TAC;
    X_GEN_TAC `d:B->bool` THEN
    REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@e. edge_image old_edge" THEN
    USE_THEN "edge_image" SUBST1_TAC THEN
    SUBGOAL_THEN `(e:A->bool) SUBSET V /\ e HAS_SIZE 2`
    (CONJUNCTS_THEN2 (LABEL_TAC "edge_subset") (LABEL_TAC "edge_size")) THENL
     [USE_THEN "edge" MATCH_MP_TAC THEN
      USE_THEN "old_edge" ACCEPT_TAC;
      CONJ_TAC THENL
       [MATCH_MP_TAC IMAGE_SUBSET THEN
        USE_THEN "edge_subset" ACCEPT_TAC;
        MATCH_MP_TAC HAS_SIZE_IMAGE_INJ THEN
        CONJ_TAC THENL
         [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
          INTRO_TAC "_ _ same" THEN
          USE_THEN "injective" MATCH_MP_TAC THEN
          USE_THEN "same" ACCEPT_TAC;
          USE_THEN "edge_size" ACCEPT_TAC]]]]);;

let GRAPH_EDGE_SUBDIVISION_IMAGE = prove
 (`!f:A->B V E V' E'.
        (!x y. f x = f y ==> x = y) /\
        graph_edge_subdivision V E V' E'
        ==> graph_edge_subdivision
             (IMAGE f V) (IMAGE (IMAGE f) E)
             (IMAGE f V') (IMAGE (IMAGE f) E')`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective subdivision" THEN
  USE_THEN "subdivision" MP_TAC THEN
  REWRITE_TAC[graph_edge_subdivision] THEN
  INTRO_TAC "@u v w. edge fresh vertices edges" THEN
  REWRITE_TAC[graph_edge_subdivision] THEN
  MAP_EVERY EXISTS_TAC [`(f:A->B) u`; `(f:A->B) v`; `(f:A->B) w`] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_IMAGE] THEN
    EXISTS_TAC `{u:A,v}` THEN
    ASM_REWRITE_TAC[IMAGE_CLAUSES];
    REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@x. same x_vertex" THEN
    SUBGOAL_THEN `(w:A) = x` (LABEL_TAC "equal") THENL
     [USE_THEN "injective" MATCH_MP_TAC THEN
      USE_THEN "same" ACCEPT_TAC;
      ASM_MESON_TAC[]];
    ASM_REWRITE_TAC[IMAGE_CLAUSES];
    USE_THEN "edges" SUBST1_TAC THEN
    REWRITE_TAC[IMAGE_UNION; IMAGE_CLAUSES] THEN
    SUBGOAL_THEN
     `IMAGE (IMAGE (f:A->B)) (E DELETE {u,v}) =
      IMAGE (IMAGE f) E DELETE {f u,f v}`
    SUBST1_TAC THENL
     [SUBGOAL_THEN
       `({(f:A->B) u,f v}:B->bool) = IMAGE f {u,v}`
      SUBST1_TAC THENL
       [REWRITE_TAC[IMAGE_CLAUSES];
        ALL_TAC] THEN
      MATCH_MP_TAC IMAGE_DELETE_INJ THEN
      X_GEN_TAC `d:A->bool` THEN
      INTRO_TAC "old same_image" THEN
      MATCH_MP_TAC(SPECL
       [`d:A->bool`; `{u:A,v}`]
       (MATCH_MP
        (ISPEC `f:A->B` IMAGE_SET_INJECTIVE)
        (ASSUME `!x y:A. (f:A->B) x = f y ==> x = y`))) THEN
      USE_THEN "same_image" ACCEPT_TAC;
      REFL_TAC]]);;

let GRAPH_SUBDIVISION_IMAGE = prove
 (`!V E V' E'.
        graph_subdivision (V:A->bool) E V' E'
        ==> !f:A->B.
              (!x y. f x = f y ==> x = y)
              ==> graph_subdivision
                   (IMAGE f V) (IMAGE (IMAGE f) E)
                   (IMAGE f V') (IMAGE (IMAGE f) E')`,
  MATCH_MP_TAC graph_subdivision_INDUCT THEN
  CONJ_TAC THENL
   [REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
    GEN_TAC THEN DISCH_THEN(LABEL_TAC "injective") THEN
    MATCH_MP_TAC(CONJUNCT1 graph_subdivision_RULES) THEN
    MATCH_MP_TAC FINITE_SIMPLE_GRAPH_IMAGE THEN
    ASM_REWRITE_TAC[];
    REPEAT GEN_TAC THEN
    INTRO_TAC "induction edge_step" THEN
    GEN_TAC THEN DISCH_THEN(LABEL_TAC "injective") THEN
    MATCH_MP_TAC(CONJUNCT2 graph_subdivision_RULES) THEN
    EXISTS_TAC `IMAGE (f:A->B) V'` THEN
    EXISTS_TAC `IMAGE (IMAGE (f:A->B)) E'` THEN
    CONJ_TAC THENL
     [USE_THEN "induction" MATCH_MP_TAC THEN
      USE_THEN "injective" ACCEPT_TAC;
      MATCH_MP_TAC GRAPH_EDGE_SUBDIVISION_IMAGE THEN
      ASM_REWRITE_TAC[]]]);;

let SWAP_INJECTIVE = prove
 (`!a b x y:A.
        swap(a,b) x = swap(a,b) y
        ==> x = y`,
  MESON_TAC[SWAP_GALOIS]);;

let IMAGE_SWAP_FIX_SET = prove
 (`!S:A->bool. !a b.
        ~(a IN S) /\ ~(b IN S)
        ==> IMAGE (swap(a,b)) S = S`,
  REPEAT GEN_TAC THEN INTRO_TAC "a_fresh b_fresh" THEN
  REWRITE_TAC[EXTENSION; IN_IMAGE] THEN X_GEN_TAC `x:A` THEN
  EQ_TAC THENL
   [INTRO_TAC "@y. image y_member" THEN
    SUBGOAL_THEN `swap(a:A,b) y = y` (LABEL_TAC "fixed") THENL
     [MATCH_MP_TAC SWAP_OTHER THEN ASM SET_TAC[];
      USE_THEN "image" MP_TAC THEN ASM_REWRITE_TAC[]];
    DISCH_THEN(LABEL_TAC "member") THEN
    EXISTS_TAC `x:A` THEN CONJ_TAC THENL
     [CONV_TAC SYM_CONV THEN MATCH_MP_TAC SWAP_OTHER THEN ASM SET_TAC[];
      USE_THEN "member" ACCEPT_TAC]]);;

let IMAGE_SWAP_REPLACE_FRESH = prove
 (`!S:A->bool. !u v.
        v IN S /\ ~(u IN S)
        ==> IMAGE (swap(u,v)) S = u INSERT (S DELETE v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "present fresh" THEN
  REWRITE_TAC[EXTENSION; IN_IMAGE; IN_INSERT; IN_DELETE; swap] THEN
  ASM_MESON_TAC[]);;

let SWAP_INVOLUTION_APPLY = prove
 (`!a b x:A. swap(a,b) (swap(a,b) x) = x`,
  MESON_TAC[SWAP_GALOIS]);;

let GRAPH_NEIGHBORS_IMAGE_SWAP = prove
 (`!D:(A->bool)->bool. !a b v:A.
        graph_neighbors (IMAGE (IMAGE (swap(a,b))) D) (swap(a,b) v) =
        IMAGE (swap(a,b)) (graph_neighbors D v)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[EXTENSION] THEN
  X_GEN_TAC `x:A` THEN
  REWRITE_TAC[IN_GRAPH_NEIGHBORS; IN_IMAGE] THEN EQ_TAC THENL
   [INTRO_TAC "@d. edge_image edge" THEN
    EXISTS_TAC `swap(a:A,b) x` THEN
    CONJ_TAC THENL
     [CONV_TAC SYM_CONV THEN MATCH_ACCEPT_TAC SWAP_INVOLUTION_APPLY;
      SUBGOAL_THEN `(d:A->bool) = {v,swap(a,b) x}`
      (fun th -> USE_THEN "edge" (fun eth -> REWRITE_TAC[GSYM th; eth]))
      THEN
      MATCH_MP_TAC(SPECL
       [`d:A->bool`; `{v:A,swap(a,b) x}`]
       (MATCH_MP
        (ISPEC `swap(a:A,b):A->A` IMAGE_SET_INJECTIVE)
        (prove
          (`!y z:A.
              swap(a,b) y = swap(a,b) z ==> y = z`,
           MESON_TAC[SWAP_GALOIS])))) THEN
      USE_THEN "edge_image" MP_TAC THEN
      ASM_REWRITE_TAC[IMAGE_CLAUSES; SWAP_INVOLUTION_APPLY]];
    INTRO_TAC "@y. image neighbor" THEN
    EXISTS_TAC `{v:A,y}` THEN
    ASM_REWRITE_TAC[IMAGE_CLAUSES]]);;

let GRAPH_NEIGHBORS_SWAP_FRESH = prove
 (`!W:A->bool. !D:(A->bool)->bool. !u v:A.
        finite_simple_graph W D /\
        ~(u = v) /\
        ~(u IN W)
        ==> graph_neighbors
             (IMAGE (IMAGE (swap(u,v))) D) u =
            graph_neighbors D v`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph distinct fresh" THEN
  SUBGOAL_THEN
   `~((u:A) IN graph_neighbors D v) /\
    ~((v:A) IN graph_neighbors D v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_not_neighbor")
   (LABEL_TAC "v_not_neighbor")) THENL
   [CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "neighbor") THEN
      MP_TAC(ISPECL
       [`W:A->bool`; `D:(A->bool)->bool`; `v:A`; `u:A`]
       FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[];
      DISCH_THEN(LABEL_TAC "neighbor") THEN
      MP_TAC(ISPECL
       [`W:A->bool`; `D:(A->bool)->bool`; `v:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`D:(A->bool)->bool`; `u:A`; `v:A`; `v:A`]
   GRAPH_NEIGHBORS_IMAGE_SWAP) THEN
  ASM_REWRITE_TAC[SWAP_RIGHT] THEN
  DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC IMAGE_SWAP_FIX_SET THEN
  ASM_REWRITE_TAC[]);;

let IMAGE_COMPLETE_GRAPH_EDGES_INJECTIVE = prove
 (`!f:A->B. !V:A->bool.
        (!x y. f x = f y ==> x = y)
        ==> IMAGE (IMAGE f) (complete_graph_edges V) =
            complete_graph_edges (IMAGE f V)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "injective") THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `e:B->bool` THEN
  REWRITE_TAC[IN_IMAGE; IN_COMPLETE_GRAPH_EDGES] THEN EQ_TAC THENL
   [INTRO_TAC "@d. edge_image old_edge" THEN
    USE_THEN "edge_image" SUBST1_TAC THEN
    USE_THEN "old_edge"
     (CONJUNCTS_THEN2 (LABEL_TAC "subset") (LABEL_TAC "size")) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC IMAGE_SUBSET THEN USE_THEN "subset" ACCEPT_TAC;
      MATCH_MP_TAC HAS_SIZE_IMAGE_INJ THEN
      CONJ_TAC THENL
       [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
        INTRO_TAC "_ _ same" THEN
        USE_THEN "injective" MATCH_MP_TAC THEN USE_THEN "same" ACCEPT_TAC;
        USE_THEN "size" ACCEPT_TAC]];
    INTRO_TAC "subset size" THEN
    USE_THEN "size" MP_TAC THEN
    REWRITE_TAC[HAS_SIZE_CONV `(e:B->bool) HAS_SIZE 2`] THEN
    INTRO_TAC "@a b. distinct edge_value" THEN
    USE_THEN "edge_value" SUBST_ALL_TAC THEN
    SUBGOAL_THEN
     `?x:A. (f:A->B) x = a /\ x IN V`
    (X_CHOOSE_THEN `x:A`
     (CONJUNCTS_THEN2 (LABEL_TAC "x_image") (LABEL_TAC "x_vertex")))
    THENL
     [USE_THEN "subset" MP_TAC THEN
      REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_IMAGE] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `?y:A. (f:A->B) y = b /\ y IN V`
    (X_CHOOSE_THEN `y:A`
     (CONJUNCTS_THEN2 (LABEL_TAC "y_image") (LABEL_TAC "y_vertex")))
    THENL
     [USE_THEN "subset" MP_TAC THEN
      REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_IMAGE] THEN MESON_TAC[];
      ALL_TAC] THEN
    EXISTS_TAC `{x:A,y}` THEN
    CONJ_TAC THENL
     [ASM_REWRITE_TAC[IMAGE_CLAUSES];
      REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `~(x:A = y)` (LABEL_TAC "xy_distinct") THENL
       [DISCH_THEN SUBST_ALL_TAC THEN ASM_MESON_TAC[];
        MAP_EVERY EXISTS_TAC [`x:A`; `y:A`] THEN
        ASM_REWRITE_TAC[]]]]);;

let IMAGE_COMPLETE_BIPARTITE_EDGES = prove
 (`!f:A->B. !X Y:A->bool.
        IMAGE (IMAGE f) (complete_bipartite_edges X Y) =
        complete_bipartite_edges (IMAGE f X) (IMAGE f Y)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[EXTENSION] THEN
  X_GEN_TAC `e:B->bool` THEN
  REWRITE_TAC[IN_IMAGE; IN_COMPLETE_BIPARTITE_EDGES] THEN
  EQ_TAC THENL
   [INTRO_TAC "@d. edge_image (@x y. x_member y_member edge_value)" THEN
    USE_THEN "edge_value" SUBST_ALL_TAC THEN
    MAP_EVERY EXISTS_TAC [`(f:A->B) x`; `(f:A->B) y`] THEN
    ASM_REWRITE_TAC[IMAGE_CLAUSES] THEN
    CONJ_TAC THENL
     [EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[]];
    INTRO_TAC
     "@x' y'. (@x. x_image x_member) (@y. y_image y_member) edge_value" THEN
    USE_THEN "x_image" SUBST_ALL_TAC THEN
    USE_THEN "y_image" SUBST_ALL_TAC THEN
    EXISTS_TAC `{x:A,y}` THEN
    ASM_REWRITE_TAC[IMAGE_CLAUSES] THEN
    MAP_EVERY EXISTS_TAC [`x:A`; `y:A`] THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_SUBDIVISION_SWAP = prove
 (`!V E V' E' a b:A.
        graph_subdivision V E V' E'
        ==> graph_subdivision
             (IMAGE (swap(a,b)) V)
             (IMAGE (IMAGE (swap(a,b))) E)
             (IMAGE (swap(a,b)) V')
             (IMAGE (IMAGE (swap(a,b))) E')`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "subdivision") THEN
  MATCH_MP_TAC(MATCH_MP
   (ISPECL
    [`V:A->bool`; `E:(A->bool)->bool`;
     `V':A->bool`; `E':(A->bool)->bool`]
    GRAPH_SUBDIVISION_IMAGE)
   (ASSUME `graph_subdivision (V:A->bool) E V' E'`)) THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
  ACCEPT_TAC(SPECL [`a:A`; `b:A`; `x:A`; `y:A`] SWAP_INJECTIVE));;

(* ------------------------------------------------------------------------- *)
(* Recovering a vertex split from a subgraph of a contraction.               *)
(* ------------------------------------------------------------------------- *)

let contract_split_side = new_definition
 `contract_split_side
    (E:(A->bool)->bool) (D:(A->bool)->bool) v =
      {w | w IN graph_neighbors D v /\ ~({v,w} IN E)}`;;

let IN_CONTRACT_SPLIT_SIDE = prove
 (`!E D:(A->bool)->bool. !v w:A.
        w IN contract_split_side E D v <=>
        w IN graph_neighbors D v /\ ~({v,w} IN E)`,
  REWRITE_TAC[contract_split_side; IN_ELIM_THM]);;

let GRAPH_CONTRACT_SUBGRAPH_EDGE_AWAY = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !D:(A->bool)->bool. !d:A->bool.
        D SUBSET graph_contract_edges V E u v /\
        d IN D /\
        ~(v IN d)
        ==> d IN E`,
  REPEAT GEN_TAC THEN INTRO_TAC "subset edge away" THEN
  SUBGOAL_THEN
   `(d:A->bool) IN graph_contract_edges V E u v`
  (LABEL_TAC "contracted_edge") THENL
   [USE_THEN "subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "edge" ACCEPT_TAC;
    USE_THEN "contracted_edge" MP_TAC THEN
    REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "old")
     (X_CHOOSE_THEN `w:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "neighbor")
       (CONJUNCTS_THEN2 (LABEL_TAC "not_v")
        (LABEL_TAC "edge_value"))))) THENL
     [ACCEPT_TAC(CONJUNCT1(ASSUME
       `(d:A->bool) IN E /\ d SUBSET V DELETE u`));
      USE_THEN "edge_value" SUBST_ALL_TAC THEN
      USE_THEN "away" MP_TAC THEN
      REWRITE_TAC[IN_INSERT]]]);;

let GRAPH_CONTRACT_SUBGRAPH_MISSING_EDGE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !D:(A->bool)->bool. !w:A.
        D SUBSET graph_contract_edges V E u v /\
        {v,w} IN D /\
        ~({v,w} IN E)
        ==> {u,w} IN E`,
  REPEAT GEN_TAC THEN INTRO_TAC "subset edge missing" THEN
  SUBGOAL_THEN
   `({v:A,w}:A->bool) IN graph_contract_edges V E u v`
  (LABEL_TAC "contracted_edge") THENL
   [USE_THEN "subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "edge" ACCEPT_TAC;
    USE_THEN "contracted_edge" MP_TAC THEN
    REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "old")
     (X_CHOOSE_THEN `z:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "neighbor")
       (CONJUNCTS_THEN2 (LABEL_TAC "not_v")
        (LABEL_TAC "edge_value"))))) THENL
     [CONTR_TAC(MP
       (NOT_ELIM(ASSUME `~(({v:A,w}:A->bool) IN E)`))
       (CONJUNCT1(ASSUME
        `({v:A,w}:A->bool) IN E /\ {v,w} SUBSET V DELETE u`)));
      SUBGOAL_THEN `(w:A) = z` SUBST_ALL_TAC THENL
       [USE_THEN "edge_value" MP_TAC THEN
        REWRITE_TAC[PAIR_SET_EQ_LEFT];
        USE_THEN "neighbor" MP_TAC THEN
        REWRITE_TAC[IN_GRAPH_NEIGHBORS]]]]);;

let GRAPH_CONTRACT_SUBGRAPH_SPLIT_DATA = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !D:(A->bool)->bool.
        D SUBSET graph_contract_edges V E u v
        ==> (!d. d IN D /\ ~(v IN d) ==> d IN E) /\
            (!w. w IN contract_split_side E D v
                 ==> {u,w} IN E) /\
            (!w. w IN graph_neighbors D v /\
                 ~(w IN contract_split_side E D v)
                 ==> {v,w} IN E)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "subset") THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `d:A->bool` THEN INTRO_TAC "edge away" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
      `D:(A->bool)->bool`; `d:A->bool`]
     GRAPH_CONTRACT_SUBGRAPH_EDGE_AWAY) THEN
    ASM_REWRITE_TAC[];
    X_GEN_TAC `w:A` THEN
    REWRITE_TAC[IN_CONTRACT_SPLIT_SIDE] THEN
    INTRO_TAC "neighbor missing" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
      `D:(A->bool)->bool`; `w:A`]
     GRAPH_CONTRACT_SUBGRAPH_MISSING_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "neighbor"
     (ACCEPT_TAC o REWRITE_RULE[IN_GRAPH_NEIGHBORS]);
    X_GEN_TAC `w:A` THEN
    REWRITE_TAC[IN_CONTRACT_SPLIT_SIDE] THEN
    MESON_TAC[]]);;

let CONTRACT_SPLIT_SIDE_SUBSET_NEIGHBORS = prove
 (`!E D:(A->bool)->bool. !v:A.
        contract_split_side E D v SUBSET graph_neighbors D v`,
  REWRITE_TAC[SUBSET; IN_CONTRACT_SPLIT_SIDE] THEN MESON_TAC[]);;

let FINITE_CONTRACT_SPLIT_SIDE = prove
 (`!E D:(A->bool)->bool. !v:A.
        FINITE(graph_neighbors D v)
        ==> FINITE(contract_split_side E D v)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "finite") THEN
  MATCH_MP_TAC FINITE_SUBSET THEN
  EXISTS_TAC `graph_neighbors (D:(A->bool)->bool) v` THEN
  ASM_REWRITE_TAC[CONTRACT_SPLIT_SIDE_SUBSET_NEIGHBORS]);;

let FINITE_SIMPLE_GRAPH_INCIDENT_EDGE = prove
 (`!W:A->bool. !D:(A->bool)->bool. !d:A->bool. !v:A.
        finite_simple_graph W D /\
        d IN D /\
        v IN d
        ==> ?w. w IN graph_neighbors D v /\ d = {v,w}`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph edge incident" THEN
  SUBGOAL_THEN `(d:A->bool) HAS_SIZE 2` (LABEL_TAC "size") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    INTRO_TAC "_ _ edge_data" THEN
    USE_THEN "edge_data" (fun eth ->
     USE_THEN "edge" (fun dth ->
      ACCEPT_TAC(CONJUNCT2(MATCH_MP
       (SPEC `d:A->bool` eth) dth))));
    USE_THEN "size" MP_TAC THEN
    REWRITE_TAC[HAS_SIZE_CONV `(d:A->bool) HAS_SIZE 2`] THEN
    INTRO_TAC "@a b. distinct edge_value" THEN
    USE_THEN "edge_value" SUBST_ALL_TAC THEN
    USE_THEN "incident" MP_TAC THEN
    REWRITE_TAC[IN_INSERT; IN_SING] THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
     [EXISTS_TAC `b:A` THEN
      ASM_REWRITE_TAC[IN_GRAPH_NEIGHBORS];
      EXISTS_TAC `a:A` THEN
      REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
      SUBGOAL_THEN `{b:A,a} = {a,b}` SUBST1_TAC THENL
       [REWRITE_TAC[PAIR_SET_EQ];
        ASM_REWRITE_TAC[]]]]);;

let GRAPH_CONTRACT_SUBGRAPH_LIFT_ONE_EDGES = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !W:A->bool. !D:(A->bool)->bool. !w:A.
        finite_simple_graph W D /\
        {u,v} IN E /\
        D SUBSET graph_contract_edges V E u v /\
        contract_split_side E D v = {w}
        ==> {{v,u},{u,w}} UNION (D DELETE {v,w}) SUBSET E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph contracted_edge subset side" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
    `D:(A->bool)->bool`]
   GRAPH_CONTRACT_SUBGRAPH_SPLIT_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "away_edge u_edge v_edge" THEN
  SUBGOAL_THEN `(w:A) IN contract_split_side E D v`
  (LABEL_TAC "w_side") THENL
   [ASM_REWRITE_TAC[IN_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN `(w:A) IN graph_neighbors D v`
  (LABEL_TAC "w_neighbor") THENL
   [USE_THEN "w_side" MP_TAC THEN
    REWRITE_TAC[IN_CONTRACT_SPLIT_SIDE] THEN MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[UNION_SUBSET; INSERT_SUBSET; EMPTY_SUBSET] THEN
  REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN `{v:A,u} = {u,v}` SUBST1_TAC THENL
     [SET_TAC[];
      USE_THEN "contracted_edge" ACCEPT_TAC];
    USE_THEN "u_edge" MATCH_MP_TAC THEN
    REWRITE_TAC[IN_SING];
    REWRITE_TAC[SUBSET; IN_DELETE] THEN
    X_GEN_TAC `d:A->bool` THEN INTRO_TAC "edge not_replaced" THEN
    ASM_CASES_TAC `(v:A) IN d` THENL
     [MP_TAC(ISPECL
       [`W:A->bool`; `D:(A->bool)->bool`; `d:A->bool`; `v:A`]
       FINITE_SIMPLE_GRAPH_INCIDENT_EDGE) THEN
      ASM_REWRITE_TAC[] THEN
      INTRO_TAC "@z. z_neighbor edge_value" THEN
      USE_THEN "edge_value" SUBST_ALL_TAC THEN
      SUBGOAL_THEN `~((z:A) IN contract_split_side E D v)`
      (LABEL_TAC "z_not_side") THENL
       [DISCH_THEN(LABEL_TAC "z_side") THEN
        SUBGOAL_THEN `(z:A) = w` SUBST_ALL_TAC THENL
         [USE_THEN "side" MP_TAC THEN
          USE_THEN "z_side" MP_TAC THEN SET_TAC[];
          USE_THEN "not_replaced" (fun nth ->
           CONTR_TAC(MP (NOT_ELIM nth) (REFL `{v:A,w}`)))];
        USE_THEN "v_edge" MATCH_MP_TAC THEN
        CONJ_TAC THENL
         [USE_THEN "z_neighbor" ACCEPT_TAC;
          USE_THEN "side" (fun th -> REWRITE_TAC[GSYM th]) THEN
          USE_THEN "z_not_side" ACCEPT_TAC]];
      USE_THEN "away_edge" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]]]);;

let GRAPH_CONTRACT_SUBDIVISION_LIFT_ONE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !W:A->bool. !D:(A->bool)->bool.
   !W':A->bool. !D':(A->bool)->bool. !w:A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        graph_subdivision W D W' D' /\
        W' SUBSET V DELETE u /\
        D' SUBSET graph_contract_edges V E u v /\
        contract_split_side E D' v = {w}
        ==> ?W'':A->bool. ?D'':(A->bool)->bool.
              graph_subdivision W D W'' D'' /\
              W'' SUBSET V /\
              D'' SUBSET induced_subgraph_edges E W''`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "ambient_graph contracted_edge subdivision vertices edges side" THEN
  SUBGOAL_THEN `finite_simple_graph (W':A->bool) D'`
  (LABEL_TAC "target_graph") THENL
   [MP_TAC(MATCH_MP
     (ISPECL
      [`W:A->bool`; `D:(A->bool)->bool`;
       `W':A->bool`; `D':(A->bool)->bool`]
      GRAPH_SUBDIVISION_FINITE_SIMPLE)
     (ASSUME
      `graph_subdivision
        (W:A->bool) (D:(A->bool)->bool)
        (W':A->bool) (D':(A->bool)->bool)`)) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(w:A) IN graph_neighbors D' v`
  (LABEL_TAC "w_neighbor") THENL
   [SUBGOAL_THEN `(w:A) IN contract_split_side E D' v`
    (LABEL_TAC "w_side") THENL
     [ASM_REWRITE_TAC[IN_SING];
      USE_THEN "w_side" MP_TAC THEN
      REWRITE_TAC[IN_CONTRACT_SPLIT_SIDE] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(u:A) IN V /\ (v:A) IN V /\ ~(u = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
    (LABEL_TAC "distinct"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) IN W')` (LABEL_TAC "fresh") THENL
   [USE_THEN "vertices" MP_TAC THEN
    REWRITE_TAC[SUBSET; IN_DELETE] THEN
    DISCH_THEN(MP_TAC o SPEC `u:A`) THEN MESON_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC
   `D'' = {{v:A,u},{u,w}} UNION
          (D' DELETE {v,w}):(A->bool)->bool` THEN
  SUBGOAL_THEN
   `graph_edge_subdivision
      (W':A->bool) D' (u INSERT W') D''`
  (LABEL_TAC "edge_step") THENL
   [REWRITE_TAC[graph_edge_subdivision] THEN
    MAP_EVERY EXISTS_TAC [`v:A`; `w:A`; `u:A`] THEN
    CONJ_TAC THENL
     [USE_THEN "w_neighbor"
       (ACCEPT_TAC o REWRITE_RULE[IN_GRAPH_NEIGHBORS]);
      CONJ_TAC THENL
       [USE_THEN "fresh" ACCEPT_TAC;
        CONJ_TAC THENL
         [REFL_TAC;
          EXPAND_TAC "D''" THEN REFL_TAC]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_subdivision
      (W:A->bool) (D:(A->bool)->bool)
      (u INSERT W':A->bool) (D'':(A->bool)->bool)`
  (LABEL_TAC "lifted_subdivision") THENL
   [MATCH_ACCEPT_TAC(MATCH_MP GRAPH_SUBDIVISION_STEP
     (CONJ
      (ASSUME
       `graph_subdivision
         (W:A->bool) (D:(A->bool)->bool)
         (W':A->bool) (D':(A->bool)->bool)`)
      (ASSUME
       `graph_edge_subdivision
         (W':A->bool) (D':(A->bool)->bool)
         (u INSERT W':A->bool) (D'':(A->bool)->bool)`)));
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (u INSERT W':A->bool) D''`
  (LABEL_TAC "lifted_graph") THENL
   [USE_THEN "target_graph" (fun gth ->
     USE_THEN "edge_step" (fun eth ->
      MATCH_ACCEPT_TAC(MATCH_MP
       FINITE_SIMPLE_GRAPH_EDGE_SUBDIVISION
       (CONJ gth eth))));
    ALL_TAC] THEN
  SUBGOAL_THEN `(D'':(A->bool)->bool) SUBSET E`
  (LABEL_TAC "lifted_edges") THENL
   [EXPAND_TAC "D''" THEN
    USE_THEN "target_graph" (fun gth ->
     USE_THEN "contracted_edge" (fun cth ->
      USE_THEN "edges" (fun eth ->
       USE_THEN "side" (fun sth ->
        MATCH_ACCEPT_TAC(MATCH_MP
         GRAPH_CONTRACT_SUBGRAPH_LIFT_ONE_EDGES
         (CONJ gth (CONJ cth (CONJ eth sth))))))));
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`u INSERT W':A->bool`; `D'':(A->bool)->bool`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "lifted_subdivision" ACCEPT_TAC;
    REWRITE_TAC[SUBSET; IN_INSERT] THEN
    X_GEN_TAC `x:A` THEN
    DISCH_THEN(DISJ_CASES_THEN2 SUBST1_TAC (LABEL_TAC "old_vertex")) THENL
     [USE_THEN "u_vertex" ACCEPT_TAC;
      SUBGOAL_THEN `(x:A) IN V DELETE u` (LABEL_TAC "old_target") THENL
       [USE_THEN "vertices" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "old_vertex" ACCEPT_TAC;
        USE_THEN "old_target" MP_TAC THEN
        REWRITE_TAC[IN_DELETE] THEN MESON_TAC[]]];
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
    X_GEN_TAC `d:A->bool` THEN DISCH_THEN(LABEL_TAC "lifted_edge") THEN
    CONJ_TAC THENL
     [USE_THEN "lifted_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "lifted_graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN
      INTRO_TAC "_ _ edge_data" THEN
      USE_THEN "edge_data" (fun eth ->
       USE_THEN "lifted_edge" (fun dth ->
        MP_TAC(CONJUNCT1(MATCH_MP
         (SPEC `d:A->bool` eth) dth)) THEN
        SET_TAC[]))]]);;

let GRAPH_CONTRACT_SUBGRAPH_LIFT_EMPTY_EDGES = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !W:A->bool. !D:(A->bool)->bool.
        finite_simple_graph W D /\
        D SUBSET graph_contract_edges V E u v /\
        contract_split_side E D v = {}
        ==> D SUBSET E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph subset side" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
    `D:(A->bool)->bool`]
   GRAPH_CONTRACT_SUBGRAPH_SPLIT_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "away_edge _ v_edge" THEN
  REWRITE_TAC[SUBSET] THEN
  X_GEN_TAC `d:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
  ASM_CASES_TAC `(v:A) IN d` THENL
   [MP_TAC(ISPECL
     [`W:A->bool`; `D:(A->bool)->bool`; `d:A->bool`; `v:A`]
     FINITE_SIMPLE_GRAPH_INCIDENT_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@z. z_neighbor edge_value" THEN
    USE_THEN "edge_value" SUBST_ALL_TAC THEN
    USE_THEN "v_edge" MATCH_MP_TAC THEN
    CONJ_TAC THENL
     [USE_THEN "z_neighbor" ACCEPT_TAC;
      USE_THEN "side" (fun th -> REWRITE_TAC[th; NOT_IN_EMPTY])];
    USE_THEN "away_edge" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_CONTRACT_SUBDIVISION_LIFT_EMPTY = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !W:A->bool. !D:(A->bool)->bool.
   !W':A->bool. !D':(A->bool)->bool.
        graph_subdivision W D W' D' /\
        W' SUBSET V DELETE u /\
        D' SUBSET graph_contract_edges V E u v /\
        contract_split_side E D' v = {}
        ==> ?W'':A->bool. ?D'':(A->bool)->bool.
              graph_subdivision W D W'' D'' /\
              W'' SUBSET V /\
              D'' SUBSET induced_subgraph_edges E W''`,
  REPEAT GEN_TAC THEN INTRO_TAC "subdivision vertices edges side" THEN
  SUBGOAL_THEN `finite_simple_graph (W':A->bool) D'`
  (LABEL_TAC "target_graph") THENL
   [MP_TAC(MATCH_MP
     (ISPECL
      [`W:A->bool`; `D:(A->bool)->bool`;
       `W':A->bool`; `D':(A->bool)->bool`]
      GRAPH_SUBDIVISION_FINITE_SIMPLE)
     (ASSUME
      `graph_subdivision
        (W:A->bool) (D:(A->bool)->bool)
        (W':A->bool) (D':(A->bool)->bool)`)) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(D':(A->bool)->bool) SUBSET E`
  (LABEL_TAC "old_edges") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
      `W':A->bool`; `D':(A->bool)->bool`]
     GRAPH_CONTRACT_SUBGRAPH_LIFT_EMPTY_EDGES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`W':A->bool`; `D':(A->bool)->bool`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "subdivision" ACCEPT_TAC;
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `V DELETE (u:A)` THEN
    ASM_REWRITE_TAC[] THEN SET_TAC[];
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
    X_GEN_TAC `d:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    CONJ_TAC THENL
     [USE_THEN "old_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "target_graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN
      INTRO_TAC "_ _ edge_data" THEN
      USE_THEN "edge_data" (fun eth ->
       USE_THEN "edge" (fun dth ->
        MP_TAC(CONJUNCT1(MATCH_MP
         (SPEC `d:A->bool` eth) dth)) THEN
        SET_TAC[]))]]);;

let GRAPH_CONTRACT_SUBGRAPH_LIFT_FULL_SWAP_EDGES = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !W:A->bool. !D:(A->bool)->bool.
        finite_simple_graph W D /\
        ~(u = v) /\
        ~(u IN W) /\
        D SUBSET graph_contract_edges V E u v /\
        contract_split_side E D v = graph_neighbors D v
        ==> IMAGE (IMAGE (swap(u,v))) D SUBSET E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph distinct fresh subset side" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
    `D:(A->bool)->bool`]
   GRAPH_CONTRACT_SUBGRAPH_SPLIT_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "away_edge u_edge _" THEN
  REWRITE_TAC[SUBSET; IN_IMAGE] THEN
  X_GEN_TAC `e:A->bool` THEN
  INTRO_TAC "@d. edge_image edge" THEN
  USE_THEN "edge_image" SUBST1_TAC THEN
  SUBGOAL_THEN `(d:A->bool) SUBSET W` (LABEL_TAC "edge_subset") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    INTRO_TAC "_ _ edge_data" THEN
    USE_THEN "edge_data" (fun eth ->
     USE_THEN "edge" (fun dth ->
      MP_TAC(CONJUNCT1(MATCH_MP
       (SPEC `d:A->bool` eth) dth)) THEN
      SET_TAC[]));
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) IN d)` (LABEL_TAC "u_not_edge") THENL
   [USE_THEN "edge_subset" MP_TAC THEN
    USE_THEN "fresh" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(v:A) IN d` THENL
   [MP_TAC(ISPECL
     [`W:A->bool`; `D:(A->bool)->bool`; `d:A->bool`; `v:A`]
     FINITE_SIMPLE_GRAPH_INCIDENT_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@z. z_neighbor edge_value" THEN
    USE_THEN "edge_value" SUBST_ALL_TAC THEN
    SUBGOAL_THEN
     `(z:A) IN W /\ ~(z = u) /\ ~(z = v)`
    (CONJUNCTS_THEN2 (LABEL_TAC "z_vertex")
     (CONJUNCTS_THEN2 (LABEL_TAC "z_not_u")
      (LABEL_TAC "z_not_v"))) THENL
     [MP_TAC(ISPECL
       [`W:A->bool`; `D:(A->bool)->bool`; `v:A`; `z:A`]
       FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "fresh" MP_TAC THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(z:A) IN contract_split_side E D v`
    (LABEL_TAC "z_side") THENL
     [USE_THEN "side" (fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `{u:A,z} IN E` (LABEL_TAC "original_edge") THENL
     [USE_THEN "u_edge" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[IMAGE_CLAUSES; SWAP_RIGHT; SWAP_OTHER]];
    SUBGOAL_THEN
     `IMAGE (swap(u:A,v)) d = d`
    (LABEL_TAC "fixed_edge") THENL
     [MATCH_MP_TAC IMAGE_SWAP_FIX_SET THEN ASM_REWRITE_TAC[];
      USE_THEN "fixed_edge" SUBST1_TAC THEN
      USE_THEN "away_edge" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]]]);;

let GRAPH_CONTRACT_SUBDIVISION_LIFT_FULL_SWAP = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !W:A->bool. !D:(A->bool)->bool.
   !W':A->bool. !D':(A->bool)->bool.
        finite_simple_graph V E /\
        {u,v} IN E /\
        graph_subdivision W D W' D' /\
        W' SUBSET V DELETE u /\
        D' SUBSET graph_contract_edges V E u v /\
        contract_split_side E D' v = graph_neighbors D' v
        ==> ?W'':A->bool. ?D'':(A->bool)->bool.
              graph_subdivision
                (IMAGE (swap(u,v)) W)
                (IMAGE (IMAGE (swap(u,v))) D) W'' D'' /\
              W'' SUBSET V /\
              D'' SUBSET induced_subgraph_edges E W''`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "ambient_graph contracted_edge subdivision vertices edges side" THEN
  SUBGOAL_THEN `finite_simple_graph (W':A->bool) D'`
  (LABEL_TAC "target_graph") THENL
   [MP_TAC(MATCH_MP
     (ISPECL
      [`W:A->bool`; `D:(A->bool)->bool`;
       `W':A->bool`; `D':(A->bool)->bool`]
      GRAPH_SUBDIVISION_FINITE_SIMPLE)
     (ASSUME
      `graph_subdivision
        (W:A->bool) (D:(A->bool)->bool)
        (W':A->bool) (D':(A->bool)->bool)`)) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(u:A) IN V /\ (v:A) IN V /\ ~(u = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
    (LABEL_TAC "distinct"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) IN W')` (LABEL_TAC "fresh") THENL
   [USE_THEN "vertices" MP_TAC THEN
    REWRITE_TAC[SUBSET; IN_DELETE] THEN
    DISCH_THEN(MP_TAC o SPEC `u:A`) THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_subdivision
      (IMAGE (swap(u,v)) (W:A->bool))
      (IMAGE (IMAGE (swap(u,v))) (D:(A->bool)->bool))
      (IMAGE (swap(u,v)) (W':A->bool))
      (IMAGE (IMAGE (swap(u,v))) (D':(A->bool)->bool))`
  (LABEL_TAC "swapped_subdivision") THENL
   [MATCH_MP_TAC(ISPECL
     [`W:A->bool`; `D:(A->bool)->bool`;
      `W':A->bool`; `D':(A->bool)->bool`; `u:A`; `v:A`]
     GRAPH_SUBDIVISION_SWAP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(IMAGE (IMAGE (swap(u,v))) (D':(A->bool)->bool)) SUBSET E`
  (LABEL_TAC "swapped_edges") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
      `W':A->bool`; `D':(A->bool)->bool`]
     GRAPH_CONTRACT_SUBGRAPH_LIFT_FULL_SWAP_EDGES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph
      (IMAGE (swap(u,v)) (W':A->bool))
      (IMAGE (IMAGE (swap(u,v))) (D':(A->bool)->bool))`
  (LABEL_TAC "swapped_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_IMAGE THEN
    CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
      MATCH_ACCEPT_TAC(SPECL
       [`u:A`; `v:A`; `x:A`; `y:A`] SWAP_INJECTIVE);
      USE_THEN "target_graph" ACCEPT_TAC];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`IMAGE (swap(u,v)) (W':A->bool)`;
    `IMAGE (IMAGE (swap(u,v))) (D':(A->bool)->bool)`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "swapped_subdivision" ACCEPT_TAC;
    REWRITE_TAC[SUBSET; IN_IMAGE] THEN
    X_GEN_TAC `x:A` THEN INTRO_TAC "@y. image old_vertex" THEN
    USE_THEN "image" SUBST1_TAC THEN
    SUBGOAL_THEN `(y:A) IN V /\ ~(y = u)`
    (CONJUNCTS_THEN2 (LABEL_TAC "y_vertex") (LABEL_TAC "y_not_u"))
    THENL
     [USE_THEN "vertices" MP_TAC THEN
      REWRITE_TAC[SUBSET; IN_DELETE] THEN
      DISCH_THEN(MP_TAC o SPEC `y:A`) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_CASES_TAC `(y:A) = v` THENL
     [ASM_REWRITE_TAC[SWAP_RIGHT];
      ASM_SIMP_TAC[SWAP_OTHER]];
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
    X_GEN_TAC `d:A->bool` THEN DISCH_THEN(LABEL_TAC "swapped_edge") THEN
    CONJ_TAC THENL
     [USE_THEN "swapped_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "swapped_graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN
      INTRO_TAC "_ _ edge_data" THEN
      USE_THEN "edge_data" (fun eth ->
       USE_THEN "swapped_edge" (fun dth ->
        MP_TAC(CONJUNCT1(MATCH_MP
         (SPEC `d:A->bool` eth) dth)) THEN
        SET_TAC[]))]]);;

let GRAPH_CONTRACT_SUBGRAPH_SWAP_EDGES = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !W:A->bool. !D:(A->bool)->bool.
        finite_simple_graph V E /\
        {u,v} IN E /\
        finite_simple_graph W D /\
        W SUBSET V DELETE u /\
        D SUBSET graph_contract_edges V E u v
        ==> IMAGE (IMAGE (swap(u,v))) D SUBSET
            graph_contract_edges V E v u`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "ambient_graph contracted_edge graph vertices subset" THEN
  SUBGOAL_THEN `(u:A) IN V /\ (v:A) IN V /\ ~(u = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
    (LABEL_TAC "distinct"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
    `D:(A->bool)->bool`]
   GRAPH_CONTRACT_SUBGRAPH_SPLIT_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "away_edge u_edge v_edge" THEN
  REWRITE_TAC[SUBSET; IN_IMAGE] THEN
  X_GEN_TAC `e:A->bool` THEN
  INTRO_TAC "@d. edge_image edge" THEN
  USE_THEN "edge_image" SUBST1_TAC THEN
  SUBGOAL_THEN `(d:A->bool) SUBSET W` (LABEL_TAC "edge_subset") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    INTRO_TAC "_ _ edge_data" THEN
    USE_THEN "edge_data" (fun eth ->
     USE_THEN "edge" (fun dth ->
      MP_TAC(CONJUNCT1(MATCH_MP
       (SPEC `d:A->bool` eth) dth)) THEN
      SET_TAC[]));
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) IN d)` (LABEL_TAC "u_not_edge") THENL
   [USE_THEN "edge_subset" MP_TAC THEN
    USE_THEN "vertices" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(v:A) IN d` THENL
   [MP_TAC(ISPECL
     [`W:A->bool`; `D:(A->bool)->bool`; `d:A->bool`; `v:A`]
     FINITE_SIMPLE_GRAPH_INCIDENT_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@z. z_neighbor edge_value" THEN
    USE_THEN "edge_value" SUBST_ALL_TAC THEN
    SUBGOAL_THEN
     `(z:A) IN V /\ ~(z = u) /\ ~(z = v)`
    (CONJUNCTS_THEN2 (LABEL_TAC "z_vertex")
     (CONJUNCTS_THEN2 (LABEL_TAC "z_not_u")
      (LABEL_TAC "z_not_v"))) THENL
     [MP_TAC(ISPECL
       [`W:A->bool`; `D:(A->bool)->bool`; `v:A`; `z:A`]
       FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "vertices" MP_TAC THEN
      REWRITE_TAC[SUBSET; IN_DELETE] THEN
      DISCH_THEN(MP_TAC o SPEC `z:A`) THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `IMAGE (swap(u:A,v)) {v,z} = {u,z}`
    SUBST1_TAC THENL
     [ASM_SIMP_TAC[IMAGE_CLAUSES; SWAP_RIGHT; SWAP_OTHER];
      ALL_TAC] THEN
    ASM_CASES_TAC
     `(z:A) IN contract_split_side E D v` THENL
     [REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN DISJ1_TAC THEN
      CONJ_TAC THENL
       [USE_THEN "u_edge" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        ASM SET_TAC[]];
      REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN DISJ2_TAC THEN
      EXISTS_TAC `z:A` THEN
      ASM_REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
      USE_THEN "v_edge" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]];
    SUBGOAL_THEN
     `IMAGE (swap(u:A,v)) d = d`
    (LABEL_TAC "fixed_edge") THENL
     [MATCH_MP_TAC IMAGE_SWAP_FIX_SET THEN ASM_REWRITE_TAC[];
      USE_THEN "fixed_edge" SUBST1_TAC THEN
      REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN DISJ1_TAC THEN
      CONJ_TAC THENL
       [USE_THEN "away_edge" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        USE_THEN "edge_subset" MP_TAC THEN
        USE_THEN "vertices" MP_TAC THEN ASM SET_TAC[]]]]);;

let CONTRACT_SPLIT_SIDE_SWAP_SUBSET_COMPLEMENT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !W:A->bool. !D:(A->bool)->bool.
        finite_simple_graph W D /\
        ~(u = v) /\
        ~(u IN W) /\
        D SUBSET graph_contract_edges V E u v
        ==> contract_split_side E
             (IMAGE (IMAGE (swap(u,v))) D) u
            SUBSET
            graph_neighbors D v DIFF contract_split_side E D v`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph distinct fresh subset" THEN
  SUBGOAL_THEN
   `graph_neighbors
      (IMAGE (IMAGE (swap(u:A,v))) D) u =
    graph_neighbors D v`
  (LABEL_TAC "neighbors") THENL
   [MATCH_MP_TAC(ISPECL
     [`W:A->bool`; `D:(A->bool)->bool`; `u:A`; `v:A`]
     GRAPH_NEIGHBORS_SWAP_FRESH) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
    `D:(A->bool)->bool`]
   GRAPH_CONTRACT_SUBGRAPH_SPLIT_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "_ u_edge _" THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `z:A` THEN
  REWRITE_TAC[IN_CONTRACT_SPLIT_SIDE; IN_DIFF] THEN
  INTRO_TAC "new_neighbor missing_u_edge" THEN
  CONJ_TAC THENL
   [USE_THEN "neighbors" (fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(LABEL_TAC "old_side_data") THEN
    SUBGOAL_THEN
     `(z:A) IN contract_split_side E D v`
    (LABEL_TAC "old_side") THENL
     [REWRITE_TAC[IN_CONTRACT_SPLIT_SIDE] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "u_edge" (MP_TAC o SPEC `z:A`) THEN
    ASM_MESON_TAC[]]);;

let GRAPH_CONTRACT_SUBDIVISION_LIFT_COMPLEMENT_ONE_SWAP = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !W:A->bool. !D:(A->bool)->bool.
   !W':A->bool. !D':(A->bool)->bool. !w:A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        graph_subdivision W D W' D' /\
        W' SUBSET V DELETE u /\
        D' SUBSET graph_contract_edges V E u v /\
        graph_neighbors D' v DIFF contract_split_side E D' v = {w}
        ==> ?W'':A->bool. ?D'':(A->bool)->bool.
              graph_subdivision
                (IMAGE (swap(u,v)) W)
                (IMAGE (IMAGE (swap(u,v))) D) W'' D'' /\
