    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (swap(u,v)) (W':A->bool) SUBSET V DELETE v`
  (LABEL_TAC "swapped_vertices") THENL
   [REWRITE_TAC[SUBSET; IN_IMAGE] THEN
    X_GEN_TAC `x:A` THEN INTRO_TAC "@y. image old_vertex" THEN
    USE_THEN "image" SUBST1_TAC THEN
    SUBGOAL_THEN `(y:A) IN V /\ ~(y = u)`
    (CONJUNCTS_THEN2 (LABEL_TAC "y_vertex") (LABEL_TAC "y_not_u"))
    THENL
     [USE_THEN "vertices" MP_TAC THEN
      REWRITE_TAC[SUBSET; IN_DELETE] THEN
      DISCH_THEN(MP_TAC o SPEC `y:A`) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[IN_DELETE] THEN
    ASM_CASES_TAC `(y:A) = v` THENL
     [ASM_REWRITE_TAC[SWAP_RIGHT];
      ASM_SIMP_TAC[SWAP_OTHER]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (IMAGE (swap(u,v))) (D':(A->bool)->bool)
    SUBSET graph_contract_edges V E v u`
  (LABEL_TAC "swapped_edges") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
      `W':A->bool`; `D':(A->bool)->bool`]
     GRAPH_CONTRACT_SUBGRAPH_SWAP_EDGES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `contract_split_side E
      (IMAGE (IMAGE (swap(u,v))) (D':(A->bool)->bool)) u
    SUBSET {w}`
  (LABEL_TAC "swapped_side_subset") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
      `W':A->bool`; `D':(A->bool)->bool`]
     CONTRACT_SPLIT_SIDE_SWAP_SUBSET_COMPLEMENT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{v:A,u} IN E` (LABEL_TAC "reverse_edge") THENL
   [SUBGOAL_THEN `{v:A,u} = {u,v}` SUBST1_TAC THENL
     [SET_TAC[];
      USE_THEN "contracted_edge" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `contract_split_side E
      (IMAGE (IMAGE (swap(u,v))) (D':(A->bool)->bool)) u = {} \/
    contract_split_side E
      (IMAGE (IMAGE (swap(u,v))) D') u = {w}`
  (DISJ_CASES_THEN2 (LABEL_TAC "swapped_empty")
   (LABEL_TAC "swapped_singleton")) THENL
   [USE_THEN "swapped_side_subset" MP_TAC THEN SET_TAC[];
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `u:A`;
      `IMAGE (swap(u,v)) (W:A->bool)`;
      `IMAGE (IMAGE (swap(u,v))) (D:(A->bool)->bool)`;
      `IMAGE (swap(u,v)) (W':A->bool)`;
      `IMAGE (IMAGE (swap(u,v))) (D':(A->bool)->bool)`]
     GRAPH_CONTRACT_SUBDIVISION_LIFT_EMPTY) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `u:A`;
      `IMAGE (swap(u,v)) (W:A->bool)`;
      `IMAGE (IMAGE (swap(u,v))) (D:(A->bool)->bool)`;
      `IMAGE (swap(u,v)) (W':A->bool)`;
      `IMAGE (IMAGE (swap(u,v))) (D':(A->bool)->bool)`;
      `w:A`]
     GRAPH_CONTRACT_SUBDIVISION_LIFT_ONE) THEN
    ASM_REWRITE_TAC[]]);;

let FINITE_CARD_ONE_SINGLETON = prove
 (`!S:A->bool.
        FINITE S /\ CARD S = 1
        ==> ?w. S = {w}`,
  REWRITE_TAC[GSYM HAS_SIZE;
              HAS_SIZE_CONV `(S:A->bool) HAS_SIZE 1`]);;

let FINITE_SMALL_SUBSET_SPLIT = prove
 (`!N S:A->bool.
        FINITE N /\
        S SUBSET N /\
        CARD N <= 3
        ==> S = {} \/
            (?w. S = {w}) \/
            S = N \/
            (?w. N DIFF S = {w})`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite subset small" THEN
  SUBGOAL_THEN `FINITE(S:A->bool)` (LABEL_TAC "finite_side") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `N:A->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE((N:A->bool) DIFF S)`
  (LABEL_TAC "finite_complement") THENL
   [MATCH_MP_TAC FINITE_DIFF THEN
    USE_THEN "finite" ACCEPT_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `(S:A->bool) = {}` THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(N:A->bool) DIFF S = {}` THENL
   [DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
    USE_THEN "subset" MP_TAC THEN ASM SET_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `CARD(S:A->bool) = 1` THENL
   [DISJ2_TAC THEN DISJ1_TAC THEN
    MATCH_MP_TAC FINITE_CARD_ONE_SINGLETON THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `CARD((N:A->bool) DIFF S) = 1` THENL
   [DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
    MATCH_MP_TAC FINITE_CARD_ONE_SINGLETON THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(CARD(S:A->bool) = 0)`
  (LABEL_TAC "side_nonzero") THENL
   [ASM_MESON_TAC[CARD_EQ_0];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(CARD((N:A->bool) DIFF S) = 0)`
  (LABEL_TAC "complement_nonzero") THENL
   [ASM_MESON_TAC[CARD_EQ_0];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`N:A->bool`; `S:A->bool`] CARD_DIFF) THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let FINITE_CARD_FOUR_SUBSET_SPLIT = prove
 (`!N S:A->bool.
        FINITE N /\
        S SUBSET N /\
        CARD N = 4
        ==> S = {} \/
            (?w. S = {w}) \/
            S = N \/
            (?w. N DIFF S = {w}) \/
            CARD S = 2`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite subset card" THEN
  SUBGOAL_THEN `FINITE(S:A->bool)` (LABEL_TAC "finite_side") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `N:A->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE((N:A->bool) DIFF S)`
  (LABEL_TAC "finite_complement") THENL
   [MATCH_MP_TAC FINITE_DIFF THEN
    USE_THEN "finite" ACCEPT_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `(S:A->bool) = {}` THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(N:A->bool) DIFF S = {}` THENL
   [DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
    USE_THEN "subset" MP_TAC THEN ASM SET_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `CARD(S:A->bool) = 1` THENL
   [DISJ2_TAC THEN DISJ1_TAC THEN
    MATCH_MP_TAC FINITE_CARD_ONE_SINGLETON THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `CARD((N:A->bool) DIFF S) = 1` THENL
   [DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
    MATCH_MP_TAC FINITE_CARD_ONE_SINGLETON THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
  SUBGOAL_THEN `~(CARD(S:A->bool) = 0)`
  (LABEL_TAC "side_nonzero") THENL
   [ASM_MESON_TAC[CARD_EQ_0];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(CARD((N:A->bool) DIFF S) = 0)`
  (LABEL_TAC "complement_nonzero") THENL
   [ASM_MESON_TAC[CARD_EQ_0];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`N:A->bool`; `S:A->bool`] CARD_DIFF) THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let GRAPH_CONTRACT_SUBDIVISION_LIFT_SMALL_DEGREE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !W:A->bool. !D:(A->bool)->bool.
   !W':A->bool. !D':(A->bool)->bool.
        finite_simple_graph V E /\
        {u,v} IN E /\
        graph_subdivision W D W' D' /\
        W' SUBSET V DELETE u /\
        D' SUBSET graph_contract_edges V E u v /\
        CARD(graph_neighbors D' v) <= 3
        ==> (?W'':A->bool. ?D'':(A->bool)->bool.
              graph_subdivision W D W'' D'' /\
              W'' SUBSET V /\
              D'' SUBSET induced_subgraph_edges E W'') \/
            (?W'':A->bool. ?D'':(A->bool)->bool.
              graph_subdivision
                (IMAGE (swap(u,v)) W)
                (IMAGE (IMAGE (swap(u,v))) D) W'' D'' /\
              W'' SUBSET V /\
              D'' SUBSET induced_subgraph_edges E W'')`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "ambient_graph contracted_edge subdivision vertices edges small" THEN
  SUBGOAL_THEN `finite_simple_graph (W':A->bool) D'`
  (LABEL_TAC "target_graph") THENL
   [MP_TAC(MATCH_MP
     (ISPECL
      [`W:A->bool`; `D:(A->bool)->bool`;
       `W':A->bool`; `D':(A->bool)->bool`]
      GRAPH_SUBDIVISION_FINITE_SIMPLE)
     (ASSUME
      `graph_subdivision
        (W:A->bool) (D:(A->bool)->bool)
        (W':A->bool) (D':(A->bool)->bool)`)) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(graph_neighbors (D':(A->bool)->bool) v)`
  (LABEL_TAC "finite_neighbors") THENL
   [MATCH_MP_TAC FINITE_GRAPH_NEIGHBORS THEN
    EXISTS_TAC `W':A->bool` THEN
    USE_THEN "target_graph" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`graph_neighbors (D':(A->bool)->bool) v`;
    `contract_split_side (E:(A->bool)->bool) D' v`]
   FINITE_SMALL_SUBSET_SPLIT) THEN
  ASM_REWRITE_TAC[CONTRACT_SPLIT_SIDE_SUBSET_NEIGHBORS] THEN
  DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "empty")
   (DISJ_CASES_THEN2
    (X_CHOOSE_THEN `w:A` (LABEL_TAC "singleton"))
    (DISJ_CASES_THEN2 (LABEL_TAC "full")
     (X_CHOOSE_THEN `w:A` (LABEL_TAC "complement"))))) THENL
   [DISJ1_TAC THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
      `W:A->bool`; `D:(A->bool)->bool`;
      `W':A->bool`; `D':(A->bool)->bool`]
     GRAPH_CONTRACT_SUBDIVISION_LIFT_EMPTY) THEN
    ASM_REWRITE_TAC[];
    DISJ1_TAC THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
      `W:A->bool`; `D:(A->bool)->bool`;
      `W':A->bool`; `D':(A->bool)->bool`; `w:A`]
     GRAPH_CONTRACT_SUBDIVISION_LIFT_ONE) THEN
    ASM_REWRITE_TAC[];
    DISJ2_TAC THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
      `W:A->bool`; `D:(A->bool)->bool`;
      `W':A->bool`; `D':(A->bool)->bool`]
     GRAPH_CONTRACT_SUBDIVISION_LIFT_FULL_SWAP) THEN
    ASM_REWRITE_TAC[];
    DISJ2_TAC THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
      `W:A->bool`; `D:(A->bool)->bool`;
      `W':A->bool`; `D':(A->bool)->bool`; `w:A`]
     GRAPH_CONTRACT_SUBDIVISION_LIFT_COMPLEMENT_ONE_SWAP) THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Splitting a branch vertex through a graph subdivision.                    *)
(* ------------------------------------------------------------------------- *)

let graph_branch_split_edges = new_definition
 `graph_branch_split_edges
    (E:(A->bool)->bool) u v (S:A->bool) =
      {{u,v}} UNION
      IMAGE (\w:A. {u,w}) S UNION
      (E DIFF IMAGE (\w:A. {v,w}) S)`;;

let IN_GRAPH_BRANCH_SPLIT_EDGES = prove
 (`!E:(A->bool)->bool. !u v:A. !S e.
        e IN graph_branch_split_edges E u v S <=>
        e = {u,v} \/
        (?w. w IN S /\ e = {u,w}) \/
        e IN E /\ ~(?w. w IN S /\ e = {v,w})`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_branch_split_edges; IN_UNION; IN_SING;
              IN_IMAGE; IN_DIFF] THEN
  MESON_TAC[]);;

let FINITE_SIMPLE_GRAPH_BRANCH_SPLIT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A. !S:A->bool.
        finite_simple_graph V E /\
        v IN V /\
        ~(u IN V) /\
        S SUBSET graph_neighbors E v
        ==> finite_simple_graph
             (u INSERT V) (graph_branch_split_edges E u v S)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph v_vertex fresh side" THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite_vertices") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(E:(A->bool)->bool)` (LABEL_TAC "finite_edges") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(graph_neighbors (E:(A->bool)->bool) v)`
  (LABEL_TAC "finite_neighbors") THENL
   [MATCH_MP_TAC FINITE_GRAPH_NEIGHBORS THEN
    EXISTS_TAC `V:A->bool` THEN USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(S:A->bool)` (LABEL_TAC "finite_side") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `graph_neighbors (E:(A->bool)->bool) v` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[finite_simple_graph] THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[FINITE_INSERT];
    REWRITE_TAC[graph_branch_split_edges] THEN
    ASM_REWRITE_TAC[FINITE_UNION; FINITE_INSERT; FINITE_EMPTY;
                    FINITE_IMAGE; FINITE_DIFF] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_IMAGE THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC FINITE_DIFF THEN ASM_REWRITE_TAC[]];
    X_GEN_TAC `e:A->bool` THEN
    REWRITE_TAC[IN_GRAPH_BRANCH_SPLIT_EDGES] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "bridge")
     (DISJ_CASES_THEN2
      (X_CHOOSE_THEN `w:A`
       (CONJUNCTS_THEN2 (LABEL_TAC "w_side") (LABEL_TAC "moved")))
      (LABEL_TAC "old"))) THENL
     [USE_THEN "bridge" SUBST1_TAC THEN
      CONJ_TAC THENL
       [ASM SET_TAC[];
        REWRITE_TAC[PAIR_HAS_SIZE_2] THEN ASM_MESON_TAC[]];
      USE_THEN "moved" SUBST1_TAC THEN
      SUBGOAL_THEN `(w:A) IN V /\ ~(w = v)`
      (CONJUNCTS_THEN2 (LABEL_TAC "w_vertex") (LABEL_TAC "w_not_v"))
      THENL
       [SUBGOAL_THEN `(w:A) IN graph_neighbors E v`
        (LABEL_TAC "w_neighbor") THENL
         [USE_THEN "side" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          USE_THEN "w_side" ACCEPT_TAC;
          MP_TAC(ISPECL
           [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `w:A`]
           FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
          ASM_REWRITE_TAC[] THEN MESON_TAC[]];
        CONJ_TAC THENL
         [ASM SET_TAC[];
          REWRITE_TAC[PAIR_HAS_SIZE_2] THEN ASM_MESON_TAC[]]];
      SUBGOAL_THEN `(e:A->bool) SUBSET V /\ e HAS_SIZE 2`
      (CONJUNCTS_THEN2 (LABEL_TAC "edge_subset") (LABEL_TAC "edge_size"))
      THENL
       [USE_THEN "graph" MP_TAC THEN
        REWRITE_TAC[finite_simple_graph] THEN
        INTRO_TAC "_ _ edge_data" THEN
        USE_THEN "edge_data" MATCH_MP_TAC THEN
        ACCEPT_TAC(CONJUNCT1
         (ASSUME
          `(e:A->bool) IN E /\
           ~(?w:A. w IN S /\ e = {v,w})`));
        CONJ_TAC THENL
         [USE_THEN "edge_subset" MP_TAC THEN SET_TAC[];
          USE_THEN "edge_size" ACCEPT_TAC]]]]);;

let PAIR_NOT_IN_EDGE_STAR_IMAGE = prove
 (`!S:A->bool. !v a b.
        ~(v = a) /\ ~(v = b)
        ==> ~({a,b} IN IMAGE (\s:A. {v,s}) S)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_IMAGE] THEN SET_TAC[]);;

let EDGE_STAR_IMAGE_MEM = prove
 (`!S:A->bool. !v w.
        {v,w} IN IMAGE (\s:A. {v,s}) S <=> w IN S`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
  MESON_TAC[PAIR_SET_EQ_LEFT]);;

let IMAGE_EDGE_STAR_DELETE = prove
 (`!S:A->bool. !v w.
        IMAGE (\s:A. {v,s}) (S DELETE w) =
        IMAGE (\s:A. {v,s}) S DELETE {v,w}`,
  REPEAT GEN_TAC THEN MATCH_MP_TAC IMAGE_DELETE_INJ THEN
  X_GEN_TAC `x:A` THEN
  REWRITE_TAC[PAIR_SET_EQ_LEFT] THEN MESON_TAC[]);;

let TWO_ELEMENT_SET_DISJOINT = prove
 (`!R:A->bool. !a b.
        ~(a IN R) /\ ~(b IN R)
        ==> DISJOINT {a,b} R`,
  SET_TAC[]);;

let PAIR_EDGE_NE = prove
 (`!u v a b:A.
        ~(u = a) /\ ~(u = b)
        ==> ~({a,b} = {u,v})`,
  SET_TAC[]);;

let TWO_EDGE_PATH_REVERSE = prove
 (`!a b w:A. {{a,w},{w,b}} = {{b,w},{w,a}}`,
  REPEAT GEN_TAC THEN
  SUBGOAL_THEN `{a:A,w} = {w,a}` (LABEL_TAC "first") THENL
   [MATCH_ACCEPT_TAC(SPECL [`a:A`; `w:A`] PAIR_SET_SYM);
    ALL_TAC] THEN
  SUBGOAL_THEN `{w:A,b} = {b,w}` (LABEL_TAC "second") THENL
   [MATCH_ACCEPT_TAC(SPECL [`w:A`; `b:A`] PAIR_SET_SYM);
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_ACCEPT_TAC(ISPECL
   [`{w:A,a}:A->bool`; `{b:A,w}:A->bool`]
   PAIR_SET_SYM));;

let BRANCH_SPLIT_SUBDIVIDE_SET = prove
 (`!B M N E R:A->bool. !e:A.
        DISJOINT N R /\
        ~(e IN R) /\
        ~(e IN B) /\
        ~(e IN M)
        ==> B UNION M UNION ((N UNION (E DELETE e)) DIFF R) =
            N UNION ((B UNION M UNION (E DIFF R)) DELETE e)`,
  REPEAT GEN_TAC THEN INTRO_TAC "disjoint er eb em" THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `x:A` THEN
  REWRITE_TAC[IN_UNION; IN_DIFF; IN_DELETE] THEN
  ASM_CASES_TAC `(x:A) = e` THENL
   [ASM_REWRITE_TAC[];
    ASM_CASES_TAC `(x:A) IN N` THENL
     [SUBGOAL_THEN `~((x:A) IN R)` (LABEL_TAC "not_R") THENL
       [USE_THEN "disjoint" MP_TAC THEN
        REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
        DISCH_THEN(MP_TAC o SPEC `x:A`) THEN ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[]];
      ASM_REWRITE_TAC[]]]);;

let GRAPH_BRANCH_SPLIT_EDGES_SUBDIVIDE_AWAY = prove
 (`!E:(A->bool)->bool. !u v a b w:A. !S:A->bool.
        ~(u = v) /\
        ~(u = a) /\ ~(u = b) /\ ~(u = w) /\
        ~(v = a) /\ ~(v = b) /\ ~(v = w) /\
        ~(a = b) /\ ~(a = w) /\ ~(b = w) /\
        ~(w IN S)
        ==> graph_branch_split_edges
             ({{a,w},{w,b}} UNION (E DELETE {a,b})) u v S =
            {{a,w},{w,b}} UNION
            (graph_branch_split_edges E u v S DELETE {a,b})`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "uv ua ub uw va vb vw ab aw bw w_fresh" THEN
  SUBGOAL_THEN
   `~({a:A,w} IN IMAGE (\s:A. {v,s}) S) /\
    ~({w:A,b} IN IMAGE (\s:A. {v,s}) S) /\
    ~({a:A,b} IN IMAGE (\s:A. {v,s}) S) /\
    ~({a:A,b} IN IMAGE (\s:A. {u,s}) S)`
  MP_TAC THENL
   [REPEAT CONJ_TAC THEN
    MATCH_MP_TAC PAIR_NOT_IN_EDGE_STAR_IMAGE THEN
    ASM_REWRITE_TAC[];
    INTRO_TAC "n_aw n_wb n_ab_v n_ab_u" THEN
    REWRITE_TAC[graph_branch_split_edges] THEN
    MATCH_MP_TAC BRANCH_SPLIT_SUBDIVIDE_SET THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC TWO_ELEMENT_SET_DISJOINT THEN ASM_REWRITE_TAC[];
      USE_THEN "n_ab_v" ACCEPT_TAC;
      REWRITE_TAC[IN_SING] THEN
      MATCH_MP_TAC PAIR_EDGE_NE THEN ASM_REWRITE_TAC[];
      USE_THEN "n_ab_u" ACCEPT_TAC]]);;

let FOUR_VERTEX_SPLIT_EDGES_DISTINCT = prove
 (`!u v b w:A.
        ~(u = v) /\ ~(u = b) /\ ~(u = w) /\
        ~(v = b) /\ ~(v = w) /\ ~(b = w)
        ==> ~({u,b} = {u,w}) /\
            ~({u,b} = {v,b}) /\
            ~({u,b} = {v,w}) /\
            ~({u,b} = {w,b}) /\
            ~({u,w} = {v,b}) /\
            ~({u,w} = {v,w}) /\
            ~({u,w} = {w,b}) /\
            ~({v,b} = {v,w}) /\
            ~({v,b} = {w,b}) /\
            ~({v,w} = {w,b})`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN ASM SET_TAC[]);;

let BRANCH_SPLIT_SUBDIVIDE_SELECTED_SET = prove
 (`!B M R E:A->bool. !p q r s t:A.
        ~(p = q) /\ ~(p = r) /\ ~(p = s) /\ ~(p = t) /\
        ~(q = r) /\ ~(q = s) /\ ~(q = t) /\
        ~(r = s) /\ ~(r = t) /\ ~(s = t) /\
        s IN R /\ ~(t IN R) /\ ~(r IN R) /\ ~(p IN R) /\
        q IN M /\ ~(p IN M) /\ ~(p IN B) /\
        ~(p IN E) /\ ~(s IN E)
        ==> B UNION M UNION (({s,t} UNION (E DELETE r)) DIFF R) =
            {q,t} UNION
            ((B UNION
              (p INSERT (M DELETE q)) UNION
              (E DIFF (r INSERT (R DELETE s)))) DELETE p)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "pq pr ps pt qr qs qt rs rt st sr tr rr pR qm pm pb pe se" THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `x:A` THEN
  REWRITE_TAC[IN_UNION; IN_DIFF; IN_DELETE; IN_INSERT; IN_SING] THEN
  ASM_CASES_TAC `(x:A) = p` THENL
   [ASM_REWRITE_TAC[];
    ASM_CASES_TAC `(x:A) = q` THENL
     [ASM_REWRITE_TAC[];
      ASM_CASES_TAC `(x:A) = r` THENL
       [ASM_REWRITE_TAC[];
        ASM_CASES_TAC `(x:A) = s` THENL
         [ASM_REWRITE_TAC[];
          ASM_CASES_TAC `(x:A) = t` THEN ASM_REWRITE_TAC[]]]]]);;

let GRAPH_BRANCH_SPLIT_EDGES_SUBDIVIDE_INCIDENT_SELECTED = prove
 (`!E:(A->bool)->bool. !u v b w:A. !S:A->bool.
        ~(u = v) /\ ~(u = b) /\ ~(u = w) /\
        ~(v = b) /\ ~(v = w) /\ ~(b = w) /\
        w IN S /\ ~(b IN S) /\
        ~({u,b} IN E) /\ ~({v,w} IN E)
        ==> graph_branch_split_edges
             ({{v,w},{w,b}} UNION (E DELETE {v,b})) u v S =
            {{u,w},{w,b}} UNION
            (graph_branch_split_edges
              E u v (b INSERT (S DELETE w)) DELETE {u,b})`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "uv ub uw vb vw bw w_side b_not_side ub_not_edge vw_not_edge" THEN
  SUBGOAL_THEN
   `~({w:A,b} IN IMAGE (\s:A. {v,s}) S)`
  (LABEL_TAC "wb_not_removed") THENL
   [MATCH_MP_TAC PAIR_NOT_IN_EDGE_STAR_IMAGE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~({u:A,b} IN IMAGE (\s:A. {v,s}) S)`
  (LABEL_TAC "ub_not_removed") THENL
   [MATCH_MP_TAC PAIR_NOT_IN_EDGE_STAR_IMAGE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`u:A`; `v:A`; `b:A`; `w:A`]
    FOUR_VERTEX_SPLIT_EDGES_DISTINCT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "pq pr ps pt qr qs qt rs rt st" THEN
  REWRITE_TAC[graph_branch_split_edges; IMAGE_CLAUSES;
              IMAGE_EDGE_STAR_DELETE] THEN
  MATCH_MP_TAC BRANCH_SPLIT_SUBDIVIDE_SELECTED_SET THEN
  ASM_REWRITE_TAC[EDGE_STAR_IMAGE_MEM; IN_SING; PAIR_SET_EQ_LEFT]);;

let GRAPH_BRANCH_SPLIT_EDGES_SUBDIVIDE_INCIDENT_UNSELECTED = prove
 (`!E:(A->bool)->bool. !u v b w:A. !S:A->bool.
        ~(u = v) /\ ~(u = b) /\ ~(u = w) /\
        ~(v = b) /\ ~(v = w) /\ ~(b = w) /\
        ~(w IN S) /\ ~(b IN S)
        ==> graph_branch_split_edges
             ({{v,w},{w,b}} UNION (E DELETE {v,b})) u v S =
            {{v,w},{w,b}} UNION
            (graph_branch_split_edges E u v S DELETE {v,b})`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "uv ub uw vb vw bw w_not_side b_not_side" THEN
  SUBGOAL_THEN
   `~({v:A,w} IN IMAGE (\s:A. {v,s}) S)`
  (LABEL_TAC "vw_not_removed") THENL
   [ASM_REWRITE_TAC[EDGE_STAR_IMAGE_MEM];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~({w:A,b} IN IMAGE (\s:A. {v,s}) S)`
  (LABEL_TAC "wb_not_removed") THENL
   [MATCH_MP_TAC PAIR_NOT_IN_EDGE_STAR_IMAGE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~({v:A,b} IN IMAGE (\s:A. {u,s}) S)`
  (LABEL_TAC "vb_not_moved") THENL
   [MATCH_MP_TAC PAIR_NOT_IN_EDGE_STAR_IMAGE THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[graph_branch_split_edges] THEN
  MATCH_MP_TAC BRANCH_SPLIT_SUBDIVIDE_SET THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC TWO_ELEMENT_SET_DISJOINT THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[EDGE_STAR_IMAGE_MEM];
    REWRITE_TAC[IN_SING] THEN
    MATCH_MP_TAC PAIR_EDGE_NE THEN ASM_REWRITE_TAC[];
    USE_THEN "vb_not_moved" ACCEPT_TAC]);;

let CARD_REPLACE_ONE = prove
 (`!S:A->bool. !w b.
        FINITE S /\ w IN S /\ ~(b IN S)
        ==> CARD(b INSERT (S DELETE w)) = CARD S`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite w_member b_fresh" THEN
  SUBGOAL_THEN `~((S:A->bool) = {})` (LABEL_TAC "nonempty") THENL
   [USE_THEN "w_member" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `0 < CARD(S:A->bool)` (LABEL_TAC "positive") THENL
   [MP_TAC(MATCH_MP
     (ISPEC `S:A->bool` CARD_EQ_0)
     (ASSUME `FINITE(S:A->bool)`)) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ASM_SIMP_TAC[CARD_CLAUSES; FINITE_DELETE; IN_DELETE; CARD_DELETE] THEN
    ASM_ARITH_TAC]);;

let FINITE_SIMPLE_GRAPH_FRESH_EDGE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !w x:A.
        finite_simple_graph V E /\ ~(w IN V)
        ==> ~({w,x} IN E)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph fresh" THEN
  DISCH_THEN(LABEL_TAC "edge") THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `w:A`; `x:A`]
   FINITE_SIMPLE_GRAPH_DART) THEN
  ASM_REWRITE_TAC[IN_GRAPH_DARTS]);;

let GRAPH_EDGE_SUBDIVISION_BRANCH_SPLIT_INCIDENT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v b w:A. !S':A->bool.
        finite_simple_graph V E /\
        {v,b} IN E /\
        ~(w IN V) /\
        ~(u IN w INSERT V) /\
        S' SUBSET
          graph_neighbors
           ({{v,w},{w,b}} UNION (E DELETE {v,b})) v
        ==> ?S:A->bool.
              S SUBSET graph_neighbors E v /\
              CARD S = CARD S' /\
              graph_edge_subdivision
               (u INSERT V) (graph_branch_split_edges E u v S)
               (u INSERT (w INSERT V))
               (graph_branch_split_edges
                 ({{v,w},{w,b}} UNION (E DELETE {v,b})) u v S')`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph edge fresh_w fresh_u side" THEN
  SUBGOAL_THEN
   `(v:A) IN V /\ (b:A) IN V /\ ~(v = b)`
  (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "b_vertex") (LABEL_TAC "vb")))
  THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `b:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(u:A = v) /\ ~(u = b) /\ ~(u = w) /\
    ~(v = w) /\ ~(b = w)`
  (CONJUNCTS_THEN2 (LABEL_TAC "uv")
   (CONJUNCTS_THEN2 (LABEL_TAC "ub")
    (CONJUNCTS_THEN2 (LABEL_TAC "uw")
     (CONJUNCTS_THEN2 (LABEL_TAC "vw")
      (LABEL_TAC "bw"))))) THENL
   [USE_THEN "fresh_u" MP_TAC THEN
    USE_THEN "fresh_w" MP_TAC THEN ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_edge_subdivision
      (V:A->bool) E (w INSERT V)
      ({{v,w},{w,b}} UNION (E DELETE {v,b}))`
  (LABEL_TAC "edge_step") THENL
   [REWRITE_TAC[graph_edge_subdivision] THEN
    MAP_EVERY EXISTS_TAC [`v:A`; `b:A`; `w:A`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph
      (w INSERT V:A->bool)
      ({{v,w},{w,b}} UNION (E DELETE {v,b}))`
  (LABEL_TAC "target_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_EDGE_SUBDIVISION THEN
    MAP_EVERY EXISTS_TAC
     [`V:A->bool`; `E:(A->bool)->bool`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_neighbors
      ({{v:A,w},{w:A,b}} UNION
       ((E:(A->bool)->bool) DELETE {v:A,b})) v =
    w INSERT (graph_neighbors E v DELETE b)`
  (LABEL_TAC "neighbors") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `w INSERT V:A->bool`;
      `{{v:A,w},{w:A,b}} UNION
       (E DELETE {v:A,b}):(A->bool)->bool`;
      `v:A`; `b:A`; `w:A`; `v:A`]
     GRAPH_EDGE_SUBDIVISION_OLD_VERTEX_NEIGHBORS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(S':A->bool)` (LABEL_TAC "finite_side") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC
     `graph_neighbors
       ({{v:A,w},{w:A,b}} UNION (E DELETE {v:A,b})) v` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_GRAPH_NEIGHBORS THEN
      EXISTS_TAC `w INSERT V:A->bool` THEN
      USE_THEN "target_graph" ACCEPT_TAC;
      USE_THEN "side" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((b:A) IN S')` (LABEL_TAC "b_not_side") THENL
   [DISCH_THEN(LABEL_TAC "b_side") THEN
    SUBGOAL_THEN
     `(b:A) IN
      graph_neighbors
       ({{v,w},{w,b}} UNION (E DELETE {v,b})) v`
    (LABEL_TAC "b_neighbor") THENL
     [USE_THEN "side" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "b_side" ACCEPT_TAC;
      USE_THEN "neighbors" MP_TAC THEN
      USE_THEN "b_neighbor" MP_TAC THEN
      ASM SET_TAC[]];
    ALL_TAC] THEN
  ASM_CASES_TAC `(w:A) IN S'` THENL
   [EXISTS_TAC `b INSERT (S' DELETE w):A->bool` THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[SUBSET; IN_INSERT; IN_DELETE] THEN
      X_GEN_TAC `x:A` THEN
      DISCH_THEN(DISJ_CASES_THEN2 SUBST1_TAC
       (LABEL_TAC "old_side")) THENL
       [REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
        USE_THEN "edge" ACCEPT_TAC;
        SUBGOAL_THEN
         `(x:A) IN
          graph_neighbors
           ({{v,w},{w,b}} UNION (E DELETE {v,b})) v`
        (LABEL_TAC "new_neighbor") THENL
         [USE_THEN "side" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          ACCEPT_TAC(CONJUNCT1
           (ASSUME `(x:A) IN S' /\ ~(x = w)`));
          USE_THEN "neighbors" (fun th ->
           USE_THEN "new_neighbor" (MP_TAC o REWRITE_RULE[th])) THEN
          REWRITE_TAC[IN_INSERT; IN_DELETE] THEN
          ASM_REWRITE_TAC[] THEN
          DISCH_THEN(ACCEPT_TAC o CONJUNCT1)]];
      MATCH_MP_TAC CARD_REPLACE_ONE THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[graph_edge_subdivision] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `b:A`; `w:A`] THEN
      REPEAT CONJ_TAC THENL
       [REWRITE_TAC[IN_GRAPH_BRANCH_SPLIT_EDGES] THEN
        DISJ2_TAC THEN DISJ1_TAC THEN
        EXISTS_TAC `b:A` THEN REWRITE_TAC[IN_INSERT];
        REWRITE_TAC[IN_INSERT; DE_MORGAN_THM] THEN
        CONJ_TAC THENL
         [DISCH_THEN(LABEL_TAC "wu") THEN
          USE_THEN "uw" (MATCH_MP_TAC o NOT_ELIM) THEN
          USE_THEN "wu" (ACCEPT_TAC o SYM);
          USE_THEN "fresh_w" ACCEPT_TAC];
        MATCH_ACCEPT_TAC(SET_RULE
         `(u:A) INSERT (w INSERT V) = w INSERT (u INSERT V)`);
        MATCH_MP_TAC
         GRAPH_BRANCH_SPLIT_EDGES_SUBDIVIDE_INCIDENT_SELECTED THEN
        ASM_REWRITE_TAC[] THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC(ISPECL
           [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `b:A`]
           FINITE_SIMPLE_GRAPH_FRESH_EDGE) THEN
          ASM_REWRITE_TAC[] THEN
          DISCH_THEN(LABEL_TAC "u_vertex") THEN
          USE_THEN "fresh_u" (MATCH_MP_TAC o NOT_ELIM) THEN
          REWRITE_TAC[IN_INSERT] THEN
          DISJ2_TAC THEN USE_THEN "u_vertex" ACCEPT_TAC;
          SUBGOAL_THEN `{v:A,w} = {w,v}` SUBST1_TAC THENL
           [MATCH_ACCEPT_TAC(SET_RULE `{v:A,w} = {w,v}`);
            MATCH_MP_TAC(ISPECL
             [`V:A->bool`; `E:(A->bool)->bool`; `w:A`; `v:A`]
             FINITE_SIMPLE_GRAPH_FRESH_EDGE) THEN
            ASM_REWRITE_TAC[]]]]];
    EXISTS_TAC `S':A->bool` THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[SUBSET] THEN X_GEN_TAC `x:A` THEN
      DISCH_THEN(LABEL_TAC "old_side") THEN
      SUBGOAL_THEN
       `(x:A) IN
        graph_neighbors
         ({{v,w},{w,b}} UNION (E DELETE {v,b})) v`
      (LABEL_TAC "new_neighbor") THENL
       [USE_THEN "side" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "old_side" ACCEPT_TAC;
        SUBGOAL_THEN `~(x:A = w)` (LABEL_TAC "x_not_w") THENL
         [DISCH_THEN SUBST_ALL_TAC THEN
          FIRST_X_ASSUM(MATCH_MP_TAC o NOT_ELIM) THEN
          USE_THEN "old_side" ACCEPT_TAC;
          USE_THEN "neighbors" (fun th ->
           USE_THEN "new_neighbor" (MP_TAC o REWRITE_RULE[th])) THEN
          ASM_REWRITE_TAC[IN_INSERT; IN_DELETE] THEN
          DISCH_THEN(ACCEPT_TAC o CONJUNCT1)]];
      REFL_TAC;
      REWRITE_TAC[graph_edge_subdivision] THEN
      MAP_EVERY EXISTS_TAC [`v:A`; `b:A`; `w:A`] THEN
      REPEAT CONJ_TAC THENL
       [REWRITE_TAC[graph_branch_split_edges; IN_UNION; IN_DIFF] THEN
       DISJ2_TAC THEN DISJ2_TAC THEN
        ASM_REWRITE_TAC[EDGE_STAR_IMAGE_MEM];
        REWRITE_TAC[IN_INSERT; DE_MORGAN_THM] THEN
        CONJ_TAC THENL
         [DISCH_THEN(LABEL_TAC "wu") THEN
          USE_THEN "uw" (MATCH_MP_TAC o NOT_ELIM) THEN
          USE_THEN "wu" (ACCEPT_TAC o SYM);
          USE_THEN "fresh_w" ACCEPT_TAC];
        MATCH_ACCEPT_TAC(SET_RULE
         `(u:A) INSERT (w INSERT V) = w INSERT (u INSERT V)`);
        MATCH_MP_TAC
         GRAPH_BRANCH_SPLIT_EDGES_SUBDIVIDE_INCIDENT_UNSELECTED THEN
        ASM_REWRITE_TAC[]]]]);;

let GRAPH_EDGE_SUBDIVISION_BRANCH_SPLIT = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !V':A->bool. !E':(A->bool)->bool.
   !u v:A. !S':A->bool.
        finite_simple_graph V E /\
        graph_edge_subdivision V E V' E' /\
        v IN V /\
        ~(u IN V') /\
        S' SUBSET graph_neighbors E' v
        ==> ?S:A->bool.
              S SUBSET graph_neighbors E v /\
              CARD S = CARD S' /\
              graph_edge_subdivision
               (u INSERT V) (graph_branch_split_edges E u v S)
               (u INSERT V') (graph_branch_split_edges E' u v S')`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph subdivision v_vertex u_fresh side" THEN
  USE_THEN "subdivision"
   (MP_TAC o REWRITE_RULE[graph_edge_subdivision]) THEN
  INTRO_TAC "@a b w. edge w_fresh vertices edges" THEN
  USE_THEN "vertices" SUBST_ALL_TAC THEN
  USE_THEN "edges" SUBST_ALL_TAC THEN
  SUBGOAL_THEN
   `(a:A) IN V /\ (b:A) IN V /\ ~(a = b)`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "b_vertex") (LABEL_TAC "ab")))
  THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `a:A`; `b:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((u:A) IN V) /\ ~(u = w) /\ ~(v = w)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_old_fresh")
   (CONJUNCTS_THEN2 (LABEL_TAC "uw") (LABEL_TAC "vw"))) THENL
   [REPEAT CONJ_TAC THENL
     [DISCH_THEN(LABEL_TAC "u_vertex") THEN
      USE_THEN "u_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      REWRITE_TAC[IN_INSERT] THEN
      DISJ2_TAC THEN USE_THEN "u_vertex" ACCEPT_TAC;
      DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "u_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      REWRITE_TAC[IN_INSERT] THEN
      DISJ1_TAC THEN USE_THEN "same" ACCEPT_TAC;
      DISCH_THEN SUBST_ALL_TAC THEN
      USE_THEN "w_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "v_vertex" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(a:A = w) /\ ~(b:A = w)`
  (CONJUNCTS_THEN2 (LABEL_TAC "aw") (LABEL_TAC "bw")) THENL
   [CONJ_TAC THENL
     [DISCH_THEN SUBST_ALL_TAC THEN
      USE_THEN "w_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "a_vertex" ACCEPT_TAC;
      DISCH_THEN SUBST_ALL_TAC THEN
      USE_THEN "w_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "b_vertex" ACCEPT_TAC];
    ALL_TAC] THEN
  ASM_CASES_TAC `(v:A) = a` THENL
   [UNDISCH_TAC `(v:A) = a` THEN DISCH_THEN SUBST_ALL_TAC THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `u:A`; `a:A`; `b:A`; `w:A`; `S':A->bool`]
     GRAPH_EDGE_SUBDIVISION_BRANCH_SPLIT_INCIDENT) THEN
    ASM_REWRITE_TAC[];
    ASM_CASES_TAC `(v:A) = b` THENL
     [UNDISCH_TAC `(v:A) = b` THEN DISCH_THEN SUBST_ALL_TAC THEN
      SUBGOAL_THEN `{a:A,b} = {b,a}` (LABEL_TAC "reverse_edge") THENL
       [MATCH_ACCEPT_TAC(SPECL [`a:A`; `b:A`] PAIR_SET_SYM);
        ALL_TAC] THEN
      SUBGOAL_THEN `{b:A,a} IN E` (LABEL_TAC "reverse_edge_member") THENL
       [SUBGOAL_THEN `{b:A,a} = {a,b}` SUBST1_TAC THENL
         [MATCH_ACCEPT_TAC(SPECL [`b:A`; `a:A`] PAIR_SET_SYM);
          USE_THEN "edge" ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `{{a:A,w},{w,b}} = {{b,w},{w,a}}`
      (LABEL_TAC "reverse_step") THENL
       [MATCH_ACCEPT_TAC(SPECL [`a:A`; `b:A`; `w:A`]
         TWO_EDGE_PATH_REVERSE);
        ALL_TAC] THEN
      SUBGOAL_THEN
       `S' SUBSET
        graph_neighbors
         ({{b:A,w},{w:A,a}} UNION
          ((E:(A->bool)->bool) DELETE {b:A,a})) b`
      (LABEL_TAC "reverse_side") THENL
       [USE_THEN "reverse_step" (fun sth ->
         USE_THEN "reverse_edge" (fun eth ->
          REWRITE_TAC[GSYM sth; GSYM eth])) THEN
        USE_THEN "side" ACCEPT_TAC;
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `u:A`; `b:A`; `a:A`; `w:A`; `S':A->bool`]
       GRAPH_EDGE_SUBDIVISION_BRANCH_SPLIT_INCIDENT) THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN
       `graph_neighbors
         ({{a:A,w},{w:A,b}} UNION
          ((E:(A->bool)->bool) DELETE {a:A,b})) v =
        graph_neighbors E v`
      (LABEL_TAC "neighbors") THENL
       [MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
          `w INSERT V:A->bool`;
          `{{a:A,w},{w:A,b}} UNION
           (E DELETE {a:A,b}):(A->bool)->bool`;
          `a:A`; `b:A`; `w:A`; `v:A`]
         GRAPH_EDGE_SUBDIVISION_OLD_VERTEX_NEIGHBORS) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `S' SUBSET graph_neighbors (E:(A->bool)->bool) v`
      (LABEL_TAC "old_side") THENL
       [USE_THEN "neighbors" (fun th -> REWRITE_TAC[GSYM th]) THEN
        USE_THEN "side" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `~((w:A) IN S')` (LABEL_TAC "w_not_side") THENL
       [DISCH_THEN(LABEL_TAC "w_side") THEN
        SUBGOAL_THEN `(w:A) IN graph_neighbors E v`
        (LABEL_TAC "w_neighbor") THENL
         [USE_THEN "old_side" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          USE_THEN "w_side" ACCEPT_TAC;
          SUBGOAL_THEN `{v:A,w} = {w,v}` (LABEL_TAC "reverse_vw") THENL
           [MATCH_ACCEPT_TAC(SET_RULE `{v:A,w} = {w,v}`);
            USE_THEN "w_neighbor" MP_TAC THEN
            REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
            USE_THEN "reverse_vw" (fun th -> REWRITE_TAC[th]) THEN
            MATCH_MP_TAC(ISPECL
             [`V:A->bool`; `E:(A->bool)->bool`; `w:A`; `v:A`]
             FINITE_SIMPLE_GRAPH_FRESH_EDGE) THEN
            ASM_REWRITE_TAC[]]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `~(u:A = v) /\ ~(u = a) /\ ~(u = b)`
      (CONJUNCTS_THEN2 (LABEL_TAC "uv")
       (CONJUNCTS_THEN2 (LABEL_TAC "ua") (LABEL_TAC "ub"))) THENL
       [USE_THEN "u_old_fresh" MP_TAC THEN
        ASM SET_TAC[];
        ALL_TAC] THEN
      EXISTS_TAC `S':A->bool` THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "old_side" ACCEPT_TAC;
        REFL_TAC;
        REWRITE_TAC[graph_edge_subdivision] THEN
        MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `w:A`] THEN
        REPEAT CONJ_TAC THENL
         [REWRITE_TAC[graph_branch_split_edges;
                      IN_UNION; IN_DIFF] THEN
          DISJ2_TAC THEN DISJ2_TAC THEN
          CONJ_TAC THENL
           [USE_THEN "edge" ACCEPT_TAC;
            MATCH_MP_TAC PAIR_NOT_IN_EDGE_STAR_IMAGE THEN
            ASM_REWRITE_TAC[]];
          REWRITE_TAC[IN_INSERT; DE_MORGAN_THM] THEN
          CONJ_TAC THENL
           [DISCH_THEN(LABEL_TAC "wu") THEN
            USE_THEN "uw" (MATCH_MP_TAC o NOT_ELIM) THEN
            USE_THEN "wu" (ACCEPT_TAC o SYM);
            USE_THEN "w_fresh" ACCEPT_TAC];
          MATCH_ACCEPT_TAC(SET_RULE
           `(u:A) INSERT (w INSERT V) = w INSERT (u INSERT V)`);
          MATCH_MP_TAC GRAPH_BRANCH_SPLIT_EDGES_SUBDIVIDE_AWAY THEN
          ASM_REWRITE_TAC[]]]]]);;

let GRAPH_SUBDIVISION_BRANCH_SPLIT = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !V':A->bool. !E':(A->bool)->bool.
        graph_subdivision V E V' E'
        ==> !u v:A. !S':A->bool.
              v IN V /\
              ~(u IN V') /\
              S' SUBSET graph_neighbors E' v
              ==> ?S:A->bool.
                    S SUBSET graph_neighbors E v /\
                    CARD S = CARD S' /\
                    graph_subdivision
                     (u INSERT V)
                     (graph_branch_split_edges E u v S)
                     (u INSERT V')
                     (graph_branch_split_edges E' u v S')`,
  SUBGOAL_THEN
   `!W:A->bool. !D:(A->bool)->bool.
    !W':A->bool. !D':(A->bool)->bool.
        graph_subdivision W D W' D'
        ==> finite_simple_graph W' D' /\
            W SUBSET W' /\
            (!u v:A. !S':A->bool.
                v IN W /\
                ~(u IN W') /\
                S' SUBSET graph_neighbors D' v
                ==> ?S:A->bool.
                      S SUBSET graph_neighbors D v /\
                      CARD S = CARD S' /\
                      graph_subdivision
                       (u INSERT W)
                       (graph_branch_split_edges D u v S)
                       (u INSERT W')
                       (graph_branch_split_edges D' u v S'))`
  (LABEL_TAC "lifting") THENL
   [MATCH_MP_TAC graph_subdivision_INDUCT THEN
    CONJ_TAC THENL
     [REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "graph" ACCEPT_TAC;
        REWRITE_TAC[SUBSET_REFL];
        REPEAT GEN_TAC THEN
        INTRO_TAC "v_vertex u_fresh side" THEN
        EXISTS_TAC `S':A->bool` THEN
        ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC(CONJUNCT1 graph_subdivision_RULES) THEN
        MATCH_MP_TAC FINITE_SIMPLE_GRAPH_BRANCH_SPLIT THEN
        ASM_REWRITE_TAC[]];
      REPEAT GEN_TAC THEN
      INTRO_TAC
       "(intermediate_graph source_subset induction) edge_step" THEN
      SUBGOAL_THEN `finite_simple_graph (V'':A->bool) E''`
      (LABEL_TAC "target_graph") THENL
       [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_EDGE_SUBDIVISION THEN
        MAP_EVERY EXISTS_TAC
         [`V':A->bool`; `E':(A->bool)->bool`] THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(V':A->bool) SUBSET V''`
      (LABEL_TAC "step_subset") THENL
       [MATCH_MP_TAC(ISPECL
         [`V':A->bool`; `E':(A->bool)->bool`;
          `V'':A->bool`; `E'':(A->bool)->bool`]
         GRAPH_EDGE_SUBDIVISION_SOURCE_SUBSET) THEN
        USE_THEN "edge_step" ACCEPT_TAC;
        ALL_TAC] THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "target_graph" ACCEPT_TAC;
        MATCH_MP_TAC SUBSET_TRANS THEN
        EXISTS_TAC `V':A->bool` THEN ASM_REWRITE_TAC[];
        REPEAT GEN_TAC THEN
        INTRO_TAC "v_source u_fresh side" THEN
        SUBGOAL_THEN `(v:A) IN V'` (LABEL_TAC "v_intermediate") THENL
         [USE_THEN "source_subset"
           (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          USE_THEN "v_source" ACCEPT_TAC;
          ALL_TAC] THEN
        SUBGOAL_THEN `~((u:A) IN V')` (LABEL_TAC "u_intermediate_fresh")
        THENL
         [USE_THEN "step_subset" MP_TAC THEN
          USE_THEN "u_fresh" MP_TAC THEN SET_TAC[];
          ALL_TAC] THEN
        MP_TAC(ISPECL
         [`V':A->bool`; `E':(A->bool)->bool`;
          `V'':A->bool`; `E'':(A->bool)->bool`;
          `u:A`; `v:A`; `S':A->bool`]
         GRAPH_EDGE_SUBDIVISION_BRANCH_SPLIT) THEN
        ASM_REWRITE_TAC[] THEN
        INTRO_TAC "@t. intermediate_side step_card split_step" THEN
        USE_THEN "induction" (MP_TAC o SPECL
         [`u:A`; `v:A`; `t:A->bool`]) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[];
          INTRO_TAC "@S. source_side induction_card subdivision" THEN
          EXISTS_TAC `S:A->bool` THEN
          ASM_REWRITE_TAC[] THEN
          MATCH_MP_TAC(CONJUNCT2 graph_subdivision_RULES) THEN
          MAP_EVERY EXISTS_TAC
           [`u INSERT V':A->bool`;
            `graph_branch_split_edges
              (E':(A->bool)->bool) u v t`] THEN
          ASM_REWRITE_TAC[]]]];
    REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "subdivision") THEN
    USE_THEN "lifting" (fun th ->
     MP_TAC(MATCH_MP
      (SPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `V':A->bool`; `E':(A->bool)->bool`] th)
      (ASSUME `graph_subdivision
                (V:A->bool) (E:(A->bool)->bool)
                (V':A->bool) (E':(A->bool)->bool)`))) THEN
    INTRO_TAC "_ _ result" THEN
    USE_THEN "result" ACCEPT_TAC]);;

let COMPLETE_GRAPH_BRANCH_SPLIT_BIPARTITE_EDGES = prove
 (`!W:A->bool. !u v:A. !S:A->bool.
        v IN W /\
        ~(u IN W) /\
        S SUBSET W DELETE v
        ==> complete_bipartite_edges
             (u INSERT ((W DELETE v) DIFF S)) (v INSERT S)
            SUBSET
            graph_branch_split_edges
             (complete_graph_edges W) u v S`,
  REPEAT GEN_TAC THEN INTRO_TAC "v_vertex u_fresh side" THEN
  REWRITE_TAC[SUBSET; IN_COMPLETE_BIPARTITE_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN
  INTRO_TAC "@x y. x_left y_right edge_value" THEN
  USE_THEN "edge_value" SUBST1_TAC THEN
  ASM_CASES_TAC `(x:A) = u` THENL
   [UNDISCH_TAC `(x:A) = u` THEN DISCH_THEN SUBST_ALL_TAC THEN
    ASM_CASES_TAC `(y:A) = v` THENL
     [UNDISCH_TAC `(y:A) = v` THEN DISCH_THEN SUBST_ALL_TAC THEN
      REWRITE_TAC[IN_GRAPH_BRANCH_SPLIT_EDGES];
      SUBGOAL_THEN `(y:A) IN S` (LABEL_TAC "y_side") THENL
       [USE_THEN "y_right" MP_TAC THEN
        REWRITE_TAC[IN_INSERT] THEN
        DISCH_THEN(DISJ_CASES_THEN2
         (LABEL_TAC "y_is_v") ACCEPT_TAC) THEN
        UNDISCH_TAC `~((y:A) = v)` THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[IN_GRAPH_BRANCH_SPLIT_EDGES] THEN
        DISJ2_TAC THEN DISJ1_TAC THEN
        EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[]]];
    SUBGOAL_THEN
     `(x:A) IN W /\ ~(x = v) /\ ~(x IN S)`
    (CONJUNCTS_THEN2 (LABEL_TAC "x_vertex")
     (CONJUNCTS_THEN2 (LABEL_TAC "x_not_v")
     (LABEL_TAC "x_not_side"))) THENL
     [USE_THEN "x_left" MP_TAC THEN
      REWRITE_TAC[IN_INSERT; IN_DIFF; IN_DELETE] THEN
      DISCH_THEN(DISJ_CASES_THEN2
       (LABEL_TAC "x_is_u") (LABEL_TAC "x_complement")) THENL
       [UNDISCH_TAC `~((x:A) = u)` THEN ASM_REWRITE_TAC[];
        USE_THEN "x_complement" MP_TAC THEN MESON_TAC[]];
      ALL_TAC] THEN
    ASM_CASES_TAC `(y:A) = v` THENL
     [UNDISCH_TAC `(y:A) = v` THEN DISCH_THEN SUBST_ALL_TAC THEN
      REWRITE_TAC[IN_GRAPH_BRANCH_SPLIT_EDGES] THEN
      DISJ2_TAC THEN DISJ2_TAC THEN CONJ_TAC THENL
       [REWRITE_TAC[IN_COMPLETE_GRAPH_EDGES; PAIR_HAS_SIZE_2] THEN
        ASM_REWRITE_TAC[INSERT_SUBSET; SING_SUBSET];
        REWRITE_TAC[PAIR_SET_EQ] THEN ASM_MESON_TAC[]];
      SUBGOAL_THEN `(y:A) IN S` (LABEL_TAC "y_side") THENL
       [USE_THEN "y_right" MP_TAC THEN
        REWRITE_TAC[IN_INSERT] THEN
        DISCH_THEN(DISJ_CASES_THEN2
         (LABEL_TAC "y_is_v") ACCEPT_TAC) THEN
        UNDISCH_TAC `~((y:A) = v)` THEN ASM_REWRITE_TAC[];
        SUBGOAL_THEN `(y:A) IN W /\ ~(y = v)`
        (CONJUNCTS_THEN2 (LABEL_TAC "y_vertex")
         (LABEL_TAC "y_not_v")) THENL
         [USE_THEN "side" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
          DISCH_THEN(MP_TAC o SPEC `y:A`) THEN
          ASM_REWRITE_TAC[IN_DELETE];
          REWRITE_TAC[IN_GRAPH_BRANCH_SPLIT_EDGES] THEN
          DISJ2_TAC THEN DISJ2_TAC THEN CONJ_TAC THENL
           [REWRITE_TAC[IN_COMPLETE_GRAPH_EDGES; PAIR_HAS_SIZE_2] THEN
            ASM_REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
            ASM_MESON_TAC[];
            REWRITE_TAC[PAIR_SET_EQ] THEN ASM_MESON_TAC[]]]]]]);;

let COMPLETE_GRAPH_5_BRANCH_SPLIT_K33 = prove
 (`!W:A->bool. !u v:A. !S:A->bool.
        W HAS_SIZE 5 /\
        v IN W /\
        ~(u IN W) /\
        S SUBSET graph_neighbors (complete_graph_edges W) v /\
        CARD S = 2
        ==> (u INSERT ((W DELETE v) DIFF S)) HAS_SIZE 3 /\
            (v INSERT S) HAS_SIZE 3 /\
            DISJOINT
             (u INSERT ((W DELETE v) DIFF S)) (v INSERT S) /\
            (u INSERT ((W DELETE v) DIFF S)) UNION (v INSERT S) =
            u INSERT W /\
            complete_bipartite_edges
             (u INSERT ((W DELETE v) DIFF S)) (v INSERT S)
            SUBSET
            induced_subgraph_edges
             (graph_branch_split_edges
               (complete_graph_edges W) u v S)
             ((u INSERT ((W DELETE v) DIFF S)) UNION (v INSERT S))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "size v_vertex u_fresh side side_card" THEN
  SUBGOAL_THEN
   `graph_neighbors (complete_graph_edges (W:A->bool)) v =
    W DELETE v`
  (LABEL_TAC "neighbors") THENL
   [ASM_REWRITE_TAC[GRAPH_NEIGHBORS_COMPLETE_GRAPH];
    ALL_TAC] THEN
  SUBGOAL_THEN `(S:A->bool) SUBSET W DELETE v`
  (LABEL_TAC "side_vertices") THENL
   [USE_THEN "neighbors" (fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "side" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(W:A->bool) /\ CARD W = 5`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_W") (LABEL_TAC "W_card")) THENL
   [USE_THEN "size" MP_TAC THEN REWRITE_TAC[HAS_SIZE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(W DELETE (v:A)) /\ CARD(W DELETE v) = 4`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_neighbors")
   (LABEL_TAC "neighbor_card")) THENL
   [CONJ_TAC THENL
     [ASM_REWRITE_TAC[FINITE_DELETE];
      ASM_SIMP_TAC[CARD_DELETE] THEN ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(S:A->bool)` (LABEL_TAC "finite_side") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `W DELETE (v:A)` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE((W DELETE (v:A)) DIFF S) /\
    CARD((W DELETE v) DIFF S) = 2`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_complement")
   (LABEL_TAC "complement_card")) THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_DIFF THEN ASM_REWRITE_TAC[];
      MP_TAC(ISPECL [`W DELETE (v:A)`; `S:A->bool`] CARD_DIFF) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((u:A) IN (W DELETE v) DIFF S) /\ ~(v IN S)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_not_complement")
   (LABEL_TAC "v_not_side")) THENL
   [USE_THEN "u_fresh" MP_TAC THEN
    USE_THEN "side_vertices" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[HAS_SIZE] THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[FINITE_INSERT];
      ASM_SIMP_TAC[CARD_CLAUSES] THEN ARITH_TAC];
    REWRITE_TAC[HAS_SIZE] THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[FINITE_INSERT];
      ASM_SIMP_TAC[CARD_CLAUSES] THEN ARITH_TAC];
    MATCH_MP_TAC(SET_RULE
     `~(u:A = v) /\
      ~(u IN S) /\
      ~(v IN R) /\
      DISJOINT R S
      ==> DISJOINT (u INSERT R) (v INSERT S)`) THEN
    REPEAT CONJ_TAC THENL
     [DISCH_THEN SUBST_ALL_TAC THEN
      USE_THEN "u_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "v_vertex" ACCEPT_TAC;
      DISCH_THEN(LABEL_TAC "u_side") THEN
      USE_THEN "u_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
      SUBGOAL_THEN `(u:A) IN W DELETE v` MP_TAC THENL
       [USE_THEN "side_vertices"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "u_side" ACCEPT_TAC;
        REWRITE_TAC[IN_DELETE] THEN MESON_TAC[]];
      REWRITE_TAC[IN_DIFF; IN_DELETE];
      MATCH_ACCEPT_TAC(SET_RULE
       `DISJOINT ((W DELETE (v:A)) DIFF S) S`)];
    MATCH_MP_TAC(SET_RULE
     `v IN W /\ S SUBSET W DELETE v
      ==> (u INSERT ((W DELETE v) DIFF S)) UNION (v INSERT S) =
          u INSERT W`) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`W:A->bool`; `u:A`; `v:A`; `S:A->bool`]
       COMPLETE_GRAPH_BRANCH_SPLIT_BIPARTITE_EDGES) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "edge" ACCEPT_TAC;
      USE_THEN "edge" MP_TAC THEN
      REWRITE_TAC[IN_COMPLETE_BIPARTITE_EDGES] THEN
      INTRO_TAC "@x y. x_left y_right edge_value" THEN
      USE_THEN "edge_value" SUBST1_TAC THEN
      X_GEN_TAC `z:A` THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN
      DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THENL
       [REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
        USE_THEN "x_left" ACCEPT_TAC;
        REWRITE_TAC[IN_UNION] THEN DISJ2_TAC THEN
        USE_THEN "y_right" ACCEPT_TAC]]]);;

let GRAPH_CONTRACT_SUBGRAPH_BRANCH_SPLIT_EDGES = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !W:A->bool. !D:(A->bool)->bool.
        finite_simple_graph W D /\
        {u,v} IN E /\
        D SUBSET graph_contract_edges V E u v
        ==> graph_branch_split_edges
             D u v (contract_split_side E D v)
            SUBSET E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph contracted_edge subset" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
    `D:(A->bool)->bool`]
   GRAPH_CONTRACT_SUBGRAPH_SPLIT_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "away_edge u_edge v_edge" THEN
  REWRITE_TAC[SUBSET; IN_GRAPH_BRANCH_SPLIT_EDGES] THEN
  X_GEN_TAC `d:A->bool` THEN
  DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "bridge")
   (DISJ_CASES_THEN2
    (X_CHOOSE_THEN `w:A`
     (CONJUNCTS_THEN2 (LABEL_TAC "w_side") (LABEL_TAC "moved")))
    (LABEL_TAC "old"))) THENL
   [USE_THEN "bridge" SUBST1_TAC THEN
    USE_THEN "contracted_edge" ACCEPT_TAC;
    USE_THEN "moved" SUBST1_TAC THEN
    USE_THEN "u_edge" MATCH_MP_TAC THEN
    USE_THEN "w_side" ACCEPT_TAC;
    ASM_CASES_TAC `(v:A) IN d` THENL
     [MP_TAC(ISPECL
       [`W:A->bool`; `D:(A->bool)->bool`; `d:A->bool`; `v:A`]
       FINITE_SIMPLE_GRAPH_INCIDENT_EDGE) THEN
      ASM_REWRITE_TAC[] THEN
      INTRO_TAC "@w. w_neighbor edge_value" THEN
      USE_THEN "edge_value" SUBST_ALL_TAC THEN
      SUBGOAL_THEN
       `~((w:A) IN contract_split_side E D v)`
      (LABEL_TAC "w_not_side") THENL
       [DISCH_THEN(LABEL_TAC "w_side") THEN
        USE_THEN "old" (MP_TAC o CONJUNCT2) THEN
        DISCH_THEN(MATCH_MP_TAC o NOT_ELIM) THEN
        EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[];
        USE_THEN "v_edge" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[]];
      USE_THEN "away_edge" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]]]);;

let GRAPH_CONTRACT_COMPLETE_GRAPH_5_SUBDIVISION_LIFT_K33 = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !W:A->bool. !W':A->bool. !D':(A->bool)->bool.
        finite_simple_graph V E /\
        {u,v} IN E /\
        W HAS_SIZE 5 /\
        graph_subdivision W (complete_graph_edges W) W' D' /\
        W' SUBSET V DELETE u /\
        D' SUBSET graph_contract_edges V E u v /\
        v IN W /\
        CARD(contract_split_side E D' v) = 2
        ==> ?X Y:A->bool.
            ?P:A->bool. ?f:(A->bool)->bool.
              X HAS_SIZE 3 /\
              Y HAS_SIZE 3 /\
              DISJOINT X Y /\
              graph_subdivision
               (X UNION Y) (complete_bipartite_edges X Y) P f /\
              P SUBSET V /\
              f SUBSET induced_subgraph_edges E P`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "ambient_graph contracted_edge size subdivision vertices edges
    v_source split_card" THEN
  SUBGOAL_THEN `finite_simple_graph (W':A->bool) D'`
  (LABEL_TAC "target_graph") THENL
   [MP_TAC(MATCH_MP
     (ISPECL
      [`W:A->bool`; `complete_graph_edges (W:A->bool)`;
       `W':A->bool`; `D':(A->bool)->bool`]
      GRAPH_SUBDIVISION_FINITE_SIMPLE)
     (ASSUME
      `graph_subdivision
        (W:A->bool) (complete_graph_edges W)
        (W':A->bool) (D':(A->bool)->bool)`)) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(W:A->bool) SUBSET W'` (LABEL_TAC "source_subset") THENL
   [MATCH_MP_TAC(ISPECL
     [`W:A->bool`; `complete_graph_edges (W:A->bool)`;
      `W':A->bool`; `D':(A->bool)->bool`]
     GRAPH_SUBDIVISION_SOURCE_SUBSET) THEN
    USE_THEN "subdivision" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(u:A) IN V` (LABEL_TAC "u_vertex") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) IN W')` (LABEL_TAC "u_target_fresh") THENL
   [USE_THEN "vertices" MP_TAC THEN
    REWRITE_TAC[SUBSET; IN_DELETE] THEN
    DISCH_THEN(MP_TAC o SPEC `u:A`) THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) IN W)` (LABEL_TAC "u_source_fresh") THENL
   [DISCH_THEN(LABEL_TAC "u_source") THEN
    USE_THEN "u_target_fresh" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "source_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "u_source" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL
   [`u:A`; `v:A`; `contract_split_side E D' v:A->bool`]
   (MATCH_MP
    (ISPECL
     [`W:A->bool`; `complete_graph_edges (W:A->bool)`;
      `W':A->bool`; `D':(A->bool)->bool`]
     GRAPH_SUBDIVISION_BRANCH_SPLIT)
    (ASSUME
     `graph_subdivision
       (W:A->bool) (complete_graph_edges W)
       (W':A->bool) (D':(A->bool)->bool)`))) THEN
  ASM_REWRITE_TAC[CONTRACT_SPLIT_SIDE_SUBSET_NEIGHBORS] THEN
  INTRO_TAC "@S. source_side side_card split_subdivision" THEN
  MP_TAC(ISPECL
   [`W:A->bool`; `u:A`; `v:A`; `S:A->bool`]
   COMPLETE_GRAPH_5_BRANCH_SPLIT_K33) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    INTRO_TAC "left_size right_size disjoint cover bipartite_edges"] THEN
  SUBGOAL_THEN
   `finite_simple_graph
      ((u INSERT ((W DELETE v) DIFF S)) UNION (v INSERT S):A->bool)
      (complete_bipartite_edges
        (u INSERT ((W DELETE v) DIFF S)) (v INSERT S))`
  (LABEL_TAC "bipartite_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_COMPLETE_BIPARTITE_GRAPH THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "left_size" MP_TAC THEN REWRITE_TAC[HAS_SIZE] THEN MESON_TAC[];
      USE_THEN "right_size" MP_TAC THEN REWRITE_TAC[HAS_SIZE] THEN MESON_TAC[];
      USE_THEN "disjoint" ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL
   [`(u INSERT ((W DELETE v) DIFF S)) UNION (v INSERT S):A->bool`;
    `complete_bipartite_edges
      (u INSERT ((W DELETE v) DIFF S)) (v INSERT S)
      :(A->bool)->bool`]
   (MATCH_MP
    (ISPECL
     [`u INSERT W:A->bool`;
      `graph_branch_split_edges
        (complete_graph_edges (W:A->bool)) u v S`;
      `u INSERT W':A->bool`;
      `graph_branch_split_edges (D':(A->bool)->bool)
        u v (contract_split_side E D' v)`]
     GRAPH_SUBDIVISION_SUBGRAPH)
    (ASSUME
     `graph_subdivision
       (u INSERT W:A->bool)
       (graph_branch_split_edges
         (complete_graph_edges W) u v S)
       (u INSERT W':A->bool)
     (graph_branch_split_edges D' u v
         (contract_split_side E D' v))`))) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "bipartite_graph" ACCEPT_TAC;
      USE_THEN "cover" (fun th -> REWRITE_TAC[th; SUBSET_REFL]);
      USE_THEN "bipartite_edges" ACCEPT_TAC];
    INTRO_TAC "@P f. restricted_subdivision retained_vertices retained_edges"]
  THEN
  SUBGOAL_THEN
   `graph_branch_split_edges (D':(A->bool)->bool)
      u v (contract_split_side E D' v)
    SUBSET E`
  (LABEL_TAC "split_edges") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
      `W':A->bool`; `D':(A->bool)->bool`]
     GRAPH_CONTRACT_SUBGRAPH_BRANCH_SPLIT_EDGES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(P:A->bool) SUBSET V` (LABEL_TAC "final_vertices") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `u INSERT W':A->bool` THEN
    CONJ_TAC THENL
     [USE_THEN "retained_vertices" ACCEPT_TAC;
      REWRITE_TAC[SUBSET; IN_INSERT] THEN
      X_GEN_TAC `x:A` THEN
      DISCH_THEN(DISJ_CASES_THEN2 SUBST1_TAC
       (LABEL_TAC "old_vertex")) THENL
       [USE_THEN "u_vertex" ACCEPT_TAC;
        SUBGOAL_THEN `(x:A) IN V DELETE u` MP_TAC THENL
         [USE_THEN "vertices" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          USE_THEN "old_vertex" ACCEPT_TAC;
          REWRITE_TAC[IN_DELETE] THEN MESON_TAC[]]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(f:(A->bool)->bool) SUBSET induced_subgraph_edges E P`
  (LABEL_TAC "final_edges") THENL
   [REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
    X_GEN_TAC `d:A->bool` THEN DISCH_THEN(LABEL_TAC "retained_edge") THEN
    SUBGOAL_THEN
     `(d:A->bool) IN induced_subgraph_edges
       (graph_branch_split_edges D' u v
         (contract_split_side E D' v)) P`
    (LABEL_TAC "split_edge") THENL
     [USE_THEN "retained_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "retained_edge" ACCEPT_TAC;
      USE_THEN "split_edge" MP_TAC THEN
      REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
      INTRO_TAC "old_edge edge_vertices" THEN CONJ_TAC THENL
       [USE_THEN "split_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "old_edge" ACCEPT_TAC;
        USE_THEN "edge_vertices"
         (ACCEPT_TAC o REWRITE_RULE[SUBSET])]];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`u INSERT ((W DELETE v) DIFF S):A->bool`;
    `v INSERT S:A->bool`; `P:A->bool`; `f:(A->bool)->bool`] THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Kuratowski subdivision obstructions and contraction lifting.              *)
(* ------------------------------------------------------------------------- *)

let graph_kuratowski_obstruction = new_definition
 `graph_kuratowski_obstruction
    (V:A->bool) (E:(A->bool)->bool) <=>
      (?W P:A->bool. ?f:(A->bool)->bool.
          W HAS_SIZE 5 /\
          graph_subdivision W (complete_graph_edges W) P f /\
          P SUBSET V /\
          f SUBSET induced_subgraph_edges E P) \/
      (?X Y P:A->bool. ?f:(A->bool)->bool.
          X HAS_SIZE 3 /\
          Y HAS_SIZE 3 /\
          DISJOINT X Y /\
          graph_subdivision
            (X UNION Y) (complete_bipartite_edges X Y) P f /\
          P SUBSET V /\
          f SUBSET induced_subgraph_edges E P)`;;

let GRAPH_KURATOWSKI_OBSTRUCTION_K5 = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !W P:A->bool. !f:(A->bool)->bool.
        W HAS_SIZE 5 /\
        graph_subdivision W (complete_graph_edges W) P f /\
        P SUBSET V /\
        f SUBSET induced_subgraph_edges E P
        ==> graph_kuratowski_obstruction V E`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_kuratowski_obstruction] THEN
  DISCH_THEN(LABEL_TAC "witness") THEN DISJ1_TAC THEN
  MAP_EVERY EXISTS_TAC
   [`W:A->bool`; `P:A->bool`; `f:(A->bool)->bool`] THEN
  USE_THEN "witness" ACCEPT_TAC);;

let GRAPH_KURATOWSKI_OBSTRUCTION_K33 = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !X Y P:A->bool. !f:(A->bool)->bool.
        X HAS_SIZE 3 /\
        Y HAS_SIZE 3 /\
        DISJOINT X Y /\
        graph_subdivision
          (X UNION Y) (complete_bipartite_edges X Y) P f /\
        P SUBSET V /\
        f SUBSET induced_subgraph_edges E P
        ==> graph_kuratowski_obstruction V E`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_kuratowski_obstruction] THEN
  DISCH_THEN(LABEL_TAC "witness") THEN DISJ2_TAC THEN
  MAP_EVERY EXISTS_TAC
   [`X:A->bool`; `Y:A->bool`; `P:A->bool`;
    `f:(A->bool)->bool`] THEN
  USE_THEN "witness" ACCEPT_TAC);;

let GRAPH_SUBDIVISION_EDGES_SUBSET_INDUCED = prove
 (`!W:A->bool. !D:(A->bool)->bool.
   !P:A->bool. !f:(A->bool)->bool. !E:(A->bool)->bool.
        graph_subdivision W D P f /\
        f SUBSET E
        ==> f SUBSET induced_subgraph_edges E P`,
  REPEAT GEN_TAC THEN INTRO_TAC "subdivision edges" THEN
  SUBGOAL_THEN `finite_simple_graph (P:A->bool) f`
  (LABEL_TAC "target_graph") THENL
   [USE_THEN "subdivision" (fun th ->
      ACCEPT_TAC(CONJUNCT2(MATCH_MP
       (ISPECL
        [`W:A->bool`; `D:(A->bool)->bool`;
         `P:A->bool`; `f:(A->bool)->bool`]
        GRAPH_SUBDIVISION_FINITE_SIMPLE) th)));
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
  CONJ_TAC THENL
   [USE_THEN "edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "edge" ACCEPT_TAC;
    USE_THEN "target_graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN
    INTRO_TAC "_ _ edge_data" THEN
    USE_THEN "edge_data" (fun th ->
     USE_THEN "edge" (fun eth ->
      MATCH_ACCEPT_TAC(REWRITE_RULE[SUBSET]
       (CONJUNCT1(MATCH_MP (SPEC `e:A->bool` th) eth)))))]);;

let GRAPH_KURATOWSKI_OBSTRUCTION_K5_SUBGRAPH = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !W P:A->bool. !f:(A->bool)->bool.
        W HAS_SIZE 5 /\
        graph_subdivision W (complete_graph_edges W) P f /\
        P SUBSET V /\
        f SUBSET E
        ==> graph_kuratowski_obstruction V E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "size subdivision vertices edges" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `W:A->bool`; `P:A->bool`; `f:(A->bool)->bool`]
   GRAPH_KURATOWSKI_OBSTRUCTION_K5) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC GRAPH_SUBDIVISION_EDGES_SUBSET_INDUCED THEN
  MAP_EVERY EXISTS_TAC
   [`W:A->bool`; `complete_graph_edges (W:A->bool)`] THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_KURATOWSKI_OBSTRUCTION_K33_SUBGRAPH = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !X Y P:A->bool. !f:(A->bool)->bool.
        X HAS_SIZE 3 /\
        Y HAS_SIZE 3 /\
        DISJOINT X Y /\
        graph_subdivision
          (X UNION Y) (complete_bipartite_edges X Y) P f /\
        P SUBSET V /\
        f SUBSET E
        ==> graph_kuratowski_obstruction V E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "X_size Y_size disjoint subdivision vertices edges" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `X:A->bool`; `Y:A->bool`; `P:A->bool`;
    `f:(A->bool)->bool`]
   GRAPH_KURATOWSKI_OBSTRUCTION_K33) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC GRAPH_SUBDIVISION_EDGES_SUBSET_INDUCED THEN
  MAP_EVERY EXISTS_TAC
   [`X UNION Y:A->bool`;
    `complete_bipartite_edges (X:A->bool) Y`] THEN
  ASM_REWRITE_TAC[]);;

let DISJOINT_IMAGE_INJECTIVE = prove
 (`!g:A->B. !X Y:A->bool.
        (!x y. g x = g y ==> x = y) /\
        DISJOINT X Y
        ==> DISJOINT (IMAGE g X) (IMAGE g Y)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective disjoint" THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; IN_IMAGE; NOT_IN_EMPTY] THEN
  X_GEN_TAC `z:B` THEN
  INTRO_TAC "(@x. x_image x_member) (@y. y_image y_member)" THEN
  SUBGOAL_THEN `(x:A) = y` SUBST_ALL_TAC THENL
   [USE_THEN "injective" MATCH_MP_TAC THEN
    TRANS_TAC EQ_TRANS `z:B` THEN
    CONJ_TAC THENL
     [USE_THEN "x_image" (ACCEPT_TAC o SYM);
      USE_THEN "y_image" ACCEPT_TAC];
    USE_THEN "disjoint" MP_TAC THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `y:A`) THEN ASM_REWRITE_TAC[]]);;

let GRAPH_KURATOWSKI_OBSTRUCTION_K5_SWAP = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !W P:A->bool. !f:(A->bool)->bool.
        W HAS_SIZE 5 /\
        graph_subdivision
          (IMAGE (swap(u,v)) W)
          (IMAGE (IMAGE (swap(u,v))) (complete_graph_edges W)) P f /\
        P SUBSET V /\
        f SUBSET induced_subgraph_edges E P
        ==> graph_kuratowski_obstruction V E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "size subdivision vertices edges" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `IMAGE (swap(u,v)) (W:A->bool)`; `P:A->bool`;
    `f:(A->bool)->bool`]
   GRAPH_KURATOWSKI_OBSTRUCTION_K5) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC HAS_SIZE_IMAGE_INJ THEN
    CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
      INTRO_TAC "_ _ same" THEN
      MATCH_MP_TAC(SPECL [`u:A`; `v:A`; `x:A`; `y:A`] SWAP_INJECTIVE) THEN
      USE_THEN "same" ACCEPT_TAC;
      USE_THEN "size" ACCEPT_TAC];
    SUBGOAL_THEN
     `IMAGE (IMAGE (swap(u:A,v))) (complete_graph_edges W) =
      complete_graph_edges (IMAGE (swap(u,v)) W)`
    (fun th -> REWRITE_TAC[GSYM th]) THENL
     [MATCH_MP_TAC IMAGE_COMPLETE_GRAPH_EDGES_INJECTIVE THEN
      MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
      MATCH_ACCEPT_TAC(SPECL
       [`u:A`; `v:A`; `x:A`; `y:A`] SWAP_INJECTIVE);
      USE_THEN "subdivision" ACCEPT_TAC];
    USE_THEN "vertices" ACCEPT_TAC;
    USE_THEN "edges" ACCEPT_TAC]);;

let GRAPH_KURATOWSKI_OBSTRUCTION_K33_SWAP = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
   !X Y P:A->bool. !f:(A->bool)->bool.
        X HAS_SIZE 3 /\
        Y HAS_SIZE 3 /\
        DISJOINT X Y /\
        graph_subdivision
          (IMAGE (swap(u,v)) (X UNION Y))
          (IMAGE (IMAGE (swap(u,v)))
            (complete_bipartite_edges X Y)) P f /\
        P SUBSET V /\
        f SUBSET induced_subgraph_edges E P
        ==> graph_kuratowski_obstruction V E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "X_size Y_size disjoint subdivision vertices edges" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `IMAGE (swap(u,v)) (X:A->bool)`;
    `IMAGE (swap(u,v)) (Y:A->bool)`;
    `P:A->bool`; `f:(A->bool)->bool`]
   GRAPH_KURATOWSKI_OBSTRUCTION_K33) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC HAS_SIZE_IMAGE_INJ THEN
    CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
      INTRO_TAC "_ _ same" THEN
      MATCH_MP_TAC(SPECL [`u:A`; `v:A`; `x:A`; `y:A`] SWAP_INJECTIVE) THEN
      USE_THEN "same" ACCEPT_TAC;
      USE_THEN "X_size" ACCEPT_TAC];
    MATCH_MP_TAC HAS_SIZE_IMAGE_INJ THEN
    CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
      INTRO_TAC "_ _ same" THEN
      MATCH_MP_TAC(SPECL [`u:A`; `v:A`; `x:A`; `y:A`] SWAP_INJECTIVE) THEN
      USE_THEN "same" ACCEPT_TAC;
      USE_THEN "Y_size" ACCEPT_TAC];
    MATCH_MP_TAC DISJOINT_IMAGE_INJECTIVE THEN
    CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
      MATCH_ACCEPT_TAC(SPECL
       [`u:A`; `v:A`; `x:A`; `y:A`] SWAP_INJECTIVE);
      USE_THEN "disjoint" ACCEPT_TAC];
    REWRITE_TAC[GSYM IMAGE_UNION; GSYM IMAGE_COMPLETE_BIPARTITE_EDGES] THEN
    USE_THEN "subdivision" ACCEPT_TAC;
    USE_THEN "vertices" ACCEPT_TAC;
    USE_THEN "edges" ACCEPT_TAC]);;

let GRAPH_KURATOWSKI_OBSTRUCTION_CONTRACT_IMP = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
        finite_simple_graph V E /\
        {u,v} IN E /\
        graph_kuratowski_obstruction
          (V DELETE u) (graph_contract_edges V E u v)
        ==> graph_kuratowski_obstruction V E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "ambient_graph contracted_edge obstruction" THEN
  USE_THEN "obstruction"
   (MP_TAC o REWRITE_RULE[graph_kuratowski_obstruction]) THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (X_CHOOSE_THEN `W:A->bool`
    (X_CHOOSE_THEN `P:A->bool`
     (X_CHOOSE_THEN `f:(A->bool)->bool`
      (CONJUNCTS_THEN2 (LABEL_TAC "size")
       (CONJUNCTS_THEN2 (LABEL_TAC "subdivision")
        (CONJUNCTS_THEN2 (LABEL_TAC "vertices")
         (LABEL_TAC "induced_edges")))))))
   (X_CHOOSE_THEN `X:A->bool`
    (X_CHOOSE_THEN `Y:A->bool`
     (X_CHOOSE_THEN `P:A->bool`
      (X_CHOOSE_THEN `f:(A->bool)->bool`
       (CONJUNCTS_THEN2 (LABEL_TAC "X_size")
        (CONJUNCTS_THEN2 (LABEL_TAC "Y_size")
         (CONJUNCTS_THEN2 (LABEL_TAC "disjoint")
           (CONJUNCTS_THEN2 (LABEL_TAC "subdivision")
            (CONJUNCTS_THEN2 (LABEL_TAC "vertices")
             (LABEL_TAC "induced_edges"))))))))))) THENL
   [SUBGOAL_THEN
     `(f:(A->bool)->bool) SUBSET graph_contract_edges V E u v`
    (LABEL_TAC "edges") THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC
       `induced_subgraph_edges
         (graph_contract_edges (V:A->bool) E u v) P` THEN
      ASM_REWRITE_TAC[INDUCED_SUBGRAPH_EDGES_SUBSET];
      ALL_TAC] THEN
    ASM_CASES_TAC `(v:A) IN W` THENL
     [SUBGOAL_THEN
       `finite_simple_graph (P:A->bool) f`
      (LABEL_TAC "target_graph") THENL
       [MP_TAC(MATCH_MP
         (ISPECL
          [`W:A->bool`; `complete_graph_edges (W:A->bool)`;
           `P:A->bool`; `f:(A->bool)->bool`]
          GRAPH_SUBDIVISION_FINITE_SIMPLE)
         (ASSUME
          `graph_subdivision
            (W:A->bool) (complete_graph_edges W)
            (P:A->bool) (f:(A->bool)->bool)`)) THEN
        MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `FINITE(graph_neighbors (f:(A->bool)->bool) v)`
      (LABEL_TAC "finite_neighbors") THENL
       [MATCH_MP_TAC FINITE_GRAPH_NEIGHBORS THEN
        EXISTS_TAC `P:A->bool` THEN
        USE_THEN "target_graph" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `CARD(graph_neighbors (f:(A->bool)->bool) v) = 4`
      (LABEL_TAC "degree") THENL
       [MATCH_MP_TAC(ISPECL
         [`W:A->bool`; `P:A->bool`; `f:(A->bool)->bool`; `v:A`]
         COMPLETE_GRAPH_5_SUBDIVISION_SOURCE_VERTEX_DEGREE) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL
       [`graph_neighbors (f:(A->bool)->bool) v`;
        `contract_split_side (E:(A->bool)->bool) f v`]
       FINITE_CARD_FOUR_SUBSET_SPLIT) THEN
      ASM_REWRITE_TAC[CONTRACT_SPLIT_SIDE_SUBSET_NEIGHBORS] THEN
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "empty")
       (DISJ_CASES_THEN2
        (X_CHOOSE_THEN `w:A` (LABEL_TAC "singleton"))
        (DISJ_CASES_THEN2 (LABEL_TAC "full")
         (DISJ_CASES_THEN2
          (X_CHOOSE_THEN `w:A` (LABEL_TAC "complement"))
          (LABEL_TAC "balanced"))))) THENL
       [MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
          `W:A->bool`; `complete_graph_edges (W:A->bool)`;
          `P:A->bool`; `f:(A->bool)->bool`]
         GRAPH_CONTRACT_SUBDIVISION_LIFT_EMPTY) THEN
        ASM_REWRITE_TAC[] THEN
        INTRO_TAC "@Q g. lifted final_vertices final_edges" THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
          `W:A->bool`; `Q:A->bool`; `g:(A->bool)->bool`]
         GRAPH_KURATOWSKI_OBSTRUCTION_K5) THEN
        ASM_REWRITE_TAC[];
        MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
          `W:A->bool`; `complete_graph_edges (W:A->bool)`;
          `P:A->bool`; `f:(A->bool)->bool`; `w:A`]
         GRAPH_CONTRACT_SUBDIVISION_LIFT_ONE) THEN
        ASM_REWRITE_TAC[] THEN
        INTRO_TAC "@Q g. lifted final_vertices final_edges" THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
          `W:A->bool`; `Q:A->bool`; `g:(A->bool)->bool`]
         GRAPH_KURATOWSKI_OBSTRUCTION_K5) THEN
        ASM_REWRITE_TAC[];
        MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
          `W:A->bool`; `complete_graph_edges (W:A->bool)`;
          `P:A->bool`; `f:(A->bool)->bool`]
         GRAPH_CONTRACT_SUBDIVISION_LIFT_FULL_SWAP) THEN
        ASM_REWRITE_TAC[] THEN
        INTRO_TAC "@Q g. lifted final_vertices final_edges" THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
          `W:A->bool`; `Q:A->bool`; `g:(A->bool)->bool`]
         GRAPH_KURATOWSKI_OBSTRUCTION_K5_SWAP) THEN
        ASM_REWRITE_TAC[];
        MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
          `W:A->bool`; `complete_graph_edges (W:A->bool)`;
          `P:A->bool`; `f:(A->bool)->bool`; `w:A`]
         GRAPH_CONTRACT_SUBDIVISION_LIFT_COMPLEMENT_ONE_SWAP) THEN
        ASM_REWRITE_TAC[] THEN
        INTRO_TAC "@Q g. lifted final_vertices final_edges" THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
          `W:A->bool`; `Q:A->bool`; `g:(A->bool)->bool`]
         GRAPH_KURATOWSKI_OBSTRUCTION_K5_SWAP) THEN
        ASM_REWRITE_TAC[];
        MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
          `W:A->bool`; `P:A->bool`; `f:(A->bool)->bool`]
         GRAPH_CONTRACT_COMPLETE_GRAPH_5_SUBDIVISION_LIFT_K33) THEN
        ASM_REWRITE_TAC[] THEN
        INTRO_TAC
         "@L R Q g. L_size R_size LR_disjoint lifted
                     final_vertices final_edges" THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
          `L:A->bool`; `R:A->bool`; `Q:A->bool`;
          `g:(A->bool)->bool`]
         GRAPH_KURATOWSKI_OBSTRUCTION_K33) THEN
        ASM_REWRITE_TAC[]];
      SUBGOAL_THEN
       `CARD(graph_neighbors (f:(A->bool)->bool) v) <= 3`
      (LABEL_TAC "small") THENL
       [MP_TAC(ISPECL
         [`W:A->bool`; `complete_graph_edges (W:A->bool)`;
          `P:A->bool`; `f:(A->bool)->bool`; `v:A`]
         GRAPH_SUBDIVISION_NONSOURCE_VERTEX_DEGREE_LE_2) THEN
        ASM_REWRITE_TAC[] THEN ARITH_TAC;
        MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
          `W:A->bool`; `complete_graph_edges (W:A->bool)`;
          `P:A->bool`; `f:(A->bool)->bool`]
         GRAPH_CONTRACT_SUBDIVISION_LIFT_SMALL_DEGREE) THEN
        ASM_REWRITE_TAC[] THEN
        DISCH_THEN(DISJ_CASES_THEN2
         (X_CHOOSE_THEN `Q:A->bool`
          (X_CHOOSE_THEN `g:(A->bool)->bool`
           (CONJUNCTS_THEN2 (LABEL_TAC "lifted")
            (CONJUNCTS_THEN2 (LABEL_TAC "final_vertices")
             (LABEL_TAC "final_edges")))))
         (X_CHOOSE_THEN `Q:A->bool`
          (X_CHOOSE_THEN `g:(A->bool)->bool`
           (CONJUNCTS_THEN2 (LABEL_TAC "lifted")
            (CONJUNCTS_THEN2 (LABEL_TAC "final_vertices")
             (LABEL_TAC "final_edges")))))) THENL
         [MATCH_MP_TAC(ISPECL
           [`V:A->bool`; `E:(A->bool)->bool`;
            `W:A->bool`; `Q:A->bool`; `g:(A->bool)->bool`]
           GRAPH_KURATOWSKI_OBSTRUCTION_K5) THEN
          ASM_REWRITE_TAC[];
          MATCH_MP_TAC(ISPECL
           [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
            `W:A->bool`; `Q:A->bool`; `g:(A->bool)->bool`]
           GRAPH_KURATOWSKI_OBSTRUCTION_K5_SWAP) THEN
          ASM_REWRITE_TAC[]]]];
    SUBGOAL_THEN
     `(f:(A->bool)->bool) SUBSET graph_contract_edges V E u v`
    (LABEL_TAC "edges") THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC
       `induced_subgraph_edges
         (graph_contract_edges (V:A->bool) E u v) P` THEN
      ASM_REWRITE_TAC[INDUCED_SUBGRAPH_EDGES_SUBSET];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD(graph_neighbors (f:(A->bool)->bool) v) <= 3`
    (LABEL_TAC "small") THENL
     [MATCH_MP_TAC(ISPECL
       [`X:A->bool`; `Y:A->bool`; `P:A->bool`;
        `f:(A->bool)->bool`; `v:A`]
       COMPLETE_BIPARTITE_3_3_SUBDIVISION_VERTEX_DEGREE_LE_3) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
        `X UNION Y:A->bool`;
        `complete_bipartite_edges (X:A->bool) Y`;
        `P:A->bool`; `f:(A->bool)->bool`]
       GRAPH_CONTRACT_SUBDIVISION_LIFT_SMALL_DEGREE) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(DISJ_CASES_THEN2
       (X_CHOOSE_THEN `Q:A->bool`
        (X_CHOOSE_THEN `g:(A->bool)->bool`
         (CONJUNCTS_THEN2 (LABEL_TAC "lifted")
          (CONJUNCTS_THEN2 (LABEL_TAC "final_vertices")
           (LABEL_TAC "final_edges")))))
       (X_CHOOSE_THEN `Q:A->bool`
        (X_CHOOSE_THEN `g:(A->bool)->bool`
         (CONJUNCTS_THEN2 (LABEL_TAC "lifted")
          (CONJUNCTS_THEN2 (LABEL_TAC "final_vertices")
           (LABEL_TAC "final_edges")))))) THENL
       [MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
          `X:A->bool`; `Y:A->bool`; `Q:A->bool`;
          `g:(A->bool)->bool`]
         GRAPH_KURATOWSKI_OBSTRUCTION_K33) THEN
        ASM_REWRITE_TAC[];
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
          `X:A->bool`; `Y:A->bool`; `Q:A->bool`;
          `g:(A->bool)->bool`]
         GRAPH_KURATOWSKI_OBSTRUCTION_K33_SWAP) THEN
        ASM_REWRITE_TAC[]]]]);;

(* ------------------------------------------------------------------------- *)
(* Simultaneously replacing four cyclically arranged edges by paths.         *)
(* ------------------------------------------------------------------------- *)

let four_path_extension_vertices = new_definition
 `four_path_extension_vertices (V:A->bool)
    (p0:num->A) l0 (p1:num->A) l1
    (p2:num->A) l2 (p3:num->A) l3 =
    (((V UNION indexed_path_vertices p0 l0) UNION
       indexed_path_vertices p1 l1) UNION
       indexed_path_vertices p2 l2) UNION
       indexed_path_vertices p3 l3`;;

let four_path_extension_edges = new_definition
 `four_path_extension_edges (E:(A->bool)->bool)
    (a:A) b c d
    (p0:num->A) l0 (p1:num->A) l1
    (p2:num->A) l2 (p3:num->A) l3 =
    (((((((E DELETE {a,b}) UNION indexed_path_edges p0 l0)
          DELETE {b,c}) UNION indexed_path_edges p1 l1)
          DELETE {c,d}) UNION indexed_path_edges p2 l2)
          DELETE {d,a}) UNION indexed_path_edges p3 l3`;;

let GRAPH_SUBDIVISION_EXTEND_FOUR_CYCLE_EDGES_BY_PATHS = prove
 (`!V:A->bool. !E:(A->bool)->bool. !a b c d:A.
   !l0 l1 l2 l3. !p0 p1 p2 p3:num->A.
        finite_simple_graph V E /\
        {a,b} IN E /\ {b,c} IN E /\ {c,d} IN E /\ {d,a} IN E /\
        (~(a = b) /\ ~(a = c) /\ ~(a = d) /\
         ~(b = c) /\ ~(b = d) /\ ~(c = d)) /\
        (0 < l0 /\ 0 < l1 /\ 0 < l2 /\ 0 < l3) /\
        (p0 0 = a /\ p0 l0 = b /\
         p1 0 = b /\ p1 l1 = c /\
         p2 0 = c /\ p2 l2 = d /\
         p3 0 = d /\ p3 l3 = a) /\
        (INJ p0 (0..l0) (:A) /\
         INJ p1 (0..l1) (:A) /\
         INJ p2 (0..l2) (:A) /\
         INJ p3 (0..l3) (:A)) /\
        (!i. 0 < i /\ i < l0 ==> ~(p0 i IN V)) /\
        (!i. 0 < i /\ i < l1
             ==> ~(p1 i IN V UNION indexed_path_vertices p0 l0)) /\
        (!i. 0 < i /\ i < l2
             ==> ~(p2 i IN
                   (V UNION indexed_path_vertices p0 l0) UNION
                   indexed_path_vertices p1 l1)) /\
        (!i. 0 < i /\ i < l3
             ==> ~(p3 i IN
                   ((V UNION indexed_path_vertices p0 l0) UNION
                    indexed_path_vertices p1 l1) UNION
                   indexed_path_vertices p2 l2))
        ==> graph_subdivision V E
             (four_path_extension_vertices V
               p0 l0 p1 l1 p2 l2 p3 l3)
             (four_path_extension_edges E a b c d
               p0 l0 p1 l1 p2 l2 p3 l3)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph edge0 edge1 edge2 edge3 \
    (ab ac ad bc bd cd) \
    (l0_positive l1_positive l2_positive l3_positive) \
    (p0_first p0_last p1_first p1_last p2_first p2_last p3_first p3_last) \
    (p0_injective p1_injective p2_injective p3_injective) \
    p0_fresh p1_fresh p2_fresh p3_fresh" THEN
  ABBREV_TAC `V0:A->bool =
    V UNION indexed_path_vertices (p0:num->A) l0` THEN
  ABBREV_TAC `E0:(A->bool)->bool =
    (E DELETE {a:A,b}) UNION indexed_path_edges (p0:num->A) l0` THEN
  SUBGOAL_THEN
   `graph_subdivision (V:A->bool) E (V0:A->bool) (E0:(A->bool)->bool)`
  (LABEL_TAC "subdivision0") THENL
   [MAP_EVERY EXPAND_TAC ["V0"; "E0"] THEN
    MATCH_MP_TAC(REWRITE_RULE
     [ASSUME `(p0:num->A) 0 = a`;
      ASSUME `(p0:num->A) l0 = b`]
     (SPECL
      [`l0:num`; `V:A->bool`; `E:(A->bool)->bool`; `p0:num->A`]
      GRAPH_SUBDIVISION_REPLACE_EDGE_BY_INDEXED_PATH_LENGTH)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{b:A,c} IN E0` (LABEL_TAC "retained_edge1") THENL
   [EXPAND_TAC "E0" THEN REWRITE_TAC[IN_UNION; IN_DELETE] THEN
    ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `V1:A->bool =
    V0 UNION indexed_path_vertices (p1:num->A) l1` THEN
  ABBREV_TAC `E1:(A->bool)->bool =
    (E0 DELETE {b:A,c}) UNION indexed_path_edges (p1:num->A) l1` THEN
  SUBGOAL_THEN
   `graph_subdivision (V:A->bool) E (V1:A->bool) (E1:(A->bool)->bool)`
  (LABEL_TAC "subdivision1") THENL
   [MAP_EVERY EXPAND_TAC ["V1"; "E1"] THEN
    MATCH_MP_TAC(REWRITE_RULE
     [ASSUME `(p1:num->A) 0 = b`;
      ASSUME `(p1:num->A) l1 = c`]
     (SPECL
      [`V:A->bool`; `E:(A->bool)->bool`;
       `V0:A->bool`; `E0:(A->bool)->bool`;
       `l1:num`; `p1:num->A`]
      GRAPH_SUBDIVISION_EXTEND_EDGE_BY_INDEXED_PATH_LENGTH)) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "p1_fresh" MP_TAC THEN
    EXPAND_TAC "V0" THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{c:A,d} IN E1` (LABEL_TAC "retained_edge2") THENL
   [MAP_EVERY EXPAND_TAC ["E1"; "E0"] THEN
    REWRITE_TAC[IN_UNION; IN_DELETE] THEN ASM_REWRITE_TAC[] THEN
    ASM SET_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `V2:A->bool =
    V1 UNION indexed_path_vertices (p2:num->A) l2` THEN
  ABBREV_TAC `E2:(A->bool)->bool =
    (E1 DELETE {c:A,d}) UNION indexed_path_edges (p2:num->A) l2` THEN
  SUBGOAL_THEN
   `graph_subdivision (V:A->bool) E (V2:A->bool) (E2:(A->bool)->bool)`
  (LABEL_TAC "subdivision2") THENL
   [MAP_EVERY EXPAND_TAC ["V2"; "E2"] THEN
    MATCH_MP_TAC(REWRITE_RULE
     [ASSUME `(p2:num->A) 0 = c`;
      ASSUME `(p2:num->A) l2 = d`]
     (SPECL
      [`V:A->bool`; `E:(A->bool)->bool`;
       `V1:A->bool`; `E1:(A->bool)->bool`;
       `l2:num`; `p2:num->A`]
      GRAPH_SUBDIVISION_EXTEND_EDGE_BY_INDEXED_PATH_LENGTH)) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "p2_fresh" MP_TAC THEN
    MAP_EVERY EXPAND_TAC ["V1"; "V0"] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{d:A,a} IN E2` (LABEL_TAC "retained_edge3") THENL
   [MAP_EVERY EXPAND_TAC ["E2"; "E1"; "E0"] THEN
    REWRITE_TAC[IN_UNION; IN_DELETE] THEN ASM_REWRITE_TAC[] THEN
    ASM SET_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXPAND_TAC ["V2"; "E2"; "V1"; "E1"; "V0"; "E0"] THEN
  REWRITE_TAC[four_path_extension_vertices; four_path_extension_edges] THEN
  MATCH_MP_TAC(REWRITE_RULE
   [ASSUME `(p3:num->A) 0 = d`;
    ASSUME `(p3:num->A) l3 = a`]
   (SPECL
    [`V:A->bool`; `E:(A->bool)->bool`;
     `((V UNION indexed_path_vertices (p0:num->A) l0) UNION
       indexed_path_vertices (p1:num->A) l1) UNION
       indexed_path_vertices (p2:num->A) l2`;
     `(((((E DELETE {a:A,b}) UNION indexed_path_edges (p0:num->A) l0)
         DELETE {b,c}) UNION indexed_path_edges (p1:num->A) l1)
         DELETE {c,d}) UNION indexed_path_edges (p2:num->A) l2`;
     `l3:num`; `p3:num->A`]
    GRAPH_SUBDIVISION_EXTEND_EDGE_BY_INDEXED_PATH_LENGTH)) THEN
  ASM_REWRITE_TAC[]);;

let FOUR_PATH_EXTENSION_EDGES_SUBSET = prove
 (`!B E C:(A->bool)->bool. !a b c d:A.
   !l0 l1 l2 l3. !p0 p1 p2 p3:num->A.
        B SUBSET {{a,b},{b,c},{c,d},{d,a}} UNION E /\
        indexed_path_edges p0 l0 SUBSET C /\
        indexed_path_edges p1 l1 SUBSET C /\
        indexed_path_edges p2 l2 SUBSET C /\
        indexed_path_edges p3 l3 SUBSET C /\
        C SUBSET E
        ==> four_path_extension_edges B a b c d
             p0 l0 p1 l1 p2 l2 p3 l3 SUBSET E`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[four_path_extension_edges] THEN
  SET_TAC[]);;

let three_path_extension_vertices = new_definition
 `three_path_extension_vertices (V:A->bool)
    (p0:num->A) l0 (p1:num->A) l1 (p2:num->A) l2 =
      ((V UNION indexed_path_vertices p0 l0) UNION
       indexed_path_vertices p1 l1) UNION
      indexed_path_vertices p2 l2`;;

let three_path_extension_edges = new_definition
 `three_path_extension_edges (E:(A->bool)->bool)
    (a:A) b c
    (p0:num->A) l0 (p1:num->A) l1 (p2:num->A) l2 =
      (((((E DELETE {a,b}) UNION indexed_path_edges p0 l0)
         DELETE {b,c}) UNION indexed_path_edges p1 l1)
         DELETE {c,a}) UNION indexed_path_edges p2 l2`;;

let GRAPH_SUBDIVISION_EXTEND_THREE_CYCLE_EDGES_BY_PATHS = prove
 (`!V:A->bool. !E:(A->bool)->bool. !a b c:A.
   !l0 l1 l2. !p0 p1 p2:num->A.
        finite_simple_graph V E /\
        {a,b} IN E /\ {b,c} IN E /\ {c,a} IN E /\
        ~(a = b) /\ ~(a = c) /\ ~(b = c) /\
        0 < l0 /\ 0 < l1 /\ 0 < l2 /\
        p0 0 = a /\ p0 l0 = b /\
        p1 0 = b /\ p1 l1 = c /\
        p2 0 = c /\ p2 l2 = a /\
        INJ p0 (0..l0) (:A) /\
        INJ p1 (0..l1) (:A) /\
        INJ p2 (0..l2) (:A) /\
        (!i. 0 < i /\ i < l0 ==> ~(p0 i IN V)) /\
        (!i. 0 < i /\ i < l1
             ==> ~(p1 i IN V UNION indexed_path_vertices p0 l0)) /\
        (!i. 0 < i /\ i < l2
             ==> ~(p2 i IN
                   (V UNION indexed_path_vertices p0 l0) UNION
                   indexed_path_vertices p1 l1))
        ==> graph_subdivision V E
             (three_path_extension_vertices V p0 l0 p1 l1 p2 l2)
             (three_path_extension_edges E a b c
               p0 l0 p1 l1 p2 l2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph edge0 edge1 edge2 ab ac bc \
    l0_positive l1_positive l2_positive \
    p0_first p0_last p1_first p1_last p2_first p2_last \
    p0_injective p1_injective p2_injective \
    p0_fresh p1_fresh p2_fresh" THEN
  ABBREV_TAC `V0:A->bool =
    V UNION indexed_path_vertices (p0:num->A) l0` THEN
  ABBREV_TAC `E0:(A->bool)->bool =
    (E DELETE {a:A,b}) UNION indexed_path_edges (p0:num->A) l0` THEN
  SUBGOAL_THEN
   `graph_subdivision (V:A->bool) E (V0:A->bool) (E0:(A->bool)->bool)`
  (LABEL_TAC "subdivision0") THENL
   [MAP_EVERY EXPAND_TAC ["V0"; "E0"] THEN
    MATCH_MP_TAC(REWRITE_RULE
     [ASSUME `(p0:num->A) 0 = a`;
      ASSUME `(p0:num->A) l0 = b`]
     (SPECL
      [`l0:num`; `V:A->bool`; `E:(A->bool)->bool`; `p0:num->A`]
      GRAPH_SUBDIVISION_REPLACE_EDGE_BY_INDEXED_PATH_LENGTH)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{b:A,c} IN E0` (LABEL_TAC "retained_edge1") THENL
   [EXPAND_TAC "E0" THEN REWRITE_TAC[IN_UNION; IN_DELETE] THEN
    ASM_REWRITE_TAC[] THEN ASM SET_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `V1:A->bool =
    V0 UNION indexed_path_vertices (p1:num->A) l1` THEN
  ABBREV_TAC `E1:(A->bool)->bool =
    (E0 DELETE {b:A,c}) UNION indexed_path_edges (p1:num->A) l1` THEN
  SUBGOAL_THEN
   `graph_subdivision (V:A->bool) E (V1:A->bool) (E1:(A->bool)->bool)`
  (LABEL_TAC "subdivision1") THENL
   [MAP_EVERY EXPAND_TAC ["V1"; "E1"] THEN
    MATCH_MP_TAC(REWRITE_RULE
     [ASSUME `(p1:num->A) 0 = b`;
      ASSUME `(p1:num->A) l1 = c`]
     (SPECL
      [`V:A->bool`; `E:(A->bool)->bool`;
       `V0:A->bool`; `E0:(A->bool)->bool`;
       `l1:num`; `p1:num->A`]
      GRAPH_SUBDIVISION_EXTEND_EDGE_BY_INDEXED_PATH_LENGTH)) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "p1_fresh" MP_TAC THEN
    EXPAND_TAC "V0" THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{c:A,a} IN E1` (LABEL_TAC "retained_edge2") THENL
   [MAP_EVERY EXPAND_TAC ["E1"; "E0"] THEN
    REWRITE_TAC[IN_UNION; IN_DELETE] THEN ASM_REWRITE_TAC[] THEN
    ASM SET_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXPAND_TAC ["V1"; "E1"; "V0"; "E0"] THEN
  REWRITE_TAC[three_path_extension_vertices;
              three_path_extension_edges] THEN
  MATCH_MP_TAC(REWRITE_RULE
   [ASSUME `(p2:num->A) 0 = c`;
    ASSUME `(p2:num->A) l2 = a`]
   (SPECL
    [`V:A->bool`; `E:(A->bool)->bool`;
     `(V UNION indexed_path_vertices (p0:num->A) l0) UNION
       indexed_path_vertices (p1:num->A) l1`;
     `((E DELETE {a:A,b}) UNION indexed_path_edges (p0:num->A) l0)
       DELETE {b,c} UNION indexed_path_edges (p1:num->A) l1`;
     `l2:num`; `p2:num->A`]
    GRAPH_SUBDIVISION_EXTEND_EDGE_BY_INDEXED_PATH_LENGTH)) THEN
  ASM_REWRITE_TAC[]);;

let THREE_PATH_EXTENSION_EDGES_SUBSET = prove
 (`!B E C:(A->bool)->bool. !a b c:A.
   !l0 l1 l2. !p0 p1 p2:num->A.
        B SUBSET {{a,b},{b,c},{c,a}} UNION E /\
        indexed_path_edges p0 l0 SUBSET C /\
        indexed_path_edges p1 l1 SUBSET C /\
        indexed_path_edges p2 l2 SUBSET C /\
        C SUBSET E
        ==> three_path_extension_edges B a b c
             p0 l0 p1 l1 p2 l2 SUBSET E`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[three_path_extension_edges] THEN
  SET_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Kuratowski obstructions formed by spokes to a simple cycle.               *)
(* ------------------------------------------------------------------------- *)

let COMPLETE_BIPARTITE_ALTERNATING_SIX_SUBSET = prove
 (`!a b c d u v:A.
        complete_bipartite_edges {a,c,v} {b,d,u} SUBSET
        {{a,b},{b,c},{c,d},{d,a},{u,a},{u,c},{v,b},{v,d},{u,v}}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[SUBSET; IN_COMPLETE_BIPARTITE_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN
  INTRO_TAC "@x y. x_member y_member edge_value" THEN
  USE_THEN "edge_value" SUBST1_TAC THEN
  USE_THEN "x_member" MP_TAC THEN
  REWRITE_TAC[IN_INSERT; IN_SING] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  USE_THEN "y_member" MP_TAC THEN
  REWRITE_TAC[IN_INSERT; IN_SING] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  REWRITE_TAC[IN_INSERT; IN_SING; PAIR_SET_SYM]);;

let COMPLETE_BIPARTITE_ALTERNATING_CYCLE_EDGES = prove
 (`!a b c d u v:A.
        {a,b} IN complete_bipartite_edges {a,c,v} {b,d,u} /\
        {b,c} IN complete_bipartite_edges {a,c,v} {b,d,u} /\
        {c,d} IN complete_bipartite_edges {a,c,v} {b,d,u} /\
        {d,a} IN complete_bipartite_edges {a,c,v} {b,d,u}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[IN_COMPLETE_BIPARTITE_EDGES] THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY EXISTS_TAC [`a:A`; `b:A`] THEN
    REWRITE_TAC[IN_INSERT];
    MAP_EVERY EXISTS_TAC [`c:A`; `b:A`] THEN
    REWRITE_TAC[IN_INSERT] THEN SET_TAC[];
    MAP_EVERY EXISTS_TAC [`c:A`; `d:A`] THEN
    REWRITE_TAC[IN_INSERT];
    MAP_EVERY EXISTS_TAC [`a:A`; `d:A`] THEN
    REWRITE_TAC[IN_INSERT] THEN SET_TAC[]]);;

let COMPLETE_BIPARTITE_ALTERNATING_REMAINDER_SUBSET = prove
 (`!E:(A->bool)->bool. !a b c d u v:A.
        {u,a} IN E /\ {u,c} IN E /\
        {v,b} IN E /\ {v,d} IN E /\ {u,v} IN E
        ==> complete_bipartite_edges {a,c,v} {b,d,u} SUBSET
            {{a,b},{b,c},{c,d},{d,a}} UNION E`,
  REPEAT GEN_TAC THEN INTRO_TAC "edge_ua edge_uc edge_vb edge_vd edge_uv" THEN
  MATCH_MP_TAC SUBSET_TRANS THEN
  EXISTS_TAC
   `{{a:A,b},{b,c},{c,d},{d,a},{u,a},{u,c},{v,b},{v,d},{u,v}}` THEN
  CONJ_TAC THENL
   [MATCH_ACCEPT_TAC(SPECL
     [`a:A`; `b:A`; `c:A`; `d:A`; `u:A`; `v:A`]
     COMPLETE_BIPARTITE_ALTERNATING_SIX_SUBSET);
    REWRITE_TAC[SUBSET; FORALL_IN_INSERT; NOT_IN_EMPTY;
                IN_UNION; IN_INSERT; IN_SING] THEN
    ASM_REWRITE_TAC[PAIR_SET_SYM]]);;

let CYCLIC_FOUR_PATH_FRESH_WITH_TWO_OUTSIDE = prove
 (`!q:num->A. !n i j k. !u v:A.
        0 < i /\ i < j /\ j < k /\ k < n /\
        INJ q (cyclic_indices n) (:A) /\
        ~(u IN cyclic_vertices q n) /\
        ~(v IN cyclic_vertices q n)
        ==> (!t. 0 < t /\ t < i
                  ==> ~(q t IN
                        {q 0,q j,v} UNION {q i,q k,u})) /\
            (!t. 0 < t /\ t < j - i
                  ==> ~(cyclic_offset_path q i t IN
                        ({q 0,q j,v} UNION {q i,q k,u}) UNION
                        indexed_path_vertices q i)) /\
            (!t. 0 < t /\ t < k - j
                  ==> ~(cyclic_offset_path q j t IN
                        (({q 0,q j,v} UNION {q i,q k,u}) UNION
                         indexed_path_vertices q i) UNION
                        indexed_path_vertices
                         (cyclic_offset_path q i) (j - i))) /\
            (!t. 0 < t /\ t < n - k
                  ==> ~(cyclic_closing_path q k n t IN
                        ((({q 0,q j,v} UNION {q i,q k,u}) UNION
                          indexed_path_vertices q i) UNION
                         indexed_path_vertices
                          (cyclic_offset_path q i) (j - i)) UNION
                        indexed_path_vertices
                         (cyclic_offset_path q j) (k - j)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "i_positive ij jk kn injective u_outside v_outside" THEN
  MP_TAC(ISPECL [`q:num->A`; `n:num`; `i:num`; `j:num`; `k:num`]
    CYCLIC_FOUR_PATH_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "_ _ _ _ p0_base p1_base p2_base p3_base" THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `t:num` THEN INTRO_TAC "t_positive t_bound" THEN
    SUBGOAL_THEN `(q:num->A) t IN cyclic_vertices q n`
    (LABEL_TAC "point_cycle") THENL
     [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `t:num` THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "p0_base" (MP_TAC o SPEC `t:num`) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "base_fresh") THEN
    ASM SET_TAC[];
    X_GEN_TAC `t:num` THEN INTRO_TAC "t_positive t_bound" THEN
    SUBGOAL_THEN
     `cyclic_offset_path (q:num->A) i t IN cyclic_vertices q n`
    (LABEL_TAC "point_cycle") THENL
     [REWRITE_TAC[cyclic_offset_path; IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `i + t:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "p1_base" (MP_TAC o SPEC `t:num`) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "base_fresh") THEN
    ASM SET_TAC[];
    X_GEN_TAC `t:num` THEN INTRO_TAC "t_positive t_bound" THEN
    SUBGOAL_THEN
     `cyclic_offset_path (q:num->A) j t IN cyclic_vertices q n`
    (LABEL_TAC "point_cycle") THENL
     [REWRITE_TAC[cyclic_offset_path; IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `j + t:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "p2_base" (MP_TAC o SPEC `t:num`) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "base_fresh") THEN
    ASM SET_TAC[];
    X_GEN_TAC `t:num` THEN INTRO_TAC "t_positive t_bound" THEN
    SUBGOAL_THEN
     `cyclic_closing_path (q:num->A) k n t IN cyclic_vertices q n`
    (LABEL_TAC "point_cycle") THENL
     [REWRITE_TAC[cyclic_closing_path] THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `k + t:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "p3_base" (MP_TAC o SPEC `t:num`) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "base_fresh") THEN
    ASM SET_TAC[]]);;

let kuratowski_alternating_vertices = new_definition
 `kuratowski_alternating_vertices
    (q:num->A) n i j k (u:A) v =
      four_path_extension_vertices
       ({q 0,q j,v} UNION {q i,q k,u})
       q i
       (cyclic_offset_path q i) (j - i)
       (cyclic_offset_path q j) (k - j)
       (cyclic_closing_path q k n) (n - k)`;;

let kuratowski_alternating_edges = new_definition
 `kuratowski_alternating_edges
    (q:num->A) n i j k (u:A) v =
      four_path_extension_edges
       (complete_bipartite_edges {q 0,q j,v} {q i,q k,u})
       (q 0) (q i) (q j) (q k)
       q i
       (cyclic_offset_path q i) (j - i)
       (cyclic_offset_path q j) (k - j)
       (cyclic_closing_path q k n) (n - k)`;;

let GRAPH_KURATOWSKI_OBSTRUCTION_ALTERNATING_SPOKES = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !q:num->A. !n i j k. !u v:A.
        0 < i /\ i < j /\ j < k /\ k < n /\
        INJ q (cyclic_indices n) (:A) /\
        cyclic_vertices q n SUBSET V /\
        cyclic_edges q n SUBSET E /\
        u IN V /\ v IN V /\ ~(u = v) /\
        ~(u IN cyclic_vertices q n) /\
        ~(v IN cyclic_vertices q n) /\
        {u,v} IN E /\
        {u,q 0} IN E /\ {u,q j} IN E /\
        {v,q i} IN E /\ {v,q k} IN E
        ==> graph_kuratowski_obstruction V E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "i_positive ij jk kn injective cycle_vertices cycle_edges \
    u_vertex v_vertex uv u_outside v_outside \
    edge_uv edge_u0 edge_uj edge_vi edge_vk" THEN
  MP_TAC(ISPECL [`q:num->A`; `n:num`; `i:num`; `j:num`; `k:num`]
    CYCLIC_FOUR_PATH_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "(q0i q0j q0k qij qik qjk) \
    (l1_positive l2_positive l3_positive) \
    (p1_first p1_last p2_first p2_last p3_first p3_last) \
    (p0_injective p1_injective p2_injective p3_injective) \
    p0_fresh_four p1_fresh_four p2_fresh_four p3_fresh_four" THEN
  SUBGOAL_THEN `(q:num->A) 0 IN cyclic_vertices q n`
  (LABEL_TAC "q0_cycle") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `0` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:num->A) i IN cyclic_vertices q n`
  (LABEL_TAC "qi_cycle") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `i:num` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:num->A) j IN cyclic_vertices q n`
  (LABEL_TAC "qj_cycle") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `j:num` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:num->A) k IN cyclic_vertices q n`
  (LABEL_TAC "qk_cycle") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `k:num` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((q:num->A) 0 = v) /\ ~(q j = v) /\
    ~(q i = u) /\ ~(q k = u)`
  (CONJUNCTS_THEN2 (LABEL_TAC "q0v")
   (CONJUNCTS_THEN2 (LABEL_TAC "qjv")
    (CONJUNCTS_THEN2 (LABEL_TAC "qiu")
     (LABEL_TAC "qku")))) THENL
   [ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `{(q:num->A) 0,q j,v} HAS_SIZE 3`
  (LABEL_TAC "X_size") THENL
   [REWRITE_TAC
     [HAS_SIZE_CONV `({(q:num->A) 0,q j,v}:A->bool) HAS_SIZE 3`] THEN
    MAP_EVERY EXISTS_TAC
     [`(q:num->A) 0`; `(q:num->A) j`; `v:A`] THEN
    REWRITE_TAC
     [ASSUME `~((q:num->A) j = v)`;
      ASSUME `~((q:num->A) 0 = q j)`;
      ASSUME `~((q:num->A) 0 = v)`];
    ALL_TAC] THEN
  SUBGOAL_THEN `{(q:num->A) i,q k,u} HAS_SIZE 3`
  (LABEL_TAC "Y_size") THENL
   [REWRITE_TAC
     [HAS_SIZE_CONV `({(q:num->A) i,q k,u}:A->bool) HAS_SIZE 3`] THEN
    EXISTS_TAC `(q:num->A) i` THEN
    EXISTS_TAC `(q:num->A) k` THEN
    EXISTS_TAC `u:A` THEN
    REWRITE_TAC
     [ASSUME `~((q:num->A) k = u)`;
      ASSUME `~((q:num->A) i = q k)`;
      ASSUME `~((q:num->A) i = u)`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `DISJOINT {(q:num->A) 0,q j,v} {q i,q k,u}`
  (LABEL_TAC "disjoint") THENL
   [REWRITE_TAC[DISJOINT] THEN ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph
      ({(q:num->A) 0,q j,v} UNION {q i,q k,u})
      (complete_bipartite_edges {q 0,q j,v} {q i,q k,u})`
  (LABEL_TAC "source_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_COMPLETE_BIPARTITE_GRAPH THEN
    ASM_REWRITE_TAC[FINITE_INSERT; FINITE_EMPTY];
    ALL_TAC] THEN
  MP_TAC(ISPECL
  [`(q:num->A) 0`; `(q:num->A) i`;
    `(q:num->A) j`; `(q:num->A) k`; `u:A`; `v:A`]
   COMPLETE_BIPARTITE_ALTERNATING_CYCLE_EDGES) THEN
  INTRO_TAC "source_edge0 source_edge1 source_edge2 source_edge3" THEN
  MP_TAC(ISPECL
   [`q:num->A`; `n:num`; `i:num`; `j:num`; `k:num`; `u:A`; `v:A`]
  CYCLIC_FOUR_PATH_FRESH_WITH_TWO_OUTSIDE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "p0_fresh p1_fresh p2_fresh p3_fresh" THEN
  SUBGOAL_THEN
   `graph_subdivision
      ({(q:num->A) 0,q j,v} UNION {q i,q k,u})
      (complete_bipartite_edges {q 0,q j,v} {q i,q k,u})
      (kuratowski_alternating_vertices q n i j k u v)
      (kuratowski_alternating_edges q n i j k u v)`
  (LABEL_TAC "subdivision") THENL
   [REWRITE_TAC
     [kuratowski_alternating_vertices; kuratowski_alternating_edges] THEN
    MATCH_MP_TAC GRAPH_SUBDIVISION_EXTEND_FOUR_CYCLE_EDGES_BY_PATHS THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `kuratowski_alternating_vertices
      (q:num->A) n i j k u v SUBSET V`
  (LABEL_TAC "vertices") THENL
   [REWRITE_TAC
     [kuratowski_alternating_vertices;
      four_path_extension_vertices; UNION_SUBSET] THEN
    REPEAT CONJ_TAC THENL
     [ASM SET_TAC[];
      ASM SET_TAC[];
      MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `cyclic_vertices (q:num->A) n` THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC INDEXED_PREFIX_VERTICES_SUBSET_CYCLIC THEN
      ASM_ARITH_TAC;
      MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `cyclic_vertices (q:num->A) n` THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC INDEXED_OFFSET_VERTICES_SUBSET_CYCLIC THEN
      ASM_ARITH_TAC;
      MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `cyclic_vertices (q:num->A) n` THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC INDEXED_OFFSET_VERTICES_SUBSET_CYCLIC THEN
      ASM_ARITH_TAC;
      MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `cyclic_vertices (q:num->A) n` THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC INDEXED_CLOSING_VERTICES_SUBSET_CYCLIC THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`q:num->A`; `i:num`; `n:num`]
    INDEXED_PREFIX_EDGES_SUBSET_CYCLIC) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(LABEL_TAC "path0_cycle")] THEN
  MP_TAC(ISPECL [`q:num->A`; `i:num`; `j - i:num`; `n:num`]
    INDEXED_OFFSET_EDGES_SUBSET_CYCLIC) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(LABEL_TAC "path1_cycle")] THEN
  MP_TAC(ISPECL [`q:num->A`; `j:num`; `k - j:num`; `n:num`]
    INDEXED_OFFSET_EDGES_SUBSET_CYCLIC) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(LABEL_TAC "path2_cycle")] THEN
  MP_TAC(ISPECL [`q:num->A`; `k:num`; `n:num`]
    INDEXED_CLOSING_EDGES_SUBSET_CYCLIC) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "path3_cycle") THEN
  SUBGOAL_THEN
   `complete_bipartite_edges
      {(q:num->A) 0,q j,v} {q i,q k,u} SUBSET
    {{q 0,q i},{q i,q j},{q j,q k},{q k,q 0}} UNION E`
  (LABEL_TAC "source_edges") THENL
   [MATCH_MP_TAC COMPLETE_BIPARTITE_ALTERNATING_REMAINDER_SUBSET THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `kuratowski_alternating_edges
      (q:num->A) n i j k u v SUBSET E`
  (LABEL_TAC "edges") THENL
   [REWRITE_TAC
     [kuratowski_alternating_edges] THEN
    MATCH_MP_TAC FOUR_PATH_EXTENSION_EDGES_SUBSET THEN
    EXISTS_TAC `cyclic_edges (q:num->A) n` THEN
    (fun (asl,_ as g) ->
      let th =
       CONJ (assoc "source_edges" asl)
        (CONJ (assoc "path0_cycle" asl)
         (CONJ (assoc "path1_cycle" asl)
           (CONJ (assoc "path2_cycle" asl)
           (CONJ (assoc "path3_cycle" asl)
                 (assoc "cycle_edges" asl))))) in
      ACCEPT_TAC th g);
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `{(q:num->A) 0,q j,v}`; `{(q:num->A) i,q k,u}`;
    `kuratowski_alternating_vertices
      (q:num->A) n i j k u v`;
    `kuratowski_alternating_edges
      (q:num->A) n i j k u v`]
   GRAPH_KURATOWSKI_OBSTRUCTION_K33_SUBGRAPH) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* A K5 obstruction formed by two common sets of spokes to a simple cycle.   *)
(* ------------------------------------------------------------------------- *)

let CYCLIC_VERTEX_NOT_IN_THREE = prove
 (`!q:num->A. !n h a b c.
        INJ q (cyclic_indices n) (:A) /\
        h < n /\ a < n /\ b < n /\ c < n /\
        ~(h = a) /\ ~(h = b) /\ ~(h = c)
        ==> ~(q h IN {q a,q b,q c})`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[IN_INSERT; IN_SING] THEN
  MESON_TAC[CYCLIC_INJECTIVE_INDEX]);;

let CYCLIC_THREE_PATH_DATA = prove
 (`!q:num->A. !n i j.
        0 < i /\ i < j /\ j < n /\
        INJ q (cyclic_indices n) (:A)
        ==> (~(q 0 = q i) /\ ~(q 0 = q j) /\ ~(q i = q j)) /\
            (0 < i /\ 0 < j - i /\ 0 < n - j) /\
            (q 0 = q 0 /\ q i = q i /\
             cyclic_offset_path q i 0 = q i /\
             cyclic_offset_path q i (j - i) = q j /\
             cyclic_closing_path q j n 0 = q j /\
             cyclic_closing_path q j n (n - j) = q 0) /\
            (INJ q (0..i) (:A) /\
             INJ (cyclic_offset_path q i) (0..j - i) (:A) /\
             INJ (cyclic_closing_path q j n) (0..n - j) (:A)) /\
            (!t. 0 < t /\ t < i
                 ==> ~(q t IN {q 0,q i,q j})) /\
            (!t. 0 < t /\ t < j - i
                 ==> ~(cyclic_offset_path q i t IN
                       {q 0,q i,q j} UNION
                       indexed_path_vertices q i)) /\
            (!t. 0 < t /\ t < n - j
                 ==> ~(cyclic_closing_path q j n t IN
                       ({q 0,q i,q j} UNION
                        indexed_path_vertices q i) UNION
                       indexed_path_vertices
                        (cyclic_offset_path q i) (j - i)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "i_positive ij jn injective" THEN
  SUBGOAL_THEN `(i:num) + (j - i) = j`
  (LABEL_TAC "ij_split") THENL
   [MATCH_MP_TAC NUM_ADD_SUB_RIGHT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(j:num) + (n - j) = n`
  (LABEL_TAC "jn_split") THENL
   [MATCH_MP_TAC NUM_ADD_SUB_RIGHT THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~((q:num->A) 0 = q i) /\ ~(q 0 = q j) /\ ~(q i = q j)`
  (LABEL_TAC "distinct") THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC CYCLIC_INJECTIVE_NE THEN
      EXISTS_TAC `n:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      CONJ_TAC THENL
       [MATCH_MP_TAC CYCLIC_INJECTIVE_NE THEN
        EXISTS_TAC `n:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        MATCH_MP_TAC CYCLIC_INJECTIVE_NE THEN
        EXISTS_TAC `n:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `0 < i /\ 0 < j - i /\ 0 < n - j`
  (LABEL_TAC "lengths") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `0 < (j:num)` (LABEL_TAC "j_positive") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(i:num) < n` (LABEL_TAC "i_index") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(i:num) + (j - i) < n`
  (LABEL_TAC "p1_last_index") THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_closing_path (q:num->A) j n 0 = q j /\
    cyclic_closing_path q j n (n - j) = q 0`
  (CONJUNCTS_THEN2 (LABEL_TAC "closing_first")
   (LABEL_TAC "closing_last")) THENL
   [USE_THEN "j_positive" (fun jth ->
     USE_THEN "jn" (fun jnth ->
      ACCEPT_TAC(MATCH_MP
       (SPECL [`q:num->A`; `n:num`; `j:num`]
        CYCLIC_CLOSING_PATH_VALUES)
       (CONJ jth jnth))));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:num->A) 0 = q 0 /\ q i = q i /\
    cyclic_offset_path q i 0 = q i /\
    cyclic_offset_path q i (j - i) = q j /\
    cyclic_closing_path q j n 0 = q j /\
    cyclic_closing_path q j n (n - j) = q 0`
  (LABEL_TAC "endpoints") THENL
   [ASM_REWRITE_TAC[cyclic_offset_path; ADD_CLAUSES];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `INJ (q:num->A) (0..i) (:A) /\
    INJ (cyclic_offset_path q i) (0..j - i) (:A) /\
    INJ (cyclic_closing_path q j n) (0..n - j) (:A)`
  (LABEL_TAC "path_injective") THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "injective" (fun ith ->
       USE_THEN "i_index" (fun index_th ->
        ACCEPT_TAC(MATCH_MP
         (SPECL [`q:num->A`; `n:num`; `i:num`]
          CYCLIC_PREFIX_PATH_INJ)
         (CONJ ith index_th))));
      USE_THEN "injective" (fun ith ->
       USE_THEN "p1_last_index" (fun index_th ->
        ACCEPT_TAC(MATCH_MP
         (SPECL [`q:num->A`; `n:num`; `i:num`; `j - i:num`]
          CYCLIC_OFFSET_PATH_INJ)
         (CONJ ith index_th))));
      USE_THEN "j_positive" (fun jpth ->
       USE_THEN "jn" (fun jth ->
        USE_THEN "injective" (fun ith ->
         ACCEPT_TAC(MATCH_MP
          (SPECL [`q:num->A`; `n:num`; `j:num`]
           CYCLIC_CLOSING_PATH_INJ)
          (CONJ jpth (CONJ jth ith))))))];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t. 0 < t /\ t < i
        ==> ~((q:num->A) t IN {q 0,q i,q j})`
  (LABEL_TAC "fresh0") THENL
   [X_GEN_TAC `t:num` THEN INTRO_TAC "positive bound" THEN
    MATCH_MP_TAC(ISPECL
     [`q:num->A`; `n:num`; `t:num`; `0`; `i:num`; `j:num`]
     CYCLIC_VERTEX_NOT_IN_THREE) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t. 0 < t /\ t < j - i
        ==> ~(cyclic_offset_path (q:num->A) i t IN
              {q 0,q i,q j} UNION indexed_path_vertices q i)`
  (LABEL_TAC "fresh1") THENL
   [X_GEN_TAC `t:num` THEN INTRO_TAC "positive bound" THEN
    SUBGOAL_THEN `(i:num) + t < j`
    (LABEL_TAC "index_before_j") THENL
     [MATCH_MP_TAC NUM_CLOSING_INTERIOR_BOUND THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[cyclic_offset_path; IN_UNION; DE_MORGAN_THM] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(i:num) + t`;
        `0`; `i:num`; `j:num`]
       CYCLIC_VERTEX_NOT_IN_THREE) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(i:num) + t`; `i:num`]
       CYCLIC_VERTEX_NOT_IN_PREFIX_PATH) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t. 0 < t /\ t < n - j
        ==> ~(cyclic_closing_path (q:num->A) j n t IN
              ({q 0,q i,q j} UNION indexed_path_vertices q i) UNION
              indexed_path_vertices
               (cyclic_offset_path q i) (j - i))`
  (LABEL_TAC "fresh2") THENL
   [X_GEN_TAC `t:num` THEN INTRO_TAC "positive bound" THEN
    SUBGOAL_THEN `(j:num) + t < n`
    (LABEL_TAC "index_before_n") THENL
     [MATCH_MP_TAC NUM_CLOSING_INTERIOR_BOUND THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[cyclic_closing_path] THEN
    REWRITE_TAC[IN_UNION; DE_MORGAN_THM] THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(j:num) + t`;
        `0`; `i:num`; `j:num`]
       CYCLIC_VERTEX_NOT_IN_THREE) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(j:num) + t`; `i:num`]
       CYCLIC_VERTEX_NOT_IN_PREFIX_PATH) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC(ISPECL
       [`q:num->A`; `n:num`; `(j:num) + t`;
        `i:num`; `j - i:num`]
       CYCLIC_VERTEX_NOT_IN_OFFSET_PATH) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let FIVE_DISTINCT_GRAPH_FACTS = prove
 (`!a b c u v:A.
        ~(a = b) /\ ~(a = c) /\ ~(a = u) /\ ~(a = v) /\
        ~(b = c) /\ ~(b = u) /\ ~(b = v) /\
        ~(c = u) /\ ~(c = v) /\ ~(u = v)
        ==> finite_simple_graph
             {a,b,c,u,v} (complete_graph_edges {a,b,c,u,v}) /\
            {a,b} IN complete_graph_edges {a,b,c,u,v} /\
            {b,c} IN complete_graph_edges {a,b,c,u,v} /\
            {c,a} IN complete_graph_edges {a,b,c,u,v}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "ab ac au av bc bu bv cu cv uv" THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SIMPLE_COMPLETE_GRAPH THEN
    SIMP_TAC[FINITE_INSERT; FINITE_EMPTY];
    REWRITE_TAC[IN_COMPLETE_GRAPH_EDGES; PAIR_HAS_SIZE_2] THEN
    ASM SET_TAC[]]);;

let COMPLETE_GRAPH_FIVE_SPOKES_SUBSET = prove
 (`!a b c u v:A.
        complete_graph_edges {a,b,c,u,v} SUBSET
        {{a,b},{b,c},{c,a},
         {u,v},{u,a},{u,b},{u,c},{v,a},{v,b},{v,c}}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[SUBSET; IN_COMPLETE_GRAPH_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN INTRO_TAC "endpoints size" THEN
  USE_THEN "size" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE_CONV `(e:A->bool) HAS_SIZE 2`] THEN
  INTRO_TAC "@x y. distinct edge_value" THEN
  SUBGOAL_THEN `({x:A,y}:A->bool) SUBSET {a,b,c,u,v}`
  MP_TAC THENL
   [REWRITE_TAC[SUBSET; IN_INSERT; IN_SING] THEN
    X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_pair") THEN
    USE_THEN "endpoints" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL
     [USE_THEN "edge_value" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_INSERT; IN_SING] THEN
      USE_THEN "z_pair" ACCEPT_TAC;
      REWRITE_TAC[IN_INSERT; IN_SING]];
    ALL_TAC] THEN
  REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_INSERT; IN_SING] THEN
  INTRO_TAC "x_cases y_cases" THEN
  USE_THEN "edge_value" SUBST1_TAC THEN
  USE_THEN "x_cases" MP_TAC THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  USE_THEN "y_cases" MP_TAC THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
  ASM_REWRITE_TAC[IN_INSERT; IN_SING; PAIR_SET_SYM] THEN
  ASM_MESON_TAC[]);;

let COMPLETE_GRAPH_FIVE_SPOKES_REMAINDER_SUBSET = prove
 (`!E:(A->bool)->bool. !a b c u v:A.
        {u,v} IN E /\
        {u,a} IN E /\ {u,b} IN E /\ {u,c} IN E /\
        {v,a} IN E /\ {v,b} IN E /\ {v,c} IN E
        ==> complete_graph_edges {a,b,c,u,v} SUBSET
            {{a,b},{b,c},{c,a}} UNION E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "edge_uv edge_ua edge_ub edge_uc edge_va edge_vb edge_vc" THEN
  MATCH_MP_TAC SUBSET_TRANS THEN
  EXISTS_TAC
   `{{a:A,b},{b,c},{c,a},
     {u,v},{u,a},{u,b},{u,c},{v,a},{v,b},{v,c}}` THEN
  CONJ_TAC THENL
   [MATCH_ACCEPT_TAC(SPECL
     [`a:A`; `b:A`; `c:A`; `u:A`; `v:A`]
     COMPLETE_GRAPH_FIVE_SPOKES_SUBSET);
    REWRITE_TAC[SUBSET; FORALL_IN_INSERT; NOT_IN_EMPTY;
                IN_UNION; IN_INSERT; IN_SING] THEN
    ASM_REWRITE_TAC[PAIR_SET_SYM]]);;

let CYCLIC_THREE_PATH_FRESH_WITH_TWO_OUTSIDE = prove
 (`!q:num->A. !n i j. !u v:A.
        0 < i /\ i < j /\ j < n /\
        INJ q (cyclic_indices n) (:A) /\
        ~(u IN cyclic_vertices q n) /\
        ~(v IN cyclic_vertices q n)
        ==> (!t. 0 < t /\ t < i
                  ==> ~(q t IN {q 0,q i,q j,u,v})) /\
            (!t. 0 < t /\ t < j - i
                  ==> ~(cyclic_offset_path q i t IN
                        {q 0,q i,q j,u,v} UNION
                        indexed_path_vertices q i)) /\
            (!t. 0 < t /\ t < n - j
                  ==> ~(cyclic_closing_path q j n t IN
                        ({q 0,q i,q j,u,v} UNION
                         indexed_path_vertices q i) UNION
                        indexed_path_vertices
                         (cyclic_offset_path q i) (j - i)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "i_positive ij jn injective u_outside v_outside" THEN
  MP_TAC(ISPECL [`q:num->A`; `n:num`; `i:num`; `j:num`]
    CYCLIC_THREE_PATH_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "_ _ _ _ p0_base p1_base p2_base" THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `t:num` THEN INTRO_TAC "t_positive t_bound" THEN
    SUBGOAL_THEN `(q:num->A) t IN cyclic_vertices q n`
    (LABEL_TAC "point_cycle") THENL
     [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `t:num` THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "p0_base" (MP_TAC o SPEC `t:num`) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "base_fresh") THEN
    ASM SET_TAC[];
    X_GEN_TAC `t:num` THEN INTRO_TAC "t_positive t_bound" THEN
    SUBGOAL_THEN
     `cyclic_offset_path (q:num->A) i t IN cyclic_vertices q n`
    (LABEL_TAC "point_cycle") THENL
     [REWRITE_TAC[cyclic_offset_path; IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `i + t:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "p1_base" (MP_TAC o SPEC `t:num`) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "base_fresh") THEN
    ASM SET_TAC[];
    X_GEN_TAC `t:num` THEN INTRO_TAC "t_positive t_bound" THEN
    SUBGOAL_THEN
     `cyclic_closing_path (q:num->A) j n t IN cyclic_vertices q n`
    (LABEL_TAC "point_cycle") THENL
     [REWRITE_TAC[cyclic_closing_path] THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `j + t:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "p2_base" (MP_TAC o SPEC `t:num`) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "base_fresh") THEN
    ASM SET_TAC[]]);;

let kuratowski_common_vertices = new_definition
 `kuratowski_common_vertices
    (q:num->A) n i j (u:A) v =
      three_path_extension_vertices
       {q 0,q i,q j,u,v}
       q i
       (cyclic_offset_path q i) (j - i)
       (cyclic_closing_path q j n) (n - j)`;;

let kuratowski_common_edges = new_definition
 `kuratowski_common_edges
    (q:num->A) n i j (u:A) v =
      three_path_extension_edges
       (complete_graph_edges {q 0,q i,q j,u,v})
       (q 0) (q i) (q j)
       q i
       (cyclic_offset_path q i) (j - i)
       (cyclic_closing_path q j n) (n - j)`;;

let GRAPH_KURATOWSKI_OBSTRUCTION_COMMON_SPOKES = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !q:num->A. !n i j. !u v:A.
        0 < i /\ i < j /\ j < n /\
        INJ q (cyclic_indices n) (:A) /\
        cyclic_vertices q n SUBSET V /\
        cyclic_edges q n SUBSET E /\
        u IN V /\ v IN V /\ ~(u = v) /\
        ~(u IN cyclic_vertices q n) /\
        ~(v IN cyclic_vertices q n) /\
        {u,v} IN E /\
        {u,q 0} IN E /\ {u,q i} IN E /\ {u,q j} IN E /\
        {v,q 0} IN E /\ {v,q i} IN E /\ {v,q j} IN E
        ==> graph_kuratowski_obstruction V E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "i_positive ij jn injective cycle_vertices cycle_edges \
    u_vertex v_vertex uv u_outside v_outside \
    edge_uv edge_u0 edge_ui edge_uj edge_v0 edge_vi edge_vj" THEN
  MP_TAC(ISPECL [`q:num->A`; `n:num`; `i:num`; `j:num`]
    CYCLIC_THREE_PATH_DATA) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "(q0i q0j qij) \
    (l1_positive l2_positive) \
    (p1_first p1_last p2_first p2_last) \
    (p0_injective p1_injective p2_injective) \
    p0_fresh_three p1_fresh_three p2_fresh_three" THEN
  SUBGOAL_THEN `(q:num->A) 0 IN cyclic_vertices q n`
  (LABEL_TAC "q0_cycle") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `0` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:num->A) i IN cyclic_vertices q n`
  (LABEL_TAC "qi_cycle") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `i:num` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(q:num->A) j IN cyclic_vertices q n`
  (LABEL_TAC "qj_cycle") THENL
   [REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `j:num` THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(q:num->A) 0`; `(q:num->A) i`; `(q:num->A) j`; `u:A`; `v:A`]
   FIVE_DISTINCT_GRAPH_FACTS) THEN
  ANTS_TAC THENL
   [ASM_MESON_TAC[];
    INTRO_TAC "source_graph source_edge0 source_edge1 source_edge2"] THEN
  SUBGOAL_THEN `{(q:num->A) 0,q i,q j,u,v} HAS_SIZE 5`
  (LABEL_TAC "source_size") THENL
   [REWRITE_TAC
     [HAS_SIZE_CONV
       `({(q:num->A) 0,q i,q j,u,v}:A->bool) HAS_SIZE 5`] THEN
    MAP_EVERY EXISTS_TAC
     [`(q:num->A) 0`; `(q:num->A) i`; `(q:num->A) j`; `u:A`; `v:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`q:num->A`; `n:num`; `i:num`; `j:num`; `u:A`; `v:A`]
   CYCLIC_THREE_PATH_FRESH_WITH_TWO_OUTSIDE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "p0_fresh p1_fresh p2_fresh" THEN
  SUBGOAL_THEN
   `graph_subdivision
      {(q:num->A) 0,q i,q j,u,v}
      (complete_graph_edges {q 0,q i,q j,u,v})
      (kuratowski_common_vertices q n i j u v)
      (kuratowski_common_edges q n i j u v)`
  (LABEL_TAC "subdivision") THENL
   [REWRITE_TAC
     [kuratowski_common_vertices; kuratowski_common_edges] THEN
    MATCH_MP_TAC GRAPH_SUBDIVISION_EXTEND_THREE_CYCLE_EDGES_BY_PATHS THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `kuratowski_common_vertices (q:num->A) n i j u v SUBSET V`
  (LABEL_TAC "vertices") THENL
   [REWRITE_TAC
     [kuratowski_common_vertices;
      three_path_extension_vertices; UNION_SUBSET] THEN
    REPEAT CONJ_TAC THENL
     [ASM SET_TAC[];
      MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `cyclic_vertices (q:num->A) n` THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC INDEXED_PREFIX_VERTICES_SUBSET_CYCLIC THEN
      ASM_ARITH_TAC;
      MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `cyclic_vertices (q:num->A) n` THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC INDEXED_OFFSET_VERTICES_SUBSET_CYCLIC THEN
      ASM_ARITH_TAC;
      MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `cyclic_vertices (q:num->A) n` THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC INDEXED_CLOSING_VERTICES_SUBSET_CYCLIC THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`q:num->A`; `i:num`; `n:num`]
    INDEXED_PREFIX_EDGES_SUBSET_CYCLIC) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(LABEL_TAC "path0_cycle")] THEN
  MP_TAC(ISPECL [`q:num->A`; `i:num`; `j - i:num`; `n:num`]
    INDEXED_OFFSET_EDGES_SUBSET_CYCLIC) THEN
  ANTS_TAC THENL
   [ASM_ARITH_TAC;
    DISCH_THEN(LABEL_TAC "path1_cycle")] THEN
  MP_TAC(ISPECL [`q:num->A`; `j:num`; `n:num`]
    INDEXED_CLOSING_EDGES_SUBSET_CYCLIC) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "path2_cycle") THEN
  SUBGOAL_THEN
   `complete_graph_edges {(q:num->A) 0,q i,q j,u,v} SUBSET
    {{q 0,q i},{q i,q j},{q j,q 0}} UNION E`
  (LABEL_TAC "source_edges") THENL
   [MATCH_MP_TAC COMPLETE_GRAPH_FIVE_SPOKES_REMAINDER_SUBSET THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `kuratowski_common_edges (q:num->A) n i j u v SUBSET E`
  (LABEL_TAC "edges") THENL
   [REWRITE_TAC[kuratowski_common_edges] THEN
    MATCH_MP_TAC THREE_PATH_EXTENSION_EDGES_SUBSET THEN
    EXISTS_TAC `cyclic_edges (q:num->A) n` THEN
    (fun (asl,_ as g) ->
      let th =
       CONJ (assoc "source_edges" asl)
        (CONJ (assoc "path0_cycle" asl)
         (CONJ (assoc "path1_cycle" asl)
          (CONJ (assoc "path2_cycle" asl)
                (assoc "cycle_edges" asl)))) in
      ACCEPT_TAC th g);
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `{(q:num->A) 0,q i,q j,u,v}`;
    `kuratowski_common_vertices (q:num->A) n i j u v`;
    `kuratowski_common_edges (q:num->A) n i j u v`]
   GRAPH_KURATOWSKI_OBSTRUCTION_K5_SUBGRAPH) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Cyclic spoke patterns for Kuratowski obstructions.                        *)
(* ------------------------------------------------------------------------- *)

let CYCLIC_OFFSET_ZERO = prove
 (`!q:num->A. !n a.
        a < n
        ==> (\i. q((i + a) MOD n)) 0 = q a`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "index") THEN
  BETA_TAC THEN
  REWRITE_TAC[ADD_CLAUSES] THEN
  ASM_SIMP_TAC[MOD_LT]);;

let CYCLIC_OFFSET_SUB = prove
 (`!q:num->A. !n a b.
        a <= b /\ b < n
        ==> (\i. q((i + a) MOD n)) (b - a) = q b`,
  REPEAT GEN_TAC THEN INTRO_TAC "order index" THEN
  BETA_TAC THEN
  USE_THEN "order"
   (fun th -> SUBST1_TAC
     (MATCH_MP (SPECL [`b:num`; `a:num`] SUB_ADD) th)) THEN
  ASM_SIMP_TAC[MOD_LT]);;

let GRAPH_KURATOWSKI_OBSTRUCTION_THREE_COMMON_SPOKES = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !q:num->A. !n a b c. !u v:A.
        a < b /\ b < c /\ c < n /\
        INJ q (cyclic_indices n) (:A) /\
        cyclic_vertices q n SUBSET V /\
        cyclic_edges q n SUBSET E /\
        u IN V /\ v IN V /\ ~(u = v) /\
        ~(u IN cyclic_vertices q n) /\
        ~(v IN cyclic_vertices q n) /\
        {u,v} IN E /\
        {u,q a} IN E /\ {u,q b} IN E /\ {u,q c} IN E /\
        {v,q a} IN E /\ {v,q b} IN E /\ {v,q c} IN E
        ==> graph_kuratowski_obstruction V E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "ab bc cn injective cycle_vertices cycle_edges \
    u_vertex v_vertex uv u_outside v_outside edge_uv \
    edge_ua edge_ub edge_uc edge_va edge_vb edge_vc" THEN
  SUBGOAL_THEN
   `INJ (\i. (q:num->A)((i + a) MOD n))
        (cyclic_indices n) (:A)`
  (LABEL_TAC "offset_injective") THENL
   [MATCH_MP_TAC INJ_CYCLIC_OFFSET THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(\i. (q:num->A)((i + a) MOD n)) 0 = q a /\
    (\i. q((i + a) MOD n)) (b - a) = q b /\
    (\i. q((i + a) MOD n)) (c - a) = q c`
  (CONJUNCTS_THEN2 (LABEL_TAC "offset_a")
   (CONJUNCTS_THEN2 (LABEL_TAC "offset_b")
    (LABEL_TAC "offset_c"))) THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC CYCLIC_OFFSET_ZERO THEN ASM_ARITH_TAC;
      MATCH_MP_TAC CYCLIC_OFFSET_SUB THEN ASM_ARITH_TAC;
      MATCH_MP_TAC CYCLIC_OFFSET_SUB THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `\i. (q:num->A)((i + a) MOD n)`; `n:num`;
    `b - a:num`; `c - a:num`; `u:A`; `v:A`]
   GRAPH_KURATOWSKI_OBSTRUCTION_COMMON_SPOKES) THEN
  ASM_REWRITE_TAC
   [CYCLIC_VERTICES_OFFSET; CYCLIC_EDGES_OFFSET] THEN
  ASM_ARITH_TAC);;

let GRAPH_KURATOWSKI_OBSTRUCTION_FOUR_ALTERNATING_SPOKES = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !q:num->A. !n a b c d. !u v:A.
        a < b /\ b < c /\ c < d /\ d < n /\
        INJ q (cyclic_indices n) (:A) /\
        cyclic_vertices q n SUBSET V /\
        cyclic_edges q n SUBSET E /\
        u IN V /\ v IN V /\ ~(u = v) /\
        ~(u IN cyclic_vertices q n) /\
        ~(v IN cyclic_vertices q n) /\
        {u,v} IN E /\
        {u,q a} IN E /\ {u,q c} IN E /\
        {v,q b} IN E /\ {v,q d} IN E
        ==> graph_kuratowski_obstruction V E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "ab bc cd dn injective cycle_vertices cycle_edges \
    u_vertex v_vertex uv u_outside v_outside \
    edge_uv edge_ua edge_uc edge_vb edge_vd" THEN
  SUBGOAL_THEN
   `INJ (\i. (q:num->A)((i + a) MOD n))
        (cyclic_indices n) (:A)`
  (LABEL_TAC "offset_injective") THENL
   [MATCH_MP_TAC INJ_CYCLIC_OFFSET THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(\i. (q:num->A)((i + a) MOD n)) 0 = q a /\
    (\i. q((i + a) MOD n)) (b - a) = q b /\
    (\i. q((i + a) MOD n)) (c - a) = q c /\
    (\i. q((i + a) MOD n)) (d - a) = q d`
  (CONJUNCTS_THEN2 (LABEL_TAC "offset_a")
   (CONJUNCTS_THEN2 (LABEL_TAC "offset_b")
    (CONJUNCTS_THEN2 (LABEL_TAC "offset_c")
     (LABEL_TAC "offset_d")))) THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC CYCLIC_OFFSET_ZERO THEN ASM_ARITH_TAC;
      MATCH_MP_TAC CYCLIC_OFFSET_SUB THEN ASM_ARITH_TAC;
      MATCH_MP_TAC CYCLIC_OFFSET_SUB THEN ASM_ARITH_TAC;
      MATCH_MP_TAC CYCLIC_OFFSET_SUB THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `\i. (q:num->A)((i + a) MOD n)`; `n:num`;
    `b - a:num`; `c - a:num`; `d - a:num`; `u:A`; `v:A`]
   GRAPH_KURATOWSKI_OBSTRUCTION_ALTERNATING_SPOKES) THEN
  ASM_REWRITE_TAC
   [CYCLIC_VERTICES_OFFSET; CYCLIC_EDGES_OFFSET] THEN
  ASM_ARITH_TAC);;

let GRAPH_KURATOWSKI_FREE_SPOKE_PATTERNS = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !q:num->A. !n. !u v:A.
        INJ q (cyclic_indices n) (:A) /\
        cyclic_vertices q n SUBSET V /\
        cyclic_edges q n SUBSET E /\
        u IN V /\ v IN V /\ ~(u = v) /\
        ~(u IN cyclic_vertices q n) /\
        ~(v IN cyclic_vertices q n) /\
        {u,v} IN E /\
        ~graph_kuratowski_obstruction V E
        ==> (!a b c.
               a < b /\ b < c /\ c < n
               ==> ~({u,q a} IN E /\ {u,q b} IN E /\ {u,q c} IN E /\
                      {v,q a} IN E /\ {v,q b} IN E /\ {v,q c} IN E)) /\
            (!a b c d.
               a < b /\ b < c /\ c < d /\ d < n
               ==> ~({u,q a} IN E /\ {u,q c} IN E /\
                      {v,q b} IN E /\ {v,q d} IN E)) /\
            (!a b c d.
               a < b /\ b < c /\ c < d /\ d < n
               ==> ~({v,q a} IN E /\ {v,q c} IN E /\
                      {u,q b} IN E /\ {u,q d} IN E))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "injective cycle_vertices cycle_edges \
    u_vertex v_vertex uv u_outside v_outside edge_uv unobstructed" THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`a:num`; `b:num`; `c:num`] THEN
    INTRO_TAC "ab bc cn" THEN
    INTRO_TAC
     "edge_ua edge_ub edge_uc edge_va edge_vb edge_vc" THEN
    USE_THEN "unobstructed" (MATCH_MP_TAC o NOT_ELIM) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `a:num`; `b:num`; `c:num`; `u:A`; `v:A`]
     GRAPH_KURATOWSKI_OBSTRUCTION_THREE_COMMON_SPOKES) THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`a:num`; `b:num`; `c:num`; `d:num`] THEN
    INTRO_TAC "ab bc cd dn" THEN
    INTRO_TAC "edge_ua edge_uc edge_vb edge_vd" THEN
    USE_THEN "unobstructed" (MATCH_MP_TAC o NOT_ELIM) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `a:num`; `b:num`; `c:num`; `d:num`; `u:A`; `v:A`]
     GRAPH_KURATOWSKI_OBSTRUCTION_FOUR_ALTERNATING_SPOKES) THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`a:num`; `b:num`; `c:num`; `d:num`] THEN
    INTRO_TAC "ab bc cd dn" THEN
    INTRO_TAC "edge_va edge_vc edge_ub edge_ud" THEN
    USE_THEN "unobstructed" (MATCH_MP_TAC o NOT_ELIM) THEN
    SUBGOAL_THEN `~((v:A) = u)` (LABEL_TAC "vu") THENL
     [ONCE_REWRITE_TAC[EQ_SYM_EQ] THEN USE_THEN "uv" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `{v:A,u} IN E` (LABEL_TAC "edge_vu") THENL
     [ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN USE_THEN "edge_uv" ACCEPT_TAC;
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `a:num`; `b:num`; `c:num`; `d:num`; `v:A`; `u:A`]
     GRAPH_KURATOWSKI_OBSTRUCTION_FOUR_ALTERNATING_SPOKES) THEN
    ASM_REWRITE_TAC[]]);;

let LINEAR_SPOKE_INTERVAL = prove
 (`!P Q:num->bool. !n.
        P 0 /\ ~Q 0 /\
        (!i. i < n ==> P i \/ Q i) /\
        (?i. i < n /\ Q i) /\
        (!a b c d.
            a < b /\ b < c /\ c < d /\ d < n
            ==> ~(P a /\ Q b /\ P c /\ Q d))
        ==> ?a b.
              0 < a /\ a <= b /\ b < n /\
              (!i. i < n ==> (Q i <=> a <= i /\ i <= b)) /\
              (!i. a < i /\ i < b ==> ~P i) /\
              (!i. i < n /\ (i < a \/ b < i) ==> P i)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "P0 not_Q0 cover Q_nonempty no_alternation" THEN
  MP_TAC(SPEC `\i:num. i < n /\ Q i` num_WOP) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@a. (a_index Qa) a_least" THEN
  SUBGOAL_THEN
   `(?i. i < n /\ (Q:num->bool) i) /\
    (?M. !i. i < n /\ Q i ==> i <= M)`
  (LABEL_TAC "Q_bounded") THENL
   [CONJ_TAC THENL
     [USE_THEN "Q_nonempty" ACCEPT_TAC;
      EXISTS_TAC `n:num` THEN
      X_GEN_TAC `i:num` THEN REWRITE_TAC[] THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  USE_THEN "Q_bounded" MP_TAC THEN
  REWRITE_TAC[num_MAX] THEN
  INTRO_TAC "@b. (b_index Qb) b_greatest" THEN
  SUBGOAL_THEN `0 < (a:num)` (LABEL_TAC "a_positive") THENL
   [MATCH_MP_TAC (ARITH_RULE `~(a = 0) ==> 0 < a`) THEN
    DISCH_THEN(LABEL_TAC "a_zero") THEN
    USE_THEN "not_Q0" (fun nth ->
      USE_THEN "Qa" (fun qth ->
        USE_THEN "a_zero" (fun ath ->
          CONTR_TAC(MP (NOT_ELIM nth) (SUBS [ath] qth)))));
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:num) <= b` (LABEL_TAC "ab") THENL
   [USE_THEN "b_greatest" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i < n ==> (Q i <=> (a:num) <= i /\ i <= b)`
  (LABEL_TAC "Q_interval") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "i_index") THEN
     EQ_TAC THENL
     [DISCH_THEN(LABEL_TAC "Qi") THEN
      CONJ_TAC THENL
       [ASM_CASES_TAC `(i:num) < a` THENL
         [USE_THEN "a_least" (MP_TAC o SPEC `i:num`) THEN
          ASM_MESON_TAC[];
          ASM_ARITH_TAC];
        USE_THEN "b_greatest" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
      INTRO_TAC "ai ib" THEN
      ASM_CASES_TAC `(Q:num->bool) i` THENL
       [ASM_REWRITE_TAC[];
        POP_ASSUM(LABEL_TAC "not_Qi")] THEN
      SUBGOAL_THEN `(P:num->bool) i` (LABEL_TAC "Pi") THENL
       [USE_THEN "cover" (MP_TAC o SPEC `i:num`) THEN
        ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `~((i:num) = a) /\ ~(i = b)`
      (CONJUNCTS_THEN2 (LABEL_TAC "not_ia") (LABEL_TAC "not_ib")) THENL
       [ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `0 < (a:num) /\ a < i /\ i < b /\ b < n`
      (LABEL_TAC "alternating_order") THENL
       [ASM_ARITH_TAC;
        ALL_TAC] THEN
      USE_THEN "no_alternation"
       (MP_TAC o SPECL [`0`; `a:num`; `i:num`; `b:num`]) THEN
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. (a:num) < i /\ i < b ==> ~(P:num->bool) i`
  (LABEL_TAC "P_not_interior") THENL
   [X_GEN_TAC `i:num` THEN INTRO_TAC "ai ib" THEN
    DISCH_THEN(LABEL_TAC "Pi") THEN
    SUBGOAL_THEN `(i:num) < n` (LABEL_TAC "i_index") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(Q:num->bool) i` (LABEL_TAC "Qi") THENL
     [USE_THEN "Q_interval" (MP_TAC o SPEC `i:num`) THEN
      ASM_MESON_TAC[LT_IMP_LE];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `0 < (a:num) /\ a < i /\ i < b /\ b < n`
    (LABEL_TAC "alternating_order") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "no_alternation"
     (MP_TAC o SPECL [`0`; `a:num`; `i:num`; `b:num`]) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i < n /\ (i < a \/ b < i) ==> (P:num->bool) i`
  (LABEL_TAC "P_outside") THENL
   [X_GEN_TAC `i:num` THEN INTRO_TAC "i_index outside" THEN
    ASM_CASES_TAC `(P:num->bool) i` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(Q:num->bool) i` (LABEL_TAC "Qi") THENL
     [USE_THEN "cover" (MP_TAC o SPEC `i:num`) THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(a:num) <= i /\ i <= b`
    (CONJUNCTS_THEN2 (LABEL_TAC "ai") (LABEL_TAC "ib")) THENL
     [USE_THEN "Q_interval" (MP_TAC o SPEC `i:num`) THEN
      ASM_MESON_TAC[];
      ASM_ARITH_TAC];
    MAP_EVERY EXISTS_TAC [`a:num`; `b:num`] THEN ASM_REWRITE_TAC[]]);;

let CYCLIC_OFFSET_PREDICATE_NONEMPTY = prove
 (`!Q:num->bool. !n k.
        (?j. j < n /\ Q j)
        ==> ?i. i < n /\ Q((i + k) MOD n)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "@j. j_index Qj" THEN
  MP_TAC(MATCH_MP PERMUTES_SURJECTIVE
   (SPECL [`n:num`; `k:num`] PERMUTES_CYCLIC_N)) THEN
  DISCH_THEN(MP_TAC o SPEC `j:num`) THEN
  INTRO_TAC "@i. image" THEN
  SUBGOAL_THEN `(i:num) < n` (LABEL_TAC "i_index") THENL
   [USE_THEN "image" (fun eth ->
      USE_THEN "j_index" (fun jth ->
        ACCEPT_TAC(EQ_MP
         (REWRITE_RULE[cyclic_indices; IN_ELIM_THM]
          (SPEC `i:num`
           (MATCH_MP PERMUTES_IN_IMAGE
            (SPECL [`n:num`; `k:num`] PERMUTES_CYCLIC_N))))
         (SUBS [SYM(BETA_RULE eth)] jth))));
    EXISTS_TAC `i:num` THEN CONJ_TAC THENL
     [USE_THEN "i_index" ACCEPT_TAC;
      USE_THEN "image" (fun eth ->
        USE_THEN "i_index" (fun ith ->
          USE_THEN "Qj" (fun qth ->
            ACCEPT_TAC
             (SUBS [SYM(REWRITE_RULE[ith] (BETA_RULE eth))] qth))))]]);;

let SPARSE_SPOKE_EXCLUSIVE_POINT = prove
 (`!P Q:num->bool. !n.
        (?a b c.
            a < b /\ b < c /\ c < n /\
            (P a \/ Q a) /\ (P b \/ Q b) /\ (P c \/ Q c)) /\
        (!a b c.
            a < b /\ b < c /\ c < n
            ==> ~((P a /\ Q a) /\ (P b /\ Q b) /\ (P c /\ Q c)))
        ==> (?k. k < n /\ P k /\ ~Q k) \/
            (?k. k < n /\ Q k /\ ~P k)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "(@a b c. ab bc cn support_a support_b support_c) no_three" THEN
  ASM_CASES_TAC `?k. k < n /\ (P:num->bool) k /\ ~Q k` THENL
   [ASM_REWRITE_TAC[];
    POP_ASSUM(LABEL_TAC "no_P_exclusive")] THEN
  ASM_CASES_TAC `?k. k < n /\ (Q:num->bool) k /\ ~P k` THENL
   [ASM_REWRITE_TAC[];
    POP_ASSUM(LABEL_TAC "no_Q_exclusive")] THEN
  SUBGOAL_THEN
   `!i. i < n /\ ((P:num->bool) i \/ (Q:num->bool) i)
        ==> P i /\ Q i`
  (LABEL_TAC "common") THENL
   [X_GEN_TAC `i:num` THEN INTRO_TAC "index support" THEN
    REMOVE_THEN "no_three" (K ALL_TAC) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(P:num->bool) a /\ (Q:num->bool) a`
  (CONJUNCTS_THEN2 (LABEL_TAC "Pa") (LABEL_TAC "Qa")) THENL
   [USE_THEN "common" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(P:num->bool) b /\ (Q:num->bool) b`
  (CONJUNCTS_THEN2 (LABEL_TAC "Pb") (LABEL_TAC "Qb")) THENL
   [USE_THEN "common" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(P:num->bool) c /\ (Q:num->bool) c`
  (CONJUNCTS_THEN2 (LABEL_TAC "Pc") (LABEL_TAC "Qc")) THENL
   [USE_THEN "common" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `F ==> p`) THEN
  USE_THEN "no_three" (MP_TAC o SPECL [`a:num`; `b:num`; `c:num`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(MATCH_MP_TAC o NOT_ELIM)] THEN
  ASM_REWRITE_TAC[]);;

let SPOKE_EXCLUSIVE_POINT = prove
 (`!P Q:num->bool. !n.
        3 <= n /\
        (!i. i < n ==> P i \/ Q i) /\
        (!a b c.
            a < b /\ b < c /\ c < n
            ==> ~((P a /\ Q a) /\ (P b /\ Q b) /\ (P c /\ Q c)))
        ==> (?k. k < n /\ P k /\ ~Q k) \/
            (?k. k < n /\ Q k /\ ~P k)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "size cover no_three" THEN
  MATCH_MP_TAC(SPECL
   [`P:num->bool`; `Q:num->bool`; `n:num`]
   SPARSE_SPOKE_EXCLUSIVE_POINT) THEN
  CONJ_TAC THENL
   [MAP_EVERY EXISTS_TAC [`0`; `1`; `2`] THEN
    REPEAT CONJ_TAC THENL
     [ASM_ARITH_TAC;
      ASM_ARITH_TAC;
      ASM_ARITH_TAC;
      USE_THEN "cover" (MATCH_MP_TAC o SPEC `0:num`) THEN ASM_ARITH_TAC;
      USE_THEN "cover" (MATCH_MP_TAC o SPEC `1:num`) THEN ASM_ARITH_TAC;
      USE_THEN "cover" (MATCH_MP_TAC o SPEC `2:num`) THEN ASM_ARITH_TAC];
    USE_THEN "no_three" ACCEPT_TAC]);;

let CYCLIC_SPOKE_INTERVAL = prove
 (`!P Q:num->bool. !n.
        ((?k. k < n /\ P k /\ ~Q k) \/
         (?k. k < n /\ Q k /\ ~P k)) /\
        (!i. i < n ==> P i \/ Q i) /\
        (?i. i < n /\ P i) /\
        (?i. i < n /\ Q i) /\
        (!k a b c d.
            a < b /\ b < c /\ c < d /\ d < n
            ==> ~(P((a + k) MOD n) /\ Q((b + k) MOD n) /\
                  P((c + k) MOD n) /\ Q((d + k) MOD n))) /\
        (!k a b c d.
            a < b /\ b < c /\ c < d /\ d < n
            ==> ~(Q((a + k) MOD n) /\ P((b + k) MOD n) /\
                  Q((c + k) MOD n) /\ P((d + k) MOD n)))
        ==> (?k a b.
                k < n /\ P k /\ ~Q k /\
                0 < a /\ a <= b /\ b < n /\
                (!i. i < n
                     ==> (Q((i + k) MOD n) <=> a <= i /\ i <= b)) /\
                (!i. a < i /\ i < b ==> ~P((i + k) MOD n)) /\
                (!i. i < n /\ (i < a \/ b < i)
                     ==> P((i + k) MOD n))) \/
            (?k a b.
                k < n /\ Q k /\ ~P k /\
                0 < a /\ a <= b /\ b < n /\
                (!i. i < n
                     ==> (P((i + k) MOD n) <=> a <= i /\ i <= b)) /\
                (!i. a < i /\ i < b ==> ~Q((i + k) MOD n)) /\
                (!i. i < n /\ (i < a \/ b < i)
                     ==> Q((i + k) MOD n)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "exclusive cover P_nonempty Q_nonempty \
    no_PQPQ no_QPQP" THEN
  USE_THEN "exclusive"
   (DISJ_CASES_THEN2
    (X_CHOOSE_THEN `k:num`
     (CONJUNCTS_THEN2 (LABEL_TAC "k_index")
      (CONJUNCTS_THEN2 (LABEL_TAC "Pk") (LABEL_TAC "not_Qk"))))
    (X_CHOOSE_THEN `k:num`
      (CONJUNCTS_THEN2 (LABEL_TAC "k_index")
      (CONJUNCTS_THEN2 (LABEL_TAC "Qk") (LABEL_TAC "not_Pk"))))) THENL
   [MP_TAC(SPECL
     [`\i:num. (P:num->bool)((i + k) MOD n)`;
      `\i:num. (Q:num->bool)((i + k) MOD n)`; `n:num`]
    LINEAR_SPOKE_INTERVAL) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [BETA_TAC THEN REWRITE_TAC[ADD_CLAUSES] THEN
        USE_THEN "k_index"
         (fun kth -> REWRITE_TAC[MATCH_MP MOD_LT kth]) THEN
        USE_THEN "Pk" ACCEPT_TAC;
        BETA_TAC THEN REWRITE_TAC[ADD_CLAUSES] THEN
        USE_THEN "k_index"
         (fun kth -> REWRITE_TAC[MATCH_MP MOD_LT kth]) THEN
        USE_THEN "not_Qk" ACCEPT_TAC;
        X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "i_index") THEN
        BETA_TAC THEN
        USE_THEN "cover"
         (MATCH_MP_TAC o SPEC `((i + k) MOD n)`) THEN
        REWRITE_TAC[MOD_LT_EQ_LT] THEN ASM_ARITH_TAC;
        BETA_TAC THEN
        MATCH_MP_TAC CYCLIC_OFFSET_PREDICATE_NONEMPTY THEN
        USE_THEN "Q_nonempty" ACCEPT_TAC;
        MAP_EVERY X_GEN_TAC
         [`a:num`; `b:num`; `c:num`; `d:num`] THEN
        DISCH_THEN(LABEL_TAC "order") THEN
        BETA_TAC THEN
        USE_THEN "no_PQPQ"
         (MATCH_MP_TAC o SPECL
           [`k:num`; `a:num`; `b:num`; `c:num`; `d:num`]) THEN
        USE_THEN "order" ACCEPT_TAC];
      INTRO_TAC
       "@a b. a_positive ab b_index Q_interval \
              not_P_interior P_outside"] THEN
    DISJ1_TAC THEN
    MAP_EVERY EXISTS_TAC [`k:num`; `a:num`; `b:num`] THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "Q_interval" (ACCEPT_TAC o BETA_RULE);
      USE_THEN "not_P_interior" (ACCEPT_TAC o BETA_RULE);
      USE_THEN "P_outside" (ACCEPT_TAC o BETA_RULE)];
    MP_TAC(SPECL
     [`\i:num. (Q:num->bool)((i + k) MOD n)`;
      `\i:num. (P:num->bool)((i + k) MOD n)`; `n:num`]
    LINEAR_SPOKE_INTERVAL) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [BETA_TAC THEN REWRITE_TAC[ADD_CLAUSES] THEN
        USE_THEN "k_index"
         (fun kth -> REWRITE_TAC[MATCH_MP MOD_LT kth]) THEN
        USE_THEN "Qk" ACCEPT_TAC;
        BETA_TAC THEN REWRITE_TAC[ADD_CLAUSES] THEN
        USE_THEN "k_index"
         (fun kth -> REWRITE_TAC[MATCH_MP MOD_LT kth]) THEN
        USE_THEN "not_Pk" ACCEPT_TAC;
        X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "i_index") THEN
        BETA_TAC THEN ONCE_REWRITE_TAC[DISJ_SYM] THEN
        USE_THEN "cover"
         (MATCH_MP_TAC o SPEC `((i + k) MOD n)`) THEN
        REWRITE_TAC[MOD_LT_EQ_LT] THEN ASM_ARITH_TAC;
        BETA_TAC THEN
        MATCH_MP_TAC CYCLIC_OFFSET_PREDICATE_NONEMPTY THEN
        USE_THEN "P_nonempty" ACCEPT_TAC;
        MAP_EVERY X_GEN_TAC
         [`a:num`; `b:num`; `c:num`; `d:num`] THEN
        DISCH_THEN(LABEL_TAC "order") THEN
        BETA_TAC THEN
        USE_THEN "no_QPQP"
         (MATCH_MP_TAC o SPECL
           [`k:num`; `a:num`; `b:num`; `c:num`; `d:num`]) THEN
        USE_THEN "order" ACCEPT_TAC];
      INTRO_TAC
       "@a b. a_positive ab b_index P_interval \
              not_Q_interior Q_outside"] THEN
    DISJ2_TAC THEN
    MAP_EVERY EXISTS_TAC [`k:num`; `a:num`; `b:num`] THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "P_interval" (ACCEPT_TAC o BETA_RULE);
      USE_THEN "not_Q_interior" (ACCEPT_TAC o BETA_RULE);
      USE_THEN "Q_outside" (ACCEPT_TAC o BETA_RULE)]]);;

let GRAPH_KURATOWSKI_FREE_ROTATED_SPOKE_PATTERNS = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !q:num->A. !n. !u v:A.
        INJ q (cyclic_indices n) (:A) /\
        cyclic_vertices q n SUBSET V /\
        cyclic_edges q n SUBSET E /\
        u IN V /\ v IN V /\ ~(u = v) /\
        ~(u IN cyclic_vertices q n) /\
        ~(v IN cyclic_vertices q n) /\
        {u,v} IN E /\
        ~graph_kuratowski_obstruction V E
        ==> (!k a b c d.
               a < b /\ b < c /\ c < d /\ d < n
               ==> ~({u,q((a + k) MOD n)} IN E /\
                     {v,q((b + k) MOD n)} IN E /\
                     {u,q((c + k) MOD n)} IN E /\
                     {v,q((d + k) MOD n)} IN E)) /\
            (!k a b c d.
               a < b /\ b < c /\ c < d /\ d < n
               ==> ~({v,q((a + k) MOD n)} IN E /\
                     {u,q((b + k) MOD n)} IN E /\
                     {v,q((c + k) MOD n)} IN E /\
                     {u,q((d + k) MOD n)} IN E))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "injective cycle_vertices cycle_edges \
    u_vertex v_vertex uv u_outside v_outside edge_uv unobstructed" THEN
  CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC
     [`k:num`; `a:num`; `b:num`; `c:num`; `d:num`] THEN
    DISCH_THEN(LABEL_TAC "order") THEN
    SUBGOAL_THEN
     `INJ (\i. (q:num->A)((i + k) MOD n))
          (cyclic_indices n) (:A)`
    (LABEL_TAC "offset_injective") THENL
     [MATCH_MP_TAC INJ_CYCLIC_OFFSET THEN
      USE_THEN "injective" ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `\i:num. (q:num->A)((i + k) MOD n)`;
      `n:num`; `u:A`; `v:A`]
     GRAPH_KURATOWSKI_FREE_SPOKE_PATTERNS) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "offset_injective" ACCEPT_TAC;
        REWRITE_TAC[CYCLIC_VERTICES_OFFSET] THEN
        USE_THEN "cycle_vertices" ACCEPT_TAC;
        REWRITE_TAC[CYCLIC_EDGES_OFFSET] THEN
        USE_THEN "cycle_edges" ACCEPT_TAC;
        USE_THEN "u_vertex" ACCEPT_TAC;
        USE_THEN "v_vertex" ACCEPT_TAC;
        USE_THEN "uv" ACCEPT_TAC;
        REWRITE_TAC[CYCLIC_VERTICES_OFFSET] THEN
        USE_THEN "u_outside" ACCEPT_TAC;
        REWRITE_TAC[CYCLIC_VERTICES_OFFSET] THEN
        USE_THEN "v_outside" ACCEPT_TAC;
        USE_THEN "edge_uv" ACCEPT_TAC;
        USE_THEN "unobstructed" ACCEPT_TAC];
      INTRO_TAC "_ no_alternation _"] THEN
    MATCH_MP_TAC(TAUT
     `~(ua /\ uc /\ vb /\ vd)
      ==> ~(ua /\ vb /\ uc /\ vd)`) THEN
    USE_THEN "no_alternation" (fun nth ->
      MATCH_MP_TAC(BETA_RULE
       (SPECL [`a:num`; `b:num`; `c:num`; `d:num`] nth))) THEN
    USE_THEN "order" ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC
     [`k:num`; `a:num`; `b:num`; `c:num`; `d:num`] THEN
    DISCH_THEN(LABEL_TAC "order") THEN
    SUBGOAL_THEN
     `INJ (\i. (q:num->A)((i + k) MOD n))
          (cyclic_indices n) (:A)`
    (LABEL_TAC "offset_injective") THENL
     [MATCH_MP_TAC INJ_CYCLIC_OFFSET THEN
      USE_THEN "injective" ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `\i:num. (q:num->A)((i + k) MOD n)`;
      `n:num`; `u:A`; `v:A`]
     GRAPH_KURATOWSKI_FREE_SPOKE_PATTERNS) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "offset_injective" ACCEPT_TAC;
        REWRITE_TAC[CYCLIC_VERTICES_OFFSET] THEN
        USE_THEN "cycle_vertices" ACCEPT_TAC;
        REWRITE_TAC[CYCLIC_EDGES_OFFSET] THEN
        USE_THEN "cycle_edges" ACCEPT_TAC;
        USE_THEN "u_vertex" ACCEPT_TAC;
        USE_THEN "v_vertex" ACCEPT_TAC;
        USE_THEN "uv" ACCEPT_TAC;
        REWRITE_TAC[CYCLIC_VERTICES_OFFSET] THEN
        USE_THEN "u_outside" ACCEPT_TAC;
        REWRITE_TAC[CYCLIC_VERTICES_OFFSET] THEN
        USE_THEN "v_outside" ACCEPT_TAC;
        USE_THEN "edge_uv" ACCEPT_TAC;
        USE_THEN "unobstructed" ACCEPT_TAC];
      INTRO_TAC "_ _ no_alternation"] THEN
    MATCH_MP_TAC(TAUT
     `~(va /\ vc /\ ub /\ ud)
      ==> ~(va /\ ub /\ vc /\ ud)`) THEN
    USE_THEN "no_alternation" (fun nth ->
      MATCH_MP_TAC(BETA_RULE
       (SPECL [`a:num`; `b:num`; `c:num`; `d:num`] nth))) THEN
    USE_THEN "order" ACCEPT_TAC]);;

let GRAPH_KURATOWSKI_FREE_SPOKE_INTERVAL = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !q:num->A. !n. !u v:A.
        3 <= n /\
        INJ q (cyclic_indices n) (:A) /\
        cyclic_vertices q n SUBSET V /\
        cyclic_edges q n SUBSET E /\
        u IN V /\ v IN V /\ ~(u = v) /\
        ~(u IN cyclic_vertices q n) /\
        ~(v IN cyclic_vertices q n) /\
        {u,v} IN E /\
        (!i. i < n ==> {u,q i} IN E \/ {v,q i} IN E) /\
        (?i. i < n /\ {u,q i} IN E) /\
        (?i. i < n /\ {v,q i} IN E) /\
        ~graph_kuratowski_obstruction V E
        ==> (?k a b.
                k < n /\ {u,q k} IN E /\ ~({v,q k} IN E) /\
                0 < a /\ a <= b /\ b < n /\
                (!i. i < n
                     ==> ({v,q((i + k) MOD n)} IN E <=>
                          a <= i /\ i <= b)) /\
                (!i. a < i /\ i < b
                     ==> ~({u,q((i + k) MOD n)} IN E)) /\
                (!i. i < n /\ (i < a \/ b < i)
                     ==> {u,q((i + k) MOD n)} IN E)) \/
            (?k a b.
                k < n /\ {v,q k} IN E /\ ~({u,q k} IN E) /\
                0 < a /\ a <= b /\ b < n /\
                (!i. i < n
                     ==> ({u,q((i + k) MOD n)} IN E <=>
                          a <= i /\ i <= b)) /\
                (!i. a < i /\ i < b
                     ==> ~({v,q((i + k) MOD n)} IN E)) /\
                (!i. i < n /\ (i < a \/ b < i)
                     ==> {v,q((i + k) MOD n)} IN E))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "size injective cycle_vertices cycle_edges \
    u_vertex v_vertex uv u_outside v_outside edge_uv \
    cover u_nonempty v_nonempty unobstructed" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `q:num->A`; `n:num`; `u:A`; `v:A`]
   GRAPH_KURATOWSKI_FREE_SPOKE_PATTERNS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN
    FIRST_X_ASSUM ACCEPT_TAC;
    INTRO_TAC "no_three _ _"] THEN
  SUBGOAL_THEN
   `(?k:num. k < n /\ {u:A,q k} IN E /\ ~({v,q k} IN E)) \/
    (?k:num. k < n /\ {v,q k} IN E /\ ~({u,q k} IN E))`
  (LABEL_TAC "exclusive") THENL
   [SUBGOAL_THEN
     `(?a b c:num.
          a < b /\ b < c /\ c < n /\
          ({u:A,q a} IN E \/ {v,q a} IN E) /\
          ({u,q b} IN E \/ {v,q b} IN E) /\
          ({u,q c} IN E \/ {v,q c} IN E)) /\
      (!a b c:num.
          a < b /\ b < c /\ c < n
          ==> ~(({u,q a} IN E /\ {v,q a} IN E) /\
                ({u,q b} IN E /\ {v,q b} IN E) /\
                {u,q c} IN E /\ {v,q c} IN E))`
    (LABEL_TAC "sparse_hypotheses") THENL
     [CONJ_TAC THENL
       [MAP_EVERY EXISTS_TAC [`0`; `1`; `2`] THEN
        REPEAT CONJ_TAC THENL
         [ASM_ARITH_TAC;
          ASM_ARITH_TAC;
          ASM_ARITH_TAC;
          USE_THEN "cover" (MATCH_MP_TAC o SPEC `0:num`) THEN
          ASM_ARITH_TAC;
          USE_THEN "cover" (MATCH_MP_TAC o SPEC `1:num`) THEN
          ASM_ARITH_TAC;
          USE_THEN "cover" (MATCH_MP_TAC o SPEC `2:num`) THEN
          ASM_ARITH_TAC];
        MAP_EVERY X_GEN_TAC [`a:num`; `b:num`; `c:num`] THEN
        DISCH_THEN(LABEL_TAC "order") THEN
        MATCH_MP_TAC(TAUT
         `~(pa /\ pb /\ pc /\ qa /\ qb /\ qc)
          ==> ~((pa /\ qa) /\ (pb /\ qb) /\ pc /\ qc)`) THEN
        USE_THEN "no_three"
         (MATCH_MP_TAC o SPECL [`a:num`; `b:num`; `c:num`]) THEN
        USE_THEN "order" ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "sparse_hypotheses" (fun hth ->
      let rth =
        MP
         (BETA_RULE(ISPECL
          [`\i:num. ({u:A,q i}:A->bool) IN E`;
           `\i:num. ({v:A,q i}:A->bool) IN E`; `n:num`]
          SPARSE_SPOKE_EXCLUSIVE_POINT))
         hth in
      ACCEPT_TAC rth);
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `q:num->A`; `n:num`; `u:A`; `v:A`]
   GRAPH_KURATOWSKI_FREE_ROTATED_SPOKE_PATTERNS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN
    FIRST_X_ASSUM ACCEPT_TAC;
    INTRO_TAC "no_PQPQ no_QPQP"] THEN
  MATCH_MP_TAC(BETA_RULE(ISPECL
   [`\i:num. ({u:A,q i}:A->bool) IN E`;
    `\i:num. ({v:A,q i}:A->bool) IN E`; `n:num`]
   CYCLIC_SPOKE_INTERVAL)) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "exclusive" ACCEPT_TAC;
    USE_THEN "cover" ACCEPT_TAC;
    USE_THEN "u_nonempty" ACCEPT_TAC;
    USE_THEN "v_nonempty" ACCEPT_TAC;
    USE_THEN "no_PQPQ" ACCEPT_TAC;
    USE_THEN "no_QPQP" ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* Facial walks of finite graph rotation systems.                            *)
(*                                                                           *)
(* A face is an orbit of the face-successor permutation.  The following      *)
(* lemmas package that orbit as a numerically indexed closed walk.           *)
(* Injectivity of the vertices is deliberately separate: it additionally     *)
(* requires planarity and 2-connectivity, whereas the enumeration below is   *)
(* purely finite and combinatorial.                                          *)
(* ------------------------------------------------------------------------- *)

let GRAPH_FACE_CYCLIC_WALK = prove
 (`!V E r d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        d IN graph_darts E
        ==> ?q:num->A.
              0 < CARD(graph_face E r d) /\
              q 0 = FST d /\
              q 1 = SND d /\
              (!i. i < CARD(graph_face E r d)
                   ==> ITER i (graph_face_successor E r) d =
                       cyclic_dart q (CARD(graph_face E r d)) i) /\
              INJ (cyclic_dart q (CARD(graph_face E r d)))
                  (cyclic_indices (CARD(graph_face E r d))) (:A#A) /\
              graph_face E r d =
                cyclic_darts q (CARD(graph_face E r d)) /\
              cyclic_edges q (CARD(graph_face E r d)) SUBSET E /\
              cyclic_face_successors
                E r q (CARD(graph_face E r d))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation dart" THEN
  ABBREV_TAC
   `f:(A#A)->A#A =
      graph_face_successor (E:(A->bool)->bool) (r:(A#A)->A#A)` THEN
  POP_ASSUM(LABEL_TAC "f_definition") THEN
  ABBREV_TAC `s:(A#A)->bool = graph_face E r d` THEN
  POP_ASSUM(LABEL_TAC "s_definition") THEN
  ABBREV_TAC `n = CARD(s:(A#A)->bool)` THEN
  POP_ASSUM(LABEL_TAC "n_definition") THEN
  ABBREV_TAC
   `g:(A#A)->A#A = restricted_permutation f s` THEN
  POP_ASSUM(LABEL_TAC "g_definition") THEN
  SUBGOAL_THEN `FINITE(s:(A#A)->bool)` (LABEL_TAC "finite_face") THENL
   [EXPAND_TAC "s" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     FINITE_GRAPH_FACE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(s:(A#A)->bool) SUBSET graph_darts E`
  (LABEL_TAC "face_darts") THENL
   [EXPAND_TAC "s" THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_FACE_SUBSET_DARTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (f:(A#A)->A#A) s = s`
  (LABEL_TAC "face_invariant") THENL
   [EXPAND_TAC "f" THEN EXPAND_TAC "s" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     GRAPH_FACE_SUCCESSOR_IMAGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(d:A#A) IN s` (LABEL_TAC "d_face") THENL
   [USE_THEN "s_definition"
     (fun th -> REWRITE_TAC[GSYM th; GRAPH_FACE_REFL]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(g:(A#A)->A#A) permutes s`
  (LABEL_TAC "face_permutation") THENL
   [EXPAND_TAC "g" THEN
    MATCH_MP_TAC(ISPECL
     [`f:(A#A)->A#A`; `graph_darts E:A#A->bool`; `s:A#A->bool`]
     RESTRICTED_PERMUTATION_PERMUTES) THEN
    ASM_REWRITE_TAC[] THEN
    EXPAND_TAC "f" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!m. ITER m (g:(A#A)->A#A) d = ITER m f d /\
        ITER m f d IN s`
  (LABEL_TAC "restricted_iter") THENL
   [USE_THEN "g_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC(ISPECL
     [`f:(A#A)->A#A`; `s:(A#A)->bool`; `d:A#A`]
     RESTRICTED_PERMUTATION_ITER) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A#A. a IN s ==> ?m. ITER m (g:(A#A)->A#A) d = a`
  (LABEL_TAC "face_transitive") THENL
   [X_GEN_TAC `a:A#A` THEN
    USE_THEN "s_definition"
     (fun th -> REWRITE_TAC[GSYM th; IN_GRAPH_FACE]) THEN
    REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
    X_GEN_TAC `m:num` THEN
    DISCH_THEN(LABEL_TAC "face_step") THEN
    EXISTS_TAC `m:num` THEN
    USE_THEN "restricted_iter"
     (fun th -> REWRITE_TAC[CONJUNCT1(SPEC `m:num` th)]) THEN
    USE_THEN "f_definition" (fun fth ->
     USE_THEN "face_step" (fun step ->
      ACCEPT_TAC(REWRITE_RULE[fth] step)));
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`g:(A#A)->A#A`; `s:(A#A)->bool`; `d:A#A`]
   FINITE_TRANSITIVE_PERMUTATION_CYCLE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(fun th ->
     USE_THEN "n_definition" (fun nth ->
     MP_TAC(REWRITE_RULE[nth] th))) THEN
    INTRO_TAC "orbit_image orbit_injective return"] THEN
  SUBGOAL_THEN `0 < n` (LABEL_TAC "positive_face") THENL
   [USE_THEN "n_definition" (SUBST1_TAC o SYM) THEN
    SUBGOAL_THEN `~((s:(A#A)->bool) = {})`
    (LABEL_TAC "face_nonempty") THENL
     [USE_THEN "d_face" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `~(CARD(s:(A#A)->bool) = 0)` MP_TAC THENL
     [ASM_SIMP_TAC[CARD_EQ_0];
      ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!m. ITER m (g:(A#A)->A#A) d =
        ITER (m MOD n) g d`
  (LABEL_TAC "periodic") THENL
   [X_GEN_TAC `m:num` THEN
    MATCH_MP_TAC(ISPECL
     [`g:(A#A)->A#A`; `d:A#A`; `n:num`; `m:num`]
    ITER_MOD_PERIODIC_POINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!m. ITER m (g:(A#A)->A#A) d IN s`
  (LABEL_TAC "iter_face") THENL
   [X_GEN_TAC `m:num` THEN
    USE_THEN "restricted_iter" (MP_TAC o SPEC `m:num`) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i < n
        ==> ITER i (g:(A#A)->A#A) d =
            cyclic_dart
              (\j. FST(ITER j g d)) n i`
  (LABEL_TAC "dart_enumeration") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    ONCE_REWRITE_TAC
     [GSYM(ISPEC `ITER i (g:(A#A)->A#A) d` PAIR)] THEN
    PURE_REWRITE_TAC[cyclic_dart; PAIR_EQ; FST; SND] THEN
    REWRITE_TAC[] THEN
    TRANS_TAC EQ_TRANS
     `FST(ITER (i + 1) (g:(A#A)->A#A) d)` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[GSYM ADD1; ITER] THEN
      SUBGOAL_THEN
       `(g:(A#A)->A#A) (ITER i g d) =
        (f:(A#A)->A#A) (ITER i g d)`
      SUBST1_TAC THENL
       [EXPAND_TAC "g" THEN
        ASM_REWRITE_TAC[restricted_permutation];
        EXPAND_TAC "f" THEN
        CONV_TAC SYM_CONV THEN
        MATCH_MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
          `ITER i (g:(A#A)->A#A) d`]
         GRAPH_FACE_SUCCESSOR_TAIL) THEN
        CONJ_TAC THENL
         [USE_THEN "rotation" ACCEPT_TAC;
          USE_THEN "face_darts" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          ASM_REWRITE_TAC[]]];
      USE_THEN "periodic"
       (MP_TAC o AP_TERM `FST:A#A->A` o SPEC `i + 1`) THEN
      MESON_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `\i:num. FST(ITER i (g:(A#A)->A#A) d)` THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "positive_face" ACCEPT_TAC;
    REWRITE_TAC[ITER];
    REWRITE_TAC[num_CONV `1`; ITER] THEN
    SUBGOAL_THEN `(g:(A#A)->A#A) d = f d` SUBST1_TAC THENL
     [EXPAND_TAC "g" THEN ASM_REWRITE_TAC[restricted_permutation];
      EXPAND_TAC "f" THEN
      MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
       GRAPH_FACE_SUCCESSOR_TAIL) THEN
      ASM_REWRITE_TAC[]];
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    USE_THEN "restricted_iter" (MP_TAC o SPEC `i:num`) THEN
    USE_THEN "dart_enumeration" (MP_TAC o SPEC `i:num`) THEN
    EXPAND_TAC "f" THEN ASM_MESON_TAC[];
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
    INTRO_TAC "i_index j_index same_dart" THEN
    USE_THEN "orbit_injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "dart_enumeration" (MP_TAC o SPEC `i:num`) THEN
    USE_THEN "dart_enumeration" (MP_TAC o SPEC `j:num`) THEN
    USE_THEN "restricted_iter" (MP_TAC o SPEC `i:num`) THEN
    USE_THEN "restricted_iter" (MP_TAC o SPEC `j:num`) THEN
    ASM_MESON_TAC[];
    USE_THEN "orbit_image"
     (fun th -> GEN_REWRITE_TAC (LAND_CONV) [GSYM th]) THEN
    REWRITE_TAC[cyclic_darts; GSYM cyclic_dart] THEN
    REWRITE_TAC[EXTENSION; IN_IMAGE; IN_CYCLIC_INDICES] THEN
    USE_THEN "dart_enumeration" (fun th -> MESON_TAC[th]);
    REWRITE_TAC[SUBSET; IN_CYCLIC_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN
    REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
    X_GEN_TAC `i:num` THEN
    INTRO_TAC "index edge" THEN
    USE_THEN "edge" SUBST1_TAC THEN
    SUBGOAL_THEN
     `cyclic_dart
       (\j. FST(ITER j (g:(A#A)->A#A) d))
       n i IN graph_darts E`
    MP_TAC THENL
     [USE_THEN "dart_enumeration" (fun enumeration_th ->
       USE_THEN "index" (fun index_th ->
        ONCE_REWRITE_TAC[GSYM(MP (SPEC `i:num` enumeration_th)
          index_th)])) THEN
      USE_THEN "iter_face" (MP_TAC o SPEC `i:num`) THEN
      USE_THEN "face_darts" MP_TAC THEN
      REWRITE_TAC[SUBSET] THEN MESON_TAC[];
      REWRITE_TAC[cyclic_dart; IN_GRAPH_DARTS; DART_EDGE_PAIR]];
    REWRITE_TAC[cyclic_face_successors] THEN
    X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    SUBGOAL_THEN `(i + 1) MOD n < n`
    (LABEL_TAC "next_index") THENL
     [REWRITE_TAC[MOD_LT_EQ_LT] THEN
      USE_THEN "positive_face" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_face_successor E r
       (cyclic_dart
         (\k. FST(ITER k (g:(A#A)->A#A) d))
         n i) =
      ITER (i + 1) g d`
    (LABEL_TAC "successor_step") THENL
     [USE_THEN "dart_enumeration" (fun enumeration_th ->
       USE_THEN "index" (fun index_th ->
        ONCE_REWRITE_TAC[GSYM(MP (SPEC `i:num` enumeration_th)
          index_th)])) THEN
      REWRITE_TAC[GSYM ADD1; ITER] THEN
      USE_THEN "f_definition" (fun fth ->
       USE_THEN "g_definition" (fun gth ->
        USE_THEN "iter_face" (fun ith ->
         let in_face =
           REWRITE_RULE[GSYM gth] (SPEC `i:num` ith) in
         REWRITE_TAC
          [fth; GSYM gth; restricted_permutation; in_face])));
      ALL_TAC] THEN
    USE_THEN "successor_step" (fun th -> REWRITE_TAC[th]) THEN
    TRANS_TAC EQ_TRANS
     `ITER ((i + 1) MOD n) (g:(A#A)->A#A) d` THEN
    CONJ_TAC THENL
     [USE_THEN "periodic"
       (fun th -> ACCEPT_TAC(SPEC `i + 1` th));
      USE_THEN "dart_enumeration" MATCH_MP_TAC THEN
      USE_THEN "next_index" ACCEPT_TAC]]);;

let CONNECTED_GRAPH_FACE_CYCLIC_WALK = prove
 (`!V E r d:A#A.
        finite_simple_graph V E /\
        connected_graph V E /\
        graph_rotation E r /\
        3 <= CARD V /\
        d IN graph_darts E
        ==> ?q:num->A.
              3 <= CARD(graph_face E r d) /\
              q 0 = FST d /\
              q 1 = SND d /\
              (!i. i < CARD(graph_face E r d)
                   ==> ITER i (graph_face_successor E r) d =
                       cyclic_dart q (CARD(graph_face E r d)) i) /\
              INJ (cyclic_dart q (CARD(graph_face E r d)))
                  (cyclic_indices (CARD(graph_face E r d))) (:A#A) /\
              graph_face E r d =
                cyclic_darts q (CARD(graph_face E r d)) /\
              cyclic_edges q (CARD(graph_face E r d)) SUBSET E /\
              cyclic_face_successors
                E r q (CARD(graph_face E r d))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph connected rotation vertices_large dart" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
   GRAPH_FACE_CYCLIC_WALK) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@q. positive start next enumeration darts_injective \
        face edges successors" THEN
  EXISTS_TAC `q:num->A` THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
     CONNECTED_SIMPLE_GRAPH_FACE_CARD_AT_LEAST_3) THEN
    ASM_REWRITE_TAC[];
    USE_THEN "start" ACCEPT_TAC;
    USE_THEN "next" ACCEPT_TAC;
    USE_THEN "enumeration" ACCEPT_TAC;
    USE_THEN "darts_injective" ACCEPT_TAC;
    USE_THEN "face" ACCEPT_TAC;
    USE_THEN "edges" ACCEPT_TAC;
    USE_THEN "successors" ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* Splitting one local rotation orbit at a repeated facial vertex.           *)
(*                                                                           *)
(* A transposition of two darts in one local rotation splits that local      *)
(* orbit.  We realize the two resulting orbits as the false and true copies  *)
(* of the original vertex in the auxiliary vertex type A#bool.  The          *)
(* definitions below first package transport of a permutation across an      *)
(* injective encoding, then define the auxiliary vertices, darts, and edges. *)
(* ------------------------------------------------------------------------- *)

let restricted_permutation_transport = new_definition
 `restricted_permutation_transport
    (p:A->A) (q:A->B) (s:A->bool) y =
      if y IN IMAGE q s
      then q (p (@x. x IN s /\ q x = y))
      else y`;;

let RESTRICTED_PERMUTATION_TRANSPORT_IMAGE = prove
 (`!p:A->A. !q:A->B. !s x.
        (!u v. u IN s /\ v IN s /\ q u = q v ==> u = v) /\
        x IN s
        ==> restricted_permutation_transport p q s (q x) = q(p x)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective member" THEN
  REWRITE_TAC[restricted_permutation_transport] THEN
  SUBGOAL_THEN `(q:A->B) x IN IMAGE q s` ASSUME_TAC THENL
   [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]] THEN
  SUBGOAL_THEN
   `(@u:A. u IN s /\ (q:A->B) u = q x) = x`
  SUBST1_TAC THENL
   [ABBREV_TAC
     `u:A = @v. v IN s /\ (q:A->B) v = q x` THEN
    SUBGOAL_THEN `u IN s /\ (q:A->B) u = q x`
    (LABEL_TAC "chosen") THENL
     [EXPAND_TAC "u" THEN
      USE_THEN "member" (fun member_th ->
       ACCEPT_TAC
        (MP
         (BETA_RULE
          (ISPECL
           [`\v:A. v IN s /\ (q:A->B) v = q x`; `x:A`]
           SELECT_AX))
         (CONJ member_th (REFL `(q:A->B) x`))));
      ALL_TAC] THEN
    SUBGOAL_THEN `(u:A) = x` MP_TAC THENL
     [USE_THEN "injective" (fun injective_th ->
       USE_THEN "chosen" (fun chosen_th ->
        USE_THEN "member" (fun member_th ->
         ACCEPT_TAC
          (MP
           (SPECL [`u:A`; `x:A`] injective_th)
           (CONJ (CONJUNCT1 chosen_th)
            (CONJ member_th (CONJUNCT2 chosen_th)))))));
      EXPAND_TAC "u" THEN MESON_TAC[]];
    REFL_TAC]);;

let RESTRICTED_PERMUTATION_TRANSPORT_OUTSIDE = prove
 (`!p:A->A. !q:A->B. !s y.
        ~(y IN IMAGE q s)
        ==> restricted_permutation_transport p q s y = y`,
  SIMP_TAC[restricted_permutation_transport]);;

let RESTRICTED_PERMUTATION_TRANSPORT_PERMUTES = prove
 (`!p:A->A. !q:A->B. !s.
        p permutes s /\
        (!u v. u IN s /\ v IN s /\ q u = q v ==> u = v)
        ==> restricted_permutation_transport p q s permutes IMAGE q s`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation injective" THEN
  MATCH_MP_TAC(ISPECL
   [`q:A->B`; `p:A->A`;
    `restricted_permutation_transport p q s:B->B`; `s:A->bool`]
   PERMUTES_TRANSFER) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "member") THEN
    MATCH_MP_TAC RESTRICTED_PERMUTATION_TRANSPORT_IMAGE THEN
    ASM_REWRITE_TAC[];
    MATCH_ACCEPT_TAC RESTRICTED_PERMUTATION_TRANSPORT_OUTSIDE]);;

let RESTRICTED_PERMUTATION_TRANSPORT_ITER = prove
 (`!p:A->A. !q:A->B. !s x.
        p permutes s /\
        (!u v. u IN s /\ v IN s /\ q u = q v ==> u = v) /\
        x IN s
        ==> !n.
              ITER n (restricted_permutation_transport p q s) (q x) =
              q(ITER n p x)`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation injective member" THEN
  SUBGOAL_THEN `!n. ITER n (p:A->A) x IN s`
  (LABEL_TAC "iter_member") THENL
   [X_GEN_TAC `n:num` THEN
    MP_TAC(ISPECL [`ITER n (p:A->A):A->A`; `s:A->bool`; `x:A`]
     PERMUTES_IN_IMAGE) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC PERMUTES_ITER THEN
      USE_THEN "permutation" ACCEPT_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  INDUCT_TAC THENL
   [REWRITE_TAC[ITER];
    REWRITE_TAC[ITER] THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC RESTRICTED_PERMUTATION_TRANSPORT_IMAGE THEN
    ASM_REWRITE_TAC[]]);;

let IMAGE_RESTRICTED_INJECTIVE_EQ = prove
 (`!q:A->B. !s t u.
        (!x y. x IN s /\ y IN s /\ q x = q y ==> x = y) /\
        t SUBSET s /\ u SUBSET s /\
        IMAGE q t = IMAGE q u
        ==> t = u`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective t_subset u_subset image" THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `x:A` THEN EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "x_t") THEN
    SUBGOAL_THEN `(q:A->B) x IN IMAGE q u` MP_TAC THENL
     [USE_THEN "image" (fun th -> REWRITE_TAC[GSYM th]) THEN
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `x:A` THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[IN_IMAGE] THEN
      INTRO_TAC "@y. same y_u" THEN
      SUBGOAL_THEN `(x:A) = y` SUBST1_TAC THENL
       [USE_THEN "injective" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [USE_THEN "t_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          USE_THEN "x_t" ACCEPT_TAC;
          USE_THEN "u_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          USE_THEN "y_u" ACCEPT_TAC];
        USE_THEN "y_u" ACCEPT_TAC]];
    DISCH_THEN(LABEL_TAC "x_u") THEN
    SUBGOAL_THEN `(q:A->B) x IN IMAGE q t` MP_TAC THENL
     [USE_THEN "image" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `x:A` THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[IN_IMAGE] THEN
      INTRO_TAC "@y. same y_t" THEN
      SUBGOAL_THEN `(x:A) = y` SUBST1_TAC THENL
       [USE_THEN "injective" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [USE_THEN "u_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          USE_THEN "x_u" ACCEPT_TAC;
          USE_THEN "t_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          USE_THEN "y_t" ACCEPT_TAC];
        USE_THEN "y_t" ACCEPT_TAC]]]);;

let RESTRICTED_PERMUTATION_TRANSPORT_ORBIT = prove
 (`!p:A->A. !q:A->B. !s x.
        p permutes s /\
        (!u v. u IN s /\ v IN s /\ q u = q v ==> u = v) /\
        x IN s
        ==> IMAGE q (permutation_orbit p x) =
            permutation_orbit
              (restricted_permutation_transport p q s) (q x)`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation injective member" THEN
  REWRITE_TAC[EXTENSION; IN_IMAGE; IN_PERMUTATION_ORBIT] THEN
  X_GEN_TAC `y:B` THEN EQ_TAC THENL
   [INTRO_TAC "@z. image (@n. step)" THEN
    EXISTS_TAC `n:num` THEN
    MP_TAC(SPEC `n:num`
     (MATCH_MP
      (ISPECL [`p:A->A`; `q:A->B`; `s:A->bool`; `x:A`]
       RESTRICTED_PERMUTATION_TRANSPORT_ITER)
      (CONJ
       (ASSUME `(p:A->A) permutes s`)
       (CONJ
        (ASSUME
         `!u v:A.
            u IN s /\ v IN s /\ (q:A->B) u = q v ==> u = v`)
        (ASSUME `(x:A) IN s`))))) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THEN
    EXISTS_TAC `ITER n (p:A->A) x` THEN
    CONJ_TAC THENL
     [USE_THEN "step" (fun th ->
       MP_TAC(SPEC `n:num`
        (MATCH_MP
         (ISPECL [`p:A->A`; `q:A->B`; `s:A->bool`; `x:A`]
          RESTRICTED_PERMUTATION_TRANSPORT_ITER)
         (CONJ
          (ASSUME `(p:A->A) permutes s`)
          (CONJ
           (ASSUME
            `!u v:A.
               u IN s /\ v IN s /\ (q:A->B) u = q v ==> u = v`)
           (ASSUME `(x:A) IN s`))))) THEN
       ASM_REWRITE_TAC[]);
      EXISTS_TAC `n:num` THEN REFL_TAC]]);;

let RESTRICTED_PERMUTATION_TRANSPORT_ORBITS = prove
 (`!p:A->A. !q:A->B. !s.
        p permutes s /\
        (!u v. u IN s /\ v IN s /\ q u = q v ==> u = v)
        ==> IMAGE (IMAGE q) (permutation_orbits p s) =
            permutation_orbits
              (restricted_permutation_transport p q s) (IMAGE q s)`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation injective" THEN
  REWRITE_TAC[permutation_orbits; GSYM IMAGE_o] THEN
  MATCH_MP_TAC IMAGE_EQ THEN X_GEN_TAC `x:A` THEN
  DISCH_THEN(LABEL_TAC "member") THEN REWRITE_TAC[o_THM] THEN
  MATCH_MP_TAC RESTRICTED_PERMUTATION_TRANSPORT_ORBIT THEN
  ASM_REWRITE_TAC[]);;

let CARD_RESTRICTED_PERMUTATION_TRANSPORT_ORBITS = prove
 (`!p:A->A. !q:A->B. !s.
        FINITE s /\
        p permutes s /\
        (!u v. u IN s /\ v IN s /\ q u = q v ==> u = v)
        ==> CARD
             (permutation_orbits
               (restricted_permutation_transport p q s) (IMAGE q s)) =
            CARD(permutation_orbits p s)`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutation injective" THEN
  MP_TAC(ISPECL [`p:A->A`; `q:A->B`; `s:A->bool`]
   RESTRICTED_PERMUTATION_TRANSPORT_ORBITS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC CARD_IMAGE_INJ THEN
  CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`t:A->bool`; `u:A->bool`] THEN
    INTRO_TAC "t_orbit u_orbit same_image" THEN
    MATCH_MP_TAC(ISPECL
     [`q:A->B`; `s:A->bool`; `t:A->bool`; `u:A->bool`]
     IMAGE_RESTRICTED_INJECTIVE_EQ) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "t_orbit" MP_TAC THEN
      REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
      INTRO_TAC "@x. x_member representation" THEN
      USE_THEN "representation" SUBST1_TAC THEN
      MATCH_MP_TAC PERMUTATION_ORBIT_SUBSET THEN
      ASM_REWRITE_TAC[];
      USE_THEN "u_orbit" MP_TAC THEN
      REWRITE_TAC[IN_PERMUTATION_ORBITS] THEN
      INTRO_TAC "@x. x_member representation" THEN
      USE_THEN "representation" SUBST1_TAC THEN
      MATCH_MP_TAC PERMUTATION_ORBIT_SUBSET THEN
      ASM_REWRITE_TAC[]];
    MATCH_MP_TAC FINITE_PERMUTATION_ORBITS THEN
    USE_THEN "finite" ACCEPT_TAC]);;

let rotation_split_vertex = new_definition
 `rotation_split_vertex
    (p:(A#A)->A#A) (x:A) (b:A#A) d =
      (FST d,(FST d = x /\ d IN permutation_orbit p b))`;;

let rotation_split_dart = new_definition
 `rotation_split_dart
    (p:(A#A)->A#A) (x:A) (b:A#A) d =
      (rotation_split_vertex p x b d,
       rotation_split_vertex p x b (reverse_dart d))`;;

let rotation_split_vertices = new_definition
 `rotation_split_vertices
    (E:(A->bool)->bool) (p:(A#A)->A#A) x b =
      IMAGE (rotation_split_vertex p x b) (graph_darts E)`;;

let rotation_split_edges = new_definition
 `rotation_split_edges
    (E:(A->bool)->bool) (p:(A#A)->A#A) x b =
      IMAGE
       (dart_edge o rotation_split_dart p x b)
       (graph_darts E)`;;

let rotation_split_rotation = new_definition
 `rotation_split_rotation
    (E:(A->bool)->bool) (p:(A#A)->A#A) x b =
      restricted_permutation_transport
        p (rotation_split_dart p x b) (graph_darts E)`;;

let FST_ROTATION_SPLIT_VERTEX = prove
 (`!p:(A#A)->A#A. !x b d.
        FST(rotation_split_vertex p x b d) = FST d`,
  REWRITE_TAC[rotation_split_vertex; FST]);;

let FST_ROTATION_SPLIT_DART = prove
 (`!p:(A#A)->A#A. !x b d.
        FST(rotation_split_dart p x b d) =
        rotation_split_vertex p x b d`,
  REWRITE_TAC[rotation_split_dart; FST]);;

let SND_ROTATION_SPLIT_DART = prove
 (`!p:(A#A)->A#A. !x b d.
        SND(rotation_split_dart p x b d) =
        rotation_split_vertex p x b (reverse_dart d)`,
  REWRITE_TAC[rotation_split_dart; SND]);;

let ROTATION_SPLIT_DART_INJECTIVE = prove
 (`!p:(A#A)->A#A. !x b d e.
        rotation_split_dart p x b d =
        rotation_split_dart p x b e
        ==> d = e`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[rotation_split_dart; PAIR_EQ] THEN
  INTRO_TAC "tails heads" THEN
  SUBGOAL_THEN `FST(d:A#A) = FST(e:A#A)`
  (LABEL_TAC "same_fst") THENL
   [USE_THEN "tails" (MP_TAC o AP_TERM `FST:A#bool->A`) THEN
    REWRITE_TAC[FST_ROTATION_SPLIT_VERTEX];
    ALL_TAC] THEN
  SUBGOAL_THEN `SND(d:A#A) = SND(e:A#A)`
  (LABEL_TAC "same_snd") THENL
   [USE_THEN "heads" (MP_TAC o AP_TERM `FST:A#bool->A`) THEN
    REWRITE_TAC[FST_ROTATION_SPLIT_VERTEX; FST_REVERSE_DART];
    ALL_TAC] THEN
  GEN_REWRITE_TAC (LAND_CONV) [GSYM(ISPEC `d:A#A` PAIR)] THEN
  GEN_REWRITE_TAC (RAND_CONV) [GSYM(ISPEC `e:A#A` PAIR)] THEN
  ASM_REWRITE_TAC[PAIR_EQ]);;

let ROTATION_SPLIT_DART_REVERSE = prove
 (`!p:(A#A)->A#A. !x b d.
        rotation_split_dart p x b (reverse_dart d) =
        reverse_dart(rotation_split_dart p x b d)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[rotation_split_dart; REVERSE_DART_PAIR;
              REVERSE_DART_INVOLUTION]);;

let DART_EDGE_EQ_DISTINCT = prove
 (`!d e:A#A.
        ~(FST d = SND d) /\
        dart_edge e = dart_edge d
        ==> e = d \/ e = reverse_dart d`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPEC `d:A#A` PAIR_SURJECTIVE) THEN
  MP_TAC(ISPEC `e:A#A` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A`
   (X_CHOOSE_THEN `b:A` SUBST_ALL_TAC)) THEN
  DISCH_THEN(X_CHOOSE_THEN `u:A`
   (X_CHOOSE_THEN `v:A` SUBST_ALL_TAC)) THEN
  REWRITE_TAC[FST; SND; DART_EDGE_PAIR; REVERSE_DART_PAIR;
              PAIR_EQ] THEN
  SET_TAC[]);;

let ROTATION_SPLIT_DART_ENDPOINTS_DISTINCT = prove
 (`!V E p x b d:A#A.
        finite_simple_graph V E /\
        d IN graph_darts E
        ==> ~(FST(rotation_split_dart p x b d) =
              SND(rotation_split_dart p x b d))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph dart" THEN
  REWRITE_TAC[FST_ROTATION_SPLIT_DART;
              SND_ROTATION_SPLIT_DART] THEN
  DISCH_THEN(LABEL_TAC "same") THEN
  SUBGOAL_THEN `FST(d:A#A) = SND d`
  (LABEL_TAC "loop") THENL
   [MP_TAC(AP_TERM `FST:A#bool->A`
     (ASSUME
      `rotation_split_vertex (p:(A#A)->A#A) x b d =
       rotation_split_vertex p x b (reverse_dart d)`)) THEN
    REWRITE_TAC[FST_ROTATION_SPLIT_VERTEX; FST_REVERSE_DART];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `FST(d:A#A)`; `SND(d:A#A)`]
   FINITE_SIMPLE_GRAPH_DART) THEN
  ASM_REWRITE_TAC[PAIR]);;

let FINITE_ROTATION_SPLIT_VERTICES = prove
 (`!V E p x b.
        finite_simple_graph (V:A->bool) E
        ==> FINITE(rotation_split_vertices E p x b)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  REWRITE_TAC[rotation_split_vertices] THEN
  MATCH_MP_TAC FINITE_IMAGE THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
  USE_THEN "graph" ACCEPT_TAC);;

let FINITE_ROTATION_SPLIT_EDGES = prove
 (`!V E p x b.
        finite_simple_graph (V:A->bool) E
        ==> FINITE(rotation_split_edges E p x b)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  REWRITE_TAC[rotation_split_edges] THEN
  MATCH_MP_TAC FINITE_IMAGE THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
  USE_THEN "graph" ACCEPT_TAC);;

let FINITE_SIMPLE_GRAPH_ROTATION_SPLIT = prove
 (`!V E p x b.
        finite_simple_graph (V:A->bool) E
        ==> finite_simple_graph
             (rotation_split_vertices E p x b)
             (rotation_split_edges E p x b)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  REWRITE_TAC[finite_simple_graph] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_ROTATION_SPLIT_VERTICES THEN
    EXISTS_TAC `V:A->bool` THEN USE_THEN "graph" ACCEPT_TAC;
    MATCH_MP_TAC FINITE_ROTATION_SPLIT_EDGES THEN
    EXISTS_TAC `V:A->bool` THEN USE_THEN "graph" ACCEPT_TAC;
    X_GEN_TAC `e:(A#bool)->bool` THEN
    REWRITE_TAC[rotation_split_edges; IN_IMAGE] THEN
    INTRO_TAC "@d. edge_image dart" THEN
    USE_THEN "edge_image" SUBST1_TAC THEN
    REWRITE_TAC[o_THM; dart_edge;
                FST_ROTATION_SPLIT_DART;
                SND_ROTATION_SPLIT_DART] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[INSERT_SUBSET; SING_SUBSET;
                  rotation_split_vertices; IN_IMAGE] THEN
      CONJ_TAC THENL
       [EXISTS_TAC `d:A#A` THEN ASM_REWRITE_TAC[];
        EXISTS_TAC `reverse_dart(d:A#A)` THEN
        ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE]];
      REWRITE_TAC[PAIR_HAS_SIZE_2] THEN
      MATCH_MP_TAC(REWRITE_RULE
       [FST_ROTATION_SPLIT_DART; SND_ROTATION_SPLIT_DART]
       (ISPECL
        [`V:A->bool`; `E:(A->bool)->bool`;
         `p:(A#A)->A#A`; `x:A`; `b:A#A`; `d:A#A`]
        ROTATION_SPLIT_DART_ENDPOINTS_DISTINCT)) THEN
      ASM_REWRITE_TAC[]]]);;

let GRAPH_DARTS_ROTATION_SPLIT_EDGES = prove
 (`!V E p x b.
        finite_simple_graph (V:A->bool) E
        ==> graph_darts(rotation_split_edges E p x b) =
            IMAGE (rotation_split_dart p x b) (graph_darts E)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `z:(A#bool)#(A#bool)` THEN
  REWRITE_TAC[graph_darts; IN_ELIM_THM;
              rotation_split_edges; IN_IMAGE] THEN
  EQ_TAC THENL
   [INTRO_TAC "@d. edge_image dart" THEN
    SUBGOAL_THEN
     `~(FST(rotation_split_dart (p:(A#A)->A#A) x b d) =
        SND(rotation_split_dart p x b d))`
    (LABEL_TAC "distinct") THENL
     [MATCH_MP_TAC(ISPECL
               [`V:A->bool`; `E:(A->bool)->bool`;
                `p:(A#A)->A#A`; `x:A`; `b:A#A`; `d:A#A`]
               ROTATION_SPLIT_DART_ENDPOINTS_DISTINCT) THEN
              CONJ_TAC THENL
               [USE_THEN "graph" ACCEPT_TAC;
                USE_THEN "dart" MP_TAC THEN
                REWRITE_TAC[dart_edge; graph_darts; IN_ELIM_THM]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `z = rotation_split_dart (p:(A#A)->A#A) x b d \/
      z = reverse_dart(rotation_split_dart p x b d)`
    (LABEL_TAC "orientation") THENL
     [MATCH_MP_TAC(ISPECL
       [`rotation_split_dart (p:(A#A)->A#A) x b d`;
       `z:(A#bool)#(A#bool)`]
       DART_EDGE_EQ_DISTINCT) THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL
                 [`V:A->bool`; `E:(A->bool)->bool`;
                  `p:(A#A)->A#A`; `x:A`; `b:A#A`; `d:A#A`]
                 ROTATION_SPLIT_DART_ENDPOINTS_DISTINCT) THEN
                CONJ_TAC THENL
                 [USE_THEN "graph" ACCEPT_TAC;
                  USE_THEN "dart" MP_TAC THEN
                  REWRITE_TAC[dart_edge; graph_darts; IN_ELIM_THM]];
        USE_THEN "edge_image" (fun th -> REWRITE_TAC[th; o_THM])];
      ALL_TAC] THEN
    USE_THEN "orientation"
     (DISJ_CASES_THEN2 (LABEL_TAC "forward") (LABEL_TAC "backward")) THENL
     [EXISTS_TAC `d:A#A` THEN CONJ_TAC THENL
       [USE_THEN "forward" ACCEPT_TAC;
        REWRITE_TAC[GSYM dart_edge] THEN
        USE_THEN "dart" ACCEPT_TAC];
      EXISTS_TAC `reverse_dart(d:A#A)` THEN CONJ_TAC THENL
       [REWRITE_TAC[ROTATION_SPLIT_DART_REVERSE] THEN
        USE_THEN "backward" ACCEPT_TAC;
        REWRITE_TAC[GSYM dart_edge; DART_EDGE_REVERSE] THEN
        USE_THEN "dart" ACCEPT_TAC]];
    INTRO_TAC "@d. representation dart" THEN
    EXISTS_TAC `d:A#A` THEN CONJ_TAC THENL
     [REWRITE_TAC[o_THM] THEN
      USE_THEN "representation"
       (ACCEPT_TAC o
        AP_TERM
         `dart_edge:((A#bool)#(A#bool))->((A#bool)->bool)`);
      REWRITE_TAC[GSYM dart_edge] THEN
      USE_THEN "dart" ACCEPT_TAC]]);;

let CARD_GRAPH_DARTS_ROTATION_SPLIT = prove
 (`!V E p x b.
        finite_simple_graph (V:A->bool) E
        ==> CARD(graph_darts(rotation_split_edges E p x b)) =
            CARD(graph_darts E)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `p:(A#A)->A#A`; `x:A`; `b:A#A`]
   GRAPH_DARTS_ROTATION_SPLIT_EDGES) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC CARD_IMAGE_INJ THEN CONJ_TAC THENL
   [REPEAT GEN_TAC THEN
    INTRO_TAC "_ _ same" THEN
    USE_THEN "same" MP_TAC THEN
    MESON_TAC[ROTATION_SPLIT_DART_INJECTIVE];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC]);;

let CARD_ROTATION_SPLIT_EDGES = prove
 (`!V E p x b.
        finite_simple_graph (V:A->bool) E
        ==> CARD(rotation_split_edges E p x b) = CARD E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  SUBGOAL_THEN
   `finite_simple_graph
     (rotation_split_vertices
       (E:(A->bool)->bool) (p:(A#A)->A#A) (x:A) (b:A#A))
     (rotation_split_edges E p x b)`
  (LABEL_TAC "split_graph") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `p:(A#A)->A#A`; `x:A`; `b:A#A`]
     FINITE_SIMPLE_GRAPH_ROTATION_SPLIT) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`rotation_split_vertices
      (E:(A->bool)->bool) (p:(A#A)->A#A) x b`;
    `rotation_split_edges
      (E:(A->bool)->bool) (p:(A#A)->A#A) x b`]
   CARD_GRAPH_DARTS) THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`] CARD_GRAPH_DARTS) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `p:(A#A)->A#A`; `x:A`; `b:A#A`]
   CARD_GRAPH_DARTS_ROTATION_SPLIT) THEN
  ASM_REWRITE_TAC[] THEN ARITH_TAC);;

let rotation_split_permutation = new_definition
 `rotation_split_permutation
    (r:(A#A)->A#A) (a:A#A) b =
      swap(a,b) o r`;;

let ROTATION_SPLIT_PERMUTATION_PERMUTES = prove
 (`!E r a b:A#A.
        graph_rotation E r /\
        a IN graph_darts E /\
        b IN graph_darts E
        ==> rotation_split_permutation r a b permutes graph_darts E`,
  REPEAT GEN_TAC THEN INTRO_TAC "rotation a_dart b_dart" THEN
  REWRITE_TAC[rotation_split_permutation] THEN
  MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
  USE_THEN "rotation" ACCEPT_TAC);;

let ROTATION_SPLIT_PERMUTATION_TAIL = prove
 (`!E r a b d:A#A.
        graph_rotation E r /\
        a IN graph_darts E /\
        b IN graph_darts E /\
        FST a = FST b /\
        d IN graph_darts E
        ==> FST(rotation_split_permutation r a b d) = FST d`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "rotation a_dart b_dart same_tail dart" THEN
  SUBGOAL_THEN `(r:(A#A)->A#A) d IN graph_darts E`
  (LABEL_TAC "rotated_dart") THENL
   [MP_TAC(ISPECL
     [`r:(A#A)->A#A`; `graph_darts E:(A#A)->bool`; `d:A#A`]
     PERMUTES_IN_IMAGE) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
      USE_THEN "rotation" ACCEPT_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `FST((r:(A#A)->A#A) d) = FST d`
  (LABEL_TAC "rotation_tail") THENL
   [MATCH_MP_TAC GRAPH_ROTATION_TAIL THEN
    EXISTS_TAC `E:(A->bool)->bool` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[rotation_split_permutation; o_THM] THEN
  ASM_CASES_TAC `(r:(A#A)->A#A) d = a` THENL
   [ASM_REWRITE_TAC[SWAP_LEFT] THEN ASM_MESON_TAC[];
    ASM_CASES_TAC `(r:(A#A)->A#A) d = b` THENL
     [ASM_REWRITE_TAC[SWAP_RIGHT] THEN ASM_MESON_TAC[];
      ASM_SIMP_TAC[SWAP_OTHER]]]);;

let GRAPH_ROTATION_SAME_TAIL_ORBIT = prove
  (`!E r d e:A#A.
        graph_rotation E r /\
        d IN graph_darts E /\
        e IN graph_darts E /\
        FST d = FST e
        ==> permutation_orbit r d = permutation_orbit r e`,
  REPEAT GEN_TAC THEN INTRO_TAC "rotation d_dart e_dart same_tail" THEN
  TRANS_TAC EQ_TRANS `outgoing_darts E (FST(d:A#A))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC GRAPH_ROTATION_ORBIT_OUTGOING_DARTS THEN
    ASM_REWRITE_TAC[];
    USE_THEN "same_tail" (fun th -> REWRITE_TAC[th]) THEN
    CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC GRAPH_ROTATION_ORBIT_OUTGOING_DARTS THEN
    ASM_REWRITE_TAC[]]);;

let ROTATION_SPLIT_PERMUTATION_ORBITS_DISTINCT = prove
 (`!V E r a b:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        a IN graph_darts E /\
        b IN graph_darts E /\
        ~(a = b) /\
        FST a = FST b
        ==> ~(permutation_orbit
                (rotation_split_permutation r a b) a =
              permutation_orbit
                (rotation_split_permutation r a b) b)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation a_dart b_dart distinct same_tail" THEN
  REWRITE_TAC[rotation_split_permutation] THEN
  MATCH_MP_TAC(ISPECL
   [`r:(A#A)->A#A`; `graph_darts E:(A#A)->bool`;
    `a:A#A`; `b:A#A`]
   PERMUTATION_SWAP_SPLITS_SAME_ORBIT) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    USE_THEN "a_dart" ACCEPT_TAC;
    USE_THEN "b_dart" ACCEPT_TAC;
    USE_THEN "distinct" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `a:A#A`; `b:A#A`]
     GRAPH_ROTATION_SAME_TAIL_ORBIT) THEN
    ASM_REWRITE_TAC[]]);;

let ROTATION_SPLIT_PERMUTATION_COVERS_VERTEX = prove
 (`!V E r a b d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        a IN graph_darts E /\
        b IN graph_darts E /\
        FST a = FST b /\
        d IN graph_darts E /\
        FST d = FST a
        ==> d IN
              permutation_orbit
                (rotation_split_permutation r a b) a \/
            d IN
              permutation_orbit
                (rotation_split_permutation r a b) b`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph rotation a_dart b_dart same_tail d_dart d_tail" THEN
  ABBREV_TAC
   `p:(A#A)->A#A = rotation_split_permutation r a b` THEN
  SUBGOAL_THEN `FINITE(graph_darts E:(A#A)->bool)`
  (LABEL_TAC "finite_darts") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:(A#A)->A#A) permutes graph_darts E`
  (LABEL_TAC "rotation_permutation") THENL
   [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:(A#A)->A#A) permutes graph_darts E`
  (LABEL_TAC "split_permutation") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC ROTATION_SPLIT_PERMUTATION_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(d:A#A) IN permutation_orbit r a`
  (LABEL_TAC "old_orbit") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `a:A#A`; `d:A#A`]
     GRAPH_ROTATION_SAME_TAIL_ORBIT) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(a:A#A) IN permutation_orbit p d \/
    b IN permutation_orbit p d`
  (DISJ_CASES_THEN2
   (LABEL_TAC "a_from_d") (LABEL_TAC "b_from_d")) THENL
   [EXPAND_TAC "p" THEN
    REWRITE_TAC[rotation_split_permutation] THEN
    MATCH_MP_TAC(ISPECL
     [`r:(A#A)->A#A`; `graph_darts E:(A#A)->bool`;
      `a:A#A`; `b:A#A`; `d:A#A`]
     PERMUTATION_SWAP_AFFECTED_ORBIT_HITS) THEN
    ASM_REWRITE_TAC[];
    DISJ1_TAC THEN
    MATCH_MP_TAC(ISPECL
     [`p:(A#A)->A#A`; `graph_darts E:(A#A)->bool`;
      `d:A#A`; `a:A#A`]
     PERMUTATION_ORBIT_SYM) THEN
    ASM_REWRITE_TAC[];
    DISJ2_TAC THEN
    MATCH_MP_TAC(ISPECL
     [`p:(A#A)->A#A`; `graph_darts E:(A#A)->bool`;
      `d:A#A`; `b:A#A`]
     PERMUTATION_ORBIT_SYM) THEN
    ASM_REWRITE_TAC[]]);;

let FINITE_PERMUTATION_ORBIT_SUCCESSOR_EQ = prove
 (`!p:A->A. !s x y.
        FINITE s /\
        p permutes s /\
        x IN s /\
        y IN s
        ==> (p y IN permutation_orbit p x <=>
             y IN permutation_orbit p x)`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite permutation x_member y_member" THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "successor_orbit") THEN
    SUBGOAL_THEN `(p:A->A) y IN s`
    (LABEL_TAC "successor_member") THENL
     [MP_TAC(ISPECL [`p:A->A`; `s:A->bool`; `y:A`]
       PERMUTES_IN_IMAGE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(y:A) IN permutation_orbit p (p y)`
    (LABEL_TAC "predecessor") THENL
     [MATCH_MP_TAC(ISPECL
       [`p:A->A`; `s:A->bool`; `y:A`; `(p:A->A) y`]
       PERMUTATION_ORBIT_SYM) THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC PERMUTATION_ORBIT_SUCCESSOR THEN
      MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL;
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`p:A->A`; `x:A`; `(p:A->A) y`; `y:A`]
     PERMUTATION_ORBIT_TRANS) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(LABEL_TAC "orbit") THEN
    MATCH_MP_TAC PERMUTATION_ORBIT_SUCCESSOR THEN
    USE_THEN "orbit" ACCEPT_TAC]);;

let ROTATION_SPLIT_VERTEX_INVARIANT = prove
 (`!V E r a b d:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        a IN graph_darts E /\
        b IN graph_darts E /\
        FST a = FST b /\
        d IN graph_darts E
        ==> rotation_split_vertex
              (rotation_split_permutation r a b) (FST a) b
              (rotation_split_permutation r a b d) =
            rotation_split_vertex
              (rotation_split_permutation r a b) (FST a) b d`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation a_dart b_dart same_tail dart" THEN
  ABBREV_TAC `p:(A#A)->A#A = rotation_split_permutation r a b` THEN
  SUBGOAL_THEN `FINITE(graph_darts E:(A#A)->bool)`
  (LABEL_TAC "finite_darts") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:(A#A)->A#A) permutes graph_darts E`
  (LABEL_TAC "split_permutation") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC ROTATION_SPLIT_PERMUTATION_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:(A#A)->A#A) d IN graph_darts E`
  (LABEL_TAC "successor_dart") THENL
   [MP_TAC(ISPECL
     [`p:(A#A)->A#A`; `graph_darts E:(A#A)->bool`; `d:A#A`]
     PERMUTES_IN_IMAGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FST((p:(A#A)->A#A) d) = FST d`
  (LABEL_TAC "same_vertex") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `a:A#A`; `b:A#A`; `d:A#A`]
     ROTATION_SPLIT_PERMUTATION_TAIL) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((p:(A#A)->A#A) d IN permutation_orbit p b <=>
      d IN permutation_orbit p b)`
  (LABEL_TAC "same_side") THENL
   [MATCH_MP_TAC(ISPECL
     [`p:(A#A)->A#A`; `graph_darts E:(A#A)->bool`;
      `b:A#A`; `d:A#A`]
     FINITE_PERMUTATION_ORBIT_SUCCESSOR_EQ) THEN
    ASM_REWRITE_TAC[];
    EXPAND_TAC "p" THEN
    REWRITE_TAC[rotation_split_vertex; PAIR_EQ] THEN
    ASM_REWRITE_TAC[]]);;

let ROTATION_SPLIT_VERTEX_FIBER_TRANSITIVE = prove
 (`!V E r a b d e:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        a IN graph_darts E /\
        b IN graph_darts E /\
        ~(a = b) /\
        FST a = FST b /\
        d IN graph_darts E /\
        e IN graph_darts E /\
        rotation_split_vertex
          (rotation_split_permutation r a b) (FST a) b d =
        rotation_split_vertex
          (rotation_split_permutation r a b) (FST a) b e
        ==> ?n.
              ITER n (rotation_split_permutation r a b) d = e`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph rotation a_dart b_dart distinct same_tail \
    d_dart e_dart same_split_vertex" THEN
  ABBREV_TAC `p:(A#A)->A#A = rotation_split_permutation r a b` THEN
  SUBGOAL_THEN `FINITE(graph_darts E:(A#A)->bool)`
  (LABEL_TAC "finite_darts") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:(A#A)->A#A) permutes graph_darts E`
  (LABEL_TAC "rotation_permutation") THENL
   [MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:(A#A)->A#A) permutes graph_darts E`
  (LABEL_TAC "split_permutation") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC ROTATION_SPLIT_PERMUTATION_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FST(d:A#A) = FST(e:A#A)`
  (LABEL_TAC "same_vertex") THENL
   [USE_THEN "same_split_vertex"
     (MP_TAC o AP_TERM `FST:A#bool->A`) THEN
    REWRITE_TAC[FST_ROTATION_SPLIT_VERTEX];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FST(d:A#A) = FST(a:A#A)
    ==> (d IN permutation_orbit p b <=>
         e IN permutation_orbit p b)`
  (LABEL_TAC "same_side") THENL
   [DISCH_THEN(LABEL_TAC "at_split") THEN
    SUBGOAL_THEN `FST(e:A#A) = FST(a:A#A)`
    (LABEL_TAC "e_at_split") THENL
     [USE_THEN "same_vertex"
       (fun th -> REWRITE_TAC[GSYM th]) THEN
      USE_THEN "at_split" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "same_split_vertex"
     (MP_TAC o AP_TERM `SND:A#bool->bool`) THEN
    REWRITE_TAC[rotation_split_vertex; SND] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit (p:(A#A)->A#A) d =
    permutation_orbit p e`
  (LABEL_TAC "same_orbit") THENL
   [ASM_CASES_TAC `FST(d:A#A) = FST(a:A#A)` THENL
     [FIRST_X_ASSUM(LABEL_TAC "split_vertex") THEN
      SUBGOAL_THEN `FST(e:A#A) = FST(a:A#A)`
      (LABEL_TAC "e_split_vertex") THENL
       [USE_THEN "same_vertex"
         (fun th -> REWRITE_TAC[GSYM th]) THEN
        USE_THEN "split_vertex" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(d:A#A) IN permutation_orbit p a \/
        d IN permutation_orbit p b`
      (LABEL_TAC "d_cover") THENL
       [EXPAND_TAC "p" THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
          `r:(A#A)->A#A`; `a:A#A`; `b:A#A`; `d:A#A`]
         ROTATION_SPLIT_PERMUTATION_COVERS_VERTEX) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(e:A#A) IN permutation_orbit p a \/
        e IN permutation_orbit p b`
      (LABEL_TAC "e_cover") THENL
       [EXPAND_TAC "p" THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
          `r:(A#A)->A#A`; `a:A#A`; `b:A#A`; `e:A#A`]
         ROTATION_SPLIT_PERMUTATION_COVERS_VERTEX) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      ASM_CASES_TAC `(d:A#A) IN permutation_orbit p b` THENL
       [SUBGOAL_THEN `(e:A#A) IN permutation_orbit p b`
        (LABEL_TAC "e_b") THENL
         [USE_THEN "same_side" (fun side_th ->
           USE_THEN "split_vertex" (fun at_th ->
            MP_TAC(MATCH_MP side_th at_th))) THEN
          ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        TRANS_TAC EQ_TRANS `permutation_orbit (p:(A#A)->A#A) b` THEN
        CONJ_TAC THENL
         [MP_TAC(ISPECL
           [`p:(A#A)->A#A`; `graph_darts E:(A#A)->bool`;
            `b:A#A`; `d:A#A`]
           PERMUTATION_ORBIT_EQ) THEN
          ASM_REWRITE_TAC[];
          CONV_TAC SYM_CONV THEN
          MP_TAC(ISPECL
           [`p:(A#A)->A#A`; `graph_darts E:(A#A)->bool`;
            `b:A#A`; `e:A#A`]
           PERMUTATION_ORBIT_EQ) THEN
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      FIRST_X_ASSUM(LABEL_TAC "d_not_b") THEN
      SUBGOAL_THEN `~((e:A#A) IN permutation_orbit p b)`
      (LABEL_TAC "e_not_b") THENL
       [USE_THEN "same_side" (fun side_th ->
         USE_THEN "split_vertex" (fun at_th ->
          MP_TAC(MATCH_MP side_th at_th))) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(d:A#A) IN permutation_orbit p a`
      (LABEL_TAC "d_a") THENL
       [ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(e:A#A) IN permutation_orbit p a`
      (LABEL_TAC "e_a") THENL
       [ASM_MESON_TAC[];
        ALL_TAC] THEN
      TRANS_TAC EQ_TRANS `permutation_orbit (p:(A#A)->A#A) a` THEN
      CONJ_TAC THENL
       [MP_TAC(ISPECL
         [`p:(A#A)->A#A`; `graph_darts E:(A#A)->bool`;
          `a:A#A`; `d:A#A`]
         PERMUTATION_ORBIT_EQ) THEN
        ASM_REWRITE_TAC[];
        CONV_TAC SYM_CONV THEN
        MP_TAC(ISPECL
         [`p:(A#A)->A#A`; `graph_darts E:(A#A)->bool`;
          `a:A#A`; `e:A#A`]
         PERMUTATION_ORBIT_EQ) THEN
        ASM_REWRITE_TAC[]];
      FIRST_X_ASSUM(LABEL_TAC "away")] THEN
    SUBGOAL_THEN
     `permutation_orbit (r:(A#A)->A#A) a =
      outgoing_darts E (FST a)`
    (LABEL_TAC "a_outgoing") THENL
     [MATCH_MP_TAC GRAPH_ROTATION_ORBIT_OUTGOING_DARTS THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `permutation_orbit (r:(A#A)->A#A) b =
      outgoing_darts E (FST b)`
    (LABEL_TAC "b_outgoing") THENL
     [MATCH_MP_TAC GRAPH_ROTATION_ORBIT_OUTGOING_DARTS THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `~(FST(d:A#A) = FST(b:A#A))`
    (LABEL_TAC "d_away_b") THENL
     [DISCH_THEN(LABEL_TAC "d_at_b") THEN
      USE_THEN "away" (MATCH_MP_TAC o NOT_ELIM) THEN
      TRANS_TAC EQ_TRANS `FST(b:A#A)` THEN
      CONJ_TAC THENL
       [USE_THEN "d_at_b" ACCEPT_TAC;
        USE_THEN "same_tail"
         (ACCEPT_TAC o GSYM)];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((d:A#A) IN permutation_orbit r a) /\
      ~(d IN permutation_orbit r b)`
    (CONJUNCTS_THEN2
      (LABEL_TAC "d_not_a") (LABEL_TAC "d_not_b")) THENL
     [ASM_REWRITE_TAC[IN_OUTGOING_DARTS];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `permutation_orbit (p:(A#A)->A#A) d =
      permutation_orbit r d`
    (LABEL_TAC "d_unaffected") THENL
     [EXPAND_TAC "p" THEN
      REWRITE_TAC[rotation_split_permutation] THEN
      MATCH_MP_TAC(ISPECL
       [`r:(A#A)->A#A`; `graph_darts E:(A#A)->bool`;
        `a:A#A`; `b:A#A`; `d:A#A`]
       PERMUTATION_SWAP_UNAFFECTED_ORBIT) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `~(FST(e:A#A) = FST(a:A#A))`
    (LABEL_TAC "e_away_a") THENL
     [DISCH_THEN(LABEL_TAC "e_at_a") THEN
      USE_THEN "away" (MATCH_MP_TAC o NOT_ELIM) THEN
      TRANS_TAC EQ_TRANS `FST(e:A#A)` THEN
      CONJ_TAC THENL
       [USE_THEN "same_vertex" ACCEPT_TAC;
        USE_THEN "e_at_a" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `~(FST(e:A#A) = FST(b:A#A))`
    (LABEL_TAC "e_away_b") THENL
     [DISCH_THEN(LABEL_TAC "e_at_b") THEN
      USE_THEN "e_away_a" (MATCH_MP_TAC o NOT_ELIM) THEN
      TRANS_TAC EQ_TRANS `FST(b:A#A)` THEN
      CONJ_TAC THENL
       [USE_THEN "e_at_b" ACCEPT_TAC;
        USE_THEN "same_tail"
         (ACCEPT_TAC o GSYM)];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~((e:A#A) IN permutation_orbit r a) /\
      ~(e IN permutation_orbit r b)`
    (CONJUNCTS_THEN2
      (LABEL_TAC "e_not_a") (LABEL_TAC "e_not_b")) THENL
     [ASM_REWRITE_TAC[IN_OUTGOING_DARTS];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `permutation_orbit (p:(A#A)->A#A) e =
      permutation_orbit r e`
    (LABEL_TAC "e_unaffected") THENL
     [EXPAND_TAC "p" THEN
      REWRITE_TAC[rotation_split_permutation] THEN
      MATCH_MP_TAC(ISPECL
       [`r:(A#A)->A#A`; `graph_darts E:(A#A)->bool`;
        `a:A#A`; `b:A#A`; `e:A#A`]
       PERMUTATION_SWAP_UNAFFECTED_ORBIT) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `permutation_orbit (r:(A#A)->A#A) d =
      permutation_orbit r e`
    (LABEL_TAC "old_same") THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `d:A#A`; `e:A#A`]
       GRAPH_ROTATION_SAME_TAIL_ORBIT) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
  SUBGOAL_THEN
   `(e:A#A) IN permutation_orbit (p:(A#A)->A#A) d`
  MP_TAC THENL
   [USE_THEN "same_orbit" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_ACCEPT_TAC PERMUTATION_ORBIT_REFL;
    REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN
    DISCH_THEN ACCEPT_TAC]);;

let GRAPH_ROTATION_ROTATION_SPLIT = prove
 (`!V E r a b:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        a IN graph_darts E /\
        b IN graph_darts E /\
        ~(a = b) /\
        FST a = FST b
        ==> graph_rotation
             (rotation_split_edges
               E (rotation_split_permutation r a b) (FST a) b)
             (rotation_split_rotation
               E (rotation_split_permutation r a b) (FST a) b)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation a_dart b_dart distinct same_tail" THEN
  ABBREV_TAC `p:(A#A)->A#A = rotation_split_permutation r a b` THEN
  ABBREV_TAC
   `q:(A#A)->(A#bool)#(A#bool) =
      rotation_split_dart p (FST(a:A#A)) b` THEN
  ABBREV_TAC
   `D:(A#A)->bool = graph_darts (E:(A->bool)->bool)` THEN
  ABBREV_TAC
   `fe:((A#bool)->bool)->bool =
      rotation_split_edges E p (FST(a:A#A)) b` THEN
  ABBREV_TAC
   `s:((A#bool)#(A#bool))->(A#bool)#(A#bool) =
      rotation_split_rotation E p (FST(a:A#A)) b` THEN
  SUBGOAL_THEN `FINITE(D:(A#A)->bool)` (LABEL_TAC "finite_darts")
  THENL
   [EXPAND_TAC "D" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:(A#A)->A#A) permutes D`
  (LABEL_TAC "split_permutation") THENL
   [EXPAND_TAC "p" THEN EXPAND_TAC "D" THEN
    MATCH_MP_TAC ROTATION_SPLIT_PERMUTATION_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u v:A#A.
      u IN D /\ v IN D /\ (q:(A#A)->(A#bool)#(A#bool)) u = q v
      ==> u = v`
  (LABEL_TAC "q_injective") THENL
   [REPEAT GEN_TAC THEN INTRO_TAC "_ _ same" THEN
    USE_THEN "same" MP_TAC THEN EXPAND_TAC "q" THEN
    MATCH_ACCEPT_TAC ROTATION_SPLIT_DART_INJECTIVE;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_darts (fe:((A#bool)->bool)->bool) =
    IMAGE (q:(A#A)->(A#bool)#(A#bool)) D`
  (LABEL_TAC "dart_image") THENL
   [EXPAND_TAC "fe" THEN EXPAND_TAC "q" THEN EXPAND_TAC "D" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `p:(A#A)->A#A`; `FST(a:A#A)`; `b:A#A`]
     GRAPH_DARTS_ROTATION_SPLIT_EDGES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(s:((A#bool)#(A#bool))->(A#bool)#(A#bool)) =
    restricted_permutation_transport
      (p:(A#A)->A#A)
      (q:(A#A)->(A#bool)#(A#bool)) D`
  (LABEL_TAC "split_rotation") THENL
   [EXPAND_TAC "s" THEN EXPAND_TAC "q" THEN EXPAND_TAC "D" THEN
    REWRITE_TAC[rotation_split_rotation];
    ALL_TAC] THEN
  REWRITE_TAC[graph_rotation] THEN REPEAT CONJ_TAC THENL
   [USE_THEN "dart_image" SUBST1_TAC THEN
    USE_THEN "split_rotation" SUBST1_TAC THEN
    MATCH_MP_TAC RESTRICTED_PERMUTATION_TRANSPORT_PERMUTES THEN
    ASM_REWRITE_TAC[];
    X_GEN_TAC `z:(A#bool)#(A#bool)` THEN
    DISCH_THEN(LABEL_TAC "z_dart") THEN
    USE_THEN "z_dart" MP_TAC THEN
    USE_THEN "dart_image" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@d. representation d_member" THEN
    USE_THEN "representation" SUBST1_TAC THEN
    USE_THEN "split_rotation" (fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
     `restricted_permutation_transport
       (p:(A#A)->A#A)
       (q:(A#A)->(A#bool)#(A#bool)) D (q d) = q(p d)`
    SUBST1_TAC THENL
     [MATCH_MP_TAC RESTRICTED_PERMUTATION_TRANSPORT_IMAGE THEN
      ASM_REWRITE_TAC[];
      EXPAND_TAC "q" THEN
      REWRITE_TAC[FST_ROTATION_SPLIT_DART] THEN
      EXPAND_TAC "p" THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `r:(A#A)->A#A`; `a:A#A`; `b:A#A`; `d:A#A`]
       ROTATION_SPLIT_VERTEX_INVARIANT) THEN
      EXPAND_TAC "D" THEN ASM_REWRITE_TAC[]];
    MAP_EVERY X_GEN_TAC
     [`z:(A#bool)#(A#bool)`; `w:(A#bool)#(A#bool)`] THEN
    INTRO_TAC "z_dart w_dart same_vertex" THEN
    USE_THEN "z_dart" MP_TAC THEN
    USE_THEN "w_dart" MP_TAC THEN
    USE_THEN "dart_image" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@e. w_representation e_member" THEN
    INTRO_TAC "@d. z_representation d_member" THEN
    USE_THEN "z_representation" SUBST_ALL_TAC THEN
    USE_THEN "w_representation" SUBST_ALL_TAC THEN
    SUBGOAL_THEN
     `rotation_split_vertex
       (p:(A#A)->A#A) (FST(a:A#A)) b d =
      rotation_split_vertex p (FST(a:A#A)) b e`
    (LABEL_TAC "same_split_vertex") THENL
     [USE_THEN "same_vertex" MP_TAC THEN EXPAND_TAC "q" THEN
      REWRITE_TAC[FST_ROTATION_SPLIT_DART];
      ALL_TAC] THEN
    SUBGOAL_THEN `?n. ITER n (p:(A#A)->A#A) d = e`
    (X_CHOOSE_THEN `n:num` (LABEL_TAC "step")) THENL
     [EXPAND_TAC "p" THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `r:(A#A)->A#A`; `a:A#A`; `b:A#A`;
        `d:A#A`; `e:A#A`]
       ROTATION_SPLIT_VERTEX_FIBER_TRANSITIVE) THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "graph" ACCEPT_TAC;
        USE_THEN "rotation" ACCEPT_TAC;
        USE_THEN "a_dart" MP_TAC THEN EXPAND_TAC "D" THEN SIMP_TAC[];
        USE_THEN "b_dart" MP_TAC THEN EXPAND_TAC "D" THEN SIMP_TAC[];
        USE_THEN "distinct" ACCEPT_TAC;
        USE_THEN "same_tail" ACCEPT_TAC;
        USE_THEN "d_member" MP_TAC THEN EXPAND_TAC "D" THEN SIMP_TAC[];
        USE_THEN "e_member" MP_TAC THEN EXPAND_TAC "D" THEN SIMP_TAC[];
        USE_THEN "same_split_vertex" MP_TAC THEN
        EXPAND_TAC "p" THEN SIMP_TAC[]];
      ALL_TAC] THEN
    EXISTS_TAC `n:num` THEN
    USE_THEN "split_rotation" (fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPEC `n:num`
     (MATCH_MP
      (ISPECL
       [`p:(A#A)->A#A`; `q:(A#A)->(A#bool)#(A#bool)`;
        `D:(A#A)->bool`; `d:A#A`]
       RESTRICTED_PERMUTATION_TRANSPORT_ITER)
      (CONJ
       (ASSUME `(p:(A#A)->A#A) permutes D`)
       (CONJ
        (ASSUME
         `!u v:A#A.
            u IN D /\
            v IN D /\
            (q:(A#A)->(A#bool)#(A#bool)) u = q v
            ==> u = v`)
        (ASSUME `(d:A#A) IN D`))))) THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_FACE_SUCCESSOR_ROTATION_SPLIT = prove
 (`!V E p x b.
        finite_simple_graph (V:A->bool) E
        ==> graph_face_successor
             (rotation_split_edges E p x b)
             (rotation_split_rotation E p x b) =
            restricted_permutation_transport
              (p o graph_reverse_dart E)
              (rotation_split_dart p x b)
              (graph_darts E)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  ABBREV_TAC `D:(A#A)->bool = graph_darts (E:(A->bool)->bool)` THEN
  ABBREV_TAC
   `q:(A#A)->(A#bool)#(A#bool) =
      rotation_split_dart p x b` THEN
  ABBREV_TAC
   `fe:((A#bool)->bool)->bool =
      rotation_split_edges E p x b` THEN
  ABBREV_TAC
   `s:((A#bool)#(A#bool))->(A#bool)#(A#bool) =
      rotation_split_rotation E p x b` THEN
  SUBGOAL_THEN
   `graph_darts (fe:((A#bool)->bool)->bool) =
    IMAGE (q:(A#A)->(A#bool)#(A#bool)) D`
  (LABEL_TAC "dart_image") THENL
   [MAP_EVERY EXPAND_TAC ["fe"; "q"; "D"] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `p:(A#A)->A#A`; `x:A`; `b:A#A`]
     GRAPH_DARTS_ROTATION_SPLIT_EDGES) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u v:A#A.
      u IN D /\ v IN D /\ (q:(A#A)->(A#bool)#(A#bool)) u = q v
      ==> u = v`
  (LABEL_TAC "q_injective") THENL
   [REPEAT GEN_TAC THEN INTRO_TAC "_ _ same" THEN
    USE_THEN "same" MP_TAC THEN EXPAND_TAC "q" THEN
    MATCH_ACCEPT_TAC ROTATION_SPLIT_DART_INJECTIVE;
    ALL_TAC] THEN
  REWRITE_TAC[FUN_EQ_THM] THEN
  X_GEN_TAC `z:(A#bool)#(A#bool)` THEN
  ASM_CASES_TAC
   `(z:(A#bool)#(A#bool)) IN
    IMAGE (q:(A#A)->(A#bool)#(A#bool)) D` THENL
   [FIRST_X_ASSUM MP_TAC THEN REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@d. representation d_member" THEN
    USE_THEN "representation" SUBST1_TAC THEN
    SUBGOAL_THEN `reverse_dart(d:A#A) IN D`
    (LABEL_TAC "reverse_member") THENL
     [EXPAND_TAC "D" THEN ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_reverse_dart (fe:((A#bool)->bool)->bool)
       ((q:(A#A)->(A#bool)#(A#bool)) d) =
      q(reverse_dart d)`
    (LABEL_TAC "encoded_reverse") THENL
     [MATCH_MP_TAC EQ_TRANS THEN
      EXISTS_TAC
       `reverse_dart
         ((q:(A#A)->(A#bool)#(A#bool)) d)` THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC GRAPH_REVERSE_DART_IN THEN
        USE_THEN "dart_image" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `d:A#A` THEN
        ASM_REWRITE_TAC[];
        EXPAND_TAC "q" THEN
        CONV_TAC SYM_CONV THEN
        MATCH_ACCEPT_TAC ROTATION_SPLIT_DART_REVERSE];
      ALL_TAC] THEN
    EXPAND_TAC "s" THEN
    REWRITE_TAC[graph_face_successor; o_THM;
                rotation_split_rotation] THEN
    USE_THEN "encoded_reverse" (fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC EQ_TRANS THEN
    EXISTS_TAC
     `(q:(A#A)->(A#bool)#(A#bool))
       ((p:(A#A)->A#A) (reverse_dart(d:A#A)))` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC RESTRICTED_PERMUTATION_TRANSPORT_IMAGE THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC EQ_TRANS THEN
      EXISTS_TAC
       `(q:(A#A)->(A#bool)#(A#bool))
         (((p:(A#A)->A#A) o graph_reverse_dart E) d)` THEN
      CONJ_TAC THENL
       [REWRITE_TAC[o_THM] THEN
        AP_TERM_TAC THEN AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
        MATCH_MP_TAC GRAPH_REVERSE_DART_IN THEN
        USE_THEN "d_member" MP_TAC THEN EXPAND_TAC "D" THEN
        SIMP_TAC[];
        CONV_TAC SYM_CONV THEN
        MATCH_MP_TAC RESTRICTED_PERMUTATION_TRANSPORT_IMAGE THEN
        ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(z IN graph_darts (fe:((A#bool)->bool)->bool))`
  (LABEL_TAC "not_dart") THENL
   [USE_THEN "dart_image" (fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXPAND_TAC "s" THEN
  REWRITE_TAC[graph_face_successor; o_THM;
              rotation_split_rotation] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `graph_reverse_dart (fe:((A#bool)->bool)->bool) z = z`
  (fun th -> REWRITE_TAC[th]) THENL
   [MATCH_MP_TAC GRAPH_REVERSE_DART_OUT THEN
    USE_THEN "not_dart" ACCEPT_TAC;
    MATCH_MP_TAC EQ_TRANS THEN
    EXISTS_TAC `z:(A#bool)#(A#bool)` THEN CONJ_TAC THENL
     [MATCH_MP_TAC RESTRICTED_PERMUTATION_TRANSPORT_OUTSIDE THEN
      ASM_MESON_TAC[];
      CONV_TAC SYM_CONV THEN
      MATCH_MP_TAC RESTRICTED_PERMUTATION_TRANSPORT_OUTSIDE THEN
      ASM_MESON_TAC[]]]);;

let CARD_GRAPH_FACES_ROTATION_SPLIT = prove
 (`!V E p x b.
        finite_simple_graph (V:A->bool) E /\
        p permutes graph_darts E
        ==> CARD
             (graph_faces
               (rotation_split_edges E p x b)
               (rotation_split_rotation E p x b)) =
            CARD
             (permutation_orbits
               (p o graph_reverse_dart E) (graph_darts E))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph permutation" THEN
  REWRITE_TAC[GRAPH_FACES_AS_PERMUTATION_ORBITS] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `p:(A#A)->A#A`; `x:A`; `b:A#A`]
   GRAPH_FACE_SUCCESSOR_ROTATION_SPLIT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
