let CARD_GRAPH_FACES_ROTATION_SPLIT_SAME_FACE = prove
 (`!V E r a b:A#A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        a IN graph_darts E /\
        b IN graph_darts E /\
        ~(a = b) /\
        FST a = FST b /\
        graph_face E r a = graph_face E r b
        ==> CARD
             (graph_faces
               (rotation_split_edges
                 E (rotation_split_permutation r a b) (FST a) b)
               (rotation_split_rotation
                 E (rotation_split_permutation r a b) (FST a) b)) =
            CARD(graph_faces E r) + 1`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph rotation a_dart b_dart distinct same_tail same_face" THEN
  ABBREV_TAC `D:(A#A)->bool = graph_darts (E:(A->bool)->bool)` THEN
  ABBREV_TAC `f:(A#A)->A#A = graph_face_successor E r` THEN
  ABBREV_TAC `p:(A#A)->A#A = rotation_split_permutation r a b` THEN
  SUBGOAL_THEN `FINITE(D:(A#A)->bool)` (LABEL_TAC "finite_darts")
  THENL
   [EXPAND_TAC "D" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(f:(A#A)->A#A) permutes D`
  (LABEL_TAC "face_permutation") THENL
   [EXPAND_TAC "f" THEN EXPAND_TAC "D" THEN
    MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    USE_THEN "rotation" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:(A#A)->A#A) permutes D`
  (LABEL_TAC "split_permutation") THENL
   [EXPAND_TAC "p" THEN EXPAND_TAC "D" THEN
    MATCH_MP_TAC ROTATION_SPLIT_PERMUTATION_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbit (f:(A#A)->A#A) a =
    permutation_orbit f b`
  (LABEL_TAC "same_face_orbit") THENL
   [MAP_EVERY EXPAND_TAC ["f"; "D"] THEN
    REWRITE_TAC[GSYM GRAPH_FACE_AS_PERMUTATION_ORBIT] THEN
    USE_THEN "same_face" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:(A#A)->A#A) o graph_reverse_dart E =
    swap(a,b) o f`
  (LABEL_TAC "split_successor") THENL
   [MAP_EVERY EXPAND_TAC ["p"; "f"] THEN
    REWRITE_TAC[rotation_split_permutation;
                graph_face_successor; o_ASSOC];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `p:(A#A)->A#A`; `FST(a:A#A)`; `b:A#A`]
   CARD_GRAPH_FACES_ROTATION_SPLIT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "split_successor" (fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[GRAPH_FACES_AS_PERMUTATION_ORBITS] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
   [`f:(A#A)->A#A`; `D:(A#A)->bool`; `a:A#A`; `b:A#A`]
   PERMUTATION_ORBITS_SWAP_SAME) THEN
  ASM_REWRITE_TAC[]);;

