let ROTATION_SPLIT_VERTICES_EQ = prove
 (`!V E r a b:A#A.
        finite_simple_graph V E /\
        connected_graph V E /\
        graph_rotation E r /\
        a IN graph_darts E /\
        b IN graph_darts E /\
        ~(a = b) /\
        FST a = FST b
        ==> rotation_split_vertices
              E (rotation_split_permutation r a b) (FST a) b =
            (FST a,T) INSERT IMAGE (\v:A. (v,F)) V`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph connected rotation a_dart b_dart distinct same_tail" THEN
  ABBREV_TAC `p:(A#A)->A#A = rotation_split_permutation r a b` THEN
  SUBGOAL_THEN `FINITE(graph_darts E:(A#A)->bool)`
  (LABEL_TAC "finite_darts") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(p:(A#A)->A#A) permutes graph_darts E`
  (LABEL_TAC "split_permutation") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC ROTATION_SPLIT_PERMUTATION_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(permutation_orbit (p:(A#A)->A#A) a =
      permutation_orbit p b)`
  (LABEL_TAC "split_orbits") THENL
   [EXPAND_TAC "p" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `r:(A#A)->A#A`; `a:A#A`; `b:A#A`]
     ROTATION_SPLIT_PERMUTATION_ORBITS_DISTINCT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((a:A#A) IN permutation_orbit p b)`
  (LABEL_TAC "a_false") THENL
   [DISCH_THEN(LABEL_TAC "a_in_b") THEN
    USE_THEN "split_orbits" (MATCH_MP_TAC o NOT_ELIM) THEN
    MP_TAC(ISPECL
     [`p:(A#A)->A#A`; `graph_darts E:(A#A)->bool`;
      `b:A#A`; `a:A#A`]
     PERMUTATION_ORBIT_EQ) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(E:(A->bool)->bool = {})`
  (LABEL_TAC "edges_nonempty") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "a_dart" MP_TAC THEN
    REWRITE_TAC[graph_darts; IN_ELIM_THM; NOT_IN_EMPTY];
    ALL_TAC] THEN
  REWRITE_TAC[rotation_split_vertices; EXTENSION] THEN
  X_GEN_TAC `z:A#bool` THEN REWRITE_TAC[IN_IMAGE; IN_INSERT] THEN
  EQ_TAC THENL
   [INTRO_TAC "@d. representation d_dart" THEN
    USE_THEN "representation" SUBST1_TAC THEN
    SUBGOAL_THEN `FST(d:A#A) IN V`
    (LABEL_TAC "tail_vertex") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `d:A#A`]
       FINITE_SIMPLE_GRAPH_DART_FST) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    EXPAND_TAC "p" THEN REWRITE_TAC[rotation_split_vertex] THEN
    ASM_CASES_TAC
     `FST(d:A#A) = FST(a:A#A) /\
      d IN permutation_orbit
            (rotation_split_permutation r a b) b` THENL
     [DISJ1_TAC THEN ASM_REWRITE_TAC[PAIR_EQ];
      DISJ2_TAC THEN EXISTS_TAC `FST(d:A#A)` THEN
      ASM_REWRITE_TAC[PAIR_EQ]];
    DISCH_THEN(DISJ_CASES_THEN2
      (LABEL_TAC "extra") (X_CHOOSE_THEN `v:A`
       (CONJUNCTS_THEN2 (LABEL_TAC "base") (LABEL_TAC "v_vertex"))))
    THENL
     [USE_THEN "extra" SUBST1_TAC THEN
      EXISTS_TAC `b:A#A` THEN ASM_REWRITE_TAC[] THEN
      EXPAND_TAC "p" THEN
      REWRITE_TAC[rotation_split_vertex; PAIR_EQ] THEN
      ASM_REWRITE_TAC[PERMUTATION_ORBIT_REFL];
      ALL_TAC] THEN
    USE_THEN "base" SUBST1_TAC THEN
    ASM_CASES_TAC `(v:A) = FST(a:A#A)` THENL
     [FIRST_X_ASSUM SUBST_ALL_TAC THEN
      EXISTS_TAC `a:A#A` THEN ASM_REWRITE_TAC[] THEN
      EXPAND_TAC "p" THEN
      REWRITE_TAC[rotation_split_vertex; PAIR_EQ] THEN
      ASM_REWRITE_TAC[];
      FIRST_X_ASSUM(LABEL_TAC "v_away")] THEN
    MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `v:A`]
     CONNECTED_GRAPH_VERTEX_HAS_OUTGOING_DART) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:A#A` (LABEL_TAC "outgoing")) THEN
    USE_THEN "outgoing" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN
    INTRO_TAC "d_dart d_tail" THEN
    EXISTS_TAC `d:A#A` THEN ASM_REWRITE_TAC[] THEN
    EXPAND_TAC "p" THEN
    REWRITE_TAC[rotation_split_vertex; PAIR_EQ] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

let CARD_ROTATION_SPLIT_VERTICES = prove
 (`!V E r a b:A#A.
        finite_simple_graph V E /\
        connected_graph V E /\
        graph_rotation E r /\
        a IN graph_darts E /\
        b IN graph_darts E /\
        ~(a = b) /\
        FST a = FST b
        ==> CARD
             (rotation_split_vertices
               E (rotation_split_permutation r a b) (FST a) b) =
            CARD V + 1`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph connected rotation a_dart b_dart distinct same_tail" THEN
  SUBGOAL_THEN
   `rotation_split_vertices
      E (rotation_split_permutation r a b) (FST a) b =
    (FST a,T) INSERT IMAGE (\v:A. (v,F)) V`
  SUBST1_TAC THENL
   [MATCH_MP_TAC ROTATION_SPLIT_VERTICES_EQ THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite_vertices") THENL
   [USE_THEN "graph"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[finite_simple_graph]);
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(IMAGE (\v:A. (v,F)) V)`
  (LABEL_TAC "finite_base") THENL
   [MATCH_MP_TAC FINITE_IMAGE THEN
    USE_THEN "finite_vertices" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((FST(a:A#A),T) IN IMAGE (\v:A. (v,F)) V)`
  (LABEL_TAC "extra_fresh") THENL
   [REWRITE_TAC[IN_IMAGE; PAIR_EQ] THEN MESON_TAC[];
    ASM_SIMP_TAC[CARD_CLAUSES] THEN
    SUBGOAL_THEN
     `CARD(IMAGE (\v:A. (v,F)) V) = CARD(V:A->bool)`
    SUBST1_TAC THENL
     [MATCH_MP_TAC CARD_IMAGE_INJ THEN
      ASM_REWRITE_TAC[PAIR_EQ] THEN MESON_TAC[];
      ARITH_TAC]]);;

let ROTATION_SPLIT_EDGE = prove
 (`!E p x b d:A#A.
        d IN graph_darts E
        ==> {rotation_split_vertex p x b d,
             rotation_split_vertex p x b (reverse_dart d)}
            IN rotation_split_edges E p x b`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "dart") THEN
  REWRITE_TAC[rotation_split_edges; IN_IMAGE] THEN
  EXISTS_TAC `d:A#A` THEN ASM_REWRITE_TAC[o_THM; dart_edge;
    FST_ROTATION_SPLIT_DART; SND_ROTATION_SPLIT_DART]);;

let ROTATION_SPLIT_VERTEX_REACHES_BASE = prove
 (`!V E p x b d:A#A.
        finite_simple_graph V E /\
        d IN graph_darts E
        ==> ?y.
              y IN V DELETE x /\
              graph_reachable
                (rotation_split_edges E p x b)
                (rotation_split_vertex p x b d) (y,F)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph dart" THEN
  SUBGOAL_THEN
   `FST(d:A#A) IN V /\ SND d IN V /\ ~(FST d = SND d)`
  (CONJUNCTS_THEN2 (LABEL_TAC "tail_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "head_vertex")
    (LABEL_TAC "endpoints_distinct"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `FST(d:A#A)`; `SND(d:A#A)`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[PAIR];
    ALL_TAC] THEN
  ASM_CASES_TAC `FST(d:A#A) = x` THENL
   [FIRST_X_ASSUM(LABEL_TAC "tail_is_x") THEN
    EXISTS_TAC `SND(d:A#A)` THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
    SUBGOAL_THEN
     `rotation_split_vertex
       (p:(A#A)->A#A) x b (reverse_dart d) =
      (SND d,F)`
    (fun th -> REWRITE_TAC[GSYM th]) THENL
     [REWRITE_TAC[rotation_split_vertex;
                  FST_REVERSE_DART; PAIR_EQ] THEN
      ASM_MESON_TAC[];
      MATCH_MP_TAC ROTATION_SPLIT_EDGE THEN
      USE_THEN "dart" ACCEPT_TAC];
    FIRST_X_ASSUM(LABEL_TAC "tail_away")] THEN
  EXISTS_TAC `FST(d:A#A)` THEN CONJ_TAC THENL
   [ASM_REWRITE_TAC[IN_DELETE];
    SUBGOAL_THEN
     `rotation_split_vertex (p:(A#A)->A#A) x b d =
      (FST d,F)`
    SUBST1_TAC THENL
     [REWRITE_TAC[rotation_split_vertex; PAIR_EQ] THEN
      ASM_REWRITE_TAC[];
      MATCH_ACCEPT_TAC GRAPH_REACHABLE_REFL]]);;

let ROTATION_SPLIT_BASE_REACHABLE = prove
 (`!V E p x b u v:A.
        graph_reachable
          (induced_subgraph_edges E (V DELETE x)) u v
        ==> graph_reachable
              (rotation_split_edges E p x b) (u,F) (v,F)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[graph_reachable] THEN
  MATCH_MP_TAC
   (REWRITE_RULE[GSYM RIGHT_FORALL_IMP_THM]
    (BETA_RULE(ISPECL
     [`\y z:A. {y,z} IN induced_subgraph_edges E (V DELETE x)`;
      `\y z:A.
         RTC
          (\w t:A#bool. {w,t} IN rotation_split_edges E p x b)
          (y,F) (z,F)`]
     RTC_INDUCT))) THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`y:A`; `z:A`] THEN
    REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "edge") THEN
    MATCH_MP_TAC RTC_INC THEN
    USE_THEN "edge" MP_TAC THEN
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES;
                INSERT_SUBSET; SING_SUBSET; IN_DELETE] THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    SUBGOAL_THEN
     `rotation_split_vertex (p:(A#A)->A#A) x b (y,z) = (y,F)`
    (fun th -> REWRITE_TAC[GSYM th]) THENL
     [REWRITE_TAC[rotation_split_vertex; FST; PAIR_EQ] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `rotation_split_vertex
       (p:(A#A)->A#A) x b (reverse_dart(y,z)) = (z,F)`
    (fun th -> REWRITE_TAC[GSYM th]) THENL
     [REWRITE_TAC[REVERSE_DART_PAIR; rotation_split_vertex;
                  FST; PAIR_EQ] THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC ROTATION_SPLIT_EDGE THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS]];
    REWRITE_TAC[RTC_REFL];
    MATCH_ACCEPT_TAC RTC_TRANS]);;

let CONNECTED_GRAPH_ROTATION_SPLIT = prove
 (`!V E p x b.
        finite_simple_graph (V:A->bool) E /\
        connected_graph
          (V DELETE x) (induced_subgraph_edges E (V DELETE x))
        ==> connected_graph
             (rotation_split_vertices E p x b)
