   [`V:A->bool`; `E:(A->bool)->bool`;
    `p:(A#A)->A#A`; `x:A`; `b:A#A`; `d:A#A`]
   ROTATION_SPLIT_VERTEX_REACHES_BASE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@u. u_vertex d_to_u" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `p:(A#A)->A#A`; `x:A`; `b:A#A`; `e:A#A`]
   ROTATION_SPLIT_VERTEX_REACHES_BASE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@v. v_vertex e_to_v" THEN
  SUBGOAL_THEN
   `graph_reachable
     (induced_subgraph_edges E (V DELETE x)) (u:A) v`
  (LABEL_TAC "base_path") THENL
   [USE_THEN "deleted_connected" MP_TAC THEN
    REWRITE_TAC[connected_graph] THEN ASM_MESON_TAC[];
