    MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
    USE_THEN "e_to_v" ACCEPT_TAC]);;

let EULER_PLANAR_ROTATION_VERTEX_SPLIT_DISTINCT_FACES = prove
 (`!V E r a b:A#A.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        a IN graph_darts E /\
        b IN graph_darts E /\
        ~(a = b) /\
        FST a = FST b /\
        ~(graph_face E r a = graph_face E r b)
        ==> euler_planar_rotation
             (rotation_split_vertices
               E (rotation_split_permutation r a b) (FST a) b)
             (rotation_split_edges
               E (rotation_split_permutation r a b) (FST a) b)
             (rotation_split_rotation
               E (rotation_split_permutation r a b) (FST a) b)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected a_dart b_dart distinct same_tail distinct_faces" THEN
  USE_THEN "euler" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph rotation formula" THEN
  ABBREV_TAC `p:(A#A)->A#A = rotation_split_permutation r a b` THEN
  ABBREV_TAC
   `W:(A#bool)->bool =
      rotation_split_vertices E p (FST(a:A#A)) b` THEN
  ABBREV_TAC
   `fe:((A#bool)->bool)->bool =
      rotation_split_edges E p (FST(a:A#A)) b` THEN
  ABBREV_TAC
   `s:((A#bool)#(A#bool))->(A#bool)#(A#bool) =
      rotation_split_rotation E p (FST(a:A#A)) b` THEN
  SUBGOAL_THEN
   `finite_simple_graph
     (W:(A#bool)->bool) (fe:((A#bool)->bool)->bool)`
  (LABEL_TAC "split_graph") THENL
   [MAP_EVERY EXPAND_TAC ["W"; "fe"] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `p:(A#A)->A#A`;
      `FST(a:A#A)`; `b:A#A`]
     FINITE_SIMPLE_GRAPH_ROTATION_SPLIT) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_rotation
     (fe:((A#bool)->bool)->bool)
     (s:((A#bool)#(A#bool))->(A#bool)#(A#bool))`
  (LABEL_TAC "split_rotation") THENL
   [MAP_EVERY EXPAND_TAC ["fe"; "s"; "p"] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `r:(A#A)->A#A`; `a:A#A`; `b:A#A`]
     GRAPH_ROTATION_ROTATION_SPLIT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(W:(A#bool)->bool) = CARD(V:A->bool) + 1`
  (LABEL_TAC "vertex_count") THENL
   [MAP_EVERY EXPAND_TAC ["W"; "p"] THEN
    MATCH_MP_TAC CARD_ROTATION_SPLIT_VERTICES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(fe:((A#bool)->bool)->bool) = CARD(E:(A->bool)->bool)`
  (LABEL_TAC "edge_count") THENL
   [MAP_EVERY EXPAND_TAC ["fe"; "p"] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `rotation_split_permutation r a b:(A#A)->A#A`;
      `FST(a:A#A)`; `b:A#A`]
     CARD_ROTATION_SPLIT_EDGES) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(graph_faces (E:(A->bool)->bool) (r:(A#A)->A#A)) =
    CARD
     (graph_faces
       (fe:((A#bool)->bool)->bool)
       (s:((A#bool)#(A#bool))->(A#bool)#(A#bool))) + 1`
  (LABEL_TAC "face_count") THENL
   [MAP_EVERY EXPAND_TAC ["fe"; "s"; "p"] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `r:(A#A)->A#A`; `a:A#A`; `b:A#A`]
     CARD_GRAPH_FACES_ROTATION_SPLIT_DISTINCT_FACES) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(E:(A->bool)->bool = {})`
  (LABEL_TAC "edges_nonempty") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "a_dart" MP_TAC THEN
    REWRITE_TAC[graph_darts; IN_ELIM_THM; NOT_IN_EMPTY];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{rotation_split_vertex (p:(A#A)->A#A) (FST(a:A#A)) b a,
     rotation_split_vertex p (FST(a:A#A)) b (reverse_dart a)}
    IN fe`
  (LABEL_TAC "split_edge") THENL
   [EXPAND_TAC "fe" THEN MATCH_MP_TAC ROTATION_SPLIT_EDGE THEN
    USE_THEN "a_dart" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(fe:((A#bool)->bool)->bool = {})`
  (LABEL_TAC "split_edges_nonempty") THENL
   [USE_THEN "split_edge" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "split_graph" ACCEPT_TAC;
    USE_THEN "split_rotation" ACCEPT_TAC;
    REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "formula" MP_TAC THEN
    REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
    ASM_REWRITE_TAC[] THEN
    ASM_ARITH_TAC]);;

