let VERTEX_2_CONNECTED_EULER_PLANAR_FACE_CYCLIC_WALK = prove
 (`!V E r d:A#A.
        vertex_k_connected_graph 2 V E /\
        euler_planar_rotation V E r /\
        d IN graph_darts E
        ==> ?q:num->A.
              3 <= CARD(graph_face E r d) /\
              INJ q (cyclic_indices (CARD(graph_face E r d))) (:A) /\
              q 0 = FST d /\
              q 1 = SND d /\
              (!i. i < CARD(graph_face E r d)
                   ==> ITER i (graph_face_successor E r) d =
                       cyclic_dart q (CARD(graph_face E r d)) i) /\
              graph_face E r d =
                cyclic_darts q (CARD(graph_face E r d)) /\
              cyclic_edges q (CARD(graph_face E r d)) SUBSET E /\
              cyclic_face_successors
                E r q (CARD(graph_face E r d))`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected2 euler dart" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `2` THEN USE_THEN "connected2" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `connected_graph (V:A->bool) E`
  (LABEL_TAC "connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`2`; `V:A->bool`; `E:(A->bool)->bool`]
     VERTEX_K_CONNECTED_GRAPH_CONNECTED) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `graph_rotation E (r:(A#A)->A#A)`
  (LABEL_TAC "rotation") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `3 <= CARD(V:A->bool)` (LABEL_TAC "vertices_large")
  THENL
   [MP_TAC(ISPECL
     [`2`; `V:A->bool`; `E:(A->bool)->bool`]
     VERTEX_K_CONNECTED_GRAPH_CARD) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `r:(A#A)->A#A`; `d:A#A`]
   CONNECTED_GRAPH_FACE_CYCLIC_WALK) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@q. face_large start next enumeration darts_injective \
        face edges successors" THEN
  SUBGOAL_THEN
   `INJ (q:num->A)
        (cyclic_indices
          (CARD
            (graph_face
              (E:(A->bool)->bool)
              (r:(A#A)->A#A) (d:A#A)))) (:A)`
  (LABEL_TAC "vertices_injective") THENL
   [REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
    INTRO_TAC "i_index j_index same_vertex" THEN
    ABBREV_TAC
     `n:num =
        CARD
         (graph_face
           (E:(A->bool)->bool) (r:(A#A)->A#A) (d:A#A))` THEN
    ABBREV_TAC `di:A#A = cyclic_dart q n i` THEN
    ABBREV_TAC `dj:A#A = cyclic_dart q n j` THEN
    SUBGOAL_THEN `(di:A#A) IN graph_face E r d`
    (LABEL_TAC "di_face") THENL
     [USE_THEN "face" (fun th -> REWRITE_TAC[th]) THEN
      EXPAND_TAC "di" THEN EXPAND_TAC "n" THEN
      REWRITE_TAC[IN_CYCLIC_DARTS_CYCLIC_DART] THEN
      EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(dj:A#A) IN graph_face E r d`
    (LABEL_TAC "dj_face") THENL
     [USE_THEN "face" (fun th -> REWRITE_TAC[th]) THEN
      EXPAND_TAC "dj" THEN EXPAND_TAC "n" THEN
      REWRITE_TAC[IN_CYCLIC_DARTS_CYCLIC_DART] THEN
      EXISTS_TAC `j:num` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(di:A#A) IN graph_darts E`
    (LABEL_TAC "di_dart") THENL
     [MATCH_MP_TAC(REWRITE_RULE[SUBSET]
       (MATCH_MP
        (ISPECL
         [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
         GRAPH_FACE_SUBSET_DARTS)
        (CONJ
         (ASSUME `graph_rotation E (r:(A#A)->A#A)`)
