     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `d:A#A`; `dj:A#A`]
       GRAPH_FACE_EQ) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `FST(di:A#A) = FST(dj:A#A)`
    (LABEL_TAC "same_tail") THENL
     [MAP_EVERY EXPAND_TAC ["di"; "dj"] THEN
      REWRITE_TAC[cyclic_dart; FST] THEN
      USE_THEN "same_vertex" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(di:A#A) = dj`
    (LABEL_TAC "same_dart") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `r:(A#A)->A#A`; `di:A#A`; `dj:A#A`]
       VERTEX_2_CONNECTED_EULER_PLANAR_ROTATION_FACE_TAIL_INJECTIVE) THEN
      ASM_REWRITE_TAC[] THEN
      TRANS_TAC EQ_TRANS
       `graph_face
         (E:(A->bool)->bool) (r:(A#A)->A#A) (d:A#A)` THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "darts_injective" MP_TAC THEN
    REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXPAND_TAC ["di"; "dj"; "n"] THEN
    USE_THEN "same_dart" ACCEPT_TAC;
    ALL_TAC] THEN
  EXISTS_TAC `q:num->A` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "face" ACCEPT_TAC);;

(* ------------------------------------------------------------------------- *)
(* The facial cycle exposed by deleting a vertex.                            *)
(*                                                                           *)
(* In a 3-connected planar graph, deleting a vertex leaves a 2-connected     *)
(* graph.  The incident faces then coalesce into one face whose boundary is  *)
(* a simple cycle containing every former neighbor.  The following lemmas    *)
(* develop the rotation-system form of that observation.                     *)
(* ------------------------------------------------------------------------- *)

let CONNECTED_GRAPH_FAN_DELETE_PREFIX_OF_DELETE_VERTEX = prove
 (`!V:A->bool. !E:(A->bool)->bool. !x:A. !w:num->A. !m t.
        finite_simple_graph V E /\
        x IN V /\
        connected_graph
          (V DELETE x) (induced_subgraph_edges E (V DELETE x)) /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        t < m
        ==> connected_graph V (fan_delete_edges x w E t)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph x_vertex deleted_connected injective avoids spokes bound" THEN
  SUBGOAL_THEN `{x:A,(w:num->A)t} IN E`
  (LABEL_TAC "anchor_edge") THENL
   [USE_THEN "spokes" MATCH_MP_TAC THEN
    USE_THEN "bound" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(w:num->A) t IN V DELETE x`
  (LABEL_TAC "anchor_vertex") THENL
   [REWRITE_TAC[IN_DELETE] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `x:A`; `(w:num->A)t`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[IN_GRAPH_DARTS];
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
         (CONJUNCTS_THEN2 (LABEL_TAC "w_vertex") (K ALL_TAC))) THEN
        USE_THEN "w_vertex" ACCEPT_TAC];
      USE_THEN "avoids" MATCH_MP_TAC THEN
      USE_THEN "bound" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph
     (x INSERT (V DELETE x):A->bool)
     ({x,(w:num->A)t} INSERT
      induced_subgraph_edges E (V DELETE x))`
  (LABEL_TAC "base_connected") THENL
   [MATCH_MP_TAC CONNECTED_GRAPH_INSERT_EDGE_VERTEX THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph
     (V:A->bool)
     ({x,(w:num->A)t} INSERT
      induced_subgraph_edges E (V DELETE x))`
  (LABEL_TAC "connected") THENL
   [USE_THEN "base_connected" (fun bth ->
     ACCEPT_TAC(REWRITE_RULE
      [MATCH_MP
        (ISPECL [`x:A`; `V:A->bool`] INSERT_DELETE)
        (ASSUME `(x:A) IN V`)] bth));
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`;
    `{x:A,(w:num->A)t} INSERT
      induced_subgraph_edges E (V DELETE x):(A->bool)->bool`;
    `fan_delete_edges x w E t:(A->bool)->bool`]
   CONNECTED_GRAPH_MONO) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[SUBSET; IN_INSERT] THEN
  X_GEN_TAC `e:A->bool` THEN
  DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "anchor")
    (LABEL_TAC "old_edge")) THENL
   [USE_THEN "anchor" SUBST1_TAC THEN
    MATCH_MP_TAC(ISPECL
     [`x:A`; `w:num->A`; `E:(A->bool)->bool`;
      `m:num`; `t:num`; `t:num`]
     FAN_DELETE_EDGE_REMAINS) THEN
    ASM_REWRITE_TAC[LE_REFL];
    USE_THEN "old_edge" MP_TAC THEN
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    INTRO_TAC "edge subset" THEN
    MATCH_MP_TAC FAN_DELETE_NONINCIDENT_EDGE_REMAINS THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "subset" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
    DISCH_THEN(MP_TAC o SPEC `x:A`) THEN
    REWRITE_TAC[IN_DELETE] THEN ITAUT_TAC]);;

let FAN_DELETE_NEXT_EDGE_REMAINS = prove
 (`!E:(A->bool)->bool. !x:A. !w:num->A. !m t.
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        t < m
        ==> t < m /\
            {x,w t} IN fan_delete_edges x w E t`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "injective avoids spokes bound" THEN
  CONJ_TAC THENL
   [USE_THEN "bound" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`x:A`; `w:num->A`; `E:(A->bool)->bool`;
      `m:num`; `t:num`; `t:num`]
     FAN_DELETE_EDGE_REMAINS) THEN
    ASM_REWRITE_TAC[LE_REFL]]);;

let CONNECTED_GRAPH_FAN_DELETE_PREFIX_OF_DELETE_VERTEX_DATA = prove
 (`!V:A->bool. !E:(A->bool)->bool. !x:A. !w:num->A. !m t.
        finite_simple_graph V E /\
        x IN V /\
        connected_graph
          (V DELETE x) (induced_subgraph_edges E (V DELETE x)) /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        t < m
        ==> t < m /\
            connected_graph V (fan_delete_edges x w E t)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "data") THEN
  CONJ_TAC THENL
   [USE_THEN "data" MP_TAC THEN MESON_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `x:A`;
      `w:num->A`; `m:num`; `t:num`]
     CONNECTED_GRAPH_FAN_DELETE_PREFIX_OF_DELETE_VERTEX) THEN
    USE_THEN "data" ACCEPT_TAC]);;

let EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX_OF_DELETE_VERTEX = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !m t.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        x IN V /\
        connected_graph
          (V DELETE x) (induced_subgraph_edges E (V DELETE x)) /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        t < m
        ==> euler_planar_rotation
             V (fan_delete_edges x w E t)
             (fan_delete_rotation x w r t) /\
            connected_graph V (fan_delete_edges x w E t)`,
  REPEAT GEN_TAC THEN SPEC_TAC(`t:num`,`t:num`) THEN
  INDUCT_TAC THENL
   [INTRO_TAC
     "euler connected x_vertex deleted_connected injective avoids \
      spokes bound" THEN
    ASM_REWRITE_TAC[fan_delete_edges; fan_delete_rotation];
    POP_ASSUM(LABEL_TAC "induction") THEN
    INTRO_TAC
     "euler connected x_vertex deleted_connected injective avoids \
      spokes new_bound" THEN
    SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
    (LABEL_TAC "graph") THENL
     [USE_THEN "euler" MP_TAC THEN
      REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(t:num) < m` (LABEL_TAC "old_bound") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `euler_planar_rotation
       (V:A->bool) (fan_delete_edges x w E t)
       (fan_delete_rotation x w r t) /\
      connected_graph V (fan_delete_edges x w E t)`
    (CONJUNCTS_THEN2 (LABEL_TAC "old_euler")
      (LABEL_TAC "old_connected")) THENL
     [USE_THEN "induction" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{x:A,(w:num->A)t} IN fan_delete_edges x w E t`
    (LABEL_TAC "deleted_edge") THENL
     [MATCH_MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`;
        `m:num`; `t:num`; `t:num`]
       FAN_DELETE_EDGE_REMAINS) THEN
      ASM_REWRITE_TAC[LE_REFL];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `connected_graph (V:A->bool) (fan_delete_edges x w E (SUC t))`
    (LABEL_TAC "new_connected") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `x:A`;
       `w:num->A`; `m:num`; `SUC t`]
       CONNECTED_GRAPH_FAN_DELETE_PREFIX_OF_DELETE_VERTEX) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `euler_planar_rotation
       (V:A->bool) (fan_delete_edges x w E (SUC t))
       (fan_delete_rotation x w r (SUC t))`
    (LABEL_TAC "new_euler") THENL
     [REWRITE_TAC[fan_delete_edges; fan_delete_rotation] THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`;
        `fan_delete_edges
          (x:A) (w:num->A) (E:(A->bool)->bool) t`;
        `fan_delete_rotation
          (x:A) (w:num->A) (r:(A#A)->A#A) t`;
        `x:A`; `(w:num->A)t`]
       EULER_PLANAR_ROTATION_DELETE_EDGE_CONNECTED) THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "old_euler" ACCEPT_TAC;
        USE_THEN "deleted_edge" ACCEPT_TAC;
        USE_THEN "new_connected" MP_TAC THEN
        REWRITE_TAC[fan_delete_edges] THEN DISCH_THEN ACCEPT_TAC];
      ASM_REWRITE_TAC[]]]);;

let EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX_OF_DELETE_VERTEX_GRAPH_DATA =
 prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !m t.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        x IN V /\
        connected_graph
          (V DELETE x) (induced_subgraph_edges E (V DELETE x)) /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        t < m
        ==> finite_simple_graph V (fan_delete_edges x w E t) /\
            graph_rotation
              (fan_delete_edges x w E t)
              (fan_delete_rotation x w r t)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "data") THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
     `x:A`; `w:num->A`; `m:num`; `t:num`]
    EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX_OF_DELETE_VERTEX)
   (ASSUME
    `euler_planar_rotation (V:A->bool) E r /\
     connected_graph V E /\
     x IN V /\
     connected_graph
       (V DELETE x) (induced_subgraph_edges E (V DELETE x)) /\
     INJ w (cyclic_indices m) (:A) /\
     (!i. i < m ==> ~(w i = x)) /\
     (!i. i < m ==> {x,w i} IN E) /\
     t < m`)) THEN
  REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[]);;

let FAN_DELETE_REVERSE_SPOKE_SUCCESSOR_OF_DELETE_VERTEX = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !m t j.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        x IN V /\
        connected_graph
          (V DELETE x) (induced_subgraph_edges E (V DELETE x)) /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> r(x,w i) = (x,w(i + 1))) /\
        t <= j /\ j + 1 < m
        ==> graph_face_successor
             (fan_delete_edges x w E t)
             (fan_delete_rotation x w r t)
             (w j,x) = (x,w(j + 1))`,
  REPEAT GEN_TAC THEN SPEC_TAC(`t:num`,`t:num`) THEN
  INDUCT_TAC THENL
   [INTRO_TAC
     "euler connected x_vertex deleted_connected injective avoids \
      spokes rotation_order lower index" THEN
    REWRITE_TAC[fan_delete_edges; fan_delete_rotation] THEN
    TRANS_TAC EQ_TRANS
     `(r:(A#A)->A#A) (x,(w:num->A) (j:num))` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PAIR THEN
      REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR] THEN
      ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
      USE_THEN "spokes" MATCH_MP_TAC THEN ASM_ARITH_TAC;
      USE_THEN "rotation_order" MATCH_MP_TAC THEN
      USE_THEN "index" ACCEPT_TAC];
    POP_ASSUM(LABEL_TAC "induction") THEN
    INTRO_TAC
     "euler connected x_vertex deleted_connected injective avoids \
      spokes rotation_order lower index" THEN
    SUBGOAL_THEN `(t:num) < j` (LABEL_TAC "strict_lower") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(t:num) < m` (LABEL_TAC "old_bound") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_face_successor
       (fan_delete_edges x w E t)
       (fan_delete_rotation x w r t)
       ((w:num->A) j,x) = (x,w(j + 1))`
    (LABEL_TAC "old_successor") THENL
     [USE_THEN "induction" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `finite_simple_graph
        (V:A->bool) (fan_delete_edges x w E t) /\
      graph_rotation
        (fan_delete_edges x w E t)
        (fan_delete_rotation x w r t)`
    (CONJUNCTS_THEN2 (LABEL_TAC "old_graph")
      (LABEL_TAC "old_rotation")) THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `x:A`; `w:num->A`; `m:num`; `t:num`]
       EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX_OF_DELETE_VERTEX_GRAPH_DATA)
      THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{x:A,(w:num->A)t} IN fan_delete_edges x w E t`
    (LABEL_TAC "deleted_edge") THENL
     [MATCH_MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`;
        `m:num`; `t:num`; `t:num`]
       FAN_DELETE_EDGE_REMAINS) THEN
      ASM_REWRITE_TAC[LE_REFL];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `((w:num->A) j,x) IN
      graph_darts (fan_delete_edges x w E (SUC t))`
    (LABEL_TAC "new_dart") THENL
     [MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`;
        `m:num`; `SUC t`; `j:num`]
       FAN_DELETE_SPOKE_DARTS_REMAIN) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        MESON_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `~((w:num->A) (j + 1) = w t)`
    (LABEL_TAC "next_distinct") THENL
     [MATCH_MP_TAC(ISPECL
       [`w:num->A`; `m:num`; `j + 1:num`; `t:num`]
       INJ_CYCLIC_INDICES_NE) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((w:num->A) t = x)`
    (LABEL_TAC "deleted_avoids") THENL
     [USE_THEN "avoids" MATCH_MP_TAC THEN
      USE_THEN "old_bound" ACCEPT_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[fan_delete_edges; fan_delete_rotation] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`;
      `fan_delete_edges
        (x:A) (w:num->A) (E:(A->bool)->bool) t`;
      `fan_delete_rotation
        (x:A) (w:num->A) (r:(A#A)->A#A) t`;
      `x:A`; `(w:num->A)t`; `(w:num->A)j`; `x:A`;
      `x:A`; `(w:num->A)(j + 1)`]
     GRAPH_FACE_SUCCESSOR_DELETE_EDGE_UNCHANGED_VALUE) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "new_dart"
     (ACCEPT_TAC o REWRITE_RULE[fan_delete_edges])]);;

