let VERTEX_2_CONNECTED_DELETE_ROTATION_EXIT_DART = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A. !x y:A.
        finite_simple_graph V E /\
        graph_rotation E r /\
        x IN V /\
        vertex_k_connected_graph
          2 (V DELETE x) (induced_subgraph_edges E (V DELETE x)) /\
        {x,y} IN E
        ==> r(y,x) IN
            graph_darts (induced_subgraph_edges E (V DELETE x))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph rotation x_vertex deleted_connected2 spoke" THEN
  ABBREV_TAC `W:A->bool = V DELETE x` THEN
  ABBREV_TAC
   `D:(A->bool)->bool = induced_subgraph_edges E (V DELETE x)` THEN
  SUBGOAL_THEN `vertex_k_connected_graph 2 (W:A->bool) D`
  (LABEL_TAC "deleted_connected2_abbrev") THENL
   [ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (W:A->bool) D`
  (LABEL_TAC "deleted_graph") THENL
   [MATCH_MP_TAC(ISPECL
     [`2`; `W:A->bool`; `D:(A->bool)->bool`]
     VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE) THEN
    USE_THEN "deleted_connected2_abbrev" ACCEPT_TAC;
     ALL_TAC] THEN
  SUBGOAL_THEN `connected_graph (W:A->bool) D`
  (LABEL_TAC "deleted_connected") THENL
   [USE_THEN "deleted_connected2_abbrev" (fun th ->
      ACCEPT_TAC(MATCH_MP
       (ISPECL
        [`2`; `W:A->bool`; `D:(A->bool)->bool`]
        VERTEX_K_CONNECTED_GRAPH_CONNECTED)
       (CONJ th (ARITH_RULE `0 < 2`))));
    ALL_TAC] THEN
  SUBGOAL_THEN `(y:A) IN W` (LABEL_TAC "y_deleted") THENL
   [EXPAND_TAC "W" THEN REWRITE_TAC[IN_DELETE] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `x:A`; `y:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `x:A`; `y:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `{y:A} SUBSET W` (LABEL_TAC "singleton_subset") THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~({y:A} = W)` (LABEL_TAC "singleton_proper") THENL
   [DISCH_THEN(LABEL_TAC "singleton_all") THEN
    MP_TAC(MATCH_MP
     (ISPECL
      [`2`; `W:A->bool`; `D:(A->bool)->bool`]
      VERTEX_K_CONNECTED_GRAPH_CARD)
     (ASSUME `vertex_k_connected_graph 2 (W:A->bool) D`)) THEN
    USE_THEN "singleton_all"
     (fun th -> REWRITE_TAC[GSYM th; CARD_SING]) THEN
    ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`W:A->bool`; `D:(A->bool)->bool`; `{y:A}`; `y:A`]
   CONNECTED_GRAPH_CROSSING_EDGE) THEN
  ASM_REWRITE_TAC[IN_SING] THEN
  INTRO_TAC "@z a. z_outside a_singleton crossing_edge" THEN
  SUBGOAL_THEN `(a:A) = y` SUBST_ALL_TAC THENL
   [USE_THEN "a_singleton" MP_TAC THEN REWRITE_TAC[IN_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN `((y:A),z) IN graph_darts D`
  (LABEL_TAC "other_deleted_dart") THENL
   [REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR] THEN
    ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
    USE_THEN "crossing_edge" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `((y:A),z) IN graph_darts E`
  (LABEL_TAC "other_dart") THENL
   [USE_THEN "other_deleted_dart" MP_TAC THEN
    MAP_EVERY EXPAND_TAC ["D"] THEN
    REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR;
                IN_INDUCED_SUBGRAPH_EDGES] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `((y:A),x) IN graph_darts E`
  (LABEL_TAC "spoke_dart") THENL
   [REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR] THEN
    ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
    USE_THEN "spoke" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) ((y:A),x) IN graph_darts E`
  (LABEL_TAC "exit_dart") THENL
   [MATCH_MP_TAC GRAPH_ROTATION_IN THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FST((r:(A#A)->A#A) ((y:A),x)) = y`
  (LABEL_TAC "exit_tail") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `((y:A),x):A#A`]
     GRAPH_ROTATION_TAIL) THEN
    ASM_REWRITE_TAC[FST];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((r:(A#A)->A#A) ((y:A),x) = (y,x))`
  (LABEL_TAC "exit_not_spoke") THENL
   [DISCH_THEN(LABEL_TAC "fixed") THEN
    SUBGOAL_THEN
     `((y:A),(z:A)):A#A = ((y:A),(x:A)):A#A`
    (LABEL_TAC "same_dart") THENL
     [MATCH_MP_TAC(ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `((y:A),x):A#A`; `((y:A),z):A#A`]
       GRAPH_ROTATION_FIXED_DART_AT_TAIL) THEN
      ASM_REWRITE_TAC[FST];
      ALL_TAC] THEN
    USE_THEN "z_outside" MP_TAC THEN
    USE_THEN "same_dart" MP_TAC THEN
    EXPAND_TAC "W" THEN
    REWRITE_TAC[IN_DIFF; IN_DELETE; IN_SING; PAIR_EQ] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPEC `(r:(A#A)->A#A) ((y:A),x)` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `u:A`
   (X_CHOOSE_THEN `v:A` (LABEL_TAC "exit_pair"))) THEN
  SUBGOAL_THEN `(u:A) = y` SUBST_ALL_TAC THENL
   [USE_THEN "exit_tail" MP_TAC THEN
    USE_THEN "exit_pair" (fun th -> REWRITE_TAC[th; FST]);
    ALL_TAC] THEN
  SUBGOAL_THEN `~((v:A) = x)` (LABEL_TAC "head_avoids") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "exit_not_spoke" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "exit_pair" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `((y:A),(v:A)) IN graph_darts E`
  (LABEL_TAC "exit_pair_dart") THENL
   [USE_THEN "exit_dart" MP_TAC THEN
    USE_THEN "exit_pair" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(v:A) IN V` (LABEL_TAC "head_vertex") THENL
   [ACCEPT_TAC(CONJUNCT1(CONJUNCT2(MATCH_MP
     (ISPECL
      [`V:A->bool`; `E:(A->bool)->bool`; `y:A`; `v:A`]
      FINITE_SIMPLE_GRAPH_DART)
     (CONJ
      (ASSUME `finite_simple_graph (V:A->bool) E`)
      (ASSUME `((y:A),(v:A)) IN graph_darts E`)))));
    ALL_TAC] THEN
  USE_THEN "exit_pair" (fun th -> REWRITE_TAC[th]) THEN
  EXPAND_TAC "D" THEN
  REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR;
              IN_INDUCED_SUBGRAPH_EDGES] THEN
  CONJ_TAC THENL
   [USE_THEN "exit_dart" MP_TAC THEN
    USE_THEN "exit_pair" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR];
    USE_THEN "y_deleted" MP_TAC THEN
    EXPAND_TAC "W" THEN
    REWRITE_TAC[SUBSET; IN_INSERT; IN_SING; IN_DELETE] THEN
    ASM_MESON_TAC[]]);;

let FAN_DELETE_DELETE_VERTEX_DART_REMAINS = prove
 (`!V:A->bool. !E:(A->bool)->bool. !x:A. !w:num->A. !t d:A#A.
        d IN graph_darts (induced_subgraph_edges E (V DELETE x))
        ==> d IN graph_darts (fan_delete_edges x w E t)`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPEC `d:A#A` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A`
   (X_CHOOSE_THEN `b:A` SUBST_ALL_TAC)) THEN
  DISCH_THEN(LABEL_TAC "deleted_dart") THEN
  MATCH_MP_TAC FAN_DELETE_NONINCIDENT_DART_REMAINS THEN
  USE_THEN "deleted_dart" MP_TAC THEN
  REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR;
              IN_INDUCED_SUBGRAPH_EDGES; SUBSET;
              IN_INSERT; IN_SING; IN_DELETE] THEN
  MESON_TAC[]);;

let FAN_DELETE_EARLIER_EXITS_COFACIAL = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !m.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        x IN V /\
        vertex_k_connected_graph
          2 (V DELETE x) (induced_subgraph_edges E (V DELETE x)) /\
        3 <= CARD V /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> r(x,w i) = (x,w(i + 1)))
        ==> !t i.
              t < m /\ i < t
              ==> r(w i,x) IN
                  graph_face
                    (fan_delete_edges x w E t)
                    (fan_delete_rotation x w r t)
                    (x,w t)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected x_vertex deleted_connected2 vertices_large \
    injective avoids spokes rotation_order" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph
     ((V:A->bool) DELETE (x:A))
     (induced_subgraph_edges
       (E:(A->bool)->bool) ((V:A->bool) DELETE (x:A)))`
  (LABEL_TAC "deleted_connected") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_CONNECTED THEN
    EXISTS_TAC `2` THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  INDUCT_TAC THENL
   [X_GEN_TAC `i:num` THEN
    INTRO_TAC "bound index" THEN ASM_ARITH_TAC;
    POP_ASSUM(LABEL_TAC "induction") THEN
    X_GEN_TAC `i:num` THEN
    INTRO_TAC "new_bound index" THEN
    SUBGOAL_THEN `(t:num) < m` (LABEL_TAC "old_bound") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `euler_planar_rotation
       (V:A->bool) (fan_delete_edges x w E t)
       (fan_delete_rotation x w r t) /\
      connected_graph V (fan_delete_edges x w E t)`
    (CONJUNCTS_THEN2 (LABEL_TAC "old_euler")
      (LABEL_TAC "old_connected")) THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `x:A`; `w:num->A`; `m:num`; `t:num`]
       EULER_PLANAR_ROTATION_FAN_DELETE_PREFIX_OF_DELETE_VERTEX) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `finite_simple_graph
       (V:A->bool) (fan_delete_edges x w E t) /\
      graph_rotation
       (fan_delete_edges x w E t)
       (fan_delete_rotation x w r t)`
    (CONJUNCTS_THEN2 (LABEL_TAC "old_graph")
      (LABEL_TAC "old_rotation")) THENL
     [USE_THEN "old_euler" MP_TAC THEN
      REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{x:A,(w:num->A)t} IN fan_delete_edges x w E t`
    (LABEL_TAC "deleted_edge") THENL
     [MATCH_MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`;
        `m:num`; `t:num`; `t:num`]
       FAN_DELETE_EDGE_REMAINS) THEN
      ASM_REWRITE_TAC[LE_REFL];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `connected_graph
       (V:A->bool) (fan_delete_edges x w E (SUC t))`
    (LABEL_TAC "new_connected") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `x:A`;
        `w:num->A`; `m:num`; `SUC t`]
       CONNECTED_GRAPH_FAN_DELETE_PREFIX_OF_DELETE_VERTEX) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x,(w:num->A)(SUC t)) IN
      graph_darts (fan_delete_edges x w E (SUC t))`
    (LABEL_TAC "new_anchor_dart") THENL
     [MP_TAC(ISPECL
       [`x:A`; `w:num->A`; `E:(A->bool)->bool`;
        `m:num`; `SUC t`; `SUC t`]
       FAN_DELETE_SPOKE_DARTS_REMAIN) THEN
      ASM_REWRITE_TAC[LE_REFL] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(r:(A#A)->A#A) ((w:num->A)i,x) IN
      graph_darts (induced_subgraph_edges E (V DELETE x))`
    (LABEL_TAC "exit_deleted_dart") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `x:A`; `(w:num->A)i`]
       VERTEX_2_CONNECTED_DELETE_ROTATION_EXIT_DART) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "spokes" MATCH_MP_TAC THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(r:(A#A)->A#A) ((w:num->A)i,x) IN
      graph_darts (fan_delete_edges x w E (SUC t))`
    (LABEL_TAC "new_exit_dart") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `x:A`;
        `w:num->A`; `SUC t`;
        `(r:(A#A)->A#A) ((w:num->A)i,x)`]
       FAN_DELETE_DELETE_VERTEX_DART_REMAINS) THEN
      USE_THEN "exit_deleted_dart" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~(graph_face
         (fan_delete_edges
           (x:A) (w:num->A) (E:(A->bool)->bool) t)
         (fan_delete_rotation
           (x:A) (w:num->A) (r:(A#A)->A#A) t)
         ((x:A),(w:num->A)t) =
        graph_face
         (fan_delete_edges
           (x:A) (w:num->A) (E:(A->bool)->bool) t)
         (fan_delete_rotation
           (x:A) (w:num->A) (r:(A#A)->A#A) t)
         ((w:num->A)t,(x:A)))`
    (LABEL_TAC "distinct_faces") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `fan_delete_edges
          (x:A) (w:num->A) (E:(A->bool)->bool) t`;
        `fan_delete_rotation
          (x:A) (w:num->A) (r:(A#A)->A#A) t`;
        `x:A`; `(w:num->A)t`]
       EULER_PLANAR_ROTATION_NONSEPARATING_EDGE_DISTINCT_FACES) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "new_connected" MP_TAC THEN
      REWRITE_TAC[fan_delete_edges] THEN
      DISCH_THEN MATCH_ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(x,(w:num->A)(SUC t)) IN
      graph_face
       (fan_delete_edges x w E t)
       (fan_delete_rotation x w r t) (w t,x)`
    (LABEL_TAC "anchor_affected") THENL
     [SUBGOAL_THEN
       `graph_face_successor
         (fan_delete_edges x w E t)
         (fan_delete_rotation x w r t) ((w:num->A)t,x) =
        (x,w(t + 1))`
      (LABEL_TAC "anchor_successor") THENL
       [MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
          `x:A`; `w:num->A`; `m:num`; `t:num`; `t:num`]
         FAN_DELETE_REVERSE_SPOKE_SUCCESSOR_OF_DELETE_VERTEX) THEN
        ASM_REWRITE_TAC[LE_REFL] THEN ASM_ARITH_TAC;
        ALL_TAC] THEN
      REWRITE_TAC[ADD1] THEN
      USE_THEN "anchor_successor"
       (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_ACCEPT_TAC(ISPECL
       [`fan_delete_edges
          (x:A) (w:num->A) (E:(A->bool)->bool) t`;
        `fan_delete_rotation
          (x:A) (w:num->A) (r:(A#A)->A#A) t`;
        `((w:num->A)t,x):A#A`]
       GRAPH_FACE_SUCCESSOR_IN_FACE);
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(r:(A#A)->A#A) ((w:num->A)i,x) IN
      graph_face
       (fan_delete_edges x w E t)
       (fan_delete_rotation x w r t) (x,w t)`
    (LABEL_TAC "exit_affected") THENL
     [ASM_CASES_TAC `(i:num) < t` THENL
       [FIRST_X_ASSUM(LABEL_TAC "old_index") THEN
        USE_THEN "induction" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
        SUBGOAL_THEN `(i:num) = t` SUBST_ALL_TAC THENL
         [ASM_ARITH_TAC;
          SUBGOAL_THEN
           `graph_face_successor
             (fan_delete_edges x w E t)
             (fan_delete_rotation x w r t)
             (x,(w:num->A)t) = r(w t,x)`
          (LABEL_TAC "exit_successor") THENL
           [MATCH_MP_TAC(ISPECL
             [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
              `x:A`; `w:num->A`; `m:num`; `t:num`; `t:num`]
             FAN_DELETE_FORWARD_SPOKE_SUCCESSOR_OF_DELETE_VERTEX) THEN
            ASM_REWRITE_TAC[LE_REFL];
            USE_THEN "exit_successor"
             (fun th -> REWRITE_TAC[GSYM th]) THEN
            MATCH_ACCEPT_TAC(ISPECL
             [`fan_delete_edges
                (x:A) (w:num->A) (E:(A->bool)->bool) t`;
              `fan_delete_rotation
                (x:A) (w:num->A) (r:(A#A)->A#A) t`;
              `((x:A),(w:num->A)t):A#A`]
             GRAPH_FACE_SUCCESSOR_IN_FACE)]]];
      ALL_TAC] THEN
    REWRITE_TAC[fan_delete_edges; fan_delete_rotation] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`;
      `fan_delete_edges
        (x:A) (w:num->A) (E:(A->bool)->bool) t`;
      `fan_delete_rotation
        (x:A) (w:num->A) (r:(A#A)->A#A) t`;
      `x:A`; `(w:num->A)t`;
      `((x:A),(w:num->A)(SUC t)):A#A`;
      `(r:(A#A)->A#A) ((w:num->A)i,x)`]
     GRAPH_FACE_DELETE_EDGE_MERGES_DISTINCT_FACES) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "new_anchor_dart"
       (ACCEPT_TAC o REWRITE_RULE[fan_delete_edges]);
      USE_THEN "new_exit_dart"
       (ACCEPT_TAC o REWRITE_RULE[fan_delete_edges])]]);;

let VERTEX_2_CONNECTED_GRAPH_EDGES_NONEMPTY = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        vertex_k_connected_graph 2 V E
        ==> ~(E = {})`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "connected2") THEN
