   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_CONNECTED THEN
    EXISTS_TAC `2` THEN ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `2 < CARD(V:A->bool)` (LABEL_TAC "card") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_CARD THEN
    EXISTS_TAC `E:(A->bool)->bool` THEN
    USE_THEN "connected2" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((V:A->bool) = {})` (LABEL_TAC "vertices_nonempty") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "card" MP_TAC THEN REWRITE_TAC[CARD_CLAUSES] THEN ARITH_TAC;
    ALL_TAC] THEN
  USE_THEN "vertices_nonempty"
   (MP_TAC o REWRITE_RULE[GSYM MEMBER_NOT_EMPTY]) THEN
  DISCH_THEN(X_CHOOSE_THEN `u:A` (LABEL_TAC "u_vertex")) THEN
  DISCH_THEN(LABEL_TAC "edges_empty") THEN
  SUBGOAL_THEN `(V:A->bool) = {u}` (LABEL_TAC "singleton") THENL
   [MATCH_MP_TAC CONNECTED_GRAPH_EMPTY_EDGES_SINGLETON THEN
    USE_THEN "edges_empty" (fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[];
    USE_THEN "card" MP_TAC THEN
    USE_THEN "singleton" (fun th -> REWRITE_TAC[th; CARD_SING]) THEN
    ARITH_TAC]);;

let VERTEX_2_CONNECTED_DELETE_VERTEX_EXITS_COFACIAL = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !m.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        x IN V /\
        vertex_k_connected_graph
          2 (V DELETE x) (induced_subgraph_edges E (V DELETE x)) /\
        3 <= CARD V /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> r(x,w i) = (x,w(i + 1))) /\
        graph_neighbors E x = cyclic_vertices w m /\
        1 <= m
        ==> ?s:(A#A)->A#A.
              euler_planar_rotation
                (V DELETE x)
