let VERTEX_2_CONNECTED_DELETE_VERTEX_NEIGHBORS_ON_FACE_CYCLE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !x:A. !w:num->A. !m.
        euler_planar_rotation V E r /\
        connected_graph V E /\
        x IN V /\
        vertex_k_connected_graph
          2 (V DELETE x) (induced_subgraph_edges E (V DELETE x)) /\
        3 <= CARD V /\
        INJ w (cyclic_indices m) (:A) /\
        (!i. i < m ==> ~(w i = x)) /\
        (!i. i < m ==> {x,w i} IN E) /\
        (!i. i + 1 < m ==> r(x,w i) = (x,w(i + 1))) /\
        graph_neighbors E x = cyclic_vertices w m /\
        1 <= m
        ==> ?s:(A#A)->A#A. ?q:num->A. ?n.
              euler_planar_rotation
                (V DELETE x)
                (induced_subgraph_edges E (V DELETE x)) s /\
              simple_graph_cycle
                (induced_subgraph_edges E (V DELETE x)) q n /\
              cyclic_face_successors
                (induced_subgraph_edges E (V DELETE x)) s q n /\
              graph_neighbors E x SUBSET cyclic_vertices q n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler connected x_vertex deleted_connected2 vertices_large \
    injective avoids spokes rotation_order neighbors positive" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    graph_rotation E (r:(A#A)->A#A)`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph") (LABEL_TAC "rotation")) THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(m - 1:num) < m` (LABEL_TAC "last_index") THENL
   [USE_THEN "positive" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `x:A`; `w:num->A`; `m:num`]
   VERTEX_2_CONNECTED_DELETE_VERTEX_EXITS_COFACIAL) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC "@s. deleted_euler exits_cofacial"] THEN
  SUBGOAL_THEN
   `(r:(A#A)->A#A) ((w:num->A)(m - 1),x) IN
    graph_darts (induced_subgraph_edges E (V DELETE x))`
  (LABEL_TAC "root_dart") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
     `x:A`; `(w:num->A)(m - 1)`]
     VERTEX_2_CONNECTED_DELETE_ROTATION_EXIT_DART) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "spokes" MATCH_MP_TAC THEN
    USE_THEN "last_index" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(V:A->bool) DELETE (x:A)`;
    `induced_subgraph_edges
      (E:(A->bool)->bool) ((V:A->bool) DELETE (x:A))`;
    `s:(A#A)->A#A`;
    `(r:(A#A)->A#A) ((w:num->A)(m - 1),x)`]
   VERTEX_2_CONNECTED_EULER_PLANAR_FACE_CYCLIC_WALK) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    INTRO_TAC
     "@q. face_large cycle_injective start next enumeration face \
      cycle_edges face_successors"] THEN
  ABBREV_TAC
   `n = CARD
         (graph_face
           (induced_subgraph_edges
             (E:(A->bool)->bool) ((V:A->bool) DELETE (x:A)))
           (s:(A#A)->A#A)
           ((r:(A#A)->A#A) ((w:num->A)(m - 1),x)))` THEN
  MAP_EVERY EXISTS_TAC
   [`s:(A#A)->A#A`; `q:num->A`; `n:num`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "deleted_euler" ACCEPT_TAC;
    REWRITE_TAC[simple_graph_cycle] THEN
    EXPAND_TAC "n" THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    REWRITE_TAC[SUBSET] THEN X_GEN_TAC `y:A` THEN
    USE_THEN "neighbors"
     (fun th -> REWRITE_TAC[th; IN_CYCLIC_VERTICES]) THEN
    DISCH_THEN(X_CHOOSE_THEN `i:num`
     (CONJUNCTS_THEN2 (LABEL_TAC "index")
      (LABEL_TAC "y_value"))) THEN
    USE_THEN "y_value" SUBST1_TAC THEN
    SUBGOAL_THEN
     `FST((r:(A#A)->A#A) ((w:num->A)i,x)) = w i`
    (LABEL_TAC "exit_tail") THENL
     [MATCH_MP_TAC(REWRITE_RULE[FST] (ISPECL
       [`E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `((w:num->A)i,x):A#A`]
       GRAPH_ROTATION_TAIL)) THEN
      ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[IN_GRAPH_DARTS; DART_EDGE_PAIR] THEN
      ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
      USE_THEN "spokes" MATCH_MP_TAC THEN
      USE_THEN "index" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(r:(A#A)->A#A) ((w:num->A)i,x) IN
      graph_face
        (induced_subgraph_edges E (V DELETE x)) s
        (r(w(m - 1),x))`
    (LABEL_TAC "exit_in_face") THENL
     [USE_THEN "exits_cofacial" (fun th ->
       USE_THEN "index" (fun ith ->
        MATCH_ACCEPT_TAC(MP (SPEC `i:num` th) ith)));
      ALL_TAC] THEN
    USE_THEN "exit_in_face" MP_TAC THEN
    USE_THEN "face" (fun th -> REWRITE_TAC[th; IN_CYCLIC_DARTS]) THEN
    DISCH_THEN(X_CHOOSE_THEN `j:num`
     (CONJUNCTS_THEN2 (LABEL_TAC "j_index")
      (LABEL_TAC "exit_value"))) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `j:num` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "exit_value"
     (MP_TAC o AP_TERM `FST:A#A->A`) THEN
    ASM_REWRITE_TAC[FST]]);;

