      USE_THEN "induced_twice" (fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(fun th ->
       MATCH_ACCEPT_TAC(REWRITE_RULE
        [SET_RULE
          `(V:A->bool) DIFF (x INSERT S) =
