    USE_THEN "singleton" (fun th -> REWRITE_TAC[GSYM th; CARD_SING]) THEN
    ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `{x:A}`; `x:A`]
   CONNECTED_GRAPH_CROSSING_EDGE) THEN
  ASM_REWRITE_TAC[SING_SUBSET; IN_SING] THEN
  INTRO_TAC "@u v. u_outside v_singleton crossing_edge" THEN
  SUBGOAL_THEN `(v:A) = x` SUBST_ALL_TAC THENL
   [USE_THEN "v_singleton" MP_TAC THEN REWRITE_TAC[IN_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((x:A),(u:A)) IN outgoing_darts E x`
  (LABEL_TAC "outgoing") THENL
   [REWRITE_TAC[IN_OUTGOING_DARTS; IN_GRAPH_DARTS;
                DART_EDGE_PAIR; FST] THEN
    ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
    USE_THEN "crossing_edge" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `x:A`; `((x:A),(u:A)):A#A`]
   GRAPH_ROTATION_NEIGHBOR_ENUMERATION_STEPS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@w. neighbors injective start steps" THEN
  ABBREV_TAC `m = CARD(graph_neighbors (E:(A->bool)->bool) (x:A))` THEN
  SUBGOAL_THEN `1 <= m` (LABEL_TAC "positive") THENL
   [EXPAND_TAC "m" THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `x:A`;
      `((x:A),(u:A)):A#A`]
     GRAPH_OUTGOING_DART_NEIGHBOR_CARD_POS) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_neighbors (E:(A->bool)->bool) x =
    cyclic_vertices (w:num->A) m`
  (LABEL_TAC "neighbors_m") THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `INJ (w:num->A) (cyclic_indices m) (:A)`
  (LABEL_TAC "injective_m") THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i:num. i < m ==> ~((w:num->A) i = (x:A))`
  (LABEL_TAC "avoids") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    SUBGOAL_THEN
     `((x:A),(w:num->A)i) IN graph_darts E`
    (LABEL_TAC "dart") THENL
     [USE_THEN "steps" (MP_TAC o SPEC `i:num`) THEN
      EXPAND_TAC "m" THEN
      ASM_REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `x:A`; `(w:num->A)i`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i:num. i < m
        ==> {(x:A),(w:num->A)i} IN (E:(A->bool)->bool)`
  (LABEL_TAC "spokes") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
    USE_THEN "steps" (MP_TAC o SPEC `i:num`) THEN
    EXPAND_TAC "m" THEN
    ASM_REWRITE_TAC[IN_OUTGOING_DARTS; IN_GRAPH_DARTS;
                    DART_EDGE_PAIR; FST] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i:num. i + 1 < m
        ==> (r:(A#A)->A#A) ((x:A),(w:num->A)i) =
            ((x:A),(w:num->A)(i + 1))`
  (LABEL_TAC "rotation_order") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "next_index") THEN
    USE_THEN "steps" (MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
        (LABEL_TAC "rotation_step"))] THEN
    USE_THEN "rotation_step" MP_TAC THEN
    ASM_SIMP_TAC[MOD_LT];
    ALL_TAC] THEN
  SUBGOAL_THEN `3 <= CARD(V:A->bool)` (LABEL_TAC "card3") THENL
   [USE_THEN "card" MP_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `x:A`; `w:num->A`; `m:num`]
   VERTEX_2_CONNECTED_DELETE_VERTEX_NEIGHBORS_ON_FACE_CYCLE) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Reconstructing a contracted edge from two noncrossing facial fans.        *)
(* ------------------------------------------------------------------------- *)

let CYCLIC_DART_CONG = prove
 (`!q p:num->A. !n i.
        0 < n /\
        i < n /\
        (!j. j < n ==> p j = q j)
        ==> cyclic_dart p n i = cyclic_dart q n i`,
  REPEAT GEN_TAC THEN INTRO_TAC "positive index agree" THEN
  REWRITE_TAC[cyclic_dart; PAIR_EQ] THEN CONJ_TAC THENL
   [USE_THEN "agree" MATCH_MP_TAC THEN
    USE_THEN "index" ACCEPT_TAC;
    USE_THEN "agree" MATCH_MP_TAC THEN
    REWRITE_TAC[MOD_LT_EQ_LT] THEN
    USE_THEN "positive" ACCEPT_TAC]);;

let CYCLIC_FACE_SUCCESSORS_CONG = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A.
   !q p:num->A. !n.
        0 < n /\
        (!i. i < n ==> p i = q i) /\
        cyclic_face_successors E r q n
        ==> cyclic_face_successors E r p n`,
  REPEAT GEN_TAC THEN INTRO_TAC "positive agree successors" THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
  USE_THEN "successors" MP_TAC THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  DISCH_THEN(MP_TAC o SPEC `i:num`) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `cyclic_dart (p:num->A) n i = cyclic_dart q n i`
  (LABEL_TAC "source") THENL
   [MATCH_MP_TAC CYCLIC_DART_CONG THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_dart (p:num->A) n ((i + 1) MOD n) =
    cyclic_dart q n ((i + 1) MOD n)`
  (LABEL_TAC "target") THENL
   [MATCH_MP_TAC CYCLIC_DART_CONG THEN
    ASM_REWRITE_TAC[MOD_LT_EQ_LT];
    ASM_REWRITE_TAC[]]);;

let SIMPLE_GRAPH_CYCLE_CONG = prove
 (`!E:(A->bool)->bool. !q p:num->A. !n.
        simple_graph_cycle E q n /\
        (!i. i < n ==> p i = q i)
        ==> simple_graph_cycle E p n`,
  REPEAT GEN_TAC THEN INTRO_TAC "cycle agree" THEN
  USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective edges" THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "large" ACCEPT_TAC;
    MATCH_MP_TAC INJ_CYCLIC_INDICES_CONG THEN
    EXISTS_TAC `q:num->A` THEN ASM_REWRITE_TAC[];
    USE_THEN "agree" (fun th ->
      REWRITE_TAC[MATCH_MP CYCLIC_EDGES_CONG th]) THEN
    USE_THEN "edges" ACCEPT_TAC]);;

let CYCLIC_DART_OFFSET = prove
 (`!q:num->A. !n k i.
        0 < n /\ i < n
        ==> cyclic_dart (\j. q((j + k) MOD n)) n i =
            cyclic_dart q n ((i + k) MOD n)`,
  REPEAT GEN_TAC THEN INTRO_TAC "positive index" THEN
  REWRITE_TAC[cyclic_dart; PAIR_EQ] THEN
  ASM_SIMP_TAC[MOD_LT_EQ_LT; CYCLIC_OFFSET_SUCCESSOR]);;

let CYCLIC_FACE_SUCCESSORS_OFFSET = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A.
   !q:num->A. !n k.
        0 < n /\ cyclic_face_successors E r q n
        ==> cyclic_face_successors E r (\i. q((i + k) MOD n)) n`,
  REPEAT GEN_TAC THEN INTRO_TAC "positive successors" THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
  USE_THEN "successors" MP_TAC THEN
  REWRITE_TAC[cyclic_face_successors] THEN
  DISCH_THEN(MP_TAC o SPEC `(i + k) MOD n`) THEN
  ASM_SIMP_TAC[MOD_LT_EQ_LT; CYCLIC_DART_OFFSET;
               CYCLIC_OFFSET_SUCCESSOR]);;

let CONNECTED_EULER_PLANAR_ROTATION_IMP_EULER_PLANAR_GRAPH = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
        euler_planar_rotation V E r /\
        connected_graph V E
        ==> euler_planar_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler connected" THEN
  REWRITE_TAC[euler_planar_graph] THEN CONJ_TAC THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "u_vertex") THEN
    MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
      CONNECTED_GRAPH_COMPONENT_EDGES) THEN
    ASM_REWRITE_TAC[] THEN
    ANTS_TAC THENL
     [USE_THEN "euler" MP_TAC THEN
      REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
      INTRO_TAC "component component_edges"] THEN
    EXISTS_TAC `r:(A#A)->A#A` THEN
    ASM_REWRITE_TAC[]]);;

let BOUNDARY_EULER_ROTATION_FULL_FAN = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !q:num->A. !n. !x:A.
        simple_graph_cycle E q n /\
        boundary_euler_rotation V E q n r /\
        connected_graph V E /\
        cyclic_vertices q n SUBSET V /\
        ~(x IN V)
        ==> euler_planar_graph
             (x INSERT V)
             (IMAGE (\u:A. {x,u}) (cyclic_vertices q n) UNION E)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "cycle boundary connected vertices fresh" THEN
  USE_THEN "cycle" MP_TAC THEN REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective edges" THEN
  SUBGOAL_THEN `cyclic_face_successors E r (q:num->A) n`
  (LABEL_TAC "successors") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `r:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_IMP_CYCLIC_FACE_SUCCESSORS) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  ABBREV_TAC `p:A#A = cyclic_dart (q:num->A) n (n - 1)` THEN
  FIRST_X_ASSUM(LABEL_TAC "p_def") THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
    `x:A`; `q:num->A`; `p:A#A`; `n - 1`]
   EULER_PLANAR_ROTATION_FAN) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "boundary" MP_TAC THEN
      REWRITE_TAC[boundary_euler_rotation] THEN MESON_TAC[];
      USE_THEN "fresh" ACCEPT_TAC;
      SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        USE_THEN "injective" ACCEPT_TAC];
      X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
      USE_THEN "vertices" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      EXPAND_TAC "p" THEN
      MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DART THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      USE_THEN "p_def" (fun th -> REWRITE_TAC[GSYM th]) THEN
      SUBGOAL_THEN `1 <= n` (LABEL_TAC "positive") THENL
       [ASM_ARITH_TAC;
        USE_THEN "positive" (fun th ->
          REWRITE_TAC
           [MATCH_MP (ISPECL [`q:num->A`; `n:num`]
              CYCLIC_DART_LAST) th; SND])];
      X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
      REWRITE_TAC[ADD1] THEN
      SUBGOAL_THEN
       `((q:num->A) i,q(i + 1)) = cyclic_dart q n i`
      (fun th -> REWRITE_TAC[th]) THENL
       [CONV_TAC SYM_CONV THEN MATCH_MP_TAC CYCLIC_DART_NOWRAP THEN
        ASM_ARITH_TAC;
        MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CYCLIC_DART THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
      X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
      EXPAND_TAC "p" THEN REWRITE_TAC[ADD1] THEN
      SUBGOAL_THEN
       `((q:num->A) i,q(i + 1)) = cyclic_dart q n i`
      (fun th -> REWRITE_TAC[th]) THENL
       [CONV_TAC SYM_CONV THEN MATCH_MP_TAC CYCLIC_DART_NOWRAP THEN
        ASM_ARITH_TAC;
        MATCH_MP_TAC CYCLIC_DART_DISTINCT THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
      X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
      ASM_CASES_TAC `(i:num) = 0` THENL
       [FIRST_X_ASSUM SUBST_ALL_TAC THEN
        USE_THEN "successors" MP_TAC THEN
        REWRITE_TAC[cyclic_face_successors] THEN
        DISCH_THEN(MP_TAC o SPEC `n - 1`) THEN
        ANTS_TAC THENL
         [ASM_ARITH_TAC;
          DISCH_THEN(LABEL_TAC "successor")] THEN
        SUBGOAL_THEN `((n - 1) + 1) MOD n = 0`
        (LABEL_TAC "wrap") THENL
         [SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
           [ASM_ARITH_TAC;
            REWRITE_TAC[MOD_REFL]];
          ALL_TAC] THEN
        USE_THEN "p_def" (fun th -> REWRITE_TAC[GSYM th]) THEN
        REWRITE_TAC[fan_source_dart] THEN
        SUBGOAL_THEN `2 <= n` (LABEL_TAC "nlarge") THENL
         [ASM_ARITH_TAC;
          USE_THEN "successor" (fun th -> REWRITE_TAC[th]) THEN
          USE_THEN "wrap" (fun th -> REWRITE_TAC[th]) THEN
          USE_THEN "nlarge" (fun th ->
            REWRITE_TAC
             [MATCH_MP (ISPECL [`q:num->A`; `n:num`]
                CYCLIC_DART_ZERO) th]) THEN
          CONV_TAC NUM_REDUCE_CONV];
        USE_THEN "successors" MP_TAC THEN
        REWRITE_TAC[cyclic_face_successors] THEN
        DISCH_THEN(MP_TAC o SPEC `i - 1`) THEN
        ANTS_TAC THENL
         [ASM_ARITH_TAC;
          DISCH_THEN(LABEL_TAC "successor")] THEN
        SUBGOAL_THEN `i = SUC(i - 1)` (LABEL_TAC "successor_form")
        THENL
         [ASM_ARITH_TAC;
          ALL_TAC] THEN
        SUBGOAL_THEN `(i - 1) + 1 = i` (LABEL_TAC "source_next")
        THENL
         [ASM_ARITH_TAC;
          ALL_TAC] THEN
        SUBGOAL_THEN
         `cyclic_dart (q:num->A) n (i - 1) = (q(i - 1),q i)`
        (LABEL_TAC "source_dart") THENL
         [SUBGOAL_THEN `(i - 1) + 1 < n`
          (LABEL_TAC "source_bound") THENL
           [ASM_ARITH_TAC;
            MP_TAC(ISPECL [`q:num->A`; `n:num`; `i - 1`]
              CYCLIC_DART_NOWRAP) THEN
            ASM_REWRITE_TAC[]];
          ALL_TAC] THEN
        SUBGOAL_THEN
         `fan_source_dart (p:A#A) (q:num->A) i =
          cyclic_dart q n (i - 1)`
        (LABEL_TAC "fan_source") THENL
         [USE_THEN "successor_form"
           (fun th -> GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [th]) THEN
          REWRITE_TAC[fan_source_dart] THEN
          USE_THEN "source_dart"
           (fun th -> GEN_REWRITE_TAC RAND_CONV [th]) THEN
          USE_THEN "successor_form"
           (fun th -> REWRITE_TAC[GSYM th]);
          ALL_TAC] THEN
        SUBGOAL_THEN `i + 1 < n` (LABEL_TAC "target_bound") THENL
         [ASM_ARITH_TAC;
          ALL_TAC] THEN
        (fun (asl,_ as g) ->
          LABEL_TAC "i_bound"
           (MATCH_MP (ARITH_RULE `(i:num) + 1 < n ==> i < n`)
             (assoc "target_bound" asl)) g) THEN
        SUBGOAL_THEN
         `cyclic_dart (q:num->A) n i = (q i,q(SUC i))`
        (LABEL_TAC "target_dart") THENL
         [REWRITE_TAC[ADD1] THEN
          MATCH_MP_TAC CYCLIC_DART_NOWRAP THEN
          USE_THEN "target_bound" ACCEPT_TAC;
          ALL_TAC] THEN
        SUBGOAL_THEN `(i - 1 + 1) MOD n = i`
        (LABEL_TAC "successor_index") THENL
         [ASM_SIMP_TAC[MOD_LT];
          ALL_TAC] THEN
        USE_THEN "fan_source" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "successor" (fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[]]];
    REWRITE_TAC[fan_rotation_invariant] THEN
    DISCH_THEN
     (fun th -> LABEL_TAC "new_euler" (CONJUNCT1 th))] THEN
  SUBGOAL_THEN
   `fan_edges (x:A) (q:num->A) E (n - 1) =
    IMAGE (\u:A. {x,u}) (cyclic_vertices q n) UNION E`
  (LABEL_TAC "fan_edges") THENL
   [REWRITE_TAC[FAN_EDGES_CYCLIC_VERTICES] THEN
    SUBGOAL_THEN `(n - 1) + 1 = n` SUBST1_TAC THENL
     [ASM_ARITH_TAC;
      REFL_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph
      (x INSERT V:A->bool)
      (fan_edges x q (E:(A->bool)->bool) (n - 1))`
  (LABEL_TAC "new_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`x INSERT V:A->bool`;
      `{x:A,(q:num->A) 0} INSERT E:(A->bool)->bool`;
      `fan_edges x q E (n - 1):(A->bool)->bool`]
     CONNECTED_GRAPH_MONO) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC CONNECTED_GRAPH_INSERT_EDGE_VERTEX THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "vertices" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      EXISTS_TAC `0` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      REWRITE_TAC[FAN_EDGES_EXPLICIT; SUBSET; IN_INSERT;
                  IN_UNION; IN_IMAGE] THEN
      X_GEN_TAC `e:A->bool` THEN
      DISCH_THEN(DISJ_CASES_THEN2 SUBST1_TAC
        (LABEL_TAC "old_edge")) THENL
       [DISJ1_TAC THEN EXISTS_TAC `0` THEN
        REWRITE_TAC[IN_NUMSEG] THEN ASM_ARITH_TAC;
        ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  USE_THEN "fan_edges" (fun th -> REWRITE_TAC[GSYM th]) THEN
  MATCH_MP_TAC(ISPECL
   [`x INSERT V:A->bool`;
    `fan_edges x q E (n - 1):(A->bool)->bool`;
    `fan_rotation x q p r (n - 1):(A#A)->A#A`]
   CONNECTED_EULER_PLANAR_ROTATION_IMP_EULER_PLANAR_GRAPH) THEN
  CONJ_TAC THENL
   [USE_THEN "new_euler" ACCEPT_TAC;
    USE_THEN "new_connected" ACCEPT_TAC]);;

let split_fan_boundary = new_definition
 `split_fan_boundary (q:num->A) n d (v:A) i =
    if i < n - d + 1 then q((i + d) MOD n) else v`;;

let SPLIT_FAN_BOUNDARY_PREFIX = prove
 (`!q:num->A. !n d v:A. !i.
        i < n - d + 1
        ==> split_fan_boundary q n d v i = q((i + d) MOD n)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[split_fan_boundary] THEN
  MESON_TAC[]);;

let SPLIT_FAN_BOUNDARY_LAST = prove
 (`!q:num->A. !n d v:A.
        0 < d /\ d < n
        ==> split_fan_boundary q n d v (n - d + 1) = v`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[split_fan_boundary] THEN
  ASM_ARITH_TAC);;

let SPLIT_FAN_BOUNDARY_INJECTIVE = prove
 (`!q:num->A. !n d v:A.
        INJ q (cyclic_indices n) (:A) /\
        ~(v IN cyclic_vertices q n) /\
        0 < d /\ d < n
        ==> INJ (split_fan_boundary q n d v)
                (cyclic_indices (n - d + 2)) (:A)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "injective outside dpositive dbound" THEN
  SUBGOAL_THEN
   `INJ (\i. (q:num->A)((i + d) MOD n))
        (cyclic_indices n) (:A)`
  (LABEL_TAC "offset_injective") THENL
   [MATCH_MP_TAC INJ_CYCLIC_OFFSET THEN
    USE_THEN "injective" ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
  INTRO_TAC "ibound jbound equal" THEN
  ASM_CASES_TAC `i < n - d + 1` THENL
   [ASM_CASES_TAC `j < n - d + 1` THENL
     [SUBGOAL_THEN
       `split_fan_boundary (q:num->A) n d v i =
        q((i + d) MOD n)`
      (LABEL_TAC "i_value") THENL
       [MATCH_MP_TAC SPLIT_FAN_BOUNDARY_PREFIX THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `split_fan_boundary (q:num->A) n d v j =
        q((j + d) MOD n)`
      (LABEL_TAC "j_value") THENL
       [MATCH_MP_TAC SPLIT_FAN_BOUNDARY_PREFIX THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "offset_injective" MP_TAC THEN
      REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
      DISCH_THEN(MATCH_MP_TAC o SPECL [`i:num`; `j:num`]) THEN
      REPEAT CONJ_TAC THENL
       [ASM_ARITH_TAC;
        ASM_ARITH_TAC;
        ASM_MESON_TAC[]];
      SUBGOAL_THEN `j = n - d + 1` SUBST_ALL_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN
         `split_fan_boundary (q:num->A) n d v i =
          q((i + d) MOD n)`
        (LABEL_TAC "i_value") THENL
         [MATCH_MP_TAC SPLIT_FAN_BOUNDARY_PREFIX THEN ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        SUBGOAL_THEN
         `split_fan_boundary (q:num->A) n d v (n - d + 1) = v`
        (LABEL_TAC "last_value") THENL
         [MATCH_MP_TAC SPLIT_FAN_BOUNDARY_LAST THEN ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        SUBGOAL_THEN `v IN cyclic_vertices (q:num->A) n`
         (fun th -> USE_THEN "outside"
           (fun nth -> CONTR_TAC(MP (NOT_ELIM nth) th))) THEN
        REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
        EXISTS_TAC `(i + d) MOD n` THEN
        CONJ_TAC THENL
         [REWRITE_TAC[MOD_LT_EQ_LT] THEN ASM_ARITH_TAC;
          ASM_MESON_TAC[]]]];
    ASM_CASES_TAC `j < n - d + 1` THENL
     [SUBGOAL_THEN `i = n - d + 1` SUBST_ALL_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN
         `split_fan_boundary (q:num->A) n d v j =
          q((j + d) MOD n)`
        (LABEL_TAC "j_value") THENL
         [MATCH_MP_TAC SPLIT_FAN_BOUNDARY_PREFIX THEN ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        SUBGOAL_THEN
         `split_fan_boundary (q:num->A) n d v (n - d + 1) = v`
        (LABEL_TAC "last_value") THENL
         [MATCH_MP_TAC SPLIT_FAN_BOUNDARY_LAST THEN ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        SUBGOAL_THEN `v IN cyclic_vertices (q:num->A) n`
         (fun th -> USE_THEN "outside"
           (fun nth -> CONTR_TAC(MP (NOT_ELIM nth) th))) THEN
        REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
        EXISTS_TAC `(j + d) MOD n` THEN
        CONJ_TAC THENL
         [REWRITE_TAC[MOD_LT_EQ_LT] THEN ASM_ARITH_TAC;
          ASM_MESON_TAC[]]];
      ASM_ARITH_TAC]]);;

let MOD_ADD_WRAP_SUB = prove
 (`!i d n.
        d < n /\ i < n /\ ~(i < n - d + 1)
        ==> (i + d) MOD n = i - (n - d)`,
  REPEAT GEN_TAC THEN INTRO_TAC "dbound ibound after_prefix" THEN
  (fun (asl,_ as g) ->
    LABEL_TAC "wraps"
     (MATCH_MP
       (ARITH_RULE
         `(d:num) < n /\ ~(i < n - d + 1) ==> ~(i + d < n)`)
       (CONJ (assoc "dbound" asl) (assoc "after_prefix" asl))) g) THEN
  MP_TAC(SPECL [`i:num`; `d:num`; `n:num`] MOD_ADD_CASES) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN SUBST1_TAC THEN ASM_ARITH_TAC);;

let SPLIT_FAN_BOUNDARY_DELETE_LAST = prove
 (`!q:num->A. !n d v:A. !i.
        0 < d /\ d < n /\ i < n
        ==> cyclic_delete_last
             (split_fan_boundary q n d v) q (n - d + 2) i =
            q((i + d) MOD n)`,
  REPEAT GEN_TAC THEN INTRO_TAC "dpositive dbound ibound" THEN
  SUBGOAL_THEN `(n - d + 2) - 1 = n - d + 1`
  (LABEL_TAC "prefix_cut") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(n - d + 2) - 2 = n - d`
  (LABEL_TAC "chain_cut") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `i < n - d + 1` THENL
   [ASM_REWRITE_TAC[cyclic_delete_last; split_fan_boundary];
    SUBGOAL_THEN `(i + d) MOD n = i - (n - d)`
    (LABEL_TAC "mod_value") THENL
     [MATCH_MP_TAC MOD_ADD_WRAP_SUB THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[cyclic_delete_last; split_fan_boundary] THEN
    AP_TERM_TAC]);;

let BOUNDARY_EULER_ROTATION_CONG = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !q p:num->A. !n.
        simple_graph_cycle E q n /\
        boundary_euler_rotation V E q n r /\
        (!i. i < n ==> p i = q i)
        ==> boundary_euler_rotation V E p n r`,
  REPEAT GEN_TAC THEN INTRO_TAC "cycle boundary agree" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective edges" THEN
  SUBGOAL_THEN `simple_graph_cycle E (p:num->A) n`
  (LABEL_TAC "new_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_CONG THEN
    EXISTS_TAC `q:num->A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `cyclic_face_successors E r (q:num->A) n`
  (LABEL_TAC "successors") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
      `r:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_IMP_CYCLIC_FACE_SUCCESSORS) THEN
    REPEAT CONJ_TAC THENL
     [ASM_ARITH_TAC;
      USE_THEN "injective" ACCEPT_TAC;
      USE_THEN "edges" ACCEPT_TAC;
      USE_THEN "boundary" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `cyclic_face_successors E r (p:num->A) n`
  (LABEL_TAC "new_successors") THENL
   [MATCH_MP_TAC CYCLIC_FACE_SUCCESSORS_CONG THEN
    EXISTS_TAC `q:num->A` THEN
    REPEAT CONJ_TAC THENL
     [ASM_ARITH_TAC;
      USE_THEN "agree" ACCEPT_TAC;
      USE_THEN "successors" ACCEPT_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC BOUNDARY_EULER_ROTATION_OF_CYCLIC_FACE_SUCCESSORS THEN
  REPEAT CONJ_TAC THENL
   [ASM_ARITH_TAC;
    USE_THEN "boundary" MP_TAC THEN
    REWRITE_TAC[boundary_euler_rotation] THEN MESON_TAC[];
    USE_THEN "new_successors" ACCEPT_TAC]);;

let INJ_CYCLIC_INDICES_MONO = prove
 (`!q:num->A. !m n.
        INJ q (cyclic_indices n) (:A) /\ m <= n
        ==> INJ q (cyclic_indices m) (:A)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective bound" THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
  MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
  INTRO_TAC "ibound jbound equal" THEN
  USE_THEN "injective" MP_TAC THEN
  REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
  DISCH_THEN(MATCH_MP_TAC o SPECL [`i:num`; `j:num`]) THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let CYCLIC_VERTICES_MONO = prove
 (`!q:num->A. !m n.
        m <= n ==> cyclic_vertices q m SUBSET cyclic_vertices q n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "bound") THEN
  REWRITE_TAC[SUBSET; IN_CYCLIC_VERTICES] THEN
  X_GEN_TAC `x:A` THEN
  INTRO_TAC "@i. index value" THEN
  EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let SPLIT_FAN_BOUNDARY_ZERO = prove
 (`!q:num->A. !n d v:A.
        0 < d /\ d < n
        ==> split_fan_boundary q n d v 0 = q d`,
  REPEAT GEN_TAC THEN INTRO_TAC "dpositive dbound" THEN
  REWRITE_TAC[split_fan_boundary; ADD_CLAUSES] THEN
  ASM_SIMP_TAC[MOD_LT] THEN ASM_ARITH_TAC);;

let SPLIT_FAN_BOUNDARY_PENULTIMATE = prove
 (`!q:num->A. !n d v:A.
        0 < d /\ d < n
        ==> split_fan_boundary q n d v (n - d) = q 0`,
  REPEAT GEN_TAC THEN INTRO_TAC "dpositive dbound" THEN
  REWRITE_TAC[split_fan_boundary] THEN
  SUBGOAL_THEN `n - d < n - d + 1` ASSUME_TAC THENL
   [ARITH_TAC;
    ASM_REWRITE_TAC[]] THEN
  (fun (asl,_ as g) ->
    LABEL_TAC "sum"
     (MATCH_MP (ISPECL [`n:num`; `d:num`] SUB_ADD)
       (MATCH_MP LT_IMP_LE (assoc "dbound" asl))) g) THEN
  ASM_REWRITE_TAC[MOD_REFL]);;

let SPLIT_FAN_BOUNDARY_VERTICES_SUBSET = prove
 (`!q:num->A. !n d v:A. !V.
        cyclic_vertices q n SUBSET V /\
        0 < d /\ d < n
        ==> cyclic_vertices (split_fan_boundary q n d v)
             (n - d + 2) SUBSET (v INSERT V)`,
  REPEAT GEN_TAC THEN INTRO_TAC "vertices dpositive dbound" THEN
  REWRITE_TAC[SUBSET; IN_CYCLIC_VERTICES] THEN
  X_GEN_TAC `x:A` THEN INTRO_TAC "@i. index value" THEN
  ASM_CASES_TAC `i < n - d + 1` THENL
   [REWRITE_TAC[IN_INSERT] THEN DISJ2_TAC THEN
    USE_THEN "vertices" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `(i + d) MOD n` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[MOD_LT_EQ_LT] THEN ASM_ARITH_TAC;
      USE_THEN "value" (fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[split_fan_boundary]];
    SUBGOAL_THEN `i = n - d + 1` SUBST_ALL_TAC THENL
     [ASM_ARITH_TAC;
      ASM_REWRITE_TAC[split_fan_boundary; IN_INSERT]]]);;

let BOUNDARY_EULER_ROTATION_TWO_FANS_STRICT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !q:num->A. !n. !u v:A. !d.
        simple_graph_cycle E q n /\
        boundary_euler_rotation V E q n r /\
        connected_graph V E /\
        cyclic_vertices q n SUBSET V /\
        ~(u IN V) /\ ~(v IN V) /\ ~(u = v) /\
        0 < d /\ d < n
        ==> euler_planar_graph
             (u INSERT v INSERT V)
             (IMAGE (\z:A. {u,z})
                (cyclic_vertices (split_fan_boundary q n d v)
                  (n - d + 2)) UNION
              (IMAGE (\z:A. {v,z}) (cyclic_vertices q (d + 1)) UNION
               E))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "cycle boundary connected vertices u_fresh v_fresh distinct \
    dpositive dbound" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective edges" THEN
  ABBREV_TAC
   `Q:num->A = split_fan_boundary (q:num->A) n d v` THEN
  ABBREV_TAC
   `N:num = n - d + 2` THEN
  ABBREV_TAC
   `E1:(A->bool)->bool =
      IMAGE (\z:A. {v,z}) (cyclic_vertices q (d + 1)) UNION E` THEN
  SUBGOAL_THEN `~(v IN cyclic_vertices (q:num->A) n)`
  (LABEL_TAC "v_outside") THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle E
     (\i:num. (q:num->A)((i + d) MOD n)) n`
  (LABEL_TAC "offset_cycle") THENL
   [MATCH_MP_TAC SIMPLE_GRAPH_CYCLE_OFFSET THEN
    USE_THEN "cycle" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle E
     (cyclic_delete_last (Q:num->A) q N) n`
  (LABEL_TAC "old_cycle") THENL
   [MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`;
     `\i:num. (q:num->A)((i + d) MOD n)`;
      `cyclic_delete_last (Q:num->A) q N`; `n:num`]
    SIMPLE_GRAPH_CYCLE_CONG) THEN
    CONJ_TAC THENL
     [USE_THEN "offset_cycle" ACCEPT_TAC;
      X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
      EXPAND_TAC "Q" THEN EXPAND_TAC "N" THEN
      ASM_SIMP_TAC[SPLIT_FAN_BOUNDARY_DELETE_LAST]];
    ALL_TAC] THEN
  SUBGOAL_THEN
  `boundary_euler_rotation
     V E (\i:num. (q:num->A)((i + d) MOD n)) n r`
  (LABEL_TAC "offset_boundary") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`;
      `n:num`; `r:(A#A)->A#A`; `d:num`]
     BOUNDARY_EULER_ROTATION_OFFSET) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `boundary_euler_rotation
     V E (cyclic_delete_last (Q:num->A) q N) n r`
  (LABEL_TAC "old_boundary") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `\i:num. (q:num->A)((i + d) MOD n)`;
      `cyclic_delete_last (Q:num->A) q N`; `n:num`]
     BOUNDARY_EULER_ROTATION_CONG) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "offset_cycle" ACCEPT_TAC;
        USE_THEN "offset_boundary" ACCEPT_TAC;
        X_GEN_TAC `i:num` THEN DISCH_THEN(LABEL_TAC "index") THEN
        EXPAND_TAC "Q" THEN EXPAND_TAC "N" THEN
        ASM_SIMP_TAC[SPLIT_FAN_BOUNDARY_DELETE_LAST]];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `3 <= N` (LABEL_TAC "Nlarge") THENL
   [EXPAND_TAC "N" THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (Q:num->A) (cyclic_indices N) (:A)`
  (LABEL_TAC "Q_injective") THENL
   [EXPAND_TAC "Q" THEN EXPAND_TAC "N" THEN
    MATCH_MP_TAC SPLIT_FAN_BOUNDARY_INJECTIVE THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(Q:num->A) (N - 1) = v`
  (LABEL_TAC "Q_last") THENL
   [EXPAND_TAC "Q" THEN EXPAND_TAC "N" THEN
    SUBGOAL_THEN `(n - d + 2) - 1 = n - d + 1` SUBST1_TAC THENL
     [ASM_ARITH_TAC;
      ASM_SIMP_TAC[SPLIT_FAN_BOUNDARY_LAST]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(Q:num->A) (N - 2) = q 0`
  (LABEL_TAC "Q_penultimate") THENL
   [EXPAND_TAC "Q" THEN EXPAND_TAC "N" THEN
    SUBGOAL_THEN `(n - d + 2) - 2 = n - d` SUBST1_TAC THENL
     [ASM_ARITH_TAC;
      ASM_SIMP_TAC[SPLIT_FAN_BOUNDARY_PENULTIMATE]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(Q:num->A) 0 = (q:num->A) (d:num)`
  (LABEL_TAC "Q_zero") THENL
   [EXPAND_TAC "Q" THEN
    MP_TAC(ISPECL [`q:num->A`; `n:num`; `d:num`; `v:A`]
      SPLIT_FAN_BOUNDARY_ZERO) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(d - 1) + 1 = d` (LABEL_TAC "fan_last") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(d - 1) + 2 = d + 1` (LABEL_TAC "fan_size") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(N - 1) + (d - 1) = n`
  (LABEL_TAC "old_length") THENL
   [EXPAND_TAC "N" THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (q:num->A) (cyclic_indices (d + 1)) (:A)`
  (LABEL_TAC "path_injective") THENL
   [MATCH_MP_TAC INJ_CYCLIC_INDICES_MONO THEN
    EXISTS_TAC `n:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `cyclic_vertices (q:num->A) (d + 1) SUBSET V`
  (LABEL_TAC "path_vertices") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `cyclic_vertices (q:num->A) n` THEN CONJ_TAC THENL
     [MATCH_MP_TAC CYCLIC_VERTICES_MONO THEN ASM_ARITH_TAC;
      USE_THEN "vertices" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?r1:(A#A)->A#A.
      boundary_euler_rotation (v INSERT V) E1 (Q:num->A) N r1`
  (X_CHOOSE_THEN `r1:(A#A)->A#A` (LABEL_TAC "first_boundary"))
  THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `Q:num->A`; `q:num->A`;
      `N:num`; `d - 1`; `r:(A#A)->A#A`]
     BOUNDARY_EULER_ROTATION_CYCLIC_FAN) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "old_length" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "old_cycle" ACCEPT_TAC;
        USE_THEN "old_length" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "old_boundary" ACCEPT_TAC;
        USE_THEN "Nlarge" ACCEPT_TAC;
        ASM_REWRITE_TAC[];
        USE_THEN "fan_size" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "path_injective" ACCEPT_TAC;
        USE_THEN "fan_size" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "path_vertices" ACCEPT_TAC;
        ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[]];
      DISCH_THEN(MP_TAC)] THEN
    EXPAND_TAC "E1" THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `simple_graph_cycle E1 (Q:num->A) N`
  (LABEL_TAC "new_cycle") THENL
   [MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `Q:num->A`; `q:num->A`;
      `N:num`; `d - 1`]
     SIMPLE_GRAPH_CYCLE_INSERT_LAST_VERTEX) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [USE_THEN "old_length" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "old_cycle" ACCEPT_TAC;
        USE_THEN "Nlarge" ACCEPT_TAC;
        USE_THEN "Q_injective" ACCEPT_TAC;
        ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[]];
      DISCH_THEN(MP_TAC)] THEN
    EXPAND_TAC "E1" THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph (v INSERT (V:A->bool)) (E1:(A->bool)->bool)`
  (LABEL_TAC "new_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`v INSERT V:A->bool`;
      `{v:A,(q:num->A) 0} INSERT E:(A->bool)->bool`;
      `E1:(A->bool)->bool`]
     CONNECTED_GRAPH_MONO) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `(q:num->A) 0`]
       CONNECTED_GRAPH_INSERT_EDGE_VERTEX) THEN
      CONJ_TAC THENL
       [USE_THEN "connected" ACCEPT_TAC;
        USE_THEN "vertices" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
        EXISTS_TAC `0` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
      EXPAND_TAC "E1" THEN
      REWRITE_TAC[SUBSET; IN_INSERT; IN_UNION; IN_IMAGE] THEN
      X_GEN_TAC `e:A->bool` THEN
      DISCH_THEN(DISJ_CASES_THEN2 SUBST1_TAC
        (LABEL_TAC "old_edge")) THENL
       [DISJ1_TAC THEN EXISTS_TAC `(q:num->A) 0` THEN
        CONJ_TAC THENL
         [REFL_TAC;
          REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
          EXISTS_TAC `0` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
        ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_vertices (Q:num->A) N SUBSET (v INSERT V)`
  (LABEL_TAC "new_vertices") THENL
   [EXPAND_TAC "Q" THEN EXPAND_TAC "N" THEN
    MATCH_MP_TAC SPLIT_FAN_BOUNDARY_VERTICES_SUBSET THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) IN v INSERT (V:A->bool))`
  (LABEL_TAC "u_new_fresh") THENL
   [ASM_REWRITE_TAC[IN_INSERT];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`v INSERT V:A->bool`; `E1:(A->bool)->bool`;
    `r1:(A#A)->A#A`; `Q:num->A`; `N:num`; `u:A`]
   BOUNDARY_EULER_ROTATION_FULL_FAN) THEN
  ASM_REWRITE_TAC[] THEN
  EXPAND_TAC "E1" THEN EXPAND_TAC "Q" THEN EXPAND_TAC "N" THEN
  ALL_TAC);;

let SPLIT_FAN_BOUNDARY_ONE_VERTICES_SUPERSET = prove
 (`!q:num->A. !n v:A.
        3 <= n
        ==> v INSERT cyclic_vertices q n SUBSET
            cyclic_vertices (split_fan_boundary q n 1 v) (n + 1)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "large") THEN
  REWRITE_TAC[SUBSET; IN_INSERT; IN_CYCLIC_VERTICES] THEN
  X_GEN_TAC `x:A` THEN
  DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "last")
    (X_CHOOSE_THEN `j:num`
      (CONJUNCTS_THEN2 (LABEL_TAC "index") (LABEL_TAC "value")))) THENL
   [EXISTS_TAC `n:num` THEN
    CONJ_TAC THENL
     [ASM_ARITH_TAC;
      USE_THEN "last" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[split_fan_boundary] THEN
      SUBGOAL_THEN `n - 1 + 1 = n` SUBST1_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[LT_REFL]]];
    ASM_CASES_TAC `(j:num) = 0` THENL
     [FIRST_X_ASSUM SUBST_ALL_TAC THEN
      EXISTS_TAC `n - 1` THEN
      CONJ_TAC THENL
       [ASM_ARITH_TAC;
        USE_THEN "value" (fun th -> REWRITE_TAC[GSYM th]) THEN
        REWRITE_TAC[split_fan_boundary] THEN
        SUBGOAL_THEN `n - 1 + 1 = n` SUBST1_TAC THENL
         [ASM_ARITH_TAC;
          SUBGOAL_THEN `n - 1 < n` (LABEL_TAC "predecessor") THENL
           [ASM_ARITH_TAC;
            ASM_REWRITE_TAC[MOD_REFL]]]];
      EXISTS_TAC `j - 1` THEN
      CONJ_TAC THENL
       [ASM_ARITH_TAC;
        USE_THEN "value" (fun th -> REWRITE_TAC[GSYM th]) THEN
        REWRITE_TAC[split_fan_boundary] THEN
        SUBGOAL_THEN `n - 1 + 1 = n` SUBST1_TAC THENL
         [ASM_ARITH_TAC;
          SUBGOAL_THEN `j - 1 + 1 = j` SUBST1_TAC THENL
           [ASM_ARITH_TAC;
            SUBGOAL_THEN `j - 1 < n` (LABEL_TAC "predecessor") THENL
             [ASM_ARITH_TAC;
              ASM_SIMP_TAC[MOD_LT]]]]]]]);;

let BOUNDARY_EULER_ROTATION_TWO_FANS_SINGLETON = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !q:num->A. !n. !u v:A.
        simple_graph_cycle E q n /\
        boundary_euler_rotation V E q n r /\
        connected_graph V E /\
        cyclic_vertices q n SUBSET V /\
        ~(u IN V) /\ ~(v IN V) /\ ~(u = v)
        ==> euler_planar_graph
             (u INSERT v INSERT V)
             (IMAGE (\z:A. {u,z})
                (v INSERT cyclic_vertices q n) UNION
              (IMAGE (\z:A. {v,z}) (cyclic_vertices q 1) UNION E))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "cycle boundary connected vertices u_fresh v_fresh distinct" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective edges" THEN
  SUBGOAL_THEN
   `euler_planar_graph
      (u INSERT v INSERT (V:A->bool))
      (IMAGE (\z:A. {u,z})
         (cyclic_vertices (split_fan_boundary q n 1 v) (n + 1)) UNION
       (IMAGE (\z:A. {v,z}) (cyclic_vertices q 2) UNION E))`
  (LABEL_TAC "with_auxiliary_spoke") THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `q:num->A`; `n:num`; `u:A`; `v:A`; `1`]
     BOUNDARY_EULER_ROTATION_TWO_FANS_STRICT) THEN
    ASM_REWRITE_TAC[] THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      DISCH_THEN(LABEL_TAC "strict_with_auxiliary") THEN
      SUBGOAL_THEN `n - 1 + 2 = n + 1`
      (LABEL_TAC "boundary_length") THENL
       [ASM_ARITH_TAC;
        USE_THEN "boundary_length"
         (fun th -> REWRITE_TAC[GSYM th]) THEN
        USE_THEN "strict_with_auxiliary"
         (ACCEPT_TAC o CONV_RULE NUM_REDUCE_CONV)]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `v INSERT cyclic_vertices (q:num->A) n SUBSET
    cyclic_vertices (split_fan_boundary q n 1 v) (n + 1)`
  (LABEL_TAC "first_fan_subset") THENL
   [MATCH_MP_TAC SPLIT_FAN_BOUNDARY_ONE_VERTICES_SUPERSET THEN
    USE_THEN "large" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_vertices (q:num->A) 1 SUBSET cyclic_vertices q 2`
  (LABEL_TAC "second_fan_subset") THENL
   [MATCH_MP_TAC CYCLIC_VERTICES_MONO THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (\z:A. {u,z}) (v INSERT cyclic_vertices q n) SUBSET
    IMAGE (\z:A. {u,z})
      (cyclic_vertices (split_fan_boundary q n 1 v) (n + 1))`
  (LABEL_TAC "first_edges_subset") THENL
   [MATCH_MP_TAC IMAGE_SUBSET THEN
    USE_THEN "first_fan_subset" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `IMAGE (\z:A. {v,z}) (cyclic_vertices q 1) SUBSET
    IMAGE (\z:A. {v,z}) (cyclic_vertices q 2)`
  (LABEL_TAC "second_edges_subset") THENL
   [MATCH_MP_TAC IMAGE_SUBSET THEN
    USE_THEN "second_fan_subset" ACCEPT_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`u INSERT v INSERT V:A->bool`;
    `IMAGE (\z:A. {u,z})
       (cyclic_vertices (split_fan_boundary q n 1 v) (n + 1)) UNION
     (IMAGE (\z:A. {v,z}) (cyclic_vertices q 2) UNION E)`;
    `IMAGE (\z:A. {u,z}) (v INSERT cyclic_vertices q n) UNION
     (IMAGE (\z:A. {v,z}) (cyclic_vertices q 1) UNION E)`]
   EULER_PLANAR_GRAPH_SUBSET_EDGES) THEN
  CONJ_TAC THENL
   [USE_THEN "with_auxiliary_spoke" ACCEPT_TAC;
    REWRITE_TAC[SUBSET; IN_UNION] THEN
    X_GEN_TAC `e:A->bool` THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "first_edge")
      (DISJ_CASES_THEN2 (LABEL_TAC "second_edge")
        (LABEL_TAC "old_edge"))) THENL
     [DISJ1_TAC THEN
      USE_THEN "first_edges_subset"
       (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "first_edge" ACCEPT_TAC;
      DISJ2_TAC THEN DISJ1_TAC THEN
      USE_THEN "second_edges_subset"
       (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "second_edge" ACCEPT_TAC;
      ASM_REWRITE_TAC[]]]);;

let SPLIT_FAN_BOUNDARY_ZERO_VERTICES_SUBSET = prove
 (`!q:num->A. !n v:A.
        3 <= n
        ==> cyclic_vertices (split_fan_boundary q n 0 v) (n + 2)
            SUBSET v INSERT cyclic_vertices q n`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "large") THEN
  REWRITE_TAC[SUBSET; IN_CYCLIC_VERTICES] THEN
  X_GEN_TAC `x:A` THEN
  INTRO_TAC "@i. index value" THEN
  ASM_CASES_TAC `(i:num) < n + 1` THENL
   [REWRITE_TAC[IN_INSERT] THEN DISJ2_TAC THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
    EXISTS_TAC `i MOD n` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[MOD_LT_EQ_LT] THEN ASM_ARITH_TAC;
      USE_THEN "value" (fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[split_fan_boundary; SUB_0; ADD_CLAUSES]];
    REWRITE_TAC[IN_INSERT] THEN DISJ1_TAC THEN
    USE_THEN "value" (fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[split_fan_boundary; SUB_0; ADD_CLAUSES]]);;

let BOUNDARY_EULER_ROTATION_TWO_FANS = prove
 (`!V:A->bool. !E:(A->bool)->bool. !r:(A#A)->A#A.
   !q:num->A. !n. !u v:A. !d.
        simple_graph_cycle E q n /\
        boundary_euler_rotation V E q n r /\
        connected_graph V E /\
        cyclic_vertices q n SUBSET V /\
        ~(u IN V) /\ ~(v IN V) /\ ~(u = v) /\
        d < n
        ==> euler_planar_graph
             (u INSERT v INSERT V)
             (IMAGE (\z:A. {u,z})
                (cyclic_vertices (split_fan_boundary q n d v)
                  (n - d + 2)) UNION
              (IMAGE (\z:A. {v,z}) (cyclic_vertices q (d + 1)) UNION
               E))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "cycle boundary connected vertices u_fresh v_fresh distinct dbound" THEN
  USE_THEN "cycle" MP_TAC THEN
  REWRITE_TAC[simple_graph_cycle] THEN
  INTRO_TAC "large injective edges" THEN
  ASM_CASES_TAC `(d:num) = 0` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    SUBGOAL_THEN
     `euler_planar_graph
        (u INSERT v INSERT (V:A->bool))
        (IMAGE (\z:A. {u,z}) (v INSERT cyclic_vertices q n) UNION
         (IMAGE (\z:A. {v,z}) (cyclic_vertices q 1) UNION E))`
    (LABEL_TAC "singleton") THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
        `q:num->A`; `n:num`; `u:A`; `v:A`]
       BOUNDARY_EULER_ROTATION_TWO_FANS_SINGLETON) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `cyclic_vertices (split_fan_boundary q n 0 v) (n + 2) SUBSET
      v INSERT cyclic_vertices (q:num->A) n`
    (LABEL_TAC "first_fan_subset") THENL
     [MATCH_MP_TAC SPLIT_FAN_BOUNDARY_ZERO_VERTICES_SUBSET THEN
      USE_THEN "large" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `IMAGE (\z:A. {u,z})
        (cyclic_vertices (split_fan_boundary q n 0 v) (n + 2)) SUBSET
      IMAGE (\z:A. {u,z}) (v INSERT cyclic_vertices q n)`
    (LABEL_TAC "first_edges_subset") THENL
     [MATCH_MP_TAC IMAGE_SUBSET THEN
      USE_THEN "first_fan_subset" ACCEPT_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[SUB_0; ADD_CLAUSES] THEN
    MATCH_MP_TAC(ISPECL
     [`u INSERT v INSERT V:A->bool`;
      `IMAGE (\z:A. {u,z}) (v INSERT cyclic_vertices q n) UNION
       (IMAGE (\z:A. {v,z}) (cyclic_vertices q 1) UNION E)`;
      `IMAGE (\z:A. {u,z})
         (cyclic_vertices (split_fan_boundary q n 0 v) (n + 2)) UNION
       (IMAGE (\z:A. {v,z}) (cyclic_vertices q 1) UNION E)`]
     EULER_PLANAR_GRAPH_SUBSET_EDGES) THEN
    CONJ_TAC THENL
     [USE_THEN "singleton" ACCEPT_TAC;
      REWRITE_TAC[SUBSET; IN_UNION] THEN
      X_GEN_TAC `e:A->bool` THEN
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "first_edge")
        (DISJ_CASES_THEN2 (LABEL_TAC "second_edge")
          (LABEL_TAC "old_edge"))) THENL
       [DISJ1_TAC THEN
        USE_THEN "first_edges_subset"
         (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "first_edge" ACCEPT_TAC;
        DISJ2_TAC THEN DISJ1_TAC THEN
        USE_THEN "second_edge" ACCEPT_TAC;
        ASM_REWRITE_TAC[]]];
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
     `q:num->A`; `n:num`; `u:A`; `v:A`; `d:num`]
     BOUNDARY_EULER_ROTATION_TWO_FANS_STRICT) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]);;

let SPLIT_FAN_BOUNDARY_APEX = prove
 (`!q:num->A. !n d v:A.
        d < n
        ==> v IN cyclic_vertices
                  (split_fan_boundary q n d v) (n - d + 2)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "dbound") THEN
  REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
  EXISTS_TAC `n - d + 1` THEN
  CONJ_TAC THENL
   [ASM_ARITH_TAC;
    ASM_CASES_TAC `(d:num) = 0` THENL
     [FIRST_X_ASSUM SUBST_ALL_TAC THEN
      REWRITE_TAC[split_fan_boundary; SUB_0; LT_REFL];
      MATCH_MP_TAC EQ_SYM THEN
      MATCH_MP_TAC SPLIT_FAN_BOUNDARY_LAST THEN
      ASM_ARITH_TAC]]);;

let SPLIT_FAN_BOUNDARY_OUTSIDE_VERTEX = prove
 (`!q:num->A. !n:num. !d:num. !i:num. !v:A.
        d < n /\ i < n /\ (i = 0 \/ d <= i)
        ==> q i IN cyclic_vertices
                    (split_fan_boundary q n d v) (n - d + 2)`,
  REPEAT GEN_TAC THEN INTRO_TAC "dbound index outside" THEN
  REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
  ASM_CASES_TAC `(d:num) = 0` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    EXISTS_TAC `i:num` THEN
    CONJ_TAC THENL
     [ASM_ARITH_TAC;
      REWRITE_TAC[split_fan_boundary; SUB_0; ADD_CLAUSES] THEN
      SUBGOAL_THEN `(i:num) < n + 1` (LABEL_TAC "prefix") THENL
       [ASM_ARITH_TAC;
        ASM_SIMP_TAC[MOD_LT]]];
    USE_THEN "outside"
     (DISJ_CASES_THEN2 (LABEL_TAC "zero_index")
       (LABEL_TAC "suffix_index")) THENL
     [USE_THEN "zero_index" SUBST_ALL_TAC THEN
      EXISTS_TAC `(n:num) - (d:num)` THEN
      CONJ_TAC THENL
       [ASM_ARITH_TAC;
        MATCH_MP_TAC EQ_SYM THEN
        MATCH_MP_TAC SPLIT_FAN_BOUNDARY_PENULTIMATE THEN
        ASM_ARITH_TAC];
      EXISTS_TAC `(i:num) - (d:num)` THEN
      CONJ_TAC THENL
       [ASM_ARITH_TAC;
        REWRITE_TAC[split_fan_boundary] THEN
        SUBGOAL_THEN `i - d < n - d + 1`
        (LABEL_TAC "prefix") THENL
         [ASM_ARITH_TAC;
          USE_THEN "prefix" (fun th -> REWRITE_TAC[th]) THEN
          ASM_SIMP_TAC[SUB_ADD; MOD_LT]]]]] THEN
  ALL_TAC);;

let BOUNDARY_EULER_ROTATION_SPOKE_INTERVAL = prove
 (`!V:A->bool. !E B:(A->bool)->bool. !r:(A#A)->A#A.
   !q:num->A. !n. !u v:A. !d.
        simple_graph_cycle E q n /\
        boundary_euler_rotation V E q n r /\
        connected_graph V E /\
        cyclic_vertices q n SUBSET V /\
        ~(u IN V) /\ ~(v IN V) /\ ~(u = v) /\
        d < n /\
        (!e:A->bool. e IN B
             ==> e IN E \/
                 e = {u,v} \/
                 (?i. i < n /\ (i = 0 \/ d <= i) /\ e = {u,q i}) \/
                 (?i. i < n /\ i <= d /\ e = {v,q i}))
        ==> euler_planar_graph (u INSERT v INSERT V) B`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "cycle boundary connected vertices u_fresh v_fresh distinct \
    dbound edge_structure" THEN
  SUBGOAL_THEN
   `euler_planar_graph
      (u INSERT v INSERT (V:A->bool))
      (IMAGE (\z:A. {u,z})
         (cyclic_vertices (split_fan_boundary q n d v)
           (n - d + 2)) UNION
       (IMAGE (\z:A. {v,z}) (cyclic_vertices q (d + 1)) UNION E))`
  (LABEL_TAC "two_fans") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `r:(A#A)->A#A`;
      `q:num->A`; `n:num`; `u:A`; `v:A`; `d:num`]
     BOUNDARY_EULER_ROTATION_TWO_FANS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`u INSERT v INSERT V:A->bool`;
    `IMAGE (\z:A. {u,z})
       (cyclic_vertices (split_fan_boundary q n d v)
         (n - d + 2)) UNION
     (IMAGE (\z:A. {v,z}) (cyclic_vertices q (d + 1)) UNION E)`;
    `B:(A->bool)->bool`]
   EULER_PLANAR_GRAPH_SUBSET_EDGES) THEN
  CONJ_TAC THENL
   [USE_THEN "two_fans" ACCEPT_TAC;
    REWRITE_TAC[SUBSET; IN_UNION; IN_IMAGE] THEN
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    (fun (asl,_ as g) ->
      MP_TAC(MATCH_MP
       (SPEC `e:A->bool` (assoc "edge_structure" asl))
       (assoc "edge" asl)) g) THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "old_edge")
      (DISJ_CASES_THEN2 (LABEL_TAC "central_edge")
       (DISJ_CASES_THEN2
        (X_CHOOSE_THEN `i:num`
         (CONJUNCTS_THEN2 (LABEL_TAC "index")
          (CONJUNCTS_THEN2 (LABEL_TAC "outside")
           (LABEL_TAC "u_edge"))))
        (X_CHOOSE_THEN `i:num`
         (CONJUNCTS_THEN2 (LABEL_TAC "index")
          (CONJUNCTS_THEN2 (LABEL_TAC "interval")
           (LABEL_TAC "v_edge"))))))) THENL
     [ASM_REWRITE_TAC[];
      DISJ1_TAC THEN EXISTS_TAC `v:A` THEN
      CONJ_TAC THENL
       [USE_THEN "central_edge" ACCEPT_TAC;
        MATCH_MP_TAC SPLIT_FAN_BOUNDARY_APEX THEN
        USE_THEN "dbound" ACCEPT_TAC];
      DISJ1_TAC THEN EXISTS_TAC `(q:num->A) i` THEN
      CONJ_TAC THENL
       [USE_THEN "u_edge" ACCEPT_TAC;
        MATCH_MP_TAC SPLIT_FAN_BOUNDARY_OUTSIDE_VERTEX THEN
        ASM_REWRITE_TAC[]];
      DISJ2_TAC THEN DISJ1_TAC THEN
      EXISTS_TAC `(q:num->A) i` THEN
      CONJ_TAC THENL
       [USE_THEN "v_edge" ACCEPT_TAC;
        REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
        EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]]]);;

(* ------------------------------------------------------------------------- *)
(* Sparse spoke intervals on a facial cycle.                                 *)
(*                                                                           *)
(* Unlike GRAPH_KURATOWSKI_FREE_SPOKE_INTERVAL, these results do not require *)
(* every cycle vertex to be joined to one of the two apices.                 *)
(* This is the form needed after deleting the merged vertex of a contraction *)
(* from a 3-connected planar graph.                                          *)
(* ------------------------------------------------------------------------- *)

let LINEAR_SPARSE_SPOKE_INTERVAL = prove
 (`!P Q:num->bool. !n.
        P 0 /\ ~Q 0 /\
        (?i. i < n /\ Q i) /\
        (!a b c d.
            a < b /\ b < c /\ c < d /\ d < n
            ==> ~(P a /\ Q b /\ P c /\ Q d))
        ==> ?a b.
              0 < a /\ a <= b /\ b < n /\
              (!i. i < n /\ Q i ==> a <= i /\ i <= b) /\
              (!i. a < i /\ i < b ==> ~P i)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "P0 not_Q0 Q_nonempty no_alternation" THEN
  MP_TAC(SPEC `\i:num. i < n /\ Q i` num_WOP) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@a. (a_index Qa) a_least" THEN
  SUBGOAL_THEN
   `(?i. i < n /\ (Q:num->bool) i) /\
    (?M. !i. i < n /\ Q i ==> i <= M)`
  (LABEL_TAC "Q_bounded") THENL
   [CONJ_TAC THENL
     [USE_THEN "Q_nonempty" ACCEPT_TAC;
      EXISTS_TAC `n:num` THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  USE_THEN "Q_bounded" MP_TAC THEN
  REWRITE_TAC[num_MAX] THEN
  INTRO_TAC "@b. (b_index Qb) b_greatest" THEN
  SUBGOAL_THEN `0 < (a:num)` (LABEL_TAC "a_positive") THENL
   [MATCH_MP_TAC(ARITH_RULE `~(a = 0) ==> 0 < a`) THEN
    DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "not_Q0" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "Qa" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(a:num) <= b` (LABEL_TAC "ab") THENL
   [USE_THEN "b_greatest" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i < n /\ (Q:num->bool) i ==> a <= i /\ i <= b`
  (LABEL_TAC "Q_interval") THENL
   [X_GEN_TAC `i:num` THEN INTRO_TAC "i_index Qi" THEN
    CONJ_TAC THENL
     [ASM_CASES_TAC `(i:num) < a` THENL
       [ASM_MESON_TAC[];
        ASM_ARITH_TAC];
      USE_THEN "b_greatest" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. (a:num) < i /\ i < b ==> ~(P:num->bool) i`
  (LABEL_TAC "P_not_interior") THENL
   [X_GEN_TAC `i:num` THEN INTRO_TAC "ai ib" THEN
    DISCH_THEN(LABEL_TAC "Pi") THEN
    USE_THEN "no_alternation"
     (MP_TAC o SPECL [`0`; `a:num`; `i:num`; `b:num`]) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      ASM_MESON_TAC[]];
    MAP_EVERY EXISTS_TAC [`a:num`; `b:num`] THEN
    ASM_REWRITE_TAC[]]);;

let CYCLIC_SPARSE_SPOKE_INTERVAL = prove
 (`!P Q:num->bool. !n.
        ((?k. k < n /\ P k /\ ~Q k) \/
         (?k. k < n /\ Q k /\ ~P k)) /\
        (?i. i < n /\ P i) /\
        (?i. i < n /\ Q i) /\
        (!k a b c d.
            a < b /\ b < c /\ c < d /\ d < n
            ==> ~(P((a + k) MOD n) /\ Q((b + k) MOD n) /\
                  P((c + k) MOD n) /\ Q((d + k) MOD n))) /\
        (!k a b c d.
            a < b /\ b < c /\ c < d /\ d < n
            ==> ~(Q((a + k) MOD n) /\ P((b + k) MOD n) /\
                  Q((c + k) MOD n) /\ P((d + k) MOD n)))
        ==> (?k a b.
                k < n /\ P k /\ ~Q k /\
                0 < a /\ a <= b /\ b < n /\
                (!i. i < n /\ Q((i + k) MOD n)
                     ==> a <= i /\ i <= b) /\
                (!i. a < i /\ i < b
                     ==> ~P((i + k) MOD n))) \/
            (?k a b.
                k < n /\ Q k /\ ~P k /\
                0 < a /\ a <= b /\ b < n /\
                (!i. i < n /\ P((i + k) MOD n)
                     ==> a <= i /\ i <= b) /\
                (!i. a < i /\ i < b
                     ==> ~Q((i + k) MOD n)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "exclusive P_nonempty Q_nonempty no_PQPQ no_QPQP" THEN
  USE_THEN "exclusive"
   (DISJ_CASES_THEN2
    (X_CHOOSE_THEN `k:num`
     (CONJUNCTS_THEN2 (LABEL_TAC "k_index")
      (CONJUNCTS_THEN2 (LABEL_TAC "Pk") (LABEL_TAC "not_Qk"))))
    (X_CHOOSE_THEN `k:num`
     (CONJUNCTS_THEN2 (LABEL_TAC "k_index")
      (CONJUNCTS_THEN2 (LABEL_TAC "Qk") (LABEL_TAC "not_Pk"))))) THENL
   [MP_TAC(SPECL
     [`\i:num. (P:num->bool)((i + k) MOD n)`;
      `\i:num. (Q:num->bool)((i + k) MOD n)`; `n:num`]
     LINEAR_SPARSE_SPOKE_INTERVAL) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [BETA_TAC THEN REWRITE_TAC[ADD_CLAUSES] THEN
        ASM_SIMP_TAC[MOD_LT];
        BETA_TAC THEN REWRITE_TAC[ADD_CLAUSES] THEN
        ASM_SIMP_TAC[MOD_LT];
        BETA_TAC THEN MATCH_MP_TAC CYCLIC_OFFSET_PREDICATE_NONEMPTY THEN
        USE_THEN "Q_nonempty" ACCEPT_TAC;
        MAP_EVERY X_GEN_TAC
         [`a:num`; `b:num`; `c:num`; `d:num`] THEN
        DISCH_THEN(LABEL_TAC "order") THEN BETA_TAC THEN
        USE_THEN "no_PQPQ"
         (MATCH_MP_TAC o SPECL
           [`k:num`; `a:num`; `b:num`; `c:num`; `d:num`]) THEN
        USE_THEN "order" ACCEPT_TAC];
      INTRO_TAC "@a b. a_positive ab b_index Q_interval P_interior"] THEN
    DISJ1_TAC THEN
    MAP_EVERY EXISTS_TAC [`k:num`; `a:num`; `b:num`] THEN
    ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [USE_THEN "Q_interval" (ACCEPT_TAC o BETA_RULE);
      USE_THEN "P_interior" (ACCEPT_TAC o BETA_RULE)];
    MP_TAC(SPECL
     [`\i:num. (Q:num->bool)((i + k) MOD n)`;
      `\i:num. (P:num->bool)((i + k) MOD n)`; `n:num`]
     LINEAR_SPARSE_SPOKE_INTERVAL) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [BETA_TAC THEN REWRITE_TAC[ADD_CLAUSES] THEN
        ASM_SIMP_TAC[MOD_LT];
        BETA_TAC THEN REWRITE_TAC[ADD_CLAUSES] THEN
        ASM_SIMP_TAC[MOD_LT];
        BETA_TAC THEN MATCH_MP_TAC CYCLIC_OFFSET_PREDICATE_NONEMPTY THEN
        USE_THEN "P_nonempty" ACCEPT_TAC;
        MAP_EVERY X_GEN_TAC
         [`a:num`; `b:num`; `c:num`; `d:num`] THEN
        DISCH_THEN(LABEL_TAC "order") THEN BETA_TAC THEN
        USE_THEN "no_QPQP"
         (MATCH_MP_TAC o SPECL
           [`k:num`; `a:num`; `b:num`; `c:num`; `d:num`]) THEN
        USE_THEN "order" ACCEPT_TAC];
      INTRO_TAC "@a b. a_positive ab b_index P_interval Q_interior"] THEN
    DISJ2_TAC THEN
    MAP_EVERY EXISTS_TAC [`k:num`; `a:num`; `b:num`] THEN
    ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [USE_THEN "P_interval" (ACCEPT_TAC o BETA_RULE);
      USE_THEN "Q_interior" (ACCEPT_TAC o BETA_RULE)]]);;

let GRAPH_KURATOWSKI_FREE_SPARSE_SPOKE_INTERVAL = prove
 (`!V:A->bool. !E:(A->bool)->bool.
   !q:num->A. !n. !u v:A.
        INJ q (cyclic_indices n) (:A) /\
        cyclic_vertices q n SUBSET V /\
        cyclic_edges q n SUBSET E /\
        u IN V /\ v IN V /\ ~(u = v) /\
        ~(u IN cyclic_vertices q n) /\
        ~(v IN cyclic_vertices q n) /\
        {u,v} IN E /\
        (?a b c.
            a < b /\ b < c /\ c < n /\
            ({u,q a} IN E \/ {v,q a} IN E) /\
            ({u,q b} IN E \/ {v,q b} IN E) /\
            ({u,q c} IN E \/ {v,q c} IN E)) /\
        (?i. i < n /\ {u,q i} IN E) /\
        (?i. i < n /\ {v,q i} IN E) /\
        ~graph_kuratowski_obstruction V E
        ==> (?k a b.
                k < n /\ {u,q k} IN E /\ ~({v,q k} IN E) /\
                0 < a /\ a <= b /\ b < n /\
                (!i. i < n /\ {v,q((i + k) MOD n)} IN E
                     ==> a <= i /\ i <= b) /\
                (!i. a < i /\ i < b
                     ==> ~({u,q((i + k) MOD n)} IN E))) \/
            (?k a b.
                k < n /\ {v,q k} IN E /\ ~({u,q k} IN E) /\
                0 < a /\ a <= b /\ b < n /\
                (!i. i < n /\ {u,q((i + k) MOD n)} IN E
                     ==> a <= i /\ i <= b) /\
                (!i. a < i /\ i < b
                     ==> ~({v,q((i + k) MOD n)} IN E)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "injective cycle_vertices cycle_edges \
    u_vertex v_vertex uv u_outside v_outside edge_uv \
    three u_nonempty v_nonempty unobstructed" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `q:num->A`; `n:num`; `u:A`; `v:A`]
   GRAPH_KURATOWSKI_FREE_SPOKE_PATTERNS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "no_three _ _" THEN
  SUBGOAL_THEN
   `(?k:num. k < n /\ {u:A,q k} IN E /\ ~({v,q k} IN E)) \/
    (?k:num. k < n /\ {v:A,q k} IN E /\ ~({u,q k} IN E))`
  (LABEL_TAC "exclusive") THENL
   [SUBGOAL_THEN
     `(?a b c:num.
          a < b /\ b < c /\ c < n /\
          ({u:A,q a} IN E \/ {v,q a} IN E) /\
          ({u,q b} IN E \/ {v,q b} IN E) /\
          ({u,q c} IN E \/ {v,q c} IN E)) /\
      (!a b c:num.
          a < b /\ b < c /\ c < n
          ==> ~(({u,q a} IN E /\ {v,q a} IN E) /\
                ({u,q b} IN E /\ {v,q b} IN E) /\
                {u,q c} IN E /\ {v,q c} IN E))`
    (LABEL_TAC "sparse_hypotheses") THENL
     [CONJ_TAC THENL
       [USE_THEN "three" ACCEPT_TAC;
        MAP_EVERY X_GEN_TAC [`a:num`; `b:num`; `c:num`] THEN
        DISCH_THEN(LABEL_TAC "order") THEN
        MATCH_MP_TAC(TAUT
         `~(pa /\ pb /\ pc /\ qa /\ qb /\ qc)
          ==> ~((pa /\ qa) /\ (pb /\ qb) /\ pc /\ qc)`) THEN
        USE_THEN "no_three"
         (MATCH_MP_TAC o SPECL [`a:num`; `b:num`; `c:num`]) THEN
        USE_THEN "order" ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "sparse_hypotheses" (fun hth ->
      ACCEPT_TAC(MP
       (BETA_RULE(ISPECL
        [`\i:num. ({u:A,q i}:A->bool) IN E`;
         `\i:num. ({v:A,q i}:A->bool) IN E`; `n:num`]
        SPARSE_SPOKE_EXCLUSIVE_POINT))
       hth));
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `q:num->A`; `n:num`; `u:A`; `v:A`]
   GRAPH_KURATOWSKI_FREE_ROTATED_SPOKE_PATTERNS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "no_PQPQ no_QPQP" THEN
  MATCH_MP_TAC(BETA_RULE(ISPECL
   [`\i:num. ({u:A,q i}:A->bool) IN E`;
    `\i:num. ({v:A,q i}:A->bool) IN E`; `n:num`]
   CYCLIC_SPARSE_SPOKE_INTERVAL)) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Kuratowski's theorem for 3-connected finite simple graphs.                *)
(* ------------------------------------------------------------------------- *)

let THREE_ORDERED_INDICES = prove
 (`!P:num->bool. !n.
        3 <= CARD {i | i < n /\ P i}
        ==> ?a b c.
              a < b /\ b < c /\ c < n /\ P a /\ P b /\ P c`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "card") THEN
  SUBGOAL_THEN `FINITE {i:num | i < n /\ P i}`
  (LABEL_TAC "finite") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `cyclic_indices n` THEN
    REWRITE_TAC[FINITE_CYCLIC_INDICES; SUBSET; IN_ELIM_THM;
                IN_CYCLIC_INDICES] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`3:num`; `{i:num | i < n /\ P i}`] CHOOSE_SUBSET_STRONG) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@S. subset size" THEN
  USE_THEN "size" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE_CONV `(S:num->bool) HAS_SIZE 3`] THEN
  INTRO_TAC "@i j k. jk ij ik S_eq" THEN
  SUBGOAL_THEN
   `(i:num) IN S /\ j IN S /\ k IN S`
  (CONJUNCTS_THEN2 (LABEL_TAC "i_member")
   (CONJUNCTS_THEN2 (LABEL_TAC "j_member")
    (LABEL_TAC "k_member"))) THENL
   [USE_THEN "S_eq" MP_TAC THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
    ALL_TAC] THEN
  USE_THEN "subset" MP_TAC THEN
  REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
  DISCH_THEN(LABEL_TAC "each") THEN
  MP_TAC(MATCH_MP
   (SPEC `i:num`
    (ASSUME `!x:num. x IN S ==> x < n /\ P x`))
   (ASSUME `(i:num) IN S`)) THEN
  INTRO_TAC "i_index Pi" THEN
  MP_TAC(MATCH_MP
   (SPEC `j:num`
    (ASSUME `!x:num. x IN S ==> x < n /\ P x`))
   (ASSUME `(j:num) IN S`)) THEN
  INTRO_TAC "j_index Pj" THEN
  MP_TAC(MATCH_MP
   (SPEC `k:num`
    (ASSUME `!x:num. x IN S ==> x < n /\ P x`))
   (ASSUME `(k:num) IN S`)) THEN
  INTRO_TAC "k_index Pk" THEN
  ASM_CASES_TAC `(i:num) < j` THENL
   [ASM_CASES_TAC `(j:num) < k` THENL
     [MAP_EVERY EXISTS_TAC [`i:num`; `j:num`; `k:num`];
      ASM_CASES_TAC `(i:num) < k` THENL
       [MAP_EVERY EXISTS_TAC [`i:num`; `k:num`; `j:num`];
        MAP_EVERY EXISTS_TAC [`k:num`; `i:num`; `j:num`]]];
    ASM_CASES_TAC `(i:num) < k` THENL
     [MAP_EVERY EXISTS_TAC [`j:num`; `i:num`; `k:num`];
      ASM_CASES_TAC `(j:num) < k` THENL
       [MAP_EVERY EXISTS_TAC [`j:num`; `k:num`; `i:num`];
        MAP_EVERY EXISTS_TAC [`k:num`; `j:num`; `i:num`]]]] THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let CYCLIC_SUBSET_INDEX_CARD = prove
 (`!q:num->A. !n N.
        INJ q (cyclic_indices n) (:A) /\
        N SUBSET cyclic_vertices q n
        ==> CARD N = CARD {i | i < n /\ q i IN N}`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective subset" THEN
  ABBREV_TAC `ix = {i:num | i < n /\ (q:num->A) i IN N}` THEN
  SUBGOAL_THEN `IMAGE (q:num->A) ix = N` (LABEL_TAC "image") THENL
   [EXPAND_TAC "ix" THEN
    USE_THEN "subset" MP_TAC THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN
    REWRITE_TAC[SUBSET; EXTENSION; IN_IMAGE; IN_ELIM_THM;
                IN_CYCLIC_VERTICES] THEN MESON_TAC[];
    ALL_TAC] THEN
  TRANS_TAC EQ_TRANS `CARD(IMAGE (q:num->A) ix)` THEN CONJ_TAC THENL
   [AP_TERM_TAC THEN USE_THEN "image" (ACCEPT_TAC o SYM);
    MATCH_MP_TAC CARD_IMAGE_INJ THEN CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
      EXPAND_TAC "ix" THEN
      REWRITE_TAC[IN_ELIM_THM] THEN
      INTRO_TAC "(i_index _) (j_index _) same" THEN
      USE_THEN "injective" MP_TAC THEN
      REWRITE_TAC[INJ; IN_UNIV; IN_CYCLIC_INDICES] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      EXPAND_TAC "ix" THEN
      MATCH_MP_TAC FINITE_SUBSET THEN
      EXISTS_TAC `cyclic_indices n` THEN
      REWRITE_TAC[FINITE_CYCLIC_INDICES; SUBSET; IN_ELIM_THM;
                  IN_CYCLIC_INDICES] THEN SET_TAC[]]]);;

let GRAPH_CONTRACT_EDGE_INCIDENT_SPOKE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v x:A.
        ~(x = v) /\
        {v,x} IN graph_contract_edges V E u v
        ==> {u,x} IN E \/ {v,x} IN E`,
  REPEAT GEN_TAC THEN INTRO_TAC "x_not_v contracted_edge" THEN
  USE_THEN "contracted_edge" MP_TAC THEN
  REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN
  DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "old")
   (X_CHOOSE_THEN `w:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "u_neighbor")
     (CONJUNCTS_THEN2 (LABEL_TAC "w_not_v")
      (LABEL_TAC "edge_value"))))) THENL
   [DISJ2_TAC THEN USE_THEN "old" MP_TAC THEN MESON_TAC[];
    SUBGOAL_THEN `(x:A) = w` SUBST_ALL_TAC THENL
     [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
       ["x_not_v"; "w_not_v"; "edge_value"] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
      DISJ1_TAC THEN
      USE_THEN "u_neighbor" MP_TAC THEN
      REWRITE_TAC[IN_GRAPH_NEIGHBORS]]]);;

(* ------------------------------------------------------------------------- *)
(* Every vertex of a 3-connected graph has at least three neighbours.        *)
(* ------------------------------------------------------------------------- *)

let VERTEX_3_CONNECTED_GRAPH_MINIMUM_DEGREE = prove
 (`!V E x:A.
        vertex_k_connected_graph 3 V E /\ x IN V
        ==> 3 <= CARD(graph_neighbors E x)`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected3 x_vertex" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `3` THEN USE_THEN "connected3" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `3 < CARD(V:A->bool)` (LABEL_TAC "card") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_CARD THEN
    EXISTS_TAC `E:(A->bool)->bool` THEN
    USE_THEN "connected3" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(graph_neighbors (E:(A->bool)->bool) x)`
  (LABEL_TAC "neighbors_finite") THENL
   [MATCH_MP_TAC FINITE_GRAPH_NEIGHBORS THEN
    EXISTS_TAC `V:A->bool` THEN USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_neighbors (E:(A->bool)->bool) x SUBSET V DELETE x`
  (LABEL_TAC "neighbors_subset") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_NEIGHBORS_SUBSET_DELETE THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ARITH_RULE `~(c < 3) ==> 3 <= c`) THEN
  DISCH_THEN(LABEL_TAC "small") THEN
  SUBGOAL_THEN
   `connected_graph
      (V DIFF graph_neighbors (E:(A->bool)->bool) x)
      (induced_subgraph_edges E (V DIFF graph_neighbors E x))`
  (LABEL_TAC "deleted_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`3`; `V:A->bool`; `E:(A->bool)->bool`;
      `graph_neighbors (E:(A->bool)->bool) x`]
     VERTEX_K_CONNECTED_GRAPH_DELETE_LT) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "connected3" ACCEPT_TAC;
      USE_THEN "neighbors_subset" MP_TAC THEN SET_TAC[];
      USE_THEN "small" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph
      (V DIFF graph_neighbors (E:(A->bool)->bool) x)
      (induced_subgraph_edges E (V DIFF graph_neighbors E x))`
  (LABEL_TAC "deleted_graph") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `V DIFF graph_neighbors (E:(A->bool)->bool) x`]
     FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH) THEN
    CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(x:A) IN V DIFF graph_neighbors E x`
  (LABEL_TAC "x_remaining") THENL
   [USE_THEN "neighbors_subset" MP_TAC THEN ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~({x:A} = V DIFF graph_neighbors E x)`
  (LABEL_TAC "remaining_proper") THENL
   [DISCH_THEN(LABEL_TAC "singleton") THEN
    SUBGOAL_THEN
     `(V:A->bool) SUBSET {x} UNION graph_neighbors E x`
    (LABEL_TAC "V_small") THENL
     [USE_THEN "singleton" MP_TAC THEN
      USE_THEN "neighbors_subset" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "V_finite") THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD(V:A->bool) <= CARD({x:A} UNION graph_neighbors E x)`
    (LABEL_TAC "V_card_small") THENL
     [MATCH_MP_TAC CARD_SUBSET THEN CONJ_TAC THENL
       [USE_THEN "V_small" ACCEPT_TAC;
        ASM_SIMP_TAC[FINITE_UNION; FINITE_SING]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `CARD({x:A} UNION graph_neighbors E x) <=
      CARD {x:A} + CARD(graph_neighbors E x)`
    (LABEL_TAC "union_card") THENL
     [MATCH_MP_TAC CARD_UNION_LE THEN ASM_SIMP_TAC[FINITE_SING];
      ALL_TAC] THEN
    USE_THEN "card" MP_TAC THEN
    USE_THEN "small" MP_TAC THEN
    USE_THEN "V_card_small" MP_TAC THEN
    USE_THEN "union_card" MP_TAC THEN
    REWRITE_TAC[CARD_SING] THEN ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V DIFF graph_neighbors (E:(A->bool)->bool) x`;
    `induced_subgraph_edges
      (E:(A->bool)->bool) (V DIFF graph_neighbors E x)`;
    `{x:A}`; `x:A`]
   CONNECTED_GRAPH_CROSSING_EDGE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "deleted_graph" ACCEPT_TAC;
      USE_THEN "deleted_connected" ACCEPT_TAC;
      USE_THEN "x_remaining" MP_TAC THEN SET_TAC[];
      REWRITE_TAC[IN_SING];
      USE_THEN "remaining_proper" ACCEPT_TAC];
    ALL_TAC] THEN
  INTRO_TAC "@y z. y_outside z_singleton yz_edge" THEN
  SUBGOAL_THEN `(z:A) = x` SUBST_ALL_TAC THENL
   [USE_THEN "z_singleton" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  USE_THEN "yz_edge" MP_TAC THEN
  REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
  INTRO_TAC "yx_edge _" THEN
  SUBGOAL_THEN `(y:A) IN graph_neighbors E x`
  (LABEL_TAC "y_neighbor") THENL
   [REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
    ONCE_REWRITE_TAC[PAIR_SET_SYM] THEN
    USE_THEN "yx_edge" ACCEPT_TAC;
    USE_THEN "y_outside" MP_TAC THEN
    USE_THEN "y_neighbor" MP_TAC THEN SET_TAC[]]);;

let VERTEX_3_CONNECTED_GRAPH_NEIGHBOR_AWAY = prove
 (`!V E x y:A.
        vertex_k_connected_graph 3 V E /\ x IN V
        ==> ?z. z IN graph_neighbors E x /\ ~(z = y)`,
  REPEAT GEN_TAC THEN INTRO_TAC "connected3 x_vertex" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `3` THEN USE_THEN "connected3" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `3 <= CARD(graph_neighbors (E:(A->bool)->bool) x)`
  (LABEL_TAC "degree") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `x:A`]
     VERTEX_3_CONNECTED_GRAPH_MINIMUM_DEGREE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
  DISCH_THEN(LABEL_TAC "none") THEN
  SUBGOAL_THEN
   `graph_neighbors (E:(A->bool)->bool) x SUBSET {y}`
  (LABEL_TAC "at_most_one") THENL
   [USE_THEN "none" MP_TAC THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`graph_neighbors (E:(A->bool)->bool) x`; `{y:A}`] CARD_SUBSET) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "at_most_one" ACCEPT_TAC;
      REWRITE_TAC[FINITE_SING]];
    REWRITE_TAC[CARD_SING] THEN ASM_ARITH_TAC]);;

let FINITE_SIMPLE_GRAPH_EDGE_DELETE_PAIR_CASES = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A. !e:A->bool.
        finite_simple_graph V E /\
        u IN V /\ v IN V /\ ~(u = v) /\ e IN E
        ==> e IN induced_subgraph_edges E ((V DELETE u) DELETE v) \/
            e = {u,v} \/
            (?x. x IN (V DELETE u) DELETE v /\ e = {u,x}) \/
            (?x. x IN (V DELETE u) DELETE v /\ e = {v,x})`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph u_vertex v_vertex distinct edge" THEN
  SUBGOAL_THEN `(e:A->bool) SUBSET V /\ e HAS_SIZE 2`
  (CONJUNCTS_THEN2 (LABEL_TAC "edge_subset") (LABEL_TAC "edge_size")) THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "edge_size" MP_TAC THEN
  REWRITE_TAC[HAS_SIZE_CONV `(e:A->bool) HAS_SIZE 2`] THEN
  INTRO_TAC "@x y. xy_distinct e_eq" THEN
  SUBGOAL_THEN `(x:A) IN V /\ (y:A) IN V`
  (CONJUNCTS_THEN2 (LABEL_TAC "x_vertex") (LABEL_TAC "y_vertex")) THENL
   [MAP_EVERY (fun name -> USE_THEN name MP_TAC)
     ["edge_subset"; "e_eq"] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(x:A) = u` THENL
   [ASM_CASES_TAC `(y:A) = v` THENL
     [DISJ2_TAC THEN DISJ1_TAC THEN ASM_REWRITE_TAC[];
      DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
      EXISTS_TAC `y:A` THEN
      ASM_REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[]];
    ASM_CASES_TAC `(x:A) = v` THENL
     [ASM_CASES_TAC `(y:A) = u` THENL
       [DISJ2_TAC THEN DISJ1_TAC THEN
        ASM_REWRITE_TAC[PAIR_SET_SYM];
        DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
        EXISTS_TAC `y:A` THEN
        ASM_REWRITE_TAC[IN_DELETE] THEN ASM_MESON_TAC[]];
      ASM_CASES_TAC `(y:A) = u` THENL
       [DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
        EXISTS_TAC `x:A` THEN
        ASM_REWRITE_TAC[IN_DELETE; PAIR_SET_SYM];
        ASM_CASES_TAC `(y:A) = v` THENL
         [DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
          EXISTS_TAC `x:A` THEN
          ASM_REWRITE_TAC[IN_DELETE; PAIR_SET_SYM];
          DISJ1_TAC THEN
          REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
          CONJ_TAC THENL
           [USE_THEN "e_eq" (fun th -> REWRITE_TAC[GSYM th]) THEN
            USE_THEN "edge" ACCEPT_TAC;
            USE_THEN "e_eq" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[SUBSET; IN_INSERT; IN_SING; IN_DELETE] THEN
      ASM_MESON_TAC[]]]]]]);;

let GRAPH_CONTRACT_EDGE_SPOKE_FORWARD = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v z:A.
        finite_simple_graph V E /\
        u IN V /\ v IN V /\ ~(u = v) /\
        z IN V /\ ~(z = u) /\ ~(z = v) /\
        ({u,z} IN E \/ {v,z} IN E)
        ==> {v,z} IN graph_contract_edges V E u v`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph u_vertex v_vertex uv z_vertex zu zv spoke" THEN
  USE_THEN "spoke" DISJ_CASES_TAC THENL
   [REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN DISJ2_TAC THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[IN_GRAPH_NEIGHBORS];
    REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN DISJ1_TAC THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[INSERT_SUBSET; SING_SUBSET; IN_DELETE] THEN
    ASM_MESON_TAC[]]);;

let GRAPH_CONTRACT_EDGE_SPOKE_BOUNDARY_INDEX = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A. !q:num->A. !n z:A.
        finite_simple_graph V E /\
        u IN V /\ v IN V /\ ~(u = v) /\
        graph_neighbors (graph_contract_edges V E u v) v
          SUBSET cyclic_vertices q n /\
        z IN V /\ ~(z = u) /\ ~(z = v) /\
        ({u,z} IN E \/ {v,z} IN E)
        ==> ?i. i < n /\ q i = z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph u_vertex v_vertex uv boundary_neighbors \
    z_vertex zu zv spoke" THEN
  SUBGOAL_THEN
   `(z:A) IN graph_neighbors (graph_contract_edges V E u v) v`
  (LABEL_TAC "contracted_neighbor") THENL
   [REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
    MATCH_MP_TAC GRAPH_CONTRACT_EDGE_SPOKE_FORWARD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN cyclic_vertices q n`
  (LABEL_TAC "boundary_vertex") THENL
   [USE_THEN "boundary_neighbors"
     (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "contracted_neighbor" ACCEPT_TAC;
    USE_THEN "boundary_vertex" MP_TAC THEN
    REWRITE_TAC[IN_CYCLIC_VERTICES; IN_CYCLIC_INDICES] THEN
    MESON_TAC[]]);;

let CYCLIC_INTERVAL_ROTATE_BOUNDARY = prove
 (`!P Q:num->bool. !n a b.
        0 < a /\ a <= b /\ b < n /\
        (!i. i < n /\ Q i ==> a <= i /\ i <= b) /\
        (!i. a < i /\ i < b ==> ~P i)
        ==> (!i. i < n /\ Q((i + a) MOD n) ==> i <= b - a) /\
            (!i. i < n /\ P((i + a) MOD n)
                 ==> i = 0 \/ b - a <= i)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "a_positive ab b_index Q_interval P_interior" THEN
  SUBGOAL_THEN `(a:num) < n` (LABEL_TAC "a_index") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [X_GEN_TAC `i:num` THEN INTRO_TAC "i_index Qi" THEN
    SUBGOAL_THEN
     `(i + a) MOD n =
      if i + a < n then i + a else (i + a) - n`
    (LABEL_TAC "offset") THENL
     [MATCH_MP_TAC(SPECL
       [`i:num`; `a:num`; `n:num`] MOD_ADD_CASES) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "Q_interval" (MP_TAC o SPEC `(i + a) MOD n`) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [REWRITE_TAC[MOD_LT_EQ_LT] THEN ASM_ARITH_TAC;
        USE_THEN "Qi" ACCEPT_TAC];
      USE_THEN "offset" (fun th -> REWRITE_TAC[th]) THEN
      COND_CASES_TAC THEN ASM_ARITH_TAC];
    X_GEN_TAC `i:num` THEN INTRO_TAC "i_index Pi" THEN
    MATCH_MP_TAC(TAUT `(~p /\ ~q ==> F) ==> p \/ q`) THEN
    INTRO_TAC "i_nonzero i_before" THEN
    SUBGOAL_THEN `(i:num) + a < n` (LABEL_TAC "no_wrap") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "P_interior" (MP_TAC o SPEC `i + a:num`) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC;
      DISCH_THEN(LABEL_TAC "not_P") THEN
      USE_THEN "no_wrap" (fun nwth ->
       USE_THEN "Pi" (fun pth ->
        USE_THEN "not_P" (fun nth ->
         CONTR_TAC
          (MP (NOT_ELIM nth)
           (REWRITE_RULE[MATCH_MP MOD_LT nwth] pth)))))]]);;

let FINITE_SIMPLE_GRAPH_CARD_4_EULER_PLANAR = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E /\ CARD V = 4
        ==> euler_planar_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph card" THEN
  SUBGOAL_THEN `(V:A->bool) HAS_SIZE 4` MP_TAC THENL
   [REWRITE_TAC[HAS_SIZE] THEN CONJ_TAC THENL
     [USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
      USE_THEN "card" ACCEPT_TAC];
    REWRITE_TAC[HAS_SIZE_CONV `(V:A->bool) HAS_SIZE 4`] THEN
    INTRO_TAC
     "@a b c d. cd bc bd ab ac ad V_eq"] THEN
  ABBREV_TAC
   `q:num->A =
      \i. if i = 0 then a else if i = 1 then b else c` THEN
  SUBGOAL_THEN
   `(q:num->A) 0 = a /\ q 1 = b /\ q 2 = c`
  (CONJUNCTS_THEN2 (LABEL_TAC "q0")
   (CONJUNCTS_THEN2 (LABEL_TAC "q1") (LABEL_TAC "q2"))) THENL
   [EXPAND_TAC "q" THEN CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  SUBGOAL_THEN `INJ (q:num->A) (cyclic_indices 3) (:A)`
  (LABEL_TAC "injective") THENL
   [MATCH_MP_TAC INJ_CYCLIC_INDICES_3 THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `simple_graph_cycle (cyclic_edges (q:num->A) 3) q 3`
  (LABEL_TAC "cycle") THENL
   [REWRITE_TAC[simple_graph_cycle; SUBSET_REFL] THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `boundary_euler_rotation
      (cyclic_vertices (q:num->A) 3)
      (cyclic_edges q 3) q 3
      (triangle_rotation (q 0) (q 1) (q 2))`
  (LABEL_TAC "boundary") THENL
   [MATCH_MP_TAC BOUNDARY_EULER_TRIANGLE_ROTATION THEN
    USE_THEN "injective" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph
      (cyclic_vertices (q:num->A) 3) (cyclic_edges q 3)`
  (LABEL_TAC "connected") THENL
   [MATCH_MP_TAC CYCLIC_GRAPH_CONNECTED THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((d:A) IN cyclic_vertices q 3)`
  (LABEL_TAC "d_fresh") THENL
   [REWRITE_TAC[CYCLIC_VERTICES_3] THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY (fun name -> USE_THEN name MP_TAC) ["ad"; "bd"; "cd"] THEN
    POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`cyclic_vertices (q:num->A) 3`;
    `cyclic_edges (q:num->A) 3`;
    `triangle_rotation (q 0) (q 1) (q 2):(A#A)->A#A`;
    `q:num->A`; `3`; `d:A`]
   BOUNDARY_EULER_ROTATION_FULL_FAN) THEN
  ASM_REWRITE_TAC[SUBSET_REFL] THEN
  DISCH_THEN(LABEL_TAC "tetrahedron") THEN
  ABBREV_TAC
   `superedges:(A->bool)->bool =
      IMAGE (\x:A. {d,x}) (cyclic_vertices q 3) UNION
      cyclic_edges q 3` THEN
  SUBGOAL_THEN
   `d INSERT cyclic_vertices (q:num->A) 3 = V`
  (LABEL_TAC "vertices") THENL
   [REWRITE_TAC[CYCLIC_VERTICES_3] THEN
    ASM_REWRITE_TAC[] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `E SUBSET complete_graph_edges (V:A->bool)`
  (LABEL_TAC "complete") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[FINITE_SIMPLE_GRAPH_EQ] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `complete_graph_edges (V:A->bool) SUBSET superedges`
  (LABEL_TAC "complete_subset") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC
     `{{a:A,b},{a,c},{a,d},{b,c},{b,d},{c,d}}` THEN
    CONJ_TAC THENL
     [USE_THEN "V_eq" SUBST1_TAC THEN
      MATCH_ACCEPT_TAC(SPECL [`a:A`; `b:A`; `c:A`; `d:A`]
       COMPLETE_GRAPH_EDGES_FOUR_SUBSET);
      EXPAND_TAC "superedges" THEN
      REWRITE_TAC[CYCLIC_VERTICES_3; CYCLIC_EDGES_3;
                  IMAGE_CLAUSES] THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `{a:A,c} = {c,a}`
      (LABEL_TAC "ac_pair") THENL
       [MATCH_ACCEPT_TAC(SPECL [`a:A`; `c:A`] PAIR_SET_SYM);
        ALL_TAC] THEN
      SUBGOAL_THEN `{a:A,d} = {d,a}`
      (LABEL_TAC "ad_pair") THENL
       [MATCH_ACCEPT_TAC(SPECL [`a:A`; `d:A`] PAIR_SET_SYM);
        ALL_TAC] THEN
      SUBGOAL_THEN `{b:A,d} = {d,b}`
      (LABEL_TAC "bd_pair") THENL
       [MATCH_ACCEPT_TAC(SPECL [`b:A`; `d:A`] PAIR_SET_SYM);
        ALL_TAC] THEN
      SUBGOAL_THEN `{c:A,d} = {d,c}`
      (LABEL_TAC "cd_pair") THENL
       [MATCH_ACCEPT_TAC(SPECL [`c:A`; `d:A`] PAIR_SET_SYM);
        ALL_TAC] THEN
      ASM_REWRITE_TAC[SUBSET; IN_UNION; IN_INSERT; IN_SING] THEN
      POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `superedges:(A->bool)->bool`; `E:(A->bool)->bool`]
  EULER_PLANAR_GRAPH_SUBSET_EDGES) THEN
  CONJ_TAC THENL
   [USE_THEN "tetrahedron" (fun eth ->
      USE_THEN "vertices" (fun vth ->
       USE_THEN "V_eq" (fun vset_th ->
        ACCEPT_TAC(REWRITE_RULE[vth; vset_th] eth))));
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `complete_graph_edges (V:A->bool)` THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Lifting Euler planarity through a contractible edge.                      *)
(* ------------------------------------------------------------------------- *)

let BOUNDARY_EULER_ROTATION_OFFSET_SPOKE_INTERVAL = prove
 (`!W:A->bool. !B E:(A->bool)->bool. !r:(A#A)->A#A.
   !q:num->A. !n. !u v:A. !k a b.
        simple_graph_cycle B q n /\
        boundary_euler_rotation W B q n r /\
        connected_graph W B /\
        cyclic_vertices q n SUBSET W /\
        ~(u IN W) /\ ~(v IN W) /\ ~(u = v) /\
        0 < a /\ a <= b /\ b < n /\
        (!i. i < n /\ {v,q((i + k) MOD n)} IN E
             ==> a <= i /\ i <= b) /\
        (!i. a < i /\ i < b
             ==> ~({u,q((i + k) MOD n)} IN E)) /\
        (!e:A->bool. e IN E
             ==> e IN B \/ e = {u,v} \/
                 (?i. i < n /\ e = {u,q i}) \/
                 (?i. i < n /\ e = {v,q i}))
        ==> euler_planar_graph (u INSERT v INSERT W) E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "cycle boundary connected vertices u_outside v_outside uv \
    a_positive ab b_index v_interval u_interior edge_cases" THEN
  MP_TAC(ISPECL
   [`\i:num. {u:A,q((i + k) MOD n)} IN E`;
    `\i:num. {v:A,q((i + k) MOD n)} IN E`;
    `n:num`; `a:num`; `b:num`]
   CYCLIC_INTERVAL_ROTATE_BOUNDARY) THEN
  ASM_REWRITE_TAC[] THEN BETA_TAC THEN
  INTRO_TAC "v_limit u_limit" THEN
  ABBREV_TAC
   `q':num->A = \i. q((((i + a) MOD n + k) MOD n))` THEN
  FIRST_X_ASSUM(LABEL_TAC "q'_def") THEN
  SUBGOAL_THEN `simple_graph_cycle B (q':num->A) n`
  (LABEL_TAC "shifted_cycle") THENL
   [EXPAND_TAC "q'" THEN
    USE_THEN "cycle" (fun cth ->
     ACCEPT_TAC(BETA_RULE
      (MATCH_MP
       (ISPECL
        [`B:(A->bool)->bool`;
         `\i:num. (q:num->A)((i + k) MOD n)`;
         `n:num`; `a:num`]
        SIMPLE_GRAPH_CYCLE_OFFSET)
       (MATCH_MP
        (ISPECL
         [`B:(A->bool)->bool`; `q:num->A`;
          `n:num`; `k:num`]
         SIMPLE_GRAPH_CYCLE_OFFSET) cth))));
    ALL_TAC] THEN
  SUBGOAL_THEN `boundary_euler_rotation W B (q':num->A) n r`
  (LABEL_TAC "shifted_boundary") THENL
   [EXPAND_TAC "q'" THEN
    USE_THEN "cycle" (fun cth ->
     USE_THEN "boundary" (fun bth ->
      let qk = `\i:num. (q:num->A)((i + k) MOD n)` in
      let ck = MATCH_MP
       (ISPECL
        [`B:(A->bool)->bool`; `q:num->A`; `n:num`; `k:num`]
        SIMPLE_GRAPH_CYCLE_OFFSET) cth in
      let bk = MATCH_MP
       (ISPECL
        [`W:A->bool`; `B:(A->bool)->bool`; `q:num->A`;
         `n:num`; `r:(A#A)->A#A`; `k:num`]
        BOUNDARY_EULER_ROTATION_OFFSET) (CONJ bth cth) in
      ACCEPT_TAC(BETA_RULE(MATCH_MP
       (ISPECL
        [`W:A->bool`; `B:(A->bool)->bool`; qk;
         `n:num`; `r:(A#A)->A#A`; `a:num`]
        BOUNDARY_EULER_ROTATION_OFFSET) (CONJ bk ck)))));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `cyclic_vertices (q':num->A) n = cyclic_vertices q n`
  (LABEL_TAC "shifted_vertices_eq") THENL
   [EXPAND_TAC "q'" THEN
    MATCH_ACCEPT_TAC(TRANS
     (BETA_RULE(SPECL
       [`\i:num. (q:num->A)((i + k) MOD n)`;
        `n:num`; `a:num`] CYCLIC_VERTICES_OFFSET))
     (SPECL [`q:num->A`; `n:num`; `k:num`]
      CYCLIC_VERTICES_OFFSET));
    ALL_TAC] THEN
  SUBGOAL_THEN `cyclic_vertices (q':num->A) n SUBSET W`
  (LABEL_TAC "shifted_vertices") THENL
   [USE_THEN "shifted_vertices_eq" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "vertices" ACCEPT_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`W:A->bool`; `B:(A->bool)->bool`; `E:(A->bool)->bool`;
    `r:(A#A)->A#A`; `q':num->A`; `n:num`;
    `u:A`; `v:A`; `b - a:num`]
   BOUNDARY_EULER_ROTATION_SPOKE_INTERVAL) THEN
  CONJ_TAC THENL
   [USE_THEN "shifted_cycle" ACCEPT_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "shifted_boundary" ACCEPT_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "connected" ACCEPT_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "shifted_vertices" ACCEPT_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "u_outside" ACCEPT_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "v_outside" ACCEPT_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "uv" ACCEPT_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    SUBGOAL_THEN
     `e IN B \/ e = {u:A,v} \/
      (?i:num. i < n /\ e = {u,q i}) \/
      (?i:num. i < n /\ e = {v,q i})`
    (LABEL_TAC "raw_case") THENL
     [USE_THEN "edge_cases" (MATCH_MP_TAC o SPEC `e:A->bool`) THEN
      USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "raw_case"
     (DISJ_CASES_THEN2 (LABEL_TAC "base_edge")
     (DISJ_CASES_THEN2 (LABEL_TAC "edge_uv")
      (DISJ_CASES_THEN2
       (X_CHOOSE_THEN `j:num`
        (CONJUNCTS_THEN2 (LABEL_TAC "j_index")
         (LABEL_TAC "edge_value")))
       (X_CHOOSE_THEN `j:num`
        (CONJUNCTS_THEN2 (LABEL_TAC "j_index")
         (LABEL_TAC "edge_value")))))) THENL
     [DISJ1_TAC THEN USE_THEN "base_edge" ACCEPT_TAC;
      DISJ2_TAC THEN DISJ1_TAC THEN USE_THEN "edge_uv" ACCEPT_TAC;
      SUBGOAL_THEN `(q:num->A) j IN cyclic_vertices q' n`
      (LABEL_TAC "shifted_vertex") THENL
       [USE_THEN "shifted_vertices_eq" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
        EXISTS_TAC `j:num` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "shifted_vertex" MP_TAC THEN
      REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      INTRO_TAC "@i. i_index vertex_value" THEN
      SUBGOAL_THEN `{u:A,(q':num->A) i} IN E`
      (LABEL_TAC "shifted_spoke") THENL
       [ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(i:num) < n /\
        {u:A,(q:num->A)(((i + a) MOD n + k) MOD n)} IN E`
      (LABEL_TAC "limit_premise") THENL
       [CONJ_TAC THENL
         [USE_THEN "i_index" ACCEPT_TAC;
          ASM_MESON_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(i:num) = 0 \/ (b:num) - a <= i`
      (LABEL_TAC "position") THENL
       [(fun ((asl,w) as g) ->
          let lth = assoc "u_limit" asl
          and pth = assoc "limit_premise" asl in
          ACCEPT_TAC(MP (SPEC `i:num` lth) pth) g);
        ALL_TAC] THEN
      DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
      EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN `(q:num->A) j IN cyclic_vertices q' n`
      (LABEL_TAC "shifted_vertex") THENL
       [USE_THEN "shifted_vertices_eq" (fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
        EXISTS_TAC `j:num` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "shifted_vertex" MP_TAC THEN
      REWRITE_TAC[IN_CYCLIC_VERTICES] THEN
      INTRO_TAC "@i. i_index vertex_value" THEN
      SUBGOAL_THEN `{v:A,(q':num->A) i} IN E`
      (LABEL_TAC "shifted_spoke") THENL
       [ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(i:num) < n /\
        {v:A,(q:num->A)(((i + a) MOD n + k) MOD n)} IN E`
      (LABEL_TAC "limit_premise") THENL
       [CONJ_TAC THENL
         [USE_THEN "i_index" ACCEPT_TAC;
          ASM_MESON_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN `(i:num) <= (b:num) - a`
      (LABEL_TAC "position") THENL
       [(fun ((asl,w) as g) ->
          let lth = assoc "v_limit" asl
          and pth = assoc "limit_premise" asl in
          ACCEPT_TAC(MP (SPEC `i:num` lth) pth) g);
        ALL_TAC] THEN
      DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
      EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[]]);;

let CONNECTED_EULER_PLANAR_GRAPH_ROTATION = prove
 (`!V:A->bool. !E:(A->bool)->bool. !x:A.
        euler_planar_graph V E /\ connected_graph V E /\ x IN V
        ==> ?r:(A#A)->A#A. euler_planar_rotation V E r`,
  REPEAT GEN_TAC THEN INTRO_TAC "planar connected vertex" THEN
  MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `x:A`]
   CONNECTED_GRAPH_COMPONENT_EDGES) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC EULER_PLANAR_GRAPH_FINITE_SIMPLE THEN
      USE_THEN "planar" ACCEPT_TAC;
      ASM_REWRITE_TAC[]];
    INTRO_TAC "component component_edges"] THEN
  USE_THEN "planar" MP_TAC THEN
  REWRITE_TAC[euler_planar_graph] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `x:A`)) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@r. rotation" THEN
  EXISTS_TAC `r:(A#A)->A#A` THEN ASM_REWRITE_TAC[]);;

let VERTEX_3_CONNECTED_GRAPH_CONTRACT_EULER_PLANAR = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
        vertex_k_connected_graph 3 V E /\
        {u,v} IN E /\
        vertex_k_connected_graph 3
          (V DELETE u) (graph_contract_edges V E u v) /\
        ~graph_kuratowski_obstruction V E /\
        euler_planar_graph
          (V DELETE u) (graph_contract_edges V E u v)
        ==> euler_planar_graph V E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "connected3 edge contracted_connected3 unobstructed contracted_planar" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `3` THEN USE_THEN "connected3" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(u:A) IN V /\ (v:A) IN V /\ ~(u = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
    (LABEL_TAC "distinct"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v:A) IN V DELETE u`
  (LABEL_TAC "contracted_vertex") THENL
   [REWRITE_TAC[IN_DELETE] THEN CONJ_TAC THENL
     [USE_THEN "v_vertex" ACCEPT_TAC;
      DISCH_THEN(LABEL_TAC "same") THEN
      USE_THEN "same" (fun sth ->
       USE_THEN "distinct" (fun dth ->
        CONTR_TAC(MP (NOT_ELIM dth) (SYM sth))))];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph
      ((V:A->bool) DELETE u)
      (graph_contract_edges (V:A->bool) (E:(A->bool)->bool) u v)`
  (LABEL_TAC "contracted_connected") THENL
   [USE_THEN "contracted_connected3" (fun cth ->
     ACCEPT_TAC(MATCH_MP
      (ISPECL
       [`3`; `(V:A->bool) DELETE u`;
        `graph_contract_edges (V:A->bool) E u v`]
       VERTEX_K_CONNECTED_GRAPH_CONNECTED)
      (CONJ cth (ARITH_RULE `(0:num) < 3`))));
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(V:A->bool) DELETE u`;
    `graph_contract_edges (V:A->bool) E u v`; `v:A`]
