      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
        `q:num->A`; `n:num`; `z:A`]
       GRAPH_CONTRACT_EDGE_SPOKE_BOUNDARY_INDEX) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "z_deleted" MP_TAC THEN SET_TAC[];
          USE_THEN "z_deleted" MP_TAC THEN SET_TAC[];
          USE_THEN "z_deleted" MP_TAC THEN SET_TAC[];
          DISJ2_TAC THEN ASM_MESON_TAC[]];
        INTRO_TAC "@i. i_index qi"] THEN
      DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
      EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `u INSERT v INSERT ((V DELETE u) DELETE v) = (V:A->bool) /\
    v INSERT u INSERT ((V DELETE u) DELETE v) = V`
  (CONJUNCTS_THEN2 (LABEL_TAC "vertices_reassembled")
   (LABEL_TAC "vertices_reassembled_swapped")) THENL
   [ASM SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `q:num->A`; `n:num`;
    `u:A`; `v:A`]
   GRAPH_KURATOWSKI_FREE_SPARSE_SPOKE_INTERVAL) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (X_CHOOSE_THEN `k:num`
    (X_CHOOSE_THEN `a:num`
     (X_CHOOSE_THEN `b:num` MP_TAC)))
   (X_CHOOSE_THEN `k:num`
    (X_CHOOSE_THEN `a:num`
     (X_CHOOSE_THEN `b:num` MP_TAC)))) THENL
   [INTRO_TAC
     "k_index uk not_vk a_positive ab b_index \
      v_interval u_interior" THEN
    USE_THEN "vertices_reassembled" (SUBST1_TAC o GSYM) THEN
    MATCH_MP_TAC(ISPECL
     [`((V:A->bool) DELETE u) DELETE v`;
      `induced_subgraph_edges (E:(A->bool)->bool)
        (((V:A->bool) DELETE u) DELETE v)`;
      `E:(A->bool)->bool`; `s:(A#A)->A#A`; `q:num->A`; `n:num`;
      `u:A`; `v:A`; `k:num`; `a:num`; `b:num`]
     BOUNDARY_EULER_ROTATION_OFFSET_SPOKE_INTERVAL) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[IN_DELETE];
    INTRO_TAC
     "k_index vk not_uk a_positive ab b_index \
      u_interval v_interior" THEN
    USE_THEN "vertices_reassembled_swapped"
     (SUBST1_TAC o GSYM) THEN
    MATCH_MP_TAC(ISPECL
     [`((V:A->bool) DELETE u) DELETE v`;
      `induced_subgraph_edges (E:(A->bool)->bool)
        (((V:A->bool) DELETE u) DELETE v)`;
      `E:(A->bool)->bool`; `s:(A#A)->A#A`; `q:num->A`; `n:num`;
      `v:A`; `u:A`; `k:num`; `a:num`; `b:num`]
     BOUNDARY_EULER_ROTATION_OFFSET_SPOKE_INTERVAL) THEN
    ASM_REWRITE_TAC[PAIR_SET_SYM] THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[IN_DELETE];
      REWRITE_TAC[IN_DELETE];
      X_GEN_TAC `e:A->bool` THEN
      DISCH_THEN(LABEL_TAC "ambient_edge") THEN
      USE_THEN "edge_cases" (fun th ->
       USE_THEN "ambient_edge" (fun eth ->
        let cth = REWRITE_RULE[PAIR_SET_SYM]
          (MP (SPEC `e:A->bool` th) eth) in
        MP_TAC cth THEN
        DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "base_edge")
         (DISJ_CASES_THEN2 (LABEL_TAC "edge_uv")
          (DISJ_CASES_THEN2 (LABEL_TAC "u_spoke")
           (LABEL_TAC "v_spoke")))) THENL
         [DISJ1_TAC THEN USE_THEN "base_edge" ACCEPT_TAC;
          DISJ2_TAC THEN DISJ1_TAC THEN USE_THEN "edge_uv" ACCEPT_TAC;
          DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
          USE_THEN "u_spoke" ACCEPT_TAC;
          DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
          USE_THEN "v_spoke" ACCEPT_TAC]))]]);;

(* ------------------------------------------------------------------------- *)
(* Kuratowski's theorem for finite simple 3-connected graphs.                *)
(* ------------------------------------------------------------------------- *)

let VERTEX_3_CONNECTED_KURATOWSKI_FREE_EULER_PLANAR = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        vertex_k_connected_graph 3 V E /\
        ~graph_kuratowski_obstruction V E
        ==> euler_planar_graph V E`,
  GEN_TAC THEN WF_INDUCT_TAC `CARD(V:A->bool)` THEN
  POP_ASSUM(LABEL_TAC "induction") THEN
  X_GEN_TAC `E:(A->bool)->bool` THEN
  INTRO_TAC "connected3 unobstructed" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `3` THEN USE_THEN "connected3" ACCEPT_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `5 <= CARD(V:A->bool)` THENL
   [FIRST_X_ASSUM(LABEL_TAC "large") THEN
    MP_TAC(MATCH_MP
     (ISPECL [`V:A->bool`; `E:(A->bool)->bool`]
      VERTEX_3_CONNECTED_GRAPH_CONTRACTIBLE_EDGE)
     (CONJ
      (ASSUME `vertex_k_connected_graph 3 (V:A->bool) E`)
      (ASSUME `5 <= CARD(V:A->bool)`))) THEN
    INTRO_TAC "@u v. edge contracted_connected3" THEN
    SUBGOAL_THEN
     `(u:A) IN V /\ (v:A) IN V /\ ~(u = v)`
    (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
     (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
      (LABEL_TAC "distinct"))) THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS];
      ALL_TAC] THEN
    SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite") THENL
     [USE_THEN "graph"
       (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[finite_simple_graph]);
      ALL_TAC] THEN
    SUBGOAL_THEN `CARD((V:A->bool) DELETE u) < CARD V`
    (LABEL_TAC "smaller") THENL
     [USE_THEN "finite" (fun fth ->
       USE_THEN "u_vertex" (fun uth ->
        let lth = ASSUME `5 <= CARD(V:A->bool)` in
        let dth = REWRITE_RULE[uth]
          (MP (SPECL [`u:A`; `V:A->bool`] CARD_DELETE) fth) in
        MATCH_ACCEPT_TAC(MATCH_MP
         (ARITH_RULE
           `(5:num) <= n /\ m = n - 1 ==> m < n`)
         (CONJ lth dth))));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~graph_kuratowski_obstruction
       ((V:A->bool) DELETE u)
       (graph_contract_edges (V:A->bool) (E:(A->bool)->bool) u v)`
    (LABEL_TAC "contracted_unobstructed") THENL
     [DISCH_THEN(LABEL_TAC "contracted_obstruction") THEN
      USE_THEN "unobstructed" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "graph" (fun gth ->
       USE_THEN "edge" (fun eth ->
        USE_THEN "contracted_obstruction" (fun oth ->
         MATCH_ACCEPT_TAC(MATCH_MP
          (ISPECL
           [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
           GRAPH_KURATOWSKI_OBSTRUCTION_CONTRACT_IMP)
          (CONJ gth (CONJ eth oth))))));
      ALL_TAC] THEN
    SUBGOAL_THEN
     `euler_planar_graph
       ((V:A->bool) DELETE u)
       (graph_contract_edges (V:A->bool) (E:(A->bool)->bool) u v)`
    (LABEL_TAC "contracted_planar") THENL
     [USE_THEN "induction"
       (MP_TAC o SPEC `((V:A->bool) DELETE u)`) THEN
      ANTS_TAC THENL
       [USE_THEN "smaller" ACCEPT_TAC;
        DISCH_THEN(fun ith ->
         MATCH_ACCEPT_TAC(MATCH_MP
          (SPEC
           `graph_contract_edges
             (V:A->bool) (E:(A->bool)->bool) u v`
           ith)
          (CONJ
           (ASSUME
             `vertex_k_connected_graph 3
               ((V:A->bool) DELETE u)
               (graph_contract_edges V E u v)`)
           (ASSUME
             `~graph_kuratowski_obstruction
               ((V:A->bool) DELETE u)
               (graph_contract_edges V E u v)`))))];
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     VERTEX_3_CONNECTED_GRAPH_CONTRACT_EULER_PLANAR) THEN
    ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "small") THEN
    SUBGOAL_THEN `CARD(V:A->bool) = 4` (LABEL_TAC "card_four") THENL
     [USE_THEN "connected3" (fun cth ->
       let lower = MATCH_MP
        (ISPECL [`3`; `V:A->bool`; `E:(A->bool)->bool`]
         VERTEX_K_CONNECTED_GRAPH_CARD) cth in
       let sth = ASSUME `~(5 <= CARD(V:A->bool))` in
       MATCH_ACCEPT_TAC(MATCH_MP
        (ARITH_RULE `(3:num) < n /\ ~(5 <= n) ==> n = 4`)
        (CONJ lower sth)));
      ALL_TAC] THEN
    USE_THEN "graph" (fun gth ->
     USE_THEN "card_four" (fun cth ->
      MATCH_ACCEPT_TAC(MATCH_MP
       (ISPECL [`V:A->bool`; `E:(A->bool)->bool`]
        FINITE_SIMPLE_GRAPH_CARD_4_EULER_PLANAR)
       (CONJ gth cth))))]);;

(* ------------------------------------------------------------------------- *)
(* Edge-maximal Kuratowski-obstruction-free supergraphs.                     *)
(* ------------------------------------------------------------------------- *)

let INDUCED_SUBGRAPH_EDGES_MONO = prove
 (`!E G:(A->bool)->bool. !P:A->bool.
        E SUBSET G
        ==> induced_subgraph_edges E P SUBSET
            induced_subgraph_edges G P`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[]);;

let GRAPH_KURATOWSKI_OBSTRUCTION_MONO = prove
 (`!V W:A->bool. !E G:(A->bool)->bool.
        V SUBSET W /\
        E SUBSET G /\
        graph_kuratowski_obstruction V E
        ==> graph_kuratowski_obstruction W G`,
  REPEAT GEN_TAC THEN INTRO_TAC "vertices edges obstruction" THEN
  USE_THEN "obstruction" MP_TAC THEN
  REWRITE_TAC[graph_kuratowski_obstruction] THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (X_CHOOSE_THEN `X:A->bool`
    (X_CHOOSE_THEN `P:A->bool`
     (X_CHOOSE_THEN `f:(A->bool)->bool`
      (LABEL_TAC "witness"))))
   (X_CHOOSE_THEN `X:A->bool`
    (X_CHOOSE_THEN `Y:A->bool`
     (X_CHOOSE_THEN `P:A->bool`
      (X_CHOOSE_THEN `f:(A->bool)->bool`
       (LABEL_TAC "witness")))))) THEN
  REWRITE_TAC[graph_kuratowski_obstruction] THENL
   [DISJ1_TAC THEN
    MAP_EVERY EXISTS_TAC
     [`X:A->bool`; `P:A->bool`; `f:(A->bool)->bool`] THEN
    USE_THEN "witness" MP_TAC THEN
    INTRO_TAC "size subdivision target subdivision_edges" THEN
    ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `induced_subgraph_edges (E:(A->bool)->bool) P` THEN
      CONJ_TAC THENL
       [USE_THEN "subdivision_edges" ACCEPT_TAC;
        MATCH_MP_TAC INDUCED_SUBGRAPH_EDGES_MONO THEN
        USE_THEN "edges" ACCEPT_TAC]];
    DISJ2_TAC THEN
    MAP_EVERY EXISTS_TAC
     [`X:A->bool`; `Y:A->bool`; `P:A->bool`;
      `f:(A->bool)->bool`] THEN
    USE_THEN "witness" MP_TAC THEN
    INTRO_TAC
     "X_size Y_size disjoint subdivision target subdivision_edges" THEN
    ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `induced_subgraph_edges (E:(A->bool)->bool) P` THEN
      CONJ_TAC THENL
       [USE_THEN "subdivision_edges" ACCEPT_TAC;
        MATCH_MP_TAC INDUCED_SUBGRAPH_EDGES_MONO THEN
        USE_THEN "edges" ACCEPT_TAC]]]);;

let GRAPH_KURATOWSKI_OBSTRUCTION_CARD_AT_LEAST_5 = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        FINITE V /\
        graph_kuratowski_obstruction V E
        ==> 5 <= CARD V`,
  REPEAT GEN_TAC THEN INTRO_TAC "finite obstruction" THEN
  USE_THEN "obstruction" MP_TAC THEN
  REWRITE_TAC[graph_kuratowski_obstruction] THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (X_CHOOSE_THEN `W:A->bool`
    (X_CHOOSE_THEN `P:A->bool`
     (X_CHOOSE_THEN `f:(A->bool)->bool`
      (LABEL_TAC "witness"))))
   (X_CHOOSE_THEN `X:A->bool`
    (X_CHOOSE_THEN `Y:A->bool`
     (X_CHOOSE_THEN `P:A->bool`
      (X_CHOOSE_THEN `f:(A->bool)->bool`
       (LABEL_TAC "witness")))))) THENL
   [USE_THEN "witness" MP_TAC THEN
    INTRO_TAC "size subdivision target subdivision_edges" THEN
    SUBGOAL_THEN `(W:A->bool) SUBSET V` (LABEL_TAC "source_subset") THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `P:A->bool` THEN
      CONJ_TAC THENL
       [USE_THEN "subdivision" (fun sth ->
         MATCH_ACCEPT_TAC(MATCH_MP
          (ISPECL
           [`W:A->bool`; `complete_graph_edges (W:A->bool)`;
            `P:A->bool`; `f:(A->bool)->bool`]
           GRAPH_SUBDIVISION_SOURCE_SUBSET)
          sth));
        USE_THEN "target" ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(MATCH_MP CARD_SUBSET
     (CONJ
      (ASSUME `(W:A->bool) SUBSET V`)
      (ASSUME `FINITE(V:A->bool)`))) THEN
    USE_THEN "size" MP_TAC THEN
    REWRITE_TAC[HAS_SIZE] THEN ARITH_TAC;
    USE_THEN "witness" MP_TAC THEN
    INTRO_TAC
     "X_size Y_size disjoint subdivision target subdivision_edges" THEN
    SUBGOAL_THEN `(X UNION Y:A->bool) HAS_SIZE 6`
    (LABEL_TAC "source_size") THENL
     [USE_THEN "X_size" (fun xth ->
       USE_THEN "Y_size" (fun yth ->
        USE_THEN "disjoint" (fun dth ->
         MATCH_ACCEPT_TAC(CONV_RULE NUM_REDUCE_CONV
          (MATCH_MP
           (ISPECL [`X:A->bool`; `Y:A->bool`; `3`; `3`]
            HAS_SIZE_UNION)
           (CONJ xth (CONJ yth dth)))))));
      ALL_TAC] THEN
    SUBGOAL_THEN `(X UNION Y:A->bool) SUBSET V`
    (LABEL_TAC "source_subset") THENL
     [MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC `P:A->bool` THEN
      CONJ_TAC THENL
       [USE_THEN "subdivision" (fun sth ->
         MATCH_ACCEPT_TAC(MATCH_MP
          (ISPECL
           [`X UNION Y:A->bool`;
            `complete_bipartite_edges (X:A->bool) Y`;
            `P:A->bool`; `f:(A->bool)->bool`]
           GRAPH_SUBDIVISION_SOURCE_SUBSET)
          sth));
        USE_THEN "target" ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(MATCH_MP CARD_SUBSET
     (CONJ
      (ASSUME `(X UNION Y:A->bool) SUBSET V`)
      (ASSUME `FINITE(V:A->bool)`))) THEN
    USE_THEN "source_size" MP_TAC THEN
    REWRITE_TAC[HAS_SIZE] THEN ARITH_TAC]);;

let MAXIMAL_KURATOWSKI_FREE_GRAPH_EXTENSION = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        finite_simple_graph V E /\
        ~graph_kuratowski_obstruction V E
        ==> ?G:(A->bool)->bool.
              E SUBSET G /\
              finite_simple_graph V G /\
              ~graph_kuratowski_obstruction V G /\
              (!H:(A->bool)->bool.
                   G PSUBSET H /\
                   H SUBSET complete_graph_edges V
                   ==> graph_kuratowski_obstruction V H)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph unobstructed" THEN
  ABBREV_TAC
   `candidates:((A->bool)->bool)->bool =
      {G:(A->bool)->bool |
         E SUBSET G /\
         G SUBSET complete_graph_edges V /\
         ~graph_kuratowski_obstruction V G}` THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite_vertices") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[FINITE_SIMPLE_GRAPH_EQ] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `E SUBSET complete_graph_edges (V:A->bool)`
  (LABEL_TAC "edges") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[FINITE_SIMPLE_GRAPH_EQ] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(candidates:((A->bool)->bool)->bool)`
  (LABEL_TAC "finite_candidates") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC
     `{G:(A->bool)->bool | G SUBSET complete_graph_edges V}` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC FINITE_POWERSET THEN
      MATCH_MP_TAC FINITE_COMPLETE_GRAPH_EDGES THEN
      USE_THEN "finite_vertices" ACCEPT_TAC;
      EXPAND_TAC "candidates" THEN
      REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(candidates:((A->bool)->bool)->bool = {})`
  (LABEL_TAC "candidates_nonempty") THENL
   [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    EXISTS_TAC `E:(A->bool)->bool` THEN
    EXPAND_TAC "candidates" THEN
    REWRITE_TAC[IN_ELIM_THM; SUBSET_REFL] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPEC
   `candidates:((A->bool)->bool)->bool`
   FINITE_MAXIMAL_ELEMENT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `G:(A->bool)->bool`
     (CONJUNCTS_THEN2
      (LABEL_TAC "candidate") (LABEL_TAC "maximal")))] THEN
  USE_THEN "candidate" MP_TAC THEN
  EXPAND_TAC "candidates" THEN
  REWRITE_TAC[IN_ELIM_THM] THEN
  INTRO_TAC "contains within unobstructed_supergraph" THEN
  EXISTS_TAC `G:(A->bool)->bool` THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "contains" ACCEPT_TAC;
    REWRITE_TAC[FINITE_SIMPLE_GRAPH_EQ] THEN
    ASM_REWRITE_TAC[];
    USE_THEN "unobstructed_supergraph" ACCEPT_TAC;
    X_GEN_TAC `H:(A->bool)->bool` THEN
    INTRO_TAC "proper allowed" THEN
    ASM_CASES_TAC `graph_kuratowski_obstruction
      (V:A->bool) (H:(A->bool)->bool)` THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(LABEL_TAC "H_unobstructed") THEN
    USE_THEN "maximal" (MP_TAC o SPEC `H:(A->bool)->bool`) THEN
    ANTS_TAC THENL
     [EXPAND_TAC "candidates" THEN
      REWRITE_TAC[IN_ELIM_THM] THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC SUBSET_TRANS THEN
        EXISTS_TAC `G:(A->bool)->bool` THEN
        CONJ_TAC THENL
         [USE_THEN "contains" ACCEPT_TAC;
          USE_THEN "proper" MP_TAC THEN
          REWRITE_TAC[PSUBSET] THEN MESON_TAC[]];
        USE_THEN "allowed" ACCEPT_TAC;
        USE_THEN "H_unobstructed" ACCEPT_TAC];
      USE_THEN "proper" MP_TAC THEN
      REWRITE_TAC[PSUBSET] THEN MESON_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* Simple indexed paths and replacement of a temporary separator edge.       *)
(* ------------------------------------------------------------------------- *)

(* ------------------------------------------------------------------------- *)
(* Every finite relational walk contains an injective path with the same     *)
(* endpoints.  No finiteness assumption on the ambient type is needed.       *)
(* ------------------------------------------------------------------------- *)

let RELPOW_IMP_SIMPLE_INDEXED_PATH = prove
 (`!R:A->A->bool. !n x y.
        RELPOW n R x y
        ==> ?l q:num->A.
              l <= n /\
              q 0 = x /\
              q l = y /\
              INJ q (0..l) (:A) /\
              (!i. i < l ==> R (q i) (q(i + 1)))`,
  GEN_TAC THEN INDUCT_TAC THENL
   [REPEAT GEN_TAC THEN REWRITE_TAC[RELPOW] THEN
    DISCH_THEN(LABEL_TAC "same") THEN
    MAP_EVERY EXISTS_TAC [`0`; `\i:num. x:A`] THEN
    REPEAT CONJ_TAC THENL
     [ARITH_TAC;
      BETA_TAC THEN REFL_TAC;
      BETA_TAC THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[INJ; IN_UNIV; IN_NUMSEG] THEN ARITH_TAC;
      ARITH_TAC];
    POP_ASSUM(LABEL_TAC "induction") THEN
    REPEAT GEN_TAC THEN
    REWRITE_TAC[RELPOW] THEN
    INTRO_TAC "@z. prefix last_step" THEN
    USE_THEN "induction" (fun ith ->
     USE_THEN "prefix" (fun pth ->
      MP_TAC(MATCH_MP (SPECL [`x:A`; `z:A`] ith) pth))) THEN
    INTRO_TAC "@l q. length start finish injective steps" THEN
    ASM_CASES_TAC `(y:A) IN IMAGE (q:num->A) (0..l)` THENL
     [FIRST_X_ASSUM(LABEL_TAC "y_on_path") THEN
      USE_THEN "y_on_path" MP_TAC THEN
      REWRITE_TAC[IN_IMAGE; IN_NUMSEG] THEN
      INTRO_TAC "@i. y_value (_ i_bound)" THEN
      MAP_EVERY EXISTS_TAC [`i:num`; `q:num->A`] THEN
      REPEAT CONJ_TAC THENL
       [ASM_ARITH_TAC;
        USE_THEN "start" ACCEPT_TAC;
        USE_THEN "y_value" (ACCEPT_TAC o SYM);
        REWRITE_TAC[INJ; IN_UNIV; IN_NUMSEG] THEN
        MAP_EVERY X_GEN_TAC [`j:num`; `k:num`] THEN
        INTRO_TAC "(_ j_bound) (_ k_bound) equal" THEN
        USE_THEN "injective" MP_TAC THEN
        REWRITE_TAC[INJ; IN_UNIV; IN_NUMSEG] THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
        ASM_ARITH_TAC;
        X_GEN_TAC `j:num` THEN DISCH_THEN(LABEL_TAC "j_bound") THEN
        USE_THEN "steps" MATCH_MP_TAC THEN ASM_ARITH_TAC];
      FIRST_X_ASSUM(LABEL_TAC "y_off_path") THEN
      ABBREV_TAC
       `p:num->A = \i. if i <= l then (q:num->A) i else y` THEN
      POP_ASSUM(LABEL_TAC "p_definition") THEN
      MAP_EVERY EXISTS_TAC [`SUC l`; `p:num->A`] THEN
      REPEAT CONJ_TAC THENL
       [ASM_ARITH_TAC;
        EXPAND_TAC "p" THEN BETA_TAC THEN ASM_REWRITE_TAC[LE_0];
        EXPAND_TAC "p" THEN BETA_TAC THEN
        ASM_REWRITE_TAC[ARITH_RULE `~(SUC l <= l)`];
        REWRITE_TAC[INJ; IN_UNIV; IN_NUMSEG] THEN
        MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN
        INTRO_TAC "(_ i_bound) (_ j_bound) equal" THEN
        EXPAND_TAC "p" THEN BETA_TAC THEN
        ASM_CASES_TAC `i:num <= l` THEN
        ASM_CASES_TAC `j:num <= l` THENL
         [SUBGOAL_THEN `(q:num->A) i = q j`
          (LABEL_TAC "old_equal") THENL
           [USE_THEN "equal" MP_TAC THEN
            USE_THEN "p_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
            ASM_REWRITE_TAC[];
            ALL_TAC] THEN
          USE_THEN "injective" MP_TAC THEN
          REWRITE_TAC[INJ; IN_UNIV; IN_NUMSEG] THEN
          DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[LE_0];
          SUBGOAL_THEN `j:num = SUC l` SUBST_ALL_TAC THENL
           [ASM_ARITH_TAC;
            SUBGOAL_THEN `(q:num->A) i = y`
            (LABEL_TAC "old_new_equal") THENL
             [USE_THEN "equal" MP_TAC THEN
              USE_THEN "p_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
              ASM_REWRITE_TAC[];
              ALL_TAC] THEN
            USE_THEN "y_off_path" MP_TAC THEN
            REWRITE_TAC[IN_IMAGE; IN_NUMSEG] THEN
            ASM_MESON_TAC[LE_0]];
          SUBGOAL_THEN `i:num = SUC l` SUBST_ALL_TAC THENL
           [ASM_ARITH_TAC;
            SUBGOAL_THEN `(y:A) = (q:num->A) j`
            (LABEL_TAC "new_old_equal") THENL
             [USE_THEN "equal" MP_TAC THEN
              USE_THEN "p_definition" (fun th -> REWRITE_TAC[GSYM th]) THEN
              ASM_REWRITE_TAC[];
              ALL_TAC] THEN
            USE_THEN "y_off_path" MP_TAC THEN
            REWRITE_TAC[IN_IMAGE; IN_NUMSEG] THEN
            ASM_MESON_TAC[LE_0]];
          ASM_ARITH_TAC];
        X_GEN_TAC `i:num` THEN
        DISCH_THEN(LABEL_TAC "i_bound") THEN
        ASM_CASES_TAC `i:num < l` THENL
         [SUBGOAL_THEN `i:num <= l /\ i + 1 <= l`
          STRIP_ASSUME_TAC THENL
           [ASM_ARITH_TAC;
            ALL_TAC] THEN
          EXPAND_TAC "p" THEN BETA_TAC THEN
          ASM_REWRITE_TAC[] THEN
          USE_THEN "steps" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
          SUBGOAL_THEN `i:num = l` SUBST_ALL_TAC THENL
           [ASM_ARITH_TAC;
            USE_THEN "p_definition"
             (fun th -> REWRITE_TAC[GSYM th]) THEN
            BETA_TAC THEN
            ASM_REWRITE_TAC
             [LE_REFL; ARITH_RULE `~(l + 1 <= l)`]]]]]]);;

let GRAPH_REACHABLE_IMP_SIMPLE_INDEXED_PATH = prove
 (`!E:(A->bool)->bool. !u v:A.
        graph_reachable E u v
        ==> ?l q:num->A.
              q 0 = u /\
              q l = v /\
              INJ q (0..l) (:A) /\
              indexed_path_edges q l SUBSET E`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_reachable; RTC_RELPOW] THEN
  INTRO_TAC "@n. reachable" THEN
  MP_TAC(MATCH_MP
   (ISPECL
     [`\x y:A. {x,y} IN E`; `n:num`; `u:A`; `v:A`]
     RELPOW_IMP_SIMPLE_INDEXED_PATH)
   (ASSUME `RELPOW n (\x y:A. {x,y} IN E) u v`)) THEN
  INTRO_TAC "@l q. _ start finish injective steps" THEN
  MAP_EVERY EXISTS_TAC [`l:num`; `q:num->A`] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[SUBSET; IN_INDEXED_PATH_EDGES] THEN
  X_GEN_TAC `e:A->bool` THEN
  INTRO_TAC "@i. i_bound edge_value" THEN
  USE_THEN "edge_value" SUBST1_TAC THEN
  USE_THEN "steps"
   (fun th -> MATCH_MP_TAC(BETA_RULE(SPEC `i:num` th))) THEN
  USE_THEN "i_bound" ACCEPT_TAC);;

let GRAPH_REACHABLE_IMP_SIMPLE_INDEXED_PATH_IN = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v:A.
        finite_simple_graph V E /\
        u IN V /\
        graph_reachable E u v
        ==> ?l q:num->A.
              q 0 = u /\
              q l = v /\
              INJ q (0..l) (:A) /\
              indexed_path_vertices q l SUBSET V /\
              indexed_path_edges q l SUBSET E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph u_vertex reachable" THEN
  MP_TAC(MATCH_MP
   (ISPECL [`E:(A->bool)->bool`; `u:A`; `v:A`]
     GRAPH_REACHABLE_IMP_SIMPLE_INDEXED_PATH)
   (ASSUME `graph_reachable (E:(A->bool)->bool) u v`)) THEN
  INTRO_TAC "@l q. start finish injective path_edges" THEN
  MAP_EVERY EXISTS_TAC [`l:num`; `q:num->A`] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[SUBSET; IN_INDEXED_PATH_VERTICES] THEN
  X_GEN_TAC `x:A` THEN
  INTRO_TAC "@i. i_bound x_value" THEN
  USE_THEN "x_value" SUBST1_TAC THEN
  ASM_CASES_TAC `i:num = 0` THENL
   [ASM_REWRITE_TAC[];
    SUBGOAL_THEN `0 < i` (LABEL_TAC "positive") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `{(q:num->A)(i - 1),q i} IN E`
    (LABEL_TAC "edge") THENL
     [USE_THEN "path_edges" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      REWRITE_TAC[IN_INDEXED_PATH_EDGES] THEN
      EXISTS_TAC `i - 1` THEN
      ASM_SIMP_TAC[ARITH_RULE `0 < i ==> i - 1 + 1 = i`] THEN
      ASM_ARITH_TAC;
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `(q:num->A)(i - 1)`; `(q:num->A) i`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* If a subdivision uses one newly inserted edge, replace that edge by a     *)
(* path whose internal vertices are fresh for the old ambient graph.         *)
(* ------------------------------------------------------------------------- *)

let GRAPH_SUBDIVISION_TRANSFER_ACROSS_INSERTED_EDGE = prove
 (`!B P V W:A->bool.
   !D f E G:(A->bool)->bool.
   !u v:A. !l. !q:num->A.
        graph_subdivision B D P f /\
        P SUBSET V /\
        f SUBSET
          induced_subgraph_edges ({u,v} INSERT E) P /\
        0 < l /\
        q 0 = u /\
        q l = v /\
        INJ q (0..l) (:A) /\
        (!i. 0 < i /\ i < l ==> ~(q i IN V)) /\
        V UNION indexed_path_vertices q l SUBSET W /\
        E UNION indexed_path_edges q l SUBSET G
        ==> ?Q h.
              graph_subdivision B D Q h /\
              Q SUBSET W /\
              h SUBSET G`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "subdivision vertices edges positive start finish injective fresh \
    final_vertices final_edges" THEN
  SUBGOAL_THEN
   `(f:(A->bool)->bool) SUBSET ({u,v} INSERT E)`
  (LABEL_TAC "ambient_edges") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC
     `induced_subgraph_edges
       ({u:A,v} INSERT E:(A->bool)->bool) P` THEN
    ASM_REWRITE_TAC[INDUCED_SUBGRAPH_EDGES_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `E SUBSET (G:(A->bool)->bool) /\
    indexed_path_edges (q:num->A) l SUBSET G`
  (CONJUNCTS_THEN2 (LABEL_TAC "old_edges_in_final")
    (LABEL_TAC "path_edges_in_final")) THENL
   [USE_THEN "final_edges" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `({u:A,v}:A->bool) IN f` THENL
   [FIRST_X_ASSUM(LABEL_TAC "temporary_edge") THEN
    ABBREV_TAC
     `Q:A->bool = P UNION indexed_path_vertices (q:num->A) l` THEN
    ABBREV_TAC
     `h:(A->bool)->bool =
        (f DELETE {u:A,v}) UNION indexed_path_edges q l` THEN
    MAP_EVERY EXISTS_TAC
     [`Q:A->bool`; `h:(A->bool)->bool`] THEN
    REPEAT CONJ_TAC THENL
     [MAP_EVERY EXPAND_TAC ["Q"; "h"] THEN
      USE_THEN "start" (fun th -> REWRITE_TAC[GSYM th]) THEN
      USE_THEN "finish" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC
       GRAPH_SUBDIVISION_EXTEND_EDGE_BY_INDEXED_PATH_LENGTH THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `i:num` THEN INTRO_TAC "i_positive i_bound" THEN
      DISCH_THEN(LABEL_TAC "i_in_target") THEN
      USE_THEN "fresh" (MP_TAC o SPEC `i:num`) THEN
      USE_THEN "vertices" MP_TAC THEN
      REWRITE_TAC[SUBSET] THEN ASM_MESON_TAC[];
      EXPAND_TAC "Q" THEN
      USE_THEN "vertices" MP_TAC THEN
      USE_THEN "final_vertices" MP_TAC THEN SET_TAC[];
      EXPAND_TAC "h" THEN
      USE_THEN "ambient_edges" MP_TAC THEN
      USE_THEN "old_edges_in_final" MP_TAC THEN
      USE_THEN "path_edges_in_final" MP_TAC THEN SET_TAC[]];
    FIRST_X_ASSUM(LABEL_TAC "temporary_edge_not_used") THEN
    MAP_EVERY EXISTS_TAC
     [`P:A->bool`; `f:(A->bool)->bool`] THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "vertices" MP_TAC THEN
      USE_THEN "final_vertices" MP_TAC THEN SET_TAC[];
      USE_THEN "old_edges_in_final" MP_TAC THEN
      USE_THEN "ambient_edges" MP_TAC THEN
      USE_THEN "temporary_edge_not_used" MP_TAC THEN SET_TAC[]]]);;

let GRAPH_KURATOWSKI_OBSTRUCTION_TRANSFER_ACROSS_INSERTED_EDGE = prove
 (`!V W:A->bool. !E G:(A->bool)->bool.
   !u v:A. !l. !q:num->A.
        graph_kuratowski_obstruction V ({u,v} INSERT E) /\
        0 < l /\
        q 0 = u /\
        q l = v /\
        INJ q (0..l) (:A) /\
        (!i. 0 < i /\ i < l ==> ~(q i IN V)) /\
        V UNION indexed_path_vertices q l SUBSET W /\
        E UNION indexed_path_edges q l SUBSET G
        ==> graph_kuratowski_obstruction W G`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "obstruction positive start finish injective fresh \
    final_vertices final_edges" THEN
  USE_THEN "obstruction" MP_TAC THEN
  REWRITE_TAC[graph_kuratowski_obstruction] THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (X_CHOOSE_THEN `B:A->bool`
    (X_CHOOSE_THEN `P:A->bool`
     (X_CHOOSE_THEN `f:(A->bool)->bool`
      (LABEL_TAC "witness"))))
   (X_CHOOSE_THEN `X:A->bool`
    (X_CHOOSE_THEN `Y:A->bool`
     (X_CHOOSE_THEN `P:A->bool`
      (X_CHOOSE_THEN `f:(A->bool)->bool`
       (LABEL_TAC "witness")))))) THENL
   [USE_THEN "witness" MP_TAC THEN
    INTRO_TAC "size subdivision vertices edges" THEN
    MP_TAC(MATCH_MP
     (ISPECL
       [`B:A->bool`; `P:A->bool`; `V:A->bool`; `W:A->bool`;
        `complete_graph_edges (B:A->bool)`;
        `f:(A->bool)->bool`; `E:(A->bool)->bool`;
        `G:(A->bool)->bool`; `u:A`; `v:A`; `l:num`;
        `q:num->A`]
       GRAPH_SUBDIVISION_TRANSFER_ACROSS_INSERTED_EDGE)
     (CONJ
       (ASSUME
        `graph_subdivision
          (B:A->bool) (complete_graph_edges B)
          (P:A->bool) (f:(A->bool)->bool)`)
       (CONJ
        (ASSUME `(P:A->bool) SUBSET V`)
        (CONJ
         (ASSUME
          `(f:(A->bool)->bool) SUBSET
           induced_subgraph_edges
            ({u:A,v} INSERT E) P`)
         (CONJ
          (ASSUME `0 < l`)
          (CONJ
           (ASSUME `(q:num->A) 0 = u`)
           (CONJ
            (ASSUME `(q:num->A) l = v`)
            (CONJ
             (ASSUME `INJ (q:num->A) (0..l) (:A)`)
             (CONJ
              (ASSUME
               `!i. 0 < i /\ i < l ==> ~((q:num->A) i IN V)`)
              (CONJ
               (ASSUME
                `V UNION indexed_path_vertices (q:num->A) l
                 SUBSET W`)
    (ASSUME
                `E UNION indexed_path_edges (q:num->A) l
                 SUBSET G`))))))))))) THEN
    INTRO_TAC "@Q h. transferred final_target_vertices final_target_edges" THEN
    REWRITE_TAC[graph_kuratowski_obstruction] THEN DISJ1_TAC THEN
    MAP_EVERY EXISTS_TAC
     [`B:A->bool`; `Q:A->bool`; `h:(A->bool)->bool`] THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC GRAPH_SUBDIVISION_EDGES_SUBSET_INDUCED THEN
    MAP_EVERY EXISTS_TAC
     [`B:A->bool`; `complete_graph_edges (B:A->bool)`] THEN
    ASM_REWRITE_TAC[];
    USE_THEN "witness" MP_TAC THEN
    INTRO_TAC
     "X_size Y_size disjoint subdivision vertices edges" THEN
    MP_TAC(MATCH_MP
     (ISPECL
       [`X UNION Y:A->bool`; `P:A->bool`; `V:A->bool`; `W:A->bool`;
        `complete_bipartite_edges (X:A->bool) Y`;
        `f:(A->bool)->bool`; `E:(A->bool)->bool`;
        `G:(A->bool)->bool`; `u:A`; `v:A`; `l:num`;
        `q:num->A`]
       GRAPH_SUBDIVISION_TRANSFER_ACROSS_INSERTED_EDGE)
     (CONJ
       (ASSUME
        `graph_subdivision
          (X UNION Y:A->bool)
          (complete_bipartite_edges (X:A->bool) Y)
          (P:A->bool) (f:(A->bool)->bool)`)
       (CONJ
        (ASSUME `(P:A->bool) SUBSET V`)
        (CONJ
         (ASSUME
          `(f:(A->bool)->bool) SUBSET
           induced_subgraph_edges
            ({u:A,v} INSERT E) P`)
         (CONJ
          (ASSUME `0 < l`)
          (CONJ
           (ASSUME `(q:num->A) 0 = u`)
           (CONJ
            (ASSUME `(q:num->A) l = v`)
            (CONJ
             (ASSUME `INJ (q:num->A) (0..l) (:A)`)
             (CONJ
              (ASSUME
               `!i. 0 < i /\ i < l ==> ~((q:num->A) i IN V)`)
              (CONJ
               (ASSUME
                `V UNION indexed_path_vertices (q:num->A) l
                 SUBSET W`)
    (ASSUME
                `E UNION indexed_path_edges (q:num->A) l
                 SUBSET G`))))))))))) THEN
    INTRO_TAC "@Q h. transferred final_target_vertices final_target_edges" THEN
    REWRITE_TAC[graph_kuratowski_obstruction] THEN DISJ2_TAC THEN
    MAP_EVERY EXISTS_TAC
     [`X:A->bool`; `Y:A->bool`; `Q:A->bool`;
      `h:(A->bool)->bool`] THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC GRAPH_SUBDIVISION_EDGES_SUBSET_INDUCED THEN
    MAP_EVERY EXISTS_TAC
     [`X UNION Y:A->bool`;
     `complete_bipartite_edges (X:A->bool) Y`] THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Every component behind a two-vertex separator meets both separator        *)
(* vertices in a 2-connected graph.                                          *)
(* ------------------------------------------------------------------------- *)

let VERTEX_2_CONNECTED_GRAPH_COMPONENT_NEIGHBOR = prove
 (`!V E u v x:A.
        vertex_k_connected_graph 2 V E /\
        u IN V /\
        v IN V /\
        ~(u = v) /\
        x IN V DIFF {u,v}
        ==> ?y.
              y IN graph_component
                (induced_subgraph_edges E (V DIFF {u,v})) x /\
              {u,y} IN E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "connected u_vertex v_vertex distinct x_vertex" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `2` THEN USE_THEN "connected" ACCEPT_TAC;
    ALL_TAC] THEN
  ABBREV_TAC
   `D:(A->bool)->bool =
      induced_subgraph_edges E (V DIFF {u:A,v})` THEN
  ABBREV_TAC
   `C:A->bool = graph_component (D:(A->bool)->bool) x` THEN
  SUBGOAL_THEN `(C:A->bool) SUBSET V DIFF {u,v}`
  (LABEL_TAC "component_subset") THENL
   [MAP_EVERY EXPAND_TAC ["C"; "D"] THEN
    MATCH_MP_TAC GRAPH_DELETED_COMPONENT_SUBSET THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph
     ((V:A->bool) DELETE v)
     (induced_subgraph_edges E (V DELETE v))`
  (LABEL_TAC "deleted_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH THEN
    EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[] THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph
     ((V:A->bool) DELETE v)
     (induced_subgraph_edges E (V DELETE v))`
  (LABEL_TAC "deleted_connected") THENL
   [MATCH_MP_TAC VERTEX_2_CONNECTED_GRAPH_DELETE_VERTEX THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(C:A->bool) SUBSET V DELETE v`
  (LABEL_TAC "component_deleted_subset") THENL
   [USE_THEN "component_subset" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:A) IN C` (LABEL_TAC "x_component") THENL
   [EXPAND_TAC "C" THEN MATCH_ACCEPT_TAC GRAPH_COMPONENT_REFL;
    ALL_TAC] THEN
  SUBGOAL_THEN `~((C:A->bool) = V DELETE v)`
  (LABEL_TAC "component_proper") THENL
   [DISCH_THEN(LABEL_TAC "component_all") THEN
    SUBGOAL_THEN `(u:A) IN C` (LABEL_TAC "u_component") THENL
     [USE_THEN "component_all" (fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[IN_DELETE];
      USE_THEN "component_subset" MP_TAC THEN
      USE_THEN "u_component" MP_TAC THEN SET_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(V:A->bool) DELETE v`;
    `induced_subgraph_edges (E:(A->bool)->bool) (V DELETE v)`;
    `C:A->bool`; `x:A`]
   CONNECTED_GRAPH_CROSSING_EDGE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@p y. p_outside y_component crossing_edge" THEN
  SUBGOAL_THEN `(p:A) = u` (LABEL_TAC "p_eq_u") THENL
   [MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "p_not_u") THEN
    SUBGOAL_THEN
     `{y:A,p} IN (D:(A->bool)->bool)`
    (LABEL_TAC "component_edge") THENL
     [EXPAND_TAC "D" THEN
      USE_THEN "crossing_edge" MP_TAC THEN
      REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
      INTRO_TAC "original_edge edge_subset" THEN
      REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
      CONJ_TAC THENL
       [ONCE_REWRITE_TAC[SET_RULE `{y:A,p} = {p,y}`] THEN
        USE_THEN "original_edge" ACCEPT_TAC;
        USE_THEN "component_subset" MP_TAC THEN
        USE_THEN "y_component" MP_TAC THEN
        USE_THEN "p_outside" MP_TAC THEN ASM SET_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `(p:A) IN C` (LABEL_TAC "p_component") THENL
     [EXPAND_TAC "C" THEN
      MATCH_MP_TAC GRAPH_COMPONENT_CLOSED THEN
      EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[];
      USE_THEN "p_outside" MP_TAC THEN
      USE_THEN "p_component" MP_TAC THEN SET_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "crossing_edge" MP_TAC THEN
  REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN ASM SET_TAC[]);;

let VERTEX_2_CONNECTED_GRAPH_COMPONENT_PATH = prove
 (`!V E u v x:A.
        vertex_k_connected_graph 2 V E /\
        u IN V /\
        v IN V /\
        ~(u = v) /\
        x IN V DIFF {u,v}
        ==> ?l q:num->A.
              0 < l /\
              q 0 = u /\
              q l = v /\
              INJ q (0..l) (:A) /\
              (!i. 0 < i /\ i < l
                   ==> q i IN graph_component
                        (induced_subgraph_edges E (V DIFF {u,v})) x) /\
              indexed_path_edges q l SUBSET E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "connected u_vertex v_vertex distinct x_vertex" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `2` THEN USE_THEN "connected" ACCEPT_TAC;
    ALL_TAC] THEN
  ABBREV_TAC `R:A->bool = V DIFF {u:A,v}` THEN
  ABBREV_TAC
   `D:(A->bool)->bool = induced_subgraph_edges E (R:A->bool)` THEN
  ABBREV_TAC
   `C:A->bool = graph_component (D:(A->bool)->bool) x` THEN
  ABBREV_TAC `S:A->bool = C UNION {u:A,v}` THEN
  ABBREV_TAC
   `H:(A->bool)->bool = induced_subgraph_edges E (S:A->bool)` THEN
  ABBREV_TAC
   `K:(A->bool)->bool = graph_component_edges (D:(A->bool)->bool) x` THEN
  SUBGOAL_THEN `(C:A->bool) SUBSET R`
  (LABEL_TAC "component_subset") THENL
   [EXPAND_TAC "C" THEN EXPAND_TAC "D" THEN EXPAND_TAC "R" THEN
    MATCH_MP_TAC GRAPH_DELETED_COMPONENT_SUBSET THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (R:A->bool) D`
  (LABEL_TAC "deleted_graph") THENL
   [EXPAND_TAC "D" THEN
    MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH THEN
    EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[] THEN
    EXPAND_TAC "R" THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (C:A->bool) K`
  (LABEL_TAC "component_graph") THENL
   [MAP_EVERY EXPAND_TAC ["C"; "K"] THEN
    MATCH_MP_TAC FINITE_SIMPLE_GRAPH_COMPONENT THEN
    EXISTS_TAC `R:A->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `connected_graph (C:A->bool) K`
  (LABEL_TAC "component_connected") THENL
   [MAP_EVERY EXPAND_TAC ["C"; "K"] THEN
    MATCH_MP_TAC GRAPH_COMPONENT_EDGES_CONNECTED THEN
    EXISTS_TAC `R:A->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(S:A->bool) SUBSET V`
  (LABEL_TAC "side_subset") THENL
   [EXPAND_TAC "S" THEN
    USE_THEN "component_subset" MP_TAC THEN
    EXPAND_TAC "R" THEN ASM SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `finite_simple_graph (S:A->bool) H`
  (LABEL_TAC "side_graph") THENL
   [EXPAND_TAC "H" THEN
    MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH THEN
    EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `u:A`; `v:A`; `x:A`]
   VERTEX_2_CONNECTED_GRAPH_COMPONENT_NEIGHBOR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "a_component")
    (LABEL_TAC "u_a_edge"))) THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `v:A`; `u:A`; `x:A`]
   VERTEX_2_CONNECTED_GRAPH_COMPONENT_NEIGHBOR) THEN
  ASM_REWRITE_TAC[SET_RULE `{v:A,u} = {u,v}`] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "b_component")
    (LABEL_TAC "v_b_edge"))) THEN
  SUBGOAL_THEN `(K:(A->bool)->bool) SUBSET H`
  (LABEL_TAC "component_edges_in_side") THENL
   [REWRITE_TAC[SUBSET] THEN
    X_GEN_TAC `e:A->bool` THEN
    EXPAND_TAC "K" THEN REWRITE_TAC[IN_GRAPH_COMPONENT_EDGES] THEN
    INTRO_TAC "e_deleted e_component" THEN
    EXPAND_TAC "H" THEN REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    CONJ_TAC THENL
     [USE_THEN "e_deleted" MP_TAC THEN EXPAND_TAC "D" THEN
      REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
      INTRO_TAC "e_original e_deleted_vertices" THEN
      USE_THEN "e_original" ACCEPT_TAC;
      EXPAND_TAC "S" THEN EXPAND_TAC "C" THEN
      MATCH_MP_TAC SUBSET_TRANS THEN
      EXISTS_TAC `graph_component (D:(A->bool)->bool) x` THEN
      CONJ_TAC THENL
       [USE_THEN "e_component" ACCEPT_TAC;
        REWRITE_TAC[SUBSET; IN_UNION] THEN
        X_GEN_TAC `z:A` THEN DISCH_TAC THEN DISJ1_TAC THEN
        ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  SUBGOAL_THEN `{u:A,a} IN H` (LABEL_TAC "u_a_side_edge") THENL
   [EXPAND_TAC "H" THEN REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      EXPAND_TAC "S" THEN
      USE_THEN "a_component" MP_TAC THEN SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `{v:A,b} IN H` (LABEL_TAC "v_b_side_edge") THENL
   [EXPAND_TAC "H" THEN REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      EXPAND_TAC "S" THEN
      USE_THEN "b_component" MP_TAC THEN SET_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN C ==> graph_reachable H z x`
  (LABEL_TAC "component_reaches_root") THENL
   [X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_component") THEN
    SUBGOAL_THEN `graph_reachable (K:(A->bool)->bool) z x`
    (LABEL_TAC "component_path") THENL
     [USE_THEN "component_connected" MP_TAC THEN
      REWRITE_TAC[connected_graph] THEN
      DISCH_THEN MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[] THEN
      EXPAND_TAC "C" THEN MATCH_ACCEPT_TAC GRAPH_COMPONENT_REFL;
      MATCH_MP_TAC(ISPECL
       [`K:(A->bool)->bool`; `H:(A->bool)->bool`; `z:A`; `x:A`]
       GRAPH_REACHABLE_MONO) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN S ==> graph_reachable H z x`
  (LABEL_TAC "reaches_root") THENL
   [X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_side") THEN
    SUBGOAL_THEN
     `(z:A) IN C \/ z = u \/ z = v`
    (DISJ_CASES_THEN2 (LABEL_TAC "z_component")
     (DISJ_CASES_THEN2 (LABEL_TAC "z_eq_u")
      (LABEL_TAC "z_eq_v"))) THENL
     [USE_THEN "z_side" MP_TAC THEN EXPAND_TAC "S" THEN SET_TAC[];
      USE_THEN "component_reaches_root" MATCH_MP_TAC THEN
      USE_THEN "z_component" ACCEPT_TAC;
      USE_THEN "z_eq_u" SUBST1_TAC THEN
      MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN
      EXISTS_TAC `a:A` THEN CONJ_TAC THENL
       [MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
        USE_THEN "u_a_side_edge" ACCEPT_TAC;
        USE_THEN "component_reaches_root" MATCH_MP_TAC THEN
        USE_THEN "a_component" ACCEPT_TAC];
      USE_THEN "z_eq_v" SUBST1_TAC THEN
      MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN
      EXISTS_TAC `b:A` THEN CONJ_TAC THENL
       [MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
        USE_THEN "v_b_side_edge" ACCEPT_TAC;
        USE_THEN "component_reaches_root" MATCH_MP_TAC THEN
        USE_THEN "b_component" ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `connected_graph (S:A->bool) H`
  (LABEL_TAC "side_connected") THENL
   [REWRITE_TAC[connected_graph] THEN
    MAP_EVERY X_GEN_TAC [`z:A`; `w:A`] THEN
    INTRO_TAC "z_side w_side" THEN
    MATCH_MP_TAC(ISPECL
     [`H:(A->bool)->bool`; `z:A`; `x:A`; `w:A`]
     GRAPH_REACHABLE_TRANS) THEN
    CONJ_TAC THENL
     [USE_THEN "reaches_root" MATCH_MP_TAC THEN
      USE_THEN "z_side" ACCEPT_TAC;
      MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
      USE_THEN "reaches_root" MATCH_MP_TAC THEN
      USE_THEN "w_side" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(u:A) IN S /\ (v:A) IN S`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_side") (LABEL_TAC "v_side")) THENL
   [EXPAND_TAC "S" THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `graph_reachable (H:(A->bool)->bool) u v`
  (LABEL_TAC "u_v_reachable") THENL
   [USE_THEN "side_connected" MP_TAC THEN
    REWRITE_TAC[connected_graph] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (ISPECL
     [`S:A->bool`; `H:(A->bool)->bool`; `u:A`; `v:A`]
     GRAPH_REACHABLE_IMP_SIMPLE_INDEXED_PATH_IN)
   (CONJ
    (ASSUME `finite_simple_graph (S:A->bool) H`)
    (CONJ
     (ASSUME `(u:A) IN S`)
     (ASSUME `graph_reachable (H:(A->bool)->bool) u v`)))) THEN
  INTRO_TAC
   "@l q. start finish injective path_vertices path_edges" THEN
  SUBGOAL_THEN `0 < l` (LABEL_TAC "positive") THENL
   [SUBGOAL_THEN `~(l = 0)` (LABEL_TAC "nonzero") THENL
     [DISCH_THEN(LABEL_TAC "zero") THEN
      USE_THEN "distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
      USE_THEN "zero" (fun zth ->
       USE_THEN "start" (fun sth ->
        USE_THEN "finish" (fun fth ->
         ACCEPT_TAC
          (TRANS (SYM sth)
            (TRANS (SYM(AP_TERM `q:num->A` zth)) fth)))));
              ASM_ARITH_TAC];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`l:num`; `q:num->A`] THEN
  ASM_REWRITE_TAC[] THEN
  (CONJ_TAC THENL
   [X_GEN_TAC `i:num` THEN INTRO_TAC "i_positive i_bound" THEN
    SUBGOAL_THEN `~((q:num->A) i = u) /\ ~(q i = v)`
    (CONJUNCTS_THEN2 (LABEL_TAC "not_u") (LABEL_TAC "not_v")) THENL
     [CONJ_TAC THENL
       [DISCH_THEN(LABEL_TAC "q_eq_u") THEN
        SUBGOAL_THEN `i:num = 0` MP_TAC THENL
         [USE_THEN "injective" MP_TAC THEN
                  REWRITE_TAC[INJ; IN_UNIV; IN_NUMSEG] THEN
                  DISCH_THEN MATCH_MP_TAC THEN
                  ASM_REWRITE_TAC[LE_0] THEN ASM_ARITH_TAC;
          ASM_ARITH_TAC];
        DISCH_THEN(LABEL_TAC "q_eq_v") THEN
        SUBGOAL_THEN `i:num = l` MP_TAC THENL
         [USE_THEN "injective" MP_TAC THEN
                  REWRITE_TAC[INJ; IN_UNIV; IN_NUMSEG] THEN
                  DISCH_THEN MATCH_MP_TAC THEN
                  ASM_REWRITE_TAC[LE_0] THEN ASM_ARITH_TAC;
          ASM_ARITH_TAC]];
      ALL_TAC] THEN
            USE_THEN "path_vertices"
     (MP_TAC o SPEC `(q:num->A) i` o REWRITE_RULE[SUBSET]) THEN
    ANTS_TAC THENL
             [REWRITE_TAC[IN_INDEXED_PATH_VERTICES] THEN
              EXISTS_TAC `i:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      EXPAND_TAC "S" THEN ASM SET_TAC[]];
    MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `H:(A->bool)->bool` THEN ASM_REWRITE_TAC[] THEN
    EXPAND_TAC "H" THEN
    REWRITE_TAC[INDUCED_SUBGRAPH_EDGES_SUBSET]]));;

(* ------------------------------------------------------------------------- *)
(* Euler-planar amalgamation lemmas for separator induction.                 *)
(* ------------------------------------------------------------------------- *)

let CONNECTED_GRAPH_UNION_SHARED_VERTEX = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u:A.
        connected_graph V1 E1 /\
        connected_graph V2 E2 /\
        u IN V1 /\
        u IN V2
        ==> connected_graph (V1 UNION V2) (E1 UNION E2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "connected1 connected2 u_vertex1 u_vertex2" THEN
  REWRITE_TAC[connected_graph] THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
  INTRO_TAC "x_vertex y_vertex" THEN
  MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN
  EXISTS_TAC `u:A` THEN CONJ_TAC THENL
   [USE_THEN "x_vertex" MP_TAC THEN REWRITE_TAC[IN_UNION] THEN
    DISCH_THEN(DISJ_CASES_THEN2
     (LABEL_TAC "x_vertex1") (LABEL_TAC "x_vertex2")) THENL
     [MATCH_MP_TAC(ISPECL
       [`E1:(A->bool)->bool`; `E1 UNION E2:(A->bool)->bool`;
        `x:A`; `u:A`] GRAPH_REACHABLE_MONO) THEN
      REWRITE_TAC[SUBSET_UNION] THEN
      USE_THEN "connected1" MP_TAC THEN
      REWRITE_TAC[connected_graph] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC(ISPECL
       [`E2:(A->bool)->bool`; `E1 UNION E2:(A->bool)->bool`;
        `x:A`; `u:A`] GRAPH_REACHABLE_MONO) THEN
      REWRITE_TAC[SUBSET_UNION] THEN
      USE_THEN "connected2" MP_TAC THEN
      REWRITE_TAC[connected_graph] THEN ASM_MESON_TAC[]];
    MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
    USE_THEN "y_vertex" MP_TAC THEN REWRITE_TAC[IN_UNION] THEN
    DISCH_THEN(DISJ_CASES_THEN2
     (LABEL_TAC "y_vertex1") (LABEL_TAC "y_vertex2")) THENL
     [MATCH_MP_TAC(ISPECL
       [`E1:(A->bool)->bool`; `E1 UNION E2:(A->bool)->bool`;
        `y:A`; `u:A`] GRAPH_REACHABLE_MONO) THEN
      REWRITE_TAC[SUBSET_UNION] THEN
      USE_THEN "connected1" MP_TAC THEN
      REWRITE_TAC[connected_graph] THEN ASM_MESON_TAC[];
      MATCH_MP_TAC(ISPECL
       [`E2:(A->bool)->bool`; `E1 UNION E2:(A->bool)->bool`;
        `y:A`; `u:A`] GRAPH_REACHABLE_MONO) THEN
      REWRITE_TAC[SUBSET_UNION] THEN
      USE_THEN "connected2" MP_TAC THEN
      REWRITE_TAC[connected_graph] THEN ASM_MESON_TAC[]]]);;

let CONNECTED_EULER_PLANAR_ROTATION_IMP_GRAPH = prove
 (`!V E r:(A#A)->A#A.
        euler_planar_rotation V E r /\
        connected_graph V E
        ==> euler_planar_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "euler connected" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "euler" MP_TAC THEN
    REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[euler_planar_graph] THEN
  CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "u_vertex") THEN
    MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
     CONNECTED_GRAPH_COMPONENT_EDGES) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "component component_edges" THEN
    EXISTS_TAC `r:(A#A)->A#A` THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "euler" ACCEPT_TAC]);;

let GRAPH_ROTATION_RESTRICTED_OUTGOING_NONFIXED = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A. !u:A. !d d':A#A.
        graph_rotation E r /\
        d IN outgoing_darts E u /\
        d' IN outgoing_darts E u /\
        ~(d = d')
        ==> ~(restricted_permutation r (outgoing_darts E u) d = d)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "rotation d_outgoing dprime_outgoing distinct" THEN
  DISCH_THEN(LABEL_TAC "fixed") THEN
  SUBGOAL_THEN `(r:(A#A)->A#A) d IN outgoing_darts E u`
  (LABEL_TAC "image_outgoing") THENL
   [USE_THEN "rotation" (fun rth ->
     let image_th =
       MATCH_MP
        (ISPECL
         [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `u:A`]
         GRAPH_ROTATION_IMAGE_OUTGOING_DARTS)
        rth in
     let member_th =
       MATCH_MP
        (ISPECL
         [`r:(A#A)->A#A`; `outgoing_darts E u:A#A->bool`; `d:A#A`]
         FUN_IN_IMAGE)
        (ASSUME `(d:A#A) IN outgoing_darts E u`) in
     ACCEPT_TAC(REWRITE_RULE[image_th] member_th));
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:(A#A)->A#A) d = d`
  (LABEL_TAC "rotation_fixed") THENL
   [USE_THEN "fixed" MP_TAC THEN
    REWRITE_TAC[restricted_permutation] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "d_outgoing" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "d_dart d_tail" THEN
  USE_THEN "dprime_outgoing" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS] THEN
  INTRO_TAC "dprime_dart dprime_tail" THEN
  SUBGOAL_THEN `~((d':A#A) = d)` (LABEL_TAC "reverse_distinct") THENL
   [DISCH_THEN(LABEL_TAC "reverse") THEN
    USE_THEN "distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "reverse" (ACCEPT_TAC o SYM);
    ALL_TAC] THEN
  USE_THEN "reverse_distinct" (MATCH_MP_TAC o NOT_ELIM) THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`; `d':A#A`]
   GRAPH_ROTATION_FIXED_DART_AT_TAIL) THEN
  ASM_REWRITE_TAC[]);;

let EULER_PLANAR_GRAPH_EDGE_AMALGAMATION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u v:A.
        euler_planar_graph V1 E1 /\
        connected_graph V1 E1 /\
        euler_planar_graph V2 E2 /\
        connected_graph V2 E2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2 /\
        (?w:A. {u,w} IN E2 /\ ~(w = v)) /\
        (?z:A. {v,z} IN E1 /\ ~(z = u))
        ==> euler_planar_graph (V1 UNION V2) (E1 UNION E2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "euler1 connected1 euler2 connected2 overlap common1 common2
    u_alternative v_alternative" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V1:A->bool) E1 /\
    finite_simple_graph (V2:A->bool) E2`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph1") (LABEL_TAC "graph2")) THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC EULER_PLANAR_GRAPH_FINITE_SIMPLE THEN
      USE_THEN "euler1" ACCEPT_TAC;
      MATCH_MP_TAC EULER_PLANAR_GRAPH_FINITE_SIMPLE THEN
      USE_THEN "euler2" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `{u:A,v} SUBSET V1 /\ {u,v} SUBSET V2`
  (CONJUNCTS_THEN2 (LABEL_TAC "endpoints1")
   (LABEL_TAC "endpoints2")) THENL
   [CONJ_TAC THENL
     [USE_THEN "graph1" MP_TAC;
      USE_THEN "graph2" MP_TAC] THEN
    REWRITE_TAC[finite_simple_graph] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
     (CONJUNCTS_THEN2 (K ALL_TAC)
      (fun eth -> MP_TAC(SPEC `{u:A,v}` eth)))) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(u:A) IN V1 /\ v IN V1 /\ u IN V2 /\ v IN V2`
  (STRIP_ASSUME_TAC) THENL
   [USE_THEN "endpoints1" MP_TAC THEN
    REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
    INTRO_TAC "u_vertex1 v_vertex1" THEN
    USE_THEN "endpoints2" MP_TAC THEN
    REWRITE_TAC[INSERT_SUBSET; SING_SUBSET] THEN
    INTRO_TAC "u_vertex2 v_vertex2" THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (ISPECL [`V1:A->bool`; `E1:(A->bool)->bool`; `u:A`]
    EULER_PLANAR_GRAPH_CONNECTED)
   (CONJ
    (ASSUME `euler_planar_graph (V1:A->bool) E1`)
    (CONJ
     (ASSUME `connected_graph (V1:A->bool) E1`)
     (ASSUME `(u:A) IN V1`)))) THEN
  DISCH_THEN(X_CHOOSE_THEN `r1:(A#A)->A#A`
   (LABEL_TAC "rotation1")) THEN
  MP_TAC(MATCH_MP
   (ISPECL [`V2:A->bool`; `E2:(A->bool)->bool`; `u:A`]
    EULER_PLANAR_GRAPH_CONNECTED)
   (CONJ
    (ASSUME `euler_planar_graph (V2:A->bool) E2`)
    (CONJ
     (ASSUME `connected_graph (V2:A->bool) E2`)
     (ASSUME `(u:A) IN V2`)))) THEN
  DISCH_THEN(X_CHOOSE_THEN `r2:(A#A)->A#A`
   (LABEL_TAC "rotation2")) THEN
  USE_THEN "u_alternative"
   (X_CHOOSE_THEN `w:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "u_w_edge")
     (LABEL_TAC "w_distinct"))) THEN
  USE_THEN "v_alternative"
   (X_CHOOSE_THEN `z:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "v_z_edge")
     (LABEL_TAC "z_distinct"))) THEN
  SUBGOAL_THEN
   `~(restricted_permutation
       (r2:(A#A)->A#A) (outgoing_darts E2 u) (u,v) = (u,v))`
  (LABEL_TAC "u_nonfixed") THENL
   [MATCH_MP_TAC(ISPECL
     [`E2:(A->bool)->bool`; `r2:(A#A)->A#A`; `u:A`;
      `(u:A,v:A)`; `(u:A,w:A)`]
     GRAPH_ROTATION_RESTRICTED_OUTGOING_NONFIXED) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "rotation2" MP_TAC THEN
      REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
      ASM_REWRITE_TAC[IN_OUTGOING_DARTS; IN_GRAPH_DARTS;
                      DART_EDGE_PAIR; FST];
      ASM_REWRITE_TAC[IN_OUTGOING_DARTS; IN_GRAPH_DARTS;
                      DART_EDGE_PAIR; FST];
      REWRITE_TAC[PAIR_EQ] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(restricted_permutation
       (r1:(A#A)->A#A) (outgoing_darts E1 v) (v,u) = (v,u))`
  (LABEL_TAC "v_nonfixed") THENL
   [MATCH_MP_TAC(ISPECL
     [`E1:(A->bool)->bool`; `r1:(A#A)->A#A`; `v:A`;
      `(v:A,u:A)`; `(v:A,z:A)`]
     GRAPH_ROTATION_RESTRICTED_OUTGOING_NONFIXED) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "rotation1" MP_TAC THEN
      REWRITE_TAC[euler_planar_rotation] THEN MESON_TAC[];
      REWRITE_TAC[IN_OUTGOING_DARTS; IN_GRAPH_DARTS;
                  DART_EDGE_PAIR; FST] THEN
      ONCE_REWRITE_TAC[SET_RULE `{v:A,u} = {u,v}`] THEN
      USE_THEN "common1" ACCEPT_TAC;
      ASM_REWRITE_TAC[IN_OUTGOING_DARTS; IN_GRAPH_DARTS;
                      DART_EDGE_PAIR; FST];
      REWRITE_TAC[PAIR_EQ] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `connected_graph (V1 UNION V2:A->bool) (E1 UNION E2)`
  (LABEL_TAC "union_connected") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`]
     CONNECTED_GRAPH_UNION_SHARED_VERTEX) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V1 UNION V2:A->bool`; `E1 UNION E2:(A->bool)->bool`;
    `graph_split_rotation
      (V1:A->bool) E1 E2
      (r1:(A#A)->A#A) (r2:(A#A)->A#A) u v`]
   CONNECTED_EULER_PLANAR_ROTATION_IMP_GRAPH) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
   [`V1:A->bool`; `V2:A->bool`;
    `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
    `r1:(A#A)->A#A`; `r2:(A#A)->A#A`; `u:A`; `v:A`]
   EULER_PLANAR_ROTATION_SPLIT) THEN
  ASM_REWRITE_TAC[]);;

let FINITE_SIMPLE_GRAPH_SINGLETON_INTER_DARTS_DISJOINT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        V1 INTER V2 = {u}
        ==> DISJOINT (graph_darts E1) (graph_darts E2)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph1 graph2 overlap" THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  X_GEN_TAC `d:A#A` THEN INTRO_TAC "dart1 dart2" THEN
  MP_TAC(ISPEC `d:A#A` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:A`
   (X_CHOOSE_THEN `y:A` SUBST_ALL_TAC)) THEN
  MP_TAC(MATCH_MP
   (ISPECL [`V1:A->bool`; `E1:(A->bool)->bool`; `x:A`; `y:A`]
    FINITE_SIMPLE_GRAPH_DART)
   (CONJ
    (ASSUME `finite_simple_graph (V1:A->bool) E1`)
    (ASSUME `(x:A,y:A) IN graph_darts E1`))) THEN
  INTRO_TAC "x_vertex1 y_vertex1 distinct" THEN
  MP_TAC(MATCH_MP
   (ISPECL [`V2:A->bool`; `E2:(A->bool)->bool`; `x:A`; `y:A`]
    FINITE_SIMPLE_GRAPH_DART)
   (CONJ
    (ASSUME `finite_simple_graph (V2:A->bool) E2`)
    (ASSUME `(x:A,y:A) IN graph_darts E2`))) THEN
  INTRO_TAC "x_vertex2 y_vertex2 distinct2" THEN
  USE_THEN "overlap" MP_TAC THEN ASM SET_TAC[]);;

let FINITE_SIMPLE_GRAPH_SINGLETON_INTER_EDGES_DISJOINT = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u:A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        V1 INTER V2 = {u}
        ==> DISJOINT E1 E2`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph1 graph2 overlap" THEN
  REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
  X_GEN_TAC `e:A->bool` THEN INTRO_TAC "edge1 edge2" THEN
  MP_TAC(MATCH_MP
   (ISPECL [`V1:A->bool`; `E1:(A->bool)->bool`; `e:A->bool`]
    FINITE_SIMPLE_GRAPH_EDGE)
   (CONJ
    (ASSUME `finite_simple_graph (V1:A->bool) E1`)
    (ASSUME `(e:A->bool) IN E1`))) THEN
  INTRO_TAC "@x y. x_vertex1 y_vertex1 distinct edge_pair" THEN
  SUBGOAL_THEN `(e:A->bool) SUBSET V2` (LABEL_TAC "edge_subset2") THENL
   [USE_THEN "graph2" MP_TAC THEN REWRITE_TAC[finite_simple_graph] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
     (CONJUNCTS_THEN2 (K ALL_TAC)
      (fun eth -> MP_TAC(SPEC `e:A->bool` eth)))) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC));
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:A) IN V2 /\ (y:A) IN V2`
  (CONJUNCTS_THEN2 (LABEL_TAC "x_vertex2")
    (LABEL_TAC "y_vertex2")) THENL
   [USE_THEN "edge_subset2" MP_TAC THEN
    USE_THEN "edge_pair" (fun th -> REWRITE_TAC[th]) THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:A) = u /\ (y:A) = u`
  (CONJUNCTS_THEN2 (LABEL_TAC "x_shared")
    (LABEL_TAC "y_shared")) THENL
   [USE_THEN "overlap" MP_TAC THEN
    REWRITE_TAC[EXTENSION; IN_INTER; IN_SING] THEN
    DISCH_THEN(fun th -> MP_TAC(SPEC `x:A` th) THEN
                          MP_TAC(SPEC `y:A` th)) THEN
    ASM_MESON_TAC[];
    ASM_MESON_TAC[]]);;

let GRAPH_FACE_SUCCESSOR_DART_DISJOINT_UNION = prove
 (`!E1 E2:(A->bool)->bool. !r1 r2:(A#A)->A#A.
        DISJOINT (graph_darts E1) (graph_darts E2)
        ==> !d:A#A.
              d IN graph_darts (E1 UNION E2)
              ==> graph_face_successor
                   (E1 UNION E2)
                   (disjoint_permutation_union
                     r1 (graph_darts E1) r2) d =
                  disjoint_permutation_union
                   (graph_face_successor E1 r1) (graph_darts E1)
                   (graph_face_successor E2 r2) d`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "darts_disjoint") THEN
  X_GEN_TAC `d:A#A` THEN
  REWRITE_TAC[GRAPH_DARTS_UNION; IN_UNION] THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (LABEL_TAC "d_left") (LABEL_TAC "d_right")) THENL
   [ASM_SIMP_TAC
     [GRAPH_FACE_SUCCESSOR_IN; GRAPH_DARTS_UNION; IN_UNION;
      disjoint_permutation_union; GRAPH_DARTS_REVERSE];
    SUBGOAL_THEN `~((d:A#A) IN graph_darts E1)`
    (LABEL_TAC "not_left") THENL
     [USE_THEN "darts_disjoint" MP_TAC THEN ASM SET_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `~(reverse_dart(d:A#A) IN graph_darts E1)`
    (LABEL_TAC "reverse_not_left") THENL
     [ASM_REWRITE_TAC[GRAPH_DARTS_REVERSE];
      ASM_SIMP_TAC
       [GRAPH_FACE_SUCCESSOR_IN; GRAPH_DARTS_UNION; IN_UNION;
        disjoint_permutation_union; GRAPH_DARTS_REVERSE]]]);;

let CARD_GRAPH_FACES_DART_DISJOINT_UNION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        DISJOINT (graph_darts E1) (graph_darts E2)
        ==> CARD
             (graph_faces (E1 UNION E2)
               (disjoint_permutation_union r1 (graph_darts E1) r2)) =
            CARD(graph_faces E1 r1) + CARD(graph_faces E2 r2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 rotation1 rotation2 darts_disjoint" THEN
  SUBGOAL_THEN
   `FINITE(graph_darts E1:A#A->bool) /\
    FINITE(graph_darts E2:A#A->bool)`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_darts1")
   (LABEL_TAC "finite_darts2")) THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
       [`V2:A->bool`; `E2:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(graph_face_successor E1 r1:(A#A)->A#A) permutes graph_darts E1 /\
    (graph_face_successor E2 r2:(A#A)->A#A) permutes graph_darts E2`
  (CONJUNCTS_THEN2 (LABEL_TAC "face_permutation1")
   (LABEL_TAC "face_permutation2")) THENL
   [CONJ_TAC THEN MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `permutation_orbits
     (graph_face_successor
       (E1 UNION E2)
       (disjoint_permutation_union
         (r1:(A#A)->A#A) (graph_darts E1) r2))
     (graph_darts E1 UNION graph_darts E2) =
    permutation_orbits
     (disjoint_permutation_union
       (graph_face_successor E1 r1) (graph_darts E1)
       (graph_face_successor E2 r2))
     (graph_darts E1 UNION graph_darts E2)`
  (LABEL_TAC "same_orbits") THENL
   [MATCH_MP_TAC PERMUTATION_ORBITS_EQ_ON THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_PERMUTES THEN
      ASM_REWRITE_TAC[];
      X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "dart") THEN
      MP_TAC(MATCH_MP
       (ISPECL
        [`E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
         `r1:(A#A)->A#A`; `r2:(A#A)->A#A`]
        GRAPH_FACE_SUCCESSOR_DART_DISJOINT_UNION)
       (ASSUME
        `DISJOINT (graph_darts E1:A#A->bool) (graph_darts E2)`)) THEN
      DISCH_THEN(MP_TAC o SPEC `d:A#A`) THEN
      ASM_REWRITE_TAC[GRAPH_DARTS_UNION]];
    ALL_TAC] THEN
  REWRITE_TAC[GRAPH_FACES_AS_PERMUTATION_ORBITS; GRAPH_DARTS_UNION] THEN
  USE_THEN "same_orbits" (fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC CARD_PERMUTATION_ORBITS_DISJOINT_UNION THEN
  ASM_REWRITE_TAC[]);;

let PERMUTATION_SWAP_MERGED_AFFECTED_ORBIT = prove
 (`!f:A->A. !s a b z.
        FINITE s /\
        f permutes s /\
        a IN s /\
        b IN s /\
        z IN s /\
        ~(permutation_orbit f a = permutation_orbit f b) /\
        (z IN permutation_orbit f a \/
         z IN permutation_orbit f b)
        ==> permutation_orbit (swap(a,b) o f) z =
            permutation_orbit (swap(a,b) o f) a`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite permutation a_member b_member z_member distinct affected" THEN
  ABBREV_TAC `g:A->A = swap(a,b) o (f:A->A)` THEN
  SUBGOAL_THEN `(g:A->A) permutes s` (LABEL_TAC "new_permutation") THENL
   [EXPAND_TAC "g" THEN MATCH_MP_TAC PERMUTATION_SWAP_PERMUTES THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(a:A) IN permutation_orbit g z`
  (LABEL_TAC "a_in_merged_orbit") THENL
   [EXPAND_TAC "g" THEN
    MATCH_MP_TAC(ISPECL
     [`f:A->A`; `s:A->bool`; `a:A`; `b:A`; `z:A`; `a:A`]
     PERMUTATION_SWAP_COALESCES_DISTINCT_ORBITS) THEN
    ASM_REWRITE_TAC[PERMUTATION_ORBIT_REFL];
    MP_TAC(ISPECL [`g:A->A`; `s:A->bool`; `z:A`; `a:A`]
     PERMUTATION_ORBIT_EQ) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o SYM)]);;

let PERMUTATION_SWAP_PRESERVES_OR_MERGES_ORBIT = prove
 (`!f:A->A. !s a b x y.
        FINITE s /\
        f permutes s /\
        a IN s /\
        b IN s /\
        x IN s /\
        y IN s /\
        ~(permutation_orbit f a = permutation_orbit f b) /\
        (y IN permutation_orbit f x \/
         ((x IN permutation_orbit f a \/
           x IN permutation_orbit f b) /\
          (y IN permutation_orbit f a \/
           y IN permutation_orbit f b)))
        ==> y IN permutation_orbit (swap(a,b) o f) x`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "finite permutation a_member b_member x_member y_member distinct \
    related" THEN
  ASM_CASES_TAC
   `(x:A) IN permutation_orbit f a \/
    x IN permutation_orbit f b` THENL
   [FIRST_X_ASSUM(LABEL_TAC "x_affected") THEN
    SUBGOAL_THEN
     `(y:A) IN permutation_orbit f a \/
      y IN permutation_orbit f b`
    (LABEL_TAC "y_affected") THENL
     [USE_THEN "related"
       (DISJ_CASES_THEN2
         (LABEL_TAC "same_old_orbit")
         (CONJUNCTS_THEN2 (K ALL_TAC)
           (LABEL_TAC "given_y_affected"))) THENL
       [ALL_TAC;
        ASM_REWRITE_TAC[]] THEN
      USE_THEN "x_affected"
       (DISJ_CASES_THEN2
         (LABEL_TAC "x_from_a") (LABEL_TAC "x_from_b")) THENL
       [DISJ1_TAC THEN MATCH_MP_TAC(ISPECL
         [`f:A->A`; `a:A`; `x:A`; `y:A`]
         PERMUTATION_ORBIT_TRANS) THEN ASM_REWRITE_TAC[];
        DISJ2_TAC THEN MATCH_MP_TAC(ISPECL
         [`f:A->A`; `b:A`; `x:A`; `y:A`]
         PERMUTATION_ORBIT_TRANS) THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`f:A->A`; `s:A->bool`; `a:A`; `b:A`; `x:A`; `y:A`]
     PERMUTATION_SWAP_COALESCES_DISTINCT_ORBITS) THEN
    ASM_REWRITE_TAC[];
    FIRST_X_ASSUM(LABEL_TAC "x_unaffected") THEN
    SUBGOAL_THEN
     `~((x:A) IN permutation_orbit f a) /\
      ~(x IN permutation_orbit f b)`
    (CONJUNCTS_THEN2 (LABEL_TAC "x_not_a")
      (LABEL_TAC "x_not_b")) THENL
     [USE_THEN "x_unaffected" MP_TAC THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(y:A) IN permutation_orbit f x`
    (LABEL_TAC "same_old_orbit") THENL
     [USE_THEN "related" MP_TAC THEN
      USE_THEN "x_unaffected" MP_TAC THEN MESON_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`f:A->A`; `s:A->bool`; `a:A`; `b:A`; `x:A`]
     PERMUTATION_SWAP_UNAFFECTED_ORBIT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "unchanged") THEN
    USE_THEN "unchanged" (fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_ROTATION_TAIL_ALL = prove
 (`!E:(A->bool)->bool. !r:(A#A)->A#A.
        graph_rotation E r
        ==> !d. d IN graph_darts E ==> FST(r d) = FST d`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "rotation") THEN
  X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "dart") THEN
  MATCH_MP_TAC(ISPECL
   [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `d:A#A`]
  GRAPH_ROTATION_TAIL) THEN
  ASM_REWRITE_TAC[]);;

let DISJOINT_GRAPH_ROTATION_TAIL = prove
 (`!E1 E2:(A->bool)->bool. !r1 r2:(A#A)->A#A.
        graph_rotation E1 r1 /\
        graph_rotation E2 r2
        ==> !d.
              d IN graph_darts (E1 UNION E2)
              ==> FST
                   (disjoint_permutation_union
                     r1 (graph_darts E1) r2 d) = FST d`,
  REPEAT GEN_TAC THEN INTRO_TAC "rotation1 rotation2" THEN
  REWRITE_TAC[GRAPH_DARTS_UNION] THEN
  MATCH_MP_TAC(ISPECL
   [`r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
    `graph_darts E1:A#A->bool`; `graph_darts E2:A#A->bool`;
    `FST:A#A->A`]
   DISJOINT_PERMUTATION_UNION_PRESERVES_KEY) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`E1:(A->bool)->bool`; `r1:(A#A)->A#A`]
     GRAPH_ROTATION_TAIL_ALL) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`E2:(A->bool)->bool`; `r2:(A#A)->A#A`]
     GRAPH_ROTATION_TAIL_ALL) THEN ASM_REWRITE_TAC[]]);;

let DISJOINT_UNION_GRAPH_ROTATION_ORBIT_LEFT = prove
 (`!E:(A->bool)->bool. !r g:(A#A)->A#A. !x y:A#A.
        graph_rotation E r /\
        x IN graph_darts E /\
        y IN graph_darts E /\
        FST x = FST y
        ==> y IN permutation_orbit
                 (disjoint_permutation_union r (graph_darts E) g) x`,
  REPEAT GEN_TAC THEN INTRO_TAC "rotation x_dart y_dart same_tail" THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`E:(A->bool)->bool`; `r:(A#A)->A#A`; `x:A#A`; `y:A#A`]
    GRAPH_ROTATION_ORBIT)
   (end_itlist CONJ
    [ASSUME `graph_rotation E (r:(A#A)->A#A)`;
     ASSUME `(x:A#A) IN graph_darts E`;
     ASSUME `(y:A#A) IN graph_darts E`])) THEN
  DISCH_THEN(fun th ->
   MP_TAC(EQ_MP (SYM th) (SYM(ASSUME `FST(x:A#A) = FST(y:A#A)`)))) THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "old_step")) THEN
  REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN EXISTS_TAC `n:num` THEN
  MATCH_ACCEPT_TAC
   (TRANS
    (CONJUNCT1
     (SPEC `n:num`
      (MATCH_MP
       (ISPECL
        [`r:(A#A)->A#A`; `g:(A#A)->A#A`;
         `graph_darts E:A#A->bool`; `x:A#A`]
        DISJOINT_PERMUTATION_UNION_ITER_LEFT)
       (CONJ
        (MATCH_MP GRAPH_ROTATION_PERMUTES
         (ASSUME `graph_rotation E (r:(A#A)->A#A)`))
        (ASSUME `(x:A#A) IN graph_darts E`)))))
    (ASSUME `ITER n (r:(A#A)->A#A) x = y`)));;

let DISJOINT_UNION_GRAPH_ROTATION_ORBIT_RIGHT = prove
 (`!E:(A->bool)->bool. !r g:(A#A)->A#A. !s:(A#A)->bool.
   !x y:A#A.
        graph_rotation E g /\
        DISJOINT s (graph_darts E) /\
        x IN graph_darts E /\
        y IN graph_darts E /\
        FST x = FST y
        ==> y IN permutation_orbit
                 (disjoint_permutation_union r s g) x`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "rotation disjoint x_dart y_dart same_tail" THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`E:(A->bool)->bool`; `g:(A#A)->A#A`; `x:A#A`; `y:A#A`]
    GRAPH_ROTATION_ORBIT)
   (end_itlist CONJ
    [ASSUME `graph_rotation E (g:(A#A)->A#A)`;
     ASSUME `(x:A#A) IN graph_darts E`;
     ASSUME `(y:A#A) IN graph_darts E`])) THEN
  DISCH_THEN(fun th ->
   MP_TAC(EQ_MP (SYM th) (SYM(ASSUME `FST(x:A#A) = FST(y:A#A)`)))) THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` (LABEL_TAC "old_step")) THEN
  REWRITE_TAC[IN_PERMUTATION_ORBIT] THEN EXISTS_TAC `n:num` THEN
  MATCH_ACCEPT_TAC
   (TRANS
    (CONJUNCT1
     (SPEC `n:num`
      (MATCH_MP
       (ISPECL
        [`r:(A#A)->A#A`; `g:(A#A)->A#A`;
         `s:A#A->bool`; `graph_darts E:A#A->bool`; `x:A#A`]
        DISJOINT_PERMUTATION_UNION_ITER_RIGHT)
       (end_itlist CONJ
        [MATCH_MP GRAPH_ROTATION_PERMUTES
          (ASSUME `graph_rotation E (g:(A#A)->A#A)`);
         ASSUME `DISJOINT (s:A#A->bool) (graph_darts E)`;
         ASSUME `(x:A#A) IN graph_darts E`]))))
    (ASSUME `ITER n (g:(A#A)->A#A) x = y`)));;

let FINITE_SIMPLE_GRAPH_SINGLETON_INTER_DARTS_SHARED_TAIL = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u:A. !d d':A#A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        V1 INTER V2 = {u} /\
        d IN graph_darts E1 /\
        d' IN graph_darts E2 /\
        FST d = FST d'
        ==> FST d = u /\ FST d' = u`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph1 graph2 overlap d_dart dprime_dart same_tail" THEN
  SUBGOAL_THEN `(FST(d:A#A)) IN V1` (LABEL_TAC "tail_vertex1") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `E1:(A->bool)->bool`; `d:A#A`]
     FINITE_SIMPLE_GRAPH_DART_FST) THEN
    CONJ_TAC THENL
     [USE_THEN "graph1" ACCEPT_TAC;
      USE_THEN "d_dart" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(FST(d:A#A)) IN V2` (LABEL_TAC "tail_vertex2") THENL
   [USE_THEN "same_tail" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(ISPECL
     [`V2:A->bool`; `E2:(A->bool)->bool`; `d':A#A`]
     FINITE_SIMPLE_GRAPH_DART_FST) THEN
    CONJ_TAC THENL
     [USE_THEN "graph2" ACCEPT_TAC;
      USE_THEN "dprime_dart" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `FST(d:A#A) = u` (LABEL_TAC "d_tail") THENL
   [USE_THEN "overlap" MP_TAC THEN
    REWRITE_TAC[EXTENSION; IN_INTER; IN_SING] THEN
    DISCH_THEN(MP_TAC o SPEC `FST(d:A#A)`) THEN
    ASM_REWRITE_TAC[];
    CONJ_TAC THENL
     [USE_THEN "d_tail" ACCEPT_TAC;
      TRANS_TAC EQ_TRANS `FST(d:A#A)` THEN CONJ_TAC THENL
       [USE_THEN "same_tail" (ACCEPT_TAC o SYM);
        USE_THEN "d_tail" ACCEPT_TAC]]]);;

let PERMUTATION_ORBIT_EQ_ON_PERMUTED_SET = prove
 (`!f g:A->A. !s x.
        f permutes s /\
        x IN s /\
        (!z. z IN s ==> g z = f z)
        ==> permutation_orbit g x = permutation_orbit f x`,
  REPEAT GEN_TAC THEN INTRO_TAC "permutation member agreement" THEN
  MATCH_MP_TAC(ISPECL [`f:A->A`; `g:A->A`; `x:A`]
   PERMUTATION_ORBIT_EQ_IF_AGREE) THEN
  X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_orbit") THEN
  USE_THEN "agreement" (MATCH_MP_TAC o SPEC `z:A`) THEN
  MP_TAC(MATCH_MP
   (ISPECL [`f:A->A`; `s:A->bool`; `x:A`]
    PERMUTATION_ORBIT_SUBSET)
   (CONJ
    (ASSUME `(f:A->A) permutes s`)
    (ASSUME `(x:A) IN s`))) THEN
  REWRITE_TAC[SUBSET] THEN
  DISCH_THEN(MATCH_MP_TAC o SPEC `z:A`) THEN
  USE_THEN "z_orbit" ACCEPT_TAC);;

let GRAPH_ROTATION_SINGLETON_AMALGAMATION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u:A. !a b:A#A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        V1 INTER V2 = {u} /\
        a IN outgoing_darts E1 u /\
        b IN outgoing_darts E2 u
        ==> graph_rotation
             (E1 UNION E2)
             (swap(a,b) o
              disjoint_permutation_union r1 (graph_darts E1) r2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph1 graph2 rotation1 rotation2 overlap a_outgoing b_outgoing" THEN
  ABBREV_TAC
   `p:(A#A)->A#A =
      disjoint_permutation_union
       (r1:(A#A)->A#A) (graph_darts E1) r2` THEN
  SUBGOAL_THEN
   `(p:(A#A)->A#A) =
    disjoint_permutation_union r1 (graph_darts E1) r2`
  (LABEL_TAC "p_definition") THENL
   [EXPAND_TAC "p" THEN REFL_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(graph_darts E1:A#A->bool) /\
    FINITE(graph_darts E2:A#A->bool)`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_darts1")
    (LABEL_TAC "finite_darts2")) THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `E1:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
       [`V2:A->bool`; `E2:(A->bool)->bool`] FINITE_GRAPH_DARTS) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `DISJOINT (graph_darts E1:A#A->bool) (graph_darts E2)`
  (LABEL_TAC "darts_disjoint") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`]
     FINITE_SIMPLE_GRAPH_SINGLETON_INTER_DARTS_DISJOINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:(A#A)->A#A) permutes graph_darts (E1 UNION E2)`
  (LABEL_TAC "p_permutation") THENL
   [USE_THEN "p_definition" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[GRAPH_DARTS_UNION] THEN
    MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_PERMUTES THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
    MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(a:A#A) IN graph_darts E1 /\
    FST a = u /\
    (b:A#A) IN graph_darts E2 /\
    FST b = u`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_dart")
    (CONJUNCTS_THEN2 (LABEL_TAC "a_tail")
      (CONJUNCTS_THEN2 (LABEL_TAC "b_dart")
        (LABEL_TAC "b_tail")))) THENL
   [USE_THEN "a_outgoing" MP_TAC THEN
    USE_THEN "b_outgoing" MP_TAC THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(a:A#A) IN graph_darts (E1 UNION E2) /\
    (b:A#A) IN graph_darts (E1 UNION E2)`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_union") (LABEL_TAC "b_union")) THENL
   [ASM_REWRITE_TAC[GRAPH_DARTS_UNION; IN_UNION];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(graph_darts (E1 UNION E2):A#A->bool)`
  (LABEL_TAC "finite_union_darts") THENL
   [ASM_REWRITE_TAC[GRAPH_DARTS_UNION; FINITE_UNION];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(permutation_orbit (p:(A#A)->A#A) a =
      permutation_orbit p b)`
  (LABEL_TAC "anchor_orbits_distinct") THENL
   [USE_THEN "p_definition" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(ISPECL
     [`r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
      `graph_darts E1:A#A->bool`; `graph_darts E2:A#A->bool`;
      `a:A#A`; `b:A#A`]
     PERMUTATION_ORBIT_DISJOINT_UNION_DISTINCT) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
    MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[graph_rotation] THEN REPEAT CONJ_TAC THENL
   [MATCH_ACCEPT_TAC
     (MATCH_MP
       (ISPECL
        [`p:(A#A)->A#A`; `graph_darts (E1 UNION E2):A#A->bool`;
         `a:A#A`; `b:A#A`]
        PERMUTATION_SWAP_PERMUTES)
       (end_itlist CONJ
        [ASSUME
         `(p:(A#A)->A#A) permutes graph_darts (E1 UNION E2)`;
         ASSUME `(a:A#A) IN graph_darts (E1 UNION E2)`;
         ASSUME `(b:A#A) IN graph_darts (E1 UNION E2)`]));
    X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "d_union") THEN
    REWRITE_TAC[o_THM] THEN
    TRANS_TAC EQ_TRANS `FST((p:(A#A)->A#A) d)` THEN CONJ_TAC THENL
     [MATCH_ACCEPT_TAC
       (MATCH_MP
        (ISPECL
         [`FST:A#A->A`; `a:A#A`; `b:A#A`; `(p:(A#A)->A#A) d`]
         SWAP_PRESERVES_KEY)
        (TRANS
         (ASSUME `FST(a:A#A) = u`)
         (SYM(ASSUME `FST(b:A#A) = u`))));
      USE_THEN "p_definition" (fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(MATCH_MP
       (ISPECL
        [`E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
         `r1:(A#A)->A#A`; `r2:(A#A)->A#A`]
        DISJOINT_GRAPH_ROTATION_TAIL)
       (CONJ
        (ASSUME `graph_rotation E1 (r1:(A#A)->A#A)`)
        (ASSUME `graph_rotation E2 (r2:(A#A)->A#A)`))) THEN
      DISCH_THEN(MP_TAC o SPEC `d:A#A`) THEN
      DISCH_THEN MATCH_MP_TAC THEN USE_THEN "d_union" ACCEPT_TAC];
    MAP_EVERY X_GEN_TAC [`d:A#A`; `d':A#A`] THEN
    INTRO_TAC "d_union dprime_union same_tail" THEN
    REWRITE_TAC[GSYM IN_PERMUTATION_ORBIT] THEN
    MATCH_MP_TAC(ISPECL
     [`p:(A#A)->A#A`; `graph_darts (E1 UNION E2):A#A->bool`;
      `a:A#A`; `b:A#A`; `d:A#A`; `d':A#A`]
     PERMUTATION_SWAP_PRESERVES_OR_MERGES_ORBIT) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "finite_union_darts" ACCEPT_TAC;
      USE_THEN "p_permutation" ACCEPT_TAC;
      USE_THEN "a_union" ACCEPT_TAC;
      USE_THEN "b_union" ACCEPT_TAC;
      USE_THEN "d_union" ACCEPT_TAC;
      USE_THEN "dprime_union" ACCEPT_TAC;
      USE_THEN "anchor_orbits_distinct" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "d_union"
     (DISJ_CASES_THEN2 (LABEL_TAC "d_left") (LABEL_TAC "d_right") o
      REWRITE_RULE[GRAPH_DARTS_UNION; IN_UNION]) THEN
    USE_THEN "dprime_union"
     (DISJ_CASES_THEN2
       (LABEL_TAC "dprime_left") (LABEL_TAC "dprime_right") o
      REWRITE_RULE[GRAPH_DARTS_UNION; IN_UNION]) THENL
     [DISJ1_TAC THEN
      USE_THEN "p_definition" (fun th -> REWRITE_TAC[th]) THEN
      MATCH_ACCEPT_TAC(MATCH_MP
       (ISPECL
        [`E1:(A->bool)->bool`; `r1:(A#A)->A#A`;
         `r2:(A#A)->A#A`; `d:A#A`; `d':A#A`]
        DISJOINT_UNION_GRAPH_ROTATION_ORBIT_LEFT)
       (end_itlist CONJ
        [ASSUME `graph_rotation E1 (r1:(A#A)->A#A)`;
         ASSUME `(d:A#A) IN graph_darts E1`;
         ASSUME `(d':A#A) IN graph_darts E1`;
         ASSUME `FST(d:A#A) = FST(d':A#A)`]));
      MP_TAC(MATCH_MP
       (ISPECL
        [`V1:A->bool`; `V2:A->bool`;
         `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
         `u:A`; `d:A#A`; `d':A#A`]
        FINITE_SIMPLE_GRAPH_SINGLETON_INTER_DARTS_SHARED_TAIL)
       (end_itlist CONJ
        [ASSUME `finite_simple_graph (V1:A->bool) E1`;
         ASSUME `finite_simple_graph (V2:A->bool) E2`;
         ASSUME `(V1:A->bool) INTER V2 = {u}`;
         ASSUME `(d:A#A) IN graph_darts E1`;
         ASSUME `(d':A#A) IN graph_darts E2`;
         ASSUME `FST(d:A#A) = FST(d':A#A)`])) THEN
      INTRO_TAC "d_tail dprime_tail" THEN
      DISJ2_TAC THEN CONJ_TAC THENL
       [DISJ1_TAC THEN
        USE_THEN "p_definition" (fun th -> REWRITE_TAC[th]) THEN
        MATCH_ACCEPT_TAC(MATCH_MP
         (ISPECL
          [`E1:(A->bool)->bool`; `r1:(A#A)->A#A`;
           `r2:(A#A)->A#A`; `a:A#A`; `d:A#A`]
          DISJOINT_UNION_GRAPH_ROTATION_ORBIT_LEFT)
         (end_itlist CONJ
          [ASSUME `graph_rotation E1 (r1:(A#A)->A#A)`;
           ASSUME `(a:A#A) IN graph_darts E1`;
           ASSUME `(d:A#A) IN graph_darts E1`;
           TRANS (ASSUME `FST(a:A#A) = u`)
                 (SYM(ASSUME `FST(d:A#A) = u`))]));
        DISJ2_TAC THEN
        USE_THEN "p_definition" (fun th -> REWRITE_TAC[th]) THEN
        MATCH_ACCEPT_TAC(MATCH_MP
         (ISPECL
          [`E2:(A->bool)->bool`; `r1:(A#A)->A#A`;
           `r2:(A#A)->A#A`; `graph_darts E1:A#A->bool`;
           `b:A#A`; `d':A#A`]
          DISJOINT_UNION_GRAPH_ROTATION_ORBIT_RIGHT)
         (end_itlist CONJ
          [ASSUME `graph_rotation E2 (r2:(A#A)->A#A)`;
           ASSUME
            `DISJOINT (graph_darts E1:A#A->bool) (graph_darts E2)`;
           ASSUME `(b:A#A) IN graph_darts E2`;
           ASSUME `(d':A#A) IN graph_darts E2`;
           TRANS (ASSUME `FST(b:A#A) = u`)
                 (SYM(ASSUME `FST(d':A#A) = u`))]))];
      MP_TAC(MATCH_MP
       (ISPECL
        [`V1:A->bool`; `V2:A->bool`;
         `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
         `u:A`; `d':A#A`; `d:A#A`]
        FINITE_SIMPLE_GRAPH_SINGLETON_INTER_DARTS_SHARED_TAIL)
       (end_itlist CONJ
        [ASSUME `finite_simple_graph (V1:A->bool) E1`;
         ASSUME `finite_simple_graph (V2:A->bool) E2`;
         ASSUME `(V1:A->bool) INTER V2 = {u}`;
         ASSUME `(d':A#A) IN graph_darts E1`;
         ASSUME `(d:A#A) IN graph_darts E2`;
         SYM(ASSUME `FST(d:A#A) = FST(d':A#A)`)])) THEN
      INTRO_TAC "dprime_tail d_tail" THEN
      DISJ2_TAC THEN CONJ_TAC THENL
       [DISJ2_TAC THEN
        USE_THEN "p_definition" (fun th -> REWRITE_TAC[th]) THEN
        MATCH_ACCEPT_TAC(MATCH_MP
         (ISPECL
          [`E2:(A->bool)->bool`; `r1:(A#A)->A#A`;
           `r2:(A#A)->A#A`; `graph_darts E1:A#A->bool`;
           `b:A#A`; `d:A#A`]
          DISJOINT_UNION_GRAPH_ROTATION_ORBIT_RIGHT)
         (end_itlist CONJ
          [ASSUME `graph_rotation E2 (r2:(A#A)->A#A)`;
           ASSUME
            `DISJOINT (graph_darts E1:A#A->bool) (graph_darts E2)`;
           ASSUME `(b:A#A) IN graph_darts E2`;
           ASSUME `(d:A#A) IN graph_darts E2`;
           TRANS (ASSUME `FST(b:A#A) = u`)
                 (SYM(ASSUME `FST(d:A#A) = u`))]));
        DISJ1_TAC THEN
        USE_THEN "p_definition" (fun th -> REWRITE_TAC[th]) THEN
        MATCH_ACCEPT_TAC(MATCH_MP
         (ISPECL
          [`E1:(A->bool)->bool`; `r1:(A#A)->A#A`;
           `r2:(A#A)->A#A`; `a:A#A`; `d':A#A`]
          DISJOINT_UNION_GRAPH_ROTATION_ORBIT_LEFT)
         (end_itlist CONJ
          [ASSUME `graph_rotation E1 (r1:(A#A)->A#A)`;
           ASSUME `(a:A#A) IN graph_darts E1`;
           ASSUME `(d':A#A) IN graph_darts E1`;
           TRANS (ASSUME `FST(a:A#A) = u`)
                 (SYM(ASSUME `FST(d':A#A) = u`))]))];
      DISJ1_TAC THEN
      USE_THEN "p_definition" (fun th -> REWRITE_TAC[th]) THEN
      MATCH_ACCEPT_TAC(MATCH_MP
       (ISPECL
        [`E2:(A->bool)->bool`; `r1:(A#A)->A#A`;
         `r2:(A#A)->A#A`; `graph_darts E1:A#A->bool`;
         `d:A#A`; `d':A#A`]
        DISJOINT_UNION_GRAPH_ROTATION_ORBIT_RIGHT)
       (end_itlist CONJ
        [ASSUME `graph_rotation E2 (r2:(A#A)->A#A)`;
         ASSUME
          `DISJOINT (graph_darts E1:A#A->bool) (graph_darts E2)`;
         ASSUME `(d:A#A) IN graph_darts E2`;
         ASSUME `(d':A#A) IN graph_darts E2`;
         ASSUME `FST(d:A#A) = FST(d':A#A)`]))]]);;

let CARD_GRAPH_FACES_SINGLETON_AMALGAMATION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u:A. !a b:A#A.
        finite_simple_graph V1 E1 /\
        finite_simple_graph V2 E2 /\
        graph_rotation E1 r1 /\
        graph_rotation E2 r2 /\
        V1 INTER V2 = {u} /\
        a IN outgoing_darts E1 u /\
        b IN outgoing_darts E2 u
        ==> CARD
             (graph_faces
               (E1 UNION E2)
               (swap(a,b) o
                disjoint_permutation_union r1 (graph_darts E1) r2)) + 1 =
            CARD(graph_faces E1 r1) + CARD(graph_faces E2 r2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph1 graph2 rotation1 rotation2 overlap a_outgoing b_outgoing" THEN
  ABBREV_TAC
   `p:(A#A)->A#A =
      disjoint_permutation_union
       (r1:(A#A)->A#A) (graph_darts E1) r2` THEN
  SUBGOAL_THEN
   `(p:(A#A)->A#A) =
    disjoint_permutation_union r1 (graph_darts E1) r2`
  (LABEL_TAC "p_definition") THENL
   [EXPAND_TAC "p" THEN REFL_TAC;
    ALL_TAC] THEN
  ABBREV_TAC
   `q:(A#A)->A#A = graph_face_successor (E1 UNION E2) p` THEN
  SUBGOAL_THEN
   `(q:(A#A)->A#A) = graph_face_successor (E1 UNION E2) p`
  (LABEL_TAC "q_definition") THENL
   [EXPAND_TAC "q" THEN REFL_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `DISJOINT (graph_darts E1:A#A->bool) (graph_darts E2)`
  (LABEL_TAC "disjoint_darts") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`]
     FINITE_SIMPLE_GRAPH_SINGLETON_INTER_DARTS_DISJOINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(graph_darts E1:A#A->bool) /\
    FINITE(graph_darts E2:A#A->bool)`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_darts1")
    (LABEL_TAC "finite_darts2")) THENL
   [MATCH_ACCEPT_TAC(CONJ
     (MATCH_MP
      (ISPECL [`V1:A->bool`; `E1:(A->bool)->bool`]
       FINITE_GRAPH_DARTS)
      (ASSUME `finite_simple_graph (V1:A->bool) E1`))
     (MATCH_MP
      (ISPECL [`V2:A->bool`; `E2:(A->bool)->bool`]
       FINITE_GRAPH_DARTS)
      (ASSUME `finite_simple_graph (V2:A->bool) E2`)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(graph_darts (E1 UNION E2):A#A->bool)`
  (LABEL_TAC "finite_darts") THENL
   [ASM_REWRITE_TAC[GRAPH_DARTS_UNION; FINITE_UNION];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(p:(A#A)->A#A) permutes graph_darts (E1 UNION E2)`
  (LABEL_TAC "p_permutation") THENL
   [USE_THEN "p_definition" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[GRAPH_DARTS_UNION] THEN
    MATCH_MP_TAC DISJOINT_PERMUTATION_UNION_PERMUTES THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
    MATCH_MP_TAC GRAPH_ROTATION_PERMUTES THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(q:(A#A)->A#A) permutes graph_darts (E1 UNION E2)`
  (LABEL_TAC "q_permutation") THENL
   [USE_THEN "q_definition" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[graph_face_successor] THEN
    MATCH_MP_TAC PERMUTES_COMPOSE THEN CONJ_TAC THENL
     [MATCH_ACCEPT_TAC GRAPH_REVERSE_DART_PERMUTES;
      USE_THEN "p_permutation" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(a:A#A) IN graph_darts E1 /\
    (b:A#A) IN graph_darts E2`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_dart") (LABEL_TAC "b_dart")) THENL
   [CONJ_TAC THENL
     [USE_THEN "a_outgoing" MP_TAC;
      USE_THEN "b_outgoing" MP_TAC] THEN
    REWRITE_TAC[IN_OUTGOING_DARTS] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(a:A#A) IN graph_darts (E1 UNION E2) /\
    (b:A#A) IN graph_darts (E1 UNION E2)`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_union") (LABEL_TAC "b_union")) THENL
   [REWRITE_TAC[GRAPH_DARTS_UNION; IN_UNION] THEN
    CONJ_TAC THENL [DISJ1_TAC; DISJ2_TAC] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC
   `h:(A#A)->A#A =
      disjoint_permutation_union
       (graph_face_successor E1 r1) (graph_darts E1)
       (graph_face_successor E2 r2)` THEN
  SUBGOAL_THEN
   `(h:(A#A)->A#A) =
    disjoint_permutation_union
     (graph_face_successor E1 r1) (graph_darts E1)
     (graph_face_successor E2 r2)`
  (LABEL_TAC "h_definition") THENL
   [EXPAND_TAC "h" THEN REFL_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!d:A#A.
        d IN graph_darts (E1 UNION E2)
        ==> (h:(A#A)->A#A) d = q d`
  (LABEL_TAC "agreement") THENL
   [X_GEN_TAC `d:A#A` THEN DISCH_THEN(LABEL_TAC "d_union") THEN
    USE_THEN "h_definition" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "q_definition" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "p_definition" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_ACCEPT_TAC(SYM
     (MP
      (SPEC `d:A#A`
       (MATCH_MP
        (ISPECL
         [`E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
          `r1:(A#A)->A#A`; `r2:(A#A)->A#A`]
         GRAPH_FACE_SUCCESSOR_DART_DISJOINT_UNION)
        (ASSUME
         `DISJOINT (graph_darts E1:A#A->bool) (graph_darts E2)`)))
      (ASSUME `(d:A#A) IN graph_darts (E1 UNION E2)`)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(permutation_orbit (h:(A#A)->A#A) a =
      permutation_orbit h b)`
  (LABEL_TAC "h_orbits_distinct") THENL
   [USE_THEN "h_definition" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(ISPECL
     [`graph_face_successor E1 r1:(A#A)->A#A`;
      `graph_face_successor E2 r2:(A#A)->A#A`;
      `graph_darts E1:A#A->bool`; `graph_darts E2:A#A->bool`;
      `a:A#A`; `b:A#A`]
     PERMUTATION_ORBIT_DISJOINT_UNION_DISTINCT) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
      USE_THEN "rotation1" ACCEPT_TAC;
      MATCH_MP_TAC GRAPH_FACE_SUCCESSOR_PERMUTES THEN
      USE_THEN "rotation2" ACCEPT_TAC;
      USE_THEN "disjoint_darts" ACCEPT_TAC;
      USE_THEN "a_dart" ACCEPT_TAC;
      USE_THEN "b_dart" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
  `permutation_orbit (h:(A#A)->A#A) a =
      permutation_orbit q a /\
    permutation_orbit h b = permutation_orbit q b`
  (CONJUNCTS_THEN2 (LABEL_TAC "a_orbit") (LABEL_TAC "b_orbit")) THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`q:(A#A)->A#A`; `h:(A#A)->A#A`;
        `graph_darts (E1 UNION E2):A#A->bool`; `a:A#A`]
       PERMUTATION_ORBIT_EQ_ON_PERMUTED_SET) THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "q_permutation" ACCEPT_TAC;
        USE_THEN "a_union" ACCEPT_TAC;
        USE_THEN "agreement" ACCEPT_TAC];
      MATCH_MP_TAC(ISPECL
       [`q:(A#A)->A#A`; `h:(A#A)->A#A`;
        `graph_darts (E1 UNION E2):A#A->bool`; `b:A#A`]
       PERMUTATION_ORBIT_EQ_ON_PERMUTED_SET) THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "q_permutation" ACCEPT_TAC;
        USE_THEN "b_union" ACCEPT_TAC;
        USE_THEN "agreement" ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
  `~(permutation_orbit (q:(A#A)->A#A) a =
      permutation_orbit q b)`
  (LABEL_TAC "q_orbits_distinct") THENL
   [DISCH_THEN(LABEL_TAC "q_orbits_equal") THEN
    USE_THEN "h_orbits_distinct" MP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(permutation_orbits (q:(A#A)->A#A)
          (graph_darts (E1 UNION E2))) =
    CARD(permutation_orbits (swap(a,b) o q)
          (graph_darts (E1 UNION E2))) + 1`
  (LABEL_TAC "merged_count") THENL
   [MATCH_MP_TAC(ISPECL
     [`q:(A#A)->A#A`; `graph_darts (E1 UNION E2):A#A->bool`;
      `a:A#A`; `b:A#A`]
     PERMUTATION_ORBITS_SWAP_DISTINCT) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "finite_darts" ACCEPT_TAC;
      USE_THEN "q_permutation" ACCEPT_TAC;
      USE_THEN "a_union" ACCEPT_TAC;
      USE_THEN "b_union" ACCEPT_TAC;
      USE_THEN "q_orbits_distinct" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
  `CARD
     (graph_faces
       ((E1:(A->bool)->bool) UNION E2)
       (disjoint_permutation_union r1 (graph_darts E1) r2)) =
    CARD(graph_faces E1 r1) + CARD(graph_faces E2 r2)`
  (LABEL_TAC "old_count") THENL
   [USE_THEN "graph1" (fun g1 ->
     USE_THEN "graph2" (fun g2 ->
      USE_THEN "rotation1" (fun r1th ->
       USE_THEN "rotation2" (fun r2th ->
        USE_THEN "disjoint_darts" (fun dth ->
         MATCH_ACCEPT_TAC
          (MATCH_MP CARD_GRAPH_FACES_DART_DISJOINT_UNION
            (end_itlist CONJ [g1; g2; r1th; r2th; dth])))))));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_face_successor (E1 UNION E2) (swap(a,b) o p) =
    swap(a,b) o (q:(A#A)->A#A)`
  (LABEL_TAC "new_successor") THENL
   [USE_THEN "q_definition" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[graph_face_successor; FUN_EQ_THM; o_THM];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(graph_faces (E1 UNION E2) p) =
    CARD(permutation_orbits (q:(A#A)->A#A)
          (graph_darts (E1 UNION E2)))`
  (LABEL_TAC "old_as_orbits") THENL
   [REWRITE_TAC[GRAPH_FACES_AS_PERMUTATION_ORBITS] THEN
    USE_THEN "q_definition" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(graph_faces (E1 UNION E2) (swap(a,b) o p)) =
    CARD(permutation_orbits (swap(a,b) o (q:(A#A)->A#A))
          (graph_darts (E1 UNION E2)))`
  (LABEL_TAC "new_as_orbits") THENL
   [REWRITE_TAC[GRAPH_FACES_AS_PERMUTATION_ORBITS] THEN
    USE_THEN "new_successor" (fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  REMOVE_THEN "old_count" MP_TAC THEN
  REMOVE_THEN "old_as_orbits" MP_TAC THEN
  REMOVE_THEN "new_as_orbits" MP_TAC THEN
  REMOVE_THEN "merged_count" MP_TAC THEN
  USE_THEN "p_definition" (fun th -> REWRITE_TAC[th]) THEN
  ARITH_TAC);;

let EULER_PLANAR_ROTATION_SINGLETON_AMALGAMATION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool.
   !r1 r2:(A#A)->A#A. !u:A. !a b:A#A.
        euler_planar_rotation V1 E1 r1 /\
        euler_planar_rotation V2 E2 r2 /\
        V1 INTER V2 = {u} /\
        a IN outgoing_darts E1 u /\
        b IN outgoing_darts E2 u
        ==> euler_planar_rotation
             (V1 UNION V2)
             (E1 UNION E2)
             (swap(a,b) o
              disjoint_permutation_union r1 (graph_darts E1) r2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "euler1 euler2 overlap a_outgoing b_outgoing" THEN
  USE_THEN "euler1" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph1 rotation1 formula1" THEN
  USE_THEN "euler2" MP_TAC THEN
  REWRITE_TAC[euler_planar_rotation] THEN
  INTRO_TAC "graph2 rotation2 formula2" THEN
  SUBGOAL_THEN
   `~(E1:(A->bool)->bool = {}) /\ ~(E2:(A->bool)->bool = {})`
  (CONJUNCTS_THEN2 (LABEL_TAC "edges1_nonempty")
    (LABEL_TAC "edges2_nonempty")) THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
      EXISTS_TAC `dart_edge(a:A#A)` THEN
      USE_THEN "a_outgoing" MP_TAC;
      REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
      EXISTS_TAC `dart_edge(b:A#A)` THEN
      USE_THEN "b_outgoing" MP_TAC] THEN
    REWRITE_TAC[IN_OUTGOING_DARTS; graph_darts; IN_ELIM_THM] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(E1 UNION E2:(A->bool)->bool = {})`
  (LABEL_TAC "union_nonempty") THENL
   [USE_THEN "edges1_nonempty" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `FINITE(V1:A->bool) /\ FINITE(E1:(A->bool)->bool) /\
    FINITE(V2:A->bool) /\ FINITE(E2:(A->bool)->bool)`
  (CONJUNCTS_THEN2 (LABEL_TAC "finite_v1")
   (CONJUNCTS_THEN2 (LABEL_TAC "finite_e1")
    (CONJUNCTS_THEN2 (LABEL_TAC "finite_v2")
     (LABEL_TAC "finite_e2")))) THENL
   [MAP_EVERY (fun name -> USE_THEN name MP_TAC) ["graph1"; "graph2"] THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `DISJOINT (E1:(A->bool)->bool) E2`
  (LABEL_TAC "edges_disjoint") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`]
     FINITE_SIMPLE_GRAPH_SINGLETON_INTER_EDGES_DISJOINT) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(V1 UNION V2:A->bool) + 1 = CARD V1 + CARD V2`
  (LABEL_TAC "vertex_union_card") THENL
   [MP_TAC(MATCH_MP
     (ISPECL [`V1:A->bool`; `V2:A->bool`]
      CARD_UNION_ADD_INTER_FINITE)
     (CONJ
      (ASSUME `FINITE(V1:A->bool)`)
      (ASSUME `FINITE(V2:A->bool)`))) THEN
    ASM_REWRITE_TAC[CARD_SING];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(E1 UNION E2:(A->bool)->bool) = CARD E1 + CARD E2`
  (LABEL_TAC "edge_union_card") THENL
   [MATCH_MP_TAC CARD_UNION THEN
    ASM_REWRITE_TAC[GSYM DISJOINT];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(V1:A->bool) +
    CARD(graph_faces (E1:(A->bool)->bool) (r1:(A#A)->A#A)) =
    CARD(E1:(A->bool)->bool) + 2`
  (LABEL_TAC "euler_faces1") THENL
   [USE_THEN "formula1" MP_TAC THEN
    REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(V2:A->bool) +
    CARD(graph_faces (E2:(A->bool)->bool) (r2:(A#A)->A#A)) =
    CARD(E2:(A->bool)->bool) + 2`
  (LABEL_TAC "euler_faces2") THENL
   [USE_THEN "formula2" MP_TAC THEN
    REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD
     (graph_faces
       (E1 UNION E2:(A->bool)->bool)
       (swap(a,b) o
        disjoint_permutation_union r1 (graph_darts E1) r2)) + 1 =
    CARD(graph_faces E1 r1) + CARD(graph_faces E2 r2)`
  (LABEL_TAC "faces_card") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
      `u:A`; `a:A#A`; `b:A#A`]
     CARD_GRAPH_FACES_SINGLETON_AMALGAMATION) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[euler_planar_rotation] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_UNION THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
      `u:A`; `a:A#A`; `b:A#A`]
     GRAPH_ROTATION_SINGLETON_AMALGAMATION) THEN
    ASM_REWRITE_TAC[];
    REWRITE_TAC[graph_euler_formula; graph_map_faces] THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]);;

let CONNECTED_GRAPH_NONEMPTY_EDGE_OUTGOING_DART = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u:A.
        finite_simple_graph V E /\
        connected_graph V E /\
        u IN V /\
        ~(E = {})
        ==> ?d:A#A. d IN outgoing_darts E u`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected vertex edges_nonempty" THEN
  SUBGOAL_THEN `{u:A} SUBSET V` (LABEL_TAC "singleton_subset") THENL
   [ASM_REWRITE_TAC[SING_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN `~({u:A} = V)` (LABEL_TAC "singleton_proper") THENL
   [DISCH_THEN(LABEL_TAC "singleton") THEN
    USE_THEN "edges_nonempty" (MATCH_MP_TAC o NOT_ELIM) THEN
    MATCH_MP_TAC(ISPECL
     [`E:(A->bool)->bool`; `u:A`]
     FINITE_SIMPLE_GRAPH_SINGLETON_EDGES_EMPTY) THEN
    USE_THEN "graph" MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`V:A->bool`; `E:(A->bool)->bool`; `{u:A}:A->bool`; `u:A`]
    CONNECTED_GRAPH_CROSSING_EDGE)
   (end_itlist CONJ
    [ASSUME `finite_simple_graph (V:A->bool) E`;
     ASSUME `connected_graph (V:A->bool) E`;
     ASSUME `{u:A} SUBSET V`;
     SET_RULE `(u:A) IN {u}`;
     ASSUME `~({u:A} = V)`])) THEN
  DISCH_THEN(X_CHOOSE_THEN `x:A`
   (X_CHOOSE_THEN `y:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "x_outside")
     (CONJUNCTS_THEN2 (LABEL_TAC "y_singleton")
      (LABEL_TAC "edge"))))) THEN
  EXISTS_TAC `(u:A,x:A)` THEN
  REWRITE_TAC[IN_OUTGOING_DARTS_PAIR] THEN
  USE_THEN "y_singleton" MP_TAC THEN
  REWRITE_TAC[IN_SING] THEN DISCH_THEN SUBST_ALL_TAC THEN
  SUBGOAL_THEN `{u:A,x} = {x,u}` SUBST1_TAC THENL
   [SET_TAC[];
    USE_THEN "edge" ACCEPT_TAC]);;

let EULER_PLANAR_GRAPH_SINGLETON_AMALGAMATION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u:A.
        euler_planar_graph V1 E1 /\
        connected_graph V1 E1 /\
        euler_planar_graph V2 E2 /\
        connected_graph V2 E2 /\
        V1 INTER V2 = {u}
        ==> euler_planar_graph (V1 UNION V2) (E1 UNION E2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "euler1 connected1 euler2 connected2 overlap" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V1:A->bool) E1 /\
    finite_simple_graph (V2:A->bool) E2`
  (CONJUNCTS_THEN2 (LABEL_TAC "graph1") (LABEL_TAC "graph2")) THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC EULER_PLANAR_GRAPH_FINITE_SIMPLE THEN
      USE_THEN "euler1" ACCEPT_TAC;
      MATCH_MP_TAC EULER_PLANAR_GRAPH_FINITE_SIMPLE THEN
      USE_THEN "euler2" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(u:A) IN V1 /\ u IN V2`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex1")
    (LABEL_TAC "u_vertex2")) THENL
   [MATCH_ACCEPT_TAC(MATCH_MP
     (SET_RULE
      `(V1:A->bool) INTER V2 = {u}
       ==> u IN V1 /\ u IN V2`)
     (ASSUME `(V1:A->bool) INTER V2 = {u}`));
    ALL_TAC] THEN
  ASM_CASES_TAC `E1:(A->bool)->bool = {}` THENL
   [SUBGOAL_THEN `V1:A->bool = {u}` (LABEL_TAC "vertices1") THENL
     [MATCH_MP_TAC(ISPECL
       [`V1:A->bool`; `u:A`] CONNECTED_GRAPH_EMPTY_EDGES_SINGLETON) THEN
      CONJ_TAC THENL
       [MATCH_ACCEPT_TAC(SUBS
         [ASSUME `E1:(A->bool)->bool = {}`]
         (ASSUME `connected_graph (V1:A->bool) E1`));
        USE_THEN "u_vertex1" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `V1 UNION V2:A->bool = V2`
    (LABEL_TAC "vertices_union1") THENL
     [MATCH_ACCEPT_TAC(MATCH_MP
       (SET_RULE
        `(V1:A->bool) = {u} /\ u IN V2 ==> V1 UNION V2 = V2`)
       (CONJ
        (ASSUME `(V1:A->bool) = {u}`)
        (ASSUME `(u:A) IN V2`)));
      ALL_TAC] THEN
    USE_THEN "vertices_union1" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[ASSUME `E1:(A->bool)->bool = {}`; UNION_EMPTY] THEN
    USE_THEN "euler2" ACCEPT_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `E2:(A->bool)->bool = {}` THENL
   [SUBGOAL_THEN `V2:A->bool = {u}` (LABEL_TAC "vertices2") THENL
     [MATCH_MP_TAC(ISPECL
       [`V2:A->bool`; `u:A`] CONNECTED_GRAPH_EMPTY_EDGES_SINGLETON) THEN
      CONJ_TAC THENL
       [MATCH_ACCEPT_TAC(SUBS
         [ASSUME `E2:(A->bool)->bool = {}`]
         (ASSUME `connected_graph (V2:A->bool) E2`));
        USE_THEN "u_vertex2" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `V1 UNION V2:A->bool = V1`
    (LABEL_TAC "vertices_union2") THENL
     [MATCH_ACCEPT_TAC(MATCH_MP
       (SET_RULE
        `(V2:A->bool) = {u} /\ u IN V1 ==> V1 UNION V2 = V1`)
       (CONJ
        (ASSUME `(V2:A->bool) = {u}`)
        (ASSUME `(u:A) IN V1`)));
      ALL_TAC] THEN
    USE_THEN "vertices_union2" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[ASSUME `E2:(A->bool)->bool = {}`; UNION_EMPTY] THEN
    USE_THEN "euler1" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`V1:A->bool`; `E1:(A->bool)->bool`; `u:A`]
    CONNECTED_GRAPH_NONEMPTY_EDGE_OUTGOING_DART)
   (end_itlist CONJ
    [ASSUME `finite_simple_graph (V1:A->bool) E1`;
     ASSUME `connected_graph (V1:A->bool) E1`;
     ASSUME `(u:A) IN V1`;
     ASSUME `~(E1:(A->bool)->bool = {})`])) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A#A` (LABEL_TAC "a_outgoing")) THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`V2:A->bool`; `E2:(A->bool)->bool`; `u:A`]
    CONNECTED_GRAPH_NONEMPTY_EDGE_OUTGOING_DART)
   (end_itlist CONJ
    [ASSUME `finite_simple_graph (V2:A->bool) E2`;
     ASSUME `connected_graph (V2:A->bool) E2`;
     ASSUME `(u:A) IN V2`;
     ASSUME `~(E2:(A->bool)->bool = {})`])) THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A#A` (LABEL_TAC "b_outgoing")) THEN
  MP_TAC(MATCH_MP
   (ISPECL [`V1:A->bool`; `E1:(A->bool)->bool`; `u:A`]
    EULER_PLANAR_GRAPH_CONNECTED)
   (end_itlist CONJ
    [ASSUME `euler_planar_graph (V1:A->bool) E1`;
     ASSUME `connected_graph (V1:A->bool) E1`;
     ASSUME `(u:A) IN V1`])) THEN
  DISCH_THEN(X_CHOOSE_THEN `r1:(A#A)->A#A`
    (LABEL_TAC "rotation1")) THEN
  MP_TAC(MATCH_MP
   (ISPECL [`V2:A->bool`; `E2:(A->bool)->bool`; `u:A`]
    EULER_PLANAR_GRAPH_CONNECTED)
   (end_itlist CONJ
    [ASSUME `euler_planar_graph (V2:A->bool) E2`;
     ASSUME `connected_graph (V2:A->bool) E2`;
     ASSUME `(u:A) IN V2`])) THEN
  DISCH_THEN(X_CHOOSE_THEN `r2:(A#A)->A#A`
    (LABEL_TAC "rotation2")) THEN
  SUBGOAL_THEN
   `euler_planar_rotation
     (V1 UNION V2:A->bool) (E1 UNION E2)
     (swap(a,b) o
      disjoint_permutation_union r1 (graph_darts E1) r2)`
  (LABEL_TAC "union_rotation") THENL
   [MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`;
      `r1:(A#A)->A#A`; `r2:(A#A)->A#A`;
      `u:A`; `a:A#A`; `b:A#A`]
     EULER_PLANAR_ROTATION_SINGLETON_AMALGAMATION) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
   [`V1 UNION V2:A->bool`; `E1 UNION E2:(A->bool)->bool`;
    `swap(a,b) o
     disjoint_permutation_union
      (r1:(A#A)->A#A) (graph_darts E1) r2`]
   CONNECTED_EULER_PLANAR_ROTATION_IMP_GRAPH) THEN
  CONJ_TAC THENL
   [USE_THEN "union_rotation" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`V1:A->bool`; `V2:A->bool`;
      `E1:(A->bool)->bool`; `E2:(A->bool)->bool`; `u:A`]
     CONNECTED_GRAPH_UNION_SHARED_VERTEX) THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Separator reduction for Kuratowski's theorem.                             *)
(* ------------------------------------------------------------------------- *)

(* ------------------------------------------------------------------------- *)
(* Small graphs and elementary connected graphs.                             *)
(* ------------------------------------------------------------------------- *)

let FINITE_SIMPLE_GRAPH_CARD_LE_3_EULER_PLANAR = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        finite_simple_graph V E /\ CARD V <= 3
        ==> euler_planar_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph small" THEN
  ASM_CASES_TAC `CARD(V:A->bool) <= 2` THENL
   [MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`]
      EULER_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC FINITE_SIMPLE_GRAPH_CARD_LE_2_IMP_STRAIGHT_LINE_PLANAR THEN
    ASM_REWRITE_TAC[];
    SUBGOAL_THEN `CARD(V:A->bool) = 3` (LABEL_TAC "card") THENL
     [ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(V:A->bool) HAS_SIZE 3` MP_TAC THENL
     [REWRITE_TAC[HAS_SIZE] THEN CONJ_TAC THENL
       [USE_THEN "graph" MP_TAC THEN
        REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
        USE_THEN "card" ACCEPT_TAC];
      REWRITE_TAC[HAS_SIZE_CONV `(V:A->bool) HAS_SIZE 3`] THEN
      INTRO_TAC "@a b c. bc ab ac vertices"] THEN
    ABBREV_TAC
     `q:num->A = \i. if i = 0 then a else if i = 1 then b else c` THEN
    SUBGOAL_THEN `(q:num->A) 0 = a /\ q 1 = b /\ q 2 = c`
    (CONJUNCTS_THEN2 (LABEL_TAC "q0")
      (CONJUNCTS_THEN2 (LABEL_TAC "q1") (LABEL_TAC "q2"))) THENL
     [EXPAND_TAC "q" THEN CONV_TAC NUM_REDUCE_CONV;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `euler_planar_rotation
       (V:A->bool) (complete_graph_edges V) (triangle_rotation a b c)`
    (LABEL_TAC "rotation") THENL
     [USE_THEN "vertices" SUBST1_TAC THEN
      MP_TAC(ISPECL [`a:A`; `b:A`; `c:A`]
       EULER_PLANAR_TRIANGLE_ROTATION) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(LABEL_TAC "triangle") THEN
      SUBGOAL_THEN
       `complete_graph_edges ({a:A,b,c}:A->bool) =
        {{a,b},{b,c},{c,a}}`
      (LABEL_TAC "complete") THENL
       [MATCH_MP_TAC COMPLETE_GRAPH_EDGES_3 THEN
        ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      USE_THEN "complete" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "triangle" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `connected_graph (V:A->bool) (complete_graph_edges V)`
    (LABEL_TAC "connected") THENL
     [USE_THEN "vertices" SUBST1_TAC THEN
      SUBGOAL_THEN
       `complete_graph_edges ({a:A,b,c}:A->bool) =
        cyclic_edges (q:num->A) 3`
      SUBST1_TAC THENL
       [MATCH_MP_TAC EQ_TRANS THEN
        EXISTS_TAC `{{a:A,b},{b,c},{c,a}}` THEN
        CONJ_TAC THENL
         [MATCH_MP_TAC COMPLETE_GRAPH_EDGES_3 THEN
          ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
          ASM_REWRITE_TAC[CYCLIC_EDGES_3]];
        SUBGOAL_THEN
         `({a:A,b,c}:A->bool) = cyclic_vertices (q:num->A) 3`
        SUBST1_TAC THENL
         [ASM_REWRITE_TAC[CYCLIC_VERTICES_3];
          MATCH_MP_TAC CYCLIC_GRAPH_CONNECTED THEN ARITH_TAC]];
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `complete_graph_edges (V:A->bool)`;
      `E:(A->bool)->bool`] EULER_PLANAR_GRAPH_SUBSET_EDGES) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `complete_graph_edges (V:A->bool)`;
        `triangle_rotation (a:A) b c`]
       CONNECTED_EULER_PLANAR_ROTATION_IMP_GRAPH) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[FINITE_SIMPLE_GRAPH_EQ] THEN MESON_TAC[]]]);;

let GRAPH_EDGE_CONNECTED_PAIR = prove
 (`!E:(A->bool)->bool. !u v:A.
        {u,v} IN E ==> connected_graph {u,v} E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "edge") THEN
  REWRITE_TAC[connected_graph] THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
  REWRITE_TAC[IN_INSERT; IN_SING] THEN
  DISCH_THEN(CONJUNCTS_THEN2
   (DISJ_CASES_THEN SUBST_ALL_TAC) (DISJ_CASES_THEN SUBST_ALL_TAC)) THEN
  REWRITE_TAC[GRAPH_REACHABLE_REFL] THEN
  MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
  ASM_REWRITE_TAC[PAIR_SET_SYM]);;

(* ------------------------------------------------------------------------- *)
(* The two sides determined by a component behind a separator contain every  *)
(* edge: an edge cannot pass between two deleted components.                 *)
(* ------------------------------------------------------------------------- *)

let GRAPH_SEPARATOR_COMPONENT_EDGE_DECOMPOSITION = prove
 (`!V:A->bool. !E:(A->bool)->bool. !S:A->bool. !x:A.
        finite_simple_graph V E /\ S SUBSET V /\ x IN V DIFF S
        ==> induced_subgraph_edges E
             (graph_component (induced_subgraph_edges E (V DIFF S)) x
              UNION S) UNION
            induced_subgraph_edges E
             (V DIFF
              graph_component (induced_subgraph_edges E (V DIFF S)) x) =
            E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph separator x_vertex" THEN
  ABBREV_TAC
   `D:(A->bool)->bool = induced_subgraph_edges E (V DIFF S)` THEN
  POP_ASSUM(LABEL_TAC "D_def") THEN
  ABBREV_TAC `C:A->bool = graph_component (D:(A->bool)->bool) x` THEN
  POP_ASSUM(LABEL_TAC "C_def") THEN
  SUBGOAL_THEN `(C:A->bool) SUBSET V DIFF S`
  (LABEL_TAC "component_subset") THENL
   [USE_THEN "C_def" (SUBST1_TAC o SYM) THEN
    USE_THEN "D_def" (SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC GRAPH_DELETED_COMPONENT_SUBSET THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC SUBSET_ANTISYM THEN CONJ_TAC THENL
   [REWRITE_TAC[UNION_SUBSET; INDUCED_SUBGRAPH_EDGES_SUBSET];
    REWRITE_TAC[SUBSET] THEN X_GEN_TAC `e:A->bool` THEN
    DISCH_THEN(LABEL_TAC "edge") THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `e:A->bool`]
     FINITE_SIMPLE_GRAPH_EDGE) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@a b. a_vertex b_vertex distinct edge_pair" THEN
    USE_THEN "edge_pair" SUBST_ALL_TAC THEN
    SUBGOAL_THEN `!z:A. z IN C ==> z IN V DIFF S`
    (LABEL_TAC "component_vertex") THENL
     [X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_component") THEN
      USE_THEN "component_subset"
       (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "z_component" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(a:A) IN C /\ b IN V DIFF S ==> b IN C`
    (LABEL_TAC "closed_ab") THENL
     [INTRO_TAC "a_component b_deleted" THEN
      SUBGOAL_THEN `(a:A) IN graph_component D x`
      (LABEL_TAC "a_original") THENL
       [USE_THEN "C_def" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "a_component" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `{a:A,b} IN D` (LABEL_TAC "deleted_edge") THENL
       [USE_THEN "D_def" (SUBST1_TAC o SYM) THEN
        REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES;
                    INSERT_SUBSET; SING_SUBSET] THEN
        CONJ_TAC THENL
         [USE_THEN "edge" ACCEPT_TAC;
          CONJ_TAC THENL
           [USE_THEN "component_vertex" MATCH_MP_TAC THEN
            USE_THEN "a_component" ACCEPT_TAC;
            USE_THEN "b_deleted" ACCEPT_TAC]];
        ALL_TAC] THEN
      USE_THEN "C_def" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC GRAPH_COMPONENT_CLOSED THEN
      EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(b:A) IN C /\ a IN V DIFF S ==> a IN C`
    (LABEL_TAC "closed_ba") THENL
     [INTRO_TAC "b_component a_deleted" THEN
      SUBGOAL_THEN `(b:A) IN graph_component D x`
      (LABEL_TAC "b_original") THENL
       [USE_THEN "C_def" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "b_component" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `{b:A,a} IN D` (LABEL_TAC "deleted_edge") THENL
       [USE_THEN "D_def" (SUBST1_TAC o SYM) THEN
        REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES;
                    INSERT_SUBSET; SING_SUBSET] THEN
        CONJ_TAC THENL
         [ONCE_REWRITE_TAC[SET_RULE `{b:A,a} = {a,b}`] THEN
          USE_THEN "edge" ACCEPT_TAC;
          CONJ_TAC THENL
           [USE_THEN "component_vertex" MATCH_MP_TAC THEN
            USE_THEN "b_component" ACCEPT_TAC;
            USE_THEN "a_deleted" ACCEPT_TAC]];
        ALL_TAC] THEN
      USE_THEN "C_def" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC GRAPH_COMPONENT_CLOSED THEN
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[IN_UNION; IN_INDUCED_SUBGRAPH_EDGES;
                INSERT_SUBSET; SING_SUBSET] THEN
    ASM_REWRITE_TAC[] THEN
    ASM_CASES_TAC `(a:A) IN C` THENL
     [ASM_CASES_TAC `(b:A) IN C` THENL
       [DISJ1_TAC THEN ASM_REWRITE_TAC[];
        ASM_CASES_TAC `(b:A) IN S` THENL
         [DISJ1_TAC THEN ASM_REWRITE_TAC[];
          SUBGOAL_THEN `(b:A) IN V DIFF S`
          (LABEL_TAC "b_deleted") THENL
           [REWRITE_TAC[IN_DIFF] THEN ASM_REWRITE_TAC[];
            ALL_TAC] THEN
          SUBGOAL_THEN `(b:A) IN C` (LABEL_TAC "b_component") THENL
           [USE_THEN "closed_ab" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
            CONTR_TAC(MP
             (NOT_ELIM(ASSUME `~((b:A) IN C)`))
             (ASSUME `(b:A) IN C`))]]];
      ASM_CASES_TAC `(b:A) IN C` THENL
       [ASM_CASES_TAC `(a:A) IN S` THENL
         [DISJ1_TAC THEN ASM_REWRITE_TAC[];
          SUBGOAL_THEN `(a:A) IN V DIFF S`
          (LABEL_TAC "a_deleted") THENL
           [REWRITE_TAC[IN_DIFF] THEN ASM_REWRITE_TAC[];
            ALL_TAC] THEN
          SUBGOAL_THEN `(a:A) IN C` (LABEL_TAC "a_component") THENL
           [USE_THEN "closed_ba" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
            CONTR_TAC(MP
             (NOT_ELIM(ASSUME `~((a:A) IN C)`))
             (ASSUME `(a:A) IN C`))]];
        DISJ2_TAC THEN ASM_REWRITE_TAC[IN_DIFF]]]]);;

(* ------------------------------------------------------------------------- *)
(* Connectedness of sides of a one-vertex separator.                         *)
(* ------------------------------------------------------------------------- *)

let GRAPH_COMPONENT_ADD_VERTEX_CONNECTED = prove
 (`!V:A->bool. !E:(A->bool)->bool. !S:A->bool.
   !x:A. !C:A->bool. !u z:A.
        finite_simple_graph V E /\
        x IN V DIFF S /\
        C = graph_component
             (induced_subgraph_edges E (V DIFF S)) x /\
        z IN C /\
        {u,z} IN E
        ==> connected_graph
             (C UNION {u})
             (induced_subgraph_edges E (C UNION {u}))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph x_vertex component z_component edge" THEN
  SUBGOAL_THEN `C UNION {u:A,z} = C UNION {u}`
  (LABEL_TAC "vertices") THENL
   [USE_THEN "z_component" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  USE_THEN "vertices" (SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `S:A->bool`;
    `x:A`; `C:A->bool`; `u:A`; `z:A`; `z:A`]
   GRAPH_COMPONENT_ADD_ADJACENT_PAIR_CONNECTED) THEN
  ASM_REWRITE_TAC[]);;

let CONNECTED_GRAPH_DELETE_COMPONENT_NEIGHBOR = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u x:A.
        finite_simple_graph V E /\
        connected_graph V E /\
        u IN V /\
        x IN V DELETE u
        ==> ?z.
              z IN graph_component
                    (induced_subgraph_edges E (V DELETE u)) x /\
              {u,z} IN E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected u_vertex x_vertex" THEN
  ABBREV_TAC
   `D:(A->bool)->bool = induced_subgraph_edges E (V DELETE u)` THEN
  POP_ASSUM(LABEL_TAC "D_def") THEN
  ABBREV_TAC `C:A->bool = graph_component (D:(A->bool)->bool) x` THEN
  POP_ASSUM(LABEL_TAC "C_def") THEN
  SUBGOAL_THEN `(C:A->bool) SUBSET V DELETE u`
  (LABEL_TAC "component_subset") THENL
   [USE_THEN "C_def" (SUBST1_TAC o SYM) THEN
    USE_THEN "D_def" (SUBST1_TAC o SYM) THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `{u:A}`; `x:A`]
     GRAPH_DELETED_COMPONENT_SUBSET) THEN
    ASM_REWRITE_TAC[SET_RULE `(V:A->bool) DIFF {u} = V DELETE u`];
    ALL_TAC] THEN
  SUBGOAL_THEN `(x:A) IN C` (LABEL_TAC "x_component") THENL
   [USE_THEN "C_def" (SUBST1_TAC o SYM) THEN
    MATCH_ACCEPT_TAC GRAPH_COMPONENT_REFL;
    ALL_TAC] THEN
  SUBGOAL_THEN `(C:A->bool) SUBSET V`
  (LABEL_TAC "component_in_V") THENL
   [MATCH_MP_TAC SUBSET_TRANS THEN
    EXISTS_TAC `(V:A->bool) DELETE u` THEN
    ASM_REWRITE_TAC[DELETE_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((C:A->bool) = V)`
  (LABEL_TAC "component_proper") THENL
   [DISCH_THEN(LABEL_TAC "all_vertices") THEN
    SUBGOAL_THEN `(u:A) IN C` (LABEL_TAC "u_component") THENL
     [USE_THEN "all_vertices" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "u_vertex" ACCEPT_TAC;
      USE_THEN "component_subset"
       (MP_TAC o REWRITE_RULE[SUBSET]) THEN
      DISCH_THEN(MP_TAC o SPEC `u:A`) THEN
      ASM_REWRITE_TAC[IN_DELETE]];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `C:A->bool`; `x:A`]
   CONNECTED_GRAPH_CROSSING_EDGE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@p z. p_outside z_component crossing_edge" THEN
  SUBGOAL_THEN `(p:A) = u` (LABEL_TAC "p_eq_u") THENL
   [MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "p_not_u") THEN
    SUBGOAL_THEN `(p:A) IN V DELETE u`
    (LABEL_TAC "p_deleted") THENL
     [REWRITE_TAC[IN_DELETE] THEN CONJ_TAC THENL
       [USE_THEN "p_outside"
         (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[IN_DIFF]);
        USE_THEN "p_not_u" ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `{z:A,p} IN D` (LABEL_TAC "deleted_edge") THENL
     [USE_THEN "D_def" (SUBST1_TAC o SYM) THEN
      REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES;
                  INSERT_SUBSET; SING_SUBSET] THEN
      CONJ_TAC THENL
       [ONCE_REWRITE_TAC[SET_RULE `{z:A,p} = {p,z}`] THEN
        USE_THEN "crossing_edge" ACCEPT_TAC;
        CONJ_TAC THENL
         [USE_THEN "component_subset"
           (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
          USE_THEN "z_component" ACCEPT_TAC;
          USE_THEN "p_deleted" ACCEPT_TAC]];
      ALL_TAC] THEN
    SUBGOAL_THEN `(p:A) IN C` (LABEL_TAC "p_component") THENL
     [USE_THEN "C_def" (fun th -> REWRITE_TAC[GSYM th]) THEN
      MATCH_MP_TAC GRAPH_COMPONENT_CLOSED THEN
      EXISTS_TAC `z:A` THEN CONJ_TAC THENL
       [USE_THEN "C_def" (fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "z_component" ACCEPT_TAC;
        USE_THEN "deleted_edge" ACCEPT_TAC];
      USE_THEN "p_outside" MP_TAC THEN
      REWRITE_TAC[IN_DIFF] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `z:A` THEN CONJ_TAC THENL
   [USE_THEN "z_component" ACCEPT_TAC;
    USE_THEN "p_eq_u" (SUBST1_TAC o SYM) THEN
    USE_THEN "crossing_edge" ACCEPT_TAC]);;

let CONNECTED_GRAPH_CUT_COMPONENT_SIDE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u x:A.
        finite_simple_graph V E /\
        connected_graph V E /\
        u IN V /\
        x IN V DELETE u
        ==> connected_graph
             (graph_component
               (induced_subgraph_edges E (V DELETE u)) x UNION {u})
             (induced_subgraph_edges E
               (graph_component
                 (induced_subgraph_edges E (V DELETE u)) x UNION {u}))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected u_vertex x_vertex" THEN
  MP_TAC(MATCH_MP
   (ISPECL
    [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `x:A`]
    CONNECTED_GRAPH_DELETE_COMPONENT_NEIGHBOR)
   (end_itlist CONJ
    [ASSUME `finite_simple_graph (V:A->bool) E`;
     ASSUME `connected_graph (V:A->bool) E`;
     ASSUME `(u:A) IN V`;
     ASSUME `(x:A) IN V DELETE u`])) THEN
  INTRO_TAC "@z. z_component edge" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `{u:A}`; `x:A`;
    `graph_component
      (induced_subgraph_edges E (V DELETE u)) x:A->bool`;
    `u:A`; `z:A`]
   GRAPH_COMPONENT_ADD_VERTEX_CONNECTED) THEN
  ASM_REWRITE_TAC[SET_RULE `(V:A->bool) DIFF {u} = V DELETE u`]);;

let INDUCED_SUBGRAPH_EDGES_MONO_VERTICES = prove
 (`!E:(A->bool)->bool. !W Z:A->bool.
        W SUBSET Z
        ==> induced_subgraph_edges E W SUBSET
            induced_subgraph_edges E Z`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "subset") THEN
  REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
  USE_THEN "subset" MP_TAC THEN REWRITE_TAC[SUBSET] THEN MESON_TAC[]);;

let GRAPH_SEPARATOR_COMPONENT_COMPLEMENT_CONNECTED = prove
 (`!V:A->bool. !E:(A->bool)->bool. !S:A->bool. !u x:A.
        finite_simple_graph V E /\
        S SUBSET V /\
        u IN S /\
        x IN V DIFF S /\
        connected_graph S (induced_subgraph_edges E S) /\
        (!z. z IN V DIFF S
             ==> connected_graph
                  (graph_component
                    (induced_subgraph_edges E (V DIFF S)) z UNION S)
                  (induced_subgraph_edges E
                    (graph_component
                      (induced_subgraph_edges E (V DIFF S)) z UNION S)))
        ==> connected_graph
             (V DIFF
              graph_component (induced_subgraph_edges E (V DIFF S)) x)
             (induced_subgraph_edges E
               (V DIFF
                graph_component
                 (induced_subgraph_edges E (V DIFF S)) x))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "graph separator root x_vertex base_connected side_connected" THEN
  ABBREV_TAC
   `D:(A->bool)->bool = induced_subgraph_edges E (V DIFF S)` THEN
  POP_ASSUM(LABEL_TAC "D_def") THEN
  ABBREV_TAC `C:A->bool = graph_component (D:(A->bool)->bool) x` THEN
  POP_ASSUM(LABEL_TAC "C_def") THEN
  ABBREV_TAC
   `H:(A->bool)->bool = induced_subgraph_edges E (V DIFF C)` THEN
  POP_ASSUM(LABEL_TAC "H_def") THEN
  SUBGOAL_THEN `(C:A->bool) SUBSET V DIFF S`
  (LABEL_TAC "component_subset") THENL
   [USE_THEN "C_def" (SUBST1_TAC o SYM) THEN
    USE_THEN "D_def" (SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC GRAPH_DELETED_COMPONENT_SUBSET THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(S:A->bool) SUBSET V DIFF C`
  (LABEL_TAC "separator_in_target") THENL
   [USE_THEN "component_subset" MP_TAC THEN
    USE_THEN "separator" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(u:A) IN V DIFF C` (LABEL_TAC "root_target") THENL
   [USE_THEN "separator_in_target"
     (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "root" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN V DIFF C ==> graph_reachable H u a`
  (LABEL_TAC "root_reaches") THENL
   [X_GEN_TAC `a:A` THEN DISCH_THEN(LABEL_TAC "a_target") THEN
    ASM_CASES_TAC `(a:A) IN S` THENL
     [SUBGOAL_THEN
       `graph_reachable (induced_subgraph_edges E S) (u:A) a`
      (LABEL_TAC "base_reachable") THENL
       [USE_THEN "base_connected" MP_TAC THEN
        REWRITE_TAC[connected_graph] THEN
        DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
         [USE_THEN "root" ACCEPT_TAC;
          ACCEPT_TAC(ASSUME `(a:A) IN S`)];
        ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
       [`induced_subgraph_edges E (S:A->bool)`;
        `H:(A->bool)->bool`; `u:A`; `a:A`]
       GRAPH_REACHABLE_MONO) THEN
      CONJ_TAC THENL
       [USE_THEN "H_def" (SUBST1_TAC o SYM) THEN
        MATCH_MP_TAC INDUCED_SUBGRAPH_EDGES_MONO_VERTICES THEN
        USE_THEN "separator_in_target" ACCEPT_TAC;
        USE_THEN "base_reachable" ACCEPT_TAC];
      SUBGOAL_THEN `(a:A) IN V DIFF S`
      (LABEL_TAC "a_deleted") THENL
       [REWRITE_TAC[IN_DIFF] THEN CONJ_TAC THENL
         [USE_THEN "a_target"
           (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[IN_DIFF]);
          ACCEPT_TAC(ASSUME `~((a:A) IN S)`)];
        ALL_TAC] THEN
      ABBREV_TAC
       `Acomp:A->bool = graph_component (D:(A->bool)->bool) a` THEN
      POP_ASSUM(LABEL_TAC "Acomp_def") THEN
      SUBGOAL_THEN `(Acomp:A->bool) SUBSET V DIFF S`
      (LABEL_TAC "a_component_subset") THENL
       [USE_THEN "Acomp_def" (SUBST1_TAC o SYM) THEN
        USE_THEN "D_def" (SUBST1_TAC o SYM) THEN
        MATCH_MP_TAC GRAPH_DELETED_COMPONENT_SUBSET THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(a:A) IN Acomp` (LABEL_TAC "a_component") THENL
       [USE_THEN "Acomp_def" (SUBST1_TAC o SYM) THEN
        MATCH_ACCEPT_TAC GRAPH_COMPONENT_REFL;
        ALL_TAC] THEN
      SUBGOAL_THEN `~graph_reachable (D:(A->bool)->bool) x a`
      (LABEL_TAC "components_separate") THENL
       [DISCH_THEN(LABEL_TAC "reachable") THEN
        SUBGOAL_THEN `(a:A) IN C` (LABEL_TAC "a_in_C") THENL
         [USE_THEN "C_def" (fun th -> REWRITE_TAC[GSYM th]) THEN
          REWRITE_TAC[IN_GRAPH_COMPONENT] THEN
          USE_THEN "reachable" ACCEPT_TAC;
          USE_THEN "a_target" MP_TAC THEN
          REWRITE_TAC[IN_DIFF] THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN `DISJOINT (C:A->bool) Acomp`
      (LABEL_TAC "components_disjoint") THENL
       [USE_THEN "C_def" (SUBST1_TAC o SYM) THEN
        USE_THEN "Acomp_def" (SUBST1_TAC o SYM) THEN
        MATCH_MP_TAC GRAPH_COMPONENTS_DISJOINT THEN
        USE_THEN "components_separate" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(Acomp UNION S:A->bool) SUBSET V DIFF C`
      (LABEL_TAC "side_subset") THENL
       [USE_THEN "component_subset" MP_TAC THEN
        USE_THEN "a_component_subset" MP_TAC THEN
        USE_THEN "components_disjoint" MP_TAC THEN
        USE_THEN "separator" MP_TAC THEN
        REWRITE_TAC[DISJOINT] THEN SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `connected_graph
         (Acomp UNION S:A->bool)
         (induced_subgraph_edges E (Acomp UNION S))`
      (LABEL_TAC "a_side_connected") THENL
       [USE_THEN "side_connected" (MP_TAC o SPEC `a:A`) THEN
        ANTS_TAC THENL
         [USE_THEN "a_deleted" ACCEPT_TAC;
          DISCH_THEN(LABEL_TAC "connected_component") THEN
          USE_THEN "Acomp_def" (fun th -> REWRITE_TAC[GSYM th]) THEN
          USE_THEN "connected_component" ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `graph_reachable
         (induced_subgraph_edges E (Acomp UNION S:A->bool)) (u:A) a`
      (LABEL_TAC "side_reachable") THENL
       [USE_THEN "a_side_connected" MP_TAC THEN
        REWRITE_TAC[connected_graph] THEN
        DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
         [REWRITE_TAC[IN_UNION] THEN DISJ2_TAC THEN
          USE_THEN "root" ACCEPT_TAC;
          REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
          USE_THEN "a_component" ACCEPT_TAC];
        ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
       [`induced_subgraph_edges E (Acomp UNION S:A->bool)`;
        `H:(A->bool)->bool`; `u:A`; `a:A`]
       GRAPH_REACHABLE_MONO) THEN
      CONJ_TAC THENL
       [USE_THEN "H_def" (SUBST1_TAC o SYM) THEN
        MATCH_MP_TAC INDUCED_SUBGRAPH_EDGES_MONO_VERTICES THEN
        USE_THEN "side_subset" ACCEPT_TAC;
        USE_THEN "side_reachable" ACCEPT_TAC]];
    ALL_TAC] THEN
  REWRITE_TAC[connected_graph] THEN
  MAP_EVERY X_GEN_TAC [`a:A`; `b:A`] THEN
  INTRO_TAC "a_target b_target" THEN
  MATCH_MP_TAC GRAPH_REACHABLE_TRANS THEN
  EXISTS_TAC `u:A` THEN CONJ_TAC THENL
   [MATCH_MP_TAC GRAPH_REACHABLE_SYM THEN
    USE_THEN "root_reaches" MATCH_MP_TAC THEN
    USE_THEN "a_target" ACCEPT_TAC;
    USE_THEN "root_reaches" MATCH_MP_TAC THEN
    USE_THEN "b_target" ACCEPT_TAC]);;

let CONNECTED_GRAPH_CUT_COMPONENT_COMPLEMENT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u x:A.
        finite_simple_graph V E /\
        connected_graph V E /\
        u IN V /\
        x IN V DELETE u
        ==> connected_graph
             (V DIFF
              graph_component
               (induced_subgraph_edges E (V DELETE u)) x)
             (induced_subgraph_edges E
               (V DIFF
                graph_component
                 (induced_subgraph_edges E (V DELETE u)) x))`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph connected u_vertex x_vertex" THEN
  REWRITE_TAC[GSYM(SET_RULE `(V:A->bool) DIFF {u} = V DELETE u`)] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `{u:A}`; `u:A`; `x:A`]
   GRAPH_SEPARATOR_COMPONENT_COMPLEMENT_CONNECTED) THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    REWRITE_TAC[SING_SUBSET] THEN USE_THEN "u_vertex" ACCEPT_TAC;
    REWRITE_TAC[IN_SING];
    USE_THEN "x_vertex" MP_TAC THEN
    REWRITE_TAC[IN_DELETE; IN_DIFF; IN_SING];
    REWRITE_TAC[connected_graph] THEN
    MAP_EVERY X_GEN_TAC [`a:A`; `b:A`] THEN
    REWRITE_TAC[IN_SING] THEN INTRO_TAC "a_eq b_eq" THEN
    USE_THEN "a_eq" SUBST_ALL_TAC THEN
    USE_THEN "b_eq" SUBST_ALL_TAC THEN
    MATCH_ACCEPT_TAC GRAPH_REACHABLE_REFL;
    X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_vertex") THEN
    REWRITE_TAC[SET_RULE `(V:A->bool) DIFF {u} = V DELETE u`] THEN
    MATCH_MP_TAC CONNECTED_GRAPH_CUT_COMPONENT_SIDE THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "z_vertex" MP_TAC THEN
    REWRITE_TAC[IN_DIFF; IN_DELETE; IN_SING]]);;

(* A temporary separator edge disappears when both its endpoints are
   deleted. *)

let INDUCED_SUBGRAPH_EDGES_INSERT_DELETED_PAIR = prove
 (`!E:(A->bool)->bool. !V:A->bool. !u v:A.
        induced_subgraph_edges ({u,v} INSERT E) (V DIFF {u,v}) =
        induced_subgraph_edges E (V DIFF {u,v})`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[EXTENSION; IN_INDUCED_SUBGRAPH_EDGES; IN_INSERT] THEN
  X_GEN_TAC `e:A->bool` THEN EQ_TAC THENL
   [INTRO_TAC "edge subset" THEN CONJ_TAC THENL
     [USE_THEN "edge" DISJ_CASES_TAC THENL
       [USE_THEN "subset" MP_TAC THEN ASM SET_TAC[];
        FIRST_ASSUM ACCEPT_TAC];
      USE_THEN "subset" ACCEPT_TAC];
    MESON_TAC[]]);;

let VERTEX_2_CONNECTED_GRAPH_SEPARATOR_COMPONENT_SIDE = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v x:A.
        vertex_k_connected_graph 2 V E /\
        u IN V /\
        v IN V /\
        ~(u = v) /\
        x IN V DIFF {u,v}
        ==> connected_graph
             (graph_component
               (induced_subgraph_edges E (V DIFF {u,v})) x UNION {u,v})
             (induced_subgraph_edges ({u,v} INSERT E)
               (graph_component
                 (induced_subgraph_edges E (V DIFF {u,v})) x UNION
                {u,v}))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "connected u_vertex v_vertex distinct x_vertex" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `2` THEN USE_THEN "connected" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) ({u,v} INSERT E)`
  (LABEL_TAC "inserted_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INSERT_EDGE THEN
    ASM_REWRITE_TAC[PAIR_HAS_SIZE_2] THEN
    USE_THEN "u_vertex" MP_TAC THEN
    USE_THEN "v_vertex" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`; `x:A`]
   VERTEX_2_CONNECTED_GRAPH_COMPONENT_NEIGHBOR) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@z. z_component edge" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `({u,v} INSERT E):(A->bool)->bool`;
    `{u,v}:A->bool`; `x:A`;
    `graph_component
      (induced_subgraph_edges E (V DIFF {u,v})) x:A->bool`;
    `u:A`; `v:A`; `z:A`]
   GRAPH_COMPONENT_ADD_ADJACENT_PAIR_CONNECTED) THEN
  ASM_REWRITE_TAC
   [IN_INSERT; INDUCED_SUBGRAPH_EDGES_INSERT_DELETED_PAIR]);;

let VERTEX_2_CONNECTED_GRAPH_SEPARATOR_COMPONENT_COMPLEMENT = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v x:A.
        vertex_k_connected_graph 2 V E /\
        u IN V /\
        v IN V /\
        ~(u = v) /\
        x IN V DIFF {u,v}
        ==> connected_graph
             (V DIFF
              graph_component
               (induced_subgraph_edges E (V DIFF {u,v})) x)
             (induced_subgraph_edges ({u,v} INSERT E)
               (V DIFF
                graph_component
                 (induced_subgraph_edges E (V DIFF {u,v})) x))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "connected u_vertex v_vertex distinct x_vertex" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `2` THEN USE_THEN "connected" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) ({u,v} INSERT E)`
  (LABEL_TAC "inserted_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INSERT_EDGE THEN
    ASM_REWRITE_TAC[PAIR_HAS_SIZE_2] THEN
    USE_THEN "u_vertex" MP_TAC THEN
    USE_THEN "v_vertex" MP_TAC THEN SET_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `({u,v} INSERT E):(A->bool)->bool`;
    `{u,v}:A->bool`; `u:A`; `x:A`]
   GRAPH_SEPARATOR_COMPONENT_COMPLEMENT_CONNECTED) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "inserted_graph" ACCEPT_TAC;
      ASM_REWRITE_TAC[INSERT_SUBSET; EMPTY_SUBSET];
      REWRITE_TAC[IN_INSERT];
      USE_THEN "x_vertex" ACCEPT_TAC;
      MATCH_MP_TAC GRAPH_EDGE_CONNECTED_PAIR THEN
      REWRITE_TAC
       [IN_INDUCED_SUBGRAPH_EDGES; IN_INSERT; SUBSET_REFL];
      X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_vertex") THEN
      REWRITE_TAC[INDUCED_SUBGRAPH_EDGES_INSERT_DELETED_PAIR] THEN
      MATCH_MP_TAC VERTEX_2_CONNECTED_GRAPH_SEPARATOR_COMPONENT_SIDE THEN
      ASM_REWRITE_TAC[]];
    DISCH_THEN(LABEL_TAC "complement") THEN
    USE_THEN "complement"
     (ACCEPT_TAC o
      REWRITE_RULE[INDUCED_SUBGRAPH_EDGES_INSERT_DELETED_PAIR])]);;

(* ------------------------------------------------------------------------- *)
(* Extracting separators from failed connectivity conditions.                *)
(* ------------------------------------------------------------------------- *)

let CONNECTED_FINITE_SIMPLE_GRAPH_NOT_2_CONNECTED_CUT_VERTEX = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        finite_simple_graph V E /\
        connected_graph V E /\
        2 < CARD V /\
        ~vertex_k_connected_graph 2 V E
        ==> ?u. u IN V /\ graph_vertex_separator V E {u}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph connected large not_connected2" THEN
  USE_THEN "not_connected2" MP_TAC THEN
  REWRITE_TAC[vertex_k_connected_graph] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[NOT_FORALL_THM; NOT_IMP] THEN
  INTRO_TAC "@S. (subset small) disconnected" THEN
  SUBGOAL_THEN `induced_subgraph_edges (E:(A->bool)->bool) V = E`
  (LABEL_TAC "induced_self") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH_SELF THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(S:A->bool = {})` (LABEL_TAC "nonempty") THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "disconnected" (MATCH_MP_TAC o NOT_ELIM) THEN
    REWRITE_TAC[DIFF_EMPTY] THEN
    USE_THEN "induced_self" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "connected" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(S:A->bool)` (LABEL_TAC "finite_S") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `V:A->bool` THEN CONJ_TAC THENL
     [USE_THEN "graph"
       (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[finite_simple_graph]);
      USE_THEN "subset" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(S:A->bool) = 1` (LABEL_TAC "card_one") THENL
   [SUBGOAL_THEN `~(CARD(S:A->bool) = 0)`
    (LABEL_TAC "positive") THENL
     [MP_TAC(MATCH_MP
       (ISPEC `S:A->bool` CARD_EQ_0)
       (ASSUME `FINITE(S:A->bool)`)) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(S:A->bool) HAS_SIZE 1` MP_TAC THENL
   [REWRITE_TAC[HAS_SIZE] THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[HAS_SIZE_CONV `(S:A->bool) HAS_SIZE 1`] THEN
    INTRO_TAC "@u. S_eq"] THEN
  EXISTS_TAC `u:A` THEN USE_THEN "S_eq" SUBST_ALL_TAC THEN
  CONJ_TAC THENL
   [USE_THEN "subset" MP_TAC THEN REWRITE_TAC[SING_SUBSET];
    REWRITE_TAC[graph_vertex_separator] THEN ASM_REWRITE_TAC[]]);;

let VERTEX_2_CONNECTED_GRAPH_NOT_3_CONNECTED_SEPARATOR_PAIR = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        vertex_k_connected_graph 2 V E /\
        3 < CARD V /\
        ~vertex_k_connected_graph 3 V E
        ==> ?u v:A.
              u IN V /\
              v IN V /\
              ~(u = v) /\
              graph_vertex_separator V E {u,v}`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "connected2 large not_connected3" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `2` THEN USE_THEN "connected2" ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "not_connected3" MP_TAC THEN
  REWRITE_TAC[vertex_k_connected_graph] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[NOT_FORALL_THM; NOT_IMP] THEN
  INTRO_TAC "@S. (subset small) disconnected" THEN
  SUBGOAL_THEN `~(CARD(S:A->bool) < 2)`
  (LABEL_TAC "not_smaller") THENL
   [DISCH_THEN(LABEL_TAC "smaller") THEN
    USE_THEN "disconnected" (MATCH_MP_TAC o NOT_ELIM) THEN
    MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_DELETE_LT THEN
    EXISTS_TAC `2` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `CARD(S:A->bool) = 2` (LABEL_TAC "card_two") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(S:A->bool)` (LABEL_TAC "finite_S") THENL
   [MATCH_MP_TAC FINITE_SUBSET THEN
    EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "graph"
     (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[finite_simple_graph]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(S:A->bool) HAS_SIZE 2` MP_TAC THENL
   [REWRITE_TAC[HAS_SIZE] THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[HAS_SIZE_CONV `(S:A->bool) HAS_SIZE 2`] THEN
    INTRO_TAC "@u v. distinct S_eq"] THEN
  MAP_EVERY EXISTS_TAC [`u:A`; `v:A`] THEN
  USE_THEN "S_eq" SUBST_ALL_TAC THEN REPEAT CONJ_TAC THENL
   [USE_THEN "subset" MP_TAC THEN
    REWRITE_TAC[INSERT_SUBSET; EMPTY_SUBSET] THEN MESON_TAC[];
    USE_THEN "subset" MP_TAC THEN
    REWRITE_TAC[INSERT_SUBSET; EMPTY_SUBSET] THEN MESON_TAC[];
    USE_THEN "distinct" ACCEPT_TAC;
    REWRITE_TAC[graph_vertex_separator] THEN ASM_REWRITE_TAC[]]);;

let EULER_PLANAR_GRAPH_COMPONENTWISE = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        finite_simple_graph V E /\
        (!u. u IN V
             ==> euler_planar_graph
                  (graph_component E u) (graph_component_edges E u))
        ==> euler_planar_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph component_euler" THEN
  REWRITE_TAC[euler_planar_graph] THEN CONJ_TAC THENL
   [USE_THEN "graph" ACCEPT_TAC;
    X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "u_vertex") THEN
    MATCH_MP_TAC(ISPECL
     [`graph_component (E:(A->bool)->bool) u:A->bool`;
      `graph_component_edges E u:(A->bool)->bool`; `u:A`]
     EULER_PLANAR_GRAPH_CONNECTED) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "component_euler" MATCH_MP_TAC THEN
      USE_THEN "u_vertex" ACCEPT_TAC;
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
       GRAPH_COMPONENT_EDGES_CONNECTED) THEN
      ASM_REWRITE_TAC[];
      MATCH_ACCEPT_TAC GRAPH_COMPONENT_REFL]]);;

(* ------------------------------------------------------------------------- *)
(* Induction for Kuratowski's theorem on arbitrary finite simple graphs.     *)
(* ------------------------------------------------------------------------- *)

let INDUCED_SUBGRAPH_EDGES_INSERT_INCLUDED = prove
 (`!E:(A->bool)->bool. !e:A->bool. !W:A->bool.
        e SUBSET W
        ==> induced_subgraph_edges (e INSERT E) W =
            e INSERT induced_subgraph_edges E W`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "included") THEN
  REWRITE_TAC[EXTENSION; IN_INDUCED_SUBGRAPH_EDGES; IN_INSERT] THEN
  USE_THEN "included" MP_TAC THEN SET_TAC[]);;

let VERTEX_2_CONNECTED_GRAPH_COMPONENT_PATH_IN = prove
 (`!V:A->bool. !E:(A->bool)->bool. !u v x:A.
        vertex_k_connected_graph 2 V E /\
        u IN V /\
        v IN V /\
        ~(u = v) /\
        x IN V DIFF {u,v}
        ==> ?l q:num->A.
              0 < l /\
              q 0 = u /\
              q l = v /\
              INJ q (0..l) (:A) /\
              (!i. 0 < i /\ i < l
                   ==> q i IN graph_component
                        (induced_subgraph_edges E (V DIFF {u,v})) x) /\
              indexed_path_vertices q l SUBSET V /\
              indexed_path_edges q l SUBSET E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "connected2 u_vertex v_vertex distinct x_vertex" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [MATCH_MP_TAC VERTEX_K_CONNECTED_GRAPH_FINITE_SIMPLE THEN
    EXISTS_TAC `2` THEN USE_THEN "connected2" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_component
     (induced_subgraph_edges E (V DIFF {u:A,v})) x
    SUBSET V DIFF {u,v}`
  (LABEL_TAC "component_subset") THENL
   [MATCH_MP_TAC GRAPH_DELETED_COMPONENT_SUBSET THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `u:A`; `v:A`; `x:A`]
   VERTEX_2_CONNECTED_GRAPH_COMPONENT_PATH) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC
   "@l q. positive start finish injective internal path_edges" THEN
  MAP_EVERY EXISTS_TAC [`l:num`; `q:num->A`] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[SUBSET; IN_INDEXED_PATH_VERTICES] THEN
  X_GEN_TAC `z:A` THEN
  INTRO_TAC "@i. i_bound z_eq" THEN
  USE_THEN "z_eq" SUBST1_TAC THEN
  ASM_CASES_TAC `i = 0` THENL
   [ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `i:num = l` THENL
   [ASM_REWRITE_TAC[];
    SUBGOAL_THEN
     `(q:num->A) i IN
      graph_component
       (induced_subgraph_edges E (V DIFF {u,v})) x`
    (LABEL_TAC "internal_vertex") THENL
     [USE_THEN "internal" MATCH_MP_TAC THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    USE_THEN "component_subset" MP_TAC THEN
    USE_THEN "internal_vertex" MP_TAC THEN SET_TAC[]]);;

let FINITE_SIMPLE_GRAPH_KURATOWSKI_FREE_EULER_PLANAR = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        finite_simple_graph V E /\
        ~graph_kuratowski_obstruction V E
        ==> euler_planar_graph V E`,
  GEN_TAC THEN WF_INDUCT_TAC `CARD(V:A->bool)` THEN
  POP_ASSUM(LABEL_TAC "induction") THEN
  X_GEN_TAC `E:(A->bool)->bool` THEN
  INTRO_TAC "graph unobstructed" THEN
  ASM_CASES_TAC `CARD(V:A->bool) <= 3` THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_CARD_LE_3_EULER_PLANAR THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `3 < CARD(V:A->bool)` (LABEL_TAC "large") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `~connected_graph (V:A->bool) E` THENL
   [FIRST_X_ASSUM(LABEL_TAC "disconnected") THEN
    MATCH_MP_TAC EULER_PLANAR_GRAPH_COMPONENTWISE THEN
    CONJ_TAC THENL
     [USE_THEN "graph" ACCEPT_TAC;
      ALL_TAC] THEN
    X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "u_vertex") THEN
    ABBREV_TAC `C:A->bool = graph_component E u` THEN
    POP_ASSUM(LABEL_TAC "C_def") THEN
    ABBREV_TAC
     `K:(A->bool)->bool = graph_component_edges E u` THEN
    POP_ASSUM(LABEL_TAC "K_def") THEN
    SUBGOAL_THEN `(C:A->bool) SUBSET V`
    (LABEL_TAC "component_subset") THENL
     [USE_THEN "C_def" (SUBST1_TAC o SYM) THEN
      MATCH_MP_TAC GRAPH_COMPONENT_SUBSET THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `~((C:A->bool) = V)`
    (LABEL_TAC "component_proper") THENL
     [DISCH_THEN(LABEL_TAC "component_all") THEN
      USE_THEN "disconnected" (MATCH_MP_TAC o NOT_ELIM) THEN
      MP_TAC(MATCH_MP
       (ISPECL [`V:A->bool`; `E:(A->bool)->bool`; `u:A`]
        CONNECTED_GRAPH_COMPONENT)
       (ASSUME `(u:A) IN V`)) THEN
      DISCH_THEN(fun th ->
       MATCH_MP_TAC(snd(EQ_IMP_RULE th))) THEN
      USE_THEN "C_def" (fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[SUBSET_REFL];
      ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite") THENL
     [USE_THEN "graph"
       (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[finite_simple_graph]);
      ALL_TAC] THEN
  SUBGOAL_THEN `CARD(C:A->bool) < CARD(V:A->bool)`
  (LABEL_TAC "smaller") THENL
     [MATCH_MP_TAC(ISPECL [`C:A->bool`; `V:A->bool`] CARD_PSUBSET) THEN
      ASM_REWRITE_TAC[PSUBSET];
      ALL_TAC] THEN
    SUBGOAL_THEN `finite_simple_graph (C:A->bool) K`
    (LABEL_TAC "component_graph") THENL
     [MAP_EVERY (fun s -> USE_THEN s (SUBST1_TAC o SYM))
       ["C_def"; "K_def"] THEN
      MATCH_MP_TAC FINITE_SIMPLE_GRAPH_COMPONENT THEN
      EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `~graph_kuratowski_obstruction (C:A->bool) K`
    (LABEL_TAC "component_unobstructed") THENL
     [DISCH_THEN(LABEL_TAC "component_obstruction") THEN
      USE_THEN "unobstructed" (MATCH_MP_TAC o NOT_ELIM) THEN
      MATCH_MP_TAC(ISPECL
       [`C:A->bool`; `V:A->bool`;
        `K:(A->bool)->bool`; `E:(A->bool)->bool`]
       GRAPH_KURATOWSKI_OBSTRUCTION_MONO) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "K_def" (SUBST1_TAC o SYM) THEN
      MATCH_ACCEPT_TAC GRAPH_COMPONENT_EDGES_SUBSET;
      ALL_TAC] THEN
    USE_THEN "induction" (MP_TAC o SPEC `C:A->bool`) THEN
    ANTS_TAC THENL
     [USE_THEN "smaller" ACCEPT_TAC;
      DISCH_THEN(MP_TAC o SPEC `K:(A->bool)->bool`) THEN
      ASM_REWRITE_TAC[]];
    FIRST_X_ASSUM(MP_TAC) THEN REWRITE_TAC[] THEN
    DISCH_THEN(LABEL_TAC "connected") THEN
    ASM_CASES_TAC
     `~vertex_k_connected_graph 2 (V:A->bool) E` THENL
     [FIRST_X_ASSUM(LABEL_TAC "not_connected2") THEN
      MP_TAC(MATCH_MP
       (ISPECL [`V:A->bool`; `E:(A->bool)->bool`]
        CONNECTED_FINITE_SIMPLE_GRAPH_NOT_2_CONNECTED_CUT_VERTEX)
       (end_itlist CONJ
        [ASSUME `finite_simple_graph (V:A->bool) E`;
         ASSUME `connected_graph (V:A->bool) E`;
         MATCH_MP (ARITH_RULE `(3:num) < n ==> 2 < n`)
          (ASSUME `3 < CARD(V:A->bool)`);
         ASSUME `~vertex_k_connected_graph 2 (V:A->bool) E`])) THEN
      INTRO_TAC "@u. u_vertex separator" THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `{u:A}`]
       GRAPH_VERTEX_SEPARATOR_COMPONENT_WITNESSES) THEN
      ASM_REWRITE_TAC
       [SET_RULE `(V:A->bool) DIFF {u} = V DELETE u`] THEN
      INTRO_TAC "@x y. x_deleted y_deleted y_outside" THEN
