      POP_ASSUM(LABEL_TAC "C_def") THEN
      ABBREV_TAC `V1:A->bool = C UNION {u}` THEN
      POP_ASSUM(LABEL_TAC "V1_def") THEN
      ABBREV_TAC `V2:A->bool = V DIFF C` THEN
      POP_ASSUM(LABEL_TAC "V2_def") THEN
      ABBREV_TAC
       `E1:(A->bool)->bool = induced_subgraph_edges E V1` THEN
      POP_ASSUM(LABEL_TAC "E1_def") THEN
      ABBREV_TAC
       `E2:(A->bool)->bool = induced_subgraph_edges E V2` THEN
