        ALL_TAC] THEN
      SUBGOAL_THEN `(V1:A->bool) SUBSET V`
      (LABEL_TAC "V1_subset") THENL
       [MAP_EVERY (fun s -> USE_THEN s MP_TAC)
         ["V1_def"; "component_subset"; "u_vertex"] THEN
        SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(V2:A->bool) SUBSET V`
      (LABEL_TAC "V2_subset") THENL
       [USE_THEN "V2_def" MP_TAC THEN SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `~((y:A) IN V1)` (LABEL_TAC "y_outside_V1") THENL
       [MAP_EVERY (fun s -> USE_THEN s MP_TAC)
         ["V1_def"; "y_deleted"; "y_outside"] THEN
        SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `~((x:A) IN V2)` (LABEL_TAC "x_outside_V2") THENL
       [MAP_EVERY (fun s -> USE_THEN s MP_TAC)
         ["V2_def"; "x_component"] THEN
        SET_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite") THENL
       [USE_THEN "graph"
         (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[finite_simple_graph]);
        ALL_TAC] THEN
      SUBGOAL_THEN `CARD(V1:A->bool) < CARD(V:A->bool)`
      (LABEL_TAC "V1_smaller") THENL
       [MATCH_MP_TAC
         (ISPECL [`V1:A->bool`; `V:A->bool`] CARD_PSUBSET) THEN
        CONJ_TAC THENL
         [REWRITE_TAC[PSUBSET] THEN CONJ_TAC THENL
           [USE_THEN "V1_subset" ACCEPT_TAC;
            DISCH_THEN(LABEL_TAC "V1_all") THEN
            USE_THEN "y_outside_V1" (MATCH_MP_TAC o NOT_ELIM) THEN
            USE_THEN "V1_all" (fun th -> REWRITE_TAC[th]) THEN
            USE_THEN "y_deleted" MP_TAC THEN SET_TAC[]];
          USE_THEN "finite" ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `CARD(V2:A->bool) < CARD(V:A->bool)`
