       [MATCH_MP_TAC
         (ISPECL [`V2:A->bool`; `V:A->bool`] CARD_PSUBSET) THEN
        CONJ_TAC THENL
         [REWRITE_TAC[PSUBSET] THEN CONJ_TAC THENL
           [USE_THEN "V2_subset" ACCEPT_TAC;
            DISCH_THEN(LABEL_TAC "V2_all") THEN
            USE_THEN "x_outside_V2" (MATCH_MP_TAC o NOT_ELIM) THEN
            USE_THEN "V2_all" (fun th -> REWRITE_TAC[th]) THEN
            USE_THEN "x_deleted" MP_TAC THEN SET_TAC[]];
          USE_THEN "finite" ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `finite_simple_graph (V1:A->bool) E1`
      (LABEL_TAC "graph1") THENL
       [USE_THEN "E1_def" (SUBST1_TAC o SYM) THEN
