           ASSUME `{u:A,v} IN E1`;
           ASSUME `{u:A,v} IN E2`;
           ASSUME `?w:A. {u,w} IN E2 /\ ~(w = v)`;
           ASSUME `?z:A. {v,z} IN E1 /\ ~(z = u)`])) THEN
        DISCH_THEN(LABEL_TAC "amalgamated") THEN
        MATCH_MP_TAC(ISPECL
         [`V:A->bool`; `{u,v} INSERT E:(A->bool)->bool`;
          `E:(A->bool)->bool`]
         EULER_PLANAR_GRAPH_SUBSET_EDGES) THEN
        CONJ_TAC THENL
         [USE_THEN "vertex_decomposition" (fun vth ->
           USE_THEN "edge_decomposition" (fun eth ->
            USE_THEN "amalgamated"
             (ACCEPT_TAC o REWRITE_RULE[vth; eth])));
          SET_TAC[]]]]]);;

(* ------------------------------------------------------------------------- *)
(* Necessary and sufficient Kuratowski conditions in the 3-connected case.   *)
(* ------------------------------------------------------------------------- *)

let EULER_PLANAR_GRAPH_IMP_KURATOWSKI_FREE = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        euler_planar_graph V E
        ==> ~graph_kuratowski_obstruction V E`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(LABEL_TAC "euler") THEN
  DISCH_THEN(LABEL_TAC "obstruction") THEN
  USE_THEN "obstruction" MP_TAC THEN
  REWRITE_TAC[graph_kuratowski_obstruction] THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (X_CHOOSE_THEN `W:A->bool`
    (X_CHOOSE_THEN `P:A->bool`
     (X_CHOOSE_THEN `f:(A->bool)->bool` STRIP_ASSUME_TAC)))
   (X_CHOOSE_THEN `X:A->bool`
    (X_CHOOSE_THEN `Y:A->bool`
     (X_CHOOSE_THEN `P:A->bool`
      (X_CHOOSE_THEN `f:(A->bool)->bool` STRIP_ASSUME_TAC))))) THENL
   [SUBGOAL_THEN
     `graph_topological_subgraph
       (W:A->bool) (complete_graph_edges W) V E`
    (LABEL_TAC "topological_subgraph") THENL
     [REWRITE_TAC[graph_topological_subgraph] THEN
      MAP_EVERY EXISTS_TAC
       [`P:A->bool`; `f:(A->bool)->bool`] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_MESON_TAC
     [COMPLETE_GRAPH_5_TOPOLOGICAL_SUBGRAPH_OBSTRUCTS_EULER_PLANARITY];
    SUBGOAL_THEN
     `graph_topological_subgraph
       (X UNION Y:A->bool) (complete_bipartite_edges X Y) V E`
    (LABEL_TAC "topological_subgraph") THENL
     [REWRITE_TAC[graph_topological_subgraph] THEN
      MAP_EVERY EXISTS_TAC
       [`P:A->bool`; `f:(A->bool)->bool`] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_MESON_TAC
    [COMPLETE_BIPARTITE_3_3_TOPOLOGICAL_SUBGRAPH_OBSTRUCTS_EULER_PLANARITY]]);;

let VERTEX_3_CONNECTED_EULER_PLANAR_GRAPH_EQ_KURATOWSKI_FREE = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        vertex_k_connected_graph 3 V E
        ==> (euler_planar_graph V E <=>
             ~graph_kuratowski_obstruction V E)`,
  MESON_TAC
   [EULER_PLANAR_GRAPH_IMP_KURATOWSKI_FREE;
    VERTEX_3_CONNECTED_KURATOWSKI_FREE_EULER_PLANAR]);;

(* ------------------------------------------------------------------------- *)
(* Kuratowski's theorem in Euler, topological, and straight-line forms.      *)
(* ------------------------------------------------------------------------- *)

let KURATOWSKI_EULER = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        finite_simple_graph V E
        ==> (euler_planar_graph V E <=>
             ~graph_kuratowski_obstruction V E)`,
  MESON_TAC
   [EULER_PLANAR_GRAPH_IMP_KURATOWSKI_FREE;
    FINITE_SIMPLE_GRAPH_KURATOWSKI_FREE_EULER_PLANAR]);;

let KURATOWSKI = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        finite_simple_graph V E
        ==> (planar_graph V E <=>
             ~graph_kuratowski_obstruction V E)`,
  MESON_TAC
   [KURATOWSKI_EULER;
    EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH]);;

let KURATOWSKI_STRAIGHT_LINE = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        finite_simple_graph V E
        ==> (straight_line_planar_graph V E <=>
             ~graph_kuratowski_obstruction V E)`,
  MESON_TAC
   [KURATOWSKI_EULER;
    EULER_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR]);;

(* ========================================================================= *)
(* Graph minors and Wagner's characterization of planar graphs.              *)
(*                                                                           *)
(* The relation graph_minor V E W F means that (W,F) is obtained from the    *)
(* finite simple graph (V,E) by repeatedly taking subgraphs and contracting  *)
(* edges. Contraction suppresses loops and merges parallel edges as required *)
(* by the simple-graph representation used throughout this development.      *)
(* ========================================================================= *)

let graph_minor_RULES,
    graph_minor_INDUCT,
    graph_minor_CASES = new_inductive_definition
 `(!V E.
        finite_simple_graph (V:A->bool) E
        ==> graph_minor V E V E) /\
  (!V E W F W' F'.
        graph_minor (V:A->bool) E W F /\
        W' SUBSET W /\
        F' SUBSET induced_subgraph_edges F W'
        ==> graph_minor V E W' F') /\
  (!V E W F u v.
        graph_minor (V:A->bool) E W F /\
        {u,v} IN F
        ==> graph_minor
             V E (W DELETE u) (graph_contract_edges W F u v))`;;

let GRAPH_MINOR_REFL = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> graph_minor V E V E`,
  MESON_TAC[graph_minor_RULES]);;

let GRAPH_MINOR_SUBGRAPH = prove
 (`!V E W F W' F'.
        graph_minor (V:A->bool) E W F /\
        W' SUBSET W /\
        F' SUBSET induced_subgraph_edges F W'
        ==> graph_minor V E W' F'`,
  MESON_TAC[graph_minor_RULES]);;

let GRAPH_MINOR_CONTRACT = prove
 (`!V E W F u v.
        graph_minor (V:A->bool) E W F /\
        {u,v} IN F
        ==> graph_minor
             V E (W DELETE u) (graph_contract_edges W F u v)`,
  MESON_TAC[graph_minor_RULES]);;

let GRAPH_MINOR_DATA = prove
 (`!V E W D.
        graph_minor (V:A->bool) E W D
        ==> finite_simple_graph V E /\
            finite_simple_graph W D /\
            (graph_kuratowski_obstruction W D
             ==> graph_kuratowski_obstruction V E)`,
  MATCH_MP_TAC graph_minor_INDUCT THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC
     [`V:A->bool`; `E:(A->bool)->bool`] THEN
    DISCH_THEN(LABEL_TAC "graph") THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC
     [`V:A->bool`; `E:(A->bool)->bool`;
      `W:A->bool`; `D:(A->bool)->bool`;
      `W':A->bool`; `D':(A->bool)->bool`] THEN
    INTRO_TAC
     "(source_graph parent_graph lift) vertices edges" THEN
    SUBGOAL_THEN
     `finite_simple_graph
       (W':A->bool) (induced_subgraph_edges D W')`
    (LABEL_TAC "induced_graph") THENL
     [MATCH_MP_TAC(ISPECL
       [`W:A->bool`; `D:(A->bool)->bool`; `W':A->bool`]
       FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `finite_simple_graph (W':A->bool) D'`
    (LABEL_TAC "target_graph") THENL
     [MATCH_MP_TAC(ISPECL
       [`W':A->bool`; `induced_subgraph_edges D W':(A->bool)->bool`;
        `D':(A->bool)->bool`]
       FINITE_SIMPLE_GRAPH_SUBSET_EDGES) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "source_graph" ACCEPT_TAC;
      USE_THEN "target_graph" ACCEPT_TAC;
      DISCH_THEN(LABEL_TAC "target_obstruction") THEN
      USE_THEN "lift" MATCH_MP_TAC THEN
      MATCH_MP_TAC(ISPECL
       [`W':A->bool`; `W:A->bool`;
        `D':(A->bool)->bool`; `D:(A->bool)->bool`]
       GRAPH_KURATOWSKI_OBSTRUCTION_MONO) THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "vertices" ACCEPT_TAC;
        MATCH_MP_TAC SUBSET_TRANS THEN
        EXISTS_TAC `induced_subgraph_edges D (W':A->bool)` THEN
        ASM_REWRITE_TAC[INDUCED_SUBGRAPH_EDGES_SUBSET];
        USE_THEN "target_obstruction" ACCEPT_TAC]];
    MAP_EVERY X_GEN_TAC
     [`V:A->bool`; `E:(A->bool)->bool`;
      `W:A->bool`; `D:(A->bool)->bool`; `u:A`; `v:A`] THEN
    INTRO_TAC "(source_graph parent_graph lift) edge" THEN
    SUBGOAL_THEN
     `(u:A) IN W /\ (v:A) IN W /\ ~(u = v)`
    (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
     (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
      (LABEL_TAC "distinct"))) THENL
     [MP_TAC(ISPECL
       [`W:A->bool`; `D:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `finite_simple_graph
       ((W:A->bool) DELETE u) (graph_contract_edges W D u v)`
    (LABEL_TAC "target_graph") THENL
     [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_CONTRACT THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "source_graph" ACCEPT_TAC;
      USE_THEN "target_graph" ACCEPT_TAC;
      DISCH_THEN(LABEL_TAC "target_obstruction") THEN
      USE_THEN "lift" MATCH_MP_TAC THEN
      MATCH_MP_TAC(ISPECL
       [`W:A->bool`; `D:(A->bool)->bool`; `u:A`; `v:A`]
       GRAPH_KURATOWSKI_OBSTRUCTION_CONTRACT_IMP) THEN
      ASM_REWRITE_TAC[]]]);;

let GRAPH_MINOR_FINITE_SIMPLE = prove
 (`!V E W F.
        graph_minor (V:A->bool) E W F
        ==> finite_simple_graph V E /\ finite_simple_graph W F`,
  MESON_TAC[GRAPH_MINOR_DATA]);;

let GRAPH_MINOR_KURATOWSKI_OBSTRUCTION = prove
 (`!V E W F.
        graph_minor (V:A->bool) E W F /\
        graph_kuratowski_obstruction W F
        ==> graph_kuratowski_obstruction V E`,
  MESON_TAC[GRAPH_MINOR_DATA]);;

let GRAPH_MINOR_TRANS = prove
 (`!V E W F X H.
        graph_minor (V:A->bool) E W F /\
        graph_minor W F X H
        ==> graph_minor V E X H`,
  SUBGOAL_THEN
   `!W F X H.
        graph_minor (W:A->bool) F X H
        ==> !V E. graph_minor V E W F ==> graph_minor V E X H`
  MP_TAC THENL
   [MATCH_MP_TAC graph_minor_INDUCT THEN
    REPEAT CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC
       [`S:A->bool`; `G:(A->bool)->bool`] THEN
      DISCH_TAC THEN
      MAP_EVERY X_GEN_TAC
       [`V:A->bool`; `E:(A->bool)->bool`] THEN
      DISCH_THEN ACCEPT_TAC;
      MAP_EVERY X_GEN_TAC
       [`S:A->bool`; `G:(A->bool)->bool`;
        `W:A->bool`; `D:(A->bool)->bool`;
        `W':A->bool`; `D':(A->bool)->bool`] THEN
      INTRO_TAC "induction vertices edges" THEN
      MAP_EVERY X_GEN_TAC
       [`V:A->bool`; `E:(A->bool)->bool`] THEN
      DISCH_THEN(LABEL_TAC "left_minor") THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `W:A->bool`; `D:(A->bool)->bool`;
        `W':A->bool`; `D':(A->bool)->bool`]
       GRAPH_MINOR_SUBGRAPH) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "induction" MATCH_MP_TAC THEN
      USE_THEN "left_minor" ACCEPT_TAC;
      MAP_EVERY X_GEN_TAC
       [`S:A->bool`; `G:(A->bool)->bool`;
        `W:A->bool`; `D:(A->bool)->bool`; `u:A`; `v:A`] THEN
      INTRO_TAC "induction edge" THEN
      MAP_EVERY X_GEN_TAC
       [`V:A->bool`; `E:(A->bool)->bool`] THEN
      DISCH_THEN(LABEL_TAC "left_minor") THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `W:A->bool`; `D:(A->bool)->bool`; `u:A`; `v:A`]
       GRAPH_MINOR_CONTRACT) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "induction" MATCH_MP_TAC THEN
      USE_THEN "left_minor" ACCEPT_TAC];
    MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Suppressing subdivision vertices produces graph minors.                   *)
(* ------------------------------------------------------------------------- *)

let GRAPH_EDGE_SUBDIVISION_CONTRACT = prove
 (`!V E V' E'.
        finite_simple_graph (V:A->bool) E /\
        graph_edge_subdivision V E V' E'
        ==> ?u w.
              {w,u} IN E' /\
              V' DELETE w = V /\
              graph_contract_edges V' E' w u = E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph subdivision" THEN
  USE_THEN "subdivision" MP_TAC THEN
  REWRITE_TAC[graph_edge_subdivision] THEN
  INTRO_TAC "@u v w. edge fresh vertices edges" THEN
  MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "edges" (fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[IN_UNION] THEN DISJ1_TAC THEN
    REWRITE_TAC[IN_INSERT] THEN DISJ1_TAC THEN
    MATCH_ACCEPT_TAC(SET_RULE `{w:A,u} = {u,w}`);
    USE_THEN "vertices" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "fresh" MP_TAC THEN SET_TAC[];
    SUBGOAL_THEN
     `graph_neighbors
       ({{u:A,w},{w,v}} UNION (E DELETE {u,v})) w = {u,v}`
    (LABEL_TAC "neighbors") THENL
     [REWRITE_TAC[EXTENSION; IN_GRAPH_NEIGHBORS; IN_INSERT; IN_SING;
                  IN_UNION; IN_DELETE] THEN
      X_GEN_TAC `x:A` THEN
      USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN
      INTRO_TAC "_ _ edge_data" THEN
      EQ_TAC THENL
       [INTRO_TAC "(new | old not_replaced)" THENL
         [USE_THEN "new" MP_TAC THEN SET_TAC[];
          SUBGOAL_THEN `({w:A,x}:A->bool) SUBSET V`
          (LABEL_TAC "old_subset") THENL
           [USE_THEN "edge_data" (fun th ->
             USE_THEN "old" (fun eth ->
              MATCH_ACCEPT_TAC(CONJUNCT1
               (MATCH_MP (SPEC `{w:A,x}` th) eth))));
            USE_THEN "old_subset" MP_TAC THEN
            USE_THEN "fresh" MP_TAC THEN SET_TAC[]]];
        DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
        DISJ1_TAC THEN SET_TAC[]];
      ALL_TAC] THEN
    USE_THEN "vertices" SUBST1_TAC THEN
    USE_THEN "edges" SUBST1_TAC THEN
    REWRITE_TAC[graph_contract_edges] THEN
    SUBGOAL_THEN `(w INSERT V:A->bool) DELETE w = V`
    (fun th -> REWRITE_TAC[th]) THENL
     [USE_THEN "fresh" MP_TAC THEN SET_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`; `w:A`]
     EDGE_SUBDIVISION_INDUCED_SUBGRAPH) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "neighbors" (fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN `~(u:A = v)` (LABEL_TAC "distinct") THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `({u:A,v}:A->bool) DELETE u = {v}`
    (fun th -> REWRITE_TAC[th]) THENL
     [USE_THEN "distinct" MP_TAC THEN SET_TAC[];
      REWRITE_TAC[IMAGE_CLAUSES] THEN
      USE_THEN "edge" MP_TAC THEN SET_TAC[]]]);;

let GRAPH_EDGE_SUBDIVISION_IMP_MINOR = prove
 (`!V E V' E'.
        finite_simple_graph (V:A->bool) E /\
        graph_edge_subdivision V E V' E'
        ==> graph_minor V' E' V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph subdivision" THEN
  SUBGOAL_THEN `finite_simple_graph (V':A->bool) E'`
  (LABEL_TAC "target_graph") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `V':A->bool`; `E':(A->bool)->bool`]
     FINITE_SIMPLE_GRAPH_EDGE_SUBDIVISION) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `V':A->bool`; `E':(A->bool)->bool`]
   GRAPH_EDGE_SUBDIVISION_CONTRACT) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@u w. edge vertices edges" THEN
  USE_THEN "vertices" (fun th -> REWRITE_TAC[GSYM th]) THEN
  USE_THEN "edges" (fun th -> REWRITE_TAC[GSYM th]) THEN
  MATCH_MP_TAC(ISPECL
   [`V':A->bool`; `E':(A->bool)->bool`;
    `V':A->bool`; `E':(A->bool)->bool`; `w:A`; `u:A`]
   GRAPH_MINOR_CONTRACT) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC GRAPH_MINOR_REFL THEN
    USE_THEN "target_graph" ACCEPT_TAC;
    USE_THEN "edge" ACCEPT_TAC]);;

let GRAPH_SUBDIVISION_IMP_MINOR = prove
 (`!V E V' E'.
        graph_subdivision (V:A->bool) E V' E'
        ==> graph_minor V' E' V E`,
  MATCH_MP_TAC graph_subdivision_INDUCT THEN
  CONJ_TAC THENL
   [REPEAT GEN_TAC THEN
    DISCH_THEN(MATCH_ACCEPT_TAC o MATCH_MP GRAPH_MINOR_REFL);
    REPEAT GEN_TAC THEN INTRO_TAC "minor edge_subdivision" THEN
    MATCH_MP_TAC GRAPH_MINOR_TRANS THEN
    MAP_EVERY EXISTS_TAC [`V':A->bool`; `E':(A->bool)->bool`] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_EDGE_SUBDIVISION_IMP_MINOR THEN
      CONJ_TAC THENL
       [USE_THEN "minor" (fun th ->
         ACCEPT_TAC(CONJUNCT1(MATCH_MP
          (ISPECL
           [`V':A->bool`; `E':(A->bool)->bool`;
            `V:A->bool`; `E:(A->bool)->bool`]
           GRAPH_MINOR_FINITE_SIMPLE) th)));
        USE_THEN "edge_subdivision" ACCEPT_TAC];
      USE_THEN "minor" ACCEPT_TAC]]);;

let GRAPH_TOPOLOGICAL_SUBGRAPH_IMP_MINOR = prove
 (`!V E W D.
        finite_simple_graph (V:A->bool) E /\
        graph_topological_subgraph W D V E
        ==> graph_minor V E W D`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_topological_subgraph] THEN
  INTRO_TAC "graph (@P f. subdivision vertices edges)" THEN
  MATCH_MP_TAC GRAPH_MINOR_TRANS THEN
  MAP_EVERY EXISTS_TAC [`P:A->bool`; `f:(A->bool)->bool`] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `V:A->bool`; `E:(A->bool)->bool`;
      `P:A->bool`; `f:(A->bool)->bool`]
     GRAPH_MINOR_SUBGRAPH) THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC GRAPH_MINOR_REFL THEN
      USE_THEN "graph" ACCEPT_TAC;
      USE_THEN "vertices" ACCEPT_TAC;
      USE_THEN "edges" ACCEPT_TAC];
    MATCH_MP_TAC GRAPH_SUBDIVISION_IMP_MINOR THEN
    USE_THEN "subdivision" ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* The forbidden-minor obstruction and Wagner's theorem.                     *)
(* ------------------------------------------------------------------------- *)

let graph_wagner_obstruction = new_definition
 `graph_wagner_obstruction (V:A->bool) (E:(A->bool)->bool) <=>
      (?W:A->bool.
          W HAS_SIZE 5 /\
          graph_minor V E W (complete_graph_edges W)) \/
      (?X Y:A->bool.
          X HAS_SIZE 3 /\
          Y HAS_SIZE 3 /\
          DISJOINT X Y /\
          graph_minor
            V E (X UNION Y) (complete_bipartite_edges X Y))`;;

let GRAPH_KURATOWSKI_OBSTRUCTION_IMP_WAGNER = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E /\
        graph_kuratowski_obstruction V E
        ==> graph_wagner_obstruction V E`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_kuratowski_obstruction; graph_wagner_obstruction] THEN
  INTRO_TAC "graph obstruction" THEN
  USE_THEN "obstruction"
   (DISJ_CASES_THEN2
    (X_CHOOSE_THEN `W:A->bool`
     (X_CHOOSE_THEN `P:A->bool`
      (X_CHOOSE_THEN `f:(A->bool)->bool`
       (LABEL_TAC "witness"))))
    (X_CHOOSE_THEN `X:A->bool`
     (X_CHOOSE_THEN `Y:A->bool`
      (X_CHOOSE_THEN `P:A->bool`
       (X_CHOOSE_THEN `f:(A->bool)->bool`
        (LABEL_TAC "witness")))))) THENL
   [DISJ1_TAC THEN EXISTS_TAC `W:A->bool` THEN
    USE_THEN "witness" MP_TAC THEN
    INTRO_TAC "size subdivision vertices edges" THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC GRAPH_TOPOLOGICAL_SUBGRAPH_IMP_MINOR THEN
    ASM_REWRITE_TAC[graph_topological_subgraph] THEN
    MAP_EVERY EXISTS_TAC [`P:A->bool`; `f:(A->bool)->bool`] THEN
    ASM_REWRITE_TAC[];
    DISJ2_TAC THEN
    MAP_EVERY EXISTS_TAC [`X:A->bool`; `Y:A->bool`] THEN
    USE_THEN "witness" MP_TAC THEN
    INTRO_TAC "X_size Y_size disjoint subdivision vertices edges" THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC GRAPH_TOPOLOGICAL_SUBGRAPH_IMP_MINOR THEN
    ASM_REWRITE_TAC[graph_topological_subgraph] THEN
    MAP_EVERY EXISTS_TAC [`P:A->bool`; `f:(A->bool)->bool`] THEN
    ASM_REWRITE_TAC[]]);;

let COMPLETE_GRAPH_KURATOWSKI_OBSTRUCTION = prove
 (`!W:A->bool.
        W HAS_SIZE 5
        ==> graph_kuratowski_obstruction W (complete_graph_edges W)`,
  GEN_TAC THEN DISCH_THEN(LABEL_TAC "size") THEN
  MATCH_MP_TAC(ISPECL
   [`W:A->bool`; `complete_graph_edges (W:A->bool)`;
    `W:A->bool`; `W:A->bool`;
    `complete_graph_edges (W:A->bool)`]
   GRAPH_KURATOWSKI_OBSTRUCTION_K5) THEN
  ASM_REWRITE_TAC[SUBSET_REFL] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(CONJUNCT1 graph_subdivision_RULES) THEN
    REWRITE_TAC[FINITE_SIMPLE_GRAPH_EQ; SUBSET_REFL] THEN
    USE_THEN "size" MP_TAC THEN REWRITE_TAC[HAS_SIZE] THEN MESON_TAC[];
    REWRITE_TAC[induced_subgraph_edges] THEN
    REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_COMPLETE_GRAPH_EDGES] THEN
    MESON_TAC[]]);;

let COMPLETE_BIPARTITE_KURATOWSKI_OBSTRUCTION = prove
 (`!X Y:A->bool.
        X HAS_SIZE 3 /\ Y HAS_SIZE 3 /\ DISJOINT X Y
        ==> graph_kuratowski_obstruction
             (X UNION Y) (complete_bipartite_edges X Y)`,
  REPEAT GEN_TAC THEN INTRO_TAC "X_size Y_size disjoint" THEN
  MATCH_MP_TAC(ISPECL
   [`X UNION Y:A->bool`;
    `complete_bipartite_edges (X:A->bool) Y`;
    `X:A->bool`; `Y:A->bool`; `X UNION Y:A->bool`;
    `complete_bipartite_edges (X:A->bool) Y`]
   GRAPH_KURATOWSKI_OBSTRUCTION_K33) THEN
  ASM_REWRITE_TAC[SUBSET_REFL] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(CONJUNCT1 graph_subdivision_RULES) THEN
    MATCH_MP_TAC FINITE_SIMPLE_COMPLETE_BIPARTITE_GRAPH THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "X_size" MP_TAC THEN
    USE_THEN "Y_size" MP_TAC THEN
    REWRITE_TAC[HAS_SIZE] THEN MESON_TAC[];
    REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
    X_GEN_TAC `e:A->bool` THEN DISCH_THEN(LABEL_TAC "edge") THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "edge" MP_TAC THEN
    REWRITE_TAC[IN_COMPLETE_BIPARTITE_EDGES] THEN SET_TAC[]]);;

let GRAPH_WAGNER_OBSTRUCTION_IMP_KURATOWSKI = prove
 (`!V E.
        graph_wagner_obstruction (V:A->bool) E
        ==> graph_kuratowski_obstruction V E`,
  REPEAT GEN_TAC THEN REWRITE_TAC[graph_wagner_obstruction] THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (X_CHOOSE_THEN `W:A->bool` (LABEL_TAC "witness"))
   (X_CHOOSE_THEN `X:A->bool`
    (X_CHOOSE_THEN `Y:A->bool` (LABEL_TAC "witness")))) THENL
   [USE_THEN "witness" MP_TAC THEN INTRO_TAC "size minor" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `W:A->bool`; `complete_graph_edges (W:A->bool)`]
     GRAPH_MINOR_KURATOWSKI_OBSTRUCTION) THEN
    CONJ_TAC THENL
     [USE_THEN "minor" ACCEPT_TAC;
      MATCH_MP_TAC COMPLETE_GRAPH_KURATOWSKI_OBSTRUCTION THEN
      USE_THEN "size" ACCEPT_TAC];
    USE_THEN "witness" MP_TAC THEN
    INTRO_TAC "X_size Y_size disjoint minor" THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `X UNION Y:A->bool`;
      `complete_bipartite_edges (X:A->bool) Y`]
     GRAPH_MINOR_KURATOWSKI_OBSTRUCTION) THEN
    CONJ_TAC THENL
     [USE_THEN "minor" ACCEPT_TAC;
      MATCH_MP_TAC COMPLETE_BIPARTITE_KURATOWSKI_OBSTRUCTION THEN
      ASM_REWRITE_TAC[]]]);;

let GRAPH_WAGNER_OBSTRUCTION_EQ_KURATOWSKI = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> (graph_wagner_obstruction V E <=>
             graph_kuratowski_obstruction V E)`,
  MESON_TAC
   [GRAPH_KURATOWSKI_OBSTRUCTION_IMP_WAGNER;
    GRAPH_WAGNER_OBSTRUCTION_IMP_KURATOWSKI]);;

let PLANAR_GRAPH_MINOR = prove
 (`!V E W D.
        planar_graph (V:A->bool) E /\
        graph_minor V E W D
        ==> planar_graph W D`,
  REPEAT GEN_TAC THEN INTRO_TAC "planar minor" THEN
  SUBGOAL_THEN
   `finite_simple_graph (V:A->bool) E /\
    finite_simple_graph (W:A->bool) D`
  (CONJUNCTS_THEN2 (LABEL_TAC "source_graph")
   (LABEL_TAC "target_graph")) THENL
   [MATCH_MP_TAC GRAPH_MINOR_FINITE_SIMPLE THEN
    USE_THEN "minor" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~graph_kuratowski_obstruction (V:A->bool) E`
  (LABEL_TAC "source_obstruction_free") THENL
   [USE_THEN "source_graph" (fun th ->
     MP_TAC(MATCH_MP
      (ISPECL [`V:A->bool`; `E:(A->bool)->bool`] KURATOWSKI) th)) THEN
    USE_THEN "planar" MP_TAC THEN ITAUT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~graph_kuratowski_obstruction (W:A->bool) D`
  (LABEL_TAC "target_obstruction_free") THENL
   [DISCH_THEN(LABEL_TAC "target_obstruction") THEN
    USE_THEN "source_obstruction_free" (MATCH_MP_TAC o NOT_ELIM) THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `W:A->bool`; `D:(A->bool)->bool`]
     GRAPH_MINOR_KURATOWSKI_OBSTRUCTION) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "target_graph" (fun th ->
   MP_TAC(MATCH_MP
    (ISPECL [`W:A->bool`; `D:(A->bool)->bool`] KURATOWSKI) th)) THEN
  USE_THEN "target_obstruction_free" MP_TAC THEN ITAUT_TAC);;

let WAGNER_EULER = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> (euler_planar_graph V E <=>
             ~graph_wagner_obstruction V E)`,
  MESON_TAC
   [KURATOWSKI_EULER;
    GRAPH_WAGNER_OBSTRUCTION_EQ_KURATOWSKI]);;

let WAGNER = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> (planar_graph V E <=>
             ~graph_wagner_obstruction V E)`,
  MESON_TAC
   [KURATOWSKI;
    GRAPH_WAGNER_OBSTRUCTION_EQ_KURATOWSKI]);;

let WAGNER_STRAIGHT_LINE = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> (straight_line_planar_graph V E <=>
             ~graph_wagner_obstruction V E)`,
  MESON_TAC
   [KURATOWSKI_STRAIGHT_LINE;
    GRAPH_WAGNER_OBSTRUCTION_EQ_KURATOWSKI]);;

(* ------------------------------------------------------------------------- *)
(* Connected branch-set characterization of graph minors.                    *)
(*                                                                           *)
(* Branch sets are rooted at target vertices because graph_minor preserves   *)
(* vertex names: contraction deletes one endpoint and retains the other.     *)
(* ------------------------------------------------------------------------- *)

let graph_branch_model = new_definition
 `graph_branch_model
    (V:A->bool) (E:(A->bool)->bool)
    (W:A->bool) (D:(A->bool)->bool) (B:A->A->bool) <=>
      (!x. x IN W
           ==> x IN B x /\
               B x SUBSET V /\
               connected_graph
                (B x) (induced_subgraph_edges E (B x))) /\
      (!x y. x IN W /\ y IN W /\ ~(x = y)
             ==> DISJOINT (B x) (B y)) /\
      (!x y. {x,y} IN D
             ==> ?a b. a IN B x /\ b IN B y /\ {a,b} IN E)`;;

let CONNECTED_GRAPH_SINGLETON = prove
 (`!E:(A->bool)->bool. !x:A. connected_graph {x} E`,
  REPEAT GEN_TAC THEN REWRITE_TAC[connected_graph] THEN
  MESON_TAC[IN_SING; GRAPH_REACHABLE_REFL]);;

let INDUCED_SUBGRAPH_EDGES_VERTEX_MONO = prove
 (`!E:(A->bool)->bool. !S U:A->bool.
        S SUBSET U
        ==> induced_subgraph_edges E S SUBSET
            induced_subgraph_edges E U`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[SUBSET; IN_INDUCED_SUBGRAPH_EDGES] THEN
  MESON_TAC[SUBSET_TRANS]);;

let CONNECTED_GRAPH_INDUCED_UNION_EDGE = prove
 (`!E:(A->bool)->bool. !S U:A->bool. !a b:A.
        connected_graph S (induced_subgraph_edges E S) /\
        connected_graph U (induced_subgraph_edges E U) /\
        a IN S /\
        b IN U /\
        {a,b} IN E
        ==> connected_graph
             (S UNION U) (induced_subgraph_edges E (S UNION U))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "connected_S connected_T a_member b_member edge" THEN
  SUBGOAL_THEN
   `!x y:A.
        x IN S /\ y IN S
        ==> graph_reachable
             (induced_subgraph_edges E (S UNION U)) x y`
  (LABEL_TAC "reachable_S") THENL
   [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    INTRO_TAC "x_member y_member" THEN
    MATCH_MP_TAC(ISPECL
     [`induced_subgraph_edges E (S:A->bool):(A->bool)->bool`;
      `induced_subgraph_edges E (S UNION U):(A->bool)->bool`;
      `x:A`; `y:A`] GRAPH_REACHABLE_MONO) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC INDUCED_SUBGRAPH_EDGES_VERTEX_MONO THEN SET_TAC[];
      USE_THEN "connected_S" MP_TAC THEN
      REWRITE_TAC[connected_graph] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x y:A.
        x IN U /\ y IN U
        ==> graph_reachable
             (induced_subgraph_edges E (S UNION U)) x y`
  (LABEL_TAC "reachable_T") THENL
   [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    INTRO_TAC "x_member y_member" THEN
    MATCH_MP_TAC(ISPECL
     [`induced_subgraph_edges E (U:A->bool):(A->bool)->bool`;
      `induced_subgraph_edges E (S UNION U):(A->bool)->bool`;
      `x:A`; `y:A`] GRAPH_REACHABLE_MONO) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC INDUCED_SUBGRAPH_EDGES_VERTEX_MONO THEN SET_TAC[];
      USE_THEN "connected_T" MP_TAC THEN
      REWRITE_TAC[connected_graph] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `graph_reachable
     (induced_subgraph_edges E (S UNION U)) (a:A) b`
  (LABEL_TAC "bridge") THENL
   [MATCH_MP_TAC GRAPH_EDGE_IMP_REACHABLE THEN
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    CONJ_TAC THENL
     [USE_THEN "edge" ACCEPT_TAC;
      USE_THEN "a_member" MP_TAC THEN
      USE_THEN "b_member" MP_TAC THEN SET_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[connected_graph] THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
  REWRITE_TAC[IN_UNION] THEN
  ASM_MESON_TAC[GRAPH_REACHABLE_TRANS; GRAPH_REACHABLE_SYM]);;

let GRAPH_BRANCH_MODEL_REFL = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> graph_branch_model V E V E (\x:A. {x})`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  REWRITE_TAC[graph_branch_model] THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "member") THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[IN_SING];
      REWRITE_TAC[SING_SUBSET] THEN USE_THEN "member" ACCEPT_TAC;
      MATCH_ACCEPT_TAC
       (ISPECL
         [`induced_subgraph_edges
            (E:(A->bool)->bool) {x}:((A->bool)->bool)`;
          `x:A`] CONNECTED_GRAPH_SINGLETON)];
    MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    INTRO_TAC "_ _ distinct" THEN
    REWRITE_TAC[DISJOINT; EXTENSION; IN_INTER; NOT_IN_EMPTY; IN_SING] THEN
    ASM_MESON_TAC[];
    MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    DISCH_THEN(LABEL_TAC "edge") THEN
    MAP_EVERY EXISTS_TAC [`x:A`; `y:A`] THEN
    ASM_REWRITE_TAC[IN_SING]]);;

let GRAPH_BRANCH_MODEL_SUBGRAPH = prove
 (`!V E W D W' D' B.
        graph_branch_model (V:A->bool) E W D B /\
        W' SUBSET W /\
        D' SUBSET induced_subgraph_edges D W'
        ==> graph_branch_model V E W' D' B`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_branch_model] THEN
  INTRO_TAC "(vertices_model disjoint_model edge_model) vertices edges" THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `x:A` THEN DISCH_THEN(LABEL_TAC "member") THEN
    USE_THEN "vertices_model" MATCH_MP_TAC THEN
    USE_THEN "vertices" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
    USE_THEN "member" ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    INTRO_TAC "x_member y_member distinct" THEN
    USE_THEN "disjoint_model" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [USE_THEN "vertices" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "x_member" ACCEPT_TAC;
      USE_THEN "vertices" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
      USE_THEN "y_member" ACCEPT_TAC];
    MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    DISCH_THEN(LABEL_TAC "edge") THEN
    USE_THEN "edge_model" MATCH_MP_TAC THEN
    USE_THEN "edges" (MP_TAC o REWRITE_RULE[SUBSET]) THEN
    DISCH_THEN(MP_TAC o SPEC `{x:A,y}`) THEN
    ASM_REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[]]);;

let graph_contract_branch_sets = new_definition
 `graph_contract_branch_sets (B:A->A->bool) u v x =
    if x = v then B u UNION B v else B x`;;

let GRAPH_BRANCH_MODEL_CONTRACT = prove
 (`!V E W D B u v.
        finite_simple_graph (W:A->bool) D /\
        graph_branch_model V E W D B /\
        {u,v} IN D
        ==> graph_branch_model
             V E (W DELETE u) (graph_contract_edges W D u v)
             (graph_contract_branch_sets B u v)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_branch_model] THEN
  INTRO_TAC
   "graph (vertices_model disjoint_model edge_model) contracted_edge" THEN
  SUBGOAL_THEN `(u:A) IN W /\ (v:A) IN W /\ ~(u = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
    (LABEL_TAC "uv_distinct"))) THENL
   [MP_TAC(ISPECL
     [`W:A->bool`; `D:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `finite_simple_graph
     ((W:A->bool) DELETE u) (graph_contract_edges W D u v)`
  (LABEL_TAC "target_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_CONTRACT THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `x:A` THEN
    REWRITE_TAC[IN_DELETE] THEN
    INTRO_TAC "x_vertex x_not_u" THEN
    ASM_CASES_TAC `(x:A) = v` THENL
     [REWRITE_TAC[graph_contract_branch_sets] THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "vertices_model" (fun th ->
       USE_THEN "u_vertex" (fun uth ->
        MP_TAC(MATCH_MP (SPEC `u:A` th) uth))) THEN
      INTRO_TAC "u_root u_subset u_connected" THEN
      USE_THEN "vertices_model" (fun th ->
       USE_THEN "v_vertex" (fun vth ->
        MP_TAC(MATCH_MP (SPEC `v:A` th) vth))) THEN
      INTRO_TAC "v_root v_subset v_connected" THEN
      REPEAT CONJ_TAC THENL
       [ASM SET_TAC[];
        ASM SET_TAC[];
        USE_THEN "edge_model" (fun th ->
         USE_THEN "contracted_edge" (fun eth ->
          MP_TAC(MATCH_MP (SPECL [`u:A`; `v:A`] th) eth))) THEN
        INTRO_TAC "@a b. a_member b_member bridge" THEN
        MATCH_MP_TAC(ISPECL
         [`E:(A->bool)->bool`; `B (u:A):A->bool`;
          `B (v:A):A->bool`; `a:A`; `b:A`]
         CONNECTED_GRAPH_INDUCED_UNION_EDGE) THEN
        ASM_REWRITE_TAC[]];
      REWRITE_TAC[graph_contract_branch_sets] THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "vertices_model" MATCH_MP_TAC THEN
      USE_THEN "x_vertex" ACCEPT_TAC];
    MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    REWRITE_TAC[IN_DELETE] THEN
    DISCH_THEN(CONJUNCTS_THEN2
     (CONJUNCTS_THEN2 (LABEL_TAC "x_vertex")
      (LABEL_TAC "x_not_u"))
     (CONJUNCTS_THEN2
      (CONJUNCTS_THEN2 (LABEL_TAC "y_vertex")
       (LABEL_TAC "y_not_u"))
      (LABEL_TAC "distinct"))) THEN
    ASM_CASES_TAC `(x:A) = v` THEN
    ASM_CASES_TAC `(y:A) = v` THENL
     [ASM_MESON_TAC[];
      REWRITE_TAC[graph_contract_branch_sets] THEN
      ASM_REWRITE_TAC[DISJOINT_UNION] THEN
      CONJ_TAC THENL
       [USE_THEN "disjoint_model"
         (MP_TAC o SPECL [`u:A`; `y:A`]) THEN
        ASM_MESON_TAC[];
        USE_THEN "disjoint_model"
         (MP_TAC o SPECL [`v:A`; `y:A`]) THEN
        ASM_MESON_TAC[]];
      REWRITE_TAC[graph_contract_branch_sets] THEN
      ASM_REWRITE_TAC[] THEN
      ONCE_REWRITE_TAC[DISJOINT_SYM] THEN
      REWRITE_TAC[DISJOINT_UNION] THEN
      CONJ_TAC THENL
       [USE_THEN "disjoint_model"
         (MP_TAC o SPECL [`u:A`; `x:A`]) THEN
        ASM_MESON_TAC[];
        USE_THEN "disjoint_model"
         (MP_TAC o SPECL [`v:A`; `x:A`]) THEN
        ASM_MESON_TAC[]];
      REWRITE_TAC[graph_contract_branch_sets] THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "disjoint_model" (fun th ->
       MATCH_MP_TAC(SPECL [`x:A`; `y:A`] th)) THEN
      ASM_REWRITE_TAC[]];
    MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    DISCH_THEN(LABEL_TAC "target_edge") THEN
    SUBGOAL_THEN
     `(x:A) IN W DELETE u /\ (y:A) IN W DELETE u /\ ~(x = y)`
    (CONJUNCTS_THEN2 (LABEL_TAC "x_vertex")
     (CONJUNCTS_THEN2 (LABEL_TAC "y_vertex")
      (LABEL_TAC "xy_distinct"))) THENL
     [MP_TAC(ISPECL
       [`(W:A->bool) DELETE (u:A)`;
        `graph_contract_edges
          (W:A->bool) (D:(A->bool)->bool) (u:A) (v:A)`;
        `x:A`; `y:A`] FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS];
      ALL_TAC] THEN
    USE_THEN "target_edge" MP_TAC THEN
    REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN
    DISCH_THEN(DISJ_CASES_THEN2
     (CONJUNCTS_THEN2 (LABEL_TAC "old_edge")
      (LABEL_TAC "old_vertices"))
      (X_CHOOSE_THEN `w:A`
       (CONJUNCTS_THEN2 (LABEL_TAC "neighbor")
        (CONJUNCTS_THEN2 (LABEL_TAC "wv_distinct")
         (LABEL_TAC "edge_value"))))) THENL
     [USE_THEN "edge_model" (fun th ->
       USE_THEN "old_edge" (fun eth ->
        MP_TAC(MATCH_MP (SPECL [`x:A`; `y:A`] th) eth))) THEN
      INTRO_TAC "@a b. a_member b_member edge" THEN
      MAP_EVERY EXISTS_TAC [`a:A`; `b:A`] THEN
      REPEAT CONJ_TAC THENL
       [REWRITE_TAC[graph_contract_branch_sets] THEN
        ASM_CASES_TAC `(x:A) = v` THENL
         [UNDISCH_TAC `(x:A) = v` THEN
          DISCH_THEN SUBST_ALL_TAC THEN
          ASM_REWRITE_TAC[IN_UNION] THEN
          DISJ2_TAC THEN
          USE_THEN "a_member" ACCEPT_TAC;
          ASM_REWRITE_TAC[] THEN
          USE_THEN "a_member" ACCEPT_TAC];
        REWRITE_TAC[graph_contract_branch_sets] THEN
        ASM_CASES_TAC `(y:A) = v` THENL
         [UNDISCH_TAC `(y:A) = v` THEN
          DISCH_THEN SUBST_ALL_TAC THEN
          ASM_REWRITE_TAC[IN_UNION] THEN
          DISJ2_TAC THEN
          USE_THEN "b_member" ACCEPT_TAC;
          ASM_REWRITE_TAC[] THEN
          USE_THEN "b_member" ACCEPT_TAC];
        USE_THEN "edge" ACCEPT_TAC];
      SUBGOAL_THEN
       `(w:A) IN W /\ ~(w = u) /\ {u,w} IN D`
      (CONJUNCTS_THEN2 (LABEL_TAC "w_vertex")
       (CONJUNCTS_THEN2 (LABEL_TAC "wu_distinct")
        (LABEL_TAC "uw_edge"))) THENL
       [USE_THEN "neighbor" MP_TAC THEN
        REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN
        DISCH_THEN(LABEL_TAC "uw_edge") THEN
        USE_THEN "graph" (fun gth ->
         USE_THEN "uw_edge" (fun eth ->
          MP_TAC(MATCH_MP
           (ISPECL
             [`W:A->bool`; `D:(A->bool)->bool`; `u:A`; `w:A`]
             FINITE_SIMPLE_GRAPH_DART)
           (CONJ gth
             (REWRITE_RULE[GSYM IN_GRAPH_DARTS] eth))))) THEN
        INTRO_TAC "_ w_vertex uw_distinct" THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "w_vertex" ACCEPT_TAC;
          USE_THEN "uw_distinct" MP_TAC THEN MESON_TAC[];
          USE_THEN "uw_edge" ACCEPT_TAC];
        ALL_TAC] THEN
      USE_THEN "edge_model" (fun th ->
      USE_THEN "uw_edge" (fun eth ->
        MP_TAC(MATCH_MP (SPECL [`u:A`; `w:A`] th) eth))) THEN
      INTRO_TAC "@a b. a_member b_member edge" THEN
      USE_THEN "edge_value"
       (MP_TAC o REWRITE_RULE[PAIR_SET_EQ]) THEN
      DISCH_THEN(DISJ_CASES_THEN STRIP_ASSUME_TAC) THENL
       [MAP_EVERY EXISTS_TAC [`a:A`; `b:A`] THEN
        ASM_REWRITE_TAC[graph_contract_branch_sets; IN_UNION];
        MAP_EVERY EXISTS_TAC [`b:A`; `a:A`] THEN
        REPEAT CONJ_TAC THENL
         [REWRITE_TAC[graph_contract_branch_sets] THEN
          ASM_REWRITE_TAC[IN_UNION];
          REWRITE_TAC[graph_contract_branch_sets] THEN
          ASM_REWRITE_TAC[IN_UNION];
          ONCE_REWRITE_TAC[SET_RULE `{b:A,a} = {a,b}`] THEN
          USE_THEN "edge" ACCEPT_TAC]]]]);;

let GRAPH_MINOR_BRANCH_MODEL_DATA = prove
 (`!V E W D.
        graph_minor (V:A->bool) E W D
        ==> finite_simple_graph V E /\
            finite_simple_graph W D /\
            ?B:A->A->bool. graph_branch_model V E W D B`,
  MATCH_MP_TAC graph_minor_INDUCT THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC
     [`V:A->bool`; `E:(A->bool)->bool`] THEN
    DISCH_THEN(LABEL_TAC "graph") THEN
    ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `\x:A. {x}` THEN
    MATCH_MP_TAC GRAPH_BRANCH_MODEL_REFL THEN
    USE_THEN "graph" ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC
     [`V:A->bool`; `E:(A->bool)->bool`;
      `W:A->bool`; `D:(A->bool)->bool`;
      `W':A->bool`; `D':(A->bool)->bool`] THEN
    INTRO_TAC
     "(source_graph parent_graph (@B. model)) vertices edges" THEN
    SUBGOAL_THEN
     `finite_simple_graph
       (W':A->bool) (induced_subgraph_edges D W')`
    (LABEL_TAC "induced_graph") THENL
     [MATCH_MP_TAC(ISPECL
       [`W:A->bool`; `D:(A->bool)->bool`; `W':A->bool`]
       FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `finite_simple_graph (W':A->bool) D'`
    (LABEL_TAC "target_graph") THENL
     [MATCH_MP_TAC(ISPECL
       [`W':A->bool`; `induced_subgraph_edges D W':(A->bool)->bool`;
        `D':(A->bool)->bool`]
       FINITE_SIMPLE_GRAPH_SUBSET_EDGES) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "source_graph" ACCEPT_TAC;
      USE_THEN "target_graph" ACCEPT_TAC;
      EXISTS_TAC `B:A->A->bool` THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `W:A->bool`; `D:(A->bool)->bool`;
        `W':A->bool`; `D':(A->bool)->bool`; `B:A->A->bool`]
       GRAPH_BRANCH_MODEL_SUBGRAPH) THEN
      ASM_REWRITE_TAC[]];
    MAP_EVERY X_GEN_TAC
     [`V:A->bool`; `E:(A->bool)->bool`;
      `W:A->bool`; `D:(A->bool)->bool`; `u:A`; `v:A`] THEN
    INTRO_TAC "(source_graph parent_graph (@B. model)) edge" THEN
    SUBGOAL_THEN
     `(u:A) IN W /\ (v:A) IN W /\ ~(u = v)`
    (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
     (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
      (LABEL_TAC "distinct"))) THENL
     [MP_TAC(ISPECL
       [`W:A->bool`; `D:(A->bool)->bool`; `u:A`; `v:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `finite_simple_graph
       ((W:A->bool) DELETE u) (graph_contract_edges W D u v)`
    (LABEL_TAC "target_graph") THENL
     [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_CONTRACT THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "source_graph" ACCEPT_TAC;
      USE_THEN "target_graph" ACCEPT_TAC;
      EXISTS_TAC `graph_contract_branch_sets (B:A->A->bool) u v` THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`;
        `W:A->bool`; `D:(A->bool)->bool`;
        `B:A->A->bool`; `u:A`; `v:A`]
       GRAPH_BRANCH_MODEL_CONTRACT) THEN
      ASM_REWRITE_TAC[]]]);;

let GRAPH_MINOR_IMP_BRANCH_MODEL = prove
 (`!V E W D.
        graph_minor (V:A->bool) E W D
        ==> ?B:A->A->bool. graph_branch_model V E W D B`,
  MESON_TAC[GRAPH_MINOR_BRANCH_MODEL_DATA]);;

let GRAPH_CONTRACT_EDGES_INDUCED_SUBSET = prove
 (`!V E S u v:A.
        finite_simple_graph V E /\
        S SUBSET V /\
        u IN S /\
        v IN S /\
        ~(u = v)
        ==> graph_contract_edges S (induced_subgraph_edges E S) u v
            SUBSET
            induced_subgraph_edges
             (graph_contract_edges V E u v) (S DELETE u)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph subset u_member v_member distinct" THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `e:A->bool` THEN
  REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN
  DISCH_THEN(DISJ_CASES_THEN2
   (CONJUNCTS_THEN2 (LABEL_TAC "old_edge")
    (LABEL_TAC "old_endpoints"))
   (X_CHOOSE_THEN `w:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "local_neighbor")
     (CONJUNCTS_THEN2 (LABEL_TAC "w_not_v")
      (LABEL_TAC "edge_value"))))) THEN
  REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THENL
   [USE_THEN "old_edge" MP_TAC THEN
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    INTRO_TAC "edge _" THEN CONJ_TAC THENL
     [REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN DISJ1_TAC THEN
      CONJ_TAC THENL
       [USE_THEN "edge" ACCEPT_TAC;
        REWRITE_TAC[SUBSET; IN_DELETE] THEN X_GEN_TAC `z:A` THEN
        DISCH_THEN(LABEL_TAC "z_edge") THEN CONJ_TAC THENL
         [USE_THEN "subset" (fun subset_th ->
           USE_THEN "old_endpoints" (fun endpoints_th ->
            USE_THEN "z_edge" (fun z_th ->
             ACCEPT_TAC(MATCH_MP
              (SPEC `z:A` (REWRITE_RULE[SUBSET] subset_th))
              (CONJUNCT1(REWRITE_RULE[IN_DELETE]
               (MATCH_MP
                (SPEC `z:A` (REWRITE_RULE[SUBSET] endpoints_th))
                z_th)))))));
          USE_THEN "old_endpoints" (fun endpoints_th ->
           USE_THEN "z_edge" (fun z_th ->
            ACCEPT_TAC(CONJUNCT2(REWRITE_RULE[IN_DELETE]
             (MATCH_MP
              (SPEC `z:A` (REWRITE_RULE[SUBSET] endpoints_th))
              z_th)))))]];
      USE_THEN "old_endpoints" ACCEPT_TAC];
    USE_THEN "local_neighbor" MP_TAC THEN
    REWRITE_TAC[IN_GRAPH_NEIGHBORS; IN_INDUCED_SUBGRAPH_EDGES] THEN
    INTRO_TAC "edge edge_endpoints" THEN
    SUBGOAL_THEN `(w:A) IN graph_neighbors E u`
    (LABEL_TAC "global_neighbor") THENL
     [REWRITE_TAC[IN_GRAPH_NEIGHBORS] THEN USE_THEN "edge" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~((w:A) = u)` (LABEL_TAC "w_not_u") THENL
     [MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `w:A`]
       FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[];
      ALL_TAC] THEN
    USE_THEN "edge_value" SUBST1_TAC THEN CONJ_TAC THENL
     [REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN DISJ2_TAC THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[SET_RULE
       `{v:A,w} SUBSET S DELETE u <=>
        v IN S /\ ~(v = u) /\ w IN S /\ ~(w = u)`] THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "v_member" ACCEPT_TAC;
        USE_THEN "distinct" MP_TAC THEN MESON_TAC[];
        USE_THEN "edge_endpoints" MP_TAC THEN SET_TAC[];
        USE_THEN "w_not_u" ACCEPT_TAC]]]);;

let INDUCED_SUBGRAPH_EDGES_CONTRACT_AWAY_SUBSET = prove
 (`!V E S u v:A.
        S SUBSET V /\
        ~(u IN S)
        ==> induced_subgraph_edges E S SUBSET
            induced_subgraph_edges
             (graph_contract_edges V E u v) S`,
  REPEAT GEN_TAC THEN INTRO_TAC "subset away" THEN
  REWRITE_TAC[SUBSET] THEN X_GEN_TAC `e:A->bool` THEN
  REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
  INTRO_TAC "edge endpoints" THEN
  REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN CONJ_TAC THENL
   [REWRITE_TAC[IN_GRAPH_CONTRACT_EDGES] THEN DISJ1_TAC THEN
    CONJ_TAC THENL
     [USE_THEN "edge" ACCEPT_TAC;
      REWRITE_TAC[SUBSET; IN_DELETE] THEN X_GEN_TAC `z:A` THEN
      DISCH_THEN(LABEL_TAC "z_edge") THEN CONJ_TAC THENL
       [USE_THEN "subset" (fun subset_th ->
         USE_THEN "endpoints" (fun endpoints_th ->
          USE_THEN "z_edge" (fun z_th ->
           ACCEPT_TAC(MATCH_MP
            (SPEC `z:A` (REWRITE_RULE[SUBSET] subset_th))
            (MATCH_MP
             (SPEC `z:A` (REWRITE_RULE[SUBSET] endpoints_th))
             z_th)))));
        DISCH_THEN(LABEL_TAC "z_eq_u") THEN
        USE_THEN "away" (MATCH_MP_TAC o NOT_ELIM) THEN
        USE_THEN "z_eq_u" SUBST_ALL_TAC THEN
        USE_THEN "endpoints" (fun endpoints_th ->
         USE_THEN "z_edge" (fun z_th ->
          ACCEPT_TAC(MATCH_MP
           (SPEC `u:A` (REWRITE_RULE[SUBSET] endpoints_th))
           z_th)))]];
    USE_THEN "endpoints" ACCEPT_TAC]);;

let CONNECTED_GRAPH_INDUCED_CONTRACT = prove
 (`!V E S u v:A.
        finite_simple_graph V E /\
        S SUBSET V /\
        connected_graph S (induced_subgraph_edges E S) /\
        u IN S /\
        v IN S /\
        ~(u = v)
        ==> connected_graph
             (S DELETE u)
             (induced_subgraph_edges
               (graph_contract_edges V E u v) (S DELETE u))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph subset connected u_member v_member distinct" THEN
  MATCH_MP_TAC CONNECTED_GRAPH_MONO THEN
  EXISTS_TAC
   `graph_contract_edges
     (S:A->bool) (induced_subgraph_edges E S) u v` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC CONNECTED_GRAPH_CONTRACT THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH THEN
    EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC GRAPH_CONTRACT_EDGES_INDUCED_SUBSET THEN
    ASM_REWRITE_TAC[]]);;

let CONNECTED_GRAPH_INDUCED_CONTRACT_AWAY = prove
 (`!V E S u v:A.
        S SUBSET V /\
        connected_graph S (induced_subgraph_edges E S) /\
        ~(u IN S)
        ==> connected_graph
             S
             (induced_subgraph_edges
               (graph_contract_edges V E u v) S)`,
  REPEAT GEN_TAC THEN INTRO_TAC "subset connected away" THEN
  MATCH_MP_TAC CONNECTED_GRAPH_MONO THEN
  EXISTS_TAC `induced_subgraph_edges (E:(A->bool)->bool) S` THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC INDUCED_SUBGRAPH_EDGES_CONTRACT_AWAY_SUBSET THEN
  ASM_REWRITE_TAC[]);;

let GRAPH_CONTRACT_VERTEX_BRANCH_MEMBER = prove
 (`!V E W D B x z u v a:A.
        graph_branch_model V E W D B /\
        x IN W /\
        z IN W /\
        u IN B x /\
        v IN B x /\
        ~(u = v) /\
        a IN B z
        ==> graph_contract_vertex u v a IN B z DELETE u`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_branch_model] THEN
  INTRO_TAC
   "(_ disjoint_model _) x_vertex z_vertex u_member v_member distinct \
    a_member" THEN
  ASM_CASES_TAC `(a:A) = u` THENL
   [SUBGOAL_THEN `(z:A) = x` (LABEL_TAC "same_branch") THENL
     [MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
      DISCH_THEN(LABEL_TAC "different_branch") THEN
      USE_THEN "disjoint_model" (MP_TAC o SPECL [`x:A`; `z:A`]) THEN
      ASM_REWRITE_TAC[DISJOINT] THEN
      USE_THEN "a_member" MP_TAC THEN
      USE_THEN "u_member" MP_TAC THEN
      ASM SET_TAC[];
      USE_THEN "same_branch" SUBST_ALL_TAC THEN
      ASM_REWRITE_TAC[graph_contract_vertex; IN_DELETE]];
    ASM_REWRITE_TAC[graph_contract_vertex; IN_DELETE]]);;

let GRAPH_BRANCH_MODEL_CONTRACT_SOURCE = prove
 (`!V E W D B x u v:A.
        finite_simple_graph V E /\
        finite_simple_graph W D /\
        graph_branch_model V E W D B /\
        x IN W /\
        u IN B x /\
        ~(u = x) /\
        v IN B x /\
        {u,v} IN E
        ==> graph_branch_model
             (V DELETE u) (graph_contract_edges V E u v) W D
             (\z:A. B z DELETE u)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC
   "source_graph target_graph model \
    x_vertex u_member u_not_root v_member contracted_edge" THEN
  USE_THEN "model" MP_TAC THEN
  REWRITE_TAC[graph_branch_model] THEN
  INTRO_TAC "vertices_model disjoint_model edge_model" THEN
  SUBGOAL_THEN
   `(u:A) IN V /\ (v:A) IN V /\ ~(u = v)`
  (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
   (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
    (LABEL_TAC "distinct"))) THENL
   [MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((u:A) IN W)` (LABEL_TAC "u_not_target") THENL
   [DISCH_THEN(LABEL_TAC "u_target") THEN
    USE_THEN "vertices_model" (fun th ->
     USE_THEN "u_target" (fun uth ->
      MP_TAC(MATCH_MP (SPEC `u:A` th) uth))) THEN
    INTRO_TAC "u_root _ _" THEN
    USE_THEN "disjoint_model" (MP_TAC o SPECL [`x:A`; `u:A`]) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[];
      REWRITE_TAC[DISJOINT] THEN ASM SET_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[graph_branch_model] THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "z_vertex") THEN
    USE_THEN "vertices_model" (fun th ->
     USE_THEN "z_vertex" (fun zth ->
      MP_TAC(MATCH_MP (SPEC `z:A` th) zth))) THEN
    INTRO_TAC "z_root z_subset z_connected" THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[IN_DELETE] THEN CONJ_TAC THENL
       [USE_THEN "z_root" ACCEPT_TAC;
        DISCH_THEN(LABEL_TAC "z_eq_u") THEN
        USE_THEN "u_not_target" (MATCH_MP_TAC o NOT_ELIM) THEN
        USE_THEN "z_eq_u" (fun th -> REWRITE_TAC[GSYM th]) THEN
        USE_THEN "z_vertex" ACCEPT_TAC];
      REWRITE_TAC[SUBSET; IN_DELETE] THEN X_GEN_TAC `a:A` THEN
      INTRO_TAC "a_member a_not_u" THEN CONJ_TAC THENL
       [USE_THEN "z_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "a_member" ACCEPT_TAC;
        USE_THEN "a_not_u" ACCEPT_TAC];
      ASM_CASES_TAC `(z:A) = x` THENL
       [UNDISCH_TAC `(z:A) = x` THEN DISCH_THEN SUBST_ALL_TAC THEN
        MATCH_MP_TAC CONNECTED_GRAPH_INDUCED_CONTRACT THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "source_graph" ACCEPT_TAC;
          USE_THEN "z_subset" ACCEPT_TAC;
          USE_THEN "z_connected" ACCEPT_TAC;
          USE_THEN "u_member" ACCEPT_TAC;
          USE_THEN "v_member" ACCEPT_TAC;
          USE_THEN "distinct" ACCEPT_TAC];
        SUBGOAL_THEN `~((u:A) IN B (z:A))`
        (LABEL_TAC "u_not_in_z") THENL
         [DISCH_THEN(LABEL_TAC "u_in_z") THEN
          USE_THEN "disjoint_model" (MP_TAC o SPECL [`x:A`; `z:A`]) THEN
          ANTS_TAC THENL
           [ASM_MESON_TAC[];
            ALL_TAC] THEN
          DISCH_THEN(LABEL_TAC "xz_disjoint") THEN
          USE_THEN "xz_disjoint" MP_TAC THEN
          USE_THEN "u_member" MP_TAC THEN
          USE_THEN "u_in_z" MP_TAC THEN
          POP_ASSUM_LIST(K ALL_TAC) THEN
          REWRITE_TAC[DISJOINT] THEN SET_TAC[];
          ALL_TAC] THEN
        SUBGOAL_THEN
         `((B:A->A->bool) (z:A)) DELETE (u:A) = B z`
        (fun th -> REWRITE_TAC[th]) THENL
         [MATCH_MP_TAC(SET_RULE `~((u:A) IN s) ==> s DELETE u = s`) THEN
          USE_THEN "u_not_in_z" ACCEPT_TAC;
          ALL_TAC] THEN
        MATCH_MP_TAC CONNECTED_GRAPH_INDUCED_CONTRACT_AWAY THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "z_subset" ACCEPT_TAC;
          USE_THEN "z_connected" ACCEPT_TAC;
          USE_THEN "u_not_in_z" ACCEPT_TAC]]];
    MAP_EVERY X_GEN_TAC [`p:A`; `q:A`] THEN
    INTRO_TAC "p_vertex q_vertex different" THEN
    MATCH_MP_TAC(SET_RULE
     `DISJOINT (s:A->bool) t
      ==> DISJOINT (s DELETE u) (t DELETE u)`) THEN
    USE_THEN "disjoint_model" (fun th ->
     MATCH_MP_TAC(SPECL [`p:A`; `q:A`] th)) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "p_vertex" ACCEPT_TAC;
      USE_THEN "q_vertex" ACCEPT_TAC;
      USE_THEN "different" ACCEPT_TAC];
    MAP_EVERY X_GEN_TAC [`p:A`; `q:A`] THEN
    DISCH_THEN(LABEL_TAC "target_edge") THEN
    SUBGOAL_THEN
     `(p:A) IN W /\ (q:A) IN W /\ ~(p = q)`
    (CONJUNCTS_THEN2 (LABEL_TAC "p_vertex")
     (CONJUNCTS_THEN2 (LABEL_TAC "q_vertex")
      (LABEL_TAC "pq_distinct"))) THENL
     [MP_TAC(ISPECL
       [`W:A->bool`; `D:(A->bool)->bool`; `p:A`; `q:A`]
       FINITE_SIMPLE_GRAPH_DART) THEN
      ASM_REWRITE_TAC[IN_GRAPH_DARTS];
      ALL_TAC] THEN
    USE_THEN "edge_model" (fun th ->
     USE_THEN "target_edge" (fun eth ->
      MP_TAC(MATCH_MP (SPECL [`p:A`; `q:A`] th) eth))) THEN
    INTRO_TAC "@a b. a_member b_member edge" THEN
    SUBGOAL_THEN
     `graph_contract_vertex (u:A) v a IN
        (B:A->A->bool) (p:A) DELETE u /\
      graph_contract_vertex u v b IN B (q:A) DELETE u`
    (CONJUNCTS_THEN2 (LABEL_TAC "a_mapped")
     (LABEL_TAC "b_mapped")) THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC GRAPH_CONTRACT_VERTEX_BRANCH_MEMBER THEN
        MAP_EVERY EXISTS_TAC
         [`V:A->bool`; `E:(A->bool)->bool`;
          `W:A->bool`; `D:(A->bool)->bool`; `x:A`] THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "model" ACCEPT_TAC;
          USE_THEN "x_vertex" ACCEPT_TAC;
          USE_THEN "p_vertex" ACCEPT_TAC;
          USE_THEN "u_member" ACCEPT_TAC;
          USE_THEN "v_member" ACCEPT_TAC;
          USE_THEN "distinct" ACCEPT_TAC;
          USE_THEN "a_member" ACCEPT_TAC];
        MATCH_MP_TAC GRAPH_CONTRACT_VERTEX_BRANCH_MEMBER THEN
        MAP_EVERY EXISTS_TAC
         [`V:A->bool`; `E:(A->bool)->bool`;
          `W:A->bool`; `D:(A->bool)->bool`; `x:A`] THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "model" ACCEPT_TAC;
          USE_THEN "x_vertex" ACCEPT_TAC;
          USE_THEN "q_vertex" ACCEPT_TAC;
          USE_THEN "u_member" ACCEPT_TAC;
          USE_THEN "v_member" ACCEPT_TAC;
          USE_THEN "distinct" ACCEPT_TAC;
          USE_THEN "b_member" ACCEPT_TAC]];
      ALL_TAC] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`;
      `a:A`; `b:A`] GRAPH_CONTRACT_EDGE_HOMOMORPHISM) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "same")
      (LABEL_TAC "mapped_edge")) THENL
     [SUBGOAL_THEN
       `DISJOINT
         (((B:A->A->bool) (p:A)) DELETE (u:A))
         (B (q:A) DELETE u)`
      (LABEL_TAC "mapped_disjoint") THENL
       [MATCH_MP_TAC(SET_RULE
         `DISJOINT (s:A->bool) t
          ==> DISJOINT (s DELETE u) (t DELETE u)`) THEN
        USE_THEN "disjoint_model" (fun th ->
         MATCH_MP_TAC(SPECL [`p:A`; `q:A`] th)) THEN
        REPEAT CONJ_TAC THENL
         [USE_THEN "p_vertex" ACCEPT_TAC;
          USE_THEN "q_vertex" ACCEPT_TAC;
          USE_THEN "pq_distinct" ACCEPT_TAC];
        USE_THEN "mapped_disjoint" MP_TAC THEN
        USE_THEN "a_mapped" MP_TAC THEN
        USE_THEN "b_mapped" MP_TAC THEN
        USE_THEN "same" MP_TAC THEN
        REWRITE_TAC[DISJOINT] THEN SET_TAC[]];
      MAP_EVERY EXISTS_TAC
       [`graph_contract_vertex (u:A) v a`;
        `graph_contract_vertex (u:A) v b`] THEN
      ASM_REWRITE_TAC[]]]);;

let CONNECTED_GRAPH_INDUCED_VERTEX_EDGE = prove
 (`!V E S x u:A.
        finite_simple_graph V E /\
        S SUBSET V /\
        connected_graph S (induced_subgraph_edges E S) /\
        x IN S /\
        u IN S /\
        ~(u = x)
        ==> ?v. v IN S /\ {u,v} IN E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph subset connected root u_member u_not_root" THEN
  SUBGOAL_THEN
   `finite_simple_graph
     (S:A->bool) (induced_subgraph_edges E S)`
  (LABEL_TAC "induced_graph") THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_INDUCED_SUBGRAPH THEN
    EXISTS_TAC `V:A->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(induced_subgraph_edges (E:(A->bool)->bool) S = {})`
  (LABEL_TAC "edges_nonempty") THENL
   [DISCH_THEN(LABEL_TAC "edges_empty") THEN
    USE_THEN "connected" (fun cth ->
     USE_THEN "edges_empty" (fun eth ->
      MP_TAC(MATCH_MP
       (ISPECL [`S:A->bool`; `x:A`]
        CONNECTED_GRAPH_EMPTY_EDGES_SINGLETON)
       (CONJ (REWRITE_RULE[eth] cth)
             (ASSUME `(x:A) IN S`))))) THEN
    DISCH_THEN(LABEL_TAC "singleton") THEN
    USE_THEN "u_member" MP_TAC THEN
    USE_THEN "singleton" (fun th -> REWRITE_TAC[th; IN_SING]) THEN
    DISCH_THEN(LABEL_TAC "u_eq_x") THEN
    USE_THEN "u_not_root" (MATCH_MP_TAC o NOT_ELIM) THEN
    USE_THEN "u_eq_x" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`S:A->bool`; `induced_subgraph_edges E S:(A->bool)->bool`; `u:A`]
   CONNECTED_GRAPH_NONEMPTY_EDGE_OUTGOING_DART) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:A#A` (LABEL_TAC "outgoing")) THEN
  MP_TAC(ISPEC `d:A#A` PAIR_SURJECTIVE) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A`
   (X_CHOOSE_THEN `v:A` SUBST_ALL_TAC)) THEN
  USE_THEN "outgoing" MP_TAC THEN
  REWRITE_TAC[IN_OUTGOING_DARTS; IN_GRAPH_DARTS; FST] THEN
  INTRO_TAC "edge a_eq_u" THEN
  USE_THEN "a_eq_u" SUBST_ALL_TAC THEN
  USE_THEN "edge" MP_TAC THEN
  REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
  INTRO_TAC "edge endpoints" THEN
  EXISTS_TAC `v:A` THEN CONJ_TAC THENL
   [USE_THEN "endpoints"
     (ACCEPT_TAC o MATCH_MP
       (SET_RULE `{u:A,v} SUBSET S ==> v IN S`));
    USE_THEN "edge" ACCEPT_TAC]);;

let GRAPH_BRANCH_MODEL_IMP_MINOR = prove
 (`!V E W D B.
        finite_simple_graph (V:A->bool) E /\
        finite_simple_graph W D /\
        graph_branch_model V E W D B
        ==> graph_minor V E W D`,
  SUBGOAL_THEN
   `!n. !V E W D B.
        finite_simple_graph (V:A->bool) E /\
        finite_simple_graph W D /\
        graph_branch_model V E W D B /\
        CARD V = n
        ==> graph_minor V E W D`
  MP_TAC THENL
   [MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN
    DISCH_THEN(LABEL_TAC "induction") THEN
    REPEAT GEN_TAC THEN
    INTRO_TAC "source_graph target_graph model card" THEN
    USE_THEN "model" MP_TAC THEN
    REWRITE_TAC[graph_branch_model] THEN
    INTRO_TAC "vertices_model disjoint_model edge_model" THEN
    ASM_CASES_TAC `!x:A. x IN W ==> B x = {x}` THENL
     [FIRST_X_ASSUM(LABEL_TAC "singleton_model") THEN
      MATCH_MP_TAC GRAPH_MINOR_SUBGRAPH THEN
      MAP_EVERY EXISTS_TAC
       [`V:A->bool`; `E:(A->bool)->bool`] THEN
      REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC GRAPH_MINOR_REFL THEN
        USE_THEN "source_graph" ACCEPT_TAC;
        REWRITE_TAC[SUBSET] THEN X_GEN_TAC `p:A` THEN
        DISCH_THEN(LABEL_TAC "p_vertex") THEN
        USE_THEN "vertices_model" (fun th ->
         USE_THEN "p_vertex" (fun pth ->
          MP_TAC(MATCH_MP (SPEC `p:A` th) pth))) THEN
        INTRO_TAC "p_root p_subset _" THEN
        USE_THEN "p_subset" (MATCH_MP_TAC o REWRITE_RULE[SUBSET]) THEN
        USE_THEN "p_root" ACCEPT_TAC;
        REWRITE_TAC[SUBSET] THEN X_GEN_TAC `e:A->bool` THEN
        DISCH_THEN(LABEL_TAC "target_edge") THEN
        MP_TAC(ISPECL
         [`W:A->bool`; `D:(A->bool)->bool`; `e:A->bool`]
         FINITE_SIMPLE_GRAPH_EDGE) THEN
        ASM_REWRITE_TAC[] THEN
        INTRO_TAC "@p q. p_vertex q_vertex pq_distinct edge_value" THEN
        USE_THEN "edge_value" SUBST_ALL_TAC THEN
        REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN CONJ_TAC THENL
         [USE_THEN "edge_model" (fun th ->
           USE_THEN "target_edge" (fun eth ->
            MP_TAC(MATCH_MP (SPECL [`p:A`; `q:A`] th) eth))) THEN
          INTRO_TAC "@a b. a_member b_member edge" THEN
          USE_THEN "singleton_model" (fun th ->
           USE_THEN "p_vertex" (fun pth ->
            MP_TAC(MATCH_MP (SPEC `p:A` th) pth))) THEN
          DISCH_THEN(LABEL_TAC "p_branch") THEN
          USE_THEN "singleton_model" (fun th ->
           USE_THEN "q_vertex" (fun qth ->
            MP_TAC(MATCH_MP (SPEC `q:A` th) qth))) THEN
          DISCH_THEN(LABEL_TAC "q_branch") THEN
          USE_THEN "a_member" MP_TAC THEN
          USE_THEN "b_member" MP_TAC THEN
          USE_THEN "p_branch" (fun th -> REWRITE_TAC[th; IN_SING]) THEN
          USE_THEN "q_branch" (fun th -> REWRITE_TAC[th; IN_SING]) THEN
          DISCH_THEN SUBST_ALL_TAC THEN
          DISCH_THEN SUBST_ALL_TAC THEN
          USE_THEN "edge" ACCEPT_TAC;
          USE_THEN "p_vertex" MP_TAC THEN
          USE_THEN "q_vertex" MP_TAC THEN SET_TAC[]]];
      UNDISCH_TAC `~(!x:A. x IN W ==> B x = {x})` THEN
      REWRITE_TAC[NOT_FORALL_THM; NOT_IMP] THEN
      INTRO_TAC "@x. x_vertex nontrivial" THEN
      USE_THEN "vertices_model" (fun th ->
       USE_THEN "x_vertex" (fun xth ->
        MP_TAC(MATCH_MP (SPEC `x:A` th) xth))) THEN
      INTRO_TAC "x_root x_subset x_connected" THEN
      SUBGOAL_THEN `?u:A. u IN B x /\ ~(u = x)`
      MP_TAC THENL
       [USE_THEN "nontrivial" MP_TAC THEN
        USE_THEN "x_root" MP_TAC THEN
        POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
        INTRO_TAC "@u. u_member u_not_root"] THEN
      MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `B (x:A):A->bool`;
        `x:A`; `u:A`] CONNECTED_GRAPH_INDUCED_VERTEX_EDGE) THEN
      ASM_REWRITE_TAC[] THEN
      INTRO_TAC "@v. v_member contracted_edge" THEN
      SUBGOAL_THEN
       `(u:A) IN V /\ (v:A) IN V /\ ~(u = v)`
      (CONJUNCTS_THEN2 (LABEL_TAC "u_vertex")
       (CONJUNCTS_THEN2 (LABEL_TAC "v_vertex")
        (LABEL_TAC "distinct"))) THENL
       [MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`; `u:A`; `v:A`]
         FINITE_SIMPLE_GRAPH_DART) THEN
        ASM_REWRITE_TAC[IN_GRAPH_DARTS];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `finite_simple_graph
         ((V:A->bool) DELETE u) (graph_contract_edges V E u v)`
      (LABEL_TAC "contracted_graph") THENL
       [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_CONTRACT THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `graph_branch_model
         ((V:A->bool) DELETE u) (graph_contract_edges V E u v) W D
         (\z:A. B z DELETE u)`
      (LABEL_TAC "contracted_model") THENL
       [MATCH_MP_TAC GRAPH_BRANCH_MODEL_CONTRACT_SOURCE THEN
        MAP_EVERY EXISTS_TAC [`x:A`] THEN
        ASM_REWRITE_TAC[] THEN
        USE_THEN "model" ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `CARD((V:A->bool) DELETE u) < n`
      (LABEL_TAC "decreases") THENL
       [USE_THEN "card" (fun th -> REWRITE_TAC[GSYM th]) THEN
        MATCH_MP_TAC CARD_PSUBSET THEN CONJ_TAC THENL
         [USE_THEN "u_vertex" MP_TAC THEN
          POP_ASSUM_LIST(K ALL_TAC) THEN SET_TAC[];
          USE_THEN "source_graph"
           (ACCEPT_TAC o CONJUNCT1 o
            REWRITE_RULE[finite_simple_graph])];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `graph_minor
         ((V:A->bool) DELETE u) (graph_contract_edges V E u v) W D`
      (LABEL_TAC "tail_minor") THENL
       [USE_THEN "induction" (fun th ->
         USE_THEN "decreases" (fun dth ->
          MATCH_MP_TAC
           (SPECL
             [`(V:A->bool) DELETE u`;
              `graph_contract_edges V E u v:(A->bool)->bool`;
              `W:A->bool`; `D:(A->bool)->bool`;
              `\z:A. (B:A->A->bool) z DELETE (u:A)`]
             (MATCH_MP
              (SPEC `CARD((V:A->bool) DELETE u)` th)
              dth)))) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MATCH_MP_TAC GRAPH_MINOR_TRANS THEN
      MAP_EVERY EXISTS_TAC
       [`(V:A->bool) DELETE u`;
        `graph_contract_edges V E u v:(A->bool)->bool`] THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC GRAPH_MINOR_CONTRACT THEN
        ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC GRAPH_MINOR_REFL THEN
        USE_THEN "source_graph" ACCEPT_TAC;
        USE_THEN "tail_minor" ACCEPT_TAC]];
    DISCH_THEN(LABEL_TAC "induction") THEN
    REPEAT GEN_TAC THEN INTRO_TAC "source_graph target_graph model" THEN
    USE_THEN "induction"
     (MATCH_MP_TAC o SPECL
       [`CARD(V:A->bool)`; `V:A->bool`; `E:(A->bool)->bool`;
        `W:A->bool`; `D:(A->bool)->bool`; `B:A->A->bool`]) THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_MINOR_BRANCH_MODEL = prove
 (`!V E W D.
        finite_simple_graph (V:A->bool) E /\
        finite_simple_graph W D
        ==> (graph_minor V E W D <=>
             ?B:A->A->bool. graph_branch_model V E W D B)`,
  MESON_TAC[GRAPH_MINOR_IMP_BRANCH_MODEL; GRAPH_BRANCH_MODEL_IMP_MINOR]);;

(* ------------------------------------------------------------------------- *)
(* A compact API for connected branch-set models.                            *)
(* ------------------------------------------------------------------------- *)

let GRAPH_BRANCH_MODEL_CONG = prove
 (`!V E W D B C.
        finite_simple_graph (W:A->bool) D /\
        (!x. x IN W ==> B x = C x)
        ==> (graph_branch_model V E W D B <=>
             graph_branch_model V E W D C)`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph same" THEN
  SUBGOAL_THEN
   `!x y:A. {x,y} IN D ==> x IN W /\ y IN W`
  (LABEL_TAC "endpoints") THENL
   [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
    DISCH_THEN(LABEL_TAC "edge") THEN
    MP_TAC(ISPECL
     [`W:A->bool`; `D:(A->bool)->bool`; `x:A`; `y:A`]
     FINITE_SIMPLE_GRAPH_DART) THEN
    ASM_REWRITE_TAC[IN_GRAPH_DARTS] THEN MESON_TAC[];
    REWRITE_TAC[graph_branch_model] THEN ASM_MESON_TAC[]]);;

let GRAPH_BRANCH_MODEL_RESTRICT = prove
 (`!V E W D U B.
        graph_branch_model (V:A->bool) E W D B /\
        U SUBSET W
        ==> graph_branch_model
             V E U (induced_subgraph_edges D U) B`,
  REPEAT GEN_TAC THEN INTRO_TAC "model subset" THEN
  MATCH_MP_TAC GRAPH_BRANCH_MODEL_SUBGRAPH THEN
  MAP_EVERY EXISTS_TAC [`W:A->bool`; `D:(A->bool)->bool`] THEN
  ASM_REWRITE_TAC[SUBSET_REFL]);;

let GRAPH_BRANCH_MODEL_COMPOSE = prove
 (`!V E W D X H B C.
        finite_simple_graph (V:A->bool) E /\
        finite_simple_graph W D /\
        finite_simple_graph X H /\
        graph_branch_model V E W D B /\
        graph_branch_model W D X H C
        ==> ?M:A->A->bool. graph_branch_model V E X H M`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "source_graph middle_graph target_graph first second" THEN
  MATCH_MP_TAC GRAPH_MINOR_IMP_BRANCH_MODEL THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `W:A->bool`; `D:(A->bool)->bool`;
    `X:A->bool`; `H:(A->bool)->bool`]
   GRAPH_MINOR_TRANS) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `W:A->bool`; `D:(A->bool)->bool`; `B:A->A->bool`]
     GRAPH_BRANCH_MODEL_IMP_MINOR) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`W:A->bool`; `D:(A->bool)->bool`;
      `X:A->bool`; `H:(A->bool)->bool`; `C:A->A->bool`]
     GRAPH_BRANCH_MODEL_IMP_MINOR) THEN
    ASM_REWRITE_TAC[]]);;

let IMAGE_IMAGE_LEFT_INVERSE = prove
 (`!f:A->B. !g:B->A.
        (!x. g(f x) = x)
        ==> !s:A->bool. IMAGE g (IMAGE f s) = s`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "left_inverse") THEN
  GEN_TAC THEN REWRITE_TAC[EXTENSION; IN_IMAGE] THEN ASM_MESON_TAC[]);;

let CONNECTED_GRAPH_INDUCED_IMAGE = prove
 (`!f:A->B. !E:(A->bool)->bool. !S:A->bool.
        connected_graph S (induced_subgraph_edges E S)
        ==> connected_graph
             (IMAGE f S)
             (induced_subgraph_edges
               (IMAGE (IMAGE f) E) (IMAGE f S))`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[connected_graph] THEN
  DISCH_THEN(LABEL_TAC "connected") THEN
  MAP_EVERY X_GEN_TAC [`x:B`; `y:B`] THEN
  REWRITE_TAC[IN_IMAGE] THEN
  INTRO_TAC "(@a. x_image a_member) (@b. y_image b_member)" THEN
  USE_THEN "x_image" SUBST_ALL_TAC THEN
  USE_THEN "y_image" SUBST_ALL_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`induced_subgraph_edges
      (E:(A->bool)->bool) (S:A->bool):(A->bool)->bool`;
    `induced_subgraph_edges
      (IMAGE (IMAGE (f:A->B)) E) (IMAGE f S):(B->bool)->bool`;
    `f:A->B`; `a:A`; `b:A`]
   GRAPH_REACHABLE_HOMOMORPHISM) THEN
  CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `v:A`] THEN
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN
    INTRO_TAC "edge endpoints" THEN DISJ2_TAC THEN
    REWRITE_TAC[IN_INDUCED_SUBGRAPH_EDGES] THEN CONJ_TAC THENL
     [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `{u:A,v}` THEN
      ASM_REWRITE_TAC[IMAGE_CLAUSES];
      USE_THEN "endpoints" MP_TAC THEN SET_TAC[]];
    USE_THEN "connected" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

let graph_branch_model_image = new_definition
 `graph_branch_model_image
    (f:A->B) (g:B->A) (M:A->A->bool) y =
    IMAGE f (M (g y))`;;

let GRAPH_BRANCH_MODEL_IMAGE = prove
 (`!f:A->B. !g:B->A. !V E W D M.
        (!x. g(f x) = x) /\
        graph_branch_model V E W D M
        ==> graph_branch_model
             (IMAGE f V) (IMAGE (IMAGE f) E)
             (IMAGE f W) (IMAGE (IMAGE f) D)
             (graph_branch_model_image f g M)`,
  REPEAT GEN_TAC THEN INTRO_TAC "left_inverse model" THEN
  SUBGOAL_THEN
   `!x y:A. (f:A->B) x = f y ==> x = y`
  (LABEL_TAC "injective") THENL
   [ASM_MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "model" MP_TAC THEN
  REWRITE_TAC[graph_branch_model] THEN
  INTRO_TAC "branch_data disjoint_data edge_data" THEN
  REWRITE_TAC[graph_branch_model] THEN
  REPEAT CONJ_TAC THENL
   [X_GEN_TAC `y:B` THEN REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@x. y_image x_vertex" THEN
    USE_THEN "y_image" SUBST_ALL_TAC THEN
    REWRITE_TAC[graph_branch_model_image] THEN
    USE_THEN "left_inverse" (fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "branch_data" (fun th ->
     USE_THEN "x_vertex" (fun xth ->
      MP_TAC(MATCH_MP (SPEC `x:A` th) xth))) THEN
    INTRO_TAC "root subset connected" THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `x:A` THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC IMAGE_SUBSET THEN USE_THEN "subset" ACCEPT_TAC;
      MATCH_MP_TAC CONNECTED_GRAPH_INDUCED_IMAGE THEN
      USE_THEN "connected" ACCEPT_TAC];
    MAP_EVERY X_GEN_TAC [`y:B`; `z:B`] THEN
    REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC
     "(@x. y_image x_vertex) (@w. z_image w_vertex) distinct" THEN
    USE_THEN "y_image" SUBST_ALL_TAC THEN
    USE_THEN "z_image" SUBST_ALL_TAC THEN
    REWRITE_TAC[graph_branch_model_image] THEN
    USE_THEN "left_inverse" (fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC DISJOINT_IMAGE_INJECTIVE THEN CONJ_TAC THENL
     [USE_THEN "injective" ACCEPT_TAC;
      USE_THEN "disjoint_data" (fun th ->
       MATCH_MP_TAC(SPECL [`x:A`; `w:A`] th)) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "distinct" MP_TAC THEN MESON_TAC[]];
    MAP_EVERY X_GEN_TAC [`y:B`; `z:B`] THEN
    REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@d. edge_image source_edge" THEN
    SUBGOAL_THEN
     `(?a:A. a IN d /\ (f:A->B) a = y) /\
      (?b:A. b IN d /\ f b = z)`
    (CONJUNCTS_THEN2
      (X_CHOOSE_THEN `a:A`
       (CONJUNCTS_THEN2 (LABEL_TAC "a_member")
        (LABEL_TAC "a_image")))
      (X_CHOOSE_THEN `b:A`
       (CONJUNCTS_THEN2 (LABEL_TAC "b_member")
        (LABEL_TAC "b_image")))) THENL
     [USE_THEN "edge_image" MP_TAC THEN
      REWRITE_TAC[EXTENSION; IN_IMAGE; IN_INSERT; IN_SING] THEN
      MESON_TAC[];
      ALL_TAC] THEN
    USE_THEN "a_image" (SUBST_ALL_TAC o SYM) THEN
    USE_THEN "b_image" (SUBST_ALL_TAC o SYM) THEN
    SUBGOAL_THEN `(d:A->bool) = {a,b}` SUBST_ALL_TAC THENL
     [USE_THEN "injective" (fun th ->
       MATCH_MP_TAC
        (SPECL [`d:A->bool`; `{a:A,b}`]
          (MATCH_MP (SPEC `f:A->B` IMAGE_SET_INJECTIVE) th))) THEN
      USE_THEN "edge_image"
       (fun th -> REWRITE_TAC[th; IMAGE_CLAUSES]);
      ALL_TAC] THEN
    USE_THEN "edge_data" (fun th ->
     USE_THEN "source_edge" (fun eth ->
      MP_TAC(MATCH_MP (SPECL [`a:A`; `b:A`] th) eth))) THEN
    INTRO_TAC "@p q. p_member q_member edge" THEN
    MAP_EVERY EXISTS_TAC [`(f:A->B) p`; `(f:A->B) q`] THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[graph_branch_model_image] THEN
      USE_THEN "left_inverse" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `p:A` THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[graph_branch_model_image] THEN
      USE_THEN "left_inverse" (fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `q:A` THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[IN_IMAGE] THEN EXISTS_TAC `{p:A,q}` THEN
      ASM_REWRITE_TAC[IMAGE_CLAUSES]]]);;

let GRAPH_BRANCH_MODEL_IMAGE_EQ = prove
 (`!f:A->B. !g:B->A. !V E W D M.
        (!x. g(f x) = x) /\
        (!y. f(g y) = y)
        ==> (graph_branch_model
              (IMAGE f V) (IMAGE (IMAGE f) E)
              (IMAGE f W) (IMAGE (IMAGE f) D)
              (graph_branch_model_image f g M) <=>
             graph_branch_model V E W D M)`,
  REPEAT GEN_TAC THEN INTRO_TAC "left_inverse right_inverse" THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "image_model") THEN
    SUBGOAL_THEN
     `graph_branch_model
       (IMAGE (g:B->A) (IMAGE (f:A->B) V))
       (IMAGE (IMAGE g) (IMAGE (IMAGE f) E))
       (IMAGE g (IMAGE f W))
       (IMAGE (IMAGE g) (IMAGE (IMAGE f) D))
       (graph_branch_model_image
         g f (graph_branch_model_image f g M))`
    (LABEL_TAC "renamed_back") THENL
     [MATCH_MP_TAC(ISPECL
       [`g:B->A`; `f:A->B`;
        `IMAGE (f:A->B) V:B->bool`;
        `IMAGE (IMAGE (f:A->B)) E:(B->bool)->bool`;
        `IMAGE (f:A->B) W:B->bool`;
        `IMAGE (IMAGE (f:A->B)) D:(B->bool)->bool`;
        `graph_branch_model_image
          (f:A->B) (g:B->A) M:B->B->bool`]
       GRAPH_BRANCH_MODEL_IMAGE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!s:A->bool. IMAGE (g:B->A) (IMAGE (f:A->B) s) = s`
    (LABEL_TAC "set_inverse") THENL
     [MATCH_MP_TAC IMAGE_IMAGE_LEFT_INVERSE THEN
      USE_THEN "left_inverse" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!S:(A->bool)->bool.
        IMAGE (IMAGE (g:B->A)) (IMAGE (IMAGE (f:A->B)) S) = S`
    (LABEL_TAC "edge_inverse") THENL
     [MATCH_MP_TAC IMAGE_IMAGE_LEFT_INVERSE THEN
      USE_THEN "set_inverse" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `graph_branch_model_image
       (g:B->A) (f:A->B) (graph_branch_model_image f g M) = M`
    (LABEL_TAC "branch_inverse") THENL
     [REWRITE_TAC[FUN_EQ_THM; graph_branch_model_image] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "set_inverse" (fun th ->
     USE_THEN "edge_inverse" (fun eth ->
      USE_THEN "branch_inverse" (fun bth ->
       USE_THEN "renamed_back" (fun rth ->
        ACCEPT_TAC(REWRITE_RULE
         [SPEC `V:A->bool` th; SPEC `W:A->bool` th;
          SPEC `E:(A->bool)->bool` eth;
          SPEC `D:(A->bool)->bool` eth; bth] rth)))));
    DISCH_THEN(LABEL_TAC "model") THEN
    MATCH_MP_TAC(ISPECL
     [`f:A->B`; `g:B->A`;
      `V:A->bool`; `E:(A->bool)->bool`;
      `W:A->bool`; `D:(A->bool)->bool`;
      `M:A->A->bool`]
     GRAPH_BRANCH_MODEL_IMAGE) THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_MINOR_IMAGE = prove
 (`!f:A->B. !g:B->A. !V E W D.
        (!x. g(f x) = x) /\
        graph_minor V E W D
        ==> graph_minor
             (IMAGE f V) (IMAGE (IMAGE f) E)
             (IMAGE f W) (IMAGE (IMAGE f) D)`,
  REPEAT GEN_TAC THEN INTRO_TAC "left_inverse minor" THEN
  SUBGOAL_THEN
   `!x y:A. (f:A->B) x = f y ==> x = y`
  (LABEL_TAC "injective") THENL
   [ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `W:A->bool`; `D:(A->bool)->bool`]
   GRAPH_MINOR_FINITE_SIMPLE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "source_graph target_graph" THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `W:A->bool`; `D:(A->bool)->bool`]
   GRAPH_MINOR_IMP_BRANCH_MODEL) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `M:A->A->bool` (LABEL_TAC "model")) THEN
  MATCH_MP_TAC(ISPECL
   [`IMAGE (f:A->B) V:B->bool`;
    `IMAGE (IMAGE (f:A->B)) E:(B->bool)->bool`;
    `IMAGE (f:A->B) W:B->bool`;
    `IMAGE (IMAGE (f:A->B)) D:(B->bool)->bool`;
    `graph_branch_model_image
      (f:A->B) (g:B->A) (M:A->A->bool):B->B->bool`]
   GRAPH_BRANCH_MODEL_IMP_MINOR) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`f:A->B`; `V:A->bool`; `E:(A->bool)->bool`]
     FINITE_SIMPLE_GRAPH_IMAGE) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`f:A->B`; `W:A->bool`; `D:(A->bool)->bool`]
     FINITE_SIMPLE_GRAPH_IMAGE) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
     [`f:A->B`; `g:B->A`;
      `V:A->bool`; `E:(A->bool)->bool`;
      `W:A->bool`; `D:(A->bool)->bool`;
      `M:A->A->bool`]
     GRAPH_BRANCH_MODEL_IMAGE) THEN
    ASM_REWRITE_TAC[]]);;

let GRAPH_MINOR_IMAGE_EQ = prove
 (`!f:A->B. !g:B->A. !V E W D.
        (!x. g(f x) = x) /\
        (!y. f(g y) = y)
        ==> (graph_minor
              (IMAGE f V) (IMAGE (IMAGE f) E)
              (IMAGE f W) (IMAGE (IMAGE f) D) <=>
             graph_minor V E W D)`,
  REPEAT GEN_TAC THEN INTRO_TAC "left_inverse right_inverse" THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "image_minor") THEN
    SUBGOAL_THEN
    `graph_minor
       (IMAGE (g:B->A) (IMAGE (f:A->B) V))
       (IMAGE (IMAGE g) (IMAGE (IMAGE f) E))
       (IMAGE g (IMAGE f W))
       (IMAGE (IMAGE g) (IMAGE (IMAGE f) D))`
    (LABEL_TAC "renamed_back") THENL
     [MATCH_MP_TAC(ISPECL
       [`g:B->A`; `f:A->B`;
        `IMAGE (f:A->B) V:B->bool`;
        `IMAGE (IMAGE (f:A->B)) E:(B->bool)->bool`;
        `IMAGE (f:A->B) W:B->bool`;
        `IMAGE (IMAGE (f:A->B)) D:(B->bool)->bool`]
       GRAPH_MINOR_IMAGE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!s:A->bool. IMAGE (g:B->A) (IMAGE (f:A->B) s) = s`
    (LABEL_TAC "set_inverse") THENL
     [MATCH_MP_TAC IMAGE_IMAGE_LEFT_INVERSE THEN
      USE_THEN "left_inverse" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!S:(A->bool)->bool.
        IMAGE (IMAGE (g:B->A)) (IMAGE (IMAGE (f:A->B)) S) = S`
    (LABEL_TAC "edge_inverse") THENL
     [MATCH_MP_TAC IMAGE_IMAGE_LEFT_INVERSE THEN
      USE_THEN "set_inverse" ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "set_inverse" (fun th ->
     USE_THEN "edge_inverse" (fun eth ->
      USE_THEN "renamed_back" (fun rth ->
       ACCEPT_TAC(REWRITE_RULE
        [SPEC `V:A->bool` th; SPEC `W:A->bool` th;
         SPEC `E:(A->bool)->bool` eth;
         SPEC `D:(A->bool)->bool` eth] rth))));
    DISCH_THEN(LABEL_TAC "minor") THEN
    MATCH_MP_TAC(ISPECL
     [`f:A->B`; `g:B->A`;
      `V:A->bool`; `E:(A->bool)->bool`;
      `W:A->bool`; `D:(A->bool)->bool`]
     GRAPH_MINOR_IMAGE) THEN
    ASM_REWRITE_TAC[]]);;

let graph_wagner_branch_obstruction = new_definition
 `graph_wagner_branch_obstruction
    (V:A->bool) (E:(A->bool)->bool) <=>
      (?W B.
          W HAS_SIZE 5 /\
          graph_branch_model V E W (complete_graph_edges W) B) \/
      (?X Y B.
          X HAS_SIZE 3 /\
          Y HAS_SIZE 3 /\
          DISJOINT X Y /\
          graph_branch_model
            V E (X UNION Y) (complete_bipartite_edges X Y) B)`;;

let GRAPH_WAGNER_BRANCH_OBSTRUCTION_IMP_WAGNER = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E /\
        graph_wagner_branch_obstruction V E
        ==> graph_wagner_obstruction V E`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_wagner_branch_obstruction; graph_wagner_obstruction] THEN
  INTRO_TAC "source_graph obstruction" THEN
  USE_THEN "obstruction"
   (DISJ_CASES_THEN2
    (X_CHOOSE_THEN `W:A->bool`
     (X_CHOOSE_THEN `B:A->A->bool` (LABEL_TAC "witness")))
    (X_CHOOSE_THEN `X:A->bool`
     (X_CHOOSE_THEN `Y:A->bool`
      (X_CHOOSE_THEN `B:A->A->bool` (LABEL_TAC "witness"))))) THENL
   [DISJ1_TAC THEN EXISTS_TAC `W:A->bool` THEN
    USE_THEN "witness" MP_TAC THEN INTRO_TAC "size model" THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `W:A->bool`; `complete_graph_edges (W:A->bool)`;
      `B:A->A->bool`]
     GRAPH_BRANCH_MODEL_IMP_MINOR) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC FINITE_SIMPLE_COMPLETE_GRAPH THEN
    USE_THEN "size" MP_TAC THEN REWRITE_TAC[HAS_SIZE] THEN MESON_TAC[];
    DISJ2_TAC THEN
    MAP_EVERY EXISTS_TAC [`X:A->bool`; `Y:A->bool`] THEN
    USE_THEN "witness" MP_TAC THEN
    INTRO_TAC "X_size Y_size disjoint model" THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `X UNION Y:A->bool`;
      `complete_bipartite_edges (X:A->bool) Y`;
      `B:A->A->bool`]
     GRAPH_BRANCH_MODEL_IMP_MINOR) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC FINITE_SIMPLE_COMPLETE_BIPARTITE_GRAPH THEN
    USE_THEN "X_size" MP_TAC THEN USE_THEN "Y_size" MP_TAC THEN
    REWRITE_TAC[HAS_SIZE] THEN ASM_MESON_TAC[]]);;

let GRAPH_WAGNER_OBSTRUCTION_IMP_BRANCH_OBSTRUCTION = prove
 (`!V E.
        graph_wagner_obstruction (V:A->bool) E
        ==> graph_wagner_branch_obstruction V E`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[graph_wagner_obstruction; graph_wagner_branch_obstruction] THEN
  MESON_TAC[GRAPH_MINOR_IMP_BRANCH_MODEL]);;

let GRAPH_WAGNER_BRANCH_OBSTRUCTION_EQ = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> (graph_wagner_branch_obstruction V E <=>
             graph_wagner_obstruction V E)`,
  MESON_TAC
   [GRAPH_WAGNER_BRANCH_OBSTRUCTION_IMP_WAGNER;
    GRAPH_WAGNER_OBSTRUCTION_IMP_BRANCH_OBSTRUCTION]);;

let WAGNER_BRANCH = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> (planar_graph V E <=>
             ~graph_wagner_branch_obstruction V E)`,
  MESON_TAC[WAGNER; GRAPH_WAGNER_BRANCH_OBSTRUCTION_EQ]);;

let WAGNER_BRANCH_EULER = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> (euler_planar_graph V E <=>
             ~graph_wagner_branch_obstruction V E)`,
  MESON_TAC[WAGNER_EULER; GRAPH_WAGNER_BRANCH_OBSTRUCTION_EQ]);;

let WAGNER_BRANCH_STRAIGHT_LINE = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> (straight_line_planar_graph V E <=>
             ~graph_wagner_branch_obstruction V E)`,
  MESON_TAC[WAGNER_STRAIGHT_LINE; GRAPH_WAGNER_BRANCH_OBSTRUCTION_EQ]);;

let K5_BRANCH_MODEL_OBSTRUCTS_PLANARITY = prove
 (`!V E W B.
        finite_simple_graph (V:A->bool) E /\
        W HAS_SIZE 5 /\
        graph_branch_model V E W (complete_graph_edges W) B
        ==> ~planar_graph V E`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph size model" THEN
  USE_THEN "graph" (fun th ->
   MP_TAC(MATCH_MP
    (ISPECL [`V:A->bool`; `E:(A->bool)->bool`] WAGNER_BRANCH) th)) THEN
  REWRITE_TAC[graph_wagner_branch_obstruction] THEN ASM_MESON_TAC[]);;

let K33_BRANCH_MODEL_OBSTRUCTS_PLANARITY = prove
 (`!V E X Y B.
        finite_simple_graph (V:A->bool) E /\
        X HAS_SIZE 3 /\
        Y HAS_SIZE 3 /\
        DISJOINT X Y /\
        graph_branch_model
          V E (X UNION Y) (complete_bipartite_edges X Y) B
        ==> ~planar_graph V E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "graph X_size Y_size disjoint model" THEN
  USE_THEN "graph" (fun th ->
   MP_TAC(MATCH_MP
    (ISPECL [`V:A->bool`; `E:(A->bool)->bool`] WAGNER_BRANCH) th)) THEN
  REWRITE_TAC[graph_wagner_branch_obstruction] THEN ASM_MESON_TAC[]);;

(* ========================================================================= *)
(* Reusable degree, transport, and closure interfaces.                       *)
(* ========================================================================= *)

(* ------------------------------------------------------------------------- *)
(* Vertex degrees and the handshaking theorem.                               *)
(* ------------------------------------------------------------------------- *)

let graph_degree = new_definition
 `graph_degree (E:(A->bool)->bool) v = CARD(graph_neighbors E v)`;;

let GRAPH_DEGREE_OUTGOING_DARTS = prove
 (`!V E v:A.
        finite_simple_graph V E
        ==> graph_degree E v = CARD(outgoing_darts E v)`,
  MESON_TAC[graph_degree; CARD_OUTGOING_DARTS]);;

let GRAPH_NEIGHBORS_INDUCED_SUBGRAPH = prove
 (`!E W v:A.
        v IN W
        ==> graph_neighbors (induced_subgraph_edges E W) v =
            graph_neighbors E v INTER W`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "vertex") THEN
  REWRITE_TAC[EXTENSION; IN_GRAPH_NEIGHBORS;
              IN_INDUCED_SUBGRAPH_EDGES; IN_INTER] THEN
  ASM SET_TAC[]);;

let GRAPH_DEGREE_INDUCED_SUBGRAPH = prove
 (`!E W v:A.
        v IN W
        ==> graph_degree (induced_subgraph_edges E W) v =
            CARD(graph_neighbors E v INTER W)`,
  SIMP_TAC[graph_degree; GRAPH_NEIGHBORS_INDUCED_SUBGRAPH]);;

let GRAPH_DEGREE_OUTSIDE = prove
 (`!V E v:A.
        finite_simple_graph V E /\ ~(v IN V)
        ==> graph_degree E v = 0`,
  REPEAT GEN_TAC THEN INTRO_TAC "graph outside" THEN
  SUBGOAL_THEN `FINITE(graph_neighbors (E:(A->bool)->bool) (v:A))`
  (LABEL_TAC "finite_neighbors") THENL
   [MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `v:A`]
     FINITE_GRAPH_NEIGHBORS) THEN
    USE_THEN "graph" ACCEPT_TAC;
    ALL_TAC] THEN
  ASM_SIMP_TAC[graph_degree; CARD_EQ_0] THEN
  REWRITE_TAC[EXTENSION; NOT_IN_EMPTY] THEN
  X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "neighbor") THEN
  USE_THEN "outside" (MATCH_MP_TAC o NOT_ELIM) THEN
  MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `v:A`; `u:A`]
   FINITE_SIMPLE_GRAPH_NEIGHBOR) THEN
  ASM_REWRITE_TAC[] THEN MESON_TAC[]);;

let GRAPH_DEGREE_LE_CARD_DELETE = prove
 (`!V E v:A.
        finite_simple_graph V E
        ==> graph_degree E v <= CARD(V DELETE v)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  REWRITE_TAC[graph_degree] THEN
  MATCH_MP_TAC CARD_SUBSET THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_NEIGHBORS_SUBSET_DELETE THEN
    USE_THEN "graph" ACCEPT_TAC;
    USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph; FINITE_DELETE] THEN MESON_TAC[]]);;

let GRAPH_DEGREE_LE_CARD = prove
 (`!V E v:A.
        finite_simple_graph V E
        ==> graph_degree E v <= CARD V`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  TRANS_TAC LE_TRANS `CARD(V DELETE (v:A))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC GRAPH_DEGREE_LE_CARD_DELETE THEN
    USE_THEN "graph" ACCEPT_TAC;
    MATCH_MP_TAC CARD_SUBSET THEN
    CONJ_TAC THENL
     [SET_TAC[];
      USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[]]]);;

let GRAPH_DARTS_UNIONS_OUTGOING_DARTS = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> graph_darts E = UNIONS(IMAGE (outgoing_darts E) V)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  REWRITE_TAC[EXTENSION; IN_UNIONS; IN_IMAGE] THEN
  X_GEN_TAC `d:A#A` THEN EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "dart") THEN
    EXISTS_TAC `outgoing_darts E (FST(d:A#A))` THEN
    CONJ_TAC THENL
     [EXISTS_TAC `FST(d:A#A)` THEN
      CONJ_TAC THENL
       [SET_TAC[];
        MP_TAC(ISPECL
         [`V:A->bool`; `E:(A->bool)->bool`;
          `FST(d:A#A)`; `SND(d:A#A)`]
         FINITE_SIMPLE_GRAPH_DART) THEN
        ASM_REWRITE_TAC[PAIR] THEN MESON_TAC[]];
      REWRITE_TAC[IN_OUTGOING_DARTS] THEN
      ASM_REWRITE_TAC[]];
    INTRO_TAC "@s. (@v. outgoing vertex) dart" THEN
    ASM_MESON_TAC[IN_OUTGOING_DARTS]]);;

let CARD_GRAPH_DARTS_AS_DEGREE_SUM = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> CARD(graph_darts E) = nsum V (graph_degree E)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `CARD(UNIONS(IMAGE (outgoing_darts E) V)) =
    nsum V (\v:A. CARD(outgoing_darts E v))`
  (LABEL_TAC "partition") THENL
   [MATCH_MP_TAC CARD_UNIONS_IMAGE THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
     [X_GEN_TAC `v:A` THEN DISCH_TAC THEN
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E:(A->bool)->bool`; `v:A`]
       FINITE_OUTGOING_DARTS) THEN
      USE_THEN "graph" ACCEPT_TAC;
      MAP_EVERY X_GEN_TAC [`u:A`; `v:A`] THEN
      INTRO_TAC "u_vertex v_vertex distinct" THEN
      REWRITE_TAC[EXTENSION; IN_INTER; NOT_IN_EMPTY] THEN
      X_GEN_TAC `d:A#A` THEN
      DISCH_THEN(MP_TAC o MATCH_MP
       (ISPECL
        [`E:(A->bool)->bool`; `u:A`; `v:A`; `d:A#A`]
        OUTGOING_DARTS_TAIL_UNIQUE)) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  TRANS_TAC EQ_TRANS
   `nsum V (\v:A. CARD(outgoing_darts E v))` THEN
  CONJ_TAC THENL
   [ASM_MESON_TAC[GRAPH_DARTS_UNIONS_OUTGOING_DARTS];
    MATCH_MP_TAC NSUM_EQ THEN
    X_GEN_TAC `v:A` THEN DISCH_TAC THEN BETA_TAC THEN
    MATCH_MP_TAC EQ_SYM THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `v:A`]
     GRAPH_DEGREE_OUTGOING_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC]);;

let FINITE_SIMPLE_GRAPH_HANDSHAKING = prove
 (`!V E.
        finite_simple_graph (V:A->bool) E
        ==> nsum V (graph_degree E) = 2 * CARD E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "graph") THEN
  TRANS_TAC EQ_TRANS
   `CARD(graph_darts (E:(A->bool)->bool))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC EQ_SYM THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`]
     CARD_GRAPH_DARTS_AS_DEGREE_SUM) THEN
    USE_THEN "graph" ACCEPT_TAC;
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`]
     CARD_GRAPH_DARTS) THEN
    USE_THEN "graph" ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* Low-degree vertices and degeneracy.                                       *)
(* ------------------------------------------------------------------------- *)

let PLANAR_GRAPH_LOW_DEGREE = prove
 (`!V E.
        planar_graph (V:A->bool) E /\ ~(V = {})
        ==> ?v. v IN V /\ graph_degree E v <= 5`,
  REPEAT GEN_TAC THEN INTRO_TAC "planar nonempty" THEN
  SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
  (LABEL_TAC "graph") THENL
   [USE_THEN "planar" MP_TAC THEN
    REWRITE_TAC[planar_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `FINITE(V:A->bool)` (LABEL_TAC "finite") THENL
   [USE_THEN "graph" MP_TAC THEN
    REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `CARD(V:A->bool) <= 2` THENL
   [USE_THEN "nonempty" MP_TAC THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY] THEN
    DISCH_THEN(X_CHOOSE_THEN `v:A` (LABEL_TAC "vertex")) THEN
    EXISTS_TAC `v:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`; `v:A`]
     GRAPH_DEGREE_LE_CARD) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `3 <= CARD(V:A->bool)` (LABEL_TAC "large") THENL
   [ASM_ARITH_TAC;
    ALL_TAC] THEN
  ASM_CASES_TAC `?v:A. v IN V /\ graph_degree E v <= 5` THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `CARD(V:A->bool) * 6 <= nsum V (graph_degree E)`
  (LABEL_TAC "degree_lower") THENL
   [SUBGOAL_THEN
     `CARD(V:A->bool) * 6 = nsum V (\v:A. 6)`
     SUBST1_TAC THENL
     [ASM_SIMP_TAC[NSUM_CONST];
      ALL_TAC] THEN
    MATCH_MP_TAC NSUM_LE THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `v:A` THEN DISCH_THEN(LABEL_TAC "vertex") THEN
    SUBGOAL_THEN `~(graph_degree E (v:A) <= 5)` MP_TAC THENL
     [ASM_MESON_TAC[];
      ARITH_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`]
    FINITE_SIMPLE_GRAPH_HANDSHAKING) THEN
  MP_TAC(ISPECL [`V:A->bool`; `E:(A->bool)->bool`]
    PLANAR_GRAPH_EDGE_BOUND) THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let EULER_PLANAR_GRAPH_LOW_DEGREE = prove
 (`!V E.
        euler_planar_graph (V:A->bool) E /\ ~(V = {})
        ==> ?v. v IN V /\ graph_degree E v <= 5`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
            PLANAR_GRAPH_LOW_DEGREE]);;

let STRAIGHT_LINE_PLANAR_GRAPH_LOW_DEGREE = prove
 (`!V E.
        straight_line_planar_graph (V:A->bool) E /\ ~(V = {})
        ==> ?v. v IN V /\ graph_degree E v <= 5`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR;
            EULER_PLANAR_GRAPH_LOW_DEGREE]);;

let graph_degenerate = new_definition
 `graph_degenerate k (V:A->bool) (E:(A->bool)->bool) <=>
        !W. W SUBSET V /\ ~(W = {})
            ==> ?v. v IN W /\
                    graph_degree (induced_subgraph_edges E W) v <= k`;;

let GRAPH_DEGENERATE_MONO = prove
 (`!k l V E.
        graph_degenerate k (V:A->bool) E /\ k <= l
        ==> graph_degenerate l V E`,
  REWRITE_TAC[graph_degenerate] THEN MESON_TAC[LE_TRANS]);;

let PLANAR_GRAPH_5_DEGENERATE = prove
 (`!V E.
        planar_graph (V:A->bool) E
        ==> graph_degenerate 5 V E`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "planar") THEN
  REWRITE_TAC[graph_degenerate] THEN
  X_GEN_TAC `W:A->bool` THEN INTRO_TAC "subset nonempty" THEN
  MATCH_MP_TAC(ISPECL
   [`W:A->bool`; `induced_subgraph_edges E W:(A->bool)->bool`]
   PLANAR_GRAPH_LOW_DEGREE) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `W:A->bool`]
   PLANAR_GRAPH_INDUCED_SUBGRAPH) THEN
  ASM_REWRITE_TAC[]);;

let EULER_PLANAR_GRAPH_5_DEGENERATE = prove
 (`!V E.
        euler_planar_graph (V:A->bool) E
        ==> graph_degenerate 5 V E`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
            PLANAR_GRAPH_5_DEGENERATE]);;

let STRAIGHT_LINE_PLANAR_GRAPH_5_DEGENERATE = prove
 (`!V E.
        straight_line_planar_graph (V:A->bool) E
        ==> graph_degenerate 5 V E`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR;
            EULER_PLANAR_GRAPH_5_DEGENERATE]);;

(* ------------------------------------------------------------------------- *)
(* Relabelling invariance.                                                   *)
(* ------------------------------------------------------------------------- *)

let FINITE_SIMPLE_GRAPH_IMAGE_INJ = prove
 (`!f:A->B. !V E.
        INJ f V (:B) /\
        finite_simple_graph V E
        ==> finite_simple_graph
             (IMAGE f V) (IMAGE (IMAGE f) E)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective graph" THEN
  USE_THEN "graph" MP_TAC THEN
  REWRITE_TAC[finite_simple_graph] THEN
  INTRO_TAC "finite_vertices finite_edges edge" THEN
  REWRITE_TAC[finite_simple_graph] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_IMAGE THEN
    USE_THEN "finite_vertices" ACCEPT_TAC;
    MATCH_MP_TAC FINITE_IMAGE THEN
    USE_THEN "finite_edges" ACCEPT_TAC;
    X_GEN_TAC `d:B->bool` THEN
    REWRITE_TAC[IN_IMAGE] THEN
    INTRO_TAC "@e. edge_image old_edge" THEN
    USE_THEN "edge_image" SUBST1_TAC THEN
    SUBGOAL_THEN `(e:A->bool) SUBSET V /\ e HAS_SIZE 2`
    (CONJUNCTS_THEN2 (LABEL_TAC "edge_subset") (LABEL_TAC "edge_size")) THENL
     [USE_THEN "edge" MATCH_MP_TAC THEN
      USE_THEN "old_edge" ACCEPT_TAC;
      CONJ_TAC THENL
       [MATCH_MP_TAC IMAGE_SUBSET THEN
        USE_THEN "edge_subset" ACCEPT_TAC;
        MATCH_MP_TAC HAS_SIZE_IMAGE_INJ THEN
        CONJ_TAC THENL
         [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
          INTRO_TAC "x_edge y_edge same" THEN
          USE_THEN "injective" MP_TAC THEN
          REWRITE_TAC[INJ; IN_UNIV] THEN
          ASM_MESON_TAC[SUBSET];
          USE_THEN "edge_size" ACCEPT_TAC]]]]);;

let RECURSIVE_PLANAR_GRAPH_IMAGE = prove
 (`!f:A->B. !V E.
        INJ f V (:B) /\
        recursive_planar_graph V E
        ==> recursive_planar_graph
             (IMAGE f V) (IMAGE (IMAGE f) E)`,
  REPEAT GEN_TAC THEN INTRO_TAC "injective recursive" THEN
  USE_THEN "recursive" MP_TAC THEN
  REWRITE_TAC[recursive_planar_graph] THEN
  INTRO_TAC "graph certificate" THEN
  REWRITE_TAC[recursive_planar_graph] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC FINITE_SIMPLE_GRAPH_IMAGE_INJ THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "certificate"
   (DISJ_CASES_THEN2 (LABEL_TAC "small") (LABEL_TAC "extension")) THENL
   [DISJ1_TAC THEN
    SUBGOAL_THEN `CARD(IMAGE (f:A->B) V) = CARD(V:A->bool)`
    (fun th -> ASM_REWRITE_TAC[th]) THEN
    MATCH_MP_TAC CARD_IMAGE_INJ THEN
    CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN
      INTRO_TAC "x_vertex y_vertex same" THEN
      USE_THEN "injective" MP_TAC THEN
      REWRITE_TAC[INJ; IN_UNIV] THEN ASM_MESON_TAC[];
      USE_THEN "graph" MP_TAC THEN
      REWRITE_TAC[finite_simple_graph] THEN MESON_TAC[]];
    DISJ2_TAC THEN
    USE_THEN "extension"
     (X_CHOOSE_THEN `E':(A->bool)->bool`
      (X_CHOOSE_THEN `q:num->A`
       (CONJUNCTS_THEN2 (LABEL_TAC "subset")
        (LABEL_TAC "triangulation")))) THEN
    MAP_EVERY EXISTS_TAC
     [`IMAGE (IMAGE (f:A->B)) E':(B->bool)->bool`;
      `(f:A->B) o (q:num->A)`] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC IMAGE_SUBSET THEN
      USE_THEN "subset" ACCEPT_TAC;
      MATCH_MP_TAC(ISPECL
       [`V:A->bool`; `E':(A->bool)->bool`; `q:num->A`; `3`;
        `f:A->B`]
       RECURSIVE_TRIANGULATED_DISK_IMAGE) THEN
      ASM_REWRITE_TAC[INJ; IN_UNIV]]]);;

let PLANAR_GRAPH_IMAGE = prove
 (`!f:A->B. !V E.
        INJ f V (:B) /\
        planar_graph V E
        ==> planar_graph
             (IMAGE f V) (IMAGE (IMAGE f) E)`,
  REWRITE_TAC[GSYM RECURSIVE_PLANAR_GRAPH_EQ_PLANAR_GRAPH] THEN
  MESON_TAC[RECURSIVE_PLANAR_GRAPH_IMAGE]);;

let STRAIGHT_LINE_PLANAR_GRAPH_IMAGE = prove
 (`!f:A->B. !V E.
        INJ f V (:B) /\
        straight_line_planar_graph V E
        ==> straight_line_planar_graph
             (IMAGE f V) (IMAGE (IMAGE f) E)`,
  REWRITE_TAC[GSYM RECURSIVE_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR] THEN
  MESON_TAC[RECURSIVE_PLANAR_GRAPH_IMAGE]);;

let EULER_PLANAR_GRAPH_IMAGE = prove
 (`!f:A->B. !V E.
        INJ f V (:B) /\
        euler_planar_graph V E
        ==> euler_planar_graph
             (IMAGE f V) (IMAGE (IMAGE f) E)`,
  REWRITE_TAC[EULER_PLANAR_GRAPH_EQ_RECURSIVE_PLANAR_GRAPH] THEN
  MESON_TAC[RECURSIVE_PLANAR_GRAPH_IMAGE]);;

let RECURSIVE_PLANAR_GRAPH_IMAGE_EQ = prove
 (`!f:A->B. !g:B->A. !V E.
        (!x. g(f x) = x) /\
        (!y. f(g y) = y)
        ==> (recursive_planar_graph
              (IMAGE f V) (IMAGE (IMAGE f) E) <=>
             recursive_planar_graph V E)`,
  REPEAT GEN_TAC THEN INTRO_TAC "left_inverse right_inverse" THEN
  SUBGOAL_THEN `!x y:A. (f:A->B) x = f y ==> x = y`
  (LABEL_TAC "f_injective") THENL
   [ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!x y:B. (g:B->A) x = g y ==> x = y`
  (LABEL_TAC "g_injective") THENL
   [ASM_MESON_TAC[];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "image_recursive") THEN
    SUBGOAL_THEN
     `recursive_planar_graph
       (IMAGE (g:B->A) (IMAGE (f:A->B) V))
       (IMAGE (IMAGE g) (IMAGE (IMAGE f) E))`
    (LABEL_TAC "renamed_back") THENL
     [MATCH_MP_TAC(ISPECL
       [`g:B->A`; `IMAGE (f:A->B) V:B->bool`;
        `IMAGE (IMAGE (f:A->B)) E:(B->bool)->bool`]
       RECURSIVE_PLANAR_GRAPH_IMAGE) THEN
      ASM_REWRITE_TAC[INJ; IN_UNIV] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!s:A->bool. IMAGE (g:B->A) (IMAGE (f:A->B) s) = s`
    (LABEL_TAC "set_inverse") THENL
     [MATCH_MP_TAC IMAGE_IMAGE_LEFT_INVERSE THEN
      USE_THEN "left_inverse" ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!S:(A->bool)->bool.
        IMAGE (IMAGE (g:B->A)) (IMAGE (IMAGE (f:A->B)) S) = S`
    (LABEL_TAC "edge_inverse") THENL
     [MATCH_MP_TAC IMAGE_IMAGE_LEFT_INVERSE THEN
      USE_THEN "set_inverse" ACCEPT_TAC;
      ALL_TAC] THEN
    ASM_MESON_TAC[];
    DISCH_THEN(LABEL_TAC "recursive") THEN
    MATCH_MP_TAC(ISPECL
     [`f:A->B`; `V:A->bool`; `E:(A->bool)->bool`]
     RECURSIVE_PLANAR_GRAPH_IMAGE) THEN
    ASM_REWRITE_TAC[INJ; IN_UNIV] THEN ASM_MESON_TAC[]]);;

let PLANAR_GRAPH_IMAGE_EQ = prove
 (`!f:A->B. !g:B->A. !V E.
        (!x. g(f x) = x) /\
        (!y. f(g y) = y)
        ==> (planar_graph
              (IMAGE f V) (IMAGE (IMAGE f) E) <=>
             planar_graph V E)`,
  REWRITE_TAC[GSYM RECURSIVE_PLANAR_GRAPH_EQ_PLANAR_GRAPH] THEN
  MESON_TAC[RECURSIVE_PLANAR_GRAPH_IMAGE_EQ]);;

let STRAIGHT_LINE_PLANAR_GRAPH_IMAGE_EQ = prove
 (`!f:A->B. !g:B->A. !V E.
        (!x. g(f x) = x) /\
        (!y. f(g y) = y)
        ==> (straight_line_planar_graph
              (IMAGE f V) (IMAGE (IMAGE f) E) <=>
             straight_line_planar_graph V E)`,
  REWRITE_TAC[GSYM RECURSIVE_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR] THEN
  MESON_TAC[RECURSIVE_PLANAR_GRAPH_IMAGE_EQ]);;

let EULER_PLANAR_GRAPH_IMAGE_EQ = prove
 (`!f:A->B. !g:B->A. !V E.
        (!x. g(f x) = x) /\
        (!y. f(g y) = y)
        ==> (euler_planar_graph
              (IMAGE f V) (IMAGE (IMAGE f) E) <=>
             euler_planar_graph V E)`,
  REWRITE_TAC[EULER_PLANAR_GRAPH_EQ_RECURSIVE_PLANAR_GRAPH] THEN
  MESON_TAC[RECURSIVE_PLANAR_GRAPH_IMAGE_EQ]);;

(* ------------------------------------------------------------------------- *)
(* Closure, components, and amalgamation.                                    *)
(* ------------------------------------------------------------------------- *)

let STRAIGHT_LINE_PLANAR_GRAPH_INDUCED_SUBGRAPH = prove
 (`!V E W.
        straight_line_planar_graph (V:A->bool) E /\ W SUBSET V
        ==> straight_line_planar_graph W (induced_subgraph_edges E W)`,
  MESON_TAC[PLANAR_GRAPH_INDUCED_SUBGRAPH;
            EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
            EULER_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR]);;

let STRAIGHT_LINE_PLANAR_GRAPH_SUBGRAPH = prove
 (`!V E W F.
        straight_line_planar_graph (V:A->bool) E /\
        W SUBSET V /\
        F SUBSET induced_subgraph_edges E W
        ==> straight_line_planar_graph W F`,
  MESON_TAC[PLANAR_GRAPH_SUBGRAPH;
            EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
            EULER_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR]);;

let EULER_PLANAR_GRAPH_MINOR = prove
 (`!V E W D.
        euler_planar_graph (V:A->bool) E /\
        graph_minor V E W D
        ==> euler_planar_graph W D`,
  MESON_TAC[PLANAR_GRAPH_MINOR;
            EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH]);;

let STRAIGHT_LINE_PLANAR_GRAPH_MINOR = prove
 (`!V E W D.
        straight_line_planar_graph (V:A->bool) E /\
        graph_minor V E W D
        ==> straight_line_planar_graph W D`,
  MESON_TAC[PLANAR_GRAPH_MINOR;
            EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
            EULER_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR]);;

let PLANAR_GRAPH_DELETE_EDGE = prove
 (`!V E e.
        planar_graph (V:A->bool) E
        ==> planar_graph V (E DELETE e)`,
  MESON_TAC[PLANAR_GRAPH_SUBSET_EDGES; DELETE_SUBSET]);;

let EULER_PLANAR_GRAPH_DELETE_EDGE = prove
 (`!V E e.
        euler_planar_graph (V:A->bool) E
        ==> euler_planar_graph V (E DELETE e)`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
            PLANAR_GRAPH_DELETE_EDGE]);;

let STRAIGHT_LINE_PLANAR_GRAPH_DELETE_EDGE = prove
 (`!V E e.
        straight_line_planar_graph (V:A->bool) E
        ==> straight_line_planar_graph V (E DELETE e)`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
            EULER_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR;
            PLANAR_GRAPH_DELETE_EDGE]);;

let PLANAR_GRAPH_CONTRACT_EDGE = prove
 (`!V E u v:A.
        planar_graph V E /\ {u,v} IN E
        ==> planar_graph
             (V DELETE u) (graph_contract_edges V E u v)`,
  REPEAT GEN_TAC THEN INTRO_TAC "planar edge" THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`;
    `V DELETE (u:A)`; `graph_contract_edges V E u v:(A->bool)->bool`]
   PLANAR_GRAPH_MINOR) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
   [`V:A->bool`; `E:(A->bool)->bool`; `V:A->bool`;
    `E:(A->bool)->bool`; `u:A`; `v:A`]
   GRAPH_MINOR_CONTRACT) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC GRAPH_MINOR_REFL THEN
  USE_THEN "planar" MP_TAC THEN
  REWRITE_TAC[planar_graph] THEN MESON_TAC[]);;

let EULER_PLANAR_GRAPH_CONTRACT_EDGE = prove
 (`!V E u v:A.
        euler_planar_graph V E /\ {u,v} IN E
        ==> euler_planar_graph
             (V DELETE u) (graph_contract_edges V E u v)`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
            PLANAR_GRAPH_CONTRACT_EDGE]);;

let STRAIGHT_LINE_PLANAR_GRAPH_CONTRACT_EDGE = prove
 (`!V E u v:A.
        straight_line_planar_graph V E /\ {u,v} IN E
        ==> straight_line_planar_graph
             (V DELETE u) (graph_contract_edges V E u v)`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
            EULER_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR;
            PLANAR_GRAPH_CONTRACT_EDGE]);;

let EULER_PLANAR_GRAPH_COMPONENTWISE_EQ = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        euler_planar_graph V E <=>
        finite_simple_graph V E /\
        (!u. u IN V
             ==> euler_planar_graph
                  (graph_component E u) (graph_component_edges E u))`,
  REPEAT GEN_TAC THEN EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "euler") THEN
    SUBGOAL_THEN `finite_simple_graph (V:A->bool) E`
    (LABEL_TAC "graph") THENL
     [MATCH_MP_TAC EULER_PLANAR_GRAPH_FINITE_SIMPLE THEN
      USE_THEN "euler" ACCEPT_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN DISCH_THEN(LABEL_TAC "vertex") THEN
    MATCH_MP_TAC(ISPECL
     [`V:A->bool`; `E:(A->bool)->bool`;
      `graph_component E (u:A):A->bool`;
      `graph_component_edges E u:(A->bool)->bool`]
     EULER_PLANAR_GRAPH_SUBGRAPH) THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "euler" ACCEPT_TAC;
      MATCH_MP_TAC GRAPH_COMPONENT_SUBSET THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[SUBSET; IN_GRAPH_COMPONENT_EDGES;
                  IN_INDUCED_SUBGRAPH_EDGES] THEN MESON_TAC[]];
    MATCH_ACCEPT_TAC EULER_PLANAR_GRAPH_COMPONENTWISE]);;

let PLANAR_GRAPH_COMPONENTWISE_EQ = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        planar_graph V E <=>
        finite_simple_graph V E /\
        (!u. u IN V
             ==> planar_graph
                  (graph_component E u) (graph_component_edges E u))`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
            EULER_PLANAR_GRAPH_COMPONENTWISE_EQ]);;

let STRAIGHT_LINE_PLANAR_GRAPH_COMPONENTWISE_EQ = prove
 (`!V:A->bool. !E:(A->bool)->bool.
        straight_line_planar_graph V E <=>
        finite_simple_graph V E /\
        (!u. u IN V
             ==> straight_line_planar_graph
                  (graph_component E u) (graph_component_edges E u))`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR;
            EULER_PLANAR_GRAPH_COMPONENTWISE_EQ]);;

let PLANAR_GRAPH_SINGLETON_AMALGAMATION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u:A.
        planar_graph V1 E1 /\
        connected_graph V1 E1 /\
        planar_graph V2 E2 /\
        connected_graph V2 E2 /\
        V1 INTER V2 = {u}
        ==> planar_graph (V1 UNION V2) (E1 UNION E2)`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
            EULER_PLANAR_GRAPH_SINGLETON_AMALGAMATION]);;

let STRAIGHT_LINE_PLANAR_GRAPH_SINGLETON_AMALGAMATION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u:A.
        straight_line_planar_graph V1 E1 /\
        connected_graph V1 E1 /\
        straight_line_planar_graph V2 E2 /\
        connected_graph V2 E2 /\
        V1 INTER V2 = {u}
        ==> straight_line_planar_graph (V1 UNION V2) (E1 UNION E2)`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR;
            EULER_PLANAR_GRAPH_SINGLETON_AMALGAMATION]);;

let PLANAR_GRAPH_EDGE_AMALGAMATION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u v:A.
        planar_graph V1 E1 /\
        connected_graph V1 E1 /\
        planar_graph V2 E2 /\
        connected_graph V2 E2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2 /\
        (?w:A. {u,w} IN E2 /\ ~(w = v)) /\
        (?z:A. {v,z} IN E1 /\ ~(z = u))
        ==> planar_graph (V1 UNION V2) (E1 UNION E2)`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_PLANAR_GRAPH;
            EULER_PLANAR_GRAPH_EDGE_AMALGAMATION]);;

let STRAIGHT_LINE_PLANAR_GRAPH_EDGE_AMALGAMATION = prove
 (`!V1 V2:A->bool. !E1 E2:(A->bool)->bool. !u v:A.
        straight_line_planar_graph V1 E1 /\
        connected_graph V1 E1 /\
        straight_line_planar_graph V2 E2 /\
        connected_graph V2 E2 /\
        V1 INTER V2 = {u,v} /\
        {u,v} IN E1 /\
        {u,v} IN E2 /\
        (?w:A. {u,w} IN E2 /\ ~(w = v)) /\
        (?z:A. {v,z} IN E1 /\ ~(z = u))
        ==> straight_line_planar_graph (V1 UNION V2) (E1 UNION E2)`,
  MESON_TAC[EULER_PLANAR_GRAPH_EQ_STRAIGHT_LINE_PLANAR;
            EULER_PLANAR_GRAPH_EDGE_AMALGAMATION]);;
